DB[2]={id=2,zoneId=331,name=[[Sharptalon's Claw]],name_loc=[[La garfa de Garfafilada]],level=30,minLevel=20,giverType=[[NPC]],ender=[[Senani Thunderheart]],ender_loc=[[Senani Corazón Atronador]],enderType=[[NPC]],enderId=12696,prevId=6383,nextId=247,exGroup=-2,poiX=2148,poiY=-2816,wowhead=[[https://www.wowhead.com/wotlk/quest=2]],image=[[assets/images/quests/placeholder.png]],desc=[[The mighty hippogryph Sharptalon has been slain, with the claw of the felled beast serving as a testament to your victory.  Senani Thunderheart at the Splintertree Post will no doubt be interested in seeing this trophy as proof of your deeds.]],logDesc=[[Bring Sharptalon's Claw to Senani Thunderheart at Splintertree Post, Ashenvale.]]}
DB[5]={id=5,zoneId=10,name=[[Jitters' Growling Gut]],name_loc=[[La hambruna de Alterio]],level=20,minLevel=17,giver=[[Jitters]],giver_loc=[[Alterio]],giverType=[[NPC]],giverId=288,ender=[[Chef Grual]],enderType=[[NPC]],enderId=272,prevId=163,rewardNextId=93,poiX=-10499,poiY=-1158,wowhead=[[https://www.wowhead.com/wotlk/quest=5]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been stuck hiding in this ghost town for weeks, and I haven't eaten anything but grubs and weeds!  I need some decent food, and I'm willing to trade well for it. Bring me a feast and I'll pay you handsomely. I heard Chef Grual at the Scarlet Raven Tavern in Darkshire makes very good Dusky Crab Cakes...]],logDesc=[[Speak with Chef Grual.]]}
DB[6]={id=6,zoneId=9,name=[[Bounty on Garrick Padfoot]],name_loc=[[La recompensa por Garrick Piesuaves]],level=5,minLevel=2,giver=[[Deputy Willem]],giver_loc=[[Ayudante de alguacil Willem]],giverType=[[NPC]],giverId=823,ender=[[Deputy Willem]],ender_loc=[[Ayudante de alguacil Willem]],enderType=[[NPC]],enderId=823,prevId=18,poiX=-9056,poiY=-461,wowhead=[[https://www.wowhead.com/wotlk/quest=6]],image=[[assets/images/quests/placeholder.png]],desc=[[Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge.  Bring me the villain's head, and earn his bounty! But be wary, $N.  Garrick has gathered a gang of thugs around him.  He will not be an easy man to reach.]],logDesc=[[Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.]],choiceRewards={{id=6076,qty=1},{id=60,qty=1},{id=3070,qty=1}}}
DB[7]={id=7,zoneId=9,name=[[Kobold Camp Cleanup]],name_loc=[[La Limpieza del Campamento Kóbold]],level=2,minLevel=1,giver=[[Marshal McBride]],giver_loc=[[Alguacil McBride]],giverType=[[NPC]],giverId=197,ender=[[Marshal McBride]],ender_loc=[[Alguacil McBride]],enderType=[[NPC]],enderId=197,prevId=783,poiX=-8797,poiY=-259,wowhead=[[https://www.wowhead.com/wotlk/quest=7]],image=[[assets/images/quests/placeholder.png]],desc=[[Your first task is one of cleansing, $N.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.]],logDesc=[[Kill 8 Kobold Vermin, then return to Marshal McBride.]]}
DB[8]={id=8,zoneId=154,name=[[A Rogue's Deal]],name_loc=[[Un trato de pícaro]],level=5,minLevel=1,giver=[[Calvin Montague]],giver_loc=[[Calvin Montesco]],giverType=[[NPC]],giverId=6784,ender=[[Innkeeper Renee]],ender_loc=[[Tabernera Renee]],enderType=[[NPC]],enderId=5688,poiX=2270,poiY=245,wowhead=[[https://www.wowhead.com/wotlk/quest=8]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey, mate! Do a favor for a young man who's been fighting more than his fair share of mindless zombies and spiders? I got this here letter that needs to go to Brill... to an innkeeper named Renee something-or-other. Don't really matter none what her last name is. Anyway, it's a nice cozy little place full of victims of the plague trying to make their way in the world. And it be a great spot for you to rest too if the need arises. You should check it out... you do and I'll pay you well.]],logDesc=[[Deliver the Nondescript Letter to Innkeeper Renee in Tirisfal Glades.]],choiceRewards={{id=4604,qty=5},{id=159,qty=5}}}
DB[9]={id=9,zoneId=40,name=[[The Killing Fields]],name_loc=[[Campos de la muerte]],level=15,minLevel=8,giver=[[Farmer Saldean]],giver_loc=[[Granjero Saldean]],giverType=[[NPC]],giverId=233,ender=[[Farmer Saldean]],ender_loc=[[Granjero Saldean]],enderType=[[NPC]],enderId=233,poiX=-9934,poiY=1166,wowhead=[[https://www.wowhead.com/wotlk/quest=9]],image=[[assets/images/quests/placeholder.png]],desc=[[Look at what has happened to this place!  These lands were once occupied by good farm folk.  But the damned thieves have driven them all off.  Not me, though!  But it seems some Harvest Watchers have taken over the fields. If you're up for the work, I'd like you to go out and kill twenty of them.  Come back when you're done for your pay.  If you finish up with the ones in my field, clear them from the neighboring fields as well.]],logDesc=[[Farmer Saldean wants you to kill 20 Harvest Watchers.]],choiceRewards={{id=3578,qty=1},{id=1561,qty=1}}}
DB[10]={id=10,zoneId=440,name=[[The Scrimshank Redemption]],name_loc=[[La redención de Patagolpe]],level=48,minLevel=39,giver=[[Senior Surveyor Fizzledowser]],giver_loc=[[Perito jefe Picoflojo]],giverType=[[NPC]],giverId=7724,ender=[[Senior Surveyor Fizzledowser]],ender_loc=[[Perito jefe Picoflojo]],enderType=[[NPC]],enderId=7724,prevId=82,rewardNextId=110,poiX=-9149,poiY=-4080,wowhead=[[https://www.wowhead.com/wotlk/quest=10]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, this is just terrible!  I sent out my top assistant, Junior Surveyor Scrimshank, into the desert southeast of here.  That's an area we call the Gaping Chasm.  Well, he's gone missing, and his last report had more of those weird bugs where he was.  Could it be that they've infested two major regions of the desert now? I need you to head into the Gaping Chasm and look for Scrimshank, please!  That... or at least find his surveying equipment.  I fear that may be all that is left of the poor sod.]],logDesc=[[Discover the fate of Junior Surveyor Scrimshank, and bring either him or his surveying equipment to Senior Surveyor Fizzledowser in Gadgetzan.]]}
DB[11]={id=11,zoneId=12,name=[[Riverpaw Gnoll Bounty]],name_loc=[[Recompensas por los gnolls Zarparrío]],level=10,minLevel=6,giver=[[Deputy Rainer]],giver_loc=[[Ayudante de alguacil Rainer]],giverType=[[NPC]],giverId=963,ender=[[Deputy Rainer]],ender_loc=[[Ayudante de alguacil Rainer]],enderType=[[NPC]],enderId=963,prevId=239,poiX=-9983,poiY=549,wowhead=[[https://www.wowhead.com/wotlk/quest=11]],image=[[assets/images/quests/placeholder.png]],desc=[[Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest.  A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder.  Another group has infested the areas near Stone Cairn Lake to the east. The Stormwind Army will commend whomever helps kill them.  Bring me their painted gnoll armbands as proof of your deed.]],logDesc=[[Bring 8 Painted Gnoll Armbands to Deputy Rainer at the Barracks.]],choiceRewards={{id=2249,qty=1},{id=2238,qty=1}}}
DB[12]={id=12,zoneId=40,name=[[The People's Militia]],name_loc=[[La Milicia Popular]],level=12,minLevel=9,giver=[[Gryan Stoutmantle]],giver_loc=[[Gryan Mantorrecio]],giverType=[[NPC]],giverId=234,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,rewardNextId=13,poiX=-10179,poiY=1878,wowhead=[[https://www.wowhead.com/wotlk/quest=12]],image=[[assets/images/quests/placeholder.png]],desc=[[The People's Militia has but one goal:  To defend the lands of Westfall and return peace to our surroundings.  Unfortunately, the price of peace is often blood.  One of my scouts has brought word of a band of Defias Trappers wreaking havoc nearby.  I have reports of Defias Trapper sightings near the Jangolode Mine to the Northwest as well as at the Molsen Farm and Furlbrow's Pumpkin Farm. If you seek to join our ranks, slay 15 Defias Trappers and 15 Defias Smugglers then return to me.]],logDesc=[[Gryan Stoutmantle wants you to kill 15 Defias Trappers and 15 Defias Smugglers then return to him on Sentinel Hill.]]}
DB[13]={id=13,zoneId=40,name=[[The People's Militia]],name_loc=[[La Milicia Popular]],level=14,minLevel=9,giver=[[Gryan Stoutmantle]],giver_loc=[[Gryan Mantorrecio]],giverType=[[NPC]],giverId=234,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,prevId=12,rewardNextId=14,poiX=-10727,poiY=1659,wowhead=[[https://www.wowhead.com/wotlk/quest=13]],image=[[assets/images/quests/placeholder.png]],desc=[[A band of vicious Defias Pillagers has been seen plundering the Gold Coast Quarry, Moonbrook and the Alexston Farmstead.  The People's Militia will not stand for such behavior.  Dispatch immediately, $n, and make the Light's presence known in Westfall. The Gold Coast Quarry is near the shore, to the West of the tower.  As the next step of your training, I want you to kill 15 of those foul Defias Pillagers and 15 Defias Looters.]],logDesc=[[Gryan Stoutmantle wants you to kill 15 Defias Pillagers and 15 Defias Looters and return to him on Sentinel Hill.]]}
DB[14]={id=14,zoneId=40,name=[[The People's Militia]],name_loc=[[La Milicia Popular]],level=17,minLevel=9,giver=[[Gryan Stoutmantle]],giver_loc=[[Gryan Mantorrecio]],giverType=[[NPC]],giverId=234,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,prevId=13,poiX=-11258,poiY=1506,wowhead=[[https://www.wowhead.com/wotlk/quest=14]],image=[[assets/images/quests/placeholder.png]],desc=[[Some Defias have eluded us.  My most trusted scout reports that these Defias have been looting and pillaging the countryside, all the way into Southern Westfall.  We believe they are hiding out in the Dagger Hills, plotting their next move.   Slay the wretches in the name of The People's Militia.]],logDesc=[[Gryan Stoutmantle wants you to kill 15 Defias Highwaymen, 5 Defias Pathstalkers and 5 Defias Knuckledusters then return to him on Sentinel Hill.]],choiceRewards={{id=1566,qty=1},{id=1480,qty=1},{id=12296,qty=1}}}
DB[15]={id=15,zoneId=9,name=[[Investigate Echo Ridge]],name_loc=[[Investigar la Mina del Eco]],level=3,minLevel=1,giver=[[Marshal McBride]],giver_loc=[[Alguacil McBride]],giverType=[[NPC]],giverId=197,ender=[[Marshal McBride]],ender_loc=[[Alguacil McBride]],enderType=[[NPC]],enderId=197,prevId=7,rewardNextId=21,poiX=-8782,poiY=-274,wowhead=[[https://www.wowhead.com/wotlk/quest=15]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, my scouts tell me that the kobold infestation is larger than we had thought.  A group of kobold workers has camped near the Echo Ridge Mine to the north. Go to the mine and remove them.  We know there are at least 8.  Kill them, see if there are more, then report back to me.]],logDesc=[[Kill 8 Kobold Workers, then report back to Marshal McBride.]]}
DB[16]={id=16,zoneId=12,name=[[Give Gerard a Drink]],name_loc=[[Dale de beber a Gerard]],level=1,minLevel=1,giver=[[Gerard Tiller]],giverType=[[NPC]],giverId=255,ender=[[Gerard Tiller]],enderType=[[NPC]],enderId=255,poiX=-9983,poiY=549,wowhead=[[https://www.wowhead.com/wotlk/quest=16]],image=[[assets/images/quests/placeholder.png]],rewards={{id=4536,qty=1}}}
DB[17]={id=17,zoneId=1517,name=[[Uldaman Reagent Run]],name_loc=[[Componentes de Uldaman]],level=42,minLevel=38,giver=[[Ghak Healtouch]],giver_loc=[[Ghak Sanadón]],giverType=[[NPC]],giverId=1470,ender=[[Ghak Healtouch]],ender_loc=[[Ghak Sanadón]],enderType=[[NPC]],enderId=1470,prevId=2500,poiX=-6172,poiY=-3030,wowhead=[[https://www.wowhead.com/wotlk/quest=17]],image=[[assets/images/quests/placeholder.png]],desc=[[I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters at the Uldaman dig site and can be found in the early tunnels and deep within the less-explored areas.  I want to study their potential use in alchemy, and that's where you come in. Find the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled. Do this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!]],logDesc=[[Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar.]],rewards={{id=9030,qty=5}}}
DB[18]={id=18,zoneId=9,name=[[Brotherhood of Thieves]],name_loc=[[Hermandad de ladrones]],level=4,minLevel=2,giver=[[Deputy Willem]],giver_loc=[[Ayudante de alguacil Willem]],giverType=[[NPC]],giverId=823,ender=[[Deputy Willem]],ender_loc=[[Ayudante de alguacil Willem]],enderType=[[NPC]],enderId=823,prevId=783,poiX=-9052,poiY=-458,wowhead=[[https://www.wowhead.com/wotlk/quest=18]],image=[[assets/images/quests/placeholder.png]],desc=[[Recently, a new group of thieves has been hanging around Northshire.  They call themselves the Defias Brotherhood, and have been seen across the river to the east. I don't know what they're up to, but I'm sure it's not good!  Bring me the bandanas they wear, and I'll reward you with a weapon.]],logDesc=[[Bring 8 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey.]],choiceRewards={{id=2224,qty=1},{id=5580,qty=1},{id=1161,qty=1},{id=5579,qty=1},{id=1159,qty=1}}}
DB[19]={id=19,zoneId=44,name=[[Tharil'zun]],name_loc=[[Tharil'zun]],level=25,minLevel=18,giver=[[Marshal Marris]],giver_loc=[[Alguacil Marris]],giverType=[[NPC]],giverId=382,ender=[[Marshal Marris]],ender_loc=[[Alguacil Marris]],enderType=[[NPC]],enderId=382,prevId=20,poiX=-9435,poiY=-3079,wowhead=[[https://www.wowhead.com/wotlk/quest=19]],image=[[assets/images/quests/placeholder.png]],desc=[[Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep.  The leader of the Outrunners is an orc named Tharil'zun--we want this orc.  Bring me the head of Tharil'zun!]],logDesc=[[Bring Tharil'zun's Head to Marshal Marris in Redridge.]],choiceRewards={{id=1276,qty=1},{id=6093,qty=1}}}
DB[20]={id=20,zoneId=44,name=[[Blackrock Menace]],name_loc=[[La amenaza de los Roca Negra]],level=21,minLevel=18,giver=[[Marshal Marris]],giver_loc=[[Alguacil Marris]],giverType=[[NPC]],giverId=382,ender=[[Marshal Marris]],ender_loc=[[Alguacil Marris]],enderType=[[NPC]],enderId=382,rewardNextId=19,poiX=-9816,poiY=-3260,wowhead=[[https://www.wowhead.com/wotlk/quest=20]],image=[[assets/images/quests/placeholder.png]],desc=[[The Blackrock orcs have travelled from the Burning Steppes and claimed Stonewatch Keep to the north.  From there they maraud the areas north of Lakeshire and keep its citizens in town, penned like cattle. Help rid Lakeshire of this menace.  Kill these Blackrock orcs and bring me ten of their Battleworn Axes as proof. And although Blackrocks threaten us from the north, we've received reports of more in the southeastern pocket of Redridge.  If you find any there, then they too should be hunted.]],logDesc=[[Bring 10 Battleworn Axes to Marshal Marris in Lakeshire.]]}
DB[21]={id=21,zoneId=9,name=[[Skirmish at Echo Ridge]],name_loc=[[Escaramuza en la Mina del Eco]],level=5,minLevel=1,giver=[[Marshal McBride]],giver_loc=[[Alguacil McBride]],giverType=[[NPC]],giverId=197,ender=[[Marshal McBride]],ender_loc=[[Alguacil McBride]],enderType=[[NPC]],enderId=197,prevId=15,poiX=-8561,poiY=-218,wowhead=[[https://www.wowhead.com/wotlk/quest=21]],image=[[assets/images/quests/placeholder.png]],desc=[[Your previous investigations are proof that the Echo Ridge Mine needs purging.  Return to the mine and help clear it of kobolds. Waste no time, $N.  The longer the kobolds are left unmolested in the mine, the deeper a foothold they gain in Northshire.]],logDesc=[[Kill 8 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.]],choiceRewards={{id=2186,qty=1},{id=2691,qty=1},{id=11192,qty=1}}}
DB[22]={id=22,zoneId=40,name=[[Goretusk Liver Pie]],name_loc=[[Pastel de hígado de dentosangre]],level=12,minLevel=9,giver=[[Salma Saldean]],giverType=[[NPC]],giverId=235,ender=[[Salma Saldean]],enderType=[[NPC]],enderId=235,poiX=-10448,poiY=872,wowhead=[[https://www.wowhead.com/wotlk/quest=22]],image=[[assets/images/quests/placeholder.png]],desc=[[The onions are peeled.  The garlic is minced.  The rosemary is crushed.  The crust has been baked.  The dill weed is chopped.  The gravy is simmering.  Now all I need for my famous meat pie are 8 Goretusk Livers!]],logDesc=[[Salma Saldean needs 8 Goretusk livers to make a Goretusk Liver Pie.]],rewards={{id=724,qty=3},{id=2697,qty=1}}}
DB[23]={id=23,zoneId=331,name=[[Ursangous's Paw]],name_loc=[[La pata de Ursangous]],level=24,minLevel=20,giverType=[[NPC]],ender=[[Senani Thunderheart]],ender_loc=[[Senani Corazón Atronador]],enderType=[[NPC]],enderId=12696,prevId=6383,nextId=247,exGroup=-2,poiX=2026,poiY=-824,wowhead=[[https://www.wowhead.com/wotlk/quest=23]],image=[[assets/images/quests/placeholder.png]],desc=[[The paw of the mighty bear Ursangous is your trophy for this part of the Ashenvale Hunt.  On the paw is a small quarter-crescent emblem; the significance of the emblem remains a mystery. The paw should be brought to Senani Thunderheart in Splintertree Post to prove that you have bested the mighty creature and completed this portion of the hunt.]],logDesc=[[Bring Ursangous's Paw to Senani Thunderheart at Splintertree Post, Ashenvale.]]}
DB[24]={id=24,zoneId=331,name=[[Shadumbra's Head]],name_loc=[[La cabeza de Shadumbra]],level=27,minLevel=20,giverType=[[NPC]],ender=[[Senani Thunderheart]],ender_loc=[[Senani Corazón Atronador]],enderType=[[NPC]],enderId=12696,prevId=6383,nextId=247,exGroup=-2,poiX=2759,poiY=-1901,wowhead=[[https://www.wowhead.com/wotlk/quest=24]],image=[[assets/images/quests/placeholder.png]],desc=[[The once swift Shadumbra now lies still as you claim victory over it.  The head of the slain nightsaber is a fitting trophy for this fight of the Ashenvale Hunt.  Senani Thunderheart at Splintertree Post will want to see such a trophy to award you credit for this part of the Ashenvale Hunt.]],logDesc=[[Bring Shadumbra's Head to Senani Thunderheart at Splintertree Post, Ashenvale.]]}
DB[25]={id=25,zoneId=331,name=[[Stonetalon Standstill]],name_loc=[[Paso del Espolón bloqueado]],level=25,minLevel=23,giver=[[Mastok Wrilehiss]],giver_loc=[[Mastok Bufido]],giverType=[[NPC]],giverId=12737,ender=[[Mastok Wrilehiss]],ender_loc=[[Mastok Bufido]],enderType=[[NPC]],enderId=12737,poiX=1916,poiY=-1315,wowhead=[[https://www.wowhead.com/wotlk/quest=25]],image=[[assets/images/quests/placeholder.png]],desc=[[If you want to be useful, then why don't you do something about the situation near Talondeep Path? The transports between Ashenvale and Stonetalon are at a standstill because of the lake coming alive and attacking anything that gets close... which means anyone on the path.  What'd be even more useful than just putting the hammer down on the water elementals there is someone scouting the gazebo on Mystral Lake - the one that has a solid view of the Alliance outpost there. You up for being useful?]],logDesc=[[Dispatch 12 Befouled Water Elementals at Mystral Lake, due east of the Talondeep Path and southwest of Splintertree Post. Scout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost. Return to Mastok Wrilehiss at Splintertree Post, Ashenvale.]]}
DB[26]={id=26,name=[[A Lesson to Learn]],name_loc=[[Una lección que aprender]],level=-1,minLevel=16,giver=[[Mathrengyl Bearwalker]],giver_loc=[[Mathrengyl Garroso]],giverType=[[NPC]],giverId=4217,ender=[[Dendrite Starblaze]],ender_loc=[[Dendrita Rafagaestelar]],enderType=[[NPC]],enderId=11802,rewardNextId=29,poiX=8020,poiY=-2679,wowhead=[[https://www.wowhead.com/wotlk/quest=26]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature. The time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.]],logDesc=[[Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.]]}
DB[27]={id=27,name=[[A Lesson to Learn]],name_loc=[[Una lección que aprender]],level=-1,minLevel=16,giver=[[Turak Runetotem]],giver_loc=[[Turak Tótem de Runa]],giverType=[[NPC]],giverId=3033,ender=[[Dendrite Starblaze]],ender_loc=[[Dendrita Rafagaestelar]],enderType=[[NPC]],enderId=11802,rewardNextId=28,poiX=8020,poiY=-2679,wowhead=[[https://www.wowhead.com/wotlk/quest=27]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature. The time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.]],logDesc=[[Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.]]}
DB[28]={id=28,name=[[Trial of the Lake]],name_loc=[[La prueba del lago]],level=-1,minLevel=16,giver=[[Dendrite Starblaze]],giver_loc=[[Dendrita Rafagaestelar]],giverType=[[NPC]],giverId=11802,ender=[[Tajarri]],enderType=[[NPC]],enderId=11799,prevId=27,rewardNextId=30,poiX=7708,poiY=-2733,wowhead=[[https://www.wowhead.com/wotlk/quest=28]],image=[[assets/images/quests/placeholder.png]],desc=[[For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens. You only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success. Good luck, $N.]],logDesc=[[Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble. You must speak with Tajarri at the shrine afterwards in order to complete the trial.]]}
DB[29]={id=29,name=[[Trial of the Lake]],name_loc=[[La prueba del lago]],level=-1,minLevel=16,giver=[[Dendrite Starblaze]],giver_loc=[[Dendrita Rafagaestelar]],giverType=[[NPC]],giverId=11802,ender=[[Tajarri]],enderType=[[NPC]],enderId=11799,prevId=26,rewardNextId=272,poiX=7708,poiY=-2733,wowhead=[[https://www.wowhead.com/wotlk/quest=29]],image=[[assets/images/quests/placeholder.png]],desc=[[For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens. You only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success. Good luck, $N.]],logDesc=[[Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble. You must speak with Tajarri at the shrine afterwards in order to complete the trial.]]}
DB[30]={id=30,name=[[Trial of the Sea Lion]],name_loc=[[La prueba del león marino]],level=-1,minLevel=16,giver=[[Tajarri]],giverType=[[NPC]],giverId=11799,ender=[[Dendrite Starblaze]],ender_loc=[[Dendrita Rafagaestelar]],enderType=[[NPC]],enderId=11802,prevId=28,rewardNextId=31,poiX=8020,poiY=-2679,wowhead=[[https://www.wowhead.com/wotlk/quest=30]],image=[[assets/images/quests/placeholder.png]],desc=[[For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form. Speak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.]],logDesc=[[Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located. Form the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this. Bring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.]]}
DB[31]={id=31,name=[[Aquatic Form]],name_loc=[[Forma acuática]],level=-1,minLevel=16,giver=[[Dendrite Starblaze]],giver_loc=[[Dendrita Rafagaestelar]],giverType=[[NPC]],giverId=11802,ender=[[Turak Runetotem]],ender_loc=[[Turak Tótem de Runa]],enderType=[[NPC]],enderId=3033,prevId=30,poiX=-1039,poiY=-282,wowhead=[[https://www.wowhead.com/wotlk/quest=31]],image=[[assets/images/quests/placeholder.png]],desc=[[You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect.  Go now back to your trainer, Turak Runetotem, in Thunder Bluff.  Show him your pendant and prove to him you are ready to learn what he has to teach you.  He will complete your training, allowing you to become one with the water. Goodbye, young druid.  We shall speak again.]],logDesc=[[Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion.]],rewards={{id=16608,qty=1}}}
DB[32]={id=32,zoneId=440,name=[[Rise of the Silithid]],name_loc=[[La sublevación de los silítidos]],level=48,minLevel=39,giver=[[Senior Surveyor Fizzledowser]],giver_loc=[[Perito jefe Picoflojo]],giverType=[[NPC]],giverId=7724,ender=[[Zilzibin Drumlore]],ender_loc=[[Zilzibin Tambor Sabio]],enderType=[[NPC]],enderId=7010,prevId=113,poiX=1837,poiY=-4470,wowhead=[[https://www.wowhead.com/wotlk/quest=32]],image=[[assets/images/quests/placeholder.png]],desc=[[Here's your report.  I urge you to take it to someone who might have working knowledge in this kind of thing. I know this troll scholar named Zilzibin Drumlore.  He's spent a lot of time studying life forms that are unique to the ecology of Azeroth; he's a historian to boot!  If you want someone to help figure out what exactly this threat is and how to stop it, give this report to him.  We're going to need all the help we can get. Zil lives in a house on the second tier of the Drag in Orgrimmar.]],logDesc=[[Take the report to Zilzibin Drumlore in Orgrimmar.]]}
DB[33]={id=33,zoneId=9,name=[[Wolves Across the Border]],name_loc=[[Los lobos cruzan la frontera]],level=2,minLevel=1,giver=[[Eagan Peltskinner]],giver_loc=[[Eagan Desollapelambres]],giverType=[[NPC]],giverId=196,ender=[[Eagan Peltskinner]],ender_loc=[[Eagan Desollapelambres]],enderType=[[NPC]],enderId=196,prevId=5261,poiX=-8837,poiY=-305,wowhead=[[https://www.wowhead.com/wotlk/quest=33]],image=[[assets/images/quests/placeholder.png]],desc=[[Whatever is affecting these wolves isn't going away. Each day that passes brings forth more sick wolves. It pains me to ask anyone to kill nature's beasts, but we must destroy the diseased young wolves before this little outbreak turns into an epidemic. Kill diseased young wolves in the valley and bring me their diseased wolf pelts as proof of your deed. ]],logDesc=[[Bring 8 Diseased Wolf Pelts to Eagan Peltskinner outside Northshire Abbey.]],choiceRewards={{id=80,qty=1},{id=6070,qty=1}}}
DB[34]={id=34,zoneId=44,name=[[An Unwelcome Guest]],name_loc=[[Una visita poco grata]],level=24,minLevel=18,giver=[[Martie Jainrose]],giverType=[[NPC]],giverId=342,ender=[[Martie Jainrose]],enderType=[[NPC]],enderId=342,poiX=-9289,poiY=-1919,wowhead=[[https://www.wowhead.com/wotlk/quest=34]],image=[[assets/images/quests/placeholder.png]],desc=[[Once again my garden was trampled and pillaged.  And I know the brute who is doing it.  It's that forsaken boar, the one Marshal Marris has taken to calling Bellygrub. I won't be able to re-plant the daffodils until next season now.  Ruined!  All ruined by that one menacing boar.  Put an end to that pest!  Show me his tusk and I'd be happy to reward you.  He seems to spend his time foraging in the field southwest of Lakeshire but occasionally he roams over here and into my garden.]],logDesc=[[Martie Jainrose of Lakeshire wants you to kill Bellygrub.  Bring her his tusk as proof.]],rewards={{id=2562,qty=1}}}
DB[35]={id=35,zoneId=12,name=[[Further Concerns]],name_loc=[[Más preocupaciones]],level=10,minLevel=7,giver=[[Marshal Dughan]],giver_loc=[[Alguacil Dughan]],giverType=[[NPC]],giverId=240,ender=[[Guard Thomas]],ender_loc=[[Guardia Thomas]],enderType=[[NPC]],enderId=261,prevId=40,rewardNextId=37,poiX=-9610,poiY=-1032,wowhead=[[https://www.wowhead.com/wotlk/quest=35]],image=[[assets/images/quests/placeholder.png]],desc=[[If you are concerned that the rumors of murlocs are true, then do this -- travel to the eastern Elwynn bridge and speak with Guard Thomas.  He has been stationed at the bridge for the past week and will know the state of the area. Bring me his report.]],logDesc=[[Marshal Dughan wants you to speak with Guard Thomas.]]}
DB[36]={id=36,zoneId=40,name=[[Westfall Stew]],name_loc=[[Estofado de los Páramos de Poniente]],level=10,minLevel=9,giver=[[Verna Furlbrow]],giver_loc=[[Verna Cejade]],giverType=[[NPC]],giverId=238,ender=[[Salma Saldean]],enderType=[[NPC]],enderId=235,poiX=-10112,poiY=1042,wowhead=[[https://www.wowhead.com/wotlk/quest=36]],image=[[assets/images/quests/placeholder.png]],desc=[[I never thought the day would come when I'd leave the farm.  But the fields are overrun with thieves and it's far too dangerous for us here now.  As soon as Farmer Furlbrow gets the wagon fixed, we'll be on our way.     Maybe you could do me a favor?  Let me scribble down my recipe for Westfall stew.  Please take it to Salma Saldean over on the farm yonder.  The Saldean's farm is just beyond the fork in the road.]],logDesc=[[Verna Furlbrow wants you to deliver her recipe for Westfall Stew to Salma Saldean.]]}
DB[37]={id=37,zoneId=12,name=[[Find the Lost Guards]],name_loc=[[Encuentra a los guardias perdidos]],level=10,minLevel=7,giver=[[Guard Thomas]],giver_loc=[[Guardia Thomas]],giverType=[[NPC]],giverId=261,ender=[[A half-eaten body]],ender_loc=[[Un cadáver medio comido]],enderType=[[GO]],enderId=55,prevId=35,rewardNextId=45,poiX=-9336,poiY=-986,wowhead=[[https://www.wowhead.com/wotlk/quest=37]],image=[[assets/images/quests/placeholder.png]],desc=[[A few days ago we sent two Guards, Rolf and Malakai, to investigate along the river, and they have not yet returned.  To complete my report, I must know what happened to those men. Travel north along the river and find the guards... or their remains.]],logDesc=[[Guard Thomas wants you to travel north up the river and search for the two lost guards, Rolf and Malakai.]]}
DB[38]={id=38,zoneId=40,name=[[Westfall Stew]],name_loc=[[Estofado de los Páramos de Poniente]],level=13,minLevel=9,giver=[[Salma Saldean]],giverType=[[NPC]],giverId=235,ender=[[Salma Saldean]],enderType=[[NPC]],enderId=235,prevId=36,poiX=-10586,poiY=816,wowhead=[[https://www.wowhead.com/wotlk/quest=38]],image=[[assets/images/quests/placeholder.png]],desc=[[Help me make some Westfall Stew!  Come back with the following ingredients:     3 Stringy Vulture Meat   3 Goretusk Snouts   3 Murloc Eyes   3 Okra]],logDesc=[[Salma Saldean wants 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes, 3 Okra.]],rewards={{id=733,qty=3},{id=728,qty=1},{id=1479,qty=1},{id=2225,qty=1}}}
DB[39]={id=39,zoneId=12,name=[[Deliver Thomas' Report]],name_loc=[[Entrega el informe de Thomas]],level=10,minLevel=7,giver=[[Guard Thomas]],giver_loc=[[Guardia Thomas]],giverType=[[NPC]],giverId=261,ender=[[Marshal Dughan]],ender_loc=[[Alguacil Dughan]],enderType=[[NPC]],enderId=240,prevId=71,rewardNextId=59,poiX=-9466,poiY=74,wowhead=[[https://www.wowhead.com/wotlk/quest=39]],image=[[assets/images/quests/placeholder.png]],desc=[[Tell Marshal Dughan of Malakai and Rolf's deaths, and report to him that the Murlocs in eastern Elwynn cannot be contained by our current troop presence. I know we don't have many troops to spare, but hopefully Dughan can find someone.]],logDesc=[[Report to Marshal Dughan in Goldshire.]]}
DB[40]={id=40,zoneId=12,name=[[A Fishy Peril]],name_loc=[[Un peligro con olor a pescado]],level=10,minLevel=7,giver=[[Remy "Two Times"]],giver_loc=[[Remy "Dos Veces"]],giverType=[[NPC]],giverId=241,ender=[[Marshal Dughan]],ender_loc=[[Alguacil Dughan]],enderType=[[NPC]],enderId=240,rewardNextId=35,poiX=-9466,poiY=74,wowhead=[[https://www.wowhead.com/wotlk/quest=40]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, there's a new threat in Elwynn Forest!  Murlocs are swimming up the streams of eastern Elwynn, scaring away fish and attacking gentle folk! I warned Marshal Dughan, but he's more worried about the gnolls and the bandits.  He's not convinced that the murlocs are a danger. Please, $N, speak to Dughan and persuade him to send more troops to the east!]],logDesc=[[Remy "Two Times" wants you to speak with Marshal Dughan in Goldshire.]]}
DB[45]={id=45,zoneId=12,name=[[Discover Rolf's Fate]],name_loc=[[Descubre el destino de Rolf]],level=10,minLevel=7,giver=[[A half-eaten body]],giver_loc=[[Un cadáver medio comido]],giverType=[[GO]],giverId=55,ender=[[Rolf's corpse]],ender_loc=[[Cadáver de Rolf]],enderType=[[GO]],enderId=56,prevId=37,rewardNextId=71,poiX=-9224,poiY=-1234,wowhead=[[https://www.wowhead.com/wotlk/quest=45]],image=[[assets/images/quests/placeholder.png]],desc=[[Upon further searching the area, you find webbed footprints leading east along the shore of Stone Cairn Lake.  In the distance to the east, you can just barely see a Murloc village. Perhaps Rolf's fate ended there...]],logDesc=[[Search the murloc village for Rolf, or signs of his death.]]}
DB[46]={id=46,zoneId=12,name=[[Bounty on Murlocs]],name_loc=[[Recompensas por los múrlocs]],level=10,minLevel=7,giver=[[Guard Thomas]],giver_loc=[[Guardia Thomas]],giverType=[[NPC]],giverId=261,ender=[[Guard Thomas]],ender_loc=[[Guardia Thomas]],enderType=[[NPC]],enderId=261,poiX=-8986,poiY=-1251,wowhead=[[https://www.wowhead.com/wotlk/quest=46]],image=[[assets/images/quests/placeholder.png]],desc=[[The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn.  Slaughter them and bring me their torn murloc fins, and the Stormwind Army will reward you well. The murlocs have built a village at Stone Cairn Lake north of here, and another to the south where the stream forks.]],logDesc=[[Bring 8 Torn Murloc Fins to Guard Thomas at the east Elwynn bridge.]],choiceRewards={{id=4840,qty=1},{id=1158,qty=1},{id=1008,qty=1}}}
DB[47]={id=47,zoneId=12,name=[[Gold Dust Exchange]],name_loc=[[Intercambio de polvo de oro]],level=7,minLevel=4,giver=[[Remy "Two Times"]],giver_loc=[[Remy "Dos Veces"]],giverType=[[NPC]],giverId=241,ender=[[Remy "Two Times"]],ender_loc=[[Remy "Dos Veces"]],enderType=[[NPC]],enderId=241,poiX=-9317,poiY=-717,wowhead=[[https://www.wowhead.com/wotlk/quest=47]],image=[[assets/images/quests/placeholder.png]],desc=[[The Kobolds in these parts sometimes carry Gold Dust on them.  I could really use the stuff - bring me a load of it and I'll give you the best price in town...best price in town! You can find kobolds in the Fargodeep Mine to the south, and around the Jasperlode Mine to the northeast.]],logDesc=[[Bring 10 Gold Dust to Remy "Two Times" in Goldshire.  Gold Dust is gathered from Kobolds in Elwynn Forest.]],rewards={{id=1191,qty=1}}}
DB[48]={id=48,zoneId=40,name=[[Sweet Amber]],name_loc=[[Dulce ámbar]],level=44,minLevel=40,giver=[[Grimbooze Thunderbrew]],giver_loc=[[Tragoamargo Cebatruenos]],giverType=[[NPC]],giverId=239,ender=[[Grimbooze Thunderbrew]],ender_loc=[[Tragoamargo Cebatruenos]],enderType=[[NPC]],enderId=239,rewardNextId=49,poiX=-13803,poiY=373,wowhead=[[https://www.wowhead.com/wotlk/quest=48]],image=[[assets/images/quests/placeholder.png]],desc=[[In the land to the south where vines twist and creep Lies a hidden well where the water runs deep Pure as the Light's sacred Daughter Bring to me now some Holy Spring Water.]],logDesc=[[Bring Holy Spring Water to Grimbooze Thunderbrew.]]}
DB[49]={id=49,zoneId=40,name=[[Sweet Amber]],name_loc=[[Dulce ámbar]],level=44,minLevel=40,giver=[[Grimbooze Thunderbrew]],giver_loc=[[Tragoamargo Cebatruenos]],giverType=[[NPC]],giverId=239,ender=[[Grimbooze Thunderbrew]],ender_loc=[[Tragoamargo Cebatruenos]],enderType=[[NPC]],enderId=239,prevId=48,rewardNextId=50,poiX=-9974,poiY=-3658,wowhead=[[https://www.wowhead.com/wotlk/quest=49]],image=[[assets/images/quests/placeholder.png]],desc=[[Amber is the hue of my life's longest love Like the last embers of dusk in the sky above Retrieve for me so that my love shall be born One sack of each: barley, rye and corn.]],logDesc=[[Grimbooze Thunderbrew wants a Sack of Barley, a Sack of Rye and a Sack of Corn.]]}
DB[50]={id=50,zoneId=40,name=[[Sweet Amber]],name_loc=[[Dulce ámbar]],level=44,minLevel=40,giver=[[Grimbooze Thunderbrew]],giver_loc=[[Tragoamargo Cebatruenos]],giverType=[[NPC]],giverId=239,ender=[[Grimbooze Thunderbrew]],ender_loc=[[Tragoamargo Cebatruenos]],enderType=[[NPC]],enderId=239,prevId=49,rewardNextId=51,poiX=-11273,poiY=1455,wowhead=[[https://www.wowhead.com/wotlk/quest=50]],image=[[assets/images/quests/placeholder.png]],desc=[[I'll mix and mix till we have a mash For this will be our own private stash A still must be fashioned of metal strong Bring me some Truesilver so I can finish this song.]],logDesc=[[Grimbooze Thunderbrew wants Truesilver.]]}
DB[51]={id=51,zoneId=40,name=[[Sweet Amber]],name_loc=[[Dulce ámbar]],level=44,minLevel=40,giver=[[Grimbooze Thunderbrew]],giver_loc=[[Tragoamargo Cebatruenos]],giverType=[[NPC]],giverId=239,ender=[[Grimbooze Thunderbrew]],ender_loc=[[Tragoamargo Cebatruenos]],enderType=[[NPC]],enderId=239,prevId=50,rewardNextId=53,poiX=-5834,poiY=1505,wowhead=[[https://www.wowhead.com/wotlk/quest=51]],image=[[assets/images/quests/placeholder.png]],desc=[[Not yet filtered but freshly distilled Like unseeded land waiting there tilled. Next I will fashion our pile of charcoal Deliver a sycamore branch, that is your next goal.]],logDesc=[[Bring a Sycamore Branch to Grimbooze Thunderbrew.]]}
DB[52]={id=52,zoneId=12,name=[[Protect the Frontier]],name_loc=[[Proteger la frontera]],level=10,minLevel=7,giver=[[Guard Thomas]],giver_loc=[[Guardia Thomas]],giverType=[[NPC]],giverId=261,ender=[[Guard Thomas]],ender_loc=[[Guardia Thomas]],enderType=[[NPC]],enderId=261,poiX=-9717,poiY=-1612,wowhead=[[https://www.wowhead.com/wotlk/quest=52]],image=[[assets/images/quests/placeholder.png]],desc=[[Hail, $N.  Wild animals are growing more and more aggressive the farther we get from Goldshire, and the Eastvale Logging Camp suffers nearly constant attacks from wolves and bears! We could use your help out here.]],logDesc=[[Kill 8 Prowlers and 5 Young Forest Bears, and then return to Guard Thomas at the east Elwynn bridge.]],rewards={{id=858,qty=2}}}
DB[53]={id=53,zoneId=40,name=[[Sweet Amber]],name_loc=[[Dulce ámbar]],level=44,minLevel=40,giver=[[Grimbooze Thunderbrew]],giver_loc=[[Tragoamargo Cebatruenos]],giverType=[[NPC]],giverId=239,ender=[[Grimbooze Thunderbrew]],ender_loc=[[Tragoamargo Cebatruenos]],enderType=[[NPC]],enderId=239,prevId=51,poiX=-6851,poiY=-1539,wowhead=[[https://www.wowhead.com/wotlk/quest=53]],image=[[assets/images/quests/placeholder.png]],desc=[[Mellifluous liquid clear as a baby's tears Turns a lovely deep amber over the years But before we proceed to get lit to the hilt A barrel of charred oak must be built.]],logDesc=[[Bring Grimbooze Thunderbrew a bundle of Charred Oak.]],rewards={{id=744,qty=1}}}
DB[54]={id=54,zoneId=9,name=[[Report to Goldshire]],name_loc=[[Informa en Villadorada]],level=5,minLevel=1,giver=[[Marshal McBride]],giver_loc=[[Alguacil McBride]],giverType=[[NPC]],giverId=197,ender=[[Marshal Dughan]],ender_loc=[[Alguacil Dughan]],enderType=[[NPC]],enderId=240,prevId=21,poiX=-9466,poiY=74,wowhead=[[https://www.wowhead.com/wotlk/quest=54]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you are a $c with proven interest in the security of Northshire.  You are now tasked with the protection of the surrounding Elwynn Forest. If you accept this duty, then I have prepared papers that must be delivered to Marshal Dughan in Goldshire.  Goldshire lies along the southern road, past the border gates.]],logDesc=[[Take Marshal McBride's Documents to Marshal Dughan in Goldshire.]],rewards={{id=6078,qty=1}}}
DB[55]={id=55,zoneId=10,name=[[Morbent Fel]],name_loc=[[Morbent Vil]],level=32,minLevel=20,giver=[[Sven Yorgen]],giverType=[[NPC]],giverId=311,ender=[[Sven Yorgen]],enderType=[[NPC]],enderId=311,prevId=325,poiX=-10318,poiY=377,wowhead=[[https://www.wowhead.com/wotlk/quest=55]],image=[[assets/images/quests/placeholder.png]],desc=[[Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery.  His time in this land is drawing to an end... Use Morbent's Bane against him.  It will render his protective magics powerless. Slay him.  Slay him, and save us from his wickedness.  Be the instrument of my revenge, and a hero of Duskwood!]],logDesc=[[Use Morbent's Bane on Morbent Fel, kill Morbent Fel, then return Morbent's Bane to Sven at his camp.]],rewards={{id=7344,qty=1}},choiceRewards={{id=2954,qty=1},{id=2953,qty=1},{id=1282,qty=1}}}
DB[56]={id=56,zoneId=10,name=[[The Night Watch]],name_loc=[[La Guardia Nocturna]],level=24,minLevel=18,giver=[[Commander Althea Ebonlocke]],giver_loc=[[Comandante Althea Cerranegro]],giverType=[[NPC]],giverId=264,ender=[[Commander Althea Ebonlocke]],ender_loc=[[Comandante Althea Cerranegro]],enderType=[[NPC]],enderId=264,rewardNextId=57,poiX=-10954,poiY=-1376,wowhead=[[https://www.wowhead.com/wotlk/quest=56]],image=[[assets/images/quests/placeholder.png]],desc=[[As Commander of The Night Watch it is my sworn duty to protect the citizens of Darkshire.  Stormwind has retracted their commissioned guards from their posts here, leaving us to our own devices. If you feel worthy of the task, we need your help! Assist The Night Watch by venturing forth into Tranquil Gardens, just south of Darkshire, and slaying 8 Skeletal Warriors and 6 Skeletal Mages.  The undead threat must be thwarted!]],logDesc=[[Commander Althea Ebonlocke of Darkshire wants you to kill 8 Skeletal Warriors and 6 Skeletal Mages.]]}
DB[57]={id=57,zoneId=10,name=[[The Night Watch]],name_loc=[[La Guardia Nocturna]],level=26,minLevel=18,giver=[[Commander Althea Ebonlocke]],giver_loc=[[Comandante Althea Cerranegro]],giverType=[[NPC]],giverId=264,ender=[[Commander Althea Ebonlocke]],ender_loc=[[Comandante Althea Cerranegro]],enderType=[[NPC]],enderId=264,prevId=56,rewardNextId=58,poiX=-10509,poiY=191,wowhead=[[https://www.wowhead.com/wotlk/quest=57]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I'm getting reports of an undead infestation in the forest!  If you're up to the job, journey to the Raven Hill graveyard and slay 15 of those vile Skeletal Fiends and 15 Skeletal Horrors.  There are also reports of skeletons just south of Darkshire, in and around Tranquil Gardens Cemetery.  The undead must be driven from Duskwood!]],logDesc=[[Commander Althea Ebonlocke of Darkshire wants you to kill 15 Skeletal Fiends and 15 Skeletal Horrors.]]}
DB[58]={id=58,zoneId=10,name=[[The Night Watch]],name_loc=[[La Guardia Nocturna]],level=30,minLevel=18,giver=[[Commander Althea Ebonlocke]],giver_loc=[[Comandante Althea Cerranegro]],giverType=[[NPC]],giverId=264,ender=[[Commander Althea Ebonlocke]],ender_loc=[[Comandante Althea Cerranegro]],enderType=[[NPC]],enderId=264,prevId=57,poiX=-10333,poiY=121,wowhead=[[https://www.wowhead.com/wotlk/quest=58]],image=[[assets/images/quests/placeholder.png]],desc=[[The situation in Raven Hill is still grim.  The safety of Darkshire is in your hands, $N.  I don't have enough Watchers to keep the town safe.  We need you to dispatch for Raven Hill yet again and rid the eastern mausoleum of 20 Plague Spreaders!]],logDesc=[[Commander Althea Ebonlocke of Darkshire wants you to kill 20 Plague Spreaders in the eastern Raven Hill mausoleum.]],choiceRewards={{id=3604,qty=1},{id=3605,qty=1},{id=1729,qty=1}}}
DB[59]={id=59,zoneId=12,name=[[Cloth and Leather Armor]],name_loc=[[Armadura de paño y cuero]],level=10,minLevel=7,giver=[[Marshal Dughan]],giver_loc=[[Alguacil Dughan]],giverType=[[NPC]],giverId=240,ender=[[Sara Timberlain]],enderType=[[NPC]],enderId=278,prevId=39,poiX=-9532,poiY=-1222,wowhead=[[https://www.wowhead.com/wotlk/quest=59]],image=[[assets/images/quests/placeholder.png]],desc=[[For your shrewdness and valor, I have a marker here that is good for one piece of armor.  I want you to take it to Sara Timberlain at the Eastvale Logging Camp.  Give her the marker, and she will fashion the armor for you.  And after you receive it, $N, use it in the defense of Elwynn. The Eastvale Logging Camp is beyond Guard Thomas' post to the east.]],logDesc=[[Give Sara Timberlain the Stormwind Armor Marker.]],choiceRewards={{id=1171,qty=1},{id=2237,qty=1}}}
DB[60]={id=60,zoneId=12,name=[[Kobold Candles]],name_loc=[[Las velas de los kóbolds]],level=7,minLevel=3,giver=[[William Pestle]],giver_loc=[[William Mortero]],giverType=[[NPC]],giverId=253,ender=[[William Pestle]],ender_loc=[[William Mortero]],enderType=[[NPC]],enderId=253,rewardNextId=61,poiX=-9317,poiY=-717,wowhead=[[https://www.wowhead.com/wotlk/quest=60]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello, $ggood sir:my lady;!  Do you have a moment? My brother and I run an apothecary in Stormwind, and I'm here to gather large candles for their wax.  Can you help me? You can get large candles from kobolds, and I hear rumors that kobolds are infesting the Elwynn mines ... the Fargodeep mine to the south and Jasperlode Mine to the east.  I suggest looking for candles in one of those places.]],logDesc=[[Bring 8 Large Candles to William Pestle in Goldshire.]],rewards={{id=1434,qty=5}}}
DB[61]={id=61,zoneId=12,name=[[Shipment to Stormwind]],name_loc=[[Un envío para Ventormenta]],level=7,minLevel=3,giver=[[William Pestle]],giver_loc=[[William Mortero]],giverType=[[NPC]],giverId=253,ender=[[Morgan Pestle]],ender_loc=[[Morgan Mortero]],enderType=[[NPC]],enderId=279,prevId=60,poiX=-8858,poiY=625,wowhead=[[https://www.wowhead.com/wotlk/quest=61]],image=[[assets/images/quests/placeholder.png]],desc=[[My brother Morgan is waiting in Stormwind for my shipment of candles.  I don't have enough time to make the trip myself, but if you'd like to take him the shipment, he'll pay you well. I've packed up the candles, and you can find Morgan in our shop, Pestle's Apothecary, in the Stormwind Trade District.]],logDesc=[[Bring William's Shipment to Morgan Pestle in the Stormwind Trade District.]],choiceRewards={{id=1178,qty=15},{id=1177,qty=5},{id=2454,qty=2}}}
DB[62]={id=62,zoneId=12,name=[[The Fargodeep Mine]],name_loc=[[La Mina Abisal]],level=7,minLevel=4,giver=[[Marshal Dughan]],giver_loc=[[Alguacil Dughan]],giverType=[[NPC]],giverId=240,ender=[[Marshal Dughan]],ender_loc=[[Alguacil Dughan]],enderType=[[NPC]],enderId=240,rewardNextId=76,poiX=-9844,poiY=92,wowhead=[[https://www.wowhead.com/wotlk/quest=62]],image=[[assets/images/quests/placeholder.png]],desc=[[The mine in Northshire isn't the only one with problems!  I have reports that the Fargodeep Mine in Elwynn has also become a haven for Kobolds. Explore the mine and confirm these reports, then return to me.  The mine is almost due south of Goldshire, between the Stonefield and Maclure homesteads.]],logDesc=[[Explore the Fargodeep Mine, then return to Marshal Dughan in Goldshire.]]}
DB[63]={id=63,name=[[Call of Water]],name_loc=[[La llamada del agua]],level=-1,minLevel=20,giver=[[Islen Waterseer]],giver_loc=[[Islen Vidente del Agua]],giverType=[[NPC]],giverId=5901,ender=[[Brazier of Everfount]],enderType=[[GO]],enderId=113791,prevId=220,rewardNextId=100,poiX=419,poiY=1832,wowhead=[[https://www.wowhead.com/wotlk/quest=63]],image=[[assets/images/quests/placeholder.png]],desc=[[Along the coast of Silverpine, west of the Sepulcher, you will find a shrine that has become tainted by the plague. The spirits there no longer speak to our people and it will be up to you to defeat the manifestation and cleanse the pool. Take the elemental's bracers, along with the remaining drops of Brine's potion, and place them on the brazier. The ritual should be enough to summon a pure spirit for you to communicate with. Bring me proof the task is done, and I will reward you with your totem.]],logDesc=[[Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest.]]}
DB[64]={id=64,zoneId=40,name=[[The Forgotten Heirloom]],name_loc=[[La reliquia olvidada]],level=12,minLevel=9,giver=[[Farmer Furlbrow]],giver_loc=[[Granjero Cejade]],giverType=[[NPC]],giverId=237,ender=[[Farmer Furlbrow]],ender_loc=[[Granjero Cejade]],enderType=[[NPC]],enderId=237,poiX=-9850,poiY=1290,wowhead=[[https://www.wowhead.com/wotlk/quest=64]],image=[[assets/images/quests/placeholder.png]],desc=[[It was horrible!  Verna woke me when she heard a ruckus in the fields.  The fields were full of hooligans.  We left in a rush and I forgot to pack my pocket watch.  Verna's pa gave me that watch on our wedding day and I feel just sick knowing those thieves have it.  I left the pocket watch in the wardrobe at the farmhouse.  Look for the field of pumpkins to the West -- you can't miss it.  If you bring it back to me, I'd sure be grateful!]],logDesc=[[Farmer Furlbrow wants you to retrieve his pocket watch from the wardrobe in his farmhouse at the pumpkin farm to the West.]],rewards={{id=4541,qty=10},{id=1179,qty=10}}}
DB[65]={id=65,zoneId=40,name=[[The Defias Brotherhood]],name_loc=[[La hermandad de los Defias]],level=18,minLevel=14,giver=[[Gryan Stoutmantle]],giver_loc=[[Gryan Mantorrecio]],giverType=[[NPC]],giverId=234,ender=[[Wiley the Black]],ender_loc=[[Wiley el Negro]],enderType=[[NPC]],enderId=266,rewardNextId=132,poiX=-9232,poiY=-2146,wowhead=[[https://www.wowhead.com/wotlk/quest=65]],image=[[assets/images/quests/placeholder.png]],desc=[[The band of wretches responsible for driving the good people of Westfall from the land call themselves The Defias Brotherhood.  I need you to infiltrate this clan of thugs.  We need to know who heads up the cartel and where they are hiding out.  In Lakeshire, in the inn, there is a rogue by the name of Wiley who owes me a favor. Travel to Lakeshire in the Redridge Mountains, east of Elwynn, and find out what you can.]],logDesc=[[Gryan Stoutmantle wants you to talk to Wiley in Lakeshire.]]}
DB[66]={id=66,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Madame Eva]],giver_loc=[[Lady Eva]],giverType=[[NPC]],giverId=265,ender=[[Clerk Daltry]],ender_loc=[[Secretario Daltry]],enderType=[[NPC]],enderId=267,rewardNextId=67,poiX=-10560,poiY=-1125,wowhead=[[https://www.wowhead.com/wotlk/quest=66]],image=[[assets/images/quests/placeholder.png]],desc=[[Last night a horrible disturbance rippled through my veins.  I sensed that my granddaughter, Alyssa, was in great danger.  I consulted the cards and Death stared up at me from the table. After taking a long journey through a dark trance I was able to uncover a clue to this terrifying mystery.  A name came to me, the name of Stalvan. Seek out the Clerk in the Town Hall and see if you can find out more about this character.  I fear for us all.]],logDesc=[[Seek out the Clerk Daltry in the Darkshire Town Hall.]]}
DB[67]={id=67,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Clerk Daltry]],giver_loc=[[Secretario Daltry]],giverType=[[NPC]],giverId=267,ender=[[Old Footlocker]],ender_loc=[[Baúl antiguo]],enderType=[[GO]],enderId=3643,prevId=66,rewardNextId=68,poiX=-10957,poiY=1564,wowhead=[[https://www.wowhead.com/wotlk/quest=67]],image=[[assets/images/quests/placeholder.png]],desc=[[Stalvan, eh?  Let me check the town registry. Stalvan. . .Stalvan. . .let's see.  Ah, here we go!  I have a record of a Mr. Stalvan Mistmantle.  The last recorded address is the Moonbrook Schoolhouse.  My, talk about outdated! Do me a favor will you, friend?  If you happen to go out to Moonbrook, let me know if you get any update on this fellow.  I like to keep the records clean.]],logDesc=[[Travel to the Moonbrook Schoolhouse and bring back any updated information about Stalvan to Clerk Daltry.]]}
DB[68]={id=68,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Old Footlocker]],giver_loc=[[Baúl antiguo]],giverType=[[GO]],giverId=3643,ender=[[Clerk Daltry]],ender_loc=[[Secretario Daltry]],enderType=[[NPC]],enderId=267,prevId=67,rewardNextId=69,poiX=-10560,poiY=-1125,wowhead=[[https://www.wowhead.com/wotlk/quest=68]],image=[[assets/images/quests/placeholder.png]],desc=[[You find a Dusty Unsent Letter in the old footlocker.]],logDesc=[[Take the Dusty Unsent Letter to Clerk Daltry.]]}
DB[69]={id=69,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Clerk Daltry]],giver_loc=[[Secretario Daltry]],giverType=[[NPC]],giverId=267,ender=[[Innkeeper Farley]],ender_loc=[[Tabernero Farley]],enderType=[[NPC]],enderId=295,prevId=68,rewardNextId=70,poiX=-9463,poiY=16,wowhead=[[https://www.wowhead.com/wotlk/quest=69]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh my!  Must have missed this the first time.  In the registry, right beneath the first address for Stalvan there's another one listed, only partially scratched out.  Looks like he was headed to The Lion's Pride Inn over in Goldshire.  Might want to check there, $N.]],logDesc=[[Go to The Lion's Pride Inn to see if anyone there has heard of the name Stalvan.]]}
DB[70]={id=70,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Innkeeper Farley]],giver_loc=[[Tabernero Farley]],giverType=[[NPC]],giverId=295,ender=[[Caretaker Folsom]],ender_loc=[[Custodio Folsom]],enderType=[[NPC]],enderId=297,prevId=69,rewardNextId=72,poiX=-9463,poiY=-2,wowhead=[[https://www.wowhead.com/wotlk/quest=70]],image=[[assets/images/quests/placeholder.png]],desc=[[The name Stalvan rings a bell.  I remember now. Many years back, on a stormy night, a messenger came in, seeking refuge for the night.  Near the stroke of midnight, the man ran down the stairs screaming, his face pale with fear.  Still wearing his bedclothes, he disappeared into the downpour. In his haste he forgot his letters in the chest upstairs.  He never returned for them. One remains from that Stalvan fellow, intended for the Canal District in Stormwind.  Help yourself to it.]],logDesc=[[Retrieve Stalvan's Undelivered Letter from the chest and deliver it to the Canal District in Stormwind.]]}
DB[71]={id=71,zoneId=12,name=[[Report to Thomas]],name_loc=[[Informa a Thomas]],level=10,minLevel=7,giver=[[Rolf's corpse]],giver_loc=[[Cadáver de Rolf]],giverType=[[GO]],giverId=56,ender=[[Guard Thomas]],ender_loc=[[Guardia Thomas]],enderType=[[NPC]],enderId=261,prevId=45,rewardNextId=39,poiX=-9610,poiY=-1032,wowhead=[[https://www.wowhead.com/wotlk/quest=71]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you have both medallions, deliver them to Guard Thomas at the bridge so that he might know the fate of his murdered guards.]],logDesc=[[Deliver Rolf and Malakai's Medallions to Guard Thomas at the eastern Elwynn bridge.]]}
DB[72]={id=72,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Caretaker Folsom]],giver_loc=[[Custodio Folsom]],giverType=[[NPC]],giverId=297,ender=[[Sealed Crate]],ender_loc=[[Cajón sellado]],enderType=[[GO]],enderId=1561,prevId=70,rewardNextId=74,poiX=-8830,poiY=985,wowhead=[[https://www.wowhead.com/wotlk/quest=72]],image=[[assets/images/quests/placeholder.png]],desc=[[My father was the caretaker of the estate long before I was.  He had to mop the blood up after the massacre.  But that's neither here nor there. The last funds of the Flintridge trust have dried up.  Now the last of the family possessions are headed for auction.  Blame the tax vultures.  I guess if you're really itching to learn more you're free to look through this junk.  Who knows what you might find.]],logDesc=[[Search through the packed up possessions for a clue.]]}
DB[74]={id=74,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Sealed Crate]],giver_loc=[[Cajón sellado]],giverType=[[GO]],giverId=1561,ender=[[Marshal Haggard]],ender_loc=[[Mariscal Haggard]],enderType=[[NPC]],enderId=294,prevId=72,rewardNextId=75,poiX=-9545,poiY=-1401,wowhead=[[https://www.wowhead.com/wotlk/quest=74]],image=[[assets/images/quests/placeholder.png]],desc=[[Inside the crate you find various objects: musty heirlooms, a family portrait, a few hunting trophies and some old books.  Near the bottom, underneath a ceramic vase, you uncover A Torn Journal Page.]],logDesc=[[The Torn Journal page you discovered provides your next clue.]]}
DB[75]={id=75,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Marshal Haggard]],giver_loc=[[Mariscal Haggard]],giverType=[[NPC]],giverId=294,ender=[[Marshal Haggard]],ender_loc=[[Mariscal Haggard]],enderType=[[NPC]],enderId=294,prevId=74,rewardNextId=78,poiX=-9549,poiY=-1439,wowhead=[[https://www.wowhead.com/wotlk/quest=75]],image=[[assets/images/quests/placeholder.png]],desc=[[There was a bundle of parchments in the chest upstairs when I moved into this place.  I looked at them once when I first arrived but I gave up once the fog hazed over my peepers.  Do an old, nearly-blind man a favor and check the chest upstairs for anything that might help you in your quest to discover more about this Stalvan character.  I'm pretty sure there's a faded journal page that might be of interest to you.  Bring it to me and I'll help in anyway I can.]],logDesc=[[Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page.]]}
DB[76]={id=76,zoneId=12,name=[[The Jasperlode Mine]],name_loc=[[La Cantera de Jaspe]],level=10,minLevel=4,giver=[[Marshal Dughan]],giver_loc=[[Alguacil Dughan]],giverType=[[NPC]],giverId=240,ender=[[Marshal Dughan]],ender_loc=[[Alguacil Dughan]],enderType=[[NPC]],enderId=240,prevId=62,poiX=-9029,poiY=-644,wowhead=[[https://www.wowhead.com/wotlk/quest=76]],image=[[assets/images/quests/placeholder.png]],desc=[[Thanks to you we know the Fargodeep Mine is infested with kobolds.  Now we need a scout to investigate the more distant Jasperlode Mine. Explore Jasperlode and confirm any kobold presence.  To reach the mine, travel east along the road until you reach the Tower of Azora.  From the tower, head north and you'll find the mine in the foothills.]],logDesc=[[Explore the Jasperlode Mine, then report back to Marshal Dughan in Goldshire.]]}
DB[77]={id=77,zoneId=47,name=[[A Sticky Situation]],name_loc=[[Una situación peliaguda]],level=48,minLevel=42,giver=[[Gilveradin Sunchaser]],giver_loc=[[Gilveradin Cazasol]],giverType=[[NPC]],giverId=7801,ender=[[Gilveradin Sunchaser]],ender_loc=[[Gilveradin Cazasol]],enderType=[[NPC]],enderId=7801,prevId=650,poiX=475,poiY=-3801,wowhead=[[https://www.wowhead.com/wotlk/quest=77]],image=[[assets/images/quests/placeholder.png]],desc=[[I possess original packaging materials for the ripple Dran Droffers seeks.  I will assist you in packaging the ripple for Malton's abrasive father... for a fee of two additional bottles of said ripple.  They are located in crates found in the abandoned Horde base near Skulk Rock. It will be an arduous task, to wit; foul slimes and oozes will be found sticking to the ruins; rumor has it they are led by some sort of master ooze.  Regardless, procure the ripple and return to me here for packaging.]],logDesc=[[Recover 10 bottles of Hinterlands Honey Ripple from the crates located around the abandoned Horde base in Skulk Rock.]]}
DB[78]={id=78,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Marshal Haggard]],giver_loc=[[Mariscal Haggard]],giverType=[[NPC]],giverId=294,ender=[[Tavernkeep Smitts]],ender_loc=[[Tabernero Smitts]],enderType=[[NPC]],enderId=273,prevId=75,rewardNextId=79,poiX=-10517,poiY=-1159,wowhead=[[https://www.wowhead.com/wotlk/quest=78]],image=[[assets/images/quests/placeholder.png]],desc=[[I know of someone who might be able to assist you.  Back when I was leading the Stormwind Guard, we used to get drinks at the Scarlet Raven Tavern in Darkshire.  The Innkeeper there, Smitts, was quite an expert on the local lore.  Show him this page and see what he has to say about it.]],logDesc=[[Take the Faded Journal Page to Tavernkeep Smitts at Darkshire in Duskwood.]]}
DB[79]={id=79,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Tavernkeep Smitts]],giver_loc=[[Tabernero Smitts]],giverType=[[NPC]],giverId=273,ender=[[Commander Althea Ebonlocke]],ender_loc=[[Comandante Althea Cerranegro]],enderType=[[NPC]],enderId=264,prevId=78,rewardNextId=80,poiX=-10560,poiY=-1152,wowhead=[[https://www.wowhead.com/wotlk/quest=79]],image=[[assets/images/quests/placeholder.png]],desc=[[I followed the legend of that Stalvan character for years.  When those visiting nobles were slaughtered a few years back I went with Haggard to investigate.  I found these muddy pages but we were never able to link the handwriting to that crazy man in the woods.  Your trail of evidence proves his guilt.  Take this to Commander Ebonlocke immediately and fill her in on what you've discovered!]],logDesc=[[Take the muddy page to Commander Ebonlocke.]],rewards={{id=939,qty=1}}}
DB[80]={id=80,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Commander Althea Ebonlocke]],giver_loc=[[Comandante Althea Cerranegro]],giverType=[[NPC]],giverId=264,ender=[[Clerk Daltry]],ender_loc=[[Secretario Daltry]],enderType=[[NPC]],enderId=267,prevId=79,rewardNextId=97,poiX=-10560,poiY=-1125,wowhead=[[https://www.wowhead.com/wotlk/quest=80]],image=[[assets/images/quests/placeholder.png]],desc=[[I have had my eye on that creep, Stalvan, for quite sometime.  But if this page was written by the same hand it proves his guilt beyond a shadow of a doubt. In all his days keeping the Town Registry, Clerk Daltry has become an expert at identifying handwriting.  Show him this page and see if the writing matches that of the registry signature.]],logDesc=[[Show Clerk Daltry the Bloodstained Journal Page.]]}
DB[81]={id=81,zoneId=1637,name=[[Ripple Delivery]],name_loc=[[Entrega el calimocho]],level=48,minLevel=42,giver=[[Gilveradin Sunchaser]],giver_loc=[[Gilveradin Cazasol]],giverType=[[NPC]],giverId=7801,ender=[[Dran Droffers]],ender_loc=[[Dran Droffers]],enderType=[[NPC]],enderId=6986,prevId=77,poiX=1932,poiY=-4515,wowhead=[[https://www.wowhead.com/wotlk/quest=81]],image=[[assets/images/quests/placeholder.png]],desc=[[I have taken the extra step of securing not only Dran's packaged ripple in the barrel, but also the extra bottles of ripple he is purloining.  While I may not hold Dran very highly, there is nothing worse than jostled ripple.  You're welcome. Now, deliver yon barrel to Dran Droffers in his salvage emporium in Orgrimmar.  Pray tell, please extend my warmest greetings to Malton; let him know that should he ever thirst for fine drink and finer drinking companions, we would be honored with his visit.]],logDesc=[[Deliver the barrel to Dran Droffers in Orgrimmar.]]}
DB[82]={id=82,zoneId=440,name=[[Noxious Lair Investigation]],name_loc=[[Investigación en la Guarida Ponzoñosa]],level=47,minLevel=39,giver=[[Senior Surveyor Fizzledowser]],giver_loc=[[Perito jefe Picoflojo]],giverType=[[NPC]],giverId=7724,ender=[[Alchemist Pestlezugg]],ender_loc=[[Alquimista Morterozugg]],enderType=[[NPC]],enderId=5594,prevId=992,poiX=-7942,poiY=-2814,wowhead=[[https://www.wowhead.com/wotlk/quest=82]],image=[[assets/images/quests/placeholder.png]],desc=[[All right now, these reports about the bugs... what we know is that they are draining the water pools that used to be where the Noxious Lair is. What we DON'T know is, well, everything else. Let's figure out who our enemy is first! I want you to head into the Noxious Lair and get some parts off of those critters. Get five from the Centipaar there and bring them to Alchemist Pestlezugg for him to dink with. With him on the case, we'll figure out what they are!]],logDesc=[[Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan.]]}
DB[83]={id=83,zoneId=12,name=[[Red Linen Goods]],name_loc=[[Pañuelos de lino rojo]],level=9,minLevel=4,giver=[[Sara Timberlain]],giverType=[[NPC]],giverId=278,ender=[[Sara Timberlain]],enderType=[[NPC]],enderId=278,poiX=-9866,poiY=-223,wowhead=[[https://www.wowhead.com/wotlk/quest=83]],image=[[assets/images/quests/placeholder.png]],desc=[[The Defias gang in Northshire wears burlap masks, but the Defias in Elwynn wear linen which I can use to make fine linen goods. Bring me red linen bandanas and I'll use them to fashion something for you. Defias gang members have camps pocketed throughout Elwynn.]],logDesc=[[Bring 6 Red Linen Bandanas to Sara Timberlain at the Eastvale Logging Camp.]],rewards={{id=2575,qty=1},{id=983,qty=1}}}
DB[84]={id=84,zoneId=12,name=[[Back to Billy]],name_loc=[[Vuelve con Billy]],level=6,minLevel=5,giver=[["Auntie" Bernice Stonefield]],giver_loc=[["Tita" Bernice Pedregosa]],giverType=[[NPC]],giverId=246,ender=[[Billy Maclure]],enderType=[[NPC]],enderId=247,prevId=86,rewardNextId=87,poiX=-9924,poiY=38,wowhead=[[https://www.wowhead.com/wotlk/quest=84]],image=[[assets/images/quests/placeholder.png]],desc=[[Here you go.  And when you give this pie to that Billy, you tell him I hope he chokes on it!]],logDesc=[[Bring the Pork Belly Pie to Billy Maclure at the Maclure Vineyards.]]}
DB[85]={id=85,zoneId=12,name=[[Lost Necklace]],name_loc=[[El collar perdido]],level=6,minLevel=5,giver=[["Auntie" Bernice Stonefield]],giver_loc=[["Tita" Bernice Pedregosa]],giverType=[[NPC]],giverId=246,ender=[[Billy Maclure]],enderType=[[NPC]],enderId=247,rewardNextId=86,poiX=-9924,poiY=38,wowhead=[[https://www.wowhead.com/wotlk/quest=85]],image=[[assets/images/quests/placeholder.png]],desc=[[I lost my necklace, and think that guttersnipe Billy Maclure took it!  He's usually scuttling like a rat around the Maclure vineyards east of here.  Get my necklace back for me, and you'll warm an old widow's heart.]],logDesc=[[Speak with Billy Maclure.]]}
DB[86]={id=86,zoneId=12,name=[[Pie for Billy]],name_loc=[[Un pastel para Billy]],level=6,minLevel=5,giver=[[Billy Maclure]],giverType=[[NPC]],giverId=247,ender=[["Auntie" Bernice Stonefield]],ender_loc=[["Tita" Bernice Pedregosa]],enderType=[[NPC]],enderId=246,prevId=85,rewardNextId=84,poiX=-9785,poiY=-1050,wowhead=[[https://www.wowhead.com/wotlk/quest=86]],image=[[assets/images/quests/placeholder.png]],desc=[[Maybe if I got a pie, I could tell you who has that necklace.  And you know, I think that old Bernice lady at that other farm makes great Pork Belly Pies...  Maybe if you gave her some chunks of boar meat from the boars that hang around our farms, and told her what it was for, she'd bake up a pie for you.]],logDesc=[[Bring 4 Chunks of Boar Meat to Auntie Bernice Stonefield at the Stonefield's Farm.]]}
DB[87]={id=87,zoneId=12,name=[[Goldtooth]],name_loc=[[Dientes de Oro]],level=8,minLevel=5,giver=[[Billy Maclure]],giverType=[[NPC]],giverId=247,ender=[["Auntie" Bernice Stonefield]],ender_loc=[["Tita" Bernice Pedregosa]],enderType=[[NPC]],enderId=246,prevId=84,poiX=-9746,poiY=88,wowhead=[[https://www.wowhead.com/wotlk/quest=87]],image=[[assets/images/quests/placeholder.png]],desc=[[I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace.  Don't ask me how it got there...it wasn't me! Well anyway, I saw this big, gold-toothed kobold pick up the necklace and run into the mine.  Go find that kobold and you'll find the necklace, I swear!]],logDesc=[[Bring Bernice's Necklace to "Auntie" Bernice Stonefield at the Stonefield Farm.]],rewards={{id=1359,qty=1}}}
DB[88]={id=88,zoneId=12,name=[[Princess Must Die!]],name_loc=[[¡Princesa debe morir!]],level=9,minLevel=6,giver=[[Ma Stonefield]],giver_loc=[[La vieja Pedregosa]],giverType=[[NPC]],giverId=244,ender=[[Ma Stonefield]],ender_loc=[[La vieja Pedregosa]],enderType=[[NPC]],enderId=244,poiX=-9783,poiY=-885,wowhead=[[https://www.wowhead.com/wotlk/quest=88]],image=[[assets/images/quests/placeholder.png]],desc=[[The Brackwells have a prize-winning pig, Princess.  The sow is HUGE, and she got that way from sneaking over here and eating my veggies! So before she comes to our fields...Princess must die!  Bring me her collar as proof of the deed and I'll give you something for your time! Princess is usually over at the Brackwell Pumpkin Patch, to the east and beyond the Maclure farm.  Get her before she gets hungry and comes back here!]],logDesc=[[Kill Princess, grab her collar, then bring it back to Ma Stonefield at the Stonefield Farm.]],choiceRewards={{id=1173,qty=1},{id=1182,qty=1},{id=11191,qty=1}}}
DB[89]={id=89,zoneId=44,name=[[The Everstill Bridge]],name_loc=[[El puente sempiterno]],level=20,minLevel=15,giver=[[Foreman Oslow]],giver_loc=[[Supervisor Olento]],giverType=[[NPC]],giverId=341,ender=[[Foreman Oslow]],ender_loc=[[Supervisor Olento]],enderType=[[NPC]],enderId=341,prevId=125,poiX=-8980,poiY=-2338,wowhead=[[https://www.wowhead.com/wotlk/quest=89]],image=[[assets/images/quests/placeholder.png]],desc=[[During the last orc invasion we were forced to smelt our iron down to make bullets, swords and armor.  We sent word to Stormwind for a new shipment of materials but a band of Redridge gnolls hijacked the caravan and ran off into the hills behind Lakeshire. Now we're coming up short on supplies to get this bridge rebuilt.  If you can bring me 5 iron pikes and 5 iron rivets, $N, I'll make sure you're rewarded.  Now let's get to work!]],logDesc=[[Bring 5 Iron Pikes and 5 Iron Rivets to Foreman Oslow in Lakeshire.]],choiceRewards={{id=1310,qty=1},{id=1303,qty=1},{id=1304,qty=1}}}
DB[90]={id=90,zoneId=10,name=[[Seasoned Wolf Kabobs]],name_loc=[[Kebab de lobo sazonado]],level=25,minLevel=18,giver=[[Chef Grual]],giverType=[[NPC]],giverId=272,ender=[[Chef Grual]],enderType=[[NPC]],enderId=272,poiX=-8822,poiY=518,wowhead=[[https://www.wowhead.com/wotlk/quest=90]],image=[[assets/images/quests/placeholder.png]],desc=[[Seasoned Wolf Kabobs are a house favorite!  Sure, I can make you some.  But first I'll need the supplies.  Bring me 10 Lean Wolf Flanks as well as some Stormwind Seasoning Herbs.  There are so many wolves here in the forest, I am sure finding the Flanks will be no problem.  For the herbs, seek out Felicia Gump in her canal district flower shop in Stormwind.]],logDesc=[[Gather 10 Lean Wolf Flanks and Stormwind Seasoning Herbs and return to Chef Grual in Darkshire.]],rewards={{id=1017,qty=4},{id=2701,qty=1}}}
DB[91]={id=91,zoneId=44,name=[[Solomon's Law]],name_loc=[[Ley de Solomon]],level=23,minLevel=17,giver=[[Bailiff Conacher]],giver_loc=[[Alguacil Conacher]],giverType=[[NPC]],giverId=900,ender=[[Bailiff Conacher]],ender_loc=[[Alguacil Conacher]],enderType=[[NPC]],enderId=900,poiX=-9267,poiY=-3355,wowhead=[[https://www.wowhead.com/wotlk/quest=91]],image=[[assets/images/quests/placeholder.png]],desc=[[An enemy of Stormwind has taken up residence in the eastern foothills of Redridge. This wicked villain uses the Arcane to spread terror and misery upon our town and our people. Under the name, Morganth, he conducts his evil business. Morganth now controls the Shadowhide Gnoll Clan to perform his biddings. As stated by the Law of Lakeshire, aiding a criminal of the Kingdom is punishable by death. These vile gnolls must be killed! Turn in 10 Shadowhide Pendants to me, and you shall be rewarded.]],logDesc=[[Bring 10 Shadowhide Pendants to Bailiff Conacher in the Lakeshire Town Hall.]]}
DB[92]={id=92,zoneId=44,name=[[Redridge Goulash]],name_loc=[[Estofado Crestagrana]],level=18,minLevel=15,giver=[[Chef Breanna]],giverType=[[NPC]],giverId=343,ender=[[Chef Breanna]],enderType=[[NPC]],enderId=343,poiX=-9493,poiY=-2346,wowhead=[[https://www.wowhead.com/wotlk/quest=92]],image=[[assets/images/quests/placeholder.png]],desc=[[Nothing would please me more than to make you some Redridge Goulash. But there's a slight problem. During the recent orc uprising I fed the entire brigade of Stormwind troops. My cupboard is now bare. But if you can provide me with the ingredients, I'd be happy to oblige. Just bring me five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.]],logDesc=[[Chef Breanna of Lakeshire wants five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.]],rewards={{id=1082,qty=5},{id=2699,qty=1}}}
DB[93]={id=93,zoneId=10,name=[[Dusky Crab Cakes]],name_loc=[[Los pasteles de cangrejo oscuro]],level=20,minLevel=17,giver=[[Chef Grual]],giverType=[[NPC]],giverId=272,ender=[[Chef Grual]],enderType=[[NPC]],enderId=272,prevId=5,rewardNextId=240,poiX=-10051,poiY=-1250,wowhead=[[https://www.wowhead.com/wotlk/quest=93]],image=[[assets/images/quests/placeholder.png]],desc=[[I'll let you in on a little secret - Dusky "Crab" Cakes are really made from spider legs!  I know it's a bit disgusting, but the cakes have a nice, tangy flavor and make great snacks!  Bring me Gooey Spider Legs and I'll whip you up a few of them. I hear Venom Web Spiders are a good source - they nest to the north, between the foothills and the river.]],logDesc=[[Gather 6 Gooey Spider Legs and bring them to Chef Grual in Darkshire.]],rewards={{id=3683,qty=1}}}
DB[94]={id=94,zoneId=44,name=[[A Watchful Eye]],name_loc=[[Un ojo vigilante]],level=21,minLevel=20,giver=[[Theocritus]],giver_loc=[[Theocritus]],giverType=[[NPC]],giverId=313,ender=[[Old Lion Statue]],ender_loc=[[Estatua de león antigua]],enderType=[[GO]],enderId=31,rewardNextId=248,poiX=-9253,poiY=-3405,wowhead=[[https://www.wowhead.com/wotlk/quest=94]],image=[[assets/images/quests/placeholder.png]],desc=[[My rival, Morganth, is a vicious mage of great power who lives in the Tower of Ilgalar in Redridge.  I have developed a means of spying on him, the Eye of Azora, and can now view him from afar. But to study his thoughts ... I require further aid. If you are willing, then take my Glyph of Azora to the Tower of Ilgalar.  Place it upon the Lion Statue near the Tower. When this is done, the power of Azora will grant visions of Morganth's future plans.]],logDesc=[[Take the Glyph of Azora to the Lion Statue near the Tower of Ilgalar in Redridge.]]}
DB[95]={id=95,zoneId=10,name=[[Sven's Revenge]],name_loc=[[La venganza de Sven]],level=25,minLevel=20,giver=[[Sven Yorgen]],giverType=[[NPC]],giverId=311,ender=[[Mound of loose dirt]],enderType=[[GO]],enderId=59,rewardNextId=230,poiX=-11116,poiY=-513,wowhead=[[https://www.wowhead.com/wotlk/quest=95]],image=[[assets/images/quests/placeholder.png]],desc=[[I used to work one of the farms to the southeast...until Dark Riders from Deadwind Pass descended upon my farm and slaughtered my family when I was away! When I returned I saw a shadowy figure skulking near my barn, burying something.  He fled before I could catch him, and I couldn't linger for I was hot on the heels of the Dark Riders.  So I never discovered what was hidden. If you can find what that shadowy figure buried, I would be grateful.  The hiding spot is behind the old stump near my barn.]],logDesc=[[Go to Sven's Farm and find what was buried behind the old stump.]]}
DB[96]={id=96,name=[[Call of Water]],name_loc=[[La llamada del agua]],level=-1,minLevel=20,giver=[[Minor Manifestation of Water]],giver_loc=[[Manifestación de agua menor]],giverType=[[NPC]],giverId=5895,ender=[[Islen Waterseer]],ender_loc=[[Islen Vidente del Agua]],enderType=[[NPC]],enderId=5901,prevId=100,poiX=-1345,poiY=-4048,wowhead=[[https://www.wowhead.com/wotlk/quest=96]],image=[[assets/images/quests/placeholder.png]],desc=[[Take shard. Take shard and give life. Give life and understand. Understand water is life... corruption stops life. You protect and give life with water's power.]],logDesc=[[Bring the Shard of Water to Islen Waterseer at the Tidus Stair in the Barrens.]],rewards={{id=5177,qty=1}}}
DB[97]={id=97,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=28,minLevel=22,giver=[[Clerk Daltry]],giver_loc=[[Secretario Daltry]],giverType=[[NPC]],giverId=267,ender=[[Commander Althea Ebonlocke]],ender_loc=[[Comandante Althea Cerranegro]],enderType=[[NPC]],enderId=264,prevId=80,rewardNextId=98,poiX=-10560,poiY=-1152,wowhead=[[https://www.wowhead.com/wotlk/quest=97]],image=[[assets/images/quests/placeholder.png]],desc=[[Let Commander Ebonlocke know immediately that the handwriting matched, $N!  Her suspicions were correct!]],logDesc=[[Report the news to Commander Ebonlocke.]]}
DB[98]={id=98,zoneId=10,name=[[The Legend of Stalvan]],name_loc=[[La leyenda de Stalvan]],level=32,minLevel=22,giver=[[Commander Althea Ebonlocke]],giver_loc=[[Comandante Althea Cerranegro]],giverType=[[NPC]],giverId=264,ender=[[Madame Eva]],ender_loc=[[Lady Eva]],enderType=[[NPC]],enderId=265,prevId=97,poiX=-10369,poiY=-1255,wowhead=[[https://www.wowhead.com/wotlk/quest=98]],image=[[assets/images/quests/placeholder.png]],desc=[[Stalvan Mistmantle led a life of depravity.  Innocent victims died by his hand.  Undoubtedly he is guilty of countless crimes.  Now the lunatic threatens Darkshire.  The Light only knows what sordid acts he is plotting.  Travel to his cottage just north of town, $C, and execute Stalvan, once and for all. When the deed is done, travel to Madame Eva's and show her his family ring.  After all, it was her premonition that led to this gruesome discovery.  But Darkshire is safer because of her.]],logDesc=[[Kill Stalvan Mistmantle and show Madame Eva his family ring.]],choiceRewards={{id=2044,qty=1},{id=2043,qty=1}}}
DB[99]={id=99,zoneId=130,name=[[Arugal's Folly]],name_loc=[[La locura de Arugal]],level=15,minLevel=9,giver=[[Dalar Dawnweaver]],giver_loc=[[Dalar Tejealba]],giverType=[[NPC]],giverId=1938,ender=[[Dalar Dawnweaver]],ender_loc=[[Dalar Tejealba]],enderType=[[NPC]],enderId=1938,prevId=424,poiX=-354,poiY=1422,wowhead=[[https://www.wowhead.com/wotlk/quest=99]],image=[[assets/images/quests/placeholder.png]],desc=[[As my understanding of Arugal's magic grows so does my disdain for the hapless fool.  I am close to completing my research on his so called remedy. My knowledge will be complete when I learn what enchantment is causing the strange behavior going on in Pyrewood Village.  By day, the peasants appear to be Human.  But when the sun goes down the townsfolk turn into Moonrage Worgen. I need to draw energy from the enchanted shackles Arugal cast on them.  Bring to me six enchanted Pyrewood Shackles, $N.]],logDesc=[[Bring 6 Pyrewood Shackles to Dalar Dawnweaver at the Sepulcher.]],choiceRewards={{id=3586,qty=1},{id=3570,qty=1},{id=5242,qty=1}}}
DB[100]={id=100,name=[[Call of Water]],name_loc=[[La llamada del agua]],level=-1,minLevel=20,giver=[[Tiev Mordune]],giverType=[[GO]],giverId=7007,ender=[[Minor Manifestation of Water]],ender_loc=[[Manifestación de agua menor]],enderType=[[NPC]],enderId=5895,prevId=63,rewardNextId=96,poiX=417,poiY=1823,wowhead=[[https://www.wowhead.com/wotlk/quest=100]],image=[[assets/images/quests/placeholder.png]],desc=[[Light explodes as you finish the incantation. The sounds of the water drops hitting the flame have died down and your senses are overcome as the corrupt spirits around you are destroyed.]],logDesc=[[Speak to the Minor Manifestation of Water at North Tide's Run in Silverpine Forest.]]}
DB[101]={id=101,zoneId=10,name=[[The Totem of Infliction]],name_loc=[[El Tótem de castigo]],level=25,minLevel=18,giver=[[Madame Eva]],giver_loc=[[Lady Eva]],giverType=[[NPC]],giverId=265,ender=[[Madame Eva]],ender_loc=[[Lady Eva]],enderType=[[NPC]],enderId=265,poiX=-10332,poiY=108,wowhead=[[https://www.wowhead.com/wotlk/quest=101]],image=[[assets/images/quests/placeholder.png]],desc=[[As the mystical taint creeps through the forest, the need for self-protection is undeniable, $N.  The winds whisper to me and they speak of a great danger which waits patiently for you in the near future. If you wish to protect yourself, noble $c, bring to me 10 ghoul fangs, 10 skeleton fingers and 5 vials of spider venom.  For you I shall enchant a Totem of Infliction which will harm those who attempt violent acts against you.]],logDesc=[[Bring 10 Ghoul Fangs, 10 Skeleton Fingers and 5 Vials of Spider Venom to Madame Eva in Darkshire.]],rewards={{id=1131,qty=1}}}
DB[102]={id=102,zoneId=40,name=[[Patrolling Westfall]],name_loc=[[En patrulla por los Páramos de Poniente]],level=14,minLevel=8,giver=[[Captain Danuvin]],giver_loc=[[Capitán Danuvin]],giverType=[[NPC]],giverId=821,ender=[[Captain Danuvin]],ender_loc=[[Capitán Danuvin]],enderType=[[NPC]],enderId=821,poiX=-10587,poiY=1913,wowhead=[[https://www.wowhead.com/wotlk/quest=102]],image=[[assets/images/quests/placeholder.png]],desc=[[Stormwind has abandoned us.  A foul wind of depravity rustles through the plains of Westfall.  This was my homeland and I will not turn my back on the citizens who choose to remain here.  We, the former farmers, shall make our stand. Your task, should you choose to accept, is to patrol the grasslands of Westfall.  Track down and slay the vile Gnolls that seem to be working in conjunction with the Deadmines thieves. Bring me eight Gnoll Paws and I will reward your bravery.]],logDesc=[[Bring 8 Gnoll Paws to Captain Danuvin on Sentinel Hill.]],choiceRewards={{id=1154,qty=1},{id=710,qty=1}}}
DB[103]={id=103,zoneId=40,name=[[Keeper of the Flame]],name_loc=[[Guardián de la Llama]],level=16,minLevel=10,giver=[[Captain Grayson]],giver_loc=[[Capitán Grisillo]],giverType=[[NPC]],giverId=392,ender=[[Captain Grayson]],ender_loc=[[Capitán Grisillo]],enderType=[[NPC]],enderId=392,poiX=-9974,poiY=1081,wowhead=[[https://www.wowhead.com/wotlk/quest=103]],image=[[assets/images/quests/placeholder.png]],desc=[[The night the Lighthouse Keeper's family died was horrible.  I watched, helpless, as Old Murk-Eye led the attack.  But what's done is done and now my concern is for the lives of the sailors on The Great Sea whose ships come close to the perilous rocks of the coastline.  With no one to keep watch on the flame the responsibility has fallen upon me. Help me keep the torch lit by bringing me 5 flasks of oil from the Harvest Monsters.]],logDesc=[[Bring 5 Flasks of Oil to Captain Grayson at the Westfall Lighthouse.]],rewards={{id=955,qty=1},{id=1180,qty=1}},choiceRewards={{id=2455,qty=3},{id=118,qty=3}}}
DB[104]={id=104,zoneId=40,name=[[The Coastal Menace]],name_loc=[[La amenaza costera]],level=20,minLevel=15,giver=[[Captain Grayson]],giver_loc=[[Capitán Grisillo]],giverType=[[NPC]],giverId=392,ender=[[Captain Grayson]],ender_loc=[[Capitán Grisillo]],enderType=[[NPC]],enderId=392,poiX=-11358,poiY=1812,wowhead=[[https://www.wowhead.com/wotlk/quest=104]],image=[[assets/images/quests/placeholder.png]],desc=[[When my life was ended upon the rocks, I had no clue what the afterlife held for me.  The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off.  They returned and re-lit the flame but Old Murk-Eye coerced the weaker minded murlocs to raid the Lighthouse with him once again.  The second time the family was not so lucky and before my eyes they perished helplessly. Slay Old Murk-Eye if you see him along the shore and bring me one of his scales and I shall reward you.]],logDesc=[[Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.]],choiceRewards={{id=1172,qty=1},{id=1557,qty=1},{id=5240,qty=1}}}
DB[105]={id=105,zoneId=28,name=[[Alas, Andorhal]],name_loc=[[Ah, Andorhal]],level=60,minLevel=50,giver=[[High Executor Derrington]],giver_loc=[[Sumo ejecutor Derrington]],giverType=[[NPC]],giverId=10837,ender=[[High Executor Derrington]],ender_loc=[[Sumo ejecutor Derrington]],enderType=[[NPC]],enderId=10837,prevId=5098,poiX=1761,poiY=-723,wowhead=[[https://www.wowhead.com/wotlk/quest=105]],image=[[assets/images/quests/placeholder.png]],desc=[[Alas, the time to attack Andorhal and drive out the lich that controls it is upon us! Inside the ruins of the city is where the lich - Araj the Summoner - holds dominion.  He is guarded by numerous Scourge surrounding the remains of city's center, and his personal retinue of guardians attached to him directly is formidable.  You will need numerous allies to even stand a chance of facing him successfully. Destroy Araj, $N, and bring me a shard from his phylactery as proof!]],logDesc=[[Bring Araj's Phylactery Shard to High Executor Derrington at the Bulwark, Western Plaguelands.]],rewards={{id=17759,qty=1}}}
DB[106]={id=106,zoneId=12,name=[[Young Lovers]],name_loc=[[Jóvenes enamorados]],level=6,minLevel=5,giver=[[Maybell Maclure]],giverType=[[NPC]],giverId=251,ender=[[Tommy Joe Stonefield]],ender_loc=[[Tommy Joe Pedregosa]],enderType=[[NPC]],enderId=252,rewardNextId=111,poiX=-9930,poiY=500,wowhead=[[https://www.wowhead.com/wotlk/quest=106]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, I'm cursed!  My heart belongs to Tommy Joe Stonefield, but our families are bitter enemies.  So I can't see him, even though my eyes ache to gaze upon that handsome face! Please, take this letter and give it to Tommy Joe.  He's usually at the river to the west of the Stonefield Farm, which is due west of here.]],logDesc=[[Give Maybell's Love Letter to Tommy Joe Stonefield.]]}
DB[107]={id=107,zoneId=12,name=[[Note to William]],name_loc=[[Una nota para William]],level=6,minLevel=5,giver=[[Gramma Stonefield]],giver_loc=[[Abuela Pedregosa]],giverType=[[NPC]],giverId=248,ender=[[William Pestle]],ender_loc=[[William Mortero]],enderType=[[NPC]],enderId=253,prevId=111,rewardNextId=112,poiX=-9460,poiY=32,wowhead=[[https://www.wowhead.com/wotlk/quest=107]],image=[[assets/images/quests/placeholder.png]],desc=[[I bet William Pestle has a potion to unite our two young lovers! Here, take this note to William.  He's staying at the Lion's Pride Inn in Goldshire.]],logDesc=[[Take Gramma Stonefield's Note to William Pestle.]]}
DB[109]={id=109,zoneId=12,name=[[Report to Gryan Stoutmantle]],name_loc=[[Habla con Gryan Mantorrecio]],level=10,minLevel=9,giver=[[Farmer Saldean]],giver_loc=[[Granjero Saldean]],giverType=[[NPC]],giverId=233,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,poiX=-10509,poiY=1045,wowhead=[[https://www.wowhead.com/wotlk/quest=109]],image=[[assets/images/quests/placeholder.png]],desc=[[Looks to me you've seen quite a bit of combat in your time, $c.  If you haven't already, you should report to Gryan Stoutmantle.  He heads up the People's Militia, aimed at protecting the farmlands of Westfall.  I bet he could use your help.  You can usually find him in the stone tower on Sentinel Hill, just off the road in the middle of Westfall.]],logDesc=[[Talk to Gryan Stoutmantle.  He usually can be found in the stone tower on Sentinel Hill, just off the road, in the middle of Westfall.]]}
DB[109]={id=109,zoneId=12,name=[[Report to Gryan Stoutmantle]],name_loc=[[Habla con Gryan Mantorrecio]],level=10,minLevel=9,giver=[[Farmer Furlbrow]],giver_loc=[[Granjero Saldean]],giverType=[[NPC]],giverId=237,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,poiX=-10509,poiY=1045,wowhead=[[https://www.wowhead.com/wotlk/quest=109]],image=[[assets/images/quests/placeholder.png]],desc=[[Looks to me you've seen quite a bit of combat in your time, $c.  If you haven't already, you should report to Gryan Stoutmantle.  He heads up the People's Militia, aimed at protecting the farmlands of Westfall.  I bet he could use your help.  You can usually find him in the stone tower on Sentinel Hill, just off the road in the middle of Westfall.]],logDesc=[[Talk to Gryan Stoutmantle.  He usually can be found in the stone tower on Sentinel Hill, just off the road, in the middle of Westfall.]]}
