DB[109]={id=109,zoneId=12,name=[[Report to Gryan Stoutmantle]],name_loc=[[Habla con Gryan Mantorrecio]],level=10,minLevel=9,giver=[[Deputy Rainer]],giver_loc=[[Granjero Saldean]],giverType=[[NPC]],giverId=963,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,poiX=-10509,poiY=1045,wowhead=[[https://www.wowhead.com/wotlk/quest=109]],image=[[assets/images/quests/placeholder.png]],desc=[[Looks to me you've seen quite a bit of combat in your time, $c.  If you haven't already, you should report to Gryan Stoutmantle.  He heads up the People's Militia, aimed at protecting the farmlands of Westfall.  I bet he could use your help.  You can usually find him in the stone tower on Sentinel Hill, just off the road in the middle of Westfall.]],logDesc=[[Talk to Gryan Stoutmantle.  He usually can be found in the stone tower on Sentinel Hill, just off the road, in the middle of Westfall.]]}
DB[110]={id=110,zoneId=440,name=[[Insect Part Analysis]],name_loc=[[Análisis de trozos de insecto]],level=48,minLevel=39,giver=[[Senior Surveyor Fizzledowser]],giver_loc=[[Perito jefe Picoflojo]],giverType=[[NPC]],giverId=7724,ender=[[Alchemist Pestlezugg]],ender_loc=[[Alquimista Morterozugg]],enderType=[[NPC]],enderId=5594,prevId=10,rewardNextId=113,poiX=-7115,poiY=-3730,wowhead=[[https://www.wowhead.com/wotlk/quest=110]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm going to spend some time taking a look at Scrimshank's surveying gear... as well as putting his personal effects in order.  I get the sneaking feeling behind my ears that this isn't the last loss we'll be facing against these bugs. I'd like for you to check in with Alchemist Pestlezugg to see if he has had a chance to process the insect parts we sent him.  If they're ready, bring them to me.]],logDesc=[[Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts.]]}
DB[111]={id=111,zoneId=12,name=[[Speak with Gramma]],name_loc=[[Habla con la abuelita]],level=6,minLevel=5,giver=[[Tommy Joe Stonefield]],giver_loc=[[Tommy Joe Pedregosa]],giverType=[[NPC]],giverId=252,ender=[[Gramma Stonefield]],ender_loc=[[Abuela Pedregosa]],enderType=[[NPC]],enderId=248,prevId=106,rewardNextId=107,poiX=-9881,poiY=323,wowhead=[[https://www.wowhead.com/wotlk/quest=111]],image=[[assets/images/quests/placeholder.png]],desc=[[Please, $N, talk with my Gramma.  If anyone can find a way to bring me together with Maybell, she can. She's inside our house east of here.]],logDesc=[[Speak with Gramma Stonefield.]]}
DB[112]={id=112,zoneId=12,name=[[Collecting Kelp]],name_loc=[[La Recolección de Kelp]],level=7,minLevel=5,giver=[[William Pestle]],giver_loc=[[William Mortero]],giverType=[[NPC]],giverId=253,ender=[[William Pestle]],ender_loc=[[William Mortero]],enderType=[[NPC]],enderId=253,prevId=107,nextId=114,poiX=-9518,poiY=-486,wowhead=[[https://www.wowhead.com/wotlk/quest=112]],image=[[assets/images/quests/placeholder.png]],desc=[[I can make an invisibility liquor for Maybell, so she can slip away from the Maclure Vineyards and go to Tommy Joe.  But to make the Liquor, I need some crystal kelp. Although the kelp usually grows in the ocean... sometimes murlocs collect it.  See if the murlocs near Crystal Lake have any.  Crystal Lake is just east of Goldshire.]],logDesc=[[Bring 4 Crystal Kelp Fronds to William Pestle in Goldshire.]]}
DB[113]={id=113,zoneId=440,name=[[Insect Part Analysis]],name_loc=[[Análisis de trozos de insecto]],level=48,minLevel=39,giver=[[Alchemist Pestlezugg]],giver_loc=[[Alquimista Morterozugg]],giverType=[[NPC]],giverId=5594,ender=[[Senior Surveyor Fizzledowser]],ender_loc=[[Perito jefe Picoflojo]],enderType=[[NPC]],enderId=7724,prevId=110,poiX=-7139,poiY=-3683,wowhead=[[https://www.wowhead.com/wotlk/quest=113]],image=[[assets/images/quests/placeholder.png]],desc=[[Senior Surveyor Fizzledowser needs to see this report immediately.  Actually... everyone who can read needs to see this report.  We are facing a grave and serious threat to not only Tanaris and Gadgetzan, but if left unchecked, the entirety of southern Kalimdor.  Heck, even quite possible the whole of Azeroth; this thing has given no indication it will subside. Have Fizzledowser make a duplicate of the report for you to distribute freely to your allegiance. Everyone must know about this threat!]],logDesc=[[Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan.  Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested.]]}
DB[114]={id=114,zoneId=12,name=[[The Escape]],name_loc=[[La fuga]],level=7,minLevel=5,giver=[[William Pestle]],giver_loc=[[William Mortero]],giverType=[[NPC]],giverId=253,ender=[[Maybell Maclure]],enderType=[[NPC]],enderId=251,prevId=112,poiX=-10014,poiY=38,wowhead=[[https://www.wowhead.com/wotlk/quest=114]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this invisibility liquor to young Maybell.  It should last long enough for her to visit Tommy Joe.]],logDesc=[[Take the Invisibility Liquor to Maybell Maclure.]],rewards={{id=118,qty=5}}}
DB[115]={id=115,zoneId=44,name=[[Shadow Magic]],name_loc=[[Magia de las Sombras]],level=23,minLevel=18,giver=[[Marshal Marris]],giver_loc=[[Alguacil Marris]],giverType=[[NPC]],giverId=382,ender=[[Marshal Marris]],ender_loc=[[Alguacil Marris]],enderType=[[NPC]],enderId=382,prevId=20,poiX=-9374,poiY=-3083,wowhead=[[https://www.wowhead.com/wotlk/quest=115]],image=[[assets/images/quests/placeholder.png]],desc=[[The Blackrock orcs enlisted shadowcasters to aid their attacks in Redridge, and they have brought with them devices of dark power--midnight orbs.  These orbs have struck telling blows against Redridge's defenders, and it's imperative we remove the demon-tainted items from the conflict. Find and deliver to me midnight orbs from slain Blackrock shadowcasters.  I will then have them disposed of, for this world would be a better place without them!]],logDesc=[[Bring 3 Midnight Orbs to Marshal Marris in Lakeshire.]]}
DB[116]={id=116,zoneId=44,name=[[Dry Times]],name_loc=[[Tiempos de sequía]],level=15,minLevel=12,giver=[[Barkeep Daniels]],giver_loc=[[Posadero Daniels]],giverType=[[NPC]],giverId=346,ender=[[Barkeep Daniels]],ender_loc=[[Posadero Daniels]],enderType=[[NPC]],enderId=346,poiX=-10510,poiY=-1157,wowhead=[[https://www.wowhead.com/wotlk/quest=116]],image=[[assets/images/quests/placeholder.png]],desc=[[I find myself in quite a pinch here, $N.  The bottles are close to running dry.  The latest booze shipment is long overdue.  The orc invasion has been hell. Perhaps you can go to work for me? I need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.]],logDesc=[[Barkeep Daniels of Lakeshire needs a keg of Thunderbrew Lager, a cask of Merlot, a bottle of Moonshine and a skin of Sweet Rum.]],rewards={{id=1270,qty=1},{id=10456,qty=1}}}
DB[117]={id=117,zoneId=40,name=[[Thunderbrew Lager]],name_loc=[[Cerveza Cebatruenos]],level=15,minLevel=1,giver=[[Grimbooze Thunderbrew]],giver_loc=[[Tragoamargo Cebatruenos]],giverType=[[NPC]],giverId=239,ender=[[Grimbooze Thunderbrew]],ender_loc=[[Tragoamargo Cebatruenos]],enderType=[[NPC]],enderId=239,poiX=-9974,poiY=1081,wowhead=[[https://www.wowhead.com/wotlk/quest=117]],image=[[assets/images/quests/placeholder.png]],desc=[[Hurry, my friend, move with haste  In order for our rich lager to taste  More like beer and less like stew,  Hops are needed to make the brew.]],logDesc=[[Bring Grimbooze Thunderbrew 5 hops to complete his special brew.]],rewards={{id=1262,qty=1}}}
DB[118]={id=118,zoneId=44,name=[[The Price of Shoes]],name_loc=[[El precio de unas herraduras]],level=18,minLevel=14,giver=[[Verner Osgood]],giver_loc=[[Verner Osbien]],giverType=[[NPC]],giverId=415,ender=[[Smith Argus]],ender_loc=[[Herrero Argus]],enderType=[[NPC]],enderId=514,rewardNextId=119,poiX=-9457,poiY=88,wowhead=[[https://www.wowhead.com/wotlk/quest=118]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been using so much iron keeping the Stormwind Guards outfitted, I don't have enough to supply the stable's horses with shoes! Take this note to Blacksmith Argus in Goldshire.  It explains to him my problem and requests a shipment of horseshoes.]],logDesc=[[Take Verner's Note to Smith Argus at Goldshire in Elwynn Forest.]]}
DB[119]={id=119,zoneId=44,name=[[Return to Verner]],name_loc=[[Regresa junto a Verner]],level=18,minLevel=13,giver=[[Smith Argus]],giver_loc=[[Herrero Argus]],giverType=[[NPC]],giverId=514,ender=[[Verner Osgood]],ender_loc=[[Verner Osbien]],enderType=[[NPC]],enderId=415,prevId=118,poiX=-9259,poiY=-2243,wowhead=[[https://www.wowhead.com/wotlk/quest=119]],image=[[assets/images/quests/placeholder.png]],desc=[[Ok, I'll give him his 50 horseshoes... Here they are, all boxed up and ready to go!  Tell Verner it was a pleasure doing business, and be sure he reads the note attached to this crate!]],logDesc=[[Return to Verner Osgood at Lakeshire in Redridge.  Give him the Crate of Horseshoes.]]}
DB[120]={id=120,zoneId=44,name=[[Messenger to Stormwind]],name_loc=[[Mensajero a Ventormenta]],level=14,minLevel=14,giver=[[Magistrate Solomon]],giver_loc=[[Magistrado Solomon]],giverType=[[NPC]],giverId=344,ender=[[General Marcus Jonathan]],ender_loc=[[General Marcus Jonathan]],enderType=[[NPC]],enderId=466,rewardNextId=121,poiX=-8954,poiY=521,wowhead=[[https://www.wowhead.com/wotlk/quest=120]],image=[[assets/images/quests/placeholder.png]],desc=[[These are trying times, $c.  The township is under constant siege.  Without reinforcements, we will certainly face defeat.  The message I now entrust to you is of utmost importance.  Get this report to General Marcus Jonathan of Stormwind immediately.  Once your delivery is made, return to me at once with any news, be it good or bad.  Now make haste!]],logDesc=[[Magistrate Solomon has given you a report which must be delivered to General Marcus Jonathan in Stormwind.  The judge wants you to return to him as soon as the delivery has been made.]]}
DB[121]={id=121,zoneId=44,name=[[Messenger to Stormwind]],name_loc=[[Mensajero a Ventormenta]],level=14,minLevel=14,giver=[[General Marcus Jonathan]],giver_loc=[[General Marcus Jonathan]],giverType=[[NPC]],giverId=466,ender=[[Magistrate Solomon]],ender_loc=[[Magistrado Solomon]],enderType=[[NPC]],enderId=344,prevId=120,poiX=-9219,poiY=-2222,wowhead=[[https://www.wowhead.com/wotlk/quest=121]],image=[[assets/images/quests/placeholder.png]],desc=[[While I wait for a response from the King I want you to carry this letter to Magistrate Solomon.  Dismissed, $c!]],logDesc=[[Take General Marcus Jonathan's letter of response to Magistrate Solomon in Lakeshire.]]}
DB[122]={id=122,zoneId=44,name=[[Underbelly Scales]],name_loc=[[Escamas de barriga]],level=18,minLevel=14,giver=[[Verner Osgood]],giver_loc=[[Verner Osbien]],giverType=[[NPC]],giverId=415,ender=[[Verner Osgood]],ender_loc=[[Verner Osbien]],enderType=[[NPC]],enderId=415,prevId=119,poiX=-9634,poiY=-2381,wowhead=[[https://www.wowhead.com/wotlk/quest=122]],image=[[assets/images/quests/placeholder.png]],desc=[[I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire.  If you can get 6 of them for me, then I can pay Argus with some... and have enough left to fashion something for you. Black dragon whelps are often flying around south of Lakeshire, but they like to wander.  You might have to just keep an eye out and hunt them when you see them.]],logDesc=[[Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge.]],choiceRewards={{id=6092,qty=1},{id=1302,qty=1}}}
DB[123]={id=123,zoneId=12,name=[[The Collector]],name_loc=[[El Coleccionista]],level=10,minLevel=7,giverType=[[NPC]],ender=[[Marshal Dughan]],ender_loc=[[Alguacil Dughan]],enderType=[[NPC]],enderId=240,poiX=-9466,poiY=74,wowhead=[[https://www.wowhead.com/wotlk/quest=123]],image=[[assets/images/quests/placeholder.png]],desc=[[This note is a schedule with a list of days and times when a person -- described only as "The Collector" -- will receive a shipment of gold from the mines in Elwynn Forest. From the schedule, it looks as if the Collector resides near the Brackwell Pumpkin Patch in eastern Elwynn. This sounds important.  You should report it to Marshal Dughan in Goldshire.]],logDesc=[[Go to Marshal Dughan in Goldshire and give him The Collector's Schedule.]]}
DB[124]={id=124,zoneId=44,name=[[A Baying of Gnolls]],name_loc=[[El aullido de los gnolls]],level=20,minLevel=15,giver=[[Verner Osgood]],giver_loc=[[Verner Osbien]],giverType=[[NPC]],giverId=415,ender=[[Verner Osgood]],ender_loc=[[Verner Osbien]],enderType=[[NPC]],enderId=415,prevId=119,rewardNextId=126,poiX=-9123,poiY=-2089,wowhead=[[https://www.wowhead.com/wotlk/quest=124]],image=[[assets/images/quests/placeholder.png]],desc=[[As if the attacking orcs weren't enough!  Now I have gnoll brutes and mystics prowling along the ridge north of my stable, taking my horses when they stray... If you can get rid of those gnolls, my horses and I would be very grateful.]],logDesc=[[Kill 10 Redridge Brutes and 8 Redridge Mystics, then return to Verner Osgood.]]}
DB[125]={id=125,zoneId=44,name=[[The Lost Tools]],name_loc=[[Las herramientas perdidas]],level=16,minLevel=15,giver=[[Foreman Oslow]],giver_loc=[[Supervisor Olento]],giverType=[[NPC]],giverId=341,ender=[[Foreman Oslow]],ender_loc=[[Supervisor Olento]],enderType=[[NPC]],enderId=341,poiX=-9366,poiY=-2472,wowhead=[[https://www.wowhead.com/wotlk/quest=125]],image=[[assets/images/quests/placeholder.png]],desc=[[I could really use a hand here, $N.  With the town under siege, it's been hard to get supplies.  My tools were being delivered from Goldshire by wagon but the bridge was blown out.  We put the tools in a boat but the orcs hit it with a catapult.  Just my luck, my toolbox sank right to the bottom of the lake. Retrieve my toolbox, $N, and I'll make it worth your while.]],logDesc=[[Foreman Oslow of Lakeshire wants you to retrieve his toolbox from the bottom of Lake Everstill.]],rewards={{id=2313,qty=2}}}
DB[126]={id=126,zoneId=44,name=[[Howling in the Hills]],name_loc=[[El aullido de las colinas]],level=21,minLevel=15,giver=[[Verner Osgood]],giver_loc=[[Verner Osbien]],giverType=[[NPC]],giverId=415,ender=[[Verner Osgood]],ender_loc=[[Verner Osbien]],enderType=[[NPC]],enderId=415,prevId=124,poiX=-8893,poiY=-2172,wowhead=[[https://www.wowhead.com/wotlk/quest=126]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, the gnolls are still out there.  I can hear their baying as they hunt in the hills above Lakeshire.  And one cry is louder than the rest - Yowler,  their leader. Kill Yowler and send his pack scattering!  Bring me his paw as proof. And be careful, this gnoll is their leader for a reason.  He is no Mongrel...]],logDesc=[[Bring Yowler's Paw to Verner Osgood in Lakeshire.]],choiceRewards={{id=1319,qty=1},{id=2910,qty=1}}}
DB[127]={id=127,zoneId=44,name=[[Selling Fish]],name_loc=[[Pescado a la venta]],level=21,minLevel=16,giver=[[Dockmaster Baren]],giver_loc=[[Maestro de embarcadero Baren]],giverType=[[NPC]],giverId=381,ender=[[Dockmaster Baren]],ender_loc=[[Maestro de embarcadero Baren]],enderType=[[NPC]],enderId=381,poiX=-9350,poiY=-2845,wowhead=[[https://www.wowhead.com/wotlk/quest=127]],image=[[assets/images/quests/placeholder.png]],desc=[[Lake Everstill is famous for its spotted sunfish.  There's always demand for them...and I'm running low! Bring me a batch of 10 and I'll barter well for them.  If you can't fish yourself, then...maybe you can get them off the murlocs!]],logDesc=[[Bring 10 Spotted Sunfish to Dockmaster Baren in Lakeshire.]],rewards={{id=3663,qty=1},{id=3680,qty=1},{id=1322,qty=5}}}
DB[128]={id=128,zoneId=44,name=[[Blackrock Bounty]],name_loc=[[La recompensa de Roca Negra]],level=25,minLevel=20,giver=[[Guard Howe]],giver_loc=[[Guardia Howe]],giverType=[[NPC]],giverId=903,ender=[[Guard Howe]],ender_loc=[[Guardia Howe]],enderType=[[NPC]],enderId=903,poiX=-8731,poiY=-2350,wowhead=[[https://www.wowhead.com/wotlk/quest=128]],image=[[assets/images/quests/placeholder.png]],desc=[[The Blackrock Clan must be destroyed. The Enemy has invaded our lands. These mountains fall under the sovereign right of the King of Stormwind. Our sources tell us that the leaders of each unit within the Clan are known as Champions. You'll find them in their encampment to the north, just west of the road to the Burning Steppes. Magistrate Solomon wants these foul brutes dead. Slay 15 Blackrock Champions and return to me.]],logDesc=[[Kill 15 Blackrock Champions and Guard Howe in Lakeshire will reward you.]]}
DB[129]={id=129,zoneId=44,name=[[A Free Lunch]],name_loc=[[Una comida gratis]],level=15,minLevel=12,giver=[[Darcy]],giver_loc=[[Darcy Parker]],giverType=[[NPC]],giverId=379,ender=[[Guard Parker]],ender_loc=[[Guardia Parker]],enderType=[[NPC]],enderId=464,rewardNextId=130,poiX=-9611,poiY=-1904,wowhead=[[https://www.wowhead.com/wotlk/quest=129]],image=[[assets/images/quests/placeholder.png]],desc=[[Can you do me a favor?  I've prepared a lunch for Guard Parker, but he's out on patrol...he's a big, strong Stormwind guard who can defend himself, but it's much too dangerous out there for a townsperson like me. So if you deliver his lunch for me, then come back here and I'll give you a free lunch!  Parker patrols the stretch of road leading to Duskwood.]],logDesc=[[Bring Parker's lunch to Guard Parker.  He patrols the road leading to Darkshire.]]}
DB[130]={id=130,zoneId=44,name=[[Visit the Herbalist]],name_loc=[[Una visita al herborista]],level=15,minLevel=12,giver=[[Guard Parker]],giver_loc=[[Guardia Parker]],giverType=[[NPC]],giverId=464,ender=[[Martie Jainrose]],enderType=[[NPC]],enderId=342,prevId=129,rewardNextId=131,poiX=-9246,poiY=-2045,wowhead=[[https://www.wowhead.com/wotlk/quest=130]],image=[[assets/images/quests/placeholder.png]],desc=[[Before you go back to Darcy, can you bring her some flowers for me?  You can get them at the herbalist shop back in Lakeshire, at the west end of town. But when you get the flowers...don't tell the herbalist, Martie, whom they're from, or whom they're for...]],logDesc=[[Speak with the Redridge Herbalist, Martie Jainrose.]]}
DB[131]={id=131,zoneId=44,name=[[Delivering Daffodils]],name_loc=[[Un ramo de narcisos]],level=15,minLevel=12,giver=[[Martie Jainrose]],giverType=[[NPC]],giverId=342,ender=[[Darcy]],ender_loc=[[Darcy Parker]],enderType=[[NPC]],enderId=379,prevId=130,poiX=-9224,poiY=-2155,wowhead=[[https://www.wowhead.com/wotlk/quest=131]],image=[[assets/images/quests/placeholder.png]],desc=[[Here is your bouquet.  I chose Daffodils for you.  They're my favorite!]],logDesc=[[Give Darcy the Daffodil Bouquet.]],rewards={{id=1326,qty=10}}}
DB[132]={id=132,zoneId=40,name=[[The Defias Brotherhood]],name_loc=[[La hermandad de los Defias]],level=18,minLevel=14,giver=[[Wiley the Black]],giver_loc=[[Wiley el Negro]],giverType=[[NPC]],giverId=266,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,prevId=65,rewardNextId=135,poiX=-10509,poiY=1045,wowhead=[[https://www.wowhead.com/wotlk/quest=132]],image=[[assets/images/quests/placeholder.png]],desc=[[What I am about to tell you could cost me my life.  The Defias gang is up to something big.  Last I heard they were working in conjunction with various gnolls, kobolds and even goblins. Take this note to Stoutmantle.  It explains as much as I know on the subject.]],logDesc=[[Take Wiley's Note to Gryan Stoutmantle in Westfall.]]}
DB[133]={id=133,zoneId=10,name=[[Ghoulish Effigy]],name_loc=[[Un espantapájaros para necrófagos]],level=27,minLevel=20,giver=[[Abercrombie]],giver_loc=[[Abercrombie]],giverType=[[NPC]],giverId=289,ender=[[Abercrombie]],ender_loc=[[Abercrombie]],enderType=[[NPC]],enderId=289,prevId=159,rewardNextId=134,poiX=-10332,poiY=108,wowhead=[[https://www.wowhead.com/wotlk/quest=133]],image=[[assets/images/quests/placeholder.png]],desc=[[I live so far from the protection of town, it's a wonder the ghouls and the walking dead haven't eaten me!  In fact, just yesterday a pack of Bone Chewers was pounding on the walls of my house! I want to make an effigy - a kind of "scarecrow" for Ghouls.  To do that I need some Ghoul Ribs.  You can get them from Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones and Plague Spreaders. Get the ribs for me, and I will repay you with some coin.]],logDesc=[[Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack.]]}
DB[134]={id=134,zoneId=10,name=[[Ogre Thieves]],name_loc=[[Ladrones ogros]],level=30,minLevel=20,giver=[[Abercrombie]],giver_loc=[[Abercrombie]],giverType=[[NPC]],giverId=289,ender=[[Abercrombie]],ender_loc=[[Abercrombie]],enderType=[[NPC]],enderId=289,prevId=133,rewardNextId=160,poiX=-11091,poiY=-69,wowhead=[[https://www.wowhead.com/wotlk/quest=134]],image=[[assets/images/quests/placeholder.png]],desc=[[A few weeks ago I was picking herbs far from my house, and a band of ogres attacked me!  I ran, and I was forced to leave behind a crate of precious tools and herbs. After they chased me off, the ogres swaggered back to the ogre mound in southern Duskwood.  I'm sure my crate is somewhere near the mound. Please, $N, retrieve this crate for me for I miss it sorely.]],logDesc=[[Return Abercrombie's Crate to Abercrombie.]]}
DB[135]={id=135,zoneId=40,name=[[The Defias Brotherhood]],name_loc=[[La hermandad de los Defias]],level=18,minLevel=14,giver=[[Gryan Stoutmantle]],giver_loc=[[Gryan Mantorrecio]],giverType=[[NPC]],giverId=234,ender=[[Master Mathias Shaw]],ender_loc=[[Maestro Mathias Shaw]],enderType=[[NPC]],enderId=332,prevId=132,rewardNextId=141,poiX=-8815,poiY=362,wowhead=[[https://www.wowhead.com/wotlk/quest=135]],image=[[assets/images/quests/placeholder.png]],desc=[[I wonder what Wiley meant when he mentioned the Stonemasons.  Perhaps that was a slip of tongue.  Could the Defias gang be related to the Stonemasons?  Only one man would know for sure:  Mathias Shaw, head of SI:7. Show him Wiley's Note and see if he has anything to add to this growing mystery. If you have trouble finding Shaw, check the Barracks in Old Town.]],logDesc=[[Take Wiley's Note to Mathias Shaw in Stormwind.]]}
DB[136]={id=136,zoneId=40,name=[[Captain Sanders' Hidden Treasure]],name_loc=[[El tesoro escondido del capitán Sanders]],level=16,minLevel=10,giverType=[[NPC]],ender=[[Captain's Footlocker]],ender_loc=[[Baúl del Capitán]],enderType=[[GO]],enderId=35,rewardNextId=138,poiX=-10514,poiY=2110,wowhead=[[https://www.wowhead.com/wotlk/quest=136]],image=[[assets/images/quests/placeholder.png]],desc=[[If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave.  So my treasure is yours now, ye jest need to follow the clues.  First ye need to find me footlocker.  It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck.  There be lots of shipwrecks but only one rusty anchor on the coast.  Find that anchor and you'll find me locker!  Look in there for the next clue.]],logDesc=[[Find Captain Sanders' footlocker and search it for the next clue.]]}
DB[138]={id=138,zoneId=40,name=[[Captain Sanders' Hidden Treasure]],name_loc=[[El tesoro escondido del capitán Sanders]],level=16,minLevel=10,giver=[[Captain's Footlocker]],giver_loc=[[Baúl del Capitán]],giverType=[[GO]],giverId=35,ender=[[Broken Barrel]],ender_loc=[[Barrica rota]],enderType=[[GO]],enderId=36,prevId=136,rewardNextId=139,poiX=-10515,poiY=1599,wowhead=[[https://www.wowhead.com/wotlk/quest=138]],image=[[assets/images/quests/placeholder.png]],desc=[[The clue to the treasure reads: Good work, matey!  Now ye need to head due east.  East up the bluffs, east to the road.  Look for the ol' chimney ruins near the side of the road.  There you'll find an old barrel with your next clue.]],logDesc=[[Find the old barrel near the ruined chimney and search it for your next clue.]]}
DB[139]={id=139,zoneId=40,name=[[Captain Sanders' Hidden Treasure]],name_loc=[[El tesoro escondido del capitán Sanders]],level=16,minLevel=10,giver=[[Broken Barrel]],giver_loc=[[Barrica rota]],giverType=[[GO]],giverId=36,ender=[[Old Jug]],ender_loc=[[Vieja jarra]],enderType=[[GO]],enderId=34,prevId=138,rewardNextId=140,poiX=-9797,poiY=1595,wowhead=[[https://www.wowhead.com/wotlk/quest=139]],image=[[assets/images/quests/placeholder.png]],desc=[[Searching through the barrel you discover another piece of parchment.  This one reads:  Now from this here barrel, face ye North.  Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs.  If ye poke around that jug, ye just might find what you're lookin' for.]],logDesc=[[Search the empty jug next to the windmill for the next clue.]]}
DB[140]={id=140,zoneId=40,name=[[Captain Sanders' Hidden Treasure]],name_loc=[[El tesoro escondido del capitán Sanders]],level=16,minLevel=10,giver=[[Old Jug]],giver_loc=[[Vieja jarra]],giverType=[[GO]],giverId=34,ender=[[Locked Chest]],ender_loc=[[Cofre cerrado]],enderType=[[GO]],enderId=33,prevId=139,poiX=-9794,poiY=2108,wowhead=[[https://www.wowhead.com/wotlk/quest=140]],image=[[assets/images/quests/placeholder.png]],desc=[[Sure enough, deep within the Old Jug there is another clue to Sanders' treasure.  The ink has run in some places and the paper smells like whiskey but you can make out some of the text:  Now that ye found me ol' whiskey jug, you're almost to the treasure!  Just face West from the bottle and walk down to the shore.  Once ye get to the water, keep going!  Swim straight west till you find the island with me treasure chest!]],logDesc=[[Locate Captain Sanders' chest and open it for your reward.]],rewards={{id=2842,qty=1},{id=3342,qty=1},{id=3344,qty=1},{id=3343,qty=1}}}
DB[141]={id=141,zoneId=40,name=[[The Defias Brotherhood]],name_loc=[[La hermandad de los Defias]],level=18,minLevel=14,giver=[[Master Mathias Shaw]],giver_loc=[[Maestro Mathias Shaw]],giverType=[[NPC]],giverId=332,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,prevId=135,rewardNextId=142,poiX=-10509,poiY=1045,wowhead=[[https://www.wowhead.com/wotlk/quest=141]],image=[[assets/images/quests/placeholder.png]],desc=[[The Stonemasons' Guild was run by a man named Edwin VanCleef.  VanCleef was responsible for rebuilding Stormwind after the orcs razed it in the First War.  Apparently, VanCleef and his men were unhappy with their treatment by the King after the reconstruction was complete.  That just might explain a thing or two. I have written a more detailed account for your Master in Westfall.  Take this to him at once!]],logDesc=[[Take Shaw's report to Gryan Stoutmantle in Westfall.]]}
DB[142]={id=142,zoneId=40,name=[[The Defias Brotherhood]],name_loc=[[La hermandad de los Defias]],level=18,minLevel=14,giver=[[Gryan Stoutmantle]],giver_loc=[[Gryan Mantorrecio]],giverType=[[NPC]],giverId=234,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,prevId=141,poiX=-11025,poiY=1460,wowhead=[[https://www.wowhead.com/wotlk/quest=142]],image=[[assets/images/quests/placeholder.png]],desc=[[We need to discover the location of the Defias hideout.  $N, my scout reports that a Defias Messenger has been seen on the roads between Moonbrook, the Gold Coast Quarry and the Jangolode Mine.  I want you to capture him.  If he resists, kill him and bring me whatever he is carrying.]],logDesc=[[Track down the Defias Messenger in Westfall and bring his message to Stoutmantle.]]}
DB[143]={id=143,zoneId=44,name=[[Messenger to Westfall]],name_loc=[[Mensajero a los Páramos de Poniente]],level=14,minLevel=14,giver=[[Magistrate Solomon]],giver_loc=[[Magistrado Solomon]],giverType=[[NPC]],giverId=344,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,prevId=121,rewardNextId=144,poiX=-10509,poiY=1045,wowhead=[[https://www.wowhead.com/wotlk/quest=143]],image=[[assets/images/quests/placeholder.png]],desc=[[Something odd is afoot with the Stormwind Army.  They should have been here in force by now.  Time is a luxury we don't have, however.  I will not stand by and watch the people of Lakeshire give their lives without trying to enlist more help.  I've heard word of a people's militia forming in Westfall. Take this plea to their leader, Gryan Stoutmantle.  Perhaps Stoutmantle's men can lend some support here until the King sends reserves.]],logDesc=[[Magistrate Solomon wants you to take his written plea to Gryan Stoutmantle in Westfall.]]}
DB[144]={id=144,zoneId=44,name=[[Messenger to Westfall]],name_loc=[[Mensajero a los Páramos de Poniente]],level=14,minLevel=14,giver=[[Gryan Stoutmantle]],giver_loc=[[Gryan Mantorrecio]],giverType=[[NPC]],giverId=234,ender=[[Magistrate Solomon]],ender_loc=[[Magistrado Solomon]],enderType=[[NPC]],enderId=344,prevId=143,poiX=-9219,poiY=-2222,wowhead=[[https://www.wowhead.com/wotlk/quest=144]],image=[[assets/images/quests/placeholder.png]],desc=[[Magistrate Solomon's note pains me to read.  But it is obvious he knows not the war which is waged in Westfall or else he would know better than to expect aid from the Militia.  If Stormwind had not deserted us as well, we would not have the need for the Militia. Take this response to your master in Redridge, $c.  And let him know that my heart is heavy with the loss of good men.]],logDesc=[[Return to Magistrate Solomon with Gryan Stoutmantle's response.]]}
DB[145]={id=145,zoneId=44,name=[[Messenger to Darkshire]],name_loc=[[Mensajero a Villa Oscura]],level=18,minLevel=18,giver=[[Magistrate Solomon]],giver_loc=[[Magistrado Solomon]],giverType=[[NPC]],giverId=344,ender=[[Lord Ello Ebonlocke]],ender_loc=[[Lord Ello Cerranegro]],enderType=[[NPC]],enderId=263,prevId=144,rewardNextId=146,poiX=-10552,poiY=-1109,wowhead=[[https://www.wowhead.com/wotlk/quest=145]],image=[[assets/images/quests/placeholder.png]],desc=[[I require your assistance once again.  I have written to Lord Ebonlocke, requesting that he sends his trained guards, the Night Watch, to help with Lakeshire's defense.  It is imperative this message makes it to him swiftly.  You must exercise extreme caution.  Ebonlocke is the mayor of Darkshire, in the heart of Duskwood.  Do not stray from the roads.]],logDesc=[[Magistrate Solomon wants you to take a letter to Lord Ebonlocke in Darkshire.]]}
DB[146]={id=146,zoneId=44,name=[[Messenger to Darkshire]],name_loc=[[Mensajero a Villa Oscura]],level=18,minLevel=18,giver=[[Lord Ello Ebonlocke]],giver_loc=[[Lord Ello Cerranegro]],giverType=[[NPC]],giverId=263,ender=[[Magistrate Solomon]],ender_loc=[[Magistrado Solomon]],enderType=[[NPC]],enderId=344,prevId=145,poiX=-9219,poiY=-2222,wowhead=[[https://www.wowhead.com/wotlk/quest=146]],image=[[assets/images/quests/placeholder.png]],desc=[[If I did not know Magistrate Solomon personally, I would say the man has gone mad.  Send the Night Watch to Lakeshire because Stormwind refuses aid?  The Night Watch was formed because Stormwind left us when this foul magic seeped into the land.  If I sent my Night Watch, this town would be overrun by evil before the guards even reached the forest's edge. Take this letter of response to your Master in Lakeshire.]],logDesc=[[Return to Magistrate Solomon with Lord Ebonlocke's letter of response.]]}
DB[147]={id=147,zoneId=12,name=[[Manhunt]],name_loc=[[La persecución]],level=10,minLevel=7,giver=[[Marshal Dughan]],giver_loc=[[Alguacil Dughan]],giverType=[[NPC]],giverId=240,ender=[[Marshal Dughan]],ender_loc=[[Alguacil Dughan]],enderType=[[NPC]],enderId=240,prevId=123,poiX=-9806,poiY=-932,wowhead=[[https://www.wowhead.com/wotlk/quest=147]],image=[[assets/images/quests/placeholder.png]],desc=[[If the "Collector" is taking gold from our mines then he's stealing from the kingdom!  Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me.  It may tell us whom the Collector is working for... That Pickup Schedule says the Collector is hiding out at the Brackwell Pumpkin Patch.  You should search for him there.]],logDesc=[[Find and kill "the Collector"  then return to Marshal Dughan with The Collector's Ring.]],choiceRewards={{id=1360,qty=1},{id=1183,qty=1}}}
DB[148]={id=148,zoneId=10,name=[[Supplies from Darkshire]],name_loc=[[Suministros de Villa Oscura]],level=24,minLevel=20,giver=[[Abercrombie]],giver_loc=[[Abercrombie]],giverType=[[NPC]],giverId=289,ender=[[Madame Eva]],ender_loc=[[Lady Eva]],enderType=[[NPC]],enderId=265,prevId=165,rewardNextId=149,poiX=-10532,poiY=-1213,wowhead=[[https://www.wowhead.com/wotlk/quest=148]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip. Can you go to Darkshire and bring me back some Ghost Hair Thread?  You can get it from Madame Eva at her home on the Darkshire square.]],logDesc=[[Speak with Madame Eva.]]}
DB[149]={id=149,zoneId=10,name=[[Ghost Hair Thread]],name_loc=[[Hilo de cabello de fantasma]],level=24,minLevel=20,giver=[[Madame Eva]],giver_loc=[[Lady Eva]],giverType=[[NPC]],giverId=265,ender=[[Blind Mary]],ender_loc=[[Mary la Ciega]],enderType=[[NPC]],enderId=302,prevId=148,rewardNextId=154,poiX=-10786,poiY=-1381,wowhead=[[https://www.wowhead.com/wotlk/quest=149]],image=[[assets/images/quests/placeholder.png]],desc=[[There is a poor, sad spirit, Blind Mary, who haunts an old farm house in the hills south of Darkshire. Here, take this Spectral Comb and ask Blind Mary to comb her hair.  Then bring back the comb and I will glean from it the Ghost Hair I'll need for the thread. And take care, for dark things now lurk near that house...]],logDesc=[[Bring the Spectral Comb to Blind Mary.]]}
DB[150]={id=150,zoneId=44,name=[[Murloc Poachers]],name_loc=[[Cazadores furtivos]],level=20,minLevel=20,giver=[[Dockmaster Baren]],giver_loc=[[Maestro de embarcadero Baren]],giverType=[[NPC]],giverId=381,ender=[[Dockmaster Baren]],ender_loc=[[Maestro de embarcadero Baren]],enderType=[[NPC]],enderId=381,poiX=-9350,poiY=-2845,wowhead=[[https://www.wowhead.com/wotlk/quest=150]],image=[[assets/images/quests/placeholder.png]],desc=[[Murlocs are becoming a problem.  Larger groups of the fishmen are dropping anchor along the shores of Lake Everstill and fishing up a storm!  We need them gone before they eat all the fish in the lake! Hunt murlocs!  Bring me eight of their fins and I might have something for you...]],logDesc=[[Bring 8 Murloc Fins to Dockmaster Baren in Lakeshire.]],rewards={{id=3567,qty=1}}}
DB[151]={id=151,zoneId=40,name=[[Poor Old Blanchy]],name_loc=[[La pobre y vieja Blanchy]],level=14,minLevel=9,giver=[[Verna Furlbrow]],giver_loc=[[Verna Cejade]],giverType=[[NPC]],giverId=238,ender=[[Verna Furlbrow]],ender_loc=[[Verna Cejade]],enderType=[[NPC]],enderId=238,poiX=-10164,poiY=1324,wowhead=[[https://www.wowhead.com/wotlk/quest=151]],image=[[assets/images/quests/placeholder.png]],desc=[[Poor Old Blanchy!  Such a tired beast after all the work we put her through. I fed her before we left the farm, but we weren't expecting the wagon to break on us. If you could bring her a few handfuls of oats from the fields, I'd be grateful. I bet you could find some around all of the farms in Westfall, if you can steer clear of those horrific machines that have taken over. There are several farms southwest of here.]],logDesc=[[Verna Furlbrow in Westfall wants you to bring her 8 Handfuls of Oats.]],rewards={{id=2165,qty=1},{id=1537,qty=1}}}
DB[152]={id=152,zoneId=40,name=[[The Coast Isn't Clear]],name_loc=[[Hay moros en la costa]],level=19,minLevel=10,giver=[[Captain Grayson]],giver_loc=[[Capitán Grisillo]],giverType=[[NPC]],giverId=392,ender=[[Captain Grayson]],ender_loc=[[Capitán Grisillo]],enderType=[[NPC]],enderId=392,poiX=-9595,poiY=1424,wowhead=[[https://www.wowhead.com/wotlk/quest=152]],image=[[assets/images/quests/placeholder.png]],desc=[[You probably noticed all of the shipwrecks along the coast.  The Great Sea is treacherous indeed.  The coast of Westfall needs to be kept clear, so that if sailors find their way to our beaches, they are safe.  The Murlocs are trouble though. Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and I will see to it that you are rewarded.]],logDesc=[[Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and return to Captain Grayson at the Westfall Lighthouse.]]}
DB[153]={id=153,zoneId=40,name=[[Red Leather Bandanas]],name_loc=[[Pañuelos rojos de cuero]],level=15,minLevel=10,giver=[[Scout Galiaan]],giver_loc=[[Explorador Galiaan]],giverType=[[NPC]],giverId=878,ender=[[Scout Galiaan]],ender_loc=[[Explorador Galiaan]],enderType=[[NPC]],enderId=878,poiX=-10278,poiY=1345,wowhead=[[https://www.wowhead.com/wotlk/quest=153]],image=[[assets/images/quests/placeholder.png]],desc=[[The Defias Front is constantly shifting.  I've been following their movements for quite some time now.  On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear. Bring me 15 of these Bandanas and I'll see to it you are rewarded.]],logDesc=[[Bring 15 Red Leather Bandanas to Scout Galiaan at Sentinel Hill.]],choiceRewards={{id=3511,qty=1},{id=5944,qty=1},{id=12295,qty=1}}}
DB[154]={id=154,zoneId=10,name=[[Return the Comb]],name_loc=[[Devuelve el peine]],level=24,minLevel=20,giver=[[Blind Mary]],giver_loc=[[Mary la Ciega]],giverType=[[NPC]],giverId=302,ender=[[Madame Eva]],ender_loc=[[Lady Eva]],enderType=[[NPC]],enderId=265,prevId=149,rewardNextId=157,poiX=-10532,poiY=-1213,wowhead=[[https://www.wowhead.com/wotlk/quest=154]],image=[[assets/images/quests/placeholder.png]],desc=[[NO!!!!! Take it, take this comb away from me! I'm a monster, and no one will ever think me lovely again!]],logDesc=[[Return the Ghost Hair Comb to Madame Eva in Darkshire.]]}
DB[155]={id=155,zoneId=40,name=[[The Defias Brotherhood]],name_loc=[[La hermandad de los Defias]],level=18,minLevel=14,giver=[[The Defias Traitor]],giver_loc=[[El Traidor de los Defias]],giverType=[[NPC]],giverId=467,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,prevId=142,rewardNextId=166,poiX=-10509,poiY=1045,wowhead=[[https://www.wowhead.com/wotlk/quest=155]],image=[[assets/images/quests/placeholder.png]],desc=[[So Stoutmantle sends a scrawny $r like you to protect me?  Guess you'll have to do.  Better bring some friends too.  You know the deal, right?  You watch my back and I'll take you to the Defias hideout.  But you better be close by my side.  The Defias gang wants my head now.  If they see me with you, they'll try to kill me. Let me know when you and any friends you can round up are ready to go.]],logDesc=[[Escort the Defias Traitor to the secret hideout of the Defias Brotherhood.  Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information.]]}
DB[156]={id=156,zoneId=10,name=[[Gather Rot Blossoms]],name_loc=[[Busca flores podridas]],level=24,minLevel=20,giver=[[Tavernkeep Smitts]],giver_loc=[[Tabernero Smitts]],giverType=[[NPC]],giverId=273,ender=[[Tavernkeep Smitts]],ender_loc=[[Tabernero Smitts]],enderType=[[NPC]],enderId=273,prevId=158,rewardNextId=159,poiX=-10565,poiY=355,wowhead=[[https://www.wowhead.com/wotlk/quest=156]],image=[[assets/images/quests/placeholder.png]],desc=[[If you bring me some rot blossoms then I can brew you up a batch of zombie juice. Rot blossoms grow in strange places.  In particular, I hear you can find them inside the skulls of Skeletal Horrors and Skeletal Fiends... not that I've gotten close enough to look! The Raven Hill Cemetery is lousy with those skeletons.  You may as well get rid of them while you're looking for rot blossoms.  The town of Darkshire would be grateful.]],logDesc=[[Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire.]]}
DB[157]={id=157,zoneId=10,name=[[Deliver the Thread]],name_loc=[[Devolver el pelo]],level=24,minLevel=20,giver=[[Madame Eva]],giver_loc=[[Lady Eva]],giverType=[[NPC]],giverId=265,ender=[[Abercrombie]],ender_loc=[[Abercrombie]],enderType=[[NPC]],enderId=289,prevId=154,rewardNextId=158,poiX=-10283,poiY=74,wowhead=[[https://www.wowhead.com/wotlk/quest=157]],image=[[assets/images/quests/placeholder.png]],desc=[[Here is your thread, $N.  It has a thousand uses, from binding evil spirits to sewing life into inanimate objects.]],logDesc=[[Bring the Ghost Hair Thread to Abercrombie, in his shack north of the Raven Hill Cemetery.]]}
DB[158]={id=158,zoneId=10,name=[[Zombie Juice]],name_loc=[[Zumo de zombi]],level=24,minLevel=20,giver=[[Abercrombie]],giver_loc=[[Abercrombie]],giverType=[[NPC]],giverId=289,ender=[[Tavernkeep Smitts]],ender_loc=[[Tabernero Smitts]],enderType=[[NPC]],enderId=273,prevId=157,rewardNextId=156,poiX=-10517,poiY=-1159,wowhead=[[https://www.wowhead.com/wotlk/quest=158]],image=[[assets/images/quests/placeholder.png]],desc=[[I need a bottle of a certain liquor - Zombie Juice.  Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some. And please hurry, $N.  These nights get cold, and I need that drink to put fire in my veins again!]],logDesc=[[Speak with Tavernkeep Smitts.]]}
DB[159]={id=159,zoneId=10,name=[[Juice Delivery]],name_loc=[[Entrega de zumo]],level=24,minLevel=20,giver=[[Tavernkeep Smitts]],giver_loc=[[Tabernero Smitts]],giverType=[[NPC]],giverId=273,ender=[[Abercrombie]],ender_loc=[[Abercrombie]],enderType=[[NPC]],enderId=289,prevId=156,rewardNextId=133,poiX=-10283,poiY=74,wowhead=[[https://www.wowhead.com/wotlk/quest=159]],image=[[assets/images/quests/placeholder.png]],desc=[[Here's your Zombie Juice... ...and be careful with this stuff.  It's strong enough to raise the dead!]],logDesc=[[Bring the Zombie Juice to Abercrombie at his shack.]]}
DB[160]={id=160,zoneId=10,name=[[Note to the Mayor]],name_loc=[[Nota para el alcalde]],level=30,minLevel=20,giver=[[Abercrombie]],giver_loc=[[Abercrombie]],giverType=[[NPC]],giverId=289,ender=[[Lord Ello Ebonlocke]],ender_loc=[[Lord Ello Cerranegro]],enderType=[[NPC]],enderId=263,prevId=134,rewardNextId=251,poiX=-10552,poiY=-1109,wowhead=[[https://www.wowhead.com/wotlk/quest=160]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this note to Ello Ebonlocke, the Mayor of Darkshire. He and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!]],logDesc=[[Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.]]}
DB[161]={id=161,zoneId=38,name=[[A Dark Threat Looms]],name_loc=[[Se aproxima una oscura amenaza]],level=18,minLevel=16,giver=[[Chief Engineer Hinderweir VII]],giver_loc=[[Ingeniero jefe Hinderweir VII]],giverType=[[NPC]],giverId=1093,ender=[[Ashlan Stonesmirk]],ender_loc=[[Ashlan Risapétrea]],enderType=[[NPC]],enderId=1073,prevId=199,rewardNextId=274,poiX=-2649,poiY=-2459,wowhead=[[https://www.wowhead.com/wotlk/quest=161]],image=[[assets/images/quests/placeholder.png]],desc=[[If my suspicions are correct, this is some type of explosive powder.  This must be analyzed by an explosives expert so we know just what we're dealing with here.  Ashlan Stonesmirk was assigned to the regiment guarding Dun Modr and the Thandol Span.  I need you to make a grave and perilous journey, $N. Travel through the Algaz Gate, follow the road through the Wetlands and seek out Stonesmirk in Dun Modr.  Heed my advice: stick to the roads and stop for nothing!]],logDesc=[[Chief Engineer Hinderweir wants you to take the strange smelling powder to Ashlan Stonesmirk, the explosives expert at Dun Modr in the Wetlands.]]}
DB[162]={id=162,zoneId=440,name=[[Rise of the Silithid]],name_loc=[[La sublevación de los silítidos]],level=49,minLevel=39,giver=[[Senior Surveyor Fizzledowser]],giver_loc=[[Perito jefe Picoflojo]],giverType=[[NPC]],giverId=7724,ender=[[Gracina Spiritmight]],ender_loc=[[Gracina Poderespíritu]],enderType=[[NPC]],enderId=7740,prevId=113,nextId=4493,poiX=9634,poiY=2496,wowhead=[[https://www.wowhead.com/wotlk/quest=162]],image=[[assets/images/quests/placeholder.png]],desc=[[I urge you to take this report to someone who has working knowledge in this kind of thing. I know this night elf scholar named Gracina Spiritmight.  She's spent a lot of time studying life forms that are unique to the ecology of Azeroth; she's a historian to boot!  If you want someone to help figure out what exactly this threat is, and more importantly how to stop it, give her the report.  We'll need the help. Last I heard, she was residing in the Temple of the Moon, located in Darnassus.]],logDesc=[[Take the Insect Analysis Report to Gracina Spiritmight in Darnassus.]]}
DB[163]={id=163,zoneId=10,name=[[Raven Hill]],name_loc=[[Cerro del Cuervo]],level=20,minLevel=17,giver=[[Elaine Carevin]],giverType=[[NPC]],giverId=633,ender=[[Jitters]],ender_loc=[[Alterio]],enderType=[[NPC]],enderId=288,poiX=-10732,poiY=337,wowhead=[[https://www.wowhead.com/wotlk/quest=163]],image=[[assets/images/quests/placeholder.png]],desc=[[Something's amiss at Raven Hill, $n. Calor swears that someone--or something--is haunting the buildings there. Two nights running he's noticed the shadows moving, and the third before that he says he saw light in one of the windows. If, as you say, you care about the safety of Duskwood, find out what monster haunts in Raven Hill.]],logDesc=[[Find out what is haunting Raven Hill.]]}
DB[164]={id=164,zoneId=10,name=[[Deliveries to Sven]],name_loc=[[Entrega a Sven]],level=23,minLevel=17,giver=[[Elaine Carevin]],giverType=[[NPC]],giverId=633,ender=[[Sven Yorgen]],enderType=[[NPC]],enderId=311,poiX=-10330,poiY=623,wowhead=[[https://www.wowhead.com/wotlk/quest=164]],image=[[assets/images/quests/placeholder.png]],desc=[[Do you know Sven? Now, there is a man who does the work of the Light! He and his followers keep a camp at the northwestern edge of Duskwood. Unfortunately, because they are so few, they cannot even spare a man to fetch supplies from town. Will you deliver these supplies to him?]],logDesc=[[Deliver the supplies to Sven.]]}
DB[165]={id=165,zoneId=10,name=[[The Hermit]],name_loc=[[El ermitaño]],level=25,minLevel=17,giver=[[Elaine Carevin]],giverType=[[NPC]],giverId=633,ender=[[Abercrombie]],ender_loc=[[Abercrombie]],enderType=[[NPC]],enderId=289,poiX=-10283,poiY=74,wowhead=[[https://www.wowhead.com/wotlk/quest=165]],image=[[assets/images/quests/placeholder.png]],desc=[[There was an old man who used to come into town to buy supplies rather frequently, but I haven't seen him for quite some time now. He lives out in a shack overlooking Raven Hill cemetery, if I remember correctly. Perhaps you should go see if something is amiss.]],logDesc=[[Check on the old man in the shack near Raven Hill cemetery.]]}
DB[166]={id=166,zoneId=1581,name=[[The Defias Brotherhood]],name_loc=[[La hermandad de los Defias]],level=22,minLevel=14,giver=[[Gryan Stoutmantle]],giver_loc=[[Gryan Mantorrecio]],giverType=[[NPC]],giverId=234,ender=[[Gryan Stoutmantle]],ender_loc=[[Gryan Mantorrecio]],enderType=[[NPC]],enderId=234,prevId=155,poiX=-10509,poiY=1045,wowhead=[[https://www.wowhead.com/wotlk/quest=166]],image=[[assets/images/quests/placeholder.png]],desc=[[There is but one task left for you to complete.  Edwin VanCleef must be assassinated.  While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all.  Bring me the villain's head once the deed is done.]],logDesc=[[Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.]],choiceRewards={{id=6087,qty=1},{id=2041,qty=1},{id=2042,qty=1}}}
DB[167]={id=167,zoneId=1581,name=[[Oh Brother. . .]],name_loc=[[Oh, hermano...]],level=20,minLevel=15,giver=[[Wilder Thistlenettle]],giver_loc=[[Wilder Cardortiga]],giverType=[[NPC]],giverId=656,ender=[[Wilder Thistlenettle]],ender_loc=[[Wilder Cardortiga]],enderType=[[NPC]],enderId=656,poiX=-11327,poiY=1539,wowhead=[[https://www.wowhead.com/wotlk/quest=167]],image=[[assets/images/quests/placeholder.png]],desc=[[We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us. I got out but the others... well... the others haven't been heard from. You look like you might have better luck in there. If you could look for my brother, I'd be thankful.  He always carried his Explorers' League Badge. If you can't find him, that badge would at least give me some peace of mind.]],logDesc=[[Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.]],rewards={{id=1893,qty=1}}}
DB[168]={id=168,zoneId=1581,name=[[Collecting Memories]],name_loc=[[Recolección de recuerdos]],level=18,minLevel=14,giver=[[Wilder Thistlenettle]],giver_loc=[[Wilder Cardortiga]],giverType=[[NPC]],giverId=656,ender=[[Wilder Thistlenettle]],ender_loc=[[Wilder Cardortiga]],enderType=[[NPC]],enderId=656,poiX=-11343,poiY=1531,wowhead=[[https://www.wowhead.com/wotlk/quest=168]],image=[[assets/images/quests/placeholder.png]],desc=[[Many of my friends perished that horrible day when the mine tunnel caved in.  If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them.  If you come across any of their Miners' Union Cards, bring them back to me and I'll make sure their families get some resolution from this horrible accident.]],logDesc=[[Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.]],choiceRewards={{id=2037,qty=1},{id=2036,qty=1}}}
DB[169]={id=169,zoneId=44,name=[[Wanted: Gath'Ilzogg]],name_loc=[[Se busca: Gath'Ilzogg]],level=26,minLevel=11,giver=[[Wanted: Gath'Ilzogg]],giver_loc=[[Se busca: Gath'Ilzogg]],giverType=[[GO]],giverId=60,ender=[[Magistrate Solomon]],ender_loc=[[Magistrado Solomon]],enderType=[[NPC]],enderId=344,poiX=-9383,poiY=-3082,wowhead=[[https://www.wowhead.com/wotlk/quest=169]],image=[[assets/images/quests/placeholder.png]],desc=[[Wanted! Gath'Ilzogg, Leader of the Blackrock attacks on Stonewatch Keep and raids against the township of Lakeshire.  Gath'Ilzogg is extremely dangerous.  He is reportedly holed up in the recently conquered keep plotting the Blackrock clan's further crimes against humanity.  The orc infestation must be quelled at all costs.  A gracious reward will be given to whatever brave soul can deliver the head of Gath'Ilzogg to Magistrate Solomon.]],logDesc=[[Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward.]]}
DB[170]={id=170,zoneId=132,name=[[A New Threat]],name_loc=[[Una nueva amenaza]],level=2,minLevel=1,giver=[[Balir Frosthammer]],giver_loc=[[Balir Martilloescarcha]],giverType=[[NPC]],giverId=713,ender=[[Balir Frosthammer]],ender_loc=[[Balir Martilloescarcha]],enderType=[[NPC]],enderId=713,prevId=179,poiX=-6353,poiY=159,wowhead=[[https://www.wowhead.com/wotlk/quest=170]],image=[[assets/images/quests/placeholder.png]],desc=[[I hope you're here to lend us a hand, $c. After the last trogg attack, we could use all the help we can get. I hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception. They've been spotted all over the hills to the southeast and near the frozen lake. And that's not all, just a few nights ago, they attacked and overran our camp to the west!  We're a bit shorthanded here, $g lad : lass;, and we need strong arms to help drive the troggs back.]],logDesc=[[Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs.]],choiceRewards={{id=6185,qty=1},{id=2172,qty=1},{id=6173,qty=1}}}
DB[171]={id=171,name=[[A Warden of the Alliance]],name_loc=[[Alcaide de la Alianza]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Orphan Matron Nightingale]],ender_loc=[[Supervisora de huérfanos Ruiseñor]],enderType=[[NPC]],enderId=14450,prevId=558,poiX=-8621,poiY=744,wowhead=[[https://www.wowhead.com/wotlk/quest=171]],image=[[assets/images/quests/placeholder.png]],desc=[[You have been so very kind to me, $N.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.  I don't wanna be sad about what's happened to me and all - my folks always told me to rise above anything bad that happens.  You know, when I grow up I wanna be a hero... just like you. I'm sad to say this, but it's time for me to go home.  Let's go back and I'll tell the matron what an awesome person you are!]],logDesc=[[Return your ward to the Stormwind orphanage by handing in the Human Orphan Whistle to Orphan Matron Nightingale in the Cathedral District.]],choiceRewards={{id=23007,qty=1},{id=23015,qty=1},{id=23002,qty=1},{id=23022,qty=1}}}
DB[172]={id=172,name=[[Children's Week]],name_loc=[[Semana de los Niños]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Orcish Orphan]],ender_loc=[[Huérfano orco]],enderType=[[NPC]],enderId=14444,poiX=2038,poiY=-4673,wowhead=[[https://www.wowhead.com/wotlk/quest=172]],image=[[assets/images/quests/placeholder.png]],desc=[[You're willing to help us here at the orphanage?  Bless you, friend; your aid during Children's Week will be invaluable. Take this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children's Week itself.  When you use it, you will be able to talk with the child you've agreed to look after.  Using it again will dismiss the child. By all means $N - use the whistle and meet your ward!  I'm sure the child will be most eager to meet you.]],logDesc=[[Use the Orcish Orphan Whistle to talk with the child you will be looking after during Children's Week.]]}
DB[173]={id=173,zoneId=10,name=[[Worgen in the Woods]],name_loc=[[Ferocanis en el bosque]],level=28,minLevel=23,giver=[[Calor]],giverType=[[NPC]],giverId=663,ender=[[Calor]],enderType=[[NPC]],enderId=663,rewardNextId=221,poiX=-10991,poiY=-984,wowhead=[[https://www.wowhead.com/wotlk/quest=173]],image=[[assets/images/quests/placeholder.png]],desc=[[Darkness seems drawn inexorably to Duskwood. Master Carevin's quest is the expulsion of evil and heresy. Through our efforts are the people of Darkshire kept safe. You believe yourself worthy to join us? I once thought as you. Disillusioned by the complacency of the Watch, I joined Master Carevin. If you wish to prove yourself, it will not be through words. Test your skills against the Nightbane Shadow Weaver worgen in Brightwood Grove--bright, hah!--and the Rotting Orchard.]],logDesc=[[Kill 6 Nightbane Shadow Weaver worgen for Calor in Darkshire.]]}
DB[174]={id=174,zoneId=10,name=[[Look To The Stars]],name_loc=[[Mira las estrellas]],level=25,minLevel=20,giver=[[Viktori Prism'Antras]],giverType=[[NPC]],giverId=276,ender=[[Viktori Prism'Antras]],enderType=[[NPC]],enderId=276,rewardNextId=175,poiX=-10582,poiY=-1321,wowhead=[[https://www.wowhead.com/wotlk/quest=174]],image=[[assets/images/quests/placeholder.png]],desc=[[My Gnomish friend, Cog, has promised to help me build a device which will let me peer towards the stars.  A truth exists, beyond magic, that can explain the strange transformation in the forest. Bring to me a bronze tube made by a skilled engineer.  That is the first step, according to Cog's blueprint.]],logDesc=[[Viktori Prism'Antras of Darkshire wants you to bring him a bronze tube.]]}
DB[175]={id=175,zoneId=10,name=[[Look To The Stars]],name_loc=[[Mira las estrellas]],level=25,minLevel=20,giver=[[Viktori Prism'Antras]],giverType=[[NPC]],giverId=276,ender=[[Blind Mary]],ender_loc=[[Mary la Ciega]],enderType=[[NPC]],enderId=302,prevId=174,rewardNextId=177,poiX=-10786,poiY=-1381,wowhead=[[https://www.wowhead.com/wotlk/quest=175]],image=[[assets/images/quests/placeholder.png]],desc=[[According to Cog's blueprint, what I need now is a way to reflect light.  I remember a woman by the name of Mary who became well known around these parts for always carrying a looking glass.  Perhaps you can track Mary down and see if she might lend us a reflective surface for this project?  I believe she once resided in southern Duskwood. . .]],logDesc=[[Locate Mary and persuade her to give up a reflective surface for Viktori's project.]]}
DB[176]={id=176,zoneId=12,name=[[Wanted:  "Hogger"]],name_loc=[[Se busca: Hogger]],level=11,minLevel=5,giver=[[Wanted Poster]],giver_loc=[[Cartel de Se busca]],giverType=[[GO]],giverId=68,ender=[[Marshal Dughan]],ender_loc=[[Alguacil Dughan]],enderType=[[NPC]],enderId=240,poiX=-10107,poiY=618,wowhead=[[https://www.wowhead.com/wotlk/quest=176]],image=[[assets/images/quests/placeholder.png]],desc=[[Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn.  He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll.  To earn the reward, bounty hunters should bring proof of Hogger's demise to Marshal Dughan in Goldshire.]],logDesc=[[Slay the gnoll Hogger and bring his Huge Gnoll Claw to Marshal Dughan.]],choiceRewards={{id=6085,qty=1},{id=6084,qty=1},{id=6215,qty=1}}}
DB[177]={id=177,zoneId=10,name=[[Look To The Stars]],name_loc=[[Mira las estrellas]],level=25,minLevel=20,giver=[[Blind Mary]],giver_loc=[[Mary la Ciega]],giverType=[[NPC]],giverId=302,ender=[[Viktori Prism'Antras]],enderType=[[NPC]],enderId=276,prevId=175,rewardNextId=181,poiX=-10582,poiY=-1321,wowhead=[[https://www.wowhead.com/wotlk/quest=177]],image=[[assets/images/quests/placeholder.png]],desc=[[The looking glass was one of my finest treasures until. . .the incident.  After that happened, I discarded it behind the barn.  There was an Insane Ghoul who used to roam back there.  Perhaps he picked it up.  Rumor has it the devilish beast resides in the Tranquil Gardens Cemetery.]],logDesc=[[Retrieve Blind Mary's Looking Glass from the Insane Ghoul and give it to Viktori in Darkshire.]]}
DB[178]={id=178,zoneId=44,name=[[Theocritus' Retrieval]],name_loc=[[Theocritus recupera el colgante]],level=23,minLevel=15,giverType=[[NPC]],ender=[[Theocritus]],ender_loc=[[Theocritus]],enderType=[[NPC]],enderId=313,poiX=-9553,poiY=-728,wowhead=[[https://www.wowhead.com/wotlk/quest=178]],image=[[assets/images/quests/placeholder.png]],desc=[[<You hear a disembodied voice...> Do not be alarmed.  I am Theocritus, High Mage of Tower Azora in Elwynn Forest.  The pendant you are holding is a method of communication between the Shadowhide Gnolls and their master, Morganth. Through months of research, I believe I too can communicate through these pendants.  If you can hear this message, then my spell was a success. Bring me this pendant and I will reward you for the service.]],logDesc=[[Bring the Faded Shadowhide Pendant to Theocritus the Mage at the Tower of Azora in Elwynn Forest.]],rewards={{id=1970,qty=3}}}
DB[179]={id=179,zoneId=132,name=[[Dwarven Outfitters]],name_loc=[[Los enanos modistos]],level=1,minLevel=1,giver=[[Sten Stoutarm]],giver_loc=[[Sten Brazorrecio]],giverType=[[NPC]],giverId=658,ender=[[Sten Stoutarm]],ender_loc=[[Sten Brazorrecio]],enderType=[[NPC]],enderId=658,poiX=-6204,poiY=215,wowhead=[[https://www.wowhead.com/wotlk/quest=179]],image=[[assets/images/quests/placeholder.png]],desc=[[What do we have here? You look as though you might need something to keep your hands warm, hm? I'll tell you what would help: a pair of nice, warm gloves. And, being the kind soul that I am, I'd be more than happy to provide you with a suitable pair. I've one condition, however. I need you to go get me some wolf meat. Nice arrangement, hm? You bring me some wolf meat, and I'll make sure you don't lose any digits to frostbite. Well, what do you say?]],logDesc=[[Sten Stoutarm would like 8 pieces of Tough Wolf Meat.]],choiceRewards={{id=719,qty=1},{id=6171,qty=1},{id=2547,qty=1}}}
DB[180]={id=180,zoneId=44,name=[[Wanted: Lieutenant Fangore]],name_loc=[[Se busca: Teniente Fangore]],level=26,minLevel=11,giver=[[Wanted: Lieutenant Fangore]],giver_loc=[[Se busca: Teniente Fangore]],giverType=[[GO]],giverId=47,ender=[[Magistrate Solomon]],ender_loc=[[Magistrado Solomon]],enderType=[[NPC]],enderId=344,poiX=-9122,poiY=-3308,wowhead=[[https://www.wowhead.com/wotlk/quest=180]],image=[[assets/images/quests/placeholder.png]],desc=[[Wanted: Lieutenant Fangore Known leader of the Shadowhide Gnoll Clan, working under the enemy of the Township and Kingdom, Morganth.  By mandate of Magistrate Solomon, this vile betrayer of Stormwind is wanted dead.  Show his paw to the Magistrate as proof of his death.]],logDesc=[[Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw.]]}
DB[181]={id=181,zoneId=10,name=[[Look To The Stars]],name_loc=[[Mira las estrellas]],level=30,minLevel=20,giver=[[Viktori Prism'Antras]],giverType=[[NPC]],giverId=276,ender=[[Viktori Prism'Antras]],enderType=[[NPC]],enderId=276,prevId=177,poiX=-11168,poiY=-141,wowhead=[[https://www.wowhead.com/wotlk/quest=181]],image=[[assets/images/quests/placeholder.png]],desc=[[Now there is just one more item needed to complete this device.  Cog's blueprint calls for a lens of some sort.  The only lens I know of that would be large enough will be very difficult to acquire. There is an ogre by the name of Zzarc'Vul who resides in the mound in southern Duskwood.  If you can, bring to me his monocle and I will use that as our lens!]],logDesc=[[Locate Zzarc'Vul in the southern ogre mound in Duskwood and return his monocle to Viktori in Darkshire.]],choiceRewards={{id=7106,qty=1},{id=7107,qty=1}}}
DB[182]={id=182,zoneId=132,name=[[The Troll Cave]],name_loc=[[La cueva de los trols]],level=4,minLevel=1,giver=[[Grelin Whitebeard]],giver_loc=[[Grelin Barbablanca]],giverType=[[NPC]],giverId=786,ender=[[Grelin Whitebeard]],ender_loc=[[Grelin Barbablanca]],enderType=[[NPC]],enderId=786,rewardNextId=218,poiX=-6515,poiY=633,wowhead=[[https://www.wowhead.com/wotlk/quest=182]],image=[[assets/images/quests/placeholder.png]],desc=[[My brother Senir and I were sent to different parts of Dun Morogh to investigate the threat posed by the trolls. The Senate has its hands full with the troggs, so they've no need for further annoyances. From what I've seen, the trolls aren't well situated here in Coldridge Valley--mostly the southern cave. I'd say that the army will not be necessary. A few strong arms should be more than enough. Perhaps you'd like to assist in this endeavor? I have the authority to offer compensation for your help.]],logDesc=[[Grelin Whitebeard would like you to kill 10 Frostmane Troll Whelps.]],rewards={{id=961,qty=3}},choiceRewards={{id=2047,qty=1},{id=2048,qty=1},{id=2195,qty=1},{id=5761,qty=1}}}
DB[183]={id=183,zoneId=132,name=[[The Boar Hunter]],name_loc=[[Cazador de jabalíes]],level=3,minLevel=1,giver=[[Talin Keeneye]],giver_loc=[[Talin Ojoagudo]],giverType=[[NPC]],giverId=714,ender=[[Talin Keeneye]],ender_loc=[[Talin Ojoagudo]],enderType=[[NPC]],enderId=714,poiX=-6280,poiY=417,wowhead=[[https://www.wowhead.com/wotlk/quest=183]],image=[[assets/images/quests/placeholder.png]],desc=[[Nothing like a day of boar hunting, eh? Though, here in Coldridge Valley, there are so many boars it almost takes the fun out of it. No need to get them charging. They're all angry and ready without any help. In fact, recently, there've been so many boars in the area, it's become dangerous for me to do my daily hunting. Long story short, if you could help me kill some of the boars, I would appreciate it.]],logDesc=[[Talin Keeneye would like you to kill 12 Small Crag Boars.]],choiceRewards={{id=79,qty=1},{id=61,qty=1}}}
DB[184]={id=184,zoneId=40,name=[[Furlbrow's Deed]],name_loc=[[Las escrituras de Cejade]],level=9,minLevel=8,giverType=[[NPC]],ender=[[Farmer Furlbrow]],ender_loc=[[Granjero Cejade]],enderType=[[NPC]],enderId=237,poiX=-9852,poiY=918,wowhead=[[https://www.wowhead.com/wotlk/quest=184]],image=[[assets/images/quests/placeholder.png]],desc=[[This is the deed to an expanse of farmlands within Westfall.  It is signed by a Theodore Furlbrow and cosigned by his wife, Verna.  And on the back of the deed are hastily scrawled words: "We leaned on Furlbrow and got his deed.  Thought it might be handy if you wanted to forge one of these for your own place. The Furlbrows won't give us trouble.  Last I saw them they were on their way out of Westfall, stuck with a broken wagon." You think the Furlbrows might want their deed back...]],logDesc=[[Bring Furlbrow's Deed to Farmer Furlbrow.]],rewards={{id=5057,qty=5},{id=4656,qty=5}}}
DB[185]={id=185,zoneId=33,name=[[Tiger Mastery]],name_loc=[[Domina el tigre]],level=31,minLevel=28,giver=[[Ajeck Rouack]],giverType=[[NPC]],giverId=717,ender=[[Ajeck Rouack]],enderType=[[NPC]],enderId=717,prevId=583,rewardNextId=186,poiX=-11731,poiY=-222,wowhead=[[https://www.wowhead.com/wotlk/quest=185]],image=[[assets/images/quests/placeholder.png]],desc=[[When I was but a young girl, my father trained me in the art of tiger hunting. You'll find the young felines much easier to track and slay.  For this reason, we'll start you out easy.  One can often find young tigers near the expedition camp. Test your tracking skills and see if you can hunt some of the beasts down.]],logDesc=[[Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers.]]}
DB[186]={id=186,zoneId=33,name=[[Tiger Mastery]],name_loc=[[Persigue al tigre]],level=33,minLevel=28,giver=[[Ajeck Rouack]],giverType=[[NPC]],giverId=717,ender=[[Ajeck Rouack]],enderType=[[NPC]],enderId=717,prevId=185,rewardNextId=187,poiX=-11650,poiY=249,wowhead=[[https://www.wowhead.com/wotlk/quest=186]],image=[[assets/images/quests/placeholder.png]],desc=[[You are learning, $c.  Let us test your skills with the mature cats now. Kill 10 Stranglethorn Tigers this time out.]],logDesc=[[Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers.]]}
DB[187]={id=187,zoneId=33,name=[[Tiger Mastery]],name_loc=[[Domina el tigre]],level=35,minLevel=28,giver=[[Ajeck Rouack]],giverType=[[NPC]],giverId=717,ender=[[Ajeck Rouack]],enderType=[[NPC]],enderId=717,prevId=186,rewardNextId=188,poiX=-11967,poiY=-83,wowhead=[[https://www.wowhead.com/wotlk/quest=187]],image=[[assets/images/quests/placeholder.png]],desc=[[Now I'm going to up the stakes on you and truly test your skill.  Prove to me you can kill 10 Elder Stranglethorn Tigers.  If you can do that, you will be ready for your final challenge before I declare you a master tiger hunter in Master Nesingwary's presence. Elder Stranglethorn Tigers are not only the most difficult to find, they are also the fiercest to defeat.]],logDesc=[[Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers.]]}
DB[188]={id=188,zoneId=33,name=[[Tiger Mastery]],name_loc=[[Domina el tigre]],level=37,minLevel=28,giver=[[Ajeck Rouack]],giverType=[[NPC]],giverId=717,ender=[[Ajeck Rouack]],enderType=[[NPC]],enderId=717,prevId=187,nextId=208,exGroup=-193,poiX=-11886,poiY=87,wowhead=[[https://www.wowhead.com/wotlk/quest=188]],image=[[assets/images/quests/placeholder.png]],desc=[[Here is the final challenge that I will put forth.  We've been tracking an elusive tiger for weeks.  We call the beast Sin'Dall.  See if you can do what no $r has done before: hunt down and kill Sin'Dall.  Bring me her paw as proof of your accomplishment. Tracking her down will be no easy task.]],logDesc=[[Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw.]],rewards={{id=4107,qty=1}}}
DB[189]={id=189,zoneId=33,name=[[Bloodscalp Ears]],name_loc=[[Orejas de Sangrapellejo]],level=35,minLevel=30,giver=[[Kebok]],giverType=[[NPC]],giverId=737,ender=[[Kebok]],enderType=[[NPC]],enderId=737,poiX=-11850,poiY=15,wowhead=[[https://www.wowhead.com/wotlk/quest=189]],image=[[assets/images/quests/placeholder.png]],desc=[[Damn trolls! They've been killing off our agents in the jungle! I've already lost a good number of my best guards to skirmishes with them. The costs are piling up! How will I explain this to Baron Revilgaz? Decisive action... Think, Kebok... you weren't assigned to the post you have today for sitting around... I've got it! You... $n, is it? You'll help me, won't you? There's money to be had! Here's the deal... you bring me the ears of fifteen Bloodscalp Trolls, and I'll compensate you well.]],logDesc=[[Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.]],rewards={{id=4598,qty=8}}}
DB[190]={id=190,zoneId=33,name=[[Panther Mastery]],name_loc=[[Domina la pantera]],level=31,minLevel=28,giver=[[Sir S. J. Erlgadin]],giverType=[[NPC]],giverId=718,ender=[[Sir S. J. Erlgadin]],enderType=[[NPC]],enderId=718,prevId=583,rewardNextId=191,poiX=-11617,poiY=-48,wowhead=[[https://www.wowhead.com/wotlk/quest=190]],image=[[assets/images/quests/placeholder.png]],desc=[[If you want to be a part of the hunt with this crack group under Hemet Jr.'s leadership, you're going to need to prove yourself an able panther hunter.  We'll start you out easy -- don't you worry.  Let's see you kill 10 young panthers to start. Tracking them down is only half the challenge...]],logDesc=[[Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers.]]}
DB[191]={id=191,zoneId=33,name=[[Panther Mastery]],name_loc=[[Domina la pantera]],level=33,minLevel=28,giver=[[Sir S. J. Erlgadin]],giverType=[[NPC]],giverId=718,ender=[[Sir S. J. Erlgadin]],enderType=[[NPC]],enderId=718,prevId=190,rewardNextId=192,poiX=-11617,poiY=-48,wowhead=[[https://www.wowhead.com/wotlk/quest=191]],image=[[assets/images/quests/placeholder.png]],desc=[[Now you're ready to turn it up a notch.  If you want to prove yourself worthy of socializing with the likes of these big game hunters, you'll need to prove that you can kill 10 panthers. Those big boys are tougher.  They're not as easy as the young ones you were killing earlier.]],logDesc=[[Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers.]]}
DB[192]={id=192,zoneId=33,name=[[Panther Mastery]],name_loc=[[Domina la pantera]],level=38,minLevel=28,giver=[[Sir S. J. Erlgadin]],giverType=[[NPC]],giverId=718,ender=[[Sir S. J. Erlgadin]],enderType=[[NPC]],enderId=718,prevId=191,rewardNextId=193,poiX=-12049,poiY=-1018,wowhead=[[https://www.wowhead.com/wotlk/quest=192]],image=[[assets/images/quests/placeholder.png]],desc=[[Now the hard part.  A true panther hunter can show skill by dropping Shadowmaw Panthers, the deadliest in Stranglethorn.  Prove to us that you can slay 10 of these beasts. If you think they are hard to track, wait until you attempt to slay one....]],logDesc=[[Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers.]]}
DB[193]={id=193,zoneId=33,name=[[Panther Mastery]],name_loc=[[Domina la pantera]],level=40,minLevel=28,giver=[[Sir S. J. Erlgadin]],giverType=[[NPC]],giverId=718,ender=[[Sir S. J. Erlgadin]],enderType=[[NPC]],enderId=718,prevId=192,nextId=208,exGroup=-193,poiX=-11617,poiY=-48,wowhead=[[https://www.wowhead.com/wotlk/quest=193]],image=[[assets/images/quests/placeholder.png]],desc=[[You've almost proven yourself to be a master hunter of panthers.  A panther by the name of Bhag'thera has been prowling the jungle.  So far he's eluded our party.  See if you can use your skills to kill the great Bhag'thera. Bring me the Fang of Bhag'thera and you'll have earned my respect!]],logDesc=[[Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera.]],rewards={{id=4108,qty=1}}}
DB[194]={id=194,zoneId=33,name=[[Raptor Mastery]],name_loc=[[Domina el raptor]],level=34,minLevel=28,giver=[[Hemet Nesingwary Jr.]],giver_loc=[[Hemet Decautela]],giverType=[[NPC]],giverId=715,ender=[[Hemet Nesingwary Jr.]],ender_loc=[[Hemet Decautela]],enderType=[[NPC]],enderId=715,prevId=583,rewardNextId=195,poiX=-11820,poiY=419,wowhead=[[https://www.wowhead.com/wotlk/quest=194]],image=[[assets/images/quests/placeholder.png]],desc=[[So you think your hunting skills are in tip-top shape?  I can put them to the test in a jiffy.  Head out into that jungle and kill 10 Stranglethorn Raptors.  We'll see just how much of a big game hunter you are. And no, I won't tell you where you can find them!  Locating the beasts is half the challenge.]],logDesc=[[Hemet Nesingwary Jr. wants you to kill 10 Stranglethorn Raptors.]]}
DB[195]={id=195,zoneId=33,name=[[Raptor Mastery]],name_loc=[[Domina el raptor]],level=36,minLevel=28,giver=[[Hemet Nesingwary Jr.]],giver_loc=[[Hemet Decautela]],giverType=[[NPC]],giverId=715,ender=[[Hemet Nesingwary Jr.]],ender_loc=[[Hemet Decautela]],enderType=[[NPC]],enderId=715,prevId=194,rewardNextId=196,poiX=-11984,poiY=-286,wowhead=[[https://www.wowhead.com/wotlk/quest=195]],image=[[assets/images/quests/placeholder.png]],desc=[[Now let's step up the challenge and see if you're up to it.  Venture into the jungle and bag yourself 10 of those bloody Lashtail Raptors.  Let's see what you've got!]],logDesc=[[Hemet Nesingwary Jr. wants you to kill 10 Lashtail Raptors.]]}
DB[196]={id=196,zoneId=33,name=[[Raptor Mastery]],name_loc=[[Domina el raptor]],level=41,minLevel=28,giver=[[Hemet Nesingwary Jr.]],giver_loc=[[Hemet Decautela]],giverType=[[NPC]],giverId=715,ender=[[Hemet Nesingwary Jr.]],ender_loc=[[Hemet Decautela]],enderType=[[NPC]],enderId=715,prevId=195,rewardNextId=197,poiX=-12882,poiY=18,wowhead=[[https://www.wowhead.com/wotlk/quest=196]],image=[[assets/images/quests/placeholder.png]],desc=[[Let's see how you handle this next challenge.  There is a cagey breed of raptor out there.  We call them Jungle Stalkers.  They are far more difficult to track down and kill than the other breeds you've been trying your luck at.  Kill 10 Jungle Stalkers and I'll tip you off to the best hunting yet.]],logDesc=[[Hemet Nesingwary Jr. wants you to kill 10 Jungle Stalkers.]]}
DB[197]={id=197,zoneId=33,name=[[Raptor Mastery]],name_loc=[[Domina el raptor]],level=43,minLevel=28,giver=[[Hemet Nesingwary Jr.]],giver_loc=[[Hemet Decautela]],giverType=[[NPC]],giverId=715,ender=[[Hemet Nesingwary Jr.]],ender_loc=[[Hemet Decautela]],enderType=[[NPC]],enderId=715,prevId=196,nextId=208,exGroup=-193,poiX=-12905,poiY=227,wowhead=[[https://www.wowhead.com/wotlk/quest=197]],image=[[assets/images/quests/placeholder.png]],desc=[[Because you proved yourself to be such a go-getter in the jungle, let me tell you about a ferocious raptor that even I have failed to kill.  Ajeck here calls this wily raptor Tethis. If you want to prove yourself a true master, kill Tethis and bring me his talon.  It would be a feat that no other big game hunter has accomplished.]],logDesc=[[Hemet Nesingwary Jr. wants you to kill Tethis, an elusive, dangerous raptor in Stranglethorn.]],rewards={{id=4119,qty=1}}}
DB[198]={id=198,zoneId=33,name=[[Supplies to Private Thorsen]],name_loc=[[Suministros para el soldado Thorsen]],level=32,minLevel=30,giver=[[Krazek]],giverType=[[NPC]],giverId=773,ender=[[Private Thorsen]],ender_loc=[[Soldado Thorsen]],enderType=[[NPC]],enderId=738,poiX=-11314,poiY=-203,wowhead=[[https://www.wowhead.com/wotlk/quest=198]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmm. Yes, I do have something you could do, actually. Lieutenant Doren and his followers up in the north need their regular supplies from us. They haven't been delivered, and with the trolls attacking, I'll need someone to do it. Doren's camp lies northwest of the road at the entrance to Stranglethorn from Duskwood. Give the supplies to Private Thorsen, if he's not in the camp, then he'll be patrolling south of it. He'll take care of them. Mind you, if you fail, you'll owe me restitution.]],logDesc=[[Deliver the Miscellaneous Goblin Supplies to Private Thorsen.]]}
DB[199]={id=199,zoneId=38,name=[[A Dark Threat Looms]],name_loc=[[Se aproxima una oscura amenaza]],level=18,minLevel=16,giver=[[Suspicious Barrel]],giver_loc=[[Barrica sospechosa]],giverType=[[GO]],giverId=257,ender=[[Chief Engineer Hinderweir VII]],ender_loc=[[Ingeniero jefe Hinderweir VII]],enderType=[[NPC]],enderId=1093,prevId=250,rewardNextId=161,poiX=-4738,poiY=-3264,wowhead=[[https://www.wowhead.com/wotlk/quest=199]],image=[[assets/images/quests/placeholder.png]],desc=[[You take a sample of the strange smelling powder.]],logDesc=[[Return to Chief Engineer Hinderweir and show him the clue that you discovered.]]}
DB[200]={id=200,zoneId=33,name=[[Bookie Herod]],name_loc=[[Corredor Herod]],level=35,minLevel=30,giver=[[Lieutenant Doren]],giver_loc=[[Teniente Doren]],giverType=[[NPC]],giverId=469,ender=[[Bookie Herod's Records]],ender_loc=[[Documentos del corredor Herod]],enderType=[[GO]],enderId=287,prevId=215,rewardNextId=328,poiX=-11567,poiY=-566,wowhead=[[https://www.wowhead.com/wotlk/quest=200]],image=[[assets/images/quests/placeholder.png]],desc=[[If Kurzen knows Thorsen's secret, then we have a spy in our midst.  We must determine how the secret was leaked! Thorsen's contact within Kurzen's camp was Bookie Herod.  Herod is Kurzen's logistics officer and knows everything about the running of Kurzen's Compound.  If you can get Herod's notes or records, maybe we can find out how Thorsen was discovered. When we were still with Kurzen, Bookie's office was on the top floor of the camp's only two-story house.  His records are probably still there.]],logDesc=[[Find Bookie Herod's Records.]]}
DB[201]={id=201,zoneId=33,name=[[Investigate the Camp]],name_loc=[[Investiga el campamento]],level=32,minLevel=28,giver=[[Krazek]],giverType=[[NPC]],giverId=773,ender=[[Krazek]],enderType=[[NPC]],enderId=773,poiX=-14453,poiY=501,wowhead=[[https://www.wowhead.com/wotlk/quest=201]],image=[[assets/images/quests/placeholder.png]],desc=[[I've gotten reports of a group of hunters that have set up camp upriver of the Venture Company mining camp on Lake Nazferiti.  Now, normally I wouldn't care, but improbably, I heard that Hemet Nesingwary Jr. was one of the hunters there.  He's certainly well-connected, if you catch my meaning, and you never can be too safe. Why don't you go check out the camp, $n, see what they're about?]],logDesc=[[Find the hunters' camp and report its location to Krazek in Booty Bay.]]}
DB[202]={id=202,zoneId=33,name=[[Colonel Kurzen]],name_loc=[[Coronel Kurzen]],level=40,minLevel=30,giver=[[Lieutenant Doren]],giver_loc=[[Teniente Doren]],giverType=[[NPC]],giverId=469,ender=[[Lieutenant Doren]],ender_loc=[[Teniente Doren]],enderType=[[NPC]],enderId=469,prevId=574,poiX=-11297,poiY=-207,wowhead=[[https://www.wowhead.com/wotlk/quest=202]],image=[[assets/images/quests/placeholder.png]],desc=[[You have proven yourself time and again, and your resourcefulness seems to rival even that of Kurzen himself.  You may be the salvation of our band of rebels...if you can pit yourself against Kurzen and prevail! He commands his men from deep within the Stockpile.  You must enter that cave, brave through his defenders, and face Kurzen and his leaders. Farewell, $N.  My hope, and the fate of my men, go with you.]],logDesc=[[Kill 6 Kurzen Elite, 4 Kurzen Subchiefs, and bring Kurzen's Head to Lieutenant Doren at the Rebel Camp.]],rewards={{id=4127,qty=1}}}
DB[203]={id=203,zoneId=33,name=[[The Second Rebellion]],name_loc=[[La segunda rebelión]],level=33,minLevel=30,giver=[[Sergeant Yohwa]],giver_loc=[[Sargento Yohwa]],giverType=[[NPC]],giverId=733,ender=[[Sergeant Yohwa]],ender_loc=[[Sargento Yohwa]],enderType=[[NPC]],enderId=733,nextId=574,exGroup=-203,poiX=-11486,poiY=-784,wowhead=[[https://www.wowhead.com/wotlk/quest=203]],image=[[assets/images/quests/placeholder.png]],desc=[[We're fighting a losing battle with Colonel Kurzen.  Not only is he a brilliant tactician, he outnumbers us at least 10 to 1!  To survive, we need to use his own, covert tactics against him. Enter his camp to the east and kill his men.  Lots of them.  And get out before reinforcements can close on you.]],logDesc=[[Kill 15 Kurzen Jungle Fighters. Return to Sergeant Yohwa at the Rebel Camp.]]}
DB[204]={id=204,zoneId=33,name=[[Bad Medicine]],name_loc=[[Mala medicina]],level=34,minLevel=30,giver=[[Sergeant Yohwa]],giver_loc=[[Sargento Yohwa]],giverType=[[NPC]],giverId=733,ender=[[Sergeant Yohwa]],ender_loc=[[Sargento Yohwa]],enderType=[[NPC]],enderId=733,nextId=574,exGroup=-203,poiX=-11486,poiY=-953,wowhead=[[https://www.wowhead.com/wotlk/quest=204]],image=[[assets/images/quests/placeholder.png]],desc=[[To have a chance against Kurzen, we need his healing support neutralized.  He has gathered a large number of medicine men who heal his forces with jungle remedies and poison our fighters with venom fern extracts. We need those remedies and extracts for our own.  Search the Kurzen Compound - his medicine men and jungle fighters will have the remedies, and the extracts are probably stowed in some of the camp's supply boxes.]],logDesc=[[Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp.]],choiceRewards={{id=4140,qty=1},{id=4126,qty=1}}}
DB[205]={id=205,zoneId=33,name=[[Troll Witchery]],name_loc=[[Brujería trol]],level=40,minLevel=30,giver=[[Brother Nimetz]],giver_loc=[[Hermano Nimetz]],giverType=[[NPC]],giverId=739,ender=[[Brother Nimetz]],ender_loc=[[Hermano Nimetz]],enderType=[[NPC]],enderId=739,prevId=207,poiX=-11320,poiY=-193,wowhead=[[https://www.wowhead.com/wotlk/quest=205]],image=[[assets/images/quests/placeholder.png]],desc=[[While I study those legends you acquired, gather for me implements of evil troll magic.  Enter the territory of the Skullsplitter trolls, a second tribe to the distant south, and acquire Skullsplitter Fetishes from their Witchdoctors and Mystics.]],logDesc=[[Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp.]]}
DB[206]={id=206,zoneId=33,name=[[Mai'Zoth]],name_loc=[[Mai'Zoth]],level=46,minLevel=30,giver=[[Brother Nimetz]],giver_loc=[[Hermano Nimetz]],giverType=[[NPC]],giverId=739,ender=[[Brother Nimetz]],ender_loc=[[Hermano Nimetz]],enderType=[[NPC]],enderId=739,prevId=205,poiX=-12343,poiY=-1157,wowhead=[[https://www.wowhead.com/wotlk/quest=206]],image=[[assets/images/quests/placeholder.png]],desc=[[Kurzen may be dead, but...that which drove him to evil still lives!  Through my studies I have discovered this: An Ogre Mage - Mai'Zoth - dwells in an Ogre Mound within the eastern mountains of Stranglethorn.  He is rumored to employ mind-controlling magic, and I am positive that he corrupted Kurzen. If Mai'Zoth is allowed to live, then his evil may influence others, and may even cause another Kurzen to surface. Kill him, and bring me his Mind's Eye, the artifact he uses to corrupt others.]],logDesc=[[Bring the Mind's Eye to Brother Nimetz at the Rebel Camp.]],rewards={{id=4125,qty=1}}}
DB[207]={id=207,zoneId=33,name=[[Kurzen's Mystery]],name_loc=[[El misterio de Kurzen]],level=38,minLevel=30,giver=[[Brother Nimetz]],giver_loc=[[Hermano Nimetz]],giverType=[[NPC]],giverId=739,ender=[[Brother Nimetz]],ender_loc=[[Hermano Nimetz]],enderType=[[NPC]],enderId=739,prevId=204,rewardNextId=205,poiX=-11320,poiY=-193,wowhead=[[https://www.wowhead.com/wotlk/quest=207]],image=[[assets/images/quests/placeholder.png]],desc=[[Colonel Kurzen was once a great, noble man - I must find what caused his fall into depravity!  He may be under the sway of troll magic.  To confirm this, I must study some of their legends. There are 4 tablets hidden within the troll ruins of Stranglethorn.  I must see what is written on these tablets!  Transcribe their markings and bring the transcriptions back to me. The first tablet is in the Bal'lal Ruins, the second is in the Vile Reef, and the third and fourth are in the Ruins of Zul'Kunda.]],logDesc=[[Find the 4 tablets and bring their legends back to Brother Nimetz.]]}
DB[208]={id=208,zoneId=33,name=[[Big Game Hunter]],name_loc=[[Caza mayor]],level=43,minLevel=28,giver=[[Hemet Nesingwary Jr.]],giver_loc=[[Hemet Decautela]],giverType=[[NPC]],giverId=715,ender=[[Hemet Nesingwary Jr.]],ender_loc=[[Hemet Decautela]],enderType=[[NPC]],enderId=715,poiX=-12614,poiY=-220,wowhead=[[https://www.wowhead.com/wotlk/quest=208]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you are a hunter worthy of our company.  From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated. You have killed the ferocious Sin'Dall, the elusive Bag'thera and the treacherous Tethis.  But the true prize is the head of King Bangalash.  That white tiger is the reason I am here.  I've had my sights on him for quite some time now.  Kill King Bangalash and your hunting prowess is proven to be second to none.]],logDesc=[[Hemet Nesingwary Jr. wants you to bring him the head of King Bangalash, the great white tiger.]],choiceRewards={{id=17686,qty=1},{id=17687,qty=1}}}
DB[209]={id=209,zoneId=33,name=[[Skullsplitter Tusks]],name_loc=[[Colmillos Machacacráneos]],level=42,minLevel=37,giver=[[Kebok]],giverType=[[NPC]],giverId=737,ender=[[Kebok]],enderType=[[NPC]],enderId=737,prevId=189,poiX=-12878,poiY=-884,wowhead=[[https://www.wowhead.com/wotlk/quest=209]],image=[[assets/images/quests/placeholder.png]],desc=[[It's expensive and hard to kill enough tigers to support the export of tiger fangs to the islands in the South Seas. Luckily, we've developed a technique that allows us to take mundane horn-like objects and turn them into undetectable forgeries. The closest match we've found, amazingly, are the tusks of the Skullsplitter trolls. Hey, before you say anything, what the buyer doesn't know doesn't hurt them, am I right? Bring me a large number of them so we can get to work on the monthly shipment!]],logDesc=[[Acquire 18 Skullsplitter Tusks and return them to Kebok.]]}
DB[210]={id=210,zoneId=33,name=[[Krazek's Cookery]],name_loc=[[La cocina de Krazek]],level=37,minLevel=32,giver=[[Corporal Kaleb]],giver_loc=[[Cabo Kaleb]],giverType=[[NPC]],giverId=770,ender=[[Krazek]],enderType=[[NPC]],enderId=773,rewardNextId=627,poiX=-14453,poiY=501,wowhead=[[https://www.wowhead.com/wotlk/quest=210]],image=[[assets/images/quests/placeholder.png]],desc=[[I do most of the cooking at the camp.  And it used to be a lot of work, until I bought a mechanical cooking pot from a goblin merchant in Booty Bay.  The pot is a wonder!  It saved me countless hours...until it broke! Can you take the pot back to the goblin for me so he can fix it?  His name is Krazek.]],logDesc=[[Bring Krazek's Crock Pot to Krazek the goblin.]]}
DB[211]={id=211,zoneId=28,name=[[Alas, Andorhal]],name_loc=[[Ah, Andorhal]],level=60,minLevel=50,giver=[[Commander Ashlam Valorfist]],giver_loc=[[Comandante Ashlam Puñovalor]],giverType=[[NPC]],giverId=10838,ender=[[Commander Ashlam Valorfist]],ender_loc=[[Comandante Ashlam Puñovalor]],enderType=[[NPC]],enderId=10838,prevId=5097,poiX=1383,poiY=-1530,wowhead=[[https://www.wowhead.com/wotlk/quest=211]],image=[[assets/images/quests/placeholder.png]],desc=[[Alas, the time to attack Andorhal and drive out the lich that controls it is upon us! Inside the ruins of the city is where the lich - Araj the Summoner - holds dominion.  He is guarded by numerous Scourge surrounding the remains of city's center, and his personal retinue of guardians attached to him directly is formidable.  You will need numerous allies to even stand a chance of facing him successfully. Destroy Araj, $N, and bring me a shard from his phylactery as proof!]],logDesc=[[Bring Araj's Phylactery Shard to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.]],rewards={{id=17759,qty=1}}}
DB[212]={id=212,zoneId=1519,name=[[A Meal Served Cold]],name_loc=[[Un plato bien frío]],level=40,minLevel=35,giver=[[Angus Stern]],giver_loc=[[Angus Stern]],giverType=[[NPC]],giverId=1141,ender=[[Angus Stern]],ender_loc=[[Angus Stern]],enderType=[[NPC]],enderId=1141,poiX=-9080,poiY=823,wowhead=[[https://www.wowhead.com/wotlk/quest=212]],image=[[assets/images/quests/placeholder.png]],desc=[[One of my most famous dishes is Chilled Basilisk in Lime Vinaigrette.  But the problem is... the meat is impossible to keep fresh, and I must serve the dish tonight for a noble's birthday! So if you can bring me a Chilled Basilisk Haunch from a freshly-killed Cold Eye Basilisk, quickly, then I will owe you a king's feast! Cold Eye Basilisks are known to roam along the beach dunes of northwestern Stranglethorn, so you have much traveling to do.  And be swift!]],logDesc=[[Kill a Cold Eye Basilisk, get a Chilled Basilisk Haunch, and return it to Angus Stern in the Blue Recluse.]]}
DB[213]={id=213,zoneId=33,name=[[Hostile Takeover]],name_loc=[[OPA hostil]],level=36,minLevel=31,giver=[[Kebok]],giverType=[[NPC]],giverId=737,ender=[[Kebok]],enderType=[[NPC]],enderId=737,poiX=-11983,poiY=-814,wowhead=[[https://www.wowhead.com/wotlk/quest=213]],image=[[assets/images/quests/placeholder.png]],desc=[[He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate! Revilgaz won't have it, and he's told me to take care of the problem in my own way. My way? Theft. The Venture Co. geologists near Lake Nazferiti are deeply interested in those strange blue crystals they have been finding in the mines. Bring me samples of the stone from their geologists, I don't care what you have to do to get them.]],logDesc=[[Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.]],rewards={{id=4121,qty=1}}}
DB[214]={id=214,zoneId=1581,name=[[Red Silk Bandanas]],name_loc=[[Pañuelos rojos de seda]],level=17,minLevel=14,giver=[[Scout Riell]],giver_loc=[[Exploradora Riell]],giverType=[[NPC]],giverId=820,ender=[[Scout Riell]],ender_loc=[[Exploradora Riell]],enderType=[[NPC]],enderId=820,prevId=155,poiX=-11199,poiY=1471,wowhead=[[https://www.wowhead.com/wotlk/quest=214]],image=[[assets/images/quests/placeholder.png]],desc=[[It's no secret that the trademark of the Defias Gang is their Red Bandanas.  But we've learned that the material from which these bandanas are made signifies the member's rank. That being said, I want you to eliminate as many high ranking Defias members as you can.  The highest ranking members will undoubtedly be found in VanCleef's secret hideout.  When you're done bring me 10 Red Silk Bandanas as proof of their deaths and I will reward you.  Good luck, $N.]],logDesc=[[Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.]],choiceRewards={{id=2074,qty=1},{id=2089,qty=1},{id=6094,qty=1}}}
DB[215]={id=215,zoneId=33,name=[[Jungle Secrets]],name_loc=[[Los secretos de la jungla]],level=33,minLevel=30,giver=[[Private Thorsen]],giver_loc=[[Soldado Thorsen]],giverType=[[NPC]],giverId=738,ender=[[Lieutenant Doren]],ender_loc=[[Teniente Doren]],enderType=[[NPC]],enderId=469,rewardNextId=200,poiX=-11297,poiY=-207,wowhead=[[https://www.wowhead.com/wotlk/quest=215]],image=[[assets/images/quests/placeholder.png]],desc=[[Thank you for saving me, $N.  I know how this looks, but...allow me to explain. I was charged by Lieutenant Doren to re-enlist with Kurzen's men, so that I might spy on them and bring sorely needed intelligence to the rebels.  You saw here what I had thought would be my chance to infiltrate Kurzen's Compound.  I was wrong, and again, thanks for saving me. This was a top secret mission, so you must tell no one.  But if you speak with Doren he will explain.]],logDesc=[[Speak with Lieutenant Doren at the Rebel Camp.]]}
DB[216]={id=216,zoneId=331,name=[[Between a Rock and a Thistlefur]],name_loc=[[Entre una roca y un Piel de Cardo]],level=24,minLevel=21,giver=[[Karang Amakkar]],giverType=[[NPC]],giverId=12757,ender=[[Karang Amakkar]],enderType=[[NPC]],enderId=12757,poiX=3144,poiY=-251,wowhead=[[https://www.wowhead.com/wotlk/quest=216]],image=[[assets/images/quests/placeholder.png]],desc=[[The Thistlefur furbolgs are threatening our expansion!  Thistlefur Village to our east blocks the way between us here and the Splintertree Post.  It's a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path. $N, we must not allow... an expansion path gap! Proceed to Thistlefur Village and thin out the furbolgs.  You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!]],logDesc=[[Take down 8 Thistlefur Avengers and 8 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village.  Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale.]]}
DB[217]={id=217,zoneId=38,name=[[In Defense of the King's Lands]],name_loc=[[En defensa de las tierras del rey]],level=17,minLevel=10,giver=[[Captain Rugelfuss]],giver_loc=[[Capitán Rugelfuss]],giverType=[[NPC]],giverId=1092,ender=[[Captain Rugelfuss]],ender_loc=[[Capitán Rugelfuss]],enderType=[[NPC]],enderId=1092,prevId=263,poiX=-6151,poiY=-2953,wowhead=[[https://www.wowhead.com/wotlk/quest=217]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, our scouts have identified the leader of this recent Trogg incursion.  It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug.  Grawmug is heavily guarded, however.  Two of his most elite guards, Gnasher and Brawler, never leave his side. If you feel yourself worthy, $N, I want you to lead the assassination mission on Grawmug and his two thugs.  With the Trogg leadership dead, we just might stand a chance at pushing these beasts back into the ground.]],logDesc=[[Kill the Trogg leader, Grawmug, and his two guards, Gnasher and Brawler then report back to Captain Rugelfuss in the southern guard tower.]],choiceRewards={{id=1436,qty=1},{id=6187,qty=1},{id=1832,qty=1}}}
DB[218]={id=218,zoneId=132,name=[[The Stolen Journal]],name_loc=[[El diario robado]],level=5,minLevel=1,giver=[[Grelin Whitebeard]],giver_loc=[[Grelin Barbablanca]],giverType=[[NPC]],giverId=786,ender=[[Grelin Whitebeard]],ender_loc=[[Grelin Barbablanca]],enderType=[[NPC]],enderId=786,prevId=182,rewardNextId=282,poiX=-6509,poiY=301,wowhead=[[https://www.wowhead.com/wotlk/quest=218]],image=[[assets/images/quests/placeholder.png]],desc=[[My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that. You've had some luck with the trolls, maybe you could go get it back for me?]],logDesc=[[Grelin Whitebeard wants you to kill Grik'nir the Cold, and retrieve his journal.]],choiceRewards={{id=6176,qty=1},{id=5581,qty=1}}}
DB[219]={id=219,zoneId=44,name=[[Missing In Action]],name_loc=[[Desaparecido en combate]],level=25,minLevel=19,giver=[[Corporal Keeshan]],giver_loc=[[Cabo Keeshan]],giverType=[[NPC]],giverId=349,ender=[[Marshal Marris]],ender_loc=[[Alguacil Marris]],enderType=[[NPC]],enderId=382,poiX=-9284,poiY=-2298,wowhead=[[https://www.wowhead.com/wotlk/quest=219]],image=[[assets/images/quests/placeholder.png]],desc=[[At last, friends of the Alliance! Help... please...  The last thing I remember these foul Orcs overpowered our regiment.  Most the men were killed. I took a strong blow to the head and everything went black. Now I am held captive in this cave.  Help me, I am hurt badly. I'll need help getting back to town... please... you're my last hope...]],logDesc=[[Protect Corporal Keeshan on the journey back to Redridge.]],choiceRewards={{id=3555,qty=1},{id=1275,qty=1},{id=3431,qty=1}}}
DB[220]={id=220,name=[[Call of Water]],name_loc=[[La llamada del agua]],level=-1,minLevel=20,giver=[[Brine]],giver_loc=[[Salmuera]],giverType=[[NPC]],giverId=5899,ender=[[Islen Waterseer]],ender_loc=[[Islen Vidente del Agua]],enderType=[[NPC]],enderId=5901,prevId=1534,poiX=-1345,poiY=-4048,wowhead=[[https://www.wowhead.com/wotlk/quest=220]],image=[[assets/images/quests/placeholder.png]],desc=[[Islen will have one more task for you before rewarding you with your next totem. The vial of water I've given you is necessary for whatever that task is. Go now and find her. We shall meet again some day.]],logDesc=[[Bring the Vial of Purest Water to Islen Waterseer at the Tidus Stair in the Barrens.]],rewards={{id=6637,qty=1}}}
DB[221]={id=221,zoneId=10,name=[[Worgen in the Woods]],name_loc=[[Ferocanis en el bosque]],level=29,minLevel=23,giver=[[Calor]],giverType=[[NPC]],giverId=663,ender=[[Calor]],enderType=[[NPC]],enderId=663,prevId=173,rewardNextId=222,poiX=-10991,poiY=-984,wowhead=[[https://www.wowhead.com/wotlk/quest=221]],image=[[assets/images/quests/placeholder.png]],desc=[[You might have noticed some larger worgen wandering around with the Shadow Weavers in the woods? From what we can tell, these Dark Runners make up the bulk of the worgen numbers. On my rangings, I've also noticed that they have overrun the Rotting Orchard southwest of town. These worgen are a bit tougher than the last you faced. Be on your guard.]],logDesc=[[Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire.]]}
DB[222]={id=222,zoneId=10,name=[[Worgen in the Woods]],name_loc=[[Ferocanis en el bosque]],level=31,minLevel=23,giver=[[Calor]],giverType=[[NPC]],giverId=663,ender=[[Calor]],enderType=[[NPC]],enderId=663,prevId=221,rewardNextId=223,poiX=-10987,poiY=-1149,wowhead=[[https://www.wowhead.com/wotlk/quest=222]],image=[[assets/images/quests/placeholder.png]],desc=[[Your previous accomplishments have convinced me that you are ready to take on the toughest worgen infesting the woods. Of the worgen that have made their new home here, the Vile Fangs and the Tainted Ones have proven the most dangerous. They've settled down near some of the caves and in the mine to the south. From far away you can even see the light from their bonfires...]],logDesc=[[Kill 8 Nightbane Vile Fang and 8 Nightbane Tainted One worgen for Calor in Darkshire.]]}
DB[223]={id=223,zoneId=10,name=[[Worgen in the Woods]],name_loc=[[Ferocanis en el bosque]],level=31,minLevel=23,giver=[[Calor]],giverType=[[NPC]],giverId=663,ender=[[Jonathan Carevin]],enderType=[[NPC]],enderId=661,prevId=222,poiX=-10599,poiY=-1200,wowhead=[[https://www.wowhead.com/wotlk/quest=223]],image=[[assets/images/quests/placeholder.png]],desc=[[Here you go, $n. Bring this message to Master Carevin. <He quickly removes a piece of faded parchment and offers it to you.> A few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today.]],logDesc=[[Bring Calor's note to Jonathan Carevin.]],rewards={{id=5244,qty=1}},choiceRewards={{id=2902,qty=1},{id=1547,qty=1}}}
DB[224]={id=224,zoneId=38,name=[[In Defense of the King's Lands]],name_loc=[[En defensa de las tierras del rey]],level=12,minLevel=10,giver=[[Mountaineer Cobbleflint]],giver_loc=[[Montaraz Pedernal]],giverType=[[NPC]],giverId=1089,ender=[[Mountaineer Cobbleflint]],ender_loc=[[Montaraz Pedernal]],enderType=[[NPC]],enderId=1089,poiX=-5794,poiY=-2971,wowhead=[[https://www.wowhead.com/wotlk/quest=224]],image=[[assets/images/quests/placeholder.png]],desc=[[We need to protect the Loch, $N!  With so many of the King's soldiers fighting valiantly on remote battlefields, we've become overwhelmed on the home front.  Troggs are tunneling up from every crevice!  The Trogg infestation poses the largest threat to Ironforge.  These disgusting mutants must be destroyed. We need you, brave adventurer, to venture forth and lay waste to the Trogg threat.  Slay 10 Stonesplinter Troggs and 10 Stonesplinter Scouts and report back.]],logDesc=[[Mountaineer Cobbleflint of the southern guard tower wants you to kill 10 Stonesplinter Troggs and 10 Stonesplinter Scouts.]],rewards={{id=414,qty=5}}}
DB[225]={id=225,zoneId=10,name=[[The Weathered Grave]],name_loc=[[La lápida desgastada]],level=30,minLevel=25,giver=[[A Weathered Grave]],giver_loc=[[Una tumba erosionada]],giverType=[[GO]],giverId=61,ender=[[Sirra Von'Indi]],ender_loc=[[Sirra Von'Indi]],enderType=[[NPC]],enderId=268,rewardNextId=227,poiX=-10574,poiY=-1127,wowhead=[[https://www.wowhead.com/wotlk/quest=225]],image=[[assets/images/quests/placeholder.png]],desc=[[The weathered grave marker reads simply: MORGAN LADIMORE <Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>]],logDesc=[[Speak with Sirra Von'Indi in Darkshire.]]}
DB[226]={id=226,zoneId=10,name=[[Wolves at Our Heels]],name_loc=[[Con los lobos en los talones]],level=21,minLevel=19,giver=[[Lars]],giverType=[[NPC]],giverId=893,ender=[[Lars]],enderType=[[NPC]],enderId=893,poiX=-10016,poiY=-482,wowhead=[[https://www.wowhead.com/wotlk/quest=226]],image=[[assets/images/quests/placeholder.png]],desc=[[Sven and I have dangerous days ahead of us, what with the Necromancer to the east and all.  And out here alone as we are, we have to hunt for our own food.  It seems every time I'm heading back to camp with some meat on me, starving or rabid dire wolves come out of the forest wanting a bite.  It goes without saying, living out here is dangerous work! But if you can rid us of some of those wolves, we'd have an easier time of it.  They mostly prowl north and east of here, near the river.]],logDesc=[[Kill 12 Starving Dire Wolves and 8 Rabid Dire Wolves, then return to Lars at Sven's Camp on the western border of Duskwood.]],rewards={{id=1127,qty=5}}}
DB[227]={id=227,zoneId=10,name=[[Morgan Ladimore]],name_loc=[[Morgan Ladimor]],level=30,minLevel=25,giver=[[Sirra Von'Indi]],giver_loc=[[Sirra Von'Indi]],giverType=[[NPC]],giverId=268,ender=[[Commander Althea Ebonlocke]],ender_loc=[[Comandante Althea Cerranegro]],enderType=[[NPC]],enderId=264,prevId=225,rewardNextId=228,poiX=-10560,poiY=-1152,wowhead=[[https://www.wowhead.com/wotlk/quest=227]],image=[[assets/images/quests/placeholder.png]],desc=[[<He searches through the shelves and comes up with a leatherbound book.> If you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.]],logDesc=[[Speak with Commander Althea Ebonlocke in Darkshire.]],rewards={{id=2154,qty=1}}}
DB[228]={id=228,zoneId=10,name=[[Mor'Ladim]],name_loc=[[Mor'Ladim]],level=30,minLevel=25,giver=[[Commander Althea Ebonlocke]],giver_loc=[[Comandante Althea Cerranegro]],giverType=[[NPC]],giverId=264,ender=[[Commander Althea Ebonlocke]],ender_loc=[[Comandante Althea Cerranegro]],enderType=[[NPC]],enderId=264,prevId=227,rewardNextId=229,poiX=-10395,poiY=340,wowhead=[[https://www.wowhead.com/wotlk/quest=228]],image=[[assets/images/quests/placeholder.png]],desc=[[From what my scouts tell me, Mor'Ladim wanders throughout Duskwood, following a strange and meandering path through the cemetery. We buried him out past the house on the hill, you know where that is? There isn't anything I can do to help you, but I wish you good luck.]],logDesc=[[Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.]]}
DB[229]={id=229,zoneId=10,name=[[The Daughter Who Lived]],name_loc=[[La hija superviviente]],level=30,minLevel=25,giver=[[Commander Althea Ebonlocke]],giver_loc=[[Comandante Althea Cerranegro]],giverType=[[NPC]],giverId=264,ender=[[Watcher Ladimore]],ender_loc=[[Vigía Ladimor]],enderType=[[NPC]],enderId=576,prevId=228,rewardNextId=231,poiX=-10566,poiY=-1208,wowhead=[[https://www.wowhead.com/wotlk/quest=229]],image=[[assets/images/quests/placeholder.png]],desc=[[I should have told you this earlier... How do I put this... Morgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.]],logDesc=[[Speak with Watcher Sarah Ladimore in Darkshire.]]}
DB[230]={id=230,zoneId=10,name=[[Sven's Camp]],name_loc=[[El campamento de Sven]],level=25,minLevel=20,giver=[[Mound of loose dirt]],giverType=[[GO]],giverId=59,ender=[[Sven Yorgen]],enderType=[[NPC]],enderId=311,prevId=95,rewardNextId=262,poiX=-10330,poiY=623,wowhead=[[https://www.wowhead.com/wotlk/quest=230]],image=[[assets/images/quests/placeholder.png]],desc=[[Digging through the mound, you find a small, dirt-stained book. The book has no title, but...it has information Sven would like to know.]],logDesc=[[Bring the Book from Sven's Farm to Sven.]]}
DB[231]={id=231,zoneId=10,name=[[A Daughter's Love]],name_loc=[[El amor de una hija]],level=30,minLevel=25,giver=[[Watcher Ladimore]],giver_loc=[[Vigía Ladimor]],giverType=[[NPC]],giverId=576,ender=[[A Weathered Grave]],ender_loc=[[Una tumba erosionada]],enderType=[[GO]],enderId=61,prevId=229,poiX=-10240,poiY=355,wowhead=[[https://www.wowhead.com/wotlk/quest=231]],image=[[assets/images/quests/placeholder.png]],desc=[[Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened. <There are tears in her eyes now, as she slides a ring from her right hand, and presses it into your hands.> And... thank you, $n.]],logDesc=[[Take Sarah Ladimore's ring to Morgan Ladimore's grave.]],rewards={{id=2000,qty=1}}}
DB[232]={id=232,zoneId=1497,name=[[Errand for Apothecary Zinge]],name_loc=[[Un recado para la boticaria Zinge]],level=45,minLevel=38,giver=[[Apothecary Zinge]],giver_loc=[[Boticaria Zinge]],giverType=[[NPC]],giverId=5204,ender=[[Alessandro Luca]],ender_loc=[[Alessandro Luca]],enderType=[[NPC]],enderId=7683,rewardNextId=238,poiX=1528,poiY=311,wowhead=[[https://www.wowhead.com/wotlk/quest=232]],image=[[assets/images/quests/placeholder.png]],desc=[[The Royal Apothecary Society needs your assistance.  Listen closely, and both of us may profit from my plan. Apothecary Keever in the next room may be... touched... but his research does potentially bear fruit if it were pursued by a clever researcher.  Fortunately, I am such a researcher.  I want you to take this purchase order to Alessandro Luca, the proprietor of Blue Moon Odds and Ends; he'll give you a testing kit.  When you have it, bring it back to me and I'll outline your task in detail.]],logDesc=[[Take the purchase order to Alessandro Luca in the Undercity.]]}
DB[233]={id=233,zoneId=132,name=[[Coldridge Valley Mail Delivery]],name_loc=[[Entrega de correo en el Valle de Crestanevada]],level=3,minLevel=1,giver=[[Sten Stoutarm]],giver_loc=[[Sten Brazorrecio]],giverType=[[NPC]],giverId=658,ender=[[Talin Keeneye]],ender_loc=[[Talin Ojoagudo]],enderType=[[NPC]],enderId=714,prevId=179,poiX=-6222,poiY=689,wowhead=[[https://www.wowhead.com/wotlk/quest=233]],image=[[assets/images/quests/placeholder.png]],desc=[[Hm, I don't suppose you'd be willing to do a favor for me, $g lad : lass;? A stack of letters came through the pass today, but I don't have the time to send them along. They're all addressed to Talin Keeneye. You can find him to the west down the road. He's set up camp next to the frozen lake. What do you say?]],logDesc=[[Deliver the stack of letters to Talin Keeneye in Coldridge Valley.]]}
DB[234]={id=234,zoneId=132,name=[[Coldridge Valley Mail Delivery]],name_loc=[[Entrega de correo en el Valle de Crestanevada]],level=4,minLevel=1,giver=[[Talin Keeneye]],giver_loc=[[Talin Ojoagudo]],giverType=[[NPC]],giverId=714,ender=[[Grelin Whitebeard]],ender_loc=[[Grelin Barbablanca]],enderType=[[NPC]],enderId=786,prevId=233,poiX=-6363,poiY=567,wowhead=[[https://www.wowhead.com/wotlk/quest=234]],image=[[assets/images/quests/placeholder.png]],desc=[[If I remember correctly, Grelin's camp is down the road to the southeast. No doubt he'll be eager to get his mail.]],logDesc=[[Deliver the letter to Grelin Whitebeard in Coldridge Valley.]]}
DB[235]={id=235,zoneId=1637,name=[[The Ashenvale Hunt]],name_loc=[[La Caza de Vallefresno]],level=20,minLevel=20,giver=[[Warcaller Gorlach]],giver_loc=[[Clamaguerras Gorlach]],giverType=[[NPC]],giverId=10880,ender=[[Senani Thunderheart]],ender_loc=[[Senani Corazón Atronador]],enderType=[[NPC]],enderId=12696,exGroup=235,poiX=2311,poiY=-2555,wowhead=[[https://www.wowhead.com/wotlk/quest=235]],image=[[assets/images/quests/placeholder.png]],desc=[[Attention, young adventurers!  The wilds of Ashenvale await you! The Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!]],logDesc=[[Speak with Senani Thunderheart at Splintertree Post, Ashenvale.]]}
DB[236]={id=236,zoneId=4197,name=[[Fueling the Demolishers]],level=80,minLevel=78,giver=[[Siege Master Stouthandle]],giverType=[[NPC]],giverId=31108,ender=[[Siege Master Stouthandle]],enderType=[[NPC]],enderId=31108,exGroup=13153,wowhead=[[https://www.wowhead.com/wotlk/quest=236]],image=[[assets/images/quests/placeholder.png]],desc=[[$n! About time you showed up. While the battle may be over, we still need to prepare for the next battle. Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve several eternal embers. The embers are mixed in with coal to fuel the Demolisher and Siege Engines.  Oh, and if you happen to see some of the Horde in the Cauldron, don't hesitate to slay them and take their embers. We can't let them have the advantage in the next battle.]],logDesc=[[Siege Master Stouthandle at Wintergrasp Fortress wants you to retrieve 10 Eternal Embers from Horde players at the Cauldron of Flames.]],rewards={{id=43228,qty=10}}}
DB[237]={id=237,zoneId=38,name=[[In Defense of the King's Lands]],name_loc=[[En defensa de las tierras del rey]],level=15,minLevel=10,giver=[[Mountaineer Gravelgaw]],giver_loc=[[Montaraz Gravagau]],giverType=[[NPC]],giverId=1091,ender=[[Mountaineer Gravelgaw]],ender_loc=[[Montaraz Gravagau]],enderType=[[NPC]],enderId=1091,prevId=224,poiX=-6028,poiY=-2824,wowhead=[[https://www.wowhead.com/wotlk/quest=237]],image=[[assets/images/quests/placeholder.png]],desc=[[Mountaineer Cobbleflint had nothing but good things to say about you, $r.  For that reason I am going to entrust upon you a mission of utmost importance.  We need to keep pressure on the invading Trogg forces until our Dwarven brethren return from the Alliance front. Set forth into the southern hills and kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers.  Your attacks will buy us some time.  Report back when your mission is complete.]],logDesc=[[Mountaineer Gravelgaw in the southern guard tower wants you to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers and report back to him.]],rewards={{id=858,qty=3}}}
DB[238]={id=238,zoneId=1497,name=[[Errand for Apothecary Zinge]],name_loc=[[Un recado para la boticaria Zinge]],level=45,minLevel=38,giver=[[Alessandro Luca]],giver_loc=[[Alessandro Luca]],giverType=[[NPC]],giverId=7683,ender=[[Apothecary Zinge]],ender_loc=[[Boticaria Zinge]],enderType=[[NPC]],enderId=5204,prevId=232,rewardNextId=243,poiX=1528,poiY=311,wowhead=[[https://www.wowhead.com/wotlk/quest=238]],image=[[assets/images/quests/placeholder.png]],desc=[[The kit is ready, $n.  No doubt that Apothecary Zinge will want this as soon as possible.  Take it to her without delay, and let her know that I will add the cost of the kit to the Society's tab.  Also, please extend to her my warmest salutations. Well, don't just stand there.  Such is the life of a simple courier, yes?]],logDesc=[[Bring the Field Sampling Kit to Apothecary Zinge in the Undercity.]]}
DB[239]={id=239,zoneId=12,name=[[Westbrook Garrison Needs Help!]],name_loc=[[El Cuartel de Arroyoeste necesita ayuda]],level=10,minLevel=6,giver=[[Marshal Dughan]],giver_loc=[[Alguacil Dughan]],giverType=[[NPC]],giverId=240,ender=[[Deputy Rainer]],ender_loc=[[Ayudante de alguacil Rainer]],enderType=[[NPC]],enderId=963,prevId=76,rewardNextId=11,poiX=-9663,poiY=694,wowhead=[[https://www.wowhead.com/wotlk/quest=239]],image=[[assets/images/quests/placeholder.png]],desc=[[The Garrison on our western border sends word of increasing gnoll and thief activity.  They're requesting we send more Stormwind soldiers... but we just don't have any to spare! If you can help, we could use it.  Go and speak with Deputy Rainer at the Westbrook Garrison and see what he needs done. The Garrison is down the road to the west.  After you cross the bridge over the small brook it will be to the right.]],logDesc=[[Go to the Westbrook Garrison and speak with Deputy Rainer.]]}
DB[240]={id=240,zoneId=10,name=[[Return to Jitters]],name_loc=[[Regresa junto a Alterio]],level=20,minLevel=17,giver=[[Chef Grual]],giverType=[[NPC]],giverId=272,ender=[[Jitters]],ender_loc=[[Alterio]],enderType=[[NPC]],enderId=288,prevId=93,poiX=-10732,poiY=337,wowhead=[[https://www.wowhead.com/wotlk/quest=240]],image=[[assets/images/quests/placeholder.png]],desc=[[And here we are - "Crab" Cakes ala Grual!]],logDesc=[[Return to Jitters with the Dusky Crab Cakes.]]}
DB[241]={id=241,zoneId=331,name=[[<TEST> HEY MISTER WILSON!]],name_loc=[[<TEST> ¡Eh, señor Wilson!]],level=1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=241]],image=[[assets/images/quests/placeholder.png]],desc=[[Description]],logDesc=[[Log]]}
DB[243]={id=243,zoneId=440,name=[[Into the Field]],name_loc=[[In situ]],level=46,minLevel=38,giver=[[Apothecary Zinge]],giver_loc=[[Boticaria Zinge]],giverType=[[NPC]],giverId=5204,ender=[[Chief Engineer Bilgewhizzle]],ender_loc=[[Ingeniero jefe Pasaquillas]],enderType=[[NPC]],enderId=7407,prevId=238,rewardNextId=379,poiX=-7187,poiY=-3839,wowhead=[[https://www.wowhead.com/wotlk/quest=243]],image=[[assets/images/quests/placeholder.png]],desc=[[You will be headed to the Tanaris desert, testing the tissue consistency of the basilisks, scorpids, and hyena native there.  Obtain tissue samples and use them with the testing kit in tow; expect a chunk of the samples to fail.  I need eight acceptable samples of each creature type. In addition, the goblins of Gadgetzan have a power source that must be used with this kind of modified kit.  Speak to Chief Engineer Bilgewhizzle and acquire one for the kit. Return to me only when you are successful.]],logDesc=[[Speak to Chief Engineer Bilgewhizzle in Gadgetzan about getting a power source for the testing kit.]]}
DB[244]={id=244,zoneId=44,name=[[Encroaching Gnolls]],name_loc=[[Gnolls invasores]],level=16,minLevel=11,giver=[[Guard Parker]],giver_loc=[[Guardia Parker]],giverType=[[NPC]],giverId=464,ender=[[Deputy Feldon]],ender_loc=[[Ayudante de alguacil Feldon]],enderType=[[NPC]],enderId=1070,rewardNextId=246,poiX=-9444,poiY=-2238,wowhead=[[https://www.wowhead.com/wotlk/quest=244]],image=[[assets/images/quests/placeholder.png]],desc=[[Hail, $c.  I am charged to patrol this stretch of road.  Although the road is safe for now, I've seen gnoll encampments to the north and east of here. Lakeshire must know of the gathering gnoll force!  Report to Deputy Feldon in Lakeshire and tell him of the gnolls.  Do this, and I'm sure Feldon will offer you a scout's wage. Feldon's usually inspecting the area south of the bridge to Lakeshire.]],logDesc=[[Report to Deputy Feldon at the bridge south of Lakeshire in Redridge Mountains.]]}
DB[245]={id=245,zoneId=10,name=[[Eight-Legged Menaces]],name_loc=[[Las amenazas de ocho patas]],level=21,minLevel=17,giver=[[Watcher Dodds]],giver_loc=[[Vigía Dodds]],giverType=[[NPC]],giverId=888,ender=[[Watcher Dodds]],ender_loc=[[Vigía Dodds]],enderType=[[NPC]],enderId=888,poiX=-10685,poiY=515,wowhead=[[https://www.wowhead.com/wotlk/quest=245]],image=[[assets/images/quests/placeholder.png]],desc=[[Hail, $c. Perhaps you've seen those spiders that have taken over the western border? The eight-legged menaces are too much for us to handle, and the Commander hasn't enough manpower to spare so far from Darkshire. I hate to ask this of you, but you seem like you might be able to handle them. I can't promise you anything of great value, but I can reward you if you can help root out the filthy bugs. Oh, and a word of advice, you'll want to avoid their venom if you can.]],logDesc=[[Kill 15 Pygmy Venom Web Spiders, and then report back to Watcher Dodds in Duskwood.]],rewards={{id=3559,qty=1}}}
DB[246]={id=246,zoneId=44,name=[[Assessing the Threat]],name_loc=[[Evaluar la amenaza]],level=17,minLevel=11,giver=[[Deputy Feldon]],giver_loc=[[Ayudante de alguacil Feldon]],giverType=[[NPC]],giverId=1070,ender=[[Deputy Feldon]],ender_loc=[[Ayudante de alguacil Feldon]],enderType=[[NPC]],enderId=1070,prevId=244,poiX=-9604,poiY=-2518,wowhead=[[https://www.wowhead.com/wotlk/quest=246]],image=[[assets/images/quests/placeholder.png]],desc=[[We don't have men to spare, but something must be done about those gnolls you reported to me. Scout southern Redridge for gnolls.  Harry them, kill those you can and report back to me with a count of their numbers and an assessment of the threat they present.  You may find those gnolls camped all along the southern road of Redridge. Do this for the Stormwind Army, $N, and you will be rewarded.]],logDesc=[[Kill 10 Redridge Mongrels and 6 Redridge Poachers, then report back to Deputy Feldon in Lakeshire.]]}
DB[247]={id=247,zoneId=331,name=[[The Hunt Completed]],name_loc=[[El fin de la Caza]],level=30,minLevel=20,giver=[[Senani Thunderheart]],giver_loc=[[Senani Corazón Atronador]],giverType=[[NPC]],giverId=12696,ender=[[Senani Thunderheart]],ender_loc=[[Senani Corazón Atronador]],enderType=[[NPC]],enderId=12696,poiX=2311,poiY=-2555,wowhead=[[https://www.wowhead.com/wotlk/quest=247]],image=[[assets/images/quests/placeholder.png]],rewards={{id=16658,qty=1}}}
DB[248]={id=248,zoneId=44,name=[[Looking Further]],name_loc=[[Ver más allá]],level=22,minLevel=20,giver=[[Old Lion Statue]],giver_loc=[[Estatua de león antigua]],giverType=[[GO]],giverId=31,ender=[[An Empty Jar]],ender_loc=[[Un tarro vacío]],enderType=[[GO]],enderId=76,prevId=94,poiX=-9297,poiY=-2944,wowhead=[[https://www.wowhead.com/wotlk/quest=248]],image=[[assets/images/quests/placeholder.png]],desc=[[I have been watching the Tower of Ilgalar, and can detect that Morganth is in conflict with the Orcs in Stonewatch Keep.  I do not know the reason behind their contention, but you may aid me in unraveling this mystery. Take another Glyph of Azora, then go to the top of the intact watch tower beside Stonewatch Keep. Find a suitable object on which to place the Glyph.  A chest or a jar -- some place where the glyph will not be noticed -- will suit my purpose.]],logDesc=[[Climb the intact watch tower beside Stonewatch Keep in Redridge Mountains. Find a suitable container to place the Glyph of Azora.]]}
DB[249]={id=249,zoneId=44,name=[[Morganth]],name_loc=[[Morganth]],level=26,minLevel=20,giver=[[Theocritus]],giver_loc=[[Theocritus]],giverType=[[GO]],giverId=313,ender=[[Theocritus]],ender_loc=[[Theocritus]],enderType=[[NPC]],enderId=313,prevId=248,poiX=-9553,poiY=-728,wowhead=[[https://www.wowhead.com/wotlk/quest=249]],image=[[assets/images/quests/placeholder.png]],desc=[[After much observation, I have discovered Morganth's plans. He searches for the Scythe of Elune...and he may have found it!  If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might. I am not prepared to pit myself against Morganth, but I fear he must be dealt with now.  So you must enter the Tower of Ilgalar and face Morganth. Defeat him, and bring me his Pendant of Shadow.  Do this, and the kingdom will owe you much.]],logDesc=[[Defeat Morganth. Bring his Pendant of Shadow to Theocritus at the Tower of Azora in Elwynn Forest.]],rewards={{id=5274,qty=1}}}
DB[250]={id=250,zoneId=38,name=[[A Dark Threat Looms]],name_loc=[[Se aproxima una oscura amenaza]],level=18,minLevel=16,giver=[[Chief Engineer Hinderweir VII]],giver_loc=[[Ingeniero jefe Hinderweir VII]],giverType=[[NPC]],giverId=1093,ender=[[Suspicious Barrel]],ender_loc=[[Barrica sospechosa]],enderType=[[GO]],enderId=257,rewardNextId=199,poiX=-4731,poiY=-3540,wowhead=[[https://www.wowhead.com/wotlk/quest=250]],image=[[assets/images/quests/placeholder.png]],desc=[[Thank the stars someone is concerned about the well-being of the Dam.  First the destruction of the Thandol Span and then the pillaging of Dun Modr!  I have no doubt that the Dam will be the target of the next Dark Iron threat.  Most of the security detail here was reassigned to the Alliance Front, including my top inspector. That's why I need you, $N.  I spotted some Dark Iron Sappers milling about the eastern ramp of the Dam.   Investigate the area and bring back a clue.]],logDesc=[[Investigate the area near the eastern ramp of the Dam and bring Chief Engineer Hinderweir a clue that might reveal what the Dark Iron Dwarves are up to.]]}
DB[251]={id=251,zoneId=10,name=[[Translate Abercrombie's Note]],name_loc=[[Traduce la nota de Abercrombie]],level=30,minLevel=20,giver=[[Lord Ello Ebonlocke]],giver_loc=[[Lord Ello Cerranegro]],giverType=[[NPC]],giverId=263,ender=[[Sirra Von'Indi]],ender_loc=[[Sirra Von'Indi]],enderType=[[NPC]],enderId=268,prevId=160,poiX=-10574,poiY=-1127,wowhead=[[https://www.wowhead.com/wotlk/quest=251]],image=[[assets/images/quests/placeholder.png]],desc=[[Take the note you gave me to Sirra Von'Indi.  He's very learned in languages and ancient arts - if anyone here can translate this message, it's he.]],logDesc=[[Bring the Letter to Ello to Sirra Von'Indi.]]}
DB[252]={id=252,zoneId=10,name=[[Translation to Ello]],name_loc=[[Una traducción para Ello]],level=30,minLevel=20,giver=[[Sirra Von'Indi]],giver_loc=[[Sirra Von'Indi]],giverType=[[NPC]],giverId=268,ender=[[Lord Ello Ebonlocke]],ender_loc=[[Lord Ello Cerranegro]],enderType=[[NPC]],enderId=263,prevId=401,poiX=-10552,poiY=-1109,wowhead=[[https://www.wowhead.com/wotlk/quest=252]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh my!  If what is written on this note is true, then Abercrombie's done something...unspeakable. You better bring the translated note back to Ello. And do so quickly, for I fear a doom already lumbers toward our town...]],logDesc=[[Bring the Translated Letter to Lord Ello Ebonlocke]],rewards={{id=3248,qty=1}}}
DB[253]={id=253,zoneId=10,name=[[Bride of the Embalmer]],name_loc=[[La novia del embalsamador]],level=30,minLevel=20,giver=[[Lord Ello Ebonlocke]],giver_loc=[[Lord Ello Cerranegro]],giverType=[[NPC]],giverId=263,ender=[[Lord Ello Ebonlocke]],ender_loc=[[Lord Ello Cerranegro]],enderType=[[NPC]],enderId=263,prevId=252,poiX=-10270,poiY=54,wowhead=[[https://www.wowhead.com/wotlk/quest=253]],image=[[assets/images/quests/placeholder.png]],desc=[[The Embalmer is a name told in one of our children's stories.  He was a kindly alchemist, driven mad by the death of his wife, Eliza.  To restore her, he used dark magic to place his own heart within the bosom of his dead spouse. This revived Eliza...but it cursed her with a hunger for human flesh, forcing the Embalmer to keep her buried. His heart is his power.  Find his wife's grave, retrieve his heart, and bring it to me while it still beats.  Do this and his power will be broken.]],logDesc=[[Find Eliza's grave.  Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke.]],rewards={{id=3560,qty=1},{id=6223,qty=1}}}
DB[254]={id=254,zoneId=10,name=[[Digging Through the Dirt]],name_loc=[[Excavar la tierra]],level=35,minLevel=20,giver=[[Eliza's Grave Dirt]],giver_loc=[[Tierra de la tumba de Eliza]],giverType=[[GO]],giverId=51708,ender=[[Eliza's Grave Dirt]],ender_loc=[[Tierra de la tumba de Eliza]],enderType=[[GO]],enderId=51708,prevId=-253,poiX=-10266,poiY=54,wowhead=[[https://www.wowhead.com/wotlk/quest=254]],image=[[assets/images/quests/placeholder.png]]}
DB[255]={id=255,zoneId=38,name=[[Mercenaries]],name_loc=[[Mercenarios]],level=19,minLevel=15,giver=[[Magistrate Bluntnose]],giver_loc=[[Magistrado Narizroma]],giverType=[[NPC]],giverId=1139,ender=[[Magistrate Bluntnose]],ender_loc=[[Magistrado Narizroma]],enderType=[[NPC]],enderId=1139,poiX=-5084,poiY=-4083,wowhead=[[https://www.wowhead.com/wotlk/quest=255]],image=[[assets/images/quests/placeholder.png]],desc=[[Two months just to hear from Ironforge that we'll be spared a handful of soldiers for our own defense, and another two months until they arrive! Bad enough that our town goes unprotected, but the excavation and the dam--the dam!--are open to attacks as well. I've no choice then, it seems. I'll need hired arms. How about you? You seem a likely sort, $c. A group of ogres has set up camp on the northeast of the lake. Perhaps you will be the one to remove the threat to our town?]],logDesc=[[Magistrate Bluntnose of Thelsamar has hired you to kill 4 Mo'grosh Ogres, 4 Mo'grosh Brutes and 4 Mo'grosh Enforcers.]]}
DB[256]={id=256,zoneId=38,name=[[WANTED: Chok'sul]],name_loc=[[SE BUSCA: Chok'sul]],level=22,minLevel=9,giver=[[WANTED]],giver_loc=[[¡Se busca!]],giverType=[[GO]],giverId=256,ender=[[Magistrate Bluntnose]],ender_loc=[[Magistrado Narizroma]],enderType=[[NPC]],enderId=1139,poiX=-4757,poiY=-4191,wowhead=[[https://www.wowhead.com/wotlk/quest=256]],image=[[assets/images/quests/placeholder.png]],desc=[[By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary. Monetary compensation will be provided when proof is brought to the Magistrate of Chok'sul's death. Chok'sul was last seen at the ogre encampment in the northeastern part of Loch Modan.]],logDesc=[[Kill Chok'sul and bring his head to Magistrate Bluntnose of Thelsamar.]],rewards={{id=1449,qty=1}},choiceRewards={{id=6189,qty=1},{id=6191,qty=1}}}
DB[257]={id=257,zoneId=38,name=[[A Hunter's Boast]],name_loc=[[La fanfarronada de un cazador]],level=16,minLevel=11,giver=[[Daryl the Youngling]],giver_loc=[[Daryl el Jovenzuelo]],giverType=[[NPC]],giverId=1187,ender=[[Daryl the Youngling]],ender_loc=[[Daryl el Jovenzuelo]],enderType=[[NPC]],enderId=1187,rewardNextId=258,poiX=-5900,poiY=-4163,wowhead=[[https://www.wowhead.com/wotlk/quest=257]],image=[[assets/images/quests/placeholder.png]],desc=[[Think you can match wits with Daryl the Bold, huh? I should think not! Of course, you're more than welcome to try. Here's a challenge that should prove to be above your abilities, so don't feel too bad if you can't face up to it. A flock of buzzards has nested here in Loch Modan. Why don't you try to take down some of the beasts? Tell you what, if you meet my challenge in fifteen minutes, I'll give you my bow or gun. <He looks you over dismissively.> It seems you haven't much to lose, anyways.]],logDesc=[[Kill 6 Mountain Buzzards and return to Daryl the Youngling in the Farstrider Lodge within 15 minutes.]],choiceRewards={{id=2903,qty=1},{id=2904,qty=1}}}
DB[258]={id=258,zoneId=38,name=[[A Hunter's Challenge]],name_loc=[[El reto de un cazador]],level=17,minLevel=11,giver=[[Daryl the Youngling]],giver_loc=[[Daryl el Jovenzuelo]],giverType=[[NPC]],giverId=1187,ender=[[Daryl the Youngling]],ender_loc=[[Daryl el Jovenzuelo]],enderType=[[NPC]],enderId=1187,prevId=257,poiX=-5186,poiY=-3918,wowhead=[[https://www.wowhead.com/wotlk/quest=258]],image=[[assets/images/quests/placeholder.png]],desc=[[$nath, is it? I can tell you're bursting with pride over completing the first test, hm? As I told you before, it's no large feat. You should try your hand at boar hunting. Trust me, this is no Coldridge Valley boar hunt, so you'd best have a care with them. I'll give you just twelve minutes this time. Don't feel bad if you fail. I'd give you the shirt off my back if you succeeded! Have I ever related to you the story of how I received my famous scar? No? It was two years ago...]],logDesc=[[Kill 5 Elder Mountain Boars and return to Daryl the Youngling in the Farstrider Lodge within 12 minutes.]],rewards={{id=859,qty=1},{id=3572,qty=1}}}
DB[261]={id=261,zoneId=405,name=[[Down the Scarlet Path]],name_loc=[[El sendero Escarlata]],level=39,minLevel=34,giver=[[Brother Anton]],giver_loc=[[Hermano Anton]],giverType=[[NPC]],giverId=1182,ender=[[Brother Anton]],ender_loc=[[Hermano Anton]],enderType=[[NPC]],enderId=1182,rewardNextId=1052,poiX=-2144,poiY=1299,wowhead=[[https://www.wowhead.com/wotlk/quest=261]],image=[[assets/images/quests/placeholder.png]],desc=[[I will be frank.  We are at war with the Scourge.  It is an evil that corrupts our people and infects our land.  It must be stopped before it overwhelms us and drags our world into shadow.  We of the Scarlet Crusade have sworn to fight the Scourge with body and soul. If you are with us, then gather your courage and prove your allegiance--destroy the undead ravagers of Desolace, in the Valley of Bones to the south. Do this, and the Crusade will embrace you.]],logDesc=[[Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point.]]}
DB[262]={id=262,zoneId=10,name=[[The Shadowy Figure]],name_loc=[[La figura en las sombras]],level=25,minLevel=20,giver=[[Sven Yorgen]],giverType=[[NPC]],giverId=311,ender=[[Madame Eva]],ender_loc=[[Lady Eva]],enderType=[[NPC]],enderId=265,prevId=230,rewardNextId=265,poiX=-10532,poiY=-1213,wowhead=[[https://www.wowhead.com/wotlk/quest=262]],image=[[assets/images/quests/placeholder.png]],desc=[[I must know who was that skulker in the shadows I saw the night my family was killed! Please, $N, you have shown your resourcefulness.  Please find that shadowy figure.  I must learn what secrets he holds! I do not have clues that you do not already know, but here - take the book you found at my farm.  Perhaps some of the townsfolk can link this book with its owner.]],logDesc=[[Take the book you found at Sven's farm and show it to townsfolk in Darkshire.]]}
DB[263]={id=263,zoneId=38,name=[[In Defense of the King's Lands]],name_loc=[[En defensa de las tierras del rey]],level=15,minLevel=10,giver=[[Mountaineer Wallbang]],giver_loc=[[Montaraz Muroplof]],giverType=[[NPC]],giverId=1090,ender=[[Mountaineer Wallbang]],ender_loc=[[Montaraz Muroplof]],enderType=[[NPC]],enderId=1090,prevId=237,poiX=-4984,poiY=-3516,wowhead=[[https://www.wowhead.com/wotlk/quest=263]],image=[[assets/images/quests/placeholder.png]],desc=[[The Mountaineers tell me you are quite brave and capable, $N.  We need a $r like you around here.  The Trogg problem isn't getting any better.  The reserves have been called to the front and we're all alone out here.  But now that we have a seasoned $c here, let's see what you can do. Go out and kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers.  Let's see if you live up to your reputation, Trogg-Slayer.]],logDesc=[[Mountaineer Wallbang in the southern guard tower wants you to kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers.]],rewards={{id=2863,qty=3}}}
DB[264]={id=264,zoneId=1638,name=[[Until Death Do Us Part]],name_loc=[[Hasta que la muerte nos separe]],level=15,minLevel=12,giver=[[Clarice Foster]],giverType=[[NPC]],giverId=5543,ender=[[Yuriv's Tombstone]],ender_loc=[[Lápida de Yuriv]],enderType=[[GO]],enderId=24776,poiX=472,poiY=1594,wowhead=[[https://www.wowhead.com/wotlk/quest=264]],image=[[assets/images/quests/placeholder.png]],desc=[[Filthy scum! Leaves me for his damn crusade. Because "the Light is the most important thing we have against the threats the undead pose." Well, what about his children?! What about ME?! Night after night I sat patiently waiting for him... always second to his blasted duty! Well, witness what "justice" brings you, $N! He's dead and I'm bearing the very thing he was trying to stop! Take this piece of junk and put it on his tomb at the Sepulcher. I want nothing to do with it anymore... or him!]],logDesc=[[Place Clarice's Pendant on Yuriv's Tomb in Silverpine.]]}
DB[265]={id=265,zoneId=10,name=[[The Shadowy Search Continues]],name_loc=[[La búsqueda de la figura continúa]],level=25,minLevel=20,giver=[[Madame Eva]],giver_loc=[[Lady Eva]],giverType=[[NPC]],giverId=265,ender=[[Clerk Daltry]],ender_loc=[[Secretario Daltry]],enderType=[[NPC]],enderId=267,prevId=262,rewardNextId=266,poiX=-10560,poiY=-1125,wowhead=[[https://www.wowhead.com/wotlk/quest=265]],image=[[assets/images/quests/placeholder.png]],desc=[[Here is your book back, $N, and I bid you fortune with your search.  If you ask others in town, perhaps they can offer you more clues. And here is one more for you - although the author of this book is a stranger to Darkshire, the book itself was purchased here.]],logDesc=[[See if other townsfolk have clues about the shadowy figure.]]}
DB[266]={id=266,zoneId=10,name=[[Inquire at the Inn]],name_loc=[[Búsqueda en la posada]],level=25,minLevel=20,giver=[[Clerk Daltry]],giver_loc=[[Secretario Daltry]],giverType=[[NPC]],giverId=267,ender=[[Tavernkeep Smitts]],ender_loc=[[Tabernero Smitts]],enderType=[[NPC]],enderId=273,prevId=265,rewardNextId=453,poiX=-10517,poiY=-1159,wowhead=[[https://www.wowhead.com/wotlk/quest=266]],image=[[assets/images/quests/placeholder.png]],desc=[[Here is your book, and good luck with your inquiries. You might want to expand your search to the inn.  If the person whom you seek spent time in town, then chances are someone saw him there.]],logDesc=[[Search the inn for clues about the shadowy figure.]]}
DB[267]={id=267,zoneId=38,name=[[The Trogg Threat]],name_loc=[[La amenaza trogg]],level=12,minLevel=10,giver=[[Captain Rugelfuss]],giver_loc=[[Capitán Rugelfuss]],giverType=[[NPC]],giverId=1092,ender=[[Captain Rugelfuss]],ender_loc=[[Capitán Rugelfuss]],enderType=[[NPC]],enderId=1092,poiX=-6100,poiY=-3050,wowhead=[[https://www.wowhead.com/wotlk/quest=267]],image=[[assets/images/quests/placeholder.png]],desc=[[$C, you may or may not be aware of the Trogg threat looming over Dwarven lands.  With the Ironforge Reserve called up to the Alliance Front, we are left with a fraction of the defense forces needed to keep these lands safe.  My regiment is assigned to watch over the Gate here and we cannot leave our post for fear of invasion. But we need some pressure put on those damned Troggs lurking in the hills.  If you're up to the task, wage an assault on the Troggs.  Bring me back 8 Trogg Stone Teeth as proof.]],logDesc=[[Bring 8 Trogg Stone Teeth to Captain Rugelfuss in the southern guard tower.]]}
DB[268]={id=268,zoneId=10,name=[[Return to Sven]],name_loc=[[Entrega para Sven]],level=25,minLevel=20,giver=[[Jitters]],giver_loc=[[Alterio]],giverType=[[NPC]],giverId=288,ender=[[Sven Yorgen]],enderType=[[NPC]],enderId=311,prevId=453,rewardNextId=323,poiX=-10330,poiY=623,wowhead=[[https://www.wowhead.com/wotlk/quest=268]],image=[[assets/images/quests/placeholder.png]],desc=[[The book you found was only half finished.  I had to leave it at Sven's farm when I fled there... Here.  Take my completed journal to Sven.  It describes more fully what happened at his farm. Although this journal has been my only company these past weeks, if giving it up keeps me from having to face Sven and his wrath, then I do it willingly!]],logDesc=[[Return to Sven with Jitters' completed journal.]]}
DB[269]={id=269,zoneId=10,name=[[Seeking Wisdom]],name_loc=[[En busca de sabiduría]],level=29,minLevel=20,giver=[[Sven Yorgen]],giverType=[[NPC]],giverId=311,ender=[[Bishop Farthing]],ender_loc=[[Obispo Lontananza]],enderType=[[NPC]],enderId=1212,prevId=323,rewardNextId=270,poiX=-8529,poiY=855,wowhead=[[https://www.wowhead.com/wotlk/quest=269]],image=[[assets/images/quests/placeholder.png]],desc=[[Go to the city of Stormwind and speak with Bishop Farthing in the Cathedral of Light.  Give him Jitters' journal and tell him you mean to face Morbent Fel. Although Stormwind has forsaken Darkshire, Farthing is a kind soul and very wise.  He may help you on your quest to save us. Your mission is perilous, but hurry, $N.  With each passing hour, the shadows of Duskwood grow ever darker.]],logDesc=[[Give Jitters' Completed Journal to Bishop Farthing in Stormwind.]]}
DB[270]={id=270,zoneId=10,name=[[The Doomed Fleet]],name_loc=[[La flota maldita]],level=29,minLevel=20,giver=[[Bishop Farthing]],giver_loc=[[Obispo Lontananza]],giverType=[[NPC]],giverId=1212,ender=[[Glorin Steelbrow]],ender_loc=[[Glorin Frenteacerada]],enderType=[[NPC]],enderId=1217,prevId=269,rewardNextId=321,poiX=-3818,poiY=-827,wowhead=[[https://www.wowhead.com/wotlk/quest=270]],image=[[assets/images/quests/placeholder.png]],desc=[[Years ago, the Third Fleet of Kul Tiras sunk along the coasts of The Wetlands, an expanse of marsh north of the dwarven kingdom of Ironforge.  Aboard one ship was a load of Lightforge Iron. This metal is precious to us, for items crafted from it strike with holy truth.  If you are to face Morbent Fel, then you will need such a weapon. Go to Menethil Harbor and speak with my dwarven colleague Glorin Steelbrow.  If that lost metal can be found, he'll know where to look.]],logDesc=[[Go to Menethil Harbor in the Wetlands, and speak with Glorin Steelbrow.]]}
DB[271]={id=271,zoneId=38,name=[[Vyrin's Revenge]],name_loc=[[La venganza de Vyrin]],level=20,minLevel=15,giver=[[Vyrin Swiftwind]],giver_loc=[[Vyrin Vientoveloz]],giverType=[[NPC]],giverId=1156,ender=[[Daryl the Youngling]],ender_loc=[[Daryl el Jovenzuelo]],enderType=[[NPC]],enderId=1187,prevId=258,rewardNextId=531,poiX=-5612,poiY=-3008,wowhead=[[https://www.wowhead.com/wotlk/quest=271]],image=[[assets/images/quests/placeholder.png]],desc=[[I don't suppose you'd be interested in a little payback for His Boldness? Daryl does have some skill, it pains me to say. A year ago, a large bear had been the target of the Farstrider Lodge, but none of the hunters had any luck with him. So, Daryl thought he'd try his hand against him. All he had to show for his effort was that ugly scar over his eye. Kill the bear, and I'm sure even Daryl would be speechless for once. The bear, Ol' Sooty, can be found around his lair in the hills over Thelsamar.]],logDesc=[[Kill Ol' Sooty then show your handiwork to Daryl the Youngling at the Farstrider Lodge.]]}
DB[272]={id=272,name=[[Trial of the Sea Lion]],name_loc=[[La prueba del león marino]],level=-1,minLevel=16,giver=[[Tajarri]],giverType=[[NPC]],giverId=11799,ender=[[Dendrite Starblaze]],ender_loc=[[Dendrita Rafagaestelar]],enderType=[[NPC]],enderId=11802,prevId=29,rewardNextId=5061,poiX=8020,poiY=-2679,wowhead=[[https://www.wowhead.com/wotlk/quest=272]],image=[[assets/images/quests/placeholder.png]],desc=[[For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form. Speak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.]],logDesc=[[Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located. Form the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this. Bring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.]]}
DB[273]={id=273,zoneId=38,name=[[Resupplying the Excavation]],name_loc=[[Aprovisionar la excavación]],level=15,minLevel=10,giver=[[Jern Hornhelm]],giver_loc=[[Jern Cornamenta]],giverType=[[NPC]],giverId=1105,ender=[[Huldar]],enderType=[[NPC]],enderId=2057,prevId=302,rewardNextId=454,poiX=-5764,poiY=-3469,wowhead=[[https://www.wowhead.com/wotlk/quest=273]],image=[[assets/images/quests/placeholder.png]],desc=[[It's not too late though, you're welcome to go look for Huldar. He can't have made it very far, strong as they are, Miran and Saean can only move so fast laden down with those barrels. They're taking the normal route to the site, leaving south out of town and following the curve of the Loch. Shouldn't have a problem finding them unless they've already gotten there.]],logDesc=[[Speak with Huldar.]]}
DB[274]={id=274,zoneId=38,name=[[A Dark Threat Looms]],name_loc=[[Se aproxima una oscura amenaza]],level=18,minLevel=16,giver=[[Ashlan Stonesmirk]],giver_loc=[[Ashlan Risapétrea]],giverType=[[NPC]],giverId=1073,ender=[[Chief Engineer Hinderweir VII]],ender_loc=[[Ingeniero jefe Hinderweir VII]],enderType=[[NPC]],enderId=1093,prevId=161,rewardNextId=278,poiX=-4738,poiY=-3264,wowhead=[[https://www.wowhead.com/wotlk/quest=274]],image=[[assets/images/quests/placeholder.png]],desc=[[This ain't no ordinary blast powder.  Look at the tiny silver crystals.  And the distinct smell!  Why it's clear as daylight that this is Seaforium Powder.  Seaforium is harmless enough.  But once it's wet it could blow Ironforge out of the mountain. The chemical reaction can be defused by mixing four components:  lurker venom, crushed Mo'Grosh crystal, a crocolisk tear and this disarming colloid.  Now tell Hinderweir before it's too late!]],logDesc=[[Ashlan Stonesmirk wants you to return to Chief Engineer Hinderweir in Loch Modan and inform him of the new discovery.]]}
DB[275]={id=275,zoneId=11,name=[[Blisters on The Land]],name_loc=[[Ampollas en la tierra]],level=26,minLevel=20,giver=[[Rethiel the Greenwarden]],giver_loc=[[Rethiel el Guardaverde]],giverType=[[NPC]],giverId=1244,ender=[[Rethiel the Greenwarden]],ender_loc=[[Rethiel el Guardaverde]],enderType=[[NPC]],enderId=1244,prevId=277,poiX=-3180,poiY=-2409,wowhead=[[https://www.wowhead.com/wotlk/quest=275]],image=[[assets/images/quests/placeholder.png]],desc=[[I do not know why, but a festering grows within the Wetlands.  Fen Creepers have risen.  They are diseased, fevered blisters on the land, and for the fever to break they must be dispatched and allowed to settle back into the marshes. The Fen Creepers shamble amidst the waterways of the Wetlands.]],logDesc=[[Kill 8 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands.]],choiceRewards={{id=3558,qty=1},{id=1273,qty=1},{id=2263,qty=1}}}
DB[276]={id=276,zoneId=11,name=[[Tramping Paws]],name_loc=[[Patas sucias]],level=21,minLevel=20,giver=[[Rethiel the Greenwarden]],giver_loc=[[Rethiel el Guardaverde]],giverType=[[NPC]],giverId=1244,ender=[[Rethiel the Greenwarden]],ender_loc=[[Rethiel el Guardaverde]],enderType=[[NPC]],enderId=1244,rewardNextId=277,poiX=-4277,poiY=-2714,wowhead=[[https://www.wowhead.com/wotlk/quest=276]],image=[[assets/images/quests/placeholder.png]],desc=[[The Mosshide Gnolls have lived in the Wetlands peacefully for many years, but now grow in numbers.  Their feet stamp flat the fen's bushes and flowers, and their foul axes cut too much wood to fuel their fires. They are no longer in balance with the land.  For the Wetlands to survive, the Gnolls must be reduced. Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels.  Hunt them to the south, near the Dwarven gate of Algaz.  After you do this, return to me.]],logDesc=[[Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands.]]}
DB[277]={id=277,zoneId=11,name=[[Fire Taboo]],name_loc=[[No al fuego]],level=23,minLevel=20,giver=[[Rethiel the Greenwarden]],giver_loc=[[Rethiel el Guardaverde]],giverType=[[NPC]],giverId=1244,ender=[[Rethiel the Greenwarden]],ender_loc=[[Rethiel el Guardaverde]],enderType=[[NPC]],enderId=1244,prevId=276,rewardNextId=275,poiX=-3882,poiY=-3085,wowhead=[[https://www.wowhead.com/wotlk/quest=277]],image=[[assets/images/quests/placeholder.png]],desc=[[The Mosshides are cutting the trees of the Wetlands, using the trees' flesh to warm themselves with fire.  I will suffer this pain no longer! Rid the Mosshides of their crude flints, the tools they use to make fire.  The flints are borne by all Mosshides except the smaller Mosshide gnolls and Mosshide mongrels.]],logDesc=[[Bring Rethiel the Greenwarden 9 Crude Flints.]],rewards={{id=4606,qty=10}}}
DB[278]={id=278,zoneId=38,name=[[A Dark Threat Looms]],name_loc=[[Se aproxima una oscura amenaza]],level=18,minLevel=16,giver=[[Chief Engineer Hinderweir VII]],giver_loc=[[Ingeniero jefe Hinderweir VII]],giverType=[[NPC]],giverId=1093,ender=[[Chief Engineer Hinderweir VII]],ender_loc=[[Ingeniero jefe Hinderweir VII]],enderType=[[NPC]],enderId=1093,prevId=274,rewardNextId=280,poiX=-5230,poiY=-4212,wowhead=[[https://www.wowhead.com/wotlk/quest=278]],image=[[assets/images/quests/placeholder.png]],desc=[[Begin collecting the disarming materials immediately, $N.  Lurker Venom can be found on the indigenous spiders in Loch Modan.  Crocolisk tears are found here in the Loch as well.  But a Mo'Grosh crystal will be very difficult to procure.  The ogres to the northeast mine them but the crystals are a very rare commodity. We need to be prepared to defuse a Dark Iron attack!  Return to me once you've collected the needed items and I will prepare the mixture.]],logDesc=[[Chief Engineer Hinderweir wants you to gather Lurker Venom, a Mo'grosh Crystal, and a Crocolisk Tear.]]}
DB[279]={id=279,zoneId=11,name=[[Claws from the Deep]],name_loc=[[Zarpas de las profundidades]],level=22,minLevel=20,giver=[[Karl Boran]],giverType=[[NPC]],giverId=1242,ender=[[Karl Boran]],enderType=[[NPC]],enderId=1242,rewardNextId=281,poiX=-3282,poiY=-1247,wowhead=[[https://www.wowhead.com/wotlk/quest=279]],image=[[assets/images/quests/placeholder.png]],desc=[[Murlocs are crawling out from the deep waters and building their villages on the coastline.  They are harassing our fishers and merchants and must be stopped. One of these murlocs, Gobbler, skulks with other bluegill murlocs and harries merchants along the road, always then retreating to the safety of the nearby murloc hovels.  Our merchants are in jeopardy, and we will pay to secure them. Gobbler prowls the river inlet north of here.  Find him, slay his kin, and bring me his head.]],logDesc=[[Kill 12 Bluegill Murlocs. Slay Gobbler and take his head. Bring Gobbler's Head to Karl Boran in Menethil Harbor.]]}
DB[280]={id=280,zoneId=38,name=[[A Dark Threat Looms]],name_loc=[[Se aproxima una oscura amenaza]],level=18,minLevel=16,giver=[[Chief Engineer Hinderweir VII]],giver_loc=[[Ingeniero jefe Hinderweir VII]],giverType=[[NPC]],giverId=1093,ender=[[Explosive Charge]],ender_loc=[[Carga explosiva]],enderType=[[GO]],enderId=1585,prevId=278,rewardNextId=283,poiX=-4751,poiY=-3389,wowhead=[[https://www.wowhead.com/wotlk/quest=280]],image=[[assets/images/quests/placeholder.png]],desc=[[Earlier today I spotted some Dark Iron Insurgents swimming toward the Dam with a large keg.  No Mountaineers were on hand to stop them!  I'm afraid they've planted the Seaforium at the base of the Dam and it could blow at any minute!  Let me combine all these ingredients into the Disarming Mixture.  There we go. Now I need you to take this mixture and stir it into the keg before it's too late!  Hurry!]],logDesc=[[Chief Engineer Hinderweir wants you to swim down to the base of the dam, locate the powder keg and stir in the Disarming Mixture to prevent an explosion.]]}
DB[281]={id=281,zoneId=11,name=[[Reclaiming Goods]],name_loc=[[Recuperación de bienes]],level=25,minLevel=20,giver=[[Karl Boran]],giverType=[[NPC]],giverId=1242,ender=[[Damaged Crate]],ender_loc=[[Cajón dañado]],enderType=[[GO]],enderId=261,prevId=279,rewardNextId=284,poiX=-3288,poiY=-949,wowhead=[[https://www.wowhead.com/wotlk/quest=281]],image=[[assets/images/quests/placeholder.png]],desc=[[Not long ago a merchant vessel, the Blind Princess, was raided by Murlocs.  Although the ship escaped intact, much of its cargo was dragged overboard by the creatures, including a very valuable statuette of Terenas Menethil.  We want that statuette recovered. Search the coastal Murloc hovels for crates, barrels and other evidence of lost cargo.  Find the Menethil Statuette and return it to me.]],logDesc=[[Search the crates and barrels at the coastal Murloc camps.]],rewards={{id=929,qty=5}}}
DB[282]={id=282,zoneId=132,name=[[Senir's Observations]],name_loc=[[Las observaciones de Senir]],level=5,minLevel=1,giver=[[Grelin Whitebeard]],giver_loc=[[Grelin Barbablanca]],giverType=[[NPC]],giverId=786,ender=[[Mountaineer Thalos]],ender_loc=[[Montaraz Thalos]],enderType=[[NPC]],enderId=1965,prevId=218,poiX=-6236,poiY=153,wowhead=[[https://www.wowhead.com/wotlk/quest=282]],image=[[assets/images/quests/placeholder.png]],desc=[[I was planning on sending my apprentice to my brother Senir with my report, but I would feel much better were it placed in more... reliable hands. That is, of course, if you wouldn't mind? Hmm... you'll have to take the tunnel to get to Kharanos. Speak with Mountaineer Thalos before going through the tunnel. It's completely infested with troggs now. Follow the road back to Anvilmar, then keep heading east to the tunnel, Thalos is stationed nearby.]],logDesc=[[Speak with Mountaineer Thalos.]]}
DB[283]={id=283,zoneId=38,name=[[A Dark Threat Looms]],name_loc=[[Se aproxima una oscura amenaza]],level=20,minLevel=16,giver=[[Explosive Charge]],giver_loc=[[Carga explosiva]],giverType=[[GO]],giverId=1585,ender=[[Chief Engineer Hinderweir VII]],ender_loc=[[Ingeniero jefe Hinderweir VII]],enderType=[[NPC]],enderId=1093,prevId=280,poiX=-4738,poiY=-3264,wowhead=[[https://www.wowhead.com/wotlk/quest=283]],image=[[assets/images/quests/placeholder.png]],desc=[[The keg fizzles slightly.]],logDesc=[[The Disarming Mixture seemed to take effect.  Return to Chief Engineer Hinderweir to report the good news.]],choiceRewards={{id=2907,qty=1},{id=2908,qty=1}}}
DB[284]={id=284,zoneId=11,name=[[The Search Continues]],name_loc=[[La búsqueda continúa]],level=25,minLevel=20,giver=[[Damaged Crate]],giver_loc=[[Cajón dañado]],giverType=[[GO]],giverId=261,ender=[[Sealed Barrel]],ender_loc=[[Barrica sellada]],enderType=[[GO]],enderId=142151,prevId=281,rewardNextId=285,poiX=-3201,poiY=-952,wowhead=[[https://www.wowhead.com/wotlk/quest=284]],image=[[assets/images/quests/placeholder.png]],desc=[[You thoroughly search this cluster of Murloc hovels, and find no trace of the Menethil Statuette. Perhaps one of the two nearby hovels to the north and northeast will have more clues.]],logDesc=[[Search for the Menethil Statuette.]],rewards={{id=422,qty=10}}}
DB[285]={id=285,zoneId=11,name=[[Search More Hovels]],name_loc=[[Inspecciona más casuchas]],level=25,minLevel=20,giver=[[Sealed Barrel]],giver_loc=[[Barrica sellada]],giverType=[[GO]],giverId=142151,ender=[[Half-buried Barrel]],ender_loc=[[Barrica semienterrada]],enderType=[[GO]],enderId=259,prevId=284,rewardNextId=286,poiX=-3107,poiY=-966,wowhead=[[https://www.wowhead.com/wotlk/quest=285]],image=[[assets/images/quests/placeholder.png]],desc=[[This grouping of Murloc hovels, after a thorough inspection, reveals nothing. ...but you're certain that the next clue you find will be fruitful. One of the hovels to the north must have the Menethil Statuette!]],logDesc=[[Continue searching the Murloc hovels for the Menethil Statuette.]]}
DB[286]={id=286,zoneId=11,name=[[Return the Statuette]],name_loc=[[Devuelve la Estatuilla]],level=25,minLevel=20,giver=[[Half-buried Barrel]],giver_loc=[[Barrica semienterrada]],giverType=[[GO]],giverId=259,ender=[[Karl Boran]],enderType=[[NPC]],enderId=1242,prevId=285,poiX=-3762,poiY=-735,wowhead=[[https://www.wowhead.com/wotlk/quest=286]],image=[[assets/images/quests/placeholder.png]],desc=[[After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw.  It depicts a young, long-haired Paladin with hammer upraised. This must be the Menethil Statuette!  You must now return it to Karl Boran in Menethil Harbor.]],logDesc=[[Bring Karl Boran at Menethil Harbor in Wetlands the Menethil Statuette.]],choiceRewards={{id=2950,qty=1},{id=2949,qty=1}}}
DB[287]={id=287,zoneId=1,name=[[Frostmane Hold]],name_loc=[[Poblado Peloescarcha]],level=9,minLevel=7,giver=[[Senir Whitebeard]],giver_loc=[[Senir Barbablanca]],giverType=[[NPC]],giverId=1252,ender=[[Senir Whitebeard]],ender_loc=[[Senir Barbablanca]],enderType=[[NPC]],enderId=1252,prevId=420,rewardNextId=291,poiX=-5566,poiY=514,wowhead=[[https://www.wowhead.com/wotlk/quest=287]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm behind on my report, and could use your help, $n. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in. Here's what I need... Go down to the cave, poke around inside, kill a few of the trolls, then come back here. Take the road north out of Kharanos, when you get to the bridge, follow the frozen river west until you reach Iceflow Lake. You'll find Brewnall Village on the west bank. The Hold is southwest of the village.]],logDesc=[[Explore Frostmane Hold, and kill 5 Frostmane Headhunters for Senir Whitebeard in Kharanos.]],choiceRewards={{id=3216,qty=1},{id=2900,qty=1}}}
DB[288]={id=288,zoneId=11,name=[[The Third Fleet]],name_loc=[[La Tercera Flota]],level=27,minLevel=22,giver=[[First Mate Fitzsimmons]],giver_loc=[[Contramaestre Fistimos]],giverType=[[NPC]],giverId=1239,ender=[[First Mate Fitzsimmons]],ender_loc=[[Contramaestre Fistimos]],enderType=[[NPC]],enderId=1239,rewardNextId=289,poiX=-3792,poiY=-840,wowhead=[[https://www.wowhead.com/wotlk/quest=288]],image=[[assets/images/quests/placeholder.png]],desc=[[I was once First Mate on the Wave Mistress, ship-of-the-line in the Kul Tiras Third Fleet.  The Doomed Fleet.  Doomed, for on its last voyage the fleet was attacked  by Red Dragons.  Dragons controlled by Orcs! We didn't stand a chance against that dragonfire...and our fleet was burned and sunk off this here coast.  I'm the sole survivor of those poor vessels... ...Oh, my head hammers and pounds!  I'll need a fresh drink if I'm to get a handle on this hangover and continue my tale.]],logDesc=[[Buy First Mate Fitzsimmons a Flagon of Mead.]]}
DB[289]={id=289,zoneId=11,name=[[The Cursed Crew]],name_loc=[[La tripulación maldita]],level=29,minLevel=22,giver=[[First Mate Fitzsimmons]],giver_loc=[[Contramaestre Fistimos]],giverType=[[NPC]],giverId=1239,ender=[[First Mate Fitzsimmons]],ender_loc=[[Contramaestre Fistimos]],enderType=[[NPC]],enderId=1239,prevId=288,rewardNextId=290,poiX=-2794,poiY=-1017,wowhead=[[https://www.wowhead.com/wotlk/quest=289]],image=[[assets/images/quests/placeholder.png]],desc=[[<Bolstered, Fitzsimmons continues his tale...> I am the sole survivor of the ill-fated Third Fleet of Kul Tiras, wrecked off the coast to the north.  But although I'm the only member of the fleet still breathing, I'm not the only one still walking about!  For on one of our ships was hidden a great, and terrible treasure, and the eerie power of it keeps the souls of my brothers trapped within the ships' rotting hulls. But if you can free some of my brothers, then perhaps you can break their curse.]],logDesc=[[Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig.  Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor.]]}
DB[290]={id=290,zoneId=11,name=[[Lifting the Curse]],name_loc=[[Purga de la maldición]],level=30,minLevel=22,giver=[[First Mate Fitzsimmons]],giver_loc=[[Contramaestre Fistimos]],giverType=[[NPC]],giverId=1239,ender=[[Intrepid's Locked Strongbox]],ender_loc=[[Caja fuerte de El Intrépido cerrada]],enderType=[[GO]],enderId=112948,prevId=289,rewardNextId=292,poiX=-2799,poiY=-1028,wowhead=[[https://www.wowhead.com/wotlk/quest=290]],image=[[assets/images/quests/placeholder.png]],desc=[[To break the curse and free all of my brethren, the...thing...stowed on my ship must be retrieved and cleansed!  I don't know what it was, but I do know that it was stored securely in the ship's strongbox, which Captain Halyndor lorded over. My old captain is still in my dreams.  I know he walks my doomed ship, the Intrepid.  Get the key from him, and use it to open the Intrepid's strongbox. Then, after you have the cursed thing, bring it to the priest Glorin Steelbrow in town.]],logDesc=[[Get the Intrepid Strongbox Key from Captain Halyndor. Use the key to open the Intrepid's Locked Strongbox.]]}
DB[291]={id=291,zoneId=1,name=[[The Reports]],name_loc=[[Los informes]],level=10,minLevel=1,giver=[[Senir Whitebeard]],giver_loc=[[Senir Barbablanca]],giverType=[[NPC]],giverId=1252,ender=[[Senator Barin Redstone]],ender_loc=[[Senador Barin Rocarroja]],enderType=[[NPC]],enderId=1274,prevId=287,poiX=-4873,poiY=-1026,wowhead=[[https://www.wowhead.com/wotlk/quest=291]],image=[[assets/images/quests/placeholder.png]],desc=[[Excellent! Take my report to Senator Barin Redstone. He's a sour type, so don't let his less-than-sunny disposition get to you. He's in Ironforge, in the chamber where King Magni holds court. Don't know the way to Ironforge? Take the road out of Kharanos north, cross the bridge, then follow the road east--there are large banners flanking the road--up the mountainside. By the way, if you might avoid mentioning how you assisted me? Can't let them think I'm not working hard out here, you know?]],logDesc=[[Deliver Senir's report to Senator Barin Redstone in Ironforge.]]}
DB[292]={id=292,zoneId=11,name=[[The Eye of Paleth]],name_loc=[[El ojo de Paleth]],level=30,minLevel=22,giver=[[Intrepid's Locked Strongbox]],giver_loc=[[Caja fuerte de El Intrépido cerrada]],giverType=[[GO]],giverId=112948,ender=[[Glorin Steelbrow]],ender_loc=[[Glorin Frenteacerada]],enderType=[[NPC]],enderId=1217,prevId=290,rewardNextId=293,poiX=-3818,poiY=-827,wowhead=[[https://www.wowhead.com/wotlk/quest=292]],image=[[assets/images/quests/placeholder.png]],desc=[[Opening the chest reveals a blackened orb, pulsing with an eerie light.  It is the treasure of which Fitzsimmons spoke: a Cursed Eye of Paleth. Take the Cursed Eye of Paleth to the dwarven priest Glorin Steelbrow, in Menethil Harbor.  Ask him how to remove the Eye's curse.]],logDesc=[[Bring the Cursed Eye of Paleth to Glorin Steelbrow at Menethil Harbor in Wetlands.]]}
DB[293]={id=293,zoneId=11,name=[[Cleansing the Eye]],name_loc=[[Limpieza del ojo]],level=30,minLevel=22,giver=[[Glorin Steelbrow]],giver_loc=[[Glorin Frenteacerada]],giverType=[[NPC]],giverId=1217,ender=[[Archbishop Benedictus]],ender_loc=[[Arzobispo Benedictus]],enderType=[[NPC]],enderId=1284,prevId=292,poiX=-8523,poiY=849,wowhead=[[https://www.wowhead.com/wotlk/quest=293]],image=[[assets/images/quests/placeholder.png]],desc=[[I can't lift the curse from the Eye of Paleth.  The Eyes were crafted by Human Priests, so you'll have to go to Stormwind to find someone who can help you.  Speak with Archbishop Benedictus.  He is head of the Cathedral of Light in Stormwind.  He can help. I hope, for your sake.]],logDesc=[[Bring Archbishop Benedictus the Cursed Eye of Paleth.  Benedictus is in the Cathedral of Light, in the city of Stormwind.]],rewards={{id=2943,qty=1}}}
DB[294]={id=294,zoneId=11,name=[[Ormer's Revenge]],name_loc=[[La venganza de Ormer]],level=24,minLevel=22,giver=[[Ormer Ironbraid]],giver_loc=[[Ormer Trenzaferro]],giverType=[[NPC]],giverId=1078,ender=[[Ormer Ironbraid]],ender_loc=[[Ormer Trenzaferro]],enderType=[[NPC]],enderId=1078,rewardNextId=295,poiX=-3316,poiY=-1685,wowhead=[[https://www.wowhead.com/wotlk/quest=294]],image=[[assets/images/quests/placeholder.png]],desc=[[The situation is severe, that much is for sure.  When we uncovered these bones it attracted the Raptors.  These filthy beasts killed my brethren and trapped me, Merrin and the poor Prospector up here. Help clear the Wetlands of these Raptors, $N.  Mottled Raptors and Mottled Screechers are just West of the bluff there.  Kill 10 of each, if you can. That will be a good start to the vengeance I have planned for them.]],logDesc=[[Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors.]]}
DB[295]={id=295,zoneId=11,name=[[Ormer's Revenge]],name_loc=[[La venganza de Ormer]],level=27,minLevel=22,giver=[[Ormer Ironbraid]],giver_loc=[[Ormer Trenzaferro]],giverType=[[NPC]],giverId=1078,ender=[[Ormer Ironbraid]],ender_loc=[[Ormer Trenzaferro]],enderType=[[NPC]],enderId=1078,prevId=294,rewardNextId=296,poiX=-3483,poiY=-1882,wowhead=[[https://www.wowhead.com/wotlk/quest=295]],image=[[assets/images/quests/placeholder.png]],desc=[[Now it's time to really make those dreaded Raptors regret their blood-thirst.  Just down below there are scores of Mottled Scytheclaws and Mottled Razormaws.  Make those rotten creatures pay by slaying 10 of each!]],logDesc=[[Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site.]]}
DB[296]={id=296,zoneId=11,name=[[Ormer's Revenge]],name_loc=[[La venganza de Ormer]],level=29,minLevel=22,giver=[[Ormer Ironbraid]],giver_loc=[[Ormer Trenzaferro]],giverType=[[NPC]],giverId=1078,ender=[[Ormer Ironbraid]],ender_loc=[[Ormer Trenzaferro]],enderType=[[NPC]],enderId=1078,prevId=295,poiX=-3567,poiY=-1765,wowhead=[[https://www.wowhead.com/wotlk/quest=296]],image=[[assets/images/quests/placeholder.png]],desc=[[While you were down there I happened to notice that one of those beasts stood out from the rest.  He was bigger and more menacing.  I bet he's the one who led the others here to cause the disruption to the dig site. I ask of you now one final task, $N.  See to it that Sarltooth is brought to justice.  And considering the gravity of his crimes, justice in this case means death!  Bring me one of his talons as proof of his death.]],logDesc=[[Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled.]],rewards={{id=3682,qty=1}},choiceRewards={{id=3493,qty=1},{id=3566,qty=1},{id=5246,qty=1}}}
DB[297]={id=297,zoneId=38,name=[[Gathering Idols]],name_loc=[[Recoger ídolos]],level=18,minLevel=13,giver=[[Magmar Fellhew]],giver_loc=[[Magmar Ceñimal]],giverType=[[NPC]],giverId=1345,ender=[[Magmar Fellhew]],ender_loc=[[Magmar Ceñimal]],enderType=[[NPC]],enderId=1345,prevId=436,poiX=-5667,poiY=-4015,wowhead=[[https://www.wowhead.com/wotlk/quest=297]],image=[[assets/images/quests/placeholder.png]],desc=[[Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols.  But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!  And those idols have a strange effect on the Troggs.  It makes them go berserk! Bring me 8 idols - I want to study them, and I want them out of Trogg hands!  You can find the idols on the Troggs infesting the site.]],logDesc=[[Bring Magmar Fellhew 8 Carved Stone Idols.]],choiceRewards={{id=5241,qty=1},{id=6186,qty=1},{id=3154,qty=1}}}
DB[298]={id=298,zoneId=38,name=[[Excavation Progress Report]],name_loc=[[Un informe sobre el avance de la excavación]],level=15,minLevel=10,giver=[[Prospector Ironband]],giver_loc=[[Prospector Vetaferro]],giverType=[[NPC]],giverId=1344,ender=[[Jern Hornhelm]],ender_loc=[[Jern Cornamenta]],enderType=[[NPC]],enderId=1105,rewardNextId=301,poiX=-5352,poiY=-3014,wowhead=[[https://www.wowhead.com/wotlk/quest=298]],image=[[assets/images/quests/placeholder.png]],desc=[[I need a progress report sent to Thelsamar - a progress report, and a restatement of my request for more blastpowder!  Here's the report.  Take it to Jern Hornhelm.  He's our local contact in Thelsamar. It's not a difficult task, but it must be done.]],logDesc=[[Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar.]]}
DB[299]={id=299,zoneId=11,name=[[Uncovering the Past]],name_loc=[[Desvelando el pasado]],level=28,minLevel=25,giver=[[Prospector Whelgar]],giver_loc=[[Prospector Whelgar]],giverType=[[NPC]],giverId=1077,ender=[[Prospector Whelgar]],ender_loc=[[Prospector Whelgar]],enderType=[[NPC]],enderId=1077,poiX=-3481,poiY=-1871,wowhead=[[https://www.wowhead.com/wotlk/quest=299]],image=[[assets/images/quests/placeholder.png]],desc=[[Just before the invasion I uncovered a large tablet called the Goaz Stone.  The translated text breaks off in 4 places.  The text speaks of a "divine plan" and a "doomed prophecy." I fear we are running out of time.  I am too old to go down and brave those beasts.  But you are strong. Scour the excavation site and uncover the 4 missing tablet fragments: Ados, Modr, Golm and Neru.  Search for them in ancient artifacts or where the soil is loose.  Bring them to me so I can begin unlocking the mystery!]],logDesc=[[Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru.]],rewards={{id=2913,qty=1}}}
DB[301]={id=301,zoneId=38,name=[[Report to Ironforge]],name_loc=[[Informe a Forjaz]],level=15,minLevel=10,giver=[[Jern Hornhelm]],giver_loc=[[Jern Cornamenta]],giverType=[[NPC]],giverId=1105,ender=[[Prospector Stormpike]],ender_loc=[[Prospector Pico Tormenta]],enderType=[[NPC]],enderId=1356,prevId=298,rewardNextId=302,poiX=-4631,poiY=-1304,wowhead=[[https://www.wowhead.com/wotlk/quest=301]],image=[[assets/images/quests/placeholder.png]],desc=[[We'll need approval to get Ironband more blastpowder. You'll have to take his report to the Explorers' League headquarters in Ironforge. Here's the report. Give it to Prospector Stormpike, and don't forget to duck after you deliver it. Stormpike is hotheaded, and he won't be happy to hear of Ironband's slow progress at the site. You'll find Stormpike in the Assembly of Explorers.]],logDesc=[[Take Ironband's Progress Report to Prospector Stormpike.]]}
DB[302]={id=302,zoneId=38,name=[[Powder to Ironband]],name_loc=[[Pólvora para Vetaferro]],level=15,minLevel=10,giver=[[Prospector Stormpike]],giver_loc=[[Prospector Pico Tormenta]],giverType=[[NPC]],giverId=1356,ender=[[Jern Hornhelm]],ender_loc=[[Jern Cornamenta]],enderType=[[NPC]],enderId=1105,prevId=301,rewardNextId=273,poiX=-5352,poiY=-3014,wowhead=[[https://www.wowhead.com/wotlk/quest=302]],image=[[assets/images/quests/placeholder.png]],desc=[[If Ironband still needs blastpowder, then by Magni he'll have it!  I sent the approval on ahead with a messenger to Jern Hornhelm in Thelsamar.  He'll prepare the powder and other supplies to take to Ironband. And one more thing: I want you to personally see that the shipment of powder reaches its destination.  The last one didn't, so keep your mind sharp and your eyes open.]],logDesc=[[Speak with Jern Hornhelm at Thelsamar in Loch Modan.]]}
DB[303]={id=303,zoneId=11,name=[[The Dark Iron War]],name_loc=[[La guerra contra los Hierro Negro]],level=30,minLevel=25,giver=[[Motley Garmason]],giverType=[[NPC]],giverId=1074,ender=[[Motley Garmason]],enderType=[[NPC]],enderId=1074,poiX=-2580,poiY=-2432,wowhead=[[https://www.wowhead.com/wotlk/quest=303]],image=[[assets/images/quests/placeholder.png]],desc=[[War rages both home and abroad.  While mighty Dwarven soldiers give their lives in far off territories in the name of the Alliance, our own lands fall prey to the evil deeds of the Dark Iron Dwarves.  They laid waste to the Thandol Span.  Dun Modr fell soon after. We need you to gather force and push the front back.  If you can kill 10 Dark Iron Dwarves, 5 Tunnelers, 5 Saboteurs and 5 Demolitionists, the reserve might arrive in time to finish the drive. Now make haste!]],logDesc=[[Motley Garmason at Dun Modr wants you to kill 10 Dark Iron Dwarves,  5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.]]}
DB[304]={id=304,zoneId=11,name=[[A Grim Task]],name_loc=[[Una misión hedionda]],level=31,minLevel=26,giver=[[Longbraid the Grim]],giver_loc=[[Largatrenza el Nefasto]],giverType=[[NPC]],giverId=1071,ender=[[Longbraid the Grim]],ender_loc=[[Largatrenza el Nefasto]],enderType=[[NPC]],enderId=1071,poiX=-2932,poiY=-2973,wowhead=[[https://www.wowhead.com/wotlk/quest=304]],image=[[assets/images/quests/placeholder.png]],desc=[[Many of my soldiers died in the battle of Dun Modr. My own brother perished when the West Bridge over the Thandol Span was destroyed.  Aye, the Dark Iron dwarves are a devilish breed.  From what Roggo was able to gather, the leader of the thugs in the Wetlands is a warlock named Balgaras the Foul. He is quite a coward, sending his soldiers to do his bidding but hides in his camp on Direforge Hill, to the southeast. If you can find the spineless scum, slay him and bring me his ear. I will reward you, $c.]],logDesc=[[Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr.]],choiceRewards={{id=2916,qty=1},{id=2917,qty=1}}}
DB[305]={id=305,zoneId=11,name=[[In Search of The Excavation Team]],name_loc=[[La búsqueda del equipo de excavación]],level=24,minLevel=21,giver=[[Tarrel Rockweaver]],giver_loc=[[Tarrel Tejepiedra]],giverType=[[NPC]],giverId=2096,ender=[[Merrin Rockweaver]],ender_loc=[[Merrin Tejepiedra]],enderType=[[NPC]],enderId=1076,rewardNextId=306,poiX=-3591,poiY=-1999,wowhead=[[https://www.wowhead.com/wotlk/quest=305]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh my, you must be the scout Longbraid said he would send!  You cannot imagine how worried I have been. My wife, Merrin, has been sending me letters each week for the past month.  She is part of the Whelgar Excavation team.  But it has been nearly two weeks since her last correspondence.  Surely something is wrong! Longbraid said that he would send a scout to check up on things if we did not hear from the team soon.  I assume that scout is you, $N.  Find Merrin at the excavation site to the east!]],logDesc=[[Tarrel Rockweaver wants you to travel to the Excavation Site and contact Merrin Rockweaver.]]}
DB[306]={id=306,zoneId=11,name=[[In Search of The Excavation Team]],name_loc=[[La búsqueda del equipo de excavación]],level=24,minLevel=21,giver=[[Merrin Rockweaver]],giver_loc=[[Merrin Tejepiedra]],giverType=[[NPC]],giverId=1076,ender=[[Tarrel Rockweaver]],ender_loc=[[Tarrel Tejepiedra]],enderType=[[NPC]],enderId=2096,prevId=305,poiX=-3585,poiY=-864,wowhead=[[https://www.wowhead.com/wotlk/quest=306]],image=[[assets/images/quests/placeholder.png]],desc=[[It was horrible!  We were uncovering some rare artifacts and we began to discover these large bones. Before we knew what was happening, these Mottled Raptors overwhelmed the dig site.  Many lives were lost. Ormer here -- so brave -- saved the Prospector and me.  He defended us as we ran for shelter.  Now we are trapped.  And our hard work lies in ruin. Here, take this note back to my sweet Tarrel.  It will explain the situation to him.]],logDesc=[[Return to Tarrel Rockweaver at Menethil Harbor in Wetlands with Merrin's note.]]}
DB[307]={id=307,zoneId=38,name=[[Filthy Paws]],name_loc=[[Zarpas asquerosas]],level=15,minLevel=9,giver=[[Mountaineer Stormpike]],giver_loc=[[Montaraz Pico Tormenta]],giverType=[[NPC]],giverId=1343,ender=[[Mountaineer Stormpike]],ender_loc=[[Montaraz Pico Tormenta]],enderType=[[NPC]],enderId=1343,poiX=-4967,poiY=-3007,wowhead=[[https://www.wowhead.com/wotlk/quest=307]],image=[[assets/images/quests/placeholder.png]],desc=[[The Silver Stream Mine to the east ran dry long ago.  It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools! We'll root out those vermin soon enough, but the League wants someone to get their gear out of the mine before we warriors tromp in there and break things.  It'll be a tough delve - you might want cohorts at your side. The gear is stored in Miners' League Crates throughout the mine.  Good luck.]],logDesc=[[Go to the Silver Stream Mine and collect 4 loads of Miners' Gear. Return to Mountaineer Stormpike.]],choiceRewards={{id=3166,qty=1},{id=3161,qty=1},{id=3160,qty=1}}}
DB[308]={id=308,zoneId=1,name=[[Distracting Jarven]],name_loc=[[Distraer a Jarven]],level=7,minLevel=1,giver=[[Jarven Thunderbrew]],giver_loc=[[Jarven Cebatruenos]],giverType=[[NPC]],giverId=1373,ender=[[Jarven Thunderbrew]],ender_loc=[[Jarven Cebatruenos]],enderType=[[NPC]],enderId=1373,prevId=-310,poiX=-5602,poiY=-531,wowhead=[[https://www.wowhead.com/wotlk/quest=308]],image=[[assets/images/quests/placeholder.png]]}
DB[309]={id=309,zoneId=38,name=[[Protecting the Shipment]],name_loc=[[Proteger el envío]],level=15,minLevel=10,giver=[[Miran]],giverType=[[NPC]],giverId=1379,ender=[[Prospector Ironband]],ender_loc=[[Prospector Vetaferro]],enderType=[[NPC]],enderId=1344,prevId=454,poiX=-5695,poiY=-3812,wowhead=[[https://www.wowhead.com/wotlk/quest=309]],image=[[assets/images/quests/placeholder.png]],desc=[[Ready to go, $n? First, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me. I'll feel a lot better with you coming along.]],logDesc=[[Ensure Miran and the shipment arrive at the excavation site, then inform Prospector Ironband.]],choiceRewards={{id=3217,qty=1},{id=6188,qty=1}}}
DB[310]={id=310,zoneId=1,name=[[Bitter Rivals]],name_loc=[[Rivales acérrimos]],level=6,minLevel=2,giver=[[Marleth Barleybrew]],giver_loc=[[Marleth Cebadiz]],giverType=[[NPC]],giverId=1375,ender=[[Unguarded Thunder Ale Barrel]],ender_loc=[[Barrica de Cerveza del Trueno sin vigilar]],enderType=[[GO]],enderId=270,rewardNextId=311,poiX=-5607,poiY=-548,wowhead=[[https://www.wowhead.com/wotlk/quest=310]],image=[[assets/images/quests/placeholder.png]],desc=[[I have to admit, those Thunderbrews make some good drinks.  But they need to learn that theirs isn't the only decent brew!  Maybe you can help me teach them that lesson... Here, take this barrel of Barleybrew Scalder.  Sneak into the basement of the Thunderbrew Distillery in Kharanos and switch it with one of their barrels of Thunder Ale.  Then we'll see how their patrons like my brew over theirs! And if the barrels are guarded, then you might have to distract the guard ...]],logDesc=[[In the basement of the Thunderbrew Distillery in Kharanos, replace a barrel of Thunder Ale with a Barrel of Barleybrew Scalder.]]}
DB[311]={id=311,zoneId=1,name=[[Return to Marleth]],name_loc=[[Regresa junto a Marleth]],level=7,minLevel=2,giver=[[Unguarded Thunder Ale Barrel]],giver_loc=[[Barrica de Cerveza del Trueno sin vigilar]],giverType=[[GO]],giverId=270,ender=[[Marleth Barleybrew]],ender_loc=[[Marleth Cebadiz]],enderType=[[NPC]],enderId=1375,prevId=310,poiX=-5372,poiY=315,wowhead=[[https://www.wowhead.com/wotlk/quest=311]],image=[[assets/images/quests/placeholder.png]],desc=[[Having inserted a barrel of Marleth's Scalder in the Kharanos Distillery's cellar, you grab a barrel of Thunder Ale as proof of the deed...]],logDesc=[[Bring the barrel of Thunder Ale to Marleth Barleybrew at the Brewnall Village.]]}
DB[312]={id=312,zoneId=1,name=[[Tundra MacGrann's Stolen Stash]],name_loc=[[La reserva robada de Tundra MacGrann]],level=12,minLevel=7,giver=[[Tundra MacGrann]],giverType=[[NPC]],giverId=1266,ender=[[Tundra MacGrann]],enderType=[[NPC]],enderId=1266,poiX=-5648,poiY=-95,wowhead=[[https://www.wowhead.com/wotlk/quest=312]],image=[[assets/images/quests/placeholder.png]],desc=[[I had a month's worth of dried meats salted and locked away for the cold season.  Kept it locked so the bears wouldn't get it!  But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker.  He won't be able to smash through that Thorium though.  But I'll starve if I can't get my meats back. You seem a bit more stealthy than me.  Perhaps you can retrieve my stash?  I'll never make it in and out of that cave fast enough with this bum leg of mine.]],logDesc=[[Retrieve Tundra MacGrann's dried meats from the stolen meat locker in Old Icebeard's cave.]],choiceRewards={{id=6177,qty=1},{id=10550,qty=1}}}
DB[313]={id=313,zoneId=1,name=[[The Grizzled Den]],name_loc=[[El Cubil Pardo]],level=7,minLevel=4,giver=[[Pilot Stonegear]],giver_loc=[[Piloto Roscapiedra]],giverType=[[NPC]],giverId=1377,ender=[[Pilot Stonegear]],ender_loc=[[Piloto Roscapiedra]],enderType=[[NPC]],enderId=1377,poiX=-5506,poiY=-344,wowhead=[[https://www.wowhead.com/wotlk/quest=313]],image=[[assets/images/quests/placeholder.png]],desc=[[Driving a Siege Engine isn't for everyone.  It takes an iron grip and nerves of steel...lucky I have both!  How about you?  How's your mettle?  Want to prove it to me? Well...I'm looking to make my engine, Trollplow, a little more cozy.  How about you get me a heap of Wendigo Manes from the Grizzled Den, west of Kharanos.  Those manes would make a great rug for Trollplow's inside deck!]],logDesc=[[Gather 8 Wendigo Manes and bring them to Pilot Stonegear.]]}
DB[314]={id=314,zoneId=1,name=[[Protecting the Herd]],name_loc=[[La protección del rebaño]],level=12,minLevel=6,giver=[[Rudra Amberstill]],giver_loc=[[Rudra Semperámbar]],giverType=[[NPC]],giverId=1265,ender=[[Rudra Amberstill]],ender_loc=[[Rudra Semperámbar]],enderType=[[NPC]],enderId=1265,poiX=-5390,poiY=-1279,wowhead=[[https://www.wowhead.com/wotlk/quest=314]],image=[[assets/images/quests/placeholder.png]],desc=[[We heard the cries in the middle of the night.  Then this morning, sure enough, the herd was missing two rams.  That dastardly beast known as Vagash has been preying on our livelihood.  With most of King Magni's army off in distant lands fighting with the Alliance, there is no one to keep Vagash at bay. Perhaps you are brave enough to seek out the beast and slay him.  Bring me one of his fangs and I will reward you.  Vagash lurks just above the ranch here, but be warned, he is deadly.]],logDesc=[[Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.]],choiceRewards={{id=10549,qty=1},{id=2817,qty=1},{id=3103,qty=1}}}
DB[315]={id=315,zoneId=1,name=[[The Perfect Stout]],name_loc=[[La cerveza perfecta]],level=9,minLevel=5,giver=[[Rejold Barleybrew]],giver_loc=[[Rejold Cebadiz]],giverType=[[NPC]],giverId=1374,ender=[[Rejold Barleybrew]],ender_loc=[[Rejold Cebadiz]],enderType=[[NPC]],enderId=1374,poiX=-5054,poiY=-317,wowhead=[[https://www.wowhead.com/wotlk/quest=315]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm on a quest, a quest to make the perfect stout.  I know I can do it -- brewing's in my blood.  I just need to find the right recipe... The Frostmane trolls grow a plant, shimmerweed, high up in the hills to the east.  They use it in their strange, tribal rituals.  We dwarves haven't found much use for it, but it has a unique taste...and I want to experiment with it in my brews! Get me some shimmerweed from Frostmane seers, or swipe it from the trolls' shimmerweed baskets.]],logDesc=[[Bring 6 Shimmerweeds to Rejold Barleybrew in the Brewnall Village.]],choiceRewards={{id=2905,qty=1},{id=2326,qty=1}}}
DB[316]={id=316,name=[[<UNUSED 1>]],name_loc=[[<UNUSED 1>]],level=1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=316]],image=[[assets/images/quests/placeholder.png]],choiceRewards={{id=20371,qty=1},{id=20651,qty=1},{id=22114,qty=1},{id=22780,qty=1},{id=33079,qty=1}}}
DB[317]={id=317,zoneId=1,name=[[Stocking Jetsteam]],name_loc=[[Los suministros del reactor a vapor]],level=6,minLevel=2,giver=[[Pilot Bellowfiz]],giver_loc=[[Piloto Bramiz]],giverType=[[NPC]],giverId=1378,ender=[[Pilot Bellowfiz]],ender_loc=[[Piloto Bramiz]],enderType=[[NPC]],enderId=1378,rewardNextId=318,poiX=-5467,poiY=-632,wowhead=[[https://www.wowhead.com/wotlk/quest=317]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm preparing to start a mission for the Siege Brigade.  It's a long one, and I need to stock Jetsteam with a month's worth of supplies.  So while Steelgrill is working on my tank, can you do some hunting for me? I'll need some fur for bedding, and boar meat for food.  You can get meat from boars and fur from the bears... you can find them both in the snow fields south of the Grizzled Den.]],logDesc=[[Gather 4 Chunks of Boar Meat and 2 Thick Bear Furs, and deliver them to Pilot Bellowfiz at Steelgrill's Depot.]]}
DB[318]={id=318,zoneId=1,name=[[Evershine]],name_loc=[[La tajada]],level=7,minLevel=2,giver=[[Pilot Bellowfiz]],giver_loc=[[Piloto Bramiz]],giverType=[[NPC]],giverId=1378,ender=[[Rejold Barleybrew]],ender_loc=[[Rejold Cebadiz]],enderType=[[NPC]],enderId=1374,prevId=317,rewardNextId=319,poiX=-5378,poiY=315,wowhead=[[https://www.wowhead.com/wotlk/quest=318]],image=[[assets/images/quests/placeholder.png]],desc=[[Rejold Barleybrew experiments with his brews.  Some of them taste good, some bad, and some...well, some will lay all but the stoutest dwarf flat. He lives at Brewnall Village, west of Kharanos, and one of his drinks, Evershine, is what I want.  It'll help keep me warm while I'm on the cold road. And...the blessed stuff burns so hot I can throw it in Jetsteam's furnace for a burst of power!  That little tactic has gotten me out of more than one tight spot.]],logDesc=[[Get a cask of Evershine from Rejold Barleybrew in Brewnall Village.]]}
DB[319]={id=319,zoneId=1,name=[[A Favor for Evershine]],name_loc=[[Un favor a cambio de un barril de tajada]],level=8,minLevel=2,giver=[[Rejold Barleybrew]],giver_loc=[[Rejold Cebadiz]],giverType=[[NPC]],giverId=1374,ender=[[Rejold Barleybrew]],ender_loc=[[Rejold Cebadiz]],enderType=[[NPC]],enderId=1374,prevId=318,rewardNextId=320,poiX=-5304,poiY=-95,wowhead=[[https://www.wowhead.com/wotlk/quest=319]],image=[[assets/images/quests/placeholder.png]],desc=[[I have a cask of Evershine handy, but...can you do me a favor?  Brewnall village could use a hand against the wild animals that wander the nearby snows.  Sometimes they wander close. We're not afraid of these bears and cats and boars - no self respecting dwarf would be - but if you can take care of those animals for us, then we'd have more time for our crafting and brewing.]],logDesc=[[Kill 6 Ice Claw Bears, 8 Elder Crag Boars, and 8 Snow Leopards, and then return to Rejold Barleybrew in Brewnall Village.]]}
DB[320]={id=320,zoneId=1,name=[[Return to Bellowfiz]],name_loc=[[Regresa junto a Bramiz]],level=8,minLevel=2,giver=[[Rejold Barleybrew]],giver_loc=[[Rejold Cebadiz]],giverType=[[NPC]],giverId=1374,ender=[[Pilot Bellowfiz]],ender_loc=[[Piloto Bramiz]],enderType=[[NPC]],enderId=1378,prevId=319,poiX=-5467,poiY=-632,wowhead=[[https://www.wowhead.com/wotlk/quest=320]],image=[[assets/images/quests/placeholder.png]],desc=[[Here's your cask of Evershine, $N.  And again, thank you for the hunting earlier.]],logDesc=[[Give the cask of Evershine to Pilot Bellowfiz at Steelgrill's Depot.]],choiceRewards={{id=1011,qty=1},{id=1010,qty=1},{id=10547,qty=1}}}
DB[321]={id=321,zoneId=10,name=[[Lightforge Iron]],name_loc=[[Hierro Forjaluz]],level=29,minLevel=20,giver=[[Glorin Steelbrow]],giver_loc=[[Glorin Frenteacerada]],giverType=[[NPC]],giverId=1217,ender=[[Waterlogged Chest]],ender_loc=[[Cofre encharcado]],enderType=[[GO]],enderId=2734,prevId=270,rewardNextId=324,poiX=-3917,poiY=-890,wowhead=[[https://www.wowhead.com/wotlk/quest=321]],image=[[assets/images/quests/placeholder.png]],desc=[[The shipwrecks off the shore here are the doomed Third Fleet of Kul'Tiras, burned and sunk by Red Dragons during the last Great War. The Fleet hailed from Lordaeron, but one ship, an Elvish Destroyer: Flying Osprey, was with it.  It was shipping a load of Lightforge Iron and joined the Third Fleet for protection.  Ironic that it sunk to the same dragons... Enough history.  The Flying Osprey is wrecked to the south of Menethil Harbor.  If you find the Lightforge Iron there, bring it to me.]],logDesc=[[Search the wreckage of The Flying Osprey in the Wetlands.]],rewards={{id=2702,qty=1}}}
DB[322]={id=322,zoneId=10,name=[[Blessed Arm]],name_loc=[[Brazo bendito]],level=29,minLevel=20,giver=[[Glorin Steelbrow]],giver_loc=[[Glorin Frenteacerada]],giverType=[[NPC]],giverId=1217,ender=[[Grimand Elmore]],enderType=[[NPC]],enderId=1416,prevId=324,rewardNextId=325,poiX=-8387,poiY=685,wowhead=[[https://www.wowhead.com/wotlk/quest=322]],image=[[assets/images/quests/placeholder.png]],desc=[[There is a dwarven weaponsmith in the Dwarven District of Stormwind who can craft with lightforge iron.  His name is Grimand Elmore. I've packed the iron you found into a crate.  Take it to Grimand and tell him your tale.  I'm sure he'll oblige someone on a quest such as yours, and craft for you a weapon - a weapon to give even Morbent Fel worry!]],logDesc=[[Take the Crate of Lightforge Ingots to Grimand Elmore in Stormwind.]]}
DB[323]={id=323,zoneId=10,name=[[Proving Your Worth]],name_loc=[[Pon a prueba tu valor]],level=28,minLevel=20,giver=[[Sven Yorgen]],giverType=[[NPC]],giverId=311,ender=[[Sven Yorgen]],enderType=[[NPC]],enderId=311,prevId=268,rewardNextId=269,poiX=-10428,poiY=327,wowhead=[[https://www.wowhead.com/wotlk/quest=323]],image=[[assets/images/quests/placeholder.png]],desc=[[Morbent Fel is a necromancer, and an ally to the dark riders.  I would pit you against the power of Morbent Fel, but I will not send you against that vile fiend without first knowing your strength. You have already proven your bravery to me, but if you truly wish to face the necromancer, then you must now prove your skill against his minions.]],logDesc=[[Kill 15 Skeletal Raiders, 3 Skeletal Healers and 3 Skeletal Warders, and then return to Sven.]]}
DB[324]={id=324,zoneId=10,name=[[The Lost Ingots]],name_loc=[[Los lingotes perdidos]],level=29,minLevel=20,giver=[[Waterlogged Chest]],giver_loc=[[Cofre encharcado]],giverType=[[GO]],giverId=2734,ender=[[Glorin Steelbrow]],ender_loc=[[Glorin Frenteacerada]],enderType=[[NPC]],enderId=1217,prevId=321,rewardNextId=322,poiX=-3915,poiY=-949,wowhead=[[https://www.wowhead.com/wotlk/quest=324]],image=[[assets/images/quests/placeholder.png]],desc=[[Having grabbed the single lightforge ingot from the waterlogged chest, it is clear that murlocs have stolen the rest.  Hunt the murloc raiders near the Flying Osprey wreckage for the lost lightforge iron.]],logDesc=[[Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands.]]}
DB[325]={id=325,zoneId=10,name=[[Armed and Ready]],name_loc=[[Armado y listo]],level=29,minLevel=20,giver=[[Grimand Elmore]],giverType=[[NPC]],giverId=1416,ender=[[Sven Yorgen]],enderType=[[NPC]],enderId=311,prevId=322,rewardNextId=55,poiX=-10330,poiY=623,wowhead=[[https://www.wowhead.com/wotlk/quest=325]],image=[[assets/images/quests/placeholder.png]],desc=[[Here is the weapon against the fiend of which you spoke.  You're all ready, $N.  Best of luck to you, and I look forward to your tale of glory!]],logDesc=[[Bring Morbent's Bane to Sven in Duskwood.]]}
DB[328]={id=328,zoneId=33,name=[[The Hidden Key]],name_loc=[[La llave oculta]],level=37,minLevel=30,giver=[[Bookie Herod's Records]],giver_loc=[[Documentos del corredor Herod]],giverType=[[GO]],giverId=287,ender=[[Bookie Herod's Strongbox]],ender_loc=[[Caja fuerte del corredor Herod]],enderType=[[GO]],enderId=288,prevId=200,rewardNextId=329,poiX=-11490,poiY=-945,wowhead=[[https://www.wowhead.com/wotlk/quest=328]],image=[[assets/images/quests/placeholder.png]],desc=[[Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key. And after further study of his notes, a few references to a "secure strongbox" are contained among various papers.  The box is somewhere within the Stockpile - the cavern complex at the back of Kurzen's Compound. If this secure strongbox is found, and the small brass key can open it, then perhaps the mystery behind Thorsen's detection will be revealed.]],logDesc=[[Use the Small Brass Key to open Bookie Herod's Strongbox.]],rewards={{id=4122,qty=1}}}
DB[329]={id=329,zoneId=33,name=[[The Spy Revealed!]],name_loc=[[¡Espía descubierto!]],level=37,minLevel=30,giver=[[Bookie Herod's Strongbox]],giver_loc=[[Caja fuerte del corredor Herod]],giverType=[[GO]],giverId=288,ender=[[Lieutenant Doren]],ender_loc=[[Teniente Doren]],enderType=[[NPC]],enderId=469,prevId=328,rewardNextId=330,poiX=-11297,poiY=-207,wowhead=[[https://www.wowhead.com/wotlk/quest=329]],image=[[assets/images/quests/placeholder.png]],desc=[[Among the valuables of the strongbox is a muddy, scribbled note.  Although barely legible, it looks to be an itinerary for Private Thorsen.  It details his patrol routes, who he speaks with and how he spends his time with the rebels.  It's signed with only one letter: -M. But whoever wrote this note must have stayed very close to Thorsen.  Whoever wrote this note is the traitor within the rebel camp.]],logDesc=[[Take the Muddy Note to Lieutenant Doren at the Rebel Camp.]]}
DB[330]={id=330,zoneId=33,name=[[Patrol Schedules]],name_loc=[[Horarios de patrulla]],level=37,minLevel=30,giver=[[Lieutenant Doren]],giver_loc=[[Teniente Doren]],giverType=[[NPC]],giverId=469,ender=[[Corporal Sethman]],ender_loc=[[Cabo Sethman]],enderType=[[NPC]],enderId=1422,prevId=329,rewardNextId=331,poiX=-11313,poiY=-183,wowhead=[[https://www.wowhead.com/wotlk/quest=330]],image=[[assets/images/quests/placeholder.png]],desc=[[The note you gave me is signed with an "-M"...I don't know what that could mean. But...the note also says this person shared patrol routes with Thorsen last week.  So whoever shared patrol with Thorsen last week must be the traitor! Go to Corporal Sethman.  He handles the patrol schedules and can tell you who was with Thorsen.]],logDesc=[[Speak with Corporal Sethman.]]}
DB[331]={id=331,zoneId=33,name=[[Report to Doren]],name_loc=[[Informa a Doren]],level=37,minLevel=30,giver=[[Corporal Sethman]],giver_loc=[[Cabo Sethman]],giverType=[[NPC]],giverId=1422,ender=[[Lieutenant Doren]],ender_loc=[[Teniente Doren]],enderType=[[NPC]],enderId=469,prevId=330,poiX=-11297,poiY=-207,wowhead=[[https://www.wowhead.com/wotlk/quest=331]],image=[[assets/images/quests/placeholder.png]],desc=[[Did Lieutenant Doren want you to report back to him with that patrol information?]],logDesc=[[Speak with Lieutenant Doren.]],choiceRewards={{id=4139,qty=1},{id=4123,qty=1}}}
DB[332]={id=332,zoneId=1519,name=[[Wine Shop Advert]],name_loc=[[Publicidad de la bodega]],level=2,minLevel=1,giver=[[Renato Gallina]],giver_loc=[[Renato Galina]],giverType=[[NPC]],giverId=1432,ender=[[Suzetta Gallina]],ender_loc=[[Suzetta Galina]],enderType=[[NPC]],enderId=1431,poiX=-8885,poiY=676,wowhead=[[https://www.wowhead.com/wotlk/quest=332]],image=[[assets/images/quests/placeholder.png]],desc=[[If you talk to anyone about wine, then you know we Gallinas sell the best wine in Stormwind.  And we're not far, still in the Trade District along the city's lovely canals. Here, take this pamphlet.  Bring it to my sister Suzetta at our shop for a complimentary bottle of our famous pinot noir.  You won't regret it!]],logDesc=[[Go to the Gallina Winery, and bring Suzetta Gallina the Wine Ticket for a free bottle of wine.]],rewards={{id=2723,qty=1}}}
DB[333]={id=333,zoneId=1519,name=[[Harlan Needs a Resupply]],name_loc=[[Harlan necesita un nuevo suministro]],level=2,minLevel=1,giver=[[Harlan Bagley]],giverType=[[NPC]],giverId=1427,ender=[[Rema Schneider]],enderType=[[NPC]],enderId=1428,poiX=-8778,poiY=713,wowhead=[[https://www.wowhead.com/wotlk/quest=333]],image=[[assets/images/quests/placeholder.png]],desc=[[We've been doing a lot of business lately.  It seems like everyone is buying armor and sturdy clothes.  Almost like they expect a cold, harsh season ahead... But those are future worries.  My worry today is that I'm running out of knitted clothing to sell.  I need another load from our supplier. If you can take this request to Rema Schneider at the Canal Tailor and Fit Shop, I'd be most grateful.]],logDesc=[[Go to the Canal Tailor Shop and bring Rema Schneider the Cloth Request from Harlan Bagley.]]}
DB[334]={id=334,zoneId=1519,name=[[Package for Thurman]],name_loc=[[Un paquete para Thurman]],level=2,minLevel=1,giver=[[Rema Schneider]],giverType=[[NPC]],giverId=1428,ender=[[Thurman Schneider]],enderType=[[NPC]],enderId=1429,poiX=-8962,poiY=809,wowhead=[[https://www.wowhead.com/wotlk/quest=334]],image=[[assets/images/quests/placeholder.png]],desc=[[My son Thurman is an apprentice at the Larson Clothiers, in the Mage's Quarter.  He was in a hurry today and forgot his shears and needles.  I know a great $C like you must have important tasks at hand, but without his tools Thurman can't do his apprentice work! Please, $N.  Can you take my son's sewing kit to him?  Larson Clothiers is one of two clothing shops in the Mage's Quarter - it's the one deeper in, near the Mage's Tower.]],logDesc=[[Go to the Larson Clothiers in the Stormwind Mage Quarter, and give Thurman Schneider his Sewing Kit.]]}
DB[335]={id=335,zoneId=1519,name=[[A Noble Brew]],name_loc=[[Una noble cerveza]],level=30,minLevel=25,giver=[[Zardeth of the Black Claw]],giver_loc=[[Zardeth de los Zarpanegra]],giverType=[[NPC]],giverId=1435,ender=[[Zardeth of the Black Claw]],ender_loc=[[Zardeth de los Zarpanegra]],enderType=[[NPC]],enderId=1435,rewardNextId=336,poiX=-10364,poiY=-1282,wowhead=[[https://www.wowhead.com/wotlk/quest=335]],image=[[assets/images/quests/placeholder.png]],desc=[[Lord Wishock is causing quite a stir amongst the House of Nobles.  He was made aware of our little "establishment" down here and is lobbying for a full investigation.  I have a plan to keep Wishock "preoccupied," but I'll need your help.  There is a flower growing in the Garden of Stalvan on the outskirts of Darkshire.  This small white flower is known as the Tear of Tilloa.  I will also need a Musquash Root, found only at the very base of the falls far beneath the Stonewrought Dam in the Wetlands.]],logDesc=[[Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands.]]}
DB[336]={id=336,zoneId=1519,name=[[A Noble Brew]],name_loc=[[Una noble cerveza]],level=30,minLevel=25,giver=[[Zardeth of the Black Claw]],giver_loc=[[Zardeth de los Zarpanegra]],giverType=[[NPC]],giverId=1435,ender=[[Lord Baurles K. Wishock]],ender_loc=[[Lord Baurles K. Wishock]],enderType=[[NPC]],enderId=1439,prevId=335,poiX=-8563,poiY=370,wowhead=[[https://www.wowhead.com/wotlk/quest=336]],image=[[assets/images/quests/placeholder.png]],desc=[[Lord Wishock, like all men, has his weaknesses.  His happens to be a fondness for liquor.  The hypocrisy is astounding.  The trite fool spends his days trying to shut down our little "tavern" while his nights are spent upstairs, running up a bill he never pays.  Well, let's see how Wishock likes this special brew I have prepared for him:  Black Claw stout.  It's got quite a kick, $n. Take it to him and see how he likes it.  Most likely the old fool is milling about the Hall of Petitioners.]],logDesc=[[Take the Black Claw Stout to Lord Wishock in the Hall of Petitioners.]]}
DB[337]={id=337,zoneId=10,name=[[An Old History Book]],name_loc=[[Un libro viejo de Historia]],level=25,minLevel=20,giverType=[[NPC]],ender=[[Milton Sheaf]],ender_loc=[[Milton Gavilla]],enderType=[[NPC]],enderId=1440,rewardNextId=538,poiX=-10251,poiY=142,wowhead=[[https://www.wowhead.com/wotlk/quest=337]],image=[[assets/images/quests/placeholder.png]],desc=[[Although the cover of this book is marred by scratches and caked with mud, the words "The History of Stormwind" can still be read along its spine.  Upon opening the book, the seal of the Stormwind Library is clearly stamped on the book's first page. It looks like someone checked out this book, and never returned it...]],logDesc=[[Return the book: The History of Stormwind, to the Stormwind Library.]]}
DB[338]={id=338,zoneId=33,name=[[The Green Hills of Stranglethorn]],name_loc=[[Las verdes colinas de Tuercespina]],level=40,minLevel=30,giver=[[Barnil Stonepot]],giver_loc=[[Barnil Jarropetra]],giverType=[[NPC]],giverId=716,ender=[[Barnil Stonepot]],ender_loc=[[Barnil Jarropetra]],enderType=[[NPC]],enderId=716,prevId=583,poiX=-11617,poiY=-55,wowhead=[[https://www.wowhead.com/wotlk/quest=338]],image=[[assets/images/quests/placeholder.png]],desc=[[Master Nesingwary will be so upset if he finds out! He trusted me to proofread the manuscript of his novel, The Green Hills of Stranglethorn.  Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere! I was able to gather most of the pages but many are still strewn about the jungle.  Collect the pages to complete each of the four chapters. I will help you organize them.  Return the chapters to me once you have all four.]],logDesc=[[Collect the missing pages from The Green Hills of Stranglethorn manuscript.  Once all four chapters are complete, return them to Barnil.]],rewards={{id=17688,qty=1},{id=8173,qty=2},{id=3928,qty=3}}}
DB[339]={id=339,zoneId=33,name=[[Chapter I]],name_loc=[[Capítulo I]],level=40,minLevel=30,giver=[[Barnil Stonepot]],giver_loc=[[Barnil Jarropetra]],giverType=[[NPC]],giverId=716,ender=[[Barnil Stonepot]],ender_loc=[[Barnil Jarropetra]],enderType=[[NPC]],enderId=716,prevId=-338,poiX=-11617,poiY=-55,wowhead=[[https://www.wowhead.com/wotlk/quest=339]],image=[[assets/images/quests/placeholder.png]],desc=[[Chapter I was quite riveting!  Master Nesingwary sets the backdrop for the story and makes mention of his hunting companions, including me!  But that's besides the point.  Let me see which pages are still missing.  It seems pages 1, 4, 6 and 8 are still out there somewhere in the jungle!]],logDesc=[[Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I.]],rewards={{id=2756,qty=1}}}
DB[340]={id=340,zoneId=33,name=[[Chapter II]],name_loc=[[Capítulo II]],level=40,minLevel=30,giver=[[Barnil Stonepot]],giver_loc=[[Barnil Jarropetra]],giverType=[[NPC]],giverId=716,ender=[[Barnil Stonepot]],ender_loc=[[Barnil Jarropetra]],enderType=[[NPC]],enderId=716,prevId=-338,poiX=-11617,poiY=-55,wowhead=[[https://www.wowhead.com/wotlk/quest=340]],image=[[assets/images/quests/placeholder.png]],desc=[[Chapter II was chock full of exciting tales of panther and tiger hunting.  I could just kick myself for letting the pages blow away!   It seems I was able to recover all of the pages with the exception of pages 10, 11, 14, and 16.]],logDesc=[[Bring pages 10, 11, 14 and 16 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter II.]],rewards={{id=2757,qty=1}}}
DB[341]={id=341,zoneId=33,name=[[Chapter III]],name_loc=[[Capítulo III]],level=40,minLevel=30,giver=[[Barnil Stonepot]],giver_loc=[[Barnil Jarropetra]],giverType=[[NPC]],giverId=716,ender=[[Barnil Stonepot]],ender_loc=[[Barnil Jarropetra]],enderType=[[NPC]],enderId=716,prevId=-338,poiX=-11617,poiY=-55,wowhead=[[https://www.wowhead.com/wotlk/quest=341]],image=[[assets/images/quests/placeholder.png]],desc=[[Chapter III was my favorite.  It tells of Sir Erlgadin and Lady Rouack's first kill with a dwarven rifle.  And the end of Chapter III, why, such a cliffhanger!   Looks to me as though we still need pages 18, 20, 21 and 24 to finish the chapter.  Those pages are out there somewhere. . .]],logDesc=[[Bring pages 18, 20, 21and 24 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter III.]],rewards={{id=2758,qty=1}}}
DB[342]={id=342,zoneId=33,name=[[Chapter IV]],name_loc=[[Capítulo IV]],level=40,minLevel=30,giver=[[Barnil Stonepot]],giver_loc=[[Barnil Jarropetra]],giverType=[[NPC]],giverId=716,ender=[[Barnil Stonepot]],ender_loc=[[Barnil Jarropetra]],enderType=[[NPC]],enderId=716,prevId=-338,poiX=-11617,poiY=-55,wowhead=[[https://www.wowhead.com/wotlk/quest=342]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah Chapter IV; the big finale!  And what an ending it was!  We are only missing three pages for this chapter.  We need pages 25, 26 and 27 to put Chapter IV back together.]],logDesc=[[Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV.]],rewards={{id=2759,qty=1}}}
DB[343]={id=343,zoneId=1519,name=[[Speaking of Fortitude]],name_loc=[[Hablando de entereza]],level=24,minLevel=20,giver=[[Brother Kristoff]],giver_loc=[[Hermano Kristoff]],giverType=[[NPC]],giverId=1444,ender=[[Milton Sheaf]],ender_loc=[[Milton Gavilla]],enderType=[[NPC]],enderId=1440,rewardNextId=344,poiX=-8346,poiY=384,wowhead=[[https://www.wowhead.com/wotlk/quest=343]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm giving a speech on the Fortitude of the Spirit, and I'd like to recite passages from a particular book on metallurgy - "The Stresses of Iron."  A copy of this book should be in the Royal Library, within Stormwind Keep.  Can you retrieve it for me?  If so, then may the blessings of the Light be with you! The Royal Library is very large, but the head librarian, Milton Sheaf, knows each shelf like it was his own son.  Speak to him, he'll retrieve the book for you.]],logDesc=[[Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf.  He can find for you the book on metallurgy that Brother Kristoff needs for his speech.]]}
DB[344]={id=344,zoneId=1519,name=[[Brother Paxton]],name_loc=[[Hermano Paxton]],level=24,minLevel=20,giver=[[Milton Sheaf]],giver_loc=[[Milton Gavilla]],giverType=[[NPC]],giverId=1440,ender=[[Brother Paxton]],ender_loc=[[Hermano Paxton]],enderType=[[NPC]],enderId=951,prevId=343,rewardNextId=345,poiX=-8875,poiY=-186,wowhead=[[https://www.wowhead.com/wotlk/quest=344]],image=[[assets/images/quests/placeholder.png]],desc=[[The Stresses of Iron?  Yes, I know the book.  Quite a good one, written by the Dwarven miner Margulf Blaggon a few decades ago.  He spent most his time deep in the mountains of Khaz Modan, digging ore.  Smart fellow! But where was I?  Oh yes, the Stresses of Iron!  I'm afraid the book was moved to the Northshire Abbey.  The caretaker of the Abbey's library, Brother Paxton, wanted to make a copy of the book for his own shelves. But that was months ago.  I wonder why it's taking him so long...]],logDesc=[[Speak with Brother Paxton in the Northshire Abbey.]]}
DB[345]={id=345,zoneId=1519,name=[[Ink Supplies]],name_loc=[[Suministros de tinta]],level=24,minLevel=20,giver=[[Brother Paxton]],giver_loc=[[Hermano Paxton]],giverType=[[NPC]],giverId=951,ender=[[Foreman Oslow]],ender_loc=[[Supervisor Olento]],enderType=[[NPC]],enderId=341,prevId=344,rewardNextId=347,poiX=-9279,poiY=-2269,wowhead=[[https://www.wowhead.com/wotlk/quest=345]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been meaning to finish my copy of The Stresses of Iron, but... Well you see, I make my own ink for books I copy.  It's my own recipe; it doesn't run or smear, and it dries very quickly.  Unfortunately, it dries too quickly!  My last batch dried up before I could finish the copying job, and I haven't had the chance to make more ink! To make more I need Rethban Iron Ore from the Redridge Mountains.  Foreman Oslow in Lakeshire is my usual supplier.]],logDesc=[[Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore.]]}
DB[346]={id=346,zoneId=1519,name=[[Return to Kristoff]],name_loc=[[Regresa junto a Kristoff]],level=24,minLevel=20,giver=[[Brother Paxton]],giver_loc=[[Hermano Paxton]],giverType=[[NPC]],giverId=951,ender=[[Brother Kristoff]],ender_loc=[[Hermano Kristoff]],enderType=[[NPC]],enderId=1444,prevId=347,poiX=-8623,poiY=767,wowhead=[[https://www.wowhead.com/wotlk/quest=346]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that I've finished copying the book, here's the original Stresses of Iron.  Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay.]],logDesc=[[Return to Brother Kristoff in the Cathedral Square.  Give him the book The Stresses of Iron.]],rewards={{id=6095,qty=1}}}
DB[347]={id=347,zoneId=1519,name=[[Rethban Ore]],name_loc=[[La mena de Rethban]],level=24,minLevel=20,giver=[[Foreman Oslow]],giver_loc=[[Supervisor Olento]],giverType=[[NPC]],giverId=341,ender=[[Brother Paxton]],ender_loc=[[Hermano Paxton]],enderType=[[NPC]],enderId=951,prevId=345,rewardNextId=346,poiX=-8892,poiY=-1933,wowhead=[[https://www.wowhead.com/wotlk/quest=347]],image=[[assets/images/quests/placeholder.png]],desc=[[Rethban Ore is named after the man who first found it, Bart Rethban.  When smelted it's not as strong as iron, but its ore has a dark, flat color that some scribes use in their dyes.  It can be found in the Rethban Caverns, north of here. We usually have some in stock, but we're too busy preparing for Orc attacks to gather any.  And besides...Redridge Gnolls are now living in the Rethban Caverns and their Drudgers are gathering the ore themselves. So if you need some, you'll have to get it yourself.]],logDesc=[[Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library.]]}
DB[348]={id=348,zoneId=33,name=[[Stranglethorn Fever]],name_loc=[[La fiebre de Tuercespina]],level=45,minLevel=40,giver=[[Fin Fizracket]],giver_loc=[[Fin Fizqueta]],giverType=[[NPC]],giverId=2486,ender=[[Fin Fizracket]],ender_loc=[[Fin Fizqueta]],enderType=[[NPC]],enderId=2486,poiX=-13839,poiY=19,wowhead=[[https://www.wowhead.com/wotlk/quest=348]],image=[[assets/images/quests/placeholder.png]],desc=[[Sick...so...very s-s-sick.... ...have contracted Stranglethorn Fever...deadly v-v-virus... ...only cure...is...is...to eat the heart of M-m-m-m-mokk the Savage...elusive white beast... ...Witch doctor Unbagwa...only one who can s-s-summon.... ...seek Unbagwa in hidden cave on southern cape... ...hurry...dying...dying....]],logDesc=[[Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage.  Bring the Heart of Mokk to Fin Fizracket.]],rewards={{id=4113,qty=1}}}
DB[349]={id=349,zoneId=33,name=[[Stranglethorn Fever]],name_loc=[[La fiebre de Tuercespina]],level=35,minLevel=32,giver=[[Witch Doctor Unbagwa]],giver_loc=[[Médico brujo Unbagwa]],giverType=[[NPC]],giverId=1449,ender=[[Witch Doctor Unbagwa]],ender_loc=[[Médico brujo Unbagwa]],enderType=[[NPC]],enderId=1449,prevId=-348,poiX=-13766,poiY=-214,wowhead=[[https://www.wowhead.com/wotlk/quest=349]],image=[[assets/images/quests/placeholder.png]],desc=[[temp text 02 - description]],logDesc=[[temp text 02 - log]]}
DB[350]={id=350,zoneId=1519,name=[[Look to an Old Friend]],name_loc=[[Mira por un viejo amigo]],level=31,minLevel=16,giver=[[Master Mathias Shaw]],giver_loc=[[Maestro Mathias Shaw]],giverType=[[NPC]],giverId=332,ender=[[Elling Trias]],ender_loc=[[Elling Trias]],enderType=[[NPC]],enderId=482,prevId=393,rewardNextId=2745,poiX=-8854,poiY=576,wowhead=[[https://www.wowhead.com/wotlk/quest=350]],image=[[assets/images/quests/placeholder.png]],desc=[[That Marzon would be contacting a member of the Defias and have ties to Lescovar... Having killed VanCleef and Thredd, it would be hard to see Lescovar brought to proper justice, as your evidence is nothing without their testimonies. That is not even considering the fact that Lescovar is a noble and well connected. It effectively makes him above the law. You'll need other help. I loathe to do so, but there is someone I know that will aid us. You'll find Trias in the Trade District of the city.]],logDesc=[[Speak to Elling Trias in Stormwind.]]}
DB[351]={id=351,zoneId=440,name=[[Find OOX-17/TN!]],name_loc=[[¡Encontrar a OOX-17/TN!]],level=48,minLevel=43,giverType=[[NPC]],ender=[[Homing Robot OOX-17/TN]],ender_loc=[[Robot mensajero OOX-17/TN]],enderType=[[NPC]],enderId=7784,rewardNextId=648,poiX=-8852,poiY=-4375,wowhead=[[https://www.wowhead.com/wotlk/quest=351]],image=[[assets/images/quests/placeholder.png]],desc=[[You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life. "The name's Oglethorpe, and my homing robot has gone missing!  I will reward you for its recovery!  Please take this beacon to the robot.  Excellent, I now have computed the coordinates for you!  It crashed near the Gaping Chasm in Tanaris!"]],logDesc=[[Bring the distress beacon to Oglethorpe's homing robot.]]}
DB[353]={id=353,zoneId=1519,name=[[Stormpike's Delivery]],name_loc=[[Una entrega a Pico Tormenta]],level=15,minLevel=9,giver=[[Grimand Elmore]],giverType=[[NPC]],giverId=1416,ender=[[Mountaineer Stormpike]],ender_loc=[[Montaraz Pico Tormenta]],enderType=[[NPC]],enderId=1343,poiX=-4826,poiY=-2677,wowhead=[[https://www.wowhead.com/wotlk/quest=353]],image=[[assets/images/quests/placeholder.png]],desc=[[The Stormpikes are a respected dwarven clan, and are well known for their fine and discerning tastes.  So it's no wonder that Gringer Stormpike, a Mountaineer of Ironforge, commissioned me to craft him a weapon. The weapon is finished, but... Mountaineer Stormpike is far away, in distant Loch Modan.  If you plan on traveling to the north, can you deliver this package to him? My last message from Mountaineer Stormpike said he's stationed at the northern guard tower in Loch Modan.]],logDesc=[[Deliver the Package for Stormpike to Mountaineer Stormpike in Loch Modan.]]}
DB[354]={id=354,zoneId=85,name=[[Deaths in the Family]],name_loc=[[Muertes en la familia]],level=11,minLevel=7,giver=[[Coleman Farthing]],giver_loc=[[Coleman Lontananza]],giverType=[[NPC]],giverId=1500,ender=[[Coleman Farthing]],ender_loc=[[Coleman Lontananza]],enderType=[[NPC]],enderId=1500,poiX=2952,poiY=964,wowhead=[[https://www.wowhead.com/wotlk/quest=354]],image=[[assets/images/quests/placeholder.png]],desc=[[The Agamand family was the most prosperous family in Tirisfal Glades.  I used to work their mills...before the Plague. When the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend.  We were fools, but at least we were loyal fools. The Agamands, in their pride, doomed us to undeath.  And now they are minions of the Scourge! Serve the Forsaken by defeating the Agamands who fell to the Plague.  Serve me by bringing me their remains.]],logDesc=[[Bring Gregor's Remains, Nissa's Remains and Thurman's Remains to Coleman Farthing in Brill.]]}
DB[355]={id=355,zoneId=85,name=[[Speak with Sevren]],name_loc=[[Habla con Sevren]],level=10,minLevel=7,giver=[[Coleman Farthing]],giver_loc=[[Coleman Lontananza]],giverType=[[NPC]],giverId=1500,ender=[[Magistrate Sevren]],ender_loc=[[Magistrado Sevren]],enderType=[[NPC]],enderId=1499,prevId=354,rewardNextId=408,poiX=2306,poiY=265,wowhead=[[https://www.wowhead.com/wotlk/quest=355]],image=[[assets/images/quests/placeholder.png]],desc=[[You have given me the remains of the Agamands, and satisfied my desire for revenge.  But the Agamand Mills hold a threat to all the Forsaken, not just to me. I have spoken to Magistrate Sevren of your exploits against the Agamands, and he wishes to speak with you.]],logDesc=[[Speak with Magistrate Sevren in Brill.]]}
DB[356]={id=356,zoneId=85,name=[[Rear Guard Patrol]],name_loc=[[Patrulla de la retaguardia]],level=11,minLevel=6,giver=[[Deathguard Linnea]],giver_loc=[[Guardia de la Muerte Linnea]],giverType=[[NPC]],giverId=1495,ender=[[Deathguard Linnea]],ender_loc=[[Guardia de la Muerte Linnea]],enderType=[[NPC]],enderId=1495,poiX=2016,poiY=-518,wowhead=[[https://www.wowhead.com/wotlk/quest=356]],image=[[assets/images/quests/placeholder.png]],desc=[[The defenders on The Bulwark protecting Tirisfal from the Plaguelands are on constant alert.  But sometimes Scourge will slip past them. Our success at the Bulwark depends on a one-front battle - we cannot allow an attack from the rear, nor can we allow our defenders' supply line to be cut. Assist the Bulwark.  Patrol east and slay any Scourge you find.  Spend particular effort at the Balnir Farmstead to the east.  It has become a haven for interloping Scourge.]],logDesc=[[Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp.]]}
DB[357]={id=357,zoneId=1497,name=[[The Lich's Identity]],name_loc=[[La identidad del exánime]],level=8,minLevel=5,giver=[[Bethor Iceshard]],giver_loc=[[Bethor Duroyelo]],giverType=[[NPC]],giverId=1498,ender=[[Bethor Iceshard]],ender_loc=[[Bethor Duroyelo]],enderType=[[NPC]],enderId=1498,prevId=405,rewardNextId=366,poiX=2569,poiY=-38,wowhead=[[https://www.wowhead.com/wotlk/quest=357]],image=[[assets/images/quests/placeholder.png]],desc=[[There is a lich who dwells on the island in Brightwater Lake to the north.  Although he is a free-willed Forsaken, he believes all other Undead are Scourge slaves and has his minions attack anyone who approaches him. But because he is Forsaken, the Queen will want him.  And if he is skilled in Necromancy, then his knowledge would be...quite useful to us. To discover his identity and his talents, I must see his spellbook.  Steal into his camp and acquire it, then return to me.]],logDesc=[[Bring the Lich's Spellbook to Bethor Iceshard in the Undercity.]]}
DB[358]={id=358,zoneId=85,name=[[Graverobbers]],name_loc=[[Profanadores]],level=8,minLevel=4,giver=[[Magistrate Sevren]],giver_loc=[[Magistrado Sevren]],giverType=[[NPC]],giverId=1499,ender=[[Magistrate Sevren]],ender_loc=[[Magistrado Sevren]],enderType=[[NPC]],enderId=1499,poiX=2552,poiY=411,wowhead=[[https://www.wowhead.com/wotlk/quest=358]],image=[[assets/images/quests/placeholder.png]],desc=[[The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came.   The bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide Gnolls to gather the corpses and use them to bolster their armies.  This cannot be allowed! Your task is twofold: slay the Rot Hides at the Mass Grave and Garren's Haunt, and gather from them the Embalming Ichor that gives them life.]],logDesc=[[Kill Rot Hide Graverobbers and Rot Hide Mongrels.   Bring 8 Embalming Ichors to Magistrate Sevren in Brill.]],choiceRewards={{id=6063,qty=1},{id=3439,qty=1}}}
DB[359]={id=359,zoneId=85,name=[[Forsaken Duties]],name_loc=[[Las obligaciones de los Renegados]],level=9,minLevel=6,giver=[[Magistrate Sevren]],giver_loc=[[Magistrado Sevren]],giverType=[[NPC]],giverId=1499,ender=[[Deathguard Linnea]],ender_loc=[[Guardia de la Muerte Linnea]],enderType=[[NPC]],enderId=1495,prevId=358,rewardNextId=360,poiX=2022,poiY=74,wowhead=[[https://www.wowhead.com/wotlk/quest=359]],image=[[assets/images/quests/placeholder.png]],desc=[[I need a fresh report from our Deathguard waystation to the east. I must know if more Scourge forces have slipped past The Bulwark and into Tirisfal.  Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here! Travel south along the road, then east at the fork to the waystation.  Speak with Deathguard Linnea.  She has the information I need.]],logDesc=[[Speak with Deathguard Linnea.]]}
DB[360]={id=360,zoneId=85,name=[[Return to the Magistrate]],name_loc=[[Regresa junto al magistrado]],level=9,minLevel=6,giver=[[Deathguard Linnea]],giver_loc=[[Guardia de la Muerte Linnea]],giverType=[[NPC]],giverId=1495,ender=[[Magistrate Sevren]],ender_loc=[[Magistrado Sevren]],enderType=[[NPC]],enderId=1499,prevId=359,poiX=2306,poiY=265,wowhead=[[https://www.wowhead.com/wotlk/quest=360]],image=[[assets/images/quests/placeholder.png]],desc=[[Now return to Magistrate Sevren with the information I gave you.  He'll want it as soon as possible, so be swift. And if you see any Scourge on your way back, take them down - we can't let them wander our lands unchallenged.]],logDesc=[[Return to Magistrate Sevren in Brill.]]}
DB[361]={id=361,zoneId=85,name=[[A Letter Undelivered]],name_loc=[[Una carta sin entregar]],level=7,minLevel=4,giverType=[[NPC]],ender=[[Yvette Farthing]],ender_loc=[[Yvette Lontananza]],enderType=[[NPC]],enderId=1560,poiX=2253,poiY=251,wowhead=[[https://www.wowhead.com/wotlk/quest=361]],image=[[assets/images/quests/placeholder.png]],desc=[[This is a letter written by Thurman, the eldest son of Gregor Agamand.  It is addressed to an Yvette Farthing, though it does not appear to have reached her...]],logDesc=[[Find Yvette Farthing, and deliver to her the letter from Thurman Agamand.]]}
DB[362]={id=362,zoneId=85,name=[[The Haunted Mills]],name_loc=[[Los molinos fantasma]],level=10,minLevel=7,giver=[[Coleman Farthing]],giver_loc=[[Coleman Lontananza]],giverType=[[NPC]],giverId=1500,ender=[[Coleman Farthing]],ender_loc=[[Coleman Lontananza]],enderType=[[NPC]],enderId=1500,poiX=2632,poiY=899,wowhead=[[https://www.wowhead.com/wotlk/quest=362]],image=[[assets/images/quests/placeholder.png]],desc=[[Devlin Agamand was the younger of two sons in the Agamand family, and in life the two could not be more different.  Thurman was tall and gentle while his younger brother was weak and sharp tongued. When Agamand Mills fell to the Plague, I was not surprised to hear that Devlin was quick to succumb.  His mad chattering can still be heard near the road leading to the Agamand Mills. I'm collecting the remains of the Agamands, and I want poor Devlin.  Find him, destroy him, and bring me his bones.]],logDesc=[[Slay Devlin Agamand, and bring Devlin's Remains to Coleman Farthing in Brill.]]}
DB[363]={id=363,zoneId=154,name=[[Rude Awakening]],name_loc=[[Desvelo brutal]],level=1,minLevel=1,giver=[[Undertaker Mordo]],giver_loc=[[Enterrador Mordo]],giverType=[[NPC]],giverId=1568,ender=[[Shadow Priest Sarvis]],ender_loc=[[Sacerdote de las Sombras Sarvis]],enderType=[[NPC]],enderId=1569,rewardNextId=364,poiX=1843,poiY=1640,wowhead=[[https://www.wowhead.com/wotlk/quest=363]],image=[[assets/images/quests/placeholder.png]],desc=[[About time you woke up. We were ready to toss you into the fire with the others, but it looks like you made it. I am Mordo, the caretaker of the crypt of Deathknell. And you are the Lich King's slave no more. Speak with Shadow Priest Sarvis in the chapel at the base of the hill, he will tell you more of what you must know. To get out of this crypt, take the steps up to the surface. Follow the road down to the chapel to find Sarvis.]],logDesc=[[Speak with Shadow Priest Sarvis.]]}
DB[364]={id=364,zoneId=154,name=[[The Mindless Ones]],name_loc=[[Los autómatas]],level=2,minLevel=1,giver=[[Shadow Priest Sarvis]],giver_loc=[[Sacerdote de las Sombras Sarvis]],giverType=[[NPC]],giverId=1569,ender=[[Shadow Priest Sarvis]],ender_loc=[[Sacerdote de las Sombras Sarvis]],enderType=[[NPC]],enderId=1569,poiX=1907,poiY=1456,wowhead=[[https://www.wowhead.com/wotlk/quest=364]],image=[[assets/images/quests/placeholder.png]],desc=[[We Forsaken are at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres. The northern part of the village has become overrun with the Mindless Ones, and they must be destroyed. Destroy them, show them no mercy, our former brothers and sisters as they might be. The Fallen are nothing but The Lich King's slaves.]],logDesc=[[Shadow Priest Sarvis wants you to kill 5 Mindless Zombies and 5 Wretched Ghouls.]],choiceRewards={{id=3275,qty=1},{id=11847,qty=1}}}
DB[365]={id=365,zoneId=85,name=[[Fields of Grief]],name_loc=[[Campos de pena]],level=7,minLevel=4,giver=[[Deathguard Simmer]],giver_loc=[[Guardia de la Muerte Simmer]],giverType=[[NPC]],giverId=1519,ender=[[Apothecary Johaan]],ender_loc=[[Boticario Johaan]],enderType=[[NPC]],enderId=1518,rewardNextId=407,poiX=2351,poiY=1325,wowhead=[[https://www.wowhead.com/wotlk/quest=365]],image=[[assets/images/quests/placeholder.png]],desc=[[What have we here?  You look like a fledgling $c.  If you hope to prove yourself to The Dark Lady, you need to learn the ways of The Forsaken. To the west you'll find a farm.  Humans infest the land like mold on a rotting corpse.  And worse yet, the Scarlet Crusade patrols nearby from their tower.  Teach those scum a lesson and steal 10 of their precious pumpkins. Once you have 10, take them to Apothecary Johaan in Brill.]],logDesc=[[Steal 10 pumpkins from the farm to the west, just north of Deathknell and take them to Apothecary Johaan in Brill.]]}
DB[366]={id=366,zoneId=85,name=[[Return the Book]],name_loc=[[Devuelve el libro]],level=8,minLevel=5,giver=[[Bethor Iceshard]],giver_loc=[[Bethor Duroyelo]],giverType=[[NPC]],giverId=1498,ender=[[Gunther Arcanus]],ender_loc=[[Gunther Arcanos]],enderType=[[NPC]],enderId=1497,prevId=357,rewardNextId=409,poiX=2575,poiY=-48,wowhead=[[https://www.wowhead.com/wotlk/quest=366]],image=[[assets/images/quests/placeholder.png]],desc=[[Long ago Gunther and I, along with the now Scourge Necromancer Thule Ravenclaw, were friends and students within the Kirin Tor - a society of mages in Dalaran. Gunther and I both fell to the Plague, but I thought he either remained dead, or was raised into the ranks of the Lich King.  It is good to know he is free. We must have him.  I have placed a spell on his book that, when he sees it, will show him that I too am free of the Lich King.  After knowing this, it is my hope that he will join us.]],logDesc=[[Return Gunther's Spellbook to him, on the island of Gunther's Retreat.]]}
DB[367]={id=367,zoneId=85,name=[[A New Plague]],name_loc=[[Una nueva Peste]],level=6,minLevel=6,giver=[[Apothecary Johaan]],giver_loc=[[Boticario Johaan]],giverType=[[NPC]],giverId=1518,ender=[[Apothecary Johaan]],ender_loc=[[Boticario Johaan]],enderType=[[NPC]],enderId=1518,rewardNextId=368,poiX=2259,poiY=347,wowhead=[[https://www.wowhead.com/wotlk/quest=367]],image=[[assets/images/quests/placeholder.png]],desc=[[Lady Sylvanas has called upon the Royal Apothecary Society. The Dark Lady believes our knowledge coupled with the newfound magic will provide the key to Arthas's demise.  She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring Arthas's Scourge Army to ruin. My studies show that the blood of beasts might prove to be the key. Bring to me 5 vials of darkhound blood so I can test my theory.]],logDesc=[[Apothecary Johaan in the town of Brill wants you to collect 5 Vials of Darkhound Blood.]],rewards={{id=3382,qty=3}}}
DB[368]={id=368,zoneId=85,name=[[A New Plague]],name_loc=[[Una nueva Peste]],level=9,minLevel=6,giver=[[Apothecary Johaan]],giver_loc=[[Boticario Johaan]],giverType=[[NPC]],giverId=1518,ender=[[Apothecary Johaan]],ender_loc=[[Boticario Johaan]],enderType=[[NPC]],enderId=1518,prevId=367,rewardNextId=369,poiX=3055,poiY=-384,wowhead=[[https://www.wowhead.com/wotlk/quest=368]],image=[[assets/images/quests/placeholder.png]],desc=[[While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly. Poisoning some hapless victim is child's play. Plaguing an entire world proves to be a bit more complicated. I will need 5 Vile Fin Scales from Murlocs in the vicinity.  You will find the creatures along the coast to the north or to the west.]],logDesc=[[Apothecary Johaan of the town of Brill needs 5 Vile Fin Scales from Murlocs in Tirisfal Glades.]],rewards={{id=3434,qty=5}}}
DB[369]={id=369,zoneId=85,name=[[A New Plague]],name_loc=[[Una nueva Peste]],level=11,minLevel=6,giver=[[Apothecary Johaan]],giver_loc=[[Boticario Johaan]],giverType=[[NPC]],giverId=1518,ender=[[Apothecary Johaan]],ender_loc=[[Boticario Johaan]],enderType=[[NPC]],enderId=1518,prevId=368,rewardNextId=492,poiX=2350,poiY=-1114,wowhead=[[https://www.wowhead.com/wotlk/quest=369]],image=[[assets/images/quests/placeholder.png]],desc=[[While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims.  Later it was discovered that the deadly agent in the plague was preserved through the venom of Night Web Spiders. Bring me some venom from a Vicious Night Web Spider to complete this experiment.  I want to see if the contagious element from the venom will work with my new concoction.  Rumor has it the spiders can be found in Eastern Tirisfal Glades.]],logDesc=[[Apothecary Johaan in the town of Brill wants you to bring him 4 samples of venom from a Vicious Night Web Spider.]],rewards={{id=3442,qty=1}}}
DB[370]={id=370,zoneId=85,name=[[At War With The Scarlet Crusade]],name_loc=[[En guerra con la Cruzada Escarlata]],level=9,minLevel=5,giver=[[Executor Zygand]],giver_loc=[[Ejecutor Zygand]],giverType=[[NPC]],giverId=1515,ender=[[Executor Zygand]],ender_loc=[[Ejecutor Zygand]],enderType=[[NPC]],enderId=1515,prevId=427,rewardNextId=371,poiX=1795,poiY=721,wowhead=[[https://www.wowhead.com/wotlk/quest=370]],image=[[assets/images/quests/placeholder.png]],desc=[[The strategic documents from Executor Arren contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill. Kill Perrine along with 3 Zealots and 3 Missionaries and report back to me.]],logDesc=[[Executor Zygand in Brill wants you to kill Captain Perrine, 3 Scarlet Zealots and 3 Scarlet Missionaries.]]}
DB[371]={id=371,zoneId=85,name=[[At War With The Scarlet Crusade]],name_loc=[[En guerra con la Cruzada Escarlata]],level=10,minLevel=5,giver=[[Executor Zygand]],giver_loc=[[Ejecutor Zygand]],giverType=[[NPC]],giverId=1515,ender=[[Executor Zygand]],ender_loc=[[Ejecutor Zygand]],enderType=[[NPC]],enderId=1515,prevId=370,rewardNextId=372,poiX=2146,poiY=-528,wowhead=[[https://www.wowhead.com/wotlk/quest=371]],image=[[assets/images/quests/placeholder.png]],desc=[[We are still at war and the Scarlet Crusade grows in strength.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon. Kill Vachon along with 5 Scarlet Friars. It should prove to be a devastating blow to the Crusade!]],logDesc=[[Executor Zygand in Brill has commissioned you to slay Captain Vachon and 5 Scarlet Friars.]]}
DB[372]={id=372,zoneId=85,name=[[At War With The Scarlet Crusade]],name_loc=[[En guerra con la Cruzada Escarlata]],level=12,minLevel=5,giver=[[Executor Zygand]],giver_loc=[[Ejecutor Zygand]],giverType=[[NPC]],giverId=1515,ender=[[Executor Zygand]],ender_loc=[[Ejecutor Zygand]],enderType=[[NPC]],enderId=1515,prevId=371,poiX=3080,poiY=-560,wowhead=[[https://www.wowhead.com/wotlk/quest=372]],image=[[assets/images/quests/placeholder.png]],desc=[[Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest.  According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew. I am entrusting you now with a special and dangerous mission.  Slay Melrache and his two bodyguards, in the name of The Dark Lady.]],logDesc=[[Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards.]],choiceRewards={{id=3445,qty=1},{id=3071,qty=1}}}
DB[373]={id=373,zoneId=1519,name=[[The Unsent Letter]],name_loc=[[La carta sin enviar]],level=22,minLevel=16,giverType=[[NPC]],ender=[[Baros Alexston]],ender_loc=[[Baros Alexston]],enderType=[[NPC]],enderId=1646,rewardNextId=389,poiX=-8550,poiY=720,wowhead=[[https://www.wowhead.com/wotlk/quest=373]],image=[[assets/images/quests/placeholder.png]],desc=[[Searching Edwin VanCleef's person, you discover, among other things, an unsent letter. It is addressed to Baros Alexston, the City Architect of Stormwind, City Hall, Cathedral Square. It appears to be recently written and sealed.]],logDesc=[[Deliver the Letter to the City Architect to Baros Alexston in Stormwind.]]}
DB[374]={id=374,zoneId=85,name=[[Proof of Demise]],name_loc=[[Prueba de defunción]],level=7,minLevel=5,giver=[[Deathguard Burgess]],giver_loc=[[Guardia de la Muerte Burgess]],giverType=[[NPC]],giverId=1652,ender=[[Deathguard Burgess]],ender_loc=[[Guardia de la Muerte Burgess]],enderType=[[NPC]],enderId=1652,poiX=3102,poiY=-582,wowhead=[[https://www.wowhead.com/wotlk/quest=374]],image=[[assets/images/quests/placeholder.png]],desc=[[Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them. Varimathras, lieutenant to The Dark Lady, is seeing to it personally that the scum of Azeroth, the Human race, gets wiped into oblivion. Here in Tirisfal Glades we face a particularly annoying breed of humans: The Scarlet Crusade. Venture forth and wage an offensive on the Scarlet Crusade, $c. Bring me back 10 Scarlet Insignia Rings as proof of your loyalty to Varimathras and The Dark Lady.]],logDesc=[[Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.]],choiceRewards={{id=3435,qty=1},{id=3437,qty=1},{id=12299,qty=1}}}
DB[375]={id=375,zoneId=85,name=[[The Chill of Death]],name_loc=[[El frío de la muerte]],level=8,minLevel=7,giver=[[Gretchen Dedmar]],giverType=[[NPC]],giverId=1521,ender=[[Gretchen Dedmar]],enderType=[[NPC]],enderId=1521,poiX=2113,poiY=296,wowhead=[[https://www.wowhead.com/wotlk/quest=375]],image=[[assets/images/quests/placeholder.png]],desc=[[It's so cold, now.  The Plague of Undeath crawls through my veins like an icy serpent.  The Mindless State will be upon me soon.  But no doomed destiny will prevent me from serving our Dark Lady.  When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army. Now my hands shake from the chill.  If you would bring me five Duskbat Pelts and some Coarse Thread I could sew myself a blanket.  Help me, $N, so that I can continue to serve the cause.]],logDesc=[[Bring five Duskbat Pelts and some Coarse Thread to Gretchen Dedmar in Brill.]],choiceRewards={{id=3833,qty=1},{id=5939,qty=1}}}
DB[376]={id=376,zoneId=154,name=[[The Damned]],name_loc=[[Los Malditos]],level=2,minLevel=2,giver=[[Novice Elreth]],giver_loc=[[Novicia Elreth]],giverType=[[NPC]],giverId=1661,ender=[[Novice Elreth]],ender_loc=[[Novicia Elreth]],enderType=[[NPC]],enderId=1661,poiX=2098,poiY=1584,wowhead=[[https://www.wowhead.com/wotlk/quest=376]],image=[[assets/images/quests/placeholder.png]],desc=[[My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need. From the look of it, you'll be enlisted in his service also... hunting the Mindless Ones, if I know his mind. Well, if you'd like to stay in one piece--and I've no doubt you do--perhaps I can help. I'm running out of paws and wings, and if you bring me some, I'll find some armor for you. You'll find a good number of wolves and bats to the south.]],logDesc=[[Novice Elreth requires 6 Scavenger Paws and 6 Duskbat Wings.]],choiceRewards={{id=6060,qty=1},{id=2173,qty=1}}}
DB[377]={id=377,zoneId=717,name=[[Crime and Punishment]],name_loc=[[Crimen y castigo]],level=26,minLevel=22,giver=[[Councilman Millstipe]],giver_loc=[[Consejero Tallolino]],giverType=[[NPC]],giverId=270,ender=[[Councilman Millstipe]],ender_loc=[[Consejero Tallolino]],enderType=[[NPC]],enderId=270,poiX=-10576,poiY=-1109,wowhead=[[https://www.wowhead.com/wotlk/quest=377]],image=[[assets/images/quests/placeholder.png]],desc=[[As if the neglect for the residents of Duskwood was not bad enough, now the House of Nobles spits in the eye of the Darkshire Council with their decision to imprison Dextren Ward in Stormwind rather than behead the villain as per Lord Ebonlocke's sentence. Ward was caught selling bodies from the cemetery to Morbent Fel, a crime punishable by death.  Yet Stormwind claims Ward as their prisoner. Assassinate Ward in The Stormwind Stockade - bring me his hand - and I shall reward you.]],logDesc=[[Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.]],choiceRewards={{id=2033,qty=1},{id=2906,qty=1}}}
DB[378]={id=378,zoneId=717,name=[[The Fury Runs Deep]],name_loc=[[La furia mora en las profundidades]],level=27,minLevel=22,giver=[[Motley Garmason]],giverType=[[NPC]],giverId=1074,ender=[[Motley Garmason]],enderType=[[NPC]],enderId=1074,prevId=303,poiX=-2650,poiY=-2443,wowhead=[[https://www.wowhead.com/wotlk/quest=378]],image=[[assets/images/quests/placeholder.png]],desc=[[You have proven your loyalty to King Magni, $c.  And your hatred for the Dark Iron scum is as great as my own. There is a task I wish to complete myself but I am bound by honor to stay with Longbraid.  But Roggo has gathered intelligence that proves Kam Deepfury was a conspirator in the attack on the Thandol Span.  It was by Deepfury's planning that Longbraid lost his kin. Deepfury is being held for political reasons in the Stormwind Stockade.  I want him dead, $N.  For Longbraid!  Bring me his head!]],logDesc=[[Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.]],choiceRewards={{id=3562,qty=1},{id=1264,qty=1}}}
DB[379]={id=379,zoneId=440,name=[[Slake That Thirst]],name_loc=[[Aplacar esa sed]],level=46,minLevel=38,giver=[[Chief Engineer Bilgewhizzle]],giver_loc=[[Ingeniero jefe Pasaquillas]],giverType=[[NPC]],giverId=7407,ender=[[Chief Engineer Bilgewhizzle]],ender_loc=[[Ingeniero jefe Pasaquillas]],enderType=[[NPC]],enderId=7407,prevId=243,poiX=-7480,poiY=-4786,wowhead=[[https://www.wowhead.com/wotlk/quest=379]],image=[[assets/images/quests/placeholder.png]],desc=[[You want a power source.  I can help you with that.  Know what I want?  I want something to drink!  Bring me five Wastewander Water Pouches, and I'll give you the 4711-FTZ. Now... guess where you can find Wastewander Water Pouches!  Why don't you walk up to one of the Wastewander nomads to the east of here and ask them for one.  Let me know how that works out for you.]],logDesc=[[Bring 5 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan.]],rewards={{id=8524,qty=1}}}
DB[380]={id=380,zoneId=154,name=[[Night Web's Hollow]],name_loc=[[Hoya Nocturácnidas]],level=4,minLevel=2,giver=[[Executor Arren]],giver_loc=[[Ejecutor Arren]],giverType=[[NPC]],giverId=1570,ender=[[Executor Arren]],ender_loc=[[Ejecutor Arren]],enderType=[[NPC]],enderId=1570,prevId=376,rewardNextId=381,poiX=2136,poiY=1652,wowhead=[[https://www.wowhead.com/wotlk/quest=380]],image=[[assets/images/quests/placeholder.png]],desc=[[One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power. There is a gold mine to the northwest that has been overrun with spiders. We need gold from the mine, but we can't very well get it while the spiders are crawling around in there. I've not much manpower to commit to the task, so we'll just have to do it little by little. Get up there and see what you can do for us, $n.]],logDesc=[[Executor Arren wants you to kill 8 Young Night Web Spiders and 5 Night Web Spiders.]],choiceRewards={{id=3270,qty=1},{id=3273,qty=1},{id=3272,qty=1}}}
DB[381]={id=381,zoneId=154,name=[[The Scarlet Crusade]],name_loc=[[La Cruzada Escarlata]],level=4,minLevel=2,giver=[[Executor Arren]],giver_loc=[[Ejecutor Arren]],giverType=[[NPC]],giverId=1570,ender=[[Executor Arren]],ender_loc=[[Ejecutor Arren]],enderType=[[NPC]],enderId=1570,prevId=380,rewardNextId=382,poiX=1748,poiY=1282,wowhead=[[https://www.wowhead.com/wotlk/quest=381]],image=[[assets/images/quests/placeholder.png]],desc=[[You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts.  We can now turn our eyes to other concerns. My scouts have reported that a detachment of the Scarlet Crusade is setting up a camp southeast of here. The Scarlet Crusade is a despicable organization that hunts us, and they will not rest until every undead--Lich King's Scourge or no--is destroyed. We must strike first! Be careful, their unholy zeal makes them dangerous adversaries.]],logDesc=[[Bring Executor Arren 12 Scarlet Armbands from Scarlet Converts and Scarlet Initiates.]],rewards={{id=159,qty=5}},choiceRewards={{id=3268,qty=1},{id=3269,qty=1},{id=3267,qty=1},{id=5779,qty=1}}}
DB[382]={id=382,zoneId=154,name=[[The Red Messenger]],name_loc=[[El mensajero rojo]],level=5,minLevel=2,giver=[[Executor Arren]],giver_loc=[[Ejecutor Arren]],giverType=[[NPC]],giverId=1570,ender=[[Executor Arren]],ender_loc=[[Ejecutor Arren]],enderType=[[NPC]],enderId=1570,prevId=381,poiX=1764,poiY=1384,wowhead=[[https://www.wowhead.com/wotlk/quest=382]],image=[[assets/images/quests/placeholder.png]],desc=[[Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell. According to the reports, the messenger possesses important information on his person. I do not have further details, but whatever it is, we must have it! You're the most qualified person I have to send, $n. Find that messenger and bring me whatever information you can find.]],logDesc=[[Kill Meven Korgal, the messenger, at the Crusader camp, then return any information you find to Executor Arren.]],choiceRewards={{id=3277,qty=1},{id=3276,qty=1}}}
DB[383]={id=383,zoneId=154,name=[[Vital Intelligence]],name_loc=[[Información decisiva]],level=5,minLevel=2,giver=[[Executor Arren]],giver_loc=[[Ejecutor Arren]],giverType=[[NPC]],giverId=1570,ender=[[Executor Zygand]],ender_loc=[[Ejecutor Zygand]],enderType=[[NPC]],enderId=1515,prevId=382,poiX=1764,poiY=1384,wowhead=[[https://www.wowhead.com/wotlk/quest=383]],image=[[assets/images/quests/placeholder.png]],desc=[[These will need to be taken to my superior, Executor Zygand, in Brill. With this information, we'll be able to deal a decisive blow to the Scarlet Crusade. Your services have been useful here in Deathknell, but I need someone to deliver this to Zygand, and I believe he'll be able to find you more appropriate work. Take the road north out of Deathknell. Soon after entering Tirisfal proper, you'll hit a crossroads. Take the eastern fork, and keep going east. You'll pass Cold Hearth Manor along the way.]],logDesc=[[Deliver the Scarlet Crusade Documents to Executor Zygand in Brill.]]}
DB[384]={id=384,name=[[Beer Basted Boar Ribs]],name_loc=[[Costillas de jabalí a la cerveza]],level=7,minLevel=5,giver=[[Ragnar Thunderbrew]],giver_loc=[[Ragnar Cebatruenos]],giverType=[[NPC]],giverId=1267,ender=[[Ragnar Thunderbrew]],ender_loc=[[Ragnar Cebatruenos]],enderType=[[NPC]],enderId=1267,poiX=-5617,poiY=-749,wowhead=[[https://www.wowhead.com/wotlk/quest=384]],image=[[assets/images/quests/placeholder.png]],desc=[[Nothing my tavern patrons enjoy more than some Beer Basted Boar Ribs!  Only problem is, the local trapper who used to bring me supplies enlisted in the King's Army to help with the war on the Alliance front.  Maybe you can help me out?  If you bring me six crag boar ribs and a Rhapsody Malt from the tavern here, I'll give you the family recipe for my famous Beer Basted Boar Ribs, not to mention a free sample!  The secret's in the Malt!]],logDesc=[[Ragnar Thunderbrew in Kharanos wants 6 Crag Boar Ribs and a mug of Rhapsody Malt.]],rewards={{id=2888,qty=5},{id=2889,qty=1}}}
DB[385]={id=385,zoneId=38,name=[[Crocolisk Hunting]],name_loc=[[La caza de crocoliscos]],level=15,minLevel=10,giver=[[Marek Ironheart]],giver_loc=[[Marek Coracero]],giverType=[[NPC]],giverId=1154,ender=[[Marek Ironheart]],ender_loc=[[Marek Coracero]],enderType=[[NPC]],enderId=1154,poiX=-5183,poiY=-3549,wowhead=[[https://www.wowhead.com/wotlk/quest=385]],image=[[assets/images/quests/placeholder.png]],desc=[[Many a hunter is attracted to Loch Modan to hunt our famous crocs. There are always merchants who seek out crocolisk skins for clothing items or armor, and there are also some who enjoy the taste of their meat. We do some trade in this, but not a huge amount, as the crocolisks are ferocious and have entrenched themselves on the islands in the Loch. But don't let me dissuade you, it's quite an experience, wrestling with the jaws of the beasts. Why, this one time...]],logDesc=[[Get 5 pieces of Crocolisk Meat and 6 Crocolisk Skins for Marek Ironheart at the Farstrider Lodge.]],rewards={{id=3678,qty=1},{id=2240,qty=1}}}
DB[386]={id=386,zoneId=717,name=[[What Comes Around...]],name_loc=[[Lo que sucede alrededor...]],level=25,minLevel=22,giver=[[Guard Berton]],giver_loc=[[Guardia Berton]],giverType=[[NPC]],giverId=859,ender=[[Guard Berton]],ender_loc=[[Guardia Berton]],enderType=[[NPC]],enderId=859,poiX=-9249,poiY=-2141,wowhead=[[https://www.wowhead.com/wotlk/quest=386]],image=[[assets/images/quests/placeholder.png]],desc=[[Targorr the Dread served under Gath'Ilzogg as supreme Executioner.  His methods were ruthless, even by filthy orc standards.  Men who fought bravely to defend the Kingdom were tortured on his whim.  Now he is being held in the Stormwind Stockade, sentenced to die.  Yet something is amiss.  One of the bureaucratic nobles put a hold on his execution.  I am sure foul play is in the works. Put an end to Targorr the Dread, $N.  Travel to The Stockade and behead him before trickery is upon us.]],logDesc=[[Bring the head of Targorr the Dread to Guard Berton in Lakeshire.]],choiceRewards={{id=3400,qty=1},{id=1317,qty=1}}}
DB[387]={id=387,zoneId=717,name=[[Quell The Uprising]],name_loc=[[Detener el motín]],level=26,minLevel=22,giver=[[Warden Thelwater]],giver_loc=[[Celador Thelagua]],giverType=[[NPC]],giverId=1719,ender=[[Warden Thelwater]],ender_loc=[[Celador Thelagua]],enderType=[[NPC]],enderId=1719,poiX=-8782,poiY=836,wowhead=[[https://www.wowhead.com/wotlk/quest=387]],image=[[assets/images/quests/placeholder.png]],desc=[[The uprising must be quelled!  I need your assistance.  If word gets out that the prison is overrun I will lose my job!  This is a case of foul play if I've ever seen one.  But what's important now is forcing these prisoners into submission for the safety of Stormwind. The punishment for insurgency is death.  Kill some of these deviants!  That ought to get things under control.]],logDesc=[[Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade.]]}
DB[388]={id=388,zoneId=717,name=[[The Color of Blood]],name_loc=[[El color de la sangre]],level=26,minLevel=22,giver=[[Nikova Raskol]],giverType=[[NPC]],giverId=1721,ender=[[Nikova Raskol]],enderType=[[NPC]],enderId=1721,poiX=-8629,poiY=441,wowhead=[[https://www.wowhead.com/wotlk/quest=388]],image=[[assets/images/quests/placeholder.png]],desc=[[Bitterness flows through my veins like a cold river.  My grandson, Mac, was such a good boy.  A mere 14 years old.  When the army was sent off to the front, Mac took up arms to defend the city.  He was a guard in The Stockade, where the Defias gang is locked up.  Mac reprimanded some of the prisoners for tearing their wool blankets to make scarves, a symbol of their gang.  For that Mac was stabbed in the back. I want revenge.  Bring me 10 of their precious Wool Bandanas.  They are the color of blood.]],logDesc=[[Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas.]]}
DB[389]={id=389,zoneId=1519,name=[[Bazil Thredd]],name_loc=[[Bazil Thredd]],level=22,minLevel=16,giver=[[Baros Alexston]],giver_loc=[[Baros Alexston]],giverType=[[NPC]],giverId=1646,ender=[[Warden Thelwater]],ender_loc=[[Celador Thelagua]],enderType=[[NPC]],enderId=1719,prevId=373,rewardNextId=391,poiX=-8792,poiY=817,wowhead=[[https://www.wowhead.com/wotlk/quest=389]],image=[[assets/images/quests/placeholder.png]],desc=[[VanCleef and I were members of the Stonemasons Guild. Our main project was to rebuild Stormwind after the War. When we had finished our duties, we were cheated. The nobles refused to pay us for our work. Some of the more senior of the Stonemasons were offered governmental jobs, but VanCleef refused it out of loyalty to all the Stonemasons. He led a riot and left the city, swearing revenge. His lieutenant, Bazil Thredd, might know more about VanCleef's plans. He's being held prisoner in the Stockade.]],logDesc=[[Speak with Warden Thelwater in the Stockade.]]}
DB[391]={id=391,zoneId=717,name=[[The Stockade Riots]],name_loc=[[El motín de Las Mazmorras]],level=29,minLevel=16,giver=[[Warden Thelwater]],giver_loc=[[Celador Thelagua]],giverType=[[NPC]],giverId=1719,ender=[[Warden Thelwater]],ender_loc=[[Celador Thelagua]],enderType=[[NPC]],enderId=1719,prevId=389,rewardNextId=392,poiX=-8792,poiY=817,wowhead=[[https://www.wowhead.com/wotlk/quest=391]],image=[[assets/images/quests/placeholder.png]],desc=[[Let's get one thing straight, $N: I don't trust you. But, with the situation as it is, you probably won't make a difference. So here's how it's going to be: go down there and have your talk with Thredd. If you're really on our side, then kill him and bring me his head when the job's done. And if it turns out you're on his side, and don't come out... when we find you, you'll die along with the rest of the maggots.]],logDesc=[[Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.]]}
DB[392]={id=392,zoneId=1519,name=[[The Curious Visitor]],name_loc=[[Extraño visitante]],level=29,minLevel=16,giver=[[Warden Thelwater]],giver_loc=[[Celador Thelagua]],giverType=[[NPC]],giverId=1719,ender=[[Baros Alexston]],ender_loc=[[Baros Alexston]],enderType=[[NPC]],enderId=1646,prevId=391,rewardNextId=393,poiX=-8550,poiY=720,wowhead=[[https://www.wowhead.com/wotlk/quest=392]],image=[[assets/images/quests/placeholder.png]],desc=[[During the first years of Thredd's imprisonment, he never had any visitors. I figured that he was no longer of use to the Brotherhood, so they abandoned him. Anyway, a few months ago, that all changed; he started to get regular visits... once, maybe twice a week. It was a strange man--the quiet type. I had my suspicions, but all his papers checked out. His documents claimed his name was Maelik; here's his description. I don't think he'll be coming to visit Thredd anymore.]],logDesc=[[Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind.]]}
DB[393]={id=393,zoneId=1519,name=[[Shadow of the Past]],name_loc=[[Sombras del pasado]],level=29,minLevel=16,giver=[[Baros Alexston]],giver_loc=[[Baros Alexston]],giverType=[[NPC]],giverId=1646,ender=[[Master Mathias Shaw]],ender_loc=[[Maestro Mathias Shaw]],enderType=[[NPC]],enderId=332,prevId=392,rewardNextId=350,poiX=-8815,poiY=362,wowhead=[[https://www.wowhead.com/wotlk/quest=393]],image=[[assets/images/quests/placeholder.png]],desc=[[I really haven't a clue, $N. There is someone else who might be able to help you, and it so happens that he owes me a favor for--well, let's not get into that. Master Mathias Shaw of SI:7 can be found in the barracks in Old Town. Shaw has his thumb on most of the shady, or underhanded dealings of the city. If anyone knows, it'd be him.]],logDesc=[[Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind.]]}
DB[394]={id=394,zoneId=1519,name=[[The Head of the Beast]],name_loc=[[La cabeza de la bestia]],level=31,minLevel=16,giver=[[Elling Trias]],giver_loc=[[Elling Trias]],giverType=[[NPC]],giverId=482,ender=[[Master Mathias Shaw]],ender_loc=[[Maestro Mathias Shaw]],enderType=[[NPC]],enderId=332,prevId=434,rewardNextId=395,poiX=-8815,poiY=362,wowhead=[[https://www.wowhead.com/wotlk/quest=394]],image=[[assets/images/quests/placeholder.png]],desc=[[Find Shaw in Old Town. Let him know that the Lescovar threat has been dealt with and about your involvement in the Lord's plots against the city. I'm sure he'll be proud to have another hero among Stormwind's citizens. He'll more than likely send you off to meet with the Prince or some other noble. Don't let it get to your head, $N. The nobles can think they rule the city all they want, but some things remain out of their hands.]],logDesc=[[Speak to Mathias Shaw in Stormwind.]]}
DB[395]={id=395,zoneId=1519,name=[[Brotherhood's End]],name_loc=[[El fin de la Hermandad]],level=31,minLevel=16,giver=[[Master Mathias Shaw]],giver_loc=[[Maestro Mathias Shaw]],giverType=[[NPC]],giverId=332,ender=[[Baros Alexston]],ender_loc=[[Baros Alexston]],enderType=[[NPC]],enderId=1646,prevId=394,rewardNextId=396,poiX=-8550,poiY=720,wowhead=[[https://www.wowhead.com/wotlk/quest=395]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, I almost forgot. Alexston came while you were away, he wished to speak with you. No doubt he wishes to report the goings-on of the Defias Brotherhood to the nobles. A bit of advice, $N: if anyone should ask, I would provide all details but that it was your hand that slew Lescovar. Trust me. I am... acquainted... with the ways of such things. And as far as Trias goes, well, speak to no one of him... ever... if you can help it.]],logDesc=[[Speak with Baros Alexston in Stormwind.]]}
DB[396]={id=396,zoneId=1519,name=[[An Audience with the King]],name_loc=[[Una audiencia con el Rey]],level=31,minLevel=16,giver=[[Baros Alexston]],giver_loc=[[Baros Alexston]],giverType=[[NPC]],giverId=1646,ender=[[Lady Katrana Prestor]],enderType=[[NPC]],enderId=1749,prevId=395,poiX=-8441,poiY=333,wowhead=[[https://www.wowhead.com/wotlk/quest=396]],image=[[assets/images/quests/placeholder.png]],desc=[[I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind. Your audience is scheduled soon, so you'd best hurry, it's a bit of a ways to Stormwind Keep.]],logDesc=[[Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.]],rewards={{id=2933,qty=1}}}
DB[396]={id=396,zoneId=1519,name=[[An Audience with the King]],name_loc=[[Una audiencia con el Rey]],level=31,minLevel=16,giver=[[Baros Alexston]],giver_loc=[[Baros Alexston]],giverType=[[NPC]],giverId=1646,ender=[[King Varian Wrynn]],enderType=[[NPC]],enderId=29611,prevId=395,poiX=-8441,poiY=333,wowhead=[[https://www.wowhead.com/wotlk/quest=396]],image=[[assets/images/quests/placeholder.png]],desc=[[I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind. Your audience is scheduled soon, so you'd best hurry, it's a bit of a ways to Stormwind Keep.]],logDesc=[[Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.]],rewards={{id=2933,qty=1}}}
DB[396]={id=396,zoneId=1519,name=[[An Audience with the King]],name_loc=[[Una audiencia con el Rey]],level=31,minLevel=16,giver=[[King Varian Wrynn]],giver_loc=[[Baros Alexston]],giverType=[[NPC]],giverId=29611,ender=[[Lady Katrana Prestor]],enderType=[[NPC]],enderId=1749,prevId=395,poiX=-8441,poiY=333,wowhead=[[https://www.wowhead.com/wotlk/quest=396]],image=[[assets/images/quests/placeholder.png]],desc=[[I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind. Your audience is scheduled soon, so you'd best hurry, it's a bit of a ways to Stormwind Keep.]],logDesc=[[Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.]],rewards={{id=2933,qty=1}}}
DB[396]={id=396,zoneId=1519,name=[[An Audience with the King]],name_loc=[[Una audiencia con el Rey]],level=31,minLevel=16,giver=[[King Varian Wrynn]],giver_loc=[[Baros Alexston]],giverType=[[NPC]],giverId=29611,ender=[[King Varian Wrynn]],enderType=[[NPC]],enderId=29611,prevId=395,poiX=-8441,poiY=333,wowhead=[[https://www.wowhead.com/wotlk/quest=396]],image=[[assets/images/quests/placeholder.png]],desc=[[I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind. Your audience is scheduled soon, so you'd best hurry, it's a bit of a ways to Stormwind Keep.]],logDesc=[[Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.]],rewards={{id=2933,qty=1}}}
DB[397]={id=397,zoneId=1519,name=[[You Have Served Us Well]],name_loc=[[Nos has hecho un gran servicio]],level=30,minLevel=25,giver=[[Zardeth of the Black Claw]],giver_loc=[[Zardeth de los Zarpanegra]],giverType=[[NPC]],giverId=1435,ender=[[Zggi]],ender_loc=[[Zggi]],enderType=[[NPC]],enderId=1733,prevId=336,poiX=-8984,poiY=1024,wowhead=[[https://www.wowhead.com/wotlk/quest=397]],image=[[assets/images/quests/placeholder.png]],desc=[[I hear Lord Wishock enjoyed his beverage.   You have served us well, $N.  The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you.  For your efforts, I have prepared a special gift for you.  Speak with my servant, Zggi, and claim your reward.]],logDesc=[[Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward.]],rewards={{id=3556,qty=1}}}
DB[398]={id=398,zoneId=85,name=[[Wanted: Maggot Eye]],name_loc=[[Se busca: Ojo de cresa]],level=10,minLevel=4,giver=[[Wanted!]],giverType=[[GO]],giverId=711,ender=[[Executor Zygand]],ender_loc=[[Ejecutor Zygand]],enderType=[[NPC]],enderId=1515,poiX=2911,poiY=383,wowhead=[[https://www.wowhead.com/wotlk/quest=398]],image=[[assets/images/quests/placeholder.png]],desc=[[Wanted: Maggot Eye! A foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken.  This despicable villain has been stealing corpses for use by the Lich King's army.  Maggot Eye was last seen pillaging the lands near Garren's Haunt to the north of Brill. The town of Brill hereby offers a reward to the capable soul who can carry out the execution.  Show Executor Zygand the villain's paw once the deed is done. Mercy is for the weak.]],logDesc=[[Kill Maggot Eye and return to Executor Zygand in Brill with his paw for a reward.]],choiceRewards={{id=5941,qty=1},{id=3444,qty=1}}}
DB[399]={id=399,zoneId=1519,name=[[Humble Beginnings]],name_loc=[[Principios humildes]],level=15,minLevel=10,giver=[[Baros Alexston]],giver_loc=[[Baros Alexston]],giverType=[[NPC]],giverId=1646,ender=[[Baros Alexston]],ender_loc=[[Baros Alexston]],enderType=[[NPC]],enderId=1646,poiX=-10672,poiY=1748,wowhead=[[https://www.wowhead.com/wotlk/quest=399]],image=[[assets/images/quests/placeholder.png]],desc=[[It seems an eternity since I was a boy working the farm in Westfall. They say you can never go back, and it's true. Doubly true in my case, my family's home has been burned down and taken over by thieves. I have spoken with my father about the fate of some of my possessions, including my first compass. He was unable to save them. However, he also says that they should be hidden away on the farm. You'll find the Alexston Farmstead west of Sentinel Hill. Perhaps you could go and retrieve it for me?]],logDesc=[[Go to Baros Alexston's house in Westfall and search for his compass, then return it to him in Cathedral Square of Stormwind.]]}
DB[400]={id=400,zoneId=1,name=[[Tools for Steelgrill]],name_loc=[[Herramientas para Brasacerada]],level=5,minLevel=2,giver=[[Tharek Blackstone]],giver_loc=[[Tharek Piedranegra]],giverType=[[NPC]],giverId=1872,ender=[[Beldin Steelgrill]],ender_loc=[[Beldin Brasacerada]],enderType=[[NPC]],enderId=1376,poiX=-5489,poiY=-682,wowhead=[[https://www.wowhead.com/wotlk/quest=400]],image=[[assets/images/quests/placeholder.png]],desc=[[Beldin Steelgrill owns the local mechanic shop, and he's the best siege engine tech there is!  But he's not forgiving to his tools.  I swear he almost breaks more arclight spanners than we can supply him with! We just filled his last order for tools.  If you deliver it to him I'm sure he'll make it worth the effort. His shop, Steelgrill's Depot, is just northeast of Kharanos.  And it's a local haunt for veteran siege engine pilots, so keep your ears open for opportunities while you're there.]],logDesc=[[Deliver Steelgrill's Tools to Beldin Steelgrill.]]}
DB[401]={id=401,zoneId=10,name=[[Wait for Sirra to Finish]],name_loc=[[Espera a que Sirra acabe]],level=30,minLevel=20,giver=[[Sirra Von'Indi]],giver_loc=[[Sirra Von'Indi]],giverType=[[NPC]],giverId=268,ender=[[Sirra Von'Indi]],ender_loc=[[Sirra Von'Indi]],enderType=[[NPC]],enderId=268,prevId=251,rewardNextId=252,poiX=-10574,poiY=-1127,wowhead=[[https://www.wowhead.com/wotlk/quest=401]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm almost finished translating that note.  If you come back in a few moments I should be done.]],logDesc=[[Wait a moment, then speak with Sirra Von'Indi again.]]}
DB[403]={id=403,zoneId=1,name=[[Guarded Thunderbrew Barrel]],name_loc=[[El barril de Cebatruenos custodiado]],level=1,minLevel=1,giver=[[Guarded Thunder Ale Barrel]],giver_loc=[[Barrica de Cerveza del Trueno custodiado]],giverType=[[GO]],giverId=269,ender=[[Guarded Thunder Ale Barrel]],ender_loc=[[Barrica de Cerveza del Trueno custodiado]],enderType=[[GO]],enderId=269,prevId=-310,poiX=-5607,poiY=-548,wowhead=[[https://www.wowhead.com/wotlk/quest=403]],image=[[assets/images/quests/placeholder.png]]}
DB[404]={id=404,zoneId=85,name=[[A Putrid Task]],name_loc=[[Una tarea pútrida]],level=6,minLevel=4,giver=[[Deathguard Dillinger]],giver_loc=[[Guardia de la Muerte Dillinger]],giverType=[[NPC]],giverId=1496,ender=[[Deathguard Dillinger]],ender_loc=[[Guardia de la Muerte Dillinger]],enderType=[[NPC]],enderId=1496,poiX=2441,poiY=487,wowhead=[[https://www.wowhead.com/wotlk/quest=404]],image=[[assets/images/quests/placeholder.png]],desc=[[Scourge have trickled into Tirisfal Glades and have infested the area west of Brill, near the old bridge. Go there and beat back the rotting dead and ravaged corpses you find.  Scatter their bones and bring back their putrid claws, and the Deathguards will reward you.]],logDesc=[[Bring 7 Putrid Claws to Deathguard Dillinger in Brill.]]}
DB[405]={id=405,zoneId=85,name=[[The Prodigal Lich]],name_loc=[[El exánime pródigo]],level=8,minLevel=5,giver=[[Magistrate Sevren]],giver_loc=[[Magistrado Sevren]],giverType=[[NPC]],giverId=1499,ender=[[Bethor Iceshard]],ender_loc=[[Bethor Duroyelo]],enderType=[[NPC]],enderId=1498,prevId=358,rewardNextId=357,poiX=1766,poiY=67,wowhead=[[https://www.wowhead.com/wotlk/quest=405]],image=[[assets/images/quests/placeholder.png]],desc=[[Bethor Iceshard, a high-ranking and powerful mage in the Undercity to the south, commands me to send him an agent with proven worth against the Scourge.  You, $N, will be that agent. Present these orders to Bethor.  He will then instruct you on your mission.  I don't know its details, but it deals with recruiting a wayward Lich.  And it will be dangerous. So ready yourself, $C.  You must not fail. You may find Bethor in the Magic Quarter of the Undercity.]],logDesc=[[Present Sevren's Orders to Bethor Iceshard in the Undercity.]]}
DB[407]={id=407,zoneId=85,name=[[Fields of Grief]],name_loc=[[Campos de pena]],level=7,minLevel=4,giver=[[Apothecary Johaan]],giver_loc=[[Boticario Johaan]],giverType=[[NPC]],giverId=1518,ender=[[Captured Scarlet Zealot]],ender_loc=[[Zelote Escarlata capturado]],enderType=[[NPC]],enderId=1931,prevId=365,poiX=2292,poiY=233,wowhead=[[https://www.wowhead.com/wotlk/quest=407]],image=[[assets/images/quests/placeholder.png]],desc=[[Harmless pumpkins, right?  Or so it would seem.  If we are to defeat Arthas's advances from the North and the Human infestation from the South we need to start realizing the full potential of our gift of undeath. With a little ingenuity a simple pumpkin becomes an agent for our Dark Lady.  This pumpkin, laced with my latest formula, will prove to be quite a treat. Yet another Scarlet Zealot has been captured and is being kept in the cellar of the Gallow's End Tavern.  Take this pumpkin to the fool.]],logDesc=[[Take the Laced Pumpkin to the Captured Scarlet Zealot who is being held in the cellar of the Gallow's End Tavern.]]}
DB[408]={id=408,zoneId=85,name=[[The Family Crypt]],name_loc=[[La Cripta de la Familia]],level=13,minLevel=7,giver=[[Magistrate Sevren]],giver_loc=[[Magistrado Sevren]],giverType=[[NPC]],giverId=1499,ender=[[Magistrate Sevren]],ender_loc=[[Magistrado Sevren]],enderType=[[NPC]],enderId=1499,prevId=355,poiX=2936,poiY=537,wowhead=[[https://www.wowhead.com/wotlk/quest=408]],image=[[assets/images/quests/placeholder.png]],desc=[[The Agamand Mills area has become a foothold for the Scourge.  Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered.  With Necromancy he has raised the ancestors of the Agamands and plans to use them against us. This cannot pass, and you must stop it.  Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors. And, bring me the skull of Captain Dargol.]],logDesc=[[Kill 8 Wailing Ancestors and 8 Rotting Ancestors. Kill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.]],choiceRewards={{id=3446,qty=1},{id=3440,qty=1}}}
DB[409]={id=409,zoneId=85,name=[[Proving Allegiance]],name_loc=[[Prueba de lealtad]],level=12,minLevel=5,giver=[[Gunther Arcanus]],giver_loc=[[Gunther Arcanos]],giverType=[[NPC]],giverId=1497,ender=[[Gunther Arcanus]],ender_loc=[[Gunther Arcanos]],enderType=[[NPC]],enderId=1497,prevId=366,rewardNextId=411,poiX=2471,poiY=15,wowhead=[[https://www.wowhead.com/wotlk/quest=409]],image=[[assets/images/quests/placeholder.png]],desc=[[You say you are not bound by the will of the Lich King, and the enchantment Bethor placed upon my book corroborates this.  But before I believe you I must have proof that you are enemy to the Scourge. There is an old, bloody altar just off the southern coast of this island.  it is used by a powerful Scourge agent, Lillith Nefara. Take a Candle of Beckoning from this crate here.  Light it on the altar and Lillith will awake.  Destroy Lillith, and I will believe you are the Lich King's foe.]],logDesc=[[Obtain a Candle of Beckoning. Summon Lillith Nefara and kill her. Return to Gunther on his island.]]}
DB[410]={id=410,zoneId=85,name=[[The Dormant Shade]],name_loc=[[Sombra durmiente]],level=10,minLevel=5,giver=[[Lillith's Dinner Table]],giver_loc=[[Mesa de cena de Lillith]],giverType=[[GO]],giverId=1557,ender=[[Lillith's Dinner Table]],ender_loc=[[Mesa de cena de Lillith]],enderType=[[GO]],enderId=1557,prevId=-409,poiX=2485,poiY=22,wowhead=[[https://www.wowhead.com/wotlk/quest=410]],image=[[assets/images/quests/placeholder.png]]}
DB[411]={id=411,zoneId=85,name=[[The Prodigal Lich Returns]],name_loc=[[El regreso del exánime pródigo]],level=12,minLevel=5,giver=[[Gunther Arcanus]],giver_loc=[[Gunther Arcanos]],giverType=[[NPC]],giverId=1497,ender=[[Bethor Iceshard]],ender_loc=[[Bethor Duroyelo]],enderType=[[NPC]],enderId=1498,prevId=409,poiX=1766,poiY=67,wowhead=[[https://www.wowhead.com/wotlk/quest=411]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this Nether Gem to my old comrade Bethor.  It will let us communicate ... and I have much to tell him.]],logDesc=[[Bring the Nether Gem to Bethor Iceshard in the Undercity.]],rewards={{id=5940,qty=1}}}
DB[412]={id=412,zoneId=1,name=[[Operation Recombobulation]],name_loc=[[Operación Recombobulación]],level=10,minLevel=7,giver=[[Razzle Sprysprocket]],giver_loc=[[Razzle Engranágil]],giverType=[[NPC]],giverId=1269,ender=[[Razzle Sprysprocket]],ender_loc=[[Razzle Engranágil]],enderType=[[NPC]],enderId=1269,poiX=-5057,poiY=418,wowhead=[[https://www.wowhead.com/wotlk/quest=412]],image=[[assets/images/quests/placeholder.png]],desc=[[Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes. Ozzie and I plan to reverse the horrible leper effect with our latest invention: The Recombobulator.  The machine is almost complete but we are in dire need of some Restabilization Cogs and Gyromechanic Gears.  Retrieve some from the leper gnomes out front of Gnomeregan for us.]],logDesc=[[Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.]],choiceRewards={{id=3152,qty=1},{id=3153,qty=1}}}
DB[413]={id=413,zoneId=1,name=[[Shimmer Stout]],name_loc=[[Cerveza negra Brillante]],level=10,minLevel=8,giver=[[Rejold Barleybrew]],giver_loc=[[Rejold Cebadiz]],giverType=[[NPC]],giverId=1374,ender=[[Mountaineer Barleybrew]],ender_loc=[[Montaraz Cebadiz]],enderType=[[NPC]],enderId=1959,prevId=315,rewardNextId=414,poiX=-5480,poiY=-2447,wowhead=[[https://www.wowhead.com/wotlk/quest=413]],image=[[assets/images/quests/placeholder.png]],desc=[[I'd like my brother Wellart to try my new Shimmer Stout.  He's a Mountaineer stationed in the southern guard tower, one of two towers on the border to Loch Modan. He may not be a brewer like the rest of us Barleybrews, but he loves his drinks and I know he'll like this one. Can you bring him this Barrel of Shimmer Stout for me?]],logDesc=[[Take the Barrel of Shimmer Stout to Mountaineer Barleybrew.]]}
DB[414]={id=414,zoneId=1,name=[[Stout to Kadrell]],name_loc=[[Cerveza negra para Kadrell]],level=10,minLevel=8,giver=[[Mountaineer Barleybrew]],giver_loc=[[Montaraz Cebadiz]],giverType=[[NPC]],giverId=1959,ender=[[Mountaineer Kadrell]],ender_loc=[[Montaraz Kadrell]],enderType=[[NPC]],enderId=1340,prevId=413,poiX=-5402,poiY=-2895,wowhead=[[https://www.wowhead.com/wotlk/quest=414]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been drinking more of that Shimmer Stout my brother made - it's great stuff!  I want a fellow Mountaineer to try it.  His name's Kadrell, and he's usually patrolling the road through Thelsamar in Loch Modan. To get to Thelsamar, go southeast through the tunnel, then turn northeast when the path forks into a road.  Follow that road straight into Thelsamar. Give Mountaineer Kadrell this cask of Shimmer Stout and see what he thinks!]],logDesc=[[Take the Cask of Shimmer Stout to Mountaineer Kadrell in Loch Modan.]]}
DB[415]={id=415,zoneId=1,name=[[Rejold's New Brew]],name_loc=[[La nueva bebida de Rejold]],level=10,minLevel=8,giver=[[Tharek Blackstone]],giver_loc=[[Tharek Piedranegra]],giverType=[[NPC]],giverId=1872,ender=[[Rejold Barleybrew]],ender_loc=[[Rejold Cebadiz]],enderType=[[NPC]],enderId=1374,prevId=315,rewardNextId=413,poiX=-5378,poiY=315,wowhead=[[https://www.wowhead.com/wotlk/quest=415]],image=[[assets/images/quests/placeholder.png]],desc=[[Rejold Barleybrew at Brewnall Village has been asking for you. He wants to talk to you about a new drink he's been brewing...said something about you helping him with it.  You might want to head back to Brewnall Village and see what he has to say. There could be some free booze in it for you...]],logDesc=[[Speak with Rejold Barleybrew.]],rewards={{id=3087,qty=1}}}
DB[416]={id=416,zoneId=38,name=[[Rat Catching]],name_loc=[[Mata ratas]],level=11,minLevel=10,giver=[[Mountaineer Kadrell]],giver_loc=[[Montaraz Kadrell]],giverType=[[NPC]],giverId=1340,ender=[[Mountaineer Kadrell]],ender_loc=[[Montaraz Kadrell]],enderType=[[NPC]],enderId=1340,poiX=-4669,poiY=-3115,wowhead=[[https://www.wowhead.com/wotlk/quest=416]],image=[[assets/images/quests/placeholder.png]],desc=[[We have a real infestation problem to the west.  Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth! We want them eliminated.  Hunt them, bring me their ears and earn their bounty. You can find tunnel rat kobolds and their dens west of Thelsamar, littered along the mountainside.]],logDesc=[[Bring 12 Tunnel Rat Ears to Mountaineer Kadrell in Thelsamar.]],choiceRewards={{id=3158,qty=1},{id=860,qty=1}}}
DB[417]={id=417,zoneId=1,name=[[A Pilot's Revenge]],name_loc=[[Vengar al piloto]],level=11,minLevel=8,giver=[[A Dwarven Corpse]],giver_loc=[[Un cadáver de enano]],giverType=[[GO]],giverId=2059,ender=[[Pilot Hammerfoot]],ender_loc=[[Piloto Podomartillo]],enderType=[[NPC]],enderId=1960,prevId=419,poiX=-5117,poiY=-2056,wowhead=[[https://www.wowhead.com/wotlk/quest=417]],image=[[assets/images/quests/placeholder.png]],desc=[[Hildelve wrote in his journal that he was attacked by Mangeclaw, a "huge Ice Claw Bear."  He drove off the beast, but not before it mauled him savagely. Judging from the state of Hildelve's body, Mangeclaw must have later returned and killed him. However, Hildelve wrote in his journal his one, final wish: Revenge against Mangeclaw.]],logDesc=[[Kill Mangeclaw. Bring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot.]],choiceRewards={{id=2218,qty=1},{id=1009,qty=1}}}
DB[418]={id=418,zoneId=38,name=[[Thelsamar Blood Sausages]],name_loc=[[Morcillas de Thelsamar]],level=11,minLevel=7,giver=[[Vidra Hearthstove]],giver_loc=[[Vidra Hogartufa]],giverType=[[NPC]],giverId=1963,ender=[[Vidra Hearthstove]],ender_loc=[[Vidra Hogartufa]],enderType=[[NPC]],enderId=1963,poiX=-5749,poiY=-3283,wowhead=[[https://www.wowhead.com/wotlk/quest=418]],image=[[assets/images/quests/placeholder.png]],desc=[[There's never a shortage of empty bellies here in Thelsamar, kids running in and out, workers from the excavation coming in after  a hard day's work. We're famous for our blood sausages, I don't suppose you've ever tried them? No? Well, around here you've got to work for your meals, and don't think just because you're a fancy $c, you'll be any exception. I'll need bear meat, boar intestines for the casings, and spider ichor for spice. You get me some of those, and leave the cooking to Vidra!]],logDesc=[[Bring 3 pieces of Bear Meat, 3 Boar Intestines, and 3 Spider Ichor to Vidra Hearthstove in Thelsamar.]],rewards={{id=3220,qty=5},{id=3679,qty=1}}}
DB[419]={id=419,zoneId=1,name=[[The Lost Pilot]],name_loc=[[El piloto perdido]],level=10,minLevel=8,giver=[[Pilot Hammerfoot]],giver_loc=[[Piloto Podomartillo]],giverType=[[NPC]],giverId=1960,ender=[[A Dwarven Corpse]],ender_loc=[[Un cadáver de enano]],enderType=[[GO]],enderId=2059,rewardNextId=417,poiX=-5065,poiY=-2122,wowhead=[[https://www.wowhead.com/wotlk/quest=419]],image=[[assets/images/quests/placeholder.png]],desc=[[My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills.  We were looking for a rare ore that's needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it! Still convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot, searching. It's been days, and I've heard some beastly growls in the hills at night.  Mori's tough as nails, but I'm worried. Please, $N.  Find him.]],logDesc=[[Find Pilot Hildelve.]],rewards={{id=3151,qty=1}}}
DB[420]={id=420,zoneId=132,name=[[Senir's Observations]],name_loc=[[Las observaciones de Senir]],level=5,minLevel=1,giver=[[Mountaineer Thalos]],giver_loc=[[Montaraz Thalos]],giverType=[[NPC]],giverId=1965,ender=[[Senir Whitebeard]],ender_loc=[[Senir Barbablanca]],enderType=[[NPC]],enderId=1252,prevId=282,poiX=-5644,poiY=-499,wowhead=[[https://www.wowhead.com/wotlk/quest=420]],image=[[assets/images/quests/placeholder.png]],desc=[[The troggs in the tunnel are extremely hostile, and haven't shown any hesitation in attacking travelers through the tunnel. You seem tough enough, though, so you should probably be safe. Directions? If you're going to speak with Senir, you'll find him in Kharanos. Make your way through the tunnel, and after you come out on the other side, just keep following the road, it'll run right into Kharanos.]],logDesc=[[Deliver Grelin's report to Senir Whitebeard in Kharanos.]]}
DB[421]={id=421,zoneId=130,name=[[Prove Your Worth]],name_loc=[[Demuestra tu valía]],level=10,minLevel=9,giver=[[Dalar Dawnweaver]],giver_loc=[[Dalar Tejealba]],giverType=[[NPC]],giverId=1938,ender=[[Dalar Dawnweaver]],ender_loc=[[Dalar Tejealba]],enderType=[[NPC]],enderId=1938,rewardNextId=422,poiX=1101,poiY=1081,wowhead=[[https://www.wowhead.com/wotlk/quest=421]],image=[[assets/images/quests/placeholder.png]],desc=[[Lady Sylvanas has charged Varimathras with the conquering of the human and dwarven lands to the south. But that fool, Arugal -- charlatan of Dalaran and now cursed beast of Shadowfang Keep -- let his reckless magic wreak havoc with the strategic stronghold of Silverpine Forest. I need someone skilled in the ways of combat to help clean up Arugal's mess.  Prove yourself to me by killing 5 Moonrage Whitescalps.  The wretched beasts can often be found just off the road, down the hill below.]],logDesc=[[Dalar Dawnweaver at the Sepulcher wants you to kill 5 Moonrage Whitescalps.]]}
DB[422]={id=422,zoneId=130,name=[[Arugal's Folly]],name_loc=[[La locura de Arugal]],level=11,minLevel=9,giver=[[Dalar Dawnweaver]],giver_loc=[[Dalar Tejealba]],giverType=[[NPC]],giverId=1938,ender=[[Dalar Dawnweaver]],ender_loc=[[Dalar Tejealba]],enderType=[[NPC]],enderId=1938,prevId=421,rewardNextId=423,poiX=866,poiY=1231,wowhead=[[https://www.wowhead.com/wotlk/quest=422]],image=[[assets/images/quests/placeholder.png]],desc=[[How Arugal gained acceptance within the Kirin Tor is beyond me.  His spell-casting knowledge seemed as transparent as a blown glass bauble. What's important now is learning exactly what magic Arugal used so that I can turn it against him and secure Silverpine Forest for the Dark Lady. Arugal first stayed at the wheat farm just north of the bridge.  One of the Deathstalkers reported seeing some spellbooks but could not secure them.  Retrieve for me the spell labeled Remedy of Arugal from those books.]],logDesc=[[Retrieve the Remedy of Arugal for Dalar Dawnweaver at the Sepulcher.]]}
DB[423]={id=423,zoneId=130,name=[[Arugal's Folly]],name_loc=[[La locura de Arugal]],level=14,minLevel=9,giver=[[Dalar Dawnweaver]],giver_loc=[[Dalar Tejealba]],giverType=[[NPC]],giverId=1938,ender=[[Dalar Dawnweaver]],ender_loc=[[Dalar Tejealba]],enderType=[[NPC]],enderId=1938,prevId=422,rewardNextId=424,poiX=866,poiY=1500,wowhead=[[https://www.wowhead.com/wotlk/quest=423]],image=[[assets/images/quests/placeholder.png]],desc=[[After examining Arugal's work my worst suspicions were confirmed.  The old hack was not qualified to clean chamber pots in Dalaran let alone represent the Kirin Tor in its most dire hour.  Fools! Arugal used enchanted items to reinforce his weak magic.  I need to examine these items first hand.  Travel forth and slay Moonrage Gluttons and Moonrage Darksouls until you have collected enough of their enchanted shackles for my research.  The foul creatures have been seen to the north and east.]],logDesc=[[Bring 6 Glutton Shackles and 3 Darksoul Shackles to Dalar Dawnweaver at the Sepulcher.]]}
DB[424]={id=424,zoneId=130,name=[[Arugal's Folly]],name_loc=[[La locura de Arugal]],level=15,minLevel=9,giver=[[Dalar Dawnweaver]],giver_loc=[[Dalar Tejealba]],giverType=[[NPC]],giverId=1938,ender=[[Dalar Dawnweaver]],ender_loc=[[Dalar Tejealba]],enderType=[[NPC]],enderId=1938,prevId=423,rewardNextId=99,poiX=411,poiY=990,wowhead=[[https://www.wowhead.com/wotlk/quest=424]],image=[[assets/images/quests/placeholder.png]],desc=[[It will indeed take me longer than I had thought to uncover the dark secrets behind the enchantments Arugal was using. But in the meantime I need you to take care of a slight problem our Darkstalkers have discovered.  It seems that Arugal let his magic spread to the Deep Elem Mine in the hills to the southeast. The mine would prove to be quite a resource for Varimathras's advance. I want you to behead the tainted foreman of the mine, Grimson the Pale.  With his death, the mine shall be ours.]],logDesc=[[Kill Grimson the Pale and bring his head to Dalar Dawnweaver at the Sepulcher.]]}
DB[425]={id=425,zoneId=130,name=[[Ivar the Foul]],name_loc=[[Ivar el Hediondo]],level=12,minLevel=10,giver=[[Rane Yorick]],giver_loc=[[Rane Yorick]],giverType=[[NPC]],giverId=1950,ender=[[Rane Yorick]],ender_loc=[[Rane Yorick]],enderType=[[NPC]],enderId=1950,prevId=430,poiX=1277,poiY=1286,wowhead=[[https://www.wowhead.com/wotlk/quest=425]],image=[[assets/images/quests/placeholder.png]],desc=[[My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec.  But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul. We escaped from Ivar, but he seriously mauled Quinn.  He's healing from the potion you gave him, but Ivar may return before Quinn recovers. Kill Ivar so Quinn will have time to heal.  Ivar is usually in the barn yonder, waiting for my guard to drop.]],logDesc=[[Kill Ivar the Foul, and bring Ivar's Head to Rane Yorick at the Ivar Patch.]],choiceRewards={{id=3453,qty=1},{id=3583,qty=1}}}
DB[426]={id=426,zoneId=85,name=[[The Mills Overrun]],name_loc=[[La invasión de los molinos]],level=8,minLevel=6,giver=[[Deathguard Dillinger]],giver_loc=[[Guardia de la Muerte Dillinger]],giverType=[[NPC]],giverId=1496,ender=[[Deathguard Dillinger]],ender_loc=[[Guardia de la Muerte Dillinger]],enderType=[[NPC]],enderId=1496,prevId=404,poiX=2850,poiY=717,wowhead=[[https://www.wowhead.com/wotlk/quest=426]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge are trying to form a base at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal. The orders have been given.  The Scourge in the Mills must be destroyed. Go to the Mills.  Collect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters. To get to the Mills, follow the road west.  After crossing the bridge, take the next fork north then keep going north.  When you see windmills, the battle will begin.]],logDesc=[[Gather 5 Notched Ribs and 3 Blackened Skulls, then return to Deathguard Dillinger in Brill.]],choiceRewards={{id=3447,qty=1},{id=3834,qty=1}}}
DB[427]={id=427,zoneId=85,name=[[At War With The Scarlet Crusade]],name_loc=[[En guerra con la Cruzada Escarlata]],level=8,minLevel=5,giver=[[Executor Zygand]],giver_loc=[[Ejecutor Zygand]],giverType=[[NPC]],giverId=1515,ender=[[Executor Zygand]],ender_loc=[[Ejecutor Zygand]],enderType=[[NPC]],enderId=1515,rewardNextId=370,poiX=2398,poiY=1349,wowhead=[[https://www.wowhead.com/wotlk/quest=427]],image=[[assets/images/quests/placeholder.png]],desc=[[The documents Executor Arren provided are just the break we needed in our battle with the wretched Scarlet Crusade.  We now know their exact locations throughout Tirisfal Glades. But the Deathguard has larger concerns.  The Lich King's army grows in number each night.  We need someone with "initiative" like yourself to drive the Scarlet Crusade to the grave. Prove to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slay 10 Scarlet Warriors.]],logDesc=[[Executor Zygand of Brill wants you to kill 10 Scarlet Warriors.]]}
DB[428]={id=428,zoneId=130,name=[[Lost Deathstalkers]],name_loc=[[Los Mortacechadores desaparecidos]],level=12,minLevel=10,giver=[[High Executor Hadrec]],giver_loc=[[Sumo ejecutor Hadrec]],giverType=[[NPC]],giverId=1952,ender=[[Rane Yorick]],ender_loc=[[Rane Yorick]],enderType=[[NPC]],enderId=1950,rewardNextId=429,poiX=1291,poiY=1205,wowhead=[[https://www.wowhead.com/wotlk/quest=428]],image=[[assets/images/quests/placeholder.png]],desc=[[A couple weeks ago two of our Deathstalkers, Rane and Quinn Yorick, were sent on a reconnaissance mission through northern Silverpine.  We have not heard from them. They may have become victim to the Scourge, though if that is true then I want it confirmed.  Find these Deathstalkers. Their first objective was to scout the farms in northern Silverpine.  You should begin your search there.]],logDesc=[[Find the Deathstalkers Quinn and Rane Yorick.]]}
DB[429]={id=429,zoneId=130,name=[[Wild Hearts]],name_loc=[[Corazones salvajes]],level=11,minLevel=10,giver=[[Rane Yorick]],giver_loc=[[Rane Yorick]],giverType=[[NPC]],giverId=1950,ender=[[Apothecary Renferrel]],ender_loc=[[Boticario Renferrel]],enderType=[[NPC]],enderId=1937,rewardNextId=430,poiX=-715,poiY=1347,wowhead=[[https://www.wowhead.com/wotlk/quest=429]],image=[[assets/images/quests/placeholder.png]],desc=[[My brother Quinn was badly hurt by the ghoul, Ivar the Foul, and I don't know if he will heal properly without magical aid.  Although I am not an apothecary, I do know that our apothecaries can make healing potions from the discolored hearts of worgs. Gather such hearts and take them to Apothecary Renferrel at the Sepulcher to the south.  Then return here with the potion. You can find plenty of worgs between here and Malden's Orchard to the east.]],logDesc=[[Gather 6 discolored worg hearts and bring them to Apothecary Renferrel at the Sepulcher.]],rewards={{id=4597,qty=1},{id=4596,qty=1}}}
DB[430]={id=430,zoneId=130,name=[[Return to Quinn]],name_loc=[[Regresa junto a Quinn]],level=11,minLevel=10,giver=[[Apothecary Renferrel]],giver_loc=[[Boticario Renferrel]],giverType=[[NPC]],giverId=1937,ender=[[Quinn Yorick]],ender_loc=[[Quinn Yorick]],enderType=[[NPC]],enderId=1951,prevId=429,poiX=1314,poiY=1206,wowhead=[[https://www.wowhead.com/wotlk/quest=430]],image=[[assets/images/quests/placeholder.png]],desc=[[Here is the potion to aid in Quinn Yorick's recovery. Now if you will excuse me, I have very important work to continue...]],logDesc=[[Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher.]]}
DB[431]={id=431,zoneId=85,name=[[Candles of Beckoning]],name_loc=[[Velas de señalización]],level=10,minLevel=5,giver=[[Crate of Candles]],giver_loc=[[Cajón de velas]],giverType=[[GO]],giverId=1586,ender=[[Crate of Candles]],ender_loc=[[Cajón de velas]],enderType=[[GO]],enderId=1586,prevId=-409,poiX=2572,poiY=-47,wowhead=[[https://www.wowhead.com/wotlk/quest=431]],image=[[assets/images/quests/placeholder.png]],rewards={{id=3080,qty=1}}}
DB[432]={id=432,zoneId=1,name=[[Those Blasted Troggs!]],name_loc=[[¡Malditos troggs!]],level=9,minLevel=5,giver=[[Foreman Stonebrow]],giver_loc=[[Supervisor Petrocejas]],giverType=[[NPC]],giverId=1254,ender=[[Foreman Stonebrow]],ender_loc=[[Supervisor Petrocejas]],enderType=[[NPC]],enderId=1254,poiX=-5634,poiY=-1806,wowhead=[[https://www.wowhead.com/wotlk/quest=432]],image=[[assets/images/quests/placeholder.png]],desc=[[Those Light-blasted troggs, turning my work site into a wreck! Look at that, there goes another barrel of powder! Ohhh, I wish I could go down there and wring every one of their scrawny little necks! I want to kill them all! This can't be good for my health, all this stress and anger... What have they left me with? Nothing! I'd kill them myself, but my aim's no good anymore! You go into the quarry and kill some of the filthy buggers! I'll pay you! Just hurt them, kill them!]],logDesc=[[Kill 6 Rockjaw Skullthumpers for Foreman Stonebrow at the Gol'Bolar quarry.]]}
DB[433]={id=433,zoneId=1,name=[[The Public Servant]],name_loc=[[El servidor público]],level=11,minLevel=6,giver=[[Senator Mehr Stonehallow]],giver_loc=[[Senador Mehr Piedrasanta]],giverType=[[NPC]],giverId=1977,ender=[[Senator Mehr Stonehallow]],ender_loc=[[Senador Mehr Piedrasanta]],enderType=[[NPC]],enderId=1977,poiX=-5600,poiY=-1856,wowhead=[[https://www.wowhead.com/wotlk/quest=433]],image=[[assets/images/quests/placeholder.png]],desc=[[As a member of the Senate and the Explorers' League, I've taken it upon myself to take care of this part of the trogg infestation that has gripped our lands. They've certainly made a mess of Gol'Bolar quarry, and for no reason. As we dug deep into the earth, they poured out, destroying our equipment and driving the miners out. There's not much for us to do but to exterminate the lot of them, rebuild, then get back to work. If you help me with the troggs, I'll gladly recompense you for your time.]],logDesc=[[Kill 10 Rockjaw Bonesnappers for Senator Mehr Stonehallow at the Gol'Bolar quarry.]]}
DB[434]={id=434,zoneId=1519,name=[[The Attack!]],name_loc=[[El ataque]],level=31,minLevel=16,giver=[[Tyrion]],giverType=[[NPC]],giverId=7766,ender=[[Elling Trias]],ender_loc=[[Elling Trias]],enderType=[[NPC]],enderId=482,prevId=2746,rewardNextId=394,poiX=-8854,poiY=576,wowhead=[[https://www.wowhead.com/wotlk/quest=434]],image=[[assets/images/quests/placeholder.png]],desc=[[After I put on Spybot's disguise, he'll head in to talk to Lescovar. The guards should let him pass no problem. While you were getting materials for me, I took care of informing Marzon that it was time for him and Lescovar to meet again. I even dropped some false information. Lescovar will dismiss his guards and wait for Marzon out here in the garden. After you catch wind of talk about the Defias, make your move. You need to kill them both before the guards return! When you're done, speak to Trias.]],logDesc=[[Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind.]]}
DB[435]={id=435,zoneId=130,name=[[Escorting Erland]],name_loc=[[Escolta a Erland]],level=11,minLevel=10,giver=[[Deathstalker Erland]],giver_loc=[[Mortacechador Erland]],giverType=[[NPC]],giverId=1978,ender=[[Rane Yorick]],ender_loc=[[Rane Yorick]],enderType=[[NPC]],enderId=1950,rewardNextId=449,poiX=1291,poiY=1205,wowhead=[[https://www.wowhead.com/wotlk/quest=435]],image=[[assets/images/quests/placeholder.png]],desc=[[The wolves outside won't leave, and they eye me evilly every time I step foot out that door.  They must be incredibly hungry to think I'm worth eating. I have to report to my teammate, the Deathstalker Rane Yorick.  And to get to Rane, I'll need help against those wolves. Please escort me!  And there are a lot of wolves out there, so we'll have a better chance if you have friends who can help...]],logDesc=[[Escort Erland through the wolves, to Rane Yorick.]],rewards={{id=3455,qty=1}}}
DB[436]={id=436,zoneId=38,name=[[Ironband's Excavation]],name_loc=[[La excavación de Vetaferro]],level=18,minLevel=13,giver=[[Jern Hornhelm]],giver_loc=[[Jern Cornamenta]],giverType=[[NPC]],giverId=1105,ender=[[Magmar Fellhew]],ender_loc=[[Magmar Ceñimal]],enderType=[[NPC]],enderId=1345,rewardNextId=297,poiX=-5714,poiY=-3784,wowhead=[[https://www.wowhead.com/wotlk/quest=436]],image=[[assets/images/quests/placeholder.png]],desc=[[Prospector Ironband is heading an excavation of ancient ruins east of the lake.  His progress has been slow lately, especially considering all the supplies we've sent him. Ironband's a stout, honest dwarf who values results, which has me worried that forces are at work against him. Go to Ironband's Excavation and speak with Magmar Fellhew.  He manages the details of the site and will know why there's a slowdown. To get to the excavation site, go around the southern tip of the lake, then head east.]],logDesc=[[Speak with Explorer Fellhew.]]}
DB[437]={id=437,zoneId=130,name=[[The Dead Fields]],name_loc=[[El Campo Muerto]],level=14,minLevel=10,giver=[[High Executor Hadrec]],giver_loc=[[Sumo ejecutor Hadrec]],giverType=[[NPC]],giverId=1952,ender=[[High Executor Hadrec]],ender_loc=[[Sumo ejecutor Hadrec]],enderType=[[NPC]],enderId=1952,rewardNextId=438,poiX=1074,poiY=1543,wowhead=[[https://www.wowhead.com/wotlk/quest=437]],image=[[assets/images/quests/placeholder.png]],desc=[[Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields.  We have sent small assaults against them, but each time they are reinforced by the banshee Nightlash, who uses her magic to rout our forces. We want Nightlash destroyed. Go to the Dead Fields and assault the rot hides.  If you don't see Nightlash then kill the rot hides until she appears, then defeat her. Her essence will turn to dust.  Bring me that dust as proof.]],logDesc=[[Kill rot hide gnolls at the Dead Fields. When Nightlash appears, kill her. Bring the Essence of Nightlash to High Executor Hadrec at the Sepulcher.]],rewards={{id=3454,qty=1}}}
DB[438]={id=438,zoneId=130,name=[[The Decrepit Ferry]],name_loc=[[El Viejo Embarcadero]],level=16,minLevel=10,giver=[[High Executor Hadrec]],giver_loc=[[Sumo ejecutor Hadrec]],giverType=[[NPC]],giverId=1952,ender=[[Corpse Laden Boat]],enderType=[[GO]],enderId=1593,prevId=437,rewardNextId=439,poiX=690,poiY=996,wowhead=[[https://www.wowhead.com/wotlk/quest=438]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, we've discovered a new hive for the Scourge: the Decrepit Ferry.  The ferry lies east of the Sepulcher, and is heavily patrolled by rot hides and other undead. There must be a reason for the Scourge's occupation of the area.  Go to the Decrepit Ferry and find out why the Scourge are there.]],logDesc=[[Go to the Decrepit Ferry. Search for the reason the Scourge are there.]]}
DB[439]={id=439,zoneId=130,name=[[Rot Hide Clues]],name_loc=[[Pistas de Putrepellejos]],level=16,minLevel=10,giver=[[Corpse Laden Boat]],giverType=[[GO]],giverId=1593,ender=[[High Executor Hadrec]],ender_loc=[[Sumo ejecutor Hadrec]],enderType=[[NPC]],enderId=1952,prevId=438,rewardNextId=443,poiX=522,poiY=1626,wowhead=[[https://www.wowhead.com/wotlk/quest=439]],image=[[assets/images/quests/placeholder.png]],desc=[[Among the corpses a hand protrudes, unwrapped.  It is the hand of a woman, pockmarked from the plague but relatively fresh.   On the hand is a ring.  Removing the ring and inspecting it reveals an engraving: "For Deliah"]],logDesc=[[Bring Deliah's Ring to High Executor Hadrec at the Sepulcher.]]}
DB[440]={id=440,zoneId=130,name=[[The Engraved Ring]],name_loc=[[El anillo grabado]],level=16,minLevel=10,giver=[[High Executor Hadrec]],giver_loc=[[Sumo ejecutor Hadrec]],giverType=[[NPC]],giverId=1952,ender=[[Magistrate Sevren]],ender_loc=[[Magistrado Sevren]],enderType=[[NPC]],enderId=1499,prevId=439,rewardNextId=441,poiX=2306,poiY=265,wowhead=[[https://www.wowhead.com/wotlk/quest=440]],image=[[assets/images/quests/placeholder.png]],desc=[[If you want to find the husband or beloved who gave Deliah her ring... then speak with Magistrate Sevren in Brill.  He should have records of recent deaths and, with luck, can discover who Deliah is. But I wouldn't hope.  Whoever gave her the ring is probably dead.  Or if he's undead he probably no longer cares about Deliah.]],logDesc=[[Bring Deliah's Ring to Magistrate Sevren in Brill.]]}
DB[441]={id=441,zoneId=130,name=[[Raleigh and the Undercity]],name_loc=[[Raleigh y Entrañas]],level=16,minLevel=10,giver=[[Magistrate Sevren]],giver_loc=[[Magistrado Sevren]],giverType=[[NPC]],giverId=1499,ender=[[Raleigh Andrean]],ender_loc=[[Raleigh Andrean]],enderType=[[NPC]],enderId=2050,prevId=440,rewardNextId=530,poiX=1604,poiY=278,wowhead=[[https://www.wowhead.com/wotlk/quest=441]],image=[[assets/images/quests/placeholder.png]],desc=[[Deliah had a husband, Raleigh, who now dwells in the Undercity.  If the Deliah who lived in Brill is the one who owned this ring, then Raleigh will know. Raleigh is in the Trade Quarter of the Undercity.]],logDesc=[[Bring Deliah's Ring to Raleigh.]]}
DB[442]={id=442,zoneId=130,name=[[Assault on Fenris Isle]],name_loc=[[Asalto a la Isla de Fenris]],level=20,minLevel=10,giver=[[High Executor Hadrec]],giver_loc=[[Sumo ejecutor Hadrec]],giverType=[[NPC]],giverId=1952,ender=[[High Executor Hadrec]],ender_loc=[[Sumo ejecutor Hadrec]],enderType=[[NPC]],enderId=1952,prevId=448,poiX=1004,poiY=690,wowhead=[[https://www.wowhead.com/wotlk/quest=442]],image=[[assets/images/quests/placeholder.png]],desc=[[Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle. You must again go to the Isle and destroy Thule Ravenclaw.  I want his head! This mission is as dangerous as it is vital, $N.  You must not fail.]],logDesc=[[Bring Thule's Head to High Executor Hadrec at the Sepulcher.]],choiceRewards={{id=3461,qty=1},{id=3462,qty=1}}}
DB[443]={id=443,zoneId=130,name=[[Rot Hide Ichor]],name_loc=[[Icor de Putrepellejo]],level=17,minLevel=10,giver=[[High Executor Hadrec]],giver_loc=[[Sumo ejecutor Hadrec]],giverType=[[NPC]],giverId=1952,ender=[[Apothecary Renferrel]],ender_loc=[[Boticario Renferrel]],enderType=[[NPC]],enderId=1937,prevId=438,rewardNextId=444,poiX=632,poiY=522,wowhead=[[https://www.wowhead.com/wotlk/quest=443]],image=[[assets/images/quests/placeholder.png]],desc=[[Before we launch an assault on Fenris Isle, we must determine who is behind the rot hide gnolls.  Our apothecaries believe their origin lies within the strange fluid that flows through their bodies. Go to Fenris Isle, east of the Decrepit Ferry, and collect rot hide ichor from the gnolls you find there.  Bring it to Apothecary Renferrel, stationed outside the Sepulcher.]],logDesc=[[Bring 8 bottles of rot hide ichor to Apothecary Renferrel at the Sepulcher.]]}
DB[444]={id=444,zoneId=130,name=[[Rot Hide Origins]],name_loc=[[El origen de los Putrepellejos]],level=17,minLevel=10,giver=[[Apothecary Renferrel]],giver_loc=[[Boticario Renferrel]],giverType=[[NPC]],giverId=1937,ender=[[Bethor Iceshard]],ender_loc=[[Bethor Duroyelo]],enderType=[[NPC]],enderId=1498,prevId=443,poiX=1766,poiY=67,wowhead=[[https://www.wowhead.com/wotlk/quest=444]],image=[[assets/images/quests/placeholder.png]],desc=[[I have reduced the ichor you brought me and separated it into its base components.  My findings are not conclusive, but I have determined that warlock and necromantic magics were used in the ichor's creation. While I continue to study the ichor, I want you to take a sample to Bethor Iceshard in the Undercity.  Bethor is not an apothecary, but his knowledge of magic may help to unravel the mystery of the rot hides. Go.  You will find Bethor in the Magic Quarter of the Undercity.]],logDesc=[[Bring the Sample Ichor to Bethor Iceshard in the Undercity.]]}
DB[445]={id=445,zoneId=85,name=[[Delivery to Silverpine Forest]],name_loc=[[Entrega a Bosque de Argénteos]],level=10,minLevel=9,giver=[[Apothecary Johaan]],giver_loc=[[Boticario Johaan]],giverType=[[NPC]],giverId=1518,ender=[[Apothecary Renferrel]],ender_loc=[[Boticario Renferrel]],enderType=[[NPC]],enderId=1937,poiX=522,poiY=1652,wowhead=[[https://www.wowhead.com/wotlk/quest=445]],image=[[assets/images/quests/placeholder.png]],desc=[[Time is a luxury that is not afforded to those of us under the employ of Lady Sylvanas.  Surely you know this by now. As a member of the Royal Apothecary Society it is my duty to share my knowledge with my colleagues so that our collective efforts might one day provide The Dark Lady with the New Plague she so badly desires. Take these findings to Apothecary Renferrel who is stationed at The Sepulcher in Silverpine Forest.  Follow the roads to the south from Brill.  From the Undercity go southwest.]],logDesc=[[Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest.]]}
DB[446]={id=446,zoneId=130,name=[[Thule Ravenclaw]],name_loc=[[Thule Corvozarpa]],level=16,minLevel=10,giver=[[Bethor Iceshard]],giver_loc=[[Bethor Duroyelo]],giverType=[[NPC]],giverId=1498,ender=[[Apothecary Renferrel]],ender_loc=[[Boticario Renferrel]],enderType=[[NPC]],enderId=1937,prevId=444,rewardNextId=448,poiX=522,poiY=1652,wowhead=[[https://www.wowhead.com/wotlk/quest=446]],image=[[assets/images/quests/placeholder.png]],desc=[[This Ichor was crafted by an old colleague of mine: Thule Ravenclaw.  He was a young, promising mage before the great war, but when the Lich King rose to power, he betrayed his brethren and allied with the Scourge. I did not realize he still lives, nor that he leads the Rot Hides in their forays against us! I know many of his spells, and can help concoct a potion to counter them.  Take this scroll back to Apothecary Renferrel.  It has the incantations needed for the potion.]],logDesc=[[Bring Bethor's Scroll to Apothecary Renferrel at the Silverpine Sepulcher.]],rewards={{id=3251,qty=1}}}
DB[447]={id=447,zoneId=130,name=[[A Recipe For Death]],name_loc=[[Una fórmula mortal]],level=12,minLevel=9,giver=[[Apothecary Renferrel]],giver_loc=[[Boticario Renferrel]],giverType=[[NPC]],giverId=1937,ender=[[Master Apothecary Faranell]],ender_loc=[[Maestro boticario Faranell]],enderType=[[NPC]],enderId=2055,rewardNextId=450,poiX=1114,poiY=1249,wowhead=[[https://www.wowhead.com/wotlk/quest=447]],image=[[assets/images/quests/placeholder.png]],desc=[[Arthas's numbers are overwhelming. But with a New Plague we could eradicate both the Scourge Army and the Human infestation once and for all. My studies have proven that spider blood combined with a toxin derived from a grizzled bear heart results in a deadly elixir. Collect samples from the spiders in the Skittering Dark to the northwest and from the bears wandering throughout Silverpine Forest. Deliver the reagents to Master Apothecary Faranell of the Royal Apothecary Society in the Undercity.]],logDesc=[[Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity.]],rewards={{id=3448,qty=20}}}
DB[448]={id=448,zoneId=130,name=[[Report to Hadrec]],name_loc=[[Preséntate ante Hadrec]],level=16,minLevel=10,giver=[[Apothecary Renferrel]],giver_loc=[[Boticario Renferrel]],giverType=[[NPC]],giverId=1937,ender=[[High Executor Hadrec]],ender_loc=[[Sumo ejecutor Hadrec]],enderType=[[NPC]],enderId=1952,prevId=446,rewardNextId=442,poiX=522,poiY=1626,wowhead=[[https://www.wowhead.com/wotlk/quest=448]],image=[[assets/images/quests/placeholder.png]],desc=[[Before you launch an assault on Fenris Isle, report to High Executor Hadrec.  He may have additional information or equipment you'll need.]],logDesc=[[Report to High Executor Hadrec at the Sepulcher.]],rewards={{id=2313,qty=1}},choiceRewards={{id=3240,qty=5},{id=2863,qty=5}}}
DB[449]={id=449,zoneId=130,name=[[The Deathstalkers' Report]],name_loc=[[El informe de los Mortacechadores]],level=11,minLevel=10,giver=[[Rane Yorick]],giver_loc=[[Rane Yorick]],giverType=[[NPC]],giverId=1950,ender=[[High Executor Hadrec]],ender_loc=[[Sumo ejecutor Hadrec]],enderType=[[NPC]],enderId=1952,prevId=435,rewardNextId=3221,poiX=522,poiY=1626,wowhead=[[https://www.wowhead.com/wotlk/quest=449]],image=[[assets/images/quests/placeholder.png]],desc=[[Although Quinn's wounds are mending, I want to get our report to High Executor Hadrec as quickly as possible.  It has information that is vital to the Forsaken's occupation of Silverpine.]],logDesc=[[Bring the Deathstalker Report to High Executor Hadrec at the Sepulcher.]]}
DB[450]={id=450,zoneId=130,name=[[A Recipe For Death]],name_loc=[[Una fórmula mortal]],level=15,minLevel=9,giver=[[Master Apothecary Faranell]],giver_loc=[[Maestro boticario Faranell]],giverType=[[NPC]],giverId=2055,ender=[[Apothecary Renferrel]],ender_loc=[[Boticario Renferrel]],enderType=[[NPC]],enderId=1937,prevId=447,rewardNextId=451,poiX=-382,poiY=1645,wowhead=[[https://www.wowhead.com/wotlk/quest=450]],image=[[assets/images/quests/placeholder.png]],desc=[[You can be of further service to the Royal Apothecary Society, $N. When Arugal cast his wretched magic on the forest, he cursed one of our most promising members, Apothecary Berard.  Now a mindless servant of Arugal, Berard is useless to us.  But his findings might prove to be of worth.  He was studying an ancient plague that killed off all the aquatic life in Lake Lordamere ages ago. Retrieve Berard's Journal from his study in the Pyrewood Village Inn and take it to Apothecary Renferrel.]],logDesc=[[Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher.]]}
DB[451]={id=451,zoneId=130,name=[[A Recipe For Death]],name_loc=[[Una fórmula mortal]],level=18,minLevel=9,giver=[[Apothecary Renferrel]],giver_loc=[[Boticario Renferrel]],giverType=[[NPC]],giverId=1937,ender=[[Master Apothecary Faranell]],ender_loc=[[Maestro boticario Faranell]],enderType=[[NPC]],enderId=2055,prevId=450,poiX=597,poiY=397,wowhead=[[https://www.wowhead.com/wotlk/quest=451]],image=[[assets/images/quests/placeholder.png]],desc=[[According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague.  Those beasts dwell on the islands in Lake Lordamere to the east. He also mentions a very rare Hardened Tumor that he discovered on a Vile Fin murloc.  Apparently the tumor is so rare Berard was only able to obtain one. Collect samples of the moss as well as the rare hardened tumor and take them to Master Apothecary Faranell in the Undercity.]],logDesc=[[Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity.]],rewards={{id=2458,qty=1},{id=2459,qty=1}},choiceRewards={{id=3451,qty=1},{id=3582,qty=1}}}
DB[452]={id=452,zoneId=130,name=[[Pyrewood Ambush]],name_loc=[[La emboscada de Aldea Piroleña]],level=15,minLevel=12,giver=[[Deathstalker Faerleia]],giver_loc=[[Mortacechadora Faerleia]],giverType=[[NPC]],giverId=2058,ender=[[Deathstalker Faerleia]],ender_loc=[[Mortacechadora Faerleia]],enderType=[[NPC]],enderId=2058,poiX=-416,poiY=1497,wowhead=[[https://www.wowhead.com/wotlk/quest=452]],image=[[assets/images/quests/placeholder.png]],desc=[[You got here just in the nick of time, $N! The Pyrewood Council will be returning any moment.  Arugal has other matters to tend to in the keep.  He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control.  But I believe that without the guidance of the Pyrewood Council, the sons of Arugal will turn against their master. I cannot handle them all by myself.  I need you to help me.  Together we can lay waste to the Council for Lady Sylvanas.]],logDesc=[[Help Deathstalker Faerleia kill the Pyrewood Council.]],choiceRewards={{id=3450,qty=1},{id=2818,qty=1},{id=3449,qty=1}}}
DB[453]={id=453,zoneId=10,name=[[Finding the Shadowy Figure]],name_loc=[[Encuentra la figura misteriosa]],level=25,minLevel=20,giver=[[Tavernkeep Smitts]],giver_loc=[[Tabernero Smitts]],giverType=[[NPC]],giverId=273,ender=[[Jitters]],ender_loc=[[Alterio]],enderType=[[NPC]],enderId=288,prevId=266,rewardNextId=268,poiX=-10732,poiY=337,wowhead=[[https://www.wowhead.com/wotlk/quest=453]],image=[[assets/images/quests/placeholder.png]],desc=[[Good luck, $N.  I hope you find the chap, and I hope you find him alive. If he's left the safety of Darkshire then he could be prey to the beasts of the wilds.]],logDesc=[[Find the Shadowy Figure.  Your clues: He is not native to Darkshire. He is a nervous, jittery person. He left Darkshire and headed west.]]}
DB[454]={id=454,zoneId=38,name=[[After the Ambush]],name_loc=[[Tras la emboscada]],level=15,minLevel=10,giver=[[Huldar]],giverType=[[NPC]],giverId=2057,ender=[[Miran]],enderType=[[NPC]],enderId=1379,prevId=273,poiX=-5765,poiY=-3434,wowhead=[[https://www.wowhead.com/wotlk/quest=454]],image=[[assets/images/quests/placeholder.png]],desc=[[We'd been hauling the barrels of powder back and forth in trips before this... business. Now we have to split up the work, Miran's taking the barrels and I'm watching over the other ones. I don't feel safe letting Miran haul the rest of the shipment by himself. When he's ready to go, maybe you could escort him on his next trip?]],logDesc=[[Speak with Miran.]]}
DB[455]={id=455,zoneId=11,name=[[The Algaz Gauntlet]],name_loc=[[El asedio de Algaz]],level=21,minLevel=19,giver=[[Mountaineer Rockgar]],giver_loc=[[Montaraz Piedragar]],giverType=[[NPC]],giverId=1342,ender=[[Valstag Ironjaw]],ender_loc=[[Valstag Quijahierro]],enderType=[[NPC]],enderId=2086,poiX=-4314,poiY=-2521,wowhead=[[https://www.wowhead.com/wotlk/quest=455]],image=[[assets/images/quests/placeholder.png]],desc=[[Orcs of the Dragonmaw clan have a haven in the Wetlands.  And now they have expanded into Dun Algaz!  We can't let them keep their foothold here or Loch Modan will be cut off from Menethil Harbor, our port and stronghold in the Wetlands. Break through Dun Algaz to the Wetlands beyond, and kill some orcs for good measure!  Report to Valstag Ironjaw in Menethil Harbor. Menethil is through Dun Algaz, then north along the road, then west at the fork. We're counting on you, $N.  Do not fail.]],logDesc=[[Traverse Dun Algaz. Kill 8 Dragonmaw Scouts and 6 Dragonmaw Grunts. Report to Valstag Ironjaw in Menethil Harbor.]]}
DB[456]={id=456,zoneId=188,name=[[The Balance of Nature]],name_loc=[[El equilibrio de la naturaleza]],level=2,minLevel=1,giver=[[Conservator Ilthalaine]],giver_loc=[[Conservador Ilthalaine]],giverType=[[NPC]],giverId=2079,ender=[[Conservator Ilthalaine]],ender_loc=[[Conservador Ilthalaine]],enderType=[[NPC]],enderId=2079,nextId=457,poiX=10447,poiY=535,wowhead=[[https://www.wowhead.com/wotlk/quest=456]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, $N.  I am Conservator Ilthalaine.  My purpose in Shadowglen is to ensure that the balance of nature is maintained. The spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered. Unfortunately, the nightsaber and thistle boar populations grew too large.  Shadowglen can only produce so much food for the beasts.  Journey forth, young $c, and thin the boar and saber populations so that nature's harmony will be preserved.]],logDesc=[[Kill 4 Young Nightsabers and 4 Young Thistle Boars and return to Conservator Ilthalaine.]],choiceRewards={{id=5394,qty=1},{id=11187,qty=1}}}
DB[457]={id=457,zoneId=188,name=[[The Balance of Nature]],name_loc=[[El equilibrio de la naturaleza]],level=3,minLevel=1,giver=[[Conservator Ilthalaine]],giver_loc=[[Conservador Ilthalaine]],giverType=[[NPC]],giverId=2079,ender=[[Conservator Ilthalaine]],ender_loc=[[Conservador Ilthalaine]],enderType=[[NPC]],enderId=2079,prevId=456,poiX=10515,poiY=585,wowhead=[[https://www.wowhead.com/wotlk/quest=457]],image=[[assets/images/quests/placeholder.png]],desc=[[Thinning the younger population of creatures here in Shadowglen was a good start, $N, but there is still work to be done. The resources of the forest will be depleted too quickly if the problem is not addressed.  Killing nature's beasts is a necessary evil for the good of all who share the land.  Venture into the forest and slay mangy nightsabers and thistle boars in the name of balance.]],logDesc=[[Conservator Ilthalaine needs you to kill 5 Mangy Nightsabers and 5 Thistle Boars.]],choiceRewards={{id=5405,qty=1},{id=6058,qty=1}}}
DB[458]={id=458,zoneId=188,name=[[The Woodland Protector]],name_loc=[[La protectora de los bosques]],level=1,minLevel=1,giver=[[Melithar Staghelm]],giver_loc=[[Melithar Corzocelada]],giverType=[[NPC]],giverId=2077,ender=[[Tarindrella]],enderType=[[NPC]],enderId=1992,rewardNextId=459,poiX=10298,poiY=875,wowhead=[[https://www.wowhead.com/wotlk/quest=458]],image=[[assets/images/quests/placeholder.png]],desc=[[Thank goodness you are here, $c. Strange news has traveled to me through the whisperings of the forest spirits. The mysterious woodland protector, Tarindrella, has returned to Shadowglen. The dryad's presence has not been felt in the forests of Kalimdor in years. Something is surely amiss if she has journeyed back to this land. Seek out Tarindrella and see what business she tends to in our grove. One of the Sentinels reported seeing her to the southwest of Aldrassil.]],logDesc=[[Seek out the dryad known as Tarindrella.]]}
DB[459]={id=459,zoneId=188,name=[[The Woodland Protector]],name_loc=[[La protectora de los bosques]],level=3,minLevel=1,giver=[[Tarindrella]],giverType=[[NPC]],giverId=1992,ender=[[Tarindrella]],enderType=[[NPC]],enderId=1992,prevId=458,poiX=10266,poiY=943,wowhead=[[https://www.wowhead.com/wotlk/quest=459]],image=[[assets/images/quests/placeholder.png]],desc=[[Something evil is brewing in the forests of Teldrassil.  Look long the hills to where the peaceful furbolgs used to dwell.  They have deserted their homes and are amassing under the name of the Gnarlpine tribe. Only the corruption of wicked Fel Moss could cause such a transformation.  The grells and grellkin have infested the area and are threatening the residents of Shadowglen.   Engage these grells and grellkin, $N, and see if they are indeed caught under the enchantment of the wicked Fel Moss.]],logDesc=[[Collect 8 Fel Moss and bring them to Tarindrella.]],rewards={{id=961,qty=3}},choiceRewards={{id=5398,qty=1},{id=5399,qty=1},{id=11190,qty=1}}}
DB[460]={id=460,zoneId=130,name=[[Resting in Pieces]],name_loc=[[Descansar en piezas]],level=17,minLevel=12,giverType=[[NPC]],ender=[[Shallow Grave]],enderType=[[GO]],enderId=1599,rewardNextId=461,poiX=632,poiY=522,wowhead=[[https://www.wowhead.com/wotlk/quest=460]],image=[[assets/images/quests/placeholder.png]],desc=[[You don't look like a rot hide.  Good.  I had lost hope... My name is Alaric, and I was once Thule's head servant and bodyguard.  He used his magic to "protect" me from the Plague of Undeath, but instead his spell gave me an unlife from which I cannot escape.  And after creating the cursed rot hide gnolls, Thule beheaded me... and gave my head to the gnolls as a plaything! Please, take me to my body.  I believe the gnolls buried it here in Fenris Keep, near the stable, in an unmarked grave.]],logDesc=[[Bring Alaric's Head to his grave.]]}
DB[461]={id=461,zoneId=130,name=[[The Hidden Niche]],name_loc=[[El nicho oculto]],level=18,minLevel=12,giver=[[Shallow Grave]],giverType=[[GO]],giverId=1599,ender=[[Dusty Shelf]],ender_loc=[[Estantería polvorienta]],enderType=[[GO]],enderId=112888,prevId=460,rewardNextId=491,poiX=972,poiY=705,wowhead=[[https://www.wowhead.com/wotlk/quest=461]],image=[[assets/images/quests/placeholder.png]],desc=[[I know of a hidden niche within the keep that holds an item dear to Thule, and his old colleagues.  It also holds something you might find useful.  Take me there! The alcove is in the southwestern tower of the keep, behind a dusty shelf. Take my body, but leave my boots.  They never fit me anyway...]],logDesc=[[Take Alaric to the hidden alcove.]]}
DB[463]={id=463,zoneId=11,name=[[The Greenwarden]],name_loc=[[El Guardaverde]],level=21,minLevel=20,giver=[[First Mate Fitzsimmons]],giver_loc=[[Contramaestre Fistimos]],giverType=[[NPC]],giverId=1239,ender=[[Rethiel the Greenwarden]],ender_loc=[[Rethiel el Guardaverde]],enderType=[[NPC]],enderId=1244,rewardNextId=276,poiX=-3263,poiY=-2719,wowhead=[[https://www.wowhead.com/wotlk/quest=463]],image=[[assets/images/quests/placeholder.png]],desc=[[You've heard of the Greenwarden?  You're not looking for him, are you?  Well I say you're crazy if you are, but who am I to keep a fool from $ghis:her; death? If you are seeking that beast, then I hear he is in the marsh, east of the road where it forks to Dun Modr.  He's lurking there among the crocs...and worse! And leave your money here.  You won't need it where you're going...and you don't want to chip ol' Greenie's tooth on your gold when he bites you in half, do you?]],logDesc=[[Find the Greenwarden.]]}
DB[464]={id=464,zoneId=11,name=[[War Banners]],name_loc=[[Estandartes de batalla]],level=26,minLevel=23,giver=[[Captain Stoutfist]],giver_loc=[[Capitán Puñorrecio]],giverType=[[NPC]],giverId=2104,ender=[[Captain Stoutfist]],ender_loc=[[Capitán Puñorrecio]],enderType=[[NPC]],enderId=2104,prevId=473,rewardNextId=465,poiX=-3415,poiY=-2550,wowhead=[[https://www.wowhead.com/wotlk/quest=464]],image=[[assets/images/quests/placeholder.png]],desc=[[The Dragonmaw orc clan was all but destroyed by the end of the Second War, after they lost control of their red dragon pets.  The dragons were not very happy with their old masters, and fiercely hunted the Dragonmaws.  What few remained fled from Grim Batol and into the Mountains east of Whelgar's Excavation. Now they've gained strength, and have an encampment northeast of Menethil. We want you to attack that encampment.  Gather and bring me their war banners as proof.]],logDesc=[[Bring 8 Dragonmaw War Banners to Captain Stoutfist.]]}
DB[465]={id=465,zoneId=11,name=[[Nek'rosh's Gambit]],name_loc=[[La estrategia de Nek'rosh]],level=26,minLevel=23,giver=[[Captain Stoutfist]],giver_loc=[[Capitán Puñorrecio]],giverType=[[NPC]],giverId=2104,ender=[[Dragonmaw Catapult]],ender_loc=[[Catapulta Faucedraco]],enderType=[[GO]],enderId=1609,prevId=464,rewardNextId=474,poiX=-3444,poiY=-2352,wowhead=[[https://www.wowhead.com/wotlk/quest=465]],image=[[assets/images/quests/placeholder.png]],desc=[[While you were fighting the Dragonmaws, we discovered more of their plans. Nek'rosh has built catapults and aims to lay siege to Menethil!  And with the fighting in Dun Algaz, we're effectively blocked from reinforcements! You need to take out those catapults.  They're in the Dragonmaw encampment. Here, take this tinder.  Fight your way to the catapults and light them with the tinder. And after you've done that, find and kill Nek'rosh.  We need to cut this Dragonmaw beast down...at its neck.]],logDesc=[[Destroy the Dragonmaw catapults.]]}
DB[466]={id=466,zoneId=1,name=[[Search for Incendicite]],name_loc=[[Búsqueda de incendicita]],level=22,minLevel=20,giver=[[Pilot Stonegear]],giver_loc=[[Piloto Roscapiedra]],giverType=[[NPC]],giverId=1377,ender=[[Pilot Stonegear]],ender_loc=[[Piloto Roscapiedra]],enderType=[[NPC]],enderId=1377,prevId=467,poiX=-5473,poiY=-642,wowhead=[[https://www.wowhead.com/wotlk/quest=466]],image=[[assets/images/quests/placeholder.png]],desc=[[I heard that a rare ore, incendicite, was found in the Wetlands, in a cave northwest of Algaz Gate.  Incendicite is volatile stuff and hard to use without blowing yourself up, but I'm sure if it's smelted the right way it could make cannon shells that pack a mighty punch! Get me incendicite ore and I'll find someone brave enough to experiment with it. Oh, and to extract that ore from a vein you'll need skill in mining.  If you don't have it, then ... bring a friend who does to that cave!]],logDesc=[[Bring 6 loads of Incendicite Ore to Pilot Stonegear in Dun Morogh.]],rewards={{id=3565,qty=1}}}
DB[467]={id=467,zoneId=1,name=[[Stonegear's Search]],name_loc=[[La búsqueda de los Roscapiedra]],level=23,minLevel=20,giver=[[Mountaineer Kadrell]],giver_loc=[[Montaraz Kadrell]],giverType=[[NPC]],giverId=1340,ender=[[Pilot Stonegear]],ender_loc=[[Piloto Roscapiedra]],enderType=[[NPC]],enderId=1377,rewardNextId=466,poiX=-5473,poiY=-642,wowhead=[[https://www.wowhead.com/wotlk/quest=467]],image=[[assets/images/quests/placeholder.png]],desc=[[Pilot Stonegear loves his siege engine, as every pilot should!  And he's always eager to find new ways to improve his tank's firepower! He heard rumors of a rare ore and is looking for someone to hunt it down for him.  If your boots are starting to itch, then find Stonegear at Steelgrill's Depot in Dun Morogh and see what he wants.]],logDesc=[[Speak with Pilot Stonegear.]]}
DB[468]={id=468,zoneId=11,name=[[Report to Mountaineer Rockgar]],name_loc=[[Preséntate ante el montaraz Piedragar]],level=21,minLevel=19,giver=[[Mountaineer Kadrell]],giver_loc=[[Montaraz Kadrell]],giverType=[[NPC]],giverId=1340,ender=[[Mountaineer Rockgar]],ender_loc=[[Montaraz Piedragar]],enderType=[[NPC]],enderId=1342,rewardNextId=455,poiX=-4679,poiY=-2695,wowhead=[[https://www.wowhead.com/wotlk/quest=468]],image=[[assets/images/quests/placeholder.png]],desc=[[Mountaineer Rockgar is looking for volunteers for a mission through Dun Algaz and into the Wetlands.   If you want to get your boots wet in that soggy county to the north, then speak with Rockgar at Dun Algaz.  Dun Algaz is north up the road, beyond the guard tower.]],logDesc=[[Speak with Mountaineer Rockgar.]]}
DB[469]={id=469,zoneId=11,name=[[Daily Delivery]],name_loc=[[Entrega cotidiana]],level=21,minLevel=18,giver=[[Einar Stonegrip]],giver_loc=[[Eina Pillapedra]],giverType=[[NPC]],giverId=2093,ender=[[James Halloran]],enderType=[[NPC]],enderId=2094,poiX=-3684,poiY=-742,wowhead=[[https://www.wowhead.com/wotlk/quest=469]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, traveler! Don't suppose you might be heading in the direction of Menethil, would you? If you're not, I'd suggest you stop there, it's a good place to purchase goods and even have a pint and relax. Now, if it just so happens that you're heading in that direction, I don't suppose you'd mind taking this bundle of crocolisk skins to James Halloran, the tanner? I'd do it myself, but my wife's been in quite a mood lately, and I'd like to put off facing her as long as possible.]],logDesc=[[Deliver the Bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor.]]}
DB[470]={id=470,zoneId=11,name=[[Digging Through the Ooze]],name_loc=[[Abriéndose paso entre los mocos]],level=24,minLevel=19,giver=[[Sida]],giver_loc=[[Shida]],giverType=[[NPC]],giverId=2111,ender=[[Sida]],ender_loc=[[Shida]],enderType=[[NPC]],enderId=2111,poiX=-2821,poiY=-2382,wowhead=[[https://www.wowhead.com/wotlk/quest=470]],image=[[assets/images/quests/placeholder.png]],desc=[[On my weekly visit to Ironbeard's Tomb I was attacked by dreadful, dripping oozes! Naturally, I panicked. I threw my bag at one, but it didn't do anything! The ooze just sucked it right up... Luckily, it did give me enough time to get away. The bad news is that I really need to get the contents of my bag! I don't know which ooze I threw my bag at; they all looked the same! Ironbeard's Tomb is northeast of here, near Dun Modr. Thank you so much!]],logDesc=[[One of the oozes at Ironbeard's Tomb has Sida's bag, retrieve it and bring it back to her in Menethil Harbor.]],rewards={{id=3352,qty=1}}}
DB[471]={id=471,zoneId=11,name=[[Apprentice's Duties]],name_loc=[[Deberes de aprendiz]],level=26,minLevel=18,giver=[[James Halloran]],giverType=[[NPC]],giverId=2094,ender=[[James Halloran]],enderType=[[NPC]],enderId=2094,prevId=484,poiX=-3783,poiY=-1217,wowhead=[[https://www.wowhead.com/wotlk/quest=471]],image=[[assets/images/quests/placeholder.png]],desc=[[I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him... Let's just say it wasn't a pretty sight. Midwife says he might pull through, but in the meantime I still need my skins! ...If you'd like to kill a few more of the brutes, I wouldn't be opposed, after what they did. You'll find the crocs north up the coast, beyond the murloc hovels.]],logDesc=[[Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.]],rewards={{id=3681,qty=1}},choiceRewards={{id=2545,qty=1},{id=3561,qty=1}}}
DB[472]={id=472,zoneId=11,name=[[Fall of Dun Modr]],name_loc=[[La caída de Dun Modr]],level=25,minLevel=25,giver=[[Harlo Barnaby]],giverType=[[NPC]],giverId=2097,ender=[[Longbraid the Grim]],ender_loc=[[Largatrenza el Nefasto]],enderType=[[NPC]],enderId=1071,poiX=-2651,poiY=-2449,wowhead=[[https://www.wowhead.com/wotlk/quest=472]],image=[[assets/images/quests/placeholder.png]],desc=[[Dun Modr has fallen to the Dark Iron Dwarves! My wounds are grave, $c.  Most of the regiment was killed!  The Dark Iron thugs attacked us before we could regroup from the Thandol Span ambush. Our leader, Longbraid, sounded the retreat horn.  As we left the town I was hit by a stray axe in the back.  All went black. I awoke here in Menethil but I fear for my fellow soldiers.  Hope still burns within me.  Perhaps Longbraid is still alive!  See if you can find him near Dun Modr, $r!]],logDesc=[[Search for Longbraid near the town of Dun Modr.]]}
DB[473]={id=473,zoneId=11,name=[[Report to Captain Stoutfist]],name_loc=[[Preséntate ante el capitán Puñorrecio]],level=26,minLevel=23,giver=[[Valstag Ironjaw]],giver_loc=[[Valstag Quijahierro]],giverType=[[NPC]],giverId=2086,ender=[[Captain Stoutfist]],ender_loc=[[Capitán Puñorrecio]],enderType=[[NPC]],enderId=2104,rewardNextId=464,poiX=-3732,poiY=-797,wowhead=[[https://www.wowhead.com/wotlk/quest=473]],image=[[assets/images/quests/placeholder.png]],desc=[[$N.  The Dragonmaw orc clan is showing its strength in more than just Algaz.  Captain Stoutfist has asked to speak with those willing to offer aid against these orcs.  He is inside the keep, in the war room.]],logDesc=[[Speak with Captain Stoutfist.]]}
DB[474]={id=474,zoneId=11,name=[[Defeat Nek'rosh]],name_loc=[[Derrota a Nek'rosh]],level=26,minLevel=23,giver=[[Dragonmaw Catapult]],giver_loc=[[Catapulta Faucedraco]],giverType=[[GO]],giverId=1609,ender=[[Captain Stoutfist]],ender_loc=[[Capitán Puñorrecio]],enderType=[[NPC]],enderId=2104,prevId=465,poiX=-3654,poiY=-2601,wowhead=[[https://www.wowhead.com/wotlk/quest=474]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that the catapults have been burned, find and kill Chieftain Nek'rosh.]],logDesc=[[Kill Chieftain Nek'rosh Bring Nek'rosh's Head to Captain Stoutfist.]],choiceRewards={{id=3209,qty=1},{id=6194,qty=1}}}
DB[475]={id=475,zoneId=141,name=[[A Troubling Breeze]],name_loc=[[Una brisa problemática]],level=6,minLevel=4,giver=[[Athridas Bearmantle]],giver_loc=[[Athridas Manto de Oso]],giverType=[[NPC]],giverId=2078,ender=[[Gaerolas Talvethren]],enderType=[[NPC]],enderId=2107,rewardNextId=476,poiX=9845,poiY=441,wowhead=[[https://www.wowhead.com/wotlk/quest=475]],image=[[assets/images/quests/placeholder.png]],desc=[[A troubling breeze blows through the forest. Gaerolas Talvethren serves as Great Warden to the hibernating Druids of the Talon in the Ban'ethil Barrow Den.  His duty as the chosen protector of the Sleeping is to ensure their safety so that their pact with Ysera remains fulfilled. But word from Gaerolas is now delayed and I grow nervous.  Travel east to Starbreeze Village and bring back a report from Gaerolas so that I can put my worries to rest, knowing my dreaming brethren slumber safely.]],logDesc=[[Seek out Gaerolas Talvethren in Starbreeze Village. ]]}
DB[476]={id=476,zoneId=141,name=[[Gnarlpine Corruption]],name_loc=[[Corrupción en Tuercepinos]],level=6,minLevel=4,giver=[[Gaerolas Talvethren]],giverType=[[NPC]],giverId=2107,ender=[[Athridas Bearmantle]],ender_loc=[[Athridas Manto de Oso]],enderType=[[NPC]],enderId=2078,prevId=475,rewardNextId=483,poiX=9888,poiY=966,wowhead=[[https://www.wowhead.com/wotlk/quest=476]],image=[[assets/images/quests/placeholder.png]],desc=[[The Gnarlpine tribe has been corrupted! The once peaceful furbolgs have turned against the protectors of the forest.  They ambushed me as I left for the Ban'ethil Barrow Den and proceeded to pillage Starbreeze Village.  Ursal the Mauler, their chieftain, is using the evil powers of the Fel Moss to drive them mad. I am too wounded to return to Athridas to bring him this grave news.  The task is left to you, young $c.  We can only hope that the deranged Gnarlpines have not made it to Ban'ethil yet!]],logDesc=[[Return to Athridas Bearmantle in Dolanaar.]]}
DB[477]={id=477,zoneId=130,name=[[Border Crossings]],name_loc=[[Pasa la frontera]],level=14,minLevel=10,giver=[[Shadow Priest Allister]],giver_loc=[[Sacerdote de las Sombras Allister]],giverType=[[NPC]],giverId=2121,ender=[[Dalaran Crate]],ender_loc=[[Cajón de Dalaran]],enderType=[[GO]],enderId=1627,rewardNextId=478,poiX=-22,poiY=1355,wowhead=[[https://www.wowhead.com/wotlk/quest=477]],image=[[assets/images/quests/placeholder.png]],desc=[[As you may know, the town of Ambermill remains a source of human opposition, mainly through the support they receive from the wizards of Dalaran. I don't know what their plan is, but for them to show interest in a backwater village like Ambermill indicates that it must have some greater importance. They've been shipping crates by the wagon from Hillsbrad. Many of those supplies end up at a small camp north of Pyrewood Village. Retrieve the contents of a crate and return them to me.]],logDesc=[[Retrieve the contents of one of the Dalaran wizards' crates. You will find Pyrewood Village to the south.]]}
DB[478]={id=478,zoneId=130,name=[[Maps and Runes]],name_loc=[[Mapas y runas]],level=14,minLevel=10,giver=[[Dalaran Crate]],giver_loc=[[Cajón de Dalaran]],giverType=[[GO]],giverId=1627,ender=[[Shadow Priest Allister]],ender_loc=[[Sacerdote de las Sombras Allister]],enderType=[[NPC]],enderId=2121,prevId=477,rewardNextId=481,poiX=521,poiY=1603,wowhead=[[https://www.wowhead.com/wotlk/quest=478]],image=[[assets/images/quests/placeholder.png]],desc=[[<You quickly remove the pendant from the crate and replace the lid.>]],logDesc=[[Bring the strange pendant to Shadow Priest Allister at the Sepulcher.]]}
DB[479]={id=479,zoneId=130,name=[[Ambermill Investigations]],name_loc=[[Las investigaciones de Molino Ámbar]],level=16,minLevel=10,giver=[[Shadow Priest Allister]],giver_loc=[[Sacerdote de las Sombras Allister]],giverType=[[NPC]],giverId=2121,ender=[[Shadow Priest Allister]],ender_loc=[[Sacerdote de las Sombras Allister]],enderType=[[NPC]],enderId=2121,prevId=482,rewardNextId=480,poiX=-176,poiY=769,wowhead=[[https://www.wowhead.com/wotlk/quest=479]],image=[[assets/images/quests/placeholder.png]],desc=[[Dalar is attempting to locate the source of the wizards' spellcasting. For now, we'll have to slow their progress in any way we can... The conjurers, mages and protectors are no doubt carrying the pendants. Remove and retrieve them. Take the main road south and the eastern fork into Ambermill.]],logDesc=[[Obtain 8 Dalaran Pendants for Shadow Priest Allister at the Sepulcher.]]}
DB[480]={id=480,zoneId=130,name=[[The Weaver]],name_loc=[[El Tejedor]],level=22,minLevel=10,giver=[[Shadow Priest Allister]],giver_loc=[[Sacerdote de las Sombras Allister]],giverType=[[NPC]],giverId=2121,ender=[[Shadow Priest Allister]],ender_loc=[[Sacerdote de las Sombras Allister]],enderType=[[NPC]],enderId=2121,prevId=479,poiX=-133,poiY=787,wowhead=[[https://www.wowhead.com/wotlk/quest=480]],image=[[assets/images/quests/placeholder.png]],desc=[[An archmage of great power is overseeing the reactivation of the ley energy node. With the progress they have made, our only hope of stopping them is by killing him. It will be difficult, he is no doubt protected by many other mages and warders. You must go, and you must dispatch him quickly. When he is dead, retrieve his staff for me. Go now.]],logDesc=[[Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher.]],choiceRewards={{id=3452,qty=1},{id=3585,qty=1}}}
DB[481]={id=481,zoneId=130,name=[[Dalar's Analysis]],name_loc=[[El análisis de Dalar]],level=14,minLevel=10,giver=[[Shadow Priest Allister]],giver_loc=[[Sacerdote de las Sombras Allister]],giverType=[[NPC]],giverId=2121,ender=[[Dalar Dawnweaver]],ender_loc=[[Dalar Tejealba]],enderType=[[NPC]],enderId=1938,prevId=478,rewardNextId=482,poiX=553,poiY=1593,wowhead=[[https://www.wowhead.com/wotlk/quest=481]],image=[[assets/images/quests/placeholder.png]],desc=[[Take the pendant to Dalar Dawnweaver, perhaps he can shed some light on the wizards' plans.]],logDesc=[[Take the rune-inscribed pendant to Dalar Dawnweaver at the Sepulcher.]]}
DB[482]={id=482,zoneId=130,name=[[Dalaran's Intentions]],name_loc=[[Las intenciones de los Dalaran]],level=14,minLevel=10,giver=[[Dalar Dawnweaver]],giver_loc=[[Dalar Tejealba]],giverType=[[NPC]],giverId=1938,ender=[[Shadow Priest Allister]],ender_loc=[[Sacerdote de las Sombras Allister]],enderType=[[NPC]],enderId=2121,prevId=481,rewardNextId=479,poiX=521,poiY=1603,wowhead=[[https://www.wowhead.com/wotlk/quest=482]],image=[[assets/images/quests/placeholder.png]],desc=[[Of course! How could I have forgotten? Ambermill was one of the sites earmarked by the Kirin Tor, noted because it houses a dormant ley energy node. The wizards must be planning to reactivate the node and use its energies for some greater purpose. We cannot allow this to happen... It will take a great amount of power to activate the area's ley energies, we can stall them by taking the pendants away from the wizards. Relay this information to Allister, he will decide a course of action.]],logDesc=[[Speak with Shadow Priest Allister at the Sepulcher.]]}
DB[483]={id=483,zoneId=141,name=[[The Relics of Wakening]],name_loc=[[Las Reliquias del Despertar]],level=9,minLevel=4,giver=[[Athridas Bearmantle]],giver_loc=[[Athridas Manto de Oso]],giverType=[[NPC]],giverId=2078,ender=[[Athridas Bearmantle]],ender_loc=[[Athridas Manto de Oso]],enderType=[[NPC]],enderId=2078,prevId=476,rewardNextId=486,poiX=9882,poiY=1490,wowhead=[[https://www.wowhead.com/wotlk/quest=483]],image=[[assets/images/quests/placeholder.png]],desc=[[Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help. The delicate hibernation ritual cannot be broken without the Relics of Wakening. Journey to the Den and retrieve the Raven Claw Talisman, Black Feather Quill, Sapphire of Sky, and Rune of Nesting. The druids store them in sacred chests.  Return them to me and I will prepare the awakening ritual.]],logDesc=[[Retrieve the Relics of Wakening and bring them to Athridas Bearmantle in Dolanaar.]],choiceRewards={{id=9599,qty=1},{id=9603,qty=1}}}
DB[484]={id=484,zoneId=11,name=[[Young Crocolisk Skins]],name_loc=[[Piel de crocolisco joven]],level=22,minLevel=18,giver=[[James Halloran]],giverType=[[NPC]],giverId=2094,ender=[[James Halloran]],enderType=[[NPC]],enderId=2094,rewardNextId=471,poiX=-3378,poiY=-1279,wowhead=[[https://www.wowhead.com/wotlk/quest=484]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm James Halloran, the tanner. My cured crocolisk skins are sought after all over, shipments leaving by boat to ports around the world. Met Einar? He's one of the hunters that brings crocolisk skins in for me. I'm a bit short on the softer skins that come off crocolisk young. Being that I'm running low, I'll pay you top coin for a stack of the skins. You can find the young crocs in the marshes right outside of town.]],logDesc=[[Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor.]]}
DB[485]={id=485,zoneId=47,name=[[Find OOX-09/HL!]],name_loc=[[¡Encuentra a OOX-09/TI!]],level=48,minLevel=43,giverType=[[NPC]],ender=[[Homing Robot OOX-09/HL]],ender_loc=[[Robot mensajero OOX-09/TI]],enderType=[[NPC]],enderId=7806,rewardNextId=836,poiX=500,poiY=-3475,wowhead=[[https://www.wowhead.com/wotlk/quest=485]],image=[[assets/images/quests/placeholder.png]],desc=[[You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life. "My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!" "I now have computed the coordinates of the robot for you; it crashed at the head of the river near Skulk Rock!"]],logDesc=[[Take the distress beacon to Oglethorpe's homing robot at the head of the river in the Hinterlands, near Skulk Rock.]]}
DB[486]={id=486,zoneId=141,name=[[Ursal the Mauler]],name_loc=[[Ursal el Violento]],level=12,minLevel=4,giver=[[Athridas Bearmantle]],giver_loc=[[Athridas Manto de Oso]],giverType=[[NPC]],giverId=2078,ender=[[Athridas Bearmantle]],ender_loc=[[Athridas Manto de Oso]],enderType=[[NPC]],enderId=2078,prevId=483,poiX=9100,poiY=1839,wowhead=[[https://www.wowhead.com/wotlk/quest=486]],image=[[assets/images/quests/placeholder.png]],desc=[[Now the time has come to save the Druids of the Talon. If we fail now, $N, they will be forever lost in sleep. I shall prepare the Relics of Wakening and perform the ritual. For my work to take effect, the cursed beast responsible for this horrible situation must be slain.  Only then will the ritual be complete. It was Ursal the Mauler who meddled with our brethren's calling and it is Ursal the Mauler who must now pay so they can be freed.  Travel to Gnarlpine Hold in the southwest and slay him.]],logDesc=[[Kill Ursal the Mauler and return to Athridas Bearmantle in Dolanaar.]],choiceRewards={{id=5459,qty=1},{id=5587,qty=1}}}
DB[487]={id=487,zoneId=141,name=[[The Road to Darnassus]],name_loc=[[El camino a Darnassus]],level=8,minLevel=5,giver=[[Moon Priestess Amara]],giver_loc=[[Sacerdotisa Lunar Amara]],giverType=[[NPC]],giverId=2151,ender=[[Moon Priestess Amara]],ender_loc=[[Sacerdotisa Lunar Amara]],enderType=[[NPC]],enderId=2151,poiX=9986,poiY=1350,wowhead=[[https://www.wowhead.com/wotlk/quest=487]],image=[[assets/images/quests/placeholder.png]],desc=[[The road to Darnassus must be kept safe.  Travelers heading from Dolanaar to Darnassus have been reporting ruthless attacks by corrupted furbolgs from the Gnarlpine tribe. Important news and commerce travels to and from Darnassus by way of this road daily.  We cannot afford to have a rogue band of heathens terrorizing people. Take up arms in the name of the sacred forest, $c.  Their den lies somewhere below this vantage point.  Slay 6 of these Gnarlpine ambushers and report back to me.]],logDesc=[[Slay 6 Gnarlpine Ambushers and return to Sentinel Amara Nightwalker outside of Dolanaar.]]}
DB[488]={id=488,zoneId=141,name=[[Zenn's Bidding]],name_loc=[[Las apuestas de Zenn]],level=5,minLevel=4,giver=[[Zenn Foulhoof]],giver_loc=[[Zenn Nauseapezuña]],giverType=[[NPC]],giverId=2150,ender=[[Zenn Foulhoof]],ender_loc=[[Zenn Nauseapezuña]],enderType=[[NPC]],enderId=2150,poiX=9449,poiY=582,wowhead=[[https://www.wowhead.com/wotlk/quest=488]],image=[[assets/images/quests/placeholder.png]],desc=[[Eager for work, I see.  Lucky for you a day never goes by that I don't wish I had a fledgling $c to perform my bidding. You see, $N, I can make you very happy and provide you with things you never dreamed of having.  But in order for that to happen you must bring me certain items. My business in the forest often requires certain. . .reagents.  Fetch for me 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk. Let's keep this our little secret, $r.]],logDesc=[[Bring Zenn Foulhoof outside of Dolanaar 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.]],rewards={{id=5457,qty=5}}}
DB[489]={id=489,zoneId=141,name=[[Seek Redemption!]],name_loc=[[¡Búsqueda de redención!]],level=7,minLevel=4,giver=[[Sentinel Kyra Starsong]],giver_loc=[[Centinela Kyra Cantoestelar]],giverType=[[NPC]],giverId=2081,ender=[[Zenn Foulhoof]],ender_loc=[[Zenn Nauseapezuña]],enderType=[[NPC]],enderId=2150,prevId=488,poiX=9718,poiY=750,wowhead=[[https://www.wowhead.com/wotlk/quest=489]],image=[[assets/images/quests/placeholder.png]],desc=[[The Council of the Forest has news that you aided Zenn Foulhoof. The satyr is an enemy of the forest. As a $r, you should know better than to defile the forest by killing Nature's creatures. You must redeem yourself in the eyes of the Council if you wish to remain a friend of Teldrassil. Teach Foulhoof a lesson and you shall be redeemed. Fel Cones are corrupted seeds that fall from the trees. They billow with green smoke. Give some to Foulhoof. He'll think you have brought him a harmless snack.]],logDesc=[[Collect 3 Fel Cones and give them to Zenn Foulhoof outside of Dolanaar.]]}
DB[489]={id=489,zoneId=141,name=[[Seek Redemption!]],name_loc=[[¡Búsqueda de redención!]],level=7,minLevel=4,giver=[[Syral Bladeleaf]],giver_loc=[[Centinela Kyra Cantoestelar]],giverType=[[NPC]],giverId=2083,ender=[[Zenn Foulhoof]],ender_loc=[[Zenn Nauseapezuña]],enderType=[[NPC]],enderId=2150,prevId=488,poiX=9718,poiY=750,wowhead=[[https://www.wowhead.com/wotlk/quest=489]],image=[[assets/images/quests/placeholder.png]],desc=[[The Council of the Forest has news that you aided Zenn Foulhoof. The satyr is an enemy of the forest. As a $r, you should know better than to defile the forest by killing Nature's creatures. You must redeem yourself in the eyes of the Council if you wish to remain a friend of Teldrassil. Teach Foulhoof a lesson and you shall be redeemed. Fel Cones are corrupted seeds that fall from the trees. They billow with green smoke. Give some to Foulhoof. He'll think you have brought him a harmless snack.]],logDesc=[[Collect 3 Fel Cones and give them to Zenn Foulhoof outside of Dolanaar.]]}
DB[489]={id=489,zoneId=141,name=[[Seek Redemption!]],name_loc=[[¡Búsqueda de redención!]],level=7,minLevel=4,giver=[[Moon Priestess Amara]],giver_loc=[[Centinela Kyra Cantoestelar]],giverType=[[NPC]],giverId=2151,ender=[[Zenn Foulhoof]],ender_loc=[[Zenn Nauseapezuña]],enderType=[[NPC]],enderId=2150,prevId=488,poiX=9718,poiY=750,wowhead=[[https://www.wowhead.com/wotlk/quest=489]],image=[[assets/images/quests/placeholder.png]],desc=[[The Council of the Forest has news that you aided Zenn Foulhoof. The satyr is an enemy of the forest. As a $r, you should know better than to defile the forest by killing Nature's creatures. You must redeem yourself in the eyes of the Council if you wish to remain a friend of Teldrassil. Teach Foulhoof a lesson and you shall be redeemed. Fel Cones are corrupted seeds that fall from the trees. They billow with green smoke. Give some to Foulhoof. He'll think you have brought him a harmless snack.]],logDesc=[[Collect 3 Fel Cones and give them to Zenn Foulhoof outside of Dolanaar.]]}
DB[489]={id=489,zoneId=141,name=[[Seek Redemption!]],name_loc=[[¡Búsqueda de redención!]],level=7,minLevel=4,giver=[[Sentinel Shayla Nightbreeze]],giver_loc=[[Centinela Kyra Cantoestelar]],giverType=[[NPC]],giverId=2155,ender=[[Zenn Foulhoof]],ender_loc=[[Zenn Nauseapezuña]],enderType=[[NPC]],enderId=2150,prevId=488,poiX=9718,poiY=750,wowhead=[[https://www.wowhead.com/wotlk/quest=489]],image=[[assets/images/quests/placeholder.png]],desc=[[The Council of the Forest has news that you aided Zenn Foulhoof. The satyr is an enemy of the forest. As a $r, you should know better than to defile the forest by killing Nature's creatures. You must redeem yourself in the eyes of the Council if you wish to remain a friend of Teldrassil. Teach Foulhoof a lesson and you shall be redeemed. Fel Cones are corrupted seeds that fall from the trees. They billow with green smoke. Give some to Foulhoof. He'll think you have brought him a harmless snack.]],logDesc=[[Collect 3 Fel Cones and give them to Zenn Foulhoof outside of Dolanaar.]]}
DB[491]={id=491,zoneId=130,name=[[Wand to Bethor]],name_loc=[[Una varita para Bethor]],level=18,minLevel=12,giver=[[Dusty Shelf]],giver_loc=[[Estantería polvorienta]],giverType=[[GO]],giverId=112888,ender=[[Bethor Iceshard]],ender_loc=[[Bethor Duroyelo]],enderType=[[NPC]],enderId=1498,prevId=461,poiX=1766,poiY=67,wowhead=[[https://www.wowhead.com/wotlk/quest=491]],image=[[assets/images/quests/placeholder.png]],desc=[[Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed.  This wand was a symbol of their friendship, and although Thule came to despise it he could not part with it, nor could he let the others have it.  So he stole the wand, and hid it in Fenris Keep. Here.  Take the wand to Bethor Iceshard, one of Thule's friends from years past.  I'm sure he will want it.]],logDesc=[[Take the Woven Wand to Bethor Iceshard in the Magic Quarter of the Undercity.]],choiceRewards={{id=3457,qty=1},{id=3458,qty=1},{id=3581,qty=1}}}
DB[492]={id=492,zoneId=85,name=[[A New Plague]],name_loc=[[Una nueva Peste]],level=11,minLevel=6,giver=[[Apothecary Johaan]],giver_loc=[[Boticario Johaan]],giverType=[[NPC]],giverId=1518,ender=[[Captured Mountaineer]],ender_loc=[[Montaraz capturado]],enderType=[[NPC]],enderId=2211,prevId=369,poiX=2289,poiY=234,wowhead=[[https://www.wowhead.com/wotlk/quest=492]],image=[[assets/images/quests/placeholder.png]],desc=[[According to the Deathguard, another one of those foolish Dwarven Mountaineers has just been captured.  The Deathguard likes to use the cellar of the Gallows End Tavern as a holding cell until prisoners can be "properly" dealt with. Why don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.]],logDesc=[[Bring Johaan's Special Drink to the Captured Mountaineer.]]}
DB[493]={id=493,zoneId=130,name=[[Journey to Hillsbrad Foothills]],name_loc=[[Viaja a Laderas de Trabalomas]],level=20,minLevel=19,giver=[[Apothecary Renferrel]],giver_loc=[[Boticario Renferrel]],giverType=[[NPC]],giverId=1937,ender=[[Apothecary Lydon]],ender_loc=[[Boticario Lydon]],enderType=[[NPC]],enderId=2216,poiX=-7,poiY=-899,wowhead=[[https://www.wowhead.com/wotlk/quest=493]],image=[[assets/images/quests/placeholder.png]],desc=[[The Royal Apothecary Society is under extreme pressure from the Dark Lady to develop a New Plague.  We are working diligently and have made much progress.  It is our belief that the success will be achieved much faster if we share information amongst the Society. For that reason I want you to deliver my latest findings to Apothecary Lydon in Tarren Mill, a small town nestled in the Hillsbrad Foothills.  The journey will be a long one. Head south and stick to the roads.  Follow the signs closely!]],logDesc=[[Deliver Apothecary Renferrel's findings to Apothecary Lydon in the town of Tarren Mill in the Hillsbrad Foothills.]]}
DB[494]={id=494,zoneId=267,name=[[Time To Strike]],name_loc=[[El momento de atacar]],level=20,minLevel=19,giver=[[Deathstalker Lesh]],giver_loc=[[Mortacechadora Lesh]],giverType=[[NPC]],giverId=2214,ender=[[High Executor Darthalia]],ender_loc=[[Suma ejecutora Darthalia]],enderType=[[NPC]],enderId=2215,poiX=-33,poiY=-928,wowhead=[[https://www.wowhead.com/wotlk/quest=494]],image=[[assets/images/quests/placeholder.png]],desc=[[Be silent and pay attention, $c. I was sent to this position in order to survey the town of Hillsbrad.  My mission is one of reconnaissance.  It is imperative that you send word to High Executor Darthalia in Tarren Mill at once.  Let her know that I, Deathstalker Lesh, send the following message: "The raven's cry from the west doth beckon." Follow the road to the east and pay close attention to the signs.  Now, hurry!  Off you go to Tarren Mill, and with urgency I might add!]],logDesc=[[Travel to Tarren Mill to deliver Deathstalker Lesh's message to High Executor Darthalia.]]}
DB[495]={id=495,zoneId=1497,name=[[The Crown of Will]],name_loc=[[Corona de Voluntad]],level=39,minLevel=34,giver=[[Sharlindra]],giverType=[[NPC]],giverId=2227,ender=[[Melisara]],enderType=[[NPC]],enderId=2278,rewardNextId=518,poiX=-40,poiY=-937,wowhead=[[https://www.wowhead.com/wotlk/quest=495]],image=[[assets/images/quests/placeholder.png]],desc=[[Mug'Thol and his ogre warband was sent to Alterac to retrieve the Crown of Will for Lady Sylvanas. Unfortunately, instead of returning it, the idiot decided to try it on... I suppose ogres can't resist anything bright and shiny. His bumbling actions have become something of a problem, however. The Crown of Will enabled him to resist the possession placed upon him to serve Lady Sylvanas. The Dark Lady wants an example made, travel to Tarren Mill in Hillsbrad and report to Melisara, my lieutenant.]],logDesc=[[Report to Melisara at Tarren Mill in the Hillsbrad Foothills.]]}
DB[496]={id=496,zoneId=267,name=[[Elixir of Suffering]],name_loc=[[Elixir de sufrimiento]],level=22,minLevel=19,giver=[[Apothecary Lydon]],giver_loc=[[Boticario Lydon]],giverType=[[NPC]],giverId=2216,ender=[[Apothecary Lydon]],ender_loc=[[Boticario Lydon]],enderType=[[NPC]],enderId=2216,rewardNextId=499,poiX=-18,poiY=-916,wowhead=[[https://www.wowhead.com/wotlk/quest=496]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, another wretched day in Tarren Mill.  All of this clean air puts me in such a foul mood, $N. The sooner we can plague the humans here, the better.  I've been conducting intense studies on possible killing agents to use in my concoctions but I haven't the time to collect them all. If you want to make yourself of use, procure the following items for me:  10 Gray Bear Tongues and the very rare and hard to find, Creeper Ichor.  You'll find both bears and creepers just outside of Tarren Mill.]],logDesc=[[Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor.]]}
DB[498]={id=498,zoneId=267,name=[[The Rescue]],name_loc=[[El rescate]],level=22,minLevel=17,giver=[[Krusk]],giverType=[[NPC]],giverId=2229,ender=[[Krusk]],enderType=[[NPC]],enderId=2229,poiX=-485,poiY=-1344,wowhead=[[https://www.wowhead.com/wotlk/quest=498]],image=[[assets/images/quests/placeholder.png]],desc=[[Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate. We went to Durnholde to take a look around, but we were taken by surprise by a large number of the humans. We fought bravely, but their sheer numbers were enough to defeat us. They took a few of us captive, but I was able to escape. Durnholde is just southeast of here, across the river. Drull and Tog'thar are being held there, you must go and rescue them.]],logDesc=[[Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.]],rewards={{id=3734,qty=1}},choiceRewards={{id=3752,qty=1},{id=3733,qty=1}}}
DB[499]={id=499,zoneId=267,name=[[Elixir of Suffering]],name_loc=[[Elixir de sufrimiento]],level=22,minLevel=19,giver=[[Apothecary Lydon]],giver_loc=[[Boticario Lydon]],giverType=[[NPC]],giverId=2216,ender=[[Umpi]],enderType=[[NPC]],enderId=2230,prevId=496,poiX=-9,poiY=-902,wowhead=[[https://www.wowhead.com/wotlk/quest=499]],image=[[assets/images/quests/placeholder.png]],desc=[[It will take but a moment for me to mix these components into what I have deemed an Elixir of Suffering. There we go!  Ah, nothing brightens a gloomy day in these miserable foothills like bringing a little suffering into the world. Let us see if our little potion has achieved its desired effect. Give my assistant Umpi a taste of what the Dark Lady has planned for both humans and Scourge alike.]],logDesc=[[Give Umpi the Elixir of Suffering.]]}
DB[500]={id=500,zoneId=36,name=[[Crushridge Bounty]],name_loc=[[La recompensa Aplastacresta]],level=36,minLevel=30,giver=[[Marshal Redpath]],giver_loc=[[Alguacil Rutagrana]],giverType=[[NPC]],giverId=2263,ender=[[Marshal Redpath]],ender_loc=[[Alguacil Rutagrana]],enderType=[[NPC]],enderId=2263,rewardNextId=504,poiX=484,poiY=-778,wowhead=[[https://www.wowhead.com/wotlk/quest=500]],image=[[assets/images/quests/placeholder.png]],desc=[[Crushridge ogres have dug an ogre mound up in the Alterac Mountains near the ruined city of Alterac.  And my scouts tell me they've taken over those ruins as well. We can't let them get cozy up there; if they think they're safe where they are, then their next step will be to move down into the foothills, which will put them right at our front door! Go north to the Alterac Mountains and hunt ogres.  Bring me the Dirty Knucklebones they carry and you will earn a nice bounty.]],logDesc=[[Gather 9 Dirty Knucklebones from Crushridge ogres in the Alterac Mountains.  Bring them to Marshal Redpath in Southshore.]]}
DB[501]={id=501,zoneId=267,name=[[Elixir of Pain]],name_loc=[[Elixir de dolor]],level=24,minLevel=21,giver=[[Apothecary Lydon]],giver_loc=[[Boticario Lydon]],giverType=[[NPC]],giverId=2216,ender=[[Apothecary Lydon]],ender_loc=[[Boticario Lydon]],enderType=[[NPC]],enderId=2216,rewardNextId=502,poiX=-7,poiY=-899,wowhead=[[https://www.wowhead.com/wotlk/quest=501]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, $N. . .the flowers are blooming in Hillsbrad and the air is so fresh and brisk.  I can't help but to wallow in the misery of it all.  I look out my grimy window and long for the day when our New Plague brings this world the death it deserves. As much as I would love to sit and brood all day, my duty to the Dark Lady calls.  Help me, would you?  My research leads me to believe I can make the most splendid death-brew with the blood of a Mountain Lion.  Bring some to me and we'll have a little fun.]],logDesc=[[Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill.]],rewards={{id=3735,qty=1}},choiceRewards={{id=2230,qty=1},{id=3741,qty=1},{id=6482,qty=1}}}
DB[502]={id=502,zoneId=267,name=[[Elixir of Pain]],name_loc=[[Elixir de dolor]],level=24,minLevel=21,giver=[[Apothecary Lydon]],giver_loc=[[Boticario Lydon]],giverType=[[NPC]],giverId=2216,ender=[[Stanley]],ender_loc=[[Filoja]],enderType=[[NPC]],enderId=2274,prevId=501,poiX=-354,poiY=21,wowhead=[[https://www.wowhead.com/wotlk/quest=502]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, nothing like the smell of fresh blood in the foothills! Now we'll mix in a touch of this and a little of that and let the real fun begin!  What I have created with this blood, I like to call an Elixir of Pain.  If my calculations are correct this concoction could be the start of something very beautiful for Lady Sylvanas.  But what we need is a test. Take this elixir out to the northern farm in Hillsbrad Fields to the southwest.  Let's see how Farmer Ray's little dog Stanley likes this "treat."]],logDesc=[[Feed the Elixir of Pain to Stanley.]]}
DB[503]={id=503,zoneId=267,name=[[Gol'dir]],name_loc=[[Gol'dir]],level=36,minLevel=29,giver=[[Krusk]],giverType=[[NPC]],giverId=2229,ender=[[Gol'dir]],enderType=[[NPC]],enderId=2316,prevId=533,rewardNextId=506,poiX=680,poiY=-913,wowhead=[[https://www.wowhead.com/wotlk/quest=503]],image=[[assets/images/quests/placeholder.png]],desc=[[From what I can tell of the documents you procured, Gol'dir is being held in a large Syndicate base to the north, most likely in the Alterac Mountains. He has been held captive far too long and must be freed.]],logDesc=[[Free Gol'dir then return to Krusk in Tarren Mill.]]}
DB[504]={id=504,zoneId=36,name=[[Crushridge Warmongers]],name_loc=[[Belicistas Aplastacresta]],level=40,minLevel=30,giver=[[Marshal Redpath]],giver_loc=[[Alguacil Rutagrana]],giverType=[[NPC]],giverId=2263,ender=[[Marshal Redpath]],ender_loc=[[Alguacil Rutagrana]],enderType=[[NPC]],enderId=2263,prevId=500,poiX=511,poiY=-351,wowhead=[[https://www.wowhead.com/wotlk/quest=504]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you've had a taste of the Crushridge ogres, I want you to really bloody their noses... Go into the Ruins of Alterac and seek out the Crushridge Warmongers.  I want you to cut down a good number of them - that's the only way those brutes will learn to keep their distance from Alliance territory.]],logDesc=[[Slay 10 Crushridge Warmongers, then return to Marshal Redpath in Southshore.]],choiceRewards={{id=5249,qty=1},{id=3763,qty=1}}}
DB[505]={id=505,zoneId=36,name=[[Syndicate Assassins]],name_loc=[[Hermandad de asesinos]],level=33,minLevel=26,giver=[[Magistrate Henry Maleb]],giver_loc=[[Magistrado Henry Maleb]],giverType=[[NPC]],giverId=2276,ender=[[Magistrate Henry Maleb]],ender_loc=[[Magistrado Henry Maleb]],enderType=[[NPC]],enderId=2276,poiX=29,poiY=-589,wowhead=[[https://www.wowhead.com/wotlk/quest=505]],image=[[assets/images/quests/placeholder.png]],desc=[[I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate.  The assassins were never found, but through our investigations we're almost certain they were hired by the Syndicate - a group of thieves led by villainous nobles of the now fallen kingdom of Alterac. The Syndicate has a camps in Sofera's Naze and Corahn's Dagger, north and west of the Horde-occupied Tarren Mill.  Slay the Syndicate members you find in these camps.]],logDesc=[[Kill 12 Syndicate Footpads and 8 Syndicate Thieves, then return to Magistrate Henry Maleb in Southshore.]],choiceRewards={{id=3758,qty=1},{id=3759,qty=1}}}
DB[506]={id=506,zoneId=267,name=[[Blackmoore's Legacy]],name_loc=[[El legado de Lodonegro]],level=36,minLevel=29,giver=[[Gol'dir]],giverType=[[NPC]],giverId=2316,ender=[[Krusk]],enderType=[[NPC]],enderId=2229,prevId=503,rewardNextId=507,poiX=-41,poiY=-957,wowhead=[[https://www.wowhead.com/wotlk/quest=506]],image=[[assets/images/quests/placeholder.png]],desc=[[A day or two ago, I was visited by the leader of this Syndicate. His name was Aliden Perenolde, and styled himself lord of this land. He confided in me his plans to take the orcs that stood against him as slaves, just as his father and his mentor, the despised Blackmoore, had planned. More important was that he brought his mistress, a wisp of a girl named Elysa. Around her neck was the pendant the Warchief desires. Now go, I will make my own way, after I have settled my business here.]],logDesc=[[Return the information gathered by Gol'dir to Krusk in Tarren Mill.]]}
DB[507]={id=507,zoneId=267,name=[[Lord Aliden Perenolde]],name_loc=[[Lord Aliden Perenolde]],level=42,minLevel=29,giver=[[Krusk]],giverType=[[NPC]],giverId=2229,ender=[[Elysa]],enderType=[[NPC]],enderId=2317,prevId=506,rewardNextId=508,poiX=1228,poiY=-317,wowhead=[[https://www.wowhead.com/wotlk/quest=507]],image=[[assets/images/quests/placeholder.png]],desc=[[It is clear that Perenolde must be killed, his foulness removed from the world. His manor lies a ways to the north of here, on the shores of Lordamere Lake. Do your duty, $n, then retrieve the pendant that the Warchief desires, and return here.]],logDesc=[[Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant.]]}
DB[508]={id=508,zoneId=267,name=[[Taretha's Gift]],name_loc=[[Un regalo de Taretha]],level=40,minLevel=29,giver=[[Elysa]],giverType=[[NPC]],giverId=2317,ender=[[Krusk]],enderType=[[NPC]],enderId=2229,prevId=507,poiX=-41,poiY=-957,wowhead=[[https://www.wowhead.com/wotlk/quest=508]],image=[[assets/images/quests/placeholder.png]],desc=[[The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace...]],logDesc=[[Return Taretha's pendant to Krusk at Tarren Mill in Hillsbrad Foothills.]],choiceRewards={{id=3764,qty=1},{id=3765,qty=1}}}
DB[509]={id=509,zoneId=267,name=[[Elixir of Agony]],name_loc=[[Elixir de agonía]],level=28,minLevel=24,giver=[[Apothecary Lydon]],giver_loc=[[Boticario Lydon]],giverType=[[NPC]],giverId=2216,ender=[[Apothecary Lydon]],ender_loc=[[Boticario Lydon]],enderType=[[NPC]],enderId=2216,rewardNextId=513,poiX=-7,poiY=-899,wowhead=[[https://www.wowhead.com/wotlk/quest=509]],image=[[assets/images/quests/placeholder.png]],desc=[[Another day, another elixir to be made. If it were up to me, I'd just let the pathetic humans and Scourge fight it out.  They seem bent on killing each other as is. Alas, our Dark Lady wants to help speed up the process a tad so why not pass these morbid days by spreading a little death and disease across the land? Here's the plan, $N: you go out to Nethander Stead, south of Tarren Mill and east of the river and Southshore. Collect for me 6 Mudsnout Blossoms from the field for my next elixir.]],logDesc=[[Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill.]],rewards={{id=2459,qty=3},{id=929,qty=5}}}
DB[510]={id=510,zoneId=36,name=[[Foreboding Plans]],name_loc=[[Documentos de planificación]],level=34,minLevel=26,giver=[[Syndicate Documents]],giver_loc=[[Documentos de la Hermandad]],giverType=[[GO]],giverId=1740,ender=[[Magistrate Henry Maleb]],ender_loc=[[Magistrado Henry Maleb]],enderType=[[NPC]],enderId=2276,rewardNextId=512,poiX=-861,poiY=-474,wowhead=[[https://www.wowhead.com/wotlk/quest=510]],image=[[assets/images/quests/placeholder.png]],desc=[[Among these documents is a list of requested supplies.  These include mundane items (food, weapons, clothing) as well as more exotic gear (masks, oil, poison). But what is most notable is the urgency of the request - these supplies were needed soon in order to undertake what is described in the document as an "important mission against Southshore."]],logDesc=[[Bring the Foreboding Plans to Magistrate Maleb in Southshore.]]}
DB[511]={id=511,zoneId=36,name=[[Encrypted Letter]],name_loc=[[Una carta cifrada]],level=34,minLevel=30,giver=[[Syndicate Documents]],giver_loc=[[Documentos de la Hermandad]],giverType=[[GO]],giverId=1740,ender=[[Loremaster Dibbs]],ender_loc=[[Maestro cultural Dibbs]],enderType=[[NPC]],enderId=2277,rewardNextId=514,poiX=-818,poiY=-552,wowhead=[[https://www.wowhead.com/wotlk/quest=511]],image=[[assets/images/quests/placeholder.png]],desc=[[One of the letters on this table is encrypted and inscrutable.]],logDesc=[[Bring the Encrypted Letter to Loremaster Dibbs in Southshore.]]}
DB[512]={id=512,zoneId=36,name=[[Noble Deaths]],name_loc=[[Nobles muertes]],level=36,minLevel=26,giver=[[Magistrate Henry Maleb]],giver_loc=[[Magistrado Henry Maleb]],giverType=[[NPC]],giverId=2276,ender=[[Magistrate Henry Maleb]],ender_loc=[[Magistrado Henry Maleb]],enderType=[[NPC]],enderId=2276,prevId=510,poiX=-861,poiY=-474,wowhead=[[https://www.wowhead.com/wotlk/quest=512]],image=[[assets/images/quests/placeholder.png]],desc=[[I fear the leadership behind the Syndicate is bent on Southshore's ruin.  We must strike hard at these leaders before their plans are realized. Enter the ruins of Strahnbrad, in the Alterac Mountains to the north.  We think the Syndicate is using the area as a headquarters. We know this gang of cutthroats is run by former Alterac nobles.  They may be hiding as normal Syndicate agents, but you'll know you've killed a noble by the signet ring he wears. Bring me those signet rings.]],logDesc=[[Bring 7 Alterac Signet Rings to Magistrate Maleb in Southshore.]]}
DB[513]={id=513,zoneId=267,name=[[Elixir of Agony]],name_loc=[[Elixir de agonía]],level=28,minLevel=24,giver=[[Apothecary Lydon]],giver_loc=[[Boticario Lydon]],giverType=[[NPC]],giverId=2216,ender=[[Master Apothecary Faranell]],ender_loc=[[Maestro boticario Faranell]],enderType=[[NPC]],enderId=2055,prevId=509,rewardNextId=515,poiX=1434,poiY=405,wowhead=[[https://www.wowhead.com/wotlk/quest=513]],image=[[assets/images/quests/placeholder.png]],desc=[[Just when I thought another day was going to pass devoid of any joy, you brought me those marvelous Mudsnout Blossoms. First I will mix them down into a fine composite.  We'll then need Master Apothecary Faranell in the Undercity to apply his colloid of decay to it and then we'll be ready for some good fun indeed! Here, take this Mudsnout Composite and run it off to Master Faranell at once, $N.]],logDesc=[[Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity.]]}
DB[514]={id=514,zoneId=36,name=[[Letter to Stormpike]],name_loc=[[Una carta para Pico Tormenta]],level=34,minLevel=30,giver=[[Loremaster Dibbs]],giver_loc=[[Maestro cultural Dibbs]],giverType=[[NPC]],giverId=2277,ender=[[Prospector Stormpike]],ender_loc=[[Prospector Pico Tormenta]],enderType=[[NPC]],enderId=1356,prevId=511,rewardNextId=525,poiX=-4631,poiY=-1304,wowhead=[[https://www.wowhead.com/wotlk/quest=514]],image=[[assets/images/quests/placeholder.png]],desc=[[I have a colleague in Ironforge who may be able to help decrypt this letter.  Go to the Library in the Hall of Explorers in Ironforge and speak with Prospector Stormpike.  Tell him I sent you and show him the letter.  If there's anyone north of Blackrock Spire who can read this, it is he.]],logDesc=[[Take the Cleverly Encrypted Letter to Prospector Stormpike in Ironforge.]]}
DB[515]={id=515,zoneId=267,name=[[Elixir of Agony]],name_loc=[[Elixir de agonía]],level=30,minLevel=24,giver=[[Master Apothecary Faranell]],giver_loc=[[Maestro boticario Faranell]],giverType=[[NPC]],giverId=2055,ender=[[Apothecary Lydon]],ender_loc=[[Boticario Lydon]],enderType=[[NPC]],enderId=2216,prevId=513,rewardNextId=517,poiX=-7,poiY=-899,wowhead=[[https://www.wowhead.com/wotlk/quest=515]],image=[[assets/images/quests/placeholder.png]],desc=[[A mudsnout composite?  Absolutely brilliant!  Why didn't I think of that? Let me contribute my colloid of decay to this devilish brew. In order to activate the contaminating agents in this mudsnout mixture, Lydon is going to need a strong troll's blood potion, as well as some daggerspine scales and torn fin eyes from the southern coast of Hillsbrad.  He'll know what to do once you've gathered him all the reagents.  And my, how anxious I am to hear how his experiment goes!]],logDesc=[[Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill.]],choiceRewards={{id=3749,qty=1},{id=3747,qty=1}}}
DB[516]={id=516,zoneId=130,name=[[Beren's Peril]],name_loc=[[El Desafío de Beren]],level=21,minLevel=16,giver=[[Shadow Priest Allister]],giver_loc=[[Sacerdote de las Sombras Allister]],giverType=[[NPC]],giverId=2121,ender=[[Shadow Priest Allister]],ender_loc=[[Sacerdote de las Sombras Allister]],enderType=[[NPC]],enderId=2121,poiX=-354,poiY=897,wowhead=[[https://www.wowhead.com/wotlk/quest=516]],image=[[assets/images/quests/placeholder.png]],desc=[[I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud. Unfortunately, my information is spotty, at best. They are reported to be hiding in a location known as Beren's Peril. The exact location is unknown, but it appears to be a cave in the hills, near a pocket of Dalaran wizards. I trust your resourcefulness. Find them, and put them down.]],logDesc=[[Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher.]],rewards={{id=5252,qty=1}}}
DB[517]={id=517,zoneId=267,name=[[Elixir of Agony]],name_loc=[[Elixir de agonía]],level=30,minLevel=24,giver=[[Apothecary Lydon]],giver_loc=[[Boticario Lydon]],giverType=[[NPC]],giverId=2216,ender=[[Apothecary Lydon]],ender_loc=[[Boticario Lydon]],enderType=[[NPC]],enderId=2216,prevId=515,rewardNextId=524,poiX=-1310,poiY=-1225,wowhead=[[https://www.wowhead.com/wotlk/quest=517]],image=[[assets/images/quests/placeholder.png]],desc=[[This new elixir is finally ready to be tested.  But why let a perfectly good, highly contagious plague go to waste on a mere frog or dog?  Let's have us some true fun in the name of Lady Sylvanas. Head down to Dun Garok.  You know the barracks where those filthy little dwarves skitter about.  Steal me a keg of their Shindigger Stout.  Once I have that keg, you and I will have quite the party, $N.]],logDesc=[[Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill.]]}
DB[518]={id=518,zoneId=267,name=[[The Crown of Will]],name_loc=[[Corona de Voluntad]],level=39,minLevel=34,giver=[[Melisara]],giverType=[[NPC]],giverId=2278,ender=[[Melisara]],enderType=[[NPC]],enderId=2278,rewardNextId=519,poiX=625,poiY=-517,wowhead=[[https://www.wowhead.com/wotlk/quest=518]],image=[[assets/images/quests/placeholder.png]],desc=[[Mug'Thol and his Crushridge ogres have overrun the ruins of Alterac. It will be hard to inflict any serious punishment upon him without thinning out the ogres' numbers. After softening them up, we'll proceed. Understood? Good. Now go.]],logDesc=[[Kill 10 Crushridge Maulers for Melisara in Tarren Mill.]]}
DB[519]={id=519,zoneId=267,name=[[The Crown of Will]],name_loc=[[Corona de Voluntad]],level=41,minLevel=34,giver=[[Melisara]],giverType=[[NPC]],giverId=2278,ender=[[Melisara]],enderType=[[NPC]],enderId=2278,prevId=518,rewardNextId=520,poiX=513,poiY=-325,wowhead=[[https://www.wowhead.com/wotlk/quest=519]],image=[[assets/images/quests/placeholder.png]],desc=[[Targ, Muckrake, and Glommus are Mug'Thol's lieutenants. They are loyal to him, though who can say what drives an ogre to loyalty. Bring me their heads, $n, and then all that will remain is to remove Mug'Thol's head, crown and all.]],logDesc=[[Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill.]]}
DB[520]={id=520,zoneId=267,name=[[The Crown of Will]],name_loc=[[Corona de Voluntad]],level=43,minLevel=34,giver=[[Melisara]],giverType=[[NPC]],giverId=2278,ender=[[Melisara]],enderType=[[NPC]],enderId=2278,prevId=519,rewardNextId=521,poiX=487,poiY=-216,wowhead=[[https://www.wowhead.com/wotlk/quest=520]],image=[[assets/images/quests/placeholder.png]],desc=[[With Mug'Thol's lieutenants dead, all that remains is to kill Mug'Thol and retrieve the Crown of Will. I have no doubt he'll be reluctant to part with it. Most likely expecting you, too, given the... departure... of his fellows. Find Mug'Thol, and deliver his head and the Crown to me. The Crushridge resistance will be at an end.]],logDesc=[[Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill.]]}
DB[521]={id=521,zoneId=267,name=[[The Crown of Will]],name_loc=[[Corona de Voluntad]],level=43,minLevel=34,giver=[[Melisara]],giverType=[[NPC]],giverId=2278,ender=[[Sharlindra]],enderType=[[NPC]],enderId=2227,prevId=520,poiX=1278,poiY=320,wowhead=[[https://www.wowhead.com/wotlk/quest=521]],image=[[assets/images/quests/placeholder.png]],desc=[[All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas. I would warn you against thinking to use it for your own purposes, $n, Mug'Thol's fate should be illustration enough.]],logDesc=[[Deliver the Crown of Will to Sharlindra in the Undercity.]],rewards={{id=4430,qty=1}}}
DB[522]={id=522,zoneId=36,name=[[Assassin's Contract]],name_loc=[[Contrato de asesino]],level=38,minLevel=30,giverType=[[NPC]],ender=[[Magistrate Henry Maleb]],ender_loc=[[Magistrado Henry Maleb]],enderType=[[NPC]],enderId=2276,rewardNextId=523,poiX=-864,poiY=-420,wowhead=[[https://www.wowhead.com/wotlk/quest=522]],image=[[assets/images/quests/placeholder.png]],desc=[[This is a contract for the assassination of Magistrate Henry Maleb.  It was sealed and stamped in red wax, using a distinctive signet ring.]],logDesc=[[Bring the Assassin's Contract to Magistrate Maleb in Southshore.]]}
DB[523]={id=523,zoneId=36,name=[[Baron's Demise]],name_loc=[[Muerte al Barón]],level=40,minLevel=30,giver=[[Magistrate Henry Maleb]],giver_loc=[[Magistrado Henry Maleb]],giverType=[[NPC]],giverId=2276,ender=[[Magistrate Henry Maleb]],ender_loc=[[Magistrado Henry Maleb]],enderType=[[NPC]],enderId=2276,prevId=522,poiX=-861,poiY=-474,wowhead=[[https://www.wowhead.com/wotlk/quest=523]],image=[[assets/images/quests/placeholder.png]],desc=[[The contract you recovered was signed by Baron Vardus, a noble of the former kingdom of Alterac, and one known for a cold heart and brutal practices.  I'm not surprised someone like the Baron was behind this. Find this man.  Find him, and bring him to justice.  He must be among the Syndicate haunts - perhaps at the ruins of Strahnbrad, or perhaps within the valley north of them.]],logDesc=[[Bring the Head of Baron Vardus to Magistrate Maleb in Southshore.]]}
DB[524]={id=524,zoneId=267,name=[[Elixir of Agony]],name_loc=[[Elixir de agonía]],level=30,minLevel=24,giver=[[Apothecary Lydon]],giver_loc=[[Boticario Lydon]],giverType=[[NPC]],giverId=2216,ender=[[Dusty Rug]],ender_loc=[[Alfombra polvorienta]],enderType=[[GO]],enderId=1728,prevId=517,poiY=-943,wowhead=[[https://www.wowhead.com/wotlk/quest=524]],image=[[assets/images/quests/placeholder.png]],desc=[[Next door the Deathguards are holding a few captured farmers hostage.  High Executor Darthalia suspected one of the military strategists from Stormwind to be hiding out amongst them.  Apparently the military chap was found dead in the Plaguelands last night.  Darthalia, always looking out for me, decided the prisoners would be left to my disposal. I think it's time we threw those farmers a party.  Sounds like a grand ol' time! Place this tainted keg on the rug in their room.  Plagued brew for all!]],logDesc=[[Place the Tainted Keg on the rug for the captured farmers.]]}
DB[525]={id=525,zoneId=36,name=[[Further Mysteries]],name_loc=[[Más misterios]],level=34,minLevel=30,giver=[[Prospector Stormpike]],giver_loc=[[Prospector Pico Tormenta]],giverType=[[NPC]],giverId=1356,ender=[[Magistrate Henry Maleb]],ender_loc=[[Magistrado Henry Maleb]],enderType=[[NPC]],enderId=2276,prevId=514,rewardNextId=537,poiX=-861,poiY=-474,wowhead=[[https://www.wowhead.com/wotlk/quest=525]],image=[[assets/images/quests/placeholder.png]],desc=[[I decrypted the letter, but I don't know what to make of it.  You found this among thieves in the Alterac foothills?  Very strange... You should take this to the magistrate of Southshore.  Although this letter is cryptic, his is the closest town to Alterac; if a threat is brewing, then he should know.]],logDesc=[[Bring the Decrypted Letter to Magistrate Maleb in Southshore.]]}
DB[526]={id=526,zoneId=10,name=[[Lightforge Ingots]],name_loc=[[Lingotes Forjaluz]],level=29,minLevel=20,giver=[[Glorin Steelbrow]],giver_loc=[[Glorin Frenteacerada]],giverType=[[NPC]],giverId=1217,ender=[[Glorin Steelbrow]],ender_loc=[[Glorin Frenteacerada]],enderType=[[NPC]],enderId=1217,prevId=324,rewardNextId=322,poiX=-3915,poiY=-949,wowhead=[[https://www.wowhead.com/wotlk/quest=526]],image=[[assets/images/quests/placeholder.png]],desc=[[You might have found one lightforge ingot in that chest, but that's not enough to craft anything decent! You should go back there and look for more.  Maybe the murlocs around that wrecked ship have lightforge ingots on them.]],logDesc=[[Gather 5 lightforge ingots, then return to Glorin Steelbrow in the Wetlands.]]}
DB[527]={id=527,zoneId=267,name=[[Battle of Hillsbrad]],name_loc=[[La batalla de Trabalomas]],level=24,minLevel=19,giver=[[High Executor Darthalia]],giver_loc=[[Suma ejecutora Darthalia]],giverType=[[NPC]],giverId=2215,ender=[[High Executor Darthalia]],ender_loc=[[Suma ejecutora Darthalia]],enderType=[[NPC]],enderId=2215,rewardNextId=528,poiX=-448,poiY=-98,wowhead=[[https://www.wowhead.com/wotlk/quest=527]],image=[[assets/images/quests/placeholder.png]],desc=[[Stand at attention while addressing me, $c. I am under direct command of Varimathras.  We are to quell the human infestation until our apothecaries can develop the new plague. Our information leads us to believe that the town of Hillsbrad is vulnerable to attack.  Your first assignment is aimed at disrupting their food supply and infrastructure. Travel west.  Raid the northernmost farms of Hillsbrad Fields.  Make sure that the landowners, Farmer Ray and Farmer Getz, are executed as well.]],logDesc=[[Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill.]]}
DB[528]={id=528,zoneId=267,name=[[Battle of Hillsbrad]],name_loc=[[La batalla de Trabalomas]],level=25,minLevel=19,giver=[[High Executor Darthalia]],giver_loc=[[Suma ejecutora Darthalia]],giverType=[[NPC]],giverId=2215,ender=[[High Executor Darthalia]],ender_loc=[[Suma ejecutora Darthalia]],enderType=[[NPC]],enderId=2215,prevId=527,rewardNextId=529,poiX=-590,poiY=-108,wowhead=[[https://www.wowhead.com/wotlk/quest=528]],image=[[assets/images/quests/placeholder.png]],desc=[[Word of the attack on the northern farms has the townsfolk panicked.  Most excellent. Our Deathstalkers report peasants fleeing to the fields in southern Hillsbrad.  The fools think they can hide in the orchards and escape their doom. Prove them wrong, $N.  Return to Hillsbrad Fields and seek out the cowering peasants.  Lay waste to them in the name of our Dark Lady. Dismissed!]],logDesc=[[Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill.]]}
DB[529]={id=529,zoneId=267,name=[[Battle of Hillsbrad]],name_loc=[[La batalla de Trabalomas]],level=26,minLevel=19,giver=[[High Executor Darthalia]],giver_loc=[[Suma ejecutora Darthalia]],giverType=[[NPC]],giverId=2215,ender=[[High Executor Darthalia]],ender_loc=[[Suma ejecutora Darthalia]],enderType=[[NPC]],enderId=2215,prevId=528,rewardNextId=532,poiX=-548,poiY=39,wowhead=[[https://www.wowhead.com/wotlk/quest=529]],image=[[assets/images/quests/placeholder.png]],desc=[[The humans of Hillsbrad have been putting up unexpected resistance.  The problem appears to be that the townsfolk are being armed by the local blacksmith.  We need to shut down all supply lines. Your mission will be to execute Blacksmith Verringtan.  Slay his apprentices as well.  While there, bring back a shipment of iron from their stockpile.  The supplies will come in handy when we are done with the conquering of Hillsbrad and begin razing Southshore.]],logDesc=[[Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths. Retrieve a shipment of iron and report back to Darthalia in Tarren Mill.]]}
DB[530]={id=530,zoneId=130,name=[[A Husband's Revenge]],name_loc=[[La venganza de un esposo]],level=20,minLevel=10,giver=[[Raleigh Andrean]],giver_loc=[[Raleigh Andrean]],giverType=[[NPC]],giverId=2050,ender=[[Raleigh Andrean]],ender_loc=[[Raleigh Andrean]],enderType=[[NPC]],enderId=2050,prevId=441,poiX=-705,poiY=1575,wowhead=[[https://www.wowhead.com/wotlk/quest=530]],image=[[assets/images/quests/placeholder.png]],desc=[[Valdred, once my good friend, was my wife's murderer.  Although I am incapable of grieving, I do yearn for revenge.  If you kill Valdred and bring me his cursed hands, then I will reward you. I last heard he was at the Greymane Wall in southern Silverpine, trying to flee into the kingdom of Gilneas.]],logDesc=[[Kill Valdred Moray. Bring his hands to Raleigh Andrean in the Undercity.]],rewards={{id=3235,qty=1}}}
DB[531]={id=531,zoneId=38,name=[[Vyrin's Revenge]],name_loc=[[La venganza de Vyrin]],level=20,minLevel=15,giver=[[Daryl the Youngling]],giver_loc=[[Daryl el Jovenzuelo]],giverType=[[NPC]],giverId=1187,ender=[[Vyrin Swiftwind]],ender_loc=[[Vyrin Vientoveloz]],enderType=[[NPC]],enderId=1156,prevId=271,poiX=-5612,poiY=-3008,wowhead=[[https://www.wowhead.com/wotlk/quest=531]],image=[[assets/images/quests/placeholder.png]],desc=[[Light! Don't bring things like that into the Lodge... it's unsanitary, unspeakable, un... un... unsanitary! Just get it out of here, will you? No one wants to see your bloody little trophy, really!]],logDesc=[[Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge.]],choiceRewards={{id=3574,qty=1},{id=3573,qty=1}}}
DB[532]={id=532,zoneId=267,name=[[Battle of Hillsbrad]],name_loc=[[La batalla de Trabalomas]],level=26,minLevel=19,giver=[[High Executor Darthalia]],giver_loc=[[Suma ejecutora Darthalia]],giverType=[[NPC]],giverId=2215,ender=[[High Executor Darthalia]],ender_loc=[[Suma ejecutora Darthalia]],enderType=[[NPC]],enderId=2215,prevId=529,rewardNextId=539,poiX=-488,poiY=117,wowhead=[[https://www.wowhead.com/wotlk/quest=532]],image=[[assets/images/quests/placeholder.png]],desc=[[The town of Hillsbrad is in disarray and we believe it will soon fall.  We must, however, persist in our ruthlessness until the human scum are wiped from the foothills for eternity. Despite their overwhelming losses, the humans rally around their leadership and keep fighting.  We must eliminate their leader, Magistrate Burnside, as well as the town council.  Destroy their revered political document as well, the Hillsbrad Proclamation.  And while you're at it, steal the town registry.]],logDesc=[[Kill Magistrate Burnside and 4 Hillsbrad Councilmen.  Destroy the Hillsbrad Proclamation.  Steal the Hillsbrad Town Registry.  Report back to Darthalia in Tarren Mill afterwards.]]}
DB[533]={id=533,zoneId=267,name=[[Infiltration]],name_loc=[[Infiltración]],level=34,minLevel=29,giver=[[Krusk]],giverType=[[NPC]],giverId=2229,ender=[[Krusk]],enderType=[[NPC]],enderId=2229,rewardNextId=503,poiX=-15,poiY=-584,wowhead=[[https://www.wowhead.com/wotlk/quest=533]],image=[[assets/images/quests/placeholder.png]],desc=[[At last we begin to hear word and rumor, find evidence of Gol'dir's whereabouts. The humans have been moving him around, but we are narrowing down our search and focusing on the large Syndicate camp just north of here. Go there, $n, and bring back whatever information you can get your hands on.]],logDesc=[[Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill.]]}
DB[535]={id=535,zoneId=36,name=[[Valik]],name_loc=[[Valik]],level=34,minLevel=29,giver=[[Henchman Valik]],giver_loc=[[Secuaz Valik]],giverType=[[NPC]],giverId=2333,ender=[[Henchman Valik]],ender_loc=[[Secuaz Valik]],enderType=[[NPC]],enderId=2333,poiX=202,poiY=-817,wowhead=[[https://www.wowhead.com/wotlk/quest=535]],image=[[assets/images/quests/placeholder.png]],desc=[[Urrgh... Injured and dying and confronted with the enemy. No doubt you'll kill me anyway, but if you bring me some Southshore stout--your kind does drink, don't they?--I'll tell you what you want to know.]],logDesc=[[Bring a mug of Southshore Stout to Valik in the Syndicate camp.]],rewards={{id=3601,qty=1}}}
DB[536]={id=536,zoneId=267,name=[[Down the Coast]],name_loc=[[A lo largo de la costa]],level=30,minLevel=25,giver=[[Lieutenant Farren Orinelle]],giver_loc=[[Teniente Farren Orinelle]],giverType=[[NPC]],giverId=2228,ender=[[Lieutenant Farren Orinelle]],ender_loc=[[Teniente Farren Orinelle]],enderType=[[NPC]],enderId=2228,rewardNextId=559,poiX=-975,poiY=-499,wowhead=[[https://www.wowhead.com/wotlk/quest=536]],image=[[assets/images/quests/placeholder.png]],desc=[[Transferred from the Stormwind city guard to Southshore, a town that should be abandoned by the looks of it... Smell of the harbor day and night. Not to mention ol' Redpath... Wants me to take care of the murlocs. Ha!  I can barely rouse myself to go out to some of the pockets of the overgrown fish down the Western Strand. If you would go in my place and take care of them, I'd appreciate it.]],logDesc=[[Kill 10 Torn Fin Tidehunters and 10 Torn Fin Oracles for Lieutenant Farren Orinelle in Southshore.]]}
DB[537]={id=537,zoneId=36,name=[[Dark Council]],name_loc=[[Consejo oscuro]],level=40,minLevel=30,giver=[[Magistrate Henry Maleb]],giver_loc=[[Magistrado Henry Maleb]],giverType=[[NPC]],giverId=2276,ender=[[Magistrate Henry Maleb]],ender_loc=[[Magistrado Henry Maleb]],enderType=[[NPC]],enderId=2276,prevId=525,poiX=684,poiY=-1000,wowhead=[[https://www.wowhead.com/wotlk/quest=537]],image=[[assets/images/quests/placeholder.png]],desc=[[The letter you brought me was written by a being who calls himself Nagaz, a member of the Argus Wake.  I don't know what this Argus Wake is, but if they're in alliance with the Syndicate then they must be a threat. I want you to find Nagaz and the Argus Shadow Mages mentioned in that letter.  I want you to find them, and kill them. Search in the Uplands, where the Syndicate is strongest.  It is north of Strahnbrad. With luck, you'll find these envoys of the Argus Wake there.]],logDesc=[[Kill 4 Argus Shadow Mages. Bring the Head of Nagaz to Magistrate Maleb in Southshore.]]}
DB[538]={id=538,zoneId=1519,name=[[Southshore]],name_loc=[[Costasur]],level=38,minLevel=20,giver=[[Milton Sheaf]],giver_loc=[[Milton Gavilla]],giverType=[[NPC]],giverId=1440,ender=[[Loremaster Dibbs]],ender_loc=[[Maestro cultural Dibbs]],enderType=[[NPC]],enderId=2277,prevId=337,rewardNextId=540,poiX=-818,poiY=-552,wowhead=[[https://www.wowhead.com/wotlk/quest=538]],image=[[assets/images/quests/placeholder.png]],desc=[[$N.  If you don't mind a long journey then I have a task for you, to again help Stormwind fill its library. The old kingdom of Alterac fell after the great war, and it had a large collection of books.  It's a tragedy that the city is ruined, but even more tragic is all of their knowledge lost!  We must recover what we can. Southshore is the closest town to the Ruins of Alterac.  Go there and speak with Loremaster Dibbs.  He can direct you to the ruins, and to what books may be found there.]],logDesc=[[Speak with Loremaster Dibbs in Southshore.]]}
DB[539]={id=539,zoneId=267,name=[[Battle of Hillsbrad]],name_loc=[[La batalla de Trabalomas]],level=28,minLevel=19,giver=[[High Executor Darthalia]],giver_loc=[[Suma ejecutora Darthalia]],giverType=[[NPC]],giverId=2215,ender=[[High Executor Darthalia]],ender_loc=[[Suma ejecutora Darthalia]],enderType=[[NPC]],enderId=2215,prevId=532,rewardNextId=541,poiX=-795,poiY=68,wowhead=[[https://www.wowhead.com/wotlk/quest=539]],image=[[assets/images/quests/placeholder.png]],desc=[[The Hillsbrad Town Registry indicates that the Azurelode Mine is under Alliance control.  Furthermore, the mine is a prime source of iron ore for the Alliance armories. Even though we've struck a decisive blow to the town of Hillsbrad, the Alliance still supports and protects the Azurelode Mine fervently. The mine lies due south of Hillsbrad.  Go there and slay the foreman, a human by the name of Bonds.  Kill his miners as well.  That should send a clear message to the Alliance.]],logDesc=[[Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill.]]}
DB[540]={id=540,zoneId=1519,name=[[Preserving Knowledge]],name_loc=[[Proteger el conocimiento]],level=38,minLevel=20,giver=[[Loremaster Dibbs]],giver_loc=[[Maestro cultural Dibbs]],giverType=[[NPC]],giverId=2277,ender=[[Loremaster Dibbs]],ender_loc=[[Maestro cultural Dibbs]],enderType=[[NPC]],enderId=2277,prevId=538,rewardNextId=542,poiX=484,poiY=-778,wowhead=[[https://www.wowhead.com/wotlk/quest=540]],image=[[assets/images/quests/placeholder.png]],desc=[[Those beastly ogres now reside within Alterac's ruins, and I shudder to think what they're doing with the precious books still there.  You must recover what you can! Enter the Ruins of Alterac and search for tomes looted by the ogres.  Get whatever you can find and bring them to me, but also seek out one book in particular: The Arm of Gri'lek.  It contains ancient troll lore that I must learn, and the Ruins of Alterac was the last known location of an intact copy of this book.]],logDesc=[[Bring 5 Recovered Tomes and the Worn Leather Book containing The Arm of Gri'lek to Loremaster Dibbs in Southshore.]]}
DB[541]={id=541,zoneId=267,name=[[Battle of Hillsbrad]],name_loc=[[La batalla de Trabalomas]],level=30,minLevel=19,giver=[[High Executor Darthalia]],giver_loc=[[Suma ejecutora Darthalia]],giverType=[[NPC]],giverId=2215,ender=[[High Executor Darthalia]],ender_loc=[[Suma ejecutora Darthalia]],enderType=[[NPC]],enderId=2215,prevId=539,rewardNextId=14351,poiX=-1335,poiY=-1263,wowhead=[[https://www.wowhead.com/wotlk/quest=541]],image=[[assets/images/quests/placeholder.png]],desc=[[Dwarves aiding the humans?  Damn those filthy little beasts. We shall test the strength of the so-called Alliance.  We'll see how anxious those little ankle-bashers are to help the humans once they feel our wrath.  We know exactly where their stronghold is in this territory. They have established a barracks in southeastern Hillsbrad along Thoradin's Wall called Dun Garok.  The final mission of this battle is to lay siege on Dun Garok, $c.  Captain Ironhill, their leader, must die.]],logDesc=[[Travel to Dun Garok and kill 8 Mountaineers, 4 Riflemen, 2 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill.]]}
DB[542]={id=542,zoneId=1519,name=[[Return to Milton]],name_loc=[[Regresa junto a Milton]],level=38,minLevel=20,giver=[[Loremaster Dibbs]],giver_loc=[[Maestro cultural Dibbs]],giverType=[[NPC]],giverId=2277,ender=[[Milton Sheaf]],ender_loc=[[Milton Gavilla]],enderType=[[NPC]],enderId=1440,prevId=540,poiX=-8346,poiY=384,wowhead=[[https://www.wowhead.com/wotlk/quest=542]],image=[[assets/images/quests/placeholder.png]],desc=[[I need to spend some time studying the Arm of Gri'lek book you brought me, though I'm sure Milton is eager to get the other recovered books into Stormwind's collection. Here are the books you gathered from the Ruins of Alterac, packed and catalogued.  Take them back to Milton Sheaf in Stormwind and I'm sure he'll be grateful.]],logDesc=[[Bring the Tomes of Alterac to Milton Sheaf in Stormwind.]]}
DB[543]={id=543,zoneId=1519,name=[[The Perenolde Tiara]],name_loc=[[La Tiara Perenolde]],level=40,minLevel=30,giver=[[Count Remington Ridgewell]],giver_loc=[[Conde Remington Bonacresta]],giverType=[[NPC]],giverId=2285,ender=[[Count Remington Ridgewell]],ender_loc=[[Conde Remington Bonacresta]],enderType=[[NPC]],enderId=2285,poiX=-8550,poiY=386,wowhead=[[https://www.wowhead.com/wotlk/quest=543]],image=[[assets/images/quests/placeholder.png]],desc=[[The Perenolde Tiara is an old heirloom of the Perenolde "nobles" - the ruling family of Alterac before that kingdom fell to ruin.  It is said to have been crafted by master jewelers in Ironforge, and fitted with the finest of emeralds. When Alterac was destroyed the Tiara was lost, but there are rumors that an Ogre Mage, Grel'borg the Miser, found the tiara and now wanders the Ruins of Alterac searching for more treasures. We would have you acquire the tiara for us.]],logDesc=[[Bring the Perenolde Tiara to Remington Ridgewell in Stormwind.]]}
DB[544]={id=544,zoneId=267,name=[[Prison Break In]],name_loc=[[Colarse en la cárcel]],level=34,minLevel=30,giver=[[Magus Wordeen Voidglare]],giver_loc=[[Magus Wordeen Vacuamirada]],giverType=[[NPC]],giverId=2410,ender=[[Magus Wordeen Voidglare]],ender_loc=[[Magus Wordeen Vacuamirada]],enderType=[[NPC]],enderId=2410,rewardNextId=545,poiX=-104,poiY=225,wowhead=[[https://www.wowhead.com/wotlk/quest=544]],image=[[assets/images/quests/placeholder.png]],desc=[[I came to Tarren Mill to research, but now must resolve a crisis.  You see, four Forsaken fled the Undercity a few months ago.  They turned their backs on their brethren, but what's worse...they stole from the Dark Lady. These thieves broke into a secure vault and stole four artifacts, items our apothecaries required in certain studies.  Sylvanas would have these artifacts returned. The thieves fled the Undercity to Dalaran, and those wizards quarantined them in the Lordamere Internment Camp.]],logDesc=[[Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill.]]}
DB[545]={id=545,zoneId=267,name=[[Dalaran Patrols]],name_loc=[[Las patrullas de Dalaran]],level=35,minLevel=30,giver=[[Magus Wordeen Voidglare]],giver_loc=[[Magus Wordeen Vacuamirada]],giverType=[[NPC]],giverId=2410,ender=[[Magus Wordeen Voidglare]],ender_loc=[[Magus Wordeen Vacuamirada]],enderType=[[NPC]],enderId=2410,prevId=544,poiX=372,poiY=156,wowhead=[[https://www.wowhead.com/wotlk/quest=545]],image=[[assets/images/quests/placeholder.png]],desc=[[The wizards of Dalaran constructed a vast, magical dome around the heart of their city.  Some believe it was for protection from the violence of these times, while others say they merely wanted solitude, to study and plot. I don't care what the reason was.  I do care that the ruined outskirts of their city may hide valuable magical treasures. But the area is patrolled by the wizards and their elemental slaves. So hunt them, and return when their numbers are sufficiently reduced.]],logDesc=[[Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill.]]}
DB[546]={id=546,zoneId=267,name=[[Souvenirs of Death]],name_loc=[[Recuerdos de muerte]],level=25,minLevel=20,giver=[[Deathguard Samsa]],giver_loc=[[Guardia de la Muerte Samsa]],giverType=[[NPC]],giverId=2418,ender=[[Deathguard Samsa]],ender_loc=[[Guardia de la Muerte Samsa]],enderType=[[NPC]],enderId=2418,poiX=-544,poiY=-121,wowhead=[[https://www.wowhead.com/wotlk/quest=546]],image=[[assets/images/quests/placeholder.png]],desc=[[I hear you were enlisted by Darthalia to wage war on the humans of Hillsbrad.  So jealous I am. . . While you're off having all the fun -- slaying humans, pillaging the town, terrorizing innocent people -- I am stuck standing guard here in Tarren Mill. Perhaps you'll take pity on an old Deathguard like myself?  You see I am collecting human skulls.  And you will be fighting humans for quite some time.  Over the course of your long battle, bring me 30 skulls and I will make it worth your while.]],logDesc=[[Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls.]],rewards={{id=3739,qty=1}}}
DB[547]={id=547,zoneId=267,name=[[Humbert's Sword]],name_loc=[[La espada de Humbert]],level=30,minLevel=26,giver=[[Deathguard Humbert]],giver_loc=[[Guardia de la Muerte Humbert]],giverType=[[NPC]],giverId=2419,ender=[[Deathguard Humbert]],ender_loc=[[Guardia de la Muerte Humbert]],enderType=[[NPC]],enderId=2419,poiX=-1335,poiY=-1263,wowhead=[[https://www.wowhead.com/wotlk/quest=547]],image=[[assets/images/quests/placeholder.png]],desc=[[High Executor Darthalia sent me to keep watch of Dun Garok from a distance.  I had set up camp just out of sight.  But when morning came and I had to boil water, I left to gather firewood. When I returned to camp, I discovered my gear was missing. Apparently some dwarven scouts from Dun Garok had passed by and made off with it.  I need my sword!  If you can get it back for me I would be so grateful.  So many dwarves there...it will be quite difficult to find the dirty little thief who stole it.]],logDesc=[[Retrieve Deathguard Humbert's sword from Dun Garok and return it to him in Tarren Mill.]],choiceRewards={{id=3750,qty=1},{id=3751,qty=1}}}
DB[549]={id=549,zoneId=267,name=[[WANTED: Syndicate Personnel]],name_loc=[[SE BUSCA: Personal de la Hermandad]],level=22,minLevel=17,giver=[[WANTED]],giverType=[[GO]],giverId=1763,ender=[[High Executor Darthalia]],ender_loc=[[Suma ejecutora Darthalia]],enderType=[[NPC]],enderId=2215,poiX=-683,poiY=-1081,wowhead=[[https://www.wowhead.com/wotlk/quest=549]],image=[[assets/images/quests/placeholder.png]],desc=[[By the authority of Lady Sylvanas, all members of the organization known as the Syndicate are wanted dead. Those brought into custody or taken prisoner will be summarily executed. They are currently known to be amassing in the ruins of Durnholde Keep, to the southeast of Tarren Mill. A handsome reward is offered to all who bring proof of their deeds to High Executor Darthalia.]],logDesc=[[Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward.]]}
DB[550]={id=550,zoneId=267,name=[[Battle of Hillsbrad]],name_loc=[[La batalla de Trabalomas]],level=32,minLevel=19,giverType=[[NPC]],enderType=[[NPC]],prevId=541,poiX=1288,poiY=334,wowhead=[[https://www.wowhead.com/wotlk/quest=550]],image=[[assets/images/quests/placeholder.png]],desc=[[Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize. Take this sealed commendation to Bragor Bloodfist in the Undercity.  Go with pride, $c.]],logDesc=[[Take Darthalia's Sealed Commendation to Bragor Bloodfist in the Undercity.]],rewards={{id=3760,qty=1}},choiceRewards={{id=6282,qty=1},{id=3761,qty=1},{id=3822,qty=1}}}
DB[551]={id=551,zoneId=36,name=[[The Ensorcelled Parchment]],name_loc=[[El papiro encantado]],level=40,minLevel=30,giverType=[[NPC]],ender=[[Loremaster Dibbs]],ender_loc=[[Maestro cultural Dibbs]],enderType=[[NPC]],enderId=2277,rewardNextId=554,poiX=-818,poiY=-552,wowhead=[[https://www.wowhead.com/wotlk/quest=551]],image=[[assets/images/quests/placeholder.png]],desc=[[This parchment is enchanted with a spell, rendering it indecipherable.  But one word at the top of the paper can be read:       Nagaz ]],logDesc=[[Take the Ensorcelled Parchment to Loremaster Dibbs at Southshore in Hillsbrad Foothills.]]}
DB[552]={id=552,zoneId=267,name=[[Helcular's Revenge]],name_loc=[[La venganza de Helcular]],level=33,minLevel=29,giver=[[Novice Thaivand]],giver_loc=[[Novicio Thaivand]],giverType=[[NPC]],giverId=2429,ender=[[Novice Thaivand]],ender_loc=[[Novicio Thaivand]],enderType=[[NPC]],enderId=2429,rewardNextId=553,poiX=285,poiY=-449,wowhead=[[https://www.wowhead.com/wotlk/quest=552]],image=[[assets/images/quests/placeholder.png]],desc=[[Master Helcular was almost complete with his transformation into a Lich when a human lynch mob discovered his ritual lair in the hills and brutally killed him.  To make matters worse they buried his corpse in the Southshore cemetery. Such disregard for the great wizard is unacceptable.  As his apprentice I shall see to it that the rains of vengeance fall upon the town of Southshore. We will need Helcular's Rod first.  Yeti overtook his ritual lair.  Undoubtedly one of the beasts has it.]],logDesc=[[Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill.]]}
DB[553]={id=553,zoneId=267,name=[[Helcular's Revenge]],name_loc=[[La venganza de Helcular]],level=33,minLevel=29,giver=[[Novice Thaivand]],giver_loc=[[Novicio Thaivand]],giverType=[[NPC]],giverId=2429,ender=[[Helcular's Grave]],ender_loc=[[Tumba de Helcular]],enderType=[[GO]],enderId=1767,prevId=552,poiX=-199,poiY=-338,wowhead=[[https://www.wowhead.com/wotlk/quest=553]],image=[[assets/images/quests/placeholder.png]],desc=[[Here, take the Rod of Helcular. You will need it. Helcular fashioned 3 ceremonial pyres as part of his most powerful spell.  The Flame of Azel and the Flame of Veraz lie within the Foothill Caverns. The Flame of Uzel lies in a cave above the caverns, further north in the mountains. The Rod of Helcular must be charged from each of the three flames. Once the ritual is complete, drive the rod into Helcular's grave in Southshore, the heavily guarded human town to the south.  Vengeance shall be ours!]],logDesc=[[Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel. Drive the charged rod into Helcular's grave in Southshore.]]}
DB[554]={id=554,zoneId=36,name=[[Stormpike's Deciphering]],name_loc=[[La descodificación de Pico Tormenta]],level=40,minLevel=28,giver=[[Loremaster Dibbs]],giver_loc=[[Maestro cultural Dibbs]],giverType=[[NPC]],giverId=2277,ender=[[Prospector Stormpike]],ender_loc=[[Prospector Pico Tormenta]],enderType=[[NPC]],enderId=1356,prevId=551,poiX=-4631,poiY=-1304,wowhead=[[https://www.wowhead.com/wotlk/quest=554]],image=[[assets/images/quests/placeholder.png]],desc=[[Prospector Stormpike is a master of decryption and deciphering.  If you take the parchment you found to him, then with luck he can make sense of it.  Stormpike is currently studying in the Prospector headquarters in Ironforge. And when you see him tell him you spoke with me - I've been sending him quite a lot of business lately.]],logDesc=[[Take the Ensorcelled Parchment to Prospector Stormpike in Ironforge.]]}
DB[555]={id=555,zoneId=267,name=[[Soothing Turtle Bisque]],name_loc=[[Sopa de tortuga reconfortante]],level=31,minLevel=28,giver=[[Chef Jessen]],giverType=[[NPC]],giverId=2430,ender=[[Chef Jessen]],enderType=[[NPC]],enderId=2430,poiX=-852,poiY=-594,wowhead=[[https://www.wowhead.com/wotlk/quest=555]],image=[[assets/images/quests/placeholder.png]],desc=[[If there's one thing you'll learn about Southshore it's that we have some of the best cuisine north of Stormwind! Take my secret recipe for Turtle Bisque, for example. I've known folks to travel from as far as Darkshire just to enjoy a bowl.  Speaking of which, I haven't been able to make any lately.  I used to head up past Dalaran to Lake Lordamere myself to hunt Snapjaws but it's just too dangerous now. If you bring me some Turtle Meat from the Snapjaws up north, I'll whip some up!]],logDesc=[[Bring 10 pieces of Turtle Meat to Chef Jessen in Southshore.]],rewards={{id=3737,qty=1},{id=3729,qty=3}}}
DB[556]={id=556,zoneId=267,name=[[Stone Tokens]],name_loc=[[Muestras de piedra]],level=32,minLevel=30,giver=[[Keeper Bel'varil]],giver_loc=[[Vigilante Bel'varil]],giverType=[[NPC]],giverId=2437,ender=[[Keeper Bel'varil]],ender_loc=[[Vigilante Bel'varil]],enderType=[[NPC]],enderId=2437,poiX=-69,poiY=189,wowhead=[[https://www.wowhead.com/wotlk/quest=556]],image=[[assets/images/quests/placeholder.png]],desc=[[A notable talent of the wizards of Dalaran is their familiarity with elementals: powerful creatures from other dimensions.  The wizards use magical tokens as a means to control these elementals.  Magus Voidglare would like some of these tokens to study. Enter the territories of the Dalaran wizards, west of Hillsbrad, and gather the tokens. You might find the tokens on any citizen of Dalaran, but I suggest hunting at the internment camp.  It's safer than Dalaran itself.]],logDesc=[[Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill.]]}
DB[557]={id=557,zoneId=267,name=[[Bracers of Binding]],name_loc=[[Brazales de vínculo]],level=34,minLevel=30,giver=[[Keeper Bel'varil]],giver_loc=[[Vigilante Bel'varil]],giverType=[[NPC]],giverId=2437,ender=[[Keeper Bel'varil]],ender_loc=[[Vigilante Bel'varil]],enderType=[[NPC]],enderId=2437,prevId=556,poiX=380,poiY=138,wowhead=[[https://www.wowhead.com/wotlk/quest=557]],image=[[assets/images/quests/placeholder.png]],desc=[[The Magus will be busy studying those stone tokens you gathered, but I know he'll eventually want examples of their counterpart: bracers of binding.  These are set around the wrists of actual elementals, and bind them into the mage's service. Hunt elementals in the ruins of Dalaran and gather their Bracers of Earth Binding, and the Magus will be pleased.]],logDesc=[[Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill.]]}
DB[558]={id=558,name=[[Jaina's Autograph]],name_loc=[[El autógrafo de Jaina]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Human Orphan]],ender_loc=[[Huérfano humano]],enderType=[[NPC]],enderId=14305,prevId=1479,exGroup=-558,wowhead=[[https://www.wowhead.com/wotlk/quest=558]],image=[[assets/images/quests/placeholder.png]],desc=[[They say that Lady Jaina Proudmoore in Theramore is one of the greatest heroes the Alliance has ever had.  When I grow up, I wanna be a hero of the Alliance too! Do you know Jaina, $N?  Could you do me a favor, please?  Could you get her autograph for me?  I dunno how to ask her, and she'd probably be too busy for someone like me... but you!  You're an adventurer just like she is!  I bet she'd give you her autograph easy! Please?]],logDesc=[[Travel to Theramore to see about getting Lady Jaina Proudmoore's autograph for your ward.]]}
DB[559]={id=559,zoneId=267,name=[[Farren's Proof]],name_loc=[[La prueba de Farren]],level=32,minLevel=25,giver=[[Lieutenant Farren Orinelle]],giver_loc=[[Teniente Farren Orinelle]],giverType=[[NPC]],giverId=2228,ender=[[Lieutenant Farren Orinelle]],ender_loc=[[Teniente Farren Orinelle]],enderType=[[NPC]],enderId=2228,prevId=536,rewardNextId=560,poiX=-1151,poiY=-18,wowhead=[[https://www.wowhead.com/wotlk/quest=559]],image=[[assets/images/quests/placeholder.png]],desc=[[Would you believe it, $n? Redpath wasn't satisfied with all the murlocs we killed--oh now, don't be modest, you had some hand in it. Now he wants me to bring proof of the dead, hacking off cold, slimy murloc heads to submit for his approval.]],logDesc=[[Collect 10 Murloc Heads from the murlocs on the Western Strand for Lieutenant Farren Orinelle in Southshore.]]}
DB[560]={id=560,zoneId=267,name=[[Farren's Proof]],name_loc=[[La prueba de Farren]],level=32,minLevel=25,giver=[[Lieutenant Farren Orinelle]],giver_loc=[[Teniente Farren Orinelle]],giverType=[[NPC]],giverId=2228,ender=[[Marshal Redpath]],ender_loc=[[Alguacil Rutagrana]],enderType=[[NPC]],enderId=2263,prevId=559,rewardNextId=561,poiX=-853,poiY=-516,wowhead=[[https://www.wowhead.com/wotlk/quest=560]],image=[[assets/images/quests/placeholder.png]],desc=[[You know, $n, I'd really rather not take these heads... Since you've already got a handle on them, would you mind delivering them to Redpath for me?]],logDesc=[[Deliver the sack of murloc heads to Marshall Redpath in Southshore.]]}
DB[561]={id=561,zoneId=267,name=[[Farren's Proof]],name_loc=[[La prueba de Farren]],level=32,minLevel=25,giver=[[Marshal Redpath]],giver_loc=[[Alguacil Rutagrana]],giverType=[[NPC]],giverId=2263,ender=[[Lieutenant Farren Orinelle]],ender_loc=[[Teniente Farren Orinelle]],enderType=[[NPC]],enderId=2228,prevId=560,rewardNextId=562,poiX=-846,poiY=-580,wowhead=[[https://www.wowhead.com/wotlk/quest=561]],image=[[assets/images/quests/placeholder.png]],desc=[[Please inform Lieutenant Orinelle that I would like him to refocus his efforts on the naga infesting the Eastern Strand. When he has results, tell him to report to me in person.]],logDesc=[[Speak with Lieutenant Farren Orinelle in Southshore.]]}
DB[562]={id=562,zoneId=267,name=[[Stormwind Ho!]],name_loc=[[Cambio de destino]],level=32,minLevel=25,giver=[[Lieutenant Farren Orinelle]],giver_loc=[[Teniente Farren Orinelle]],giverType=[[NPC]],giverId=2228,ender=[[Lieutenant Farren Orinelle]],ender_loc=[[Teniente Farren Orinelle]],enderType=[[NPC]],enderId=2228,prevId=561,rewardNextId=563,poiX=-1195,poiY=-871,wowhead=[[https://www.wowhead.com/wotlk/quest=562]],image=[[assets/images/quests/placeholder.png]],desc=[[My former mentor in the Stormwind city guard sent a message to me that Alliance High Command is becoming concerned with the threat posed by the naga. From what he's heard, there's good chances for promotion--or at least reassignment--for anyone who proves valuable in this regard. There's just one small problem... I can't handle the naga, $n. Oh sure, I could break up a drunken barroom brawl, or haul off a belligerent beggar, but the naga are too much for me. You've got to help me, $n!]],logDesc=[[Kill 10 Daggerspine Shorehunters and 10 Daggerspine Sirens for Lieutenant Farren Orinelle in Southshore.]],rewards={{id=3755,qty=1}}}
DB[563]={id=563,zoneId=267,name=[[Reassignment]],name_loc=[[Nueva asignación]],level=32,minLevel=25,giver=[[Lieutenant Farren Orinelle]],giver_loc=[[Teniente Farren Orinelle]],giverType=[[NPC]],giverId=2228,ender=[[Major Samuelson]],ender_loc=[[Mayor Samuelson]],enderType=[[NPC]],enderId=2439,prevId=562,poiX=-8421,poiY=405,wowhead=[[https://www.wowhead.com/wotlk/quest=563]],image=[[assets/images/quests/placeholder.png]],desc=[[It shouldn't be a problem getting my report seen. The new captain of the guard, Major Samuelson, was my mentor while I was stationed in Stormwind. It should give him more than enough excuse to have me transferred back to the city. I'll need you to carry my report to him, though... wouldn't want ol' Redpath to catch on.]],logDesc=[[Deliver Farren's report to Major Samuelson in Stormwind Keep.]]}
DB[564]={id=564,zoneId=267,name=[[Costly Menace]],name_loc=[[Una amenaza costosa]],level=34,minLevel=30,giver=[[Darren Malvew]],giver_loc=[[Darren Malavista]],giverType=[[NPC]],giverId=2382,ender=[[Darren Malvew]],ender_loc=[[Darren Malavista]],enderType=[[NPC]],enderId=2382,poiX=-115,poiY=-315,wowhead=[[https://www.wowhead.com/wotlk/quest=564]],image=[[assets/images/quests/placeholder.png]],desc=[[Ain't nothin' that irks me more than losin' these here beautiful horses.  And believe me, we've lost quite a few between them pesky undead creeps, the dang Syndicate gang and all the other good-for-nothin' scoundrels pokin' about these parts. But I swear on my ol' grand-daddy's grave there ain't no bigger menace to our horses here than them Mountain Lions up in Alterac.  Always comin' down from the hills and makin' my life difficult! You fancy yourself a hero?  Go and do somethin' about it then!]],logDesc=[[Darren Malvew of Southshore wants you to kill 8 Mountain Lions and 10 Hulking Mountain Lions.]],rewards={{id=3736,qty=1},{id=3728,qty=5}},choiceRewards={{id=3753,qty=1},{id=3754,qty=1}}}
DB[565]={id=565,zoneId=267,name=[[Bartolo's Yeti Fur Cloak]],name_loc=[[Capa de piel de yeti de Bartolo]],level=34,minLevel=29,giver=[[Bartolo Ginsetti]],giverType=[[NPC]],giverId=2438,ender=[[Bartolo Ginsetti]],enderType=[[NPC]],enderId=2438,poiX=-252,poiY=-451,wowhead=[[https://www.wowhead.com/wotlk/quest=565]],image=[[assets/images/quests/placeholder.png]],desc=[[I, the great Bartolo, shall make for you the world famous, Alliance renowned, Yeti Fur Cloak! Travel the planet and find yourself a better cloak, I dare you.  Oh wait, what is that, little $r?  "Bartolo, there is no finer cloak!"  Yes, yes!  That, I have heard before. Bartolo requires a Bolt of Wool, a Hillman's Cloak made by a skilled leatherworker, Fine Thread and Yeti Fur, of course!  Bring to me these items and you shall be a happy customer!]],logDesc=[[Bring Bartolo Ginsetti of Southshore a Bolt of Wool, a Hillman's Cloak, Fine Thread and 10 clumps of Yeti Fur.]],rewards={{id=2805,qty=1}}}
DB[566]={id=566,zoneId=267,name=[[WANTED: Baron Vardus]],name_loc=[[SE BUSCA: Barón Vardus]],level=40,minLevel=17,giver=[[WANTED]],giverType=[[GO]],giverId=1763,ender=[[High Executor Darthalia]],ender_loc=[[Suma ejecutora Darthalia]],enderType=[[NPC]],enderId=2215,poiX=-33,poiY=-928,wowhead=[[https://www.wowhead.com/wotlk/quest=566]],image=[[assets/images/quests/placeholder.png]],desc=[[By order of High Executor Darthalia, the human known as Baron Vardus is wanted for crimes against the Forsaken. Vardus is known to be a high-ranking member of the organization known as the Syndicate. He was last spotted in the Uplands in the Alterac Mountains, north of Tarren Mill. He is wanted dead. Bring evidence of his demise to High Executor Darthalia to claim the reward.]],logDesc=[[Kill Baron Vardus and deliver his head to High Executor Darthalia in Tarren Mill.]],rewards={{id=2231,qty=1}}}
DB[567]={id=567,zoneId=267,name=[[Dangerous!]],name_loc=[[¡Peligrosos!]],level=28,minLevel=17,giver=[[Dangerous!]],giverType=[[GO]],giverId=2008,ender=[[High Executor Darthalia]],ender_loc=[[Suma ejecutora Darthalia]],enderType=[[NPC]],enderId=2215,poiX=-505,poiY=122,wowhead=[[https://www.wowhead.com/wotlk/quest=567]],image=[[assets/images/quests/placeholder.png]],desc=[[Dangerous! The following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia: Clerk Horrace Whitesteed.  Wanted for the murder of Deathguard Toma. Citizen Wilkes.  Wanted for the murder of Apothecary Eli. Miner Hackett.  Wanted for the murder of Deathstalker Fry. Farmer Kalaba.  Wanted for the ambush of supplies from the Undercity. All of these enemies are hiding and will be hard to find.  A reward will be granted upon notice of their death.]],logDesc=[[High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.]],rewards={{id=3732,qty=1}},choiceRewards={{id=3742,qty=1},{id=3743,qty=1},{id=5250,qty=1}}}
DB[568]={id=568,zoneId=33,name=[[The Defense of Grom'gol]],name_loc=[[La defensa de Grom'gol]],level=36,minLevel=33,giver=[[Commander Aggro'gosh]],giver_loc=[[Comandante Aggro'gosh]],giverType=[[NPC]],giverId=2464,ender=[[Commander Aggro'gosh]],ender_loc=[[Comandante Aggro'gosh]],enderType=[[NPC]],enderId=2464,rewardNextId=569,poiX=-12396,poiY=168,wowhead=[[https://www.wowhead.com/wotlk/quest=568]],image=[[assets/images/quests/placeholder.png]],desc=[[Throm'ka, $c! Your arrival at Grom'gol is timely, indeed.  As commander of the Warchief's base camp here in the jungle I am bound by honor to ensure the safety of all members of the Horde.  Our mission to provide a safe chain of supply to Stonard is being hampered by some of the local inhabitants. I am putting you in charge of thinning out the raptor population outside of Grom'gol.  Once you have made significant progress, report back to me for reassignment.]],logDesc=[[Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors.]]}
DB[569]={id=569,zoneId=33,name=[[The Defense of Grom'gol]],name_loc=[[La defensa de Grom'gol]],level=37,minLevel=33,giver=[[Commander Aggro'gosh]],giver_loc=[[Comandante Aggro'gosh]],giverType=[[NPC]],giverId=2464,ender=[[Commander Aggro'gosh]],ender_loc=[[Comandante Aggro'gosh]],enderType=[[NPC]],enderId=2464,prevId=568,poiX=-12447,poiY=-214,wowhead=[[https://www.wowhead.com/wotlk/quest=569]],image=[[assets/images/quests/placeholder.png]],desc=[[When we first arrived in this jungle we did not intend to wage war on the local tribes.  Our mission to supply Stonard is of the highest priority.  But complications have arisen.  A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol.  Despite warnings, they continue to ambush our supply caravans. I am putting you in charge of dealing with these uncooperative ogres. Travel to the ruins and attempt to drive them from the area.  At the very least it will send a firm message.]],logDesc=[[Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors.]],rewards={{id=4115,qty=1}}}
DB[570]={id=570,zoneId=33,name=[[Mok'thardin's Enchantment]],name_loc=[[El encantamiento de Mok'thardin]],level=38,minLevel=33,giver=[[Far Seer Mok'thardin]],giver_loc=[[Clarividente Mok'thardin]],giverType=[[NPC]],giverId=2465,ender=[[Far Seer Mok'thardin]],ender_loc=[[Clarividente Mok'thardin]],enderType=[[NPC]],enderId=2465,rewardNextId=572,poiX=-13548,poiY=-121,wowhead=[[https://www.wowhead.com/wotlk/quest=570]],image=[[assets/images/quests/placeholder.png]],desc=[[The power of the jungle's magic must be realized and then harnessed by the Horde.  My rituals have proven successful so far.  I can cast very powerful enchantments.  For you, brave $c, I shall make a special item indeed. Bring to me some Shadowmaw Panther claws along with a Tigress fang.  Not just any fang will do.  It must be in pristine condition. The beasts lurk throughout the jungle but you will find some close by, just across the river from Mizjah Ruins to the southeast.]],logDesc=[[Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang.]]}
DB[571]={id=571,zoneId=33,name=[[Mok'thardin's Enchantment]],name_loc=[[El encantamiento de Mok'thardin]],level=41,minLevel=33,giver=[[Far Seer Mok'thardin]],giver_loc=[[Clarividente Mok'thardin]],giverType=[[NPC]],giverId=2465,ender=[[Far Seer Mok'thardin]],ender_loc=[[Clarividente Mok'thardin]],enderType=[[NPC]],enderId=2465,prevId=572,rewardNextId=573,poiX=-13910,poiY=-16,wowhead=[[https://www.wowhead.com/wotlk/quest=571]],image=[[assets/images/quests/placeholder.png]],desc=[[What I need from you now will be very difficult to obtain. To hold all these feathers, claws and the pristine fang in place I require a magical tether.  Only an aged gorilla sinew will work. You will only be able to find one on an Elder Mistvale Gorilla.  They are known to forage to the east of Booty Bay. The sinew must be perfect.  It might take quite a few kills for you to find exactly what I need but it will be well worth the hunt.]],logDesc=[[Bring an Aged Gorilla Sinew to Far Seer Mok'thardin in Grom'gol.]]}
DB[572]={id=572,zoneId=33,name=[[Mok'thardin's Enchantment]],name_loc=[[El encantamiento de Mok'thardin]],level=41,minLevel=33,giver=[[Far Seer Mok'thardin]],giver_loc=[[Clarividente Mok'thardin]],giverType=[[NPC]],giverId=2465,ender=[[Far Seer Mok'thardin]],ender_loc=[[Clarividente Mok'thardin]],enderType=[[NPC]],enderId=2465,prevId=570,rewardNextId=571,poiX=-12882,poiY=18,wowhead=[[https://www.wowhead.com/wotlk/quest=572]],image=[[assets/images/quests/placeholder.png]],desc=[[The items you gathered from the feline beasts of the Vale are only the first requirement for a powerful enchanted item.  These jungle trinkets combined with my shamanistic ritual will provide you with a very useful tool in assisting the Horde and the Warchief. But now you must gather for me some Jungle Stalker Feathers.  The feathers are traditionally worn by the beasts on their armbands.  You will find a tribe of the raptors directly south of Grom'gol, not far from the great arena.]],logDesc=[[Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp.]]}
DB[573]={id=573,zoneId=33,name=[[Mok'thardin's Enchantment]],name_loc=[[El encantamiento de Mok'thardin]],level=44,minLevel=33,giver=[[Far Seer Mok'thardin]],giver_loc=[[Clarividente Mok'thardin]],giverType=[[NPC]],giverId=2465,ender=[[Far Seer Mok'thardin]],ender_loc=[[Clarividente Mok'thardin]],enderType=[[NPC]],enderId=2465,prevId=571,poiX=-13909,poiY=420,wowhead=[[https://www.wowhead.com/wotlk/quest=573]],image=[[assets/images/quests/placeholder.png]],desc=[[There is but one final reagent needed to complete the enchantment. In the south, towards the western coast, high above the bluffs, lies a Holy Spring.  This spring is the subject of great conflict amongst religious and mystical scholars.  Every race in Azeroth claims that the spring waters were made divine for their people. My final request of you: bring to me Holy Spring Water.  Be warned.  An expedition of naga explorers have advanced upon the spring.  They will need to be dealt with as well.]],logDesc=[[Far Seer Mok'thardin of Grom'gol needs Holy Spring Water.  He also wants you to kill 10 Naga Explorers.]],rewards={{id=4112,qty=1}}}
DB[574]={id=574,zoneId=33,name=[[Special Forces]],name_loc=[[Fuerzas especiales]],level=38,minLevel=30,giver=[[Sergeant Yohwa]],giver_loc=[[Sargento Yohwa]],giverType=[[NPC]],giverId=733,ender=[[Lieutenant Doren]],ender_loc=[[Teniente Doren]],enderType=[[NPC]],enderId=469,rewardNextId=202,poiX=-11297,poiY=-207,wowhead=[[https://www.wowhead.com/wotlk/quest=574]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that many of his regular troops are reduced, you must face his highly trained forces.  When they're not in the wilderness slaughtering our rebel soldiers, they are found deep in the back of the Kurzen Compound, in a cave they call the Stockpile. I know many of Kurzen's troops personally, and I know they are skilled, loyal, and cruel.  This is no easy task I set before you, $N. After you defeat them, report to Lieutenant Doren, my commanding officer.  He will want your report firsthand.]],logDesc=[[Kill 10 Kurzen Commandoes and 6 Kurzen Headshrinkers. Report to Lieutenant Doren at the Rebel Camp.]]}
DB[575]={id=575,zoneId=33,name=[[Supply and Demand]],name_loc=[[La oferta y la demanda]],level=31,minLevel=26,giver=[[Drizzlik]],giverType=[[NPC]],giverId=2495,ender=[[Drizzlik]],enderType=[[NPC]],enderId=2495,poiX=-11751,poiY=-394,wowhead=[[https://www.wowhead.com/wotlk/quest=575]],image=[[assets/images/quests/placeholder.png]],desc=[["The finest leathercrafter of the South Seas and the worlds old and new." That's what they call me. Me! Drizzlik! The finest lea... Ahem. Well. My leather goods are known far and wide as the most exquisite, a connoisseur's choice! I've just received an order from Director Riddlevox of the Tinkers' Union for a dozen of his favorite Excelsior-line boots. Our best sellers, actually. To start on the basic shape, I'll need crocolisk skins from the crocs along the river in northern Stranglethorn.]],logDesc=[[Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay.]]}
DB[576]={id=576,zoneId=33,name=[[Keep An Eye Out]],name_loc=[[¡Ojo!]],level=42,minLevel=37,giver=[[Dizzy One-Eye]],giver_loc=[[Dizzy el Tuerto]],giverType=[[NPC]],giverId=2493,ender=[[Dizzy One-Eye]],ender_loc=[[Dizzy el Tuerto]],enderType=[[NPC]],enderId=2493,prevId=595,poiX=-14834,poiY=61,wowhead=[[https://www.wowhead.com/wotlk/quest=576]],image=[[assets/images/quests/placeholder.png]],desc=[[Avast!  Who goes there? Argh, I am but useless without me special enchanted eye.  Bad enough to have lost me eyes in battle in the first place!  But by some stroke o' luck we docked in Menethil and a traveling wizard enchanted a special glass eye that let me see again. Last night I ended up gettin' jumped by some Bloodsail Buccaneers on me way out.  Took me eye, they did!  Seems those blokes have found their way to Booty Bay. Help an old sea dog out by gettin' me eye back?]],logDesc=[[Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers.]],rewards={{id=4114,qty=1}}}
DB[577]={id=577,zoneId=33,name=[[Some Assembly Required]],name_loc=[[Hay que ensamblar]],level=36,minLevel=31,giver=[[Drizzlik]],giverType=[[NPC]],giverId=2495,ender=[[Drizzlik]],enderType=[[NPC]],enderId=2495,prevId=575,rewardNextId=628,poiX=-11876,poiY=-487,wowhead=[[https://www.wowhead.com/wotlk/quest=577]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, I've got the basic shape of the boots worked out, and they're coming along fine, but the skins you brought aren't going to be quite enough for the inner layers. "What are we going to do, Drizzlik?" No doubt the question on your lips, and well, isn't it lucky you're talking to Drizzlik, because he's going to tell you what we're going to do! The inner layers will never really be seen, so we'll just get some of the thicker, cheaper skins from the crocs around Lake Nazferiti to fill the boots out.]],logDesc=[[Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay.]]}
DB[578]={id=578,zoneId=33,name=[[The Stone of the Tides]],name_loc=[[La piedra de las mareas]],level=37,minLevel=32,giver=[[Baron Revilgaz]],giver_loc=[[Barón Revilgaz]],giverType=[[NPC]],giverId=2496,ender=[[Baron Revilgaz]],ender_loc=[[Barón Revilgaz]],enderType=[[NPC]],enderId=2496,prevId=616,rewardNextId=601,poiX=-12154,poiY=828,wowhead=[[https://www.wowhead.com/wotlk/quest=578]],image=[[assets/images/quests/placeholder.png]],desc=[[If there is indeed a goblin mage and water elementals haunting the island, it could mean the Stone of the Tides can be mine! I want you to locate this haunted island... find out what's going on. Oh, and if you perhaps want to find out more about the Stone of the Tides, take this scrip to the Stormwind Library, they should be able to find you a copy of the book I first came across the legend in. Could it be that Gazban actually discovered the Stone...?]],logDesc=[[Find the haunted island for Baron Revilgaz in Booty Bay.]]}
DB[579]={id=579,zoneId=1519,name=[[Stormwind Library]],name_loc=[[La biblioteca de Ventormenta]],level=1,minLevel=1,giver=[[Donyal Tovald]],giver_loc=[[Donyal Tovald]],giverType=[[NPC]],giverId=2504,ender=[[Donyal Tovald]],ender_loc=[[Donyal Tovald]],enderType=[[NPC]],enderId=2504,poiX=-8345,poiY=419,wowhead=[[https://www.wowhead.com/wotlk/quest=579]],image=[[assets/images/quests/placeholder.png]],choiceRewards={{id=2154,qty=1},{id=3899,qty=1}}}
DB[580]={id=580,zoneId=33,name=[[Whiskey Slim's Lost Grog]],name_loc=[[El grog de Whiskey el Delgado]],level=50,minLevel=40,giver=[[Whiskey Slim]],giver_loc=[[Whiskey el Delgado]],giverType=[[NPC]],giverId=2491,ender=[[Whiskey Slim]],ender_loc=[[Whiskey el Delgado]],enderType=[[NPC]],enderId=2491,poiX=-338,poiY=-4634,wowhead=[[https://www.wowhead.com/wotlk/quest=580]],image=[[assets/images/quests/placeholder.png]],desc=[[We was splicin' the mainbrace somethin' fierce off of the Overlook Cliffs, ol' Hinterlands just in the distance.  Thought the seas was goin' to swallow us whole. Ol' Slim knows all about liquid courage!  Cap'n had a crate of Pupellyverbos Port we commandeered from a privateer en route to Stormwind. So when that storm off of Hinterlands hit, I busted into the grog.  Big wave hit and tossed them bottles overboard.  Cap'n is goin' to give me a taste o' the cat if ye don't help me get 'em back though!]],logDesc=[[Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost.]],rewards={{id=17048,qty=5}}}
DB[581]={id=581,zoneId=33,name=[[Hunt for Yenniku]],name_loc=[[Caza para Yenniku]],level=34,minLevel=30,giver=[[Nimboya]],giverType=[[NPC]],giverId=2497,ender=[[Nimboya]],enderType=[[NPC]],enderId=2497,rewardNextId=582,poiX=-11850,poiY=15,wowhead=[[https://www.wowhead.com/wotlk/quest=581]],image=[[assets/images/quests/placeholder.png]],desc=[[A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son. And I believe the Bloodscalp tribe has him. If you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me.]],logDesc=[[Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.]]}
DB[582]={id=582,zoneId=33,name=[[Headhunting]],name_loc=[[Caza cabezas]],level=37,minLevel=30,giver=[[Nimboya]],giverType=[[NPC]],giverId=2497,ender=[[Nimboya]],enderType=[[NPC]],enderId=2497,prevId=581,poiX=-11587,poiY=642,wowhead=[[https://www.wowhead.com/wotlk/quest=582]],image=[[assets/images/quests/placeholder.png]],desc=[[We must find if Yenniku is dead. Slay the Bloodscalp Headhunters and take from them their Shrunken Heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them. And if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan'zulah! Go, $N.  You may find many Headhunters at the ruins of Zuuldaia and Zul'Kunda, along the coast to the north.]],logDesc=[[Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.]],choiceRewards={{id=4133,qty=1},{id=4132,qty=1}}}
DB[583]={id=583,zoneId=33,name=[[Welcome to the Jungle]],name_loc=[[Bienvenido a la jungla]],level=30,minLevel=28,giver=[[Barnil Stonepot]],giver_loc=[[Barnil Jarropetra]],giverType=[[NPC]],giverId=716,ender=[[Hemet Nesingwary Jr.]],ender_loc=[[Hemet Decautela]],enderType=[[NPC]],enderId=715,poiX=-11629,poiY=-55,wowhead=[[https://www.wowhead.com/wotlk/quest=583]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome to Stranglethorn! Perhaps you're not aware of this, but that dwarf over there is the son of the one and only Hemet Nesingwary, renowned war hero of the Alliance and master big game hunter.  Like his father, he's not one for welcoming strangers into his camp, but you look like you've seen quite a bit of action in your day, $c. Go and speak with him.  He's a chip off the old block, so perhaps he can give you some hunting pointers.]],logDesc=[[Speak with Hemet Nesingwary Jr.]]}
DB[584]={id=584,zoneId=33,name=[[Bloodscalp Clan Heads]],name_loc=[[Las cabezas de los Sangrapellejo]],level=41,minLevel=30,giver=[[Nimboya]],giverType=[[NPC]],giverId=2497,ender=[[Bubbling Cauldron]],ender_loc=[[Caldera burbujeante]],enderType=[[GO]],enderId=2076,prevId=582,poiX=-11514,poiY=725,wowhead=[[https://www.wowhead.com/wotlk/quest=584]],image=[[assets/images/quests/placeholder.png]],desc=[[Yenniku was not among the heads, and I thank the Great Serpent for it.  But we are no closer to finding him. We must know the truth, and I fear that only the Bloodscalp chief and his witchdoctor know it.  They are the enemies of the Darkspear tribe and will not speak freely, so we must force the truth from their dead lips! Bring me the heads of Gan'zulah and Nezzliok the Dire and place them within this cauldron. They are deep within Zul'Kunda.  Bring their heads...we will then make them talk.]],logDesc=[[Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp.]]}
DB[585]={id=585,zoneId=33,name=[[Speaking with Nezzliok]],name_loc=[[Hablando con Nezzliok]],level=40,minLevel=30,giver=[[Bubbling Cauldron]],giver_loc=[[Caldera burbujeante]],giverType=[[GO]],giverId=2076,ender=[[Bubbling Cauldron]],ender_loc=[[Caldera burbujeante]],enderType=[[GO]],enderId=2076,prevId=584,nextId=588,exGroup=-585,poiX=-12544,poiY=-723,wowhead=[[https://www.wowhead.com/wotlk/quest=585]],image=[[assets/images/quests/placeholder.png]],desc=[[<The head of Nezzliok speaks.> It is true.  I know where the child of the Darkspears was taken.  You have bested me and bound my spirit, but I will say nothing without appeasement! The Bloodscalps war with the Skullsplitters.  To gain my favor, steal from the Skullsplitters 3 of their trophy skulls and place them here with us, so that my spirit will have slaves in the Nether.  One skull must be from their trophy pile in Balia'mah, another from Ziata'jai, and the last from Zul'Mamwe.]],logDesc=[[Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp.]]}
DB[586]={id=586,zoneId=33,name=[[Speaking with Gan'zulah]],name_loc=[[Hablando con Gan'zulah]],level=46,minLevel=30,giver=[[Bubbling Cauldron]],giver_loc=[[Caldera burbujeante]],giverType=[[GO]],giverId=2076,ender=[[Bubbling Cauldron]],ender_loc=[[Caldera burbujeante]],enderType=[[GO]],enderId=2076,prevId=584,nextId=588,exGroup=-585,poiX=-12818,poiY=-737,wowhead=[[https://www.wowhead.com/wotlk/quest=586]],image=[[assets/images/quests/placeholder.png]],desc=[[<The head of Gan'zulah speaks.> Curse you!  And curse your ancestors!! Only blood and revenge can cool my rage, so if that is your wish, then... do this: Throw yourself into the heart of the Skullsplitters to the east.  Slay the fiercest among them, and if you survive...then break yourself against their chief, Ana'thek the Cruel.  Hah!  Bring me his shattered armor if you can! May he tear off your limbs and leave you to rot and be eaten by carrion.]],logDesc=[[Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers. Bring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp.]]}
DB[587]={id=587,zoneId=33,name=[[Up to Snuff]],name_loc=[[Tabaco rapé]],level=41,minLevel=37,giver=[[Deeg]],giver_loc=[[Deeg]],giverType=[[NPC]],giverId=2488,ender=[[Deeg]],ender_loc=[[Deeg]],enderType=[[NPC]],enderId=2488,prevId=595,poiX=-14834,poiY=61,wowhead=[[https://www.wowhead.com/wotlk/quest=587]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, the sea life.  I ain't gonna say it's the good life, but it's my life. When I get into port I like to find me a good bottle of grog and some high quality snuff.  Nasty habits but what's a pirate without his vices, right? So you can imagine how heartbroken I was to find out the herbalist here in town has gone and sold out of the stuff.  Says his shipment got hijacked by those damned Bloodsail Raiders. I bet a fearless $c like you could convince 'em to share the goods, eh?]],logDesc=[[Deeg in Booty Bay wants you to bring him 15 shares of Snuff.]]}
DB[588]={id=588,zoneId=33,name=[[The Fate of Yenniku]],name_loc=[[El destino de Yenniku]],level=45,minLevel=30,giver=[[Bubbling Cauldron]],giver_loc=[[Caldera burbujeante]],giverType=[[GO]],giverId=2076,ender=[[Kin'weelay]],enderType=[[NPC]],enderId=2519,rewardNextId=589,poiX=-12347,poiY=161,wowhead=[[https://www.wowhead.com/wotlk/quest=588]],image=[[assets/images/quests/placeholder.png]],desc=[[<Nezzliok speaks.> You have appeased myself and my chief, so I will tell you that which you seek to discover... Young Yenniku is lost to his clan. He was taken by the witchdoctor Zanzil the Outcast.  Now Zanzil controls him, body and soul, and only the most potent magic could set him free. A magic that you do not have, $c. Perhaps your Darkspear allies can offer a hope of Yenniku's salvation.  But that, I doubt.]],logDesc=[[Speak with Kin'weelay.]]}
DB[589]={id=589,zoneId=33,name=[[The Singing Crystals]],name_loc=[[Los cristales canto]],level=45,minLevel=30,giver=[[Kin'weelay]],giverType=[[NPC]],giverId=2519,ender=[[Kin'weelay]],enderType=[[NPC]],enderId=2519,prevId=588,rewardNextId=591,poiX=-13203,poiY=-599,wowhead=[[https://www.wowhead.com/wotlk/quest=589]],image=[[assets/images/quests/placeholder.png]],desc=[[Legends tell of a jewel, hidden deep in the heart of Stranglethorn.  We call it the Mind's Eye, and it has great powers.  If you gain this Eye then, perhaps, we can use it to bring lost Yenniku back from the darkness. I will consult with the spirits of the jungle to find the Mind's Eye.  While I do this, you enter the Crystalvein Mine, southeast of here, and gather Pulsing Blue Shards from Ironjaw Basilisks.  The shards are rare, but we will need their magic to bend the Mind's Eye to our will.]],logDesc=[[Bring 3 Pulsing Blue Shards to Kin'weelay at the Grom'gol Base Camp.]]}
DB[590]={id=590,zoneId=154,name=[[A Rogue's Deal]],name_loc=[[Un trato de pícaro]],level=5,minLevel=1,giver=[[Calvin Montague]],giver_loc=[[Calvin Montesco]],giverType=[[NPC]],giverId=6784,ender=[[Calvin Montague]],ender_loc=[[Calvin Montesco]],enderType=[[NPC]],enderId=6784,prevId=8,poiX=2127,poiY=1305,wowhead=[[https://www.wowhead.com/wotlk/quest=590]],image=[[assets/images/quests/placeholder.png]],desc=[[What? What?! You want money? I don't owe you any money. Letter? What letter? Oh, you wanna fight then? All right, mate... let's do this! Owe you any money...]],logDesc=[[Defeat Calvin Montague in Deathknell.]]}
DB[591]={id=591,zoneId=33,name=[[The Mind's Eye]],name_loc=[[El Ojo de la mente]],level=46,minLevel=30,giver=[[Kin'weelay]],giverType=[[NPC]],giverId=2519,ender=[[Kin'weelay]],enderType=[[NPC]],enderId=2519,prevId=589,poiX=-12343,poiY=-1157,wowhead=[[https://www.wowhead.com/wotlk/quest=591]],image=[[assets/images/quests/placeholder.png]],desc=[[The Mind's Eye is held by an ogre mage, east of here and deep within the Mosh'Ogg ogre mound.  His name is Mai'Zoth.  I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong. And if he has the Mind's Eye, then his magic will be stronger still. You must face Mai'Zoth and wrest from him the Mind's Eye.  It is a perilous task, but it is the only hope we have of saving Yenniku.]],logDesc=[[Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp.]]}
DB[592]={id=592,zoneId=33,name=[[Saving Yenniku]],name_loc=[[Salvar a Yenniku]],level=46,minLevel=30,giver=[[Kin'weelay]],giverType=[[NPC]],giverId=2519,ender=[[Nimboya]],enderType=[[NPC]],enderId=2497,prevId=591,poiX=-12348,poiY=169,wowhead=[[https://www.wowhead.com/wotlk/quest=592]],image=[[assets/images/quests/placeholder.png]],desc=[[I have reshaped the Mind's Eye into a Soul Gem.  Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul. Then, bring the gem to Nimboya. Yenniku dwells with Zanzil the Outcast, at the Ruins of Aboraz, along the Crystal Shore on the distant Cape of Stranglethorn.]],logDesc=[[Bring the Filled Soul Gem to Nimboya.]],choiceRewards={{id=4134,qty=1},{id=6723,qty=1}}}
DB[593]={id=593,zoneId=33,name=[[Filling the Soul Gem]],name_loc=[[Llenando la Gema de alma]],level=46,minLevel=1,giver=[[Yenniku]],giverType=[[NPC]],giverId=2530,ender=[[Yenniku]],enderType=[[NPC]],enderId=2530,prevId=-592,poiX=-13650,poiY=-270,wowhead=[[https://www.wowhead.com/wotlk/quest=593]],image=[[assets/images/quests/placeholder.png]],rewards={{id=3913,qty=1}}}
DB[594]={id=594,zoneId=33,name=[[Message in a Bottle]],name_loc=[[Mensaje en una botella]],level=42,minLevel=42,giverType=[[NPC]],ender=[[Princess Poobah]],ender_loc=[[Princesa Poobah]],enderType=[[NPC]],enderId=2634,rewardNextId=630,poiX=-14597,poiY=-238,wowhead=[[https://www.wowhead.com/wotlk/quest=594]],image=[[assets/images/quests/placeholder.png]],desc=[[The note reads, in fairly good handwriting: To any that can aid me- Please, my need for help is dire. A great Skymane holds me captive on an island in the South Seas. The stars at night are foreign to me and obscured by the jungle trees, but on the clearest days I see Wild Shore to the northwest, and what seem to be large sailing ships to the southwest. I beg of you, my would-be savior, please help me.]],logDesc=[[Find the author of the message in a bottle.]]}
DB[595]={id=595,zoneId=33,name=[[The Bloodsail Buccaneers]],name_loc=[[Bucaneros Velasangre]],level=41,minLevel=37,giver=[[First Mate Crazz]],giver_loc=[[Contramaestre Crazz]],giverType=[[NPC]],giverId=2490,ender=[[Bloodsail Correspondence]],ender_loc=[[Correspondencia de los Velasangre]],enderType=[[GO]],enderId=2083,rewardNextId=597,poiX=-14126,poiY=480,wowhead=[[https://www.wowhead.com/wotlk/quest=595]],image=[[assets/images/quests/placeholder.png]],desc=[[You sure seem eager to work, matey.  Not sure why some land-loving $r $c is offering help to the Blackwater Raiders, but I'm not going to turn you away. Our ship just docked here in Booty Bay and word has it that our rivals--those damned, dirty Bloodsail Buccaneers--have been spotted all over southern Stranglethorn. All the boys are too busy hitting the grog and looking for ladies!  What I need is a scout. Check the cove just north of Booty Bay along the Savage Coast and see what you find.]],logDesc=[[First Mate Crazz wants you to check the cove north of Booty Bay.]]}
DB[596]={id=596,zoneId=33,name=[[Bloody Bone Necklaces]],name_loc=[[Collares de huesos sangrientos]],level=37,minLevel=30,giver=[[Kin'weelay]],giverType=[[NPC]],giverId=2519,ender=[[Kin'weelay]],enderType=[[NPC]],enderId=2519,poiX=-11850,poiY=15,wowhead=[[https://www.wowhead.com/wotlk/quest=596]],image=[[assets/images/quests/placeholder.png]],desc=[[I was sent to Grom'gol  to aid Nimboya on his quest, but... I too have reasons for being here. The Bloodscalp tribe is enemy to our tribe.  Collecting trophies of our enemies gives us power over them.  You may aid our tribe by hunting our enemies. They dwell to the north.  Slay Bloodscalp trolls and take from them their bloody bone necklaces.  Collect many, and your reward will be great.]],logDesc=[[Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp.]],rewards={{id=4135,qty=1}}}
DB[597]={id=597,zoneId=33,name=[[The Bloodsail Buccaneers]],name_loc=[[Bucaneros Velasangre]],level=41,minLevel=37,giver=[[Bloodsail Correspondence]],giver_loc=[[Correspondencia de los Velasangre]],giverType=[[GO]],giverId=2083,ender=[[First Mate Crazz]],ender_loc=[[Contramaestre Crazz]],enderType=[[NPC]],enderId=2490,prevId=595,rewardNextId=599,poiX=-14411,poiY=428,wowhead=[[https://www.wowhead.com/wotlk/quest=597]],image=[[assets/images/quests/placeholder.png]],desc=[[The map shows Booty Bay with a red "X" drawn precisely at the spot at which you are standing. The scribbled text reads: "You men are to secure a camp at this location and keep quiet.  Wait for the signal from the southern command post before attacking.  If anyone approaches you, kill them."]],logDesc=[[Report your findings to First Mate Crazz in Booty Bay.]]}
DB[598]={id=598,zoneId=33,name=[[Split Bone Necklace]],name_loc=[[Collar de hueso partido]],level=42,minLevel=30,giver=[[Kin'weelay]],giverType=[[NPC]],giverId=2519,ender=[[Kin'weelay]],enderType=[[NPC]],enderId=2519,prevId=596,poiX=-12878,poiY=-884,wowhead=[[https://www.wowhead.com/wotlk/quest=598]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you have gathered Bloodscalp trophies, I have another task for you.  The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them.  Although the Darkspears no longer dwell in Stranglethorn, we are bound to our conflict with the Skullsplitters. So, hunt them.  Gather their Split Bone Necklaces and return to me.  Aid us in our war, and you will earn the friendship of the Darkspears.]],logDesc=[[Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp.]],choiceRewards={{id=4137,qty=1},{id=4136,qty=1}}}
DB[599]={id=599,zoneId=33,name=[[The Bloodsail Buccaneers]],name_loc=[[Bucaneros Velasangre]],level=41,minLevel=37,giver=[[First Mate Crazz]],giver_loc=[[Contramaestre Crazz]],giverType=[[NPC]],giverId=2490,ender=[[Fleet Master Seahorn]],ender_loc=[[Maestro de flota Cuernomarino]],enderType=[[NPC]],enderId=2487,prevId=597,rewardNextId=604,poiX=-14445,poiY=487,wowhead=[[https://www.wowhead.com/wotlk/quest=599]],image=[[assets/images/quests/placeholder.png]],desc=[[Shiver me timbers!  So the Bloodsail Buccaneers are planning some sort of attack on Booty Bay?  Why, the nerve of those scoundrels.  Booty Bay will always be run by the Blackwater Raiders! This is bigger than I thought.  Report what you have learned to Fleet Master Seahorn at once!  The ol' sea dog is around town somewhere....]],logDesc=[[Report the planned Bloodsail attack to Fleet Master Seahorn.]]}
DB[600]={id=600,zoneId=33,name=[[Venture Company Mining]],name_loc=[[La minería de Ventura y Cía.]],level=41,minLevel=30,giver=[[Crank Fizzlebub]],giver_loc=[[Loquillo Pinchabujas]],giverType=[[NPC]],giverId=2498,ender=[[Crank Fizzlebub]],ender_loc=[[Loquillo Pinchabujas]],enderType=[[NPC]],enderId=2498,prevId=605,poiX=-12930,poiY=-484,wowhead=[[https://www.wowhead.com/wotlk/quest=600]],image=[[assets/images/quests/placeholder.png]],desc=[[The Venture Company has a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold!  Please, you must help me! The Venture Company is mining near the Crystalvein Mine to the north.  They can't get into the mine because of all the basilisks, but they're still able to dig up Singing Crystals from the surrounding hills. Take their crystals from them, and show them they don't have the run of the jungle. And... um... bring me those crystals as proof!]],logDesc=[[Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay.]],choiceRewards={{id=5253,qty=1},{id=4128,qty=1}}}
DB[601]={id=601,zoneId=33,name=[[Water Elementals]],name_loc=[[Elementales de agua]],level=37,minLevel=32,giver=[[Baron Revilgaz]],giver_loc=[[Barón Revilgaz]],giverType=[[NPC]],giverId=2496,ender=[[Baron Revilgaz]],ender_loc=[[Barón Revilgaz]],enderType=[[NPC]],enderId=2496,prevId=578,rewardNextId=602,poiX=-12152,poiY=783,wowhead=[[https://www.wowhead.com/wotlk/quest=601]],image=[[assets/images/quests/placeholder.png]],desc=[[The water elementals were no doubt summoned by Gazban, the goblin wizard rumored to have discovered the Stone of the Tides. As you may know, the Stone of the Tides curses its bearer, causing him to fade in and out of existence... Perhaps we can find a way to counteract the curse. We can have a mage of Dalaran analyze the magical residue of one of the water elemental's bracers. I need you to go back to the island and retrieve a few specimens.]],logDesc=[[Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.]]}
DB[602]={id=602,zoneId=33,name=[[Magical Analysis]],name_loc=[[Análisis mágico]],level=37,minLevel=32,giver=[[Baron Revilgaz]],giver_loc=[[Barón Revilgaz]],giverType=[[NPC]],giverId=2496,ender=[[Archmage Ansirem Runeweaver]],ender_loc=[[Archimago Ansirem Tejerruna]],enderType=[[NPC]],enderId=2543,prevId=601,poiX=35,poiY=256,wowhead=[[https://www.wowhead.com/wotlk/quest=602]],image=[[assets/images/quests/placeholder.png]],desc=[[From what I've heard, the mages of Dalaran have succeeded in rebuilding their magical city and moving it to Northrend, leaving behind a massive crater.  Some mages remained here though, who should spare some time to look at the bracers. If there's anything I know about mages, they can't resist a magical puzzle. Take the bag of water elemental bracers and see if they can shed any light on the Stone's curse.  Look for the Archmage Ansirem Runeweaver.  I've dealt with him before, and his knowledge is vast.]],logDesc=[[Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran Crater.]]}
DB[603]={id=603,zoneId=33,name=[[Ansirem's Key]],name_loc=[[Llave de Ansirem]],level=37,minLevel=32,giver=[[Archmage Ansirem Runeweaver]],giver_loc=[[Archimago Ansirem Tejerruna]],giverType=[[NPC]],giverId=2543,ender=[[Catelyn the Blade]],ender_loc=[[Catelyn la Afilada]],enderType=[[NPC]],enderId=2542,prevId=602,rewardNextId=610,poiX=-14467,poiY=480,wowhead=[[https://www.wowhead.com/wotlk/quest=603]],image=[[assets/images/quests/placeholder.png]],desc=[[The mage that is in possession of the Stone is amplifying its power through some focal point... an altar of some sort. You should be able to disrupt it by overpowering it. As it happens, I know just the thing: an ancient dagger, another troll relic. There's just one... little problem. You see, I found the dagger while researching in Stranglethorn, but I gave it to my willful daughter, Catelyn, who ran off to Booty Bay to become a pirate.]],logDesc=[[Talk to Catelyn in Booty Bay.]]}
DB[604]={id=604,zoneId=33,name=[[The Bloodsail Buccaneers]],name_loc=[[Bucaneros Velasangre]],level=42,minLevel=37,giver=[[Fleet Master Seahorn]],giver_loc=[[Maestro de flota Cuernomarino]],giverType=[[NPC]],giverId=2487,ender=[[Fleet Master Seahorn]],ender_loc=[[Maestro de flota Cuernomarino]],enderType=[[NPC]],enderId=2487,prevId=599,rewardNextId=608,poiX=-13468,poiY=656,wowhead=[[https://www.wowhead.com/wotlk/quest=604]],image=[[assets/images/quests/placeholder.png]],desc=[[Crazz speaks highly of your dedication to the Blackwater Raiders.  I am going to trust you with a mission of extreme importance to the fleet. Infiltrate the so-called southern command post the Bloodsail Buccaneers have established on the Wild Shore.  Raid the encampment.  Bring me their charts along with their written orders.  We shall see exactly what those scum are up to.]],logDesc=[[Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders.]]}
DB[605]={id=605,zoneId=33,name=[[Singing Blue Shards]],name_loc=[[Fragmentos de cristales canto azules]],level=35,minLevel=30,giver=[[Crank Fizzlebub]],giver_loc=[[Loquillo Pinchabujas]],giverType=[[NPC]],giverId=2498,ender=[[Crank Fizzlebub]],ender_loc=[[Loquillo Pinchabujas]],enderType=[[NPC]],enderId=2498,rewardNextId=600,poiX=-13203,poiY=-599,wowhead=[[https://www.wowhead.com/wotlk/quest=605]],image=[[assets/images/quests/placeholder.png]],desc=[[The Singing Crystals are unique to Stranglethorn, and are very valuable to certain parties.  I can move those crystals, but the cursed Venture Company makes it hard for an honest entrepreneur like myself to gather any! I'd like to hire you. The basilisks in Stranglethorn eat the crystal.  This gives them their hardened skin, and sometimes decent quality crystal can be harvested from it. You can get it from any basilisk, but the less nasty ones are along the shores south of Zul'Kunda, to the north.]],logDesc=[[Bring 10 Singing Crystal Shards to Crank Fizzlebub.]]}
DB[606]={id=606,zoneId=33,name=[[Scaring Shaky]],name_loc=[[Asusta al Trémulo]],level=41,minLevel=30,giver=[["Sea Wolf" MacKinley]],giver_loc=[["Lobo de Mar" MacKinley]],giverType=[[NPC]],giverId=2501,ender=[["Shaky" Phillipe]],ender_loc=[["Trémulo" Phillipe]],enderType=[[NPC]],enderId=2502,rewardNextId=607,poiX=-13910,poiY=-16,wowhead=[[https://www.wowhead.com/wotlk/quest=606]],image=[[assets/images/quests/placeholder.png]],desc=[[If there's one thing I can't stand, it's people who don't pay their gambling debts!  And there are a lot of people who owe me. Think you can help me collect? First, there's "Shaky" Phillipe down by the docks.  He owes me plenty after last week's game and I want my due!  But to get it, we'll have to scare him. Go out of town and hunt Elder Mistvale Gorillas.  Find a nice selection of giblets, then take them to Shaky.  Don't let on that they're from an animal; let him think the worst.]],logDesc=[[Bring 5 Mistvale Giblets to "Shaky" Phillipe in Booty Bay.]]}
DB[607]={id=607,zoneId=33,name=[[Return to MacKinley]],name_loc=[[Regresa junto a MacKinley]],level=41,minLevel=30,giver=[["Shaky" Phillipe]],giver_loc=[["Trémulo" Phillipe]],giverType=[[NPC]],giverId=2502,ender=[["Sea Wolf" MacKinley]],ender_loc=[["Lobo de Mar" MacKinley]],enderType=[[NPC]],enderId=2501,prevId=606,rewardNextId=609,poiX=-14447,poiY=448,wowhead=[[https://www.wowhead.com/wotlk/quest=607]],image=[[assets/images/quests/placeholder.png]],desc=[[Here, take this pouch and give it to Sea Wolf.  And tell him I meant to pay him back!  I swear!! I just got a little drunk and lost my way, and...you know how things are.  He'll understand - you don't have to get rough!]],logDesc=[[Bring Shaky's Payment to "Sea Wolf" MacKinley.]]}
DB[608]={id=608,zoneId=33,name=[[The Bloodsail Buccaneers]],name_loc=[[Bucaneros Velasangre]],level=42,minLevel=37,giver=[[Fleet Master Seahorn]],giver_loc=[[Maestro de flota Cuernomarino]],giverType=[[NPC]],giverId=2487,ender=[[Fleet Master Seahorn]],ender_loc=[[Maestro de flota Cuernomarino]],enderType=[[NPC]],enderId=2487,prevId=604,poiX=-14921,poiY=123,wowhead=[[https://www.wowhead.com/wotlk/quest=608]],image=[[assets/images/quests/placeholder.png]],desc=[[Blast the nerve of Firallon!  He couldn't sail a skiff through Crystal Lake let alone lead an entire fleet against us. The Bloodsail Buccaneers will pay for their carelessness.  Now that we know their plan of attack, we can counter before they know what hit them. But why send the entire fleet to do the work of one brave adventuring party?  $n, take some of your most skilled comrades out to Firallon's landing spot and assassinate the Bloodsail leadership.  Their fleet will sink soon after....]],logDesc=[[Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.]],rewards={{id=4138,qty=1}}}
DB[609]={id=609,zoneId=33,name=[[Voodoo Dues]],name_loc=[[El vudú debido]],level=44,minLevel=30,giver=[["Sea Wolf" MacKinley]],giver_loc=[["Lobo de Mar" MacKinley]],giverType=[[NPC]],giverId=2501,ender=[["Sea Wolf" MacKinley]],ender_loc=[["Lobo de Mar" MacKinley]],enderType=[[NPC]],enderId=2501,prevId=607,poiX=-13349,poiY=-29,wowhead=[[https://www.wowhead.com/wotlk/quest=609]],image=[[assets/images/quests/placeholder.png]],desc=[[My list is shortening, but there are still people who owe me. Next, we have Maury "Club Foot" Wilkins, Jon-Jon the Crow, and Chucky "Ten Thumbs." These scurvy dogs' debts are months outstanding and I thought they skipped town to avoid paying up!  Later, I heard they're cursed and bewitched and now wander the jungle ruins.  But I don't care what their fate is - I want what's mine! They're at the Ruins of Aboraz and the Ruins of Jubuwal, northeast of here.  Find them, and collect.]],logDesc=[[Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to "Sea Wolf" MacKinley in Booty Bay.]]}
DB[610]={id=610,zoneId=33,name=[["Pretty Boy" Duncan]],name_loc=[["El Guapo" Duncan]],level=39,minLevel=32,giver=[[Catelyn the Blade]],giver_loc=[[Catelyn la Afilada]],giverType=[[NPC]],giverId=2542,ender=[[Catelyn the Blade]],ender_loc=[[Catelyn la Afilada]],enderType=[[NPC]],enderId=2542,prevId=603,rewardNextId=611,poiX=-14122,poiY=473,wowhead=[[https://www.wowhead.com/wotlk/quest=610]],image=[[assets/images/quests/placeholder.png]],desc=[[My FATHER sent you? I'd have thought that old codger would have given up on me by now. It wasn't really his fault I ran off, he just shouldn't have expected I'd be willing to live a boring life, reading over musty books and associating with grey-haired, stiff-backed, stuffy mages! If you need my dagger, you'll have to get it back from "Pretty Boy" Duncan, one of the Bloodsail Buccaneers. Put something 'tween his shoulders and I'm sure he'll give it up.]],logDesc=[[Get Catelyn's dagger from "Pretty Boy" Duncan.]]}
DB[611]={id=611,zoneId=33,name=[[The Curse of the Tides]],name_loc=[[La maldición de las mareas]],level=40,minLevel=32,giver=[[Catelyn the Blade]],giver_loc=[[Catelyn la Afilada]],giverType=[[NPC]],giverId=2542,ender=[[Baron Revilgaz]],ender_loc=[[Barón Revilgaz]],enderType=[[NPC]],enderId=2496,prevId=610,poiX=-14439,poiY=483,wowhead=[[https://www.wowhead.com/wotlk/quest=611]],image=[[assets/images/quests/placeholder.png]],desc=[[So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for. Maybe you should try there. You got my knife back for me, so I guess you can borrow it... but I want it back when you're done!]],logDesc=[[Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz.]],rewards={{id=4120,qty=1}}}
DB[613]={id=613,zoneId=33,name=[[Cracking Maury's Foot]],name_loc=[[Abrir la pata de Maury]],level=44,minLevel=30,giver=[["Sea Wolf" MacKinley]],giver_loc=[["Lobo de Mar" MacKinley]],giverType=[[NPC]],giverId=2501,ender=[["Sea Wolf" MacKinley]],ender_loc=[["Lobo de Mar" MacKinley]],enderType=[[NPC]],enderId=2501,prevId=609,poiX=-12353,poiY=-1154,wowhead=[[https://www.wowhead.com/wotlk/quest=613]],image=[[assets/images/quests/placeholder.png]],desc=[[Curses!  That swab Maury put a lock on his foot, and I can't open it!  His loot's inside the foot, and that's what he owes me! We need to find the key to open the lock.  Maury was known to gamble with the Mosh'Ogg ogres, at their mound to the northeast.  And he told me, when he was still alive, that the last time he went to the mound he was chased off after winning too much.  Maybe the Ogres there have his key. But if they do, you might have to kill a load of them to find the right one...]],logDesc=[[Bring Maury's Key to "Sea Wolf" Mackinley in Booty Bay.]],rewards={{id=4129,qty=1}}}
DB[614]={id=614,zoneId=33,name=[[The Captain's Chest]],name_loc=[[El cofre del Capitán]],level=42,minLevel=35,giver=[[Captain Hecklebury Smotts]],giver_loc=[[Capitán Hecklebury Smotts]],giverType=[[NPC]],giverId=2500,ender=[[Captain Hecklebury Smotts]],ender_loc=[[Capitán Hecklebury Smotts]],enderType=[[NPC]],enderId=2500,poiX=-14148,poiY=-123,wowhead=[[https://www.wowhead.com/wotlk/quest=614]],image=[[assets/images/quests/placeholder.png]],desc=[[I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation. Until... Those cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve! I hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.]],logDesc=[[Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.]],rewards={{id=11469,qty=1}}}
DB[615]={id=615,zoneId=33,name=[[The Captain's Cutlass]],name_loc=[[El alfanje del Capitán]],level=42,minLevel=35,giverType=[[NPC]],ender=[[Sprogger]],ender_loc=[[Tardo]],enderType=[[NPC]],enderId=2594,prevId=8552,rewardNextId=8554,poiX=-14302,poiY=520,wowhead=[[https://www.wowhead.com/wotlk/quest=615]],image=[[assets/images/quests/placeholder.png]],desc=[[After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat. This time another of the giants, Negolash, stole my cutlass. Face Negolash and bring me my cutlass! Speak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the giant.]],logDesc=[[Speak with Sprogger.]]}
DB[616]={id=616,zoneId=33,name=[[The Haunted Isle]],name_loc=[[La isla fantasma]],level=37,minLevel=32,giver=[[Krazek]],giverType=[[NPC]],giverId=773,ender=[[Baron Revilgaz]],ender_loc=[[Barón Revilgaz]],enderType=[[NPC]],enderId=2496,rewardNextId=578,poiX=-14439,poiY=483,wowhead=[[https://www.wowhead.com/wotlk/quest=616]],image=[[assets/images/quests/placeholder.png]],desc=[[Baron Revilgaz has had me keep an ear out for rumors of the strange and out-of-place in Booty Bay and Stranglethorn. I don't usually put much stock in ghost stories, but I heard some sailors in the tavern talking about a haunted island off the coast. Water elementals and a raving goblin ghost, they say. If you're going to go talk to Revilgaz, could you relay that story to him?]],logDesc=[[Speak with Baron Revilgaz in Booty Bay.]]}
DB[617]={id=617,zoneId=33,name=[[Akiris by the Bundle]],name_loc=[[Tallos de juncos akiris]],level=43,minLevel=38,giver=[[Privateer Bloads]],giver_loc=[[Corsario Bloads]],giverType=[[NPC]],giverId=2494,ender=[[Privateer Bloads]],ender_loc=[[Corsario Bloads]],enderType=[[NPC]],enderId=2494,poiX=-13909,poiY=420,wowhead=[[https://www.wowhead.com/wotlk/quest=617]],image=[[assets/images/quests/placeholder.png]],desc=[[You looking fer work, $N? I might have some if you're up for a little challenge. I got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed. Not too sure what it's for, but he pays well for bundles of the stuff. Ya bring me ten stalks of the stuff, and we'll have business to do. The naga were last seen along the beach to the north of here.]],logDesc=[[Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.]],rewards={{id=4117,qty=1}}}
DB[618]={id=618,zoneId=33,name=[[Facing Negolash]],name_loc=[[Enfréntate a Negolash]],level=42,minLevel=35,giver=[[Sprogger]],giver_loc=[[Tardo]],giverType=[[NPC]],giverId=2594,ender=[[Captain Hecklebury Smotts]],ender_loc=[[Capitán Hecklebury Smotts]],enderType=[[NPC]],enderId=2500,prevId=615,poiX=-14599,poiY=76,wowhead=[[https://www.wowhead.com/wotlk/quest=618]],image=[[assets/images/quests/placeholder.png]],desc=[[Negolash is a hungry giant. When the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe! If you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!]],logDesc=[[Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat. Kill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.]],rewards={{id=4130,qty=1}}}
DB[619]={id=619,zoneId=33,name=[[Enticing Negolash]],name_loc=[[La tentación de Negolash]],level=42,minLevel=1,giver=[[Ruined Lifeboat]],giver_loc=[[Bote salvavidas inservible]],giverType=[[GO]],giverId=2289,ender=[[Ruined Lifeboat]],ender_loc=[[Bote salvavidas inservible]],enderType=[[GO]],enderId=2289,poiX=-14452,poiY=495,wowhead=[[https://www.wowhead.com/wotlk/quest=619]],image=[[assets/images/quests/placeholder.png]]}
DB[621]={id=621,zoneId=33,name=[[Zanzil's Secret]],name_loc=[[El secreto de Zanzil]],level=44,minLevel=35,giver=[[Crank Fizzlebub]],giver_loc=[[Loquillo Pinchabujas]],giverType=[[NPC]],giverId=2498,ender=[[Crank Fizzlebub]],ender_loc=[[Loquillo Pinchabujas]],enderType=[[NPC]],enderId=2498,nextId=1119,exGroup=-621,poiX=-13349,poiY=-29,wowhead=[[https://www.wowhead.com/wotlk/quest=621]],image=[[assets/images/quests/placeholder.png]],desc=[[Zanzil the Outcast dwells with his followers in the Jubuwal and Aboraz Ruins, northeast of Booty Bay.  He is exiled from his tribe.  Why? Well... Zanzil has methods of bending the minds of others, and his leaders fear him.  He uses a mixture of jungle plants on his followers to suppress their will and strengthen their bodies. His mixture would be worth much to those who wish to control others. Bring me samples of his mixture, and I will find a use for them.]],logDesc=[[Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.]],rewards={{id=4131,qty=1}}}
DB[622]={id=622,zoneId=33,name=[[Return to Corporal Kaleb]],name_loc=[[Regresa junto al cabo Kaleb]],level=37,minLevel=32,giver=[[Krazek]],giverType=[[NPC]],giverId=773,ender=[[Corporal Kaleb]],ender_loc=[[Cabo Kaleb]],enderType=[[NPC]],enderId=770,prevId=627,poiX=-11309,poiY=-187,wowhead=[[https://www.wowhead.com/wotlk/quest=622]],image=[[assets/images/quests/placeholder.png]],desc=[[While you were gone I fixed the pot you brought me.  I even added an extra steam whistle, and look!  There's a new chopper at the bottom that'll cut through leg bones! Yes yes, Krazek's Crock Pot is a 100% cook pleaser!  I'm sure its owner will be satisfied.]],logDesc=[[Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp.]],rewards={{id=4124,qty=1}}}
DB[623]={id=623,zoneId=33,name=[[Akiris by the Bundle]],name_loc=[[Tallos de juncos akiris]],level=43,minLevel=38,giver=[[Privateer Bloads]],giver_loc=[[Corsario Bloads]],giverType=[[NPC]],giverId=2494,ender=[[Privateer Groy]],ender_loc=[[Corsario Groy]],enderType=[[NPC]],enderId=2616,prevId=617,poiX=-3843,poiY=-4530,wowhead=[[https://www.wowhead.com/wotlk/quest=623]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, since I have you here, I got a message from Groy while you were gone. He mentioned bein' satisfied with the last shipment that arrived and has a client that wants some more of the stuff right away. I won't be headin' to Theramore for a week, but if you're willin' to make the journey, there's no reason you can't take the stuff for me. Feeling adventurous? You do know where Dustwallow Marsh is, doncha? I'd be careful though, Theramore can be dangerous if you're the wrong kind of crowd.]],logDesc=[[Bring a Bundle of Akiris Reeds to Privateer Groy in Theramore.]]}
DB[624]={id=624,zoneId=33,name=[[Cortello's Riddle]],name_loc=[[El enigma de Cortello]],level=43,minLevel=35,giverType=[[NPC]],ender=[[A Soggy Scroll]],ender_loc=[[Un viejo pergamino]],enderType=[[GO]],enderId=2553,rewardNextId=625,poiX=-10358,poiY=-2748,wowhead=[[https://www.wowhead.com/wotlk/quest=624]],image=[[assets/images/quests/placeholder.png]],desc=[[There is an ornate, well-traveled bridge East of Deadwind and south of Redridge Underneath there waits something for you Some call it a hint, others a clue There it will lie for endless tomorrows Biding its time in the Swamp of Sorrows]],logDesc=[[Solve the riddle!]]}
DB[625]={id=625,zoneId=33,name=[[Cortello's Riddle]],name_loc=[[El enigma de Cortello]],level=43,minLevel=35,giver=[[A Soggy Scroll]],giver_loc=[[Un viejo pergamino]],giverType=[[GO]],giverId=2553,ender=[[Musty Scroll]],ender_loc=[[Pergamino mohoso]],enderType=[[GO]],enderId=2555,prevId=624,rewardNextId=626,poiX=-4348,poiY=-2608,wowhead=[[https://www.wowhead.com/wotlk/quest=625]],image=[[assets/images/quests/placeholder.png]],desc=[[A far off land in Kalimdor awaits Where peril has dashed hopes and fates East of Barrens the weather is harsh Gloom and danger pock Dustwallow Marsh But there lies a clue for those up to the test Waiting to be found in a cave in the southwest]],logDesc=[[Solve the riddle!]]}
DB[626]={id=626,zoneId=33,name=[[Cortello's Riddle]],name_loc=[[El enigma de Cortello]],level=51,minLevel=35,giver=[[Musty Scroll]],giver_loc=[[Pergamino mohoso]],giverType=[[GO]],giverId=2555,ender=[[Cortello's Treasure]],ender_loc=[[El tesoro de Cortello]],enderType=[[GO]],enderId=2556,prevId=625,poiX=265,poiY=-4685,wowhead=[[https://www.wowhead.com/wotlk/quest=626]],image=[[assets/images/quests/placeholder.png]],desc=[[To Lordaeron! The great land of turmoil Where brave soldiers with death do toil Find your way through the great unrest There you will find the end to this quest Along the coast of the Hinterlands, at the base of the great falls Underneath the water there does your treasure call!]],logDesc=[[Solve the riddle!]],rewards={{id=11324,qty=1}}}
DB[627]={id=627,zoneId=33,name=[[Favor for Krazek]],name_loc=[[Un favor a Krazek]],level=37,minLevel=32,giver=[[Krazek]],giverType=[[NPC]],giverId=773,ender=[[Krazek]],enderType=[[NPC]],enderId=773,prevId=210,rewardNextId=622,poiX=-14453,poiY=501,wowhead=[[https://www.wowhead.com/wotlk/quest=627]],image=[[assets/images/quests/placeholder.png]],desc=[[There is a mountain cave in Drywhisker Gorge, far to the north in the Arathi Highlands.  In that cave is rare ore: bloodstone.  The bloodstone in this cave is not of the highest grade, but even low-quality bloodstone is valuable... to those with the knowledge to use it. I would like some. I will fix your crock pot, but while I work on it... bring me samples of bloodstone.  Bring me enough, and I'll even give you a bonus. Oh, and if you don't have the skill to mine it... find someone who does!]],logDesc=[[Bring 4 loads of Lesser Bloodstone Ore to Krazek in Booty Bay.]]}
DB[628]={id=628,zoneId=33,name=[[Excelsior]],name_loc=[[Borceguí]],level=38,minLevel=31,giver=[[Drizzlik]],giverType=[[NPC]],giverId=2495,ender=[[Drizzlik]],enderType=[[NPC]],enderId=2495,prevId=577,poiX=-11985,poiY=612,wowhead=[[https://www.wowhead.com/wotlk/quest=628]],image=[[assets/images/quests/placeholder.png]],desc=[[With the inside finished, all that's left is to add the outer layer. For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line. It's hard to find that perfect skin though, the only one that fits my plan is the skin of an elder saltwater crocolisk. The elders only come out to defend the other saltwater crocs, so you might need to kill a few to draw one out.]],logDesc=[[Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay.]],rewards={{id=4109,qty=1}}}
DB[629]={id=629,zoneId=33,name=[[The Vile Reef]],name_loc=[[El Arrecife Mortal]],level=37,minLevel=30,giver=[[Kin'weelay]],giverType=[[NPC]],giverId=2519,ender=[[Kin'weelay]],enderType=[[NPC]],enderId=2519,poiX=-12148,poiY=637,wowhead=[[https://www.wowhead.com/wotlk/quest=629]],image=[[assets/images/quests/placeholder.png]],desc=[[Long ago, a great shudder of the earth sunk an old troll city beneath the waters of the Savage Coast to the northwest.  We call that place the Vile Reef, for murlocs now reside in the ruins of the city, attacking any who draw close. There is an old tablet among those ruins that tells the ancient tale of Gri'lek, a hero of troll legends.  The tale is sacred to the Darkspear tribe, and although the tablet is too large to move, I want a shard of it to enshrine in our new home in Orgrimmar.]],logDesc=[[Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.]]}
DB[630]={id=630,zoneId=33,name=[[Message in a Bottle]],name_loc=[[Mensaje en una botella]],level=42,minLevel=42,giver=[[Princess Poobah]],giver_loc=[[Princesa Poobah]],giverType=[[NPC]],giverId=2634,ender=[[Princess Poobah]],ender_loc=[[Princesa Poobah]],enderType=[[NPC]],enderId=2634,prevId=594,poiX=-14722,poiY=-391,wowhead=[[https://www.wowhead.com/wotlk/quest=630]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I put my faith in you and anyone you can muster to help free me. The great Skymane King Mukla is my captor. He commands the beasts of this island, and they keep me here against my will with the aid of this chain. If you can slay him and find the key to this shackle, I shall be indebted to you greatly. I often hear him to the southeast side of the island, but please be careful: he is not to be trifled with.]],logDesc=[[Slay King Mukla and return to Princess Poobah with the Key to free her.]],rewards={{id=4118,qty=1}}}
DB[631]={id=631,zoneId=11,name=[[The Thandol Span]],name_loc=[[El Puente Thandol]],level=31,minLevel=28,giver=[[Rhag Garmason]],giverType=[[NPC]],giverId=1075,ender=[[Ebenezer Rustlocke's Corpse]],ender_loc=[[Cadáver de Ebenezer Herrumbra]],enderType=[[GO]],enderId=2652,rewardNextId=632,poiX=-2367,poiY=-2510,wowhead=[[https://www.wowhead.com/wotlk/quest=631]],image=[[assets/images/quests/placeholder.png]],desc=[[A tremendous explosion roared through the hills.  'Twas horrible, I tell you! Good soldiers died defending the Thandol Span.  Longbraid says we'll take revenge on the Dark Irons before all is said and done. We're in a world of hurt though and I don't see any reinforcements in sight.  Longbraid sent Ol' Rustlocke to scout the eastern bridge to see if we could secure it. That was days ago.  We haven't the manpower to search for him with Dun Modr under siege. Perhaps you can find him...]],logDesc=[[Rhag Garmason wants you to locate Ol' Rustlocke.]]}
DB[632]={id=632,zoneId=11,name=[[The Thandol Span]],name_loc=[[El Puente Thandol]],level=31,minLevel=28,giver=[[Ebenezer Rustlocke's Corpse]],giver_loc=[[Cadáver de Ebenezer Herrumbra]],giverType=[[GO]],giverId=2652,ender=[[Rhag Garmason]],enderType=[[NPC]],enderId=1075,prevId=631,rewardNextId=633,poiX=-2650,poiY=-2454,wowhead=[[https://www.wowhead.com/wotlk/quest=632]],image=[[assets/images/quests/placeholder.png]],desc=[[It seems as though poor Ol' Rustlocke ran into a Dark Iron ambush.  You notice a parchment next to his clenched fist. Report the grim news to Rhag Garmason and show him what you found.]],logDesc=[[Report back to Rhag Garmason at Dun Modir in Wetlands and show him the parchment you found on Rustlocke's corpse.]]}
DB[633]={id=633,zoneId=11,name=[[The Thandol Span]],name_loc=[[El Puente Thandol]],level=31,minLevel=28,giver=[[Rhag Garmason]],giverType=[[NPC]],giverId=1075,ender=[[Rhag Garmason]],enderType=[[NPC]],enderId=1075,prevId=632,rewardNextId=634,poiX=-2650,poiY=-2454,wowhead=[[https://www.wowhead.com/wotlk/quest=633]],image=[[assets/images/quests/placeholder.png]],desc=[[Heavens no!  Poor Rustlocke.  'Tis quite a tragedy indeed. We must not let his death pass in vain.  This parchment you discovered indicates that Kam Deepfury, the mastermind behind the original attack, arranged for a cache of explosives to be stashed just across the Thandol Span, in Arathi Highlands. If those explosives make it to the bridge, our major supply line to the north will be severed!  The cache must be destroyed, $n!  Return to me when your mission is complete. You're our only hope.]],logDesc=[[Destroy the cache of explosives.]],choiceRewards={{id=4504,qty=1},{id=4505,qty=1}}}
DB[634]={id=634,zoneId=11,name=[[Plea To The Alliance]],name_loc=[[Petición a la Alianza]],level=31,minLevel=28,giver=[[Rhag Garmason]],giverType=[[NPC]],giverId=1075,ender=[[Captain Nials]],ender_loc=[[Capitana Nials]],enderType=[[NPC]],enderId=2700,prevId=633,poiX=-1274,poiY=-2517,wowhead=[[https://www.wowhead.com/wotlk/quest=634]],image=[[assets/images/quests/placeholder.png]],desc=[[I ask of you one more small favor, $c.  We await the reserves of Ironforge.  However, Roggo has knowledge of an Alliance camp to the north in Arathi Highlands at Refuge Pointe. Travel there and seek out Captain Nials.  Ask the good Captain if the Alliance can spare some soldiers to help us reclaim Dun Modr and the Thandol Span.]],logDesc=[[Seek out Captain Nials at Refuge Pointe in Arathi Highlands.]]}
DB[635]={id=635,zoneId=45,name=[[Crystal in the Mountains]],name_loc=[[Cristal en las montañas]],level=35,minLevel=30,giverType=[[NPC]],ender=[[Shards of Myzrael]],ender_loc=[[Fragmentos de Myzrael]],enderType=[[GO]],enderId=138492,poiX=-943,poiY=-3117,wowhead=[[https://www.wowhead.com/wotlk/quest=635]],image=[[assets/images/quests/placeholder.png]],desc=[[This shard pulses as you hold it... You feel a sense of pleading coming from the shard, as if someone is trying to communicate, someone who desperately needs your help. A vision appears in your mind - of the northern mountains of Arathi, and of a brilliant crystal jutting from the earth there. You feel drawn to that place.]],logDesc=[[Find the crystal from your vision.]]}
DB[637]={id=637,zoneId=1537,name=[[Sully Balloo's Letter]],name_loc=[[La carta de Sully Balloo]],level=30,minLevel=25,giverType=[[NPC]],ender=[[Sara Balloo]],enderType=[[NPC]],enderId=2695,poiX=-4924,poiY=-1216,wowhead=[[https://www.wowhead.com/wotlk/quest=637]],image=[[assets/images/quests/placeholder.png]],desc=[[The waterlogged and war-torn envelope dissolves in your hands, leaving you with a few pages of a letter in your grasp, written with painstaking care. The letter is addressed to a Mrs. Sara Balloo of Ironforge and begins, "My dear Sara...."]],logDesc=[[Deliver Sully Balloo's Letter to Sara Balloo.]]}
DB[638]={id=638,zoneId=33,name=[[Trollbane]],name_loc=[[Aterratrols]],level=37,minLevel=32,giver=[[Nimboya]],giverType=[[NPC]],giverId=2497,ender=[[Zengu]],enderType=[[NPC]],enderId=2703,rewardNextId=639,poiX=-948,poiY=-3523,wowhead=[[https://www.wowhead.com/wotlk/quest=638]],image=[[assets/images/quests/placeholder.png]],desc=[[With Thoras Trollbane dead and Stromgarde in ruins, Vol'jin has instructed that we make every effort to spirit the legendary sword Trol'kalar from the humans' hands, so that we might use it in our coming battles against the trolls of Zul'Gurub. Zengu, one of our seasoned hunters, was dispatched to Hammerfall in northeastern Arathi Highlands to oversee its procurement.]],logDesc=[[Travel to Hammerfall in the Arathi Highlands and speak with Zengu.]]}
DB[639]={id=639,zoneId=45,name=[[Sigil of Strom]],name_loc=[[El sigilo de Strom]],level=37,minLevel=32,giver=[[Zengu]],giverType=[[NPC]],giverId=2703,ender=[[Zengu]],enderType=[[NPC]],enderId=2703,prevId=638,rewardNextId=640,poiX=-1633,poiY=-1934,wowhead=[[https://www.wowhead.com/wotlk/quest=639]],image=[[assets/images/quests/placeholder.png]],desc=[[In ancient times, trolls fought against the Arathorian Empire and our most capable adversary, Lord Ignaeus of Strom, named Trollbane. He rode into battle wielding Trol'kalar--troll slayer, in their ancient tongue. But now the sons of Trollbane are weakened, their stronghold brought to ruin. The sword is protected by several sigils that were divided among the survivors of Stromgarde, and we must retrieve them. The first was taken by the Syndicate, one of their men in Stromgarde should have it.]],logDesc=[[Get the Sigil of Strom for Zengu in Hammerfall.]]}
DB[640]={id=640,zoneId=45,name=[[The Broken Sigil]],name_loc=[[El sigilo roto]],level=40,minLevel=32,giver=[[Zengu]],giverType=[[NPC]],giverId=2703,ender=[[Tor'gan]],enderType=[[NPC]],enderId=2706,prevId=639,poiX=-1549,poiY=-1907,wowhead=[[https://www.wowhead.com/wotlk/quest=640]],image=[[assets/images/quests/placeholder.png]],desc=[[Thoras Trollbane's tomb is protected by three sigils--the first of which you retrieved from the Syndicate. The other two will be harder to get, as they're held by the firmly entrenched Stromgarde militia. The sigil of Thoradin was divided into five pieces by Thoras' son, Galen, and dispersed among the Stromgarde defenders. Retrieve the pieces and bring them to Tor'gan, the troll shaman, he will be able to bind them into the complete sigil.]],logDesc=[[Retrieve the 5 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.]]}
DB[641]={id=641,zoneId=45,name=[[Sigil of Thoradin]],name_loc=[[El sigilo de Thoradin]],level=40,minLevel=32,giver=[[Tor'gan]],giverType=[[NPC]],giverId=2706,ender=[[Zengu]],enderType=[[NPC]],enderId=2703,prevId=640,rewardNextId=643,poiX=-948,poiY=-3523,wowhead=[[https://www.wowhead.com/wotlk/quest=641]],image=[[assets/images/quests/placeholder.png]],desc=[[The reconstruction worked flawlessly. The sigil can now be used to unlock the seal on Trollbane's tomb. Return it to Zengu, no doubt he has additional tasks for you to complete.]],logDesc=[[Bring the restored Sigil of Thoradin to Zengu in Hammerfall.]]}
DB[642]={id=642,zoneId=45,name=[[The Princess Trapped]],name_loc=[[La princesa encerrada]],level=37,minLevel=30,giver=[[Shards of Myzrael]],giver_loc=[[Fragmentos de Myzrael]],giverType=[[GO]],giverId=138492,ender=[[Iridescent Shards]],ender_loc=[[Fragmentos iridiscentes]],enderType=[[GO]],enderId=2701,rewardNextId=651,poiX=-891,poiY=-3999,wowhead=[[https://www.wowhead.com/wotlk/quest=642]],image=[[assets/images/quests/placeholder.png]],desc=[[My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world. Please help me.  Allies of the giants, the Drywhisker Kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather Motes of Myzrael from the kobolds and apply them to it. I beg you, $N, aid me!]],logDesc=[[Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.]]}
DB[643]={id=643,zoneId=45,name=[[Sigil of Arathor]],name_loc=[[El sigilo de Arathor]],level=41,minLevel=32,giver=[[Zengu]],giverType=[[NPC]],giverId=2703,ender=[[Zengu]],enderType=[[NPC]],enderId=2703,prevId=641,rewardNextId=644,poiX=-1112,poiY=-2788,wowhead=[[https://www.wowhead.com/wotlk/quest=643]],image=[[assets/images/quests/placeholder.png]],desc=[[Though they can barely be said to control Stromgarde, let alone the whole of Arathi Highlands, the human prince trots the remnants of his cavalry over the countryside. I can't understand why he does it, but who understands the way the humans think, hm? Whatever his reasoning, more importantly, he has given one of the sigils to Lieutenant Valorcall, their cavalry leader. Locate him and bring his sigil back to me.]],logDesc=[[Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall.]]}
DB[644]={id=644,zoneId=45,name=[[Sigil of Trollbane]],name_loc=[[El sigilo de Aterratrols]],level=42,minLevel=32,giver=[[Zengu]],giverType=[[NPC]],giverId=2703,ender=[[Zengu]],enderType=[[NPC]],enderId=2703,prevId=643,rewardNextId=645,poiX=-1528,poiY=-1889,wowhead=[[https://www.wowhead.com/wotlk/quest=644]],image=[[assets/images/quests/placeholder.png]],desc=[[The final of the sigils needed to unlock the tomb of Thoras Trollbane is held by his son personally. He resides deep within Stromgarde, in a chapel in the militia-held districts. Prince Galen is well protected and no slouch of a warrior himself, so this task could prove most difficult.]],logDesc=[[Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall.]]}
DB[645]={id=645,zoneId=45,name=[[Trol'kalar]],name_loc=[[Trol'kalar]],level=42,minLevel=32,giver=[[Zengu]],giverType=[[NPC]],giverId=2703,ender=[[Trollbane's Tomb]],ender_loc=[[Tumba de Aterratrols]],enderType=[[GO]],enderId=2703,prevId=644,rewardNextId=646,poiX=-1564,poiY=-1906,wowhead=[[https://www.wowhead.com/wotlk/quest=645]],image=[[assets/images/quests/placeholder.png]],desc=[[What's this? With the four sigils brought together, they have formed together to create one sigil. There can be no doubt that this will be able to break the wardings placed upon Trollbane's tomb. Trollbane's remains are entombed in the Sanctum behind the chapel in Stromgarde. Retrieve Trol'kalar.]],logDesc=[[Retrieve Trol'kalar from Trollbane's tomb in Stromgarde.]]}
DB[646]={id=646,zoneId=45,name=[[Trol'kalar]],name_loc=[[Trol'kalar]],level=42,minLevel=32,giver=[[Trollbane's Tomb]],giver_loc=[[Tumba de Aterratrols]],giverType=[[GO]],giverId=2703,ender=[[Zengu]],enderType=[[NPC]],enderId=2703,prevId=645,poiX=-948,poiY=-3523,wowhead=[[https://www.wowhead.com/wotlk/quest=646]],image=[[assets/images/quests/placeholder.png]],desc=[[The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released.]],logDesc=[[Deliver Trol'kalar to Zengu in Hammerfall.]],choiceRewards={{id=4508,qty=1},{id=4507,qty=1}}}
DB[647]={id=647,zoneId=11,name=[[MacKreel's Moonshine]],name_loc=[[Licor de luna de Mackreel]],level=30,minLevel=28,giver=[[Foggy MacKreel]],giver_loc=[[Nubos MacKreel]],giverType=[[NPC]],giverId=2696,ender=[[Brewmeister Bilger]],ender_loc=[[Maestro cervecero Bilger]],enderType=[[NPC]],enderId=2705,poiX=-855,poiY=-601,wowhead=[[https://www.wowhead.com/wotlk/quest=647]],image=[[assets/images/quests/placeholder.png]],desc=[[Had quite a bit of the ol' Moonshine last night!  Longbraid would have my head if he knew that I passed out during my watch. The noggin hurts something fierce.  Felt as though a whole brigade of siege engines passed overhead, all that rumbling. Oh my, look at the time! I promised Brewmeister Bilger in Southshore that I'd repay my debt to him by sending some Moonshine. But there are just 15 minutes left before I'm overdue!  Take him this batch, would you please?  And hurry!]],logDesc=[[Take MacKreel's Moonshine to Brewmeister Bilger in Southshore.]]}
DB[648]={id=648,zoneId=440,name=[[Rescue OOX-17/TN!]],name_loc=[[¡Rescatar a OOX-17/TN!]],level=48,minLevel=43,giver=[[Homing Robot OOX-17/TN]],giver_loc=[[Robot mensajero OOX-17/TN]],giverType=[[NPC]],giverId=7784,ender=[[Oglethorpe Obnoticus]],ender_loc=[[Oglethorpe Obnoticus]],enderType=[[NPC]],enderId=7406,prevId=351,nextId=3721,exGroup=-648,poiX=-14417,poiY=411,wowhead=[[https://www.wowhead.com/wotlk/quest=648]],image=[[assets/images/quests/placeholder.png]],desc=[[The gnome's voice crackles once again from the robot: "I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  I need you to escort the robot from its current location to, let's say, near the Caverns of Time!  That should be a perfect place, and long enough, to get things on line!" "Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!"]],logDesc=[[Escort OOX-17/TN to safety, then report to Oglethorpe Obnoticus in Booty Bay.]],choiceRewards={{id=9643,qty=1},{id=9644,qty=1}}}
DB[649]={id=649,zoneId=1637,name=[[Ripple Recovery]],name_loc=[[Recupera el calimocho]],level=48,minLevel=42,giver=[[Dran Droffers]],giver_loc=[[Dran Droffers]],giverType=[[NPC]],giverId=6986,ender=[[Malton Droffers]],ender_loc=[[Malton Droffers]],enderType=[[NPC]],enderId=6987,rewardNextId=650,poiX=1928,poiY=-4517,wowhead=[[https://www.wowhead.com/wotlk/quest=649]],image=[[assets/images/quests/placeholder.png]],desc=[[I've got some salvage work for you, and if you're an aficionado of fine ripple like I am, then you'll love this task.  Ripple! It's a drink, you dummy. An abandoned Horde outpost has a stash of Hinterlands Honey Ripple from when they were in business.  You can't get fine ripple like that anymore!  One of Malton's dummy associates knows the shot, so you'll go out there and bring me a case of packaged ripple, and two for my own collection!  Talk to Malton, he'll fill you in on the details.]],logDesc=[[Talk to Malton Droffers in Orgrimmar.]]}
DB[650]={id=650,zoneId=1637,name=[[Ripple Recovery]],name_loc=[[Recupera el calimocho]],level=48,minLevel=42,giver=[[Malton Droffers]],giver_loc=[[Malton Droffers]],giverType=[[NPC]],giverId=6987,ender=[[Gilveradin Sunchaser]],ender_loc=[[Gilveradin Cazasol]],enderType=[[NPC]],enderId=7801,prevId=649,rewardNextId=77,poiX=219,poiY=-2603,wowhead=[[https://www.wowhead.com/wotlk/quest=650]],image=[[assets/images/quests/placeholder.png]],desc=[[The elf you will need to talk to is Gilveradin Sunchaser.  He can name any wine, vintage and all, just by smell alone!  He can package up the ripple we need, so you'll need to talk with him.  We need six bottles for packaging, two for dad, and how ever many he'll want... and believe me, he'll want some.  When you've packaged the ripple and got dad's two bottles, come back here! Gilveradin's camp is near some high elf lodge in the Hinterlands, and those high elves are not good.  Trust me.]],logDesc=[[Talk to Gilveradin Sunchaser; his camp is located in the Hinterlands.]]}
DB[651]={id=651,zoneId=45,name=[[Stones of Binding]],name_loc=[[Piedras de Vínculo]],level=38,minLevel=30,giver=[[Iridescent Shards]],giver_loc=[[Fragmentos iridiscentes]],giverType=[[GO]],giverId=2701,ender=[[Stone of Inner Binding]],ender_loc=[[Piedra de Vínculo Interior]],enderType=[[GO]],enderId=2702,prevId=642,rewardNextId=652,poiX=-856,poiY=-1783,wowhead=[[https://www.wowhead.com/wotlk/quest=651]],image=[[assets/images/quests/placeholder.png]],desc=[[Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth. To unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three. These stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them.]],logDesc=[[Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding. Bring them to the Stone of Inner Binding.]]}
DB[652]={id=652,zoneId=45,name=[[Breaking the Keystone]],name_loc=[[Desbloquear la piedra angular]],level=42,minLevel=30,giver=[[Stone of Inner Binding]],giver_loc=[[Piedra de Vínculo Interior]],giverType=[[GO]],giverId=2702,ender=[[Keystone]],ender_loc=[[Piedra angular]],enderType=[[GO]],enderId=2688,prevId=651,poiX=-1528,poiY=-2165,wowhead=[[https://www.wowhead.com/wotlk/quest=652]],image=[[assets/images/quests/placeholder.png]],desc=[[Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk. You must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone. $N, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!]],logDesc=[[Find and kill Fozruk.  Bring the Rod of Order to the Keystone in the Arathi Highlands.]]}
DB[653]={id=653,zoneId=45,name=[[Myzrael's Allies]],name_loc=[[Aliados de Myzrael]],level=40,minLevel=30,giver=[[Keystone]],giver_loc=[[Piedra angular]],giverType=[[GO]],giverId=2688,ender=[[Gerrig Bonegrip]],ender_loc=[[Gerrig Agarrahueso]],enderType=[[NPC]],enderId=2786,prevId=652,nextId=687,rewardNextId=687,poiX=-4599,poiY=-1115,wowhead=[[https://www.wowhead.com/wotlk/quest=653]],image=[[assets/images/quests/placeholder.png]],desc=[[<Myzrael speaks.> Free!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me. But in time I will confront the giants, and they will regret their wardship of me! You are a noble ally, $N.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface. Speak with Gerrig Bonegrip.  He is in Ironforge, in a shop of the Forlorn Cavern.  He knows how I can be summoned.]],logDesc=[[Speak with Gerrig Bonegrip in the Forlorn Cavern of Ironforge.]]}
DB[654]={id=654,zoneId=440,name=[[Tanaris Field Sampling]],name_loc=[[Recogida de muestras en Tanaris]],level=46,minLevel=38,giverType=[[NPC]],ender=[[Chief Engineer Bilgewhizzle]],ender_loc=[[Ingeniero jefe Pasaquillas]],enderType=[[NPC]],enderId=7407,prevId=379,rewardNextId=864,poiX=-7187,poiY=-3839,wowhead=[[https://www.wowhead.com/wotlk/quest=654]],image=[[assets/images/quests/placeholder.png]],desc=[[Activating the power source makes the field testing kit start to glow and vibrate.  It would seem to be working as planned. I will have it shipped immediately. According to Chief Engineer Bilgewhizzle, you now have some time to collect the data you need in the Tanaris desert. Return to him when you have completed the task.]],logDesc=[[Acquire untested samples for 8 basilisks, 8 hyenas, and 8 scorpions.  Bring the testing kit back to Chief Engineer Bilgewhizzle in Gadgetzan before the power source runs out.]]}
DB[655]={id=655,zoneId=45,name=[[Hammerfall]],name_loc=[[Sentencia]],level=34,minLevel=29,giver=[[Gor'mul]],giverType=[[NPC]],giverId=2792,ender=[[Tor'gan]],enderType=[[NPC]],enderId=2706,rewardNextId=672,poiX=-1004,poiY=-3557,wowhead=[[https://www.wowhead.com/wotlk/quest=655]],image=[[assets/images/quests/placeholder.png]],desc=[[It is still clear to me, like yesterday... So many years without hope, with wood and steel to bind me to this terrible place. Then finally, finally! There was the Warchief. Doomhammer in his midnight plate, his warhammer held high. It was... too terrible... That the blow of a coward would strike down our greatest hero. From behind he charged on his horse, and then his lance ran him through... I fell to my knees. What hope was there? What hope is there...]],logDesc=[[Speak with Tor'gan in Hammerfall.]]}
DB[656]={id=656,zoneId=45,name=[[Summoning the Princess]],name_loc=[[Invocar a la princesa]],level=50,minLevel=30,giver=[[Theldurin the Lost]],giver_loc=[[Theldurin el Perdido]],giverType=[[NPC]],giverId=2785,ender=[[Shards of Myzrael]],ender_loc=[[Fragmentos de Myzrael]],enderType=[[GO]],enderId=138492,prevId=692,poiX=-943,poiY=-3120,wowhead=[[https://www.wowhead.com/wotlk/quest=656]],image=[[assets/images/quests/placeholder.png]],desc=[[You must defeat Myzrael before she grows in strength.  If you do not, then once she has gathered enough power she will challenge her captors!  There are some who think they can control her, but if she can be controlled then why did the giants chain her in the first place?? Crazy logic, eh? To defeat her, summon her at the Shards of Myzrael where you first spoke with her.  Defeat her and gather her Eldritch Shackles, then bind them to the Shards of Myzrael. Do that, and she will again be trapped.]],logDesc=[[Go to the Shards of Myzrael, summon her and defeat her. Gather her Eldritch Shackles and bind them to the Shards of Myzrael.]],rewards={{id=4743,qty=1}}}
DB[657]={id=657,zoneId=267,name=[[Hints of a New Plague?]],name_loc=[[Sospechas de una nueva Peste]],level=36,minLevel=30,giver=[[Quae]],giverType=[[NPC]],giverId=2712,ender=[[Kinelory]],enderType=[[NPC]],enderId=2713,prevId=658,poiX=-1427,poiY=-3035,wowhead=[[https://www.wowhead.com/wotlk/quest=657]],image=[[assets/images/quests/placeholder.png]],desc=[[<Quae begins to go through the folder.> This IS interesting. Seems Apothecary Jorell has been working on some deadly experiments here at Go'Shek. Not sure what that has to do with Hillsbrad, but Phin wouldn't like it if we let it continue. We had a run-in with some orcs while you were gone, and I'm not in good enough shape to help Kinelory. If you're up for it, she's going to need some protection when she goes down to the farm to steal whatever research Jorell still hasn't sent to Tarren Mill.]],logDesc=[[Speak to Kinelory near Go'Shek Farm in Arathi Highlands.]]}
DB[658]={id=658,zoneId=267,name=[[Hints of a New Plague?]],name_loc=[[Sospechas de una nueva Peste]],level=36,minLevel=30,giver=[[Quae]],giverType=[[NPC]],giverId=2712,ender=[[Quae]],enderType=[[NPC]],enderId=2712,prevId=659,rewardNextId=657,poiX=-1552,poiY=-3035,wowhead=[[https://www.wowhead.com/wotlk/quest=658]],image=[[assets/images/quests/placeholder.png]],desc=[[So, Phin sent you to check on us? Not surprised--he worries too much. We've been watching the farm for days, and Kin claims she saw a courier come out of that small house to the south not long ago. She talks a lot, but I can always trust her senses when we're in dangerous areas. You wouldn't happen to be a skilled tracker, would you? We think the courier might be carrying notes to Tarren Mill. If we could get our hands on those documents, it might shed some light on what's happening in Hillsbrad.]],logDesc=[[Find the Forsaken Courier and bring back her Sealed Folder to Quae near the Go'Shek Farm.]]}
DB[659]={id=659,zoneId=267,name=[[Hints of a New Plague?]],name_loc=[[Sospechas de una nueva Peste]],level=33,minLevel=30,giver=[[Phin Odelic]],giverType=[[NPC]],giverId=2711,ender=[[Quae]],enderType=[[NPC]],enderId=2712,rewardNextId=658,poiX=-1426,poiY=-3033,wowhead=[[https://www.wowhead.com/wotlk/quest=659]],image=[[assets/images/quests/placeholder.png]],desc=[[Hail, and well met, $N. I lead a group of adventurers investigating odd happenings in this area. My cousin in Hillsbrad recently put down his dog Stanley because the animal mystically grew to an immense size and savagely attacked anyone who came near him. I believe the undead are involved, and we're looking for signs to prove as much. Two of my companions, Quae and Kinelory, headed to the Go'Shek Farm in the Arathi Highlands, and haven't checked in for days. Find them for me? I grow concerned.]],logDesc=[[Find Quae and Kinelory near the Go'Shek Farm in the Arathi Highlands.]]}
DB[660]={id=660,zoneId=267,name=[[Hints of a New Plague?]],name_loc=[[Sospechas de una nueva Peste]],level=37,minLevel=30,giver=[[Kinelory]],giverType=[[NPC]],giverId=2713,ender=[[Quae]],enderType=[[NPC]],enderId=2712,prevId=657,rewardNextId=661,poiX=-1426,poiY=-3033,wowhead=[[https://www.wowhead.com/wotlk/quest=660]],image=[[assets/images/quests/placeholder.png]],desc=[[All right, $N. I'm ready if you are. Shall we?]],logDesc=[[Protect Kinelory until she returns to Quae.]]}
DB[661]={id=661,zoneId=267,name=[[Hints of a New Plague?]],name_loc=[[Sospechas de una nueva Peste]],level=37,minLevel=30,giver=[[Quae]],giverType=[[NPC]],giverId=2712,ender=[[Phin Odelic]],enderType=[[NPC]],enderId=2711,prevId=660,poiX=-860,poiY=-544,wowhead=[[https://www.wowhead.com/wotlk/quest=661]],image=[[assets/images/quests/placeholder.png]],desc=[[I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her. These items she brought back from the farm should at least let Phin get an idea of what's going on out here in Arathi. Just to make sure there's no retaliation after your attack, we're going to stay here for a bit longer. Would you be willing to head back to Southshore and talk to Phin?]],logDesc=[[Find Phin Odelic at Southshore in Hillsbrad Foothills.]],choiceRewards={{id=15455,qty=1},{id=15456,qty=1}}}
DB[662]={id=662,zoneId=45,name=[[Deep Sea Salvage]],name_loc=[[Rescate en alta mar]],level=40,minLevel=35,giver=[[First Mate Nilzlix]],giver_loc=[[Contramaestre Nizlix]],giverType=[[NPC]],giverId=2767,ender=[[First Mate Nilzlix]],ender_loc=[[Contramaestre Nizlix]],enderType=[[NPC]],enderId=2767,prevId=663,poiX=-2162,poiY=-1696,wowhead=[[https://www.wowhead.com/wotlk/quest=662]],image=[[assets/images/quests/placeholder.png]],desc=[[O'Breen led the ships into the cove.  We were certain this is where the treasure could be found.  The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower.  Strangest thing I've ever seen! Those two ships ran aground into something... some sort of temple in the reef.  They sank so quickly, was quite a tragedy. We need to retrieve their Logs as well as their Charts before we leave.  We can't leave that information behind for prying eyes!]],logDesc=[[First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine.]],rewards={{id=4511,qty=1}}}
DB[663]={id=663,zoneId=45,name=[[Land Ho!]],name_loc=[[¡Tierra a vista!]],level=35,minLevel=35,giver=[[Lolo the Lookout]],giver_loc=[[Lolo el Oteador]],giverType=[[NPC]],giverId=2766,ender=[[Shakes O'Breen]],ender_loc=[[Temblores O'Breen]],enderType=[[NPC]],enderId=2610,poiX=-2086,poiY=-2029,wowhead=[[https://www.wowhead.com/wotlk/quest=663]],image=[[assets/images/quests/placeholder.png]],desc=[[Lolo sees a tiny $r! Always on the lookout, Lolo is! Welcome to Faldir's Cove.  Captain O'Breen said we'd only be here for a few hours.  Just long enough to gather the treasure and get back to Booty Bay. But Lolo thinks we're going to be here a lot longer than that.  We lost the other two ships from our formation.  Poor Spirit of Silverpine and Maiden's Folly.  On the bottom of the sea they rest now! Lolo suggests you talk to Captain O'Breen if you plan on sticking around here.]],logDesc=[[Talk to Captain O'Breen at Faldir's Cove in Arathi Highlands.]]}
DB[664]={id=664,zoneId=45,name=[[Drowned Sorrows]],name_loc=[[Ahogar las penas]],level=40,minLevel=35,giver=[[Captain Steelgut]],giver_loc=[[Capitán Tripacero]],giverType=[[NPC]],giverId=2769,ender=[[Captain Steelgut]],ender_loc=[[Capitán Tripacero]],enderType=[[NPC]],enderId=2769,prevId=663,poiX=-2225,poiY=-1784,wowhead=[[https://www.wowhead.com/wotlk/quest=664]],image=[[assets/images/quests/placeholder.png]],desc=[[Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air. The crew tried so hard to save my beautiful Maiden's Folly. Bless the boys, bless their hearts. O'Breen made it to shore safely but we weren't so lucky. The seas just sank on us, I swear. One second we're afloat and the next water is rushin' in. And those beasts! Killed all the survivors. Horrible naga scum. I went black and ended up here, saved. I want those beasts dead.]],logDesc=[[Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.]],rewards={{id=4509,qty=1}}}
DB[665]={id=665,zoneId=45,name=[[Sunken Treasure]],name_loc=[[El tesoro sumergido]],level=40,minLevel=35,giver=[[Professor Phizzlethorpe]],giver_loc=[[Profesor Fiseltor]],giverType=[[NPC]],giverId=2768,ender=[[Doctor Draxlegauge]],ender_loc=[[Doctor Draxlegauge]],enderType=[[NPC]],enderId=2774,prevId=663,rewardNextId=666,poiX=-2064,poiY=-2085,wowhead=[[https://www.wowhead.com/wotlk/quest=665]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure. It is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill. But the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles.]],logDesc=[[Escort Professor Phizzlethorpe to the cave and back.]]}
DB[666]={id=666,zoneId=45,name=[[Sunken Treasure]],name_loc=[[El tesoro sumergido]],level=40,minLevel=35,giver=[[Doctor Draxlegauge]],giver_loc=[[Doctor Draxlegauge]],giverType=[[NPC]],giverId=2774,ender=[[Doctor Draxlegauge]],ender_loc=[[Doctor Draxlegauge]],enderType=[[NPC]],enderId=2774,prevId=665,rewardNextId=668,poiX=-2278,poiY=-1764,wowhead=[[https://www.wowhead.com/wotlk/quest=666]],image=[[assets/images/quests/placeholder.png]],desc=[[The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily. A little gnomish ingenuity goes a long way! So borrow the Goggles of Gem Hunting, $n, and see if you can collect some of the lost treasure for Captain O'Breen. I'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah.]],logDesc=[[Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.]],choiceRewards={{id=4547,qty=1},{id=4548,qty=1}}}
DB[667]={id=667,zoneId=45,name=[[Death From Below]],name_loc=[[Muerte desde abajo]],level=44,minLevel=35,giver=[[Shakes O'Breen]],giver_loc=[[Temblores O'Breen]],giverType=[[NPC]],giverId=2610,ender=[[Shakes O'Breen]],ender_loc=[[Temblores O'Breen]],enderType=[[NPC]],enderId=2610,prevId=670,poiX=-2086,poiY=-2029,wowhead=[[https://www.wowhead.com/wotlk/quest=667]],image=[[assets/images/quests/placeholder.png]],desc=[[This is bad. It seems the Daggerspines are amassing for an attack. Naga are known for their ruthlessness in battle. They will keep attacking until I am dead. I don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas. The naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back. Are you ready, $n?]],logDesc=[[Protect Shakes O'Breen during the attack.]],choiceRewards={{id=4550,qty=1},{id=4549,qty=1}}}
DB[668]={id=668,zoneId=45,name=[[Sunken Treasure]],name_loc=[[El tesoro sumergido]],level=40,minLevel=35,giver=[[Doctor Draxlegauge]],giver_loc=[[Doctor Draxlegauge]],giverType=[[NPC]],giverId=2774,ender=[[Shakes O'Breen]],ender_loc=[[Temblores O'Breen]],enderType=[[NPC]],enderId=2610,prevId=666,rewardNextId=669,poiX=-2086,poiY=-2029,wowhead=[[https://www.wowhead.com/wotlk/quest=668]],image=[[assets/images/quests/placeholder.png]],desc=[[Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here! And after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure. Here, $n, take these to O'Breen.]],logDesc=[[Take the Elven Gems to Captain O'Breen at Faldir's Cove in Arathi Highlands.]]}
DB[669]={id=669,zoneId=45,name=[[Sunken Treasure]],name_loc=[[El tesoro sumergido]],level=40,minLevel=35,giver=[[Shakes O'Breen]],giver_loc=[[Temblores O'Breen]],giverType=[[NPC]],giverId=2610,ender=[[Fleet Master Seahorn]],ender_loc=[[Maestro de flota Cuernomarino]],enderType=[[NPC]],enderId=2487,prevId=668,rewardNextId=670,poiX=-14445,poiY=487,wowhead=[[https://www.wowhead.com/wotlk/quest=669]],image=[[assets/images/quests/placeholder.png]],desc=[[Fleet Master Seahorn will want to hear about our find at once. But as you can see, we're not in much of a position to get out of here. Not only is the tide too low, but those damned creatures we disrupted are keeping a close eye on our movements. You can be of great service to the Blackwater Raiders if you can get word to Fleet Master Seahorn in Booty Bay that we discovered the treasure and are working on extracting more.  Take him this sample as proof.]],logDesc=[[Take the Sample Elven Gem to Fleet Master Seahorn at Booty Bay in Stranglethorn Vale.]]}
DB[670]={id=670,zoneId=45,name=[[Sunken Treasure]],name_loc=[[El tesoro sumergido]],level=40,minLevel=35,giver=[[Fleet Master Seahorn]],giver_loc=[[Maestro de flota Cuernomarino]],giverType=[[NPC]],giverId=2487,ender=[[Shakes O'Breen]],ender_loc=[[Temblores O'Breen]],enderType=[[NPC]],enderId=2610,prevId=669,poiX=-2086,poiY=-2029,wowhead=[[https://www.wowhead.com/wotlk/quest=670]],image=[[assets/images/quests/placeholder.png]],desc=[[Say, $n, you seem to be an adventurous type. My fleet is stuck in Booty Bay until we can restock. There are some heavy things brewing here and abroad and I need to get some top secret correspondence to Shakes O'Breen who is tied up off the Arathi coast. Can I trust you to deliver this message safely and in confidence?]],logDesc=[[Deliver Seahorn's Letter to Shakes O'Breen at Faldir's Cove in Arathi Highlands.]]}
DB[671]={id=671,zoneId=45,name=[[Foul Magics]],name_loc=[[Magia demoníaca]],level=33,minLevel=30,giver=[[Tor'gan]],giverType=[[NPC]],giverId=2706,ender=[[Tor'gan]],enderType=[[NPC]],enderId=2706,poiX=-850,poiY=-2121,wowhead=[[https://www.wowhead.com/wotlk/quest=671]],image=[[assets/images/quests/placeholder.png]],desc=[[I have felt a strangeness in the air... a feeling that simmers in my blood. I had my suspicions. I set off to find the source of my unease and discovered to the west, at Northfold Manor, the residual traces of demonic summoning. As I got close, my blood began to boil and the rage within me grew. On the ground I spied an amulet of bloodstone, used to assist in demonic summoning. The one I found was depleted, however. I'll need another to examine, but I dare not return to the manor. Can you bring me some?]],logDesc=[[Get 10 Bloodstone Amulets for Tor'gan in Hammerfall.]]}
DB[672]={id=672,zoneId=45,name=[[Raising Spirits]],name_loc=[[El despertar de los espíritus]],level=34,minLevel=29,giver=[[Tor'gan]],giverType=[[NPC]],giverId=2706,ender=[[Tor'gan]],enderType=[[NPC]],enderId=2706,prevId=655,rewardNextId=674,poiX=-984,poiY=-3385,wowhead=[[https://www.wowhead.com/wotlk/quest=672]],image=[[assets/images/quests/placeholder.png]],desc=[[We tried to settle him in, cheer him up, telling him stories of our mighty city at Orgrimmar in Kalimdor, but nothing would move him. Tales of our young Warchief, Thrall, who bears the armor and hammer of Orgrim... but, perhaps... Perhaps! A demonstration of our newly found shamanistic magic would give him new hope. It is worth a try! A small object we could make for him, yes... Bring me some raptor eyes, and I will see what I can do.]],logDesc=[[Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall.]]}
DB[673]={id=673,zoneId=45,name=[[Foul Magics]],name_loc=[[Magia demoníaca]],level=40,minLevel=35,giver=[[Tor'gan]],giverType=[[NPC]],giverId=2706,ender=[[Tor'gan]],enderType=[[NPC]],enderId=2706,prevId=671,poiX=-1673,poiY=-1928,wowhead=[[https://www.wowhead.com/wotlk/quest=673]],image=[[assets/images/quests/placeholder.png]],desc=[[There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of his energy. Find the warlock and kill him. Bring me whatever magical object you find on his person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.]],logDesc=[[Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.]],choiceRewards={{id=4543,qty=1},{id=4545,qty=1}}}
DB[674]={id=674,zoneId=45,name=[[Raising Spirits]],name_loc=[[El despertar de los espíritus]],level=34,minLevel=29,giver=[[Tor'gan]],giverType=[[NPC]],giverId=2706,ender=[[Gor'mul]],enderType=[[NPC]],enderId=2792,prevId=672,rewardNextId=675,poiX=-948,poiY=-3482,wowhead=[[https://www.wowhead.com/wotlk/quest=674]],image=[[assets/images/quests/placeholder.png]],desc=[[Here, take this amulet to Gor'mul, and see if the raptors' strength can awaken the flame of the warrior that once burned through his veins.]],logDesc=[[Give the Raptor Talon Amulet to Gor'mul at Hammerfall in Arathi Highlands.]]}
DB[675]={id=675,zoneId=45,name=[[Raising Spirits]],name_loc=[[El despertar de los espíritus]],level=34,minLevel=29,giver=[[Gor'mul]],giverType=[[NPC]],giverId=2792,ender=[[Tor'gan]],enderType=[[NPC]],enderId=2706,prevId=674,rewardNextId=701,poiX=-1004,poiY=-3557,wowhead=[[https://www.wowhead.com/wotlk/quest=675]],image=[[assets/images/quests/placeholder.png]],desc=[[<Gor'mul tosses the amulet into the ground.> Tor'gan sent you, didn't he? Pah! Why he feels some mercy towards me I would not understand. Mercy was denied me when I was not allowed to die with my Warchief in battle. A cruel blow fate has dealt me...]],logDesc=[[Speak with Tor'gan at Hammerfall in Arathi Highlands.]]}
DB[676]={id=676,zoneId=267,name=[[The Hammer May Fall]],name_loc=[[La Sentencia]],level=32,minLevel=30,giver=[[Tallow]],giver_loc=[[Sebo]],giverType=[[NPC]],giverId=2770,ender=[[Drum Fel]],ender_loc=[[Bombo Vil]],enderType=[[NPC]],enderId=2771,rewardNextId=677,poiX=-1251,poiY=-2221,wowhead=[[https://www.wowhead.com/wotlk/quest=676]],image=[[assets/images/quests/placeholder.png]],desc=[[Weaklings... all of them. You, $c, what are you looking at? Think you're something special, huh? Why not prove it? The Hammerfall outpost in Arathi's under attack. Unless we send them help soon, their demise is imminent. But before you go rushing off, you may want to test your skills first. Northeast of Stromgarde in Arathi is an ogre mound inhabited by the Boulderfist tribe. When you can handle the ogres and enforcers there, then report to Drum Fel in Hammerfall.]],logDesc=[[Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands.]]}
DB[677]={id=677,zoneId=45,name=[[Call to Arms]],name_loc=[[Un llamamiento a las armas]],level=32,minLevel=30,giver=[[Drum Fel]],giver_loc=[[Bombo Vil]],giverType=[[NPC]],giverId=2771,ender=[[Drum Fel]],ender_loc=[[Bombo Vil]],enderType=[[NPC]],enderId=2771,prevId=676,rewardNextId=678,poiX=-1703,poiY=-3533,wowhead=[[https://www.wowhead.com/wotlk/quest=677]],image=[[assets/images/quests/placeholder.png]],desc=[[The Witherbark trolls and Boulderfist ogres of Arathi are working together to rid us from this land, but we shall not meet our fates at their, or anyone else's, hand. We will slay them and show them that we, too, have a home here.  The trolls turned their backs to us; the ogres would use us for food and bedding if we allowed them to--these things shall not be. We start our attack on the Witherbark trolls to the south of here. Slay them in droves, and only return when their camps run thick with blood.]],logDesc=[[Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost.]]}
DB[678]={id=678,zoneId=45,name=[[Call to Arms]],name_loc=[[Un llamamiento a las armas]],level=38,minLevel=30,giver=[[Drum Fel]],giver_loc=[[Bombo Vil]],giverType=[[NPC]],giverId=2771,ender=[[Drum Fel]],ender_loc=[[Bombo Vil]],enderType=[[NPC]],enderId=2771,prevId=677,rewardNextId=679,poiX=-1876,poiY=-2851,wowhead=[[https://www.wowhead.com/wotlk/quest=678]],image=[[assets/images/quests/placeholder.png]],desc=[[Your strength is evident, $N. Now to see how you fare against a real enemy. The Boulderfists have a lair to the southwest of here towards the dwarven bridge, and, if I'm not mistaken, the maulers and magi there shall present to you a greater challenge--they have done so to us thus far. Slay as many as you can and come to me in body when you are successful, or come to me in spirit when you fail. I shall give praise to your tenacity in battle either way.]],logDesc=[[Kill 10 Boulderfist Brutes and 4 Boulderfist Magi, and return to Drum Fel in the Hammerfall outpost.]]}
DB[679]={id=679,zoneId=45,name=[[Call to Arms]],name_loc=[[Un llamamiento a las armas]],level=40,minLevel=30,giver=[[Drum Fel]],giver_loc=[[Bombo Vil]],giverType=[[NPC]],giverId=2771,ender=[[Drum Fel]],ender_loc=[[Bombo Vil]],enderType=[[NPC]],enderId=2771,prevId=678,poiX=-1741,poiY=-1644,wowhead=[[https://www.wowhead.com/wotlk/quest=679]],image=[[assets/images/quests/placeholder.png]],desc=[[The head of the beast is ready to be taken off... with great force, $N. You have shown every sign that you are able to help us with this final mighty blow. The leaders of these attacks have made their lair within the ruins of Stromgarde, a glaring symbol of human frailty. Find and slay those Boulderfist lords and their lackey shaman who would try and drive us from these lands.]],logDesc=[[Kill 7 Boulderfist Shaman and 3 Boulderfist Lords and return to Drum Fel in the Hammerfall outpost.]],choiceRewards={{id=9520,qty=1},{id=9521,qty=1}}}
DB[680]={id=680,zoneId=45,name=[[The Real Threat]],name_loc=[[Una auténtica amenaza]],level=40,minLevel=30,giver=[[Korin Fel]],giver_loc=[[Korin Vil]],giverType=[[NPC]],giverId=2772,ender=[[Korin Fel]],ender_loc=[[Korin Vil]],enderType=[[NPC]],enderId=2772,poiX=-927,poiY=-3532,wowhead=[[https://www.wowhead.com/wotlk/quest=680]],image=[[assets/images/quests/placeholder.png]],desc=[[You serve my husband well, $c, but he does not know why Hammerfall is under attack. Or'Kalar, Mug'thol's pawn in Stromgarde, has an intense hatred for my husband, and wishes nothing more than my husband's death for defeating him years ago. My auguries tell me that Or'Kalar has laid a trap for my husband, so I have hidden signs of the ogre's presence from him. My husband will rush off foolishly if he learns of the ogre's whereabouts and I would ask for your help in slaying the creature.]],logDesc=[[Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost.]],choiceRewards={{id=4976,qty=1},{id=4977,qty=1}}}
DB[681]={id=681,zoneId=45,name=[[Northfold Manor]],name_loc=[[Mansión Redilnorte]],level=31,minLevel=30,giver=[[Captain Nials]],giver_loc=[[Capitana Nials]],giverType=[[NPC]],giverId=2700,ender=[[Captain Nials]],ender_loc=[[Capitana Nials]],enderType=[[NPC]],enderId=2700,poiX=-850,poiY=-2121,wowhead=[[https://www.wowhead.com/wotlk/quest=681]],image=[[assets/images/quests/placeholder.png]],desc=[[We are fighting a war for Stromgarde, and we are losing.  The ogres, the Syndicate and we have divided our once great city, and each faction battles the other into a bloody stalemate. But our forces dwindle while our enemy grows. We need help from the town of Southshore, but supplies are difficult to receive while the Syndicate holds territory between us. Go to the Syndicate base in Northfold Manor and slay them.  Then, perhaps, pressure on our supply trains will lessen and more will get through.]],logDesc=[[Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries. Return to Captain Nials at Refuge Pointe.]]}
DB[682]={id=682,zoneId=45,name=[[Stromgarde Badges]],name_loc=[[Distintivos de Stromgarde]],level=37,minLevel=30,giver=[[Captain Nials]],giver_loc=[[Capitana Nials]],giverType=[[NPC]],giverId=2700,ender=[[Captain Nials]],ender_loc=[[Capitana Nials]],enderType=[[NPC]],enderId=2700,prevId=681,poiX=-1633,poiY=-1934,wowhead=[[https://www.wowhead.com/wotlk/quest=682]],image=[[assets/images/quests/placeholder.png]],desc=[[The Syndicate in Stromgarde do battle with our contingent of militia there. In order to urge the rabble to fight our more disciplined troops, the Syndicate leaders have placed a bounty on our soldiers, awarding gold for each Stromgarde Badge gathered off killed militiamen. We want those badges retrieved - we cannot allow the cutthroats to take trophies from our brave fallen! Enter the Syndicate-controlled area of Stromgarde and hunt them for our badges.]],logDesc=[[Bring 7 Stromgarde Badges to Captain Nials at Refuge Pointe.]],rewards={{id=4741,qty=1}}}
DB[683]={id=683,zoneId=1537,name=[[Sara Balloo's Plea]],name_loc=[[La petición de Sara Balloo]],level=30,minLevel=25,giver=[[Sara Balloo]],giverType=[[NPC]],giverId=2695,ender=[[King Magni Bronzebeard]],ender_loc=[[Rey Magni Barbabronce]],enderType=[[NPC]],enderId=2784,prevId=637,poiX=-4866,poiY=-1023,wowhead=[[https://www.wowhead.com/wotlk/quest=683]],image=[[assets/images/quests/placeholder.png]],desc=[[$n, I have but a small request to ask of you. Take this note I have prepared to our great monarch of Ironforge, King Magni Bronzebeard. 'Tis a small task to ask of one such as yourself, someone who has shown great valor to the cause of the Alliance thus far. For me to go before the King in my grief-ridden state would not serve the purpose of my cause.  Surely you understand.]],logDesc=[[Take Sara Balloo's note to King Magni Bronzebeard of Ironforge.]]}
DB[684]={id=684,zoneId=45,name=[[Wanted!  Marez Cowl]],name_loc=[[Se busca: Marez Cogulla]],level=39,minLevel=29,giver=[[Wanted Board]],giver_loc=[[Tablón de Se busca]],giverType=[[GO]],giverId=2713,ender=[[Captain Nials]],ender_loc=[[Capitana Nials]],enderType=[[NPC]],enderId=2700,poiX=-1673,poiY=-1928,wowhead=[[https://www.wowhead.com/wotlk/quest=684]],image=[[assets/images/quests/placeholder.png]],desc=[[A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate.  She was last seen within the Syndicate controlled territory of Stromgarde. Bounty may be collected from Captain Nials. Be warned: Marez is a skilled and cunning Warlock, known for her trafficking with demons.  Extreme caution is advised when hunting her.]],logDesc=[[Bring Marez's head to Captain Nials at Refuge Pointe.]],rewards={{id=4744,qty=1}}}
DB[685]={id=685,zoneId=45,name=[[Wanted!  Otto and Falconcrest]],name_loc=[[Se busca: Otto y Lord Falconcrest]],level=40,minLevel=29,giver=[[Wanted Board]],giver_loc=[[Tablón de Se busca]],giverType=[[GO]],giverId=2713,ender=[[Captain Nials]],ender_loc=[[Capitana Nials]],enderType=[[NPC]],enderId=2700,poiX=-1707,poiY=-1811,wowhead=[[https://www.wowhead.com/wotlk/quest=685]],image=[[assets/images/quests/placeholder.png]],desc=[[The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto.  Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts. His bodyguard Otto, although not a strategic target, is a fierce opponent and has killed dozens of our defenders. Their bounties may be collected from Captain Nials.]],logDesc=[[Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.]],choiceRewards={{id=5247,qty=1},{id=4745,qty=1}}}
DB[686]={id=686,zoneId=1537,name=[[A King's Tribute]],name_loc=[[Un homenaje real]],level=30,minLevel=25,giver=[[King Magni Bronzebeard]],giver_loc=[[Rey Magni Barbabronce]],giverType=[[NPC]],giverId=2784,ender=[[Grand Mason Marblesten]],ender_loc=[[Gran mampostero Marmolez]],enderType=[[NPC]],enderId=2790,prevId=683,rewardNextId=689,poiX=-5028,poiY=-1020,wowhead=[[https://www.wowhead.com/wotlk/quest=686]],image=[[assets/images/quests/placeholder.png]],desc=[[I do not expect good dwarves like Mrs. Balloo to understand why the travesties of war must be endured for the greater good of our people. The loss of her husband, and the loss of every dwarf that fights in the name of the Alliance, weighs heavy on my soul. While I cannot bring her husband back from the Twisting Nether, I can pay tribute to him. I am going to commission a memorial to Sully Balloo to be built by Grand Mason Marblesten. Send word to him now, $c. You shall be custodian of my bidding.]],logDesc=[[King Magni Bronzebeard wants you to speak with Grand Mason Marblesten.]]}
DB[687]={id=687,zoneId=45,name=[[Theldurin the Lost]],name_loc=[[Theldurin el Perdido]],level=40,minLevel=30,giver=[[Gerrig Bonegrip]],giver_loc=[[Gerrig Agarrahueso]],giverType=[[NPC]],giverId=2786,ender=[[Theldurin the Lost]],ender_loc=[[Theldurin el Perdido]],enderType=[[NPC]],enderId=2785,rewardNextId=692,poiX=-7164,poiY=-3357,wowhead=[[https://www.wowhead.com/wotlk/quest=687]],image=[[assets/images/quests/placeholder.png]],desc=[[Theldurin the Lost was once a member of our order, the Twilight's Hammer.  But he lost his mind and scorned our teachings.  And before he fled from us, he stole the scroll of Myzrael!  We could not catch him, but rumors say he hides in the Badlands, gibbering and mad. To bring the Lady back to us, you must find the scroll.  And to do that, you must find Theldurin.]],logDesc=[[Find Theldurin the Lost.]]}
DB[687]={id=687,zoneId=45,name=[[Theldurin the Lost]],name_loc=[[Theldurin el Perdido]],level=40,minLevel=30,giver=[[Zaruk]],giver_loc=[[Gerrig Agarrahueso]],giverType=[[NPC]],giverId=2787,ender=[[Theldurin the Lost]],ender_loc=[[Theldurin el Perdido]],enderType=[[NPC]],enderId=2785,rewardNextId=692,poiX=-7164,poiY=-3357,wowhead=[[https://www.wowhead.com/wotlk/quest=687]],image=[[assets/images/quests/placeholder.png]],desc=[[Theldurin the Lost was once a member of our order, the Twilight's Hammer.  But he lost his mind and scorned our teachings.  And before he fled from us, he stole the scroll of Myzrael!  We could not catch him, but rumors say he hides in the Badlands, gibbering and mad. To bring the Lady back to us, you must find the scroll.  And to do that, you must find Theldurin.]],logDesc=[[Find Theldurin the Lost.]]}
DB[688]={id=688,zoneId=45,name=[[Myzrael's Allies]],name_loc=[[Aliados de Myzrael]],level=40,minLevel=30,giver=[[Keystone]],giver_loc=[[Piedra angular]],giverType=[[GO]],giverId=2688,ender=[[Zaruk]],enderType=[[NPC]],enderId=2787,prevId=652,nextId=687,rewardNextId=687,poiX=-989,poiY=-3550,wowhead=[[https://www.wowhead.com/wotlk/quest=688]],image=[[assets/images/quests/placeholder.png]],desc=[[<Myzrael speaks.> Free!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me. But in time I will confront the giants, and they will regret their wardship of me! You are a noble ally, $N.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface Speak with Zaruk in Hammerfall.  He knows how I can be summoned.]],logDesc=[[Speak with Zaruk at Hammerfall in Arathi Highlands.]]}
DB[689]={id=689,zoneId=1537,name=[[A King's Tribute]],name_loc=[[Un homenaje real]],level=31,minLevel=25,giver=[[Grand Mason Marblesten]],giver_loc=[[Gran mampostero Marmolez]],giverType=[[NPC]],giverId=2790,ender=[[Grand Mason Marblesten]],ender_loc=[[Gran mampostero Marmolez]],enderType=[[NPC]],enderId=2790,prevId=686,poiX=-5028,poiY=-1020,wowhead=[[https://www.wowhead.com/wotlk/quest=689]],image=[[assets/images/quests/placeholder.png]],desc=[[So our good King would like a memorial built in honor of a soldier named Sully Balloo?  And you say the poor chap died during the Thandol Span tragedy? Bah, will there ever be peace on Azeroth? Nonetheless, any commission from the King is of utmost importance. To build a truly epic and lasting piece I want to work with one of the finest stones available. Travel to Darrow Hill in Hillsbrad and gather for me some Alterac Granite.]],logDesc=[[Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite.]]}
DB[690]={id=690,zoneId=1519,name=[[Malin's Request]],name_loc=[[Una petición de Malin]],level=32,minLevel=30,giver=[[Archmage Malin]],giver_loc=[[Archimago Malin]],giverType=[[NPC]],giverId=2708,ender=[[Skuerto]],enderType=[[NPC]],enderId=2789,poiX=-1262,poiY=-2546,wowhead=[[https://www.wowhead.com/wotlk/quest=690]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, $N. You have the look of an adventurer about you, and I have a task that needs some tending to. Archmage Trelane, my original master, fled Stromgarde in the Arathi Highlands not too long ago, and he's asked me to help him in recovering some of the items he left behind. The city fell under siege, and he attempted to defend the Tower of Arathor, but to no avail. I have agents in the Highlands already, but they've requested I send more aid. Are you interested?]],logDesc=[[Find Skuerto at Refuge Pointe in the Arathi Highlands.]]}
DB[691]={id=691,zoneId=45,name=[[Worth Its Weight in Gold]],name_loc=[[Valer su peso en oro]],level=36,minLevel=30,giver=[[Apprentice Kryten]],giver_loc=[[Aprendiz Kryten]],giverType=[[NPC]],giverId=2788,ender=[[Apprentice Kryten]],ender_loc=[[Aprendiz Kryten]],enderType=[[NPC]],enderId=2788,poiX=-1703,poiY=-3533,wowhead=[[https://www.wowhead.com/wotlk/quest=691]],image=[[assets/images/quests/placeholder.png]],desc=[[Archmage Malin sent Skuerto and I here to collect reagents for him. I was at a loss as to how I was going to collect the items, but now that you're here, I think my problem's solved. I need the following: Witherbark tusks, Witherbark medicine pouches and a shadow hunter knife. Could you find those for me? The Witherbark live to the southeast of Arathi.]],logDesc=[[Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe.]]}
DB[692]={id=692,zoneId=3,name=[[The Lost Fragments]],name_loc=[[Los trozos perdidos]],level=41,minLevel=30,giver=[[Theldurin the Lost]],giver_loc=[[Theldurin el Perdido]],giverType=[[NPC]],giverId=2785,ender=[[Theldurin the Lost]],ender_loc=[[Theldurin el Perdido]],enderType=[[NPC]],enderId=2785,prevId=687,poiX=-7250,poiY=-3483,wowhead=[[https://www.wowhead.com/wotlk/quest=692]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scroll of Myzrael...the Scroll of Myzrael?!  You don't want that!  Its magic can pull Myzrael to the surface world and if you do that, we are in trouble! Or...maybe it's too late.  Maybe she already is free.  Maybe she's just gathering strength before unleashing herself upon us.  If so, then you'll NEED the scroll! ...too bad it's destroyed.  Enraged elementals stole it and tore it up and now fight over the fragments. But if you can gather those fragments, maybe we can fix it...]],logDesc=[[Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost.]]}
DB[693]={id=693,zoneId=45,name=[[Wand over Fist]],name_loc=[[Empuñar la varita]],level=39,minLevel=30,giver=[[Skuerto]],giverType=[[NPC]],giverId=2789,ender=[[Skuerto]],enderType=[[NPC]],enderId=2789,prevId=691,poiX=-2098,poiY=-2838,wowhead=[[https://www.wowhead.com/wotlk/quest=693]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey, $N. Sorry to be so short with ye earlier... and no, that ain't a pun. I figured out where Trelane's first item ended up: Kor'gresh has it in Boulderfist Hall. An' by the way he was throwing down blasts of ice at his kin to keep them in line, he must be close to figurin' out how to use all of its powers. Boulderfist Hall's south of here an' then east of Thandol Span. Find the ogre an' get back that wand. While you're gone, I'll figure out what we're gonna do about Stromgarde.]],logDesc=[[Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe.]]}
DB[694]={id=694,zoneId=45,name=[[Trelane's Defenses]],name_loc=[[Las defensas de Trelane]],level=39,minLevel=30,giver=[[Skuerto]],giverType=[[NPC]],giverId=2789,ender=[[Apprentice Kryten]],ender_loc=[[Aprendiz Kryten]],enderType=[[NPC]],enderId=2788,prevId=693,rewardNextId=695,poiX=-1741,poiY=-1644,wowhead=[[https://www.wowhead.com/wotlk/quest=694]],image=[[assets/images/quests/placeholder.png]],desc=[[All rested? Here's our next step: there're ogres all around the Tower of Arathor in Stromgarde. We're gonna need to activate the tower's defenses if you're gonna stand a chance against 'em an' still make it to the items alive. To do that, we're gonna need some gems the Boulderfist shaman have taken a liking to. They took 'em from the tower, but they're not gonna stay in their possession for long. Get one of them gems an' bring 'em to Kryten--he knows the spell to enchant 'em so they'll work as a key.]],logDesc=[[Find an Azure Agate and bring it to Apprentice Kryten at Refuge Pointe.]]}
DB[695]={id=695,zoneId=45,name=[[An Apprentice's Enchantment]],name_loc=[[Un encantamiento de aprendiz]],level=39,minLevel=30,giver=[[Apprentice Kryten]],giver_loc=[[Aprendiz Kryten]],giverType=[[NPC]],giverId=2788,ender=[[Skuerto]],enderType=[[NPC]],enderId=2789,prevId=694,rewardNextId=696,poiX=-1262,poiY=-2546,wowhead=[[https://www.wowhead.com/wotlk/quest=695]],image=[[assets/images/quests/placeholder.png]],desc=[[Here you are, $N. The gem only needs to be pressed against one of the pedestals near the base of the tower to activate its defenses. Use it when you're ready to enter the tower and find Trelane's remaining items.  Good luck to you. I'll be awaiting your return here at the camp. Oh, and speak to Skuerto before you leave. He'll give you the rest of the details you'll need.]],logDesc=[[Speak to Skuerto at Refuge Pointe in Arathi Highlands.]]}
DB[696]={id=696,zoneId=45,name=[[Attack on the Tower]],name_loc=[[Ataque a la torre]],level=39,minLevel=30,giver=[[Skuerto]],giverType=[[NPC]],giverId=2789,ender=[[Skuerto]],enderType=[[NPC]],enderId=2789,prevId=695,rewardNextId=697,poiX=-1769,poiY=-1521,wowhead=[[https://www.wowhead.com/wotlk/quest=696]],image=[[assets/images/quests/placeholder.png]],desc=[[Here's what your lookin' for: Trelane's phylactery, Trelane's orb, an' Trelane's ember agate. All three should be in chests within the tower an' you shouldn't have a problem opening the chests on your own; you just have to be careful of the ogres. The tower's defenses won't take care of 'em on their own; you'll need to have your weapons at the ready. Those ogres find out you're there and stealing from 'em, an' they'll be sure to put the hurt on you. Be careful, an' good luck.]],logDesc=[[Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.]]}
DB[697]={id=697,zoneId=45,name=[[Malin's Request]],name_loc=[[Una petición de Malin]],level=39,minLevel=30,giver=[[Skuerto]],giverType=[[NPC]],giverId=2789,ender=[[Archmage Malin]],ender_loc=[[Archimago Malin]],enderType=[[NPC]],enderId=2708,prevId=696,poiX=-9009,poiY=845,wowhead=[[https://www.wowhead.com/wotlk/quest=697]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, $N, of that I've no doubt. Travel safely.]],logDesc=[[Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind.]],choiceRewards={{id=4975,qty=1},{id=15104,qty=1}}}
DB[698]={id=698,zoneId=8,name=[[Lack of Surplus]],name_loc=[[Falta de suministros]],level=40,minLevel=35,giver=[[Dar]],giverType=[[NPC]],giverId=5591,ender=[[Tok'Kar]],enderType=[[NPC]],enderId=5592,rewardNextId=699,poiX=-10548,poiY=-4216,wowhead=[[https://www.wowhead.com/wotlk/quest=698]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm working on getting some supplies together for our outpost near the beach to the east--Tok'kar does what he can, but between shifts of guard duty and cooking for his soldiers there's not much time left in the day. They do enjoy cooking up some sawtooth meat when they can, but I haven't had time to get them another shipment. Would you mind helping them out? The young sawtooths aren't as tasty as the older ones, so stay clear of those; give them a year or two to get to full size.]],logDesc=[[Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows.]]}
DB[699]={id=699,zoneId=8,name=[[Lack of Surplus]],name_loc=[[Falta de suministros]],level=42,minLevel=35,giver=[[Tok'Kar]],giverType=[[NPC]],giverId=5592,ender=[[Tok'Kar]],enderType=[[NPC]],enderId=5592,prevId=698,rewardNextId=1422,poiX=-10548,poiY=-4216,wowhead=[[https://www.wowhead.com/wotlk/quest=699]],image=[[assets/images/quests/placeholder.png]],desc=[[With the threat of murlocs along the coast, we're stationed out here to protect--or warn if the force is too large--of any coming threats to Stonard. It doesn't give us much time for relaxation, and we could use some more help if you're able. The sawtooth snappers' claws make for fine weapons when properly prepared. Bring me some of their claws and I'll see you're rewarded with one of our weapons in thanks for the fresh meat and the good company.]],logDesc=[[Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows.]]}
DB[700]={id=700,zoneId=1537,name=[[A King's Tribute]],name_loc=[[Un homenaje real]],level=31,minLevel=25,giver=[[Grand Mason Marblesten]],giver_loc=[[Gran mampostero Marmolez]],giverType=[[NPC]],giverId=2790,ender=[[King Magni Bronzebeard]],ender_loc=[[Rey Magni Barbabronce]],enderType=[[NPC]],enderId=2784,prevId=689,poiX=-4866,poiY=-1023,wowhead=[[https://www.wowhead.com/wotlk/quest=700]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, such fine stone comes from Lordaeron.  Such a shame the land is in such shambles. But the Memorial came out quite well! I should think the King will be most pleased with it. Now if you will, please send word to His Majesty that the Memorial is complete as requested.]],logDesc=[[Report to King Magni Bronzebeard.]],rewards={{id=4535,qty=1}}}
DB[701]={id=701,zoneId=45,name=[[Guile of the Raptor]],name_loc=[[La astucia del raptor]],level=37,minLevel=29,giver=[[Tor'gan]],giverType=[[NPC]],giverId=2706,ender=[[Tor'gan]],enderType=[[NPC]],enderId=2706,prevId=675,rewardNextId=702,poiX=-1716,poiY=-2846,wowhead=[[https://www.wowhead.com/wotlk/quest=701]],image=[[assets/images/quests/placeholder.png]],desc=[[With some additional objects, I will be able to create an item that will imbue Gor'mul with the guile of the raptor! With the power of the raptor flowing through him, Gor'mul will know our new power and rediscover the warrior that lies dormant! I will require raptor hearts to fashion the item and spell.]],logDesc=[[Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan.]]}
DB[702]={id=702,zoneId=45,name=[[Guile of the Raptor]],name_loc=[[La astucia del raptor]],level=37,minLevel=29,giver=[[Tor'gan]],giverType=[[NPC]],giverId=2706,ender=[[Gor'mul]],enderType=[[NPC]],enderId=2792,prevId=701,poiX=-948,poiY=-3482,wowhead=[[https://www.wowhead.com/wotlk/quest=702]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this orb and use its energy to give Gor'mul the essence of the raptor. Surely this will invigorate his spirit and give him new purpose in life. With him returned to normal, we can explain to him the current state of the Horde, and we will have a great warrior's assistance in our unceasing battles.]],logDesc=[[Give Tor'gan's Orb to Gor'mul at Hammerfall in Arathi Highlands.]]}
DB[703]={id=703,zoneId=3,name=[[Barbecued Buzzard Wings]],name_loc=[[Alas de águila ratonera a la parrilla]],level=40,minLevel=33,giver=[[Rigglefuzz]],giver_loc=[[Aparejez]],giverType=[[NPC]],giverId=2817,ender=[[Rigglefuzz]],ender_loc=[[Aparejez]],enderType=[[NPC]],enderId=2817,poiX=-6859,poiY=-2508,wowhead=[[https://www.wowhead.com/wotlk/quest=703]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh yes, my barbecued buzzard wings are a favorite!  The sauce is rich and the meat is tangy.  And the smell will bring the hungry running from miles away! I have everything I need to cook up a batch.  Everything...except the buzzard wings! If you want some then get me the buzzard wings.  Bring me enough, and I might even share the recipe with you!]],logDesc=[[Bring 4 Buzzard Wings to Rigglefuzz.]],rewards={{id=4457,qty=2},{id=4609,qty=1}}}
DB[704]={id=704,zoneId=1517,name=[[Agmond's Fate]],name_loc=[[El sino de Agmond]],level=38,minLevel=30,giver=[[Prospector Ironband]],giver_loc=[[Prospector Vetaferro]],giverType=[[NPC]],giverId=1344,ender=[[Prospector Ironband]],ender_loc=[[Prospector Vetaferro]],enderType=[[NPC]],enderId=1344,prevId=739,poiX=-6183,poiY=-2940,wowhead=[[https://www.wowhead.com/wotlk/quest=704]],image=[[assets/images/quests/placeholder.png]],desc=[[The last report I received from Agmond is troubling, more so now that he's dead!  He mentioned that his diggers uncovered "ancient urns" at the dig site outside Uldaman.  I fear that the urns he found at that site incited the troggs, just as did the idols I found here. I need you to get those urns for our studies.  Go to the Uldaman site, gather the urns, then return to me.]],logDesc=[[Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan.]],rewards={{id=4980,qty=1}}}
DB[705]={id=705,zoneId=3,name=[[Pearl Diving]],name_loc=[[La pesca de perlas]],level=37,minLevel=30,giver=[[Rigglefuzz]],giver_loc=[[Aparejez]],giverType=[[NPC]],giverId=2817,ender=[[Rigglefuzz]],ender_loc=[[Aparejez]],enderType=[[NPC]],enderId=2817,poiX=-6767,poiY=-3134,wowhead=[[https://www.wowhead.com/wotlk/quest=705]],image=[[assets/images/quests/placeholder.png]],desc=[[The Badlands is a harsh place, filled with vicious predators and bold scavengers.  Scary, especially for a short little goblin.  To survive, I have to be tricky! I know the recipe for flash bombs.  I use those to scare away wildlife.  But I'm running low on one of the ingredients: crushed blue pearl powder.  Get me some and I'll make it worth your efforts. Heh, and I hope you have good boots on.  The Blue Pearls I need are found from clams at the Vile Reef. Yep, the Vile Reef in Stranglethorn!]],logDesc=[[Bring 9 Blue Pearls to Rigglefuzz in the Badlands.]],rewards={{id=4852,qty=1}},choiceRewards={{id=4086,qty=1},{id=5248,qty=1}}}
DB[706]={id=706,zoneId=3,name=[[Fiery Blaze Enchantments]],name_loc=[[Encantamientos Llamarada ígnea]],level=45,minLevel=40,giver=[[Sigrun Ironhew]],giver_loc=[[Sigrun Extracero]],giverType=[[NPC]],giverId=2860,ender=[[Sigrun Ironhew]],ender_loc=[[Sigrun Extracero]],enderType=[[NPC]],enderId=2860,poiX=-6365,poiY=-4214,wowhead=[[https://www.wowhead.com/wotlk/quest=706]],image=[[assets/images/quests/placeholder.png]],desc=[[As an apprentice to Feranor Steeltoe, I learned his special technique for imbuing weapons with fiery enchantments. Last I heard of him, he was working at a smithy with a hunting party up in Lordaeron. I can't tell you too many of the details about the process, but I can tell you it requires blood from a rare, still-beating black drake whelp's heart. I don't have much to do waiting for word from Ironforge. If you bring me a heart from the whelps in Lethlor Ravine, I'll show you my skill!]],logDesc=[[Acquire a Black Drake's Heart for Sigrun Ironhew.]],rewards={{id=5421,qty=1}}}
DB[707]={id=707,zoneId=1537,name=[[Ironband Wants You!]],name_loc=[[¡Vetaferro te necesita!]],level=37,minLevel=30,giver=[[Prospector Stormpike]],giver_loc=[[Prospector Pico Tormenta]],giverType=[[NPC]],giverId=1356,ender=[[Prospector Ironband]],ender_loc=[[Prospector Vetaferro]],enderType=[[NPC]],enderId=1344,rewardNextId=738,poiX=-5695,poiY=-3812,wowhead=[[https://www.wowhead.com/wotlk/quest=707]],image=[[assets/images/quests/placeholder.png]],desc=[[$N.  I received reports from Prospector Ironband at his excavation site in Loch Modan--he needs some legwork done concerning another of our excavations. I don't have more details than that, but if you want to stretch your legs then go speak with Ironband.]],logDesc=[[Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan.]]}
DB[708]={id=708,zoneId=3,name=[[The Black Box]],name_loc=[[La caja negra]],level=40,minLevel=30,giverType=[[NPC]],ender=[[Pilot Longbeard]],ender_loc=[[Piloto Barbalarga]],enderType=[[NPC]],enderId=2092,poiX=-5065,poiY=-1289,wowhead=[[https://www.wowhead.com/wotlk/quest=708]],image=[[assets/images/quests/placeholder.png]],desc=[[The surface of this metallic black box is heavily pitted, as if it had been immersed in acid - it must have been sitting in the giant condor's stomach for a long time. Turning the box over, a symbol is found stamped on its bottom.  Below the symbol are the words: "Engine #19 - Ironforge Siege Brigade"]],logDesc=[[Take the Corroded Black Box to the Hall of Arms in Ironforge.]]}
DB[709]={id=709,zoneId=1517,name=[[Solution to Doom]],name_loc=[[La solución a la maldición]],level=40,minLevel=30,giver=[[Theldurin the Lost]],giver_loc=[[Theldurin el Perdido]],giverType=[[NPC]],giverId=2785,ender=[[Theldurin the Lost]],ender_loc=[[Theldurin el Perdido]],enderType=[[NPC]],enderId=2785,poiX=-7164,poiY=-3357,wowhead=[[https://www.wowhead.com/wotlk/quest=709]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh my!  Oh my!  There is a doom approaching.  Mark me!  A doom! No, I cannot speak of it...cannot utter their names or they may hear me!  But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them! Maybe. Go into Uldaman.  No!  I said it!  You must find...find the tablet of...Ryun'eh.  Yes, find it!  And don't make me speak that name again! It is deep in that place, in an ancient chest.  That's where it hides...in a chest crafted before the works of any dwarf.]],logDesc=[[Bring the Tablet of Ryun'eh to Theldurin the Lost.]],rewards={{id=4746,qty=1}}}
DB[710]={id=710,zoneId=3,name=[[Study of the Elements: Rock]],name_loc=[[Estudio de los elementos: roca]],level=37,minLevel=35,giver=[[Lotwil Veriatus]],giverType=[[NPC]],giverId=2921,ender=[[Lotwil Veriatus]],enderType=[[NPC]],enderId=2921,rewardNextId=711,poiX=-6522,poiY=-2490,wowhead=[[https://www.wowhead.com/wotlk/quest=710]],image=[[assets/images/quests/placeholder.png]],desc=[[Here in the Badlands I've stopped to work on my latest project: my shackles of elemental binding. When complete, they will allow mages to summon even more powerful elementals for use in even greater capacities. To start things off, I need small stone shards to test some of my newest offensive spells along with a few gizmos I've pieced together. The shards are easily collected from the lesser rock elementals to the west of here. Could you bring me some?]],logDesc=[[Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands.]]}
DB[711]={id=711,zoneId=3,name=[[Study of the Elements: Rock]],name_loc=[[Estudio de los elementos: roca]],level=39,minLevel=35,giver=[[Lotwil Veriatus]],giverType=[[NPC]],giverId=2921,ender=[[Lotwil Veriatus]],enderType=[[NPC]],enderId=2921,prevId=710,rewardNextId=712,poiX=-6485,poiY=-2484,wowhead=[[https://www.wowhead.com/wotlk/quest=711]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you've already proven more able than all my apprentices combined. The next parts I need require a little more strength. Large stone slabs can be found on rock elementals if you're careful enough. Their bodies are stronger and larger, and therefore more prone to having pieces large enough for my tests. You can find them further west of here or southeast along the mountains' edges. Take your time; I'll need a while to test these smaller pieces you brought me.]],logDesc=[[Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands.]]}
DB[712]={id=712,zoneId=3,name=[[Study of the Elements: Rock]],name_loc=[[Estudio de los elementos: roca]],level=42,minLevel=35,giver=[[Lotwil Veriatus]],giverType=[[NPC]],giverId=2921,ender=[[Lotwil Veriatus]],enderType=[[NPC]],enderId=2921,prevId=711,nextId=734,exGroup=-734,poiX=-7286,poiY=-2504,wowhead=[[https://www.wowhead.com/wotlk/quest=712]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, there's one more part I need from the elementals here in the Badlands: the bracers of rock binding from the greater rock elementals. By my calculations, those bracers should be enough to gauge the strength of my own shackles. My attempts at scrying the greater rock elementals showed a group of them southwest of here, near some ogres if I recall. Bring me 5 of their bracers just so I have extras. Servo's notorious for misplacing my reagents and research.]],logDesc=[[Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.]]}
DB[713]={id=713,zoneId=3,name=[[Coolant Heads Prevail]],name_loc=[[Mantener la cabeza fría]],level=37,minLevel=35,giver=[[Lotwil Veriatus]],giverType=[[NPC]],giverId=2921,ender=[[Lotwil Veriatus]],enderType=[[NPC]],enderId=2921,rewardNextId=714,poiX=-6634,poiY=-2725,wowhead=[[https://www.wowhead.com/wotlk/quest=713]],image=[[assets/images/quests/placeholder.png]],desc=[[Let me tell you something about Frost Oil: nothing can keep an engine or gears from overheating quite like it. Its cooling properties are extraordinary, and its longevity as a lubricant without equal. That's not all: it also aids in retaining enchantments on magical items. I need a vial of it to increase the magical capacity of my shackles and make them powerful enough to stop our summoned friend from killing us all. Bro'kin, a goblin friend of mine, can teach you to make it. He's in Alterac.]],logDesc=[[Find Frost Oil and bring it to Lotwil Veriatus in Badlands.]]}
DB[714]={id=714,zoneId=3,name=[[Gyro... What?]],name_loc=[[Un giro... ¿Qué?]],level=37,minLevel=35,giver=[[Lotwil Veriatus]],giverType=[[NPC]],giverId=2921,ender=[[Lotwil Veriatus]],enderType=[[NPC]],enderId=2921,prevId=713,nextId=734,exGroup=-734,poiX=-6634,poiY=-2725,wowhead=[[https://www.wowhead.com/wotlk/quest=714]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you've done your job well beyond all standards. <Lotwil's obviously distracted by his work.> If we ever meet in Kharanos, feel free to come apply for work. Whoops! Quick, grab the... yes, that. Thanks. Now I just need one more thing. It's a small part, but rather crucial, I'm afraid: a gyrochronatom. If you could just go grab one and bring it to me, I should be ready to complete this.]],logDesc=[[Bring a Gyrochronatom to Lotwil Veriatus in the Badlands.]]}
DB[715]={id=715,zoneId=3,name=[[Liquid Stone]],name_loc=[[Piedra líquida]],level=37,minLevel=35,giver=[[Lucien Tosselwrench]],giver_loc=[[Lucien Borlallave]],giverType=[[NPC]],giverId=2920,ender=[[Lucien Tosselwrench]],ender_loc=[[Lucien Borlallave]],enderType=[[NPC]],enderId=2920,prevId=714,poiX=-6624,poiY=-2721,wowhead=[[https://www.wowhead.com/wotlk/quest=715]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm thinking those items you acquired for Lotwil are going to be the least of our worries, $N. On the other hand, you've proven more than adept at the sciences Lotwil holds sacred, so how about helping me out? I need an invisibility potion and a healing potion; both might come in handy real soon if he pulls this off. In return, I'll give you this recipe for a potion I've been developing while learning from Lotwil. It's based on some of the research he's been doing here in the Badlands.]],logDesc=[[Bring a Healing Potion and a Lesser Invisibility Potion to Lucien Tosselwrench in the Badlands.]],rewards={{id=4624,qty=1},{id=4623,qty=2}}}
DB[716]={id=716,zoneId=3,name=[[Stone Is Better than Cloth]],name_loc=[[Es mejor la piedra que la tela]],level=42,minLevel=35,giver=[[Lucien Tosselwrench]],giver_loc=[[Lucien Borlallave]],giverType=[[NPC]],giverId=2920,ender=[[Lucien Tosselwrench]],ender_loc=[[Lucien Borlallave]],enderType=[[NPC]],enderId=2920,prevId=712,poiX=-6624,poiY=-2721,wowhead=[[https://www.wowhead.com/wotlk/quest=716]],image=[[assets/images/quests/placeholder.png]],desc=[[I know how cheap Lotwil can be, $N, so let me make you something for all your troubles. Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention. I've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use. They're enchanted, of course. I'll just need patterned bronze bracers crafted by a blacksmith so I can complete the bracers I'm making for you.]],logDesc=[[Bring some Patterned Bronze Bracers to Lucien Tosselwrench in the Badlands.]],rewards={{id=4979,qty=1}}}
DB[717]={id=717,zoneId=3,name=[[Tremors of the Earth]],name_loc=[[Terremotos]],level=50,minLevel=40,giver=[[Garek]],giverType=[[NPC]],giverId=2888,ender=[[Garek]],enderType=[[NPC]],enderId=2888,prevId=732,poiX=-6715,poiY=-4104,wowhead=[[https://www.wowhead.com/wotlk/quest=717]],image=[[assets/images/quests/placeholder.png]],desc=[[It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor. That black dragons have taken up residence there, and that the ogres managed to steal the Sign indicates that more drastic measures will have to be taken. The drakes' prison is maintained by three runestones that may only be retrieved using the Sign of the Earth. Those runestones can then be used to break the seal which imprisons them. $n... assure that their dreams are eternal.]],logDesc=[[Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones. Place the runestones in the Seal of the Earth to free Blacklash and Hematus. Slay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek.]],choiceRewards={{id=11193,qty=1},{id=11194,qty=1},{id=11195,qty=1},{id=11196,qty=1}}}
DB[718]={id=718,zoneId=3,name=[[Mirages]],name_loc=[[Espejismos]],level=38,minLevel=35,giver=[[Sigrun Ironhew]],giver_loc=[[Sigrun Extracero]],giverType=[[NPC]],giverId=2860,ender=[[Sigrun Ironhew]],ender_loc=[[Sigrun Extracero]],enderType=[[NPC]],enderId=2860,rewardNextId=733,poiX=-6255,poiY=-3736,wowhead=[[https://www.wowhead.com/wotlk/quest=718]],image=[[assets/images/quests/placeholder.png]],desc=[[In our hurry to leave the Uldaman excavation site, we were forced to abandon many wagons and crates of supplies along the way. The local ogres from Camp Kosh have been on our abandoned equipment like vultures on a rotting corpse. Don't smell much better, either. Than the corpses, I mean. Anyways, they took the cart that was carrying all our weapons and such... so--well, this is a bit embarrassing--we haven't been able to get any food. We're in a bit of a pickle here, suppose you could help us out?]],logDesc=[[Retrieve the Supply Crate for Sigrun Ironhew.]]}
DB[719]={id=719,zoneId=3,name=[[A Dwarf and His Tools]],name_loc=[[Un enano y sus herramientas]],level=35,minLevel=35,giver=[[Prospector Ryedol]],giver_loc=[[Prospector Ryedol]],giverType=[[NPC]],giverId=2910,ender=[[Prospector Ryedol]],ender_loc=[[Prospector Ryedol]],enderType=[[NPC]],enderId=2910,poiX=-6452,poiY=-3435,wowhead=[[https://www.wowhead.com/wotlk/quest=719]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey, $N. Be careful 'round here. There be Dark Iron dwarves all around--looked like the Shadowforge clan. They just attacked the excavation site I was workin' at--killed nearly everyone there, including my boss Hammertoe. I barely escaped with me life. The site's just to the north of here, and I'm tryin' to plan a way to get some of our supplies back, especially me lucky pick. Think you'd be up to helpin' me out some? One of those damned Dark Iron must have my pick! Could be anyone of them.]],logDesc=[[Find Ryedol's Lucky Pick and return it to Prospector Ryedol south of Hammertoe's Dig Site.]],rewards={{id=4978,qty=1}}}
DB[720]={id=720,zoneId=3,name=[[A Sign of Hope]],name_loc=[[Un signo de esperanza]],level=35,minLevel=35,giver=[[Crumpled Map]],giver_loc=[[Mapa arrugado]],giverType=[[GO]],giverId=2868,ender=[[Prospector Ryedol]],ender_loc=[[Prospector Ryedol]],enderType=[[NPC]],enderId=2910,rewardNextId=721,poiX=-6609,poiY=-3408,wowhead=[[https://www.wowhead.com/wotlk/quest=720]],image=[[assets/images/quests/placeholder.png]],desc=[[<There is text roughly scribbled in chalk on the map.> "Ryedol,  They're taking me to Uldaman. Send help. -Hammertoe"]],logDesc=[[Find Prospector Ryedol and let him know Hammertoe Grez is alive.]]}
DB[721]={id=721,zoneId=1517,name=[[A Sign of Hope]],name_loc=[[Un signo de esperanza]],level=35,minLevel=35,giver=[[Prospector Ryedol]],giver_loc=[[Prospector Ryedol]],giverType=[[NPC]],giverId=2910,ender=[[Hammertoe Grez]],ender_loc=[[Grez Piemartillo]],enderType=[[NPC]],enderId=2909,prevId=720,rewardNextId=722,poiX=-6065,poiY=-3022,wowhead=[[https://www.wowhead.com/wotlk/quest=721]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, can ye find him? Can you find Hammertoe in Uldaman? If those dirty Shadowforge are holdin' him hostage to figure out what he knows about the titan excavations, then all of Ironforge could be in huge trouble. For a long time now those Dark Irons have been lookin' for magics to make more powerful golems. Hammertoe was doin' the same, of course, but only to stop them. They're probably keepin' him alive until they learn what he knows.Ye've got to hurry if you're gonna save him!]],logDesc=[[Find Hammertoe Grez in Uldaman.]]}
DB[722]={id=722,zoneId=1517,name=[[Amulet of Secrets]],name_loc=[[El amuleto de los secretos]],level=40,minLevel=35,giver=[[Hammertoe Grez]],giver_loc=[[Grez Piemartillo]],giverType=[[NPC]],giverId=2909,ender=[[Hammertoe Grez]],ender_loc=[[Grez Piemartillo]],enderType=[[NPC]],enderId=2909,prevId=721,rewardNextId=723,poiX=-6216,poiY=-3052,wowhead=[[https://www.wowhead.com/wotlk/quest=722]],image=[[assets/images/quests/placeholder.png]],desc=[[Ye're brave... <cough>... to come into Uldaman fer me, $c. If ye're really here to help... ol' Hammertoe, then... <cough>... you'll need to find... me amulet. Deepshadow's got it... Magregan Deepshadow. He's 'round here... in the ruins fer sure. That amulet'll lead 'em... <cough>...  right to the scrolls if he ain't stopped. It's up to you, $N. Please... get that amulet. The scrolls will surely help the Dark Irons create even more powerful golems. I just know it. I can feel it in me bones.]],logDesc=[[Find Hammertoe's Amulet and return it to him in Uldaman.]]}
DB[723]={id=723,zoneId=3,name=[[Prospect of Faith]],name_loc=[[Tener fe en el porvenir]],level=40,minLevel=35,giver=[[Hammertoe Grez]],giver_loc=[[Grez Piemartillo]],giverType=[[NPC]],giverId=2909,ender=[[Prospector Ryedol]],ender_loc=[[Prospector Ryedol]],enderType=[[NPC]],enderId=2910,prevId=722,rewardNextId=724,poiX=-6216,poiY=-3052,wowhead=[[https://www.wowhead.com/wotlk/quest=723]],image=[[assets/images/quests/placeholder.png]],desc=[[<Hammertoe holds his wounds and takes a moment to regain his composure before speaking again.> Find Ryedol, $N. Bring 'im me amulet. <cough cough> He'll... <cough> figure out what to do. He knows I was seeking the origins of our people, and he... <cough>... knows it was also my mission to stop the Shadowforge clan. They must not be allowed to find the scrolls... <cough>]],logDesc=[[Take Hammertoe's Amulet to Prospector Ryedol in the Badlands.]]}
DB[724]={id=724,zoneId=3,name=[[Prospect of Faith]],name_loc=[[Tener fe en el porvenir]],level=40,minLevel=35,giver=[[Prospector Ryedol]],giver_loc=[[Prospector Ryedol]],giverType=[[NPC]],giverId=2910,ender=[[Historian Karnik]],ender_loc=[[Karnik el Historiador]],enderType=[[NPC]],enderId=2916,prevId=723,poiX=-4632,poiY=-1327,wowhead=[[https://www.wowhead.com/wotlk/quest=724]],image=[[assets/images/quests/placeholder.png]],desc=[[Okay, okay... who would know what to do? Historian Karnik! That's it! He's in Ironforge. He'll be able to help. He and Hammertoe were workin' together to find the lost artifacts in Uldaman. Guess the Shadowforge found out the two of them knew more than they were lettin' on. Tell Karnik what's happened to Hammertoe and give him the amulet--he'll tell you what needs to be done next.]],logDesc=[[Take Hammertoe's Amulet to Historian Karnik in Ironforge.]]}
DB[725]={id=725,zoneId=3,name=[[Passing Word of a Threat]],name_loc=[[Advertir de la amenaza]],level=40,minLevel=35,giver=[[Historian Karnik]],giver_loc=[[Karnik el Historiador]],giverType=[[NPC]],giverId=2916,ender=[[Advisor Belgrum]],ender_loc=[[Consejero Belgrum]],enderType=[[NPC]],enderId=2918,prevId=724,rewardNextId=726,poiX=-4620,poiY=-1325,wowhead=[[https://www.wowhead.com/wotlk/quest=725]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, run and find Advisor Belgrum as quickly as you can. Tell him what you've witnessed and ask him how he wants us to proceed. This note will explain more to him. In the meantime, I will take the time to speak to Hammertoe's spirit. Maybe he knows something that will help us put a stop to those Shadowforge cretins' activities in the Badlands. We can only pray.]],logDesc=[[Find Advisor Belgrum and give him his note.]]}
DB[726]={id=726,zoneId=3,name=[[Passing Word of a Threat]],name_loc=[[Advertir de la amenaza]],level=40,minLevel=35,giver=[[Advisor Belgrum]],giver_loc=[[Consejero Belgrum]],giverType=[[NPC]],giverId=2918,ender=[[Historian Karnik]],ender_loc=[[Karnik el Historiador]],enderType=[[NPC]],enderId=2916,prevId=725,rewardNextId=762,poiX=-4632,poiY=-1327,wowhead=[[https://www.wowhead.com/wotlk/quest=726]],image=[[assets/images/quests/placeholder.png]],desc=[[<Advisor Belgrum reaches the end of the note, and his eyes widen for a moment.> Och, these are evil tidings. $N, please return to Historian Karnik and tell him on the king's authority to act on this information swiftly and decisively. He must halt the Shadowforge's activities in the Badlands.]],logDesc=[[Speak to Historian Karnik.]]}
DB[727]={id=727,zoneId=3,name=[[To Ironforge for Yagyin's Digest]],name_loc=[[Ir a Forjaz a buscar el "Compendio" de Yagyin]],level=40,minLevel=30,giver=[[Theldurin the Lost]],giver_loc=[[Theldurin el Perdido]],giverType=[[NPC]],giverId=2785,ender=[[Gerrig Bonegrip]],ender_loc=[[Gerrig Agarrahueso]],enderType=[[NPC]],enderId=2786,prevId=709,rewardNextId=735,poiX=-4599,poiY=-1115,wowhead=[[https://www.wowhead.com/wotlk/quest=727]],image=[[assets/images/quests/placeholder.png]],desc=[[The Tablet tells much.  But not enough!  Not nearly enough! There is a book, a digest that Yagyin wrote in ages past.  The ... people I fled ... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us! Go to Gerrig Bonegrip.  He is in a shop in Ironforge, in the Forlorn Cavern.  Show him this sigil and he'll think you one of them.  Ask him for Yagyin's Digest ... and bring it to me!]],logDesc=[[Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge.]]}
DB[728]={id=728,zoneId=3,name=[[To the Undercity for Yagyin's Digest]],name_loc=[[Ir a Entrañas a buscar el "Compendio" de Yagyin]],level=40,minLevel=30,giver=[[Theldurin the Lost]],giver_loc=[[Theldurin el Perdido]],giverType=[[NPC]],giverId=2785,ender=[[Keeper Bel'dugur]],ender_loc=[[Vigilante Bel'dugur]],enderType=[[NPC]],enderId=2934,prevId=709,rewardNextId=736,poiX=1529,poiY=358,wowhead=[[https://www.wowhead.com/wotlk/quest=728]],image=[[assets/images/quests/placeholder.png]],desc=[[The tablet tells much.  But not enough!  Not nearly enough! There is a book, a digest that Yagyin wrote in ages past.  The... people I fled from... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us! Go to Keeper Bel'dugur in the Undercity of Lordaeron.  Show him this sigil and he'll think you one of them.  Ask him for Yagin's Digest...and bring it to me!]],logDesc=[[Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity.]]}
DB[729]={id=729,zoneId=148,name=[[The Absent Minded Prospector]],name_loc=[[El prospector despistado]],level=20,minLevel=15,giver=[[Archaeologist Hollee]],giver_loc=[[Arqueóloga Hollee]],giverType=[[NPC]],giverId=2913,ender=[[Prospector Remtravel]],ender_loc=[[Prospector Tripirrem]],enderType=[[NPC]],enderId=2917,poiX=4679,poiY=602,wowhead=[[https://www.wowhead.com/wotlk/quest=729]],image=[[assets/images/quests/placeholder.png]],desc=[[What an honor it was when Master Greywhisker assigned me to work under the guidance of the great Prospector Remtravel. At the academy in Ironforge everyone knew of Remtravel's great discoveries. But the prospector is rather... um... oblivious ...to his surroundings. We had uncovered evidence of a great society. Horrible golems sprang forth from the ground and overran the site. Remtravel never seemed to notice. I ran back to Auberdine for help. Please travel south and see if the prospector is okay!]],logDesc=[[Travel south and check on Prospector Remtravel.]]}
DB[730]={id=730,zoneId=1657,name=[[Trouble In Darkshore?]],name_loc=[[¿Problemas en Costa Oscura?]],level=14,minLevel=14,giver=[[Chief Archaeologist Greywhisker]],giver_loc=[[Arqueólogo Jefe Mostachogris]],giverType=[[NPC]],giverId=2912,ender=[[Archaeologist Hollee]],ender_loc=[[Arqueóloga Hollee]],enderType=[[NPC]],enderId=2913,rewardNextId=729,poiX=6506,poiY=489,wowhead=[[https://www.wowhead.com/wotlk/quest=730]],image=[[assets/images/quests/placeholder.png]],desc=[[How nice it is to see a $c interested in the great archeological wonders of our world. Oftentimes our work is dismissed as mere hobby by our friends in the Alliance. But what many fail to realize is that recent discoveries in Khaz Modan have proven that a great and powerful force threatens all of Azeroth, from Lordaeron to Kalimdor. I am most worried about my crew that I sent to Darkshore. They haven't sent word in weeks. Travel to Auberdine and look for a clue as to their whereabouts.]],logDesc=[[Travel to Auberdine and look for signs of the dwarven excavation team.]]}
DB[731]={id=731,zoneId=148,name=[[The Absent Minded Prospector]],name_loc=[[El prospector despistado]],level=20,minLevel=15,giver=[[Prospector Remtravel]],giver_loc=[[Prospector Tripirrem]],giverType=[[NPC]],giverId=2917,ender=[[Archaeologist Hollee]],ender_loc=[[Arqueóloga Hollee]],enderType=[[NPC]],enderId=2913,prevId=729,rewardNextId=741,poiX=6506,poiY=489,wowhead=[[https://www.wowhead.com/wotlk/quest=731]],image=[[assets/images/quests/placeholder.png]],desc=[[So then, Hollee... oh that's right, you are not Hollee. Where's Hollee? Bah, that's beside the point. We must find that stone brush... I mean the mysterious fossil! We must find that fossil. The Explorers' League in Darnassus will want some indication as to what I've been doing. Let me know when you are ready and we will hunt down that brush.... I mean fossil! We shall find something in writing to satisfy the League. So are you ready yet?]],logDesc=[[Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine.]]}
DB[732]={id=732,zoneId=3,name=[[Tremors of the Earth]],name_loc=[[Terremotos]],level=43,minLevel=40,giver=[[Garek]],giverType=[[NPC]],giverId=2888,ender=[[Garek]],enderType=[[NPC]],enderId=2888,prevId=718,rewardNextId=717,poiX=-7015,poiY=-3611,wowhead=[[https://www.wowhead.com/wotlk/quest=732]],image=[[assets/images/quests/placeholder.png]],desc=[[I heard from Sigrun that you have been a great help to him. Perhaps I might enlist your help. I was sent here by my master, Krasus of the Kirin Tor, to put an end to the trouble brewing in Lethlor Ravine. I cannot divulge the exact nature of my assignment here or the tasks that I must undertake, but be assured it is of vital importance. A band of wandering ogres, sometimes seen near Camp Boff, stole an object called the Sign of the Earth; I must have it. Bring it to me, and I will tell you more.]],logDesc=[[Retrieve the Sign of the Earth for Garek.]]}
DB[733]={id=733,zoneId=3,name=[[Scrounging]],name_loc=[[¡A gorronear!]],level=40,minLevel=35,giver=[[Sigrun Ironhew]],giver_loc=[[Sigrun Extracero]],giverType=[[NPC]],giverId=2860,ender=[[Sigrun Ironhew]],ender_loc=[[Sigrun Extracero]],enderType=[[NPC]],enderId=2860,prevId=718,poiX=-6299,poiY=-3767,wowhead=[[https://www.wowhead.com/wotlk/quest=733]],image=[[assets/images/quests/placeholder.png]],desc=[[It's going to be tough going here if I can't manage to scrounge up some materials to construct some defenses and other necessities. I've noticed that the ogres in the area seem to be well equipped with scrap metal. Maybe the stories of siege engines in the Badlands weren't so far off after all... Anyways, the Prospector's been getting worried about the state of our little camp, so I'd like to get working soon if I can. The main ogre camp is at Dustbelch Grotto, a good trek to the west of here.]],logDesc=[[Get 7 pieces of Scrap Metal for Sigrun.]],choiceRewards={{id=4652,qty=1},{id=4653,qty=1}}}
DB[734]={id=734,zoneId=3,name=[[This Is Going to Be Hard]],name_loc=[[Lo tienes crudo]],level=42,minLevel=35,giver=[[Lotwil Veriatus]],giverType=[[NPC]],giverId=2921,ender=[[Lucien Tosselwrench]],ender_loc=[[Lucien Borlallave]],enderType=[[NPC]],enderId=2920,rewardNextId=777,poiX=-6624,poiY=-2721,wowhead=[[https://www.wowhead.com/wotlk/quest=734]],image=[[assets/images/quests/placeholder.png]],desc=[[Wonderful, wonderful. <Lotwil looks up at you for a moment before going back to his shackles.> Go speak to Lucien, $N. I need a cog #5. Bring it to me, will you?]],logDesc=[[Speak to Lucien Tosselwrench in the Badlands.]]}
DB[735]={id=735,zoneId=3,name=[[The Star, the Hand and the Heart]],name_loc=[[La Estrella, la Mano y el Corazón]],level=44,minLevel=30,giver=[[Gerrig Bonegrip]],giver_loc=[[Gerrig Agarrahueso]],giverType=[[NPC]],giverId=2786,ender=[[Gerrig Bonegrip]],ender_loc=[[Gerrig Agarrahueso]],enderType=[[NPC]],enderId=2786,prevId=727,nextId=737,rewardNextId=737,poiX=484,poiY=-213,wowhead=[[https://www.wowhead.com/wotlk/quest=735]],image=[[assets/images/quests/placeholder.png]],desc=[[Yagyin's Digest, eh?  Are you starting a new chapter of us, somewhere?  Never mind, it is not my place to ask. I will help you, for I have an extra copy.  We must aid each other, yes?  That is how we flourish. I require three items of power.  Bring them to me and I will give you the digest. I will not speak their names.  Ears may be on us.  But here, I will write them down.]],logDesc=[[Return the items on the Bonegrip's Note to Gerrig Bonegrip in Ironforge.]]}
DB[736]={id=736,zoneId=1497,name=[[The Star, the Hand and the Heart]],name_loc=[[La Estrella, la Mano y el Corazón]],level=44,minLevel=30,giver=[[Keeper Bel'dugur]],giver_loc=[[Vigilante Bel'dugur]],giverType=[[NPC]],giverId=2934,ender=[[Keeper Bel'dugur]],ender_loc=[[Vigilante Bel'dugur]],enderType=[[NPC]],enderId=2934,prevId=728,nextId=737,rewardNextId=737,poiX=484,poiY=-213,wowhead=[[https://www.wowhead.com/wotlk/quest=736]],image=[[assets/images/quests/placeholder.png]],desc=[[You need Yagyin's Digest?  Your plan, then, is to gather another flock?  Of course it is...and of course I will help you, $gbrother:sister;. But you must help me too. I require three items of power.  Bring me these and the digest will be yours. I cannot utter the names of these items, but I will write them down. Get me the items on this list.  If you can do that, then you are truly worthy of opening your own chapter of our order.]],logDesc=[[Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity.]]}
DB[737]={id=737,zoneId=3,name=[[Forbidden Knowledge]],name_loc=[[El saber prohibido]],level=40,minLevel=30,giver=[[Gerrig Bonegrip]],giver_loc=[[Gerrig Agarrahueso]],giverType=[[NPC]],giverId=2786,ender=[[Theldurin the Lost]],ender_loc=[[Theldurin el Perdido]],enderType=[[NPC]],enderId=2785,poiX=-7164,poiY=-3357,wowhead=[[https://www.wowhead.com/wotlk/quest=737]],image=[[assets/images/quests/placeholder.png]],desc=[[I have the digest for you, $N.  I need not tell you to take great care with it.  And to keep it far from unfriendly hands.   This book holds many truths... ...And the truth can burn.]],logDesc=[[Bring Yagyin's Digest to Theldurin.]],rewards={{id=4984,qty=1}}}
DB[737]={id=737,zoneId=3,name=[[Forbidden Knowledge]],name_loc=[[El saber prohibido]],level=40,minLevel=30,giver=[[Keeper Bel'dugur]],giver_loc=[[Gerrig Agarrahueso]],giverType=[[NPC]],giverId=2934,ender=[[Theldurin the Lost]],ender_loc=[[Theldurin el Perdido]],enderType=[[NPC]],enderId=2785,poiX=-7164,poiY=-3357,wowhead=[[https://www.wowhead.com/wotlk/quest=737]],image=[[assets/images/quests/placeholder.png]],desc=[[I have the digest for you, $N.  I need not tell you to take great care with it.  And to keep it far from unfriendly hands.   This book holds many truths... ...And the truth can burn.]],logDesc=[[Bring Yagyin's Digest to Theldurin.]],rewards={{id=4984,qty=1}}}
DB[738]={id=738,zoneId=3,name=[[Find Agmond]],name_loc=[[Encontrar a Agmond]],level=38,minLevel=30,giver=[[Prospector Ironband]],giver_loc=[[Prospector Vetaferro]],giverType=[[NPC]],giverId=1344,ender=[[Battered Dwarven Skeleton]],ender_loc=[[Esqueleto de enano maltrecho]],enderType=[[GO]],enderId=2875,prevId=707,rewardNextId=739,poiX=-6924,poiY=-3345,wowhead=[[https://www.wowhead.com/wotlk/quest=738]],image=[[assets/images/quests/placeholder.png]],desc=[[Prospector Agmond was in charge of our excavation sites in the Badlands, to the southwest.  I say "was" because...well, I haven't heard from him in weeks.  I need you to find Agmond so I can get his report. Last I heard Agmond was at the southernmost dig site in the Badlands--a tiny operation past the Angor Fortress.  I'd start your search for him there.]],logDesc=[[Find Agmond.]],rewards={{id=4982,qty=1},{id=1529,qty=1},{id=2776,qty=2}}}
DB[739]={id=739,zoneId=3,name=[[Murdaloc]],name_loc=[[Murdaloc]],level=42,minLevel=30,giver=[[Battered Dwarven Skeleton]],giver_loc=[[Esqueleto de enano maltrecho]],giverType=[[GO]],giverId=2875,ender=[[Prospector Ironband]],ender_loc=[[Prospector Vetaferro]],enderType=[[NPC]],enderId=1344,prevId=738,rewardNextId=704,poiX=-6988,poiY=-3313,wowhead=[[https://www.wowhead.com/wotlk/quest=739]],image=[[assets/images/quests/placeholder.png]],desc=[[Agmond's tracks lead from the west.  It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance. And here he died. Upon close inspection, the word "Murdaloc" is roughly scrawled in a patch of Badlands sandstone. Scrawled next to Agmond's dead hand.]],logDesc=[[Slay Agmond's killer, Murdaloc. Slay 12 Stonevault Bonesnappers. Report to Prospector Ironband in Loch Modan.]],rewards={{id=4983,qty=1}}}
DB[741]={id=741,zoneId=148,name=[[The Absent Minded Prospector]],name_loc=[[El prospector despistado]],level=20,minLevel=15,giver=[[Archaeologist Hollee]],giver_loc=[[Arqueóloga Hollee]],giverType=[[NPC]],giverId=2913,ender=[[Chief Archaeologist Greywhisker]],ender_loc=[[Arqueólogo Jefe Mostachogris]],enderType=[[NPC]],enderId=2912,prevId=731,rewardNextId=942,poiX=9642,poiY=2608,wowhead=[[https://www.wowhead.com/wotlk/quest=741]],image=[[assets/images/quests/placeholder.png]],desc=[[So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him. Here, $n, deliver the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.]],logDesc=[[Take the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.]],choiceRewards={{id=5629,qty=1},{id=5630,qty=1},{id=11936,qty=1}}}
DB[742]={id=742,zoneId=1638,name=[[The Ashenvale Hunt]],name_loc=[[La Caza de Vallefresno]],level=20,minLevel=20,giver=[[Bluff Runner Windstrider]],giver_loc=[[Asaltaviento Correbrisa]],giverType=[[NPC]],giverId=10881,ender=[[Senani Thunderheart]],ender_loc=[[Senani Corazón Atronador]],enderType=[[NPC]],enderId=12696,exGroup=235,poiX=2311,poiY=-2555,wowhead=[[https://www.wowhead.com/wotlk/quest=742]],image=[[assets/images/quests/placeholder.png]],desc=[[Attention, young adventurers!  The wilds of Ashenvale await you! The Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!]],logDesc=[[Speak with Senani Thunderheart at Splintertree Post, Ashenvale.]]}
DB[743]={id=743,zoneId=215,name=[[Dangers of the Windfury]],name_loc=[[Las Viento Furioso son un peligro]],level=8,minLevel=5,giver=[[Ruul Eagletalon]],giver_loc=[[Ruul Garraguilar]],giverType=[[NPC]],giverId=2985,ender=[[Ruul Eagletalon]],ender_loc=[[Ruul Garraguilar]],enderType=[[NPC]],enderId=2985,poiX=-2716,poiY=-1449,wowhead=[[https://www.wowhead.com/wotlk/quest=743]],image=[[assets/images/quests/placeholder.png]],desc=[[Thank you for taking the time to speak to me, $N. I am Ruul, warrior and teacher. You have obviously reached an age when you must prepare for your trials if you are to adventure much further out of Mulgore. If you wish a test of your strength, start by seeking out the Windfury harpies to the southeast. They nestle along the mountain's edges away from the road. They are one of our natural enemies here in Mulgore and will be a good gauge of your skill.]],logDesc=[[Bring 8 Windfury Talons to Ruul Eagletalon in Bloodhoof Village.]]}
DB[744]={id=744,zoneId=1638,name=[[Preparation for Ceremony]],name_loc=[[Preparación para la ceremonia]],level=11,minLevel=7,giver=[[Eyahn Eagletalon]],giver_loc=[[Eyahn Garra de Águila]],giverType=[[NPC]],giverId=2987,ender=[[Eyahn Eagletalon]],ender_loc=[[Eyahn Garra de Águila]],enderType=[[NPC]],enderId=2987,poiX=-1117,poiY=383,wowhead=[[https://www.wowhead.com/wotlk/quest=744]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him. I want to ask a favor of you while I finish tanning these leather straps. There is not time for me to find enough feathers, and I was wondering, would you gather more for me? You can find feathers of the correct size from the harpies residing far to the north and northwest of Thunder Bluff. I need only 6 azure and 6 bronze feathers to complete the design.]],logDesc=[[Collect 6 Azure Feathers and 6 Bronze Feathers, and bring them to Eyahn Eagletalon in Thunder Bluff.]],choiceRewards={{id=4968,qty=1},{id=4967,qty=1}}}
DB[745]={id=745,zoneId=215,name=[[Sharing the Land]],name_loc=[[Compartir la tierra]],level=6,minLevel=1,giver=[[Baine Bloodhoof]],giver_loc=[[Baine Pezuña de Sangre]],giverType=[[NPC]],giverId=2993,ender=[[Baine Bloodhoof]],ender_loc=[[Baine Pezuña de Sangre]],enderType=[[NPC]],enderId=2993,poiX=-2451,poiY=216,wowhead=[[https://www.wowhead.com/wotlk/quest=745]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, there are many conflicts that wound this land. It is my hope that you will not bear witness to as many of them as I have. Yet there is one that I would ask you to seek out. It will give you some sense of how terrible, if left unchecked, even a small threat can be to the land. Palemane gnolls have settled to the south of Bloodhoof and in a cave to the west. They disrespect our attempts to communicate with them, and they slay the wildlife of Mulgore unbridled. Words are no longer the answer.]],logDesc=[[Kill 10 Palemane Tanners, 8 Palemane Skinners, and 5 Palemane Poachers, then return to Baine Bloodhoof in Bloodhoof Village.]],rewards={{id=4960,qty=25}}}
DB[746]={id=746,zoneId=215,name=[[Dwarven Digging]],name_loc=[[Una excavación de los enanos]],level=8,minLevel=6,giver=[[Baine Bloodhoof]],giver_loc=[[Baine Pezuña de Sangre]],giverType=[[NPC]],giverId=2993,ender=[[Baine Bloodhoof]],ender_loc=[[Baine Pezuña de Sangre]],enderType=[[NPC]],enderId=2993,poiX=-1885,poiY=282,wowhead=[[https://www.wowhead.com/wotlk/quest=746]],image=[[assets/images/quests/placeholder.png]],desc=[[There are dwarves preparing a dig site to the northwest.  They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings. Collect the dwarven tools of digging, smash them, and return to me with the dwarves' broken tools. You can smash the tools at a forge.  You will find one in Thunder Bluff, but any forge -- even a forge at the dwarven camp -- will suffice.]],logDesc=[[Collect 5 Prospector's Picks. At a forge, smash the Prospector's Picks to create Broken Tools. Bring 5 Broken Tools to Baine Bloodhoof in Bloodhoof Village.]],choiceRewards={{id=4969,qty=1},{id=4970,qty=1}}}
DB[747]={id=747,zoneId=220,name=[[The Hunt Begins]],name_loc=[[Empieza la caza]],level=2,minLevel=1,giver=[[Grull Hawkwind]],giver_loc=[[Grull Viento de Halcón]],giverType=[[NPC]],giverId=2980,ender=[[Grull Hawkwind]],ender_loc=[[Grull Viento de Halcón]],enderType=[[NPC]],enderId=2980,poiX=-3215,poiY=-749,wowhead=[[https://www.wowhead.com/wotlk/quest=747]],image=[[assets/images/quests/placeholder.png]],desc=[[You have a promising air about you, and will prove yourself to the tribe. Perhaps someday soon you will be welcomed into the great city of Thunder Bluff. But before that can happen you must prove yourself to my father, Chief Hawkwind. Up here on Red Cloud Mesa we pride ourselves on keen hunting skills. Tauren hunt out of necessity and for sport. Our supply of meats has run low and we require feathers for clothing. Hunt the nearby plainstriders and prove yourself by resupplying the village.]],logDesc=[[Grull Hawkwind in Camp Narache wants you to bring him 7 Plainstrider Feathers and 7 pieces of Plainstrider Meat.]],choiceRewards={{id=4954,qty=1},{id=4910,qty=1}}}
DB[748]={id=748,zoneId=215,name=[[Poison Water]],name_loc=[[Pozos envenenados]],level=5,minLevel=4,giver=[[Mull Thunderhorn]],giver_loc=[[Mull Tronacuerno]],giverType=[[NPC]],giverId=2948,ender=[[Mull Thunderhorn]],ender_loc=[[Mull Tronacuerno]],enderType=[[NPC]],enderId=2948,poiX=-2450,poiY=-1050,wowhead=[[https://www.wowhead.com/wotlk/quest=748]],image=[[assets/images/quests/placeholder.png]],desc=[[Goblins and their servants have tainted our sacred water wells!  We cannot allow this. To cleanse each well, I must create a cleansing totem, then you must bring the totem to the well and perform a cleansing ritual. First we will create a cleansing totem for the Winterhoof Water Well.  To do this, the land must offer its aid. Hunt prairie wolves for their paws and adult plainstriders for their talons.  They are to the southwest. Return to me with the paws and talons, $N.]],logDesc=[[Bring 6 Prairie Wolf Paws and 4 Plainstrider Talons to Mull Thunderhorn in Bloodhoof.]]}
DB[749]={id=749,zoneId=215,name=[[The Ravaged Caravan]],name_loc=[[La Caravana Devastada]],level=8,minLevel=5,giver=[[Morin Cloudstalker]],giver_loc=[[Morin Acechanubes]],giverType=[[NPC]],giverId=2988,ender=[[Sealed Supply Crate]],ender_loc=[[Cajón de suministros sellado]],enderType=[[GO]],enderId=2908,rewardNextId=751,poiX=-1923,poiY=-713,wowhead=[[https://www.wowhead.com/wotlk/quest=749]],image=[[assets/images/quests/placeholder.png]],desc=[[A few days ago, we found a Venture Co. caravan traveling under guard on the northern shore of Stonebull Lake. We'd lost two of our number in an earlier battle, so we were quick to attack and lay waste to the caravan. We left their supply crates, thinking that our torches would destroy anything of value, but given that Venture Co. salvagers have been spotted near the burned wagons, maybe we were wrong. Perhaps you could go to the caravan and examine the contents of the crates.]],logDesc=[[Morin Cloudstalker wants you to examine the contents of a supply crate at the Ravaged Caravan.]]}
DB[750]={id=750,zoneId=220,name=[[The Hunt Continues]],name_loc=[[La caza sigue]],level=3,minLevel=1,giver=[[Grull Hawkwind]],giver_loc=[[Grull Viento de Halcón]],giverType=[[NPC]],giverId=2980,ender=[[Grull Hawkwind]],ender_loc=[[Grull Viento de Halcón]],enderType=[[NPC]],enderId=2980,prevId=747,rewardNextId=780,poiX=-3430,poiY=-931,wowhead=[[https://www.wowhead.com/wotlk/quest=750]],image=[[assets/images/quests/placeholder.png]],desc=[[A tauren skilled in the ways of the hunt knows that his prey is not for mere trophy. The beasts of the plains provide us with a means of survival. You will make quite an impression on the elders if you can bring back some highly valued Mountain Cougar Pelts. You can find the beasts lurking in the hills to the south. Our children need clothing and our tents need mending.]],logDesc=[[Grull Hawkwind in Camp Narache wants you to bring him 10 Mountain Cougar Pelts.]],choiceRewards={{id=4908,qty=1},{id=4913,qty=1}}}
DB[751]={id=751,zoneId=215,name=[[The Ravaged Caravan]],name_loc=[[La Caravana Devastada]],level=8,minLevel=5,giver=[[Sealed Supply Crate]],giver_loc=[[Cajón de suministros sellado]],giverType=[[GO]],giverId=2908,ender=[[Morin Cloudstalker]],ender_loc=[[Morin Acechanubes]],enderType=[[NPC]],enderId=2988,prevId=749,poiX=-2299,poiY=-595,wowhead=[[https://www.wowhead.com/wotlk/quest=751]],image=[[assets/images/quests/placeholder.png]],desc=[[Prying open the lid reveals a tightly packed assortment of ore and minerals, more evidence of the Venture Co.'s mining operation in Mulgore. On the top of the ore and minerals you remove a tightly bound sheaf of papers. Up in the foothills to the east, you can barely hear the sounds of work, and see smoke rising from a large fire.]],logDesc=[[Return the Venture Co. Documents to Morin Cloudstalker near Bloodhoof Village.]]}
DB[752]={id=752,zoneId=220,name=[[A Humble Task]],name_loc=[[Una humilde contribución]],level=2,minLevel=1,giver=[[Chief Hawkwind]],giver_loc=[[Jefe Viento de Halcón]],giverType=[[NPC]],giverId=2981,ender=[[Greatmother Hawkwind]],ender_loc=[[Abuela Vientaguilar]],enderType=[[NPC]],enderId=2991,rewardNextId=753,poiX=-3053,poiY=-522,wowhead=[[https://www.wowhead.com/wotlk/quest=752]],image=[[assets/images/quests/placeholder.png]],desc=[[All members of the tribe share in the harmony of life. We live together and work together. Our commitment to one another carries with it a high degree of responsibility. I ask of you now a humble task. My mother set out this morning to fetch water from the well to the southeast of Narache. It has been quite some time now. Perhaps you could check on her for me while I attend to tribal matters here?]],logDesc=[[Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache.]]}
DB[753]={id=753,zoneId=220,name=[[A Humble Task]],name_loc=[[Una humilde contribución]],level=3,minLevel=1,giver=[[Greatmother Hawkwind]],giver_loc=[[Abuela Vientaguilar]],giverType=[[NPC]],giverId=2991,ender=[[Chief Hawkwind]],ender_loc=[[Jefe Viento de Halcón]],enderType=[[NPC]],enderId=2981,prevId=752,rewardNextId=755,poiX=-3067,poiY=-539,wowhead=[[https://www.wowhead.com/wotlk/quest=753]],image=[[assets/images/quests/placeholder.png]],desc=[[I have traveled many paths through life and these old legs lack the vigor they once had. I can still perform my duties to the tribe. Sometimes it just takes an old woman a little longer to do the task. But you look like an eager $c. Let's put some of that youthful vitality to the test. Take a water pitcher from the well and bring it to my son, the Chief, in Camp Narache. Remember that even the most humble task can gain the recognition of elders.]],logDesc=[[Take a Water Pitcher from the water well. Return the pitcher to Chief Hawkwind in Camp Narache which is northwest from the water well.]]}
DB[754]={id=754,zoneId=215,name=[[Winterhoof Cleansing]],name_loc=[[La purificación de Pezuña Invernal]],level=6,minLevel=4,giver=[[Mull Thunderhorn]],giver_loc=[[Mull Tronacuerno]],giverType=[[NPC]],giverId=2948,ender=[[Mull Thunderhorn]],ender_loc=[[Mull Tronacuerno]],enderType=[[NPC]],enderId=2948,prevId=748,poiX=-2341,poiY=-445,wowhead=[[https://www.wowhead.com/wotlk/quest=754]],image=[[assets/images/quests/placeholder.png]],desc=[[I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  You will find it to the southeast, guarded by foul goblins! This will not be an easy task, but you must do it if we are ever to use its waters again. Fortune to you, $N.]],logDesc=[[Use the Winterhoof Cleansing Totem at the Winterhoof Water Well, then return to Mull Thunderhorn.]]}
DB[755]={id=755,zoneId=220,name=[[Rites of the Earthmother]],name_loc=[[Los ritos de la Madre Tierra]],level=3,minLevel=1,giver=[[Chief Hawkwind]],giver_loc=[[Jefe Viento de Halcón]],giverType=[[NPC]],giverId=2981,ender=[[Seer Graytongue]],ender_loc=[[Vidente Lenguagris]],enderType=[[NPC]],enderId=2982,prevId=753,rewardNextId=757,poiX=-3430,poiY=-139,wowhead=[[https://www.wowhead.com/wotlk/quest=755]],image=[[assets/images/quests/placeholder.png]],desc=[[Your willingness to perform a humble task for the tauren of Narache and your eagerness to learn are noble traits, $n. I believe one day you will be heralded in Thunder Bluff as a $c of greatness. Before that you must embark on the Rites of the Earthmother, of which there are three. The first test is the Rite of Strength. Travel to Seer Graytongue and tell him Chief Hawkwind has sent you. You will find the seer's abode directly to the south of Camp Narache, tucked away in the hills.]],logDesc=[[Travel to Seer Graytongue who lives in the hills directly south of Camp Narache.]]}
DB[756]={id=756,zoneId=215,name=[[Thunderhorn Totem]],name_loc=[[El tótem de Tronacuerno]],level=7,minLevel=4,giver=[[Mull Thunderhorn]],giver_loc=[[Mull Tronacuerno]],giverType=[[NPC]],giverId=2948,ender=[[Mull Thunderhorn]],ender_loc=[[Mull Tronacuerno]],enderType=[[NPC]],enderId=2948,prevId=754,poiX=-2450,poiY=-1050,wowhead=[[https://www.wowhead.com/wotlk/quest=756]],image=[[assets/images/quests/placeholder.png]],desc=[[To create the Thunderhorn Cleansing Totem, you must gather the claws of the predators of the Mulgore plains.  Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws, then return to me. You will find the prairie stalkers and flatland cougars to the east and west.]],logDesc=[[Bring 6 Stalker Claws and 6 Cougar Claws to Mull Thunderhorn.]]}
DB[757]={id=757,zoneId=220,name=[[Rite of Strength]],name_loc=[[Rito de la fuerza]],level=4,minLevel=1,giver=[[Seer Graytongue]],giver_loc=[[Vidente Lenguagris]],giverType=[[NPC]],giverId=2982,ender=[[Chief Hawkwind]],ender_loc=[[Jefe Viento de Halcón]],enderType=[[NPC]],enderId=2981,prevId=755,poiX=-2938,poiY=-1347,wowhead=[[https://www.wowhead.com/wotlk/quest=757]],image=[[assets/images/quests/placeholder.png]],desc=[[The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff. First you must pass the Rite of Strength. In this test you must prove your bravery by slaying enemies of the tribe. Bristlebacks of Brambleblade Ravine to the east are encroaching on our tribal lands. They ambush our hunting parties and steal from the village by dark. Show your valor by slaying these villains and return to the Chief in Camp Narache with their belts as proof of your deeds.]],logDesc=[[Kill Bristlebacks in Brambleblade Ravine and bring 8 Bristleback Belts to Chief Hawkwind in Camp Narache.]],choiceRewards={{id=1382,qty=1},{id=1383,qty=1},{id=2137,qty=1},{id=5776,qty=1},{id=5777,qty=1}}}
DB[758]={id=758,zoneId=215,name=[[Thunderhorn Cleansing]],name_loc=[[La purificación de Tronacuerno]],level=8,minLevel=4,giver=[[Mull Thunderhorn]],giver_loc=[[Mull Tronacuerno]],giverType=[[NPC]],giverId=2948,ender=[[Mull Thunderhorn]],ender_loc=[[Mull Tronacuerno]],enderType=[[NPC]],enderId=2948,prevId=756,poiX=-2341,poiY=-445,wowhead=[[https://www.wowhead.com/wotlk/quest=758]],image=[[assets/images/quests/placeholder.png]],desc=[[The totem is ready, $N.  And again, it is your task to perform the ritual of cleansing. Go to the Thunderhorn Water Well, north of the village, and use the Thunderhorn Cleansing Totem in your ritual.  After you do this, return to me. May the spirits guide you.]],logDesc=[[Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well, then return to Mull.]],rewards={{id=4963,qty=1}}}
DB[759]={id=759,zoneId=215,name=[[Wildmane Totem]],name_loc=[[El tótem Ferocrín]],level=10,minLevel=4,giver=[[Mull Thunderhorn]],giver_loc=[[Mull Tronacuerno]],giverType=[[NPC]],giverId=2948,ender=[[Mull Thunderhorn]],ender_loc=[[Mull Tronacuerno]],enderType=[[NPC]],enderId=2948,prevId=758,poiX=-2449,poiY=-1450,wowhead=[[https://www.wowhead.com/wotlk/quest=759]],image=[[assets/images/quests/placeholder.png]],desc=[[There is but one water well left to cleanse, named after the Wildmane clan.  For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha.  Find the alphas to the north, then return to me when your hunt is finished. Alphas often wander around the base of our mighty city, Thunder Bluff.]],logDesc=[[Bring 8 Prairie Alpha Teeth to Mull Thunderhorn in Bloodhoof Village.]]}
DB[760]={id=760,zoneId=215,name=[[Wildmane Cleansing]],name_loc=[[La purificación de Ferocrín]],level=10,minLevel=4,giver=[[Mull Thunderhorn]],giver_loc=[[Mull Tronacuerno]],giverType=[[NPC]],giverId=2948,ender=[[Mull Thunderhorn]],ender_loc=[[Mull Tronacuerno]],enderType=[[NPC]],enderId=2948,prevId=759,poiX=-2341,poiY=-445,wowhead=[[https://www.wowhead.com/wotlk/quest=760]],image=[[assets/images/quests/placeholder.png]],desc=[[Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young $N.  The Wildmane Totem is made, and your last task lies ahead. The Wildmane Water Well lies north of Thunder Bluff.  Perform the ritual!  Heal the land of the goblins' poisons!  Let clean water flow once again!]],logDesc=[[Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn.]],choiceRewards={{id=3443,qty=1},{id=4961,qty=1}}}
DB[761]={id=761,zoneId=215,name=[[Swoop Hunting]],name_loc=[[La caza de los aguilones]],level=6,minLevel=4,giver=[[Harken Windtotem]],giver_loc=[[Harken Tótem de Viento]],giverType=[[NPC]],giverId=2947,ender=[[Harken Windtotem]],ender_loc=[[Harken Tótem de Viento]],enderType=[[NPC]],enderId=2947,poiX=-2649,poiY=-1150,wowhead=[[https://www.wowhead.com/wotlk/quest=761]],image=[[assets/images/quests/placeholder.png]],desc=[[The swoop is a cunning bird, and difficult to find and hunt.  A collection of Swoop Quills is a badge of cleverness and determination for a hunter. If you are willing to take up this task, then enter the plains and hunt the swoop. Bring me their quills, and bring honor to your clan. The swoops may be found anywhere in Mulgore, but your eyes must be sharp to spot them, and your hooves must be quick to catch them.]],logDesc=[[Bring 8 Trophy Swoop Quills to Harken Windtotem in Bloodhoof Village.]]}
DB[762]={id=762,zoneId=3,name=[[An Ambassador of Evil]],name_loc=[[Un embajador del mal]],level=44,minLevel=35,giver=[[Historian Karnik]],giver_loc=[[Karnik el Historiador]],giverType=[[NPC]],giverId=2916,ender=[[Advisor Belgrum]],ender_loc=[[Consejero Belgrum]],enderType=[[NPC]],enderId=2918,prevId=726,poiX=-4620,poiY=-1325,wowhead=[[https://www.wowhead.com/wotlk/quest=762]],image=[[assets/images/quests/placeholder.png]],desc=[[Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman. It has already meant tremendous casualties for our people, but it has obviously grown worse. I hesitate to guess how many artifacts they would be able to find and use against Ironforge. Our goal is simple, $c. Return to the Badlands and destroy Ambassador Infernus. Once the threat is eliminated, return to Advisor Belgrum with proof of your victory. It is in your hands now.]],logDesc=[[Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.]],rewards={{id=4987,qty=1}}}
DB[763]={id=763,zoneId=220,name=[[Rites of the Earthmother]],name_loc=[[Los ritos de la Madre Tierra]],level=5,minLevel=1,giver=[[Chief Hawkwind]],giver_loc=[[Jefe Viento de Halcón]],giverType=[[NPC]],giverId=2981,ender=[[Baine Bloodhoof]],ender_loc=[[Baine Pezuña de Sangre]],enderType=[[NPC]],enderId=2993,prevId=757,poiX=-2334,poiY=-393,wowhead=[[https://www.wowhead.com/wotlk/quest=763]],image=[[assets/images/quests/placeholder.png]],desc=[[For you to continue with the Rites of the Earthmother you must pass two more tests. It is time for you to broaden your experience, $n. Travel to Bloodhoof Village and seek out the Chief, Baine Bloodhoof, son of Cairne. There you may continue your journey and earn the acceptance of the elders of Thunder Bluff. Take this totem to Baine. He will recognize my carvings and help you on your path. Follow the road out of Camp Narache and travel with haste. Do not stray or you will lose your way.]],logDesc=[[Take the Totem of Hawkwind to Baine Bloodhoof in Bloodhoof Village. Follow the road out of Camp Narache.]]}
DB[764]={id=764,zoneId=215,name=[[The Venture Co.]],name_loc=[[Los Ventura y Cía.]],level=10,minLevel=5,giver=[[Morin Cloudstalker]],giver_loc=[[Morin Acechanubes]],giverType=[[NPC]],giverId=2988,ender=[[Morin Cloudstalker]],ender_loc=[[Morin Acechanubes]],enderType=[[NPC]],enderId=2988,prevId=751,poiX=-1605,poiY=-1395,wowhead=[[https://www.wowhead.com/wotlk/quest=764]],image=[[assets/images/quests/placeholder.png]],desc=[[This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore. Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background. Greedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.]],logDesc=[[Kill 14 Venture Co. Workers and 6 Venture Co. Supervisors for Morin Cloudstalker at Bloodhoof Village.]]}
DB[765]={id=765,zoneId=215,name=[[Supervisor Fizsprocket]],name_loc=[[Supervisor Saltatuercas]],level=12,minLevel=5,giver=[[Morin Cloudstalker]],giver_loc=[[Morin Acechanubes]],giverType=[[NPC]],giverId=2988,ender=[[Morin Cloudstalker]],ender_loc=[[Morin Acechanubes]],enderType=[[NPC]],enderId=2988,prevId=751,poiX=-1757,poiY=-1287,wowhead=[[https://www.wowhead.com/wotlk/quest=765]],image=[[assets/images/quests/placeholder.png]],desc=[[According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands. The depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything useful.]],logDesc=[[Kill Supervisor Fizsprocket and return his clipboard to Morin Cloudstalker at Bloodhoof Village.]],choiceRewards={{id=4974,qty=1},{id=4964,qty=1}}}
DB[766]={id=766,zoneId=215,name=[[Mazzranache]],name_loc=[[Mazzranache]],level=8,minLevel=5,giver=[[Maur Raincaller]],giver_loc=[[Maur Clamalluvias]],giverType=[[NPC]],giverId=3055,ender=[[Maur Raincaller]],ender_loc=[[Maur Clamalluvias]],enderType=[[NPC]],enderId=3055,poiX=-2450,poiY=-1050,wowhead=[[https://www.wowhead.com/wotlk/quest=766]],image=[[assets/images/quests/placeholder.png]],desc=[[My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite. As fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder. He was as terrible as my grandfather described. I will need some hard-to-find animal parts to clean the infection from his bite: a wolf heart, cougar femur, plainstrider scale and swoop gizzard. Hurry, time is of the essence.]],logDesc=[[Bring a Prairie Wolf Heart, Flatland Cougar Femur, Plainstrider Scale and Swoop Gizzard to Maur Raincaller at Bloodhoof Village.]],choiceRewards={{id=4972,qty=1},{id=4973,qty=1}}}
DB[767]={id=767,zoneId=215,name=[[Rite of Vision]],name_loc=[[Rito de la Visión]],level=6,minLevel=3,giver=[[Baine Bloodhoof]],giver_loc=[[Baine Pezuña de Sangre]],giverType=[[NPC]],giverId=2993,ender=[[Zarlman Two-Moons]],ender_loc=[[Zarlman Dos Lunas]],enderType=[[NPC]],enderId=3054,prevId=763,rewardNextId=771,poiX=-2243,poiY=-406,wowhead=[[https://www.wowhead.com/wotlk/quest=767]],image=[[assets/images/quests/placeholder.png]],desc=[[The Rite of Vision, one of the Rites of the Earthmother, will help guide you toward earning the respect of the elders of Thunder Bluff. Our people have learned that the land is our most holy provider. In order to take part in the ritualistic vision, you must speak with the spiritual leader of the village, Zarlman Two-Moons.]],logDesc=[[Speak with Zarlman Two-Moons in Bloodhoof Village.]]}
DB[768]={id=768,zoneId=1638,name=[[Gathering Leather]],name_loc=[[Recolecta cuero]],level=8,minLevel=4,giver=[[Veren Tallstrider]],giver_loc=[[Veren Zancaalta]],giverType=[[NPC]],giverId=3050,ender=[[Veren Tallstrider]],ender_loc=[[Veren Zancaalta]],enderType=[[NPC]],enderId=3050,poiX=-1161,poiY=53,wowhead=[[https://www.wowhead.com/wotlk/quest=768]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, young one.  You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt.  May you bring honor to your clan! I work with the skins of beasts, fashioning them into clothes and armor for the people of Thunder Bluff. If you hunt beasts and bring me their skins, then I will fashion something for you.]],logDesc=[[Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff.]],choiceRewards={{id=5936,qty=1},{id=4962,qty=1}}}
DB[769]={id=769,zoneId=1638,name=[[Kodo Hide Bag]],name_loc=[[Bolsa de pellejo de kodo]],level=10,minLevel=4,giver=[[Veren Tallstrider]],giver_loc=[[Veren Zancaalta]],giverType=[[NPC]],giverId=3050,ender=[[Veren Tallstrider]],ender_loc=[[Veren Zancaalta]],enderType=[[NPC]],enderId=3050,prevId=768,poiX=-1161,poiY=53,wowhead=[[https://www.wowhead.com/wotlk/quest=769]],image=[[assets/images/quests/placeholder.png]],desc=[[The kodo beasts of Mulgore are strong and sturdy -- traits much respected among us.  If you are skilled in leatherworking and wish the knowledge to make a Kodo Hide Bag, then bring me supplies for my trade. Do this, and I will share my knowledge with you.]],logDesc=[[Bring 4 Light Leather and 4 Coarse Thread to Veren Tallstrider in Thunder Bluff.]],rewards={{id=5083,qty=1}}}
DB[770]={id=770,zoneId=215,name=[[The Demon Scarred Cloak]],name_loc=[[La capa del demonio marcado]],level=12,minLevel=6,giverType=[[NPC]],ender=[[Skorn Whitecloud]],ender_loc=[[Skorn Nubeblanca]],enderType=[[NPC]],enderId=3052,poiX=-2336,poiY=-354,wowhead=[[https://www.wowhead.com/wotlk/quest=770]],image=[[assets/images/quests/placeholder.png]],desc=[[The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion. Perhaps someone in Bloodhoof Village should know of Ghost Howl's demise....]],logDesc=[[Find someone who knows of Ghost Howl.]],choiceRewards={{id=4971,qty=1},{id=3079,qty=1}}}
DB[771]={id=771,zoneId=215,name=[[Rite of Vision]],name_loc=[[Rito de la Visión]],level=7,minLevel=3,giver=[[Zarlman Two-Moons]],giver_loc=[[Zarlman Dos Lunas]],giverType=[[NPC]],giverId=3054,ender=[[Zarlman Two-Moons]],ender_loc=[[Zarlman Dos Lunas]],enderType=[[NPC]],enderId=3054,prevId=767,nextId=772,poiX=-1827,poiY=-268,wowhead=[[https://www.wowhead.com/wotlk/quest=771]],image=[[assets/images/quests/placeholder.png]],desc=[[In order to pass through the Rite of Vision, you must gather the reagents needed to make the Water of the Seers. I will need well stones, which can be found around the water wells in Mulgore. With those I will combine Ambercorn, which fall beneath the mighty trees in our land. These reagents contain magical elements, and when brewed and consumed before the tribal fire, will cause you to encounter a vision. Follow it, and it will lead you to the next step of this holy quest.]],logDesc=[[Collect 2 Well Stones and 2 Ambercorn and bring them back to Zarlman Two-Moons in Bloodhoof Village.]]}
DB[772]={id=772,zoneId=215,name=[[Rite of Vision]],name_loc=[[Rito de la Visión]],level=7,minLevel=3,giver=[[Zarlman Two-Moons]],giver_loc=[[Zarlman Dos Lunas]],giverType=[[NPC]],giverId=3054,ender=[[Seer Wiserunner]],ender_loc=[[Vidente Corredor Sabio]],enderType=[[NPC]],enderId=2984,prevId=771,rewardNextId=773,poiX=-1509,poiY=367,wowhead=[[https://www.wowhead.com/wotlk/quest=772]],image=[[assets/images/quests/placeholder.png]],desc=[[I now present you with the Water of the Seers. When you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, it will take a few moments before the vision materializes before the fire. At that point, it is up to you to follow it to your destiny....]],logDesc=[[Consume the Water of the Seers in front of the tribal fire in Bloodhoof Village and follow the vision once it appears.]],choiceRewards={{id=4906,qty=1},{id=4958,qty=1}}}
DB[773]={id=773,zoneId=215,name=[[Rite of Wisdom]],name_loc=[[Rito de la Sabiduría]],level=10,minLevel=3,giver=[[Seer Wiserunner]],giver_loc=[[Vidente Corredor Sabio]],giverType=[[NPC]],giverId=2984,ender=[[Ancestral Spirit]],ender_loc=[[Espíritu ancestral]],enderType=[[NPC]],enderId=2994,prevId=772,rewardNextId=775,poiX=-993,poiY=-1109,wowhead=[[https://www.wowhead.com/wotlk/quest=773]],image=[[assets/images/quests/placeholder.png]],desc=[[To gain acceptance amongst the elders of Thunder Bluff you must next complete the Rite of Wisdom. Now that you have passed the Rite of Vision, the ancestral spirits of Red Rocks will give you the blessing of our ancestors. Only those who have drunk from the Water of Seers can gain the blessing. Travel east of Thunder Bluff, to Red Rocks and seek out the Ancestral Spirit, $n.]],logDesc=[[Travel to Red Rocks east of Thunder Bluff and speak with the Ancestral Spirit.]]}
DB[775]={id=775,zoneId=215,name=[[Journey into Thunder Bluff]],name_loc=[[Viaje a Cima del Trueno]],level=10,minLevel=3,giver=[[Ancestral Spirit]],giver_loc=[[Espíritu ancestral]],giverType=[[NPC]],giverId=2994,ender=[[Cairne Bloodhoof]],ender_loc=[[Cairne Pezuña de Sangre]],enderType=[[NPC]],enderId=3057,prevId=773,rewardNextId=776,poiX=-1210,poiY=-113,wowhead=[[https://www.wowhead.com/wotlk/quest=775]],image=[[assets/images/quests/placeholder.png]],desc=[[You will now be revered within our great city. Any $r worthy of completing the Rites of the Earthmother earns that honor. For your final quest, seek out our noble leader, Cairne Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.]],logDesc=[[Speak with Cairne Bloodhoof in Thunder Bluff.]]}
DB[776]={id=776,zoneId=215,name=[[Rites of the Earthmother]],name_loc=[[Los ritos de la Madre Tierra]],level=14,minLevel=3,giver=[[Cairne Bloodhoof]],giver_loc=[[Cairne Pezuña de Sangre]],giverType=[[NPC]],giverId=3057,ender=[[Cairne Bloodhoof]],ender_loc=[[Cairne Pezuña de Sangre]],enderType=[[NPC]],enderId=3057,prevId=775,poiX=-912,poiY=-477,wowhead=[[https://www.wowhead.com/wotlk/quest=776]],image=[[assets/images/quests/placeholder.png]],desc=[[You have passed the Rites of the Earthmother and earned your place in Thunder Bluff. But in order to maintain the spot that you strived so hard to achieve, you must continue to prove your worth to your people. We are hunters, $n. Down below in Mulgore there is a mighty kodo named Arra'chea. Show me your skills in the ways of tracking and hunting by bringing me the Horn of Arra'chea.]],logDesc=[[Cairne Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea.]],rewards={{id=4909,qty=1}}}
DB[777]={id=777,zoneId=3,name=[[This Is Going to Be Hard]],name_loc=[[Lo tienes crudo]],level=42,minLevel=35,giver=[[Lucien Tosselwrench]],giver_loc=[[Lucien Borlallave]],giverType=[[NPC]],giverId=2920,ender=[[Lotwil Veriatus]],enderType=[[NPC]],enderId=2921,prevId=734,rewardNextId=778,poiX=-6634,poiY=-2725,wowhead=[[https://www.wowhead.com/wotlk/quest=777]],image=[[assets/images/quests/placeholder.png]],desc=[[Okay, here you go. I'm going to be over here... behind cover. Feel free to join me.]],logDesc=[[Bring Cog #5 to Lotwil Veriatus.]]}
DB[778]={id=778,zoneId=3,name=[[This Is Going to Be Hard]],name_loc=[[Lo tienes crudo]],level=45,minLevel=35,giver=[[Lotwil Veriatus]],giverType=[[NPC]],giverId=2921,ender=[[Lotwil Veriatus]],enderType=[[NPC]],enderId=2921,prevId=777,poiX=-6666,poiY=-2728,wowhead=[[https://www.wowhead.com/wotlk/quest=778]],image=[[assets/images/quests/placeholder.png]],desc=[[Haha! Done! The shackles are done! It's time, Lucien. It's time, Servo! Are you ready to bear witness to the perfect blend of alchemy, engineering, and the arcane, $N? I shall summon forth a powerful elemental now. This is a groundbreaking day for all of us.]],logDesc=[[Defeat the Fam'retor Guardian and bring Lotwil's Shackles of Elemental Binding back to Lotwil Veriatus.]],rewards={{id=2820,qty=1}}}
DB[779]={id=779,zoneId=3,name=[[Seal of the Earth]],name_loc=[[El Sello de la Tierra]],level=50,minLevel=40,giver=[[Seal of the Earth]],giverType=[[GO]],giverId=2933,ender=[[Seal of the Earth]],enderType=[[GO]],enderId=2933,prevId=-717,poiX=-6434,poiY=-4157,wowhead=[[https://www.wowhead.com/wotlk/quest=779]],image=[[assets/images/quests/placeholder.png]]}
DB[780]={id=780,zoneId=220,name=[[The Battleboars]],name_loc=[[Los jabaguerreros]],level=4,minLevel=1,giver=[[Grull Hawkwind]],giver_loc=[[Grull Viento de Halcón]],giverType=[[NPC]],giverId=2980,ender=[[Grull Hawkwind]],ender_loc=[[Grull Viento de Halcón]],enderType=[[NPC]],enderId=2980,prevId=750,poiX=-2942,poiY=-1323,wowhead=[[https://www.wowhead.com/wotlk/quest=780]],image=[[assets/images/quests/placeholder.png]],desc=[[The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war. Go and slay the vile creatures and bring back some snouts and flanks so that we can make stew for our young.]],logDesc=[[Grull Hawkwind in Camp Narache wants you to kill Battleboars and bring back 8 Battleboar Snouts and 8 Battleboar Flanks.]],rewards={{id=6059,qty=1},{id=4540,qty=10}}}
DB[781]={id=781,zoneId=220,name=[[Attack on Camp Narache]],name_loc=[[Ataque al Campamento Narache]],level=4,minLevel=1,giverType=[[NPC]],ender=[[Chief Hawkwind]],ender_loc=[[Jefe Viento de Halcón]],enderType=[[NPC]],enderId=2981,poiX=-2878,poiY=-222,wowhead=[[https://www.wowhead.com/wotlk/quest=781]],image=[[assets/images/quests/placeholder.png]],desc=[[After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache. Surely Chief Hawkwind could use this information!]],logDesc=[[Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.]],rewards={{id=4911,qty=1}}}
DB[782]={id=782,zoneId=3,name=[[Broken Alliances]],name_loc=[[Alianzas rotas]],level=43,minLevel=40,giver=[[Gorn]],giverType=[[NPC]],giverId=1068,ender=[[Gorn]],enderType=[[NPC]],enderId=1068,rewardNextId=793,poiX=-7015,poiY=-3611,wowhead=[[https://www.wowhead.com/wotlk/quest=782]],image=[[assets/images/quests/placeholder.png]],desc=[[From the Horde's alliance with the dragon Deathwing during the Second War, we know that two of his lieutenants, Blacklash and Hematus, were imprisoned within Lethlor Ravine far to the east. We must silence our depraved allies of old to restore honor to the Horde! We hired Tho'grun and his band of ogre mercenaries to help us obtain the Sign of the Earth, a key needed to unlock the drakes' prison. Tho'grun betrayed us though, overwhelming us and taking it for himself. Go to Camp Boff and take it back!]],logDesc=[[Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath.]]}
DB[783]={id=783,zoneId=9,name=[[A Threat Within]],name_loc=[[Una amenaza del interior]],level=1,minLevel=1,giver=[[Deputy Willem]],giver_loc=[[Ayudante de alguacil Willem]],giverType=[[NPC]],giverId=823,ender=[[Marshal McBride]],ender_loc=[[Alguacil McBride]],enderType=[[NPC]],enderId=197,rewardNextId=7,poiX=-8903,poiY=-163,wowhead=[[https://www.wowhead.com/wotlk/quest=783]],image=[[assets/images/quests/placeholder.png]],desc=[[I hope you strapped your belt on tight, young $c, because there is work to do here in Northshire. And I don't mean farming. The Stormwind guards are hard pressed to keep the peace here, with so many of us in distant lands and so many threats pressing close.  And so we're enlisting the aid of anyone willing to defend their home.  And their alliance. If you're here to answer the call, then speak with my superior, Marshal McBride.  He's inside the abbey behind me.]],logDesc=[[Speak with Marshal McBride.]]}
DB[784]={id=784,zoneId=14,name=[[Vanquish the Betrayers]],name_loc=[[Vencer a los traidores]],level=7,minLevel=3,giver=[[Gar'Thok]],giverType=[[NPC]],giverId=3139,ender=[[Gar'Thok]],enderType=[[NPC]],enderId=3139,rewardNextId=825,poiX=-282,poiY=-5181,wowhead=[[https://www.wowhead.com/wotlk/quest=784]],image=[[assets/images/quests/placeholder.png]],desc=[[Led by Admiral Proudmoore, the humans of Kul Tiras encroached on Durotar, violating the Warchief's pact made with Jaina Proudmoore in order to defeat Archimonde years ago. The human aggression was repelled and Tiragarde Keep fell. But recently, the Admiral's reserves, led by Lieutenant Benedict, have retaken the keep and once again pose a threat to our homeland. These humans show no respect for diplomacy. Prove your honor and travel south to Tiragarde Keep to eliminate the human invaders.]],logDesc=[[Kill 10 Kul Tiras Sailors, 8 Kul Tiras Marines and Lieutenant Benedict and return to Gar'Thok in Razor Hill.]]}
DB[786]={id=786,zoneId=14,name=[[Thwarting Kolkar Aggression]],name_loc=[[Frustrar los planes kolkar]],level=8,minLevel=5,giver=[[Lar Prowltusk]],giver_loc=[[Lar Colmillo Acechador]],giverType=[[NPC]],giverId=3140,ender=[[Lar Prowltusk]],ender_loc=[[Lar Colmillo Acechador]],enderType=[[NPC]],enderId=3140,poiX=-1057,poiY=-4596,wowhead=[[https://www.wowhead.com/wotlk/quest=786]],image=[[assets/images/quests/placeholder.png]],desc=[[Lower your voice, $c. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag. Last night while they were raiding, I snuck into their village and discovered that the dirty beasts have a three-tiered attack planned on the trolls and orcs of Durotar. We mustn't let their invasion come to fruition. Perhaps you can muster the might needed to infiltrate Kolkar Crag and destroy their attack plans. Last I saw, they had divided them up amongst three of their leaders.]],logDesc=[[Lar Prowltusk outside of Sen'jin Village wants you to destroy the 3 sets of Attack Plans held within Kolkar Crag.]],choiceRewards={{id=4933,qty=1},{id=6062,qty=1}}}
DB[787]={id=787,zoneId=363,name=[[The New Horde]],name_loc=[[La nueva Horda]],level=1,minLevel=1,giver=[[Eitrigg]],giverType=[[NPC]],giverId=3144,ender=[[Gornek]],enderType=[[NPC]],enderId=3143,rewardNextId=788,poiX=-600,poiY=-4186,wowhead=[[https://www.wowhead.com/wotlk/quest=787]],image=[[assets/images/quests/placeholder.png]],desc=[[Throm'ka, $c. I am Eitrigg, charged by Thrall to oversee the training of recruits. The Horde has changed from what it once was. There was a time where I left the Horde, disillusioned by the growing influence of the power-hungry pawns of the Burning Legion. During my exile, I was taken prisoner by a group of humans, but was rescued by the Warchief. Hearing his vision of the Horde free of demonic influence, guided by the shamans, I returned. Gornek will have further instructions for you.]],logDesc=[[Report to Gornek in the Den.]]}
DB[788]={id=788,zoneId=363,name=[[Cutting Teeth]],name_loc=[[Dientes afilados]],level=2,minLevel=1,giver=[[Gornek]],giverType=[[NPC]],giverId=3143,ender=[[Gornek]],enderType=[[NPC]],enderId=3143,poiX=-483,poiY=-4453,wowhead=[[https://www.wowhead.com/wotlk/quest=788]],image=[[assets/images/quests/placeholder.png]],desc=[[The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead. I believe you would find a good match with the mottled boars you'll find to the north of here.]],logDesc=[[Kill 8 Mottled Boars then return to Gornek at the Den.]],choiceRewards={{id=4915,qty=1},{id=4914,qty=1}}}
DB[789]={id=789,zoneId=363,name=[[Sting of the Scorpid]],name_loc=[[Aguijón de escórpido]],level=3,minLevel=1,giver=[[Gornek]],giverType=[[NPC]],giverId=3143,ender=[[Gornek]],enderType=[[NPC]],enderId=3143,prevId=788,poiX=-449,poiY=-4480,wowhead=[[https://www.wowhead.com/wotlk/quest=789]],image=[[assets/images/quests/placeholder.png]],desc=[[Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here. Bring me eight of their tails as proof of your prowess in battle. The antidote for their sting is actually made from venom extracted from their stingers. We keep large quantities of antidote for scorpid venom on hand to heal young bloods just like you... But I'm sure you won't be needing any of that, will you?]],logDesc=[[Get 8 Scorpid Worker Tails for Gornek in the Den.]],choiceRewards={{id=4919,qty=1},{id=4920,qty=1}}}
DB[790]={id=790,zoneId=363,name=[[Sarkoth]],name_loc=[[Sarkoth]],level=5,minLevel=1,giver=[[Hana'zua]],giverType=[[NPC]],giverId=3287,ender=[[Hana'zua]],enderType=[[NPC]],enderId=3287,rewardNextId=804,poiX=-566,poiY=-4100,wowhead=[[https://www.wowhead.com/wotlk/quest=790]],image=[[assets/images/quests/placeholder.png]],desc=[[$C! I thought I would die out here with none to know of it. While I was hunting the scorpids of the Valley, I came across a particularly vicious-looking one. Hurling myself at it, I managed to inflict a massive blow to its claw before it closed around my leg. I wasn't ready for its stinger though, and it sliced down and into my chest, cutting into my flesh and letting my blood. Please, you must kill the scorpid for me! My honor must be upheld! I fought it up on the plateau to the south.]],logDesc=[[Kill Sarkoth and bring his claw back to Hana'zua.]]}
DB[791]={id=791,zoneId=14,name=[[Carry Your Weight]],name_loc=[[Asume tu responsabilidad]],level=7,minLevel=4,giver=[[Furl Scornbrow]],giver_loc=[[Furl Ceñosprecio]],giverType=[[NPC]],giverId=3147,ender=[[Furl Scornbrow]],ender_loc=[[Furl Ceñosprecio]],enderType=[[NPC]],enderId=3147,poiX=-1000,poiY=-4766,wowhead=[[https://www.wowhead.com/wotlk/quest=791]],image=[[assets/images/quests/placeholder.png]],desc=[[Age has rendered me useless in battle. Now I make myself useful in other ways. From this vantage point I watch for invaders. As our strength here grows, I find myself blowing the signal horn less and less. To pass the time I fashion goods to help younger, more able warriors defend our homeland. For you, I can fashion you a bag for your belongings. If such an item would be of use to you, bring me some canvas, a material common to the humans and centaurs.]],logDesc=[[Furl Scornbrow in the Razor Hill watchtower wants 8 Canvas Scraps.]],rewards={{id=11845,qty=1}}}
DB[792]={id=792,zoneId=363,name=[[Vile Familiars]],name_loc=[[Familiares viles]],level=4,minLevel=2,giver=[[Zureetha Fargaze]],giver_loc=[[Zureetha Vistalonga]],giverType=[[NPC]],giverId=3145,ender=[[Zureetha Fargaze]],ender_loc=[[Zureetha Vistalonga]],enderType=[[NPC]],enderId=3145,nextId=794,rewardNextId=794,poiX=-210,poiY=-4447,wowhead=[[https://www.wowhead.com/wotlk/quest=792]],image=[[assets/images/quests/placeholder.png]],desc=[[I trust the Valley of Trials will teach you much, young $c. I was sent to the Valley to guide you, but I have discovered a growing taint here... A group that calls itself the Burning Blade has a coven here in the Valley of Trials.  They are skulking in a cave to the northeast, and their Vile Familiars have spilled from its mouth to cause havoc. As your first task against the Burning Blade, I bid you, defeat these familiars. Slay many and, if you survive, return to me.]],logDesc=[[Kill 8 Vile Familiars. Return to Zureetha Fargaze outside the Den.]],choiceRewards={{id=4924,qty=1},{id=4925,qty=1},{id=4923,qty=1},{id=5778,qty=1}}}
DB[793]={id=793,zoneId=3,name=[[Broken Alliances]],name_loc=[[Alianzas rotas]],level=50,minLevel=40,giver=[[Gorn]],giverType=[[NPC]],giverId=1068,ender=[[Gorn]],enderType=[[NPC]],enderId=1068,prevId=782,poiX=-6715,poiY=-4104,wowhead=[[https://www.wowhead.com/wotlk/quest=793]],image=[[assets/images/quests/placeholder.png]],desc=[[The Seal of the Earth is held by three runestones, held in the Pillars of Diamond, Opal, and Amethyst in Lethlor Ravine. Using the Sign of the Earth, you will be able to remove the runestones and unlock the Seal of the Earth. Be wary though, $n, the black drakes Blacklash and Hematus are not to be trifled with. See them dead and return their bindings to me. To reach the ravine, travel to the far eastern part of the Badlands.  Be careful though, for the ravine is home to countless drakes.]],logDesc=[[Use the Sign of the Earth to activate the Pillars of Diamond, Opal, and Amethyst and obtain the Runestones. Place the runestones in the Seal of the Earth to free Blacklash and Hematus. Slay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Gorn.]],choiceRewards={{id=11193,qty=1},{id=11194,qty=1},{id=11195,qty=1},{id=11196,qty=1}}}
DB[794]={id=794,zoneId=363,name=[[Burning Blade Medallion]],name_loc=[[El medallón del Filo Ardiente]],level=5,minLevel=1,giver=[[Zureetha Fargaze]],giver_loc=[[Zureetha Vistalonga]],giverType=[[NPC]],giverId=3145,ender=[[Zureetha Fargaze]],ender_loc=[[Zureetha Vistalonga]],enderType=[[NPC]],enderId=3145,rewardNextId=805,poiX=-167,poiY=-4355,wowhead=[[https://www.wowhead.com/wotlk/quest=794]],image=[[assets/images/quests/placeholder.png]],desc=[[Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic. It is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven. But be wary, for the medallion may be possessed by an agent of the Burning Blade, and if so then the agent's power would be greater than the familiars you have already encountered. Go, $N.  You will find the coven in a cave, to the north and west.]],logDesc=[[Bring the Burning Blade Medallion to Zureetha Fargaze, outside The Den.]],rewards={{id=118,qty=1}},choiceRewards={{id=4921,qty=1},{id=4922,qty=1},{id=6713,qty=1}}}
DB[795]={id=795,zoneId=3,name=[[Seal of the Earth]],name_loc=[[El Sello de la Tierra]],level=50,minLevel=40,giver=[[Seal of the Earth]],giverType=[[GO]],giverId=2933,ender=[[Seal of the Earth]],enderType=[[GO]],enderId=2933,prevId=-793,poiX=-6434,poiY=-4157,wowhead=[[https://www.wowhead.com/wotlk/quest=795]],image=[[assets/images/quests/placeholder.png]]}
DB[804]={id=804,zoneId=363,name=[[Sarkoth]],name_loc=[[Sarkoth]],level=5,minLevel=1,giver=[[Hana'zua]],giverType=[[NPC]],giverId=3287,ender=[[Gornek]],enderType=[[NPC]],enderId=3143,prevId=790,poiX=-600,poiY=-4186,wowhead=[[https://www.wowhead.com/wotlk/quest=804]],image=[[assets/images/quests/placeholder.png]],desc=[[Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure! But it remains that I cannot make the trek back to the Den unassisted. Please, $n, return to the Den and tell Gornek of my situation. Perhaps he can help me.]],logDesc=[[Bring the news of Hana'zua's plight to Gornek at the Den.]],choiceRewards={{id=4916,qty=1},{id=4917,qty=1}}}
DB[805]={id=805,zoneId=363,name=[[Report to Sen'jin Village]],name_loc=[[Preséntate en el Poblado Sen'jin]],level=5,minLevel=1,giver=[[Zureetha Fargaze]],giver_loc=[[Zureetha Vistalonga]],giverType=[[NPC]],giverId=3145,ender=[[Master Gadrin]],ender_loc=[[Maestro Gadrin]],enderType=[[NPC]],enderId=3188,prevId=794,poiX=-826,poiY=-4921,wowhead=[[https://www.wowhead.com/wotlk/quest=805]],image=[[assets/images/quests/placeholder.png]],desc=[[Your trials against the Burning Blade are finished... here in the Valley.  But I want you to report your findings. Go to the troll village of Sen'jin and seek out Master Gadrin.  Sen'jin Village is east out of the valley, then right at the fork. Tell Gadrin of the Burning Blade, and that they have reached the Valley of Trials.  Discover from him if they have yet reached Sen'jin. Go, $N, and be swift.  I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...]],logDesc=[[Speak with Master Gadrin in Sen'jin Village.]]}
DB[806]={id=806,zoneId=14,name=[[Dark Storms]],name_loc=[[Oscuras tormentas]],level=12,minLevel=4,giver=[[Orgnil Soulscar]],giver_loc=[[Orgnil Escaralma]],giverType=[[NPC]],giverId=3142,ender=[[Orgnil Soulscar]],ender_loc=[[Orgnil Escaralma]],enderType=[[NPC]],enderId=3142,prevId=823,poiX=869,poiY=-4189,wowhead=[[https://www.wowhead.com/wotlk/quest=806]],image=[[assets/images/quests/placeholder.png]],desc=[[We cannot allow the Burning Blade a foothold in Durotar!  We must destroy them before their evil festers! I have undergone my own investigations and found that a Burning Blade warlock, the goblin Fizzle Darkstorm, has camped within Thunder Ridge to the northwest.  There he and his cultist minions spread chaos. Find and defeat Fizzle, and bring me his dead claw!]],logDesc=[[Bring Fizzle's Claw to Orgnil Soulscar in Razor Hill.]],rewards={{id=4942,qty=1}}}
DB[808]={id=808,zoneId=14,name=[[Minshina's Skull]],name_loc=[[La calavera de Minshina]],level=9,minLevel=4,giver=[[Master Gadrin]],giver_loc=[[Maestro Gadrin]],giverType=[[NPC]],giverId=3188,ender=[[Master Gadrin]],ender_loc=[[Maestro Gadrin]],enderType=[[NPC]],enderId=3188,poiX=-1287,poiY=-5530,wowhead=[[https://www.wowhead.com/wotlk/quest=808]],image=[[assets/images/quests/placeholder.png]],desc=[[I hear the voice of my brother, Minshina, calling to me in my dreams. He was taken by Zalazane, the warlock on the Echo Isles to the east. And he is dead. But death is not freedom for my brother. Minshina's spirit was trapped within his own skull by Zalazane's magics. In my dreams I see it with other skulls, in a circle of power on the largest Echo Isle. As long as it remains there my brother's soul is doomed. Please, $N. Find the circle and retrieve Minshina's skull. Bring it to me. Free him!]],logDesc=[[Retrieve Minshina's skull from the circle of power on the Echo Isles. Bring it to Master Gadrin in Sen'jin Village.]],rewards={{id=4945,qty=1}}}
DB[809]={id=809,zoneId=14,name=[[Ak'Zeloth]],name_loc=[[Ak'Zeloth]],level=13,minLevel=4,giver=[[Neeru Fireblade]],giver_loc=[[Neeru Hojafuego]],giverType=[[NPC]],giverId=3216,ender=[[Ak'Zeloth]],enderType=[[NPC]],enderId=3521,prevId=829,rewardNextId=924,poiX=256,poiY=-3694,wowhead=[[https://www.wowhead.com/wotlk/quest=809]],image=[[assets/images/quests/placeholder.png]],desc=[[Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears. It belongs to the Burning Blade, a cult that rallies around an item of demonic power.  It is called the Demon Seed, and it resides in the Barrens atop Dreadmist Peak.  It must be destroyed! Go to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  He will direct you further.]],logDesc=[[Speak with Ak'Zeloth in the Barrens.]]}
DB[812]={id=812,zoneId=14,name=[[Need for a Cure]],name_loc=[[Se necesita un remedio]],level=9,minLevel=7,giver=[[Rhinag]],giverType=[[NPC]],giverId=3190,ender=[[Rhinag]],enderType=[[NPC]],enderId=3190,poiX=1232,poiY=-4123,wowhead=[[https://www.wowhead.com/wotlk/quest=812]],image=[[assets/images/quests/placeholder.png]],desc=[[$N... your timing is perfect. I just hope I can compliment your haste as well. I was careless while fighting a few of the venomtails nearby, and one of them stung me deeply. I can feel its poison weakening me even as we speak. At this rate, I got maybe an hour left to live. But I'll need your help if I'm to do so... Kor'ghan in Orgrimmar knows how to make the antidote. Find him... and hurry, $N. I won't be able to last much longer. He should be in the Cleft of Shadow.]],logDesc=[[Find Kor'ghan in Orgrimmar and get the Venomtail Antidote. Then bring the antidote to Rhinag near the northwestern border of Durotar.]],choiceRewards={{id=4937,qty=1},{id=4929,qty=1}}}
DB[813]={id=813,zoneId=14,name=[[Finding the Antidote]],name_loc=[[En busca del antídoto]],level=9,minLevel=7,giver=[[Kor'ghan]],giverType=[[NPC]],giverId=3189,ender=[[Kor'ghan]],enderType=[[NPC]],enderId=3189,prevId=-812,poiX=851,poiY=-3918,wowhead=[[https://www.wowhead.com/wotlk/quest=813]],image=[[assets/images/quests/placeholder.png]],desc=[[Venomtails are some of the deadliest scorpids in Durotar. It was unwise for Rhinag to hunt them without having some of the antidote with him, but right now, chastising is the last thing he needs. Bring me a few venomtail poison sacs from any of the venomtails near the entrance of Orgrimmar and I'll make an antidote for him. Make haste, $N. One of our own needs your help.]],logDesc=[[Bring 4 Venomtail Poison Sacs to Kor'ghan in Orgrimmar.]],rewards={{id=4904,qty=1}}}
DB[815]={id=815,zoneId=14,name=[[Break a Few Eggs]],name_loc=[[Romper huevos]],level=8,minLevel=6,giver=[[Cook Torka]],giver_loc=[[Cocinero Torka]],giverType=[[NPC]],giverId=3191,ender=[[Cook Torka]],ender_loc=[[Cocinero Torka]],enderType=[[NPC]],enderId=3191,poiX=-672,poiY=-5648,wowhead=[[https://www.wowhead.com/wotlk/quest=815]],image=[[assets/images/quests/placeholder.png]],desc=[[Bah! I almost forgot I need to get breakfast ready. $N, get yourself movin' and get me some taillasher eggs. I'll need at least three of them if I'm going to have enough for tomorrow's meal. The Bloodtalon taillashers can be fierce, and protect their eggs to the death more often than not. They sometimes bury their eggs too deep in the earth to uncover safely, but if you head to the Echo Isles to the southeast of Sen'jin Village, you can usually find them all over those islands.]],logDesc=[[Bring 3 Taillasher Eggs to Cook Torka in Razor Hill.]],rewards={{id=4540,qty=5},{id=117,qty=5}}}
DB[816]={id=816,zoneId=14,name=[[Lost But Not Forgotten]],name_loc=[[Perdido, pero no olvidado]],level=11,minLevel=8,giver=[[Misha Tor'kren]],giverType=[[NPC]],giverId=3193,ender=[[Misha Tor'kren]],enderType=[[NPC]],enderId=3193,poiX=1247,poiY=-3918,wowhead=[[https://www.wowhead.com/wotlk/quest=816]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, please, can you help me? My son Kron went hunting days ago, and he still hasn't returned. He went west towards the Barrens to hunt crocolisks along Southfury River. I fear the worst. As strong as he was, his stubborn pride has always drawn him into trouble. I warned him that the crocolisks were powerful and vicious. He grew angry and stormed off. If you can't find him, at least bring me a sign of his fate... even if you have to open up the stomach of every crocolisk along the Southfury's banks.]],logDesc=[[Bring a sign of Kron's fate to Misha Tor'kren at the farmstead northwest of Razor Hill.]],rewards={{id=4944,qty=1}}}
DB[817]={id=817,zoneId=14,name=[[Practical Prey]],name_loc=[[Presa práctica]],level=8,minLevel=5,giver=[[Vel'rin Fang]],giver_loc=[[Vel'rin Colmillo]],giverType=[[NPC]],giverId=3194,ender=[[Vel'rin Fang]],ender_loc=[[Vel'rin Colmillo]],enderType=[[NPC]],enderId=3194,poiX=-1350,poiY=-5216,wowhead=[[https://www.wowhead.com/wotlk/quest=817]],image=[[assets/images/quests/placeholder.png]],desc=[[Many of the hides we use come from Durotar tigers, $N. Blankets, armor, tents: there are a great many reasons we hunt the beasts, and many reasons we let them thrive at the same time. The time has come for us to cull the flock, so to speak. Our numbers grow, and our needs are beginning to overwhelm our stocks. I need more hides if I'm to prepare suitable goods for our people. Bring me 4 Durotar tiger furs, and I shall reward you. You can find them on the islands south of here.]],logDesc=[[Bring 4 Durotar Tiger Furs to Vel'rin Fang in Sen'jin Village.]]}
DB[818]={id=818,zoneId=14,name=[[A Solvent Spirit]],name_loc=[[Un espíritu responsable]],level=7,minLevel=5,giver=[[Master Vornal]],giver_loc=[[Maestro Vornal]],giverType=[[NPC]],giverId=3304,ender=[[Master Vornal]],ender_loc=[[Maestro Vornal]],enderType=[[NPC]],enderId=3304,poiX=-616,poiY=-5552,wowhead=[[https://www.wowhead.com/wotlk/quest=818]],image=[[assets/images/quests/placeholder.png]],desc=[[Although my eyes fail me, I still can see clearly enough. More often I must rely on my alchemical skills to aid me in magics that once came easily. But I refuse to take on an apprentice--no troll or orc worthy enough has ever come forward. Are you worthy? Yes, of course you are... of course you think you are. I need a few things. Will you get them for me? I need intact makrura eyes, and vials of crawler mucus. You can find them on any makrura or crawler in Durotar. We shall speak again soon.]],logDesc=[[Bring 4 Intact Makrura Eyes and 8 vials of Crawler Mucus to Master Vornal in Sen'jin Village.]],rewards={{id=4941,qty=10}}}
DB[819]={id=819,zoneId=17,name=[[Chen's Empty Keg]],name_loc=[[El barril vacío de Chen]],level=15,minLevel=11,giverType=[[NPC]],ender=[[Brewmaster Drohn]],ender_loc=[[Maestro cervecero Drohn]],enderType=[[NPC]],enderId=3292,rewardNextId=821,poiX=-981,poiY=-3686,wowhead=[[https://www.wowhead.com/wotlk/quest=819]],image=[[assets/images/quests/placeholder.png]],desc=[[A small placard on one of the ends of the keg says, "Chen Stormstout- May your spirit be raised and always raise your spirits."]],logDesc=[[Find someone who knows about Chen's Empty Keg.]]}
DB[821]={id=821,zoneId=17,name=[[Chen's Empty Keg]],name_loc=[[El barril vacío de Chen]],level=15,minLevel=11,giver=[[Brewmaster Drohn]],giver_loc=[[Maestro cervecero Drohn]],giverType=[[NPC]],giverId=3292,ender=[[Brewmaster Drohn]],ender_loc=[[Maestro cervecero Drohn]],enderType=[[NPC]],enderId=3292,prevId=819,rewardNextId=822,poiX=-650,poiY=-3715,wowhead=[[https://www.wowhead.com/wotlk/quest=821]],image=[[assets/images/quests/placeholder.png]],desc=[[Would you like a taste of Chen's namesake? Ahh, the stormstout is a mighty brew. Chen taught the recipe to my mentor, and my mentor passed it on to me. I'll need you to get me a few things, but I can tell you this: the kick is worth it. Bring me 5 savannah lion tusks from any savannah lion, 5 plainstrider kidneys from any plainstrider, and 1 thunder lizard horn from any species of thunder lizard. That should do the trick nicely. You can find these ingredients throughout the Barrens.]],logDesc=[[Bring 5 Savannah Lion Tusks, 5 Plainstrider Kidneys, and 1 Thunder Lizard Horn to Brewmaster Drohn in Ratchet.]],rewards={{id=4952,qty=5}}}
DB[822]={id=822,zoneId=17,name=[[Chen's Empty Keg]],name_loc=[[El barril vacío de Chen]],level=24,minLevel=11,giver=[[Brewmaster Drohn]],giver_loc=[[Maestro cervecero Drohn]],giverType=[[NPC]],giverId=3292,ender=[[Brewmaster Drohn]],ender_loc=[[Maestro cervecero Drohn]],enderType=[[NPC]],enderId=3292,prevId=821,poiX=-3584,poiY=-2482,wowhead=[[https://www.wowhead.com/wotlk/quest=822]],image=[[assets/images/quests/placeholder.png]],desc=[[Good stuff, that stormstout, huh? I have another recipe that I learned from Chen. Would you be interested? It won't take long to make, and it might be useful if you plan on adventuring some more. Bring me 5 lightning glands from any stormhide, 1 thunderhawk saliva gland from greater thunderhawks, and a kodo liver from any of the Barrens' kodos. Like I said, this stuff has kick; it's the trogg ale that I mentioned to you before.]],logDesc=[[Bring 5 Lightning Glands, 1 Thunderhawk Saliva Gland and 1 Kodo Liver to Brewmaster Drohn in Ratchet.]],rewards={{id=4953,qty=5}}}
DB[823]={id=823,zoneId=14,name=[[Report to Orgnil]],name_loc=[[Informa a Orgnil]],level=7,minLevel=4,giver=[[Master Gadrin]],giver_loc=[[Maestro Gadrin]],giverType=[[NPC]],giverId=3188,ender=[[Orgnil Soulscar]],ender_loc=[[Orgnil Escaralma]],enderType=[[NPC]],enderId=3142,prevId=805,poiX=287,poiY=-4725,wowhead=[[https://www.wowhead.com/wotlk/quest=823]],image=[[assets/images/quests/placeholder.png]],desc=[[We at Sen'jin Village are not without our own troubles, and we thank you for your aid.  But the news you bring regarding the Burning Blade could be trouble for everyone. There is an orc stationed at Razor Hill, Orgnil Soulscar, who polices Durotar from evils such as the Burning Blade!  Go to Orgnil and tell him of our plight, as well as your news from the Valley of Trials.  He will want to know these things. Razor Hill lies to the north.]],logDesc=[[Speak with Orgnil Soulscar in Razor Hill.]]}
DB[824]={id=824,zoneId=331,name=[[Je'neu of the Earthen Ring]],name_loc=[[Je'neu del Anillo de la Tierra]],level=27,minLevel=23,giver=[[Mastok Wrilehiss]],giver_loc=[[Mastok Bufido]],giverType=[[NPC]],giverId=12737,ender=[[Je'neu Sancrea]],ender_loc=[[Je'neu Sancrea]],enderType=[[NPC]],enderId=12736,prevId=1918,poiX=1958,poiY=-946,wowhead=[[https://www.wowhead.com/wotlk/quest=824]],image=[[assets/images/quests/placeholder.png]],desc=[[The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements.  They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know. Lucky for you, I know someone in the Earthen Ring here in Ashenvale.  Head over to Zoram'gar Outpost on the coast of the Zoram Strand; show Je'neu Sancrea what you found.  If anyone can figure out that globe's significance, it'd be him.]],logDesc=[[Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.]],choiceRewards={{id=16659,qty=1},{id=16660,qty=1},{id=16661,qty=1}}}
DB[825]={id=825,zoneId=14,name=[[From The Wreckage....]],name_loc=[[Los restos del naufragio...]],level=8,minLevel=3,giver=[[Gar'Thok]],giverType=[[NPC]],giverId=3139,ender=[[Gar'Thok]],enderType=[[NPC]],enderId=3139,prevId=784,poiX=-80,poiY=-5386,wowhead=[[https://www.wowhead.com/wotlk/quest=825]],image=[[assets/images/quests/placeholder.png]],desc=[[One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep. It is no secret that the humans, in alliance with those foul little creatures known as gnomes, have an advanced knowledge of mechanics. We must have a complete understanding of all our potential enemies. And our people will benefit from this new knowledge as well. Swim through the wreckage, $n, and retrieve for me the tools of the Alliance.]],logDesc=[[Gar'Thok of Razor Hill wants you to retrieve 3 Gnomish Tools from the wreckage off the coast.]],choiceRewards={{id=4936,qty=1},{id=4928,qty=1},{id=4935,qty=1}}}
DB[826]={id=826,zoneId=14,name=[[Zalazane]],name_loc=[[Zalazane]],level=10,minLevel=4,giver=[[Master Gadrin]],giver_loc=[[Maestro Gadrin]],giverType=[[NPC]],giverId=3188,ender=[[Master Gadrin]],ender_loc=[[Maestro Gadrin]],enderType=[[NPC]],enderId=3188,poiX=-1135,poiY=-5587,wowhead=[[https://www.wowhead.com/wotlk/quest=826]],image=[[assets/images/quests/placeholder.png]],desc=[[The witchdoctor Zalazane dwells on the Echo Isles to the east.  They are the isles we once called home. From there he sends his trolls to the mainland, to hex our people and drag more of them under his sway. He must be stopped. Defeat Zalazane and his minions -- former Darkspear trolls, now lost to us.  Bring me his head and I will know his reign of evil is over.]],logDesc=[[Defeat Zalazane. Kill 8 Voodoo Trolls and 8 Hexed Trolls. Bring Zalazane's Head to Gadrin.]],choiceRewards={{id=4946,qty=1},{id=4940,qty=1}}}
DB[827]={id=827,zoneId=14,name=[[Skull Rock]],name_loc=[[Roca del Cráneo]],level=12,minLevel=4,giver=[[Margoz]],giverType=[[NPC]],giverId=3208,ender=[[Margoz]],enderType=[[NPC]],enderId=3208,prevId=828,poiX=1463,poiY=-4871,wowhead=[[https://www.wowhead.com/wotlk/quest=827]],image=[[assets/images/quests/placeholder.png]],desc=[[$N.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars. By wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study. Go to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.]],logDesc=[[Gather Searing Collars from the cultists in Skull Rock. Bring them to Margoz at his camp.]],choiceRewards={{id=4947,qty=1},{id=4939,qty=1},{id=4948,qty=1}}}
DB[828]={id=828,zoneId=14,name=[[Margoz]],name_loc=[[Margoz]],level=12,minLevel=4,giver=[[Orgnil Soulscar]],giver_loc=[[Orgnil Escaralma]],giverType=[[NPC]],giverId=3142,ender=[[Margoz]],enderType=[[NPC]],enderId=3208,prevId=806,rewardNextId=827,poiX=1102,poiY=-4945,wowhead=[[https://www.wowhead.com/wotlk/quest=828]],image=[[assets/images/quests/placeholder.png]],desc=[[One of our Shamans, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains - just outside Orgrimmar! - that shelters a large band of Burning Blade cultists. Before you go to Skull Rock speak with Margoz.  He is wise and his council is valued. He is camped to the northeast, between the coast and Drygulch Ravine. Follow his advice, but whatever Margoz says, $N, I still want you to crush those cultists!]],logDesc=[[Speak with Margoz.]]}
DB[829]={id=829,zoneId=14,name=[[Neeru Fireblade]],name_loc=[[Neeru Hojafuego]],level=12,minLevel=4,giver=[[Margoz]],giverType=[[NPC]],giverId=3208,ender=[[Neeru Fireblade]],ender_loc=[[Neeru Hojafuego]],enderType=[[NPC]],enderId=3216,prevId=827,rewardNextId=809,poiX=1801,poiY=-4375,wowhead=[[https://www.wowhead.com/wotlk/quest=829]],image=[[assets/images/quests/placeholder.png]],desc=[[The Searing Collars you brought me are powerful, demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them. Take a searing collar to Neeru Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar. You may find Neeru in Orgrimmar in the Cleft of Shadow.]],logDesc=[[Bring an Example Collar to Neeru Fireblade in Orgrimmar.]]}
DB[830]={id=830,zoneId=14,name=[[The Admiral's Orders]],name_loc=[[Las órdenes del almirante]],level=7,minLevel=1,giverType=[[NPC]],ender=[[Gar'Thok]],enderType=[[NPC]],enderId=3139,rewardNextId=831,poiX=275,poiY=-4709,wowhead=[[https://www.wowhead.com/wotlk/quest=830]],image=[[assets/images/quests/placeholder.png]],desc=[[You open the aged and weathered envelope and discover an official looking document. You recognize the seal of Admiral Proudmoore. This looks important. Perhaps Gar'Thok, the commander of Razor Hill, would be interested in having this information.]],logDesc=[[Take Admiral Proudmoore's Orders to Gar'Thok in Razor Hill.]]}
DB[831]={id=831,zoneId=14,name=[[The Admiral's Orders]],name_loc=[[Las órdenes del almirante]],level=7,minLevel=1,giver=[[Gar'Thok]],giverType=[[NPC]],giverId=3139,ender=[[Vol'jin]],enderType=[[NPC]],enderId=10540,prevId=830,poiX=1939,poiY=-4184,wowhead=[[https://www.wowhead.com/wotlk/quest=831]],image=[[assets/images/quests/placeholder.png]],desc=[[Humans cannot be trusted. We fought alongside them with a weary heart, knowing they would betray us one day. Admiral Proudmoore's death was not enough to stop his legacy of deceit. The human scum had his plans well laid out before he ever met his demise. His reign won't even die with Benedict it seems. Who knows how long it will be before the next waves of Proudmoore's men land upon our shores. We need to get these orders to Vol'jin in Orgrimmar immediately! He can be found in Thrall's chamber.]],logDesc=[[Deliver Admiral Proudmoore's Orders to Vol'jin in Thrall's chamber in Orgrimmar.]]}
DB[832]={id=832,zoneId=14,name=[[Burning Shadows]],name_loc=[[Sombras Ardientes]],level=12,minLevel=4,giverType=[[NPC]],ender=[[Neeru Fireblade]],ender_loc=[[Neeru Hojafuego]],enderType=[[NPC]],enderId=3216,poiX=1801,poiY=-4375,wowhead=[[https://www.wowhead.com/wotlk/quest=832]],image=[[assets/images/quests/placeholder.png]],desc=[[<Words emanate from the pendant and into your mind.> Gazz'uz? Gazz'uz...report! There is word of your discovery in Skull Rock.  You must prepare for an attack! Gazz'uz, I order you to speak!  Speak or I will make sure Neeru Fireblade knows of your presence, and he will descend on you with swift brutality. Do not test your skills against Neeru... ...Gazz'uz, are you there...?]],logDesc=[[Take this eye to Neeru Fireblade in Orgrimmar.]]}
DB[833]={id=833,zoneId=215,name=[[A Sacred Burial]],name_loc=[[Cementerio sagrado]],level=10,minLevel=7,giver=[[Lorekeeper Raintotem]],giver_loc=[[Tradicionalista Tótem de Lluvia]],giverType=[[NPC]],giverId=3233,ender=[[Lorekeeper Raintotem]],ender_loc=[[Tradicionalista Tótem de Lluvia]],enderType=[[NPC]],enderId=3233,poiX=-991,poiY=-1156,wowhead=[[https://www.wowhead.com/wotlk/quest=833]],image=[[assets/images/quests/placeholder.png]],desc=[[Only the most valiant tauren are laid to rest at Red Rocks, our sacred burial ground. It is an honor bestowed upon the great warriors who helped found and defend Thunder Bluff and those who have given their lives for the greater good of their tribes and chieftains. But it appears a foul menace has made its way onto our holy land. A band of Bristleback Interlopers is ravaging the grave site and I am too old and past my prime to drive them away. They must be driven off with force, $n.]],logDesc=[[Lorekeeper Raintotem wants you to kill 8 Bristleback Interlopers at Red Rocks.]]}
DB[834]={id=834,zoneId=14,name=[[Winds in the Desert]],name_loc=[[Las arpías Viento Seco]],level=9,minLevel=7,giver=[[Rezlak]],giver_loc=[[Rezlak]],giverType=[[NPC]],giverId=3293,ender=[[Rezlak]],ender_loc=[[Rezlak]],enderType=[[NPC]],enderId=3293,rewardNextId=835,poiX=829,poiY=-4696,wowhead=[[https://www.wowhead.com/wotlk/quest=834]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm Rezlak, one of Gazlowe's boys. Boss sent me to help the orcs here in Durotar. Things'd been going good except for the caravans. Can't manage to keep them safe! Makes my job a little harder, you know? The last shipment--they promised it'd get through!--was snatched by the Dustwind harpies of...where was it...Razorwind Canyon? I gotta have those supplies or I'll never get anything done! Follow the big canyon to the south, you'll find the ravine cut right into the west and east sides of the walls.]],logDesc=[[Retrieve 5 Sacks of Supplies and return them to Rezlak near Orgrimmar.]]}
DB[835]={id=835,zoneId=14,name=[[Securing the Lines]],name_loc=[[Asegurar las rutas]],level=11,minLevel=7,giver=[[Rezlak]],giver_loc=[[Rezlak]],giverType=[[NPC]],giverId=3293,ender=[[Rezlak]],ender_loc=[[Rezlak]],enderType=[[NPC]],enderId=3293,prevId=834,poiX=847,poiY=-4819,wowhead=[[https://www.wowhead.com/wotlk/quest=835]],image=[[assets/images/quests/placeholder.png]],desc=[[Gazlowe told me once, "Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself." I can't deal with losing all our caravans, so I'm just going to take matters into my own hands. Drygulch Ravine lies through the eastern part of Razorwind Canyon. If we kill all the harpies there, the routes will be safe. Of course, there was one other thing that Gazlowe taught me, and that's "You can get anything done for a price." So, going to help me out, $n?]],logDesc=[[Kill 12 Dustwind Savages and 8 Dustwind Storm Witches for Rezlak near Drygulch Ravine.]],choiceRewards={{id=4932,qty=1},{id=4931,qty=1},{id=4938,qty=1}}}
DB[836]={id=836,zoneId=47,name=[[Rescue OOX-09/HL!]],name_loc=[[¡Rescata a OOX-09/TI!]],level=48,minLevel=43,giver=[[Homing Robot OOX-09/HL]],giver_loc=[[Robot mensajero OOX-09/TI]],giverType=[[NPC]],giverId=7806,ender=[[Oglethorpe Obnoticus]],ender_loc=[[Oglethorpe Obnoticus]],enderType=[[NPC]],enderId=7406,prevId=485,nextId=3721,exGroup=-648,poiX=-14417,poiY=411,wowhead=[[https://www.wowhead.com/wotlk/quest=836]],image=[[assets/images/quests/placeholder.png]],desc=[[The gnome's voice crackles once again from the robot: "I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, some big rocks that obscure visibility! That should be a perfect place, and long enough, to get things online!" "Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!"]],logDesc=[[Escort OOX-09/HL to safety, then report to Oglethorpe Obnoticus in Booty Bay.]],choiceRewards={{id=9645,qty=1},{id=9646,qty=1}}}
DB[837]={id=837,zoneId=14,name=[[Encroachment]],name_loc=[[Invasión]],level=10,minLevel=6,giver=[[Gar'Thok]],giverType=[[NPC]],giverId=3139,ender=[[Gar'Thok]],enderType=[[NPC]],enderId=3139,poiX=83,poiY=-4651,wowhead=[[https://www.wowhead.com/wotlk/quest=837]],image=[[assets/images/quests/placeholder.png]],desc=[[When we arrived, the Razormane quilboars possessed much of the land, and proved a thorn in our sides. Through our efforts we have driven out the largest part of their numbers, but still they remain well-fortified in some areas. It has gone on long enough, however. For our own protection, we cannot allow the Razormane any hold in our lands. Their camps can be found to the west of here. Look for the brambles and you will find them. Today we drive them from Durotar, tomorrow, perhaps from all of Kalimdor.]],logDesc=[[Kill 4 Razormane Quilboars, 4 Razormane Scouts, 4 Razormane Dustrunners and 4 Razormane Battleguards for Gar'Thok at Razor Hill.]]}
DB[838]={id=838,zoneId=28,name=[[Scholomance]],name_loc=[[Scholomance]],level=55,minLevel=55,giver=[[High Executor Derrington]],giver_loc=[[Sumo ejecutor Derrington]],giverType=[[NPC]],giverId=10837,ender=[[Apothecary Dithers]],ender_loc=[[Boticario Dithers]],enderType=[[NPC]],enderId=11057,prevId=5098,rewardNextId=964,poiX=1752,poiY=-730,wowhead=[[https://www.wowhead.com/wotlk/quest=838]],image=[[assets/images/quests/placeholder.png]],desc=[[On the island of Caer Darrow lies Scholomance - a school that serves as a stronghold for the Scourge.  Our enemy dwells within, safely allowed to pursue research that strengthens their power.  A door bars the way, and try as we might no entry is to be had without a proper key. Apothecary Dithers is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your value to me as someone who can get things done; I now entrust this task to you.  Speak with him on this matter.]],logDesc=[[Speak with Apothecary Dithers at the Bulwark, Western Plaguelands.]]}
DB[840]={id=840,zoneId=14,name=[[Conscript of the Horde]],name_loc=[[Nuevo recluta de la Horda]],level=12,minLevel=10,giver=[[Takrin Pathseeker]],giver_loc=[[Takrin Abrecaminos]],giverType=[[NPC]],giverId=3336,ender=[[Kargal Battlescar]],ender_loc=[[Kargal Marca de Guerra]],enderType=[[NPC]],enderId=3337,rewardNextId=842,poiX=303,poiY=-3686,wowhead=[[https://www.wowhead.com/wotlk/quest=840]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmm, you look pretty strong. Listen, my good friend Kargal needs some new recruits for Barrens duty. I know you want to do what's right for the Horde. Well, this is your chance. Take this recruitment letter to Kargal and see if he'll sign it.]],logDesc=[[Follow the western road from Razor Hill to the Barrens over a bridge. Stop at the orc outpost across the bridge. Give Kargal Battlescar at the Barrens outpost your recruitment letter.]]}
DB[841]={id=841,zoneId=440,name=[[Another Power Source?]],name_loc=[[¿Otra fuente de alimentación?]],level=46,minLevel=38,giver=[[Chief Engineer Bilgewhizzle]],giver_loc=[[Ingeniero jefe Pasaquillas]],giverType=[[NPC]],giverId=7407,ender=[[Chief Engineer Bilgewhizzle]],ender_loc=[[Ingeniero jefe Pasaquillas]],enderType=[[NPC]],enderId=7407,prevId=379,poiX=-7480,poiY=-4786,wowhead=[[https://www.wowhead.com/wotlk/quest=841]],image=[[assets/images/quests/placeholder.png]],desc=[[Let me guess - you didn't get whatever world-ending, nefarious deed you were doing done in time.  No wait, better still... you dropped it in the sand!  Well, whatever the reason, I do have additional power sources I will sell to you.  This time, however, it will cost you ten, YES TEN Wastewander Water Pouches! Times are tough all around, $n, and power sources don't grow on trees!  Hrm, but what if they did.  Maybe we could MAKE a power source tree...]],logDesc=[[Bring 10 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan in exchange for another power source.]],rewards={{id=8524,qty=1}}}
DB[842]={id=842,zoneId=14,name=[[Crossroads Conscription]],name_loc=[[Servicio militar en El Cruce]],level=12,minLevel=10,giver=[[Kargal Battlescar]],giver_loc=[[Kargal Marca de Guerra]],giverType=[[NPC]],giverId=3337,ender=[[Sergra Darkthorn]],ender_loc=[[Sergra Espinoscura]],enderType=[[NPC]],enderId=3338,prevId=840,poiX=-482,poiY=-2670,wowhead=[[https://www.wowhead.com/wotlk/quest=842]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this signed recruitment letter to the Crossroads. Sergra Darkthorn, curse her hide, is in charge there. She's a nasty shaman who will talk your head in circles before she lets you do anything useful. Thrall is convinced she's something special, but I'm not so sure. You'll just have to decide for yourself, pup...]],logDesc=[[Follow the western road from Kargal's Far Watch Outpost. At the T intersection, turn left and follow the road south.  Find Sergra Darkthorn at the crossing of roads within the Crossroads.]]}
DB[843]={id=843,zoneId=17,name=[[Gann's Reclamation]],name_loc=[[La reclamación de Gann]],level=23,minLevel=17,giver=[[Gann Stonespire]],giver_loc=[[Gann Aguja de Piedra]],giverType=[[NPC]],giverId=3341,ender=[[Gann Stonespire]],ender_loc=[[Gann Aguja de Piedra]],enderType=[[NPC]],enderId=3341,rewardNextId=846,poiX=-4198,poiY=-2284,wowhead=[[https://www.wowhead.com/wotlk/quest=843]],image=[[assets/images/quests/placeholder.png]],desc=[[In solitude I wander these roads. The dwarves of Bael Modan show no respect for my land. Horrendous blasts drive holes deep into the ground as noisy machines rip apart the hills. Lands which once served as home and provider to my tribe are now riddled with destructive dwarves. Attempts at reaching a diplomatic resolution have failed. Now is the time for decisive action. Drive the dwarves from the Bael Modan excavation by force and bring to me the journal of their leader, Prospector Khazgorm.]],logDesc=[[Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen. Bring Khazgorm's Journal to Gann Stonespire.]]}
DB[844]={id=844,zoneId=17,name=[[Plainstrider Menace]],name_loc=[[La amenaza de los zancudos de llanura]],level=12,minLevel=10,giver=[[Sergra Darkthorn]],giver_loc=[[Sergra Espinoscura]],giverType=[[NPC]],giverId=3338,ender=[[Sergra Darkthorn]],ender_loc=[[Sergra Espinoscura]],enderType=[[NPC]],enderId=3338,rewardNextId=845,poiX=-717,poiY=-3950,wowhead=[[https://www.wowhead.com/wotlk/quest=844]],image=[[assets/images/quests/placeholder.png]],desc=[[Your first prey will be easy. The plainstriders to the east have been harassing our food supplies and have become a nuisance. Put down the plainstriders and return to me with their beaks.]],logDesc=[[Collect 7 Plainstrider Beaks and return them to Sergra Darkthorn in the Crossroads.]]}
DB[845]={id=845,zoneId=17,name=[[The Zhevra]],name_loc=[[La zhebra]],level=13,minLevel=10,giver=[[Sergra Darkthorn]],giver_loc=[[Sergra Espinoscura]],giverType=[[NPC]],giverId=3338,ender=[[Sergra Darkthorn]],ender_loc=[[Sergra Espinoscura]],enderType=[[NPC]],enderId=3338,prevId=844,rewardNextId=903,poiX=-216,poiY=-2184,wowhead=[[https://www.wowhead.com/wotlk/quest=845]],image=[[assets/images/quests/placeholder.png]],desc=[[The zhevra, although not the fiercest beast in the Barrens, are a shade tougher than the plainstriders.  Don't worry -- we'll send you against bigger prey in good time, but for now your teeth could use a little more cutting. Hunt the zhevra to the north and south, and collect their hooves.  Bring them to me and perhaps we'll next send you against something tougher.]],logDesc=[[Slay Zhevra Runners to collect 4 Zhevra Hooves for Sergra Darkthorn in the Crossroads.]]}
DB[846]={id=846,zoneId=17,name=[[Revenge of Gann]],name_loc=[[La venganza de Gann]],level=26,minLevel=17,giver=[[Gann Stonespire]],giver_loc=[[Gann Aguja de Piedra]],giverType=[[NPC]],giverId=3341,ender=[[Gann Stonespire]],ender_loc=[[Gann Aguja de Piedra]],enderType=[[NPC]],enderId=3341,prevId=843,rewardNextId=849,poiX=-4070,poiY=-2419,wowhead=[[https://www.wowhead.com/wotlk/quest=846]],image=[[assets/images/quests/placeholder.png]],desc=[[It is clear the prospector depended on explosives and those noisy vehicles to rip the ground apart. We can expect a new foreman to take over soon. I want to give the dwarves a taste of their own medicine. According to these plans if we combine nitroglycerin with wood pulp and sodium nitrate we can create an explosive charge. The rifleman, soldiers and officers in the Keep are known to have the supplies. Collect these items and bring them to me. I will fashion a charge that the dwarves won't forget!]],logDesc=[[Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate.]]}
DB[847]={id=847,zoneId=45,name=[[Guile of the Raptor]],name_loc=[[La astucia del raptor]],level=37,minLevel=29,giver=[[Gor'mul]],giverType=[[NPC]],giverId=2792,ender=[[Tor'gan]],enderType=[[NPC]],enderId=2706,prevId=702,poiX=-1004,poiY=-3557,wowhead=[[https://www.wowhead.com/wotlk/quest=847]],image=[[assets/images/quests/placeholder.png]],desc=[[This... this power.... Is this the power of the shamans that Tor'gan tried to show me? I must say, it is interesting. Tell Tor'gan that he has convinced me... for the time being. I will listen to what he has to say.]],logDesc=[[Speak with Tor'gan at Hammerfall in Arathi Highlands.]],rewards={{id=4546,qty=1}}}
DB[848]={id=848,zoneId=17,name=[[Fungal Spores]],name_loc=[[Esporas de hongos]],level=15,minLevel=10,giver=[[Apothecary Helbrim]],giver_loc=[[Boticario Helbrim]],giverType=[[NPC]],giverId=3390,ender=[[Apothecary Helbrim]],ender_loc=[[Boticario Helbrim]],enderType=[[NPC]],enderId=3390,poiX=26,poiY=-2005,wowhead=[[https://www.wowhead.com/wotlk/quest=848]],image=[[assets/images/quests/placeholder.png]],desc=[[The oases of the Barrens hide a mystery.  Life energy flows from their waters, invigorating the plants and beasts that drink it. Invigorating, and altering. There is a mushroom that grows near these oases.  Its spores hold properties that we, the apothecaries of Lordaeron, find useful. Bring me these spores and you will earn our gratitude.]],logDesc=[[Bring 4 Fungal Spores to Apothecary Helbrim at the Crossroads.]]}
DB[849]={id=849,zoneId=17,name=[[Revenge of Gann]],name_loc=[[La venganza de Gann]],level=26,minLevel=17,giver=[[Gann Stonespire]],giver_loc=[[Gann Aguja de Piedra]],giverType=[[NPC]],giverId=3341,ender=[[Gann Stonespire]],ender_loc=[[Gann Aguja de Piedra]],enderType=[[NPC]],enderId=3341,prevId=846,poiX=-4173,poiY=-2137,wowhead=[[https://www.wowhead.com/wotlk/quest=849]],image=[[assets/images/quests/placeholder.png]],desc=[[Following Khazgorm's plans it should be no problem to fashion an explosive charge Ah, there we go. Now, $n, I am going to entrust you with a special task. Take this explosive stick and use it to blow up the flying machine at Bael Modan. Not only is the flying machine a key part of the site's infrastructure it also serves as a weapon of war. More importantly it is an icon of power and an insult to the memory of my tribe. Make me proud by completing this heroic task and you shall be rewarded.]],logDesc=[[Destroy the flying machine at Bael Modan and return to Gann Stonespire.]],rewards={{id=5313,qty=1}}}
DB[850]={id=850,zoneId=17,name=[[Kolkar Leaders]],name_loc=[[Los jefes Kolkar]],level=16,minLevel=11,giver=[[Regthar Deathgate]],giver_loc=[[Regthar Portamorta]],giverType=[[NPC]],giverId=3389,ender=[[Regthar Deathgate]],ender_loc=[[Regthar Portamorta]],enderType=[[NPC]],enderId=3389,poiX=23,poiY=-1716,wowhead=[[https://www.wowhead.com/wotlk/quest=850]],image=[[assets/images/quests/placeholder.png]],desc=[[The centaurs have plagued the Tauren for years.  And recently, the Kolkar centaurs of the Barrens have grown into a real threat.  Normally they were disorganized in these lands, but new leaders have risen among them.  Rallying them. To preserve our holdings here, these centaur leaders must be destroyed. Bring me the head of Barak Kodobane.  He camps near the Forgotten Pools to the north. Defeat him, then return to me.]],logDesc=[[Bring Barak's Head to Regthar Deathgate, west of the Crossroads.]]}
DB[851]={id=851,zoneId=17,name=[[Verog the Dervish]],name_loc=[[Verog el Derviche]],level=18,minLevel=11,giver=[[Regthar Deathgate]],giver_loc=[[Regthar Portamorta]],giverType=[[NPC]],giverId=3389,ender=[[Regthar Deathgate]],ender_loc=[[Regthar Portamorta]],enderType=[[NPC]],enderId=3389,prevId=850,rewardNextId=852,poiX=-1211,poiY=-2726,wowhead=[[https://www.wowhead.com/wotlk/quest=851]],image=[[assets/images/quests/placeholder.png]],desc=[[The centaur Verog the Dervish wanders the Barrens, and will be difficult to find.  But he is based at the centaur command tent at the Stagnant Oasis to the southeast.  It may be possible to draw him to you. Travel to the Stagnant Oasis to the southeast and attack centaur near the command tent.  It will be dangerous, but if you can kill enough centaur then they should raise an alarm.  And Verog will come. Bring me his head and I will place it with Barak Kodobane's.]],logDesc=[[Bring Verog's Head to Regthar Deathgate, west of the Crossroads.]]}
DB[852]={id=852,zoneId=17,name=[[Hezrul Bloodmark]],name_loc=[[Hezrul Marcasangre]],level=19,minLevel=11,giver=[[Regthar Deathgate]],giver_loc=[[Regthar Portamorta]],giverType=[[NPC]],giverId=3389,ender=[[Regthar Deathgate]],ender_loc=[[Regthar Portamorta]],enderType=[[NPC]],enderId=3389,prevId=851,poiX=-882,poiY=-2053,wowhead=[[https://www.wowhead.com/wotlk/quest=852]],image=[[assets/images/quests/placeholder.png]],desc=[[Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens.  He is fierce, brutal and cunning.  Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us. So kill him.  As with Barak and Verog, bring me Hezrul's Head. He leads his people from the Lushwater Oasis, to the south.]],logDesc=[[Bring Hezrul's Head to Regthar Deathgate, west of the Crossroads.]],rewards={{id=5351,qty=1}}}
DB[853]={id=853,zoneId=17,name=[[Apothecary Zamah]],name_loc=[[Boticaria Zamah]],level=15,minLevel=10,giver=[[Apothecary Helbrim]],giver_loc=[[Boticario Helbrim]],giverType=[[NPC]],giverId=3390,ender=[[Apothecary Zamah]],ender_loc=[[Boticaria Zamah]],enderType=[[NPC]],enderId=3419,prevId=848,poiX=-995,poiY=279,wowhead=[[https://www.wowhead.com/wotlk/quest=853]],image=[[assets/images/quests/placeholder.png]],desc=[[I have rendered the spores you gave me into an emulsion.  I must now send it to my associate, Apothecary Zamah.  If you were to carry this to her, she can offer you something from our stores of alchemical goods. She is in the Pools of Vision, a cave beneath the shamans of Thunder Bluff.  The path to this cave is well hidden, but you may find it on the Spirit Rise bluff. Do hurry.  This emulsion will maintain its potency for only a short time, and must be resealed and processed before then.]],logDesc=[[Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up.]],rewards={{id=5340,qty=1}},choiceRewards={{id=2458,qty=4},{id=2457,qty=4},{id=2456,qty=3},{id=2459,qty=2}}}
DB[854]={id=854,zoneId=215,name=[[Journey to the Crossroads]],name_loc=[[Viaja a El Cruce]],level=12,minLevel=9,giver=[[Kirge Sternhorn]],giver_loc=[[Kirge Astadura]],giverType=[[NPC]],giverId=3418,ender=[[Thork]],enderType=[[NPC]],enderId=3429,poiX=-473,poiY=-2596,wowhead=[[https://www.wowhead.com/wotlk/quest=854]],image=[[assets/images/quests/placeholder.png]],desc=[[I have foreseen your arrival, young $c. Though perhaps you are not so young anymore. I think that it is time for you to move deeper into this land. I can sense that you are destined for great things. It is the Crossroads that you must seek out, for our lives with the orcs have become intertwined and they need assistance. Continue down this road towards the east and follow it north to the Crossroads. Find Thork within its walls, he has the Earthmother's blessing.]],logDesc=[[Speak with Thork at the Crossroads in the Barrens.]]}
DB[855]={id=855,zoneId=17,name=[[Centaur Bracers]],name_loc=[[Los brazales centauro]],level=14,minLevel=9,giver=[[Regthar Deathgate]],giver_loc=[[Regthar Portamorta]],giverType=[[NPC]],giverId=3389,ender=[[Regthar Deathgate]],ender_loc=[[Regthar Portamorta]],enderType=[[NPC]],enderId=3389,poiX=-1150,poiY=-3198,wowhead=[[https://www.wowhead.com/wotlk/quest=855]],image=[[assets/images/quests/placeholder.png]],desc=[[The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops.  And so, I have a bounty task for you. While in Kolkar territories, slay their warriors and collect centaur bracers.  Return when you have a heap of bracers and the Horde will reward you well.]],logDesc=[[Bring 15 Centaur Bracers to Regthar Deathgate, west of the Crossroads.]],choiceRewards={{id=5346,qty=1},{id=5344,qty=1},{id=5345,qty=1}}}
DB[857]={id=857,zoneId=17,name=[[The Tear of the Moons]],name_loc=[[La Lágrima de las Lunas]],level=30,minLevel=22,giver=[[Feegly the Exiled]],giver_loc=[[Feegly el Exiliado]],giverType=[[NPC]],giverId=3421,ender=[[Feegly the Exiled]],ender_loc=[[Feegly el Exiliado]],enderType=[[NPC]],enderId=3421,poiX=-4080,poiY=-2355,wowhead=[[https://www.wowhead.com/wotlk/quest=857]],image=[[assets/images/quests/placeholder.png]],desc=[[The power was mine! In my very hands! And I want it back! Back I say! Those dirty excavators uncovered it... so beautiful it was. Deemed the Tear of the Moons, it was the first great discovery we made at Bael Modan. It should have been mine! Mine I say! General Twinbraid grew jealous of the power it gave me. He locked it away in the Keep. Called it cursed, he did! The fool! Others wanted it and they had to be stopped! That fiend Twinbraid drove me off. Now I want it back. Back I say!]],logDesc=[[Feegly the Exiled wants you to retrieve for him the Tear of the Moons.]]}
DB[858]={id=858,zoneId=17,name=[[Ignition]],name_loc=[[La llave de contacto]],level=18,minLevel=13,giver=[[Wizzlecrank's Shredder]],giver_loc=[[Machacador de Rabiaire]],giverType=[[NPC]],giverId=3439,ender=[[Wizzlecrank's Shredder]],ender_loc=[[Machacador de Rabiaire]],enderType=[[NPC]],enderId=3439,poiX=1020,poiY=-3080,wowhead=[[https://www.wowhead.com/wotlk/quest=858]],image=[[assets/images/quests/placeholder.png]],desc=[[I don't suppose Sputtervalve sent you? I'm in a bind here. I hopped in without realizing that I need a key to unlock the shredder's movement column. One of the other shredder operators asked me if everything was okay, and I panicked! Instead of telling him that I was missing my key, I told him there was some sort of mechanical problem. We need to get out of here on the double! Go up to the control room at the top of the derrick, the supervisor should have a key for this shredder. Help me out here!]],logDesc=[[Get the Ignition Key and bring it to Wizzlecrank.]]}
DB[860]={id=860,zoneId=17,name=[[Sergra Darkthorn]],name_loc=[[Sergra Espinoscura]],level=10,minLevel=10,giver=[[Melor Stonehoof]],giver_loc=[[Melor Pezuña Pétrea]],giverType=[[NPC]],giverId=3441,ender=[[Sergra Darkthorn]],ender_loc=[[Sergra Espinoscura]],enderType=[[NPC]],enderId=3338,prevId=861,rewardNextId=844,poiX=-482,poiY=-2670,wowhead=[[https://www.wowhead.com/wotlk/quest=860]],image=[[assets/images/quests/placeholder.png]],desc=[[If you wish to walk the hunter's path, then your journey leads to the Barrens.  Its beasts are strong-willed and fierce.  You will learn much by hunting there, and your spirit will grow. Speak with Sergra Darkthorn.  She will be your first guide in the Barrens. Sergra is at the Crossroads.  To reach her, travel east from Bloodhoof Village into the Barrens, then north as the road forks.  And have care as you travel--the Barrens holds great danger for the unprepared and unwary.]],logDesc=[[Speak with Sergra Darkthorn at the Crossroads in the Barrens.]]}
DB[861]={id=861,zoneId=215,name=[[The Hunter's Way]],name_loc=[[Los hábitos del cazador]],level=10,minLevel=10,giver=[[Skorn Whitecloud]],giver_loc=[[Skorn Nubeblanca]],giverType=[[NPC]],giverId=3052,ender=[[Melor Stonehoof]],ender_loc=[[Melor Pezuña Pétrea]],enderType=[[NPC]],enderId=3441,poiX=-1084,poiY=-1150,wowhead=[[https://www.wowhead.com/wotlk/quest=861]],image=[[assets/images/quests/placeholder.png]],desc=[[You are eager to explore, I can tell.  I too had the lust to wander, once... Wander, and hunt.  For hunting is a Tauren's greatest honor. If you truly wish to follow the ways of the hunter, then Melor Stonehoof can show you the path.  He is in Thunder Bluff, on the Hunter's Rise. And to show him your skill and resolve, bring him the claws of the flatland prowlers of Mulgore.  They are tough and cunning -- fitting prey for a young $c on the hunter's path.]],logDesc=[[Bring 4 Flatland Prowler Claws to Melor Stonehoof in Thunder Bluff.]]}
DB[862]={id=862,name=[[Dig Rat Stew]],name_loc=[[Estofado de ratas de madriguera]],level=23,minLevel=15,giver=[[Grub]],giver_loc=[[Larva]],giverType=[[NPC]],giverId=3443,ender=[[Grub]],ender_loc=[[Larva]],enderType=[[NPC]],enderId=3443,poiX=-4070,poiY=-2421,wowhead=[[https://www.wowhead.com/wotlk/quest=862]],image=[[assets/images/quests/placeholder.png]],desc=[[A $c like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long. Tell you what, I'll fix you up a nice stew. Just need a few dig rats. Seems those filthy dwarves at Bael Modan are overrun with everyone's favorite feast. Now head on down south to Bael Modan and bring me back some dig rats. You can't call yourself a seasoned adventurer until you've spent some time killing rats! Haw!]],logDesc=[[Bring 8 Dig Rats to Grub east of the Crossroads.]],rewards={{id=5487,qty=1},{id=5478,qty=5},{id=10919,qty=1}}}
DB[863]={id=863,zoneId=17,name=[[The Escape]],name_loc=[[La fuga]],level=18,minLevel=13,giver=[[Wizzlecrank's Shredder]],giver_loc=[[Machacador de Rabiaire]],giverType=[[NPC]],giverId=3439,ender=[[Sputtervalve]],ender_loc=[[Petardol]],enderType=[[NPC]],enderId=3442,prevId=858,poiX=-902,poiY=-3759,wowhead=[[https://www.wowhead.com/wotlk/quest=863]],image=[[assets/images/quests/placeholder.png]],desc=[[I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?]],logDesc=[[Protect Wizzlecrank and the stolen goblin shredder on the way to Sputtervalve in Ratchet.]],choiceRewards={{id=5326,qty=1},{id=5327,qty=1}}}
DB[864]={id=864,zoneId=1497,name=[[Return to Apothecary Zinge]],name_loc=[[Regresa junto a la boticaria Zinge]],level=46,minLevel=38,giver=[[Chief Engineer Bilgewhizzle]],giver_loc=[[Ingeniero jefe Pasaquillas]],giverType=[[NPC]],giverId=7407,ender=[[Apothecary Zinge]],ender_loc=[[Boticaria Zinge]],enderType=[[NPC]],enderId=5204,prevId=654,poiX=1443,poiY=392,wowhead=[[https://www.wowhead.com/wotlk/quest=864]],image=[[assets/images/quests/placeholder.png]],desc=[["Here you go, the power source is safely removed and the data is preserved.  Well, safe journeys and all that.  Hope the nefarious science experiment worked out for you and all." The goblin turns away from you to attend to the demands of the Gadgetzan Water Company.  You secure the sealed testing kit for the journey back to the Undercity.  Apothecary Zinge waits for you and the sealed field testing kit there.]],logDesc=[[Bring the Sealed Field Testing Kit to Apothecary Zinge in the Undercity.]],choiceRewards={{id=9634,qty=1},{id=9635,qty=1},{id=11502,qty=1}}}
DB[865]={id=865,zoneId=17,name=[[Raptor Horns]],name_loc=[[Los cuernos de raptor]],level=18,minLevel=13,giver=[[Mebok Mizzyrix]],giverType=[[NPC]],giverId=3446,ender=[[Mebok Mizzyrix]],enderType=[[NPC]],enderId=3446,poiX=705,poiY=-3581,wowhead=[[https://www.wowhead.com/wotlk/quest=865]],image=[[assets/images/quests/placeholder.png]],desc=[[The raptors of the Barrens are smarter than raptors in other lands.  And I think all that smarts is hiding in their horns!  If so, then I could grind their horns into powder and use it to make "smart drinks."  I could sell them for a fortune!!! And you can help me.  Find me intact raptor horns from sunscale scytheclaws.  They roam in the southern Barrens, and in the northern Barrens near the border of Ashenvale Forest.]],logDesc=[[Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet.]],rewards={{id=5342,qty=5},{id=5343,qty=1}}}
DB[866]={id=866,name=[[Root Samples]],name_loc=[[Recoge muestras de raíces]],level=16,minLevel=9,giver=[[Mebok Mizzyrix]],giverType=[[NPC]],giverId=3446,ender=[[Mebok Mizzyrix]],enderType=[[NPC]],enderId=3446,poiX=-929,poiY=-3697,wowhead=[[https://www.wowhead.com/wotlk/quest=866]],image=[[assets/images/quests/placeholder.png]],desc=[[The herbs of the Barrens are not quite like herbs in other lands.  Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different. I want to study those differences... to see if they're exploitable! If you are skilled in herbalism, then gather root samples off the herbs you find in the Barrens.  Bring back these samples so that I may compare them with herbs from other regions.]],logDesc=[[Bring 8 Root Samples to Mebok Mizzyrix in Ratchet.]],rewards={{id=5341,qty=1}}}
DB[867]={id=867,zoneId=17,name=[[Harpy Raiders]],name_loc=[[Arpías saqueadoras]],level=15,minLevel=12,giver=[[Darsok Swiftdagger]],giver_loc=[[Darsok Movedaga]],giverType=[[NPC]],giverId=3449,ender=[[Darsok Swiftdagger]],ender_loc=[[Darsok Movedaga]],enderType=[[NPC]],enderId=3449,rewardNextId=875,poiX=332,poiY=-1620,wowhead=[[https://www.wowhead.com/wotlk/quest=867]],image=[[assets/images/quests/placeholder.png]],desc=[[The blasted harpies have been ravaging our caravan supplies for too long. It's time we slit a few of their throats and diminished their numbers. I've been snooping around their nests and figured out who leads who. The most devastating attack will destroy a good section of their lower chain of command and then we can work our way to the top. I'll start you off slow, take out Witchwing Harpies and Witchwing Roguefeathers in the Northwest and bring me 8 Witchwing talons. That should be a good start...]],logDesc=[[Collect 8 Witchwing talons. Return them to Darsok Swiftdagger at the Crossroads.]]}
DB[868]={id=868,zoneId=17,name=[[Egg Hunt]],name_loc=[[¡A cazar huevos!]],level=22,minLevel=17,giver=[[Korran]],giverType=[[NPC]],giverId=3428,ender=[[Korran]],enderType=[[NPC]],enderId=3428,poiX=-3112,poiY=-2283,wowhead=[[https://www.wowhead.com/wotlk/quest=868]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey, $N. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar. One object of my studies are the insect-like creatures found to the south in the Field of Giants. We know little of the creatures, so I be makin' it a point to discover more. They seem to have intelligence to them, more so than any normal animal. Take this digging claw and collect some of the creatures' eggs from their mounds, but be careful: if alerted, they will attack you.]],logDesc=[[Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads.]],choiceRewards={{id=6503,qty=1},{id=6502,qty=1}}}
DB[869]={id=869,zoneId=17,name=[[Raptor Thieves]],name_loc=[[Los raptores ladrones]],level=13,minLevel=9,giver=[[Gazrog]],giverType=[[NPC]],giverId=3464,ender=[[Gazrog]],enderType=[[NPC]],enderId=3464,rewardNextId=3281,poiX=-1050,poiY=-2417,wowhead=[[https://www.wowhead.com/wotlk/quest=869]],image=[[assets/images/quests/placeholder.png]],desc=[[Not long ago, a shipment of silver was stolen from our guard tower.  It was meant as payroll to the Crossroads' guards, and we want that silver back. The strange thing is... we caught one of the thieves on the night of the theft.  And... it was a raptor!  Unbelievable! I don't know what raptors would want with silver.  But I don't care -- I want the raptors dead so they won't steal from us again! Hunt raptors in the Barrens.  Collect for me their heads!]],logDesc=[[Bring 12 Raptor Heads to Gazrog at the Crossroads.]]}
DB[870]={id=870,zoneId=17,name=[[The Forgotten Pools]],name_loc=[[Las Charcas del Olvido]],level=13,minLevel=10,giver=[[Tonga Runetotem]],giver_loc=[[Tonga Tótem de Runa]],giverType=[[NPC]],giverId=3448,ender=[[Tonga Runetotem]],ender_loc=[[Tonga Tótem de Runa]],enderType=[[NPC]],enderId=3448,rewardNextId=877,poiX=90,poiY=-2049,wowhead=[[https://www.wowhead.com/wotlk/quest=870]],image=[[assets/images/quests/placeholder.png]],desc=[[Long ago, the Barrens was a lush place, teeming with life.  But war and cataclysm raged across the land, scorching it and leaving a dry husk.  Such is the way of things, and it saddens my heart. But within the past few years, new oases have formed in the Barrens, and life stirs.  And deep down, we druids sense a power leaking its way to the surface. We must find its source.  Travel to the Forgotten Pools, northwest of the Crossroads.  Search its waters for a source of power, then return here.]],logDesc=[[Report back to Tonga Runetotem with your findings.]]}
DB[871]={id=871,zoneId=17,name=[[Disrupt the Attacks]],name_loc=[[Acabar con los ataques de los Crines de Acero]],level=12,minLevel=9,giver=[[Thork]],giverType=[[NPC]],giverId=3429,ender=[[Thork]],enderType=[[NPC]],enderId=3429,poiX=-165,poiY=-3038,wowhead=[[https://www.wowhead.com/wotlk/quest=871]],image=[[assets/images/quests/placeholder.png]],desc=[[All the quilboars are our enemies, $N. Some just prove to be more of a nuisance than others. The Razormane tribe has been attacking our supply lines from Durotar, causing us no end of annoyance. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us. Start in the northeast towards Durotar. You can always tell their dens from the huge thorny vines that come up from the earth. Seek them out, and slay them.]],logDesc=[[Of the Razormane tribe, kill 8 Water Seekers, 8 Thornweavers and 3 Hunters, and then return to Thork in the Crossroads.]]}
DB[872]={id=872,zoneId=17,name=[[The Disruption Ends]],name_loc=[[El fin de las hostilidades]],level=15,minLevel=9,giver=[[Thork]],giverType=[[NPC]],giverId=3429,ender=[[Thork]],enderType=[[NPC]],enderId=3429,prevId=871,poiX=-41,poiY=-3420,wowhead=[[https://www.wowhead.com/wotlk/quest=872]],image=[[assets/images/quests/placeholder.png]],desc=[[One of my scouts witnessed an attack on a caravan from Durotar, $N. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout. He was seen northeast of here, just south of the road from Durotar. If the threat is to be ended, then Kreenig must die. To be sure the attacks cease, though, I say we add insult to their injury. Kill Kreenig along with more of their tribe, and return to me when you have his tusk.]],logDesc=[[Kill 8 Razormane Geomancers, 8 Razormane Defenders, and Kreenig Snarlsnout. Then bring Kreenig Snarlsnout's Tusk to Thork at the Crossroads.]],choiceRewards={{id=5275,qty=1},{id=5328,qty=1}}}
DB[873]={id=873,zoneId=17,name=[[Isha Awak]],name_loc=[[Isha Awak]],level=27,minLevel=10,giver=[[Mahren Skyseer]],giver_loc=[[Mahren Vidente del Cielo]],giverType=[[NPC]],giverId=3388,ender=[[Mahren Skyseer]],ender_loc=[[Mahren Vidente del Cielo]],enderType=[[NPC]],enderId=3388,prevId=874,poiX=-1351,poiY=-4048,wowhead=[[https://www.wowhead.com/wotlk/quest=873]],image=[[assets/images/quests/placeholder.png]],desc=[[The grand Isha Awak is lord of these waters.  Great is his strength, and solemn his pride.  The humans on the coast fear him, for he has consumed many of their number. But I do not fear him.  I am grateful he is here.  He is a worthy challenge, and honorable prey. If you are ready, then swim out and search for Isha Awak, the Deep Doom. His spirit dwells in his heart, and to hear its beat is to know your fate.]],logDesc=[[Bring the Heart of Isha Awak to Mahren Skyseer.]],rewards={{id=5355,qty=1}},choiceRewards={{id=5356,qty=1},{id=5357,qty=1}}}
DB[874]={id=874,zoneId=17,name=[[Mahren Skyseer]],name_loc=[[Mahren Vidente del Cielo]],level=27,minLevel=9,giver=[[Jorn Skyseer]],giver_loc=[[Jorn Vidente del Cielo]],giverType=[[NPC]],giverId=3387,ender=[[Mahren Skyseer]],ender_loc=[[Mahren Vidente del Cielo]],enderType=[[NPC]],enderId=3388,prevId=913,rewardNextId=873,poiX=-1351,poiY=-4048,wowhead=[[https://www.wowhead.com/wotlk/quest=874]],image=[[assets/images/quests/placeholder.png]],desc=[[You have hunted the beasts of the Barrens.  Your spirit is strong.  But a hunter must always be prepared.  A true hunter can stalk prey down any path.  Mountains and swamps will not sway $ghim:her;. Not even the sea. Find my sister, Mahren.  She hunts the great water beasts along the coast.  She will be your teacher in their ways. But be wary in your search for her, for the Barrens' coast is held by humans.]],logDesc=[[Speak with Mahren Skyseer.]]}
DB[875]={id=875,zoneId=17,name=[[Harpy Lieutenants]],name_loc=[[Las tenientes arpías]],level=16,minLevel=12,giver=[[Darsok Swiftdagger]],giver_loc=[[Darsok Movedaga]],giverType=[[NPC]],giverId=3449,ender=[[Darsok Swiftdagger]],ender_loc=[[Darsok Movedaga]],enderType=[[NPC]],enderId=3449,prevId=867,rewardNextId=876,poiX=567,poiY=-1460,wowhead=[[https://www.wowhead.com/wotlk/quest=875]],image=[[assets/images/quests/placeholder.png]],desc=[[Hahaha, $n. Back for more? Good, I like to hear that. This time I want you to assassinate some of the harpy lieutenants in the Dry Hills. Only Witchwing Slayers can be lieutenants, and you can tell them apart by the rings they carry. They are a nasty bunch, but they lead some of the underlings in that area. Taking out 6 of them will be a decisive strike against their matriarchy. Make sure they die painfully, $n. We want those harpy wenches to know the idiocy of picking fights with the Horde.]],logDesc=[[Collect 6 Harpy Lieutenant Rings from Witchwing Slayers and return them to Darsok Swiftdagger at the Crossroads.]]}
DB[876]={id=876,zoneId=17,name=[[Serena Bloodfeather]],name_loc=[[Serena Sangrepluma]],level=20,minLevel=12,giver=[[Darsok Swiftdagger]],giver_loc=[[Darsok Movedaga]],giverType=[[NPC]],giverId=3449,ender=[[Darsok Swiftdagger]],ender_loc=[[Darsok Movedaga]],enderType=[[NPC]],enderId=3449,prevId=875,poiX=790,poiY=-1346,wowhead=[[https://www.wowhead.com/wotlk/quest=876]],image=[[assets/images/quests/placeholder.png]],desc=[[You did so well with the lieutenants and underlings that I'd like you to do one last thing for me. Serena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago. Apparently, these attacks on the Horde caravans are revenge for her sister's death. I need you to slit her throat and bring me back her head. I want to place it on the next caravan we send out... Give those harpies something to think about.]],logDesc=[[Slay Serena Bloodfeather and return her head to Darsok Swiftdagger at the Crossroads.]],choiceRewards={{id=5321,qty=1},{id=5279,qty=1},{id=5318,qty=1}}}
DB[877]={id=877,zoneId=17,name=[[The Stagnant Oasis]],name_loc=[[El Oasis Estancado]],level=16,minLevel=10,giver=[[Tonga Runetotem]],giver_loc=[[Tonga Tótem de Runa]],giverType=[[NPC]],giverId=3448,ender=[[Tonga Runetotem]],ender_loc=[[Tonga Tótem de Runa]],enderType=[[NPC]],enderId=3448,prevId=870,rewardNextId=880,poiX=-1276,poiY=-3012,wowhead=[[https://www.wowhead.com/wotlk/quest=877]],image=[[assets/images/quests/placeholder.png]],desc=[[Like the one you found at the Forgotten Pools, there may be fissures at the other oases in the Barrens.  If so, then perhaps the fissures are the oases' source of life. We must test this. Here, take these seeds.  They are dead and infertile, but take them to the Stagnant Oasis to the southeast.  If there is a fissure there, then place the seeds within it...and observe.]],logDesc=[[Return to Tonga at The Crossroads, after investigating the Stagnant Oasis.]]}
DB[878]={id=878,zoneId=17,name=[[Tribes at War]],name_loc=[[Tribus en guerra]],level=21,minLevel=14,giver=[[Mangletooth]],giver_loc=[[Quebrantadientes]],giverType=[[NPC]],giverId=3430,ender=[[Mangletooth]],ender_loc=[[Quebrantadientes]],enderType=[[NPC]],enderId=3430,poiX=-1951,poiY=-2215,wowhead=[[https://www.wowhead.com/wotlk/quest=878]],image=[[assets/images/quests/placeholder.png]],desc=[[You must strike my enemies. <snort> You must help Mangletooth and the Razormane by weakening the Bristlebacks. Both tribes are very spiritual--tied to the earth and its power. <snort> It gives us strength in all things... especially war. If you want to find out who really causes Thork <snort> and the Horde such anguish, then help Mangletooth! You attack the spiritual leaders of the Bristlebacks to the north; weaken them so the Razormanes can defeat them and rule the Barrens.]],logDesc=[[Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens.]]}
DB[879]={id=879,zoneId=17,name=[[Betrayal from Within]],name_loc=[[Traidores]],level=25,minLevel=17,giver=[[Mangletooth]],giver_loc=[[Quebrantadientes]],giverType=[[NPC]],giverId=3430,ender=[[Mangletooth]],ender_loc=[[Quebrantadientes]],enderType=[[NPC]],enderId=3430,prevId=5052,rewardNextId=906,poiX=-3764,poiY=-1833,wowhead=[[https://www.wowhead.com/wotlk/quest=879]],image=[[assets/images/quests/placeholder.png]],desc=[[Three of my tribe came out of the Kraul to lead the raids against the Horde, $r. <snort> They are ruthless and cunning, and if you defeat them, then your Crossroads and even most of the Barrens will learn peace... <snort> at least from the Razormane tribe. <snort> Nak, Kuz, and Lok Orcbane are the ones you seek. They are far to the south  of the Barrens. One is a spell caster, another a tracker, and their leader, the one called Orcbane, <snort> a warrior. Kill them, $r, like they have killed me.]],logDesc=[[Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens.]]}
DB[880]={id=880,zoneId=17,name=[[Altered Beings]],name_loc=[[Seres alterados]],level=16,minLevel=10,giver=[[Tonga Runetotem]],giver_loc=[[Tonga Tótem de Runa]],giverType=[[NPC]],giverId=3448,ender=[[Tonga Runetotem]],ender_loc=[[Tonga Tótem de Runa]],enderType=[[NPC]],enderId=3448,prevId=877,poiX=-1127,poiY=-2248,wowhead=[[https://www.wowhead.com/wotlk/quest=880]],image=[[assets/images/quests/placeholder.png]],desc=[[Your findings are incredible, $N.  These oases hold properties that must come from an outside source.  Or perhaps an inside one. I want to know how these fissures are affecting the beasts who drink from the oases' water. Hunt oasis snapjaws at the Lushwater and Stagnant Oases.  Bring me their shells so I may examine them.]],logDesc=[[Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads.]]}
DB[881]={id=881,zoneId=17,name=[[Echeyakee]],name_loc=[[Echeyakee]],level=16,minLevel=10,giver=[[Sergra Darkthorn]],giver_loc=[[Sergra Espinoscura]],giverType=[[NPC]],giverId=3338,ender=[[Sergra Darkthorn]],ender_loc=[[Sergra Espinoscura]],enderType=[[NPC]],enderId=3338,prevId=903,rewardNextId=905,poiX=454,poiY=-3036,wowhead=[[https://www.wowhead.com/wotlk/quest=881]],image=[[assets/images/quests/placeholder.png]],desc=[[Whitemist, Echeyakee in the Tauren tongue, is the king of the savannah cats.  He hunts with such stealth, they say he's like a thin, white mist on the earth.  And he kills so fast his prey have no time for fear, or pain. The Tauren say he is both mercy and death. You will learn if that's true, for I now set you on the path to hunt Echeyakee.  His lair is northeast of the Crossroads, among the bones of giant Kodo Go.  Blow this horn when you reach his lair.  Blow the horn, and he will come.]],logDesc=[[Bring Echeyakee's Hide to Sergra Darkthorn at the Crossroads.]]}
DB[882]={id=882,zoneId=17,name=[[Ishamuhale]],name_loc=[[Ishamuhale]],level=19,minLevel=10,giver=[[Jorn Skyseer]],giver_loc=[[Jorn Vidente del Cielo]],giverType=[[NPC]],giverId=3387,ender=[[Jorn Skyseer]],ender_loc=[[Jorn Vidente del Cielo]],enderType=[[NPC]],enderId=3387,prevId=3261,rewardNextId=907,poiX=-435,poiY=-3428,wowhead=[[https://www.wowhead.com/wotlk/quest=882]],image=[[assets/images/quests/placeholder.png]],desc=[[Ishamuhale, Speartooth, is the fiercest sunscale raptor of the Barrens.  He does not hunt for sport, nor for food.  He hunts because hunting is his passion.  He kills because it is his nature to kill. And you will learn of his nature, $N, for your path now follows the taloned tracks of Ishamuhale. Begin the hunt.  Slay his favorite prey, a zhevra, then bring its carcass to the dead tree northwest of Ratchet.  Ishamuhale will smell the carcass and be drawn to it. Be ready when he comes.]],logDesc=[[Bring Ishamuhale's Fang to Jorn at Camp Taurajo.]]}
DB[883]={id=883,zoneId=17,name=[[Lakota'mani]],name_loc=[[Lakota'mani]],level=22,minLevel=10,giverType=[[NPC]],ender=[[Jorn Skyseer]],ender_loc=[[Jorn Vidente del Cielo]],enderType=[[NPC]],enderId=3387,poiX=-1717,poiY=-2052,wowhead=[[https://www.wowhead.com/wotlk/quest=883]],image=[[assets/images/quests/placeholder.png]],desc=[[The Hoof of Lakota'mani is a symbol of the strength of the great kodo.]],logDesc=[[Bring the Hoof of Lakota'mani to Jorn at Camp Taurajo.]]}
DB[884]={id=884,zoneId=17,name=[[Owatanka]],name_loc=[[Owatanka]],level=24,minLevel=10,giverType=[[NPC]],ender=[[Jorn Skyseer]],ender_loc=[[Jorn Vidente del Cielo]],enderType=[[NPC]],enderId=3387,poiX=-2515,poiY=-2384,wowhead=[[https://www.wowhead.com/wotlk/quest=884]],image=[[assets/images/quests/placeholder.png]],desc=[[When touched, sparks fly from the tailspike of Owatanka.]],logDesc=[[Bring Owatanka's Tailspike to Jorn at Camp Taurajo.]]}
DB[885]={id=885,zoneId=17,name=[[Washte Pawne]],name_loc=[[Washte Pawne]],level=25,minLevel=10,giverType=[[NPC]],ender=[[Jorn Skyseer]],ender_loc=[[Jorn Vidente del Cielo]],enderType=[[NPC]],enderId=3387,poiX=-3450,poiY=-1918,wowhead=[[https://www.wowhead.com/wotlk/quest=885]],image=[[assets/images/quests/placeholder.png]],desc=[[The feather of Washte Pawne is painful to the touch.]],logDesc=[[Bring Washte Pawne's Feather to Jorn Skyseer at Camp Taurajo.]]}
DB[886]={id=886,zoneId=17,name=[[The Barrens Oases]],name_loc=[[El oasis de Los Baldíos]],level=10,minLevel=10,giver=[[Arch Druid Hamuul Runetotem]],giver_loc=[[Archidruida Hamuul Tótem de Runa]],giverType=[[NPC]],giverId=5769,ender=[[Tonga Runetotem]],ender_loc=[[Tonga Tótem de Runa]],enderType=[[NPC]],enderId=3448,rewardNextId=870,poiX=-545,poiY=-2673,wowhead=[[https://www.wowhead.com/wotlk/quest=886]],image=[[assets/images/quests/placeholder.png]],desc=[[The druids of Thunder Bluff sense a strange power leaking into the Barrens, east of Mulgore. Tonga Runetotem was sent to discover the source of this power, but we fear he will need aid. Travel to the Barrens and speak with Tonga.  He will be at the Crossroads.  To reach there, take the road east out of Bloodhoof village.  Enter the Barrens, then turn north when the road forks.  Continue north and  you will find the Crossroads. And do not leave the road, $N, for the Barrens is a harsh land.]],logDesc=[[Speak with Tonga Runetotem at the Crossroads in the Barrens.]]}
DB[887]={id=887,zoneId=17,name=[[Southsea Freebooters]],name_loc=[[Los filibusteros de los Mares del Sur]],level=14,minLevel=9,giver=[[Gazlowe]],giverType=[[NPC]],giverId=3391,ender=[[Gazlowe]],enderType=[[NPC]],enderId=3391,rewardNextId=890,poiX=-1540,poiY=-3910,wowhead=[[https://www.wowhead.com/wotlk/quest=887]],image=[[assets/images/quests/placeholder.png]],desc=[[I sure wish Vice Admiral Grezzlik did a better job of keeping the seas safe for our trading vessels. With all the gold the trade princes have poured into the Trade Fleets, it ticks me off to see so many pirates running willy-nilly, raiding my ships and stealing my goods! I heard that the Southsea Freebooters have set up a camp just south of here. They've been a real thorn in my side and if Grezzlik won't take care of them, well, maybe you can help me get rid of them.]],logDesc=[[Kill 12 Southsea Brigands and 6 Southsea Cannoneers for Gazlowe in Ratchet.]]}
DB[888]={id=888,zoneId=17,name=[[Stolen Booty]],name_loc=[[El botín robado]],level=16,minLevel=9,giver=[[Gazlowe]],giverType=[[NPC]],giverId=3391,ender=[[Gazlowe]],enderType=[[NPC]],enderId=3391,prevId=892,poiX=-1740,poiY=-3724,wowhead=[[https://www.wowhead.com/wotlk/quest=888]],image=[[assets/images/quests/placeholder.png]],desc=[[While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have! As you see, my observatory is ready to go, but it needs the smaller of the two lenses. The first arrived by caravan from Durotar, but the second was bound by ship, and never arrived. Also, I never got my boot shipment from Drizzlik in Booty Bay! Head down to the pirate camp and see if you can find them.]],logDesc=[[Retrieve the Shipment of Boots and Telescopic Lens for Gazlowe in Ratchet.]],choiceRewards={{id=5337,qty=1},{id=5320,qty=1}}}
DB[889]={id=889,zoneId=17,name=[[Spirit of the Wind]],name_loc=[[El espíritu del viento]],level=20,minLevel=14,giver=[[Mangletooth]],giver_loc=[[Quebrantadientes]],giverType=[[NPC]],giverId=3430,ender=[[Mangletooth]],ender_loc=[[Quebrantadientes]],enderType=[[NPC]],enderId=3430,prevId=5052,poiX=-2034,poiY=-2821,wowhead=[[https://www.wowhead.com/wotlk/quest=889]],image=[[assets/images/quests/placeholder.png]]}
DB[890]={id=890,zoneId=17,name=[[The Missing Shipment]],name_loc=[[El envío perdido]],level=14,minLevel=9,giver=[[Gazlowe]],giverType=[[NPC]],giverId=3391,ender=[[Wharfmaster Dizzywig]],ender_loc=[[Maestro de muelles Vertipeluca]],enderType=[[NPC]],enderId=3453,prevId=887,rewardNextId=892,poiX=-986,poiY=-3797,wowhead=[[https://www.wowhead.com/wotlk/quest=890]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been waiting forever for my last shipment of goods from Booty Bay! I'm pretty sure that it must have been stolen by the Freebooters, but just to make sure, will you go down to the dockside and ask Dizzywig if my goods were already put into my warehouse without my knowledge? Here, take my ledger down to Dizzywig and have him double check my inventory records against his logs.]],logDesc=[[Bring Gazlowe's Ledger to Wharfmaster Dizzywig.]]}
DB[891]={id=891,zoneId=17,name=[[The Guns of Northwatch]],name_loc=[[Las armas del Fuerte del Norte]],level=20,minLevel=13,giver=[[Captain Thalo'thas Brightsun]],giver_loc=[[Capitán Thalo'thas Solbrillante]],giverType=[[NPC]],giverId=3339,ender=[[Captain Thalo'thas Brightsun]],ender_loc=[[Capitán Thalo'thas Solbrillante]],enderType=[[NPC]],enderId=3339,poiX=-2080,poiY=-3644,wowhead=[[https://www.wowhead.com/wotlk/quest=891]],image=[[assets/images/quests/placeholder.png]],desc=[[Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold! Those pests must be dealt with. Their paranoia has them in a state of frenzy. Trigger happy, reckless louts are shooting at anything in their sights. Travel south along the Merchant Coast to the Hold and lay siege to their forces. Bring me the medals of their soldiers as proof. And for the love of my fleet, slay Captain Fairmount and her overzealous cannoneers!]],logDesc=[[Captain Thalo'thas Brightsun of Ratchet wants you to collect 10 Theramore Medals and slay Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe.]],choiceRewards={{id=5309,qty=1},{id=5310,qty=1}}}
DB[892]={id=892,zoneId=17,name=[[The Missing Shipment]],name_loc=[[El envío perdido]],level=14,minLevel=9,giver=[[Wharfmaster Dizzywig]],giver_loc=[[Maestro de muelles Vertipeluca]],giverType=[[NPC]],giverId=3453,ender=[[Gazlowe]],enderType=[[NPC]],enderId=3391,prevId=890,rewardNextId=888,poiX=-836,poiY=-3729,wowhead=[[https://www.wowhead.com/wotlk/quest=892]],image=[[assets/images/quests/placeholder.png]],desc=[[Everything looks square from my records, $n. Go on back and tell Gazlowe he's out of luck. I wouldn't be surprised if it was the pirates that nabbed his goodies. Nothing else I can do for him. Oh... though you could tell him that I've got some things from Undermine for him, when he has the time to come pick them up.]],logDesc=[[Return Gazlowe's Ledger to Gazlowe in Ratchet.]]}
DB[893]={id=893,zoneId=17,name=[[Weapons of Choice]],name_loc=[[Una selección de armas]],level=24,minLevel=17,giver=[[Tatternack Steelforge]],giver_loc=[[Jironack Forjacero]],giverType=[[NPC]],giverId=3433,ender=[[Tatternack Steelforge]],ender_loc=[[Jironack Forjacero]],enderType=[[NPC]],enderId=3433,poiX=-3813,poiY=-1983,wowhead=[[https://www.wowhead.com/wotlk/quest=893]],image=[[assets/images/quests/placeholder.png]],desc=[[The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons. I'd like to get my hands on a few different types to learn their techniques if possible. If you wish to help bring honor to the Horde, then bring me examples of their weapons. Find me a dagger from their stalkers, a wand from their seers, and a shield from their warfrenzy. That should do nicely!]],logDesc=[[Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.]],choiceRewards={{id=5322,qty=1},{id=5323,qty=1}}}
DB[894]={id=894,zoneId=17,name=[[Samophlange]],name_loc=[[El churumbele]],level=14,minLevel=10,giver=[[Sputtervalve]],giver_loc=[[Petardol]],giverType=[[NPC]],giverId=3442,ender=[[Control Console]],ender_loc=[[Consola de control]],enderType=[[GO]],enderId=4141,rewardNextId=900,poiX=826,poiY=-2687,wowhead=[[https://www.wowhead.com/wotlk/quest=894]],image=[[assets/images/quests/placeholder.png]],desc=[[The Venture Company set up a small research facility far to the north of here, southwest of the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a "samophlange". Now what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it. I obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.]],logDesc=[[Access the control console at the Venture Company research site.]]}
DB[895]={id=895,zoneId=17,name=[[WANTED: Baron Longshore]],name_loc=[[SE BUSCA: Capitán Garvey]],level=16,minLevel=9,giver=[[WANTED]],giver_loc=[[SE BUSCA]],giverType=[[GO]],giverId=3972,ender=[[Gazlowe]],enderType=[[NPC]],enderId=3391,poiX=-836,poiY=-3729,wowhead=[[https://www.wowhead.com/wotlk/quest=895]],image=[[assets/images/quests/placeholder.png]],desc=[[WANTED! Baron Longshore, Captain of the Heedless Captain Longshore of Gilneas leads vessels of the Southsea Freebooters, and is wanted on charges of piracy. Remains must be in identifiable condition! -- Gazlowe]],logDesc=[[Bring the head of Baron Longshore to Gazlowe in Ratchet.]]}
DB[896]={id=896,zoneId=17,name=[[Miner's Fortune]],name_loc=[[La fortuna de un minero]],level=18,minLevel=13,giver=[[Wharfmaster Dizzywig]],giver_loc=[[Maestro de muelles Vertipeluca]],giverType=[[NPC]],giverId=3453,ender=[[Wharfmaster Dizzywig]],ender_loc=[[Maestro de muelles Vertipeluca]],enderType=[[NPC]],enderId=3453,poiX=1401,poiY=-3687,wowhead=[[https://www.wowhead.com/wotlk/quest=896]],image=[[assets/images/quests/placeholder.png]],desc=[[Being Wharfmaster of a busy port like Ratchet, I keep my finger on the pulse of information. I know all about the exchange of goods and money between here and Booty Bay. The latest bit of news I've heard is about the Venture Company's Boulder Lode mine northeast of the Sludge Fen. One of the miners discovered an emerald the size of your fist. I know a few buyers who'd be interested in getting their hands on something like that, and I'd be willing to go half and half on its sale.]],logDesc=[[Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers for Wharfmaster Dizzywig at Ratchet.]],rewards={{id=5335,qty=1}}}
DB[897]={id=897,zoneId=17,name=[[The Harvester]],name_loc=[[El Cosechador]],level=24,minLevel=10,giverType=[[NPC]],ender=[[Jorn Skyseer]],ender_loc=[[Jorn Vidente del Cielo]],enderType=[[NPC]],enderId=3387,poiX=-2383,poiY=-1923,wowhead=[[https://www.wowhead.com/wotlk/quest=897]],image=[[assets/images/quests/placeholder.png]],desc=[[This strange, insect-like creature looks outside of the natural order, as though it does not belong in the Barrens.]],logDesc=[[Bring the Harvester's Head to Jorn Skyseer.]]}
DB[898]={id=898,zoneId=17,name=[[Free From the Hold]],name_loc=[[Escapar del fuerte]],level=20,minLevel=13,giver=[[Gilthares Firebough]],giver_loc=[[Gilthares Ramafuego]],giverType=[[NPC]],giverId=3465,ender=[[Captain Thalo'thas Brightsun]],ender_loc=[[Capitán Thalo'thas Solbrillante]],enderType=[[NPC]],enderId=3339,poiX=-1025,poiY=-3689,wowhead=[[https://www.wowhead.com/wotlk/quest=898]],image=[[assets/images/quests/placeholder.png]],desc=[[Finally! Someone to rescue me! I can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor. I was called an enemy and threat to the Alliance. Me! A threat to their great sham of an Alliance? I was a deckhand on a moonshine transport between Ratchet and Booty Bay. Enough talk. Help me get back to Ratchet will you? Let me know when you're ready and we'll make our break.]],logDesc=[[Safely escort Gilthares Firebough back to Captain Brightsun in Ratchet.]],choiceRewards={{id=5311,qty=1},{id=5312,qty=1}}}
DB[899]={id=899,zoneId=17,name=[[Consumed by Hatred]],name_loc=[[Consumido por el odio]],level=20,minLevel=14,giver=[[Mankrik]],giverType=[[NPC]],giverId=3432,ender=[[Mankrik]],enderType=[[NPC]],enderId=3432,poiX=-2034,poiY=-2821,wowhead=[[https://www.wowhead.com/wotlk/quest=899]],image=[[assets/images/quests/placeholder.png]],desc=[[Perhaps you know the pain of uncertainty, perhaps not, $c. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters. I've killed every pig man I've come across since, but my thirst for their blood is far from quenched. Perhaps instead of heading north to the Crossroads I should have headed to Taurajo. You, $c--you  could help me. Kill them. Kill as many as you can. Bring me their tusks, and we will celebrate their deaths together.]],logDesc=[[Bring 60 Bristleback Quilboar Tusks to Mankrik at the Crossroads.]],choiceRewards={{id=5314,qty=1},{id=6477,qty=1}}}
DB[900]={id=900,zoneId=17,name=[[Samophlange]],name_loc=[[El churumbele]],level=14,minLevel=10,giver=[[Control Console]],giver_loc=[[Consola de control]],giverType=[[GO]],giverId=4141,ender=[[Control Console]],ender_loc=[[Consola de control]],enderType=[[GO]],enderId=4141,prevId=894,rewardNextId=901,poiX=831,poiY=-2680,wowhead=[[https://www.wowhead.com/wotlk/quest=900]],image=[[assets/images/quests/placeholder.png]],desc=[[The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.]],logDesc=[[Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again.]]}
DB[901]={id=901,zoneId=17,name=[[Samophlange]],name_loc=[[El churumbele]],level=14,minLevel=10,giver=[[Control Console]],giver_loc=[[Consola de control]],giverType=[[GO]],giverId=4141,ender=[[Control Console]],ender_loc=[[Consola de control]],enderType=[[GO]],enderId=4141,prevId=900,rewardNextId=902,poiX=910,poiY=-2732,wowhead=[[https://www.wowhead.com/wotlk/quest=901]],image=[[assets/images/quests/placeholder.png]],desc=[[With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.]],logDesc=[[Get the Console Key from Tinkerer Sniggles to use on the control console.]]}
DB[902]={id=902,zoneId=17,name=[[Samophlange]],name_loc=[[El churumbele]],level=16,minLevel=10,giver=[[Control Console]],giver_loc=[[Consola de control]],giverType=[[GO]],giverId=4141,ender=[[Sputtervalve]],ender_loc=[[Petardol]],enderType=[[NPC]],enderId=3442,prevId=901,poiX=-902,poiY=-3759,wowhead=[[https://www.wowhead.com/wotlk/quest=902]],image=[[assets/images/quests/placeholder.png]],desc=[[Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange. A tug removes it from its housing.]],logDesc=[[Return the Samophlange to Sputtervalve in Ratchet.]],choiceRewards={{id=5324,qty=1},{id=5325,qty=1}}}
DB[903]={id=903,zoneId=17,name=[[Prowlers of the Barrens]],name_loc=[[Merodeadores de los Baldíos]],level=15,minLevel=10,giver=[[Sergra Darkthorn]],giver_loc=[[Sergra Espinoscura]],giverType=[[NPC]],giverId=3338,ender=[[Sergra Darkthorn]],ender_loc=[[Sergra Espinoscura]],enderType=[[NPC]],enderId=3338,prevId=845,rewardNextId=881,poiX=-739,poiY=-3444,wowhead=[[https://www.wowhead.com/wotlk/quest=903]],image=[[assets/images/quests/placeholder.png]],desc=[[Now it's time to go after something that really bites.  The prowlers of the Barrens are a tough breed.  Tough, resourceful, sly... and deadly.  You'll find them among the tall grasses.  You'll find many to the southwest of the Crossroads. Be wary as you hunt them, $n, or you may find yourself no longer the predator, but instead the prey.]],logDesc=[[Collect 7 Prowler Claws from Savannah Prowlers for Sergra Darkthorn in the Crossroads.]]}
DB[905]={id=905,zoneId=17,name=[[The Angry Scytheclaws]],name_loc=[[La ira de los segadores]],level=17,minLevel=10,giver=[[Sergra Darkthorn]],giver_loc=[[Sergra Espinoscura]],giverType=[[NPC]],giverId=3338,ender=[[Sergra Darkthorn]],ender_loc=[[Sergra Espinoscura]],enderType=[[NPC]],enderId=3338,prevId=881,rewardNextId=3261,poiX=-1502,poiY=-2707,wowhead=[[https://www.wowhead.com/wotlk/quest=905]],image=[[assets/images/quests/placeholder.png]],desc=[[Now, $N, the hunt deepens.  Now you must defeat your prey, and then find your way to its lair. Hunt the sunscale raptors to the south.  Slay them and remove the feathers they wear.  Place the feathers on the scytheclaw nests southwest of the Stagnant Oasis. Show their brethren you do not fear them!]],logDesc=[[Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Scytheclaw nests. Return to Sergra Darkthorn in the Crossroads.]]}
DB[906]={id=906,zoneId=17,name=[[Betrayal from Within]],name_loc=[[Traidores]],level=25,minLevel=17,giver=[[Mangletooth]],giver_loc=[[Quebrantadientes]],giverType=[[NPC]],giverId=3430,ender=[[Thork]],enderType=[[NPC]],enderId=3429,prevId=879,poiX=-3831,poiY=-1445,wowhead=[[https://www.wowhead.com/wotlk/quest=906]],image=[[assets/images/quests/placeholder.png]],desc=[[Take Lok's head to Thork in the Crossroads, $r. <snort> He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in <snort> such things. But I am sure he'll reward you for carrying out such a great deed. <snort> I will continue to bless you with Agamaggan's power for as long as I remain in this cage, $r. Until then, farewell.]],logDesc=[[Bring Lok's Skull to Thork at the Crossroads in the Barrens.]],choiceRewards={{id=5316,qty=1},{id=5317,qty=1}}}
DB[907]={id=907,zoneId=17,name=[[Enraged Thunder Lizards]],name_loc=[[Los truenagartos iracundos]],level=18,minLevel=10,giver=[[Jorn Skyseer]],giver_loc=[[Jorn Vidente del Cielo]],giverType=[[NPC]],giverId=3387,ender=[[Jorn Skyseer]],ender_loc=[[Jorn Vidente del Cielo]],enderType=[[NPC]],enderId=3387,prevId=882,rewardNextId=913,poiX=-2249,poiY=-2751,wowhead=[[https://www.wowhead.com/wotlk/quest=907]],image=[[assets/images/quests/placeholder.png]],desc=[[Now, $N, you must face the great thunder lizards.  So large are the beasts, the ground rumbles as they stomp across the plains.  Take care as you fight them, for one false step and you may find yourself beneath their feet. You will find the thunder lizards in the southern Barrens.  They are known as Stormsnouts, Stormhides and Thunderheads.  Return to me after you have bested them.]],logDesc=[[Bring 3 Thunder Lizard Blood to Jorn Skyseer at Camp Taurajo.]]}
DB[908]={id=908,zoneId=331,name=[[Amongst the Ruins]],name_loc=[[Entre ruinas]],level=27,minLevel=25,giverType=[[NPC]],enderType=[[NPC]],prevId=6563,poiX=3355,poiY=1033,wowhead=[[https://www.wowhead.com/wotlk/quest=908]],image=[[assets/images/quests/placeholder.png]],desc=[[The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good. $N, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!]],logDesc=[[Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.]]}
DB[909]={id=909,zoneId=331,name=[[Baron Aquanis]],name_loc=[[Barón Aquanis]],level=30,minLevel=25,giverType=[[NPC]],enderType=[[NPC]],poiX=3355,poiY=1033,wowhead=[[https://www.wowhead.com/wotlk/quest=909]],image=[[assets/images/quests/placeholder.png]],desc=[[The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force. If anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.]],logDesc=[[Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.]],choiceRewards={{id=16886,qty=1},{id=16887,qty=1}}}
DB[910]={id=910,name=[[Down at the Docks]],name_loc=[[Un paseo por los embarcaderos]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Orcish Orphan]],ender_loc=[[Huérfano orco]],enderType=[[NPC]],enderId=14444,prevId=172,exGroup=-910,poiX=-998,poiY=-3822,wowhead=[[https://www.wowhead.com/wotlk/quest=910]],image=[[assets/images/quests/placeholder.png]],desc=[[I have heard tales of the mighty ships that sail between Ratchet and Booty Bay!  That would be so cool to sail on the ocean and fight in many great sea battles.  Maybe I will be a mighty Horde sailor when I grow up!  Yeah! Would you take me to see the Ratchet docks, please?  I promise I won't get into the water or cause any trouble - I just want to see the big boats and smell the salty sea water!  Yeah!]],logDesc=[[Take your ward to the docks of Ratchet in the Barrens.]]}
DB[911]={id=911,name=[[Gateway to the Frontier]],name_loc=[[El acceso a la frontera]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Orcish Orphan]],ender_loc=[[Huérfano orco]],enderType=[[NPC]],enderId=14444,prevId=172,exGroup=-910,poiX=1261,poiY=-2224,wowhead=[[https://www.wowhead.com/wotlk/quest=911]],image=[[assets/images/quests/placeholder.png]],desc=[[They say that Ashenvale is the new frontier, and that the Mor'shan Rampart in the Barrens is the gateway to it.  That would be so cool to be a pioneer, carving everything you need out of the untamed wilds!  They say that this is where the Horde and Alliance will clash the most in the future, and I want to be there $N! Would you take me to the Mor'shan Rampart so I can see what the frontier looks like, please?  I wanna see where the Horde is driving out those smelly night elves!]],logDesc=[[Take your ward to the Mor'shan Rampart in the northern part of the Barrens, just before entering Ashenvale.]]}
DB[912]={id=912,zoneId=38,name=[[Stonesplinter Trogg Disguise]],name_loc=[[Disfrazado de trogg Rompecantos]],level=12,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],poiX=-5833,poiY=-2603,wowhead=[[https://www.wowhead.com/wotlk/quest=912]],image=[[assets/images/quests/placeholder.png]],rewards={{id=5131,qty=1}}}
DB[913]={id=913,zoneId=17,name=[[Cry of the Thunderhawk]],name_loc=[[El chillido del halcón trueno]],level=20,minLevel=10,giver=[[Jorn Skyseer]],giver_loc=[[Jorn Vidente del Cielo]],giverType=[[NPC]],giverId=3387,ender=[[Jorn Skyseer]],ender_loc=[[Jorn Vidente del Cielo]],enderType=[[NPC]],enderId=3387,prevId=907,rewardNextId=874,poiX=-3461,poiY=-2402,wowhead=[[https://www.wowhead.com/wotlk/quest=913]],image=[[assets/images/quests/placeholder.png]],desc=[[The thunderhawk, $N, is a fierce beast.  It is time for you to face them.  You must find where it roams, and bring me its wings as proof of your successful hunt. Do this, and your time with me will near its end.]],logDesc=[[Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo.]],rewards={{id=5299,qty=1}},choiceRewards={{id=5302,qty=1},{id=5306,qty=1}}}
DB[914]={id=914,zoneId=718,name=[[Leaders of the Fang]],name_loc=[[Líderes del Colmillo]],level=22,minLevel=10,giver=[[Nara Wildmane]],giver_loc=[[Nara Ferocrín]],giverType=[[NPC]],giverId=5770,ender=[[Nara Wildmane]],ender_loc=[[Nara Ferocrín]],enderType=[[NPC]],enderId=5770,prevId=1490,poiX=-1070,poiY=-273,wowhead=[[https://www.wowhead.com/wotlk/quest=914]],image=[[assets/images/quests/placeholder.png]],desc=[[The druids in the Wailing Caverns, the Druids of the Fang, are an aberration.  They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams. The Druids of the Fang have four leaders, and each possesses a dream gem.  Even now their faces haunt me!  Defeat the leaders and bring me their gems, and the Barrens may again know peace. Go, $N.  You will find them lurking deep within the Wailing Caverns.]],logDesc=[[Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.]],choiceRewards={{id=6505,qty=1},{id=6504,qty=1}}}
DB[915]={id=915,name=[[You Scream, I Scream...]],name_loc=[[¡Quiero un heladooooo!]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Orcish Orphan]],ender_loc=[[Huérfano orco]],enderType=[[NPC]],enderId=14444,prevId=910,exGroup=-915,wowhead=[[https://www.wowhead.com/wotlk/quest=915]],image=[[assets/images/quests/placeholder.png]],desc=[[ICE CREAM!  Oh please please please could you get me some ice cream?!  Strawberry is my favorite flavor, and there's no better strawberry ice cream in the world than Tigule and Foror's Strawberry Ice Cream!  It's my favorite ice cream in the whole wide world! I had it once a long time ago when I was at the Shimmering Flats race track, but I heard that they might be selling them in town now!  Please?  Pretty please?  With Tigule and Foror's Strawberry Ice Cream on top??!?!]],logDesc=[[Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream.]]}
DB[916]={id=916,zoneId=188,name=[[Webwood Venom]],name_loc=[[El veneno de la Tejemadera]],level=4,minLevel=3,giver=[[Gilshalan Windwalker]],giver_loc=[[Gilshalan Caminaviento]],giverType=[[NPC]],giverId=2082,ender=[[Gilshalan Windwalker]],ender_loc=[[Gilshalan Caminaviento]],enderType=[[NPC]],enderId=2082,rewardNextId=917,poiX=10719,poiY=816,wowhead=[[https://www.wowhead.com/wotlk/quest=916]],image=[[assets/images/quests/placeholder.png]],desc=[[I came to Shadowglen to observe the webwood spiders that dwell in the Shadowthread Cave.  They are cousin to a much smaller variety of spider; I believe the world tree has had a profound effect on them, and I would like specimens to study to confirm this. First, I would like some of their venom.  Gather Webwood venom sacs from the spiders in and around the Shadowthread Cave, to the north.  I can then examine them for similarities with their smaller cousin's venom.]],logDesc=[[Bring 10 Webwood Venom Sacs to Gilshalan Windwalker at Aldrassil.]],choiceRewards={{id=10544,qty=1},{id=5392,qty=1},{id=5393,qty=1},{id=5586,qty=1}}}
DB[917]={id=917,zoneId=188,name=[[Webwood Egg]],name_loc=[[Huevo de Tejemadera]],level=5,minLevel=1,giver=[[Gilshalan Windwalker]],giver_loc=[[Gilshalan Caminaviento]],giverType=[[NPC]],giverId=2082,ender=[[Gilshalan Windwalker]],ender_loc=[[Gilshalan Caminaviento]],enderType=[[NPC]],enderId=2082,prevId=916,nextId=920,poiX=10932,poiY=912,wowhead=[[https://www.wowhead.com/wotlk/quest=917]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that I have the spiders' venom, I'd like some live specimens to study.  Unfortunately, capturing a living, giant spider is more than I can ask of you, young $c.  And a giant spider is more than I could handle myself! But if you can find an unhatched egg, then delivering specimens will be much easier, and I can then arrange for the unhatched spiders to be contained. There must be a nest deep in the Shadowthread Cave.  Please, search for an egg in the nest and return it to me.]],logDesc=[[Bring a Webwood Egg to Gilshalan in Aldrassil.]],choiceRewards={{id=5395,qty=1},{id=4907,qty=1},{id=11189,qty=1}}}
DB[918]={id=918,zoneId=141,name=[[Timberling Seeds]],name_loc=[[Semillas de Brezomadera]],level=7,minLevel=4,giver=[[Denalan]],giverType=[[NPC]],giverId=2080,ender=[[Denalan]],enderType=[[NPC]],enderId=2080,prevId=997,rewardNextId=922,poiX=9501,poiY=649,wowhead=[[https://www.wowhead.com/wotlk/quest=918]],image=[[assets/images/quests/placeholder.png]],desc=[[The timberlings of Teldrassil are elementals of nature.  In some ways they reflect the natural order of plants and animals on our great tree. So it is disturbing to see how angry the timberlings have become. I believe it has something to do with the soil.  I have been working on different methods of nurturing plants and would like to try them on timberling seeds.  Please, can you gather seeds from timberlings around Lake Al'Ameth and bring them to me?]],logDesc=[[Bring 8 Timberling Seeds to Denelan at Lake Al'Ameth.]],rewards={{id=4604,qty=10}}}
DB[919]={id=919,zoneId=141,name=[[Timberling Sprouts]],name_loc=[[Brotes de Brezomadera]],level=7,minLevel=4,giver=[[Denalan]],giverType=[[NPC]],giverId=2080,ender=[[Denalan]],enderType=[[NPC]],enderId=2080,poiX=9508,poiY=649,wowhead=[[https://www.wowhead.com/wotlk/quest=919]],image=[[assets/images/quests/placeholder.png]],desc=[[Small timberlings are sprouting around the waters of Lake Al'Ameth.  I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble. When you're wandering the lake, if you see any timberling sprouts please take them.  Help keep our land clean!]],logDesc=[[Bring 12 Timberling Sprouts to Denalan at Lake Al'Ameth.]],choiceRewards={{id=5606,qty=1},{id=6061,qty=1}}}
DB[920]={id=920,zoneId=188,name=[[Tenaron's Summons]],name_loc=[[Las invocaciones de Tenaron]],level=5,minLevel=1,giver=[[Gilshalan Windwalker]],giver_loc=[[Gilshalan Caminaviento]],giverType=[[NPC]],giverId=2082,ender=[[Tenaron Stormgrip]],ender_loc=[[Tenaron Tormentagarre]],enderType=[[NPC]],enderId=3514,prevId=917,rewardNextId=921,poiX=10493,poiY=807,wowhead=[[https://www.wowhead.com/wotlk/quest=920]],image=[[assets/images/quests/placeholder.png]],desc=[[$n, is it? I heard that Tenaron has been asking for you. You'll find him in the highest room atop Aldrassil. We may live long lives, but it's best you not keep him waiting too long.]],logDesc=[[Speak with Tenaron Stormgrip atop Aldrassil in Shadowglen.]]}
DB[921]={id=921,zoneId=188,name=[[Crown of the Earth]],name_loc=[[La corona de la Tierra]],level=5,minLevel=1,giver=[[Tenaron Stormgrip]],giver_loc=[[Tenaron Tormentagarre]],giverType=[[NPC]],giverId=3514,ender=[[Tenaron Stormgrip]],ender_loc=[[Tenaron Tormentagarre]],enderType=[[NPC]],enderId=3514,prevId=920,poiX=10493,poiY=807,wowhead=[[https://www.wowhead.com/wotlk/quest=921]],image=[[assets/images/quests/placeholder.png]],desc=[[It is time for you to set out to seek your destiny, $n. But before you are ready to set out into the world beyond our enchanted forests, there is much you must learn about our recent history. Much has changed with our people since the Battle of Mount Hyjal. Nordrassil lies a pale shadow of what it once was, its power used to defeat Archimonde and drive back the Burning Legion... There is a task you must perform. Go to the moonwell north of Aldrassil and return me a phial of its water.]],logDesc=[[Fill the Crystal Phial and bring it back to Tenaron Stormgrip atop Aldrassil.]]}
DB[922]={id=922,zoneId=141,name=[[Rellian Greenspyre]],name_loc=[[Rellian Verdeguja]],level=7,minLevel=4,giver=[[Denalan]],giverType=[[NPC]],giverId=2080,ender=[[Rellian Greenspyre]],ender_loc=[[Rellian Verdeguja]],enderType=[[NPC]],enderId=3517,prevId=918,rewardNextId=923,poiX=9501,poiY=649,wowhead=[[https://www.wowhead.com/wotlk/quest=922]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, can you take one of the seeds you brought me to my friend, Rellian Greenspyre?  He is a druid in Darnassus, and when last we spoke he revealed his interest in my work with the Timberlings.  He had some ideas himself, and he will appreciate a specimen seed to work with. Thank you, $N.  You have been a great help to me.  I hope that, some day, you will see the fruit of my labors. You will usually find Rellian walking the pathways of the Cenarion Enclave in Darnassus.]],logDesc=[[Bring a Timberling Seed to Rellian Greenspyre in Darnassus.]]}
DB[923]={id=923,zoneId=141,name=[[Tumors]],name_loc=[[Los tumores]],level=9,minLevel=4,giver=[[Rellian Greenspyre]],giver_loc=[[Rellian Verdeguja]],giverType=[[NPC]],giverId=3517,ender=[[Rellian Greenspyre]],ender_loc=[[Rellian Verdeguja]],enderType=[[NPC]],enderId=3517,prevId=922,nextId=2498,poiX=10930,poiY=1522,wowhead=[[https://www.wowhead.com/wotlk/quest=923]],image=[[assets/images/quests/placeholder.png]],desc=[[There is a malevolence growing in the timberlings.  We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help.  Those that wander Wellspring Lake in northern Teldrassil are the most tainted.  They must be removed! Destroy the Timberlings you find there, and gather the mossy tumors growing upon them.  Bring the tumors to me so that they may be burned.]],logDesc=[[Bring 5 Mossy Tumors to Rellian Greenspyre in Darnassus.]],rewards={{id=5605,qty=1}}}
DB[924]={id=924,zoneId=14,name=[[The Demon Seed]],name_loc=[[La Semilla del Demonio]],level=14,minLevel=9,giver=[[Ak'Zeloth]],giverType=[[NPC]],giverId=3521,ender=[[Ak'Zeloth]],enderType=[[NPC]],enderId=3521,prevId=809,poiX=324,poiY=-2239,wowhead=[[https://www.wowhead.com/wotlk/quest=924]],image=[[assets/images/quests/placeholder.png]],desc=[[The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire. I have prepared power stones that when placed near the Seed will disrupt its connection to the Legion. Take a stone from the table and bring it to the altar of fire atop Dreadmist Peak. Travel west, then north when the road forks. The Peak will be to your left. The safest climb to the top is on its northern face. And hurry--the stone's power will consume itself in time.]],logDesc=[[Grab a Flawed Power Stone.  Bring it to the Altar of Fire before the stone expires, then return to Ak'Zeloth.]],rewards={{id=5420,qty=1}}}
DB[925]={id=925,name=[[Cairne's Hoofprint]],name_loc=[[Huella de Cairne]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Orcish Orphan]],ender_loc=[[Huérfano orco]],enderType=[[NPC]],enderId=14444,prevId=910,exGroup=-915,wowhead=[[https://www.wowhead.com/wotlk/quest=925]],image=[[assets/images/quests/placeholder.png]],desc=[[They say that Cairne Bloodhoof is one of the greatest heroes the Horde has ever seen.  When I grow up, I wanna be a hero of the Horde too! Do you know Cairne, $N?  Could you do me a favor, please?  Could you get his hoofprint for me?  I dunno how to ask him, and he'd probably be too busy for someone like me... but you!  You're an adventurer just like he is!  I bet he'd give you his hoofprint easy! Please?]],logDesc=[[Travel to Thunder Bluff to see about getting Cairne Bloodhoof's hoofprint for your ward.]]}
DB[926]={id=926,zoneId=14,name=[[Flawed Power Stone]],name_loc=[[La piedra de energía con imperfecciones]],level=14,minLevel=1,giver=[[Flawed Power Stones]],giver_loc=[[Piedras de energía imperfectas]],giverType=[[GO]],giverId=5620,ender=[[Flawed Power Stones]],ender_loc=[[Piedras de energía imperfectas]],enderType=[[GO]],enderId=5620,prevId=-924,poiX=259,poiY=-3694,wowhead=[[https://www.wowhead.com/wotlk/quest=926]],image=[[assets/images/quests/placeholder.png]],rewards={{id=4986,qty=1}}}
DB[927]={id=927,zoneId=141,name=[[The Moss-twined Heart]],name_loc=[[El corazón musgoso]],level=12,minLevel=5,giverType=[[NPC]],ender=[[Denalan]],enderType=[[NPC]],enderId=2080,poiX=10832,poiY=1575,wowhead=[[https://www.wowhead.com/wotlk/quest=927]],image=[[assets/images/quests/placeholder.png]],desc=[[The heart of Blackmoss the Fetid is covered with a dark, oily moss.  In fact, the only way to tell this is a heart is from its slow, rhythmic beat... A beat that continues even now. Perhaps Denalan will want to see this heart.]],logDesc=[[Bring the Moss-twined Heart to Denalan at Lake Al'Ameth.]]}
DB[928]={id=928,zoneId=188,name=[[Crown of the Earth]],name_loc=[[La corona de la Tierra]],level=5,minLevel=1,giver=[[Tenaron Stormgrip]],giver_loc=[[Tenaron Tormentagarre]],giverType=[[NPC]],giverId=3514,ender=[[Corithras Moonrage]],ender_loc=[[Corithras Furia Lunar]],enderType=[[NPC]],enderId=3515,prevId=921,poiX=9737,poiY=956,wowhead=[[https://www.wowhead.com/wotlk/quest=928]],image=[[assets/images/quests/placeholder.png]],desc=[[While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him. Seek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west. Mind you stay on the road though, $n. There are dangerous beasts in the forests of late.]],logDesc=[[Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.]]}
DB[929]={id=929,zoneId=141,name=[[Crown of the Earth]],name_loc=[[La corona de la Tierra]],level=5,minLevel=1,giver=[[Corithras Moonrage]],giver_loc=[[Corithras Furia Lunar]],giverType=[[NPC]],giverId=3515,ender=[[Corithras Moonrage]],ender_loc=[[Corithras Furia Lunar]],enderType=[[NPC]],enderId=3515,prevId=928,rewardNextId=933,poiX=9737,poiY=956,wowhead=[[https://www.wowhead.com/wotlk/quest=929]],image=[[assets/images/quests/placeholder.png]],desc=[[First, let me tell you more of the task you must complete. The druids in Darnassus use the water of the moonwells of Teldrassil, and their moonwell must be replenished from time to time. Using these specially crafted phials, you can collect the water of the moonwells. Take this vessel to the moonwell outside of Starbreeze Village to the east, and fill it with some of its waters, then return to me. When you have completed your task, I shall continue the story where Tenaron left off...]],logDesc=[[Fill the Jade Phial and bring it back to Corithras Moonrage in Dolanaar.]]}
DB[930]={id=930,zoneId=141,name=[[The Glowing Fruit]],name_loc=[[El fruto resplandeciente]],level=10,minLevel=4,giver=[[Strange Fruited Plant]],giver_loc=[[Planta con extraños frutos]],giverType=[[GO]],giverId=6751,ender=[[Denalan]],enderType=[[NPC]],enderId=2080,poiX=9507,poiY=714,wowhead=[[https://www.wowhead.com/wotlk/quest=930]],image=[[assets/images/quests/placeholder.png]],desc=[[Hanging from beneath its fronds of this glowing plant is a large, round fruit. Denalan would want to study this fruit, you are certain.]],logDesc=[[Bring the glowing fruit to Denalan at Lake Al'Ameth.]]}
DB[931]={id=931,zoneId=141,name=[[The Shimmering Frond]],name_loc=[[Fronda fulgurante]],level=10,minLevel=4,giver=[[Strange Fronded Plant]],giver_loc=[[Planta con extrañas hojas]],giverType=[[GO]],giverId=6752,ender=[[Denalan]],enderType=[[NPC]],enderId=2080,poiX=9507,poiY=714,wowhead=[[https://www.wowhead.com/wotlk/quest=931]],image=[[assets/images/quests/placeholder.png]],desc=[[The fronds on this plant shimmer in the forest light, giving it a twisting, pulsing aura. You believe that Denalan would want a specimen of this.]],logDesc=[[Bring a Shimmering Frond to Denalan at Lake Al'Ameth]]}
DB[932]={id=932,zoneId=141,name=[[Twisted Hatred]],name_loc=[[Odio enraizado]],level=7,minLevel=4,giver=[[Tallonkai Swiftroot]],giver_loc=[[Tallonkai Cruzarraíz]],giverType=[[NPC]],giverId=3567,ender=[[Tallonkai Swiftroot]],ender_loc=[[Tallonkai Cruzarraíz]],enderType=[[NPC]],enderId=3567,poiX=10131,poiY=1191,wowhead=[[https://www.wowhead.com/wotlk/quest=932]],image=[[assets/images/quests/placeholder.png]],desc=[[I must warn you, $n, this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home. He is called Lord Melenas. He resides in the nearby cave of Fel Rock where he has gathered a large group of grell warriors. His heart is black as night, and he plots something most foul. You must find him within his nearby cave just to the north of here, and bring me his head.]],logDesc=[[Kill Lord Melenas and bring his head to Tallonkai Swiftroot in Dolanaar.]],choiceRewards={{id=5419,qty=1},{id=2571,qty=1}}}
DB[933]={id=933,zoneId=141,name=[[Crown of the Earth]],name_loc=[[La corona de la Tierra]],level=9,minLevel=1,giver=[[Corithras Moonrage]],giver_loc=[[Corithras Furia Lunar]],giverType=[[NPC]],giverId=3515,ender=[[Corithras Moonrage]],ender_loc=[[Corithras Furia Lunar]],enderType=[[NPC]],enderId=3515,prevId=929,rewardNextId=7383,poiX=9737,poiY=956,wowhead=[[https://www.wowhead.com/wotlk/quest=933]],image=[[assets/images/quests/placeholder.png]],desc=[[There is another moonwell southeast of the entrance to Darnassus, on the shores of the Pools of Arlithrien. The Sentinels are having problems patrolling the area because of attacks and the growing ill-temperedness of the Gnarlpine furbolgs. Be wary as you seek out the well, and keep your weapons close at hand.]],logDesc=[[Fill the Tourmaline Phial and bring it back to Corithras Moonrage in Dolanaar.]]}
DB[934]={id=934,zoneId=141,name=[[Crown of the Earth]],name_loc=[[Corona de la Tierra]],level=11,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],prevId=933,rewardNextId=935,poiX=9737,poiY=956,wowhead=[[https://www.wowhead.com/wotlk/quest=934]],image=[[assets/images/quests/placeholder.png]],desc=[[All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed. However, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me.]],logDesc=[[Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.]]}
DB[935]={id=935,zoneId=141,name=[[Crown of the Earth]],name_loc=[[La corona de la Tierra]],level=11,minLevel=1,giver=[[Corithras Moonrage]],giver_loc=[[Corithras Furia Lunar]],giverType=[[NPC]],giverId=3515,ender=[[Arch Druid Fandral Staghelm]],ender_loc=[[Archidruida Fandral Corzocelada]],enderType=[[NPC]],enderId=3516,prevId=7383,poiX=10175,poiY=2568,wowhead=[[https://www.wowhead.com/wotlk/quest=935]],image=[[assets/images/quests/placeholder.png]],desc=[[Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw. Strange beasts have been reported arising from the very ground of the tree, and crazed furbolgs attack passing travelers. I can only hope that the solution the Arch Druid is looking for will be found quickly. I will pour all the phials you brought into this vessel, for you to deliver to Darnassus. Bring it to Fandral Staghelm, you will find him in the druid grove.]],logDesc=[[Bring the Filled Vessel to Arch Druid Fandral Staghelm in Darnassus.]],choiceRewards={{id=5596,qty=1},{id=5595,qty=1}}}
DB[936]={id=936,zoneId=1637,name=[[Assisting Arch Druid Runetotem]],name_loc=[[Ayuda al archidruida Runatótem]],level=50,minLevel=47,giver=[[Innkeeper Gryshka]],giver_loc=[[Tabernera Gryshka]],giverType=[[NPC]],giverId=6929,ender=[[Arch Druid Hamuul Runetotem]],ender_loc=[[Archidruida Hamuul Tótem de Runa]],enderType=[[NPC]],enderId=5769,rewardNextId=3761,poiX=-1049,poiY=-304,wowhead=[[https://www.wowhead.com/wotlk/quest=936]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me $c, but I'd like just a moment of your time if possible. The Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research. Please - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.]],logDesc=[[Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.]]}
DB[937]={id=937,zoneId=141,name=[[The Enchanted Glade]],name_loc=[[El claro encantado]],level=11,minLevel=6,giver=[[Sentinel Arynia Cloudsbreak]],giver_loc=[[Centinela Arynia Quiebranubes]],giverType=[[NPC]],giverId=3519,ender=[[Sentinel Arynia Cloudsbreak]],ender_loc=[[Centinela Arynia Quiebranubes]],enderType=[[NPC]],enderId=3519,nextId=940,poiX=10386,poiY=1848,wowhead=[[https://www.wowhead.com/wotlk/quest=937]],image=[[assets/images/quests/placeholder.png]],desc=[[I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade. Little by little we are trying to push them back. When the Oracle Tree attempted to send a runner to Darnassus with a report, the messenger was attacked and killed by a group of the harpies. If you feel up to the task, go to their nests, slay them, and return their belts to me as proof of your deeds.]],logDesc=[[Acquire 6 Bloodfeather Belts and bring them to Sentinel Arynia Cloudsbreak in the Oracle Glade.]],choiceRewards={{id=5592,qty=1},{id=5591,qty=1}}}
DB[938]={id=938,zoneId=141,name=[[Mist]],name_loc=[[Niebla]],level=12,minLevel=7,giver=[[Mist]],giver_loc=[[Niebla]],giverType=[[NPC]],giverId=3568,ender=[[Sentinel Arynia Cloudsbreak]],ender_loc=[[Centinela Arynia Quiebranubes]],enderType=[[NPC]],enderId=3519,poiX=10665,poiY=1864,wowhead=[[https://www.wowhead.com/wotlk/quest=938]],image=[[assets/images/quests/placeholder.png]],desc=[[The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach. She raises her head and gazes at you, bright intelligence shining in blue eyes. She seems to wish to follow you.]],logDesc=[[Escort Mist to Sentinel Arynia Cloudsbreak at the moon well near the Oracle Tree.]],choiceRewards={{id=5590,qty=1},{id=5593,qty=1},{id=5618,qty=1}}}
DB[939]={id=939,zoneId=361,name=[[Flute of Xavaric]],name_loc=[[La Flauta de Xavaric]],level=54,minLevel=49,giverType=[[NPC]],ender=[[Eridan Bluewind]],ender_loc=[[Eridan Vientoazul]],enderType=[[NPC]],enderId=9116,rewardNextId=4441,poiX=6279,poiY=-604,wowhead=[[https://www.wowhead.com/wotlk/quest=939]],image=[[assets/images/quests/placeholder.png]],desc=[[You study the simple wooden flute you picked up after defeating Xavaric. The knotted wood feels solid, but it seems as if the spirals and patterns in the surface begin to spin and move as you turn it over in your hands. Suddenly, you feel a sense of dread... You shake your head, sure that your mind is playing tricks on you. It's possible that other satyrs carry clues as to what you have found. Bring your findings to the druid, Eridan Bluewind, that lives in southern Felwood.]],logDesc=[[Bring the Flute of Xavaric and 5 Jadefire Felbind samples to Eridan Bluewind in southern Felwood.]]}
DB[940]={id=940,zoneId=141,name=[[Teldrassil]],name_loc=[[Teldrassil]],level=11,minLevel=6,giver=[[Sentinel Arynia Cloudsbreak]],giver_loc=[[Centinela Arynia Quiebranubes]],giverType=[[NPC]],giverId=3519,ender=[[Arch Druid Fandral Staghelm]],ender_loc=[[Archidruida Fandral Corzocelada]],enderType=[[NPC]],enderId=3516,prevId=937,rewardNextId=952,poiX=10175,poiY=2568,wowhead=[[https://www.wowhead.com/wotlk/quest=940]],image=[[assets/images/quests/placeholder.png]],desc=[[The forest whispers of your feats of valor, $n. As I felt the harpies forced from their nests, a greater calm spread across the forest, its creatures once again feeling safe. I have feared sending another messenger to the Arch Druid, but I know that you will see my message safely to him. Deliver this to him and know that the forest will see you safely along its paths to the forest of stone.]],logDesc=[[Deliver the Oracle Tree's report to Arch Druid Fandral Staghelm in Darnassus.]]}
DB[941]={id=941,zoneId=141,name=[[Planting the Heart]],name_loc=[[Plantar el corazón]],level=12,minLevel=9,giver=[[Denalan]],giverType=[[NPC]],giverId=2080,ender=[[Denalan's Planter]],ender_loc=[[Maceta de Denalan]],enderType=[[GO]],enderId=7923,prevId=927,poiX=9502,poiY=721,wowhead=[[https://www.wowhead.com/wotlk/quest=941]],image=[[assets/images/quests/placeholder.png]],desc=[[I have removed that foul moss from the heart, but it remains tainted... Try placing the heart in my planter.  It is filled with a nutritive soil that may cleanse and heal the heart.]],logDesc=[[Plant the Tainted Heart in Denalan's Planter.]],rewards={{id=5218,qty=1}}}
DB[942]={id=942,zoneId=148,name=[[The Absent Minded Prospector]],name_loc=[[El prospector despistado]],level=20,minLevel=15,giver=[[Chief Archaeologist Greywhisker]],giver_loc=[[Arqueólogo Jefe Mostachogris]],giverType=[[NPC]],giverId=2912,ender=[[Archaeologist Flagongut]],ender_loc=[[Arqueólogo Gargavino]],enderType=[[NPC]],enderId=2911,prevId=741,rewardNextId=943,poiX=-3814,poiY=-838,wowhead=[[https://www.wowhead.com/wotlk/quest=942]],image=[[assets/images/quests/placeholder.png]],desc=[[This fossil bears a striking resemblance to one I once saw in Ironforge. An archaeologist by the name of Flagongut brought it to our annual Explorers' League conference. He believed the fossil had a power which could be unlocked somehow. Last I heard Flagongut had holed up in the Deepwater Tavern in Menethil Harbor, awaiting escort to the Whelgar Excavation Site. Seek him out and show him Remtravel's fossil. Perhaps he can reveal the secrets of the past. Good luck findin' your way there!]],logDesc=[[Take the mysterious fossil to Archaeologist Flagongut in Menethil Harbor.]]}
DB[943]={id=943,zoneId=148,name=[[The Absent Minded Prospector]],name_loc=[[El prospector despistado]],level=24,minLevel=15,giver=[[Archaeologist Flagongut]],giver_loc=[[Arqueólogo Gargavino]],giverType=[[NPC]],giverId=2911,ender=[[Archaeologist Flagongut]],ender_loc=[[Arqueólogo Gargavino]],enderType=[[NPC]],enderId=2911,prevId=942,poiX=-3313,poiY=-1923,wowhead=[[https://www.wowhead.com/wotlk/quest=943]],image=[[assets/images/quests/placeholder.png]],desc=[[Prospector Whelgar now holds the original fossil at his site in the Wetlands. When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil. While I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost. I don't know which one of the mottled beasts swallowed the relic but if you can retrieve it, I can unleash the power of these artifacts. Bring me both the Stone of Relu, and the original fossil he holds.]],logDesc=[[Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil.]],choiceRewards={{id=5627,qty=1},{id=5626,qty=1}}}
DB[944]={id=944,zoneId=148,name=[[The Master's Glaive]],name_loc=[[La Espada del Maestro]],level=17,minLevel=12,giver=[[Onu]],giver_loc=[[Onus]],giverType=[[NPC]],giverId=3616,ender=[[Scrying Bowl]],ender_loc=[[Cuenco de visión]],enderType=[[GO]],enderId=10076,prevId=948,rewardNextId=949,poiX=4508,poiY=313,wowhead=[[https://www.wowhead.com/wotlk/quest=944]],image=[[assets/images/quests/placeholder.png]],desc=[[It is strange that the naga are here, in Darkshore.  But stranger still...are the Twilight's Hammer.  That cult worships the old, old lords of the earth.  Lords defeated long ago. The Master's Glaive, to the south, is a place where such an old lord fell. Go there and look for more Twilight's Hammer cultists. Take this phial of scrying.  Use it to create a scrying bowl after searching the Master's Glaive.  Then speak to me through the bowl.]],logDesc=[[Gather information, then use the Phial of Scrying to create a Scrying Bowl.  Use the bowl to speak with Onu.]]}
DB[945]={id=945,zoneId=148,name=[[Therylune's Escape]],name_loc=[[La fuga de Therylune]],level=18,minLevel=10,giver=[[Therylune]],giverType=[[NPC]],giverId=3584,ender=[[Therysil]],enderType=[[NPC]],enderId=3585,poiX=4524,poiY=263,wowhead=[[https://www.wowhead.com/wotlk/quest=945]],image=[[assets/images/quests/placeholder.png]],desc=[[Help! I was wandering around the Master's Glaive, and these dirty cultists surrounded me.  Lucky I'm good at hiding!! Can you help me out of here?  And I need to send word to my sister Therysil that I'm all right.  She's in Ashenvale to the south, at the Shrine of Aessina.]],logDesc=[[Help Therylune escape, then tell Therysil at the Shrine of Aessina in Ashenvale that her sister is safe.]]}
DB[947]={id=947,zoneId=148,name=[[Cave Mushrooms]],name_loc=[[La cueva de las setas]],level=17,minLevel=12,giver=[[Barithras Moonshade]],giver_loc=[[Barithras Sombra Lunar]],giverType=[[NPC]],giverId=3583,ender=[[Barithras Moonshade]],ender_loc=[[Barithras Sombra Lunar]],enderType=[[NPC]],enderId=3583,rewardNextId=948,poiX=6858,poiY=-795,wowhead=[[https://www.wowhead.com/wotlk/quest=947]],image=[[assets/images/quests/placeholder.png]],desc=[[I am devising a potion that requires rare mushrooms, mushrooms that grow only in a certain cave.  The cave lies behind Cliffspring Falls, to the east and slightly north along the mountains. I would go there myself, but I was advised by the Grove of the Ancients to stay away from that place.  Our venerable allies sense that the cave is the hiding place for a new evil in Darkshore. Please, $N, gather the mushrooms for me.  And while doing so, scout the cave to confirm the Ancients' fears.]],logDesc=[[Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine.]],rewards={{id=5610,qty=1},{id=4605,qty=10}}}
DB[948]={id=948,zoneId=148,name=[[Onu]],name_loc=[[Onus]],level=17,minLevel=12,giver=[[Barithras Moonshade]],giver_loc=[[Barithras Sombra Lunar]],giverType=[[NPC]],giverId=3583,ender=[[Onu]],ender_loc=[[Onus]],enderType=[[NPC]],enderId=3616,prevId=947,rewardNextId=944,poiX=5002,poiY=89,wowhead=[[https://www.wowhead.com/wotlk/quest=948]],image=[[assets/images/quests/placeholder.png]],desc=[[Onu, an Ancient of Lore at the Grove of the Ancients, knows of your journey to Cliffwater Falls and wishes to speak with you.  The grove lies to the south, nestled near the mountains. The Ancients are patient and wise, $N.  But if Onu seeks your counsel concerning what you saw in the falls, then I fear it is urgent.]],logDesc=[[Speak with Onu at the Grove of the Ancients.]]}
DB[949]={id=949,zoneId=148,name=[[The Twilight Camp]],name_loc=[[El campamento del Martillo Crepuscular]],level=17,minLevel=12,giver=[[Scrying Bowl]],giver_loc=[[Cuenco de visión]],giverType=[[GO]],giverId=10076,ender=[[Twilight Tome]],enderType=[[GO]],enderId=12666,prevId=944,rewardNextId=950,poiX=4576,poiY=417,wowhead=[[https://www.wowhead.com/wotlk/quest=949]],image=[[assets/images/quests/placeholder.png]],desc=[[The Twilight's Hammer's purpose at the Master's Glaive is not known.  But it must be dark. Search through their camp at the Glaive... Search for some thing that may teach us their intentions. For we must learn their intentions before a plan is made.]],logDesc=[[Find a clue in the Twilight's Hammer camp at the Master's Glaive.]]}
DB[950]={id=950,zoneId=148,name=[[Return to Onu]],name_loc=[[Regresa junto a Onus]],level=17,minLevel=12,giver=[[Twilight Tome]],giverType=[[GO]],giverId=12666,ender=[[Onu]],ender_loc=[[Onus]],enderType=[[NPC]],enderId=3616,prevId=949,poiX=5002,poiY=89,wowhead=[[https://www.wowhead.com/wotlk/quest=950]],image=[[assets/images/quests/placeholder.png]],desc=[[Peering into the Twilight Tome is maddening.  Text begins to swim and dance after only a moment's glance, and once beautiful scrollwork twists into grotesque shapes. Tearing away one page of insane scribbles is all that is possible before a swoon overtakes you.]],logDesc=[[Bring Onu the recovered Insane Scribbles.]]}
DB[951]={id=951,zoneId=148,name=[[Mathystra Relics]],name_loc=[[Las reliquias de Mathystra]],level=20,minLevel=12,giver=[[Onu]],giver_loc=[[Onus]],giverType=[[NPC]],giverId=3616,ender=[[Onu]],ender_loc=[[Onus]],enderType=[[NPC]],enderId=3616,prevId=950,poiX=7395,poiY=-1123,wowhead=[[https://www.wowhead.com/wotlk/quest=951]],image=[[assets/images/quests/placeholder.png]],desc=[[The parchment you found at the Master's Glaive is a page from an ancient text...written by elves!  It is heavily cursed and tainted by the corruption of the Twilight's Hammer, but it seems the cult is using ancient elven magic to bring their old masters back to our world. Travel to the ruins of Mathystra to the northeast, and search for ancient relics among the grass and broken stones.  Through their study, we may divine how the Twilight's Hammer intends to exploit the magic of the elves.]],logDesc=[[Bring 6 Mathystra Relics to Onu at the Grove of the Ancients.]],choiceRewards={{id=5757,qty=1},{id=5615,qty=1}}}
DB[952]={id=952,zoneId=1657,name=[[Grove of the Ancients]],name_loc=[[El Páramo de los Ancianos]],level=11,minLevel=6,giver=[[Arch Druid Fandral Staghelm]],giver_loc=[[Archidruida Fandral Corzocelada]],giverType=[[NPC]],giverId=3516,ender=[[Onu]],ender_loc=[[Onus]],enderType=[[NPC]],enderId=3616,prevId=940,poiX=5002,poiY=89,wowhead=[[https://www.wowhead.com/wotlk/quest=952]],image=[[assets/images/quests/placeholder.png]],desc=[[If you had enough time to run messages for the Oracle Tree, then I'm sure that I can press you into service to deliver a message to the Grove of the Ancients in Darkshore, due south of Auberdine. You will most likely have to secure transport on a hippogryph, but I have faith enough in you that you can manage that. Take this to Onu, the Ancient of Lore. He has been awaiting word from me, even as I waited for news from the Oracle Glade.]],logDesc=[[Deliver Fandral's message to Onu in the Grove of the Ancients in Darkshore, south of Auberdine.]]}
DB[953]={id=953,zoneId=148,name=[[The Fall of Ameth'Aran]],name_loc=[[La caída de Ameth'Aran]],level=12,minLevel=9,giver=[[Sentinel Tysha Moonblade]],giver_loc=[[Centinela Tysha Filoluna]],giverType=[[NPC]],giverId=3639,ender=[[Sentinel Tysha Moonblade]],ender_loc=[[Centinela Tysha Filoluna]],enderType=[[NPC]],enderId=3639,poiX=5771,poiY=106,wowhead=[[https://www.wowhead.com/wotlk/quest=953]],image=[[assets/images/quests/placeholder.png]],desc=[[To the east you will find the ruins of Ameth'Aran. It is now inhabited by the restless spirits of the Highborne that once dwelt within its walls, but once it was a place where the servants of Azshara freely practiced their powerful magics. I was sent to explore the ruins and came across two large tablets, scrawled with the stories of Ameth'Aran and its fall. While I read the runes, I was accosted by the spirits, and fled. Please, if you can, venture to the ruins and decipher the tablets in my place.]],logDesc=[[Study the tablets which tell of Ameth'Aran and of its fall, then return to Sentinel Tysha Moonblade in Darkshore.]]}
DB[954]={id=954,zoneId=148,name=[[Bashal'Aran]],name_loc=[[Bashal'Aran]],level=12,minLevel=7,giver=[[Thundris Windweaver]],giver_loc=[[Thundris Tejevientos]],giverType=[[NPC]],giverId=3649,ender=[[Asterion]],enderType=[[NPC]],enderId=3650,rewardNextId=955,poiX=6749,poiY=49,wowhead=[[https://www.wowhead.com/wotlk/quest=954]],image=[[assets/images/quests/placeholder.png]],desc=[[The ruins of Bashal'Aran to the east are overrun with demonic minions. The sprites and satyrs that have taken up residence in the area feed upon the magical energies of the area, their powers growing from continued exposure. Even with that, I have noticed that there is one shrine they will not approach. On the western side of the ruins, atop a small bluff, a strange blue aura permeates... There must be an explanation to the demons' reluctance. I would like you to investigate it.]],logDesc=[[Find the source of the strange blue aura in the ruins of Bashal'Aran.]]}
DB[955]={id=955,zoneId=148,name=[[Bashal'Aran]],name_loc=[[Bashal'Aran]],level=12,minLevel=7,giver=[[Asterion]],giverType=[[NPC]],giverId=3650,ender=[[Asterion]],enderType=[[NPC]],enderId=3650,prevId=954,rewardNextId=956,poiX=6732,poiY=-220,wowhead=[[https://www.wowhead.com/wotlk/quest=955]],image=[[assets/images/quests/placeholder.png]],desc=[[If I were to relate the story of my life, I have no doubt it would surpass the limits of your patience. Let us say that mine has been a long and painful life, and this spectral form is perhaps the worst torment of all. I am held here by the means of magic. Though my words may seem disingenuous, I assure you I would be grateful beyond words if you would help me find the means of my imprisonment. A seal binds me, and by examining the earpieces of the sprites and grells, I may find a trace of it.]],logDesc=[[Acquire 8 Grell Earrings for Asterion in Bashal'Aran.]]}
DB[956]={id=956,zoneId=148,name=[[Bashal'Aran]],name_loc=[[Bashal'Aran]],level=13,minLevel=7,giver=[[Asterion]],giverType=[[NPC]],giverId=3650,ender=[[Asterion]],enderType=[[NPC]],enderId=3650,prevId=955,rewardNextId=957,poiX=6712,poiY=-200,wowhead=[[https://www.wowhead.com/wotlk/quest=956]],image=[[assets/images/quests/placeholder.png]],desc=[[If the grells have come into close contact with the seal that binds my eternal prison, I suspect I know the cause. No doubt the seal has come into the possession of the satyr that lead them. I feel strongly that this must be true, $n. One of the satyr must surely possess it. If you can obtain it, you would bring me so close to passing the bars of my prison that tears would come to my eyes.]],logDesc=[[Obtain the Ancient Moonstone Seal and bring it to Asterion in Bashal'Aran.]]}
DB[957]={id=957,zoneId=148,name=[[Bashal'Aran]],name_loc=[[Bashal'Aran]],level=13,minLevel=7,giver=[[Asterion]],giverType=[[NPC]],giverId=3650,ender=[[Asterion]],enderType=[[NPC]],enderId=3650,prevId=956,poiX=5634,poiY=166,wowhead=[[https://www.wowhead.com/wotlk/quest=957]],image=[[assets/images/quests/placeholder.png]],desc=[[It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color. In this flame this seal could be destroyed. Be wary in the ruins, $n...]],logDesc=[[Destroy the Ancient Moonstone Seal at the ancient flame in Ameth'Aran, then return to Asterion in Bashal'Aran.]],choiceRewards={{id=7229,qty=1},{id=5617,qty=1},{id=5604,qty=1}}}
DB[958]={id=958,zoneId=148,name=[[Tools of the Highborne]],name_loc=[[Las herramientas de los Altonato]],level=12,minLevel=9,giver=[[Thundris Windweaver]],giver_loc=[[Thundris Tejevientos]],giverType=[[NPC]],giverId=3649,ender=[[Thundris Windweaver]],ender_loc=[[Thundris Tejevientos]],enderType=[[NPC]],enderId=3649,poiX=5689,poiY=57,wowhead=[[https://www.wowhead.com/wotlk/quest=958]],image=[[assets/images/quests/placeholder.png]],desc=[[$C. A task I would ask of you. Have you seen the ruins of Ameth'Aran? If not, you will find them on the eastern side of the main road, some ways to the south. Once they were the home of many powerful Highborne, now they are a testament to the destruction their dabblings produced. I have been told by the Sentinels that the spirits of the Highborne persist, and that they wield their ancient magical implements. Those relics must be appropriated, so that we might destroy them.]],logDesc=[[Retrieve 7 Highborne Relics for Thundris Windweaver in Auberdine.]],rewards={{id=5612,qty=1}}}
DB[959]={id=959,zoneId=718,name=[[Trouble at the Docks]],name_loc=[[¡A por la botella!]],level=18,minLevel=14,giver=[[Crane Operator Bigglefuzz]],giver_loc=[[Operador de grúa Pelardo]],giverType=[[NPC]],giverId=3665,ender=[[Crane Operator Bigglefuzz]],ender_loc=[[Operador de grúa Pelardo]],enderType=[[NPC]],enderId=3665,poiX=-659,poiY=-2008,wowhead=[[https://www.wowhead.com/wotlk/quest=959]],image=[[assets/images/quests/placeholder.png]],desc=[[Oops! Had a little mishap, as you can see! The morning cargo shipment from Booty Bay was huge. Huge I say! Never seen so many crates. Well, I was trying to expedite things so I started unloading a bit more than I could handle. That's when everything came tumbling down. Before I knew what was going on, I saw that menace, Mad Magglish, go running off with a bottle of 99-year-old port. Chased him all the way to Wailing Caverns. No way I was going in there. Maybe you're brave enough to find him?]],logDesc=[[Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns.]]}
DB[960]={id=960,zoneId=148,name=[[Onu is meditating]],name_loc=[[Onus lo está meditando]],level=1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],prevId=-944,poiX=5002,poiY=89,wowhead=[[https://www.wowhead.com/wotlk/quest=960]],image=[[assets/images/quests/placeholder.png]],rewards={{id=5251,qty=1}}}
DB[961]={id=961,zoneId=148,name=[[Onu is meditating]],name_loc=[[Onus lo está meditando]],level=1,minLevel=1,giver=[[Onu]],giver_loc=[[Onus]],giverType=[[NPC]],giverId=3616,ender=[[Onu]],ender_loc=[[Onus]],enderType=[[NPC]],enderId=3616,prevId=-944,poiX=5002,poiY=89,wowhead=[[https://www.wowhead.com/wotlk/quest=961]],image=[[assets/images/quests/placeholder.png]],rewards={{id=5251,qty=1}}}
DB[962]={id=962,zoneId=718,name=[[Serpentbloom]],name_loc=[[Reptilia]],level=18,minLevel=14,giver=[[Apothecary Zamah]],giver_loc=[[Boticaria Zamah]],giverType=[[NPC]],giverId=3419,ender=[[Apothecary Zamah]],ender_loc=[[Boticaria Zamah]],enderType=[[NPC]],enderId=3419,poiX=-669,poiY=-2345,wowhead=[[https://www.wowhead.com/wotlk/quest=962]],image=[[assets/images/quests/placeholder.png]],desc=[[The Royal Apothecary Society, based in the great Undercity of Lordaeron, has sent me here for a very specific service, $n. Perhaps you wish to aid me, and in turn The Dark Lady in our efforts to advance the Forsaken. Recently I studied a rare specimen of flora named Serpentbloom. I believe in greater quantities this herb has great potential. Unfortunately Serpentbloom can only be found in the darkest recesses of the Wailing Caverns, a dangerous cave system located in the Barrens.]],logDesc=[[Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.]],rewards={{id=10919,qty=1}}}
DB[963]={id=963,zoneId=148,name=[[For Love Eternal]],name_loc=[[Un amor eterno]],level=16,minLevel=11,giver=[[Cerellean Whiteclaw]],giver_loc=[[Cerellean Zarpablanca]],giverType=[[NPC]],giverId=3644,ender=[[Cerellean Whiteclaw]],ender_loc=[[Cerellean Zarpablanca]],enderType=[[NPC]],enderId=3644,poiX=5760,poiY=190,wowhead=[[https://www.wowhead.com/wotlk/quest=963]],image=[[assets/images/quests/placeholder.png]],desc=[[In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya. I would never have thought, thousands of years later, that memories of Anaya would still haunt my dreams. Wandering the woods of Darkshore in a stupor, I found myself in the ruins of Ameth'Aran... where I saw the haunted spirit of my beloved. She must be freed, but I lack the heart to do it. Her spirit must be destroyed.]],logDesc=[[Free the spirit of Anaya Dawnrunner and bring her pendant back to Cerellean Whiteclaw in Auberdine.]],rewards={{id=5611,qty=1}}}
DB[964]={id=964,zoneId=28,name=[[Skeletal Fragments]],name_loc=[[Trozos esqueléticos]],level=57,minLevel=55,giver=[[Apothecary Dithers]],giver_loc=[[Boticario Dithers]],giverType=[[NPC]],giverId=11057,ender=[[Apothecary Dithers]],ender_loc=[[Boticario Dithers]],enderType=[[NPC]],enderId=11057,prevId=838,rewardNextId=5514,poiX=1792,poiY=-1273,wowhead=[[https://www.wowhead.com/wotlk/quest=964]],image=[[assets/images/quests/placeholder.png]],desc=[[The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function. First thing's first though, $N.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.]],logDesc=[[Bring 15 Skeletal Fragments to Apothecary Dithers at the Bulwark, Western Plaguelands.]]}
DB[965]={id=965,zoneId=148,name=[[The Tower of Althalaxx]],name_loc=[[La Torre de Althalaxx]],level=18,minLevel=13,giver=[[Sentinel Elissa Starbreeze]],giver_loc=[[Centinela Elissa Brisa Estelar]],giverType=[[NPC]],giverId=3657,ender=[[Balthule Shadowstrike]],ender_loc=[[Balthule Golpesombra]],enderType=[[NPC]],enderId=3661,rewardNextId=966,poiX=7247,poiY=-659,wowhead=[[https://www.wowhead.com/wotlk/quest=965]],image=[[assets/images/quests/placeholder.png]],desc=[[Hail, young $r. I am Elissa Starbreeze, and it is my charge to protect Auberdine from harm. To this end, I sent Balthule Shadowstrike to observe the strange happenings around the Tower of Althalaxx to the northeast. It is past time that he should have returned. I worry that he has encountered some unforeseen danger in the forest. I would be most appreciative if you would find him and see that he is doing well.]],logDesc=[[Find Balthule Shadowstrike near the Tower of Althalaxx in Darkshore.]]}
DB[966]={id=966,zoneId=148,name=[[The Tower of Althalaxx]],name_loc=[[La Torre de Althalaxx]],level=18,minLevel=13,giver=[[Balthule Shadowstrike]],giver_loc=[[Balthule Golpesombra]],giverType=[[NPC]],giverId=3661,ender=[[Balthule Shadowstrike]],ender_loc=[[Balthule Golpesombra]],enderType=[[NPC]],enderId=3661,prevId=965,rewardNextId=967,poiX=7215,poiY=-849,wowhead=[[https://www.wowhead.com/wotlk/quest=966]],image=[[assets/images/quests/placeholder.png]],desc=[[A group of warlocks has taken up residence around and inside the tower. I would have returned to Auberdine to report to Elissa earlier, but I was afraid that I might miss something while I was away. Delgren suspected such a company might be gathering at the tower, but did not know why. A few scraps of parchment that the warlocks carry have found their way to my hands, but I need more to complete the puzzle. I warn you not to venture into the tower, however, the warlocks there are much more powerful!]],logDesc=[[Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx.]]}
DB[967]={id=967,zoneId=148,name=[[The Tower of Althalaxx]],name_loc=[[La Torre de Althalaxx]],level=18,minLevel=13,giver=[[Balthule Shadowstrike]],giver_loc=[[Balthule Golpesombra]],giverType=[[NPC]],giverId=3661,ender=[[Delgren the Purifier]],ender_loc=[[Delgren el Purificador]],enderType=[[NPC]],enderId=3663,prevId=966,rewardNextId=970,poiX=3185,poiY=189,wowhead=[[https://www.wowhead.com/wotlk/quest=967]],image=[[assets/images/quests/placeholder.png]],desc=[[My master, Delgren the Purifier, is a paladin who has graciously offered his assistance in defending our forests from the forces of the demons and undead. He has taught me much about the Holy Light and the art of battle. Delgren must know of the cult's operations immediately. You will find him far south of here at Maestra's Post in Ashenvale Forest. Be swift, I fear the Dark Strand's threat grows with each passing hour.]],logDesc=[[Deliver Balthule's letter to Delgren the Purifier in Ashenvale Forest.]]}
DB[968]={id=968,zoneId=148,name=[[The Powers Below]],name_loc=[[Los Poderes Subyacentes]],level=20,minLevel=10,giverType=[[NPC]],ender=[[Gerrig Bonegrip]],ender_loc=[[Gerrig Agarrahueso]],enderType=[[NPC]],enderId=2786,poiX=-4599,poiY=-1115,wowhead=[[https://www.wowhead.com/wotlk/quest=968]],image=[[assets/images/quests/placeholder.png]],desc=[[Although terribly worn and scratched, the title of this book can still be read upon its cover: The Powers Below Inside the book is a listing of unpronounceable names with foreboding titles, methods of worship, and preferred sacrifices...many of which include living, humanoid creatures. On the inside cover of the book are the words: "Bonegrip's Runes and Dooms, The Forlorn Cavern, Ironforge.  Proprietor: Gerrig Bonegrip." If Bonegrip sells books like this, perhaps he'll buy this one back.]],logDesc=[[Bring the Book: The Powers Below to Gerrig Bonegrip in the Forlorn Cavern, Ironforge.]]}
DB[969]={id=969,zoneId=618,name=[[Luck Be With You]],name_loc=[[Que la suerte sea contigo]],level=60,minLevel=55,giver=[[Witch Doctor Mau'ari]],giver_loc=[[Médica bruja Mau'ari]],giverType=[[NPC]],giverId=10307,ender=[[Witch Doctor Mau'ari]],ender_loc=[[Médica bruja Mau'ari]],enderType=[[NPC]],enderId=10307,rewardNextId=975,poiX=5269,poiY=-4996,wowhead=[[https://www.wowhead.com/wotlk/quest=969]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, I can tell just by lookin' at ya -- you be wantin' to make a lucky charm. Mau'ari always knows! To da south. you'll find a canyon, an' giants made a' solid ice. The giants sometimes be carryin' dem, but ya can always gather da shards yerself from da canyon. These shards have a powerful reflective quality. Bring back 4 frostmaul shards, and my lucky charm will be yours.]],logDesc=[[Collect 4 Frostmaul Shards for Witch Doctor Mau'ari in Everlook.]]}
DB[970]={id=970,zoneId=148,name=[[The Tower of Althalaxx]],name_loc=[[La Torre de Althalaxx]],level=21,minLevel=13,giver=[[Delgren the Purifier]],giver_loc=[[Delgren el Purificador]],giverType=[[NPC]],giverId=3663,ender=[[Delgren the Purifier]],ender_loc=[[Delgren el Purificador]],enderType=[[NPC]],enderId=3663,prevId=967,poiX=3550,poiY=-179,wowhead=[[https://www.wowhead.com/wotlk/quest=970]],image=[[assets/images/quests/placeholder.png]],desc=[[Balthule's letter is dire. This Cult of the Dark Strand is a thorn in my side that must be removed. I have been dealing with some of the Dark Strand scum northeast of here at Ordil'Aran. One of their number possesses a soul gem that I believe holds the secret to the cult's power. Bring it to me, and I will be able to decipher the secrets held within.]],logDesc=[[Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post.]]}
DB[971]={id=971,zoneId=719,name=[[Knowledge in the Deeps]],name_loc=[[El conocimiento de las profundidades]],level=23,minLevel=19,giver=[[Gerrig Bonegrip]],giver_loc=[[Gerrig Agarrahueso]],giverType=[[NPC]],giverId=2786,ender=[[Gerrig Bonegrip]],ender_loc=[[Gerrig Agarrahueso]],enderType=[[NPC]],enderId=2786,poiX=-4599,poiY=-1115,wowhead=[[https://www.wowhead.com/wotlk/quest=971]],image=[[assets/images/quests/placeholder.png]],desc=[[As you might know, I collect lore.  Old lore.  Powerful lore.  Lore that opens doorways, and lore that can awaken Those Who Sleep. There are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of Blackfathom Deeps in Ashenvale.  That place is the old dwelling of long-dead elves.  Elves who held great knowledge before their city fell to ruin. Search Blackfathom Deeps for the manuscript.  Do this, and I will not forget it.  Not even after ... the end days.]],logDesc=[[Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge.]],rewards={{id=6743,qty=1}}}
DB[972]={id=972,name=[[Water Sapta]],name_loc=[[La sapta de agua]],level=-1,minLevel=20,giver=[[Islen Waterseer]],giver_loc=[[Islen Vidente del Agua]],giverType=[[NPC]],giverId=5901,ender=[[Islen Waterseer]],ender_loc=[[Islen Vidente del Agua]],enderType=[[NPC]],enderId=5901,prevId=220,poiX=-1345,poiY=-4048,wowhead=[[https://www.wowhead.com/wotlk/quest=972]],image=[[assets/images/quests/placeholder.png]],rewards={{id=6637,qty=1}}}
DB[973]={id=973,zoneId=148,name=[[The Tower of Althalaxx]],name_loc=[[La Torre de Althalaxx]],level=24,minLevel=13,giver=[[Delgren the Purifier]],giver_loc=[[Delgren el Purificador]],giverType=[[NPC]],giverId=3663,ender=[[Delgren the Purifier]],ender_loc=[[Delgren el Purificador]],enderType=[[NPC]],enderId=3663,prevId=970,rewardNextId=1140,poiX=2340,poiY=242,wowhead=[[https://www.wowhead.com/wotlk/quest=973]],image=[[assets/images/quests/placeholder.png]],desc=[[Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine,  a place of great evil in southwestern Ashenvale. He had been little more than an annoyance until now, and I had not dealt with him, but it seems that his time has come.]],logDesc=[[Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post.]],choiceRewards={{id=5622,qty=1},{id=5613,qty=1}}}
DB[974]={id=974,zoneId=490,name=[[Finding the Source]],name_loc=[[Busca la fuente]],level=55,minLevel=51,giver=[[Krakle]],giver_loc=[[Krakle]],giverType=[[NPC]],giverId=10302,ender=[[Krakle]],ender_loc=[[Krakle]],enderType=[[NPC]],enderId=10302,rewardNextId=980,poiX=-7211,poiY=-611,wowhead=[[https://www.wowhead.com/wotlk/quest=974]],image=[[assets/images/quests/placeholder.png]],desc=[[The hot springs here are a source of mystery to me. Where does the heat come from? Looking at how close the pools are to Fire Plume Ridge, I really wonder if the volcano might have something to do with it. I created a thermometer to take readings of the temperatures at the volcano, and I'd like to find the hottest part. It gives the measurements in degrees Kraklenheit! Here, take it, and take readings of the temperatures at the ridge whenever you see a hot spot!]],logDesc=[[Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge. Whenever you find a hot spot, right click the thermometer to check the temperature. Keep looking until you find the hottest one.]]}
DB[975]={id=975,zoneId=618,name=[[Cache of Mau'ari]],name_loc=[[Alijo de Mau'ari]],level=60,minLevel=55,giver=[[Witch Doctor Mau'ari]],giver_loc=[[Médica bruja Mau'ari]],giverType=[[NPC]],giverId=10307,ender=[[Witch Doctor Mau'ari]],ender_loc=[[Médica bruja Mau'ari]],enderType=[[NPC]],enderId=10307,prevId=969,poiX=6721,poiY=-4713,wowhead=[[https://www.wowhead.com/wotlk/quest=975]],image=[[assets/images/quests/placeholder.png]],desc=[[Now, before I give ya dis charm, I better explain how ta use it. If you carry da charm with ya, you'll find dat certain items will drop from creatures ya fight. If you don't have da charm with you, you won't find them. Understand? You'll know these special items by the name -- they be called E'ko. If you find any of these items, just bring dem to ol' Mau'ari, and she help ya out. Wait here while I fix your charm.]],logDesc=[[Speak to Witch Doctor Mau'ari again in a moment to receive the lucky charm.]],rewards={{id=12384,qty=1}}}
DB[976]={id=976,zoneId=331,name=[[Supplies to Auberdine]],name_loc=[[Suministros a Auberdine]],level=24,minLevel=19,giver=[[Feero Ironhand]],giver_loc=[[Feero Ferramán]],giverType=[[NPC]],giverId=4484,ender=[[Delgren the Purifier]],ender_loc=[[Delgren el Purificador]],enderType=[[NPC]],enderId=3663,prevId=973,poiX=3185,poiY=189,wowhead=[[https://www.wowhead.com/wotlk/quest=976]],image=[[assets/images/quests/placeholder.png]],desc=[[Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own. Dangerous foes operate in the forest, and I do not wish to risk letting these supplies and information fall into the wrong hands. If you and others could act as my guards, I could leave now. With your protection, I have no doubt that we can see these goods safely to Auberdine.]],logDesc=[[Speak with Delgren the Purifier at Maestra's Post after seeing Feero safely through Ashenvale Forest.]],choiceRewards={{id=5323,qty=1},{id=6721,qty=1}}}
DB[977]={id=977,zoneId=618,name=[[Are We There, Yeti?]],name_loc=[[Yeti... ¿ya hemos llegado?]],level=58,minLevel=52,giver=[[Umi Rumplesnicker]],giver_loc=[[Umi Risitas]],giverType=[[NPC]],giverId=10305,ender=[[Umi Rumplesnicker]],ender_loc=[[Umi Risitas]],enderType=[[NPC]],enderId=10305,prevId=3783,rewardNextId=5163,poiX=6662,poiY=-5405,wowhead=[[https://www.wowhead.com/wotlk/quest=977]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that I have what I need to cover the mechanical moving parts, I only need one other thing. Well, actually two. Two horns! The ice thistle patriarchs and matriarchs have the largest horns, so of course, those are the ones I want. That type of yeti inhabits a cave to the southeast. There are plenty of them there; you shouldn't have any problem finding them. Remember, I only want the best looking ones -- no beat up or broken horns, please!]],logDesc=[[Collect 2 Pristine Yeti Horns for Umi Rumplesnicker in Everlook.]]}
DB[978]={id=978,zoneId=702,name=[[Moontouched Wildkin]],name_loc=[[Lechúcico Lunadón]],level=55,minLevel=52,giver=[[Erelas Ambersky]],giver_loc=[[Erelas Cieloámbar]],giverType=[[NPC]],giverId=7916,ender=[[Erelas Ambersky]],ender_loc=[[Erelas Cieloámbar]],enderType=[[NPC]],enderId=7916,prevId=3661,rewardNextId=979,poiX=8707,poiY=989,wowhead=[[https://www.wowhead.com/wotlk/quest=978]],image=[[assets/images/quests/placeholder.png]],desc=[[Wildkin feathers from the Hinterlands appear to contain traces of magical qualities. These powers... they don't seem to be wielded by the creatures, it's more like they are simply inherent to the species -- part of their very essence. During my studies, I heard that a large population of wildkin inhabit the snowy lands of Winterspring. Could these creatures have the same powers? Please help me find an answer, $N. Go to Winterspring and gather feathers that have dropped to the ground, then return to me.]],logDesc=[[Collect 10 Moontouched Feathers from Winterspring, then return to Erelas Ambersky in Rut'theran Village.]]}
DB[979]={id=979,zoneId=702,name=[[Find Ranshalla]],name_loc=[[Encuentra a Ranshalla]],level=57,minLevel=52,giver=[[Erelas Ambersky]],giver_loc=[[Erelas Cieloámbar]],giverType=[[NPC]],giverId=7916,ender=[[Ranshalla]],enderType=[[NPC]],enderId=10300,prevId=978,poiX=5718,poiY=-4795,wowhead=[[https://www.wowhead.com/wotlk/quest=979]],image=[[assets/images/quests/placeholder.png]],desc=[[Yes, yes, these feathers seem to hold the same magical enchantment that I noticed previously... While I am not certain what we might find, I urge you to continue searching for answers, $N. A colleague of mine recently traveled into Winterspring to observe the wildkin there, in their own habitat. Why don't you catch up with her and see what she has found?]],logDesc=[[Find Ranshalla in eastern Winterspring.]]}
DB[980]={id=980,zoneId=490,name=[[The New Springs]],name_loc=[[Nuevos manantiales]],level=55,minLevel=51,giver=[[Krakle]],giver_loc=[[Krakle]],giverType=[[NPC]],giverId=10302,ender=[[Donova Snowden]],ender_loc=[[Donova Cubilnevado]],enderType=[[NPC]],enderId=9298,prevId=974,rewardNextId=4842,poiX=6396,poiY=-2537,wowhead=[[https://www.wowhead.com/wotlk/quest=980]],image=[[assets/images/quests/placeholder.png]],desc=[[Now, I've heard about other hot springs in a place called Winterspring, far to the north of here. The strange thing is, there are no volcanoes anywhere near them. Interesting, I know. Well, if you want to find out more, you should head to Winterspring and speak to a friend of mine. Her name is Donova Snowden, and she is currently staying by the hot springs there. Thanks again for helping me with my thermometer! See you later!]],logDesc=[[Travel to Winterspring and speak with Donova Snowden.]]}
DB[981]={id=981,zoneId=148,name=[[The Tower of Althalaxx]],name_loc=[[La Torre de Althalaxx]],level=31,minLevel=13,giver=[[Balthule Shadowstrike]],giver_loc=[[Balthule Golpesombra]],giverType=[[NPC]],giverId=3661,ender=[[Delgren the Purifier]],ender_loc=[[Delgren el Purificador]],enderType=[[NPC]],enderId=3663,prevId=1143,poiX=3185,poiY=189,wowhead=[[https://www.wowhead.com/wotlk/quest=981]],image=[[assets/images/quests/placeholder.png]],desc=[[For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered.]],logDesc=[[Talk to Delgren the Purifier at Maestra's Post.]],choiceRewards={{id=10043,qty=1},{id=5614,qty=1}}}
DB[982]={id=982,zoneId=148,name=[[Deep Ocean, Vast Sea]],name_loc=[[Profundo océano, mar inmenso]],level=17,minLevel=13,giver=[[Gorbold Steelhand]],giver_loc=[[Gorbold Mano de Acero]],giverType=[[NPC]],giverId=6301,ender=[[Gorbold Steelhand]],ender_loc=[[Gorbold Mano de Acero]],enderType=[[NPC]],enderId=6301,poiX=7076,poiY=437,wowhead=[[https://www.wowhead.com/wotlk/quest=982]],image=[[assets/images/quests/placeholder.png]],desc=[[Off the coast of Darkshore to our north are two wrecked ships - the Silver Dawning and the Mist Veil.  Some time ago, both ships ran afoul of the blasted murlocs as they sailed across the vast sea into Auberdine.  They now lie at the bottom of the ocean as trophies for those fiends. Both captains didn't make it out that night, and their logs and other effects are still below in lockboxes.  I'd like for you to recover them for us; it would mean a lot to the crew members still around these parts.]],logDesc=[[Recover the Silver Dawning's Lockbox and the Mist Veil's Lockbox for Gorbold Steelhand in Auberdine.  Both items should be found aboard the wreckage of the ships to the north of the village.]],choiceRewards={{id=15401,qty=1},{id=15402,qty=1}}}
DB[983]={id=983,zoneId=148,name=[[Buzzbox 827]],name_loc=[[La caja mecánica 827]],level=10,minLevel=7,giver=[[Wizbang Cranktoggle]],giver_loc=[[Maniveo Zumbang]],giverType=[[NPC]],giverId=3666,ender=[[Buzzbox 827]],ender_loc=[[Caja mecánica 827]],enderType=[[GO]],enderId=17182,rewardNextId=1001,poiX=5384,poiY=519,wowhead=[[https://www.wowhead.com/wotlk/quest=983]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey! Help me with my latest invention, the buzzbox. You can talk to people far away! Maybe you've already seen them, they're boxes with levers on them. The only problem is they need constant maintenance. Each one suffers from a different problem, but I made a really smart decision. I placed each one near creatures that have the proper parts to fix that particular machine. Right now Buzzbox 827 is on the fritz. It's just south of Auberdine, real close. It takes 6 Crawler Legs to fix it. I'll pay ya...]],logDesc=[[Collect 6 Crawler Legs and place them in Buzzbox 827.]]}
DB[984]={id=984,zoneId=148,name=[[How Big a Threat?]],name_loc=[[La extensión de la amenaza]],level=14,minLevel=10,giver=[[Terenthis]],giverType=[[NPC]],giverId=3693,ender=[[Terenthis]],enderType=[[NPC]],enderId=3693,rewardNextId=985,poiX=5980,poiY=263,wowhead=[[https://www.wowhead.com/wotlk/quest=984]],image=[[assets/images/quests/placeholder.png]],desc=[[Some of my brethren were rescued from a corrupt furbolg in Teldrassil, and I've vowed to stop any more atrocities before more of our kind are injured... or worse. I have seen a couple hints of corruption in Darkshore already, but I have yet to find any widespread signs. I think it would be logical if the investigation continued with the furbolgs. Would you find one of their camps, and return to me if you see any signs of corruption?]],logDesc=[[Find a corrupt furbolg camp in Darkshore and return to Terenthis in Auberdine.]]}
DB[985]={id=985,zoneId=148,name=[[How Big a Threat?]],name_loc=[[La extensión de la amenaza]],level=14,minLevel=10,giver=[[Terenthis]],giverType=[[NPC]],giverId=3693,ender=[[Terenthis]],enderType=[[NPC]],enderId=3693,prevId=984,poiX=5874,poiY=307,wowhead=[[https://www.wowhead.com/wotlk/quest=985]],image=[[assets/images/quests/placeholder.png]],desc=[[You've already proven adept at scouting our enemy, $N. Do you have what it takes to fight them as well? Not all adventurers prefer straightforward combat to the art of stealth and evasion. If you think you're up for the task, then the furbolg camp south of Auberdine is currently the biggest threat to our people. You'll find some of the Blackwood tribe there. Kill 8 pathfinders and 5 windtalkers, and return to me here.]],logDesc=[[Kill 8 Blackwood Pathfinders and 5 Windtalkers and return to Terenthis in Auberdine.]]}
DB[986]={id=986,zoneId=148,name=[[A Lost Master]],name_loc=[[El maestro perdido]],level=20,minLevel=10,giver=[[Terenthis]],giverType=[[NPC]],giverId=3693,ender=[[Terenthis]],enderType=[[NPC]],enderId=3693,prevId=985,poiX=4765,poiY=-7,wowhead=[[https://www.wowhead.com/wotlk/quest=986]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, your skills have already helped me in my endeavor. Could I impose on you again to help Grimclaw and his master Volcor? In addition, I can craft you a magical cloak that will allow you to walk unhindered by Darkshore's creatures while you look for him. To create the cloak, I'll need five fine moonstalker pelts from a moonstalker sire or matriarch to have enough material. The cats can be found near Wildbend River to the south, or even farther south near Ashenvale.]],logDesc=[[Find 5 Fine Moonstalker Pelts and return them to Terenthis in Auberdine.]]}
DB[990]={id=990,zoneId=331,name=[[Trek to Ashenvale]],name_loc=[[El camino de Vallefresno]],level=19,minLevel=15,giver=[[Sentinel Selarin]],giver_loc=[[Centinela Selarin]],giverType=[[NPC]],giverId=3694,ender=[[Raene Wolfrunner]],ender_loc=[[Raene Correlobo]],enderType=[[NPC]],enderId=3691,poiX=2767,poiY=-412,wowhead=[[https://www.wowhead.com/wotlk/quest=990]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, my mistress, Raene Wolfrunner, awaits you in the city of Astranaar within Ashenvale. With your help, perhaps we can at least ease some of the corruption that's taken hold there. Head south from here and stay close to the road--you'll find your way there without issue if you follow those directions.]],logDesc=[[Find Raene Wolfrunner in Ashenvale.]]}
DB[991]={id=991,zoneId=331,name=[[Raene's Cleansing]],name_loc=[[La limpieza de Raene]],level=19,minLevel=18,giver=[[Raene Wolfrunner]],giver_loc=[[Raene Correlobo]],giverType=[[NPC]],giverId=3691,ender=[[Teronis' Corpse]],ender_loc=[[Cadáver de Teronis]],enderType=[[NPC]],enderId=3891,rewardNextId=1023,poiX=3046,poiY=529,wowhead=[[https://www.wowhead.com/wotlk/quest=991]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, a longtime friend of mine is also aiding the Sentinels here in Ashenvale, but he has yet to return. He had leads on finding an item that he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard. Before he left here, he mentioned seeking out a gem for the rod. He mentioned the gem possibly being hidden at the shrine in Lake Falathim at the base of the mountain to the west. The gem was being held there before it was overrun. Find my friend, $N, please.]],logDesc=[[Find Teronis in Ashenvale.]]}
DB[992]={id=992,zoneId=440,name=[[Gadgetzan Water Survey]],name_loc=[[Un estudio de agua de Gadgetzan]],level=46,minLevel=38,giver=[[Senior Surveyor Fizzledowser]],giver_loc=[[Perito jefe Picoflojo]],giverType=[[NPC]],giverId=7724,ender=[[Senior Surveyor Fizzledowser]],ender_loc=[[Perito jefe Picoflojo]],enderType=[[NPC]],enderId=7724,rewardNextId=82,poiX=-7139,poiY=-3683,wowhead=[[https://www.wowhead.com/wotlk/quest=992]],image=[[assets/images/quests/placeholder.png]],desc=[[We've got a position open for a temporary junior-grade surveyor in the Gadgetzan Water Company, if you're interested! With the nomads seizing all our wells, we need to exploit more free sources of water!  There is water to be had in the desert, but only to those smart enough to survey them first. Take this dowsing widget and tap a sample of the water by the pool near Sandsorrow Watch.  It's right in sight of the trolls around there.  Bring the tapped widget back to me when you're done!]],logDesc=[[Use the untapped dowsing widget near the pool of water by Sandsorrow Watch.  Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan.]]}
DB[993]={id=993,zoneId=148,name=[[A Lost Master]],name_loc=[[El maestro perdido]],level=20,minLevel=10,giver=[[Terenthis]],giverType=[[NPC]],giverId=3693,ender=[[Volcor]],enderType=[[NPC]],enderId=3692,prevId=986,poiX=4608,poiY=-6,wowhead=[[https://www.wowhead.com/wotlk/quest=993]],image=[[assets/images/quests/placeholder.png]],desc=[[The cloak is complete, $N. The time has come to find Volcor. I can only hope we are in time. The cloak's magic, once invoked, will not last long; perhaps five minutes. It will be up to you to know when to use it: I would suggest waiting until you find Grimclaw. If what he has told me is true, you will find his master in a cave south of here. Grimclaw will be alongside the road waiting for you. Signal to him by waving when you see him, and he'll point the way towards his master.]],logDesc=[[Find Volcor in Darkshore and give him the Enchanted Moonstalker Cloak.]]}
DB[994]={id=994,zoneId=148,name=[[Escape Through Force]],name_loc=[[Escaparse por la fuerza]],level=22,minLevel=10,giver=[[Volcor]],giverType=[[NPC]],giverId=3692,ender=[[Terenthis]],enderType=[[NPC]],enderId=3693,prevId=993,exGroup=994,poiX=4774,poiY=210,wowhead=[[https://www.wowhead.com/wotlk/quest=994]],image=[[assets/images/quests/placeholder.png]],desc=[[All right, $N, force it is. Let's get out of here as soon as you're ready. We'll fight our way down to the road--Grimclaw should still be there. Once there, we can part ways. Terenthis will want to hear your version of the story immediately, so head to Auberdine after we make it out of here.]],logDesc=[[Protect Volcor until you reach the road, then speak to Terenthis in Auberdine.]],rewards={{id=5609,qty=1}}}
DB[995]={id=995,zoneId=148,name=[[Escape Through Stealth]],name_loc=[[Escaparse furtivamente]],level=20,minLevel=10,giver=[[Volcor]],giverType=[[NPC]],giverId=3692,ender=[[Terenthis]],enderType=[[NPC]],enderId=3693,prevId=993,exGroup=994,poiX=6435,poiY=363,wowhead=[[https://www.wowhead.com/wotlk/quest=995]],image=[[assets/images/quests/placeholder.png]],desc=[[All right then... if you're sure, we'll sneak out of here. Let us leave when you're ready. Remember, after you've escaped, meet Terenthis back in Auberdine. I'll head there on my own since I'll probably be moving faster than you.]],logDesc=[[Escape the Furbolg cave and meet Terenthis in Auberdine.]],rewards={{id=6659,qty=1}}}
DB[996]={id=996,zoneId=361,name=[[Corrupted Windblossom]],name_loc=[[Flor del viento corrupta]],level=55,minLevel=48,giver=[[Corrupted Windblossom]],giver_loc=[[Flor del viento corrupta]],giverType=[[GO]],giverId=164887,ender=[[Corrupted Windblossom]],ender_loc=[[Flor del viento corrupta]],enderType=[[GO]],enderId=164887,poiX=6367,poiY=-1667,wowhead=[[https://www.wowhead.com/wotlk/quest=996]],image=[[assets/images/quests/placeholder.png]]}
DB[997]={id=997,zoneId=141,name=[[Denalan's Earth]],name_loc=[[Las tierras de Denalan]],level=5,minLevel=4,giver=[[Syral Bladeleaf]],giver_loc=[[Syral Filohoja]],giverType=[[NPC]],giverId=2083,ender=[[Denalan]],enderType=[[NPC]],enderId=2080,poiX=9507,poiY=714,wowhead=[[https://www.wowhead.com/wotlk/quest=997]],image=[[assets/images/quests/placeholder.png]],desc=[[Are you heading to the south?  To Lake Al'Ameth?  If so, then I have a task I might ask of you... My colleague Denalan has a camp along the eastern end of the lake, where he is studying and experimenting on the plant life of Teldrassil.  He requested a package of rare earths from Darnassus and it was late, only recently arriving here in Dolanaar. Can you take the package to him?]],logDesc=[[Bring the package of Rare Earth to Denalan at Lake Al'Ameth.]]}
DB[998]={id=998,zoneId=361,name=[[Corrupted Windblossom]],name_loc=[[Flor del viento corrupta]],level=55,minLevel=48,giver=[[Corrupted Windblossom]],giver_loc=[[Flor del viento corrupta]],giverType=[[GO]],giverId=173327,ender=[[Corrupted Windblossom]],ender_loc=[[Flor del viento corrupta]],enderType=[[GO]],enderId=173327,poiX=6867,poiY=-1567,wowhead=[[https://www.wowhead.com/wotlk/quest=998]],image=[[assets/images/quests/placeholder.png]]}
DB[1000]={id=1000,zoneId=1638,name=[[The New Frontier]],name_loc=[[La nueva frontera]],level=55,minLevel=54,giver=[[Bluff Runner Windstrider]],giver_loc=[[Asaltaviento Correbrisa]],giverType=[[NPC]],giverId=10881,ender=[[Arch Druid Hamuul Runetotem]],ender_loc=[[Archidruida Hamuul Tótem de Runa]],enderType=[[NPC]],enderId=5769,nextId=1123,rewardNextId=1123,exGroup=1000,poiX=-1049,poiY=-304,wowhead=[[https://www.wowhead.com/wotlk/quest=1000]],image=[[assets/images/quests/placeholder.png]],desc=[[Attention, heroes! The Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead. All interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!]],logDesc=[[Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.]]}
DB[1001]={id=1001,zoneId=148,name=[[Buzzbox 411]],name_loc=[[La caja mecánica 411]],level=12,minLevel=7,giver=[[Buzzbox 827]],giver_loc=[[Caja mecánica 827]],giverType=[[GO]],giverId=17182,ender=[[Buzzbox 411]],ender_loc=[[Caja mecánica 411]],enderType=[[GO]],enderId=17183,prevId=983,rewardNextId=1002,poiX=7118,poiY=317,wowhead=[[https://www.wowhead.com/wotlk/quest=1001]],image=[[assets/images/quests/placeholder.png]],desc=[[A tiny voice crackles from deep within the machine. "Wizbang here! The next Buzzbox is north of Auberdine, on the beach So, that Buzzbox is number 411 and it needs 3 Thresher Eyes for its repairs. They're just off the coast! The darkshore threshers... *Hic*... Sorry about that... Just like last time, when you give the Buzzbox the goods, it'll spit out your reward. *Hic*... What? No, I'm fine!"]],logDesc=[[Collect 3 Thresher Eyes from Darkshore Threshers in the deep sea near Buzzbox 411.]]}
DB[1002]={id=1002,zoneId=148,name=[[Buzzbox 323]],name_loc=[[La caja mecánica 323]],level=14,minLevel=7,giver=[[Buzzbox 411]],giver_loc=[[Caja mecánica 411]],giverType=[[GO]],giverId=17183,ender=[[Buzzbox 323]],enderType=[[GO]],enderId=17184,prevId=1001,rewardNextId=1003,poiX=7260,poiY=-418,wowhead=[[https://www.wowhead.com/wotlk/quest=1002]],image=[[assets/images/quests/placeholder.png]],desc=[[The Buzzbox gives a burst of static as you hear Wizbang begin to speak. "The next Buzzbox is number 323. Ish north of Auberdine but... where's the ale? Wha? Oh, ish on the road sho ya shouldn't have trouble finding it near the bridge." Wizbang mumbles something incoherent before you hear a loud gulping sound. "Thish one needs Moonstalker Fangs... 6 of 'em."]],logDesc=[[Collect 6 Moonstalker Fangs and place them in Buzzbox 323.]]}
DB[1003]={id=1003,zoneId=148,name=[[Buzzbox 525]],name_loc=[[La caja mecánica 525]],level=16,minLevel=7,giver=[[Buzzbox 323]],giverType=[[GO]],giverId=17184,ender=[[Buzzbox 525]],ender_loc=[[Caja mecánica 525]],enderType=[[GO]],enderId=17185,prevId=1002,poiX=4765,poiY=-7,wowhead=[[https://www.wowhead.com/wotlk/quest=1003]],image=[[assets/images/quests/placeholder.png]],desc=[[Over the boiling noises and dripping sounds coming from the machine, you hear Wizbang's wavering voice call out. "Nexsht onesh far south down the road. Shouldn't be hard to find... jusht off to the shide... near a fensh. I think I hid it in shum bushesh... Bushessh. Hehehe... Yesh, Buzzbox 525 takes grizzled scalps from thoshe grizzled thistle bears. Boy thash a mouthful. Grizzshled... Hehehe..." You hear more gulping sounds as the machine cuts out. Then, suddenly, it bursts back to life. "4!"]],logDesc=[[Collect 4 Grizzled Scalps from Grizzled Thistle Bears to the south of Auberdine and place them in Buzzbox 525.]],rewards={{id=2082,qty=1},{id=11846,qty=5}}}
DB[1004]={id=1004,zoneId=1497,name=[[The New Frontier]],name_loc=[[La nueva frontera]],level=55,minLevel=54,giver=[[Harbinger Balthazad]],giver_loc=[[Presagista Balthazad]],giverType=[[NPC]],giverId=10879,ender=[[Arch Druid Hamuul Runetotem]],ender_loc=[[Archidruida Hamuul Tótem de Runa]],enderType=[[NPC]],enderId=5769,nextId=1123,rewardNextId=1123,exGroup=1000,poiX=-1049,poiY=-304,wowhead=[[https://www.wowhead.com/wotlk/quest=1004]],image=[[assets/images/quests/placeholder.png]],desc=[[Attention, heroes! The Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead. All interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!]],logDesc=[[Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.]]}
DB[1007]={id=1007,zoneId=331,name=[[The Ancient Statuette]],name_loc=[[Las antiguas estatuillas]],level=20,minLevel=19,giver=[[Talen]],giverType=[[NPC]],giverId=3846,ender=[[Talen]],enderType=[[NPC]],enderId=3846,poiX=3880,poiY=881,wowhead=[[https://www.wowhead.com/wotlk/quest=1007]],image=[[assets/images/quests/placeholder.png]],desc=[[I would charge you with a task, $N. I was on my small vessel, skimming over the submerged ruins of Zoram, when naga attacked me, surging from the water and tearing at me with their claws!  I fled, carrying what supplies I could to make this meager camp. But when I reached the shore and ran... my prized possession was lost. Please, $N, find the site of my ambush, along the coast to the north, and search for an ancient statuette.  It is the reason I have braved the dangers of the Zoram Strand.]],logDesc=[[Bring the Ancient Statuette to Talen, in his camp near the Zoram Strand.]]}
DB[1008]={id=1008,zoneId=331,name=[[The Zoram Strand]],name_loc=[[La Ensenada de Zoram]],level=19,minLevel=14,giver=[[Shindrell Swiftfire]],giver_loc=[[Shindrell Fuegoveloz]],giverType=[[NPC]],giverId=3845,ender=[[Shindrell Swiftfire]],ender_loc=[[Shindrell Fuegoveloz]],enderType=[[NPC]],enderId=3845,poiX=4118,poiY=1214,wowhead=[[https://www.wowhead.com/wotlk/quest=1008]],image=[[assets/images/quests/placeholder.png]],desc=[[There is evil lurking on our northwestern coast, known as the Zoram Strand. It is the resting place of the doomed city of Zoram, destroyed during the Sundering and submerged beneath the seas.  It has been lost to the night elves for ages.  Lost, and nearly forgotten. Now, the naga have returned, and for what reason we do not know.  But reason matters little; we must slay these fiends and throw them back to the depths! Return to me when your mission is complete.]],logDesc=[[Bring 20 Wrathtail Heads to Shindrell Swiftfire in Astranaar.]]}
DB[1009]={id=1009,zoneId=331,name=[[Ruuzel]],name_loc=[[Ruuzel]],level=25,minLevel=20,giver=[[Talen]],giverType=[[NPC]],giverId=3846,ender=[[Talen]],enderType=[[NPC]],enderId=3846,prevId=1007,poiX=4163,poiY=1324,wowhead=[[https://www.wowhead.com/wotlk/quest=1009]],image=[[assets/images/quests/placeholder.png]],desc=[[I fear the ancient statuette's secrets will remain forever hidden unless you find the key to its ancient lock. That key is a ring, the Ring of Zoram.  It belonged to the rulers of this city before the waves of the Sundering drowned it. For years the ring was lost, but the naga have recently found it. Their leader, Ruuzel, dwells on an isle on the northern edge of Zoram.  Please, $N, retrieve the ring for me!]],logDesc=[[Bring the Ring of Zoram to Talen near the Zoram Strand.]],rewards={{id=5812,qty=1}}}
DB[1010]={id=1010,zoneId=331,name=[[Bathran's Hair]],name_loc=[[Cabello de Bathran]],level=20,minLevel=20,giver=[[Orendil Broadleaf]],giver_loc=[[Orendil Hojagrande]],giverType=[[NPC]],giverId=3847,ender=[[Orendil Broadleaf]],ender_loc=[[Orendil Hojagrande]],enderType=[[NPC]],enderId=3847,poiX=3783,poiY=-178,wowhead=[[https://www.wowhead.com/wotlk/quest=1010]],image=[[assets/images/quests/placeholder.png]],desc=[[There is a plant that once grew in the old ruins of Bathran's Haunt to the north.  The plant was called Bathran's Hair and was known to cure ailments of the spirit. There is a sick child in the village, and I believe it is more than just a physical illness.  Will you go to Bathran's Haunt and search it for Bathran's Hair?  I may need it to properly treat the child. Bathran's Haunt lies north of Maestra's Post and just south of the border to Darkshore.]],logDesc=[[Bring 5 Bathran's Hair to Orendil Broadleaf in Ashenvale.]]}
DB[1011]={id=1011,zoneId=331,name=[[Forsaken Diseases]],name_loc=[[Los males de los Renegados]],level=29,minLevel=24,giver=[[Kayneth Stillwind]],giver_loc=[[Kayneth Ventoleve]],giverType=[[NPC]],giverId=3848,ender=[[Kayneth Stillwind]],ender_loc=[[Kayneth Ventoleve]],enderType=[[NPC]],enderId=3848,prevId=4581,poiX=2954,poiY=-3215,wowhead=[[https://www.wowhead.com/wotlk/quest=1011]],image=[[assets/images/quests/placeholder.png]],desc=[[The Forsaken, the undead arm of the Horde, have crept into Ashenvale, lurking at our ruins and our barrows.  We believe their goal is to spread disease amongst the lands of the night elves.  We must confirm this! The Forsaken have a camp south of here, near the Dor'Danil Barrow Den, where they create poisons and diseases and place them in bottles.  Fight your way into that camp and steal a bottle of disease.  Return with such a bottle.  I will test it and find its purpose.]],logDesc=[[Bring a Bottle of Disease to Kayneth Stillwind in Forest Song.]]}
DB[1012]={id=1012,zoneId=331,name=[[Insane Druids]],name_loc=[[Druidas dementes]],level=32,minLevel=24,giver=[[Kayneth Stillwind]],giver_loc=[[Kayneth Ventoleve]],giverType=[[NPC]],giverId=3848,ender=[[Kayneth Stillwind]],ender_loc=[[Kayneth Ventoleve]],enderType=[[NPC]],enderId=3848,prevId=1011,poiX=1829,poiY=-2751,wowhead=[[https://www.wowhead.com/wotlk/quest=1012]],image=[[assets/images/quests/placeholder.png]],desc=[[When I struggled with the Forsaken's poisons, I had a vision.  I had a vision of the druids in the Dor'danil Barrow Den, poisoned... murdered by the undead!  They are now errant ghosts, severed from their bodies and driven mad. So that the druids' spirits might some day find peace, you must enter the Dor'danil Barrow Den and destroy its once great leaders: Taneel Darkwood, Uthil Mooncall and Mavoris Cloudsbreak. Do this, then return to me.]],logDesc=[[Kill the druids: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; then return to Kayneth Stillwind in Forest Song.]],rewards={{id=5813,qty=1}}}
DB[1013]={id=1013,zoneId=209,name=[[The Book of Ur]],name_loc=[[El Libro de Ur]],level=26,minLevel=16,giver=[[Keeper Bel'dugur]],giver_loc=[[Vigilante Bel'dugur]],giverType=[[NPC]],giverId=2934,ender=[[Keeper Bel'dugur]],ender_loc=[[Vigilante Bel'dugur]],enderType=[[NPC]],enderId=2934,poiX=1529,poiY=358,wowhead=[[https://www.wowhead.com/wotlk/quest=1013]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection.  Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to ... certain parties among the Forsaken. Enter Shadowfang Keep and find the book.  Bring it to me, and I will report your service to our Dark Lady...]],logDesc=[[Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.]],choiceRewards={{id=6335,qty=1},{id=4534,qty=1}}}
DB[1014]={id=1014,zoneId=209,name=[[Arugal Must Die]],name_loc=[[Arugal debe morir]],level=27,minLevel=18,giver=[[Dalar Dawnweaver]],giver_loc=[[Dalar Tejealba]],giverType=[[NPC]],giverId=1938,ender=[[Dalar Dawnweaver]],ender_loc=[[Dalar Tejealba]],enderType=[[NPC]],enderId=1938,poiX=553,poiY=1593,wowhead=[[https://www.wowhead.com/wotlk/quest=1014]],image=[[assets/images/quests/placeholder.png]],desc=[[Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain. I shall see to it that his magic is eradicated, $n. But I leave it in your hands to see that Arugal meets the death he so deserves. Travel to Shadowfang Keep and put an end to Arugal's foul spells once and for all. Bring to me the vile wizard's head!]],logDesc=[[Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.]],rewards={{id=6414,qty=1}}}
DB[1015]={id=1015,zoneId=1519,name=[[The New Frontier]],name_loc=[[La nueva frontera]],level=55,minLevel=54,giver=[[Crier Goodman]],giver_loc=[[Pregonero Buenhombre]],giverType=[[NPC]],giverId=2198,ender=[[Arch Druid Fandral Staghelm]],ender_loc=[[Archidruida Fandral Corzocelada]],enderType=[[NPC]],enderId=3516,nextId=6761,rewardNextId=6761,exGroup=1015,poiX=10175,poiY=2568,wowhead=[[https://www.wowhead.com/wotlk/quest=1015]],image=[[assets/images/quests/placeholder.png]],desc=[[Attention, heroes! The Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead. All interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!]],logDesc=[[Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.]]}
DB[1016]={id=1016,zoneId=331,name=[[Elemental Bracers]],name_loc=[[Brazales elementales]],level=24,minLevel=20,giver=[[Sentinel Velene Starstrike]],giver_loc=[[Centinela Velene Golpe Estelar]],giverType=[[NPC]],giverId=3885,ender=[[Sentinel Velene Starstrike]],ender_loc=[[Centinela Velene Golpe Estelar]],enderType=[[NPC]],enderId=3885,rewardNextId=1017,poiX=1916,poiY=-1315,wowhead=[[https://www.wowhead.com/wotlk/quest=1016]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this divining scroll--it can determine the creator of these elementals. But you will need something from them to use as a reagent to focus scroll's magic--their bracers should do nicely. A few intact bracers from the creatures should be enough. The other bracers will be useless for our purposes, but they may be worth something to a merchant if you wish to sell them. Once you have the intact bracers attempt to use the scroll. Return to me with the results and we shall proceed from there.]],logDesc=[[Collect 5 Intact Elemental Bracers and use the Divining Scroll on them. Afterwards, bring the Divined Scroll to Sentinel Velene Starstrike at the Silverwind Refuge.]]}
DB[1017]={id=1017,zoneId=331,name=[[Mage Summoner]],name_loc=[[Mago invocador]],level=25,minLevel=20,giver=[[Sentinel Velene Starstrike]],giver_loc=[[Centinela Velene Golpe Estelar]],giverType=[[NPC]],giverId=3885,ender=[[Sentinel Velene Starstrike]],ender_loc=[[Centinela Velene Golpe Estelar]],enderType=[[NPC]],enderId=3885,prevId=1016,poiX=319,poiY=-2264,wowhead=[[https://www.wowhead.com/wotlk/quest=1017]],image=[[assets/images/quests/placeholder.png]],desc=[[There's only one undead mage in the Barrens capable of defiling this many water elementals. He's also the only one foolish enough to try. Sarilus Foulborne is probably sitting at the top of Dreadmist Peak, laughing at me. $n, you must go into enemy territory and destroy this miscreant. I have had enough of his idiocy and we must show him what happens to those who annoy the Sentinels. Destroy him and bring me his head. Be wary though, the Horde may be watching for you.]],logDesc=[[Slay Sarilus Foulborne and bring his head to Sentinel Velene Starstrike in Silverwind Refuge.]],rewards={{id=5816,qty=1}}}
DB[1018]={id=1018,zoneId=1637,name=[[The New Frontier]],name_loc=[[La nueva frontera]],level=55,minLevel=54,giver=[[Warcaller Gorlach]],giver_loc=[[Clamaguerras Gorlach]],giverType=[[NPC]],giverId=10880,ender=[[Arch Druid Hamuul Runetotem]],ender_loc=[[Archidruida Hamuul Tótem de Runa]],enderType=[[NPC]],enderId=5769,nextId=1123,rewardNextId=1123,exGroup=1000,poiX=-1049,poiY=-304,wowhead=[[https://www.wowhead.com/wotlk/quest=1018]],image=[[assets/images/quests/placeholder.png]],desc=[[Attention, heroes! The Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead. All interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!]],logDesc=[[Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.]]}
DB[1019]={id=1019,zoneId=1537,name=[[The New Frontier]],name_loc=[[La nueva frontera]],level=55,minLevel=54,giver=[[Courier Hammerfall]],giver_loc=[[Mensajero Sentencia]],giverType=[[NPC]],giverId=10877,ender=[[Arch Druid Fandral Staghelm]],ender_loc=[[Archidruida Fandral Corzocelada]],enderType=[[NPC]],enderId=3516,nextId=6761,rewardNextId=6761,exGroup=1015,poiX=10175,poiY=2568,wowhead=[[https://www.wowhead.com/wotlk/quest=1019]],image=[[assets/images/quests/placeholder.png]],desc=[[Attention, heroes! The Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead. All interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!]],logDesc=[[Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.]]}
DB[1020]={id=1020,zoneId=331,name=[[Orendil's Cure]],name_loc=[[Cura de Orendil]],level=20,minLevel=20,giver=[[Orendil Broadleaf]],giver_loc=[[Orendil Hojagrande]],giverType=[[NPC]],giverId=3847,ender=[[Pelturas Whitemoon]],ender_loc=[[Pelturas Lunablanca]],enderType=[[NPC]],enderId=3894,prevId=1010,poiX=2682,poiY=-455,wowhead=[[https://www.wowhead.com/wotlk/quest=1020]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I have created a cure that I believe will help the afflicted child.  Take it to Astranaar and give it to the child's parent, Pelturas Whitemoon. To reach Astranaar, follow the road south, then east.]],logDesc=[[Bring Orendil's Cure to Pelturas Whitemoon in Astranaar.]]}
DB[1021]={id=1021,zoneId=331,name=[[Vile Satyr! Dryads in Danger!]],name_loc=[[¡Vil sátiro! ¡Dríades en peligro!]],level=32,minLevel=26,giver=[[Illiyana]],giverType=[[NPC]],giverId=3901,ender=[[Anilia]],enderType=[[NPC]],enderId=3920,rewardNextId=1031,poiX=2950,poiY=-2817,wowhead=[[https://www.wowhead.com/wotlk/quest=1021]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen, I don't know who you are, but I need your help. My sisters went to take back the Branch of Cenarius from the satyr. They said they'd be back soon, but it's been two whole days! $n, you have to find them! They were looking for the ruins of a night elf temple in Xavian to the northwest. I don't know what to think. Look for Anilia, she was leading them on the search.]],logDesc=[[Find Anilia in Xavian in Ashenvale.]]}
DB[1022]={id=1022,zoneId=331,name=[[The Howling Vale]],name_loc=[[La Vega del Aullido]],level=30,minLevel=25,giver=[[Sentinel Melyria Frostshadow]],giver_loc=[[Centinela Melyria Sombrigélida]],giverType=[[NPC]],giverId=3880,ender=[[Sentinel Melyria Frostshadow]],ender_loc=[[Centinela Melyria Sombrigélida]],enderType=[[NPC]],enderId=3880,rewardNextId=1037,poiX=3169,poiY=-1212,wowhead=[[https://www.wowhead.com/wotlk/quest=1022]],image=[[assets/images/quests/placeholder.png]],desc=[[Though we have put many resources and much effort into driving the remaining demons from the Felwood to the north, our successes have been few. We have been able to keep much of the demonic presence from Ashenvale. To the north, near the Felwood border, the ruined shrine of Mel'Thandris has been overtaken by mysterious wolf-men. Their chilling calls have led the area to be known as the Howling Vale. The Tome of Mel'Thandris kept at the shrine may shed some light on why these wolf-men have come.]],logDesc=[[Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at Forest Song.]]}
DB[1023]={id=1023,zoneId=331,name=[[Raene's Cleansing]],name_loc=[[La limpieza de Raene]],level=21,minLevel=18,giver=[[Teronis' Corpse]],giver_loc=[[Cadáver de Teronis]],giverType=[[NPC]],giverId=3891,ender=[[Raene Wolfrunner]],ender_loc=[[Raene Correlobo]],enderType=[[NPC]],enderId=3691,prevId=991,poiX=3049,poiY=450,wowhead=[[https://www.wowhead.com/wotlk/quest=1023]],image=[[assets/images/quests/placeholder.png]],desc=[[As you rummage through Teronis' belongings, you find a journal that is still in good condition. You take the journal and leave Teronis' corpse as is. The only thing left to do is find the gem Teronis was seeking. Raene mentioned it being in the area. Perhaps the murlocs have it...]],logDesc=[[Find the Glowing Gem and return to Raene Wolfrunner in Astranaar with Teronis' Journal.]]}
DB[1024]={id=1024,zoneId=331,name=[[Raene's Cleansing]],name_loc=[[La limpieza de Raene]],level=21,minLevel=18,giver=[[Raene Wolfrunner]],giver_loc=[[Raene Correlobo]],giverType=[[NPC]],giverId=3691,ender=[[Shael'dryn]],enderType=[[NPC]],enderId=3916,prevId=1023,rewardNextId=1026,poiX=2894,poiY=-1386,wowhead=[[https://www.wowhead.com/wotlk/quest=1024]],image=[[assets/images/quests/placeholder.png]],desc=[[You'll have to do the research yourself, but from what notes Teronis has made, it sounds like your next course of action is to find the other pieces of the rod Dartol created. I would start by heading to the moonwell east of Iris Lake. When you're ready, follow the road and turn north when you reach a small sitting area on your left. A dryad there named Shael'dryn is better suited to guide you. Seek her out. Keep the gem with you--Shael'dryn will need it if she's to help you recreate the rod.]],logDesc=[[Find Shael'dryn at the moonwell to the northeast.]]}
DB[1025]={id=1025,zoneId=331,name=[[An Aggressive Defense]],name_loc=[[Una defensa agresiva]],level=24,minLevel=18,giver=[[Raene Wolfrunner]],giver_loc=[[Raene Correlobo]],giverType=[[NPC]],giverId=3691,ender=[[Raene Wolfrunner]],ender_loc=[[Raene Correlobo]],enderType=[[NPC]],enderId=3691,prevId=1023,poiX=2260,poiY=-1244,wowhead=[[https://www.wowhead.com/wotlk/quest=1025]],image=[[assets/images/quests/placeholder.png]],desc=[[Before you travel to the moonwell I have another task that will aid the people of Ashenvale if you would like to test your skills. Along the road heading east before the Falfarren River, furbolgs have been attacking travelers. Their tortured minds feeding upon fear, and their appetites satiated by the blood of innocents. Aid the Sentinels in protecting the lands by showing those monsters the same mercy they have shown our kind. I believe their camps are south of the road... be careful.]],logDesc=[[Kill 1 Den Watcher, 2 Ursas, 10 Totemics, and 12 Warriors of the Foulweald tribe, and then return to Raene Wolfrunner in Astranaar.]],rewards={{id=4542,qty=10},{id=1205,qty=10}}}
DB[1026]={id=1026,zoneId=331,name=[[Raene's Cleansing]],name_loc=[[La limpieza de Raene]],level=27,minLevel=18,giver=[[Shael'dryn]],giverType=[[NPC]],giverId=3916,ender=[[Shael'dryn]],enderType=[[NPC]],enderId=3916,prevId=1024,rewardNextId=1027,poiX=3312,poiY=-1438,wowhead=[[https://www.wowhead.com/wotlk/quest=1026]],image=[[assets/images/quests/placeholder.png]],desc=[[I wish your tidings were better. Raene is correct, I know about Dartol's creation and the treants in the area--at least I did once. They've become corrupted now, their nature twisted. If your goal is to find the next piece of the rod, then you'll have to find the key to open the chest it's in. The wooden key is on one of the treants northeast of here, near Felwood. Once you have it, look for a small glade west of the road near the Felwood border... the chest should be hidden around there.]],logDesc=[[Find the Wooden Key and a piece of Dartol's Rod before returning to Shael'dryn at the moonwell.]]}
DB[1027]={id=1027,zoneId=331,name=[[Raene's Cleansing]],name_loc=[[La limpieza de Raene]],level=28,minLevel=18,giver=[[Shael'dryn]],giverType=[[NPC]],giverId=3916,ender=[[Shael'dryn]],enderType=[[NPC]],enderId=3916,prevId=1026,rewardNextId=1028,poiX=2894,poiY=-1386,wowhead=[[https://www.wowhead.com/wotlk/quest=1027]],image=[[assets/images/quests/placeholder.png]],desc=[[The final piece of the rod was given to the druids of Dor'danil for safekeeping. I have no idea where they hid it. I'm sorry I can't help you more than that. All I can tell you is to follow the road that leads towards the Barrens. The druids took shelter to the east of that road, but they won't be of much help to you: they were killed recently... it's something I don't like to think about much. When you find the final piece, bring it to me and I will help you reconstruct the rod.]],logDesc=[[Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell.]]}
DB[1028]={id=1028,zoneId=331,name=[[Raene's Cleansing]],name_loc=[[La limpieza de Raene]],level=28,minLevel=18,giver=[[Shael'dryn]],giverType=[[NPC]],giverId=3916,ender=[[Hidden Shrine]],ender_loc=[[Santuario Oculto]],enderType=[[GO]],enderId=19024,prevId=1027,rewardNextId=1055,poiX=2782,poiY=-1550,wowhead=[[https://www.wowhead.com/wotlk/quest=1028]],image=[[assets/images/quests/placeholder.png]],desc=[[Here is the completed rod, $N. Reconstructing it was simple... it's finding the shrine that has the power to recharge it that will be the hard part. With some focus and effort it shouldn't be too hard for someone like you, who's already accomplished so much. Head southeast of here--there are very few paths, so be careful--and keep your eyes to the north. The shrine is hidden within the mountains that surround this glade. Once there, place the rod within the shrine... the rest is magic. Hehe.]],logDesc=[[Find the hidden shrine and re-enchant Dartol's Rod.]],rewards={{id=5462,qty=1}}}
DB[1029]={id=1029,zoneId=331,name=[[Raene's Cleansing]],name_loc=[[La limpieza de Raene]],level=28,minLevel=18,giver=[[Shael'dryn]],giverType=[[NPC]],giverId=3916,ender=[[Raene Wolfrunner]],ender_loc=[[Raene Correlobo]],enderType=[[NPC]],enderId=3691,prevId=1055,rewardNextId=1030,poiX=2767,poiY=-412,wowhead=[[https://www.wowhead.com/wotlk/quest=1029]],image=[[assets/images/quests/placeholder.png]],desc=[[I suggest you find Raene and let her know the rod is finished. I'm sure she'll know what your next course should be. Good luck, $N.]],logDesc=[[Return to Raene Wolfrunner in Astranaar.]]}
DB[1030]={id=1030,zoneId=331,name=[[Raene's Cleansing]],name_loc=[[La limpieza de Raene]],level=28,minLevel=18,giver=[[Raene Wolfrunner]],giver_loc=[[Raene Correlobo]],giverType=[[NPC]],giverId=3691,ender=[[Krolg]],enderType=[[NPC]],enderId=3897,prevId=1029,rewardNextId=1045,poiX=1787,poiY=-1232,wowhead=[[https://www.wowhead.com/wotlk/quest=1030]],image=[[assets/images/quests/placeholder.png]],desc=[[Alas, I'm not completely certain what he had in mind next. If what he said was true about the rod's power, then it will allow you to take on another form altogether. Which form, I do not know. Perhaps he meant to use its powers to get closer to the tainted furbolgs, but even the uncorrupted creatures would slaughter him were he not careful. Transformed by the rod, Dartol would have to speak to a furbolg who was safe from the effects of Fel Moss. I would start your search southeast of Mystral Lake.]],logDesc=[[Find an uncorrupted furbolg, and using the power of Dartol's Rod of Transformation, speak to him.]]}
DB[1031]={id=1031,zoneId=331,name=[[The Branch of Cenarius]],name_loc=[[La Rama de Cenarius]],level=32,minLevel=26,giver=[[Anilia]],giverType=[[NPC]],giverId=3920,ender=[[Illiyana]],enderType=[[NPC]],enderId=3901,prevId=1021,poiX=3042,poiY=-2798,wowhead=[[https://www.wowhead.com/wotlk/quest=1031]],image=[[assets/images/quests/placeholder.png]],desc=[[Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body. "He has taken it... Geltharis..." You know in your heart that Anilia's dying wish is to see the Branch of Cenarius back in dryad hands.]],logDesc=[[Kill Geltharis and return the Branch of Cenarius to Illiyana at Forest Song.]],choiceRewards={{id=5820,qty=1},{id=11229,qty=1}}}
DB[1032]={id=1032,zoneId=331,name=[[Satyr Slaying!]],name_loc=[[¡Muerte a los sátiros!]],level=32,minLevel=26,giver=[[Illiyana]],giverType=[[NPC]],giverId=3901,ender=[[Illiyana]],enderType=[[NPC]],enderId=3901,prevId=1031,poiX=2752,poiY=-3085,wowhead=[[https://www.wowhead.com/wotlk/quest=1032]],image=[[assets/images/quests/placeholder.png]],desc=[[I can't believe that Anilia is gone... We used to play together in the forests all the time. I almost feel... sad. I know something that might make me feel better. Please, slay the satyrs that took Anilia from me! Bring me their horns as proof of your actions and you will forever have my gratitude. ]],logDesc=[[Bring 16 Satyr Horns to Illiyana in Forest Song.]]}
DB[1033]={id=1033,zoneId=331,name=[[Elune's Tear]],name_loc=[[Lágrima de Elune]],level=22,minLevel=20,giver=[[Pelturas Whitemoon]],giver_loc=[[Pelturas Lunablanca]],giverType=[[NPC]],giverId=3894,ender=[[Pelturas Whitemoon]],ender_loc=[[Pelturas Lunablanca]],enderType=[[NPC]],enderId=3894,prevId=1020,poiX=2682,poiY=-455,wowhead=[[https://www.wowhead.com/wotlk/quest=1033]],image=[[assets/images/quests/placeholder.png]],desc=[[I had hoped Orendil's cure would save Relara, but I fear it only slowed the disease running through my child.  We must find more powerful medicine!  Thankfully, Orendil spoke to me of further remedies to try should his first one fail. Elune's Tear is a type of stone that rests in only one place: the isle on Iris Lake, east of Astranaar.  Orendil said the stone will wash away corruption... please, $N, bring me Elune's Tear and pray it will end my child's sickness!]],logDesc=[[Bring Elune's Tear to Pelturas in Astranaar.]]}
DB[1034]={id=1034,zoneId=331,name=[[The Ruins of Stardust]],name_loc=[[Las Ruinas del Polvo Estelar]],level=23,minLevel=20,giver=[[Pelturas Whitemoon]],giver_loc=[[Pelturas Lunablanca]],giverType=[[NPC]],giverId=3894,ender=[[Pelturas Whitemoon]],ender_loc=[[Pelturas Lunablanca]],enderType=[[NPC]],enderId=3894,prevId=1033,poiX=2094,poiY=-268,wowhead=[[https://www.wowhead.com/wotlk/quest=1034]],image=[[assets/images/quests/placeholder.png]],desc=[[Elune's Tear washed clear some of my daughter's sickness.  Her nightmares are lessened and I thank the goddess for her blessing.  But ... fever still rages within her. Orendil told me of a frosted dust found among the Ruins of Stardust.  Perhaps it will abate Relara's fever.  Gather some of the dust, then please return to me. The Ruins of Stardust lie to the south, $N.  May Elune speed your journey.]],logDesc=[[Bring 5 Handfuls of Stardust to Pelturas in Astranaar.]]}
DB[1035]={id=1035,zoneId=331,name=[[Fallen Sky Lake]],name_loc=[[Lago Cielo Estrellado]],level=30,minLevel=20,giver=[[Pelturas Whitemoon]],giver_loc=[[Pelturas Lunablanca]],giverType=[[NPC]],giverId=3894,ender=[[Pelturas Whitemoon]],ender_loc=[[Pelturas Lunablanca]],enderType=[[NPC]],enderId=3894,prevId=1034,poiX=1515,poiY=-2144,wowhead=[[https://www.wowhead.com/wotlk/quest=1035]],image=[[assets/images/quests/placeholder.png]],desc=[[Relara's fever has passed, but she is still very weak.  I do not believe time alone will give her back the strength she has lost.  I believe it will take the power of a moonstone. We used to gather moonstones at Fallen Sky Lake to the southeast... until the Shadethickets came. Their leader, a Shadethicket Oracle, gathered up all the fallen moonstones and hoards them.  Now, you must retrieve a moonstone from the Oracle. And to do that, I fear that you must slay him.]],logDesc=[[Retrieve a Fallen Moonstone from the Shadethicket Oracle, then bring it to Pelturas in Astranaar.]],choiceRewards={{id=5814,qty=1},{id=6722,qty=1},{id=17047,qty=1}}}
DB[1036]={id=1036,zoneId=33,name=[[Avast Ye, Scallywag]],name_loc=[[¡Adelante, pillín!]],level=60,minLevel=55,giver=[["Pretty Boy" Duncan]],giver_loc=[["El Guapo" Duncan]],giverType=[[NPC]],giverId=2545,ender=[[Fleet Master Firallon]],ender_loc=[[Maestro de flota Firallon]],enderType=[[NPC]],enderId=2546,rewardNextId=4621,poiX=-15025,poiY=269,wowhead=[[https://www.wowhead.com/wotlk/quest=1036]],image=[[assets/images/quests/placeholder.png]],desc=[[$N... yeah, I've heard of you.  I've heard that you're no friend of Booty Bay - just like us Bloodsail Buccaneers.  Fleet Master Firallon is looking for hale and hearty $g men : women; just like you for a special mission. If you're interested, head on out to the Crimson Veil and speak with him below decks.  She's anchored off the Wild Coast east of here, next to the Riptide and the Damsel's Luck.]],logDesc=[[Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale.]]}
DB[1037]={id=1037,zoneId=331,name=[[Velinde Starsong]],name_loc=[[Velinde Cantoestelar]],level=30,minLevel=25,giver=[[Sentinel Melyria Frostshadow]],giver_loc=[[Centinela Melyria Sombrigélida]],giverType=[[NPC]],giverId=3880,ender=[[Thyn'tel Bladeweaver]],ender_loc=[[Thyn'tel Tejespada]],enderType=[[NPC]],enderId=8026,prevId=1022,rewardNextId=1038,poiX=9962,poiY=2285,wowhead=[[https://www.wowhead.com/wotlk/quest=1037]],image=[[assets/images/quests/placeholder.png]],desc=[[Velinde Starsong was my predecessor here in Ashenvale Forest. At first it seemed she had the situation in Felwood under control, but little by little her efforts faltered. One day, she simply disappeared. I was sent here to continue her work. I'm afraid I know nothing of the priestess, however. Perhaps Thyn'tel Bladeweaver, one of the commanders of the Sentinels, knows further details of her disappearance that I was not a party to. Surely she will understand the import of such information.]],logDesc=[[Speak with Thyn'tel Bladeweaver at the Warrior's Terrace in Darnassus.]]}
DB[1038]={id=1038,zoneId=331,name=[[Velinde's Effects]],name_loc=[[Las pertenencias de Velinde]],level=30,minLevel=25,giver=[[Thyn'tel Bladeweaver]],giver_loc=[[Thyn'tel Tejespada]],giverType=[[NPC]],giverId=8026,ender=[[Thyn'tel Bladeweaver]],ender_loc=[[Thyn'tel Tejespada]],enderType=[[NPC]],enderId=8026,prevId=1037,rewardNextId=1039,poiX=9651,poiY=2279,wowhead=[[https://www.wowhead.com/wotlk/quest=1038]],image=[[assets/images/quests/placeholder.png]],desc=[[The Tome of Mel'Thandris showed you this? I suppose there would be little harm in allowing you to examine her belongings. This key will allow you to open the chest where we stored her things in the Sentinels' bunkhouse. She kept a journal of her duties, if there is anything to be learned, it will be from that. I should tell you, the Sentinels believe that she had her own reasons for leaving, and expect that she could return at any time. The priestess has done much in the past to earn our trust.]],logDesc=[[Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus.]]}
DB[1039]={id=1039,zoneId=331,name=[[The Barrens Port]],name_loc=[[El puerto de Los Baldíos]],level=30,minLevel=25,giver=[[Thyn'tel Bladeweaver]],giver_loc=[[Thyn'tel Tejespada]],giverType=[[NPC]],giverId=8026,ender=[[Wharfmaster Dizzywig]],ender_loc=[[Maestro de muelles Vertipeluca]],enderType=[[NPC]],enderId=3453,prevId=1038,rewardNextId=1040,poiX=-986,poiY=-3797,wowhead=[[https://www.wowhead.com/wotlk/quest=1039]],image=[[assets/images/quests/placeholder.png]],desc=[[Ratchet is the only port in the Barrens. Most likely Velinde found a trading vessel in Ratchet to take her to Blackwater Cove in Azeroth. We've had limited dealings with the goblins that run the port, but the master of the dock should have information about the comings and goings of ship passengers. Follow the road southeast through Ashenvale and you will find yourself in the Barrens. Watch your step, $n, warriors of the Horde patrol the land. You will be safe at the port, though.]],logDesc=[[Speak with Wharfmaster Dizzywig at Ratchet in the Barrens.]]}
DB[1040]={id=1040,zoneId=331,name=[[Passage to Booty Bay]],name_loc=[[Pasaje a Bahía del Botín]],level=30,minLevel=25,giver=[[Wharfmaster Dizzywig]],giver_loc=[[Maestro de muelles Vertipeluca]],giverType=[[NPC]],giverId=3453,ender=[[Caravaneer Ruzzgot]],ender_loc=[[Caravanero Ruzzgot]],enderType=[[NPC]],enderId=3945,prevId=1039,rewardNextId=1041,poiX=-14320,poiY=474,wowhead=[[https://www.wowhead.com/wotlk/quest=1040]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah yes, finally found it. Should have told me she passed through here that long ago. Let's see. Velinde. Booked passage to Booty Bay on the Black Osprey. I don't have anything here saying otherwise, so I'd assume it arrived in port safely. Not much more help I can be to you, but she asked about overland travel over on that side of the world, and I mentioned Ruzzgot, a caravan driver based out of Booty Bay. Might be that this Velinde traveled with him. Move along, now. I haven't all day for you.]],logDesc=[[Take a boat to Booty Bay and speak with Caravaneer Ruzzgot.]]}
DB[1041]={id=1041,zoneId=331,name=[[The Caravan Road]],name_loc=[[La ruta de la caravana]],level=30,minLevel=25,giver=[[Caravaneer Ruzzgot]],giver_loc=[[Caravanero Ruzzgot]],giverType=[[NPC]],giverId=3945,ender=[[Clerk Daltry]],ender_loc=[[Secretario Daltry]],enderType=[[NPC]],enderId=267,prevId=1040,rewardNextId=1042,poiX=-10560,poiY=-1125,wowhead=[[https://www.wowhead.com/wotlk/quest=1041]],image=[[assets/images/quests/placeholder.png]],desc=[[Turns out I was wrong about you, and that isn't something that happens everyday. It just so happens that I remember this Velinde you're looking for. Isn't every day that a night elf priestess that wants to travel with a dirty old--but great for your shipping needs!--caravan like my own. We split up on the way north, she was headed for Darkshire. The clerk there keeps all sorts of records. Might know something useful. Be careful in the jungle, it is a deadly place even at the best of times.]],logDesc=[[Speak with Clerk Daltry in Darkshire.]]}
DB[1042]={id=1042,zoneId=331,name=[[The Carevin Family]],name_loc=[[La familia Carevin]],level=30,minLevel=25,giver=[[Clerk Daltry]],giver_loc=[[Secretario Daltry]],giverType=[[NPC]],giverId=267,ender=[[Jonathan Carevin]],enderType=[[NPC]],enderId=661,prevId=1041,rewardNextId=1043,poiX=-10599,poiY=-1200,wowhead=[[https://www.wowhead.com/wotlk/quest=1042]],image=[[assets/images/quests/placeholder.png]],desc=[[No, I don't have any records of a Velinde Starsong staying in Darkshire... though, if you don't mind me saying, I can hardly imagine a night elf priestess taking a room in the inn, if you get my meaning? These wolf-men you mentioned though, that's something I've heard about. Just the other day, Calor came into town with a string of their heads. He works with the Carevin family. Hunters of demons, undead, and other monstrosities. Speak with Jonathan, he's the head of the household.]],logDesc=[[Speak with Jonathan Carevin in Darkshire.]]}
DB[1043]={id=1043,zoneId=331,name=[[The Scythe of Elune]],name_loc=[[La Guadaña de Elune]],level=30,minLevel=25,giver=[[Jonathan Carevin]],giverType=[[NPC]],giverId=661,ender=[[Jonathan Carevin]],enderType=[[NPC]],enderId=661,prevId=1042,rewardNextId=1044,poiX=-11141,poiY=-1152,wowhead=[[https://www.wowhead.com/wotlk/quest=1043]],image=[[assets/images/quests/placeholder.png]],desc=[[Your story rings true... I do not entirely understand your motives, but if your business here in Duskwood involves ridding the forest of worgen in any number, then I can forgo understanding for results. There is a mine to the south that has been overrun with worgen... They appeared out of nowhere, but from what we know, that is where they first were found. Go about your business, but I would ask that if you find anything of import, you share it with me. We will accept any aid in our war against evil.]],logDesc=[[Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire.]]}
DB[1044]={id=1044,zoneId=331,name=[[Answered Questions]],name_loc=[[La respuesta a las preguntas]],level=30,minLevel=25,giver=[[Jonathan Carevin]],giverType=[[NPC]],giverId=661,ender=[[Thyn'tel Bladeweaver]],ender_loc=[[Thyn'tel Tejespada]],enderType=[[NPC]],enderId=8026,prevId=1043,poiX=9962,poiY=2285,wowhead=[[https://www.wowhead.com/wotlk/quest=1044]],image=[[assets/images/quests/placeholder.png]],desc=[[We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions. Strange events are afoot in these times, $n, and the darkness knows no respite. I will keep you no longer. I suspect that there are others that should hear of what you have found in the mines of Duskwood.]],logDesc=[[Return to Thyn'tel Bladeweaver in Darnassus.]],choiceRewards={{id=5817,qty=1},{id=5818,qty=1}}}
DB[1045]={id=1045,zoneId=331,name=[[Raene's Cleansing]],name_loc=[[La limpieza de Raene]],level=30,minLevel=18,giver=[[Krolg]],giverType=[[NPC]],giverId=3897,ender=[[Krolg]],enderType=[[NPC]],enderId=3897,prevId=1030,rewardNextId=1046,poiX=1613,poiY=-1457,wowhead=[[https://www.wowhead.com/wotlk/quest=1045]],image=[[assets/images/quests/placeholder.png]],desc=[[The night elves are as old as time, but their arrogance destroys their very world. And now it destroys our lives too. But that can no longer be controlled... I blame the elves for much, but we are still responsible for our actions. Even beyond the corruption, we are capable of great evil. Ran Bloodtooth is one such evil. Power hungry, lusting... the corruption has only made him stronger. My hatred for the elves burns, but I do not wish ill upon their children, so we must police our own.]],logDesc=[[Kill Ran Bloodtooth, 4 Bloodtooth Guards and collect Ran Bloodtooth's Skull. Return to Krolg near Lake Mystral should you succeed.]]}
DB[1046]={id=1046,zoneId=331,name=[[Raene's Cleansing]],name_loc=[[La limpieza de Raene]],level=30,minLevel=18,giver=[[Krolg]],giverType=[[NPC]],giverId=3897,ender=[[Raene Wolfrunner]],ender_loc=[[Raene Correlobo]],enderType=[[NPC]],enderId=3691,prevId=1045,poiX=2767,poiY=-412,wowhead=[[https://www.wowhead.com/wotlk/quest=1046]],image=[[assets/images/quests/placeholder.png]],desc=[[Return to your own tribe and let them know of your victory here. Show them your trophy, and bask in the glory...]],logDesc=[[Bring Ran Bloodtooth's Skull to Raene Wolfrunner in Astranaar.]],rewards={{id=1116,qty=1}},choiceRewards={{id=5815,qty=1},{id=17046,qty=1}}}
DB[1047]={id=1047,zoneId=1657,name=[[The New Frontier]],name_loc=[[La nueva frontera]],level=55,minLevel=54,giver=[[Herald Moonstalker]],giver_loc=[[Heraldo Acechalunas]],giverType=[[NPC]],giverId=10878,ender=[[Arch Druid Fandral Staghelm]],ender_loc=[[Archidruida Fandral Corzocelada]],enderType=[[NPC]],enderId=3516,nextId=6761,rewardNextId=6761,exGroup=1015,poiX=10175,poiY=2568,wowhead=[[https://www.wowhead.com/wotlk/quest=1047]],image=[[assets/images/quests/placeholder.png]],desc=[[Attention, heroes! The Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead. All interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!]],logDesc=[[Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.]]}
DB[1048]={id=1048,zoneId=796,name=[[Into The Scarlet Monastery]],name_loc=[[En el Monasterio Escarlata]],level=42,minLevel=30,giver=[[Varimathras]],giverType=[[NPC]],giverId=2425,ender=[[Varimathras]],enderType=[[NPC]],enderId=2425,poiX=1288,poiY=334,wowhead=[[https://www.wowhead.com/wotlk/quest=1048]],image=[[assets/images/quests/placeholder.png]],desc=[[Whilst the Dark Lady tends to the pressing issue of the Lich King's advance to the north, I am seeing to it that matters closer to home are being taken care of accordingly. No doubt, the human pests who call themselves the Scarlet Crusade are proving to be the sharpest thorn in our side domestically. Tirisfal Glades is literally crawling with the little red ants. Travel to the Monastery, $c, and lay waste to High Inquisitor Whitemane and her top lieutenants.]],logDesc=[[Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.]],choiceRewards={{id=6802,qty=1},{id=6803,qty=1},{id=10711,qty=1}}}
DB[1049]={id=1049,zoneId=796,name=[[Compendium of the Fallen]],name_loc=[[El Compendio de los Caídos]],level=38,minLevel=28,giver=[[Sage Truthseeker]],giver_loc=[[Sabio Buscador de la Verdad]],giverType=[[NPC]],giverId=3978,ender=[[Sage Truthseeker]],ender_loc=[[Sabio Buscador de la Verdad]],enderType=[[NPC]],enderId=3978,poiX=-1176,poiY=158,wowhead=[[https://www.wowhead.com/wotlk/quest=1049]],image=[[assets/images/quests/placeholder.png]],desc=[[The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council? The Forsaken whom we have allied with have a history wrought with deceit. Too hasty was our pact. Perhaps Cairne would have been wise to heed the warnings from Orgrimmar. Deep within the Scarlet Monastery lies the Compendium of the Fallen, guarded by crazed human zealots. Their method is forged from insanity but their research might prove useful.]],logDesc=[[Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.]],choiceRewards={{id=7747,qty=1},{id=17508,qty=1},{id=7749,qty=1}}}
DB[1050]={id=1050,zoneId=796,name=[[Mythology of the Titans]],name_loc=[[Mitología de los titanes]],level=38,minLevel=28,giver=[[Librarian Mae Paledust]],giver_loc=[[Bibliotecaria Mae Palipolvo]],giverType=[[NPC]],giverId=3979,ender=[[Librarian Mae Paledust]],ender_loc=[[Bibliotecaria Mae Palipolvo]],enderType=[[NPC]],enderId=3979,poiX=-4635,poiY=-1306,wowhead=[[https://www.wowhead.com/wotlk/quest=1050]],image=[[assets/images/quests/placeholder.png]],desc=[[The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea. But perhaps, by studying the past, we can know what to expect and be better prepared for the unknown. Before dire troubles fell upon Lordaeron, there was a bastion of knowledge tucked away in the Tirisfal Glades. It is rumored that a book called Mythology of the Titans was housed in the library of the old Monastery. Bring it to me and perhaps together we can unlock the secrets of the past!]],logDesc=[[Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.]],rewards={{id=7746,qty=1}}}
DB[1051]={id=1051,zoneId=796,name=[[Vorrel's Revenge]],name_loc=[[La venganza de Vorrel]],level=33,minLevel=25,giver=[[Vorrel Sengutz]],giverType=[[NPC]],giverId=3981,ender=[[Monika Sengutz]],enderType=[[NPC]],enderId=3982,poiX=888,poiY=-122,wowhead=[[https://www.wowhead.com/wotlk/quest=1051]],image=[[assets/images/quests/placeholder.png]],desc=[[Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered. Interrogator Vishas did this to me! Tortured me for weeks! Took my wedding ring and gave it to his wife. The monster! Revenge... I want revenge! The pompous fool bragged about his precious wife, Nancy, who lived along Lake Lordamere. Track the wench down, slay her and return my wedding ring to my wife, Monika in Tarren Mill. Heed my last wishes....]],logDesc=[[Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.]],rewards={{id=7751,qty=1}},choiceRewards={{id=7750,qty=1},{id=4643,qty=1}}}
DB[1052]={id=1052,zoneId=405,name=[[Down the Scarlet Path]],name_loc=[[El sendero Escarlata]],level=40,minLevel=34,giver=[[Brother Anton]],giver_loc=[[Hermano Anton]],giverType=[[NPC]],giverId=1182,ender=[[Raleigh the Devout]],ender_loc=[[Raleigh el Devoto]],enderType=[[NPC]],enderId=3980,prevId=261,poiX=-845,poiY=-580,wowhead=[[https://www.wowhead.com/wotlk/quest=1052]],image=[[assets/images/quests/placeholder.png]],desc=[[We of the Scarlet Crusade lay claim to strongholds from Hearthglen to Tirisfal Glades. We are quite proud of our bastions of cleansing throughout Lordaeron. You have proven yourself against the undead in Desolace. But the true threat of the plague lies in Lordaeron. Travel to the town of Southshore, in the Eastern Kingdoms. Seek out a crusader named Raleigh the Devout. Give him this letter of commendation bearing my seal and he will escort you to a place of honor in our Scarlet Monastery.]],logDesc=[[Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore.]]}
DB[1053]={id=1053,zoneId=796,name=[[In the Name of the Light]],name_loc=[[En el nombre de la Luz]],level=40,minLevel=34,giver=[[Raleigh the Devout]],giver_loc=[[Raleigh el Devoto]],giverType=[[NPC]],giverId=3980,ender=[[Raleigh the Devout]],ender_loc=[[Raleigh el Devoto]],enderType=[[NPC]],enderId=3980,prevId=1052,poiX=-845,poiY=-580,wowhead=[[https://www.wowhead.com/wotlk/quest=1053]],image=[[assets/images/quests/placeholder.png]],desc=[[I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead. But as I spent time at the Monastery in Tirisfal Glades I realized that their grasp on reality was slipping. They now think everyone is plagued who doesn't wear the tabard of the Crusade. Innocent men and women were tortured because they were supposedly plagued.  The Scarlet Crusade must be crushed in the name of the Light. You, $n, must destroy the deranged regime.]],logDesc=[[Kill High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.]],choiceRewards={{id=6829,qty=1},{id=6830,qty=1},{id=6831,qty=1},{id=11262,qty=1}}}
DB[1054]={id=1054,zoneId=331,name=[[Culling the Threat]],name_loc=[[Matanza selectiva]],level=25,minLevel=18,giver=[[Raene Wolfrunner]],giver_loc=[[Raene Correlobo]],giverType=[[NPC]],giverId=3691,ender=[[Raene Wolfrunner]],ender_loc=[[Raene Correlobo]],enderType=[[NPC]],enderId=3691,poiX=3277,poiY=-584,wowhead=[[https://www.wowhead.com/wotlk/quest=1054]],image=[[assets/images/quests/placeholder.png]],desc=[[Directly to the north of Astranaar are the Thistlefur furbolg. My scouts report that their numbers have grown greatly over the past few months. If they grow too great, they may find the courage to attack Astranaar directly. Kill as many of their kind as you can, but bring me their chieftain's skull as proof that their efforts have been stifled... for now. I shall remain here in Astranaar and await word from you. Elune be with you.]],logDesc=[[Bring Dal Bloodclaw's Skull to Raene Wolfrunner in Astranaar.]],rewards={{id=1970,qty=2}}}
DB[1055]={id=1055,zoneId=331,name=[[Raene's Cleansing]],name_loc=[[La limpieza de Raene]],level=28,minLevel=18,giver=[[Hidden Shrine]],giver_loc=[[Santuario Oculto]],giverType=[[GO]],giverId=19024,ender=[[Shael'dryn]],enderType=[[NPC]],enderId=3916,prevId=1028,rewardNextId=1029,poiX=2894,poiY=-1386,wowhead=[[https://www.wowhead.com/wotlk/quest=1055]],image=[[assets/images/quests/placeholder.png]],desc=[[The rod, now complete, lies in your hands. Shael'dryn will want to hear of your success.]],logDesc=[[Return to Shael'dryn at the moonwell.]]}
DB[1056]={id=1056,zoneId=331,name=[[Journey to Stonetalon Peak]],name_loc=[[Viaje a Cima del Espolón]],level=18,minLevel=18,giver=[[Faldreas Goeth'Shael]],giverType=[[NPC]],giverId=3996,ender=[[Keeper Albagorm]],ender_loc=[[Vigilante Albagorm]],enderType=[[NPC]],enderId=3994,poiX=2653,poiY=1434,wowhead=[[https://www.wowhead.com/wotlk/quest=1056]],image=[[assets/images/quests/placeholder.png]],desc=[[The forest spirits tell me you are brave and willing to travel. To the south, not far from Mystral Lake, there lies a tunnel named The Talondeep Path. Through this tunnel you will come to an area known as Windshear Crag in the Stonetalon Mountains. Once there, journey to the southwest past Cragpool Lake and then north, up the steep slope until you reach Stonetalon Peak. There awaits Keeper Albagorm. Heed his bidding, $r. The journey will be perilous.]],logDesc=[[Travel to Keeper Albagorm on Stonetalon Peak.]]}
DB[1057]={id=1057,zoneId=406,name=[[Reclaiming the Charred Vale]],name_loc=[[La reconquista de La Vega Carbonizada]],level=27,minLevel=20,giver=[[Keeper Albagorm]],giver_loc=[[Vigilante Albagorm]],giverType=[[NPC]],giverId=3994,ender=[[Keeper Albagorm]],ender_loc=[[Vigilante Albagorm]],enderType=[[NPC]],enderId=3994,rewardNextId=1059,poiX=824,poiY=1516,wowhead=[[https://www.wowhead.com/wotlk/quest=1057]],image=[[assets/images/quests/placeholder.png]],desc=[[As a protector of the forest spirits you can undoubtedly guess why I am alarmed. You have traveled through these mountains to reach this peak. Surely you have seen the travesty which has befallen the land. Greed has led to the destruction of these sacred hills. The Charred Vale to the south was set afire by the greedy mechanized army of industrialists. Worse yet, the Bloodfuries that have encroached on the land refuse us passage in to begin regrowth. Drive the wretched harpies out, $n!]],logDesc=[[Keeper Albagorm on Stonetalon Peak wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.]]}
DB[1058]={id=1058,zoneId=406,name=[[Jin'Zil's Forest Magic]],name_loc=[[Magia del bosque de Jin'Zil]],level=26,minLevel=20,giver=[[Witch Doctor Jin'Zil]],giver_loc=[[Médico brujo Jin'Zil]],giverType=[[NPC]],giverId=3995,ender=[[Witch Doctor Jin'Zil]],ender_loc=[[Médico brujo Jin'Zil]],enderType=[[NPC]],enderId=3995,poiX=2449,poiY=1282,wowhead=[[https://www.wowhead.com/wotlk/quest=1058]],image=[[assets/images/quests/placeholder.png]],desc=[[So excited I am! Three little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of... what do they call it... forest magic! I'll need a good mess of Stonetalon sap. From those horrid felines, bring me some twilight whiskers. This calls for plenty of courser eyes, of course -- can never have enough eyes. Oh, and lest we forget, a precious scale from a fey dragon. Hurry to Stonetalon Peak, $n, so I can brew some forest magic!]],logDesc=[[Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale.]],choiceRewards={{id=6664,qty=1},{id=6665,qty=1}}}
DB[1059]={id=1059,zoneId=406,name=[[Reclaiming the Charred Vale]],name_loc=[[La reconquista de La Vega Carbonizada]],level=27,minLevel=20,giver=[[Keeper Albagorm]],giver_loc=[[Vigilante Albagorm]],giverType=[[NPC]],giverId=3994,ender=[[Falfindel Waywarder]],ender_loc=[[Díscolo Falfindel]],enderType=[[NPC]],enderId=4048,prevId=1057,poiX=-4524,poiY=-788,wowhead=[[https://www.wowhead.com/wotlk/quest=1059]],image=[[assets/images/quests/placeholder.png]],desc=[[The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken. Far south of the Barrens lies a land known as Thousand Needles. If you travel west in Thousand Needles until you reach the lush forest's edge of Feralas, you will find a druid named Falfindel Waywarder. This great and wise druid is capable of calling forth great forest spirits which can aid in the reclamation of the Charred Vale. Send word of our need! Seek him out at once!]],logDesc=[[Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas.]],choiceRewards={{id=6675,qty=1},{id=6676,qty=1}}}
DB[1060]={id=1060,zoneId=17,name=[[Letter to Jin'Zil]],name_loc=[[Una carta para Jin'Zil]],level=20,minLevel=15,giver=[[Darsok Swiftdagger]],giver_loc=[[Darsok Movedaga]],giverType=[[NPC]],giverId=3449,ender=[[Witch Doctor Jin'Zil]],ender_loc=[[Médico brujo Jin'Zil]],enderType=[[NPC]],enderId=3995,prevId=876,poiX=-272,poiY=-394,wowhead=[[https://www.wowhead.com/wotlk/quest=1060]],image=[[assets/images/quests/placeholder.png]],desc=[[You've done so well for me, $n. You're a regular lucky rabbit's foot and there's something I want you to see. The harpies are not from around the Barrens. They come from a place called Stonetalon, far to the northwest of here. Though it is probably a dangerous place for you, I need this letter delivered to an old friend of mine who lives there, a witch doctor by the name of Jin'Zil. He'll be happy to know that Serena Bloodfeather is dead, and I think you'll find Stonetalon an interesting place.]],logDesc=[[Deliver Darsok's letter to Jin'Zil within his cave in Malaka'Jin, in Stonetalon.]]}
DB[1061]={id=1061,zoneId=406,name=[[The Spirits of Stonetalon]],name_loc=[[Los espíritus del Espolón]],level=17,minLevel=13,giver=[[Zor Lonetree]],giver_loc=[[Zor Árbol Solitario]],giverType=[[NPC]],giverId=4047,ender=[[Seereth Stonebreak]],ender_loc=[[Seereth Rompepedras]],enderType=[[NPC]],enderId=4049,rewardNextId=1062,poiX=-271,poiY=-950,wowhead=[[https://www.wowhead.com/wotlk/quest=1061]],image=[[assets/images/quests/placeholder.png]],desc=[[The spirits of the Stonetalon Mountains are angered, for goblins and their servants are plundering and burning the land.  So the land has cried out, and those who listen for such things... have heard. Seereth Stonebreak, a promising shaman of the Horde, was sent to Stonetalon.  She reports massive deforestation at the hands of the goblins, and requests aid. Meet Seereth in Stonetalon.  To reach her, follow the road west of the Barrens' Crossroads.  She is camped near the Greatwood Vale.]],logDesc=[[Speak with Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.]]}
DB[1062]={id=1062,zoneId=406,name=[[Goblin Invaders]],name_loc=[[Los invasores goblin]],level=19,minLevel=13,giver=[[Seereth Stonebreak]],giver_loc=[[Seereth Rompepedras]],giverType=[[NPC]],giverId=4049,ender=[[Seereth Stonebreak]],ender_loc=[[Seereth Rompepedras]],enderType=[[NPC]],enderId=4049,poiX=989,poiY=-420,wowhead=[[https://www.wowhead.com/wotlk/quest=1062]],image=[[assets/images/quests/placeholder.png]],desc=[[The goblin-run Venture Company moved into the Stonetalon Mountains, chopping down trees and burning huge stretches of forest.  The spirits of this place are nearly blind with pain and rage.  We must stop the Venture Company! Head northwest, beyond the Greatwood Vale and into the Windshear Crag.  You will find the goblins and their servants at work--show them the Horde will not allow the exploitation of Stonetalon.  Show them in the language they best understand... Violence.]],logDesc=[[Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens.]]}
DB[1063]={id=1063,zoneId=406,name=[[The Elder Crone]],name_loc=[[La bruja anciana]],level=18,minLevel=13,giver=[[Seereth Stonebreak]],giver_loc=[[Seereth Rompepedras]],giverType=[[NPC]],giverId=4049,ender=[[Magatha Grimtotem]],ender_loc=[[Magatha Tótem Siniestro]],enderType=[[NPC]],enderId=4046,prevId=1062,poiX=-1065,poiY=-212,wowhead=[[https://www.wowhead.com/wotlk/quest=1063]],image=[[assets/images/quests/placeholder.png]],desc=[[To truly tend the spirits of Stonetalon we must consult the tauren elders. I do not know many of their leaders' names, but I do know of one: Magatha.  I have heard that she is very old, and she knows much.  If anyone can marshal spiritual aid from the tauren, it is she. Magatha resides in the tauren capital of Thunder Bluff, on Elder Rise -- the city's northeastern bluff.  Speak with Magatha, and tell her of the peril of Stonetalon Mountains.]],logDesc=[[Speak with Magatha in Thunder Bluff.]]}
DB[1064]={id=1064,zoneId=1638,name=[[Forsaken Aid]],name_loc=[[La ayuda de los Renegados]],level=18,minLevel=13,giver=[[Magatha Grimtotem]],giver_loc=[[Magatha Tótem Siniestro]],giverType=[[NPC]],giverId=4046,ender=[[Apothecary Zamah]],ender_loc=[[Boticaria Zamah]],enderType=[[NPC]],enderId=3419,prevId=1063,rewardNextId=1065,poiX=-995,poiY=279,wowhead=[[https://www.wowhead.com/wotlk/quest=1064]],image=[[assets/images/quests/placeholder.png]],desc=[[The tauren have a bond with the land, and it pains me to hear of Stonetalon's plight.  But I fear that to heal the land, we must first remove the disease upon it. Is it not fortunate, then, that the Forsaken are allied with us?  They know much of disease.  I believe they can aid us, and by doing so they will strengthen the trust between our people. Speak with Apothecary Zamah.  She is a scholar and an emissary of the Forsaken.  You will find her in the Pools of Vision below the Spirit Rise.]],logDesc=[[Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff.]]}
DB[1065]={id=1065,zoneId=1638,name=[[Journey to Tarren Mill]],name_loc=[[Viaja a Molino Tarren]],level=18,minLevel=13,giver=[[Apothecary Zamah]],giver_loc=[[Boticaria Zamah]],giverType=[[NPC]],giverId=3419,ender=[[Apothecary Lydon]],ender_loc=[[Boticario Lydon]],enderType=[[NPC]],enderId=2216,prevId=1064,rewardNextId=1066,poiX=-7,poiY=-899,wowhead=[[https://www.wowhead.com/wotlk/quest=1065]],image=[[assets/images/quests/placeholder.png]],desc=[[To rid Stonetalon of the Venture Company, we must take extreme measures.  Extreme, but without bloodshed. A colleague of mine may have just the tool we need.  His name is Lydon; he dwells in the town of Tarren Mill in the Hillsbrad Foothills, in the distant land of Lordaeron. To reach Hillsbrad, travel by zeppelin to our capital, the Undercity.  Then go north to Tirisfal Glades, southwest to Silverpine, and south to Hillsbrad. Seek Lydon and bring him this note.  It details our needs to him.]],logDesc=[[Bring Zamah's Note to Apothecary Lydon in Tarren Mill.]]}
DB[1066]={id=1066,zoneId=1638,name=[[Blood of Innocents]],name_loc=[[Sangre inocente]],level=23,minLevel=13,giver=[[Apothecary Lydon]],giver_loc=[[Boticario Lydon]],giverType=[[NPC]],giverId=2216,ender=[[Apothecary Lydon]],ender_loc=[[Boticario Lydon]],enderType=[[NPC]],enderId=2216,prevId=1065,poiX=-464,poiY=-1604,wowhead=[[https://www.wowhead.com/wotlk/quest=1066]],image=[[assets/images/quests/placeholder.png]],desc=[[I will create a toxin to bleed the violence from the Venture Company, rendering them weak and docile.  That should fix the Horde's problem in Stonetalon, yes? But to create the toxin, I will need the blood of innocents, a difficult ingredient to obtain. Fortunately the Syndicate, a group of human brigands in this area, employ shadow mages... and those mages collect innocent blood for their own, unsavory purposes. You can find the Syndicate shadow mages in Durnholde Keep to the southeast.]],logDesc=[[Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill.]]}
DB[1067]={id=1067,zoneId=1638,name=[[Return to Thunder Bluff]],name_loc=[[Regresa a Cima del Trueno]],level=23,minLevel=13,giver=[[Apothecary Lydon]],giver_loc=[[Boticario Lydon]],giverType=[[NPC]],giverId=2216,ender=[[Apothecary Zamah]],ender_loc=[[Boticaria Zamah]],enderType=[[NPC]],enderId=3419,prevId=1066,poiX=-995,poiY=279,wowhead=[[https://www.wowhead.com/wotlk/quest=1067]],image=[[assets/images/quests/placeholder.png]],desc=[[Here is the toxin.  If you use it against the Venture Company it should produce favorable, perhaps even contagious, results.  I must say, it is quite exciting to see my work applied in the field! But before using it, take it to Apothecary Zamah.  She must create a delivery method for the toxin to maximize its effect.]],logDesc=[[Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff.]]}
DB[1068]={id=1068,zoneId=406,name=[[Shredding Machines]],name_loc=[[Las sierras XT:4 y XT:9]],level=23,minLevel=13,giver=[[Seereth Stonebreak]],giver_loc=[[Seereth Rompepedras]],giverType=[[NPC]],giverId=4049,ender=[[Seereth Stonebreak]],ender_loc=[[Seereth Rompepedras]],enderType=[[NPC]],enderId=4049,prevId=1062,poiX=1400,poiY=-43,wowhead=[[https://www.wowhead.com/wotlk/quest=1068]],image=[[assets/images/quests/placeholder.png]],desc=[[There is a relation to the spiritual magic of shaman and the natural magic of druids.  This is why we shaman can hear the plea of the spirits of Stonetalon.  Many of their whisperings are lost to me, but one message, one vision, is clear... I saw a vision of two man-shaped machines in Windshear Crag, northwest of Greatwood Vale, felling trees with impossible speed.  These metal beasts must be stopped! In my vision, the machines were marked with strange symbols: XT:4 and XT:9.]],logDesc=[[Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.]]}
DB[1069]={id=1069,zoneId=17,name=[[Deepmoss Spider Eggs]],name_loc=[[Huevos de arañas Musgondo]],level=20,minLevel=15,giver=[[Mebok Mizzyrix]],giverType=[[NPC]],giverId=3446,ender=[[Mebok Mizzyrix]],enderType=[[NPC]],enderId=3446,poiX=587,poiY=559,wowhead=[[https://www.wowhead.com/wotlk/quest=1069]],image=[[assets/images/quests/placeholder.png]],desc=[[Spider egg omelettes are a new fad in Booty Bay!  The problem is... Booty Bay's got no eggs. I smell an opportunity! In Windshear Crag and Sishir Canyon, in the Stonetalon Mountains to the northwest, lives the deepmoss spider.  Bring me its eggs and I'll pay a bundle! In Windshear Crag, the eggs will be clustered under what trees remain. In Sishir Canyon... well, if you have a weak stomach then maybe you should just collect the eggs at Windshear Crag...]],logDesc=[[Bring 15 Deepmoss Eggs to Mebok Mizzyrix in Ratchet.]]}
DB[1070]={id=1070,zoneId=331,name=[[On Guard in Stonetalon]],name_loc=[[Estar de guardia en Espolón]],level=21,minLevel=17,giver=[[Sentinel Thenysil]],giver_loc=[[Centinela Thenysil]],giverType=[[NPC]],giverId=4079,ender=[[Kaela Shadowspear]],ender_loc=[[Kaela Lanzasombra]],enderType=[[NPC]],enderId=4080,rewardNextId=1085,poiX=740,poiY=321,wowhead=[[https://www.wowhead.com/wotlk/quest=1070]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello, $N. You seem to be full of wanderlust by the looks of you. Have you been to the Stonetalon Mountains? It is a land plagued by the Venture Co. and other enemies of the night elves. Recently, Sentinel Wolfrunner sent my friend Kaela Shadowspear there to investigate what's happening to the land, but I have yet to hear word back from her. I'm even more concerned because the Alliance sent a gnome mage along with her... a sign of trouble for sure. Would you find her and report back to me?]],logDesc=[[Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains.]]}
DB[1071]={id=1071,zoneId=406,name=[[A Gnome's Respite]],name_loc=[[Una tregua para el gnomo]],level=21,minLevel=17,giver=[[Gaxim Rustfizzle]],giver_loc=[[Gaxim Silvóxido]],giverType=[[NPC]],giverId=4077,ender=[[Gaxim Rustfizzle]],ender_loc=[[Gaxim Silvóxido]],enderType=[[NPC]],enderId=4077,prevId=1085,poiX=1118,poiY=-416,wowhead=[[https://www.wowhead.com/wotlk/quest=1071]],image=[[assets/images/quests/placeholder.png]],desc=[[You see, $N, I'm a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, and it's my goal... nay, my DUTY! to show the night elves that a blend of magic, mixtures, and mechanisms can help save their forests. But it's a hard fought war, and the goblins reproduce like rabbits it seems. I haven't even had time to build my newest inventions! I need some time to plan and organize. But to do that, I need your help keeping the goblins at bay in Windshear Crag to the east...]],logDesc=[[Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon.]]}
DB[1072]={id=1072,zoneId=406,name=[[An Old Colleague]],name_loc=[[Un viejo colega]],level=21,minLevel=17,giver=[[Gaxim Rustfizzle]],giver_loc=[[Gaxim Silvóxido]],giverType=[[NPC]],giverId=4077,ender=[[Lomac Gearstrip]],ender_loc=[[Lomac Destrabaengranajes]],enderType=[[NPC]],enderId=4081,prevId=1071,rewardNextId=1073,poiX=-4843,poiY=-1284,wowhead=[[https://www.wowhead.com/wotlk/quest=1072]],image=[[assets/images/quests/placeholder.png]],desc=[[The device I'm thinking about is my most advanced version to date. But we'll need a special potion if it's to work. I'm thinking we might as well get the good stuff since this mission could be your last. And for that, we're going to need some potent explosives: Nitromirglyceronium. The only person who can make NG-5 is an old friend of mine: Lomac Gearstrip. Look for him in Tinker Town. You talk him into making us some NG-5, I'll get to work on placement for my devices.]],logDesc=[[Speak to Lomac Gearstrip in Ironforge.]]}
DB[1073]={id=1073,zoneId=406,name=[[Ineptitude + Chemicals = Fun]],name_loc=[[Ineptitud + Productos químicos = Diversión]],level=21,minLevel=17,giver=[[Lomac Gearstrip]],giver_loc=[[Lomac Destrabaengranajes]],giverType=[[NPC]],giverId=4081,ender=[[Lomac Gearstrip]],ender_loc=[[Lomac Destrabaengranajes]],enderType=[[NPC]],enderId=4081,prevId=1072,rewardNextId=1074,poiX=-4669,poiY=-3115,wowhead=[[https://www.wowhead.com/wotlk/quest=1073]],image=[[assets/images/quests/placeholder.png]],desc=[[Hahaha... you need Nitromirglyceronium to stop goblins from destroying a forest?! I don't care if you know Gaxim or not... I'll give you the stuff just to see you or them explode into itty bitty pieces. There's a problem though: I'm all out. But I'll tell you what, you bring me the correct potions, and I'll make some up for you right away. The least you can do is prove you've got some skill as an alchemist before I just give you a sample of my greatest creation.]],logDesc=[[Bring 4 Minor Mana Potions and 2 Elixirs of Minor Fortitude to Lomac Gearstrip in Ironforge.]]}
DB[1074]={id=1074,zoneId=406,name=[[Ineptitude + Chemicals = Fun]],name_loc=[[Ineptitud + Productos químicos = Diversión]],level=21,minLevel=17,giver=[[Lomac Gearstrip]],giver_loc=[[Lomac Destrabaengranajes]],giverType=[[NPC]],giverId=4081,ender=[[Gaxim Rustfizzle]],ender_loc=[[Gaxim Silvóxido]],enderType=[[NPC]],enderId=4077,prevId=1073,nextId=1080,exGroup=-1074,poiX=730,poiY=340,wowhead=[[https://www.wowhead.com/wotlk/quest=1074]],image=[[assets/images/quests/placeholder.png]],desc=[[Here you go, stranger. Take heed with it though... it's volatile stuff. If you're really a friend of Gaxim's, then tell him I say hello. If you're not, then have fun blowin' yerself up.]],logDesc=[[Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon.]]}
DB[1075]={id=1075,zoneId=406,name=[[A Scroll from Mauren]],name_loc=[[Un pergamino de Mauren]],level=21,minLevel=17,giver=[[Gaxim Rustfizzle]],giver_loc=[[Gaxim Silvóxido]],giverType=[[NPC]],giverId=4077,ender=[[Collin Mauren]],enderType=[[NPC]],enderId=4078,prevId=1071,rewardNextId=1076,poiX=-8997,poiY=800,wowhead=[[https://www.wowhead.com/wotlk/quest=1075]],image=[[assets/images/quests/placeholder.png]],desc=[[Okay, now for the remote detonation part of my plan... oh, I haven't explained that yet, have I? Okay, so the short of it is this: with a little magic, I can make it so the explosives go off while you're not around. I'm putting together a device that'll allow you to push just one button and have the NG-5 explode when you're ready. But I need a spell from a friend in Stormwind--Collin Mauren is his name. You can find him in the mage quarter there. He's human, so he shouldn't be hard to miss.]],logDesc=[[Find Collin Mauren in Stormwind.]]}
DB[1076]={id=1076,zoneId=406,name=[[Devils in Westfall]],name_loc=[[Demonios en los Páramos de Poniente]],level=21,minLevel=17,giver=[[Collin Mauren]],giverType=[[NPC]],giverId=4078,ender=[[Collin Mauren]],enderType=[[NPC]],enderId=4078,prevId=1075,poiX=-10216,poiY=889,wowhead=[[https://www.wowhead.com/wotlk/quest=1076]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, I think I have it. A messaging spell... I believe that's the effect he's looking for. I'll have to create a scroll with the spell impressed upon it. To do that I'll need debris from a dust devil. While I gather the rest of the components, why don't you head to Westfall and find one of the foul creatures? They are dangerous, but I'm sure it's nothing you can't handle if you're willing to subject yourself to one of Gaxim's experiments. I'll be here when you return.]],logDesc=[[Bring Dust Devil Debris to Collin Mauren in Stormwind.]]}
DB[1077]={id=1077,zoneId=406,name=[[Special Delivery for Gaxim]],name_loc=[[Entrega especial para Gaxim]],level=21,minLevel=17,giver=[[Collin Mauren]],giverType=[[NPC]],giverId=4078,ender=[[Gaxim Rustfizzle]],ender_loc=[[Gaxim Silvóxido]],enderType=[[NPC]],enderId=4077,prevId=1076,nextId=1079,exGroup=-1074,poiX=730,poiY=340,wowhead=[[https://www.wowhead.com/wotlk/quest=1077]],image=[[assets/images/quests/placeholder.png]],desc=[[Here you are, $N. This should do nicely. Please give my regards to Gaxim when next you see him. I look forward to hearing about this adventure when it sees its completion. Fare well.]],logDesc=[[Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon.]]}
DB[1078]={id=1078,zoneId=406,name=[[Retrieval for Mauren]],name_loc=[[Escamas cristalizadas para Mauren]],level=26,minLevel=17,giver=[[Collin Mauren]],giverType=[[NPC]],giverId=4078,ender=[[Collin Mauren]],enderType=[[NPC]],enderId=4078,poiX=-8999,poiY=802,wowhead=[[https://www.wowhead.com/wotlk/quest=1078]],image=[[assets/images/quests/placeholder.png]],desc=[[Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co. Within the Charred Vale, deep in Stonetalon, there used to be a species of basilisks whose scales, when ground to dust, made a wonderful reagent for some spells I've created. If those basilisks still live, I would love to have a few of their scales. Take your time, it is no rush, but I can pay well.]],logDesc=[[Bring 8 Crystalized Scales to Collin Mauren in Stormwind.]],rewards={{id=6677,qty=1}}}
DB[1079]={id=1079,zoneId=406,name=[[Covert Ops - Alpha]],name_loc=[[Operaciones secretas: plan A]],level=22,minLevel=17,giver=[[Gaxim Rustfizzle]],giver_loc=[[Gaxim Silvóxido]],giverType=[[NPC]],giverId=4077,ender=[[Gaxim Rustfizzle]],ender_loc=[[Gaxim Silvóxido]],enderType=[[NPC]],enderId=4077,prevId=1074,nextId=1091,exGroup=-1079,poiX=1245,poiY=18,wowhead=[[https://www.wowhead.com/wotlk/quest=1079]],image=[[assets/images/quests/placeholder.png]],desc=[[This is it, $N. Pay close attention. The devices are done, and ready to be used. Take these pages--they'll explain more about the detonators and explosives, and where you should place them. Remember, the success of your mission doesn't depend on how much destruction you cause. Plan Alpha's success depends on you bringing back the Venture Co.'s engineering plans from inside the lumber mill south of Cragpool Lake.]],logDesc=[[Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag.]]}
DB[1080]={id=1080,zoneId=406,name=[[Covert Ops - Beta]],name_loc=[[Operaciones secretas: plan B]],level=22,minLevel=17,giver=[[Gaxim Rustfizzle]],giver_loc=[[Gaxim Silvóxido]],giverType=[[NPC]],giverId=4077,ender=[[Gaxim Rustfizzle]],ender_loc=[[Gaxim Silvóxido]],enderType=[[NPC]],enderId=4077,prevId=1077,nextId=1091,exGroup=-1079,poiX=986,poiY=-390,wowhead=[[https://www.wowhead.com/wotlk/quest=1080]],image=[[assets/images/quests/placeholder.png]],desc=[[Plan Beta's just like Plan Alpha, $N. We cause a distraction and then steal their precious letters. The key is to get their letters... remember that. The pages I gave you already will tell you where to plant the explosives. Just get back here alive and with those letters....]],logDesc=[[Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag.]]}
DB[1081]={id=1081,zoneId=406,name=[[Reception from Tyrande]],name_loc=[[El recibimiento de Tyrande]],level=28,minLevel=17,giver=[[Sentinel Thenysil]],giver_loc=[[Centinela Thenysil]],giverType=[[NPC]],giverId=4079,ender=[[Tyrande Whisperwind]],ender_loc=[[Tyrande Susurravientos]],enderType=[[NPC]],enderId=7999,prevId=1082,poiX=9663,poiY=2525,wowhead=[[https://www.wowhead.com/wotlk/quest=1081]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission. It may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains. If you consider yourself our ally against these atrocities, go see Tyrande in the Temple of the Moon in Darnassus.]],logDesc=[[Find Tyrande Whisperwind in Darnassus.]],rewards={{id=6678,qty=1}},choiceRewards={{id=7334,qty=1},{id=7335,qty=1},{id=7336,qty=1}}}
DB[1082]={id=1082,zoneId=406,name=[[Update for Sentinel Thenysil]],name_loc=[[Noticias para Centinela Thenysil]],level=22,minLevel=17,giver=[[Kaela Shadowspear]],giver_loc=[[Kaela Lanzasombra]],giverType=[[NPC]],giverId=4080,ender=[[Sentinel Thenysil]],ender_loc=[[Centinela Thenysil]],enderType=[[NPC]],enderId=4079,rewardNextId=1081,poiX=2759,poiY=-312,wowhead=[[https://www.wowhead.com/wotlk/quest=1082]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you have done a great deed by lending a hand here. The Sentinels of Ashenvale will reward you well if you informed them that Gaxim and I are alive. Tell them we are well on our way to stopping the Venture Co. and healing the lands. Find Tara Thenysil in Astranaar; she will be pleased to see you've returned with good news.]],logDesc=[[Return to Sentinel Thenysil in Ashenvale.]]}
DB[1083]={id=1083,zoneId=406,name=[[Enraged Spirits]],name_loc=[[Los espíritus iracundos]],level=26,minLevel=20,giver=[[Kaela Shadowspear]],giver_loc=[[Kaela Lanzasombra]],giverType=[[NPC]],giverId=4080,ender=[[Kaela Shadowspear]],ender_loc=[[Kaela Lanzasombra]],enderType=[[NPC]],enderId=4080,prevId=1091,nextId=1082,exGroup=-1083,poiX=585,poiY=1450,wowhead=[[https://www.wowhead.com/wotlk/quest=1083]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm unsure what the Venture Co. did to the Vale, but it's obvious they were overpowered by the creatures there. They set the forest aflame, and used their inventions of destruction to decimate as much of the Vale as possible. But in their ignorance they also released something else: burning spirits, elementals of flame, stone and rage. The land has no chance to see Elune's smile while these creatures roam free. Bring me their smoldering embers to show you've reduced their numbers.]],logDesc=[[Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon.]]}
DB[1084]={id=1084,zoneId=406,name=[[Wounded Ancients]],name_loc=[[Los antárboles corruptos]],level=28,minLevel=22,giver=[[Kaela Shadowspear]],giver_loc=[[Kaela Lanzasombra]],giverType=[[NPC]],giverId=4080,ender=[[Kaela Shadowspear]],ender_loc=[[Kaela Lanzasombra]],enderType=[[NPC]],enderId=4080,prevId=1091,nextId=1082,exGroup=-1083,poiX=740,poiY=321,wowhead=[[https://www.wowhead.com/wotlk/quest=1084]],image=[[assets/images/quests/placeholder.png]],desc=[[It seems obvious to me that the protectors of the Vale--the treants--had something to do with the Venture Co. being driven back. Unfortunately, even those once great guardians have now become corrupt. Gaxim thinks their corruption is somehow linked to the weapons the goblins used during their retreat. I told him I'd collect a sample from a wounded treant and allow him to study it in order to figure out if that's true. Bring me some of the shrapnel so the gnome can tell me more...]],logDesc=[[Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon.]]}
DB[1085]={id=1085,zoneId=331,name=[[On Guard in Stonetalon]],name_loc=[[Estar de guardia en Espolón]],level=21,minLevel=17,giver=[[Kaela Shadowspear]],giver_loc=[[Kaela Lanzasombra]],giverType=[[NPC]],giverId=4080,ender=[[Gaxim Rustfizzle]],ender_loc=[[Gaxim Silvóxido]],enderType=[[NPC]],enderId=4077,rewardNextId=1071,poiX=730,poiY=340,wowhead=[[https://www.wowhead.com/wotlk/quest=1085]],image=[[assets/images/quests/placeholder.png]],desc=[[The situation here in Stonetalon is obviously grave for a night elf and gnome to be working together. The Venture Co. has devastated these lands and I've spent most of my time putting an end to the destruction. Do not judge Gaxim prematurely; he understands the need for us to work together. If you wish to aid us, then start by speaking to Gaxim. I'm sorry I cannot send you back to Tara with good news yet. Perhaps soon.]],logDesc=[[Speak to Gaxim in Stonetalon Mountains.]]}
DB[1086]={id=1086,zoneId=1638,name=[[The Flying Machine Airport]],name_loc=[[El aeropuerto]],level=23,minLevel=13,giver=[[Apothecary Zamah]],giver_loc=[[Boticaria Zamah]],giverType=[[NPC]],giverId=3419,ender=[[Apothecary Zamah]],ender_loc=[[Boticaria Zamah]],enderType=[[NPC]],enderId=3419,prevId=1067,poiX=1435,poiY=14,wowhead=[[https://www.wowhead.com/wotlk/quest=1086]],image=[[assets/images/quests/placeholder.png]],desc=[[The toxin is ready.  All that remains is its delivery.  You, $N, must make that delivery. The Venture Company must have a means of sending messages and light cargo between its headquarters and its operations in Stonetalon.  It is likely a small sky port -- not big enough for a zeppelin, but perhaps for a flying machine.  You must search the areas in Stonetalon under control of the Venture Company and find this sky port, if it exists.  If you find it, then place the toxin there. Place it, and run.]],logDesc=[[Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah.]]}
DB[1087]={id=1087,zoneId=406,name=[[Cenarius' Legacy]],name_loc=[[El legado de Cenarius]],level=25,minLevel=20,giver=[[Braelyn Firehand]],giver_loc=[[Braelyn Manofuego]],giverType=[[NPC]],giverId=4198,ender=[[Braelyn Firehand]],ender_loc=[[Braelyn Manofuego]],enderType=[[NPC]],enderId=4198,rewardNextId=1088,poiX=2548,poiY=1384,wowhead=[[https://www.wowhead.com/wotlk/quest=1087]],image=[[assets/images/quests/placeholder.png]],desc=[[You cannot imagine the hatred I possess for this wretched land. The ilk of Cenarius and the kaldorei druids at the peak employ their pathetic powers to stifle the flow of magic, even so far south of their pathetic holdings... their beloved forests. Would that I could return to Jaedenar and exult in the flow of magic, but my master will not allow me to return until my work is done. I have no doubt you love the night elves and their allies as little as I. Aid me, and both our ends might be satisfied.]],logDesc=[[Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat.]]}
DB[1088]={id=1088,zoneId=406,name=[[Ordanus]],name_loc=[[Ordanus]],level=29,minLevel=20,giver=[[Braelyn Firehand]],giver_loc=[[Braelyn Manofuego]],giverType=[[NPC]],giverId=4198,ender=[[Braelyn Firehand]],ender_loc=[[Braelyn Manofuego]],enderType=[[NPC]],enderId=4198,prevId=1087,rewardNextId=1089,poiX=949,poiY=1002,wowhead=[[https://www.wowhead.com/wotlk/quest=1088]],image=[[assets/images/quests/placeholder.png]],desc=[[They thought that they could halt the flow of magic. They were mistaken. They thought that they could hide Ordanus, but I will have his head! Magic grants me true sight. Yes... there he is. A crossroads... At the top of a great tree in Ashenvale Forest. A name... Raynewood. One of the eldest sons of the forest god. They spirited him away from the peak before I could find him, but his time runs short. Bring it to me and I will share with you a mighty gift.]],logDesc=[[Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat.]]}
DB[1089]={id=1089,zoneId=406,name=[[The Den]],name_loc=[[El Cubil]],level=29,minLevel=20,giver=[[Braelyn Firehand]],giver_loc=[[Braelyn Manofuego]],giverType=[[NPC]],giverId=4198,ender=[[Talon Den Hoard]],ender_loc=[[Tesoro de El Cubil del Espolón]],enderType=[[GO]],enderId=19599,prevId=1088,poiX=2547,poiY=1998,wowhead=[[https://www.wowhead.com/wotlk/quest=1089]],image=[[assets/images/quests/placeholder.png]],desc=[[The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items. They devised a complex scheme to keep them from falling into the wrong hands. Luckily, I managed to... extract some details from one of them. Hidden in a small lantern at the entrance of the Den, you will find the Gatekeeper's Key--with it you will be able to open caches around the Den. The items from these caches will allow you to open their hoard, located in one of the central areas.]],logDesc=[[Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard.]],rewards={{id=6669,qty=1},{id=6670,qty=1},{id=6671,qty=1}}}
DB[1090]={id=1090,zoneId=406,name=[[Gerenzo's Orders]],name_loc=[[Órdenes de Gerenzo]],level=22,minLevel=17,giver=[[Piznik]],giver_loc=[[Piznik]],giverType=[[NPC]],giverId=4276,ender=[[Piznik]],ender_loc=[[Piznik]],enderType=[[NPC]],enderId=4276,rewardNextId=1092,poiX=963,poiY=-315,wowhead=[[https://www.wowhead.com/wotlk/quest=1090]],image=[[assets/images/quests/placeholder.png]],desc=[[You know, I was once the second most important person here at this site. That all changed when Gerenzo took over. Fired my boss, Ziz Fizziks, and sent me down to work in the mines. Ziz told me to stay here and gather information, though. His new boss will pay us well if we can find out what Gerenzo's plans are. Anyways, what I do know is that Gerenzo has ordered large amounts of this gold-green ore to be mined. I can get you a sample to bring to Ziz, but you'll have to watch for patrols while I get it.]],logDesc=[[Get the mysterious ore from Piznik after he finishes mining it.]]}
DB[1091]={id=1091,zoneId=406,name=[[Kaela's Update]],name_loc=[[Noticias para Kaela]],level=22,minLevel=17,giver=[[Gaxim Rustfizzle]],giver_loc=[[Gaxim Silvóxido]],giverType=[[NPC]],giverId=4077,ender=[[Kaela Shadowspear]],ender_loc=[[Kaela Lanzasombra]],enderType=[[NPC]],enderId=4080,poiX=740,poiY=321,wowhead=[[https://www.wowhead.com/wotlk/quest=1091]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, take these letters to Kaela. I'm sure she'll want to know about this. Or at least the Sentinels will. Make sure you tell her how successful we were and how we couldn't have done it without a little bit of magic.]],logDesc=[[Bring the Venture Co. Letters to Kaela Shadowspear in Stonetalon Mountains.]]}
DB[1092]={id=1092,zoneId=406,name=[[Gerenzo's Orders]],name_loc=[[Órdenes de Gerenzo]],level=22,minLevel=17,giver=[[Piznik]],giver_loc=[[Piznik]],giverType=[[NPC]],giverId=4276,ender=[[Ziz Fizziks]],enderType=[[NPC]],enderId=4201,prevId=1090,poiX=878,poiY=365,wowhead=[[https://www.wowhead.com/wotlk/quest=1092]],image=[[assets/images/quests/placeholder.png]],desc=[[I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again. I'll sneak out and meet with Ziz. Hopefully, he'll be able to find me a new job! I'll try and clean up this mess a little, but you should take the ore sample to Ziz right away. He told me that he'd set up camp somewhere on the western side of Windshear Crag. Good luck.]],logDesc=[[Deliver the Unidentified Ore to Ziz Fizziks in the Stonetalon Mountains.]],rewards={{id=6666,qty=1}}}
DB[1093]={id=1093,zoneId=406,name=[[Super Reaper 6000]],name_loc=[[Súper Segadora 6000]],level=21,minLevel=16,giver=[[Ziz Fizziks]],giverType=[[NPC]],giverId=4201,ender=[[Ziz Fizziks]],enderType=[[NPC]],enderId=4201,rewardNextId=1094,poiX=1179,poiY=131,wowhead=[[https://www.wowhead.com/wotlk/quest=1093]],image=[[assets/images/quests/placeholder.png]],desc=[[Terrible what the Venture Company has done here, eh? What were they thinking? Goblin company hiring a gnome! Lucky for me, Sputtervalve knows a genius when he sees one. Hired me just after I'd been kicked out! Tells me they built some enormous woodcutting machine, and Sput' wants me to steal the plans for him. Unfortunately, Gerenzo--bloody gnome--wants me dead on sight... maybe you could steal the plans for me? You should be able to find them on one of their operators.]],logDesc=[[Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.]]}
DB[1094]={id=1094,zoneId=406,name=[[Further Instructions]],name_loc=[[Más instrucciones]],level=21,minLevel=16,giver=[[Ziz Fizziks]],giverType=[[NPC]],giverId=4201,ender=[[Sputtervalve]],ender_loc=[[Petardol]],enderType=[[NPC]],enderId=3442,prevId=1093,rewardNextId=1095,poiX=-902,poiY=-3759,wowhead=[[https://www.wowhead.com/wotlk/quest=1094]],image=[[assets/images/quests/placeholder.png]],desc=[[This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints. Sputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow.]],logDesc=[[Deliver the Sealed Envelope to Sputtervalve at Ratchet in the Barrens.]]}
DB[1095]={id=1095,zoneId=406,name=[[Further Instructions]],name_loc=[[Más instrucciones]],level=27,minLevel=16,giver=[[Sputtervalve]],giver_loc=[[Petardol]],giverType=[[NPC]],giverId=3442,ender=[[Ziz Fizziks]],enderType=[[NPC]],enderId=4201,prevId=1094,rewardNextId=1096,poiX=878,poiY=365,wowhead=[[https://www.wowhead.com/wotlk/quest=1095]],image=[[assets/images/quests/placeholder.png]],desc=[[The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo. Riddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch. Whatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him.]],logDesc=[[Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.]]}
DB[1096]={id=1096,zoneId=406,name=[[Gerenzo Wrenchwhistle]],name_loc=[[Gerenzo Silbillave]],level=27,minLevel=16,giver=[[Ziz Fizziks]],giverType=[[NPC]],giverId=4201,ender=[[Ziz Fizziks]],enderType=[[NPC]],enderId=4201,prevId=1095,poiX=1624,poiY=151,wowhead=[[https://www.wowhead.com/wotlk/quest=1096]],image=[[assets/images/quests/placeholder.png]],desc=[[I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones. Northeast of here, far above Cragpool Lake, up near the water wheel is where Gerenzo watches over the entire site. There's no way I could fight my way up there, not to mention take on Gerenzo... But you look like you might be able to make it. If you kill him for me, I'll make it worth your while!]],logDesc=[[Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.]],choiceRewards={{id=6667,qty=1},{id=6668,qty=1}}}
DB[1097]={id=1097,zoneId=1519,name=[[Elmore's Task]],name_loc=[[La tarea de Elmore]],level=15,minLevel=9,giver=[[Verner Osgood]],giver_loc=[[Verner Osbien]],giverType=[[NPC]],giverId=415,ender=[[Grimand Elmore]],enderType=[[NPC]],enderId=1416,rewardNextId=353,poiX=-8387,poiY=685,wowhead=[[https://www.wowhead.com/wotlk/quest=1097]],image=[[assets/images/quests/placeholder.png]],desc=[[There's a dwarven weaponsmith in Stormwind, Grimand Elmore, who sent word that he needs help with a delivery.  I believe he wants a package sent to his homeland in the north. You have a sturdy pair on you!  So if you're interested in some legwork then speak with Grimand.  We could use you down here, but we must also keep our ties strong with the dwarves. You can find Grimand Elmore at the weapon shop in the Dwarven District of Stormwind, in the northeast section of town.]],logDesc=[[Speak with Grimand Elmore in Stormwind.]]}
DB[1097]={id=1097,zoneId=1519,name=[[Elmore's Task]],name_loc=[[La tarea de Elmore]],level=15,minLevel=9,giver=[[Smith Argus]],giver_loc=[[Verner Osbien]],giverType=[[NPC]],giverId=514,ender=[[Grimand Elmore]],enderType=[[NPC]],enderId=1416,rewardNextId=353,poiX=-8387,poiY=685,wowhead=[[https://www.wowhead.com/wotlk/quest=1097]],image=[[assets/images/quests/placeholder.png]],desc=[[There's a dwarven weaponsmith in Stormwind, Grimand Elmore, who sent word that he needs help with a delivery.  I believe he wants a package sent to his homeland in the north. You have a sturdy pair on you!  So if you're interested in some legwork then speak with Grimand.  We could use you down here, but we must also keep our ties strong with the dwarves. You can find Grimand Elmore at the weapon shop in the Dwarven District of Stormwind, in the northeast section of town.]],logDesc=[[Speak with Grimand Elmore in Stormwind.]]}
DB[1098]={id=1098,zoneId=209,name=[[Deathstalkers in Shadowfang]],name_loc=[[Mortacechadores en Colmillo Oscuro]],level=25,minLevel=18,giver=[[High Executor Hadrec]],giver_loc=[[Sumo ejecutor Hadrec]],giverType=[[NPC]],giverId=1952,ender=[[Deathstalker Vincent]],ender_loc=[[Mortacechador Vincent]],enderType=[[NPC]],enderId=4444,wowhead=[[https://www.wowhead.com/wotlk/quest=1098]],image=[[assets/images/quests/placeholder.png]],desc=[[In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence.  It has been many days and they have not returned, but we must receive their report if we're to have any hope of a successful attack! So here is your task, $N.  Go to Shadowfang Keep to the south and find the Deathstalkers Adamant and Vincent.  Find them, and if they require aid then give it. This mission is as dangerous as is it critical, $N.  Do not fail.]],logDesc=[[Find the Deathstalker Adamant and Deathstalker Vincent.]],rewards={{id=3324,qty=1}}}
DB[1100]={id=1100,zoneId=400,name=[[Lonebrow's Journal]],name_loc=[[El diario de Soliceja]],level=27,minLevel=23,giverType=[[NPC]],ender=[[Falfindel Waywarder]],ender_loc=[[Díscolo Falfindel]],enderType=[[NPC]],enderId=4048,rewardNextId=1101,poiX=-4524,poiY=-788,wowhead=[[https://www.wowhead.com/wotlk/quest=1100]],image=[[assets/images/quests/placeholder.png]],desc=[[You slowly open the weathered journal of Henrig Lonebrow....]],logDesc=[[Read Henrig Lonebrow's Journal.]]}
DB[1101]={id=1101,zoneId=1717,name=[[The Crone of the Kraul]],name_loc=[[La bruja del Horado]],level=27,minLevel=23,giver=[[Falfindel Waywarder]],giver_loc=[[Díscolo Falfindel]],giverType=[[NPC]],giverId=4048,ender=[[Falfindel Waywarder]],ender_loc=[[Díscolo Falfindel]],enderType=[[NPC]],enderId=4048,prevId=1100,poiX=-4524,poiY=-788,wowhead=[[https://www.wowhead.com/wotlk/quest=1101]],image=[[assets/images/quests/placeholder.png]],desc=[[Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was. We must not let their valiance go for naught. This crone... Charlga Razorflank ... must be stopped. Surely, infiltrating the Kraul will be perilous. There isn't time to send word to Darnassus. $n, assemble a party to slay the crone. Bring me Razorflank's Medallion as proof of demise.]],logDesc=[[Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.]],rewards={{id=29200,qty=1}},choiceRewards={{id=4197,qty=1},{id=6742,qty=1},{id=6725,qty=1}}}
DB[1102]={id=1102,zoneId=1717,name=[[A Vengeful Fate]],name_loc=[[Un destino vengador]],level=27,minLevel=23,giver=[[Auld Stonespire]],giver_loc=[[Auld Picopiedra]],giverType=[[NPC]],giverId=4451,ender=[[Auld Stonespire]],ender_loc=[[Auld Picopiedra]],enderType=[[NPC]],enderId=4451,poiX=-1267,poiY=141,wowhead=[[https://www.wowhead.com/wotlk/quest=1102]],image=[[assets/images/quests/placeholder.png]],desc=[[Cairne is a noble leader for uniting our people here on Thunder Bluff. But I cannot forgive those who drove us from our ancestral lands as easily as some. My people inhabited the southern Barrens for decades. The land was holy to us. But we were driven off by numerous foes. A vengeful fate awaits the crone, Charlga Razorflank, who musters a foul army from within Razorfen Kraul. Bring me Razorflank's heart and I can die in peace, $n.]],logDesc=[[Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.]],choiceRewards={{id=4197,qty=1},{id=6742,qty=1},{id=6725,qty=1}}}
DB[1103]={id=1103,name=[[Call of Water]],name_loc=[[La llamada del agua]],level=-1,minLevel=20,giver=[[Tiev Mordune]],giverType=[[NPC]],giverId=7007,ender=[[Tiev Mordune]],enderType=[[NPC]],enderId=7007,prevId=-100,poiX=430,poiY=1882,wowhead=[[https://www.wowhead.com/wotlk/quest=1103]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetin's, $g brotha:sista;! Have you too come to purify the waters here and prove your understandin' to Islen? I've just defeated the corrupt water spirit meself, and I'm just 'bout to put da bracers and remaining drops o' water on the brazier. What's dat? Ahhh. Tiev understan' all too well when somethin' goes wrong. Well, Tiev can help you plenty if you be needin' to see the pure water spirit again. Bring me a water sapta from Islen as proof that you be ready, an' I'll wait to turn in me parts.]],logDesc=[[Bring a Water Sapta to Tiev Mordune in Silverpine Forest if you failed to speak to the Minor Manifestation of Water.]]}
DB[1104]={id=1104,zoneId=400,name=[[Salt Flat Venom]],name_loc=[[Veneno de El Desierto de Sal]],level=30,minLevel=28,giver=[[Fizzle Brassbolts]],giver_loc=[[Fizzle Pernolatón]],giverType=[[NPC]],giverId=4454,ender=[[Fizzle Brassbolts]],ender_loc=[[Fizzle Pernolatón]],enderType=[[NPC]],enderId=4454,nextId=1106,exGroup=-1104,poiX=-5680,poiY=-4253,wowhead=[[https://www.wowhead.com/wotlk/quest=1104]],image=[[assets/images/quests/placeholder.png]],desc=[[I have so many designs for our rocket car!  So many!  And I must try them all!! I'm working on a new type of fuel.  One that burns really really really hot!!  I haven't gotten the mixture perfect, but I think I know what I need... The scorpids who wander the Shimmering Flats have a venom with lots and lots of salt in it.  It's very unique!  And it's just what I need! Bring me venom and trust me -- our car will fly!!]],logDesc=[[Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats.]]}
DB[1105]={id=1105,zoneId=400,name=[[Hardened Shells]],name_loc=[[Caparazones endurecidos]],level=30,minLevel=28,giver=[[Wizzle Brassbolts]],giver_loc=[[Wizzle Pernolatón]],giverType=[[NPC]],giverId=4453,ender=[[Wizzle Brassbolts]],ender_loc=[[Wizzle Pernolatón]],enderType=[[NPC]],enderId=4453,nextId=1106,exGroup=-1104,poiX=-5783,poiY=-4284,wowhead=[[https://www.wowhead.com/wotlk/quest=1105]],image=[[assets/images/quests/placeholder.png]],desc=[[My brother is working on a new fuel for his rocket car.  He's brilliant, he really is.  So brilliant that... I think that new fuel he's designing is strong enough to eat right through the car's chassis! I want to reinforce its fuel tanks before that happens. The tortoises out on the flats have very hard shells.  I want to use them to create new tanks for our rocket car.  Tanks that can hold my brother's new fuel. You look responsible enough.  Will you get me those shells?]],logDesc=[[Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats.]]}
DB[1106]={id=1106,zoneId=400,name=[[Martek the Exiled]],name_loc=[[Martek el Exiliado]],level=35,minLevel=26,giver=[[Fizzle Brassbolts]],giver_loc=[[Fizzle Pernolatón]],giverType=[[NPC]],giverId=4454,ender=[[Martek the Exiled]],ender_loc=[[Martek el Exiliado]],enderType=[[NPC]],enderId=4618,rewardNextId=1108,poiX=-6763,poiY=-3129,wowhead=[[https://www.wowhead.com/wotlk/quest=1106]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm developing a new engine that'll make the car go so fast!  Fast enough to fly, I know it!  I just need to make pistons that can handle very very heavy stress.  All my trials have failed because I can't make pistons hard enough! But there is someone who might know how. His name is Martek the Exiled.  He is a great smith and knows more about metal than anyone.  Take him this letter, I know he can help! But he's far far away -- in Azeroth, in the Badlands, in a camp, with a goblin! Find him!]],logDesc=[[Bring Fizzle's Letter to Martek the Exiled in the Badlands.]]}
DB[1107]={id=1107,zoneId=400,name=[[Encrusted Tail Fins]],name_loc=[[Aletas dorsales taraceadas]],level=35,minLevel=28,giver=[[Wizzle Brassbolts]],giver_loc=[[Wizzle Pernolatón]],giverType=[[NPC]],giverId=4453,ender=[[Wizzle Brassbolts]],ender_loc=[[Wizzle Pernolatón]],enderType=[[NPC]],enderId=4453,prevId=1105,poiX=-12123,poiY=468,wowhead=[[https://www.wowhead.com/wotlk/quest=1107]],image=[[assets/images/quests/placeholder.png]],desc=[[Our rocket car is the fastest thing on the flats!  So fast that ... I'm afraid friction is going to tear it apart! To prevent that I need to create a composite to coat the car's moving parts.  It must be hard but not brittle, and must be resistant to salt corrosion, or time spent on the Shimmering Flats will eat it away. Have you heard of the Vile Reef, $N?  It's off the coast of Stranglethorn Vale.  Saltscale murlocs live there, and their tail fins are a crucial ingredient of my composite.]],logDesc=[[Bring 10 Encrusted Tail Fins to Wizzle Brassbolts in the Shimmering Flats.]]}
DB[1108]={id=1108,zoneId=400,name=[[Indurium]],name_loc=[[Indurio]],level=39,minLevel=28,giver=[[Martek the Exiled]],giver_loc=[[Martek el Exiliado]],giverType=[[NPC]],giverId=4618,ender=[[Martek the Exiled]],ender_loc=[[Martek el Exiliado]],enderType=[[NPC]],enderId=4618,prevId=1106,poiX=-6634,poiY=-3727,wowhead=[[https://www.wowhead.com/wotlk/quest=1108]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm not out here just to stay away from people.  There is a wealth of metal in the Badlands, $N, if you have the guts to get it. The metal's called indurium and as luck would have it, it is rumored to possess high resistance to heat and stress.  It might work for Fizzle's car. But let's make sure.  Get me samples of indurium and I'll test its properties. True indurium ore lies deep in Uldaman, but the Stonevault troggs of the Badlands sometimes have flakes of it on them.  Bring me those flakes.]],logDesc=[[Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.]]}
DB[1109]={id=1109,zoneId=1717,name=[[Going, Going, Guano!]],name_loc=[[Guano del Horado]],level=26,minLevel=22,giver=[[Master Apothecary Faranell]],giver_loc=[[Maestro boticario Faranell]],giverType=[[NPC]],giverId=2055,ender=[[Master Apothecary Faranell]],ender_loc=[[Maestro boticario Faranell]],enderType=[[NPC]],enderId=2055,rewardNextId=1113,poiX=-4536,poiY=-1839,wowhead=[[https://www.wowhead.com/wotlk/quest=1109]],image=[[assets/images/quests/placeholder.png]],desc=[[As you can see, $n, we're up to some very.... interesting experiments at the Royal Apothecary Society. As the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time! You look well traveled for a $c. Perhaps you can aid me. I'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...]],logDesc=[[Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.]]}
DB[1110]={id=1110,zoneId=400,name=[[Rocket Car Parts]],name_loc=[[Las piezas de coche cohete]],level=31,minLevel=28,giver=[[Kravel Koalbeard]],giver_loc=[[Kravel Karbarbán]],giverType=[[NPC]],giverId=4452,ender=[[Kravel Koalbeard]],ender_loc=[[Kravel Karbarbán]],enderType=[[NPC]],enderId=4452,poiX=-5917,poiY=-4343,wowhead=[[https://www.wowhead.com/wotlk/quest=1110]],image=[[assets/images/quests/placeholder.png]],desc=[[Heh heh, with all the races they're running here, it's no surprise that a few mishaps happen along the way.  If you look around the Shimmering Flats then you'll see evidence of past crashes -- scraps of rocket car parts are littered everywhere! And those parts are worth money to the gnomes and goblins.  They're always looking for more contraptions to slap onto their cars. So go out and get me parts.  Bring me a heap and I'll pay you well.]],logDesc=[[Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats.]]}
DB[1111]={id=1111,zoneId=400,name=[[Wharfmaster Dizzywig]],name_loc=[[Maestro de muelles Vertipeluca]],level=36,minLevel=30,giver=[[Kravel Koalbeard]],giver_loc=[[Kravel Karbarbán]],giverType=[[NPC]],giverId=4452,ender=[[Wharfmaster Dizzywig]],ender_loc=[[Maestro de muelles Vertipeluca]],enderType=[[NPC]],enderId=3453,rewardNextId=1112,poiX=-986,poiY=-3797,wowhead=[[https://www.wowhead.com/wotlk/quest=1111]],image=[[assets/images/quests/placeholder.png]],desc=[[I make it my job to get people what they need, and the gnomes over there need a parts order filled.  Their parts were shipped to Ratchet a week ago, but I haven't been able to make the trip. So, are you ready for some legwork?  Go to Ratchet and give this parts order to Wharfmaster Dizzywig -- he'll probably be at the docks. Do this for me, and I'll have more jobs for you. Jobs, my friend, with serious profit potential...]],logDesc=[[Bring Kravel's Parts Order to Wharfmaster Dizzywig at Ratchet in the Barrens.]]}
DB[1112]={id=1112,zoneId=400,name=[[Parts for Kravel]],name_loc=[[Las piezas de Kravel]],level=36,minLevel=30,giver=[[Wharfmaster Dizzywig]],giver_loc=[[Maestro de muelles Vertipeluca]],giverType=[[NPC]],giverId=3453,ender=[[Kravel Koalbeard]],ender_loc=[[Kravel Karbarbán]],enderType=[[NPC]],enderId=4452,prevId=1111,poiX=-6233,poiY=-3856,wowhead=[[https://www.wowhead.com/wotlk/quest=1112]],image=[[assets/images/quests/placeholder.png]],desc=[[Here's Kravel's package, $N.  And when you deliver it, tell him... if he wants more special orders, then he'll have to pay his tab!]],logDesc=[[Bring Kravel's Parts to Kravel Koalbeard on the Shimmering Flats in Thousand Needles.]]}
DB[1113]={id=1113,zoneId=796,name=[[Hearts of Zeal]],name_loc=[[Corazones de fanatismo]],level=33,minLevel=30,giver=[[Master Apothecary Faranell]],giver_loc=[[Maestro boticario Faranell]],giverType=[[NPC]],giverId=2055,ender=[[Master Apothecary Faranell]],ender_loc=[[Maestro boticario Faranell]],enderType=[[NPC]],enderId=2055,prevId=1109,poiX=1740,poiY=1093,wowhead=[[https://www.wowhead.com/wotlk/quest=1113]],image=[[assets/images/quests/placeholder.png]],desc=[[Why do I need a rare type of guano, you might ask. Well, for this experiment I want to see what effect two diametrically opposed chemical substances can have on each other, especially when both are combined with an ever-toxic agent to ensure the most... ghastly results. In the northeastern peaks of Tirisfal Glades lies the Scarlet Monastery. There the crazed disciples of the Scarlet Crusade congregate, both inside and outside the halls. Which you slay matters not, any of them may have the heart I need.]],logDesc=[[Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.]]}
DB[1114]={id=1114,zoneId=400,name=[[Delivery to the Gnomes]],name_loc=[[Un envío para los gnomos]],level=36,minLevel=30,giver=[[Kravel Koalbeard]],giver_loc=[[Kravel Karbarbán]],giverType=[[NPC]],giverId=4452,ender=[[Fizzle Brassbolts]],ender_loc=[[Fizzle Pernolatón]],enderType=[[NPC]],enderId=4454,prevId=1112,poiX=-6229,poiY=-3868,wowhead=[[https://www.wowhead.com/wotlk/quest=1114]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that I have what I need, give these parts to Fizzle Brassbolts.  He's been waiting a long time for them -- I'm sure he won't miss the little piece I removed from his order... And I wouldn't bother mentioning it to him.  It was small and worthless. Trust me.]],logDesc=[[Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats.]]}
DB[1115]={id=1115,zoneId=400,name=[[The Rumormonger]],name_loc=[[Rumores]],level=36,minLevel=30,giver=[[Kravel Koalbeard]],giver_loc=[[Kravel Karbarbán]],giverType=[[NPC]],giverId=4452,ender=[[Krazek]],enderType=[[NPC]],enderId=773,prevId=1114,rewardNextId=1116,poiX=-14453,poiY=501,wowhead=[[https://www.wowhead.com/wotlk/quest=1115]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we've done a service for the gnomes, it's time to do the goblins a favor!   I hear that the goblin racer pilot, Nazz Steamboil, didn't always use that name.  I wonder why he changed it.  I wonder if it's a secret, and... I wonder if he values that secret. If anyone knows the truth, then it's Krazek of Booty Bay, on the southern tip of Stranglethorn.  Speak with Krazek and ask him about our goblin pilot. If you can get useful information from him, then we might just turn a profit from it.]],logDesc=[[Talk to Krazek at Booty Bay in Stranglethorn Vale.]]}
DB[1116]={id=1116,zoneId=8,name=[[Dream Dust in the Swamp]],name_loc=[[Polvo onírico en el pantano]],level=36,minLevel=30,giver=[[Krazek]],giverType=[[NPC]],giverId=773,ender=[[Krazek]],enderType=[[NPC]],enderId=773,prevId=1115,rewardNextId=1117,poiX=-14453,poiY=501,wowhead=[[https://www.wowhead.com/wotlk/quest=1116]],image=[[assets/images/quests/placeholder.png]],desc=[[Getting the information on Nazz is quite a favor, $N.  Yes, quite a favor.  But you've come all the way from the Shimmering Flats to get it... are you willing to travel some more? While I contact my sources, why don't you gather something for me, eh? Hm... what will it be?  How about dream dust, from the dragon whelps of the Swamp of Sorrows.  Yes, I'd love some dream dust for my snuff pouch! Get it for me, $N, and I'll give you the information you seek.]],logDesc=[[Bring 10 Specks of Dream Dust to Krazek in Booty Bay.  Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.]]}
DB[1117]={id=1117,zoneId=400,name=[[Rumors for Kravel]],name_loc=[[Rumores para Kravel]],level=36,minLevel=30,giver=[[Krazek]],giverType=[[NPC]],giverId=773,ender=[[Kravel Koalbeard]],ender_loc=[[Kravel Karbarbán]],enderType=[[NPC]],enderId=4452,prevId=1116,poiX=-6233,poiY=-3856,wowhead=[[https://www.wowhead.com/wotlk/quest=1117]],image=[[assets/images/quests/placeholder.png]],desc=[[I had to use some of my favors, and gave away a rare bottle of elven wine, and did some heavy deducing myself!  But I found the information you seek. Here, I wrote a letter with some very interesting bits on our friend, Nazz Steamboil.  Do with it what you will -- it's too dangerous for me to use. Just don't tell anyone where you got it!]],logDesc=[[Bring the Goblin Rumors to Kravel Koalbeard on the Shimmering Flats in Thousand Needles.]]}
DB[1118]={id=1118,zoneId=400,name=[[Back to Booty Bay]],name_loc=[[De vuelta a Bahía del Botín]],level=43,minLevel=35,giver=[[Kravel Koalbeard]],giver_loc=[[Kravel Karbarbán]],giverType=[[NPC]],giverId=4452,ender=[[Crank Fizzlebub]],ender_loc=[[Loquillo Pinchabujas]],enderType=[[NPC]],enderId=2498,prevId=1117,nextId=1119,exGroup=-621,poiX=-14453,poiY=490,wowhead=[[https://www.wowhead.com/wotlk/quest=1118]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you're a $c I can trust, both to get the job done and to keep your mouth shut while doing it. I've been brewing up a new scheme.  It's risky, but if it works then we could both make a bundle!  And I think you're just the person to see it through. To start, you must go back to Booty Bay.  I apologize, good $N.  I know my last task took you there.  But this time, speak with Crank Fizzlebub. Give him this letter.  And if he requires aid, do your best to help him.  It will be worth the effort.]],logDesc=[[Bring Kravel's Scheme to Crank Fizzlebub at Booty Bay in Stranglethorn Vale.]]}
DB[1119]={id=1119,zoneId=400,name=[[Zanzil's Mixture and a Fool's Stout]],name_loc=[[La mezcla de Zanzil y la cerveza de tontos]],level=44,minLevel=35,giver=[[Crank Fizzlebub]],giver_loc=[[Loquillo Pinchabujas]],giverType=[[NPC]],giverId=2498,ender=[[Kravel Koalbeard]],ender_loc=[[Kravel Karbarbán]],enderType=[[NPC]],enderId=4452,poiX=-6233,poiY=-3856,wowhead=[[https://www.wowhead.com/wotlk/quest=1119]],image=[[assets/images/quests/placeholder.png]],desc=[[I figured out how to use Zanzil's mixture with stout to make a powerful libation.  A Fool's Stout.  I think it'll be just what Kravel needs, but try it out and let me know how it works. And $N, don't keep this stuff too long without using it.  Zanzil's mixture has a weird effect on the stout's yeast, kicking it into high gear.  So it won't stay fresh forever.]],logDesc=[[Bring the Fool's Stout back to Kravel on the Shimmering Flats in Thousand Needles.]]}
DB[1120]={id=1120,zoneId=400,name=[[Get the Gnomes Drunk]],name_loc=[[Emborrachar a los gnomos]],level=44,minLevel=35,giver=[[Kravel Koalbeard]],giver_loc=[[Kravel Karbarbán]],giverType=[[NPC]],giverId=4452,ender=[[Gnome Pit Boss]],ender_loc=[[Encargado de foso gnomo]],enderType=[[NPC]],enderId=4495,prevId=1119,nextId=1122,exGroup=1120,poiX=-6224,poiY=-3846,wowhead=[[https://www.wowhead.com/wotlk/quest=1120]],image=[[assets/images/quests/placeholder.png]],desc=[[We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the gnomes, then here -- take the stout and give it to the gnome pit boss. And don't wait too long.  This stout will go bad eventually.]],logDesc=[[Bring the Fool's Stout to the Gnome Pit Boss at Mirage Raceway in Thousand Needles.]]}
DB[1121]={id=1121,zoneId=400,name=[[Get the Goblins Drunk]],name_loc=[[Emborrachar a los goblins]],level=44,minLevel=35,giver=[[Kravel Koalbeard]],giver_loc=[[Kravel Karbarbán]],giverType=[[NPC]],giverId=4452,ender=[[Goblin Pit Boss]],ender_loc=[[Encargado de foso goblin]],enderType=[[NPC]],enderId=4496,prevId=1119,nextId=1122,exGroup=1120,poiX=-6218,poiY=-3949,wowhead=[[https://www.wowhead.com/wotlk/quest=1121]],image=[[assets/images/quests/placeholder.png]],desc=[[We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the goblins, then here -- take the stout and give it to the goblin pit boss. And don't wait too long.  This stout will go bad eventually.]],logDesc=[[Bring the Fool's Stout to the Goblin Pit Boss at Mirage Raceway in Thousand Needles.]]}
DB[1122]={id=1122,zoneId=400,name=[[Report Back to Fizzlebub]],name_loc=[[Volver a informar a Pinchabujas]],level=44,minLevel=35,giver=[[Kravel Koalbeard]],giver_loc=[[Kravel Karbarbán]],giverType=[[NPC]],giverId=4452,ender=[[Crank Fizzlebub]],ender_loc=[[Loquillo Pinchabujas]],enderType=[[NPC]],enderId=2498,poiX=-14453,poiY=490,wowhead=[[https://www.wowhead.com/wotlk/quest=1122]],image=[[assets/images/quests/placeholder.png]],desc=[[That Fool's Stout worked great!  I placed a bet on the next race, and... let's hope the crew you got drunk did a number on their car! There's only one more task for you -- take this note back to Crank Fizzlebub in Booty Bay.  He'll want to know of the successful test. And hopefully we can get more of that Fool's Stout for future races!]],logDesc=[[Bring the Fool's Stout report to Crank Fizzlebub at Booty Bay in Stranglethorn Vale.]]}
DB[1123]={id=1123,zoneId=1638,name=[[Rabine Saturna]],name_loc=[[Rabine Saturna]],level=55,minLevel=54,giver=[[Arch Druid Hamuul Runetotem]],giver_loc=[[Archidruida Hamuul Tótem de Runa]],giverType=[[NPC]],giverId=5769,ender=[[Rabine Saturna]],enderType=[[NPC]],enderId=11801,nextId=1124,rewardNextId=1124,poiX=7797,poiY=-2574,wowhead=[[https://www.wowhead.com/wotlk/quest=1123]],image=[[assets/images/quests/placeholder.png]],desc=[[For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris and Un'Goro.  He is located in Nighthaven, the main village of Moonglade. I want to impart on you the importance of your presence.  There are growing tensions between the night elves of Darnassus and the Cenarion Circle in Moonglade.  Look beyond racial boundaries and tap into the wisdom of your ancestors in dealings with the Circle there, $N.  Good luck.]],logDesc=[[Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.]]}
DB[1124]={id=1124,zoneId=493,name=[[Wasteland]],name_loc=[[Páramo]],level=55,minLevel=54,giver=[[Rabine Saturna]],giverType=[[NPC]],giverId=11801,ender=[[Layo Starstrike]],ender_loc=[[Layo Estrella]],enderType=[[NPC]],enderId=13220,rewardNextId=1125,poiX=-6398,poiY=-314,wowhead=[[https://www.wowhead.com/wotlk/quest=1124]],image=[[assets/images/quests/placeholder.png]],desc=[[West of Un'Goro Crater, via the northwestern ridge, is a harsh wasteland - Silithus.  Few know that an ancient war was waged there between the night elves and a malign, alien power.  The evil was sealed, but now we suspect that forces work to stir this... unspeakable horror. Seek out Layo Starstrike, one of our agents in Silithus; look for him at Valor's Rest, the final resting spot for the fallen of the wastes.  Give him this letter, and he will give you his trust accordingly.]],logDesc=[[Speak with Layo Starstrike near the Valor's Rest graveyard of Silithus, showing him Rabine's Letter.]]}
DB[1125]={id=1125,zoneId=1377,name=[[The Spirits of Southwind]],name_loc=[[Los espíritus de Viento del Sur]],level=55,minLevel=54,giver=[[Layo Starstrike]],giver_loc=[[Layo Estrella]],giverType=[[NPC]],giverId=13220,ender=[[Layo Starstrike]],ender_loc=[[Layo Estrella]],enderType=[[NPC]],enderId=13220,prevId=1124,rewardNextId=1126,poiX=-7113,poiY=240,wowhead=[[https://www.wowhead.com/wotlk/quest=1125]],image=[[assets/images/quests/placeholder.png]],desc=[[To our southwest lies a tragic site - the ruins of Southwind Village.  This is where our work should begin, $N. From what we've learned, this village was once a night elf base of operations for Silithus.  It's long since overrun by the silithid hives that infest the wastes.  I can only imagine the horror of the village's initial sundering... The tortured spirits of fallen druids and sentinels wander the ruins aimlessly.  Explore this locale, freeing the souls of these wretched beings as needed.]],logDesc=[[Free the spirits of 8 Tortured Druids and 8 Tortured Sentinels in Southwind Village, and then return to Layo Starstrike at the Valor's Rest graveyard of Silithus.]]}
DB[1126]={id=1126,zoneId=1377,name=[[Hive in the Tower]],name_loc=[[Una colmena en la torre]],level=57,minLevel=54,giver=[[Layo Starstrike]],giver_loc=[[Layo Estrella]],giverType=[[NPC]],giverId=13220,ender=[[Layo Starstrike]],ender_loc=[[Layo Estrella]],enderType=[[NPC]],enderId=13220,prevId=1125,rewardNextId=6844,poiX=-7179,poiY=435,wowhead=[[https://www.wowhead.com/wotlk/quest=1126]],image=[[assets/images/quests/placeholder.png]],desc=[[The hive needs to be addressed in Southwind Village, and I think I know a way to get at them.  It's been my experience that the silithid hives are very sensitive to their environment; this explains their attacks when hearing the death wails of the spirits. The silithid are strongest in the tower - the one with the mass of wasps circling it.  Scale the tower and jostle the hive into activity.  Report back what you learn, but be careful!  If you uncover anything that might help, bring it to me.]],logDesc=[[Scale the tower of Southwind Village and locate a means to stir the silithid hive into activity.  Bring back anything unusual you may uncover when doing so to Layo Starstrike at the Valor's Rest graveyard of Silithus.]]}
DB[1127]={id=1127,zoneId=33,name=[[Fool's Stout]],name_loc=[[Cerveza de tontos]],level=44,minLevel=35,giver=[[Crank Fizzlebub]],giver_loc=[[Loquillo Pinchabujas]],giverType=[[NPC]],giverId=2498,ender=[[Crank Fizzlebub]],ender_loc=[[Loquillo Pinchabujas]],enderType=[[NPC]],enderId=2498,prevId=1122,poiX=-13573,poiY=-441,wowhead=[[https://www.wowhead.com/wotlk/quest=1127]],image=[[assets/images/quests/placeholder.png]],desc=[[So you want some Fool's Stout, eh?  Thinking of heading back to the races...? All right, bring me more of Zanzil's mixture and I'll make some more stout for you.]],logDesc=[[Bring 12 of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.]],rewards={{id=5806,qty=1}}}
DB[1130]={id=1130,zoneId=1638,name=[[Melor Sends Word]],name_loc=[[Melor manda saludos]],level=30,minLevel=20,giver=[[Jorn Skyseer]],giver_loc=[[Jorn Vidente del Cielo]],giverType=[[NPC]],giverId=3387,ender=[[Melor Stonehoof]],ender_loc=[[Melor Pezuña Pétrea]],enderType=[[NPC]],enderId=3441,rewardNextId=1131,poiX=-1413,poiY=-126,wowhead=[[https://www.wowhead.com/wotlk/quest=1130]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, Melor Stonehoof has heard of your deeds, and has set a path before you. If you wish to take it, then go to Thunder Bluff and speak with Melor.  You will find him on Hunter's Rise.]],logDesc=[[Speak with Melor Stonehoof in Thunder Bluff.]]}
DB[1131]={id=1131,zoneId=1638,name=[[Steelsnap]],name_loc=[[Metaleador]],level=30,minLevel=20,giver=[[Melor Stonehoof]],giver_loc=[[Melor Pezuña Pétrea]],giverType=[[NPC]],giverId=3441,ender=[[Melor Stonehoof]],ender_loc=[[Melor Pezuña Pétrea]],enderType=[[NPC]],enderId=3441,prevId=1130,poiX=-1413,poiY=-126,wowhead=[[https://www.wowhead.com/wotlk/quest=1131]],image=[[assets/images/quests/placeholder.png]],desc=[[At times we hunt for food.  At times we hunt for honor.  And at times we hunt to earn the Earthmother's teachings. But the hunt I now set upon you is none of these things.  It is to slay a creature outside the Earthmother's blessing. The hyena Steelsnap roams the Thousand Needles, south of the Barrens.  He is a tyrant, attracting other hyenas to him and spreading fear and bloodshed among more peaceful beasts. Find Steelsnap, $N.  Find him, and defeat him.]],logDesc=[[Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff.]]}
DB[1132]={id=1132,zoneId=11,name=[[Fiora Longears]],name_loc=[[Fiora Orejona]],level=20,minLevel=18,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=1133,poiX=6483,poiY=730,wowhead=[[https://www.wowhead.com/wotlk/quest=1132]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, to be at sea once again!  To feel the kiss of the wind, and to have the waves rock me like my blessed mother, long ago! Oh, I wish I had your fortune, good $c, for I see the sea in your future! It's my job to tell eager souls of the land of Kalimdor, the land of opportunity!  If you're willing to try your luck across the sea, then take a ship from here to the lovely port of Auberdine.  Speak there with my partner, the elf, Fiora Longears. She'll start you on your Kalimdor adventure!]],logDesc=[[Speak with Fiora Longears on the docks at Auberdine in Darkshore.]]}
DB[1133]={id=1133,zoneId=148,name=[[Journey to Astranaar]],name_loc=[[Viaje a Astranaar]],level=20,minLevel=18,giverType=[[NPC]],enderType=[[NPC]],prevId=1132,poiX=2796,poiY=-299,wowhead=[[https://www.wowhead.com/wotlk/quest=1133]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, go to Astranaar.  I'm sure an eager member of the Alliance such as you can do some real good there.  Speak with Shindrell Swiftfire and offer your services. But don't bother mentioning who sent you.  Shindrell does not know me...]],logDesc=[[Speak with Shindrell Swiftfire in Astranaar.]]}
DB[1134]={id=1134,zoneId=331,name=[[Pridewings of Stonetalon]],name_loc=[[Alaorgullo del Espolón]],level=21,minLevel=18,giver=[[Shindrell Swiftfire]],giver_loc=[[Shindrell Fuegoveloz]],giverType=[[NPC]],giverId=3845,ender=[[Shindrell Swiftfire]],ender_loc=[[Shindrell Fuegoveloz]],enderType=[[NPC]],enderId=3845,prevId=1008,poiX=2796,poiY=-299,wowhead=[[https://www.wowhead.com/wotlk/quest=1134]],image=[[assets/images/quests/placeholder.png]],desc=[[We are not in open war with the Horde, but our peace is fragile.  We often find their agents moving against us, but they do so covertly. One such advance was revealed to us from hidden sources in Theramore, claiming that the orcs collect venom from the pridewings near Mirkfallon Lake, in the Stonetalon Mountains to the south.  Orc assassins then use the venom on their secret death raids against the Alliance! If this is true, then we must stop them, $N.  We must deny them their source of venom.]],logDesc=[[Bring 12 Pridewing Venom Sacs to Shindrell Swiftfire in Astranaar.]]}
DB[1135]={id=1135,zoneId=15,name=[[Highperch Venom]],name_loc=[[Veneno de Nido Alto]],level=30,minLevel=25,giverType=[[NPC]],enderType=[[NPC]],poiX=6483,poiY=730,wowhead=[[https://www.wowhead.com/wotlk/quest=1135]],image=[[assets/images/quests/placeholder.png]],desc=[[As you may know, wyverns are often tamed by orcs for use as mounts.  But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself.  So if you're not afraid to do a little wyvern hunting, then... I have a job for you. There is a place called Highperch in the land of a Thousand Needles, west of here.  The Highperch wyverns have a potent venom.  Potent, and valuable.]],logDesc=[[Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore.]],rewards={{id=6719,qty=1}}}
DB[1136]={id=1136,zoneId=1638,name=[[Frostmaw]],name_loc=[[Faucehielo]],level=37,minLevel=26,giver=[[Melor Stonehoof]],giver_loc=[[Melor Pezuña Pétrea]],giverType=[[NPC]],giverId=3441,ender=[[Melor Stonehoof]],ender_loc=[[Melor Pezuña Pétrea]],enderType=[[NPC]],enderId=3441,prevId=1131,poiX=-1413,poiY=-126,wowhead=[[https://www.wowhead.com/wotlk/quest=1136]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, it is now time for you to travel to far-off lands.  You are ready. You now hunt Frostmaw, a yeti in the Alterac Mountains.  He is elusive, his white coat blending into the snows of his mountain home.  He rarely shows himself. But I will show you how to entice a creature such as he.  Here, take this scroll.  On it I have written how Frostmaw may be lured. Now go, $N.  Your journey is long and many challenges lay waiting.  When you return with Frostmaw's mane, only then is your task complete.]],logDesc=[[Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff.]],rewards={{id=6720,qty=1}}}
DB[1137]={id=1137,zoneId=400,name=[[News for Fizzle]],name_loc=[[Noticias para Fizzle]],level=38,minLevel=28,giver=[[Martek the Exiled]],giver_loc=[[Martek el Exiliado]],giverType=[[NPC]],giverId=4618,ender=[[Fizzle Brassbolts]],ender_loc=[[Fizzle Pernolatón]],enderType=[[NPC]],enderId=4454,prevId=1108,poiX=-6229,poiY=-3868,wowhead=[[https://www.wowhead.com/wotlk/quest=1137]],image=[[assets/images/quests/placeholder.png]],desc=[[Indurium has an amazing resistance to heat!  I'm sure it will work for Fizzle's pistons.  But he'll need true indurium ore, not just the flakes. To get the ore, it must be mined from deep within Uldaman, on the northern borders of the Badlands.  That is the true source of indurium. Send Fizzle Brassbolts my regards, and tell him what I told you. Safe travels, $N.  And it won't surprise me if we meet again -- once Fizzle learns of indurium he'll probably send you to Uldaman to acquire it!]],logDesc=[[Speak with Fizzle Brassbolts on the Shimmering Flats in Thousand Needles.]],choiceRewards={{id=6729,qty=1},{id=6732,qty=1}}}
DB[1138]={id=1138,zoneId=148,name=[[Fruit of the Sea]],name_loc=[[Rico marisco]],level=17,minLevel=15,giver=[[Gubber Blump]],giverType=[[NPC]],giverId=10216,ender=[[Gubber Blump]],enderType=[[NPC]],enderId=10216,poiX=7519,poiY=-615,wowhead=[[https://www.wowhead.com/wotlk/quest=1138]],image=[[assets/images/quests/placeholder.png]],desc=[[I love crab.  Crabs are the fruit of the sea!  You can bake it, barbecue it, boil it, and broil it.  They're pan fried, deep fried, and stir fried.  There's crab salad, crab soup, crab stew, pepper crab, lemon crab, whipper root crab, and Ironforge surprise crab.  That's... that's about it. I'm here fishing right now, so I can't get any fine crab chunks.  You can pick them out of reef crawlers and encrusted tide crawlers.  You can make a lot with it.  You can bake it, barbecue it, boil it...]],logDesc=[[Collect 6 Fine Crab Chunks for Gubber Blump in Auberdine.]],choiceRewards={{id=15405,qty=1},{id=15406,qty=1}}}
DB[1139]={id=1139,zoneId=1517,name=[[The Lost Tablets of Will]],name_loc=[[Las tablillas perdidas de Voluntad]],level=45,minLevel=35,giver=[[Advisor Belgrum]],giver_loc=[[Consejero Belgrum]],giverType=[[NPC]],giverId=2918,ender=[[Advisor Belgrum]],ender_loc=[[Consejero Belgrum]],enderType=[[NPC]],enderId=2918,prevId=762,poiX=-4620,poiY=-1325,wowhead=[[https://www.wowhead.com/wotlk/quest=1139]],image=[[assets/images/quests/placeholder.png]],desc=[[We've slowed the Shadowforge clan by cutting them off from Blackrock Spire, but Hammertoe's quest is still unfulfilled. His death must not be in vain. He dreamt of finding the Tablet of Will: a stone shard inscribed with magic by the titans themselves to help imbue their creations with life--making them have a will of their own, or so the legends say. We must still recover the Tablet before the Shadowforge clan finds it. Return to Uldaman, find the tablet, and return here immediately.]],logDesc=[[Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.]],rewards={{id=6723,qty=1}}}
DB[1140]={id=1140,zoneId=148,name=[[The Tower of Althalaxx]],name_loc=[[La Torre de Althalaxx]],level=28,minLevel=13,giver=[[Delgren the Purifier]],giver_loc=[[Delgren el Purificador]],giverType=[[NPC]],giverId=3663,ender=[[Delgren the Purifier]],ender_loc=[[Delgren el Purificador]],enderType=[[NPC]],enderId=3663,prevId=973,rewardNextId=1167,poiX=2482,poiY=-2142,wowhead=[[https://www.wowhead.com/wotlk/quest=1140]],image=[[assets/images/quests/placeholder.png]],desc=[[The writing of the orcs is little better than the scribblings of a child. Many of my order scoffed when I chose to learn their tongue, but I have found it beneficial to gain further understanding of my enemies. From Ilkrud's scribblings, it appears that Athrikus still possesses two soulgems, and they are being held in Night Run and Satyrnaar, satyr-held areas in northeast Ashenvale. Be careful out there, $n, the satyrs' blood-soaked temples can be unsettling even for a seasoned $c such as yourself.]],logDesc=[[Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post.]]}
DB[1141]={id=1141,zoneId=148,name=[[The Family and the Fishing Pole]],name_loc=[[La familia y la caña de pescar]],level=14,minLevel=10,giver=[[Gubber Blump]],giverType=[[NPC]],giverId=10216,ender=[[Gubber Blump]],enderType=[[NPC]],enderId=10216,poiX=6371,poiY=577,wowhead=[[https://www.wowhead.com/wotlk/quest=1141]],image=[[assets/images/quests/placeholder.png]],desc=[[I love fishing.  The Blump family is known for fishing.  My name is Gubber Blump; I fish. There's a kind of fish I like to catch around these parts called Darkshore grouper.  I used to go out on a boat to fish for grouper, but no boats have been going out since them mean ol' murlocs moved in.  I bet they been eating up all the grouper too. Say, you wanna help me catch Darkshore grouper?  I'd give you a bona fide Blump Family Fishing Pole if you did!  It's a real good pole to catch fish with.]],logDesc=[[Catch 6 Darkshore Grouper for Gubber Blump in Auberdine.]],rewards={{id=12225,qty=1}}}
DB[1142]={id=1142,zoneId=1717,name=[[Mortality Wanes]],name_loc=[[Decaída mortal]],level=30,minLevel=25,giver=[[Heralath Fallowbrook]],giver_loc=[[Heralath Arroyobarbecho]],giverType=[[NPC]],giverId=4510,ender=[[Treshala Fallowbrook]],ender_loc=[[Treshala Arroyobarbecho]],enderType=[[NPC]],enderId=4521,poiX=9760,poiY=2202,wowhead=[[https://www.wowhead.com/wotlk/quest=1142]],image=[[assets/images/quests/placeholder.png]],desc=[[I have not long to live... so... so... weak. ...the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel... But before I... d-d-die... ...my wife, Treshala... her pendant of bonding to me... stolen... by one of the f-f-foul aggressors... Find it p-p-please... and return it to Treshala in Darnassus... ...along with w-w-word of my lonely... death.]],logDesc=[[Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.]],choiceRewards={{id=6751,qty=1},{id=6752,qty=1}}}
DB[1143]={id=1143,zoneId=148,name=[[The Tower of Althalaxx]],name_loc=[[La Torre de Althalaxx]],level=31,minLevel=13,giver=[[Balthule Shadowstrike]],giver_loc=[[Balthule Golpesombra]],giverType=[[NPC]],giverId=3661,ender=[[Balthule Shadowstrike]],ender_loc=[[Balthule Golpesombra]],enderType=[[NPC]],enderId=3661,prevId=1167,rewardNextId=981,poiX=7183,poiY=-728,wowhead=[[https://www.wowhead.com/wotlk/quest=1143]],image=[[assets/images/quests/placeholder.png]],desc=[[I see. Well, if what you say is true, then now is the time to strike. I believe Athrikus resides at the top of the tower. Be careful though, he is surrounded by many powerful warlocks, much more deadly than the ones you faced before.]],logDesc=[[Kill Athrikus Narassin and bring his head to Balthule Shadowstrike near the Tower of Althalaxx.]]}
DB[1144]={id=1144,zoneId=1717,name=[[Willix the Importer]],name_loc=[[Willix el Importador]],level=30,minLevel=22,giver=[[Willix the Importer]],giver_loc=[[Willix el Importador]],giverType=[[NPC]],giverId=4508,ender=[[Willix the Importer]],ender_loc=[[Willix el Importador]],enderType=[[NPC]],enderId=4508,wowhead=[[https://www.wowhead.com/wotlk/quest=1144]],image=[[assets/images/quests/placeholder.png]],desc=[[At last, help has arrived! You have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place. You see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that Mebok Mizzyrix was paying well for Blueleaf Tuber from this here pig pen. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong! Anyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.]],logDesc=[[Escort Willix the Importer to the exit of Razorfen Kraul.]],choiceRewards={{id=6748,qty=1},{id=6750,qty=1},{id=6749,qty=1}}}
DB[1145]={id=1145,zoneId=17,name=[[The Swarm Grows]],name_loc=[[El enjambre crece]],level=33,minLevel=29,giver=[[Korran]],giverType=[[NPC]],giverId=3428,ender=[[Belgrom Rockmaul]],ender_loc=[[Belgrom Destrozarroca]],enderType=[[NPC]],enderId=4485,rewardNextId=1146,poiX=1954,poiY=-4736,wowhead=[[https://www.wowhead.com/wotlk/quest=1145]],image=[[assets/images/quests/placeholder.png]],desc=[[Many travelers who've come through the Crossroads helped me gather eggs from the Field of Giants, and many of them have tales of how deadly the creatures are. I've heard enough to consider them insects a much larger threat than my masters first thought. I need a courier to travel to Orgrimmar to meet Belgrom Rockmaul. It be no simple matter, and someone who would take the task seriously should go. Belgrom usually be found outside the warriors' guild house.]],logDesc=[[Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar.]]}
DB[1146]={id=1146,zoneId=1637,name=[[The Swarm Grows]],name_loc=[[El enjambre crece]],level=33,minLevel=29,giver=[[Belgrom Rockmaul]],giver_loc=[[Belgrom Destrozarroca]],giverType=[[NPC]],giverId=4485,ender=[[Moktar Krin]],enderType=[[NPC]],enderId=4483,prevId=1145,rewardNextId=1147,poiX=-5842,poiY=-3407,wowhead=[[https://www.wowhead.com/wotlk/quest=1146]],image=[[assets/images/quests/placeholder.png]],desc=[[So, Korran has come to a similar conclusion about these insects--they seem to be a larger threat than we assumed. A few days ago a hunter returned to me from Thousand Needles nearly dead. He was with a raiding party sent to drive a dwarven excavation team out of the Shimmering Flats. During the attack, more of these insects erupted from a cave in the dig site and nearly killed the party. They were led by Moktar Krin, and they've taken refuge on the border of the Shimmering Flats. Bring him this note.]],logDesc=[[Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles.]]}
DB[1147]={id=1147,zoneId=400,name=[[The Swarm Grows]],name_loc=[[El enjambre crece]],level=35,minLevel=29,giver=[[Moktar Krin]],giverType=[[NPC]],giverId=4483,ender=[[Moktar Krin]],enderType=[[NPC]],enderId=4483,prevId=1146,poiX=-6484,poiY=-3586,wowhead=[[https://www.wowhead.com/wotlk/quest=1147]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmm. Seems Belgrom thinks those monsters are a threat. He wants them pushed back into whatever depths they crawled up out of. I guess killing the dwarves sent by the Explorers' League wasn't enough--now I have to send a half-dead war party into another battle. We won't be able to do it ourselves; not while we're in this condition. The dig site's to the south of here. There shouldn't be anymore dwarves to deal with. Feel up to wielding a blade or staff and doing your part to aid us?]],logDesc=[[Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles.]]}
DB[1148]={id=1148,zoneId=400,name=[[Parts of the Swarm]],name_loc=[[Pedazos del enjambre]],level=35,minLevel=28,giverType=[[NPC]],ender=[[Korran]],enderType=[[NPC]],enderId=3428,rewardNextId=1184,poiX=-389,poiY=-2552,wowhead=[[https://www.wowhead.com/wotlk/quest=1148]],image=[[assets/images/quests/placeholder.png]],desc=[[You inspect the carapace carefully. As you turn it over in your hands you realize that the chitinous plating is interlaced in such a way that makes it incredibly strong. It's unlike anything you've ever seen. You inspect the rest of the corpse further and realize that these creatures are very powerful and highly evolved. Looking down at the carapace again, you think that Korran would enjoy studying more of these creatures. It could help him figure out what these creatures are, and where they come from.]],logDesc=[[Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.]]}
DB[1149]={id=1149,zoneId=400,name=[[Test of Faith]],name_loc=[[Prueba de fe]],level=26,minLevel=25,giver=[[Dorn Plainstalker]],giver_loc=[[Dorn Acechallanos]],giverType=[[NPC]],giverId=2986,ender=[[Dorn Plainstalker]],ender_loc=[[Dorn Acechallanos]],enderType=[[NPC]],enderId=2986,rewardNextId=1150,poiX=-4933,poiY=-1642,wowhead=[[https://www.wowhead.com/wotlk/quest=1149]],image=[[assets/images/quests/placeholder.png]],desc=[[So, you have sought me out, or perhaps destiny brings you to me? No matter. You are here now, and so your journey will begin anew. Many facets make up a being: the spirit, the body, the mind. Some of these can be measured by a culture's traditions. Others we can only hope exist within ourselves. If you agree, I shall test some of the facets within you. If you pass, then you shall become stronger. If you fail, then you will realize the vastness of the Nether. The first is a Test of Faith.]],logDesc=[[If you have faith, leap from the planks overlooking Thousand Needles.]]}
DB[1150]={id=1150,zoneId=400,name=[[Test of Endurance]],name_loc=[[Prueba de resistencia]],level=30,minLevel=25,giver=[[Dorn Plainstalker]],giver_loc=[[Dorn Acechallanos]],giverType=[[NPC]],giverId=2986,ender=[[Dorn Plainstalker]],ender_loc=[[Dorn Acechallanos]],enderType=[[NPC]],enderId=2986,prevId=1149,rewardNextId=1151,poiX=-5583,poiY=-1626,wowhead=[[https://www.wowhead.com/wotlk/quest=1150]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm pleased to see your courage remains steadfast in light of what you've already done. Since your faith is intact, the time has come to test your body. First is a test of endurance. Go to the Roguefeather Den west of Freewind Post. Make your way to the depths of their lair and destroy their foodstuffs. By then you should have provoked their fury, and if you are able to survive long enough, Grenka Bloodscreech herself will come for you--kill her and bring me her claw to complete your test.]],logDesc=[[Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.]]}
DB[1151]={id=1151,zoneId=400,name=[[Test of Strength]],name_loc=[[Prueba de fuerza]],level=30,minLevel=25,giver=[[Dorn Plainstalker]],giver_loc=[[Dorn Acechallanos]],giverType=[[NPC]],giverId=2986,ender=[[Dorn Plainstalker]],ender_loc=[[Dorn Acechallanos]],enderType=[[NPC]],enderId=2986,prevId=1150,rewardNextId=1152,poiX=-4619,poiY=-913,wowhead=[[https://www.wowhead.com/wotlk/quest=1151]],image=[[assets/images/quests/placeholder.png]],desc=[[During the time of the Old Gods, elementals inhabited much of this world. They worshipped the Old Gods, and the Gods, through their power, kept the elementals bound to this world. When the Old Gods were banished, the elementals faded from our world and now only return at the bidding of powerful mages. There are exceptions though. Some elementals were powerful enough to remain here on their own. One such elemental is Rok'Alim. To test your strength, find Rok'Alim in Thousand Needles and slay him.]],logDesc=[[Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.]]}
DB[1152]={id=1152,zoneId=400,name=[[Test of Lore]],name_loc=[[Prueba de conocimiento]],level=30,minLevel=25,giver=[[Dorn Plainstalker]],giver_loc=[[Dorn Acechallanos]],giverType=[[NPC]],giverId=2986,ender=[[Braug Dimspirit]],ender_loc=[[Braug Espiritoscuro]],enderType=[[NPC]],enderId=4489,prevId=1151,rewardNextId=1154,poiX=1429,poiY=-602,wowhead=[[https://www.wowhead.com/wotlk/quest=1152]],image=[[assets/images/quests/placeholder.png]],desc=[[Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over. If you are prepared, then seek out Braug Dimspirit--he is a shaman of great wisdom. He will test you further, so heed his words, $N. When you are ready, find the tunnel that connects the Stonetalon Mountains with Ashenvale: Braug dwells near there. And be careful, $N, the night elves may wish to impede your test.]],logDesc=[[Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.]]}
DB[1153]={id=1153,zoneId=17,name=[[A New Ore Sample]],name_loc=[[Una nueva muestra de mineral]],level=29,minLevel=25,giver=[[Tatternack Steelforge]],giver_loc=[[Jironack Forjacero]],giverType=[[NPC]],giverId=3433,ender=[[Tatternack Steelforge]],ender_loc=[[Jironack Forjacero]],enderType=[[NPC]],enderId=3433,prevId=893,poiX=-2285,poiY=-1947,wowhead=[[https://www.wowhead.com/wotlk/quest=1153]],image=[[assets/images/quests/placeholder.png]],desc=[[$C, you have done well in helping me in the past. The warchief is pleased thus far with what I've accomplished, and asks me to continue with renewed determination. My honor dictates that I give you proper recognition to the warchief for all you have done, but first I would ask you for your help again. Travelers recently came from the south from a place called Thousand Needles. There they killed a kobold who had an unusual ore sample, but they would not sell it. I want a sample of that ore to examine.]],logDesc=[[Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens.]],rewards={{id=6741,qty=1}}}
DB[1154]={id=1154,zoneId=400,name=[[Test of Lore]],name_loc=[[Prueba de conocimiento]],level=30,minLevel=25,giver=[[Braug Dimspirit]],giver_loc=[[Braug Espiritoscuro]],giverType=[[NPC]],giverId=4489,ender=[[Braug Dimspirit]],ender_loc=[[Braug Espiritoscuro]],enderType=[[NPC]],enderId=4489,prevId=1152,rewardNextId=6627,poiX=1429,poiY=-602,wowhead=[[https://www.wowhead.com/wotlk/quest=1154]],image=[[assets/images/quests/placeholder.png]],desc=[[You have passed Dorn's tests, and now you seek to pass your next trial. Very good. But up until now, your challenges have been childish. It is easy to test your body--your mind is another matter completely. I shall explain it simply: find the book I name, study it, and answer my question about its contents. What book, you must be asking? The Legacy of the Aspects. It can be found at the bottom of Dor'danil in southern Ashenvale, protected by the dead druids and their slayers.]],logDesc=[[Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.]]}
DB[1159]={id=1159,zoneId=400,name=[[Test of Lore]],name_loc=[[Prueba de conocimiento]],level=30,minLevel=25,giver=[[Braug Dimspirit]],giver_loc=[[Braug Espiritoscuro]],giverType=[[NPC]],giverId=4489,ender=[[Parqual Fintallas]],enderType=[[NPC]],enderId=4488,prevId=6627,rewardNextId=1160,poiX=1459,poiY=319,wowhead=[[https://www.wowhead.com/wotlk/quest=1159]],image=[[assets/images/quests/placeholder.png]],desc=[[Well done, $N. You have passed the first portion of the Test of Lore, but there is still another question to be answered. But that question is not mine to ask. Seek out Parqual Fintallas in Lordaeron City. He was a great historian for the humans before the Plague overtook him. Now he continues to seek enlightenment, but of a different nature. He will have another requirement of you before he asks you anything, but you have done masterfully thus far--I'm sure you will overcome his obstacle.]],logDesc=[[Find Parqual Fintallas in Undercity.]]}
DB[1160]={id=1160,zoneId=796,name=[[Test of Lore]],name_loc=[[Prueba de conocimiento]],level=36,minLevel=25,giver=[[Parqual Fintallas]],giverType=[[NPC]],giverId=4488,ender=[[Parqual Fintallas]],enderType=[[NPC]],enderId=4488,prevId=1159,rewardNextId=6628,poiX=1459,poiY=319,wowhead=[[https://www.wowhead.com/wotlk/quest=1160]],image=[[assets/images/quests/placeholder.png]],desc=[[I will tell you what you must seek, and I will even ask you my question, but not because you wish to prove yourself. Knowledge is far more important than strength. Even as others seem to pass you by in ability, your knowledge of the world will be more valuable. Go to the Monastery in the north of Tirisfal Glades. In the library there, a book called Beginnings of the Undead Threat resides. It was used by the now-corrupt paladins there to train them to fight my kind. Bring it to me.]],logDesc=[[Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.]]}
DB[1164]={id=1164,zoneId=1497,name=[[To Steal From Thieves]],name_loc=[[Robar a un ladrón...]],level=36,minLevel=27,giver=[[Genavie Callow]],giverType=[[NPC]],giverId=4486,ender=[[Genavie Callow]],enderType=[[NPC]],enderId=4486,poiX=1561,poiY=261,wowhead=[[https://www.wowhead.com/wotlk/quest=1164]],image=[[assets/images/quests/placeholder.png]],desc=[[The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed! My family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, her and her lousy children had the audacity to steal the only precious belongings I had left. I don't care about the things they stole any more. What I want now are their heads! Kill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.]],logDesc=[[Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.]],choiceRewards={{id=4443,qty=1},{id=2032,qty=1}}}
DB[1166]={id=1166,zoneId=15,name=[[Overlord Mok'Morokk's Concern]],name_loc=[[Las pertenencias del señor supremo Mok'Morokk]],level=41,minLevel=37,giver=[[Overlord Mok'Morokk]],giver_loc=[[Señor supremo Mok'Morokk]],giverType=[[NPC]],giverId=4500,ender=[[Overlord Mok'Morokk]],ender_loc=[[Señor supremo Mok'Morokk]],enderType=[[NPC]],enderId=4500,poiX=-4345,poiY=-3313,wowhead=[[https://www.wowhead.com/wotlk/quest=1166]],image=[[assets/images/quests/placeholder.png]],desc=[[Bow before Overlord Mok'Morokk! Rexxar make me mighty leader of Stonemaul Clan! Me good leader. Me keep clan safe. Big dragons come and make fire at old home. Me smart ogre. Find new home for clan here. Leave old home so fast, me forget stuff. Tiny $r, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!]],logDesc=[[Overlord Mok'Morokk in Brackenwall Village wants you to retrieve his grog, snuff and strongbox in Dustwallow Swamp.]],rewards={{id=10702,qty=1}}}
DB[1167]={id=1167,zoneId=148,name=[[The Tower of Althalaxx]],name_loc=[[La Torre de Althalaxx]],level=28,minLevel=13,giver=[[Delgren the Purifier]],giver_loc=[[Delgren el Purificador]],giverType=[[NPC]],giverId=3663,ender=[[Balthule Shadowstrike]],ender_loc=[[Balthule Golpesombra]],enderType=[[NPC]],enderId=3661,prevId=1140,rewardNextId=1143,poiX=7247,poiY=-659,wowhead=[[https://www.wowhead.com/wotlk/quest=1167]],image=[[assets/images/quests/placeholder.png]],desc=[[Before confronting Athrikus, it would probably be wise for you to consult with Balthule. I have no doubt he has been vigilant in his watch of the Tower, and he may have information about recent developments.]],logDesc=[[Speak with Balthule Shadowstrike near the Tower of Althalaxx.]]}
DB[1168]={id=1168,zoneId=15,name=[[Army of the Black Dragon]],name_loc=[[El ejército de los dragones Negros]],level=41,minLevel=37,giver=[[Tharg]],giverType=[[NPC]],giverId=4502,ender=[[Tharg]],enderType=[[NPC]],enderId=4502,poiX=-4339,poiY=-3374,wowhead=[[https://www.wowhead.com/wotlk/quest=1168]],image=[[assets/images/quests/placeholder.png]],desc=[[Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres. Black dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here. Ogre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk. Me call Stonemaul Ruins home. Me like it in the south. This place not home. Help ogres fight army of the black dragon. Me want revenge. Me want to go home.]],logDesc=[[Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes.]],choiceRewards={{id=9705,qty=1},{id=9706,qty=1}}}
DB[1169]={id=1169,zoneId=15,name=[[Identifying the Brood]],name_loc=[[Identifica a los cachorros]],level=41,minLevel=37,giver=[[Draz'Zilb]],giverType=[[NPC]],giverId=4501,ender=[[Draz'Zilb]],enderType=[[NPC]],enderId=4501,poiX=-4516,poiY=-3918,wowhead=[[https://www.wowhead.com/wotlk/quest=1169]],image=[[assets/images/quests/placeholder.png]],desc=[[Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home. Why the puzzled stare, $n? Expecting me to speak like an uncouth ruffian merely because I am an ogre? Now back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...]],logDesc=[[Draz'Zilb in Brackenwall Village would like you to bring him 7 Searing Tongues and 7 Searing Hearts.]],choiceRewards={{id=9703,qty=1},{id=9704,qty=1}}}
DB[1170]={id=1170,zoneId=15,name=[[The Brood of Onyxia]],name_loc=[[El linaje de Onyxia]],level=41,minLevel=37,giver=[[Draz'Zilb]],giverType=[[NPC]],giverId=4501,ender=[[Overlord Mok'Morokk]],ender_loc=[[Señor supremo Mok'Morokk]],enderType=[[NPC]],enderId=4500,prevId=1169,rewardNextId=1171,poiX=-3133,poiY=-2880,wowhead=[[https://www.wowhead.com/wotlk/quest=1170]],image=[[assets/images/quests/placeholder.png]],desc=[[Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands? This is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres. Notify Mok'Morokk at once! Action must be taken.]],logDesc=[[Speak with Overlord Mok'Morokk in Brackenwall Village.]]}
DB[1171]={id=1171,zoneId=15,name=[[The Brood of Onyxia]],name_loc=[[El linaje de Onyxia]],level=41,minLevel=37,giver=[[Overlord Mok'Morokk]],giver_loc=[[Señor supremo Mok'Morokk]],giverType=[[NPC]],giverId=4500,ender=[[Draz'Zilb]],enderType=[[NPC]],enderId=4501,prevId=1170,rewardNextId=1172,poiX=-3191,poiY=-2926,wowhead=[[https://www.wowhead.com/wotlk/quest=1171]],image=[[assets/images/quests/placeholder.png]],desc=[[You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.]],logDesc=[[Speak with Draz'Zilb in Brackenwall Village.]]}
DB[1172]={id=1172,zoneId=15,name=[[The Brood of Onyxia]],name_loc=[[El linaje de Onyxia]],level=41,minLevel=37,giver=[[Draz'Zilb]],giverType=[[NPC]],giverId=4501,ender=[[Draz'Zilb]],enderType=[[NPC]],enderId=4501,prevId=1171,poiX=-4623,poiY=-3538,wowhead=[[https://www.wowhead.com/wotlk/quest=1172]],image=[[assets/images/quests/placeholder.png]],desc=[[Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch. Make haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them. We will never reclaim Stonemaul Village if the surrounding area remains a breeding ground. As for Mok'Morokk... I have other plans for the sod.]],logDesc=[[Draz'Zilb in Brackenwall Village wants you to destroy 5 Eggs of Onyxia.]],choiceRewards={{id=10700,qty=1},{id=10701,qty=1}}}
DB[1173]={id=1173,zoneId=15,name=[[Challenge Overlord Mok'Morokk]],name_loc=[[Desafiar al señor supremo Mok'Morokk]],level=45,minLevel=38,giver=[[Overlord Mok'Morokk]],giver_loc=[[Señor supremo Mok'Morokk]],giverType=[[NPC]],giverId=4500,ender=[[Draz'Zilb]],enderType=[[NPC]],enderId=4501,prevId=1172,poiX=-3133,poiY=-2935,wowhead=[[https://www.wowhead.com/wotlk/quest=1173]],image=[[assets/images/quests/placeholder.png]],desc=[[You dare challenge Overlord Mok'Morokk? Haw! Me crush tiny $r! You tell me when ready for good beating.]],logDesc=[[Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.]],choiceRewards={{id=10703,qty=1},{id=10704,qty=1}}}
DB[1174]={id=1174,zoneId=400,name=[[Gnomes Win!]],name_loc=[[¡Los gnomos ganan!]],level=1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=1174]],image=[[assets/images/quests/placeholder.png]],rewards={{id=5857,qty=1}}}
DB[1175]={id=1175,zoneId=400,name=[[A Bump in the Road]],name_loc=[[Un bache en la carretera]],level=33,minLevel=28,giver=[[Trackmaster Zherin]],giver_loc=[[Maestro rastreador Zherin]],giverType=[[NPC]],giverId=4629,ender=[[Trackmaster Zherin]],ender_loc=[[Maestro rastreador Zherin]],enderType=[[NPC]],enderId=4629,poiX=-5748,poiY=-3987,wowhead=[[https://www.wowhead.com/wotlk/quest=1175]],image=[[assets/images/quests/placeholder.png]],desc=[[After the big crash with the goblins' Red Thunder racer and a basilisk, Kronkrider hired me on to take care of the track. I don't know what all the animals out on the flats are feeding on to grow so big, but we have to be careful to thin them out so they won't wander onto the track when a race is going on. Tell you what. If you want to go out and make a little profit, go out and remove the basilisks from the area.]],logDesc=[[Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats.]]}
DB[1176]={id=1176,zoneId=400,name=[[Load Lightening]],name_loc=[[Menos peso]],level=30,minLevel=29,giver=[[Pozzik]],giver_loc=[[Pozík]],giverType=[[NPC]],giverId=4630,ender=[[Pozzik]],ender_loc=[[Pozík]],enderType=[[NPC]],enderId=4630,rewardNextId=1178,poiX=-6427,poiY=-4181,wowhead=[[https://www.wowhead.com/wotlk/quest=1176]],image=[[assets/images/quests/placeholder.png]],desc=[[When it comes to racing, every bit counts! Whether it's a minor tweaking on the power output, a slight slackening on the tension coils, or lightening the weight of the frame, you have to take everything into account. We use vulture bones for a lot of the minor structural tweaks we make to our racers, which offer the perfect balance of strength and weight. Even better, it's easy for us to get more, as the salt flats are littered with vultures. Bring me some and I'll give you a good price on them.]],logDesc=[[Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats.]]}
DB[1177]={id=1177,zoneId=15,name=[[Hungry!]],name_loc=[[¡Qué hambre!]],level=36,minLevel=32,giver=[[Mudcrush Durtfeet]],giver_loc=[[Fangolpe Piesucio]],giverType=[[NPC]],giverId=4503,ender=[[Mudcrush Durtfeet]],ender_loc=[[Fangolpe Piesucio]],enderType=[[NPC]],enderId=4503,poiX=-2359,poiY=-4150,wowhead=[[https://www.wowhead.com/wotlk/quest=1177]],image=[[assets/images/quests/placeholder.png]],desc=[[Mud big ogre. Me hungry. Go bash fishy. Bring Mud food. You feed Mud or Mud eat you.]],logDesc=[[Mudcrush Durtfeet in northern Dustwallow wants 8 Mirefin Heads.]],choiceRewards={{id=9518,qty=1},{id=9519,qty=1}}}
DB[1178]={id=1178,zoneId=400,name=[[Goblin Sponsorship]],name_loc=[[Patrocinio goblin]],level=37,minLevel=29,giver=[[Pozzik]],giver_loc=[[Pozík]],giverType=[[NPC]],giverId=4630,ender=[[Gazlowe]],enderType=[[NPC]],enderId=3391,prevId=1176,rewardNextId=1180,poiX=-836,poiY=-3729,wowhead=[[https://www.wowhead.com/wotlk/quest=1178]],image=[[assets/images/quests/placeholder.png]],desc=[[Our racing team is the pride of goblins everywhere. You'd be surprised at some of the people who contribute in one way or another to our team. You know Gazlowe? He tracks down parts from around the world for us. He even came down to work on one of our rigs once! A few weeks ago, he said he'd send us a new prototype fuel regulator but it hasn't come yet. He's usually very prompt... Maybe you wouldn't mind going to Ratchet to ask him about it? I wouldn't be so pushy, but the gnomes are gaining on us!]],logDesc=[[Speak to Gazlowe at Ratchet in The Barrens.]]}
DB[1179]={id=1179,zoneId=400,name=[[The Brassbolts Brothers]],name_loc=[[Los hermanos Pernolatón]],level=30,minLevel=28,giver=[[Pilot Longbeard]],giver_loc=[[Piloto Barbalarga]],giverType=[[NPC]],giverId=2092,ender=[[Wizzle Brassbolts]],ender_loc=[[Wizzle Pernolatón]],enderType=[[NPC]],enderId=4453,poiX=-6229,poiY=-3872,wowhead=[[https://www.wowhead.com/wotlk/quest=1179]],image=[[assets/images/quests/placeholder.png]],desc=[[You ever heard of the Shimmering Flats?  It's a stretch of salt flats way over in Kalimdor, just south of the Thousand Needles canyon.  It's a great place for racing because, well, it's so flat! A couple of gnome brothers are out there, friends of mine, trying out their new rocket car, and from what I hear it's fast!  Heh, so fast that their pilots keep crashing.  Giving themselves concussions. So they asked me for some Siege Engine helmets, but I have duties here.  I can't make the trip! Can you?]],logDesc=[[Bring the crate of crash helmets to Wizzle Brassbolts at Mirage Raceway in Thousand Needles.]]}
DB[1180]={id=1180,zoneId=400,name=[[Goblin Sponsorship]],name_loc=[[Patrocinio goblin]],level=37,minLevel=29,giver=[[Gazlowe]],giverType=[[NPC]],giverId=3391,ender=[[Wharfmaster Lozgil]],ender_loc=[[Jefe de embarcadero Lozgil]],enderType=[[NPC]],enderId=4631,prevId=1178,rewardNextId=1181,poiX=-14298,poiY=540,wowhead=[[https://www.wowhead.com/wotlk/quest=1180]],image=[[assets/images/quests/placeholder.png]],desc=[[Back to what you came here about. I know I promised Pozzik that I'd deliver a new fuel regulator for him, but I still haven't received it yet. Revilgaz over in Booty Bay said he'd have it shipped over, but it might be it slipped through the cracks somehow. If that's true, there's not much we can do about it. We can at least find out if it was dispatched from Booty Bay. Check in with Wharfmaster Lozgil over there, he should be able to check the cargo records.]],logDesc=[[Speak with Wharfmaster Lozgil at Booty Bay in Stranglethorn Vale.]]}
DB[1181]={id=1181,zoneId=400,name=[[Goblin Sponsorship]],name_loc=[[Patrocinio goblin]],level=37,minLevel=29,giver=[[Wharfmaster Lozgil]],giver_loc=[[Jefe de embarcadero Lozgil]],giverType=[[NPC]],giverId=4631,ender=[[Baron Revilgaz]],ender_loc=[[Barón Revilgaz]],enderType=[[NPC]],enderId=2496,prevId=1180,rewardNextId=1182,poiX=-14439,poiY=483,wowhead=[[https://www.wowhead.com/wotlk/quest=1181]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm afraid I can't be of much more help to you, $n. If you'd like to follow up on it more, I'd suggest you go hit up the Baron himself. If there's anyone who knows Revilgaz's business, it's Revilgaz. You'll find him at the tavern across the harbor, top floor.]],logDesc=[[Speak with Baron Revilgaz in Booty Bay.]]}
DB[1182]={id=1182,zoneId=400,name=[[Goblin Sponsorship]],name_loc=[[Patrocinio goblin]],level=37,minLevel=29,giver=[[Baron Revilgaz]],giver_loc=[[Barón Revilgaz]],giverType=[[NPC]],giverId=2496,ender=[[Baron Revilgaz]],ender_loc=[[Barón Revilgaz]],enderType=[[NPC]],enderId=2496,prevId=1181,rewardNextId=1183,poiX=-12034,poiY=-544,wowhead=[[https://www.wowhead.com/wotlk/quest=1182]],image=[[assets/images/quests/placeholder.png]],desc=[[See, the Venture Company shredders out in Lake Nazferiti (in northern Stranglethorn) have been equipped with a new model fuel regulator. I was thinking that Pozzik would be able to take advantage of it, if he could get some details. Unfortunately, Cozzle, the foreman out there, appears to be a little more clever than I gave him credit for. You seem like you might have more luck finding the blueprints though. I know he keeps them in his house, but they're almost certainly under lock and key.]],logDesc=[[Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.]]}
DB[1183]={id=1183,zoneId=400,name=[[Goblin Sponsorship]],name_loc=[[Patrocinio goblin]],level=37,minLevel=29,giver=[[Baron Revilgaz]],giver_loc=[[Barón Revilgaz]],giverType=[[NPC]],giverId=2496,ender=[[Pozzik]],ender_loc=[[Pozík]],enderType=[[NPC]],enderId=4630,prevId=1182,rewardNextId=1186,poiX=-6193,poiY=-3961,wowhead=[[https://www.wowhead.com/wotlk/quest=1183]],image=[[assets/images/quests/placeholder.png]],desc=[[You should be all set to go. Give Pozzik my regards and tell him that if he ever needs anything, not to hesitate to ask. I'll be waiting for the news that he breaks the track record soon!]],logDesc=[[Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats.]]}
DB[1184]={id=1184,zoneId=400,name=[[Parts of the Swarm]],name_loc=[[Pedazos del enjambre]],level=35,minLevel=28,giver=[[Korran]],giverType=[[NPC]],giverId=3428,ender=[[Belgrom Rockmaul]],ender_loc=[[Belgrom Destrozarroca]],enderType=[[NPC]],enderId=4485,prevId=1148,poiX=1954,poiY=-4736,wowhead=[[https://www.wowhead.com/wotlk/quest=1184]],image=[[assets/images/quests/placeholder.png]],desc=[[Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon. That should please him greatly.]],logDesc=[[Return to Belgrom Rockmaul in Orgrimmar.]],choiceRewards={{id=6737,qty=1},{id=6738,qty=1}}}
DB[1185]={id=1185,zoneId=493,name=[[Under the Chitin Was...]],name_loc=[[Debajo de la quitina había...]],level=57,minLevel=54,giver=[[Umber]],giverType=[[NPC]],giverId=11939,ender=[[Umber]],enderType=[[NPC]],enderId=11939,prevId=6845,poiX=7944,poiY=-2417,wowhead=[[https://www.wowhead.com/wotlk/quest=1185]],image=[[assets/images/quests/placeholder.png]]}
DB[1186]={id=1186,zoneId=400,name=[[The Eighteenth Pilot]],name_loc=[[El piloto nº18]],level=37,minLevel=29,giver=[[Pozzik]],giver_loc=[[Pozík]],giverType=[[NPC]],giverId=4630,ender=[[Razzeric]],enderType=[[NPC]],enderId=4706,prevId=1183,rewardNextId=1187,poiX=-6199,poiY=-3968,wowhead=[[https://www.wowhead.com/wotlk/quest=1186]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm going to be busy with working on integrating this new fuel regulator to our racer designs, but if you'd like to help out the team some more, talk to Razzeric. He's our pilot--well, our eighteenth pilot, to be exact--and he likes to add his own little modifications to the racers. He's a little off his rocker, though, so try not to act too surprised.]],logDesc=[[Speak with Razzeric on the Shimmering Flats in Thousand Needles.]]}
DB[1187]={id=1187,zoneId=400,name=[[Razzeric's Tweaking]],name_loc=[[Los ajustes de Razzeric]],level=41,minLevel=29,giver=[[Razzeric]],giverType=[[NPC]],giverId=4706,ender=[[Razzeric]],enderType=[[NPC]],enderId=4706,prevId=1186,rewardNextId=1188,poiX=-6199,poiY=-3968,wowhead=[[https://www.wowhead.com/wotlk/quest=1187]],image=[[assets/images/quests/placeholder.png]],desc=[[Pozzik's a great mechanic, I know that, but he's afraid to just load on the firepower and grab on for the ride. Not me, though. After Pozzik finishes with a racer, I take a little time to put my own modifications on--you know, loosening up the controls, removing parts of the frame, and adding more juice! I ordered a seaforium booster from Shreev at the Gizmorium in Gadgetzan, but apparently the zeppelin it was being sent on crashed in Dustwallow Marsh! I gotta have it, $n!]],logDesc=[[Retrieve the Seaforium Booster for Razzeric in the Shimmering Flats.]]}
DB[1188]={id=1188,zoneId=400,name=[[Safety First]],name_loc=[[La seguridad primero]],level=41,minLevel=29,giver=[[Razzeric]],giverType=[[NPC]],giverId=4706,ender=[[Shreev]],enderType=[[NPC]],enderId=4708,prevId=1187,rewardNextId=1189,poiX=-7128,poiY=-3735,wowhead=[[https://www.wowhead.com/wotlk/quest=1188]],image=[[assets/images/quests/placeholder.png]],desc=[[But wait, what's this? Shreev left the safety on. That will limit the amount of power I can draw from the booster at any time. I told him I wanted it off! This is no good. You have to take this to the Gadgetzan Gizmorium in the Tanaris Desert and have Shreev remove this.]],logDesc=[[Bring the Seaforium Booster to Shreev at Gadgetzan in Tanaris.]]}
DB[1189]={id=1189,zoneId=400,name=[[Safety First]],name_loc=[[La seguridad primero]],level=41,minLevel=29,giver=[[Shreev]],giverType=[[NPC]],giverId=4708,ender=[[Razzeric]],enderType=[[NPC]],enderId=4706,prevId=1188,poiX=-6199,poiY=-3968,wowhead=[[https://www.wowhead.com/wotlk/quest=1189]],image=[[assets/images/quests/placeholder.png]],desc=[[There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track. Would be a shame, too, if that happened. Who knows if our nineteenth driver would be any good?]],logDesc=[[Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats in Thousand Needles.]],choiceRewards={{id=6726,qty=1},{id=6727,qty=1}}}
DB[1190]={id=1190,zoneId=400,name=[[Keeping Pace]],name_loc=[[Mantener la velocidad]],level=41,minLevel=29,giver=[[Pozzik]],giver_loc=[[Pozík]],giverType=[[NPC]],giverId=4630,ender=[[Rizzle's Unguarded Plans]],ender_loc=[[Planes sin vigilancia de Rizzle]],enderType=[[GO]],enderId=20805,prevId=1137,rewardNextId=1194,poiX=-6237,poiY=-3830,wowhead=[[https://www.wowhead.com/wotlk/quest=1190]],image=[[assets/images/quests/placeholder.png]],desc=[[The Brassbolts brothers have discovered a new building material, that's the only explanation that makes sense. Their cars have been operating faster than before, but their designs, and all the other data we've gathered from their runs is identical. What we do know, is that Rizzle Brassbolts has been focused on the plans for this new discovery almost constantly. Zamek can create a diversion for you, so that you can steal those plans from them.]],logDesc=[[Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats in Thousand Needles.]]}
DB[1191]={id=1191,zoneId=400,name=[[Zamek's Distraction]],name_loc=[[La distracción de Zamek]],level=41,minLevel=29,giver=[[Zamek]],giverType=[[NPC]],giverId=4709,ender=[[Zamek]],enderType=[[NPC]],enderId=4709,poiX=-6226,poiY=-3945,wowhead=[[https://www.wowhead.com/wotlk/quest=1191]],image=[[assets/images/quests/placeholder.png]]}
DB[1192]={id=1192,zoneId=400,name=[[Indurium Ore]],name_loc=[[Mena de indurio]],level=42,minLevel=29,giver=[[Pozzik]],giver_loc=[[Pozík]],giverType=[[NPC]],giverId=4630,ender=[[Pozzik]],ender_loc=[[Pozík]],enderType=[[NPC]],enderId=4630,prevId=1194,poiX=-6193,poiY=-3961,wowhead=[[https://www.wowhead.com/wotlk/quest=1192]],image=[[assets/images/quests/placeholder.png]]}
DB[1193]={id=1193,zoneId=2557,name=[[A Broken Trap]],name_loc=[[Una trampa rota]],level=60,minLevel=56,giver=[[Broken Trap]],giver_loc=[[Trampa rota]],giverType=[[GO]],giverId=179485,ender=[[Broken Trap]],ender_loc=[[Trampa rota]],enderType=[[GO]],enderId=179485,poiX=559,poiY=550,wowhead=[[https://www.wowhead.com/wotlk/quest=1193]],image=[[assets/images/quests/placeholder.png]]}
DB[1194]={id=1194,zoneId=400,name=[[Rizzle's Schematics]],name_loc=[[Los esquemas de Rizzle]],level=41,minLevel=29,giver=[[Rizzle's Unguarded Plans]],giver_loc=[[Planes sin vigilancia de Rizzle]],giverType=[[GO]],giverId=20805,ender=[[Pozzik]],ender_loc=[[Pozík]],enderType=[[NPC]],enderId=4630,prevId=1190,poiX=-6193,poiY=-3961,wowhead=[[https://www.wowhead.com/wotlk/quest=1194]],image=[[assets/images/quests/placeholder.png]],desc=[[Rizzle's schematics describe the process of the refinement of indurium ore. From his scrawls, it is apparent that indurium ore is being obtained from the dwarven excavation site of Uldaman in the Badlands. Much of the other notes relate to the heat resistant properties. Used as a paperweight for the plans is a hunk of what appears to be unrefined indurium ore.]],logDesc=[[Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats in Thousand Needles.]]}
DB[1195]={id=1195,zoneId=1638,name=[[The Sacred Flame]],name_loc=[[La llama sacra]],level=25,minLevel=20,giver=[[Zangen Stonehoof]],giver_loc=[[Zangen Pezuña Pétrea]],giverType=[[NPC]],giverId=4721,ender=[[Zangen Stonehoof]],ender_loc=[[Zangen Pezuña Pétrea]],enderType=[[NPC]],enderId=4721,rewardNextId=1196,poiX=-1208,poiY=-57,wowhead=[[https://www.wowhead.com/wotlk/quest=1195]],image=[[assets/images/quests/placeholder.png]],desc=[[The Galak centaur in the Thousand Needles are protecting an artifact from the time of the centaurs' creation. We would like to retrieve it, but we require a phial of water from one of the night elves' moonwells. To collect the water, you will first need to obtain one of the phials carried by the dryads near the Raynewood Retreat in the heart of Ashenvale Forest. There is a moonwell near the western bank of the Falfarren River, south of the main road, where you can fill the phial.]],logDesc=[[Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff.]]}
DB[1196]={id=1196,zoneId=1638,name=[[The Sacred Flame]],name_loc=[[La llama sacra]],level=29,minLevel=20,giver=[[Zangen Stonehoof]],giver_loc=[[Zangen Pezuña Pétrea]],giverType=[[NPC]],giverId=4721,ender=[[Rau Cliffrunner]],ender_loc=[[Rau Abiscorredor]],enderType=[[NPC]],enderId=4722,prevId=1195,rewardNextId=1197,poiX=-5484,poiY=-2463,wowhead=[[https://www.wowhead.com/wotlk/quest=1196]],image=[[assets/images/quests/placeholder.png]],desc=[[Bring the filled phial to Rau Cliffrunner at the Freewind Post in southeastern Thousand Needles. You can get to the Thousand Needles by taking the Great Lift at the southern edge of the Barrens. I wouldn't be surprised if you can help us out further.]],logDesc=[[Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post.]]}
DB[1197]={id=1197,zoneId=1638,name=[[The Sacred Flame]],name_loc=[[La llama sacra]],level=29,minLevel=20,giver=[[Rau Cliffrunner]],giver_loc=[[Rau Abiscorredor]],giverType=[[NPC]],giverId=4722,ender=[[Rau Cliffrunner]],ender_loc=[[Rau Abiscorredor]],enderType=[[NPC]],enderId=4722,prevId=1196,poiX=-4890,poiY=-2282,wowhead=[[https://www.wowhead.com/wotlk/quest=1197]],image=[[assets/images/quests/placeholder.png]],desc=[[Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it. You will find Splithoof Crag, the centaurs' stronghold, to the north of here. The flame is kept in Splithoof Hold, a heavily guarded part of the crag. Be careful, though, the Galak centaur have great numbers here, and will be rather reluctant to surrender something so dear to them.]],logDesc=[[Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post.]],choiceRewards={{id=6739,qty=1},{id=6740,qty=1}}}
DB[1198]={id=1198,zoneId=719,name=[[In Search of Thaelrid]],name_loc=[[Buscando a Thaelrid]],level=24,minLevel=18,giver=[[Dawnwatcher Shaedlass]],giver_loc=[[Vigía del Alba Shaedlass]],giverType=[[NPC]],giverId=4786,ender=[[Argent Guard Thaelrid]],ender_loc=[[Guardia Argenta Thaelrid]],enderType=[[NPC]],enderId=4787,rewardNextId=1200,poiX=4138,poiY=899,wowhead=[[https://www.wowhead.com/wotlk/quest=1198]],image=[[assets/images/quests/placeholder.png]],desc=[[Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps on the coasts of Ashenvale. My role here with the Argent Dawn is to collect as much information as I can, so we know when and where help is needed. It has been weeks now since I sent a scout to check on the activity at Blackfathom Deeps. Argent Guard Thaelrid has not yet reported back. My other scouts are preoccupied with pressing matters. Seek out and aid Thaelrid for me, $n.]],logDesc=[[Seek out Argent Guard Thaelrid in Blackfathom Deeps.]]}
DB[1199]={id=1199,zoneId=719,name=[[Twilight Falls]],name_loc=[[Cascada Crepuscular]],level=25,minLevel=20,giver=[[Argent Guard Manados]],giver_loc=[[Guardia Argenta Manados]],giverType=[[NPC]],giverId=4784,ender=[[Argent Guard Manados]],ender_loc=[[Guardia Argenta Manados]],enderType=[[NPC]],enderId=4784,poiX=10069,poiY=2354,wowhead=[[https://www.wowhead.com/wotlk/quest=1199]],image=[[assets/images/quests/placeholder.png]],desc=[[Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world. We believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps on the coast of Ashenvale. Whatever evil plan brews in the depths of the old temple must be thwarted. Wage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.]],logDesc=[[Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus.]],rewards={{id=6998,qty=1},{id=7000,qty=1}}}
DB[1200]={id=1200,zoneId=719,name=[[Blackfathom Villainy]],name_loc=[[La vileza de Brazanegra]],level=27,minLevel=18,giver=[[Argent Guard Thaelrid]],giver_loc=[[Guardia Argenta Thaelrid]],giverType=[[NPC]],giverId=4787,ender=[[Dawnwatcher Selgorm]],ender_loc=[[Vigía del Alba Selgorm]],enderType=[[NPC]],enderId=4783,prevId=1198,poiX=10066,poiY=2344,wowhead=[[https://www.wowhead.com/wotlk/quest=1200]],image=[[assets/images/quests/placeholder.png]],desc=[[Strength has left me. Your help is needed! Long ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well. Aku'Mai, servant of the Old God, rose from the waters. The Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power. Slay Kelris and bring his head to Selgorm in Darnassus, $N, please.]],logDesc=[[Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.]],choiceRewards={{id=7001,qty=1},{id=7002,qty=1}}}
DB[1201]={id=1201,zoneId=15,name=[[Theramore Spies]],name_loc=[[Los espías de Theramore]],level=35,minLevel=30,giver=[[Nazeer Bloodpike]],giver_loc=[[Nazeer Picasangre]],giverType=[[NPC]],giverId=4791,ender=[[Nazeer Bloodpike]],ender_loc=[[Nazeer Picasangre]],enderType=[[NPC]],enderId=4791,rewardNextId=1202,poiX=-2990,poiY=-3286,wowhead=[[https://www.wowhead.com/wotlk/quest=1201]],image=[[assets/images/quests/placeholder.png]],desc=[[The Horde and Alliance hold an uneasy truce.  Outlying skirmishes and covert actions are taken by one side against the other, and it is our duty to ensure the Horde is on top! Now is the chance to do just that. Alliance infiltrators have taken positions east of Brackenwall Village.  They spy on the village and report our movements to Theramore, which we cannot allow. Hunt down the infiltrators and slay them.  Send a clear message to their superiors that we will not tolerate their spies' presence!]],logDesc=[[Kill 9 Theramore Infiltrators, then return to Nazeer Bloodpike in Brackenwall Village.]]}
DB[1202]={id=1202,zoneId=15,name=[[The Theramore Docks]],name_loc=[[El puerto de Theramore]],level=35,minLevel=30,giver=[[Nazeer Bloodpike]],giver_loc=[[Nazeer Picasangre]],giverType=[[NPC]],giverId=4791,ender=[[Nazeer Bloodpike]],ender_loc=[[Nazeer Picasangre]],enderType=[[NPC]],enderId=4791,prevId=1201,poiX=-3825,poiY=-4730,wowhead=[[https://www.wowhead.com/wotlk/quest=1202]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, two of our spies were sent to steal documents from a ship at the Theramore docks.  They gained the papers but were discovered, and were forced to throw the documents into the sea. One spy later escaped, but was unable to recover the prize.  He reported his failure to me, and I now charge the task to you. The documents are in a footlocker, in the waters somewhere beneath the Theramore docks.  Find those documents, $N, and bring them to me.]],logDesc=[[Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village.]]}
DB[1203]={id=1203,zoneId=15,name=[[Jarl Needs a Blade]],name_loc=[[Jarl necesita una hoja]],level=35,minLevel=30,giver=[["Swamp Eye" Jarl]],giver_loc=[["Ojolodo" Jarl]],giverType=[[NPC]],giverId=4792,ender=[["Swamp Eye" Jarl]],ender_loc=[["Ojolodo" Jarl]],enderType=[[NPC]],enderId=4792,prevId=1206,poiX=-2656,poiY=-4017,wowhead=[[https://www.wowhead.com/wotlk/quest=1203]],image=[[assets/images/quests/placeholder.png]],desc=[[I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade... Some people call it a sword.  I call it a swing blade. You help me?  Those fish-men, you know, murlocs or whatever they're called.... There's one they call Razorspine, carries a big sword, lives north of here near the beach. That's the sword I need! But don't sleep on this.  What I'm cutting won't keep forever...]],logDesc=[[Bring Razorspine's Sword to "Swamp Eye" Jarl at Swamplight Manor.]],rewards={{id=9622,qty=1},{id=5016,qty=1}}}
DB[1204]={id=1204,zoneId=15,name=[[Mudrock Soup and Bugs]],name_loc=[[Sopa de Fangorroca con tropezones]],level=38,minLevel=33,giver=[[Morgan Stern]],giverType=[[NPC]],giverId=4794,ender=[[Morgan Stern]],enderType=[[NPC]],enderId=4794,rewardNextId=1258,poiX=-2284,poiY=-4354,wowhead=[[https://www.wowhead.com/wotlk/quest=1204]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm working on a dish I call "Mudrock Soup and Bugs."  I still need the major ingredients, and... well, I don't think I'd last long trudging through Dustwallow Marsh! So, $N, can you do some hunting for me?  First, I need the tongues of Mudrock turtles.  You can find Mudrocks along the coast, mostly around the bay. But I don't want just any tongues!  I hear that the tongues of some Mudrocks are forked... They say the forked tongues have a distinct flavor, and I want that flavor in my dish...]],logDesc=[[Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore.]]}
DB[1205]={id=1205,zoneId=15,name=[[Deadmire]],name_loc=[[Lodomuerto]],level=41,minLevel=35,giver=[[Melor Stonehoof]],giver_loc=[[Melor Pezuña Pétrea]],giverType=[[NPC]],giverId=3441,ender=[[Melor Stonehoof]],ender_loc=[[Melor Pezuña Pétrea]],enderType=[[NPC]],enderId=3441,poiX=-1413,poiY=-126,wowhead=[[https://www.wowhead.com/wotlk/quest=1205]],image=[[assets/images/quests/placeholder.png]],desc=[[Deadmire is an ancient crocolisk in Dustwallow marsh.  And it is his time to die. Old bones grind as he pulls his huge body through the swamp, and although he still moves with the strength and speed of youth, his aging body tortures the great spirit within it, a spirit whose flame will not waver. Yet now he lives in constant, maddening pain.  You must end the life of this noble creature, $N.  You must lead Deadmire to peace.]],logDesc=[[Bring Deadmire's Tooth to Melor in Thunder Bluff.]]}
DB[1206]={id=1206,zoneId=15,name=[[Jarl Needs Eyes]],name_loc=[[Jarl necesita ojos]],level=35,minLevel=30,giver=[["Swamp Eye" Jarl]],giver_loc=[["Ojolodo" Jarl]],giverType=[[NPC]],giverId=4792,ender=[["Swamp Eye" Jarl]],ender_loc=[["Ojolodo" Jarl]],enderType=[[NPC]],enderId=4792,prevId=1218,rewardNextId=1203,poiX=-2750,poiY=-2852,wowhead=[[https://www.wowhead.com/wotlk/quest=1206]],image=[[assets/images/quests/placeholder.png]],desc=[[Eye juice is good juice for drinking.  Too bad most critters only have two eyes. But spiders have lots of eyes.  Lots and lots.  And Darkmist eye juice is tasty.  Smooth and salty!  Unpopped spider eyes... I taste them already. Darkmist spiders are west of here, in the Darkmist Cavern.  You figure the spiders are named after the cave... or is it the other way around?]],logDesc=[[Bring 20 Unpopped Darkmist Eyes to "Swamp Eye" Jarl at the Swamplight Manor.]]}
DB[1218]={id=1218,zoneId=15,name=[[Marsh Frog Legs]],name_loc=[[Ancas de rana de marisma]],level=35,minLevel=30,giver=[["Swamp Eye" Jarl]],giver_loc=[["Ojolodo" Jarl]],giverType=[[NPC]],giverId=4792,ender=[["Swamp Eye" Jarl]],ender_loc=[["Ojolodo" Jarl]],enderType=[[NPC]],enderId=4792,rewardNextId=1206,poiX=-2931,poiY=-4056,wowhead=[[https://www.wowhead.com/wotlk/quest=1218]],image=[[assets/images/quests/placeholder.png]],desc=[[I like cooking.  Good swamp cooking.  Fried green frog legs and the like. And I'm all out of legs. The manor is overrun with frogs, though. Giant marsh frogs. Think you could bring me some of those legs? Nothin' to it, really. Just bop 'em on the head and bring me the legs. Then I'll make a stew and stew it up and suck it down and give you some too. Do you like stew?]],logDesc=[[Bring 10 Marsh Frog Legs to "Swamp Eye" Jarl in Dustwallow Marsh.]],rewards={{id=6807,qty=20}}}
DB[1219]={id=1219,zoneId=15,name=[[The Orc Report]],name_loc=[[El informe orco]],level=35,minLevel=30,giver=[[Loose Dirt]],giver_loc=[[Tierra esparcida]],giverType=[[GO]],giverId=20985,ender=[[Lieutenant Aden]],ender_loc=[[Teniente Aden]],enderType=[[NPC]],enderId=23951,rewardNextId=1220,poiX=-3683,poiY=-4391,wowhead=[[https://www.wowhead.com/wotlk/quest=1219]],image=[[assets/images/quests/placeholder.png]],desc=[[Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment. The parchment is written in orcish... and it looks important.]],logDesc=[[Bring the Spy's Report to Lieutenant Aden in Theramore.]]}
DB[1220]={id=1220,zoneId=15,name=[[Captain Vimes]],name_loc=[[Capitán Vimes]],level=35,minLevel=30,giver=[[Theramore Lieutenant]],giver_loc=[[Teniente de Theramore]],giverType=[[NPC]],giverId=4947,ender=[[Captain Garran Vimes]],ender_loc=[[Capitán Garran Vimes]],enderType=[[NPC]],enderId=4944,prevId=1219,poiX=-3735,poiY=-4556,wowhead=[[https://www.wowhead.com/wotlk/quest=1220]],image=[[assets/images/quests/placeholder.png]],desc=[[Captain Vimes should see the orc report you found, $N.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore! The captain is in the barracks, on the northeastern side of Theramore Isle.]],logDesc=[[Bring the Spy's Report to Captain Garran Vimes.]]}
DB[1220]={id=1220,zoneId=15,name=[[Captain Vimes]],name_loc=[[Capitán Vimes]],level=35,minLevel=30,giver=[[Lieutenant Aden]],giver_loc=[[Teniente de Theramore]],giverType=[[NPC]],giverId=23951,ender=[[Captain Garran Vimes]],ender_loc=[[Capitán Garran Vimes]],enderType=[[NPC]],enderId=4944,prevId=1219,poiX=-3735,poiY=-4556,wowhead=[[https://www.wowhead.com/wotlk/quest=1220]],image=[[assets/images/quests/placeholder.png]],desc=[[Captain Vimes should see the orc report you found, $N.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore! The captain is in the barracks, on the northeastern side of Theramore Isle.]],logDesc=[[Bring the Spy's Report to Captain Garran Vimes.]]}
DB[1221]={id=1221,zoneId=1717,name=[[Blueleaf Tubers]],name_loc=[[Los tubérculos hojazul]],level=26,minLevel=20,giver=[[Mebok Mizzyrix]],giverType=[[NPC]],giverId=3446,ender=[[Mebok Mizzyrix]],enderType=[[NPC]],enderId=3446,poiX=-930,poiY=-3693,wowhead=[[https://www.wowhead.com/wotlk/quest=1221]],image=[[assets/images/quests/placeholder.png]],desc=[[Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul. And even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away. It won't be easy, but if you get me some tubers I'll pay you handsomely.]],logDesc=[[Grab a Crate with Holes. Grab a Snufflenose Command Stick. Grab and read the Snufflenose Owner's Manual. In Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers. Bring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.]],rewards={{id=6755,qty=1}}}
DB[1222]={id=1222,zoneId=15,name=[[Stinky's Escape]],name_loc=[[La fuga de Apestoso]],level=37,minLevel=30,giver=[["Stinky" Ignatz]],giver_loc=[["Apestoso" Ignatz]],giverType=[[NPC]],giverId=4880,ender=[[Morgan Stern]],enderType=[[NPC]],enderId=4794,nextId=1271,exGroup=-1222,poiX=-3625,poiY=-4458,wowhead=[[https://www.wowhead.com/wotlk/quest=1222]],image=[[assets/images/quests/placeholder.png]],desc=[[Great, finally something that doesn't want to eat me! I need help handling the critters around here, and you fit the mold, $gbuddy:lady;. The cook Morgan Stern is researching a new recipe, and he sent me out here to gather bogbean leaves.  I guess he thinks they're tasty. Anyway, while looking for a bogbean plant... I got myself surrounded!  Can you help me out of here, and watch my back as I look for the bogbean?]],logDesc=[[Escort "Stinky" Ignatz, then speak with Morgan Stern in Theramore.]],rewards={{id=3825,qty=1}}}
DB[1238]={id=1238,zoneId=15,name=[[The Lost Report]],name_loc=[[El informe perdido]],level=35,minLevel=30,giver=[[Loose Dirt]],giver_loc=[[Tierra esparcida]],giverType=[[GO]],giverId=20985,ender=[[Nazeer Bloodpike]],ender_loc=[[Nazeer Picasangre]],enderType=[[NPC]],enderId=4791,poiX=-3106,poiY=-2824,wowhead=[[https://www.wowhead.com/wotlk/quest=1238]],image=[[assets/images/quests/placeholder.png]],desc=[[Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment. The parchment is a report made by an orc who spent weeks spying on the city of Theramore. After scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.]],logDesc=[[Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.]]}
DB[1239]={id=1239,zoneId=15,name=[[The Severed Head]],name_loc=[[La cabeza cercenada]],level=35,minLevel=30,giver=[[Loose Dirt]],giver_loc=[[Tierra esparcida]],giverType=[[GO]],giverId=20985,ender=[[Nazeer Bloodpike]],ender_loc=[[Nazeer Picasangre]],enderType=[[NPC]],enderId=4791,prevId=1238,rewardNextId=1240,poiX=-3106,poiY=-2824,wowhead=[[https://www.wowhead.com/wotlk/quest=1239]],image=[[assets/images/quests/placeholder.png]],desc=[[Vigorous digging reveals the head of a male orc, raggedly severed at the neck.  His lips are frozen in a snarl, and its dark eyes stare defiantly.]],logDesc=[[Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village.]]}
DB[1240]={id=1240,zoneId=15,name=[[The Troll Witchdoctor]],name_loc=[[El trol médico brujo]],level=35,minLevel=30,giver=[[Nazeer Bloodpike]],giver_loc=[[Nazeer Picasangre]],giverType=[[NPC]],giverId=4791,ender=[[Kin'weelay]],enderType=[[NPC]],enderId=2519,prevId=1239,poiX=-12347,poiY=161,wowhead=[[https://www.wowhead.com/wotlk/quest=1240]],image=[[assets/images/quests/placeholder.png]],desc=[[We must know the events surrounding Marg's death!  And the only way to do that, $N, is through the witch-magic of trolls. Bring Marg's head to Kin'weelay in Stranglethorn Vale, at the Grom'gol Base Camp. Kin'weelay is the most powerful witchdoctor of the Darkspear trolls.  If anyone can speak to Marg Nighteye's spirit, it is he.]],logDesc=[[Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale.]]}
DB[1241]={id=1241,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=28,minLevel=28,giver=[[Bishop DeLavey]],giver_loc=[[Obispo DeLavey]],giverType=[[NPC]],giverId=4960,ender=[[Jorgen]],enderType=[[NPC]],enderId=4959,prevId=1274,rewardNextId=1242,poiX=-8982,poiY=397,wowhead=[[https://www.wowhead.com/wotlk/quest=1241]],image=[[assets/images/quests/placeholder.png]],desc=[[Recently a diplomat was sent to Theramore to meet with Jaina Proudmoore. That diplomat never arrived. I believe the Defias are involved in this plot, but I'm not sure how. The diplomat's disappearance still eludes public attention, but it can't remain that way for long. Agents of the king are already scouring the city for clues, but I have my own contacts I would like involved. In the Valley of Heroes is an old friend of mine named Jorgen. Find him, give him this note, and follow his instructions.]],logDesc=[[Find Jorgen in Stormwind City.]]}
DB[1242]={id=1242,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=28,minLevel=28,giver=[[Jorgen]],giverType=[[NPC]],giverId=4959,ender=[[Elling Trias]],ender_loc=[[Elling Trias]],enderType=[[NPC]],enderId=482,prevId=1241,rewardNextId=1243,poiX=-8854,poiY=576,wowhead=[[https://www.wowhead.com/wotlk/quest=1242]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this here note to Elling Trias. Don't say nothin' else to him. Just be polite and wait for him to respond. And don't worry, he will. I'm gonna only impress this on ya once more, $N: treat this matter seriously, and keep your yapper shut. Ya can find Trias at his cheese shop, Trias' Cheese, in the Trade District. Good luck.]],logDesc=[[Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City.]]}
DB[1243]={id=1243,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=28,minLevel=28,giver=[[Elling Trias]],giver_loc=[[Elling Trias]],giverType=[[NPC]],giverId=482,ender=[[Watcher Backus]],ender_loc=[[Vigía Backus]],enderType=[[NPC]],enderId=840,prevId=1242,rewardNextId=1244,poiX=-10512,poiY=-1196,wowhead=[[https://www.wowhead.com/wotlk/quest=1243]],image=[[assets/images/quests/placeholder.png]],desc=[[Jorgen, you ol' sonuva.... So, that's how it's going to be, huh? All right, I can deal with that. I hope he finds the Twisting Nether that much sooner! Here's what's gonna happen, $N. I'll start using my contacts here, but you're doing most of the footwork so I save some coin. Head to Darkshire in Duskwood and find Watcher Backus--he usually patrols the north road right outside of town. Just tell him you're looking into any Defias activity for me and he'll help you out with any information he can.]],logDesc=[[Give the Sealed Note to Watcher Backus in Duskwood.]]}
DB[1244]={id=1244,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=30,minLevel=28,giver=[[Watcher Backus]],giver_loc=[[Vigía Backus]],giverType=[[NPC]],giverId=840,ender=[[Watcher Backus]],ender_loc=[[Vigía Backus]],enderType=[[NPC]],enderId=840,prevId=1243,rewardNextId=1245,poiX=-11014,poiY=187,wowhead=[[https://www.wowhead.com/wotlk/quest=1244]],image=[[assets/images/quests/placeholder.png]],desc=[[Defias activity? Well, there's always some activity; even if they keep to themselves we consider them a threat. But now that I think about it, there was a recent sighting that seemed odd. It must have been a couple weeks ago, but some of their agents had gathered around Addle's Stead. From the report, I'd guessed something big went down. Why don't you check there first and bring me back anything you find? The farmstead is south of the road from Westfall just as you enter Duskwood.]],logDesc=[[Find the Defias Docket and return it to Watcher Backus in Duskwood.]]}
DB[1245]={id=1245,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=30,minLevel=28,giver=[[Watcher Backus]],giver_loc=[[Vigía Backus]],giverType=[[NPC]],giverId=840,ender=[[Elling Trias]],ender_loc=[[Elling Trias]],enderType=[[NPC]],enderId=482,prevId=1244,rewardNextId=1246,poiX=-8854,poiY=576,wowhead=[[https://www.wowhead.com/wotlk/quest=1245]],image=[[assets/images/quests/placeholder.png]],desc=[[Whoa, this looks way too complex to be something to just lead you astray. I shouldn't even be looking at this stuff. Take it to Trias--he'll be able to make sense of it. And DON'T let anyone get in your way. This is bigger than me. It might even be bigger than him, but we'll see. And do me a favor, $N, don't tell anyone I helped you. If my superiors found out I knew about any of this and didn't share it with them they'd probably hang me.]],logDesc=[[Bring the Defias Docket to Elling Trias in Stormwind.]]}
DB[1246]={id=1246,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=31,minLevel=28,giver=[[Elling Trias]],giver_loc=[[Elling Trias]],giverType=[[NPC]],giverId=482,ender=[[Dashel Stonefist]],ender_loc=[[Dashel Puñopiedra]],enderType=[[NPC]],enderId=4961,prevId=1245,rewardNextId=1447,poiX=-8681,poiY=433,wowhead=[[https://www.wowhead.com/wotlk/quest=1246]],image=[[assets/images/quests/placeholder.png]],desc=[[Yeah, now that I think about it... Dashel... Dashel something... What was his name? FIST! Dashel Stonefist. They call him Fist in some circles--probably on account that he likes to get in brawls. You can find him in Old Town usually--right smack dab in the center of it. Go talk to him. If you have to, use a sword or something heavy and blunt to persuade him to open up some. And don't hesitate. If he's in this as deep as these papers suggest, then he's not going to give you any information willingly.]],logDesc=[[Speak to Dashel Stonefist in Stormwind.]]}
DB[1247]={id=1247,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=31,minLevel=28,giver=[[Dashel Stonefist]],giver_loc=[[Dashel Puñopiedra]],giverType=[[NPC]],giverId=4961,ender=[[Elling Trias]],ender_loc=[[Elling Trias]],enderType=[[NPC]],enderId=482,prevId=1447,rewardNextId=1248,poiX=-8854,poiY=576,wowhead=[[https://www.wowhead.com/wotlk/quest=1247]],image=[[assets/images/quests/placeholder.png]],desc=[[So yeah... um... I might know something 'bout that meeting at Addle's Stead. Happened a few weeks back I think. I really didn't have any part in it. Me part was done when plan A failed... damn adventurers. The guy we got on the inside for plan B came out of Menethil; guy called Slim. That's all I know regarding their backup plan.]],logDesc=[[Speak to Elling Trias in Stormwind.]]}
DB[1248]={id=1248,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=33,minLevel=28,giver=[[Elling Trias]],giver_loc=[[Elling Trias]],giverType=[[NPC]],giverId=482,ender=[[Mikhail]],ender_loc=[[Mikhail]],enderType=[[NPC]],enderId=4963,prevId=1247,rewardNextId=1249,poiX=-3823,poiY=-828,wowhead=[[https://www.wowhead.com/wotlk/quest=1248]],image=[[assets/images/quests/placeholder.png]],desc=[[A contact of mine retired in the Wetlands at the harbor city of Menethil. He should be willing to help on your word alone if you tell him you're working for me. His name is Mikhail. He mentioned becoming a bartender before leaving Stormwind a few years ago. Speak to him, find this Slim, and find out if there's anything else to know about this kidnapped diplomat. We need to find out where they've taken him, or at least who he is. The docket doesn't mention anything about their plans after he's captured.]],logDesc=[[Speak to Mikhail in the Wetlands.]]}
DB[1249]={id=1249,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=33,minLevel=28,giver=[[Mikhail]],giver_loc=[[Mikhail]],giverType=[[NPC]],giverId=4963,ender=[[Mikhail]],ender_loc=[[Mikhail]],enderType=[[NPC]],enderId=4963,prevId=1248,nextId=1250,poiX=-3809,poiY=-826,wowhead=[[https://www.wowhead.com/wotlk/quest=1249]],image=[[assets/images/quests/placeholder.png]],desc=[[You say Elling sent you here? Well then, the hospitality I expressed is now tenfold. Anything you need, just ask. I will do my best to aid you. Hmm, Slim, you say? Not sure the name sounds familiar, but I'll keep my eyes out for him. Don't look now, $N, but the gentleman over by the exit is looking over here. He's listening to our conversation a little too intently if you catch my meaning? If I were you, I'd do what you can to subdue him before he makes a break for the door.]],logDesc=[[Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil.]]}
DB[1250]={id=1250,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=33,minLevel=28,giver=[[Tapoke "Slim" Jahn]],giver_loc=[[Tapoke "El Flaco" Jahn]],giverType=[[NPC]],giverId=4962,ender=[[Mikhail]],ender_loc=[[Mikhail]],enderType=[[NPC]],enderId=4963,prevId=1249,rewardNextId=1264,poiX=-3823,poiY=-828,wowhead=[[https://www.wowhead.com/wotlk/quest=1250]],image=[[assets/images/quests/placeholder.png]],desc=[[The Defias didn't pay me well enough to die for their cause. They took the king. Yeah, the king of Stormwind, not some lowly diplomat. He was on his way to Theramore to meet with Jaina Proudmore--it was a big deal apparently, and a big secret. But it's not just the Defias that are involved. They're working with someone. I think they knew this was bigger than them. My part was just to get their man on board the king's ship while it was in the harbor. The guy's name was Hendel. That's all I know. I swear!]],logDesc=[[Speak to Mikhail in the Wetlands.]]}
DB[1251]={id=1251,zoneId=15,name=[[The Black Shield]],name_loc=[[El escudo negro]],level=35,minLevel=30,giver=[[Black Shield]],giver_loc=[[Escudo negro]],giverType=[[GO]],giverId=20992,ender=[[Krog]],enderType=[[NPC]],enderId=4926,rewardNextId=1321,poiX=-3149,poiY=-2887,wowhead=[[https://www.wowhead.com/wotlk/quest=1251]],image=[[assets/images/quests/placeholder.png]],desc=[[An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn. The shield can be removed from the brick of the chimney.]],logDesc=[[Bring the Blackened Iron Shield to Krog in Brackenwall Village.]]}
DB[1252]={id=1252,zoneId=15,name=[[Lieutenant Paval Reethe]],name_loc=[[Teniente Paval Reethe]],level=35,minLevel=30,giver=[[Theramore Guard Badge]],giver_loc=[[Identificación de guardia de Theramore]],giverType=[[GO]],giverId=21042,ender=[[Captain Garran Vimes]],ender_loc=[[Capitán Garran Vimes]],enderType=[[NPC]],enderId=4944,rewardNextId=1259,poiX=-3735,poiY=-4556,wowhead=[[https://www.wowhead.com/wotlk/quest=1252]],image=[[assets/images/quests/placeholder.png]],desc=[[A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore. Underneath the anchor is embossed the name "Lieutenant Paval Reethe".]],logDesc=[[Bring Reethe's Badge to Captain Garran Vimes in Theramore.]]}
DB[1253]={id=1253,zoneId=15,name=[[The Black Shield]],name_loc=[[El escudo negro]],level=35,minLevel=30,giver=[[Black Shield]],giver_loc=[[Escudo negro]],giverType=[[GO]],giverId=20992,ender=[[Captain Garran Vimes]],ender_loc=[[Capitán Garran Vimes]],enderType=[[NPC]],enderId=4944,rewardNextId=1319,poiX=-3735,poiY=-4556,wowhead=[[https://www.wowhead.com/wotlk/quest=1253]],image=[[assets/images/quests/placeholder.png]],desc=[[An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn. The shield can be removed from the brick of the chimney.]],logDesc=[[Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.]]}
DB[1258]={id=1258,zoneId=15,name=[[... and Bugs]],name_loc=[[...con tropezones]],level=40,minLevel=33,giver=[[Morgan Stern]],giverType=[[NPC]],giverId=4794,ender=[[Morgan Stern]],enderType=[[NPC]],enderId=4794,prevId=1204,nextId=1271,exGroup=-1222,poiX=-3625,poiY=-4458,wowhead=[[https://www.wowhead.com/wotlk/quest=1258]],image=[[assets/images/quests/placeholder.png]],desc=[[Another component of my new recipe is the shelled leg of a giant crab.  And the crabs they have in Dustwallow -- Muckshells they call them -- just won't do!  I'm afraid the only suitable crabs live far away, in the Swamp of Sorrows. The shell of the crab leg is a key element of the dish's presentation so I need pristine, unscarred legs.  An adult crab might only have one or two such legs, and I need a lot in order to research my dish. So, $N... are you willing to travel?]],logDesc=[[Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore.]],rewards={{id=6801,qty=1}}}
DB[1259]={id=1259,zoneId=15,name=[[Lieutenant Paval Reethe]],name_loc=[[Teniente Paval Reethe]],level=40,minLevel=30,giver=[[Captain Garran Vimes]],giver_loc=[[Capitán Garran Vimes]],giverType=[[NPC]],giverId=4944,ender=[[Adjutant Tesoran]],ender_loc=[[Ayudante Tesoran]],enderType=[[NPC]],enderId=4948,prevId=1252,rewardNextId=1285,poiX=-3717,poiY=-4547,wowhead=[[https://www.wowhead.com/wotlk/quest=1259]],image=[[assets/images/quests/placeholder.png]],desc=[[I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment. He should be able to tell you who this Reethe is with a quick check of his books.]],logDesc=[[Find out more about Reethe from Adjutant Tesoran in Theramore.]]}
DB[1260]={id=1260,zoneId=15,name=[[Morgan Stern]],name_loc=[[Morgan Stern]],level=38,minLevel=33,giver=[[Angus Stern]],giver_loc=[[Angus Stern]],giverType=[[NPC]],giverId=1141,ender=[[Morgan Stern]],enderType=[[NPC]],enderId=4794,rewardNextId=1204,poiX=-3625,poiY=-4458,wowhead=[[https://www.wowhead.com/wotlk/quest=1260]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm developing a new menu for the restaurant.  It will be filled with rural dishes with a "bayou" theme.  I think my clientele at the Blue Recluse will love them! I sent my nephew Morgan to Theramore, a city on the edge of the Dustwallow Marsh.  He's there gathering recipes from the locals, and I must know what he found so far. The trip to Theramore is long.  Too long for me.  But I bet a young $c like yourself would jump at the chance to travel, yes?]],logDesc=[[Speak with Morgan Stern in Theramore.]]}
DB[1261]={id=1261,zoneId=15,name=[[Marg Speaks]],name_loc=[[Las declaraciones de Marg]],level=40,minLevel=30,giver=[[Bubbling Cauldron]],giver_loc=[[Caldera burbujeante]],giverType=[[GO]],giverId=2076,ender=[[Nazeer Bloodpike]],ender_loc=[[Nazeer Picasangre]],enderType=[[NPC]],enderId=4791,prevId=1240,rewardNextId=1262,poiX=-4313,poiY=-4483,wowhead=[[https://www.wowhead.com/wotlk/quest=1261]],image=[[assets/images/quests/placeholder.png]],desc=[[Cursed muckshell!  You can't kill Marg!  Ah, but I am dead.  So it must have slain me... But my mission!  My mission!  You, $N, must complete it. While near Theramore, I spied a group of Alliance soldiers camped on the beach.  And one soldier wore a pendant... a pendant laden with more gems than any soldier could afford! That night I snuck into their camp and stole the pendant, but on my return to base a muckshell crab-man killed me! $N, you must find that muckshell and recover the pendant!]],logDesc=[[Bring the Jeweled Pendant to Nazeer in Brackenwall Village.]]}
DB[1262]={id=1262,zoneId=15,name=[[Report to Zor]],name_loc=[[Informa a Zor]],level=40,minLevel=30,giver=[[Nazeer Bloodpike]],giver_loc=[[Nazeer Picasangre]],giverType=[[NPC]],giverId=4791,ender=[[Zor Lonetree]],ender_loc=[[Zor Árbol Solitario]],enderType=[[NPC]],enderId=4047,prevId=1261,poiX=1915,poiY=-4227,wowhead=[[https://www.wowhead.com/wotlk/quest=1262]],image=[[assets/images/quests/placeholder.png]],desc=[[It is strange that the pendant Marg stole was in the hands of common soldiers.  Perhaps its owner was in disguise, or perhaps the soldiers themselves stole it! Regardless of which is true, this is a noble's pendant and we must discover its true owner if we are to unravel its mystery. Take the pendant to Zor Lonetree in Orgrimmar.  He is well schooled in Alliance politics, and will know if this pendant has a history among the nobles of Stormwind.]],logDesc=[[Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar.]]}
DB[1264]={id=1264,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=33,minLevel=28,giver=[[Mikhail]],giver_loc=[[Mikhail]],giverType=[[NPC]],giverId=4963,ender=[[Commander Samaul]],ender_loc=[[Comandante Samaul]],enderType=[[NPC]],enderId=4964,prevId=1250,rewardNextId=1265,poiX=-3738,poiY=-4546,wowhead=[[https://www.wowhead.com/wotlk/quest=1264]],image=[[assets/images/quests/placeholder.png]],desc=[[The beginning of every month the Kul Tiras Marines all get paid and usually leave Theramore for somewhere else. A lot of them come here to womanize, carouse, and just have a good time. One of those groups I'd consider regulars here at the tavern, and I believe this Hendel is among them. Commander Samaul in Theramore would be able to help you find him if Hendel's still stationed there. He's completely loyal to Proudmoore, but if you drop Elling's name, he should help you out... discreetly.]],logDesc=[[Find Commander Samaul in Dustwallow Marsh.]]}
DB[1265]={id=1265,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=35,minLevel=28,giver=[[Commander Samaul]],giver_loc=[[Comandante Samaul]],giverType=[[NPC]],giverId=4964,ender=[[Archmage Tervosh]],ender_loc=[[Archimago Tervosh]],enderType=[[NPC]],enderId=4967,prevId=1264,rewardNextId=1266,poiX=-3465,poiY=-4176,wowhead=[[https://www.wowhead.com/wotlk/quest=1265]],image=[[assets/images/quests/placeholder.png]],desc=[[Hendel? Yes, I know the man. But why would you need one of my soldiers? Elling sent you to find him? Hmm, I don't like the sound of that. Elling wouldn't have you come to me first if your business wasn't troubling. I understand if you can't tell me what this is about, but know this: I have a duty to protect these lands. If you're going to cause a disturbance, then I suggest you inform me of whatever you can. I believe Hendel was stationed at the first tower outside of Theramore. Be cautious.]],logDesc=[[Search Sentry Point for any sign of Private Hendel.]]}
DB[1266]={id=1266,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=36,minLevel=28,giver=[[Archmage Tervosh]],giver_loc=[[Archimago Tervosh]],giverType=[[NPC]],giverId=4967,ender=[[Private Hendel]],ender_loc=[[Soldado Hendel]],enderType=[[NPC]],enderId=4966,prevId=1265,poiX=-2896,poiY=-3350,wowhead=[[https://www.wowhead.com/wotlk/quest=1266]],image=[[assets/images/quests/placeholder.png]],desc=[[Private Hendel is to the west of here. He's currently on guard duty protecting some of Theramore's infiltrators while they rest. They've been keeping tabs on the Horde base, Brackenwall, and looking for anything else that might threaten our borders. You should have no problem finding him; just look for the tents along the road. I have another matter to attend to, but I shall catch up to you soon enough. You can always find me in the Lady Proudmoore's tower if you have any problems.]],logDesc=[[Find Private Hendel in Dustwallow Marsh.]]}
DB[1267]={id=1267,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=38,minLevel=28,giver=[[Lady Jaina Proudmoore]],giver_loc=[[Lady Jaina Valiente]],giverType=[[NPC]],giverId=4968,ender=[[Lady Jaina Proudmoore]],ender_loc=[[Lady Jaina Valiente]],enderType=[[NPC]],enderId=4968,prevId=1324,poiX=-3750,poiY=-4454,wowhead=[[https://www.wowhead.com/wotlk/quest=1267]],image=[[assets/images/quests/placeholder.png]],logDesc=[[Speak to Jaina Proudmore in Dustwallow Swamp.]],rewards={{id=6757,qty=1}}}
DB[1268]={id=1268,zoneId=15,name=[[Suspicious Hoofprints]],name_loc=[[Huellas de pezuñas sospechosas]],level=35,minLevel=30,giver=[[Suspicious Hoofprint]],giver_loc=[[Huella de casco sospechosa]],giverType=[[GO]],giverId=187273,ender=[[Krog]],enderType=[[NPC]],enderId=4926,poiX=-3149,poiY=-2887,wowhead=[[https://www.wowhead.com/wotlk/quest=1268]],image=[[assets/images/quests/placeholder.png]],desc=[[Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.]],logDesc=[[Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.]]}
DB[1269]={id=1269,zoneId=15,name=[[Lieutenant Paval Reethe]],name_loc=[[Teniente Paval Reethe]],level=37,minLevel=30,giver=[[Theramore Guard Badge]],giver_loc=[[Identificación de guardia de Theramore]],giverType=[[GO]],giverId=21042,ender=[[Krog]],enderType=[[NPC]],enderId=4926,poiX=-3149,poiY=-2887,wowhead=[[https://www.wowhead.com/wotlk/quest=1269]],image=[[assets/images/quests/placeholder.png]],desc=[[A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore. Underneath the anchor is embossed the name "Lieutenant Paval Reethe".]],logDesc=[[Bring Reethe's Badge to Krog in Brackenwall Village.]]}
DB[1270]={id=1270,zoneId=15,name=[[Stinky's Escape]],name_loc=[[La fuga de Apestoso]],level=37,minLevel=30,giver=[["Stinky" Ignatz]],giver_loc=[["Apestoso" Ignatz]],giverType=[[NPC]],giverId=4880,ender=[[Mebok Mizzyrix]],enderType=[[NPC]],enderId=3446,poiX=-929,poiY=-3697,wowhead=[[https://www.wowhead.com/wotlk/quest=1270]],image=[[assets/images/quests/placeholder.png]],desc=[[Great, finally something that doesn't want to eat me!! I need help handling the critters around here, and you fit the mold, $gbuddy:lady;. A goblin from Ratchet named Mebok Mizzyrix needs some bogbean leaves for a potion, or something... I honestly don't care why -- his money was good and I know this swamp, so here I am. Too bad I got myself surrounded before I found the bogbean!  Can you help me out of here, and watch my back as I look for Mebok's plant?]],logDesc=[[Escort "Stinky" Ignatz, then speak with Mebok Mizzyrix in Ratchet.]],rewards={{id=3825,qty=1}}}
DB[1271]={id=1271,zoneId=15,name=[[Feast at the Blue Recluse]],name_loc=[[¡Una fiesta en tu honor!]],level=37,minLevel=30,giver=[[Angus Stern]],giver_loc=[[Angus Stern]],giverType=[[NPC]],giverId=1141,ender=[[Angus Stern]],ender_loc=[[Angus Stern]],enderType=[[NPC]],enderId=1141,poiX=-9080,poiY=823,wowhead=[[https://www.wowhead.com/wotlk/quest=1271]],image=[[assets/images/quests/placeholder.png]],rewards={{id=5951,qty=1}}}
DB[1273]={id=1273,zoneId=15,name=[[Questioning Reethe]],name_loc=[[El interrogatorio de Reethe]],level=37,minLevel=30,giver=[[Ogron]],giverType=[[NPC]],giverId=4983,ender=[[Krog]],enderType=[[NPC]],enderId=4926,prevId=1269,poiX=-3366,poiY=-3214,wowhead=[[https://www.wowhead.com/wotlk/quest=1273]],image=[[assets/images/quests/placeholder.png]],desc=[[It took a long time, but I found Reethe. He hide good for a human. Ogron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.]],logDesc=[[Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village.]],choiceRewards={{id=6797,qty=1},{id=6798,qty=1}}}
DB[1274]={id=1274,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=28,minLevel=28,giver=[[Thomas]],giver_loc=[[Thomas]],giverType=[[NPC]],giverId=4982,ender=[[Bishop DeLavey]],ender_loc=[[Obispo DeLavey]],enderType=[[NPC]],enderId=4960,rewardNextId=1241,poiX=-8507,poiY=328,wowhead=[[https://www.wowhead.com/wotlk/quest=1274]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me, $g sir : madam;. Bishop DeLavey asked me to approach adventurers that might be able to help him with a delicate matter. If you could quietly head to Stormwind Keep and speak to him at your earliest convenience, I'm sure he would appreciate your help. Again, please be discreet. It is a matter of some importance.]],logDesc=[[Find Bishop DeLavey in Stormwind Keep.]]}
DB[1275]={id=1275,zoneId=719,name=[[Researching the Corruption]],name_loc=[[Investigaciones acerca de la corrupción]],level=24,minLevel=18,giver=[[Gershala Nightwhisper]],giver_loc=[[Gershala Susurro Nocturno]],giverType=[[NPC]],giverId=8997,ender=[[Gershala Nightwhisper]],ender_loc=[[Gershala Susurro Nocturno]],enderType=[[NPC]],enderId=8997,prevId=3765,poiX=4254,poiY=666,wowhead=[[https://www.wowhead.com/wotlk/quest=1275]],image=[[assets/images/quests/placeholder.png]],desc=[[Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor? I fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters. I wish to study the brain stems of the satyr and naga so that I might deduce what fate the elves are headed toward. In Blackfathom Deeps, on the coast of Ashenvale, you will find both satyr and naga. 'Tis a long journey, $n.]],logDesc=[[Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems.]],choiceRewards={{id=7003,qty=1},{id=7004,qty=1}}}
DB[1276]={id=1276,zoneId=15,name=[[The Black Shield]],name_loc=[[El escudo negro]],level=37,minLevel=30,giver=[[Krog]],giverType=[[NPC]],giverId=4926,ender=[[Mosarn]],enderType=[[NPC]],enderId=4943,prevId=1323,nextId=11204,poiX=-1412,poiY=-47,wowhead=[[https://www.wowhead.com/wotlk/quest=1276]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before. In thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work. Perhaps he can tell you more about the shield he crafted. It's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.]],logDesc=[[Show the Blackened Iron Shield to Mosarn in Thunder Bluff.]]}
DB[1282]={id=1282,zoneId=15,name=[[They Call Him Smiling Jim]],name_loc=[[Le llaman Jim Sonrisas]],level=35,minLevel=30,giver=[[Guard Byron]],giver_loc=[[Guardia Byron]],giverType=[[NPC]],giverId=4921,ender=[[Captain Garran Vimes]],ender_loc=[[Capitán Garran Vimes]],enderType=[[NPC]],enderId=4944,nextId=11123,rewardNextId=11123,exGroup=1282,poiX=-3735,poiY=-4556,wowhead=[[https://www.wowhead.com/wotlk/quest=1282]],image=[[assets/images/quests/placeholder.png]],desc=[[I can't help it if I feel sorry for ol' Jim there. He wasn't always like that. Ran an inn out in the marsh for a while, wonderful place. Look, I don't really want to talk about it. Bring it up with Captain Vimes if you really have to. He's stationed on the top floor of Foothold Citadel, the large barracks to the east of Lady Jaina's tower.]],logDesc=[[Speak with Captain Garran Vimes on the top floor of Foothold Citadel.]]}
DB[1283]={id=1283,zoneId=15,name=[[Fire at the Shady Rest <CHANGE TO GOSSIP>]],name_loc=[[El incendio de Reposo Umbrío <CHANGE TO GOSSIP>]],level=35,minLevel=30,giverType=[[NPC]],enderType=[[NPC]],poiX=-3735,poiY=-4556,wowhead=[[https://www.wowhead.com/wotlk/quest=1283]],image=[[assets/images/quests/placeholder.png]]}
DB[1284]={id=1284,zoneId=15,name=[[Suspicious Hoofprints]],name_loc=[[Huellas de pezuñas sospechosas]],level=35,minLevel=30,giver=[[Suspicious Hoofprint]],giver_loc=[[Huella de casco sospechosa]],giverType=[[GO]],giverId=187273,ender=[[Captain Garran Vimes]],ender_loc=[[Capitán Garran Vimes]],enderType=[[NPC]],enderId=4944,poiX=-3735,poiY=-4556,wowhead=[[https://www.wowhead.com/wotlk/quest=1284]],image=[[assets/images/quests/placeholder.png]],desc=[[Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.]],logDesc=[[Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.]]}
DB[1285]={id=1285,zoneId=15,name=[[Daelin's Men]],name_loc=[[Los hombres de Daelin]],level=38,minLevel=30,giver=[[Adjutant Tesoran]],giver_loc=[[Ayudante Tesoran]],giverType=[[NPC]],giverId=4948,ender=[[Captain Garran Vimes]],ender_loc=[[Capitán Garran Vimes]],enderType=[[NPC]],enderId=4944,prevId=1259,rewardNextId=1286,poiX=-3735,poiY=-4556,wowhead=[[https://www.wowhead.com/wotlk/quest=1285]],image=[[assets/images/quests/placeholder.png]],desc=[[Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe. Joined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions... Listed as missing.]],logDesc=[[Return the information about Reethe to Captain Garran Vimes in Theramore.]]}
DB[1286]={id=1286,zoneId=15,name=[[The Deserters]],name_loc=[[Los desertores]],level=38,minLevel=30,giver=[[Captain Garran Vimes]],giver_loc=[[Capitán Garran Vimes]],giverType=[[NPC]],giverId=4944,ender=[[Balos Jacken]],enderType=[[NPC]],enderId=5089,prevId=1285,rewardNextId=1287,poiX=-3934,poiY=-2870,wowhead=[[https://www.wowhead.com/wotlk/quest=1286]],image=[[assets/images/quests/placeholder.png]],desc=[[It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area. The latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn. The local lieutenant seems to be Balos Jacken. See if you can get some information out of him. Be warned, $n. He may be a tough nut to crack.]],logDesc=[[Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.]]}
DB[1287]={id=1287,zoneId=15,name=[[The Deserters]],name_loc=[[Los desertores]],level=38,minLevel=30,giver=[[Balos Jacken]],giverType=[[NPC]],giverId=5089,ender=[[Captain Garran Vimes]],ender_loc=[[Capitán Garran Vimes]],enderType=[[NPC]],enderId=4944,prevId=1286,poiX=-3735,poiY=-4556,wowhead=[[https://www.wowhead.com/wotlk/quest=1287]],image=[[assets/images/quests/placeholder.png]],desc=[[Reethe? That coward? We threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes. He crossed the line one too many times, so we left him to fend for himself. Now, I helped you out... So, why don't you help us out and forget you bumped into us?]],logDesc=[[Speak with Captain Garran Vimes in Theramore about Reethe.]]}
DB[1288]={id=1288,zoneId=15,name=[[Vimes's Report]],name_loc=[[El informe de Vimes]],level=38,minLevel=30,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=1289,poiX=-3750,poiY=-4454,wowhead=[[https://www.wowhead.com/wotlk/quest=1288]],image=[[assets/images/quests/placeholder.png]],desc=[[You've done some good work, $n, best I've seen from an amateur. Lady Proudmoore asked that I keep her apprised of this delicate situation, and I haven't spoken to her for some time now. I was going to deliver my report to her later, but it seems more fitting that you should be the one to speak with her about it. You can probably answer her questions better than I could.]],logDesc=[[Bring Vimes's Report to Lady Jaina Proudmoore in Theramore.]]}
DB[1301]={id=1301,zoneId=1519,name=[[James Hyal]],name_loc=[[James Hyal]],level=35,minLevel=30,giver=[[Connor Rivers]],giver_loc=[[Connor Ríos]],giverType=[[NPC]],giverId=5081,ender=[[Vincent Hyal]],enderType=[[NPC]],enderId=5082,rewardNextId=1302,poiX=-3850,poiY=-736,wowhead=[[https://www.wowhead.com/wotlk/quest=1301]],image=[[assets/images/quests/placeholder.png]],desc=[[Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him. I wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently. If you ever happen to be headed in that direction, maybe you could say hello to him for me?]],logDesc=[[Speak with Vincent Hyal in Menethil Harbor.]]}
DB[1302]={id=1302,zoneId=11,name=[[James Hyal]],name_loc=[[James Hyal]],level=35,minLevel=30,giver=[[Vincent Hyal]],giverType=[[NPC]],giverId=5082,ender=[[Clerk Lendry]],ender_loc=[[Secretario Lendry]],enderType=[[NPC]],enderId=5083,nextId=11123,exGroup=1282,poiX=-3722,poiY=-4539,wowhead=[[https://www.wowhead.com/wotlk/quest=1302]],image=[[assets/images/quests/placeholder.png]],desc=[[My brother James went with Lady Proudmoore across the sea. Last I heard, the fighting had settled down over there, and James was setting up an inn somewhere on the continent. Wherever he is, I'm sure he's doing good business. Damn fine cook he was. I haven't heard from him for a while now--too busy with his inn, I'd wager--but the clerk in Theramore could probably point you to him. Look for him on the top floor of that keep near the middle of the city. What's it called... Foothold Citadel, that's it.]],logDesc=[[Speak with Clerk Lendry at Foothold Citadel in Theramore.]]}
DB[1318]={id=1318,zoneId=2557,name=[[Unfinished Gordok Business]],name_loc=[[Asuntos Pendientes con Gordok]],level=60,minLevel=56,giver=[[Captain Kromcrush]],giver_loc=[[Capitán Kromcrush]],giverType=[[NPC]],giverId=14325,ender=[[Captain Kromcrush]],ender_loc=[[Capitán Kromcrush]],enderType=[[NPC]],enderId=14325,poiX=116,poiY=639,wowhead=[[https://www.wowhead.com/wotlk/quest=1318]],image=[[assets/images/quests/placeholder.png]],desc=[[Now you da king, so maybe you get prized Gordok artifact back from creepy elf who calls himself Prince!  Da king before you failed, just like all da other kings since Tortheldrin - da creepy elf - stole it from old timey Gordok king! Artifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  Old timey story also say creepy elf is still around here - you find it and it will become mighty gauntlet you wear forever!  Yar, I show you!]],logDesc=[[Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul. According to Kromcrush, the "old timey story" says that Tortheldrin - a "creepy" elf who called himself a prince - stole it from one of the Gordok kings.]],choiceRewards={{id=18366,qty=1},{id=18367,qty=1},{id=18368,qty=1},{id=18369,qty=1}}}
DB[1319]={id=1319,zoneId=15,name=[[The Black Shield]],name_loc=[[El escudo negro]],level=35,minLevel=30,giver=[[Captain Garran Vimes]],giver_loc=[[Capitán Garran Vimes]],giverType=[[NPC]],giverId=4944,ender=[[Caz Twosprocket]],ender_loc=[[Caz Dosdientes]],enderType=[[NPC]],enderId=4941,prevId=1253,rewardNextId=1320,poiX=-3798,poiY=-4375,wowhead=[[https://www.wowhead.com/wotlk/quest=1319]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm sorry I can't be of much help, $n, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy. Take the shield to him, and see what he can tell you.]],logDesc=[[Show the Blackened Iron Shield to Caz Twosprocket in Theramore.]]}
DB[1320]={id=1320,zoneId=15,name=[[The Black Shield]],name_loc=[[El escudo negro]],level=35,minLevel=30,giver=[[Caz Twosprocket]],giver_loc=[[Caz Dosdientes]],giverType=[[NPC]],giverId=4941,ender=[[Captain Garran Vimes]],ender_loc=[[Capitán Garran Vimes]],enderType=[[NPC]],enderId=4944,prevId=1319,poiX=-3735,poiY=-4556,wowhead=[[https://www.wowhead.com/wotlk/quest=1320]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually. That's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help.]],logDesc=[[Speak with Captain Garran Vimes in Theramore.]]}
DB[1321]={id=1321,zoneId=15,name=[[The Black Shield]],name_loc=[[El escudo negro]],level=35,minLevel=30,giver=[[Krog]],giverType=[[NPC]],giverId=4926,ender=[[Do'gol]],enderType=[[NPC]],enderId=5087,prevId=1251,rewardNextId=1322,poiX=-3111,poiY=-2893,wowhead=[[https://www.wowhead.com/wotlk/quest=1321]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...]],logDesc=[[Show the Blackened Iron Shield to Do'gol in Brackenwall Village.]]}
DB[1322]={id=1322,zoneId=15,name=[[The Black Shield]],name_loc=[[El escudo negro]],level=37,minLevel=30,giver=[[Do'gol]],giverType=[[NPC]],giverId=5087,ender=[[Do'gol]],enderType=[[NPC]],enderId=5087,prevId=1321,rewardNextId=1323,poiX=-2750,poiY=-2852,wowhead=[[https://www.wowhead.com/wotlk/quest=1322]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff. I need acid to make it clear. Venom from the darkmist spiders would do good. The spiders have taken over an old mine, the Darkmist Cavern, northwest of the village. Get me some of their sacs and I can clean this up.]],logDesc=[[Acquire 5 Acidic Venom Sacs for Do'gol in Brackenwall Village.]]}
DB[1323]={id=1323,zoneId=15,name=[[The Black Shield]],name_loc=[[El escudo negro]],level=37,minLevel=30,giver=[[Do'gol]],giverType=[[NPC]],giverId=5087,ender=[[Krog]],enderType=[[NPC]],enderId=4926,prevId=1322,poiX=-3149,poiY=-2887,wowhead=[[https://www.wowhead.com/wotlk/quest=1323]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little... Hm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.]],logDesc=[[Talk with Krog in Brackenwall Village.]]}
DB[1324]={id=1324,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=38,minLevel=28,giver=[[Private Hendel]],giver_loc=[[Soldado Hendel]],giverType=[[NPC]],giverId=4966,ender=[[Archmage Tervosh]],ender_loc=[[Archimago Tervosh]],enderType=[[NPC]],enderId=4967,prevId=1266,poiX=-2896,poiY=-3350,wowhead=[[https://www.wowhead.com/wotlk/quest=1324]],image=[[assets/images/quests/placeholder.png]],desc=[[What?! You come here accusing me of allying with the Defias, and think I'll just stand here while you insult me?! Something tells me you've had this coming for a long time.]],logDesc=[[Defeat Private Hendel in Dustwallow Marsh.]]}
DB[1338]={id=1338,zoneId=38,name=[[Stormpike's Order]],name_loc=[[Un pedido de Pico Tormenta]],level=14,minLevel=9,giver=[[Mountaineer Stormpike]],giver_loc=[[Montaraz Pico Tormenta]],giverType=[[NPC]],giverId=1343,ender=[[Furen Longbeard]],ender_loc=[[Furen Barbalarga]],enderType=[[NPC]],enderId=5413,poiX=-8427,poiY=600,wowhead=[[https://www.wowhead.com/wotlk/quest=1338]],image=[[assets/images/quests/placeholder.png]],desc=[[There is a dwarven armorsmith whose work I admire greatly.  His name is Furen Longbeard, and his skill is unmatched.  I need a new shield, and I must have one of his! The problem is... Furen is far to the south, in the dwarven district within Stormwind.  In human lands!  I can't imagine why he would live there, so far from Ironforge.  The humans must pay him a king's ransom to keep him there! So, if you want to travel and don't mind making some money, then will you send Furen my request for a shield?]],logDesc=[[Bring Stormpike's Request to Furen Longbeard in Stormwind.]]}
DB[1339]={id=1339,zoneId=38,name=[[Mountaineer Stormpike's Task]],name_loc=[[La tarea del montaraz Pico Tormenta]],level=15,minLevel=9,giver=[[Mountaineer Kadrell]],giver_loc=[[Montaraz Kadrell]],giverType=[[NPC]],giverId=1340,ender=[[Mountaineer Stormpike]],ender_loc=[[Montaraz Pico Tormenta]],enderType=[[NPC]],enderId=1343,rewardNextId=1338,poiX=-4826,poiY=-2677,wowhead=[[https://www.wowhead.com/wotlk/quest=1339]],image=[[assets/images/quests/placeholder.png]],desc=[[I hear Mountaineer Stormpike is looking for a runner.  Someone to do a little traveling for him.  How about it?  Are you the $r for the job? If so, then you'll find Stormpike at the top of the northern guard tower.]],logDesc=[[Speak with Mountaineer Stormpike.]]}
DB[1358]={id=1358,zoneId=1497,name=[[Sample for Helbrim]],name_loc=[[Muestra para Helbrim]],level=15,minLevel=10,giver=[[Apothecary Zinge]],giver_loc=[[Boticaria Zinge]],giverType=[[NPC]],giverId=5204,ender=[[Apothecary Helbrim]],ender_loc=[[Boticario Helbrim]],enderType=[[NPC]],enderId=3390,prevId=1359,poiX=-425,poiY=-2590,wowhead=[[https://www.wowhead.com/wotlk/quest=1358]],image=[[assets/images/quests/placeholder.png]],desc=[[A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor.  He would be very interested in a sample of the wolf hearts Renferrel sent me. Helbrim is stationed in the Barrens, in a village known as the Crossroads.  To reach him, you must travel via zeppelin to the orc capital of Orgrimmar, then travel south, by foot, to Durotar.  Head west into the Barrens, and you will soon reach the Crossroads.]],logDesc=[[Bring the Wolf Heart Sample to Apothecary Helbrim in the Barrens.]],choiceRewards={{id=10637,qty=1},{id=10638,qty=1}}}
DB[1359]={id=1359,zoneId=1497,name=[[Zinge's Delivery]],name_loc=[[Una entrega de Zinge]],level=15,minLevel=10,giver=[[Apothecary Renferrel]],giver_loc=[[Boticario Renferrel]],giverType=[[NPC]],giverId=1937,ender=[[Apothecary Zinge]],ender_loc=[[Boticaria Zinge]],enderType=[[NPC]],enderId=5204,prevId=3221,rewardNextId=1358,poiX=1443,poiY=392,wowhead=[[https://www.wowhead.com/wotlk/quest=1359]],image=[[assets/images/quests/placeholder.png]],desc=[[The wolf hearts you acquired possess a quality unseen in similar specimens.  There is a toxicity to them that should be deadly to the very wolves in which the hearts beat! It's quite incredible, and we must study it further.  I kept a few samples of the hearts acquired.  Take them to my colleague, Apothecary Zinge.  You will find her in our headquarters in the Undercity.]],logDesc=[[Bring the Wolf Heart Samples to Apothecary Zinge in the Undercity.]]}
DB[1360]={id=1360,zoneId=1517,name=[[Reclaimed Treasures]],name_loc=[[Los tesoros reclamados]],level=43,minLevel=33,giver=[[Krom Stoutarm]],giver_loc=[[Krom Brazorrecio]],giverType=[[NPC]],giverId=6294,ender=[[Krom Stoutarm]],ender_loc=[[Krom Brazorrecio]],enderType=[[NPC]],enderId=6294,poiX=-6279,poiY=-2964,wowhead=[[https://www.wowhead.com/wotlk/quest=1360]],image=[[assets/images/quests/placeholder.png]],desc=[[I had myself a fine job as a digger at the Uldaman excavation site in the Badlands... that is until those blasted troggs showed up.  I escaped with my hide barely intact, and nothing else.  In the chaos, I left my most treasured possession.  It's safe from the troggs in my chest, sure, but it's right in the thick of 'em. I'd be in your debt, both in honor and coin, if you could fetch it for me!  A chest with my name on it is at the end of the North Common Hall.  That's the one you need to get in.]],logDesc=[[Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge.]]}
DB[1361]={id=1361,zoneId=405,name=[[Regthar Deathgate]],name_loc=[[Regthar Portamorta]],level=32,minLevel=30,giver=[[Krusk]],giverType=[[NPC]],giverId=2229,ender=[[Regthar Deathgate]],ender_loc=[[Regthar Portamorta]],enderType=[[NPC]],enderId=3389,rewardNextId=1362,poiX=-307,poiY=-1972,wowhead=[[https://www.wowhead.com/wotlk/quest=1361]],image=[[assets/images/quests/placeholder.png]],desc=[[A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads. And sharpen your weapons.  Desolace is a place torn by war.]],logDesc=[[Speak with Regthar Deathgate in the Barrens.]]}
DB[1361]={id=1361,zoneId=405,name=[[Regthar Deathgate]],name_loc=[[Regthar Portamorta]],level=32,minLevel=30,giver=[[Belgrom Rockmaul]],giverType=[[NPC]],giverId=4485,ender=[[Regthar Deathgate]],ender_loc=[[Regthar Portamorta]],enderType=[[NPC]],enderId=3389,rewardNextId=1362,poiX=-307,poiY=-1972,wowhead=[[https://www.wowhead.com/wotlk/quest=1361]],image=[[assets/images/quests/placeholder.png]],desc=[[A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads. And sharpen your weapons.  Desolace is a place torn by war.]],logDesc=[[Speak with Regthar Deathgate in the Barrens.]]}
DB[1361]={id=1361,zoneId=405,name=[[Regthar Deathgate]],name_loc=[[Regthar Portamorta]],level=32,minLevel=30,giver=[[Vol'jin]],giverType=[[NPC]],giverId=10540,ender=[[Regthar Deathgate]],ender_loc=[[Regthar Portamorta]],enderType=[[NPC]],enderId=3389,rewardNextId=1362,poiX=-307,poiY=-1972,wowhead=[[https://www.wowhead.com/wotlk/quest=1361]],image=[[assets/images/quests/placeholder.png]],desc=[[A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads. And sharpen your weapons.  Desolace is a place torn by war.]],logDesc=[[Speak with Regthar Deathgate in the Barrens.]]}
DB[1362]={id=1362,zoneId=405,name=[[The Kolkar of Desolace]],name_loc=[[Los Kolkar de Desolace]],level=32,minLevel=30,giver=[[Regthar Deathgate]],giver_loc=[[Regthar Portamorta]],giverType=[[NPC]],giverId=3389,ender=[[Felgur Twocuts]],ender_loc=[[Felgur Doscortes]],enderType=[[NPC]],enderId=5395,poiX=-1334,poiY=1707,wowhead=[[https://www.wowhead.com/wotlk/quest=1362]],image=[[assets/images/quests/placeholder.png]],desc=[[The Kolkar centaur live in Desolace, and their forces have spread into the Barrens.  This is a known fact and we have Horde agents dealing with them here. But as long as the centaur are strong in Desolace, they will always pose a threat.  It is time we rid ourselves of that threat. Speak with Felgur Twocuts at Ghost Walker Post in Desolace.  He was sent to gather intelligence on the centaur.  He will know how to best deal with the Kolkar of Desolace.]],logDesc=[[Speak with Felgur Twocuts at Ghost Walker Post in Desolace.]]}
DB[1363]={id=1363,zoneId=1519,name=[[Mazen's Behest]],name_loc=[[La orden de Mazen]],level=41,minLevel=37,giver=[[Mazen Mac'Nadir]],giver_loc=[[Mazen Mac'Nadir]],giverType=[[NPC]],giverId=338,ender=[[Acolyte Dellis]],ender_loc=[[Acólito Dellis]],enderType=[[NPC]],enderId=5386,rewardNextId=1364,poiX=-8851,poiY=830,wowhead=[[https://www.wowhead.com/wotlk/quest=1363]],image=[[assets/images/quests/placeholder.png]],desc=[[As caretaker of the works here in the library of the Academy of Arcane Arts and Sciences, it is my responsibility to ensure all the magical tomes and scrolls are accounted for at all times. Who knows what folly would unfold if some of these enchanted texts were to fall into the wrong hands? Which reminds me... my assistant, Dellis, made a horrible mistake last week. He's quite able in the library but incompetent when he leaves the gates of Stormwind. Be a hero, and help old Dellis out, would you?]],logDesc=[[Speak with Acolyte Dellis in Stormwind.]]}
DB[1364]={id=1364,zoneId=1519,name=[[Mazen's Behest]],name_loc=[[La orden de Mazen]],level=41,minLevel=37,giver=[[Acolyte Dellis]],giver_loc=[[Acólito Dellis]],giverType=[[NPC]],giverId=5386,ender=[[Watcher Mahar Ba]],ender_loc=[[Vigilante Mahar Ba]],enderType=[[NPC]],enderId=5385,prevId=1363,poiX=-10214,poiY=-2612,wowhead=[[https://www.wowhead.com/wotlk/quest=1364]],image=[[assets/images/quests/placeholder.png]],desc=[[Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep. But I had never been to the Blasted Lands before! The journey was frightening! When I got to the Swamp of Sorrows, I made a wrong turn and ended up surrounded by horrible plant-like swamp creatures. They lurched as if to attack me so I ran. But in my haste I dropped the essay. One of the beasts took it I am sure. Could you please try to retrieve it and deliver it to Mahar Ba?]],logDesc=[[Retrieve Khadgar's Essays on Dimensional Convergence and deliver them to Watcher Mahar Ba in Nethergarde Keep.]],choiceRewards={{id=10747,qty=1},{id=10748,qty=1}}}
DB[1365]={id=1365,zoneId=405,name=[[Khan Dez'hepah]],name_loc=[[Khan Dez'hepah]],level=35,minLevel=30,giver=[[Felgur Twocuts]],giver_loc=[[Felgur Doscortes]],giverType=[[NPC]],giverId=5395,ender=[[Felgur Twocuts]],ender_loc=[[Felgur Doscortes]],enderType=[[NPC]],enderId=5395,poiX=-796,poiY=934,wowhead=[[https://www.wowhead.com/wotlk/quest=1365]],image=[[assets/images/quests/placeholder.png]],desc=[[The Kolkar are not the only centaur of Desolace.  Many clans wander these dry plains, fighting and dying against each other.  And it is good that they fight among themselves, for they are strong and brutal.  If the centaur united against us, they would be a fierce foe. We must deal with them before they unite. Your first task is to disrupt the Kolkar clan.  Do this by killing its leader, Khan Dez'hepah. The Kolkar Village is northeast of here.  Go, and may fortune go with you.]],logDesc=[[Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace.]]}
DB[1366]={id=1366,zoneId=405,name=[[Centaur Bounty]],name_loc=[[Colección de orejas]],level=31,minLevel=30,giver=[[Felgur Twocuts]],giver_loc=[[Felgur Doscortes]],giverType=[[NPC]],giverId=5395,ender=[[Felgur Twocuts]],ender_loc=[[Felgur Doscortes]],enderType=[[NPC]],enderId=5395,prevId=1365,poiX=-2316,poiY=2405,wowhead=[[https://www.wowhead.com/wotlk/quest=1366]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you scared the centaur clans, it's time to bleed them.  When traveling Desolace, hunt centaur.  I don't care which clan you hunt.  Just gather ears.  A hoard of ears. By weakening their numbers you will weaken their resolve, and stamp out any thoughts of expansion. Good hunting, $N.]],logDesc=[[Bring 15 Centaur Ears to Felgur Twocuts in Desolace.]],choiceRewards={{id=6780,qty=1},{id=6784,qty=1}}}
DB[1367]={id=1367,zoneId=405,name=[[Magram Alliance]],name_loc=[[La alianza con los Magram]],level=33,minLevel=30,giver=[[Gurda Wildmane]],giver_loc=[[Gurda Bravacrín]],giverType=[[NPC]],giverId=5412,ender=[[Warug]],enderType=[[NPC]],enderId=5398,nextId=1369,rewardNextId=1369,poiX=-1591,poiY=863,wowhead=[[https://www.wowhead.com/wotlk/quest=1367]],image=[[assets/images/quests/placeholder.png]],desc=[[To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans. If you choose to ally with the Magram then slay their foes, the Gelkis.  This will earn you respect among the Magram.  When you earn enough, then meet with the Magram spokesman Warug, on the outskirts of the Magram Village, in southeast Desolace.]],logDesc=[[Gain a Friendly reputation with the Magram, then speak with Warug.]]}
DB[1368]={id=1368,zoneId=405,name=[[Gelkis Alliance]],name_loc=[[La alianza con los Gelkis]],level=33,minLevel=30,giver=[[Gurda Wildmane]],giver_loc=[[Gurda Bravacrín]],giverType=[[NPC]],giverId=5412,ender=[[Uthek the Wise]],ender_loc=[[Uthek la Sabia]],enderType=[[NPC]],enderId=5397,nextId=1370,rewardNextId=1370,poiX=-1924,poiY=2605,wowhead=[[https://www.wowhead.com/wotlk/quest=1368]],image=[[assets/images/quests/placeholder.png]],desc=[[To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans. If you choose to ally with the Gelkis then slay their most hated rival, the Magram.  After you earn the respect of the Gelkis, meet with the Gelkis shaman Uthek the Wise, on the outskirts of the Gelkis Village, in southwest Desolace.]],logDesc=[[Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.]]}
DB[1369]={id=1369,zoneId=405,name=[[Broken Tears]],name_loc=[[Lágrimas rotas]],level=33,minLevel=30,giver=[[Warug]],giverType=[[NPC]],giverId=5398,ender=[[Warug]],enderType=[[NPC]],enderId=5398,rewardNextId=1371,poiX=-2388,poiY=2398,wowhead=[[https://www.wowhead.com/wotlk/quest=1369]],image=[[assets/images/quests/placeholder.png]],desc=[[The Gelkis think our centaur mother, Theradras, protects us.  They are stupid.  No one protects the centaur.  The Magram do not need protection!  We are the strongest! Show the Gelkis they are stupid.  Go to the cave in their village.  They hoard crystals in that cave, the tears of Theradras.  Destroy the tears and bring me the broken pieces!]],logDesc=[[Maintain your reputation with the Magram, and bring 3 Broken Tears to Warug in the Magram Village.]]}
DB[1370]={id=1370,zoneId=405,name=[[Stealing Supplies]],name_loc=[[¡A robar provisiones!]],level=35,minLevel=30,giver=[[Uthek the Wise]],giver_loc=[[Uthek la Sabia]],giverType=[[NPC]],giverId=5397,ender=[[Uthek the Wise]],ender_loc=[[Uthek la Sabia]],enderType=[[NPC]],enderId=5397,rewardNextId=1373,poiX=-1726,poiY=903,wowhead=[[https://www.wowhead.com/wotlk/quest=1370]],image=[[assets/images/quests/placeholder.png]],desc=[[When we are not at war, we hunt for meat.  Meat gives us strength, and full bellies fight harder than empty ones. It is the same with the Magram.  They store extra meat so they may fight longer between hunts.  If you raid their village to the east and take their stores of meat, then their strength will fail.]],logDesc=[[Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village.]],choiceRewards={{id=32378,qty=1},{id=3464,qty=200},{id=3465,qty=200}}}
DB[1371]={id=1371,zoneId=405,name=[[Gizmo for Warug]],name_loc=[[Un cacharro para Warug]],level=35,minLevel=30,giver=[[Warug]],giverType=[[NPC]],giverId=5398,ender=[[Warug]],enderType=[[NPC]],enderId=5398,prevId=1369,poiX=-1591,poiY=863,wowhead=[[https://www.wowhead.com/wotlk/quest=1371]],image=[[assets/images/quests/placeholder.png]],desc=[[Long ago, a little gnome came to Desolace.  He had horses and a cart, and the cart held strange things.  Funny things.  Things that burned different colors.  Things that moved and weren't alive.  I killed the little gnome, but before that... he made me laugh. I kept my favorite thing from his cart.  It was a human made of wood and it waved at me until I hit it and broke it. I want a new one.  Get me a new one!]],logDesc=[[Maintain your reputation with the Magram, and bring an Advanced Target Dummy to Warug in the Magram Village in Desolace.]]}
DB[1372]={id=1372,zoneId=10,name=[[Nothing But The Truth]],name_loc=[[El suero de la verdad]],level=42,minLevel=37,giver=[[Deathstalker Zraedus]],giver_loc=[[Mortacechador Zraedus]],giverType=[[NPC]],giverId=5418,ender=[[Apothecary Faustin]],ender_loc=[[Boticario Faustin]],enderType=[[NPC]],enderId=5414,rewardNextId=1383,poiX=-10351,poiY=-1528,wowhead=[[https://www.wowhead.com/wotlk/quest=1372]],image=[[assets/images/quests/placeholder.png]],desc=[[Our expeditionary force was sent at Varimathras's behest to survey lower Azeroth. While out scouting I noticed a human Infiltrator spying on Beggar's Haunt. Before I could apprehend him, some of our orcish... brethren... captured him and took him to Stonard, their stronghold in Swamp of Sorrows. I want to... help... our orcish allies. They did not see our camp here but nonetheless I want to lend a hand. Work with Faustin here to develop a... truth serum for our friend in Stonard.]],logDesc=[[Speak with Apothecary Faustin at Beggar's Haunt.]]}
DB[1373]={id=1373,zoneId=405,name=[[Ongeku]],name_loc=[[Ongeku]],level=37,minLevel=30,giver=[[Uthek the Wise]],giver_loc=[[Uthek la Sabia]],giverType=[[NPC]],giverId=5397,ender=[[Uthek the Wise]],ender_loc=[[Uthek la Sabia]],enderType=[[NPC]],enderId=5397,prevId=1370,rewardNextId=1374,poiX=-1924,poiY=2605,wowhead=[[https://www.wowhead.com/wotlk/quest=1373]],image=[[assets/images/quests/placeholder.png]],desc=[[You have more to prove, and your next task will take you far, so for now the Gelkis will fight the Magram without you. The earth whispers many secrets to those who listen.  One secret I hear is of a red crystal.  It is called draenethyst, and it is new to our earth.  It comes from a place where mountains fly, and where demons rule. Bring me a shard of draenethyst, and it will make my magic strong!  The shard is in a place called the Swamp of Sorrows, held by the lost one Ongeku.]],logDesc=[[Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace.]]}
DB[1374]={id=1374,zoneId=405,name=[[Khan Jehn]],name_loc=[[Khan Jehn]],level=37,minLevel=30,giver=[[Uthek the Wise]],giver_loc=[[Uthek la Sabia]],giverType=[[NPC]],giverId=5397,ender=[[Uthek the Wise]],ender_loc=[[Uthek la Sabia]],enderType=[[NPC]],enderId=5397,prevId=1373,rewardNextId=1380,poiX=-1963,poiY=1268,wowhead=[[https://www.wowhead.com/wotlk/quest=1374]],image=[[assets/images/quests/placeholder.png]],desc=[[The earth speaks to me, and it says that the Magram grow weak.  Now it is time to kill their Khan! Bring me the head of the Magram Khan, Jehn!]],logDesc=[[Bring the Khan Jehn's Head to Uthek the Wise in the Gelkis Village in Desolace.]]}
DB[1375]={id=1375,zoneId=405,name=[[Khan Shaka]],name_loc=[[Khan Shaka]],level=37,minLevel=30,giver=[[Warug]],giverType=[[NPC]],giverId=5398,ender=[[Warug]],enderType=[[NPC]],enderId=5398,prevId=1371,rewardNextId=1381,poiX=-2411,poiY=2413,wowhead=[[https://www.wowhead.com/wotlk/quest=1375]],image=[[assets/images/quests/placeholder.png]],desc=[[You help the Magram, and I like you.  Now, kill the Khan of the Gelkis!  He is Khan Shaka, and I want his head!  I want to stare at his head and laugh at him!]],logDesc=[[Maintain your reputation with the Magram, and bring the Head of Khan Shaka to Warug in the Magram Village in Desolace.]]}
DB[1380]={id=1380,zoneId=405,name=[[Khan Hratha]],name_loc=[[Khan Hratha]],level=42,minLevel=30,giver=[[Uthek the Wise]],giver_loc=[[Uthek la Sabia]],giverType=[[NPC]],giverId=5397,ender=[[Uthek the Wise]],ender_loc=[[Uthek la Sabia]],enderType=[[NPC]],enderId=5397,prevId=1374,poiX=-1101,poiY=2890,wowhead=[[https://www.wowhead.com/wotlk/quest=1380]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you helped us against the Magram.  Now, help us beat the Maraudine!  Kill the head of their clan, Khan Hratha! To face him, blow the Maraudine War Horn.  It is atop a high bluff in the Valley of Spears. But to blow the horn, you must gain a warhorn mouthpiece.  These are rare, carried only by trusted Maraudine centaur. After the horn is blown, centaur will come.  Kill them until Hratha appears. Khan Hratha holds the piece of... a key.  Bring it to me...]],logDesc=[[Maintain your reputation with the Gelkis, and bring the Maraudine Key Fragment to Uthek the Wise in the Gelkis Village.]],choiceRewards={{id=6773,qty=1},{id=6774,qty=1}}}
DB[1381]={id=1381,zoneId=405,name=[[Khan Hratha]],name_loc=[[Khan Hratha]],level=42,minLevel=30,giver=[[Warug]],giverType=[[NPC]],giverId=5398,ender=[[Warug]],enderType=[[NPC]],enderId=5398,prevId=1375,poiX=-1101,poiY=2890,wowhead=[[https://www.wowhead.com/wotlk/quest=1381]],image=[[assets/images/quests/placeholder.png]],desc=[[The Gelkis Khan is dead, and now the Maraudine will fall!  Kill the Maraudine Khan, Hratha! To face him, blow the horn on the high bluff in the Valley of Spears.  But to blow the horn, you need a mouthpiece.  To get a mouthpiece, kill Maraudine centaur.  Keep killing until you find a mouthpiece.  Then blow the horn. Do this and Maraudine centaur will come to the tower.  Kill them until Khan Hratha appears.  Hratha holds the piece of a key.  Give this piece to me...]],logDesc=[[Maintain your Magram reputation, and bring the Maraudine Key Fragment to Warug in the Magram Village in Desolace.]],choiceRewards={{id=6788,qty=1},{id=6789,qty=1}}}
DB[1382]={id=1382,zoneId=405,name=[[Strange Alliance]],name_loc=[[Extraña alianza]],level=35,minLevel=30,giver=[[Captain Pentigast]],giver_loc=[[Capitán Pentigast]],giverType=[[NPC]],giverId=5396,ender=[[Uthek the Wise]],ender_loc=[[Uthek la Sabia]],enderType=[[NPC]],enderId=5397,rewardNextId=1384,poiX=-1924,poiY=2605,wowhead=[[https://www.wowhead.com/wotlk/quest=1382]],image=[[assets/images/quests/placeholder.png]],desc=[[We are fortunate the centaur clans fight among themselves, for if they joined into a single force then they would be unstoppable.  Yes, we are fortunate, and we should press our advantage. One of the centaur clans, the Gelkis clan, is in brutal war with the Magram clan.  If we attack the Magram, then perhaps an alliance may be struck with the Gelkis. Speak with Uthek the Wise, in the outskirts of the Gelkis camps in southwestern Desolace.  Through her we might strike an alliance with the Gelkis.]],logDesc=[[Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.]]}
DB[1383]={id=1383,zoneId=10,name=[[Nothing But The Truth]],name_loc=[[El suero de la verdad]],level=42,minLevel=37,giver=[[Apothecary Faustin]],giver_loc=[[Boticario Faustin]],giverType=[[NPC]],giverId=5414,ender=[[Apothecary Faustin]],ender_loc=[[Boticario Faustin]],enderType=[[NPC]],enderId=5414,prevId=1372,poiX=-9767,poiY=-3900,wowhead=[[https://www.wowhead.com/wotlk/quest=1383]],image=[[assets/images/quests/placeholder.png]],desc=[[I have just the right serum in mind. It will deal with the truth in precisely the way the truth should be dealt with. For this concoction I will need several Shadow Panther hearts from the Swamp. I also require the enchanted fungus off of the Mire Lord who resides there. I am sure one as able as you, $n, can persuade him to part with some. The last item I'll need for the serum is the blood of a dreaming whelp, like the ones that live outside Itharius' cave in the swamp. Now, off you go!]],logDesc=[[Apothecary Faustin at Beggar's Haunt needs 5 Shadow Panther Hearts, Mire Lord Fungus and some Green Whelp Blood.]],choiceRewards={{id=6832,qty=1},{id=11265,qty=1}}}
DB[1384]={id=1384,zoneId=405,name=[[Raid on the Kolkar]],name_loc=[[Asalta a los Kolkar]],level=32,minLevel=30,giver=[[Uthek the Wise]],giver_loc=[[Uthek la Sabia]],giverType=[[NPC]],giverId=5397,ender=[[Uthek the Wise]],ender_loc=[[Uthek la Sabia]],enderType=[[NPC]],enderId=5397,prevId=1382,nextId=1370,rewardNextId=1370,poiX=-1010,poiY=875,wowhead=[[https://www.wowhead.com/wotlk/quest=1384]],image=[[assets/images/quests/placeholder.png]],desc=[[The Kolkar centaurs think their magic is strong.  They do not know magic!  They would not know magic if it bit them! You will show them their magic is weak.  Go to the Kolkar  to the northeast and kill them.  Take their charms.  Bring me the charms and I will throw them in the fire and laugh!]],logDesc=[[Maintain your reputation with the Gelkis, and bring 10 Crude Charms to Uthek the Wise in the Gelkis Village in Desolace.]]}
DB[1385]={id=1385,zoneId=405,name=[[Brutal Politics]],name_loc=[[Políticas brutales]],level=35,minLevel=30,giver=[[Captain Pentigast]],giver_loc=[[Capitán Pentigast]],giverType=[[NPC]],giverId=5396,ender=[[Warug]],enderType=[[NPC]],enderId=5398,rewardNextId=1386,poiX=-1591,poiY=863,wowhead=[[https://www.wowhead.com/wotlk/quest=1385]],image=[[assets/images/quests/placeholder.png]],desc=[[Desolace is a land at war.  The centaurs wage war with each other, and we believe the victor among them will spill out and threaten our strongholds.  That, we cannot allow We must learn how to beat the centaurs, and to do that... we must ally with one of the clans.  The Magram centaurs war with the Gelkis.  If you fight the Gelkis then the Magram might consider an alliance. Earn the favor of the Magrams then speak with Warug, in the Magram village in southeastern Desolace.]],logDesc=[[Gain a Friendly reputation with the Magram, then speak with Warug.]]}
DB[1386]={id=1386,zoneId=405,name=[[Assault on the Kolkar]],name_loc=[[Ataca a los Kolkar]],level=32,minLevel=30,giver=[[Warug]],giverType=[[NPC]],giverId=5398,ender=[[Warug]],enderType=[[NPC]],enderId=5398,prevId=1385,nextId=1369,rewardNextId=1369,poiX=-726,poiY=1014,wowhead=[[https://www.wowhead.com/wotlk/quest=1386]],image=[[assets/images/quests/placeholder.png]],desc=[[The Kolkar think they are strong, but we laugh at them!  We laugh and we kill them!  You kill them too.  Show me you can kill Kolkar like we do. Head north and slay them all!]],logDesc=[[Maintain your reputation with the Magram. Kill 12 Kolkar Centaurs, 12 Kolkar Scouts and 6 Kolkar Maulers, then return to Warug in the Magram Village in Desolace.]]}
DB[1387]={id=1387,zoneId=405,name=[[Centaur Bounty]],name_loc=[[Colección de orejas]],level=31,minLevel=30,giver=[[Corporal Melkins]],giver_loc=[[Cabo Melkins]],giverType=[[NPC]],giverId=5752,ender=[[Corporal Melkins]],ender_loc=[[Cabo Melkins]],enderType=[[NPC]],enderId=5752,poiX=126,poiY=1233,wowhead=[[https://www.wowhead.com/wotlk/quest=1387]],image=[[assets/images/quests/placeholder.png]],desc=[[Many clans make up the centaur race.  Each has its own leader and agenda, but all the clans have one thing in common.  Cruelty. If we are to ever find peace, then the centaurs must be removed.  And so I put you on the task to do just that. While wandering Desolace, hunt centaur and take their ears.  Bring me many, many ears. Do this in service of the Alliance, $N, and we will be one step closer to war's end.]],logDesc=[[Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace.]],rewards={{id=6790,qty=1}}}
DB[1388]={id=1388,zoneId=10,name=[[Nothing But The Truth]],name_loc=[[El suero de la verdad]],level=42,minLevel=37,giver=[[Apothecary Faustin]],giver_loc=[[Boticario Faustin]],giverType=[[NPC]],giverId=5414,ender=[[Deathstalker Zraedus]],ender_loc=[[Mortacechador Zraedus]],enderType=[[NPC]],enderId=5418,prevId=1383,rewardNextId=1391,poiX=-10358,poiY=-1538,wowhead=[[https://www.wowhead.com/wotlk/quest=1388]],image=[[assets/images/quests/placeholder.png]],desc=[[Everything is proceeding according to plan, $n. I want you to give this truth serum to Deathstalker Zraedus and he'll show you how to administer it.... properly. Haha!]],logDesc=[[Give Faustin's Truth Serum to Deathstalker Zraedus at Beggar's Haunt.]]}
DB[1389]={id=1389,zoneId=8,name=[[Draenethyst Crystals]],name_loc=[[Cristales draenetistas]],level=35,minLevel=30,giver=[[Magtoor]],giverType=[[NPC]],giverId=1776,ender=[[Magtoor]],enderType=[[NPC]],enderId=1776,poiX=-9926,poiY=-3733,wowhead=[[https://www.wowhead.com/wotlk/quest=1389]],image=[[assets/images/quests/placeholder.png]],desc=[[The lost ones who live in the Fallow Sanctuary look as we look, but they are monsters... driven mad by the rigors of our journey to Azeroth.  Once our brethren, they now live in the Fallow Sanctuary to the east, catching or killing any who wander near. And they have stolen something sacred to us--draenethyst crystals. We lack the force to enter the Fallow Sanctuary and reclaim our stolen draenethyst from among their huts and campfires, but without those crystals... we too may lose our way.]],logDesc=[[Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows.]]}
DB[1391]={id=1391,zoneId=10,name=[[Nothing But The Truth]],name_loc=[[El suero de la verdad]],level=42,minLevel=37,giver=[[Deathstalker Zraedus]],giver_loc=[[Mortacechador Zraedus]],giverType=[[NPC]],giverId=5418,ender=[[Infiltrator Marksen]],ender_loc=[[Infiltrado Marksen]],enderType=[[NPC]],enderId=5416,prevId=1388,poiX=-10422,poiY=-3239,wowhead=[[https://www.wowhead.com/wotlk/quest=1391]],image=[[assets/images/quests/placeholder.png]],desc=[[We need to operate with a certain amount of discretion. After all, it's not like you're going to waltz in there and convince the fool to drink Faustin's concoction here, right? But if there's one thing those humans cannot deny it's the booze. I'll take Faustin's serum and mix it into this ale. I guarantee the poor sap will show no reluctance when it comes to chug-a-lugging a brew. Make haste to Stonard in the Swamp of Sorrows, $n. And keep our little mission nice and quiet...]],logDesc=[[Take Zraedus's Brew to Infiltrator Marksen in Stonard.]]}
DB[1392]={id=1392,zoneId=8,name=[[Noboru the Cudgel]],name_loc=[[Noboru el Garrote]],level=39,minLevel=29,giverType=[[NPC]],ender=[[Magtoor]],enderType=[[NPC]],enderId=1776,poiX=-10146,poiY=-3500,wowhead=[[https://www.wowhead.com/wotlk/quest=1392]],image=[[assets/images/quests/placeholder.png]],desc=[[Noboru has plagued the Draenei of the Harborage for months, and his cudgel is a symbol of the brutality they have suffered at the hands of the lost ones.]],logDesc=[[Bring Noboru's Cudgel to the leader of The Harborage in the Swamp of Sorrows.]]}
DB[1393]={id=1393,zoneId=8,name=[[Galen's Escape]],name_loc=[[La huida de Galen]],level=38,minLevel=30,giver=[[Galen Goodward]],giver_loc=[[Galen Bonguarda]],giverType=[[NPC]],giverId=5391,ender=[[Galen's Strongbox]],ender_loc=[[Caja fuerte de Galen]],enderType=[[GO]],enderId=32569,poiX=-10229,poiY=-3319,wowhead=[[https://www.wowhead.com/wotlk/quest=1393]],image=[[assets/images/quests/placeholder.png]],desc=[[Please help!  These creatures are going to eat me! Help me out of here, and I'll give you a great treasure!  It's in my camp in the swamp north of Stonard, but it's locked in a strongbox that can be opened through a trick that only I know. If you help me escape, then I'll teach it to you.]],logDesc=[[Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.]],rewards={{id=6828,qty=1}}}
DB[1394]={id=1394,zoneId=400,name=[[Final Passage]],name_loc=[[La recta final]],level=36,minLevel=25,giver=[[Parqual Fintallas]],giverType=[[NPC]],giverId=4488,ender=[[Dorn Plainstalker]],ender_loc=[[Dorn Acechallanos]],enderType=[[NPC]],enderId=2986,prevId=6628,poiX=-5184,poiY=-2807,wowhead=[[https://www.wowhead.com/wotlk/quest=1394]],image=[[assets/images/quests/placeholder.png]],desc=[[You have done well, $N. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles. He will sense the change within you, and see that your mind, body and spirit are strong enough that you should be rewarded for your efforts. Stay true to the balance you've shown throughout these trials, $N. Dorn will test you again in the future if you do.]],logDesc=[[Speak to Dorn Plainstalker in Thousand Needles.]],choiceRewards={{id=6804,qty=1},{id=6806,qty=1}}}
DB[1395]={id=1395,zoneId=10,name=[[Supplies for Nethergarde]],name_loc=[[Suministros para Nethergarde]],level=45,minLevel=40,giver=[[Watchmaster Sorigal]],giver_loc=[[Maestro de vigilantes Sorigal]],giverType=[[NPC]],giverId=5464,ender=[[Quartermaster Lungertz]],ender_loc=[[Intendente Lungertz]],enderType=[[NPC]],enderId=5393,poiX=-11044,poiY=-3470,wowhead=[[https://www.wowhead.com/wotlk/quest=1395]],image=[[assets/images/quests/placeholder.png]],desc=[[This crate of powerstones needs to go to Nethergarde Keep, in the Blasted Lands.  They won't hold their power for long, so we can't ship them with the next caravan. You must take them, and you must take them quickly. Bring them to Quartermaster Lungertz in Nethergarde Keep.  To reach the keep, you must travel east through Deadwind Pass, then east through the Swamp of Sorrows, then south through the Blasted Lands. Use caution, $N.  You will travel through dangerous lands, yet you must not fail.]],logDesc=[[Bring the Crate of Powerstones to Quartermaster Lungertz, before the powerstones expire.]]}
DB[1396]={id=1396,zoneId=8,name=[[Encroaching Wildlife]],name_loc=[[Contra la fauna feroz]],level=37,minLevel=30,giver=[[Watcher Biggs]],giver_loc=[[Vigía Biggs]],giverType=[[NPC]],giverId=5476,ender=[[Watcher Biggs]],ender_loc=[[Vigía Biggs]],enderType=[[NPC]],enderId=5476,rewardNextId=1421,poiX=-10147,poiY=-3175,wowhead=[[https://www.wowhead.com/wotlk/quest=1396]],image=[[assets/images/quests/placeholder.png]],desc=[[My caravan was destined for the eastern coast, but we did not reach our goal.  Lost Ones attacked us, killing guards and dashing supplies. I alone survived their assault.  I have sworn to protect what supplies remain, but wild creatures skulk near.  Please, help me defend my camp from the beasts!]],logDesc=[[Kill 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners and 10 Swamp Jaguars then return to Watcher Biggs in the Swamp of Sorrows.]]}
DB[1398]={id=1398,zoneId=8,name=[[Driftwood]],name_loc=[[Madera a la deriva]],level=42,minLevel=30,giver=[[Watcher Biggs]],giver_loc=[[Vigía Biggs]],giverType=[[NPC]],giverId=5476,ender=[[Watcher Biggs]],ender_loc=[[Vigía Biggs]],enderType=[[NPC]],enderId=5476,prevId=1421,rewardNextId=1425,poiX=-10536,poiY=-2836,wowhead=[[https://www.wowhead.com/wotlk/quest=1398]],image=[[assets/images/quests/placeholder.png]],desc=[[I owe you greatly, $N.  An honorable heart beats within you.  And now I have another task for which I humbly ask your aid. If I'm ever to reach Nethergarde, then I must fix this wagon.  And for that... I will need wood.  Strong, dry wood--not the spongy, tangled wood of the swamp's trees. $N, go east to the coast and search for driftwood that has been dried by the sun.  Bring it to me.]],logDesc=[[Bring 8 pieces of Sundried Driftwood to Watcher Biggs in the Swamp of Sorrows.]]}
DB[1418]={id=1418,zoneId=8,name=[[Neeka Bloodscar]],name_loc=[[Neeka Marca de Sangre]],level=35,minLevel=30,giver=[[Helgrum the Swift]],giver_loc=[[Helgrum el Veloz]],giverType=[[NPC]],giverId=1442,ender=[[Neeka Bloodscar]],ender_loc=[[Neeka Marca de Sangre]],enderType=[[NPC]],enderId=5394,rewardNextId=1420,poiX=-6672,poiY=-2241,wowhead=[[https://www.wowhead.com/wotlk/quest=1418]],image=[[assets/images/quests/placeholder.png]],desc=[[The Badlands is harsh and lies close to the Alliance-held land of Loch Modan, so communication between Stonard and the Badlands outpost of Kargath is often cut. Prove yourself, $N.  Travel to the Badlands and speak with Neeka Bloodscar, head scout of the Kargath outpost.  Speak with her, and then send her report back to me.]],logDesc=[[Speak with Neeka Bloodscar.]]}
DB[1419]={id=1419,zoneId=3,name=[[Coyote Thieves]],name_loc=[[Ladrones coyote]],level=40,minLevel=30,giver=[[Neeka Bloodscar]],giver_loc=[[Neeka Marca de Sangre]],giverType=[[NPC]],giverId=5394,ender=[[Neeka Bloodscar]],ender_loc=[[Neeka Marca de Sangre]],enderType=[[NPC]],enderId=5394,poiX=-6951,poiY=-2383,wowhead=[[https://www.wowhead.com/wotlk/quest=1419]],image=[[assets/images/quests/placeholder.png]],desc=[[Have you spent many days in the Badlands, $c?  Have you felt its heat? Have you faced the beasts that wander its dusty plains?  It's time you did. Crag coyotes are a tough breed.  Tough, and bold enough to creep into Kargath and steal from our food supplies.  Help rid the outpost of these thieves! Hunt crag coyotes, $N.  Hunt them and bring me their jawbones.  Bring me enough, and maybe I'll believe it when you say you know the Badlands.]],logDesc=[[Bring 30 Coyote Jawbones to Neeka Bloodscar in Kargath.]]}
DB[1420]={id=1420,zoneId=3,name=[[Report to Helgrum]],name_loc=[[Un informe para Helgrum]],level=40,minLevel=30,giver=[[Neeka Bloodscar]],giver_loc=[[Neeka Marca de Sangre]],giverType=[[NPC]],giverId=5394,ender=[[Helgrum the Swift]],ender_loc=[[Helgrum el Veloz]],enderType=[[NPC]],enderId=1442,prevId=1418,poiX=-10465,poiY=-3318,wowhead=[[https://www.wowhead.com/wotlk/quest=1420]],image=[[assets/images/quests/placeholder.png]],desc=[[I wrote a fresh report for Helgrum in Stonard.  Bring it to him. And if you consider yourself an outrunner, then don't lose your way.  Or fall to an enemy.]],logDesc=[[Bring Neeka's Report to Helgrum the Swift in Stonard.]]}
DB[1421]={id=1421,zoneId=8,name=[[The Lost Caravan]],name_loc=[[La caravana perdida]],level=35,minLevel=30,giver=[[Watcher Biggs]],giver_loc=[[Vigía Biggs]],giverType=[[NPC]],giverId=5476,ender=[[Watcher Biggs]],ender_loc=[[Vigía Biggs]],enderType=[[NPC]],enderId=5476,prevId=1396,rewardNextId=1398,poiX=-9901,poiY=-3702,wowhead=[[https://www.wowhead.com/wotlk/quest=1421]],image=[[assets/images/quests/placeholder.png]],desc=[[I was stunned during the attack by the Lost Ones, but before my sight went black I spied one of our wagons being dragged to the Fallow Sanctuary, the lost one village to the north. A caravan chest with valuable reagents was in that wagon, reagents vital to the studies of the wizards of Nethergarde Keep.  Find the chest and get those reagents, $N.  Get them and bring them to me.]],logDesc=[[Find the Caravan Chest in the Fallow Sanctuary, obtain the Wizards' Reagents and bring to Watcher Biggs.]]}
DB[1422]={id=1422,zoneId=8,name=[[Threat From the Sea]],name_loc=[[La amenaza marítima]],level=45,minLevel=35,giver=[[Tok'Kar]],giverType=[[NPC]],giverId=5592,ender=[[Katar]],enderType=[[NPC]],enderId=5593,prevId=699,rewardNextId=1426,poiX=-10850,poiY=-4144,wowhead=[[https://www.wowhead.com/wotlk/quest=1422]],image=[[assets/images/quests/placeholder.png]],desc=[[While I begin work on your weapon, why don't you talk to Katar? He mentioned needing help with patrols along the beach, and I'd rather see you keep your wits and weapons prepared instead of getting drunk with some of the other louses I share this camp with.]],logDesc=[[Speak to Katar in the Swamp of Sorrows.]]}
DB[1423]={id=1423,zoneId=8,name=[[The Lost Supplies]],name_loc=[[Los suministros perdidos]],level=40,minLevel=30,giverType=[[NPC]],ender=[[Quartermaster Lungertz]],ender_loc=[[Intendente Lungertz]],enderType=[[NPC]],enderId=5393,poiX=-11044,poiY=-3470,wowhead=[[https://www.wowhead.com/wotlk/quest=1423]],image=[[assets/images/quests/placeholder.png]],desc=[[This barrel is small yet sturdy.  Its seams are sealed with a yellow, pungent wax.  Stamped on the bottom of the barrel are the words: QUARTERMASTER LUNGERTZ NETHERGARDE KEEP]],logDesc=[[Bring the Lost Supplies to Quartermaster Lungertz.]],rewards={{id=6827,qty=1}}}
DB[1424]={id=1424,zoneId=8,name=[[Pool of Tears]],name_loc=[[Charca de Lágrimas]],level=43,minLevel=38,giver=[[Fel'zerul]],giverType=[[NPC]],giverId=1443,ender=[[Fel'zerul]],enderType=[[NPC]],enderId=1443,rewardNextId=1429,poiX=-10441,poiY=-3973,wowhead=[[https://www.wowhead.com/wotlk/quest=1424]],image=[[assets/images/quests/placeholder.png]],desc=[[The Warchief sent us to investigate strange happenings at The Temple of Atal'Hakkar. The Atal'ai trolls are a tribe of dark casters, known for practicing forbidden magic. You can imagine how astonished we were when we arrived here to discover the temple had been sunk. The green dragons now guard the site, claiming to be protectors of Azeroth. We need to discover what happened. Explore around the Pool of Tears and gather Atal'ai artifacts. From those I can begin to piece together this puzzle.]],logDesc=[[Fel'zerul in Stonard wants you to gather 5 Atal'ai Artifacts.]]}
DB[1425]={id=1425,zoneId=8,name=[[Deliver the Shipment]],name_loc=[[Envío de suministros]],level=42,minLevel=30,giver=[[Watcher Biggs]],giver_loc=[[Vigía Biggs]],giverType=[[NPC]],giverId=5476,ender=[[Quartermaster Lungertz]],ender_loc=[[Intendente Lungertz]],enderType=[[NPC]],enderId=5393,prevId=1398,poiX=-11044,poiY=-3470,wowhead=[[https://www.wowhead.com/wotlk/quest=1425]],image=[[assets/images/quests/placeholder.png]],desc=[[While I fix this wagon, $N, I have one last task for you. I have packed the most vital supplies saved from the ogre attacks.  Take them to Nethergarde Keep.  The keep is nestled in the northern hills of the Blasted Lands, keeping watch over the Dark Portal. To reach Nethergard, follow the road east.  When it branches head south into the Blasted Lands, then turn left at the next fork.  Follow the road, $N, and be wary.]],logDesc=[[Bring the Shipment to Nethergarde to Quartermaster Lungertz in Nethergarde Keep.]]}
DB[1426]={id=1426,zoneId=8,name=[[Threat From the Sea]],name_loc=[[La amenaza marítima]],level=43,minLevel=35,giver=[[Katar]],giverType=[[NPC]],giverId=5593,ender=[[Katar]],enderType=[[NPC]],enderId=5593,prevId=1422,rewardNextId=1427,poiX=-10882,poiY=-4244,wowhead=[[https://www.wowhead.com/wotlk/quest=1426]],image=[[assets/images/quests/placeholder.png]],desc=[[I have no love for the sea, nor any creature I've seen come from its depths. It is a powerful but blind mistress; callous and brutal. It would bring me great pleasure to slay the fish men by the hundreds if it were within my power. But I garner some pleasure from watching their deaths at the hands of any who do the Horde's will. Which brings us to you, $c. How many can you slay? Would you test yourself against their most powerful kind?]],logDesc=[[Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows.]]}
DB[1427]={id=1427,zoneId=8,name=[[Threat From the Sea]],name_loc=[[La amenaza marítima]],level=43,minLevel=35,giver=[[Katar]],giverType=[[NPC]],giverId=5593,ender=[[Tok'Kar]],enderType=[[NPC]],enderId=5592,prevId=1426,poiX=-10859,poiY=-4088,wowhead=[[https://www.wowhead.com/wotlk/quest=1427]],image=[[assets/images/quests/placeholder.png]],desc=[[Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you. You would do well to test its strength against the fish men when you are ready... but only to please me further.]],logDesc=[[Speak with Tok'Kar in the Swamp of Sorrows.]],choiceRewards={{id=9680,qty=1},{id=9678,qty=1},{id=9679,qty=1}}}
DB[1428]={id=1428,zoneId=8,name=[[Continued Threat]],name_loc=[[La amenaza continua]],level=45,minLevel=35,giver=[[Katar]],giverType=[[NPC]],giverId=5593,ender=[[Katar]],enderType=[[NPC]],enderId=5593,prevId=1427,poiX=-10419,poiY=-4418,wowhead=[[https://www.wowhead.com/wotlk/quest=1428]],image=[[assets/images/quests/placeholder.png]],desc=[[It pleases me to see your hatred for the fish men grows with mine. Find more of their kind along the beach, and when you've had your fill of combat, return to me. We shall speak then of a reward for your diligence.]],logDesc=[[Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows.]]}
DB[1429]={id=1429,zoneId=8,name=[[The Atal'ai Exile]],name_loc=[[El exiliado Atal'ai]],level=44,minLevel=38,giver=[[Fel'zerul]],giverType=[[NPC]],giverId=1443,ender=[[Atal'ai Exile]],ender_loc=[[Exiliado Atal'ai]],enderType=[[NPC]],enderId=5598,prevId=1424,rewardNextId=1444,poiX=-464,poiY=-2874,wowhead=[[https://www.wowhead.com/wotlk/quest=1429]],image=[[assets/images/quests/placeholder.png]],desc=[[While you were braving the dangers of the Pool of Tears, one of my scouts returned with a scroll written in blood on dried flesh. It seems to be a judicial sentence against a priest of the Atal'ai tribe. This priest was sentenced to a fate worse than death amongst the Atal'ai. He was exiled to live far north in the Hinterlands, with the Witherbark trolls. I will bundle these artifacts. You are to seek out the exile and discover their true use. Return to me once your journey is complete.]],logDesc=[[Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands.]]}
DB[1430]={id=1430,zoneId=8,name=[[Fresh Meat]],name_loc=[[Carne fresca]],level=44,minLevel=35,giver=[[Dar]],giverType=[[NPC]],giverId=5591,ender=[[Dar]],enderType=[[NPC]],enderId=5591,poiX=-10496,poiY=-3248,wowhead=[[https://www.wowhead.com/wotlk/quest=1430]],image=[[assets/images/quests/placeholder.png]],desc=[[There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers. If you plan on heading to the coast, then I could easily make it worth your while to bring me back some of their legs to have transported back to Orgrimmar. The coast is to the east from here, and you should have no problem finding the creatures scurrying along the beaches and under the sea.]],logDesc=[[Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows.]],rewards={{id=9681,qty=10},{id=9682,qty=1}}}
DB[1431]={id=1431,zoneId=1637,name=[[Alliance Relations]],name_loc=[[Las relaciones de la Alianza]],level=30,minLevel=30,giver=[[Craven Drok]],giverType=[[NPC]],giverId=5639,ender=[[Keldran]],enderType=[[NPC]],enderId=5640,rewardNextId=1432,poiX=1782,poiY=-3997,wowhead=[[https://www.wowhead.com/wotlk/quest=1431]],image=[[assets/images/quests/placeholder.png]],desc=[[Be still, $c, and allow me to share with you something important to our people, but far from obvious. We are a proud race, and the war with the humans tried even Thrall's great patience. You see, our Warchief is wise and prudent, and he continues to put his people first. Ultimately, he is a diplomat, and in his time with the humans he learned much of their ways. If the tale I've started piques your interest, then find Keldran near the western exit of the city. His hovel is there.]],logDesc=[[Speak to Keldran in Orgrimmar.]]}
DB[1432]={id=1432,zoneId=1637,name=[[Alliance Relations]],name_loc=[[Las relaciones de la Alianza]],level=30,minLevel=30,giver=[[Keldran]],giverType=[[NPC]],giverId=5640,ender=[[Takata Steelblade]],ender_loc=[[Takata Hoja de Acero]],enderType=[[NPC]],enderId=5641,prevId=1431,poiX=-1178,poiY=1870,wowhead=[[https://www.wowhead.com/wotlk/quest=1432]],image=[[assets/images/quests/placeholder.png]],desc=[[As the Alliance progresses deeper and deeper into Kalimdor, incorrect conclusions may be drawn about the Horde making pacts with the Burning Legion. The Warchief cannot allow that to happen. And with his blessing, I am taking control of overseeing them removed. I have agents in the area of Desolace at the Ghost Walker Post north of the great Kodo Graveyard. Head south of the Charred Vale in the Stonetalon Mountains and you shall come across it. When you arrive, seek out Takata Steelblade.]],logDesc=[[Speak to Takata Steelblade in Desolace.]]}
DB[1433]={id=1433,zoneId=1637,name=[[Alliance Relations]],name_loc=[[Las relaciones de la Alianza]],level=33,minLevel=30,giver=[[Takata Steelblade]],giver_loc=[[Takata Hoja de Acero]],giverType=[[NPC]],giverId=5641,ender=[[Maurin Bonesplitter]],ender_loc=[[Maurin Partehuesos]],enderType=[[NPC]],enderId=4498,prevId=1432,rewardNextId=1435,poiX=-1150,poiY=1884,wowhead=[[https://www.wowhead.com/wotlk/quest=1433]],image=[[assets/images/quests/placeholder.png]],desc=[[The Burning Blade have many agendas, but know that they are evil to their core, their spirits corrupted, and their destruction is the only way to thwart their objectives. Keldran sent Maurin with me because of his knowledge of the Blade and their warlock ways. He has control of our plots against the Blade while I deal with the other demonic threats here in Desolace. Speak to him, and he will guide you in his designs.]],logDesc=[[Speak to Maurin Bonesplitter in Desolace.]]}
DB[1434]={id=1434,zoneId=1637,name=[[Befouled by Satyr]],name_loc=[[La contaminación del sátiro]],level=33,minLevel=25,giver=[[Takata Steelblade]],giver_loc=[[Takata Hoja de Acero]],giverType=[[NPC]],giverId=5641,ender=[[Takata Steelblade]],ender_loc=[[Takata Hoja de Acero]],enderType=[[NPC]],enderId=5641,poiX=-39,poiY=612,wowhead=[[https://www.wowhead.com/wotlk/quest=1434]],image=[[assets/images/quests/placeholder.png]],desc=[[A demon infestation does not occur without other influences--something else allows evil to gain a foothold. It may start with a weakened spirit, a needless desire for power; perhaps it's a thirst for revenge, or the appeal for final justice. When we are beset by pain, evil takes advantage of us--evil such as the satyr. Ties have been made between them and the Burning Blade, and Thrall would have them slain. Seek them out to the northeast of here, and return to me when you've driven them back.]],logDesc=[[Slay 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers, and 7 Hatefury Hellcallers, and return to Takata Steelblade in Desolace.]]}
DB[1435]={id=1435,zoneId=1637,name=[[The Burning of Spirits]],name_loc=[[Los espíritus ardientes]],level=33,minLevel=25,giver=[[Maurin Bonesplitter]],giver_loc=[[Maurin Partehuesos]],giverType=[[NPC]],giverId=4498,ender=[[Maurin Bonesplitter]],ender_loc=[[Maurin Partehuesos]],enderType=[[NPC]],enderId=4498,prevId=1433,poiX=-1150,poiY=1884,wowhead=[[https://www.wowhead.com/wotlk/quest=1435]],image=[[assets/images/quests/placeholder.png]],desc=[[Death is most desirable for those despicable creatures that turn their back on their liege for such selfish reasons. But death is not enough when dealing with those that have given themselves over to the darkness. Take this gem. When one of the Burning Blade's near death, activate its magic. The spell shall pull the corrupted spirit out of its victim, leaving an infused gem behind. Bring me these infused gems so I may dispose of them properly. Go now, and may you elude death.]],logDesc=[[Return the Burning Gem and 15 Infused Burning Gems to Maurin Bonesplitter in Desolace.]]}
DB[1436]={id=1436,zoneId=1637,name=[[Alliance Relations]],name_loc=[[Las relaciones de la Alianza]],level=33,minLevel=30,giver=[[Takata Steelblade]],giver_loc=[[Takata Hoja de Acero]],giverType=[[NPC]],giverId=5641,ender=[[Keldran]],enderType=[[NPC]],enderId=5640,prevId=1435,poiX=1782,poiY=-3997,wowhead=[[https://www.wowhead.com/wotlk/quest=1436]],image=[[assets/images/quests/placeholder.png]],desc=[[The fight goes well, $N. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings. Return to Keldran and let him know what we have done. I am sure he will reward you for your efforts here. His cause is important to him, and he will take pride in knowing that the Warchief respects his concerns.]],logDesc=[[Speak to Keldran in Orgrimmar.]],choiceRewards={{id=6744,qty=1},{id=6745,qty=1}}}
DB[1437]={id=1437,zoneId=405,name=[[Vahlarriel's Search]],name_loc=[[Buscando para Vahlarriel]],level=33,minLevel=30,giver=[[Vahlarriel Demonslayer]],giver_loc=[[Vahlarriel Destripademonios]],giverType=[[NPC]],giverId=5642,ender=[[Malem Chest]],ender_loc=[[Cofre de Malem]],enderType=[[GO]],enderId=50961,rewardNextId=1465,poiX=-83,poiY=1692,wowhead=[[https://www.wowhead.com/wotlk/quest=1437]],image=[[assets/images/quests/placeholder.png]],desc=[[I am Vahlarriel, $N. I've come here to discover the whereabouts of two missing nobles of a Darnassian merchant family--House Malem. The father of the house fears the worst, and I am to do everything I can to find his missing children. I have yet to start my search for Tyranis or Dalinda, but I am hopeful I shall not be here long. Last word tells of them passing through the Stonetalon Mountains a few weeks ago. If you find their wagon, please, come find me immediately.]],logDesc=[[Find and search Tyranis and Dalinda Malem's wagon in Desolace.]]}
DB[1438]={id=1438,zoneId=405,name=[[Vahlarriel's Search]],name_loc=[[Buscando para Vahlarriel]],level=33,minLevel=30,giver=[[Vahlarriel Demonslayer]],giver_loc=[[Vahlarriel Destripademonios]],giverType=[[NPC]],giverId=5642,ender=[[Dalinda Malem]],enderType=[[NPC]],enderId=5644,prevId=1465,rewardNextId=1439,poiX=-331,poiY=1767,wowhead=[[https://www.wowhead.com/wotlk/quest=1438]],image=[[assets/images/quests/placeholder.png]],desc=[[Find both Dalinda and Tyranis if you can and come back to me with your findings. Start your search at this fortress. I will contact my superiors in Darnassus immediately and let them know the situation. $N, there is something else I wish to impress upon you. My superiors have shown some concern over Tyranis' and his motives for coming here. It is more important to them that Dalinda is found and brought back safely. Tyranis is to be... gauged before he is taken home.]],logDesc=[[Find Dalinda Malem in Desolace.]]}
DB[1439]={id=1439,zoneId=405,name=[[Search for Tyranis]],name_loc=[[Buscando a Tyranis]],level=33,minLevel=30,giver=[[Dalinda Malem]],giverType=[[NPC]],giverId=5644,ender=[[Dalinda Malem]],enderType=[[NPC]],enderId=5644,prevId=1438,poiX=-420,poiY=1850,wowhead=[[https://www.wowhead.com/wotlk/quest=1439]],image=[[assets/images/quests/placeholder.png]],desc=[[We were brought here after the orcs slaughtered all our guards and servants. Oh, the terrible things they did to them! I thought surely they would kill us right there and then, but it became obvious they had other plans. Tyranis attempted to speak to them. I think he wanted to impress them with his knowledge of the arcane... I'm not sure why. Please, I can't leave here until I know what's happened to my brother. Find him, then come back for me when his fate is known.]],logDesc=[[Find Tyranis Malem in Desolace.]]}
DB[1440]={id=1440,zoneId=405,name=[[Return to Vahlarriel]],name_loc=[[Regresa junto a Vahlarriel]],level=33,minLevel=30,giver=[[Dalinda Malem]],giverType=[[NPC]],giverId=5644,ender=[[Vahlarriel Demonslayer]],ender_loc=[[Vahlarriel Destripademonios]],enderType=[[NPC]],enderId=5642,prevId=1439,poiX=98,poiY=1246,wowhead=[[https://www.wowhead.com/wotlk/quest=1440]],image=[[assets/images/quests/placeholder.png]],desc=[[So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family. If you're ready, then there is nothing else for me here--we can leave when you feel the time is right.]],logDesc=[[Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.]],choiceRewards={{id=9687,qty=1},{id=9698,qty=1},{id=9699,qty=1},{id=11884,qty=1}}}
DB[1442]={id=1442,name=[[Seeking the Kor Gem]],name_loc=[[La búsqueda de la gema Kor]],level=22,minLevel=20,giver=[[Thundris Windweaver]],giver_loc=[[Thundris Tejevientos]],giverType=[[NPC]],giverId=3649,ender=[[Thundris Windweaver]],ender_loc=[[Thundris Tejevientos]],enderType=[[NPC]],enderId=3649,prevId=1653,poiX=4254,poiY=666,wowhead=[[https://www.wowhead.com/wotlk/quest=1442]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, $N. What can I do for one who follows a holy path? Ah, yes, Stilwell, the blacksmith... from long ago. I remember him well, though, I have not heard his name in some time. He never struck me as an impudent man, so I can only assume his desire for a Kor gem is noble. If you truly wish for one of the gems, then you must head to the northwest of Ashenvale. You will find Blackfathom Deeps there within some ancient ruins. The naga who still use the gems are down below. Do not go alone, $c.]],logDesc=[[Bring a Kor Gem to Thundris Windweaver in Darkshore.]],rewards={{id=7083,qty=1}}}
DB[1444]={id=1444,zoneId=47,name=[[Return to Fel'Zerul]],name_loc=[[Regresa junto a Fel'Zerul]],level=44,minLevel=38,giver=[[Atal'ai Exile]],giver_loc=[[Exiliado Atal'ai]],giverType=[[NPC]],giverId=5598,ender=[[Fel'zerul]],enderType=[[NPC]],enderId=1443,prevId=1429,rewardNextId=1445,poiX=-10459,poiY=-3322,wowhead=[[https://www.wowhead.com/wotlk/quest=1444]],image=[[assets/images/quests/placeholder.png]],desc=[[Jammal'an the Prophet sentenced me to exile from The Temple of Atal'Hakkar. I once felt the high priest was a worthy leader. His unyielding faith in his prophecy will bring about the destruction of the Atal'ai. If it hasn't already. When I expressed my concerns, I was labeled an infidel and ousted from the temple. Those artifacts you brought to me are harmless. But if Jammal'an has found the proper fetish enchantment for the summoning ritual, the world lies in great peril....]],logDesc=[[Return to Fel'Zerul in Stonard.]]}
DB[1445]={id=1445,zoneId=1417,name=[[The Temple of Atal'Hakkar]],name_loc=[[El Templo de Atal'Hakkar]],level=50,minLevel=38,giver=[[Fel'zerul]],giverType=[[NPC]],giverId=1443,ender=[[Fel'zerul]],enderType=[[NPC]],enderId=1443,prevId=1444,poiX=-10271,poiY=-4090,wowhead=[[https://www.wowhead.com/wotlk/quest=1445]],image=[[assets/images/quests/placeholder.png]],desc=[[So he spoke of Jammal'an's prophecy? The Atal'ai spiritual leader believes once Hakkar returns to Azeroth from the Nether, the god will grant the Atal'ai tribe immortality. Foolish trickery to bring about a premature doomsday if you ask me. But you say the exile spoke of enchanted fetishes? This concerns me greatly. If these are in fact the key to the Atal'ai ritual which caused this mess, we must understand their intrinsic powers. Venture into the Temple, and seize the fetishes!]],logDesc=[[Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard.]],rewards={{id=1490,qty=1}}}
DB[1446]={id=1446,zoneId=1417,name=[[Jammal'an the Prophet]],name_loc=[[Jammal'an el Profeta]],level=53,minLevel=38,giver=[[Atal'ai Exile]],giver_loc=[[Exiliado Atal'ai]],giverType=[[NPC]],giverId=5598,ender=[[Atal'ai Exile]],ender_loc=[[Exiliado Atal'ai]],enderType=[[NPC]],enderId=5598,poiX=-464,poiY=-2874,wowhead=[[https://www.wowhead.com/wotlk/quest=1446]],image=[[assets/images/quests/placeholder.png]],desc=[[My Witherbark companions don't take kindly to strangers around their home. Me? I don't have a home anymore. I was exiled from my people, the great Atal'ai tribe of the Swamp of Sorrows. Our spiritual leader, Jammal'an, had what he called a prophecy. He believes the summoning of the god, Hakkar will bring the Atal'ai immortality. But I urged caution. What if the prophecy was nothing more than manipulation? I want revenge for my exile. Bring me Jammal'an's head. Maybe then my people will be free.]],logDesc=[[The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.]],choiceRewards={{id=11123,qty=1},{id=11124,qty=1}}}
DB[1447]={id=1447,zoneId=1519,name=[[The Missing Diplomat]],name_loc=[[El diplomático desaparecido]],level=31,minLevel=28,giver=[[Dashel Stonefist]],giver_loc=[[Dashel Puñopiedra]],giverType=[[NPC]],giverId=4961,ender=[[Dashel Stonefist]],ender_loc=[[Dashel Puñopiedra]],enderType=[[NPC]],enderId=4961,prevId=1246,rewardNextId=1247,poiX=-8681,poiY=433,wowhead=[[https://www.wowhead.com/wotlk/quest=1447]],image=[[assets/images/quests/placeholder.png]],desc=[[Yeah, you're obviously not the smartest $c to come into Stormwind, but you're about to be one of the dumbest to never leave. Have you met me friends?]],logDesc=[[Defeat Dashel Stonefist in Stormwind.]]}
DB[1448]={id=1448,zoneId=1519,name=[[In Search of The Temple]],name_loc=[[En búsqueda del templo]],level=43,minLevel=38,giver=[[Brohann Caskbelly]],giver_loc=[[Brohann Barriliga]],giverType=[[NPC]],giverId=5384,ender=[[Brohann Caskbelly]],ender_loc=[[Brohann Barriliga]],enderType=[[NPC]],enderId=5384,rewardNextId=1449,poiX=-10429,poiY=-3853,wowhead=[[https://www.wowhead.com/wotlk/quest=1448]],image=[[assets/images/quests/placeholder.png]],desc=[[There was a time when I was young and full of vigor like you, $c. But now I'm old and unable to explore the world like I once did. Ah, the things I saw! But there was one mystery that eluded me. For my final quest, the Explorers' League sent me in search of The Temple of Atal'Hakkar. It was rumored to be located in the Swamp of Sorrows. Because of my frail state, I traveled the skies by gryphon in search of it but never found it. Help an old dwarf out? Perhaps you will have better luck on foot.]],logDesc=[[Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar.]]}
DB[1449]={id=1449,zoneId=1519,name=[[To The Hinterlands]],name_loc=[[A las Tierras del Interior]],level=43,minLevel=38,giver=[[Brohann Caskbelly]],giver_loc=[[Brohann Barriliga]],giverType=[[NPC]],giverId=5384,ender=[[Falstad Wildhammer]],ender_loc=[[Falstad Martillo Salvaje]],enderType=[[NPC]],enderId=5635,prevId=1448,rewardNextId=1450,poiX=267,poiY=-2030,wowhead=[[https://www.wowhead.com/wotlk/quest=1449]],image=[[assets/images/quests/placeholder.png]],desc=[[As I mentioned earlier, I attempted to scout the temple on my own from the air. Well, I wasn't exactly alone. I traveled to the renowned gryphon aviary at Aerie Peak in The Hinterlands. There I enlisted the aid of one of their finest pilots. The pilot fell off his mount, down into the swamp... In my old age the poor fellow's name eludes me. The master of the aviary would remember, no doubt. Journey there and seek out Falstad Wildhammer. We need to find out what happened to that pilot.]],logDesc=[[Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands.]]}
DB[1450]={id=1450,zoneId=47,name=[[Gryphon Master Talonaxe]],name_loc=[[Maestro de grifos Garracha]],level=43,minLevel=38,giver=[[Falstad Wildhammer]],giver_loc=[[Falstad Martillo Salvaje]],giverType=[[NPC]],giverId=5635,ender=[[Gryphon Master Talonaxe]],ender_loc=[[Maestro de grifos Garracha]],enderType=[[NPC]],enderId=5636,prevId=1449,rewardNextId=1451,poiX=325,poiY=-1951,wowhead=[[https://www.wowhead.com/wotlk/quest=1450]],image=[[assets/images/quests/placeholder.png]],desc=[[So you're a glorified errand $g boy:girl; for some old Explorers' League geezer, eh? Well you listen to me, $c. I don't know who your old buddy was flying around with down in Azeroth. Do I look like Gryphon Master Talonaxe to you? Do I? If you're so interested in the flight assignments why don't you ask the gryphon master? If I catch you idling around here for much longer, I'm going to put you to some real work. Now get a move on.]],logDesc=[[Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary.]]}
DB[1451]={id=1451,zoneId=47,name=[[Rhapsody Shindigger]],name_loc=[[Rapsodio Machacacanillas]],level=43,minLevel=38,giver=[[Gryphon Master Talonaxe]],giver_loc=[[Maestro de grifos Garracha]],giverType=[[NPC]],giverId=5636,ender=[[Rhapsody Shindigger]],ender_loc=[[Rapsodio Machacacanillas]],enderType=[[NPC]],enderId=5634,prevId=1450,rewardNextId=1452,poiX=220,poiY=-2612,wowhead=[[https://www.wowhead.com/wotlk/quest=1451]],image=[[assets/images/quests/placeholder.png]],desc=[[Rhapsody took quite a liking to the booze. Now don't get me wrong -- all of us dwarves up here at the aviary love a good ale when the time is right. But ol' Shindigger took to the liquor like a gryphon takes to the skies. And a damned shame it was, too. No one could fly like Rhapsody. First sign of trouble was when he came stumbling back from that mission with your buddy, Brohann. All went down hill quickly after that. Had to let him go. Last I heard, he's set up a brew camp to the east of here...]],logDesc=[[Seek out Rhapsody Shindigger in The Hinterlands.]]}
DB[1452]={id=1452,zoneId=47,name=[[Rhapsody's Kalimdor Kocktail]],name_loc=[[El cubata de Kalimdor de Rapsodio]],level=43,minLevel=38,giver=[[Rhapsody Shindigger]],giver_loc=[[Rapsodio Machacacanillas]],giverType=[[NPC]],giverId=5634,ender=[[Rhapsody Shindigger]],ender_loc=[[Rapsodio Machacacanillas]],enderType=[[NPC]],enderId=5634,prevId=1451,poiX=-7685,poiY=-3456,wowhead=[[https://www.wowhead.com/wotlk/quest=1452]],image=[[assets/images/quests/placeholder.png]],desc=[[Hiccup! So that crazy fool Brohann sent ya? My we had quite an adventure...Hiccup! If ya want me to tell ya what happened down in the swamp, I'm gonna need me something stiff to drink. It wasn't a pretty scene, ya see. Hiccup! Tell ya what... bring me what I need to whip up a Kalimdor Kocktail and I'll tell ya all about it. Gonna need some Roc gizzards from Tanaris... and let's see... some Groddoc and Ironfur livers from Feralas... A nice stiff Kalimdor Kocktail... that'll get me talking!]],logDesc=[[Rhapsody Shindigger in The Hinterlands wants you to bring him 3 Roc Gizzards, 3 Groddoc Livers and 3 Ironfur Livers.]]}
DB[1453]={id=1453,zoneId=1537,name=[[Reclaimers' Business in Desolace]],name_loc=[[Los negocios de los Recuperadores en Desolace]],level=33,minLevel=30,giver=[[Roetten Stonehammer]],giver_loc=[[Roetten Rocamartillo]],giverType=[[NPC]],giverId=5637,ender=[[Kreldig Ungor]],ender_loc=[[Kreldig Ungor]],enderType=[[NPC]],enderId=5638,poiX=163,poiY=1257,wowhead=[[https://www.wowhead.com/wotlk/quest=1453]],image=[[assets/images/quests/placeholder.png]],desc=[[There's work to be done in Desolace, $N. It's an atrocious place, befouled by centaur and other nasties. But if you're looking for a good week's honest work, then head there, meet with Kreldig Ungor, and tell him I sentcha. You can find him holed up at Nijel's Point--it's a little cozy camp hidden in the mountains of northern Desolace. Just head east if you enter from the Stonetalon Mountains. It's easy to miss, so be on the lookout.]],logDesc=[[Speak to Kreldig Ungor at Nijel's Point in Desolace.]]}
DB[1454]={id=1454,zoneId=405,name=[[The Karnitol Shipwreck]],name_loc=[[El naufragio de Karnitol]],level=39,minLevel=30,giver=[[Kreldig Ungor]],giver_loc=[[Kreldig Ungor]],giverType=[[NPC]],giverId=5638,ender=[[Karnitol's Chest]],ender_loc=[[Cofre de Karnitol]],enderType=[[GO]],enderId=35251,prevId=1453,rewardNextId=1455,poiX=-461,poiY=2610,wowhead=[[https://www.wowhead.com/wotlk/quest=1454]],image=[[assets/images/quests/placeholder.png]],desc=[[My first order of business is for the mage Karnitol--a noble of some sort in Stormwind. Seems his ship was attacked by sea giants while off the coast in the northwest of Desolace. He and his servants tried to bring one of his more valuable chests ashore, but when the sea giants attacked in droves, he chose to abandon it and teleport himself and his servants to safety. He wants us to find the chest and its contents, and return it to him in Stormwind.]],logDesc=[[Find Karnitol's Chest in Desolace.]]}
DB[1455]={id=1455,zoneId=405,name=[[The Karnitol Shipwreck]],name_loc=[[El naufragio de Karnitol]],level=39,minLevel=30,giver=[[Karnitol's Chest]],giver_loc=[[Cofre de Karnitol]],giverType=[[GO]],giverId=35251,ender=[[Kreldig Ungor]],ender_loc=[[Kreldig Ungor]],enderType=[[NPC]],enderId=5638,prevId=1454,rewardNextId=1456,poiX=163,poiY=1257,wowhead=[[https://www.wowhead.com/wotlk/quest=1455]],image=[[assets/images/quests/placeholder.png]],desc=[[You take a few moments to figure out what pried the chest open, and you notice along the sides and top of the chest, long, deep scratches that reveal that something other than a man or giant took interest in it. The marks don't appear as if they were caused by dagger or sword. After going through the chest you find it to be completely empty. Not having another course of action, you close the chest and prepare to leave. Kreldig will be disappointed.]],logDesc=[[Return to Kreldig Ungor at Nijel's Point in Desolace.]]}
DB[1456]={id=1456,zoneId=405,name=[[The Karnitol Shipwreck]],name_loc=[[El naufragio de Karnitol]],level=39,minLevel=30,giver=[[Kreldig Ungor]],giver_loc=[[Kreldig Ungor]],giverType=[[NPC]],giverId=5638,ender=[[Kreldig Ungor]],ender_loc=[[Kreldig Ungor]],enderType=[[NPC]],enderId=5638,prevId=1455,rewardNextId=1457,poiX=156,poiY=2845,wowhead=[[https://www.wowhead.com/wotlk/quest=1456]],image=[[assets/images/quests/placeholder.png]],desc=[[Intriguing. Well, we might not be without hope quite yet. Along that same coast, but to the north near Ranazjar Isle, there're night elf ruins at the bottom of the ocean. A tribe of naga, the Slitherblade, make that their home. I think that'd be our best bet. If a scouting party went that far south, then they must've been pretty powerful. If you're gonna find Karnitol's belongings, I'd start with the more powerful naga: the tidehunters or sea witches.]],logDesc=[[Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace.]]}
DB[1457]={id=1457,zoneId=405,name=[[The Karnitol Shipwreck]],name_loc=[[El naufragio de Karnitol]],level=39,minLevel=30,giver=[[Kreldig Ungor]],giver_loc=[[Kreldig Ungor]],giverType=[[NPC]],giverId=5638,ender=[[Roetten Stonehammer]],ender_loc=[[Roetten Rocamartillo]],enderType=[[NPC]],enderId=5637,prevId=1456,poiX=-4681,poiY=-1267,wowhead=[[https://www.wowhead.com/wotlk/quest=1457]],image=[[assets/images/quests/placeholder.png]],desc=[[Take Karnitol's things back to Roetten in Ironforge and he'll pay you for a job well done. Haha, if you're not careful, he's gonna be so pleased with ya that he'll ask you to join us full time. Again, great job, $N. Be careful on your way back, and don't take too much time--Karnitol's not the most of patient of men, but he's very generous nonetheless.]],logDesc=[[Bring Karnitol's Satchel to Roetten Stonehammer in Ironforge.]],choiceRewards={{id=6791,qty=1},{id=6792,qty=1}}}
DB[1458]={id=1458,zoneId=405,name=[[Reagents for Reclaimers Inc.]],name_loc=[[Componentes para Recuperadores S.A.]],level=33,minLevel=30,giver=[[Kreldig Ungor]],giver_loc=[[Kreldig Ungor]],giverType=[[NPC]],giverId=5638,ender=[[Kreldig Ungor]],ender_loc=[[Kreldig Ungor]],enderType=[[NPC]],enderId=5638,prevId=1453,rewardNextId=1459,poiX=-39,poiY=612,wowhead=[[https://www.wowhead.com/wotlk/quest=1458]],image=[[assets/images/quests/placeholder.png]],desc=[[One of my tasks out here involves picking up some reagents for Leftwitch, a gnome mage in Kharanos . Roetten seems to think it's easy coin in the bank since we're out here already. He doesn't really care that we're short-handed as is. The first few items on his list should be easy enough to get, and it'd be a good chunk of coin for anyone helping me out. I need some horns and claws from the Hatefury satyr to the east of here. Bring 'em back to me and we'll get started on the rest of the list.]],logDesc=[[Bring 10 Hatefury Claws, and 10 Hatefury Horns to Kreldig Ungor in Desolace.]]}
DB[1459]={id=1459,zoneId=405,name=[[Reagents for Reclaimers Inc.]],name_loc=[[Componentes para Recuperadores S.A.]],level=35,minLevel=30,giver=[[Kreldig Ungor]],giver_loc=[[Kreldig Ungor]],giverType=[[NPC]],giverId=5638,ender=[[Kreldig Ungor]],ender_loc=[[Kreldig Ungor]],enderType=[[NPC]],enderId=5638,prevId=1458,rewardNextId=1466,poiX=-650,poiY=617,wowhead=[[https://www.wowhead.com/wotlk/quest=1459]],image=[[assets/images/quests/placeholder.png]],desc=[[Next on Leftwitch's list is... let's see... hmm. Oh, here it is. Simple enough, but pretty explicit in his directions. He needs venom from the scorpashi, and hide from some kodo. The fine print says both are from specific creatures: the venom's got to come from any of the scorpashi, and the hide's got to come from an aged kodo, not the dying or ancient ones. Mages, I tell ya, some of the stuff they want... it's just weird.]],logDesc=[[Bring 7 vials of Scorpashi Venom and 3 Aged Kodo Hides to Kreldig Ungor in Desolace.]]}
DB[1462]={id=1462,name=[[Earth Sapta]],name_loc=[[Sapta de tierra]],level=4,minLevel=4,giver=[[Seer Ravenfeather]],giver_loc=[[Vidente Pluma de Cuervo]],giverType=[[NPC]],giverId=5888,ender=[[Seer Ravenfeather]],ender_loc=[[Vidente Pluma de Cuervo]],enderType=[[NPC]],enderId=5888,prevId=-1520,poiX=-2882,poiY=-250,wowhead=[[https://www.wowhead.com/wotlk/quest=1462]],image=[[assets/images/quests/placeholder.png]],logDesc=[[Speak to Seer Ravenfeather for another Earth Sapta.]],rewards={{id=6635,qty=1}}}
DB[1463]={id=1463,name=[[Earth Sapta]],name_loc=[[Sapta de tierra]],level=4,minLevel=4,giver=[[Canaga Earthcaller]],giver_loc=[[Canaga Clamatierra]],giverType=[[NPC]],giverId=5887,ender=[[Canaga Earthcaller]],ender_loc=[[Canaga Clamatierra]],enderType=[[NPC]],enderId=5887,prevId=-1517,poiX=-630,poiY=-4205,wowhead=[[https://www.wowhead.com/wotlk/quest=1463]],image=[[assets/images/quests/placeholder.png]],logDesc=[[Speak to Canaga Earthcaller for another Earth Sapta.]],rewards={{id=6635,qty=1}}}
DB[1464]={id=1464,name=[[Fire Sapta]],name_loc=[[La sapta de fuego]],level=-1,minLevel=10,giver=[[Telf Joolam]],giverType=[[NPC]],giverId=5900,ender=[[Telf Joolam]],enderType=[[NPC]],enderId=5900,prevId=-1526,poiX=-270,poiY=-4001,wowhead=[[https://www.wowhead.com/wotlk/quest=1464]],image=[[assets/images/quests/placeholder.png]],logDesc=[[Speak to Telf Joolam for another Fire Sapta.]],rewards={{id=6636,qty=1}}}
DB[1465]={id=1465,zoneId=405,name=[[Vahlarriel's Search]],name_loc=[[Buscando para Vahlarriel]],level=33,minLevel=30,giver=[[Malem Chest]],giver_loc=[[Cofre de Malem]],giverType=[[GO]],giverId=50961,ender=[[Vahlarriel Demonslayer]],ender_loc=[[Vahlarriel Destripademonios]],enderType=[[NPC]],enderId=5642,prevId=1437,rewardNextId=1438,poiX=98,poiY=1246,wowhead=[[https://www.wowhead.com/wotlk/quest=1465]],image=[[assets/images/quests/placeholder.png]],desc=[[As you continue your search of the wagon you find not only a pendant, but also footprints leading off towards the south. In the distance you can see smoke rising from a large fort. The smoke is from a kept fire, not the burning of buildings, and your instincts tell you that the Malems, if still alive, were taken that direction. You think Vahlarriel at Nijel's Point should not only see the pendant you've found, but also know about the signs of life to the south.]],logDesc=[[Return the Malem Pendant to Vahlarriel Demonslayer at Nijel's Point in Desolace.]]}
DB[1466]={id=1466,zoneId=405,name=[[Reagents for Reclaimers Inc.]],name_loc=[[Componentes para Recuperadores S.A.]],level=40,minLevel=30,giver=[[Kreldig Ungor]],giver_loc=[[Kreldig Ungor]],giverType=[[NPC]],giverId=5638,ender=[[Kreldig Ungor]],ender_loc=[[Kreldig Ungor]],enderType=[[NPC]],enderId=5638,prevId=1459,rewardNextId=1467,poiX=-1815,poiY=1621,wowhead=[[https://www.wowhead.com/wotlk/quest=1466]],image=[[assets/images/quests/placeholder.png]],desc=[[This is the last of the items, and I won't lie, it ain't pretty. I'm also expecting this to take you a little bit longer than the other items. So, enough with the warning, let's get this started. Leftwitch says he needs: ten brains from either mana eaters, mage hunters, or ley hunters. Ten nether wings from a nether maiden, sister or sorceress. And... ten vials of doomwarder blood from a doomwarder captain, or lord. Simple enough, huh? Sheesh... if you wanna pass on this one, I'd understand.]],logDesc=[[Bring 10 Felhound Brains, 10 Nether Wings, and 10 vials of Doomwarder Blood to Kreldig Ungor in Desolace.]]}
DB[1467]={id=1467,zoneId=405,name=[[Reagents for Reclaimers Inc.]],name_loc=[[Componentes para Recuperadores S.A.]],level=40,minLevel=30,giver=[[Kreldig Ungor]],giver_loc=[[Kreldig Ungor]],giverType=[[NPC]],giverId=5638,ender=[[Roetten Stonehammer]],ender_loc=[[Roetten Rocamartillo]],enderType=[[NPC]],enderId=5637,prevId=1466,poiX=-4681,poiY=-1267,wowhead=[[https://www.wowhead.com/wotlk/quest=1467]],image=[[assets/images/quests/placeholder.png]],desc=[[To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway. Just give him this and it should be enough to get your booty. And don't worry, I'm still going to put in a good word for you when I get back. I shouldn't be in Desolace much longer.]],logDesc=[[Bring Leftwitch's Package back to Roetten Stonehammer in Ironforge.]],choiceRewards={{id=6793,qty=1},{id=6794,qty=1}}}
DB[1468]={id=1468,name=[[Children's Week]],name_loc=[[Semana de los Niños]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Human Orphan]],ender_loc=[[Huérfano humano]],enderType=[[NPC]],enderId=14305,wowhead=[[https://www.wowhead.com/wotlk/quest=1468]],image=[[assets/images/quests/placeholder.png]],desc=[[You're willing to help us here at the orphanage?  Bless you, friend; your aid during Children's Week will be invaluable. Take this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children's Week itself.  When you use it, you will be able to talk with the child you've agreed to look after.  Using it again will dismiss the child. By all means $N - use the whistle and meet your ward!  I'm sure the child will be most eager to meet you.]],logDesc=[[Use the Human Orphan Whistle to talk with the child you will be looking after during Children's Week.]]}
DB[1469]={id=1469,zoneId=47,name=[[Rhapsody's Tale]],name_loc=[[El relato de Rapsodio]],level=43,minLevel=38,giver=[[Rhapsody Shindigger]],giver_loc=[[Rapsodio Machacacanillas]],giverType=[[NPC]],giverId=5634,ender=[[Brohann Caskbelly]],ender_loc=[[Brohann Barriliga]],enderType=[[NPC]],enderId=5384,prevId=1452,rewardNextId=1475,poiX=-8464,poiY=516,wowhead=[[https://www.wowhead.com/wotlk/quest=1469]],image=[[assets/images/quests/placeholder.png]],desc=[[Before the flight, I drank me a whole keg of stout. Hiccup! And what a flight it was. Zipping around with Brohann following me. Didn't see no temple though. Hiccup! Well, didn't see no temple till I got a little too tipsy and fell off my mount. I plunged right into the water and was sucked down. Found myself surrounded by a bunch of creepy trolls. Sure swam out of there fast! Even made off with this troll souvenir. Here, take it to Brohann and let him know his temple is down there, indeed. Hiccup!]],logDesc=[[Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind.]]}
DB[1470]={id=1470,name=[[Piercing the Veil]],name_loc=[[Descubrir el misterio]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=1897,poiY=1473,wowhead=[[https://www.wowhead.com/wotlk/quest=1470]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, child. I can see that you are still young in the ways of the warlock, power still eluding your grasp. I can sense your eagerness to learn. And you will learn. There is no strength in ignorance. Knowledge is our greatest power. Through its application, we can control the chaotic magics and beings of the void, bending them to our will. I will show you how to bind a servant to your will, but first you must bring me three skulls of the rattlecage skeletons near the abandoned smithy.]],logDesc=[[Bring Venya Marthand 3 Rattlecage Skulls.]]}
DB[1471]={id=1471,name=[[The Binding]],name_loc=[[El vínculo]],level=-1,minLevel=10,giver=[[Carendin Halgar]],giverType=[[NPC]],giverId=5675,ender=[[Carendin Halgar]],enderType=[[NPC]],enderId=5675,prevId=1473,poiX=1705,poiY=41,wowhead=[[https://www.wowhead.com/wotlk/quest=1471]],image=[[assets/images/quests/placeholder.png]],desc=[[Surely you have seen the circle of summoning below us? Only there will you be able to draw forth an unbound voidwalker. Using these runes, you will be able to draw it forth, and then you must dominate it through strength of arms and magic. When it is subdued, it will be indentured to you. Come to me then, and I will elucidate the spell of summoning, so that it may serve you to whatever end you wish.]],logDesc=[[Using the Runes of Summoning, summon and subdue a voidwalker, then return the Runes of Summoning to Carendin Halgar in the Magic Quarter of the Undercity.]]}
DB[1472]={id=1472,name=[[Devourer of Souls]],name_loc=[[Devoradora de almas]],level=-1,minLevel=20,giver=[[Carendin Halgar]],giverType=[[NPC]],giverId=5675,ender=[[Godrick Farsan]],enderType=[[NPC]],enderId=5693,rewardNextId=1476,exGroup=1472,poiX=1783,poiY=60,wowhead=[[https://www.wowhead.com/wotlk/quest=1472]],image=[[assets/images/quests/placeholder.png]],desc=[[A succubus is a devourer of souls, destroyer of hearts, tempter of men. A creature of profound evil and of singular mind. It cannot be brought into our world without a stimulus. Thus we use its own strength against it. With the hearts of good men, pure men, loving men, the succubus will be unable to resist, and will cross into our world. Then you can dominate it, and make it your own. Speak with my assistant, Godrick Farsan, within the Temple. He will help you find your bait.]],logDesc=[[Speak with Godrick Farsan in the Temple of the Damned.]]}
DB[1473]={id=1473,name=[[Creature of the Void]],name_loc=[[Criatura Abisal]],level=-1,minLevel=10,giver=[[Carendin Halgar]],giverType=[[NPC]],giverId=5675,ender=[[Carendin Halgar]],enderType=[[NPC]],enderId=5675,rewardNextId=1471,poiX=1802,poiY=726,wowhead=[[https://www.wowhead.com/wotlk/quest=1473]],image=[[assets/images/quests/placeholder.png]],desc=[[It seems the consensus that you are ready to learn to summon a voidwalker. A being created of the chaos that lies beyond, if you summon one but cannot control it, you will be torn asunder. The first voidwalker was summoned by Egalin, and in his grimoire is the process explained. Unfortunately, it was stolen from us by an agent of the Scarlet Crusade who has it secreted away in his base at a tower to the west. Bring it to me, and I will impart the knowledge to you.]],logDesc=[[Recover Egalin's Grimoire and bring it to Carendin Halgar in the Temple of the Damned.]]}
DB[1474]={id=1474,name=[[The Binding]],name_loc=[[El vínculo]],level=-1,minLevel=20,giver=[[Carendin Halgar]],giverType=[[NPC]],giverId=5675,ender=[[Carendin Halgar]],enderType=[[NPC]],enderId=5675,prevId=1476,poiX=1705,poiY=41,wowhead=[[https://www.wowhead.com/wotlk/quest=1474]],image=[[assets/images/quests/placeholder.png]],desc=[[Using these hearts, cast a spell at the summoning circle to open a doorway for the succubus to come through. Your powers are greater now, and you will need all of them to defeat the succubus.  Beware its charms, $n, many a strong mind has been bound to its will. When overcome, the succubus will be returned to the void, and I will teach you the spell to summon it forth at your command.]],logDesc=[[Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity.]],rewards={{id=22243,qty=1}}}
DB[1475]={id=1475,zoneId=1417,name=[[Into The Temple of Atal'Hakkar]],name_loc=[[En El Templo de Atal'Hakkar]],level=50,minLevel=38,giver=[[Brohann Caskbelly]],giver_loc=[[Brohann Barriliga]],giverType=[[NPC]],giverId=5384,ender=[[Brohann Caskbelly]],ender_loc=[[Brohann Barriliga]],enderType=[[NPC]],enderId=5384,prevId=1469,poiX=-8464,poiY=516,wowhead=[[https://www.wowhead.com/wotlk/quest=1475]],image=[[assets/images/quests/placeholder.png]],desc=[[According to legend, The Temple of Atal'Hakkar is a holy shrine dedicated to the ancient god, Hakkar the Soulflayer. Maintained by a vicious tribe of trolls named the Atal'ai, the temple is rumored to be impenetrable. Now sunk beneath the Pool of Tears, retrieving artifacts from the temple is even more difficult. But that's what I need you to do, $n. Aid me by gathering the intact Atal'ai Tablets. Bring them to me and I will return to the Explorers' Guild a hero. Together we will share the glory.]],logDesc=[[Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind.]],rewards={{id=1490,qty=1}}}
DB[1476]={id=1476,name=[[Hearts of the Pure]],name_loc=[[Corazones puros]],level=-1,minLevel=20,giver=[[Godrick Farsan]],giverType=[[NPC]],giverId=5693,ender=[[Carendin Halgar]],enderType=[[NPC]],enderId=5675,prevId=1472,rewardNextId=1474,poiX=1712,poiY=57,wowhead=[[https://www.wowhead.com/wotlk/quest=1476]],image=[[assets/images/quests/placeholder.png]],desc=[[Men of honor and goodness? Does such a man exist? It took much research, but through bits of overheard stories, I managed to find two men that should do. The first is Dalin Forgewright, who has dedicated himself to the care of the Lordaeron refugees, whom are refused by their kin at the Greymane Wall. The other is Comar Villard, a man who remains faithful to his lost love, wandering the Wetlands for a sign of his wife. Deliver their hearts to Carendin. But first, let me show you your quarry.]],logDesc=[[Bring the hearts of Dalin Forgewright and Comar Villard to Carendin Halgar in the Temple of the Damned.]]}
DB[1477]={id=1477,zoneId=1519,name=[[Vital Supplies]],name_loc=[[Suministros de vital importancia]],level=45,minLevel=40,giver=[[High Sorcerer Andromath]],giver_loc=[[Sumo Hechicero Andromath]],giverType=[[NPC]],giverId=5694,ender=[[Watchmaster Sorigal]],ender_loc=[[Maestro de vigilantes Sorigal]],enderType=[[NPC]],enderId=5464,rewardNextId=1395,poiX=-10547,poiY=-1213,wowhead=[[https://www.wowhead.com/wotlk/quest=1477]],image=[[assets/images/quests/placeholder.png]],desc=[[Our mages are conducting research at Nethergarde Keep in the Blasted Lands, research vital to our understanding of the Dark Portals. They require nearly constant supplies, but our supply line to Nethergarde is tenuous. You must help ensure the supplies make it to Nethergard.  Report to Watchmaster Sorigal in Darkshire, and do as he asks.  This task will take you into hostile lands, $N.  Prepare yourself.]],logDesc=[[Speak with Watchmaster Sorigal at Darkshire in Duskwood.]]}
DB[1478]={id=1478,name=[[Halgar's Summons]],name_loc=[[Las invocaciones de Halgar]],level=-1,minLevel=10,giver=[[Ageron Kargal]],giverType=[[NPC]],giverId=5724,ender=[[Carendin Halgar]],enderType=[[NPC]],enderId=5675,rewardNextId=1473,poiX=1712,poiY=57,wowhead=[[https://www.wowhead.com/wotlk/quest=1478]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, $n! I just received word from Carendin Halgar that he would like to see you for further training. You should be proud of yourself, $n. It's not every day that Master Halgar personally sees fit to instruct a young warlock. You'll be able to find him in the Magic Quarter of the Undercity, near the Temple of the Damned.]],logDesc=[[Speak with Carendin Halgar in the Undercity.]]}
DB[1479]={id=1479,name=[[The Bough of the Eternals]],name_loc=[[La Rama de los Eternos]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Human Orphan]],ender_loc=[[Huérfano humano]],enderType=[[NPC]],enderId=14305,prevId=1468,exGroup=-1479,poiX=9933,poiY=2500,wowhead=[[https://www.wowhead.com/wotlk/quest=1479]],image=[[assets/images/quests/placeholder.png]],desc=[[I've heard stories about how the night elves have their bank in a tree - one that looks like a bear!  That's so cool!  Night elves are neat how they like nature and stuff, but bears are just totally awesome! Would you take me to see the bear-tree in Darnassus, please?  There's a boat that will take us close to there, and it shouldn't take very long.  Please, please, please!]],logDesc=[[Take the orphan to the bank of Darnassus.  The bank itself is hollowed out of a tree known as the Bough of the Eternals.]]}
DB[1480]={id=1480,zoneId=405,name=[[The Corrupter]],name_loc=[[El corruptor]],level=33,minLevel=25,giverType=[[NPC]],ender=[[Maurin Bonesplitter]],ender_loc=[[Maurin Partehuesos]],enderType=[[NPC]],enderId=4498,rewardNextId=1481,poiX=-336,poiY=1639,wowhead=[[https://www.wowhead.com/wotlk/quest=1480]],image=[[assets/images/quests/placeholder.png]],desc=[[The torn skin smells rotten, and is remarkably pliable for something that appears to be dry and fragile. As you unroll it, you can clearly see the red markings of some kind of language on one side. At the bottom of the skin is a very clear symbol that you guess is a signature of some kind. Perhaps it is something Maurin could tell you more about?]],logDesc=[[Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace.]]}
DB[1481]={id=1481,zoneId=405,name=[[The Corrupter]],name_loc=[[El corruptor]],level=33,minLevel=25,giver=[[Maurin Bonesplitter]],giver_loc=[[Maurin Partehuesos]],giverType=[[NPC]],giverId=4498,ender=[[Maurin Bonesplitter]],ender_loc=[[Maurin Partehuesos]],enderType=[[NPC]],enderId=4498,prevId=1480,rewardNextId=1482,poiX=-39,poiY=612,wowhead=[[https://www.wowhead.com/wotlk/quest=1481]],image=[[assets/images/quests/placeholder.png]],desc=[[I believe I can find this demon lord given the proper reagents. If he is indeed as powerful as I suspect, I will need items gathered from deadly creatures. But you act in the Warchief's name, so I am sure you will accept my task. First, I will have to break any wards he has against scrying. For this, I will need the scalp from a satyr--but not any satyr. The scalp must come from a Hatefury shadowstalker. Search for them among the ancient ruins in the northeast of Desolace.]],logDesc=[[Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace.]]}
DB[1482]={id=1482,zoneId=405,name=[[The Corrupter]],name_loc=[[El corruptor]],level=35,minLevel=25,giver=[[Maurin Bonesplitter]],giver_loc=[[Maurin Partehuesos]],giverType=[[NPC]],giverId=4498,ender=[[Maurin Bonesplitter]],ender_loc=[[Maurin Partehuesos]],enderType=[[NPC]],enderId=4498,prevId=1481,poiX=-52,poiY=2424,wowhead=[[https://www.wowhead.com/wotlk/quest=1482]],image=[[assets/images/quests/placeholder.png]],desc=[[An oracle crystal would do nicely. They are crafted by the naga for their oracles to use. Northwest of here, along the coast, is a vast coral reef that the naga have taken as their home when this close to the shore. You can find their oracles there. The Slitherblade are deadly and will not react kindly to your intrusions, so be careful and make haste. When you return, we shall see about finding this demon lord Azrethoc.]],logDesc=[[Bring an Oracle Crystal to Maurin Bonesplitter in Desolace.]]}
DB[1483]={id=1483,zoneId=17,name=[[Ziz Fizziks]],name_loc=[[Ziz Fizziks]],level=21,minLevel=16,giver=[[Sputtervalve]],giver_loc=[[Petardol]],giverType=[[NPC]],giverId=3442,ender=[[Ziz Fizziks]],enderType=[[NPC]],enderId=4201,rewardNextId=1093,poiX=878,poiY=365,wowhead=[[https://www.wowhead.com/wotlk/quest=1483]],image=[[assets/images/quests/placeholder.png]],desc=[[The Venture Company stole many of the best goblin minds, but from time to time, we get the opportunity to steal some back. A while ago, the Venture Company outfit in the Stonetalon Mountains hired Gerenzo Wrenchwhistle--a gnome! Their other engineer, Ziz Fizziks, was so taken aback by this, he pleaded with me to find him new employment with the Tinkers' Union. I set him on a few tasks, but he might need help. Maybe you could look in on him for me? He's stationed at the western edge of Windshear Crag.]],logDesc=[[Speak with Ziz Fizziks in Windshear Crag in Stonetalon Mountains.]]}
DB[1484]={id=1484,zoneId=405,name=[[The Corrupter]],name_loc=[[El corruptor]],level=33,minLevel=25,giver=[[Maurin Bonesplitter]],giver_loc=[[Maurin Partehuesos]],giverType=[[NPC]],giverId=4498,ender=[[Takata Steelblade]],ender_loc=[[Takata Hoja de Acero]],enderType=[[NPC]],enderId=5641,prevId=1482,poiX=-1178,poiY=1870,wowhead=[[https://www.wowhead.com/wotlk/quest=1484]],image=[[assets/images/quests/placeholder.png]],desc=[[This creature is far more dangerous than I had anticipated.  No doubt Takata questions my abilities to take on such a creature, and it would insult his honor if he were not informed about what just happened. Speak to the swordsman, tell him you are willing to slay the demon if he would allow it, but do not press too hard. It is better if he thinks it his own idea.]],logDesc=[[Speak to Takata Steelblade in Desolace.]]}
DB[1485]={id=1485,name=[[Vile Familiars]],name_loc=[[Familiares viles]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=1499,poiX=-210,poiY=-4447,wowhead=[[https://www.wowhead.com/wotlk/quest=1485]],image=[[assets/images/quests/placeholder.png]],desc=[[Those warlocks who came before us have earned the distrust of the Horde, and while we are tolerated, we are not loved. This has not brought the warlocks closer together, however, as many choose to live reclusively, dabbling in their magics alone. I will not seek to lead you down one path or the other, but only help you in your maturation. Before I teach you the art of summoning, bring me six heads of the vile familiars from the cave to the northeast.]],logDesc=[[Bring 6 Vile Familiar Heads to Ruzan.]]}
DB[1486]={id=1486,zoneId=718,name=[[Deviate Hides]],name_loc=[[Pellejos descarriados]],level=17,minLevel=13,giver=[[Nalpak]],giver_loc=[[Nalpak]],giverType=[[NPC]],giverId=5767,ender=[[Nalpak]],ender_loc=[[Nalpak]],enderType=[[NPC]],enderId=5767,poiX=-624,poiY=-2383,wowhead=[[https://www.wowhead.com/wotlk/quest=1486]],image=[[assets/images/quests/placeholder.png]],desc=[[As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns. These deviate creatures have strange, otherworldly properties. While evil in nature, it is my opinion that some good can come from their existence here in Kalimdor. I believe their hides will be of particular use in the ways of leatherworking. If you feel up to the task, venture into the caves below and retrieve some deviate hides.]],logDesc=[[Nalpak in the Wailing Caverns wants 20 Deviate Hides.]],choiceRewards={{id=6480,qty=1},{id=918,qty=1}}}
DB[1487]={id=1487,zoneId=718,name=[[Deviate Eradication]],name_loc=[[Erradicación de descarriados]],level=21,minLevel=15,giver=[[Ebru]],giver_loc=[[Ebru]],giverType=[[NPC]],giverId=5768,ender=[[Ebru]],ender_loc=[[Ebru]],enderType=[[NPC]],enderId=5768,poiX=-28,poiY=84,wowhead=[[https://www.wowhead.com/wotlk/quest=1487]],image=[[assets/images/quests/placeholder.png]],desc=[[Naralex had a noble goal. Our great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was. But something went terribly wrong. Naralex's dream turned into a nightmare and corrupt creatures began to inhabit the caverns. While some Disciples of Naralex seek to awake our master, my concern is with ridding these caves of the evil beasts. Brave the caverns, $n, and eradicate the deviate spawn.]],logDesc=[[Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.]],choiceRewards={{id=6476,qty=1},{id=8071,qty=1},{id=6481,qty=1}}}
DB[1488]={id=1488,zoneId=405,name=[[The Corrupter]],name_loc=[[El corruptor]],level=40,minLevel=25,giver=[[Takata Steelblade]],giver_loc=[[Takata Hoja de Acero]],giverType=[[NPC]],giverId=5641,ender=[[Takata Steelblade]],ender_loc=[[Takata Hoja de Acero]],enderType=[[NPC]],enderId=5641,prevId=1484,poiX=-1883,poiY=1714,wowhead=[[https://www.wowhead.com/wotlk/quest=1488]],image=[[assets/images/quests/placeholder.png]],desc=[[Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals. You have already shown you wish to aid the Warchief, and I would trust you to gather a party to slay the demon lord and his warlock servant. When you are ready, head directly south,  and return to me when the threat has been ended.]],logDesc=[[Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace.]],choiceRewards={{id=6746,qty=1},{id=6747,qty=1}}}
DB[1489]={id=1489,zoneId=718,name=[[Hamuul Runetotem]],name_loc=[[Hamuul Runatótem]],level=16,minLevel=10,giver=[[Tonga Runetotem]],giver_loc=[[Tonga Tótem de Runa]],giverType=[[NPC]],giverId=3448,ender=[[Arch Druid Hamuul Runetotem]],ender_loc=[[Archidruida Hamuul Tótem de Runa]],enderType=[[NPC]],enderId=5769,prevId=880,rewardNextId=1490,poiX=-1049,poiY=-304,wowhead=[[https://www.wowhead.com/wotlk/quest=1489]],image=[[assets/images/quests/placeholder.png]],desc=[[The shells you brought me have a taint, one I have never before seen.  I am certain the water of the Oases is the cause, and I can sense the confusion they cause this land.  It is as if the land dreams and cannot awake. The Wailing Caverns must be the source of the taint.  But before you go there, speak with Hamuul Runetotem, the elder druid.  I sent word to him of the happenings in the Barrens.  He is wise, and can offer you counsel. You will find him in Thunder Bluff, on the Elder Rise.]],logDesc=[[Speak with Hamuul Runetotem.]]}
DB[1490]={id=1490,zoneId=718,name=[[Nara Wildmane]],name_loc=[[Nara Ferocrín]],level=16,minLevel=10,giver=[[Arch Druid Hamuul Runetotem]],giver_loc=[[Archidruida Hamuul Tótem de Runa]],giverType=[[NPC]],giverId=5769,ender=[[Nara Wildmane]],ender_loc=[[Nara Ferocrín]],enderType=[[NPC]],enderId=5770,prevId=1489,rewardNextId=914,poiX=-1070,poiY=-273,wowhead=[[https://www.wowhead.com/wotlk/quest=1490]],image=[[assets/images/quests/placeholder.png]],desc=[[I entered the land of dreams, and dreamed of a cult of druids who dwell in the Wailing Caverns.  I saw that their goals were once noble, but they have lost their way.  They are now servants of the taint seeping through the Barrens. I am old and my strength fails.  I could not long dwell in that dreaming place and know little more of the tainted druids.  But Nara is young and her spirit is fierce.  She remained in the dreaming when I fled. Speak with Nara.  She is in the tent, over yonder.]],logDesc=[[Speak with Nara Wildmane.]]}
DB[1491]={id=1491,zoneId=718,name=[[Smart Drinks]],name_loc=[[Bebidas de inteligencia]],level=18,minLevel=13,giver=[[Mebok Mizzyrix]],giverType=[[NPC]],giverId=3446,ender=[[Mebok Mizzyrix]],enderType=[[NPC]],enderId=3446,prevId=865,poiX=-552,poiY=-2291,wowhead=[[https://www.wowhead.com/wotlk/quest=1491]],image=[[assets/images/quests/placeholder.png]],desc=[[Ok, so the raptor horns didn't work so well.  But that's all right -- no one got rich on their first try!  And besides, I think I found something that'll work even better in my smart drinks! There is a substance called Wailing Essence, and I think it is the cause of the strange plants and animals in the Barrens.  Get me some and I'll try it in my drink! I heard the essence gathers in ectoplasmic creatures in the Wailing Caverns to the west.  Hunt those creatures and gather the essence.]],logDesc=[[Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet.]]}
DB[1492]={id=1492,zoneId=17,name=[[Wharfmaster Dizzywig]],name_loc=[[Maestro de muelles Vertipeluca]],level=11,minLevel=9,giver=[[Apothecary Helbrim]],giver_loc=[[Boticario Helbrim]],giverType=[[NPC]],giverId=3390,ender=[[Wharfmaster Dizzywig]],ender_loc=[[Maestro de muelles Vertipeluca]],enderType=[[NPC]],enderId=3453,poiX=-986,poiY=-3797,wowhead=[[https://www.wowhead.com/wotlk/quest=1492]],image=[[assets/images/quests/placeholder.png]],desc=[[I have need to send a crate of potions, reagents and other items to my associates in the Old World. Little time I have to actually see them to the dock at Ratchet, and the last caravan has already left. If you could, please take this to Wharfmaster Dizzywig. He will ensure that it is placed on the next boat to Blackwater Cove.]],logDesc=[[Bring the Secure Crate to Wharfmaster Dizzywig in Ratchet.]]}
DB[1498]={id=1498,name=[[Path of Defense]],name_loc=[[Camino de defensa]],level=-1,minLevel=10,giver=[[Uzzek]],giverType=[[NPC]],giverId=5810,ender=[[Uzzek]],enderType=[[NPC]],enderId=5810,prevId=1505,rewardNextId=1502,poiX=960,poiY=-4270,wowhead=[[https://www.wowhead.com/wotlk/quest=1498]],image=[[assets/images/quests/placeholder.png]],desc=[[As a warrior, one of our most crucial tasks is... protection.  We are the shield of the Horde, and we keep our weaker brethren safe.  If you are to join in our ranks, then you must prove your mettle to me. Go to Thunder Ridge in Durotar, where live the lightning hides and thunder lizards.  Hunt the beasts!  Show me you are tougher than they!  Brave their assaults and bring me a stack of their singed scales as proof. Do this, and then I will teach you.]],logDesc=[[Bring 5 Singed Scales to Uzzek at Far Watch Post in the Barrens.]]}
DB[1499]={id=1499,name=[[Vile Familiars]],name_loc=[[Familiares viles]],level=-1,minLevel=1,giver=[[Ruzan]],giverType=[[NPC]],giverId=5765,ender=[[Zureetha Fargaze]],ender_loc=[[Zureetha Vistalonga]],enderType=[[NPC]],enderId=3145,prevId=1485,nextId=794,rewardNextId=794,poiX=-629,poiY=-4228,wowhead=[[https://www.wowhead.com/wotlk/quest=1499]],image=[[assets/images/quests/placeholder.png]],desc=[[Zureetha has been sending novices like yourself to help cull the numbers of the creatures in the cave near where you fought the vile familiars. I think it would be good for you to gain experience by assisting her. Be sure to tell her that you assisted with the imp problem, she'll probably have a reward for you.]],logDesc=[[Speak with Zureetha Fargaze.]],choiceRewards={{id=4925,qty=1},{id=5778,qty=1}}}
DB[1501]={id=1501,name=[[Creature of the Void]],name_loc=[[Criatura Abisal]],level=-1,minLevel=10,giver=[[Gan'rul Bloodeye]],giver_loc=[[Gan'rul Ojosangre]],giverType=[[NPC]],giverId=5875,ender=[[Gan'rul Bloodeye]],ender_loc=[[Gan'rul Ojosangre]],enderType=[[NPC]],enderId=5875,rewardNextId=1504,poiX=1464,poiY=-4692,wowhead=[[https://www.wowhead.com/wotlk/quest=1501]],image=[[assets/images/quests/placeholder.png]],desc=[[So few warlocks remain... We risk much, but the risks are warranted. You must quickly reach maturity in your ability if you are to be of use to the Horde and to the Warchief. It is time that you learned a new summoning spell. First, you must recover the Tablet of Verga, which was stolen by warlocks of the Burning Blade and is now kept at their lair in Skull Rock to the east of the city. With the tablet, I will show you the runes necessary to summoning a voidwalker.]],logDesc=[[Retrieve the Tablet of Verga for Gan'rul Bloodeye in Orgrimmar.]]}
DB[1502]={id=1502,name=[[Thun'grim Firegaze]],name_loc=[[Thun'grim Vistafuego]],level=10,minLevel=10,giver=[[Uzzek]],giverType=[[NPC]],giverId=5810,ender=[[Thun'grim Firegaze]],ender_loc=[[Thun'grim Vistafuego]],enderType=[[NPC]],enderId=5878,prevId=1498,rewardNextId=1503,poiX=-438,poiY=-3176,wowhead=[[https://www.wowhead.com/wotlk/quest=1502]],image=[[assets/images/quests/placeholder.png]],desc=[[It is vital that a warrior's weapon is one of quality.  And if there is an orc who can craft quality weapons, then that orc is Thun'grim Firegaze.  He is a hermit who dwells atop the hills east of the Crossroads. If you seek a weapon, warrior, then you should seek Thun'grim.  To find him, first travel to the Crossroads to the west, then strike east into the hills.  His camp is high on a hilltop.]],logDesc=[[Speak with Thun'grim Firegaze in the Barrens.]]}
DB[1503]={id=1503,name=[[Forged Steel]],name_loc=[[Acero fundido]],level=10,minLevel=10,giver=[[Thun'grim Firegaze]],giver_loc=[[Thun'grim Vistafuego]],giverType=[[NPC]],giverId=5878,ender=[[Thun'grim Firegaze]],ender_loc=[[Thun'grim Vistafuego]],enderType=[[NPC]],enderId=5878,prevId=1502,poiX=-188,poiY=-2955,wowhead=[[https://www.wowhead.com/wotlk/quest=1503]],image=[[assets/images/quests/placeholder.png]],desc=[[I will give you a weapon, $N, but first you must aid me.  The Razormanes to the northwest came into my camp a few nights past.  They would not meet me in combat, but they know my eyes are bad--a few distracted me with snorts while others stole from me!  The cowards! They took an iron chest, and within it were some forged steel bars.  If you can recover them then I will give you the weapon you seek. Search for the iron box within the quilboar camps, and return with the forged steel bars.]],logDesc=[[Bring the Forged Steel Bars to Thun'grim Firegaze in the Barrens.]],choiceRewards={{id=7326,qty=1},{id=7328,qty=1},{id=7327,qty=1},{id=7329,qty=1}}}
DB[1504]={id=1504,name=[[The Binding]],name_loc=[[El vínculo]],level=-1,minLevel=10,giver=[[Gan'rul Bloodeye]],giver_loc=[[Gan'rul Ojosangre]],giverType=[[NPC]],giverId=5875,ender=[[Gan'rul Bloodeye]],ender_loc=[[Gan'rul Ojosangre]],enderType=[[NPC]],enderId=5875,prevId=1501,poiX=1850,poiY=-4357,wowhead=[[https://www.wowhead.com/wotlk/quest=1504]],image=[[assets/images/quests/placeholder.png]],desc=[[Now, observe the Tablet of Verga, for it contains the glyphs you will need for the summoning. Take them to the circle in Neeru Fireblade's tent on the other side of the cavern. There you will be able to call for the voidwalker. You must defeat it using whatever physical and magical means you have at your disposal. When this is completed, return to me with the glyphs of summoning and I will demonstrate how you may bind the creature to your will.]],logDesc=[[Using the Glyphs of Summoning, summon and subdue a voidwalker, then return the Glyphs of Summoning to Gan'rul Bloodeye in Orgrimmar.]]}
DB[1505]={id=1505,name=[[Veteran Uzzek]],name_loc=[[Uzzek, el veterano]],level=-1,minLevel=10,giver=[[Krang Stonehoof]],giver_loc=[[Krang Pezuña Pétrea]],giverType=[[NPC]],giverId=3063,ender=[[Uzzek]],enderType=[[NPC]],enderId=5810,rewardNextId=1498,exGroup=1505,poiX=186,poiY=-3597,wowhead=[[https://www.wowhead.com/wotlk/quest=1505]],image=[[assets/images/quests/placeholder.png]],desc=[[The Horde honors its warriors because their strength is unquestioned.  But the truly great warriors are great students as well. Seek out Uzzek.  He is a veteran of many battles and now instructs young warriors in the ways of combat.  You will find him south of Far Watch Post, the orc garrison on the border of the Barrens and Durotar.]],logDesc=[[Speak with Uzzek at Far Watch Post in the Barrens.]]}
DB[1505]={id=1505,name=[[Veteran Uzzek]],name_loc=[[Uzzek, el veterano]],level=-1,minLevel=10,giver=[[Tarshaw Jaggedscar]],giver_loc=[[Krang Pezuña Pétrea]],giverType=[[NPC]],giverId=3169,ender=[[Uzzek]],enderType=[[NPC]],enderId=5810,rewardNextId=1498,exGroup=1505,poiX=186,poiY=-3597,wowhead=[[https://www.wowhead.com/wotlk/quest=1505]],image=[[assets/images/quests/placeholder.png]],desc=[[The Horde honors its warriors because their strength is unquestioned.  But the truly great warriors are great students as well. Seek out Uzzek.  He is a veteran of many battles and now instructs young warriors in the ways of combat.  You will find him south of Far Watch Post, the orc garrison on the border of the Barrens and Durotar.]],logDesc=[[Speak with Uzzek at Far Watch Post in the Barrens.]]}
DB[1505]={id=1505,name=[[Veteran Uzzek]],name_loc=[[Uzzek, el veterano]],level=-1,minLevel=10,giver=[[Sorek]],giver_loc=[[Krang Pezuña Pétrea]],giverType=[[NPC]],giverId=3354,ender=[[Uzzek]],enderType=[[NPC]],enderId=5810,rewardNextId=1498,exGroup=1505,poiX=186,poiY=-3597,wowhead=[[https://www.wowhead.com/wotlk/quest=1505]],image=[[assets/images/quests/placeholder.png]],desc=[[The Horde honors its warriors because their strength is unquestioned.  But the truly great warriors are great students as well. Seek out Uzzek.  He is a veteran of many battles and now instructs young warriors in the ways of combat.  You will find him south of Far Watch Post, the orc garrison on the border of the Barrens and Durotar.]],logDesc=[[Speak with Uzzek at Far Watch Post in the Barrens.]]}
DB[1506]={id=1506,name=[[Gan'rul's Summons]],name_loc=[[Las invocaciones de Gan'rul]],level=-1,minLevel=10,giver=[[Ophek]],giverType=[[NPC]],giverId=3294,ender=[[Gan'rul Bloodeye]],ender_loc=[[Gan'rul Ojosangre]],enderType=[[NPC]],enderId=5875,rewardNextId=1501,poiX=1850,poiY=-4357,wowhead=[[https://www.wowhead.com/wotlk/quest=1506]],image=[[assets/images/quests/placeholder.png]],desc=[[You there. $n, right? I hope your schedule isn't busy, because Gan'rul wants to see you right away. You'll find him with the senior warlocks in the Cleft of Shadow. Based on my past dealings with Gan'rul, your summons is either a very good thing or a very bad thing.]],logDesc=[[Speak with Gan'rul Bloodeye in Orgrimmar.]]}
DB[1507]={id=1507,name=[[Devourer of Souls]],name_loc=[[Devoradora de almas]],level=-1,minLevel=20,giver=[[Gan'rul Bloodeye]],giver_loc=[[Gan'rul Ojosangre]],giverType=[[NPC]],giverId=5875,ender=[[Cazul]],enderType=[[NPC]],enderId=5909,rewardNextId=1508,exGroup=1472,poiX=1840,poiY=-4341,wowhead=[[https://www.wowhead.com/wotlk/quest=1507]],image=[[assets/images/quests/placeholder.png]],desc=[[The time has come for you to learn more of the summoning magics. You will learn to summon a succubus, a creature of incredible mental powers. It can lull those of weak minds into its servitude--but have no fear! I feel certain that you will be equal to the challenge. A succubus can only be summoned when baited with an item that represents great devotion and love. I leave it to you to find such an object. A suggestion? Speak with Cazul... There seems to be little the ancient warlock does not know.]],logDesc=[[Speak with Cazul in the Cleft of Shadow.]]}
DB[1508]={id=1508,name=[[Blind Cazul]],name_loc=[[Cazul, el ciego]],level=-1,minLevel=20,giver=[[Cazul]],giverType=[[NPC]],giverId=5909,ender=[[Zankaja]],enderType=[[NPC]],enderId=5910,prevId=1507,rewardNextId=1509,poiX=1718,poiY=-4200,wowhead=[[https://www.wowhead.com/wotlk/quest=1508]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmm... But, of course, that is not why you have come to speak with me. If Gan'rul has sent you to me, it must be that you are to summon a succubus, and need an object to use for enticement. Hmm... If you trust a blind man to lead you, $n, then listen. In the bluffs of Orgrimmar, west of the wind rider tower, lives Zankaja. She waits for the return of her mate. Go to her.]],logDesc=[[Speak with Zankaja in Orgrimmar.]]}
DB[1509]={id=1509,name=[[News of Dogran]],name_loc=[[Noticias de Dogran]],level=-1,minLevel=20,giver=[[Zankaja]],giverType=[[NPC]],giverId=5910,ender=[[Gazrog]],enderType=[[NPC]],enderId=3464,prevId=1508,rewardNextId=1510,poiX=-436,poiY=-2639,wowhead=[[https://www.wowhead.com/wotlk/quest=1509]],image=[[assets/images/quests/placeholder.png]],desc=[[My mate, Dogran, was recently sent to the Crossroads for duty. It was a promotion, and he was very proud. I was sad, of course, but I didn't let him know that. And worried, too. The Barrens is a more dangerous place than Orgrimmar, and I feared the worst. Now it's been a week after he should have returned, and I have received no word from him... Perhaps you could go to the Crossroads and see if they have any news? He worked with Gazrog, who should still be stationed there.]],logDesc=[[Speak with Gazrog at the Crossroads.]]}
DB[1510]={id=1510,name=[[News of Dogran]],name_loc=[[Noticias de Dogran]],level=-1,minLevel=20,giver=[[Gazrog]],giverType=[[NPC]],giverId=3464,ender=[[Ken'zigla]],enderType=[[NPC]],enderId=4197,prevId=1509,rewardNextId=1511,poiX=-181,poiY=-331,wowhead=[[https://www.wowhead.com/wotlk/quest=1510]],image=[[assets/images/quests/placeholder.png]],desc=[[He was stationed at Camp Taurajo, where we've been trying to weed out the quilboar. He led a few grunts to one of their camps, where he was hurt bad. The others made it back and tried to rescue him. He was in bad shape, his wounds festered, so they were afraid to move him without patching him up first. They sent a message here, requesting a healing draught from the trolls at the Malaka'jin at the base of the Stonetalon Mountains. We sent someone to get it, but they haven't returned yet.]],logDesc=[[Speak with Ken'zigla at the Malaka'jin.]]}
DB[1511]={id=1511,name=[[Ken'zigla's Draught]],name_loc=[[Jarabe de Ken'zigla]],level=-1,minLevel=20,giver=[[Ken'zigla]],giverType=[[NPC]],giverId=4197,ender=[[Grunt Logmar]],ender_loc=[[Bruto Logmar]],enderType=[[NPC]],enderId=5911,prevId=1510,rewardNextId=1515,poiX=-2392,poiY=-1899,wowhead=[[https://www.wowhead.com/wotlk/quest=1511]],image=[[assets/images/quests/placeholder.png]],desc=[[I figured there might be another coming to get the draught, so I prepared it anyways. Here you go, $n. Mind you, you should only give half of it to him! That will give him enough strength to move without bleeding himself dry. Wait a night, then give him the other half. Anyways, you'll want to bring this to Logmar at Camp Taurajo. From what the first one told me, he should have an idea where this Dogran is.]],logDesc=[[Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo.]]}
DB[1512]={id=1512,name=[[Love's Gift]],name_loc=[[Un regalo de amor]],level=-1,minLevel=20,giver=[[Grunt Dogran]],giver_loc=[[Bruto Dogran]],giverType=[[NPC]],giverId=5908,ender=[[Gan'rul Bloodeye]],ender_loc=[[Gan'rul Ojosangre]],enderType=[[NPC]],enderId=5875,prevId=1515,rewardNextId=1513,poiX=1850,poiY=-4357,wowhead=[[https://www.wowhead.com/wotlk/quest=1512]],image=[[assets/images/quests/placeholder.png]],desc=[[Zankaja is young and beautiful. To be chained to an invalid... I will not allow her to suffer that injustice. Leave me, $n. And thank you. I may end my life in glorious battle, instead of a lifeless husk. And please, I would ask you not to tell my mate of this... I do not want guilt on her conscience.]],logDesc=[[Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar.]]}
DB[1513]={id=1513,name=[[The Binding]],name_loc=[[El vínculo]],level=-1,minLevel=20,giver=[[Gan'rul Bloodeye]],giver_loc=[[Gan'rul Ojosangre]],giverType=[[NPC]],giverId=5875,ender=[[Gan'rul Bloodeye]],ender_loc=[[Gan'rul Ojosangre]],enderType=[[NPC]],enderId=5875,prevId=1512,poiX=1806,poiY=-4374,wowhead=[[https://www.wowhead.com/wotlk/quest=1513]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this to the summoning circle in Neeru's tent, $n. Summon forth a foul succubus, then show it your mastery. I believe in the strength of your magic. As always, though, be wary, for pride and overconfidence has overcome many a promising warlock. When you have defeated it, return the pendant to me so that I might deliver the news to Zankaja.]],logDesc=[[Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar.]],rewards={{id=22243,qty=1}}}
DB[1514]={id=1514,zoneId=361,name=[[Corrupted Windblossom]],name_loc=[[Flor del viento corrupta]],level=55,minLevel=48,giver=[[Corrupted Windblossom]],giver_loc=[[Flor del viento corrupta]],giverType=[[GO]],giverId=174599,ender=[[Corrupted Windblossom]],ender_loc=[[Flor del viento corrupta]],enderType=[[GO]],enderId=174599,poiX=6233,poiY=-1533,wowhead=[[https://www.wowhead.com/wotlk/quest=1514]],image=[[assets/images/quests/placeholder.png]]}
DB[1515]={id=1515,name=[[Dogran's Captivity]],name_loc=[[El cautiverio de Dogran]],level=-1,minLevel=20,giver=[[Grunt Logmar]],giver_loc=[[Bruto Logmar]],giverType=[[NPC]],giverId=5911,ender=[[Grunt Dogran]],ender_loc=[[Bruto Dogran]],enderType=[[NPC]],enderId=5908,prevId=1511,rewardNextId=1512,poiX=-1623,poiY=-1765,wowhead=[[https://www.wowhead.com/wotlk/quest=1515]],image=[[assets/images/quests/placeholder.png]],desc=[[You've made it this far, so if you want to see this through to the end, I won't stop you. I can't spare you any additional manpower though, you'll be on your own. Dogran is being held in a quilboar camp to the north of here. Look for a group of two huts. He'll be heavily guarded--that is, if they haven't killed him yet, or he hasn't succumbed to his wounds. Good luck.]],logDesc=[[Bring Ken'zigla's Draught to Dogran in the Barrens.]]}
DB[1516]={id=1516,name=[[Call of Earth]],name_loc=[[La llamada de la tierra]],level=4,minLevel=4,giver=[[Canaga Earthcaller]],giver_loc=[[Canaga Clamatierra]],giverType=[[NPC]],giverId=5887,ender=[[Canaga Earthcaller]],ender_loc=[[Canaga Clamatierra]],enderType=[[NPC]],enderId=5887,rewardNextId=1517,exGroup=1516,poiX=-139,poiY=-4370,wowhead=[[https://www.wowhead.com/wotlk/quest=1516]],image=[[assets/images/quests/placeholder.png]],desc=[[The time is now, young $c. You've grown strong and your spirit endures like the earth. Following the shaman's path shows you have wisdom before even proving yourself. The element of earth will guide your destiny, becoming part of you if you are ready. But you must stand before the earth itself. If you are ready, then you will see things only shaman know of. Seek out the Felstalkers to the north, and take from them two of their hooves. Return to me then, and we shall speak more of your future. ]],logDesc=[[Bring 2 Felstalker Hooves to Canaga Earthcaller in the Valley of Trials.]]}
DB[1517]={id=1517,name=[[Call of Earth]],name_loc=[[La llamada de la tierra]],level=4,minLevel=4,giver=[[Canaga Earthcaller]],giver_loc=[[Canaga Clamatierra]],giverType=[[NPC]],giverId=5887,ender=[[Minor Manifestation of Earth]],ender_loc=[[Manifestación de tierra menor]],enderType=[[NPC]],enderId=5891,prevId=1516,rewardNextId=1518,poiX=-878,poiY=-4290,wowhead=[[https://www.wowhead.com/wotlk/quest=1517]],image=[[assets/images/quests/placeholder.png]],desc=[[A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe. The sapta is always drunk in a holy place, and never anywhere else--remember that. Seek out Spirit Rock southwest of here--it is found at the end of the Hidden Path. Drink your sapta there, and... well, you shall see.]],logDesc=[[Find Spirit Rock and drink the Earth Sapta.]]}
DB[1518]={id=1518,name=[[Call of Earth]],name_loc=[[La llamada de la tierra]],level=4,minLevel=4,giver=[[Minor Manifestation of Earth]],giver_loc=[[Manifestación de tierra menor]],giverType=[[NPC]],giverId=5891,ender=[[Canaga Earthcaller]],ender_loc=[[Canaga Clamatierra]],enderType=[[NPC]],enderId=5887,prevId=1517,poiX=-630,poiY=-4205,wowhead=[[https://www.wowhead.com/wotlk/quest=1518]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this rough quartz from me and bring it to Canaga Earthcaller as proof of our meeting. He will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others. Be patient, $N. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.]],logDesc=[[Bring the Rough Quartz to Canaga Earthcaller in the Valley of Trials.]],rewards={{id=5175,qty=1}}}
DB[1519]={id=1519,name=[[Call of Earth]],name_loc=[[La llamada de la tierra]],level=4,minLevel=4,giver=[[Seer Ravenfeather]],giver_loc=[[Vidente Pluma de Cuervo]],giverType=[[NPC]],giverId=5888,ender=[[Seer Ravenfeather]],ender_loc=[[Vidente Pluma de Cuervo]],enderType=[[NPC]],enderId=5888,rewardNextId=1520,exGroup=1516,poiX=-2938,poiY=-1347,wowhead=[[https://www.wowhead.com/wotlk/quest=1519]],image=[[assets/images/quests/placeholder.png]],desc=[[The time has come, young $c. Your body ages and grows strong, and your spirit endures like the earth. I see it within you-you have wisdom already. The earth guides our people, and it speaks to us, as it will to you in time. But you must be tested. If you are ready, then you shall see things only our kind know of. Seek out the Bristleback shamans in their ravine to the east, and take from them a salve they use in their rituals. Return to me only when you have enough for your own potion.]],logDesc=[[Bring 2 applications of Ritual Salve to Seer Ravenfeather in Camp Narache.]]}
DB[1520]={id=1520,name=[[Call of Earth]],name_loc=[[La llamada de la tierra]],level=4,minLevel=4,giver=[[Seer Ravenfeather]],giver_loc=[[Vidente Pluma de Cuervo]],giverType=[[NPC]],giverId=5888,ender=[[Minor Manifestation of Earth]],ender_loc=[[Manifestación de tierra menor]],enderType=[[NPC]],enderId=5891,prevId=1519,rewardNextId=1521,poiX=-3032,poiY=-718,wowhead=[[https://www.wowhead.com/wotlk/quest=1520]],image=[[assets/images/quests/placeholder.png]],desc=[[A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the open minded to see the elements as no one has seen them before. Your spirit will forever be tied to the element the sapta was created for, and only a select few of our kind know the secrets of its creation. The sapta is always imbibed in a holy place, and never anywhere else. Seek out the shaman shrine to the east of here and drink of the sapta.]],logDesc=[[Find Kodo Rock and drink the Earth Sapta.]]}
DB[1521]={id=1521,name=[[Call of Earth]],name_loc=[[La llamada de la tierra]],level=4,minLevel=4,giver=[[Minor Manifestation of Earth]],giver_loc=[[Manifestación de tierra menor]],giverType=[[NPC]],giverId=5891,ender=[[Seer Ravenfeather]],ender_loc=[[Vidente Pluma de Cuervo]],enderType=[[NPC]],enderId=5888,prevId=1520,poiX=-2882,poiY=-250,wowhead=[[https://www.wowhead.com/wotlk/quest=1521]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this rough quartz from me and bring it to Seer Ravenfeather as proof of our meeting. She will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast mountains. Be patient, $N. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.]],logDesc=[[Bring the Rough Quartz to Seer Ravenfeather in Camp Narache.]],rewards={{id=5175,qty=1}}}
DB[1522]={id=1522,name=[[Call of Fire]],name_loc=[[La llamada del fuego]],level=-1,minLevel=10,giver=[[Searn Firewarder]],giver_loc=[[Searn Guardafogo]],giverType=[[NPC]],giverId=5892,ender=[[Kranal Fiss]],enderType=[[NPC]],enderId=5907,rewardNextId=1524,exGroup=1522,poiX=265,poiY=-3037,wowhead=[[https://www.wowhead.com/wotlk/quest=1522]],image=[[assets/images/quests/placeholder.png]],desc=[[Fire be witcha, mon. I see you be strong in da ways of earth already, an' me tinkin' you be ready to talk to Kranal. Kranal live north of da Crossroads in da Barrens. He be strong in da ways of da elements and can teach ya da ways of fire... if you tink you be ready. He be easy ta find, just don' go too far--ya go too far an' ya find yerself in da elves' lands.]],logDesc=[[Find Kranal Fiss in the Barrens.]]}
DB[1523]={id=1523,name=[[Call of Fire]],name_loc=[[La llamada del fuego]],level=-1,minLevel=10,giver=[[Beram Skychaser]],giver_loc=[[Beram Cazacielo]],giverType=[[NPC]],giverId=3032,ender=[[Kranal Fiss]],enderType=[[NPC]],enderId=5907,rewardNextId=1524,exGroup=1522,poiX=265,poiY=-3037,wowhead=[[https://www.wowhead.com/wotlk/quest=1523]],image=[[assets/images/quests/placeholder.png]],desc=[[Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it. Seek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.]],logDesc=[[Find Kranal Fiss in the Barrens.]]}
DB[1524]={id=1524,name=[[Call of Fire]],name_loc=[[La llamada del fuego]],level=-1,minLevel=10,giver=[[Kranal Fiss]],giverType=[[NPC]],giverId=5907,ender=[[Telf Joolam]],enderType=[[NPC]],enderId=5900,rewardNextId=1525,poiX=-270,poiY=-4001,wowhead=[[https://www.wowhead.com/wotlk/quest=1524]],image=[[assets/images/quests/placeholder.png]],desc=[[You are powerful enough to wield the totem of fire, but that does not mean you are ready. Along the Southfury River in Durotar, before the Great Sea, lies a hidden trail to one of the highest peaks in the land. Find your way to the top and you shall find one of our holy shrines watched over by Telf Joolam--the Shrine of the Dormant Flame. Take this torch to him--it marks that you attempt to tame fire. Return it to me aflame by the brazier at the shrine and I will see you are given the totem of fire.]],logDesc=[[Bring the Torch of the Dormant Flame to Telf Joolam in Durotar.]]}
DB[1525]={id=1525,name=[[Call of Fire]],name_loc=[[La llamada del fuego]],level=-1,minLevel=10,giver=[[Telf Joolam]],giverType=[[NPC]],giverId=5900,ender=[[Telf Joolam]],enderType=[[NPC]],enderId=5900,prevId=1524,rewardNextId=1526,poiX=-165,poiY=-3038,wowhead=[[https://www.wowhead.com/wotlk/quest=1525]],image=[[assets/images/quests/placeholder.png]],desc=[[But you did not come here for a history lesson, did you? You came for the Eternal Flame and fire totem. The first step is to create a sapta and bind you to the flame. I can create the fire sapta for you if you bring me two items. The first is fire tar, a simple item usually carried by Razormane spellcasters in eastern Barrens. The second item will be more dangerous: a reagent pouch from one of the cultists of the Burning Blade. You can find them in a cave above the ravines northeast of Razor Hill.]],logDesc=[[Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar.]],rewards={{id=6636,qty=1}}}
DB[1526]={id=1526,name=[[Call of Fire]],name_loc=[[La llamada del fuego]],level=-1,minLevel=10,giver=[[Telf Joolam]],giverType=[[NPC]],giverId=5900,ender=[[Brazier of the Dormant Flame]],ender_loc=[[Blandón de la Llama Latente]],enderType=[[GO]],enderId=61934,prevId=1525,rewardNextId=1527,poiX=-244,poiY=-4019,wowhead=[[https://www.wowhead.com/wotlk/quest=1526]],image=[[assets/images/quests/placeholder.png]],desc=[[The fire sapta is finished. The time has come for you to face the flame. Use the sapta at the shrine and head to the top of the mountain to face the manifestation there. He will not attack until you are ready, but he will realize you are able to see him. Strike him down swiftly, $N, for he shall only grow in power the longer you take to slay him. Once he is defeated, place his glowing embers within the brazier and light the torch.]],logDesc=[[Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.]],rewards={{id=6654,qty=1}}}
DB[1527]={id=1527,name=[[Call of Fire]],name_loc=[[La llamada del fuego]],level=-1,minLevel=10,giver=[[Brazier of the Dormant Flame]],giver_loc=[[Blandón de la Llama Latente]],giverType=[[GO]],giverId=61934,ender=[[Kranal Fiss]],enderType=[[NPC]],enderId=5907,prevId=1526,poiX=265,poiY=-3037,wowhead=[[https://www.wowhead.com/wotlk/quest=1527]],image=[[assets/images/quests/placeholder.png]],desc=[[Torch firmly in hand, you turn away from the brazier and look out over Durotar. You feel an excitement tugging at your spirit as the wind picks up and forces the flame to dance violently. You start off down the path back to the Barrens in search of Kranal Fiss.]],logDesc=[[Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens.]],rewards={{id=5176,qty=1}}}
DB[1528]={id=1528,name=[[Call of Water]],name_loc=[[La llamada del agua]],level=-1,minLevel=20,giver=[[Searn Firewarder]],giver_loc=[[Searn Guardafogo]],giverType=[[NPC]],giverId=5892,ender=[[Islen Waterseer]],ender_loc=[[Islen Vidente del Agua]],enderType=[[NPC]],enderId=5901,rewardNextId=1530,exGroup=1528,poiX=-1345,poiY=-4048,wowhead=[[https://www.wowhead.com/wotlk/quest=1528]],image=[[assets/images/quests/placeholder.png]],desc=[[Water be in ya future, mon. I see you be strong in da ways of fire already, an' me tinkin' you be ready to talk to Islen. Islen live along the coast of da Barrens. If ya head south along the Southfury River, ya canna miss her--look fer da big shark! She be strong in da ways of da elements and can teach ya da ways of water... if you tink you be ready. She be easy ta find, just don' go too far south--she be jus' beyond Ratchet.]],logDesc=[[Find Islen Waterseer in the Barrens.]]}
DB[1529]={id=1529,name=[[Call of Water]],name_loc=[[La llamada del agua]],level=-1,minLevel=20,giver=[[Xanis Flameweaver]],giver_loc=[[Xanis Tejedor de Fuego]],giverType=[[NPC]],giverId=5906,ender=[[Islen Waterseer]],ender_loc=[[Islen Vidente del Agua]],enderType=[[NPC]],enderId=5901,rewardNextId=1530,exGroup=1528,poiX=-1345,poiY=-4048,wowhead=[[https://www.wowhead.com/wotlk/quest=1529]],image=[[assets/images/quests/placeholder.png]],desc=[[Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water. Seek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, $N.]],logDesc=[[Find Islen Waterseer in the Barrens.]]}
DB[1530]={id=1530,name=[[Call of Water]],name_loc=[[La llamada del agua]],level=-1,minLevel=20,giver=[[Islen Waterseer]],giver_loc=[[Islen Vidente del Agua]],giverType=[[NPC]],giverId=5901,ender=[[Brine]],ender_loc=[[Salmuera]],enderType=[[NPC]],enderId=5899,rewardNextId=1535,poiX=-3618,poiY=-1777,wowhead=[[https://www.wowhead.com/wotlk/quest=1530]],image=[[assets/images/quests/placeholder.png]],desc=[[If there is one lesson you must learn of water, it is this: water means rebirth. Its power flows, erodes, and makes clean all manner of things. You will find its ability to heal and replenish incomparable, but only when it is pure. When you understand that water, when polluted, can devastate all that it touches, you will appreciate how vital a resource it is. If you wish the water sapta, find Brine deep in Southern Barrens. Her home is continually molested by the quilboar there.]],logDesc=[[Find Brine at Blackthorn Ridge in Southern Barrens.]]}
DB[1531]={id=1531,name=[[Call of Air]],name_loc=[[La llamada del aire]],level=-1,minLevel=30,giver=[[Searn Firewarder]],giver_loc=[[Searn Guardafogo]],giverType=[[NPC]],giverId=5892,ender=[[Prate Cloudseer]],ender_loc=[[Prate Vidente de las Nubes]],enderType=[[NPC]],enderId=5905,exGroup=1531,poiX=-5218,poiY=-2789,wowhead=[[https://www.wowhead.com/wotlk/quest=1531]],image=[[assets/images/quests/placeholder.png]],desc=[[You be makin' headway now, mon. Your be ready to prove yerself worthy of the air totem, but first, ya must fin' Prate Cloudseer in Thousand Needles. She be willin' ta tell ya how to get yer air totem if ya treat her wit enough respect. Head south through the Barrens, and after ya reach Thousand Needles, head east. You'll find her hiddin' in a hole wit' her boyfriend--haha, don' tell her I be dissin' her none--she not take it too kindly.]],logDesc=[[Find Prate Cloudseer in Thousand Needles.]],rewards={{id=5178,qty=1}}}
DB[1532]={id=1532,name=[[Call of Air]],name_loc=[[La llamada del aire]],level=-1,minLevel=30,giver=[[Xanis Flameweaver]],giver_loc=[[Xanis Tejedor de Fuego]],giverType=[[NPC]],giverId=5906,ender=[[Prate Cloudseer]],ender_loc=[[Prate Vidente de las Nubes]],enderType=[[NPC]],enderId=5905,exGroup=1531,poiX=-5218,poiY=-2789,wowhead=[[https://www.wowhead.com/wotlk/quest=1532]],image=[[assets/images/quests/placeholder.png]],desc=[[The winds of Kalimdor rush to meet you and you shall be counted among some of our most powerful $g brothers:sisters;. I am proud to see you have come this far and have such a promising future. The element of air is a difficult one to control, but I have faith that your skills will overcome any obstacles that are placed in front of you. Head to the very south of the Barrens, and enter Thousand Needles. It is there, far to the east, that you will find Prate Cloudseer. She will teach you more.]],logDesc=[[Find Prate Cloudseer in Thousand Needles.]],rewards={{id=5178,qty=1}}}
DB[1534]={id=1534,name=[[Call of Water]],name_loc=[[La llamada del agua]],level=-1,minLevel=20,giver=[[Brine]],giver_loc=[[Salmuera]],giverType=[[NPC]],giverId=5899,ender=[[Brine]],ender_loc=[[Salmuera]],enderType=[[NPC]],enderId=5899,prevId=1536,rewardNextId=220,poiX=-3618,poiY=-1777,wowhead=[[https://www.wowhead.com/wotlk/quest=1534]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this waterskin and head deep into the lush forest the night elves call Ashenvale. It is to the far north of the Barrens. Once you've entered the forest, travel west. Along the mountains that separate Stonetalon and Ashenvale, and beyond Lake Mystral, you will find a holy place: the Ruins of Stardust. At the center of the lake you will find a small fountain. Bring me a sample of the fountain's water. It will be the final component you'll need before I send you back to Islen.]],logDesc=[[Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens.]]}
DB[1535]={id=1535,name=[[Call of Water]],name_loc=[[La llamada del agua]],level=-1,minLevel=20,giver=[[Brine]],giver_loc=[[Salmuera]],giverType=[[NPC]],giverId=5899,ender=[[Brine]],ender_loc=[[Salmuera]],enderType=[[NPC]],enderId=5899,prevId=1530,rewardNextId=1536,poiX=-3618,poiY=-1777,wowhead=[[https://www.wowhead.com/wotlk/quest=1535]],image=[[assets/images/quests/placeholder.png]],desc=[[To find understanding and gain the sapta from me, you must seek out only the purest forms of water. As you fetch the samples for me, take note of your surroundings. Be aware of the creatures that rely on the water, that protect it. See how it affects forests and deserts. Witness how the very substance that sustains life will force creatures to take lives. We shall start with a simple task: down below my hut there is a pond of the precious liquid. Fill this skin with it and return to me.]],logDesc=[[Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens.]]}
DB[1536]={id=1536,name=[[Call of Water]],name_loc=[[La llamada del agua]],level=-1,minLevel=20,giver=[[Brine]],giver_loc=[[Salmuera]],giverType=[[NPC]],giverId=5899,ender=[[Brine]],ender_loc=[[Salmuera]],enderType=[[NPC]],enderId=5899,prevId=1535,rewardNextId=1534,poiX=-3618,poiY=-1777,wowhead=[[https://www.wowhead.com/wotlk/quest=1536]],image=[[assets/images/quests/placeholder.png]],desc=[[Long ago I followed some companions into the Hillsbrad Foothills. We defended ourselves from some tenacious humans who make their home there and we found ourselves in a small town the Forsaken had taken over: Tarren Mill. It was there I found a most peculiar thing: in the center of town was a small well of fresh spring water. I'm not sure the plagued citizens of the town even realize its value--it's a small holy vestige in an unhallowed sea. Bring me a sample of that water in this waterskin.]],logDesc=[[Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens.]]}
DB[1558]={id=1558,name=[[The Stonewrought Dam]],name_loc=[[Presa de las Tres Cabezas]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Human Orphan]],ender_loc=[[Huérfano humano]],enderType=[[NPC]],enderId=14305,prevId=1468,exGroup=-1479,poiX=-4746,poiY=-3313,wowhead=[[https://www.wowhead.com/wotlk/quest=1558]],image=[[assets/images/quests/placeholder.png]],desc=[[Ironforge is where all the dwarves and gnomes live.  Near there is a place called Loch Modan, and the dwarves built a HUGE dam there.  They say it's one of the biggest things anyone's ever made.  Wow! Could you take me to Loch Modan and see the dam there, please?  I think it is the Stone... um... Stonewrench Dam?  Stonewrought?  It's big - that's for sure.  I'd like to look out over the big waterfall.  I promise I won't lean over too far!]],logDesc=[[Take the orphan to the Stonewrought Dam in Loch Modan.  You should take him to the middle of the dam so he can see out over the giant waterfall.]]}
DB[1559]={id=1559,name=[[Flash Bomb Recipe]],name_loc=[[Receta de bomba cegadora]],level=37,minLevel=30,giver=[[Rigglefuzz]],giver_loc=[[Aparejez]],giverType=[[NPC]],giverId=2817,ender=[[Rigglefuzz]],ender_loc=[[Aparejez]],enderType=[[NPC]],enderId=2817,prevId=705,poiX=-6767,poiY=-3134,wowhead=[[https://www.wowhead.com/wotlk/quest=1559]],image=[[assets/images/quests/placeholder.png]],rewards={{id=6672,qty=1}}}
DB[1560]={id=1560,zoneId=440,name=[[Tooga's Quest]],name_loc=[[La misión de Tooga]],level=50,minLevel=40,giver=[[Tooga]],giverType=[[NPC]],giverId=5955,ender=[[Torta]],ender_loc=[[Thorta]],enderType=[[NPC]],enderId=6015,poiX=-7054,poiY=-4813,wowhead=[[https://www.wowhead.com/wotlk/quest=1560]],image=[[assets/images/quests/placeholder.png]],desc=[[I am so lost! My wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere. Would you be so kind as to lead me back to Torta? She's waiting for me just south of Steamwheedle Port.]],logDesc=[[Show Tooga the way back to his wife, Torta.]],choiceRewards={{id=9638,qty=1},{id=9642,qty=1}}}
DB[1578]={id=1578,name=[[Supplying the Front]],name_loc=[[Abastecer al frente]],level=12,minLevel=1,giver=[[Tormus Deepforge]],giver_loc=[[Tormus Forjahonda]],giverType=[[NPC]],giverId=6031,ender=[[Thorvald Deepforge]],ender_loc=[[Thorvald Forjahonda]],enderType=[[NPC]],enderId=6030,poiX=-5855,poiY=-2647,wowhead=[[https://www.wowhead.com/wotlk/quest=1578]],image=[[assets/images/quests/placeholder.png]],desc=[[The mountaineers of Loch Modan are fighting troggs, and having a busy time of it!  They need constant supplies of new armor and weapons if we're ever to get a handle on those troggs. That's why my colleague Thorvald is there, trying to keep the mountaineers in good gear.  So if you were to make some copper axes and copper chain belts and bring them to Thorvald, he would be obliged.  He might even share his knowledge with you. Thorvald is in Loch Modan's southern guard tower.]],logDesc=[[Bring 6 Copper Axes and 6 Copper Chain Belts to Thorvald in the southern guard tower of Loch Modan.]],rewards={{id=33792,qty=1},{id=3609,qty=1}}}
DB[1579]={id=1579,name=[[Gaffer Jacks]],name_loc=[[Mecanismos eléctricos]],level=12,minLevel=10,giver=[[Wizbang Cranktoggle]],giver_loc=[[Maniveo Zumbang]],giverType=[[NPC]],giverId=3666,ender=[[Wizbang Cranktoggle]],ender_loc=[[Maniveo Zumbang]],enderType=[[NPC]],enderId=3666,rewardNextId=1580,poiX=6406,poiY=520,wowhead=[[https://www.wowhead.com/wotlk/quest=1579]],image=[[assets/images/quests/placeholder.png]],desc=[[I came to Auberdine because of the quiet.  I want to invent my inventions where it's quiet, because after a night of drinking I don't like all the noise of Ironforge! So I took a ship to Auberdine and had a little too much to drink on the way.  I dropped my box of gaffer jacks overboard!  I need my gaffer jacks! I don't know exactly where I dropped them, but if you fish for them in the ocean you might get lucky...]],logDesc=[[Bring 8 Gaffer Jacks to Wizbang Cranktoggle in Auberdine.]]}
DB[1580]={id=1580,name=[[Electropellers]],name_loc=[[Los electromuelles]],level=12,minLevel=10,giver=[[Wizbang Cranktoggle]],giver_loc=[[Maniveo Zumbang]],giverType=[[NPC]],giverId=3666,ender=[[Wizbang Cranktoggle]],ender_loc=[[Maniveo Zumbang]],enderType=[[NPC]],enderId=3666,prevId=1579,poiX=6406,poiY=520,wowhead=[[https://www.wowhead.com/wotlk/quest=1580]],image=[[assets/images/quests/placeholder.png]],desc=[[We know you're lucky, but... just how lucky are you, $N? One night I was wandering the roads of Darkshore.  I was looking for a good river or lake to try my new self-propelled, exploding duck decoy and I think I was a little tipsy... because I passed out and awoke hours later in Auberdine.  My hair was singed and my bag of electropellers was gone!  I must have dropped them in the water! I need those electropellers!  Maybe you can fish them out of some lake or stream in Darkshore...]],logDesc=[[Bring 12 Electropellers to Wizbang Cranktoggle in Auberdine.]],rewards={{id=6811,qty=20}}}
DB[1581]={id=1581,name=[[Elixirs for the Bladeleafs]],name_loc=[[Elixires para Filohoja]],level=8,minLevel=4,giver=[[Syral Bladeleaf]],giver_loc=[[Syral Filohoja]],giverType=[[NPC]],giverId=2083,ender=[[Syral Bladeleaf]],ender_loc=[[Syral Filohoja]],enderType=[[NPC]],enderId=2083,poiX=9872,poiY=959,wowhead=[[https://www.wowhead.com/wotlk/quest=1581]],image=[[assets/images/quests/placeholder.png]],desc=[[Our herb and alchemy shop is booming, but my husband spends so much time mixing potions that we never have time for each other. Can you help us? If you can bring me a supply of pre-made elixirs, then I would be happy to trade with you.  I have some rare herbs that you might find useful.]],logDesc=[[Bring 6 Elixirs of Lion's Strength and 2 Elixirs of Minor Defense to Syral Bladeleaf in Dolanaar.]],rewards={{id=2449,qty=6},{id=785,qty=6}}}
DB[1582]={id=1582,name=[[Moonglow Vest]],name_loc=[[El jubón resplandor lunar]],level=18,minLevel=8,giver=[[Lotherias]],giverType=[[NPC]],giverId=6034,ender=[[Lotherias]],enderType=[[NPC]],enderId=6034,poiX=10081,poiY=2257,wowhead=[[https://www.wowhead.com/wotlk/quest=1582]],image=[[assets/images/quests/placeholder.png]],desc=[[We in Darnassus, especially we craftsman, are quite busy.  Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies. If you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique.]],logDesc=[[Bring 1 Embossed Leather Gloves, 5 Embossed Leather Boots and 5 Embossed Leather Cloaks to Lotherias in Darnassus.]],rewards={{id=6710,qty=1}}}
DB[1598]={id=1598,name=[[The Stolen Tome]],name_loc=[[El libro robado]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-8957,poiY=-433,wowhead=[[https://www.wowhead.com/wotlk/quest=1598]],image=[[assets/images/quests/placeholder.png]],desc=[[You there! $n, right? I hope you're sure about becoming a warlock, because if you can't hold your own, you're likely to get pulled under. I'm to teach you, but I need to make sure you're strong enough first. There was a novice studying at the Abbey who ran off to join the Defias Brotherhood. Why do I care? Well, he stole some important books. One of those happens to be a book I've wanted for myself, the Powers of the Void. Steal it for me, they have it hidden at their tent in the Vineyards.]],logDesc=[[Retrieve the Powers of the Void for Drusilla La Salle.]]}
DB[1599]={id=1599,name=[[Beginnings]],name_loc=[[Novato]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-6491,poiY=298,wowhead=[[https://www.wowhead.com/wotlk/quest=1599]],image=[[assets/images/quests/placeholder.png]],desc=[[You must be the new warlock everyone's been whispering about. Must be someone's taken a liking to you if they've asked me to take time away from my research to start your training. Don't worry, I won't hold it against you. The simplest of the summoning spells you will learn is that of the imp. Before I impart this to you, however, you must prove that you have the necessary magical and physical ability. Bring me three feather charms from the frostmane novices from the cave to the southwest.]],logDesc=[[Bring 3 Feather Charms to Alamar Grimm in Anvilmar.]]}
DB[1618]={id=1618,name=[[Gearing Redridge]],name_loc=[[Equipar Crestagrana]],level=16,minLevel=1,giver=[[Tormus Deepforge]],giver_loc=[[Tormus Forjahonda]],giverType=[[NPC]],giverId=6031,ender=[[Verner Osgood]],ender_loc=[[Verner Osbien]],enderType=[[NPC]],enderId=415,poiX=-9259,poiY=-2243,wowhead=[[https://www.wowhead.com/wotlk/quest=1618]],image=[[assets/images/quests/placeholder.png]],desc=[[We dwarves aren't the only ones fighting.  Our human allies have their hands full too! Redridge is under periodic attack from blackrock orcs, and their supply of equipment is always low.  If you were to help them out, I'm sure their resident blacksmith, Verner Osgood, would teach you a trick or two.]],logDesc=[[Tormus Deepforge wants you to bring 4 Runed Copper Belts and 4 Heavy Copper Mauls to Verner Osgood in Redridge.]],rewards={{id=6735,qty=1}}}
DB[1638]={id=1638,name=[[A Warrior's Training]],name_loc=[[Instrucción de guerrero]],level=-1,minLevel=10,giver=[[Lyria Du Lac]],giver_loc=[[Lyria Du Lac]],giverType=[[NPC]],giverId=913,ender=[[Harry Burlguard]],enderType=[[NPC]],enderId=6089,rewardNextId=1639,exGroup=1638,poiX=-8613,poiY=383,wowhead=[[https://www.wowhead.com/wotlk/quest=1638]],image=[[assets/images/quests/placeholder.png]],desc=[[You've shown yourself to be a competent warrior, $N.  But you're still young and have a lot to learn. Speak with Harry Burlguard--he's usually in the Pig and Whistle tavern, in the Old Town of Stormwind.  Harry is an old veteran and a good teacher.  He can show you a few moves that'll keep you breathing longer.]],logDesc=[[Speak with Harry Burlguard in Stormwind.]]}
DB[1638]={id=1638,name=[[A Warrior's Training]],name_loc=[[Instrucción de guerrero]],level=-1,minLevel=10,giver=[[Ilsa Corbin]],giver_loc=[[Lyria Du Lac]],giverType=[[NPC]],giverId=5480,ender=[[Harry Burlguard]],enderType=[[NPC]],enderId=6089,rewardNextId=1639,exGroup=1638,poiX=-8613,poiY=383,wowhead=[[https://www.wowhead.com/wotlk/quest=1638]],image=[[assets/images/quests/placeholder.png]],desc=[[You've shown yourself to be a competent warrior, $N.  But you're still young and have a lot to learn. Speak with Harry Burlguard--he's usually in the Pig and Whistle tavern, in the Old Town of Stormwind.  Harry is an old veteran and a good teacher.  He can show you a few moves that'll keep you breathing longer.]],logDesc=[[Speak with Harry Burlguard in Stormwind.]]}
DB[1639]={id=1639,name=[[Bartleby the Drunk]],name_loc=[[Bartleby, el borracho]],level=-1,minLevel=10,giver=[[Harry Burlguard]],giverType=[[NPC]],giverId=6089,ender=[[Bartleby]],ender_loc=[[Bartleby]],enderType=[[NPC]],enderId=6090,prevId=1638,rewardNextId=1640,poiX=-8604,poiY=389,wowhead=[[https://www.wowhead.com/wotlk/quest=1639]],image=[[assets/images/quests/placeholder.png]],desc=[[Yeah, I can teach you.  But first I wanna see what moves you have already. See that drunk over there at the end of the bar?  Bartleby?  I want you to get his mug. Hah, and if you know Bartleby then you know he won't just give it to you.]],logDesc=[[Speak with Bartleby.]]}
DB[1640]={id=1640,name=[[Beat Bartleby]],name_loc=[[Vence a Bartleby]],level=-1,minLevel=10,giver=[[Bartleby]],giver_loc=[[Bartleby]],giverType=[[NPC]],giverId=6090,ender=[[Bartleby]],ender_loc=[[Bartleby]],enderType=[[NPC]],enderId=6090,prevId=1639,rewardNextId=1665,poiX=-8604,poiY=389,wowhead=[[https://www.wowhead.com/wotlk/quest=1640]],image=[[assets/images/quests/placeholder.png]],desc=[[You want what??  You're crazy! The only way you'll get this mug is if you pry it from my cold, dead fingers...]],logDesc=[[Beat Bartleby, then talk to him.]]}
DB[1641]={id=1641,name=[[The Tome of Divinity]],name_loc=[[El Libro de la Divinidad]],level=-1,minLevel=12,giver=[[Duthorian Rall]],giverType=[[NPC]],giverId=6171,ender=[[Duthorian Rall]],enderType=[[NPC]],enderId=6171,poiX=-8546,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=1641]],image=[[assets/images/quests/placeholder.png]],rewards={{id=6775,qty=1}}}
DB[1642]={id=1642,name=[[The Tome of Divinity]],name_loc=[[El Libro de la Divinidad]],level=-1,minLevel=12,giverType=[[NPC]],ender=[[Duthorian Rall]],enderType=[[NPC]],enderId=6171,nextId=1643,rewardNextId=1643,poiX=-8546,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=1642]],image=[[assets/images/quests/placeholder.png]],desc=[[In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions. Although called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle. Know this well, and never forget it.]],logDesc=[[Speak to Duthorian Rall in Stormwind.]]}
DB[1643]={id=1643,name=[[The Tome of Divinity]],name_loc=[[Escrito sobre divinidad]],level=-1,minLevel=12,giver=[[Duthorian Rall]],giverType=[[NPC]],giverId=6171,ender=[[Stephanie Turner]],enderType=[[NPC]],enderId=6174,rewardNextId=1644,poiX=-8832,poiY=614,wowhead=[[https://www.wowhead.com/wotlk/quest=1643]],image=[[assets/images/quests/placeholder.png]],desc=[[Your task then, $N, is to find someone here in Stormwind that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness. Do this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light.]],logDesc=[[Search the Trade District of Stormwind for Stephanie Turner.]]}
DB[1644]={id=1644,name=[[The Tome of Divinity]],name_loc=[[Escrito sobre divinidad]],level=-1,minLevel=12,giver=[[Stephanie Turner]],giverType=[[NPC]],giverId=6174,ender=[[Stephanie Turner]],enderType=[[NPC]],enderId=6174,prevId=1643,rewardNextId=1780,poiX=-9866,poiY=-223,wowhead=[[https://www.wowhead.com/wotlk/quest=1644]],image=[[assets/images/quests/placeholder.png]],desc=[[Bless their hearts, most of them have no families because of the Scourge attacks in the last decade. My husband John collects the materials for me to make the shirts and pants for the children, but I haven't even had time to do that. I've been too focused on keeping food on their plates, and a roof over their heads. What's that? You'd be willing to help? Oh, thank the Light, and thank you, $N. If you could bring me some linen cloth so I can sew clothes for the kids, that would help me out so much.]],logDesc=[[Bring 10 Linen Cloth to Stephanie Turner in Stormwind.]]}
DB[1645]={id=1645,name=[[The Tome of Divinity]],name_loc=[[El Libro de la Divinidad]],level=-1,minLevel=12,giver=[[Tiza Battleforge]],giver_loc=[[Tiza Forjabatalla]],giverType=[[NPC]],giverId=6179,ender=[[Tiza Battleforge]],ender_loc=[[Tiza Forjabatalla]],enderType=[[NPC]],enderId=6179,poiX=-4634,poiY=-932,wowhead=[[https://www.wowhead.com/wotlk/quest=1645]],image=[[assets/images/quests/placeholder.png]],rewards={{id=6916,qty=1}}}
DB[1646]={id=1646,name=[[The Tome of Divinity]],name_loc=[[Escrito sobre divinidad]],level=-1,minLevel=12,giverType=[[NPC]],ender=[[Tiza Battleforge]],ender_loc=[[Tiza Forjabatalla]],enderType=[[NPC]],enderId=6179,nextId=1647,rewardNextId=1647,poiX=-4634,poiY=-932,wowhead=[[https://www.wowhead.com/wotlk/quest=1646]],image=[[assets/images/quests/placeholder.png]],desc=[[In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions. Although called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle. Know this well, and never forget it.]],logDesc=[[Speak to Tiza Battleforge in Ironforge.]]}
DB[1647]={id=1647,name=[[The Tome of Divinity]],name_loc=[[Escrito sobre divinidad]],level=-1,minLevel=12,giver=[[Tiza Battleforge]],giver_loc=[[Tiza Forjabatalla]],giverType=[[NPC]],giverId=6179,ender=[[John Turner]],enderType=[[NPC]],enderId=6175,rewardNextId=1648,poiX=-4896,poiY=-898,wowhead=[[https://www.wowhead.com/wotlk/quest=1647]],image=[[assets/images/quests/placeholder.png]],desc=[[Your task then, $N, is to find someone here in Ironforge that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness. Do this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light. I will remain here in the temple for your return. Other paladins will need my guidance also.]],logDesc=[[Search the outer ring of Ironforge for John Turner.]]}
DB[1648]={id=1648,name=[[The Tome of Divinity]],name_loc=[[Escrito sobre divinidad]],level=-1,minLevel=12,giver=[[John Turner]],giverType=[[NPC]],giverId=6175,ender=[[John Turner]],enderType=[[NPC]],enderId=6175,prevId=1647,rewardNextId=1778,poiX=-4896,poiY=-898,wowhead=[[https://www.wowhead.com/wotlk/quest=1648]],image=[[assets/images/quests/placeholder.png]],desc=[[My wife and I run an orphanage in Stormwind, mostly for children who have lost parents due to the attacks by the Scourge in the last decade. I come to Ironforge every month or so to see about collecting more supplies from the citizens here, and talk to the various groups to see if they can do anything to help. This trip's been agonizingly slow, and not very productive. If I could just get some more linen for my wife to make some clothes, I could finally send a shipment home.]],logDesc=[[Bring 10 Linen Cloth to John Turner in Ironforge.]]}
DB[1649]={id=1649,name=[[The Tome of Valor]],name_loc=[[Escrito sobre valor]],level=-1,minLevel=20,giverType=[[NPC]],ender=[[Duthorian Rall]],enderType=[[NPC]],enderId=6171,rewardNextId=1650,poiX=-8546,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=1649]],image=[[assets/images/quests/placeholder.png]],desc=[[Valor, and all the virtues that go along with it, are like rare minerals: you must cherish them when you find them because of their value, but you must also take time to harvest them... refine them. When mixed together properly, a strong alloy is formed, sometimes unbreakable by even the most powerful blows. This strength, your faith, your bravery, must be tested. You must learn to never lose faith and realize that with the power of the Light, you can overcome things that most others cannot.]],logDesc=[[Speak to Duthorian Rall in Stormwind.]]}
DB[1650]={id=1650,name=[[The Tome of Valor]],name_loc=[[Escrito sobre valor]],level=-1,minLevel=20,giver=[[Duthorian Rall]],giverType=[[NPC]],giverId=6171,ender=[[Daphne Stilwell]],ender_loc=[[Daphne Fontana]],enderType=[[NPC]],enderId=6182,prevId=1649,poiX=-11471,poiY=1546,wowhead=[[https://www.wowhead.com/wotlk/quest=1650]],image=[[assets/images/quests/placeholder.png]],desc=[[Good! Your lack of hesitation is a sure sign that you are prepared and eager to test yourself. So be it. At the very ends of Westfall's Longshore, a small house overlooks the ocean. There, a couple lives, the Stilwells. Jordan is an incredible smith, and he's gone to Ironforge to meet with the dwarves for a while. But this has left Daphne, his wife, alone and unprotected. Reports suggest that the Defias have all but taken over the area, Daphne may need some protection from the villains. Go there.]],logDesc=[[Find Daphne Stilwell in Westfall.]]}
DB[1651]={id=1651,name=[[The Tome of Valor]],name_loc=[[Escrito sobre valor]],level=-1,minLevel=20,giver=[[Daphne Stilwell]],giver_loc=[[Daphne Fontana]],giverType=[[NPC]],giverId=6182,ender=[[Daphne Stilwell]],ender_loc=[[Daphne Fontana]],enderType=[[NPC]],enderId=6182,prevId=1650,rewardNextId=1652,poiX=-11471,poiY=1510,wowhead=[[https://www.wowhead.com/wotlk/quest=1651]],image=[[assets/images/quests/placeholder.png]],desc=[[Now, they'll be coming again soon, I'd wager, so get yourself ready. I've got myself a gun in the house. I'll grab it and be ready to help you out, but for the most part, you're on your own. I've no idea how many they'll send, but I'm sure it'll be more than the few they sent earlier. Ask the Light for whatever blessings you can because... did you hear that? I think they're coming. We make our stand near the house!]],logDesc=[[Defend Daphne Stilwell from the Defias attack. Neither of your spirits must be released from their mortal coils if you wish to succeed. After you are successful, speak to Daphne Stilwell again.]]}
DB[1652]={id=1652,name=[[The Tome of Valor]],name_loc=[[Escrito sobre valor]],level=-1,minLevel=20,giver=[[Daphne Stilwell]],giver_loc=[[Daphne Fontana]],giverType=[[NPC]],giverId=6182,ender=[[Duthorian Rall]],enderType=[[NPC]],enderId=6171,prevId=1651,rewardNextId=1653,poiX=-8546,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=1652]],image=[[assets/images/quests/placeholder.png]],desc=[[Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that. He'll send word to Ironforge to let my Jordan know that he has nothing to fear. Oh, how I miss my husband. I can't wait till he returns.]],logDesc=[[Speak to Duthorian Rall in Stormwind.]],rewards={{id=9607,qty=1}}}
DB[1653]={id=1653,name=[[The Test of Righteousness]],name_loc=[[La prueba de rectitud]],level=-1,minLevel=20,giver=[[Duthorian Rall]],giverType=[[NPC]],giverId=6171,ender=[[Jordan Stilwell]],ender_loc=[[Jordan Fontana]],enderType=[[NPC]],enderId=6181,prevId=1652,rewardNextId=1654,poiX=-5089,poiY=-783,wowhead=[[https://www.wowhead.com/wotlk/quest=1653]],image=[[assets/images/quests/placeholder.png]],desc=[[Actually, I have no doubt that Jordan himself would like to thank you, and seeing as I need a messenger to send word that his wife is safe, I think you'd be a perfect choice. Jordan was to be a paladin of the Light before his dedication to his father's craft took him on another path--he's intimately familiar with our way of life and is considered among our most faithful. He should still be in Ironforge--he likes to work outside the gates during the day, something about the cool mountain air.]],logDesc=[[Speak to Jordan Stilwell in Ironforge]]}
DB[1654]={id=1654,name=[[The Test of Righteousness]],name_loc=[[La prueba de rectitud]],level=22,minLevel=20,giver=[[Jordan Stilwell]],giver_loc=[[Jordan Fontana]],giverType=[[NPC]],giverId=6181,ender=[[Jordan Stilwell]],ender_loc=[[Jordan Fontana]],enderType=[[NPC]],enderId=6181,prevId=1653,rewardNextId=1806,poiX=-5089,poiY=-783,wowhead=[[https://www.wowhead.com/wotlk/quest=1654]],image=[[assets/images/quests/placeholder.png]],desc=[[I'd like to reward you if you'd be willing to accept such a thing? Don't misunderstand me, my generosity is dependent on how much help you can be, but I see us both benefiting greatly from such an alliance. I will craft for you a weapon worthy of what you've accomplished, a symbol of paladinhood and the Light, but you must gather the items I need to craft it. I've already started taking notes on the items, it just requires someone brave and skilled enough to recover them. What do you say, $c?]],logDesc=[[Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge.]]}
DB[1655]={id=1655,name=[[Bailor's Ore Shipment]],name_loc=[[Envío de mena de Bailor]],level=22,minLevel=20,giver=[[Bailor Stonehand]],giver_loc=[[Bailor Petramano]],giverType=[[NPC]],giverId=6241,ender=[[Bailor Stonehand]],ender_loc=[[Bailor Petramano]],enderType=[[NPC]],enderId=6241,prevId=1653,poiX=-4885,poiY=-3969,wowhead=[[https://www.wowhead.com/wotlk/quest=1655]],image=[[assets/images/quests/placeholder.png]],desc=[[Ach, ya startled me, $G man:woman;! Can't ya see I was lost in thought? What's that? Jordan's shipment... fer Ironforge. Ahhh, yeah, I know whatcha speak of. Mo'grosh ogres... dat's who took me ol' friend's ore shipment. Caravan was headin' here from the Wetlands and was ambushed. The guard who survived their attack just passed away a few days ago--healer couldn't get to 'em fast enough. If you want the shipment, you'll have to head northeast across the Loch. It's got to be there somewhere.]],logDesc=[[Bring Jordan's Ore Shipment to Bailor Stonehand in Loch Modan.]],rewards={{id=6993,qty=1}}}
DB[1656]={id=1656,zoneId=220,name=[[A Task Unfinished]],name_loc=[[Una tarea por terminar]],level=5,minLevel=1,giver=[[Antur Fallow]],giver_loc=[[Antur Barbecho]],giverType=[[NPC]],giverId=6775,ender=[[Innkeeper Kauth]],ender_loc=[[Tabernero Kauth]],enderType=[[NPC]],enderId=6747,poiX=-2365,poiY=-347,wowhead=[[https://www.wowhead.com/wotlk/quest=1656]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, please, I beg of you, can you help me? I have not finished my tasks here on the Mesa--I'm in the middle of my Rite of Strength--and my father asked me to deliver these furs to the inn in Bloodhoof. I'm far from rested enough to complete both my rite and this task for my father. Would you mind going on for me? The inn is pleasant and a perfect place to rest during your long travels. I'm sure you'll agree once you see it.]],logDesc=[[Bring the Bundle of Furs to Innkeeper Kauth in Bloodhoof Village.]],choiceRewards={{id=4540,qty=5},{id=159,qty=5}}}
DB[1657]={id=1657,name=[[Stinking Up Southshore]],name_loc=[[Apesta Costasur]],level=-1,minLevel=25,giver=[[Darkcaller Yanka]],giver_loc=[[Llamasombra Yanka]],giverType=[[NPC]],giverId=15197,ender=[[Darkcaller Yanka]],ender_loc=[[Llamasombra Yanka]],enderType=[[NPC]],enderId=15197,poiX=-855,poiY=-504,wowhead=[[https://www.wowhead.com/wotlk/quest=1657]],image=[[assets/images/quests/placeholder.png]],desc=[[Celebrate Hallow's End in style... by bringing grief to our enemies in Southshore! Take one of these specially crafted stink bombs.  It is filled with an odiferous funk that no human - or any weak-willed beast for that matter - can stand to smell.  You'll need to throw it right in the heart of Southshore for it to do its job, so be prepared for a fight against the Alliance! When you've completed this task... this tribute to our liberation, return to me!]],logDesc=[[Toss three Forsaken Stink Bombs into the heart of Southshore in Hillsbrad, and return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.]],rewards={{id=20557,qty=15}}}
DB[1658]={id=1658,name=[[Crashing the Wickerman Festival]],name_loc=[[Arruinar el Festival del Hombre de Mimbre]],level=-1,minLevel=25,giver=[[Sergeant Hartman]],giver_loc=[[Sargento Hartman]],giverType=[[NPC]],giverId=15199,ender=[[Sergeant Hartman]],ender_loc=[[Sargento Hartman]],enderType=[[NPC]],enderId=15199,poiX=1733,poiY=479,wowhead=[[https://www.wowhead.com/wotlk/quest=1658]],image=[[assets/images/quests/placeholder.png]],desc=[[I need brave individuals to head up to Tirisfal Glades and check out the Wickerman Festival.  I'm not going to lie - heading up there will be dangerous.  The guards at the festival will be exceptionally vicious.  Still, we need to know how big the festival is this year, and how much trouble the Forsaken are going to cause us during Hallow's End. If you're up for it, head to Tirisfal and scout out the festival.  Return to me with the information, and I'll make sure you're well compensated.]],logDesc=[[Locate the Forsaken's Wickerman Festival in Tirisfal Glades.  Return to Sergeant Hartman in Southshore once you've done so.]],rewards={{id=20557,qty=15}}}
DB[1661]={id=1661,name=[[The Tome of Nobility]],name_loc=[[Escrito sobre nobleza]],level=-1,minLevel=40,giverType=[[NPC]],enderType=[[NPC]],poiX=-8546,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=1661]],image=[[assets/images/quests/placeholder.png]],desc=[[I greet you once again, $N. I am more proud to call you $g brother:sister; than ever before--your dedication is a tribute to us all. The time has come for me to bestow a great gift upon you. But know this, for now I give you this freely, but later, when time permits, this will be a much greater challenge to all paladins who choose to undertake my quest. Speak to me again and I shall grant you a great boon.]],logDesc=[[Speak to Duthorian Rall in Stormwind.]]}
DB[1665]={id=1665,name=[[Bartleby's Mug]],name_loc=[[La jarra de Bartleby]],level=-1,minLevel=10,giver=[[Bartleby]],giver_loc=[[Bartleby]],giverType=[[NPC]],giverId=6090,ender=[[Harry Burlguard]],enderType=[[NPC]],enderId=6089,prevId=1640,poiX=-8613,poiY=383,wowhead=[[https://www.wowhead.com/wotlk/quest=1665]],image=[[assets/images/quests/placeholder.png]],desc=[[Ok, here's my mug.  Wait!  Let me finish what's in it first... there we go.]],logDesc=[[Bring Bartleby's Mug to Burlguard]]}
DB[1666]={id=1666,name=[[Marshal Haggard]],name_loc=[[El mariscal Haggard]],level=10,minLevel=10,giver=[[Harry Burlguard]],giverType=[[NPC]],giverId=6089,ender=[[Marshal Haggard]],ender_loc=[[Mariscal Haggard]],enderType=[[NPC]],enderId=294,prevId=1665,rewardNextId=1667,poiX=-9545,poiY=-1401,wowhead=[[https://www.wowhead.com/wotlk/quest=1666]],image=[[assets/images/quests/placeholder.png]],desc=[[You've learned a few moves, but you could still use a decent weapon.  I bet if you spoke with Marshal Haggard he could help you. Marshal Haggard lives in a manor in Elwynn Forest, at the Eastvale Lumber Camp.  He's retired now but he collected a lot of gear during his career. Let him know I sent you, and with luck he'll have a spare weapon to offer.]],logDesc=[[Speak with Marshal Haggard.]]}
DB[1667]={id=1667,name=[[Dead-tooth Jack]],name_loc=[[Jack Dentomuerto]],level=10,minLevel=10,giver=[[Marshal Haggard]],giver_loc=[[Mariscal Haggard]],giverType=[[NPC]],giverId=294,ender=[[Marshal Haggard]],ender_loc=[[Mariscal Haggard]],enderType=[[NPC]],enderId=294,prevId=1666,poiX=-9765,poiY=-1565,wowhead=[[https://www.wowhead.com/wotlk/quest=1667]],image=[[assets/images/quests/placeholder.png]],desc=[[Burlguard sent you, did he?  Yes, I have spare weapons around here, but first I have a task for you... A while ago a Defias villain Dead-tooth Jack tricked me.  It was dark and he was wearing a Stormwind tabard and I thought he was Marshal Dughan.  He said he needed my old Stormwind Marshal's badge and I gave it to him... and then he laughed and ran off before I could catch him! Get back my badge!  Dead-tooth Jack probably has it stowed in his camp to the south.]],logDesc=[[Retrieve Haggard's Badge from Dead-tooth Jack's camp, and return to Marshal Haggard.]],choiceRewards={{id=6979,qty=1},{id=6983,qty=1},{id=6980,qty=1},{id=6985,qty=1}}}
DB[1678]={id=1678,name=[[Vejrek]],name_loc=[[Vejrek]],level=-1,minLevel=10,giver=[[Muren Stormpike]],giver_loc=[[Muren Pico Tormenta]],giverType=[[NPC]],giverId=6114,ender=[[Muren Stormpike]],ender_loc=[[Muren Pico Tormenta]],enderType=[[NPC]],enderId=6114,prevId=1679,rewardNextId=1680,poiX=-5775,poiY=437,wowhead=[[https://www.wowhead.com/wotlk/quest=1678]],image=[[assets/images/quests/placeholder.png]],desc=[[If you want to rise in the ranks of the warriors, then you better be tough.  I can teach you new moves but before that, prove to me you can handle yourself against real foes. Vejrek is the toughest troll you'll find in these parts, and he's who you have to beat.  He has a hut in the foothills just south of Frostmane Hold. Bring me Vejrek's head and I'll know you have mettle.]],logDesc=[[Bring Vejrek's Head to Muren Stormpike in Ironforge.]]}
DB[1679]={id=1679,name=[[Muren Stormpike]],name_loc=[[Muren Pico Tormenta]],level=-1,minLevel=10,giver=[[Granis Swiftaxe]],giver_loc=[[Granis Hachaveloz]],giverType=[[NPC]],giverId=1229,ender=[[Muren Stormpike]],ender_loc=[[Muren Pico Tormenta]],enderType=[[NPC]],enderId=6114,rewardNextId=1678,exGroup=1638,poiX=-5046,poiY=-1273,wowhead=[[https://www.wowhead.com/wotlk/quest=1679]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello, warrior!  You show a lot of promise, but you still need to learn some tricks and Muren Stormpike is just the dwarf to teach you. You can find Muren at the Hall of Arms in the Military Ward of Ironforge.  Talk to him when you're ready to learn what it is to be a warrior.]],logDesc=[[Speak with Muren Stormpike.]]}
DB[1680]={id=1680,name=[[Tormus Deepforge]],name_loc=[[Tormus Forjahonda]],level=11,minLevel=10,giver=[[Muren Stormpike]],giver_loc=[[Muren Pico Tormenta]],giverType=[[NPC]],giverId=6114,ender=[[Tormus Deepforge]],ender_loc=[[Tormus Forjahonda]],enderType=[[NPC]],enderId=6031,prevId=1678,rewardNextId=1681,poiX=-4793,poiY=-1098,wowhead=[[https://www.wowhead.com/wotlk/quest=1680]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you've learned some moves, it's time to get you a decent weapon.  Speak with Tormus Deepforge.  He can make you a weapon I'm sure you'll like. You'll find Tormus here in Ironforge, at the Great Forge.]],logDesc=[[Speak with Tormus Deepforge.]]}
DB[1681]={id=1681,name=[[Ironband's Compound]],name_loc=[[Complejo Vetaferro]],level=11,minLevel=10,giver=[[Tormus Deepforge]],giver_loc=[[Tormus Forjahonda]],giverType=[[NPC]],giverId=6031,ender=[[Tormus Deepforge]],ender_loc=[[Tormus Forjahonda]],enderType=[[NPC]],enderId=6031,prevId=1680,poiX=-5918,poiY=-2038,wowhead=[[https://www.wowhead.com/wotlk/quest=1681]],image=[[assets/images/quests/placeholder.png]],desc=[[My mentor, Sturgy Ironband, had a compound south of Helm's Bed Lake in eastern Dun Morogh.  There he taught blacksmithing and he was the best. But one day, one of his students brought him a load of strange ore.  Master Ironband called it umbral ore and was eager to work with it, but soon after it arrived... a band of Dark Iron dwarves attacked his compound.  They killed everyone! Enter Ironband's compound, $N, and avenge my master's death.  And bring me the load of umbral ore that caused it.]],logDesc=[[Bring a load of Umbral Ore to Tormus Deepforge in Ironforge.]]}
DB[1682]={id=1682,name=[[Grey Iron Weapons]],name_loc=[[Armas de hierro gris]],level=10,minLevel=10,giver=[[Tormus Deepforge]],giver_loc=[[Tormus Forjahonda]],giverType=[[NPC]],giverId=6031,ender=[[Tormus Deepforge]],ender_loc=[[Tormus Forjahonda]],enderType=[[NPC]],enderId=6031,prevId=1681,poiX=-4793,poiY=-1098,wowhead=[[https://www.wowhead.com/wotlk/quest=1682]],image=[[assets/images/quests/placeholder.png]],choiceRewards={{id=6978,qty=1},{id=6982,qty=1},{id=6981,qty=1},{id=6984,qty=1}}}
DB[1683]={id=1683,name=[[Vorlus Vilehoof]],name_loc=[[Vorlus Pezuñavil]],level=-1,minLevel=10,giver=[[Elanaria]],giverType=[[NPC]],giverId=4088,ender=[[Elanaria]],enderType=[[NPC]],enderId=4088,prevId=1684,poiX=9676,poiY=1410,wowhead=[[https://www.wowhead.com/wotlk/quest=1683]],image=[[assets/images/quests/placeholder.png]],desc=[[Before I can teach you, you must show me your resolve. The satyr Vorlus Vilehoof has found one of our remote moonwells, southeast of the Ban'ethil Barrow Den.  He now splashes within it, defiling its pure waters with his filth. Find Vorlus at the moonwell and destroy him.  Bring me his horn as proof and I will begin your advanced training as a warrior. The path to the moonwell is hidden well, $N, but stay focused and alert and you will find it.]],logDesc=[[Bring the Horn of Vorlus to Elanaria in Darnassus.]]}
DB[1684]={id=1684,name=[[Elanaria]],name_loc=[[Elanaria]],level=-1,minLevel=10,giver=[[Moon Priestess Amara]],giver_loc=[[Sacerdotisa Lunar Amara]],giverType=[[NPC]],giverId=2151,ender=[[Elanaria]],enderType=[[NPC]],enderId=4088,rewardNextId=1683,exGroup=1638,poiX=9994,poiY=2332,wowhead=[[https://www.wowhead.com/wotlk/quest=1684]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, warrior.  Your skill grows, but there is more to your profession than you may believe.  To further progress, you must soon find a teacher. The warrior Elanaria dwells in Darnassus, at the Warrior's Terrace.  She can instruct you.]],logDesc=[[Speak with Elanaria.]]}
DB[1684]={id=1684,name=[[Elanaria]],name_loc=[[Elanaria]],level=-1,minLevel=10,giver=[[Kyra Windblade]],giver_loc=[[Sacerdotisa Lunar Amara]],giverType=[[NPC]],giverId=3598,ender=[[Elanaria]],enderType=[[NPC]],enderId=4088,rewardNextId=1683,exGroup=1638,poiX=9994,poiY=2332,wowhead=[[https://www.wowhead.com/wotlk/quest=1684]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, warrior.  Your skill grows, but there is more to your profession than you may believe.  To further progress, you must soon find a teacher. The warrior Elanaria dwells in Darnassus, at the Warrior's Terrace.  She can instruct you.]],logDesc=[[Speak with Elanaria.]]}
DB[1685]={id=1685,name=[[Gakin's Summons]],name_loc=[[La invocación de Gakin]],level=-1,minLevel=10,giver=[[Remen Marcot]],giverType=[[NPC]],giverId=6121,ender=[[Gakin the Darkbinder]],ender_loc=[[Gakin el Presotenebra]],enderType=[[NPC]],enderId=6122,rewardNextId=1688,poiX=-8983,poiY=1042,wowhead=[[https://www.wowhead.com/wotlk/quest=1685]],image=[[assets/images/quests/placeholder.png]],desc=[[Isn't that how it always works? Was looking for you all day and couldn't find you, now when I'm not expecting it, you come and walk right up to me. I've wasted enough time trying to find you, so I won't delay you any longer. Master Gakin's summoned you for additional training. Seems to me you should seek him out as soon as possible. You'll find him in the basement of the Slaughtered Lamb tavern. By the way, you might want to keep that particular location quiet. Don't want word spreading about it.]],logDesc=[[Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.]]}
DB[1686]={id=1686,name=[[The Shade of Elura]],name_loc=[[La sombra de Elura]],level=10,minLevel=10,giver=[[Elanaria]],giverType=[[NPC]],giverId=4088,ender=[[Elanaria]],enderType=[[NPC]],enderId=4088,prevId=1683,rewardNextId=1692,poiX=6356,poiY=723,wowhead=[[https://www.wowhead.com/wotlk/quest=1686]],image=[[assets/images/quests/placeholder.png]],desc=[[You have learned much, $N.  Now we will craft you a weapon.  A warrior's weapon. To do this, you must travel to Darkshore. Long ago a ship crashed upon the rocks near the Auberdine lighthouse, scattering many crates of elunite ore along the ocean floor. First, you must defeat the elunite's guardian, the Shade of Elura.  Once the ship's captain, she cursed herself to roam the deeps and protect her shipment for all time.  Defeat her, gain her medallion, and gather the crates of lost Elunite.]],logDesc=[[Bring 8 loads of Elunite Ore and the Medallion of Elura to Elanaria in Darnassus.]]}
DB[1687]={id=1687,name=[[Spooky Lighthouse]],name_loc=[[El faro fantasma]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Human Orphan]],ender_loc=[[Huérfano humano]],enderType=[[NPC]],enderId=14305,prevId=1468,exGroup=-1479,poiX=-11400,poiY=1945,wowhead=[[https://www.wowhead.com/wotlk/quest=1687]],image=[[assets/images/quests/placeholder.png]],desc=[[Sometimes late at night, our matrons at the orphanage will tell us spooky stories.  Those RULE!  There's one about a ghost that haunts a lighthouse in Westfall.  They say he was a pirate captain who had his ship taken from him by other pirates.  Wow! Could you please take me to the lighthouse in Westfall?  I wanna see if the ghost of that captain is there!  I promise to stay close to you; I won't run off or anything!]],logDesc=[[Take the orphan to see the lighthouse off the coast of Westfall. ]]}
DB[1688]={id=1688,name=[[Surena Caledon]],name_loc=[[Surena Caledon]],level=-1,minLevel=10,giver=[[Gakin the Darkbinder]],giver_loc=[[Gakin el Presotenebra]],giverType=[[NPC]],giverId=6122,ender=[[Gakin the Darkbinder]],ender_loc=[[Gakin el Presotenebra]],enderType=[[NPC]],enderId=6122,rewardNextId=1689,poiX=-9806,poiY=-927,wowhead=[[https://www.wowhead.com/wotlk/quest=1688]],image=[[assets/images/quests/placeholder.png]],desc=[[I had a student named Surena Caledon. She stood where you stand now, eager to learn of warlock magic, and possessing no small bit of talent. More than that she was young and pleasing to the eye. Had I seen it then, the traitorous trollop! The thieving wench ran off with one of the Defias, Erlan Drudgemoor. While her loss is of little importance, I gifted her a bloodstone choker that I must have. Her life means nothing to me now. You will find her at the Brackwell Pumpkin Patch. Retrieve what is mine.]],logDesc=[[Retrieve Surena's Choker for Gakin the Darkbinder in Stormwind.]]}
DB[1689]={id=1689,name=[[The Binding]],name_loc=[[El vínculo]],level=-1,minLevel=10,giver=[[Gakin the Darkbinder]],giver_loc=[[Gakin el Presotenebra]],giverType=[[NPC]],giverId=6122,ender=[[Gakin the Darkbinder]],ender_loc=[[Gakin el Presotenebra]],enderType=[[NPC]],enderId=6122,prevId=1688,poiX=-8973,poiY=1043,wowhead=[[https://www.wowhead.com/wotlk/quest=1689]],image=[[assets/images/quests/placeholder.png]],desc=[[By retrieving my choker and besting Surena, you've proven that you're at least as capable as she was. With that said, I can tell you're direly in need of training. You can manage the flows of magic, yes, but being a warlock is much more than that. I will show you how to command a voidwalker, but before I can, you must call one forth at a summoning circle and subdue it using whatever weapons--physical and magical--you have at your disposal. Use the magic of this choker at the summoning circle below.]],logDesc=[[Using the Bloodstone Choker, summon and subdue a voidwalker, then return the Bloodstone Choker to Gakin the Darkbinder in Stormwind.]]}
DB[1690]={id=1690,zoneId=440,name=[[Wastewander Justice]],name_loc=[[Justicia para los Vagayermos]],level=43,minLevel=40,giver=[[Chief Engineer Bilgewhizzle]],giver_loc=[[Ingeniero jefe Pasaquillas]],giverType=[[NPC]],giverId=7407,ender=[[Chief Engineer Bilgewhizzle]],ender_loc=[[Ingeniero jefe Pasaquillas]],enderType=[[NPC]],enderId=7407,rewardNextId=1691,poiX=-7358,poiY=-4745,wowhead=[[https://www.wowhead.com/wotlk/quest=1690]],image=[[assets/images/quests/placeholder.png]],desc=[[You there!  It's time for you to be a big helper to the Gadgetzan Water Company. The Wastewander nomads out in the Tanaris desert have seized almost all the water wells!  Without access to them, our water supply will dry up in no time.  If you want to get in our good graces, then you'll help us bring justice to those nomads! Head east of here and bring down ten Wastewander Bandits and Thieves, then report back to me on the double.  Justice waits for no man... goblin... bah, just get on it!]],logDesc=[[Take down 10 Wastewander Bandits and Thieves east of Gadgetzan, then report back to Chief Engineer Bilgewhizzle.]]}
DB[1691]={id=1691,zoneId=440,name=[[More Wastewander Justice]],name_loc=[[Más justicia para los Vagayermos]],level=44,minLevel=40,giver=[[Chief Engineer Bilgewhizzle]],giver_loc=[[Ingeniero jefe Pasaquillas]],giverType=[[NPC]],giverId=7407,ender=[[Chief Engineer Bilgewhizzle]],ender_loc=[[Ingeniero jefe Pasaquillas]],enderType=[[NPC]],enderId=7407,prevId=1690,poiX=-7534,poiY=-4756,wowhead=[[https://www.wowhead.com/wotlk/quest=1691]],image=[[assets/images/quests/placeholder.png]],desc=[[We need you to take on the stronger ranks of the Wastewander nomads now.  You've done a good job thus far, but if we are to take back those water wells, then it only makes sense to do it against as few nomads as possible! This time around we need you to take down their rogues, assassins, and shadow mages.  You'll find them east and southeast of here. I'm not going to lie to you - they're a nasty lot.  Do this for us though, and we'll be on our way to taking back what is rightfully ours!]],logDesc=[[Take down 10 Wastewander Shadow Mages, 8 Wastewander Rogues, and 6 Wastewander Assassins for Chief Engineer Bilgewhizzle in Gadgetzan. ]]}
DB[1692]={id=1692,name=[[Smith Mathiel]],name_loc=[[Mathiel, el herrero]],level=10,minLevel=10,giver=[[Elanaria]],giverType=[[NPC]],giverId=4088,ender=[[Mathiel]],enderType=[[NPC]],enderId=6142,prevId=1686,poiX=9918,poiY=2309,wowhead=[[https://www.wowhead.com/wotlk/quest=1692]],image=[[assets/images/quests/placeholder.png]],desc=[[I have placed the elunite you gathered into a case.  Take it to the blacksmith Mathiel, and he will craft for you an elunite weapon. Mathiel is to the south, on the other side of this building.]],logDesc=[[Bring the Case of Elunite to Smith Mathiel.]]}
DB[1693]={id=1693,name=[[Weapons of Elunite]],name_loc=[[Armas de Elunita]],level=10,minLevel=10,giver=[[Mathiel]],giverType=[[NPC]],giverId=6142,ender=[[Mathiel]],enderType=[[NPC]],enderId=6142,prevId=1692,poiX=9918,poiY=2309,wowhead=[[https://www.wowhead.com/wotlk/quest=1693]],image=[[assets/images/quests/placeholder.png]],choiceRewards={{id=6966,qty=1},{id=6968,qty=1},{id=6969,qty=1},{id=6967,qty=1}}}
DB[1698]={id=1698,name=[[Yorus Barleybrew]],name_loc=[[Yorus Cebadiz]],level=20,minLevel=20,giver=[[Wu Shen]],giver_loc=[[Wu Shen]],giverType=[[NPC]],giverId=5479,ender=[[Yorus Barleybrew]],ender_loc=[[Yorus Cebadiz]],enderType=[[NPC]],enderId=6166,rewardNextId=1699,poiX=-9223,poiY=-2148,wowhead=[[https://www.wowhead.com/wotlk/quest=1698]],image=[[assets/images/quests/placeholder.png]],desc=[[Yorus Barleybrew has issued a challenge to all able warriors of the Alliance.  He waits at the Lakeshire Inn, in Redridge, and pledges a grand reward to anyone able to pass his trial.]],logDesc=[[Speak with Yorus Barleybrew.]]}
DB[1699]={id=1699,name=[[The Rethban Gauntlet]],name_loc=[[El guantelete de Rethban]],level=22,minLevel=20,giver=[[Yorus Barleybrew]],giver_loc=[[Yorus Cebadiz]],giverType=[[NPC]],giverId=6166,ender=[[Yorus Barleybrew]],ender_loc=[[Yorus Cebadiz]],enderType=[[NPC]],enderId=6166,poiX=-8933,poiY=-2009,wowhead=[[https://www.wowhead.com/wotlk/quest=1699]],image=[[assets/images/quests/placeholder.png]],desc=[[I call my challenge the Rethban Gauntlet.  To pass the trial, all you must do is enter the Rethban Caverns, to the first fork, then return here.  Easy!  Except there are a few wrinkles... You have to return within an hour. There are whole heaps of Redridge Gnolls in the way. Before you start, you have to take a swig of my family's signature drink: Barleybrew Scalder! So what do you say?  The Rethban Caverns are in the foothills north of Lakeshire.  Are you ready to run the Rethban Gauntlet?]],logDesc=[[Enter the Rethban Caverns, reach the first fork, and return to Yorus Barleybrew within the time allowed. You must not die and release your spirit.]]}
DB[1700]={id=1700,name=[[Grimand Elmore]],name_loc=[[Grimand Elmore]],level=28,minLevel=20,giver=[[Furen Longbeard]],giver_loc=[[Furen Barbalarga]],giverType=[[NPC]],giverId=5413,ender=[[Grimand Elmore]],enderType=[[NPC]],enderId=1416,prevId=1701,rewardNextId=1705,poiX=-8387,poiY=685,wowhead=[[https://www.wowhead.com/wotlk/quest=1700]],image=[[assets/images/quests/placeholder.png]],desc=[[I made a copy of my notes on the techniques I learned while making your armor, and I need them sent to Grimand Elmore.  He's here in the Dwarven District, in the weapon shop. And duck when you give these to him.  He's fiercely proud of his skills, and won't like the idea of learning something from me...]],logDesc=[[Bring Furen's Notes to Grimand Elmore.]]}
DB[1701]={id=1701,name=[[Fire Hardened Mail]],name_loc=[[Armadura de malla endurecida con fuego]],level=28,minLevel=20,giver=[[Furen Longbeard]],giver_loc=[[Furen Barbalarga]],giverType=[[NPC]],giverId=5413,ender=[[Furen Longbeard]],ender_loc=[[Furen Barbalarga]],enderType=[[NPC]],enderId=5413,prevId=1702,poiX=-8427,poiY=600,wowhead=[[https://www.wowhead.com/wotlk/quest=1701]],image=[[assets/images/quests/placeholder.png]],desc=[[So I gave you a nice shield, but we don't have to stop there.  I know the secrets to make extremely hard mail armor.  It's not easy and it takes very rare materials, but if you're willing to do the legwork then I'll make a piece for you. What do you say, $N?  If you're up for the challenge, then I'll give you a list of what to get and where to get them.]],logDesc=[[Gather the materials Furen Longbeard requires, and bring them to him in Stormwind.]]}
DB[1702]={id=1702,name=[[The Shieldsmith]],name_loc=[[El forjador de escudos]],level=22,minLevel=20,giver=[[Yorus Barleybrew]],giver_loc=[[Yorus Cebadiz]],giverType=[[NPC]],giverId=6166,ender=[[Furen Longbeard]],ender_loc=[[Furen Barbalarga]],enderType=[[NPC]],enderId=5413,prevId=1699,rewardNextId=1701,poiX=-8427,poiY=600,wowhead=[[https://www.wowhead.com/wotlk/quest=1702]],image=[[assets/images/quests/placeholder.png]],desc=[[You really showed what you were made of when you ran the Rethban Gauntlet, $N.  And I'm true to my word.  I'll get you the reward I promised... Except it's in Stormwind. Talk to my friend, Furen Longbeard, in the Dwarven District of Stormwind.  He's the best shieldsmith you'll ever meet, and he owes me a big favor. Here, take Furen this cask of Barleybrew Scalder and ask him for a shield.  He'll give you a nice one.]],logDesc=[[Bring the Cask of Scalder to Furen Longbeard.]],rewards={{id=6970,qty=1}}}
DB[1703]={id=1703,name=[[Mathiel]],name_loc=[[Mathiel]],level=28,minLevel=20,giver=[[Furen Longbeard]],giver_loc=[[Furen Barbalarga]],giverType=[[NPC]],giverId=5413,ender=[[Mathiel]],enderType=[[NPC]],enderId=6142,prevId=1701,rewardNextId=1710,poiX=9918,poiY=2309,wowhead=[[https://www.wowhead.com/wotlk/quest=1703]],image=[[assets/images/quests/placeholder.png]],desc=[[I made a copy of my notes on the techniques I learned while making your armor, and need them sent to the blacksmith Mathiel.  He lives in Darnassus which is quite a long way off, but I'm sure he'll be very grateful to learn what I've learned.]],logDesc=[[Bring Furen's Notes to Mathiel.]]}
DB[1704]={id=1704,name=[[Klockmort Spannerspan]],name_loc=[[Klockmort Palmalicate]],level=28,minLevel=20,giver=[[Furen Longbeard]],giver_loc=[[Furen Barbalarga]],giverType=[[NPC]],giverId=5413,ender=[[Klockmort Spannerspan]],ender_loc=[[Klockmort Palmalicate]],enderType=[[NPC]],enderId=6169,prevId=1701,rewardNextId=1708,poiX=-4812,poiY=-1251,wowhead=[[https://www.wowhead.com/wotlk/quest=1704]],image=[[assets/images/quests/placeholder.png]],desc=[[I made a copy of my notes on the techniques I learned while making your armor, and need someone to take them to Klockmort Spannerspan.  He's a gnomish blacksmith in Ironforge and when he learns what I've learned... I bet he'll pull off his own beard in excitement.]],logDesc=[[Bring Furen's Notes to Klockmort Spannerspan.]]}
DB[1705]={id=1705,name=[[Burning Blood]],name_loc=[[Sangre ardiente]],level=28,minLevel=20,giver=[[Grimand Elmore]],giverType=[[NPC]],giverId=1416,ender=[[Grimand Elmore]],enderType=[[NPC]],enderId=1416,prevId=1701,poiX=-10215,poiY=-849,wowhead=[[https://www.wowhead.com/wotlk/quest=1705]],image=[[assets/images/quests/placeholder.png]],desc=[[I hate to admit that Furen might have really found something.  But to be sure I'll need to try his techniques on a new piece of armor.  If you help me with the materials, $N, then you can have the armor. To make this armor, I need samples of burning blood and a burning rock. The only place I know to get them is Duskwood.  The Nightbane worgen based in the Roland's Doom mine have burning blood, and their leader Gutspill will have the rock. May fortune grant you speed, $N.]],logDesc=[[Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind.]]}
DB[1706]={id=1706,name=[[Grimand's Armor]],name_loc=[[La armadura de Grimand]],level=30,minLevel=20,giver=[[Grimand Elmore]],giverType=[[NPC]],giverId=1416,ender=[[Grimand Elmore]],enderType=[[NPC]],enderId=1416,prevId=1705,poiX=-8387,poiY=685,wowhead=[[https://www.wowhead.com/wotlk/quest=1706]],image=[[assets/images/quests/placeholder.png]],rewards={{id=6971,qty=1}}}
DB[1707]={id=1707,zoneId=440,name=[[Water Pouch Bounty]],name_loc=[[Cazador de faltriqueras de agua]],level=44,minLevel=40,giver=[[Spigot Operator Luglunket]],giver_loc=[[Grifoperador Llantalunket]],giverType=[[NPC]],giverId=7408,ender=[[Spigot Operator Luglunket]],ender_loc=[[Grifoperador Llantalunket]],enderType=[[NPC]],enderId=7408,poiX=-7480,poiY=-4786,wowhead=[[https://www.wowhead.com/wotlk/quest=1707]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings $n - the name's Luglunket, and we've got an important job for you if you're up for it!  Huzzah! Nothing would please me more as a seasoned spigot operator to take any Wastewander water pouches you might find out in the desert.  That's our water anyway - the nomads have just stolen it is all!  The Gadgetzan Water Company will offer you an official care package for every five you turn in.  Most importantly though, you're helping Gadgetzan help itself!]],logDesc=[[Bring 5 Wastewander Water Pouches to Spigot Operator Luglunket in Gadgetzan.]],rewards={{id=8484,qty=1}}}
DB[1708]={id=1708,name=[[Iron Coral]],name_loc=[[Coral férreo]],level=29,minLevel=20,giver=[[Klockmort Spannerspan]],giver_loc=[[Klockmort Palmalicate]],giverType=[[NPC]],giverId=6169,ender=[[Klockmort Spannerspan]],ender_loc=[[Klockmort Palmalicate]],enderType=[[NPC]],enderId=6169,prevId=1701,poiX=-4812,poiY=-1251,wowhead=[[https://www.wowhead.com/wotlk/quest=1708]],image=[[assets/images/quests/placeholder.png]],desc=[[I want to try Furen Longbeard's new techniques on my own piece of armor.  And because you helped Furen and he helped me, you're welcome to the armor after I make it! To finish the piece, I need a special coral, searing coral.  It grows in only one place--along the coast south of Menethil Harbor in the Wetlands. Bring me enough searing coral and I'll get right to work on the armor.  And hurry, $N.  I'm so eager to get started it's making my toes twist!]],logDesc=[[Bring 20 loads of Searing Coral to Klockmort Spannerspan in Ironforge.]]}
DB[1709]={id=1709,name=[[Klockmort's Creation]],name_loc=[[La creación de Klockmort]],level=30,minLevel=20,giver=[[Klockmort Spannerspan]],giver_loc=[[Klockmort Palmalicate]],giverType=[[NPC]],giverId=6169,ender=[[Klockmort Spannerspan]],ender_loc=[[Klockmort Palmalicate]],enderType=[[NPC]],enderId=6169,prevId=1708,poiX=-4812,poiY=-1251,wowhead=[[https://www.wowhead.com/wotlk/quest=1709]],image=[[assets/images/quests/placeholder.png]],rewards={{id=6974,qty=1}}}
DB[1710]={id=1710,name=[[Sunscorched Shells]],name_loc=[[Cáscaras asoladas]],level=30,minLevel=20,giver=[[Mathiel]],giverType=[[NPC]],giverId=6142,ender=[[Mathiel]],enderType=[[NPC]],enderId=6142,prevId=1701,poiX=9918,poiY=2309,wowhead=[[https://www.wowhead.com/wotlk/quest=1710]],image=[[assets/images/quests/placeholder.png]],desc=[[My colleague, Furen Longbeard, made a discovery which I am eager to test.  I wish to try it on a new armor that I am researching, for I believe Furen's techniques will produce superior results. Will you help me?  If you gather what I need to make the armor, then I will make an extra piece for you. I need the sunscorched egg shells of the Highperch Wyverns who dwell at Highperch, in Thousand Needles.  Search for the shells below their nests, and return to me when you have a sufficient amount.]],logDesc=[[Bring 20 Sunscorched Shells to Mathiel in Darnassus.]]}
DB[1711]={id=1711,name=[[Mathiel's Armor]],name_loc=[[La armadura de Mathiel]],level=30,minLevel=20,giver=[[Mathiel]],giverType=[[NPC]],giverId=6142,ender=[[Mathiel]],enderType=[[NPC]],enderId=6142,prevId=1710,poiX=9918,poiY=2309,wowhead=[[https://www.wowhead.com/wotlk/quest=1711]],image=[[assets/images/quests/placeholder.png]],rewards={{id=6973,qty=1}}}
DB[1712]={id=1712,name=[[Cyclonian]],name_loc=[[Ciclonio]],level=40,minLevel=30,giver=[[Bath'rah the Windwatcher]],giver_loc=[[Bath'rah el Vigía del viento]],giverType=[[NPC]],giverId=6176,ender=[[Bath'rah the Windwatcher]],ender_loc=[[Bath'rah el Vigía del viento]],enderType=[[NPC]],enderId=6176,prevId=1791,rewardNextId=1713,poiX=-6,poiY=186,wowhead=[[https://www.wowhead.com/wotlk/quest=1712]],image=[[assets/images/quests/placeholder.png]],desc=[[I have spent ages watching this site.  I watch, so that one day I might see the great Cyclonian fall.  But I have not yet found a champion to defeat the wind lord. Perhaps you are that champion. Prove it to me.  Gather the items I need to summon Cyclonian, and I will know you are a great warrior.  Perhaps then you can defeat him and gain his whirlwind heart. If so, then I will infuse the heart's power in a weapon, and I will give that weapon to you. Here is a parchment with the items I need.]],logDesc=[[Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac.]]}
DB[1713]={id=1713,name=[[The Summoning]],name_loc=[[La invocación]],level=40,minLevel=30,giver=[[Bath'rah the Windwatcher]],giver_loc=[[Bath'rah el Vigía del viento]],giverType=[[NPC]],giverId=6176,ender=[[Bath'rah the Windwatcher]],ender_loc=[[Bath'rah el Vigía del viento]],enderType=[[NPC]],enderId=6176,prevId=1712,poiX=343,poiY=-1474,wowhead=[[https://www.wowhead.com/wotlk/quest=1713]],image=[[assets/images/quests/placeholder.png]],desc=[[I am ready to perform the ritual to summon Cyclonian.  When he is summoned, you must defeat him and take his whirlwind heart.  This I will use to instill a weapon with Cyclonian's power. $N, are you ready to face the wind lord?]],logDesc=[[Bring the Whirlwind Heart to Bath'rah Windwatcher.]]}
DB[1714]={id=1714,name=[[Essence of the Exile]],name_loc=[[Esencia del exilio]],level=37,minLevel=30,giver=[[Bath'rah's Cauldron]],giver_loc=[[Caldera de Bath'rah]],giverType=[[GO]],giverId=89931,ender=[[Bath'rah's Cauldron]],ender_loc=[[Caldera de Bath'rah]],enderType=[[GO]],enderId=89931,prevId=-1712,poiX=253,poiY=-1438,wowhead=[[https://www.wowhead.com/wotlk/quest=1714]],image=[[assets/images/quests/placeholder.png]],rewards={{id=6851,qty=1}}}
DB[1715]={id=1715,name=[[The Slaughtered Lamb]],name_loc=[[El Cordero Degollado]],level=-1,minLevel=10,giver=[[Lago Blackwrench]],giver_loc=[[Yago Llavenegra]],giverType=[[NPC]],giverId=6120,ender=[[Gakin the Darkbinder]],ender_loc=[[Gakin el Presotenebra]],enderType=[[NPC]],enderId=6122,poiX=-8983,poiY=1042,wowhead=[[https://www.wowhead.com/wotlk/quest=1715]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmph. Times past, all warlocks in Khaz Modan were trained under the auspices of the masters of Gnomeregan, but now that we've all been forced to relocate into this rat's hole in Ironforge, and Magni's decided to keep a careful watch on us, we're forced to send our novices to Stormwind for training. Luckily, Gakin's no slouch, so you'll still learn what you need to know, but it burns my blood! Anyways, you'll find Gakin in the basement of the Slaughtered Lamb in Stormwind.]],logDesc=[[Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.]]}
DB[1716]={id=1716,name=[[Devourer of Souls]],name_loc=[[Devoradora de almas]],level=-1,minLevel=20,giver=[[Gakin the Darkbinder]],giver_loc=[[Gakin el Presotenebra]],giverType=[[NPC]],giverId=6122,ender=[[Takar the Seer]],ender_loc=[[Takar el Vidente]],enderType=[[NPC]],enderId=6244,rewardNextId=1738,poiX=-2245,poiY=-2374,wowhead=[[https://www.wowhead.com/wotlk/quest=1716]],image=[[assets/images/quests/placeholder.png]],desc=[[A succubus is a devourer of souls, destroyer of hearts, and dominator of minds. It knows nothing but evil. This will be the creature you will learn to summon and control, but it cannot be brought into our world without a stimulus. With a symbol of love as bait, it will surely answer your call. Then you can defeat it, and make it your tool. It will be hard to find something of this nature, though. You should speak with Takar the Seer. You will find him in the Barrens of Kalimdor near Camp Taurajo.]],logDesc=[[Speak with Takar the Seer in the Barrens.]]}
DB[1717]={id=1717,name=[[Gakin's Summons]],name_loc=[[La invocación de Gakin]],level=-1,minLevel=20,giver=[[Lago Blackwrench]],giver_loc=[[Yago Llavenegra]],giverType=[[NPC]],giverId=6120,ender=[[Gakin the Darkbinder]],ender_loc=[[Gakin el Presotenebra]],enderType=[[NPC]],enderId=6122,rewardNextId=1716,poiX=-8983,poiY=1042,wowhead=[[https://www.wowhead.com/wotlk/quest=1717]],image=[[assets/images/quests/placeholder.png]],desc=[[$n! Didn't expect to see you around these parts, but I was instructed to keep an eye out for you. It's past time you got some more training, so you should stop in to see Gakin the next time you're in Stormwind. He'll be waiting for you.]],logDesc=[[Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.]]}
DB[1718]={id=1718,name=[[The Islander]],name_loc=[[El isleño]],level=-1,minLevel=30,giver=[[Torm Ragetotem]],giver_loc=[[Torm Tótem de Ira]],giverType=[[NPC]],giverId=3041,ender=[[Klannoc Macleod]],ender_loc=[[Klannoc Macleod]],enderType=[[NPC]],enderId=6236,rewardNextId=1719,poiX=-1709,poiY=-4330,wowhead=[[https://www.wowhead.com/wotlk/quest=1718]],image=[[assets/images/quests/placeholder.png]],desc=[[Your renown as a warrior grows, $N.  Now it is time to pit yourself against your peers and see where you stand. There is an island off the coast of the Barrens, south of Ratchet.  It is called Fray Island and it is a place where warriors meet. Meet, and fight. Speak with the chief warrior of Fray Island, Klannoc Macleod.  If he finds you worthy, then Klannoc will lead you further down the warrior's path. To reach Fray Island, search for the sand bar shallows along the Merchant Coast.]],logDesc=[[Speak with Klannoc Macleod.]]}
DB[1718]={id=1718,name=[[The Islander]],name_loc=[[El isleño]],level=-1,minLevel=30,giver=[[Sorek]],giver_loc=[[Torm Tótem de Ira]],giverType=[[NPC]],giverId=3354,ender=[[Klannoc Macleod]],ender_loc=[[Klannoc Macleod]],enderType=[[NPC]],enderId=6236,rewardNextId=1719,poiX=-1709,poiY=-4330,wowhead=[[https://www.wowhead.com/wotlk/quest=1718]],image=[[assets/images/quests/placeholder.png]],desc=[[Your renown as a warrior grows, $N.  Now it is time to pit yourself against your peers and see where you stand. There is an island off the coast of the Barrens, south of Ratchet.  It is called Fray Island and it is a place where warriors meet. Meet, and fight. Speak with the chief warrior of Fray Island, Klannoc Macleod.  If he finds you worthy, then Klannoc will lead you further down the warrior's path. To reach Fray Island, search for the sand bar shallows along the Merchant Coast.]],logDesc=[[Speak with Klannoc Macleod.]]}
