DB[3090]={id=3090,name=[[Tainted Parchment]],name_loc=[[Papiro corrupto]],level=1,minLevel=1,giver=[[Gornek]],giverType=[[NPC]],giverId=3143,ender=[[Nartok]],ender_loc=[[Nartok]],enderType=[[NPC]],enderId=3156,prevId=788,poiX=-607,poiY=-4112,wowhead=[[https://www.wowhead.com/wotlk/quest=3090]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, while you were gone a parchment came for you, $N. I usually avoid dealing with warlocks if I can help it, but I think you should read it when you have time. If I'm not mistaken, it came from your newly-appointed trainer Nartok. He would have words with you when you're ready.]],logDesc=[[Read the Tainted Parchment and speak to Nartok inside the Den in the Valley of Trials.]]}
DB[3091]={id=3091,name=[[Simple Note]],name_loc=[[La nota simple]],level=1,minLevel=1,giver=[[Grull Hawkwind]],giver_loc=[[Grull Viento de Halcón]],giverType=[[NPC]],giverId=2980,ender=[[Harutt Thunderhorn]],ender_loc=[[Harutt Tronacuerno]],enderType=[[NPC]],enderId=3059,prevId=747,poiX=-2880,poiY=-213,wowhead=[[https://www.wowhead.com/wotlk/quest=3091]],image=[[assets/images/quests/placeholder.png]],desc=[[Just a moment ago a messenger was looking for you, $N. I believe she was sent by the warrior trainer Harutt. If this note is from Harutt, I wouldn't take long in reading it's contents. ]],logDesc=[[Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache.]]}
