DB[3116]={id=3116,name=[[Simple Sigil]],name_loc=[[El sigilo simple]],level=1,minLevel=1,giver=[[Conservator Ilthalaine]],giver_loc=[[Conservador Ilthalaine]],giverType=[[NPC]],giverId=2079,ender=[[Alyissia]],ender_loc=[[Alyissia]],enderType=[[NPC]],enderId=3593,prevId=456,poiX=10527,poiY=778,wowhead=[[https://www.wowhead.com/wotlk/quest=3116]],image=[[assets/images/quests/placeholder.png]],desc=[[This sigil was given to me by a messenger from our warrior trainer, Alyissia. It seems Alyissia would have words with you when you have a moment. Read it and bring it to her afterwards.]],logDesc=[[Read the Simple Sigil and speak to Alyissia in Shadowglen.]]}
