DB[3661]={id=3661,zoneId=702,name=[[Favored of Elune?]],name_loc=[[¿Creados por Elune?]],level=47,minLevel=42,giver=[[Erelas Ambersky]],giver_loc=[[Erelas Cieloámbar]],giverType=[[NPC]],giverId=7916,ender=[[Erelas Ambersky]],ender_loc=[[Erelas Cieloámbar]],enderType=[[NPC]],enderId=7916,poiX=8707,poiY=989,wowhead=[[https://www.wowhead.com/wotlk/quest=3661]],image=[[assets/images/quests/placeholder.png]],desc=[[Wildkin are quite unpredictable creatures, $N. Capable of incredible gentleness, these creatures will show extreme ferocity if something they deem important is threatened. These beasts are rumored to have been created by Elune, and I am interested in finding if this is really the truth. Recently, I heard about a population of wildkin living in the Hinterlands -- Vicious, Primitive, and Savage Owlbeasts. They can be found amongst the wildlife there. Will you gather some wildkin feathers for me?]],logDesc=[[Collect 15 Wildkin Feathers from the Hinterlands for Erelas Ambersky in Rut'theran Village.]]}
DB[3681]={id=3681,name=[[Tome of Divinity]],name_loc=[[Escrito sobre divinidad]],level=-1,minLevel=12,giver=[[Brandur Ironhammer]],giver_loc=[[Brandur Martiyerro]],giverType=[[NPC]],giverId=5149,ender=[[Duthorian Rall]],enderType=[[NPC]],enderId=6171,nextId=1643,exGroup=2998,poiX=-8546,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=3681]],image=[[assets/images/quests/placeholder.png]],desc=[[Sorry to interrupt your travels, $r, but I thought you should know that word was sent from Stormwind recently asking that paladins report there for training. If I didn't know any better, I'd say your close to reaching a special time and it's time you started studying the Tomes. Look for Duthorian Rall in Stormwind. He usually trains paladins in the Cathedral of Light.]],logDesc=[[Speak with Duthorian Rall in Stormwind.]]}
DB[3701]={id=3701,zoneId=1537,name=[[The Smoldering Ruins of Thaurissan]],name_loc=[[Las humeantes Ruinas de Thaurissan]],level=54,minLevel=50,giver=[[Royal Historian Archesonus]],giver_loc=[[Historiador real Archesonus]],giverType=[[NPC]],giverId=8879,ender=[[Royal Historian Archesonus]],ender_loc=[[Historiador real Archesonus]],enderType=[[NPC]],enderId=8879,prevId=3702,poiX=-7694,poiY=-2387,wowhead=[[https://www.wowhead.com/wotlk/quest=3701]],image=[[assets/images/quests/placeholder.png]],desc=[[Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible. It is said that mysterious relics litter the ruins. Perhaps you should start your search there, $N. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected.]],logDesc=[[Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.]],rewards={{id=12102,qty=1}}}
DB[3702]={id=3702,zoneId=1537,name=[[The Smoldering Ruins of Thaurissan]],name_loc=[[Las humeantes Ruinas de Thaurissan]],level=54,minLevel=50,giver=[[Royal Historian Archesonus]],giver_loc=[[Historiador real Archesonus]],giverType=[[NPC]],giverId=8879,ender=[[Royal Historian Archesonus]],ender_loc=[[Historiador real Archesonus]],enderType=[[NPC]],enderId=8879,rewardNextId=3701,poiX=-4861,poiY=-1017,wowhead=[[https://www.wowhead.com/wotlk/quest=3702]],image=[[assets/images/quests/placeholder.png]],desc=[[Would you like to hear a brief history of the Dark Iron dwarves?]],logDesc=[[Listen to Royal Historian Archesonus recant the history of Thaurissan.]]}
DB[3721]={id=3721,zoneId=35,name=[[An OOX of Your Own]],name_loc=[[Tu propio OOX]],level=50,minLevel=40,giver=[[Oglethorpe Obnoticus]],giver_loc=[[Oglethorpe Obnoticus]],giverType=[[NPC]],giverId=7406,ender=[[Oglethorpe Obnoticus]],ender_loc=[[Oglethorpe Obnoticus]],enderType=[[NPC]],enderId=7406,poiX=-14417,poiY=411,wowhead=[[https://www.wowhead.com/wotlk/quest=3721]],image=[[assets/images/quests/placeholder.png]],rewards={{id=10398,qty=1}}}
DB[3741]={id=3741,zoneId=44,name=[[Hilary's Necklace]],name_loc=[[El collar de Hilary]],level=15,minLevel=12,giver=[[Shawn]],giverType=[[NPC]],giverId=8965,ender=[[Hilary]],ender_loc=[[Nida]],enderType=[[NPC]],enderId=8962,poiX=-9364,poiY=-2397,wowhead=[[https://www.wowhead.com/wotlk/quest=3741]],image=[[assets/images/quests/placeholder.png]],desc=[[My friend Hilary lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things. Could you find it for her, please?]],logDesc=[[Find Hilary's Necklace, and return it to Hilary in Lakeshire.]]}
DB[3761]={id=3761,zoneId=1638,name=[[Un'Goro Soil]],name_loc=[[Tierra de Un'Goro]],level=50,minLevel=47,giver=[[Arch Druid Hamuul Runetotem]],giver_loc=[[Archidruida Hamuul Tótem de Runa]],giverType=[[NPC]],giverId=5769,ender=[[Ghede]],enderType=[[NPC]],enderId=9076,prevId=936,poiX=-1003,poiY=-292,wowhead=[[https://www.wowhead.com/wotlk/quest=3761]],image=[[assets/images/quests/placeholder.png]],desc=[[The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  The Cenarion Circle wants to study this soil in large quantities; go into the wilds of Un'Goro and acquire enough of it for our continued research. The rich soil will stick out in piles from time to time, and some of the beasts might have usable samples on their being.  Take them all outside to Ghede; just look for the piles of dirt and the tauren barking orders.  He means well, just don't get him riled up though!]],logDesc=[[Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff.]]}
DB[3762]={id=3762,zoneId=1638,name=[[Assisting Arch Druid Runetotem]],name_loc=[[Ayuda al archidruida Tótem de Runa]],level=50,minLevel=47,giver=[[Innkeeper Pala]],giver_loc=[[Tabernera Pala]],giverType=[[NPC]],giverId=6746,ender=[[Arch Druid Hamuul Runetotem]],ender_loc=[[Archidruida Hamuul Tótem de Runa]],enderType=[[NPC]],enderId=5769,rewardNextId=3761,poiX=-1049,poiY=-304,wowhead=[[https://www.wowhead.com/wotlk/quest=3762]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me $c, but I'd like just a moment of your time if possible. The Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research. Please - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.]],logDesc=[[Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.]]}
DB[3763]={id=3763,zoneId=1657,name=[[Assisting Arch Druid Staghelm]],name_loc=[[Ayuda al archidruida Corzocelada]],level=50,minLevel=47,giver=[[Innkeeper Saelienne]],giver_loc=[[Tabernera Saelienne]],giverType=[[NPC]],giverId=6735,ender=[[Arch Druid Fandral Staghelm]],ender_loc=[[Archidruida Fandral Corzocelada]],enderType=[[NPC]],enderId=3516,rewardNextId=3764,poiX=10175,poiY=2568,wowhead=[[https://www.wowhead.com/wotlk/quest=3763]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me $c, but I'd like just a moment of your time if possible. The Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research. Please - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.]],logDesc=[[Speak with Arch Druid Fandral Staghelm in Darnassus.]]}
DB[3764]={id=3764,zoneId=1657,name=[[Un'Goro Soil]],name_loc=[[Tierra de Un'Goro]],level=50,minLevel=47,giver=[[Arch Druid Fandral Staghelm]],giver_loc=[[Archidruida Fandral Corzocelada]],giverType=[[NPC]],giverId=3516,ender=[[Jenal]],ender_loc=[[Jenal]],enderType=[[NPC]],enderId=9047,poiX=10180,poiY=2605,wowhead=[[https://www.wowhead.com/wotlk/quest=3764]],image=[[assets/images/quests/placeholder.png]],desc=[[The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  I want to know facts from falsehoods; go into the wilds of Un'Goro and acquire enough quality samples of soil for our continued study. You may think that collection tasks are beneath you; that sort of attitude does not endear yourself to me or the Cenarion Circle.  Bring the samples to Jenal, who is no doubt wasting time outside behind this tree; just look for the piles of dirt.  He will handle the logistics - not I.]],logDesc=[[Bring 20 Un'Goro Soil samples to Jenal at the Cenarion Enclave in Darnassus.]]}
DB[3765]={id=3765,zoneId=1519,name=[[The Corruption Abroad]],name_loc=[[Lejana corrupción]],level=24,minLevel=18,giver=[[Argos Nightwhisper]],giver_loc=[[Argos Susurro Nocturno]],giverType=[[NPC]],giverId=4984,ender=[[Gershala Nightwhisper]],ender_loc=[[Gershala Susurro Nocturno]],enderType=[[NPC]],enderId=8997,rewardNextId=1275,poiX=6454,poiY=431,wowhead=[[https://www.wowhead.com/wotlk/quest=3765]],image=[[assets/images/quests/placeholder.png]],desc=[[Stormwind -- such a bustling hub of activity. I have traveled from afar to seek help. Often it is heard that brave adventurers roam these city streets. My brother, Gershala, requires assistance in Darkshore. He resides in the seaside town of Auberdine. The journey is a long and epic one. It is for this reason that I ask the help of a seasoned $c such as yourself.]],logDesc=[[Travel to Gershala Nightwhisper in Auberdine.]]}
DB[3781]={id=3781,zoneId=1657,name=[[Morrowgrain Research]],name_loc=[[Investigar la mañagrana]],level=50,minLevel=47,giver=[[Arch Druid Fandral Staghelm]],giver_loc=[[Archidruida Fandral Corzocelada]],giverType=[[NPC]],giverId=3516,ender=[[Mathrengyl Bearwalker]],ender_loc=[[Mathrengyl Garroso]],enderType=[[NPC]],enderId=4217,prevId=3764,rewardNextId=3785,poiX=10179,poiY=2564,wowhead=[[https://www.wowhead.com/wotlk/quest=3781]],image=[[assets/images/quests/placeholder.png]],desc=[[With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds blossom into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I intend to unravel this mystery. Take this to Mathrengyl downstairs, and he will give you some seeds so you can get started.  If you run out, you will need to purchase more from him.]],logDesc=[[Take the Arch Druid's Seed Voucher to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus.]],rewards={{id=11022,qty=20}}}
DB[3782]={id=3782,zoneId=1638,name=[[Morrowgrain Research]],name_loc=[[Investigar la mañagrana]],level=50,minLevel=47,giver=[[Arch Druid Hamuul Runetotem]],giver_loc=[[Archidruida Hamuul Tótem de Runa]],giverType=[[NPC]],giverId=5769,ender=[[Bashana Runetotem]],ender_loc=[[Bashana Tótem de Runa]],enderType=[[NPC]],enderId=9087,prevId=3761,rewardNextId=3786,poiX=-1088,poiY=-225,wowhead=[[https://www.wowhead.com/wotlk/quest=3782]],image=[[assets/images/quests/placeholder.png]],desc=[[With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds have blossomed into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I very much hope to unravel this mystery for the Circle. Take this voucher over to my daughter Bashana, and she will give you some seeds so you may assist us.  If you run out, you will need to purchase more from her.]],logDesc=[[Take the Seed Voucher to Bashana Runetotem in Thunder Bluff.]],rewards={{id=11022,qty=20}}}
DB[3783]={id=3783,zoneId=618,name=[[Are We There, Yeti?]],name_loc=[[Yeti... ¿ya hemos llegado?]],level=56,minLevel=52,giver=[[Umi Rumplesnicker]],giver_loc=[[Umi Risitas]],giverType=[[NPC]],giverId=10305,ender=[[Umi Rumplesnicker]],ender_loc=[[Umi Risitas]],enderType=[[NPC]],enderId=10305,rewardNextId=977,poiX=6630,poiY=-5412,wowhead=[[https://www.wowhead.com/wotlk/quest=3783]],image=[[assets/images/quests/placeholder.png]],desc=[[My friends are always coming up with great ideas. I've never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I'll let you in on the secret...  I'm going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they'll be impressed! I need thick yeti fur from the ice thistle yeti to start with. Will you help? You'll find them to the southeast.]],logDesc=[[Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook.]]}
DB[3784]={id=3784,zoneId=1497,name=[[Assisting Arch Druid Runetotem]],name_loc=[[Ayuda al archidruida Tótem de Runa]],level=50,minLevel=47,giver=[[Innkeeper Norman]],giver_loc=[[Tabernero Norman]],giverType=[[NPC]],giverId=6741,ender=[[Arch Druid Hamuul Runetotem]],ender_loc=[[Archidruida Hamuul Tótem de Runa]],enderType=[[NPC]],enderId=5769,rewardNextId=3761,poiX=-1049,poiY=-304,wowhead=[[https://www.wowhead.com/wotlk/quest=3784]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me $c, but I'd like just a moment of your time if possible. The Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research. Please - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.]],logDesc=[[Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.]]}
DB[3785]={id=3785,zoneId=1657,name=[[Morrowgrain Research]],name_loc=[[Investigar la mañagrana]],level=50,minLevel=47,giver=[[Mathrengyl Bearwalker]],giver_loc=[[Mathrengyl Garroso]],giverType=[[NPC]],giverId=4217,ender=[[Mathrengyl Bearwalker]],ender_loc=[[Mathrengyl Garroso]],enderType=[[NPC]],enderId=4217,prevId=3781,nextId=3803,poiX=10179,poiY=2564,wowhead=[[https://www.wowhead.com/wotlk/quest=3785]],image=[[assets/images/quests/placeholder.png]],desc=[[Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest. When you have enough morrowgrain, bring them here to me in the enclave.  Please don't bother the Arch Druid; he's a very busy man, and he doesn't need to be disturbed every time someone returns with another batch of morrowgrain!]],logDesc=[[Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain. Bring 10 Morrowgrain to Mathrengyl Bearwalker in Darnassus.]],rewards={{id=11887,qty=1}}}
DB[3786]={id=3786,zoneId=1638,name=[[Morrowgrain Research]],name_loc=[[Investigar la mañagrana]],level=50,minLevel=47,giver=[[Bashana Runetotem]],giver_loc=[[Bashana Tótem de Runa]],giverType=[[NPC]],giverId=9087,ender=[[Bashana Runetotem]],ender_loc=[[Bashana Tótem de Runa]],enderType=[[NPC]],enderId=9087,prevId=3782,nextId=3804,poiX=-1088,poiY=-225,wowhead=[[https://www.wowhead.com/wotlk/quest=3786]],image=[[assets/images/quests/placeholder.png]],desc=[[Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest. When you have enough morrowgrain, bring them to me here on Elder Rise.  Please don't bother the Arch Druid; he'll be very busy with the research, as well as the multitude of concerns he has!]],logDesc=[[Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain. Bring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff.]],rewards={{id=11887,qty=1}}}
DB[3787]={id=3787,zoneId=1519,name=[[Jonespyre's Request]],name_loc=[[La petición de Jonguja]],level=50,minLevel=47,giver=[[Tannysa]],giver_loc=[[Tannysa]],giverType=[[NPC]],giverId=5566,ender=[[Quintis Jonespyre]],ender_loc=[[Quintis Jonguja]],enderType=[[NPC]],enderId=7879,rewardNextId=3791,poiX=-4396,poiY=3187,wowhead=[[https://www.wowhead.com/wotlk/quest=3787]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me, friend... A colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides in Feathermoon Stronghold, Feralas.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid. If you're interested, speak with him; no doubt, all will be revealed once you do.]],logDesc=[[Speak with Quintis Jonespyre in Feathermoon Stronghold.]]}
DB[3788]={id=3788,zoneId=1116,name=[[Jonespyre's Request]],name_loc=[[La petición de Jonguja]],level=50,minLevel=47,giver=[[Innkeeper Shyria]],giver_loc=[[Tabernera Shyria]],giverType=[[NPC]],giverId=7736,ender=[[Quintis Jonespyre]],ender_loc=[[Quintis Jonguja]],enderType=[[NPC]],enderId=7879,rewardNextId=3791,poiX=-4396,poiY=3187,wowhead=[[https://www.wowhead.com/wotlk/quest=3788]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me, friend... A colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides here in Feathermoon Stronghold.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid. If you're interested, speak with him; no doubt, all will be revealed once you do.]],logDesc=[[Speak with Quintis Jonespyre in Feathermoon Stronghold.]]}
DB[3789]={id=3789,zoneId=1519,name=[[Assisting Arch Druid Staghelm]],name_loc=[[Ayuda al archidruida Corzocelada]],level=50,minLevel=47,giver=[[Innkeeper Allison]],giver_loc=[[Tabernera Allison]],giverType=[[NPC]],giverId=6740,ender=[[Arch Druid Fandral Staghelm]],ender_loc=[[Archidruida Fandral Corzocelada]],enderType=[[NPC]],enderId=3516,rewardNextId=3764,poiX=10175,poiY=2568,wowhead=[[https://www.wowhead.com/wotlk/quest=3789]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me $c, but I'd like just a moment of your time if possible. The Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research. Please - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.]],logDesc=[[Speak with Arch Druid Fandral Staghelm in Darnassus.]]}
DB[3790]={id=3790,zoneId=1537,name=[[Assisting Arch Druid Staghelm]],name_loc=[[Ayuda al archidruida Corzocelada]],level=50,minLevel=47,giver=[[Innkeeper Firebrew]],giver_loc=[[Tabernero Brebefuego]],giverType=[[NPC]],giverId=5111,ender=[[Arch Druid Fandral Staghelm]],ender_loc=[[Archidruida Fandral Corzocelada]],enderType=[[NPC]],enderId=3516,rewardNextId=3764,poiX=10175,poiY=2568,wowhead=[[https://www.wowhead.com/wotlk/quest=3790]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me $c, but I'd like just a moment of your time if possible. The Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research. Please - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.]],logDesc=[[Speak with Arch Druid Fandral Staghelm in Darnassus.]]}
DB[3791]={id=3791,zoneId=1116,name=[[The Mystery of Morrowgrain]],name_loc=[[El misterio de mañagrana]],level=50,minLevel=47,giver=[[Quintis Jonespyre]],giver_loc=[[Quintis Jonguja]],giverType=[[NPC]],giverId=7879,ender=[[Quintis Jonespyre]],ender_loc=[[Quintis Jonguja]],enderType=[[NPC]],enderId=7879,prevId=3785,poiX=-4396,poiY=3187,wowhead=[[https://www.wowhead.com/wotlk/quest=3791]],image=[[assets/images/quests/placeholder.png]],desc=[[Let me to be frank with you, $N.  I'm interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle's resources to procure vast amounts of morrowgrain.  I'm a researcher - curses are my specialty.  I've heard that morrowgrain, under the right conditions, exude qualities like other herbs used in primitive curses. I want to know more, and I ask for your help.  Bring me ten morrowgrain, and I will be sure to take care of you.]],logDesc=[[Bring 10 Morrowgrain to Quintis Jonespyre in Feathermoon Stronghold.]],choiceRewards={{id=11888,qty=1},{id=11889,qty=1}}}
DB[3792]={id=3792,zoneId=1116,name=[[Morrowgrain to Feathermoon Stronghold]],name_loc=[[Mañagrana a Bastión Plumaluna]],level=55,minLevel=47,giver=[[Quintis Jonespyre]],giver_loc=[[Quintis Jonguja]],giverType=[[NPC]],giverId=7879,ender=[[Quintis Jonespyre]],ender_loc=[[Quintis Jonguja]],enderType=[[NPC]],enderId=7879,prevId=3791,poiX=-4396,poiY=3187,wowhead=[[https://www.wowhead.com/wotlk/quest=3792]],image=[[assets/images/quests/placeholder.png]],rewards={{id=11022,qty=10}}}
DB[3801]={id=3801,zoneId=1584,name=[[Dark Iron Legacy]],name_loc=[[El legado de los Hierro Negro]],level=52,minLevel=48,giver=[[Franclorn Forgewright]],giver_loc=[[Franclorn Forjador]],giverType=[[NPC]],giverId=8888,ender=[[Franclorn Forgewright]],ender_loc=[[Franclorn Forjador]],enderType=[[NPC]],enderId=8888,rewardNextId=3802,poiX=-7714,poiY=-1134,wowhead=[[https://www.wowhead.com/wotlk/quest=3801]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, $N. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world. You are probably wondering why I am here and what it is that I want from you - both valid questions. I need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city.]],logDesc=[[Speak with Franclorn Forgewright at Forgewright's Tomb in Blackrock Mountain if you are interested in obtaining a key to the city major.]]}
DB[3802]={id=3802,zoneId=1584,name=[[Dark Iron Legacy]],name_loc=[[El legado de los Hierro Negro]],level=52,minLevel=48,giver=[[Franclorn Forgewright]],giver_loc=[[Franclorn Forjador]],giverType=[[NPC]],giverId=8888,ender=[[Monument of Franclorn Forgewright]],ender_loc=[[Monumento a Franclorn Forjador]],enderType=[[GO]],enderId=164689,prevId=3801,wowhead=[[https://www.wowhead.com/wotlk/quest=3802]],image=[[assets/images/quests/placeholder.png]],desc=[[You will find Fineous Darkvire beyond the Ring of Law, in the Hall of Crafting. Kill the miserable cur and recover Ironfel. Take Ironfel to the Shrine of Thaurissan and place the hammer in its rightful place: In the hands of the statue erected in my honor. When this is done, the compartment in which I stored the master key will open. More importantly, Ironfel will remain forever in my grasp. Should they make an attempt to remove the hammer; both the statue and hammer will shatter, lost forever.]],logDesc=[[Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright. ]],rewards={{id=11000,qty=1}}}
DB[3803]={id=3803,zoneId=1657,name=[[Morrowgrain to Darnassus]],name_loc=[[Mañagrana para Darnassus]],level=55,minLevel=47,giver=[[Mathrengyl Bearwalker]],giver_loc=[[Mathrengyl Garroso]],giverType=[[NPC]],giverId=4217,ender=[[Mathrengyl Bearwalker]],ender_loc=[[Mathrengyl Garroso]],enderType=[[NPC]],enderId=4217,prevId=3785,poiX=10179,poiY=2564,wowhead=[[https://www.wowhead.com/wotlk/quest=3803]],image=[[assets/images/quests/placeholder.png]],rewards={{id=11887,qty=1}}}
DB[3804]={id=3804,zoneId=1638,name=[[Morrowgrain to Thunder Bluff]],name_loc=[[Mañagrana para Cima del Trueno]],level=55,minLevel=47,giver=[[Bashana Runetotem]],giver_loc=[[Bashana Tótem de Runa]],giverType=[[NPC]],giverId=9087,ender=[[Bashana Runetotem]],ender_loc=[[Bashana Tótem de Runa]],enderType=[[NPC]],enderId=9087,prevId=3786,poiX=-1088,poiY=-225,wowhead=[[https://www.wowhead.com/wotlk/quest=3804]],image=[[assets/images/quests/placeholder.png]],rewards={{id=11887,qty=1}}}
DB[3821]={id=3821,zoneId=3,name=[[Dreadmaul Rock]],name_loc=[[Roca Machacamiedo]],level=52,minLevel=48,giver=[[Thal'trak Proudtusk]],giver_loc=[[Thal'trak Colmillo Orgulloso]],giverType=[[NPC]],giverId=9082,ender=[[Sha'ni Proudtusk]],ender_loc=[[Sha'ni Colmorgullo]],enderType=[[NPC]],enderId=9136,rewardNextId=3822,poiX=-7917,poiY=-2610,wowhead=[[https://www.wowhead.com/wotlk/quest=3821]],image=[[assets/images/quests/placeholder.png]],desc=[[Sha'ni was sent to investigate reports of strange ritualistic activity coming from the Firegut ogres of the Burning Steppes over three weeks ago. Goretooth tells me that he hasn't heard from anyone in that platoon and that it's best that I move on and focus on the task at hand. Can you believe it? That's my wife! I can't leave my post, $N, but I must know what became of Sha'ni. Travel to the Burning Steppes and search for her.]],logDesc=[[Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk.]]}
DB[3822]={id=3822,zoneId=46,name=[[Krom'Grul]],name_loc=[[Krom'Grul]],level=53,minLevel=48,giver=[[Sha'ni Proudtusk]],giver_loc=[[Sha'ni Colmorgullo]],giverType=[[NPC]],giverId=9136,ender=[[Thal'trak Proudtusk]],ender_loc=[[Thal'trak Colmillo Orgulloso]],enderType=[[NPC]],enderId=9082,prevId=3821,poiX=-6687,poiY=-2163,wowhead=[[https://www.wowhead.com/wotlk/quest=3822]],image=[[assets/images/quests/placeholder.png]],desc=[[My whole platoon was captured, $N. All were slain - except me. Their leader, Krom'Grul, wanted to save me for some sort of ritual. I was chained to this altar and brutalized by the beast. My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger. I had never seen such savagery! Find Krom'Grul and kill him! Take my ring back to Thal'trak. And $N, tell him that we will meet again... in another life.]],logDesc=[[Recover Sha'ni's Nose-Ring from Krom'Grul and return it to Thal'trak in Kargath. Search the various caves and mines in Dreadmaul Rock. ]],rewards={{id=11869,qty=1}}}
DB[3823]={id=3823,zoneId=46,name=[[Extinguish the Firegut]],name_loc=[[El exterminio de los Pirontraña]],level=52,minLevel=48,giver=[[Oralius]],giverType=[[NPC]],giverId=9177,ender=[[Oralius]],enderType=[[NPC]],enderId=9177,rewardNextId=3824,poiX=-7951,poiY=-2816,wowhead=[[https://www.wowhead.com/wotlk/quest=3823]],image=[[assets/images/quests/placeholder.png]],desc=[[We must strike at our enemies before they strike at us! I'll make this brief, soldier. The Firegut ogres of the Burning Steppes are allies of the Blackrock orcs. They work closely with those vile orcs, keeping the mineral rich Dreadmaul Rock guarded and the supply lines open at all times. Leave your mark, $N. Cripple their forces and return to me when the job is done. <Oralius grabs at the air and makes a choking motion.> I WILL KILL YOU, WINKY!]],logDesc=[[Slay 15 Firegut Ogre-Mages, 7 Firegut Ogres, and 7 Firegut Ogre Brutes.]]}
DB[3824]={id=3824,zoneId=46,name=[[Gor'tesh the Brute Lord]],name_loc=[[Gor'tesh, el Señor de los toscos]],level=53,minLevel=48,giver=[[Oralius]],giverType=[[NPC]],giverId=9177,ender=[[Oralius]],enderType=[[NPC]],enderId=9177,prevId=3823,rewardNextId=3825,poiX=-8111,poiY=-1418,wowhead=[[https://www.wowhead.com/wotlk/quest=3824]],image=[[assets/images/quests/placeholder.png]],desc=[[They're reeling I tell you! Our next strike must be decisive. The brute lord, Gor'tesh, must be slain. More importantly, his head must be returned to me so that I may prepare the third phase of our attack on the Firegut ogres. Be warned, soldier, Gor'tesh rules not from Dreadmaul Rock but from a Blackrock orc structure to the west of Dreadmaul Rock. Your orders, then, are simple. Find Gor'tesh and chop off his fat head. Return to me when the job is done. SHUT UP, WINKY!]],logDesc=[[Collect Gor'tesh's Lopped Off Head. ]]}
DB[3825]={id=3825,zoneId=46,name=[[Ogre Head On A Stick = Party]],name_loc=[[Una cabeza ogro empalada = FIESTA]],level=53,minLevel=48,giver=[[Oralius]],giverType=[[NPC]],giverId=9177,ender=[[Oralius]],enderType=[[NPC]],enderId=9177,prevId=3824,poiX=-7945,poiY=-2639,wowhead=[[https://www.wowhead.com/wotlk/quest=3825]],image=[[assets/images/quests/placeholder.png]],desc=[[Just one last thing you must do, soldier. I've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground. Once you do that, watch as those cowardly ogres run for their lives! After you've had your fun, come back to me and I'll reward you for all of your hard work. <Oralius seems to be losing touch with reality.>]],logDesc=[[Take Gor'tesh's Lopped Off Head and place it at the top of Dreadmaul Rock. Look for a soft dirt mound to plant the pike.]],choiceRewards={{id=11867,qty=1},{id=11868,qty=1}}}
DB[3841]={id=3841,zoneId=357,name=[[An Orphan Looking For a Home]],name_loc=[[Un huérfano que busca un hogar]],level=47,minLevel=38,giver=[[Kindal Moonweaver]],giver_loc=[[Kindal Tejeluna]],giverType=[[NPC]],giverId=7956,ender=[[Quentin]],enderType=[[NPC]],enderId=9238,prevId=2972,rewardNextId=3842,poiX=-6159,poiY=-3881,wowhead=[[https://www.wowhead.com/wotlk/quest=3841]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, hello, $N. I'm so glad to see you again. How was your trip to Darnassus? Well, you'll be happy to know that we've made quite a bit of progress while you've been gone. We even saved a nest full of eggs. Unfortunately, the mother died before we got to her. Say, would you want one for a pet? They look to hatch soon, so they'll need a good $Gfather:mother;. What do you say? If you're really interested, take one of the eggs to Quentin at the race tracks in Shimmering Flats. He'll tell you more.]],logDesc=[[Speak to Quentin in Thousand Needles.]]}
DB[3842]={id=3842,zoneId=357,name=[[A Short Incubation]],name_loc=[[Una corta incubación]],level=47,minLevel=38,giver=[[Quentin]],giverType=[[NPC]],giverId=9238,ender=[[Quentin]],enderType=[[NPC]],enderId=9238,prevId=3841,poiX=-6159,poiY=-3881,wowhead=[[https://www.wowhead.com/wotlk/quest=3842]],image=[[assets/images/quests/placeholder.png]],desc=[[The Moonweavers, huh? Most intriguing. I wish the sprite darters could truly appreciate what it means to have those two look after them. They are both quite capable. So, they gave you the egg as a gift. Well, then you should be responsible for it for as long as you desire. It appears it's almost ready to hatch, but we should ensure it's healthy and no damage has been done to it. I only need two elixirs of fortitude for a small spell to protect the egg. I have the rest of the components here with me.]],logDesc=[[Bring 2 Elixir of Fortitudes to Quentin in Thousand Needles.]]}
DB[3843]={id=3843,zoneId=357,name=[[The Newest Member of the Family]],name_loc=[[Un nuevo miembro en la familia]],level=47,minLevel=38,giver=[[Quentin]],giverType=[[NPC]],giverId=9238,ender=[[Agnar Beastamer]],ender_loc=[[Agnar Domabestias]],enderType=[[NPC]],enderId=9660,prevId=3842,rewardNextId=4297,poiX=347,poiY=-2120,wowhead=[[https://www.wowhead.com/wotlk/quest=3843]],image=[[assets/images/quests/placeholder.png]],desc=[[A magnificent specimen, $N. If this creature survives gestation, then it'll be a healthy pet indeed! There is one last thing I would suggest doing if you plan on following through with this--head to Aerie Peak in the Hinterlands. Speak to a dwarf there named Agnar Beastamer, he's a master animal handler and should be able to guide you in the final steps of incubation. But hurry, $N, this egg is fragile and will not last long without proper care.]],logDesc=[[Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies.]]}
DB[3844]={id=3844,zoneId=490,name=[[It's a Secret to Everybody]],name_loc=[[Un secreto bien guardado]],level=52,minLevel=47,giver=[[A Wrecked Raft]],giver_loc=[[Una balsa estropeada]],giverType=[[GO]],giverId=161505,ender=[[A Small Pack]],ender_loc=[[Un paquetito]],enderType=[[GO]],enderId=161504,rewardNextId=3845,poiX=-7670,poiY=-1802,wowhead=[[https://www.wowhead.com/wotlk/quest=3844]],image=[[assets/images/quests/placeholder.png]],desc=[[A destroyed raft rests along the shoreline. Considering this is only a small pond, it is not clear as to how it ended up here, although looking at the trees tells you that the water level may not be constant. Perhaps a little exploration in the area might uncover more clues...]],logDesc=[[Look around in the pond for a clue about who this wrecked raft may belong to.]]}
DB[3845]={id=3845,zoneId=490,name=[[It's a Secret to Everybody]],name_loc=[[Un secreto bien guardado]],level=52,minLevel=47,giver=[[A Small Pack]],giver_loc=[[Un paquetito]],giverType=[[GO]],giverId=161504,ender=[[Linken]],enderType=[[NPC]],enderId=8737,prevId=3844,rewardNextId=3908,poiX=-6166,poiY=-1119,wowhead=[[https://www.wowhead.com/wotlk/quest=3845]],image=[[assets/images/quests/placeholder.png]],desc=[[Grabbing onto it, you pull the pack back to the shore. Perhaps if you examine the items inside the pack, you might find out more about who it belongs to. There are a few stray travelers at Marshal's Refuge. Perhaps you might find out more there.]],logDesc=[[Examine the items inside the pack and bring them to their owner.]]}
DB[3861]={id=3861,name=[[CLUCK!]],name_loc=[[¡CLOQUEA!]],level=1,minLevel=1,giver=[[Chicken]],giver_loc=[[Pollo]],giverType=[[NPC]],giverId=620,ender=[[Chicken]],ender_loc=[[Pollo]],enderType=[[NPC]],enderId=620,poiX=-10129,poiY=1055,wowhead=[[https://www.wowhead.com/wotlk/quest=3861]],image=[[assets/images/quests/placeholder.png]],desc=[["Cluck... cluck... cluck... BACAW! Cluck... cluck... cluck." The chicken looks up at you and then starts to scratch its claws into the ground. You think it is spelling out a word, but you are not sure what it is. Could it be... S-A-L-D-E-A-N? Before you can ask, the chicken turns away and goes about its business.]],logDesc=[[Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed.]]}
DB[3881]={id=3881,zoneId=490,name=[[Expedition Salvation]],name_loc=[[Salvar a la expedición]],level=53,minLevel=48,giver=[[Williden Marshal]],giver_loc=[[Williden Marshal]],giverType=[[NPC]],giverId=9270,ender=[[Williden Marshal]],ender_loc=[[Williden Marshal]],enderType=[[NPC]],enderId=9270,poiX=-6868,poiY=-2003,wowhead=[[https://www.wowhead.com/wotlk/quest=3881]],image=[[assets/images/quests/placeholder.png]],desc=[[I don't know how you made it here, but you're a sight for sore eyes!  I'm Williden Marshal, and I lead a non-aligned expedition troupe.  Our latest and greatest endeavor has met with what seems like countless disasters, the most serious of which being that we underestimated the savagery of Un'Goro Crater! As we fled our base camps in the southwestern and northeastern parts of the crater, we left behind vital supplies.  You look like you're capable enough - can you help us by getting them back?]],logDesc=[[Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater.]]}
DB[3882]={id=3882,zoneId=490,name=[[Roll the Bones]],name_loc=[[Choca esos huesos]],level=51,minLevel=49,giver=[[Spark Nilminer]],giver_loc=[[Chispik Nilminer]],giverType=[[NPC]],giverId=9272,ender=[[Spark Nilminer]],ender_loc=[[Chispik Nilminer]],enderType=[[NPC]],enderId=9272,poiX=-6750,poiY=-751,wowhead=[[https://www.wowhead.com/wotlk/quest=3882]],image=[[assets/images/quests/placeholder.png]],desc=[[You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind. We were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.]],logDesc=[[Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater.]],choiceRewards={{id=11908,qty=1},{id=11909,qty=1}}}
DB[3883]={id=3883,zoneId=490,name=[[Alien Ecology]],name_loc=[[Ecología alienígena]],level=52,minLevel=48,giver=[[Hol'anyee Marshal]],giver_loc=[[Hol'anyee Marshal]],giverType=[[NPC]],giverId=9271,ender=[[Hol'anyee Marshal]],ender_loc=[[Hol'anyee Marshal]],enderType=[[NPC]],enderId=9271,poiX=-6145,poiY=-1091,wowhead=[[https://www.wowhead.com/wotlk/quest=3883]],image=[[assets/images/quests/placeholder.png]],desc=[[Just because we've suffered a setback doesn't mean that research must stop!  We were investigating the Gorishi insects in the southern part of the crater before winding up here.  Their presence is alien to the ecology of Un'Goro, and we want to find out why. In their hive network must be larval hatcheries.  You can identify these places by their hanging larval spawns.  Use this vial to take a sample of the hive wall near any of the hatcheries.  Bring it back to me for study, but be careful!]],logDesc=[[Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater.  Look for the chambers with the hanging larval spawns. Bring the Hive Wall Sample to Hol'anyee Marshal in Un'Goro Crater.]]}
DB[3884]={id=3884,zoneId=490,name=[[Williden's Journal]],name_loc=[[Diario de Williden]],level=50,minLevel=48,giverType=[[NPC]],ender=[[Williden Marshal]],ender_loc=[[Williden Marshal]],enderType=[[NPC]],enderId=9270,poiX=-6143,poiY=-1093,wowhead=[[https://www.wowhead.com/wotlk/quest=3884]],image=[[assets/images/quests/placeholder.png]],desc=[[You have uncovered a mangled journal.  Parts of it remain legible, with a Williden Marshal claiming ownership over the contents therein.  If the journal is accurate, then Williden may be found somewhere in the northern part of the Crater; according to the journal, he and his companions sought higher ground from the savage beasts of the Crater once their base camps were overrun.]],logDesc=[[Return the journal to Williden Marshal somewhere in Un'Goro Crater.]]}
DB[3901]={id=3901,zoneId=154,name=[[Rattling the Rattlecages]],name_loc=[[Sacudir esqueletos]],level=3,minLevel=1,giver=[[Shadow Priest Sarvis]],giver_loc=[[Sacerdote de las Sombras Sarvis]],giverType=[[NPC]],giverId=1569,ender=[[Shadow Priest Sarvis]],ender_loc=[[Sacerdote de las Sombras Sarvis]],enderType=[[NPC]],enderId=1569,prevId=364,poiX=1897,poiY=1473,wowhead=[[https://www.wowhead.com/wotlk/quest=3901]],image=[[assets/images/quests/placeholder.png]],desc=[[You've shown your potential to the Forsaken under normal circumstances $N - now let's see you under pressure. The Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far.  Again, thin their numbers and prove yourself to the Forsaken.  Do not tarry - when you are done, speak to me again.]],logDesc=[[Kill 8 Rattlecage Skeletons, and then return to Shadow Priest Sarvis in Deathknell when you are done.]],choiceRewards={{id=3274,qty=1},{id=11851,qty=1},{id=11852,qty=1}}}
DB[3902]={id=3902,zoneId=154,name=[[Scavenging Deathknell]],name_loc=[[Hurgar en Camposanto]],level=3,minLevel=2,giver=[[Deathguard Saltain]],giver_loc=[[Guardia de la Muerte Saltain]],giverType=[[NPC]],giverId=1740,ender=[[Deathguard Saltain]],ender_loc=[[Guardia de la Muerte Saltain]],enderType=[[NPC]],enderId=1740,prevId=376,poiX=1903,poiY=1488,wowhead=[[https://www.wowhead.com/wotlk/quest=3902]],image=[[assets/images/quests/placeholder.png]],desc=[[You there!  If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment.  Most likely, they'll be in stacks of boxes.  We expect more recruits to be rising soon, and unless we want them to stumble about naked we had better get to scavenging! Well get to work, you miserable bag of bones!  I'm not going to reward those without some hustle.]],logDesc=[[Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.]],choiceRewards={{id=11848,qty=1},{id=11849,qty=1},{id=11850,qty=1}}}
DB[3903]={id=3903,zoneId=9,name=[[Milly Osworth]],name_loc=[[Milly Osworth]],level=4,minLevel=2,giver=[[Deputy Willem]],giver_loc=[[Ayudante de alguacil Willem]],giverType=[[NPC]],giverId=823,ender=[[Milly Osworth]],enderType=[[NPC]],enderId=9296,prevId=33,rewardNextId=3904,poiX=-8850,poiY=-224,wowhead=[[https://www.wowhead.com/wotlk/quest=3903]],image=[[assets/images/quests/placeholder.png]],desc=[[You've shown yourself a dependable $c, $N.  Dependable, and not afraid to get your hands dirty, eh? I have a friend, Milly Osworth, who's in some trouble.  She's over with her wagon on the other side of the abbey, near the stable.  I'm sure she could use a pair of hands like yours.]],logDesc=[[Speak with Milly Osworth.]]}
DB[3904]={id=3904,zoneId=9,name=[[Milly's Harvest]],name_loc=[[La cosecha de Milly]],level=4,minLevel=2,giver=[[Milly Osworth]],giverType=[[NPC]],giverId=9296,ender=[[Milly Osworth]],enderType=[[NPC]],enderId=9296,prevId=3903,poiX=-9075,poiY=-380,wowhead=[[https://www.wowhead.com/wotlk/quest=3904]],image=[[assets/images/quests/placeholder.png]],desc=[[A gang of brigands, the Defias, moved into the Northshire Vineyards while I was harvesting!  I reported it to the Northshire guards and they assured me they'd take care of things, but... I'm afraid for my crop of grapes!  If the Defias don't steal them then I fear our guards will trample them when they chase away the thugs. Please, you must help me!  I gathered most of my grapes into buckets, but I left them in the vineyards to the southeast. Bring me those buckets!  Save my harvest!]],logDesc=[[Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey.]]}
DB[3905]={id=3905,zoneId=9,name=[[Grape Manifest]],name_loc=[[Informe de la vendimia]],level=4,minLevel=2,giver=[[Milly Osworth]],giverType=[[NPC]],giverId=9296,ender=[[Brother Neals]],ender_loc=[[Hermano Neals]],enderType=[[NPC]],enderId=952,prevId=3904,poiX=-8902,poiY=-182,wowhead=[[https://www.wowhead.com/wotlk/quest=3905]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that my crop is saved, take this Grape Manifest to Brother Neals.  He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes. You'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine.]],logDesc=[[Bring the Grape Manifest to Brother Neals in Northshire Abbey.]],choiceRewards={{id=11475,qty=1},{id=2690,qty=1}}}
DB[3906]={id=3906,zoneId=25,name=[[Disharmony of Flame]],name_loc=[[La discordia de las llamas]],level=52,minLevel=48,giver=[[Thunderheart]],giver_loc=[[Corazón Atronador]],giverType=[[NPC]],giverId=9084,ender=[[Thunderheart]],ender_loc=[[Corazón Atronador]],enderType=[[NPC]],enderId=9084,rewardNextId=3907,poiX=-7292,poiY=-891,wowhead=[[https://www.wowhead.com/wotlk/quest=3906]],image=[[assets/images/quests/placeholder.png]],desc=[[The elders have felt a disturbance amongst the elements. The Dark Iron dwarves have summoned a foul spirit into our world that threatens to plague our lands with an eternal draught. This disharmony of flame must be investigated. Travel to Blackrock Mountain, through the Chasm of Flame, into the quarry. It is there that you shall find this lord of fire: Overmaster Pyron. End the disruption and return to me.]],logDesc=[[Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment. ]]}
DB[3907]={id=3907,zoneId=1584,name=[[Disharmony of Fire]],name_loc=[[La discordia del fuego]],level=56,minLevel=48,giver=[[Thunderheart]],giver_loc=[[Corazón Atronador]],giverType=[[NPC]],giverId=9084,ender=[[Thunderheart]],ender_loc=[[Corazón Atronador]],enderType=[[NPC]],enderId=9084,prevId=3906,poiX=-6690,poiY=-2162,wowhead=[[https://www.wowhead.com/wotlk/quest=3907]],image=[[assets/images/quests/placeholder.png]],desc=[[I can taste the foulness in the air that surrounds you, $N. There is another, hidden in the depths of Blackrock, who does control this foulness. The wind and earth cry his name: Lord Incendius... but someone... something... commands this being. He is merely an emissary. Find him and discover where his master hides. Return to me when you have collected this information. ]],logDesc=[[Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart. ]],choiceRewards={{id=12113,qty=1},{id=12114,qty=1},{id=12112,qty=1},{id=12115,qty=1}}}
DB[3908]={id=3908,zoneId=490,name=[[It's a Secret to Everybody]],name_loc=[[Un secreto bien guardado]],level=52,minLevel=47,giver=[[Linken]],giverType=[[NPC]],giverId=8737,ender=[[Donova Snowden]],ender_loc=[[Donova Cubilnevado]],enderType=[[NPC]],enderId=9298,prevId=3845,poiX=6396,poiY=-2537,wowhead=[[https://www.wowhead.com/wotlk/quest=3908]],image=[[assets/images/quests/placeholder.png]],desc=[[You see, I have no idea how I ended up here. No one really knows -- it's a secret to everybody! I just can't seem to remember anything... These items you brought to me, though... I am remembering something. My sword. I am supposed to strengthen it somehow, but I'm really not sure why. Sorry I can't tell you more, but I just don't remember! Anyhoo, I do know where you can take it -- Donova Snowden in Winterspring. You'll find her by the hot springs. She can temper the sword by the pools there.]],logDesc=[[Take Linken's Sword to Donova Snowden in Winterspring.]]}
DB[3909]={id=3909,zoneId=490,name=[[The Videre Elixir]],name_loc=[[El Elixir de Videre]],level=52,minLevel=47,giver=[[Donova Snowden]],giver_loc=[[Donova Cubilnevado]],giverType=[[NPC]],giverId=9298,ender=[[Donova Snowden]],ender_loc=[[Donova Cubilnevado]],enderType=[[NPC]],enderId=9298,prevId=3908,rewardNextId=3912,poiX=6396,poiY=-2537,wowhead=[[https://www.wowhead.com/wotlk/quest=3909]],image=[[assets/images/quests/placeholder.png]],desc=[[Now, what's this? Linken... FORGOT? Oh, I see... Lost his memory... Well, here is his sword. It's not complete, though. I know of the one that can finish it, but... speaking with him may prove difficult. Listen, I know of someone that will be able to help you. It's too much to explain right now, but you must somehow acquire a Videre Elixir. The only one I know that can help you with that is Gregan Brewspewer. He's hard to track down, but last I knew he was camping in the wilds of Feralas.]],logDesc=[[Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring.]]}
DB[3912]={id=3912,zoneId=490,name=[[Meet at the Grave]],name_loc=[[Encuentro en la tumba]],level=52,minLevel=47,giver=[[Donova Snowden]],giver_loc=[[Donova Cubilnevado]],giverType=[[NPC]],giverId=9298,ender=[[Gaeriyan]],enderType=[[NPC]],enderId=9299,prevId=3909,rewardNextId=3913,poiX=-6949,poiY=-3943,wowhead=[[https://www.wowhead.com/wotlk/quest=3912]],image=[[assets/images/quests/placeholder.png]],desc=[[This elixir will allow you to speak with one that you would not normally even see... Take the Videre elixir, along with Linken's sword, to the graveyard just outside Gadgetzan in Tanaris. Once there, drink the potion. You may be quite surprised at the results, but do not be alarmed. In your "other" form, head due north until you reach the mountains. You'll find the one you need to speak with in one of the rocky crevices. His name is Gaeriyan. Remember, he will only speak to you in that form...]],logDesc=[[Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova's instructions to find Gaeriyan.]]}
DB[3913]={id=3913,zoneId=490,name=[[A Grave Situation]],name_loc=[[Una situación mortal]],level=52,minLevel=47,giver=[[Gaeriyan]],giverType=[[NPC]],giverId=9299,ender=[[A Conspicuous Gravestone]],ender_loc=[[Una lápida llamativa]],enderType=[[GO]],enderId=148504,prevId=3912,rewardNextId=3914,poiX=-7212,poiY=-3932,wowhead=[[https://www.wowhead.com/wotlk/quest=3913]],image=[[assets/images/quests/placeholder.png]],desc=[[If you return to the graveyard, $N, you will find a gravestone there... Not just any gravestone; this one will stand out from the others. Secrets lie within it. Push on the stone, and you will learn of these secrets...]],logDesc=[[Resurrect, then look for the gravestone that Gaeriyan told you to find.]]}
DB[3914]={id=3914,zoneId=490,name=[[Linken's Sword]],name_loc=[[La Espada de Linken]],level=52,minLevel=47,giver=[[A Conspicuous Gravestone]],giver_loc=[[Una lápida llamativa]],giverType=[[GO]],giverId=148504,ender=[[Linken]],enderType=[[NPC]],enderId=8737,prevId=3913,rewardNextId=3941,poiX=-6166,poiY=-1119,wowhead=[[https://www.wowhead.com/wotlk/quest=3914]],image=[[assets/images/quests/placeholder.png]],desc=[[After a strong flash of light, you are able to pick up the sword again. It has been transformed!]],logDesc=[[Deliver Linken's Superior Sword to Linken in Un'Goro Crater.]]}
DB[3921]={id=3921,zoneId=17,name=[[Wenikee Boltbucket]],name_loc=[[Wenikee Tuercasmil]],level=14,minLevel=10,giver=[[Sputtervalve]],giver_loc=[[Petardol]],giverType=[[NPC]],giverId=3442,ender=[[Wenikee Boltbucket]],ender_loc=[[Wenikee Tuercasmil]],enderType=[[NPC]],enderId=9316,prevId=902,rewardNextId=3922,poiX=858,poiY=-2348,wowhead=[[https://www.wowhead.com/wotlk/quest=3921]],image=[[assets/images/quests/placeholder.png]],desc=[[I think I might have broken that Samophlange.  That's not good, because I already told some colleagues in Undermine about it and they were very intrigued.  We must find a way to fix it! Take the broken samophlange to Wenikee Boltbucket, just south of Mor'shan Rampart, the horde outpost between the Barrens and Ashenvale.  She is very clever and inquisitive.  If you show her the samophlange I bet she'd jump at the chance to fix it.]],logDesc=[[Bring the Broken Samophlange to Wenikee Boltbucket.]]}
DB[3922]={id=3922,zoneId=17,name=[[Nugget Slugs]],name_loc=[[Engranajes]],level=15,minLevel=10,giver=[[Wenikee Boltbucket]],giver_loc=[[Wenikee Tuercasmil]],giverType=[[NPC]],giverId=9316,ender=[[Wenikee Boltbucket]],ender_loc=[[Wenikee Tuercasmil]],enderType=[[NPC]],enderId=9316,prevId=3921,poiX=1127,poiY=-3185,wowhead=[[https://www.wowhead.com/wotlk/quest=3922]],image=[[assets/images/quests/placeholder.png]],desc=[[I want to fix this samophlange, but to do that I'm going to need some supplies.  I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead. The closest place to get them is the Sludge Fen to the east.  The Venture Company usually keeps them in their tool buckets.  Go to the Sludge Fen and look in the tool buckets you find there, then return to me when you've gathered enough nugget slugs.]],logDesc=[[Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens.]]}
DB[3923]={id=3923,zoneId=17,name=[[Rilli Greasygob]],name_loc=[[Rilli Gapegajoso]],level=18,minLevel=10,giver=[[Wenikee Boltbucket]],giver_loc=[[Wenikee Tuercasmil]],giverType=[[NPC]],giverId=9316,ender=[[Rilli Greasygob]],ender_loc=[[Rilli Gapegajoso]],enderType=[[NPC]],enderId=9317,prevId=3922,rewardNextId=3924,poiX=2046,poiY=-4754,wowhead=[[https://www.wowhead.com/wotlk/quest=3923]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, that didn't work.  I put some extra gauges on the samophlange to measure its structural integrity, and they read the integrity at an all-time low.  I could add some more dials and maybe a lever or two to try and fix it, but... I think that might make things even worse. You should take the samophlange to Rilli Greasygob.  He used to work for the Venture Company -- if anyone knows how to fix it, it's Rilli. You can find him at Nogg's Machine Shop in Orgrimmar, in the Valley of Honor.]],logDesc=[[Bring the Broken and Battered Samophlange to Rilli Greasygob in Orgrimmar.]]}
DB[3924]={id=3924,zoneId=17,name=[[Samophlange Manual]],name_loc=[[El manual del churumbele]],level=19,minLevel=10,giver=[[Rilli Greasygob]],giver_loc=[[Rilli Gapegajoso]],giverType=[[NPC]],giverId=9317,ender=[[Rilli Greasygob]],ender_loc=[[Rilli Gapegajoso]],enderType=[[NPC]],enderId=9317,prevId=3923,poiX=1334,poiY=-3456,wowhead=[[https://www.wowhead.com/wotlk/quest=3924]],image=[[assets/images/quests/placeholder.png]],desc=[[I think I can fix the samophlange, but I'm going to need the user's manual first.  When I was in the Venture Company I had a rival, Boss Copperplug, who hoarded the secrets of the samophlange, giving out small bits of knowledge on the device to those he trusted.  I wasn't one of the trusted few... Boss Copperplug used to stay at the Boulder Lode Mine in northeastern Barrens.  Get the manual from him, and if he's given pages from it to anyone, you'll have to collect them too.]],logDesc=[[Bring the Samophlange Manual to Rilli Greasygob in Orgrimmar.]],choiceRewards={{id=11855,qty=1},{id=11854,qty=1}}}
DB[3941]={id=3941,zoneId=490,name=[[A Gnome's Assistance]],name_loc=[[La ayuda de una gnoma]],level=52,minLevel=47,giver=[[Linken]],giverType=[[NPC]],giverId=8737,ender=[[J.D. Collie]],ender_loc=[[J.D. Collie]],enderType=[[NPC]],enderId=9117,prevId=3914,poiX=-6033,poiY=-1018,wowhead=[[https://www.wowhead.com/wotlk/quest=3941]],image=[[assets/images/quests/placeholder.png]],desc=[[Thinking... Thinking... I know I came here for something important... I have an idea, $N. In the cave over there is a gnome named J.D. that was very kind to me when I first arrived here. Perhaps in my disoriented state, I might have mentioned something to her. Why don't you go ask her if she knows anything? Oh, but be careful -- she's always messing with those crazy glowing crystals I've seen in the crater. I'm not quite sure what she's up to in there!]],logDesc=[[Find J.D. Collie in the cave at Marshal's Refuge.]]}
DB[3942]={id=3942,zoneId=490,name=[[Linken's Memory]],name_loc=[[Recuerdos de Linken]],level=54,minLevel=47,giver=[[J.D. Collie]],giver_loc=[[J.D. Collie]],giverType=[[NPC]],giverId=9117,ender=[[Eridan Bluewind]],ender_loc=[[Eridan Vientoazul]],enderType=[[NPC]],enderId=9116,prevId=3941,rewardNextId=4084,poiX=4009,poiY=-1311,wowhead=[[https://www.wowhead.com/wotlk/quest=3942]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh... Linken? Yeah, he's a funny one. When he first got here, he was mumbling about all kinds of strange things. Probably got bumped on the head pretty hard, I imagine. Something he said kinda stuck with me though -- that he was making some sort of totem; said he had to talk to someone named Eridan Bluewind... in a place called Felwood, I think? I doubt he could tell you much now, though. If you want to know more, maybe you should look for Eridan yourself?]],logDesc=[[Find Eridan Bluewind in southern Felwood.]]}
DB[3961]={id=3961,zoneId=490,name=[[Linken's Adventure]],name_loc=[[La aventura de Linken]],level=54,minLevel=47,giver=[[J.D. Collie]],giver_loc=[[J.D. Collie]],giverType=[[NPC]],giverId=9117,ender=[[Linken]],enderType=[[NPC]],enderId=8737,prevId=4005,rewardNextId=3962,poiX=-6166,poiY=-1119,wowhead=[[https://www.wowhead.com/wotlk/quest=3961]],image=[[assets/images/quests/placeholder.png]],desc=[[To think all this time that the reason Linken came here was to rid us of Blazerunner... He seems like such an ordinary guy, but I did notice that he's not at all interested in any of my experiments or gadgets like most gnomes would be. He must be a true warrior at heart. Bring the totem to him. See if that helps him remember why he came here.]],logDesc=[[Take the Silver Totem of Aquementas to Linken in Marshal's Refuge.]]}
DB[3962]={id=3962,zoneId=490,name=[[It's Dangerous to Go Alone]],name_loc=[[Ir solo es peligroso]],level=56,minLevel=47,giver=[[Linken]],giverType=[[NPC]],giverId=8737,ender=[[Linken]],enderType=[[NPC]],enderId=8737,prevId=3961,poiX=-7183,poiY=-1295,wowhead=[[https://www.wowhead.com/wotlk/quest=3962]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero... You are. All that you have done -- you must finish this now, not me. Blazerunner guards an artifact called the Golden Flame. It provides power more vast than anything else I have ever known, and it is dangerous in the hands of one with an evil heart. You will want to bring others with you -- it's dangerous to go alone. Take this as my advice.]],logDesc=[[Travel to Fire Plume Ridge, south of Marshal's Refuge. Find Blazerunner and use the totem to remove his protective aura. Once he has been defeated, acquire the Golden Flame from the cave.]],rewards={{id=11905,qty=1}},choiceRewards={{id=11902,qty=1},{id=11904,qty=1}}}
DB[3981]={id=3981,zoneId=1584,name=[[Commander Gor'shak]],name_loc=[[Comandante Gor'shak]],level=52,minLevel=48,giver=[[Galamav the Marksman]],giver_loc=[[Galamav el Tirador]],giverType=[[NPC]],giverId=9081,ender=[[Commander Gor'shak]],ender_loc=[[Comandante Gor'shak]],enderType=[[NPC]],enderId=9020,prevId=3906,rewardNextId=3982,poiX=-7349,poiY=-1119,wowhead=[[https://www.wowhead.com/wotlk/quest=3981]],image=[[assets/images/quests/placeholder.png]],desc=[[Poor Gargal... didn't even see it coming. WHAM! The arrow landed dead center on the top of his head. He was no genius before but now... <Galamav grimaces.> When we dislodged the arrow, we noticed a rolled up note attached to the shaft. On the note was a crudely drawn picture of an orc behind bars with the signature of Commander Gor'shak attached. If he's still alive in the Depths, you'll have to find him. A trap you say? Well no kidding, numb hooves! That's why you're going! ]],logDesc=[[Find Commander Gor'shak in Blackrock Depths. You recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.]]}
DB[3982]={id=3982,zoneId=1584,name=[[What Is Going On?]],name_loc=[[¿Qué pasa?]],level=54,minLevel=48,giver=[[Commander Gor'shak]],giver_loc=[[Comandante Gor'shak]],giverType=[[NPC]],giverId=9020,ender=[[Commander Gor'shak]],ender_loc=[[Comandante Gor'shak]],enderType=[[NPC]],enderId=9020,prevId=3981,rewardNextId=4001,wowhead=[[https://www.wowhead.com/wotlk/quest=3982]],image=[[assets/images/quests/placeholder.png]],desc=[[I was sent here under the auspices of Thrall. Do you actually think these buffoons could capture me? I allowed myself to be captured so that I could gather intelligence. <Gor'shak whispers.> The Princess of Ironforge has been kidnapped by Emperor Thaurissan. Princess Bronzebeard is in this very city! I bet old Magni's heart almost stopped when he heard that news. <Gor'shak laughs.> Shhh! Do you hear that? Guards coming! DEFEND YOURSELF!]],logDesc=[[Defend Gor'shak.]]}
DB[4001]={id=4001,zoneId=1584,name=[[What Is Going On?]],name_loc=[[¿Qué pasa?]],level=54,minLevel=48,giver=[[Commander Gor'shak]],giver_loc=[[Comandante Gor'shak]],giverType=[[NPC]],giverId=9020,ender=[[Thrall]],ender_loc=[[Thrall]],enderType=[[NPC]],enderId=4949,prevId=3982,rewardNextId=4002,poiX=1920,poiY=-4124,wowhead=[[https://www.wowhead.com/wotlk/quest=4001]],image=[[assets/images/quests/placeholder.png]],desc=[[So far, my communication with the dwarf, Kharan, in the cell across the hall, has been limited. I have, however, managed to convince him that I, rather -we- mean him no harm. Go speak with him and gather as much information about the Princess and her captors as possible. Take that information back to the Warchief. Thrall does not want the Princess harmed, but instead, has some grand plan laid out, which includes her being safely returned to Ironforge. Kharan already knows all of this... Go! ]],logDesc=[[Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar. You recall Gor'shak mentioning that Kharan is being held in a cell nearby. ]]}
DB[4002]={id=4002,zoneId=1584,name=[[The Eastern Kingdoms]],name_loc=[[Los Reinos del Este]],level=54,minLevel=48,giver=[[Thrall]],giver_loc=[[Thrall]],giverType=[[NPC]],giverId=4949,ender=[[Thrall]],ender_loc=[[Thrall]],enderType=[[NPC]],enderId=4949,prevId=4001,rewardNextId=4003,poiX=1930,poiY=-4165,wowhead=[[https://www.wowhead.com/wotlk/quest=4002]],image=[[assets/images/quests/placeholder.png]],desc=[[You bring excellent information, $N. As Warchief, it is my duty to do what is best for the Horde. To ensure that the generations that come after us are not forced into a hopeless existence. The opportunity to shape our future alliances has fallen into our collective laps. A move to help the dwarves could greatly strengthen our relationships in the Eastern Kingdoms. This, then, is why you must not fail! Are you prepared?]],logDesc=[[Speak with Thrall if you are prepared to take on the mission he has planned.]]}
DB[4003]={id=4003,zoneId=1584,name=[[The Royal Rescue]],name_loc=[[El rescate real]],level=59,minLevel=48,giver=[[Thrall]],giver_loc=[[Thrall]],giverType=[[NPC]],giverId=4949,ender=[[Princess Moira Bronzebeard]],ender_loc=[[Princesa Moira Barbabronce]],enderType=[[NPC]],enderId=8929,prevId=4002,rewardNextId=4004,wowhead=[[https://www.wowhead.com/wotlk/quest=4003]],image=[[assets/images/quests/placeholder.png]],desc=[[This strike against the Dark Iron dwarves, if successful, will send a shockwave throughout their entire kingdom. Princess Bronzebeard is under the control of Emperor Thaurissan. To free her, you must kill the Emperor. Be warned, your task is doubly dangerous, as Bronzebeard will attack you without question while under the control of the Emperor. DO NOT HARM HER!]],logDesc=[[Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell.  ]]}
DB[4004]={id=4004,zoneId=1584,name=[[The Princess Saved?]],name_loc=[[¿Princesa salvada?]],level=60,minLevel=48,giver=[[Princess Moira Bronzebeard]],giver_loc=[[Princesa Moira Barbabronce]],giverType=[[NPC]],giverId=8929,ender=[[Thrall]],ender_loc=[[Thrall]],enderType=[[NPC]],enderId=4949,prevId=4003,poiX=1927,poiY=-4164,wowhead=[[https://www.wowhead.com/wotlk/quest=4004]],image=[[assets/images/quests/placeholder.png]],desc=[[You have slain my husband, $r! My child will be born into this world without a father. <Princess Moira points directly at you.> I assure you, this child will be the next ruler of the kingdom of Ironforge. You and your kind shall be hunted down until the end of days for this wrongful act. <You think that Princess Moira may be suffering from the residual effect of Thaurissan's spell.> Leave me be, $r. I am certain your warchief will be eager to hear the results of his meddling. ]],logDesc=[[Return to Thrall at Grommash Hold in Orgrimmar. ]],choiceRewards={{id=12544,qty=1},{id=12545,qty=1}}}
DB[4005]={id=4005,zoneId=490,name=[[Aquementas]],name_loc=[[Aquamentas]],level=54,minLevel=47,giver=[[Eridan Bluewind]],giver_loc=[[Eridan Vientoazul]],giverType=[[NPC]],giverId=9116,ender=[[J.D. Collie]],ender_loc=[[J.D. Collie]],enderType=[[NPC]],enderId=9117,prevId=4084,poiX=-6033,poiY=-1018,wowhead=[[https://www.wowhead.com/wotlk/quest=4005]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this bag of supplies with you to Tanaris. Travel to Lost Rigger Cove, and look for a circle of stones. The eastmost peninsula is the secret... From this circle only, read from the book of Aquor; summon the only creature that can transform the items you collected into a totem to fight Blazerunner. Aquementas will not be pleased to be awakened, but remember, you must remain in the circle for him to transform the items.]],logDesc=[[Take the Book of Aquor, the Silvery Claws, and the Irontree Heart to Tanaris. Use the Book of Aquor to summon Aquementas. After you have the completed totem, take it to J.D. Collie in Marshal's Refuge.]]}
DB[4021]={id=4021,zoneId=17,name=[[Counterattack!]],name_loc=[[¡Contraataca!]],level=20,minLevel=11,giver=[[Regthar Deathgate]],giver_loc=[[Regthar Portamorta]],giverType=[[NPC]],giverId=3389,ender=[[Regthar Deathgate]],ender_loc=[[Regthar Portamorta]],enderType=[[NPC]],enderId=3389,prevId=852,poiX=-307,poiY=-1972,wowhead=[[https://www.wowhead.com/wotlk/quest=4021]],image=[[assets/images/quests/placeholder.png]],desc=[[The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened.  I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance.  My latest report was that, even now, they move against these bunkers, from the west! Face the Kolkar invaders, and end their threat in the Barrens.  Kill them until their leader, Warlord Krom'zar, appears.  Defeat him and bring me a piece of his banner as proof. We're counting on you, $N.]],logDesc=[[Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads.]]}
DB[4022]={id=4022,zoneId=46,name=[[A Taste of Flame]],name_loc=[[Un sabor a llamarada]],level=54,minLevel=52,giver=[[Cyrus Therepentous]],giver_loc=[[Cyrus Therepentio]],giverType=[[NPC]],giverId=9459,ender=[[Cyrus Therepentous]],ender_loc=[[Cyrus Therepentio]],enderType=[[NPC]],enderId=9459,prevId=3481,nextId=4024,rewardNextId=4024,exGroup=4022,poiX=-7659,poiY=-2997,wowhead=[[https://www.wowhead.com/wotlk/quest=4022]],image=[[assets/images/quests/placeholder.png]],desc=[[The flight is aware of your work in the Searing Gorge. Show it to me, $r. The molt, imbecile.]],logDesc=[[Show Cyrus Therepentous the Black Dragonflight Molt you received from Kalaran Windblade. ]]}
DB[4023]={id=4023,zoneId=46,name=[[A Taste of Flame]],name_loc=[[Un sabor a llamarada]],level=54,minLevel=52,giver=[[Cyrus Therepentous]],giver_loc=[[Cyrus Therepentio]],giverType=[[NPC]],giverId=9459,ender=[[Cyrus Therepentous]],ender_loc=[[Cyrus Therepentio]],enderType=[[NPC]],enderId=9459,nextId=4024,rewardNextId=4024,exGroup=4022,poiX=-7659,poiY=-2997,wowhead=[[https://www.wowhead.com/wotlk/quest=4023]],image=[[assets/images/quests/placeholder.png]],desc=[[You seek out the Flight? Present to me proof of your worth, mortal.]],logDesc=[[Show Cyrus Therepentous proof of your worth. You have a feeling that Cyrus already knows that you are unworthy.]]}
DB[4024]={id=4024,zoneId=1584,name=[[A Taste of Flame]],name_loc=[[Un sabor a llamarada]],level=58,minLevel=52,giver=[[Cyrus Therepentous]],giver_loc=[[Cyrus Therepentio]],giverType=[[NPC]],giverId=9459,ender=[[Cyrus Therepentous]],ender_loc=[[Cyrus Therepentio]],enderType=[[NPC]],enderId=9459,prevId=4023,poiX=-7647,poiY=-3052,wowhead=[[https://www.wowhead.com/wotlk/quest=4024]],image=[[assets/images/quests/placeholder.png]],desc=[[I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave. Bael'Gar resides in the Depths of Blackrock: A being of pure flame, born of the fires of Ragnaros. Slay Bael'Gar and from his smoldering remains bring for me a piece of his inner fire. Use the molt on his remains to safely extract the inner flame. Succeed and be rewarded.]],logDesc=[[Travel to Blackrock Depths and slay Bael'Gar. You only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence. Return the Encased Fiery Essence to Cyrus Therepentous. ]],choiceRewards={{id=12066,qty=1},{id=12082,qty=1},{id=12083,qty=1}}}
DB[4041]={id=4041,zoneId=357,name=[[The Videre Elixir]],name_loc=[[El Elixir de Videre]],level=52,minLevel=47,giver=[[Gregan Brewspewer]],giver_loc=[[Gregan Vomitabrebaje]],giverType=[[NPC]],giverId=7775,ender=[[Gregan Brewspewer]],ender_loc=[[Gregan Vomitabrebaje]],enderType=[[NPC]],enderId=7775,prevId=-3909,poiX=-2838,poiY=2342,wowhead=[[https://www.wowhead.com/wotlk/quest=4041]],image=[[assets/images/quests/placeholder.png]],rewards={{id=11243,qty=3}}}
DB[4061]={id=4061,zoneId=46,name=[[The Rise of the Machines]],name_loc=[[La revuelta de las máquinas]],level=54,minLevel=52,giver=[[Hierophant Theodora Mulvadania]],giver_loc=[[Hierofante Theodora Mulvadania]],giverType=[[NPC]],giverId=9079,ender=[[Hierophant Theodora Mulvadania]],ender_loc=[[Hierofante Theodora Mulvadania]],enderType=[[NPC]],enderId=9079,rewardNextId=4062,poiX=-6682,poiY=-2154,wowhead=[[https://www.wowhead.com/wotlk/quest=4061]],image=[[assets/images/quests/placeholder.png]],desc=[[The machines made themselves known to us during our initial forays into the Searing Gorge. Upon further investigation we discovered that they were being imported from Burning Steppes, possibly Blackrock Depths. That is what we need you for, $N. Your first task is to venture to the Burning Steppes and recover elemental shards from the rock automatons and lesser rock creations of the region. Once you have collected a sufficient amount, return to me and I shall determine their source of origin. ]],logDesc=[[Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania. You recall Theodora mentioning the golems and elementals of that region as being a source for these shards.]]}
DB[4062]={id=4062,zoneId=3,name=[[The Rise of the Machines]],name_loc=[[La revuelta de las máquinas]],level=54,minLevel=52,giver=[[Hierophant Theodora Mulvadania]],giver_loc=[[Hierofante Theodora Mulvadania]],giverType=[[NPC]],giverId=9079,ender=[[Lotwil Veriatus]],enderType=[[NPC]],enderId=2921,prevId=4061,rewardNextId=4063,poiX=-6634,poiY=-2725,wowhead=[[https://www.wowhead.com/wotlk/quest=4062]],image=[[assets/images/quests/placeholder.png]],desc=[[G.L.A. Those are the 'initials' imprinted on the elemental shards. Below the initials are a rank marking of some sort. The machinations you destroyed in the Burning Steppes were of 'Rank IV.' I assume that this is a lowly rank. Take this shard sample to Lotwil Veriatus in the camp to the east. He is a scholar of some renown in the field of elemental sciences. He may be able to assist us in our search.]],logDesc=[[Take the Elemental Shard Sample to Lotwil Veriatus. You recall Theodora saying that Lotwil was stationed in a camp to the east. ]]}
DB[4063]={id=4063,zoneId=1584,name=[[The Rise of the Machines]],name_loc=[[La revuelta de las máquinas]],level=58,minLevel=52,giver=[[Lotwil Veriatus]],giverType=[[NPC]],giverId=2921,ender=[[Lotwil Veriatus]],enderType=[[NPC]],enderId=2921,prevId=4062,poiX=-6634,poiY=-2725,wowhead=[[https://www.wowhead.com/wotlk/quest=4063]],image=[[assets/images/quests/placeholder.png]],desc=[[This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him. He was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs. It seems that the wicked always find a way to escape justice. If this is Argelmach's handiwork then he must be destroyed. I will need samplings of his latest creations. With the proper samples, I may be able to stop this uprising. The creations guard Argelmach in Blackrock Depths.]],logDesc=[[Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.]],choiceRewards={{id=12109,qty=1},{id=12110,qty=1},{id=12108,qty=1},{id=12111,qty=1}}}
DB[4081]={id=4081,zoneId=1584,name=[[KILL ON SIGHT: Dark Iron Dwarves]],name_loc=[[MATAR INMEDIATAMENTE: enanos Hierro Negro]],level=52,minLevel=48,giver=[[WANTED]],giver_loc=[[SE BUSCA]],giverType=[[GO]],giverId=164867,ender=[[Warlord Goretooth]],ender_loc=[[Señor de la guerra Dientegore]],enderType=[[NPC]],enderId=9077,poiX=-6678,poiY=-2224,wowhead=[[https://www.wowhead.com/wotlk/quest=4081]],image=[[assets/images/quests/placeholder.png]],desc=[[By order of Warlord Goretooth, commander of the Kargath Expeditionary Force: Any and all of General Angerforge's forces within Blackrock Depths must be annihilated. Angerforge's men are ruthless killers, responsible for the mass murder of the 109th division of the Kargath Expeditionary Force. Heroes are warned to exercise extreme caution when confronting these brutes. Any person who destroys the first line of General Angerforge's forces in Blackrock Depths shall receive a tribute.]],logDesc=[[Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete. ]]}
DB[4082]={id=4082,zoneId=1584,name=[[KILL ON SIGHT: High Ranking Dark Iron Officials]],name_loc=[[MATAR INMEDIATAMENTE: oficiales Hierro Negro de alto rango]],level=54,minLevel=48,giver=[[KILL ON SIGHT]],giver_loc=[[MATAR INMEDIATAMENTE]],giverType=[[GO]],giverId=164868,ender=[[Warlord Goretooth]],ender_loc=[[Señor de la guerra Dientegore]],enderType=[[NPC]],enderId=9077,prevId=4081,nextId=4122,poiX=-6678,poiY=-2224,wowhead=[[https://www.wowhead.com/wotlk/quest=4082]],image=[[assets/images/quests/placeholder.png]],desc=[[By order of Warlord Goretooth, commander of the Kargath Expeditionary Force: Head of the K.E.F. reconnaissance division, Grandmaster Lexlort, has returned with news of the whereabouts of high ranking Dark Iron officials. Through locked gate, near the heart of the city, they train their forces to snuff out our men. Travel to Blackrock Depths and destroy them! Completion of this mission will result in a tribute. ]],logDesc=[[Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.]]}
DB[4083]={id=4083,zoneId=1584,name=[[The Spectral Chalice]],name_loc=[[El cáliz espectral]],level=55,minLevel=40,giver=[[Spectral Chalice]],giver_loc=[[Cáliz espectral]],giverType=[[GO]],giverId=164869,ender=[[Spectral Chalice]],ender_loc=[[Cáliz espectral]],enderType=[[GO]],enderId=164869,wowhead=[[https://www.wowhead.com/wotlk/quest=4083]],image=[[assets/images/quests/placeholder.png]]}
DB[4084]={id=4084,zoneId=490,name=[[Silver Heart]],name_loc=[[Corazón de plata]],level=54,minLevel=47,giver=[[Eridan Bluewind]],giver_loc=[[Eridan Vientoazul]],giverType=[[NPC]],giverId=9116,ender=[[Eridan Bluewind]],ender_loc=[[Eridan Vientoazul]],enderType=[[NPC]],enderId=9116,prevId=3942,rewardNextId=4005,poiX=6551,poiY=-1466,wowhead=[[https://www.wowhead.com/wotlk/quest=4084]],image=[[assets/images/quests/placeholder.png]],desc=[[I do not know the one you speak of, $N. But worry not; if your friend was on a journey to find me, I do know what it was he desired. In the heart of Un'Goro Crater dwells evil of the purest form. This evil takes the shape of an elemental called Blazerunner... protected by an aura that none can dispel... None... except those with enough power to do so. I can teach you of this power, $N. First, do as I ask. Collect 11 Silvery Claws and 1 Irontree Heart from the creatures in Felwood, then return.]],logDesc=[[Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood.]]}
DB[4101]={id=4101,zoneId=361,name=[[Cleansing Felwood]],name_loc=[[Limpiar Frondavil]],level=55,minLevel=48,giver=[[Arathandris Silversky]],giver_loc=[[Arathandris Cielargento]],giverType=[[NPC]],giverId=9528,ender=[[Arathandris Silversky]],ender_loc=[[Arathandris Cielargento]],enderType=[[NPC]],enderId=9528,poiX=6312,poiY=-1786,wowhead=[[https://www.wowhead.com/wotlk/quest=4101]],image=[[assets/images/quests/placeholder.png]],desc=[[Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle! To the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.]],logDesc=[[Bring 15 Blood Amber to Arathandris Silversky in Felwood.]]}
DB[4102]={id=4102,zoneId=361,name=[[Cleansing Felwood]],name_loc=[[Limpiar Frondavil]],level=55,minLevel=48,giver=[[Maybess Riverbreeze]],giver_loc=[[Maybess Brisafluvial]],giverType=[[NPC]],giverId=9529,ender=[[Maybess Riverbreeze]],ender_loc=[[Maybess Brisafluvial]],enderType=[[NPC]],enderId=9529,poiX=6312,poiY=-1786,wowhead=[[https://www.wowhead.com/wotlk/quest=4102]],image=[[assets/images/quests/placeholder.png]],desc=[[Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle! To the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.]],logDesc=[[Bring 15 Blood Amber to Maybess Riverbreeze in Felwood.]]}
