DB[4119]={id=4119,zoneId=361,name=[[Corrupted Night Dragon]],name_loc=[[Dragón nocturno corrupto]],level=55,minLevel=48,giver=[[Corrupted Night Dragon]],giver_loc=[[Dragón nocturno corrupto]],giverType=[[GO]],giverId=164885,ender=[[Corrupted Night Dragon]],ender_loc=[[Dragón nocturno corrupto]],enderType=[[GO]],enderId=164885,poiX=4133,poiY=-700,wowhead=[[https://www.wowhead.com/wotlk/quest=4119]],image=[[assets/images/quests/placeholder.png]]}
DB[4120]={id=4120,zoneId=357,name=[[The Strength of Corruption]],name_loc=[[La fuerza de la corrupción]],level=52,minLevel=47,giver=[[Talo Thornhoof]],giver_loc=[[Talo Pezuñahendida]],giverType=[[NPC]],giverId=7776,ender=[[Talo Thornhoof]],ender_loc=[[Talo Pezuñahendida]],enderType=[[NPC]],enderId=7776,poiX=6352,poiY=-2084,wowhead=[[https://www.wowhead.com/wotlk/quest=4120]],image=[[assets/images/quests/placeholder.png]],desc=[[Being a hunter, I strive to emulate the strengths I see in my opponents. It is possible to turn the battle in your favor by simply knowing your enemy well, $N. In a place called Felwood, north of Ashenvale, the creatures have been tainted by a substance called fel. The bears and wolves have been driven mad by it, but I believe that they have also grown even stronger as well. Go, $N. Travel to Felwood and face these beasts. Learn for yourself if they are truly as strong as I believe.]],logDesc=[[Talo Thornhoof at Camp Mojache in Feralas wants you to kill 12 Angerclaw Grizzlies and 12 Felpaw Ravagers in Felwood.]]}
DB[4121]={id=4121,zoneId=1584,name=[[Precarious Predicament]],name_loc=[[¡Estás en un aprieto!]],level=58,minLevel=52,giver=[[Grark Lorkrub]],giverType=[[NPC]],giverId=9520,ender=[[Lexlort]],ender_loc=[[Lexlort]],enderType=[[NPC]],enderId=9080,prevId=4122,poiX=-6679,poiY=-2225,wowhead=[[https://www.wowhead.com/wotlk/quest=4121]],image=[[assets/images/quests/placeholder.png]],desc=[[Do you truly believe that you will make it to your rendezvous point with me in custody? You actually expected to break into a heavily fortified Blackrock fortress to capture a prized asset of theirs without alerting anyone or anything to your presence? You will be destroyed! ]],logDesc=[[Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge. You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody. You will also be required to hand over your Thorium Shackles to Lexlort.]]}
DB[4122]={id=4122,zoneId=1584,name=[[Grark Lorkrub]],name_loc=[[Grark Lorkrub]],level=58,minLevel=52,giver=[[Lexlort]],giver_loc=[[Lexlort]],giverType=[[NPC]],giverId=9080,ender=[[Grark Lorkrub]],enderType=[[NPC]],enderId=9520,prevId=4082,poiX=-7700,poiY=-1444,wowhead=[[https://www.wowhead.com/wotlk/quest=4122]],image=[[assets/images/quests/placeholder.png]],desc=[[I tracked him across the Searing Gorge, through the mountain, and into the Burning Steppes. That traitor was caught red-handed giving the Blackrock orcs vital information about our day to day operations. I'm speaking of Grark Lorkrub. He now sits in the Burning Steppes, safely under their protection - or so he thinks. Take these shackles, $N. Find Grark, place the shackles on him and lead him through Blackrock Mountain. Do this and a tribute is yours. ]],logDesc=[[Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress. When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody. ]]}
DB[4123]={id=4123,zoneId=1584,name=[[The Heart of the Mountain]],name_loc=[[El corazón de la montaña]],level=55,minLevel=50,giver=[[Maxwort Uberglint]],giver_loc=[[Maxwort Suprandor]],giverType=[[NPC]],giverId=9536,ender=[[Maxwort Uberglint]],ender_loc=[[Maxwort Suprandor]],enderType=[[NPC]],enderId=9536,poiX=-7498,poiY=-2175,wowhead=[[https://www.wowhead.com/wotlk/quest=4123]],image=[[assets/images/quests/placeholder.png]],desc=[[For years I have sought a certain gem.  It is called the Heart of the Mountain and it's the size of your fist!  The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it. So I must resort to force. Fight your way to the Lower Vault of Blackrock Depths, breach its secret safe and gain the Heart.  To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault! Good luck.]],logDesc=[[Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.]]}
DB[4124]={id=4124,zoneId=357,name=[[The Missing Courier]],name_loc=[[El mensajero desaparecido]],level=43,minLevel=40,giver=[[Latronicus Moonspear]],giver_loc=[[Latronicus Lanzaluna]],giverType=[[NPC]],giverId=7877,ender=[[Ginro Hearthkindle]],ender_loc=[[Ginro Mechogar]],enderType=[[NPC]],enderId=7880,rewardNextId=4125,poiX=-4458,poiY=3227,wowhead=[[https://www.wowhead.com/wotlk/quest=4124]],image=[[assets/images/quests/placeholder.png]],desc=[[An associate of mine, Ginro Hearthkindle, is looking for assistance concerning the location of a courier and the parcels he was carrying.  It has been a week or so since the courier went missing; our own searches have proved fruitless, and we're at an impasse.  Unfortunately, I have had to declare the courier as missing in action. If you have the time and resources to spare, please speak with Ginro.  He should be here in the Stronghold - perhaps in his quarters.]],logDesc=[[Speak with Ginro Hearthkindle in Feathermoon Stronghold.]]}
DB[4125]={id=4125,zoneId=357,name=[[The Missing Courier]],name_loc=[[El mensajero desaparecido]],level=43,minLevel=40,giver=[[Ginro Hearthkindle]],giver_loc=[[Ginro Mechogar]],giverType=[[NPC]],giverId=7880,ender=[[Wrecked Row Boat]],ender_loc=[[Restos de un bote de remos]],enderType=[[GO]],enderId=164909,prevId=4124,rewardNextId=4127,poiX=-5377,poiY=2283,wowhead=[[https://www.wowhead.com/wotlk/quest=4125]],image=[[assets/images/quests/placeholder.png]],desc=[[It's been about a week since Raschal, the courier, set out for Thalanaar.  He knows Feralas well; he's been with us since General Feathermoon led the expeditionary forces here.  I know his plan was to take a row boat down the coast and try and traverse across southern Feralas to avoid the Horde camp. I couldn't find his boat, but maybe you can.  Maybe it is hidden, or maybe it was sunk.  Regardless, it might hold a clue as to where he is.  If you uncover something, please let me know.]],logDesc=[[Locate the courier's boat somewhere along the coast of Feralas.]]}
DB[4126]={id=4126,zoneId=1584,name=[[Hurley Blackbreath]],name_loc=[[Hurley Negrálito]],level=55,minLevel=50,giver=[[Ragnar Thunderbrew]],giver_loc=[[Ragnar Cebatruenos]],giverType=[[NPC]],giverId=1267,ender=[[Ragnar Thunderbrew]],ender_loc=[[Ragnar Cebatruenos]],enderType=[[NPC]],enderId=1267,prevId=4128,poiX=-5596,poiY=-504,wowhead=[[https://www.wowhead.com/wotlk/quest=4126]],image=[[assets/images/quests/placeholder.png]],desc=[[The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager.  The villains!  They don't deserve such a fine brew! $N, I have a tough task for you.  Go to the Blackrock Depths in the Burning Steppes, destroy any kegs of Thunderbrew Lager you find, and bring back our recipe for Thunderbrew Lager! Please, get that recipe back, even if you have to turn Blackrock Depths upside down to do it!]],logDesc=[[Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.]],rewards={{id=12003,qty=10}},choiceRewards={{id=11964,qty=1},{id=12000,qty=1}}}
DB[4127]={id=4127,zoneId=357,name=[[Boat Wreckage]],name_loc=[[Los restos del bote]],level=44,minLevel=40,giver=[[Wrecked Row Boat]],giver_loc=[[Restos de un bote de remos]],giverType=[[GO]],giverId=164909,ender=[[Ginro Hearthkindle]],ender_loc=[[Ginro Mechogar]],enderType=[[NPC]],enderId=7880,prevId=4125,rewardNextId=4129,poiX=-4458,poiY=3227,wowhead=[[https://www.wowhead.com/wotlk/quest=4127]],image=[[assets/images/quests/placeholder.png]],desc=[[Running your hand along the mud, your fingers graze the handle of a knife.  It looks well cared for, and it might be safe to assume that whoever was on the boat might have lost it.  Perhaps the large chunk of the missing boat might have something to do with the loss. You grab the knife, remembering that Ginro Hearthkindle in the Feathermoon Stronghold instructed you to return to him with any found clues.  You get the feeling, however, that you are not quite alone in the water...]],logDesc=[[Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.]]}
DB[4128]={id=4128,zoneId=1584,name=[[Ragnar Thunderbrew]],name_loc=[[Ragnar Cebatruenos]],level=55,minLevel=50,giver=[[Enohar Thunderbrew]],giver_loc=[[Enohar Cebatruenos]],giverType=[[NPC]],giverId=9540,ender=[[Ragnar Thunderbrew]],ender_loc=[[Ragnar Cebatruenos]],enderType=[[NPC]],enderId=1267,rewardNextId=4126,poiX=-5596,poiY=-504,wowhead=[[https://www.wowhead.com/wotlk/quest=4128]],image=[[assets/images/quests/placeholder.png]],desc=[[Ho, $n.  I heard that Ragnar Thunderbrew is steaming mad about someone stealing his ale.  He's looking for stalwart adventurers, and willing to pay plenty. Talk to Ragnar if you're interested.  He's at the Thunderbrew Distillery in Kharanos, in Dun Morogh.]],logDesc=[[Speak with Ragnar Thunderbrew.]]}
DB[4129]={id=4129,zoneId=357,name=[[The Knife Revealed]],name_loc=[[La revelación del cuchillo]],level=44,minLevel=40,giver=[[Ginro Hearthkindle]],giver_loc=[[Ginro Mechogar]],giverType=[[NPC]],giverId=7880,ender=[[Quintis Jonespyre]],ender_loc=[[Quintis Jonguja]],enderType=[[NPC]],enderId=7879,prevId=4127,poiX=-4396,poiY=3187,wowhead=[[https://www.wowhead.com/wotlk/quest=4129]],image=[[assets/images/quests/placeholder.png]],desc=[[The Stronghold's resident druid, Quintis Jonespyre, has some... unusual skills.  One of them involves psychometry - the ability to reveal an item's history by touch.  Don't ask me how he does it; I chalk it up to magic I do not and choose not to understand.  I do know, however, two things: one, I've seen it work and two, the bum owes me. Take the knife up to Quint in his little tree-house here, and tell him for me that his Kalimdor Hold 'Em debt will be paid if he works his mojo on that knife.]],logDesc=[[Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.]]}
DB[4130]={id=4130,zoneId=357,name=[[Psychometric Reading]],name_loc=[[Lectura psicométrica]],level=44,minLevel=40,giver=[[Quintis Jonespyre]],giver_loc=[[Quintis Jonguja]],giverType=[[NPC]],giverId=7879,ender=[[Ginro Hearthkindle]],ender_loc=[[Ginro Mechogar]],enderType=[[NPC]],enderId=7880,prevId=4129,rewardNextId=4131,poiX=-4458,poiY=3227,wowhead=[[https://www.wowhead.com/wotlk/quest=4130]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm a little wobbly still, sorry.  Anyway, I received some useful visions. Raschal takes two large leather backpacks from his boat and goes inland; he returns to the boat, however.  I see gnoll scalps... he ran into some gnolls - Woodpaw I think they're called.  He's very worried - almost terrified - about something.  So much so, that he is not paying attention to water elementals forming behind him.  The images... stop there. I need to rest, sorry $N.  Tell Gin what I've seen.  He needs to know.]],logDesc=[[Speak with Ginro Hearthkindle in Feathermoon Stronghold.]]}
DB[4131]={id=4131,zoneId=357,name=[[The Woodpaw Gnolls]],name_loc=[[Los gnolls Zarpaleña]],level=44,minLevel=40,giver=[[Ginro Hearthkindle]],giver_loc=[[Ginro Mechogar]],giverType=[[NPC]],giverId=7880,ender=[[Large Leather Backpacks]],ender_loc=[[Mochilas de piel grandes]],enderType=[[GO]],enderId=164953,prevId=4130,rewardNextId=4135,poiX=-4976,poiY=346,wowhead=[[https://www.wowhead.com/wotlk/quest=4131]],image=[[assets/images/quests/placeholder.png]],desc=[[Our "friends" the Woodpaw might have gotten Raschal in the end, but something tells me that's not what occurred.  Still, they're the best place to start looking. I wish I had clearer insight as to what to do, but all I have right now is 'Search the Woodpaw camps - go.'  I do know that gnolls will keep items they scavenge and fight over them; maybe they ran across the backpacks Quint mentioned.  I hadn't risked a head-on fight in past searches, but with Quint's vision on this I say rip into them.]],logDesc=[[Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.]]}
DB[4132]={id=4132,zoneId=1584,name=[[Operation: Death to Angerforge]],name_loc=[[Operación: muerte a Forjainquina]],level=58,minLevel=52,giver=[[Warlord Goretooth]],giver_loc=[[Señor de la guerra Dientegore]],giverType=[[NPC]],giverId=9077,ender=[[Warlord Goretooth]],ender_loc=[[Señor de la guerra Dientegore]],enderType=[[NPC]],enderId=9077,prevId=4121,poiX=-6678,poiY=-2224,wowhead=[[https://www.wowhead.com/wotlk/quest=4132]],image=[[assets/images/quests/placeholder.png]],desc=[[You have done an exemplary job, $N. It is now time to send you on your last mission. General Angerforge, the Dark Iron responsible for coordinating the attacks on the 109th division of the K.E.F. and the mass slaughter of our forces must be brought to justice. This will undoubtedly be your most grueling mission, but should you succeed, you will be richly rewarded. ]],logDesc=[[Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.]],rewards={{id=12059,qty=1}}}
DB[4133]={id=4133,zoneId=1584,name=[[Vivian Lagrave]],name_loc=[[Vivian Lagrave]],level=55,minLevel=50,giver=[[Apothecary Zinge]],giver_loc=[[Boticaria Zinge]],giverType=[[NPC]],giverId=5204,ender=[[Shadowmage Vivian Lagrave]],ender_loc=[[Maga oscura Vivian Lagrave]],enderType=[[NPC]],enderId=9078,rewardNextId=4134,poiX=-6682,poiY=-2151,wowhead=[[https://www.wowhead.com/wotlk/quest=4133]],image=[[assets/images/quests/placeholder.png]],desc=[[Shadowmaster Vivian Lagrave is in need of your services.  She is in the Badlands, in the orcish outpost of Kargath, pursuing rumors of a certain brew made by the Dark Iron dwarves of Blackrock Depths. Speak with Vivian.  She awaits you.]],logDesc=[[Speak with Shadowmaster Vivian Lagrave in Kargath.]]}
DB[4134]={id=4134,zoneId=1584,name=[[Lost Thunderbrew Recipe]],name_loc=[[La receta de Cebatruenos perdida]],level=55,minLevel=50,giver=[[Shadowmage Vivian Lagrave]],giver_loc=[[Maga oscura Vivian Lagrave]],giverType=[[NPC]],giverId=9078,ender=[[Shadowmage Vivian Lagrave]],ender_loc=[[Maga oscura Vivian Lagrave]],enderType=[[NPC]],enderId=9078,prevId=4133,poiX=-6682,poiY=-2151,wowhead=[[https://www.wowhead.com/wotlk/quest=4134]],image=[[assets/images/quests/placeholder.png]],desc=[[It is rumored that the Dark Iron Hurley Blackbreath has stolen a recipe for ale.  This ale, Thunderbrew Lager, is said to infuse its imbiber with great strength and courage.  We wish to study the drink.  Perhaps, we will find other applications for its virtues... applications more in line with Forsaken objectives. Delve into Blackrock Depths, find Hurley, take from him the recipe for Thunderbrew lager and bring it to me. And to find him, you may have to entice him by threatening his precious ale.]],logDesc=[[Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.]],rewards={{id=3928,qty=5},{id=6149,qty=5}},choiceRewards={{id=11964,qty=1},{id=12000,qty=1}}}
DB[4135]={id=4135,zoneId=357,name=[[The Writhing Deep]],name_loc=[[Las Galerías Retorcidas]],level=46,minLevel=40,giver=[[Large Leather Backpacks]],giver_loc=[[Mochilas de piel grandes]],giverType=[[GO]],giverId=164953,ender=[[Zukk'ash Pod]],ender_loc=[[Vaina de Zukk'ash]],enderType=[[GO]],enderId=164954,prevId=4131,rewardNextId=4265,poiX=-5319,poiY=433,wowhead=[[https://www.wowhead.com/wotlk/quest=4135]],image=[[assets/images/quests/placeholder.png]],desc=[[Inside the backpacks are two items: the first is a parcel of goods that was bound for Thalanaar, and the second is a note hastily penned to an unknown reader. The note tells of discovering insidious bug-like creatures south of the gnoll camps in a place called the Writhing Deep.  The author felt the need to investigate it personally, as though it was a serious threat to all of Feralas.  The note is signed, "Raschal of Feathermoon". It would seem that you have located where Raschal ultimately went.]],logDesc=[[Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep.  According to the note, it is located to the south of the Woodpaw gnoll camps.]]}
DB[4136]={id=4136,zoneId=1584,name=[[Ribbly Screwspigot]],name_loc=[[Ribbly Llavenrosca]],level=53,minLevel=48,giver=[[Yuka Screwspigot]],giver_loc=[[Yuka Llavenrosca]],giverType=[[NPC]],giverId=9544,ender=[[Yuka Screwspigot]],ender_loc=[[Yuka Llavenrosca]],enderType=[[NPC]],enderId=9544,prevId=4324,poiX=-7460,poiY=-2202,wowhead=[[https://www.wowhead.com/wotlk/quest=4136]],image=[[assets/images/quests/placeholder.png]],desc=[[My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another. Well, his last scheme must have been his worst, because Baron Revilgaz of Booty Bay just put a price on poor Ribbly's head.  I can't tell you how happy this makes the Screwspigots!  Our little Ribbly's finally worth something! But now he's hiding out, deep in Blackrock Depths.  Please, find him and bring him to me! Or, if he won't come, then that's ok... just bring me his head.]],logDesc=[[Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.]],choiceRewards={{id=11865,qty=1},{id=11963,qty=1},{id=12049,qty=1}}}
DB[4141]={id=4141,zoneId=490,name=[[Muigin and Larion]],name_loc=[[Muigin y Larion]],level=52,minLevel=47,giver=[[Muigin]],giverType=[[NPC]],giverId=9119,ender=[[Muigin]],enderType=[[NPC]],enderId=9119,rewardNextId=4142,poiX=-7084,poiY=-2282,wowhead=[[https://www.wowhead.com/wotlk/quest=4141]],image=[[assets/images/quests/placeholder.png]],desc=[[See Larion over there? It's HIS fault we're here! I told him we were going the wrong way, but would he listen? And would you believe that he's the one that won't speak to me? Well, until he changes his mind, let's have a bit of fun with him. Have you noticed the strange plant-like creatures around here? They're nothing but trouble, really, but I think if trained properly, I could get them to obey commands. First thing though, I'll need some samples to study. Do you think you could collect some?]],logDesc=[[Collect 15 Bloodpetals and return to Muigin.]]}
DB[4142]={id=4142,zoneId=490,name=[[A Visit to Gregan]],name_loc=[[Visita a Gregan]],level=52,minLevel=47,giver=[[Muigin]],giverType=[[NPC]],giverId=9119,ender=[[Gregan Brewspewer]],ender_loc=[[Gregan Vomitabrebaje]],enderType=[[NPC]],enderId=7775,prevId=4141,rewardNextId=4143,poiX=-3551,poiY=2306,wowhead=[[https://www.wowhead.com/wotlk/quest=4142]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm not quite sure what to make of this, $N. The plants... they seem to have some minimal intelligence. I'm no expert, though. But, I do know someone that is! Head to northern Feralas, and look for a buddy of mine named Gregan Brewspewer. He's an expert on this sort of thing. I'm sure Gregan can help us out here. You'll find him out in the wilderness; he's not the type to live in a big city.]],logDesc=[[Take a Bloodpetal to Gregan Brewspewer in Feralas.]]}
DB[4143]={id=4143,zoneId=490,name=[[Haze of Evil]],name_loc=[[Bruma del mal]],level=52,minLevel=47,giver=[[Gregan Brewspewer]],giver_loc=[[Gregan Vomitabrebaje]],giverType=[[NPC]],giverId=7775,ender=[[Muigin]],enderType=[[NPC]],enderId=9119,prevId=4142,poiX=-6204,poiY=-1055,wowhead=[[https://www.wowhead.com/wotlk/quest=4143]],image=[[assets/images/quests/placeholder.png]],desc=[[To tell you the truth, $N, I've never seen any plants like this in my travels. Perhaps I should take a trip to this crater... At any rate, I think I know just the thing Muigin's looking for -- Atal'ai haze. It's horrid stuff, hard to collect, but it's just what he needs to control the little monsters. You'll need to visit the temple of Atal'Hakkar in the Swamp of Sorrows. The Atal'ai Haze can be collected from the deep lurkers, murk worms, or oozes found there. Good luck, $N!]],logDesc=[[Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater.]]}
DB[4144]={id=4144,zoneId=490,name=[[Bloodpetal Sprouts]],name_loc=[[Brotes Sangrepétalo]],level=53,minLevel=47,giver=[[Muigin]],giverType=[[NPC]],giverId=9119,ender=[[Muigin]],enderType=[[NPC]],enderId=9119,prevId=4143,poiX=-6204,poiY=-1055,wowhead=[[https://www.wowhead.com/wotlk/quest=4144]],image=[[assets/images/quests/placeholder.png]]}
DB[4145]={id=4145,zoneId=490,name=[[Larion and Muigin]],name_loc=[[Larion y Muigin]],level=52,minLevel=47,giver=[[Larion]],giverType=[[NPC]],giverId=9118,ender=[[Larion]],enderType=[[NPC]],enderId=9118,rewardNextId=4147,poiX=-6983,poiY=-1717,wowhead=[[https://www.wowhead.com/wotlk/quest=4145]],image=[[assets/images/quests/placeholder.png]],desc=[[See Muigin over there? It's HIS fault we're lost! I'm the one that knew the way, but he insisted he knew a shortcut, and we ended up here! To make matters worse, now he keeps sending his crazy plant pests to annoy me. I'm so angry that I'm not planning on talking to him any time soon, but these pests are too much to handle. Why don't we try to limit his supply, first thing. Go out and hunt some Bloodpetals, then return to me.]],logDesc=[[Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge.]]}
DB[4146]={id=4146,zoneId=1417,name=[[Zapper Fuel]],name_loc=[[Combustible de irradior]],level=52,minLevel=47,giver=[[Liv Rizzlefix]],giver_loc=[[Liv Rizzlefix]],giverType=[[NPC]],giverId=8496,ender=[[Larion]],enderType=[[NPC]],enderId=9118,prevId=4147,poiX=-6182,poiY=-1152,wowhead=[[https://www.wowhead.com/wotlk/quest=4146]],image=[[assets/images/quests/placeholder.png]],desc=[[You're in luck, $n! I've been working on some of my own experiments while Marvon's been gone, and one of them is a short range bug zapper. With just a few adjustments, it should be great for ridding yourself of those Bloodpetal pests. I can let you have one of my zapper prototypes, but you'll still need to collect the fuel. You can get the necessary Atal'ai haze that the zapper needs in the temple of Atal'Hakkar. The deep lurkers, murk worms, or oozes are the ones you'll need to get it from.]],logDesc=[[Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge.]]}
DB[4147]={id=4147,zoneId=490,name=[[Marvon's Workshop]],name_loc=[[El taller de Marvon]],level=52,minLevel=47,giver=[[Larion]],giverType=[[NPC]],giverId=9118,ender=[[Liv Rizzlefix]],ender_loc=[[Liv Rizzlefix]],enderType=[[NPC]],enderId=8496,prevId=4145,rewardNextId=4146,poiX=-1004,poiY=-3705,wowhead=[[https://www.wowhead.com/wotlk/quest=4147]],image=[[assets/images/quests/placeholder.png]],desc=[[I managed to spy on what Muigin was doing, and he's actually growing the darn things over there! I think the only solution here is to... no, not go talk to him... What are you thinking? The solution is to fight back! We'll need the help of my friend, Marvon, who has a workshop in Ratchet.  I'm sure he'll be able to create some sort of gadget that will help us.]],logDesc=[[Travel to Marvon Rivetseeker's workshop in Ratchet.]]}
DB[4148]={id=4148,zoneId=490,name=[[Bloodpetal Zapper]],name_loc=[[Liquidador de Sangrepétalo]],level=53,minLevel=47,giver=[[Larion]],giverType=[[NPC]],giverId=9118,ender=[[Larion]],enderType=[[NPC]],enderId=9118,prevId=4146,poiX=-6182,poiY=-1152,wowhead=[[https://www.wowhead.com/wotlk/quest=4148]],image=[[assets/images/quests/placeholder.png]],rewards={{id=11320,qty=1}}}
DB[4161]={id=4161,name=[[Recipe of the Kaldorei]],name_loc=[[La receta de los kaldorei]],level=7,minLevel=1,giver=[[Zarrin]],giverType=[[NPC]],giverId=6286,ender=[[Zarrin]],enderType=[[NPC]],enderId=6286,poiX=9652,poiY=1049,wowhead=[[https://www.wowhead.com/wotlk/quest=4161]],image=[[assets/images/quests/placeholder.png]],desc=[[Long ago, the night elves were called the kaldorei, a name that means "children of the stars." Learning of the past is an important step in your path as a $c, $N, so listen well to what I have to tell you. The kaldorei have always taken much pride in their harmonious relationship with nature. This means that we only take from nature what is necessary, and that we return in kind. This balance has afforded us much, $N. Go out and collect seven small spider legs -- no more than that, and return to me.]],logDesc=[[Collect 7 Small Spider Legs for Zarrin in Dolanaar.]],rewards={{id=5482,qty=1},{id=5472,qty=3}}}
DB[4181]={id=4181,name=[[Goblin Engineering]],name_loc=[[Ingeniería goblin]],level=-1,minLevel=10,giver=[[Lilliam Sparkspindle]],giver_loc=[[Lilliam Chispeje]],giverType=[[NPC]],giverId=5518,ender=[[Nixx Sprocketspring]],ender_loc=[[Nixx Muellepiñón]],enderType=[[NPC]],enderId=8126,nextId=3639,rewardNextId=3639,exGroup=3526,poiX=-7132,poiY=-3840,wowhead=[[https://www.wowhead.com/wotlk/quest=4181]],image=[[assets/images/quests/placeholder.png]],desc=[[Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves. $N, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.]],logDesc=[[If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.]]}
DB[4182]={id=4182,zoneId=46,name=[[Dragonkin Menace]],name_loc=[[La amenaza de los dragonantes]],level=54,minLevel=48,giverType=[[NPC]],enderType=[[NPC]],poiX=-8377,poiY=-2780,wowhead=[[https://www.wowhead.com/wotlk/quest=4182]],image=[[assets/images/quests/placeholder.png]],desc=[[Life in the Burning Steppes is rife with conflict. Just look at this place! We know very little of what happened to these buildings, but we do know that at one time, before the great explosion, this was all part of the Redridge mountain range. Enough lamenting! We have a problem, $N. You may have noticed the dragonkin below this ridge. We need assistance in pushing them back. Kill as many as you can and return to me. Succeed and perhaps we can talk of other things. ]],logDesc=[[Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake.]]}
DB[4183]={id=4183,zoneId=46,name=[[The True Masters]],name_loc=[[Los verdaderos maestros]],level=54,minLevel=48,giverType=[[NPC]],enderType=[[NPC]],prevId=4182,poiX=-9219,poiY=-2222,wowhead=[[https://www.wowhead.com/wotlk/quest=4183]],image=[[assets/images/quests/placeholder.png]],desc=[[We had always assumed that the Blackrock orcs were a product of their savage upbringing. What we have found here, in their homeland, tells us another story. Indeed, it is bloodlust and thirst for conflict that empowers them, but the black dragonflight are the beings whom control the orcs of Blackrock. We suspect that it is the black dragonflight that fuels them with rage and hostility. Take this letter to Magistrate Solomon. He will know what must be done. <Helendis hands you a sealed letter.>]],logDesc=[[Travel to Lakeshire in Redridge Mountains and deliver Helendis Riverhorn's Letter to Magistrate Solomon.]]}
DB[4184]={id=4184,zoneId=46,name=[[The True Masters]],name_loc=[[Los verdaderos maestros]],level=54,minLevel=48,giverType=[[NPC]],enderType=[[NPC]],prevId=4183,poiX=-8441,poiY=333,wowhead=[[https://www.wowhead.com/wotlk/quest=4184]],image=[[assets/images/quests/placeholder.png]],desc=[[This is grim news, $N. To discover that our mortal enemies are merely pawns of a much greater threat is disheartening. There is no possible way that Lakeshire could survive an attack from both the Blackrock orcs and the black dragonflight. Should Lakeshire fall to this menace, Darkshire would fall next, and then what? Goldshire? Stormwind itself? You must take this information to King Varian Wrynn in Stormwind at once! If this does not merit the aid of Stormwind, nothing will and all is lost. ]],logDesc=[[Travel to Stormwind and deliver Solomon's Plea to King Varian Wrynn. King Varian Wrynn resides in Stormwind Keep.]]}
DB[4185]={id=4185,zoneId=46,name=[[The True Masters]],name_loc=[[Los verdaderos maestros]],level=54,minLevel=48,giverType=[[NPC]],enderType=[[NPC]],prevId=4184,poiX=-8437,poiY=333,wowhead=[[https://www.wowhead.com/wotlk/quest=4185]],image=[[assets/images/quests/placeholder.png]],desc=[[Solomon paints a dreary picture. Still, we cannot afford to send our thinly spread troops to the aid of Lakeshire on speculation. I will need proof of these claims before I can act. Speak with Lady Prestor, $N. She is a learned woman and knows much of dragons and dragonkin. She may be able to shed some light on this situation. ]],logDesc=[[Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor.]]}
DB[4186]={id=4186,zoneId=46,name=[[The True Masters]],name_loc=[[Los verdaderos maestros]],level=54,minLevel=48,giverType=[[NPC]],enderType=[[NPC]],prevId=4185,poiX=-9219,poiY=-2222,wowhead=[[https://www.wowhead.com/wotlk/quest=4186]],image=[[assets/images/quests/placeholder.png]],desc=[[I am going to empower you as an acting deputy of Stormwind, $N. Return to Magistrate Solomon in Lakeshire and deliver this decree.]],logDesc=[[Take Wrynn's Decree to Magistrate Solomon in Lakeshire. ]]}
DB[4201]={id=4201,zoneId=1584,name=[[The Love Potion]],name_loc=[[La poción de enamoramiento]],level=54,minLevel=50,giver=[[Mistress Nagmara]],giver_loc=[[Coima Nagmara]],giverType=[[NPC]],giverId=9500,ender=[[Mistress Nagmara]],ender_loc=[[Coima Nagmara]],enderType=[[NPC]],enderId=9500,poiX=2381,poiY=-6518,wowhead=[[https://www.wowhead.com/wotlk/quest=4201]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, the pains of love!  My dear Private Rocknot is immune to my charms.  I am spurned!  It's maddening! You must help me!  We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart.  To make it, I need these items: the herb gromsblood, giant silver veins from the cliff giants of Azshara, and water from the Golakka Springs Crater in Un'Goro.  You can place the water in this vial. Please, $N, help a poor soul in her quest for happiness!]],logDesc=[[Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.]],choiceRewards={{id=11962,qty=1},{id=11866,qty=1}}}
DB[4221]={id=4221,zoneId=361,name=[[Corrupted Windblossom]],name_loc=[[Flor del viento corrupta]],level=55,minLevel=48,giver=[[Corrupted Windblossom]],giver_loc=[[Flor del viento corrupta]],giverType=[[GO]],giverId=174601,ender=[[Corrupted Windblossom]],ender_loc=[[Flor del viento corrupta]],enderType=[[GO]],enderId=174601,poiX=4867,poiY=-600,wowhead=[[https://www.wowhead.com/wotlk/quest=4221]],image=[[assets/images/quests/placeholder.png]]}
DB[4222]={id=4222,zoneId=361,name=[[Corrupted Windblossom]],name_loc=[[Flor del viento corrupta]],level=55,minLevel=48,giver=[[Corrupted Windblossom]],giver_loc=[[Flor del viento corrupta]],giverType=[[GO]],giverId=174602,ender=[[Corrupted Windblossom]],ender_loc=[[Flor del viento corrupta]],enderType=[[GO]],enderId=174602,poiX=5267,poiY=-333,wowhead=[[https://www.wowhead.com/wotlk/quest=4222]],image=[[assets/images/quests/placeholder.png]]}
DB[4223]={id=4223,zoneId=46,name=[[The True Masters]],name_loc=[[Los verdaderos maestros]],level=54,minLevel=48,giverType=[[NPC]],enderType=[[NPC]],prevId=4186,poiX=-8379,poiY=-2749,wowhead=[[https://www.wowhead.com/wotlk/quest=4223]],image=[[assets/images/quests/placeholder.png]],desc=[[<Magistrate Solomon sighs.> You must return to the Burning Steppes, $N. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck.]],logDesc=[[Speak with Marshal Maxwell in the Burning Steppes.]]}
DB[4224]={id=4224,zoneId=46,name=[[The True Masters]],name_loc=[[Los verdaderos maestros]],level=54,minLevel=48,giverType=[[NPC]],enderType=[[NPC]],prevId=4223,poiX=-8379,poiY=-2749,wowhead=[[https://www.wowhead.com/wotlk/quest=4224]],image=[[assets/images/quests/placeholder.png]],desc=[[What? You thought you were the first? How many soldiers must we lose before Stormwind acts? We had accumulated enormous amounts of intelligence pertaining to the Blackrock menace before we lost our commanding officer, Marshal Windsor. With Marshal Windsor went all of our precious information. What we need is that documentation. Speak with Ragged John, $N. He was with Windsor when they were attacked by a Blackrock raiding party.  He was last seen in a cave to the north.]],logDesc=[[Speak with Ragged John.]]}
DB[4241]={id=4241,zoneId=1584,name=[[Marshal Windsor]],name_loc=[[El mariscal Windsor]],level=54,minLevel=48,giverType=[[NPC]],enderType=[[NPC]],prevId=4224,wowhead=[[https://www.wowhead.com/wotlk/quest=4241]],image=[[assets/images/quests/placeholder.png]],desc=[[So that good for nothing coward says that Windsor is alive, eh? Suit up, deputy, you are going in to find him. If Windsor is alive, you are to bring him back. If he's dead, I want proof. <Maxwell laughs.> I bet you are getting tired of hearing that, aren't you?]],logDesc=[[Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor. You recall Ragged John talking about Windsor being dragged off to a prison.]]}
DB[4242]={id=4242,zoneId=1584,name=[[Abandoned Hope]],name_loc=[[Esperanza perdida]],level=54,minLevel=48,giverType=[[NPC]],enderType=[[NPC]],prevId=4241,poiX=-8379,poiY=-2749,wowhead=[[https://www.wowhead.com/wotlk/quest=4242]],image=[[assets/images/quests/placeholder.png]],desc=[[Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see. As for my data, it's lost. Gone. Unrecoverable. Should I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile's eyes. Leave me, $N.]],logDesc=[[Give Marshal Maxwell at Morgan's Vigil in the Burning Steppes the bad news.]],choiceRewards={{id=12018,qty=1},{id=12021,qty=1},{id=12041,qty=1}}}
DB[4243]={id=4243,zoneId=490,name=[[Chasing A-Me 01]],name_loc=[[Buscando a Memo 01]],level=53,minLevel=48,giver=[[Karna Remtravel]],giver_loc=[[Karna Tripirrem]],giverType=[[NPC]],giverId=9618,ender=[[A-Me 01]],ender_loc=[[Memo 01]],enderType=[[NPC]],enderId=9623,rewardNextId=4244,poiX=-6380,poiY=-1970,wowhead=[[https://www.wowhead.com/wotlk/quest=4243]],image=[[assets/images/quests/placeholder.png]],desc=[[Unfortunately, something's happened to one of my greatest inventions. You've seen mechanical squirrels, yes? Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01. She has scrying gems for eyes so I could see everything she saw. She made it to Fungal Rock--the apes' lair--just east of here, and that's when I lost contact. The last thing I saw was one of their alpha males rushing up to say hello to her! Can you help me find her?]],logDesc=[[Find A-Me 01 in Un'Goro Crater.]]}
DB[4244]={id=4244,zoneId=490,name=[[Chasing A-Me 01]],name_loc=[[Buscando a Memo 01]],level=53,minLevel=48,giver=[[A-Me 01]],giver_loc=[[Memo 01]],giverType=[[NPC]],giverId=9623,ender=[[A-Me 01]],ender_loc=[[Memo 01]],enderType=[[NPC]],enderId=9623,prevId=4243,poiX=-6380,poiY=-1970,wowhead=[[https://www.wowhead.com/wotlk/quest=4244]],image=[[assets/images/quests/placeholder.png]],desc=[[A little further investigation shows a panel that slides open. Clearly written above some wiring is the statement, "Replace Mithril Casing And Turn Power Off Then On." Taking a moment to replace the panel, you wonder if it'll be that simple to fix A-Me 01 and get her back to Karna Remtravel near Marshall's Refuge. Only trying it will tell.]],logDesc=[[Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater.]]}
DB[4245]={id=4245,zoneId=490,name=[[Chasing A-Me 01]],name_loc=[[Buscando a Memo 01]],level=53,minLevel=48,giver=[[A-Me 01]],giver_loc=[[Memo 01]],giverType=[[NPC]],giverId=9623,ender=[[Karna Remtravel]],ender_loc=[[Karna Tripirrem]],enderType=[[NPC]],enderId=9618,prevId=4244,poiX=-6298,poiY=-1183,wowhead=[[https://www.wowhead.com/wotlk/quest=4245]],image=[[assets/images/quests/placeholder.png]],desc=[[Checking to see if you're prepared to lead A-Me 01 back to Karna Remtravel, you flip the switch to the "Off" position. Glancing around once again to make sure none of the gorillas are coming, you prepare to see what happens when you flip the switch back to the "On" position. This is your last chance... are you sure this is what you want to do?]],logDesc=[[Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater.]]}
DB[4261]={id=4261,zoneId=361,name=[[Ancient Spirit]],name_loc=[[El espíritu de un Ancestro]],level=56,minLevel=49,giver=[[Arei]],giverType=[[NPC]],giverId=9598,ender=[[Kayneth Stillwind]],ender_loc=[[Kayneth Ventoleve]],enderType=[[NPC]],enderId=3848,prevId=4442,poiX=2954,poiY=-3215,wowhead=[[https://www.wowhead.com/wotlk/quest=4261]],image=[[assets/images/quests/placeholder.png]],desc=[[Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos... The skull of Gul'dan ensured that none were spared here. All fell to the corruption. Even now, as a spirit, I still find myself trapped, bearing the suffering of this land. Help me find my way home. Please, $N, tell me you will lead an ancient spirit away from here, where I may finally rest. Once I am free, seek out Kayneth Stillwind, a druid that resides in Forest Song, to the east.]],logDesc=[[Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale.]],choiceRewards={{id=11873,qty=1},{id=11874,qty=1}}}
DB[4262]={id=4262,zoneId=25,name=[[Overmaster Pyron]],name_loc=[[Maestro supremo Pyron]],level=52,minLevel=48,giver=[[Jalinda Sprig]],giver_loc=[[Jalinda Espiga]],giverType=[[NPC]],giverId=9561,ender=[[Jalinda Sprig]],ender_loc=[[Jalinda Espiga]],enderType=[[NPC]],enderId=9561,rewardNextId=4263,poiX=-7292,poiY=-891,wowhead=[[https://www.wowhead.com/wotlk/quest=4262]],image=[[assets/images/quests/placeholder.png]],desc=[[The last five of my mages that went snooping around in Blackrock Mountain came back extra crispy with a permanent orange gnomefro - or worse. <Jalinda picks up some ashes from the ground and releases them into the air.> One nasty bugger in particular, Overmaster Pyron, seems to be causing quite a bit of trouble. We need that elemental terminated so that our expedition crew can make its way into Blackrock Depths! He guards the entrance at the Blackrock Quarry.]],logDesc=[[Slay Overmaster Pyron. You recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?]]}
DB[4263]={id=4263,zoneId=1584,name=[[Incendius!]],name_loc=[[¡Incendius!]],level=56,minLevel=48,giver=[[Jalinda Sprig]],giver_loc=[[Jalinda Espiga]],giverType=[[NPC]],giverId=9561,ender=[[Jalinda Sprig]],ender_loc=[[Jalinda Espiga]],enderType=[[NPC]],enderId=9561,prevId=4262,poiX=-8399,poiY=-2769,wowhead=[[https://www.wowhead.com/wotlk/quest=4263]],image=[[assets/images/quests/placeholder.png]],desc=[[Are you sure Pyron said 'Incendius' when he died? <Jalinda swallows hard.> Lord Incendius is purported to be a minion of Ragnaros! Oh dear, oh dear... whatever will we do? Do you think you can handle another mission? I don't have anybody else to send, $N! We will never get a team in if Incendius continues to raise Pyron from the ashes. You'll have to find and destroy Lord Incendius! ]],logDesc=[[Find Lord Incendius in Blackrock Depths and destroy him!]],choiceRewards={{id=12113,qty=1},{id=12114,qty=1},{id=12112,qty=1},{id=12115,qty=1}}}
DB[4264]={id=4264,zoneId=1584,name=[[A Crumpled Up Note]],name_loc=[[Una nota arrugada]],level=58,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],prevId=4242,wowhead=[[https://www.wowhead.com/wotlk/quest=4264]],image=[[assets/images/quests/placeholder.png]],desc=[[The note has stains covering its surface. The text is barely legible, but you make out the following: ...sweet irony... ...the fall of the broken Alliance... ...if it were not for General Angerforge's diligence, we may have never discovered the pattern to the encryption... ...Argelmach is almost done with the decryption of Windsor's notes. Our lord will rise from the depths and crush any that remain... -Emperor Dagran Thaurissan. ]],logDesc=[[You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all.]]}
DB[4265]={id=4265,zoneId=357,name=[[Freed from the Hive]],name_loc=[[Liberado de la colmena]],level=46,minLevel=40,giver=[[Zukk'ash Pod]],giver_loc=[[Vaina de Zukk'ash]],giverType=[[GO]],giverId=164954,ender=[[Ginro Hearthkindle]],ender_loc=[[Ginro Mechogar]],enderType=[[NPC]],enderId=7880,prevId=4135,rewardNextId=4266,poiX=-5323,poiY=360,wowhead=[[https://www.wowhead.com/wotlk/quest=4265]],image=[[assets/images/quests/placeholder.png]],desc=[[The pod splits opens some when you touch it, revealing a night elven male who is surprisingly still alive.  He seems to be in good health, though deeply stunned.  As you help him down from the pod, he stirs to life. "Thank Elune - you've saved me, friend!  I... I'm Raschal, and I awoke paralyzed inside this pod after these bugs overwhelmed me.  Were you sent by the Stronghold?" It would seem that you've found the missing courier!]],logDesc=[[Free Raschal from the Zukk'ash hive. Return to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well.]]}
DB[4266]={id=4266,zoneId=357,name=[[A Hero's Welcome]],name_loc=[[La bienvenida de un héroe]],level=46,minLevel=40,giver=[[Ginro Hearthkindle]],giver_loc=[[Ginro Mechogar]],giverType=[[NPC]],giverId=7880,ender=[[Shandris Feathermoon]],ender_loc=[[Shandris Plumaluna]],enderType=[[NPC]],enderId=3936,prevId=4265,rewardNextId=4267,poiX=-4506,poiY=3337,wowhead=[[https://www.wowhead.com/wotlk/quest=4266]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, General Shandris Feathermoon would like to speak with you personally.  No doubt she wants to thank you for your service to the Stronghold, but I do know that she also wants to talk to you about the insect creatures that you and Raschal faced in southern Feralas.  The reports of those Zukk'ash insects are... frightening, to say the least. General Feathermoon is waiting for you in the main compound.]],logDesc=[[Speak with Shandris Feathermoon in Feathermoon Stronghold.]],choiceRewards={{id=11856,qty=1},{id=11857,qty=1}}}
DB[4267]={id=4267,zoneId=357,name=[[Rise of the Silithid]],name_loc=[[La sublevación de los silítidos]],level=46,minLevel=40,giver=[[Shandris Feathermoon]],giver_loc=[[Shandris Plumaluna]],giverType=[[NPC]],giverId=3936,ender=[[Gracina Spiritmight]],ender_loc=[[Gracina Poderespíritu]],enderType=[[NPC]],enderId=7740,prevId=4266,nextId=4493,poiX=9634,poiY=2496,wowhead=[[https://www.wowhead.com/wotlk/quest=4267]],image=[[assets/images/quests/placeholder.png]],desc=[[I am entrusting you with a copy of the report Raschal made on the infestation of southeastern Feralas.  While the main report is being filed in Darnassus, I want you to give this copy to an associate of the Protectorate.  Her name is Gracina Spiritmight; she is a priestess who dwells in the Temple of the Moon in Darnassus.  She has broad knowledge on these kinds of creatures, and her receiving this report would benefit us all. You're dismissed - good luck, $N; may Elune watch over us all.]],logDesc=[[Bring Raschal's Report to Gracina Spiritmight in Darnassus.]],choiceRewards={{id=34416,qty=1},{id=34417,qty=1}}}
DB[4281]={id=4281,zoneId=357,name=[[Thalanaar Delivery]],name_loc=[[Una entrega en Thalanaar]],level=44,minLevel=40,giverType=[[NPC]],ender=[[Falfindel Waywarder]],ender_loc=[[Díscolo Falfindel]],enderType=[[NPC]],enderId=4048,poiX=-4524,poiY=-788,wowhead=[[https://www.wowhead.com/wotlk/quest=4281]],image=[[assets/images/quests/placeholder.png]],desc=[[This parcel of goods you found in the Woodpaw gnoll camps was supposed to be delivered to the small way-station of Thalanaar in southeastern Feralas.  Regardless of the missing courier's fate, the task of delivering the parcel remains unfinished. Examining the parcel in detail reveals a hand written name of "Falfindel Waywarder" on the outside of the packaging.  Perhaps this is the parcel's ultimate recipient.]],logDesc=[[Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar.]]}
DB[4282]={id=4282,zoneId=1584,name=[[A Shred of Hope]],name_loc=[[Una brizna de esperanza]],level=58,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],prevId=4264,wowhead=[[https://www.wowhead.com/wotlk/quest=4282]],image=[[assets/images/quests/placeholder.png]],desc=[[<Marshal Windsor shakes the note excitedly.> Do you realize what this means, $N? Perhaps all is not lost! From what I can ascertain, the information is being held by two Dark Iron dwarves: General Angerforge and the golem lord, Argelmach. I have a feeling that they won't just hand over the information if we ask nicely. I hope you are ready to battle. Venture forth and find these two villains! Destroy them and return my lost information.]],logDesc=[[Return Marshal Windsor's Lost Information. Marshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge.]]}
DB[4283]={id=4283,zoneId=46,name=[[FIFTY! YEP!]],name_loc=[[¡CINCUENTA! ¡SÍ!]],level=56,minLevel=50,giver=[[Oralius]],giverType=[[NPC]],giverId=9177,ender=[[Oralius]],enderType=[[NPC]],enderId=9177,poiX=-8183,poiY=-2872,wowhead=[[https://www.wowhead.com/wotlk/quest=4283]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm going to let you in on a little secret, soldier. Come a little closer. I'M THE ONLY SANE ONE HERE! Look at these people! Would you believe that they're all insane!? Well they are! NUTS! CRAZY! <Oralius lowers his voice.> Let's just keep that between me, you, and my pal Captain Winky. <Oralius grabs at the air and squeezes.> Anyhooooo... I'm collecting badges to go along with my ogre ear collection. Orc is the flavor of the day. Fifty. GO! <Oralius blows into a horn.> SHIP IT!]],logDesc=[[Collect 50 Blackrock Medallions.]]}
DB[4284]={id=4284,zoneId=490,name=[[Crystals of Power]],name_loc=[[Cristales de poder]],level=53,minLevel=47,giver=[[J.D. Collie]],giver_loc=[[J.D. Collie]],giverType=[[NPC]],giverId=9117,ender=[[J.D. Collie]],ender_loc=[[J.D. Collie]],enderType=[[NPC]],enderId=9117,poiX=-6033,poiY=-1018,wowhead=[[https://www.wowhead.com/wotlk/quest=4284]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm sure you've noticed 'em, $N. They're everywhere! What am I talking about? Why, the crystals, of course! The crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them. I've been doing experiments here with them for a while, but I can't seem to find anything. Well, I haven't yet, anyway. Say, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?]],logDesc=[[Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge.]]}
DB[4285]={id=4285,zoneId=490,name=[[The Northern Pylon]],name_loc=[[La Torre de cristal del Norte]],level=53,minLevel=47,giver=[[J.D. Collie]],giver_loc=[[J.D. Collie]],giverType=[[NPC]],giverId=9117,ender=[[J.D. Collie]],ender_loc=[[J.D. Collie]],enderType=[[NPC]],enderId=9117,prevId=4284,nextId=4321,exGroup=-4285,poiX=-6033,poiY=-1018,wowhead=[[https://www.wowhead.com/wotlk/quest=4285]],image=[[assets/images/quests/placeholder.png]],desc=[[What could they be for? I can't get the thought out of my head! It's driving me crazy --  that the rumors I have heard about the crystal pylons are all true. Call me gullible, but I'll usually believe anything people tell me. Anyway, I have heard that there is one of the crystal pylons fairly close. Somewhere in the north... Please locate it, $N. I just know they exist.]],logDesc=[[Discover the location of the Northern Crystal Pylon in Un'Goro Crater.]]}
DB[4286]={id=4286,zoneId=1584,name=[[The Good Stuff]],name_loc=[[Buena mercancía]],level=56,minLevel=50,giver=[[Oralius]],giverType=[[NPC]],giverId=9177,ender=[[Oralius]],enderType=[[NPC]],enderId=9177,poiX=-8372,poiY=-2743,wowhead=[[https://www.wowhead.com/wotlk/quest=4286]],image=[[assets/images/quests/placeholder.png]],desc=[[Captain Winky tells me that the Dark Irons in the Depths got all the good stuff. Ain't that right, Winky? <Oralius does his best impersonation of a pirate.> ARRR MATEY! IT BE RIGHT! See what I'm saying? You need to get in there and bring me back some samples of the good stuff. Get in there and shake your moneymaker! ]],logDesc=[[Collect 20 Dark Iron Fanny Packs.]],rewards={{id=11883,qty=1}}}
DB[4287]={id=4287,zoneId=490,name=[[The Eastern Pylon]],name_loc=[[La Torre de cristal del Este]],level=53,minLevel=47,giver=[[J.D. Collie]],giver_loc=[[J.D. Collie]],giverType=[[NPC]],giverId=9117,ender=[[J.D. Collie]],ender_loc=[[J.D. Collie]],enderType=[[NPC]],enderId=9117,prevId=4284,nextId=4321,exGroup=-4285,poiX=-6033,poiY=-1018,wowhead=[[https://www.wowhead.com/wotlk/quest=4287]],image=[[assets/images/quests/placeholder.png]],desc=[[During my stay here, I have heard strange rumors about mysterious pylons existing out in the wilderness of the crater, $N. I guess that they are quite large, with crystals lining their interiors. Although I've never seen one, I can't help but think that the rumors are true -- and that the pylons have something to do with all the crystals we found So why don't you help me put my curiosity to rest? Supposedly, there is one in the eastern area of the crater. Do you think you can find it?]],logDesc=[[Discover the location of the Eastern Crystal Pylon in Un'Goro Crater.]]}
DB[4288]={id=4288,zoneId=490,name=[[The Western Pylon]],name_loc=[[La Torre de cristal del Oeste]],level=53,minLevel=47,giver=[[J.D. Collie]],giver_loc=[[J.D. Collie]],giverType=[[NPC]],giverId=9117,ender=[[J.D. Collie]],ender_loc=[[J.D. Collie]],enderType=[[NPC]],enderId=9117,prevId=4284,nextId=4321,exGroup=-4285,poiX=-6033,poiY=-1018,wowhead=[[https://www.wowhead.com/wotlk/quest=4288]],image=[[assets/images/quests/placeholder.png]],desc=[[My experiments so far have not yielded any positive results, $N. I can't help but hope that you can find a solution by searching for one of the pylons that I have heard exist. Perhaps if we combine certain colors at them... but I get ahead of myself. Let's find them first! $N, search the western area of the crater; a pylon is said to be somewhere in that area.]],logDesc=[[Discover the location of the Western Crystal Pylon.]]}
DB[4289]={id=4289,zoneId=490,name=[[The Apes of Un'Goro]],name_loc=[[Los simios de Un'Goro]],level=55,minLevel=47,giver=[[Torwa Pathfinder]],giver_loc=[[Torwa Abrecaminos]],giverType=[[NPC]],giverId=9619,ender=[[Torwa Pathfinder]],ender_loc=[[Torwa Abrecaminos]],enderType=[[NPC]],enderId=9619,poiX=-6402,poiY=-2023,wowhead=[[https://www.wowhead.com/wotlk/quest=4289]],image=[[assets/images/quests/placeholder.png]],desc=[[This crater has many strange creatures--they seem to be nobler versions of the creatures found throughout my homeland and beyond. I cannot explain it, but this place cries of the Earth Mother. I pay homage to her every time I track one of her beautiful creatures across its basin. If you too wish to feel the enlightenment that accompanies such a great feat, then head to the north. There you'll find great apes who are a test for any mortal's strength. Bring me their pelts... prove your strength.]],logDesc=[[Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.]]}
DB[4290]={id=4290,zoneId=490,name=[[The Fare of Lar'korwi]],name_loc=[[La comida de Lar'korwi]],level=53,minLevel=48,giver=[[Torwa Pathfinder]],giver_loc=[[Torwa Abrecaminos]],giverType=[[NPC]],giverId=9619,ender=[[Torwa Pathfinder]],ender_loc=[[Torwa Abrecaminos]],enderType=[[NPC]],enderId=9619,rewardNextId=4291,poiX=-7365,poiY=-2010,wowhead=[[https://www.wowhead.com/wotlk/quest=4290]],image=[[assets/images/quests/placeholder.png]],desc=[[Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind. Lar'korwi killed him not far from this spot. If you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it. Return to me afterwards.]],logDesc=[[Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater.]]}
DB[4291]={id=4291,zoneId=490,name=[[The Scent of Lar'korwi]],name_loc=[[Un aroma irresistible para Lar'korwi]],level=53,minLevel=48,giver=[[Torwa Pathfinder]],giver_loc=[[Torwa Abrecaminos]],giverType=[[NPC]],giverId=9619,ender=[[Torwa Pathfinder]],ender_loc=[[Torwa Abrecaminos]],enderType=[[NPC]],enderId=9619,prevId=4290,rewardNextId=4292,poiX=-7840,poiY=-2117,wowhead=[[https://www.wowhead.com/wotlk/quest=4291]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm actually surprised he has not come for you yet, $N. But all is well, for I have a final plan that will bring the monster to us. Being the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.]],logDesc=[[Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater.]]}
DB[4292]={id=4292,zoneId=490,name=[[The Bait for Lar'korwi]],name_loc=[[El cebo para Lar'korwi]],level=56,minLevel=48,giver=[[Torwa Pathfinder]],giver_loc=[[Torwa Abrecaminos]],giverType=[[NPC]],giverId=9619,ender=[[Torwa Pathfinder]],ender_loc=[[Torwa Abrecaminos]],enderType=[[NPC]],enderId=9619,prevId=4291,poiX=-7205,poiY=-2357,wowhead=[[https://www.wowhead.com/wotlk/quest=4292]],image=[[assets/images/quests/placeholder.png]],desc=[[This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains. It was here I saw Lar'korwi last. You will know you are in the right area because of all the bones from massive creatures that once wandered nearby. Take the meat you recovered and place it there. Then, rub this mixture I created on the meat. If both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.]],logDesc=[[Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.]],choiceRewards={{id=11876,qty=1},{id=11882,qty=1}}}
DB[4293]={id=4293,zoneId=1497,name=[[A Sample of Slime...]],name_loc=[[Muestras de babosa...]],level=52,minLevel=48,giver=[[Chemist Fuely]],giver_loc=[[Químico Fuely]],giverType=[[NPC]],giverId=10136,ender=[[Chemist Fuely]],ender_loc=[[Químico Fuely]],enderType=[[NPC]],enderId=10136,nextId=4642,exGroup=-4293,poiX=5354,poiY=-886,wowhead=[[https://www.wowhead.com/wotlk/quest=4293]],image=[[assets/images/quests/placeholder.png]],desc=[[Felwood is a forest far north of the Barrens, even farther than Ashenvale. There, slimes are found all around pools of water blessed by the touch of Fel. The Scourge decimated the area with attacks of Infernals and other demonic magics--the slimes supposedly crept up through the earth during these attacks. Gather samples of Felwood slimes and we will use the testing equipment next to me to create a control group for our tests against other samples you gather.]],logDesc=[[Gather Felwood Slime Samples from any of the slimes in Felwood. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most corrupt. Bring 5 of the Corrupted Felwood Samples you find to Chemist Fuely.]]}
DB[4294]={id=4294,zoneId=1497,name=[[... and a Batch of Ooze]],name_loc=[[... y unos mocos]],level=56,minLevel=48,giver=[[Chemist Fuely]],giver_loc=[[Químico Fuely]],giverType=[[NPC]],giverId=10136,ender=[[Chemist Fuely]],ender_loc=[[Químico Fuely]],enderType=[[NPC]],enderId=10136,nextId=4642,exGroup=-4293,poiX=1408,poiY=418,wowhead=[[https://www.wowhead.com/wotlk/quest=4294]],image=[[assets/images/quests/placeholder.png]],desc=[[Have you heard of the Un'Goro Crater, $N? It is near the Tanaris desert, and it is a magnificent place: lush, vibrant, full of creatures and plant life. It is there you must go. Word has reached me that the place seems completely untainted by outside hands. Explorers are just now discovering its secrets. I would like to test the slimes or oozes there. If it is true--that they are uncorrupt--then I would like to see how such creatures have evolved.]],logDesc=[[Gather Un'Goro Slime Samples from any of the slimes in Un'Goro Crater. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most pure. Bring 5 of the Pure Un'Goro Samples you find to Chemist Fuely.]]}
DB[4295]={id=4295,zoneId=1584,name=[[Rocknot's Ale]],name_loc=[[La cerveza de Sinroca]],level=1,minLevel=1,giver=[[Private Rocknot]],giver_loc=[[Soldado Sinroca]],giverType=[[NPC]],giverId=9503,ender=[[Private Rocknot]],ender_loc=[[Soldado Sinroca]],enderType=[[NPC]],enderId=9503,wowhead=[[https://www.wowhead.com/wotlk/quest=4295]],image=[[assets/images/quests/placeholder.png]]}
DB[4296]={id=4296,zoneId=46,name=[[Tablet of the Seven]],name_loc=[[La tablilla de los Siete]],level=50,minLevel=50,giver=[[Maxwort Uberglint]],giver_loc=[[Maxwort Suprandor]],giverType=[[NPC]],giverId=9536,ender=[[Maxwort Uberglint]],ender_loc=[[Maxwort Suprandor]],enderType=[[NPC]],enderId=9536,poiX=-7498,poiY=-2175,wowhead=[[https://www.wowhead.com/wotlk/quest=4296]],image=[[assets/images/quests/placeholder.png]],desc=[[I came to the Burning Steppes, following the legends of the Seven.  They were dwarves of great knowledge and power, and if you have knowledge and power, then wealth is sure to follow. That's what I want.  Wealth! If we can learn more of the Seven, then maybe we can get rich together.  The ruins of Thaurissan is rumored to keep the Tablet of the Seven, which holds knowledge of the ancient dwarves.  Find this tablet, copy its text and bring it to me.  Let's discover its secrets together!]],logDesc=[[Collect the Tablet Transcript.]]}
DB[4297]={id=4297,zoneId=357,name=[[Food for Baby]],name_loc=[[Comida para el bebé]],level=47,minLevel=38,giver=[[Agnar Beastamer]],giver_loc=[[Agnar Domabestias]],giverType=[[NPC]],giverId=9660,ender=[[Agnar Beastamer]],ender_loc=[[Agnar Domabestias]],enderType=[[NPC]],enderId=9660,prevId=3843,rewardNextId=4298,poiX=148,poiY=-4585,wowhead=[[https://www.wowhead.com/wotlk/quest=4297]],image=[[assets/images/quests/placeholder.png]],desc=[[Sprite darters are omnivores--that means they eat both meat and vegetation. If your egg here's gonna hatch, we best be prepared. Some good eats for these little guys are flanks of meat, raw and juicy, believe it or not. I was never able to find out why, but it has somethin' to do with Elune's plan for the elves... maybe they were to be protectors or somethin', I don't know. I'll take care of the egg for now, why don't you get me some good Silvermane stalker flanks for 'em to eat when he's hatched.]],logDesc=[[Bring 5 Silvermane Stalker Flanks to Agnar Beastamer in Hinterlands.]]}
DB[4298]={id=4298,zoneId=357,name=[[Becoming a Parent]],name_loc=[[El amor parental]],level=48,minLevel=37,giver=[[Agnar Beastamer]],giver_loc=[[Agnar Domabestias]],giverType=[[NPC]],giverId=9660,ender=[[Agnar Beastamer]],ender_loc=[[Agnar Domabestias]],enderType=[[NPC]],enderId=9660,prevId=4297,poiX=347,poiY=-2120,wowhead=[[https://www.wowhead.com/wotlk/quest=4298]],image=[[assets/images/quests/placeholder.png]],desc=[[Whoa, it was a lot more ready than I thought...]],logDesc=[[Speak to Agnar Beastamer in the Hinterlands.]],rewards={{id=11474,qty=1}}}
DB[4300]={id=4300,zoneId=1637,name=[[Bone-Bladed Weapons]],name_loc=[[Armas con filo de hueso]],level=52,minLevel=48,giver=[[Jes'rimon]],giverType=[[NPC]],giverId=8659,ender=[[Jes'rimon]],enderType=[[NPC]],enderId=8659,poiX=-7286,poiY=-2163,wowhead=[[https://www.wowhead.com/wotlk/quest=4300]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmm, maybe there be somethin' you can do for the Hand now that me think 'bout it. Yes, Jes'rimon could use your help for sure. In Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death. The Hand have... clients... that like weapons crafted from these claws. Bring me many of those white claws, and me pay you good coin. Do it fast enough, and maybe me help you in other ways.]],logDesc=[[Bring 8 White Ravasaur Claws to Jes'rimon in Orgrimmar.]],choiceRewards={{id=11862,qty=1},{id=11863,qty=1},{id=11864,qty=1}}}
DB[4301]={id=4301,zoneId=490,name=[[The Mighty U'cha]],name_loc=[[El poderoso U'cha]],level=55,minLevel=50,giver=[[Torwa Pathfinder]],giver_loc=[[Torwa Abrecaminos]],giverType=[[NPC]],giverId=9619,ender=[[Torwa Pathfinder]],ender_loc=[[Torwa Abrecaminos]],enderType=[[NPC]],enderId=9619,prevId=4289,poiX=-6268,poiY=-1996,wowhead=[[https://www.wowhead.com/wotlk/quest=4301]],image=[[assets/images/quests/placeholder.png]],desc=[[While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north. You have been to that cave before, but this time, I wonder if you'll survive the encounter if you accept my task. I call him U'cha, and he is one of the Earth Mother's greatest sons, of that you can be sure. Defeat U'cha and bring me his pelt. Do this, and I will defend your right to call yourself a great hunter.]],logDesc=[[Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.]],choiceRewards={{id=11906,qty=1},{id=11907,qty=1}}}
DB[4321]={id=4321,zoneId=490,name=[[Making Sense of It]],name_loc=[[Entender el significado]],level=53,minLevel=47,giver=[[J.D. Collie]],giver_loc=[[J.D. Collie]],giverType=[[NPC]],giverId=9117,ender=[[J.D. Collie]],ender_loc=[[J.D. Collie]],enderType=[[NPC]],enderId=9117,poiX=-6033,poiY=-1018,wowhead=[[https://www.wowhead.com/wotlk/quest=4321]],image=[[assets/images/quests/placeholder.png]],desc=[[The information you have given me about the pylons is very interesting... Give me a moment to do some calculations, $N. Speak to me again in a moment and I should be able to give you the answer we have been looking for.]],logDesc=[[Speak with J.D. Collie in a moment.]],rewards={{id=11482,qty=1}}}
DB[4322]={id=4322,zoneId=1584,name=[[Jail Break!]],name_loc=[[La fuga de la prisión]],level=58,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],prevId=4282,poiX=-8379,poiY=-2749,wowhead=[[https://www.wowhead.com/wotlk/quest=4322]],image=[[assets/images/quests/placeholder.png]],desc=[[We need to get out of here, $N. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell. He will give you further instruction.]],logDesc=[[Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.]],rewards={{id=12065,qty=1}},choiceRewards={{id=12061,qty=1},{id=12062,qty=1}}}
DB[4324]={id=4324,zoneId=1584,name=[[Yuka Screwspigot]],name_loc=[[Yuka Llavenrosca]],level=53,minLevel=48,giver=[[Yorba Screwspigot]],giver_loc=[[Yorba Llavenrosca]],giverType=[[NPC]],giverId=9706,ender=[[Yuka Screwspigot]],ender_loc=[[Yuka Llavenrosca]],enderType=[[NPC]],enderId=9544,rewardNextId=4136,poiX=-7460,poiY=-2202,wowhead=[[https://www.wowhead.com/wotlk/quest=4324]],image=[[assets/images/quests/placeholder.png]],desc=[[Although my little brother Ribbly has been worthless his whole life, I think, finally, he has some value!  But... we might need your help to capitalize on Ribbly's newfound worth. My sister Yuka has been looking for him for weeks, and tracked him to the Burning Steppes.  She sent word to me, asking for some hired hands. So, what do you say?  Want to help?  If so, then speak with my sister.  You'll find her holed up in Flame Crest, a cave northwest of Dreadmaul Rock.]],logDesc=[[Speak with Yuka Screwspigot in the Burning Steppes.]]}
DB[4341]={id=4341,zoneId=1584,name=[[Kharan Mighthammer]],name_loc=[[Kharan Martillo Poderoso]],level=59,minLevel=50,giver=[[King Magni Bronzebeard]],giver_loc=[[Rey Magni Barbabronce]],giverType=[[NPC]],giverId=2784,ender=[[Kharan Mighthammer]],ender_loc=[[Kharan Martillo Poderoso]],enderType=[[NPC]],enderId=9021,prevId=3701,nextId=4342,wowhead=[[https://www.wowhead.com/wotlk/quest=4341]],image=[[assets/images/quests/placeholder.png]],desc=[[You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl! <The King sobs.> And now she's gone, $N! I have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead! Kharan is supposedly being held prisoner there... find him! I want answers!]],logDesc=[[Travel to Blackrock Depths and find Kharan Mighthammer. The King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.]]}
DB[4342]={id=4342,zoneId=1584,name=[[Kharan's Tale]],name_loc=[[El relato de Kharan]],level=59,minLevel=50,giver=[[Kharan Mighthammer]],giver_loc=[[Kharan Martillo Poderoso]],giverType=[[NPC]],giverId=9021,ender=[[Kharan Mighthammer]],ender_loc=[[Kharan Martillo Poderoso]],enderType=[[NPC]],enderId=9021,prevId=4341,rewardNextId=4361,wowhead=[[https://www.wowhead.com/wotlk/quest=4342]],image=[[assets/images/quests/placeholder.png]],desc=[[Please, hear me out before passing judgement! ]],logDesc=[[Listen as Kharan Mighthammer tells his story.]]}
DB[4343]={id=4343,zoneId=361,name=[[Corrupted Windblossom]],name_loc=[[Flor del viento corrupta]],level=55,minLevel=48,giver=[[Corrupted Windblossom]],giver_loc=[[Flor del viento corrupta]],giverType=[[GO]],giverId=174603,ender=[[Corrupted Windblossom]],ender_loc=[[Flor del viento corrupta]],enderType=[[GO]],enderId=174603,poiX=6292,poiY=-589,wowhead=[[https://www.wowhead.com/wotlk/quest=4343]],image=[[assets/images/quests/placeholder.png]]}
DB[4361]={id=4361,zoneId=1584,name=[[The Bearer of Bad News]],name_loc=[[Portador de malas noticias]],level=59,minLevel=50,giver=[[Kharan Mighthammer]],giver_loc=[[Kharan Martillo Poderoso]],giverType=[[NPC]],giverId=9021,ender=[[King Magni Bronzebeard]],ender_loc=[[Rey Magni Barbabronce]],enderType=[[NPC]],enderId=2784,prevId=4342,rewardNextId=4362,poiX=-4866,poiY=-1023,wowhead=[[https://www.wowhead.com/wotlk/quest=4361]],image=[[assets/images/quests/placeholder.png]],desc=[[You must take this information back to King Magni, $N. He will know what to do! ]],logDesc=[[Return to Ironforge and deliver the bad news to King Magni Bronzebeard.]]}
DB[4362]={id=4362,zoneId=1584,name=[[The Fate of the Kingdom]],name_loc=[[El destino del reino]],level=59,minLevel=50,giver=[[King Magni Bronzebeard]],giver_loc=[[Rey Magni Barbabronce]],giverType=[[NPC]],giverId=2784,ender=[[Princess Moira Bronzebeard]],ender_loc=[[Princesa Moira Barbabronce]],enderType=[[NPC]],enderId=8929,prevId=4361,rewardNextId=4363,wowhead=[[https://www.wowhead.com/wotlk/quest=4362]],image=[[assets/images/quests/placeholder.png]],desc=[[It would seem as if my old adversary, Dagran Thaurissan, has me and the kingdom of Ironforge at his mercy. You may be my last hope, $N. You must rescue my dear daughter, Moira! There is only one way to make sure that the spell Thaurissan has cast on Moira is broken: Kill him. And $N, do not harm her! Remember, she is being controlled by Thaurissan! The things she may do or say are a result of Thaurissan's evil spell!]],logDesc=[[Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan. ]]}
DB[4363]={id=4363,zoneId=1584,name=[[The Princess's Surprise]],name_loc=[[La sorpresa de la princesa]],level=59,minLevel=50,giver=[[Princess Moira Bronzebeard]],giver_loc=[[Princesa Moira Barbabronce]],giverType=[[NPC]],giverId=8929,ender=[[King Magni Bronzebeard]],ender_loc=[[Rey Magni Barbabronce]],enderType=[[NPC]],enderId=2784,prevId=4362,poiX=-4866,poiY=-1023,wowhead=[[https://www.wowhead.com/wotlk/quest=4363]],image=[[assets/images/quests/placeholder.png]],desc=[[Thaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child! <You think that Princess Bronzebeard may still be suffering from the residual effect of the Emperor's spell.> Return to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf. Whether he approves or not, it shall be.]],logDesc=[[Return to Ironforge and speak with King Magni Bronzebeard.]],choiceRewards={{id=12548,qty=1},{id=12543,qty=1}}}
