DB[4421]={id=4421,zoneId=361,name=[[The Corruption of the Jadefire]],name_loc=[[La corrupción de los Fuego de Jade]],level=54,minLevel=49,giver=[[Eridan Bluewind]],giver_loc=[[Eridan Vientoazul]],giverType=[[NPC]],giverId=9116,ender=[[Eridan Bluewind]],ender_loc=[[Eridan Vientoazul]],enderType=[[NPC]],enderId=9116,poiX=4471,poiY=-550,wowhead=[[https://www.wowhead.com/wotlk/quest=4421]],image=[[assets/images/quests/placeholder.png]],desc=[[Not many seek adventure here... Felwood's corruption is widespread and indiscriminate. As part of the Emerald Circle, I seek to heal this land, but there are some that wish it to fester. The ones I speak of are the Jadefire satyrs that dwell to the northwest of here, at the Ruins of Constellas. Led by a particularly cruel satyr named Xavathras, they continue to spread the disease to any creatures they encounter. We must defend this land that was once ours. Defeat Xavathras and destroy his minions.]],logDesc=[[Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed.]]}
DB[4441]={id=4441,zoneId=361,name=[[Felbound Ancients]],name_loc=[[Los Ancestros corrompidos]],level=54,minLevel=49,giver=[[Eridan Bluewind]],giver_loc=[[Eridan Vientoazul]],giverType=[[NPC]],giverId=9116,ender=[[Eridan Bluewind]],ender_loc=[[Eridan Vientoazul]],enderType=[[NPC]],enderId=9116,prevId=939,poiX=4009,poiY=-1311,wowhead=[[https://www.wowhead.com/wotlk/quest=4441]],image=[[assets/images/quests/placeholder.png]],desc=[[The flute you found was carved from an ancient protector, the treant allies that have faithfully protected the night elves. The satyrs have been able to corrupt anything they come in contact with, which includes the ancients that made Felwood their home. By the use of the fel, the spirit of the ancient has been bound and tortured, never completely released. The felbind you found is no doubt related. We must try to purify the flute, $N. Bring me blessed water from the Temple of the Moon in Darnassus.]],logDesc=[[Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial.]]}
DB[4442]={id=4442,zoneId=361,name=[[Purified!]],name_loc=[[¡Purificada!]],level=54,minLevel=49,giver=[[Eridan Bluewind]],giver_loc=[[Eridan Vientoazul]],giverType=[[NPC]],giverId=9116,ender=[[Eridan Bluewind]],ender_loc=[[Eridan Vientoazul]],enderType=[[NPC]],enderId=9116,prevId=4441,poiX=4009,poiY=-1311,wowhead=[[https://www.wowhead.com/wotlk/quest=4442]],image=[[assets/images/quests/placeholder.png]],desc=[[Using the water of Elune, I will attempt to purify the flute. We must end this suffering... May Elune guide my hands and heart. Speak with me again in a moment.]],logDesc=[[Speak to Eridan again in a moment.]],rewards={{id=11445,qty=1}}}
