DB[4449]={id=4449,zoneId=51,name=[[Caught!]],name_loc=[[Atrapado]],level=45,minLevel=43,giver=[[Wooden Outhouse]],giver_loc=[[Letrina de madera]],giverType=[[GO]],giverId=173265,ender=[[Wooden Outhouse]],ender_loc=[[Letrina de madera]],enderType=[[GO]],enderId=173265,rewardNextId=4450,poiX=-6999,poiY=-1750,wowhead=[[https://www.wowhead.com/wotlk/quest=4449]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey! Hey, you! Get over here! Ya gotta help me out. I was runnin' from them Dark Iron dwarves, and I hid in here to get out of sight. Damn geologists and their magic ways! They musta seen me hide, cause next thing I knew, they locked the door and stuck me in here. Teach them geologists a lesson! Oh... an' can ya get me some pieces of silk cloth for... for... nothin'.]],logDesc=[[Kill 8 Dark Iron Geologists and bring 15 pieces of Silk Cloth to the person locked in the outhouse in Searing Gorge.]]}
DB[4450]={id=4450,zoneId=51,name=[[Ledger from Tanaris]],name_loc=[[El libro de contabilidad de Tanaris]],level=46,minLevel=43,giver=[[Wooden Outhouse]],giver_loc=[[Letrina de madera]],giverType=[[GO]],giverId=173265,ender=[[Krinkle Goodsteel]],ender_loc=[[Krinkle Buenacero]],enderType=[[NPC]],enderId=5411,prevId=4449,poiX=-7025,poiY=-1784,wowhead=[[https://www.wowhead.com/wotlk/quest=4450]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, you know what? That reminds me. You wanna finish up a little job I took up while I was in Tanaris? It's easy... Krinkle Goodsteel in Gadgetzan was lookin' for some stuff found here in Searing Gorge and a few other places. Maybe you could take a look at the list and then bring it all to him? I'll just slide his ledger under the door if you're interested. Take that, and the stuff he wants back to him after ya collected it all.]],logDesc=[[Take the copy of Goodsteel's Ledger and then find the items listed in it before seeking Krinkle Goodsteel in Tanaris.]],choiceRewards={{id=11860,qty=1},{id=11861,qty=1}}}
DB[4451]={id=4451,zoneId=51,name=[[The Key to Freedom]],name_loc=[[La llave de la libertad]],level=47,minLevel=43,giverType=[[NPC]],ender=[[Wooden Outhouse]],ender_loc=[[Letrina de madera]],enderType=[[GO]],enderId=173265,poiX=-7004,poiY=-1151,wowhead=[[https://www.wowhead.com/wotlk/quest=4451]],image=[[assets/images/quests/placeholder.png]],desc=[[The small brass key looks simple enough.. The only thing that seems to make it stand out are some words scratched into the head of it: "Dark Iron Outhouse - Do Not Duplicate." You have no idea what it means or what it will lead to.]],logDesc=[[Search Searing Gorge and find a use for the Grimesilt Outhouse Key you have found.]]}
