DB[4605]={id=4605,zoneId=133,name=[[The Sparklematic 5200!]],name_loc=[[¡El Destellamatic 5200!]],level=30,minLevel=25,giver=[[The Sparklematic 5200]],giver_loc=[[El Destellamatic 5200]],giverType=[[GO]],giverId=175084,ender=[[The Sparklematic 5200]],ender_loc=[[El Destellamatic 5200]],enderType=[[GO]],enderId=175084,prevId=4601,wowhead=[[https://www.wowhead.com/wotlk/quest=4605]],image=[[assets/images/quests/placeholder.png]],rewards={{id=9363,qty=1}}}
DB[4606]={id=4606,zoneId=133,name=[[The Sparklematic 5200!]],name_loc=[[¡El Destellamatic 5200!]],level=30,minLevel=25,giver=[[The Sparklematic 5200]],giver_loc=[[El Destellamatic 5200]],giverType=[[GO]],giverId=175085,ender=[[The Sparklematic 5200]],ender_loc=[[El Destellamatic 5200]],enderType=[[GO]],enderId=175085,prevId=4602,wowhead=[[https://www.wowhead.com/wotlk/quest=4606]],image=[[assets/images/quests/placeholder.png]],rewards={{id=9363,qty=1}}}
DB[4621]={id=4621,zoneId=33,name=[[Avast Ye, Admiral!]],name_loc=[[¡Adelante, almirante!]],level=60,minLevel=55,giver=[[Fleet Master Firallon]],giver_loc=[[Maestro de flota Firallon]],giverType=[[NPC]],giverId=2546,ender=[[Fleet Master Firallon]],ender_loc=[[Maestro de flota Firallon]],enderType=[[NPC]],enderId=2546,poiX=-14439,poiY=483,wowhead=[[https://www.wowhead.com/wotlk/quest=4621]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen close, sea dawg... the powers of Booty Bay is what keeps us Bloodsail from sailing wheres we like and taking whats we want as rights o' plunder.  Were ye to put a knife to Fleet Master Seahorn, we'd ne'er run afoul of a Booty Bay's vessel.  Were ye to put a knife to Baron Revilgaz, we'd ne'er face the law on their terms. If ye are to be an honorary admiral amongst us - yes, ADMIRAL, you'll puts a knife to both of 'em as I've says.  Go now $g lad : lass;, and return to me once ye does the deeds.]],logDesc=[[Slay Fleet Master Seahorn and Baron Revilgaz of Booty Bay, and then return to Fleet Master Firallon aboard the Crimson Veil off the coast of Stranglethorn Vale.]],rewards={{id=12185,qty=1}}}
DB[4641]={id=4641,zoneId=363,name=[[Your Place In The World]],name_loc=[[Tu lugar en el mundo]],level=1,minLevel=1,giver=[[Kaltunk]],giverType=[[NPC]],giverId=10176,ender=[[Gornek]],enderType=[[NPC]],enderId=3143,rewardNextId=788,poiX=-600,poiY=-4186,wowhead=[[https://www.wowhead.com/wotlk/quest=4641]],image=[[assets/images/quests/placeholder.png]],desc=[[Finally, you are of age, $N... of age to battle in the name of the Horde. To conquer for the glory of the Warchief. Yes... <Kaltunk looks you over.> You will do nicely. No doubt you wish to find a great dragon or demon and strangle it with your bare hands, but perhaps it would be wise to start on something less... dangerous. <Kaltunk laughs.> Report to Gornek, he should be able to assign a task better suited to a young $c. You will find Gornek in the Den, to the west. ]],logDesc=[[Speak with Gornek. You recall Kaltunk marking your map with his location and mentioning that Gornek resided in the Den, a building to the west.  ]]}
DB[4642]={id=4642,zoneId=1497,name=[[Melding of Influences]],name_loc=[[Fusión de influencias]],level=55,minLevel=48,giver=[[Chemist Fuely]],giver_loc=[[Químico Fuely]],giverType=[[NPC]],giverId=10136,ender=[[Chemist Fuely]],ender_loc=[[Químico Fuely]],enderType=[[NPC]],enderId=10136,poiX=1408,poiY=418,wowhead=[[https://www.wowhead.com/wotlk/quest=4642]],image=[[assets/images/quests/placeholder.png]],desc=[[Here is some encased ooze created from the Felwood samples you recovered. Take the case to Un'Goro Crater and find a pure ooze... the primal variety will do nicely. When you get close enough, release the ooze in the case, and let us see what the two think of one another. After the experiment concludes, bring me a sample of whatever is left over. I will await you here in the Apothecarium.]],logDesc=[[Bring a Merged Ooze Sample to Chemist Fuely in Undercity.]],choiceRewards={{id=15702,qty=1},{id=15703,qty=1}}}
DB[4661]={id=4661,zoneId=1497,name=[[Testing for Corruption - Felwood]],name_loc=[[Pruebas de Corrupción: Frondavil]],level=52,minLevel=48,giver=[[Testing Equipment]],giver_loc=[[Equipo de pruebas]],giverType=[[GO]],giverId=174848,ender=[[Testing Equipment]],ender_loc=[[Equipo de pruebas]],enderType=[[GO]],enderId=174848,poiX=4872,poiY=-711,wowhead=[[https://www.wowhead.com/wotlk/quest=4661]],image=[[assets/images/quests/placeholder.png]],rewards={{id=15103,qty=1}}}
DB[4681]={id=4681,zoneId=148,name=[[Washed Ashore]],name_loc=[[Varado]],level=14,minLevel=11,giver=[[Gwennyth Bly'Leggonde]],giverType=[[NPC]],giverId=10219,ender=[[Gwennyth Bly'Leggonde]],enderType=[[NPC]],enderId=10219,prevId=3524,poiX=6311,poiY=857,wowhead=[[https://www.wowhead.com/wotlk/quest=4681]],image=[[assets/images/quests/placeholder.png]],desc=[[That beached creature is not an isolated incident here in Darkshore.  There are more along the coastline and even in the water.  I would like for you to investigate another one that we know of; this one was reported to be in the water due west of Auberdine, close to a sunken vessel.  Return to me with anything that you may recover that would aid our research. Also, in your travels you may find other creatures.  By all means, if you should discover anything then please bring it to our attention!]],logDesc=[[Recover the Sea Turtle Remains from the Skeletal Sea Turtle in the waters west of Auberdine, and then speak with Gwennyth Bly'Leggonde back in Auberdine.]],choiceRewards={{id=15398,qty=1},{id=15399,qty=1},{id=15400,qty=1}}}
DB[4701]={id=4701,zoneId=1583,name=[[Put Her Down]],name_loc=[[Acaba con el origen de la amenaza]],level=59,minLevel=55,giver=[[Helendis Riverhorn]],giver_loc=[[Helendis Rivacuerno]],giverType=[[NPC]],giverId=9562,ender=[[Helendis Riverhorn]],ender_loc=[[Helendis Rivacuerno]],enderType=[[NPC]],enderId=9562,poiX=-8377,poiY=-2780,wowhead=[[https://www.wowhead.com/wotlk/quest=4701]],image=[[assets/images/quests/placeholder.png]],desc=[[You have no doubt seen the worgs which the Blackrock orcs command. It is curious - no matter how many we destroy, their numbers never dwindle. My scouts have reported that the worgs are bred, trained, and ultimately exported from Blackrock Spire: capital city of the Blackrock orcs. You must travel to Blackrock Spire and discover the source of this menace. Discover... and destroy. Good luck, $N. May Cenarius protect you... ]],logDesc=[[Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg.]],choiceRewards={{id=15824,qty=1},{id=15825,qty=1},{id=15827,qty=1}}}
DB[4721]={id=4721,zoneId=361,name=[[Wild Guardians]],name_loc=[[Guardianes salvajes]],level=59,minLevel=52,giver=[[Trull Failbane]],giver_loc=[[Trull Fallarruina]],giverType=[[NPC]],giverId=10306,ender=[[Trull Failbane]],ender_loc=[[Trull Fallarruina]],enderType=[[NPC]],enderId=10306,prevId=4741,poiX=5694,poiY=-5047,wowhead=[[https://www.wowhead.com/wotlk/quest=4721]],image=[[assets/images/quests/placeholder.png]],desc=[[Runners have returned from Winterspring with reports that there is a series of small caves in the southern area of Winterspring. It seems that there are wildkin situated in the area around these caves. If there is something valuable that they are guarding, I believe that this is the place we will find it. You will find these to be more of a challenge than the previous types, $N. The creatures seem to have gone mad from exposure to the very thing that they strive to protect.]],logDesc=[[Trull Failbane in Felwood wants you to hunt 10 Berserk Owlbeasts in Winterspring.]]}
DB[4722]={id=4722,zoneId=148,name=[[Beached Sea Turtle]],name_loc=[[Tortuga marina varada]],level=13,minLevel=11,giver=[[Beached Sea Turtle]],giver_loc=[[Tortuga marina varada]],giverType=[[GO]],giverId=176190,ender=[[Gwennyth Bly'Leggonde]],enderType=[[NPC]],enderId=10219,prevId=4681,poiX=6311,poiY=857,wowhead=[[https://www.wowhead.com/wotlk/quest=4722]],image=[[assets/images/quests/placeholder.png]],desc=[[You find a corpse of a sea turtle that had beached itself on the coast of Darkshore some time ago.  It has been scavenged by the murlocs who have encamped themselves around the creature's remains.  Still, there appear to be some suitable samples left on the creature's remains that Gwennyth Bly'Leggonde in Auberdine might be able to make use of.]],logDesc=[[Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.]]}
DB[4723]={id=4723,zoneId=148,name=[[Beached Sea Creature]],name_loc=[[Criatura marina varada]],level=13,minLevel=11,giver=[[Beached Sea Creature]],giverType=[[GO]],giverId=175233,ender=[[Gwennyth Bly'Leggonde]],enderType=[[NPC]],enderId=10219,prevId=4681,poiX=6110,poiY=560,wowhead=[[https://www.wowhead.com/wotlk/quest=4723]],image=[[assets/images/quests/placeholder.png]],desc=[[The remains of a giant thresher - much larger than one you'd expect to find in Darkshore - lie beached on the coast of the Mist's Edge.  How this creature came to be here is unknown; the group of murlocs that now feast off the carcass of it seem to be much too weak, even in large numbers, to have brought down the beast.  While some of it has been picked clean, enough of it remains to take a sample for Gwennyth Bly'Leggonde in Auberdine to study.]],logDesc=[[Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.]]}
DB[4724]={id=4724,zoneId=1583,name=[[The Pack Mistress]],name_loc=[[La maestra de la manada]],level=59,minLevel=55,giver=[[Galamav the Marksman]],giver_loc=[[Galamav el Tirador]],giverType=[[NPC]],giverId=9081,ender=[[Galamav the Marksman]],ender_loc=[[Galamav el Tirador]],enderType=[[NPC]],enderId=9081,poiX=-6681,poiY=-2227,wowhead=[[https://www.wowhead.com/wotlk/quest=4724]],image=[[assets/images/quests/placeholder.png]],desc=[[Some say the worg controlled by the Blackrock orcs are the creation of a supernatural force. Others say they are not true worg but instead a breed of demon dog, granted to the orcs by a fallen pit lord. The truth is far less contrived but every bit as frightening. The worg of Blackrock come from Halycon and her mate. Halycon is the gigantic den mother of the worg. Her mate? Nobody has ever lived to tell the tale of that one. Strike at the heart of the worg. Destroy Halycon... and $N, watch your back.]],logDesc=[[Slay Halycon, pack mistress of the Bloodaxe worg.]],choiceRewards={{id=15824,qty=1},{id=15825,qty=1},{id=15827,qty=1}}}
DB[4725]={id=4725,zoneId=148,name=[[Beached Sea Turtle]],name_loc=[[Tortuga marina varada]],level=15,minLevel=12,giver=[[Beached Sea Turtle]],giverType=[[GO]],giverId=176197,ender=[[Gwennyth Bly'Leggonde]],enderType=[[NPC]],enderId=10219,prevId=4681,poiX=6342,poiY=543,wowhead=[[https://www.wowhead.com/wotlk/quest=4725]],image=[[assets/images/quests/placeholder.png]],desc=[[More sea turtle remains lie beached along the coastline.  This particular set has an abandoned carriage attached to the turtle's shell.  Perhaps this creature was driven to the shoreline by unknown beings rather than beaching itself as some of the other remains suggested.  Greymist murlocs now make the remains of this creature their home, feasting off the carrion. In the carriage, you find a box with strange markings on it; perhaps Gwennyth Bly'Leggonde in Auberdine can make sense of it.]],logDesc=[[Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine.]]}
DB[4726]={id=4726,zoneId=46,name=[[Broodling Essence]],name_loc=[[Esencia de cría]],level=52,minLevel=50,giver=[[Tinkee Steamboil]],giver_loc=[[Tinkee Vaporio]],giverType=[[NPC]],giverId=10267,ender=[[Tinkee Steamboil]],ender_loc=[[Tinkee Vaporio]],enderType=[[NPC]],enderId=10267,rewardNextId=4808,poiX=-7500,poiY=-2178,wowhead=[[https://www.wowhead.com/wotlk/quest=4726]],image=[[assets/images/quests/placeholder.png]],desc=[[I have been studying the dragonkin of the Burning Steppes for weeks, and I think I've finally had a breakthrough!  I created a device--I call it the Draco Incarcinatrix 900.  It can capture the essence of dragon whelp broodlings! Or, at least I think it can. Here, take the device and zap a broodling in the Burning Steppes with it.  While it's under the device's effects, defeat the broodling and its essence should be released. If it is, then splendid!  Bring me back samples so I can study them!]],logDesc=[[Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.]]}
DB[4727]={id=4727,zoneId=148,name=[[Beached Sea Turtle]],name_loc=[[Tortuga marina varada]],level=15,minLevel=12,giver=[[Beached Sea Turtle]],giver_loc=[[Tortuga marina varada]],giverType=[[GO]],giverId=176196,ender=[[Gwennyth Bly'Leggonde]],enderType=[[NPC]],enderId=10219,prevId=4681,poiX=6311,poiY=857,wowhead=[[https://www.wowhead.com/wotlk/quest=4727]],image=[[assets/images/quests/placeholder.png]],desc=[[The skeletal remains of a sea turtle lie in the sand of the northern Darkshore beaches.  The Greymist murlocs have either not found this carcass, or perhaps they have and are shying away from it for some unknown reason.  Regardless, there is enough of the turtle left to take a sample back to Gwennyth Bly'Leggonde in Auberdine for the Temple of the Moon to study.]],logDesc=[[Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.]]}
DB[4728]={id=4728,zoneId=148,name=[[Beached Sea Creature]],name_loc=[[Criatura marina varada]],level=14,minLevel=12,giver=[[Beached Sea Creature]],giverType=[[GO]],giverId=175226,ender=[[Gwennyth Bly'Leggonde]],enderType=[[NPC]],enderId=10219,prevId=4681,poiX=6110,poiY=560,wowhead=[[https://www.wowhead.com/wotlk/quest=4728]],image=[[assets/images/quests/placeholder.png]],desc=[[The corpse of what appears to be some sort of giant sea mammal lies partially gutted on the beach.  A wheelbarrow and various tools lie abandoned by this enormous beached sea creature, as though an attempt to study it had been made previously.  Though murlocs have scavenged this beast, enough of it remains to gather a suitable sample for Gwennyth Bly'Leggonde in Auberdine.]],logDesc=[[Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.]]}
DB[4729]={id=4729,zoneId=1583,name=[[Kibler's Exotic Pets]],name_loc=[[Las mascotas exóticas de Kibler]],level=59,minLevel=55,giver=[[Kibler]],giverType=[[NPC]],giverId=10260,ender=[[Kibler]],enderType=[[NPC]],enderId=10260,poiX=-7459,poiY=-2197,wowhead=[[https://www.wowhead.com/wotlk/quest=4729]],image=[[assets/images/quests/placeholder.png]],desc=[[You're probably wondering what I'm doing out here. Look at the cages! Ain't it obvious? I'm an animal lover, first and foremost, but a salesman by trade. I track down exotic animals for the rich and famous and domesticate the beasts so they behave as proper pets. Now you're probably wondering, "What can I do for you, Kibler." The answer is simple: Take this here beast cage and find me some worg pups. For that, I'll domesticate a worg for you! ]],logDesc=[[Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler.]],rewards={{id=12264,qty=1}}}
DB[4730]={id=4730,zoneId=148,name=[[Beached Sea Creature]],name_loc=[[Criatura marina varada]],level=16,minLevel=12,giver=[[Beached Sea Creature]],giver_loc=[[Criatura marina varada]],giverType=[[GO]],giverId=175227,ender=[[Gwennyth Bly'Leggonde]],enderType=[[NPC]],enderId=10219,prevId=4681,poiX=6110,poiY=560,wowhead=[[https://www.wowhead.com/wotlk/quest=4730]],image=[[assets/images/quests/placeholder.png]],desc=[[The half-devoured corpse of what might have been a giant sea mammal lies on the beach.  A band of murlocs, stronger than those found closer to Auberdine, have taken up residence around the fallen creature.  Enough of the creature remains that a suitable sample of its bones could be delivered to Gwennyth Bly'Leggonde in Auberdine.]],logDesc=[[Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.]]}
DB[4731]={id=4731,zoneId=148,name=[[Beached Sea Turtle]],name_loc=[[Tortuga marina varada]],level=19,minLevel=13,giver=[[Beached Sea Turtle]],giverType=[[GO]],giverId=176198,ender=[[Gwennyth Bly'Leggonde]],enderType=[[NPC]],enderId=10219,prevId=4681,poiX=6342,poiY=543,wowhead=[[https://www.wowhead.com/wotlk/quest=4731]],image=[[assets/images/quests/placeholder.png]],desc=[[Another set of sea turtle remains lie beached on the coastline.  This set of remains has an abandoned carriage half buckled to the turtle's shell.  Perhaps this creature was driven to the shoreline by unknown beings rather than beaching itself as some of the other remains suggested.  Powerful Greymist murlocs have made the carcass of this creature their current home. In the carriage, you find a box with strange markings on it; perhaps Gwennyth Bly'Leggonde in Auberdine can make sense of it.]],logDesc=[[Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine.]]}
DB[4732]={id=4732,zoneId=148,name=[[Beached Sea Turtle]],name_loc=[[Tortuga marina varada]],level=19,minLevel=13,giver=[[Beached Sea Turtle]],giverType=[[GO]],giverId=176191,ender=[[Gwennyth Bly'Leggonde]],enderType=[[NPC]],enderId=10219,prevId=4681,poiX=6311,poiY=857,wowhead=[[https://www.wowhead.com/wotlk/quest=4732]],image=[[assets/images/quests/placeholder.png]],desc=[[You find a corpse of a sea turtle that had beached itself on the coast of Darkshore some time ago.  It has been picked nearly clean by Greymist murlocs, the very ones who now have encamped themselves around the creature's remains.  Still, there appear to be some suitable samples left on the creature's remains that Gwennyth Bly'Leggonde in Auberdine might be able to make use of.]],logDesc=[[Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.]]}
DB[4733]={id=4733,zoneId=148,name=[[Beached Sea Creature]],name_loc=[[Criatura marina varada]],level=19,minLevel=13,giver=[[Beached Sea Creature]],giverType=[[GO]],giverId=175230,ender=[[Gwennyth Bly'Leggonde]],enderType=[[NPC]],enderId=10219,prevId=4681,poiX=6110,poiY=560,wowhead=[[https://www.wowhead.com/wotlk/quest=4733]],image=[[assets/images/quests/placeholder.png]],desc=[[The remains of what appear to be a giant thresher have washed ashore on the rocky inlet of the Twilight Shore.  The thresher is several times larger than any of the other threshers spotted in these parts.  Wherever it came from, this creature would not seem to have been native to Darkshore. Though the creature has been picked apart in places, enough of it remains to gather a suitable sample for Gwennyth Bly'Leggonde in Auberdine.]],logDesc=[[Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.]]}
DB[4734]={id=4734,zoneId=1583,name=[[Egg Freezing]],name_loc=[[Un huevo congelado]],level=60,minLevel=57,giver=[[Tinkee Steamboil]],giver_loc=[[Tinkee Vaporio]],giverType=[[NPC]],giverId=10267,ender=[[Tinkee Steamboil]],ender_loc=[[Tinkee Vaporio]],enderType=[[NPC]],enderId=10267,prevId=4810,poiX=-7500,poiY=-2178,wowhead=[[https://www.wowhead.com/wotlk/quest=4734]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I've been working hard on a new device, the eggscilloscope!  It's designed to project a burst of cold energy at the egg of a black dragon... and freeze it solid!  Can you test it for me? I heard that high up in Blackrock Spire, the dragons have a rookery where they hatch their eggs.  That's where you'll have to go to test the eggscilloscope, and then let me know how it worked! And don't worry.  Frozen dragon eggs should be harmless.  It's the unfrozen ones you have to worry about!]],logDesc=[[Use the Eggscilloscope Prototype on an egg in the Rookery of Blackrock Spire.]],rewards={{id=12144,qty=1}}}
DB[4735]={id=4735,zoneId=1583,name=[[Egg Collection]],name_loc=[[La colecta de huevos]],level=60,minLevel=57,giver=[[Tinkee Steamboil]],giver_loc=[[Tinkee Vaporio]],giverType=[[NPC]],giverId=10267,ender=[[Tinkee Steamboil]],ender_loc=[[Tinkee Vaporio]],enderType=[[NPC]],enderId=10267,prevId=4734,nextId=5522,poiX=-7500,poiY=-2178,wowhead=[[https://www.wowhead.com/wotlk/quest=4735]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I'm finally ready for real samples of dragon eggs!  Here, take this collectronic module.  It's designed to extract a dragon egg and prepare it for transport.  Go back to the Rookery and use the module to collect eggs. And don't forget to freeze them first, or they might hatch before you can collect them! When you have enough eggs, bring them to me!]],logDesc=[[Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.]]}
DB[4736]={id=4736,name=[[In Search of Menara Voidrender]],name_loc=[[Buscando a Menara Nadiz]],level=31,minLevel=31,giver=[[Briarthorn]],giver_loc=[[Brezospina]],giverType=[[NPC]],giverId=5172,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,rewardNextId=1796,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4736]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, hello, $N. You're progressing well in your training. So well in fact that I think you should be rewarded for your hard work--and for not becoming corrupted by the arcane yet. If you're interested, seek out Menara Voidrender in Ratchet. She is currently staying at Strahad Farsan's tower overlooking the town. She's not very friendly, $N, so don't expect any praise. But if you work hard, she'll make sure you're taken care of.]],logDesc=[[Speak to Menara Voidrender in the Barrens.]]}
DB[4737]={id=4737,name=[[In Search of Menara Voidrender]],name_loc=[[Buscando a Menara Nadiz]],level=31,minLevel=31,giver=[[Zevrost]],giver_loc=[[Zevrost]],giverType=[[NPC]],giverId=3326,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,rewardNextId=1796,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4737]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmph, still you strive to become more powerful. I say it's only time before the corruption and addiction takes hold of you and you become a slave to that which you seek to gain power over. Pfah! A fool you are! Time will prove me right--nothing else... just time. But it seems that not all agree with Zevrost. It seems Menara would create tools for you to become more powerful and to harness your strength. If you're interested, then go to Ratchet in the Barrens. She is there overlooking the town.]],logDesc=[[Speak to Menara Voidrender in the Barrens.]]}
DB[4738]={id=4738,name=[[In Search of Menara Voidrender]],name_loc=[[Buscando a Menara Nadiz]],level=31,minLevel=31,giver=[[Demisette Cloyce]],giver_loc=[[Demisette Cloyce]],giverType=[[NPC]],giverId=461,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,rewardNextId=1796,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4738]],image=[[assets/images/quests/placeholder.png]],desc=[[Let us be clear about one thing, $N: I don't feel you are ready for such responsibilities. I don't think aiding in the creation of any item of power is something a novice should ever be involved in; especially one so untested. But that's not my decision. The powers that be, or at least the ones that do wish to impart such gifts upon you get to decide that. If you're interested in learning more, I suggest you seek out Menara Voidrender in Ratchet. She usually resides in the tower above the port town.]],logDesc=[[Speak with Menara Voidrender in the Barrens.]]}
DB[4739]={id=4739,name=[[In Search of Menara Voidrender]],name_loc=[[Buscando a Menara Nadiz]],level=31,minLevel=31,giver=[[Kaal Soulreaper]],giver_loc=[[Kaal Segador de Almas]],giverType=[[NPC]],giverId=4563,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,rewardNextId=1796,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4739]],image=[[assets/images/quests/placeholder.png]],desc=[[$C! Yes, you! You don't have all the accoutrements, but it's plain to see you're ready--the air around you exudes greater confidence. Yes, I see it now. Menara Voidrender would teach you a few things if you feel you're ready. She spends her time tutoring younger students in the arcane. She even gives gifts to those who pass her tests. Go to Ratchet in the Barrens if you're interested. She's above the city in Strahad's tower.]],logDesc=[[Speak to Menara Voidrender in the Barrens.]]}
DB[4740]={id=4740,zoneId=148,name=[[WANTED: Murkdeep!]],name_loc=[[SE BUSCA: ¡Viscoso!]],level=18,minLevel=9,giver=[[WANTED: Murkdeep!]],giverType=[[GO]],giverId=175320,ender=[[Sentinel Glynda Nal'Shea]],ender_loc=[[Centinela Glynda Nal'Shea]],enderType=[[NPC]],enderId=2930,poiX=4993,poiY=617,wowhead=[[https://www.wowhead.com/wotlk/quest=4740]],image=[[assets/images/quests/placeholder.png]],desc=[[Attention! A reward is being offered for the death of the murloc "Murkdeep".  This foul beast is known to be responsible for the death of at least one Sentinel, and is suspected of causing the sinking of at least two cargo vessels in the waters off Darkshore! Murkdeep was last spotted at a hutted murloc camp south of Auberdine, and is thought to be protecting the huts there.  Reward claims for this bounty should be claimed with Sentinel Glynda Nal'Shea in Auberdine. The Auberdine Village Council]],logDesc=[[Find and slay the murloc known as Murkdeep.  The creature is thought to be defending the murloc huts south of Auberdine along the water. Report the death of Murkdeep to Sentinel Glynda Nal'Shea in Auberdine.]],choiceRewards={{id=5315,qty=1},{id=15403,qty=1},{id=15404,qty=1}}}
DB[4741]={id=4741,zoneId=361,name=[[Wild Guardians]],name_loc=[[Guardianes salvajes]],level=58,minLevel=52,giver=[[Trull Failbane]],giver_loc=[[Trull Fallarruina]],giverType=[[NPC]],giverId=10306,ender=[[Trull Failbane]],ender_loc=[[Trull Fallarruina]],enderType=[[NPC]],enderId=10306,prevId=4521,rewardNextId=4721,poiX=5694,poiY=-5047,wowhead=[[https://www.wowhead.com/wotlk/quest=4741]],image=[[assets/images/quests/placeholder.png]],desc=[[In the northern areas of Winterspring, the Wildkin grow even more ferocious. We must continue our measures there. Hunt the moontouched owlbeasts in Winterspring, and explore the area they inhabit. This is dangerous ground, but I know that you will be able to handle the challenge. Return to me after you have slain 13 of the wildkin.]],logDesc=[[Trull Failbane in Felwood wants you to hunt 13 Moontouched Owlbeasts.]]}
DB[4742]={id=4742,zoneId=1583,name=[[Seal of Ascension]],name_loc=[[El sello de ascensión]],level=60,minLevel=57,giver=[[Vaelan]],giver_loc=[[Acride]],giverType=[[NPC]],giverId=10296,ender=[[Vaelan]],ender_loc=[[Acride]],enderType=[[NPC]],enderId=10296,rewardNextId=4743,wowhead=[[https://www.wowhead.com/wotlk/quest=4742]],image=[[assets/images/quests/placeholder.png]],desc=[[As you can see, the unadorned seal has three empty sockets. Each of those sockets must be filled with a gemstone representing the leadership's command. Finally, Overlord Wyrmthalak, master of the lower citadel, must forge the seal in the flames of the Black Dragonflight. Understand this, mortal: the chance that one of the three generals of the lower citadel would carry a gemstone at any given time is rare. You must be vigilant in your quest. Remain determined!]],logDesc=[[Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan. The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak  of the Bloodaxe.]]}
DB[4743]={id=4743,zoneId=1583,name=[[Seal of Ascension]],name_loc=[[El sello de ascensión]],level=60,minLevel=57,giver=[[Vaelan]],giver_loc=[[Acride]],giverType=[[NPC]],giverId=10296,ender=[[Vaelan]],ender_loc=[[Acride]],enderType=[[NPC]],enderId=10296,prevId=4742,wowhead=[[https://www.wowhead.com/wotlk/quest=4743]],image=[[assets/images/quests/placeholder.png]],desc=[[Few of the black dragonkin, outside of those in the upper citadel, have the ability to forge the seal with their own flaming breath. Wyrmthalak is one such dragonkin, but his will is unbreakable. You must travel to the Wyrmbog in Dustwallow Marsh. It is there that you will find an ancient drake known as Emberstrife. You must break his will, $N. Break it and use this orb on his weakened form. You will have scant seconds to control his mind and fan the flames that will forge the seal.]],logDesc=[[Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken. It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!]],rewards={{id=12344,qty=1}}}
DB[4761]={id=4761,zoneId=148,name=[[Thundris Windweaver]],name_loc=[[Thundris Tejevientos]],level=15,minLevel=11,giver=[[Terenthis]],giverType=[[NPC]],giverId=3693,ender=[[Thundris Windweaver]],ender_loc=[[Thundris Tejevientos]],enderType=[[NPC]],enderId=3649,prevId=984,rewardNextId=4762,poiX=6581,poiY=492,wowhead=[[https://www.wowhead.com/wotlk/quest=4761]],image=[[assets/images/quests/placeholder.png]],desc=[[Your scouting of the furbolg camp is information that Thundris Windweaver should be made aware of.  He graciously serves as the elder of Auberdine, offering sage and just stewardship of the day to day affairs of the village.  Please - share with him your findings to date on the furbolg situation. I believe he has some ideas of his own on the reasons behind their corruption.  Perhaps you can work with him to enact a plan to restore the balance of nature here!]],logDesc=[[Speak with Thundris Windweaver in Auberdine.]]}
DB[4762]={id=4762,zoneId=148,name=[[The Cliffspring River]],name_loc=[[El Río Fonroca]],level=15,minLevel=11,giver=[[Thundris Windweaver]],giver_loc=[[Thundris Tejevientos]],giverType=[[NPC]],giverId=3649,ender=[[Thundris Windweaver]],ender_loc=[[Thundris Tejevientos]],enderType=[[NPC]],enderId=3649,prevId=4761,poiX=6581,poiY=492,wowhead=[[https://www.wowhead.com/wotlk/quest=4762]],image=[[assets/images/quests/placeholder.png]],desc=[[The Cliffspring River has begun turning foul and corrupted.  It empties into the Mist's Edge, and I fear the wash will affect Auberdine soon.  I suspect the Blackwood furbolgs up-river are the cause of the taint, but I also suspect that they aren't the true root of it. Take this sampling tube and go to the mouth of the river to our north.  Proceed inland to the first waterfall and draw a sample from the pool there.  You'll see a bridge overhead.  Once you have a sample, return to me in Auberdine.]],logDesc=[[Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there. Return to Thundris Windweaver in Auberdine with the Cliffspring River Sample.]]}
DB[4763]={id=4763,zoneId=148,name=[[The Blackwood Corrupted]],name_loc=[[La corrupción de los Bosque Negro]],level=18,minLevel=15,giver=[[Thundris Windweaver]],giver_loc=[[Thundris Tejevientos]],giverType=[[NPC]],giverId=3649,ender=[[Thundris Windweaver]],ender_loc=[[Thundris Tejevientos]],enderType=[[NPC]],enderId=3649,prevId=4762,poiX=6807,poiY=-376,wowhead=[[https://www.wowhead.com/wotlk/quest=4763]],image=[[assets/images/quests/placeholder.png]],desc=[[We've learned that a source of furbolg corruption is from the satyr.  They hold sway via talismans that they channel magic through.  If the furbolg have a chance at salvation, we must lure out the satyr corruptor and take that talisman! Fill this bowl at our moonwell and take samples of the furbolgs' food from their northern camp.  Mix them and place it near the bonfire by the river; any furbolgs who eat will be cleansed just long enough to lure out the satyr corruptor... who then you must slay!]],logDesc=[[Fill the Empty Cleansing Bowl at the Auberdine Moonwell. Gather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps. Mix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor. Take the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.]],choiceRewards={{id=15204,qty=1},{id=15202,qty=1},{id=15203,qty=1}}}
DB[4764]={id=4764,zoneId=1583,name=[[Doomrigger's Clasp]],name_loc=[[El Broche de Equipasino]],level=60,minLevel=57,giver=[[Mayara Brightwing]],giver_loc=[[Mayara Alasol]],giverType=[[NPC]],giverId=9565,ender=[[Mayara Brightwing]],ender_loc=[[Mayara Alasol]],enderType=[[NPC]],enderId=9565,prevId=4766,rewardNextId=4765,poiX=-8381,poiY=-2752,wowhead=[[https://www.wowhead.com/wotlk/quest=4764]],image=[[assets/images/quests/placeholder.png]],desc=[[There is a chamber, high in Blackrock Spire, that was once called the Hall of Fortune.  It was where the Dark Iron dwarves kept their relics, trophies and objects of art. That was long ago.  It is said the hall has collapsed and is now used for... less savory tasks.  But I believe some old dwarven relics may still be found there. One such relic is Doomrigger's clasp, with a surface so encrusted with rare gems that it was said to make weep any dwarf who gazes upon it. That clasp, $N, is your goal.]],logDesc=[[Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.]]}
DB[4765]={id=4765,zoneId=1583,name=[[Delivery to Ridgewell]],name_loc=[[Entrega a Bonacresta]],level=60,minLevel=57,giver=[[Mayara Brightwing]],giver_loc=[[Mayara Alasol]],giverType=[[NPC]],giverId=9565,ender=[[Count Remington Ridgewell]],ender_loc=[[Conde Remington Bonacresta]],enderType=[[NPC]],enderId=2285,prevId=4764,poiX=-8550,poiY=386,wowhead=[[https://www.wowhead.com/wotlk/quest=4765]],image=[[assets/images/quests/placeholder.png]],desc=[[I have packaged Doomriggers Clasp into a crate, suitable for shipment to Stormwind.  $N, you have been extremely helpful -- can I ask you for one last favor? Deliver the crate to Count Remington Ridgewell.  You will find him in the Keep of Stormwind.  I am sure he'll be very pleased to see what you have for him.]],logDesc=[[Bring Ridgewell's Crate to Count Remington Ridgewell at Stormwind Keep in Stormwind.]],choiceRewards={{id=15861,qty=1},{id=15860,qty=1}}}
DB[4766]={id=4766,zoneId=1583,name=[[Mayara Brightwing]],name_loc=[[Mayara Alasol]],level=60,minLevel=57,giver=[[Count Remington Ridgewell]],giver_loc=[[Conde Remington Bonacresta]],giverType=[[NPC]],giverId=2285,ender=[[Mayara Brightwing]],ender_loc=[[Mayara Alasol]],enderType=[[NPC]],enderId=9565,rewardNextId=4764,poiX=-8381,poiY=-2752,wowhead=[[https://www.wowhead.com/wotlk/quest=4766]],image=[[assets/images/quests/placeholder.png]],desc=[[An agent of mine, Mayara Brightwing, was sent to the Burning Steppes to scout the ruined city of Thaurissan.  That destroyed city of the Dark Iron dwarves may hide objects of great value... objects that would fit nicely into our family museum. Mayara says she found something and will need aid in retrieving it, but it is not in Thaurissan.  Instead, a foray into Blackrock Spire will be required. I do not know the details, but if interested then speak with Mayara in the Burning Steppes.]],logDesc=[[Speak with Mayara Brightwing at Morgan's Vigil in the Burning Steppes.]]}
DB[4767]={id=4767,zoneId=400,name=[[Wind Rider]],name_loc=[[Jinete del viento]],level=29,minLevel=25,giver=[[Elu]],giver_loc=[[Elu]],giverType=[[NPC]],giverId=10377,ender=[[Elu]],ender_loc=[[Elu]],enderType=[[NPC]],enderId=10377,poiX=-5118,poiY=-1053,wowhead=[[https://www.wowhead.com/wotlk/quest=4767]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been tasked to recruit more wyverns for the master wind riders. Their numbers are growing and I myself hope to become a wind rider one day. However, we cannot train enough wyverns to keep up with the demand. Perhaps you can help me, $N. I need you to travel to Highperch to gather some wyvern eggs. From here, head northwest along the canyon walls to a ramp that will lead you into Highperch. Be careful, wyverns are very protective over their eggs and they will not be kind to intruders.]],logDesc=[[Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post.]],rewards={{id=4265,qty=2}}}
DB[4768]={id=4768,zoneId=1583,name=[[The Darkstone Tablet]],name_loc=[[La tablilla de Rocanegra]],level=60,minLevel=57,giver=[[Shadowmage Vivian Lagrave]],giver_loc=[[Maga oscura Vivian Lagrave]],giverType=[[NPC]],giverId=9078,ender=[[Shadowmage Vivian Lagrave]],ender_loc=[[Maga oscura Vivian Lagrave]],enderType=[[NPC]],enderId=9078,prevId=4769,poiX=-6682,poiY=-2151,wowhead=[[https://www.wowhead.com/wotlk/quest=4768]],image=[[assets/images/quests/placeholder.png]],desc=[[The Darkstone Tablet holds the writings of the long-dead dwarf Urheld Darkstone.  An alchemist of great skill, he was thought insane by his contemporaries and, hence, did not share his research. But he did etch it onto tablets, and I believe one such tablet lies in Blackrock Spire, in a chamber once named the Hall of Fortune.  I know not what it is now called, for few enter Blackrock and return. But if you are willing to brave its dangers and return to me with the tablet, your reward will be great.]],logDesc=[[Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.]],choiceRewards={{id=15861,qty=1},{id=15860,qty=1}}}
DB[4769]={id=4769,zoneId=1583,name=[[Vivian Lagrave and the Darkstone Tablet]],name_loc=[[Vivian Lagrave y la tablilla de Rocanegra]],level=60,minLevel=57,giver=[[Apothecary Zinge]],giver_loc=[[Boticaria Zinge]],giverType=[[NPC]],giverId=5204,ender=[[Shadowmage Vivian Lagrave]],ender_loc=[[Maga oscura Vivian Lagrave]],enderType=[[NPC]],enderId=9078,rewardNextId=4768,poiX=-6682,poiY=-2151,wowhead=[[https://www.wowhead.com/wotlk/quest=4769]],image=[[assets/images/quests/placeholder.png]],desc=[[Vivian Lagrave sent me word from Kargath, in the Badlands.  Through her studies, she believes there is an ancient text within Blackrock Spire that would benefit our research.  To confirm this, she will need someone to extract the text from the spire.  No easy task. If interested, then speak with Vivian in Kargath.]],logDesc=[[Speak with Shadowmage Vivian Lagrave.]]}
DB[4770]={id=4770,zoneId=400,name=[[Homeward Bound]],name_loc=[[De vuelta a casa]],level=29,minLevel=25,giver=[[Pao'ka Swiftmountain]],giver_loc=[[Pao'ka Velocimontés]],giverType=[[NPC]],giverId=10427,ender=[[Motega Firemane]],ender_loc=[[Motega Pirocabello]],enderType=[[NPC]],enderId=10428,poiX=-4916,poiY=-1381,wowhead=[[https://www.wowhead.com/wotlk/quest=4770]],image=[[assets/images/quests/placeholder.png]],desc=[[Please help me, $c! I've been hiding here in Highperch for some time now and it's been days since I've seen a friendly face. I came here to study the wyvern and I think I got a little too close. After being chased away from one of the nests I got lost. I need to get back to Whitereach Post! Motega does not know that I am missing and will be furious to know that I ventured into Highperch by myself. Whitereach Post is just east of here... please take me there!]],logDesc=[[Escort Pao'ka Swiftmountain from Highperch, and then talk to Motega Firemane in Whitereach Post.]]}
DB[4771]={id=4771,zoneId=2057,name=[[Dawn's Gambit]],name_loc=[[Gambito del Alba]],level=60,minLevel=57,giver=[[Betina Bigglezink]],giver_loc=[[Betina Bigglezink]],giverType=[[NPC]],giverId=11035,ender=[[Betina Bigglezink]],ender_loc=[[Betina Bigglezink]],enderType=[[NPC]],enderId=11035,prevId=5531,poiX=2260,poiY=-5339,wowhead=[[https://www.wowhead.com/wotlk/quest=4771]],image=[[assets/images/quests/placeholder.png]],desc=[[I've placed Dawn's Gambit in the container you brought to us, the one that held the dragon eggs.  Your job is to bring it deep within the Scholomance. The undead mage Vectus leads a team of Scourge scholars... place Dawn's Gambit in their chamber, called the "viewing room."  It will then react with the undead found there and, with a little luck, destroy them! After that, defeating Vectus shouldn't be a problem.  Right?]],logDesc=[[Place Dawn's Gambit in the Viewing Room of the Scholomance.  Defeat Vectus, then return to Betina Bigglezink.]],choiceRewards={{id=15853,qty=1},{id=15854,qty=1}}}
DB[4781]={id=4781,name=[[Components for the Enchanted Gold Bloodrobe]],name_loc=[[Los componentes para la toga de sangre dorada encantada]],level=34,minLevel=31,giver=[[Menara Voidrender]],giver_loc=[[Menara Nadiz]],giverType=[[NPC]],giverId=6266,ender=[[Xizk Goodstitch]],ender_loc=[[Xizk Cortefino]],enderType=[[NPC]],enderId=2670,prevId=1796,rewardNextId=4782,poiX=-14440,poiY=389,wowhead=[[https://www.wowhead.com/wotlk/quest=4781]],image=[[assets/images/quests/placeholder.png]],desc=[[Your next task is as simple as your first, but will require you to seek out aid. I require gold thread for the embroidery of the cloak, but gold thread is not easy to come by, and very few know how to make it. Fortunately, one who is loyal to our cause knows its secrets and is willing to help those rising in our ranks. Bring a gold bar to Xizk Goodstitch in Booty Bay. He is a master tailor and will be happy to spin the thread for you. Gold bars are smelted by skilled miners. Ask a miner for help.]],logDesc=[[Bring a Gold Bar to Xizk Goodstitch in Stranglethorn Vale.]]}
DB[4782]={id=4782,name=[[Components for the Enchanted Gold Bloodrobe]],name_loc=[[Los componentes para la toga de sangre dorada encantada]],level=34,minLevel=31,giver=[[Xizk Goodstitch]],giver_loc=[[Xizk Cortefino]],giverType=[[NPC]],giverId=2670,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,prevId=4781,rewardNextId=4783,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4782]],image=[[assets/images/quests/placeholder.png]],desc=[[Return to Menara, tell her it'll take some time, but I'll make sure to come through for her... and you. Tell her to have you finish gathering the rest of your components--I should have the thread done by then. You can return and pick it up then. Good luck, $N. Oh, and say hello to Strahad for me while you're there. That old coot... putting a tower right there next to Ratchet... crazy.]],logDesc=[[Return to Menara Voidrender in the Barrens.]]}
DB[4783]={id=4783,name=[[Components for the Enchanted Gold Bloodrobe]],name_loc=[[Los componentes para la toga de sangre dorada encantada]],level=37,minLevel=31,giver=[[Menara Voidrender]],giver_loc=[[Menara Nadiz]],giverType=[[NPC]],giverId=6266,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,prevId=4782,rewardNextId=4784,poiX=-284,poiY=686,wowhead=[[https://www.wowhead.com/wotlk/quest=4783]],image=[[assets/images/quests/placeholder.png]],desc=[[The next components are found in Desolace, far to the west of the Barrens and even the Stonetalon Mountains. There, chaos still reigns after the Sundering. Both your strength and cunning will be tested there--you will face creatures of hatred and also of the Burning Legion. From the Hatefury satyr in the northeast, bring me their blood. From the lesser infernals in Mannoroc Coven, bring me a lesser infernal stone. We will use both in the construction of your robe.]],logDesc=[[Bring 10 Vials of Hatefury Blood and 1 Lesser Infernal Stone to Menara Voidrender in the Barrens.]]}
DB[4784]={id=4784,name=[[Components for the Enchanted Gold Bloodrobe]],name_loc=[[Los componentes para la toga de sangre dorada encantada]],level=37,minLevel=31,giver=[[Menara Voidrender]],giver_loc=[[Menara Nadiz]],giverType=[[NPC]],giverId=6266,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,prevId=4783,rewardNextId=4786,poiX=-884,poiY=-1849,wowhead=[[https://www.wowhead.com/wotlk/quest=4784]],image=[[assets/images/quests/placeholder.png]],desc=[[I need only three things now, $N, then we can finish your robe. First, the fine gold thread Xizk is making for you. Return to him in Booty Bay and get it. Second, bring me two smoldering coals from the fire elementals in the Arathi Highlands. If I recall correctly, they are to the west, near Thoradin's Wall. Finally, a soul shard created by you. After you have all the components, return here to the tower and I will complete the robe for you.]],logDesc=[[Bring some Fine Gold Thread, 2 Smoldering Coals, and a Soul Shard to Menara Voidrender in the Barrens.]]}
DB[4785]={id=4785,name=[[Fine Gold Thread]],name_loc=[[Hilo de oro fino]],level=37,minLevel=31,giver=[[Xizk Goodstitch]],giver_loc=[[Xizk Cortefino]],giverType=[[NPC]],giverId=2670,ender=[[Xizk Goodstitch]],ender_loc=[[Xizk Cortefino]],enderType=[[NPC]],enderId=2670,prevId=4783,poiX=-14440,poiY=389,wowhead=[[https://www.wowhead.com/wotlk/quest=4785]],image=[[assets/images/quests/placeholder.png]],rewards={{id=12293,qty=1}}}
DB[4786]={id=4786,name=[[The Completed Robe]],name_loc=[[Toga terminada]],level=38,minLevel=31,giver=[[Menara Voidrender]],giver_loc=[[Menara Nadiz]],giverType=[[NPC]],giverId=6266,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,prevId=4784,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4786]],image=[[assets/images/quests/placeholder.png]],desc=[[I will put the robe together for you now. It will take but a few moments. Do not go far.]],logDesc=[[Wait for Menara Voidrender to complete your robe and then speak to her again.]],rewards={{id=6900,qty=1}}}
DB[4787]={id=4787,zoneId=47,name=[[The Ancient Egg]],name_loc=[[El huevo antiguo]],level=50,minLevel=40,giver=[[Yeh'kinya]],giverType=[[NPC]],giverId=8579,ender=[[Yeh'kinya]],enderType=[[NPC]],enderId=8579,prevId=3527,rewardNextId=3528,poiX=-6903,poiY=-4841,wowhead=[[https://www.wowhead.com/wotlk/quest=4787]],image=[[assets/images/quests/placeholder.png]],desc=[[The Prophecy of Mosh'aru speaks of an ancient egg.  It is a relic of a time when trolls ruled vast empires, and it has the power to hold the essence of Hakkar.  It may be the only way to keep our world safe from his evil. Bring me the ancient egg, $N.  It is said to lay hidden deep within Jintha'Alor in the Hinterlands, in a cave behind the amphitheater at the top of the city.]],logDesc=[[Bring the Ancient Egg to Yeh'kinya in Tanaris.]]}
DB[4788]={id=4788,zoneId=1583,name=[[The Final Tablets]],name_loc=[[Las últimas tablillas]],level=58,minLevel=40,giver=[[Prospector Ironboot]],giver_loc=[[Prospector Ferrobota]],giverType=[[NPC]],giverId=10460,ender=[[Prospector Ironboot]],ender_loc=[[Prospector Ferrobota]],enderType=[[NPC]],enderId=10460,prevId=5065,poiX=-6980,poiY=-4834,wowhead=[[https://www.wowhead.com/wotlk/quest=4788]],image=[[assets/images/quests/placeholder.png]],desc=[[While I look over the third and fourth tablets of Mosh'aru, you must find the fifth and sixth!  It will not be easy, for they are held by the Smolderthorn trolls within Blackrock Spire.  The spire is a dark mountain of fire between the Burning Steppes and the Searing Gorge. Good luck, $N.  Blackrock Spire is no place for decent folk...]],logDesc=[[Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.]]}
DB[4801]={id=4801,zoneId=618,name=[[Frostsaber E'ko]],name_loc=[[E'ko de sable de hielo]],level=60,minLevel=55,giver=[[Witch Doctor Mau'ari]],giver_loc=[[Médica bruja Mau'ari]],giverType=[[NPC]],giverId=10307,ender=[[Witch Doctor Mau'ari]],ender_loc=[[Médica bruja Mau'ari]],enderType=[[NPC]],enderId=10307,prevId=975,poiX=7883,poiY=-4348,wowhead=[[https://www.wowhead.com/wotlk/quest=4801]],image=[[assets/images/quests/placeholder.png]],rewards={{id=12450,qty=3}}}
