DB[4806]={id=4806,zoneId=618,name=[[Frostmaul E'ko]],name_loc=[[E'ko de los Machacahielo]],level=60,minLevel=55,giver=[[Witch Doctor Mau'ari]],giver_loc=[[Médica bruja Mau'ari]],giverType=[[NPC]],giverId=10307,ender=[[Witch Doctor Mau'ari]],ender_loc=[[Médica bruja Mau'ari]],enderType=[[NPC]],enderId=10307,prevId=975,poiX=5261,poiY=-4989,wowhead=[[https://www.wowhead.com/wotlk/quest=4806]],image=[[assets/images/quests/placeholder.png]],rewards={{id=12460,qty=3}}}
DB[4807]={id=4807,zoneId=618,name=[[Wildkin E'ko]],name_loc=[[E'ko de lechúcico salvaje]],level=60,minLevel=55,giver=[[Witch Doctor Mau'ari]],giver_loc=[[Médica bruja Mau'ari]],giverType=[[NPC]],giverId=10307,ender=[[Witch Doctor Mau'ari]],ender_loc=[[Médica bruja Mau'ari]],enderType=[[NPC]],enderId=10307,prevId=975,poiX=6360,poiY=-3794,wowhead=[[https://www.wowhead.com/wotlk/quest=4807]],image=[[assets/images/quests/placeholder.png]],rewards={{id=12458,qty=3}}}
DB[4808]={id=4808,zoneId=46,name=[[Felnok Steelspring]],name_loc=[[Felnok Acerovera]],level=54,minLevel=50,giver=[[Tinkee Steamboil]],giver_loc=[[Tinkee Vaporio]],giverType=[[NPC]],giverId=10267,ender=[[Felnok Steelspring]],ender_loc=[[Felnok Acerovera]],enderType=[[NPC]],enderId=10468,prevId=4726,rewardNextId=4809,poiX=6706,poiY=-4692,wowhead=[[https://www.wowhead.com/wotlk/quest=4808]],image=[[assets/images/quests/placeholder.png]],desc=[[I have another favor to ask of you. My initial study of the essence you collected shows that it might be possible to freeze dragon whelp eggs and preserve them!  I want to test this theory, but first I need specially made engineering components.  My colleague, Felnok Steelspring, can make them. Here, take this letter to Felnok.  It tells him what I need.  You'll find Felnok in Winterspring, in the town of Everlook.]],logDesc=[[Give Tinkee's Letter to Felnok Steelspring at Everlook in Winterspring.]]}
DB[4809]={id=4809,zoneId=618,name=[[Chillwind Horns]],name_loc=[[Cuernos de Orvallo]],level=54,minLevel=50,giver=[[Felnok Steelspring]],giver_loc=[[Felnok Acerovera]],giverType=[[NPC]],giverId=10468,ender=[[Felnok Steelspring]],ender_loc=[[Felnok Acerovera]],enderType=[[NPC]],enderId=10468,prevId=4808,rewardNextId=4810,poiX=6886,poiY=-3847,wowhead=[[https://www.wowhead.com/wotlk/quest=4809]],image=[[assets/images/quests/placeholder.png]],desc=[[I have most of what Tinkee needs, but I'm missing one important component, and that's chillwind horns.  The horns of the chillwind chimaera in Winterspring are a concentrated source of cold, but only pristine, uncracked horns will do!  I'll need a supply of those to complete Tinkee's order. Bring me the uncracked chillwind horns, and I'll prepare a package for Tinkee.]],logDesc=[[Collect 8 Uncracked Chillwind Horns.]]}
DB[4810]={id=4810,zoneId=618,name=[[Return to Tinkee]],name_loc=[[Regresa junto a Tinkee]],level=54,minLevel=50,giver=[[Felnok Steelspring]],giver_loc=[[Felnok Acerovera]],giverType=[[NPC]],giverId=10468,ender=[[Tinkee Steamboil]],ender_loc=[[Tinkee Vaporio]],enderType=[[NPC]],enderId=10267,prevId=4809,poiX=-7500,poiY=-2178,wowhead=[[https://www.wowhead.com/wotlk/quest=4810]],image=[[assets/images/quests/placeholder.png]],desc=[[Ok, everything is prepared and packed and ready for transport!  Good luck in your journey, and make sure you tell Tinkee that she owes me!]],logDesc=[[Bring Felnok's Package to Tinkee Steamboil at Flame Crest in the Burning Steppes.]],choiceRewards={{id=15862,qty=1},{id=15863,qty=1}}}
DB[4811]={id=4811,zoneId=148,name=[[The Red Crystal]],name_loc=[[El cristal rojo]],level=14,minLevel=12,giver=[[Sentinel Glynda Nal'Shea]],giver_loc=[[Centinela Glynda Nal'Shea]],giverType=[[NPC]],giverId=2930,ender=[[Sentinel Glynda Nal'Shea]],ender_loc=[[Centinela Glynda Nal'Shea]],enderType=[[NPC]],enderId=2930,rewardNextId=4812,poiX=6208,poiY=-221,wowhead=[[https://www.wowhead.com/wotlk/quest=4811]],image=[[assets/images/quests/placeholder.png]],desc=[[Hostile moonkin roam in ever increasing numbers to our east.  They once were thought to be gentle, almost mystical creatures.  While some continue to hold reverence for them, the safety of Auberdine forces me to keep a more realistic view. I've received reports that moonkin are being drawn to a large red crystal along Darkshore's eastern mountain range.  No one has any idea what that crystal is, or even if it really exists.  I want you to locate it over there and report back to me what you find.]],logDesc=[[Travel east of Auberdine and look for a large, red crystal along Darkshore's eastern mountain range.  Report back what you find to Sentinel Glynda Nal'Shea in Auberdine.]]}
DB[4812]={id=4812,zoneId=148,name=[[As Water Cascades]],name_loc=[[Agua en cascada]],level=14,minLevel=12,giver=[[Sentinel Glynda Nal'Shea]],giver_loc=[[Centinela Glynda Nal'Shea]],giverType=[[NPC]],giverId=2930,ender=[[Mysterious Red Crystal]],ender_loc=[[Cristal rojo misterioso]],enderType=[[GO]],enderId=175524,prevId=4811,rewardNextId=4813,poiX=6208,poiY=-158,wowhead=[[https://www.wowhead.com/wotlk/quest=4812]],image=[[assets/images/quests/placeholder.png]],desc=[[Use this empty vial and fill up on some moonwell water here in Auberdine.  Such potent magic should provide a clue as to the composition of the crystal.  To do that, you'll pour the liquid over the crystal; it should take care of the rest. While I don't anticipate anything bad happening to you, I still want you to be careful.  Above us to the east is Felwood; if that crystal is tied to that place as I suspect it is, then it could prove to be very dangerous.]],logDesc=[[Fill the Empty Water Tube at the Auberdine moonwell, and then investigate the red crystal along Darkshore's eastern mountain wall.]]}
DB[4813]={id=4813,zoneId=148,name=[[The Fragments Within]],name_loc=[[Los trozos del interior]],level=14,minLevel=12,giver=[[Mysterious Red Crystal]],giver_loc=[[Cristal rojo misterioso]],giverType=[[GO]],giverId=175524,ender=[[Sentinel Glynda Nal'Shea]],ender_loc=[[Centinela Glynda Nal'Shea]],enderType=[[NPC]],enderId=2930,prevId=4812,poiX=6439,poiY=473,wowhead=[[https://www.wowhead.com/wotlk/quest=4813]],image=[[assets/images/quests/placeholder.png]],desc=[[The moonwell water has revealed that embedded inside the crystal are a few small fragments of bone, as well as half of a jawbone.  The jawbone appears to be from a humanoid, but it is unclear without breaking open the crystal - a feat that even the strongest of magic would find near impossible. With the task at hand complete, all that remains is to report back to Sentinel Glynda Nal'Shea in Auberdine.]],logDesc=[[Report back what you have found to Sentinel Glynda Nal'Shea in Auberdine.]],choiceRewards={{id=15335,qty=1},{id=15396,qty=1},{id=15397,qty=1}}}
DB[4821]={id=4821,zoneId=400,name=[[Alien Egg]],name_loc=[[Un huevo extraño]],level=26,minLevel=24,giver=[[Hagar Lightninghoof]],giver_loc=[[Hagar Pezuña del Rayo]],giverType=[[NPC]],giverId=10539,ender=[[Hagar Lightninghoof]],ender_loc=[[Hagar Pezuña del Rayo]],enderType=[[NPC]],enderId=10539,poiX=-5442,poiY=-2397,wowhead=[[https://www.wowhead.com/wotlk/quest=4821]],image=[[assets/images/quests/placeholder.png]],desc=[[A rumor has surfaced about an alien egg here in Thousand Needles. Those that report seeing this egg have failed to even get close enough to examine it in detail. Serpents guard the egg as if it's one of their own. I want you to seek out this alien egg and bring it to me so that I may examine it. Reports say the egg is located within a serpent den, but there are several serpent dens along the base of the cliff walls south and northeast of Freewind Post.]],logDesc=[[Return the Alien Egg to Hagar Lightninghoof in Freewind Post.]]}
DB[4822]={id=4822,name=[[You Scream, I Scream...]],name_loc=[[¡Quiero un heladooooo!]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Human Orphan]],ender_loc=[[Huérfano humano]],enderType=[[NPC]],enderId=14305,prevId=1479,exGroup=-558,wowhead=[[https://www.wowhead.com/wotlk/quest=4822]],image=[[assets/images/quests/placeholder.png]],desc=[[ICE CREAM!  Oh please please please could you get me some ice cream?!  Strawberry is my favorite flavor, and there's no better strawberry ice cream in the world than Tigule and Foror's Strawberry Ice Cream!  It's my favorite ice cream in the whole wide world! I had it once a long time ago when I was at the Shimmering Flats race track, but I heard that they might be selling them in town now!  Please?  Pretty please?  With Tigule and Foror's Strawberry Ice Cream on top??!?!]],logDesc=[[Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream.]]}
DB[4841]={id=4841,zoneId=400,name=[[Pacify the Centaur]],name_loc=[[Apaciguar al centauro]],level=25,minLevel=23,giver=[[Cliffwatcher Longhorn]],giver_loc=[[Vigiarrisco Cuerno Largo]],giverType=[[NPC]],giverId=10537,ender=[[Cliffwatcher Longhorn]],ender_loc=[[Vigiarrisco Cuerno Largo]],enderType=[[NPC]],enderId=10537,prevId=4542,rewardNextId=5064,poiX=-5183,poiY=-2613,wowhead=[[https://www.wowhead.com/wotlk/quest=4841]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I entreat you to hunt these centaur down. They shall feel the wrath of our revenge. Attack the centaur camp to the north of Freewind Post!  Let wrath guide your hand! ]],logDesc=[[Kill 12 Galak Scouts, 10 Galak Wranglers, and 6 Galak Windchasers, and then return to Cliffwatcher Longhorn in Freewind Post.]]}
DB[4842]={id=4842,zoneId=618,name=[[Strange Sources]],name_loc=[[Fuentes extrañas]],level=56,minLevel=51,giver=[[Donova Snowden]],giver_loc=[[Donova Cubilnevado]],giverType=[[NPC]],giverId=9298,ender=[[Donova Snowden]],ender_loc=[[Donova Cubilnevado]],enderType=[[NPC]],enderId=9298,prevId=980,poiX=5019,poiY=-4638,wowhead=[[https://www.wowhead.com/wotlk/quest=4842]],image=[[assets/images/quests/placeholder.png]],desc=[[To tell you the truth, although there are no volcanoes here in Winterspring, I believe that there are far more threatening reasons for these hot springs... Well, I think you'll want to see it for yourself. You'll need to travel the length of Winterspring, and head to the very south. When the air becomes thick and muggy, and the sky turns dark, you'll have found what I believe to be the source of the hot springs. Have a look. I'm sure you'll have many questions when you return.]],logDesc=[[Follow Donova Snowden's instructions, then report back.]],rewards={{id=15789,qty=1}}}
DB[4861]={id=4861,zoneId=618,name=[[Enraged Wildkin]],name_loc=[[Lechúcico salvaje iracundo]],level=59,minLevel=53,giver=[[Jaron Stoneshaper]],giver_loc=[[Jaron Tallapiedras]],giverType=[[NPC]],giverId=10301,ender=[[Damaged Crate]],ender_loc=[[Cajón dañado]],enderType=[[GO]],enderId=175587,rewardNextId=4863,poiX=5703,poiY=-4505,wowhead=[[https://www.wowhead.com/wotlk/quest=4861]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey there, $Glad:lass;! I was chased from my camp in southern Winterspring by some bloodthirsty wildkin! Well, I suppose I got too close to something the wildkin were guarding. I barely managed to get away safely; I fear a buddy of mine wasn't as lucky. Would you mind braving the wildkin and heading to the camp? I really need my supplies, and I'd also like to get back the amulet I unearthed yesterday at the dig site.]],logDesc=[[Locate Jaron Stoneshaper's wrecked camp and supplies in southern Winterspring.]]}
DB[4862]={id=4862,zoneId=1583,name=[[En-Ay-Es-Tee-Why]],name_loc=[[Bestia amaestrada]],level=59,minLevel=55,giver=[[Kibler]],giverType=[[NPC]],giverId=10260,ender=[[Kibler]],enderType=[[NPC]],enderId=10260,poiX=-7459,poiY=-2197,wowhead=[[https://www.wowhead.com/wotlk/quest=4862]],image=[[assets/images/quests/placeholder.png]],desc=[[Believe it or not, there are people out there willing to pay for the most vile of domesticated beast! I'd sent Bijou into the Spire to try and collect some of those spire spider eggs but I haven't heard from her in weeks. Maybe you can help me out? I'll tell you what, $N. Go to Blackrock Spire and collect some spire spider eggs for me. Bring them back here and not only will I give you a little cash, but I'll even domesticate one for you!]],logDesc=[[Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler. By the sound of it, these eggs could be found near spiders. ]],rewards={{id=12529,qty=1}}}
DB[4863]={id=4863,zoneId=618,name=[[Enraged Wildkin]],name_loc=[[Lechúcico salvaje iracundo]],level=59,minLevel=53,giver=[[Damaged Crate]],giver_loc=[[Cajón dañado]],giverType=[[GO]],giverId=175587,ender=[[Jaron's Wagon]],ender_loc=[[Carro de Jaron]],enderType=[[GO]],enderId=175586,prevId=4861,rewardNextId=4864,poiX=5661,poiY=-4679,wowhead=[[https://www.wowhead.com/wotlk/quest=4863]],image=[[assets/images/quests/placeholder.png]],desc=[[Looking around, you don't see much that Jaron could want here. However, you do notice that the crate you found has been smashed open, almost as if this was what the wildkin were after... Looking to the east, you can barely make out an abandoned wagon. Perhaps you might find Jaron's things there. It's worth a look.]],logDesc=[[Find Jaron Stoneshaper's wrecked wagon.]]}
DB[4864]={id=4864,zoneId=618,name=[[Enraged Wildkin]],name_loc=[[Lechúcico salvaje iracundo]],level=59,minLevel=53,giver=[[Jaron's Wagon]],giver_loc=[[Carro de Jaron]],giverType=[[GO]],giverId=175586,ender=[[Jaron Stoneshaper]],ender_loc=[[Jaron Tallapiedras]],enderType=[[NPC]],enderId=10301,prevId=4863,poiX=5659,poiY=-4676,wowhead=[[https://www.wowhead.com/wotlk/quest=4864]],image=[[assets/images/quests/placeholder.png]],desc=[[After inspecting the contents of the box, you decide that Jaron could make use of the tools and other items inside. However, there is no sign of the amulet. It appears that the wildkin inhabit the lands to the north and east of here, so you decide that the next step is to face the creatures and reclaim the amulet from them.]],logDesc=[[Pick up Jaron's Supplies from the snow, then find the wildkin that stole the amulet Jaron spoke of. Bring Jaron's Supplies and the Blue-feathered Amulet to Jaron Stoneshaper at the lodge in Winterspring.]]}
DB[4865]={id=4865,zoneId=400,name=[[Serpent Wild]],name_loc=[[Venganza]],level=26,minLevel=24,giver=[[Hagar Lightninghoof]],giver_loc=[[Hagar Pezuña del Rayo]],giverType=[[NPC]],giverId=10539,ender=[[Motega Firemane]],ender_loc=[[Motega Pirocabello]],enderType=[[NPC]],enderId=10428,prevId=4821,rewardNextId=5062,poiX=-4916,poiY=-1381,wowhead=[[https://www.wowhead.com/wotlk/quest=4865]],image=[[assets/images/quests/placeholder.png]],desc=[[If I did not see that with my own eyes I would never have believed it to be true. Vengeance has come to Thousand Needles! <Hagar wipes his brow.> $N, you must act quickly! Go now and seek out Motega Firemane; he is located at Whitereach Post just northwest of Freewind Post along the road. He will know what to do!]],logDesc=[[Report your findings to Motega Firemane at Whitereach Post in Thousand Needles.]]}
DB[4866]={id=4866,zoneId=1583,name=[[Mother's Milk]],name_loc=[[La leche de la madre]],level=60,minLevel=55,giver=[[Ragged John]],giver_loc=[[John Andrajoso]],giverType=[[NPC]],giverId=9563,ender=[[Ragged John]],ender_loc=[[John Andrajoso]],enderType=[[NPC]],enderId=9563,poiX=-7495,poiY=-2171,wowhead=[[https://www.wowhead.com/wotlk/quest=4866]],image=[[assets/images/quests/placeholder.png]],desc=[[It's probably one of the most potent poisons in the world, $r! I've overheard the Blackrock speaking about its lethality in my jaunts into the Spire. They call it 'Mother's Milk', named after Mother Smolderweb, the big nasty spider in the Skitterweb cave. Now here's what I need from you: A live sample of the Milk, flowing through YOUR veins. Just bringing me the gland won't be enough! Get her to poison you and come back to me! Then... I get to milk ya! <Rubs his hands together in anticipation.>]],logDesc=[[In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you.]],rewards={{id=15873,qty=1}}}
DB[4867]={id=4867,zoneId=1583,name=[[Urok Doomhowl]],name_loc=[[Urok Aullasino]],level=60,minLevel=55,giver=[[Warosh]],giver_loc=[[Warosh]],giverType=[[NPC]],giverId=10799,ender=[[Warosh]],ender_loc=[[Warosh]],enderType=[[NPC]],enderId=10799,wowhead=[[https://www.wowhead.com/wotlk/quest=4867]],image=[[assets/images/quests/placeholder.png]],desc=[[Argh!  So hard to speak! Take this note!  Get me my mojo!]],logDesc=[[Read Warosh's Scroll.  Bring Warosh's Mojo to Warosh.]],rewards={{id=15867,qty=1}}}
DB[4881]={id=4881,zoneId=400,name=[[Assassination Plot]],name_loc=[[Complot de asesinato]],level=28,minLevel=23,giverType=[[NPC]],ender=[[Kanati Greycloud]],ender_loc=[[Kanati Nube Gris]],enderType=[[NPC]],enderId=10638,rewardNextId=4966,poiX=-4907,poiY=-1368,wowhead=[[https://www.wowhead.com/wotlk/quest=4881]],image=[[assets/images/quests/placeholder.png]],desc=[[The Tauren, Kanati Greycloud is bold to set up a hunting camp in Thousand Needles. We must kill him to rid this hunting camp and all who may follow him. We will converge at the small post Southwest of the Great Lift. ]],logDesc=[[Warn Kanati Greycloud at Whitereach Post of the plot to kill him.]]}
DB[4882]={id=4882,zoneId=618,name=[[Guarding Secrets]],name_loc=[[Guardar un secreto]],level=59,minLevel=52,giverType=[[NPC]],ender=[[Trull Failbane]],ender_loc=[[Trull Fallarruina]],enderType=[[NPC]],enderId=10306,rewardNextId=4883,poiX=5110,poiY=-355,wowhead=[[https://www.wowhead.com/wotlk/quest=4882]],image=[[assets/images/quests/placeholder.png]],desc=[[You are unsure of the significance of the necklace that fell from the neck of the recently-slain wildkin. It glows brightly, slowly fading in and out. Trull Failbane might be able to tell you more, since his knowledge of the wildkin seems extensive. Perhaps you should ask him about it.]],logDesc=[[Take the Blue-feathered Necklace to Trull Failbane at Bloodvenom Post.]]}
DB[4883]={id=4883,zoneId=618,name=[[Guarding Secrets]],name_loc=[[Guardar un secreto]],level=59,minLevel=52,giver=[[Trull Failbane]],giver_loc=[[Trull Fallarruina]],giverType=[[NPC]],giverId=10306,ender=[[Nara Wildmane]],ender_loc=[[Nara Ferocrín]],enderType=[[NPC]],enderId=5770,prevId=4882,poiX=-1070,poiY=-273,wowhead=[[https://www.wowhead.com/wotlk/quest=4883]],image=[[assets/images/quests/placeholder.png]],desc=[[While I do possess much knowledge about the owlbeasts you defeated in Winterspring, I am not very learned on the subject of the magics they wield. But I do believe I know of one that would be able to examine the necklace and most likely tell you what it is. Nara Wildmane in Thunder Bluff is an expert in this field; see her. Good luck, $N.]],logDesc=[[Take the Blue-feathered Necklace to Nara Wildmane.]],choiceRewards={{id=15796,qty=1},{id=15797,qty=1}}}
DB[4901]={id=4901,zoneId=618,name=[[Guardians of the Altar]],name_loc=[[Guardianes del altar]],level=59,minLevel=52,giver=[[Ranshalla]],giverType=[[NPC]],giverId=10300,ender=[[Erelas Ambersky]],ender_loc=[[Erelas Cieloámbar]],enderType=[[NPC]],enderId=7916,prevId=979,poiX=5718,poiY=-4869,wowhead=[[https://www.wowhead.com/wotlk/quest=4901]],image=[[assets/images/quests/placeholder.png]],desc=[[At the very top of the ridge lies what I believe to be an altar of the goddess Elune. From what I can tell, we need to light the five torches in each cave, and then we will be able to access the altar directly. I transcribed some incantations carved into the stone in the ancient ruins of Kel'Theril, which I believe are the secret to unlocking the altar. I'll need your help to light each torch, while I recite the spell. If we are successful, you'll be able to report our findings to Erelas!]],logDesc=[[Protect Ranshalla while she attempts to reactivate the Altar of Elune. Report your findings to Erelas Ambersky in Rut'theran Village.]]}
DB[4902]={id=4902,zoneId=618,name=[[Wildkin of Elune]],name_loc=[[Lechúcico salvaje de Elune]],level=57,minLevel=52,giver=[[Erelas Ambersky]],giver_loc=[[Erelas Cieloámbar]],giverType=[[NPC]],giverId=7916,ender=[[Arch Druid Fandral Staghelm]],ender_loc=[[Archidruida Fandral Corzocelada]],enderType=[[NPC]],enderId=3516,prevId=4901,poiX=10175,poiY=2568,wowhead=[[https://www.wowhead.com/wotlk/quest=4902]],image=[[assets/images/quests/placeholder.png]],desc=[[That's fascinating! I have always wondered about the truth... Well, you must share this knowledge, definitely! Go to Arch Druid Fandral Staghelm right away -- you'll find him in Darnassus, in the Cenarion Circle. Explain to him what happened, just the same as you told me. I'm sure he will be just as interested! This is important information, $N!]],logDesc=[[Speak with Arch Druid Fandral Staghelm in Darnassus.]],choiceRewards={{id=16622,qty=1},{id=16623,qty=1}}}
DB[4903]={id=4903,zoneId=1583,name=[[Warlord's Command]],name_loc=[[La orden del Señor de la Guerra]],level=60,minLevel=55,giver=[[Warlord Goretooth]],giver_loc=[[Señor de la guerra Dientegore]],giverType=[[NPC]],giverId=9077,ender=[[Warlord Goretooth]],ender_loc=[[Señor de la guerra Dientegore]],enderType=[[NPC]],enderId=9077,rewardNextId=4941,poiX=-6678,poiY=-2224,wowhead=[[https://www.wowhead.com/wotlk/quest=4903]],image=[[assets/images/quests/placeholder.png]],desc=[[By order of Warlord Goretooth, the following inhabitants of Blackrock Spire must be destroyed: The rotund menace, Highlord Omokk. The cruel and ruthless troll, War Master Voone. Overlord Wyrmthalak, taskmaster of the lesser city. You will also be required to return any important documents that you may find. Succeed and be honored. Fail and be forgotten.]],logDesc=[[Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.]],choiceRewards={{id=13958,qty=1},{id=13959,qty=1},{id=13961,qty=1},{id=13962,qty=1},{id=13963,qty=1}}}
DB[4904]={id=4904,zoneId=400,name=[[Free at Last]],name_loc=[[Al fin libre]],level=29,minLevel=25,giver=[[Lakota Windsong]],giver_loc=[[Lakota Son del Viento]],giverType=[[NPC]],giverId=10646,ender=[[Thalia Amberhide]],ender_loc=[[Thalia Pellejo Ámbar]],enderType=[[NPC]],enderId=10645,poiX=-5481,poiY=-2456,wowhead=[[https://www.wowhead.com/wotlk/quest=4904]],image=[[assets/images/quests/placeholder.png]],desc=[[Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong. He... he slew my brother and then brought me here.  My poor brother... $N, could you escort me out of the Darkcloud Pinnacle?  Please... I need to get back to Thalia! She must be worried sick about me.]],logDesc=[[Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post.]],choiceRewards={{id=15469,qty=1},{id=15468,qty=1}}}
DB[4906]={id=4906,zoneId=361,name=[[Further Corruption]],name_loc=[[Más corrupción]],level=54,minLevel=49,giver=[[Eridan Bluewind]],giver_loc=[[Eridan Vientoazul]],giverType=[[NPC]],giverId=9116,ender=[[Eridan Bluewind]],ender_loc=[[Eridan Vientoazul]],enderType=[[NPC]],enderId=9116,prevId=4421,poiX=4587,poiY=-871,wowhead=[[https://www.wowhead.com/wotlk/quest=4906]],image=[[assets/images/quests/placeholder.png]],desc=[[A second encampment of satyrs threatens the land of Felwood towards the north, led by the cruel Xavaric. The vile betrayers and tricksters feed upon the corruption of the native creatures of Felwood. Xavathras and his minions were only part of a larger plan -- to cultivate a corrupted moonwell, and then provide the spoils to Xavaric. Now that Xavathras is out of the way, finish this task, $N. Head to the north and defeat Xavaric.]],logDesc=[[Eridan Bluewind in Felwood wants you to kill 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters, and Xavaric. Return to Eridan when the task is completed.]],rewards={{id=11875,qty=1}}}
DB[4907]={id=4907,zoneId=1583,name=[[Tinkee Steamboil]],name_loc=[[Tinkee Vaporio]],level=60,minLevel=57,giver=[[Felnok Steelspring]],giver_loc=[[Felnok Acerovera]],giverType=[[NPC]],giverId=10468,ender=[[Tinkee Steamboil]],ender_loc=[[Tinkee Vaporio]],enderType=[[NPC]],enderId=10267,prevId=4810,rewardNextId=4734,poiX=-7500,poiY=-2178,wowhead=[[https://www.wowhead.com/wotlk/quest=4907]],image=[[assets/images/quests/placeholder.png]],desc=[[Hi, $N.  Remember Tinkee Steamboil?  Well, she remembers you!  She sent me a message to keep an eye out for you, because... she needs your help again.  I think it has something to do with her studies on dragons. You should speak to her in the Burning Steppes, at the Flame Crest.]],logDesc=[[Speak with Tinkee Steamboil at Flame Crest in the Burning Steppes.]]}
DB[4921]={id=4921,zoneId=17,name=[[Lost in Battle]],name_loc=[[Perdida en la batalla]],level=20,minLevel=14,giver=[[Mankrik]],giverType=[[NPC]],giverId=3432,ender=[[Mankrik]],enderType=[[NPC]],enderId=3432,poiX=-1787,poiY=-2376,wowhead=[[https://www.wowhead.com/wotlk/quest=4921]],image=[[assets/images/quests/placeholder.png]],desc=[[We battled in a small tauren camp when we were separated--she held three of the Bristlebacks off by herself. But the odds began to overwhelm us. I led some away only to see her overwhelmed by newcomers. In my rage, I turned to face my enemies, but they brought me down easily with their vast numbers. I awoke to a tauren druid tending my wounds--he had come across me on the Gold Road as I fell. Please, $c, find some sign of my wife.]],logDesc=[[Find Mankrik's wife and then return to him in the Crossroads.]]}
DB[4941]={id=4941,zoneId=1637,name=[[Eitrigg's Wisdom]],name_loc=[[La sabiduría de Eitrigg]],level=60,minLevel=55,giver=[[Warlord Goretooth]],giver_loc=[[Señor de la guerra Dientegore]],giverType=[[NPC]],giverId=9077,ender=[[Thrall]],ender_loc=[[Thrall]],enderType=[[NPC]],enderId=4949,prevId=4903,rewardNextId=4974,poiX=1920,poiY=-4124,wowhead=[[https://www.wowhead.com/wotlk/quest=4941]],image=[[assets/images/quests/placeholder.png]],desc=[[Rend lives? Impossible! It had been thought that Rend  was slain decades ago. Seek out the wisdom of Eitrigg, $N. None know the workings of the Blackrock better than he and if what is written here bares truth, Eitrigg should be informed. No person should be denied the right of vengeance. You will find him in Orgrimmar. Once you have spoken with Eitrigg, confer with the Warchief to find out what he wishes to do about this problem.]],logDesc=[[Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall. You recall having seen Eitrigg in Thrall's chamber.]]}
DB[4961]={id=4961,name=[[Cleansing of the Orb of Orahil]],name_loc=[[La purificación del orbe de Orahil]],level=40,minLevel=35,giver=[[Tabetha]],giverType=[[NPC]],giverId=6546,ender=[[Tabetha]],enderType=[[NPC]],enderId=6546,prevId=1799,rewardNextId=4976,poiX=-4032,poiY=-3391,wowhead=[[https://www.wowhead.com/wotlk/quest=4961]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, a summoner's orb--this is where the taint must be coming from. We must exorcise the demon within it if you're to use it. That I can do easily. You're the one who has the hard job.  You must kill the demon once I release it. And you'll have to be quick.  If you take too long then he'll return to the orb and we'll have to start over! So get yourself ready, $N.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty.]],logDesc=[[Kill the Demon of the Orb, then speak with Tabetha.]],rewards={{id=12642,qty=1}}}
DB[4962]={id=4962,name=[[Shard of a Felhound]],name_loc=[[Fragmento de can manáfago]],level=40,minLevel=35,giver=[[Acolyte Wytula]],giver_loc=[[Acólito Wytula]],giverType=[[NPC]],giverId=6254,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,prevId=-1799,exGroup=4962,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4962]],image=[[assets/images/quests/placeholder.png]],desc=[[So, you have chosen to capture the soul of a felhound, good. Take this ruby--with it, you will be able to capture the creature's soul. It works very similar to spells you already know: when the creature is close to dying, use the gem and it should do the rest of the work for you. I would suggest going to Desolace and trying your hand at any of the felhounds there. Those should do nicely. After you're successful, take both the captured spirit and your ruby to Menara.]],logDesc=[[Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens.]]}
DB[4963]={id=4963,name=[[Shard of an Infernal]],name_loc=[[Fragmento de infernal]],level=40,minLevel=35,giver=[[Acolyte Magaz]],giver_loc=[[Acólito Magaz]],giverType=[[NPC]],giverId=6252,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,prevId=-1799,exGroup=4962,poiX=-1849,poiY=1649,wowhead=[[https://www.wowhead.com/wotlk/quest=4963]],image=[[assets/images/quests/placeholder.png]],desc=[[So, you have chosen to capture the soul of an infernal, good. Take this emerald--with it, you will be able to capture the creature's soul. It works very similar to spells you already know: when the creature is close to dying, use the gem and it should do the rest of the work for you. I would suggest going to Desolace and trying your hand at any of the infernals there. Those should do nicely. After you're successful, take both the captured spirit and your emerald to Menara.]],logDesc=[[Take the Infus Emerald and use it on one of the Infernals found in Desolace. After successful, bring the Infus Emerald and the Imprisoned Infernal Spirit back to Menara Voidrender in the Barrens.]]}
DB[4964]={id=4964,name=[[The Completed Orb of Dar'Orahil]],name_loc=[[El orbe completo de Dar'Orahil]],level=40,minLevel=35,giver=[[Menara Voidrender]],giver_loc=[[Menara Nadiz]],giverType=[[NPC]],giverId=6266,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,prevId=4976,exGroup=4964,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4964]],image=[[assets/images/quests/placeholder.png]],desc=[[I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb. I always felt it was important to cater to a warlock's chosen weapon... I see no reason not to continue that practice.]],logDesc=[[Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.]],choiceRewards={{id=15108,qty=1},{id=15106,qty=1}}}
DB[4965]={id=4965,name=[[Knowledge of the Orb of Orahil]],name_loc=[[El conocimiento del orbe de Orahil]],level=35,minLevel=35,giver=[[Briarthorn]],giver_loc=[[Brezospina]],giverType=[[NPC]],giverId=5172,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,rewardNextId=1799,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4965]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, well, well... a pleasure to see you're growing in power, $N. I'd wager you'd be about ready to speak to Menara Voidrender in the Barrens. If you haven't spoken to her before, then let me tell you, I don't think I've ever met another expert in the creation of items--orbs specifically--that can inprison even a demon to serve our will so easily. If you're interested, she's in Strahad's tower above Ratchet in the Barrens.]],logDesc=[[Speak to Menara Voidrender in the Barrens.]]}
DB[4966]={id=4966,zoneId=400,name=[[Protect Kanati Greycloud]],name_loc=[[Defensa de Kanati Nube Gris]],level=28,minLevel=23,giver=[[Kanati Greycloud]],giver_loc=[[Kanati Nube Gris]],giverType=[[NPC]],giverId=10638,ender=[[Kanati Greycloud]],ender_loc=[[Kanati Nube Gris]],enderType=[[NPC]],enderId=10638,prevId=4881,poiX=-4907,poiY=-1414,wowhead=[[https://www.wowhead.com/wotlk/quest=4966]],image=[[assets/images/quests/placeholder.png]],desc=[[But, there may be more centaur than I thought, I ask you, $n, to fight with me against these vile assassins.]],logDesc=[[Protect Kanati Greycloud from the centaur attack.]],choiceRewards={{id=15461,qty=1},{id=15462,qty=1},{id=15463,qty=1}}}
DB[4967]={id=4967,name=[[Knowledge of the Orb of Orahil]],name_loc=[[El conocimiento del orbe de Orahil]],level=35,minLevel=35,giver=[[Zevrost]],giver_loc=[[Zevrost]],giverType=[[NPC]],giverId=3326,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,rewardNextId=1799,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4967]],image=[[assets/images/quests/placeholder.png]],desc=[[Still a fool, and still seeking the trappings of mortals. Yes, I speak to you with arrogance. I see you before me and I laugh. You're pathetic! But it matters not what I think. It only matters what those willing to deal with you thinks!  And in this case, against my better judgment, those with some portion of power feel you deserve more. If this is something you strive for then you should speak with Menara Voidrender in the tower above Ratchet. I believe you have met her before some time ago.]],logDesc=[[Speak to Menara Voidrender in the Barrens.]]}
DB[4968]={id=4968,name=[[Knowledge of the Orb of Orahil]],name_loc=[[El conocimiento del orbe de Orahil]],level=35,minLevel=35,giver=[[Demisette Cloyce]],giver_loc=[[Demisette Cloyce]],giverType=[[NPC]],giverId=461,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,rewardNextId=1799,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4968]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmm, you've made it this far... truly astonishing. I would have thought the corruption of channeling the arcane would have seeped into your very soul and driven you mad by now. How about we try and push you further then? If you want to test your skill, seek out Menara Voidrender above Ratchet in Strahad's tower. She will guide you.]],logDesc=[[Speak to Menara Voidrender in the Barrens.]]}
DB[4968]={id=4968,name=[[Knowledge of the Orb of Orahil]],name_loc=[[El conocimiento del orbe de Orahil]],level=35,minLevel=35,giver=[[Alamma]],giver_loc=[[Demisette Cloyce]],giverType=[[NPC]],giverId=16646,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,rewardNextId=1799,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4968]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmm, you've made it this far... truly astonishing. I would have thought the corruption of channeling the arcane would have seeped into your very soul and driven you mad by now. How about we try and push you further then? If you want to test your skill, seek out Menara Voidrender above Ratchet in Strahad's tower. She will guide you.]],logDesc=[[Speak to Menara Voidrender in the Barrens.]]}
DB[4969]={id=4969,name=[[Knowledge of the Orb of Orahil]],name_loc=[[El conocimiento del orbe de Orahil]],level=35,minLevel=35,giver=[[Kaal Soulreaper]],giver_loc=[[Kaal Segador de Almas]],giverType=[[NPC]],giverId=4563,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,rewardNextId=1799,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4969]],image=[[assets/images/quests/placeholder.png]],desc=[[Haha! You're doing very well for yourself, young $c. Given time, infernals and dreadlords will bow before you! But until that time comes, you must still rely on weapons forged by the hands of the mortal races. You seem prepared for another such creation, and if you are willing, Menara Voidrender would speak with you! She is near Strahad's tower overlooking the port town of Ratchet. Go there when you are ready.]],logDesc=[[Speak to Menara Voidrender in the Barrens.]]}
DB[4970]={id=4970,zoneId=618,name=[[Frostsaber Provisions]],name_loc=[[Provisiones de sable de hielo]],level=60,minLevel=58,giver=[[Rivern Frostwind]],giver_loc=[[Rivern Ventogélido]],giverType=[[NPC]],giverId=10618,ender=[[Rivern Frostwind]],ender_loc=[[Rivern Ventogélido]],enderType=[[NPC]],enderId=10618,poiX=6220,poiY=-5202,wowhead=[[https://www.wowhead.com/wotlk/quest=4970]],image=[[assets/images/quests/placeholder.png]],desc=[[If you wish to prove yourself, you may begin by doing a very simple, but very important task. Gather meat from the chimaera and from the shardtooth bears in the area. Bring it to me so that I may use it to feed the frostsabers that are being trained.]],logDesc=[[Collect 5 Shardtooth Meats and 5 Chillwind Meats for Rivern Frostwind in Winterspring.]]}
DB[4971]={id=4971,zoneId=28,name=[[A Matter of Time]],name_loc=[[Una cuestión de tiempo]],level=56,minLevel=53,giver=[[Chromie]],giver_loc=[[Cromi]],giverType=[[NPC]],giverId=10667,ender=[[Chromie]],ender_loc=[[Cromi]],enderType=[[NPC]],enderId=10667,poiX=1453,poiY=-1280,wowhead=[[https://www.wowhead.com/wotlk/quest=4971]],image=[[assets/images/quests/placeholder.png]],desc=[[Tampering of the timeline by a sinister force - most likely the Scourge - has occurred in Andorhal!  I can try to keep the passage of time here intact and mend what has been damaged, but I'll need your help to do so uninterrupted. Temporal parasites - carrion that feed on the strands of time's altered flow - now infest the silos of Andorhal.  A blue pulse of distortion is their only visual marker.  They slow my auguries; please $N, help me by using this temporal displacer to root out these parasites.]],logDesc=[[Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites. Slay 10 Temporal Parasites, and then return the Temporal Displacer to Chromie in the Andorhal Inn, Western Plaguelands.]],choiceRewards={{id=15812,qty=1},{id=15813,qty=1}}}
DB[4972]={id=4972,zoneId=28,name=[[Counting Out Time]],name_loc=[[Contar el tiempo]],level=56,minLevel=53,giver=[[Chromie]],giver_loc=[[Cromi]],giverType=[[NPC]],giverId=10667,ender=[[Chromie]],ender_loc=[[Cromi]],enderType=[[NPC]],enderId=10667,prevId=4971,poiX=1275,poiY=-1578,wowhead=[[https://www.wowhead.com/wotlk/quest=4972]],image=[[assets/images/quests/placeholder.png]],desc=[[I need you to reach into the world beyond this room, $N.  Allow me to explain. You see the difference in this room compared to the rest of Andorhal.  My dragonflight works in many different ways and in many different timelines.  To mend Andorhal's damage, I now act from a different timeline as not to overly contaminate it.  To continue this though I need time trinkets, ones trapped from when the plague hit.  Find them in lockboxes found in the ruined buildings that make up this once proud city.]],logDesc=[[Locate 5 Andorhal Watches, found in lockboxes amongst the rubble of the city.  Return with them to Chromie in the Andorhal Inn, Western Plaguelands.]],rewards={{id=12650,qty=1}}}
DB[4973]={id=4973,zoneId=28,name=[[Counting Out Time]],name_loc=[[Contar el tiempo]],level=56,minLevel=53,giver=[[Chromie]],giver_loc=[[Cromi]],giverType=[[NPC]],giverId=10667,ender=[[Chromie]],ender_loc=[[Cromi]],enderType=[[NPC]],enderId=10667,prevId=4972,poiX=1275,poiY=-1578,wowhead=[[https://www.wowhead.com/wotlk/quest=4973]],image=[[assets/images/quests/placeholder.png]],desc=[[If you are willing to help once more, I can certainly use your assistance.  I'll gladly take more watches you might uncover from the ruins of Andorhal.  They certainly help me in maintaining a balance against whatever malign force is meddling with the timeline here. In exchange for those watches, I'll give you another item that, in the future, I suspect you'll find quite the use for.]],logDesc=[[Locate 5 Andorhal Watches amongst the rubble of the city, and return with them to Chromie in the Andorhal Inn, Western Plaguelands.]],rewards={{id=12650,qty=1}}}
DB[4974]={id=4974,zoneId=1583,name=[[For The Horde!]],name_loc=[[¡Por la Horda!]],level=60,minLevel=55,giver=[[Thrall]],giver_loc=[[Thrall]],giverType=[[NPC]],giverId=4949,ender=[[Thrall]],ender_loc=[[Thrall]],enderType=[[NPC]],enderId=4949,prevId=4941,poiX=1924,poiY=-4159,wowhead=[[https://www.wowhead.com/wotlk/quest=4974]],image=[[assets/images/quests/placeholder.png]],desc=[[Rend dares make such grand claims because of the protection he is afforded by the black flight. You, $N, will find a way to pass through the Halls of Ascension. You will then find 'Warchief' Rend Blackhand and you will destroy him - FOR THE HORDE! <Thrall slams a fist down upon his throne.> The next time you return to my chambers, you will hold his head high in triumph and then you shall present it to your Warchief. Do this and be honored as a hero of the Horde.]],logDesc=[[Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar.]],choiceRewards={{id=13966,qty=1},{id=13968,qty=1},{id=13965,qty=1}}}
DB[4975]={id=4975,name=[[The Completed Orb of Noh'Orahil]],name_loc=[[El orbe completo de Noh'Orahil]],level=40,minLevel=35,giver=[[Menara Voidrender]],giver_loc=[[Menara Nadiz]],giverType=[[NPC]],giverId=6266,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,prevId=4976,exGroup=4964,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4975]],image=[[assets/images/quests/placeholder.png]],desc=[[I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb. I always felt it was important to cater to a warlock's chosen weapon... I see no reason not to continue that practice.]],logDesc=[[Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again.]],choiceRewards={{id=15107,qty=1},{id=15105,qty=1}}}
DB[4976]={id=4976,name=[[Returning the Cleansed Orb]],name_loc=[[Devolver el orbe purificado]],level=40,minLevel=35,giver=[[Tabetha]],giverType=[[NPC]],giverId=6546,ender=[[Menara Voidrender]],ender_loc=[[Menara Nadiz]],enderType=[[NPC]],enderId=6266,prevId=4961,poiX=-783,poiY=-3711,wowhead=[[https://www.wowhead.com/wotlk/quest=4976]],image=[[assets/images/quests/placeholder.png]],desc=[[Take the cleansed orb back to Menara in Ratchet, $N. Give her my regards and be safe. I truly hope you are able to withstand the temptation and corruption that is sure to come as you follow your path. Good luck.]],logDesc=[[Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens.]]}
DB[4981]={id=4981,zoneId=1583,name=[[Operative Bijou]],name_loc=[[La espía Bijou]],level=59,minLevel=55,giver=[[Lexlort]],giver_loc=[[Lexlort]],giverType=[[NPC]],giverId=9080,ender=[[Bijou]],enderType=[[NPC]],enderId=10257,rewardNextId=4982,wowhead=[[https://www.wowhead.com/wotlk/quest=4981]],image=[[assets/images/quests/placeholder.png]],desc=[[Never trust a goblin. That's what it comes down to, $N. Bijou is her name - one of our slipperiest operatives. I found out she was working for some shady exotic pet dealer out of the Burning Steppes named Kibler, in essence, two timing us. Worse yet, she was using Horde funds to finance her operations. I want her brought back here alive. She was last seen entering Blackrock Spire. Find her and bring her back. And $N, do not let her sweet talk you.]],logDesc=[[Travel to Blackrock Spire and find out what happened to Bijou.]]}
DB[4982]={id=4982,zoneId=1583,name=[[Bijou's Belongings]],name_loc=[[Las pertenencias de Bijou]],level=59,minLevel=55,giver=[[Bijou]],giverType=[[NPC]],giverId=10257,ender=[[Bijou]],enderType=[[NPC]],enderId=10257,prevId=4981,rewardNextId=4983,wowhead=[[https://www.wowhead.com/wotlk/quest=4982]],image=[[assets/images/quests/placeholder.png]],desc=[[At night when this place is lightly guarded, I sneak around the city, taking notes and writing down anything I see that could be of some strategic value to the K.E.F. Last night, however, things went dreadfully wrong. I stumbled across a tripwire and set off an alarm. I stashed my recon gear and ran for cover! Unfortunately, I can't get back to that gear. They've doubled and tripled up the patrols! All that information is lost. Get my belongings back and I'll return to the K.E.F. peacefully.]],logDesc=[[Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city. ]]}
DB[4983]={id=4983,zoneId=1583,name=[[Bijou's Reconnaissance Report]],name_loc=[[El informe de reconocimiento de Bijou]],level=59,minLevel=55,giver=[[Bijou]],giverType=[[NPC]],giverId=10257,ender=[[Lexlort]],ender_loc=[[Lexlort]],enderType=[[NPC]],enderId=9080,prevId=4982,poiX=-6679,poiY=-2225,wowhead=[[https://www.wowhead.com/wotlk/quest=4983]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this report back to Lexlort. It will redeem my good name and will surely give the K.E.F. a strategic advantage in dealing with these orcs. Come with you? I've got way too much work to do. Get going, they need these reports as soon as possible! ]],logDesc=[[Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath. ]],choiceRewards={{id=15858,qty=1},{id=15859,qty=1}}}
DB[4984]={id=4984,zoneId=28,name=[[The Wildlife Suffers Too]],name_loc=[[La naturaleza también sufre]],level=54,minLevel=51,giver=[[Mulgris Deepriver]],giver_loc=[[Mulgris Riohondo]],giverType=[[NPC]],giverId=10739,ender=[[Mulgris Deepriver]],ender_loc=[[Mulgris Riohondo]],enderType=[[NPC]],enderId=10739,rewardNextId=4985,poiX=1615,poiY=-1817,wowhead=[[https://www.wowhead.com/wotlk/quest=4984]],image=[[assets/images/quests/placeholder.png]],desc=[[While there was little I could do alone to thwart the Scourge, I nevertheless came to these lands to try and heal the damage done to nature.  Animals suffer from the plague that continues to choke these lands, unable to find mercy and peace.  I ask for you to continue what I could not finish here. There is no salvation for the suffering animals but a sweet and merciful release.  Seek out diseased wolves nearby and put them down.  Please $N, end their misery - doing so will surely soothe mine.]],logDesc=[[Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands. ]]}
DB[4985]={id=4985,zoneId=28,name=[[The Wildlife Suffers Too]],name_loc=[[La naturaleza también sufre]],level=56,minLevel=51,giver=[[Mulgris Deepriver]],giver_loc=[[Mulgris Riohondo]],giverType=[[NPC]],giverId=10739,ender=[[Mulgris Deepriver]],ender_loc=[[Mulgris Riohondo]],enderType=[[NPC]],enderId=10739,prevId=4984,poiX=2015,poiY=-2517,wowhead=[[https://www.wowhead.com/wotlk/quest=4985]],image=[[assets/images/quests/placeholder.png]],desc=[[To the east of where we are, near where the Eastern Plaguelands begin, once proud and majestic grizzlies roamed the countryside.  The plague released by the Scourge has sundered these beasts too.  They wander the countryside, agonized by the stiffening of their muscles and the rotting of their fur and flesh. I ask of you to end their misery as well.  The only cure for their suffering is a swift death, one that must be ministered by your hand.]],logDesc=[[Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.]]}
DB[4986]={id=4986,zoneId=28,name=[[Glyphed Oaken Branch]],name_loc=[[Rama de roble con inscripciones]],level=56,minLevel=51,giver=[[Mulgris Deepriver]],giver_loc=[[Mulgris Riohondo]],giverType=[[NPC]],giverId=10739,ender=[[Mathrengyl Bearwalker]],ender_loc=[[Mathrengyl Garroso]],enderType=[[NPC]],enderId=4217,prevId=4985,poiX=10179,poiY=2564,wowhead=[[https://www.wowhead.com/wotlk/quest=4986]],image=[[assets/images/quests/placeholder.png]],desc=[[The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch.  Examining the branch reveals glyphs of a druidic nature carved into the bark. As you grasp the branch, you notice it is warm to the touch, more than it should be.  The image of the Teldrassil tree enters your mind - Darnassus specifically - and the words "Cenarion Circle" are on the tip of your tongue.  It would appear that the suggestion of where to take the branch has been placed within it.]],logDesc=[[Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought.  Seek one of the druids there for assistance.]],rewards={{id=15804,qty=1}}}
DB[4987]={id=4987,zoneId=28,name=[[Glyphed Oaken Branch]],name_loc=[[Rama de roble con inscripciones]],level=56,minLevel=51,giver=[[Mulgris Deepriver]],giver_loc=[[Mulgris Riohondo]],giverType=[[NPC]],giverId=10739,ender=[[Nara Wildmane]],ender_loc=[[Nara Ferocrín]],enderType=[[NPC]],enderId=5770,prevId=4985,poiX=-1070,poiY=-273,wowhead=[[https://www.wowhead.com/wotlk/quest=4987]],image=[[assets/images/quests/placeholder.png]],desc=[[The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch.  Examining the branch reveals glyphs of a druidic nature carved into the bark. As you grasp the branch, you notice it is warm to the touch, more than it should be.  The image of Thunder Bluff in Mulgore enters your mind - Elder Rise specifically - and the words "Cenarion Circle" are on the tip of your tongue.  It would appear that the suggestion of where to take the branch has been placed within it.]],logDesc=[[Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Thunder Bluff is the next step the tauren druid sought.  Seek one of the druids there for assistance.]],rewards={{id=15804,qty=1}}}
DB[5001]={id=5001,zoneId=1583,name=[[Bijou's Belongings]],name_loc=[[Las pertenencias de Bijou]],level=59,minLevel=55,giver=[[Bijou]],giverType=[[NPC]],giverId=10257,ender=[[Bijou]],enderType=[[NPC]],enderId=10257,rewardNextId=5002,wowhead=[[https://www.wowhead.com/wotlk/quest=5001]],image=[[assets/images/quests/placeholder.png]],desc=[[Ordinarily I don't deal with $rs but it seems that I'm stuck between a troll and a hard place. You see, my mission here is one of utmost importance to the Horde. The information I've discovered, however, applies to the well being of the Alliance as well. Now believe me, I'm no Alliance sympathizer, but the Blackrock threat is bigger than just a bunch of orcs. You help me out by finding my belongings and I'll help you out with some information that could prove useful to your kind. Deal?]],logDesc=[[Find Bijou's Belongings and return them to her. Good luck! ]]}
DB[5002]={id=5002,zoneId=1583,name=[[Message to Maxwell]],name_loc=[[Un mensaje para Maxwell]],level=59,minLevel=55,giver=[[Bijou]],giverType=[[NPC]],giverId=10257,ender=[[Marshal Maxwell]],ender_loc=[[Mariscal Maxwell]],enderType=[[NPC]],enderId=9560,prevId=5001,rewardNextId=5081,poiX=-8379,poiY=-2749,wowhead=[[https://www.wowhead.com/wotlk/quest=5002]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm a goblin of my word, $r. Now listen closely: These orcs are used primarily as beasts of burden and cannon fodder for the black dragonflight! Their true leader is none other than Nefarian, brood of Deathwing. I've also discovered the location of Nefarian's subordinates in this part of the citadel. Take this map to Marshal Maxwell in the Burning Steppes. It has the location of these fiends marked for easy identification.]],logDesc=[[Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell.]]}
DB[5021]={id=5021,zoneId=28,name=[[Better Late Than Never]],name_loc=[[Más vale tarde que nunca]],level=52,minLevel=50,giver=[[Janice Felstone]],giver_loc=[[Janice Piedra Mácula]],giverType=[[NPC]],giverId=10778,ender=[[Janice's Parcel]],ender_loc=[[Paquete de Janice]],enderType=[[GO]],enderId=175894,poiX=1783,poiY=-1249,wowhead=[[https://www.wowhead.com/wotlk/quest=5021]],image=[[assets/images/quests/placeholder.png]],desc=[["The package must be delivered... delivered before I'm trapped here!" The cries of a panicked woman feel almost like a whisper floating through the house.  Cowered in the upstairs corner is the apparition of a woman.  She does not seem to be fully cognizant of her surroundings, and she is only vaguely aware of you. "Are you here to deliver my package?  Please, before it gets much worse!  I was going to ride out of here.  It should still be by my horse... or am I too late?"]],logDesc=[[The ramblings of the ghostly woman indicated that she needed a package delivered.  She claimed that it was where her horse was.  As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible.]]}
DB[5022]={id=5022,zoneId=28,name=[[Better Late Than Never]],name_loc=[[Más vale tarde que nunca]],level=52,minLevel=50,giver=[[Janice's Parcel]],giver_loc=[[Paquete de Janice]],giverType=[[GO]],giverId=175894,ender=[[Royal Factor Bathrilor]],ender_loc=[[Agente Real Bathrilor]],enderType=[[NPC]],enderId=10782,prevId=5021,rewardNextId=5048,poiX=-8553,poiY=729,wowhead=[[https://www.wowhead.com/wotlk/quest=5022]],image=[[assets/images/quests/placeholder.png]],desc=[[You pick up the package, wiping off a small layer of dust and grime that had settled on it.  It is addressed in a hurried hand to an Emma Felstone of Stormwind; the delivery of the package is dated for well over four years ago. Though it is unclear if Emma Felstone is even alive, it is widely known that the Stormwind City Hall keep records on the populace of the city.  This is handled through the Royal Factors of the Stormwind Census.]],logDesc=[[Check with the Royal Factors of Stormwind to learn the whereabouts of an Emma Felstone.  There is usually a census officer located in City Hall.]]}
DB[5023]={id=5023,zoneId=28,name=[[Better Late Than Never]],name_loc=[[Más vale tarde que nunca]],level=52,minLevel=50,giver=[[Janice's Parcel]],giver_loc=[[Paquete de Janice]],giverType=[[GO]],giverId=175894,ender=[[Royal Overseer Bauhaus]],ender_loc=[[Sobrestante real Bauhaus]],enderType=[[NPC]],enderId=10781,prevId=5021,rewardNextId=5049,poiX=1602,poiY=204,wowhead=[[https://www.wowhead.com/wotlk/quest=5023]],image=[[assets/images/quests/placeholder.png]],desc=[[You pick up the package, wiping off a small layer of dust and grime that had settled on it.  It is addressed in a hurried hand to a Jeremiah Felstone of Lordaeron; the delivery of the package is dated for well over four years ago. Though it is unclear if Jeremiah Felstone is even alive, it is widely known that the Undercity, formerly known as Lordaeron, keeps records on the populace of the city.  This is handled through the Royal Overseers of the Undercity Census.]],logDesc=[[Check with the Royal Overseers of the Undercity to learn the whereabouts of a Jeremiah Felstone.  There is usually a census officer located near guild and tabard registration.]]}
DB[5041]={id=5041,zoneId=17,name=[[Supplies for the Crossroads]],name_loc=[[Suministros para El Cruce]],level=14,minLevel=9,giver=[[Thork]],giverType=[[NPC]],giverId=3429,ender=[[Thork]],enderType=[[NPC]],enderId=3429,poiX=-48,poiY=-3403,wowhead=[[https://www.wowhead.com/wotlk/quest=5041]],image=[[assets/images/quests/placeholder.png]],desc=[[That attack on the caravan contained supplies we desperately needed. You've been brave enough to take on the Razormane tribe so far, and I will ask you to do so again, but this time, I wonder if I could ask you to keep your eyes open for some of our lost supplies. You can probably find them throughout their camps, the quilboar getting fat off their dishonorable acts. The people of the Crossroads would be in your debt.]],logDesc=[[Find and return Crossroads' Supply Crates to Thork in the Barrens.]]}
DB[5042]={id=5042,zoneId=17,name=[[Agamaggan's Strength]],name_loc=[[La fuerza de Agamaggan]],level=20,minLevel=14,giver=[[Mangletooth]],giver_loc=[[Quebrantadientes]],giverType=[[NPC]],giverId=3430,ender=[[Mangletooth]],ender_loc=[[Quebrantadientes]],enderType=[[NPC]],enderId=3430,prevId=5052,poiX=-2392,poiY=-1891,wowhead=[[https://www.wowhead.com/wotlk/quest=5042]],image=[[assets/images/quests/placeholder.png]]}
