DB[5044]={id=5044,zoneId=17,name=[[Wisdom of Agamaggan]],name_loc=[[La sabiduría de Agamaggan]],level=20,minLevel=14,giver=[[Mangletooth]],giver_loc=[[Quebrantadientes]],giverType=[[NPC]],giverId=3430,ender=[[Mangletooth]],ender_loc=[[Quebrantadientes]],enderType=[[NPC]],enderId=3430,prevId=5052,poiX=-2392,poiY=-1891,wowhead=[[https://www.wowhead.com/wotlk/quest=5044]],image=[[assets/images/quests/placeholder.png]]}
DB[5045]={id=5045,zoneId=17,name=[[Rising Spirit]],name_loc=[[Fortaleza de espíritu]],level=20,minLevel=14,giver=[[Mangletooth]],giver_loc=[[Quebrantadientes]],giverType=[[NPC]],giverId=3430,ender=[[Mangletooth]],ender_loc=[[Quebrantadientes]],enderType=[[NPC]],enderId=3430,prevId=5052,poiX=-2392,poiY=-1891,wowhead=[[https://www.wowhead.com/wotlk/quest=5045]],image=[[assets/images/quests/placeholder.png]]}
DB[5046]={id=5046,zoneId=17,name=[[Razorhide]],name_loc=[[Ocultafilo]],level=20,minLevel=14,giver=[[Mangletooth]],giver_loc=[[Quebrantadientes]],giverType=[[NPC]],giverId=3430,ender=[[Mangletooth]],ender_loc=[[Quebrantadientes]],enderType=[[NPC]],enderId=3430,prevId=5052,poiX=-2392,poiY=-1891,wowhead=[[https://www.wowhead.com/wotlk/quest=5046]],image=[[assets/images/quests/placeholder.png]]}
DB[5047]={id=5047,zoneId=1583,name=[[Finkle Einhorn, At Your Service!]],name_loc=[[¡Finkle Einhorn, a tu servicio!]],level=60,minLevel=57,giver=[[Finkle Einhorn]],giver_loc=[[Finkle Unicornín]],giverType=[[NPC]],giverId=10776,ender=[[Malyfous Darkhammer]],ender_loc=[[Malyfous Martilloscuro]],enderType=[[NPC]],enderId=10637,poiX=6698,poiY=-4647,wowhead=[[https://www.wowhead.com/wotlk/quest=5047]],image=[[assets/images/quests/placeholder.png]],desc=[[You'll find Malyfous Darkhammer in Everlook, $c. Tell him that 'Finkle is A-OK' and that the suit works perfectly. Then hand him this: <Finkle hands you a glowing piece of flesh.> I snatched it from the beast's innards during my 'vacation.' I bet Malyfous could give you a fairly accurate assessment of what he can do with parts from a monster like this! Oh, I suppose you don't know where Everlook is, do you? To Winterspring, $g fella:lady;!]],logDesc=[[Talk to Malyfous Darkhammer in Everlook.]]}
DB[5048]={id=5048,zoneId=1519,name=[[Good Natured Emma]],name_loc=[[El buen carácter de Emma]],level=52,minLevel=50,giver=[[Royal Factor Bathrilor]],giver_loc=[[Agente Real Bathrilor]],giverType=[[NPC]],giverId=10782,ender=[[Ol' Emma]],ender_loc=[[Vieja Emma]],enderType=[[NPC]],enderId=3520,prevId=5022,nextId=5050,rewardNextId=5050,poiX=-8657,poiY=677,wowhead=[[https://www.wowhead.com/wotlk/quest=5048]],image=[[assets/images/quests/placeholder.png]],desc=[[She's a tad ornery, and quite possibly out of her gourd... but the records indicate that Ol' Emma does fit the framework of who Emma Felstone might be. Perhaps you've seen Ol' Emma wander the city - she talks to herself, most often in nonsensical jibber-jabber.  Still, she doesn't hurt anything or anyone, so folks pretty much leave her be. All things considered, I would say that Ol' Emma is in fact Emma Felstone.  You might try asking if her last name is indeed Felstone.]],logDesc=[[Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone.  If she is, then perhaps she'd like the package Janice Felstone made for her.]]}
DB[5049]={id=5049,zoneId=1497,name=[[The Jeremiah Blues]],name_loc=[[La depre de Jeremiah]],level=52,minLevel=50,giver=[[Royal Overseer Bauhaus]],giver_loc=[[Sobrestante real Bauhaus]],giverType=[[NPC]],giverId=10781,ender=[[Jeremiah Payson]],ender_loc=[[Jeremiah Payson]],enderType=[[NPC]],enderId=8403,prevId=5023,nextId=5050,rewardNextId=5050,poiX=1595,poiY=225,wowhead=[[https://www.wowhead.com/wotlk/quest=5049]],image=[[assets/images/quests/placeholder.png]],desc=[[From the evidence I am able to muster, the person you seek - and the intended recipient of the parcel - is Jeremiah Payson, the Undercity cockroach vendor. I've always been of the opinion that it takes a special gift to sell... cockroaches.  No doubt you are on quite the epic sojourn now, mighty $c.  I will leave you to your world-shaping endeavors.  Allow me, however, to be a part of your magnum opus and reveal that he is located near the bank, suitably groveling under one of the walkways.]],logDesc=[[Find Jeremiah Payson in the Undercity and see if he is in fact Jeremiah Felstone.  If he is, then perhaps he'd like the package Janice Felstone made for him.]]}
DB[5050]={id=5050,zoneId=28,name=[[Good Luck Charm]],name_loc=[[Talismán de buena suerte]],level=52,minLevel=50,giver=[[Ol' Emma]],giver_loc=[[Vieja Emma]],giverType=[[NPC]],giverId=3520,ender=[[Janice Felstone]],ender_loc=[[Janice Piedra Mácula]],enderType=[[NPC]],enderId=10778,rewardNextId=5051,poiX=1817,poiY=-1235,wowhead=[[https://www.wowhead.com/wotlk/quest=5050]],image=[[assets/images/quests/placeholder.png]],desc=[[It would seem that I was wrong about you $N, and for that I owe you an apology.  My sister sent me a number of personal effects, including humorously enough the deed to the Felstone farm.  I think I'll pass on reclaiming it right now. If my sister's spirit remains tethered to the farm and cannot rest, please... could you return this to her?  It is half of a good luck charm she had, with her husband having the other half. Maybe her knowing I have these things will now put her soul to rest.]],logDesc=[[Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm.]]}
DB[5050]={id=5050,zoneId=28,name=[[Good Luck Charm]],name_loc=[[Talismán de buena suerte]],level=52,minLevel=50,giver=[[Jeremiah Payson]],giver_loc=[[Vieja Emma]],giverType=[[NPC]],giverId=8403,ender=[[Janice Felstone]],ender_loc=[[Janice Piedra Mácula]],enderType=[[NPC]],enderId=10778,rewardNextId=5051,poiX=1817,poiY=-1235,wowhead=[[https://www.wowhead.com/wotlk/quest=5050]],image=[[assets/images/quests/placeholder.png]],desc=[[It would seem that I was wrong about you $N, and for that I owe you an apology.  My sister sent me a number of personal effects, including humorously enough the deed to the Felstone farm.  I think I'll pass on reclaiming it right now. If my sister's spirit remains tethered to the farm and cannot rest, please... could you return this to her?  It is half of a good luck charm she had, with her husband having the other half. Maybe her knowing I have these things will now put her soul to rest.]],logDesc=[[Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm.]]}
DB[5051]={id=5051,zoneId=28,name=[[Two Halves Become One]],name_loc=[[Dos mitades hacen una]],level=54,minLevel=50,giver=[[Janice Felstone]],giver_loc=[[Janice Piedra Mácula]],giverType=[[NPC]],giverId=10778,ender=[[Janice Felstone]],ender_loc=[[Janice Piedra Mácula]],enderType=[[NPC]],enderId=10778,prevId=5050,poiX=1751,poiY=-1217,wowhead=[[https://www.wowhead.com/wotlk/quest=5051]],image=[[assets/images/quests/placeholder.png]],desc=[[The ramblings of the poor ghost continue: "I'm so cold, John.  Bring me your charm, and we'll be together!  Quickly John, before the plague comes to change us into hideous beasts!  I can't see you John... but I know you're near.  I feel you near me." Perhaps if the second half of the charm was found and reassembled, this would constitute what the spirit of Janice Felstone is seeking.]],logDesc=[[Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it. Give the Good Luck Charm to Janice Felstone on the Felstone Farm, Western Plaguelands.]],rewards={{id=13473,qty=1}}}
DB[5052]={id=5052,zoneId=17,name=[[Blood Shards of Agamaggan]],name_loc=[[Esquirlas de sangre de Agamaggan]],level=21,minLevel=14,giver=[[Mangletooth]],giver_loc=[[Quebrantadientes]],giverType=[[NPC]],giverId=3430,ender=[[Mangletooth]],ender_loc=[[Quebrantadientes]],enderType=[[NPC]],enderId=3430,prevId=878,poiX=-2392,poiY=-1891,wowhead=[[https://www.wowhead.com/wotlk/quest=5052]],image=[[assets/images/quests/placeholder.png]],desc=[[Along with the thorns, the blood affected <snort> other aspects of the earth: blood red stones mixed in with other minerals. The Bristleback dig up these shards and carry them as totems <snort> for strength in battle and as totems for their magics. <snort> I know the secrets of that magic. Bring Mangletooth one of these blood shards to show you understand. Bring Mangletooth many of the shards, and he will bless you with quilboar magic--the magic of Agamaggan! <snort>]],logDesc=[[Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens. Collect more Blood Shards if you want him to bless you with Agamaggan's power.]]}
DB[5054]={id=5054,zoneId=618,name=[[Ursius of the Shardtooth]],name_loc=[[Ursius de los Dentoesquirla]],level=56,minLevel=53,giver=[[Storm Shadowhoof]],giver_loc=[[Ventisca Pezuña Umbría]],giverType=[[NPC]],giverId=10303,ender=[[Storm Shadowhoof]],ender_loc=[[Ventisca Pezuña Umbría]],enderType=[[NPC]],enderId=10303,rewardNextId=5055,poiX=6990,poiY=-4296,wowhead=[[https://www.wowhead.com/wotlk/quest=5054]],image=[[assets/images/quests/placeholder.png]],desc=[[In the snowy mountains of Winterspring, to the northwest, a skilled hunter stalks his prey... I speak of Ursius of the shardtooth bears, an agile and clever beast. I send you now against him. He roams the sloping hills to the northwest of Everlook. Find and hunt him, before he discovers your intent. All that have gone up against Ursius have quickly found themselves to be the prey, and he, the hunter. Stay on your guard.]],logDesc=[[Storm Shadowhoof at Everlook in Winterspring wants you to kill Ursius.]]}
DB[5055]={id=5055,zoneId=618,name=[[Brumeran of the Chillwind]],name_loc=[[Brumerán de los Orvallo]],level=58,minLevel=53,giver=[[Storm Shadowhoof]],giver_loc=[[Ventisca Pezuña Umbría]],giverType=[[NPC]],giverId=10303,ender=[[Storm Shadowhoof]],ender_loc=[[Ventisca Pezuña Umbría]],enderType=[[NPC]],enderId=10303,prevId=5054,rewardNextId=5056,poiX=5542,poiY=-4495,wowhead=[[https://www.wowhead.com/wotlk/quest=5055]],image=[[assets/images/quests/placeholder.png]],desc=[[Swift, and clever, Brumeran glides silently across the snowy landscape of southern Winterspring. But do not let her graceful appearance convince you that she is harmless. All that cross her pay considerably, and often with their own lives. Seek out Brumeran of the chillwind among the chimera. Defeat her, then return again to me.]],logDesc=[[Storm Shadowhoof at Everlook in Winterspring wants you to kill Brumeran.]]}
DB[5056]={id=5056,zoneId=618,name=[[Shy-Rotam]],name_loc=[[Shi-Rotam]],level=60,minLevel=53,giver=[[Storm Shadowhoof]],giver_loc=[[Ventisca Pezuña Umbría]],giverType=[[NPC]],giverId=10303,ender=[[Storm Shadowhoof]],ender_loc=[[Ventisca Pezuña Umbría]],enderType=[[NPC]],enderId=10303,prevId=5055,poiX=8073,poiY=-3817,wowhead=[[https://www.wowhead.com/wotlk/quest=5056]],image=[[assets/images/quests/placeholder.png]],desc=[[In northern Winterspring, great cats assemble around a large landmark called Frostsaber Rock. The leader of these cats is known by the name Shy-Rotam. Defeating the matriarch of the frostsabers would grant you much respect in the eyes of your fellow $r. Go again to the harsh wilds, and once there, gather sacred meat from the frostsabers. Find the stone of Shy-Rotam, and place it there. Placing the meat of her kin before her will summon Shy-Rotam, in anger. Be ready for her fury, and defeat her.]],logDesc=[[Storm Shadowhoof at Everlook in Winterspring wants you to defeat Shy-Rotam.]],choiceRewards={{id=15783,qty=1},{id=15782,qty=1}}}
DB[5057]={id=5057,zoneId=618,name=[[Past Endeavors]],name_loc=[[Esfuerzos del pasado]],level=60,minLevel=53,giver=[[Storm Shadowhoof]],giver_loc=[[Ventisca Pezuña Umbría]],giverType=[[NPC]],giverId=10303,ender=[[Storm Shadowhoof]],ender_loc=[[Ventisca Pezuña Umbría]],enderType=[[NPC]],enderId=10303,prevId=5056,poiX=6717,poiY=-4714,wowhead=[[https://www.wowhead.com/wotlk/quest=5057]],image=[[assets/images/quests/placeholder.png]],desc=[[Before you spoke to me, $N, I had heard of your endeavors... that you had an unyielding desire to prove yourself, that you had an exceptional ability as a $c, and I now know these things to be the truth. Those that excel as you do are worthy of recognition. Take this marker to a friend of mine in Thunder Bluff named Melor Stonehoof. I'm sure he will remember you, and what you accomplished so long ago. Speak to him of you recent victories, and do not ever forget what you have accomplished today.]],logDesc=[[Bring Storm Shadowhoof's Marker to Melor Stonehoof in Thunder Bluff.]],rewards={{id=15704,qty=1}}}
DB[5058]={id=5058,zoneId=28,name=[[Mrs. Dalson's Diary]],name_loc=[[El diario de la señora Dalson]],level=55,minLevel=52,giver=[[Mrs. Dalson's Diary]],giver_loc=[[Diario de la señora Dalson]],giverType=[[GO]],giverId=175926,ender=[[Mrs. Dalson's Diary]],ender_loc=[[Diario de la señora Dalson]],enderType=[[GO]],enderId=175926,poiX=1914,poiY=-1639,wowhead=[[https://www.wowhead.com/wotlk/quest=5058]],image=[[assets/images/quests/placeholder.png]]}
