DB[5060]={id=5060,zoneId=28,name=[[Locked Away]],name_loc=[[Encierro]],level=55,minLevel=52,giver=[[Locked Cabinet]],giver_loc=[[Armario cerrado]],giverType=[[GO]],giverId=175924,ender=[[Locked Cabinet]],ender_loc=[[Armario cerrado]],enderType=[[GO]],enderId=175924,poiX=1941,poiY=-1652,wowhead=[[https://www.wowhead.com/wotlk/quest=5060]],image=[[assets/images/quests/placeholder.png]],rewards={{id=13474,qty=1},{id=13475,qty=1}}}
DB[5061]={id=5061,name=[[Aquatic Form]],name_loc=[[Forma acuática]],level=-1,minLevel=16,giver=[[Dendrite Starblaze]],giver_loc=[[Dendrita Rafagaestelar]],giverType=[[NPC]],giverId=11802,ender=[[Mathrengyl Bearwalker]],ender_loc=[[Mathrengyl Garroso]],enderType=[[NPC]],enderId=4217,prevId=272,poiX=10179,poiY=2564,wowhead=[[https://www.wowhead.com/wotlk/quest=5061]],image=[[assets/images/quests/placeholder.png]],desc=[[You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect.  Go now back to your trainer, Mathrengyl Bearwalker, in Darnassus.  Show him your pendant and prove to him you are ready to learn what he has to teach you.  He will complete your training, allowing you to become one with the water. Goodbye, young druid.  We shall speak again.]],logDesc=[[Return to Darnassus and show Mathrengyl Bearwalker the Pendant of the Sea Lion.]],rewards={{id=16608,qty=1}}}
DB[5062]={id=5062,zoneId=400,name=[[Sacred Fire]],name_loc=[[El fuego Sagrado]],level=27,minLevel=24,giver=[[Motega Firemane]],giver_loc=[[Motega Pirocabello]],giverType=[[NPC]],giverId=10428,ender=[[Magatha Grimtotem]],ender_loc=[[Magatha Tótem Siniestro]],enderType=[[NPC]],enderId=4046,prevId=4865,poiX=-1065,poiY=-212,wowhead=[[https://www.wowhead.com/wotlk/quest=5062]],image=[[assets/images/quests/placeholder.png]],desc=[[Arikara is a deadly creature that must be dealt with swiftly. In order to hunt her down you will need to light the sacred fire of life - this will summon Arikara. Go now and harvest the rare Incendia agave plant. Once you have harvested enough agave, seek council with Magatha Grimtotem on Elder Rise in Thunder Bluff. She is a powerful shaman that can enchant the agave plant to create a powder that will light the fire. Travel northeast to the Boiling Pool and gather Incendia Agave.]],logDesc=[[Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff.]]}
DB[5063]={id=5063,zoneId=618,name=[[Cap of the Scarlet Savant]],name_loc=[[Almete del Sabio Escarlata]],level=60,minLevel=57,giver=[[Malyfous's Catalogue]],giver_loc=[[Catálogo de Malyfous]],giverType=[[GO]],giverId=175927,ender=[[Malyfous Darkhammer]],ender_loc=[[Malyfous Martilloscuro]],enderType=[[NPC]],enderId=10637,prevId=5047,poiX=6698,poiY=-4647,wowhead=[[https://www.wowhead.com/wotlk/quest=5063]],image=[[assets/images/quests/placeholder.png]],desc=[[A finer cap you may never see. From the pristine hide of the beast, our expert crafters will create the most phenomenal hat a prestidigitator could ever hope to don! Fifty gold pieces along with the listed items and your head shall be graced with the Cap of the Scarlet Savant: *The pristine hide of the Beast. *Frayed abomination stitchings. *Arcane crystals. *Enchanted scarlet thread. BEHOLD!]],logDesc=[[In order to create the Cap of the Scarlet Savant, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread.  You will also be required to pay 50 gold pieces for the crafting of the item.]],rewards={{id=12752,qty=1}}}
DB[5064]={id=5064,zoneId=400,name=[[Grimtotem Spying]],name_loc=[[Espiando a los Tótem Siniestro]],level=28,minLevel=24,giver=[[Cliffwatcher Longhorn]],giver_loc=[[Vigiarrisco Cuerno Largo]],giverType=[[NPC]],giverId=10537,ender=[[Cliffwatcher Longhorn]],ender_loc=[[Vigiarrisco Cuerno Largo]],enderType=[[NPC]],enderId=10537,prevId=4841,poiX=-4922,poiY=-1832,wowhead=[[https://www.wowhead.com/wotlk/quest=5064]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you have served us well in the past, so I now entrust to you an important mission. The Grimtotem Clan is up to something secretive. Three agents of unknown origin were seen visiting the Grimtotem over the recent weeks. We discovered that separate chests in Darkcloud Pinnacle hold these guarded messages. $N, if you succeed in this dangerous mission, I will reward you in kind. ]],logDesc=[[Locate and retrieve the three Secret Notes in Darkcloud Pinnacle.]],choiceRewards={{id=15457,qty=1},{id=15458,qty=1},{id=15459,qty=1}}}
DB[5065]={id=5065,zoneId=139,name=[[The Lost Tablets of Mosh'aru]],name_loc=[[Las tablillas perdidas Mosh'aru]],level=58,minLevel=40,giver=[[Prospector Ironboot]],giver_loc=[[Prospector Ferrobota]],giverType=[[NPC]],giverId=10460,ender=[[Prospector Ironboot]],ender_loc=[[Prospector Ferrobota]],enderType=[[NPC]],enderId=10460,prevId=3528,rewardNextId=4788,poiX=-6980,poiY=-4834,wowhead=[[https://www.wowhead.com/wotlk/quest=5065]],image=[[assets/images/quests/placeholder.png]],desc=[[The troll with whom you spoke did not tell the truth.  The two tablets you gained for him spoke of containing the essence of Hakkar, but there is more to that legend.  I have studied long, and found that there are six Tablets of Mosh'aru, not two!  Six! And I fear that we will not like what secrets the others hold.. Find the third and fourth tablets of Mosh'aru.  They're in the Eastern Plaguelands, held by the mossflayer trolls. Find them, and bring them to me.]],logDesc=[[Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris.]]}
DB[5066]={id=5066,zoneId=1519,name=[[A Call to Arms: The Plaguelands!]],name_loc=[[Un llamamiento a las armas: las Tierras de la Peste]],level=50,minLevel=50,giver=[[Crier Goodman]],giver_loc=[[Pregonero Buenhombre]],giverType=[[NPC]],giverId=2198,ender=[[Commander Ashlam Valorfist]],ender_loc=[[Comandante Ashlam Puñovalor]],enderType=[[NPC]],enderId=10838,rewardNextId=5092,poiX=958,poiY=-1419,wowhead=[[https://www.wowhead.com/wotlk/quest=5066]],image=[[assets/images/quests/placeholder.png]],desc=[[Hear ye, hear ye!  All heroes are called upon to heed these words! A call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands! Heroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!]],logDesc=[[Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains.]]}
DB[5067]={id=5067,zoneId=618,name=[[Leggings of Arcana]],name_loc=[[Leotardos de Arcana]],level=60,minLevel=57,giver=[[Malyfous's Catalogue]],giver_loc=[[Catálogo de Malyfous]],giverType=[[GO]],giverId=175927,ender=[[Malyfous Darkhammer]],ender_loc=[[Malyfous Martilloscuro]],enderType=[[NPC]],enderId=10637,prevId=5047,poiX=6698,poiY=-4647,wowhead=[[https://www.wowhead.com/wotlk/quest=5067]],image=[[assets/images/quests/placeholder.png]],desc=[[While the crafting of such an item has never successfully been accomplished, it is thought to be possible - under the right circumstance. Should the seeker of arcanum desire to imbue leggings with immense power, the following they must find: * The pristine hide of the Beast. * Frayed abomination stitchings. *Arcanite Bars. *Frostwhisper's embalming fluid. BEHOLD!]],logDesc=[[In order to create the Leggings of Arcana, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Frostwhisper's Embalming Fluid. You will also be required to pay 50 gold pieces for the crafting of the item.]],rewards={{id=12756,qty=1}}}
DB[5068]={id=5068,zoneId=618,name=[[Breastplate of Bloodthirst]],name_loc=[[Coraza Sed de Sangre]],level=60,minLevel=57,giver=[[Malyfous's Catalogue]],giver_loc=[[Catálogo de Malyfous]],giverType=[[GO]],giverId=175927,ender=[[Malyfous Darkhammer]],ender_loc=[[Malyfous Martilloscuro]],enderType=[[NPC]],enderId=10637,prevId=5047,poiX=6698,poiY=-4647,wowhead=[[https://www.wowhead.com/wotlk/quest=5068]],image=[[assets/images/quests/placeholder.png]],desc=[[It is said that only one Breastplate of Bloodthirst has ever been created and that it was made for the legendary assassin, Garona. Whether this world will ever see another is doubtful. Regardless! Our master crafters can reproduce the item given the necessary components: *The pristine hide of the Beast. *Frayed abomination stitchings. *Arcanite bars. *The skin of shadow. BEHOLD!]],logDesc=[[In order to create the Breastplate of Bloodthirst, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 10 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Skin of Shadow. You will also be required to pay 50 gold pieces for the crafting of the item.]],rewards={{id=12757,qty=1}}}
DB[5081]={id=5081,zoneId=1583,name=[[Maxwell's Mission]],name_loc=[[La misión de Maxwell]],level=60,minLevel=55,giver=[[Marshal Maxwell]],giver_loc=[[Mariscal Maxwell]],giverType=[[NPC]],giverId=9560,ender=[[Marshal Maxwell]],ender_loc=[[Mariscal Maxwell]],enderType=[[NPC]],enderId=9560,prevId=5002,poiX=-8379,poiY=-2749,wowhead=[[https://www.wowhead.com/wotlk/quest=5081]],image=[[assets/images/quests/placeholder.png]],desc=[[This information fills in the gaps to our otherwise impeccable intelligence of Blackrock Spire. The attack must be decisive, $N. First their war master, the troll Voone, must be destroyed. Without his battle plans, the Blackrock orcs will be thrown into chaos. You must then take out the ogre Highlord, Omokk. The cowardly ogres of Blackrock are powerless without his leadership. Lastly, the overlord of the citadel: Wyrmthalak. With Wyrmthalak dead, their central command unit is without a conduit.]],logDesc=[[Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak.]],choiceRewards={{id=13958,qty=1},{id=13959,qty=1},{id=13961,qty=1},{id=13962,qty=1},{id=13963,qty=1}}}
DB[5082]={id=5082,zoneId=618,name=[[Threat of the Winterfall]],name_loc=[[La amenaza de los Nevada]],level=56,minLevel=52,giver=[[Donova Snowden]],giver_loc=[[Donova Cubilnevado]],giverType=[[NPC]],giverId=9298,ender=[[Donova Snowden]],ender_loc=[[Donova Cubilnevado]],enderType=[[NPC]],enderId=9298,poiX=6783,poiY=-2783,wowhead=[[https://www.wowhead.com/wotlk/quest=5082]],image=[[assets/images/quests/placeholder.png]],desc=[[I came to Winterspring to investigate the Frostfire Hot Springs. I've noticed that the water seems to have ...strange qualities. I haven't yet been able to discover the source, and to tell you the truth, I've had some difficulty lately, due to the Winterfall furbolg. They seem to be drawn to the springs, just as I am. They have become extremely protective of the water, and won't let me come near the two larger springs to the north of here. I'd like to continue my studies, so won't you help me?]],logDesc=[[Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics.]]}
DB[5083]={id=5083,zoneId=618,name=[[Winterfall Firewater]],name_loc=[[Aguardiente Nevada]],level=56,minLevel=52,giverType=[[NPC]],ender=[[Donova Snowden]],ender_loc=[[Donova Cubilnevado]],enderType=[[NPC]],enderId=9298,rewardNextId=5084,poiX=6396,poiY=-2537,wowhead=[[https://www.wowhead.com/wotlk/quest=5083]],image=[[assets/images/quests/placeholder.png]],desc=[[This vial that you picked up from the Winterfall furbolg is empty, but you can detect a few drops of a strange green liquid inside; it almost glows. Is it something important? Donova Snowden would probably be able to tell you more, since she has been camped by the hot springs in Winterspring for some time now.]],logDesc=[[Bring the Empty Firewater Flask to Donova Snowden in Winterspring.]]}
DB[5084]={id=5084,zoneId=618,name=[[Falling to Corruption]],name_loc=[[Sucumbir a la corrupción]],level=56,minLevel=52,giver=[[Donova Snowden]],giver_loc=[[Donova Cubilnevado]],giverType=[[NPC]],giverId=9298,ender=[[Deadwood Cauldron]],ender_loc=[[Caldera de Muertobosque]],enderType=[[GO]],enderId=176091,prevId=5083,rewardNextId=5085,poiX=6909,poiY=-1820,wowhead=[[https://www.wowhead.com/wotlk/quest=5084]],image=[[assets/images/quests/placeholder.png]],desc=[[This greenish liquid... it reminds me a bit of the sludge I saw when traveling through Felwood. And I have seen some Winterfall Runners passing into Timbermaw... Perhaps these things have something to do with the flask you found, $N. There is a large group of furbolg just past Timbermaw Hold, in Felwood. Called the Deadwood tribe, they have been corrupted and driven mad by the fel. Why don't you look around there and see if you can find any evidence of dealings between the Winterfall and the Deadwood?]],logDesc=[[Search the Deadwood furbolg camp in northern Felwood for a clue.]]}
DB[5085]={id=5085,zoneId=618,name=[[Mystery Goo]],name_loc=[[Baba misteriosa]],level=56,minLevel=52,giver=[[Deadwood Cauldron]],giver_loc=[[Caldera de Muertobosque]],giverType=[[GO]],giverId=176091,ender=[[Donova Snowden]],ender_loc=[[Donova Cubilnevado]],enderType=[[NPC]],enderId=9298,prevId=5084,rewardNextId=5086,poiX=6396,poiY=-2537,wowhead=[[https://www.wowhead.com/wotlk/quest=5085]],image=[[assets/images/quests/placeholder.png]],desc=[[The greenish substance inside the cauldron appears to be similar to what you found in the flask. This strange gooey stuff could be as corrupted as the furbolg that created it... If the Winterfall furbolg are using it, does this mean that they will soon be as corrupted as the Deadwood tribe? It would be best to report back to Donova with your findings, along with a sample of the liquid in the cauldron.]],logDesc=[[Report back to Donova Snowden with your findings.]]}
DB[5086]={id=5086,zoneId=618,name=[[Toxic Horrors]],name_loc=[[Horrores tóxicos]],level=56,minLevel=52,giver=[[Donova Snowden]],giver_loc=[[Donova Cubilnevado]],giverType=[[NPC]],giverId=9298,ender=[[Donova Snowden]],ender_loc=[[Donova Cubilnevado]],enderType=[[NPC]],enderId=9298,prevId=5085,rewardNextId=5087,poiX=6396,poiY=-2537,wowhead=[[https://www.wowhead.com/wotlk/quest=5086]],image=[[assets/images/quests/placeholder.png]],desc=[[I've studied the sample you returned with, and while I can't say for sure, I believe it contains traces of toxic elements. However, the only way to know for sure is to gather some as a comparison. I believe that the Deadwood furbolg may be gathering these elements from other corrupted creatures in Felwood; in particular, the elementals living in the Irontree Woods, called toxic horrors. Collect a few samples for me to compare, but be careful -- it's very dangerous there!]],logDesc=[[Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring.]]}
DB[5087]={id=5087,zoneId=618,name=[[Winterfall Runners]],name_loc=[[Corredores Nevada]],level=57,minLevel=52,giver=[[Donova Snowden]],giver_loc=[[Donova Cubilnevado]],giverType=[[NPC]],giverId=9298,ender=[[Donova Snowden]],ender_loc=[[Donova Cubilnevado]],enderType=[[NPC]],enderId=9298,prevId=5086,rewardNextId=5121,poiX=6396,poiY=-2537,wowhead=[[https://www.wowhead.com/wotlk/quest=5087]],image=[[assets/images/quests/placeholder.png]],desc=[[Very interesting, $N... When this toxic substance is mixed with the water from the hot springs, it loses its toxicity, only retaining the ability to temporarily affect those that ingest it. This must be why the Winterfall protect the hot springs so fervently -- they need them to purify their firewater. We need to stop this -- cut off contact between the Winterfall and the Deadwood. A group of runners walks the distance between their village and Felwood. Find and defeat them, and steal their shipment.]],logDesc=[[Find the Winterfall Runners and stop them from delivering their shipment to Winterfall Village.]]}
DB[5088]={id=5088,zoneId=400,name=[[Arikara]],name_loc=[[Arikara]],level=28,minLevel=24,giver=[[Magatha Grimtotem]],giver_loc=[[Magatha Tótem Siniestro]],giverType=[[NPC]],giverId=4046,ender=[[Motega Firemane]],ender_loc=[[Motega Pirocabello]],enderType=[[NPC]],enderId=10428,prevId=5062,poiX=-5008,poiY=-2115,wowhead=[[https://www.wowhead.com/wotlk/quest=5088]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this refined and purified Incendia powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead. The enchantment that I have weaved into the Incendia powder will summon Arikara to you, $N. I fear she may be stalking Cairne Bloodhoof; too much Tauren lore has changed, and I fear this has angered Arikara. Move quickly before all is lost, $c!]],logDesc=[[Slay Arikara. Bring her remains and the Incendia powder to Motega Firemane in Whitereach Post as proof of your deed.]],choiceRewards={{id=15464,qty=1},{id=15465,qty=1},{id=15466,qty=1}}}
DB[5089]={id=5089,zoneId=1583,name=[[General Drakkisath's Command]],name_loc=[[Orden del general Drakkisath]],level=60,minLevel=55,giverType=[[NPC]],ender=[[Marshal Maxwell]],ender_loc=[[Mariscal Maxwell]],enderType=[[NPC]],enderId=9560,rewardNextId=5102,poiX=-8379,poiY=-2749,wowhead=[[https://www.wowhead.com/wotlk/quest=5089]],image=[[assets/images/quests/placeholder.png]],desc=[[From the corpse of the defeated serpent you uncover what appears to be a note of some importance: A letter from his superior, General Drakkisath, concerning protocol. Your instinct tells you that you should take it to Marshal Maxwell.]],logDesc=[[Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes.]]}
DB[5090]={id=5090,zoneId=1537,name=[[A Call to Arms: The Plaguelands!]],name_loc=[[Un llamamiento a las armas: las Tierras de la Peste]],level=50,minLevel=50,giver=[[Courier Hammerfall]],giver_loc=[[Mensajero Sentencia]],giverType=[[NPC]],giverId=10877,ender=[[Commander Ashlam Valorfist]],ender_loc=[[Comandante Ashlam Puñovalor]],enderType=[[NPC]],enderId=10838,rewardNextId=5092,poiX=958,poiY=-1419,wowhead=[[https://www.wowhead.com/wotlk/quest=5090]],image=[[assets/images/quests/placeholder.png]],desc=[[Hear ye, hear ye!  All heroes are called upon to heed these words! A call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands! Heroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!]],logDesc=[[Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains.]]}
DB[5091]={id=5091,zoneId=1657,name=[[A Call to Arms: The Plaguelands!]],name_loc=[[Un llamamiento a las armas: las Tierras de la Peste]],level=50,minLevel=50,giver=[[Herald Moonstalker]],giver_loc=[[Heraldo Acechalunas]],giverType=[[NPC]],giverId=10878,ender=[[Commander Ashlam Valorfist]],ender_loc=[[Comandante Ashlam Puñovalor]],enderType=[[NPC]],enderId=10838,rewardNextId=5092,poiX=958,poiY=-1419,wowhead=[[https://www.wowhead.com/wotlk/quest=5091]],image=[[assets/images/quests/placeholder.png]],desc=[[Hear ye, hear ye!  All heroes are called upon to heed these words! A call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands! Heroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!]],logDesc=[[Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains.]]}
DB[5092]={id=5092,zoneId=28,name=[[Clear the Way]],name_loc=[[Despejar el camino]],level=52,minLevel=50,giver=[[Commander Ashlam Valorfist]],giver_loc=[[Comandante Ashlam Puñovalor]],giverType=[[NPC]],giverId=10838,ender=[[Commander Ashlam Valorfist]],ender_loc=[[Comandante Ashlam Puñovalor]],enderType=[[NPC]],enderId=10838,poiX=1178,poiY=-1785,wowhead=[[https://www.wowhead.com/wotlk/quest=5092]],image=[[assets/images/quests/placeholder.png]],desc=[[With Andorhal's western and northern roads into the city well fortified, I'm looking to strike at it from the less defended eastern road.  The Scourge relies on the buffer of undead that infests Sorrow Hill as a first line of defense.  If we are to advance on Andorhal, we will need to do it through Sorrow Hill. Your first assignment will be to clear the way through Sorrow Hill.  Thin out the skeletons and ghouls that haunt the area; report back to me when this is done!]],logDesc=[[Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill. Return to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.]]}
DB[5093]={id=5093,zoneId=28,name=[[A Call to Arms: The Plaguelands!]],name_loc=[[Un llamamiento a las armas: las Tierras de la Peste]],level=50,minLevel=50,giver=[[Warcaller Gorlach]],giver_loc=[[Clamaguerras Gorlach]],giverType=[[NPC]],giverId=10880,ender=[[High Executor Derrington]],ender_loc=[[Sumo ejecutor Derrington]],enderType=[[NPC]],enderId=10837,rewardNextId=5096,poiX=1761,poiY=-723,wowhead=[[https://www.wowhead.com/wotlk/quest=5093]],image=[[assets/images/quests/placeholder.png]],desc=[[Heroes of the realm, hear me - the Horde calls upon you for swift action! A call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands! Heroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glade!]],logDesc=[[Seek out High Executor Derrington.  His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity.]]}
DB[5094]={id=5094,zoneId=28,name=[[A Call to Arms: The Plaguelands!]],name_loc=[[Un llamamiento a las armas: las Tierras de la Peste]],level=50,minLevel=50,giver=[[Harbinger Balthazad]],giver_loc=[[Presagista Balthazad]],giverType=[[NPC]],giverId=10879,ender=[[High Executor Derrington]],ender_loc=[[Sumo ejecutor Derrington]],enderType=[[NPC]],enderId=10837,rewardNextId=5096,poiX=1761,poiY=-723,wowhead=[[https://www.wowhead.com/wotlk/quest=5094]],image=[[assets/images/quests/placeholder.png]],desc=[[Heroes of the realm, hear me - the Horde calls upon you for swift action! A call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands! Heroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glade!]],logDesc=[[Seek out High Executor Derrington.  His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity.]]}
DB[5095]={id=5095,zoneId=28,name=[[A Call to Arms: The Plaguelands!]],name_loc=[[Un llamamiento a las armas: las Tierras de la Peste]],level=50,minLevel=50,giver=[[Bluff Runner Windstrider]],giver_loc=[[Asaltaviento Correbrisa]],giverType=[[NPC]],giverId=10881,ender=[[High Executor Derrington]],ender_loc=[[Sumo ejecutor Derrington]],enderType=[[NPC]],enderId=10837,rewardNextId=5096,poiX=1761,poiY=-723,wowhead=[[https://www.wowhead.com/wotlk/quest=5095]],image=[[assets/images/quests/placeholder.png]],desc=[[Heroes of the realm, hear me - the Horde calls upon you for swift action! A call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands! Heroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glades!]],logDesc=[[Seek out High Executor Derrington.  His base camp is located at the Bulwark, east of Tirisfal Glades and the Undercity.]]}
DB[5096]={id=5096,zoneId=28,name=[[Scarlet Diversions]],name_loc=[[Distracción Escarlata]],level=53,minLevel=50,giver=[[High Executor Derrington]],giver_loc=[[Sumo ejecutor Derrington]],giverType=[[NPC]],giverId=10837,ender=[[High Executor Derrington]],ender_loc=[[Sumo ejecutor Derrington]],enderType=[[NPC]],enderId=10837,poiX=1761,poiY=-723,wowhead=[[https://www.wowhead.com/wotlk/quest=5096]],image=[[assets/images/quests/placeholder.png]],desc=[[Before Andorhal, we must tackle the advancing Scarlet Crusade menace from Hearthglen.  They've made camp between Felstone Field and Dalson's Tears, making us risk conflict against both the Scourge and the Crusade at once. My plan is to play them off of each other by sending you to destroy the command tent they've set up; use some Flame in a Bottle from this box of incendiaries.  Once razed, plant this Scourge banner by the tent.  With some luck, they'll ignore us and focus on the Scourge for vengeance.]],logDesc=[[Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent. Place the Scourge banner at the camp, and then return to High Executor Derrington at the Bulwark, Western Plaguelands.]]}
DB[5097]={id=5097,zoneId=28,name=[[All Along the Watchtowers]],name_loc=[[Todas las atalayas]],level=56,minLevel=50,giver=[[Commander Ashlam Valorfist]],giver_loc=[[Comandante Ashlam Puñovalor]],giverType=[[NPC]],giverId=10838,ender=[[Commander Ashlam Valorfist]],ender_loc=[[Comandante Ashlam Puñovalor]],enderType=[[NPC]],enderId=10838,prevId=5092,poiX=1314,poiY=-1305,wowhead=[[https://www.wowhead.com/wotlk/quest=5097]],image=[[assets/images/quests/placeholder.png]],desc=[[Through the use of a magical device known as a beacon torch, we can mark targets of our choosing for future actions by our troops.  To that end, we think the Scourge are using Andorhal's watchtowers as a means to control their troop movements. Your mission: breach Andorhal's defenses to plant beacons at all four watchtowers.  You'll need to be in the doorway of each tower to plant the beacon; it will then proceed to mark the tower.  There are only five charges on the beacon torch, so use them wisely!]],logDesc=[[Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it. Once all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands.]]}
DB[5098]={id=5098,zoneId=28,name=[[All Along the Watchtowers]],name_loc=[[Todas las atalayas]],level=56,minLevel=50,giver=[[High Executor Derrington]],giver_loc=[[Sumo ejecutor Derrington]],giverType=[[NPC]],giverId=10837,ender=[[High Executor Derrington]],ender_loc=[[Sumo ejecutor Derrington]],enderType=[[NPC]],enderId=10837,prevId=5096,poiX=1314,poiY=-1305,wowhead=[[https://www.wowhead.com/wotlk/quest=5098]],image=[[assets/images/quests/placeholder.png]],desc=[[Through the use of a magical device known as a beacon torch, we can mark targets of our choosing for future actions by our troops.  To that end, we think the Scourge are using Andorhal's watchtowers as a means to control their troop movements. Your mission: breach Andorhal's defenses to plant beacons at all four watchtowers.  You'll need to be in the doorway of each tower to plant the beacon; it will then proceed to mark the tower.  There are only five charges on the beacon torch, so use them wisely!]],logDesc=[[Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it. Once all four towers are marked, return the Beacon Torch to High Executor Derrington at the Bulwark, Western Plaguelands.]]}
DB[5102]={id=5102,zoneId=1583,name=[[General Drakkisath's Demise]],name_loc=[[Muerte al general Drakkisath]],level=60,minLevel=55,giver=[[Marshal Maxwell]],giver_loc=[[Mariscal Maxwell]],giverType=[[NPC]],giverId=9560,ender=[[Marshal Maxwell]],ender_loc=[[Mariscal Maxwell]],enderType=[[NPC]],enderId=9560,prevId=5089,poiX=-8379,poiY=-2749,wowhead=[[https://www.wowhead.com/wotlk/quest=5102]],image=[[assets/images/quests/placeholder.png]],desc=[[We battle against these beasts on two fronts: From our capital of Stormwind we fight them from the inside out and here, in the Burning Steppes, we take the battle to their doorstep. We must be vigilant, $N. None should be spared our wrath as none of our own were spared when they struck at our homes and families. Find this General Drakkisath and destroy him! The task certainly will not be a simple one, but the rewards shall be extravagant.]],logDesc=[[Travel to Blackrock Spire and slay General Drakkisath.]],choiceRewards={{id=13966,qty=1},{id=13968,qty=1},{id=13965,qty=1}}}
DB[5103]={id=5103,name=[[Hot Fiery Death]],name_loc=[[Muerte abrasadora]],level=60,minLevel=55,giver=[[Human Remains]],giver_loc=[[Restos humanos]],giverType=[[GO]],giverId=176090,ender=[[Malyfous Darkhammer]],ender_loc=[[Malyfous Martilloscuro]],enderType=[[NPC]],enderId=10637,rewardNextId=5124,poiX=6698,poiY=-4647,wowhead=[[https://www.wowhead.com/wotlk/quest=5103]],image=[[assets/images/quests/placeholder.png]],desc=[[The only thing that remains of this human are some charred bones. He seems to have died within arms reach of what he was after - unfired plate gauntlets. Perhaps you should grab the gauntlets and get out of the fire?]],logDesc=[[Someone in this world must know what to do with these gauntlets. Good luck!]]}
DB[5121]={id=5121,zoneId=618,name=[[High Chief Winterfall]],name_loc=[[Gran Jefe Nevada]],level=59,minLevel=52,giver=[[Donova Snowden]],giver_loc=[[Donova Cubilnevado]],giverType=[[NPC]],giverId=9298,ender=[[Donova Snowden]],ender_loc=[[Donova Cubilnevado]],enderType=[[NPC]],enderId=9298,prevId=5087,poiX=6725,poiY=-5278,wowhead=[[https://www.wowhead.com/wotlk/quest=5121]],image=[[assets/images/quests/placeholder.png]],desc=[[While we still know very little about why the furbolg have been ingesting this strange substance, I do think it's best that we put a stop to it before it gets out of hand. The Winterfall furbolg are not a normally aggressive tribe, and this change in their behavior leads me to think that they must be under orders from their chief. We most likely can't undo the damage that has already been done, but I think that if their leader is slain, they will not get any worse. Head east to Winterfall Village.]],logDesc=[[Donova Snowden in Winterspring wants you to defeat High Chief Winterfall.]],choiceRewards={{id=15784,qty=1},{id=15786,qty=1},{id=15787,qty=1}}}
DB[5122]={id=5122,zoneId=2017,name=[[The Medallion of Faith]],name_loc=[[El medallón de Fe]],level=60,minLevel=55,giver=[[Aurius]],giverType=[[NPC]],giverId=10917,ender=[[Aurius]],enderType=[[NPC]],enderId=10917,wowhead=[[https://www.wowhead.com/wotlk/quest=5122]],image=[[assets/images/quests/placeholder.png]]}
DB[5123]={id=5123,zoneId=618,name=[[The Final Piece]],name_loc=[[La pieza final]],level=59,minLevel=52,giverType=[[NPC]],ender=[[Donova Snowden]],ender_loc=[[Donova Cubilnevado]],enderType=[[NPC]],enderId=9298,prevId=5087,poiX=6725,poiY=-5278,wowhead=[[https://www.wowhead.com/wotlk/quest=5123]],image=[[assets/images/quests/placeholder.png]],desc=[[The log you found on the high chief looks extensive, but after looking through a couple of the pages, you find that you cannot read the text. The markings are so crude and poorly-formed that you are not sure if anyone would be able to read them. But perhaps Donova will be able to tell you what it says...]],logDesc=[[Bring the Crudely-written Log to Donova Snowden in Winterspring.]]}
DB[5124]={id=5124,zoneId=618,name=[[Fiery Plate Gauntlets]],name_loc=[[Guanteletes de placas ígneas]],level=60,minLevel=55,giver=[[Malyfous Darkhammer]],giver_loc=[[Malyfous Martilloscuro]],giverType=[[NPC]],giverId=10637,ender=[[Malyfous Darkhammer]],ender_loc=[[Malyfous Martilloscuro]],enderType=[[NPC]],enderId=10637,prevId=5103,poiX=6698,poiY=-4647,wowhead=[[https://www.wowhead.com/wotlk/quest=5124]],image=[[assets/images/quests/placeholder.png]],desc=[[By Thaurissan's beard! Where did you find them? More importantly, are you willing to part with them? Naturally, I would pay you for such a noble gesture. I'll tell you what, $N. If you give me those unfired gauntlets, I will teach you how to make a set all your own. All you need to do is collect the parts for me so that I may narrow down the exact recipe. Do we have a deal?? Here's the list of what I need, I'll front the non-enchanted thorium myself since you're supplying the gauntlets. ]],logDesc=[[Bring Malyfous Darkhammer 6 Enchanted Thorium Bars, 2 Essence of Fire, and 4 Star Rubies. You will also need to turn in your Unfired Plate Gauntlets.]],rewards={{id=12699,qty=1},{id=12631,qty=1}}}
DB[5125]={id=5125,zoneId=2017,name=[[Aurius' Reckoning]],name_loc=[[La estimación de Aurius]],level=60,minLevel=55,giver=[[Aurius]],giverType=[[NPC]],giverId=10917,ender=[[Aurius]],enderType=[[NPC]],enderId=10917,prevId=5122,wowhead=[[https://www.wowhead.com/wotlk/quest=5125]],image=[[assets/images/quests/placeholder.png]],choiceRewards={{id=17044,qty=1},{id=17045,qty=1}}}
DB[5126]={id=5126,zoneId=618,name=[[Lorax's Tale]],name_loc=[[La historia de Lorax]],level=60,minLevel=55,giver=[[Lorax]],giverType=[[NPC]],giverId=10918,ender=[[Lorax]],enderType=[[NPC]],enderId=10918,poiX=5041,poiY=-4848,wowhead=[[https://www.wowhead.com/wotlk/quest=5126]],image=[[assets/images/quests/placeholder.png]],desc=[[The Satyr paces about and talks to himself. Do you wish to question him?]],logDesc=[[Speak with Lorax. Listen to what he has to say. ]]}
DB[5127]={id=5127,zoneId=1583,name=[[The Demon Forge]],name_loc=[[La forja demoníaca]],level=60,minLevel=55,giver=[[Lorax]],giverType=[[NPC]],giverId=10918,ender=[[Lorax]],enderType=[[NPC]],enderId=10918,prevId=5126,poiX=5041,poiY=-4848,wowhead=[[https://www.wowhead.com/wotlk/quest=5127]],image=[[assets/images/quests/placeholder.png]],desc=[[Lorax makes deals, he does not accept them from insignificant mortals. A deal I shall make with you, however... take this pike, it is imbued with powerful Fel energies. When you find Goraluk Anvilcrack, slay him and drive this pike through his dying heart. His soul he bartered, his soul I shall have. Return the pike and return the breastplate that the thief stole and I shall teach you what it is that he was to learn.]],logDesc=[[Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained. You must also find the Unforged Rune Covered Breastplate. Return both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.]],rewards={{id=12696,qty=1},{id=9224,qty=5},{id=12849,qty=1}}}
DB[5128]={id=5128,zoneId=618,name=[[Words of the High Chief]],name_loc=[[Las palabras del Gran Jefe]],level=59,minLevel=52,giver=[[Donova Snowden]],giver_loc=[[Donova Cubilnevado]],giverType=[[NPC]],giverId=9298,ender=[[Kelek Skykeeper]],ender_loc=[[Kelek Guardacielo]],enderType=[[NPC]],enderId=10920,prevId=5123,poiX=3999,poiY=-1299,wowhead=[[https://www.wowhead.com/wotlk/quest=5128]],image=[[assets/images/quests/placeholder.png]],desc=[[The Winterfall are no longer a threat to me, but if you still want to find out what was driving the furbolg to create and consume this strange firewater, I think you should seek out Kelek Skykeeper. He is part of a group known as the Emerald Circle, druids that are committed to their work in Felwood, healing the land from the corruption. Kelek has much experience with the furbolgs in Felwood, and may be able to tell you more about the log. Thank you, again, $N.]],logDesc=[[Take the Crudely-written Log to Kelek Skykeeper in southern Felwood.]],choiceRewards={{id=34423,qty=1},{id=34424,qty=1}}}
DB[5141]={id=5141,name=[[Dragonscale Leatherworking]],name_loc=[[Peletería dragontina]],level=55,minLevel=40,giver=[[Peter Galen]],giverType=[[NPC]],giverId=7866,ender=[[Peter Galen]],enderType=[[NPC]],enderId=7866,exGroup=5141,poiX=3130,poiY=-5183,wowhead=[[https://www.wowhead.com/wotlk/quest=5141]],image=[[assets/images/quests/placeholder.png]],desc=[[Dragonscale leatherworking isn't easy, but it's extremely rewarding.  I'll teach you how to make this fine mail armor, but only if you agree to certain conditions. By choosing this path, you agree never to learn elemental or tribal leatherworking; there is only room for one of the three at the apex of the craft.  Furthermore, I'll need some samples of your best work involving scorpid armor.  Finally, I'll need proof of your ability to acquire the staple of the trade: scales of the dragonkin.]],logDesc=[[Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Peter Galen in Azshara. Completing this quest will give you access to the Dragonscale Leatherworking arts. The completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.]]}
DB[5142]={id=5142,zoneId=139,name=[[Little Pamela]],name_loc=[[La pequeña Pamela]],level=55,minLevel=50,giver=[[Marlene Redpath]],giver_loc=[[Marlene Rutagrana]],giverType=[[NPC]],giverId=10927,ender=[[Pamela Redpath]],ender_loc=[[Pamela Rutagrana]],enderType=[[NPC]],enderId=10926,rewardNextId=5149,exGroup=5142,poiX=1456,poiY=-3596,wowhead=[[https://www.wowhead.com/wotlk/quest=5142]],image=[[assets/images/quests/placeholder.png]],desc=[[So many of us died at the battle of Darrowshire.  So many died... and worse. When the battle began I hid my niece Pamela, and I do not know what happened to her.  I am but a wandering spirit, but my heart still longs to know Pamela's fate. Please, good $c.  Will you go to Darrowshire and search for her?  It is to the east, beyond Gahrron's Withering.]],logDesc=[[Find Pamela Redpath in Darrowshire.]]}
DB[5143]={id=5143,name=[[Tribal Leatherworking]],name_loc=[[Peletería tribal]],level=55,minLevel=40,giver=[[Caryssia Moonhunter]],giver_loc=[[Caryssia Cazaluna]],giverType=[[NPC]],giverId=7870,ender=[[Caryssia Moonhunter]],ender_loc=[[Caryssia Cazaluna]],enderType=[[NPC]],enderId=7870,exGroup=5141,poiX=-4524,poiY=-773,wowhead=[[https://www.wowhead.com/wotlk/quest=5143]],image=[[assets/images/quests/placeholder.png]],desc=[[To learn tribal leatherworking demands an understanding of how primal nature truly is; I know that you have already mastered the art of making wild leather armor, and I am willing to complete your training. Know this, $c: by choosing this path you agree never to learn dragonscale or elemental leatherworking; there is only room for practice of one of the three arts.  Furthermore, bring to me the finest samples of your wild leather armor.  From there, we will begin your mastery.]],logDesc=[[Bring a Wild Leather Vest and a Wild Leather Helmet to Caryssia Moonhunter in Feralas. Completing this quest will give you access to the Tribal Leatherworking arts. The completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so.]]}
DB[5144]={id=5144,name=[[Elemental Leatherworking]],name_loc=[[Peletería elemental]],level=55,minLevel=40,giver=[[Sarah Tanner]],giver_loc=[[Sarah Peletero]],giverType=[[NPC]],giverId=7868,ender=[[Sarah Tanner]],ender_loc=[[Sarah Peletero]],enderType=[[NPC]],enderId=7868,exGroup=5141,poiX=-7230,poiY=-1741,wowhead=[[https://www.wowhead.com/wotlk/quest=5144]],image=[[assets/images/quests/placeholder.png]],desc=[[Elemental leatherworking is what I know, and if you're willing to open your mind to the greater powers of substance, I will share with you all there is to learn. Know this, $c: by choosing this path you agree never to learn dragonscale or tribal leatherworking; there is only room for practice of one of the three arts.  Furthermore, I'll need adequate proof that you are in tune with the elements of nature; to that end, bring me the purest essences of fire, water, earth, and wind.]],logDesc=[[Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Sarah Tanner in Searing Gorge. Completing this quest will give you access to the Elemental Leatherworking arts. The completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.]]}
DB[5145]={id=5145,name=[[Dragonscale Leatherworking]],name_loc=[[Peletería dragontina]],level=55,minLevel=40,giver=[[Thorkaf Dragoneye]],giver_loc=[[Thorkaf Ojo de Dragón]],giverType=[[NPC]],giverId=7867,ender=[[Thorkaf Dragoneye]],ender_loc=[[Thorkaf Ojo de Dragón]],enderType=[[NPC]],enderId=7867,exGroup=5145,poiX=-6842,poiY=-3639,wowhead=[[https://www.wowhead.com/wotlk/quest=5145]],image=[[assets/images/quests/placeholder.png]],desc=[[Dragonscale leatherworking isn't easy, but it's extremely rewarding.  I'll teach you how to make this fine mail armor, but only if you agree to certain conditions. By choosing this path, you agree never to learn elemental or tribal leatherworking; there is only room for one of the three at the apex of the craft.  Furthermore, I'll need some samples of your best work involving scorpid armor.  Finally, I'll need proof of your ability to acquire the staple of the trade: scales of the dragonkin.]],logDesc=[[Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Thorkaf Dragoneye in the Badlands. Completing this quest will give you access to the Dragonscale Leatherworking arts. The completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.]]}
DB[5146]={id=5146,name=[[Elemental Leatherworking]],name_loc=[[Peletería elemental]],level=55,minLevel=40,giver=[[Brumn Winterhoof]],giver_loc=[[Brumm Pezuña Invernal]],giverType=[[NPC]],giverId=7869,ender=[[Brumn Winterhoof]],ender_loc=[[Brumm Pezuña Invernal]],enderType=[[NPC]],enderId=7869,exGroup=5145,poiX=-1215,poiY=-1884,wowhead=[[https://www.wowhead.com/wotlk/quest=5146]],image=[[assets/images/quests/placeholder.png]],desc=[[Elemental leatherworking is what I know, and if you're willing to open your mind to the greater powers of substance, I will share with you all there is to learn. Know this, $c: by choosing this path you agree never to learn dragonscale or tribal leatherworking; there is only room for practice of one of the three arts.  Furthermore, I'll need adequate proof that you are in tune with the elements of nature; to that end, bring me the purest essences of fire, water, earth, and wind.]],logDesc=[[Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Brumn Winterhoof in the Arathi Mountains. Completing this quest will give you access to the Elemental Leatherworking arts. The completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.]]}
DB[5147]={id=5147,zoneId=400,name=[[Wanted - Arnak Grimtotem]],name_loc=[[Se busca: Arnak Tótem Siniestro]],level=29,minLevel=20,giver=[[Wanted Poster - Arnak Grimtotem]],giver_loc=[[Cartel de Se busca: Arnak Tótem Siniestro]],giverType=[[GO]],giverId=176115,ender=[[Cliffwatcher Longhorn]],ender_loc=[[Vigiarrisco Cuerno Largo]],enderType=[[NPC]],enderId=10537,poiX=-4754,poiY=-2109,wowhead=[[https://www.wowhead.com/wotlk/quest=5147]],image=[[assets/images/quests/placeholder.png]],desc=[[Wanted: Arnak Grimtotem Arnak the outcast is wanted for the heinous crimes of murder and kidnapping. Handsome rewards will be given to those brave enough to bring this criminal to justice. Arnak was last seen on the cliffs near the Darkcloud Pinnacle. Show the proof of your deed to Cliffwatcher Longhorn in Freewind Post in order to claim the reward.]],logDesc=[[Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post.]],choiceRewards={{id=15471,qty=1},{id=15470,qty=1}}}
DB[5148]={id=5148,name=[[Tribal Leatherworking]],name_loc=[[Peletería tribal]],level=55,minLevel=40,giver=[[Se'Jib]],giverType=[[NPC]],giverId=7871,ender=[[Se'Jib]],enderType=[[NPC]],enderId=7871,exGroup=5145,poiX=-12619,poiY=-111,wowhead=[[https://www.wowhead.com/wotlk/quest=5148]],image=[[assets/images/quests/placeholder.png]],desc=[[To learn tribal leatherworking demands an understanding of how primal nature truly is; I know that you have already mastered the art of making wild leather armor, and I am willing to complete your training. Know this, $c: by choosing this path you agree never to learn dragonscale or elemental leatherworking; there is only room for practice of one of the three arts.  Furthermore, bring to me the finest samples of your wild leather armor.  From there, we will begin your mastery.]],logDesc=[[Bring a Wild Leather Vest and a Wild Leather Helmet to Se'Jib in Stranglethorn Vale. Completing this quest will give you access to the Tribal Leatherworking arts. The completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so.]]}
DB[5149]={id=5149,zoneId=139,name=[[Pamela's Doll]],name_loc=[[La muñeca de Pamela]],level=55,minLevel=50,giver=[[Pamela Redpath]],giver_loc=[[Pamela Rutagrana]],giverType=[[NPC]],giverId=10926,ender=[[Pamela Redpath]],ender_loc=[[Pamela Rutagrana]],enderType=[[NPC]],enderId=10926,poiX=1456,poiY=-3596,wowhead=[[https://www.wowhead.com/wotlk/quest=5149]],image=[[assets/images/quests/placeholder.png]],desc=[[My auntie Marlene told me to stay here in our house because my father had to go and fight.  My father's the bravest man in the whole world! But I've been here for a long time, and he hasn't come for me.  Sometimes bad people come and whisper to me and I want my dad to make them go away, but he's not here! And sometimes when it gets dark I want to play with my doll but I can't because I left it in town. Will you find my doll for me?]],logDesc=[[Find Pamela's doll.]]}
DB[5150]={id=5150,zoneId=490,name=[[Dadanga is Hungry!]],name_loc=[[¡Dadanga tiene hambre!]],level=55,minLevel=47,giver=[[Dadanga]],giverType=[[NPC]],giverId=9274,ender=[[Dadanga]],enderType=[[NPC]],enderId=9274,poiX=-6143,poiY=-1081,wowhead=[[https://www.wowhead.com/wotlk/quest=5150]],image=[[assets/images/quests/placeholder.png]],rewards={{id=15699,qty=1}}}
DB[5151]={id=5151,zoneId=400,name=[[Hypercapacitor Gizmo]],name_loc=[[Hipercondensador]],level=30,minLevel=24,giver=[[Wizlo Bearingshiner]],giver_loc=[[Wizlo Rodabrillante]],giverType=[[NPC]],giverId=10941,ender=[[Wizlo Bearingshiner]],ender_loc=[[Wizlo Rodabrillante]],enderType=[[NPC]],enderId=10941,poiX=-4689,poiY=-1435,wowhead=[[https://www.wowhead.com/wotlk/quest=5151]],image=[[assets/images/quests/placeholder.png]],desc=[[I am the only survivor from our caravan attack by the centaur! A rare yet mighty panther is guarding my best gizmo, which is around his neck. Hah! Even the centaur tremble in the presence of this ferocious beast! Here is the key to the cage. They took everything there, but left him alone. Slay this beast and bring back my hypercapacitor, and I shall reward you. The wrecked caravan is just north of here. ]],logDesc=[[Slay the beast and bring back the Hypercapacitor Gizmo and Panther Cage Key to Wizlo Bearingshiner.]],rewards={{id=15467,qty=1}}}
DB[5152]={id=5152,zoneId=139,name=[[Auntie Marlene]],name_loc=[[Tía Marlene]],level=56,minLevel=50,giver=[[Pamela Redpath]],giver_loc=[[Pamela Rutagrana]],giverType=[[NPC]],giverId=10926,ender=[[Marlene Redpath]],ender_loc=[[Marlene Rutagrana]],enderType=[[NPC]],enderId=10927,prevId=5149,rewardNextId=5153,poiX=1119,poiY=-1685,wowhead=[[https://www.wowhead.com/wotlk/quest=5152]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, I'm so lonely!  Where is my family?  Auntie Marlene told me to stay here, but then she left and never came back!  And my dad... have you seen him? Maybe Auntie Marlene knows where he is.  She lives near Andorhal, in a house to the south.  I think it was on a hill... she said it was on a hill. Please, $N.  You're my new friend!  Will you talk to my Auntie for me?]],logDesc=[[Speak with Marlene, south of the Ruins of Andorhal.]]}
DB[5153]={id=5153,zoneId=139,name=[[A Strange Historian]],name_loc=[[Una extraña historiadora]],level=56,minLevel=50,giver=[[Marlene Redpath]],giver_loc=[[Marlene Rutagrana]],giverType=[[NPC]],giverId=10927,ender=[[Chromie]],ender_loc=[[Cromi]],enderType=[[NPC]],enderId=10667,prevId=5152,rewardNextId=5154,poiX=1166,poiY=-1720,wowhead=[[https://www.wowhead.com/wotlk/quest=5153]],image=[[assets/images/quests/placeholder.png]],desc=[[I wish Joseph could again be with his daughter, but it cannot be so.  His soul was twisted by the Scourge, and he became a monster.  Oh, he is doomed! But perhaps we can change his fate. Search the graves outside for Joseph's monument.  His body's not there, for it was trampled and destroyed years ago, but under the monument is his wedding ring.  Take that ring to Chromie... a strange gnome with very strange powers. Chromie is staying in the ruined inn at the northwest corner of Andorhal.]],logDesc=[[Bring Joseph's Wedding Ring to Chromie.]]}
DB[5154]={id=5154,zoneId=28,name=[[The Annals of Darrowshire]],name_loc=[[Las Crónicas de Villa Darrow]],level=56,minLevel=50,giver=[[Chromie]],giver_loc=[[Cromi]],giverType=[[NPC]],giverId=10667,ender=[[Chromie]],ender_loc=[[Cromi]],enderType=[[NPC]],enderId=10667,prevId=5153,nextId=5210,poiX=1361,poiY=-1458,wowhead=[[https://www.wowhead.com/wotlk/quest=5154]],image=[[assets/images/quests/placeholder.png]],desc=[[To save Joseph Redpath, we must first discover his past.  We can learn this in the Annals of Darrowshire, a book held in the city hall of Andorhal. Bring me that book.  We can then learn Joseph's fate, and with luck... change it!]],logDesc=[[Bring the Annals of Darrowshire to Chromie in Andorhal.]]}
DB[5155]={id=5155,zoneId=361,name=[[Forces of Jaedenar]],name_loc=[[Las fuerzas de Jaedenar]],level=51,minLevel=48,giver=[[Greta Mosshoof]],giver_loc=[[Greta Pezuñamusgo]],giverType=[[NPC]],giverId=10922,ender=[[Greta Mosshoof]],ender_loc=[[Greta Pezuñamusgo]],enderType=[[NPC]],enderId=10922,rewardNextId=5157,poiX=4865,poiY=-605,wowhead=[[https://www.wowhead.com/wotlk/quest=5155]],image=[[assets/images/quests/placeholder.png]],desc=[[If I am to trust you in this matter, you will first have to prove yourself. I must know that you are an enemy of the Shadow Council--the ones responsible for many evils here and abroad. Travel deeper into Felwood. To the west you will see a path leading to Jaedenar. It is there that the Council plots with the Burning Legion. Enter the depths of one of the corrupted Barrow Dens they inhabit and slay their kind. Return to me after you've done this. Then I will know you truly seek to help us.]],logDesc=[[Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood.]]}
DB[5156]={id=5156,zoneId=361,name=[[Verifying the Corruption]],name_loc=[[Investigación acerca de la corrupción]],level=54,minLevel=48,giver=[[Taronn Redfeather]],giver_loc=[[Taronn Plumarroja]],giverType=[[NPC]],giverId=10921,ender=[[Taronn Redfeather]],ender_loc=[[Taronn Plumarroja]],enderType=[[NPC]],enderId=10921,poiX=5616,poiY=-1016,wowhead=[[https://www.wowhead.com/wotlk/quest=5156]],image=[[assets/images/quests/placeholder.png]],desc=[[To the north, along the east of the road in what's called Shatter Scar Vale, is an area where infernals were called down during the last great war--the craters still scar the land, as do the infernals themselves. I am curious about two things. First, are there still entropic elementals roaming the area? And second, are the craters still filled with the corrupt, fetid water that gathered there years ago? Will you help me and check, $N? Be careful though, the infernals destroy anything in their path.]],logDesc=[[Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood.]]}
DB[5157]={id=5157,zoneId=361,name=[[Collection of the Corrupt Water]],name_loc=[[Una muestra de agua corrupta]],level=52,minLevel=48,giver=[[Greta Mosshoof]],giver_loc=[[Greta Pezuñamusgo]],giverType=[[NPC]],giverId=10922,ender=[[Greta Mosshoof]],ender_loc=[[Greta Pezuñamusgo]],enderType=[[NPC]],enderId=10922,prevId=5155,rewardNextId=5158,poiX=3984,poiY=-1304,wowhead=[[https://www.wowhead.com/wotlk/quest=5157]],image=[[assets/images/quests/placeholder.png]],desc=[[Deep within Jaedenar lies Shadow Hold--the main fortress of their corruption and evil. The Shadow Council has protective spells surrounding their lair in the form of braziers. If I am to find out any more information about our enemy through scrying, then those braziers must be extinguished. By doing so, I should be able to spy on the Council and find out who leads them. If you can, take this canteen and fill it at the Moon Well in the center of Jaedenar. Return to me afterwards.]],logDesc=[[Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood.]]}
DB[5158]={id=5158,zoneId=361,name=[[Seeking Spiritual Aid]],name_loc=[[Buscando ayuda espiritual]],level=52,minLevel=48,giver=[[Greta Mosshoof]],giver_loc=[[Greta Pezuñamusgo]],giverType=[[NPC]],giverId=10922,ender=[[Islen Waterseer]],ender_loc=[[Islen Vidente del Agua]],enderType=[[NPC]],enderId=5901,prevId=5157,poiX=-1345,poiY=-4048,wowhead=[[https://www.wowhead.com/wotlk/quest=5158]],image=[[assets/images/quests/placeholder.png]],desc=[[Take the corrupt water to the Barrens, $N. South of Ratchet, hidden along the shore, is an old friend of mine, a shaman named Islen Waterseer. She is a powerful shaman who will help us. Her relationship with the spirits of water has always been strong. Our task being a noble one should be enough to persuade her and the spirits of water to aid us in this task. You should find her at a small camp right along the water's edge. And, $N, ignore the pirates... they are but a nuisance and no threat to you.]],logDesc=[[Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens.]]}
DB[5159]={id=5159,zoneId=361,name=[[Cleansed Water Returns to Felwood]],name_loc=[[El agua purificada vuelve a Frondavil]],level=54,minLevel=48,giver=[[Islen Waterseer]],giver_loc=[[Islen Vidente del Agua]],giverType=[[NPC]],giverId=5901,ender=[[Greta Mosshoof]],ender_loc=[[Greta Pezuñamusgo]],enderType=[[NPC]],enderId=10922,prevId=5158,rewardNextId=5165,poiX=3984,poiY=-1304,wowhead=[[https://www.wowhead.com/wotlk/quest=5159]],image=[[assets/images/quests/placeholder.png]],desc=[[Thank the spirits, $N. They are the ones that have come to your aid, not me. I give this purified water to you now. Please give my regards to Greta and my best wishes. She is tackling something greater than many of us... as I'm sure she will soon find out. The Shadow Council is not a force to be trifled with, $N. Remember that. Go now. Take the water and return to Greta.]],logDesc=[[Take the Purified Moon Well Water to Greta Mosshoof in Felwood.]]}
DB[5160]={id=5160,zoneId=1583,name=[[The Matron Protectorate]],name_loc=[[El Protectorado de la matrona]],level=60,minLevel=57,giver=[[Awbee]],giverType=[[NPC]],giverId=10740,ender=[[Haleh]],enderType=[[NPC]],enderId=10929,rewardNextId=5161,poiX=6110,poiY=-4189,wowhead=[[https://www.wowhead.com/wotlk/quest=5160]],image=[[assets/images/quests/placeholder.png]],desc=[[Travel to Kalimdor, $r. Our flight makes its home in the frigid landscape of Winterspring. Once you reach Winterspring, find the caves of Mazthoril. Upon the icy floors of Mazthoril you will find cobalt runes. Hold one of my scales and stand upon a rune and you shall be transported to Haleh, our matron protectorate. Give her the scale so that she may scry what it is I have seen and felt, here in this doomed place.]],logDesc=[[Travel to Winterspring and find Haleh. Give her Awbee's scale.]]}
DB[5161]={id=5161,zoneId=618,name=[[Wrath of the Blue Flight]],name_loc=[[La cólera del Vuelo Azul]],level=60,minLevel=57,giver=[[Haleh]],giverType=[[NPC]],giverId=10929,ender=[[Haleh]],enderType=[[NPC]],enderId=10929,prevId=5160,rewardNextId=5162,poiX=6110,poiY=-4189,wowhead=[[https://www.wowhead.com/wotlk/quest=5161]],image=[[assets/images/quests/placeholder.png]],desc=[[We understand what the cursed brood of Deathwing attempts to do and we know that it cannot be allowed. Because of the protection Blackrock mountain affords Nefarian, it has become increasingly difficult for us to intercede. We can, however, empower you, mortal - should you so choose. The path before you is one full of peril. You must decide whether to accept our help. Ponder this and speak with me again when a decision has been made.]],logDesc=[[Speak with Haleh if you wish to continue.]]}
DB[5162]={id=5162,zoneId=28,name=[[Wrath of the Blue Flight]],name_loc=[[La cólera del Vuelo Azul]],level=60,minLevel=57,giver=[[Haleh]],giverType=[[NPC]],giverId=10929,ender=[[Jeziba]],enderType=[[NPC]],enderId=10976,prevId=5161,rewardNextId=5164,poiX=1452,poiY=-1276,wowhead=[[https://www.wowhead.com/wotlk/quest=5162]],image=[[assets/images/quests/placeholder.png]],desc=[[It is the arcane that I control and the arcane which will send you to your next destination. When you are ready, the journey will begin. To the Plaguelands you will go and to Jeziba you will speak. He is a mortal as wise as the ancients and as patient as the immovable earth. Find him in Andorhal. ]],logDesc=[[Speak with Jeziba in the Plaguelands. He resides in Andorhal.]]}
DB[5163]={id=5163,zoneId=618,name=[[Are We There, Yeti?]],name_loc=[[Yeti... ¿ya hemos llegado?]],level=58,minLevel=52,giver=[[Umi Rumplesnicker]],giver_loc=[[Umi Risitas]],giverType=[[NPC]],giverId=10305,ender=[[Umi Rumplesnicker]],ender_loc=[[Umi Risitas]],enderType=[[NPC]],enderId=10305,prevId=977,poiX=6706,poiY=-4686,wowhead=[[https://www.wowhead.com/wotlk/quest=5163]],image=[[assets/images/quests/placeholder.png]],desc=[[It's all ready, $N! Now, I sent some mail to my friends already, telling them that I have a surprise for them. This is where you come in! I'm going to give you my mechanical yeti, and you need to surprise them by paying each of my friends a visit, turning the yeti on and sending it towards them.  Once you have shown Legacki in Everlook, Sprinkle in Gadgetzan, and Quixxil in Marshal's Refuge, come back and tell me what happened! Please bring my yeti back to me then, too.]],logDesc=[[Take Umi's Mechanical Yeti and scare her friends with it: Legacki in Everlook (Winterspring) Sprinkle in Gadgetzan (Tanaris) Quixxil in Marshal's Refuge (Un'Goro Crater) When you are done, bring the Mechanical Yeti back to Umi.]],rewards={{id=15778,qty=1}}}
DB[5164]={id=5164,zoneId=28,name=[[Catalogue of the Wayward]],name_loc=[[Catálogo del Díscolo]],level=60,minLevel=57,giver=[[Jeziba]],giverType=[[NPC]],giverId=10976,ender=[[Catalogue of the Wayward]],ender_loc=[[Catálogo del Díscolo]],enderType=[[GO]],enderId=176192,prevId=5162,poiX=1458,poiY=-1275,wowhead=[[https://www.wowhead.com/wotlk/quest=5164]],image=[[assets/images/quests/placeholder.png]],desc=[[A finer instrument of justice, Haleh could not have chosen. Read from the catalogue of the wayward and be enlightened. Should you persist... should you do what is asked of you... should you survive... a hero you will make.]],logDesc=[[Read from the Catalogue of the Wayward. ]]}
DB[5165]={id=5165,zoneId=361,name=[[Dousing the Flames of Protection]],name_loc=[[Sofocar las llamas de protección]],level=55,minLevel=48,giver=[[Greta Mosshoof]],giver_loc=[[Greta Pezuñamusgo]],giverType=[[NPC]],giverId=10922,ender=[[Greta Mosshoof]],ender_loc=[[Greta Pezuñamusgo]],enderType=[[NPC]],enderId=10922,prevId=5159,poiX=3984,poiY=-1304,wowhead=[[https://www.wowhead.com/wotlk/quest=5165]],image=[[assets/images/quests/placeholder.png]],desc=[[Now, you must return to Jaedenar. The braziers are more than likely spread throughout Shadow Hold. Douse each of their flames and the protections the Council has set up will fall for at least a short period of time. I will be waiting for that to happen. When it does, I will look deep within the Hold and try to find out who the head of this beast is. Then, and only then, will we see about attacking them directly.]],logDesc=[[Using the Purified Moon Well Water, douse the flames of the four braziers of protection within Shadow Hold in Felwood, then return to Greta Mosshoof in the Emerald Sanctuary.]]}
DB[5166]={id=5166,zoneId=28,name=[[Breastplate of the Chromatic Flight]],name_loc=[[Coraza del Vuelo Cromático]],level=60,minLevel=57,giver=[[Catalogue of the Wayward]],giver_loc=[[Catálogo del Díscolo]],giverType=[[GO]],giverId=176192,ender=[[Jeziba]],enderType=[[NPC]],enderId=10976,prevId=5164,poiX=1452,poiY=-1276,wowhead=[[https://www.wowhead.com/wotlk/quest=5166]],image=[[assets/images/quests/placeholder.png]],desc=[[The forging of a powerful breastplate to protect against the unrelenting attacks of the chromatic flight is one built upon irony. The scales of the very beasts we battle must be sewn to the pristine carapace of an elder chromatic drake or dragon. None are known to exist at this time and we should hope that none will ever exist. Lastly, perhaps the most difficult of all components: the blood of heroes. The Sculptor must ultimately forge this creation.]],logDesc=[[To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor': 1 Chromatic Carapace. 10 Brilliant Chromatic Scales. 10 Blood of Heroes. 10 Frayed Abomination Stitchings.]],rewards={{id=12895,qty=1}}}
DB[5167]={id=5167,zoneId=28,name=[[Legplates of the Chromatic Defier]],name_loc=[[Quijotes del desafiante cromático]],level=60,minLevel=57,giver=[[Catalogue of the Wayward]],giver_loc=[[Catálogo del Díscolo]],giverType=[[GO]],giverId=176192,ender=[[Jeziba]],enderType=[[NPC]],enderId=10976,prevId=5164,poiX=1452,poiY=-1276,wowhead=[[https://www.wowhead.com/wotlk/quest=5167]],image=[[assets/images/quests/placeholder.png]],desc=[[The carapace of a mature chromatic drake is needed to form the foundation of the leggings. Brilliant chromatic scales are then layered upon the wire frame and enchanted in the blood of heroes. Finally, the supple skin of shadow must be applied to the inner greaves.]],logDesc=[[To forge the Legplates of the Chromatic Defier, you will be required to bring the following items to Jeziba the 'Sculptor': 1 Chromatic Carapace. 10 Brilliant Chromatic Scales. 10 Blood of Heroes. 5 Skin of Shadow.]],choiceRewards={{id=12903,qty=1},{id=12945,qty=1}}}
DB[5168]={id=5168,zoneId=139,name=[[Heroes of Darrowshire]],name_loc=[[Los héroes de Villa Darrow]],level=56,minLevel=50,giver=[[Carlin Redpath]],giver_loc=[[Carlin Rutagrana]],giverType=[[NPC]],giverId=11063,ender=[[Carlin Redpath]],ender_loc=[[Carlin Rutagrana]],enderType=[[NPC]],enderId=11063,prevId=5210,nextId=5206,exGroup=-5181,poiX=2257,poiY=-5341,wowhead=[[https://www.wowhead.com/wotlk/quest=5168]],image=[[assets/images/quests/placeholder.png]],desc=[[The heroes of Darrowshire hold a place in my heart, and the book you brought me, the Annals of Darrowshire, tells their tales. It tells of the paladin Davil Lightfire and how the Crusade took his libram to the town hall of Hearthglen. Its passages also speak of my brother, Captain Redpath.  After his betrayal, his shield was cracked and discarded and now lies in the most unlikely of places -- near the barn of Gahrron's Withering. Gather these relics, $N.  For fate and tragedy surrounds them.]],logDesc=[[Bring Davil's Libram and Redpath's Shield to Carlin Redpath.]]}
DB[5181]={id=5181,zoneId=139,name=[[Villains of Darrowshire]],name_loc=[[Los villanos de Villa Darrow]],level=57,minLevel=50,giver=[[Carlin Redpath]],giver_loc=[[Carlin Rutagrana]],giverType=[[NPC]],giverId=11063,ender=[[Carlin Redpath]],ender_loc=[[Carlin Rutagrana]],enderType=[[NPC]],enderId=11063,prevId=5210,nextId=5206,exGroup=-5181,poiX=2511,poiY=-4164,wowhead=[[https://www.wowhead.com/wotlk/quest=5181]],image=[[assets/images/quests/placeholder.png]],desc=[[The Annals of Darrowshire tells of the villains of that battle.  It tells how the ghoul lord Horgus the Ravager was destroyed by Alliance forces during the battle.  His body was cast into a lake, northwest of Corin's Crossing, and his skull remains there. Marduk the Black was never defeated, but his fabled sword was shattered and lost.  It lies at the bottom of the gorge west of Corin's Crossing. Retrieve these items, $N.  I know not why, but I am certain their fate lies with you.]],logDesc=[[Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel.]]}
DB[5201]={id=5201,zoneId=618,name=[[Winterfall Intrusion]],name_loc=[[Intrusión Nevada]],level=60,minLevel=58,giver=[[Rivern Frostwind]],giver_loc=[[Rivern Ventogélido]],giverType=[[NPC]],giverId=10618,ender=[[Rivern Frostwind]],ender_loc=[[Rivern Ventogélido]],enderType=[[NPC]],enderId=10618,poiX=6721,poiY=-5278,wowhead=[[https://www.wowhead.com/wotlk/quest=5201]],image=[[assets/images/quests/placeholder.png]],desc=[[My presence goes unnoticed by most, $N. However, there is an annoyance that seems firmly rooted here in Winterspring: the Winterfall furbolg. Although I have never directly attacked the furbolg, they seem crazed, fearful of anything in their path. I have watched them slay countless creatures that had the misfortune to simply be in the wrong place at the wrong time. I am weary of their meddling -- please, help me by fighting back. Slay the furbolg and keep them away from Frostsaber Rock.]],logDesc=[[Rivern Frostwind wants you to slay 5 Winterfall Shaman and 5 Winterfall Ursa.]]}
DB[5202]={id=5202,zoneId=361,name=[[A Strange Red Key]],name_loc=[[Una extraña llave roja]],level=55,minLevel=49,giverType=[[NPC]],ender=[[Captured Arko'narin]],ender_loc=[[Arko'narin capturada]],enderType=[[NPC]],enderId=11016,poiX=5007,poiY=-440,wowhead=[[https://www.wowhead.com/wotlk/quest=5202]],image=[[assets/images/quests/placeholder.png]],desc=[[The small red key seems to be made of some kind of bone material. It is heavy in your hand, but appears very fragile. Why would a member of the Shadow Council have such a thing? Perhaps there is something within Jaedenar that this strange key unlocks.]],logDesc=[[Search through Jaedenar to discover what the Blood Red Key is used for.]]}
DB[5203]={id=5203,zoneId=361,name=[[Rescue From Jaedenar]],name_loc=[[El rescate en Jaedenar]],level=55,minLevel=49,giver=[[Captured Arko'narin]],giver_loc=[[Arko'narin capturada]],giverType=[[NPC]],giverId=11016,ender=[[Jessir Moonbow]],ender_loc=[[Jessir Arcolunar]],enderType=[[NPC]],enderId=11019,prevId=5202,rewardNextId=5204,poiX=4822,poiY=-410,wowhead=[[https://www.wowhead.com/wotlk/quest=5203]],image=[[assets/images/quests/placeholder.png]],desc=[[But, as much as it pains me, there is one thing that must be done first: I have to find Trey's sword Lightforge and escape Shadow Hold to tell my superiors what's happening here. Can you help me, $N? Our equipment isn't far from here, and you've already proven you can survive the path to the top. After we escape, I'll head to Darnassus if you can find my friend Jessir near the Ashenvale border. She was to meet us at the Emerald Circle's camp near there. What do you say, $N? Can you help me again?]],logDesc=[[Escort Arko'narin to where Lightforge and her equipment are being held, and then protect her as you escape Shadow Hold. Afterwards, seek out Jessir Moonbow in Felwood to let her know what's happened to her friends.]]}
DB[5204]={id=5204,zoneId=361,name=[[Retribution of the Light]],name_loc=[[La reprensión de la Luz]],level=57,minLevel=49,giver=[[Jessir Moonbow]],giver_loc=[[Jessir Arcolunar]],giverType=[[NPC]],giverId=11019,ender=[[Remains of Trey Lightforge]],ender_loc=[[Restos de Trey Forjaluz]],enderType=[[NPC]],enderId=11020,prevId=5203,rewardNextId=5385,poiX=5197,poiY=-561,wowhead=[[https://www.wowhead.com/wotlk/quest=5204]],image=[[assets/images/quests/placeholder.png]],desc=[[She would like to pretend that she's fine. She'd love for me to think that she's strong enough to deal with all of this on her own, but I know better than that. Trey's death and hearing the torture he was put through is going to haunt her for a long time, and there's nothing we can do to stop that. But we can give her some peace! $N, return to Shadow Hold, kill Trey's torturer and find his remains. There is no reason we can't tie off all these loose ends while Arko'narin mourns in her own private way.]],logDesc=[[Return to Jaedenar and kill the succubus Rakaiah before finding the Remains of Trey Lightforge.]],rewards={{id=13562,qty=1}}}
DB[5206]={id=5206,zoneId=139,name=[[Marauders of Darrowshire]],name_loc=[[Los merodeadores de Villa Darrow]],level=60,minLevel=50,giver=[[Carlin Redpath]],giver_loc=[[Carlin Rutagrana]],giverType=[[NPC]],giverId=11063,ender=[[Carlin Redpath]],ender_loc=[[Carlin Rutagrana]],enderType=[[NPC]],enderId=11063,rewardNextId=5941,poiX=2650,poiY=-5551,wowhead=[[https://www.wowhead.com/wotlk/quest=5206]],image=[[assets/images/quests/placeholder.png]],desc=[[Chromie said the relics you gathered are reagents to a powerful spell, and one more is required: skulls from the scourge who took part in the battle of Darrowshire. Take this crystal and hunt scourge champions for their skulls.  The crystal is enchanted; if a champion took part in the battle, then when you pass the crystal over its skull it will resonate.  Bring me those resonating skulls. Go, $N.  You'll find scourge champions in the Noxious Glade to the north and the Fungal Vale to the west.]],logDesc=[[Bring 5 Resonating Skulls and the Mystic Crystal to Carlin Redpath in Eastern Plaguelands.]]}
DB[5210]={id=5210,zoneId=139,name=[[Brother Carlin]],name_loc=[[Carlin, el hermano de Joseph]],level=56,minLevel=50,giver=[[Chromie]],giver_loc=[[Cromi]],giverType=[[NPC]],giverId=10667,ender=[[Carlin Redpath]],ender_loc=[[Carlin Rutagrana]],enderType=[[NPC]],enderId=11063,prevId=5154,rewardNextId=5181,poiX=2257,poiY=-5341,wowhead=[[https://www.wowhead.com/wotlk/quest=5210]],image=[[assets/images/quests/placeholder.png]],desc=[[The Annals of Darrowshire, through my magic, has gained pages at its end, and now it extends its history beyond the battle.  One of the extra passages tells of another Redpath, Carlin, who survived Joseph's betrayal.  Carlin's now in the Plaguelands to the east, at the Light's Hope Chapel. Take the book and speak with him.]],logDesc=[[Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands.]]}
DB[5211]={id=5211,zoneId=139,name=[[Defenders of Darrowshire]],name_loc=[[Los defensores de Villa Darrow]],level=55,minLevel=50,giver=[[Carlin Redpath]],giver_loc=[[Carlin Rutagrana]],giverType=[[NPC]],giverId=11063,ender=[[Carlin Redpath]],ender_loc=[[Carlin Rutagrana]],enderType=[[NPC]],enderId=11063,poiX=2257,poiY=-5341,wowhead=[[https://www.wowhead.com/wotlk/quest=5211]],image=[[assets/images/quests/placeholder.png]],desc=[[Many of the defenders fell at the battle of Darrowshire.  And many roam again as the ghastly servants of the Scourge!  Find these poor souls and end their misery! Hunt cannibal ghouls, gibbering ghouls and diseased flayers.  Many of these fiends were once the good folk of Darrowshire and destroying their forms now will set their souls free. You will find them in Plaguewood and Corin's Crossing, and in other Scourge strongholds of Eastern Plaguelands.]],logDesc=[[Free 15 Darrowshire Spirits and return to Carlin Redpath.]]}
DB[5212]={id=5212,zoneId=2017,name=[[The Flesh Does Not Lie]],name_loc=[[La carne no miente]],level=60,minLevel=55,giver=[[Betina Bigglezink]],giver_loc=[[Betina Bigglezink]],giverType=[[NPC]],giverId=11035,ender=[[Betina Bigglezink]],ender_loc=[[Betina Bigglezink]],enderType=[[NPC]],enderId=11035,rewardNextId=5213,poiX=2260,poiY=-5339,wowhead=[[https://www.wowhead.com/wotlk/quest=5212]],image=[[assets/images/quests/placeholder.png]],desc=[[The Forsaken apothecaries are not the only beings in this world schooled in the sciences. I have been studying the plague for years, $r. We had previously thought that the potency of the plague was dwindling, but what I have discovered here in the Plaguelands is startling. The plague seems to be growing in strength! I need to run more tests! The most potent source of the plague is from the tainted flesh of the most recently infected. Travel to Stratholme and bring me samples, $N. ]],logDesc=[[Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.]]}
DB[5213]={id=5213,zoneId=2017,name=[[The Active Agent]],name_loc=[[El agente activo]],level=60,minLevel=55,giver=[[Betina Bigglezink]],giver_loc=[[Betina Bigglezink]],giverType=[[NPC]],giverId=11035,ender=[[Betina Bigglezink]],ender_loc=[[Betina Bigglezink]],enderType=[[NPC]],enderId=11035,prevId=5212,poiX=2260,poiY=-5339,wowhead=[[https://www.wowhead.com/wotlk/quest=5213]],image=[[assets/images/quests/placeholder.png]],desc=[[You will have to delve deeper into Stratholme, $N. Beyond the first gates you will find the ziggurats. We know that the Scourge draws great power from these structures. Search the Ziggurats and return with any information that you may discover. ]],logDesc=[[Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink. ]],choiceRewards={{id=13209,qty=1},{id=19812,qty=1}}}
DB[5214]={id=5214,zoneId=2017,name=[[The Great Fras Siabi]],name_loc=[[El gran Fras Siabi]],level=60,minLevel=55,giver=[[Smokey LaRue]],giverType=[[NPC]],giverId=11033,ender=[[Smokey LaRue]],enderType=[[NPC]],enderId=11033,poiX=3492,poiY=-3303,wowhead=[[https://www.wowhead.com/wotlk/quest=5214]],image=[[assets/images/quests/placeholder.png]],desc=[[Terrible thing... what happened to Fras. You see, the town was sacked and Fras didn't want to leave his precious goods behind. The last thing I remember him saying was, 'I'll burn every last leaf before they get their damned, dirty hands on them!' I may love a good stogie but I'm no fool. I left Fras and his delightful store that day. I assume he went down in flames but if there's a chance that even one box of his famous tobacco is still intact... What do you say, $N? Find a box for ol' Smokey?]],logDesc=[[Find Fras Siabi's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done. ]],rewards={{id=13171,qty=1}}}
DB[5215]={id=5215,zoneId=28,name=[[The Scourge Cauldrons]],name_loc=[[Las calderas de la Plaga]],level=53,minLevel=50,giver=[[Commander Ashlam Valorfist]],giver_loc=[[Comandante Ashlam Puñovalor]],giverType=[[NPC]],giverId=10838,ender=[[High Priestess MacDonnell]],ender_loc=[[Suma sacerdotisa MacDonnell]],enderType=[[NPC]],enderId=11053,prevId=5092,rewardNextId=5216,poiX=944,poiY=-1431,wowhead=[[https://www.wowhead.com/wotlk/quest=5215]],image=[[assets/images/quests/placeholder.png]],desc=[[Within the lands of former Lordaeron are eight cauldrons - four here in the west, and four more ensconced in the east.  These cauldrons spew poisons into the air, propagating the plague throughout the land for the Scourge. The necromantic might of Kel'Thuzad is too strong to outright shut down these cauldrons, but we think we might have a way to subvert them to our advantage.  My second, High Priestess MacDonnell, will be your point on this assignment; she'll continue the briefing from here.]],logDesc=[[Speak with High Priestess MacDonnell at Chillwind Point, Western Plaguelands.]]}
DB[5216]={id=5216,zoneId=28,name=[[Target: Felstone Field]],name_loc=[[Objetivo: Campo de Piedramácula]],level=53,minLevel=50,giver=[[High Priestess MacDonnell]],giver_loc=[[Suma sacerdotisa MacDonnell]],giverType=[[NPC]],giverId=11053,ender=[[Scourge Cauldron]],enderType=[[GO]],enderId=176361,prevId=5215,nextId=5218,rewardNextId=5217,poiX=1729,poiY=-1175,wowhead=[[https://www.wowhead.com/wotlk/quest=5216]],image=[[assets/images/quests/placeholder.png]],desc=[[Of the four cauldrons here in the west, the one located at Felstone Field may be the easiest one in obtaining access to.  The Scourge have greener troops positioned here, though they should not be underestimated. Go to Felstone Field, northwest of Andorhal, and engage the cauldron lord there.  We think it has a key that will unlock access to the cauldron.  When unlocked, use this bottle to obtain a sample of the poisons inside the cauldron; we'll need it for study in developing a counter agent.]],logDesc=[[Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there.  It may have a key that will allow access to the cauldron.  You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.]]}
DB[5217]={id=5217,zoneId=28,name=[[Return to Chillwind Camp]],name_loc=[[Regresa al Campamento del Orvallo]],level=53,minLevel=50,giver=[[Scourge Cauldron]],giverType=[[GO]],giverId=176361,ender=[[High Priestess MacDonnell]],ender_loc=[[Suma sacerdotisa MacDonnell]],enderType=[[NPC]],enderId=11053,prevId=5216,rewardNextId=5219,poiX=944,poiY=-1431,wowhead=[[https://www.wowhead.com/wotlk/quest=5217]],image=[[assets/images/quests/placeholder.png]],desc=[[You fill the bottle with enough of the cauldron's poisonous concoction for a suitable sample to be studied. With the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.]],logDesc=[[Bring the Filled Felstone Field Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands.]]}
DB[5218]={id=5218,zoneId=28,name=[[Felstone Field Cauldron]],name_loc=[[La caldera del Campo de Piedramácula]],level=53,minLevel=50,giver=[[Scourge Cauldron]],giverType=[[GO]],giverId=176361,ender=[[Scourge Cauldron]],enderType=[[GO]],enderId=176361,poiX=1739,poiY=-1185,wowhead=[[https://www.wowhead.com/wotlk/quest=5218]],image=[[assets/images/quests/placeholder.png]]}
DB[5219]={id=5219,zoneId=28,name=[[Target: Dalson's Tears]],name_loc=[[Objetivo: Llanto de Dalson]],level=55,minLevel=50,giver=[[High Priestess MacDonnell]],giver_loc=[[Suma sacerdotisa MacDonnell]],giverType=[[NPC]],giverId=11053,ender=[[Scourge Cauldron]],enderType=[[GO]],enderId=177289,prevId=5217,nextId=5221,rewardNextId=5220,poiX=1865,poiY=-1569,wowhead=[[https://www.wowhead.com/wotlk/quest=5219]],image=[[assets/images/quests/placeholder.png]],desc=[[One of the plague cauldrons is located in the field of a former farmhouse now referred to as Dalson's Tears.  Well, we shall shed no tears this day as we thwart the Scourge and have them choke on their own fumes! Go to Dalson's Tears, almost due north of Andorhal, and eliminate the cauldron lord there.  It should have a key like the last one did, allowing you into the cauldron.  Use this bottle to obtain a sample from inside the cauldron; each cauldron has its own distinct brew of toxins it uses.]],logDesc=[[Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.]]}
DB[5220]={id=5220,zoneId=28,name=[[Return to Chillwind Camp]],name_loc=[[Regresa al Campamento del Orvallo]],level=55,minLevel=50,giver=[[Scourge Cauldron]],giverType=[[GO]],giverId=177289,ender=[[High Priestess MacDonnell]],ender_loc=[[Suma sacerdotisa MacDonnell]],enderType=[[NPC]],enderId=11053,prevId=5219,rewardNextId=5222,poiX=944,poiY=-1431,wowhead=[[https://www.wowhead.com/wotlk/quest=5220]],image=[[assets/images/quests/placeholder.png]],desc=[[You carefully fill the bottle with enough of the cauldron's ichors for what you consider to be suitably sized sample. With the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.]],logDesc=[[Bring the Filled Dalson's Tears Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands.]]}
DB[5221]={id=5221,zoneId=28,name=[[Dalson's Tears Cauldron]],name_loc=[[La caldera del Llanto de Dalson]],level=55,minLevel=50,giver=[[Scourge Cauldron]],giverType=[[GO]],giverId=177289,ender=[[Scourge Cauldron]],enderType=[[GO]],enderId=177289,poiX=1879,poiY=-1569,wowhead=[[https://www.wowhead.com/wotlk/quest=5221]],image=[[assets/images/quests/placeholder.png]]}
DB[5222]={id=5222,zoneId=28,name=[[Target: Writhing Haunt]],name_loc=[[Objetivo: El Tormento]],level=55,minLevel=50,giver=[[High Priestess MacDonnell]],giver_loc=[[Suma sacerdotisa MacDonnell]],giverType=[[NPC]],giverId=11053,ender=[[Scourge Cauldron]],enderType=[[GO]],enderId=176393,prevId=5220,nextId=5224,rewardNextId=5223,poiX=1473,poiY=-1863,wowhead=[[https://www.wowhead.com/wotlk/quest=5222]],image=[[assets/images/quests/placeholder.png]],desc=[[Two cauldrons have been successfully opened; while you will be able to access them indefinitely, we still want to open up the other two that remain.  This will provide all of us with more options to introduce the counter agent! This time, you'll be hitting the Writhing Haunt's cauldron.  It is almost due east of Andorhal, relatively close to the ruined city walls; again, eliminate the cauldron lord present there for its key.  Use this bottle to obtain the sample from the cauldron. Good hunting, $N!]],logDesc=[[Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.]]}
DB[5223]={id=5223,zoneId=28,name=[[Return to Chillwind Camp]],name_loc=[[Regresa al Campamento del Orvallo]],level=55,minLevel=50,giver=[[Scourge Cauldron]],giverType=[[GO]],giverId=176393,ender=[[High Priestess MacDonnell]],ender_loc=[[Suma sacerdotisa MacDonnell]],enderType=[[NPC]],enderId=11053,prevId=5222,rewardNextId=5225,poiX=944,poiY=-1431,wowhead=[[https://www.wowhead.com/wotlk/quest=5223]],image=[[assets/images/quests/placeholder.png]],desc=[[You delicately top off the empty bottle; a sample of the foul substance that churns under the platform of the cauldron now oozes back and forth inside the fragile glass container. With the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.]],logDesc=[[Bring the Filled Writhing Haunt Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands.]]}
DB[5224]={id=5224,zoneId=28,name=[[Writhing Haunt Cauldron]],name_loc=[[La caldera de El Tormento]],level=55,minLevel=50,giver=[[Scourge Cauldron]],giverType=[[GO]],giverId=176393,ender=[[Scourge Cauldron]],enderType=[[GO]],enderId=176393,poiX=1486,poiY=-1863,wowhead=[[https://www.wowhead.com/wotlk/quest=5224]],image=[[assets/images/quests/placeholder.png]]}
DB[5225]={id=5225,zoneId=28,name=[[Target: Gahrron's Withering]],name_loc=[[Objetivo: Gangrena de Gahrron]],level=58,minLevel=50,giver=[[High Priestess MacDonnell]],giver_loc=[[Suma sacerdotisa MacDonnell]],giverType=[[NPC]],giverId=11053,ender=[[Scourge Cauldron]],ender_loc=[[Caldera de la Plaga]],enderType=[[GO]],enderId=176392,prevId=5223,nextId=5227,rewardNextId=5226,poiX=1679,poiY=-2278,wowhead=[[https://www.wowhead.com/wotlk/quest=5225]],image=[[assets/images/quests/placeholder.png]],desc=[[The last cauldron that remains is located on a farm now called Gahrron's Withering.  It is guarded by some of the Scourge's tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, $N. Gahrron's Withering is due northeast of our position here, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the Light protect you in this dangerous mission, $c.]],logDesc=[[Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.]]}
DB[5226]={id=5226,zoneId=28,name=[[Return to Chillwind Camp]],name_loc=[[Regresa al Campamento del Orvallo]],level=58,minLevel=50,giver=[[Scourge Cauldron]],giver_loc=[[Caldera de la Plaga]],giverType=[[GO]],giverId=176392,ender=[[High Priestess MacDonnell]],ender_loc=[[Suma sacerdotisa MacDonnell]],enderType=[[NPC]],enderId=11053,prevId=5225,poiX=944,poiY=-1431,wowhead=[[https://www.wowhead.com/wotlk/quest=5226]],image=[[assets/images/quests/placeholder.png]],desc=[[You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle. With the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.]],logDesc=[[Bring the Filled Gahrron's Withering Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands.]]}
DB[5227]={id=5227,zoneId=28,name=[[Gahrron's Withering Cauldron]],name_loc=[[La caldera de la Gangrena de Gahrron]],level=58,minLevel=50,giver=[[Scourge Cauldron]],giver_loc=[[Caldera de la Plaga]],giverType=[[GO]],giverId=176392,ender=[[Scourge Cauldron]],ender_loc=[[Caldera de la Plaga]],enderType=[[GO]],enderId=176392,poiX=1690,poiY=-2273,wowhead=[[https://www.wowhead.com/wotlk/quest=5227]],image=[[assets/images/quests/placeholder.png]]}
DB[5228]={id=5228,zoneId=28,name=[[The Scourge Cauldrons]],name_loc=[[Las calderas de la Plaga]],level=53,minLevel=50,giver=[[High Executor Derrington]],giver_loc=[[Sumo ejecutor Derrington]],giverType=[[NPC]],giverId=10837,ender=[[Shadow Priestess Vandis]],ender_loc=[[Sacerdotisa de las Sombras Vandis]],enderType=[[NPC]],enderId=11055,prevId=5096,rewardNextId=5229,poiX=1671,poiY=-719,wowhead=[[https://www.wowhead.com/wotlk/quest=5228]],image=[[assets/images/quests/placeholder.png]],desc=[[Within the lands of former Lordaeron are eight cauldrons - four in the west, and four more entrenched in the east.  These cauldrons spew poisons into the air, propagating the plague throughout the land for the Scourge. The necromantic might of Kel'Thuzad is too strong to outright shut down these cauldrons, but we think we might have a way to subvert them to our advantage.  My second, Shadow Priestess Vandis, will be your point on this assignment; she'll continue the briefing from here.]],logDesc=[[Speak with Shadow Priestess Vandis at the Bulwark, Western Plaguelands.]]}
DB[5229]={id=5229,zoneId=28,name=[[Target: Felstone Field]],name_loc=[[Objetivo: Campo de Piedramácula]],level=53,minLevel=50,giver=[[Shadow Priestess Vandis]],giver_loc=[[Sacerdotisa de las Sombras Vandis]],giverType=[[NPC]],giverId=11055,ender=[[Scourge Cauldron]],enderType=[[GO]],enderId=176361,prevId=5228,nextId=5218,rewardNextId=5230,poiX=1729,poiY=-1175,wowhead=[[https://www.wowhead.com/wotlk/quest=5229]],image=[[assets/images/quests/placeholder.png]],desc=[[Of the four cauldrons in the Western Plaguelands, the one at Felstone Field may be the easiest one to gain access to.  The Scourge have greener troops positioned here, though they should not be underestimated. Go to Felstone Field, due east of here and northwest of Andorhal, and engage the cauldron lord there.  On it is a key that will unlock access to the cauldron.  When unlocked, use this bottle to get a sample of the cauldron's toxins; we'll need it for study in developing a counter agent.]],logDesc=[[Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there.  It may have a key that will allow access to the cauldron.  You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.]]}
DB[5230]={id=5230,zoneId=28,name=[[Return to the Bulwark]],name_loc=[[Regresa a El Baluarte]],level=53,minLevel=50,giver=[[Scourge Cauldron]],giverType=[[GO]],giverId=176361,ender=[[Shadow Priestess Vandis]],ender_loc=[[Sacerdotisa de las Sombras Vandis]],enderType=[[NPC]],enderId=11055,prevId=5229,rewardNextId=5231,poiX=1671,poiY=-719,wowhead=[[https://www.wowhead.com/wotlk/quest=5230]],image=[[assets/images/quests/placeholder.png]],desc=[[You fill the bottle with enough of the cauldron's poisonous concoction for a suitable sample to be studied. With the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.]],logDesc=[[Bring the Filled Felstone Field Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands.]]}
DB[5231]={id=5231,zoneId=28,name=[[Target: Dalson's Tears]],name_loc=[[Objetivo: Llanto de Dalson]],level=55,minLevel=50,giver=[[Shadow Priestess Vandis]],giver_loc=[[Sacerdotisa de las Sombras Vandis]],giverType=[[NPC]],giverId=11055,ender=[[Scourge Cauldron]],enderType=[[GO]],enderId=177289,prevId=5230,nextId=5221,rewardNextId=5232,poiX=1865,poiY=-1569,wowhead=[[https://www.wowhead.com/wotlk/quest=5231]],image=[[assets/images/quests/placeholder.png]],desc=[[One of the plague cauldrons is located in the field of a former farmhouse now referred to as Dalson's Tears.  No tears will be shed this day, $c; we must strike at this cauldron and gain access to it! Go to Dalson's Tears, almost due north of Andorhal, and eliminate the cauldron lord there.  It should have a key like the last one did, allowing you inside the cauldron's innards.  Use this bottle to obtain a sample from inside the cauldron; each cauldron has its own distinct brew of toxins it uses.]],logDesc=[[Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.]]}
DB[5232]={id=5232,zoneId=28,name=[[Return to the Bulwark]],name_loc=[[Regresa a El Baluarte]],level=55,minLevel=50,giver=[[Scourge Cauldron]],giverType=[[GO]],giverId=177289,ender=[[Shadow Priestess Vandis]],ender_loc=[[Sacerdotisa de las Sombras Vandis]],enderType=[[NPC]],enderId=11055,prevId=5231,rewardNextId=5233,poiX=1671,poiY=-719,wowhead=[[https://www.wowhead.com/wotlk/quest=5232]],image=[[assets/images/quests/placeholder.png]],desc=[[You carefully fill the bottle with enough of the cauldron's ichors for what you consider to be suitably sized sample. With the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.]],logDesc=[[Bring the Filled Dalson's Tears Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands.]]}
DB[5233]={id=5233,zoneId=28,name=[[Target: Writhing Haunt]],name_loc=[[Objetivo: El Tormento]],level=55,minLevel=50,giver=[[Shadow Priestess Vandis]],giver_loc=[[Sacerdotisa de las Sombras Vandis]],giverType=[[NPC]],giverId=11055,ender=[[Scourge Cauldron]],enderType=[[GO]],enderId=176393,prevId=5232,nextId=5224,rewardNextId=5234,poiX=1473,poiY=-1863,wowhead=[[https://www.wowhead.com/wotlk/quest=5233]],image=[[assets/images/quests/placeholder.png]],desc=[[Two cauldrons have been successfully opened; while you'll be able to access them indefinitely, we still want to open up the other two that remain.  This will provide all of us with more options to introduce the counter agent! This time, you'll be hitting the Writhing Haunt's cauldron.  It is almost due east of Andorhal, relatively close to the ruined city walls; again, eliminate the cauldron lord present there for its key.  Use this bottle to obtain the sample from the cauldron. Good hunting, $N!]],logDesc=[[Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.]]}
DB[5234]={id=5234,zoneId=28,name=[[Return to the Bulwark]],name_loc=[[Regresa a El Baluarte]],level=55,minLevel=50,giver=[[Scourge Cauldron]],giverType=[[GO]],giverId=176393,ender=[[Shadow Priestess Vandis]],ender_loc=[[Sacerdotisa de las Sombras Vandis]],enderType=[[NPC]],enderId=11055,prevId=5233,rewardNextId=5235,poiX=1671,poiY=-719,wowhead=[[https://www.wowhead.com/wotlk/quest=5234]],image=[[assets/images/quests/placeholder.png]],desc=[[You delicately top off the empty bottle; a sample of the foul substance that churns under the platform of the cauldron now oozes back and forth inside the fragile glass container. With the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.]],logDesc=[[Bring the Filled Writhing Haunt Bottle to Shadow Priestess Vandis at The Bulwark, Western Plaguelands.]]}
DB[5235]={id=5235,zoneId=28,name=[[Target: Gahrron's Withering]],name_loc=[[Objetivo: Gangrena de Gahrron]],level=58,minLevel=50,giver=[[Shadow Priestess Vandis]],giver_loc=[[Sacerdotisa de las Sombras Vandis]],giverType=[[NPC]],giverId=11055,ender=[[Scourge Cauldron]],ender_loc=[[Caldera de la Plaga]],enderType=[[GO]],enderId=176392,prevId=5234,nextId=5227,rewardNextId=5236,poiX=1679,poiY=-2278,wowhead=[[https://www.wowhead.com/wotlk/quest=5235]],image=[[assets/images/quests/placeholder.png]],desc=[[The last cauldron that remains is located on a farm now called Gahrron's Withering.  It is guarded by some of the Scourge's tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, $N. Gahrron's Withering is far to the east of the Bulwark, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the shadows cloak you in safety for this dangerous mission, $c.]],logDesc=[[Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.]]}
DB[5236]={id=5236,zoneId=28,name=[[Return to the Bulwark]],name_loc=[[Regresa a El Baluarte]],level=58,minLevel=50,giver=[[Scourge Cauldron]],giver_loc=[[Caldera de la Plaga]],giverType=[[GO]],giverId=176392,ender=[[Shadow Priestess Vandis]],ender_loc=[[Sacerdotisa de las Sombras Vandis]],enderType=[[NPC]],enderId=11055,prevId=5235,poiX=1671,poiY=-719,wowhead=[[https://www.wowhead.com/wotlk/quest=5236]],image=[[assets/images/quests/placeholder.png]],desc=[[You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle. With the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.]],logDesc=[[Bring the Filled Gahrron's Withering Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands.]]}
DB[5237]={id=5237,zoneId=28,name=[[Mission Accomplished!]],name_loc=[[¡Misión cumplida!]],level=58,minLevel=50,giver=[[Commander Ashlam Valorfist]],giver_loc=[[Comandante Ashlam Puñovalor]],giverType=[[NPC]],giverId=10838,ender=[[Commander Ashlam Valorfist]],ender_loc=[[Comandante Ashlam Puñovalor]],enderType=[[NPC]],enderId=10838,prevId=5226,poiX=958,poiY=-1419,wowhead=[[https://www.wowhead.com/wotlk/quest=5237]],image=[[assets/images/quests/placeholder.png]],rewards={{id=15799,qty=1}},choiceRewards={{id=15801,qty=1},{id=15800,qty=1}}}
DB[5238]={id=5238,zoneId=28,name=[[Mission Accomplished!]],name_loc=[[¡Misión cumplida!]],level=58,minLevel=50,giver=[[High Executor Derrington]],giver_loc=[[Sumo ejecutor Derrington]],giverType=[[NPC]],giverId=10837,ender=[[High Executor Derrington]],ender_loc=[[Sumo ejecutor Derrington]],enderType=[[NPC]],enderId=10837,prevId=5236,poiX=1761,poiY=-723,wowhead=[[https://www.wowhead.com/wotlk/quest=5238]],image=[[assets/images/quests/placeholder.png]],rewards={{id=15799,qty=1}},choiceRewards={{id=15801,qty=1},{id=15800,qty=1}}}
DB[5241]={id=5241,zoneId=139,name=[[Uncle Carlin]],name_loc=[[Tío Carlin]],level=56,minLevel=50,giver=[[Pamela Redpath]],giver_loc=[[Pamela Rutagrana]],giverType=[[NPC]],giverId=10926,ender=[[Carlin Redpath]],ender_loc=[[Carlin Rutagrana]],enderType=[[NPC]],enderId=11063,prevId=5149,rewardNextId=5211,poiX=2257,poiY=-5341,wowhead=[[https://www.wowhead.com/wotlk/quest=5241]],image=[[assets/images/quests/placeholder.png]],desc=[[Sometimes, when it's nighttime, I can hear my Uncle Carlin crying.  It sounds like he's far away, to the east. I hope he's not crying for me!  $N, will you find my uncle and tell him I'm alright? If you find him say I'm waiting for him, and I want to hear the story he used to tell... the one about the rabbits and the berry jam!  That story's so funny!]],logDesc=[[Find Carlin Redpath.]]}
DB[5242]={id=5242,zoneId=361,name=[[A Final Blow]],name_loc=[[Un golpe final]],level=58,minLevel=48,giver=[[Greta Mosshoof]],giver_loc=[[Greta Pezuñamusgo]],giverType=[[NPC]],giverId=10922,ender=[[Greta Mosshoof]],ender_loc=[[Greta Pezuñamusgo]],enderType=[[NPC]],enderId=10922,prevId=5165,poiX=4903,poiY=-397,wowhead=[[https://www.wowhead.com/wotlk/quest=5242]],image=[[assets/images/quests/placeholder.png]],desc=[[Unfortunately, I see the only way to stop this threat to Felwood is a frontal attack. There are no other ways into Shadow Hold, and I have no means to teleport you inside. The straight path down to the bottom is the only way... and I also know who you should seek out. His name is Fel'dan... Shadow Lord Fel'dan. He is the mortal in power down below... he is the head of the serpent. Kill him and his two succubus servants and return to me. Fel'dan is the one making pacts with the Legion. He must be stopped.]],logDesc=[[Kill Moora and Salia, and bring Shadow Lord Fel'dan's Head to Greta Mosshoof in Felwood.]],choiceRewards={{id=15707,qty=1},{id=15708,qty=1},{id=15709,qty=1}}}
DB[5243]={id=5243,zoneId=2017,name=[[Houses of the Holy]],name_loc=[[Las casas de lo sagrado]],level=60,minLevel=55,giver=[[Leonid Barthalomew the Revered]],giver_loc=[[Leonid Barthalomew el Venerado]],giverType=[[NPC]],giverId=11036,ender=[[Leonid Barthalomew the Revered]],ender_loc=[[Leonid Barthalomew el Venerado]],enderType=[[NPC]],enderId=11036,poiX=2307,poiY=-5349,wowhead=[[https://www.wowhead.com/wotlk/quest=5243]],image=[[assets/images/quests/placeholder.png]],desc=[[I look at my undeath as a malady, $r. An illness that merely requires treatment; however, it is also a great blessing for the Argent Dawn. What better vessel to smite the heathens of the Scourge than through the undead? I am revered by my colleagues because of the sacrifices I have made, but the accolades mean nothing to me. If you are interested in assisting the Argent Dawn, then a job I can offer. Venture to Stratholme and recover our surplus of holy water. Search the supply crates. ]],logDesc=[[Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.]],rewards={{id=3928,qty=5},{id=6149,qty=5}},choiceRewards={{id=13216,qty=1},{id=13217,qty=1}}}
DB[5244]={id=5244,zoneId=618,name=[[The Ruins of Kel'Theril]],name_loc=[[Las Ruinas de Kel'Theril]],level=56,minLevel=53,giver=[[Wynd Nightchaser]],giver_loc=[[Wynd Cazanoche]],giverType=[[NPC]],giverId=11079,ender=[[Jaron Stoneshaper]],ender_loc=[[Jaron Tallapiedras]],enderType=[[NPC]],enderId=10301,rewardNextId=5245,poiX=7093,poiY=-4019,wowhead=[[https://www.wowhead.com/wotlk/quest=5244]],image=[[assets/images/quests/placeholder.png]],desc=[[The story behind Kel'Theril is one of a cursed race, bound to the place where they attempted an unfortunate ritual... The highborne that you will find there once stole a sacred artifact, believing that they could siphon its power for themselves, becoming even more powerful. In their efforts, the relic shattered in a huge explosion, driving the pieces below the ice of the lake... Speak with Jaron Stoneshaper if you'd like to learn more; he has recently visited the area and can tell you more.]],logDesc=[[Speak with Jaron Stoneshaper in Starfall Village.]]}
DB[5245]={id=5245,zoneId=618,name=[[Troubled Spirits of Kel'Theril]],name_loc=[[Espíritus condenados de Kel'Theril]],level=56,minLevel=53,giver=[[Jaron Stoneshaper]],giver_loc=[[Jaron Tallapiedras]],giverType=[[NPC]],giverId=10301,ender=[[Aurora Skycaller]],ender_loc=[[Aurora Llamacielo]],enderType=[[NPC]],enderId=10304,prevId=5244,rewardNextId=5246,poiX=3232,poiY=-4256,wowhead=[[https://www.wowhead.com/wotlk/quest=5245]],image=[[assets/images/quests/placeholder.png]],desc=[[The highborne spirits are miserable creatures, that's for sure. They are still searching for pieces of the very thing that has cursed them to Kel'Theril forever -- the stolen relic. If you are that interested, take my pick and go south to the lake, see if you can gather the pieces of it from within the ice. Now, I can't tell you a thing about what you find, but I do know of someone who might... Aurora Skycaller; she dwells near the Northpass Tower in the northern part of Eastern Plaguelands.]],logDesc=[[Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands.]]}
DB[5246]={id=5246,zoneId=139,name=[[Fragments of the Past]],name_loc=[[Trozos del pasado]],level=56,minLevel=53,giver=[[Aurora Skycaller]],giver_loc=[[Aurora Llamacielo]],giverType=[[NPC]],giverId=10304,ender=[[Aurora Skycaller]],ender_loc=[[Aurora Llamacielo]],enderType=[[NPC]],enderId=10304,prevId=5245,rewardNextId=5247,poiX=3232,poiY=-4256,wowhead=[[https://www.wowhead.com/wotlk/quest=5246]],image=[[assets/images/quests/placeholder.png]],desc=[[I did not realize... Forgive my callous words, $c. The mistakes of my ancestors are not what I wish to dwell on, but if your request is truly genuine, then I will help you. <Aurora examines the fragments.> I believe this is the Crystal of Zin-Malor, an artifact that can contain and control strong arcane forces. It could have been used for good, but the evil intentions of those that stole it caused it to shatter. Go to the Temple of Zin-Malor in Azshara - I can only hope the book is still there.]],logDesc=[[Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands.]]}
DB[5247]={id=5247,zoneId=139,name=[[Fragments of the Past]],name_loc=[[Trozos del pasado]],level=57,minLevel=53,giver=[[Aurora Skycaller]],giver_loc=[[Aurora Llamacielo]],giverType=[[NPC]],giverId=10304,ender=[[Aurora Skycaller]],ender_loc=[[Aurora Llamacielo]],enderType=[[NPC]],enderId=10304,prevId=5246,poiX=3232,poiY=-4256,wowhead=[[https://www.wowhead.com/wotlk/quest=5247]],image=[[assets/images/quests/placeholder.png]],desc=[[I will be able to help you, if recreating the artifact is truly what you wish to do. To seal the pieces back together, I will need items with strong magical qualities. An enchanted thorium bar and five crystal restore... You'll also need to collect some water from what might seem an unlikely place... Find the dire pool along Eldreth Row at Dire Maul in Feralas, and fill this vial. While you are gone, I will attempt to glean from these pages the knowledge I need to repair the damage done to the relic.]],logDesc=[[Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands.]]}
DB[5248]={id=5248,zoneId=139,name=[[Tormented By the Past]],name_loc=[[Atormentados por el pasado]],level=58,minLevel=53,giver=[[Aurora Skycaller]],giver_loc=[[Aurora Llamacielo]],giverType=[[NPC]],giverId=10304,ender=[[Remorseful Highborne]],ender_loc=[[Altonato arrepentido]],enderType=[[NPC]],enderId=10684,prevId=5247,rewardNextId=5252,poiX=6430,poiY=-4303,wowhead=[[https://www.wowhead.com/wotlk/quest=5248]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I weep for what has happened in the past. Like this crystal, the elves, as a race, have been shattered. I do not know if the pieces will ever again be reunited into one, but my sorrow has been eased by being able to help you with this one small task.  We must not forget the past, $N... Please take the Crystal of Zin-Malor back to Lake Kel'Theril. You must find a highborne spirit that realizes the error of what was done so long ago. Show the spirit that we have made things right again.]],logDesc=[[Take the Crystal of Zin-Malor to Lake Kel'Theril in Winterspring and find a highborne spirit that will speak to you.]]}
DB[5249]={id=5249,zoneId=361,name=[[To Winterspring!]],name_loc=[[¡A la Cuna del Invierno!]],level=56,minLevel=53,giver=[[Ivy Leafrunner]],giver_loc=[[Ivy Correhoja]],giverType=[[NPC]],giverId=10924,ender=[[Wynd Nightchaser]],ender_loc=[[Wynd Cazanoche]],enderType=[[NPC]],enderId=11079,rewardNextId=5244,poiX=7095,poiY=-4007,wowhead=[[https://www.wowhead.com/wotlk/quest=5249]],image=[[assets/images/quests/placeholder.png]],desc=[[In Winterspring, to the north of here, there are many ancient elven ruins. It's a harsh land, but it holds many secrets and places to explore. With all my work to do here in Felwood, I have not had the opportunity to travel to Winterspring. But there's no reason why you shouldn't! While you're there, look for Wynd Nightchaser. He spends most of his time in Starfall Village and he knows a lot about the area.]],logDesc=[[Find Starfall Village in Winterspring and speak with Wynd Nightchaser.]]}
DB[5250]={id=5250,zoneId=702,name=[[Starfall]],name_loc=[[Estrella Fugaz]],level=56,minLevel=53,giver=[[Daryn Lightwind]],giver_loc=[[Daryn Brisela]],giverType=[[NPC]],giverId=7907,ender=[[Wynd Nightchaser]],ender_loc=[[Wynd Cazanoche]],enderType=[[NPC]],enderId=11079,rewardNextId=5244,poiX=7095,poiY=-4007,wowhead=[[https://www.wowhead.com/wotlk/quest=5250]],image=[[assets/images/quests/placeholder.png]],desc=[[In Winterspring, to the north of Felwood, there are many ancient elven ruins. It's a harsh land, but it holds many secrets and places to explore. My studies here keep me so busy that I have not had the opportunity to travel to Winterspring for some time. But there's no reason why you shouldn't travel there and study the ruins. While you're there, look for Wynd Nightchaser. He spends most of his time in Starfall and he knows a lot about the area. Tell him that you are a student of mine...]],logDesc=[[Find Starfall in Winterspring and speak with Wynd Nightchaser.]]}
DB[5251]={id=5251,zoneId=2017,name=[[The Archivist]],name_loc=[[El archivista]],level=60,minLevel=55,giver=[[Duke Nicholas Zverenhoff]],giver_loc=[[Duque Nicholas Zverenhoff]],giverType=[[NPC]],giverId=11039,ender=[[Duke Nicholas Zverenhoff]],ender_loc=[[Duque Nicholas Zverenhoff]],enderType=[[NPC]],enderId=11039,poiX=2256,poiY=-5338,wowhead=[[https://www.wowhead.com/wotlk/quest=5251]],image=[[assets/images/quests/placeholder.png]],desc=[[Anything taken to an extreme is hazardous to our world, $N. Take for example, the Scarlet Crusade. Do you believe that their blind zealotry serves a greater good? How many innocents have they destroyed in the name of the Light? Blasphemers, one and all! One in particular interests me, though; the Archivist Galford of Stratholme: A man that watches over the Crusade's most valued documents. Destroy him and burn down his archives! Should you succeed, return to me and be rewarded.]],logDesc=[[Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.]]}
DB[5252]={id=5252,zoneId=618,name=[[Remorseful Highborne]],name_loc=[[Altonato arrepentido]],level=58,minLevel=53,giver=[[Remorseful Highborne]],giver_loc=[[Altonato arrepentido]],giverType=[[NPC]],giverId=10684,ender=[[Wynd Nightchaser]],ender_loc=[[Wynd Cazanoche]],enderType=[[NPC]],enderId=11079,prevId=5248,rewardNextId=5253,poiX=7095,poiY=-4007,wowhead=[[https://www.wowhead.com/wotlk/quest=5252]],image=[[assets/images/quests/placeholder.png]],desc=[[The... the crystal... The highborne here are clouded by their own misssery... I am sorrrrrowful, but I realize the errorrrr of what happened so long ago. Even though there is no waaaay to change the past, I am now at peacccce knowing that you have recovered the crystal of Zin-Malor... Youuu must return it... It muuuussst be returrrned.]],logDesc=[[Speak with Wynd Nightchaser in Starfall Village, and ask about the proper place for the Crystal of Zin-Malor.]]}
DB[5253]={id=5253,zoneId=618,name=[[The Crystal of Zin-Malor]],name_loc=[[El cristal de Zin-Malor]],level=58,minLevel=53,giver=[[Wynd Nightchaser]],giver_loc=[[Wynd Cazanoche]],giverType=[[NPC]],giverId=11079,ender=[[Arch Druid Fandral Staghelm]],ender_loc=[[Archidruida Fandral Corzocelada]],enderType=[[NPC]],enderId=3516,prevId=5252,poiX=10175,poiY=2568,wowhead=[[https://www.wowhead.com/wotlk/quest=5253]],image=[[assets/images/quests/placeholder.png]],desc=[[Quite impressive, $N. The crystal of Zin-Malor can never be returned to the temple which, as you know, lies in ruin. But I believe that your effort to undo the evil of the past should not go unrewarded. Seek out Arch Druid Fandral Staghelm in Darnassus, and bring the crystal to him, $N. It should be in the hands of those that will not abuse its power. From the looks of it, only a handful of the strongest magic users would be able to control such a power.]],logDesc=[[Deliver the Crystal of Zin-Malor to Arch Druid Fandral Staghelm in Darnassus.]],choiceRewards={{id=15791,qty=1},{id=15792,qty=1},{id=15795,qty=1}}}
DB[5261]={id=5261,zoneId=9,name=[[Eagan Peltskinner]],name_loc=[[Eagan Desollapelambres]],level=2,minLevel=1,giver=[[Deputy Willem]],giver_loc=[[Ayudante de alguacil Willem]],giverType=[[NPC]],giverId=823,ender=[[Eagan Peltskinner]],ender_loc=[[Eagan Desollapelambres]],enderType=[[NPC]],enderId=196,prevId=783,rewardNextId=33,poiX=-8869,poiY=-163,wowhead=[[https://www.wowhead.com/wotlk/quest=5261]],image=[[assets/images/quests/placeholder.png]],desc=[[Eagan Peltskinner is looking for someone to hunt diseased wolves for him.  That's good news, because we're seeing a lot more diseased wolves in Northshire Valley lately. If you're interested then speak with Eagan.  He's around the side of the abbey, to the left.]],logDesc=[[Speak with Eagan Peltskinner.]]}
DB[5262]={id=5262,zoneId=2017,name=[[The Truth Comes Crashing Down]],name_loc=[[La verdad cae del cielo]],level=60,minLevel=55,giverType=[[NPC]],ender=[[Duke Nicholas Zverenhoff]],ender_loc=[[Duque Nicholas Zverenhoff]],enderType=[[NPC]],enderId=11039,prevId=5251,rewardNextId=5263,poiX=3416,poiY=-3045,wowhead=[[https://www.wowhead.com/wotlk/quest=5262]],image=[[assets/images/quests/placeholder.png]],desc=[[You try and gather your thoughts as the dust settles across the chamber. You go over the events that just transpired and still cannot comprehend the gravity of the situation. The Grand Crusader of the Scarlet Crusade a demon? And not just any demon but brother to Varimathras, arch lord of the Undercity? You carefully stow the severed head of the dreadlord into your pack. Surely, none would believe the tale you would tell without proof. Duke Nicholas Zverenhoff must be told at once!]],logDesc=[[Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.]]}
DB[5263]={id=5263,zoneId=2017,name=[[Above and Beyond]],name_loc=[[Por encima y más allá]],level=60,minLevel=55,giver=[[Duke Nicholas Zverenhoff]],giver_loc=[[Duque Nicholas Zverenhoff]],giverType=[[NPC]],giverId=11039,ender=[[Duke Nicholas Zverenhoff]],ender_loc=[[Duque Nicholas Zverenhoff]],enderType=[[NPC]],enderId=11039,prevId=5262,poiX=2256,poiY=-5338,wowhead=[[https://www.wowhead.com/wotlk/quest=5263]],image=[[assets/images/quests/placeholder.png]],desc=[[You display a natural aptitude for destruction and you follow orders. It is rare to see the two coexist. I am beginning to think that you may make an excellent vehicle of divine justice. <Zverenhoff clasps his hands together in front of his face.> Kel'Thuzad's errand boy rules over Stratholme. Prove to me that you are a champion - my champion. Destroy Baron Rivendare and return to me with his head.  ]],logDesc=[[Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff. ]]}
DB[5264]={id=5264,zoneId=139,name=[[Lord Maxwell Tyrosus]],name_loc=[[Lord Maxwell Neófitus]],level=60,minLevel=55,giver=[[Duke Nicholas Zverenhoff]],giver_loc=[[Duque Nicholas Zverenhoff]],giverType=[[NPC]],giverId=11039,ender=[[Lord Maxwell Tyrosus]],ender_loc=[[Lord Maxwell Neófitus]],enderType=[[NPC]],enderId=11034,prevId=5263,rewardNextId=5265,poiX=2304,poiY=-5349,wowhead=[[https://www.wowhead.com/wotlk/quest=5264]],image=[[assets/images/quests/placeholder.png]],desc=[[I am about to bestow a great honor upon you, $N. Lord Maxwell wishes to reward you for your service to the Argent Dawn! It has been years since Maxwell has granted audience to outsiders. ]],logDesc=[[Speak with Lord Maxwell Tyrosus. He is inside the church.]]}
DB[5265]={id=5265,zoneId=139,name=[[The Argent Hold]],name_loc=[[El Bastión Argenta]],level=60,minLevel=55,giver=[[Lord Maxwell Tyrosus]],giver_loc=[[Lord Maxwell Neófitus]],giverType=[[NPC]],giverId=11034,ender=[[The Argent Hold]],ender_loc=[[Bastión Argenta]],enderType=[[GO]],enderId=176317,prevId=5264,poiX=2304,poiY=-5352,wowhead=[[https://www.wowhead.com/wotlk/quest=5265]],image=[[assets/images/quests/placeholder.png]],desc=[[Through the years the Argent Hold has remained locked. None have been worthy to reach inside and take from it the power of the Argent Dawn - until today. The Argent Hold is now open to you, $N.]],logDesc=[[Open the Argent Hold and claim your reward.]],choiceRewards={{id=13246,qty=1},{id=13243,qty=1},{id=13249,qty=1}}}
DB[5281]={id=5281,zoneId=139,name=[[The Restless Souls]],name_loc=[[Espíritus inquietos]],level=60,minLevel=55,giver=[[Caretaker Alen]],giver_loc=[[Custodio Alen]],giverType=[[NPC]],giverId=11038,ender=[[Egan]],enderType=[[NPC]],enderId=11140,rewardNextId=5282,poiX=2929,poiY=-2745,wowhead=[[https://www.wowhead.com/wotlk/quest=5281]],image=[[assets/images/quests/placeholder.png]],desc=[[There are those that died tragically in the fall of Stratholme. Many took their own lives, opting to hurl themselves into the myriad flames of the smoldering city rather than become one of the Scourge. They now walk the streets of Stratholme as restless spirits. We must aid them, $N! I have an associate named Egan who has been doing miraculous work with ghosts and souls. Seek him out. He walks the eastern Plaguelands, near Stratholme, testing his innovations.]],logDesc=[[Find Egan. You only know that he was last seen around Stratholme.]]}
DB[5282]={id=5282,zoneId=2017,name=[[The Restless Souls]],name_loc=[[Espíritus inquietos]],level=60,minLevel=55,giver=[[Egan]],giverType=[[NPC]],giverId=11140,ender=[[Egan]],enderType=[[NPC]],enderId=11140,prevId=5281,poiX=2929,poiY=-2745,wowhead=[[https://www.wowhead.com/wotlk/quest=5282]],image=[[assets/images/quests/placeholder.png]],desc=[[I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done. I am, however, no zealot. There are those, like the Scarlet Crusade, who would sooner destroy the innocent undead than lend them even an ounce of compassion. Which brings me to this: My blaster. It will unchain the tortured souls from Stratholme. Use it on the ghosts that haunt the ransacked streets. Free their souls.]],logDesc=[[Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs! Free 15 Restless Souls and return to Egan.]],rewards={{id=13315,qty=1}}}
DB[5283]={id=5283,name=[[The Art of the Armorsmith]],name_loc=[[El arte del forjador de armaduras]],level=40,minLevel=40,giver=[[Grumnus Steelshaper]],giver_loc=[[Grumnus Forjacero]],giverType=[[NPC]],giverId=5164,ender=[[Grumnus Steelshaper]],ender_loc=[[Grumnus Forjacero]],enderType=[[NPC]],enderId=5164,exGroup=5283,poiX=-4795,poiY=-1109,wowhead=[[https://www.wowhead.com/wotlk/quest=5283]],image=[[assets/images/quests/placeholder.png]],desc=[[So ye made the smart decision. There ain't no love lost betwixt me an old Ironus here. That good for nothing toy maker knows who the true craftsmen round here be. The truly great wars are won with a good defense. When it be go time, no offense is gonna be helping ye out. Right, so let's get to work. All ye need to do is show me that ye've got some raw talent. After that, I'll yank whatever impurities be left in ye and mold ye into an armorsmith. Ye do know how to make ornate mithril, don't ye?]],logDesc=[[To become an Armorsmith, you must make the following items and return them to Grumnus: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate.]]}
DB[5284]={id=5284,name=[[The Way of the Weaponsmith]],name_loc=[[El arte del forjador de armas]],level=40,minLevel=40,giver=[[Ironus Coldsteel]],giver_loc=[[Ironus Acero Frío]],giverType=[[NPC]],giverId=11146,ender=[[Ironus Coldsteel]],ender_loc=[[Ironus Acero Frío]],enderType=[[NPC]],enderId=11146,exGroup=5283,poiX=-4799,poiY=-1111,wowhead=[[https://www.wowhead.com/wotlk/quest=5284]],image=[[assets/images/quests/placeholder.png]],desc=[[As a weaponsmith you'll find that more often than not, heroes and adventurers will be coming to you for gear. While the workload can be unbearable at times, the riches more than make up for the back strain and ash lung. Oh yes, $N, weaponsmiths are the ones with all the gold! If you wish to join our ranks, you'll need to show me that you can make me a silver or two - I mean, show me that you've got what it takes to be the go to $g guy:girl; when people need superior quality weapons. Get to work!]],logDesc=[[To become a Weaponsmith, you must make the following items and return them to Ironus: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces. ]]}
DB[5301]={id=5301,name=[[The Art of the Armorsmith]],name_loc=[[El arte del forjador de armaduras]],level=40,minLevel=40,giver=[[Okothos Ironrager]],giver_loc=[[Okothos Ira de Hierro]],giverType=[[NPC]],giverId=11177,ender=[[Okothos Ironrager]],ender_loc=[[Okothos Ira de Hierro]],enderType=[[NPC]],enderId=11177,exGroup=5301,poiX=2049,poiY=-4800,wowhead=[[https://www.wowhead.com/wotlk/quest=5301]],image=[[assets/images/quests/placeholder.png]],desc=[[Satisfaction. It is what I draw from the hammer and the anvil. To see a proud Horde warrior protected under my steel reminds me of what it is to be alive. It is an addiction that I dare never give up, $N. I can not grant you this satisfaction, merely set you upon the path. As with all of life's endeavors, the path of the armorsmith is a journey. If you wish to be one of the select few, you need only to ask and I shall train, but, a task you must first complete.]],logDesc=[[To become an armorsmith, you must make the following items and return them to Okothos: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate.]]}
DB[5302]={id=5302,name=[[The Way of the Weaponsmith]],name_loc=[[El arte del forjador de armas]],level=40,minLevel=40,giver=[[Borgosh Corebender]],giver_loc=[[Borgosh Ramagma]],giverType=[[NPC]],giverId=11178,ender=[[Borgosh Corebender]],ender_loc=[[Borgosh Ramagma]],enderType=[[NPC]],enderId=11178,exGroup=5301,poiX=2052,poiY=-4794,wowhead=[[https://www.wowhead.com/wotlk/quest=5302]],image=[[assets/images/quests/placeholder.png]],desc=[[One day, I will create a legendary hammer. A hammer fit for a Warchief! It is my life's work, $N. My passion. I recognize that you have the potential to be among us, one of us - a weaponsmith. I am the one that can help you harness that potential. A simple task is all that you must complete. Simple for one of your exceptional skill.]],logDesc=[[To become a Weaponsmith, you must make the following items and return them to Borgosh: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces. ]]}
DB[5305]={id=5305,name=[[Sweet Serenity]],name_loc=[[Dulce serenidad]],level=60,minLevel=50,giver=[[Lilith the Lithe]],giver_loc=[[Lilith la Ágil]],giverType=[[NPC]],giverId=11191,ender=[[Lilith the Lithe]],ender_loc=[[Lilith la Ágil]],enderType=[[NPC]],enderId=11191,poiX=6776,poiY=-4671,wowhead=[[https://www.wowhead.com/wotlk/quest=5305]],image=[[assets/images/quests/placeholder.png]],desc=[[Within the confines of the Scarlet Bastion lies sweet Serenity. The Crimson Hammersmith guards the recipe with his life. Defeat him and bring me his apron. For that, I shall reward you with the knowledge required to create an enchanted battlehammer!]],logDesc=[[Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith. ]],rewards={{id=12824,qty=1}}}
DB[5306]={id=5306,name=[[Snakestone of the Shadow Huntress]],name_loc=[[Piedra culebra de la cazadora de las Sombras]],level=60,minLevel=50,giver=[[Kilram]],giverType=[[NPC]],giverId=11192,ender=[[Kilram]],enderType=[[NPC]],enderId=11192,poiX=6779,poiY=-4669,wowhead=[[https://www.wowhead.com/wotlk/quest=5306]],image=[[assets/images/quests/placeholder.png]],desc=[[Don't let her beauty fool you, $c. The shadow huntress, Vosh'gajin is deadly and deranged. <Kilram points to the scar on his face.> Aye, she gave me that - a love tap, she called it. The time for vengeance has finally come. You can find Vosh'gajin in Blackrock Spire. Slay her and return to me with her snakestone. Do this and I will teach you the secret to crafting Dawn's Edge!]],logDesc=[[Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram.]],rewards={{id=12821,qty=1}}}
DB[5307]={id=5307,name=[[Corruption]],name_loc=[[Corrupción]],level=60,minLevel=50,giver=[[Seril Scourgebane]],giver_loc=[[Seril Finiquiplaga]],giverType=[[NPC]],giverId=11193,ender=[[Seril Scourgebane]],ender_loc=[[Seril Finiquiplaga]],enderType=[[NPC]],enderId=11193,poiX=6773,poiY=-4671,wowhead=[[https://www.wowhead.com/wotlk/quest=5307]],image=[[assets/images/quests/placeholder.png]],desc=[[If I am short with you, it is for a reason. The plans for the creation of the great blade, Corruption, have been stolen by the Black Guard: Elite skeletal units of Baron Rivendare. Yes, Baron Rivendare of Stratholme. The Black Guard swordsmith now guards those plans with his... undeath. Slay him and return proof of this deed and I shall grant you the knowledge required to create a blazing rapier!]],logDesc=[[Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane.]],rewards={{id=12825,qty=1}}}
DB[5321]={id=5321,zoneId=148,name=[[The Sleeper Has Awakened]],name_loc=[[El despertar]],level=20,minLevel=17,giver=[[Kerlonian Evershade]],giver_loc=[[Kerlonian Semprumbrío]],giverType=[[NPC]],giverId=11218,ender=[[Liladris Moonriver]],ender_loc=[[Liladris Rioluna]],enderType=[[NPC]],enderId=11219,poiX=5001,poiY=34,wowhead=[[https://www.wowhead.com/wotlk/quest=5321]],image=[[assets/images/quests/placeholder.png]],desc=[[I was on my way to Maestra's Post to meet Liladris Moonriver, but I decided to stop here and take a short nap. Ever since I awoke from the emerald dream, I have been so sleepy... <yawn> Would you mind showing me the way? I understand that Maestra's Post is south of here, along the road in Ashenvale. It can be dangerous, so I hope you have some friends that will join us. Lastly, I may fall asleep so if you ever need to wake me, please use my horn. You'll find it in the chest here.]],logDesc=[[Escort Kerlonian Evershade to Liladris Moonriver at Maestra's Post in Ashenvale.]],choiceRewards={{id=15205,qty=1},{id=15206,qty=1},{id=15207,qty=1}}}
DB[5341]={id=5341,zoneId=2057,name=[[Barov Family Fortune]],name_loc=[[La fortuna de la familia Barov]],level=60,minLevel=52,giver=[[Alexi Barov]],giver_loc=[[Alexi Barov]],giverType=[[NPC]],giverId=11022,ender=[[Alexi Barov]],ender_loc=[[Alexi Barov]],enderType=[[NPC]],enderId=11022,rewardNextId=5342,poiX=1680,poiY=-720,wowhead=[[https://www.wowhead.com/wotlk/quest=5341]],image=[[assets/images/quests/placeholder.png]],desc=[[Within the Scholomance lays the Barov family fortune. I, Alexi Barov, am one of the last two remaining heirs of the house Barov. My brother, Weldon, is the other. Weldon, the miserable coward, fled during the war and thus retained his worthless existence as a human. He now searches for the deeds so that he may claim the fortune for his own. Recover the deeds before my brother does and I shall make you wealthy beyond your wildest dreams!]],logDesc=[[Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.]]}
DB[5342]={id=5342,zoneId=28,name=[[The Last Barov]],name_loc=[[El último de los Barov]],level=60,minLevel=52,giver=[[Alexi Barov]],giver_loc=[[Alexi Barov]],giverType=[[NPC]],giverId=11022,ender=[[Alexi Barov]],ender_loc=[[Alexi Barov]],enderType=[[NPC]],enderId=11022,prevId=5341,poiX=966,poiY=-1452,wowhead=[[https://www.wowhead.com/wotlk/quest=5342]],image=[[assets/images/quests/placeholder.png]],desc=[[Naturally, with my brother still alive, there may be some contention as to the primary beneficiary of the family's fortune. This cannot be. A low down guttersnipe like you isn't above a little cold-blooded murder, I hope. It's a simple task and one that I expect you will complete; that is, if you wish to claim your reward. Weldon sits under Alliance protection at Chillwind Camp, to the east. Slay him, return his head. <Alexi yawns.> Hurry along now.]],logDesc=[[Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov. Be warned, Weldon will probably be well protected by Alliance scum.]],rewards={{id=14022,qty=1}}}
DB[5343]={id=5343,zoneId=2057,name=[[Barov Family Fortune]],name_loc=[[La fortuna de la familia Barov]],level=60,minLevel=52,giver=[[Weldon Barov]],giver_loc=[[Weldon Barov]],giverType=[[NPC]],giverId=11023,ender=[[Weldon Barov]],ender_loc=[[Weldon Barov]],enderType=[[NPC]],enderId=11023,rewardNextId=5344,poiX=966,poiY=-1452,wowhead=[[https://www.wowhead.com/wotlk/quest=5343]],image=[[assets/images/quests/placeholder.png]],desc=[[My dear brother Alexi. What a fool I was to spare his life. I looked into the face of the enemy, one of the undead, and let him live. <Weldon spits.> He now searches for MY inheritance. This simply cannot happen. Find my family's deeds before that vile retch gets his boney hands upon them and I shall reward you with vast riches. They lay in the ruins of the Scholomance. Make haste!]],logDesc=[[Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task.]]}
DB[5344]={id=5344,zoneId=28,name=[[The Last Barov]],name_loc=[[El último de los Barov]],level=60,minLevel=52,giver=[[Weldon Barov]],giver_loc=[[Weldon Barov]],giverType=[[NPC]],giverId=11023,ender=[[Weldon Barov]],ender_loc=[[Weldon Barov]],enderType=[[NPC]],enderId=11023,prevId=5343,poiX=1680,poiY=-720,wowhead=[[https://www.wowhead.com/wotlk/quest=5344]],image=[[assets/images/quests/placeholder.png]],desc=[[With the deeds recovered, there is but one thing left to do. Alexi must be killed. With him dead, I need not ever worry about an unscrupulous gang of mercenaries seeking my head. It's a simple task. Alexi hides under the protection of the Horde - at the Bulwark. No, I do not expect you to just walk up and kill him, I want his head! How you get it... well, that part is up to you. That type of behavior is below one of my noble upbringing.]],logDesc=[[Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov. Be warned, Alexi will probably be well protected by Horde filth.]],rewards={{id=14023,qty=1}}}
DB[5361]={id=5361,zoneId=400,name=[[Family Tree]],name_loc=[[Árbol genealógico]],level=35,minLevel=32,giver=[[Cliffwatcher Longhorn]],giver_loc=[[Vigiarrisco Cuerno Largo]],giverType=[[NPC]],giverId=10537,ender=[[Nataka Longhorn]],ender_loc=[[Nataka Cuerno Largo]],enderType=[[NPC]],enderId=11259,poiX=-1221,poiY=1742,wowhead=[[https://www.wowhead.com/wotlk/quest=5361]],image=[[assets/images/quests/placeholder.png]],desc=[[My brother Nataka is stationed at Ghost Walker Post over in Desolace. I'd like to ask you... could you give this report to him for me? A year has passed since the last time I wrote, there has been unusual centaur activity since then and he should be informed. Journey to Stonetalon Mountain north of the Crossroads, and then head west into Charred Vale. From there, head south into Desolace; there you will find a road going south to Ghost Walker Post.]],logDesc=[[Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace.]]}
DB[5381]={id=5381,zoneId=405,name=[[Hand of Iruxos]],name_loc=[[La Mano de Iruxos]],level=38,minLevel=32,giver=[[Taiga Wisemane]],giver_loc=[[Taiga Crin Sabia]],giverType=[[NPC]],giverId=11624,ender=[[Taiga Wisemane]],ender_loc=[[Taiga Crin Sabia]],enderType=[[NPC]],enderId=11624,rewardNextId=5581,poiX=-348,poiY=1763,wowhead=[[https://www.wowhead.com/wotlk/quest=5381]],image=[[assets/images/quests/placeholder.png]],desc=[[The Burning Blade possesses the Demon Box. Within it lies the powerful Hand of Iruxos. The Burning Blade uses it to open demonic portals at Mannoroc Coven. We must stop the tide of demons entering our world, $n! Use this demon pick on the red crystal in Thunder Axe Fortress to gain access to the Demon Box. ]],logDesc=[[Retrieve the Demon Box from Thunder Axe Fortress, and return it, along with the Demon Pick to Taiga Wisemane in Shadowprey Village. ]]}
DB[5382]={id=5382,zoneId=2057,name=[[Doctor Theolen Krastinov, the Butcher]],name_loc=[[Doctor Theolen Krastinov, el Carnicero]],level=60,minLevel=55,giver=[[Eva Sarkhoff]],giverType=[[NPC]],giverId=11216,ender=[[Eva Sarkhoff]],enderType=[[NPC]],enderId=11216,rewardNextId=5515,poiX=1254,poiY=-2603,wowhead=[[https://www.wowhead.com/wotlk/quest=5382]],image=[[assets/images/quests/placeholder.png]],desc=[[Krastinov is responsible for the deaths of thousands. He must be punished, justice must be meted out. Find him and exact upon him the agony he has inflicted upon countless innocents. Once he is destroyed, burn our remains. Turn them to ashes, $N.]],logDesc=[[Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete. ]]}
DB[5384]={id=5384,zoneId=2057,name=[[Kirtonos the Herald]],name_loc=[[Kirtonos el Heraldo]],level=60,minLevel=55,giver=[[Eva Sarkhoff]],giverType=[[NPC]],giverId=11216,ender=[[Eva Sarkhoff]],enderType=[[NPC]],enderId=11216,prevId=5515,poiX=1254,poiY=-2603,wowhead=[[https://www.wowhead.com/wotlk/quest=5384]],image=[[assets/images/quests/placeholder.png]],desc=[[This is it, $N. <Eva points to the vial inside the bag.> The blood of innocents. The purest blood, used to appease Krastinov's master. It is with this blood that Kirtonos may be summoned. It is with this blood, then, that Kirtonos must be destroyed. Take the blood to the porch. Place it upon the brazier. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him. Should you succeed, you will earn more than just our gratitude.]],logDesc=[[Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul. Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff. ]],rewards={{id=13544,qty=1}},choiceRewards={{id=15805,qty=1},{id=15806,qty=1}}}
DB[5385]={id=5385,zoneId=361,name=[[The Remains of Trey Lightforge]],name_loc=[[Los restos de Trey Forjaluz]],level=57,minLevel=49,giver=[[Remains of Trey Lightforge]],giver_loc=[[Restos de Trey Forjaluz]],giverType=[[NPC]],giverId=11020,ender=[[Jessir Moonbow]],ender_loc=[[Jessir Arcolunar]],enderType=[[NPC]],enderId=11019,prevId=5204,poiX=3990,poiY=-1311,wowhead=[[https://www.wowhead.com/wotlk/quest=5385]],image=[[assets/images/quests/placeholder.png]],desc=[[You pick up the sack carefully and prepare to make your way back to Jessir Moonbow on the border of Felwood and Ashenvale. Hopefully the paladin will be given the proper respects once you've passed his remains on to his friends.]],logDesc=[[Return the Remains of Trey Lightforge to Jessir Moonbow in Felwood.]],choiceRewards={{id=15706,qty=1},{id=15705,qty=1}}}
DB[5386]={id=5386,zoneId=405,name=[[Catch of the Day]],name_loc=[[La pesca del día]],level=37,minLevel=32,giver=[[Nataka Longhorn]],giver_loc=[[Nataka Cuerno Largo]],giverType=[[NPC]],giverId=11259,ender=[[Nataka Longhorn]],ender_loc=[[Nataka Cuerno Largo]],enderType=[[NPC]],enderId=11259,poiX=-1221,poiY=1742,wowhead=[[https://www.wowhead.com/wotlk/quest=5386]],image=[[assets/images/quests/placeholder.png]],desc=[[The smell of cooked fish has long been missing here at Ghost Walker Post. The trolls at Shadowprey Village are the best at catching fish... but alas, with all the centaur activities I have little time to make a journey to the trolls. Hrm... Do me a favor and journey to Shadowprey Village. Talk to the local fisherman Jinar'Zillen and bring me back my favorite, Bloodbelly fish. The road south of here will take you west to the troll village.]],logDesc=[[Talk to Jinar'Zillen at Shadowprey Village, and then bring Nataka Longhorn 2 Bloodbelly fish.]],choiceRewards={{id=3858,qty=3},{id=4304,qty=5},{id=4338,qty=5}}}
DB[5401]={id=5401,zoneId=28,name=[[Argent Dawn Commission]],name_loc=[[Comisión de El Alba Argenta]],level=55,minLevel=50,giver=[[Argent Officer Pureheart]],giver_loc=[[Oficial Argenta Purocorazón]],giverType=[[NPC]],giverId=10840,ender=[[Argent Officer Pureheart]],ender_loc=[[Oficial Argenta Purocorazón]],enderType=[[NPC]],enderId=10840,poiX=972,poiY=-1431,wowhead=[[https://www.wowhead.com/wotlk/quest=5401]],image=[[assets/images/quests/placeholder.png]],rewards={{id=12846,qty=1}}}
DB[5402]={id=5402,zoneId=28,name=[[Minion's Scourgestones]],name_loc=[[Piedras de la Plaga del esbirro]],level=55,minLevel=50,giver=[[Argent Officer Garush]],giver_loc=[[Oficial Argenta Garush]],giverType=[[NPC]],giverId=10839,ender=[[Argent Officer Garush]],ender_loc=[[Oficial Argenta Garush]],enderType=[[NPC]],enderId=10839,poiX=972,poiY=-1431,wowhead=[[https://www.wowhead.com/wotlk/quest=5402]],image=[[assets/images/quests/placeholder.png]],rewards={{id=12844,qty=1}}}
