DB[5513]={id=5513,zoneId=139,name=[[Mantles of the Dawn]],name_loc=[[Mantos del Alba]],level=60,minLevel=55,giver=[[Quartermaster Miranda Breechlock]],giver_loc=[[Intendente Cerrobrecha]],giverType=[[NPC]],giverId=11536,ender=[[Quartermaster Miranda Breechlock]],ender_loc=[[Intendente Cerrobrecha]],enderType=[[NPC]],enderId=11536,exGroup=5504,poiX=2251,poiY=-5345,wowhead=[[https://www.wowhead.com/wotlk/quest=5513]],image=[[assets/images/quests/placeholder.png]],desc=[[Your service to the Argent Dawn is to be commended, $N.  You are truly revered amongst us.  I have been authorized to make available for you to purchase one of the Dawn's most valued items - our magic resistance mantles. Application of a mantle to your existing shoulder piece will enhance your resistance to the powers of magic in one of five potential ways.  As a sign of continued dedication to our cause, I ask for no less than ten of our valor tokens in exchange for access to these mantles.]],logDesc=[[Bring 10 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands.]]}
DB[5514]={id=5514,zoneId=28,name=[[Mold Rhymes With...]],name_loc=[[Molde rima con... ¿oro?]],level=57,minLevel=55,giver=[[Apothecary Dithers]],giver_loc=[[Boticario Dithers]],giverType=[[NPC]],giverId=11057,ender=[[Krinkle Goodsteel]],ender_loc=[[Krinkle Buenacero]],enderType=[[NPC]],enderId=5411,prevId=964,rewardNextId=5802,poiX=-7200,poiY=-3770,wowhead=[[https://www.wowhead.com/wotlk/quest=5514]],image=[[assets/images/quests/placeholder.png]],desc=[[The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge. I'm an apothecary, not a banker.  If I had gold lying around, I certainly wouldn't be here. I guess I said the quiet part out loud again.  Oops. Gadgetzan awaits you!  Good luck!]],logDesc=[[Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.]]}
DB[5515]={id=5515,zoneId=2057,name=[[Krastinov's Bag of Horrors]],name_loc=[[Bolsa de los horrores de Krastinov]],level=60,minLevel=55,giver=[[Eva Sarkhoff]],giverType=[[NPC]],giverId=11216,ender=[[Eva Sarkhoff]],enderType=[[NPC]],enderId=11216,prevId=5382,rewardNextId=5384,poiX=1254,poiY=-2603,wowhead=[[https://www.wowhead.com/wotlk/quest=5515]],image=[[assets/images/quests/placeholder.png]],desc=[[A great weight has been lifted from our hearts, $N, but your task is not yet complete. Krastinov's master, Kirtonos, still lives. Before you may face Kirtonos, however, you must first secure a method in which to summon him. It is said that Jandice Barov stewards the blood of innocents from Krastinov to Kirtonos. Find her in the sunken catacombs of Scholomance and strike her down. Bring back any clues that you may find.]],logDesc=[[Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.]]}
DB[5517]={id=5517,zoneId=139,name=[[Chromatic Mantle of the Dawn]],name_loc=[[Manto del Alba cromático]],level=60,minLevel=55,giver=[[Quartermaster Miranda Breechlock]],giver_loc=[[Intendente Cerrobrecha]],giverType=[[NPC]],giverId=11536,ender=[[Quartermaster Miranda Breechlock]],ender_loc=[[Intendente Cerrobrecha]],enderType=[[NPC]],enderId=11536,exGroup=5517,poiX=2251,poiY=-5345,wowhead=[[https://www.wowhead.com/wotlk/quest=5517]],image=[[assets/images/quests/placeholder.png]],desc=[[$G Brother : Sister; $N - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes! Bring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.]],logDesc=[[Bring 25 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands.]],rewards={{id=18182,qty=1}}}
DB[5518]={id=5518,zoneId=2557,name=[[The Gordok Ogre Suit]],name_loc=[[El disfraz de ogro Gordok]],level=60,minLevel=56,giver=[[Knot Thimblejack]],giver_loc=[[Knot Llavededo]],giverType=[[NPC]],giverId=14338,ender=[[Knot Thimblejack]],ender_loc=[[Knot Llavededo]],enderType=[[NPC]],enderId=14338,poiX=581,poiY=523,wowhead=[[https://www.wowhead.com/wotlk/quest=5518]],image=[[assets/images/quests/placeholder.png]],desc=[[If you're going to fight the king of this dump - and I think that's what you're bound to do - then you're going to need to get by Captain Kromcrush.  Now, you can get by him by killing him, sure.  You might actually want to leave him alive. How, you ask?  Since I've been here, I think I know how to make an ogre suit that will last just long enough to fool these bozos.  The only problem is stability - ten minutes tops.  Bring me what I need, and I'll make you one.  I'm not going anywhere...]],logDesc=[[Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack.  He is currently chained inside the Gordok wing of Dire Maul.]],rewards={{id=18258,qty=1}}}
DB[5519]={id=5519,zoneId=2557,name=[[The Gordok Ogre Suit]],name_loc=[[El disfraz de ogro Gordok]],level=60,minLevel=56,giver=[[Knot Thimblejack]],giver_loc=[[Knot Llavededo]],giverType=[[NPC]],giverId=14338,ender=[[Knot Thimblejack]],ender_loc=[[Knot Llavededo]],enderType=[[NPC]],enderId=14338,prevId=5518,poiX=581,poiY=523,wowhead=[[https://www.wowhead.com/wotlk/quest=5519]],image=[[assets/images/quests/placeholder.png]],rewards={{id=18258,qty=1}}}
DB[5521]={id=5521,zoneId=28,name=[[Chromatic Mantle of the Dawn]],name_loc=[[Manto del Alba cromático]],level=60,minLevel=55,giver=[[Argent Quartermaster Lightspark]],giver_loc=[[Intendente Argenta Chispillo]],giverType=[[NPC]],giverId=10857,ender=[[Argent Quartermaster Lightspark]],ender_loc=[[Intendente Argenta Chispillo]],enderType=[[NPC]],enderId=10857,exGroup=5517,poiX=967,poiY=-1425,wowhead=[[https://www.wowhead.com/wotlk/quest=5521]],image=[[assets/images/quests/placeholder.png]],desc=[[$G Brother : Sister; $N - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes! Bring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.]],logDesc=[[Bring 25 Argent Dawn Valor Tokens to Quartermaster Lightspark at Chillwind Camp, Western Plaguelands.]],rewards={{id=18182,qty=1}}}
DB[5522]={id=5522,zoneId=46,name=[[Leonid Barthalomew]],name_loc=[[Leonid Barthalomew]],level=60,minLevel=57,giver=[[Tinkee Steamboil]],giver_loc=[[Tinkee Vaporio]],giverType=[[NPC]],giverId=10267,ender=[[Leonid Barthalomew the Revered]],ender_loc=[[Leonid Barthalomew el Venerado]],enderType=[[NPC]],enderId=11036,prevId=4734,rewardNextId=5531,poiX=2307,poiY=-5349,wowhead=[[https://www.wowhead.com/wotlk/quest=5522]],image=[[assets/images/quests/placeholder.png]],desc=[[I received a message from my master, Vectus.  Well, the message wasn't really from Vectus...it was from someone named Leonid Barthalomew.  I don't know Leonid, but he knew my master, and no one knows my master unless he allows it. Leonid says Vectus wants the dragon eggs.  He wants you to deliver them to him at the Light's Hope Chapel in the Eastern Plaguelands. That hurts!  Why you?  Doesn't Vectus trust me?  Oh, never mind... just take the eggs and tell Leonid that I did what our master commanded.]],logDesc=[[Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands.]]}
DB[5524]={id=5524,zoneId=28,name=[[Chromatic Mantle of the Dawn]],name_loc=[[Manto del Alba cromático]],level=60,minLevel=55,giver=[[Argent Quartermaster Hasana]],giver_loc=[[Intendente Argenta Hasana]],giverType=[[NPC]],giverId=10856,ender=[[Argent Quartermaster Hasana]],ender_loc=[[Intendente Argenta Hasana]],enderType=[[NPC]],enderId=10856,exGroup=5517,poiX=1785,poiY=-729,wowhead=[[https://www.wowhead.com/wotlk/quest=5524]],image=[[assets/images/quests/placeholder.png]],desc=[[$G Brother : Sister; $N - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes! Bring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.]],logDesc=[[Bring 25 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark, Western Plaguelands.]],rewards={{id=18182,qty=1}}}
DB[5525]={id=5525,zoneId=2557,name=[[Free Knot!]],name_loc=[[¡Libera a Knot!]],level=60,minLevel=56,giver=[[Knot Thimblejack]],giver_loc=[[Knot Llavededo]],giverType=[[NPC]],giverId=14338,ender=[[Knot Thimblejack]],ender_loc=[[Knot Llavededo]],enderType=[[NPC]],enderId=14338,poiX=581,poiY=523,wowhead=[[https://www.wowhead.com/wotlk/quest=5525]],image=[[assets/images/quests/placeholder.png]]}
DB[5526]={id=5526,zoneId=493,name=[[Shards of the Felvine]],name_loc=[[Fragmentos de gangrevid]],level=60,minLevel=56,giver=[[Rabine Saturna]],giverType=[[NPC]],giverId=11801,ender=[[Rabine Saturna]],enderType=[[NPC]],enderId=11801,prevId=5527,poiX=7797,poiY=-2574,wowhead=[[https://www.wowhead.com/wotlk/quest=5526]],image=[[assets/images/quests/placeholder.png]],desc=[[Your knowledge of Eldre'Thalas - Dire Maul - in Feralas will now come into play, $N.  In the eastern part of the ruined city is where Alzzin the Wildshaper has exerted his corrupt dominion.  Go there with all due haste and brave whatever challenges await you. The Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin.  When he falls, capture whatever essence of the Felvine you can.  Seal it in the Reliquary, and bring it to me. Good luck, and Cenarion's speed.]],logDesc=[[Find the Felvine in Dire Maul and acquire a shard from it.  Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper.  Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade.]],choiceRewards={{id=18535,qty=1},{id=18536,qty=1}}}
DB[5527]={id=5527,zoneId=493,name=[[A Reliquary of Purity]],name_loc=[[Un relicario de Pureza]],level=60,minLevel=56,giver=[[Rabine Saturna]],giverType=[[NPC]],giverId=11801,ender=[[Rabine Saturna]],enderType=[[NPC]],enderId=11801,rewardNextId=5526,poiX=7797,poiY=-2574,wowhead=[[https://www.wowhead.com/wotlk/quest=5527]],image=[[assets/images/quests/placeholder.png]],desc=[[The first step is to find a container capable of holding an extremely corruptible substance without the handler suffering ill effects.  There is only one sort device I am aware of that could possibly contain something as vile as the Felvine: a Reliquary of Purity. Deep in the wasteland of Silithus is the remnants of the night elf village known as Southwind.  I know one was there many, many years ago.  If we are to succeed, I need you to scour those ruins in the hopes of reclaiming it.]],logDesc=[[Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village.  If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.]]}
DB[5528]={id=5528,zoneId=2557,name=[[The Gordok Taste Test]],name_loc=[[La cata de los Gordok]],level=60,minLevel=56,giver=[[Stomper Kreeg]],giver_loc=[[Vapuleador Kreeg]],giverType=[[NPC]],giverId=14322,ender=[[Stomper Kreeg]],ender_loc=[[Vapuleador Kreeg]],enderType=[[NPC]],enderId=14322,wowhead=[[https://www.wowhead.com/wotlk/quest=5528]],image=[[assets/images/quests/placeholder.png]],rewards={{id=18269,qty=5},{id=18284,qty=5}}}
DB[5529]={id=5529,zoneId=2057,name=[[Plagued Hatchlings]],name_loc=[[Crías de dragón apestadas]],level=58,minLevel=55,giver=[[Betina Bigglezink]],giver_loc=[[Betina Bigglezink]],giverType=[[NPC]],giverId=11035,ender=[[Betina Bigglezink]],ender_loc=[[Betina Bigglezink]],enderType=[[NPC]],enderId=11035,poiX=2260,poiY=-5339,wowhead=[[https://www.wowhead.com/wotlk/quest=5529]],image=[[assets/images/quests/placeholder.png]],desc=[[The Argent Dawn recently learned that the Scourge are creating their own plagued dragonflight!  We must stop them -- if the Scourge gain a force of dragons they'll sweep across Azeroth unchecked! Their necromancers are breeding plagued dragons at the Scholomance, in the middle of Darrowmere Lake. Go to the Scholomance and kill as many hatchlings as you can... before they get any bigger!]],logDesc=[[Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.]]}
DB[5531]={id=5531,zoneId=2057,name=[[Betina Bigglezink]],name_loc=[[Betina Bigglezink]],level=60,minLevel=57,giver=[[Leonid Barthalomew the Revered]],giver_loc=[[Leonid Barthalomew el Venerado]],giverType=[[NPC]],giverId=11036,ender=[[Betina Bigglezink]],ender_loc=[[Betina Bigglezink]],enderType=[[NPC]],enderId=11035,prevId=5522,rewardNextId=4771,poiX=2260,poiY=-5339,wowhead=[[https://www.wowhead.com/wotlk/quest=5531]],image=[[assets/images/quests/placeholder.png]],desc=[[The eggs you brought were to be used in Scourge experiments to create a plagued dragonflight.  These frozen black dragon eggs would have been invaluable in their studies, and would have assuredly quickened their timetable. Now, it is time we ended their research. Take the frozen eggs to Betina Bigglezink outside.  She is well-learned in science and alchemy, and has produced a weapon we can use against the Scourge.  With your help, we will deal them a heavy blow.]],logDesc=[[Bring the Frozen Eggs to Betina Bigglezink.]]}
DB[5533]={id=5533,zoneId=28,name=[[Scholomance]],name_loc=[[Scholomance]],level=55,minLevel=55,giver=[[Commander Ashlam Valorfist]],giver_loc=[[Comandante Ashlam Puñovalor]],giverType=[[NPC]],giverId=10838,ender=[[Alchemist Arbington]],ender_loc=[[Alquimista Arbington]],enderType=[[NPC]],enderId=11056,prevId=5097,rewardNextId=5537,poiX=965,poiY=-1418,wowhead=[[https://www.wowhead.com/wotlk/quest=5533]],image=[[assets/images/quests/placeholder.png]],desc=[[On the island of Caer Darrow lies Scholomance - a wretched center of Scourge necromancy and evil.  Our enemy dwells within, conducting unspeakable acts of depravity on unwitting victims... at least, we surmise as much.  A door bars the way, and try as we might no entry is to be had without a proper key. Alchemist Arbington is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your worth to me, and now I entrust this task to you.  Speak with him on this matter.]],logDesc=[[Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands.]]}
DB[5534]={id=5534,zoneId=16,name=[[Kim'jael's "Missing" Equipment]],name_loc=[[El equipamiento "perdido" de Kim'jael]],level=53,minLevel=47,giver=[[Kim'jael]],giverType=[[NPC]],giverId=8420,ender=[[Kim'jael]],enderType=[[NPC]],enderId=8420,prevId=3601,poiX=2460,poiY=-6949,wowhead=[[https://www.wowhead.com/wotlk/quest=5534]],image=[[assets/images/quests/placeholder.png]],desc=[[What?! What?! That wasn't good enough for you? You know how expensive those explosives are? They sell for... oh, nevermind. Fine, you want to make some real money? Cause that's how business is done: you prove you're a valuable employee and then you're rewarded adequately after you stick it out some. If you're a "valuable" employee, then hit the Ruins of Eldarath and find me some rune that them Blood elves were lookin' for. The naga apparently have it in their possession.]],logDesc=[[Find Some Rune that the naga have in their possession in the Ruins of Eldarath and return it to Kim'jael in Azshara.]]}
DB[5535]={id=5535,zoneId=16,name=[[Spiritual Unrest]],name_loc=[[Agitación espiritual]],level=47,minLevel=45,giver=[[Loh'atu]],giverType=[[NPC]],giverId=11548,ender=[[Loh'atu]],enderType=[[NPC]],enderId=11548,poiX=3014,poiY=-4187,wowhead=[[https://www.wowhead.com/wotlk/quest=5535]],image=[[assets/images/quests/placeholder.png]],desc=[[Long ago, the Highborne were some of the most powerful students of the arcane the night elves ever produced. The corruption that comes along with such studies caused much harm to night elf society and greatly affected all of Azeroth... as I'm sure you well know. I promised the Sentinels that I would release the spirits from their mortal bonds as I find them. If you would do the same, then I am sure I can reward you some. The spirits haunt the Shadowsong Shrine to the northeast of here.]],logDesc=[[Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara.]]}
DB[5536]={id=5536,zoneId=16,name=[[A Land Filled with Hatred]],name_loc=[[Una tierra llena de odio]],level=47,minLevel=45,giver=[[Loh'atu]],giverType=[[NPC]],giverId=11548,ender=[[Loh'atu]],enderType=[[NPC]],enderId=11548,poiX=3284,poiY=-4355,wowhead=[[https://www.wowhead.com/wotlk/quest=5536]],image=[[assets/images/quests/placeholder.png]],desc=[[The satyr, a disfigured, evil aspect of the night elves, now infect the sacred lands once traveled by Cenarius. I cannot speak for the night elves when it comes to all the atrocities those demonic creatures have committed, but I have sworn an oath to the Earthmother to aid the elves in ridding the land of such a nuisance. I am sure you would prove yourself if you aided me in purging them. Northeast of here, you can find the Haldarr clan. Return to me after you've tested yourself against their power.]],logDesc=[[Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale.]]}
DB[5537]={id=5537,zoneId=28,name=[[Skeletal Fragments]],name_loc=[[Trozos esqueléticos]],level=57,minLevel=55,giver=[[Alchemist Arbington]],giver_loc=[[Alquimista Arbington]],giverType=[[NPC]],giverId=11056,ender=[[Alchemist Arbington]],ender_loc=[[Alquimista Arbington]],enderType=[[NPC]],enderId=11056,prevId=5533,rewardNextId=5538,poiX=965,poiY=-1418,wowhead=[[https://www.wowhead.com/wotlk/quest=5537]],image=[[assets/images/quests/placeholder.png]],desc=[[The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function. First thing's first though, $N.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.]],logDesc=[[Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands.]]}
DB[5538]={id=5538,zoneId=28,name=[[Mold Rhymes With...]],name_loc=[[Molde rima con... ¿oro?]],level=57,minLevel=55,giver=[[Alchemist Arbington]],giver_loc=[[Alquimista Arbington]],giverType=[[NPC]],giverId=11056,ender=[[Krinkle Goodsteel]],ender_loc=[[Krinkle Buenacero]],enderType=[[NPC]],enderId=5411,prevId=5537,rewardNextId=5801,poiX=-7200,poiY=-3770,wowhead=[[https://www.wowhead.com/wotlk/quest=5538]],image=[[assets/images/quests/placeholder.png]],desc=[[The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge. I'm an alchemist, not a banker.  If I had gold lying around, I certainly wouldn't be here. I guess I said the quiet part out loud again.  Oops. Gadgetzan awaits you!  Good luck!]],logDesc=[[Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.]]}
DB[5541]={id=5541,zoneId=1,name=[[Ammo for Rumbleshot]],name_loc=[[Municiones para Estruendo]],level=6,minLevel=5,giver=[[Loslor Rudge]],giver_loc=[[Loslor Rudge]],giverType=[[NPC]],giverId=1694,ender=[[Hegnar Rumbleshot]],ender_loc=[[Hegnar Estruendo]],enderType=[[NPC]],enderId=1243,poiX=-5747,poiY=-371,wowhead=[[https://www.wowhead.com/wotlk/quest=5541]],image=[[assets/images/quests/placeholder.png]],desc=[[Hegnar Rumbleshot sells guns off the road to Anvilmar.  Riflemen and mortar teams spend a lot of time practicing out near his shop, and he's always needing fresh ammunition. But... the last crate of ammo I sent him got lost along the way.  My courier said he was camped near the Grizzled Den when wendigo chased him away... and the fool left Rumbleshot's ammo behind! $N, can you get that ammo and take it to Rumbleshot?  He's been waiting on it and I'm sure he's running low.]],logDesc=[[Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh.]]}
DB[5542]={id=5542,zoneId=139,name=[[Demon Dogs]],name_loc=[[Perros demoníacos]],level=56,minLevel=52,giver=[[Tirion Fordring]],giver_loc=[[Tirion Vadín]],giverType=[[NPC]],giverId=1855,ender=[[Tirion Fordring]],ender_loc=[[Tirion Vadín]],enderType=[[NPC]],enderId=1855,nextId=5742,exGroup=-5542,poiX=1585,poiY=-4651,wowhead=[[https://www.wowhead.com/wotlk/quest=5542]],image=[[assets/images/quests/placeholder.png]],desc=[[If you are going to remain here, I ask only that you earn your keep. We have many nuisances that could use some 'discipline.' You can start with the Plaguehounds and their runts. I cannot offer much in return, but you are guaranteed a warm meal and some conversation should you succeed.]],logDesc=[[Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.]]}
DB[5543]={id=5543,zoneId=139,name=[[Blood Tinged Skies]],name_loc=[[Cielos sangrientos]],level=56,minLevel=52,giver=[[Tirion Fordring]],giver_loc=[[Tirion Vadín]],giverType=[[NPC]],giverId=1855,ender=[[Tirion Fordring]],ender_loc=[[Tirion Vadín]],enderType=[[NPC]],enderId=1855,nextId=5742,exGroup=-5542,poiX=1683,poiY=-3879,wowhead=[[https://www.wowhead.com/wotlk/quest=5543]],image=[[assets/images/quests/placeholder.png]],desc=[[Woe to those that foolishly wander into the Plaguelands. All manner of foulness inhabit these woods - from the fanatical Scarlet Crusade, who will kill any that do not bear the mark of the Crusade, to the murderous Scourge, who only look to bolster their numbers by adding more undead to their ranks. Even the wildlife have been transformed into rapacious, man eating beasts. I ask that you destroy those that would strike from the skies: The Plaguebats.]],logDesc=[[Slay 30 Plaguebats and return to Tirion Fordring.]]}
DB[5544]={id=5544,zoneId=139,name=[[Carrion Grubbage]],name_loc=[[Gusanos carroñeros]],level=56,minLevel=52,giver=[[Tirion Fordring]],giver_loc=[[Tirion Vadín]],giverType=[[NPC]],giverId=1855,ender=[[Tirion Fordring]],ender_loc=[[Tirion Vadín]],enderType=[[NPC]],enderId=1855,nextId=5742,exGroup=-5542,poiX=2014,poiY=-5304,wowhead=[[https://www.wowhead.com/wotlk/quest=5544]],image=[[assets/images/quests/placeholder.png]],desc=[[My food supplies are running low, $r. I am ashamed to admit that I might not have enough food to share with you. Could you assist an old man with a simple task? Around here, the only manner of beast unaffected by the ravages of the Plague are the Carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. I will need several hundred pounds to restock for the coming winter!]],logDesc=[[Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat. ]]}
DB[5545]={id=5545,zoneId=12,name=[[A Bundle of Trouble]],name_loc=[[El cumplimiento del plazo]],level=9,minLevel=5,giver=[[Supervisor Raelen]],giver_loc=[[Supervisora Raelen]],giverType=[[NPC]],giverId=10616,ender=[[Supervisor Raelen]],ender_loc=[[Supervisora Raelen]],enderType=[[NPC]],enderId=10616,poiX=-9351,poiY=-1421,wowhead=[[https://www.wowhead.com/wotlk/quest=5545]],image=[[assets/images/quests/placeholder.png]],desc=[[I've got a real problem on my hands. I have a deadline looming for an order of lumber, and I'm running out of time. The wolves and bears north of here have chased my workers away from the bundles of wood that they've already chopped. I've already talked to Deputy Rainer about clearing the animals, but I need someone to go collect the wood for me. If you could collect eight bundles of wood for me I might just make my deadline.]],logDesc=[[Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp.]]}
DB[5561]={id=5561,zoneId=405,name=[[Kodo Roundup]],name_loc=[[El rodeo kodo]],level=34,minLevel=30,giver=[[Smeed Scrabblescrew]],giver_loc=[[Smeed Mezclatornillos]],giverType=[[NPC]],giverId=11596,ender=[[Smeed Scrabblescrew]],ender_loc=[[Smeed Mezclatornillos]],enderType=[[NPC]],enderId=11596,poiX=-1427,poiY=1728,wowhead=[[https://www.wowhead.com/wotlk/quest=5561]],image=[[assets/images/quests/placeholder.png]],desc=[[Bibbly thinks he is the only goblin in Desolace who knows how to make money.  Well, the only caravan brave enough to travel these parts relies on me.  Ever since I learned how to rejuvenate and control aged and dying kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership. Take the kombobulator and use it on any ancient, aged, or dying kodos; it will jolt the beast into a tamed kodo and force it to follow you.  Once you have a kodo tamed, bring it back to me.]],logDesc=[[Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp.]],choiceRewards={{id=15697,qty=1},{id=15698,qty=1}}}
DB[5581]={id=5581,zoneId=405,name=[[Portals of the Legion]],name_loc=[[Los portales de la Legión]],level=38,minLevel=32,giver=[[Taiga Wisemane]],giver_loc=[[Taiga Crin Sabia]],giverType=[[NPC]],giverId=11624,ender=[[Taiga Wisemane]],ender_loc=[[Taiga Crin Sabia]],enderType=[[NPC]],enderId=11624,prevId=5381,poiX=-1928,poiY=1757,wowhead=[[https://www.wowhead.com/wotlk/quest=5581]],image=[[assets/images/quests/placeholder.png]],desc=[[Behold - the Hand of Iruxos. A gruesome sight indeed. You must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do. The Demon threat is increasing and we must close these portals to stem the tide of demons to this world. Good luck, $N... and be wary of the portal guardians. ]],logDesc=[[Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village. ]],choiceRewards={{id=16794,qty=1},{id=16873,qty=1}}}
DB[5582]={id=5582,zoneId=2057,name=[[Healthy Dragon Scale]],name_loc=[[Escama de dragón sana]],level=58,minLevel=55,giverType=[[NPC]],ender=[[Betina Bigglezink]],ender_loc=[[Betina Bigglezink]],enderType=[[NPC]],enderId=11035,prevId=5529,poiX=2260,poiY=-5339,wowhead=[[https://www.wowhead.com/wotlk/quest=5582]],image=[[assets/images/quests/placeholder.png]],desc=[[This is a scale shed from a plagued dragon hatchling.  But unlike the other pocked, oozing scales on the infant beast, this rare scale is healthy and unmarred. Betina Bigglezink will want a sample of this to study.]],logDesc=[[Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands.]]}
DB[5601]={id=5601,zoneId=139,name=[[Sister Pamela]],name_loc=[[Pamela, mi hermana]],level=55,minLevel=50,giver=[[Jessica Redpath]],giver_loc=[[Jessica Rutagrana]],giverType=[[NPC]],giverId=11629,ender=[[Pamela Redpath]],ender_loc=[[Pamela Rutagrana]],enderType=[[NPC]],enderId=10926,rewardNextId=5149,exGroup=5142,poiX=1456,poiY=-3596,wowhead=[[https://www.wowhead.com/wotlk/quest=5601]],image=[[assets/images/quests/placeholder.png]],desc=[[I fled Lordaeron during the great war, and was lucky to escape before the Scourge swept through my homeland and turned it into a plagued nightmare!  I was lucky, but my family was not.  I fear they were all killed during the battle of Darrowshire. Darrowshire is a village in the Eastern Kingdoms, nestled in the southern hills of what is now the Eastern Plaguelands.  Will you go there and search for my family?  I miss them so much, especially my little sister Pamela. Please, find her for me!]],logDesc=[[Find Pamela Redpath in Darrowshire.]]}
DB[5621]={id=5621,name=[[Garments of the Moon]],name_loc=[[Prendas de la luna]],level=4,minLevel=5,giver=[[Laurna Morninglight]],giver_loc=[[Laurna Luzdelalba]],giverType=[[NPC]],giverId=3600,ender=[[Laurna Morninglight]],ender_loc=[[Laurna Luzdelalba]],enderType=[[NPC]],enderId=3600,prevId=5622,poiX=9676,poiY=900,wowhead=[[https://www.wowhead.com/wotlk/quest=5621]],image=[[assets/images/quests/placeholder.png]],desc=[[I need your help, $N. I am needed here to train the other students, but you, you can help one of our injured Sentinels just south of Dolanaar. She was hurt patrolling the town and could use our aid. Her name is Shaya. When you find her, heal her wounds, and then fortify her body with your spells. This will at least protect her from harm longer if she finds trouble. Return to me here after you've done your duty to Elune.]],logDesc=[[Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar.]],rewards={{id=16604,qty=1}}}
DB[5622]={id=5622,name=[[In Favor of Elune]],name_loc=[[Los caminos de Elune]],level=4,minLevel=5,giver=[[Shanda]],giver_loc=[[Shanda]],giverType=[[NPC]],giverId=3595,ender=[[Laurna Morninglight]],ender_loc=[[Laurna Luzdelalba]],enderType=[[NPC]],enderId=3600,rewardNextId=5621,poiX=9905,poiY=985,wowhead=[[https://www.wowhead.com/wotlk/quest=5622]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you must travel to Dolanaar when your business here in Shadowglen is done. There, you will find Laurna Morninglight. She will instruct you further in the ways of Elune, and it is with her that you will earn your first garments denoting your station as a $gpriest:priestess; of Elune. Take care, and may you be protected in your journeys.]],logDesc=[[Speak to Laurna Morninglight in Teldrassil.]]}
DB[5623]={id=5623,name=[[In Favor of the Light]],name_loc=[[Al servicio de la Luz]],level=4,minLevel=5,giver=[[Priestess Anetta]],giver_loc=[[Sacerdotisa Anetta]],giverType=[[NPC]],giverId=375,ender=[[Priestess Josetta]],ender_loc=[[Sacerdotisa Josetta]],enderType=[[NPC]],enderId=377,rewardNextId=5624,exGroup=5623,poiX=-9461,poiY=33,wowhead=[[https://www.wowhead.com/wotlk/quest=5623]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello again, young $gpriest:priestess;. The time has come for you to learn more about our religion. After you've completed whatever tasks you have here in Northshire, please seek out Priestess Josetta in Goldshire. She has more to teach you and has heard that you are growing strong in the ways of the Light. She looks forward to tutoring you more.]],logDesc=[[Speak to Priestess Josetta in Elwynn Forest.]]}
DB[5624]={id=5624,name=[[Garments of the Light]],name_loc=[[Las prendas de la Luz]],level=4,minLevel=5,giver=[[Priestess Josetta]],giver_loc=[[Sacerdotisa Josetta]],giverType=[[NPC]],giverId=377,ender=[[Priestess Josetta]],ender_loc=[[Sacerdotisa Josetta]],enderType=[[NPC]],enderId=377,prevId=5623,poiX=-9515,poiY=-136,wowhead=[[https://www.wowhead.com/wotlk/quest=5624]],image=[[assets/images/quests/placeholder.png]],desc=[[Normally I put forth a small challenge to followers of the Light to test their skill. I want to see if they are worthy of wearing their first robes--a sign that the church outwardly approves of the $gpriest:priestess; and supports $ghim:her;. But this situation is a bit different. One of Goldshire's citizens saw an injured guard near the lake to the east of here. His name is Roberts. Find him, heal him, fortify his body and return here. If you can do that for me, then I will consider your test complete.]],logDesc=[[Find Guard Roberts and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Priestess Josetta in Goldshire.]],rewards={{id=16605,qty=1}}}
DB[5625]={id=5625,name=[[Garments of the Light]],name_loc=[[Las prendas de la Luz]],level=4,minLevel=5,giver=[[Maxan Anvol]],giver_loc=[[Maxan Anvol]],giverType=[[NPC]],giverId=1226,ender=[[Maxan Anvol]],ender_loc=[[Maxan Anvol]],enderType=[[NPC]],enderId=1226,prevId=5626,poiX=-5669,poiY=-454,wowhead=[[https://www.wowhead.com/wotlk/quest=5625]],image=[[assets/images/quests/placeholder.png]],desc=[[It's usually about this time that one of your power is tested to see if they're worthy of wearing robes denoting their place in the church. But to be honest, I got more pressing matters to look into. Citizen of Kharanos' just came in here and told me 'bout a hurt mountaineer just outside town to the south--name's Dolf. You heal Dolf and give him Fortitude, and I'll consider you done with proving yourself. How's that sound?]],logDesc=[[Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.]],rewards={{id=16605,qty=1}}}
DB[5626]={id=5626,name=[[In Favor of the Light]],name_loc=[[Al servicio de la Luz]],level=4,minLevel=5,giver=[[Branstock Khalder]],giver_loc=[[Silo Khalder]],giverType=[[NPC]],giverId=837,ender=[[Maxan Anvol]],ender_loc=[[Maxan Anvol]],enderType=[[NPC]],enderId=1226,rewardNextId=5625,exGroup=5623,poiX=-5591,poiY=-530,wowhead=[[https://www.wowhead.com/wotlk/quest=5626]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey! $N! Got a minute?! Ya been following the Light now for long enough that you find your way to Maxan Anvol in Kharanos. He'll teach ya more about the path yer following, and if you prove worthy, give ya yer first set of robes to denote your station as a $gpriest:priestess;. Now get goin'! As soon as yer done here, head through the tunnel--he'll be waitin' for ya.]],logDesc=[[Speak to Maxan Anvol in Dun Morogh.]]}
DB[5627]={id=5627,name=[[Stars of Elune]],name_loc=[[Estrellas de Elune]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],poiX=9665,poiY=2520,wowhead=[[https://www.wowhead.com/wotlk/quest=5627]],image=[[assets/images/quests/placeholder.png]]}
DB[5628]={id=5628,name=[[Returning Home]],name_loc=[[La vuelta a casa]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5631,poiX=9665,poiY=2520,wowhead=[[https://www.wowhead.com/wotlk/quest=5628]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, yes, hello, $N? I'm glad you stopped to talk for a moment. You are a far way from home at such a young age--I admire such ambition. I wish when I was younger I could have mustered the courage to travel the world. There was a priestess of your order here looking for you not too long ago. She said it was very urgent you returned to the Temple of the Moon in Darnassus and speak to Priestess Alathea--it had something to do with your training. I wouldn't dally too long if you can help it.]],logDesc=[[Speak to Priestess Alathea in Darnassus.]]}
DB[5629]={id=5629,name=[[Returning Home]],name_loc=[[La vuelta a casa]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5631,poiX=9665,poiY=2520,wowhead=[[https://www.wowhead.com/wotlk/quest=5629]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello again, $N. I know you've been busy aiding our people, but you must take some time for yourself also. Priestess Alathea sent someone here looking for you. It seems that you've caught the attention of our elders and they feel you are prepared for greater things. Head to the Temple of the Moon in Darnassus and look for Alathea there. She will be waiting. Good luck, and may Elune be with you.]],logDesc=[[Speak to Priestess Alathea in Darnassus.]]}
DB[5630]={id=5630,name=[[Returning Home]],name_loc=[[La vuelta a casa]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],poiX=9665,poiY=2520,wowhead=[[https://www.wowhead.com/wotlk/quest=5630]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello there, $gladdy:lassy;. Good to see you travelin' far and wide to distant lands. No offense meant, but a lot o' your kind don't take well to these cold climates usually. Glad to see you're made of tougher stuff. Not too long ago one of your priestesses was in here lookin' for you--said somethin' about you finding a Priestess Alathea in the Temple of the Moon back in Darnassus. Said it was important and you should head back there soon.]],logDesc=[[Speak to Priestess Alathea in Darnassus.]]}
DB[5631]={id=5631,name=[[Returning Home]],name_loc=[[La vuelta a casa]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5631,poiX=9665,poiY=2520,wowhead=[[https://www.wowhead.com/wotlk/quest=5631]],image=[[assets/images/quests/placeholder.png]],desc=[[A priestess recently visited our halls seeking you out, young $r. She said that she was on a mission to find you and that you should return to the Temple of the Moon in Darnassus as soon as possible. When you arrive, seek out a Priestess Alathea--she will tell you more. The Light be with you, $N.]],logDesc=[[Speak to Priestess Alathea in Darnassus.]]}
DB[5632]={id=5632,name=[[Returning Home]],name_loc=[[La vuelta a casa]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],poiX=9665,poiY=2520,wowhead=[[https://www.wowhead.com/wotlk/quest=5632]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, yes, of course. Hello, $N. A messenger from our order was here not too long ago looking for you. She mentioned something important happening back in Darnassus and that you should return to the Temple of the Moon as soon as you can. When you arrive, speak to Priestess Alathea. I believe it has something to do with your progressing so well in our ways. Again, return to Darnassus when you can.]],logDesc=[[Speak to Priestess Alathea in Darnassus.]]}
DB[5633]={id=5633,name=[[Returning Home]],name_loc=[[La vuelta a casa]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],poiX=9665,poiY=2520,wowhead=[[https://www.wowhead.com/wotlk/quest=5633]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, $gladdy:lass;. Good to see you here in our great halls. A blessing be on you and your kind. While you were traveling through our lands, a priestess of your temple came here seeking you. She said that you were to return to the Temple of the Moon as soon as possible. I'm sorry I can't tell you more, but it did sound important. When you get to the temple, speak to a Priestess Alathea.]],logDesc=[[Speak to Priestess Alathea in Darnassus.]]}
DB[5634]={id=5634,name=[[Desperate Prayer]],name_loc=[[Oración desesperada]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5634,poiX=-8512,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=5634]],image=[[assets/images/quests/placeholder.png]]}
DB[5635]={id=5635,name=[[Desperate Prayer]],name_loc=[[Oración desesperada]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5634,poiX=-8512,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=5635]],image=[[assets/images/quests/placeholder.png]],desc=[[You've caught the attention of our superiors, $N. They've asked you travel to the Cathedral of Light in Stormwind as soon as possible. Apparently they feel you've proven yourself already and are prepared to further your training. When you get there, find High Priestess Laurena. She will be able to guide you further. Good luck, and may the Light be with you.]],logDesc=[[Speak to High Priestess Laurena in Stormwind.]]}
DB[5636]={id=5636,name=[[Desperate Prayer]],name_loc=[[Oración desesperada]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5634,poiX=-8512,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=5636]],image=[[assets/images/quests/placeholder.png]],desc=[[Elune bless you, good $r. I hope your Light finds you and protects you well this day. One of your priests was here not long ago looking for you. He mentioned you returning to the Cathedral of Light as soon as possible to speak with High Priestess Laurena. It seems you've done well to garner such attention. I wouldn't spend too much time here--your people have need of you.]],logDesc=[[Speak to High Priestess Laurena in Stormwind.]]}
DB[5637]={id=5637,name=[[Desperate Prayer]],name_loc=[[Oración desesperada]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5634,poiX=-8512,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=5637]],image=[[assets/images/quests/placeholder.png]],desc=[[Time's come for you to head to Stormwind, $N. High Priestess Laurena in the Cathedral of Light wants to speak to you. Gotta be somethin' really good or really bad for the High Priestess to want you there personally, but I'm guessin' you've only done well for yourself and it's a good thing that she wants to speak to ya. But don't waste too much time 'round here. I'd head there as soon as you can.]],logDesc=[[Speak to High Priestess Laurena in Stormwind.]]}
DB[5638]={id=5638,name=[[Desperate Prayer]],name_loc=[[Oración desesperada]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5634,poiX=-8512,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=5638]],image=[[assets/images/quests/placeholder.png]],desc=[[Just a short time ago, one of your priests was here looking for you, $r. He said that if I were to see you, I should direct you towards the Cathedral of Light. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn't take too long in making my way there if I were you. Elune be with you, good $r.]],logDesc=[[Speak to High Priestess Laurena in Stormwind.]]}
DB[5639]={id=5639,name=[[Desperate Prayer]],name_loc=[[Oración desesperada]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5634,poiX=-8512,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=5639]],image=[[assets/images/quests/placeholder.png]],desc=[[You're needed in Stormwind, $N. The High Priestess there, Laurena, says it's time for you to prove you're worthy of the next level of your training. Don't waste too much time finding your way there. You can find her in the Cathedral of Light in the center of the city. Give her my regards, and prove how worthy you are of such a calling. The Light be with you, $N.]],logDesc=[[Speak to High Priestess Laurena in Stormwind.]]}
DB[5640]={id=5640,name=[[Desperate Prayer]],name_loc=[[Oración desesperada]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],poiX=-8512,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=5640]],image=[[assets/images/quests/placeholder.png]],desc=[[Praise be to Elune, and to your Light, $N. About this time, many of our order learn abilities reflecting their faith in Elune. If knowledge serves me, I believe the same holds true for your order also. When your business in Darnassus is complete, I would seek out one of your High Priestesses for further training.]],logDesc=[[Speak to High Priestess Laurena in Stormwind.]]}
DB[5641]={id=5641,name=[[A Lack of Fear]],name_loc=[[Sin miedo]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5641,poiX=-4612,poiY=-909,wowhead=[[https://www.wowhead.com/wotlk/quest=5641]],image=[[assets/images/quests/placeholder.png]]}
DB[5642]={id=5642,name=[[Shadowguard]],name_loc=[[Guardia de las Sombras]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5642,poiX=1452,poiY=-4180,wowhead=[[https://www.wowhead.com/wotlk/quest=5642]],image=[[assets/images/quests/placeholder.png]],desc=[[Something important is up in Orgrimmar, $N. The normal messengers that come through here looking for troll priests usually are very casual. This time, they seemed to be in much more a hurry. Don't dally too long in Thunder Bluff. I'd return to the Valley of Spirits as soon as possible.]],logDesc=[[Speak to Ur'kyo in Orgrimmar.]]}
DB[5643]={id=5643,name=[[Shadowguard]],name_loc=[[Guardia de las Sombras]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5642,poiX=1452,poiY=-4180,wowhead=[[https://www.wowhead.com/wotlk/quest=5643]],image=[[assets/images/quests/placeholder.png]],desc=[[Like many of our own priests, your own tribe puts you through rites of passage. These rites often teach priests special abilities that are vital to their survival. I sense that time is upon you even as we speak. You must return to the Valley of Spirits in Orgrimmar and speak to Ur'kyo. What he teaches you might be very important for the future.]],logDesc=[[Speak to Ur'kyo in Orgrimmar.]]}
DB[5644]={id=5644,name=[[Devouring Plague]],name_loc=[[Peste devoradora]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5644,poiX=1768,poiY=401,wowhead=[[https://www.wowhead.com/wotlk/quest=5644]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, a wonderful day for you, $N. I can see by the lessons you've learned that the time has come to send you back to Aelthalyste. There are things only she can teach you, and even then, only if you prove worthy. I will not spoil the surprise for you, but I remember when I was a young priest learning about true power... divine power. Yes, those were the days. Go back to Aelthalyste in the Undercity, $N. She will be awaiting you in the War Quarter.]],logDesc=[[Speak to Aelthalyste in the Undercity.]]}
DB[5645]={id=5645,name=[[A Lack of Fear]],name_loc=[[Sin miedo]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5641,poiX=-4612,poiY=-909,wowhead=[[https://www.wowhead.com/wotlk/quest=5645]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, your High Priest Rohan would have an audience with you in Ironforge. Make haste, my strong friend, your next test quickly approaches. Although I wish I could bear witness to your race's own special rites, my place is here. But may the Light go with you in your travels. Rohan should still be in the Mystic Ward once you reach the city. He will be waiting.]],logDesc=[[Speak to High Priest Rohan in Ironforge.]]}
DB[5646]={id=5646,name=[[Devouring Plague]],name_loc=[[Peste devoradora]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5644,poiX=1768,poiY=401,wowhead=[[https://www.wowhead.com/wotlk/quest=5646]],image=[[assets/images/quests/placeholder.png]],desc=[[Aelthalyste show our people great respect by sending them back to me for more training, and now I do the same for her tribe. You return to the Undercity, $N. There, in the War Quarter, she be ready to teach you more 'bout your people and their ways. Go there, and do not wait long.]],logDesc=[[Speak to Aelthalyste in the Undercity.]]}
DB[5647]={id=5647,name=[[A Lack of Fear]],name_loc=[[Sin miedo]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5641,poiX=-4612,poiY=-909,wowhead=[[https://www.wowhead.com/wotlk/quest=5647]],image=[[assets/images/quests/placeholder.png]],desc=[[Your race is so very strong, $N. We are proud to call you allies. And as each day's sun sets, you and your kin grow closer to not only finding your true origins, but find great confidence that you are on the right path in so many things. That feeling must make you feel so triumphant. Word came from Ironforge just recently. It asked that you return there and speak to High Priest Rohan in the Mystic Ward. I would not keep him waiting. May Elune guide your travels.]],logDesc=[[Speak to High Priest Rohan in Ironforge.]]}
DB[5648]={id=5648,name=[[Garments of Spirituality]],name_loc=[[Prendas de espiritualidad]],level=4,minLevel=5,giver=[[Tai'jin]],giver_loc=[[Tai'jin]],giverType=[[NPC]],giverId=3706,ender=[[Tai'jin]],ender_loc=[[Tai'jin]],enderType=[[NPC]],enderId=3706,prevId=5649,poiX=171,poiY=-4770,wowhead=[[https://www.wowhead.com/wotlk/quest=5648]],image=[[assets/images/quests/placeholder.png]],desc=[[You be ready for your first test, $N. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops. She not doin' too well, an' she benefit much if one of our kind could help her. Find her--her name be Kor'ja--heal her wounds, an' give her the blessin' of our ancestors. You do this, an' me thinks that be sufficient proof that you ready to move on in our ways.]],logDesc=[[Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill.]],rewards={{id=16606,qty=1}}}
DB[5649]={id=5649,name=[[In Favor of Spirituality]],name_loc=[[Al servicio de la espiritualidad]],level=4,minLevel=5,giver=[[Ken'jai]],giver_loc=[[Ken'jai]],giverType=[[NPC]],giverId=3707,ender=[[Tai'jin]],ender_loc=[[Tai'jin]],enderType=[[NPC]],enderId=3706,rewardNextId=5648,exGroup=5649,poiX=295,poiY=-4831,wowhead=[[https://www.wowhead.com/wotlk/quest=5649]],image=[[assets/images/quests/placeholder.png]],desc=[[Aye, mon. Our kind have joined the Horde because they be good for us. They loyal, and they teach us much 'bout tings like honor. But our old ways die hard. The orcs may not approve of all our traditions, but that not mean we can't continue to practice some them in secret. You know this, an' that's why I send you to Tai'jin in Razor Hill. She teach you more 'bout our history. She teach you the ways of our tribe. Go to her when you be ready.]],logDesc=[[Speak to Tai'jin in Durotar.]]}
DB[5650]={id=5650,name=[[Garments of Darkness]],name_loc=[[Las prendas de la Oscuridad]],level=4,minLevel=5,giver=[[Dark Cleric Beryl]],giver_loc=[[Clérigo oscuro Beryl]],giverType=[[NPC]],giverId=2129,ender=[[Dark Cleric Beryl]],ender_loc=[[Clérigo oscuro Beryl]],enderType=[[NPC]],enderId=2129,prevId=5651,poiX=2437,poiY=359,wowhead=[[https://www.wowhead.com/wotlk/quest=5650]],image=[[assets/images/quests/placeholder.png]],desc=[[Our power comes from darkness and shadow, $N, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts. This is wise. But before you can know the dark, you must also know the light. And for this, I have a test for you. North of the cemetery is a wounded Deathguard--Deathguard Kel. He has protected us from gnolls for some time, and needs healing. But, you must also fortify his body before he can return to duty. Do both with your spells, and then return to me.]],logDesc=[[Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill.]],rewards={{id=16607,qty=1}}}
DB[5651]={id=5651,name=[[In Favor of Darkness]],name_loc=[[Al servicio de la Oscuridad]],level=4,minLevel=5,giver=[[Dark Cleric Duesten]],giver_loc=[[Clérigo oscuro Duesten]],giverType=[[NPC]],giverId=2123,ender=[[Dark Cleric Beryl]],ender_loc=[[Clérigo oscuro Beryl]],enderType=[[NPC]],enderId=2129,rewardNextId=5650,exGroup=5649,poiX=2265,poiY=251,wowhead=[[https://www.wowhead.com/wotlk/quest=5651]],image=[[assets/images/quests/placeholder.png]],desc=[[There are many lessons that the Forsaken have learned through experience--things that some races can only begin to fathom. And although our path lies in darkness, you will find that a great many things rely on both the light and the dark. Your lessons shall teach you to use both... and with discretion. But heed my words: never forget we were forged in corruption and left to rot like so much carrion. The Darkness is our home. Seek out Dark Cleric Beryl in Brill when you're ready to learn more.]],logDesc=[[Speak to Dark Cleric Beryl in Tirisfal Glades.]]}
DB[5652]={id=5652,name=[[Hex of Weakness]],name_loc=[[Maleficio de Debilidad]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5652,poiX=1452,poiY=-4180,wowhead=[[https://www.wowhead.com/wotlk/quest=5652]],image=[[assets/images/quests/placeholder.png]]}
DB[5654]={id=5654,name=[[Hex of Weakness]],name_loc=[[Maleficio de Debilidad]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5652,poiX=1452,poiY=-4180,wowhead=[[https://www.wowhead.com/wotlk/quest=5654]],image=[[assets/images/quests/placeholder.png]],desc=[[It be time for you to meet with Ur'kyo, $N. He be in the Valley of Spirits in the orc city. Go there and speak to him. It is time you learn more of the old ways of our kind. It time you be brought into the circle and made a true priest of our tribe.]],logDesc=[[Speak to Ur'kyo in Orgrimmar.]]}
DB[5655]={id=5655,name=[[Hex of Weakness]],name_loc=[[Maleficio de Debilidad]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5652,poiX=1452,poiY=-4180,wowhead=[[https://www.wowhead.com/wotlk/quest=5655]],image=[[assets/images/quests/placeholder.png]],desc=[[I sent here to make sure that you not wander too far from home, $N. They send me to make sure you return home because Ur'kyo, greatest of our priests, wish to speak to you. You go there. You go to the Valley of Spirits in the orc city and you speak to Ur'kyo. He wait for you now.]],logDesc=[[Speak to Ur'kyo in Orgrimmar.]]}
DB[5656]={id=5656,name=[[Hex of Weakness]],name_loc=[[Maleficio de Debilidad]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5652,poiX=1452,poiY=-4180,wowhead=[[https://www.wowhead.com/wotlk/quest=5656]],image=[[assets/images/quests/placeholder.png]],desc=[[It always warms my undying heart to see priests from all cultures wander the world. To know that power exists that is not arcane and well within our grasp. That's why it is my honor to direct you home, $N. Ur'kyo, your great priest in Orgrimmar, has asked for your presence. You can find him in the Valley of Spirits.]],logDesc=[[Speak to Ur'kyo in Orgrimmar.]]}
DB[5657]={id=5657,name=[[Hex of Weakness]],name_loc=[[Maleficio de Debilidad]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5652,poiX=1452,poiY=-4180,wowhead=[[https://www.wowhead.com/wotlk/quest=5657]],image=[[assets/images/quests/placeholder.png]],desc=[[Home. Return home, young $r. Your spiritual leader Ur'kyo begs you to return to him and speak about the path you travel. Go to the Valley of Spirits in the great Horde city of Orgrimmar. You will find him there.]],logDesc=[[Speak to Ur'kyo in Orgrimmar.]]}
DB[5658]={id=5658,name=[[Touch of Weakness]],name_loc=[[Toque de debilidad]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5658,poiX=1768,poiY=401,wowhead=[[https://www.wowhead.com/wotlk/quest=5658]],image=[[assets/images/quests/placeholder.png]]}
DB[5660]={id=5660,name=[[Touch of Weakness]],name_loc=[[Toque de debilidad]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5658,poiX=1768,poiY=401,wowhead=[[https://www.wowhead.com/wotlk/quest=5660]],image=[[assets/images/quests/placeholder.png]],desc=[[You be far from home, $c. You be needed there, back in your city under the ground. Your mistress, the one you be callin' Aelthalyste be needin' you back there. Like my tribe, there things you must learn only from her. Don't be stayin' here too long. You should be headin' to the War Quarter as fast as a zeppelin can carry you.]],logDesc=[[Speak to Aelthalyste in the Undercity.]]}
DB[5661]={id=5661,name=[[Touch of Weakness]],name_loc=[[Toque de debilidad]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5658,poiX=1768,poiY=401,wowhead=[[https://www.wowhead.com/wotlk/quest=5661]],image=[[assets/images/quests/placeholder.png]],desc=[[You be far from home out here in the Bloodhoof Village, $N. I be sent here to find priests of my own tribe to send back to speak to our leaders, but that not mean I cannot help you too. I hear word that your head priestess spirit want all Forsaken to come to her--there are things you must learn. Go to meet Aelthalyste in the War Quarter in that city of yours.]],logDesc=[[Speak to Aelthalyste in the Undercity.]]}
DB[5662]={id=5662,name=[[Touch of Weakness]],name_loc=[[Toque de debilidad]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5658,poiX=1768,poiY=401,wowhead=[[https://www.wowhead.com/wotlk/quest=5662]],image=[[assets/images/quests/placeholder.png]],desc=[[My respect to you and your kind, $N. I normally teach only those of my own tribe. Your lessons come from Aelthalyste in the city once called Lordaeron. You should return to her if you're to learn those abilities that set you apart from other faiths. Go to the War Quarter in the Undercity and find your mistress there.]],logDesc=[[Speak to Aelthalyste in the Undercity.]]}
DB[5663]={id=5663,name=[[Touch of Weakness]],name_loc=[[Toque de debilidad]],level=-1,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=5658,poiX=1768,poiY=401,wowhead=[[https://www.wowhead.com/wotlk/quest=5663]],image=[[assets/images/quests/placeholder.png]],desc=[[Aelthalyste sent word out to all her priests. We're to direct the younger of our order to the Undercity for more training. If you truly count yourself among our faithful, then you should return there also. You can find Aelthalyste in the War Quarter deep in the Undercity.]],logDesc=[[Speak to Aelthalyste in the Undercity.]]}
DB[5672]={id=5672,name=[[Elune's Grace]],name_loc=[[La Gracia de Elune]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5672,poiX=9665,poiY=2520,wowhead=[[https://www.wowhead.com/wotlk/quest=5672]],image=[[assets/images/quests/placeholder.png]]}
DB[5673]={id=5673,name=[[Elune's Grace]],name_loc=[[La Gracia de Elune]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5672,poiX=9665,poiY=2520,wowhead=[[https://www.wowhead.com/wotlk/quest=5673]],image=[[assets/images/quests/placeholder.png]],desc=[[You know you have access to any of our trainers at any time, $N, but there are some things that we cannot pass on to you. One of those things are the teachings of your goddess Elune. She gives special abilities to her faithful, and if I'm not mistaken, it is time for you to return home to your Temple of the Moon to be tested. Return there when you can and speak to Priestess Alathea.]],logDesc=[[Speak to Priestess Alathea in Darnassus.]]}
DB[5674]={id=5674,name=[[Elune's Grace]],name_loc=[[La Gracia de Elune]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5672,poiX=9665,poiY=2520,wowhead=[[https://www.wowhead.com/wotlk/quest=5674]],image=[[assets/images/quests/placeholder.png]],desc=[[A wonderful day has come, $N. You've reached the age in which our $gpriests:priestesses; are trained in abilities only Night elves know. But it is not for me to train you. You must return to the Temple of the Moon and speak to Priestess Alathea as soon as your business here is concluded. She will test you to ensure you're prepared, and only then will she teach you Elune's Grace.]],logDesc=[[Speak to Priestess Alathea in Darnassus.]]}
DB[5675]={id=5675,name=[[Elune's Grace]],name_loc=[[La Gracia de Elune]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5672,poiX=9665,poiY=2520,wowhead=[[https://www.wowhead.com/wotlk/quest=5675]],image=[[assets/images/quests/placeholder.png]],desc=[[Time's a wastin', $glad:lass;. It's time for you to return home to Darnassus. Priestess Alathea's sent word here that you're to return there for training. Seems they feel you're ready to be tested much like those who serve the Light. You should head out whenever you can. Alathea's message said that she'd be waitin' for you in the Temple of the Moon. Good luck.]],logDesc=[[Speak to Priestess Alathea in Darnassus.]]}
DB[5676]={id=5676,name=[[Arcane Feedback]],name_loc=[[La reacción Arcana]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5676,poiX=-8512,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=5676]],image=[[assets/images/quests/placeholder.png]]}
DB[5677]={id=5677,name=[[Arcane Feedback]],name_loc=[[La reacción Arcana]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5676,poiX=-8512,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=5677]],image=[[assets/images/quests/placeholder.png]],desc=[[As much as I'd like to show you our own special teachings of the Light, it is not our place. Your place is back in Stormwind with your own kind, $N... for now. Believe me, I mean no offense. When you return to High Priestess Laurena in the Cathedral of Light you'll understand what I'm talking about--the time has come for your race to prepare you for the future; to separate yourself from others that follow a similar path.]],logDesc=[[Speak to High Priestess Laurena in Stormwind.]]}
DB[5678]={id=5678,name=[[Arcane Feedback]],name_loc=[[La reacción Arcana]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5676,poiX=-8512,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=5678]],image=[[assets/images/quests/placeholder.png]],desc=[[It is time for you to return to Stormwind, young one. Your superiors there have called you back for more training. And although it disturbs me some, your race and mine are allies and I would not betray that. I do not mean to be so coy with you--my distrust of arcane magics, be they divine inspired or not, is still strong within me. You will know of what I speak after you return to your Cathedral of Light. Speak to High Priestess Laurena when you arrive.]],logDesc=[[Speak to High Priestess Laurena in Stormwind.]]}
DB[5679]={id=5679,name=[[Devouring Plague]],name_loc=[[Peste devoradora]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5644,poiX=1768,poiY=401,wowhead=[[https://www.wowhead.com/wotlk/quest=5679]],image=[[assets/images/quests/placeholder.png]]}
DB[5680]={id=5680,name=[[Shadowguard]],name_loc=[[Guardia de las Sombras]],level=-1,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=5642,poiX=1452,poiY=-4180,wowhead=[[https://www.wowhead.com/wotlk/quest=5680]],image=[[assets/images/quests/placeholder.png]]}
DB[5713]={id=5713,zoneId=148,name=[[One Shot.  One Kill.]],name_loc=[[Un disparo, una baja]],level=15,minLevel=10,giver=[[Sentinel Aynasha]],giver_loc=[[Centinela Aynasha]],giverType=[[NPC]],giverId=11711,ender=[[Sentinel Onaeya]],ender_loc=[[Centinela Onaeya]],enderType=[[NPC]],enderId=11806,poiX=3261,poiY=166,wowhead=[[https://www.wowhead.com/wotlk/quest=5713]],image=[[assets/images/quests/placeholder.png]],desc=[[I was traveling to Auberdine with an important message when I was attacked by the furbolg Marosh and his trackers. During the attack I was poisoned, leaving me barely able to stand. I can make an antidote, but it will take time before it is ready. I would ask that you defend me until I can apply the antidote. I will aid you with my bow as best I can. Should we survive, I will be able to deliver my message to Auberdine, while you speak with Onaeya at Maestra's Post to inform her of this incident.]],logDesc=[[Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale.]]}
DB[5721]={id=5721,zoneId=139,name=[[The Battle of Darrowshire]],name_loc=[[La Batalla de Villa Darrow]],level=60,minLevel=55,giver=[[Chromie]],giver_loc=[[Cromi]],giverType=[[NPC]],giverId=10667,ender=[[Pamela Redpath]],ender_loc=[[Pamela Rutagrana]],enderType=[[NPC]],enderId=10926,prevId=5941,rewardNextId=5942,poiX=1445,poiY=-3701,wowhead=[[https://www.wowhead.com/wotlk/quest=5721]],image=[[assets/images/quests/placeholder.png]],desc=[[Now, $N, you will take part in battle of Darrowshire, and you will save Joseph Redpath. Place this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated. After defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela.]],logDesc=[[Place the Relic Bundle at the Darrowshire town square. Prevent Davil Lightfire's death until the death of Horgus. Prevent Captain Redpath's death until Redpath the Corrupted appears. Defeat Redpath the Corrupted. Speak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.]],rewards={{id=15723,qty=1}}}
DB[5722]={id=5722,zoneId=2437,name=[[Searching for the Lost Satchel]],name_loc=[[Buscando la cartera perdida]],level=16,minLevel=9,giver=[[Rahauro]],giver_loc=[[Rahauro]],giverType=[[NPC]],giverId=11833,ender=[[Maur Grimtotem]],ender_loc=[[Maur Tótem Siniestro]],enderType=[[NPC]],enderId=11834,rewardNextId=5724,poiX=1805,poiY=-4403,wowhead=[[https://www.wowhead.com/wotlk/quest=5722]],image=[[assets/images/quests/placeholder.png]],desc=[[The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs. Return to Magatha any items of interest, and I'm sure she would be very generous in her reward. Again, seek the Chasm in the darkest areas of Orgrimmar.]],logDesc=[[Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.]]}
DB[5723]={id=5723,zoneId=2437,name=[[Testing an Enemy's Strength]],name_loc=[[Midiendo fuerzas con el enemigo]],level=15,minLevel=9,giver=[[Rahauro]],giver_loc=[[Rahauro]],giverType=[[NPC]],giverId=11833,ender=[[Rahauro]],ender_loc=[[Rahauro]],enderType=[[NPC]],enderId=11833,poiX=-1055,poiY=-215,wowhead=[[https://www.wowhead.com/wotlk/quest=5723]],image=[[assets/images/quests/placeholder.png]],desc=[[Beneath the city of Orgrimmar, stout creatures known as troggs started coming to the surface from deep below the lava filled tunnels. In her ever-benevolence, Magatha sought to make peace with the creatures, but they turned on her diplomats, killing them. She will not allow such treatment of the tauren people and now consider the creatures a threat to all of the Horde. She asks that you put an end to this trogg threat before it overwhelms the Horde from below. Find Ragefire Chasm and destroy them all.]],logDesc=[[Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.]]}
DB[5724]={id=5724,zoneId=2437,name=[[Returning the Lost Satchel]],name_loc=[[La vuelta de la cartera perdida]],level=16,minLevel=9,giver=[[Maur Grimtotem]],giver_loc=[[Maur Tótem Siniestro]],giverType=[[NPC]],giverId=11834,ender=[[Rahauro]],ender_loc=[[Rahauro]],enderType=[[NPC]],enderId=11833,prevId=5722,poiX=-1055,poiY=-215,wowhead=[[https://www.wowhead.com/wotlk/quest=5724]],image=[[assets/images/quests/placeholder.png]],desc=[[You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs. Removing the satchel from his vice-like grip, you stow it with your own equipment and prepare to make your way out of the tunnels and back to Rahauro in Thunder Bluff.]],logDesc=[[Take the Grimtotem Satchel to Rahauro in Thunder Bluff.]],choiceRewards={{id=15452,qty=1},{id=15453,qty=1}}}
DB[5725]={id=5725,zoneId=2437,name=[[The Power to Destroy...]],name_loc=[[Poder destructivo]],level=16,minLevel=9,giver=[[Varimathras]],giverType=[[NPC]],giverId=2425,ender=[[Varimathras]],enderType=[[NPC]],enderId=2425,poiX=1288,poiY=334,wowhead=[[https://www.wowhead.com/wotlk/quest=5725]],image=[[assets/images/quests/placeholder.png]],desc=[[Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with... lesser vision. A sect of the Shadow Council hidden in caverns below Orgrimmar known as the Searing Blade are a prime example. The Lady tells me that members of the Searing Blade have come into the possession of two powerful spell books--she would like to "borrow" these books from them. You will get them for her.]],logDesc=[[Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.]],choiceRewards={{id=15449,qty=1},{id=15450,qty=1},{id=15451,qty=1}}}
DB[5726]={id=5726,zoneId=1637,name=[[Hidden Enemies]],name_loc=[[Enemigos ocultos]],level=12,minLevel=9,giver=[[Thrall]],giver_loc=[[Thrall]],giverType=[[NPC]],giverId=4949,ender=[[Thrall]],ender_loc=[[Thrall]],enderType=[[NPC]],enderId=4949,poiX=877,poiY=-4230,wowhead=[[https://www.wowhead.com/wotlk/quest=5726]],image=[[assets/images/quests/placeholder.png]],desc=[[One thing I will not tolerate are traitors in our midst, $N. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse. But you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast. If you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant's insignia off one of the Burning Blade there, and return to me.]],logDesc=[[Bring a Lieutenant's Insignia to Thrall in Orgrimmar.]]}
DB[5727]={id=5727,zoneId=1637,name=[[Hidden Enemies]],name_loc=[[Enemigos ocultos]],level=12,minLevel=9,giver=[[Thrall]],giver_loc=[[Thrall]],giverType=[[NPC]],giverId=4949,ender=[[Thrall]],ender_loc=[[Thrall]],enderType=[[NPC]],enderId=4949,prevId=5726,rewardNextId=5728,poiX=1929,poiY=-4159,wowhead=[[https://www.wowhead.com/wotlk/quest=5727]],image=[[assets/images/quests/placeholder.png]],desc=[[Now let us see if this insignia you found is worth the effort. There is a warlock within the city who believes he has my trust. He does not know that I realize where his true loyalties lie. He is in fact the leader of the Burning Blade. But do not rush off to do battle with him; he has a purpose, and we shall use him against our enemies. Take this insignia to him in the Cleft of Shadow here in Orgrimmar, speak to him and see if he believes you are one of his own, then return to me here.]],logDesc=[[Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar.]]}
DB[5728]={id=5728,zoneId=2437,name=[[Hidden Enemies]],name_loc=[[Enemigos ocultos]],level=16,minLevel=9,giver=[[Thrall]],giver_loc=[[Thrall]],giverType=[[NPC]],giverId=4949,ender=[[Thrall]],ender_loc=[[Thrall]],enderType=[[NPC]],enderId=4949,prevId=5727,rewardNextId=5729,poiX=1928,poiY=-4158,wowhead=[[https://www.wowhead.com/wotlk/quest=5728]],image=[[assets/images/quests/placeholder.png]],desc=[[Hmm, leaders of the Searing Blade... this concerns me most. If they are the ones of value to Neeru, then those are who we must target first. This satyr... Bazzalan, and the other Neeru mentioned--what was he, a warlock?--must be slain. Return to the Cleft of Shadow and enter Ragefire Chasm, $N. Find these two leaders of the Searing Blade, and kill them. But be careful not to let Neeru know it was you who did this. You must retain your identity as one of his $gbrothers:sisters; in arms.]],logDesc=[[Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.]]}
DB[5729]={id=5729,zoneId=1637,name=[[Hidden Enemies]],name_loc=[[Enemigos ocultos]],level=15,minLevel=9,giver=[[Thrall]],giver_loc=[[Thrall]],giverType=[[NPC]],giverId=4949,ender=[[Neeru Fireblade]],ender_loc=[[Neeru Hojafuego]],enderType=[[NPC]],enderId=3216,prevId=5728,rewardNextId=5730,poiX=1801,poiY=-4375,wowhead=[[https://www.wowhead.com/wotlk/quest=5729]],image=[[assets/images/quests/placeholder.png]],desc=[[I think our next step should be to have you placed close to Neeru. If he is as agitated as reports suggest, then we may accomplish two things. One, you may be able to gain some greater knowledge about the Council or at least the Burning Blade, and two, he may just begin to trust you enough that he asks you to start to aid him. He may very well look at you as someone who can fill the void now that some of the leadership is in turmoil. Return to the Cleft and speak to him again, but do not be too overt.]],logDesc=[[Speak to Neeru Fireblade in Orgrimmar.]]}
DB[5730]={id=5730,zoneId=1637,name=[[Hidden Enemies]],name_loc=[[Enemigos ocultos]],level=16,minLevel=9,giver=[[Neeru Fireblade]],giver_loc=[[Neeru Hojafuego]],giverType=[[NPC]],giverId=3216,ender=[[Thrall]],ender_loc=[[Thrall]],enderType=[[NPC]],enderId=4949,prevId=5729,poiX=1924,poiY=-4160,wowhead=[[https://www.wowhead.com/wotlk/quest=5730]],image=[[assets/images/quests/placeholder.png]],desc=[[You are one of my lieutenants! Prepare yourself, $c. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer. I will do what I can to minimize the damage here in Ragefire Chasm. In the meantime, I will have my agents in the Barrens and Ashenvale begin work on our newest agenda. Return to me soon.]],logDesc=[[Speak to Thrall in Orgrimmar and tell him what you've learned.]],choiceRewards={{id=15443,qty=1},{id=15445,qty=1},{id=15424,qty=1},{id=15444,qty=1}}}
DB[5741]={id=5741,zoneId=405,name=[[Sceptre of Light]],name_loc=[[El Cetro de Luz]],level=33,minLevel=30,giver=[[Azore Aldamort]],giver_loc=[[Azore Aldamort]],giverType=[[NPC]],giverId=11863,ender=[[Azore Aldamort]],ender_loc=[[Azore Aldamort]],enderType=[[NPC]],enderId=11863,rewardNextId=6027,poiX=-452,poiY=1753,wowhead=[[https://www.wowhead.com/wotlk/quest=5741]],image=[[assets/images/quests/placeholder.png]],desc=[[The Burning Blade in Thunder Axe Fortress to the east is rumored to have acquired the Sceptre of Light from the Naga. Legend tells that the sceptre is able to sink entire cities under the great seas. The Burning Blade must not be allowed to possess such power. To that end, you must retrieve the sceptre yourself!  It is held by a Burning Blade seer, who studies the sceptre from atop one of the Thunder Axe watchtowers. ]],logDesc=[[Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor. ]]}
DB[5742]={id=5742,zoneId=139,name=[[Redemption]],name_loc=[[Redención]],level=56,minLevel=52,giver=[[Tirion Fordring]],giver_loc=[[Tirion Vadín]],giverType=[[NPC]],giverId=1855,ender=[[Tirion Fordring]],ender_loc=[[Tirion Vadín]],enderType=[[NPC]],enderId=1855,rewardNextId=5781,poiX=2674,poiY=-2477,wowhead=[[https://www.wowhead.com/wotlk/quest=5742]],image=[[assets/images/quests/placeholder.png]],desc=[[You have worked hard, friend. Rest your weary bones and allow me to properly introduce myself. ]],logDesc=[[Listen to what Tirion Fordring has to say.]]}
DB[5761]={id=5761,zoneId=2437,name=[[Slaying the Beast]],name_loc=[[Matar a la bestia]],level=16,minLevel=9,giver=[[Neeru Fireblade]],giver_loc=[[Neeru Hojafuego]],giverType=[[NPC]],giverId=3216,ender=[[Neeru Fireblade]],ender_loc=[[Neeru Hojafuego]],enderType=[[NPC]],enderId=3216,poiX=1801,poiY=-4375,wowhead=[[https://www.wowhead.com/wotlk/quest=5761]],image=[[assets/images/quests/placeholder.png]],desc=[[The primary task set upon me by our great Warchief is to root out the creatures responsible for infesting our lord's great city with demonic influence. The Burning Blade is one threat, but there are others; the Searing Blade for instance, who make their home in Ragefire Chasm, secretly attempting to subvert innocent members of the Horde. If they are to be stopped, then their leader must be slain--a Felguard named Taragaman the Hungerer. Kill him, and his heart will appease Thrall, of this I'm sure.]],logDesc=[[Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.]]}
DB[5762]={id=5762,zoneId=400,name=[[Hemet Nesingwary Jr.]],name_loc=[[Hemet Nesingwary Jr.]],level=31,minLevel=28,giver=[[Kravel Koalbeard]],giver_loc=[[Kravel Karbarbán]],giverType=[[NPC]],giverId=4452,ender=[[Hemet Nesingwary Jr.]],ender_loc=[[Hemet Decautela]],enderType=[[NPC]],enderId=715,poiX=-11629,poiY=-55,wowhead=[[https://www.wowhead.com/wotlk/quest=5762]],image=[[assets/images/quests/placeholder.png]],desc=[[I have a package for a new customer of mine, a dwarf named Hemet Nesingwary Jr..  The package took weeks to arrive, and Hemet's long gone by now.  He said he was going to Stranglethorn to take his father's place and hunt the beasts there, but he left me some money to send his delivery when I could.   Junior's a rich dwarf and it's a good idea to keep up relations with the rich ones, yeah?  So... you want to deliver the package for me? I heard he has a camp in Stranglethorn, north of Grom'gol.]],logDesc=[[Take Kravel's Crate to Hemet Nesingwary Jr. in Stranglethorn Vale.]]}
DB[5763]={id=5763,zoneId=405,name=[[Hunting in Stranglethorn]],name_loc=[[La caza en Tuercespina]],level=31,minLevel=28,giver=[[Roon Wildmane]],giver_loc=[[Roon Ferocrín]],giverType=[[NPC]],giverId=11877,ender=[[Hemet Nesingwary Jr.]],ender_loc=[[Hemet Decautela]],enderType=[[NPC]],enderId=715,poiX=-11629,poiY=-55,wowhead=[[https://www.wowhead.com/wotlk/quest=5763]],image=[[assets/images/quests/placeholder.png]],desc=[[Long ago, a dwarf came to this land.  His name was Hemet and he wished to hunt great beasts.  His skills with the rifle were uncanny, and we spent many days hunting together.  Even the enmity between our peoples was forgotten. When he left for Stranglethorn, I vowed to one day welcome him back.  Now he has gone on to hunt in lands unknown, but his son has taken his place. Take this kodo horn as a gift to Hemet Jr..  You will find him in Stranglethorn, north of the Grom'gol Base camp.]],logDesc=[[Bring Roon's Kodo Horn to Hemet Nesingwary Jr. in Stranglethorn Vale.]]}
DB[5781]={id=5781,zoneId=139,name=[[Of Forgotten Memories]],name_loc=[[De recuerdos olvidados]],level=57,minLevel=52,giver=[[Tirion Fordring]],giver_loc=[[Tirion Vadín]],giverType=[[NPC]],giverId=1855,ender=[[Tirion Fordring]],ender_loc=[[Tirion Vadín]],enderType=[[NPC]],enderId=1855,prevId=5742,rewardNextId=5845,poiX=2674,poiY=-2477,wowhead=[[https://www.wowhead.com/wotlk/quest=5781]],image=[[assets/images/quests/placeholder.png]],desc=[[To help Taelan regain what he has lost, you must gather items from his past. The first such item is a toy that I gave to him on his 7th birthday. It was his most cherished possession: A miniature war hammer; an exact replica of my very own. After I was banished for treason, his mother told him that I had died. He was taken to my false grave at the Undercroft, where he buried the hammer along with my memory - forever. You must venture to the Undercroft and recover Taelan's hammer.]],logDesc=[[Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.]]}
DB[5801]={id=5801,zoneId=440,name=[[Fire Plume Forged]],name_loc=[[La forja del Penacho en Llamas]],level=57,minLevel=55,giver=[[Krinkle Goodsteel]],giver_loc=[[Krinkle Buenacero]],giverType=[[NPC]],giverId=5411,ender=[[Alchemist Arbington]],ender_loc=[[Alquimista Arbington]],enderType=[[NPC]],enderId=11056,prevId=5538,rewardNextId=5803,poiX=-7133,poiY=-1267,wowhead=[[https://www.wowhead.com/wotlk/quest=5801]],image=[[assets/images/quests/placeholder.png]],desc=[[You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat. To our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest. That's it on my end.  To finish your key, you'll need to talk to Arbington again.]],logDesc=[[Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater.  Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key. Bring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands.]]}
DB[5802]={id=5802,zoneId=440,name=[[Fire Plume Forged]],name_loc=[[La forja del Penacho en Llamas]],level=57,minLevel=55,giver=[[Krinkle Goodsteel]],giver_loc=[[Krinkle Buenacero]],giverType=[[NPC]],giverId=5411,ender=[[Apothecary Dithers]],ender_loc=[[Boticario Dithers]],enderType=[[NPC]],enderId=11057,prevId=5514,rewardNextId=5804,poiX=1752,poiY=-730,wowhead=[[https://www.wowhead.com/wotlk/quest=5802]],image=[[assets/images/quests/placeholder.png]],desc=[[You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat. To our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest. That's it on my end.  To finish your key, you'll need to talk to Dithers again.]],logDesc=[[Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater.  Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key. Bring the Unfinished Skeleton Key to Apothecary Dithers at the Bulwark, Western Plaguelands.]]}
DB[5803]={id=5803,zoneId=28,name=[[Araj's Scarab]],name_loc=[[El escarabeo de Araj]],level=60,minLevel=55,giver=[[Alchemist Arbington]],giver_loc=[[Alquimista Arbington]],giverType=[[NPC]],giverId=11056,ender=[[Alchemist Arbington]],ender_loc=[[Alquimista Arbington]],enderType=[[NPC]],enderId=11056,prevId=5801,poiX=1383,poiY=-1530,wowhead=[[https://www.wowhead.com/wotlk/quest=5803]],image=[[assets/images/quests/placeholder.png]],desc=[[Araj the Summoner lords over Andorhal from the ruined city's heart.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key. Make your way into the heart of Andorhal, and break his hold on the city now that he is drawn into the open.  Once destroyed, seize his scarab from his fallen phylactery! The Key to Scholomance awaits, $N!]],logDesc=[[Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands.]]}
DB[5804]={id=5804,zoneId=28,name=[[Araj's Scarab]],name_loc=[[El escarabeo de Araj]],level=60,minLevel=55,giver=[[Apothecary Dithers]],giver_loc=[[Boticario Dithers]],giverType=[[NPC]],giverId=11057,ender=[[Apothecary Dithers]],ender_loc=[[Boticario Dithers]],enderType=[[NPC]],enderId=11057,prevId=5802,poiX=1383,poiY=-1530,wowhead=[[https://www.wowhead.com/wotlk/quest=5804]],image=[[assets/images/quests/placeholder.png]],desc=[[Araj the Summoner lords over Andorhal from the ruined city's heart.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key. Make your way into the heart of Andorhal, and break his hold on the city now that he is drawn into the open.  Once destroyed, seize his scarab from his fallen phylactery! The Key to Scholomance awaits, $N!]],logDesc=[[Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands.]]}
DB[5805]={id=5805,zoneId=24,name=[[Welcome!]],name_loc=[[¡Te damos la bienvenida!]],level=1,minLevel=1,giverType=[[NPC]],ender=[[Merissa Stilwell]],ender_loc=[[Merissa Fontana]],enderType=[[NPC]],enderId=11940,poiX=-9479,poiY=53,wowhead=[[https://www.wowhead.com/wotlk/quest=5805]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome to the World of Warcraft! As special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Merissa Stilwell in Goldshire.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory. Thanks again, and enjoy your stay in the World of Warcraft! ]],logDesc=[[Bring the Goldshire Gift Voucher to Merissa Stilwell in Goldshire.]],choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}}
DB[5821]={id=5821,zoneId=405,name=[[Bodyguard for Hire]],name_loc=[[Guardaespaldas de alquiler]],level=35,minLevel=30,giver=[[Cork Gizelton]],giverType=[[NPC]],giverId=11625,ender=[[Smeed Scrabblescrew]],ender_loc=[[Smeed Mezclatornillos]],enderType=[[NPC]],enderId=11596,poiX=-1402,poiY=1497,wowhead=[[https://www.wowhead.com/wotlk/quest=5821]],image=[[assets/images/quests/placeholder.png]],desc=[[Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop. It's not good for business to be dead! I'll tell you what $c, if you protect us past the Kolkar village we'll make it worth your while. It's just a short distance, all you need to do is keep the caravan intact and you can pick up your reward from Smeed Scrabblescrew - he is down the road a bit. We do a little business together.]],logDesc=[[Escort the Gizelton Caravan past the Kolkar Centaur village. Talk with Smeed at Scrabblescrew's Camp for your reward.]],rewards={{id=15689,qty=1}}}
DB[5841]={id=5841,zoneId=132,name=[[Welcome!]],name_loc=[[¡Te damos la bienvenida!]],level=1,minLevel=1,giverType=[[NPC]],ender=[[Yori Crackhelm]],ender_loc=[[Yori Yelmopartido]],enderType=[[NPC]],enderId=11941,poiX=-5581,poiY=-541,wowhead=[[https://www.wowhead.com/wotlk/quest=5841]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome to the World of Warcraft! As special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Yori Crackhelm in Kharanos.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory. Thanks again, and enjoy your stay in the World of Warcraft!]],logDesc=[[Bring the Kharanos Gift Voucher to Yori Crackhelm in Kharanos.]],choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}}
DB[5842]={id=5842,zoneId=188,name=[[Welcome!]],name_loc=[[¡Te damos la bienvenida!]],level=1,minLevel=1,giverType=[[NPC]],ender=[[Orenthil Whisperwind]],ender_loc=[[Orenthil Susurravientos]],enderType=[[NPC]],enderId=11942,poiX=9840,poiY=946,wowhead=[[https://www.wowhead.com/wotlk/quest=5842]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome to the World of Warcraft! As special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Orenthil Whisperwind in Dolanaar.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory. Thanks again, and enjoy your stay in the World of Warcraft!]],logDesc=[[Bring the Dolanaar Gift Voucher to Orenthil Whisperwind in Dolanaar.]],choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}}
DB[5843]={id=5843,zoneId=363,name=[[Welcome!]],name_loc=[[¡Te damos la bienvenida!]],level=1,minLevel=1,giverType=[[NPC]],ender=[[Magga]],enderType=[[NPC]],enderId=11943,poiX=350,poiY=-4676,wowhead=[[https://www.wowhead.com/wotlk/quest=5843]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome to the World of Warcraft! As special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Magga in Razor Hill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory. Thanks again, and enjoy your stay in the World of Warcraft!]],logDesc=[[Bring the Razor Hill Gift Voucher to Magga in Razor Hill.]],choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}}
DB[5844]={id=5844,zoneId=221,name=[[Welcome!]],name_loc=[[¡Te damos la bienvenida!]],level=1,minLevel=1,giverType=[[NPC]],ender=[[Vorn Skyseer]],ender_loc=[[Vorn Vidente del Cielo]],enderType=[[NPC]],enderId=11944,poiX=-2328,poiY=-382,wowhead=[[https://www.wowhead.com/wotlk/quest=5844]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome to the World of Warcraft! As special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Vorn Skyseer in Bloodhoof Village.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory. Thanks again, and enjoy your stay in the World of Warcraft!]],logDesc=[[Bring the Bloodhoof Village Gift Voucher to Vorn Skyseer in Bloodhoof Village.]],choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}}
DB[5845]={id=5845,zoneId=139,name=[[Of Lost Honor]],name_loc=[[Del honor perdido]],level=58,minLevel=52,giver=[[Tirion Fordring]],giver_loc=[[Tirion Vadín]],giverType=[[NPC]],giverId=1855,ender=[[Tirion Fordring]],ender_loc=[[Tirion Vadín]],enderType=[[NPC]],enderId=1855,prevId=5781,rewardNextId=5846,poiX=2674,poiY=-2477,wowhead=[[https://www.wowhead.com/wotlk/quest=5845]],image=[[assets/images/quests/placeholder.png]],desc=[[The Order of the Silver Hand was utterly decimated when Uther was slain. The boy held out for as long as he could. Pushed to the war torn hamlet of Northdale, he made his final stand. Were any of the Order left alive, he thought - and did it matter? It was with that thought that Taelan threw down the standard of the Order and renounced all that he had known. His honor left upon the blood soaked ground of Northdale. You must travel to Northdale and recover that symbol of lost honor.]],logDesc=[[Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.]]}
DB[5846]={id=5846,zoneId=139,name=[[Of Love and Family]],name_loc=[[Del amor y la familia]],level=58,minLevel=52,giver=[[Tirion Fordring]],giver_loc=[[Tirion Vadín]],giverType=[[NPC]],giverId=1855,ender=[[Artist Renfray]],ender_loc=[[Artista Renfray]],enderType=[[NPC]],enderId=11936,prevId=5845,rewardNextId=5848,poiX=1206,poiY=-2412,wowhead=[[https://www.wowhead.com/wotlk/quest=5846]],image=[[assets/images/quests/placeholder.png]],desc=[[When Taelan was a child, we would oft visit Caer Darrow on family excursions. On our last visit, an artist by the name of Renfray painted a portrait of us poised along the beachside. It is my fondest memory of both Taelan and Karandra. For it was at that moment, with my wife and son in my arms, that I felt a bond of love and family that I would never know again. If this painting still exists, you must find it. Travel to the ruined island of Caer Darrow and see if the painting or the artist remain.]],logDesc=[[Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting.]]}
DB[5847]={id=5847,zoneId=154,name=[[Welcome!]],name_loc=[[¡Te damos la bienvenida!]],level=1,minLevel=1,giverType=[[NPC]],ender=[[Claire Willower]],ender_loc=[[Claire Sauzal]],enderType=[[NPC]],enderId=11945,poiX=2286,poiY=248,wowhead=[[https://www.wowhead.com/wotlk/quest=5847]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome to the World of Warcraft! As special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Claire Willower in Brill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory. Thanks again, and enjoy your stay in the World of Warcraft!]],logDesc=[[Bring the Brill Gift Voucher to Claire Willower in Brill.]],choiceRewards={{id=13584,qty=1},{id=13583,qty=1},{id=13582,qty=1}}}
DB[5848]={id=5848,zoneId=2017,name=[[Of Love and Family]],name_loc=[[Del amor y la familia]],level=60,minLevel=52,giver=[[Artist Renfray]],giver_loc=[[Artista Renfray]],giverType=[[NPC]],giverId=11936,ender=[[Tirion Fordring]],ender_loc=[[Tirion Vadín]],enderType=[[NPC]],enderId=1855,prevId=5846,rewardNextId=5861,poiX=2674,poiY=-2477,wowhead=[[https://www.wowhead.com/wotlk/quest=5848]],image=[[assets/images/quests/placeholder.png]],desc=[[The painting... It hung on the wall of my workshop - inside the Order's barracks - for years. After Tirion's trial was over, I knew that I could no longer keep the painting visible. I hid it in a place that they would never think to look. Travel to Stratholme and make your way deep inside what is now the Scarlet Bastion, search for a painting of our twin moons. Chip away at the paint until you uncover my master work, 'Of Love and Family.' May the Light guide your actions.]],logDesc=[[Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world. Return the painting to Tirion Fordring.]]}
DB[5861]={id=5861,zoneId=28,name=[[Find Myranda]],name_loc=[[Encuentra a Myranda]],level=60,minLevel=52,giver=[[Tirion Fordring]],giver_loc=[[Tirion Vadín]],giverType=[[NPC]],giverId=1855,ender=[[Myranda the Hag]],ender_loc=[[Myranda la Fada]],enderType=[[NPC]],enderId=11872,prevId=5848,rewardNextId=5862,poiX=1135,poiY=-1767,wowhead=[[https://www.wowhead.com/wotlk/quest=5861]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you have done all that I have asked thus far. Only one step remains in your quest of redemption. You must deliver the items you have collected to Taelan. Unfortunately, Taelan and his Scarlet Crusaders will attack you on sight. There is only one way in which to deliver my message and that is through a guise of deception. To the south you will find Uther's tomb. An old and trusted confidant of mine, Myranda, now resides there - seek her out. Show her the items and she will assist you.]],logDesc=[[Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift.]]}
DB[5862]={id=5862,zoneId=28,name=[[Scarlet Subterfuge]],name_loc=[[El subterfugio Escarlata]],level=60,minLevel=52,giver=[[Myranda the Hag]],giver_loc=[[Myranda la Fada]],giverType=[[NPC]],giverId=11872,ender=[[Highlord Taelan Fordring]],ender_loc=[[Alto señor Taelan Vadín]],enderType=[[NPC]],enderId=1842,prevId=5861,poiX=2943,poiY=-1390,wowhead=[[https://www.wowhead.com/wotlk/quest=5862]],image=[[assets/images/quests/placeholder.png]],desc=[[I am what you would call, an illusionist. Though I may be able to create an illusion to allow you entry into Hearthglen, be warned; my powers have their limitations. Should you travel too far from these lands, the effects of the illusion will cease. The spell itself takes a great amount of concentration and power from me, and thus, I can only sustain the effect for a short time. Speak to me again when you are ready.]],logDesc=[[Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring. Hearthglen is to the north, Taelan should be inside of Mardenholde Keep.]]}
DB[5863]={id=5863,zoneId=440,name=[[The Dunemaul Compound]],name_loc=[[La Base Machacaduna]],level=49,minLevel=44,giver=[[Andi Lynn]],giverType=[[NPC]],giverId=11758,ender=[[Andi Lynn]],enderType=[[NPC]],enderId=11758,poiX=-8396,poiY=-3179,wowhead=[[https://www.wowhead.com/wotlk/quest=5863]],image=[[assets/images/quests/placeholder.png]],desc=[[Just recently, a large band of nomadic ogres arrived in Tanaris. South of here, they have taken over a large area of the desert and formed a compound. Several smaller bands are currently wandering the desert, some of which have invaded the old troll ruins. The Dunemaul Compound must be destroyed! We cannot allow these ogres to build up a force. The leader of this band is named Gor'marok the Ravager; I believe that putting an end to his leadership will be the beginning of the end for the ogres.]],logDesc=[[Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.]],choiceRewards={{id=16738,qty=1},{id=16739,qty=1}}}
DB[5881]={id=5881,zoneId=406,name=[[Calling in the Reserves]],name_loc=[[La sustitución]],level=28,minLevel=23,giver=[[Maggran Earthbinder]],giver_loc=[[Maggran Vinculador Terrestre]],giverType=[[NPC]],giverId=11860,ender=[[Grish Longrunner]],ender_loc=[[Grish Largo Camino]],enderType=[[NPC]],enderId=12576,poiX=-4602,poiY=-1835,wowhead=[[https://www.wowhead.com/wotlk/quest=5881]],image=[[assets/images/quests/placeholder.png]],desc=[[The Horde does well keeping our troops fresh... since the Great War we have been prosperous here in Kalimdor. I need you to do me a favor, I have a lad by the name of Grish Longrunner protecting the Great Lift in the southern barrens. Give him this letter; the letter will let him know that I have a reserve warrior coming to relieve him of duty so that he can visit his family. He requested this sometime ago and he would be happy to hear the news.]],logDesc=[[Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens.]]}
