DB[5892]={id=5892,zoneId=2597,name=[[Irondeep Supplies]],name_loc=[[Suministros de Ferrohondo]],level=-1,minLevel=51,giver=[[Stormpike Quartermaster]],giver_loc=[[Intendente Pico Tormenta]],giverType=[[NPC]],giverId=12096,ender=[[Stormpike Quartermaster]],ender_loc=[[Intendente Pico Tormenta]],enderType=[[NPC]],enderId=12096,poiX=900,poiY=-479,wowhead=[[https://www.wowhead.com/wotlk/quest=5892]],image=[[assets/images/quests/placeholder.png]],desc=[[Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine.  The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep. We need the supplies in Irondeep, $N.  Enter the mine and bring me a load of them.]],logDesc=[[Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar.]]}
DB[5893]={id=5893,zoneId=2597,name=[[Coldtooth Supplies]],name_loc=[[Suministros de Dentefrío]],level=-1,minLevel=51,giver=[[Frostwolf Quartermaster]],giver_loc=[[Intendente Lobo Gélido]],giverType=[[NPC]],giverId=12097,ender=[[Frostwolf Quartermaster]],ender_loc=[[Intendente Lobo Gélido]],enderType=[[NPC]],enderId=12097,poiX=-948,poiY=-209,wowhead=[[https://www.wowhead.com/wotlk/quest=5893]],image=[[assets/images/quests/placeholder.png]],desc=[[The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it.  And so, control of the mine often falls to the Alliance, or to underground denizens... But we still need our supplies, $N!  Go to the Coldtooth mine and bring me a load of them.  And be wary of enemies as you go; the tides of battle shift quickly in that place...]],logDesc=[[Bring 10 Coldtooth Supplies to the Horde Quatermaster in Frostwolf Keep.]]}
DB[5901]={id=5901,zoneId=139,name=[[A Plague Upon Thee]],name_loc=[[Una Peste en la Cruzada]],level=55,minLevel=48,giver=[[Mickey Levine]],giverType=[[NPC]],giverId=11615,ender=[[Mickey Levine]],enderType=[[NPC]],enderId=11615,rewardNextId=5902,poiX=1658,poiY=-730,wowhead=[[https://www.wowhead.com/wotlk/quest=5901]],image=[[assets/images/quests/placeholder.png]],desc=[[So, to bring pain and strife to the Scarlet Crusade, I want to take their precious lumber mill from them. I'm sure the loss of such a resource will cause them a great deal of harm in defending and rebuilding the town for their own reasons. Will you help me, $N? Start by taking this jar to Plaguewood in the Eastern Plaguelands. Fill it with the termites you find in their mounds throughout the woods. Come back when you have enough.]],logDesc=[[Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Mickey Levine at the Bulwark in Tirisfal Glades.]]}
DB[5902]={id=5902,zoneId=85,name=[[A Plague Upon Thee]],name_loc=[[Una Peste en la Cruzada]],level=55,minLevel=48,giver=[[Mickey Levine]],giverType=[[NPC]],giverId=11615,ender=[[Termite Barrel]],ender_loc=[[Barrica de termitas]],enderType=[[GO]],enderId=177491,prevId=5901,rewardNextId=6390,poiX=2449,poiY=-1662,wowhead=[[https://www.wowhead.com/wotlk/quest=5902]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we have plenty of termites, take this steel reinforced barrel to the Northridge Lumber Mill south of Hearthglen--you'll find it to the west of the road that leads you up to the town. Once there, place the barrel in the center of the lumber mill; someplace high, like on a crate or something. After you open it, the rest should take care of itself. Just come back here and I'll reward you for helping me.]],logDesc=[[Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.]]}
DB[5903]={id=5903,zoneId=139,name=[[A Plague Upon Thee]],name_loc=[[Una Peste en la Cruzada]],level=55,minLevel=48,giver=[[Nathaniel Dumah]],giver_loc=[[Nathaniel Dumah]],giverType=[[NPC]],giverId=11616,ender=[[Nathaniel Dumah]],ender_loc=[[Nathaniel Dumah]],enderType=[[NPC]],enderId=11616,rewardNextId=5904,poiX=935,poiY=-1450,wowhead=[[https://www.wowhead.com/wotlk/quest=5903]],image=[[assets/images/quests/placeholder.png]],desc=[[I've tried many times to rout out the Scarlet Crusade through force alone, but to no avail. So, as an alternative, I've decided to make their lives more difficult. If you are willing to help, I want to infest that lumber mill with the most terrible species of termites ever found. In Plaguewood, near the once-great Stratholme, there is a breed that survived the plague and the Scourge combined. Find their mounds and fill this jar with them, so we can prepare them to be unleashed on the Crusade.]],logDesc=[[Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.]]}
DB[5904]={id=5904,zoneId=28,name=[[A Plague Upon Thee]],name_loc=[[Una Peste en la Cruzada]],level=55,minLevel=48,giver=[[Nathaniel Dumah]],giver_loc=[[Nathaniel Dumah]],giverType=[[NPC]],giverId=11616,ender=[[Termite Barrel]],ender_loc=[[Barrica de termitas]],enderType=[[GO]],enderId=177491,prevId=5903,rewardNextId=6389,poiX=2449,poiY=-1662,wowhead=[[https://www.wowhead.com/wotlk/quest=5904]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we have the termites, take this steel reinforced barrel to the Northridge Lumber Mill south of Hearthglen--you'll find it to the west of the road that leads you up to the town. Once there, place the barrel in the center of the lumber mill; find someplace suitable, like on a crate and then open it. The termites should do their work from there and make the mill useless to the Crusade.]],logDesc=[[Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.]]}
DB[5921]={id=5921,name=[[Moonglade]],name_loc=[[Claro de la Luna]],level=-1,minLevel=10,giver=[[Mathrengyl Bearwalker]],giver_loc=[[Mathrengyl Garroso]],giverType=[[NPC]],giverId=4217,ender=[[Dendrite Starblaze]],ender_loc=[[Dendrita Rafagaestelar]],enderType=[[NPC]],enderId=11802,nextId=5929,rewardNextId=5929,poiX=8020,poiY=-2679,wowhead=[[https://www.wowhead.com/wotlk/quest=5921]],image=[[assets/images/quests/placeholder.png]],desc=[[All druids are welcome in the sacred lands of Moonglade, regardless of the current tensions in the Cenarion Circle between Arch Druid Staghelm and Keeper Remulos - Moonglade's guardian.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace. As for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, young druid.]],logDesc=[[Use the spell "Teleport: Moonglade" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.]]}
DB[5922]={id=5922,name=[[Moonglade]],name_loc=[[Claro de la Luna]],level=-1,minLevel=10,giver=[[Turak Runetotem]],giver_loc=[[Turak Tótem de Runa]],giverType=[[NPC]],giverId=3033,ender=[[Dendrite Starblaze]],ender_loc=[[Dendrita Rafagaestelar]],enderType=[[NPC]],enderId=11802,nextId=5930,rewardNextId=5930,poiX=8020,poiY=-2679,wowhead=[[https://www.wowhead.com/wotlk/quest=5922]],image=[[assets/images/quests/placeholder.png]],desc=[[All druids are welcomed to the sacred lands of Moonglade, tauren and night elf alike.  Keeper Remulos - Moonglade's guardian - keeps watch over all druids who hibernate there.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace. As for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, young druid.]],logDesc=[[Use the spell "Teleport: Moonglade" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.]]}
DB[5923]={id=5923,name=[[Heeding the Call]],name_loc=[[Escucha la llamada]],level=-1,minLevel=10,giver=[[Kal]],giver_loc=[[Kal]],giverType=[[NPC]],giverId=3602,ender=[[Mathrengyl Bearwalker]],ender_loc=[[Mathrengyl Garroso]],enderType=[[NPC]],enderId=4217,rewardNextId=5921,exGroup=5923,poiX=10179,poiY=2564,wowhead=[[https://www.wowhead.com/wotlk/quest=5923]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me, friend... It has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil. He is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.]],logDesc=[[Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.]]}
DB[5924]={id=5924,name=[[Heeding the Call]],name_loc=[[Escucha la llamada]],level=-1,minLevel=10,giver=[[Theridran]],giver_loc=[[Theridran]],giverType=[[NPC]],giverId=5505,ender=[[Mathrengyl Bearwalker]],ender_loc=[[Mathrengyl Garroso]],enderType=[[NPC]],enderId=4217,rewardNextId=5921,exGroup=5923,poiX=10179,poiY=2564,wowhead=[[https://www.wowhead.com/wotlk/quest=5924]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me, friend... It has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil. He is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.]],logDesc=[[Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.]]}
