DB[6068]={id=6068,name=[[The Hunter's Path]],name_loc=[[El camino del cazador]],level=-1,minLevel=10,giver=[[Kary Thunderhorn]],giver_loc=[[Kary Tronacuerno]],giverType=[[NPC]],giverId=3038,ender=[[Thotar]],ender_loc=[[Thotar]],enderType=[[NPC]],enderId=3171,rewardNextId=6062,exGroup=6068,poiX=275,poiY=-4704,wowhead=[[https://www.wowhead.com/wotlk/quest=6068]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion. You must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own.]],logDesc=[[Speak with Thotar at Razor Hill in Durotar.]]}
