DB[6661]={id=6661,zoneId=2257,name=[[Deeprun Rat Roundup]],name_loc=[[A por las ratas del tranvía subterráneo]],level=12,minLevel=10,giver=[[Monty]],giver_loc=[[Monty]],giverType=[[NPC]],giverId=12997,ender=[[Monty]],ender_loc=[[Monty]],enderType=[[NPC]],enderId=12997,poiX=-42,poiY=-35,wowhead=[[https://www.wowhead.com/wotlk/quest=6661]],image=[[assets/images/quests/placeholder.png]],desc=[[Avast ye scallywag. Arrrr... Arrrr ye looking fer work? We gots a serious rat problem down here an' not enough hands on the poop deck. What do ye say? All ye needs to do is take this here rat catchin' flute and play the melody around the vermin. They'll follow ye to the ends of the world! Just capture five of the little buggers and bring em back here. We needs em alive. Arrrrr...]],logDesc=[[Capture 5 Deeprun Rats by using the Rat Catcher's Flute. Lead the rats back to Monty. Don't forget to turn in the flute when you're finished.]]}
DB[6662]={id=6662,zoneId=2257,name=[[Me Brother, Nipsy]],name_loc=[[Mi hermano Niblis]],level=12,minLevel=10,giver=[[Monty]],giver_loc=[[Monty]],giverType=[[NPC]],giverId=12997,ender=[[Nipsy]],ender_loc=[[Niblis]],enderType=[[NPC]],enderId=13018,prevId=6661,poiX=-4838,poiY=-1318,wowhead=[[https://www.wowhead.com/wotlk/quest=6662]],image=[[assets/images/quests/placeholder.png]],desc=[[Me brother, Nipsy, runs a rat kabob operation on the other side of Deeprun. Ye needs to take this here crate o' rats to him before they go bad. Get a move on! Ye have ridden a tram before, aye? It's easy. Just step aboard when she arrives and enjoy the ride. An' keep yer arms and legs inside durin' the ride, lest ye be peglegged fer life.]],logDesc=[[Take the Carton of Mystery Meat to Nipsy at the Stormwind Deeprun Tram Depot.]],rewards={{id=17119,qty=10}}}
DB[6681]={id=6681,name=[[The Manor, Ravenholdt]],name_loc=[[Mansión Ravenholdt]],level=24,minLevel=24,giverType=[[NPC]],ender=[[Fahrad]],ender_loc=[[Fahrad]],enderType=[[NPC]],enderId=6707,nextId=6701,poiX=107,poiY=-1492,wowhead=[[https://www.wowhead.com/wotlk/quest=6681]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, Ravenholdt has taken an interest in you, young thief. We have been watching. Your style is a bit awkward but nothing we couldn't fix. Should you be prepared to embark on a career as a disciple of Master Ravenholdt and member of the Assassin's League, you have only to bring the Seal of Ravenholdt (attached to this letter) to Ravenholdt Manor. Your first task is to find the manor, hidden away in the hills of Hillsbrad and demonstrate your cunning. Regards, Fahrad]],logDesc=[[Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad. Your cunning will be tested along the way. Be prepared.]]}
DB[6701]={id=6701,name=[[Syndicate Emblems]],name_loc=[[Emblemas de la Hermandad]],level=60,minLevel=24,giver=[[Ravenholdt Guard]],giver_loc=[[Guardia de Ravenholdt]],giverType=[[NPC]],giverId=6766,ender=[[Ravenholdt Guard]],ender_loc=[[Guardia de Ravenholdt]],enderType=[[NPC]],enderId=6766,prevId=6681,poiX=-15,poiY=-584,wowhead=[[https://www.wowhead.com/wotlk/quest=6701]],image=[[assets/images/quests/placeholder.png]]}
DB[6721]={id=6721,zoneId=1537,name=[[The Hunter's Path]],name_loc=[[El camino del cazador]],level=-1,minLevel=10,giver=[[Regnus Thundergranite]],giver_loc=[[Regnus Tronagranito]],giverType=[[NPC]],giverId=5117,ender=[[Dazalar]],ender_loc=[[Dazalar]],enderType=[[NPC]],enderId=3601,rewardNextId=6063,exGroup=6071,poiX=9812,poiY=929,wowhead=[[https://www.wowhead.com/wotlk/quest=6721]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion. You must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own. ]],logDesc=[[Speak with Dazalar at Dolanaar in Teldrassil.]]}
DB[6722]={id=6722,zoneId=131,name=[[The Hunter's Path]],name_loc=[[El camino del cazador]],level=-1,minLevel=10,giver=[[Einris Brightspear]],giver_loc=[[Einris Lanza Reluciente]],giverType=[[NPC]],giverId=5515,ender=[[Dazalar]],ender_loc=[[Dazalar]],enderType=[[NPC]],enderId=3601,rewardNextId=6063,exGroup=6071,poiX=9812,poiY=929,wowhead=[[https://www.wowhead.com/wotlk/quest=6722]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion. You must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.]],logDesc=[[Speak with Dazalar at Dolanaar in Teldrassil.]]}
DB[6741]={id=6741,zoneId=2597,name=[[More Booty!]],name_loc=[[¡Más botines!]],level=-1,minLevel=51,giver=[[Smith Regzar]],giver_loc=[[Herrero Regzar]],giverType=[[NPC]],giverId=13176,ender=[[Smith Regzar]],ender_loc=[[Herrero Regzar]],enderType=[[NPC]],enderId=13176,prevId=7224,poiX=-1252,poiY=-316,wowhead=[[https://www.wowhead.com/wotlk/quest=6741]],image=[[assets/images/quests/placeholder.png]]}
DB[6761]={id=6761,zoneId=1657,name=[[The New Frontier]],name_loc=[[La nueva frontera]],level=55,minLevel=54,giver=[[Arch Druid Fandral Staghelm]],giver_loc=[[Archidruida Fandral Corzocelada]],giverType=[[NPC]],giverId=3516,ender=[[Mathrengyl Bearwalker]],ender_loc=[[Mathrengyl Garroso]],enderType=[[NPC]],enderId=4217,rewardNextId=6762,poiX=10179,poiY=2564,wowhead=[[https://www.wowhead.com/wotlk/quest=6761]],image=[[assets/images/quests/placeholder.png]],desc=[[I have relegated my second, Mathrengyl Bearwalker, to deal with Moonglade's call for aid.  Speak to him on this matter - NOT me. Let me give you some... friendly... advice.  It is I who led us out of the darkness - NOT the Cenarion Circle in Moonglade - when all was lost for our race.  Teldrassil gives us all new life!  They would have you believe otherwise, and to believe their propaganda would be a fool's task. I'll leave it to you to decide whether or not you're a fool.]],logDesc=[[Speak with Mathrengyl Bearwalker at the Cenarion Enclave of Darnassus.]]}
DB[6762]={id=6762,zoneId=1657,name=[[Rabine Saturna]],name_loc=[[Rabine Saturna]],level=55,minLevel=54,giver=[[Mathrengyl Bearwalker]],giver_loc=[[Mathrengyl Garroso]],giverType=[[NPC]],giverId=4217,ender=[[Rabine Saturna]],enderType=[[NPC]],enderId=11801,prevId=6761,nextId=1124,rewardNextId=1124,poiX=7797,poiY=-2574,wowhead=[[https://www.wowhead.com/wotlk/quest=6762]],image=[[assets/images/quests/placeholder.png]],desc=[[For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris... and even further west of Un'Goro.  You should find him in Nighthaven, the main village of Moonglade. While your work will no doubt be of tremendous benefit to us all, I advise you to tread gingerly.  There are tensions between Darnassus and Moonglade... ones that may grow over the course of time.]],logDesc=[[Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.]]}
DB[6781]={id=6781,zoneId=2597,name=[[More Armor Scraps]],name_loc=[[Más restos de armadura]],level=-1,minLevel=51,giver=[[Murgot Deepforge]],giver_loc=[[Murgot Forjahonda]],giverType=[[NPC]],giverId=13257,ender=[[Murgot Deepforge]],ender_loc=[[Murgot Forjahonda]],enderType=[[NPC]],enderId=13257,prevId=7223,poiX=648,poiY=-61,wowhead=[[https://www.wowhead.com/wotlk/quest=6781]],image=[[assets/images/quests/placeholder.png]]}
DB[6801]={id=6801,zoneId=2597,name=[[Lokholar the Ice Lord]],name_loc=[[Lokholar, el Señor del Hielo]],level=-1,minLevel=51,giver=[[Primalist Thurloga]],giver_loc=[[Primalista Thurloga]],giverType=[[NPC]],giverId=13236,ender=[[Primalist Thurloga]],ender_loc=[[Primalista Thurloga]],enderType=[[NPC]],enderId=13236,poiX=-1320,poiY=-343,wowhead=[[https://www.wowhead.com/wotlk/quest=6801]],image=[[assets/images/quests/placeholder.png]]}
DB[6804]={id=6804,zoneId=16,name=[[Poisoned Water]],name_loc=[[Agua envenenada]],level=56,minLevel=55,giverType=[[NPC]],ender=[[Duke Hydraxis]],ender_loc=[[Duque Hydraxis]],enderType=[[NPC]],enderId=13278,poiX=2850,poiY=-7297,wowhead=[[https://www.wowhead.com/wotlk/quest=6804]],image=[[assets/images/quests/placeholder.png]],desc=[[A force of elemental scouts was sent to the eastern plaguelands of Lordaeron, and the disease of that place twisted and infected them.  The Waterlords cannot allow this affront to our purity! Take this vial.  In it is a quantity of one aspect of Neptulon.  If used on the plagued elementals it will fight the poison within their bodies and cure them!  But their inner conflict will drive them into a surging madness. Defeat the discordant surges and bring me their bracers of binding.]],logDesc=[[Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands.  Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara.]]}
DB[6805]={id=6805,zoneId=16,name=[[Stormers and Rumblers]],name_loc=[[Sirocosos y reptarenas]],level=57,minLevel=55,giver=[[Duke Hydraxis]],giver_loc=[[Duque Hydraxis]],giverType=[[NPC]],giverId=13278,ender=[[Duke Hydraxis]],ender_loc=[[Duque Hydraxis]],enderType=[[NPC]],enderId=13278,poiX=-6249,poiY=1317,wowhead=[[https://www.wowhead.com/wotlk/quest=6805]],image=[[assets/images/quests/placeholder.png]],desc=[[We, the elementals of water, wage war with those beings of the lesser elements.  If you are truly our ally in this conflict, then show me your conviction! Far to the south, in the desert land of Silithus, the servants of air and earth scurry in a corner of rock named the Crystal Vale.  They protect items of power from smaller beings, mortals, and although I do not know why they do this, I wish to foil their efforts. Go to the Crystal Vale in Silithus and defeat our enemies, then return to me.]],logDesc=[[Kill 15 Dust Stormers and 15 Desert Rumblers and then return to Duke Hydraxis in Azshara.]]}
DB[6821]={id=6821,zoneId=16,name=[[Eye of the Emberseer]],name_loc=[[Ojo del Brasadivino]],level=60,minLevel=55,giver=[[Duke Hydraxis]],giver_loc=[[Duque Hydraxis]],giverType=[[NPC]],giverId=13278,ender=[[Duke Hydraxis]],ender_loc=[[Duque Hydraxis]],enderType=[[NPC]],enderId=13278,prevId=6805,nextId=6822,rewardNextId=6822,poiX=2850,poiY=-7297,wowhead=[[https://www.wowhead.com/wotlk/quest=6821]],image=[[assets/images/quests/placeholder.png]],desc=[[You have shown me that you can defeat our enemies and perform missions to further the cause of the Waterlords.  But until now you have only faced lesser foes... if pitted against a powerful enemy, can you prevail? That is your new task. High up in Blackrock Spire the orcs have captured a servant of fire, the Pyroguard Emberseer.  Find his place of imprisonment, slay his captors, and then slay the emberseer.  Bring me his eye and it will show me your worth.]],logDesc=[[Bring the Eye of the Emberseer to Duke Hydraxis in Azshara.]]}
DB[6822]={id=6822,zoneId=16,name=[[The Molten Core]],name_loc=[[El Núcleo de Magma]],level=60,minLevel=55,giver=[[Duke Hydraxis]],giver_loc=[[Duque Hydraxis]],giverType=[[NPC]],giverId=13278,ender=[[Duke Hydraxis]],ender_loc=[[Duque Hydraxis]],enderType=[[NPC]],enderId=13278,prevId=6021,nextId=6823,rewardNextId=6823,poiX=2850,poiY=-7297,wowhead=[[https://www.wowhead.com/wotlk/quest=6822]],image=[[assets/images/quests/placeholder.png]],desc=[[$n, perhaps it is time to give you a real test.  Are you ready? At the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world. Go to the Molten Core, $N.  Show me you have the strength and the will to defeat what you find there. And if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live.]],logDesc=[[Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.]]}
DB[6823]={id=6823,zoneId=16,name=[[Agent of Hydraxis]],name_loc=[[Agente de Hydraxis]],level=60,minLevel=55,giver=[[Duke Hydraxis]],giver_loc=[[Duque Hydraxis]],giverType=[[NPC]],giverId=13278,ender=[[Duke Hydraxis]],ender_loc=[[Duque Hydraxis]],enderType=[[NPC]],enderId=13278,prevId=6022,nextId=6824,rewardNextId=6824,poiX=2850,poiY=-7297,wowhead=[[https://www.wowhead.com/wotlk/quest=6823]],image=[[assets/images/quests/placeholder.png]],desc=[[If you truly wish an allegiance with us, then I invite you to wage war on our foes, the servants of air and earth and fire.  Each defeat you heap upon them will weaken their foothold here, and further prove your adherence to our cause. The campaign will be long, but if you persevere then your glory and honor will be great.]],logDesc=[[Earn an Honored faction with the Hydraxian Waterlords, then talk to Duke Hydraxis in Azshara.]]}
DB[6824]={id=6824,zoneId=16,name=[[Hands of the Enemy]],name_loc=[[Las manos de los enemigos]],level=60,minLevel=55,giver=[[Duke Hydraxis]],giver_loc=[[Duque Hydraxis]],giverType=[[NPC]],giverId=13278,ender=[[Duke Hydraxis]],ender_loc=[[Duque Hydraxis]],enderType=[[NPC]],enderId=13278,prevId=6823,nextId=7486,poiX=2850,poiY=-7297,wowhead=[[https://www.wowhead.com/wotlk/quest=6824]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, your service is of great value to us, so we are reluctant to send you on this last mission for we do not want to lose such a useful agent. But its success would further our war efforts tremendously and... it was deemed worth risking you. We want these captains in the Molten Core destroyed: Lucifron, Sulfuron, Gehennas and Shazzrah.  Kill them and bring me their hands! This task will take every resource you possess, $N, but if can do it then the Firelords will be dealt a terrible blow.]],logDesc=[[Bring the Hands of Lucifron, Sulfuron, Gehennas and Shazzrah to Duke Hydraxis in Azshara.]]}
DB[6825]={id=6825,zoneId=2597,name=[[Call of Air - Guse's Fleet]],name_loc=[[La llamada del aire: flota de Guse]],level=-1,minLevel=51,giver=[[Wing Commander Guse]],giver_loc=[[Comandante del aire Guse]],giverType=[[NPC]],giverId=13179,ender=[[Wing Commander Guse]],ender_loc=[[Comandante del aire Guse]],enderType=[[NPC]],enderId=13179,poiX=211,poiY=-357,wowhead=[[https://www.wowhead.com/wotlk/quest=6825]],image=[[assets/images/quests/placeholder.png]]}
DB[6826]={id=6826,zoneId=2597,name=[[Call of Air - Jeztor's Fleet]],name_loc=[[La llamada del aire: flota de Jeztor]],level=-1,minLevel=51,giver=[[Wing Commander Jeztor]],giver_loc=[[Comandante del aire Jeztor]],giverType=[[NPC]],giverId=13180,ender=[[Wing Commander Jeztor]],ender_loc=[[Comandante del aire Jeztor]],enderType=[[NPC]],enderId=13180,poiX=320,poiY=-503,wowhead=[[https://www.wowhead.com/wotlk/quest=6826]],image=[[assets/images/quests/placeholder.png]]}
DB[6827]={id=6827,zoneId=2597,name=[[Call of Air - Mulverick's Fleet]],name_loc=[[La llamada del aire: flota de Mulverick]],level=-1,minLevel=51,giver=[[Wing Commander Mulverick]],giver_loc=[[Comandante del aire Mulverick]],giverType=[[NPC]],giverId=13181,ender=[[Wing Commander Mulverick]],ender_loc=[[Comandante del aire Mulverick]],enderType=[[NPC]],enderId=13181,poiX=674,poiY=-145,wowhead=[[https://www.wowhead.com/wotlk/quest=6827]],image=[[assets/images/quests/placeholder.png]]}
DB[6844]={id=6844,zoneId=1377,name=[[Umber, Archivist]],name_loc=[[Umber, el archivista]],level=57,minLevel=54,giver=[[Layo Starstrike]],giver_loc=[[Layo Estrella]],giverType=[[NPC]],giverId=13220,ender=[[Umber]],enderType=[[NPC]],enderId=11939,prevId=1126,rewardNextId=6845,poiX=7944,poiY=-2417,wowhead=[[https://www.wowhead.com/wotlk/quest=6844]],image=[[assets/images/quests/placeholder.png]],desc=[[There's plenty to do here still, but I think taking this back to the Circle for analysis is key.  Trust me - the work will still be here once this is all said and done.  If it's a journal inside this sticky chitin, then the Circle would finally have a window into the past! Take this to the Circle's archivist in Nighthaven.  His name is Umber, and the man's brilliant.  Touched, sure, but brilliant nonetheless!  Umber's salvaged tomes in far worse shape than this.  If it can be saved, he can do it.]],logDesc=[[Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade.]]}
DB[6845]={id=6845,zoneId=493,name=[[Uncovering Past Secrets]],name_loc=[[Desvelar los secretos del pasado]],level=57,minLevel=54,giver=[[Umber]],giverType=[[NPC]],giverId=11939,ender=[[Rabine Saturna]],enderType=[[NPC]],enderId=11801,prevId=6844,poiX=7797,poiY=-2574,wowhead=[[https://www.wowhead.com/wotlk/quest=6845]],image=[[assets/images/quests/placeholder.png]],desc=[[Anyway, you should check back with me relatively soon... that is if you want to know what was in here.  As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you. In the meantime, I'd check in with the den mother of this little bear camp, Rabine.  No doubt he'll want to know what crazy antics you've been up to.  Never leave the den mother waiting, $N... that is, unless you want to be doused in honey. It's happened, trust me.]],logDesc=[[Speak with Rabine Saturna in the village of Nighthaven, Moonglade.]],choiceRewards={{id=18400,qty=1},{id=18402,qty=1}}}
DB[6846]={id=6846,zoneId=2597,name=[[Begin the Attack!]],name_loc=[[¡Al ataque!]],level=-1,minLevel=1,giver=[[Field Marshal Teravaine]],giver_loc=[[Mariscal de campo Teravaine]],giverType=[[NPC]],giverId=13446,ender=[[Field Marshal Teravaine]],ender_loc=[[Mariscal de campo Teravaine]],enderType=[[NPC]],enderId=13446,poiX=-258,poiY=-418,wowhead=[[https://www.wowhead.com/wotlk/quest=6846]],image=[[assets/images/quests/placeholder.png]]}
DB[6847]={id=6847,zoneId=2597,name=[[Master Ryson's All Seeing Eye]],name_loc=[[El ojo que todo lo ve del maestro Ryson]],level=60,minLevel=51,giver=[[Syndicate Master Ryson]],giver_loc=[[Maestro de la Hermandad Ryson]],giverType=[[NPC]],giverId=13151,ender=[[Syndicate Master Ryson]],ender_loc=[[Maestro de la Hermandad Ryson]],enderType=[[NPC]],enderId=13151,poiX=-351,poiY=-656,wowhead=[[https://www.wowhead.com/wotlk/quest=6847]],image=[[assets/images/quests/placeholder.png]],desc=[[Your war in the heart of Alterac means nothing to the Syndicate, $c. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike. That, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region. Recover the Eye and our services shall be yours - for whatever time remains for your side. Return to me once you acquire the eye so that I may examine you. <Master Ryson grins.>]],logDesc=[[Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson. Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!]]}
DB[6848]={id=6848,zoneId=2597,name=[[Master Ryson's All Seeing Eye]],name_loc=[[El ojo que todo lo ve del maestro Ryson]],level=60,minLevel=50,giver=[[Syndicate Master Ryson]],giver_loc=[[Maestro de la Hermandad Ryson]],giverType=[[NPC]],giverId=13151,ender=[[Syndicate Master Ryson]],ender_loc=[[Maestro de la Hermandad Ryson]],enderType=[[NPC]],enderId=13151,poiX=-351,poiY=-656,wowhead=[[https://www.wowhead.com/wotlk/quest=6848]],image=[[assets/images/quests/placeholder.png]],desc=[[Your war in the heart of Alterac means nothing to the Syndicate, $c. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike. That, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region. Recover the Eye and our services shall be yours - for whatever time remains for your side. Return to me once you acquire the eye so that I may examine you. <Master Ryson grins.>]],logDesc=[[Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson. Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!]]}
DB[6861]={id=6861,zoneId=2597,name=[[Zinfizzlex's Portable Shredder Unit]],name_loc=[[La unidad trituradora portátil de Zinfizzlex]],level=60,minLevel=51,giver=[[Master Engineer Zinfizzlex]],giver_loc=[[Maestro ingeniero Zinfizzlex]],giverType=[[NPC]],giverId=13377,ender=[[Master Engineer Zinfizzlex]],ender_loc=[[Maestro ingeniero Zinfizzlex]],enderType=[[NPC]],enderId=13377,poiX=-151,poiY=72,wowhead=[[https://www.wowhead.com/wotlk/quest=6861]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm as anxious as you are to try out my portable shredder unit, $r, but before I can make the kit, I'm going to need materials - lots of materials! To be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill. When I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Stormpike lumber camp.]],logDesc=[[Master Engineer Zinfizzlex wants you to bring him the following: *30 Thorium Bars. *50 Mithril Bars. *75 Iron bars. *1 Steamsaw. ]],rewards={{id=17384,qty=1}}}
DB[6862]={id=6862,zoneId=2597,name=[[Zinfizzlex's Portable Shredder Unit]],name_loc=[[La unidad trituradora portátil de Zinfizzlex]],level=60,minLevel=51,giver=[[Master Engineer Zinfizzlex]],giver_loc=[[Maestro ingeniero Zinfizzlex]],giverType=[[NPC]],giverId=13377,ender=[[Master Engineer Zinfizzlex]],ender_loc=[[Maestro ingeniero Zinfizzlex]],enderType=[[NPC]],enderId=13377,poiX=-151,poiY=72,wowhead=[[https://www.wowhead.com/wotlk/quest=6862]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm as anxious as you are to try out my portable shredder unit, $r, but before I can make the kit, I'm going to need materials - lots of materials! To be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill. When I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Frostwolf lumber camp.]],logDesc=[[Master Engineer Zinfizzlex wants you to bring him the following: *30 Thorium Bars. *50 Mithril Bars. *75 Iron bars. *1 Steamsaw. ]],rewards={{id=17410,qty=1}}}
DB[6881]={id=6881,zoneId=2597,name=[[Ivus the Forest Lord]],name_loc=[[Ivus, el Señor del Bosque]],level=-1,minLevel=51,giver=[[Arch Druid Renferal]],giver_loc=[[Archidruida Renferal]],giverType=[[NPC]],giverId=13442,ender=[[Arch Druid Renferal]],ender_loc=[[Archidruida Renferal]],enderType=[[NPC]],enderId=13442,poiX=729,poiY=-79,wowhead=[[https://www.wowhead.com/wotlk/quest=6881]],image=[[assets/images/quests/placeholder.png]]}
DB[6901]={id=6901,zoneId=2597,name=[[Launch the Attack!]],name_loc=[[Lanzar el ataque]],level=-1,minLevel=1,giver=[[Warmaster Garrick]],giver_loc=[[Maestro de guerra Garrick]],giverType=[[NPC]],giverId=13449,ender=[[Warmaster Garrick]],ender_loc=[[Maestro de guerra Garrick]],enderType=[[NPC]],enderId=13449,poiX=-271,poiY=-147,wowhead=[[https://www.wowhead.com/wotlk/quest=6901]],image=[[assets/images/quests/placeholder.png]]}
DB[6921]={id=6921,zoneId=719,name=[[Amongst the Ruins]],name_loc=[[Entre ruinas]],level=27,minLevel=21,giver=[[Je'neu Sancrea]],giver_loc=[[Je'neu Sancrea]],giverType=[[NPC]],giverId=12736,ender=[[Je'neu Sancrea]],ender_loc=[[Je'neu Sancrea]],enderType=[[NPC]],enderId=12736,poiX=3355,poiY=1033,wowhead=[[https://www.wowhead.com/wotlk/quest=6921]],image=[[assets/images/quests/placeholder.png]],desc=[[The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good. $N, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!]],logDesc=[[Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.]]}
DB[6922]={id=6922,zoneId=331,name=[[Baron Aquanis]],name_loc=[[Barón Aquanis]],level=30,minLevel=21,giverType=[[NPC]],ender=[[Je'neu Sancrea]],ender_loc=[[Je'neu Sancrea]],enderType=[[NPC]],enderId=12736,poiX=3355,poiY=1033,wowhead=[[https://www.wowhead.com/wotlk/quest=6922]],image=[[assets/images/quests/placeholder.png]],desc=[[The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force. If anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.]],logDesc=[[Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.]],choiceRewards={{id=16886,qty=1},{id=16887,qty=1}}}
DB[6941]={id=6941,zoneId=2597,name=[[Call of Air - Vipore's Fleet]],name_loc=[[La llamada del aire: la flota de Vipore]],level=-1,minLevel=51,giver=[[Wing Commander Vipore]],giver_loc=[[Comandante del aire Vipore]],giverType=[[NPC]],giverId=13439,ender=[[Wing Commander Vipore]],ender_loc=[[Comandante del aire Vipore]],enderType=[[NPC]],enderId=13439,poiX=-1219,poiY=-353,wowhead=[[https://www.wowhead.com/wotlk/quest=6941]],image=[[assets/images/quests/placeholder.png]]}
