DB[7171]={id=7171,zoneId=2597,name=[[Legendary Heroes]],name_loc=[[Héroes legendarios]],level=-1,minLevel=51,giver=[[Lieutenant Haggerdin]],giver_loc=[[Teniente Haggerdin]],giverType=[[NPC]],giverId=13841,ender=[[Lieutenant Haggerdin]],ender_loc=[[Teniente Haggerdin]],enderType=[[NPC]],enderId=13841,prevId=7170,poiX=-16,poiY=-322,wowhead=[[https://www.wowhead.com/wotlk/quest=7171]],image=[[assets/images/quests/placeholder.png]],rewards={{id=17903,qty=1}}}
DB[7172]={id=7172,zoneId=2597,name=[[The Eye of Command]],name_loc=[[El ojo del orden]],level=-1,minLevel=51,giver=[[Lieutenant Haggerdin]],giver_loc=[[Teniente Haggerdin]],giverType=[[NPC]],giverId=13841,ender=[[Lieutenant Haggerdin]],ender_loc=[[Teniente Haggerdin]],enderType=[[NPC]],enderId=13841,prevId=7171,poiX=-16,poiY=-322,wowhead=[[https://www.wowhead.com/wotlk/quest=7172]],image=[[assets/images/quests/placeholder.png]],rewards={{id=17904,qty=1}}}
DB[7181]={id=7181,zoneId=2597,name=[[The Legend of Korrak]],name_loc=[[La leyenda de Korrak]],level=60,minLevel=51,giver=[[Warmaster Laggrond]],giver_loc=[[Maestro de guerra Laggrond]],giverType=[[NPC]],giverId=13840,ender=[[Warmaster Laggrond]],ender_loc=[[Maestro de guerra Laggrond]],enderType=[[NPC]],enderId=13840,poiX=401,poiY=-960,wowhead=[[https://www.wowhead.com/wotlk/quest=7181]],image=[[assets/images/quests/placeholder.png]],desc=[[The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power. They are lead by Korrak the Bloodrager - a cruel and cunning beast. A strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!]],logDesc=[[According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley. Should Korrak make himself known, destroy him and return to Warmaster Laggrond.]],rewards={{id=18149,qty=1}},choiceRewards={{id=19107,qty=1},{id=19106,qty=1},{id=19108,qty=1}}}
DB[7201]={id=7201,zoneId=1584,name=[[The Last Element]],name_loc=[[El último elemento]],level=54,minLevel=48,giver=[[Shadowmage Vivian Lagrave]],giver_loc=[[Maga oscura Vivian Lagrave]],giverType=[[NPC]],giverId=9078,ender=[[Shadowmage Vivian Lagrave]],ender_loc=[[Maga oscura Vivian Lagrave]],enderType=[[NPC]],enderId=9078,prevId=3906,poiX=-6682,poiY=-2151,wowhead=[[https://www.wowhead.com/wotlk/quest=7201]],image=[[assets/images/quests/placeholder.png]],desc=[[There is work to be had for those venturing into the depths, $N. The Dark Irons have mastered creation of extremely powerful golems. Initial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power. Just imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the risk.]],logDesc=[[Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals. ]],rewards={{id=12038,qty=1}}}
DB[7202]={id=7202,zoneId=2597,name=[[Korrak the Bloodrager]],name_loc=[[Korrak el Sanguinario]],level=60,minLevel=51,giver=[[Lieutenant Haggerdin]],giver_loc=[[Teniente Haggerdin]],giverType=[[NPC]],giverId=13841,ender=[[Lieutenant Haggerdin]],ender_loc=[[Teniente Haggerdin]],enderType=[[NPC]],enderId=13841,poiX=-16,poiY=-322,wowhead=[[https://www.wowhead.com/wotlk/quest=7202]],image=[[assets/images/quests/placeholder.png]],desc=[[The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew. We must show them our might! We have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager, tends to remain hidden until given a reason to make his presence known. Death to Korrak would mean death to Winterax Clan! Slay him and return.]],logDesc=[[According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley. Should Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Alterac Mountains.]],rewards={{id=18150,qty=1}},choiceRewards={{id=19107,qty=1},{id=19106,qty=1},{id=19108,qty=1}}}
DB[7223]={id=7223,zoneId=2597,name=[[Armor Scraps]],name_loc=[[Los restos de armadura]],level=-1,minLevel=51,giver=[[Murgot Deepforge]],giver_loc=[[Murgot Forjahonda]],giverType=[[NPC]],giverId=13257,ender=[[Murgot Deepforge]],ender_loc=[[Murgot Forjahonda]],enderType=[[NPC]],enderId=13257,poiX=648,poiY=-61,wowhead=[[https://www.wowhead.com/wotlk/quest=7223]],image=[[assets/images/quests/placeholder.png]],desc=[[Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops. If you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!]],logDesc=[[Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar.]]}
DB[7224]={id=7224,zoneId=2597,name=[[Enemy Booty]],name_loc=[[Botín enemigo]],level=-1,minLevel=51,giver=[[Smith Regzar]],giver_loc=[[Herrero Regzar]],giverType=[[NPC]],giverId=13176,ender=[[Smith Regzar]],ender_loc=[[Herrero Regzar]],enderType=[[NPC]],enderId=13176,poiX=-1252,poiY=-316,wowhead=[[https://www.wowhead.com/wotlk/quest=7224]],image=[[assets/images/quests/placeholder.png]],desc=[[When you fight the enemy, gather the scraps of their armor and bring them to me.  I'll use those scraps to make armor for our own troops!]],logDesc=[[Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village.]]}
DB[7241]={id=7241,zoneId=2597,name=[[In Defense of Frostwolf]],name_loc=[[En defensa de Lobo Gélido]],level=-1,minLevel=51,giver=[[Frostwolf Ambassador Rokhstrom]],giver_loc=[[Embajadora Rokhstrom Lobo Gélido]],giverType=[[NPC]],giverId=13842,ender=[[Warmaster Laggrond]],ender_loc=[[Maestro de guerra Laggrond]],enderType=[[NPC]],enderId=13840,poiX=401,poiY=-960,wowhead=[[https://www.wowhead.com/wotlk/quest=7241]],image=[[assets/images/quests/placeholder.png]],desc=[[The drums of war sound off in a distant land, $c. The favored clan of your Warchief is under attack from the nefarious Stormpike Guard of Ironforge. By the looks of you, I can discern that you are indeed battle hardy and prepared to take on the cause of the Frostwolf. It is you who must now take the next step in your evolution. North of Tarren Mill, in Alterac,  you will find the entrance to Alterac Valley. It is there that you will find Warmaster Laggrond. Hurry $c, for the battle is upon us!]],logDesc=[[Venture to Alterac Valley, located in the Alterac Mountains. Find and speak with Warmaster Laggrond - who stands outside the tunnel entrance - to begin your career as a soldier of Frostwolf. You will find Alterac Valley north of Tarren Mill at the base of the Alterac Mountains.]]}
DB[7261]={id=7261,zoneId=2597,name=[[The Sovereign Imperative]],name_loc=[[El imperativo soberano]],level=-1,minLevel=51,giver=[[Lieutenant Rotimer]],giver_loc=[[Teniente Rotimer]],giverType=[[NPC]],giverId=13843,ender=[[Lieutenant Haggerdin]],ender_loc=[[Teniente Haggerdin]],enderType=[[NPC]],enderId=13841,poiX=-16,poiY=-322,wowhead=[[https://www.wowhead.com/wotlk/quest=7261]],image=[[assets/images/quests/placeholder.png]],desc=[[We are fighting a brutal battle in the valleys of Alterac. The savage Frostwolf Clan challenges the might of the Stormpike! They must be exterminated in the name of King Magni Bronzebeard! The taking, culling, and turning of that land is a sovereign and territorial imperative to the kingdom of Ironforge. Alas, soldiers do not grow on trees! Report to Lieutenant Haggerdin outside Alterac Valley to begin your tour of duty and honor amongst the Stormpike.]],logDesc=[[Travel to Alterac Valley in the Hillsbrad Foothills. Outside of the entrance tunnel, find and speak with Lieutenant Haggerdin. For the glory of Bronzebeard!]]}
DB[7281]={id=7281,zoneId=2597,name=[[Brotherly Love]],name_loc=[[Amor fraternal]],level=-1,minLevel=51,giverType=[[NPC]],enderType=[[NPC]],poiX=214,poiY=-374,wowhead=[[https://www.wowhead.com/wotlk/quest=7281]],image=[[assets/images/quests/placeholder.png]],desc=[[Tragic... My brother faces me on the field of battle: A commander for the Stormpike. Of the four Stormpike Commanders, he is undoubtedly the most dangerous. Perhaps if he is slain, the Banshee Queen could turn him as she did me - show him the error of his ways... Deep within enemy territory you will find my brother. Slay him and return to me. I trust that you are capable of completing this mission, soldier. And soldier, do not go alone.]],logDesc=[[Travel into Stormpike territory and slay Commander Karl Philips. Return to Commander Louis Philips when the task is complete. ]]}
DB[7282]={id=7282,zoneId=2597,name=[[Brotherly Love]],name_loc=[[Amor fraternal]],level=-1,minLevel=51,giverType=[[NPC]],enderType=[[NPC]],poiX=-765,poiY=-355,wowhead=[[https://www.wowhead.com/wotlk/quest=7282]],image=[[assets/images/quests/placeholder.png]],desc=[[He must be put out of his misery, soldier! He knows not what he does. He has become a mindless servant of the dreaded Banshee Queen. Venture forth, across the Field of Strife, to the depths of Frostwolf territory. Find my brother and destroy him. His torment must come to an end.]],logDesc=[[Travel into Frostwolf territory and slay Commander Louis Philips. Return to Commander Karl Philips when the task is complete. ]]}
DB[7301]={id=7301,zoneId=2597,name=[[Fallen Sky Lords]],name_loc=[[Señores del Cielo caídos]],level=-1,minLevel=51,giverType=[[NPC]],enderType=[[NPC]],poiX=-1304,poiY=-267,wowhead=[[https://www.wowhead.com/wotlk/quest=7301]],image=[[assets/images/quests/placeholder.png]],desc=[[We got them held prisoner, $r. I'm talking about their Wing Commanders. It was a furious battle in the skies but they finally fell! Unfortunately, our best pilots were shot down in a counterattack against Frostwolf Keep. You gotta find out what happened to them. Search Tower Point West and Frostwolf Keep. These were their last known locations. Search these areas thoroughly.]],logDesc=[[Travel to Frostwolf territory and search for Wing Commander Slidore, Wing Commander Vipore, and Wing Commander Ichman. Return to Commander Duffy should you complete your mission.]]}
DB[7302]={id=7302,zoneId=2597,name=[[Fallen Sky Lords]],name_loc=[[Señores del Cielo caídos]],level=-1,minLevel=51,giverType=[[NPC]],enderType=[[NPC]],poiX=217,poiY=-378,wowhead=[[https://www.wowhead.com/wotlk/quest=7302]],image=[[assets/images/quests/placeholder.png]],desc=[[Our air support is in shambles, $N. The Wing Commanders were shot down over enemy territory. You must find out what became of them so that we can attempt a rescue! Guse was last seen flying over the Icewing Bunker. Jeztor's War Rider was spotted near the Stormpike lumber mill. Mulverick... that reckless fool was seen crashing near the Dun'Baldar North Bunker. That's all the information I have. Move out! Search through the areas thoroughly.]],logDesc=[[Find out what became of Wing Commander Guse, Wing Commander Jeztor, and Wing Commander Mulverick. Return to Commander Mulfort should you complete your mission.]]}
DB[7321]={id=7321,name=[[Soothing Turtle Bisque]],name_loc=[[Sopa de tortuga reconfortante]],level=31,minLevel=28,giver=[[Christoph Jeffcoat]],giver_loc=[[Christoph Jeffcoat]],giverType=[[NPC]],giverId=2393,ender=[[Christoph Jeffcoat]],ender_loc=[[Christoph Jeffcoat]],enderType=[[NPC]],enderId=2393,poiX=-852,poiY=-594,wowhead=[[https://www.wowhead.com/wotlk/quest=7321]],image=[[assets/images/quests/placeholder.png]],desc=[[Who says that the undead don't know anything about cooking? Take my secret recipe for Turtle Bisque, for example. I've known folks that would come back from the dead just to enjoy a bowl! Heh, heh... Speaking of which, I haven't been able to make any lately.  I used to head over to Lake Lordamere myself to hunt snapjaws, the nasty things, but I can't pull myself away from my work here. If you bring me some Turtle Meat from the snapjaws, I'll show you how it's done!]],logDesc=[[Bring 10 pieces of Turtle Meat to Christoph Jeffcoat in Tarren Mill.]],rewards={{id=3737,qty=1},{id=3729,qty=3}}}
DB[7341]={id=7341,zoneId=1637,name=[[A Fair Trade]],name_loc=[[Un trato justo]],level=60,minLevel=52,giver=[[Bounty Hunter Kolark]],giver_loc=[[Cazador de recompensas Kolark]],giverType=[[NPC]],giverId=14182,ender=[[Bounty Hunter Kolark]],ender_loc=[[Cazador de recompensas Kolark]],enderType=[[NPC]],enderId=14182,poiX=2141,poiY=-4636,wowhead=[[https://www.wowhead.com/wotlk/quest=7341]],image=[[assets/images/quests/placeholder.png]],rewards={{id=18042,qty=200}}}
DB[7342]={id=7342,zoneId=1537,name=[[Arrows Are For Sissies]],name_loc=[[Las flechas no valen para nada]],level=60,minLevel=52,giver=[[Artilleryman Sheldonore]],giver_loc=[[Artillero Sheldonore]],giverType=[[NPC]],giverId=14183,ender=[[Artilleryman Sheldonore]],ender_loc=[[Artillero Sheldonore]],enderType=[[NPC]],enderId=14183,poiX=-4842,poiY=-869,wowhead=[[https://www.wowhead.com/wotlk/quest=7342]],image=[[assets/images/quests/placeholder.png]],rewards={{id=18042,qty=200}}}
DB[7361]={id=7361,zoneId=2597,name=[[Favor Amongst the Darkspear]],level=60,minLevel=200,giver=[[Najak Hexxen]],giverType=[[NPC]],giverId=14185,ender=[[Najak Hexxen]],enderType=[[NPC]],enderId=14185,wowhead=[[https://www.wowhead.com/wotlk/quest=7361]],image=[[assets/images/quests/placeholder.png]],desc=[[<Najak snarls.> Before the night elves existed there was troll. It was from troll that the night elves came. Their mutinous attacks against my people will not be tolerated. Staghelm seeks to wipe us out - to leave no trace of those that bore him and his ilk. It will not happen! For every night elf that you slay and decapitate, Najak will grant you favor amongst the Darkspear. Word of your deeds will be spread across Kalimdor and the Eastern Kingdoms. Go now and serve the Darkspear!]],logDesc=[[You have been tasked with slaying opposing night elf players in Alterac Valley. Kill a night elf and return to Najak Hexxen at Frostwolf Keep with a Severed Night Elf Head.]]}
DB[7362]={id=7362,zoneId=2597,name=[[Ally of the Tauren]],level=60,minLevel=200,giver=[[Ravak Grimtotem]],giverType=[[NPC]],giverId=14186,ender=[[Ravak Grimtotem]],enderType=[[NPC]],enderId=14186,wowhead=[[https://www.wowhead.com/wotlk/quest=7362]],image=[[assets/images/quests/placeholder.png]],desc=[[The Elder Crone has sent me to this warzone to research the other races. More specifically, I am to collect gnome samples. Magatha is primarily interested in their survivability. Aye, the gnomes - while pitifully weak and miniscule - exude great resilience both in and out of combat. Fortunately for you, I am looking for ruffians to do Magatha's bidding. Return to me with tufts of gnome hair and you shall be known to the tauren as an ally.]],logDesc=[[You have been tasked with slaying opposing gnome players in Alterac Valley. Kill a gnome and return to Ravak Grimtotem at Frostwolf Keep with a Tuft of Gnome Hair.]]}
DB[7363]={id=7363,zoneId=2597,name=[[The Human Condition]],level=60,minLevel=200,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=7363]],image=[[assets/images/quests/placeholder.png]],desc=[[Humans are so utterly detestable. <Commander Philips grimaces.> While it is true that I am a soldier of Frostwolf, I remain a servant of Sylvanas. During my tour of duty, I do extra work on the side for the Dark Apothecaries of the Undercity. I have been tasked with collecting human bone chips that are to be used in curing the human condition. I am authorized to pass that task on to my subordinates. Find them. Kill them. Return their bone chips to me.]],logDesc=[[You have been tasked with slaying opposing human players in Alterac Valley. Kill a human and return to Commander Louis Philips (who wanders between the front lines and Frostwolf keep) with a  Human Bone Chip. A cure for the human condition is close at hand!]]}
DB[7364]={id=7364,zoneId=2597,name=[[Gnomeregan Bounty]],level=60,minLevel=200,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=7364]],image=[[assets/images/quests/placeholder.png]],desc=[[The High Tinkerer himself has sent me to this field of battle to defend my gnomish brothers and sisters. We have received word that the tauren are singling out and slaying gnomes. Worst of all, they are removing tufts of glorious gnome hair from the corpses of the fallen. These atrocities must be stopped. We must reciprocate! I want them de-hoofed, $c. Bring me their hooves! Show yourself as an ally of the gnomes.]],logDesc=[[You have been tasked with slaying opposing tauren players in Alterac Valley. Kill a tauren and return to Dirk Swindle at Dun'Baldar with a  Tauren Hoof.]]}
DB[7365]={id=7365,zoneId=2597,name=[[Staghelm's Requiem]],level=60,minLevel=200,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=7365]],image=[[assets/images/quests/placeholder.png]],desc=[[Staghelm has given the order. All trolls on the field of battle must be exterminated. Their preposterous claims of birthing night elves must be met with force and due prejudice. Slay them and return to me with their mojo. To reiterate: I want you to steal their mojo.]],logDesc=[[You have been tasked with slaying opposing troll players in Alterac Valley. Kill a troll and return to Athramanis at Dun'Baldar with Darkspear Troll Mojo.]]}
DB[7366]={id=7366,zoneId=2597,name=[[The Archbishop's Mercy]],level=60,minLevel=200,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=7366]],image=[[assets/images/quests/placeholder.png]],desc=[[The Archbishop is as kind as he is wise. For a man to look mercifully on such a wretched lot... <Commander Philips shakes his head in disbelief.> Too kind... Just too kind. The Archbishop asks that we take pity on the undead and grant them swift and permanent deaths. For this grand display of mercy, we merely require their black, disease ridden hearts. Bring me the hearts of the Forsaken so that they may be ceremoniously incinerated at the Cathedral of Light. Make haste, $N!]],logDesc=[[You have been tasked with slaying opposing Forsaken players in Alterac Valley. Kill a Forsaken and return to Commander Karl Philips (who wanders between the lumber mill and the mine) with a Forsaken Heart.]]}
DB[7367]={id=7367,zoneId=2597,name=[[Defusing the Threat]],name_loc=[[Acabar con la amenaza]],level=-1,minLevel=51,giver=[[Stormpike Explosives Expert]],giver_loc=[[Experto de explosivos de Pico Tormenta]],giverType=[[NPC]],giverId=13598,ender=[[Stormpike Explosives Expert]],ender_loc=[[Experto de explosivos de Pico Tormenta]],enderType=[[NPC]],enderId=13598,poiX=-568,poiY=-267,wowhead=[[https://www.wowhead.com/wotlk/quest=7367]],image=[[assets/images/quests/placeholder.png]],desc=[[The Frostwolf have their front lines and bases booby trapped, $c. You have to watch your step when invading enemy territory. If you want to make a solid strike against them, you must destroy their source of anti personnel munitions - I'm talking about their explosives expert. If you kill him, you are safe to disarm the mines. As long as he is kept down, the mines will also stay down. You will probably find him in a tower near the Iceblood Garrison. Good luck!]],logDesc=[[Find the Frostwolf Explosives Expert and kill him. Return to the Stormpike Explosives Expert when the task is complete.]]}
DB[7368]={id=7368,zoneId=2597,name=[[Defusing the Threat]],name_loc=[[Acabar con la amenaza]],level=-1,minLevel=51,giver=[[Frostwolf Explosives Expert]],giver_loc=[[Experto en explosivos Lobo Gélido]],giverType=[[NPC]],giverId=13597,ender=[[Frostwolf Explosives Expert]],ender_loc=[[Experto en explosivos Lobo Gélido]],enderType=[[NPC]],enderId=13597,poiX=-148,poiY=-453,wowhead=[[https://www.wowhead.com/wotlk/quest=7368]],image=[[assets/images/quests/placeholder.png]],desc=[[I know all about landmines. I'm the one that lays all the mines on the front lines here, after all. If you want to defuse the Stormpike mine fields, all you have to do is kill their explosives expert. That dwarven coward is no doubt hiding in the first tower on the Field of Strife. Take him out and those landmines won't come back after they've been disarmed. If you do happen to kill him, come back here and let me know. No good deed should go unrewarded.]],logDesc=[[Find the Stormpike Explosives Expert and kill him. Return to the Frostwolf Explosives Expert when the task is complete.]]}
DB[7381]={id=7381,zoneId=2597,name=[[The Return of Korrak]],name_loc=[[El regreso de Korrak]],level=60,minLevel=51,giver=[[Warmaster Laggrond]],giver_loc=[[Maestro de guerra Laggrond]],giverType=[[NPC]],giverId=13840,ender=[[Warmaster Laggrond]],ender_loc=[[Maestro de guerra Laggrond]],enderType=[[NPC]],enderId=13840,poiX=401,poiY=-960,wowhead=[[https://www.wowhead.com/wotlk/quest=7381]],image=[[assets/images/quests/placeholder.png]],desc=[[While it is true that Korrak has been slain, one question remains: Will he remain dead? Trolls are notorious for their other-worldly tribal magics. I would not be surprised if the fallen leader was raised from the dead to once more rule over his clan. You know what to do should this ever occur. <Warmaster Laggrond makes a cutting motion across his neck with his index finger.> And  this time, I want his skull. Just keep your eyes peeled, soldier. Dismissed!]],logDesc=[[Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him. Return the Skull of Korrak to Warmaster Laggrond in the Hillsbrad Foothills.]],rewards={{id=18149,qty=1}}}
DB[7382]={id=7382,zoneId=2597,name=[[Korrak the Everliving]],name_loc=[[Korrak el Eterno]],level=60,minLevel=50,giver=[[Lieutenant Haggerdin]],giver_loc=[[Teniente Haggerdin]],giverType=[[NPC]],giverId=13841,ender=[[Lieutenant Haggerdin]],ender_loc=[[Teniente Haggerdin]],enderType=[[NPC]],enderId=13841,poiX=-16,poiY=-322,wowhead=[[https://www.wowhead.com/wotlk/quest=7382]],image=[[assets/images/quests/placeholder.png]],desc=[[There's something not quite right about all of this... Did anybody think to burn Korrak's corpse? Those trolls will stop at nothing to revive their fallen leader - as blue skinned pagan man-beasts often do. Just keep your eyes out, $N. Don't be alarmed if Korrak makes a surprise appearance; and if he does, I want him executed - his corpse burned to ashes. For good measure, lop off his head and bring me his skull before you ignite the lifeless mass.]],logDesc=[[Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him. Return the Skull of Korrak to Lieutenant Haggerdin in the Hillsbrad Foothills. ]],rewards={{id=18150,qty=1}}}
DB[7383]={id=7383,zoneId=141,name=[[Crown of the Earth]],name_loc=[[La corona de la Tierra]],level=11,minLevel=1,giver=[[Corithras Moonrage]],giver_loc=[[Corithras Furia Lunar]],giverType=[[NPC]],giverId=3515,ender=[[Corithras Moonrage]],ender_loc=[[Corithras Furia Lunar]],enderType=[[NPC]],enderId=3515,prevId=933,rewardNextId=935,poiX=9737,poiY=956,wowhead=[[https://www.wowhead.com/wotlk/quest=7383]],image=[[assets/images/quests/placeholder.png]],desc=[[All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed. However, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me.]],logDesc=[[Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.]]}
DB[7385]={id=7385,zoneId=2597,name=[[A Gallon of Blood]],name_loc=[[Un galón de sangre]],level=-1,minLevel=51,giver=[[Primalist Thurloga]],giver_loc=[[Primalista Thurloga]],giverType=[[NPC]],giverId=13236,ender=[[Primalist Thurloga]],ender_loc=[[Primalista Thurloga]],enderType=[[NPC]],enderId=13236,poiX=-1320,poiY=-343,wowhead=[[https://www.wowhead.com/wotlk/quest=7385]],image=[[assets/images/quests/placeholder.png]]}
DB[7386]={id=7386,zoneId=2597,name=[[Crystal Cluster]],name_loc=[[Recogida de cristal]],level=-1,minLevel=51,giver=[[Arch Druid Renferal]],giver_loc=[[Archidruida Renferal]],giverType=[[NPC]],giverId=13442,ender=[[Arch Druid Renferal]],ender_loc=[[Archidruida Renferal]],enderType=[[NPC]],enderId=13442,poiX=729,poiY=-79,wowhead=[[https://www.wowhead.com/wotlk/quest=7386]],image=[[assets/images/quests/placeholder.png]]}
DB[7401]={id=7401,zoneId=2597,name=[[Wanted: DWARVES!]],level=60,minLevel=200,giverType=[[NPC]],ender=[[Sergeant Yazra Bloodsnarl]],enderType=[[NPC]],enderId=13448,wowhead=[[https://www.wowhead.com/wotlk/quest=7401]],image=[[assets/images/quests/placeholder.png]],desc=[[By order of Sergeant Yazra Bloodsnarl, all dwarves on the field of battle are to be killed on sight. Should you slay a dwarf in combat, rip out their spine, leaving a spineless heap of stink and rot to serve as a warning to any and all that dare oppose the might of the Frostwolf. Return to Sergeant Yazra Bloodsnarl with proof of your heroics.]],logDesc=[[You have been tasked with slaying opposing Dwarf players in Alterac Valley. Kill a Dwarf and rip out their spine. Take the Dwarf Spine to Sergeant Yazra Bloodsnarl at Frostwolf Keep.]]}
DB[7402]={id=7402,zoneId=2597,name=[[Wanted: ORCS!]],level=60,minLevel=200,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=7402]],image=[[assets/images/quests/placeholder.png]],desc=[[By order of Corporal Noreg Stormpike, all able bodied soldiers of Stormpike are required to slay any opposing orcs that they meet upon the field of battle. Soldiers are required to remove a tusk or tooth from the maw of the enemy and present said tooth as proof of their accomplishment. Wear protective gloves.]],logDesc=[[You have been tasked with slaying opposing Orc players in Alterac Valley. Kill an Orc and take their Orc Tooth back to Corporal Noreg Stormpike at Dun Baldar.]]}
