DB[7429]={id=7429,zoneId=2557,name=[[Free Knot!]],name_loc=[[¡Libera a Knot!]],level=60,minLevel=56,giver=[[Knot Thimblejack]],giver_loc=[[Knot Llavededo]],giverType=[[NPC]],giverId=14338,ender=[[Knot Thimblejack]],ender_loc=[[Knot Llavededo]],enderType=[[NPC]],enderId=14338,prevId=5525,poiX=735,poiY=424,wowhead=[[https://www.wowhead.com/wotlk/quest=7429]],image=[[assets/images/quests/placeholder.png]]}
DB[7441]={id=7441,zoneId=2557,name=[[Pusillin and the Elder Azj'Tordin]],name_loc=[[Pusillín y el ancestro Azj'Tordin]],level=58,minLevel=54,giver=[[Azj'Tordin]],giver_loc=[[Azj'Tordin]],giverType=[[NPC]],giverId=14355,ender=[[Azj'Tordin]],ender_loc=[[Azj'Tordin]],enderType=[[NPC]],enderId=14355,poiX=-4097,poiY=96,wowhead=[[https://www.wowhead.com/wotlk/quest=7441]],image=[[assets/images/quests/placeholder.png]],desc=[[I had let my guard down for only one moment, stranger. In my haste to escape the grip of the fallen Prince, I was robbed. A most foul demon, the imp Pusillin, pilfered my book of incantations and the key to the once great halls of Eldre'Thalas. I no longer hold interest in the key, as I have exchanged my immortality for freedom, but I desperately need my book of incantations. Find the imp, Pusillin, and recover my book. Search the Warpwood Quarter of Dire Maul for Pusillin.]],logDesc=[[Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary. Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.]],choiceRewards={{id=18411,qty=1},{id=18410,qty=1}}}
DB[7461]={id=7461,zoneId=2557,name=[[The Madness Within]],name_loc=[[Locura interior]],level=60,minLevel=56,giver=[[Shen'dralar Ancient]],giver_loc=[[Ancestro Shen'dralar]],giverType=[[NPC]],giverId=14358,ender=[[Shen'dralar Ancient]],ender_loc=[[Ancestro Shen'dralar]],enderType=[[NPC]],enderId=14358,rewardNextId=7877,poiX=-38,poiY=812,wowhead=[[https://www.wowhead.com/wotlk/quest=7461]],image=[[assets/images/quests/placeholder.png]],desc=[[Have you heard enough? Are you a $g man:woman; of action? This madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced, attack and end him. Lay the spirits of this city to rest, adventurer.]],logDesc=[[You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated. Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum. Return to the Shen'dralar Ancient in the courtyard should you complete this quest.]]}
DB[7462]={id=7462,zoneId=2557,name=[[The Treasure of the Shen'dralar]],name_loc=[[El tesoro de los Shen'dralar]],level=60,minLevel=56,giver=[[Shen'dralar Ancient]],giver_loc=[[Ancestro Shen'dralar]],giverType=[[NPC]],giverId=14358,ender=[[Treasure of the Shen'dralar]],ender_loc=[[Tesoro de los Shen'dralar]],enderType=[[GO]],enderId=179517,prevId=7461,poiX=129,poiY=545,wowhead=[[https://www.wowhead.com/wotlk/quest=7462]],image=[[assets/images/quests/placeholder.png]],desc=[[In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.]],logDesc=[[Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!]],choiceRewards={{id=18420,qty=1},{id=18421,qty=1},{id=18424,qty=1}}}
DB[7463]={id=7463,zoneId=2557,name=[[Arcane Refreshment]],name_loc=[[El refresco arcano]],level=-1,minLevel=60,giver=[[Lorekeeper Lydros]],giver_loc=[[Tradicionalista Lydros]],giverType=[[NPC]],giverId=14368,ender=[[Lorekeeper Lydros]],ender_loc=[[Tradicionalista Lydros]],enderType=[[NPC]],enderId=14368,poiX=3,poiY=-419,wowhead=[[https://www.wowhead.com/wotlk/quest=7463]],image=[[assets/images/quests/placeholder.png]],desc=[[A $r mage! How wonderous. I have not seen one of your kind for... oh what is it going on now? 500 years! I have something that will quench your thirst, but first you must do a task for me. <Lydros snickers.> There is an anomaly in Eldre'Thalas. A water elemental has taken residence in the east wing. His presence must be catalogued! Venture to the Warpwood Quarter and extract a portion of the elemental essence of the Hydrospawn. Return it to me and I shall teach you a useful cantrip.]],logDesc=[[Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.]]}
DB[7481]={id=7481,zoneId=2557,name=[[Elven Legends]],name_loc=[[Leyendas élficas]],level=60,minLevel=54,giver=[[Sage Korolusk]],giver_loc=[[Sabio Korolusk]],giverType=[[NPC]],giverId=14373,ender=[[Sage Korolusk]],ender_loc=[[Sabio Korolusk]],enderType=[[NPC]],enderId=14373,poiX=-4390,poiY=193,wowhead=[[https://www.wowhead.com/wotlk/quest=7481]],image=[[assets/images/quests/placeholder.png]],desc=[[Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow. Our search for this lost master lead us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas. We suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul). You must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!]],logDesc=[[Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.]]}
DB[7482]={id=7482,zoneId=2557,name=[[Elven Legends]],name_loc=[[Leyendas élficas]],level=60,minLevel=54,giver=[[Scholar Runethorn]],giver_loc=[[Erudita Runaespina]],giverType=[[NPC]],giverId=14374,ender=[[Scholar Runethorn]],ender_loc=[[Erudita Runaespina]],enderType=[[NPC]],enderId=14374,poiX=-4377,poiY=3233,wowhead=[[https://www.wowhead.com/wotlk/quest=7482]],image=[[assets/images/quests/placeholder.png]],desc=[[Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow. Our search for this lost master lead us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas. We suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul). You must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!]],logDesc=[[Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.]]}
DB[7483]={id=7483,zoneId=2557,name=[[Libram of Rapidity]],name_loc=[[El tratado sobre rapidez]],level=60,minLevel=54,giver=[[Lorekeeper Lydros]],giver_loc=[[Tradicionalista Lydros]],giverType=[[NPC]],giverId=14368,ender=[[Lorekeeper Lydros]],ender_loc=[[Tradicionalista Lydros]],enderType=[[NPC]],enderId=14368,wowhead=[[https://www.wowhead.com/wotlk/quest=7483]],image=[[assets/images/quests/placeholder.png]],desc=[[Master Winthalus lost the Libram of Rapidity in the east wing. The Libram will allow for a minor haste cantrip to be placed upon your equipment. Parlor tricks, really... Regardless, if you are interested, you will need to present the Libram along with some basic reagents. Hrm... I believe it also requires blood of heroes, a pristine black diamond, and large brilliant shards. I could be wrong! <Lydros shrugs.>]],logDesc=[[Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.]],rewards={{id=18329,qty=1}}}
DB[7484]={id=7484,zoneId=2557,name=[[Libram of Focus]],name_loc=[[El tratado sobre enfoque]],level=60,minLevel=54,giver=[[Lorekeeper Lydros]],giver_loc=[[Tradicionalista Lydros]],giverType=[[NPC]],giverId=14368,ender=[[Lorekeeper Lydros]],ender_loc=[[Tradicionalista Lydros]],enderType=[[NPC]],enderId=14368,wowhead=[[https://www.wowhead.com/wotlk/quest=7484]],image=[[assets/images/quests/placeholder.png]],desc=[[This libram almost aroused interest in one of the younger Lorekeeper's familiars. Poor thing, it was only a few weeks old. Those among you who are more magically inclined might find this item interesting. The Libram of Focus was lost in this wing. I can only assume one of the Highborne spirits holds it in their possession. Bring the Libram along with some large brilliant shards, skin of shadow, and a pristine black diamond and I shall conjure the Arcanum.]],logDesc=[[Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.]],rewards={{id=18330,qty=1}}}
DB[7485]={id=7485,zoneId=2557,name=[[Libram of Protection]],name_loc=[[El tratado sobre protección]],level=60,minLevel=54,giver=[[Lorekeeper Lydros]],giver_loc=[[Tradicionalista Lydros]],giverType=[[NPC]],giverId=14368,ender=[[Lorekeeper Lydros]],ender_loc=[[Tradicionalista Lydros]],enderType=[[NPC]],enderId=14368,wowhead=[[https://www.wowhead.com/wotlk/quest=7485]],image=[[assets/images/quests/placeholder.png]],desc=[[He wept like an infant at the loss of this libram. Mind you, I myself have wept over texts - there is no greater loss than that of knowledge and history - but to cry over this nearly useless jumbling of incantations? Preposterous! It left me to believe that the Prince was doing him a favor in flaying the flesh from his bones. Bring the Libram along with a pristine black diamond, large brilliant shards, and a frayed abomination stitching and I shall recreate the Arcanum. Oh, and check the north wing.]],logDesc=[[Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.]],rewards={{id=18331,qty=1}}}
DB[7486]={id=7486,zoneId=16,name=[[A Hero's Reward]],name_loc=[[Una recompensa de héroe]],level=60,minLevel=55,giver=[[Duke Hydraxis]],giver_loc=[[Duque Hydraxis]],giverType=[[NPC]],giverId=13278,ender=[[Hydraxis' Coffer]],ender_loc=[[Arca de Hydraxis]],enderType=[[GO]],enderId=179551,prevId=6824,poiX=2810,poiY=-7295,wowhead=[[https://www.wowhead.com/wotlk/quest=7486]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, your services to the Warlords surpassed all we could expect from the denizens of this world. We do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted. Under the surf at the southern base of this island, you will find a coffer.  In it you will find your... reward. Go, $N.  Claim your reward.]],logDesc=[[Claim your reward from Hydraxis' Coffer.]],choiceRewards={{id=18399,qty=1},{id=18398,qty=1}}}
DB[7487]={id=7487,zoneId=2717,name=[[Attunement to the Core]],name_loc=[[Armonización con el Núcleo]],level=60,minLevel=55,giver=[[Lothos Riftwaker]],giver_loc=[[Lothos Levantagrietas]],giverType=[[NPC]],giverId=14387,ender=[[Lothos Riftwaker]],ender_loc=[[Lothos Levantagrietas]],enderType=[[NPC]],enderId=14387,poiX=-7509,poiY=-1040,wowhead=[[https://www.wowhead.com/wotlk/quest=7487]],image=[[assets/images/quests/placeholder.png]],desc=[[Rifts stir, tear, and collapse all around us, $r. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord. Surprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel. I assure you, the portal is there and access is possible. I've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the portal.]],logDesc=[[Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.]]}
DB[7488]={id=7488,zoneId=2557,name=[[Lethtendris's Web]],name_loc=[[La membrana de Lethtendris]],level=57,minLevel=54,giver=[[Latronicus Moonspear]],giver_loc=[[Latronicus Lanzaluna]],giverType=[[NPC]],giverId=7877,ender=[[Latronicus Moonspear]],ender_loc=[[Latronicus Lanzaluna]],enderType=[[NPC]],enderId=7877,prevId=7494,poiX=-4506,poiY=3330,wowhead=[[https://www.wowhead.com/wotlk/quest=7488]],image=[[assets/images/quests/placeholder.png]],desc=[[The mage Lethtendris, a vicious blood elf whose brutality is matched only by her twisted addiction to magic, has fled into Dire Maul.  She has created a device, a web to ensnare the magical energies of that place and we fear that, if left unchecked, she will cause irreparable damage to our world! Stop her, $N.  Find her and retrieve her web.  She is likely near the satyrs in Warpwood Quarter of Dire Maul.  Bring the web to me so that its power may be released safely back into the wilds...]],logDesc=[[Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.]],rewards={{id=18491,qty=1}}}
DB[7489]={id=7489,zoneId=2557,name=[[Lethtendris's Web]],name_loc=[[La membrana de Lethtendris]],level=57,minLevel=54,giver=[[Talo Thornhoof]],giver_loc=[[Talo Pezuñahendida]],giverType=[[NPC]],giverId=7776,ender=[[Talo Thornhoof]],ender_loc=[[Talo Pezuñahendida]],enderType=[[NPC]],enderId=7776,prevId=7492,poiX=-4398,poiY=147,wowhead=[[https://www.wowhead.com/wotlk/quest=7489]],image=[[assets/images/quests/placeholder.png]],desc=[[The blood elf Lethtendris has overstepped her bounds.  So eager was she to gather magical power that she defied her brethren and created a device of insidious design, a web meant to siphon the tainted magical energies of Dire Maul.  Even now she gathers those energies and plans to release them against her enemies. Lethtendris must be stopped.  Find her within the Warpwood Quarter of Dire Maul, defeat her and bring her web to me so that it might be returned to more clear-headed blood elves for study.]],logDesc=[[Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.]],rewards={{id=18491,qty=1}}}
DB[7490]={id=7490,zoneId=1637,name=[[Victory for the Horde]],name_loc=[[Victoria para la Horda]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=7491,poiX=1924,poiY=-4157,wowhead=[[https://www.wowhead.com/wotlk/quest=7490]],image=[[assets/images/quests/placeholder.png]],desc=[[You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to your Warchief.]],logDesc=[[Take the Head of Onyxia to Thrall in Orgrimmar.]]}
DB[7491]={id=7491,zoneId=1637,name=[[For All To See]],name_loc=[[Para que todos lo vean]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],prevId=7490,poiX=1568,poiY=-4406,wowhead=[[https://www.wowhead.com/wotlk/quest=7491]],image=[[assets/images/quests/placeholder.png]],desc=[[Overlord Runthak awaits your arrival in the Valley of Strength. <Thrall salutes you.> Do not keep your public waiting, hero.]],logDesc=[[Seek out Overlord Runthak in the Valley of Strength.]],choiceRewards={{id=18406,qty=1},{id=18403,qty=1},{id=18404,qty=1}}}
DB[7492]={id=7492,zoneId=2557,name=[[Camp Mojache]],name_loc=[[Campamento Mojache]],level=57,minLevel=54,giver=[[Harbinger Balthazad]],giver_loc=[[Presagista Balthazad]],giverType=[[NPC]],giverId=10879,ender=[[Talo Thornhoof]],ender_loc=[[Talo Pezuñahendida]],enderType=[[NPC]],enderId=7776,rewardNextId=7489,poiX=-4398,poiY=147,wowhead=[[https://www.wowhead.com/wotlk/quest=7492]],image=[[assets/images/quests/placeholder.png]],desc=[[Talo Thornhoof, a Tauren elder in Feralas, sends a request for aid.  He offered few details, but he did say that he needs agents for a matter both delicate... and dire. Serve the Horde, $N.  Go to Camp Mojache in Feralas and speak with Talo.]],logDesc=[[Speak with Talo Thornhoof at Camp Mojache in Feralas.]]}
