DB[7494]={id=7494,zoneId=2557,name=[[Feathermoon Stronghold]],name_loc=[[Bastión Plumaluna]],level=57,minLevel=54,giver=[[Crier Goodman]],giver_loc=[[Pregonero Buenhombre]],giverType=[[NPC]],giverId=2198,ender=[[Latronicus Moonspear]],ender_loc=[[Latronicus Lanzaluna]],enderType=[[NPC]],enderId=7877,rewardNextId=7488,poiX=-4506,poiY=3330,wowhead=[[https://www.wowhead.com/wotlk/quest=7494]],image=[[assets/images/quests/placeholder.png]],desc=[[$N!  Your aid is needed in Feralas! An outlaw mage, Lethtendris, has fled to the ancient elven ruins Eldre'thalas, now called Dire Maul.  It is believed she has an item of dangerous magical energy which must be recovered. Latronicus Moonspear requests agents to enter Dire Maul and retrieve the item from Lethtendris. Serve the Alliance!  Seek out Latronicus at the Feathermoon Stronghold in Feralas.]],logDesc=[[Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas.]]}
