DB[7494]={id=7494,zoneId=2557,name=[[Feathermoon Stronghold]],name_loc=[[Bastión Plumaluna]],level=57,minLevel=54,giver=[[Herald Bran'daan]],giver_loc=[[Pregonero Buenhombre]],giverType=[[NPC]],giverId=20722,ender=[[Latronicus Moonspear]],ender_loc=[[Latronicus Lanzaluna]],enderType=[[NPC]],enderId=7877,rewardNextId=7488,poiX=-4506,poiY=3330,wowhead=[[https://www.wowhead.com/wotlk/quest=7494]],image=[[assets/images/quests/placeholder.png]],desc=[[$N!  Your aid is needed in Feralas! An outlaw mage, Lethtendris, has fled to the ancient elven ruins Eldre'thalas, now called Dire Maul.  It is believed she has an item of dangerous magical energy which must be recovered. Latronicus Moonspear requests agents to enter Dire Maul and retrieve the item from Lethtendris. Serve the Alliance!  Seek out Latronicus at the Feathermoon Stronghold in Feralas.]],logDesc=[[Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas.]]}
DB[7495]={id=7495,zoneId=1519,name=[[Victory for the Alliance]],name_loc=[[Victoria para la Alianza]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=7496,poiX=-8441,poiY=333,wowhead=[[https://www.wowhead.com/wotlk/quest=7495]],image=[[assets/images/quests/placeholder.png]],desc=[[You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the King Varian Wrynn.]],logDesc=[[Take the Head of Onyxia to King Varian Wrynn in Stormwind.]]}
