DB[7507]={id=7507,zoneId=2557,name=[[Foror's Compendium]],name_loc=[[Compendio de Foror]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],poiX=164,poiY=522,wowhead=[[https://www.wowhead.com/wotlk/quest=7507]],image=[[assets/images/quests/placeholder.png]],desc=[[You have uncovered something of great importance. This book is unlike any that you have seen. It would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible.]],logDesc=[[Return Foror's Compendium of Dragon Slaying to the Athenaeum.]]}
DB[7508]={id=7508,zoneId=2557,name=[[The Forging of Quel'Serrar]],name_loc=[[Forjar Quel'Serrar]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],prevId=7507,rewardNextId=7509,poiX=164,poiY=522,wowhead=[[https://www.wowhead.com/wotlk/quest=7508]],image=[[assets/images/quests/placeholder.png]],desc=[[If you wish to take on this task, present Lydros with the dull blade.]],logDesc=[[Give the Dull and Flat Elven Blade to Lorekeeper Lydros.]]}
DB[7509]={id=7509,zoneId=2159,name=[[The Forging of Quel'Serrar]],name_loc=[[Forjar Quel'Serrar]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],prevId=7508,poiX=164,poiY=522,wowhead=[[https://www.wowhead.com/wotlk/quest=7509]],image=[[assets/images/quests/placeholder.png]],desc=[[Take the unfired ancient blade to the lair of Onyxia and engage her in battle. Some trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon. Plunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade.]],logDesc=[[You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence. The last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse. Do this and Quel'Serrar will be yours.]],rewards={{id=18348,qty=1}}}
DB[7521]={id=7521,name=[[Thunderaan the Windseeker]],name_loc=[[Thunderaan el Hijo del Viento]],level=1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-6158,poiY=1781,wowhead=[[https://www.wowhead.com/wotlk/quest=7521]],image=[[assets/images/quests/placeholder.png]],desc=[[I have told you all that I know, $N. It is you who must find elementium. It is you who must destroy the Firelord's corporeal form. Do this and gain the blessing of Thunderaan.]],logDesc=[[To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Wind Seeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian.]]}
DB[7541]={id=7541,zoneId=15,name=[[Service to the Horde]],name_loc=[[Un servicio para la Horda]],level=40,minLevel=30,giver=[[Zor Lonetree]],giver_loc=[[Zor Árbol Solitario]],giverType=[[NPC]],giverId=4047,ender=[[Zor Lonetree]],ender_loc=[[Zor Árbol Solitario]],enderType=[[NPC]],enderId=4047,prevId=1262,poiX=1915,poiY=-4227,wowhead=[[https://www.wowhead.com/wotlk/quest=7541]],image=[[assets/images/quests/placeholder.png]],choiceRewards={{id=18585,qty=1},{id=18586,qty=1}}}
DB[7561]={id=7561,name=[[Rise,Thunderfury!]],level=60,minLevel=100,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=7561]],image=[[assets/images/quests/placeholder.png]],desc=[[You have defeated the Wind Seeker. Take the dormant blade and force the lying wretch,Demitrian,to use the materials you provided for his betrayal to wake Thunderfury.]],logDesc=[[Present the Dormant Wind Kissed Blade to Highlord Demitrian.]],rewards={{id=17802,qty=1}}}
DB[7562]={id=7562,name=[[Mor'zul Bloodbringer]],name_loc=[[Mor'zul Sangredoble]],level=-1,minLevel=60,giver=[[Spackle Thornberry]],giver_loc=[[Spackle Zarzamora]],giverType=[[NPC]],giverId=5520,ender=[[Mor'zul Bloodbringer]],ender_loc=[[Mor'zul Sangredoble]],enderType=[[NPC]],enderId=14436,nextId=7563,rewardNextId=7563,poiX=-7649,poiY=-638,wowhead=[[https://www.wowhead.com/wotlk/quest=7562]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, your delvings into the dark arts are deep.  Your mastery over otherworldly denizens has grown so strong... perhaps you are ready to bind to you one of the infamous dreadsteeds. The ritual to summon the beast from its home requires great power and resources, but if you desire to dominate that epic mount, then speak with Mor'zul Bloodbringer.  He is camped near the Altar of Storms in the Burning Steppes. Go, $N.  This quest will be perilous, but a Warlock of your stature does not shy from danger!]],logDesc=[[Speak with Mor'zul Bloodbringer at the Altar of Storms in the Burning Steppes.]]}
