DB[7701]={id=7701,zoneId=51,name=[[WANTED: Overseer Maltorius]],name_loc=[[SE BUSCA: Sobrestante Maltorius]],level=50,minLevel=45,giver=[[Wanted/Missing/Lost & Found]],giver_loc=[[Se busca/Desaparecido/Objetos perdidos]],giverType=[[GO]],giverId=179827,ender=[[Lookout Captain Lolo Longstriker]],ender_loc=[[Capitán de vigía Lolo Zancalarga]],enderType=[[NPC]],enderId=14634,poiX=-6632,poiY=-1233,wowhead=[[https://www.wowhead.com/wotlk/quest=7701]],image=[[assets/images/quests/placeholder.png]],desc=[[By order o' 'is eminence, Overseer Oilfist, the rogue Thorium Brotherhood agent an' newly hired commander o' the Dark Iron Slag Pit crew o' the Cauldron, Overseer Maltorius, is to be killed an' 'is head brung back as proof o' the deed. See Lookout Captan Lolo Longstriker fer the reward on this bounty.]],logDesc=[[Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius. Slay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.]],choiceRewards={{id=19128,qty=1},{id=19127,qty=1}}}
DB[7702]={id=7702,zoneId=51,name=[[Kill 'Em With Sleep Deprivation]],name_loc=[[¡Mátalos de sueño!]],level=49,minLevel=30,giver=[[Evonice Sootsmoker]],giver_loc=[[Evonis Fumollín]],giverType=[[NPC]],giverId=14628,ender=[[Evonice Sootsmoker]],ender_loc=[[Evonis Fumollín]],enderType=[[NPC]],enderId=14628,poiX=-6524,poiY=-1365,wowhead=[[https://www.wowhead.com/wotlk/quest=7702]],image=[[assets/images/quests/placeholder.png]],desc=[[If we want to put a dent in the productivity of the Dark Iron forces working out of the Slag Pit, we have to hit them where it's going to hurt the most. It's a little known fact but dwarves, particularly of the Dark Iron variety, need rest! Lots of rest! Now I ask you; How can they sleep without pillows? Exactly, $N, they can't. This is why you must weasel your way into the Slag Pit and steal their pillows.]],logDesc=[[Deep within the Slag Pit of the Cauldron, you will find the sleeping quarters of the Dark Iron dwarves. Travel to the sleeping quarters and steal 20 Dark Iron Pillows. Return to Evonice Sootsmoker in the Searing Gorge when you have accomplished this task.]],rewards={{id=19129,qty=1}}}
DB[7703]={id=7703,zoneId=2557,name=[[Unfinished Gordok Business]],name_loc=[[Asunto Gordok sin finiquitar]],level=60,minLevel=56,giver=[[Captain Kromcrush]],giver_loc=[[Capitán Kromcrush]],giverType=[[NPC]],giverId=14325,ender=[[Captain Kromcrush]],ender_loc=[[Capitán Kromcrush]],enderType=[[NPC]],enderId=14325,poiX=116,poiY=639,wowhead=[[https://www.wowhead.com/wotlk/quest=7703]],image=[[assets/images/quests/placeholder.png]],desc=[[Now you da king, so maybe you get prized Gordok artifact back from creepy elf who calls himself Prince!  Da king before you failed, just like all da other kings since Tortheldrin - da creepy elf - stole it from old timey Gordok king! Artifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  Old timey story also say creepy elf is still around here - you find it and it will become mighty gauntlet you wear forever!  Yar, I show you!]],logDesc=[[Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul. According to Kromcrush, the "old timey story" says that Tortheldrin - a "creepy" elf who called himself a prince - stole it from one of the Gordok kings.]],choiceRewards={{id=18366,qty=1},{id=18367,qty=1},{id=18368,qty=1},{id=18369,qty=1}}}
DB[7704]={id=7704,zoneId=51,name=[[Look at the Size of It!]],name_loc=[[¡Mira el tamaño de esto!]],level=50,minLevel=45,giverType=[[NPC]],ender=[[Evonice Sootsmoker]],ender_loc=[[Evonis Fumollín]],enderType=[[NPC]],enderId=14628,poiX=-6513,poiY=-1179,wowhead=[[https://www.wowhead.com/wotlk/quest=7704]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, well, well... Isn't this a surprise. The Chambermaid had a gigantic ornate pillow and now it's yours. Evonice Sootsmoker will definitely want to get her grubby little hands all over this item. Take it to her and see if she'll offer you any goodies for your trouble.]],logDesc=[[Take Chambermaid Pillaclencher's Pillow to Evonice Sootsmoker in the Searing Gorge.]],rewards={{id=18951,qty=1}}}
DB[7721]={id=7721,zoneId=357,name=[[Fuel for the Zapping]],name_loc=[[Combustible para el Ultra-reductor]],level=48,minLevel=45,giver=[[Zorbin Fandazzle]],giver_loc=[[Zorbin Hipnoviento]],giverType=[[NPC]],giverId=14637,ender=[[Zorbin Fandazzle]],ender_loc=[[Zorbin Hipnoviento]],enderType=[[NPC]],enderId=14637,poiX=-4182,poiY=2317,wowhead=[[https://www.wowhead.com/wotlk/quest=7721]],image=[[assets/images/quests/placeholder.png]],desc=[[If I bet against my own better judgment and stay to run an engineering shop along the Forgotten Coast, I will need to deal with these pesky elementals.  Curse the powers of elementalism unchecked, I say! Fortunately for me, and now for you my hopeful agent provocateur, the elementals represent an ideal source of raw power for my Ultra-Shrinker refinement - give them the what-for I say!  When doing this though, be sure to save me the water elemental cores!]],logDesc=[[Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.]],rewards={{id=19039,qty=1}}}
DB[7722]={id=7722,zoneId=51,name=[[What the Flux?]],name_loc=[[¿Qué pasa con el flujo?]],level=50,minLevel=45,giver=[[Master Smith Burninate]],giver_loc=[[Maestro herrero Cremación]],giverType=[[NPC]],giverId=14624,ender=[[Master Smith Burninate]],ender_loc=[[Maestro herrero Cremación]],enderType=[[NPC]],enderId=14624,poiX=-6632,poiY=-1225,wowhead=[[https://www.wowhead.com/wotlk/quest=7722]],image=[[assets/images/quests/placeholder.png]],desc=[[When that traitor, Maltorius, left our clan, he left with something more valuable than a pristine arcane crystal: Our recipe for fiery flux! I'd bet anything that the recipe was part of the deal in his new promotion amongst the Dark Irons. I want you to get our secret plans back, $N. I'm sure they're somewhere near Maltorius, deep inside the Slag Pit.]],logDesc=[[Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge. ]]}
DB[7723]={id=7723,zoneId=51,name=[[Curse These Fat Fingers]],name_loc=[[¡Malditos dedos gordos!]],level=49,minLevel=45,giver=[[Hansel Heavyhands]],giver_loc=[[Hansel Manospesadas]],giverType=[[NPC]],giverId=14627,ender=[[Hansel Heavyhands]],ender_loc=[[Hansel Manospesadas]],enderType=[[NPC]],enderId=14627,poiX=-6685,poiY=-1451,wowhead=[[https://www.wowhead.com/wotlk/quest=7723]],image=[[assets/images/quests/placeholder.png]],desc=[[Unfortunately, I can't dish out the beats like I used to, due to this here fat finger problem. Ye see, the climate out here combined with the lack o' air pressure makes me fingers expand. They're like gigantic Thelsamar Blood Sausages, they are... Ye're gonna have to carry out me orders of business and what have ye. First on me agenda: Poundin' the livin' daylights out o' the heavy war golems o' the Gorge. Get crackin'.]],logDesc=[[Hansel Heavyhands wants you to kill 20 Heavy War Golems. The Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.]],rewards={{id=19126,qty=1}}}
DB[7724]={id=7724,zoneId=51,name=[[Fiery Menace!]],name_loc=[[Amenaza abrasadora]],level=49,minLevel=45,giver=[[Hansel Heavyhands]],giver_loc=[[Hansel Manospesadas]],giverType=[[NPC]],giverId=14627,ender=[[Hansel Heavyhands]],ender_loc=[[Hansel Manospesadas]],enderType=[[NPC]],enderId=14627,poiX=-6686,poiY=-1049,wowhead=[[https://www.wowhead.com/wotlk/quest=7724]],image=[[assets/images/quests/placeholder.png]],desc=[[Wouldn't ye know it, every time ol' Hansel wants to take a moment to relax and reflect upon his life, the powers that be give him another job. Me gots to think, come on! Ye know what I be saying? Come. On. So, these here greater lava spiders are causin' a ruckus o' some sort. Oilfist says they shoot fire out their... erm, yea well, anyway, such things upset the children. I guess we gots to kill 'em. Rather, ye gots to kill 'em.]],logDesc=[[Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge. Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.]],rewards={{id=19125,qty=1}}}
DB[7725]={id=7725,zoneId=357,name=[[Again With the Zapped Giants]],name_loc=[[Encoge más gigantes]],level=55,minLevel=45,giver=[[Zorbin Fandazzle]],giver_loc=[[Zorbin Hipnoviento]],giverType=[[NPC]],giverId=14637,ender=[[Zorbin Fandazzle]],ender_loc=[[Zorbin Hipnoviento]],enderType=[[NPC]],enderId=14637,prevId=7003,poiX=-4379,poiY=2327,wowhead=[[https://www.wowhead.com/wotlk/quest=7725]],image=[[assets/images/quests/placeholder.png]],desc=[[I know you've gathered residue for me already... but should you find yourself for want of an encore performance to a fun-time activity, I can always use more residue. While I can't offer nearly as much in the way of compensation again, I'll be more than happy to spread the good word of your service to all my goblin friends with ears. Believe me $g sir : madam; when I say that these goblins have quite large ears.]],logDesc=[[Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form.  Bring 10 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.]]}
DB[7726]={id=7726,zoneId=357,name=[[Refuel for the Zapping]],name_loc=[[Más combustible para el Ultra-reductor]],level=55,minLevel=45,giver=[[Zorbin Fandazzle]],giver_loc=[[Zorbin Hipnoviento]],giverType=[[NPC]],giverId=14637,ender=[[Zorbin Fandazzle]],ender_loc=[[Zorbin Hipnoviento]],enderType=[[NPC]],enderId=14637,prevId=7721,poiX=-4182,poiY=2317,wowhead=[[https://www.wowhead.com/wotlk/quest=7726]],image=[[assets/images/quests/placeholder.png]],desc=[[More work, you say?  Did my heroic mission of collecting bits of goo found inside elemental beings not slake your thirst for adventure?  Perhaps more of the same will vainly try to fill the bottomless well of questing you possess... OK, melodrama aside, I do need more water elemental cores.  I'm trying desperately to set up shop here, so the rewards won't be as great... but I promise you I'll tell everyone in earshot how you've helped me.  Trust me on this - I know people in the Cartel!]],logDesc=[[Collect 6 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.]]}
DB[7727]={id=7727,zoneId=51,name=[[Incendosaurs? Whateverosaur is More Like It]],name_loc=[[¿Incendosaurio? Loqueseasaurio más bien]],level=49,minLevel=45,giver=[[Hansel Heavyhands]],giver_loc=[[Hansel Manospesadas]],giverType=[[NPC]],giverId=14627,ender=[[Hansel Heavyhands]],ender_loc=[[Hansel Manospesadas]],enderType=[[NPC]],enderId=14627,poiX=-6421,poiY=-1389,wowhead=[[https://www.wowhead.com/wotlk/quest=7727]],image=[[assets/images/quests/placeholder.png]],desc=[[Bunions, $g lad:lass;. Me bunions got bunions. How am I supposed to do any sort of killin' with me feet in such disarray? That's why ye're gonna help. Scrange and Burninate tasked me to kill these things so they can send some expeditionary teams down into the Slag Pit lava pools to do some explorin'. Supposedly some incendosaurs or some such nonsense down there causin' all kinds o' problems. Now move along an' don't come back 'til the incendosaur population be extinct.]],logDesc=[[Hansel Heavyhands wants you to kill 20 Incendosaurs. You will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge. Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.]],rewards={{id=19141,qty=1}}}
DB[7728]={id=7728,zoneId=51,name=[[STOLEN: Smithing Tuyere and Lookout's Spyglass]],name_loc=[[OBJETOS ROBADOS: Tobera y catalejo]],level=48,minLevel=45,giver=[[Wanted/Missing/Lost & Found]],giver_loc=[[Se busca/Desaparecido/Objetos perdidos]],giverType=[[GO]],giverId=179827,ender=[[Taskmaster Scrange]],ender_loc=[[Capataz Scrange]],enderType=[[NPC]],enderId=14626,poiX=-6869,poiY=-1282,wowhead=[[https://www.wowhead.com/wotlk/quest=7728]],image=[[assets/images/quests/placeholder.png]],desc=[[The following items have been stolen: *One Dark Iron Tuyere. *One Lookout's Spyglass. A reward is being offered to individuals who find and return these pilfered items. The Thorium Brotherhood is certain that these items were stolen by unscrupulous and jealous Dark Iron dwarves that inhabit the Searing Gorge. The spyglass in question was an excellent tool for the lookouts and the tuyere was an irreplaceable smithing tool. Should you find the missing items, return them to Scrange.]],logDesc=[[Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge. The only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts.]],choiceRewards={{id=19124,qty=1},{id=19123,qty=1}}}
DB[7729]={id=7729,zoneId=51,name=[[JOB OPPORTUNITY: Culling the Competition]],name_loc=[[OPORTUNIDAD LABORAL: Acabar con la competencia]],level=48,minLevel=45,giver=[[Wanted/Missing/Lost & Found]],giver_loc=[[Se busca/Desaparecido/Objetos perdidos]],giverType=[[GO]],giverId=179827,ender=[[Taskmaster Scrange]],ender_loc=[[Capataz Scrange]],enderType=[[NPC]],enderId=14626,poiX=-6872,poiY=-1324,wowhead=[[https://www.wowhead.com/wotlk/quest=7729]],image=[[assets/images/quests/placeholder.png]],desc=[[Taskmaster Scrange is looking for a few good men and women to help 'cull the competition' in the Searing Gorge. If you are interested in this position, venture out into the Searing Gorge and slaughter every Dark Iron Taskmaster and Dark Iron Slaver that you see. Return to Taskmaster Scrange when your clothes are bloody enough. You'll know when they're bloody enough so don't ask.]],logDesc=[[Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task.]]}
DB[7730]={id=7730,zoneId=357,name=[[Zukk'ash Infestation]],name_loc=[[Infestación de Zukk'ash]],level=45,minLevel=39,giver=[[Hadoken Swiftstrider]],giver_loc=[[Hadoken Zanco Veloz]],giverType=[[NPC]],giverId=7875,ender=[[Hadoken Swiftstrider]],ender_loc=[[Hadoken Zanco Veloz]],enderType=[[NPC]],enderId=7875,prevId=2903,nextId=7732,exGroup=-7730,poiX=-5380,poiY=-53,wowhead=[[https://www.wowhead.com/wotlk/quest=7730]],image=[[assets/images/quests/placeholder.png]],desc=[[From what scouting we have managed to muster, we believe that the foe south of the gnolls is an insect-like race.  Frankly, it is irrelevant whether or not if they're sentient.  If they are driving the gnolls to frenzy against us, then they are as big of a threat - if not more - than the gnolls. Drive deep into where these Zukk'ash insects dwell; it is known as the Writhing Deep.  Thin their numbers and report back to me what you find, bringing back their carapaces as evidence of your handiwork.]],logDesc=[[Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas.]]}
DB[7731]={id=7731,zoneId=357,name=[[Stinglasher]],name_loc=[[Latigador con aguijón]],level=47,minLevel=39,giver=[[Hadoken Swiftstrider]],giver_loc=[[Hadoken Zanco Veloz]],giverType=[[NPC]],giverId=7875,ender=[[Hadoken Swiftstrider]],ender_loc=[[Hadoken Zanco Veloz]],enderType=[[NPC]],enderId=7875,prevId=2903,nextId=7732,exGroup=-7730,poiX=-5307,poiY=330,wowhead=[[https://www.wowhead.com/wotlk/quest=7731]],image=[[assets/images/quests/placeholder.png]],desc=[[In surveying the Writhing Deep, one of our scouts reported seeing a giant insect - much larger than the other insects spotted - wandering about the twisted terrain.  Not only is it larger, it also seems to secrete some sort of aura that the other insects don't.  We've given it a name - Stinglasher. The innards of this beast would be invaluable to study as we figure out the best way to deal with this new threat.  Cut out its secretion glands and bring it back to me immediately!]],logDesc=[[Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas.]]}
DB[7732]={id=7732,zoneId=357,name=[[Zukk'ash Report]],name_loc=[[El informe Zukk'ash]],level=48,minLevel=39,giver=[[Hadoken Swiftstrider]],giver_loc=[[Hadoken Zanco Veloz]],giverType=[[NPC]],giverId=7875,ender=[[Zilzibin Drumlore]],ender_loc=[[Zilzibin Tambor Sabio]],enderType=[[NPC]],enderId=7010,poiX=1837,poiY=-4470,wowhead=[[https://www.wowhead.com/wotlk/quest=7732]],image=[[assets/images/quests/placeholder.png]],desc=[[You've done doubly well in addressing the threat that the Zukk'ash insects pose to Camp Mojache.  The threat these things pose is far from over, and I'd like to ask you for one last task on behalf of the Horde. This is a document that details all the information we have learned about these Zukk'ash insects.  I want you to deliver it to Zilzibin Drumlore in the Drag of Orgrimmar.  He's an expert on alien creatures like these; I hope he can do something with the lore we've obtained.]],logDesc=[[Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore.  He resides in the Drag of Orgrimmar.]],choiceRewards={{id=19038,qty=1},{id=19037,qty=1}}}
DB[7733]={id=7733,zoneId=357,name=[[Improved Quality]],name_loc=[[Calidad mejorada]],level=48,minLevel=40,giver=[[Pratt McGrubben]],giver_loc=[[Pratt McGrubben]],giverType=[[NPC]],giverId=7852,ender=[[Pratt McGrubben]],ender_loc=[[Pratt McGrubben]],enderType=[[NPC]],enderId=7852,prevId=2821,poiX=-3905,poiY=1563,wowhead=[[https://www.wowhead.com/wotlk/quest=7733]],image=[[assets/images/quests/placeholder.png]],desc=[[I have a lead on an even BETTER source of hides, if that's even possible to believe!  In the northern parts of Feralas - deep within Rage Scar Hold - are another throng of yetis.  They're much tougher than the ones you dealt with before, so if you're up for a bigger challenge you'd best be on your toes! I would reward you handsomely for a stack of ten of their hides; bring them to me here, and we'll finish our business.]],logDesc=[[Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas.]],rewards={{id=19041,qty=1}}}
DB[7734]={id=7734,zoneId=357,name=[[Improved Quality]],name_loc=[[Calidad mejorada]],level=48,minLevel=40,giver=[[Jangdor Swiftstrider]],giver_loc=[[Jangdor Zanco Veloz]],giverType=[[NPC]],giverId=7854,ender=[[Jangdor Swiftstrider]],ender_loc=[[Jangdor Zanco Veloz]],enderType=[[NPC]],enderId=7854,prevId=2822,poiX=-3905,poiY=1563,wowhead=[[https://www.wowhead.com/wotlk/quest=7734]],image=[[assets/images/quests/placeholder.png]],desc=[[I have a lead on an even BETTER source of hides, if that's even possible to believe!  In the northern parts of Feralas - deep within Rage Scar Hold - are another throng of yetis.  They're much tougher than the ones you dealt with before, so if you're up for a bigger challenge you'd best be on your toes! I would reward you handsomely for a stack of ten of their hides; bring them to me here, and we'll finish our business.]],logDesc=[[Bring 10 Rage Scar Yeti Hides to Jangdor Swiftstrider at Camp Mojache, Feralas.]],rewards={{id=19042,qty=1}}}
DB[7735]={id=7735,zoneId=357,name=[[Pristine Yeti Hide]],name_loc=[[Pellejo de yeti prístino]],level=48,minLevel=40,giverType=[[NPC]],ender=[[Pratt McGrubben]],ender_loc=[[Pratt McGrubben]],enderType=[[NPC]],enderId=7852,poiX=-3905,poiY=1563,wowhead=[[https://www.wowhead.com/wotlk/quest=7735]],image=[[assets/images/quests/placeholder.png]],desc=[[You have found a pristine yeti hide that is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar. Considering that Pratt McGrubben at the Feathermoon Stronghold is in the market for yeti hides, this particular one may be of considerable interest to him.]],logDesc=[[Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas.]]}
DB[7736]={id=7736,zoneId=51,name=[[Restoring Fiery Flux Supplies via Kingsblood]],name_loc=[[Fabricar flujo ígneo con sangrerregia]],level=60,minLevel=45,giver=[[Master Smith Burninate]],giver_loc=[[Maestro herrero Cremación]],giverType=[[NPC]],giverId=14624,ender=[[Master Smith Burninate]],ender_loc=[[Maestro herrero Cremación]],enderType=[[NPC]],enderId=14624,prevId=7722,poiX=-6524,poiY=-1189,wowhead=[[https://www.wowhead.com/wotlk/quest=7736]],image=[[assets/images/quests/placeholder.png]]}
