DB[7738]={id=7738,zoneId=357,name=[[Perfect Yeti Hide]],name_loc=[[Pellejo de yeti perfecto]],level=48,minLevel=40,giverType=[[NPC]],ender=[[Jangdor Swiftstrider]],ender_loc=[[Jangdor Zanco Veloz]],enderType=[[NPC]],enderId=7854,poiX=-3905,poiY=1563,wowhead=[[https://www.wowhead.com/wotlk/quest=7738]],image=[[assets/images/quests/placeholder.png]],desc=[[You have found what may very well be a perfect yeti hide.  You easily note that it is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar. Considering that Jangdor Swiftstrider at Camp Mojache is in the market for yeti hides, this particular one may be of considerable interest to him.]],logDesc=[[Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Camp Mojache, Feralas.]]}
DB[7761]={id=7761,zoneId=1583,name=[[Blackhand's Command]],name_loc=[[Orden de Puño Negro]],level=60,minLevel=55,giverType=[[NPC]],ender=[[Drakkisath's Brand]],ender_loc=[[Enseña de Drakkisath]],enderType=[[GO]],enderId=179880,wowhead=[[https://www.wowhead.com/wotlk/quest=7761]],image=[[assets/images/quests/placeholder.png]],desc=[[Imbecile, I hold very little faith in your ability to prevent outsiders from accessing the master's lair. In the very likely event of your death, this orb has its own failsafe built in to prevent outsiders from teleporting directly into Blackwing. Only those with the Mark of Drakkisath branded upon their hand may make use of this orb. Thankfully, Drakkisath is not nearly as incompetent as you, Quartermaster. He guards the brand himself! -Warchief Rend Blackhand P.S. Destroy this letter, idiot.]],logDesc=[[That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command. The letter indicates that General Drakkisath guards the brand. Perhaps you should investigate.]]}
DB[7781]={id=7781,zoneId=1519,name=[[The Lord of Blackrock]],name_loc=[[Señor de Roca Negra]],level=60,minLevel=60,giverType=[[NPC]],ender=[[King Varian Wrynn]],ender_loc=[[Rey Varian Wrynn]],enderType=[[NPC]],enderId=29611,rewardNextId=7782,poiX=-8441,poiY=333,wowhead=[[https://www.wowhead.com/wotlk/quest=7781]],image=[[assets/images/quests/placeholder.png]],desc=[[The old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian. Return it to King Varian Wrynn, champion.]],logDesc=[[Return the Head of Nefarian to King Varian Wrynn in Stormwind.]]}
DB[7782]={id=7782,zoneId=1519,name=[[The Lord of Blackrock]],name_loc=[[Señor de Roca Negra]],level=60,minLevel=60,giver=[[Highlord Bolvar Fordragon]],giver_loc=[[Alto señor Bolvar Fordragón]],giverType=[[NPC]],giverId=1748,ender=[[Field Marshal Afrasiabi]],ender_loc=[[Mariscal de campo Petraponte]],enderType=[[NPC]],enderId=14721,prevId=7781,poiX=-8928,poiY=481,wowhead=[[https://www.wowhead.com/wotlk/quest=7782]],image=[[assets/images/quests/placeholder.png]],desc=[[Go to the Valley of Heroes and speak with Field Marshal Afrasiabi.]],logDesc=[[Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi.]],choiceRewards={{id=19383,qty=1},{id=19366,qty=1},{id=19384,qty=1}}}
