DB[7783]={id=7783,zoneId=1637,name=[[The Lord of Blackrock]],name_loc=[[Señor de Roca Negra]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Thrall]],ender_loc=[[Thrall]],enderType=[[NPC]],enderId=4949,rewardNextId=7784,poiX=1926,poiY=-4160,wowhead=[[https://www.wowhead.com/wotlk/quest=7783]],image=[[assets/images/quests/placeholder.png]],desc=[[The old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian. Return it to your Warchief, champion.]],logDesc=[[Return the Head of Nefarian to Thrall in Orgrimmar.]]}
DB[7784]={id=7784,zoneId=1637,name=[[The Lord of Blackrock]],name_loc=[[Señor de Roca Negra]],level=60,minLevel=60,giver=[[Thrall]],giver_loc=[[Thrall]],giverType=[[NPC]],giverId=4949,ender=[[Overlord Runthak]],ender_loc=[[Señor supremo Runthak]],enderType=[[NPC]],enderId=14392,prevId=7783,poiX=1568,poiY=-4406,wowhead=[[https://www.wowhead.com/wotlk/quest=7784]],image=[[assets/images/quests/placeholder.png]],desc=[[Seek out Overlord Runthak in the Valley of Strength.]],logDesc=[[Speak with Overlord Runthak in Orgrimmar. He stands waiting for you in the Valley of Strength.]],choiceRewards={{id=19383,qty=1},{id=19366,qty=1},{id=19384,qty=1}}}
DB[7785]={id=7785,name=[[Examine the Vessel]],name_loc=[[Examina la vasija]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Highlord Demitrian]],ender_loc=[[Alto Señor Demitrian]],enderType=[[NPC]],enderId=14347,rewardNextId=7786,poiX=-6158,poiY=1781,wowhead=[[https://www.wowhead.com/wotlk/quest=7785]],image=[[assets/images/quests/placeholder.png]],desc=[[Examine the vessel of his rebirth, mortal. It is from this that the Windseeker shall be reborn!]],logDesc=[[Examine the Vessel of Rebirth and return it to Highlord Demitrian.]]}
DB[7786]={id=7786,name=[[Thunderaan the Windseeker]],name_loc=[[Thunderaan el Hijo del Viento]],level=60,minLevel=60,giver=[[Highlord Demitrian]],giver_loc=[[Alto Señor Demitrian]],giverType=[[NPC]],giverId=14347,ender=[[Highlord Demitrian]],ender_loc=[[Alto Señor Demitrian]],enderType=[[NPC]],enderId=14347,prevId=7785,poiX=-6158,poiY=1781,wowhead=[[https://www.wowhead.com/wotlk/quest=7786]],image=[[assets/images/quests/placeholder.png]],desc=[[I have told you all that I know, $N. It is you who must find elementium. It is you who must destroy the Firelord's corporeal form. Do this and gain the blessing of Thunderaan.]],logDesc=[[To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Windseeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian in Silithus.]]}
DB[7787]={id=7787,name=[[Rise, Thunderfury!]],name_loc=[[¡Arriba, Trueno Furioso!]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Highlord Demitrian]],ender_loc=[[Alto Señor Demitrian]],enderType=[[NPC]],enderId=14347,prevId=7786,poiX=-6243,poiY=1715,wowhead=[[https://www.wowhead.com/wotlk/quest=7787]],image=[[assets/images/quests/placeholder.png]],desc=[[You have defeated the Wind Seeker. Take the dormant blade and force the lying wretch, Demitrian, to use the materials you provided for his betrayal to wake Thunderfury.]],logDesc=[[Present the Dormant Wind Kissed Blade to Highlord Demitrian.]],rewards={{id=19019,qty=1}}}
DB[7788]={id=7788,zoneId=3277,name=[[Vanquish the Invaders!]],name_loc=[[¡Expulsa al invasor!]],level=25,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=7788,poiX=1448,poiY=-1867,wowhead=[[https://www.wowhead.com/wotlk/quest=7788]],image=[[assets/images/quests/placeholder.png]],desc=[[Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war. Enter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces! Do this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.]],logDesc=[[Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.]]}
DB[7789]={id=7789,zoneId=3277,name=[[Quell the Silverwing Usurpers]],name_loc=[[Acaba con los usurpadores Ala de Plata]],level=25,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=7922,poiX=1044,poiY=-2099,wowhead=[[https://www.wowhead.com/wotlk/quest=7789]],image=[[assets/images/quests/placeholder.png]],desc=[[The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours! Let the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded. ]],logDesc=[[Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.]]}
