DB[7810]={id=7810,zoneId=33,name=[[Arena Master]],name_loc=[[El maestro de la arena]],level=55,minLevel=1,giverType=[[NPC]],ender=[[Short John Mithril]],ender_loc=[[Corto John Mitril]],enderType=[[NPC]],enderId=14508,nextId=7838,poiX=-13184,poiY=333,wowhead=[[https://www.wowhead.com/wotlk/quest=7810]],image=[[assets/images/quests/placeholder.png]],desc=[[There must be more to being a master of the arena than this!   Perhaps the Pirate who runs the event at Gurubashi will know!]],logDesc=[[Speak with Short John Mithril in the Stranglethorn Arena.]]}
