DB[7815]={id=7815,zoneId=47,name=[[Snapjaws, Mon!]],name_loc=[[¡Quijafortes, colega!]],level=50,minLevel=44,giver=[[Katoom the Angler]],giver_loc=[[Katoom el Pescador]],giverType=[[NPC]],giverId=14740,ender=[[Katoom the Angler]],ender_loc=[[Katoom el Pescador]],enderType=[[NPC]],enderId=14740,poiX=-17,poiY=-4846,wowhead=[[https://www.wowhead.com/wotlk/quest=7815]],image=[[assets/images/quests/placeholder.png]],desc=[[Don't let their big eyes fool you, mon! Those saltwater snapjaws be a menace. I can't fish for five minutes without getting a broken line from one of those oversized fish vacuums stealing my bait. Do me and the people of Revantusk Village a service and kill em, mon. Kill the whole lot of em!]],logDesc=[[Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 10 Saltwater Snapjaw turtles. Return to him when you have completed this task.]],rewards={{id=19022,qty=1}}}
DB[7816]={id=7816,zoneId=47,name=[[Gammerita, Mon!]],name_loc=[[¡Gammerita, colega!]],level=48,minLevel=44,giver=[[Katoom the Angler]],giver_loc=[[Katoom el Pescador]],giverType=[[NPC]],giverId=14740,ender=[[Katoom the Angler]],ender_loc=[[Katoom el Pescador]],enderType=[[NPC]],enderId=14740,poiX=220,poiY=-4717,wowhead=[[https://www.wowhead.com/wotlk/quest=7816]],image=[[assets/images/quests/placeholder.png]],desc=[[Yo! There be a turtle out there not like the others. She be the Gammerita, leader of the saltwater snapjaws - a downright dirty thievin' reptile. Mon, she stole my best lure. Snapped it right off my line! Since then, the fish just aren't biting the same. Find Gammerita and get my lure out of her stomach.]],logDesc=[[Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse. Katoom mentioned that Gammerita hangs out on the coast with the other turtles.]]}
