DB[7828]={id=7828,zoneId=47,name=[[Stalking the Stalkers]],name_loc=[[Acechar a los acechadores]],level=48,minLevel=44,giver=[[Huntsman Markhor]],giver_loc=[[Montero Markhor]],giverType=[[NPC]],giverId=14741,ender=[[Huntsman Markhor]],ender_loc=[[Montero Markhor]],enderType=[[NPC]],enderId=14741,poiX=148,poiY=-4585,wowhead=[[https://www.wowhead.com/wotlk/quest=7828]],image=[[assets/images/quests/placeholder.png]],desc=[[Many brave trolls have been lost to the harsh wilds of the Hinterlands, $r. The Silvermane wolves are one of the biggest threats to our hunters. They lay in wait, hiding amongst the bushes and landscape, then strike out when the opportunity presents itself. This type of ferocity will not go unchecked! You must think like the Silvermane. Stalk the stalkers! Slay them all!]],logDesc=[[Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 5 Silvermane Stalkers and 5 Silvermane Howlers. Return to him once the task is complete. Markhor mentioned that the wolves hide in the wilds of the Hinterlands.]]}
DB[7829]={id=7829,zoneId=47,name=[[Hunt the Savages]],name_loc=[[Cazar a los salvajes]],level=48,minLevel=44,giver=[[Huntsman Markhor]],giver_loc=[[Montero Markhor]],giverType=[[NPC]],giverId=14741,ender=[[Huntsman Markhor]],ender_loc=[[Montero Markhor]],enderType=[[NPC]],enderId=14741,poiX=112,poiY=-4087,wowhead=[[https://www.wowhead.com/wotlk/quest=7829]],image=[[assets/images/quests/placeholder.png]],desc=[[Among the more ornery of the wildlife of the Hinterlands are the savage owlbeasts. Many a good Revantusk warrior has been lost to the ferocious claws and beak of the beasts. Kill every savage owlbeast you see, $r. Return to me when you can stand no more bloodshed. Your contribution will then be weighed, measured, and judged.]],logDesc=[[Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 10 Savage Owlbeasts. Return to him once the task is complete. Markhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands.]]}
DB[7830]={id=7830,zoneId=47,name=[[Avenging the Fallen]],name_loc=[[Vengar a los Caídos]],level=48,minLevel=44,giver=[[Huntsman Markhor]],giver_loc=[[Montero Markhor]],giverType=[[NPC]],giverId=14741,ender=[[Huntsman Markhor]],ender_loc=[[Montero Markhor]],enderType=[[NPC]],enderId=14741,poiX=-575,poiY=-4623,wowhead=[[https://www.wowhead.com/wotlk/quest=7830]],image=[[assets/images/quests/placeholder.png]],desc=[[The filth that calls itself Wildhammer trains gryphon to slay troll. Horrible, I know, but worry not, justice will soon be meted out. For now, I want you to focus on eradicating the elder gryphons of the region. They are known as Skylords. Slay one and return to me with its plume.]],logDesc=[[Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete. Markhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands.]]}
