DB[7871]={id=7871,zoneId=3277,name=[[Vanquish the Invaders!]],name_loc=[[¡Expulsa al invasor!]],level=35,minLevel=30,giverType=[[NPC]],enderType=[[NPC]],exGroup=7788,poiX=1448,poiY=-1867,wowhead=[[https://www.wowhead.com/wotlk/quest=7871]],image=[[assets/images/quests/placeholder.png]],desc=[[Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war. Enter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces! Do this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.]],logDesc=[[Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.]]}
DB[7872]={id=7872,zoneId=3277,name=[[Vanquish the Invaders!]],name_loc=[[¡Expulsa al invasor!]],level=45,minLevel=40,giverType=[[NPC]],enderType=[[NPC]],exGroup=7788,poiX=1448,poiY=-1867,wowhead=[[https://www.wowhead.com/wotlk/quest=7872]],image=[[assets/images/quests/placeholder.png]],desc=[[Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war. Enter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces! Do this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.]],logDesc=[[Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.]]}
DB[7873]={id=7873,zoneId=3277,name=[[Vanquish the Invaders!]],name_loc=[[¡Expulsa al invasor!]],level=55,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],exGroup=7788,poiX=1448,poiY=-1867,wowhead=[[https://www.wowhead.com/wotlk/quest=7873]],image=[[assets/images/quests/placeholder.png]],desc=[[Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war. Enter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces! Do this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.]],logDesc=[[Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.]]}
DB[7874]={id=7874,zoneId=3277,name=[[Quell the Silverwing Usurpers]],name_loc=[[Acaba con los usurpadores Ala de Plata]],level=35,minLevel=30,giverType=[[NPC]],enderType=[[NPC]],exGroup=7922,poiX=1044,poiY=-2099,wowhead=[[https://www.wowhead.com/wotlk/quest=7874]],image=[[assets/images/quests/placeholder.png]],desc=[[The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours! Let the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded. ]],logDesc=[[Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.]]}
DB[7875]={id=7875,zoneId=3277,name=[[Quell the Silverwing Usurpers]],name_loc=[[Acaba con los usurpadores Ala de Plata]],level=45,minLevel=40,giverType=[[NPC]],enderType=[[NPC]],exGroup=7922,poiX=1044,poiY=-2099,wowhead=[[https://www.wowhead.com/wotlk/quest=7875]],image=[[assets/images/quests/placeholder.png]],desc=[[The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours! Let the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded. ]],logDesc=[[Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.]]}
