DB[7937]={id=7937,name=[[Your Fortune Awaits You...]],name_loc=[[La Fortuna te espera...]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Mysterious Eastvale Haystack]],ender_loc=[[Misterioso fardo de heno de la Vega del Este]],enderType=[[GO]],enderId=180025,poiX=-9430,poiY=-1410,wowhead=[[https://www.wowhead.com/wotlk/quest=7937]],image=[[assets/images/quests/placeholder.png]],desc=[["Your fortune awaits you in Eastvale." The fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Eastvale Logging Camp in Elwynn Forest.  Focusing closer in on the image, you see a haystack that sits next to a stable. ]],logDesc=[[Travel to the Eastvale Logging Camp in Elwynn Forest and seek out your fortune.]],rewards={{id=19425,qty=1}}}
DB[7938]={id=7938,name=[[Your Fortune Awaits You...]],name_loc=[[La Fortuna te espera...]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Mysterious Deadmines Chest]],ender_loc=[[Cofre misterioso de Las Minas de la Muerte]],enderType=[[GO]],enderId=180024,wowhead=[[https://www.wowhead.com/wotlk/quest=7938]],image=[[assets/images/quests/placeholder.png]],desc=[["Your fortune awaits you inside the Deadmines." The fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Deadmines inside Westfall's ruined hamlet of Moonbrook.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the mines itself.  Stepping through it, a strange chest appears out from nowhere.]],logDesc=[[Travel to the Deadmines in Westfall and seek out your fortune.]],rewards={{id=19425,qty=1}}}
