DB[7944]={id=7944,name=[[Your Fortune Awaits You...]],name_loc=[[La Fortuna te espera...]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Mysterious Wailing Caverns Chest]],enderType=[[GO]],enderId=180055,poiX=-732,poiY=-2219,wowhead=[[https://www.wowhead.com/wotlk/quest=7944]],image=[[assets/images/quests/placeholder.png]],desc=[["Your fortune awaits you inside Wailing Caverns." The fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of a cave to the southwest of the Crossroads in the Barrens.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the caverns itself.  Stepping through it, a strange chest appears out from nowhere. ]],logDesc=[[Travel to the Wailing Caverns in the Barrens and seek out your fortune.]],rewards={{id=19425,qty=1}}}
DB[7945]={id=7945,name=[[Your Fortune Awaits You...]],name_loc=[[La Fortuna te espera...]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Mysterious Tree Stump]],ender_loc=[[Tocón misterioso]],enderType=[[GO]],enderId=180056,poiX=-2381,poiY=250,wowhead=[[https://www.wowhead.com/wotlk/quest=7945]],image=[[assets/images/quests/placeholder.png]],desc=[["Your fortune awaits you outside Palemane Rock." The fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Palemane Rock of Mulgore.  Focusing closer in on the image, you see a tree stump that sits close to the cave entrance. ]],logDesc=[[Travel to Palemane Rock in Mulgore and seek out your fortune.]],rewards={{id=19425,qty=1}}}
