DB[8113]={id=8113,zoneId=1977,name=[[Pristine Enchanted South Seas Kelp]],name_loc=[[Algas de los Mares del Sur encantadas prístinas]],level=60,minLevel=58,giver=[[Maywiki of Zuldazar]],giver_loc=[[Maywiki de Zuldazar]],giverType=[[NPC]],giverId=14904,ender=[[Maywiki of Zuldazar]],ender_loc=[[Maywiki de Zuldazar]],enderType=[[NPC]],enderId=14904,prevId=8112,poiX=-11850,poiY=1245,wowhead=[[https://www.wowhead.com/wotlk/quest=8113]],image=[[assets/images/quests/placeholder.png]],rewards={{id=19613,qty=1}}}
DB[8114]={id=8114,zoneId=3358,name=[[Control Four Bases]],name_loc=[[Controla cuatro bases]],level=60,minLevel=60,giver=[[Field Marshal Oslight]],giver_loc=[[Mariscal de campo Uluz]],giverType=[[NPC]],giverId=14983,ender=[[Field Marshal Oslight]],ender_loc=[[Mariscal de campo Uluz]],enderType=[[NPC]],enderId=14983,prevId=8105,poiX=-1224,poiY=-2516,wowhead=[[https://www.wowhead.com/wotlk/quest=8114]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you have taken the battle of Arathi Basin to our enemies and earned great honors in that field of battle.  You have shown us your worth as a $c, and you have shown our enemies that we will not submit to their villainy! Because of your proven value to us, I have a difficult task for you.  I want you to take and hold at least four of the bases in Arathi Basin.  If you can do that, then we will not only secure critical resources, we will show the Horde our dominance! Go, $N, and good fortune.]],logDesc=[[Enter Arathi Basin, capture and control four bases at the same time, and then return to Field Marshal Oslight at Refuge Pointe.]]}
DB[8115]={id=8115,zoneId=3358,name=[[Control Five Bases]],name_loc=[[Controla cinco bases]],level=60,minLevel=60,giver=[[Field Marshal Oslight]],giver_loc=[[Mariscal de campo Uluz]],giverType=[[NPC]],giverId=14983,ender=[[Field Marshal Oslight]],ender_loc=[[Mariscal de campo Uluz]],enderType=[[NPC]],enderId=14983,poiX=-1224,poiY=-2516,wowhead=[[https://www.wowhead.com/wotlk/quest=8115]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, battling for the resources of Arathi Basin is a bloody undertaking.  Your services to the League of Arathor are as needed as they are appreciated. And we have one more task for you. The League wishes to make one strong push against the Defilers' occupation of Arathi Basin.  We want them driven out of every strategic point on the battlefield! It will not be easy, but if anyone can get it done, it is you.]],logDesc=[[Control 5 bases in Arathi Basin at the same time, then return to Field Marshal Oslight at Refuge Pointe.]],rewards={{id=20132,qty=1}}}
DB[8116]={id=8116,zoneId=1977,name=[[Vision of Voodress]],name_loc=[[Visión de Voodress]],level=60,minLevel=58,giver=[[Maywiki of Zuldazar]],giver_loc=[[Maywiki de Zuldazar]],giverType=[[NPC]],giverId=14904,ender=[[Maywiki of Zuldazar]],ender_loc=[[Maywiki de Zuldazar]],enderType=[[NPC]],enderId=14904,poiX=-11850,poiY=1245,wowhead=[[https://www.wowhead.com/wotlk/quest=8116]],image=[[assets/images/quests/placeholder.png]],rewards={{id=19606,qty=1}}}
