DB[8119]={id=8119,zoneId=1977,name=[[The Unmarred Vision of Voodress]],name_loc=[[Visión inmaculada de Voodress]],level=60,minLevel=58,giver=[[Maywiki of Zuldazar]],giver_loc=[[Maywiki de Zuldazar]],giverType=[[NPC]],giverId=14904,ender=[[Maywiki of Zuldazar]],ender_loc=[[Maywiki de Zuldazar]],enderType=[[NPC]],enderId=14904,prevId=8118,poiX=-11850,poiY=1245,wowhead=[[https://www.wowhead.com/wotlk/quest=8119]],image=[[assets/images/quests/placeholder.png]],rewards={{id=19609,qty=1}}}
DB[8120]={id=8120,zoneId=3358,name=[[The Battle for Arathi Basin!]],name_loc=[[La batalla por la Cuenca de Arathi]],level=55,minLevel=50,giver=[[Deathmaster Dwire]],giver_loc=[[Maestra de la muerte Duire]],giverType=[[NPC]],giverId=15021,ender=[[Deathmaster Dwire]],ender_loc=[[Maestra de la muerte Duire]],enderType=[[NPC]],enderId=15021,exGroup=8120,poiX=990,poiY=1008,wowhead=[[https://www.wowhead.com/wotlk/quest=8120]],image=[[assets/images/quests/placeholder.png]],desc=[[As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans! Go to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde. Go, $N.  Report back to me when this task is complete.]],logDesc=[[Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.]]}
DB[8121]={id=8121,zoneId=3358,name=[[Take Four Bases]],name_loc=[[Toma el control de cuatro bases]],level=60,minLevel=60,giver=[[Deathmaster Dwire]],giver_loc=[[Maestra de la muerte Duire]],giverType=[[NPC]],giverId=15021,ender=[[Deathmaster Dwire]],ender_loc=[[Maestra de la muerte Duire]],enderType=[[NPC]],enderId=15021,prevId=8120,poiX=-847,poiY=-3504,wowhead=[[https://www.wowhead.com/wotlk/quest=8121]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, as the battles over Arathi Basin rage, news of your actions have reached many ears.  You are highly regarded among us, which gives me confidence that you will accomplish the mission I now have for you. It is time to send a message to the League of Arathor.  We must show them that their holdings in Arathi Basin are tenuous and quickly lost.  We will show them this by holding, all at once, four strategic points in Arathi Basin. Succeed in this, $N, and earn great respect among the Defilers.]],logDesc=[[Hold four bases at the same time in Arathi Basin, and then return to Deathmaster Dwire in Hammerfall.]]}
DB[8122]={id=8122,zoneId=3358,name=[[Take Five Bases]],name_loc=[[Toma el control de cinco bases]],level=60,minLevel=60,giver=[[Deathmaster Dwire]],giver_loc=[[Maestra de la muerte Duire]],giverType=[[NPC]],giverId=15021,ender=[[Deathmaster Dwire]],ender_loc=[[Maestra de la muerte Duire]],enderType=[[NPC]],enderId=15021,poiX=-847,poiY=-3504,wowhead=[[https://www.wowhead.com/wotlk/quest=8122]],image=[[assets/images/quests/placeholder.png]],desc=[[It is difficult to see, so deep we are in the conflict, but our spies report a weakening in the League of Arathor's resolve.  We must use this window and strike a brutal blow against them!  Return to Arathi Basin and throw yourself against our foes.  Curse them and kill them and control all five strategic bases!  Send their soldiers screaming and bleeding from the front lines, with stories of your cruelty on their mewling lips. Do this, and score a great victory for the Defilers.]],logDesc=[[Hold five bases in Arathi Basin at the same time, then return to Deathmaster Dwire in Hammerfall.]],rewards={{id=20131,qty=1}}}
DB[8123]={id=8123,zoneId=3358,name=[[Cut Arathor Supply Lines]],name_loc=[[Córtale el suministro a la Liga de Arathor]],level=55,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],exGroup=8123,poiX=-848,poiY=-3511,wowhead=[[https://www.wowhead.com/wotlk/quest=8123]],image=[[assets/images/quests/placeholder.png]],desc=[[The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies. You can help us, $N.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.]],logDesc=[[Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.]]}
