DB[8149]={id=8149,name=[[Honoring a Hero]],name_loc=[[En honor a un héroe]],level=-1,minLevel=30,giver=[[Wagner Hammerstrike]],giver_loc=[[Wagner Mazas]],giverType=[[NPC]],giverId=15011,ender=[[Wagner Hammerstrike]],ender_loc=[[Wagner Mazas]],enderType=[[NPC]],enderId=15011,poiX=-5060,poiY=-789,wowhead=[[https://www.wowhead.com/wotlk/quest=8149]],image=[[assets/images/quests/placeholder.png]],desc=[[During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf.  The Alliance acknowledges many heroes, but none weave a more tragic tale than that of Uther Lightbringer. Help us honor Uther by taking this offering to his tomb in the Western Plaguelands.  Place it at his statue, and then return to me.  I'll only be here through the end of the festival, so waste no time in giving Uther his tribute.]],logDesc=[[Travel to Uther's Tomb in Western Plaguelands and use Uther's Tribute at his statue, and then return to Wagner Hammerstrike outside Ironforge before the Harvest Festival is over.]],rewards={{id=20009,qty=1}}}
DB[8150]={id=8150,name=[[Honoring a Hero]],name_loc=[[En honor a un héroe]],level=-1,minLevel=30,giver=[[Javnir Nashak]],giverType=[[NPC]],giverId=15012,ender=[[Javnir Nashak]],enderType=[[NPC]],enderId=15012,poiX=1323,poiY=-4400,wowhead=[[https://www.wowhead.com/wotlk/quest=8150]],image=[[assets/images/quests/placeholder.png]],desc=[[During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf.  The Horde acknowledges many heroes, but none exemplify strength and sacrifice more than Grom Hellscream. Help us honor Grom by taking this offering to his monument in the Demon Fall Canyon of Ashenvale.  Place it at the base, and then return to me.  I'll only be here through the end of the festival, so waste no time in giving Grom his tribute.]],logDesc=[[Travel to Grom's Monument in the Demon Fall Canyon of Ashenvale and use Grom's Tribute at the base of the monument.  Return to Javnir Nashak outside Orgrimmar before the Harvest Festival is over.]],rewards={{id=20010,qty=1}}}
DB[8151]={id=8151,name=[[The Hunter's Charm]],name_loc=[[El talismán del cazador]],level=52,minLevel=50,giver=[[Holt Thunderhorn]],giver_loc=[[Holt Tronacuerno]],giverType=[[NPC]],giverId=3039,ender=[[Ogtinc]],enderType=[[NPC]],enderId=8405,rewardNextId=8153,poiX=3901,poiY=-5427,wowhead=[[https://www.wowhead.com/wotlk/quest=8151]],image=[[assets/images/quests/placeholder.png]],desc=[[Ogtinc of Azshara has sent out a call for seasoned hunters such as yourself.  He is a furbolg hunter who has left his tribe to aid the Cenarion Circle.  His teachings are meant to enrich the wisdom of others who share his craft, and guide them toward maintaining a balance.  You would do well to speak with him. Ogtinc resides atop the cliffs of Azshara, northeast from the Ruins of Eldarath.]],logDesc=[[Speak to Ogtinc in Azshara.]]}
