DB[8152]={id=8152,name=[[REUSE]],name_loc=[[REUSE]],level=52,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=8151,poiX=3901,poiY=-5427,wowhead=[[https://www.wowhead.com/wotlk/quest=8152]],image=[[assets/images/quests/placeholder.png]],desc=[[$N,when you feel you are ready,there is a wisened furbolg hunter by the name of Ogtinc who resides in Azshara.  He may be able to enhance your teaching,and provide you with guidance. Ogtinc is atop the cliffs northeast the Ruins of Eldarath in Azshara.]],logDesc=[[Speak with Ogtinc in Azshara.]]}
DB[8153]={id=8153,name=[[Courser Antlers]],name_loc=[[Cornamenta de trotador]],level=52,minLevel=50,giver=[[Ogtinc]],giverType=[[NPC]],giverId=8405,ender=[[Ogtinc]],enderType=[[NPC]],enderId=8405,prevId=8151,rewardNextId=8231,poiX=4688,poiY=-6521,wowhead=[[https://www.wowhead.com/wotlk/quest=8153]],image=[[assets/images/quests/placeholder.png]],desc=[[The courser wears the mightiest antlers in the known lands.  Such antlers are used to defend the courser, goring an attacker and often damaging the points.  Perfect, natural antlers are the sign of an animal spirit with supreme confidence. To hold such antlers will bestow the same confidence in you. Hunt the mosshoof courser, find the perfect antlers and bring them to me.]],logDesc=[[Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath.]]}
DB[8154]={id=8154,zoneId=3358,name=[[Arathi Basin Resources!]],name_loc=[[Los recursos de la Cuenca de Arathi]],level=45,minLevel=40,giverType=[[NPC]],enderType=[[NPC]],exGroup=8080,poiX=-1220,poiY=-2518,wowhead=[[https://www.wowhead.com/wotlk/quest=8154]],image=[[assets/images/quests/placeholder.png]],desc=[[War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts! That is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there. That is what I want from you, $N.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.]],logDesc=[[Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.]]}
