DB[8166]={id=8166,zoneId=3358,name=[[The Battle for Arathi Basin!]],name_loc=[[La batalla por la Cuenca de Arathi]],level=45,minLevel=40,giver=[[Field Marshal Oslight]],giver_loc=[[Mariscal de campo Uluz]],giverType=[[NPC]],giverId=14983,ender=[[Field Marshal Oslight]],ender_loc=[[Mariscal de campo Uluz]],enderType=[[NPC]],enderId=14983,exGroup=8105,poiX=990,poiY=1008,wowhead=[[https://www.wowhead.com/wotlk/quest=8166]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base. Assault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post! When you have done this to all four points, return to me.]],logDesc=[[Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.]]}
DB[8167]={id=8167,zoneId=3358,name=[[The Battle for Arathi Basin!]],name_loc=[[La batalla por la Cuenca de Arathi]],level=35,minLevel=30,giver=[[Field Marshal Oslight]],giver_loc=[[Mariscal de campo Uluz]],giverType=[[NPC]],giverId=14983,ender=[[Field Marshal Oslight]],ender_loc=[[Mariscal de campo Uluz]],enderType=[[NPC]],enderId=14983,exGroup=8105,poiX=990,poiY=1008,wowhead=[[https://www.wowhead.com/wotlk/quest=8167]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base. Assault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post! When you have done this to all four points, return to me.]],logDesc=[[Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.]]}
