DB[8169]={id=8169,zoneId=3358,name=[[The Battle for Arathi Basin!]],name_loc=[[La batalla por la Cuenca de Arathi]],level=45,minLevel=40,giver=[[Deathmaster Dwire]],giver_loc=[[Maestra de la muerte Duire]],giverType=[[NPC]],giverId=15021,ender=[[Deathmaster Dwire]],ender_loc=[[Maestra de la muerte Duire]],enderType=[[NPC]],enderId=15021,exGroup=8120,poiX=990,poiY=1008,wowhead=[[https://www.wowhead.com/wotlk/quest=8169]],image=[[assets/images/quests/placeholder.png]],desc=[[As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans! Go to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde. Go, $N.  Report back to me when this task is complete.]],logDesc=[[Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.]]}
DB[8170]={id=8170,zoneId=3358,name=[[The Battle for Arathi Basin!]],name_loc=[[La batalla por la Cuenca de Arathi]],level=35,minLevel=30,giver=[[Deathmaster Dwire]],giver_loc=[[Maestra de la muerte Duire]],giverType=[[NPC]],giverId=15021,ender=[[Deathmaster Dwire]],ender_loc=[[Maestra de la muerte Duire]],enderType=[[NPC]],enderId=15021,exGroup=8120,poiX=990,poiY=1008,wowhead=[[https://www.wowhead.com/wotlk/quest=8170]],image=[[assets/images/quests/placeholder.png]],desc=[[As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans! Go to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde. Go, $N.  Report back to me when this task is complete.]],logDesc=[[Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.]]}
