DB[8181]={id=8181,zoneId=19,name=[[Confront Yeh'kinya]],name_loc=[[La confrontación con Yeh'kinya]],level=58,minLevel=40,giver=[[Prospector Ironboot]],giver_loc=[[Prospector Ferrobota]],giverType=[[NPC]],giverId=10460,ender=[[Yeh'kinya]],enderType=[[NPC]],enderId=8579,prevId=4788,poiX=-6903,poiY=-4841,wowhead=[[https://www.wowhead.com/wotlk/quest=8181]],image=[[assets/images/quests/placeholder.png]],desc=[[My delvings into the Mosh'aru Tablets bear grim news, $N.  Hakkar's true form, the god himself, can be born again through the very egg into which you captured him.  Yeh'kinya told you it was to contain his evil, but it is to recreate it!  The troll has led you astray! Go to Yeh'kinya and demand the egg from him.  Pray that it is not too late to stop Hakkar's return!]],logDesc=[[Speak with Yeh'kinya.]],choiceRewards={{id=20218,qty=1},{id=20219,qty=1}}}
DB[8182]={id=8182,zoneId=440,name=[[The Hand of Rastakhan]],name_loc=[[La mano de Rastakhan]],level=58,minLevel=40,giver=[[Prospector Ironboot]],giver_loc=[[Prospector Ferrobota]],giverType=[[NPC]],giverId=10460,ender=[[Molthor]],ender_loc=[[Molthor]],enderType=[[NPC]],enderId=14875,prevId=8181,poiX=-11812,poiY=1261,wowhead=[[https://www.wowhead.com/wotlk/quest=8182]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, our worst fears have come.  Legend speaks of the Soulflayer ruling the ancient troll world through evil and terror, and his power was absolute.  If he cannot be stopped now, then his new reign may spread across all of Azeroth! There is a contingent of Zandalarian trolls who may help us stem this tide of darkness.  They have camped on Yojamba Isle, off the coast of Stranglethorn, west of the ruins of Zul'Kunda.  Speak with their leader, Molthor, and pray he knows how to defeat Hakkar.]],logDesc=[[Speak with Molthor in Stranglethorn.]]}
DB[8183]={id=8183,zoneId=19,name=[[The Heart of Hakkar]],name_loc=[[El corazón de Hakkar]],level=60,minLevel=58,giver=[[Heart of Hakkar]],giver_loc=[[Corazón de Hakkar]],giverType=[[NPC]],giverId=15069,ender=[[Molthor]],ender_loc=[[Molthor]],enderType=[[NPC]],enderId=14875,poiX=-11787,poiY=-1649,wowhead=[[https://www.wowhead.com/wotlk/quest=8183]],image=[[assets/images/quests/placeholder.png]],desc=[[The Heart of Hakkar burns from within.  Although the Soulflayer is defeated, the kernel of his power yet remains in this cursed organ.]],logDesc=[[Bring the Heart of Hakkar to Molthor on Yojamba Isle.]],choiceRewards={{id=19948,qty=1},{id=19950,qty=1},{id=19949,qty=1}}}
