DB[8201]={id=8201,zoneId=19,name=[[A Collection of Heads]],name_loc=[[Una colección de cabezas]],level=60,minLevel=58,giver=[[Exzhal]],giver_loc=[[Exzhal]],giverType=[[NPC]],giverId=14910,ender=[[Exzhal]],ender_loc=[[Exzhal]],enderType=[[NPC]],enderId=14910,poiX=-11828,poiY=1247,wowhead=[[https://www.wowhead.com/wotlk/quest=8201]],image=[[assets/images/quests/placeholder.png]],desc=[[It is true.  Hakkar now dwells in Zul'Gurub, bathing in the power of our gods.  Enthralled high priests now channel the energies of our most sacred divinities into the Soulflayer, who will soon have a strength beyond any being of Azeroth.  He must be stopped! Take this sacred cord, and string through it the heads of the high priests responsible for channeling our gods' energy. When you have done this, return to me.]],logDesc=[[String 5 Channeler's Heads, then return the Collection of Troll Heads to Exzhal on Yojamba Isle.]],choiceRewards={{id=20213,qty=1},{id=20215,qty=1},{id=20216,qty=1},{id=20217,qty=1}}}
