DB[8227]={id=8227,zoneId=19,name=[[Nat's Measuring Tape]],name_loc=[[Cinta métrica de Nat]],level=60,minLevel=58,giver=[[Battered Tackle Box]],giver_loc=[[Caja de aparejos maltrecha]],giverType=[[GO]],giverId=180366,ender=[[Nat Pagle]],enderType=[[NPC]],enderId=12919,poiX=-4139,poiY=-4060,wowhead=[[https://www.wowhead.com/wotlk/quest=8227]],image=[[assets/images/quests/placeholder.png]],desc=[[Amongst the shattered fishing lures and tackle is a rolled, silken measuring tape.  Attached to the tape is a label that reads: "Nat Pagle, Dustwallow Marsh."]],logDesc=[[Return Nat's Measuring Tape to Nat Pagle in Dustwallow Marsh.]]}
