DB[8231]={id=8231,name=[[Wavethrashing]],name_loc=[[Los vándalos marinos]],level=52,minLevel=50,giver=[[Ogtinc]],giverType=[[NPC]],giverId=8405,ender=[[Ogtinc]],enderType=[[NPC]],enderId=8405,prevId=8153,rewardNextId=8232,poiX=5081,poiY=-6417,wowhead=[[https://www.wowhead.com/wotlk/quest=8231]],image=[[assets/images/quests/placeholder.png]],desc=[[The wavethrasher is an amphibious beast living only here in Azshara.  They are powerful and resilient. The tough, reflective scales from a wavethrasher mirror the strength of the hunter. Track and hunt wavethrashers along the coast of Azshara, and bring me their scales.]],logDesc=[[Bring 6 Wavethrasher Scales to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.]]}
DB[8232]={id=8232,name=[[The Green Drake]],name_loc=[[El draco verde]],level=52,minLevel=50,giver=[[Ogtinc]],giverType=[[NPC]],giverId=8405,ender=[[Ogtinc]],enderType=[[NPC]],enderId=8405,prevId=8231,poiX=3901,poiY=-5427,wowhead=[[https://www.wowhead.com/wotlk/quest=8232]],image=[[assets/images/quests/placeholder.png]],desc=[[Now I set you on a dangerous hunt to slay the green drake, Morphaz, and bring his tooth to me.  Morphaz dwells deep in Temple of Atal'Hakkar, the entrance to which lies in Swamp of Sorrows. If you wish to defeat him, you must not go alone.  This drake is an enemy of many -- seek others who wish to destroy him. The drake's tooth represents the power a hunter will find in the company of others.  Bring it to me and you will have learned much.]],logDesc=[[Bring the Tooth of Morphaz to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.]],choiceRewards={{id=20083,qty=1},{id=19991,qty=1},{id=19992,qty=1}}}
DB[8233]={id=8233,name=[[A Simple Request]],name_loc=[[Un pedido sencillo]],level=52,minLevel=50,giver=[[Osborne the Night Man]],giver_loc=[[Osborne el Nocturno]],giverType=[[NPC]],giverId=918,ender=[[Lord Jorach Ravenholdt]],ender_loc=[[Lord Jorach Ravenholdt]],enderType=[[NPC]],enderId=6768,rewardNextId=8234,poiX=28,poiY=-1625,wowhead=[[https://www.wowhead.com/wotlk/quest=8233]],image=[[assets/images/quests/placeholder.png]],desc=[[Lord Jorach Ravenholdt has requested your presence.  The matter is secret, and I cannot say any more. Ravenholdt Manor is located in the Hillsbrad Foothills -- look for a path in the mountains northwest of Durnhold Keep.]],logDesc=[[Speak with Lord Jorach Ravenholdt in Ravenholdt Manor.]]}
