DB[8234]={id=8234,name=[[Sealed Azure Bag]],name_loc=[[Bolsa azur sellada]],level=52,minLevel=50,giver=[[Lord Jorach Ravenholdt]],giver_loc=[[Lord Jorach Ravenholdt]],giverType=[[NPC]],giverId=6768,ender=[[Archmage Xylem]],ender_loc=[[Archimago Xylem]],enderType=[[NPC]],enderId=8379,prevId=8233,rewardNextId=8235,poiX=4284,poiY=-5749,wowhead=[[https://www.wowhead.com/wotlk/quest=8234]],image=[[assets/images/quests/placeholder.png]],desc=[[First things first.  What I've lost is a small blue bag, the contents of which are a private matter. Don't bother going after the thieves, because they are already dead.  What we do know is the fools couldn't get the bag open. so they sold it to some timbermaw shaman in Azshara as a holy relic.  Clever. I need you to travel to Azshara and retrieve it from the shaman through subtlety... or force.  Better luck with the first method, I'd wager.  Once acquired, take it to Archmage Xylem.]],logDesc=[[Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara.  Then take the bag to Archmage Xylem, also found in Azshara.]]}
DB[8235]={id=8235,name=[[Encoded Fragments]],name_loc=[[Los trozos codificados]],level=52,minLevel=50,giver=[[Archmage Xylem]],giver_loc=[[Archimago Xylem]],giverType=[[NPC]],giverId=8379,ender=[[Archmage Xylem]],ender_loc=[[Archimago Xylem]],enderType=[[NPC]],enderId=8379,prevId=8234,rewardNextId=8236,poiX=4674,poiY=-7565,wowhead=[[https://www.wowhead.com/wotlk/quest=8235]],image=[[assets/images/quests/placeholder.png]],desc=[[Lord Ravenholdt has asked a favor of us both.  He wishes to remove the enchantment from this bag. Unfortunately, some of my books on the subject of dispelling were taken recently, only to be destroyed by savages.  The remains of my books are still valuable to me. If you can bring me enough of the encoded fragments, I can piece them back together.  Your best chance is to kill the beasts of Azshara, since they have a tendency to pick up just about anything.]],logDesc=[[Bring 10 Encoded Fragments to Archmage Xylem in Azshara.]]}
DB[8236]={id=8236,name=[[The Azure Key]],name_loc=[[La llave azur]],level=52,minLevel=50,giver=[[Archmage Xylem]],giver_loc=[[Archimago Xylem]],giverType=[[NPC]],giverId=8379,ender=[[Lord Jorach Ravenholdt]],ender_loc=[[Lord Jorach Ravenholdt]],enderType=[[NPC]],enderId=6768,prevId=8235,poiX=-1459,poiY=-4671,wowhead=[[https://www.wowhead.com/wotlk/quest=8236]],image=[[assets/images/quests/placeholder.png]],desc=[[It will take some time to decipher the fragments and remove the enchantment.  When I am complete, I'll deliver the bag to Lord Ravenholdt personally. There is still the matter of the key, said to be held by a green drake known as Morphaz.  The drake has made its home deep in the Temple of Atal'Hakkar, the entrance to which lies in the Swamp of Sorrows. Gather your friends and venture to his lair.  Lord Ravenholdt will await your return with the key.]],logDesc=[[Return the Azure Key to Lord Jorach Ravenholdt.]],choiceRewards={{id=19984,qty=1},{id=20255,qty=1},{id=19982,qty=1}}}
