DB[8240]={id=8240,zoneId=19,name=[[A Bijou for Zanza]],name_loc=[[Una joya para Zanza]],level=60,minLevel=58,giver=[[Vinchaxa]],giver_loc=[[Vinchaxa]],giverType=[[NPC]],giverId=15070,ender=[[Vinchaxa]],ender_loc=[[Vinchaxa]],enderType=[[NPC]],enderId=15070,poiX=-11842,poiY=1296,wowhead=[[https://www.wowhead.com/wotlk/quest=8240]],image=[[assets/images/quests/placeholder.png]],desc=[[The destruction of the various Hakkari Bijous is of grave importance to us, so much so that we welcome outsiders of the tribe to do so for themselves! Take any one of the bijous that you find in Zul'Gurub to the Altar of Zanza and destroy it.  For this one time alone, I will give you an additional Honor Token from our tribe; this is above and beyond what you would normally receive. Witness for yourself the blessings of Zanza!]],logDesc=[[Destroy any one of the Hakkari Bijous found in Zul'Gurub at the Altar of Zanza on Yojamba Isle.  When done, speak with Vinchaxa nearby.]],rewards={{id=19858,qty=1}}}
