DB[8250]={id=8250,name=[[Magecraft]],name_loc=[[Pura magia]],level=52,minLevel=50,giver=[[Archmage Shymm]],giver_loc=[[Archimago Shymm]],giverType=[[NPC]],giverId=3047,ender=[[Sanath Lim-yo]],enderType=[[NPC]],enderId=8395,poiX=3648,poiY=-4703,wowhead=[[https://www.wowhead.com/wotlk/quest=8250]],image=[[assets/images/quests/placeholder.png]],desc=[[Archmage Xylem has been asking around lately... for someone of your experience. If you wish to seek him out, you can find him in Azshara.  His tower is built high atop the cliffs, and the only way up is a teleport spell invoked by his arrogant servant, Sanath Lim-yo. Sanath makes camp below his master's tower.  To find him, travel to where Azshara's main road forks at the entrance to the Ruins of Eldarath.  From that spot, head directly north until you reach the cliffs.]],logDesc=[[Seek out Sanath Lim-yo and gain passage to see Archmage Xylem.]]}
