DB[8251]={id=8251,name=[[Magic Dust]],name_loc=[[El polvo mágico]],level=52,minLevel=50,giver=[[Archmage Xylem]],giver_loc=[[Archimago Xylem]],giverType=[[NPC]],giverId=8379,ender=[[Archmage Xylem]],ender_loc=[[Archimago Xylem]],enderType=[[NPC]],enderId=8379,prevId=8250,rewardNextId=8252,poiX=4379,poiY=-6281,wowhead=[[https://www.wowhead.com/wotlk/quest=8251]],image=[[assets/images/quests/placeholder.png]],desc=[[The blood elves in Azshara have developed a method for pulverizing the magical items they acquire.  This glittering dust they produce differs from the components normally acquired by a disenchantment spell. When I sent my apprentice to trade for the dust, he was killed without hesitation.  For that, they must pay. The time for talk is over, $N.  Find the blood elves along the cliffs of Azshara and use more "persuasive" methods to acquire their glittering dust.]],logDesc=[[Bring 10 Glittering Dust to Archmage Xylem.]]}
DB[8252]={id=8252,name=[[The Siren's Coral]],name_loc=[[El coral de las sirenas]],level=52,minLevel=50,giver=[[Archmage Xylem]],giver_loc=[[Archimago Xylem]],giverType=[[NPC]],giverId=8379,ender=[[Archmage Xylem]],ender_loc=[[Archimago Xylem]],enderType=[[NPC]],enderId=8379,prevId=8251,rewardNextId=8253,poiX=3085,poiY=-5820,wowhead=[[https://www.wowhead.com/wotlk/quest=8252]],image=[[assets/images/quests/placeholder.png]],desc=[[Take a look around you.  The ruins and beaches are overrun with spitelash.  Recently, the wretched creatures have learned to recognize the rare components indigenous to Azshara. Specifically, I speak of enchanted coral -- they are drawn to it by reasons unknown to me.  Now there is little coral left in the bay, and it is vital to my research.  I need you to separate some enchanted coral from the spitelash sirens and bring it to me.]],logDesc=[[Collect 6 Enchanted Coral and return them to Archmage Xylem.]]}
DB[8253]={id=8253,name=[[Destroy Morphaz]],name_loc=[[Destruye a Morphaz]],level=52,minLevel=50,giver=[[Archmage Xylem]],giver_loc=[[Archimago Xylem]],giverType=[[NPC]],giverId=8379,ender=[[Archmage Xylem]],ender_loc=[[Archimago Xylem]],enderType=[[NPC]],enderId=8379,prevId=8252,poiX=3982,poiY=-4760,wowhead=[[https://www.wowhead.com/wotlk/quest=8253]],image=[[assets/images/quests/placeholder.png]],desc=[[There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz. Years ago, he overwhelmed me in a bold ambush and consumed my apprentice whole.  While the loss of an apprentice is not unknown to me, this particular one carried an arcane shard of unsurpassed size and quality. You must gather powerful allies and delve into the temple.  Destroy Morphaz and recover the arcane shard from his ageless stomach.]],logDesc=[[Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.]],choiceRewards={{id=20035,qty=1},{id=20037,qty=1},{id=20036,qty=1}}}
DB[8254]={id=8254,name=[[Cenarion Aid]],name_loc=[[Ayuda a Cenarion]],level=52,minLevel=50,giver=[[High Priestess Laurena]],giver_loc=[[Suma sacerdotisa Laurena]],giverType=[[NPC]],giverId=376,ender=[[Ogtinc]],enderType=[[NPC]],enderId=8405,rewardNextId=8255,poiX=3901,poiY=-5427,wowhead=[[https://www.wowhead.com/wotlk/quest=8254]],image=[[assets/images/quests/placeholder.png]],desc=[[It is the way of the divine to help those in need.  The how is insignificant -- only the why matters. The Cenarion Circle has such a need.  Speak with Ogtinc to lend aid to their plight.  He resides atop the cliffs to the northeast of the Ruins of Eldarath in Azshara.]],logDesc=[[Seek out Ogtinc in Azshara.]]}
