DB[8274]={id=8274,name=[[Test Kill Quest]],name_loc=[[Misión de prueba]],level=5,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-9688,poiY=1522,wowhead=[[https://www.wowhead.com/wotlk/quest=8274]],image=[[assets/images/quests/placeholder.png]],desc=[[Got some time to spare?  Kill me some Murlocs and I'll give you something shiny!]],logDesc=[[Kill 5 Murlocs and come back to the test character.]]}
DB[8275]={id=8275,zoneId=1537,name=[[Taking Back Silithus]],name_loc=[[La reconquista de Silithus]],level=55,minLevel=54,giver=[[Cenarion Emissary Jademoon]],giver_loc=[[Emisaria Cenarion Lunajade]],giverType=[[NPC]],giverId=15187,ender=[[Windcaller Proudhorn]],ender_loc=[[Clamavientos Cuerno Digno]],enderType=[[NPC]],enderId=15191,rewardNextId=8280,poiX=-6848,poiY=756,wowhead=[[https://www.wowhead.com/wotlk/quest=8275]],image=[[assets/images/quests/placeholder.png]],desc=[[Attention, heroes of the Alliance!  The silithid menace has been left unchecked for too long.  Unfettered by any real opposition, they've been preparing all this time for a large-scale expansion.   Cenarion Circle forces are gathering in Silithus to take the fight to these wretched creatures and all able-bodied adventurers are hereby called to join us! Don't wait until it's too late!  Aid us in the defense of Azeroth! Report to Windcaller Proudhorn at Cenarion Hold for specific instructions!]],logDesc=[[Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.]]}
DB[8276]={id=8276,zoneId=1637,name=[[Taking Back Silithus]],name_loc=[[La reconquista de Silithus]],level=55,minLevel=54,giver=[[Cenarion Emissary Blackhoof]],giver_loc=[[Emisario Cenarion Pezuña Negra]],giverType=[[NPC]],giverId=15188,ender=[[Windcaller Proudhorn]],ender_loc=[[Clamavientos Cuerno Digno]],enderType=[[NPC]],enderId=15191,rewardNextId=8280,poiX=-6848,poiY=756,wowhead=[[https://www.wowhead.com/wotlk/quest=8276]],image=[[assets/images/quests/placeholder.png]],desc=[[Attention, champions of the Horde!  There's a threat we've left unchallenged for too long.  Tremors in the earth near silithid hives all around Azeroth have alerted us to large movements in their numbers as they prepare for expansion. Cenarion Circle forces are gathering in Silithus to take the fight to the silithid before it's too late!  No more shall they defile our lands! All able-bodied combatants are to report to Windcaller Proudhorn at Cenarion Hold!  The silithid shall be vanquished!]],logDesc=[[Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.]]}
DB[8277]={id=8277,zoneId=1377,name=[[Deadly Desert Venom]],name_loc=[[Veneno mortal del desierto]],level=55,minLevel=54,giver=[[Beetix Ficklespragg]],giver_loc=[[Beetix Castañeta]],giverType=[[NPC]],giverId=15189,ender=[[Beetix Ficklespragg]],ender_loc=[[Beetix Castañeta]],enderType=[[NPC]],enderId=15189,poiX=-6883,poiY=216,wowhead=[[https://www.wowhead.com/wotlk/quest=8277]],image=[[assets/images/quests/placeholder.png]],desc=[[Beetix Ficklespragg at your service!  My cousin Noggle makes a living gathering rare herbs for Cenarion Hold alchemists.  Or used to, anyway.  He came back from his last trip with a strong poison running though his veins. I've managed to slow down the venom, but to fully neutralize it I need poison samples from whatever stung him. Noggle arrived from the north, so I'd bet my shirt stonelash scorpids or sand skitterers did it.  Bring me some stingers and fangs and I'll try to make an antidote for him.]],logDesc=[[Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 8 Stonelash Scorpid Stingers and 8 Sand Skitterer Fangs. Return to her when you have completed the task.]]}
DB[8278]={id=8278,zoneId=1377,name=[[Noggle's Last Hope]],name_loc=[[La última esperanza de Noggle]],level=57,minLevel=54,giver=[[Beetix Ficklespragg]],giver_loc=[[Beetix Castañeta]],giverType=[[NPC]],giverId=15189,ender=[[Beetix Ficklespragg]],ender_loc=[[Beetix Castañeta]],enderType=[[NPC]],enderId=15189,prevId=8277,poiX=-7584,poiY=1117,wowhead=[[https://www.wowhead.com/wotlk/quest=8278]],image=[[assets/images/quests/placeholder.png]],desc=[[Blasted!  The antidote didn't work.  Noggle must've been stung by one of the stronger creatures in the far south. I'm going to need you to go there and get me some more samples, $N.  The good news is that since their poison is stronger I won't require as many.  The bad news is that there are more kinds of poisonous creatures crawling around the southern area so you'll have to draw from more sources.]],logDesc=[[Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 3 Stonelash Pincer Stingers, 3 Stonelash Flayer Stingers and 3 Rock Stalker Fangs.]],choiceRewards={{id=13446,qty=2},{id=13444,qty=1}}}
DB[8279]={id=8279,zoneId=1377,name=[[The Twilight Lexicon]],name_loc=[[El Lexicón Crepuscular]],level=60,minLevel=54,giver=[[Hermit Ortell]],giver_loc=[[Ermitaño Ortell]],giverType=[[NPC]],giverId=15194,ender=[[Hermit Ortell]],ender_loc=[[Ermitaño Ortell]],enderType=[[NPC]],enderId=15194,prevId=8285,rewardNextId=8287,poiX=-6784,poiY=1593,wowhead=[[https://www.wowhead.com/wotlk/quest=8279]],image=[[assets/images/quests/placeholder.png]],desc=[[The Twilight's Hammer are not kind to those that leave their ranks.  They hunt me to this day like I'm some sort of beast!  Needless to say, an enemy of theirs is a friend of mine! To decipher this Tablet I'll need the book used by their scribes to encode secret messages: the Twilight Lexicon.  It's such an important tool that they keep its three chapters in different locations!  The officers entrusted with the Lexicon are known as Twilight Keepers.  Look for them at the Twilight's Hammer camps.]],logDesc=[[Bring the three chapters of the Twilight Lexicon to Hermit Ortell in Silithus.]]}
DB[8280]={id=8280,zoneId=1377,name=[[Securing the Supply Lines]],name_loc=[[Asegurar las rutas de suministros]],level=55,minLevel=54,giver=[[Windcaller Proudhorn]],giver_loc=[[Clamavientos Cuerno Digno]],giverType=[[NPC]],giverId=15191,ender=[[Windcaller Proudhorn]],ender_loc=[[Clamavientos Cuerno Digno]],enderType=[[NPC]],enderId=15191,rewardNextId=8281,poiX=-6684,poiY=85,wowhead=[[https://www.wowhead.com/wotlk/quest=8280]],image=[[assets/images/quests/placeholder.png]],desc=[[Cenarion Hold is a location of utmost strategic importance.  I'm convinced that while we hold it our victory over the silithid is guaranteed.  Provided our influx supplies can be maintained, that is. Desert worms have proven to be more of a threat to our supply caravans than even the silithid themselves.  Just this morning, a large shipment of morrowgrain was ravaged by a group of dredge strikers.  I need you to thin their numbers to ensure our supplies aren't jeopardized.]],logDesc=[[Windcaller Proudhorn at Cenarion Hold in Silithus wants you to kill 15 Dredge Strikers.]]}
DB[8281]={id=8281,zoneId=1377,name=[[Stepping Up Security]],name_loc=[[Intensificar la seguridad]],level=57,minLevel=54,giver=[[Windcaller Proudhorn]],giver_loc=[[Clamavientos Cuerno Digno]],giverType=[[NPC]],giverId=15191,ender=[[Windcaller Proudhorn]],ender_loc=[[Clamavientos Cuerno Digno]],enderType=[[NPC]],enderId=15191,prevId=8280,poiX=-6850,poiY=1251,wowhead=[[https://www.wowhead.com/wotlk/quest=8281]],image=[[assets/images/quests/placeholder.png]],desc=[[Your performance has been truly exemplary so far, $N.  Our supply lines are not completely safe yet, however.  In the absence of dredge strikers, their larger southern cousins will surely move in to take their place in the north. You'll have to kill quite a few dredge crushers to keep them at bay, but we cannot leave the safety of our supply lines to chance.]],logDesc=[[Windcaller Proudhorn at Cenarion Hold in Silithus wants you to slay 20 Dredge Crushers.]]}
DB[8282]={id=8282,zoneId=1377,name=[[Noggle's Lost Satchel]],name_loc=[[La cartera perdida de Noggle]],level=58,minLevel=54,giver=[[Noggle Ficklespragg]],giver_loc=[[Noggle Castañeta]],giverType=[[NPC]],giverId=15190,ender=[[Noggle Ficklespragg]],ender_loc=[[Noggle Castañeta]],enderType=[[NPC]],enderId=15190,prevId=8278,poiX=-8081,poiY=985,wowhead=[[https://www.wowhead.com/wotlk/quest=8282]],image=[[assets/images/quests/placeholder.png]],desc=[[Where am I?  Where's my bag? *gasp* I must've lost it while fleeing from Deathclasp, the giant scorpid.  In my rush to escape I walked right into a nest of stonelash flayers. The satchel I was carrying had all sorts of rare reagents in it.  Without them, me and Beetix won't be able to make the potions that Cenarion Hold needs.  I'm too weak to get up yet, but I can make it worth your while if you bring back my reagents. I ran into Deathclasp in the southern mountain range, behind Bronzebeard's camp.]],logDesc=[[Retrieve Noggle's Satchel from the mountains in the south of Silithus and return it to him at Cenarion Hold.]],choiceRewards={{id=13452,qty=2},{id=13447,qty=2}}}
DB[8283]={id=8283,zoneId=1377,name=[[Wanted - Deathclasp, Terror of the Sands]],name_loc=[[Se busca: Pinzamorten el Terror de las arenas]],level=59,minLevel=54,giver=[[Wanted Poster: Deathclasp]],giver_loc=[[Cartel de Se busca: Pinzamorten]],giverType=[[GO]],giverId=180448,ender=[[Vish Kozus]],ender_loc=[[Vish Kozus]],enderType=[[NPC]],enderId=15182,poiX=-8113,poiY=972,wowhead=[[https://www.wowhead.com/wotlk/quest=8283]],image=[[assets/images/quests/placeholder.png]],desc=[[The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity.  She presents a great threat to patrols and expeditions in the southern regions.  Individuals participating in her destruction will be remunerated handsomely.  Inquire with Captain Vish Kozus, at the top of the Cenarion Hold Watchtower, regarding a reward.]],logDesc=[[Bring Deathclasp's Pincer to Vish Kozus, Captain of the Guard.]],choiceRewards={{id=20646,qty=1},{id=20647,qty=1}}}
DB[8284]={id=8284,zoneId=1377,name=[[The Twilight Mystery]],name_loc=[[El misterio Crepuscular]],level=58,minLevel=54,giver=[[Geologist Larksbane]],giver_loc=[[Geóloga Trotuina]],giverType=[[NPC]],giverId=15183,ender=[[Geologist Larksbane]],ender_loc=[[Geóloga Trotuina]],enderType=[[NPC]],enderId=15183,rewardNextId=8285,poiX=-6186,poiY=1659,wowhead=[[https://www.wowhead.com/wotlk/quest=8284]],image=[[assets/images/quests/placeholder.png]],desc=[[A camp of Twilight's Hammer cultists once thrived northwest of here.  If you were to venture there now, you'd find the area swarming with elementals and nothing but scattered pieces of wood and canvas to mark the spot where the camp was. I've recovered a few fragments of a clay tablet from the site, but I have too few of them to piece together anything useful.  See if you can find the remaining tablet fragments so we can shed some light into the Twilight's Hammer presence here in Silithus.]],logDesc=[[Geologist Larksbane at Cenarion Hold in Silithus wants you to collect 8 Twilight Tablet Fragments.]]}
DB[8285]={id=8285,zoneId=1377,name=[[The Deserter]],name_loc=[[El desertor]],level=59,minLevel=54,giver=[[Geologist Larksbane]],giver_loc=[[Geóloga Trotuina]],giverType=[[NPC]],giverId=15183,ender=[[Hermit Ortell]],ender_loc=[[Ermitaño Ortell]],enderType=[[NPC]],enderId=15194,prevId=8284,rewardNextId=8279,poiX=-7579,poiY=197,wowhead=[[https://www.wowhead.com/wotlk/quest=8285]],image=[[assets/images/quests/placeholder.png]],desc=[[There are rumors of a Twilight's Hammer member called Ortell having deserted his sect.  Word has it he hid in the mountains south of Southwind Village, where he lives as a hermit.  Perhaps you can enlist his help in deciphering the tablet. Take the restored tablet with you and seek out Ortell.]],logDesc=[[Take the restored tablet to Hermit Ortell in Silithus. ]]}
DB[8286]={id=8286,zoneId=1377,name=[[What Tomorrow Brings]],name_loc=[[Lo que nos depara el futuro]],level=60,minLevel=60,giver=[[Baristolth of the Shifting Sands]],giver_loc=[[Baristolth del Mar de Dunas]],giverType=[[NPC]],giverId=15180,ender=[[Baristolth of the Shifting Sands]],ender_loc=[[Baristolth del Mar de Dunas]],enderType=[[NPC]],enderId=15180,rewardNextId=8288,poiX=-8215,poiY=-4694,wowhead=[[https://www.wowhead.com/wotlk/quest=8286]],image=[[assets/images/quests/placeholder.png]],desc=[[The embrace of death had all but overcome my being when he intervened. He breathed only once upon my maimed body and then waited patiently for the sands of time to cleanse my wounds. "Forever you will remain if you must," he said, and with those words I was bound as a Watcher. Look now to the desert. The second war is upon us. You must seek out the resting place of the Bronze. Venture to the Caverns of Time and see if the master has returned. I must be sure before I am able to proceed.]],logDesc=[[Venture to the Caverns of Time in Tanaris and find Anachronos, Brood of Nozdormu.]]}
DB[8287]={id=8287,zoneId=1377,name=[[A Terrible Purpose]],name_loc=[[Un propósito terrible]],level=60,minLevel=54,giver=[[Hermit Ortell]],giver_loc=[[Ermitaño Ortell]],giverType=[[NPC]],giverId=15194,ender=[[Commander Mar'alith]],ender_loc=[[Comandante Mar'alith]],enderType=[[NPC]],enderId=15181,prevId=8279,poiX=-6752,poiY=824,wowhead=[[https://www.wowhead.com/wotlk/quest=8287]],image=[[assets/images/quests/placeholder.png]],desc=[[Ok, here we are... a pretty valuable chunk of information, I must say!  I've seen the Cenarion Circle forces arrive at Silithus.  They plan to drive the Twilight's Hammer out, don't they?  This will help.   Take this parchment to their leader, Commander Mar'alith.  Soon the Twilight's Hammer will be vanquished and I will be outside their grasp for good!]],logDesc=[[Take the Decoded Tablet Parchment to Commander Mar'alith.]]}
DB[8288]={id=8288,zoneId=2677,name=[[Only One May Rise]],name_loc=[[Solo uno puede alzarse]],level=60,minLevel=60,giver=[[Baristolth of the Shifting Sands]],giver_loc=[[Baristolth del Mar de Dunas]],giverType=[[NPC]],giverId=15180,ender=[[Baristolth of the Shifting Sands]],ender_loc=[[Baristolth del Mar de Dunas]],enderType=[[NPC]],enderId=15180,prevId=8286,rewardNextId=8301,poiX=-6805,poiY=815,wowhead=[[https://www.wowhead.com/wotlk/quest=8288]],image=[[assets/images/quests/placeholder.png]],desc=[[There is no time to waste! A hero must be found! The task I give will require an army to complete but only one may rise from the throng of would be champions to take on the burden and responsibility of an ally of the Brood. Within the lair of the Lord of Blackrock is a most cruel beast. The Broodlord Lashlayer guards the Halls of Strife, blocking the way into Nefarian's inner sanctum. Slay the foul aberration and return his head to me. Do this and you may begin the next step of your journey.]],logDesc=[[Return the Head of the Broodlord Lashlayer to Baristolth of the Shifting Sands at Cenarion Hold in Silithus.]]}
DB[8289]={id=8289,zoneId=3277,name=[[Talismans of Merit]],name_loc=[[Talismanes del mérito]],level=15,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],poiX=1448,poiY=-1867,wowhead=[[https://www.wowhead.com/wotlk/quest=8289]],image=[[assets/images/quests/placeholder.png]]}
DB[8291]={id=8291,zoneId=3277,name=[[Vanquish the Invaders!]],name_loc=[[¡Expulsa al invasor!]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],exGroup=7788,poiX=1448,poiY=-1867,wowhead=[[https://www.wowhead.com/wotlk/quest=8291]],image=[[assets/images/quests/placeholder.png]],desc=[[Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war. Enter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces! Do this, and earn a talisman of merit.  Bring me such a talisman, $N, and I shall reward you.]],logDesc=[[Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.]]}
DB[8292]={id=8292,zoneId=3277,name=[[Talismans of Merit]],name_loc=[[Talismanes del mérito]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],prevId=8291,exGroup=7788,poiX=1448,poiY=-1867,wowhead=[[https://www.wowhead.com/wotlk/quest=8292]],image=[[assets/images/quests/placeholder.png]]}
DB[8293]={id=8293,zoneId=3277,name=[[Mark of Honor]],name_loc=[[Marca de Honor]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],prevId=8294,exGroup=7922,poiX=1044,poiY=-2099,wowhead=[[https://www.wowhead.com/wotlk/quest=8293]],image=[[assets/images/quests/placeholder.png]]}
DB[8294]={id=8294,zoneId=3277,name=[[Quell the Silverwing Usurpers]],name_loc=[[Acaba con los usurpadores Ala de Plata]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],exGroup=7922,poiX=1044,poiY=-2099,wowhead=[[https://www.wowhead.com/wotlk/quest=8294]],image=[[assets/images/quests/placeholder.png]],desc=[[The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours! Let the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $N, and you will be rewarded.]],logDesc=[[Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.]]}
DB[8296]={id=8296,zoneId=3277,name=[[Mark of Honor]],name_loc=[[Marca de Honor]],level=15,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],poiX=1044,poiY=-2099,wowhead=[[https://www.wowhead.com/wotlk/quest=8296]],image=[[assets/images/quests/placeholder.png]]}
DB[8297]={id=8297,zoneId=3358,name=[[Arathi Basin Resources!]],name_loc=[[Los recursos de la Cuenca de Arathi]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],exGroup=8080,poiX=-1220,poiY=-2518,wowhead=[[https://www.wowhead.com/wotlk/quest=8297]],image=[[assets/images/quests/placeholder.png]],desc=[[War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts! That is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there. That is what I want from you, $N.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.]],logDesc=[[Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.]]}
DB[8298]={id=8298,zoneId=3358,name=[[More Resource Crates]],name_loc=[[Más cajas de suministros]],level=60,minLevel=60,giver=[[Sergeant Maclear]],giver_loc=[[Sargento Maclear]],giverType=[[NPC]],giverId=14984,ender=[[Sergeant Maclear]],ender_loc=[[Sargento Maclear]],enderType=[[NPC]],enderId=14984,prevId=8297,exGroup=8080,poiX=-1220,poiY=-2518,wowhead=[[https://www.wowhead.com/wotlk/quest=8298]],image=[[assets/images/quests/placeholder.png]]}
DB[8299]={id=8299,zoneId=3358,name=[[Cut Arathor Supply Lines]],name_loc=[[Córtale el suministro a la Liga de Arathor]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],exGroup=8123,poiX=-848,poiY=-3511,wowhead=[[https://www.wowhead.com/wotlk/quest=8299]],image=[[assets/images/quests/placeholder.png]],desc=[[The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies. You can help us, $N.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.]],logDesc=[[Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.]]}
DB[8300]={id=8300,zoneId=3358,name=[[More Resource Crates]],name_loc=[[Más cajas de suministros]],level=60,minLevel=60,giver=[[Deathstalker Mortis]],giver_loc=[[Mortacechador Mortis]],giverType=[[NPC]],giverId=15022,ender=[[Deathstalker Mortis]],ender_loc=[[Mortacechador Mortis]],enderType=[[NPC]],enderId=15022,prevId=8299,exGroup=8123,poiX=-848,poiY=-3511,wowhead=[[https://www.wowhead.com/wotlk/quest=8300]],image=[[assets/images/quests/placeholder.png]]}
DB[8301]={id=8301,zoneId=1377,name=[[The Path of the Righteous]],name_loc=[[El camino del honrado]],level=60,minLevel=60,giver=[[Baristolth of the Shifting Sands]],giver_loc=[[Baristolth del Mar de Dunas]],giverType=[[NPC]],giverId=15180,ender=[[Baristolth of the Shifting Sands]],ender_loc=[[Baristolth del Mar de Dunas]],enderType=[[NPC]],enderId=15180,prevId=8288,poiX=-6805,poiY=815,wowhead=[[https://www.wowhead.com/wotlk/quest=8301]],image=[[assets/images/quests/placeholder.png]],desc=[[The Brood of Nozdormu are naturally distrusting of the lesser races. While it is true that you have proven to me that you have the potential makings of a hero, the time has come to prove this to my master. Hive'Ashi, Hive'Zora, Hive'Regal: All swarming with activity and all a threat to our existence. Slay silithid at these hives and take from them a fragment of their carapace. When you can carry no more, return to me and I shall strengthen your resolve.]],logDesc=[[Collect 200 Silithid Carapace Fragments and return to Baristolth.]],rewards={{id=20403,qty=1}}}
DB[8302]={id=8302,zoneId=1377,name=[[The Hand of the Righteous]],name_loc=[[La mano del honrado]],level=60,minLevel=60,giver=[[Baristolth of the Shifting Sands]],giver_loc=[[Baristolth del Mar de Dunas]],giverType=[[NPC]],giverId=15180,ender=[[Baristolth of the Shifting Sands]],ender_loc=[[Baristolth del Mar de Dunas]],enderType=[[NPC]],enderId=15180,prevId=8301,poiX=-6805,poiY=815,wowhead=[[https://www.wowhead.com/wotlk/quest=8302]],image=[[assets/images/quests/placeholder.png]],desc=[[Choose your deputies wisely, mortal. Each time you return with your task complete, a new deputy you will be allowed to choose. With that said, I require more of the carapace fragments. Waste no time!]],logDesc=[[Collect 200 Silithid Carapace Fragments and return to Baristolth.]],rewards={{id=20403,qty=1}}}
DB[8303]={id=8303,zoneId=1377,name=[[Anachronos]],name_loc=[[Anacronos]],level=60,minLevel=60,giver=[[Baristolth of the Shifting Sands]],giver_loc=[[Baristolth del Mar de Dunas]],giverType=[[NPC]],giverId=15180,ender=[[Anachronos]],ender_loc=[[Anacronos]],enderType=[[NPC]],enderId=15192,prevId=8301,rewardNextId=8305,poiX=-8240,poiY=-4649,wowhead=[[https://www.wowhead.com/wotlk/quest=8303]],image=[[assets/images/quests/placeholder.png]],desc=[[It is time, $N. I must apologize for keeping so much in secret. Enemies abound, even under our very noses. Please, read from this tome and learn. Take the knowledge I give to you and seek out our master.]],logDesc=[[Seek out Anachronos at the Caverns of Time in Tanaris.]]}
DB[8304]={id=8304,zoneId=1377,name=[[Dearest Natalia]],name_loc=[[Queridísima Natalia]],level=60,minLevel=58,giver=[[Commander Mar'alith]],giver_loc=[[Comandante Mar'alith]],giverType=[[NPC]],giverId=15181,ender=[[Commander Mar'alith]],ender_loc=[[Comandante Mar'alith]],enderType=[[NPC]],enderId=15181,rewardNextId=8306,poiX=-8030,poiY=1123,wowhead=[[https://www.wowhead.com/wotlk/quest=8304]],image=[[assets/images/quests/placeholder.png]],desc=[[My dear Natalia has gone missing. Truth be told, she had been acting strangely for weeks leading up to her disappearance. I had caught her talking to herself when no one was around on more than one occasion. She was adamant that everything was ok and that she must be allowed to continue her research. She was last seen heading to Bronzebeard's camp to the south. My soldiers are spread too thin, $N. I need you to go to Bronzebeard's camp and question those dwarves.]],logDesc=[[Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold. Once you have gathered the requested information, return to Commander Mar'alith.]]}
DB[8305]={id=8305,zoneId=1377,name=[[Long Forgotten Memories]],name_loc=[[Recuerdos olvidados]],level=60,minLevel=60,giver=[[Anachronos]],giver_loc=[[Anacronos]],giverType=[[NPC]],giverId=15192,ender=[[Crystalline Tear]],ender_loc=[[Lágrima cristalina]],enderType=[[GO]],enderId=180633,prevId=8303,rewardNextId=8519,poiX=-8029,poiY=1539,wowhead=[[https://www.wowhead.com/wotlk/quest=8305]],image=[[assets/images/quests/placeholder.png]],desc=[[In the southern desert of Silithus, near the sacred barrier, exists a single crystalline tear. This tear serves as a symbol of the great losses beset upon us during the War of the Shifting Sands. Locate this tear and gaze into its depths to gain enlightenment. ]],logDesc=[[Locate the Crystalline Tear in Silithus and gaze into its depths.]]}
DB[8306]={id=8306,zoneId=1377,name=[[Into The Maw of Madness]],name_loc=[[En las fauces de la locura]],level=60,minLevel=58,giver=[[Commander Mar'alith]],giver_loc=[[Comandante Mar'alith]],giverType=[[NPC]],giverId=15181,ender=[[Commander Mar'alith]],ender_loc=[[Comandante Mar'alith]],enderType=[[NPC]],enderId=15181,prevId=8304,poiX=-6752,poiY=824,wowhead=[[https://www.wowhead.com/wotlk/quest=8306]],image=[[assets/images/quests/placeholder.png]],desc=[[I need you to venture into Hive'Regal and find what became of my dearest Natalia, $N. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you go back and speak with those dwarves. They might be able to give you some tips on dealing with the silithid that inhabit that hive. And $N, if she truly is as mad as they say... do what you must. <Commander Mar'alith turns away from you.> ]],logDesc=[[Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith. Do not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you. And $N, remember the Commander's words: "Do what you must..."]],rewards={{id=20724,qty=1}}}
DB[8307]={id=8307,name=[[Desert Recipe]],name_loc=[[Receta del desierto]],level=57,minLevel=54,giver=[[Calandrath]],giver_loc=[[Calandrath]],giverType=[[NPC]],giverId=15174,ender=[[Sandy Cookbook]],ender_loc=[[Libro de cocina de Sandy]],enderType=[[GO]],enderId=180503,rewardNextId=8313,poiX=-7011,poiY=1216,wowhead=[[https://www.wowhead.com/wotlk/quest=8307]],image=[[assets/images/quests/placeholder.png]],desc=[[Adapting to life in the desert has been difficult to say the least.  Not only do I miss the birds and trees of Auberdine but our food selection is severely limited by this arid environment.  I'm trying to learn about desert herbs, but there aren't many. I've seen Twilight's Hammer groups from the camp west of here hunt sandworms for food.  Sandworm meat is so bitter though, I can't imagine how they make it palatable.  Keep your eyes open if you go to their camp and let me know if you learn anything.]],logDesc=[[Look for information about cooking Sandworm Meat at the Twilight's Hammer camp west of Cenarion Hold.]]}
DB[8308]={id=8308,zoneId=1377,name=[[Brann Bronzebeard's Lost Letter]],name_loc=[[La carta perdida de Brann Barbabronce]],level=60,minLevel=58,giverType=[[NPC]],ender=[[Rutgar Glyphshaper]],ender_loc=[[Rutgar Glifoforma]],enderType=[[NPC]],enderId=15170,poiX=-8013,poiY=1100,wowhead=[[https://www.wowhead.com/wotlk/quest=8308]],image=[[assets/images/quests/placeholder.png]],desc=[[To Whom It May Concern: If you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow. Found information about a Titan. Great battle between him and an Old God. Yes, a bona fide Old God. Found ancient tunnel leading to Ahn'Qiraj. Taking it. Take this letter to my old camp. Make sure my monkey is getting adequate food, water, and hugs. -Brann Bronzebeard, Explorer Extreme P.S. Watch out for crazy Old God worshipping night elf.]],logDesc=[[Take Brann Bronzebeard's Letter to Bronzebeard's Encampment in southern Silithus.]],rewards={{id=20723,qty=1}}}
DB[8309]={id=8309,zoneId=1377,name=[[Glyph Chasing]],name_loc=[[Los grabados de los glifos]],level=60,minLevel=58,giver=[[Rutgar Glyphshaper]],giver_loc=[[Rutgar Glifoforma]],giverType=[[NPC]],giverId=15170,ender=[[Rutgar Glyphshaper]],ender_loc=[[Rutgar Glifoforma]],enderType=[[NPC]],enderId=15170,prevId=8304,nextId=8314,exGroup=-8309,poiX=-8013,poiY=1100,wowhead=[[https://www.wowhead.com/wotlk/quest=8309]],image=[[assets/images/quests/placeholder.png]],desc=[[After our initial foray into the hives and Mistress Mar'alith's subsequent madness the three hives have been spewing out bugs! The increased activity might be tied into the glyphs covering those strange crystals. We must get a rubbing from crystals in all three hives. If we can get those rubbings, we might be able to make sense of this madness. Take this transcription set  and hit those hives, $N. Don't come back until you've gotten copies from each hive.]],logDesc=[[Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive. Use the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task.]]}
DB[8310]={id=8310,zoneId=1377,name=[[Breaking the Code]],name_loc=[[Descifrar el código]],level=60,minLevel=58,giver=[[Frankal Stonebridge]],giver_loc=[[Frankal Petraponte]],giverType=[[NPC]],giverId=15171,ender=[[Frankal Stonebridge]],ender_loc=[[Frankal Petraponte]],enderType=[[NPC]],enderId=15171,prevId=8304,nextId=8314,exGroup=-8309,poiX=-6569,poiY=758,wowhead=[[https://www.wowhead.com/wotlk/quest=8310]],image=[[assets/images/quests/placeholder.png]],desc=[[I think I can formulate an elixir that will allow us to more readily decipher the glyphs and language of the silithid and Qiraji! What do I need? Glad you asked! I need brains! More specifically, a brain from each silithid type that inhabit the hives. Bring me brains and Rutgar's work might not be for naught.]],logDesc=[[Frankal Stonebridge at Bronzebeard's Encampment in Silithus wants you to recover a Hive'Zora Silithid Brain, Hive'Ashi Silithid Brain, and a Hive'Regal Silithid Brain. Return to Frankal when you have completed this task.]]}
DB[8311]={id=8311,name=[[Hallow's End Treats for Jesper!]],name_loc=[[Golosinas de Halloween para Jesper]],level=-1,minLevel=10,giver=[[Jesper]],giverType=[[NPC]],giverId=15310,ender=[[Jesper]],enderType=[[NPC]],enderId=15310,poiX=-8595,poiY=741,wowhead=[[https://www.wowhead.com/wotlk/quest=8311]],image=[[assets/images/quests/placeholder.png]],desc=[[I want to go trick-or-treating, but I can't because I'm sick.  If you go for me, I'd trade you the candy you get for some I already have!  I think you'd like this candy - it makes you turn into things both funny and scary! Each of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a little gnome named Talvash in Ironforge is handing out candy as well.  When you have all the candy, bring them back to me here!]],logDesc=[[Speak with the innkeepers of Stormwind, Ironforge, and Darnassus, as well as Talvash del Kissel in Ironforge.  Perform the tricks they ask of you in exchange for the treats they offer. Return to Jesper at the Stormwind Orphanage with a Darnassus Marzipan, Gnomeregan Gumdrop, Stormwind Nougat, and Ironforge Mint.]],rewards={{id=20557,qty=30}}}
DB[8312]={id=8312,name=[[Hallow's End Treats for Spoops!]],name_loc=[[Golosinas de Halloween para Pupas]],level=-1,minLevel=10,giver=[[Spoops]],giver_loc=[[Pupas]],giverType=[[NPC]],giverId=15309,ender=[[Spoops]],ender_loc=[[Pupas]],enderType=[[NPC]],enderId=15309,poiX=2061,poiY=-4683,wowhead=[[https://www.wowhead.com/wotlk/quest=8312]],image=[[assets/images/quests/placeholder.png]],desc=[[I want to go trick-or-treating, but I can't because I'm sick.  If you go for me, I'd trade you the candy you get for some I already have!  I think you'd like this candy - it makes you turn into things both funny and scary! Each of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a troll named Kali Remik in Sen'jin Village is handing out candy as well.  When you have all the candy, bring them back to me here!]],logDesc=[[Speak with the innkeepers of Orgrimmar, Undercity, and Thunder Bluff, as well as Kali Remik in Sen'jin Village.  Perform the tricks they ask of you in exchange for the treats they offer. Return to Spoops at the Orgrimmar Orphanage with a Thunder Bluff Marzipan, Darkspear Gumdrop, Orgrimmar Nougat, and Undercity Mint.]],rewards={{id=20557,qty=30}}}
DB[8313]={id=8313,name=[[Sharing the Knowledge]],name_loc=[[Compartir el conocimiento]],level=57,minLevel=54,giver=[[Sandy Cookbook]],giver_loc=[[Libro de cocina de Sandy]],giverType=[[GO]],giverId=180503,ender=[[Calandrath]],ender_loc=[[Calandrath]],enderType=[[NPC]],enderId=15174,prevId=8307,rewardNextId=8317,poiX=-6868,poiY=730,wowhead=[[https://www.wowhead.com/wotlk/quest=8313]],image=[[assets/images/quests/placeholder.png]],desc=[[While the recipe for cooking sandworm meat is legible, it contains references to herbs and spices you've never heard of.  Calandrath might have enough knowledge of the plants that grow in the desert to make sense of it.]],logDesc=[[Bring the Torn Recipe Page to Calandrath at the inn in Cenarion Hold.]]}
DB[8314]={id=8314,zoneId=1377,name=[[Unraveling the Mystery]],name_loc=[[Desentrañar el misterio]],level=60,minLevel=58,giver=[[Rutgar Glyphshaper]],giver_loc=[[Rutgar Glifoforma]],giverType=[[NPC]],giverId=15170,ender=[[Geologist Larksbane]],ender_loc=[[Geóloga Trotuina]],enderType=[[NPC]],enderId=15183,rewardNextId=8315,poiX=-6828,poiY=807,wowhead=[[https://www.wowhead.com/wotlk/quest=8314]],image=[[assets/images/quests/placeholder.png]],desc=[[We're on the verge of a breakthrough, $N! The rubbings you recovered have allowed us to recreate the glyphs on this crystalline prism. They are apparently a means for the Qiraji and other unknown entities to communicate various messages to the silithid. Unfortunately, that is all we could get out of the glyphs. We need to find a way to unlock the messages hidden within the crystals. Take the glyphed crystal prism to Geologist Larksbane at Cenarion Hold.  She might be able to help.]],logDesc=[[Rutgar Glyphshaper at Bronzebeard's Encampment wants you to deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus.]]}
DB[8315]={id=8315,zoneId=1377,name=[[The Calling]],name_loc=[[La llamada]],level=60,minLevel=58,giver=[[Geologist Larksbane]],giver_loc=[[Geóloga Trotuina]],giverType=[[NPC]],giverId=15183,ender=[[Geologist Larksbane]],ender_loc=[[Geóloga Trotuina]],enderType=[[NPC]],enderId=15183,prevId=8314,poiX=-7308,poiY=839,wowhead=[[https://www.wowhead.com/wotlk/quest=8315]],image=[[assets/images/quests/placeholder.png]],desc=[[The glyphs illustrate an emissary of the Qiraji meeting with three silithid at the bones of a large dragon. Above the glyphs is what I can only assume to be a code of some sort. This code might very well be the key to summoning the emissary. I will create a copy of the glyph code that you must use in the sand at the Bones of Grakkarond. If I am right, the Overlords will come thinking that new data is ready for transmission. Strike them down and confront the emissary. He holds the key to the crystals...]],logDesc=[[Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary. You have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed. Assemble an army for this task, $N!]]}
DB[8316]={id=8316,zoneId=1377,name=[[Armaments of War]],name_loc=[[Armamentos de guerra]],level=60,minLevel=58,giver=[[Geologist Larksbane]],giver_loc=[[Geóloga Trotuina]],giverType=[[NPC]],giverId=15183,ender=[[Geologist Larksbane]],ender_loc=[[Geóloga Trotuina]],enderType=[[NPC]],enderId=15183,prevId=8315,poiX=-6828,poiY=807,wowhead=[[https://www.wowhead.com/wotlk/quest=8316]],image=[[assets/images/quests/placeholder.png]],rewards={{id=20699,qty=1},{id=20710,qty=1}}}
DB[8317]={id=8317,name=[[Kitchen Assistance]],name_loc=[[Echar una mano en la cocina]],level=57,minLevel=54,giver=[[Calandrath]],giver_loc=[[Calandrath]],giverType=[[NPC]],giverId=15174,ender=[[Calandrath]],ender_loc=[[Calandrath]],enderType=[[NPC]],enderId=15174,prevId=8313,poiX=-6868,poiY=730,wowhead=[[https://www.wowhead.com/wotlk/quest=8317]],image=[[assets/images/quests/placeholder.png]],desc=[[That recipe sure will come in handy.  I'd better get to work so I can have some smoked desert dumplings ready for today.  I could use a hand in making some, I'll make it worth your while.]],logDesc=[[Calandrath at Cenarion Hold needs a batch of 10 Smoked Desert Dumplings.]]}
DB[8318]={id=8318,zoneId=1377,name=[[Secret Communication]],name_loc=[[Mensajes secretos]],level=60,minLevel=57,giver=[[Bor Wildmane]],giver_loc=[[Bor Ferocrín]],giverType=[[NPC]],giverId=15306,ender=[[Bor Wildmane]],ender_loc=[[Bor Ferocrín]],enderType=[[NPC]],enderId=15306,poiX=-6713,poiY=1521,wowhead=[[https://www.wowhead.com/wotlk/quest=8318]],image=[[assets/images/quests/placeholder.png]],desc=[[Some of the Twilight's Hammer cultists carry around little papers with gibberish written on them.  I want you to bring me a stack of them, $c. I can't figure out what the gibberish means, but that's not the point!  These papers are how their different groups communicate secretly.  The more texts we take out of circulation, the less they can communicate!]],logDesc=[[Bring 10 Encrypted Twilight Texts to Bor Wildmane in Cenarion Hold.]]}
DB[8319]={id=8319,zoneId=1377,name=[[Encrypted Twilight Texts]],name_loc=[[Textos Crepusculares codificados]],level=60,minLevel=57,giver=[[Bor Wildmane]],giver_loc=[[Bor Ferocrín]],giverType=[[NPC]],giverId=15306,ender=[[Bor Wildmane]],ender_loc=[[Bor Ferocrín]],enderType=[[NPC]],enderId=15306,prevId=8318,poiX=-6713,poiY=1521,wowhead=[[https://www.wowhead.com/wotlk/quest=8319]],image=[[assets/images/quests/placeholder.png]]}
DB[8320]={id=8320,zoneId=1377,name=[[Twilight Geolords]],name_loc=[[Geoseñores Crepusculares]],level=60,minLevel=60,giver=[[Huum Wildmane]],giver_loc=[[Huum Ferocrín]],giverType=[[NPC]],giverId=15270,ender=[[Huum Wildmane]],ender_loc=[[Huum Ferocrín]],enderType=[[NPC]],enderId=15270,rewardNextId=8321,poiX=-6985,poiY=1082,wowhead=[[https://www.wowhead.com/wotlk/quest=8320]],image=[[assets/images/quests/placeholder.png]],desc=[[The Twilight's Hammer, an insane cult bent on destruction, set up camps in Silithus and perform rituals day and night.  We do not yet know their plans, but we do think they are somehow linked to the pulsing red crystals spread across the desert. Although their mystery may one day be solved, we must first deal with their immediate threat.  Go to their camps to the west and seek out Twilight geolords.  They are the heads of these serpents; that is where we must strike!]],logDesc=[[Kill 10 Twilight Geolords, then return to Huum Wildmane in Cenarion Hold.]]}
DB[8321]={id=8321,zoneId=1377,name=[[Vyral the Vile]],name_loc=[[Vyral el Vil]],level=60,minLevel=60,giver=[[Huum Wildmane]],giver_loc=[[Huum Ferocrín]],giverType=[[NPC]],giverId=15270,ender=[[Huum Wildmane]],ender_loc=[[Huum Ferocrín]],enderType=[[NPC]],enderId=15270,prevId=8320,poiX=-6320,poiY=16,wowhead=[[https://www.wowhead.com/wotlk/quest=8321]],image=[[assets/images/quests/placeholder.png]],desc=[[We have discovered another base of operations for the Twilight's Hammer.  It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus.  The local leader of the cult, Vyral the Vile, haunts that cave - it is he who you must next defeat.  When you have done this, bring me his signet ring. Fortune to you, $N.  The horrors of Twilight's Run are formidable indeed.]],logDesc=[[Bring Vyral's Signet Ring to Huum Wildmane in Cenarion Hold.]],choiceRewards={{id=20650,qty=1},{id=20649,qty=1}}}
DB[8322]={id=8322,name=[[Rotten Eggs]],name_loc=[[Huevos podridos]],level=-1,minLevel=30,giver=[[Darkcaller Yanka]],giver_loc=[[Llamasombra Yanka]],giverType=[[NPC]],giverId=15197,ender=[[Keg]],ender_loc=[[Barril]],enderType=[[GO]],enderId=180570,rewardNextId=8409,poiX=-854,poiY=-567,wowhead=[[https://www.wowhead.com/wotlk/quest=8322]],image=[[assets/images/quests/placeholder.png]],desc=[[The humans of Southshore love their ale, and as such they prize the ale served at the Southshore Inn.  With the chaos of Hallow's End now upon them, we can use it to ruin their latest batch of beverages for weeks - if not months to come! Take these rotten eggs and place them in the main brew keg inside the Southshore Inn.  Your presence alone will cause strife, so be prepared to defend yourself! Once you've given Southshore a taste they'll not soon forget, return to me here at the festival!]],logDesc=[[Place the Rotten Eggs in the main brew keg located inside the Southshore Inn.]]}
DB[8323]={id=8323,zoneId=1377,name=[[True Believers]],name_loc=[[El creyente verdadero]],level=59,minLevel=54,giver=[[Hermit Ortell]],giver_loc=[[Ermitaño Ortell]],giverType=[[NPC]],giverId=15194,ender=[[Hermit Ortell]],ender_loc=[[Ermitaño Ortell]],enderType=[[NPC]],enderId=15194,prevId=8279,poiX=-6713,poiY=1521,wowhead=[[https://www.wowhead.com/wotlk/quest=8323]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that I have the Twilight Lexicon in my possession, there is a small favor I'd like to ask of you. My former organization has a secret encoded bulletin they circulate on a monthly basis. If they make any progress searching for me or if they call off the search, word will be published on the True Believer. Although this information is obviously valuable to me, the publication contains other useful information that I can share.  Bring me any encoded texts you find on Twilight's Hammer members.]],logDesc=[[Hermit Ortell wants you to bring him 10 Encrypted Twilight Texts]]}
DB[8324]={id=8324,zoneId=1377,name=[[Still Believing]],name_loc=[[Seguir creyendo]],level=59,minLevel=54,giver=[[Hermit Ortell]],giver_loc=[[Ermitaño Ortell]],giverType=[[NPC]],giverId=15194,ender=[[Hermit Ortell]],ender_loc=[[Ermitaño Ortell]],enderType=[[NPC]],enderId=15194,prevId=8323,poiX=-6713,poiY=1521,wowhead=[[https://www.wowhead.com/wotlk/quest=8324]],image=[[assets/images/quests/placeholder.png]]}
DB[8331]={id=8331,zoneId=1377,name=[[Aurel Goldleaf]],name_loc=[[Aurel Hojaurea]],level=60,minLevel=60,giver=[[Huum Wildmane]],giver_loc=[[Huum Ferocrín]],giverType=[[NPC]],giverId=15270,ender=[[Aurel Goldleaf]],ender_loc=[[Aurel Hojaurea]],enderType=[[NPC]],enderId=15282,rewardNextId=8332,poiX=-6845,poiY=728,wowhead=[[https://www.wowhead.com/wotlk/quest=8331]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, although we had hoped the Twilight's Hammer's operations in Silithus were slowing... we were, regrettably, mistaken.  Through continued forays against the cult, we have learned that an even darker power, the Abyssal Council, controls the Hammer through the arcane wind stones dotted amongst the cult's camps.  Your next action, $N, will be against the Abyssal Council. Speak with the craftsman Aurel Goldleaf, in the eastern section of Cenarion Hold.  Her skill will be needed for this next gambit.]],logDesc=[[Speak with Aurel Goldleaf in Cenarion Hold.]]}
DB[8332]={id=8332,zoneId=1377,name=[[Dukes of the Council]],name_loc=[[Los Duques del Consejo]],level=60,minLevel=60,giver=[[Aurel Goldleaf]],giver_loc=[[Aurel Hojaurea]],giverType=[[NPC]],giverId=15282,ender=[[Aurel Goldleaf]],ender_loc=[[Aurel Hojaurea]],enderType=[[NPC]],enderId=15282,prevId=8331,rewardNextId=8349,poiX=-6845,poiY=728,wowhead=[[https://www.wowhead.com/wotlk/quest=8332]],image=[[assets/images/quests/placeholder.png]],desc=[[We think it is possible to use a wind stone to ambush a duke of the Abyssal Council.  To do this, however, one must commune through the wind stone, and convince the council you are a middle ranked leader of the Twilight's Hammer.   Such a gambit requires a replica of the cult's medallion of station.  I can create the medallion, but I will need a large brilliant shard, and crests worn by the Abyssal Templar. Bring these to me and I will do the rest.]],logDesc=[[Bring 1 Large Brilliant Shard and 3 Abyssal Crests to Aurel Goldleaf in Cenarion Hold.]],rewards={{id=20422,qty=1}}}
DB[8333]={id=8333,zoneId=1377,name=[[Medallion of Station]],name_loc=[[Medallón de estatus]],level=60,minLevel=60,giver=[[Aurel Goldleaf]],giver_loc=[[Aurel Hojaurea]],giverType=[[NPC]],giverId=15282,ender=[[Aurel Goldleaf]],ender_loc=[[Aurel Hojaurea]],enderType=[[NPC]],enderId=15282,prevId=8332,poiX=-6845,poiY=728,wowhead=[[https://www.wowhead.com/wotlk/quest=8333]],image=[[assets/images/quests/placeholder.png]],rewards={{id=20422,qty=1}}}
DB[8341]={id=8341,zoneId=1377,name=[[Lords of the Council]],name_loc=[[Señores del Consejo]],level=60,minLevel=60,giver=[[Aurel Goldleaf]],giver_loc=[[Aurel Hojaurea]],giverType=[[NPC]],giverId=15282,ender=[[Aurel Goldleaf]],ender_loc=[[Aurel Hojaurea]],enderType=[[NPC]],enderId=15282,prevId=8343,rewardNextId=8351,poiX=-6845,poiY=728,wowhead=[[https://www.wowhead.com/wotlk/quest=8341]],image=[[assets/images/quests/placeholder.png]],desc=[[Lords of the Abyssal Council can only be summoned through the greater wind stones, and only the top ranking members of the Twilight's Council may speak to them.  But... I have found a way to upgrade your disguise and fool the Abyssal Lords! The disguise calls for a ring of lordship, worn only by the highest members of the cult.  I will craft one for you if you can bring me large brilliant shards and abyssal signets.]],logDesc=[[Bring 5 Large Brilliant Shards and 3 Abyssal Signets to Aurel Goldleaf in Cenarion Hold.]],rewards={{id=20451,qty=1}}}
DB[8342]={id=8342,zoneId=1377,name=[[Twilight Ring of Lordship]],name_loc=[[Anillo de nobleza Crepuscular]],level=60,minLevel=60,giver=[[Aurel Goldleaf]],giver_loc=[[Aurel Hojaurea]],giverType=[[NPC]],giverId=15282,ender=[[Aurel Goldleaf]],ender_loc=[[Aurel Hojaurea]],enderType=[[NPC]],enderId=15282,prevId=8341,poiX=-6845,poiY=728,wowhead=[[https://www.wowhead.com/wotlk/quest=8342]],image=[[assets/images/quests/placeholder.png]],rewards={{id=20451,qty=1}}}
DB[8343]={id=8343,zoneId=1377,name=[[Goldleaf's Discovery]],name_loc=[[El descubrimiento de Hojaurea]],level=60,minLevel=60,giver=[[Huum Wildmane]],giver_loc=[[Huum Ferocrín]],giverType=[[NPC]],giverId=15270,ender=[[Aurel Goldleaf]],ender_loc=[[Aurel Hojaurea]],enderType=[[NPC]],enderId=15282,rewardNextId=8341,poiX=-6845,poiY=728,wowhead=[[https://www.wowhead.com/wotlk/quest=8343]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, Aurel Goldleaf thinks she's found a way to summon and defeat a ruling member of the Abyssal Council!  Such a task will be dangerous, but you have earned great respect amongst the Cenarion Circle.  We know that if anyone can do it, you can. May fortune go with you, $N.  Speak with Aurel when you are ready.]],logDesc=[[Speak with Aurel Goldleaf in Cenarion Hold.]]}
DB[8348]={id=8348,zoneId=1377,name=[[Signet of the Dukes]],name_loc=[[Sellos de los Duques]],level=60,minLevel=60,giver=[[Bor Wildmane]],giver_loc=[[Bor Ferocrín]],giverType=[[NPC]],giverId=15306,ender=[[Bor Wildmane]],ender_loc=[[Bor Ferocrín]],enderType=[[NPC]],enderId=15306,prevId=8349,poiX=-6836,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=8348]],image=[[assets/images/quests/placeholder.png]],desc=[[Huum tells me you've figured out how to summon the Abyssal Dukes!  That's quite an accomplishment. You know what else would be quite the accomplishment?  Smashing up one of those things really good.  That'll cause an impression on their underlings, if you know what I mean.  Bring back its signet as proof of the deed.]],logDesc=[[Bring the Abyssal Signet to Bor Wildmane in Cenarion Hold.]],rewards={{id=20601,qty=1}}}
DB[8349]={id=8349,zoneId=1377,name=[[Bor Wildmane]],name_loc=[[Bor Ferocrín]],level=60,minLevel=60,giver=[[Aurel Goldleaf]],giver_loc=[[Aurel Hojaurea]],giverType=[[NPC]],giverId=15282,ender=[[Bor Wildmane]],ender_loc=[[Bor Ferocrín]],enderType=[[NPC]],enderId=15306,prevId=8332,rewardNextId=8348,poiX=-6836,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=8349]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you have a medallion and can summon an Abyssal Duke, speak with Bor Wildmane.  He will set you on a task against the Abyssal Council. Good luck, $N.  And if you ever need more medallions, return to me.]],logDesc=[[Speak with Bor Wildmane in Cenarion Hold.]]}
DB[8351]={id=8351,zoneId=1377,name=[[Bor Wishes to Speak]],name_loc=[[Bor quiere hablar contigo]],level=60,minLevel=60,giver=[[Aurel Goldleaf]],giver_loc=[[Aurel Hojaurea]],giverType=[[NPC]],giverId=15282,ender=[[Bor Wildmane]],ender_loc=[[Bor Ferocrín]],enderType=[[NPC]],enderId=15306,prevId=8341,rewardNextId=8352,poiX=-6836,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=8351]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you can disguise yourself as a ruling member of the Twilight Council, I am certain Bor Wildmane will want to speak with you.  Go see him, and prepare yourself for a very difficult mission...]],logDesc=[[Speak with Bor Wildmane in Cenarion Hold.]]}
DB[8352]={id=8352,zoneId=1377,name=[[Scepter of the Council]],name_loc=[[Cetro del Consejo]],level=60,minLevel=60,giver=[[Bor Wildmane]],giver_loc=[[Bor Ferocrín]],giverType=[[NPC]],giverId=15306,ender=[[Bor Wildmane]],ender_loc=[[Bor Ferocrín]],enderType=[[NPC]],enderId=15306,prevId=8351,poiX=-6836,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=8352]],image=[[assets/images/quests/placeholder.png]],desc=[[Huum and I were just talking about you.  He tells me you're just about ready to try your hand at fighting an Abyssal Lord! I must tell you this is a very dangerous endeavor.  You'd better bring backup.  And I don't mean one or two of your friends, I'm talking about a top-notch, battle-ready fighting force.  If your friends are as good as you, you might even defeat it! If you do - and I'll want evidence, as always - I'll give you a truly great reward.]],logDesc=[[Bring an Abyssal Scepter to Bor Wildmane in Cenarion Hold.]],rewards={{id=20602,qty=1}}}
DB[8353]={id=8353,name=[[Chicken Clucking for a Mint]],name_loc=[[Una menta por cacarear como un pollo]],level=-1,minLevel=10,giver=[[Innkeeper Firebrew]],giver_loc=[[Tabernero Brebefuego]],giverType=[[NPC]],giverId=5111,ender=[[Innkeeper Firebrew]],ender_loc=[[Tabernero Brebefuego]],enderType=[[NPC]],enderId=5111,prevId=-8311,poiX=-4841,poiY=-857,wowhead=[[https://www.wowhead.com/wotlk/quest=8353]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, trick-or-treating for a sick child, are we?  I was going to say, you're a little old to be rummaging about for candies... Well, for my treat - an Ironforge Mint - you will need to... cluck like a chicken!  Yes, chickens love mints... well OK, maybe they don't LOVE them... but I won't give you a mint unless you chicken cluck for me! Well $c, are you up to the challenge or not?!  Time to earn your treat!]],logDesc=[[Do a chicken emote at Innkeeper Firebrew, and in exchange you'll receive an Ironforge Mint!]],rewards={{id=20490,qty=1}}}
DB[8354]={id=8354,name=[[Chicken Clucking for a Mint]],name_loc=[[Una menta por cacarear como un pollo]],level=-1,minLevel=10,giver=[[Innkeeper Norman]],giver_loc=[[Tabernero Norman]],giverType=[[NPC]],giverId=6741,ender=[[Innkeeper Norman]],ender_loc=[[Tabernero Norman]],enderType=[[NPC]],enderId=6741,prevId=-8312,poiX=1635,poiY=223,wowhead=[[https://www.wowhead.com/wotlk/quest=8354]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, trick-or-treating for a sick child, are we?  I was going to say, you're a little old to be rummaging about for candies... Well, for my treat - an Undercity Mint - you will need to... cluck like a chicken!  Yes, chickens love mints... well OK, maybe they don't LOVE them... but I won't give you a mint unless you chicken cluck for me! Well $c, are you up to the challenge or not?!  Time to earn your treat! ]],logDesc=[[Do a chicken emote at Innkeeper Norman, and in exchange you'll receive an Undercity Mint!]],rewards={{id=20491,qty=1}}}
DB[8355]={id=8355,name=[[Incoming Gumdrop]],name_loc=[[¡Truco o trato!]],level=-1,minLevel=10,giver=[[Talvash del Kissel]],giverType=[[NPC]],giverId=6826,ender=[[Talvash del Kissel]],enderType=[[NPC]],enderId=6826,prevId=-8311,poiX=-4588,poiY=-1001,wowhead=[[https://www.wowhead.com/wotlk/quest=8355]],image=[[assets/images/quests/placeholder.png]],desc=[[A trick-or-treater!  Huzzah! Well now, even though you're doing something noble and collecting candies for a sick child, I can't let you off the hook that easily.  I have a yummy Gnomeregan Gumdrop to give to the sick child... if you make a train noise for me!  Haha, yes, that'll be the trick!  The price of this gumdrop is one train noise! Chugga-chugga, $c!]],logDesc=[[Do a train emote at Talvash del Kissel, and in exchange you'll receive a Gnomeregan Gumdrop!]],rewards={{id=20494,qty=1}}}
DB[8356]={id=8356,name=[[Flexing for Nougat]],name_loc=[[Saca músculo a cambio de almendrados]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Innkeeper Allison]],ender_loc=[[Tabernera Allison]],enderType=[[NPC]],enderId=6740,prevId=-8311,poiX=-8868,poiY=674,wowhead=[[https://www.wowhead.com/wotlk/quest=8356]],image=[[assets/images/quests/placeholder.png]],desc=[[That's an... interesting costume you have on.  Even though you're being nice and helping a sick child trick-or-treat this year, I'm afraid I'm going to have to ask you perform a trick for me! Let's see... you look so strong and buff in that... costume... let's see you flex!  Yes, go on now and flex for me, strong $g man : woman;! When and only when you flex, I'll give you some tasty Stormwind Nougat.  It's a great Hallow's End treat.]],logDesc=[[Do a flex emote at Innkeeper Allison, and in exchange you'll receive Stormwind Nougat! ]],rewards={{id=20492,qty=1}}}
DB[8357]={id=8357,name=[[Dancing for Marzipan]],name_loc=[[Bailando por mazapanes]],level=-1,minLevel=10,giver=[[Innkeeper Saelienne]],giver_loc=[[Tabernera Saelienne]],giverType=[[NPC]],giverId=6735,ender=[[Innkeeper Saelienne]],ender_loc=[[Tabernera Saelienne]],enderType=[[NPC]],enderId=6735,prevId=-8311,poiX=10128,poiY=2225,wowhead=[[https://www.wowhead.com/wotlk/quest=8357]],image=[[assets/images/quests/placeholder.png]],desc=[[Even though you're trick-or-treating for a sick child, you still need to perform a trick for the treat!  We can't very well change the tradition, now can we... I believe the cost of a piece of marzipan nowadays is to bust out and DANCE!  That's right, let me see your moves!  Dance for me, and I'll give you some tasty marzipan!]],logDesc=[[Do a dance emote at Innkeeper Saelienne, and in exchange you'll receive Darnassus Marzipan!]],rewards={{id=20496,qty=1}}}
DB[8358]={id=8358,name=[[Incoming Gumdrop]],name_loc=[[¡Truco o trato!]],level=-1,minLevel=10,giver=[[Kali Remik]],giverType=[[NPC]],giverId=11814,ender=[[Kali Remik]],enderType=[[NPC]],enderId=11814,prevId=-8312,poiX=-809,poiY=-4930,wowhead=[[https://www.wowhead.com/wotlk/quest=8358]],image=[[assets/images/quests/placeholder.png]],desc=[[A trick-or-treater!  Yeah mon! Well now, even though you're doing something noble and collecting candies for a sick child, I can't let you off the hook that easily.  I have a yummy Darkspear Gumdrop to give to the sick child... if you make a train noise for me!  Haha, yes, that'll be the trick!  The price of this gumdrop is one train noise! Chugga-chugga, $c! ]],logDesc=[[Do a train emote at Kali Remik, and in exchange you'll receive a Darkspear Gumdrop! ]],rewards={{id=20495,qty=1}}}
DB[8359]={id=8359,name=[[Flexing for Nougat]],name_loc=[[Saca músculo a cambio de almendrados]],level=-1,minLevel=10,giver=[[Innkeeper Gryshka]],giver_loc=[[Tabernera Gryshka]],giverType=[[NPC]],giverId=6929,ender=[[Innkeeper Gryshka]],ender_loc=[[Tabernera Gryshka]],enderType=[[NPC]],enderId=6929,prevId=-8312,poiX=1634,poiY=-4439,wowhead=[[https://www.wowhead.com/wotlk/quest=8359]],image=[[assets/images/quests/placeholder.png]],desc=[[That's an... interesting costume you have on.  Even though you're being nice and helping a sick child trick-or-treat this year, I'm afraid I'm going to have to ask you perform a trick for me! Let's see... you look so strong and buff in that... costume... let's see you flex!  Yes, go on now and flex for me, strong $g man : woman;! When and only when you flex, I'll give you some tasty Orgrimmar Nougat.  It's a great Hallow's End treat. ]],logDesc=[[Do a flex emote at Innkeeper Gryshka, and in exchange you'll receive Orgrimmar Nougat!]],rewards={{id=20493,qty=1}}}
DB[8360]={id=8360,name=[[Dancing for Marzipan]],name_loc=[[Bailando por mazapanes]],level=-1,minLevel=10,giver=[[Innkeeper Pala]],giver_loc=[[Tabernera Pala]],giverType=[[NPC]],giverId=6746,ender=[[Innkeeper Pala]],ender_loc=[[Tabernera Pala]],enderType=[[NPC]],enderId=6746,prevId=-8312,poiX=-1300,poiY=38,wowhead=[[https://www.wowhead.com/wotlk/quest=8360]],image=[[assets/images/quests/placeholder.png]],desc=[[Even though you're trick-or-treating for a sick child, you still need to perform a trick for the treat!  We can't very well change the tradition, now can we... I believe the cost of a piece of marzipan nowadays is to bust out and DANCE!  That's right, let me see your moves!  Dance for me, and I'll give you some tasty marzipan!]],logDesc=[[Do a dance emote at Innkeeper Pala, and in exchange you'll receive Thunder Bluff Marzipan!]],rewards={{id=20497,qty=1}}}
DB[8361]={id=8361,zoneId=1377,name=[[Abyssal Contacts]],name_loc=[[Contactos Abisales]],level=60,minLevel=60,giver=[[Bor Wildmane]],giver_loc=[[Bor Ferocrín]],giverType=[[NPC]],giverId=15306,ender=[[Bor Wildmane]],ender_loc=[[Bor Ferocrín]],enderType=[[NPC]],enderId=15306,poiX=-6836,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=8361]],image=[[assets/images/quests/placeholder.png]],desc=[[We've seen the Twilight's Hammer cultists performing rituals to summon powerful elemental nobles.  We don't know if these are the beings the cultists worship or if they act as intermediaries to even more powerful forces.  One thing is for sure: they are receiving orders from these elementals. I want you to find a way to contact an Abyssal Templar and give it a proper beating!  Nothing throws the troops in disarray like taking out the chain of command.  Bring back proof while you're at it.]],logDesc=[[Bor Wildmane at Cenarion Hold in Silithus wants you to destroy an Abyssal Templar and bring him an Abyssal Crest as proof of the deed.]],rewards={{id=20603,qty=1}}}
DB[8362]={id=8362,zoneId=1377,name=[[Abyssal Crests]],name_loc=[[Blasones Abisales]],level=60,minLevel=60,giver=[[Bor Wildmane]],giver_loc=[[Bor Ferocrín]],giverType=[[NPC]],giverId=15306,ender=[[Bor Wildmane]],ender_loc=[[Bor Ferocrín]],enderType=[[NPC]],enderId=15306,prevId=8361,poiX=-6836,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=8362]],image=[[assets/images/quests/placeholder.png]],rewards={{id=20603,qty=1}}}
DB[8363]={id=8363,zoneId=1377,name=[[Abyssal Signets]],name_loc=[[Sellos abisales]],level=60,minLevel=60,giver=[[Bor Wildmane]],giver_loc=[[Bor Ferocrín]],giverType=[[NPC]],giverId=15306,ender=[[Bor Wildmane]],ender_loc=[[Bor Ferocrín]],enderType=[[NPC]],enderId=15306,prevId=8348,poiX=-6836,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=8363]],image=[[assets/images/quests/placeholder.png]],rewards={{id=20601,qty=1}}}
DB[8364]={id=8364,zoneId=1377,name=[[Abyssal Scepters]],name_loc=[[Cetros Abisales]],level=60,minLevel=60,giver=[[Bor Wildmane]],giver_loc=[[Bor Ferocrín]],giverType=[[NPC]],giverId=15306,ender=[[Bor Wildmane]],ender_loc=[[Bor Ferocrín]],enderType=[[NPC]],enderId=15306,prevId=8352,poiX=-6836,poiY=846,wowhead=[[https://www.wowhead.com/wotlk/quest=8364]],image=[[assets/images/quests/placeholder.png]],rewards={{id=20602,qty=1}}}
DB[8365]={id=8365,zoneId=440,name=[[Pirate Hats Ahoy!]],name_loc=[[¡Sombreros de pirata a babor!]],level=45,minLevel=40,giver=[[Haughty Modiste]],giver_loc=[[Modista Jactancia]],giverType=[[NPC]],giverId=15165,ender=[[Haughty Modiste]],ender_loc=[[Modista Jactancia]],enderType=[[NPC]],enderId=15165,poiX=-7981,poiY=-5491,wowhead=[[https://www.wowhead.com/wotlk/quest=8365]],image=[[assets/images/quests/placeholder.png]],desc=[[You're the help the Cartel sent? I suppose you'll do. Listen carefully $c. As you know, I am a procurer of fashionable apparel for the elite of Azerothian society.  Kings and Queens, Warchiefs and, well whatever the Horde calls their queens, all wear what I choose is in style.  And they pay through the nose for it, which is the best part. So here's what's going to happen. You head down to Lost Rigger Cove and acquire a lot of pirate hats by whatever means. Do you think you can handle that?]],logDesc=[[Haughty Modiste wants you to collect 20 Southsea Pirate Hats and return them to her at Steamwheedle Port in Tanaris.]]}
DB[8366]={id=8366,zoneId=440,name=[[Southsea Shakedown]],name_loc=[[Mamporros en los Mares del Sur]],level=45,minLevel=40,giver=[[Security Chief Bilgewhizzle]],giver_loc=[[Jefe de seguridad Pasaquillas]],giverType=[[NPC]],giverId=7882,ender=[[Security Chief Bilgewhizzle]],ender_loc=[[Jefe de seguridad Pasaquillas]],enderType=[[NPC]],enderId=7882,poiX=-8016,poiY=-5350,wowhead=[[https://www.wowhead.com/wotlk/quest=8366]],image=[[assets/images/quests/placeholder.png]],desc=[[Argh! They want the impossible from me! The Steamwheedle Cartel wants me to teach the Southsea pirates a lesson.  The problem is that I can't be in two places at once; I need to stay here to keep the peace. Of late, the pirates have been disregarding the protection money that the cartel regularly forks over. So I'd like to temporarily deputize you to go down there and show them what for. You'll find them at Lost Rigger Cove, which is not too far to the south.  Thanks $N, I'll owe you one!]],logDesc=[[Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to kill 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers and 10 Southsea Swashbucklers.]],choiceRewards={{id=20640,qty=1},{id=20641,qty=1}}}
DB[8367]={id=8367,name=[[For Great Honor]],level=-1,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=8367]],image=[[assets/images/quests/placeholder.png]],desc=[[Serving the Horde in one of the great battles against the Alliance is a source of great honor!  The few however, that have served the Horde in ALL of our active battlefronts are our truly great fighters.  We shall vanquish our opponents, not by fighting isolated skirmishes, but by waging a well-coordinated war. Go forth and crush the Alliance on every front!  For Honor!  For the Horde!]],logDesc=[[Bring a Mark of Honor from each battleground to a Horde Warbringer in any Horde capital city or Shattrath.]]}
DB[8368]={id=8368,zoneId=3277,name=[[Battle of Warsong Gulch]],name_loc=[[La batalla por Garganta Grito de Guerra]],level=19,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=8368,poiX=1316,poiY=357,wowhead=[[https://www.wowhead.com/wotlk/quest=8368]],image=[[assets/images/quests/placeholder.png]],desc=[[The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber. Do not let this happen, $N!  Come back to me with proof of serving the Horde in a worthy manner!]],logDesc=[[Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.]]}
DB[8369]={id=8369,zoneId=2597,name=[[Invaders of Alterac Valley]],name_loc=[[Invasores del Valle de Alterac]],level=60,minLevel=51,giverType=[[NPC]],enderType=[[NPC]],poiX=1316,poiY=357,wowhead=[[https://www.wowhead.com/wotlk/quest=8369]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen up, $N.  No matter what you might have heard about the battle raging in Alterac Valley, one thing remains true: the Stormpike Expedition invaded Frostwolf Territory.  The day we allow the Alliance to invade Horde lands without a forceful response is the day I hang up my axe and live the rest of my life in shame.  Go forth and expel the invaders!]],logDesc=[[Bring 3 Alterac Valley Marks of Honor to a Horde Warbringer outside the battlegrounds.]]}
DB[8370]={id=8370,zoneId=3358,name=[[Conquering Arathi Basin]],name_loc=[[La conquista de la Cuenca de Arathi]],level=29,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=8370,poiX=1316,poiY=357,wowhead=[[https://www.wowhead.com/wotlk/quest=8370]],image=[[assets/images/quests/placeholder.png]],desc=[[Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point. The battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, $N!]],logDesc=[[Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.]]}
DB[8371]={id=8371,name=[[Concerted Efforts]],level=-1,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=8371]],image=[[assets/images/quests/placeholder.png]],desc=[[We're not fighting isolated battles against the Horde anymore, $g lad:lass;. Victory in one front means denying the Horde resources they'd use against us in a different battle.  By the same token, abandoning any given battle could give the advantage to our opponent somewhere else around the world. The Alliance is in need of more combatants with this sort of worldly understanding... truly seasoned veterans!  $N, come back to me after you've served against the Horde at all of our active battlegrounds.]],logDesc=[[Bring a Mark of Honor from each battleground to an Alliance Brigadier General in any Alliance Capital City, Dalaran or Shattrath.]]}
DB[8372]={id=8372,zoneId=3277,name=[[Fight for Warsong Gulch]],name_loc=[[Lucha por Garganta Grito de Guerra]],level=19,minLevel=10,giverType=[[NPC]],enderType=[[NPC]],exGroup=8372,poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=8372]],image=[[assets/images/quests/placeholder.png]],desc=[[The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature. The forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens. Do your part in fighting the Warsong Outriders, $N!  For the Alliance!]],logDesc=[[Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.]]}
DB[8373]={id=8373,name=[[The Power of Pine]],name_loc=[[El poder del pino]],level=-1,minLevel=25,giver=[[Sergeant Hartman]],giver_loc=[[Sargento Hartman]],giverType=[[NPC]],giverId=15199,ender=[[Sergeant Hartman]],ender_loc=[[Sargento Hartman]],enderType=[[NPC]],enderId=15199,poiX=-823,poiY=-533,wowhead=[[https://www.wowhead.com/wotlk/quest=8373]],image=[[assets/images/quests/placeholder.png]],desc=[[The thing I hate the most about Hallow's End are the stink bombs the Forsaken use on Southshore.  Who knew that celebrating liberation would have to involve such a smelly mess? During Hallow's End, use this cleaner to remove any nasty stink bombs the Horde may drop here in the village.  It uses the power of pine to fight funky smells. Do your part to keep Southshore clean, and I'll give you some Hallow's End treats I'm sure you'll enjoy.  We have a deal?]],logDesc=[[Use a Stink Bomb Cleaner to remove any Forsaken Stink Bomb that's been dropped on Southshore.  Return to Sergeant Hartman in Southshore when you're done.]],rewards={{id=20557,qty=15}}}
DB[8374]={id=8374,zoneId=3358,name=[[Claiming Arathi Basin]],name_loc=[[Reclamo por la Cuenca de Arathi]],level=29,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=8374,poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=8374]],image=[[assets/images/quests/placeholder.png]],desc=[[Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy. What we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first. If the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, $N.]],logDesc=[[Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.]]}
DB[8375]={id=8375,zoneId=2839,name=[[Remember Alterac Valley!]],name_loc=[[¡Recuerda el Valle de Alterac!]],level=60,minLevel=51,giverType=[[NPC]],enderType=[[NPC]],poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=8375]],image=[[assets/images/quests/placeholder.png]],desc=[[Make no mistake about it, $N.  The Horde is quite right when they say Alterac Valley is Frostwolf Territory. You see, the Stormpike Expedition arrived as peaceful visitors to the area in search of ore and relics.  The Frostwolves reacted with the most brutal and uncivilized act of aggression the Alliance has experienced. Let us never forget the brave dwarves that perished in that cowardly unannounced attack.  Go now, $c, do your part in the battle for Alterac Valley.  For the Alliance!]],logDesc=[[Bring 3 Alterac Valley Marks of Honor to an Alliance Brigadier General outside the battlegrounds.]]}
DB[8376]={id=8376,zoneId=1377,name=[[Armaments of War]],name_loc=[[Armamentos de guerra]],level=60,minLevel=58,giver=[[Geologist Larksbane]],giver_loc=[[Geóloga Trotuina]],giverType=[[NPC]],giverId=15183,ender=[[Geologist Larksbane]],ender_loc=[[Geóloga Trotuina]],enderType=[[NPC]],enderId=15183,prevId=8315,poiX=-6828,poiY=807,wowhead=[[https://www.wowhead.com/wotlk/quest=8376]],image=[[assets/images/quests/placeholder.png]],rewards={{id=20700,qty=1},{id=20711,qty=1}}}
