DB[8396]={id=8396,zoneId=3358,name=[[Claiming Arathi Basin]],name_loc=[[Reclamo por la Cuenca de Arathi]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],exGroup=8374,poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=8396]],image=[[assets/images/quests/placeholder.png]],desc=[[Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy. What we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first. If the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, $N.]],logDesc=[[Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.]]}
