DB[8399]={id=8399,zoneId=3277,name=[[Fight for Warsong Gulch]],name_loc=[[Lucha por Garganta Grito de Guerra]],level=29,minLevel=20,giverType=[[NPC]],enderType=[[NPC]],exGroup=8372,poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=8399]],image=[[assets/images/quests/placeholder.png]],desc=[[The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature. The forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens. Do your part in fighting the Warsong Outriders, $N!  For the Alliance!]],logDesc=[[Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.]]}
DB[8400]={id=8400,zoneId=3277,name=[[Fight for Warsong Gulch]],name_loc=[[Lucha por Garganta Grito de Guerra]],level=39,minLevel=30,giverType=[[NPC]],enderType=[[NPC]],exGroup=8372,poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=8400]],image=[[assets/images/quests/placeholder.png]],desc=[[The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature. The forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens. Do your part in fighting the Warsong Outriders, $N!  For the Alliance!]],logDesc=[[Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.]]}
DB[8401]={id=8401,zoneId=3277,name=[[Fight for Warsong Gulch]],name_loc=[[Lucha por Garganta Grito de Guerra]],level=49,minLevel=40,giverType=[[NPC]],enderType=[[NPC]],exGroup=8372,poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=8401]],image=[[assets/images/quests/placeholder.png]],desc=[[The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than the preservationist philosophy the Silverwings espouse. The forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.  Do your part in fighting the Warsong Outriders!  For the Alliance!]],logDesc=[[Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.]]}
