DB[8409]={id=8409,name=[[Ruined Kegs]],name_loc=[[Los barriles dañados]],level=-1,minLevel=30,giver=[[Keg]],giver_loc=[[Barril]],giverType=[[GO]],giverId=180570,ender=[[Darkcaller Yanka]],ender_loc=[[Llamasombra Yanka]],enderType=[[NPC]],enderId=15197,prevId=8322,poiX=1732,poiY=522,wowhead=[[https://www.wowhead.com/wotlk/quest=8409]],image=[[assets/images/quests/placeholder.png]],desc=[[The rotten eggs have been successfully placed inside the keg.  Future batches of ale from the Southshore Inn are sure to be ruined! You should now report back to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade and report your success.]],logDesc=[[Return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.]],rewards={{id=20557,qty=15}}}
DB[8410]={id=8410,name=[[Elemental Mastery]],name_loc=[[Maestría elemental]],level=52,minLevel=50,giver=[[Haromm]],giver_loc=[[Haromm]],giverType=[[NPC]],giverId=986,ender=[[Bath'rah the Windwatcher]],ender_loc=[[Bath'rah el Vigía del viento]],enderType=[[NPC]],enderId=6176,rewardNextId=8412,poiX=251,poiY=-1471,wowhead=[[https://www.wowhead.com/wotlk/quest=8410]],image=[[assets/images/quests/placeholder.png]],desc=[[Bath'rah the Windwatcher has sent out a summons for a shaman of your wisdom.  He requests you bring a sample of each of the elements to show you are ready. To find Bath'rah, go to the river east of Tarren Mill.  Follow the river north until you come across the ruins where Bath'rah resides.]],logDesc=[[Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher.]]}
