DB[8410]={id=8410,name=[[Elemental Mastery]],name_loc=[[Maestría elemental]],level=52,minLevel=50,giver=[[Farseer Javad]],giver_loc=[[Haromm]],giverType=[[NPC]],giverId=23127,ender=[[Bath'rah the Windwatcher]],ender_loc=[[Bath'rah el Vigía del viento]],enderType=[[NPC]],enderId=6176,rewardNextId=8412,poiX=251,poiY=-1471,wowhead=[[https://www.wowhead.com/wotlk/quest=8410]],image=[[assets/images/quests/placeholder.png]],desc=[[Bath'rah the Windwatcher has sent out a summons for a shaman of your wisdom.  He requests you bring a sample of each of the elements to show you are ready. To find Bath'rah, go to the river east of Tarren Mill.  Follow the river north until you come across the ruins where Bath'rah resides.]],logDesc=[[Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher.]]}
DB[8411]={id=8411,name=[[Mastering the Elements]],name_loc=[[Dominar los elementos]],level=52,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=8412,poiX=251,poiY=-1471,wowhead=[[https://www.wowhead.com/wotlk/quest=8411]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome, $c.  You bring me the elements and then we do the talkin'. The fire, the air, the water, and the earth I be needin' before I trust ya, mon.  I gots to know you be knowledgeable.]],logDesc=[[Bring the elements earth, air, fire and water to Bath'rah the Windwatcher.]]}
DB[8412]={id=8412,name=[[Spirit Totem]],name_loc=[[Tótem de espíritu]],level=52,minLevel=50,giver=[[Bath'rah the Windwatcher]],giver_loc=[[Bath'rah el Vigía del viento]],giverType=[[NPC]],giverId=6176,ender=[[Bath'rah the Windwatcher]],ender_loc=[[Bath'rah el Vigía del viento]],enderType=[[NPC]],enderId=6176,prevId=8410,poiX=251,poiY=-1471,wowhead=[[https://www.wowhead.com/wotlk/quest=8412]],image=[[assets/images/quests/placeholder.png]],desc=[[The elemental spirits of this place don't be likin' me any more. You know about the totems more than any, and I be needin' a spirit totem to protect me.  We already got the elements, now we need somethin' more with more nature.  More primal. In the Western Plaguelands you can kill bears for claws and spiders for their eyes.  The carrion birds eat everything, so they might have either one.]],logDesc=[[Bring the pieces for the spirit totem to Bath'rah the Windwatcher.]]}
DB[8413]={id=8413,name=[[Da Voodoo]],name_loc=[[Vudú]],level=52,minLevel=50,giver=[[Bath'rah the Windwatcher]],giver_loc=[[Bath'rah el Vigía del viento]],giverType=[[NPC]],giverId=6176,ender=[[Bath'rah the Windwatcher]],ender_loc=[[Bath'rah el Vigía del viento]],enderType=[[NPC]],enderId=6176,prevId=8412,poiX=251,poiY=-1471,wowhead=[[https://www.wowhead.com/wotlk/quest=8413]],image=[[assets/images/quests/placeholder.png]],desc=[[The spirit totem just isn't enough.  We be needin' some voodoo magic to make it work jus' right. The trolls in the sunken temple have feathers strong with voodoo magics.  Go there and kill Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Then we have magic enough for a real spirit totem.]],logDesc=[[Bring the voodoo feathers to Bath'rah the Windwatcher.]],choiceRewards={{id=20369,qty=1},{id=20503,qty=1},{id=20556,qty=1}}}
DB[8414]={id=8414,name=[[Dispelling Evil]],name_loc=[[Expulsión de los demonios]],level=52,minLevel=50,giver=[[Commander Ashlam Valorfist]],giver_loc=[[Comandante Ashlam Puñovalor]],giverType=[[NPC]],giverId=10838,ender=[[High Priest Thel'danis]],ender_loc=[[Sumo sacerdote Thel'danis]],enderType=[[NPC]],enderId=1854,poiX=992,poiY=-1819,wowhead=[[https://www.wowhead.com/wotlk/quest=8414]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, $c.  Crusaders like you are a welcome sight in these desolate reaches. Your holy strength is needed to help fight the endless undead here.  We need you to collect a large number of scourgestones and bring them to High Priest Thel'danis.  The high priest can be found guarding Uther's Tomb in Sorrow Hill, not far from here. Only one with an Argent Dawn Commission can hope to find scourgestones, so speak to Officer Pureheart if you haven't already.]],logDesc=[[Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands.]]}
DB[8415]={id=8415,name=[[Chillwind Camp]],name_loc=[[Campamento del Orvallo]],level=52,minLevel=50,giver=[[Lord Grayson Shadowbreaker]],giver_loc=[[Lord Grayson Quiebrasombras]],giverType=[[NPC]],giverId=928,ender=[[Commander Ashlam Valorfist]],ender_loc=[[Comandante Ashlam Puñovalor]],enderType=[[NPC]],enderId=10838,rewardNextId=8414,poiX=958,poiY=-1419,wowhead=[[https://www.wowhead.com/wotlk/quest=8415]],image=[[assets/images/quests/placeholder.png]],desc=[[Commander Ashlam Valorfist has sent out a call for a paladin of your purity and valor, $n.  You can find him at Chillwind Camp in the southern part of the Western Plaguelands.  Seek him and aid in his cause for the Light!]],logDesc=[[Speak to Commander Ashlam Valorfist at Chillwind Camp.]]}
DB[8416]={id=8416,name=[[Inert Scourgestones]],name_loc=[[Piedras de la Plaga inertes]],level=52,minLevel=50,giver=[[High Priest Thel'danis]],giver_loc=[[Sumo sacerdote Thel'danis]],giverType=[[NPC]],giverId=1854,ender=[[Commander Ashlam Valorfist]],ender_loc=[[Comandante Ashlam Puñovalor]],enderType=[[NPC]],enderId=10838,prevId=8414,rewardNextId=8418,poiX=958,poiY=-1419,wowhead=[[https://www.wowhead.com/wotlk/quest=8416]],image=[[assets/images/quests/placeholder.png]],desc=[[The evil has been purged from the stones, $n. I am aware of Commander Ashlam's plans, and he will require only a single inert stone.  Bring it to him so we may bathe the Scourge in righteous fire.]],logDesc=[[Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point.]]}
DB[8417]={id=8417,name=[[A Troubled Spirit]],name_loc=[[Un espíritu afligido]],level=52,minLevel=50,giver=[[Torm Ragetotem]],giver_loc=[[Torm Tótem de Ira]],giverType=[[NPC]],giverId=3041,ender=[[Fallen Hero of the Horde]],ender_loc=[[Héroe caído de la Horda]],enderType=[[NPC]],enderId=7572,rewardNextId=8423,poiX=-10632,poiY=-3009,wowhead=[[https://www.wowhead.com/wotlk/quest=8417]],image=[[assets/images/quests/placeholder.png]],desc=[[In the Blasted Lands, there is a troubled spirit who was once a great hero of the horde.  A warrior's honor does not die with the body, and it would serve you well to speak with him.]],logDesc=[[Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands.]]}
