DB[8418]={id=8418,name=[[Forging the Mightstone]],name_loc=[[La forja de la piedra de poderío]],level=52,minLevel=50,giver=[[Commander Ashlam Valorfist]],giver_loc=[[Comandante Ashlam Puñovalor]],giverType=[[NPC]],giverId=10838,ender=[[Commander Ashlam Valorfist]],ender_loc=[[Comandante Ashlam Puñovalor]],enderType=[[NPC]],enderId=10838,prevId=8416,poiX=958,poiY=-1419,wowhead=[[https://www.wowhead.com/wotlk/quest=8418]],image=[[assets/images/quests/placeholder.png]],desc=[[Now we must combine the inert scourgestones and create a weapon to shatter the ranks of undead.  This is no trivial task, $n.  Only the trolls of the sunken temple carry the kind of rare magic able to turn the evil of something against itself. In the temple, the trolls are known as Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Do not feel remorse for their corrupt souls... they are not without evil.]],logDesc=[[Collect Amber, Blue, and Green Voodoo Feathers from the trolls of Sunken Temple.]],rewards={{id=20620,qty=1}},choiceRewards={{id=20504,qty=1},{id=20512,qty=1},{id=20505,qty=1}}}
DB[8419]={id=8419,name=[[An Imp's Request]],name_loc=[[Pedido de un diablillo]],level=52,minLevel=50,giver=[[Demisette Cloyce]],giver_loc=[[Demisette Cloyce]],giverType=[[NPC]],giverId=461,ender=[[Impsy]],ender_loc=[[Diblis]],enderType=[[NPC]],enderId=14470,nextId=8421,rewardNextId=8421,exGroup=8419,poiX=5408,poiY=-747,wowhead=[[https://www.wowhead.com/wotlk/quest=8419]],image=[[assets/images/quests/placeholder.png]],desc=[[$n, an imp in Felwood by the name of Impsy has requested your presence.  It is somewhat strange, as he has asked that you bring a piece of felcloth as a sign of good faith.  Considering the power you already wield as a warlock, I can only assume you know the satyrs of Felwood carry this felcloth. You can find Impsy just north of the Bloodvenom Falls, which I've heard is quite lovely this time of year.]],logDesc=[[Bring a piece of felcloth to Impsy in Felwood.]]}
