DB[8436]={id=8436,zoneId=3358,name=[[Conquering Arathi Basin]],name_loc=[[La conquista de la Cuenca de Arathi]],level=39,minLevel=30,giverType=[[NPC]],enderType=[[NPC]],exGroup=8370,poiX=1316,poiY=357,wowhead=[[https://www.wowhead.com/wotlk/quest=8436]],image=[[assets/images/quests/placeholder.png]],desc=[[Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point. The battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, $N!]],logDesc=[[Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.]]}
