DB[8572]={id=8572,zoneId=1377,name=[[Veteran's Battlegear]],name_loc=[[Equipamiento de Veterano]],level=60,minLevel=60,giver=[[Vargus]],giver_loc=[[Vargus]],giverType=[[NPC]],giverId=15176,ender=[[Vargus]],ender_loc=[[Vargus]],enderType=[[NPC]],enderId=15176,prevId=8800,poiX=-6861,poiY=753,wowhead=[[https://www.wowhead.com/wotlk/quest=8572]],image=[[assets/images/quests/placeholder.png]],desc=[[The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, $N. You'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.]],logDesc=[[Bring 7 Cenarion Combat Badges, 4 Cenarion Logistics Badges and 4 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus.  You must also attain Honored reputation with Cenarion Circle to be able to complete this quest. ]],choiceRewards={{id=21181,qty=1},{id=21182,qty=1},{id=21183,qty=1}}}
DB[8573]={id=8573,zoneId=1377,name=[[Champion's Battlegear]],name_loc=[[Equipamiento de Campeón]],level=60,minLevel=60,giver=[[Vargus]],giver_loc=[[Vargus]],giverType=[[NPC]],giverId=15176,ender=[[Vargus]],ender_loc=[[Vargus]],enderType=[[NPC]],enderId=15176,prevId=8800,poiX=-6861,poiY=753,wowhead=[[https://www.wowhead.com/wotlk/quest=8573]],image=[[assets/images/quests/placeholder.png]],desc=[[The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, $N. You'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.]],logDesc=[[Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 20 Cenarion Tactical Badges and 1 Mark of Cenarius to Vargus at Cenarion Hold in Silithus.  You must also attain Exalted reputation with Cenarion Circle to be able to complete this quest. ]],choiceRewards={{id=21188,qty=1},{id=21190,qty=1},{id=21180,qty=1}}}
DB[8574]={id=8574,zoneId=1377,name=[[Stalwart's Battlegear]],name_loc=[[Equipamiento de adepto]],level=60,minLevel=60,giver=[[Vargus]],giver_loc=[[Vargus]],giverType=[[NPC]],giverId=15176,ender=[[Vargus]],ender_loc=[[Vargus]],enderType=[[NPC]],enderId=15176,prevId=8800,poiX=-6861,poiY=753,wowhead=[[https://www.wowhead.com/wotlk/quest=8574]],image=[[assets/images/quests/placeholder.png]],desc=[[The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show, $N. You'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.]],logDesc=[[Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 17 Cenarion Tactical Badges and 1 Mark of Remulos to Vargus at Cenarion Hold in Silithus.  You must also attain Revered reputation with Cenarion Circle to be able to complete this quest.]],choiceRewards={{id=21184,qty=1},{id=21185,qty=1},{id=21186,qty=1},{id=21189,qty=1}}}
DB[8575]={id=8575,zoneId=16,name=[[Azuregos's Magical Ledger]],name_loc=[[El libro de contabilidad mágico de Azuregos]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Narain Soothfancy]],ender_loc=[[Narain Sabelotodo]],enderType=[[NPC]],enderId=11811,prevId=8555,rewardNextId=8576,poiX=-6730,poiY=-4720,wowhead=[[https://www.wowhead.com/wotlk/quest=8575]],image=[[assets/images/quests/placeholder.png]],desc=[[You cannot understand a single word on this ledger. You don't even know what language it is written in!]],logDesc=[[Deliver Azuregos's Magical Ledger to Narain Soothfancy in Tanaris.]]}
DB[8576]={id=8576,zoneId=440,name=[[Translating the Ledger]],name_loc=[[La traducción del libro de contabilidad]],level=60,minLevel=60,giver=[[Narain Soothfancy]],giver_loc=[[Narain Sabelotodo]],giverType=[[NPC]],giverId=11811,ender=[[Narain Soothfancy]],ender_loc=[[Narain Sabelotodo]],enderType=[[NPC]],enderId=11811,prevId=8575,poiX=-6730,poiY=-4720,wowhead=[[https://www.wowhead.com/wotlk/quest=8576]],image=[[assets/images/quests/placeholder.png]]}
DB[8577]={id=8577,zoneId=440,name=[[Stewvul, Ex-B.F.F.]],name_loc=[[Guisón, ex mejor amigo]],level=60,minLevel=60,giver=[[Narain Soothfancy]],giver_loc=[[Narain Sabelotodo]],giverType=[[NPC]],giverId=11811,ender=[[Inconspicuous Crate]],ender_loc=[[Cajón inadvertido]],enderType=[[GO]],enderId=180642,prevId=8576,rewardNextId=8578,poiX=-760,poiY=1510,wowhead=[[https://www.wowhead.com/wotlk/quest=8577]],image=[[assets/images/quests/placeholder.png]],desc=[[If I am to translate anything, I will need my scrying goggles. Unfortunately, those were stolen quite some time ago by my ex-best friend forever, Stewvul. He broke my heart in five places and then left me here to rot. With the help of my trusty crystal ball, I've isolated his whereabouts to either the Greymane Wall in Silverpine or what appears to be a portal world in the Outland that is currently being overrun by the Burning Legion. You're going to have to track him down and get my goggles back, $N!]],logDesc=[[Narain Soothfancy wants you to find his ex-best friend forever (BFF),  Stewvul, and take back the scrying goggles that Stewvul stole from him.]]}
DB[8578]={id=8578,zoneId=2717,name=[[Scrying Goggles? No Problem!]],name_loc=[[¿Unas gafas? ¡Sin problemas!]],level=60,minLevel=60,giver=[[Inconspicuous Crate]],giver_loc=[[Cajón inadvertido]],giverType=[[GO]],giverId=180642,ender=[[Narain Soothfancy]],ender_loc=[[Narain Sabelotodo]],enderType=[[NPC]],enderId=11811,prevId=8577,nextId=8728,exGroup=-8578,poiX=-6730,poiY=-4720,wowhead=[[https://www.wowhead.com/wotlk/quest=8578]],image=[[assets/images/quests/placeholder.png]],desc=[[<You hear a sigh of relief escape the crate.> You just want his scrying goggles? Great! That will be no problem... Just give me a minute to... Hey! Where the... Dagnabbit! Well, there's some bad news and some worse news. The bad news is that I lost the goggles. The worse news is that I lost them when I was nosing around in the Molten Core last month. Yep, the Molten Core... I guess that concludes our business! Bye!]],logDesc=[[Find Narain's Scrying Goggles and return them to Narain Soothfancy in Tanaris.]],rewards={{id=18253,qty=3}}}
DB[8579]={id=8579,zoneId=3428,name=[[Mortal Champions]],name_loc=[[Campeones mortales]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],prevId=8595,wowhead=[[https://www.wowhead.com/wotlk/quest=8579]],image=[[assets/images/quests/placeholder.png]]}
DB[8580]={id=8580,name=[[The Horde Needs Firebloom!]],name_loc=[[¡La Horda necesita flores de fuego!]],level=60,minLevel=1,giver=[[Batrider Pele'keiki]],giver_loc=[[Jinete de murciélagos Pele'keiki]],giverType=[[NPC]],giverId=15508,ender=[[Batrider Pele'keiki]],ender_loc=[[Jinete de murciélagos Pele'keiki]],enderType=[[NPC]],enderId=15508,poiX=1626,poiY=-4149,wowhead=[[https://www.wowhead.com/wotlk/quest=8580]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey, $c. Ya you, mon! There be a whole mess of firebloom the Horde thinkin' they need for this Ahn'Qiraj war effort. Maybe they put it in nice things that go boom? Maybe they give it to the Alliance as fuel for their steam tanks? Who knows? Not Pele'keiki! Pele'keiki know this though... he know you gonna help him out and bring back lots of the firebloom, right, mon?]],logDesc=[[Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar.]],rewards={{id=21438,qty=10},{id=21511,qty=1}}}
DB[8581]={id=8581,name=[[The Horde Needs More Firebloom!]],name_loc=[[¡La Horda necesita más flores de fuego!]],level=60,minLevel=1,giver=[[Batrider Pele'keiki]],giver_loc=[[Jinete de murciélagos Pele'keiki]],giverType=[[NPC]],giverId=15508,ender=[[Batrider Pele'keiki]],ender_loc=[[Jinete de murciélagos Pele'keiki]],enderType=[[NPC]],enderId=15508,prevId=8580,poiX=1626,poiY=-4149,wowhead=[[https://www.wowhead.com/wotlk/quest=8581]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21438,qty=5},{id=21511,qty=1}}}
DB[8582]={id=8582,name=[[The Horde Needs Purple Lotus!]],name_loc=[[¡La Horda necesita lotos cárdenos!]],level=60,minLevel=1,giver=[[Apothecary Jezel]],giver_loc=[[Boticaria Jezel]],giverType=[[NPC]],giverId=15512,ender=[[Apothecary Jezel]],ender_loc=[[Boticaria Jezel]],enderType=[[NPC]],enderId=15512,poiX=1633,poiY=-4142,wowhead=[[https://www.wowhead.com/wotlk/quest=8582]],image=[[assets/images/quests/placeholder.png]],desc=[[The purple lotus, $c, is a reagent in a great many potions, elixirs and oils, some of which will be of use to us at Ahn'Qiraj. We're going to need to create an immense number of those potions for the war effort. And I'm going to experiment to find more uses for the lotus as well. But to do all of that I'm going to need a great quantity of the flower. That's where you come in. Go out into the field and collect up as many purple lotuses as you can. Is this something that you are willing to do for us?]],logDesc=[[Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar.]],rewards={{id=21438,qty=10},{id=21512,qty=1}}}
DB[8583]={id=8583,name=[[The Horde Needs More Purple Lotus!]],name_loc=[[¡La Horda necesita más lotos cárdenos!]],level=60,minLevel=1,giver=[[Apothecary Jezel]],giver_loc=[[Boticaria Jezel]],giverType=[[NPC]],giverId=15512,ender=[[Apothecary Jezel]],ender_loc=[[Boticaria Jezel]],enderType=[[NPC]],enderId=15512,prevId=8582,poiX=1633,poiY=-4142,wowhead=[[https://www.wowhead.com/wotlk/quest=8583]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21438,qty=7},{id=21512,qty=1}}}
DB[8584]={id=8584,zoneId=440,name=[[Never Ask Me About My Business]],name_loc=[[¡Nunca me preguntes por mi negocio!]],level=60,minLevel=60,giver=[[Narain Soothfancy]],giver_loc=[[Narain Sabelotodo]],giverType=[[NPC]],giverId=11811,ender=[[Dirge Quikcleave]],ender_loc=[[Dirge Hojágil]],enderType=[[NPC]],enderId=8125,prevId=8576,rewardNextId=8585,poiX=-7168,poiY=-3850,wowhead=[[https://www.wowhead.com/wotlk/quest=8584]],image=[[assets/images/quests/placeholder.png]],desc=[[If there is one thing that you should know about me, it is this: NEVER ask me about my business! I work with things you simply cannot understand. Like for example: Do you know what a psychotronic muzzledorf is? Of course you don't! And that's why we leave the planning to me and the fetching to you. As I said earlier, if this is going to work, we're going to need a 500 pound chicken. Head to Gadgetzan and speak with Dirge Quikcleave - he'll get you started on finding a suitable specimen. ]],logDesc=[[Narain Soothfancy in Tanaris wants you to speak with Dirge Quikcleave in Gadgetzan.]]}
DB[8585]={id=8585,zoneId=440,name=[[The Isle of Dread!]],name_loc=[[La Isla del Terror]],level=60,minLevel=60,giver=[[Dirge Quikcleave]],giver_loc=[[Dirge Hojágil]],giverType=[[NPC]],giverId=8125,ender=[[Dirge Quikcleave]],ender_loc=[[Dirge Hojágil]],enderType=[[NPC]],enderId=8125,prevId=8584,rewardNextId=8586,poiX=-7168,poiY=-3850,wowhead=[[https://www.wowhead.com/wotlk/quest=8585]],image=[[assets/images/quests/placeholder.png]],desc=[[Legend has it that the chimaerok of the Isle of Dread in Feralas have the most succulent and tender vittles in existence! Now these chimaerok also have a daddy who, with proper preparation, may or may not look like a 500 pound chicken. Head to the Isle of Dread and kill Lord Lakmaeran and bring me his fresh carcass. That should satisfy the gnome. To satisfy me, you'll need to get your hands on some chimaerok tenderloin. Do this and you'll have your 500 pound chicken and a little something extra. ]],logDesc=[[Recover Lakmaeran's Carcass and 20 Chimaerok Tenderloins for Dirge Quikcleave in Tanaris.]]}
DB[8586]={id=8586,zoneId=440,name=[[Dirge's Kickin' Chimaerok Chops]],name_loc=[[Fabulosas chuletillas de quimerok de Dirge]],level=60,minLevel=60,giver=[[Dirge Quikcleave]],giver_loc=[[Dirge Hojágil]],giverType=[[NPC]],giverId=8125,ender=[[Dirge Quikcleave]],ender_loc=[[Dirge Hojágil]],enderType=[[NPC]],enderId=8125,prevId=8585,rewardNextId=8587,poiX=-7168,poiY=-3850,wowhead=[[https://www.wowhead.com/wotlk/quest=8586]],image=[[assets/images/quests/placeholder.png]],desc=[[My recipe is complete! What I need from you now is some rocket fuel and deeprock salt. I'll handle the spices and the meat you brought me will cover the rest. After you bring me what I asked for, the chicken will be ready to take back to Narain.]],logDesc=[[Dirge Quikcleave in Gadgetzan wants you to bring him 20 Goblin Rocket Fuel and 20 Deeprock Salt.]],rewards={{id=21025,qty=1},{id=21023,qty=20}}}
DB[8587]={id=8587,zoneId=440,name=[[Return to Narain]],name_loc=[[Regresa junto a Narain]],level=60,minLevel=60,giver=[[Dirge Quikcleave]],giver_loc=[[Dirge Hojágil]],giverType=[[NPC]],giverId=8125,ender=[[Narain Soothfancy]],ender_loc=[[Narain Sabelotodo]],enderType=[[NPC]],enderId=11811,prevId=8586,nextId=8728,exGroup=-8578,poiX=-6730,poiY=-4720,wowhead=[[https://www.wowhead.com/wotlk/quest=8587]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm a goblin of my word, kid. Here's your 500 pound chicken. What a gnome wants with a 500 pound chicken, I'll never know... <Dirge grumbles something unintelligible.> Probably to sleep in it... Dirty gnomes...]],logDesc=[[Deliver the 500 Pound Chicken to Narain Soothfancy in Tanaris.]]}
DB[8588]={id=8588,name=[[The Horde Needs Heavy Leather!]],name_loc=[[¡La Horda necesita cuero pesado!]],level=60,minLevel=1,giver=[[Skinner Jamani]],giver_loc=[[Desolladora Jamani]],giverType=[[NPC]],giverId=15515,ender=[[Skinner Jamani]],ender_loc=[[Desolladora Jamani]],enderType=[[NPC]],enderId=15515,poiX=1588,poiY=-4180,wowhead=[[https://www.wowhead.com/wotlk/quest=8588]],image=[[assets/images/quests/placeholder.png]],desc=[[Since we're preparing for war, it might be best if we get all of the goods we need first, don't you think, mon? One of the staples of the war materiel that we're producing is heavy leather. We'll use it for just about everything, from reinforcement to armor, and good old plain tarps too. But first we need to get our hands on more of it. That's your job, $c. Sharpen your knife and bring me back a bundle. Then we'll talk further.]],logDesc=[[Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar.]],rewards={{id=21438,qty=10},{id=21511,qty=1}}}
DB[8589]={id=8589,name=[[The Horde Needs More Heavy Leather!]],name_loc=[[¡La Horda necesita más cuero pesado!]],level=60,minLevel=1,giver=[[Skinner Jamani]],giver_loc=[[Desolladora Jamani]],giverType=[[NPC]],giverId=15515,ender=[[Skinner Jamani]],ender_loc=[[Desolladora Jamani]],enderType=[[NPC]],enderId=15515,prevId=8588,poiX=1588,poiY=-4180,wowhead=[[https://www.wowhead.com/wotlk/quest=8589]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21438,qty=5},{id=21511,qty=1}}}
DB[8590]={id=8590,name=[[The Horde Needs Thick Leather!]],name_loc=[[¡La Horda necesita cuero grueso!]],level=60,minLevel=1,giver=[[Sergeant Umala]],giver_loc=[[Sargento Umala]],giverType=[[NPC]],giverId=15522,ender=[[Sergeant Umala]],ender_loc=[[Sargento Umala]],enderType=[[NPC]],enderId=15522,poiX=1593,poiY=-4159,wowhead=[[https://www.wowhead.com/wotlk/quest=8590]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm glad that you decided to speak to me about this, $c. It looks like the Horde's preparations for the upcoming Ahn'Qiraj War are in full swing. But you and I still need to do our part. I've been asked to collect a great number of thick leather skins for use in all manner of war materiel, and I need you to help me by going out there and gathering them up. There's honor and the gratitude of the Horde in it for you should you decide to help. Will you?]],logDesc=[[Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar.]],rewards={{id=21438,qty=10},{id=21512,qty=1}}}
DB[8591]={id=8591,name=[[The Horde Needs More Thick Leather!]],name_loc=[[¡La Horda necesita más cuero grueso!]],level=60,minLevel=1,giver=[[Sergeant Umala]],giver_loc=[[Sargento Umala]],giverType=[[NPC]],giverId=15522,ender=[[Sergeant Umala]],ender_loc=[[Sargento Umala]],enderType=[[NPC]],enderId=15522,prevId=8590,poiX=1593,poiY=-4159,wowhead=[[https://www.wowhead.com/wotlk/quest=8591]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21438,qty=7},{id=21512,qty=1}}}
DB[8592]={id=8592,zoneId=3428,name=[[Tiara of the Oracle]],name_loc=[[La tiara del Oráculo]],level=60,minLevel=60,giver=[[Andorgos]],giver_loc=[[Andorgos]],giverType=[[NPC]],giverId=15502,ender=[[Andorgos]],ender_loc=[[Andorgos]],enderType=[[NPC]],enderId=15502,wowhead=[[https://www.wowhead.com/wotlk/quest=8592]],image=[[assets/images/quests/placeholder.png]],desc=[[The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos. In my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs. Bring me the components I require, $N.  I will give you a headpiece of unmatched power.]],logDesc=[[Bring Vek'nilash's Circlet, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.]],rewards={{id=21348,qty=1}}}
DB[8593]={id=8593,zoneId=3428,name=[[Trousers of the Oracle]],name_loc=[[Las calzas del Oráculo]],level=60,minLevel=60,giver=[[Kandrostrasz]],giver_loc=[[Kandrostrasz]],giverType=[[NPC]],giverId=15503,ender=[[Kandrostrasz]],ender_loc=[[Kandrostrasz]],enderType=[[NPC]],enderId=15503,wowhead=[[https://www.wowhead.com/wotlk/quest=8593]],image=[[assets/images/quests/placeholder.png]],desc=[[You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life. His skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature. Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power.]],logDesc=[[Bring Ouro's Intact Hide, 2 Idols of Life, 5 Gold Scarabs and 5 Clay Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.]],rewards={{id=21352,qty=1}}}
DB[8594]={id=8594,zoneId=3428,name=[[Mantle of the Oracle]],name_loc=[[El manto del Oráculo]],level=60,minLevel=60,giver=[[Andorgos]],giver_loc=[[Andorgos]],giverType=[[NPC]],giverId=15502,ender=[[Andorgos]],ender_loc=[[Andorgos]],enderType=[[NPC]],enderId=15502,wowhead=[[https://www.wowhead.com/wotlk/quest=8594]],image=[[assets/images/quests/placeholder.png]],desc=[[It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon. Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!]],logDesc=[[Bring the Qiraji Bindings of Command, 2 Idols of Rebirth, 5 Silver Scarabs and 5 Ivory Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.]],rewards={{id=21350,qty=1}}}
DB[8595]={id=8595,zoneId=3428,name=[[Mortal Champions]],name_loc=[[Campeones mortales]],level=60,minLevel=60,giver=[[Kandrostrasz]],giver_loc=[[Kandrostrasz]],giverType=[[NPC]],giverId=15503,ender=[[Kandrostrasz]],ender_loc=[[Kandrostrasz]],enderType=[[NPC]],enderId=15503,wowhead=[[https://www.wowhead.com/wotlk/quest=8595]],image=[[assets/images/quests/placeholder.png]]}
DB[8596]={id=8596,zoneId=3428,name=[[Footwraps of the Oracle]],name_loc=[[Los borceguíes del Oráculo]],level=60,minLevel=60,giver=[[Kandrostrasz]],giver_loc=[[Kandrostrasz]],giverType=[[NPC]],giverId=15503,ender=[[Kandrostrasz]],ender_loc=[[Kandrostrasz]],enderType=[[NPC]],enderId=15503,wowhead=[[https://www.wowhead.com/wotlk/quest=8596]],image=[[assets/images/quests/placeholder.png]],desc=[[Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you. You will find them useful in the fight against the enemy.]],logDesc=[[Bring the Qiraji Bindings of Command, 2 Idols of Death, 5 Bronze Scarabs and 5 Gold Scarabs to Kandrostrasz in Ahn'Qiraj.  This quest also requires Neutral faction with the Brood of Nozdormu.]],rewards={{id=21349,qty=1}}}
DB[8597]={id=8597,zoneId=440,name=[[Draconic for Dummies]],name_loc=[[Dracónico para torpes]],level=60,minLevel=60,giver=[[Narain Soothfancy]],giver_loc=[[Narain Sabelotodo]],giverType=[[NPC]],giverId=11811,ender=[[Freshly Dug Dirt]],ender_loc=[[Tierra removida]],enderType=[[GO]],enderId=180652,prevId=8576,rewardNextId=8598,poiX=-10412,poiY=-4920,wowhead=[[https://www.wowhead.com/wotlk/quest=8597]],image=[[assets/images/quests/placeholder.png]],desc=[[I knew that book would come in handy some day! Thankfully, I had the wit and foresight to stow it somewhere safe. Don't worry, it's in a place that nobody could ever hope to find it! I needed a gyrocopter just to get there the first time. Unfortunately I crashed it on the beach on my way back. It was through that accident that I gained these super-gnomish psychic powers! Look for my crashed gyrocopter somewhere on Land's End Beach and swim south from there! You'll know the spot when you see it!]],logDesc=[[Find Narain Soothfancy's book, buried on an island in the South Seas.]]}
DB[8598]={id=8598,zoneId=440,name=[[rAnS0m]],name_loc=[[ReScaTe]],level=60,minLevel=60,giver=[[Freshly Dug Dirt]],giver_loc=[[Tierra removida]],giverType=[[GO]],giverId=180652,ender=[[Narain Soothfancy]],ender_loc=[[Narain Sabelotodo]],enderType=[[NPC]],enderId=11811,prevId=8597,rewardNextId=8606,poiX=-6730,poiY=-4720,wowhead=[[https://www.wowhead.com/wotlk/quest=8598]],image=[[assets/images/quests/placeholder.png]],desc=[[<The text on this note is made up of various typefaces glued onto the parchment's surface.> We've got your precious book, gnome. If you ever want to see it again, you'll do exactly as we ask. <A detailed set of instructions is listed, spanning 3 pages.> Bring the money and come alone!]],logDesc=[[Return the Ransom Letter to Narain Soothfancy in Tanaris. ]]}
DB[8599]={id=8599,zoneId=440,name=[[Love Song for Narain]],name_loc=[[Una canción de amor para Narain]],level=60,minLevel=60,giver=[[Meridith the Mermaiden]],giver_loc=[[Meridith la Sirenita]],giverType=[[NPC]],giverId=15526,ender=[[Narain Soothfancy]],ender_loc=[[Narain Sabelotodo]],enderType=[[NPC]],enderId=11811,prevId=-8597,poiX=-6730,poiY=-4720,wowhead=[[https://www.wowhead.com/wotlk/quest=8599]],image=[[assets/images/quests/placeholder.png]],desc=[[It isn't often that I get visitors. As a matter of fact, the last time I had a visitor was when I rescued that dear, sweet gnome from the wreckage of the crashed flying machine. <Meridith gazes into nothingness, lost in a memory.> Do you know him? Narain? Narain Soothfancy? Oh it would mean so much to me if somebody would deliver a message to him for me. I must tell him how I feel! I know it's love! I just know it! Could you possibly deliver a message to Narain? I would be forever indebted to you!]],logDesc=[[Take Meridith's Love Letter to Narain Soothfancy in Tanaris.]]}
DB[8600]={id=8600,name=[[The Horde Needs Rugged Leather!]],name_loc=[[¡La Horda necesita pieles de cuero basto!]],level=60,minLevel=1,giver=[[Doctor Serratus]],giver_loc=[[Doctor Serratus]],giverType=[[NPC]],giverId=15525,ender=[[Doctor Serratus]],ender_loc=[[Doctor Serratus]],enderType=[[NPC]],enderId=15525,poiX=1596,poiY=-4174,wowhead=[[https://www.wowhead.com/wotlk/quest=8600]],image=[[assets/images/quests/placeholder.png]],desc=[[I find that the fit of the knife in your palm is more important than the edge on it. Even the dullest blade can be made to cut if pressure is being properly applied through it, wouldn't you agree, $c? But you and I don't have such problems as we maintain the sharpest of edges, yes?  Well, no matter, I have a task for you. In service to the Horde, and to do your part for the Ahn'Qiraj war effort, I want you to return to me with a number of rugged leather skins. This is something that you will do, no?]],logDesc=[[Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar.]],rewards={{id=21438,qty=10},{id=21513,qty=1}}}
DB[8601]={id=8601,name=[[The Horde Needs More Rugged Leather!]],name_loc=[[¡La Horda necesita más pieles de cuero basto!]],level=60,minLevel=1,giver=[[Doctor Serratus]],giver_loc=[[Doctor Serratus]],giverType=[[NPC]],giverId=15525,ender=[[Doctor Serratus]],ender_loc=[[Doctor Serratus]],enderType=[[NPC]],enderId=15525,prevId=8600,poiX=1596,poiY=-4174,wowhead=[[https://www.wowhead.com/wotlk/quest=8601]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21438,qty=10},{id=21513,qty=1}}}
DB[8602]={id=8602,zoneId=3428,name=[[Stormcaller's Pauldrons]],name_loc=[[Los espaldares de clamatormentas]],level=60,minLevel=60,giver=[[Andorgos]],giver_loc=[[Andorgos]],giverType=[[NPC]],giverId=15502,ender=[[Andorgos]],ender_loc=[[Andorgos]],enderType=[[NPC]],enderId=15502,wowhead=[[https://www.wowhead.com/wotlk/quest=8602]],image=[[assets/images/quests/placeholder.png]],desc=[[It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon. Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!]],logDesc=[[Bring the Qiraji Bindings of Dominance, 2 Idols of Life, 5 Gold Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.]],rewards={{id=21376,qty=1}}}
DB[8603]={id=8603,zoneId=3428,name=[[Vestments of the Oracle]],name_loc=[[Las vestimentas del Oráculo]],level=60,minLevel=60,giver=[[Vethsera]],giver_loc=[[Vethsera]],giverType=[[NPC]],giverId=15504,ender=[[Vethsera]],ender_loc=[[Vethsera]],enderType=[[NPC]],enderId=15504,wowhead=[[https://www.wowhead.com/wotlk/quest=8603]],image=[[assets/images/quests/placeholder.png]],desc=[[The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power. When the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end. Do this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!]],logDesc=[[Bring the the Husk of the Old God, 2 Idols of Death, 5 Stone Scarabs and 5 Crystal Scarabs to Vethsera inside Ahn'Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.]],rewards={{id=21351,qty=1}}}
DB[8604]={id=8604,name=[[The Horde Needs Wool Bandages!]],name_loc=[[¡La Horda necesita vendas de lana!]],level=60,minLevel=1,giver=[[Healer Longrunner]],giver_loc=[[Sanador Largocamino]],giverType=[[NPC]],giverId=15528,ender=[[Healer Longrunner]],ender_loc=[[Sanador Largocamino]],enderType=[[NPC]],enderId=15528,poiX=1580,poiY=-4116,wowhead=[[https://www.wowhead.com/wotlk/quest=8604]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, $c. In preparation for the war at Ahn'Qiraj, I am here coordinating the Horde's efforts at gathering wool bandages. Unfortunately, out in the field, our soldiers cannot afford to rely upon the presence of a healer to keep them alive. Trust me, I know first hand. Thus, we're putting together all of these first aid kits for them. If you have the time, I need many wool bandages. Return them to me here and I will see to it that you are properly rewarded.]],logDesc=[[Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar.]],rewards={{id=21438,qty=10},{id=21510,qty=1}}}
DB[8605]={id=8605,name=[[The Horde Needs More Wool Bandages!]],name_loc=[[¡La Horda necesita más vendas de lana!]],level=60,minLevel=1,giver=[[Healer Longrunner]],giver_loc=[[Sanador Largocamino]],giverType=[[NPC]],giverId=15528,ender=[[Healer Longrunner]],ender_loc=[[Sanador Largocamino]],enderType=[[NPC]],enderId=15528,prevId=8604,poiX=1580,poiY=-4116,wowhead=[[https://www.wowhead.com/wotlk/quest=8605]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21438,qty=3},{id=21510,qty=1}}}
DB[8606]={id=8606,zoneId=440,name=[[Decoy!]],name_loc=[[¡Señuelo!]],level=60,minLevel=60,giver=[[Narain Soothfancy]],giver_loc=[[Narain Sabelotodo]],giverType=[[NPC]],giverId=11811,ender=[[Narain Soothfancy]],ender_loc=[[Narain Sabelotodo]],enderType=[[NPC]],enderId=11811,prevId=8598,rewardNextId=8620,poiX=5107,poiY=-5071,wowhead=[[https://www.wowhead.com/wotlk/quest=8606]],image=[[assets/images/quests/placeholder.png]],desc=[[I've got it! Here's what we're going to do. I'm going to fill a sack up with rocks and you're going to make the drop. I know it said that I should make the delivery and I'm going to - sort of. <Narain looks you up and down.> Yes, you will do just fine. Take this turban, robe, and sack of rocks and head to the drop off point in Winterspring. I've included everything you need in this special kit. When they show up to pick up the goods, snuff them out! That will teach them to mess with Narain! ]],logDesc=[[Narain Soothfancy in Tanaris wants you to travel to Winterspring and place the Bag of Gold at the drop off point documented by the booknappers.]]}
DB[8607]={id=8607,name=[[The Horde Needs Mageweave Bandages!]],name_loc=[[¡La Horda necesita vendas de tejido mágico!]],level=60,minLevel=1,giver=[[Lady Callow]],giver_loc=[[Lady Callow]],giverType=[[NPC]],giverId=15529,ender=[[Lady Callow]],ender_loc=[[Lady Callow]],enderType=[[NPC]],enderId=15529,poiX=1571,poiY=-4119,wowhead=[[https://www.wowhead.com/wotlk/quest=8607]],image=[[assets/images/quests/placeholder.png]],desc=[[I trust that you are speaking to me because you are going to help with the collection I have been entrusted to? Good! By whatever means, and I do mean whatever, I wish for you to gather up a good number of mageweave bandages. Fresh would be nice, but not absolutely necessary. Return them to me here, $c, and I will personally see to it that you are properly rewarded.]],logDesc=[[Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.]],rewards={{id=21438,qty=10},{id=21512,qty=1}}}
DB[8608]={id=8608,name=[[The Horde Needs More Mageweave Bandages!]],name_loc=[[¡La Horda necesita más vendas de tejido mágico!]],level=60,minLevel=1,giver=[[Lady Callow]],giver_loc=[[Lady Callow]],giverType=[[NPC]],giverId=15529,ender=[[Lady Callow]],ender_loc=[[Lady Callow]],enderType=[[NPC]],enderId=15529,prevId=8607,poiX=1571,poiY=-4119,wowhead=[[https://www.wowhead.com/wotlk/quest=8608]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21438,qty=7},{id=21512,qty=1}}}
DB[8609]={id=8609,name=[[The Horde Needs Runecloth Bandages!]],name_loc=[[¡La Horda necesita vendas de paño rúnico!]],level=60,minLevel=1,giver=[[Stoneguard Clayhoof]],giver_loc=[[Pezuñarcilla Garrapetra]],giverType=[[NPC]],giverId=15532,ender=[[Stoneguard Clayhoof]],ender_loc=[[Pezuñarcilla Garrapetra]],enderType=[[NPC]],enderId=15532,poiX=1565,poiY=-4124,wowhead=[[https://www.wowhead.com/wotlk/quest=8609]],image=[[assets/images/quests/placeholder.png]],desc=[[It appears inevitable that the Horde and Alliance are on a collision course for war at Ahn'Qiraj. Surprisingly, it is not a war with each other, but rather with the silithid, and whatever force controls them. Also surprisingly, both sides are doing their part to gather the resources necessary to wage a successful war. I am collecting runecloth bandages to distribute to the soldiers, but I won't be successful without assistance, hopefully yours. Is this something that you can aid me with, $c? ]],logDesc=[[Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar.]],rewards={{id=21438,qty=10},{id=21513,qty=1}}}
DB[8610]={id=8610,name=[[The Horde Needs More Runecloth Bandages!]],name_loc=[[¡La Horda necesita más vendas de paño rúnico!]],level=60,minLevel=1,giver=[[Stoneguard Clayhoof]],giver_loc=[[Pezuñarcilla Garrapetra]],giverType=[[NPC]],giverId=15532,ender=[[Stoneguard Clayhoof]],ender_loc=[[Pezuñarcilla Garrapetra]],enderType=[[NPC]],enderId=15532,prevId=8609,poiX=1565,poiY=-4124,wowhead=[[https://www.wowhead.com/wotlk/quest=8610]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21438,qty=10},{id=21513,qty=1}}}
DB[8611]={id=8611,name=[[The Horde Needs Lean Wolf Steaks!]],name_loc=[[¡La Horda necesita filetes de lobo magro!]],level=60,minLevel=1,giver=[[Bloodguard Rawtar]],giver_loc=[[Guardasangre Alquicrudo]],giverType=[[NPC]],giverId=15533,ender=[[Bloodguard Rawtar]],ender_loc=[[Guardasangre Alquicrudo]],enderType=[[NPC]],enderId=15533,poiX=1643,poiY=-4085,wowhead=[[https://www.wowhead.com/wotlk/quest=8611]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm not standing here just to get a nice tan, $c. There are war preparations to be made. If we're going to crush those bugs at Ahn'Qiraj then we need to be ready, and that includes food too! They have me gathering and salting lean wolf steaks here for the upcoming war. But since I need to stay here to take care of all of this, I need you to go out, kill some wolves and then cook up the meat into lean wolf steaks and bring them back to me here. You got all that?]],logDesc=[[Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar.]],rewards={{id=21438,qty=10},{id=21510,qty=1}}}
DB[8612]={id=8612,name=[[The Horde Needs More Lean Wolf Steaks!]],name_loc=[[¡La Horda necesita más filetes de lobo magro!]],level=60,minLevel=1,giver=[[Bloodguard Rawtar]],giver_loc=[[Guardasangre Alquicrudo]],giverType=[[NPC]],giverId=15533,ender=[[Bloodguard Rawtar]],ender_loc=[[Guardasangre Alquicrudo]],enderType=[[NPC]],enderId=15533,prevId=8611,poiX=1643,poiY=-4085,wowhead=[[https://www.wowhead.com/wotlk/quest=8612]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21438,qty=1},{id=21510,qty=1}}}
DB[8613]={id=8613,name=[[The Horde Needs Spotted Yellowtail!]],name_loc=[[¡La Horda necesita serviolas moteadas!]],level=60,minLevel=1,giver=[[Fisherman Lin'do]],giver_loc=[[Pescador Len'do]],giverType=[[NPC]],giverId=15534,ender=[[Fisherman Lin'do]],ender_loc=[[Pescador Len'do]],enderType=[[NPC]],enderId=15534,poiX=1630,poiY=-4089,wowhead=[[https://www.wowhead.com/wotlk/quest=8613]],image=[[assets/images/quests/placeholder.png]],desc=[[It be a nice day for fishin', don't'cha think mon? Good thing, cuz I be needin' a lot of fish it lookin' like. The Horde, they askin' me to be in charge of collectin' a ton of the spotted yellowtail for them. They say they needin' it for the war they getting' ready for at Ahn'Qiraj. I say to them I do the best I can. So I be needin' to get some help. You gonna be helpin' me, $c?]],logDesc=[[Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar.]],rewards={{id=21438,qty=10},{id=21512,qty=1}}}
DB[8614]={id=8614,name=[[The Horde Needs More Spotted Yellowtail!]],name_loc=[[¡La Horda necesita más serviolas moteadas!]],level=60,minLevel=1,giver=[[Fisherman Lin'do]],giver_loc=[[Pescador Len'do]],giverType=[[NPC]],giverId=15534,ender=[[Fisherman Lin'do]],ender_loc=[[Pescador Len'do]],enderType=[[NPC]],enderId=15534,prevId=8613,poiX=1630,poiY=-4089,wowhead=[[https://www.wowhead.com/wotlk/quest=8614]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21438,qty=7},{id=21512,qty=1}}}
DB[8615]={id=8615,name=[[The Horde Needs Baked Salmon!]],name_loc=[[¡La Horda necesita salmón asado!]],level=60,minLevel=1,giver=[[Chief Sharpclaw]],giver_loc=[[Jefe Garrafilo]],giverType=[[NPC]],giverId=15535,ender=[[Chief Sharpclaw]],ender_loc=[[Jefe Garrafilo]],enderType=[[NPC]],enderId=15535,poiX=1634,poiY=-4085,wowhead=[[https://www.wowhead.com/wotlk/quest=8615]],image=[[assets/images/quests/placeholder.png]],desc=[[The Ahn'Qiraj war effort is an immense undertaking, $c. All of the materials being gathered here, whether it is metal for weapons, or food to eat, are all as important as the other. For, if you haven't eaten in days you will not have the strength to lift your axe when it matters. Thus, we gather what food we can. I am collecting baked salmon, a dish that was chosen both for its sustenance and its ability to keep well. Can you aid me with this task, $c?]],logDesc=[[Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar.]],rewards={{id=21438,qty=10},{id=21513,qty=1}}}
DB[8616]={id=8616,name=[[The Horde Needs More Baked Salmon!]],name_loc=[[¡La Horda necesita más salmón asado!]],level=60,minLevel=1,giver=[[Chief Sharpclaw]],giver_loc=[[Jefe Garrafilo]],giverType=[[NPC]],giverId=15535,ender=[[Chief Sharpclaw]],ender_loc=[[Jefe Garrafilo]],enderType=[[NPC]],enderId=15535,prevId=8615,poiX=1634,poiY=-4085,wowhead=[[https://www.wowhead.com/wotlk/quest=8616]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21438,qty=10},{id=21513,qty=1}}}
DB[8617]={id=8617,name=[[The Horde Needs Singed Corestones!]],name_loc=[[¡La Horda necesita piedras nuclearias chamuscadas!]],level=60,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-4981,poiY=-1218,wowhead=[[https://www.wowhead.com/wotlk/quest=8617]],image=[[assets/images/quests/placeholder.png]],desc=[[The time has come for you to contribute to the Ahn'Qiraj war effort, $c. Gone are the halcyon days of whiling away your time in leisure. Now it is time to serve me and the Horde, and I assure you that I am not as forgiving as the Warchief. You will gather your forces, a guild if you have one, and invade the Molten Core. Inside you will find that the denizens of the place have singed corestones. Bring these back to me in large quantities.]],logDesc=[[Bring 50 singed corestones to General Zog in Durotar.]]}
DB[8619]={id=8619,name=[[Morndeep the Elder]],name_loc=[[Alborhondo el Ancestro]],level=-1,minLevel=1,giver=[[Elder Morndeep]],giver_loc=[[Ancestro Alborhondo]],giverType=[[NPC]],giverId=15549,ender=[[Elder Morndeep]],ender_loc=[[Ancestro Alborhondo]],enderType=[[NPC]],enderId=15549,poiX=597,poiY=-189,wowhead=[[https://www.wowhead.com/wotlk/quest=8619]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21100,qty=1}}}
DB[8620]={id=8620,zoneId=440,name=[[The Only Prescription]],name_loc=[[La única receta]],level=60,minLevel=60,giver=[[Narain Soothfancy]],giver_loc=[[Narain Sabelotodo]],giverType=[[NPC]],giverId=11811,ender=[[Narain Soothfancy]],ender_loc=[[Narain Sabelotodo]],enderType=[[NPC]],enderId=11811,prevId=8606,nextId=8728,exGroup=-8578,poiX=-6730,poiY=-4720,wowhead=[[https://www.wowhead.com/wotlk/quest=8620]],image=[[assets/images/quests/placeholder.png]],desc=[[I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book! How are you going to save the world now, hero? The note I received stated that the only known copy of "Draconic for Dummies: Volume II" was ripped into 8 parts and scattered to the wind! If you somehow manage to find those missing chapters, use this magical binding to put them back together and return to me.]],logDesc=[[Recover the 8 lost chapters of Draconic for Dummies and combine them with the Magical Book Binding and return the completed book of Draconic for Dummies: Volume II to Narain Soothfancy in Tanaris.]],rewards={{id=21517,qty=1}}}
DB[8621]={id=8621,zoneId=3428,name=[[Stormcaller's Footguards]],name_loc=[[Los guardapiés de clamatormentas]],level=60,minLevel=60,giver=[[Kandrostrasz]],giver_loc=[[Kandrostrasz]],giverType=[[NPC]],giverId=15503,ender=[[Kandrostrasz]],ender_loc=[[Kandrostrasz]],enderType=[[NPC]],enderId=15503,wowhead=[[https://www.wowhead.com/wotlk/quest=8621]],image=[[assets/images/quests/placeholder.png]],desc=[[Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of dominance and other minor components and I'll create a set of powerful boots for you. You will find them useful in the fight against the enemy.]],logDesc=[[Bring the Qiraji Bindings of Dominance, 2 Idols of the Sage, 5 Bronze Scarabs and 5 Clay Scarabs to Kandrostrasz in Ahn'Qiraj.  This quest also requires Neutral faction with the Brood of Nozdormu.]],rewards={{id=21373,qty=1}}}
DB[8622]={id=8622,zoneId=3428,name=[[Stormcaller's Hauberk]],name_loc=[[El camisote de clamatormentas]],level=60,minLevel=60,giver=[[Vethsera]],giver_loc=[[Vethsera]],giverType=[[NPC]],giverId=15504,ender=[[Vethsera]],ender_loc=[[Vethsera]],enderType=[[NPC]],enderId=15504,wowhead=[[https://www.wowhead.com/wotlk/quest=8622]],image=[[assets/images/quests/placeholder.png]],desc=[[The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power. When the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end. Do this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!]],logDesc=[[Bring the Carapace of the Old God, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn'Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.]],rewards={{id=21374,qty=1}}}
DB[8623]={id=8623,zoneId=3428,name=[[Stormcaller's Diadem]],name_loc=[[La diadema de clamatormentas]],level=60,minLevel=60,giver=[[Andorgos]],giver_loc=[[Andorgos]],giverType=[[NPC]],giverId=15502,ender=[[Andorgos]],ender_loc=[[Andorgos]],enderType=[[NPC]],enderId=15502,wowhead=[[https://www.wowhead.com/wotlk/quest=8623]],image=[[assets/images/quests/placeholder.png]],desc=[[The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos. In my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs. Bring me the components I require, $N.  I will give you a headpiece of unmatched power.]],logDesc=[[Bring Vek'lor's Diadem, 2 Idols of Rebirth, 5 Stone Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.]],rewards={{id=21372,qty=1}}}
DB[8624]={id=8624,zoneId=3428,name=[[Stormcaller's Leggings]],name_loc=[[Los leotardos de clamatormentas]],level=60,minLevel=60,giver=[[Kandrostrasz]],giver_loc=[[Kandrostrasz]],giverType=[[NPC]],giverId=15503,ender=[[Kandrostrasz]],ender_loc=[[Kandrostrasz]],enderType=[[NPC]],enderId=15503,wowhead=[[https://www.wowhead.com/wotlk/quest=8624]],image=[[assets/images/quests/placeholder.png]],desc=[[You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life. His skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature. Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power.]],logDesc=[[Bring the Skin of the Great Sandworm, 2 Idols of Strife, 5 Bronze Scarabs and 5 Ivory Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.]],rewards={{id=21375,qty=1}}}
DB[8625]={id=8625,zoneId=3428,name=[[Enigma Shoulderpads]],name_loc=[[Las hombreras enigma]],level=60,minLevel=60,giver=[[Andorgos]],giver_loc=[[Andorgos]],giverType=[[NPC]],giverId=15502,ender=[[Andorgos]],ender_loc=[[Andorgos]],enderType=[[NPC]],enderId=15502,wowhead=[[https://www.wowhead.com/wotlk/quest=8625]],image=[[assets/images/quests/placeholder.png]],desc=[[It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon. Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!]],logDesc=[[Bring the Qiraji Bindings of Dominance, 2 Idols of Death, 5 Stone Scarabs and 5 Bronze Scarabs to Andorgos in Ahn'Qiraj.  You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.]],rewards={{id=21345,qty=1}}}
