DB[8770]={id=8770,zoneId=1377,name=[[Target: Hive'Ashi Defenders]],name_loc=[[Objetivo: los defensores Colmen'Ashi]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Commander Mar'alith]],ender_loc=[[Comandante Mar'alith]],enderType=[[NPC]],enderId=15181,poiX=-6222,poiY=987,wowhead=[[https://www.wowhead.com/wotlk/quest=8770]],image=[[assets/images/quests/placeholder.png]],desc=[[As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of Hive'Ashi defenders. Report back to Commander Mar'alith after your task is completed.]],logDesc=[[Slay 30 Hive'Ashi Defenders and report back to Commander Mar'alith at Cenarion Hold in Silithus.  You must also bring Combat Task Briefing I in order to complete this quest.]],rewards={{id=20802,qty=1}}}
