DB[8778]={id=8778,zoneId=1377,name=[[The Ironforge Brigade Needs Explosives!]],name_loc=[[¡La Brigada de Forjaz necesita explosivos!]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Arcanist Nozzlespring]],ender_loc=[[Arcanista Bocafuente]],enderType=[[NPC]],enderId=15444,poiX=-7167,poiY=1404,wowhead=[[https://www.wowhead.com/wotlk/quest=8778]],image=[[assets/images/quests/placeholder.png]],desc=[[The Ironforge Brigade has put in an unusual request for highly... volatile... components.  Gather them and bring them to Mr. Nozzlespring from the Ironforge Brigade.]],logDesc=[[Bring 6 Oils of Immolation, 5 Goblin Rocket Fuel and 10 Dense Blasting Powder to Arcanist Nozzlespring near Hive'Zora in Silithus.  You must also bring Logistics Task Briefing IV in order to complete this quest.]],rewards={{id=20800,qty=1},{id=20805,qty=1}}}
DB[8779]={id=8779,zoneId=1377,name=[[Scrying Materials]],name_loc=[[Materiales de visión]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Geologist Larksbane]],ender_loc=[[Geóloga Trotuina]],enderType=[[NPC]],enderId=15183,poiX=-6828,poiY=807,wowhead=[[https://www.wowhead.com/wotlk/quest=8779]],image=[[assets/images/quests/placeholder.png]],desc=[[Geologist Larksbane's studies have proven to be of tremendous value to our operations in Silithus.  She has recently requested scrying materials to be used in her research. Please gather these materials and deliver them to her directly so that she may continue her research.]],logDesc=[[Bring 1 Large Brilliant Shard, 1 Large Radiant Shard and 1 Huge Emerald to Geologist Larksbane at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing V in order to complete this quest.]],rewards={{id=20800,qty=1},{id=20805,qty=1}}}
DB[8780]={id=8780,zoneId=1377,name=[[Armor Kits for the Field]],name_loc=[[Refuerzos para armadura para el campo de batalla]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Janela Stouthammer]],ender_loc=[[Janela Martillotenaz]],enderType=[[NPC]],enderId=15443,poiX=-7179,poiY=1392,wowhead=[[https://www.wowhead.com/wotlk/quest=8780]],image=[[assets/images/quests/placeholder.png]],desc=[[The Ironforge Brigade's supply of armor kits in the battlefield is running dangerously low.  Obtain a batch and deliver them to Janela Stouthammer at the Ironforge Brigade's outpost outside Hive'Zora.]],logDesc=[[Bring 8 Rugged Armor Kits and 8 Heavy Armor Kits to Janela Stouthammer at the Ironforge Brigade Outpost near Hive'Zora in Silithus.  You must also bring Logistics Task Briefing VII in order to complete this quest.]],rewards={{id=20800,qty=1},{id=20805,qty=1}}}
DB[8781]={id=8781,zoneId=1377,name=[[Arms for the Field]],name_loc=[[Armas para el campo de batalla]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Janela Stouthammer]],ender_loc=[[Janela Martillotenaz]],enderType=[[NPC]],enderId=15443,poiX=-7179,poiY=1392,wowhead=[[https://www.wowhead.com/wotlk/quest=8781]],image=[[assets/images/quests/placeholder.png]],desc=[[The Ironforge Brigade has been a worthy ally in our fight in Silithus.  Unfortunately, many of their supplies were lost on their way here.  Procure a batch of weapons and deliver them to Janela Stouthammer near Hive'Zora.]],logDesc=[[Bring 2 Moonsteel Broadswords to Janela Stouthammer at the Ironforge Brigade Outpost outside of Hive'Zora.  You must also bring Logistics Task Briefing VI in order to complete this quest.]],rewards={{id=20800,qty=1},{id=20805,qty=1}}}
DB[8782]={id=8782,zoneId=1377,name=[[Uniform Supplies]],name_loc=[[Suministros para uniformes]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Windcaller Proudhorn]],ender_loc=[[Clamavientos Cuerno Digno]],enderType=[[NPC]],enderId=15191,poiX=-6848,poiY=756,wowhead=[[https://www.wowhead.com/wotlk/quest=8782]],image=[[assets/images/quests/placeholder.png]],desc=[[The latest influx of volunteers has caused a shortage of uniforms.  Procure a batch of uniform materials and bring them to Windcaller Proudhorn.]],logDesc=[[Bring 1 Mooncloth, 2 Bolts of Runecloth and 1 Ironweb Spider Silk to Windcaller Proudhorn at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing VIII in order to complete this quest.]],rewards={{id=20800,qty=1},{id=21132,qty=1}}}
DB[8783]={id=8783,zoneId=1377,name=[[Extraordinary Materials]],name_loc=[[Materiales encantados]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Vargus]],ender_loc=[[Vargus]],enderType=[[NPC]],enderId=15176,poiX=-6861,poiY=753,wowhead=[[https://www.wowhead.com/wotlk/quest=8783]],image=[[assets/images/quests/placeholder.png]],desc=[[Vargus, Cenarion Hold's blacksmith, has requested enchanted materials to be used in the crafting of powerful weapons for our forces.  Obtain these and bring them directly to Vargus so that Cenarion Hold's troops may continue to be well equipped.]],logDesc=[[Bring 2 Enchanted Thorium Bars and 2 Enchanted Leather to Vargus at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing IX in order to complete this quest.]],rewards={{id=20800,qty=1},{id=21132,qty=1}}}
DB[8784]={id=8784,zoneId=3428,name=[[Secrets of the Qiraji]],name_loc=[[Los secretos de los qiraji]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Andorgos]],ender_loc=[[Andorgos]],enderType=[[NPC]],enderId=15502,wowhead=[[https://www.wowhead.com/wotlk/quest=8784]],image=[[assets/images/quests/placeholder.png]],desc=[[You have discovered an ancient Qiraji artifact! Perhaps one of the dragons near the entrance of the temple would have a use for this relic.]],logDesc=[[Take the Ancient Qiraji Artifact to the dragons hiding near the entrance of the temple. ]]}
DB[8785]={id=8785,zoneId=1377,name=[[The Orgrimmar Legion Needs Mojo!]],name_loc=[[¡La Legión de Orgrimmar necesita mojo!]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Shadow Priestess Shai]],ender_loc=[[Sacerdotisa de las Sombras Shai]],enderType=[[NPC]],enderId=15615,poiX=-7557,poiY=749,wowhead=[[https://www.wowhead.com/wotlk/quest=8785]],image=[[assets/images/quests/placeholder.png]],desc=[[The Orgrimmar Legion has put in a request for several unusual ingredients.  Given their current performance in Silithus, we'd like to comply with their request as soon as possible.  Gather the materials and bring them to the troll called Shai.]],logDesc=[[Bring 6 Powerful Mojo, 6 Flasks of Big Mojo and 8 Oils of Immolation to Shadow Priestess Shai near Hive'Regal in Silithus.  You must also bring Logistics Task Briefing IV in order to complete this quest.]],rewards={{id=20800,qty=1},{id=21386,qty=1}}}
DB[8786]={id=8786,zoneId=1377,name=[[Arms for the Field]],name_loc=[[Armas para el campo de batalla]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Merok Longstride]],ender_loc=[[Merok Zancolargo]],enderType=[[NPC]],enderId=15613,poiX=-7537,poiY=731,wowhead=[[https://www.wowhead.com/wotlk/quest=8786]],image=[[assets/images/quests/placeholder.png]],desc=[[The Orgrimmar Legion has put in a request for additional weapons that we haven't been able to provide at the moment.  Obtain the weapons they've requested and bring them to Merok Longstride outside of Hive'Regal.]],logDesc=[[Bring 3 Massive Iron Axes to Merok Longstride at the Orgrimmar Legion camp outside of Hive'Regal.  You must also bring Logistics Task Briefing VI in order to complete this quest.]],rewards={{id=20800,qty=1},{id=21386,qty=1}}}
DB[8787]={id=8787,zoneId=1377,name=[[Armor Kits for the Field]],name_loc=[[Refuerzos para armadura para el campo de batalla]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Merok Longstride]],ender_loc=[[Merok Zancolargo]],enderType=[[NPC]],enderId=15613,poiX=-7537,poiY=731,wowhead=[[https://www.wowhead.com/wotlk/quest=8787]],image=[[assets/images/quests/placeholder.png]],desc=[[The brave volunteers of the Orgrimmar Legion have arrived to Silithus to aid us in our cause.  Their supplies of armor kits were somehow lost in the trip.  Obtain a batch of armor kits and deliver them to Merok Longstride at the location of the Orgrimmar Legion camp.]],logDesc=[[Bring 8 Rugged Armor Kits and 8 Heavy Armor Kits to Merok Longstride near Hive'Regal.  You must also bring Logistics Task Briefing VII in order to complete this quest.]],rewards={{id=20800,qty=1},{id=21386,qty=1}}}
DB[8788]={id=8788,name=[[A Gently Shaken Gift]],name_loc=[[Un obsequio ligeramente agitado]],level=-1,minLevel=1,giver=[[Gently Shaken Gift]],giver_loc=[[Obsequio ligeramente agitado]],giverType=[[GO]],giverId=180746,ender=[[Gently Shaken Gift]],ender_loc=[[Obsequio ligeramente agitado]],enderType=[[GO]],enderId=180746,poiX=-4915,poiY=-978,wowhead=[[https://www.wowhead.com/wotlk/quest=8788]],image=[[assets/images/quests/placeholder.png]],rewards={{id=21271,qty=1}}}
DB[8789]={id=8789,zoneId=3428,name=[[Imperial Qiraji Armaments]],name_loc=[[Armamentos imperiales qiraji]],level=60,minLevel=60,giver=[[Arygos]],giverType=[[NPC]],giverId=15380,ender=[[Arygos]],enderType=[[NPC]],enderId=15380,poiX=-7515,poiY=-937,wowhead=[[https://www.wowhead.com/wotlk/quest=8789]],image=[[assets/images/quests/placeholder.png]],desc=[[We have not sat idly by for a millennium, $N. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world. And we have learned of their own internal treachery. Weaknesses exist and we know how to use those weaknesses to our advantage. Find and bring me their ceremonial armaments: Combined with the element created from the volatility of their own God, they will become a force of reckoning.]],logDesc=[[Arygos in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring him Imperial Qiraji Armaments and 3 Elementium Ore.]],choiceRewards={{id=21242,qty=1},{id=21272,qty=1},{id=21244,qty=1},{id=21269,qty=1}}}
DB[8790]={id=8790,zoneId=3428,name=[[Imperial Qiraji Regalia]],name_loc=[[Atavío imperial qiraji]],level=60,minLevel=60,giver=[[Merithra of the Dream]],giver_loc=[[Merithra del Sueño]],giverType=[[NPC]],giverId=15378,ender=[[Merithra of the Dream]],ender_loc=[[Merithra del Sueño]],enderType=[[NPC]],enderId=15378,poiX=-7515,poiY=-937,wowhead=[[https://www.wowhead.com/wotlk/quest=8790]],image=[[assets/images/quests/placeholder.png]],desc=[[Arygos theorizes that the element which is born of conflicts between the Old Gods and their minions is also extremely deadly to them under the right conditions. I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power. ]],logDesc=[[Merithra of the Dream in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring her Imperial Qiraji Regalia and 3 Elementium Ore. ]],choiceRewards={{id=21273,qty=1},{id=21275,qty=1},{id=21268,qty=1}}}
DB[8791]={id=8791,zoneId=3429,name=[[The Fall of Ossirian]],name_loc=[[La caída de Osirio]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Commander Mar'alith]],ender_loc=[[Comandante Mar'alith]],enderType=[[NPC]],enderId=15181,poiX=-6752,poiY=824,wowhead=[[https://www.wowhead.com/wotlk/quest=8791]],image=[[assets/images/quests/placeholder.png]],desc=[[A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory. Take Ossirian's head and present it to Commander Mar'alith of Cenarion Hold.]],logDesc=[[Deliver the Head of Ossirian the Unscarred to Commander Mar'alith at Cenarion Hold in Silithus. ]],choiceRewards={{id=21504,qty=1},{id=21507,qty=1},{id=21505,qty=1},{id=21506,qty=1}}}
DB[8792]={id=8792,name=[[The Horde Needs Your Help!]],name_loc=[[¡La Horda te necesita!]],level=60,minLevel=1,giver=[[Senior Sergeant Taiga]],giver_loc=[[Sargento Jefe Taiga]],giverType=[[NPC]],giverId=15702,ender=[[Warlord Gorchuk]],ender_loc=[[Señor de la Guerra Gorchuk]],enderType=[[NPC]],enderId=15700,exGroup=8792,poiX=1582,poiY=-4185,wowhead=[[https://www.wowhead.com/wotlk/quest=8792]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, $N! You should go speak with the guy in charge, Warlord Gorchuk. What do you say, $c? Will you help out with the vital preparations?]],logDesc=[[Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.]]}
