DB[8827]={id=8827,name=[[Winter's Presents]],name_loc=[[Regalos del invierno]],level=-1,minLevel=1,giver=[[Wonderform Operator]],giver_loc=[[Operador Formavillosa]],giverType=[[NPC]],giverId=15732,ender=[[Greatfather Winter]],ender_loc=[[Gran Padre Invierno]],enderType=[[NPC]],enderId=13444,poiX=-4915,poiY=-976,wowhead=[[https://www.wowhead.com/wotlk/quest=8827]],image=[[assets/images/quests/placeholder.png]],desc=[[I hear Greatfather Winter - with the generous support of Smokeywood Pastures - has put presents for everyone under the tree in Ironforge. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt. But you should definitely check it out. I'm sure Greatfather Winter has some presents with your name on them.]],logDesc=[[Speak with Greatfather Winter. He is located near the Smokywood Pastures vendor area in Ironforge.]]}
DB[8828]={id=8828,name=[[Winter's Presents]],name_loc=[[Regalos del invierno]],level=-1,minLevel=1,giver=[[Wonderform Operator]],giver_loc=[[Operador Formavillosa]],giverType=[[NPC]],giverId=15732,ender=[[Great-father Winter]],ender_loc=[[Gran Padre Invierno]],enderType=[[NPC]],enderId=13445,poiX=1627,poiY=-4417,wowhead=[[https://www.wowhead.com/wotlk/quest=8828]],image=[[assets/images/quests/placeholder.png]],desc=[[I hear Great-father Winter - with the generous support of Smokeywood Pastures - has put presents for everyone under the tree in Orgrimmar. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt. But you should definitely check it out. I'm sure Great-father Winter has some presents with your name on them.]],logDesc=[[Speak with Great-father Winter. He is located near the Smokywood Pastures vendor area in Orgrimmar.]]}
DB[8829]={id=8829,zoneId=1377,name=[[The Ultimate Deception]],name_loc=[[El último engaño]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Aurel Goldleaf]],ender_loc=[[Aurel Hojaurea]],enderType=[[NPC]],enderId=15282,poiX=-6845,poiY=728,wowhead=[[https://www.wowhead.com/wotlk/quest=8829]],image=[[assets/images/quests/placeholder.png]],desc=[[The Twilight's Hammer operates through innumerable layers of secrecy and deceit.  While their actions are carried out in our world, they are planned in a place we have not yet been able to reach. We've come to believe that the stones the Twilight's Hammer uses to summon their superiors allow for two-way transportation.  To attempt to use them in this manner, we must replicate - to every last detail - a twilight emissary's robe. Gather the necessary materials and bring them to Aurel Goldleaf, $N.]],logDesc=[[Bring a Skin of Shadow, 3 Frayed Abomination Stitchings and 1 Twilight Cultist Robe to Aurel Goldleaf at Cenarion Hold in Silithus.  You must also bring Logistics Task Briefing XI in order to complete this quest. ]],rewards={{id=21515,qty=1}}}
