DB[8857]={id=8857,zoneId=1377,name=[[Secrets of the Colossus - Ashi]],name_loc=[[Los secretos de los Colosos: Ashi]],level=60,minLevel=51,giver=[[Colossus Researcher Nestor]],giver_loc=[[Investigador de colosos Nestor]],giverType=[[NPC]],giverId=15798,ender=[[Oglethorpe Obnoticus]],ender_loc=[[Oglethorpe Obnoticus]],enderType=[[NPC]],enderId=7406,poiX=-14417,poiY=411,wowhead=[[https://www.wowhead.com/wotlk/quest=8857]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm looking for battle hardened adventurers willing and able to get a fresh husk sample from the fallen Colossus of Ashi to Oglethorpe in Booty Bay. No, no, I wouldn't want you to go anywhere near that thing's corpse. Just take one of my samples and make it snappy. These things are no good to him rotten!]],logDesc=[[Take the Colossus of Ashi's Husk to Oglethorpe Obnoticus in Booty Bay. ]],rewards={{id=21528,qty=1}}}
DB[8858]={id=8858,zoneId=1377,name=[[Secrets of the Colossus - Regal]],name_loc=[[Los secretos de los Colosos: Regal]],level=60,minLevel=51,giver=[[Colossus Researcher Eazel]],giver_loc=[[Investigador de colosos Eazel]],giverType=[[NPC]],giverId=15799,ender=[[Overseer Oilfist]],ender_loc=[[Sobrestante Puñaceite]],enderType=[[NPC]],enderId=14625,poiX=-6501,poiY=-1173,wowhead=[[https://www.wowhead.com/wotlk/quest=8858]],image=[[assets/images/quests/placeholder.png]],desc=[[There ain't nothin' I'd like more than to stuff this bug husk down Oilfist's fat face... Cept, I'm stuck here collectin' samples from that overgrown cockroach. I'll be here 'till the wee mornin' hours given the size o' that thing. Take this here sample to Oilfist fer me and do it fast, $c. He's payin' BIG! Yar, Thorium Point - it be in the Searin' Gorge.]],logDesc=[[Take the Colossus of Regal's Husk to Overseer Oilfist in Searing Gorge. ]],rewards={{id=21528,qty=1}}}
DB[8859]={id=8859,zoneId=1377,name=[[Secrets of the Colossus - Zora]],name_loc=[[Los secretos de los Colosos: Zora]],level=60,minLevel=51,giver=[[Colossus Researcher Sophia]],giver_loc=[[Investigadora de colosos Sofía]],giverType=[[NPC]],giverId=15797,ender=[[Lord Maxwell Tyrosus]],ender_loc=[[Lord Maxwell Neófitus]],enderType=[[NPC]],enderId=11034,poiX=2304,poiY=-5349,wowhead=[[https://www.wowhead.com/wotlk/quest=8859]],image=[[assets/images/quests/placeholder.png]],desc=[[My servants were nearly killed in their efforts to recover this sample. You absolutely must hurry! Lord Maxwell Tyrosus eagerly awaits a fresh husk sample. He believes that the secrets of this Colossus could help us in the war against the Scourge! Why are you still here!? To Light's Hope! Yes, you will be rewarded handsomely for your efforts... ]],logDesc=[[Take the Colossus of Zora's Husk to Lord Maxwell Tyrosus at Light's Hope Chapel in the Eastern Plaguelands. ]],rewards={{id=21528,qty=1}}}
DB[8860]={id=8860,name=[[New Year Celebrations!]],name_loc=[[¡Las fiestas de Año Nuevo!]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Innkeeper Allison]],ender_loc=[[Tabernera Allison]],enderType=[[NPC]],enderId=6740,poiX=-8868,poiY=674,wowhead=[[https://www.wowhead.com/wotlk/quest=8860]],image=[[assets/images/quests/placeholder.png]],desc=[[Stormwind is holding a celebration for the new year!  All day long today you can get free booze, and at night they'll put on a firework show!  It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better! Well anyway, Innkeeper Allison in Stormwind needs a supply of Smoky Wood Pasture fare to help feed all the party goers.  Can you do me a favor and deliver it! Thanks, $N!  Innkeeper Allison is in the Gilded Rose, in the Trade District of Stormwind.]],logDesc=[[Bring the Smokywood Supplies to Innkeeper Allison in Stormwind.]]}
DB[8861]={id=8861,name=[[New Year Celebrations!]],name_loc=[[¡Las fiestas de Año Nuevo!]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Innkeeper Pala]],ender_loc=[[Tabernera Pala]],enderType=[[NPC]],enderId=6746,poiX=-1300,poiY=38,wowhead=[[https://www.wowhead.com/wotlk/quest=8861]],image=[[assets/images/quests/placeholder.png]],desc=[[Thunder Bluff is holding a celebration for the new year!  All day you'll find free booze there, and at night they'll put on a firework show! It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better! Well anyway, Innkeeper Pala in Thunder Bluff needs a supply of Smoky Wood Pasture fare to help feed all the party goers.  Can you do me a favor and deliver it! Thanks, $N!  Innkeeper Pala is in the inn near the bridge to Hunter's Rise.]],logDesc=[[Bring the Smokywood Supplies to Innkeeper Pala in Thunder Bluff.]]}
