DB[8867]={id=8867,name=[[Lunar Fireworks]],name_loc=[[Fuegos artificiales lunares]],level=-1,minLevel=1,giver=[[Lunar Festival Harbinger]],giver_loc=[[Presagista del Festival Lunar]],giverType=[[NPC]],giverId=15895,ender=[[Lunar Festival Harbinger]],ender_loc=[[Presagista del Festival Lunar]],enderType=[[NPC]],enderId=15895,rewardNextId=8883,poiX=-8756,poiY=1069,wowhead=[[https://www.wowhead.com/wotlk/quest=8867]],image=[[assets/images/quests/placeholder.png]],desc=[[Every year the druids of Moonglade hold a celebration of our city's great triumph over an ancient evil. We celebrate the wisdom of our elders, share in magnificent feasts and of course... shoot fireworks! For a small donation you can purchase colorful rockets from our vendor.  Try using some of the launchers around here, $N.]],logDesc=[[Launch 8 Lunar Fireworks and 2 Cluster Fireworks and return to a Lunar Festival Harbinger at any capital city.]],rewards={{id=21711,qty=1}}}
DB[8868]={id=8868,name=[[Elune's Blessing]],name_loc=[[La bendición de Elune]],level=-1,minLevel=40,giver=[[Valadar Starsong]],giver_loc=[[Valadar Cantoestelar]],giverType=[[NPC]],giverId=15864,ender=[[Valadar Starsong]],ender_loc=[[Valadar Cantoestelar]],enderType=[[NPC]],enderId=15864,poiX=7949,poiY=-2620,wowhead=[[https://www.wowhead.com/wotlk/quest=8868]],image=[[assets/images/quests/placeholder.png]],desc=[[The beast Omen was once a hero of this world.  A wolf of great strength and fortune, Omen fought beside the heroes of the War of the Ancients until he succumbed to demonic magics.  Turning against his allies, he raged across Azeroth and carried death and terror in his wake. Finally defeated here, in Moonglade, Omen now sleeps among the silt of Lake Elune'ara.  But each new year, during the festival, he stirs... Gather cohorts, $N, and summon and defeat the beast Omen.  Earn the blessing of Elune!]],logDesc=[[Summon Omen, defeat him and gain Elune's Blessing.  Return to Valadar Starsong in Nighthaven]],rewards={{id=21540,qty=1},{id=21640,qty=1},{id=7912,qty=3}}}
DB[8870]={id=8870,name=[[The Lunar Festival]],name_loc=[[El Festival Lunar]],level=-1,minLevel=1,giver=[[Lunar Festival Emissary]],giver_loc=[[Emisario del Festival Lunar]],giverType=[[NPC]],giverId=15892,ender=[[Lunar Festival Harbinger]],ender_loc=[[Presagista del Festival Lunar]],enderType=[[NPC]],enderId=15895,rewardNextId=8867,exGroup=8870,poiX=-8756,poiY=1069,wowhead=[[https://www.wowhead.com/wotlk/quest=8870]],image=[[assets/images/quests/placeholder.png]],desc=[[It's that time of the year, $N!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.]],logDesc=[[Talk to the Lunar Festival Harbinger in the Mystic Ward of Ironforge.  You can also talk to Lunar Festival Harbingers in other capital cities.]]}
