DB[9050]={id=9050,zoneId=3456,name=[[Redemption Wristguards]],name_loc=[[Los guardamuñecas de redención]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],prevId=9033,poiX=3363,poiY=-3621,wowhead=[[https://www.wowhead.com/wotlk/quest=9050]],image=[[assets/images/quests/placeholder.png]],desc=[[You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.]],logDesc=[[Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make Redemption Wristguards if you bring him the following: 1 Desecrated Wristguards, 6 Wartorn Plate Scraps, 1 Arcanite Bar and 2 Cured Rugged Hides.]],rewards={{id=22424,qty=1}}}
DB[9051]={id=9051,name=[[Toxic Test]],name_loc=[[Prueba de toxicidad]],level=52,minLevel=50,giver=[[Torwa Pathfinder]],giver_loc=[[Torwa Abrecaminos]],giverType=[[NPC]],giverId=9619,ender=[[Torwa Pathfinder]],ender_loc=[[Torwa Abrecaminos]],enderType=[[NPC]],enderId=9619,prevId=9052,rewardNextId=9053,poiX=-7840,poiY=-2117,wowhead=[[https://www.wowhead.com/wotlk/quest=9051]],image=[[assets/images/quests/placeholder.png]],desc=[[The toxin you helped me create is for a special purpose.  The great devilsaurs of the crater make it dangerous to hunt and difficult for me to survive.  Even if I possessed the necessary strength, killing a devilsaur simply allows another to move into its territory. Take this poisoned barb and stab it deep into a living devilsaur.  The toxin should pacify the creature, though I do not know how quickly...]],logDesc=[[Stab a Devilsaur with the Devilsaur Barb. Return to Torwa Pathfinder in Un'Goro Crater when you have completed this task.]]}
DB[9052]={id=9052,name=[[Bloodpetal Poison]],name_loc=[[Veneno de Sangrepétalo]],level=52,minLevel=50,giver=[[Torwa Pathfinder]],giver_loc=[[Torwa Abrecaminos]],giverType=[[NPC]],giverId=9619,ender=[[Torwa Pathfinder]],ender_loc=[[Torwa Abrecaminos]],enderType=[[NPC]],enderId=9619,rewardNextId=9051,poiX=-8050,poiY=-1547,wowhead=[[https://www.wowhead.com/wotlk/quest=9052]],image=[[assets/images/quests/placeholder.png]],desc=[[I would ask you to help me create a toxin of sorts, to pacify a great creature living here in the crater.  It is not deadly, and only the keen eyes of a $c can hope to collect the ingredients. You can find the bloodcap mushrooms growing within the bloodpetal sprouts all across the crater.  Gorishi stings are from the insects inside and around the Slithering Scar, located in the southern part of the crater.]],logDesc=[[Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater.]],rewards={{id=13446,qty=2}}}
DB[9053]={id=9053,name=[[A Better Ingredient]],name_loc=[[Un ingrediente mejor]],level=52,minLevel=50,giver=[[Torwa Pathfinder]],giver_loc=[[Torwa Abrecaminos]],giverType=[[NPC]],giverId=9619,ender=[[Torwa Pathfinder]],ender_loc=[[Torwa Abrecaminos]],enderType=[[NPC]],enderId=9619,prevId=9051,poiX=-7840,poiY=-2117,wowhead=[[https://www.wowhead.com/wotlk/quest=9053]],image=[[assets/images/quests/placeholder.png]],desc=[[It is as I feared -- the toxin is simply too weak for such a powerful creature. If we are to create a toxin of high enough potency, you must venture to the bottom of the Temple of Atal'Hakkar, unlock the secrets of the altar and recover a putrid vine from the guardian there.  The temple is dangerous, and it would behoove you to bring friends. Return to me when this is done.]],logDesc=[[Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder.]],choiceRewards={{id=22274,qty=1},{id=22272,qty=1},{id=22458,qty=1}}}
DB[9054]={id=9054,zoneId=3456,name=[[Cryptstalker Tunic]],name_loc=[[La guerrera de acechacriptas]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],prevId=9033,poiX=3363,poiY=-3621,wowhead=[[https://www.wowhead.com/wotlk/quest=9054]],image=[[assets/images/quests/placeholder.png]],desc=[[I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas. Bring me the items I require and I shall fashion for you a suit of armor the likes of which has never before been seen in our world!]],logDesc=[[Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands will make a Cryptstalker Tunic if you bring him the following: 1 Desecrated Tunic, 25 Wartorn Chain Scraps, 4 Arcanite Bars and 3 Cured Rugged Hides.]],rewards={{id=22436,qty=1}}}
