DB[9063]={id=9063,name=[[Torwa Pathfinder]],name_loc=[[Torwa Abrecaminos]],level=52,minLevel=50,giver=[[Turak Runetotem]],giver_loc=[[Turak Tótem de Runa]],giverType=[[NPC]],giverId=3033,ender=[[Torwa Pathfinder]],ender_loc=[[Torwa Abrecaminos]],enderType=[[NPC]],enderId=9619,rewardNextId=9052,poiX=-7840,poiY=-2117,wowhead=[[https://www.wowhead.com/wotlk/quest=9063]],image=[[assets/images/quests/placeholder.png]],desc=[[A hunter by the name of Torwa Pathfinder has requested the help of a druid.  He said only we would possess the necessary skills and respect for nature to help him. There is a road that connects the Un'Goro Crater and the desert of Tanaris.  As that road enters the crater, you will find Torwa close by.]],logDesc=[[Speak with Torwa Pathfinder in Un'Goro Crater.]]}
