DB[9120]={id=9120,zoneId=3456,name=[[The Fall of Kel'Thuzad]],name_loc=[[La caída de Kel'Thuzad]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],poiX=2299,poiY=-5338,wowhead=[[https://www.wowhead.com/wotlk/quest=9120]],image=[[assets/images/quests/placeholder.png]],desc=[[The phylactery is all that remains of the master of Naxxramas. Your better judgment dictates that you destroy the phylactery, preventing the lich from ever reforming. Thankfully, you seldom listen to that internal voice of reason. Someone at Light's Hope will pay you hugely for this artifact. Who cares if Kel'Thuzad regenerates to full power?]],logDesc=[[Take the Phylactery of Kel'Thuzad to Light's Hope Chapel in the Eastern Plaguelands.]],choiceRewards={{id=23206,qty=1},{id=23207,qty=1}}}
DB[9121]={id=9121,zoneId=139,name=[[The Dread Citadel - Naxxramas]],name_loc=[[La ciudadela del terror: Naxxramas]],level=60,minLevel=60,giver=[[Archmage Angela Dosantos]],giver_loc=[[Archimaga Angela Dosantos]],giverType=[[NPC]],giverId=16116,ender=[[Archmage Angela Dosantos]],ender_loc=[[Archimaga Angela Dosantos]],enderType=[[NPC]],enderId=16116,nextId=9033,exGroup=9121,poiX=2295,poiY=-5340,wowhead=[[https://www.wowhead.com/wotlk/quest=9121]],image=[[assets/images/quests/placeholder.png]],desc=[[In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now. We have devised a way to gain entry via arcane cloaking - an old cantrip of the Kirin Tor with a few modifications of my own. Since your dedication to the cause of the Dawn is somewhat lacking, $N, the price will be high. You may decline and choose to return when you are revered or exalted for a discount.]],logDesc=[[Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 5 Arcane Crystals, 2 Nexus Crystals, 1 Righteous Orb and 60 gold pieces. You must also be Honored with the Argent Dawn. ]]}
DB[9122]={id=9122,zoneId=139,name=[[The Dread Citadel - Naxxramas]],name_loc=[[La ciudadela del terror: Naxxramas]],level=60,minLevel=60,giver=[[Archmage Angela Dosantos]],giver_loc=[[Archimaga Angela Dosantos]],giverType=[[NPC]],giverId=16116,ender=[[Archmage Angela Dosantos]],ender_loc=[[Archimaga Angela Dosantos]],enderType=[[NPC]],enderId=16116,nextId=9033,exGroup=9121,poiX=2295,poiY=-5340,wowhead=[[https://www.wowhead.com/wotlk/quest=9122]],image=[[assets/images/quests/placeholder.png]],desc=[[In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now. We have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly. Since your dedication to the cause of the Dawn is admirable, we are willing to incur some of those costs.]],logDesc=[[Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 2 Arcane Crystals, 1 Nexus Crystal and 30 gold pieces. You must also be Revered with the Argent Dawn.]]}
DB[9123]={id=9123,zoneId=139,name=[[The Dread Citadel - Naxxramas]],name_loc=[[La ciudadela del terror: Naxxramas]],level=60,minLevel=60,giver=[[Archmage Angela Dosantos]],giver_loc=[[Archimaga Angela Dosantos]],giverType=[[NPC]],giverId=16116,ender=[[Archmage Angela Dosantos]],ender_loc=[[Archimaga Angela Dosantos]],enderType=[[NPC]],enderId=16116,nextId=9033,exGroup=9121,poiX=2295,poiY=-5340,wowhead=[[https://www.wowhead.com/wotlk/quest=9123]],image=[[assets/images/quests/placeholder.png]],desc=[[In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now. We have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.]],logDesc=[[Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn.]]}
DB[9124]={id=9124,zoneId=139,name=[[Cryptstalker Armor Doesn't Make Itself...]],name_loc=[[La armadura de acechacriptas no se hace sola...]],level=60,minLevel=55,giver=[[Huntsman Leopold]],giver_loc=[[Montero Leopold]],giverType=[[NPC]],giverId=16132,ender=[[Huntsman Leopold]],ender_loc=[[Montero Leopold]],enderType=[[NPC]],enderId=16132,poiX=2289,poiY=-5340,wowhead=[[https://www.wowhead.com/wotlk/quest=9124]],image=[[assets/images/quests/placeholder.png]],desc=[[How would you like to earn yourself one of these shiny coins? <Leopold holds up an insignia of the Crusade.> I've got a little problem that you might be able to help me with, $N. You see, I make Cryptstalker armor for those daft enough to venture into Naxxramas. While they supply me with the core material requirements for the armor, I always run out of the crypt fiend parts. Bring me back a bundle of parts and I'll pay you with an insignia - usable at the quartermaster.]],logDesc=[[Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands wants 30 Crypt Fiend Parts.]],rewards={{id=22524,qty=1}}}
DB[9125]={id=9125,zoneId=139,name=[[Crypt Fiend Parts]],name_loc=[[Trozos de maligno de cripta]],level=60,minLevel=55,giver=[[Huntsman Leopold]],giver_loc=[[Montero Leopold]],giverType=[[NPC]],giverId=16132,ender=[[Huntsman Leopold]],ender_loc=[[Montero Leopold]],enderType=[[NPC]],enderId=16132,prevId=9124,poiX=2289,poiY=-5340,wowhead=[[https://www.wowhead.com/wotlk/quest=9125]],image=[[assets/images/quests/placeholder.png]],rewards={{id=22524,qty=1}}}
DB[9126]={id=9126,zoneId=139,name=[[Bonescythe Digs]],name_loc=[[Excavaciones para la armadura Segahuesos]],level=60,minLevel=55,giver=[[Rohan the Assassin]],giver_loc=[[Rohan el Asesino]],giverType=[[NPC]],giverId=16131,ender=[[Rohan the Assassin]],ender_loc=[[Rohan el Asesino]],enderType=[[NPC]],enderId=16131,poiX=2290,poiY=-5337,wowhead=[[https://www.wowhead.com/wotlk/quest=9126]],image=[[assets/images/quests/placeholder.png]],desc=[[Don Julio's Bonescythe armor pattern requires bone fragments - a lot of bone fragments. While those crazy enough to venture into Naxxramas provide me with enough of the core materials to make the armor, I'm always looking for more Scourge bone fragments. So what do you think? Interested in getting your hands dirty and destroying some Scourge at the same time? It's a win-win situation.]],logDesc=[[Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands wants 30 Bone Fragments. ]],rewards={{id=22524,qty=1}}}
DB[9127]={id=9127,zoneId=139,name=[[Bone Fragments]],name_loc=[[Trozos de hueso]],level=60,minLevel=55,giver=[[Rohan the Assassin]],giver_loc=[[Rohan el Asesino]],giverType=[[NPC]],giverId=16131,ender=[[Rohan the Assassin]],ender_loc=[[Rohan el Asesino]],enderType=[[NPC]],enderId=16131,prevId=9126,poiX=2290,poiY=-5337,wowhead=[[https://www.wowhead.com/wotlk/quest=9127]],image=[[assets/images/quests/placeholder.png]],rewards={{id=22524,qty=1}}}
DB[9128]={id=9128,zoneId=139,name=[[The Elemental Equation]],name_loc=[[La ecuación elemental]],level=60,minLevel=55,giver=[[Archmage Angela Dosantos]],giver_loc=[[Archimaga Angela Dosantos]],giverType=[[NPC]],giverId=16116,ender=[[Archmage Angela Dosantos]],ender_loc=[[Archimaga Angela Dosantos]],enderType=[[NPC]],enderId=16116,poiX=2295,poiY=-5340,wowhead=[[https://www.wowhead.com/wotlk/quest=9128]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, adventurer! Are you interested in some work? I pay those under my employ with insignias. These insignias can be used at the Quartermaster to purchase items of power. All I need you to do is bring me as many core of elements as you can carry. The more the better! You'll find them on elementals of varying shapes and sizes that exist across our world.]],logDesc=[[Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 30 Core of Elements. ]],rewards={{id=22523,qty=1}}}
DB[9129]={id=9129,zoneId=139,name=[[Core of Elements]],name_loc=[[Núcleo de elementos]],level=60,minLevel=55,giver=[[Archmage Angela Dosantos]],giver_loc=[[Archimaga Angela Dosantos]],giverType=[[NPC]],giverId=16116,ender=[[Archmage Angela Dosantos]],ender_loc=[[Archimaga Angela Dosantos]],enderType=[[NPC]],enderId=16116,prevId=9128,poiX=2295,poiY=-5340,wowhead=[[https://www.wowhead.com/wotlk/quest=9129]],image=[[assets/images/quests/placeholder.png]],rewards={{id=22523,qty=1}}}
DB[9131]={id=9131,zoneId=139,name=[[Binding the Dreadnaught]],name_loc=[[Armar la acorator]],level=60,minLevel=55,giver=[[Korfax, Champion of the Light]],giver_loc=[[Korfax, Campeón de la Luz]],giverType=[[NPC]],giverId=16112,ender=[[Korfax, Champion of the Light]],ender_loc=[[Korfax, Campeón de la Luz]],enderType=[[NPC]],enderId=16112,poiX=2301,poiY=-5352,wowhead=[[https://www.wowhead.com/wotlk/quest=9131]],image=[[assets/images/quests/placeholder.png]],desc=[[Have you ever seen Dreadnaught armor, $c? No, of course you haven't. You're still a $g boy:girl; - a tyke. Let me tell you, it is glorious. You're probably asking yourself what any of this has to do with you, right? I'll tell you what, scrub; I need Dark Iron scraps and I'm willing to pay to get my hands on as many as possible. I need the scraps to put together sets of Dreadnaught for our champions. Bring me scraps and get paid.]],logDesc=[[Korfax at Light's Hope Chapel in the Eastern Plaguelands wants 30 Dark Iron Scraps.]],rewards={{id=22523,qty=1}}}
DB[9132]={id=9132,zoneId=139,name=[[Dark Iron Scraps]],name_loc=[[Fragmentos de hierro negro]],level=60,minLevel=55,giver=[[Korfax, Champion of the Light]],giver_loc=[[Korfax, Campeón de la Luz]],giverType=[[NPC]],giverId=16112,ender=[[Korfax, Champion of the Light]],ender_loc=[[Korfax, Campeón de la Luz]],enderType=[[NPC]],enderId=16112,prevId=9131,poiX=2301,poiY=-5352,wowhead=[[https://www.wowhead.com/wotlk/quest=9132]],image=[[assets/images/quests/placeholder.png]],rewards={{id=22523,qty=1}}}
DB[9136]={id=9136,zoneId=139,name=[[Savage Flora]],name_loc=[[Flora salvaje]],level=60,minLevel=55,giver=[[Rayne]],giver_loc=[[Rayne]],giverType=[[NPC]],giverId=16135,ender=[[Rayne]],ender_loc=[[Rayne]],enderType=[[NPC]],enderId=16135,poiX=2277,poiY=-5329,wowhead=[[https://www.wowhead.com/wotlk/quest=9136]],image=[[assets/images/quests/placeholder.png]],desc=[[I make a special type of armor for the brave heroes that enter Naxxramas known as Dreamwalker. They are able to provide me with most of the materials I require but I am always looking for those able to retrieve savage fronds from the flora of our world. You may think of this job as beneath you, but without the fronds, the armor could not be made. I am also in a unique position to pay you with an insignia of your choice as both the Dawn and the Crusade supply me with funds. ]],logDesc=[[Rayne at Light's Hope Chapel in the Eastern Plaguelands wants 30 Savage Fronds.]],choiceRewards={{id=22524,qty=1},{id=22523,qty=1}}}
DB[9137]={id=9137,zoneId=139,name=[[Savage Fronds]],name_loc=[[Hojas salvajes]],level=60,minLevel=55,giver=[[Rayne]],giver_loc=[[Rayne]],giverType=[[NPC]],giverId=16135,ender=[[Rayne]],ender_loc=[[Rayne]],enderType=[[NPC]],enderId=16135,prevId=9136,poiX=2277,poiY=-5329,wowhead=[[https://www.wowhead.com/wotlk/quest=9137]],image=[[assets/images/quests/placeholder.png]],choiceRewards={{id=22523,qty=1},{id=22524,qty=1}}}
DB[9141]={id=9141,zoneId=139,name=[[They Call Me "The Rooster"]],name_loc=[[Me llaman "El Gallo"]],level=60,minLevel=55,giver=[[Dispatch Commander Metz]],giver_loc=[[Comandante de envíos Metz]],giverType=[[NPC]],giverId=16212,ender=[[Dispatch Commander Metz]],ender_loc=[[Comandante de envíos Metz]],enderType=[[NPC]],enderId=16212,poiX=2315,poiY=-5323,wowhead=[[https://www.wowhead.com/wotlk/quest=9141]],image=[[assets/images/quests/placeholder.png]],desc=[[You want a writ? What? Do you expect me to hand you a highly sought after work order just for showing up? I think not, scrub. Crafters from around the world bid for jobs here at the front lines. If you want a work order, you'll have to show me that you're willing to bleed for the cause. Bring me a valor token and we'll talk. And there's only one way to get your grubby little scrub mitts on those - get to killin'.]],logDesc=[[Dispatch Commander Metz at Light's Hope Chapel in the Eastern Plaguelands wants an Argent Dawn Valor Token. ]],rewards={{id=22568,qty=1}}}
DB[9142]={id=9142,zoneId=139,name=[[Craftsman's Writ]],name_loc=[[Libranza del artesano]],level=60,minLevel=55,giver=[[Dispatch Commander Metz]],giver_loc=[[Comandante de envíos Metz]],giverType=[[NPC]],giverId=16212,ender=[[Dispatch Commander Metz]],ender_loc=[[Comandante de envíos Metz]],enderType=[[NPC]],enderId=16212,prevId=9141,poiX=2315,poiY=-5323,wowhead=[[https://www.wowhead.com/wotlk/quest=9142]],image=[[assets/images/quests/placeholder.png]],rewards={{id=22568,qty=1}}}
DB[9153]={id=9153,name=[[Under the Shadow]],name_loc=[[Bajo la Sombra]],level=-1,minLevel=50,giver=[[Commander Thomas Helleran]],giver_loc=[[Comandante Thomas Helleran]],giverType=[[NPC]],giverId=16361,ender=[[Commander Thomas Helleran]],ender_loc=[[Comandante Thomas Helleran]],enderType=[[NPC]],enderId=16361,poiX=2241,poiY=-5317,wowhead=[[https://www.wowhead.com/wotlk/quest=9153]],image=[[assets/images/quests/placeholder.png]],desc=[[The floating necropolises of the Scourge plague the lands of Horde and Alliance alike. Tanaris, the Blasted Lands, Winterspring and the Burning Steppes are blanketed in the shadows of the flying fortresses. Only through our combined efforts will they be repelled. Each necropolis is supported by nearby magical circles, and among each circle swarms a host of undead creartures. We have determined that destroying these mindless hordes will destroy the circle's defenses.]],logDesc=[[Check your map to find an area under Scourge attack. Go there and damage a necropolis by defeating the Scourge around them. Return 10 of their Necrotic Runes to Commander Thomas Helleran at Light's Hope Chapel in the Eastern Plaguelands.]],choiceRewards={{id=23123,qty=2},{id=23122,qty=2}}}
DB[9154]={id=9154,name=[[Light's Hope Chapel]],name_loc=[[Capilla de la Esperanza de la Luz]],level=-1,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],poiX=2242,poiY=-5317,wowhead=[[https://www.wowhead.com/wotlk/quest=9154]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge have returned in greater numbers than we have seen before.  This must be the doing of the Lich King!  The Argent Dawn is recruiting all willing and capable men and women to defend our lands. If we share common cause, take this document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.]],logDesc=[[Deliver the Call to Arms Announcement to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.]]}
DB[9165]={id=9165,zoneId=139,name=[[Writ of Safe Passage]],name_loc=[[La libranza de salvoconducto]],level=60,minLevel=55,giver=[[Guard Didier]],giver_loc=[[Guardia Didier]],giverType=[[NPC]],giverId=16226,ender=[[Dispatch Commander Metz]],ender_loc=[[Comandante de envíos Metz]],enderType=[[NPC]],enderId=16212,poiX=2854,poiY=-3872,wowhead=[[https://www.wowhead.com/wotlk/quest=9165]],image=[[assets/images/quests/placeholder.png]],desc=[[Without the help of adventurers, my caravan would have never made it! Scourge were coming out of the woodwork to try and stop us from getting here. <Guard Didier wipes his brow.> Now we need to wait here for Field Marshal Chambers to arrive. He'll sign your writ of safe passage to take back to Dispatch Commander Metz at Light's Hope Chapel. And $N, watch what you say around Chambers. He's the 'bite off your head and spit down your wind pipe' type of guy - except that he'll actually do it...]],logDesc=[[Deliver the signed Writ of Safe Passage to Dispatch Commander Metz at Light's Hope Chapel in the Eastern Plaguelands.]],choiceRewards={{id=22523,qty=1},{id=22524,qty=1}}}
