DB[9208]={id=9208,zoneId=1977,name=[[The Savage Guard - Arcanum of Protection]],name_loc=[[La guardia salvaje: arcanum de protección]],level=60,minLevel=58,giver=[[Zanza the Restless]],giver_loc=[[Zanza el Incansable]],giverType=[[NPC]],giverId=15042,ender=[[Zanza the Restless]],ender_loc=[[Zanza el Incansable]],enderType=[[NPC]],enderId=15042,wowhead=[[https://www.wowhead.com/wotlk/quest=9208]],image=[[assets/images/quests/placeholder.png]],desc=[[Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic. Bring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours. ]],logDesc=[[Zanza the Restless in Zul'Gurub wants an Arcanum of Protection.]],rewards={{id=22635,qty=1}}}
