DB[9211]={id=9211,zoneId=139,name=[[The Ice Guard]],name_loc=[[El guardahielo]],level=60,minLevel=60,giver=[[Mataus the Wrathcaster]],giver_loc=[[Mataus el Colérico]],giverType=[[NPC]],giverId=16133,ender=[[Mataus the Wrathcaster]],ender_loc=[[Mataus el Colérico]],enderType=[[NPC]],enderId=16133,poiX=2297,poiY=-5336,wowhead=[[https://www.wowhead.com/wotlk/quest=9211]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, the Ice Guard. It is a thin sheen of protective magic that covers certain pieces of equipment. Those that do battle with creatures of frost and ice will gain increased protection from their attacks by using the Ice Guard. As with all things the Wrathcaster creates, there is a price - a price that I will not lower, regardless of how much you whimper. Interested?]],logDesc=[[Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.]],rewards={{id=22636,qty=1}}}
DB[9213]={id=9213,zoneId=139,name=[[The Shadow Guard]],name_loc=[[El guardasombras]],level=60,minLevel=60,giver=[[Mataus the Wrathcaster]],giver_loc=[[Mataus el Colérico]],giverType=[[NPC]],giverId=16133,ender=[[Mataus the Wrathcaster]],ender_loc=[[Mataus el Colérico]],enderType=[[NPC]],enderId=16133,poiX=2297,poiY=-5336,wowhead=[[https://www.wowhead.com/wotlk/quest=9213]],image=[[assets/images/quests/placeholder.png]],desc=[[A creation of genius! Much like the Ice Guard, the Shadow Guard employs a thin sheen of protective magic that covers certain pieces of equipment. And like the Ice Guard, the Shadow Guard is going to cost you a good amount of money. <Mataus holds his hand out and rubs his fingers together.> Interested?]],logDesc=[[Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.]],rewards={{id=22638,qty=1}}}
