DB[9247]={id=9247,name=[[The Keeper's Call]],name_loc=[[La llamada de los guardianes]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Keeper of the Rolls]],ender_loc=[[Guardián de los Pergaminos]],enderType=[[NPC]],enderId=16281,poiX=2242,poiY=-5317,wowhead=[[https://www.wowhead.com/wotlk/quest=9247]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, In times past you have served the interests of the Argent Dawn, always to the best of your abilities. Now, once again, we sound the clarion call in our time of greatest need. $N, please report to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands if you are willing to aid us once more.]],logDesc=[[Take the Letter from the Keeper of the Rolls to him at Light's Hope Chapel in the Eastern Plaguelands.]],choiceRewards={{id=23123,qty=1},{id=23122,qty=1}}}
DB[9248]={id=9248,zoneId=1377,name=[[A Humble Offering]],name_loc=[[Una humilde ofrenda]],level=60,minLevel=58,giver=[[Aurel Goldleaf]],giver_loc=[[Aurel Hojaurea]],giverType=[[NPC]],giverId=15282,ender=[[Aurel Goldleaf]],ender_loc=[[Aurel Hojaurea]],enderType=[[NPC]],enderId=15282,poiX=-6845,poiY=728,wowhead=[[https://www.wowhead.com/wotlk/quest=9248]],image=[[assets/images/quests/placeholder.png]],desc=[[Ishnu-alah, $r. Show me proof of the demise of a Lord of the Abyssal Council and I shall reward you with an item that should aid you in your battles against the Qiraji.]],logDesc=[[Aurel Goldleaf at Cenarion Hold in Silithus wants you to bring her 1 Abyssal Scepter. You must also be Honored with the Cenarion Circle.]],rewards={{id=22725,qty=1}}}
DB[9250]={id=9250,name=[[Frame of Atiesh]],name_loc=[[Cuerpo de Atiesh]],level=60,minLevel=60,giverType=[[NPC]],ender=[[Anachronos]],ender_loc=[[Anacronos]],enderType=[[NPC]],enderId=15192,rewardNextId=9251,poiX=-8240,poiY=-4649,wowhead=[[https://www.wowhead.com/wotlk/quest=9250]],image=[[assets/images/quests/placeholder.png]],desc=[[With the frame formed, Atiesh is nearly whole. Only the head and base of the staff are now missing. There is also a minor issue regarding the staff being a conduit for Sargeras's evil. Find someone that can assist you in locating the remaining pieces and exorcising the evil from the staff.]],logDesc=[[Find someone that will help you in recovering the last two pieces of the staff and ridding it of evil.]]}
DB[9251]={id=9251,name=[[Atiesh, the Befouled Greatstaff]],name_loc=[[Atiesh, el gran báculo maligno]],level=60,minLevel=60,giver=[[Anachronos]],giver_loc=[[Anacronos]],giverType=[[NPC]],giverId=15192,ender=[[Anachronos]],ender_loc=[[Anacronos]],enderType=[[NPC]],enderId=15192,prevId=9250,poiX=-8240,poiY=-4649,wowhead=[[https://www.wowhead.com/wotlk/quest=9251]],image=[[assets/images/quests/placeholder.png]],desc=[[You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, $N. I only do as I must. Kel'Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek. As for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn'Qiraj. He has left Ahn'Qiraj but the base of Atiesh remains. Should you succeed in recovering the pieces, return them to me.]],logDesc=[[Anachronos at the Caverns of Time in Tanaris wants the Staff Head of Atiesh and the Base of Atiesh.]]}
DB[9257]={id=9257,name=[[Atiesh, Greatstaff of the Guardian]],name_loc=[[Atiesh, el gran báculo del guardián]],level=60,minLevel=60,giver=[[Anachronos]],giver_loc=[[Anacronos]],giverType=[[NPC]],giverId=15192,ender=[[Anachronos]],ender_loc=[[Anacronos]],enderType=[[NPC]],enderId=15192,prevId=9251,exGroup=9257,poiX=-8240,poiY=-4649,wowhead=[[https://www.wowhead.com/wotlk/quest=9257]],image=[[assets/images/quests/placeholder.png]],desc=[[This final task will be the most difficult of all, $N. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras. Take the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.]],logDesc=[[Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.]],rewards={{id=22631,qty=1}}}
DB[9259]={id=9259,zoneId=33,name=[[Traitor to the Bloodsail]],name_loc=[[Un traidor de Velasangre]],level=-1,minLevel=30,giver=[[Bloodsail Traitor]],giver_loc=[[Traidor Velasangre]],giverType=[[NPC]],giverId=16399,ender=[[Bloodsail Traitor]],ender_loc=[[Traidor Velasangre]],enderType=[[NPC]],enderId=16399,poiX=-14184,poiY=193,wowhead=[[https://www.wowhead.com/wotlk/quest=9259]],image=[[assets/images/quests/placeholder.png]]}
DB[9260]={id=9260,name=[[Investigate the Scourge of Stormwind]],name_loc=[[Investigar la Plaga de Ventormenta]],level=6,minLevel=1,giver=[[Lieutenant Orrin]],giver_loc=[[Teniente Orrin]],giverType=[[NPC]],giverId=16478,ender=[[Lieutenant Orrin]],ender_loc=[[Teniente Orrin]],enderType=[[NPC]],enderId=16478,poiX=-9255,poiY=229,wowhead=[[https://www.wowhead.com/wotlk/quest=9260]],image=[[assets/images/quests/placeholder.png]],desc=[[The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Stormwind from these accursed invaders?    There are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!]],logDesc=[[Collect three Dim Necrotic Stones from the Scourge outside Stormwind and investigate the glowing runic circles near their encampment.]]}
