DB[9295]={id=9295,name=[[Letter from the Front]],name_loc=[[Una carta del frente]],level=-1,minLevel=45,giverType=[[NPC]],ender=[[Keeper of the Rolls]],ender_loc=[[Guardián de los Pergaminos]],enderType=[[NPC]],enderId=16281,poiX=2242,poiY=-5317,wowhead=[[https://www.wowhead.com/wotlk/quest=9295]],image=[[assets/images/quests/placeholder.png]],desc=[[You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...]],logDesc=[[Take the Torn Letter to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.]]}
