DB[9306]={id=9306,zoneId=3526,name=[[<DEPRECATED>Speak with Vindicator Aldar]],name_loc=[[Hablar con el vindicador Aldar]],level=4,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=9307,poiX=-4195,poiY=-13736,wowhead=[[https://www.wowhead.com/wotlk/quest=9306]],image=[[assets/images/quests/placeholder.png]],desc=[[$N,Vindicator Aldar has been looking for someone to take care of a problem that we're having with the mutated owlkin at Nestlewood Thicket.  We must deal with an unfortunate side effect of our unintended arrival here. You'll find him outside to the south in the crash site. Please,speak with him as soon as you can.]],logDesc=[[Speak with Vindicator Aldar at the Crash Site in Ammen Vale.]]}
DB[9307]={id=9307,zoneId=3526,name=[[<DEPRECATED>Compassion]],name_loc=[[Compasión]],level=4,minLevel=2,giverType=[[NPC]],enderType=[[NPC]],poiX=-4495,poiY=-14105,wowhead=[[https://www.wowhead.com/wotlk/quest=9307]],image=[[assets/images/quests/placeholder.png]],desc=[[Nearby Silverline Lake was contaminated by a piece of the ship that fell into it.  This in turn has caused the mutation of most of the creatures in the area,some of which have turned hostile.  The worst of these are the mutated owlkin. Go south into Nestlewood Thicket and put down as many of these pitiful creatures as you can.  It's a mercy killing,$c,so please make it quick and painless.]],logDesc=[[Kill 14 Mutated Owlkin and then return to Vindicator Aldar at the Crash Site in Ammen Vale.]],choiceRewards={{id=24135,qty=1},{id=24134,qty=1},{id=24133,qty=1}}}
DB[9308]={id=9308,zoneId=3526,name=[[<DEPRECATED>Blood Elf Remains?]],name_loc=[[Restos de elfo de sangre]],level=4,minLevel=3,giverType=[[NPC]],enderType=[[NPC]],poiX=-4195,poiY=-13736,wowhead=[[https://www.wowhead.com/wotlk/quest=9308]],image=[[assets/images/quests/placeholder.png]],desc=[[You believe that these are the remains of one of the sin'dorei -- a blood elf -- laying dead here on the ground.  By the look of it he fell victim to the savage claws of at least a few of the mutated owlkin in the thicket. Searching the body,you uncover an amulet on a chain around his neck.  Perhaps this would be of interest to Vindicator Aldar?]],logDesc=[[Take the Blood Elf Amulet to Vindicator Aldar at the Crash Site in Ammen Vale.]]}
DB[9310]={id=9310,name=[[Faint Necrotic Crystal]],name_loc=[[Cristal necrótico tenue]],level=-1,minLevel=1,giver=[[Faint Necrotic Crystal]],giver_loc=[[Cristal necrótico tenue]],giverType=[[NPC]],giverId=16531,ender=[[Lieutenant Rukag]],ender_loc=[[Teniente Rukag]],enderType=[[NPC]],enderId=16494,poiX=1737,poiY=240,wowhead=[[https://www.wowhead.com/wotlk/quest=9310]],image=[[assets/images/quests/placeholder.png]],desc=[[On the corpse of the fallen wight, you find a crystal faintly radiating necrotic energy.]],logDesc=[[Bring the Faint Necrotic Crystal to Lieutenant Rukag in the courtyard of the Undercity.]],choiceRewards={{id=23123,qty=1},{id=23122,qty=1}}}
DB[9316]={id=9316,zoneId=151,name=[[[TXT] Goblin Savages]],name_loc=[[Goblin salvajes]],level=50,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=9316]],image=[[assets/images/quests/placeholder.png]],desc=[[<Brianna gives you a searching glance.> So,you want to kill some goblins,eh? Well,if you're determined,you can start with the nearby savages. Bring me their teeth as proof of your deeds.]],logDesc=[[Brianna Schneider on Designer Island wants 10 Goblin Teeth.]],rewards={{id=13909,qty=1}}}
