DB[9318]={id=9318,name=[[Blessed Wizard Oil]],name_loc=[[Aceite de zahorí bendito]],level=-1,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],poiX=-8837,poiY=648,wowhead=[[https://www.wowhead.com/wotlk/quest=9318]],image=[[assets/images/quests/placeholder.png]],rewards={{id=23123,qty=1}}}
DB[9319]={id=9319,name=[[A Light in Dark Places]],name_loc=[[Una luz en la oscuridad]],level=-1,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],poiX=-8833,poiY=866,wowhead=[[https://www.wowhead.com/wotlk/quest=9319]],image=[[assets/images/quests/placeholder.png]],desc=[[We are not the only ones who celebrate this holiday, $n. All creatures, all cultures, are touched by the flame. Even in the darkest places, the fires are being lit. If you wish to see them for yourself, travel into the depths. Seek out the bonfires burning within Stratholme, Scholomance, among the ogres of Dire Maul, and the halls of Blackrock Spire itself; I will await your return.]],logDesc=[[Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then return to the Festival Flamekeeper.]],rewards={{id=23083,qty=1},{id=23247,qty=10}}}
DB[9320]={id=9320,name=[[Super Mana Potion]],name_loc=[[Superpoción de maná]],level=-1,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],poiX=1580,poiY=245,wowhead=[[https://www.wowhead.com/wotlk/quest=9320]],image=[[assets/images/quests/placeholder.png]],rewards={{id=22832,qty=1}}}
DB[9321]={id=9321,name=[[Super Healing Potion]],name_loc=[[Superpoción de sanación]],level=-1,minLevel=50,giverType=[[NPC]],enderType=[[NPC]],poiX=-8837,poiY=648,wowhead=[[https://www.wowhead.com/wotlk/quest=9321]],image=[[assets/images/quests/placeholder.png]],rewards={{id=22829,qty=1}}}
DB[9322]={id=9322,name=[[Wild Fires in Kalimdor]],name_loc=[[Los fuegos salvajes de Kalimdor]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=3883,poiY=-5380,wowhead=[[https://www.wowhead.com/wotlk/quest=9322]],image=[[assets/images/quests/placeholder.png]],desc=[[The Midsummer Fire Festival is celebrated everywhere in Azeroth, and the diverse land of Kalimdor is no exception. You look fit to travel -- perhaps a journey is in order. Midsummer cannot be truly appreciated unless you've seen the blistering blue fires abroad. The celebrants have lit fires in chilly western Winterspring, northeastern Azshara, near Valor's Rest in the wastes of Silithus, and by the entrance to lush Un'Goro. Return once your journey is complete.]],logDesc=[[Visit the Midsummer camps located in Azshara, Silithus, Un'Goro Crater, and Winterspring, then return to the Festival Flamekeeper.]],rewards={{id=23379,qty=1},{id=23247,qty=10}}}
DB[9323]={id=9323,name=[[Wild Fires in the Eastern Kingdoms]],name_loc=[[Los fuegos salvajes de los Reinos del Este]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-11268,poiY=-3053,wowhead=[[https://www.wowhead.com/wotlk/quest=9323]],image=[[assets/images/quests/placeholder.png]],desc=[[Our celebration of the flame is spread throughout the land, $c. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue. Seek them out. You'll find one just north of Blackrock Spire. The others are located deep within the Eastern Plaguelands near a decrepit town, along the road to the cliffs within the mountainous Hinterlands, and on the way to the Dark Portal within the Blasted Lands.  Return once your journey is done.]],logDesc=[[Visit the Fire Festival camps located in Blasted Lands, Eastern Plaguelands, the Hinterlands and Searing Gorge, then speak with the Festival Flamekeeper.]],rewards={{id=23324,qty=1},{id=23247,qty=10}}}
DB[9324]={id=9324,name=[[Stealing Orgrimmar's Flame]],name_loc=[[Robar la llama de Orgrimmar]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Festival Loremaster]],ender_loc=[[Maestro cultural del Festival]],enderType=[[NPC]],enderId=16817,nextId=9365,exGroup=-9324,poiX=-8833,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=9324]],image=[[assets/images/quests/placeholder.png]],desc=[[This flame, stolen from the heart of Orgrimmar itself, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...]],logDesc=[[Return the Flame of Orgrimmar to the Festival Loremaster.]],rewards={{id=23247,qty=25}},choiceRewards={{id=23435,qty=5},{id=23327,qty=5},{id=23326,qty=5},{id=23211,qty=5},{id=23246,qty=10},{id=34684,qty=10}}}
DB[9325]={id=9325,name=[[Stealing Thunder Bluff's Flame]],name_loc=[[Robar la llama de Cima del Trueno]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Festival Loremaster]],ender_loc=[[Maestro cultural del Festival]],enderType=[[NPC]],enderId=16817,nextId=9365,exGroup=-9324,poiX=-8833,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=9325]],image=[[assets/images/quests/placeholder.png]],desc=[[This flame, stolen from the shaman of Thunder Bluff, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...]],logDesc=[[Return the Flame of Thunder Bluff to the Festival Loremaster.]],rewards={{id=23247,qty=25}},choiceRewards={{id=23435,qty=5},{id=23327,qty=5},{id=23326,qty=5},{id=23211,qty=5},{id=23246,qty=10},{id=34684,qty=10}}}
DB[9326]={id=9326,name=[[Stealing the Undercity's Flame]],name_loc=[[Robar la llama de Entrañas]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Festival Loremaster]],ender_loc=[[Maestro cultural del Festival]],enderType=[[NPC]],enderId=16817,nextId=9365,exGroup=-9324,poiX=-8833,poiY=862,wowhead=[[https://www.wowhead.com/wotlk/quest=9326]],image=[[assets/images/quests/placeholder.png]],desc=[[This flame, stolen from the ruins above the Undercity, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...]],logDesc=[[Return the Flame of the Undercity to the Festival Loremaster.]],rewards={{id=23247,qty=25}},choiceRewards={{id=23435,qty=5},{id=23327,qty=5},{id=23326,qty=5},{id=23211,qty=5},{id=23246,qty=10},{id=34684,qty=10}}}
