DB[9662]={id=9662,zoneId=2562,name=[[Deprecated: Keanna's Freedom]],level=70,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=9662]],image=[[assets/images/quests/placeholder.png]],desc=[[My memories... I remember everything now!  My mind feels like a puzzle falling into place all of a sudden. I was one of the first sent to investigate Karazhan after it changed.  The demon Malchezaar discovered my intrusion. I quickly realized that I was no match for him.  I began to feel my soul become trapped by his magic. At the last moment I hid a fraction of myself... of my memories inside the only place I could think of: my weapon.  Malchezaar has my soul.  You must help me recover it!]],logDesc=[[Defeat Malchezar in Karazhan while equipped with Keanna's Will.  Facet of Keanna must survive.]]}
DB[9664]={id=9664,zoneId=139,name=[[Establishing New Outposts]],name_loc=[[Nuevas avanzadas]],level=60,minLevel=55,giver=[[Emissary Whitebeard]],giver_loc=[[Emisario Barbablanca]],giverType=[[NPC]],giverId=17069,ender=[[Emissary Whitebeard]],ender_loc=[[Emisario Barbablanca]],enderType=[[NPC]],enderId=17069,poiX=1854,poiY=-3723,wowhead=[[https://www.wowhead.com/wotlk/quest=9664]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome to the Plaguelands, $n. As you know, the Forsaken and their allies hold the lands to the west of here against our best efforts. The Alliance commanders have decided that here in the east, we will establish new fortifications to tighten the noose around our enemies. Towers long abandoned since the days of Lordaeron are to be seized and rebuilt for this purpose. These lands are dangerous, and we could use your help.]],logDesc=[[Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Whitebeard at Light's Hope Chapel.]]}
DB[9665]={id=9665,zoneId=139,name=[[Bolstering Our Defenses]],name_loc=[[Fortalecimiento de nuestras defensas]],level=60,minLevel=55,giver=[[Emissary Gormok]],giver_loc=[[Emisario Gormok]],giverType=[[NPC]],giverId=17072,ender=[[Emissary Gormok]],ender_loc=[[Emisario Gormok]],enderType=[[NPC]],enderId=17072,poiX=1854,poiY=-3723,wowhead=[[https://www.wowhead.com/wotlk/quest=9665]],image=[[assets/images/quests/placeholder.png]],desc=[[Agents of the Forsaken uncovered an Alliance plot to establish new bases here in the Eastern Plaguelands, at abandoned towers throughout the area. It is imperative that we not allow them to establish a significant presence on our eastern borders, and so we must stave off this Alliance incursion. Our current plans are to drive them out of any towers they may have already seized, and occupy those that we have under our control against further attacks.]],logDesc=[[Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel.]]}
DB[9695]={id=9695,zoneId=3525,name=[[The Sun King's Command]],name_loc=[[Las órdenes del Rey del Sol]],level=16,minLevel=14,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=9696,poiX=-1960,poiY=-11883,wowhead=[[https://www.wowhead.com/wotlk/quest=9695]],image=[[assets/images/quests/placeholder.png]],desc=[[This document looks to be important. Unfortunately,it is written in Thalassian,a language that you cannot understand. Perhaps Vindicator Boros will know what to do with the letter.]],logDesc=[[Take the Sun King's Command to Vindicator Boros at Blood Watch.]]}
