DB[10549]={id=10549,name=[[REUSE]],name_loc=[[REUSE]],level=18,minLevel=16,giverType=[[NPC]],enderType=[[NPC]],poiX=6701,poiY=-7323,wowhead=[[https://www.wowhead.com/wotlk/quest=10549]],image=[[assets/images/quests/placeholder.png]],desc=[[Remember how I told you about the fat merchant who was looking for that ring?  As it turns out,he had his archeologist son looking for the thing and it didn't turn out so well.  By not so well I mean they killed him and shrunk his head. Now this might seem cold,calculating,and exceptionally callous,but he'd pay a lot to get his son's head back.  Sounds like the perfect job for you! Go east until you find the troll ruins of Zeb'Tela and Zeb'Nowa.  You're bound to find it one of the chests there.]],logDesc=[[Eralan in Tranquillien wants you to retrieve the Archeologist's Shrunken Head from one of the chests in Zeb'Tela or Zeb'Nowa.]],choiceRewards={{id=30504,qty=1},{id=30505,qty=1}}}
DB[10591]={id=10591,name=[[DESTROY THIS QUEST!]],name_loc=[[DESTROY THIS QUEST!]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=10591]],image=[[assets/images/quests/placeholder.png]],rewards={{id=30696,qty=1}}}
DB[10631]={id=10631,zoneId=3483,name=[[Back In Business]],level=61,minLevel=255,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=10631]],image=[[assets/images/quests/placeholder.png]],desc=[[Take my shredder.  Go into the mine and get some ore.]],logDesc=[[Get some ore.]]}
DB[10746]={id=10746,zoneId=1941,name=[[DEPRECATED Karazhan: LAB - E - Exalted Ring - Caster]],level=70,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=10746]],image=[[assets/images/quests/placeholder.png]],desc=[[Your accomplishments have gone beyond my greatest expectations,$N. You step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there. Continue to serve the Scale of the Sands and I will unleash your gift's full potential.]],logDesc=[[Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.]],rewards={{id=29305,qty=1}}}
DB[10999]={id=10999,zoneId=151,name=[[One Shot,One Kill]],name_loc=[[Un disparo, una baja]],level=1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-5822,poiY=-2811,wowhead=[[https://www.wowhead.com/wotlk/quest=10999]],image=[[assets/images/quests/placeholder.png]],desc=[[Bring me 8 trogg stone teeth.]],logDesc=[[Bring me 8 trogg stone teeth.]]}
DB[11087]={id=11087,zoneId=1941,name=[[HYJAL FLAG]],level=70,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11087]],image=[[assets/images/quests/placeholder.png]],desc=[[Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost. With the opening of the Dark Portal,we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal,recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.]],logDesc=[[Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep.]]}
DB[11088]={id=11088,name=[[<DEPRECATED>Unravelling Your Training]],level=70,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11088]],image=[[assets/images/quests/placeholder.png]],desc=[[Bring me a lot of Spellfire cloth,and then you can forget everything.]],logDesc=[[Bring Jonathan LeCraft 10 pieces of Spellfire cloth.]]}
DB[11115]={id=11115,zoneId=3717,name=[[The Mark of Vashj (FLAG ONLY)]],level=70,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11115]],image=[[assets/images/quests/placeholder.png]]}
DB[11116]={id=11116,zoneId=3836,name=[[Trial of the Naaru: (QUEST FLAG)]],level=70,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11116]],image=[[assets/images/quests/placeholder.png]],desc=[[Four trials you must pass before you are deemed worthy of the Tempest key. Only one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter! Do this and you will be granted the Tempest key.]],logDesc=[[A'dal in Shattrath City wants you to slay Magtheridon.]],rewards={{id=31704,qty=1},{id=31746,qty=1}}}
DB[11121]={id=11121,name=[[DAILY TEST QUEST (RAID)]],level=70,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11121]],image=[[assets/images/quests/placeholder.png]],desc=[[<NYI>Seek <QUESTGIVER> in <LOCATION>.  S/he wishes for you to aid them in a difficult task.]],logDesc=[[Speak with <QUESTGIVER> in the <AREA>.]]}
DB[11125]={id=11125,name=[[[PH] New Hinterlands Quest]],name_loc=[[[PH] New Hinterlands Quest]],level=40,minLevel=39,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11125]],image=[[assets/images/quests/placeholder.png]]}
DB[11153]={id=11153,zoneId=495,name=[[Break the Blockade]],level=71,minLevel=68,giver=[[Bombardier Petrov]],giverType=[[NPC]],giverId=23895,ender=[[Bombardier Petrov]],enderType=[[NPC]],enderId=23895,wowhead=[[https://www.wowhead.com/wotlk/quest=11153]],image=[[assets/images/quests/placeholder.png]],desc=[[All of our ships are sunk! We need your help to break the pirate blockade below in the Shattered Straits! Take these cluster bombs and hitch a ride on the zeppelin that Harrowmeiser has 'loaned' to us.  He'll fly you over the decks of those pirate scoundrels, and you make sure to give it to them good! If you can't bomb them to smithereens, I'm afraid we'll never be able to break the blockade.]],logDesc=[[Take Petrov's Cluster Bombs and drop them on enough pirates to kill or destroy 25 Blockade Pirates and 10 Blockade Cannons.  Once you've accomplished that, return to Bombardier Petrov at Westguard Keep.]]}
DB[11154]={id=11154,zoneId=495,name=[[Scare the Guano Out of Them!]],level=71,minLevel=69,giver=[[Engineer Feknut]],giverType=[[NPC]],giverId=24227,ender=[[Engineer Feknut]],enderType=[[NPC]],enderId=24227,wowhead=[[https://www.wowhead.com/wotlk/quest=11154]],image=[[assets/images/quests/placeholder.png]],desc=[[You, yes you... I need your help! Petrov sent me up here to get bat guano for the cluster bombs he's making back at the keep. He sent me to my doom! The darkclaw bats hang out in the Rivenwood to the north, but I'm not taking a step off of this platform unless it's to go home! But you... you could get it for me! Yes? Pretty please?!!! Here, take these firecrackers. My thinking is that if you drop 'em underneath the bats, the guano will be scared right out of them!]],logDesc=[[Collect 10 Darkclaw Guano and deliver them to Engineer Feknut at Steel Gate.]],choiceRewards={{id=35896,qty=1},{id=35898,qty=1},{id=35899,qty=1},{id=35897,qty=1}}}
DB[11155]={id=11155,zoneId=495,name=[[Shoveltusk Soup Again?]],level=71,minLevel=68,giver=[[Chef Kettleblack]],giverType=[[NPC]],giverId=23773,ender=[[Chef Kettleblack]],enderType=[[NPC]],enderId=23773,wowhead=[[https://www.wowhead.com/wotlk/quest=11155]],image=[[assets/images/quests/placeholder.png]],desc=[[With all of the strange disappearances of our livestock, we better resupply in a hurry, or the beasties around these parts will be the least of our worries! Seeing as I'm in charge of feeding this lot, I'm going to need you to head east and get me some meat. More to the point, I'm looking to cook us up some tender shoveltusk meat. Just beware the stags... they're mean!]],logDesc=[[Chef Kettleblack has asked you to obtain 6 Shoveltusk Meat and deliver them to her at Westguard Keep.]],rewards={{id=34125,qty=20}}}
DB[11157]={id=11157,zoneId=495,name=[[The Clutches of Evil]],level=71,minLevel=68,giver=[[Captain Adams]],giverType=[[NPC]],giverId=23749,ender=[[Captain Adams]],enderType=[[NPC]],enderId=23749,wowhead=[[https://www.wowhead.com/wotlk/quest=11157]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I don't trust anyone but you to take care of this.  I need the proto-drake eggs and proto-whelps in the burning forest to the southeast destroyed! Since we arrived here, the Ember Clutch has been ablaze; there must be some sort of perverse magic at work. And lately it seems to be growing. My men tell me that if we don't do something quickly, we'll be surrounded on all sides by the fire within a few weeks' time! Get down there and eliminate the threat by destroying those eggs and the proto-whelps.]],logDesc=[[Destroy 15 Proto-Drake Eggs and 15 Proto-Whelps, and then return to Captain Adams at Westguard Keep.]]}
DB[11167]={id=11167,zoneId=495,name=[[The New Plague]],level=71,minLevel=68,giver=[[Apothecary Lysander]],giverType=[[NPC]],giverId=24126,ender=[[Apothecary Lysander]],enderType=[[NPC]],enderId=24126,rewardNextId=11168,wowhead=[[https://www.wowhead.com/wotlk/quest=11167]],image=[[assets/images/quests/placeholder.png]],desc=[[Not long after Arthas condemned us to this wretched existence, we in the Royal Apothecary Society endeavored to create a plague of our own.  A plague that would devour all flesh: living, dead or undead. We've succeeded in creating this plague and we're here to hand deliver it to the Scourge's doorstep. The Alliance intercepted the ship carrying the latest strain engineered in our Undercity laboratories.  Head to the wreckage southeast of here and salvage whatever containers you can.]],logDesc=[[Apothecary Lysander at Vengeance Landing wants you to recover 10 Intact Plague Containers from the wrecked ship to the southeast.]],choiceRewards={{id=35832,qty=1},{id=35834,qty=1},{id=35835,qty=1},{id=35833,qty=1}}}
DB[11168]={id=11168,zoneId=495,name=[[Spiking the Mix]],level=71,minLevel=68,giver=[[Apothecary Lysander]],giverType=[[NPC]],giverId=24126,ender=[[Apothecary Lysander]],enderType=[[NPC]],enderId=24126,prevId=11167,rewardNextId=11170,wowhead=[[https://www.wowhead.com/wotlk/quest=11168]],image=[[assets/images/quests/placeholder.png]],desc=[[I've a feeling the long trip across the sea is affecting the effectiveness of our plague.  What is needed is a potent toxin to boost the potency of the strain. The crabs near this beach are a distant relative of the much smaller brown-shelled tidecrawler.  The smaller tropical variety produces a paralytic toxin strong enough to knock out an ogre. As we all know bigger is better!  The much larger glands on the local variety should prove more potent.  Bring me a few!]],logDesc=[[Bring 3 Giant Toxin Glands from Giant Tidecrawlers to Apothecary Lysander at Vengeance Landing in Howling Fjord.]]}
DB[11170]={id=11170,zoneId=495,name=[[Test at Sea]],level=71,minLevel=68,giver=[[Apothecary Lysander]],giverType=[[NPC]],giverId=24126,ender=[[Apothecary Lysander]],enderType=[[NPC]],enderId=24126,prevId=11168,wowhead=[[https://www.wowhead.com/wotlk/quest=11170]],image=[[assets/images/quests/placeholder.png]],desc=[[We've just received word of reinforcements coming to the aid of the Alliance forces.  Their timing couldn't be better! We're in sore need of test subjects and these North Fleet reservists will do nicely! Take these plague vials with you and speak to Camille, the Bat Handler.  Tell her you need to commandeer a riding bat for a special assignment for us. Once you're at sea, drop the vials on the reinforcement fleet.  I can't wait to see the results!]],logDesc=[[Speak to Bat Handler Camille and take a riding bat to intercept the Alliance reinforcements.  Once above their fleet, use the Plague Vials to infect 16 North Fleet reservists.]],choiceRewards={{id=35841,qty=1},{id=35842,qty=1},{id=35843,qty=1},{id=35839,qty=1}}}
DB[11175]={id=11175,zoneId=495,name=[[My Daughter]],level=71,minLevel=69,giver=[[Old Man Stonemantle]],giverType=[[NPC]],giverId=23831,ender=[[Overseer Irena Stonemantle]],enderType=[[NPC]],enderId=23891,prevId=11240,wowhead=[[https://www.wowhead.com/wotlk/quest=11175]],image=[[assets/images/quests/placeholder.png]],desc=[[Tell me, is it true? Did the explorers that went into Whisper Gulch go mad? My daughter is the overseer of the Explorers' League that went north to some place called Steel Gate. With the horrible events that have befallen us, I fear for her safety. Please, $c, I am too old to make the journey. Her name is Irena. Will you go make certain that she is alright?]],logDesc=[[Old Man Stonemantle has asked you to find his daughter, Overseer Irena Stonemantle, at Steel Gate.]]}
DB[11176]={id=11176,zoneId=495,name=[[See to the Operations]],level=71,minLevel=69,giver=[[Overseer Irena Stonemantle]],giverType=[[NPC]],giverId=23891,ender=[[Steel Gate Chief Archaeologist]],enderType=[[NPC]],enderId=24399,prevId=11240,rewardNextId=11390,wowhead=[[https://www.wowhead.com/wotlk/quest=11176]],image=[[assets/images/quests/placeholder.png]],desc=[[Our work out here is really just beginning. But now that we've brought these flying machines in from Westguard Keep, it should really pick up. The problem is that we're lacking enough qualified pilots. And with things getting worse in the Rivenwood to the north, I'd like to get things wrapped up here quickly and then head back home. If you can lend a hand, go have a chat with one of my chief archaeologists. You'll find them next to the flying machines on the north and south sides of the site.]],logDesc=[[Explorer Irena Stonemantle has asked you to speak with a Steel Gate Chief Archaeologist at Steel Gate.]]}
DB[11179]={id=11179,zoneId=495,name=[[[Temporarily Deprecated Awaiting a New Mob]Finlay Is Gutless]],level=71,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11179]],image=[[assets/images/quests/placeholder.png]],desc=[[All these crossbowmen, and who is it that has to maintain all of their weapons? Me, Finlay Fletcher! The commander commandeered my assistant to get ready for the move up to Fort Wildervaar, and I haven't the time to go out and get all of the catgut that I need for their strings! $C, be a good $g lad : lass; and gather me up some catgut. The mistsabers prowling about the fjord will do, but mind that you only bring back the most pristine of intestines from them! Severed gut won't do us any good.]],logDesc=[[Collect 7 Pristine Mistsaber Catgut for Finlay Fletcher and return to him at Westguard Keep.]]}
DB[11182]={id=11182,zoneId=495,name=[[Root Causes]],level=71,minLevel=68,giver=[[Ember Clutch Ancient]],giverType=[[NPC]],giverId=23870,ender=[[Ember Clutch Ancient]],enderType=[[NPC]],enderId=23870,wowhead=[[https://www.wowhead.com/wotlk/quest=11182]],image=[[assets/images/quests/placeholder.png]],desc=[[All things in nature seek a balance. It is only through the interference of those not in tune with that harmony that the balance is shifted. You waste your efforts when you kill the whelps and drakes. The real culprits behind the expansion of these magically burning woods are the newly awakened vrykul and their master, Skeld Drakeson. If it's blood on your hands that you seek, start with them. You will find their lair on the south side of the Ember Clutch.]],logDesc=[[Slay 5 Dragonflayer Handlers and Skeld Drakeson.  If you manage to do so, return to an Ember Clutch Ancient in the Ember Clutch.]],choiceRewards={{id=35922,qty=1},{id=35921,qty=1},{id=35923,qty=1},{id=35924,qty=1}}}
DB[11187]={id=11187,zoneId=495,name=[[Mage-Lieutenant Malister]],level=71,minLevel=68,giver=[[Captain Adams]],giverType=[[NPC]],giverId=23749,ender=[[Mage-Lieutenant Malister]],enderType=[[NPC]],enderId=23888,prevId=11157,rewardNextId=11188,wowhead=[[https://www.wowhead.com/wotlk/quest=11187]],image=[[assets/images/quests/placeholder.png]],desc=[[THIS IS OUTRAGEOUS! Those proto-drakes are attacking the keep! Beasts such as that should have been scared off when you took care of their clutches and whelps. You did take care of them, right? $N, this calls for more direct action. Speak with my advisor, Mage-Lieutenant Malister. He'll provide you with the means to get at those infernal creatures.]],logDesc=[[Captain Adams has asked you to speak with his advisor, Mage-Lieutenant Malister, at Westguard Keep.]]}
DB[11188]={id=11188,zoneId=495,name=[[Two Wrongs...]],level=71,minLevel=68,giver=[[Mage-Lieutenant Malister]],giverType=[[NPC]],giverId=23888,ender=[[Mage-Lieutenant Malister]],enderType=[[NPC]],enderId=23888,prevId=11187,wowhead=[[https://www.wowhead.com/wotlk/quest=11188]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we've riled up these Ember Clutch proto-drakes, they may be inclined to continue their attacks upon the keep. This will not do. I hate to compound one wrong with another, but in this case it would appear that we will have to destroy the creatures. A regrettable course of action, but one that we need to undertake regardless. Take my wand. I've been experimenting with increasing its range, but it doesn't pack much of a punch. However, what it will do is get a proto-drake's attention.]],logDesc=[[Mage-Lieutenant Malister at Westguard Keep has tasked you with the destruction of 3 Proto-Drakes.]],choiceRewards={{id=35871,qty=1},{id=35873,qty=1},{id=35875,qty=1},{id=35872,qty=1}}}
DB[11189]={id=11189,zoneId=495,name=[[One Last Time]],level=72,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11189]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello there. Am I dead? I think I am, because I'm hovering over my body! Oh, what an unfortunate turn of events. I was about to propose to Irena when the Scourge descended on us. I know that she's still alive... I can feel her in my heart. $C, do you think you might safely get me to her? The Scourge can still see my ghost, and no doubt can do horrible things to me. I'd like to look upon her beautiful face one last time. You can tell her that I love her for me.]],logDesc=[[Escort the Ghost of Explorer Jaren safely to Explorer Irena Stonemantle at Steel Gate in the Howling Fjord.]]}
DB[11190]={id=11190,zoneId=495,name=[[One Size Does Not Fit All]],level=71,minLevel=68,giver=[[Cannoneer Ely]],giverType=[[NPC]],giverId=23770,ender=[[Cannoneer Ely]],enderType=[[NPC]],enderId=23770,wowhead=[[https://www.wowhead.com/wotlk/quest=11190]],image=[[assets/images/quests/placeholder.png]],desc=[[$G Lad : Lass;, who's the genius that made our cannons a non-standard size? Now we have ta make special cannonballs ta shoot out o' the infernal contraptions! I would look kindly on ye if ye would go out and find the balls we've already shot. No doubt with the way these louts shoot they be all o'er the place ta the south and east. <The cannoneer spaces his hands apart to give you an idea of how big the cannonballs are.> That would be faster than us making 'em from scratch fer a certainty.]],logDesc=[[Cannoneer Ely has tasked you with rounding up 10 Westguard Cannonballs and returning them to him at Westguard Keep.]]}
DB[11197]={id=11197,name=[[ZZOLD Upper Deck Promo - Ghost Wolf Mount OLD]],name_loc=[[ZZOLD Upper Deck Promo - Ghost Wolf Mount OLD]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11197]],image=[[assets/images/quests/placeholder.png]]}
DB[11199]={id=11199,zoneId=495,name=[[Report to Scout Knowles]],level=71,minLevel=68,giver=[[Captain Adams]],giverType=[[NPC]],giverId=23749,ender=[[Scout Knowles]],enderType=[[NPC]],enderId=23906,prevId=11188,rewardNextId=11202,wowhead=[[https://www.wowhead.com/wotlk/quest=11199]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, now that those damnable proto-creatures have been dealt with, I've another task for you. One of my scouts has reported back some suspicious activity by the Forsaken to the south. It looks like they're up to no good at the vrykul village known as Halgrind. I want you to personally take over the investigation down there. Speak with Scout Knowles to find out what he's uncovered and proceed from there. His last reported position is at the Ember Spear Tower, just to the west of Halgrind.]],logDesc=[[Captain Adams has asked you to report to Scout Knowles at the Ember Spear Tower.]]}
DB[11202]={id=11202,zoneId=495,name=[[Mission: Eternal Flame]],level=71,minLevel=68,giver=[[Scout Knowles]],giverType=[[NPC]],giverId=23906,ender=[[Scout Knowles]],enderType=[[NPC]],enderId=23906,prevId=11199,rewardNextId=11327,wowhead=[[https://www.wowhead.com/wotlk/quest=11202]],image=[[assets/images/quests/placeholder.png]],desc=[[The Forsaken are up to no good and from what I can tell, those plague tanks of sludge are a big part of it. If I may suggest, $g sir : ma'am;, we should probably destroy them before they can get any more use out of the things. I took the liberty of preparing a bundle of torches from the Ember Clutch. These things have been burning for days! Here, I'm sure you can put them to better use than I in destroying those tanks.]],logDesc=[[Scout Knowles at the Ember Spear Tower has recommended that you use the Ever-burning Torches to destroy the four Plague Tanks surrounding Halgrind.]],choiceRewards={{id=35889,qty=1},{id=35888,qty=1},{id=35890,qty=1},{id=35891,qty=1}}}
DB[11218]={id=11218,zoneId=495,name=[[Danger! Explosives!]],level=71,minLevel=68,giver=[[Sapper Steelring]],giverType=[[NPC]],giverId=23976,ender=[[Sapper Steelring]],enderType=[[NPC]],enderId=23976,prevId=11188,rewardNextId=11240,wowhead=[[https://www.wowhead.com/wotlk/quest=11218]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, the captain's tasked me with a mission. I'd like you to help. A bunch of my fellow Explorers' League people went nuts digging up stuff in the Whisper Gulch just to the north. They're attacking anyone trying to get in! The captain is only concerned with the ore for the keep. Lucky for us, I have just the thing to do the trick. Get in there, blow up the ore, and bring it back along with any gems you find. Running this place isn't cheap you know! I gotta warn you though, that ore is strange!]],logDesc=[[Use Steelring's Foolproof Dynamite to collect 6 Whisper Gulch Ore Fragments and 18 Whisper Gulch Gems. Then return them to Sapper Steelring at Westguard Keep.]]}
DB[11221]={id=11221,zoneId=495,name=[[Reports from the Field]],level=71,minLevel=68,giver=[[High Executor Anselm]],giverType=[[NPC]],giverId=23780,ender=[[High Executor Anselm]],enderType=[[NPC]],enderId=23780,prevId=11270,rewardNextId=11229,wowhead=[[https://www.wowhead.com/wotlk/quest=11221]],image=[[assets/images/quests/placeholder.png]],desc=[[Our mission in Northrend is to destroy Arthas.  The Alliance are but an obstacle that we'll crush wherever we find them. We've managed to destroy their easternmost fleet; but the survivors have barricaded themselves on the Derelict Strand, south of here. Our forces should've overwhelmed their make-shift defenses long ago, but we underestimated their will to live.  Seek my officers in the field, Dark Ranger Lyana and Deathstalker Razael and get them to report on the situation.]],logDesc=[[Speak to Dark Ranger Lyana and Deathstalker Razael in the battlefield at the Bleeding Vale south of Vengeance Landing.  Return to High Executor Anselm when you've completed this task.]]}
DB[11224]={id=11224,zoneId=495,name=[[Send Them Packing]],level=71,minLevel=68,giver=[[Explorer Abigail]],giverType=[[NPC]],giverId=23978,ender=[[Explorer Abigail]],enderType=[[NPC]],enderId=23978,prevId=11188,wowhead=[[https://www.wowhead.com/wotlk/quest=11224]],image=[[assets/images/quests/placeholder.png]],desc=[[I've heard rumors of bad happenings in the Whisper Gulch to the north. Most of the Explorers' League went down into that place, and some say they went mad with what they discovered. That doesn't change the fact that they took most of our mules and equipment with them, though. I won't lose those mules! If you find yourself in there, and happen across any of my mules, just get up close on them and threaten them with a raised hand. They'll spook and come home for sure.]],logDesc=[[Explorer Abigail has asked you to /raise your hand at 10 Abandoned Pack Mules and then return to her at Westguard Keep.]]}
DB[11226]={id=11226,name=[[Upper Deck Promo - Spectral Tiger Mount]],name_loc=[[Upper Deck Promo - Ghost Wolf Mount]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11226]],image=[[assets/images/quests/placeholder.png]]}
DB[11227]={id=11227,zoneId=495,name=[[Let Them Eat Crow]],level=71,minLevel=68,giver=[[Pontius]],giverType=[[NPC]],giverId=23938,ender=[[Pontius]],enderType=[[NPC]],enderId=23938,rewardNextId=11253,wowhead=[[https://www.wowhead.com/wotlk/quest=11227]],image=[[assets/images/quests/placeholder.png]],desc=[[The high executor wants me to use my dogs to sniff out enemy scouts, but I can tell you right now these plaguehounds aren't going anywhere until they're properly fed. If our military doesn't understand that these beasts are picky enough to not eat the rubbish they've given me, then they can't expect them to be of any use in the field. You seem to have some time on your hands, why don't you take one of these dogs out hunting for crows out west?  Their meat isn't very tasty to us, but my boys love it!]],logDesc=[[Pontius, the kennel keeper at Vengeance Landing, wants you to use the Plaguehound Cage to summon a Hungry Plaguehound and feed it Crow Meat from Fjord Crows west of Vengeance Landing.]]}
DB[11228]={id=11228,zoneId=495,name=[[Hell Has Frozen Over...]],level=70,minLevel=68,giver=[[Macalroy]],giverType=[[NPC]],giverId=23547,ender=[[Vice Admiral Keller]],enderType=[[NPC]],enderId=23546,rewardNextId=11243,wowhead=[[https://www.wowhead.com/wotlk/quest=11228]],image=[[assets/images/quests/placeholder.png]],desc=[[Fordragon's got another thing coming if he thinks the group of green-gilled scrubs he sent to defend this port can hold out much longer. <Macalroy raises an eyebrow as he examines your equipment.> You, however, might fare a bit better. The importance of holding this port cannot be stated enough; and with those monsters flying overhead, the situation around here has gone from bad to worse. Report to Vice Admiral Keller just northwest of here and let him know that you're all out of bubble gum.]],logDesc=[[Speak with Vice Admiral Keller at Valgarde Port.]]}
DB[11229]={id=11229,zoneId=495,name=[[The Windrunner Fleet]],level=71,minLevel=68,giver=[[High Executor Anselm]],giverType=[[NPC]],giverId=23780,ender=[[Captain Harker]],enderType=[[NPC]],enderId=24037,prevId=11221,rewardNextId=11230,wowhead=[[https://www.wowhead.com/wotlk/quest=11229]],image=[[assets/images/quests/placeholder.png]],desc=[[We have the Windrunner, the Queen's Reprisal and the Oblivion stationed just east of the Derelict Strand.  Send orders to the fleet's commander, Captain Harker, that they're to destroy the Alliance's cannons. Speak to our bat handler, Camille, and ask for passage to the fleet's location.  Be quick, $N, every minute we spend fighting the Alliance is a minute we could've spent fighting Arthas.]],logDesc=[[Speak to Bat Handler Camille at Vengeance Landing and obtain passage to the Windrunner.  Report to Captain Harker aboard the ship.]]}
DB[11230]={id=11230,zoneId=495,name=[[Ambushed!]],level=71,minLevel=68,giver=[[Captain Harker]],giverType=[[NPC]],giverId=24037,ender=[[Captain Harker]],enderType=[[NPC]],enderId=24037,prevId=11229,rewardNextId=11232,wowhead=[[https://www.wowhead.com/wotlk/quest=11230]],image=[[assets/images/quests/placeholder.png]],desc=[[This should have been a walk in the park.  Their forces are hungry, injured and ill equipped.  Yet somehow, we walked right into their trap. We approached these reefs from the south to gain cover and were immediately boarded by the Alliance dogs. I'm sorry to say, if you want our cannons to fire at anything, you're going to have to help us take our ships back.]],logDesc=[[Captain Harker aboard the Windrunner wants you to kill 15 North Fleet Marines.]],choiceRewards={{id=35815,qty=1},{id=35814,qty=1},{id=35817,qty=1}}}
DB[11231]={id=11231,zoneId=495,name=[[Of Keys and Cages]],level=71,minLevel=68,giver=[[Father Levariol]],giverType=[[NPC]],giverId=24038,ender=[[Father Levariol]],enderType=[[NPC]],enderId=24038,prevId=11250,rewardNextId=11239,wowhead=[[https://www.wowhead.com/wotlk/quest=11231]],image=[[assets/images/quests/placeholder.png]],desc=[[The captain may not care, but from the little we know, the vrykul are conducting heinous rites in some sort of 'awakening' ritual up north in Gjalerbron. They're using living sacrifices to fuel their unholy rituals! $C, you must put a stop to this! It matters not who or what is in those cages, they must be freed. I'd bet that the vrykul hold the keys. The Light knows the last thing we need is more of those strange vrykul walking about, or worse yet, them wakening something even more evil!]],logDesc=[[Father Levariol has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to him at Westguard Keep when you manage to do so.]]}
DB[11232]={id=11232,zoneId=495,name=[[Guide Our Sights]],level=71,minLevel=68,giver=[[Captain Harker]],giverType=[[NPC]],giverId=24037,ender=[[Dark Ranger Lyana]],enderType=[[NPC]],enderId=23778,prevId=11230,rewardNextId=11233,wowhead=[[https://www.wowhead.com/wotlk/quest=11232]],image=[[assets/images/quests/placeholder.png]],desc=[[We should be able to kill our way back to our guns.  Unfortunately, visibility is less than desirable so you will have to mark our targets from the ground. Take these smoke flares with you and use them to mark the locations of the cannons along the northern wall in the Derelict Strand, west of here, where the Alliance are holding out. Let Lyana know as soon as the way is clear for the ground troops.  We can take care of ourselves over here.]],logDesc=[[Use the Smoke Flares at the location of the Alliance Cannons on the northern wall of the Derelict Strand.  Report to Dark Ranger Lyana at the Bleeding Vale after you've completed this task.]]}
DB[11233]={id=11233,zoneId=495,name=[[Landing the Killing Blow]],level=71,minLevel=68,giver=[[Dark Ranger Lyana]],giverType=[[NPC]],giverId=23778,ender=[[Dark Ranger Lyana]],enderType=[[NPC]],enderId=23778,prevId=11232,rewardNextId=11234,wowhead=[[https://www.wowhead.com/wotlk/quest=11233]],image=[[assets/images/quests/placeholder.png]],desc=[[You've proven yourself in the field of battle, $N.  You might very well have changed the tides in our favor. I've an important assignment for you now.  I'm not sure how much longer the weakness we've exposed is going to last, so we must use the element of surprise to our advantage. I want you to use the confusion created by our attack and go behind enemy lines to assassinate their leaders.  In order of rank, they are: Captain Olster, Lieutenant Celeyne and Sergeant Lorric.  Good luck, $c.]],logDesc=[[Dark Ranger Lyana south of the Vengeance Landing wants you to kill Captain Olster, Lieutenant Celeyne, and Sergeant Lorric at the Derelict Strand.]],choiceRewards={{id=35807,qty=1},{id=35808,qty=1},{id=35812,qty=1},{id=35809,qty=1},{id=35811,qty=1},{id=35810,qty=1}}}
DB[11234]={id=11234,zoneId=495,name=[[Report to Anselm]],level=71,minLevel=68,giver=[[Dark Ranger Lyana]],giverType=[[NPC]],giverId=23778,ender=[[High Executor Anselm]],enderType=[[NPC]],enderId=23780,prevId=11233,wowhead=[[https://www.wowhead.com/wotlk/quest=11234]],image=[[assets/images/quests/placeholder.png]],desc=[[Let's send word back to old Anselm then.  Victory has come later than expected, but better late than never.  Tell him it will take our forces a few hours at most to finish off the stragglers here. Glory to the Banshee Queen!]],logDesc=[[Report back to High Executor Anselm at Vengeance Landing in Howling Fjord.]]}
DB[11235]={id=11235,zoneId=495,name=[[Dealing With Gjalerbron]],level=71,minLevel=68,giver=[[Captain Adams]],giverType=[[NPC]],giverId=23749,ender=[[Captain Adams]],enderType=[[NPC]],enderId=23749,prevId=11250,rewardNextId=11236,wowhead=[[https://www.wowhead.com/wotlk/quest=11235]],image=[[assets/images/quests/placeholder.png]],desc=[[And now we have a different problem. My scouts that have lived to return have informed me that the vrykul are up to no good at their main fortress to the north. They call the place Gjalerbron, though you'd pronounce the 'Gj' as if it were an 'Sh'. Odd creatures. But that's not important; what is, is that you get up there and put an end to the lives of as many of those creatures as you can while trying to figure out what they're up to. I know that I can count on you, $N.]],logDesc=[[Captain Adams has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Westguard Keep.]]}
DB[11236]={id=11236,zoneId=495,name=[[Necro Overlord Mezhen]],level=72,minLevel=68,giver=[[Captain Adams]],giverType=[[NPC]],giverId=23749,ender=[[Captain Adams]],enderType=[[NPC]],enderId=23749,prevId=11235,wowhead=[[https://www.wowhead.com/wotlk/quest=11236]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge are at Gjalerbron and they have necromancers with them! They must be working to bring the vrykul into Arthas' fold. I want the leader of these necrolords eliminated! Do whatever it takes, $N, but see to it that Necro Overlord Mezhen, and whatever he's attempting to accomplish, is neutralized. I will not see the vrykul successfully allied with the Scourge! Look for Mezhen on the platform in the rear right section of Gjalerbron.]],logDesc=[[Kill Necro Overlord Mezhen. Then, return to Captain Adams at Westguard Keep.]],choiceRewards={{id=35938,qty=1},{id=35878,qty=1},{id=35879,qty=1},{id=35877,qty=1}}}
DB[11237]={id=11237,zoneId=495,name=[[Gjalerbron Attack Plans]],level=72,minLevel=68,giverType=[[NPC]],ender=[[Mage-Lieutenant Malister]],enderType=[[NPC]],enderId=23888,prevId=11250,rewardNextId=11238,wowhead=[[https://www.wowhead.com/wotlk/quest=11237]],image=[[assets/images/quests/placeholder.png]],desc=[[These plans detail an imminent attack upon Westguard Keep. It would appear that the frost wyrm, Glacion, who circles overhead is to be used for the offensive. Surely Mage-Lieutenant Malister would be of some assistance in this matter. Deliver the plans to him at the keep to the south.]],logDesc=[[Deliver the Gjalerbron Attack Plans to Mage-Lieutenant Malister at Westguard Keep.]]}
DB[11238]={id=11238,zoneId=495,name=[[The Frost Wyrm and its Master]],level=72,minLevel=68,giver=[[Mage-Lieutenant Malister]],giverType=[[NPC]],giverId=23888,ender=[[Mage-Lieutenant Malister]],enderType=[[NPC]],enderId=23888,prevId=11237,wowhead=[[https://www.wowhead.com/wotlk/quest=11238]],image=[[assets/images/quests/placeholder.png]],desc=[[You were right to bring this to me, $N. You must take help back north with you to Gjalerbron and slay that wyrm and its master, Wyrmcaller Vile! Even now, as we speak here, the frost wyrm may be on its way. However, if I'm reading these plans correctly, blowing the wyrmcaller's horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it! And $N, please bring me the horn. We wouldn't want it falling back into the wrong hands.]],logDesc=[[Slay Wyrmcaller Vile and use the Wyrmcaller's Horn to call down and slay Glacion. Then, return with the horn to Mage-Lieutenant Malister at Westguard Keep.]],choiceRewards={{id=35880,qty=1},{id=35882,qty=1},{id=35883,qty=1},{id=35881,qty=1}}}
DB[11239]={id=11239,zoneId=495,name=[[In Service to the Light]],level=71,minLevel=68,giver=[[Father Levariol]],giverType=[[NPC]],giverId=24038,ender=[[Father Levariol]],enderType=[[NPC]],enderId=24038,prevId=11231,wowhead=[[https://www.wowhead.com/wotlk/quest=11239]],image=[[assets/images/quests/placeholder.png]],desc=[[Your service has been exemplary, $N, but there is something that is troubling me: the Scourge. The Light cannot abide their presence, and neither shall we. I hope that it is not asking you too much, but I would have you return north to Gjalerbron and crush the unholy Scourge in that vile lair! Be sure to check for them in the Waking Halls beneath Gjalerbron as well. Purification is the key to salvation, my child. Make us proud!]],logDesc=[[Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Father Levariol at Westguard Keep of your success.]],choiceRewards={{id=35884,qty=1},{id=35887,qty=1},{id=35885,qty=1},{id=35886,qty=1}}}
DB[11240]={id=11240,zoneId=495,name=[[Leader of the Deranged]],level=71,minLevel=68,giver=[[Sapper Steelring]],giverType=[[NPC]],giverId=23976,ender=[[Sapper Steelring]],enderType=[[NPC]],enderId=23976,prevId=11218,wowhead=[[https://www.wowhead.com/wotlk/quest=11240]],image=[[assets/images/quests/placeholder.png]],desc=[[So, I hate to say it, pal, but while you were out, the captain took a keener interest in that place. Looks like he wants my old Explorers' League boss in there dead. My guess would be that we're gearing up for an offensive to clear out the rest of them, and the captain wants their head lopped off, as it were. Do me a favor? Head back into Whisper Gulch and put an end to Squeeg Idolhunter. From what I remember, my guess would be that he's in the cave in the northwest corner.]],logDesc=[[Slay Squeeg Idolhunter and then report back to Sapper Steelring at Westguard Keep.]],choiceRewards={{id=35917,qty=1},{id=35919,qty=1},{id=35920,qty=1},{id=35918,qty=1}}}
DB[11241]={id=11241,zoneId=495,name=[[Trail of Fire]],level=71,minLevel=68,giver=[[Apothecary Hanes]],giverType=[[NPC]],giverId=23784,ender=[[Apothecary Lysander]],enderType=[[NPC]],enderId=24126,wowhead=[[https://www.wowhead.com/wotlk/quest=11241]],image=[[assets/images/quests/placeholder.png]],desc=[[Thanks for bailing me out of this mess, $N.  I was not looking forward to what these Alliance scumbags had in store for me. Let's get out of here and see if we can get back at them somehow.  Is that a campfire over there?]],logDesc=[[Escort Apothecary Hanes out of the Derelict Strand.  Report to Apothecary Lysander at Vengeance Landing in Howling Fjord when you've completed this task.]],choiceRewards={{id=35829,qty=1},{id=35827,qty=1},{id=35830,qty=1},{id=35826,qty=1},{id=35823,qty=1},{id=35824,qty=1}}}
DB[11243]={id=11243,zoneId=495,name=[[If Valgarde Falls...]],level=70,minLevel=68,giver=[[Vice Admiral Keller]],giverType=[[NPC]],giverId=23546,ender=[[Vice Admiral Keller]],enderType=[[NPC]],enderId=23546,prevId=11228,rewardNextId=11244,wowhead=[[https://www.wowhead.com/wotlk/quest=11243]],image=[[assets/images/quests/placeholder.png]],desc=[[If Valgarde falls, our primary supply line into Northrend will cease to exist. From there it'll only be a matter of time before we're all servants of the Lich King. Now I don't know about you, but I've got a wife and three kids back in Elwynn and I'll be damned if I'll go down without a fight. The situation here is critical and we can use all the manpower you're able to muster. Get to the front gate and help the guards defend the city against the invading monsters!]],logDesc=[[Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to slay 12 Dragonflayer Invaders or Dragonflayer Worgs. ]]}
DB[11244]={id=11244,zoneId=495,name=[[Rescuing the Rescuers]],level=70,minLevel=68,giver=[[Vice Admiral Keller]],giverType=[[NPC]],giverId=23546,ender=[[Vice Admiral Keller]],enderType=[[NPC]],enderId=23546,prevId=11243,rewardNextId=11255,wowhead=[[https://www.wowhead.com/wotlk/quest=11244]],image=[[assets/images/quests/placeholder.png]],desc=[[We'd been here for a month when those malformed giants appeared out of thin air. We were ill-prepared for any sort of attack and paid dearly for our complacency. An entire archaeology team was lost and several townsfolk were abducted and taken to the ruins. We've been on the defensive ever since. To make matters worse, the scouts we sent to rescue our people have been harpooned by the vrykul and left for dead in the forest directly north of Valgarde. Dislodge those harpoons and free our scouts! ]],logDesc=[[Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 8 Valgarde Scouts that have been impaled and left for dead.]],choiceRewards={{id=35809,qty=1},{id=35811,qty=1},{id=35810,qty=1},{id=35807,qty=1},{id=35808,qty=1},{id=35812,qty=1}}}
DB[11245]={id=11245,zoneId=495,name=[[Towers of Certain Doom]],level=71,minLevel=68,giver=[[Westguard Sergeant]],giverType=[[NPC]],giverId=24060,ender=[[Westguard Sergeant]],enderType=[[NPC]],enderId=24060,prevId=11248,nextId=11250,exGroup=-11245,wowhead=[[https://www.wowhead.com/wotlk/quest=11245]],image=[[assets/images/quests/placeholder.png]],desc=[[$G Sir : Ma'am;, as we move through Skorn, we have to bring down those towers! If you have a look at them, you'll notice that their tops are lined with casters. Getting too close to them would mean certain doom for us! However, we do have it within our means to call in cannon volleys from Westguard Keep. To do so, we need to get close enough so that you can lob a smoke flare atop of them. Just don't get too close!]],logDesc=[[The Westguard Sergeant has informed you that using the Sergeant's Flare to target all four of the towers at Skorn for cannon volleys would be advisable.]]}
DB[11246]={id=11246,zoneId=495,name=[[Gruesome, But Necessary]],level=71,minLevel=68,giver=[[Westguard Sergeant]],giverType=[[NPC]],giverId=24060,ender=[[Westguard Sergeant]],enderType=[[NPC]],enderId=24060,prevId=11248,nextId=11250,exGroup=-11245,wowhead=[[https://www.wowhead.com/wotlk/quest=11246]],image=[[assets/images/quests/placeholder.png]],desc=[[We've had reports that these vrykul can rise from the dead; not unlike the Scourge, but a different kind of undeath. Let's not take any chances. Here, take my machete. As we move through this place, you'll need to carve up the remains of the vrykul that we take down. I'd do it, but I have a sensitive stomach. <The sergeant smirks.> I spent all morning sharpening it, so it should do the job.]],logDesc=[[The Westguard Sergeant has asked you to use The Sergeant's Machete to dismember 20 Vrykul of the Winterskorn tribe at Skorn.]]}
DB[11247]={id=11247,zoneId=495,name=[[Burn Skorn, Burn!]],level=71,minLevel=68,giver=[[Westguard Sergeant]],giverType=[[NPC]],giverId=24060,ender=[[Westguard Sergeant]],enderType=[[NPC]],enderId=24060,prevId=11248,nextId=11250,exGroup=-11245,wowhead=[[https://www.wowhead.com/wotlk/quest=11247]],image=[[assets/images/quests/placeholder.png]],desc=[[Captain Adams gave me strict instructions to make sure that a good deal of infrastructure damage was inflicted on this site. However, since you're in charge out here, that's at your discretion, $g sir : ma'am;. May I suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn? All we have to do is get inside each and throw this torch.]],logDesc=[[The Westguard Sergeant has orders that you should use the Sergeant's Torch to set fire to the Northeast and Northwest Longhouses and the Barracks at Skorn.]]}
DB[11248]={id=11248,zoneId=495,name=[[Operation: Skornful Wrath]],level=71,minLevel=68,giver=[[Captain Adams]],giverType=[[NPC]],giverId=23749,ender=[[Westguard Sergeant]],enderType=[[NPC]],enderId=24060,prevId=11332,wowhead=[[https://www.wowhead.com/wotlk/quest=11248]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, I must now ask you to undertake an operation so hazardous, so deadly, that only you can see it through. The vrykul fortress, Skorn, sits on our eastern border. My scouts inform me that those 'giants' are poised to strike us, and with my forces scattered all over the fjord, I don't have the men to take the place by force. Instead, you're going to use your cunning. I've sent a sergeant ahead with the details. Show this command insignia at Skorn and he'll reveal himself and follow your orders.]],logDesc=[[Captain Adams has asked you to use the Westguard Command Insignia at Skorn, and then to speak with the Westguard Sergeant.]]}
DB[11249]={id=11249,zoneId=495,name=[[Stop the Ascension!]],level=72,minLevel=68,giverType=[[NPC]],ender=[[Father Levariol]],enderType=[[NPC]],enderId=24038,prevId=11248,wowhead=[[https://www.wowhead.com/wotlk/quest=11249]],image=[[assets/images/quests/placeholder.png]],desc=[[This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual. A vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture's background. A tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.]],logDesc=[[Present the Vrykul Scroll of Ascension near the Thane's Pyre to call him out and slay him. Afterward, due to the nature of the ritual, you're sure that Father Levariol at Westguard Keep will be interested in seeing the scroll.]],choiceRewards={{id=35900,qty=1},{id=35902,qty=1},{id=35903,qty=1},{id=35901,qty=1}}}
DB[11250]={id=11250,zoneId=495,name=[[All Hail the Conqueror of Skorn!]],level=72,minLevel=68,giver=[[Westguard Sergeant]],giverType=[[NPC]],giverId=24060,ender=[[Captain Adams]],enderType=[[NPC]],enderId=23749,wowhead=[[https://www.wowhead.com/wotlk/quest=11250]],image=[[assets/images/quests/placeholder.png]],desc=[[We -- well, you -- have done everything that we were sent here to accomplish $g sir : ma'am;. I must say that it's been a pleasure taking orders from such a fine, young $r. The captain is sure to want to hear of your success, but if you decide to stay out here for whatever reason, I am at your disposal.]],logDesc=[[Return the Westguard Command Insignia to Captain Adams at Westguard Keep.]],choiceRewards={{id=35909,qty=1},{id=35910,qty=1},{id=35904,qty=1},{id=35905,qty=1}}}
DB[11251]={id=11251,zoneId=495,name=[[Fresh Legs]],level=71,minLevel=68,giver=[[Scout Valory]],giverType=[[NPC]],giverId=24106,ender=[[Defender Mordun]],enderType=[[NPC]],enderId=24111,prevId=11244,rewardNextId=11252,wowhead=[[https://www.wowhead.com/wotlk/quest=11251]],image=[[assets/images/quests/placeholder.png]],desc=[[It's come at great cost, but we've completed our inspection of the site. The news isn't good. Nearly everyone has been slain or captured. Only a few veteran guards remain unaccounted for. The scouts have done all we can here. You must pick up where we've left off. Sounds of a skirmish are coming from up the hill to the northeast. Have a look, $c. We can only hope there are some who have survived, and that they may have some intel we can use against this enemy.]],logDesc=[[Scout Valory wants you to investigate the sounds of battle coming from the northeast of Wyrmskull Village.]]}
DB[11252]={id=11252,zoneId=206,name=[[Into Utgarde!]],level=71,minLevel=68,giver=[[Defender Mordun]],giverType=[[NPC]],giverId=24111,ender=[[Vice Admiral Keller]],enderType=[[NPC]],enderId=23546,prevId=11244,wowhead=[[https://www.wowhead.com/wotlk/quest=11252]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen up, youngster. I've put down me share of these creatures - and your share too fer that matter. Here be what ya need to know.... The vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we're doomed - plain and simple. There's one they esteem though, goes by the name of Ingvar. I dunno why they be seekin' his praise, but bring him down and you'll deal a mighty blow to their spirit. Then, perhaps, we'll have a chance....]],logDesc=[[Defender Mordun has tasked you with the execution of Ingvar the Plunderer who resides deep in Utgarde. You are then to bring his head to Vice Admiral Keller.]],choiceRewards={{id=38218,qty=1},{id=38219,qty=1},{id=38220,qty=1}}}
DB[11253]={id=11253,zoneId=495,name=[[Sniff Out the Enemy]],level=71,minLevel=68,giver=[[Pontius]],giverType=[[NPC]],giverId=23938,enderType=[[NPC]],prevId=11227,rewardNextId=11254,wowhead=[[https://www.wowhead.com/wotlk/quest=11253]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that this rascal's belly's full, maybe he will be more willing to cooperate.  Here's his leash, just come get him from his cage whenever you're ready to take him. I don't know what Anselm expects you to find, but look for clues wherever it is that the dog takes you.]],logDesc=[[Use the Plaguehound Leash near the plaguehound cages at Vengeance Landing and look for clues at the location you're led to by the Plaguehound Tracker.]]}
DB[11254]={id=11254,zoneId=495,name=[[The Dragonskin Map]],level=71,minLevel=68,giverType=[[NPC]],ender=[[High Executor Anselm]],enderType=[[NPC]],enderId=23780,prevId=11253,rewardNextId=11295,wowhead=[[https://www.wowhead.com/wotlk/quest=11254]],image=[[assets/images/quests/placeholder.png]],desc=[[Upon closer inspection, the scroll appears to be a heavily-illustrated map of the fjord.  The location of various villages are depicted in what seem to be tribal symbols. The location of Vengeance Landing is marked with a disproportionately large skull. This map will almost certainly be of military value to High Executor Anselm.]],logDesc=[[Bring the Dragonskin Map to High Executor Anselm in Vengeance Landing.]]}
DB[11255]={id=11255,zoneId=495,name=[[Prisoners of Wyrmskull]],level=70,minLevel=68,giver=[[Vice Admiral Keller]],giverType=[[NPC]],giverId=23546,ender=[[Vice Admiral Keller]],enderType=[[NPC]],enderId=23546,prevId=11244,rewardNextId=11290,wowhead=[[https://www.wowhead.com/wotlk/quest=11255]],image=[[assets/images/quests/placeholder.png]],desc=[[This battle is far from over, $N. If our people are still alive inside that village, someone has to go and get 'em. <Vice Admiral Keller nods at you.> Head north and enter Wyrmskull Village. Once there, look for our people. If they are imprisoned you'll need to find a way to break them out. Maybe they'll have some more information about what it is that we're actually fighting.]],logDesc=[[Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 3 Captured Valgarde Prisoners.]]}
DB[11256]={id=11256,zoneId=495,name=[[Skorn Must Fall!]],level=71,minLevel=68,giver=[[Chieftain Ashtotem]],giverType=[[NPC]],giverId=24129,ender=[[Winterhoof Brave]],enderType=[[NPC]],enderId=24130,prevId=11281,wowhead=[[https://www.wowhead.com/wotlk/quest=11256]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, the vrykul fortress, Skorn, sits to the south. Its strange giants have recently awakened and have begun to spread, attacking us wherever they can. My scouts inform me that they are poised to strike at us here, but I do not have the strength to repel such a force. Instead, we will prepare to leave north to less dangerous lands. I ask that you use your cunning to buy us time. I've sent a brave ahead with the details. Show this emblem at Skorn and he'll reveal himself and do all he can to aid you.]],logDesc=[[Chieftain Ashtotem has asked you to use the Winterhoof Emblem at Skorn, and then to speak with the Winterhoof Brave.]]}
DB[11257]={id=11257,zoneId=495,name=[[Gruesome, But Necessary]],level=71,minLevel=68,giver=[[Winterhoof Brave]],giverType=[[NPC]],giverId=24130,ender=[[Winterhoof Brave]],enderType=[[NPC]],enderId=24130,prevId=11256,nextId=11261,rewardNextId=11261,exGroup=-11257,wowhead=[[https://www.wowhead.com/wotlk/quest=11257]],image=[[assets/images/quests/placeholder.png]],desc=[[Our elders say that these vrykul may be able to rise from the dead; not unlike the walking dead you call the Scourge, but a different kind of undeath. We should not take any chances. Here, take my machete. As we move through this place, carve up the remains of the vrykul that we slay. I spent the morning sharpening it, so it should cleave even through their thick bones.]],logDesc=[[The Winterhoof Brave has asked you to use The Brave's Machete to dismember 20 Vrykul of the Winterskorn tribe at Skorn.]]}
DB[11258]={id=11258,zoneId=495,name=[[Burn Skorn, Burn!]],level=71,minLevel=68,giver=[[Winterhoof Brave]],giverType=[[NPC]],giverId=24130,ender=[[Winterhoof Brave]],enderType=[[NPC]],enderId=24130,prevId=11256,nextId=11261,rewardNextId=11261,exGroup=-11257,wowhead=[[https://www.wowhead.com/wotlk/quest=11258]],image=[[assets/images/quests/placeholder.png]],desc=[[Chieftain Ashtotem ordered me to destroy many buildings here. However, you are in charge, so it falls to your hands, $N. I suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn. All we have to do is get inside each and set them ablaze with this torch.]],logDesc=[[The Winterhoof Brave suggests that you use the Brave's Torch to set fire to the Northeast and Northwest Longhouses and the Barracks at Skorn.]]}
DB[11259]={id=11259,zoneId=495,name=[[Towers of Certain Doom]],level=71,minLevel=68,giver=[[Winterhoof Brave]],giverType=[[NPC]],giverId=24130,ender=[[Winterhoof Brave]],enderType=[[NPC]],enderId=24130,prevId=11256,nextId=11261,rewardNextId=11261,exGroup=-11257,wowhead=[[https://www.wowhead.com/wotlk/quest=11259]],image=[[assets/images/quests/placeholder.png]],desc=[[As we move through Skorn, we must destroy the towers. If you have a look at them, you'll notice that their tops are lined with casters. Getting too close to them would mean certain doom. However, we can call in wind rider air strikes from Camp Winterhoof. To do so, we need to get close enough so that you can lob a smoke flare atop of them. Just don't get too close.]],logDesc=[[The Winterhoof Brave has informed you that using the Brave's Flare to target all four of the towers at Skorn for air strikes would be advisable.]]}
DB[11260]={id=11260,zoneId=495,name=[[Stop the Ascension!]],level=72,minLevel=68,giverType=[[NPC]],ender=[[Greatmother Ankha]],enderType=[[NPC]],enderId=24135,prevId=11256,wowhead=[[https://www.wowhead.com/wotlk/quest=11260]],image=[[assets/images/quests/placeholder.png]],desc=[[This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual. A vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture's background. A tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.]],logDesc=[[Present the Vrykul Scroll of Ascension near the Thane's Pyre to call him out and slay him. Afterward, due to the nature of the ritual, you're sure that Greatmother Ankha at Camp Winterhoof will be interested in seeing the scroll.]],choiceRewards={{id=35900,qty=1},{id=35902,qty=1},{id=35903,qty=1},{id=35901,qty=1}}}
DB[11261]={id=11261,zoneId=495,name=[[The Conqueror of Skorn!]],level=72,minLevel=68,giver=[[Winterhoof Brave]],giverType=[[NPC]],giverId=24130,ender=[[Chieftain Ashtotem]],enderType=[[NPC]],enderId=24129,rewardNextId=11263,wowhead=[[https://www.wowhead.com/wotlk/quest=11261]],image=[[assets/images/quests/placeholder.png]],desc=[[You have done everything that we were sent here to do, $c. I must admit that you fight well. Your people are not as strange as I first thought. Chieftain Ashtotem is certain to want to hear of your success, but if you decide to stay out here for whatever reason, I will continue to fight at your side.]],logDesc=[[Return the Winterhoof Token to Chieftain Ashtotem at Camp Winterhoof.]],choiceRewards={{id=35909,qty=1},{id=35910,qty=1},{id=35904,qty=1},{id=35905,qty=1}}}
DB[11262]={id=11262,zoneId=206,name=[[Ingvar Must Die!]],level=71,minLevel=68,giver=[[Dark Ranger Marrah]],giverType=[[NPC]],giverId=24137,ender=[[High Executor Anselm]],enderType=[[NPC]],enderId=23780,wowhead=[[https://www.wowhead.com/wotlk/quest=11262]],image=[[assets/images/quests/placeholder.png]],desc=[[Finally, someone's come. I've been here far too long and my wits are beginning to fail me. Of our entire recon party, only I remain. I shall give you my report and it will be up to you to act upon the information. Know this, $c; it did not come cheaply. These vrykul are relentless fighters. Given their numbers and their savage tactics, our only hope is to bring down their leader and pray it brings chaos to their ranks. Ingvar is his name. Bring his head to Anselm when your duty is done.]],logDesc=[[Dark Ranger Marrah has asked you to kill Ingvar the Plunderer in Utgarde Keep, then bring his head to High Executor Anselm at Vengeance Landing.]],choiceRewards={{id=38218,qty=1},{id=38219,qty=1},{id=38220,qty=1}}}
DB[11263]={id=11263,zoneId=495,name=[[Dealing With Gjalerbron]],level=71,minLevel=68,giver=[[Chieftain Ashtotem]],giverType=[[NPC]],giverId=24129,ender=[[Chieftain Ashtotem]],enderType=[[NPC]],enderId=24129,prevId=11261,rewardNextId=11264,wowhead=[[https://www.wowhead.com/wotlk/quest=11263]],image=[[assets/images/quests/placeholder.png]],desc=[[My longrunners that have lived to return have informed me that the vrykul have awakened at their main fortress to the west. It is a forbidden place known as Gjalerbron. The longrunners tell me that the vrykul are performing strange rituals. We cannot allow this to continue. Are you willing to continue to assist us? Will you kill the vrykul at Gjalerbron before they finish whatever they are doing and attack us here?]],logDesc=[[Chieftain Ashtotem has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Camp Winterhoof.]]}
DB[11264]={id=11264,zoneId=495,name=[[Necro Overlord Mezhen]],level=72,minLevel=68,giver=[[Chieftain Ashtotem]],giverType=[[NPC]],giverId=24129,ender=[[Chieftain Ashtotem]],enderType=[[NPC]],enderId=24129,prevId=11263,wowhead=[[https://www.wowhead.com/wotlk/quest=11264]],image=[[assets/images/quests/placeholder.png]],desc=[[The dead ones are at Gjalerbron and they have necromancers with them? We must eliminate the leader of these necrolords. Do whatever it takes, $N, but see to it that Necro Overlord Mezhen, and whatever he's attempting to accomplish, is neutralized. We cannot afford to see the vrykul successful in whatever they are doing with these undead creatures! Look for Mezhen on the platform in the rear right section of Gjalerbron.]],logDesc=[[Kill Necro Overlord Mezhen. Then, return to Chieftain Ashtotem at Camp Winterhoof.]],choiceRewards={{id=35938,qty=1},{id=35878,qty=1},{id=35879,qty=1},{id=35877,qty=1}}}
DB[11265]={id=11265,zoneId=495,name=[[Of Keys and Cages]],level=71,minLevel=68,giver=[[Greatmother Ankha]],giverType=[[NPC]],giverId=24135,ender=[[Greatmother Ankha]],enderType=[[NPC]],enderId=24135,prevId=11261,rewardNextId=11268,wowhead=[[https://www.wowhead.com/wotlk/quest=11265]],image=[[assets/images/quests/placeholder.png]],desc=[[From the little we know, the vrykul are conducting unnatural rites in an 'awakening' ritual to the west in Gjalerbron. They're using living sacrifices to fuel their rituals. $N, you must stop this. It matters not who or what is in those cages, they must be freed. I would guess that the vrykul hold the keys. The last thing we need is more of those strange vrykul threatening us, or worse, them wakening something even more evil....]],logDesc=[[Greatmother Ankha has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to her at Camp Winterhoof when you manage to do so.]]}
DB[11266]={id=11266,zoneId=495,name=[[Gjalerbron Attack Plans]],level=72,minLevel=68,giverType=[[NPC]],ender=[[Celea Frozenmane]],enderType=[[NPC]],enderId=24032,prevId=11261,rewardNextId=11267,wowhead=[[https://www.wowhead.com/wotlk/quest=11266]],image=[[assets/images/quests/placeholder.png]],desc=[[These plans detail an imminent attack upon Camp Winterhoof. It would appear that the frost wyrm, Glacion, who circles overhead, is to be used for the offensive. Surely Celea Frozenmane would be of some assistance in this matter. Deliver the plans to her at the camp to the east.]],logDesc=[[Deliver the Gjalerbron Attack Plans to Celea Frozenmane at Camp Winterhoof.]]}
DB[11267]={id=11267,zoneId=495,name=[[The Frost Wyrm and its Master]],level=72,minLevel=68,giver=[[Celea Frozenmane]],giverType=[[NPC]],giverId=24032,ender=[[Celea Frozenmane]],enderType=[[NPC]],enderId=24032,prevId=11266,wowhead=[[https://www.wowhead.com/wotlk/quest=11267]],image=[[assets/images/quests/placeholder.png]],desc=[[Your instincts were right to bring this to me, but my wind riders cannot fight a dragon. You must take help back west with you to Gjalerbron and slay the frost wyrm and its master, Wyrmcaller Vile! Even now it may be on its way! If I'm reading these plans correctly, blowing the wyrmcaller's horn on his platform, outside in the rear left area of Gjalerbron, will  call Glacion back. When the creature lands, destroy it! And $N, bring me the horn. We wouldn't want it falling back into the wrong hands!]],logDesc=[[Slay Wyrmcaller Vile and use the Wyrmcaller's Horn to call down and slay Glacion. Then, return with the horn to Celea Frozenmane at Camp Winterhoof.]],choiceRewards={{id=35880,qty=1},{id=35882,qty=1},{id=35883,qty=1},{id=35881,qty=1}}}
DB[11268]={id=11268,zoneId=495,name=[[The Walking Dead]],level=71,minLevel=68,giver=[[Greatmother Ankha]],giverType=[[NPC]],giverId=24135,ender=[[Greatmother Ankha]],enderType=[[NPC]],enderId=24135,prevId=11265,wowhead=[[https://www.wowhead.com/wotlk/quest=11268]],image=[[assets/images/quests/placeholder.png]],desc=[[Your assistance to us has been tremendous, $N, but there is something that is troubling me: these so-called Scourge. The spirits of the land and air, the waters and the fire below the world, would not abide their presence, but seem to do nothing about them. We will see to it that they are dealt with! Perhaps it is asking too much, but I would have you return west to Gjalerbron and destroy the unnatural Scourge in that vile lair. Be sure to check in the Waking Halls below Gjalerbron as well!]],logDesc=[[Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Greatmother Ankha at Camp Winterhoof of your success.]],choiceRewards={{id=35884,qty=1},{id=35887,qty=1},{id=35885,qty=1},{id=35886,qty=1}}}
DB[11269]={id=11269,zoneId=495,name=[[Down to the Wire]],level=71,minLevel=69,giver=[[Gil Grisert]],giverType=[[NPC]],giverId=24139,ender=[[Gil Grisert]],enderType=[[NPC]],enderId=24139,prevId=11250,rewardNextId=11418,wowhead=[[https://www.wowhead.com/wotlk/quest=11269]],image=[[assets/images/quests/placeholder.png]],desc=[[The vanguard of the Alliance force will be arriving within days. The soldiers will be expecting their winter gear to be prepared, but I've still got more cloaks to make. I've been using spotted hippogryph down for the cloaks' linings, but my stock won't last! You've got to help me, $N. Captain Adams will have my hide if those cloaks aren't ready in time! Bring me all the down you can find out there. It's dropped to the ground by molting hippogryphs flying over the wilderness around the fort.]],logDesc=[[Gil Grisert wants you to bring him 10 clumps of Spotted Hippogryph Down.]],choiceRewards={{id=35926,qty=1},{id=35927,qty=1},{id=35928,qty=1},{id=35925,qty=1}}}
DB[11270]={id=11270,zoneId=495,name=[[War is Hell]],level=71,minLevel=68,giver=[[High Executor Anselm]],giverType=[[NPC]],giverId=23780,ender=[[High Executor Anselm]],enderType=[[NPC]],enderId=23780,rewardNextId=11221,wowhead=[[https://www.wowhead.com/wotlk/quest=11270]],image=[[assets/images/quests/placeholder.png]],desc=[[We're slowly finishing off the remnants of Stormwind's North Fleet stationed on this coast.  The bodies to the west are a testament to how brutal this confrontation has been. This does not happen to bother my refined aesthetics, but it does present a danger to our lives. In the lands of the Lich King, the dead are a weapon that can rise against us at any point in time.  Take this torch - you're going to make sure that doesn't happen.]],logDesc=[[High Executor Anselm at Vengeance Landing wants you to take the Burning Torch and use it to burn 10 of the corpses littered to the west of town.]]}
DB[11271]={id=11271,zoneId=495,name=[[Hasty Preparations]],level=71,minLevel=69,giver=[[Ahota Whitefrost]],giverType=[[NPC]],giverId=24127,ender=[[Ahota Whitefrost]],enderType=[[NPC]],enderId=24127,wowhead=[[https://www.wowhead.com/wotlk/quest=11271]],image=[[assets/images/quests/placeholder.png]],desc=[[The down of the spotted hippogryph is prized by my people and used for everything from fletching to ceremonial clothing. We're making preparations to leave the post, so this is the last chance I'll get to gather it this season. With your help, I'll have enough to make sure everyone has the equipment they need for the long trek into the hills. Conditions worsen very quickly up there and a storm can blow in without warning. The down can be found all over the ground in the area surrounding the post.]],logDesc=[[Ahota Whitefrost at Camp Winterhoof wants you to bring him 10 clumps of Spotted Hippogryph Down.]],choiceRewards={{id=35926,qty=1},{id=35927,qty=1},{id=35928,qty=1},{id=35925,qty=1}}}
DB[11272]={id=11272,zoneId=206,name=[[A Score to Settle]],level=71,minLevel=68,giver=[[High Executor Anselm]],giverType=[[NPC]],giverId=23780,ender=[[High Executor Anselm]],enderType=[[NPC]],enderId=23780,prevId=11234,wowhead=[[https://www.wowhead.com/wotlk/quest=11272]],image=[[assets/images/quests/placeholder.png]],desc=[[This elf prince thinks he can come to my town, insult my queen, kill my men and get away with it?  He thinks we're going to stand by while the hordes of Utgarde build up to launch an attack? Not in a million years. You're going to walk right into Utgarde and kill him in front of any of these vrykul gorillas that might be watching.  I want Arthas to know that we've arrived and we're playing for keeps.]],logDesc=[[High Executor Anselm wants you to to go into Utgarde and slay Prince Keleseth.]],choiceRewards={{id=39676,qty=1},{id=39678,qty=1},{id=39679,qty=1},{id=39680,qty=1}}}
DB[11273]={id=11273,zoneId=495,name=[[The Human League]],level=70,minLevel=68,giver=[[Beltrand McSorf]],giverType=[[NPC]],giverId=23548,ender=[[Pulroy the Archaeologist]],enderType=[[NPC]],enderId=24122,prevId=11244,rewardNextId=11274,wowhead=[[https://www.wowhead.com/wotlk/quest=11273]],image=[[assets/images/quests/placeholder.png]],desc=[[We were on the brink of an archaeological breakthrough when those monsters attacked! Sadly, I was the only one to make it back to Valgarde. Now I don't know if my crew is dead or alive, but the artifacts we uncovered on that dig must be found! If you're heading into Wyrmskull Village, will you keep an eye out for my team? If there's any hope of recovering that information, we must pursue it! Search for Pulroy first. He was the last one I saw before I made my escape.]],logDesc=[[Search Wyrmskull Village for Pulroy.]]}
DB[11274]={id=11274,zoneId=495,name=[[Zedd's Probably Dead]],level=70,minLevel=68,giver=[[Pulroy the Archaeologist]],giverType=[[NPC]],giverId=24122,ender=[[Zedd]],enderType=[[NPC]],enderId=24145,prevId=11273,rewardNextId=11276,wowhead=[[https://www.wowhead.com/wotlk/quest=11274]],image=[[assets/images/quests/placeholder.png]],desc=[[To whomever finds this journal: These bloodthirsty monsters have taken up residence in the ruins of Wyrmskull. What they want or why they're here is a mystery. In any case, the artifacts are not safe with those beast-men around. Zedd and I made a new discovery while hiding out: a cipher to decode the tablets! Unfortunately Zedd and I were separated late last night. He had the cipher. Tablets were with Glorenfeld and Daegarn. Location unknown... Find Zedd. -Pulroy]],logDesc=[[Search Wyrmskull Village for Zedd.]]}
DB[11275]={id=11275,zoneId=495,name=[[Making the Horn]],level=71,minLevel=69,giver=[[Nokoma Snowseer]],giverType=[[NPC]],giverId=24123,ender=[[Nokoma Snowseer]],enderType=[[NPC]],enderId=24123,rewardNextId=11281,wowhead=[[https://www.wowhead.com/wotlk/quest=11275]],image=[[assets/images/quests/placeholder.png]],desc=[[My people have been hunting the giant yeti of these hills for generations and I will be participating for the first time this year. It will probably be the last before we leave the post forever. To prepare for the hunt, I must fashion a loud horn from the horns of the dire rams that roam the snowy areas near our camp. The elders tell me the sound mimics the mating call of the female yeti, but I have my doubts. Bring me the best dire ram horns you can find, $N, and I'll select one from among them.]],logDesc=[[Nokoma Snowseer at Camp Winterhoof wants you to bring her 6 Undamaged Ram Horns.]]}
DB[11276]={id=11276,zoneId=495,name=[[And Then There Were Two...]],level=70,minLevel=68,giver=[[Zedd]],giverType=[[NPC]],giverId=24145,ender=[[Glorenfeld]],enderType=[[NPC]],enderId=24150,prevId=11274,rewardNextId=11277,wowhead=[[https://www.wowhead.com/wotlk/quest=11276]],image=[[assets/images/quests/placeholder.png]],desc=[[There's no sign of the cipher on Zedd. After carefully searching the area you discover some writing in the dirt: "Glor and Dae inside catacombs. Have cipher and tablets." Perhaps you should head into the catacombs located just north of here and search for Glorenfeld and Daegarn. The bridge crossing the worg pit will lead you right to the tunnel leading down into the catacombs.]],logDesc=[[Search the Utgarde Catacombs for Glorenfeld.]]}
DB[11277]={id=11277,zoneId=495,name=[[The Depths of Depravity]],level=71,minLevel=68,giver=[[Glorenfeld]],giverType=[[NPC]],giverId=24150,ender=[[Glorenfeld]],enderType=[[NPC]],enderId=24150,prevId=11276,rewardNextId=11299,wowhead=[[https://www.wowhead.com/wotlk/quest=11277]],image=[[assets/images/quests/placeholder.png]],desc=[[They're keepin' Daegarn locked up in a cage at the large fightin' ring nearby. From what I've gathered, the Dragonflayers bring out their prisoners to battle against their most powerful gladiators. They dump the losers in the basement where Scourge necromancers turn 'em into ghoulies! It's horrifying! But first things first! The tablets are strewn about all across this dungeon. Let's get those recovered before you go off tryin' to be a hero.]],logDesc=[[Glorenfeld at the Utgarde Catacombs wants you to collect 10 Wyrmskull Tablets.]]}
DB[11278]={id=11278,zoneId=495,name=[[Return to Valgarde]],level=71,minLevel=68,giver=[[Glorenfeld]],giverType=[[NPC]],giverId=24150,ender=[[Beltrand McSorf]],enderType=[[NPC]],enderId=23548,prevId=11300,rewardNextId=11448,wowhead=[[https://www.wowhead.com/wotlk/quest=11278]],image=[[assets/images/quests/placeholder.png]],desc=[['Tis a shame we lost two of our best dwarves while uncovering these relics. They sacrificed their lives to keep this information safe. <Glorenfeld wraps the cipher and tablets in a tattered cloth.> Take these back to Valgarde. McSorf will know what to do with the find. As for me? I'll be alright on my own. I've gotten this far in one piece!]],logDesc=[[Take Glorenfeld's Package to Beltrand McSorf at Valgarde Port.]],choiceRewards={{id=35820,qty=1},{id=35818,qty=1},{id=35821,qty=1},{id=35822,qty=1}}}
DB[11279]={id=11279,zoneId=495,name=[[Green Eggs and Whelps]],level=71,minLevel=68,giver=[[Plaguebringer Tillinghast]],giverType=[[NPC]],giverId=24157,ender=[[Plaguebringer Tillinghast]],enderType=[[NPC]],enderId=24157,rewardNextId=11280,wowhead=[[https://www.wowhead.com/wotlk/quest=11279]],image=[[assets/images/quests/placeholder.png]],desc=[[This new plague that we're working on is wonderful and I think we should expand its testing. How about testing it on proto-whelps?! Just think of the possibilities. The ability to infect not only humanoids, but extend our reach to any creature! Here, I've hoarded an extra plague canister for the right time and place, and you look like the right person. Spray the eggs at Ember Clutch to the northwest, then get specimens from the plagued proto-whelps that hatch.]],logDesc=[[Plaguebringer Tillinghast has asked you to collect 10 Plagued Proto-Whelp Specimens and deliver them to him at New Agamand.]]}
DB[11280]={id=11280,zoneId=495,name=[[Draconis Gastritis]],level=71,minLevel=68,giver=[[Plaguebringer Tillinghast]],giverType=[[NPC]],giverId=24157,ender=[[Plaguebringer Tillinghast]],enderType=[[NPC]],enderId=24157,prevId=11279,wowhead=[[https://www.wowhead.com/wotlk/quest=11280]],image=[[assets/images/quests/placeholder.png]],desc=[[Wait, that gives me an idea! What if it didn't kill the whelps because it was sprayed on the outside of their eggs? $N, we have to get the plague inside of them! I know! I've got some plagued meat here. Take it to the Ember Clutch and get them to eat it! But no, we're thinking too small. Let's get one of the proto-drakes flying overhead to come down and eat it. Yes! Stay close to the meat and observe what happens. Yes, it might attack you, but such is the price of progress.]],logDesc=[[Plaguebringer Tillinghast at New Agamand wants you to use Tillinghast's Plagued Meat to attract down a Proto-Drake and observe its reaction to eating the stuff.]],choiceRewards={{id=35871,qty=1},{id=35873,qty=1},{id=35875,qty=1},{id=35872,qty=1}}}
DB[11281]={id=11281,zoneId=495,name=[[Mimicking Nature's Call]],level=71,minLevel=69,giver=[[Nokoma Snowseer]],giverType=[[NPC]],giverId=24123,ender=[[Nokoma Snowseer]],enderType=[[NPC]],enderId=24123,prevId=11275,wowhead=[[https://www.wowhead.com/wotlk/quest=11281]],image=[[assets/images/quests/placeholder.png]],desc=[[The horn has been roughed out, but before I make the traditional carvings, I want to be certain that it will work. Ahota tells me that he tests his horns at the foot of the frozen waterfall to the northeast of the post. Ahota tells me that our hunters have used the acoustics of frozen water in this way for generations. I can't wait to learn more! Will you help me test out the horn? If I've done everything right, you may even attract a yeti, so be prepared! Bring the horn back once you've tested it.]],logDesc=[[Test the Carved Horn and then return to Nokoma Snowseer at Camp Winterhoof with the results.]],choiceRewards={{id=35937,qty=1},{id=35929,qty=1},{id=35931,qty=1},{id=35930,qty=1}}}
DB[11282]={id=11282,zoneId=495,name=[[A Lesson in Fear]],level=71,minLevel=68,giver=[[Sergeant Gorth]],giverType=[[NPC]],giverId=24027,ender=[[Sergeant Gorth]],enderType=[[NPC]],enderId=24027,prevId=11295,wowhead=[[https://www.wowhead.com/wotlk/quest=11282]],image=[[assets/images/quests/placeholder.png]],desc=[[When you've been in lots of fight like Gorth, you learn that to beat enemy good you have to make them really scared to die! But these vrykuls not afraid.  You kill one and another comes... screaming louder and with a bigger weapon than the one before. Only thing that makes vrykuls afraid is when we kill the biggest and baddest vrykul of all. Go fight the Winterskorn across the blockade until hero vrykuls show up!  Then you kill them dead and put queen's flag on corpses.  They must learn to fear!]],logDesc=[[Gorth wants you to kill Ulf the Bloodletter, Oric the Baleful and Gunnar Thorvardsson and drive the Forsaken Banner through their corpses.  Slay Vrykul across the Forsaken blockade until they appear.]],choiceRewards={{id=35868,qty=1},{id=35869,qty=1},{id=35867,qty=1},{id=35870,qty=1}}}
DB[11283]={id=11283,zoneId=495,name=[[Baleheim Bodycount]],level=71,minLevel=68,giver=[[Sergeant Gorth]],giverType=[[NPC]],giverId=24027,ender=[[Sergeant Gorth]],enderType=[[NPC]],enderId=24027,prevId=11282,nextId=11303,exGroup=-11283,wowhead=[[https://www.wowhead.com/wotlk/quest=11283]],image=[[assets/images/quests/placeholder.png]],desc=[[Them vrykuls just keeps coming and coming out from town west of here.  No end in sight! Gorth has an idea.  You go INSIDE town and kill them Winterskorn there.  THEN they stop coming here!]],logDesc=[[Sergeant Gorth wants you to kill 16 Winterskorn Vrykul inside Baleheim.]],choiceRewards={{id=35820,qty=1},{id=35818,qty=1},{id=35821,qty=1},{id=35822,qty=1}}}
DB[11284]={id=11284,zoneId=495,name=[[The Yeti Next Door]],level=71,minLevel=68,giver=[[Foreman Colbey]],giverType=[[NPC]],giverId=24176,ender=[[Foreman Colbey]],enderType=[[NPC]],enderId=24176,wowhead=[[https://www.wowhead.com/wotlk/quest=11284]],image=[[assets/images/quests/placeholder.png]],desc=[[Maybe if the sentries won't help me, you will? I'm the foreman of the mine just across the bridge. My men are mining ore for the weapons our expeditionary force will need to carve a path into the Grizzly Hills. A giant yeti has invaded the mine, blocking the tunnel we need to expand! We've tried yelling at him and smoking him out, but nothing's worked. Maybe you could rouse it from its sleep with a meal of meat from the frosthorn rams in the snowy areas around town? Please? We're desperate!]],logDesc=[[Foreman Colbey at Fort Wildervar wants you to defeat Shatterhorn.]],choiceRewards={{id=35937,qty=1},{id=35929,qty=1},{id=35931,qty=1},{id=35930,qty=1}}}
DB[11285]={id=11285,zoneId=495,name=[[Baleheim Must Burn!]],level=71,minLevel=68,giver=[[Sergeant Gorth]],giverType=[[NPC]],giverId=24027,ender=[[Sergeant Gorth]],enderType=[[NPC]],enderId=24027,prevId=11282,nextId=11303,exGroup=-11283,wowhead=[[https://www.wowhead.com/wotlk/quest=11285]],image=[[assets/images/quests/placeholder.png]],desc=[[Killing the Winterskorns maybe not enough.  Maybe we burn their houses too!  Uh... and their bridges.  We should burn whole town to be safe! You take this torch.  Go to Baleheim, to the west, and burn EVERYTHING!  That teach them good.]],logDesc=[[Sergeant Gorth wants you to go to Baleheim and use Gorth's Torch to burn 1 Winterskorn Dwelling, 1 Winterskorn Watchtower, 1 Winterskorn Bridge and 1 Winterskorn Barracks.]]}
DB[11286]={id=11286,zoneId=495,name=[[The Artifacts of Steel Gate]],level=71,minLevel=69,giver=[[Sage Mistwalker]],giverType=[[NPC]],giverId=24186,ender=[[Sage Mistwalker]],enderType=[[NPC]],enderId=24186,rewardNextId=11317,wowhead=[[https://www.wowhead.com/wotlk/quest=11286]],image=[[assets/images/quests/placeholder.png]],desc=[[I came out here for a different reason; an old friend of mine has been calling to me in my dreams. But now that I see these small things with their machines making a big hole in the ground, it makes my blood boil. From what I can see, these dwarves, as they are known, are digging up artifacts; artifacts that could be important to our past. I want you to go down there and get these things for me. Don't let any of those dwarves stand in your way.]],logDesc=[[Sage Mistwalker has asked you to collect 10 Steel Gate Artifacts. When you have all of them, return to him at Steel Gate.]],choiceRewards={{id=35912,qty=1},{id=35911,qty=1},{id=35936,qty=1}}}
DB[11287]={id=11287,zoneId=495,name=[[Find Sage Mistwalker]],level=71,minLevel=69,giver=[[Greatmother Ankha]],giverType=[[NPC]],giverId=24135,ender=[[Sage Mistwalker]],enderType=[[NPC]],enderId=24186,prevId=11261,wowhead=[[https://www.wowhead.com/wotlk/quest=11287]],image=[[assets/images/quests/placeholder.png]],desc=[[$C, I grow worried that my son, Sage Mistwalker, has been gone for such a long time. The land is cruel and deadly. He spoke of a recurring vision that he had of a wolf, and went west with a small group of longrunners to seek its source. I believe the name of the place he mentioned was Steel Gate. Will you find him? I want to make sure that no ill has befallen him.]],logDesc=[[Greatmother Ankha has asked you to check on the condition of Sage Mistwalker. She believes him to be at or near Steel Gate.]]}
DB[11288]={id=11288,zoneId=495,name=[[The Shining Light]],level=71,minLevel=68,giver=[[Ares the Oathbound]],giverType=[[NPC]],giverId=24189,ender=[[Ares the Oathbound]],enderType=[[NPC]],enderId=24189,prevId=11244,rewardNextId=11289,wowhead=[[https://www.wowhead.com/wotlk/quest=11288]],image=[[assets/images/quests/placeholder.png]],desc=[[<Ares gasps for air as he tries to speak.> I am an envoy of the Argent Crusade, charged with a sacred duty. Our forces were decimated in the Plaguelands. By the light of dawn, the artifact was cleansed and made pure once more. So many perished in the wake of its redemption. There is still a chance... still time. The artifact was hurled into the den of the fallen, far below us. Guarded by the unmerciful dead. <Ares' body glows with blinding light.> Light. Will. Protect. You. ]],logDesc=[[Ares the Oathbound in the Utgarde Catacombs wants you to recover the Sacred Artifact. This is a timed quest.]],choiceRewards={{id=35829,qty=1},{id=35823,qty=1},{id=35827,qty=1},{id=35824,qty=1},{id=35826,qty=1},{id=35830,qty=1}}}
DB[11289]={id=11289,zoneId=495,name=[[Guided by Honor]],level=71,minLevel=68,giver=[[Ares the Oathbound]],giverType=[[NPC]],giverId=24189,ender=[[Lord Irulon Trueblade]],enderType=[[NPC]],enderId=24191,prevId=11288,wowhead=[[https://www.wowhead.com/wotlk/quest=11289]],image=[[assets/images/quests/placeholder.png]],desc=[[<Ares smiles.> Glory to the Light. You have done it! <Ares coughs.> Take the artifact and return it to Valgarde. Lord Irulon Trueblade awaits its return. Fight with honor, friend. Always. Honor. <Ares dies.>]],logDesc=[[Return the Sacred Artifact to Lord Irulon Trueblade at Valgarde.]]}
DB[11290]={id=11290,zoneId=495,name=[[Dragonflayer Battle Plans]],level=70,minLevel=68,giver=[[Vice Admiral Keller]],giverType=[[NPC]],giverId=23546,ender=[[Vice Admiral Keller]],enderType=[[NPC]],enderId=23546,prevId=11255,rewardNextId=11291,wowhead=[[https://www.wowhead.com/wotlk/quest=11290]],image=[[assets/images/quests/placeholder.png]],desc=[[While we were able to gather very little information as to the whereabouts of Ingvar, we do know that Yanis resides in a cave next to the worg pit inside Wyrmskull Village. Intelligence gathered from the rescued soldiers indicates that Yanis guards Dragonflayer battle plans. I need you to go back to Wyrmskull and recover those plans. Kill any vrykul that get in your way - including Yanis!]],logDesc=[[Vice Admiral Keller at Valgarde Port in the Howling Fjord has asked that you bring him the Dragonflayer Battle Plans. ]],choiceRewards={{id=35814,qty=1},{id=35816,qty=1},{id=35815,qty=1},{id=35817,qty=1}}}
DB[11291]={id=11291,zoneId=495,name=[[To Westguard Keep!]],level=70,minLevel=68,giver=[[Vice Admiral Keller]],giverType=[[NPC]],giverId=23546,ender=[[Captain Adams]],enderType=[[NPC]],enderId=23749,prevId=11290,wowhead=[[https://www.wowhead.com/wotlk/quest=11291]],image=[[assets/images/quests/placeholder.png]],desc=[[<Vice Admiral Keller rolls up the battle plans.> We've got all the information we need to keep Valgarde protected. You must take these battle plans to Westguard Keep, located on the western fjord cliff wall. Speak with the flight master assistant, Emilune Winterwind. She will put you on the back of a gryphon headed towards Westguard. Once there, find Captain Adams. He's the one in charge. Adams will know what to do with these plans.]],logDesc=[[Take the Dragonflayer Battle Plans to Captain Adams at Westguard Keep in the Howling Fjord. ]]}
DB[11292]={id=11292,zoneId=495,name=[[Preying Upon the Weak]],level=70,minLevel=69,giver=[[Trapper Jethan]],giverType=[[NPC]],giverId=24131,ender=[[Trapper Jethan]],enderType=[[NPC]],enderId=24131,prevId=11406,wowhead=[[https://www.wowhead.com/wotlk/quest=11292]],image=[[assets/images/quests/placeholder.png]],desc=[[Glad to meet you. I've come here from the Grizzly Hills to do business with your cohorts. My people maintain a large outpost there, and you'd do well to visit it when you head north. I've set up traps in the woodlands and snowy areas around here. With the meat and the furs from the creatures they capture, I'll have plenty to barter with the townspeople. I can offer you a share of my profits if you're willing to help gather prey from the traps. Beware though, you won't be the only predator out there.]],logDesc=[[Trapper Jethan at Fort Wildervar wants you to bring him 8 pieces of Trapped Prey.]],choiceRewards={{id=35864,qty=1},{id=35863,qty=1},{id=35866,qty=1},{id=35865,qty=1}}}
DB[11295]={id=11295,zoneId=495,name=[[The Offensive Begins]],level=71,minLevel=68,giver=[[High Executor Anselm]],giverType=[[NPC]],giverId=23780,ender=[[Sergeant Gorth]],enderType=[[NPC]],enderId=24027,prevId=11254,rewardNextId=11282,wowhead=[[https://www.wowhead.com/wotlk/quest=11295]],image=[[assets/images/quests/placeholder.png]],desc=[[No one seems to know very much about the vrykul.  Our records show no signs of activity in their lands for centuries.  Yet here they are, just as we move against Arthas. The map you retrieved makes it clear that we'll have to defeat them if our forces are to get any further into Northrend. One of my best sergeants, an abomination known as Gorth, oversees the blockade beyond the lift.  Assist him in launching a pre-emptive strike on Baleheim.  If a vrykul attack occurs, it will be launched from there.]],logDesc=[[Speak to Sergeant Gorth at the blockade near the elevator west of Vengeance Landing in Howling Fjord.]]}
DB[11296]={id=11296,zoneId=495,name=[[Rivenwood Captives]],level=72,minLevel=70,giver=[[Longrunner Skycloud]],giverType=[[NPC]],giverId=24209,ender=[[Longrunner Skycloud]],enderType=[[NPC]],enderId=24209,wowhead=[[https://www.wowhead.com/wotlk/quest=11296]],image=[[assets/images/quests/placeholder.png]],desc=[[Something, most likely the walking dead known as the Scourge, has agitated the creatures hereabouts. While escorting the sage here, we lost most of our hunting force to the riven widows -- huge and deadly spiders, which inhabit the Rivenwood to the north. I must stay here to protect the small force we have left, but you... you could see if my longrunners are still alive, trapped within the riven widow's cocoons. Would you do this, stranger?]],logDesc=[[Longrunner Skycloud has asked you to free his 7 Winterhoof Longrunners. Once you have managed to do so, return to him at Steel Gate.]],choiceRewards={{id=35896,qty=1},{id=35898,qty=1},{id=35899,qty=1},{id=35897,qty=1}}}
DB[11297]={id=11297,zoneId=495,name=[[Keeping Watch on the Interlopers]],level=71,minLevel=69,giver=[[Junat the Wanderer]],giverType=[[NPC]],giverId=24234,ender=[[Apothecary Malthus]],enderType=[[NPC]],enderId=24152,prevId=11311,rewardNextId=11298,wowhead=[[https://www.wowhead.com/wotlk/quest=11297]],image=[[assets/images/quests/placeholder.png]],desc=[[Even the earth cannot hold back the tide of death washing over it. Corpses walk the land, spreading their putrefaction with alarming speed. A small expedition has made its way up the western cliffs and rests near Whisper Gulch. Take a look for yourself, $N. See if you can learn their purpose and dissuade them from bringing their poisons into our lands. Travel southwest from the post, toward the cliffs overlooking the western beach. Their camp will be west of the excavation at Steel Gate.]],logDesc=[[Speak to Apothecary Malthus at the Apothecary Camp.]]}
DB[11298]={id=11298,zoneId=495,name=[[What's in That Brew?]],level=71,minLevel=69,giver=[[Apothecary Malthus]],giverType=[[NPC]],giverId=24152,ender=[[Apothecary Malthus]],enderType=[[NPC]],enderId=24152,wowhead=[[https://www.wowhead.com/wotlk/quest=11298]],image=[[assets/images/quests/placeholder.png]],desc=[[To the southeast is an area called Whisper Gulch. It's overrun with members of the Explorers' League who've gone mad! They attacked our caravan as it passed through the area, and they've harried our foraging parties as well. I must know what's causing this madness! I suspect that whatever they're drinking from the kegs scattered around the gulch contributes to their insanity. I want you to steal the kegs from those dwarves while they're busy mining away.]],logDesc=[[Apothecary Malthus at the Apothecary Camp wants you to bring him 5 Dwarven Kegs.]]}
DB[11299]={id=11299,zoneId=495,name=[[The Ring of Judgement]],level=71,minLevel=68,giver=[[Glorenfeld]],giverType=[[NPC]],giverId=24150,ender=[[Daegarn]],enderType=[[NPC]],enderId=24151,prevId=11277,rewardNextId=11300,wowhead=[[https://www.wowhead.com/wotlk/quest=11299]],image=[[assets/images/quests/placeholder.png]],desc=[[You might have already seen the room where Daegarn is being held while you were gatherin' the tablets. It's through this corridor and then down a set of steps. Daegarn will be in the room at the bottom of the steps - locked up tight! Get down there and find him. At the very least you might be able to get the cipher from him.]],logDesc=[[Find Daegarn in the Ring of Judgement located inside the Utgarde Catacombs.]]}
DB[11300]={id=11300,zoneId=495,name=[[Stunning Defeat at the Ring]],level=71,minLevel=68,giver=[[Daegarn]],giverType=[[NPC]],giverId=24151,ender=[[Glorenfeld]],enderType=[[NPC]],enderId=24150,prevId=11299,rewardNextId=11278,wowhead=[[https://www.wowhead.com/wotlk/quest=11300]],image=[[assets/images/quests/placeholder.png]],desc=[[Oluf will come out if you defeat the other gladiators. That's 'bout the only way we're getting' that cipher back. Put on your whompin' boots and get busy in the Ring of Judgement. If you do manage to get the cipher back, return it to Glorenfeld o'er near the entrance to these catacombs. Me? Don't worry about me! We're on the brink of discovering the missing link to human-kind!]],logDesc=[[Defeat the gladiators at the Ring of Judgement and face Oluf the Violent. Defeat Oluf and recover the Ancient Cipher. Return the Ancient Cipher to Glorenfeld at the entrance to the Utgarde Catacombs.]]}
DB[11301]={id=11301,zoneId=495,name=[[Brains! Brains! Brains!]],level=71,minLevel=69,giver=[[Apothecary Grick]],giverType=[[NPC]],giverId=24218,ender=[[Apothecary Grick]],enderType=[[NPC]],enderId=24218,wowhead=[[https://www.wowhead.com/wotlk/quest=11301]],image=[[assets/images/quests/placeholder.png]],desc=[[Has Malthus drawn you in with his blather about beer kegs and crazy dwarves? I'm not questioning that the dwarves are crazy, but I don't think stealing their beer is going to do any good. What we need is brains. Lots of brains. We'll get down to the bottom of this mystery in no time, and perhaps even find a new component for the plague. Take this saw, go southeast into the Whisper Gulch, and kill yourself some dwarves. Use the saw to help you harvest the brains and bring them back here.]],logDesc=[[Apothecary Grick at the Apothecary Camp wants you to bring him 12 Deranged Explorer Brains.]],choiceRewards={{id=35864,qty=1},{id=35863,qty=1},{id=35866,qty=1},{id=35865,qty=1}}}
DB[11302]={id=11302,zoneId=495,name=[[The Enigmatic Frost Nymphs]],level=70,minLevel=68,giver=[[Lieutenant Maeve]],giverType=[[NPC]],giverId=24282,ender=[[Lurielle]],enderType=[[NPC]],enderId=24117,prevId=11284,nextId=11313,rewardNextId=11313,exGroup=11312,wowhead=[[https://www.wowhead.com/wotlk/quest=11302]],image=[[assets/images/quests/placeholder.png]],desc=[[When we first scouted locations for the fort, we encountered hostile creatures at two of the glades here in the north. When we passed the snow-covered one directly south of the town, the dryads there watched us with interest, but did not attack. We were tired and worn down by the weather. They could've easily killed several of our men, but they didn't. Perhaps, in reaching out to them, we might discover unexpected allies. Are you willing to travel to the Frozen Glade and make contact with them?]],logDesc=[[Speak with Lurielle at the Frozen Glade.]]}
DB[11303]={id=11303,zoneId=495,name=[[The Ambush]],level=71,minLevel=68,giver=[[Sergeant Gorth]],giverType=[[NPC]],giverId=24027,ender=[[Lydell]],enderType=[[NPC]],enderId=24458,rewardNextId=12481,wowhead=[[https://www.wowhead.com/wotlk/quest=11303]],image=[[assets/images/quests/placeholder.png]],desc=[[The vrykuls in Baleheim is completely defeated, no doubt about it.  But still their leader stays in town and won't give up. Gorth sends Lydell and his assassins to make good ambush to the northwest.  You talk to Lydell and figure out how to get Vrykul chieftain to come out.  Then you kill him.  You kill him real good.]],logDesc=[[Speak to Lydell at Lydell's Ambush.]]}
DB[11304]={id=11304,zoneId=495,name=[[New Agamand]],level=71,minLevel=68,giver=[[Apothecary Lysander]],giverType=[[NPC]],giverId=24126,ender=[[Chief Plaguebringer Harris]],enderType=[[NPC]],enderId=24251,prevId=11170,rewardNextId=11305,wowhead=[[https://www.wowhead.com/wotlk/quest=11304]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm afraid our equipment isn't exactly the best here at Vengeance Landing.  After all it's a military controlled outpost. I will need you to take a sample of this strain to Chief Plaguebringer Harris in New Agamand, follow the road beyond Baleheim south and then west.  They have better equipment there - he will know what to do. You must hurry, $N.  Our enemies are stronger and more numerous than us.  We need to develop a viable weapon against them!]],logDesc=[[Bring Lysander's Strain to Chief Plaguebringer Harris in New Agamand in western Howling Fjord.]]}
DB[11305]={id=11305,zoneId=495,name=[[A Tailor-Made Formula]],level=71,minLevel=68,giver=[[Chief Plaguebringer Harris]],giverType=[[NPC]],giverId=24251,ender=[[Chief Plaguebringer Harris]],enderType=[[NPC]],enderId=24251,prevId=11304,rewardNextId=11306,wowhead=[[https://www.wowhead.com/wotlk/quest=11305]],image=[[assets/images/quests/placeholder.png]],desc=[[We've been spraying down the vrykul village of Halgrind for weeks now and the vrykul just won't drop dead. Let's face it, $N, by now our Plague has been exposed to humans, dwarves, dogs, livestock... you name it.  As our strains adapt to their hosts, more impurities get thrown in the mix.  What we need is a strain made custom for the vrykul's biology. Halgrind's chieftain fled the town after we took it over; you'll find him west of here.  As a patriarch of the Dragonflayer clan, his blood is ideal.]],logDesc=[[Obtain the Dragonflayer Patriarch's Blood from Thorvald at Thorvald's Camp and bring it to Chief Plaguebringer Harris in New Agamand.]],choiceRewards={{id=35851,qty=1},{id=35849,qty=1},{id=35852,qty=1},{id=35856,qty=1}}}
DB[11306]={id=11306,zoneId=495,name=[[Apply Heat and Stir]],level=71,minLevel=68,giver=[[Chief Plaguebringer Harris]],giverType=[[NPC]],giverId=24251,ender=[[Chief Plaguebringer Harris]],enderType=[[NPC]],enderId=24251,prevId=11305,rewardNextId=11307,wowhead=[[https://www.wowhead.com/wotlk/quest=11306]],image=[[assets/images/quests/placeholder.png]],desc=[[You've done well so far, $N.  I'd like to teach you some of my more advanced techniques, so that you gain a better understanding of the plague. Take this empty flask and fill it with blood from the cauldron to my left.  Mix it with the plague samples to my right until you obtain a well balanced mix.]],logDesc=[[Fill the Empty Apothecary's Flask at the Cauldron of Vrykul Blood, then mix the Flask of Vrykul Blood with Harris's Plague Samples nearby until you've obtained a Balanced Concoction. Return to Chief Plaguebringer Harris when you've completed this task.]]}
DB[11307]={id=11307,zoneId=495,name=[[Field Test]],level=71,minLevel=68,giver=[[Chief Plaguebringer Harris]],giverType=[[NPC]],giverId=24251,ender=[[Chief Plaguebringer Harris]],enderType=[[NPC]],enderId=24251,prevId=11306,rewardNextId=11308,wowhead=[[https://www.wowhead.com/wotlk/quest=11307]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we have a strain of the plague that has adapted to vrykul carriers, we really ought to test it on our specimens in Halgrind.  If all goes according to plan, they will disintegrate immediately as the plague devours their innards! You will find Halgrind north of here.  Our plaguebringers are deploying the previous strain there - shouldn't be hard to spot.]],logDesc=[[Venture into Halgrind and use the Plague Spray on 10 Plagued Dragonflayer Vrykul.  Return to Chief Plaguebringer Harris to report the results.]],choiceRewards={{id=35857,qty=1},{id=35858,qty=1}}}
DB[11308]={id=11308,zoneId=495,name=[[Time for Cleanup]],level=71,minLevel=68,giver=[[Chief Plaguebringer Harris]],giverType=[[NPC]],giverId=24251,ender=[["Hacksaw" Jenny]],enderType=[[NPC]],enderId=24252,prevId=11307,rewardNextId=11309,wowhead=[[https://www.wowhead.com/wotlk/quest=11308]],image=[[assets/images/quests/placeholder.png]],desc=[[Being the practical man that I am, I'm going to declare our research here a success.  After all, what army can't be stopped by turning its rank and file against each other? I will send word of our achievements to Vengeance Landing soon enough.  But first I need you to take care of cleaning up our experimentation site. See "Hacksaw" Jenny about making you a custom abomination.  One packing some explosive power if you catch my drift.]],logDesc=[[Speak to "Hacksaw" Jenny in New Agamand.]]}
DB[11309]={id=11309,zoneId=495,name=[[Parts for the Job]],level=71,minLevel=68,giver=[["Hacksaw" Jenny]],giverType=[[NPC]],giverId=24252,ender=[["Hacksaw" Jenny]],enderType=[[NPC]],enderId=24252,prevId=11308,rewardNextId=11310,wowhead=[[https://www.wowhead.com/wotlk/quest=11309]],image=[[assets/images/quests/placeholder.png]],desc=[[So Harris wants a demolition job, eh?  Yeah, I can help out. You're gonna have to get me some parts, though.  I can't afford to use up my choice components on something that's gonna get blown up. First of all, I'm going to need shoveltusk ligaments... way better than the human kind. I will also need a pound of flesh.  A fellow known as Anton sells cheap meat.  He travels up and down the road to the west.]],logDesc=[["Hacksaw" Jenny in New Agamand wants you to obtain 6 Shoveltusk Ligaments and 1 Fresh Pound of Flesh.]],choiceRewards={{id=35845,qty=1},{id=35844,qty=1},{id=35846,qty=1},{id=35848,qty=1}}}
DB[11310]={id=11310,zoneId=495,name=[[Warning: Some Assembly Required]],level=71,minLevel=68,giver=[["Hacksaw" Jenny]],giverType=[[NPC]],giverId=24252,ender=[["Hacksaw" Jenny]],enderType=[[NPC]],enderId=24252,prevId=11309,wowhead=[[https://www.wowhead.com/wotlk/quest=11310]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, here you are!  Our friend's going to be somewhat... unstable.  So I suggest not putting him together until reaching Halgrind. Once you're there, use the abomination to round up as many vrykul as you can before self-destructing. Come back with whatever's left once you're done.  I can always use more body parts!]],logDesc=[[Use the Abomination Assembly Kit in Halgrind and round up plagued Vrykul with your Mindless Abomination.  Slay at least 20 and return to "Hacksaw" Jenny in New Agamand when you're done.]],choiceRewards={{id=35860,qty=1},{id=35859,qty=1},{id=35861,qty=1},{id=35862,qty=1}}}
DB[11311]={id=11311,zoneId=495,name=[[Suppressing the Elements]],level=71,minLevel=69,giver=[[Wind Tamer Kagan]],giverType=[[NPC]],giverId=24256,ender=[[Wind Tamer Kagan]],enderType=[[NPC]],enderId=24256,wowhead=[[https://www.wowhead.com/wotlk/quest=11311]],image=[[assets/images/quests/placeholder.png]],desc=[[If you are to survive here, as we have, you must learn to face the environment's challenges head on. The elements will claim your life if you're not vigilant, as the proliferation of elementals in these northern hills shows. We must cull the elementals one last time before we can leave this place. Are you willing to aid us while we continue to make preparations? You must kill any iceshard elementals or howling cyclones you encounter in the snowy hills surrounding the outpost.]],logDesc=[[Wind Tamer Kagan at Camp Winterhoof wants you to kill 8 mountain elementals. You may kill either Howling Cyclones or Iceshard Elementals.]]}
DB[11312]={id=11312,zoneId=495,name=[[The Frozen Glade]],level=71,minLevel=69,giver=[[Nokoma Snowseer]],giverType=[[NPC]],giverId=24123,ender=[[Lurielle]],enderType=[[NPC]],enderId=24117,nextId=11313,rewardNextId=11313,exGroup=11312,wowhead=[[https://www.wowhead.com/wotlk/quest=11312]],image=[[assets/images/quests/placeholder.png]],desc=[[For generations, my people have told tales of frost nymphs cavorting in glades hidden away in the wilderness. I used to search for them as a child, against the advice of my parents, until I nearly froze to death. These days, it isn't necessary to comb the forests for them. They've decided to reveal themselves for reasons I can only guess, but I don't think the change can be ignored. Venture southeast to the Frozen Glade and seek out the nymphs, but beware; you will pass the Twisted Glade on your way.]],logDesc=[[Speak with Lurielle at the Frozen Glade.]]}
DB[11313]={id=11313,zoneId=495,name=[[Spirits of the Ice]],level=71,minLevel=69,giver=[[Lurielle]],giverType=[[NPC]],giverId=24117,ender=[[Lurielle]],enderType=[[NPC]],enderId=24117,wowhead=[[https://www.wowhead.com/wotlk/quest=11313]],image=[[assets/images/quests/placeholder.png]],desc=[[The ice elementals surrounding our glade were once our companions, but a volatile and destructive force has swept through the land, turning them against us! This is but one of the horrors my sisters and I have endured. We have revealed ourselves to you in the hope that you will help us stave off the decay that has crept into our glades and poisoned our sisters! We've been gathering the cores of the ice elementals and keeping them safe so that one day, we might be able to restore them. Will you help?]],logDesc=[[Lurielle at the Frozen Glade wants you to bring her 15 Icy Cores.]]}
DB[11314]={id=11314,zoneId=495,name=[[The Fallen Sisters]],level=71,minLevel=69,giver=[[Lurielle]],giverType=[[NPC]],giverId=24117,ender=[[Lurielle]],enderType=[[NPC]],enderId=24117,prevId=11313,nextId=11319,wowhead=[[https://www.wowhead.com/wotlk/quest=11314]],image=[[assets/images/quests/placeholder.png]],desc=[[To the southwest was a glade that used to look much like this one. Mysterious forces and alien magics are reshaping the land. The glade has thawed, the sisters living there driven mad by the sudden change. We thought to reach out to them, but they attacked us. I fear many may be beyond saving, but I cannot give up hope. Take my pendant, travel southwest to the Vibrant Glade, and use it to try to free my sisters.]],logDesc=[[Lurielle at the Frozen Glade wants you to use her pendant on 7 Chill Nymphs.]]}
DB[11315]={id=11315,zoneId=495,name=[[Wild Vines]],level=71,minLevel=69,giver=[[Lurielle]],giverType=[[NPC]],giverId=24117,ender=[[Lurielle]],enderType=[[NPC]],enderId=24117,prevId=11313,nextId=11316,wowhead=[[https://www.wowhead.com/wotlk/quest=11315]],image=[[assets/images/quests/placeholder.png]],desc=[[The sisters who lived in the Vibrant Glade, to the southwest, used to tend to gorgeous beds of scarlet ivy, but the same force that has driven them mad has transformed their beloved ivy. The vines now grasp at the feet of the unwary, or lash at any who approach the glade. Before we can reclaim the glade, the vines must be tamed and uprooted. Clear as much of the ivy as you are able. It has already begun to grow out of control.]],logDesc=[[Lurielle at the Frozen Glade wants you to kill 8 Scarlet Ivy.]]}
DB[11316]={id=11316,zoneId=495,name=[[Spawn of the Twisted Glade]],level=71,minLevel=69,giver=[[Lurielle]],giverType=[[NPC]],giverId=24117,ender=[[Lurielle]],enderType=[[NPC]],enderId=24117,prevId=11314,wowhead=[[https://www.wowhead.com/wotlk/quest=11316]],image=[[assets/images/quests/placeholder.png]],desc=[[The glade to the west has been transformed into a hideous place called the Twisted Glade. Horrible beasts dwell among the trees, stones, and pool of the glade. I cannot guess where the creatures came from or what horrible forces animate them, but they must be dealt with! I fear that if they are allowed to dominate the glade, they will poison it beyond redemption. Clear the glade of these creatures who murdered our sisters.]],logDesc=[[Lurielle at the Frozen Glade wants you to kill 10 Thornvine Creepers.]]}
DB[11317]={id=11317,zoneId=495,name=[[The Cleansing]],level=71,minLevel=69,giver=[[Sage Mistwalker]],giverType=[[NPC]],giverId=24186,ender=[[Sage Mistwalker]],enderType=[[NPC]],enderId=24186,prevId=11286,rewardNextId=11323,wowhead=[[https://www.wowhead.com/wotlk/quest=11317]],image=[[assets/images/quests/placeholder.png]],desc=[[We braved the Rivenwood because of my troubled dreams concerning my worg life-friend, Ulfang. He has called out for help, and you must go to him. But, you do not have the means to speak with him, or walk amongst the other worgs. I know a way. First, you must cleanse your inner turmoil. There is a shrine that sits at the top of Frostblade Peak, northeast of Camp Winterhoof. A single path leads up to it from the western base of the mountain. Meditate there and then return to me.]],logDesc=[[Sage Mistwalker at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.]]}
DB[11319]={id=11319,zoneId=495,name=[[Seeds of the Blacksouled Keepers]],level=71,minLevel=69,giver=[[Lurielle]],giverType=[[NPC]],giverId=24117,ender=[[Lurielle]],enderType=[[NPC]],enderId=24117,prevId=11315,wowhead=[[https://www.wowhead.com/wotlk/quest=11319]],image=[[assets/images/quests/placeholder.png]],desc=[[The glade to the northwest, now the Twisted Glade, used to be home to a number of keepers of the glade. Together with the sisters, they saw to the glade's upkeep. When the glade changed, the sisters died, but somehow the keepers managed to survive. Now, they seed the land with poisonous spores that wither healthy greenery. I'll give you one of the cores from the ice elementals. Once you've destroyed a spore, use the ice crystal to freeze it and keep it from regenerating.]],logDesc=[[Lurielle at the Frozen Glade wants you to freeze 8 Spores.]],choiceRewards={{id=39074,qty=1},{id=39072,qty=1},{id=39073,qty=1}}}
DB[11320]={id=11320,name=[[[NYI] Now this is Ram Racing... Almost.]],level=70,minLevel=2,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11320]],image=[[assets/images/quests/placeholder.png]],desc=[[Quest Description]],logDesc=[[Log Descritpion]]}
DB[11322]={id=11322,zoneId=495,name=[[The Cleansing]],level=71,minLevel=69,giver=[[Watcher Moonleaf]],giverType=[[NPC]],giverId=24273,ender=[[Watcher Moonleaf]],enderType=[[NPC]],enderId=24273,rewardNextId=11325,wowhead=[[https://www.wowhead.com/wotlk/quest=11322]],image=[[assets/images/quests/placeholder.png]],desc=[[Of late I've had nightmares concerning a worg named Ulfang. He has called out for help, and you must go to him. However, you do not have the means to speak with him, or walk amongst the other worgs. I know a way. But first, you must cleanse your inner turmoil through meditation. There is a shrine that sits at the top of Frostblade Peak, far to the northeast. A single path leads up to it from the western base of the mountain. Meditate there to cleanse yourself and then return to me.]],logDesc=[[Watcher Moonleaf at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.]]}
DB[11323]={id=11323,zoneId=495,name=[[In Worg's Clothing]],level=71,minLevel=69,giver=[[Sage Mistwalker]],giverType=[[NPC]],giverId=24186,ender=[[Ulfang]],enderType=[[NPC]],enderId=24261,prevId=11317,rewardNextId=11415,wowhead=[[https://www.wowhead.com/wotlk/quest=11323]],image=[[assets/images/quests/placeholder.png]],desc=[[From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood. He is in great danger. I have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang. Please, $c, find and help him.]],logDesc=[[Sage Mistwalker has asked you to seek out and help Ulfang in the Rivenwood. If you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.]]}
DB[11324]={id=11324,zoneId=495,name=[[Alpha Worg]],level=71,minLevel=69,giver=[[Ulfang]],giverType=[[NPC]],giverId=24261,ender=[[Sage Mistwalker]],enderType=[[NPC]],enderId=24186,prevId=11417,wowhead=[[https://www.wowhead.com/wotlk/quest=11324]],image=[[assets/images/quests/placeholder.png]],desc=[[When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat! $R-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Mistwalker that I am once more the alpha worg!]],logDesc=[[Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Sage Mistwalker at Steel Gate.]],choiceRewards={{id=35913,qty=1},{id=35915,qty=1},{id=35916,qty=1},{id=35914,qty=1}}}
DB[11325]={id=11325,zoneId=495,name=[[In Worg's Clothing]],level=71,minLevel=69,giver=[[Watcher Moonleaf]],giverType=[[NPC]],giverId=24273,ender=[[Ulfang]],enderType=[[NPC]],enderId=24261,prevId=11322,rewardNextId=11414,wowhead=[[https://www.wowhead.com/wotlk/quest=11325]],image=[[assets/images/quests/placeholder.png]],desc=[[From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood. He is in great danger! I have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang. Please, $c, find and help him.]],logDesc=[[Watcher Moonleaf has asked you to seek out and help Ulfang in the Rivenwood. If you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.]]}
DB[11326]={id=11326,zoneId=495,name=[[Alpha Worg]],level=71,minLevel=69,giver=[[Ulfang]],giverType=[[NPC]],giverId=24261,ender=[[Watcher Moonleaf]],enderType=[[NPC]],enderId=24273,prevId=11416,wowhead=[[https://www.wowhead.com/wotlk/quest=11326]],image=[[assets/images/quests/placeholder.png]],desc=[[When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat! $R-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Moonleaf that I am once more the alpha worg!]],logDesc=[[Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Watcher Moonleaf at Steel Gate.]],choiceRewards={{id=35913,qty=1},{id=35915,qty=1},{id=35916,qty=1},{id=35914,qty=1}}}
DB[11327]={id=11327,zoneId=495,name=[[Mission: Package Retrieval]],level=71,minLevel=68,giver=[[Scout Knowles]],giverType=[[NPC]],giverId=23906,ender=[[Scout Knowles]],enderType=[[NPC]],enderId=23906,prevId=11202,rewardNextId=11328,wowhead=[[https://www.wowhead.com/wotlk/quest=11327]],image=[[assets/images/quests/placeholder.png]],desc=[[Well darn, we need some of that plague-stuff. I know! While you were destroying the vats, I happened to spy one of the apothecaries from New Agamand being pulled into Halgrind by the vrykul down in there. Poor fella'. $N, I'd bet anything that apothecary has the goods on him. Think you could go into Halgrind and retrieve his package?]],logDesc=[[Scout Knowles has asked you to retrieve the Apothecary's Package from inside Halgrind. Once you have it, return to the scout at the Ember Spear Tower.]]}
DB[11328]={id=11328,zoneId=495,name=[[Mission: Forsaken Intel]],level=71,minLevel=68,giver=[[Scout Knowles]],giverType=[[NPC]],giverId=23906,ender=[[Peppy Wrongnozzle]],enderType=[[NPC]],enderId=24283,prevId=11327,wowhead=[[https://www.wowhead.com/wotlk/quest=11328]],image=[[assets/images/quests/placeholder.png]],desc=[[Right, so I think you should get this stuff over to Peppy Wrongnozzle back at the keep. She's something of an amateur alchemist, but she's the only one we've got. One thing about Peppy; she does love her drink. So, you'll likely find her at the tavern 'soaking up the atmosphere'. I'm sure she'll know what to do.]],logDesc=[[Scout Knowles has asked you to deliver the Apothecary's Package to Peppy Wrongnozzle at Westguard Keep.]]}
DB[11329]={id=11329,zoneId=495,name=[[I'll Try Anything!]],level=70,minLevel=69,giver=[[Christopher Sloan]],giverType=[[NPC]],giverId=24056,ender=[[Christopher Sloan]],enderType=[[NPC]],enderId=24056,prevId=11250,rewardNextId=11410,wowhead=[[https://www.wowhead.com/wotlk/quest=11329]],image=[[assets/images/quests/placeholder.png]],desc=[[I never want to see another barrel of salted fish as long as I live! Filling barrels day in and day out, and there are still more to be filled! I wish I hadn't used up all that bait I bought from Nat Pagle. Worked like magic, it did. Now I'm lucky if I can catch a fish an hour! I hear the northern barbfish make pretty good bait, but who's crazy enough to dive into a freezing cold lake and hack up the water plants in search of them? Not me... but maybe, just maybe, I can persuade you to...]],logDesc=[[Christopher Sloan at Fort Wildervar wants you to bring him 5 Northern Barbfish.]]}
DB[11330]={id=11330,zoneId=495,name=[[Absholutely... Thish Will Work!]],level=71,minLevel=68,giver=[[Peppy Wrongnozzle]],giverType=[[NPC]],giverId=24283,ender=[[Peppy Wrongnozzle]],enderType=[[NPC]],enderId=24283,prevId=11328,rewardNextId=11331,wowhead=[[https://www.wowhead.com/wotlk/quest=11330]],image=[[assets/images/quests/placeholder.png]],desc=[[Voila, inshtant plague vacshine! But I sure as heck am not going to try thish on myself. And I know you don't want to be my tesht shubject! Oh, I've got... I've got an idea! We've got a vrykul prishoner being held down in the cells under the keep. Why don't you take thish mix I whipped up down there, and get that giant to drink it ...hic?!]],logDesc=[[Peppy Wrongnozzle at Westguard Keep has suggested that you take her Peppy's Special Mix and administer it to the Dragonflayer Vrykul Prisoner to witness its results.]]}
DB[11331]={id=11331,zoneId=495,name=[[You Tell Him ...Hic!]],level=71,minLevel=68,giver=[[Peppy Wrongnozzle]],giverType=[[NPC]],giverId=24283,ender=[[Captain Adams]],enderType=[[NPC]],enderId=23749,prevId=11330,rewardNextId=11332,wowhead=[[https://www.wowhead.com/wotlk/quest=11331]],image=[[assets/images/quests/placeholder.png]],desc=[[Here'sh the deal. I'm not going to the captain with thish news. I'm an amateur alchemist, thish ishn't my job, and I'm on break! Beshides, he'sh a big grumpkin... and you know him better than I do! Sho, jusht go up into the keep and tell him. I'm sure he'll be reashonable about the whole thing ...hic. <Peppy turns back to her drinking.>]],logDesc=[[Peppy Wrongnozzle has suckered you into giving the bad news about the Forsaken plague to Captain Adams. Visit him at Westguard Keep.]]}
DB[11332]={id=11332,zoneId=495,name=[[Mission: Plague This!]],level=71,minLevel=68,giver=[[Captain Adams]],giverType=[[NPC]],giverId=23749,ender=[[Captain Adams]],enderType=[[NPC]],enderId=23749,prevId=11331,rewardNextId=11248,wowhead=[[https://www.wowhead.com/wotlk/quest=11332]],image=[[assets/images/quests/placeholder.png]],desc=[[The Royal Apothecary Society thinks they're going to perfect a new plague to melt us down where we stand?! Not on my watch! Get out to the courtyard and speak with Greer Orehammer. He's got a gryphon and some bombs ready for you. I want you to bomb the plague tanks at New Agamand to smithereens!]],logDesc=[[Captain Adams has ordered you to get 5 bomb hits on the Plague Tanks at New Agamand. Do not return to him at Westguard Keep until you have accomplished that.]],choiceRewards={{id=35893,qty=1},{id=35892,qty=1},{id=35894,qty=1},{id=35895,qty=1}}}
DB[11333]={id=11333,zoneId=495,name=[[Into the World of Spirits]],level=71,minLevel=68,giver=[[Thoralius the Wise]],giverType=[[NPC]],giverId=23975,ender=[[Thoralius the Wise]],enderType=[[NPC]],enderId=23975,prevId=11244,rewardNextId=11343,wowhead=[[https://www.wowhead.com/wotlk/quest=11333]],image=[[assets/images/quests/placeholder.png]],desc=[[While the Explorers' League may discern bits and pieces of the past through their archaeological findings and the Vice Admiral might extract some knowledge of the present through brute force, the truth lies with the spirits. With the proper reagents I am able to see into the spirit world. It is there that the past, present and future of Northrend resides. If you wish to learn more, I will require my reagent pouch. It was lost in a ship that is now at the bottom of Daggercap Bay, just east of here.]],logDesc=[[Thoralius the Wise at Valgarde wants you to find his Reagent Pouch.]]}
DB[11334]={id=11334,name=[[He Shoots,He Scores!]],name_loc=[[¡Dispara y marca!]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-9576,poiY=88,wowhead=[[https://www.wowhead.com/wotlk/quest=11334]],image=[[assets/images/quests/placeholder.png]],desc=[[[PH] Shoot a marked target.]],logDesc=[[[PH] Rinling wants you to shoot a marked target and then return the Target Rifle to him.]]}
DB[11343]={id=11343,zoneId=495,name=[[The Echo of Ymiron]],level=71,minLevel=68,giver=[[Thoralius the Wise]],giverType=[[NPC]],giverId=23975,ender=[[Thoralius the Wise]],enderType=[[NPC]],enderId=23975,prevId=11333,rewardNextId=11344,wowhead=[[https://www.wowhead.com/wotlk/quest=11343]],image=[[assets/images/quests/placeholder.png]],desc=[[The spirit world has fallen under the sway of the Lich King. Fearsome creatures made of pure nightmare now stand watch over the realm of the elements. I sense that these val'kyr are guarding a terrible secret. I am too old and weak to survive another journey. You must go in my place, $N. Take this incense burner to Wyrmskull Village and use it to enter the spirit world. Find the large dwelling in the northeast! Avoid the val'kyr at all costs lest they make you a permanent fixture in their world.]],logDesc=[[Thoralius the Wise wants you to search Wyrmskull Village while you are in the spirit world and find information about the Secrets of Wyrmskull.]]}
DB[11344]={id=11344,zoneId=495,name=[[Anguish of Nifflevar]],level=71,minLevel=68,giver=[[Thoralius the Wise]],giverType=[[NPC]],giverId=23975,ender=[[Thoralius the Wise]],enderType=[[NPC]],enderId=23975,prevId=11343,wowhead=[[https://www.wowhead.com/wotlk/quest=11344]],image=[[assets/images/quests/placeholder.png]],desc=[[All that we know of the vrykul indicates that they only recently appeared in Northrend. Why, then, are we seeing vrykul in visions that date back 15,000 years? Surely if the vrykul had previously existed in Northrend we would have known. You must press on to Nifflevar. To get there you must go northeast, through Wyrmskull Village, and take the path leading up through the dam. Nifflevar is on the bluffs of the fjord. Use the incense burner once you arrive at Nifflevar and search the area for clues.]],logDesc=[[Thoralius the Wise wants you to search Nifflevar while you are in the spirit world and find information about the Secrets of Nifflevar.]],choiceRewards={{id=35832,qty=1},{id=35834,qty=1},{id=35835,qty=1},{id=35833,qty=1}}}
DB[11345]={id=11345,name=[[Prizes for Pellets]],name_loc=[[Premios por los perdigones]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-9576,poiY=88,wowhead=[[https://www.wowhead.com/wotlk/quest=11345]],image=[[assets/images/quests/placeholder.png]],desc=[[[PH] Shoot a marked target.]],logDesc=[[[PH] Rinling wants you to shoot a marked target and then return the Target Rifle to him.]],rewards={{id=33776,qty=1}}}
DB[11346]={id=11346,zoneId=495,name=[[The Book of Runes]],level=71,minLevel=69,giver=[[Prospector Belvar]],giverType=[[NPC]],giverId=24328,ender=[[Prospector Belvar]],enderType=[[NPC]],enderId=24328,prevId=11284,rewardNextId=11349,wowhead=[[https://www.wowhead.com/wotlk/quest=11346]],image=[[assets/images/quests/placeholder.png]],desc=[[The vast rocky area to the southeast, Giants' Run, has been overrun by Iron Dwarves. Scouts have reported seeing the dwarves coaxing stone giants from the ground, then carving runes on them. I can't fathom their motives, but I suspect they're somehow trying to turn the giants into weapons. The iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants. Capture the pieces of this book, assemble them, and bring it back to me, $N.]],logDesc=[[Prospector Belvar at Fort Wildervar wants you to bring him The Book of Runes.]]}
DB[11348]={id=11348,zoneId=495,name=[[The Rune of Command]],level=71,minLevel=69,giver=[[Prospector Belvar]],giverType=[[NPC]],giverId=24328,ender=[[Prospector Belvar]],enderType=[[NPC]],enderId=24328,prevId=11349,wowhead=[[https://www.wowhead.com/wotlk/quest=11348]],image=[[assets/images/quests/placeholder.png]],desc=[[Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation. Take it to Giants' Run and use it on a stone giant that the dwarves have not altered. The giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.]],logDesc=[[Prospector Belvar at Fort Wildervar wants you to test the Rune of Command and defeat Binder Murdis.]]}
DB[11349]={id=11349,zoneId=495,name=[[Mastering the Runes]],level=71,minLevel=69,giver=[[Prospector Belvar]],giverType=[[NPC]],giverId=24328,ender=[[Prospector Belvar]],enderType=[[NPC]],enderId=24328,prevId=11346,rewardNextId=11348,wowhead=[[https://www.wowhead.com/wotlk/quest=11349]],image=[[assets/images/quests/placeholder.png]],desc=[[I've got a set of picks, hammers, and chisels with me, but they won't work for carving these runes. The tools used by the Iron Dwarves are imbued with magic during their forging. When they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist. I believe I know how it works, but without a set of those tools, I can't be certain. Look for kits resembling mine near the Iron Dwarf pavilions at Giants' Run and bring them to me.]],logDesc=[[Bring a set of Iron Rune Carving Tools to Prospector Belvar at Fort Wildervar.]]}
DB[11350]={id=11350,zoneId=495,name=[[The Book of Runes]],level=71,minLevel=69,giver=[[Longrunner Pembe]],giverType=[[NPC]],giverId=24362,ender=[[Longrunner Pembe]],enderType=[[NPC]],enderId=24362,prevId=11275,rewardNextId=11351,wowhead=[[https://www.wowhead.com/wotlk/quest=11350]],image=[[assets/images/quests/placeholder.png]],desc=[[Chieftain Ashtotem dispatched me on a scouting mission to Giants' Run, a broad, rocky plateau to the southeast, past the Frozen Glade. The area has been taken over by Iron Dwarves who seem to be altering the giants as they emerge from the earth. The iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants. Capture the pieces of this book, assemble them, and bring it back to me. It's the only way we'll understand their plans.]],logDesc=[[Longrunner Pembe at Camp Winterhoof wants you to bring him The Book of Runes.]]}
DB[11351]={id=11351,zoneId=495,name=[[Mastering the Runes]],level=71,minLevel=69,giver=[[Longrunner Pembe]],giverType=[[NPC]],giverId=24362,ender=[[Longrunner Pembe]],enderType=[[NPC]],enderId=24362,prevId=11350,rewardNextId=11352,wowhead=[[https://www.wowhead.com/wotlk/quest=11351]],image=[[assets/images/quests/placeholder.png]],desc=[[I think I've figured out what the Iron Dwarves are doing. The tools they use are imbued with magic during their forging. When they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist. If I had a set of those tools, I could mimic the runes in the book. I captured one of these boxes from one of the pavilions at Giants' Run, but it was empty. Look for similar boxes and recover a set of tools from them.]],logDesc=[[Bring a set of Iron Rune Carving Tools to Longrunner Pembe at Camp Winterhoof.]]}
DB[11352]={id=11352,zoneId=495,name=[[The Rune of Command]],level=71,minLevel=69,giver=[[Longrunner Pembe]],giverType=[[NPC]],giverId=24362,ender=[[Longrunner Pembe]],enderType=[[NPC]],enderId=24362,prevId=11351,wowhead=[[https://www.wowhead.com/wotlk/quest=11352]],image=[[assets/images/quests/placeholder.png]],desc=[[Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation. Take it to Giants' Run and use it on a stone giant that the dwarves have not altered. The giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.]],logDesc=[[Longrunner Pembe at Camp Winterhoof wants you to test the Rune of Command and defeat Binder Murdis.]]}
DB[11353]={id=11353,name=[[FLAG: Got the work shirt]],name_loc=[[FLAG: Got the work shirt]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11353]],image=[[assets/images/quests/placeholder.png]]}
DB[11355]={id=11355,zoneId=495,name=[[March of the Giants]],level=72,minLevel=69,giver=[[Researcher Aderan]],giverType=[[NPC]],giverId=24376,ender=[[Researcher Aderan]],enderType=[[NPC]],enderId=24376,prevId=11284,rewardNextId=11358,wowhead=[[https://www.wowhead.com/wotlk/quest=11355]],image=[[assets/images/quests/placeholder.png]],desc=[[To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. What their ultimate destination is, I do not know. The glowing runes inscribed in the stone flesh of the giants guide them on their journey. Use this pick to deactivate the runes on the giants' corpses and return with your findings.]],logDesc=[[Researcher Aderan at Fort Wildervar wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.]]}
DB[11358]={id=11358,zoneId=495,name=[[The Lodestone]],level=72,minLevel=69,giver=[[Researcher Aderan]],giverType=[[NPC]],giverId=24376,ender=[[Researcher Aderan]],enderType=[[NPC]],enderId=24376,prevId=11355,rewardNextId=11359,wowhead=[[https://www.wowhead.com/wotlk/quest=11358]],image=[[assets/images/quests/placeholder.png]],desc=[[If we can locate what's luring the giants northwest, we might be able to stop them before they reach their destination. Although I was able to decipher many of the runes on the samples you brought me, the ones I don't know concern me the most. When I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn.]],logDesc=[[Researcher Aderan at Fort Wildervar wants you to compare the Rune Sample with the Broken Tablet.]]}
DB[11359]={id=11359,zoneId=495,name=[[Demolishing Megalith]],level=72,minLevel=69,giver=[[Researcher Aderan]],giverType=[[NPC]],giverId=24376,ender=[[Researcher Aderan]],enderType=[[NPC]],enderId=24376,prevId=11358,wowhead=[[https://www.wowhead.com/wotlk/quest=11359]],image=[[assets/images/quests/placeholder.png]],desc=[[Binder Murdis created Megalith to be the most powerful of the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. After the expeditionary force arrives, our soldiers will be able to isolate and defeat the remaining giants and oust their Iron Dwarf masters from their camps. Search the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!]],logDesc=[[Defeat Megalith and return to Researcher Aderan at Fort Wildervar.]]}
DB[11365]={id=11365,zoneId=495,name=[[March of the Giants]],level=72,minLevel=69,giver=[[Sage Edan]],giverType=[[NPC]],giverId=24390,ender=[[Sage Edan]],enderType=[[NPC]],enderId=24390,prevId=11275,rewardNextId=11366,wowhead=[[https://www.wowhead.com/wotlk/quest=11365]],image=[[assets/images/quests/placeholder.png]],desc=[[To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. I know nothing of their goals, nor of their destination. The glowing runes inscribed in the stone flesh of the giants guide them on their journey. Fell some of these giants. Take this pick with you and use it on the corpses of the runed stone giants. It will deactivate the runes. Once you've tested enough giants, return to me with your findings.]],logDesc=[[Sage Edan and Camp Winterhoof wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.]]}
DB[11366]={id=11366,zoneId=495,name=[[The Lodestone]],level=72,minLevel=69,giver=[[Sage Edan]],giverType=[[NPC]],giverId=24390,ender=[[Sage Edan]],enderType=[[NPC]],enderId=24390,prevId=11365,rewardNextId=11367,wowhead=[[https://www.wowhead.com/wotlk/quest=11366]],image=[[assets/images/quests/placeholder.png]],desc=[[We must find what's luring the giants northwest, so we can stop them before they reach their destination. While the rune samples gave us some clues, the unknown runes worry me. When I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn about the identity of this lodestone.]],logDesc=[[Sage Edan at Camp Winterhoof wants you to compare the Rune Sample with the Broken Tablet.]]}
DB[11367]={id=11367,zoneId=495,name=[[Demolishing Megalith]],level=72,minLevel=69,giver=[[Sage Edan]],giverType=[[NPC]],giverId=24390,ender=[[Sage Edan]],enderType=[[NPC]],enderId=24390,prevId=11366,wowhead=[[https://www.wowhead.com/wotlk/quest=11367]],image=[[assets/images/quests/placeholder.png]],desc=[[Binder Murdis created Megalith to be a kind of keystone for the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. I will ask Chieftain Ashtotem to divert some of our men as we move north and dedicate them to eliminating the last of the runed giants. Without their giants, the Iron Dwarves cannot stand against us. Search the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!]],logDesc=[[Defeat Megalith and return to Sage Edan at Camp Winterhoof.]]}
DB[11390]={id=11390,zoneId=495,name=[[I've Got a Flying Machine!]],level=71,minLevel=69,giver=[[Steel Gate Chief Archaeologist]],giverType=[[NPC]],giverId=24399,ender=[[Steel Gate Chief Archaeologist]],enderType=[[NPC]],enderId=24399,prevId=11176,rewardNextId=11391,wowhead=[[https://www.wowhead.com/wotlk/quest=11390]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, what are you waiting for, there's work to be done! Here's the keys to our flying machine. Grab three sacks of relics and haul them up to the crane platforms on the north and south sides of Steel Gate.  I'll mark them for you. Hurry up! We haven't got all day!]],logDesc=[[The Steel Gate Chief Archaeologist wants you to transport 3 Sacks of Relics from the bottom of the site and take them to the platform on the north or south side of Steel Gate. Use the grappling hook on the flying machine to do this. Report back to him after you've done so.]],rewards={{id=22829,qty=5}},choiceRewards={{id=35912,qty=1},{id=35911,qty=1},{id=35936,qty=1}}}
DB[11391]={id=11391,zoneId=495,name=[[Steel Gate Patrol]],level=71,minLevel=69,giver=[[Steel Gate Chief Archaeologist]],giverType=[[NPC]],giverId=24399,ender=[[Steel Gate Chief Archaeologist]],enderType=[[NPC]],enderId=24399,prevId=11390,wowhead=[[https://www.wowhead.com/wotlk/quest=11391]],image=[[assets/images/quests/placeholder.png]],desc=[[Eh? Yer back for another day's work? Well, alright, here's the keys. We don't need any haulin' today, so just keep an eye out for anything suspicious, okay? I've hooked her up with some rockets and a machine gun - just in case.]],logDesc=[[You're Steel Gate's ace pilot now, so the Steel Gate Chief Archaeologist wants you to keep patrol around the dig site and fight off anything that attacks. Report back to him when you're done with your patrol.]],rewards={{id=22829,qty=2}}}
DB[11393]={id=11393,zoneId=495,name=[[Where is Explorer Jaren?]],level=71,minLevel=69,giver=[[Overseer Irena Stonemantle]],giverType=[[NPC]],giverId=23891,ender=[[Explorer Jaren]],enderType=[[NPC]],enderId=23833,wowhead=[[https://www.wowhead.com/wotlk/quest=11393]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, my betrothed, Jaren, went west with a small group of explorers to check into rumors of artifacts on the Chillmere Coast. But there are murloc down there, and I fear the worst has befallen them. Surely you have time to see if they're alright? There's a way down to the beach just to the southwest, though watch out for the worgs and other things lurking in the woods.]],logDesc=[[Overseer Irena Stonemantle has asked you to locate her fiance, Explorer Jaren.]]}
DB[11394]={id=11394,zoneId=495,name=[[And You Thought Murlocs Smelled Bad!]],level=71,minLevel=69,giver=[[Explorer Jaren]],giverType=[[NPC]],giverId=23833,ender=[[Explorer Jaren]],enderType=[[NPC]],enderId=23833,wowhead=[[https://www.wowhead.com/wotlk/quest=11394]],image=[[assets/images/quests/placeholder.png]],desc=[[Originally I came down here to investigate some rumors about artifacts to be dug up. I knew that there were murlocs along the coast here, but I never in a million years thought I'd see this. <The explorer pokes his head out to look around the tree.> The Scourge are out there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead! $C, I think it's our duty to do something about this. Think you could take out a good chunk of those Scourge?]],logDesc=[[Explorer Jaren has asked you to kill 15 Scourge of any type along the Chillmere Coast. Return to him once you have done so.]]}
DB[11395]={id=11395,zoneId=495,name=[[It's a Scourge Device]],level=71,minLevel=69,giverType=[[NPC]],ender=[[Explorer Jaren]],enderType=[[NPC]],enderId=23833,rewardNextId=11396,wowhead=[[https://www.wowhead.com/wotlk/quest=11395]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals. Surely, Explorer Jaren would like to have a look at this.]],logDesc=[[Deliver the Scourge Device to Explorer Jaren on the Chillmere Coast.]]}
DB[11396]={id=11396,zoneId=495,name=[[Bring Down Those Shields]],level=71,minLevel=69,giver=[[Explorer Jaren]],giverType=[[NPC]],giverId=23833,ender=[[Explorer Jaren]],enderType=[[NPC]],enderId=23833,prevId=11395,wowhead=[[https://www.wowhead.com/wotlk/quest=11396]],image=[[assets/images/quests/placeholder.png]],desc=[[Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up. What do you say, $N? You up for it? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals. It's the least we can do to keep the Scourge from making more of their own kind.]],logDesc=[[Explorer Jaren on the Chillmere Coast has asked you to destroy 3 Scourging Crystals.]],choiceRewards={{id=35932,qty=1},{id=35933,qty=1},{id=35934,qty=1},{id=35935,qty=1}}}
DB[11397]={id=11397,zoneId=495,name=[[And You Thought Murlocs Smelled Bad!]],level=71,minLevel=69,giver=[[Apothecary Anastasia]],giverType=[[NPC]],giverId=24359,ender=[[Apothecary Anastasia]],enderType=[[NPC]],enderId=24359,wowhead=[[https://www.wowhead.com/wotlk/quest=11397]],image=[[assets/images/quests/placeholder.png]],desc=[[I came here to investigate a rumor about a Scourge presence nearby. I expected murlocs along the coast down below, but I never thought I'd see this! The Scourge are down there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead! $C, we will not suffer them to create more of their kind, especially not from murlocs! There is a ramp down to the beach just northwest of the camp. See to it that you deal with the Scourge in a timely fashion!]],logDesc=[[Apothecary Anastasia has asked you to destroy 15 Scourge of any type along the Chillmere Coast. Return to her at the Apothecary Camp once you have done so.]]}
DB[11398]={id=11398,zoneId=495,name=[[It's a Scourge Device]],level=71,minLevel=69,giverType=[[NPC]],ender=[[Apothecary Anastasia]],enderType=[[NPC]],enderId=24359,rewardNextId=11399,wowhead=[[https://www.wowhead.com/wotlk/quest=11398]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals. Surely, Apothecary Anastasia would like to have a look at this.]],logDesc=[[Deliver the Scourge Device to Apothecary Anastasia at the Apothecary Camp.]]}
DB[11399]={id=11399,zoneId=495,name=[[Bring Down Those Shields]],level=71,minLevel=69,giver=[[Apothecary Anastasia]],giverType=[[NPC]],giverId=24359,ender=[[Apothecary Anastasia]],enderType=[[NPC]],enderId=24359,prevId=11398,wowhead=[[https://www.wowhead.com/wotlk/quest=11399]],image=[[assets/images/quests/placeholder.png]],desc=[[Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up. Brave enough to hazard another trip down there, $N? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals. How can you refuse if it means less Scourge, especially ones made from murlocs?]],logDesc=[[Apothecary Anastasia at the Apothecary Camp has asked you to destroy 3 Scourging Crystals.]],choiceRewards={{id=35932,qty=1},{id=35933,qty=1},{id=35934,qty=1},{id=35935,qty=1}}}
DB[11402]={id=11402,zoneId=151,name=[[Clayton's Quest: Extreme!]],level=68,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11402]],image=[[assets/images/quests/placeholder.png]],desc=[[Clayton wants you to find and slay twenty Evil Squirrels.]],logDesc=[[Seriously, go slay those Evil Squirrels!]]}
DB[11406]={id=11406,zoneId=495,name=[[Everything Must Be Ready]],level=70,minLevel=68,giver=[[Quartermaster Brevin]],giverType=[[NPC]],giverId=24494,ender=[[Gil Grisert]],enderType=[[NPC]],enderId=24139,prevId=11250,wowhead=[[https://www.wowhead.com/wotlk/quest=11406]],image=[[assets/images/quests/placeholder.png]],desc=[[When the expeditionary force moves north, Captain Adams expects everything to be ready at Fort Wildervar. The scouts and craftsmen there have been tasked with preparing the gear and rations for our men for the climb into the hills. The captain's famous for his temper, so I want to send someone ahead to check on the preparations. Fort Wildervar is far to the northeast, beyond Skorn, up in the snow-covered areas near the border with Grizzly Hills. Find Gil Grisert there and make sure he is prepared.]],logDesc=[[Speak with Gil Grisert at Fort Wildervar.]]}
DB[11410]={id=11410,zoneId=495,name=[[The One That Got Away]],level=71,minLevel=68,giver=[[Christopher Sloan]],giverType=[[NPC]],giverId=24056,ender=[[Christopher Sloan]],enderType=[[NPC]],enderId=24056,prevId=11329,wowhead=[[https://www.wowhead.com/wotlk/quest=11410]],image=[[assets/images/quests/placeholder.png]],desc=[[The barbfish you brought should work well as bait for most fish, but I fear it'll attract a monster! When I first arrived, I put some of Nat Pagle's favorite bait on my hook and cast it into the water. A huge monster latched on, with giant teeth and icicles hanging from its fins! Would've pulled me into those icy waters if I hadn't cut the line! I can't use the new bait until ol' Frostfin's been dealt with. Use this bait near the sunken boat in the middle of the lake. He won't be able to resist!]],logDesc=[[Christopher Sloan at Fort Wildervar wants you to defeat Frostfin.]]}
DB[11411]={id=11411,zoneId=495,name=[[Camp Winterhoof]],level=70,minLevel=68,giver=[[Cormath the Courier]],giverType=[[NPC]],giverId=24125,ender=[[Chieftain Ashtotem]],enderType=[[NPC]],enderId=24129,exGroup=11411,wowhead=[[https://www.wowhead.com/wotlk/quest=11411]],image=[[assets/images/quests/placeholder.png]],desc=[[In my travels as a courier, I've seen a number of strange denizens of the Howling Fjord, but one group stands out. From a distance, they look like tauren, but upon closer inspection, they're quite different -- sturdier and shaggier. I found one of their settlements far to the north, beyond Halgrind, Skorn, and the northern forests. Camp Winterhoof, it's called, and it sits in the foothills of Gjalerhorn near the border with Grizzly Hills. Make contact with them, and see if they might be of use to us.]],logDesc=[[Speak to Chieftain Ashtotem at Camp Winterhoof.]]}
DB[11414]={id=11414,zoneId=495,name=[[Brother Betrayers]],level=71,minLevel=69,giver=[[Ulfang]],giverType=[[NPC]],giverId=24261,ender=[[Ulfang]],enderType=[[NPC]],enderId=24261,prevId=11325,rewardNextId=11416,wowhead=[[https://www.wowhead.com/wotlk/quest=11414]],image=[[assets/images/quests/placeholder.png]],desc=[[Watcher Moonleaf is from my dreams! If you are her friend, you are mine. I was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha worg. There is something unnatural about him. To help, you must first kill those who betrayed me. Bjomolf hunts to the northwest of a place called Steel Gate. And look for Varg to the southeast, near the West Spear Tower. They will not be fooled by your form.]],logDesc=[[Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so. If you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.]]}
DB[11415]={id=11415,zoneId=495,name=[[Brother Betrayers]],level=71,minLevel=69,giver=[[Ulfang]],giverType=[[NPC]],giverId=24261,ender=[[Ulfang]],enderType=[[NPC]],enderId=24261,prevId=11323,rewardNextId=11417,wowhead=[[https://www.wowhead.com/wotlk/quest=11415]],image=[[assets/images/quests/placeholder.png]],desc=[[Mistwalker is from my dreams! If you are his friend, you are mine. I was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha. There is something unnatural about him. To help, you must first kill those who betrayed me. Bjomolf hunts to the northwest of a place the two-legs call Steel Gate. And look for Varg to the southeast, near the West Spear Tower. They will not be fooled by your form.]],logDesc=[[Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so. If you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.]]}
DB[11416]={id=11416,zoneId=495,name=[[Eyes of the Eagle]],level=71,minLevel=69,giver=[[Ulfang]],giverType=[[NPC]],giverId=24261,ender=[[Ulfang]],enderType=[[NPC]],enderId=24261,prevId=11414,rewardNextId=11326,wowhead=[[https://www.wowhead.com/wotlk/quest=11416]],image=[[assets/images/quests/placeholder.png]],desc=[[Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though. My enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal. Talonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you. Get her eyes.]],logDesc=[[Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so. If you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.]]}
DB[11417]={id=11417,zoneId=495,name=[[Eyes of the Eagle]],level=71,minLevel=69,giver=[[Ulfang]],giverType=[[NPC]],giverId=24261,ender=[[Ulfang]],enderType=[[NPC]],enderId=24261,prevId=11415,rewardNextId=11324,wowhead=[[https://www.wowhead.com/wotlk/quest=11417]],image=[[assets/images/quests/placeholder.png]],desc=[[Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though. My enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal. Talonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you. Get her eyes.]],logDesc=[[Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so. If you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.]]}
DB[11418]={id=11418,zoneId=495,name=[[We Call Him Steelfeather]],level=70,minLevel=68,giver=[[Gil Grisert]],giverType=[[NPC]],giverId=24139,ender=[[Gil Grisert]],enderType=[[NPC]],enderId=24139,prevId=11269,wowhead=[[https://www.wowhead.com/wotlk/quest=11418]],image=[[assets/images/quests/placeholder.png]],desc=[[We see one brave hippogryph circling over the fort, then swooping down and taking prey. Jethan over there has taken a couple of shots at the creature, but his arrows bounced right off! We've taken to calling this remarkable creature Steelfeather, but we can't see why he prefers the area around Fort Wildervar. Most hippogryphs are wary of people. Researcher Aderan has helped us fashion a charm from one of the creature's feathers. He claims it will allow the user to see through Steelfeather's eyes.]],logDesc=[[Locate Steelfeather circling Fort Wildervar and use the Feathered Charm to discover his secret. Report your findings to Gil Grisert.]]}
DB[11420]={id=11420,zoneId=495,name=[[The Path to Payback]],level=71,minLevel=68,giver=[[Guard Captain Zorek]],giverType=[[NPC]],giverId=23728,ender=[[Guard Captain Zorek]],enderType=[[NPC]],enderId=23728,prevId=11244,rewardNextId=11426,wowhead=[[https://www.wowhead.com/wotlk/quest=11420]],image=[[assets/images/quests/placeholder.png]],desc=[[Two weeks ago our chief engineer got his hands on a vrykul harpoon gun - the same type of gun that the vrykul use to take down our ships. By studying that gun he managed to put together a comprehensive operation manual. Unfortunately he was abducted and taken north of here to Wyrmskull Village. We eventually did find him, but near death and without the manual. His dying words indicated that the manual was lost in the Utgarde Catacombs, located at the northwest end of Wyrmskull. Get me that manual!]],logDesc=[[Guard Captain Zorek at Valgarde in Howling Fjord wants you to recover the Harpoon Operation Manual.]]}
DB[11421]={id=11421,zoneId=495,name=[[It Goes to 11...]],level=71,minLevel=68,giver=[[Lieutenant Icehammer]],giverType=[[NPC]],giverId=24634,ender=[[Lieutenant Icehammer]],enderType=[[NPC]],enderId=24634,prevId=11430,rewardNextId=11436,wowhead=[[https://www.wowhead.com/wotlk/quest=11421]],image=[[assets/images/quests/placeholder.png]],desc=[[We must strike while the vrykul forces are in disarray! Take the harpoon control mechanism to Nifflevar and locate the northernmost harpoon building on the bluff side of the village. Once there, commandeer one of the vrykul harpoon guns that are stationed on the building's deck. Use the harpoon gun to rain hell upon Wyrmskull Village! Destroy the longhouse, dockhouse, storage facility and any defenders that the vrykul may send at you! Do this and Daggercap Bay will become a much safer port!]],logDesc=[[Lieutenant Icehammer in the Howling Fjord wants you to destroy the Dragonflayer Longhouse, Dragonflayer Dockhouse, Dragonflayer Storage Facility and 8 Dragonflayer Defenders. Return the Harpoon Control Mechanism to him once the task is complete.]],choiceRewards={{id=35841,qty=1},{id=35842,qty=1},{id=35843,qty=1},{id=35839,qty=1}}}
DB[11422]={id=11422,zoneId=495,name=[[Trident of the Son]],level=71,minLevel=69,giver=[[Old Icefin]],giverType=[[NPC]],giverId=24544,ender=[[Old Icefin]],enderType=[[NPC]],enderId=24544,wowhead=[[https://www.wowhead.com/wotlk/quest=11422]],image=[[assets/images/quests/placeholder.png]],desc=[[<From the scratches he makes in the rock, you see several symbols: a trident, a mur'ghoul, the sun, a wrecked ship, and a rough stick-figure of yourself.> <Puzzling out what the murloc is conveying takes a while. Obviously he wants you to get a trident from the Chillmere Coast, but the image of the sun is puzzling. That is until you realize he means his son.> <His son was changed into a mur'ghoul! He wants you to find him to the south near the wrecked ship and return with his trident.>]],logDesc=[[Old Icefin wants you to obtain Rotgill's Trident. Return it to him on the small island on the Chillmere Coast.]]}
DB[11423]={id=11423,zoneId=495,name=[[The Enemy's Legacy]],level=71,minLevel=70,giver=[[Scribe Seguine]],giverType=[[NPC]],giverId=24548,ender=[[Scribe Seguine]],enderType=[[NPC]],enderId=24548,wowhead=[[https://www.wowhead.com/wotlk/quest=11423]],image=[[assets/images/quests/placeholder.png]],desc=[[As our armies march through Northrend, our enemies will not suffer mere defeat.  Their houses will burn, their corpses will be devoured by our plagues, all trace of their existence will be lost. This worries me as a seeker of knowledge.  The eastern town of Nifflevar will soon be razed by our forces in Vengeance Landing.  The vrykul bard, Helgus, lived there and wrote three sagas: the Saga of the Twins, the Saga of the Winter Curse and the Saga of the Val'kyr.  Obtain them before Nifflevar is destroyed.]],logDesc=[[Go into Nifflevar, north of Ghostblade Post and look for the Saga of the Winter Curse, the Saga of the Val'kyr and the Saga of the Twins.]]}
DB[11424]={id=11424,zoneId=495,name=[[Shield Hill]],level=71,minLevel=68,giver=[["Hacksaw" Jenny]],giverType=[[NPC]],giverId=24252,ender=[["Hacksaw" Jenny]],enderType=[[NPC]],enderId=24252,wowhead=[[https://www.wowhead.com/wotlk/quest=11424]],image=[[assets/images/quests/placeholder.png]],desc=[[My work should be extremely easy in a time of war.  There ought to be usable body parts everywhere. It's not that simple, though.  With these eggheads making all sorts of killer plagues and sending them to enemy towns, most of the material gets contaminated. There is a place, though, where usable samples exist.  Shield Hill, south of here, is an ancient vrykul burial ground where the dead walk but are not afflicted with any plague - ours or the Lich King's.  Get me some bones, I'll pay ya well.]],logDesc=[["Hacksaw" Jenny wants you to bring her 5 Ancient Vrykul Bones from the reanimated Vrykul in Shield Hill, south of New Agamand.]],choiceRewards={{id=35893,qty=1},{id=35892,qty=1},{id=35894,qty=1},{id=35895,qty=1}}}
DB[11426]={id=11426,zoneId=495,name=[[Locating the Mechanism]],level=71,minLevel=68,giver=[[Guard Captain Zorek]],giverType=[[NPC]],giverId=23728,ender=[[Guard Captain Zorek]],enderType=[[NPC]],enderId=23728,prevId=11420,rewardNextId=11427,wowhead=[[https://www.wowhead.com/wotlk/quest=11426]],image=[[assets/images/quests/placeholder.png]],desc=[[Don't worry, $N; this is all going to lead to something big! HUGE! You're just going to have to trust me for now and do as I ask of you. We need to get the mechanism mentioned in the manual for the next step of the plan. I have a strong suspicion that you'll find one on one of those vrykul that operate the harpoon guns in Wyrmskull Village. You'll find them on the east side of the village, on the docks by the longhouses.]],logDesc=[[Guard Captain Zorek at Valgarde in Howling Fjord wants you to bring him a Harpoon Control Mechanism.]]}
DB[11427]={id=11427,zoneId=495,name=[[Meet Lieutenant Icehammer...]],level=71,minLevel=68,giver=[[Guard Captain Zorek]],giverType=[[NPC]],giverId=23728,ender=[[Lieutenant Icehammer]],enderType=[[NPC]],enderId=24634,prevId=11426,rewardNextId=11429,wowhead=[[https://www.wowhead.com/wotlk/quest=11427]],image=[[assets/images/quests/placeholder.png]],desc=[[Do you see those vrykul buildings on the bluffs to the northeast? The vrykul call that place Nifflevar. It's where most of their harpoon attacks on our frigates originate. Well guess what? The time for payback has come, $N. I need you to take this harpoon control mechanism and meet up with Lieutenant Icehammer, who is hiding out in a vrykul building northwest of Nifflevar. When you're ready I'll place you on the back of one of our gryphons and zip you right to him!  ]],logDesc=[[Guard Captain Zorek wants you to take the Harpoon Control Mechanism to Lieutenant Icehammer stationed outside of Nifflevar.]]}
DB[11428]={id=11428,zoneId=495,name=[[Keeper Witherleaf]],level=71,minLevel=69,giver=[[Lurielle]],giverType=[[NPC]],giverId=24117,ender=[[Lurielle]],enderType=[[NPC]],enderId=24117,prevId=11316,wowhead=[[https://www.wowhead.com/wotlk/quest=11428]],image=[[assets/images/quests/placeholder.png]],desc=[[You have been a great friend and ally to us, $N. There is one more thing I must ask of you. You have seen the corruption of the Twisted Glade and the beasts that dwell there. The blacksouled keepers will continue raising these abominations from the waters and soil of our glade unless we act against them. The most powerful of the blacksouled keepers is known as Keeper Witherleaf. Slay him, $N, and open the way for the redemption of the glade as you once redeemed my sisters.]],logDesc=[[Lurielle at the Frozen Glade wants you to kill Keeper Witherleaf.]]}
DB[11429]={id=11429,zoneId=495,name=[[Drop It then Rock It!]],level=71,minLevel=68,giver=[[Lieutenant Icehammer]],giverType=[[NPC]],giverId=24634,ender=[[Lieutenant Icehammer]],enderType=[[NPC]],enderId=24634,prevId=11427,rewardNextId=11430,wowhead=[[https://www.wowhead.com/wotlk/quest=11429]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm not about to put the fate of this mission into the hands of some untested scrub. Now, if you want to prove to me that you've got what it takes to carry out this mission, you'll need to do what I tell you. Take this battle standard and head over to Baleheim, directly north of here. Once you're at Baleheim, find the center of town and drop our flag. Fight off any vrykul dirt bags that attempt to take down our beloved flag and return to me once you've established Alliance dominance!]],logDesc=[[Lieutenant Icehammer in the Howling Fjord wants you to place the Alliance Banner in Baleheim and then defend the banner against attackers. Return to Lieutenant Icehammer with the Alliance Banner should you survive.]]}
DB[11430]={id=11430,zoneId=495,name=[[Harpoon Master Yavus]],level=71,minLevel=68,giver=[[Lieutenant Icehammer]],giverType=[[NPC]],giverId=24634,ender=[[Lieutenant Icehammer]],enderType=[[NPC]],enderId=24634,prevId=11429,rewardNextId=11421,wowhead=[[https://www.wowhead.com/wotlk/quest=11430]],image=[[assets/images/quests/placeholder.png]],desc=[[That was a fairly strong showing at Baleheim, $N. Before you go off patting yourself on the back there's work to be done at Nifflevar. We've located the vrykul responsible for the majority of the harpoon attacks on our frigates - goes by the name of Yavus. You'll find him in the main harpoon structure on the bluffs of Nifflevar, southeast of here. Track him down and execute him for crimes against the Alliance! Do me proud, $N! ]],logDesc=[[Lieutenant Icehammer in the Howling Fjord wants you to slay Harpoon Master Yavus at Nifflevar.]]}
DB[11432]={id=11432,zoneId=495,name=[[Sleeping Giants]],level=71,minLevel=68,giver=[[Mage-Lieutenant Malister]],giverType=[[NPC]],giverId=23888,ender=[[Mage-Lieutenant Malister]],enderType=[[NPC]],enderId=23888,prevId=11239,wowhead=[[https://www.wowhead.com/wotlk/quest=11432]],image=[[assets/images/quests/placeholder.png]],desc=[[I've overheard what you've had to say with Father Levariol. Allow me to suggest that he's not having you go far enough. You must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron! I have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely. Surely such a disruption will prove fatal to the vrykul.]],logDesc=[[Mage-Lieutenant Malister has tasked you with slaying 5 Dormant Vrykul. Return to him at Westguard Keep when you have done so.]]}
DB[11433]={id=11433,zoneId=495,name=[[Sleeping Giants]],level=71,minLevel=68,giver=[[Ahota Whitefrost]],giverType=[[NPC]],giverId=24127,ender=[[Ahota Whitefrost]],enderType=[[NPC]],enderId=24127,prevId=11265,wowhead=[[https://www.wowhead.com/wotlk/quest=11433]],image=[[assets/images/quests/placeholder.png]],desc=[[I've overheard what you've had to say with Greatmother Ankha. With all due respect, she's not having you go far enough. You must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron! I have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely. Surely such a disruption will prove fatal to the vrykul.]],logDesc=[[Ahota Whitefrost has tasked you with slaying 5 Dormant Vrykul. Return to him at Camp Winterhoof when you have done so.]]}
DB[11434]={id=11434,zoneId=495,name=[[Forgotten Treasure]],level=71,minLevel=69,giver=[[Handsome Terry]],giverType=[[NPC]],giverId=24537,ender=[[Handsome Terry]],enderType=[[NPC]],enderId=24537,prevId=11509,rewardNextId=11455,wowhead=[[https://www.wowhead.com/wotlk/quest=11434]],image=[[assets/images/quests/placeholder.png]],desc=[[I've made my fortune by specializing in treasure that regular pirates don't appreciate: art, antiquities, collector's pieces. Black Conrad's fleet sank south of here years ago.  All the gold and jewelry was picked clean by divers, but two ancient relics remain there.  One is a museum-quality Amani vase, the other is an eagle figurine. Go and retrieve them for me and I'll vouch for you with the other pirates.  I'll even throw in something to make your underwater adventure a bit more manageable.]],logDesc=[[Handsome Terry at Scalawag Point wants you to bring him 1 Amani Vase and 1 Eagle Figurine from the shipwreck to the south.]]}
DB[11435]={id=11435,name=[[Gathered Pumpkins NYI]],level=70,minLevel=5,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11435]],image=[[assets/images/quests/placeholder.png]],desc=[[Hi,$N!  Thanks for driving away the Horseman!  Now that he's gone,the matron said we can roam the village! I found some pumpkins that the Horseman dropped.  They look scary... will you take them and show  them to the matron?]],logDesc=[[Take the bunch of jack-o'-lanterns to the Costumed Orphan Matron.]],rewards={{id=34068,qty=5}}}
DB[11436]={id=11436,zoneId=495,name=[[Let's Go Surfing Now]],level=71,minLevel=68,giver=[[Lieutenant Icehammer]],giverType=[[NPC]],giverId=24634,ender=[[Guard Captain Zorek]],enderType=[[NPC]],enderId=23728,prevId=11421,wowhead=[[https://www.wowhead.com/wotlk/quest=11436]],image=[[assets/images/quests/placeholder.png]],desc=[[Navigating the steep bluffs of Howling Fjord can be nerve-racking! I've come up with a solution to ease that burden by utilizing vrykul technology and dwarven ingenuity. With just a few adjustments and some fine tuning I've created Icehammer's harpoon controller! Of course it hasn't been tested, but that's what you're here for! Take the controller to the big gun in Nifflevar and use it to launch yourself into Valgarde. Report your victory to Zorek. Oh yea, you can keep the controller.]],logDesc=[[Use the large Vrykul Harpoon Gun in Nifflevar to launch yourself into Valgarde. Report your victory over the Vrykul to Guard Captain Zorek.]]}
DB[11437]={id=11437,name=[[[PH] Beer Garden A]],level=70,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11437]],image=[[assets/images/quests/placeholder.png]],desc=[[[PH] Speak to a Brewfest Barker in any Beer Garden outside of Darnassus,the Exodar,Shattrath City,or Stormwind City and receive a free pretzel.]],logDesc=[[[PH] Speak to a Brewfest Barker in any Beer Garden and receive a free pretzel.]],rewards={{id=33043,qty=1}}}
DB[11438]={id=11438,name=[[[PH] Beer Garden B]],level=70,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11438]],image=[[assets/images/quests/placeholder.png]],desc=[[[PH] Speak to a Brewfest Barker in any Beer Garden outside of Darnassus,the Exodar,Shattrath City,or Stormwind City and receive a free pretzel.]],logDesc=[[[PH] Speak to a Brewfest Barker in any Beer Garden and receive a free pretzel.]],rewards={{id=33043,qty=1}}}
DB[11443]={id=11443,zoneId=495,name=[[Daggercap Divin']],level=71,minLevel=68,giver=[[Harold Lagras]],giverType=[[NPC]],giverId=23730,ender=[[Harold Lagras]],enderType=[[NPC]],enderId=23730,wowhead=[[https://www.wowhead.com/wotlk/quest=11443]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey... Uh... What's up? What are you doing down here? Me? Oh... Well, you see... I'm... Um... I'm trying to clean this place up! Orders from Keller himself! He says to me, "Harry, I want you to put on a divin' bell and search the shipwrecks of Daggercap for OUR stuff..." Say, maybe you could lend me a hand while you're down here. Throughout the bay here are all kinds of goodies, err, I mean supplies. Go out and bring me back whatever you find. Use this diving helm so you don't run out of air and die.]],logDesc=[[Harold Lagras at the bottom of Daggercap Bay wants you to recover 10 Valgarde Supply Crates.]]}
DB[11444]={id=11444,name=[[[PH] Beer Garden A]],level=70,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11444]],image=[[assets/images/quests/placeholder.png]],desc=[[[PH] Speak to a Brewfest Barker in any Beer Garden outside of Darnassus,the Exodar,Shattrath City,or Stormwind City and receive a free pretzel.]],logDesc=[[[PH] Speak to a Brewfest Barker in any Beer Garden and receive a free pretzel.]],rewards={{id=33043,qty=1}}}
DB[11445]={id=11445,name=[[[PH] Beer Garden B]],level=70,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11445]],image=[[assets/images/quests/placeholder.png]],desc=[[[PH] Speak to a Brewfest Barker in any Beer Garden outside of Darnassus,the Exodar,Shattrath City,or Stormwind City and receive a free pretzel.]],logDesc=[[[PH] Speak to a Brewfest Barker in any Beer Garden and receive a free pretzel.]],rewards={{id=33043,qty=1}}}
DB[11448]={id=11448,zoneId=495,name=[[The Explorers' League Outpost]],level=71,minLevel=68,giver=[[Beltrand McSorf]],giverType=[[NPC]],giverId=23548,ender=[[Stanwad]],enderType=[[NPC]],enderId=24717,prevId=11278,rewardNextId=11474,wowhead=[[https://www.wowhead.com/wotlk/quest=11448]],image=[[assets/images/quests/placeholder.png]],desc=[[It's all a bunch of cryptic nonsense! Even with this cipher I can't make heads or tails of these tablets. Admittedly, cryptography is not my strong point. You'll need to take the cipher and tablets to our cryptographer, Stanwad. Unfortunately, I haven't heard from Stanwad in two weeks. He took a team of twenty scientists to the dig sites on the southeastern bluffs of the fjord and hasn't been heard from since. The best I can do is have McGoyver over there give you a lift with his flying machine.]],logDesc=[[Deliver McSorf's Bundle to Stanwad at the Explorers' League Outpost in Howling Fjord.]]}
DB[11452]={id=11452,zoneId=495,name=[[The Slumbering King]],level=72,minLevel=68,giverType=[[NPC]],ender=[[Captain Adams]],enderType=[[NPC]],enderId=23749,prevId=11235,wowhead=[[https://www.wowhead.com/wotlk/quest=11452]],image=[[assets/images/quests/placeholder.png]],desc=[[A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below. However, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron. If you hurry, you may be able to stop her before it is too late.]],logDesc=[[Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Westguard Keep and report your success to Captain Adams.]]}
DB[11453]={id=11453,zoneId=495,name=[[The Slumbering King]],level=72,minLevel=68,giverType=[[NPC]],ender=[[Chieftain Ashtotem]],enderType=[[NPC]],enderId=24129,prevId=11263,wowhead=[[https://www.wowhead.com/wotlk/quest=11453]],image=[[assets/images/quests/placeholder.png]],desc=[[A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below. However, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron. If you hurry, you may be able to stop her before it is too late.]],logDesc=[[Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Camp Winterhoof and report your success to Chieftain Ashtotem.]]}
DB[11455]={id=11455,zoneId=495,name=[[The Fragrance of Money]],level=71,minLevel=69,giver=[[Handsome Terry]],giverType=[[NPC]],giverId=24537,ender=[[Handsome Terry]],enderType=[[NPC]],enderId=24537,prevId=11434,rewardNextId=11473,wowhead=[[https://www.wowhead.com/wotlk/quest=11455]],image=[[assets/images/quests/placeholder.png]],desc=[[Us pirates are known for many things, but hygiene isn't one of them.  Most pirate ships be carrying five or six times as many rats as people. It's no wonder all the bears on this island caught the rabies soon after we moved in.  Long story short, the boss wants 'em all dead. It just so happens I know a recipe for a bear musk fragrance popular among Stormwind nobles.  We kill the bears and sell the musk.  I see a fine business opportunity for us here.  What say ye?]],logDesc=[[Handsome Terry at Scalawag Point in Howling Fjord wants you to obtain 4 Bear Musk from the Rabid Brown Bears in the surrounding area.]]}
DB[11456]={id=11456,zoneId=495,name=[[Feeding the Survivors]],level=71,minLevel=69,giver=[[Elder Atuik]],giverType=[[NPC]],giverId=24755,ender=[[Elder Atuik]],enderType=[[NPC]],enderId=24755,wowhead=[[https://www.wowhead.com/wotlk/quest=11456]],image=[[assets/images/quests/placeholder.png]],desc=[[We tuskarr rely mostly on our fish catch for sustenance.  In times of great need, however, we will on occasion hunt land animals. The nearby village of Iskaal was recently attacked by pirates and the survivors just keep pouring in. Our catch has been modest this week, but there are many shoveltusk on the island and their meat is plentiful. Aid my people by hunting these great beasts and obtaining their meat.]],logDesc=[[Elder Atuik at Kamagua in Howling Fjord wants you to obtain 6 pieces of Island Shoveltusk Meat from Island Shoveltusk in the Isle of Spears.]]}
DB[11457]={id=11457,zoneId=495,name=[[Arming Kamagua]],level=71,minLevel=69,giver=[[Elder Atuik]],giverType=[[NPC]],giverId=24755,ender=[[Elder Atuik]],enderType=[[NPC]],enderId=24755,prevId=11456,rewardNextId=11458,wowhead=[[https://www.wowhead.com/wotlk/quest=11457]],image=[[assets/images/quests/placeholder.png]],desc=[[Issliruk, the spirit of war, is depicted as a silver eagle by my people.  Our stories tell of how Issliruk fought against a hundred worgs to save his young. It is time for us, too, to fight against our foes to save our brethren.  We will need to craft new weapons.  The horns of the frostwing chimaera that make their home in the snowy parts of the island are sharp and are easily crafted into spear tips.  Bring me the best of these horns that you can find.]],logDesc=[[Elder Atuik wants you to obain 3 Chimaera Horns.]]}
DB[11458]={id=11458,zoneId=495,name=[[Avenge Iskaal]],level=71,minLevel=69,giver=[[Elder Atuik]],giverType=[[NPC]],giverId=24755,ender=[[Elder Atuik]],enderType=[[NPC]],enderId=24755,prevId=11457,wowhead=[[https://www.wowhead.com/wotlk/quest=11458]],image=[[assets/images/quests/placeholder.png]],desc=[[The totem of Issliruk is ready, $N, and for that I thank you.  We must cast our peaceful ways for the time being and strike at those who've attacked our land and our kin. The pirate slavers that raided Iskaal have lost their minds and slaughtered all their captives.  Go to Iskaal, to the east of here and do what must must be done.  Take this horn and call on my brethren should you need assistance.]],logDesc=[[Elder Atuik wants you to go to Iskaal and slay 8 Northsea Slavers.  Use the Horn of Kamagua should you need assistance.]]}
DB[11459]={id=11459,zoneId=495,name=[[Zeh'gehn Sez]],level=71,minLevel=69,giver=[[Zeh'gehn]],giverType=[[NPC]],giverId=24525,ender=[[Handsome Terry]],enderType=[[NPC]],enderId=24537,prevId=11473,rewardNextId=11476,wowhead=[[https://www.wowhead.com/wotlk/quest=11459]],image=[[assets/images/quests/placeholder.png]],desc=[[Is like dis, mon.  Ye be wantin' me 'elp spotting some craven bag-o-wire been cardin' da crew? Ye gotta bring me a croaker, matey.  Aft I an' I show ye who da blaggard be, mon.  Nah, nah, croaker show ye.  Ye'll ku fer yerself with yer own deadlights, yahso. Bring us a carver yahso too, 'atsteppa.  Galang, bucko.]],logDesc=[[Return to Handsome Terry to decipher what Zeh'gehn asked of you.]]}
DB[11460]={id=11460,zoneId=495,name=[[Trust is Earned]],level=71,minLevel=68,giver=[[Hidalgo the Master Falconer]],giverType=[[NPC]],giverId=24750,ender=[[Hidalgo the Master Falconer]],enderType=[[NPC]],enderId=24750,prevId=11278,rewardNextId=11465,wowhead=[[https://www.wowhead.com/wotlk/quest=11460]],image=[[assets/images/quests/placeholder.png]],desc=[[The first and most important factor in falconry is the bond between the falconer and $g his:her; bird. Trust must be earned by the master! <Hidalgo points to the falcons in the cage at his feet.> If you are to earn their trust you will first need to fill their bellies. The fjord rock falcon, as these birds are known, primarily eat grubs. Throughout the fjord you will find loose rocks that serve as breeding grounds for these grubs. Find a grub and return here to feed the falcons in the cage.]],logDesc=[[Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to find a Fjord Grub and feed it to one of the falcons in the cage by his feet.]]}
DB[11461]={id=11461,zoneId=495,name=[[DEPRECATED]],level=71,minLevel=69,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11461]],image=[[assets/images/quests/placeholder.png]]}
DB[11462]={id=11462,zoneId=495,name=[[Handsome Terry]],level=71,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=11434,wowhead=[[https://www.wowhead.com/wotlk/quest=11462]],image=[[assets/images/quests/placeholder.png]],desc=[[Your people paid me good money to infiltrate the Northsea Freebooters and get your foot in the door. I talked you up to a fellow in Scalawag Point called Handsome Terry.  I told him you come highly recommended. Put your disguise on and go see him.  Here comes someone to take you there. You're going to have to prove yourself a bit before they introduce you to their higher ups.  But that's all up to you.  Remember, $N, once you're inside you're on your own!]],logDesc=[[Don the Pirate Disguise and speak to Handsome Terry inside Scalawag point.]]}
DB[11463]={id=11463,zoneId=495,name=[[Pirates of the North Seas]],level=71,minLevel=69,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=11462,wowhead=[[https://www.wowhead.com/wotlk/quest=11463]],image=[[assets/images/quests/placeholder.png]],desc=[[The past few weeks have seen an increase in pirate attacks against our supply ships.  We've hired a goblin spy to pave the way for one of our agents to infiltrate the suspected pirates. This group of Northsea Freebooters operates out of Scalawag Point, on Garvan's Reef.  We don't know much about them, but we do know that Sylvanas wants their leader's head. You come very highly recommended, $N.  If you take on this task, we can keep our military focused against Arthas' forces.  Are you up to it?]],logDesc=[[Find Grezzix Spindlesnap on the northern end of Garvan's Reef off of the Southwestern coast of Howling Fjord.]]}
DB[11464]={id=11464,zoneId=495,name=[[Gambling Debt]],level=71,minLevel=69,giver=[[Taruk]],giverType=[[NPC]],giverId=24541,ender=[[Taruk]],enderType=[[NPC]],enderId=24541,prevId=11434,rewardNextId=11466,wowhead=[[https://www.wowhead.com/wotlk/quest=11464]],image=[[assets/images/quests/placeholder.png]],desc=[[I heard you did a little work for Terry.  I was hoping someone reliable would show up around these parts. See, pirates love to gamble.  They, however, do not love to pay their gambling debt. If you're interested in collecting some coin on my behalf, I'd be willing to give you a cut. Let's start you out with an easy one.  "Silvermoon" Harry's a bit of an eccentric, keeps all sorts of expensive blood elf knickknacks inside his tent - yet when I see him he always pretends to be broke.  Get my gold.]],logDesc=[[Taruk at Scalawag Point wants you to collect "Silvermoon" Harry's Debt.]]}
DB[11465]={id=11465,zoneId=495,name=[[The Ransacked Caravan]],level=71,minLevel=68,giver=[[Hidalgo the Master Falconer]],giverType=[[NPC]],giverId=24750,ender=[[Hidalgo the Master Falconer]],enderType=[[NPC]],enderId=24750,prevId=11460,rewardNextId=11468,wowhead=[[https://www.wowhead.com/wotlk/quest=11465]],image=[[assets/images/quests/placeholder.png]],desc=[[I was leading a caravan here from Valgarde that was attacked by Dragonflayers. I was the only survivor of that ambush. Unfortunately, I couldn't make it back here with the cargo of fjord turkeys. This is the perfect opportunity for you to get your feet wet with your rock falcon. <Hidalgo hands you a cage.> Take this falcon cage and head west down the road leading out of this camp. Use the falcon to capture the loose turkeys and return here when you've gathered enough. Remember to feed the falcon!]],logDesc=[[Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use the Trained Rock Falcon to recover 5 Fjord Turkeys. Return to Hidalgo with the cage once you have completed this task.]]}
DB[11466]={id=11466,zoneId=495,name=[[Jack Likes His Drink]],level=71,minLevel=69,giver=[[Taruk]],giverType=[[NPC]],giverId=24541,ender=[[Taruk]],enderType=[[NPC]],enderId=24541,prevId=11464,rewardNextId=11467,wowhead=[[https://www.wowhead.com/wotlk/quest=11466]],image=[[assets/images/quests/placeholder.png]],desc=[[Our next customer,  Jack Adams, won't be the pushover that Harry was.  He spends all day drinking with his friends, tough pirates all of them.  Let's not use force this time, could get ugly. See if you can use his drinking habit to your advantage.  There's only so much alcohol someone can handle before passing out. Maybe one of the bar wenches will be of assistance.  Once he's out, see if you can slip your hand into his pocket and get what's mine.]],logDesc=[[Taruk at Scalawag Point in Howling Fjord wants you to collect Jack Adams' Debt.]]}
DB[11467]={id=11467,zoneId=495,name=[[Dead Man's Debt]],level=71,minLevel=69,giver=[[Taruk]],giverType=[[NPC]],giverId=24541,ender=[[Taruk]],enderType=[[NPC]],enderId=24541,prevId=11466,wowhead=[[https://www.wowhead.com/wotlk/quest=11467]],image=[[assets/images/quests/placeholder.png]],desc=[[You might've heard of Black Conrad, he's a famous pirate around these parts. Well, he had a thing for gambling on my fights.  He had a thing for not paying, too. I'd love to collect, but trouble is... he's dead. I was about ready to write the whole thing off, when I came across this... <Taruk unfolds a map of the Isle of Spears with an X on a northeastern plateau.> He hid his treasure on tuskarr land.  I want you to get it.  I'll be damned if I let that bilge sucker get away without paying.]],logDesc=[[Taruk at Scalawag Point wants you to search for Black Conrad's Treasure on the plateau in the northeastern end of the Isle of Spears, just north of Iskaal.]],rewards={{id=34119,qty=1}}}
DB[11468]={id=11468,zoneId=495,name=[[Falcon Versus Hawk]],level=71,minLevel=68,giver=[[Hidalgo the Master Falconer]],giverType=[[NPC]],giverId=24750,ender=[[Hidalgo the Master Falconer]],enderType=[[NPC]],enderId=24750,prevId=11465,rewardNextId=11470,wowhead=[[https://www.wowhead.com/wotlk/quest=11468]],image=[[assets/images/quests/placeholder.png]],desc=[[Do you feel the closeness, $N? Surely you feel a true bond forming between you and your falcon. Would you believe me if I told you that when the time is right you'll be able to see through the eyes of your bird? Aye, it is the ultimate level of falconry. But first you must hunt more! The bird must hone and quicken its reflexes. Send it against a more formidable opponent! The fjord hawks of the region make the tops of the trees around us their homes. They shall be your next target!]],logDesc=[[Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 10 Fjord Hawks. Return to Hidalgo with the cage when you have completed this task. ]]}
DB[11469]={id=11469,zoneId=495,name=[[Swabbin' Soap]],level=71,minLevel=69,giver=[[Scuttle Frostprow]],giverType=[[NPC]],giverId=24784,ender=[[Scuttle Frostprow]],enderType=[[NPC]],enderId=24784,prevId=11509,wowhead=[[https://www.wowhead.com/wotlk/quest=11469]],image=[[assets/images/quests/placeholder.png]],desc=[[Yeah, I got to get the deck swabbed spotless afore Mad Jonah comes 'round. An' I ain't gonna do it on my hands and knees neither! Problem is, we're all outa soap. That's more your problem than mine though, mate. Being the newbie 'round here, I gots a special trip for ya to make. Up on the northwest coast of this island, there's a whole mess o' sea lions. Amongst the nearby ice floes you'll find the alpha bull, Big Roy. Bring me back his blubber and I'll magic-up the best soap ya ever seen!]],logDesc=[[Scuttle Frostprow wants you to obtain Big Roy's Blubber as the main ingredient for her magic swabbin' soap. Return to her on the eastern pirate ship at Scalawag Point when you have it.]]}
DB[11470]={id=11470,zoneId=495,name=[[There Exists No Honor Among Birds]],level=71,minLevel=68,giver=[[Hidalgo the Master Falconer]],giverType=[[NPC]],giverId=24750,ender=[[Hidalgo the Master Falconer]],enderType=[[NPC]],enderId=24750,prevId=11468,wowhead=[[https://www.wowhead.com/wotlk/quest=11470]],image=[[assets/images/quests/placeholder.png]],desc=[[You are most definitely ready for the next step in falconry, $N. Take your trained falcon east of here, to the vrykul hawk roost near the Stonewall Lift. From the roost you will send out your falcon to steal the eggs of the hawks. Their nests will be located in remote areas of the cliff walls surrounding the roost. Locate those nests and use your falcon to scavenge for the eggs! Beware the fjord hawk matriarchs, $N. Should you come under attack, use your falcon's escape and soar abilities to flee!]],logDesc=[[Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 8 Fjord Hawk Eggs. Return to Hidalgo with the cage when you have completed this task.]],choiceRewards={{id=35860,qty=1},{id=35859,qty=1},{id=35861,qty=1},{id=35862,qty=1}}}
DB[11471]={id=11471,zoneId=495,name=[[The Jig is Up]],level=71,minLevel=69,giver=[[Annie Bonn]],giverType=[[NPC]],giverId=24741,ender=[[Annie Bonn]],enderType=[[NPC]],enderId=24741,prevId=11480,wowhead=[[https://www.wowhead.com/wotlk/quest=11471]],image=[[assets/images/quests/placeholder.png]],desc=[[I know why you're here, $N.  You've been sent to kill our leader, Jonah Sterling. I'd like to offer my help.  Jonah's leadership threatens our operation. Attacking the Horde and the Alliance fleets simultaneously?  Suicidal.  Trying to sell the tuskarr as slaves when they die days after leaving this climate?  Disastrous. Jonah's hideout is located inside a cave west of here.  Bring me his spyglass as proof of the deed  and my first action as lead will be to end all attacks against your allies.]],logDesc=[[Annie Bonn at Scalawag Point wants you to bring her Jonah Sterling's Spyglass.]],choiceRewards={{id=38258,qty=1},{id=38259,qty=1},{id=38257,qty=1}}}
DB[11472]={id=11472,zoneId=495,name=[[The Way to His Heart...]],level=-1,minLevel=69,giver=[[Anuniaq]],giverType=[[NPC]],giverId=24810,ender=[[Anuniaq]],enderType=[[NPC]],enderId=24810,prevId=11469,wowhead=[[https://www.wowhead.com/wotlk/quest=11472]],image=[[assets/images/quests/placeholder.png]],desc=[[The Northsea Pirates slaughtered the isles' alpha sea lion bull, Big Roy. They made soap from him to clean the decks of their ships! <Anuniaq sighs.> Now the sea lions won't mate. Help me to repopulate their numbers. The reef bulls can be found at the Twin Shores to the southeast. They crave the tasty reef fish that can be found on the east and west sides of the isles. Take this net and gather enough fish, at least a dozen -- maybe more, to lure a bull across the strait to a reef cow.]],logDesc=[[Toss Tasty Reef Fish at a Reef Bull to lead it to a Reef Cow. Once you have helped the two to find true love, return to Anuniaq at Kamagua.]]}
DB[11473]={id=11473,zoneId=495,name=[[A Traitor Among Us]],level=71,minLevel=69,giver=[[Handsome Terry]],giverType=[[NPC]],giverId=24537,ender=[[Zeh'gehn]],enderType=[[NPC]],enderId=24525,prevId=11455,rewardNextId=11459,wowhead=[[https://www.wowhead.com/wotlk/quest=11473]],image=[[assets/images/quests/placeholder.png]],desc=[[Our second in command, Annie Bonn, has been acting rather paranoid as of late.  She seems sure we have an infiltrator in our ranks, can ye believe it? Anyhow, we have a foolproof way of uncovering rats around these parts.  See, good ole' Zeh'gehn over here happens to be an authentic witch doctor.  His family hails all the way from Zul... something or other. Go let him know that we're in need of his divination skills.  I must warn ye, $N, only one or two of us can understand anything Zeh'gehn says.]],logDesc=[[Speak to Zeh'gehn at Scalawag Post.]]}
DB[11474]={id=11474,zoneId=495,name=[[Problems on the High Bluff]],level=71,minLevel=68,giver=[[Stanwad]],giverType=[[NPC]],giverId=24717,ender=[[Walt]],enderType=[[NPC]],enderId=24807,prevId=11448,rewardNextId=11475,wowhead=[[https://www.wowhead.com/wotlk/quest=11474]],image=[[assets/images/quests/placeholder.png]],desc=[[As usual, the real work is left up to me and my crew. Thankfully McSorf's team didn't die for nothin'. The cipher they recovered will help us crack the stuff we've found up here - that is if we can ever get back to it! Damned iron dwarves have sprung up like leaks all over the place and are now attemptin' to bury the sites! Can you believe it? Bastards want to bury our finds! Anyhow, talk to Walt over yonder. He'll get you started.]],logDesc=[[Speak with Walt.]]}
DB[11475]={id=11475,zoneId=495,name=[[Tools to Get the Job Done]],level=71,minLevel=68,giver=[[Walt]],giverType=[[NPC]],giverId=24807,ender=[[Walt]],enderType=[[NPC]],enderId=24807,prevId=11474,wowhead=[[https://www.wowhead.com/wotlk/quest=11475]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been studying this deactivated construct for days, $N. I think I can create a reasonable facsimile of the golem that would have room inside to fit one passenger. The idea being that it would fool those iron dwarves and allow us to get inside Baelgun's. Now I'm not gonna be able to make anything with a hammer and poker. I need my tools! Unfortunately I left those behind at Ivald's Ruin when the iron dwarves first attacked. Get me my tools! Ivald's Ruin is located far to the northeast.]],logDesc=[[Walt at the Explorers' League Outpost in the Howling Fjord wants you to recover his Building Tools.]]}
DB[11476]={id=11476,zoneId=495,name=[[A Carver and a Croaker]],level=71,minLevel=69,giver=[[Handsome Terry]],giverType=[[NPC]],giverId=24537,ender=[[Zeh'gehn]],enderType=[[NPC]],enderId=24525,prevId=11459,wowhead=[[https://www.wowhead.com/wotlk/quest=11476]],image=[[assets/images/quests/placeholder.png]],desc=[[Some of the pirates around here... we have our own special way of talking.  Zeh'gehn has... many different special ways of talking... all mixed together. From what I can tell he wants a frog and a knife. "Silvermoon" Harry might have a knife on the cheap.  There's frogs all over town, just grab one and bring it to him along with the knife. I'd hate to be in the poor critter's shoes, if you know what I mean.]],logDesc=[[Get a Shiny Knife from "Silvermoon" Harry and capture a Scalawag Frog.  Bring these to Zeh'Gehn at Scalawag Point.]]}
DB[11477]={id=11477,zoneId=495,name=[[Out of My Element?]],level=70,minLevel=68,giver=[[Donny]],giverType=[[NPC]],giverId=24811,ender=[[Donny]],enderType=[[NPC]],enderId=24811,prevId=11278,wowhead=[[https://www.wowhead.com/wotlk/quest=11477]],image=[[assets/images/quests/placeholder.png]],desc=[[Keep it down, $r. These iron dwarves are quick on the trigger. Now don't let the activities down in the dig fool you. Those steel-skinned abominations aren't digging anything up! No sir - on the contrary - they're burying the site! For whatever whacked out reason, they don't want anyone finding this place. What kind of dwarf buries ancient relics and dig sites? I'll tell you what kind: the kind you kill with reckless abandon! Get in there and take 'em out!]],logDesc=[[Donny at Ivald's Ruin in the Howling Fjord wants you to kill 10 Iron Rune Destroyers, 5 Iron Rune Laborers and 2 Iron Rune Sages.]]}
DB[11478]={id=11478,zoneId=495,name=[[Outpost Over Yonder...]],level=71,minLevel=68,giver=[[Donny]],giverType=[[NPC]],giverId=24811,ender=[[Stanwad]],enderType=[[NPC]],enderId=24717,prevId=11278,wowhead=[[https://www.wowhead.com/wotlk/quest=11478]],image=[[assets/images/quests/placeholder.png]],desc=[[I see that you haven't visited my brothers at the Explorers' League Outpost south of here. Why don't you do Donny a favor and deliver this message to Stanwad. He'll be interested to hear about the activities of the iron dwarves up here. Like I said, mount up and start heading south. You'll see the outpost right before you get to Baelgun's.]],logDesc=[[Deliver Donny's Letter to Stanwad at the Explorers' League Outpost.]]}
DB[11479]={id=11479,zoneId=495,name=[["Crowleg" Dan]],level=71,minLevel=69,giver=[[Zeh'gehn]],giverType=[[NPC]],giverId=24525,ender=[[Handsome Terry]],enderType=[[NPC]],enderId=24537,prevId=11476,rewardNextId=11480,wowhead=[[https://www.wowhead.com/wotlk/quest=11479]],image=[[assets/images/quests/placeholder.png]],desc=[[Croaker's spoken, matey. "Crowleg" Dan's on da ship yonder. Best go trace that blaggard, mon.  Show'im dis set's not fe be crossed.  Gaan back fe Terry when ye keelhaul 'is behind.]],logDesc=[[Confront "Crowleg" Dan, who is in one of the ships at Scalawag Point. Speak to Handsome Terry when you've completed this task.]]}
DB[11480]={id=11480,zoneId=495,name=[[Meet Number Two]],level=71,minLevel=69,giver=[[Handsome Terry]],giverType=[[NPC]],giverId=24537,ender=[[Annie Bonn]],enderType=[[NPC]],enderId=24741,prevId=11479,rewardNextId=11471,wowhead=[[https://www.wowhead.com/wotlk/quest=11480]],image=[[assets/images/quests/placeholder.png]],desc=[[All the good work you've done for us hasn't gone unnoticed, $N.  Our second in command, the delightful Annie Bonn, is incredibly impressed with what you've done so far and wants to meet you.]],logDesc=[[Speak to Annie Bonn at Scalawag Point.]]}
DB[11483]={id=11483,zoneId=495,name=[[We Can Rebuild It]],level=71,minLevel=68,giver=[[Walt]],giverType=[[NPC]],giverId=24807,ender=[[Walt]],enderType=[[NPC]],enderId=24807,prevId=11475,nextId=11485,exGroup=-11483,wowhead=[[https://www.wowhead.com/wotlk/quest=11483]],image=[[assets/images/quests/placeholder.png]],desc=[[Tools? Check. Materials? Negative. If we're going to build this thing, you're going to have to get me the materials. First things first, $N. For the skeletal structure I'm going to need a large barrel from Nifflevar, some dark iron ingots from Valgarde, and industrial strength rope from Baleheim. Nifflevar and Baleheim are vrykul towns northwest of here. Valgarde is located in Daggercap Bay, also to the northwest. Speak with McGoyver to get the ingots. He'll fly you back here once you're all done.]],logDesc=[[Walt at the Explorers' League Outpost in the Howling Fjord wants you to bring him a Large Barrel, Industrial Strength Rope and Dark Iron Ingots.]]}
DB[11484]={id=11484,zoneId=495,name=[[We Have the Technology]],level=71,minLevel=68,giver=[[Walt]],giverType=[[NPC]],giverId=24807,ender=[[Walt]],enderType=[[NPC]],enderId=24807,prevId=11475,nextId=11485,exGroup=-11483,wowhead=[[https://www.wowhead.com/wotlk/quest=11484]],image=[[assets/images/quests/placeholder.png]],desc=[[While the infrastructure for a piece of machinery like this is important, we can't underestimate the appearance of the construct. If we're to fool the iron dwarves the clone must be exact! I can make this happen. Bring me a pristine shoveltusk hide from the shoveltusk of this region and steel ribbing from vrykul in Nifflevar or Baleheim to the northwest.]],logDesc=[[Walt at the Explorers' League Outpost in the Howling Fjord wants you to bring him a Pristine Shoveltusk Hide and Steel Ribbing.]]}
DB[11485]={id=11485,zoneId=495,name=[[Iron Rune Constructs and You: Rocket Jumping]],level=71,minLevel=68,giver=[[Walt]],giverType=[[NPC]],giverId=24807,ender=[[Walt]],enderType=[[NPC]],enderId=24807,rewardNextId=11489,wowhead=[[https://www.wowhead.com/wotlk/quest=11485]],image=[[assets/images/quests/placeholder.png]],desc=[[Alright, $N; the time has come for you to climb inside this thing and learn how to use its basic abilities. When you're ready, get on the work bench and I'll get you situated inside the construct. Your first lesson is going to be using the construct's transportation system. You'll notice that the iron dwarves have set up special rune carvings around the dig site. Their constructs use those rune carvings to power up and fly from point to point. Try it with the rune carving I built here. ]],logDesc=[[Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Rocket Jump ability at Walt's Iron Rune Carving. Dismiss your construct by dismissing it from the pet window once you have completed the quest.]]}
DB[11489]={id=11489,zoneId=495,name=[[Iron Rune Constructs and You: Collecting Data]],level=71,minLevel=68,giver=[[Walt]],giverType=[[NPC]],giverId=24807,ender=[[Walt]],enderType=[[NPC]],enderId=24807,prevId=11485,rewardNextId=11491,wowhead=[[https://www.wowhead.com/wotlk/quest=11489]],image=[[assets/images/quests/placeholder.png]],desc=[[The most important part of your job while controlling the construct is the collection of data. I've placed an iron dwarf relic in the cart over yonder. It's the floating, lightning infused crystal. Get on the work bench and I'll put you back in the construct. Once you're back in the driver's seat, use the construct's data collection ability to pick up the test data.]],logDesc=[[Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Collect Data ability while standing near the Iron Dwarf Relic. Dismiss your construct by dismissing it from the pet window once you have completed the quest.]]}
DB[11491]={id=11491,zoneId=495,name=[[Iron Rune Constructs and You: The Bluff]],level=71,minLevel=68,giver=[[Walt]],giverType=[[NPC]],giverId=24807,ender=[[Walt]],enderType=[[NPC]],enderId=24807,prevId=11489,wowhead=[[https://www.wowhead.com/wotlk/quest=11491]],image=[[assets/images/quests/placeholder.png]],desc=[[You always gotta have a contingency plan in case your main plan backfires! That's why I've built in some anti-intelligence systems into the construct. Your shiny new ride might rouse some suspicion while you're at Baelgun's excavation site. That's what your bluff ability is for! Just use that any time you're confronted and you'll be safe from harm. Test it out on Lebronski by walking on his rug. Once he starts huffin' and puffin', use the bluff! Get on the work bench when you're ready to begin.]],logDesc=[[Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Bluff ability on Lebronski after you've walked on his rug. Dismiss your construct by dismissing it from the pet window once you have completed the quest. ]]}
DB[11493]={id=11493,name=[[UNUSED]],name_loc=[[UNUSED]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11493]],image=[[assets/images/quests/placeholder.png]]}
DB[11494]={id=11494,zoneId=495,name=[[Lightning Infused Relics]],level=71,minLevel=68,giver=[[Walt]],giverType=[[NPC]],giverId=24807,ender=[[Walt]],enderType=[[NPC]],enderId=24807,prevId=11491,nextId=11501,exGroup=-11494,wowhead=[[https://www.wowhead.com/wotlk/quest=11494]],image=[[assets/images/quests/placeholder.png]],desc=[[Your construct is ready to go. All abilities have been given a once over and I've programmed the machine to both comprehend and speak the language of the titans. Take the construct to Baelgun's Excavation Site, due south of here, and collect data from the lightning infused relics that litter the site. Remember to bluff any iron dwarves that suspect your construct to be a fake. And don't forget about rocket jumping from rune to rune to get around in there! Get on the table when you're ready!]],logDesc=[[Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Collect Data ability to collect 15 sets of Iron Rune Data. Dismiss your construct by dismissing it from the pet window once you have completed the quest.]],choiceRewards={{id=35845,qty=1},{id=35844,qty=1},{id=35846,qty=1},{id=35848,qty=1}}}
DB[11495]={id=11495,zoneId=495,name=[[The Delicate Sound of Thunder]],level=71,minLevel=68,giver=[[Walt]],giverType=[[NPC]],giverId=24807,ender=[[Walt]],enderType=[[NPC]],enderId=24807,prevId=11491,nextId=11501,exGroup=-11494,wowhead=[[https://www.wowhead.com/wotlk/quest=11495]],image=[[assets/images/quests/placeholder.png]],desc=[[The cavern that we opened at Baelgun's was the one place that most steered clear of... Can't say I blame 'em. The sound of thunder shot out of that cave, $N! Loud, booming thunder! I think near the end, it was abandoned by all. Bad, bad things happened to any that went in to explore - most never coming back. I want you to check that cave out while you're at Baelgun's. Explore around the titan statue inside and report back with your findings.]],logDesc=[[Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct to explore the thundering cave at Baelgun's Excavation Site. Dismiss your construct by dismissing it from the pet window once you have completed the quest.]],choiceRewards={{id=35851,qty=1},{id=35849,qty=1},{id=35852,qty=1},{id=35856,qty=1}}}
DB[11501]={id=11501,zoneId=495,name=[[News From the East]],level=71,minLevel=68,giver=[[Walt]],giverType=[[NPC]],giverId=24807,ender=[[Captain Adams]],enderType=[[NPC]],enderId=23749,nextId=11157,wowhead=[[https://www.wowhead.com/wotlk/quest=11501]],image=[[assets/images/quests/placeholder.png]],desc=[[Westguard needs to know what's going on here, $N. I want you to personally deliver the news to Captain Adams. Whenever you're ready, let me know and I'll put you back in the construct for one final flight. It'll take you to Westguard Keep, but more than likely blow up in the process. It's been a pleasure...]],logDesc=[[Speak with Captain Adams at Westguard Keep.]],choiceRewards={{id=35857,qty=1},{id=35858,qty=1}}}
DB[11504]={id=11504,zoneId=495,name=[[The Dead Rise!]],level=71,minLevel=68,giver=[[Orfus of Kamagua]],giverType=[[NPC]],giverId=23804,ender=[[Orfus of Kamagua]],enderType=[[NPC]],enderId=23804,rewardNextId=11507,wowhead=[[https://www.wowhead.com/wotlk/quest=11504]],image=[[assets/images/quests/placeholder.png]],desc=[[The path east of us is a primary hunting trail of the tuskarr. At least that's what it used to be... More recently our hunters have been returning to Kamagua claiming that the dead have risen and are out for blood! That is what has brought my son and me here. Elder Atuik asks that we find resolution in the bluffs. Will you assist us in our time of need? I seek heroes willing to brave the perils of Shield Hill, southeast of here. Search the desecrated graves for clues and return your findings to me.]],logDesc=[[Orfus of Kamagua at the Ancient Lift in the Howling Fjord wants you to find Fengir's Clue, Rodin's Clue, Isuldof's Clue and Windan's Clue.]]}
DB[11507]={id=11507,zoneId=495,name=[[Elder Atuik and Kamagua]],level=71,minLevel=68,giver=[[Orfus of Kamagua]],giverType=[[NPC]],giverId=23804,ender=[[Elder Atuik]],enderType=[[NPC]],enderId=24755,prevId=11504,rewardNextId=11508,wowhead=[[https://www.wowhead.com/wotlk/quest=11507]],image=[[assets/images/quests/placeholder.png]],desc=[[<Orfus bundles up the clues you brought him.> My people are bitterly entrenched in a war with the Northsea Freebooters. If any tuskarr could help us in our quest to right the wrongs of the pirates, it will be Elder Atuik of Kamagua. You must take these clues to him at once. To get to Kamagua you must take the Ancient Lift, behind me. Take the lift directly to Kamagua and find Elder Atuik.]],logDesc=[[Orfus of Kamagua in the Howling Fjord wants you to deliver Orfus's Bundle to Elder Atuik at Kamagua.]]}
DB[11508]={id=11508,zoneId=495,name=[[Grezzix Spindlesnap]],level=71,minLevel=68,giver=[[Elder Atuik]],giverType=[[NPC]],giverId=24755,ender=[[Grezzix Spindlesnap]],enderType=[[NPC]],enderId=24643,prevId=11507,rewardNextId=11509,wowhead=[[https://www.wowhead.com/wotlk/quest=11508]],image=[[assets/images/quests/placeholder.png]],desc=[[The pirate thieves have set up port at Scalawag Point, far to the south. Unfortunately, they have fortified their camp with many deadly defenses. There is someone that might be able to assist us in infiltrating Scalawag. A pirate mercenary by the name of Grezzix Spindlesnap recently came to our village in search of food and shelter. In exchange he gives us information about our enemies and feeds them misinformation about our attack plans. Seek him out at his ship just off the coast here - southwest.]],logDesc=[[Speak with Grezzix Spindlesnap.]]}
DB[11509]={id=11509,zoneId=495,name=[[Street "Cred"]],level=71,minLevel=68,giver=[[Grezzix Spindlesnap]],giverType=[[NPC]],giverId=24643,ender=[["Silvermoon" Harry]],enderType=[[NPC]],enderId=24539,prevId=11508,rewardNextId=11510,wowhead=[[https://www.wowhead.com/wotlk/quest=11509]],image=[[assets/images/quests/placeholder.png]],desc=[[The Northsea Freebooters all fear and respect Grezzix. I'm thinking they recognize my special talents and envy my amazing ship. All you need to do is tag along with my cabin boy, Lou, and you'll be in like... In like tin. Pirates love tin. Just talk to Lou when you're ready to go and he'll take you to Scalawag. Oh yea, you'll want to talk to "Silvermoon" Harry first. He'll have more information on the stuff they pilfered. Just watch what you say around him. He's a freak... crazy for blood elves.]],logDesc=[[Speak with "Silvermoon" Harry at Scalawag Point about the missing Vrykul artifacts.]]}
DB[11510]={id=11510,zoneId=495,name=[["Scoodles"]],level=71,minLevel=68,giver=[["Silvermoon" Harry]],giverType=[[NPC]],giverId=24539,ender=[["Silvermoon" Harry]],enderType=[[NPC]],enderId=24539,prevId=11509,wowhead=[[https://www.wowhead.com/wotlk/quest=11510]],image=[[assets/images/quests/placeholder.png]],desc=[[One of the first things Jonah Sterling did after he went crazy was to take my prized sin'dorei scrying crystal and feed it to the bane of my existence, "Scoodles" the orca. No I didn't name the damned thing. I just know that she swims out past the ships directly southeast of Scalawag. Kill that overinflated goldfish and rip out my beautiful sin'dorei crystal from its stomach. Do this and we can get down to business.]],logDesc=[["Silvermoon" Harry at Scalawag Point wants you to recover his Sin'dorei Scrying Crystal from the orca, "Scoodles."]]}
DB[11511]={id=11511,zoneId=495,name=[[The Staff of Storm's Fury]],level=71,minLevel=68,giver=[["Silvermoon" Harry]],giverType=[[NPC]],giverId=24539,ender=[[Orfus of Kamagua]],enderType=[[NPC]],enderId=23804,prevId=11510,nextId=11568,exGroup=-11511,wowhead=[[https://www.wowhead.com/wotlk/quest=11511]],image=[[assets/images/quests/placeholder.png]],desc=[[Those artifacts are cursed and you'd be crazy to go looking for them, $r. I know for certain that anyone that's come into direct contact with any of those items has either gone mad or been killed. Take that staff, for example. Last I heard the ship that held it was abandoned and left to rot on the coast of the Isle of Spears, north of here. If you want that thing, check the ship's hold. Whatever you do, don't bring that staff back here! And steer clear of Abdul! He'll tear your heart out.]],logDesc=[[Recover the Staff of Storm's Fury and deliver it to Orfus of Kamagua in the Howling Fjord. ]]}
DB[11512]={id=11512,zoneId=495,name=[[The Frozen Heart of Isuldof]],level=71,minLevel=68,giver=[["Silvermoon" Harry]],giverType=[[NPC]],giverId=24539,ender=[[Orfus of Kamagua]],enderType=[[NPC]],enderId=23804,prevId=11510,nextId=11568,exGroup=-11511,wowhead=[[https://www.wowhead.com/wotlk/quest=11512]],image=[[assets/images/quests/placeholder.png]],desc=[[Some say Jonah was never quite right in the head, but I know the truth. It was the heart. That damned frozen heart! I saw the change in him the second he pulled it from the grave. I could see the blood freeze in his veins... It was then that the madness truly took over. He left us to hole up in his cave on the north side of this island. Last I heard he had thrown the heart in the back of his bear den. Too little, too late... I'll kill you myself if you even think about bringing that heart back here!]],logDesc=[[Recover the Frozen Heart of Isuldof and deliver it to Orfus of Kamagua in the Howling Fjord.]]}
DB[11519]={id=11519,zoneId=495,name=[[The Lost Shield of the Aesirites]],level=71,minLevel=68,giver=[["Silvermoon" Harry]],giverType=[[NPC]],giverId=24539,ender=[[Captain Ellis]],enderType=[[NPC]],enderId=24910,prevId=11510,rewardNextId=11527,wowhead=[[https://www.wowhead.com/wotlk/quest=11519]],image=[[assets/images/quests/placeholder.png]],desc=[[If you listen real close you can hear cannon fire coming from the northeast. That's Captain Ellis's ship, Sister Mercy. Thing is, Ellis and his entire crew were killed 'bout a month ago. <Harry nods.> Ghost ship... If it's info you be wantin' 'bout the shield, Ellis is the man to ask. Sister Mercy docks on the small island between here and Sorlof's Strand to pick up more souls for the ship's crew 'bout once every five minutes. There be no shortage of souls 'round these parts...]],logDesc=[[Speak with Captain Ellis aboard the Sister Mercy.]]}
DB[11522]={id=11522,name=[[[PH]For whatever reason,(TBD),

you are to collect 5 Razorth]],level=70,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11522]],image=[[assets/images/quests/placeholder.png]],desc=[[[PH]For whatever reason,(TBD), you are to collect 5 Razorthorn Roots. These can only be found in a remote location Northeast of Shattrath,just as you crest the rise to Hellfire Penninsula.]]}
DB[11527]={id=11527,zoneId=495,name=[[Mutiny on the Mercy]],level=71,minLevel=68,giver=[[Captain Ellis]],giverType=[[NPC]],giverId=24910,ender=[[Captain Ellis]],enderType=[[NPC]],enderId=24910,prevId=11519,rewardNextId=11529,wowhead=[[https://www.wowhead.com/wotlk/quest=11527]],image=[[assets/images/quests/placeholder.png]],desc=[[Aye, we got problems, matey. Me gunners have mutinied! M'n'the crew up top be tryin' to kick Sorlof's keester while dealin' with the mutinous gunners down'blo. Ye're gonna have to go down'blo and deal with those mutinous sea dogs and take their blastin' powder for the big'un o'er on the poop deck. With ye mannin' the big'un, Sorlof is sure to die and give up the booty!]],logDesc=[[Captain Ellis aboard the Sister Mercy in the Howling Fjord has asked that you recover 5 Barrels of Blasting Powder from the ship's hold. ]]}
DB[11529]={id=11529,zoneId=495,name=[[Sorlof's Booty]],level=71,minLevel=68,giver=[[Captain Ellis]],giverType=[[NPC]],giverId=24910,ender=[[Captain Ellis]],enderType=[[NPC]],enderId=24910,prevId=11527,rewardNextId=11530,wowhead=[[https://www.wowhead.com/wotlk/quest=11529]],image=[[assets/images/quests/placeholder.png]],desc=[[Me crew is gonna get the big'un all primed an'ready for ya, matey. She's restin' snuggly on the bow, o'er on the other side of the ship. Go'n man it and be ready to fire when Sorlof is in our sights! Once we take that landlubber down, ye'll have to recover the booty for us, seein' as how we can't leave the damned ship! Bring that booty back to me and ye'll get your cut - the shield...]],logDesc=[[Slay Sorlof using the Big Gun and recover Sorlof's Booty. Return Sorlof's Booty to Captain Ellis aboard the Sister Mercy.]]}
DB[11530]={id=11530,zoneId=495,name=[[The Shield of the Aesirites]],level=71,minLevel=68,giver=[[Captain Ellis]],giverType=[[NPC]],giverId=24910,ender=[[Orfus of Kamagua]],enderType=[[NPC]],enderId=23804,prevId=11529,nextId=11568,exGroup=-11511,wowhead=[[https://www.wowhead.com/wotlk/quest=11530]],image=[[assets/images/quests/placeholder.png]],desc=[[Here's yer shield. Me hopes it doesn't curse ye like it did me'n'me crew. Ye don't have to go home, but ye can't stay here... I be certain that thar be some that would be interested in getting' it back. Now get that thing off me ship!]],logDesc=[[Return the Shield of the Aesirites to Orfus of Kamagua at the Ancient Lift in the Howling Fjord.]]}
DB[11559]={id=11559,zoneId=3537,name=[[Winterfin Commerce]],level=71,minLevel=69,giver=[[King Mrgl-Mrgl]],giverType=[[NPC]],giverId=25197,ender=[[Ahlurglgr]],enderType=[[NPC]],enderId=25206,prevId=11571,wowhead=[[https://www.wowhead.com/wotlk/quest=11559]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you can speak with the Winterfin, it is time for you to let them get to know you. One of the best ways to do that is to conduct business with them. The murlocs prize clams over any other object and their only surviving merchant is Ahlurglgr. If I were you, I'd collect a handful of Winterfin clams and give them to him as a gift. The clams can be found all over down in the trench, as well as across it in the Winterfin village and their caverns.]],logDesc=[[Collect 5 Winterfin Clams and deliver them to Ahlurglgr at Winterfin Retreat.]]}
DB[11560]={id=11560,zoneId=3537,name=[[Oh Noes, the Tadpoles!]],level=71,minLevel=69,giver=[[King Mrgl-Mrgl]],giverType=[[NPC]],giverId=25197,ender=[[King Mrgl-Mrgl]],enderType=[[NPC]],enderId=25197,prevId=11559,rewardNextId=11562,wowhead=[[https://www.wowhead.com/wotlk/quest=11560]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh good, you're back! When the landslide at the village across the water exposed the caverns, a malevolent lobstrok, known as Claximus, came out of the caves and stole the Winterfin tadpoles away. Something happened to all of the murlocs that followed him in there, and when they re-emerged, they were under his control. $C, you must swim across the waters and rescue the Winterfin tadpoles in the village and caverns. The future of the Winterfin tribe depends upon you!]],logDesc=[[King Mrgl-Mrgl has asked you to rescue 20 Winterfin Tadpoles. Return to him at Winterfin Retreat once you have done so.]],choiceRewards={{id=37034,qty=1},{id=37558,qty=1},{id=37508,qty=1},{id=37527,qty=1}}}
DB[11561]={id=11561,zoneId=3537,name=[[Them!]],level=71,minLevel=69,giver=[[Brglmurgl]],giverType=[[NPC]],giverId=25199,ender=[[Brglmurgl]],enderType=[[NPC]],enderId=25199,prevId=11559,wowhead=[[https://www.wowhead.com/wotlk/quest=11561]],image=[[assets/images/quests/placeholder.png]],desc=[[Our brothers and sisters across the water are now our mortal enemies. They have kidnapped our tadpoles, driven us out of our village, and killed more of us than I can count. Prove yourself, $r! Swim across the rift and slay them! Despite the favor that the new king has shown you, only then will we consider accepting you here. Fail to do so, and you might as well leave now and never return!]],logDesc=[[Brglmurgl at Winterfin Retreat has asked you to kill 15 Winterfin murlocs. Any combination of warriors, oracles, and shorestrikers will do.]]}
DB[11562]={id=11562,zoneId=3537,name=[[I'm Being Blackmailed By My Cleaner]],level=71,minLevel=69,giver=[[King Mrgl-Mrgl]],giverType=[[NPC]],giverId=25197,ender=[[Mrmrglmr]],enderType=[[NPC]],enderId=25205,prevId=11560,rewardNextId=11563,wowhead=[[https://www.wowhead.com/wotlk/quest=11562]],image=[[assets/images/quests/placeholder.png]],desc=[[I have something embarrassing to admit: I'm being blackmailed! Mrmrglmr agreed to clean some of my things, and got hold of my spare murloc costume. He's threatening to reveal my true nature to the other murlocs. I need not explain to you what a disaster that would be! Besides, I have a plan that's going to require that we get that costume back. Please, $N, go to Mrmrglmr at the other end of the Retreat to the north and do whatever he asks of you.]],logDesc=[[King Mrgl-Mrgl has asked you to speak with Mrmrglmr at the northwest end of Winterfin Retreat.]]}
DB[11563]={id=11563,zoneId=3537,name=[[Grmmurggll Mrllggrl Glrggl!!!]],level=71,minLevel=69,giver=[[Mrmrglmr]],giverType=[[NPC]],giverId=25205,ender=[[Mrmrglmr]],enderType=[[NPC]],enderId=25205,prevId=11562,rewardNextId=11565,wowhead=[[https://www.wowhead.com/wotlk/quest=11563]],image=[[assets/images/quests/placeholder.png]],desc=[[If your pathetic little eyes were any good, you'd see that we're being slaughtered by the orcas to the north in the bay! Assuming your precious night elf king wants his spare costume back, I think you'll do me a favor and bring back the head of the king of the orcas, Glrggl: he who swims against the tides of fate -- eradicating the hope of life for all those who hear the siren song of death upon the waves! Be quick about it, $r, Winterfin murlocs are losing their lives even as we waste time talking!]],logDesc=[[Mrmrglmr wants you to return to him at Winterfin Retreat with Glrggl's Head.]]}
DB[11564]={id=11564,zoneId=3537,name=[[Succulent Orca Stew]],level=71,minLevel=69,giver=[[Cleaver Bmurglbrm]],giverType=[[NPC]],giverId=25211,ender=[[Cleaver Bmurglbrm]],enderType=[[NPC]],enderId=25211,wowhead=[[https://www.wowhead.com/wotlk/quest=11564]],image=[[assets/images/quests/placeholder.png]],desc=[[Word is, strange $r, that you might be going after the king of the orcas, Glrggl. That's all fine and good, but if you want to taste the stew that makes life worth living, then you'll bring me back the succulent blubber of the orcas that swim in Glimmer Bay. Hurry... I have quite a bit of cutting to do on this carcass if you want to reap the benefits of your efforts.]],logDesc=[[Cleaver Bmurglbrm has tasked you with acquiring 7 Succulent Orca Blubber. Return with them to him at Winterfin Retreat.]],rewards={{id=39691,qty=20}}}
DB[11565]={id=11565,zoneId=3537,name=[[The Spare Suit]],level=71,minLevel=69,giver=[[Mrmrglmr]],giverType=[[NPC]],giverId=25205,ender=[[King Mrgl-Mrgl]],enderType=[[NPC]],enderId=25197,prevId=11563,rewardNextId=11566,wowhead=[[https://www.wowhead.com/wotlk/quest=11565]],image=[[assets/images/quests/placeholder.png]],desc=[[Very well, your king's secret is safe with me as long as he continues to help us against our enemies. Here, take this to him. I cleaned it up nicely, though I have no idea why he needs a second disguise. Maybe he has something in mind for you?]],logDesc=[[Return King Mrgl-Mrgl's Spare Suit to him at Winterfin Retreat.]]}
DB[11566]={id=11566,zoneId=3537,name=[[Surrender... Not!]],level=72,minLevel=69,giver=[[King Mrgl-Mrgl]],giverType=[[NPC]],giverId=25197,ender=[[King Mrgl-Mrgl]],enderType=[[NPC]],enderId=25197,prevId=11565,wowhead=[[https://www.wowhead.com/wotlk/quest=11566]],image=[[assets/images/quests/placeholder.png]],desc=[[The time has come to put an end to this unnatural situation, $N. For the Winterfin murlocs to have a chance at a future, Claximus must die! I want you to take my spare murloc suit and enter the Winterfin Caverns under the pretext of surrender. With the white flag in hand, the murlocs won't attack you. You'll find him in the southwestern most corner of the caverns. Once you get close enough, deal with Claximus. Bring me one of his claws as proof that the grisly deed has been done.]],logDesc=[[King Mrgl-Mrgl at Winterfin Retreat has asked you to bring him a Claw of Claximus.]],choiceRewards={{id=37215,qty=1},{id=37392,qty=1},{id=37426,qty=1},{id=37506,qty=1}}}
DB[11567]={id=11567,zoneId=495,name=[[The Ancient Armor of the Kvaldir]],level=71,minLevel=68,giver=[["Silvermoon" Harry]],giverType=[[NPC]],giverId=24539,ender=[[Orfus of Kamagua]],enderType=[[NPC]],enderId=23804,prevId=11510,nextId=11568,exGroup=-11511,wowhead=[[https://www.wowhead.com/wotlk/quest=11567]],image=[[assets/images/quests/placeholder.png]],desc=[[I was on the vessel that was bringing in the armor. We'd just boarded the ship and were headin' back here when we were attacked by a Forsaken destroyer. They boarded our ship, took all the booty for themselves, and then sunk her. That was the last I'd seen of that armor. If you want, you can take my bomber from Scalawag to the dreaded isle that the destroyer be docked. Talk to my woman, Alanya, outside. She'll get you on the bomber. If you manage to find the stuff, don't you dare bring it back!]],logDesc=[[Recover the Ancient Armor of the Kvaldir and deliver it to Orfus of Kamagua in the Howling Fjord.]]}
DB[11568]={id=11568,zoneId=495,name=[[A Return to Resting]],level=71,minLevel=68,giver=[[Orfus of Kamagua]],giverType=[[NPC]],giverId=23804,ender=[[Orfus of Kamagua]],enderType=[[NPC]],enderId=23804,rewardNextId=11572,wowhead=[[https://www.wowhead.com/wotlk/quest=11568]],image=[[assets/images/quests/placeholder.png]],desc=[[<Orfus hands you a satchel.> Within this satchel are the artifacts that you recovered. Locate the burial mounds of Shield Hill, far to the southeast, where the items were originally stolen from and return the artifacts. It is my hope that this gesture will quell the spirits that now haunt our hunting grounds. Be strong, $N...]],logDesc=[[Use the Bundle of Vrykul Artifacts at the ransacked burial mounds of Shield Hill to return the Frozen Heart of Isuldof, the Shield of the Aesirites, the Staff of Storm's Fury and the Ancient Armor of the Kvaldir. Return to Orfus of Kamagua at the Ancient Lift should you succeed.]]}
DB[11569]={id=11569,zoneId=3537,name=[[Keymaster Urmgrgl]],level=71,minLevel=69,giver=[[Glrglrglr]],giverType=[[NPC]],giverId=28375,ender=[[Glrglrglr]],enderType=[[NPC]],enderId=28375,wowhead=[[https://www.wowhead.com/wotlk/quest=11569]],image=[[assets/images/quests/placeholder.png]],desc=[[I have to get out of these caverns! There's magic stuff seeping in from Coldarra, above, and affecting everyone's minds. I don't intend to be controlled like these others! Keymaster Urmgrgl is in the cave below and to the south. He holds the key to my cage. Get it from him and bring it back so that I can unlock my cage and get out of here. Hurry!]],logDesc=[[Glrglrglr inside the Winterfin Caverns has asked you to retrieve Urmgrgl's Key.]]}
DB[11570]={id=11570,zoneId=3537,name=[[Escape from the Winterfin Caverns]],level=71,minLevel=69,giver=[[Lurgglbr]],giverType=[[NPC]],giverId=25208,ender=[[King Mrgl-Mrgl]],enderType=[[NPC]],enderId=25197,prevId=11571,wowhead=[[https://www.wowhead.com/wotlk/quest=11570]],image=[[assets/images/quests/placeholder.png]],desc=[[The lock on my cage doesn't look too solid, but I'm not foolish enough to try to leave without assistance. Will you help me safely get out of these caverns? There's no time to waste, $r. When you get back to the retreat, please let the king know that I'm okay. He's sure to give you a reward.]],logDesc=[[Escort Lurgglbr to safety and then report to King Mrgl-Mrgl at Winterfin Retreat with the good news.]],choiceRewards={{id=37046,qty=1},{id=37044,qty=1},{id=37041,qty=1},{id=37036,qty=1},{id=37039,qty=1},{id=37042,qty=1}}}
DB[11571]={id=11571,zoneId=3537,name=[[Learning to Communicate]],level=71,minLevel=69,giver=[[King Mrgl-Mrgl]],giverType=[[NPC]],giverId=25197,ender=[[King Mrgl-Mrgl]],enderType=[[NPC]],enderId=25197,rewardNextId=11559,wowhead=[[https://www.wowhead.com/wotlk/quest=11571]],image=[[assets/images/quests/placeholder.png]],desc=[[To help, you must learn how to speak the Winterfin dialect. We'll work with the forces of nature and magic to do that. Take this empty conch shell. At the bottom of the watery trench below exists Scalder, an elemental of air and watery fury. Once she is defeated, use the conch upon her remains to capture her magical steam. Return the full conch to me, and I'll imbue my knowledge of the Winterfin tongue into you. Luckily, a friend taught me a water breathing spell, which I will cast upon you.]],logDesc=[[King Mrgl-Mrgl has given you a conch to use upon Scalder's remains. Return The King's Filled Conch to him at Winterfin Retreat.]]}
DB[11572]={id=11572,zoneId=495,name=[[Return to Atuik]],level=71,minLevel=68,giver=[[Orfus of Kamagua]],giverType=[[NPC]],giverId=23804,ender=[[Elder Atuik]],enderType=[[NPC]],enderId=24755,prevId=11568,wowhead=[[https://www.wowhead.com/wotlk/quest=11572]],image=[[assets/images/quests/placeholder.png]],desc=[[Return to Elder Atuik at Kamagua. He and the rest of my people must be warned of this impending doom that approaches from the sea. <Orfus shivers.> Use the Ancient Lift to reach him. Please hurry!]],logDesc=[[Deliver the bad news to Elder Atuik at Kamagua.]],choiceRewards={{id=36874,qty=1},{id=36872,qty=1},{id=36871,qty=1}}}
DB[11573]={id=11573,zoneId=495,name=[[Orfus of Kamagua]],level=71,minLevel=68,giver=[[Lunk-tusk]],giverType=[[NPC]],giverId=25233,ender=[[Orfus of Kamagua]],enderType=[[NPC]],enderId=23804,rewardNextId=11504,wowhead=[[https://www.wowhead.com/wotlk/quest=11573]],image=[[assets/images/quests/placeholder.png]],desc=[[Hail, traveler. I am Lunk-tusk of the Kalu'ak. We are known as tuskarr to your people. My partner and I were recently sent up to investigate strange happenings along one of our hunting trails. It was when we approached the graveyard known as Shield Hill that we were attacked by the undead. I was lucky to make it to this camp, but I am uncertain as to what became of Orfus. We parted ways at the Ancient Lift, southeast of here along the cliff edge. Will you go see if he is ok?]],logDesc=[[Find Orfus of Kamagua at the Ancient Lift in Howling Fjord.]]}
DB[11574]={id=11574,zoneId=3537,name=[[Too Close For Comfort]],level=71,minLevel=69,giver=[[Endorah]],giverType=[[NPC]],giverId=25247,ender=[[Librarian Donathan]],enderType=[[NPC]],enderId=25262,prevId=11598,nextId=11587,rewardNextId=11587,wowhead=[[https://www.wowhead.com/wotlk/quest=11574]],image=[[assets/images/quests/placeholder.png]],desc=[[I told them all that I remember. Why don't they believe me? I was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts - I was surrounded! A magical box appeared above me, opened up and pulled me inside. Just as it began to close around me, my rescuers swooped in on the backs of red drakes. It was breathtaking! I never thanked them for saving me. Please, $c, find them, and pass on my gratitude.]],logDesc=[[Endorah wants you to go to Amber Ledge north of Warsong Hold and thank those there for rescuing her.]]}
DB[11575]={id=11575,zoneId=3537,name=[[Nick of Time]],level=71,minLevel=69,giver=[[Midge]],giverType=[[NPC]],giverId=25249,ender=[[Librarian Donathan]],enderType=[[NPC]],enderId=25262,prevId=11897,nextId=11587,rewardNextId=11587,wowhead=[[https://www.wowhead.com/wotlk/quest=11575]],image=[[assets/images/quests/placeholder.png]],desc=[[I told them all that I remember. Why don't they believe me? I was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts. I was surrounded! A huge magical cube appeared above me. It opened up and pulled me inside. I swear it's true! Just as it began to close around me, my rescuers swooped in on the backs of drakes - It was amazing! My captors scattered and I was able to escape. I never thanked them for saving me. Please, $c, if you see them, pass on my gratitude.]],logDesc=[[Midge in Valiance Keep wants you to go to Amber Ledge to the north and thank those there for rescuing her.]]}
DB[11576]={id=11576,zoneId=3537,name=[[Monitoring the Rift: Cleftcliff Anomaly]],level=71,minLevel=69,giver=[[Librarian Garren]],giverType=[[NPC]],giverId=25291,ender=[[Librarian Garren]],enderType=[[NPC]],enderId=25291,rewardNextId=11582,wowhead=[[https://www.wowhead.com/wotlk/quest=11576]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, $r. I am Garren of Dalaran. Not long ago, the rift was a peaceful place - geothermally speaking at least. Recently though, earthquakes have occurred with alarming frequency and scars in the earth have appeared, exposing unique energy fields of chaotic power. My mission here is to chart and monitor these anomalies. My instruments indicate that another has appeared on the cliff face to the southwest. Take this device with you and use it when you locate the new disruption.]],logDesc=[[Garren on Amber Ledge wants you to use the Arcanometer at the Cleftcliff Anomaly.]]}
DB[11578]={id=11578,zoneId=15,name=[[The "Chow" Quest (123)aa COPY]],name_loc=[[La misión "Chow" (123)aa COPIA]],level=4,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-8797,poiY=-259,wowhead=[[https://www.wowhead.com/wotlk/quest=11578]],image=[[assets/images/quests/placeholder.png]],desc=[[$Tpunk;!  Kill Kobold Vermin, 2 of em.]],logDesc=[[Kill Kobold Vermin, 2 of em.]],rewards={{id=159,qty=1},{id=118,qty=5}}}
DB[11579]={id=11579,zoneId=15,name=[[The "Chow" Quest (123)aa COPY]],name_loc=[[La misión "Chow" (123)aa COPIA]],level=4,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-8797,poiY=-259,wowhead=[[https://www.wowhead.com/wotlk/quest=11579]],image=[[assets/images/quests/placeholder.png]],desc=[[$Tpunk;!  Kill Kobold Vermin, 2 of em.]],logDesc=[[Kill Kobold Vermin, 2 of em.]],rewards={{id=159,qty=1},{id=118,qty=5}}}
DB[11582]={id=11582,zoneId=3537,name=[[Monitoring the Rift: Sundered Chasm]],level=71,minLevel=69,giver=[[Librarian Garren]],giverType=[[NPC]],giverId=25291,ender=[[Librarian Garren]],enderType=[[NPC]],enderId=25291,prevId=11576,rewardNextId=12728,wowhead=[[https://www.wowhead.com/wotlk/quest=11582]],image=[[assets/images/quests/placeholder.png]],desc=[[Did you feel that?! That was just an aftershock... you should've been here a few minutes ago! I'm afraid I must call upon your services again. My instruments indicate that there is an immense disruption just west of here, far beneath the water's surface. Just as before, I need you to take the arcanometer and capture the anomaly's data. I'll cast a spell that will enable you to breathe underwater. If it wears off before you find it, come let me know and I'll renew its effects.]],logDesc=[[Garren at Amber Ledge wants you to use the Arcanometer at the Sundered Chasm anomaly and return to him with the readings.]]}
DB[11585]={id=11585,zoneId=3537,name=[[Hellscream's Vigil]],level=71,minLevel=68,giver=[[Warsong Recruitment Officer]],giverType=[[NPC]],giverId=25273,ender=[[Garrosh Hellscream]],enderType=[[NPC]],enderId=25237,exGroup=11585,wowhead=[[https://www.wowhead.com/wotlk/quest=11585]],image=[[assets/images/quests/placeholder.png]],desc=[[Throm-Ka, $r! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty! This impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed! Garrosh awaits your arrival below. Lok'tar ogar!]],logDesc=[[Speak with Garrosh Hellscream in Warsong Hold.]]}
DB[11586]={id=11586,zoneId=3537,name=[[Hellscream's Vigil]],level=71,minLevel=68,giver=[[Warsong Recruitment Officer]],giverType=[[NPC]],giverId=25273,ender=[[Garrosh Hellscream]],enderType=[[NPC]],enderId=25237,exGroup=11585,wowhead=[[https://www.wowhead.com/wotlk/quest=11586]],image=[[assets/images/quests/placeholder.png]],desc=[[Throm-Ka, $r! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty! This impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed! Garrosh awaits your arrival below. Lok'tar ogar!]],logDesc=[[Speak with Garrosh Hellscream in Warsong Hold.]]}
DB[11587]={id=11587,zoneId=3537,name=[[Prison Break]],level=71,minLevel=69,giver=[[Librarian Donathan]],giverType=[[NPC]],giverId=25262,ender=[[Librarian Donathan]],enderType=[[NPC]],enderId=25262,rewardNextId=11590,wowhead=[[https://www.wowhead.com/wotlk/quest=11587]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, $c. I am Donathan, a loyal representative of Dalaran. Forgive my abruptness, but we find ourselves in the midst of a crisis. Mages all across Azeroth are being abducted and I have been authorized to conscript anyone able to assist in the unraveling of this mystery. The camp just south of ours is where our investigation begins. I call upon you to rescue one of the imprisoned mages held there. You must obtain a key from one of the mage hunters and use it to open an arcane prison.]],logDesc=[[Librarian Donathan on Amber Ledge wants you to collect the Beryl Prison Key from one of the Beryl Mage Hunters at Beryl Point and use it to release a trapped mage from an arcane prison.]]}
DB[11588]={id=11588,name=[[REUSE]],level=70,minLevel=65,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11588]],image=[[assets/images/quests/placeholder.png]],desc=[[Stop Ahune from coming to Azeroth and inciting an elemental war!]],logDesc=[[Destroy the elemental Ahune within Blackfathom Deeps.]]}
DB[11589]={id=11589,name=[[REUSE]],level=70,minLevel=65,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11589]],image=[[assets/images/quests/placeholder.png]],desc=[[Stop Ahune from coming to Azeroth and inciting an elemental war!]],logDesc=[[Destroy the elemental Ahune within Blackfathom Deeps.]]}
DB[11590]={id=11590,zoneId=3537,name=[[Abduction]],level=71,minLevel=69,giver=[[Librarian Donathan]],giverType=[[NPC]],giverId=25262,ender=[[Librarian Donathan]],enderType=[[NPC]],enderId=25262,prevId=11587,rewardNextId=11646,wowhead=[[https://www.wowhead.com/wotlk/quest=11590]],image=[[assets/images/quests/placeholder.png]],desc=[[$n, we have a situation. I've just learned that one of our archmages en route from Dalaran has gone missing. Naturally, we suspect the mage hunters are behind her disappearance. Time is clearly of the essence. We must know what has become of Lady Evanor at once if we are to have any hope of rescuing her. Take this device. Return to Beryl Point and use it on a Beryl sorcerer when he is near death. It should bind him long enough for you to bring him here for questioning.]],logDesc=[[Donathan wants you to use the Arcane Binder on a wounded Beryl Sorcerer at Beryl Point and return to Amber Ledge with him.]]}
DB[11591]={id=11591,zoneId=3537,name=[[Report to Steeljaw's Caravan]],level=71,minLevel=68,giver=[[Overlord Bor'gorok]],giverType=[[NPC]],giverId=25326,ender=[[Grunt Ragefist]],enderType=[[NPC]],enderId=25336,wowhead=[[https://www.wowhead.com/wotlk/quest=11591]],image=[[assets/images/quests/placeholder.png]],desc=[[That dimwitted cur, Steeljaw, tried to take our caravan of supplies on a shortcut through a taunka graveyard! We just struck up relations with them! Now the caravan lies in ruins, overrun by the taunka spirits that rose out of their graves as he was trampling them. Head south and see if you can salvage the situation, $c. I sent Grunt Ragefist and a few others down there with him to help out. Why don't you see if you can lend a hand.]],logDesc=[[Speak with Grunt Ragefist at Steeljaw's Caravan.]]}
DB[11592]={id=11592,zoneId=3537,name=[[We Strike!]],level=72,minLevel=68,giver=[[Longrunner Proudhoof]],giverType=[[NPC]],giverId=25335,ender=[[Overlord Bor'gorok]],enderType=[[NPC]],enderId=25326,wowhead=[[https://www.wowhead.com/wotlk/quest=11592]],image=[[assets/images/quests/placeholder.png]],desc=[[One of your orcs named Steeljaw tried to save some time by taking a shortcut through our burial grounds. This had better not be how your Horde normally acts, $r, or you will find the taunka to be the end of you! But, you look as if you want to help fix this situation. Good! Steeljaw's cursed spirit now haunts this place and disturbs the remains of my ancestors. We must put an end to him! If we live through this, tell your Overlord Bor'gorok at the outpost to the north. Are you with me?]],logDesc=[[Help Longrunner Proudhoof and his Warsong raiders to survive the assault upon Steeljaw's Caravan and finish off the spirit of Force-Commander Steeljaw. If successful, report to Overlord Bor'gorok at Bor'gorok Outpost.]],choiceRewards={{id=37271,qty=1},{id=37393,qty=1},{id=37425,qty=1},{id=37557,qty=1}}}
DB[11593]={id=11593,zoneId=3537,name=[[The Honored Dead]],level=71,minLevel=68,giver=[[Grunt Ragefist]],giverType=[[NPC]],giverId=25336,ender=[[Grunt Ragefist]],enderType=[[NPC]],enderId=25336,wowhead=[[https://www.wowhead.com/wotlk/quest=11593]],image=[[assets/images/quests/placeholder.png]],desc=[[Our fallen deserve a hero's funeral, but we cannot bury them here on sacred taunka ground. I'll not ask you to drag their bodies back here, but take this and head further into the cemetary.  When you come across our dead caravan guards and workers, put them to the torch. Honor our dead, $c!]],logDesc=[[Grunt Ragefist at Steeljaw's Caravan has asked you to use Ragefist's Torch to burn any combination of 10 Dead Carvan Guards and Workers.]]}
DB[11594]={id=11594,zoneId=3537,name=[[Put Them to Rest]],level=71,minLevel=68,giver=[[Grunt Ragefist]],giverType=[[NPC]],giverId=25336,ender=[[Grunt Ragefist]],enderType=[[NPC]],enderId=25336,wowhead=[[https://www.wowhead.com/wotlk/quest=11594]],image=[[assets/images/quests/placeholder.png]],desc=[[Force-Commander Steeljaw's idiocy caused this mess. What was he thinking taking a caravan through a taunka burial mound? Still, what's done is done. Now it is up to us to deal with the consequences. Overlord Bor'gorok asked me to help Longrunner Proudhoof in any way that I can. The longrunner has asked that we lay to rest the spirits of his ancestors. What do you say, $c? Are you $g man : strong; enough to handle such a simple task?]],logDesc=[[Put 20 taunka spirits, either Ghostly Sages or Risen Longrunners, to rest and then report back to Grunt Ragefist at Steeljaw's Caravan.]]}
DB[11595]={id=11595,zoneId=3537,name=[[The Defense of Warsong Hold]],level=71,minLevel=68,giver=[[High Overlord Saurfang]],giverType=[[NPC]],giverId=25256,ender=[[Overlord Razgor]],enderType=[[NPC]],enderId=25279,nextId=11598,rewardNextId=11598,exGroup=11595,wowhead=[[https://www.wowhead.com/wotlk/quest=11595]],image=[[assets/images/quests/placeholder.png]],desc=[[Hellscream has the weight of the Horde upon his shoulders. Do not be dissuaded from your duties because of his temperament, $N. <Saurfang nods.> Did you think that I would forget the name of a hero of Orgrimmar? It is not every day that I have the pleasure of putting the head of Nefarian on a pike! The Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.]],logDesc=[[Report to Overlord Razgor at the hut on the south side of Warsong Hold.]]}
DB[11596]={id=11596,zoneId=3537,name=[[The Defense of Warsong Hold]],level=71,minLevel=68,giver=[[High Overlord Saurfang]],giverType=[[NPC]],giverId=25256,ender=[[Overlord Razgor]],enderType=[[NPC]],enderId=25279,nextId=11598,rewardNextId=11598,exGroup=11595,wowhead=[[https://www.wowhead.com/wotlk/quest=11596]],image=[[assets/images/quests/placeholder.png]],desc=[[Do not let Hellscream dissuade you from your duties as a soldier of the Horde, $r. He bears a terrible burden in these frozen wastes, with the outcome of his charge resulting in victory over the Scourge or the extinction of all life on Azeroth. It is for this reason that we require your strength and wisdom. The Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.]],logDesc=[[Report to Overlord Razgor at the hut on the south side of Warsong Hold.]]}
DB[11597]={id=11597,zoneId=3537,name=[[The Defense of Warsong Hold]],level=71,minLevel=68,giver=[[High Overlord Saurfang]],giverType=[[NPC]],giverId=25256,ender=[[Overlord Razgor]],enderType=[[NPC]],enderId=25279,nextId=11598,rewardNextId=11598,exGroup=11595,wowhead=[[https://www.wowhead.com/wotlk/quest=11597]],image=[[assets/images/quests/placeholder.png]],desc=[[It seems that we always meet in the direst of circumstances, Scarab Lord. Were you not saving the world from certain destruction the last time we met? <Saurfang chuckles.> Your assistance is most welcome in Northrend, despite what the young chieftain might say. If we had even a dozen more soldiers with your power, we would be sitting in Orgrimmar right now, hunched over a warm fire. Report to Overlord Razgor, right outside the main entry to Warsong Hold, to the south.]],logDesc=[[Report to Overlord Razgor at the hut on the south side of Warsong Hold.]]}
DB[11598]={id=11598,zoneId=3537,name=[[Taking Back Mightstone Quarry]],level=71,minLevel=68,giver=[[Overlord Razgor]],giverType=[[NPC]],giverId=25279,ender=[[Overlord Razgor]],enderType=[[NPC]],enderId=25279,rewardNextId=11602,wowhead=[[https://www.wowhead.com/wotlk/quest=11598]],image=[[assets/images/quests/placeholder.png]],desc=[[While Warsong is protected by 10 feet of steel and stone on all sides, this quarry is soft and primed for attacks by the Nerubians. <Razgor points west.> Beyond this quarry stand thousands of Scourge, awaiting orders to attack. Should the Nerubians take down our inner defenses, we will be overrun by the undead legions of Arthas. We can't let that happen - which is why you're going on the offensive and slaughtering the Nerubians in the quarry. Blood and thunder, soldier! Take 'em both with you.]],logDesc=[[Overlord Razgor at Warsong Hold wants you to kill 15 Nerub'ar Nerubians.]]}
DB[11599]={id=11599,zoneId=3537,name=[[Thassarian, My Brother]],level=71,minLevel=68,giver=[[Leryssa]],giverType=[[NPC]],giverId=25251,ender=[[William Allerton]],enderType=[[NPC]],enderId=25385,prevId=11927,rewardNextId=11600,wowhead=[[https://www.wowhead.com/wotlk/quest=11599]],image=[[assets/images/quests/placeholder.png]],desc=[[I recently received word from William Allerton, a family friend, that my brother enlisted here in Valiance Keep on the same day he did.  Thing is... my brother's been dead for years. I sold everything I owned to come looking for Thassarian, only to be stonewalled by the local bureaucracy.  I've even been threatened with arrest if I keep snooping around. I need someone in the good graces of the higher-ups... someone like you.  If you can help me, I heard that William's stationed at the Farshire mine.]],logDesc=[[Look for William Allerton inside the Farshire mine.]]}
DB[11600]={id=11600,zoneId=3537,name=[[The Late William Allerton]],level=71,minLevel=68,giver=[[William Allerton]],giverType=[[NPC]],giverId=25385,ender=[[Leryssa]],enderType=[[NPC]],enderId=25251,prevId=11599,rewardNextId=11601,wowhead=[[https://www.wowhead.com/wotlk/quest=11600]],image=[[assets/images/quests/placeholder.png]],desc=[[William's neck has been cut by a sharp object. Further inspection reveals a single clue to bring to Leryssa - an enlistment card bearing the name of William Allerton.]],logDesc=[[Bring the Enlistment Card to Leryssa at Valiance Keep in Borean Tundra.]],choiceRewards={{id=37207,qty=1},{id=37418,qty=1},{id=37556,qty=1},{id=37483,qty=1}}}
DB[11601]={id=11601,zoneId=3537,name=[[Lost and Found]],level=71,minLevel=68,giver=[[Leryssa]],giverType=[[NPC]],giverId=25251,ender=[[James Deacon]],enderType=[[NPC]],enderId=25245,prevId=11600,rewardNextId=11603,wowhead=[[https://www.wowhead.com/wotlk/quest=11601]],image=[[assets/images/quests/placeholder.png]],desc=[[Poor Mr. Allerton might yet help us find my brother. <Leryssa unveils a voluminous book, not unlike an army recruitment ledger.> I borrowed it, ok?  Let's see, does that enlistment card have a date? William saw Thassarian at the enlistment line.  Their entries must be near each other... here it is! He was assigned to... Unit S?  All the other military units are named after Alliance towns. Who's in the unit?  Where are they deployed?  We need rumors.  See if the innkeeper's heard anything.]],logDesc=[[Speak to James Deacon at the inn in Valiance Keep.]]}
DB[11602]={id=11602,zoneId=3537,name=[[Cutting Off the Source]],level=71,minLevel=68,giver=[[Overlord Razgor]],giverType=[[NPC]],giverId=25279,ender=[[Overlord Razgor]],enderType=[[NPC]],enderId=25279,prevId=11598,rewardNextId=11634,wowhead=[[https://www.wowhead.com/wotlk/quest=11602]],image=[[assets/images/quests/placeholder.png]],desc=[[Aerial reconnaissance of the quarry reports that the Nerubians are storing their eggs on the scaffolding surrounding the base. Smart beasts these are... They're keeping the eggs high and dry, away from the epicenter of conflict. You're going to have to go back out there and track down their eggs. Find 'em, smash 'em, and trash 'em. Each egg destroyed means twenty less Nerubians feeding on our corpses. ]],logDesc=[[Overlord Razgor at Warsong Hold wants you to destroy 10 Nerub'ar Egg Sacs.]],choiceRewards={{id=36883,qty=1},{id=36882,qty=1},{id=36878,qty=1},{id=36881,qty=1},{id=36879,qty=1},{id=36880,qty=1}}}
DB[11603]={id=11603,zoneId=3537,name=[[In Wine, Truth]],level=71,minLevel=68,giver=[[James Deacon]],giverType=[[NPC]],giverId=25245,ender=[[Old Man Colburn]],enderType=[[NPC]],enderId=25302,prevId=11601,rewardNextId=11604,wowhead=[[https://www.wowhead.com/wotlk/quest=11603]],image=[[assets/images/quests/placeholder.png]],desc=[[The military was all that old man Colburn had.  After he retired, he still clung to it like a lifeline. He knows the name of every general, unit, brigade, detachment... you name it.  He's the man you need. Problem is, his mind is scarred.  He won't talk to anyone unless he gets his Kul Tiras wine.  Takes him back to the times he was a marine. I haven't received a shipment in months.  The last merchant ship out of Kul Tiras sunk northeast of here.  See if you can salvage a bottle to bring Colburn.]],logDesc=[[Salvage a bottle of Kul Tiras Wine from the underwater shipwreck northeast of Valiance Keep and bring it to Old Man Colburn in the Valiance Keep inn.]],rewards={{id=40042,qty=5}}}
DB[11604]={id=11604,zoneId=3537,name=[[A Deserter]],level=71,minLevel=68,giver=[[Old Man Colburn]],giverType=[[NPC]],giverId=25302,ender=[[Private Brau]],enderType=[[NPC]],enderId=25395,prevId=11603,rewardNextId=11932,wowhead=[[https://www.wowhead.com/wotlk/quest=11604]],image=[[assets/images/quests/placeholder.png]],desc=[[Unit S... Unit S.... hmmmpph.... don't make any sense... it oughta be named after a town... Darkshire was sent to Dragonblight.  The Goldshire boys were sent to the Fjord.   Where did I hear... Oh, yes... the deserter!  There's a turn-tail in the barracks prison.  Got thrown in not too long ago.  Kept saying that "S" stood for suicide. Look for the deserter.  He might have some information for you.]],logDesc=[[Find the prison inside Inner Hold in Valiance Keep and speak to the deserter.]]}
DB[11605]={id=11605,zoneId=3537,name=[[The Honored Ancestors]],level=72,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=11607,wowhead=[[https://www.wowhead.com/wotlk/quest=11605]],image=[[assets/images/quests/placeholder.png]],desc=[[<A distant voice echoes in your head as you regard the stone statue.> Do not be startled, stranger. I am Elder Atkanok, an ancient ancestor of the tuskarr people, a skilled craftsman in my own time and the guardian of this quarry for centuries. The quarry has been overrun, leaving many statues unfinished while the ancestors' spirits wander the world. Will you aid me in righting this wrong? First, I must know the names of these wandering ancestors. Look for the markers near their statues.]],logDesc=[[Elder Atkanok outside Coldrock Quarry wants you to identify the statues of Elder Kesuk, Elder Sagani, and Elder Takret.]]}
DB[11606]={id=11606,zoneId=3537,name=[[Patience is a Virtue that We Don't Need]],level=71,minLevel=68,giver=[[Quartermaster Holgoth]],giverType=[[NPC]],giverId=25327,ender=[[Quartermaster Holgoth]],enderType=[[NPC]],enderId=25327,rewardNextId=11608,wowhead=[[https://www.wowhead.com/wotlk/quest=11606]],image=[[assets/images/quests/placeholder.png]],desc=[[We can kill all the Nerubians that we see and destroy all the eggs that we find, but those things won't stop coming until we blow their tunnels and passageways up. Of course, we can't do that without some heavy grade munitions. Unfortunately, most of our stockpile is being used up by the goblins and blacksmiths for our siege tanks and weaponry. We do happen to have a pretty good supply of the stuff out in Mightstone Quarry - underneath all the Nerubian crap. You'll just have to go out and get it for me.]],logDesc=[[Quartermaster Holgoth at Warsong Hold wants you to recover 15 crates of Warsong Munitions.]]}
DB[11607]={id=11607,zoneId=3537,name=[[The Lost Spirits]],level=72,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],prevId=11605,rewardNextId=11609,wowhead=[[https://www.wowhead.com/wotlk/quest=11607]],image=[[assets/images/quests/placeholder.png]],desc=[[In the attack on the quarry, the shaman and craftsmen working here were slain. The violence threw the spirit world into utter chaos and we'll be unable to guide the ancestors home unless we find a way to soothe the spirits of the murdered. The aggressors themselves pay no heed to the spirits, but their companions, the beryl hounds, sense the spirits and hold them in thrall. Kill the beryl hounds, and using the raw energy left behind, break the imprisonment of the spirits of the innocent.]],logDesc=[[Elder Atkanok, on the outskirts of Coldrock Quarry, wants you to free the spirits of 3 Kaskala Craftsmen and 3 Kaskala Shaman.]]}
DB[11608]={id=11608,zoneId=3537,name=[[Bury Those Cockroaches!]],level=71,minLevel=68,giver=[[Quartermaster Holgoth]],giverType=[[NPC]],giverId=25327,ender=[[Quartermaster Holgoth]],enderType=[[NPC]],enderId=25327,prevId=11606,wowhead=[[https://www.wowhead.com/wotlk/quest=11608]],image=[[assets/images/quests/placeholder.png]],desc=[[North, south, east and west. Those are the locations that you should be concerned about. Surrounding this fortress, within Mightstone Quarry, are four perfectly situated Nerub'ar sinkholes. <Holgoth hands you a bundle.> Be very careful with that package, $N. Mishandle it and you'll be dog meat. Inside the bundle are seaforium depth charges. Get to each of those Nerub'ar sinkholes and plant a depth charge at their center point. If all goes well, the tunnels will collapse. Get a move on!]],logDesc=[[Quartermaster Holgoth at Warsong Hold wants you to use the Seaforium Depth Charge Bundle to destroy the Nerub'ar sinkholes to the south, east, west and north of Warsong Hold.]],choiceRewards={{id=36888,qty=1},{id=36937,qty=1},{id=36938,qty=1},{id=37555,qty=1}}}
DB[11609]={id=11609,zoneId=3537,name=[[Picking Up the Pieces]],level=72,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],prevId=11607,rewardNextId=11610,wowhead=[[https://www.wowhead.com/wotlk/quest=11609]],image=[[assets/images/quests/placeholder.png]],desc=[[With the spirits of the murdered craftsmen and shaman at rest, the way is clear for us to complete the ceremonies interrupted by the attack. You must perform a role traditionally reserved for a tuskarr shaman, and you must possess all the necessary ritual items. There is no time to craft new ones, so you will need to scour the quarry for those left by the victims of the attack. Handle these objects with care, $N, for some are centuries old. You may need to wrest them from the hands of the invaders.]],logDesc=[[Bring 6 Tuskarr Ritual Objects to Elder Atkanok, who stands outside Coldrock Quarry.]]}
DB[11610]={id=11610,zoneId=3537,name=[[Leading the Ancestors Home]],level=72,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],prevId=11609,wowhead=[[https://www.wowhead.com/wotlk/quest=11610]],image=[[assets/images/quests/placeholder.png]],desc=[[With your help, the ancestor spirits can now be guided to their rightful homes, the statues lovingly prepared by Kaskala's craftsmen and shaman. The ceremonies for these ancestors were interrupted during the attack on the quarry, and you will need to complete them. Take with you the objects that you recovered from the quarry, stand in front of the statues with the name markers, and recite this chant. <Words in a strange language flood your head, but you have no difficulty recalling them.>]],logDesc=[[Elder Atkanok wants you to guide the spirits of Elder Kesuk, Elder Sagani, and Elder Takret to their stone monuments.]],choiceRewards={{id=37227,qty=1},{id=37548,qty=1},{id=37380,qty=1},{id=37514,qty=1}}}
DB[11611]={id=11611,zoneId=3537,name=[[Taken by the Scourge]],level=71,minLevel=68,giver=[[Foreman Mortuus]],giverType=[[NPC]],giverId=25280,ender=[[Foreman Mortuus]],enderType=[[NPC]],enderId=25280,wowhead=[[https://www.wowhead.com/wotlk/quest=11611]],image=[[assets/images/quests/placeholder.png]],desc=[[<Mortuus sighs.> Peons... We may as well post up a sign offering the Nerub'ar a free meal. See, the problem with a peon is that: (1) they're dumber than dirt; and (2) they're weaker than a leper gnome. Of course they're the first to be taken by the Scourge! This puts me in a bit of a predicament, you see. Without peons, manual labor comes to a halt. No peons, no construction. Find and release my peons, $r. If they're alive, you'll find 'em spun up in webbing throughout Mightstone Quarry. ]],logDesc=[[Foreman Mortuus at Warsong Hold wants you to free 5 Warsong Peons.]],choiceRewards={{id=37206,qty=1},{id=37403,qty=1},{id=37417,qty=1},{id=37482,qty=1}}}
DB[11612]={id=11612,zoneId=3537,name=[[Reclaiming the Quarry]],level=72,minLevel=68,giver=[[Etaruk]],giverType=[[NPC]],giverId=25292,ender=[[Etaruk]],enderType=[[NPC]],enderId=25292,rewardNextId=11617,wowhead=[[https://www.wowhead.com/wotlk/quest=11612]],image=[[assets/images/quests/placeholder.png]],desc=[[You're a welcome sight, $c. My name is Etaruk, and I used to be a craftsman here at the Coldrock Quarry. My companions and I were preparing a new set of statues for their last set of rites when we saw those mysterious blue platforms come flying over the plateau. When they landed, the mages they carried swarmed the quarry, murdering my fellows and plundering the quarry. If we don't stop them, they'll destroy our statues and make off with our artifacts. Will you help me defeat the invaders?]],logDesc=[[Etaruk, camped near the entrance to the Coldrock Quarry, wants you to kill 12 Beryl Treasure Hunters.]]}
DB[11613]={id=11613,zoneId=3537,name=[[Karuk's Oath]],level=71,minLevel=68,giver=[[Karuk]],giverType=[[NPC]],giverId=25435,ender=[[Karuk]],enderType=[[NPC]],enderId=25435,rewardNextId=11619,wowhead=[[https://www.wowhead.com/wotlk/quest=11613]],image=[[assets/images/quests/placeholder.png]],desc=[[They call themselves the Kvaldir.  My people have legends about them; we call them the tuk-hariq - walkers of the fog. My village was destroyed by these giant mist-men.  Everyone I knew was slain, including my father Ariut. By tuskarr law I must seek retribution against those who shed my kin's blood. I am but a fisherman and I've not yet passed the test of manhood... I cannot stand toe-to-toe with the vile Kvaldir. If you were to carry out my blood duty for me, I will be in great debt to you.]],logDesc=[[Karuk wants you to slay 6 Skadir Raiders and 5 Skadir Longboatsmen.]],choiceRewards={{id=37025,qty=1},{id=37023,qty=1},{id=37024,qty=1},{id=37022,qty=1},{id=37021,qty=1},{id=37026,qty=1}}}
DB[11614]={id=11614,zoneId=3537,name=[[Untold Truths]],level=71,minLevel=68,giver=[[Shadowstalker Barthus]],giverType=[[NPC]],giverId=25394,ender=[[Shadowstalker Luther]],enderType=[[NPC]],enderId=25328,prevId=11598,rewardNextId=11615,wowhead=[[https://www.wowhead.com/wotlk/quest=11614]],image=[[assets/images/quests/placeholder.png]],desc=[[We are here by order of Varimathras! The mission of the Shadowstalkers is a simple one: spy. Well, spy with a little assassination on the side. One of my best field agents has gone missing. I haven't heard from him in days, which has left me fearing the worst. No, not death! Death would be ideal. I fear he may have gone rogue... turned traitor even. His last known location was northern Mightstone Quarry. He was gathering intelligence on the Nerubians. Find him. He better be dead...]],logDesc=[[Find Shadowstalker Luther in Mightstone Quarry.]]}
DB[11615]={id=11615,zoneId=3537,name=[[Nerub'ar Secrets]],level=71,minLevel=68,giver=[[Shadowstalker Luther]],giverType=[[NPC]],giverId=25328,ender=[[Shadowstalker Barthus]],enderType=[[NPC]],enderId=25394,prevId=11614,rewardNextId=11616,wowhead=[[https://www.wowhead.com/wotlk/quest=11615]],image=[[assets/images/quests/placeholder.png]],desc=[[You skim through the pages of the book, looking for anything of importance. On the last page you discover what appears to be frantic scribbling: Necrolords. At least a dozen by my count. Farms to west being used as some sort of horrible spawning glade for Scourge. Row upon row of victims. I think they're on to me. Made a dash for the hold. I won't be captured alive. Dreadvenom hemotoxin. If they decide to bite into me, they'll be in for a surprise. Take this information back to Barthus.]],logDesc=[[Take Luther's Journal to Shadowstalker Barthus at Warsong Hold.]]}
DB[11616]={id=11616,zoneId=3537,name=[[Message to Hellscream]],level=71,minLevel=68,giver=[[Shadowstalker Barthus]],giverType=[[NPC]],giverId=25394,ender=[[Garrosh Hellscream]],enderType=[[NPC]],enderId=25237,prevId=11615,rewardNextId=11618,wowhead=[[https://www.wowhead.com/wotlk/quest=11616]],image=[[assets/images/quests/placeholder.png]],desc=[[<Barthus tears out the last page and rolls it up.> Take this to Hellscream at once! In the meantime, I'm going to send a team to scout out the farms. Be sure to tell Hellscream that we're going to need reinforcements.]],logDesc=[[Take Barthus's Note to Garrosh Hellscream at Warsong Hold.]]}
DB[11617]={id=11617,zoneId=3537,name=[[Hampering Their Escape]],level=72,minLevel=68,giver=[[Etaruk]],giverType=[[NPC]],giverId=25292,ender=[[Etaruk]],enderType=[[NPC]],enderId=25292,prevId=11612,rewardNextId=11623,wowhead=[[https://www.wowhead.com/wotlk/quest=11617]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm sure you've seen those blue and white platforms hovering over the quarry. They're the transportation the mage hunters used to land their forces here, and now they're loading them up with our artifacts and fragments of our statues. We must stop them before they leave the quarry. The small creatures digging in the quarry carry explosives. Take them and use them to destroy the three floating platforms. The leader keeps watch from a fourth, grounded platform, but we'll deal with him afterward.]],logDesc=[[Etaruk, outside the Coldrock Quarry, wants you to destroy the North Platform, the East Platform, and the West Platform.]]}
DB[11618]={id=11618,zoneId=3537,name=[[Reinforcements Incoming...]],level=71,minLevel=68,giver=[[Garrosh Hellscream]],giverType=[[NPC]],giverId=25237,ender=[[Shadowstalker Ickoris]],enderType=[[NPC]],enderId=25437,prevId=11616,rewardNextId=11686,wowhead=[[https://www.wowhead.com/wotlk/quest=11618]],image=[[assets/images/quests/placeholder.png]],desc=[[<Hellscream shakes his head.> You may not have noticed that we're trying to win a war here, $r. I need all available soldiers at the primary points of conflict. This means that we don't have any real soldiers to spare for these minor incursions. <Hellscream pauses to think.> If Barthus wants reinforcements at the farm... <Hellscream claps his hands together.> ...he shall have them! Report to Barthus's assassins at the farms, west of here. Let them know that reinforcements have arrived.]],logDesc=[[Seek out Shadowstalker Ickoris at the Warsong Farms Outpost west of Warsong Hold.]]}
DB[11619]={id=11619,zoneId=3537,name=[[Gamel the Cruel]],level=71,minLevel=68,giver=[[Karuk]],giverType=[[NPC]],giverId=25435,ender=[[Karuk]],enderType=[[NPC]],enderId=25435,prevId=11613,wowhead=[[https://www.wowhead.com/wotlk/quest=11619]],image=[[assets/images/quests/placeholder.png]],desc=[[My own father was slain by the leader of this raiding party, Gamel the Cruel.  He has made his abode inside a cave on the beach. You've dealt with his men already.  Finish what you've started, $N.  Avenge my father and I will share with you what little I still have.]],logDesc=[[Karuk wants you to defeat Gamel the Cruel at Riplash Strand.]],choiceRewards={{id=37209,qty=1},{id=37419,qty=1},{id=37523,qty=1},{id=37541,qty=1}}}
DB[11620]={id=11620,zoneId=3537,name=[[A Father's Words]],level=71,minLevel=68,giver=[[Karuk]],giverType=[[NPC]],giverId=25435,ender=[[Veehja]],enderType=[[NPC]],enderId=25450,prevId=11619,rewardNextId=11625,wowhead=[[https://www.wowhead.com/wotlk/quest=11620]],image=[[assets/images/quests/placeholder.png]],desc=[[There is someone who might shed light on this mystery, $r.  It is rumored that the Kvaldir have kept a naga priestess alive at the temple on the west side of the shore. She will no doubt have great reason to resent her uninvited Kvaldir guests.  Perhaps my father is expecting her to cooperate with you in some way.]],logDesc=[[Look for Veehja at the Shrine of Scales on Riplash Strand.]]}
DB[11621]={id=11621,zoneId=3537,name=[[The Tablet of Leviroth]],name_loc=[[La tablilla de Leviroth]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=1996,poiY=5854,wowhead=[[https://www.wowhead.com/wotlk/quest=11621]],image=[[assets/images/quests/placeholder.png]],desc=[[You scour through the tablet's etchings, looking for any text you can understand.  You finally find the following fragment: "The sons of the fog will claim a thousand souls for the one who dwells in darkest waters.  His emissary will then awake." Karuk might be interested in this information.]],logDesc=[[Return to Karuk with the information you found on the tablet.]]}
DB[11622]={id=11622,zoneId=3537,name=[[Secrets of Riplash]],level=71,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11622]],image=[[assets/images/quests/placeholder.png]],desc=[[There is someone who might shed light on this mystery, $r.  It is rumored that the kvaldir have kept a handful of naga priestesses alive inside the temple. The high priestess, Veehja, will no doubt have great reason to resent her uninvited kvaldir guests.  Perhaps she can tell you more about what the writing on the tablet means.]],logDesc=[[Find Veehja at the ruins of Riplash in Borean Tundra.]]}
DB[11623]={id=11623,zoneId=3537,name=[[A Visit to the Curator]],level=72,minLevel=68,giver=[[Etaruk]],giverType=[[NPC]],giverId=25292,ender=[[Etaruk]],enderType=[[NPC]],enderId=25292,prevId=11617,wowhead=[[https://www.wowhead.com/wotlk/quest=11623]],image=[[assets/images/quests/placeholder.png]],desc=[[The leader of the mage hunter forces is a fearsome creature called Curator Insivius. My people have hunted the beasts of the seas and land for countless generations, but I've never seen anything like this curator before. He's landed one of those flying disks on the upper rim of the quarry and oversees the operation from there. $N, I can only believe the ancestors themselves sent you to my rescue and I hope you will help me drive the mage hunters from this quarry once and for all.]],logDesc=[[Etaruk, on the outskirts of the Coldrock Quarry, wants you to kill Curator Insivius.]],choiceRewards={{id=37378,qty=1},{id=37436,qty=1},{id=37521,qty=1},{id=37515,qty=1}}}
DB[11624]={id=11624,zoneId=3537,name=[[The Sky Will Know]],level=71,minLevel=69,giver=[[Spirit Talker Snarlfang]],giverType=[[NPC]],giverId=25339,ender=[[Imperean]],enderType=[[NPC]],enderId=25376,prevId=12486,rewardNextId=11627,wowhead=[[https://www.wowhead.com/wotlk/quest=11624]],image=[[assets/images/quests/placeholder.png]],desc=[[I must find out what happened to my master, Farseer Grimwalker! Earlier, he was observing the magnataur at nearby Magmoth. But one of his grunts just returned, saying that the group had been crushed, and that the farseer was dragged into the depths of the place. Before I send you on a suicide mission, I wish to consult with the spirits to learn more. There is an air elemental known as Imperean in the ruins of Eldra'nath to the west. She is wise and may give you the information we seek.]],logDesc=[[Speak with Imperean at the Ruins of Eldra'nath.]]}
DB[11625]={id=11625,zoneId=3537,name=[[The Trident of Naz'jan]],level=71,minLevel=68,giver=[[Veehja]],giverType=[[NPC]],giverId=25450,ender=[[Veehja]],enderType=[[NPC]],enderId=25450,prevId=11620,rewardNextId=11626,wowhead=[[https://www.wowhead.com/wotlk/quest=11625]],image=[[assets/images/quests/placeholder.png]],desc=[[Five hundred years ago, Azshara imprisoned a being named Leviroth in the waters below.  Now these barbarians seek to undo our queen's work! They took over our city and began to sacrifice my brethren to awaken him!  When they ran out of naga, they began to take tuskarr.  Their spirits will know no peace! I will help you, for it will go a long way towards quelling my vengeance.  Their captain, Ragnar, dwells deep inside northeastern Riplash.  He has in his possession a golden trident.  Bring it to me!]],logDesc=[[Veehja in Riplash wants you to go to the far northeastern end of the Riplash Ruins.  Once there slay Ragnar Drakkarlund and obtain the Trident of Naz'jan from him.]]}
DB[11626]={id=11626,zoneId=3537,name=[[The Emissary]],level=71,minLevel=68,giver=[[Veehja]],giverType=[[NPC]],giverId=25450,ender=[[Karuk]],enderType=[[NPC]],enderId=25435,prevId=11625,wowhead=[[https://www.wowhead.com/wotlk/quest=11626]],image=[[assets/images/quests/placeholder.png]],desc=[[Raj Naz'jan was the emperor of Riplash when Leviroth was imprisoned.  Azshara herself blessed his trident so it would slay the beast should it ever escape. Now you wield it, $r.  As much as it disgusts me, I will have my revenge on these barbaric giant-men. Take the trident to the depths beneath Riplash.  You will find Leviroth below an iceberg closest to northern Riplash. Drive the trident into his flesh and slay him!  Return to whomever sent you when you're done; I wish to see no more of you.]],logDesc=[[Find Leviroth in the waters below the iceberg floating among the northern edge of Riplash Ruins.  Use the Trident of Naz'jan to slay him and return to Karuk to the north of Riplash Strand.]],choiceRewards={{id=37213,qty=1},{id=37396,qty=1},{id=37423,qty=1},{id=37487,qty=1}}}
DB[11627]={id=11627,zoneId=3537,name=[[Boiling Point]],level=72,minLevel=69,giver=[[Imperean]],giverType=[[NPC]],giverId=25376,ender=[[Imperean]],enderType=[[NPC]],enderId=25376,prevId=11624,rewardNextId=11649,wowhead=[[https://www.wowhead.com/wotlk/quest=11627]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, it is information that you crave: the whereabouts and condition of your 'farseer'. He did not see so far as to avoid the trouble which befell him. Nevertheless, I will give you the means to acquire the knowledge. But first, you will do some things for me. No doubt you have seen the war between fire and water to the south. Simmer keeps boiling Churn's pool, and the two have been battling for ages. Go to the Charred Rise and Blistering Pool, and convince each of them to stop their bickering.]],logDesc=[[Imperean wants you to beat Simmer and Churn into submission.  Return to her at the Ruins of Eldra'nath when they have submitted.]]}
DB[11628]={id=11628,zoneId=3537,name=[[Shrouds of the Scourge]],level=72,minLevel=68,giver=[[Chieftain Wintergale]],giverType=[[NPC]],giverId=24703,ender=[[Chieftain Wintergale]],enderType=[[NPC]],enderId=24703,prevId=11894,rewardNextId=11630,wowhead=[[https://www.wowhead.com/wotlk/quest=11628]],image=[[assets/images/quests/placeholder.png]],desc=[[To the northeast looms the Temple City of En'kilah, the Scourge's seat in Borean Tundra. From behind its walls, the Scourge commander has sent his Nerubians to surround us. Remaining on the defensive would doom my people, but my advisors differ in their strategies. Durm would charge in blindly, while Sage Aeire favors stealth. The Temple City has blighted the nearby lands and the native creatures. Aeire believes the pelts of the scourged mammoths can serve as a cloak that may hide an infiltrator.]],logDesc=[[Chieftain Wintergale at Taunka'le Village wants you to bring him 5 Scourged Mammoth Pelts.]]}
DB[11629]={id=11629,zoneId=3537,name=[[Return to the Spirit Talker]],level=71,minLevel=69,giver=[[Imperean]],giverType=[[NPC]],giverId=25376,ender=[[Spirit Talker Snarlfang]],enderType=[[NPC]],enderId=25339,prevId=11649,rewardNextId=11631,wowhead=[[https://www.wowhead.com/wotlk/quest=11629]],image=[[assets/images/quests/placeholder.png]],desc=[[You have done what was asked, and now I give you that which you desire. Deliver this primal to the spirit talker back at your Bor'gorok Outpost. If she is wise, she will know a ritual to gain you the information which you seek.]],logDesc=[[Deliver Imperean's Primal to Spirit Talker Snarlfang at Bor'gorok Outpost.]]}
DB[11630]={id=11630,zoneId=3537,name=[[The Bad Earth]],level=72,minLevel=68,giver=[[Chieftain Wintergale]],giverType=[[NPC]],giverId=24703,ender=[[Chieftain Wintergale]],enderType=[[NPC]],enderId=24703,prevId=11628,rewardNextId=11633,wowhead=[[https://www.wowhead.com/wotlk/quest=11630]],image=[[assets/images/quests/placeholder.png]],desc=[[By curing the hides with the blighted earth outside the Temple City, Sage Aeire believes she can create a cloak which will cause most of the Scourge minions to ignore your presence. You should blend right in, she says. She'd best be correct. It's our only chance to gather information and plan our counterattack. You should be able to find the earth she needs poking in the areas to the south and west of the fortress. Bring it to me when you've finished gathering it.]],logDesc=[[Bring 8 clods of Scourged Earth to Chieftain Wintergale at Taunka'le Village.]]}
DB[11631]={id=11631,zoneId=3537,name=[[Vision of Air]],level=71,minLevel=69,giver=[[Spirit Talker Snarlfang]],giverType=[[NPC]],giverId=25339,ender=[[Spirit Talker Snarlfang]],enderType=[[NPC]],enderId=25339,prevId=11629,wowhead=[[https://www.wowhead.com/wotlk/quest=11631]],image=[[assets/images/quests/placeholder.png]],desc=[[Here, $N, I've attuned the primal to you. Open your soul to it in the presence of my totem of air and concentrate upon the fate of Farseer Grimwalker. The spirit of the wind touches all; with any luck you will be granted a vision.]],logDesc=[[Use Imperean's Primal to perform a ritual at Snarlfang's Totem at Bor'gorok Outpost to gain information concerning Farseer Grimwalker. Afterward, speak with Spirit Talker Snarlfang.]],choiceRewards={{id=37274,qty=1},{id=37352,qty=1},{id=37442,qty=1},{id=37530,qty=1}}}
DB[11632]={id=11632,zoneId=3537,name=[[What the Cold Wind Brings...]],level=71,minLevel=68,giverType=[[NPC]],ender=[[High Overlord Saurfang]],enderType=[[NPC]],enderId=25256,wowhead=[[https://www.wowhead.com/wotlk/quest=11632]],image=[[assets/images/quests/placeholder.png]],desc=[[You hold the carapace fragment of Ith'rix the Harvester and realize that this is only the beginning. Even now you sense that victory is fleeting. Surely the Lich King has a thousand more beasts like Ith'rix, waiting to be unleashed upon the Horde. Take your trophy and present it to High Overlord Saurfang, inside Warsong Hold. He should be notified of your victory over a powerful Scourge agent.]],logDesc=[[Take Ith'rix's Hardened Carapace to High Overlord Saurfang at Warsong Hold.]],choiceRewards={{id=37214,qty=1},{id=37394,qty=1},{id=37424,qty=1},{id=37505,qty=1}}}
DB[11633]={id=11633,zoneId=3537,name=[[Blending In]],level=72,minLevel=68,giver=[[Chieftain Wintergale]],giverType=[[NPC]],giverId=24703,ender=[[Chieftain Wintergale]],enderType=[[NPC]],enderId=24703,prevId=11630,rewardNextId=11640,wowhead=[[https://www.wowhead.com/wotlk/quest=11633]],image=[[assets/images/quests/placeholder.png]],desc=[[Sage Aeire has finished the shroud. Take it with you and travel to the Temple City of En'kilah. Don the cloak within the city's bounds to hide yourself from most of the Scourge there. This will be our best opportunity to gather information about the enemy's fortifications and leaders. While wearing the cloak, scout the three large spires on the grounds of the city. While the shroud will shield you from most of the Scourge, the En'kilah abominations will be able to find you if you get too close.]],logDesc=[[Chieftain Wintergale at Taunka'le Village wants you to wear the Imbued Scourge Shroud in the Temple City of En'kilah and scout the Spire of Blood, the Spire of Pain, and the Spire of Decay.]]}
DB[11634]={id=11634,zoneId=3537,name=[[Wind Master To'bor]],level=71,minLevel=68,giver=[[Overlord Razgor]],giverType=[[NPC]],giverId=25279,ender=[[Wind Master To'bor]],enderType=[[NPC]],enderId=25289,prevId=11602,rewardNextId=11636,wowhead=[[https://www.wowhead.com/wotlk/quest=11634]],image=[[assets/images/quests/placeholder.png]],desc=[[You're a tough mother, $N. I think your talents are better suited elsewhere - like the root of the whole damn problem! <Razgor points to the west.> A thousand Scourge, at least four full sized floating death machines and who knows what else. But you're gonna find out and then you're gonna handle it... That's right, you're gonna beat the hell out of the Scourge army that's currently beating down our door. Get to the top of Warsong Hold and report to Wind Master To'bor. He'll be expecting you.]],logDesc=[[Report to Wind Master To'bor at Warsong Hold.]]}
DB[11635]={id=11635,zoneId=3537,name=[[Farseer Grimwalker's Spirit]],level=71,minLevel=69,giver=[[Spirit Talker Snarlfang]],giverType=[[NPC]],giverId=25339,ender=[[Farseer Grimwalker's Spirit]],enderType=[[NPC]],enderId=25425,prevId=11631,rewardNextId=11637,wowhead=[[https://www.wowhead.com/wotlk/quest=11635]],image=[[assets/images/quests/placeholder.png]],desc=[[You must go to Magmoth to the east. You must descend into the depths of their caverns. You must speak with Farseer Grimwalker's spirit!]],logDesc=[[Speak with Farseer Grimwalker's Spirit inside of Magmoth.]]}
DB[11636]={id=11636,zoneId=3537,name=[[Magic Carpet Ride]],level=71,minLevel=68,giver=[[Wind Master To'bor]],giverType=[[NPC]],giverId=25289,ender=[[Gorge the Corpsegrinder]],enderType=[[NPC]],enderId=25329,prevId=11634,rewardNextId=11642,wowhead=[[https://www.wowhead.com/wotlk/quest=11636]],image=[[assets/images/quests/placeholder.png]],desc=[[Tanks, mon. I be talkin' bout siege machines! We got heavy tanks stationed at Garrosh's Landing on da west coast. We gonna get you to da tank and you gonna use da tank to lay down some Horde justice on da Scourge! Da only tricky part be getting' you der. No way we be sendin' you on our wind riders. Too risky. You see dat pixie o'er der? Dat blondie elf? Yanni be his name, mon. He can get you to da coast, safely. Once der, talk to Gorge da Corpsegrinder!]],logDesc=[[Talk to Yanni at Warsong Hold to arrange safe travel to the coast. Speak to Gorge the Corpsegrinder once you arrive at Garrosh's Landing.]]}
DB[11637]={id=11637,zoneId=3537,name=[[Kaganishu]],level=72,minLevel=69,giver=[[Farseer Grimwalker's Spirit]],giverType=[[NPC]],giverId=25425,ender=[[Farseer Grimwalker's Spirit]],enderType=[[NPC]],enderId=25425,prevId=11635,rewardNextId=11638,wowhead=[[https://www.wowhead.com/wotlk/quest=11637]],image=[[assets/images/quests/placeholder.png]],desc=[[After my small force of grunts were killed, I was dragged down here and ritually murdered. The snobold who did this is known as Kaganishu. Though you have vanquished his shaman helpers, my spirit is still tethered to this place. After he slew me, he created a fetish from my body, which anchors me here. Kaganishu is using it to learn all that I know of shamanism. You must retrieve the fetish from him and use it upon my spirit. Kaganishu is nearby in the caves. Only then will I truly be free.]],logDesc=[[Retrieve Kaganishu's Fetish and use it upon Farseer Grimwalker's Remains. You will need to give the fetish to Farseer Grimwalker's Spirit inside of Magmoth.]]}
DB[11638]={id=11638,zoneId=3537,name=[[Return My Remains]],level=71,minLevel=69,giver=[[Farseer Grimwalker's Spirit]],giverType=[[NPC]],giverId=25425,ender=[[Spirit Talker Snarlfang]],enderType=[[NPC]],enderId=25339,prevId=11637,wowhead=[[https://www.wowhead.com/wotlk/quest=11638]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, now that my spirit has been freed would you do me the honor of returning my remains to Spirit Talker Snarlfang? They lay upon the ground beneath me. I sense that the spirit talker is still at Bor'gorok Outpost to the west where last I saw her.]],logDesc=[[Deliver Farseer Grimwalker's Remains, which are resting below his spirit, to Spirit Talker Snarlfang at Bor'gorok Outpost.]],choiceRewards={{id=37049,qty=1},{id=37528,qty=1},{id=37573,qty=1},{id=37574,qty=1},{id=37575,qty=1},{id=37047,qty=1}}}
DB[11639]={id=11639,zoneId=3537,name=[[Revenge Upon Magmoth]],level=71,minLevel=69,giver=[[Ortrosh]],giverType=[[NPC]],giverId=25374,ender=[[Ortrosh]],enderType=[[NPC]],enderId=25374,prevId=11631,wowhead=[[https://www.wowhead.com/wotlk/quest=11639]],image=[[assets/images/quests/placeholder.png]],desc=[[The overlord refuses to allow the shaman to heal my wounds. He says that it will be a good lesson for me and give me time to reflect upon my failure. But you could get revenge for me and the others who fell at Magmoth! I know that the spirit talker wants you to go in there to save the farseer. It's just to the east. Go, $c... go slay the magnataur and their snobold servants. Regain the outpost's honor!]],logDesc=[[Kill 10 Magmoth Shaman, 5 Magmoth Foragers, 3 Magmoth Crushers, and 3 Mates of Magmothregar. Then, return to Ortrosh at Bor'gorok Outpost.]],choiceRewards={{id=37270,qty=1},{id=37353,qty=1},{id=37441,qty=1},{id=37479,qty=1}}}
DB[11640]={id=11640,zoneId=3537,name=[[Words of Power]],level=72,minLevel=68,giver=[[Chieftain Wintergale]],giverType=[[NPC]],giverId=24703,ender=[[Chieftain Wintergale]],enderType=[[NPC]],enderId=24703,prevId=11633,wowhead=[[https://www.wowhead.com/wotlk/quest=11640]],image=[[assets/images/quests/placeholder.png]],desc=[[Within the spires you described dwell the main lieutenants of the Scourge leader, the high priests. Not only do they command the Scourge forces, but they hold the key to the necropolis above, and their master. An endless stream of Scourge minions will overrun us if we can't find and defeat their leader. I cannot leave my people defenseless, however much Durm might want to bring the fight to the enemy. It falls to you, $N, to slay the high priests and take the scrolls they hold.]],logDesc=[[Bring High Priest Naferset's Scroll, High Priest Talet-Kha's Scroll, and High Priest Andorath's Scroll to Chieftain Wintergale at Taunka'le Village.]]}
DB[11641]={id=11641,zoneId=3537,name=[[A Courageous Strike]],level=72,minLevel=68,giver=[[Durm Icehide]],giverType=[[NPC]],giverId=24706,ender=[[Durm Icehide]],enderType=[[NPC]],enderId=24706,prevId=11633,wowhead=[[https://www.wowhead.com/wotlk/quest=11641]],image=[[assets/images/quests/placeholder.png]],desc=[[From the beginning, I've counseled that Chieftain Wintergale should assemble our mighty warriors and attack our enemy at their base. My advice has fallen on deaf ears and he has proven that he'd rather tip-toe around according to Sage Aeire's plans. I'll wait no longer. If Chieftain Wintergale is too cowardly to send our warriors into battle, perhaps you'd be willing to show him that a direct attack can succeed. Storm the Temple City of En'kilah and slay all in your path, $N.]],logDesc=[[Slay 15 En'kilah Ghouls and 5 En'kilah Necromancers and report back to Durm Icehide at Taunka'le Village.]]}
DB[11642]={id=11642,zoneId=3537,name=[[Tank Ain't Gonna Fix Itself]],level=71,minLevel=68,giver=[[Gorge the Corpsegrinder]],giverType=[[NPC]],giverId=25329,ender=[[Mobu]],enderType=[[NPC]],enderId=25475,prevId=11636,wowhead=[[https://www.wowhead.com/wotlk/quest=11642]],image=[[assets/images/quests/placeholder.png]],desc=[[We need to get these tanks back up and runnin'! They ain't gonna fix themselves. Mobu's gonna be the one to handle that stuff. Talk to him and see what he needs. Maybe you can shut him up before he finally drives me into a berserker frenzy and I cleave his little gnome-sized frame in two! I hate gnomes...]],logDesc=[[Speak with Mobu at Garrosh's Landing.]]}
DB[11643]={id=11643,zoneId=3537,name=[[Mobu's Pneumatic Tank Transjigamarig]],level=71,minLevel=68,giver=[[Mobu]],giverType=[[NPC]],giverId=25475,ender=[[Mobu]],enderType=[[NPC]],enderId=25475,prevId=11642,nextId=11651,exGroup=-11643,wowhead=[[https://www.wowhead.com/wotlk/quest=11643]],image=[[assets/images/quests/placeholder.png]],desc=[[These wrenches are useless, buddy. I need my pneumatic tank transjigamarig to get these things up and running! Unfortunately, I left it at my old digs, on the other side of this landing. It's the beat down hut next to the stables. You're gonna have to go and get it for me, because I sure as hellfire am not going to go anywhere near the mist. Oh yea, buddy, watch out for the mist. The mist is what tore up these shores. ]],logDesc=[[Mobu at the Coast of Echoes in the Borean Tundra wants you to recover his Pneumatic Tank Transjigamarig. ]]}
DB[11644]={id=11644,zoneId=3537,name=[[Super Strong Metal Plates!]],level=71,minLevel=68,giver=[[Mobu]],giverType=[[NPC]],giverId=25475,ender=[[Mobu]],enderType=[[NPC]],enderId=25475,prevId=11642,nextId=11651,exGroup=-11643,wowhead=[[https://www.wowhead.com/wotlk/quest=11644]],image=[[assets/images/quests/placeholder.png]],desc=[[I need metal to patch these tanks up! Super strong metal plates can be found scattered about all across Garrosh's Landing and at the bottom of the bay. Just be careful when you're out there searching for plates. The mist is... um... AGGRESSIVE! The mist is what took out the landing and the adjoining tuskarr town. Poor little tuskarr...]],logDesc=[[Mobu at the Coast of Echoes in the Borean Tundra wants you to collect 10 Super Strong Metal Plates.]]}
DB[11645]={id=11645,zoneId=3537,name=[[Dirty, Stinkin' Snobolds!]],level=71,minLevel=69,giver=[[Crafty Wobblesprocket]],giverType=[[NPC]],giverId=25477,ender=[[Crafty Wobblesprocket]],enderType=[[NPC]],enderId=25477,prevId=11708,rewardNextId=11650,wowhead=[[https://www.wowhead.com/wotlk/quest=11645]],image=[[assets/images/quests/placeholder.png]],desc=[[Those dirty, stinkin' snobolds... they stole all of my supplies! What's a snobold you ask? It's like a kobold, 'cept they serve the magnataur; kinda take care of them. I know, weird! Anywho, wanna help me out? I know the little creeps stole off with all of my stuff. Stupid me thinkin' that it'd be nice and safe, packed up on the north side of the airstrip. Why don'tcha do me a favor and head north to their stupid Magmoth. There's a cash reward if you bring all my stuff back quick!]],logDesc=[[Retrieve 10 boxes of Crafty's Stuff and return them to Crafty Wobblesprocket at Fizzcrank Airstrip.]]}
DB[11646]={id=11646,zoneId=3537,name=[[The Borean Inquisition]],level=71,minLevel=69,giver=[[Librarian Donathan]],giverType=[[NPC]],giverId=25262,ender=[[Librarian Normantis]],enderType=[[NPC]],enderId=25480,prevId=11590,rewardNextId=11648,wowhead=[[https://www.wowhead.com/wotlk/quest=11646]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen closely, $n, for there is not a moment to spare. Your prisoner is being prepared for interrogation here in our tower. In the event that he is less than forthcoming, your assistance may be required. Make your way up to where he is being detained and tell Librarian Normantis that I've sent you to assist him.]],logDesc=[[Donathan ordered you to offer your assistance to Librarian Normantis in the mage tower on Amber Ledge.]]}
DB[11647]={id=11647,zoneId=3537,name=[[Neutralizing the Cauldrons]],level=72,minLevel=68,giver=[[Sage Aeire]],giverType=[[NPC]],giverId=24709,ender=[[Sage Aeire]],enderType=[[NPC]],enderId=24709,prevId=11633,wowhead=[[https://www.wowhead.com/wotlk/quest=11647]],image=[[assets/images/quests/placeholder.png]],desc=[[The presence of plague cauldrons within the Temple City of En'kilah worries me greatly, $N. It's clear that Chieftain Wintergale trusts your judgment and your knowledge of our enemy. Would you help me deal with the cauldrons as you help the chieftain carry out his plans in the Temple City? I've prepared a totem which will attack and neutralize the contents of the cauldrons. All you must do is locate the cauldrons and use the totem near each. Each Scourge weapon we destroy brings us closer to victory.]],logDesc=[[Sage Aeire at Taunka'le Village wants you to use her totem to neutralize the East Cauldron, the Central Cauldron, and the West Cauldron in the Temple City of En'kilah.]],choiceRewards={{id=37234,qty=1},{id=37356,qty=1},{id=37439,qty=1},{id=37517,qty=1}}}
DB[11648]={id=11648,zoneId=3537,name=[[The Art of Persuasion]],level=71,minLevel=69,giver=[[Librarian Normantis]],giverType=[[NPC]],giverId=25480,ender=[[Librarian Normantis]],enderType=[[NPC]],enderId=25480,prevId=11646,rewardNextId=11663,wowhead=[[https://www.wowhead.com/wotlk/quest=11648]],image=[[assets/images/quests/placeholder.png]],desc=[[It is fortunate you're here, $r. You see, the Kirin Tor code of conduct frowns upon our taking certain 'extreme' measures - even in desperate times such as these. You, however, as an outsider, are not bound by such restrictions and could take any steps necessary in the retrieval of information. Do what you must. We need to know where Lady Evanor is being held at once! I'll just busy myself organizing these shelves here. Oh, and here, perhaps you'll find this old thing useful....]],logDesc=[[Librarian Normantis on Amber Ledge wants you to use the Neural Needler on the Imprisoned Beryl Sorcerer until he reveals the location of Lady Evanor.]]}
DB[11649]={id=11649,zoneId=3537,name=[[Motes of the Enraged]],level=71,minLevel=69,giver=[[Imperean]],giverType=[[NPC]],giverId=25376,ender=[[Imperean]],enderType=[[NPC]],enderId=25376,prevId=11627,rewardNextId=11629,wowhead=[[https://www.wowhead.com/wotlk/quest=11649]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that their little squabble is dealt with, there is still the matter of helping you and your spirit talker. As you can see, my vassals have been enraged by the ongoing war between fire and water. This will not change anytime soon, but it will serve to your advantage. In order to assist you, what we need are their motes. Head further into the ruins and retrieve them from the tempests.]],logDesc=[[Obtain 5 Tempest Motes and deliver them to Imperean at the Ruins of Eldra'nath.]]}
DB[11650]={id=11650,zoneId=3537,name=[[Just a Few More Things...]],level=71,minLevel=69,giver=[[Crafty Wobblesprocket]],giverType=[[NPC]],giverId=25477,ender=[[Crafty Wobblesprocket]],enderType=[[NPC]],enderId=25477,prevId=11645,wowhead=[[https://www.wowhead.com/wotlk/quest=11650]],image=[[assets/images/quests/placeholder.png]],desc=[[As you may have noticed, we created the airstrip on the southern border of a magnataur den! <Crafty says something uncharitable about Fizzcrank under her breath.> The old man has put me in charge of finding a... ahem... creative solution to this situation: if we don't deal with them soon, they'll come down here and tear us limb from limb! That's where you come in. I want you to get me everything on this shopping list. Please.]],logDesc=[[Collect Crafty's Tools, an Overcharged Capacitor, and a Handful of Rocknar's Grit. Deliver them to Crafty Wobblesprocket at Fizzcrank Airstrip.]]}
DB[11651]={id=11651,zoneId=3537,name=[[Tanks a lot...]],level=71,minLevel=68,giver=[[Mobu]],giverType=[[NPC]],giverId=25475,ender=[[Gorge the Corpsegrinder]],enderType=[[NPC]],enderId=25329,rewardNextId=11652,wowhead=[[https://www.wowhead.com/wotlk/quest=11651]],image=[[assets/images/quests/placeholder.png]],desc=[[Thanks for all your help, buddy. You can let Gorge know the tanks are ready for action. Hopefully you can clean up this place once and for all! ]],logDesc=[[Speak to Gorge the Corpsegrinder at the Coast of Echoes.]]}
DB[11652]={id=11652,zoneId=3537,name=[[The Plains of Nasam]],level=71,minLevel=68,giver=[[Gorge the Corpsegrinder]],giverType=[[NPC]],giverId=25329,ender=[[Garrosh Hellscream]],enderType=[[NPC]],enderId=25237,prevId=11651,wowhead=[[https://www.wowhead.com/wotlk/quest=11652]],image=[[assets/images/quests/placeholder.png]],desc=[[Once you're ready, jump into one of the tanks and drive it out to the Plains of Nasam, southeast of here. Use the tank's weapon arsenal to take down the Scourge army. If you get in a jam, the "Meatpounder" will tear 'em up and the land mines will finish 'em off! If you find any of our soldiers, grab 'em! One last thing, fuel tanks can be found all over the field. Try to get close enough to that structure in the center and see what's going on. If you do all of this and live, go to Hellscream!]],logDesc=[[Use the Horde Siege Tank to destroy 100 Scourge Soldiers and rescue 3 Injured Warsong Soldiers on the Plains of Nasam. You must also discover the identity of the leader of the Scourge assault. Report to Garrosh Hellscream at Warsong Hold should you succeed.]],choiceRewards={{id=37276,qty=1},{id=37325,qty=1},{id=37446,qty=1},{id=37476,qty=1}}}
DB[11653]={id=11653,zoneId=3537,name=[[Hah... You're Not So Big Now!]],level=71,minLevel=69,giver=[[Crafty Wobblesprocket]],giverType=[[NPC]],giverId=25477,ender=[[Crafty Wobblesprocket]],enderType=[[NPC]],enderId=25477,prevId=11650,rewardNextId=11658,wowhead=[[https://www.wowhead.com/wotlk/quest=11653]],image=[[assets/images/quests/placeholder.png]],desc=[[That'll do her, chief! So, here's what I want ya to do.... Take my blaster and head north to Magmoth. If we're gonna have a chance at all against those monsters, we need to cut them down to size... so to speak. In order to gauge its effectiveness, I need you to slay the magnataur while the blaster's effects are still on it. Any of the crushers or mates will do, but don't bother with the offspring... they're too small to worry about.]],logDesc=[[Test out Crafty's Ultra-Advanced Proto-Typical Shortening Blaster on 5 Magmoth Crushers or Mates of Magmothregar. After you have done so, return to her at Fizzcrank Airstrip.]],choiceRewards={{id=37272,qty=1},{id=37388,qty=1},{id=37428,qty=1},{id=37526,qty=1}}}
DB[11654]={id=11654,zoneId=3537,name=[[The Spire of Blood]],level=72,minLevel=68,giverType=[[NPC]],ender=[[Snow Tracker Grumm]],enderType=[[NPC]],enderId=25516,rewardNextId=11659,wowhead=[[https://www.wowhead.com/wotlk/quest=11654]],image=[[assets/images/quests/placeholder.png]],desc=[[As you inspect the captured blood vial, you realize its contents are still warm. The victim must have just been bled and may still be alive. What use would the Scourge have for blood? They've never shown an interest in live prisoners in the past. Perhaps if you can locate the source of the blood, you'll be able to discover what the Scourge is planning.]],logDesc=[[Search the Spire of Blood for more information about the Vial of Fresh Blood.]]}
DB[11655]={id=11655,zoneId=3537,name=[[Into the Mist]],level=71,minLevel=68,giver=[[Waltor of Pal'ea]],giverType=[[NPC]],giverId=25476,ender=[[Waltor of Pal'ea]],enderType=[[NPC]],enderId=25476,rewardNextId=11656,wowhead=[[https://www.wowhead.com/wotlk/quest=11655]],image=[[assets/images/quests/placeholder.png]],desc=[[Across the mist to the north you will find Garrosh's Landing. To the south are the ruins of my old home, Pal'ea. Both have been ransacked by an ancient force known as the Kvaldir. These fearsome savages slew all of my people without mercy and drove your people inland. All that remains of the tuskarr of Pal'ea are our personal effects, taken as relics by the Kvaldir. While we are not a vengeful race, justice must be served. The tuskarr relics must be returned to me. Enter the mist and find them...]],logDesc=[[Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to kill Kvaldir and recover 8 Tuskarr Relics.]]}
DB[11656]={id=11656,zoneId=3537,name=[[Burn in Effigy]],level=71,minLevel=68,giver=[[Waltor of Pal'ea]],giverType=[[NPC]],giverId=25476,ender=[[Waltor of Pal'ea]],enderType=[[NPC]],enderId=25476,prevId=11655,wowhead=[[https://www.wowhead.com/wotlk/quest=11656]],image=[[assets/images/quests/placeholder.png]],desc=[[Tuskarr magic is similar to what your people call shamanism. While we serve the elements differently than you, the power that we are able to call forth is formidable. <Waltor waves a torch-like baton in front of you.> With this tuskarr torch I want you to return to the mist and strike at the Kvaldir vessels. You will find three of their vessels docked behind the mist at Garrosh's Landing, north of here, and one docked off the shores of Pal'ea, to the south. Burn their ships in effigy! For all to see!]],logDesc=[[Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to use the Tuskarr Torch to burn the Kvaldir ships at Pal'ea and Garrosh's Landing. You must destroy the following ships: The Serpent's Maw, The Kur Drakkar, Bor's Hammer and Bor's Anvil. ]],choiceRewards={{id=37207,qty=1},{id=37418,qty=1},{id=37556,qty=1},{id=37483,qty=1}}}
DB[11658]={id=11658,zoneId=3537,name=[[Plan B]],level=71,minLevel=69,giver=[[Crafty Wobblesprocket]],giverType=[[NPC]],giverId=25477,ender=[[Crafty Wobblesprocket]],enderType=[[NPC]],enderId=25477,prevId=11653,wowhead=[[https://www.wowhead.com/wotlk/quest=11658]],image=[[assets/images/quests/placeholder.png]],desc=[[Okay, don't panic! The blaster might not've worked, but we still have options. <Crafty snaps her fingers.> We're going to divert attention away from the airstrip! To make this work, we'll need a few things first. <Wobblesprocket looks you up and down appraisingly.> Steeljaw's caravan, just to the west, stupidly took a shortcut through a taunka graveyard and was destroyed by their risen spirits. Head over there and get some outfits off of the dead orcs. Pick up one of their banners, too!]],logDesc=[[Collect 10 Warsong Outfits and a Warsong Banner. Bring them back to Crafty Wobblesprocket at Fizzcrank Airstrip.]]}
DB[11659]={id=11659,zoneId=3537,name=[[Shatter the Orbs!]],level=72,minLevel=68,giver=[[Snow Tracker Grumm]],giverType=[[NPC]],giverId=25516,ender=[[Snow Tracker Junek]],enderType=[[NPC]],enderId=24733,prevId=11654,wowhead=[[https://www.wowhead.com/wotlk/quest=11659]],image=[[assets/images/quests/placeholder.png]],desc=[[They're... bleeding the prisoners... putting the blood... in those globes. <Grumm's eyes close momentarily and he leans his head back.> The blood... taken up to necropolis... to feed blood prince... <Grumm gasps for breath.> P-promise... you'll... destroy blood... globes... bring word... to Junek. <The snow tracker collapses into unconsciousness.>]],logDesc=[[Destroy 5 Blood Globes and report to Snow Tracker Junek at Taunka'le Village.]]}
DB[11660]={id=11660,zoneId=3537,name=[[Horn of the Ancient Mariner]],level=71,minLevel=68,giver=[[Waltor of Pal'ea]],giverType=[[NPC]],giverId=25476,ender=[[Waltor of Pal'ea]],enderType=[[NPC]],enderId=25476,rewardNextId=11661,wowhead=[[https://www.wowhead.com/wotlk/quest=11660]],image=[[assets/images/quests/placeholder.png]],desc=[[A Kvaldir lieutenant known as Orabus directed the initial incursion against my people at Pal'ea, He oversaw the destruction of both villages and then disappeared into the mist. In those early days there was talk of a horn that Orabus gifted to the Kvaldir mistweavers. This horn could be used to summon him should the need arise. We need to get that horn from the Kvaldir mistweavers and call forth Orabus. If he is destroyed, these savages might retreat. Seek out mistweavers at Pal'ea, to the south.]],logDesc=[[Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to bring him the Horn of the Ancient Mariner.]]}
DB[11661]={id=11661,zoneId=3537,name=[[Orabus the Helmsman]],level=71,minLevel=68,giver=[[Waltor of Pal'ea]],giverType=[[NPC]],giverId=25476,ender=[[Waltor of Pal'ea]],enderType=[[NPC]],enderId=25476,prevId=11660,wowhead=[[https://www.wowhead.com/wotlk/quest=11661]],image=[[assets/images/quests/placeholder.png]],desc=[[Take the horn and travel west to the Warsong Jetty. Make your way to the end of the jetty and blow into the horn. The sound should rouse Orabus. Slay the foul beast and return to me!]],logDesc=[[Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to use the Horn of the Ancient Mariner to summon Orabus the Helmsman. Once summoned, slay Orabus the Helmsman.]],choiceRewards={{id=37208,qty=1},{id=37402,qty=1},{id=37543,qty=1},{id=37484,qty=1}}}
DB[11662]={id=11662,zoneId=3537,name=[[Seek Out Karuk!]],level=71,minLevel=68,giver=[[Waltor of Pal'ea]],giverType=[[NPC]],giverId=25476,ender=[[Karuk]],enderType=[[NPC]],enderId=25435,prevId=11656,nextId=11613,wowhead=[[https://www.wowhead.com/wotlk/quest=11662]],image=[[assets/images/quests/placeholder.png]],desc=[[A fellow survivor of Pal'ea known as Karuk has made his way to the main base of the Kvaldir in the Borean Tundra - far to the south where the snow was once bountiful. Karuk hides along the bluffs overlooking Riplash Strand. Seek out Karuk and let him know what you did for my people here at the Coast of Echoes. The safest route to Karuk is through your fortress. From Warsong Hold, take the road south and follow it around until you reach Riplash Strand.]],logDesc=[[Seek out Karuk at Riplash Strand.]]}
DB[11663]={id=11663,zoneId=3537,name=[[Sharing Intelligence]],level=71,minLevel=69,giver=[[Librarian Normantis]],giverType=[[NPC]],giverId=25480,ender=[[Librarian Donathan]],enderType=[[NPC]],enderId=25262,prevId=11648,rewardNextId=11671,wowhead=[[https://www.wowhead.com/wotlk/quest=11663]],image=[[assets/images/quests/placeholder.png]],desc=[[Thank you, $c! The information you've extracted is of vital importance to the Kirin Tor. Return at once to Donathan as we make plans for the rescue of Lady Evanor.]],logDesc=[[Normantis has asked you to report to Librarian Donathan on Amber Ledge.]]}
DB[11664]={id=11664,zoneId=3537,name=[[Escaping the Mist]],level=71,minLevel=68,giver=[[Mootoo the Younger]],giverType=[[NPC]],giverId=25504,ender=[[Elder Mootoo]],enderType=[[NPC]],enderId=25503,wowhead=[[https://www.wowhead.com/wotlk/quest=11664]],image=[[assets/images/quests/placeholder.png]],desc=[[I can hear the mist creatures outside. Their yells are driving me mad, but I dare not try to escape. And where would I even go? How long would it be until they caught up with me and executed me like the others? I wonder, how far has the mist crept, stranger? Has it overtaken this whole continent? Would you be willing to help me try and escape the mist? I think I can lead us back toward my father. I still sense his life spirit. He is close.]],logDesc=[[Follow Mootoo the Younger out of the mist. Speak to Elder Mootoo should you successfully save Mootoo the Younger.]],choiceRewards={{id=37212,qty=1},{id=37399,qty=1},{id=37422,qty=1},{id=37028,qty=1}}}
DB[11670]={id=11670,zoneId=3537,name=[[It Was The Orcs, Honest!]],level=72,minLevel=69,giver=[[Crafty Wobblesprocket]],giverType=[[NPC]],giverId=25477,ender=[[Crafty Wobblesprocket]],enderType=[[NPC]],enderId=25477,prevId=11658,wowhead=[[https://www.wowhead.com/wotlk/quest=11670]],image=[[assets/images/quests/placeholder.png]],desc=[[With all of those outfits you, er, recovered, I fashioned a Warsong orc disguise. I had the genius idea of combining it with some old stuff that I had left hanging around from last Hallows' End, so it should be foolproof! Here, in this sack is the disguise and the banner you recovered. Head down into the bowels of Magmoth and slay the magnataur chieftain, Magmothregar. If you're going to convince them to turn their attention on the Warsong orcs, you'll need to plant the banner while disguised.]],logDesc=[[While disguised as a Warsong orc, plant the Warsong Banner in the corpse of Magmothregar. Then, return with the disguise to Crafty Wobblesprocket at Fizzcrank Airstrip.]],choiceRewards={{id=37054,qty=1},{id=37073,qty=1},{id=37357,qty=1},{id=37072,qty=1},{id=37231,qty=1}}}
DB[11671]={id=11671,zoneId=3537,name=[[A Race Against Time]],level=71,minLevel=69,giver=[[Librarian Donathan]],giverType=[[NPC]],giverId=25262,ender=[[Librarian Donathan]],enderType=[[NPC]],enderId=25262,prevId=11663,rewardNextId=11679,wowhead=[[https://www.wowhead.com/wotlk/quest=11671]],image=[[assets/images/quests/placeholder.png]],desc=[[So it's true. They have her. It's clear what must be done, $r. She WILL be saved. I must remain here and aid in the rescue preparations. I call upon you again; this time to collect the prison key. All we know of this Salrand figure is that she cannot be harmed so long as her shield is intact. We've customized a special explosive that should strip her of this protection, allowing you to perform your duty. Return to me when you've collected the key. Hurry, $n. Lady Evanor is suffering!]],logDesc=[[Donathan on Amber Ledge has tasked you with using the Beryl Shield Detonator to bring down the shield at Beryl Point. You are then to defeat Salrand and collect the key she holds.]]}
DB[11672]={id=11672,zoneId=3537,name=[[Enlistment Day]],level=71,minLevel=68,giver=[[Recruitment Officer Blythe]],giverType=[[NPC]],giverId=25307,ender=[[General Arlos]],enderType=[[NPC]],enderId=25250,wowhead=[[https://www.wowhead.com/wotlk/quest=11672]],image=[[assets/images/quests/placeholder.png]],desc=[[You've come to enlist, right?  Normally you'd have to stand in line like the other recruits.  Normally you'd be out of luck because the recruitment ledger's gone missing and I can't process anyone until the new books get here. Fortunately for you, $N, I've heard about you and what you did in Outland.  To be honest, you're a cut above these poor saps.  Lines aren't for you. Go to the barracks and speak to General Arlos.  He'll be more than happy to meet with someone of your caliber.]],logDesc=[[Meet with General Arlos inside the barracks in Valiance Keep.]]}
DB[11673]={id=11673,zoneId=3537,name=[[Get Me Outa Here!]],level=72,minLevel=69,giver=[[Bonker Togglevolt]],giverType=[[NPC]],giverId=25589,ender=[[Fizzcrank Fullthrottle]],enderType=[[NPC]],enderId=25590,wowhead=[[https://www.wowhead.com/wotlk/quest=11673]],image=[[assets/images/quests/placeholder.png]],desc=[[I knew they'd send someone for me sooner or later... turned out to be later, of course. I came in here to parlay with the snobolds, but their main shaman, Kaganishu, decided instead that I'd make a tasty snack for Magmothregar. Wait... what?! They didn't send you?! DID THEY FORGET ABOUT ME?! Okay, you're here now and that's all that matters. As soon as you break this chain we'll make our way back to the airstrip. Then you can tell Fizzcrank I'm safely back. If he remembers me, that is.]],logDesc=[[Escort Bonker Togglevolt to safety and then report in with Fizzcrank Fullthrottle at Fizzcrank Airstrip.]],choiceRewards={{id=37049,qty=1},{id=37528,qty=1},{id=37573,qty=1},{id=37574,qty=1},{id=37575,qty=1},{id=37047,qty=1}}}
DB[11674]={id=11674,zoneId=3537,name=[[Sage Highmesa is Missing]],level=71,minLevel=68,giver=[[Greatmother Taiga]],giverType=[[NPC]],giverId=25602,ender=[[Sage Highmesa]],enderType=[[NPC]],enderId=25604,rewardNextId=11675,wowhead=[[https://www.wowhead.com/wotlk/quest=11674]],image=[[assets/images/quests/placeholder.png]],desc=[[There are many new mysteries walking the lands now. One of our sages, Highmesa, has foolishly gone north with only one longrunner to investigate something strange near the Dens of Dying. What are the dens, you ask? They are a sacred place to the magnataur, where they go in their old age to die. She saw something fall from the sky near them a few days ago. If you would be friend to the taunka, I would have you find and help her. She is not so stubborn that she will not accept your aid.]],logDesc=[[Find Sage Highmesa near the Dens of Dying.]]}
DB[11675]={id=11675,zoneId=3537,name=[[A Proper Death]],level=71,minLevel=68,giver=[[Sage Highmesa]],giverType=[[NPC]],giverId=25604,ender=[[Sage Highmesa]],enderType=[[NPC]],enderId=25604,prevId=11674,rewardNextId=11677,wowhead=[[https://www.wowhead.com/wotlk/quest=11675]],image=[[assets/images/quests/placeholder.png]],desc=[[The magnataur at the Dens of Dying have contracted a plague. We must find the cause, but first we must put them out of their misery. $R, you must go north onto the slopes in front of us and destroy as many of the poor creatures as you can.]],logDesc=[[Destroy 10 Plagued Magnataur and then return to Sage Highmesa south of The Dens of Dying.]]}
DB[11676]={id=11676,zoneId=3537,name=[[Merciful Freedom]],level=71,minLevel=68,giver=[[Shadowstalker Canarius]],giverType=[[NPC]],giverId=25438,ender=[[Shadowstalker Canarius]],enderType=[[NPC]],enderId=25438,prevId=11618,wowhead=[[https://www.wowhead.com/wotlk/quest=11676]],image=[[assets/images/quests/placeholder.png]],desc=[[The soldiers that they didn't kill are being held in cages scattered across this farmland. Through some thievery we've managed to find a few keys, but we're unable to get close enough to any prisoners without being attacked. We need your "talents" in securing those keys and freeing the prisoners. Bash in the brains of the necrolords and aberrations and take their keys. Use those keys to free Scourge prisoners.]],logDesc=[[Shadowstalker Canarius at Warsong Farms Outpost wants you to free 5 Scourge Prisoners.]]}
DB[11677]={id=11677,zoneId=3537,name=[[Stop the Plague]],level=71,minLevel=68,giver=[[Sage Highmesa]],giverType=[[NPC]],giverId=25604,ender=[[Sage Highmesa]],enderType=[[NPC]],enderId=25604,prevId=11675,wowhead=[[https://www.wowhead.com/wotlk/quest=11677]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm convinced that the plague is being caused by something in the caves up there. $C, I want you to take these seeds. I normally use them as a ward against the Scourge, though perhaps they can be used to disrupt whatever foulness is happening in the dens. Find the source of the plague and throw them into it.]],logDesc=[[Sage Highmesa, standing just south of The Dens of Dying, has asked you to use Highmesa's Cleansing Seeds at a Den of Dying Plague Cauldron to neutralize it.]],choiceRewards={{id=37223,qty=1},{id=37391,qty=1},{id=37427,qty=1},{id=37507,qty=1}}}
DB[11678]={id=11678,zoneId=3537,name=[[Find Bristlehorn]],level=71,minLevel=68,giver=[[Sage Highmesa]],giverType=[[NPC]],giverId=25604,ender=[[Longrunner Bristlehorn]],enderType=[[NPC]],enderId=25658,prevId=11677,rewardNextId=11687,wowhead=[[https://www.wowhead.com/wotlk/quest=11678]],image=[[assets/images/quests/placeholder.png]],desc=[[Bristlehorn should have returned by now. The other reason why we came up here was to investigate that Scourge structure to the west, which fell from the sky. He's impetuous and has likely gotten himself into trouble. $N, go to that place and find him, please.]],logDesc=[[Find Longrunner Bristlehorn at Talramas.]]}
DB[11679]={id=11679,zoneId=3537,name=[[Reforging the Key]],level=71,minLevel=69,giver=[[Librarian Donathan]],giverType=[[NPC]],giverId=25262,ender=[[Surristrasz]],enderType=[[NPC]],enderId=24795,prevId=11671,wowhead=[[https://www.wowhead.com/wotlk/quest=11679]],image=[[assets/images/quests/placeholder.png]],desc=[[Delays, delays... the one thing we cannot afford right now! As much as I hate to disturb Lord Surristrasz, he's our only hope of saving our beloved Evanor. Bring him the key fragments and hope that his mood is favorable. Hurry, $c, our assault team is waiting.]],logDesc=[[Donathan wants you to speak to Surristrasz on Amber Ledge.]]}
DB[11680]={id=11680,zoneId=3537,name=[[Taking Wing]],level=71,minLevel=69,giver=[[Surristrasz]],giverType=[[NPC]],giverId=24795,ender=[[Warmage Anzim]],enderType=[[NPC]],enderId=25356,prevId=11679,rewardNextId=11681,wowhead=[[https://www.wowhead.com/wotlk/quest=11680]],image=[[assets/images/quests/placeholder.png]],desc=[[The key is forged anew. Now heed my counsel, $r. Succeed in your endeavor or die trying, for if a single scale falls from one of my drakes I shall hold you personally accountable. Now, off with you.]],logDesc=[[Give Salrand's Key to Warmage Anzim when you are ready to free Evanor.]]}
DB[11681]={id=11681,zoneId=3537,name=[[Rescuing Evanor]],level=71,minLevel=69,giver=[[Warmage Anzim]],giverType=[[NPC]],giverId=25356,ender=[[Archmage Evanor]],enderType=[[NPC]],enderId=25785,prevId=11680,rewardNextId=11682,wowhead=[[https://www.wowhead.com/wotlk/quest=11681]],image=[[assets/images/quests/placeholder.png]],desc=[[At last, we attack! Once we've cleared the platform I'll use the key. You are to ensure that Lady Evanor remains safe after her release. Hurry now, let us be off!]],logDesc=[[Anzim on Amber Ledge wants you to fly with his war mages to free Lady Evanor at Beryl Point. You are then to report to her in the mage tower on Amber Ledge.]],choiceRewards={{id=37224,qty=1},{id=37387,qty=1},{id=37429,qty=1},{id=37509,qty=1}}}
DB[11682]={id=11682,zoneId=3537,name=[[Dragonspeak]],level=71,minLevel=69,giver=[[Archmage Evanor]],giverType=[[NPC]],giverId=25784,ender=[[Surristrasz]],enderType=[[NPC]],enderId=24795,prevId=11681,rewardNextId=11733,wowhead=[[https://www.wowhead.com/wotlk/quest=11682]],image=[[assets/images/quests/placeholder.png]],desc=[[I am aware of your recent deeds here, $n, and again I thank you. As for this local menace, we've learned all we need to know from them. They'll be dealt with in short order. On now to more important issues.... Azeroth needs you. The region just west of here is the center of an urgent crisis. I'll leave the details to Lord Surristrasz. You must speak with him at once. Good luck, friend of Dalaran.]],logDesc=[[Lady Evanor has sent you to speak with Surristrasz on Amber Ledge.]]}
DB[11682]={id=11682,zoneId=3537,name=[[Dragonspeak]],level=71,minLevel=69,giver=[[Archmage Evanor]],giverType=[[NPC]],giverId=25785,ender=[[Surristrasz]],enderType=[[NPC]],enderId=24795,prevId=11681,rewardNextId=11733,wowhead=[[https://www.wowhead.com/wotlk/quest=11682]],image=[[assets/images/quests/placeholder.png]],desc=[[I am aware of your recent deeds here, $n, and again I thank you. As for this local menace, we've learned all we need to know from them. They'll be dealt with in short order. On now to more important issues.... Azeroth needs you. The region just west of here is the center of an urgent crisis. I'll leave the details to Lord Surristrasz. You must speak with him at once. Good luck, friend of Dalaran.]],logDesc=[[Lady Evanor has sent you to speak with Surristrasz on Amber Ledge.]]}
DB[11683]={id=11683,zoneId=3537,name=[[Fallen Necropolis]],level=71,minLevel=68,giver=[[Sage Highmesa]],giverType=[[NPC]],giverId=25604,ender=[[Sage Highmesa]],enderType=[[NPC]],enderId=25604,prevId=11677,wowhead=[[https://www.wowhead.com/wotlk/quest=11683]],image=[[assets/images/quests/placeholder.png]],desc=[[The fallen necropolis to the west can only be assumed to still be filled with Scourge. While you are at Talramas, $c, I would ask that you dispatch all of the Lich King's servants that you find within and in the surrounding pools where it fell.]],logDesc=[[Destroy 20 Scourge of any type at Talramas and the Festering Pools. Then, return to Sage Highmesa just to the south of The Dens of the Dying.]],choiceRewards={{id=37239,qty=1},{id=37560,qty=1},{id=37355,qty=1},{id=37518,qty=1}}}
DB[11684]={id=11684,zoneId=3537,name=[[Scouting the Sinkholes]],level=71,minLevel=68,giver=[[Greatfather Mahan]],giverType=[[NPC]],giverId=24702,ender=[[Greatfather Mahan]],enderType=[[NPC]],enderId=24702,rewardNextId=11685,wowhead=[[https://www.wowhead.com/wotlk/quest=11684]],image=[[assets/images/quests/placeholder.png]],desc=[[Can you feel the tremors in the earth? The Scourge's nerubians are on the move deep beneath the ground. They've emerged to the southwest in the Geyser Fields, and are harassing the patrols Chieftain Wintergale sent out. <The taunka elder offers you a worn map.> Perhaps a single person can succeed where the patrols have failed. Take this with you to the Geyser Fields and map out the locations of the Nerubian sinkholes.]],logDesc=[[Greatfather Mahan at Taunka'le Village wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole.]]}
DB[11685]={id=11685,zoneId=3537,name=[[The Heart of the Elements]],level=71,minLevel=68,giver=[[Greatfather Mahan]],giverType=[[NPC]],giverId=24702,ender=[[Wind Tamer Barah]],enderType=[[NPC]],enderId=24730,prevId=11684,rewardNextId=11695,wowhead=[[https://www.wowhead.com/wotlk/quest=11685]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we know the exact locations of the nerubian sinkholes, we can collapse them to halt the Scourge offensive and cripple their force. Wind Tamer Barah knows a way to harness elementals to destroy the tunnels the Nerubians are using, but she will require your help. Southeast of the village, near the coast beyond the Frozen Reach, you'll find an area dominated by frozen earth elementals. The hearts of these elements are exactly what Wind Tamer Barah will need.]],logDesc=[[Bring 5 Elemental Hearts to Wind Tamer Barah at Taunka'le Village.]]}
DB[11686]={id=11686,zoneId=3537,name=[[The Warsong Farms]],level=71,minLevel=68,giver=[[Shadowstalker Ickoris]],giverType=[[NPC]],giverId=25437,ender=[[Shadowstalker Ickoris]],enderType=[[NPC]],enderId=25437,prevId=11618,rewardNextId=11703,wowhead=[[https://www.wowhead.com/wotlk/quest=11686]],image=[[assets/images/quests/placeholder.png]],desc=[[According to Luther's notes the Scourge is now using this place as a breeding ground for those monsters you see lumbering across the field. <Ickoris shudders.> Those monsters were once orcs... tauren... We need more information before a plan can be devised. I want you to investigate three sites that are heavily trafficked by Scourge: the Warsong Granary, southwest of us, Torp's Farm, directly west of us, and the old Warsong Slaughterhouse, north of us. Return to me once you've scouted 'em out.]],logDesc=[[Shadowstalker Ickoris at Warsong Farms Outpost wants you to scout Warsong Granary, Torp's Farm, and Warsong Slaughterhouse.]]}
DB[11687]={id=11687,zoneId=3537,name=[[The Doctor and the Lich-Lord]],level=72,minLevel=68,giver=[[Longrunner Bristlehorn]],giverType=[[NPC]],giverId=25658,ender=[[Sage Highmesa]],enderType=[[NPC]],enderId=25604,prevId=11678,rewardNextId=11689,wowhead=[[https://www.wowhead.com/wotlk/quest=11687]],image=[[assets/images/quests/placeholder.png]],desc=[[There are two... that must... be killed. The doctor and... the lich-lord... are above. Find them... destroy them... before.... ...it is too... late....]],logDesc=[[Destroy Doctor Razorgrin and Lich-Lord Chillwinter. Then, return to Sage Highmesa just to the south of The Dens of Dying.]]}
DB[11688]={id=11688,zoneId=3537,name=[[Damned Filthy Swine]],level=71,minLevel=68,giver=[[Farmer Torp]],giverType=[[NPC]],giverId=25607,ender=[[Farmer Torp]],enderType=[[NPC]],enderId=25607,prevId=11618,rewardNextId=11690,wowhead=[[https://www.wowhead.com/wotlk/quest=11688]],image=[[assets/images/quests/placeholder.png]],desc=[[Just look at 'em! My beautiful kodos are helpless to defend themselves against those filthy swine! I need you to buy me some time, $r. I think I can cure the kodo of the sickness, but you need to keep the unliving swine off 'em, else there'll be nothin' left to cure! Get out there and send those swine to their graves - permanently!]],logDesc=[[Farmer Torp at Warsong Farms Outpost wants you to kill 10 Unliving Swine.]]}
DB[11689]={id=11689,zoneId=3537,name=[[Return with the Bad News]],level=71,minLevel=68,giver=[[Sage Highmesa]],giverType=[[NPC]],giverId=25604,ender=[[Greatmother Taiga]],enderType=[[NPC]],enderId=25602,prevId=11687,wowhead=[[https://www.wowhead.com/wotlk/quest=11689]],image=[[assets/images/quests/placeholder.png]],desc=[[The greatmother will need to know, $N. Will you please return to Taunka'le? Tell her that I will be following shortly.]],logDesc=[[Speak with Greatmother Taiga at Taunka'le Village.]],choiceRewards={{id=37529,qty=1},{id=37354,qty=1},{id=37440,qty=1},{id=37519,qty=1},{id=37074,qty=1}}}
DB[11690]={id=11690,zoneId=3537,name=[[Bring 'Em Back Alive]],level=71,minLevel=68,giver=[[Farmer Torp]],giverType=[[NPC]],giverId=25607,ender=[[Farmer Torp]],enderType=[[NPC]],enderId=25607,prevId=11688,wowhead=[[https://www.wowhead.com/wotlk/quest=11690]],image=[[assets/images/quests/placeholder.png]],desc=[[Take this riding snaffle, $N. You'll notice that I've placed a tiny medicine dispenser in the mouthpiece. That thing will cure the infection as soon as a kodo bites down. Once you've cured the sick out of 'em, you'll need to ride 'em home. They'll be weak so you'll need to gently direct 'em here. Bring my babies back, $N! One last thing, you've got ten minutes! That's how long the antidote will remain effective inside that snaffle.]],logDesc=[[Farmer Torp at Warsong Farms Outpost wants you to rescue 8 Infected Kodo Beasts.]],choiceRewards={{id=36884,qty=1},{id=36885,qty=1},{id=36886,qty=1},{id=36887,qty=1}}}
DB[11692]={id=11692,zoneId=3537,name=[[Check in With Bixie]],level=71,minLevel=68,giver=[[Mordle Cogspinner]],giverType=[[NPC]],giverId=25702,ender=[[Bixie Wrenchshanker]],enderType=[[NPC]],enderId=25705,prevId=11710,rewardNextId=11693,wowhead=[[https://www.wowhead.com/wotlk/quest=11692]],image=[[assets/images/quests/placeholder.png]],desc=[[You're a proven $g hero : heroine;. I have another problem! My boss, Tinky, went east with Bixie Wrenchshanker and I CAN'T get the outgoing on this thing to work! Tinky's the only one that can fix it and we really need it working one-hundred percent. You think you could find them? Bixie said something about following some old magnataur to a place called The Dens of Dying. I'm guessing that's where you'll find them. You can catch a ride out there by talking with Kara Thricestar at the runway.]],logDesc=[[Mordle Cogspinner has asked you to find Bixie Wrenchshanker to the south of The Dens of Dying.]]}
DB[11693]={id=11693,zoneId=3537,name=[[Oh Great... Plagued Magnataur!]],level=71,minLevel=68,giver=[[Bixie Wrenchshanker]],giverType=[[NPC]],giverId=25705,ender=[[Bixie Wrenchshanker]],enderType=[[NPC]],enderId=25705,prevId=11692,rewardNextId=11694,wowhead=[[https://www.wowhead.com/wotlk/quest=11693]],image=[[assets/images/quests/placeholder.png]],desc=[[Tinky and I came out here stalking some old magnataur. Apparently those caves up there are where they go to die. Of course, we had no idea that they were going to get plagued when they went in there. We can't have plagued things just roaming about; it's not healthy. Say, why don't you put down a number of those things while I figure out what our next step should be?]],logDesc=[[Kill 10 Plagued Magnataur and then return to Bixie Wrenchshanker to the south of The Dens of Dying.]]}
DB[11694]={id=11694,zoneId=3537,name=[[There's Something Going On In Those Caves]],level=71,minLevel=68,giver=[[Bixie Wrenchshanker]],giverType=[[NPC]],giverId=25705,ender=[[Bixie Wrenchshanker]],enderType=[[NPC]],enderId=25705,prevId=11693,wowhead=[[https://www.wowhead.com/wotlk/quest=11694]],image=[[assets/images/quests/placeholder.png]],desc=[[So, while you were out taking care of those plagued beasts, I took a peek inside the caves up there. There are cultists in there plaguing them! They have some sort of noxious concoction brewing in a cauldron. I have a powder that I normally use as an anti-poison, and I mixed it up with some other stuff. I think it'll neutralize their brew! Take it up to one of those caves and see if it works.]],logDesc=[[Bixie Wrenchshanker, skulking just to the south of The Dens of Dying, has asked you to use Bixie's Inhibiting Powder at a Den of Dying Plague Cauldron to neutralize it.]],choiceRewards={{id=37223,qty=1},{id=37391,qty=1},{id=37427,qty=1},{id=37507,qty=1}}}
DB[11695]={id=11695,zoneId=3537,name=[[The Horn of Elemental Fury]],level=71,minLevel=68,giver=[[Wind Tamer Barah]],giverType=[[NPC]],giverId=24730,ender=[[Wind Tamer Barah]],enderType=[[NPC]],enderId=24730,prevId=11685,rewardNextId=11706,wowhead=[[https://www.wowhead.com/wotlk/quest=11695]],image=[[assets/images/quests/placeholder.png]],desc=[[I can fashion the likeness of an elemental from these pieces of inanimate stone, but breathing life into it is different. For that, we'll need help and a bit of luck. Legend tells of an ancient artifact called the Horn of Elemental Fury, sought after by a great hero. I'll lend you a scroll with a copy of the tale. I don't know if the legend is true, but it's our best bet. If the legend is right, the parts of the horn may be in the Flood Plains surrounding the village to the north and southwest.]],logDesc=[[Reclaim the Lower Horn Half and Upper Horn Half from Chieftain Burblegoggle and Chieftain Gurgleboggle and bring them to Wind Tamer Barah at Taunka'le Village.]]}
DB[11697]={id=11697,zoneId=3537,name=[[Rats, Tinky Went into the Necropolis!]],level=71,minLevel=68,giver=[[Bixie Wrenchshanker]],giverType=[[NPC]],giverId=25705,ender=[[Tinky Wickwhistle]],enderType=[[NPC]],enderId=25714,prevId=11694,rewardNextId=11699,wowhead=[[https://www.wowhead.com/wotlk/quest=11697]],image=[[assets/images/quests/placeholder.png]],desc=[[I told Tinky not to go off on her own, but she just HAD to check out that crashed necropolis to the west. I'm 100% certain that those cultists came from inside that thing, which means I'm now 100% certain that Tinky's in trouble! She's the airstrip's number one engineer. Without her we're doomed! I'd find her myself, but one of those things got in a swipe on my leg before I could vanish again. $N, if anyone can get her out, it's you!]],logDesc=[[Find Tinky Wickwhistle inside Talramas.]]}
DB[11698]={id=11698,zoneId=3537,name=[[Might As Well Wipe Out the Scourge]],level=71,minLevel=68,giver=[[Bixie Wrenchshanker]],giverType=[[NPC]],giverId=25705,ender=[[Bixie Wrenchshanker]],enderType=[[NPC]],enderId=25705,prevId=11694,wowhead=[[https://www.wowhead.com/wotlk/quest=11698]],image=[[assets/images/quests/placeholder.png]],desc=[[If the cultists up in those caves survived the crash, then that fallen necropolis to the west can only be assumed to still be filled with Scourge. There're probably lots of them out in front of it in the pools, too! While you're at Talramas, $c, do you think you could dispatch all of the Lich King's flunkies that you find there?]],logDesc=[[Destroy 20 Scourge of any type at Talramas and the Festering Pools. Then, return to Bixie Wrenchshanker just to the south of The Dens of the Dying.]],choiceRewards={{id=37239,qty=1},{id=37560,qty=1},{id=37355,qty=1},{id=37518,qty=1}}}
DB[11699]={id=11699,zoneId=3537,name=[[I'm Stuck in this Damned Cage... But Not For Long!]],level=72,minLevel=68,giver=[[Tinky Wickwhistle]],giverType=[[NPC]],giverId=25714,ender=[[Tinky Wickwhistle]],enderType=[[NPC]],enderId=25714,prevId=11697,wowhead=[[https://www.wowhead.com/wotlk/quest=11699]],image=[[assets/images/quests/placeholder.png]],desc=[[The cultists magicked me into this cage and there's no door to it. Little did they know that I'm the chief transmatter engineer for the airstrip! With your help, and a little elbow-grease, I won't be in here for long. I'm going to need an engine-core crystal from one of the ghouls in here, a magical gyroscope from their doctor, and a piloting scourgestone from the lich-lord up top. With all of that stuff, I should be able to make a port device to get back to Fizzcrank's and escape the gnome way!]],logDesc=[[Collect an Engine-Core Crystal, a Magical Gyroscope, and a Piloting Scourgestone. Deliver them to Tinky Wickwhistle at Talramas.]]}
DB[11700]={id=11700,zoneId=3537,name=[[Let Bixie Know]],level=71,minLevel=68,giver=[[Tinky Wickwhistle]],giverType=[[NPC]],giverId=25714,ender=[[Bixie Wrenchshanker]],enderType=[[NPC]],enderId=25705,prevId=11699,wowhead=[[https://www.wowhead.com/wotlk/quest=11700]],image=[[assets/images/quests/placeholder.png]],desc=[[My evil twin's out there somewhere now. I'm pretty sure that she's not back at the airstrip. In fact, wherever she ended up, it's colder there than here. But I could only 'feel' her for a moment. Oh well, I'll reconfigure this thing and port myself back to the airstrip soon enough. In the meantime, do you think you could go east and let Bixie know that I'll meet her back there? Thanks, $N!]],logDesc=[[Speak with Bixie Wrenchshanker just south of The Dens of Dying.]]}
DB[11701]={id=11701,zoneId=3537,name=[[Back to the Airstrip]],level=71,minLevel=68,giver=[[Bixie Wrenchshanker]],giverType=[[NPC]],giverId=25705,ender=[[Fizzcrank Fullthrottle]],enderType=[[NPC]],enderId=25590,prevId=11700,wowhead=[[https://www.wowhead.com/wotlk/quest=11701]],image=[[assets/images/quests/placeholder.png]],desc=[[Okay, I think I'm going to start making my way back to the airstrip, too. Of course, I'm moving a little slower with this leg injury. Say, do you think you could get there ahead of me and pass on the good news to Ol' Fizzcrank? I bet anything that there'll be a reward in it for you. Thanks, $N!]],logDesc=[[Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip in Borean Tundra.]],choiceRewards={{id=37529,qty=1},{id=37354,qty=1},{id=37440,qty=1},{id=37519,qty=1},{id=38214,qty=1}}}
DB[11702]={id=11702,zoneId=3537,name=[[King Mrgl-Mrgl]],level=71,minLevel=69,giver=[[Supply Master Taz'ishi]],giverType=[[NPC]],giverId=25736,ender=[[King Mrgl-Mrgl]],enderType=[[NPC]],enderId=25197,rewardNextId=11571,wowhead=[[https://www.wowhead.com/wotlk/quest=11702]],image=[[assets/images/quests/placeholder.png]],desc=[[Dis is gonna sound weird, $c, but dere be a murloc askin' for our help! He goes by da name of King Mrgl-Mrgl, leader of da Winterfin murlocs. Him and his people been run outa dere village and wantin' you to come save dem. You find him by headin' west and go down da cliffs. He hangin' out on da south side of da Winterfin Retreat.]],logDesc=[[Speak with King Mrgl-Mrgl at Winterfin Retreat.]]}
DB[11703]={id=11703,zoneId=3537,name=[[Get to Getry]],level=71,minLevel=68,giver=[[Shadowstalker Ickoris]],giverType=[[NPC]],giverId=25437,ender=[[Shadowstalker Getry]],enderType=[[NPC]],enderId=25729,prevId=11686,wowhead=[[https://www.wowhead.com/wotlk/quest=11703]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge agent that's overseeing the abduction and transformation of Horde soldiers into undead monsters is using the northwest farm as a spawning glade. Shadowstalker Getry has been staking out that monster for the past week and has gathered some vital information that might allow us to end this menace. Get to Getry and see if you can help him put a stop to this Scourge assembly line. You'll find Getry at the abandoned tower on the northwest border of these farms.]],logDesc=[[Find Shadowstalker Getry at Warsong Farms.]]}
DB[11704]={id=11704,zoneId=3537,name=[[King Mrgl-Mrgl]],level=71,minLevel=69,giver=[[Mordle Cogspinner]],giverType=[[NPC]],giverId=25702,ender=[[King Mrgl-Mrgl]],enderType=[[NPC]],enderId=25197,rewardNextId=11571,wowhead=[[https://www.wowhead.com/wotlk/quest=11704]],image=[[assets/images/quests/placeholder.png]],desc=[[This is the weirdest thing, $c, but there's a murloc asking for our help! He goes by the name of King Mrgl-Mrgl, leader of the Winterfin murlocs. It would seem that he and his people have been run out of their village and they want someone to come save them. That someone is you! You'll find Winterfin Retreat, and the king, by heading west down the road until you come to the cliffs. Head down to the water line near the Blistering Pool.]],logDesc=[[Speak with King Mrgl-Mrgl at Winterfin Retreat.]]}
DB[11705]={id=11705,zoneId=3537,name=[[Foolish Endeavors]],level=71,minLevel=68,giver=[[Shadowstalker Getry]],giverType=[[NPC]],giverId=25729,ender=[[Garrosh Hellscream]],enderType=[[NPC]],enderId=25237,prevId=11703,nextId=11709,rewardNextId=11709,wowhead=[[https://www.wowhead.com/wotlk/quest=11705]],image=[[assets/images/quests/placeholder.png]],desc=[[This is madness. How do they expect us to take on a Scourge necrolord and an unknown number of his minions? <Getry sighs.> If Ickoris sent you he must think that you are capable of great feats. Perhaps you will call down a miracle today, eh? When you're ready we will descend and face Varidus. If we make it out of this mess in one piece, report back to Hellscream in Warsong Hold.]],logDesc=[[Help Getry defeat Varidus the Flenser at Warsong Farms. Report to Garrosh Hellscream should you succeed. ]],choiceRewards={{id=37447,qty=1},{id=37545,qty=1},{id=37475,qty=1},{id=37277,qty=1}}}
DB[11706]={id=11706,zoneId=3537,name=[[The Collapse]],level=71,minLevel=68,giver=[[Wind Tamer Barah]],giverType=[[NPC]],giverId=24730,ender=[[Wind Tamer Barah]],enderType=[[NPC]],enderId=24730,prevId=11695,wowhead=[[https://www.wowhead.com/wotlk/quest=11706]],image=[[assets/images/quests/placeholder.png]],desc=[[I have created and bound Alluvius using the Horn of Elemental Fury. He will respond to the horn's call when you stand near the southernmost sinkhole in the Geyser Fields. The quake Alluvius will unleash should collapse the Nerubian tunnels and put an end to their flanking attack. I wouldn't be surprised if the Nerubian commander showed himself after the quake. If the collapse of the tunnels doesn't break the back of their assault, the defeat of their leader surely will.]],logDesc=[[Wind Tamer Barah at Taunka'le Village wants you to collapse the Nerubian sinkholes using the Horn of Elemental Fury and defeat Lord Kryxix.]],choiceRewards={{id=37228,qty=1},{id=37375,qty=1},{id=37437,qty=1},{id=37516,qty=1}}}
DB[11707]={id=11707,zoneId=3537,name=[[Distress Call]],level=71,minLevel=68,giver=[[Airman Skyhopper]],giverType=[[NPC]],giverId=25737,ender=[[Fizzcrank Fullthrottle]],enderType=[[NPC]],enderId=25590,prevId=11897,rewardNextId=11708,wowhead=[[https://www.wowhead.com/wotlk/quest=11707]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh good, you're $N, right? We need your help up north at Fizzcrank Airstrip, like yesterday! The magnataur, and the Scourge... and the pumping station! It's madness I tell you, madness! You've got to head up there and talk to old man Fullthrottle a.s.a.p.!]],logDesc=[[Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip.]]}
DB[11708]={id=11708,zoneId=3537,name=[[The Mechagnomes]],level=71,minLevel=68,giver=[[Fizzcrank Fullthrottle]],giverType=[[NPC]],giverId=25590,ender=[[Jinky Wingnut]],enderType=[[NPC]],enderId=25747,prevId=11707,rewardNextId=11712,wowhead=[[https://www.wowhead.com/wotlk/quest=11708]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you're here, it's time for me to tell you the full story of what's going on. After you've heard my tale, go outside and find my second-in-command, Jinky Wingnut. She'll handle everything from here on out.]],logDesc=[[Listen to Fizzcrank Fullthrottle's tale and then find Jinky Wingnut at Fizzcrank Airstrip.]]}
DB[11709]={id=11709,zoneId=3537,name=[[Nork Bloodfrenzy's Charge]],level=71,minLevel=68,giver=[[Garrosh Hellscream]],giverType=[[NPC]],giverId=25237,ender=[[Warden Nork Bloodfrenzy]],enderType=[[NPC]],enderId=25379,prevId=11705,rewardNextId=11711,wowhead=[[https://www.wowhead.com/wotlk/quest=11709]],image=[[assets/images/quests/placeholder.png]],desc=[[While you have done much to secure our foothold in these frozen wastes, other dangers still lurk in the shadows. I want you to assist Warden Nork Bloodfrenzy, stationed at the internment camp just outside and immediately southeast of Warsong Hold. Seek him out and offer your assistance for prisoner transport and exchange. You are dismissed, $N.]],logDesc=[[Speak to Warden Nork Bloodfrenzy at Warsong Hold in Borean Tundra.]]}
DB[11710]={id=11710,zoneId=3537,name=[[What's the Matter with the Transmatter?]],level=71,minLevel=68,giver=[[Mordle Cogspinner]],giverType=[[NPC]],giverId=25702,ender=[[Mordle Cogspinner]],enderType=[[NPC]],enderId=25702,prevId=11708,rewardNextId=11692,wowhead=[[https://www.wowhead.com/wotlk/quest=11710]],image=[[assets/images/quests/placeholder.png]],desc=[[There're spare parts strewn all over to the east in the Scalding Pools, the Geyser Fields... heck, probably even up on the pumping station still, too. Bring back a whole bunch. Maybe then I'll be able to get outgoing teleport on this thing working, not to mention getting the incoming transmatter ports aligned. I'd hate to see another accident....]],logDesc=[[Collect 15 Fizzcrank Spare Parts and deliver them to Mordle Cogspinner at Fizzcrank Airstrip.]]}
DB[11711]={id=11711,zoneId=3537,name=[[Coward Delivery... Under 30 Minutes or it's Free]],level=71,minLevel=68,giver=[[Warden Nork Bloodfrenzy]],giverType=[[NPC]],giverId=25379,ender=[[Scout Tungok]],enderType=[[NPC]],enderId=25440,prevId=11709,rewardNextId=11714,wowhead=[[https://www.wowhead.com/wotlk/quest=11711]],image=[[assets/images/quests/placeholder.png]],desc=[[We're seeing more deserters show up at our gates with each passing day. We simply do not have enough room to keep all of these maggots caged up. Especially not if we want to keep the pigs happy. <Nork snorts as he laughs.> I want you to escort one of these cowards to the crossroads east of here and fire this flare gun. One of their captains will show up when they see the flare and take the coward off your hands. Report to Scout Tungok on the east road once the delivery has been made. ]],logDesc=[[Take the Alliance Deserter to the crossroads east of Warsong Hold and fire your Warsong Flare Gun to signal the Alliance. Report to Scout Tungok once you have successfully delivered the Alliance Deserter to their destination.]]}
DB[11712]={id=11712,zoneId=3537,name=[[Re-Cursive]],level=71,minLevel=68,giver=[[Jinky Wingnut]],giverType=[[NPC]],giverId=25747,ender=[[Jinky Wingnut]],enderType=[[NPC]],enderId=25747,prevId=11708,rewardNextId=11788,wowhead=[[https://www.wowhead.com/wotlk/quest=11712]],image=[[assets/images/quests/placeholder.png]],desc=[[If you listened to the old man, then you know that we have gnomes out there that were changed. Gearmaster Mechazod infected them with something that reversed the "Curse of the Flesh", and now they're robots! We think we have a way to re-curse them back to normal. We want you to take this re-cursive transmatter injection and use it on the corpses of any mechagnomes you come across. We're hoping that this stuff will cure them and allow us to lock onto them to port 'em out of there. Whaddya say, $N?]],logDesc=[[Jinky Wingnut at Fizzcrank Airstrip has asked you to use the Re-Cursive Transmatter Injection on 6 Fizzcrank Mechagnomes.]],choiceRewards={{id=37234,qty=1},{id=37356,qty=1},{id=37439,qty=1},{id=37517,qty=1}}}
DB[11713]={id=11713,zoneId=3537,name=[[Scouting the Sinkholes]],level=71,minLevel=68,giver=[[Abner Fizzletorque]],giverType=[[NPC]],giverId=25780,ender=[[Abner Fizzletorque]],enderType=[[NPC]],enderId=25780,prevId=11873,rewardNextId=11715,wowhead=[[https://www.wowhead.com/wotlk/quest=11713]],image=[[assets/images/quests/placeholder.png]],desc=[[Fizzcrank sent out an aerial surveillance team to map the Nerubian sinkholes in the southern part of the Geyser Fields, but they haven't yet returned. I can't afford to wait any longer for their information, so I'm going to need someone to check out the sinkholes on foot. I understand the dangers involved, and I'll compensate you accordingly. Take this map with you and record the vital information about each of the sinkholes you encounter out there.]],logDesc=[[Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole.]]}
DB[11714]={id=11714,zoneId=3537,name=[[Vermin Extermination]],level=71,minLevel=68,giver=[[Scout Tungok]],giverType=[[NPC]],giverId=25440,ender=[[Scout Tungok]],enderType=[[NPC]],enderId=25440,prevId=11711,wowhead=[[https://www.wowhead.com/wotlk/quest=11714]],image=[[assets/images/quests/placeholder.png]],desc=[[Perhaps you'd be interested in helping me clean up these fields? They're littered with dirty little rat men! Kobolds, snobolds, whatever you wanna call 'em, they're all over the damned place. The stink alone is making my life hell! Take care of the vermin for me and I'll make it worth your while, $N. ]],logDesc=[[Scout Tungok at the Bloodspore Plains in the Borean Tundra wants you to kill 8 Bloodspore Harvesters, 5 Bloodspore Firestarters and 2 Bloodspore Roasters.]],choiceRewards={{id=37205,qty=1},{id=37404,qty=1},{id=37524,qty=1},{id=37481,qty=1}}}
DB[11715]={id=11715,zoneId=3537,name=[[Fueling the Project]],level=71,minLevel=68,giver=[[Abner Fizzletorque]],giverType=[[NPC]],giverId=25780,ender=[[Abner Fizzletorque]],enderType=[[NPC]],enderId=25780,prevId=11713,rewardNextId=11718,wowhead=[[https://www.wowhead.com/wotlk/quest=11715]],image=[[assets/images/quests/placeholder.png]],desc=[[I plan to build a machine that will collapse the tunnels the Scourge is using to deploy their Nerubians, but with the main drilling rig out of order, we'll have to collect the fuel for the device some other way. Out in the Geyser Fields to the southeast, small pools of oil bubble up away from the main rig. If you can collect enough of the oil from those pools, I can make a crude fuel to power the machine. Simply deploy the collector near the rig, and it will pump and store the oil in its tank.]],logDesc=[[Abner Fizzletorque at Fizzcrank Airstrip wants you to collect 8 Barrels of Oil using the Portable Oil Collector.]]}
DB[11716]={id=11716,zoneId=3537,name=[[The Wondrous Bloodspore]],level=71,minLevel=68,giver=[[Bloodmage Laurith]],giverType=[[NPC]],giverId=25381,ender=[[Bloodmage Laurith]],enderType=[[NPC]],enderId=25381,rewardNextId=11717,wowhead=[[https://www.wowhead.com/wotlk/quest=11716]],image=[[assets/images/quests/placeholder.png]],desc=[[We are witnessing something amazing here, $r. A whole undiscovered ecology lives and breathes not more than a few paces from us! I surmise it is the bloodspore plant that sets this environment abuzz. I have collected some pollen from the nearby male species of bloodspore plant but still lack female receptors for pollination. Fetch me a bushel of the bloodspore carpels. You'll find them near the larger plants surrounding us. Be wary of their guardians! The kobolds won't give them up easily!]],logDesc=[[Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 10 Bloodspore Carpels.]]}
DB[11717]={id=11717,zoneId=3537,name=[[Pollen from the Source]],level=71,minLevel=68,giver=[[Bloodmage Laurith]],giverType=[[NPC]],giverId=25381,ender=[[Bloodmage Laurith]],enderType=[[NPC]],enderId=25381,prevId=11716,rewardNextId=11719,wowhead=[[https://www.wowhead.com/wotlk/quest=11717]],image=[[assets/images/quests/placeholder.png]],desc=[[It's obvious! The bloodspore moths are the entities responsible for pollination on these plains. It must be something that happens within the moth's internal system that acts as a catalyst for this pollen to work. It's all starting to make sense now, $N. That's why the kobolds don't kill the moths and instead go to great lengths to protect them! Those stupid little rats have it all figured out! Well we'll just have to get our own moth pollen! What do you say? Fetch me some in the name of science?]],logDesc=[[Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 5 Bloodspore Moth Pollen. ]]}
DB[11718]={id=11718,zoneId=3537,name=[[A Bot in Mammoth's Clothing]],level=71,minLevel=68,giver=[[Abner Fizzletorque]],giverType=[[NPC]],giverId=25780,ender=[[Abner Fizzletorque]],enderType=[[NPC]],enderId=25780,prevId=11715,rewardNextId=11723,wowhead=[[https://www.wowhead.com/wotlk/quest=11718]],image=[[assets/images/quests/placeholder.png]],desc=[[I've reconfigured the skeleton of an old bot to create an earthquake large enough to collapse the tunnels, but the machinery is delicate and sensitive to Northrend's biting cold. I've devised a means of insulating it using the thickest hides of the native mammoths. They roam the plains south of the airstrip and adjacent to the Geyser Fields. Bring back enough of the hides for me to finish the machine and then we'll be able to unleash it on the Nerubians!]],logDesc=[[Abner Fizzletorque at Fizzcrank Airstrip wants you to bring him 6 Thick Mammoth Hides.]]}
DB[11719]={id=11719,zoneId=3537,name=[[A Suitable Test Subject]],level=71,minLevel=68,giver=[[Bloodmage Laurith]],giverType=[[NPC]],giverId=25381,ender=[[Bloodmage Laurith]],enderType=[[NPC]],enderId=25381,prevId=11717,rewardNextId=11720,wowhead=[[https://www.wowhead.com/wotlk/quest=11719]],image=[[assets/images/quests/placeholder.png]],desc=[[<Laurith looks you over as if to size you up.> So we've got this pollinated bloodspore flower and nobody to test its effects on. Say, would you perhaps be interested in rubbing this on your skin and letting me observe? What's the worst that could happen anyway? Don't you worry, $N! Just take this sample and rub it all over your face.]],logDesc=[[Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra has asked that you use the Pollinated Bloodspore Flower and allow her to observe the results.]]}
DB[11720]={id=11720,zoneId=3537,name=[[The Invasion of Gammoth]],level=71,minLevel=68,giver=[[Bloodmage Laurith]],giverType=[[NPC]],giverId=25381,ender=[[Primal Mighthorn]],enderType=[[NPC]],enderId=25380,prevId=11719,rewardNextId=11721,wowhead=[[https://www.wowhead.com/wotlk/quest=11720]],image=[[assets/images/quests/placeholder.png]],desc=[[Hellscream assigned Mighthorn and I with the daunting task of magnataur extermination on the southern front of Warsong Hold. With us came an entire platoon of seasoned Horde soldiers. Our initial foray into the nearby magnataur dens proved quite unsuccessful as our entire squad was wiped out by the lair defenders. We're the only ones left... We aren't scientists or researchers. We're soldiers of the Horde, just like you. Soldiers on a mission that cannot fail... Speak to Primal Mighthorn now.]],logDesc=[[Speak to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra. ]]}
DB[11721]={id=11721,zoneId=3537,name=[[Gammothra the Tormentor]],level=71,minLevel=68,giver=[[Primal Mighthorn]],giverType=[[NPC]],giverId=25380,ender=[[Primal Mighthorn]],enderType=[[NPC]],enderId=25380,prevId=11720,rewardNextId=11722,wowhead=[[https://www.wowhead.com/wotlk/quest=11721]],image=[[assets/images/quests/placeholder.png]],desc=[[Magnataur live in prides, much like lions: one or two dominant males and several females along with their offspring. In the case of Gammoth, the magnataur den west of here, Gammothra is the leader. It is Gammothra that controls this magnataur population and therefore it is Gammothra that must be slain to prevent any type of magnataur uprising. Take this pouch of crushed bloodspore flower to Gammoth. Use the powder from the pouch to weaken Gammothra and then slay him! Return his head to me as proof.]],logDesc=[[Slay Gammothra and return the Head of Gammothra to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra.]]}
DB[11722]={id=11722,zoneId=3537,name=[[Trophies of Gammoth]],level=71,minLevel=68,giver=[[Primal Mighthorn]],giverType=[[NPC]],giverId=25380,ender=[[Garrosh Hellscream]],enderType=[[NPC]],enderId=25237,prevId=11721,wowhead=[[https://www.wowhead.com/wotlk/quest=11722]],image=[[assets/images/quests/placeholder.png]],desc=[[We cannot take all of the credit for this Horde victory, $N. It was you who risked your life to test the bloodspore and it was you who ultimately put an end to Gammothra. Honor us by returning to Warsong Hold and presenting the head of Gammothra to Lord Hellscream.]],logDesc=[[Take the Head of Gammothra to Garrosh Hellscream in Warsong Hold.]],choiceRewards={{id=37204,qty=1},{id=37405,qty=1},{id=37415,qty=1},{id=37480,qty=1}}}
DB[11723]={id=11723,zoneId=3537,name=[[Deploy the Shake-n-Quake!]],level=71,minLevel=68,giver=[[Abner Fizzletorque]],giverType=[[NPC]],giverId=25780,ender=[[Abner Fizzletorque]],enderType=[[NPC]],enderId=25780,prevId=11718,wowhead=[[https://www.wowhead.com/wotlk/quest=11723]],image=[[assets/images/quests/placeholder.png]],desc=[[Behold, the machine that will save us from the Nerubian threat! <Abner beams with pride as he presents the finished bot.> Take this remote control with you, and go out to the southernmost of the Nerubian sinkholes in the Geyser Fields. Use the remote to activate the Shake-n-Quake 5000. It will do the rest on its own. Don't be surprised if the quake it creates attracts the attention of a Nerubian leader. In fact, it would be a great opportunity to finish off the Nerubian offensive.]],logDesc=[[Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Shake-n-Quake 5000 to collapse the Nerubian tunnels and defeat Lord Kryxix.]],choiceRewards={{id=37228,qty=1},{id=37375,qty=1},{id=37437,qty=1},{id=37516,qty=1}}}
DB[11724]={id=11724,zoneId=3537,name=[[Massive Moth Omelet?]],level=71,minLevel=68,giverType=[[NPC]],ender=[[Bloodmage Laurith]],enderType=[[NPC]],enderId=25381,wowhead=[[https://www.wowhead.com/wotlk/quest=11724]],image=[[assets/images/quests/placeholder.png]],desc=[[This egg was obviously important to somebody, as the corpse nearby can attest. As you look the egg over you notice that it has already been tagged for shipment to the Bloodspore Plains, care of Bloodmage Laurith. That's just east of here! Collect the egg and take it to the expectant Bloodmage.]],logDesc=[[Take the Massive Glowing Egg to Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra.]]}
DB[11725]={id=11725,zoneId=3537,name=[[Finding Pilot Tailspin]],level=71,minLevel=68,giver=[[Fizzcrank Fullthrottle]],giverType=[[NPC]],giverId=25590,ender=[[Iggy "Tailspin" Cogtoggle]],enderType=[[NPC]],enderId=25807,prevId=11712,wowhead=[[https://www.wowhead.com/wotlk/quest=11725]],image=[[assets/images/quests/placeholder.png]],desc=[[I should've flown the mission myself. It's not that I don't trust Tailspin. Far from it. Heck, he was the best wingman I ever flew with. No, it's just that it's my responsibility to lead a mission of such import. I sent Tailspin out with our fastest recon squadron to gather information about the Nerubian infestation in the middle of the Geyser Fields. The last report we received placed his squadron in the pools to the far south and just west of the Nerubian sinkholes. Find Tailspin, $N.]],logDesc=[[Locate Iggy "Tailspin" Cogtoggle in the Geyser Fields.]]}
DB[11726]={id=11726,zoneId=3537,name=[[A Little Bit of Spice]],level=71,minLevel=68,giver=[[Iggy "Tailspin" Cogtoggle]],giverType=[[NPC]],giverId=25807,ender=[[Iggy "Tailspin" Cogtoggle]],enderType=[[NPC]],enderId=25807,prevId=11725,rewardNextId=11728,wowhead=[[https://www.wowhead.com/wotlk/quest=11726]],image=[[assets/images/quests/placeholder.png]],desc=[[The wolves have been pawing through the wreckage ever since the crash and I'm afraid they consumed the microfilm from our mission in the process. I have a plan to recover that microfilm, but I need your help to make it work. To the south and east, in the Flood Plains, live creatures called gorlocs. They prepare their foods with noxious spices, which would sicken any other creature. If you can gather enough of the spice pouches from gorloc steam belchers or gorloc waddlers, I can make the wolf bait.]],logDesc=[[Iggy "Tailspin" Cogtoggle in the Scalding Pools wants you to gather 4 Gorloc Spice Pouches.]]}
DB[11727]={id=11727,zoneId=3537,name=[[A Time for Heroes]],level=71,minLevel=68,giver=[[General Arlos]],giverType=[[NPC]],giverId=25250,ender=[[Sergeant Hammerhill]],enderType=[[NPC]],enderId=25816,prevId=11672,rewardNextId=11797,wowhead=[[https://www.wowhead.com/wotlk/quest=11727]],image=[[assets/images/quests/placeholder.png]],desc=[[It's good to have you among us, $N.  We've all heard of your past deeds. As you know, King Wrynn is moving great armies into Northrend to meet those of Arthas.  But armies are nothing without true heroes to inspire and lead them. I want you to be that hero for my men.  Fight alongside them against the Scourge that lays siege to our stronghold. Report to Sergeant Hammerhill outside the inner hold.  Valiance Keep cannot fall.  The future of our campaign depends on it.]],logDesc=[[Report to Sergeant Hammerhill at Valiance Keep.]]}
DB[11728]={id=11728,zoneId=3537,name=[[Lupus Pupus]],level=71,minLevel=68,giver=[[Iggy "Tailspin" Cogtoggle]],giverType=[[NPC]],giverId=25807,ender=[[Iggy "Tailspin" Cogtoggle]],enderType=[[NPC]],enderId=25807,prevId=11726,rewardNextId=11795,wowhead=[[https://www.wowhead.com/wotlk/quest=11728]],image=[[assets/images/quests/placeholder.png]],desc=[[Whatever you do, don't eat this bait yourself. Just set it down in the vicinity of an oil-soaked wolf. If they're desperate enough to eat the microfilm, they'll come running when they smell the bait. Simply wait for nature to take its course and then all you need to do is search the, uh... byproduct for the film. I'd offer you my special lupus pupus scupus for the job, but I left it back at the airstrip. I'm afraid you'll have to conduct the... err... search the old-fashioned way.]],logDesc=[[Iggy "Tailspin" Cogtoggle in the Scalding Pools wants you to bring him 8 pieces of Microfilm.]]}
DB[11729]={id=11729,zoneId=3537,name=[[The Ultrasonic Screwdriver]],level=71,minLevel=68,giverType=[[NPC]],ender=[[Crafty Wobblesprocket]],enderType=[[NPC]],enderId=25477,rewardNextId=11730,wowhead=[[https://www.wowhead.com/wotlk/quest=11729]],image=[[assets/images/quests/placeholder.png]],desc=[[The unit you just dismantled had this inside of its mechanical innards. It looks pretty complicated... certainly someone back at the airstrip would want to take a look at it. Maybe Crafty Wobblesprocket?]],logDesc=[[Deliver the Ultrasonic Screwdriver to Crafty Wobblesprocket at Fizzcrank Airstrip.]]}
DB[11730]={id=11730,zoneId=3537,name=[[Master and Servant]],level=71,minLevel=68,giver=[[Crafty Wobblesprocket]],giverType=[[NPC]],giverId=25477,ender=[[Crafty Wobblesprocket]],enderType=[[NPC]],enderId=25477,prevId=11729,wowhead=[[https://www.wowhead.com/wotlk/quest=11730]],image=[[assets/images/quests/placeholder.png]],desc=[[The Ultrasonic Screwdriver is the ultimate tool. It can do anything to mechanical stuff! Head back into the pools and dismantle a number of Mechazod's robots. Then all you have to do is use the screwdriver on their remains, and I'm betting that they'll turn to our side, for a short time anyway. I'm pretty sure it won't work on the mechagnomes, so don't even bother with them. Oh, and if you want to take anything from the robot's insides, you'll want to do so before using the screwdriver!]],logDesc=[[Use the Ultrasonic Screwdriver to reprogram 15 robots and then return to Crafty Wobblesprocket at Fizzcrank Airstrip. Make sure to loot the dead robot before you reprogram it.]],choiceRewards={{id=37270,qty=1},{id=37353,qty=1},{id=37441,qty=1},{id=37479,qty=1}}}
DB[11733]={id=11733,zoneId=3537,name=[[Traversing the Rift]],level=71,minLevel=69,giver=[[Surristrasz]],giverType=[[NPC]],giverId=24795,ender=[[Archmage Berinand]],enderType=[[NPC]],enderId=25314,prevId=11682,wowhead=[[https://www.wowhead.com/wotlk/quest=11733]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been mindful of your efforts, mortal. Do not feign surprise. Surely you've felt my eye upon you. The time has come to peel back a layer of darkness from your mind. There are stark truths that you have grown ready to accept. Before hearing the tale, you shall be shown firsthand what we face. Put your affairs in order, $c....]],logDesc=[[Surristrasz wants you to travel to Coldarra. Once there, you are to speak with Archmage Berinand.]]}
DB[11788]={id=11788,zoneId=3537,name=[[Lefty Loosey, Righty Tighty]],level=71,minLevel=68,giver=[[Jinky Wingnut]],giverType=[[NPC]],giverId=25747,ender=[[Jinky Wingnut]],enderType=[[NPC]],enderId=25747,prevId=11712,rewardNextId=11798,wowhead=[[https://www.wowhead.com/wotlk/quest=11788]],image=[[assets/images/quests/placeholder.png]],desc=[[Okay, I think we're ready for the penultimate assault... before you can bring down Mechazod, you're going to have to dismantle his lieutenants first! You'll find Twonky, ED-210, Max Blasto, and The Grinder at the West Point, North Point, Mid Point and South Point stations, respectively. To get them to show up, just turn the valves at the stations to mess up whatever they're trying to do out there. You can't miss the places, they all have spinning lights.]],logDesc=[[Dismantle Twonky, ED-210, Max Blasto, and The Grinder, and then report back to Jinky Wingnut at Fizzcrank Airstrip.]]}
DB[11789]={id=11789,zoneId=3537,name=[[A Soldier in Need]],level=71,minLevel=68,giver=[[Medic Hawthorn]],giverType=[[NPC]],giverId=25825,ender=[[Medic Hawthorn]],enderType=[[NPC]],enderId=25825,wowhead=[[https://www.wowhead.com/wotlk/quest=11789]],image=[[assets/images/quests/placeholder.png]],desc=[[You there!  Please, I need your help.  This soldier will succumb to the cryptfiends' venom unless we act immediately. I've managed to slow down the poison, but without a suitable supply of antidote I cannot counteract it. I was promised a new shipment of anti-venom in the Stormbreaker's most recent trip from the south.  Go inside its hold and search for a chest of first aid supplies. Hurry, $c!  We can't afford to lose any more men unnecessarily.]],logDesc=[[Medic Hawthorn, outside of Valiance Keep, wants you to go inside the Stormbreaker's hold and retrieve Hawthorn's Anti-Venom from a crate of First Aid Supplies.]],rewards={{id=22850,qty=2}}}
DB[11790]={id=11790,zoneId=3537,name=[[Cultists Among Us]],level=71,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11790]],image=[[assets/images/quests/placeholder.png]],desc=[[This altar bears all the markings of the Cult of the Damned.  It appears fanatics from the mainland have made it into Northrend.  It might be prudent to notify the captain of the ship. Perhaps he is to be found above deck.]],logDesc=[[Speak to Captain "Lefty" Lugsail above the Stormbreaker in Valiance Keep.]]}
DB[11791]={id=11791,zoneId=3537,name=[[Notify Arlos]],level=71,minLevel=68,giver=[[Admiral Cantlebree]],giverType=[[NPC]],giverId=25299,ender=[[General Arlos]],enderType=[[NPC]],enderId=25250,prevId=11920,wowhead=[[https://www.wowhead.com/wotlk/quest=11791]],image=[[assets/images/quests/placeholder.png]],desc=[[We must notify General Arlos at once.  I've known the captain for a long time and, believe me, he is one of the more careful ones. Who knows how many cultists have been smuggled into our settlements in Northrend in other ships?  This could be disastrous.]],logDesc=[[Speak to General Arlos inside the Inner Hold at Valiance Keep.]]}
DB[11792]={id=11792,zoneId=3537,name=[[Enemies of the Light]],level=71,minLevel=68,giver=[[Harbinger Vurenn]],giverType=[[NPC]],giverId=25285,ender=[[Harbinger Vurenn]],enderType=[[NPC]],enderId=25285,prevId=11791,rewardNextId=11793,wowhead=[[https://www.wowhead.com/wotlk/quest=11792]],image=[[assets/images/quests/placeholder.png]],desc=[[Not so fast there.  I don't know about you, $c, but I was hardly convinced by the general's words.  They rung unsure... as if they were not his own. Something's amiss here.  All of our efforts to collaborate have been blocked and delayed.  It is time we took a more independent approach. If we're to learn more about the cultists inside the keep... perhaps we should investigate those outside. Intelligence reports a small group of them aiding the Scourge north of here.  See if they carry any clues.]],logDesc=[[Harbinger Vurenn wants you to fight the Cultist Necrolytes near Farshire to the north of Valiance Keep and retrieve the Cultist Communique from them.]],choiceRewards={{id=36888,qty=1},{id=36937,qty=1},{id=36938,qty=1},{id=38213,qty=1}}}
DB[11793]={id=11793,zoneId=3537,name=[[Further Investigation]],level=71,minLevel=68,giver=[[Harbinger Vurenn]],giverType=[[NPC]],giverId=25285,ender=[[Vindicator Yaala]],enderType=[[NPC]],enderId=25826,prevId=11792,rewardNextId=11794,wowhead=[[https://www.wowhead.com/wotlk/quest=11793]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm afraid this is a matter I must delegate to one of my operatives... someone who can work in secret.  Keep the evidence with you and take it to Vindicator Yaala inside the inn. Tell her I sent you and speak of this matter to no one else.  We do not know who might be working for the cult.]],logDesc=[[Bring the Cultist Communique to Vindicator Yaala inside the inn in Valiance Keep.]]}
DB[11794]={id=11794,zoneId=3537,name=[[The Hunt is On]],level=71,minLevel=68,giver=[[Vindicator Yaala]],giverType=[[NPC]],giverId=25826,ender=[[Vindicator Yaala]],enderType=[[NPC]],enderId=25826,prevId=11793,wowhead=[[https://www.wowhead.com/wotlk/quest=11794]],image=[[assets/images/quests/placeholder.png]],desc=[[I've made it my business to learn as much as possible about the vile death cult, including their secret language. Vurenn was right.  The cultists mention disguised operatives in various locations in Valiance Keep: the lower docks, the jail inside the inner hold and in the inn's kitchen. Take this oculus.  Use it at those three locations - anyone that has recently used the cult's necromancy will be enshrouded by a dark aura.  Take care of the cultists before something nefarious happens.]],logDesc=[[Vindicator Yaala wants you to use the Oculus of the Exorcist in three different locations in Valiance Keep to uncover and defeat Cult of the Damned members.]],choiceRewards={{id=37204,qty=1},{id=37405,qty=1},{id=37415,qty=1},{id=37480,qty=1}}}
DB[11795]={id=11795,zoneId=3537,name=[[Emergency Protocol: Section 8.2, Paragraph C]],level=71,minLevel=68,giver=[[Iggy "Tailspin" Cogtoggle]],giverType=[[NPC]],giverId=25807,ender=[[Iggy "Tailspin" Cogtoggle]],enderType=[[NPC]],enderId=25807,prevId=11728,rewardNextId=11796,wowhead=[[https://www.wowhead.com/wotlk/quest=11795]],image=[[assets/images/quests/placeholder.png]],desc=[[Injured or not, as squadron commander, I'm responsible for locating and returning the insignia of all fallen pilots under my command. In all the years I've flown with Fizzcrank, we've never failed to return the signet of a pilot. My injuries make it dangerous for me to stray far from the safety of the wreckage, but perhaps you would be willing to help me recover the insignia? In the meantime, I'll make preparations to carry out my final duty as squadron commander.]],logDesc=[[Recover 6 Fizzcrank Pilot Insignia from the bodies of Fizzcrank Recon Pilots and return them to Iggy "Tailspin" Cogtoggle in the Scalding Pools.]]}
DB[11796]={id=11796,zoneId=3537,name=[[Emergency Protocol: Section 8.2, Paragraph D]],level=71,minLevel=68,giver=[[Iggy "Tailspin" Cogtoggle]],giverType=[[NPC]],giverId=25807,ender=[[Iggy "Tailspin" Cogtoggle]],enderType=[[NPC]],enderId=25807,prevId=11795,rewardNextId=11873,wowhead=[[https://www.wowhead.com/wotlk/quest=11796]],image=[[assets/images/quests/placeholder.png]],desc=[[There's only one more thing left to do before I can finally return to the airstrip and make my report. Section 8.2, paragraph D of the emergency protocol requires me to scuttle as much of the wreckage as possible, in order to prevent our technology from falling into enemy hands. I'll give you my torch if you agree to help me complete this last duty. I don't want to think about what the Horde's goblin allies will do if these machines fall into their hands.]],logDesc=[[Iggy "Tailspin" Cogtoggle wants you to scuttle the Eastern Wreck, a Southern Wreck, and a Northwestern Wreck.]]}
DB[11797]={id=11797,zoneId=3537,name=[[The Siege]],level=71,minLevel=68,giver=[[Sergeant Hammerhill]],giverType=[[NPC]],giverId=25816,ender=[[Sergeant Hammerhill]],enderType=[[NPC]],enderId=25816,prevId=11727,rewardNextId=11889,wowhead=[[https://www.wowhead.com/wotlk/quest=11797]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, well, well.  It's good to see Arlos bring out the big guns. Don't get me wrong - our lads are doing the best they can, but someone of your renown fighting alongside them could really turn the tides for us.  I'm not sure how much longer we can hold out against these undead Nerubians. What do you say you get out there and kill me some creepers?  Show these boys how it's done.]],logDesc=[[Sergeant Hammerhill wants you to kill 6 Crypt Crawlers in the Sands of Nasam outside of Valiance Keep.]],choiceRewards={{id=36883,qty=1},{id=38208,qty=1},{id=36878,qty=1},{id=36881,qty=1},{id=36879,qty=1},{id=36880,qty=1}}}
DB[11798]={id=11798,zoneId=3537,name=[[The Gearmaster]],level=72,minLevel=68,giver=[[Jinky Wingnut]],giverType=[[NPC]],giverId=25747,ender=[[Fizzcrank Fullthrottle]],enderType=[[NPC]],enderId=25590,prevId=11788,wowhead=[[https://www.wowhead.com/wotlk/quest=11798]],image=[[assets/images/quests/placeholder.png]],desc=[[Gearmaster Mechazod is insane! He says that he offers us immortality by removing this so-called 'Curse of the Flesh', but what he's really making are robotic slaves! $N, we're pretty certain that he's still at the pumping station out in the middle of the pools to the east. The last we saw of him, he was in the command hut up top. Go up there and research his stuff. You must confront Mechazod if gnomes everywhere,... no, everyone everywhere, are to stay alive!]],logDesc=[[Research the Gearmaster's Manual and return Mechazod's Head to Fizzcrank Fullthrottle.]],choiceRewards={{id=37274,qty=1},{id=37352,qty=1},{id=37442,qty=1},{id=37530,qty=1}}}
DB[11864]={id=11864,zoneId=3537,name=[[A Mission Statement]],level=72,minLevel=70,giver=[[Arch Druid Lathorius]],giverType=[[NPC]],giverId=25809,ender=[[Arch Druid Lathorius]],enderType=[[NPC]],enderId=25809,wowhead=[[https://www.wowhead.com/wotlk/quest=11864]],image=[[assets/images/quests/placeholder.png]]}
DB[11865]={id=11865,zoneId=3537,name=[[Unfit for Death]],level=72,minLevel=70,giver=[[Zaza]],giverType=[[NPC]],giverId=25811,ender=[[Zaza]],enderType=[[NPC]],enderId=25811,prevId=11864,rewardNextId=11868,wowhead=[[https://www.wowhead.com/wotlk/quest=11865]],image=[[assets/images/quests/placeholder.png]],desc=[[Just south of us the caribou used to roam freely, peacefully. Then Nesingwary showed up and everything changed. Now the caribou are in a perpetual state of frenzy, always in a panic. They are stalked by the hunters and trappers hidden in the field. Nesingwary's executioners are unfit for death. They must feel the torture that they put the caribou through! Take this pile of fake furs and lay it upon their caribou traps to the south. Watch as the hunters are caught in their own deadly traps!]],logDesc=[[Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the Pile of Fake Furs to trap 8 Nesingwary Trappers. ]]}
DB[11866]={id=11866,zoneId=3537,name=[[Ears of Our Enemies]],level=72,minLevel=70,giver=[[Arch Druid Lathorius]],giverType=[[NPC]],giverId=25809,ender=[[Arch Druid Lathorius]],enderType=[[NPC]],enderId=25809,prevId=11864,nextId=11892,exGroup=-11884,wowhead=[[https://www.wowhead.com/wotlk/quest=11866]],image=[[assets/images/quests/placeholder.png]],desc=[[Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A. Should you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A. ]],logDesc=[[Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.]]}
DB[11867]={id=11867,zoneId=3537,name=[[Can't Get Ear-nough...]],level=72,minLevel=70,giver=[[Arch Druid Lathorius]],giverType=[[NPC]],giverId=25809,ender=[[Arch Druid Lathorius]],enderType=[[NPC]],enderId=25809,prevId=11866,wowhead=[[https://www.wowhead.com/wotlk/quest=11867]],image=[[assets/images/quests/placeholder.png]],desc=[[Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nessingwary and does dare strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A. Should you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A. ]],logDesc=[[Arch Druid Lathorius at the D.E.H.T.A. Outpost in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.]]}
DB[11868]={id=11868,zoneId=3537,name=[[The Culler Cometh]],level=72,minLevel=70,giver=[[Zaza]],giverType=[[NPC]],giverId=25811,ender=[[Zaza]],enderType=[[NPC]],enderId=25811,prevId=11865,nextId=11892,exGroup=-11884,wowhead=[[https://www.wowhead.com/wotlk/quest=11868]],image=[[assets/images/quests/placeholder.png]],desc=[[Near the southern end of this bluff is where you will find the treacherous leader of the caribou trappers. She is a savage like no other, making a mockery out of the carcasses of the slain animals: drinking from their blood and howling to the moons! Find this murderer, Karen, and end her worthless existence. Prepare yourself properly, $N. Karen the Culler has indulged in the riches that Nesingwary has lavished upon her! She will be well armed and guarded by lackeys.]],logDesc=[[Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Karen the Culler.]],choiceRewards={{id=36939,qty=1},{id=37002,qty=1},{id=36998,qty=1},{id=37004,qty=1}}}
DB[11869]={id=11869,zoneId=3537,name=[[Happy as a Clam]],level=72,minLevel=70,giver=[[Hierophant Cenius]],giverType=[[NPC]],giverId=25810,ender=[[Hierophant Cenius]],enderType=[[NPC]],enderId=25810,prevId=11864,rewardNextId=11870,wowhead=[[https://www.wowhead.com/wotlk/quest=11869]],image=[[assets/images/quests/placeholder.png]],desc=[[To the west of us you will find Lake Kum'uya. It is, as far as we know, the only freshwater giant clam habitat in the world. Of course Nesingwary's lackeys are now using the lake as a giant pearl farm. They must be stopped! A lesson must be taught to those that would think to endanger an entire species. Go to Lake Kum'uya and locate the loot crazed divers. Slay them until the water runs red! Return to me when a proper example has been made!]],logDesc=[[Hierophant Cenius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill 10 Loot Crazed Divers.]]}
DB[11870]={id=11870,zoneId=3537,name=[[The Abandoned Reach]],level=72,minLevel=70,giver=[[Hierophant Cenius]],giverType=[[NPC]],giverId=25810,ender=[[Hierophant Liandra]],enderType=[[NPC]],enderId=25838,prevId=11869,rewardNextId=11871,wowhead=[[https://www.wowhead.com/wotlk/quest=11870]],image=[[assets/images/quests/placeholder.png]],desc=[[We have just gotten word from Liandra that mercenaries hired by Nesingwary are moving goods off the beach and onto the main Nesingwary shipping vessel. No doubt they plan on making a fortune from their murderous trade! She has asked that we send assistance to the Abandoned Reach, directly south of here on the beachfront of the Borean Tundra. Make haste, Liandra awaits you there! ]],logDesc=[[Seek out Hierophant Liandra at the Abandoned Reach.]]}
DB[11871]={id=11871,zoneId=3537,name=[[Not On Our Watch]],level=72,minLevel=70,giver=[[Hierophant Liandra]],giverType=[[NPC]],giverId=25838,ender=[[Hierophant Liandra]],enderType=[[NPC]],enderId=25838,prevId=11870,rewardNextId=11872,wowhead=[[https://www.wowhead.com/wotlk/quest=11871]],image=[[assets/images/quests/placeholder.png]],desc=[[Strewn across this beach, amidst the flotsam and jetsam, are crates and sacks of animal parts. It would seem that Nesingwary is in cahoots with the Northsea Freebooters. Those dirty pirates are transporting the goods that Nesingwary's murderous lackeys gather offshore. No doubt they will end up in the homes and on the backs of wealthy, unscrupulous individuals across Azeroth. This won't happen. Not on our watch. Bring me all shipments that you find upon this beach. They'll never have them!]],logDesc=[[Hierophant Liandra at the Abandoned Reach in the Borean Tundra wants you to recover 12 Shipments of Animal Parts.]]}
DB[11872]={id=11872,zoneId=3537,name=[[The Nefarious Clam Master...]],level=72,minLevel=70,giver=[[Hierophant Liandra]],giverType=[[NPC]],giverId=25838,ender=[[Hierophant Cenius]],enderType=[[NPC]],enderId=25810,prevId=11871,nextId=11892,exGroup=-11884,wowhead=[[https://www.wowhead.com/wotlk/quest=11872]],image=[[assets/images/quests/placeholder.png]],desc=[[It's despicable, really, to anoint one's self as the "Clam Master," as if they hold mastery over the creatures of the sea. None may make such claims! This "Clam Master" must be found and slain. He was last seen at the wreckage just off the coast of the Abandoned Reach. Find him and kill him. Once this is done, return to Hierophant Cenius at the D.E.H.T.A. Encampment, north of here, and let her know that the mission was a success.]],logDesc=[[Slay Clam Master K and return to Hierophant Cenius at the D.E.H.T.A. Encampment. ]],choiceRewards={{id=37017,qty=1},{id=37014,qty=1},{id=37018,qty=1},{id=37019,qty=1},{id=37016,qty=1},{id=37015,qty=1}}}
DB[11873]={id=11873,zoneId=3537,name=[[Give Fizzcrank the News]],level=71,minLevel=68,giver=[[Iggy "Tailspin" Cogtoggle]],giverType=[[NPC]],giverId=25807,ender=[[Fizzcrank Fullthrottle]],enderType=[[NPC]],enderId=25590,prevId=11796,wowhead=[[https://www.wowhead.com/wotlk/quest=11873]],image=[[assets/images/quests/placeholder.png]],desc=[[Would you be willing to head back to the airstrip and let Fizzcrank know that I'll be along shortly to give my formal report? I've got to deal with the wreckage of my flying machine, and then I'll be on my way. I'll be certain that Fizzcrank knows that he has you to thank for my survival and the recovery effort. I only wonder what the old man would've done himself if he'd been flying with us. I miss those days.]],logDesc=[[Make your way back to Fizzcrank Airstrip and speak with Fizzcrank Fullthrottle.]],choiceRewards={{id=37275,qty=1},{id=37351,qty=1},{id=37443,qty=1},{id=37478,qty=1}}}
DB[11876]={id=11876,zoneId=3537,name=[[Help Those That Cannot Help Themselves]],level=72,minLevel=70,giver=[[Arch Druid Lathorius]],giverType=[[NPC]],giverId=25809,ender=[[Arch Druid Lathorius]],enderType=[[NPC]],enderId=25809,prevId=11864,rewardNextId=11878,wowhead=[[https://www.wowhead.com/wotlk/quest=11876]],image=[[assets/images/quests/placeholder.png]],desc=[[They're majestic beasts, aren't they? <Lathorius points towards the mammoths of the northern tundra.> With each passing day their numbers diminish. Demons that call themselves hunters slay the beasts for sport and riches. <Lathorius' face contorts with anger.> It's the whimpers that drive me to madness, $N. You can hear them, carried by the wind. The mammoth calves, trapped in the hunters' vile traps, call out to us. Take this hammer and smash those traps. Free the calves!]],logDesc=[[Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the D.E.H.T.A. Trap Smasher to free 8 Mammoth Calves.]]}
DB[11878]={id=11878,zoneId=3537,name=[[Khu'nok Will Know]],level=72,minLevel=70,giver=[[Arch Druid Lathorius]],giverType=[[NPC]],giverId=25809,ender=[[Khu'nok the Behemoth]],enderType=[[NPC]],enderId=25862,prevId=11876,rewardNextId=11879,wowhead=[[https://www.wowhead.com/wotlk/quest=11878]],image=[[assets/images/quests/placeholder.png]],desc=[[Although you have acted valiantly in freeing the trapped calves, many of them will still die. You see, without a caretaker, these calves must fend for themselves in the wild. But there is a way! Hope yet remains! North of here in the mammoth fields, bordering the Scalding Pools, you will find Khu'nok the Behemoth: a mammoth as wise as he is ancient. Take this mammoth orphan and present it to Khu'nok. He will know what to do.]],logDesc=[[Take the Orphaned Mammoth Calf to Khu'nok the Behemoth in the Borean Tundra.]]}
DB[11879]={id=11879,zoneId=3537,name=[[Kaw the Mammoth Destroyer]],level=72,minLevel=70,giver=[[Khu'nok the Behemoth]],giverType=[[NPC]],giverId=25862,ender=[[Arch Druid Lathorius]],enderType=[[NPC]],enderId=25809,prevId=11878,nextId=11892,exGroup=-11884,wowhead=[[https://www.wowhead.com/wotlk/quest=11879]],image=[[assets/images/quests/placeholder.png]],desc=[[You cannot defeat the being responsible for the slaughter of my kind by yourself. The mammoths of the tundra will help you! Venture forth to the plains and find a mammoth bull. He will allow you to mount him and control his movements and actions. Ride upon his back and find Kaw, north of here at Kaw's Roost. Together, you will be the instrument of Kaw's demise. Destroy Kaw's armies and take from Kaw his coveted war halberd. Return to Lathorius at the D.E.H.T.A. Encampment should you succeed.]],logDesc=[[Kill Kaw the Mammoth Destroyer and recover Kaw's War Halberd. Deliver Kaw's War Halberd to Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra.]],choiceRewards={{id=37005,qty=1},{id=37007,qty=1},{id=37008,qty=1},{id=37009,qty=1}}}
DB[11881]={id=11881,zoneId=3537,name=[[Load'er Up!]],level=71,minLevel=68,giver=[[Fezzix Geartwist]],giverType=[[NPC]],giverId=25849,ender=[[Fezzix Geartwist]],enderType=[[NPC]],enderId=25849,wowhead=[[https://www.wowhead.com/wotlk/quest=11881]],image=[[assets/images/quests/placeholder.png]],desc=[[Have you seen the flying machines buzzing around? That's gnomish innovation at its finest. I've long waited to get my hands on some of their technology and a perfect opportunity has presented itself. One of their recon wings crashed in the Scalding Pools, in the southwest part of the Geyser Fields. Blow this whistle near one of the crashed machines and my trusty mule, Jenny will answer. She'll follow you and carry the salvage, but you must keep her safe. She'll begin to drop the cargo if attacked.]],logDesc=[[Help Jenny make her way from the crash site to Fezzix Geartwist at Taunka'le Village without losing all her cargo.]]}
DB[11884]={id=11884,zoneId=3537,name=[[Ned, Lord of Rhinos...]],level=72,minLevel=70,giver=[[Killinger the Den Watcher]],giverType=[[NPC]],giverId=25812,ender=[[Killinger the Den Watcher]],enderType=[[NPC]],enderId=25812,prevId=11864,nextId=11892,exGroup=-11884,wowhead=[[https://www.wowhead.com/wotlk/quest=11884]],image=[[assets/images/quests/placeholder.png]],desc=[[West of here, on the high bluffs above Lake Kum'uya, roams a despicable being known as Nedar. The self proclaimed "Lord of Rhinos" hunts the wastes for the injured or young - rhinos unable to defend themselves against Ned's cowardly attacks. To add insult to injury, Ned has raised a rhino of his own to become his mount and bodyguard. It is a rare thing that D.E.H.T.A. would ever call for the death of an animal, but Ned's tainted rhino must be disposed of... Kill them both and return to me.]],logDesc=[[Killinger the Den Watcher at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Nedar, Lord of Rhinos and his companion, "Lunchbox."]],choiceRewards={{id=37203,qty=1},{id=37406,qty=1},{id=37414,qty=1},{id=37520,qty=1}}}
DB[11887]={id=11887,zoneId=3537,name=[[Emergency Supplies]],level=71,minLevel=68,giver=[[Crashed Recon Pilot]],giverType=[[NPC]],giverId=25984,ender=[[Fezzix Geartwist]],enderType=[[NPC]],enderId=25849,wowhead=[[https://www.wowhead.com/wotlk/quest=11887]],image=[[assets/images/quests/placeholder.png]],desc=[[Rifling through the dead gnome's possessions, you come across a small packet filled with rations, tools, and a handy roll of gnomish duct tape. The contents of these kits might prove helpful to Fezzix Geartwist when it comes time for him to reassemble the wreckage of the gnomish flying machines. Bringing a few of these kits to Fezzix might just be worth a nice bonus.]],logDesc=[[Collect 7 Gnomish Emergency Toolkits from the bodies of crashed Fizzcrank Recon Pilots and bring them to Fezzix Geartwist at Taunka'le Village.]]}
DB[11888]={id=11888,zoneId=3537,name=[[Ride to Taunka'le Village]],level=71,minLevel=68,giver=[[Ambassador Talonga]],giverType=[[NPC]],giverId=25978,ender=[[Sage Earth and Sky]],enderType=[[NPC]],enderId=25982,prevId=11598,rewardNextId=11890,wowhead=[[https://www.wowhead.com/wotlk/quest=11888]],image=[[assets/images/quests/placeholder.png]],desc=[[$R, the chieftain is making me wait... time that Taunka'le does not have! There has been talk of your prowess. Rather than wait for Garrosh to send help, I ask you to go and help my people. Taunka'le village lies far to the northeast. Follow the road east out of the hold, turning north at the intersection. Not long after, you will come to another intersection. Follow the path east, passing south and then east of the great pools along the flood plains. Speak with Sage Earth and Sky when you arrive.]],logDesc=[[Speak with Sage Earth and Sky at Taunka'le Village.]]}
DB[11889]={id=11889,zoneId=3537,name=[[Death From Above]],level=71,minLevel=68,giver=[[Sergeant Hammerhill]],giverType=[[NPC]],giverId=25816,ender=[[Sergeant Hammerhill]],enderType=[[NPC]],enderId=25816,prevId=11797,rewardNextId=11897,wowhead=[[https://www.wowhead.com/wotlk/quest=11889]],image=[[assets/images/quests/placeholder.png]],desc=[[We're doing a good job of holding the front lines against these bugs.  Some of these cheeky fiends, however, can fly over the aforementioned front lines and are really beating down on our inner defenses. I've requisitioned reinforced fishing nets from our civilian ships.  If you've got a good enough throwing arm, they'll help you knock the enemy out of the sky.  Thin their numbers so that our defenses can hold the keep.]],logDesc=[[Sergeant Hammerhill wants you to use the Reinforced Net to help you slay 6 Scourged Flamespitters outside of Valiance Keep.]]}
DB[11890]={id=11890,zoneId=3537,name=[[What Are They Up To?]],level=71,minLevel=68,giver=[[Sage Earth and Sky]],giverType=[[NPC]],giverId=25982,ender=[[Sage Earth and Sky]],enderType=[[NPC]],enderId=25982,prevId=11888,rewardNextId=11895,wowhead=[[https://www.wowhead.com/wotlk/quest=11890]],image=[[assets/images/quests/placeholder.png]],desc=[[The gnomes have run into some trouble in the pools to the west. It serves them right as they have been fouling up the land with their so-called inventions. I want you to go out to their pumping station and observe what has befallen them. Return to me after.]],logDesc=[[Investigate the area surrounding the Fizzcrank Pumping Station. Then, return to Sage Earth and Sky at Taunka'le Village.]]}
DB[11892]={id=11892,zoneId=3537,name=[[The Assassination of Harold Lane]],level=72,minLevel=70,giver=[[Arch Druid Lathorius]],giverType=[[NPC]],giverId=25809,ender=[[Arch Druid Lathorius]],enderType=[[NPC]],enderId=25809,wowhead=[[https://www.wowhead.com/wotlk/quest=11892]],image=[[assets/images/quests/placeholder.png]],desc=[[You have done much for the animals of the Borean Tundra, $N. Nesingwary's lackeys have been beaten back and taught a lesson that they will not soon forget. Harold Lane, the primary agent responsible for the mass slaughters in Nagrand, has been identified as the man in charge of Nesingwary operations in the tundra. He is stationed at Lake Kum'uya, west of here. <Lathorius hands you an intricately carved oak horn.> Find Lane and kill him. Use this horn should you require our aid. ]],logDesc=[[Arch Druid Lathorius at the D.E.H.T.A. Outpost in the Borean Tundra wants you to kill Harold Lane.]],choiceRewards={{id=38252,qty=1},{id=38251,qty=1},{id=38250,qty=1}}}
DB[11893]={id=11893,zoneId=3537,name=[[The Power of the Elements]],level=71,minLevel=68,giver=[[Dorain Frosthoof]],giverType=[[NPC]],giverId=25983,ender=[[Dorain Frosthoof]],enderType=[[NPC]],enderId=25983,prevId=11881,wowhead=[[https://www.wowhead.com/wotlk/quest=11893]],image=[[assets/images/quests/placeholder.png]],desc=[[I kept trying to tell that silly goblin his machines are unreliable. But the power of the elements; that is deep and abiding. When my apprenticeship is over, I will wield their full power. What I know now should be sufficient to help out our friend Fezzix, though. Take this windsoul totem and plant it near any of the steam ragers to the west of the village. The totem will gather up the energies of slain elementals. Return the fully charged totem to me and I'll do the rest.]],logDesc=[[Dorain Frosthoof at Taunka'le Village wants you to use the Windsoul Totem to gather the energy of 10 Steam Ragers.]]}
DB[11894]={id=11894,zoneId=3537,name=[[Patching Up]],level=71,minLevel=68,giver=[[Fezzix Geartwist]],giverType=[[NPC]],giverId=25849,ender=[[Fezzix Geartwist]],enderType=[[NPC]],enderId=25849,prevId=11893,wowhead=[[https://www.wowhead.com/wotlk/quest=11894]],image=[[assets/images/quests/placeholder.png]],desc=[[Remember all that gnomish duct tape you brought me? Well, I've found a use for it. The body of this flying machine is so banged up in places, that I'm going to need to reinforce it if I ever hope to fly. Dorain over there has been telling me that the taunka use steam cured caribou leather for making watertight containers. Marsh caribou live all around the village and in the Flood Plains to the south. Get the best hides you can find and cure them over the steam vents in the Geyser Fields.]],logDesc=[[Fezzix Geartwist at Taunka'le Village wants you to bring him 5 Steam Cured Hides.]],choiceRewards={{id=37272,qty=1},{id=37388,qty=1},{id=37428,qty=1},{id=37526,qty=1}}}
DB[11895]={id=11895,zoneId=3537,name=[[Master the Storm]],level=71,minLevel=68,giver=[[Sage Earth and Sky]],giverType=[[NPC]],giverId=25982,ender=[[Sage Earth and Sky]],enderType=[[NPC]],enderId=25982,prevId=11890,rewardNextId=11896,wowhead=[[https://www.wowhead.com/wotlk/quest=11895]],image=[[assets/images/quests/placeholder.png]],desc=[[From what you describe, the creatures of metal should be easy to deal with. But first, you must master the storm. Behind me in the lodge is a totem. When you are ready, focus your will upon it and the storm will come. You must defeat the storm and in so doing take its essence into yourself. If others are there, it is enough that you all work together to defeat it. Return to me after, $c.]],logDesc=[[Defeat the Storm Tempest and then return to Sage Earth and Sky at Taunka'le Village.]]}
DB[11896]={id=11896,zoneId=3537,name=[[Weakness to Lightning]],level=71,minLevel=68,giver=[[Sage Earth and Sky]],giverType=[[NPC]],giverId=25982,ender=[[Sage Earth and Sky]],enderType=[[NPC]],enderId=25982,prevId=11895,rewardNextId=11907,wowhead=[[https://www.wowhead.com/wotlk/quest=11896]],image=[[assets/images/quests/placeholder.png]],desc=[[You now have the power of the storm within you. I will give you the means to focus that power and weaken the robots in the pools. Take this lightning rod. Use it against the robotic creations of the mechagnomes you find within the greater pools area to the west. Do not worry about using it against the mechagnomes themselves; Greatmother Taiga has other plans for them. Once the robots are weakened by the power of the storm, dismantle them utterly!]],logDesc=[[While weakened by the Power of the Storm, destroy any 15 of the robotic units, except the mechagnomes, in the greater pools area surrounding the Fizzcrank Pumping Station. Afterward, return to Sage Earth and Sky at Taunka'le Village.]]}
DB[11897]={id=11897,zoneId=3537,name=[[Plug the Sinkholes]],level=71,minLevel=68,giver=[[Sergeant Hammerhill]],giverType=[[NPC]],giverId=25816,ender=[[Sergeant Hammerhill]],enderType=[[NPC]],enderId=25816,prevId=11889,wowhead=[[https://www.wowhead.com/wotlk/quest=11897]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge are showing no sign of letting up, $N.  It's those blasted sinkholes; they connect to tunnels all the way to Icecrown for all we know.  Giant undead worms burrow under the ground to create them. If there's something years of mining has taught me it's that without support beams, tunnels will cave in easily after an explosion. Take these explosives and place them at the entrance to the sinkholes up on the ridge beyond the beach to the west.  Come back after you've collapsed them.]],logDesc=[[Sergeant Hammerhill wants you to use the Incendiary Explosives to collapse the sinkholes southwest and northwest of Valiance Keep.]],choiceRewards={{id=36884,qty=1},{id=36885,qty=1},{id=36886,qty=1},{id=36887,qty=1}}}
DB[11898]={id=11898,zoneId=3537,name=[[Breaking Through]],level=71,minLevel=68,giver=[[Chieftain Wintergale]],giverType=[[NPC]],giverId=24703,ender=[[Chieftain Wintergale]],enderType=[[NPC]],enderId=24703,prevId=11640,wowhead=[[https://www.wowhead.com/wotlk/quest=11898]],image=[[assets/images/quests/placeholder.png]],desc=[[On the lowest tier of the Temple City, there is a gray altar bathed in light. Step into it to gain entry to the dread necropolis Naxxanar. Be cautious, $N. Prince Valanar will certainly be defended by his personal retainers, who will give their lives to keep you from ascending to the top level of the necropolis. You must find your way through the necropolis to the prince's seat. If you fail to defeat him, $N, I fear my people will never know the safety Icemist offers.]],logDesc=[[Defeat Prince Valanar and his lieutenants, Vanthryn the Merciless and Luthion the Vile, then report to Chieftain Wintergale at Taunka'le Village.]],choiceRewards={{id=38232,qty=1},{id=38230,qty=1},{id=38231,qty=1}}}
DB[11899]={id=11899,zoneId=3537,name=[[Souls of the Decursed]],level=71,minLevel=68,giver=[[Greatmother Taiga]],giverType=[[NPC]],giverId=25602,ender=[[Greatmother Taiga]],enderType=[[NPC]],enderId=25602,wowhead=[[https://www.wowhead.com/wotlk/quest=11899]],image=[[assets/images/quests/placeholder.png]],desc=[[The mechagnomes in the pools to the west are a great mystery to us. They appeared not long after the gnomes disappeared from their pumping station and its environs. They are an unnatural danger and must be dealt with. Take this soulcatcher and use it on the remains of the mechagnomes to capture their souls. When you return, we will set them free so that we might find out what happened.]],logDesc=[[Use The Greatmother's Soulcatcher to capture the souls of 10 Fizzcrank mechagnomes. Then, return to Greatmother Taiga at Taunka'le Village once you have done so.]]}
DB[11900]={id=11900,zoneId=4024,name=[[Reading the Meters]],level=71,minLevel=69,giver=[[Archmage Berinand]],giverType=[[NPC]],giverId=25314,ender=[[Archmage Berinand]],enderType=[[NPC]],enderId=25314,rewardNextId=11905,wowhead=[[https://www.wowhead.com/wotlk/quest=11900]],image=[[assets/images/quests/placeholder.png]],desc=[[I had hoped that the Nexus' impact was limited to this region. Recently though, reports have flooded in from all over Azeroth suggesting that geologic instability is growing exponentially! I need the Nexus monitored regularly as I work to develop a solution. I've placed sensitive instruments around Coldarra, disguised as Malygos' scrying orbs. One lies in the trench near the Nexus, and three are hidden in the structures around the valley's perimeter. Visit each and return to me with their readings.]],logDesc=[[Archmage Berinand at the Transitus Shield has asked you to collect the readings from his instruments in Coldarra.]]}
DB[11901]={id=11901,zoneId=3537,name=[[Military?  What Military?]],level=71,minLevel=68,giver=[[Gerald Green]],giverType=[[NPC]],giverId=26083,enderType=[[NPC]],prevId=11928,rewardNextId=11902,wowhead=[[https://www.wowhead.com/wotlk/quest=11901]],image=[[assets/images/quests/placeholder.png]],desc=[[There's Scourge everywhere, $c.  We've organized the farmers and miners into a militia, but this just won't cut it. The one detachment of troops that Valiance Keep sent is defending the mine.  We haven't heard from them in days! If you really wish to help us, why don't you go to the mine and see what's going on?  Maybe we can get them to send us some reinforcements.]],logDesc=[[Gerald Green in Farshire wants you to go into the mine to the north and find out what happened to the military detachment that was sent there.]]}
DB[11902]={id=11902,zoneId=3537,name=[[Pernicious Evidence]],level=71,minLevel=68,giverType=[[NPC]],ender=[[Gerald Green]],enderType=[[NPC]],enderId=26083,prevId=11901,rewardNextId=11903,wowhead=[[https://www.wowhead.com/wotlk/quest=11902]],image=[[assets/images/quests/placeholder.png]],desc=[[The sacks of grain emanate the foul stench you've come to associate with the Plague.  This probably explains what happened to the footmen defending the mine. You'd best bring word back to Gerald Green.]],logDesc=[[Return to Gerald Green in Farshire.]]}
DB[11903]={id=11903,zoneId=3537,name=[[It's Time for Action]],level=71,minLevel=68,giver=[[Gerald Green]],giverType=[[NPC]],giverId=26083,ender=[[Gerald Green]],enderType=[[NPC]],enderId=26083,prevId=11902,rewardNextId=11904,wowhead=[[https://www.wowhead.com/wotlk/quest=11903]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, $N.  With the last of our military in Farshire dead or worse, we can do but one thing: fight these Scourge ourselves. We have deployed militia in what remains of Farshire.  Without your help, they've but little hope of winning.  Go and lend them a hand.  Me and the lads will watch this path.  We can't let the Scourge break through!]],logDesc=[[Gerald Green in Farshire wants you to kill 14 Plagued Scavengers.]],choiceRewards={{id=37208,qty=1},{id=37402,qty=1},{id=37543,qty=1},{id=37484,qty=1}}}
DB[11904]={id=11904,zoneId=3537,name=[[Fruits of Our Labor]],level=71,minLevel=68,giver=[[Gerald Green]],giverType=[[NPC]],giverId=26083,ender=[[Gerald Green]],enderType=[[NPC]],enderId=26083,prevId=11903,rewardNextId=11962,wowhead=[[https://www.wowhead.com/wotlk/quest=11904]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge just keeps coming... but we can't give up!  Listen, $N.  Inside that mine there's a cart with the last of the ore the Alliance is going to see on this side of the continent for a long time. The problem is the cart release is locked.  When the military went in there, Captain Jacobs commandeered all the important equipment, including the cart release key. The plague that affected the soldiers in the mine must also have affected Jacobs.  Get the key from him and salvage the ore.]],logDesc=[[Go to the mine in Farshire, obtain the Cart Release Key from Captain Jacobs and use it to release the ore cart.  Return to Gerald Green in Farshire when you've completed this task.]]}
DB[11905]={id=11905,zoneId=4265,name=[[Postponing the Inevitable]],level=71,minLevel=69,giver=[[Archmage Berinand]],giverType=[[NPC]],giverId=25314,ender=[[Archmage Berinand]],enderType=[[NPC]],enderId=25314,prevId=11900,wowhead=[[https://www.wowhead.com/wotlk/quest=11905]],image=[[assets/images/quests/placeholder.png]],desc=[[I've determined the cause of the instability! Azeroth's ley lines are being redirected to the Nexus. It's fascinating! If only I could spend the remainder of my days studying this anomaly.... Sadly, I must focus on the immediate crisis. The influx of arcane energies is tearing a rift between dimensions. Deep inside the Nexus, the fabric of our universe is being weakened. I cannot stop it, but I've discovered a way to slow it down. Take this into the Nexus and activate it near the forming rift.]],logDesc=[[Archmage Berinand in the Transitus Shield wants you to use the Interdimensional Refabricator near the rift in the Nexus.]],choiceRewards={{id=42758,qty=1},{id=42761,qty=1},{id=42763,qty=1},{id=42765,qty=1}}}
DB[11906]={id=11906,zoneId=3537,name=[[Cleaning Up the Pools]],level=71,minLevel=68,giver=[[Iron Eyes]],giverType=[[NPC]],giverId=26104,ender=[[Iron Eyes]],enderType=[[NPC]],enderId=26104,wowhead=[[https://www.wowhead.com/wotlk/quest=11906]],image=[[assets/images/quests/placeholder.png]],desc=[[<A single tear rolls down the face of Iron Eyes.> I have heard that you are heading back into the pools to the west. I have something for you to do while you are out there, $r. The gnomes, who care nothing for the land, have polluted it with their machinery. I want you to pick up any spare parts that you come across. Return them to me here. I will see to it that they are properly disposed of before we leave this place for good.]],logDesc=[[Collect 15 Fizzcrank Spare Parts and deliver them to Iron Eyes at Taunka'le Village.]],choiceRewards={{id=37275,qty=1},{id=37351,qty=1},{id=37443,qty=1},{id=37478,qty=1}}}
DB[11907]={id=11907,zoneId=3537,name=[[The Sub-Chieftains]],level=71,minLevel=68,giver=[[Sage Earth and Sky]],giverType=[[NPC]],giverId=25982,ender=[[Sage Earth and Sky]],enderType=[[NPC]],enderId=25982,prevId=11896,wowhead=[[https://www.wowhead.com/wotlk/quest=11907]],image=[[assets/images/quests/placeholder.png]],desc=[[It is known that Gearmaster Mechazod has four sub-chieftains that manage the robots in the pools. We must put an end to them! Our longrunners and snow trackers say that if you were to turn the valves at the west point, north point, mid point and south point stations, each of his sub-chieftains would come quickly to prevent you from fouling their operations. The stations are centered on the spinning lights in the pools surrounding the pumping station. Hurry, $N!]],logDesc=[[Defeat Twonky, ED-210, Max Blasto, and The Grinder, and then report back to Sage Earth and Sky at Taunka'le Village.]],choiceRewards={{id=37054,qty=1},{id=37231,qty=1},{id=37073,qty=1},{id=37072,qty=1},{id=37357,qty=1}}}
DB[11908]={id=11908,zoneId=3537,name=[[Reference Material]],level=71,minLevel=68,giver=[[Jeremiah Hawning]],giverType=[[NPC]],giverId=26084,ender=[[Jeremiah Hawning]],enderType=[[NPC]],enderId=26084,prevId=11901,rewardNextId=12035,wowhead=[[https://www.wowhead.com/wotlk/quest=11908]],image=[[assets/images/quests/placeholder.png]],desc=[[I was in charge of the harvest golems - an important job until the Scourge destroyed most of our farmlands.  I've an idea that would make the golems useful again, however. I think I can rewire the harvest collectors so they'll give us a hand fighting the Scourge. I'm not an expert at this just yet, so I'm going to need my manual.  The problem is, I left it at the workshop... which happens to be that burning building next to the mine.  Think you could go salvage it?]],logDesc=[[Jeremiah Hawning wants you to retrieve the book "Fields, Factories and Workshops" from the burning building next to the mine in Farshire.]]}
DB[11909]={id=11909,zoneId=3537,name=[[Defeat the Gearmaster]],level=72,minLevel=68,giver=[[Greatmother Taiga]],giverType=[[NPC]],giverId=25602,ender=[[Greatmother Taiga]],enderType=[[NPC]],enderId=25602,prevId=11899,wowhead=[[https://www.wowhead.com/wotlk/quest=11909]],image=[[assets/images/quests/placeholder.png]],desc=[[Clearly this Gearmaster Mechazod creature is not in his right mind. If his offer of a cure and immortality means all of us becoming robotic slaves then he must be stopped! The winds that guide me whisper that he's atop the pumping station out in the middle of the pools to the west. Most likely, he'll be found in the command hut on top of the structure. Go inside and research his works. $N, you must confront Mechazod if we are to survive!]],logDesc=[[Research the Gearmaster's Manual and return Mechazod's Head to Greatmother Taiga at Taunka'le Village.]],choiceRewards={{id=37122,qty=1},{id=37537,qty=1},{id=37522,qty=1},{id=37547,qty=1},{id=37535,qty=1}}}
DB[11910]={id=11910,zoneId=4024,name=[[Secrets of the Ancients]],level=71,minLevel=69,giver=[[Archmage Berinand]],giverType=[[NPC]],giverId=25314,ender=[[Archmage Berinand]],enderType=[[NPC]],enderId=25314,rewardNextId=11911,wowhead=[[https://www.wowhead.com/wotlk/quest=11910]],image=[[assets/images/quests/placeholder.png]],desc=[[It's become clear that the instability in the region has had an effect on its indigenous creatures. I've taken a particular interest in the Glacial Ancients and their recent adaptations. I suspect that their transformation into these 'Magic-bound' Ancients may hold clues to our predicament here. For my studies, I'll need samples from both. Do hurry....]],logDesc=[[Archmage Berinand in the Transitus Shield wants you to collect 3 Glacial Splinters and 3 Magic-Bound Splinters from the Ancients in Coldarra.]]}
DB[11911]={id=11911,zoneId=4265,name=[[Quickening]],level=71,minLevel=69,giver=[[Archmage Berinand]],giverType=[[NPC]],giverId=25314,ender=[[Archmage Berinand]],enderType=[[NPC]],enderId=25314,prevId=11910,wowhead=[[https://www.wowhead.com/wotlk/quest=11911]],image=[[assets/images/quests/placeholder.png]],desc=[[Though we may be witnessing the end of our existence, I can't help but marvel. I've learned more in my short time here than in decades of studies. These Ancients are being exposed to incredible levels of arcane energy. It's literally transforming them into something... different. I'm confident that there's another stage in their metamorphosis. I'll need you to actually enter the Nexus, $n, and find me some evidence of their final state. Do be careful....]],logDesc=[[Archmage Berinand in the Transitus Shield wants you to enter the Nexus and collect 5 Arcane Splinters from Crystalline Protectors.]],choiceRewards={{id=42760,qty=1},{id=42762,qty=1},{id=42766,qty=1},{id=42767,qty=1},{id=42768,qty=1}}}
DB[11912]={id=11912,zoneId=4024,name=[[Nuts for Berries]],level=71,minLevel=69,giver=[[Librarian Serrah]],giverType=[[NPC]],giverId=26110,ender=[[Librarian Serrah]],enderType=[[NPC]],enderId=26110,rewardNextId=11914,wowhead=[[https://www.wowhead.com/wotlk/quest=11912]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh! What a relief it is to see a fresh face. I was beginning to feel we had been forsaken. Our supply lines were cut off days ago, and things have been looking - well, bleak. To be honest, this was a suicide mission to begin with if you ask me. Maybe I'm simply not cut out for all of this violence - to say nothing of the bitter cold! I'd much rather be back in Dalaran studying ancient texts. To the point, our food supply is nearly spent. Please, gather what you can and bring it to me.]],logDesc=[[Librarian Serrah in the Transitus Shield wants you to gather 10 Frostberries from the Frostberry Bushes in Coldarra.]]}
DB[11913]={id=11913,zoneId=3537,name=[[Take No Chances]],level=71,minLevel=68,giver=[[Wendy Darren]],giverType=[[NPC]],giverId=26085,ender=[[Wendy Darren]],enderType=[[NPC]],enderId=26085,prevId=11902,wowhead=[[https://www.wowhead.com/wotlk/quest=11913]],image=[[assets/images/quests/placeholder.png]],desc=[[I heard what you told Gerald and I don't like it one bit.  If cultists managed to poison the grain in the mines with their foul plague, they could've easily done the same with the grain outside. We don't have time to sort the good grain from the bad.  We must act quickly and burn it all. Take this torch and set fire to any sacks of grain you find out here.  It would be a tragedy if we survived this attack only to succumb to the plague afterwards.]],logDesc=[[Wendy Darren wants you to use Wendy's Torch to burn 8 sacks of Farshire Grain.]],choiceRewards={{id=37205,qty=1},{id=37404,qty=1},{id=37524,qty=1},{id=37481,qty=1}}}
DB[11914]={id=11914,zoneId=4024,name=[[Keep the Secret Safe]],level=71,minLevel=69,giver=[[Librarian Serrah]],giverType=[[NPC]],giverId=26110,ender=[[Librarian Serrah]],enderType=[[NPC]],enderId=26110,prevId=11912,wowhead=[[https://www.wowhead.com/wotlk/quest=11914]],image=[[assets/images/quests/placeholder.png]],desc=[[Our existence here depends entirely upon staying hidden. Should the shield fail, even for a moment, Malygos' minions would have us. One of my responsibilities is to rejuvenate the warmages' mana levels so their focus doesn't falter. With our supply lines lost, I've been forced to improvise. I could use your help, $n. Very near the Nexus, Arcane Serpents feast on the abundant magical energies. Once defeated, they will yield a mana essence that I can make use of.]],logDesc=[[Librarian Serrah in the Transitus Shield needs you to kill Arcane Serpents near the Nexus and collect 5 Nexus Mana Essences from them.]],choiceRewards={{id=37434,qty=1},{id=37383,qty=1},{id=37512,qty=1},{id=37559,qty=1}}}
DB[11916]={id=11916,zoneId=3537,name=[[Hellscream's Champion]],level=71,minLevel=68,giver=[[Garrosh Hellscream]],giverType=[[NPC]],giverId=25237,ender=[[Chieftain Wintergale]],enderType=[[NPC]],enderId=24703,wowhead=[[https://www.wowhead.com/wotlk/quest=11916]],image=[[assets/images/quests/placeholder.png]],desc=[[You have faced all challenges that have been set before you and squashed them beneath your boot heel. It is because of you, $N, that the Horde is now firmly entrenched in Northrend. But our work has only just begun. We must march to Icecrown and we must tear down its walls! Your next assignment begins to the east, at Taunka'le Village. Our taunka allies are in dire straits and require aid. Secure transport from the stable master, Durkot Wolfbrother, and seek out Chieftain Wintergale at Taunka'le.]],logDesc=[[Seek out Chieftain Wintergale at Taunka'le Village.]],choiceRewards={{id=38238,qty=1},{id=38237,qty=1},{id=38240,qty=1},{id=38241,qty=1},{id=38242,qty=1},{id=38239,qty=1}}}
DB[11918]={id=11918,zoneId=4024,name=[[Basic Training]],level=71,minLevel=69,giver=[[Raelorasz]],giverType=[[NPC]],giverId=26117,ender=[[Raelorasz]],enderType=[[NPC]],enderId=26117,rewardNextId=11936,wowhead=[[https://www.wowhead.com/wotlk/quest=11918]],image=[[assets/images/quests/placeholder.png]],desc=[[This is war, mortal, and we are the tip of the spear. Your little spats over land or currency pale in comparison to this conflict. We face the aspect Malygos and his entire blue dragonflight. All you need to know is that if he is victorious, this world shall be no more. We are but few here, and we fly against many. Our deaths are all but a certainty, and our ultimate success lies in merely delaying our enemy. Go now. Busy yourself while I decide what to do with you.]],logDesc=[[Raelorasz at the Transitus Shield wants you to slay 10 Coldarra Spellweavers.]]}
DB[11919]={id=11919,zoneId=4024,name=[[Drake Hunt]],level=71,minLevel=69,giver=[[Raelorasz]],giverType=[[NPC]],giverId=26117,ender=[[Raelorasz]],enderType=[[NPC]],enderId=26117,prevId=11936,rewardNextId=11931,wowhead=[[https://www.wowhead.com/wotlk/quest=11919]],image=[[assets/images/quests/placeholder.png]],desc=[[The blues have begun to cover their drakes in mysterious runes. I must discover their significance. <Raelorasz pokes his hand with a spear and coats the tip with his blood.> Take this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires. Their hatchlings feed around the northwest edge of the valley.]],logDesc=[[Raelorasz wants you to use Raelorasz's Spear to subdue a Nexus Drake Hatchling and return it to him at the Transitus Shield.]],choiceRewards={{id=37226,qty=1},{id=37382,qty=1},{id=37435,qty=1},{id=37513,qty=1}}}
DB[11920]={id=11920,zoneId=3537,name=[[Cultists Among Us]],level=71,minLevel=68,giverType=[[NPC]],ender=[[Captain "Lefty" Lugsail]],enderType=[[NPC]],enderId=25298,prevId=-11789,wowhead=[[https://www.wowhead.com/wotlk/quest=11920]],image=[[assets/images/quests/placeholder.png]],desc=[[This altar bears all the markings of the Cult of the Damned.  It appears fanatics from the mainland have made it into Northrend.  It might be prudent to notify the captain of the ship. Perhaps he is to be found above deck.]],logDesc=[[Speak to Captain "Lefty" Lugsail above the Stormbreaker in Valiance Keep.]]}
DB[11927]={id=11927,zoneId=3537,name=[[Word on the Street]],level=71,minLevel=68,giver=[[Mark Hanes]],giverType=[[NPC]],giverId=26155,ender=[[Leryssa]],enderType=[[NPC]],enderId=25251,prevId=11897,rewardNextId=11599,wowhead=[[https://www.wowhead.com/wotlk/quest=11927]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey, $N.  There's a girl in the inn that's asking about you.  Her name's Leryssa. I don't think she knows you, but she said she needed your help.  She sounded really desperate.]],logDesc=[[Find Leryssa at the inn in Valiance Keep]]}
DB[11928]={id=11928,zoneId=3537,name=[[Farshire]],level=71,minLevel=68,giver=[[Sergeant Hammerhill]],giverType=[[NPC]],giverId=25816,ender=[[Gerald Green]],enderType=[[NPC]],enderId=26083,prevId=11897,rewardNextId=11901,wowhead=[[https://www.wowhead.com/wotlk/quest=11928]],image=[[assets/images/quests/placeholder.png]],desc=[[My lads should be able to take it from here, $N.  Valiance Keep is built to take a beating far worse than this.  I worry about our farmlands and mine in Farshire, however. We sent a full detachment to protect our mining operations right before the invasion - they should be able to defend the civilians. Gerald Green's in charge of the villagers there. There's a passage out of the northern wall out of Valiance Keep; it'll take you straight to him.  See what you can do to help them.]],logDesc=[[Travel to Farshire in Borean Tundra and speak to Gerald Green.]]}
DB[11929]={id=11929,zoneId=3537,name=[[The Fall of Taunka'le Village]],level=72,minLevel=71,giver=[[Chieftain Wintergale]],giverType=[[NPC]],giverId=24703,ender=[[Mother Tauranook]],enderType=[[NPC]],enderId=26158,prevId=11898,rewardNextId=11930,wowhead=[[https://www.wowhead.com/wotlk/quest=11929]],image=[[assets/images/quests/placeholder.png]],desc=[[We are lost, $N. This place has been our home for many generations, but it is no longer safe. There remains only death... Death and a memory of what used to be. I have called for the evacuation of Taunka'le. All remaining taunka must leave at once and make their way to our capital city, Icemist, located in the Dragonblight. <Wintergale points east.> You must help get my people to safety, $N. Mother Tauranook awaits you at the village gates. Hurry! The Scourge closes in from all sides!]],logDesc=[[Speak to Mother Tauranook outside the gates of Taunka'le Village.]]}
DB[11930]={id=11930,zoneId=3537,name=[[Across Transborea]],level=72,minLevel=71,giver=[[Mother Tauranook]],giverType=[[NPC]],giverId=26158,ender=[[Wartook Iceborn]],enderType=[[NPC]],enderId=26156,prevId=11929,rewardNextId=11977,wowhead=[[https://www.wowhead.com/wotlk/quest=11930]],image=[[assets/images/quests/placeholder.png]],desc=[[The path across Transborea, to the east, is the only way to reach the Dragonblight. Many perils await you as you make your journey across the tundra. Beware the Scourge and its influence upon the beasts of the land. Rumors have started to spread about our very own taunka brothers and sisters rising from the dead and attacking caravans on their way to the Dragonblight! Defend your caravan and get the evacuees to safety! Wartook Iceborn waits for you across the bridge leading into the Dragonblight.]],logDesc=[[Escort the Taunka'le Evacuees across Transborea to Wartook Iceborn on the border of the Dragonblight. ]]}
DB[11931]={id=11931,zoneId=4024,name=[[Cracking the Code]],level=71,minLevel=69,giver=[[Raelorasz]],giverType=[[NPC]],giverId=26117,ender=[[Raelorasz]],enderType=[[NPC]],enderId=26117,prevId=11919,wowhead=[[https://www.wowhead.com/wotlk/quest=11931]],image=[[assets/images/quests/placeholder.png]],desc=[[I sense a distinct peculiarity in the drakes here but the meaning of the runes that cover their bodies still eludes me. Without a codex, it will take more time than we can afford for me to interpret them. Not far from here is a Kirin Tor traitor, Caleras, who is likely to have a copy of the tome I require. His underlings hold the runes I will need for my translation. Hurry, mortal. Malygos gains strength with every passing moment.]],logDesc=[[Raelorasz at the Transitus Shield wants you to get the Azure Codex from Inquisitor Caleras and collect 3 Shimmering Runes from his Coldarra Spellbinders.]]}
DB[11932]={id=11932,zoneId=3537,name=[[Cowards and Fools]],level=71,minLevel=68,giver=[[Private Brau]],giverType=[[NPC]],giverId=25395,ender=[[Ataika]],enderType=[[NPC]],enderId=26169,prevId=11604,rewardNextId=12086,wowhead=[[https://www.wowhead.com/wotlk/quest=11932]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen, $N.  No offense, but the operation they put Thassarian in charge of was pure suicide. A handful of our men were to launch an attack on the biggest Scourge presence in the area.  Call me crazy, but storming a Scourge ziggurat outside a plagued Nerubian city with a dozen men ain't my idea of fun. If you're still interested in finding Thassarian, we were supposed to arrange for passage east with a tuskarr by the name of Ataika in Kaskala to the northeast.  Good luck with your fool's errand.]],logDesc=[[Speak to Ataika in Kaskala, northeast of Valiance Keep.]]}
DB[11934]={id=11934,name=[[Unlocking Your Potential [PH] ]],name_loc=[[Desbloquea tu potencial]],level=15,minLevel=15,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11934]],image=[[assets/images/quests/placeholder.png]],desc=[[Today you unlock a page in your spellbook, one you may not have realized it was there.  Bring me something, and I'll open it up for you.]],logDesc=[[Bring this dude some stuff.]]}
DB[11936]={id=11936,zoneId=4024,name=[[Hatching a Plan]],level=71,minLevel=69,giver=[[Raelorasz]],giverType=[[NPC]],giverId=26117,ender=[[Raelorasz]],enderType=[[NPC]],enderId=26117,prevId=11918,rewardNextId=11919,wowhead=[[https://www.wowhead.com/wotlk/quest=11936]],image=[[assets/images/quests/placeholder.png]],desc=[[Our goals here are simple. We are to remain hidden from Malygos, observe his brood, and thwart his efforts wherever possible. To that end, I have a task for you. The blues are laying their eggs at the base of the Nexus. Exposure to so much arcane energy will surely make them hatch sooner, and there's no telling what effect it will have on their spawn. I don't intend to find out. Slay the local wyrmkin and use their frozen axes to break the eggs.]],logDesc=[[Raelorasz at the Transitus Shield wants you to kill Coldarra Wyrmkin and use their frozen axes to break 5 blue dragon eggs.]]}
DB[11938]={id=11938,zoneId=3537,name=[[Buying Some Time]],level=72,minLevel=68,giver=[[Thassarian]],giverType=[[NPC]],giverId=26170,ender=[[Thassarian]],enderType=[[NPC]],enderId=26170,prevId=11956,rewardNextId=11942,wowhead=[[https://www.wowhead.com/wotlk/quest=11938]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we have this phylactery, I shouldn't have any problems getting the information I need.  It won't take long for the Scourge in the Temple City to notice something's up, however. I won't be able to fend off a full scale attack here.  Or maybe I would... but I'd rather not find out. I want you to head down there and inflict some casualties.  Hopefully they'll be distracted long enough for these two to spill their guts... figuratively, of course.  Take Lurid with you, he might be of aid.]],logDesc=[[Thassarian at the Wailing Ziggurat in Borean Tundra wants you to inflict 20 casualties against the Scourge inside the Temple City of En'kilah.  Use Lurid's Bones if you need assistance.]],choiceRewards={{id=37271,qty=1},{id=37393,qty=1},{id=37425,qty=1},{id=38212,qty=1}}}
DB[11939]={id=11939,zoneId=4024,name=[[?????]],level=71,minLevel=69,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11939]],image=[[assets/images/quests/placeholder.png]],desc=[[[PH]Quest to close this questline - summon and kill a mature drake (Elite?) - Fight a drake in the dungeon?]]}
DB[11940]={id=11940,zoneId=4024,name=[[Drake Hunt]],level=71,minLevel=69,giver=[[Raelorasz]],giverType=[[NPC]],giverId=26117,ender=[[Raelorasz]],enderType=[[NPC]],enderId=26117,prevId=11919,wowhead=[[https://www.wowhead.com/wotlk/quest=11940]],image=[[assets/images/quests/placeholder.png]],desc=[[I need more drake hatchlings to continue researching the runes covering their bodies. They can be found around the northwest edge of the valley.... <Raelorasz pokes his hand with a spear and coats the tip with his blood.> Take this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.]],logDesc=[[Raelorasz wants you to use the Blood-tipped Spear to subdue a Nexus Drake Hatchling and return it to him at the Transitus Shield.]]}
DB[11941]={id=11941,zoneId=4024,name=[[Puzzling...]],level=71,minLevel=69,giverType=[[NPC]],ender=[[Raelorasz]],enderType=[[NPC]],enderId=26117,rewardNextId=11943,wowhead=[[https://www.wowhead.com/wotlk/quest=11941]],image=[[assets/images/quests/placeholder.png]],desc=[[Something about this scrap of metal prevents you from casting it aside. Perhaps Raelorasz might be able to shed some light on its purpose.]],logDesc=[[Bring the Scintillating Fragment to Raelorasz at the Transitus Shield.]]}
DB[11942]={id=11942,zoneId=3537,name=[[Words of Power]],level=72,minLevel=68,giver=[[Thassarian]],giverType=[[NPC]],giverId=26170,ender=[[Thassarian]],enderType=[[NPC]],enderId=26170,prevId=11938,rewardNextId=12019,wowhead=[[https://www.wowhead.com/wotlk/quest=11942]],image=[[assets/images/quests/placeholder.png]],desc=[[The lich has spoken, $N.  The high priests of En'kilah hold the secret to entering Naxxanar. Go to the Spire of Blood, the Spire of Pain and the Spire of Decay and slay each of the priests. Return once you've obtained the three scrolls.]],logDesc=[[Thassarian at the Wailing Ziggurat wants you to go to the Temple City of En'kilah and retrieve High Priest Talet-Kha's Scroll from the Spire of Pain, High Priest Naferset's Scroll from the Spire of Decay and High Priest Andorath's Scroll at the Spire of Blood.]]}
DB[11943]={id=11943,zoneId=4024,name=[[The Cell]],level=71,minLevel=69,giver=[[Raelorasz]],giverType=[[NPC]],giverId=26117,ender=[[Raelorasz]],enderType=[[NPC]],enderId=26117,prevId=11941,wowhead=[[https://www.wowhead.com/wotlk/quest=11943]],image=[[assets/images/quests/placeholder.png]],desc=[[You've discovered a fragment of a special prison, $n. Malygos' minions use similar prisons to hold their captured mages and other arcane entities, but this prison was constructed to hold something... stronger. In hopes that the enemy of our enemy will prove to be a friend, you must search for the prison's remaining fragments. They are likely to be in the possession of Malygos' most trusted underlings.]],logDesc=[[Raelorasz at the Transitus Shield wants you to obtain the Prison Casing from General Cerulean and the Energy Core from Warbringer Goredrak.]],rewards={{id=35671,qty=1}}}
DB[11944]={id=11944,zoneId=3537,name=[[Surrounded!]],level=72,minLevel=68,giver=[[Corporal Venn]],giverType=[[NPC]],giverId=26187,ender=[[Corporal Venn]],enderType=[[NPC]],enderId=26187,prevId=12086,rewardNextId=12088,wowhead=[[https://www.wowhead.com/wotlk/quest=11944]],image=[[assets/images/quests/placeholder.png]],desc=[[Our situation is nearly hopeless.  We were ordered to take the Wailing Ziggurat with a handful of men. We'll be lucky if we can hold this position against the Scourge.  We're outnumbered, injured and have no escape route. If you can take some of the pressure off of us, we might be able to solidify our position.  Kill some of the undead circling the structure - we'll hold off their advance.]],logDesc=[[Corporal Venn at Death's Stand wants you to slay 7 Ziggurat Defenders.]],choiceRewards={{id=37214,qty=1},{id=37394,qty=1},{id=37424,qty=1},{id=37505,qty=1}}}
DB[11945]={id=11945,zoneId=3537,name=[[Preparing for the Worst]],level=72,minLevel=68,giver=[[Utaik]],giverType=[[NPC]],giverId=26213,ender=[[Utaik]],enderType=[[NPC]],enderId=26213,wowhead=[[https://www.wowhead.com/wotlk/quest=11945]],image=[[assets/images/quests/placeholder.png]],desc=[[Dark times are upon us.  Karkut's spirit walks the earth and gathers the spirits of dead tuskarr. The sons of the mist have taken many of our brethren.  Soon dear Kaskala will be reduced to ashes. There is hope yet.  Not for us perhaps, but we've sent our families to Unu'pe.  We fight here so there may be a future for them. They will need supplies or they will starve.  There's not enough food in Unu'pe.  Salvage any supplies before it's too late for our families.]],logDesc=[[Utaik wants you to gather 8 Kaskala Supplies in Kaskala.]]}
DB[11946]={id=11946,zoneId=4024,name=[[Keristrasza]],level=71,minLevel=69,giver=[[Keristrasza]],giverType=[[NPC]],giverId=26206,ender=[[Keristrasza]],enderType=[[NPC]],enderId=26206,prevId=11943,rewardNextId=11951,wowhead=[[https://www.wowhead.com/wotlk/quest=11946]],image=[[assets/images/quests/placeholder.png]],desc=[[I am... free? I was destined to spend an eternity roaming an empty abyss, and now am saved? You cannot fathom my gratitude, mortal. When I refused to bend to his will Malygos bound me to that prison, then shattered it and scattered the pieces. Should I live one hundred of your lifetimes, I shall not forget this kindness. Perhaps, in time, I will find ways to repay you. For now, though, we must focus our attention on Malygos. I am weak, and there is much to be done. I need your help, $n.]],logDesc=[[Keristrasza wants you to speak to her when you are ready to prepare for a confrontation with Malygos. If you lose your Augmented Arcane Prison, speak to Raelorasz at the Transitus Shield.]]}
DB[11949]={id=11949,zoneId=3537,name=[[Not Without a Fight!]],level=72,minLevel=68,giver=[[Ataika]],giverType=[[NPC]],giverId=26169,ender=[[Ataika]],enderType=[[NPC]],enderId=26169,rewardNextId=11950,wowhead=[[https://www.wowhead.com/wotlk/quest=11949]],image=[[assets/images/quests/placeholder.png]],desc=[[Kaskala is a sacred place for us, $r.  Our ancestors were guided here by the spirit of Tayutka herself. Now these foul creatures attack us from the mists without any provocation. We will show them that our spears are not merely for whaling.  Fight alongside us, friend.  Perhaps my people might repay you some time in the future.]],logDesc=[[Ataika wants you to slay 12 Kvaldir Raiders in Kaskala.]],choiceRewards={{id=37211,qty=1},{id=37421,qty=1},{id=37486,qty=1},{id=37525,qty=1}}}
DB[11950]={id=11950,zoneId=3537,name=[[Muahit's Wisdom]],level=72,minLevel=68,giver=[[Ataika]],giverType=[[NPC]],giverId=26169,ender=[[Elder Muahit]],enderType=[[NPC]],enderId=26218,prevId=11949,rewardNextId=11961,wowhead=[[https://www.wowhead.com/wotlk/quest=11950]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen, $N.  Warriors like me are replaceable.  If I fall, my brothers and cousins will pick up my spear and fight. My people cannot survive without wise elders.  Stubborn Muahit, our most venerable shaman, refuses to leave the altar to Tayutka in the central island.  We would suffer a significant loss if he was slain by these monsters. You are an outsider, maybe he'll listen to you.  Show him reason... ask him to flee to the safety of Unu'pe before it's too late.]],logDesc=[[Find Elder Muahit in Kaskala.]]}
DB[11951]={id=11951,zoneId=4024,name=[[Bait and Switch]],level=71,minLevel=69,giver=[[Keristrasza]],giverType=[[NPC]],giverId=26206,ender=[[Keristrasza]],enderType=[[NPC]],enderId=26206,prevId=11946,rewardNextId=11957,wowhead=[[https://www.wowhead.com/wotlk/quest=11951]],image=[[assets/images/quests/placeholder.png]],desc=[[During my captivity I was able to learn much about Malygos. Fate now allows us to use this knowledge against him. There is a great blue dragon, Saragosa, who circles high above the Nexus. She serves both as the aspect's guardian and as his consort. If any serious threats arise, she alerts her master of the danger. I suffered greatly at the hand of Saragosa during my captivity, and now her time to die has come. First, however, we must fashion the perfect bait....]],logDesc=[[Keristrasza has asked you to collect 10 Crystalized Mana Shards from around Coldarra. If you lose your Augmented Arcane Prison, speak to Raelorasz at the Transitus Shield.]]}
DB[11956]={id=11956,zoneId=3537,name=[[Finding the Phylactery]],level=71,minLevel=68,giver=[[Thassarian]],giverType=[[NPC]],giverId=26170,ender=[[Thassarian]],enderType=[[NPC]],enderId=26170,rewardNextId=11938,wowhead=[[https://www.wowhead.com/wotlk/quest=11956]],image=[[assets/images/quests/placeholder.png]],desc=[[No time for small talk, $N.  I was sent on what was to be a suicide mission to take this ziggurat.  I've accomplished my duty as a soldier, now is the time to get some answers. This lich has knowledge I seek, yet I cannot inflict pain to his physical body to obtain that knowledge. The lich stored his soul in a phylactery, and while it remains hidden, I won't be able to pry the information from him. Return to the camp and take my horse, Dusk, she will lead you to the phylactery.  Bring it to me.]],logDesc=[[Go to Death's Stand and ride Dusk to the location of Tanathal's Phylactery.  Obtain it and bring it back to Thassarian inside the Wailing Ziggurat.]]}
DB[11957]={id=11957,zoneId=4024,name=[[Saragosa's End]],level=71,minLevel=69,giver=[[Keristrasza]],giverType=[[NPC]],giverId=26206,ender=[[Keristrasza]],enderType=[[NPC]],enderId=26206,prevId=11951,rewardNextId=11967,wowhead=[[https://www.wowhead.com/wotlk/quest=11957]],image=[[assets/images/quests/placeholder.png]],desc=[[Using the mana crystals you provided, I have created this Power Focus. Saragosa is a glutton. She will be unable to resist its lure. Inside it lie magics that will greatly diminish her power. Let us hope she does not see through my ruse.... Prepare yourself, $n, and speak to me again when you are ready to face Saragosa. ]],logDesc=[[Keristrasza wants you to use the Power Focus to lure Saragosa, and then defeat her.]],choiceRewards={{id=37280,qty=1},{id=37322,qty=1},{id=37456,qty=1},{id=37562,qty=1}}}
DB[11958]={id=11958,zoneId=65,name=[[Let Nothing Go To Waste]],level=72,minLevel=71,giver=[[Elder Ko'nani]],giverType=[[NPC]],giverId=26194,ender=[[Elder Ko'nani]],enderType=[[NPC]],enderId=26194,rewardNextId=11959,wowhead=[[https://www.wowhead.com/wotlk/quest=11958]],image=[[assets/images/quests/placeholder.png]],desc=[[The wolvar have always been our natural enemies. But the incursion of your peoples into the Great Dragonblight has forced them into a small space upon the glade to the north. Combined with the land's upheaval this morning, they have become even more aggressive than ever before. They have made several raids upon our goods... things that we'll need if we are to survive the trek from our home here. As a sign of good faith and friendship, retrieve our goods from the Snowfall Glade wolvar.]],logDesc=[[Retrieve 6 Stolen Moa'ki Goods from the wolvar. Return them to Elder Ko'nani at Moa'ki Harbor.]]}
DB[11959]={id=11959,zoneId=65,name=[[Slay Loguhn]],level=73,minLevel=71,giver=[[Elder Ko'nani]],giverType=[[NPC]],giverId=26194,ender=[[Elder Ko'nani]],enderType=[[NPC]],enderId=26194,prevId=11958,wowhead=[[https://www.wowhead.com/wotlk/quest=11959]],image=[[assets/images/quests/placeholder.png]],desc=[[Already it goes from bad to worse. There is only one course to take... regrettably, Loguhn must die! He's the alpha male of the Snowfall Glade tribe and one mean wolvar. But it's the only way to get a short break from their attacks and stealing forays. You will find the "Render of Flesh" in front of his hovel upon the northern rise of the glade. It's larger than the others and hard to miss. Kill him and smear his blood upon yourself, both to show your dominance and respect.]],logDesc=[[Smear the Blood of Loguhn upon yourself and then return to Elder Ko'nani at Moa'ki Harbor.]],choiceRewards={{id=38026,qty=1},{id=37982,qty=1},{id=38087,qty=1},{id=37939,qty=1}}}
DB[11960]={id=11960,zoneId=65,name=[[Planning for the Future]],level=72,minLevel=71,giver=[[Trapper Mau'i]],giverType=[[NPC]],giverId=26228,ender=[[Trapper Mau'i]],enderType=[[NPC]],enderId=26228,wowhead=[[https://www.wowhead.com/wotlk/quest=11960]],image=[[assets/images/quests/placeholder.png]],desc=[[We must move decisively against the wolvar if we're to have a chance of survival. However, I worry that in our zeal, too many of them will be slain. The Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it that they get that chance. If Elder Ko'nani hasn't asked you already, he will ask you to deal with them.  While you're upon the glade to the north, I'd like you to bag up their pups and bring them back to me.]],logDesc=[[Collect 12 Snowfall Glade Pups. Deliver them to Trapper Mau'i at Moa'ki Harbor.]]}
DB[11961]={id=11961,zoneId=3537,name=[[Spirits Watch Over Us]],level=72,minLevel=68,giver=[[Elder Muahit]],giverType=[[NPC]],giverId=26218,ender=[[Elder Muahit]],enderType=[[NPC]],enderId=26218,prevId=11950,rewardNextId=11968,wowhead=[[https://www.wowhead.com/wotlk/quest=11961]],image=[[assets/images/quests/placeholder.png]],desc=[[Powerful spirits watch over my tribe -- Kaskala will not be lost. Issliruk will give us courage, Tayutka will make sure our survivors always have food and shelter and Karkut will watch over the fallen so they do not lose their way. Issliruk's guidance is the one we need the most right now.  I asked my nephew, Iruk, to bring me Issliruk's totem, but the Kvaldir's spears struck him down and his body fell into the waters to the north.  Bring me the totem, $N.  Don't let my nephew's death be in vain.]],logDesc=[[Elder Muahit at Njord's Breath Bay wants you to find Iruk's corpse in the water and retrieve Issliruk's totem.]]}
DB[11962]={id=11962,zoneId=3537,name=[[One Last Delivery]],level=71,minLevel=68,giver=[[Gerald Green]],giverType=[[NPC]],giverId=26083,ender=[[Hilda Stoneforge]],enderType=[[NPC]],enderId=25235,prevId=11904,rewardNextId=11963,wowhead=[[https://www.wowhead.com/wotlk/quest=11962]],image=[[assets/images/quests/placeholder.png]],desc=[[That's it then.  With the last of the ore you salvaged we now have enough to send to Valiance Keep. If Farshire is wiped off the face of Azeroth, then at least let us be remembered as the first ones to defend our land and the last ones to give up. Take this ore to Hilda Stoneforge - she is a good friend of mine.  Tell her to make some good weapons with this ore.  We'll need plenty of them in the days to come.]],logDesc=[[Deliver the Crate of Farshire Ore to Hilda Stoneforge in Valiance Keep.]]}
DB[11963]={id=11963,zoneId=3537,name=[[Weapons for Farshire]],level=71,minLevel=68,giver=[[Hilda Stoneforge]],giverType=[[NPC]],giverId=25235,ender=[[Gerald Green]],enderType=[[NPC]],enderId=26083,prevId=11962,rewardNextId=11965,wowhead=[[https://www.wowhead.com/wotlk/quest=11963]],image=[[assets/images/quests/placeholder.png]],desc=[[Farshire is overrun and all that Gerald can think of is to get me my ore shipment?  I swear that man has as much heart as any of our soldiers on the frontlines. We cannot let the civilians lose their lands if they're willing to fight for them.  We might not have the troops to spare, but we can send them weapons. These were earmarked for new recruits, but I'll be able to cover those with the ore you've brought me.  Send word to Gerald that weapons are on the way.]],logDesc=[[Return to Gerald Green in Farshire.]]}
DB[11965]={id=11965,zoneId=3537,name=[[Call to Arms!]],level=71,minLevel=68,giver=[[Gerald Green]],giverType=[[NPC]],giverId=26083,ender=[[Gerald Green]],enderType=[[NPC]],enderId=26083,prevId=11963,wowhead=[[https://www.wowhead.com/wotlk/quest=11965]],image=[[assets/images/quests/placeholder.png]],desc=[[Farshire has a fighting chance now, $N.  That's all we could've asked for and you've made it possible. All we need now is a rallying point.  I'll have my men deliver the weapons to our town hall.  Go and ring the town hall bell so any survivors know to rally there. It's time to show the Scourge what we're made of.]],logDesc=[[Go to the town hall building in Farshire and ring the bell inside of it.]],choiceRewards={{id=38227,qty=1},{id=38226,qty=1},{id=38228,qty=1}}}
DB[11967]={id=11967,zoneId=4024,name=[[Mustering the Reds]],level=71,minLevel=69,giver=[[Keristrasza]],giverType=[[NPC]],giverId=26206,ender=[[Raelorasz]],enderType=[[NPC]],enderId=26117,prevId=11957,rewardNextId=11969,wowhead=[[https://www.wowhead.com/wotlk/quest=11967]],image=[[assets/images/quests/placeholder.png]],desc=[[Malygos is certainly aware that something is amiss. I know him. His focus is fragmented. I am confident that I can lure him from the safety of his realm when he learns what has become of his precious Saragosa. Take me to Raelorasz at once, $n. He must rouse every dragon he commands to face Malygos.]],logDesc=[[Keristrasza has asked you to bring her to Raelorasz at the Transitus Shield.]]}
DB[11968]={id=11968,zoneId=3537,name=[[The Tides Turn]],level=71,minLevel=68,giver=[[Elder Muahit]],giverType=[[NPC]],giverId=26218,ender=[[Elder Muahit]],enderType=[[NPC]],enderId=26218,prevId=11961,wowhead=[[https://www.wowhead.com/wotlk/quest=11968]],image=[[assets/images/quests/placeholder.png]],desc=[[The spirits have heard our cry for help, $N.  It's a sign that Kaskala might yet be saved. Take advantage of the confusion the weather has created and slay the Kvaldir leader.  Your actions will sway the battle in our favor, I am sure of it.]],logDesc=[[Elder Muahit wants you to kill Heigarr the Horrible in Njord's Breath Bay.]],choiceRewards={{id=37030,qty=1},{id=37031,qty=1},{id=37029,qty=1},{id=37032,qty=1},{id=37033,qty=1}}}
DB[11969]={id=11969,zoneId=4024,name=[[Springing the Trap]],level=71,minLevel=69,giver=[[Raelorasz]],giverType=[[NPC]],giverId=26117,ender=[[Raelorasz]],enderType=[[NPC]],enderId=26117,prevId=11967,rewardNextId=11973,wowhead=[[https://www.wowhead.com/wotlk/quest=11969]],image=[[assets/images/quests/placeholder.png]],desc=[[We owe this opportunity in great part to your efforts, $n. It is only fitting that you initiate the attack on Malygos. Take this spark and use it to light the signal fire northwest of the Nexus. Keristrasza will direct you from there.]],logDesc=[[Raelorasz wants you to use Raelorasz' Spark at the signal fire in Coldarra.]],choiceRewards={{id=37080,qty=1},{id=37075,qty=1},{id=37076,qty=1},{id=37078,qty=1},{id=37077,qty=1},{id=37564,qty=1}}}
DB[11973]={id=11973,zoneId=4265,name=[[Prisoner of War]],level=71,minLevel=69,giver=[[Raelorasz]],giverType=[[NPC]],giverId=26117,ender=[[Raelorasz]],enderType=[[NPC]],enderId=26117,prevId=11969,wowhead=[[https://www.wowhead.com/wotlk/quest=11973]],image=[[assets/images/quests/placeholder.png]],desc=[[Malygos has taken Keristrasza to serve as his consort!? Unthinkable! She'll never cooperate willingly, but Malygos is a powerful aspect, and will eventually bend her will. This cannot come to pass, $n. I refuse to allow her to suffer this indignity. You must enter the Nexus and do whatever is required to spare her this fate.]],logDesc=[[Raelorasz at the Transitus Shield wants you to enter the Nexus and release Keristrasza.]],choiceRewards={{id=38223,qty=1},{id=38222,qty=1},{id=38221,qty=1}}}
DB[11974]={id=11974,name=[[[ph] Now, When I Grow Up...]],name_loc=[[Ahora, cuando sea mayor ...]],level=-1,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11974]],image=[[assets/images/quests/placeholder.png]],desc=[[When you were my age did you know that you wanted to be a $c when you grew up? I'm not sure what I want to be.  I used to want to be a Blood Knight, but not anymore.  Now I want to be a Rock Star!  Like the blood elf in L70 ETC! When they aren't touring, they hang out in Silvermoon City! Could you take me there? They hang out in the Walk of Elder's on a balcony... Probably to keep the fans away  But that shouldn't stop us from trying, right? Please take me there.  Please!]],logDesc=[[Take your orphan, Salandria, to see L70ETC in Silvermoon City's Walk of Elder's.  Make sure to call for her if she is not present when you arrive.]]}
DB[11977]={id=11977,zoneId=65,name=[[A Tauren Among Taunka]],level=72,minLevel=71,giver=[[Wartook Iceborn]],giverType=[[NPC]],giverId=26156,ender=[[Emissary Brighthoof]],enderType=[[NPC]],enderId=26181,prevId=11930,rewardNextId=11978,wowhead=[[https://www.wowhead.com/wotlk/quest=11977]],image=[[assets/images/quests/placeholder.png]],desc=[[<Wartook points northeast.> She is quite kind, you know. If it were not for your emissary, the surviving refugees may have given up hope. While she may not be taunka by birthright, the tribe has taken to her as a village elder for the time being. If you are who I think you are, please go and pay Emissary Brighthoof a visit inside the refugee camp. She has been waiting for you.]],logDesc=[[Seek out Emissary Brighthoof at the Westwind Refugee Camp.]]}
DB[11978]={id=11978,zoneId=65,name=[[Into the Fold]],level=72,minLevel=71,giver=[[Emissary Brighthoof]],giverType=[[NPC]],giverId=26181,ender=[[Emissary Brighthoof]],enderType=[[NPC]],enderId=26181,rewardNextId=11983,wowhead=[[https://www.wowhead.com/wotlk/quest=11978]],image=[[assets/images/quests/placeholder.png]],desc=[[Before we can officially bring these taunka into the Horde we must recover our armaments from the Anub'ar Nerubians that infest the nearby woods. The armaments were lost when a caravan from Agmar's Hammer was ambushed by the Scourge late last night. Venture out into the woods to the east of Westwind Refugee Camp and recover those armaments, $r.]],logDesc=[[Emissary Brighthoof at the Westwind Refugee Camp in the Dragonblight wants you to recover 10 Horde Armaments.]]}
DB[11979]={id=11979,zoneId=65,name=[[The Taunka and the Tauren]],level=72,minLevel=71,giver=[[Senior Sergeant Juktok]],giverType=[[NPC]],giverId=26415,ender=[[Emissary Brighthoof]],enderType=[[NPC]],enderId=26181,rewardNextId=11978,wowhead=[[https://www.wowhead.com/wotlk/quest=11979]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge have seized control of the capital city of the taunka, Icemist Village! All living taunka that escaped the massacre are being held in protective custody at the Westwind Refugee Camp on the western border of Dragonblight. Lord Hellscream believes that the taunka must join the Horde if they are to survive and has sent a tauren emissary to Westwind to bolster our relationship with the winter tauren. Travel to Westwind Refugee Camp and seek out Emissary Brighthoof. You will assist her.]],logDesc=[[Seek out Emissary Brighthoof at the Westwind Refugee Camp. ]]}
DB[11980]={id=11980,zoneId=65,name=[[Pride of the Horde]],level=72,minLevel=71,giver=[[Blood Guard Roh'kill]],giverType=[[NPC]],giverId=26180,ender=[[Blood Guard Roh'kill]],enderType=[[NPC]],enderId=26180,wowhead=[[https://www.wowhead.com/wotlk/quest=11980]],image=[[assets/images/quests/placeholder.png]],desc=[[I was one of the guards chosen to escort the caravan carrying the armament shipment to this camp. The attack came fast and without warning. We fought and killed dozens of the beasts, but in the end there were simply too many. Tor'zin and I barely made it out alive... If not for our injuries we would be out in the woods hunting down those fiends ourselves. Will you help us regain our lost pride? Search the woods east of here for Anub'ar Nerubians and kill them! For the Horde!]],logDesc=[[Blood Guard Roh'kill at the Westwind Refugee Camp in the Dragonblight wants you to slay 15 Anub'ar Ambushers. ]],choiceRewards={{id=37964,qty=1},{id=38006,qty=1},{id=38048,qty=1},{id=38081,qty=1},{id=38110,qty=1}}}
DB[11981]={id=11981,zoneId=394,name=[[Find Kurun!]],level=75,minLevel=72,giver=[[Fallen Earthen Warrior]],giverType=[[NPC]],giverId=26335,ender=[[Kurun]],enderType=[[NPC]],enderId=26260,nextId=11982,rewardNextId=11982,exGroup=11981,wowhead=[[https://www.wowhead.com/wotlk/quest=11981]],image=[[assets/images/quests/placeholder.png]],desc=[[The Earthen warrior's stone surface is covered with cracks and gouges. Although it is incapable of bleeding, you can sense that the warrior is near death. A low, hoarse voice escapes from the dying warrior's mouth. "Find... Kurun... you must find... Kurun." It looks at you helplessly as you ask for any clues as to who or what Kurun might be. "Our... leader... he stands on the... hill overlooking Thor Modan... commands us. Please... tell him... we cannot take... the city... "]],logDesc=[[Speak with Kurun on the hill overlooking Thor Modan.]]}
DB[11982]={id=11982,zoneId=394,name=[[Raining Down Destruction]],level=75,minLevel=72,giver=[[Kurun]],giverType=[[NPC]],giverId=26260,ender=[[Kurun]],enderType=[[NPC]],enderId=26260,prevId=11981,rewardNextId=12070,wowhead=[[https://www.wowhead.com/wotlk/quest=11982]],image=[[assets/images/quests/placeholder.png]],desc=[[Beneath us is iron's ancient bastion, Thor Modan. Thousands of years ago, the stone giants tore the land asunder, collapsing part of the city and exposing much of the rest. Even now, the iron dwarves attempt to reclaim their old capital, but we will not permit it. My giants fill the trench with boulders and debris, hoping to seal it off and kill the servants of iron as they work. Take up the boulders you see near the trench to the northeast, and help us put an end to their efforts.]],logDesc=[[Kurun on the hill overlooking Thor Modan wants you to disrupt the iron dwarves' work by throwing boulders into the exposed area of Thor Modan.]]}
DB[11983]={id=11983,zoneId=65,name=[[Blood Oath of the Horde]],level=72,minLevel=71,giver=[[Emissary Brighthoof]],giverType=[[NPC]],giverId=26181,ender=[[Emissary Brighthoof]],enderType=[[NPC]],enderId=26181,prevId=11978,rewardNextId=12008,wowhead=[[https://www.wowhead.com/wotlk/quest=11983]],image=[[assets/images/quests/placeholder.png]],desc=[[They are ready, $N. These taunka will all willingly join the Horde and give all that they have to see the Scourge driven from this world. <Brighthoof hands you a scroll bearing the insignia of the Horde.> Within this scroll you will find the blood oath of the Horde. Tradition dictates that our new taunka brothers and sisters utter the sacred words herein. Take the scroll and swear the taunka into the Horde, commander. Return the scroll to me when you have completed your duty.]],logDesc=[[Speak to the taunka at Westwind Refugee Camp and make 5 of them pledge their allegiance to the Horde. Return the Blood Oath of the Horde to Emissary Brighthoof once you have completed this task.]]}
DB[11984]={id=11984,zoneId=394,name=[[Filling the Cages]],level=74,minLevel=73,giver=[[Samir]],giverType=[[NPC]],giverId=26424,ender=[[Samir]],enderType=[[NPC]],enderId=26424,rewardNextId=11989,wowhead=[[https://www.wowhead.com/wotlk/quest=11984]],image=[[assets/images/quests/placeholder.png]],desc=[['Ol Budd's seen better days. Ever since our stay in Ghostlands he's been useless to us. We've had to find ways to make it on our own, and today that means sellin' trolls to the highest bidder. Fortunately, we've recently found a use for Budd. Something about his condition allows him to mingle with the local trolls, so we taught him a little game that's turned us a tidy profit. See for yourself. Talk to Budd, take him southwest to Drak' Zin Ruins and use this cage as soon as he tags a troll.]],logDesc=[[Samir at Granite Springs wants you to use the Bounty Hunter's Cage on a drakkari troll that's been stunned by Budd.]],choiceRewards={{id=39116,qty=1},{id=39131,qty=1},{id=39142,qty=1},{id=39129,qty=1},{id=39128,qty=1},{id=39132,qty=1}}}
DB[11985]={id=11985,zoneId=394,name=[[Into the Breach]],level=75,minLevel=72,giver=[[Kurun]],giverType=[[NPC]],giverId=26260,ender=[[Kurun]],enderType=[[NPC]],enderId=26260,prevId=12070,rewardNextId=12081,wowhead=[[https://www.wowhead.com/wotlk/quest=11985]],image=[[assets/images/quests/placeholder.png]],desc=[[If we can't overcome the defenders inside Thor Modan, the iron dwarves can hold out forever. The Earthen are bravely taking on the constructs built by the sons of iron, but they cannot break into the city. The tunnels narrow too quickly for my fellow giants to be of use, so our options are few. Would you be willing to venture into the city and kill the dwarf commanding the resistance?]],logDesc=[[Kurun on the hill overlooking Thor Modan wants you to kill Iron Thane Argrum.]],choiceRewards={{id=38715,qty=1},{id=39019,qty=1},{id=39048,qty=1},{id=39080,qty=1}}}
DB[11986]={id=11986,zoneId=394,name=[[The Damaged Journal]],level=75,minLevel=73,giverType=[[NPC]],ender=[[Torthen Deepdig]],enderType=[[NPC]],enderId=26361,wowhead=[[https://www.wowhead.com/wotlk/quest=11986]],image=[[assets/images/quests/placeholder.png]],desc=[[This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps. The author's handwriting seems vaguely familiar, but you're unable to place it until you discover an entry signed with the name of Brann Bronzebeard. The back half of the book, containing the most recent entries, has been torn away. Pages litter the battlefield, and it will be impossible to know what Brann discovered here until the book is whole again.]],logDesc=[[Recover 8 Missing Journal Pages, combine them with the Incomplete Journal, and return the completed journal to Torthen Deepdig at the Westfall Brigade Encampment.]]}
DB[11987]={id=11987,name=[[zzOLDFortune Card: Silver]],name_loc=[[zzOLDFortune Card: Silver]],level=1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11987]],image=[[assets/images/quests/placeholder.png]],choiceRewards={{id=35745,qty=1},{id=35745,qty=1},{id=35745,qty=1}}}
DB[11988]={id=11988,zoneId=394,name=[[The Runic Keystone]],level=75,minLevel=73,giver=[[Torthen Deepdig]],giverType=[[NPC]],giverId=26361,ender=[[Torthen Deepdig]],enderType=[[NPC]],enderId=26361,prevId=11986,wowhead=[[https://www.wowhead.com/wotlk/quest=11988]],image=[[assets/images/quests/placeholder.png]],desc=[[Brann's journal mentions that he used a runic keystone to illuminate the important runes on the plate he discovered. Without the keystone, the plate's contents would be little better than gibberish. At the end of Brann's last entry, he describes the iron dwarf defenders seizing the keystone from him, shattering it, and dividing it among themselves. Before we can decipher the runed plate, we must hunt down the fragments. Any of the dwarves within Thor Modan or the buildings around it may carry fragments.]],logDesc=[[Bring 5 Runic Keystone Fragments to Torthen Deepdig at the Westfall Brigade Encampment.]]}
DB[11989]={id=11989,zoneId=394,name=[[Truce?]],level=73,minLevel=73,giver=[[Drakuru]],giverType=[[NPC]],giverId=26423,ender=[[Drakuru]],enderType=[[NPC]],enderId=26423,prevId=11984,rewardNextId=11990,wowhead=[[https://www.wowhead.com/wotlk/quest=11989]],image=[[assets/images/quests/placeholder.png]],desc=[[Watch yerself, mon. Drakuru shrunk more $r heads than I can remember - and even if I could remember, I couldn't count that high. Lucky for you I be stuck in dis cage or I'd be addin' one more to da list. But things bein' what they are, mebbe we be puttin' our differences aside fer a time, eh? Drakuru know things, mon. Things that will aid you in your struggle here. <Drakuru cuts the palm of his hand on one of his tusks and extends it through the cage.> So, what you say, mon... truce?]],logDesc=[[Drakuru at Granite Springs wants you to use the Dull Carving Knife near his cage and then speak to him.]]}
DB[11990]={id=11990,zoneId=394,name=[[Vial of Visions]],level=74,minLevel=73,giver=[[Drakuru]],giverType=[[NPC]],giverId=26423,ender=[[Drakuru]],enderType=[[NPC]],enderId=26423,prevId=11989,rewardNextId=11991,wowhead=[[https://www.wowhead.com/wotlk/quest=11990]],image=[[assets/images/quests/placeholder.png]],desc=[[First things first, mon. There be some preparatory work that need doin'. No tellin' how long dey gunna keep me here. Ya be needin' a powerful elixir so we can be keepin' in touch. Lucky for you, I know just the thing! And the ingredients all be close by. I need a vial from the pretty little troll over there, some waterweed from the lake just north of here, and a few haze leaves found around the camp here. Hurry now, mon, before dey be haulin' me away.]],logDesc=[[Drakuru at Granite Springs wants you to bring him an Imbued Vial, a Waterweed Frond, and 3 Haze Leaves.]]}
DB[11991]={id=11991,zoneId=394,name=[[Subject to Interpretation]],level=74,minLevel=73,giver=[[Drakuru]],giverType=[[NPC]],giverId=26423,ender=[[Image of Drakuru]],enderType=[[NPC]],enderId=26500,prevId=11990,rewardNextId=12007,wowhead=[[https://www.wowhead.com/wotlk/quest=11991]],image=[[assets/images/quests/placeholder.png]],desc=[[A legendary set of artifacts, lost for thousands of years, were created to make Drak'Tharon Keep impervious. Most think they be myth, but Drakuru knows better, mon! I nearly discovered where one be, but got captured while interpreting hieroglyphs. Ya gotta summon my soul back dere so I can finish readin' em! Use my elixir at da brazier on Drak'Zin Ruins, southwest of here. You'll hafta mix in da frozen mojo my bruddas be holdin'. I hate ta see my bruddas fall, but it be for the greater good. ]],logDesc=[[Drakuru wants you to get 5 Frozen Mojo from the Drakkari Trolls at the Ruins of Drak'Zin and then use the elixir at Drakuru's Brazier there.]],choiceRewards={{id=38716,qty=1},{id=39020,qty=1},{id=39049,qty=1},{id=39081,qty=1}}}
DB[11992]={id=11992,zoneId=3537,name=[[Navigation Charts (Deprecated)]],level=71,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11992]],image=[[assets/images/quests/placeholder.png]],desc=[[You've uncovered the first part of a navigation chart drawn on flayed dragonskin.  If you could complete it you'd be able to find the kvaldir's future plans of attack. Other mariners in Riplash might have the missing charts on them.  Karuk would be interested in the information they contain.]],logDesc=[[Obtain the missing parts of the Skadir Navigational Chart and bring it to Karuk in Riplash Stand.]]}
DB[11993]={id=11993,zoneId=394,name=[[The Runic Prophecies]],level=75,minLevel=73,giver=[[Torthen Deepdig]],giverType=[[NPC]],giverId=26361,ender=[[Torthen Deepdig]],enderType=[[NPC]],enderId=26361,prevId=11988,wowhead=[[https://www.wowhead.com/wotlk/quest=11993]],image=[[assets/images/quests/placeholder.png]],desc=[[We've no time to lose! Now that we've reassembled the runic keystone -- well, most of it -- we can decipher the contents of those very same runic plates Brann was working on before he fled. We have no way of knowing if he managed to read the contents of all three plates, but we'll have to assume he got enough information to determine his next destination. Stand before each of the plates and use the keystone to determine the contents of each. Brann may be counting on us!]],logDesc=[[Torthen Deepdig at the Westfall Brigade Encampment wants you to decipher the three Rune Plates.]],choiceRewards={{id=38710,qty=1},{id=39013,qty=1},{id=39043,qty=1},{id=39075,qty=1}}}
DB[11994]={id=11994,name=[[Juno's Flag Tester]],name_loc=[[Juno's Flag Tester]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11994]],image=[[assets/images/quests/placeholder.png]]}
DB[11995]={id=11995,zoneId=65,name=[[Your Presence is Required at Stars' Rest]],level=72,minLevel=71,giver=[[Emissary Skyhaven]],giverType=[[NPC]],giverId=26440,ender=[[Image of Archmage Modera]],enderType=[[NPC]],enderId=26673,rewardNextId=12000,exGroup=11995,wowhead=[[https://www.wowhead.com/wotlk/quest=11995]],image=[[assets/images/quests/placeholder.png]],desc=[[$C, I know these tuskarr will ask you to do many favors for them, but you must get to Stars' Rest with all due haste! The upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives. Stars' Rest is westward past the intersection of the road leading north out of the harbor. There is an archmage there named Modera. She will be expecting you.]],logDesc=[[Speak with the Image of Archmage Modera at Stars' Rest.]]}
DB[11996]={id=11996,zoneId=65,name=[[Your Presence is Required at Agmar's Hammer]],level=72,minLevel=71,giver=[[Envoy Ripfang]],giverType=[[NPC]],giverId=26441,ender=[[Image of Archmage Aethas Sunreaver]],enderType=[[NPC]],enderId=26471,rewardNextId=11999,wowhead=[[https://www.wowhead.com/wotlk/quest=11996]],image=[[assets/images/quests/placeholder.png]],desc=[[$C, I know these tuskarr will ask you to do many favors for them, but you must get to Agmar's Hammer with all due haste! The upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives. The Hammer is westward past the intersection of the road leading north out of the harbor. Archmage Aethas Sunreaver himself will be expecting you!]],logDesc=[[Speak with the Image of Archmage Aethas Sunreaver at Agmar's Hammer.]]}
DB[11997]={id=11997,zoneId=394,name=[[REUSE]],level=75,minLevel=73,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=11997]],image=[[assets/images/quests/placeholder.png]],desc=[[The Westfall Brigade has been dispatched to the northeastern part of Grizzly Hills to secure passage for our troops. They have established a base camp to the northeast of Grizzlemaw, and to the southwest of Thor Modan. You might recognize the brigade's leader, Captain Gryan Stoutmantle as an honored veteran of the war against the Scourge in Lordaeron. But the people of Westfall know him best for his decision to leave the battlefield and return home to take on the Defias.]],logDesc=[[Speak with Captain Gryan Stoutmantle at the Westfall Brigade Encampment.]]}
DB[11998]={id=11998,zoneId=394,name=[[Softening the Blow]],level=75,minLevel=73,giver=[[Captain Gryan Stoutmantle]],giverType=[[NPC]],giverId=26212,ender=[[Brugar Stoneshear]],enderType=[[NPC]],enderId=26226,rewardNextId=12002,wowhead=[[https://www.wowhead.com/wotlk/quest=11998]],image=[[assets/images/quests/placeholder.png]],desc=[[Our best bet for moving our forces quickly to Icecrown Glacier lies with the network of tunnels beneath the ancient iron dwarf city of Thor Modan. Brugar Stoneshear and his Explorers' League boys aren't going to be happy, but orders are orders. The news might go over better if you brought him a cask of that moonshine sold by that trapper, Hugh Glass, down at Redwood Trading Post, southeast of here along the tree line. Man's not right in the head, but you won't find better moonshine out here.]],logDesc=[[Bring Brugar Stoneshear at the Westfall Brigade Encampment a cask of Howlin' Good Moonshine.]]}
DB[11999]={id=11999,zoneId=65,name=[[Rifle the Bodies]],level=72,minLevel=71,giver=[[Image of Archmage Aethas Sunreaver]],giverType=[[NPC]],giverId=26471,ender=[[Image of Archmage Aethas Sunreaver]],enderType=[[NPC]],enderId=26471,prevId=11996,rewardNextId=12005,wowhead=[[https://www.wowhead.com/wotlk/quest=11999]],image=[[assets/images/quests/placeholder.png]],desc=[[The Moonrest Gardens to the southwest were the final resting place of a group of Highborne elves. It was also a ley line nexus. The blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will. I want more information and you are going to get it for me! After the land was destroyed at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters there. Go rifle their corpses for clues.]],logDesc=[[Find the Moonrest Gardens Plans and return them to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.]]}
DB[12000]={id=12000,zoneId=65,name=[[Rifle the Bodies]],level=72,minLevel=71,giver=[[Image of Archmage Modera]],giverType=[[NPC]],giverId=26673,ender=[[Image of Archmage Modera]],enderType=[[NPC]],enderId=26673,rewardNextId=12004,wowhead=[[https://www.wowhead.com/wotlk/quest=12000]],image=[[assets/images/quests/placeholder.png]],desc=[[The Moonrest Gardens to the southwest were the final resting place of a noble group of Highborne elves. It was also a powerful ley line nexus. The blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will. I need more information and I hope that you will get it for me. After the upheaval at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters present. Go rifle their corpses for clues.]],logDesc=[[Find the Moonrest Gardens Plans and return them to the Image of Archmage Modera at Stars' Rest.]]}
DB[12001]={id=12001,name=[[zzOLDHunting Tarot: Lesser Beasts]],name_loc=[[zzOLDHunting Tarot: Lesser Beasts]],level=5,minLevel=5,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12001]],image=[[assets/images/quests/placeholder.png]],desc=[[Staring into the card, the image blurs until you see yourself standing covered in the furs from many wolves and bears.  You can only assume this is your destiny should you invoke the tarot's power.]],logDesc=[[Collect 12 Torn Hides and then summon the Huntsman with the Hunting Tarot.  The Torn Hides can only be gathered from beasts of level 5 or higher.]]}
DB[12002]={id=12002,zoneId=394,name=[[Brothers in Battle]],level=75,minLevel=73,giver=[[Brugar Stoneshear]],giverType=[[NPC]],giverId=26226,ender=[[Brugar Stoneshear]],enderType=[[NPC]],enderId=26226,prevId=11998,rewardNextId=12003,wowhead=[[https://www.wowhead.com/wotlk/quest=12002]],image=[[assets/images/quests/placeholder.png]],desc=[[I hope Gryan knows I withdrew my men from Thor Modan when the battle began. There's no way we can excavate anything until that place settles down. You seem like a brave sort, though, and you have Stoutmantle's trust. Thor Modan is just to the northeast of us and the battle still rages between our Earthen brothers and the creations of those accursed iron dwarves. Help our brethren to even the odds and I'll start figuring out how we're going to accomplish this survey of Thor Modan.]],logDesc=[[Kill 10 Runic Battle Golems and return to Brugar Stoneshear at the Westfall Brigade Encampment.]]}
DB[12003]={id=12003,zoneId=394,name=[[Uncovering the Tunnels]],level=75,minLevel=73,giver=[[Brugar Stoneshear]],giverType=[[NPC]],giverId=26226,ender=[[Brugar Stoneshear]],enderType=[[NPC]],enderId=26226,prevId=12002,rewardNextId=12010,wowhead=[[https://www.wowhead.com/wotlk/quest=12003]],image=[[assets/images/quests/placeholder.png]],desc=[[The first place we'll search for entrances to the Thor Modan tunnel system will be the outlying buildings. As I left the site with my men, it looked like the iron dwarf defenders were taking refuge inside the buildings. Be careful as you explore them. Any tunnel entrances are likely to be toward the back of the buildings. I'm not sure what Stoutmantle thinks we're going to find down there, but I doubt the iron dwarves will make the search easy.]],logDesc=[[Brugar Stoneshear at the Westfall Brigade Encampment wants you to explore the North Building, the East Building, and the South Building of Thor Modan.]]}
DB[12004]={id=12004,zoneId=65,name=[[Prevent the Accord]],level=73,minLevel=71,giver=[[Image of Archmage Modera]],giverType=[[NPC]],giverId=26673,ender=[[Image of Archmage Modera]],enderType=[[NPC]],enderId=26673,prevId=12000,wowhead=[[https://www.wowhead.com/wotlk/quest=12004]],image=[[assets/images/quests/placeholder.png]],desc=[[We need to kill two birds with one stone here, $c. You're the stone. Our two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit. I require proof of their demise, if you would be so kind.]],logDesc=[[Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Modera at Stars' Rest.]],choiceRewards={{id=37943,qty=1},{id=37987,qty=1},{id=38031,qty=1},{id=38094,qty=1}}}
DB[12005]={id=12005,zoneId=65,name=[[Prevent the Accord]],level=73,minLevel=71,giver=[[Image of Archmage Aethas Sunreaver]],giverType=[[NPC]],giverId=26471,ender=[[Image of Archmage Aethas Sunreaver]],enderType=[[NPC]],enderId=26471,prevId=11999,wowhead=[[https://www.wowhead.com/wotlk/quest=12005]],image=[[assets/images/quests/placeholder.png]],desc=[[We need to kill two birds with one stone here, $c. You're the stone. Our two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit. I require proof of their demise, if you would be so kind.]],logDesc=[[Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.]],choiceRewards={{id=37943,qty=1},{id=37987,qty=1},{id=38031,qty=1},{id=38094,qty=1}}}
DB[12006]={id=12006,zoneId=65,name=[[Avenge this Atrocity!]],level=72,minLevel=71,giver=[[Ethenial Moonshadow]],giverType=[[NPC]],giverId=26501,ender=[[Ethenial Moonshadow]],enderType=[[NPC]],enderId=26501,rewardNextId=12013,wowhead=[[https://www.wowhead.com/wotlk/quest=12006]],image=[[assets/images/quests/placeholder.png]],desc=[[These so-called mage hunters came here and destroyed our resting place. Avenge us, or I will see to it that your base of operations is overrun with the spirits of the dead!]],logDesc=[[Kill any combination of 15 Dragonblight Mage Hunters, Moonrest Stalkers, Surge Needle Sorcerers, and Focus Wizards. After you have done that, return to Ethenial Moonshadow at Moonrest Gardens.]]}
DB[12007]={id=12007,zoneId=394,name=[[Sacrifices Must be Made]],level=74,minLevel=73,giver=[[Image of Drakuru]],giverType=[[NPC]],giverId=26500,ender=[[Image of Drakuru]],enderType=[[NPC]],enderId=26543,prevId=11991,rewardNextId=12042,wowhead=[[https://www.wowhead.com/wotlk/quest=12007]],image=[[assets/images/quests/placeholder.png]],desc=[[I've got it, mon! To da north, on da Ziggurat at Zeb'Halak be a stone head with ruby eyes. One o' dem be da Eye of the Prophets! Bring it to the brazier there and drink my elixir. Again, ya be needing some mojo for my elixir to work - dis time from da warlord, Zim'bo. He be hidin' in one of da huts in Zeb'Halak. It be a shame to kill Zim'bo, mon, but he swore da blood oath to defend Drak'Tharon and he done failed. Now at least his mojo be helpin' us to reclaim Drak'Tharon.]],logDesc=[[Drakuru wants you to bring the Eye of the Prophets to him at Drakuru's Brazier in Zeb'Halak. You will need to collect Zim'bo's Mojo to use Drakuru's Elixir there.]]}
DB[12008]={id=12008,zoneId=65,name=[[Agmar's Hammer]],level=72,minLevel=71,giver=[[Emissary Brighthoof]],giverType=[[NPC]],giverId=26181,ender=[[Overlord Agmar]],enderType=[[NPC]],enderId=26379,prevId=11983,wowhead=[[https://www.wowhead.com/wotlk/quest=12008]],image=[[assets/images/quests/placeholder.png]],desc=[[Directly east of this refugee camp stands Agmar's Hammer - testament to the Hordes' power in the Dragonblight. While I have no doubt that our Horde brothers and sisters are already seeing the result of your efforts to bring the taunka into the Horde, I want you to deliver news of your success to Overlord Agmar in person. Go now, $N! Race the winds! East to Agmar's Hammer! ]],logDesc=[[Travel to Agmar's Hammer in the Dragonblight and speak to Overlord Agmar. ]]}
DB[12009]={id=12009,zoneId=65,name=[[Tua'kea's Crab Traps]],level=72,minLevel=71,giver=[[Tua'kea]],giverType=[[NPC]],giverId=26245,ender=[[Tua'kea]],enderType=[[NPC]],enderId=26245,prevId=11959,wowhead=[[https://www.wowhead.com/wotlk/quest=12009]],image=[[assets/images/quests/placeholder.png]],desc=[[With all of the troubles, I've lost my assistants. I was wondering if maybe you could help me? I have many crab traps under the waves of the harbor. Will you retrieve them for me? I'm too old for that sort of thing and the waters can be very dangerous. Please, take this bladder. It will help you to breathe while you're down there.]],logDesc=[[Collect 8 of Tua'kea's Crab Traps and return them to him at Moa'ki Harbor.]]}
DB[12010]={id=12010,zoneId=394,name=[[The Fate of Orlond]],level=75,minLevel=73,giver=[[Brugar Stoneshear]],giverType=[[NPC]],giverId=26226,ender=[[Surveyor Orlond]],enderType=[[NPC]],enderId=26514,prevId=12003,rewardNextId=12014,wowhead=[[https://www.wowhead.com/wotlk/quest=12010]],image=[[assets/images/quests/placeholder.png]],desc=[[When we began excavating the city, I sent Surveyor Orlond to check the stability of the tunnels in Thor Modan. I didn't see him escape when we withdrew at the beginning of the battle, and I worry he may still be trapped inside the city. If we're going to get an army through Thor Modan, we'll need the information he was collecting. Stoutmantle and his superiors would have my hide if the tunnels collapsed on one of their brigades!]],logDesc=[[Locate Surveyor Orlond within Thor Modan.]]}
DB[12011]={id=12011,zoneId=65,name=[[Signs of Big Watery Trouble]],level=72,minLevel=71,giverType=[[NPC]],ender=[[Tua'kea]],enderType=[[NPC]],enderId=26245,prevId=11959,rewardNextId=12016,wowhead=[[https://www.wowhead.com/wotlk/quest=12011]],image=[[assets/images/quests/placeholder.png]],desc=[[This crab trap appears to have been destroyed by something much larger than the nearby circling sharks. Perhaps Tua'kea, the fisherman at Moa'ki Harbor, should be told about this?]],logDesc=[[Inform Tua'kea at Moa'ki Harbor about the wrecked crab trap.]]}
DB[12013]={id=12013,zoneId=65,name=[[End Arcanimus]],level=73,minLevel=71,giver=[[Ethenial Moonshadow]],giverType=[[NPC]],giverId=26501,ender=[[Ethenial Moonshadow]],enderType=[[NPC]],enderId=26501,prevId=12006,wowhead=[[https://www.wowhead.com/wotlk/quest=12013]],image=[[assets/images/quests/placeholder.png]],desc=[[There is one last thing that I would have you do, $N the $r. I would have you destroy Arcanimus! The sorcerers to the west used that giant device in the sky to bore a massive pit into our resting place. When they did that, they unleashed a monstrosity! I would not care if it were only a concern for mortals, but Arcanimus feeds upon the spirits of the dead. You will put an end to it now!]],logDesc=[[Destroy Arcanimus and then return to Ethenial Moonshadow at Moonrest Gardens.]],choiceRewards={{id=37941,qty=1},{id=38028,qty=1},{id=37984,qty=1},{id=38092,qty=1}}}
DB[12014]={id=12014,zoneId=394,name=[[Steady as a Rock?]],level=75,minLevel=73,giver=[[Surveyor Orlond]],giverType=[[NPC]],giverId=26514,ender=[[Brugar Stoneshear]],enderType=[[NPC]],enderId=26226,prevId=12010,wowhead=[[https://www.wowhead.com/wotlk/quest=12014]],image=[[assets/images/quests/placeholder.png]],desc=[[Orlond's notes indicate that he brought a piece of equipment called a portable seismograph with him, but the device is nowhere to be seen. The survey log shows that Orlond completed all his readings in the Thor Modan tunnel, save one labeled the 'east end of the exposed tunnel.' The last entry in the log indicates Orlond tried to take refuge in the water and was attacked by subterranean threshers. They might've taken his equipment.You'll need to recover it before you can take the last reading.]],logDesc=[[Retreive the Portable Seismograph and use it to take stability readings in Thor Modan, then return to Brugar Stoneshear at the Westfall Brigade Encampment.]],choiceRewards={{id=38717,qty=1},{id=39021,qty=1},{id=39050,qty=1},{id=39082,qty=1}}}
DB[12015]={id=12015,zoneId=65,name=[[Test Quest for Craig]],level=62,minLevel=58,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12015]],image=[[assets/images/quests/placeholder.png]],desc=[[klajsdklajlsd]],logDesc=[[Craig Amai at wherever wants you to bring him 5 whatevers.]]}
DB[12016]={id=12016,zoneId=65,name=[[The Bait]],level=72,minLevel=71,giver=[[Tua'kea]],giverType=[[NPC]],giverId=26245,ender=[[Tua'kea]],enderType=[[NPC]],enderId=26245,prevId=12011,rewardNextId=12017,wowhead=[[https://www.wowhead.com/wotlk/quest=12016]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm sure of it... our ancient aquatic nemesis, Tu'u'gwar, "He Who Plays With Food", has returned. We must lay a trap for him, you and I. If Tu'u'gwar has one weakness it's his stomach. There's one meat for certain that he'd never be able to pass up. "Two Huge Pincers", the mother of all crabs, Kili'ua, paces upon her island out in the waters to the southwest. You must pay her a visit and return with her meat.]],logDesc=[[Obtain The Flesh of "Two Huge Pincers" and deliver it to Tua'kea at Moa'ki Harbor.]]}
DB[12017]={id=12017,zoneId=65,name=[[Meat on the Hook]],level=73,minLevel=71,giver=[[Tua'kea]],giverType=[[NPC]],giverId=26245,ender=[[Tua'kea]],enderType=[[NPC]],enderId=26245,prevId=12016,wowhead=[[https://www.wowhead.com/wotlk/quest=12017]],image=[[assets/images/quests/placeholder.png]],desc=[[The time has come my friend: Tu'u'gwar must be dealt with! I've prepped the meat so that the beast is sure to come once you bait the hook I have out in the water. Just follow the fishing line here down to it. Whatever you do, don't let Tu'u'gwar swallow you whole, $N!]],logDesc=[[Slay Tu'u'gwar and then return to Tua'kea at Moa'ki Harbor.]],choiceRewards={{id=37936,qty=1},{id=37980,qty=1},{id=38023,qty=1},{id=38084,qty=1}}}
DB[12018]={id=12018,zoneId=65,name=[[Sweet Revenge]],level=73,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12018]],image=[[assets/images/quests/placeholder.png]],desc=[[You there... you look the fighting type.  I want some sweet Revenge on the Scourge that killed my family.  Go get me 2 Stone Hunks O' Gargoyle so that I can throw them on the ground and stomp on them violently until they are mashed into itty bitty pebbly bits.  Yes. Go. Kill.]],logDesc=[[Obtain 2 Stone Hunks O' Gargoyle from Carrion Gargoyles in the Eastern Carrion Fields.  Return to Lord Bevis when the task is complete.]]}
DB[12019]={id=12019,zoneId=3537,name=[[Last Rites]],level=72,minLevel=68,giver=[[Thassarian]],giverType=[[NPC]],giverId=26170,ender=[[Thassarian]],enderType=[[NPC]],enderId=26170,prevId=11942,wowhead=[[https://www.wowhead.com/wotlk/quest=12019]],image=[[assets/images/quests/placeholder.png]],desc=[[I served Arthas in death, because I had no choice.  He had control over my will and my body.  The Cult of the Damned serves Arthas in life... willingly. Now that we know the words of power to enter Naxxanar we can put an end to the cultist blight.  Go to En'kilah and look for the teleportation orb beneath the floating citadel. Work your way up and meet me at the top.  Arm yourself with what courage you can, we might not make it out of this alive.]],logDesc=[[Go to the Temple City of En'kilah and find the teleportation orb beneath the floating Scourge citadel of Naxxanar.  Use it to reach the top and help Thassarian there.]],choiceRewards={{id=38238,qty=1},{id=38237,qty=1},{id=38240,qty=1},{id=38241,qty=1},{id=38242,qty=1},{id=38239,qty=1}}}
DB[12021]={id=12021,zoneId=65,name=[[A Letter Home]],level=73,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12021]],image=[[assets/images/quests/placeholder.png]],desc=[[This letter appears to be addressed to a resident of Stormwind from one of the late Villagers in the Carrion Fields.  Perhaps one of the surviving residents in the Eastern camp would be interested in forwarding it to its intended recipient.]],logDesc=[[Bring the letter home to Lady Alustra in the Eastern Carrion Fields.]]}
DB[12023]={id=12023,zoneId=65,name=[[Sweeter Revenge]],level=73,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12023]],image=[[assets/images/quests/placeholder.png]],desc=[[Satisfyingly crunchy.  Now... you... $R thing... there's an Abomination wandering the hillside to the south.  Go kill it.  Kill it good.]],logDesc=[[Kill the Abomination on the hillside in Eastern Carrion Fields.  Return to Lord Bevis once the slaughter is complete.]]}
DB[12024]={id=12024,zoneId=65,name=[[Recording the Fallen]],level=73,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12024]],image=[[assets/images/quests/placeholder.png]],desc=[[Thank you for coming $N.  We haven't recieved any word from Wintergarde Keep.  I'm sure they're still battling the Scourge, but I can believe they left us alone to this slaughter.   We need to gather the names of the dead so that we can notify their families.  When the Alliance Military brought us here, we all filled out Settlement Documentation and were required to keep it on our persons.   Go sift through the corpses and bring me any Documents that you find so that I can start a list of the names.]],logDesc=[[Search the skeletons in the Carrion Fields for Alliance Settlement Documents.]]}
DB[12025]={id=12025,zoneId=65,name=[[A Scarlet Among Us]],level=73,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12025]],image=[[assets/images/quests/placeholder.png]],desc=[[It's good to see that you were not ravaged by the Scourge as well.  Perhaps you'd be willing to lend a hand.   The Scarlet Crusade has taken up a post to the north with the obvious intent of battling the Scourge.  The thing that bothers me is that they were building before we were attacked - they must have known something.   I need to know if one of our Villagers was involved.  Search for evidence on those of us that were brought back as ghouls.  If you find anything, bring it to me.]],logDesc=[[Search for evidence of the Scarlet Crusade on the freshly risen Carrion Ghouls in the Eastern Carrion Fields.  Return to Lady Alustra with anything you find.]]}
DB[12026]={id=12026,zoneId=394,name=[[The Damaged Journal]],level=75,minLevel=73,giverType=[[NPC]],ender=[[Sage Paluna]],enderType=[[NPC]],enderId=26584,rewardNextId=12054,wowhead=[[https://www.wowhead.com/wotlk/quest=12026]],image=[[assets/images/quests/placeholder.png]],desc=[[This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps in the dwarven language. The only text you're able to decipher is the name of Brann Bronzebeard scrawled at the end of one of the entries. The back half of the book, containing the most recent entries, has been torn away. Someone thought the notes important enough to attempt to destroy them. Perhaps gathering the missing pages from the battlefield will yield some clues.]],logDesc=[[Recover 8 Missing Journal Pages, combine them with the Incomplete Journal, and return the completed journal to Sage Paluna at Camp Oneqwah.]]}
DB[12027]={id=12027,zoneId=394,name=[[Mr. Floppy's Perilous Adventure]],level=74,minLevel=73,giver=[[Emily]],giverType=[[NPC]],giverId=26588,ender=[[Squire Walter]],enderType=[[NPC]],enderId=26371,wowhead=[[https://www.wowhead.com/wotlk/quest=12027]],image=[[assets/images/quests/placeholder.png]],desc=[[Excuse me, $g Mister: Ma'am;, do you know the way back to the soldiers' camp? Mr. Floppy and I decided to go for a walk in the woods, and my brother Walter was gonna come with us, but then he had squire things to do. So Mr. Floppy and I went by ourselves, but we got lost, and there were a whole bunch of hungry wolves, but we found this tower. The wolves went away, but we're still lost. I asked Mr. Floppy, and he doesn't know the way back. Would you help us? Please?]],logDesc=[[Help Emily and Mr. Floppy get back to the Westfall Brigade Encampment, then speak to Squire Walter.]],choiceRewards={{id=38714,qty=1},{id=39018,qty=1},{id=39047,qty=1},{id=39079,qty=1}}}
DB[12028]={id=12028,zoneId=65,name=[[Spiritual Insight]],level=72,minLevel=71,giver=[[Toalu'u the Mystic]],giverType=[[NPC]],giverId=26595,ender=[[Toalu'u the Mystic]],enderType=[[NPC]],enderId=26595,prevId=11959,rewardNextId=12030,wowhead=[[https://www.wowhead.com/wotlk/quest=12028]],image=[[assets/images/quests/placeholder.png]],desc=[[$R, we have not heard from our people at Indu'le Village since the ground shook and was torn apart! Have you ever been upon a vision quest? You've bested Loguhn, so you must be capable. I will give you a special incense to sprinkle into my brazier. Breathe deep from its vapors and your spirit will be sent aloft to view what has transpired at Indu'le. As your spirit soars, I will be able to look through your eyes.]],logDesc=[[Speak with Toalu'u the Mystic at Moa'ki Harbor after you have attained your spiritual insight.]]}
DB[12029]={id=12029,zoneId=394,name=[[Seared Scourge]],level=74,minLevel=73,giver=[[Mack Fearsen]],giverType=[[NPC]],giverId=26604,ender=[[Mack Fearsen]],enderType=[[NPC]],enderId=26604,prevId=12484,rewardNextId=12037,wowhead=[[https://www.wowhead.com/wotlk/quest=12029]],image=[[assets/images/quests/placeholder.png]],desc=[[<Hic>... gotta burn these corpshes 'fore they shtart walkin' around again. Poppa always said, only thing worshe than havin' to kill a troll is havin' ta kill a troll twice. Say,<hic>... shpeakin' of Scourge, we can't get into tha' troll keep up north 'til we get them trolls thinned out a bit. How 'bout ya take shome o my grog here and put them bashtards outta their misery?]],logDesc=[[Mack at Granite Springs wants you to use his grog to burn 20 Famished Scourge Trolls at Drak'Tharon.]]}
DB[12030]={id=12030,zoneId=65,name=[[Elder Mana'loa]],level=72,minLevel=71,giver=[[Toalu'u the Mystic]],giverType=[[NPC]],giverId=26595,enderType=[[NPC]],prevId=12028,rewardNextId=12031,wowhead=[[https://www.wowhead.com/wotlk/quest=12030]],image=[[assets/images/quests/placeholder.png]],desc=[[My people.... <The mystic is on the verge of breaking down.> While your spirit was flying through the village, I sensed that Elder Mana'loa took notice of you. $N, he wishes to speak with you. The stone elders are revered by us as fonts of ancient wisdom. The elder must want to help. Seek him in the northwest corner of the village.]],logDesc=[[Speak with the statue, Elder Mana'loa, at Indu'le Village.]]}
DB[12031]={id=12031,zoneId=65,name=[[Freedom for the Lingering]],level=72,minLevel=71,giverType=[[NPC]],enderType=[[NPC]],prevId=12030,rewardNextId=12032,wowhead=[[https://www.wowhead.com/wotlk/quest=12031]],image=[[assets/images/quests/placeholder.png]],desc=[[The sacred ground of the elves to the west has been torn asunder. Now their magic is moving through the land causing ruin where it flows. The souls of the Kalu'ak are in danger as the blue dragons forces attempt to control the magic. The power came up through the lake, instantly slaying most in the village. Those that survived were driven insane. $N, you must release these spirits so that they may move on. Leave the deranged living alone; they may yet regain their sanity in time.]],logDesc=[[Put to rest any combination of 15 Indu'le Fishermen, Mystics and Warriors, then return to Elder Mana'loa at Indu'le Village.]]}
DB[12032]={id=12032,zoneId=65,name=[[Conversing With the Depths]],level=72,minLevel=71,giverType=[[NPC]],ender=[[Toalu'u the Mystic]],enderType=[[NPC]],enderId=26595,prevId=12031,wowhead=[[https://www.wowhead.com/wotlk/quest=12032]],image=[[assets/images/quests/placeholder.png]],desc=[[The watery goddess, Oacha'noa, must be consulted; only she will know what the destiny of the Kalu'ak is to be. And only The Pearl of the Depths can call her forth from the murky nether. Off the coast to the southwest rises The Briny Pinnacle. Atop it sits the altar upon which the pearl rests. Commune at the altar and Oacha'noa is certain to hear your call. Do as she says lest you incur her wrath and bring ruin upon all of the tuskarr. Should you survive, return to the mystic.]],logDesc=[[Commune with The Pearl of the Depths and do as the sea-goddess Oacha'noa instructs. Should you survive the ordeal, return to Toalu'u the Mystic at Moa'ki Harbor.]],choiceRewards={{id=38148,qty=1},{id=38150,qty=1},{id=38128,qty=1},{id=38127,qty=1},{id=38146,qty=1},{id=38126,qty=1}}}
DB[12033]={id=12033,zoneId=65,name=[[Message from the West]],level=72,minLevel=71,giver=[[Messenger Torvus]],giverType=[[NPC]],giverId=26649,ender=[[Messenger Torvus]],enderType=[[NPC]],enderId=26649,wowhead=[[https://www.wowhead.com/wotlk/quest=12033]],image=[[assets/images/quests/placeholder.png]],desc=[[<Torvus shakes your hand, giving you a letter in the process.> <Torvus speaks under his breath.> Just play along, $N. It is good to see you here, soldier! Lord Hellscream has undoubtedly sent his strongest warriors to Lord Agmar! <Torvus speaks under his breath.> Read it and then destroy it in the fire pot next to me.]],logDesc=[[Read the Letter from Saurfang and then destroy it. Speak to Messenger Torvus once you have completed this task.]]}
DB[12034]={id=12034,zoneId=65,name=[[Victory Nears...]],level=72,minLevel=71,giver=[[Overlord Agmar]],giverType=[[NPC]],giverId=26379,ender=[[Senior Sergeant Juktok]],enderType=[[NPC]],enderId=26415,rewardNextId=12036,wowhead=[[https://www.wowhead.com/wotlk/quest=12034]],image=[[assets/images/quests/placeholder.png]],desc=[[There remain only two primary threats that stand in our way. One is the dread citadel of Naxxramas, far to the east, above the Alliance fortress of Wintergarde and the other is the Pit of Narjun, exit point for the undead armies of Azjol'Nerub. It is from the Pit of Narjun that the Anub'ar Nerubians assaulted and ultimately razed the taunka village of Icemist. We will destroy the Anub'ar and close off the Pit of Narjun. Report to Senior Sergeant Juktok for your mission orders.]],logDesc=[[Speak to Senior Sergeant Juktok at Agmar's Hammer.]]}
DB[12035]={id=12035,zoneId=3537,name=[[Repurposed Technology]],level=71,minLevel=68,giver=[[Jeremiah Hawning]],giverType=[[NPC]],giverId=26084,ender=[[Jeremiah Hawning]],enderType=[[NPC]],enderId=26084,prevId=11908,wowhead=[[https://www.wowhead.com/wotlk/quest=12035]],image=[[assets/images/quests/placeholder.png]],desc=[[Ok, I've got it!  The rewiring is a little complicated, but nothing a clever $c like you can't handle. Take my tools and put some of the harvest collectors out of commission.  Once they're down use the tools to plug all the red wires into the blue sockets.  That'll make them go into self-defense mode.  Hurry, $N.  Before long there won't be anything left to save.]],logDesc=[[Jeremiah Hawning at Farshire wants you to destroy 5 Harvest Collectors and then use Jeremiah's Tools to rewire them.]],choiceRewards={{id=37206,qty=1},{id=37403,qty=1},{id=37417,qty=1},{id=37482,qty=1}}}
DB[12036]={id=12036,zoneId=65,name=[[From the Depths of Azjol-Nerub]],level=72,minLevel=71,giver=[[Senior Sergeant Juktok]],giverType=[[NPC]],giverId=26415,ender=[[Senior Sergeant Juktok]],enderType=[[NPC]],enderId=26415,prevId=12034,rewardNextId=12053,wowhead=[[https://www.wowhead.com/wotlk/quest=12036]],image=[[assets/images/quests/placeholder.png]],desc=[[The undead Nerubians that attacked Icemist Village came from a gigantic sinkhole known as the Pit of Narjun. If left alone, those fiends will no doubt flank our forces at the Wrathgate and end our march to victory. I need eyes on the ground, $N. You are to head west and investigate the Pit of Narjun. We need to locate their primary exit point and seal it off! Find me that location. ]],logDesc=[[Explore the Pit of Narjun and return with your findings to Senior Sergeant Juktok at Agmar's Hammer.]]}
DB[12037]={id=12037,zoneId=4196,name=[[Search and Rescue]],level=74,minLevel=72,giver=[[Mack Fearsen]],giverType=[[NPC]],giverId=26604,ender=[[Kurzel]],enderType=[[NPC]],enderId=26664,prevId=12029,rewardNextId=13129,wowhead=[[https://www.wowhead.com/wotlk/quest=12037]],image=[[assets/images/quests/placeholder.png]],desc=[[Orc women... they just don't lissen - hic. Know what I mean, $r? Kurzel's been with us fer years. You'd think she'd get a feel fer how we do things by now. Lure the fools in fer the dangerous work, then reap the rewards when it's safe. What's so hard to understand? Not her though... impatient green-skin goes off and takes matters into her own hands. Probably dead by now, but I'd feel horrible if we didn't follow after her, and I'm in no shape to do it myself - hic. So whatdya say, pal?]],logDesc=[[Mack at Granite Springs wants you to go into Drak'Tharon and find out what became of Kurzel.]],choiceRewards={{id=39649,qty=1},{id=39648,qty=1},{id=39650,qty=1}}}
DB[12038]={id=12038,zoneId=394,name=[[Seared Scourge]],level=72,minLevel=70,giver=[[Mack Fearsen]],giverType=[[NPC]],giverId=26604,ender=[[Mack Fearsen]],enderType=[[NPC]],enderId=26604,wowhead=[[https://www.wowhead.com/wotlk/quest=12038]],image=[[assets/images/quests/placeholder.png]],desc=[[Whatcha waitin' fer, $c? Them shcourged trolls ain't gunna kill themselves! You know the drill. Git up ta Drak'Tharon up north... Take some o thish here grog and hurl it at 'em from a distance...<hic>.  Then jusht sit back an' watch 'em burn.]],logDesc=[[Mack at Granite Springs wants you to use his grog to burn 30 Famished Scourge Trolls.]]}
DB[12039]={id=12039,zoneId=65,name=[[Black Blood of Yogg-Saron]],level=72,minLevel=71,giver=[[Borus Ironbender]],giverType=[[NPC]],giverId=26564,ender=[[Borus Ironbender]],enderType=[[NPC]],enderId=26564,rewardNextId=12048,wowhead=[[https://www.wowhead.com/wotlk/quest=12039]],image=[[assets/images/quests/placeholder.png]],desc=[[Angrathar, the Wrathgate... I watched as the metal holding the gate together pulsed and undulated as if it were alive! In 50 years I've never seen metal "breathe." Only ones who knew anything about it were the tuskarr. They called it the "Black Blood of Yogg-Saron" and told me to keep my distance. There's a sinkhole outside Icemist Village to the west called the Pit of Narjun. I've heard of these sinkholes being rich with this strange ore. If you head that way, could you try and get me some samples?]],logDesc=[[Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to recover 10 Black Blood of Yogg-Saron Samples.]]}
DB[12040]={id=12040,zoneId=65,name=[[An Enemy in Arthas]],level=72,minLevel=71,giver=[[Kilix the Unraveler]],giverType=[[NPC]],giverId=26653,ender=[[Kilix the Unraveler]],enderType=[[NPC]],enderId=26653,rewardNextId=12041,wowhead=[[https://www.wowhead.com/wotlk/quest=12040]],image=[[assets/images/quests/placeholder.png]],desc=[[We are in the midst of a civil war. At the heart of this world the last living members of my species defend themselves against total annihilation. The Lich King seeks to rule the kingdom of Azjol-Nerub at any cost. Those that do not acquiesce are branded enemies of the Scourge and marked for death. In Arthas we both have an enemy... Join our cause and rid this place of the taint of Anub'ar! Let Anub'arak himself hear the anguish of their death cries!]],logDesc=[[Kilix the Unraveler at the Pit of Narjun in the Dragonblight has asked that you slay 6 Anub'ar Underlords. ]]}
DB[12041]={id=12041,zoneId=65,name=[[The Lost Empire]],level=72,minLevel=71,giver=[[Kilix the Unraveler]],giverType=[[NPC]],giverId=26653,ender=[[Overlord Agmar]],enderType=[[NPC]],enderId=26379,prevId=12040,wowhead=[[https://www.wowhead.com/wotlk/quest=12041]],image=[[assets/images/quests/placeholder.png]],desc=[[You have proven that you are willing to assist the Azjol Empire in its time of need and as such the Azjol Empire will assist the Horde. Take this scroll back to your leader. It documents the strengths and weaknesses of the Nerubians attacking Icemist Village. Consider it a gesture of good faith - a willingness to help your people. Use the knowledge on those pages to crush the Anub'ar and you will have done a service for us all. Farewell, $r. ]],logDesc=[[Deliver Kilix's Battle Plan to Overlord Agmar at Agmar's Hammer to the east.]],choiceRewards={{id=37954,qty=1},{id=37996,qty=1},{id=38040,qty=1},{id=38101,qty=1}}}
DB[12042]={id=12042,zoneId=394,name=[[Heart of the Ancients]],level=74,minLevel=73,giver=[[Image of Drakuru]],giverType=[[NPC]],giverId=26543,enderType=[[NPC]],prevId=12007,rewardNextId=12802,wowhead=[[https://www.wowhead.com/wotlk/quest=12042]],image=[[assets/images/quests/placeholder.png]],desc=[[Secrets of da ages, be revealed to me now! <Drakuru peers through the Eye of the Prophets.> Ahh, great be mah destiny, $n. You be lucky ta know me.... There! I be seein' it, mon. The Heart of the Ancients. Dis be too easy! You gunna find da heart lyin' near da corpse of a goblin east of here. He be up in a chamber, near a river of broken trees. Hurry, mon, before someone else be findin' it!]],logDesc=[[Drakuru wants you to go to the uppermost chamber at Blue Sky Logging Ground and find the Heart of the Ancients.]],rewards={{id=36739,qty=1}}}
DB[12043]={id=12043,zoneId=65,name=[[Nozzlerust Defense]],level=74,minLevel=72,giver=[[Narf]],giverType=[[NPC]],giverId=26647,ender=[[Narf]],enderType=[[NPC]],enderId=26647,wowhead=[[https://www.wowhead.com/wotlk/quest=12043]],image=[[assets/images/quests/placeholder.png]],desc=[[You, $c!  These undead south of us are being a constant nuisance to our work.  Go clear them out, will ya?]],logDesc=[[Kill 12 Wastes Diggers and 1 Wastes Taskmaster at the digs surrounding Galakrond's Rest.  Return to Narf at Nozzlerust Post when the task is complete.]]}
DB[12044]={id=12044,zoneId=65,name=[[Stocking Up]],level=74,minLevel=72,giver=[[Xink]],giverType=[[NPC]],giverId=26660,ender=[[Xink]],enderType=[[NPC]],enderId=26660,prevId=12469,wowhead=[[https://www.wowhead.com/wotlk/quest=12044]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello hello!  The Scourge to the south are digging up some ancient dragon thing.  I could care less why they're doing it, but they're pulling cartloads of composite ore in the process. Go lift me a bunch of that ore.  That stuff should yield a pretty penny for all the weapons the Horde are crafting. ]],logDesc=[[Gather 8 bundles of Composite Ore from the digs surrounding Galakrond's Rest and bring them to Xink at Nozzlerust Post.]]}
DB[12045]={id=12045,zoneId=65,name=[[Shaved Ice]],level=74,minLevel=72,giver=[[Zivlix]],giverType=[[NPC]],giverId=26661,ender=[[Zivlix]],enderType=[[NPC]],enderId=26661,rewardNextId=12046,wowhead=[[https://www.wowhead.com/wotlk/quest=12045]],image=[[assets/images/quests/placeholder.png]],desc=[[I've never seen you before... are you new to the Vice?  Glad to have you.  I could always use some more hands. You get the materials, I'll finish my machine, then we can sell it to those commander types and all go home rich. I actually have most of the primary components, so I just need some of the materials for the weapon itself.  Narf said that jagged ice shards from those elementals to the north would make perfect shrapnel for my bombs - go nab some, will ya? ]],logDesc=[[Collect 4 Ice Shard Clusters from Ice Elementals in the north and bring them to Zivlix at Nozzlerust Post.]]}
DB[12046]={id=12046,zoneId=65,name=[[Soft Packaging]],level=74,minLevel=72,giver=[[Zivlix]],giverType=[[NPC]],giverId=26661,ender=[[Zivlix]],enderType=[[NPC]],enderId=26661,prevId=12045,rewardNextId=12047,wowhead=[[https://www.wowhead.com/wotlk/quest=12046]],image=[[assets/images/quests/placeholder.png]],desc=[[I need some new packaging for the shrapnel bombs.  All the stuff I have is too hard and the shrapnel doesn't spread when it bursts.   What we need is some really thin animal hide.  Those jormungar tunnelers to the west might work... or perhaps the condors sifting through the dragon bones.  Go get me whatever you can find. ]],logDesc=[[Collect 12 Thin Animal Hides from the Jormungar Tunnelers or the Dragonbone Condors near Nozzlerust Post.  Once you've located the hides, return them to Zivlix.]]}
DB[12047]={id=12047,zoneId=65,name=[[Something That Doesn't Melt]],level=74,minLevel=72,giver=[[Zivlix]],giverType=[[NPC]],giverId=26661,ender=[[Zivlix]],enderType=[[NPC]],enderId=26661,prevId=12046,wowhead=[[https://www.wowhead.com/wotlk/quest=12047]],image=[[assets/images/quests/placeholder.png]],desc=[[No no no! Those ice shards didn't work at all! They'll melt before they even do any damage. That's the last time I'll trust Narf's word on materials. This means we need something else entirely for the shrapnel. I know! I'm brilliant. Bone splinters. There are some bones all around here that the jormungar have been gnawing on pretty thoroughly. Go check them out and see if you can find me some splintered bone that I can use.]],logDesc=[[Search the dragon bones east of Nozzlerust Post for 12 Splintered Bone Chunks.]],choiceRewards={{id=37948,qty=1},{id=37991,qty=1},{id=38035,qty=1},{id=38080,qty=1},{id=38072,qty=1}}}
DB[12048]={id=12048,zoneId=65,name=[[Scourge Armaments]],level=72,minLevel=71,giver=[[Borus Ironbender]],giverType=[[NPC]],giverId=26564,ender=[[Borus Ironbender]],enderType=[[NPC]],enderId=26564,prevId=12039,wowhead=[[https://www.wowhead.com/wotlk/quest=12048]],image=[[assets/images/quests/placeholder.png]],desc=[[I can't make a damned thing out of this ore. It simply will not hold together! Despite my best efforts the Scourge metal will not bend! Perhaps if I had some samples of some forged Scourge armaments I might be able to reverse engineer the process by which the items are created. Icemist Village is crawling with armored Scourge Nerubians. Go there and get me some Scourge armaments! With your help I might actually succeed in creating something from this ore. You'll find Icemist to the west.]],logDesc=[[Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to bring him 8 Scourge Armaments.]],choiceRewards={{id=37961,qty=1},{id=38003,qty=1},{id=38045,qty=1},{id=38107,qty=1}}}
DB[12049]={id=12049,zoneId=65,name=[[Hard to Swallow]],level=74,minLevel=72,giver=[[Xink]],giverType=[[NPC]],giverId=26660,ender=[[Xink]],enderType=[[NPC]],enderId=26660,wowhead=[[https://www.wowhead.com/wotlk/quest=12049]],image=[[assets/images/quests/placeholder.png]],desc=[[Those troops are sure to be needin' a hefty supply of food in their bellies. I'll let you in on a little secret that a squeamish $r like you would never know... those jormungar worms taste just like chicken. Go provoke one of those giant hulking jormungar to the east.  You're not likely to be able to kill one straight out, so just toss this down its throat when it opens its mouth wide.  Bring me back as many of the slabs of meat as you can tote.]],logDesc=[[Battle a Hulking Jormungar east of Nozzlerust Post until it opens its mouth, then throw a Potent Explosive Charge into its throat. After it explodes, collect 6 slabs of Seared Jormungar Meat off of the ground and bring them back to Xink.]]}
DB[12050]={id=12050,zoneId=65,name=[[Lumber Hack]],level=74,minLevel=72,giver=[[Xink]],giverType=[[NPC]],giverId=26660,ender=[[Xink]],enderType=[[NPC]],enderId=26660,wowhead=[[https://www.wowhead.com/wotlk/quest=12050]],image=[[assets/images/quests/placeholder.png]],desc=[[Next up, we need to haul in some lumber for all the towers the Alliance are building.  There are some thin trees to the south, but the trees the Harpies are nesting in to the north look much more fit for structures. Take this.  When you get to the Harpy nesting area, use the control and one of my Shredders should come to you.  Gather as much lumber as it can carry.  The Harpies are sure to disagree with you chopping down their homes - just deal with them as necessary. Hop to it!]],logDesc=[[Use Xink's Shredder Control Device to call a Shredder once you reach the Harpy Nesting Grounds in the North.  Gather 50 Bundles of Lumber from the trees in the area, and then return to Xink at Nozzlerust Post. Should you lose Xink's Shredder Control Device, speak to Xink at Nozzlerust Post to obtain a new one.]],choiceRewards={{id=38197,qty=1},{id=38141,qty=1},{id=38143,qty=1},{id=38191,qty=1},{id=38187,qty=1},{id=38142,qty=1}}}
DB[12051]={id=12051,zoneId=65,name=[[Rustling Some Feathers]],level=74,minLevel=72,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12051]],image=[[assets/images/quests/placeholder.png]],desc=[[Those harpies have slowed our profits long enough!  Kill them all.]],logDesc=[[Kill 20 Harpies Northwest of Nozzlerust Post for Narf at Nozzlerust Post.]]}
DB[12052]={id=12052,zoneId=65,name=[[Harp on This!]],level=74,minLevel=72,giver=[[Narf]],giverType=[[NPC]],giverId=26647,ender=[[Narf]],enderType=[[NPC]],enderId=26647,wowhead=[[https://www.wowhead.com/wotlk/quest=12052]],image=[[assets/images/quests/placeholder.png]],desc=[[$C, did you see that? That's the harpy that's been leading the attack on our shipments to the gate! I've seen her in the back of Coldwind Heights before.  Those harpies have slowed our profits long enough! Kill them all.]],logDesc=[[Kill the Mistress of the Coldwind and 15 Coldwind harpies in the mountains northwest of Nozzlerust Post. Return to Narf once the task is complete. Should you be in need of Xink's Shredder Control Device, speak to Xink at Nozzlerust Post.]],choiceRewards={{id=37947,qty=1},{id=37990,qty=1},{id=38034,qty=1},{id=38097,qty=1}}}
DB[12053]={id=12053,zoneId=65,name=[[The Might of the Horde]],level=72,minLevel=71,giver=[[Senior Sergeant Juktok]],giverType=[[NPC]],giverId=26415,ender=[[Senior Sergeant Juktok]],enderType=[[NPC]],enderId=26415,prevId=12036,rewardNextId=12071,wowhead=[[https://www.wowhead.com/wotlk/quest=12053]],image=[[assets/images/quests/placeholder.png]],desc=[[The taunka are now our brothers in arms. We must show our solidarity and retake Icemist Village. You will find Icemist Village west of Agmar's Hammer, sitting at the foot of the mountains. Travel there and challenge the Anub'ar Nerubians! Plant our beloved Horde banner at Icemist Village and destroy all that dare come to tear it down! Let the Anub'ar feel the true might of the Horde! Let our battle standard be the last thing that they see before death!]],logDesc=[[Senior Sergeant Juktok at Agmar's Hammer in the Dragonblight wants you to use the Warsong Battle Standard at Icemist Village and defend it against attackers. Return the Warsong Battle Standard when you are finished.]],choiceRewards={{id=37956,qty=1},{id=37998,qty=1},{id=38041,qty=1},{id=38102,qty=1}}}
DB[12054]={id=12054,zoneId=394,name=[[Deciphering the Journal]],level=75,minLevel=73,giver=[[Sage Paluna]],giverType=[[NPC]],giverId=26584,ender=[[Sage Paluna]],enderType=[[NPC]],enderId=26584,prevId=12026,wowhead=[[https://www.wowhead.com/wotlk/quest=12054]],image=[[assets/images/quests/placeholder.png]],desc=[[Vor'takh is right -- we cannot allow this opportunity to slip through our fingers. Fortunately, I think I know of a way to translate the journal of this Brann. The shamans of the Redfang furbolgs, who congregate at the Heart's Blood Shrine south of the camp, grow an herb known as spiritsbreath. An experienced mystic can use incense made from it to seek wisdom from the spirits of the ancestors. Seek out the shaman known as Grumbald One-Eye. He should carry the herb for his devotions to Ursoc.]],logDesc=[[Bring a sprig of Spiritsbreath to Sage Paluna at Camp Oneqwah.]]}
DB[12055]={id=12055,zoneId=65,name=[[A Strange Device]],level=72,minLevel=71,giverType=[[NPC]],ender=[[Image of Archmage Modera]],enderType=[[NPC]],enderId=26673,rewardNextId=12060,wowhead=[[https://www.wowhead.com/wotlk/quest=12055]],image=[[assets/images/quests/placeholder.png]],desc=[[Picking up this strange device, you are certain that it is magical in nature. Unfortunately, it doesn't seem to connote any other kind of use. Perhaps the archmage back at Stars' Rest to the east of the Moonrest Gardens would be able to tell what it's used for?]],logDesc=[[Deliver Goramosh's Strange Device to the Image of Archmage Modera at Stars' Rest.]]}
DB[12056]={id=12056,zoneId=65,name=[[Marked for Death: High Cultist Zangus]],level=72,minLevel=71,giver=[[Captain Gort]],giverType=[[NPC]],giverId=26618,ender=[[Captain Gort]],enderType=[[NPC]],enderId=26618,wowhead=[[https://www.wowhead.com/wotlk/quest=12056]],image=[[assets/images/quests/placeholder.png]],desc=[[I witnessed his treachery with my own eyes! The traitor led an Anub'ar assault on this stronghold, taking out some of my best soldiers. <Gort shakes his head.> He'd been working with the Scourge the whole time and we didn't have a clue! How many more like Zangus are there? We'll find 'em all and when we do... <Gort makes a cutting motion across his neck.> First on the list is Zangus. Our scouts report that he is hiding in The Pit of Narjun, west of here. Find him, kill him, bring me his head. ]],logDesc=[[Kill High Cultist Zangus and return High Cultist Zangus's Head to Captain Gort at Agmar's Hammer in the Dragonblight.]]}
DB[12057]={id=12057,zoneId=65,name=[[The Flesh-Bound Tome]],level=72,minLevel=71,giverType=[[NPC]],ender=[[Captain Gort]],enderType=[[NPC]],enderId=26618,rewardNextId=12115,wowhead=[[https://www.wowhead.com/wotlk/quest=12057]],image=[[assets/images/quests/placeholder.png]],desc=[[The tome is bound in flesh and appears to be bleeding. Upon examination you discover page after page filled with strange symbols that appear to be written in blood. Whatever knowledge is held within the pages of this tome could be important. Return it to Captain Gort at Agmar's Hammer, east of Icemist Village.]],logDesc=[[Return the Flesh-bound Tome to Captain Gort at Agmar's Hammer.]]}
DB[12058]={id=12058,zoneId=394,name=[[The Runic Prophecies]],level=75,minLevel=73,giver=[[Sage Paluna]],giverType=[[NPC]],giverId=26584,ender=[[Sage Paluna]],enderType=[[NPC]],enderId=26584,prevId=12054,nextId=12204,rewardNextId=12204,exGroup=-12058,wowhead=[[https://www.wowhead.com/wotlk/quest=12058]],image=[[assets/images/quests/placeholder.png]],desc=[[Brann's journal also contained a guide to iron dwarf symbols. I've inscribed these on a keystone which will help you to understand the words inscribed on the rune plates. From the journal entries, it seems Brann may be chasing after clues to the origins of his people. Keep your eyes open for any clues as to his destination. Return to Thor Modan, northeast of here, stand before each of the plates, and use the stone to determine the contents of each. We can't allow the Alliance to find him first.]],logDesc=[[Sage Paluna at Camp Oneqwah wants you to decipher the three Rune Plates.]],choiceRewards={{id=38710,qty=1},{id=39013,qty=1},{id=39043,qty=1},{id=39075,qty=1}}}
DB[12059]={id=12059,zoneId=65,name=[[A Strange Device]],level=72,minLevel=71,giverType=[[NPC]],ender=[[Image of Archmage Aethas Sunreaver]],enderType=[[NPC]],enderId=26471,rewardNextId=12061,wowhead=[[https://www.wowhead.com/wotlk/quest=12059]],image=[[assets/images/quests/placeholder.png]],desc=[[Picking up this strange device, you are certain that it is magical in nature. Unfortunately, it doesn't seem to connote any other kind of use. Perhaps the archmage back at Agmar's Hammer to the northeast of the Moonrest Gardens would be able to tell what it's used for?]],logDesc=[[Deliver Goramosh's Strange Device to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.]]}
DB[12060]={id=12060,zoneId=65,name=[[Projections and Plans]],level=72,minLevel=71,giver=[[Image of Archmage Modera]],giverType=[[NPC]],giverId=26673,ender=[[Image of Archmage Modera]],enderType=[[NPC]],enderId=26673,prevId=12055,rewardNextId=12065,wowhead=[[https://www.wowhead.com/wotlk/quest=12060]],image=[[assets/images/quests/placeholder.png]],desc=[[This is a teleportation device. If I had to guess, I'd say that it leads to the surge needle platform floating above the Moonrest Gardens to the west. I need you to use it to investigate what's up there. It appears that the device works both ways so you shouldn't have to jump off. I expect that once you teleport to the top of the surge needle, there will be some sort of apparatus on it to observe. You should be able to use the teleporter from anywhere within the gardens.]],logDesc=[[Get close to and observe the projection atop the Surge Needle floating above Moonrest Gardens. Afterward, return to the Image of Archmage Modera at Stars' Rest with the information.]]}
DB[12061]={id=12061,zoneId=65,name=[[Projections and Plans]],level=72,minLevel=71,giver=[[Image of Archmage Aethas Sunreaver]],giverType=[[NPC]],giverId=26471,ender=[[Image of Archmage Aethas Sunreaver]],enderType=[[NPC]],enderId=26471,prevId=12059,rewardNextId=12066,wowhead=[[https://www.wowhead.com/wotlk/quest=12061]],image=[[assets/images/quests/placeholder.png]],desc=[[This is a teleportation device. If I had to guess, I'd say that it leads to the surge needle platform floating above the Moonrest Gardens to the southwest. $N, I need you to use it to investigate what's up there. It appears that the device works both ways so you shouldn't have to jump off. I expect that once you teleport up to the top of the surge needle, there will be some sort of apparatus on it to observe. You should be able to use the teleporter from anywhere within the gardens.]],logDesc=[[Get close to and observe the projection atop the Surge Needle floating above Moonrest Gardens. Afterward, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer with the information.]]}
DB[12063]={id=12063,zoneId=65,name=[[Strength of Icemist]],level=72,minLevel=71,giver=[[Greatmother Icemist]],giverType=[[NPC]],giverId=26652,ender=[[Banthok Icemist]],enderType=[[NPC]],enderId=26733,prevId=12036,rewardNextId=12064,wowhead=[[https://www.wowhead.com/wotlk/quest=12063]],image=[[assets/images/quests/placeholder.png]],desc=[[<Greatmother Icemist bows.> It is an honor to meet you, hero. It is because of your actions that many of us are here now, alive and ready for battle against the Scourge. You have done so much for us that it shames me to ask you for your assistance once more. Despite my pleas, my only son, Banthok, left here to go in search of his father, High Chief Icemist. He was last seen heading west, towards Icemist Village. Please find Banthok. I do not know what I would do if I lost my son.]],logDesc=[[Find Banthok Icemist at Icemist Village.]]}
DB[12064]={id=12064,zoneId=65,name=[[Chains of the Anub'ar]],level=72,minLevel=71,giver=[[Banthok Icemist]],giverType=[[NPC]],giverId=26733,ender=[[Banthok Icemist]],enderType=[[NPC]],enderId=26733,prevId=12063,rewardNextId=12069,wowhead=[[https://www.wowhead.com/wotlk/quest=12064]],image=[[assets/images/quests/placeholder.png]],desc=[[They have my father bound by magical chains in the middle of Icemist Village. From what I have been able to gather, the prison is controlled by three powerful Anub'ar magi - each holding a piece of the key. Scour Icemist and locate the magi. Kill them and take their key fragments. With all three pieces we might be able to free my father. Once he is free... Retribution will come swiftly.]],logDesc=[[Banthok Icemist at Icemist Village in the Dragonblight has asked that you bring him Anok'ra's Key Fragment, Tivax's Key Fragment and Sinok's Key Fragment. ]],choiceRewards={{id=37959,qty=1},{id=38001,qty=1},{id=38044,qty=1},{id=38105,qty=1}}}
DB[12065]={id=12065,zoneId=65,name=[[The Focus on the Beach]],level=72,minLevel=71,giver=[[Image of Archmage Modera]],giverType=[[NPC]],giverId=26673,ender=[[Image of Archmage Modera]],enderType=[[NPC]],enderId=26673,prevId=12060,rewardNextId=12083,wowhead=[[https://www.wowhead.com/wotlk/quest=12065]],image=[[assets/images/quests/placeholder.png]],desc=[[The mage hunter forces are active on the Glittering Strand to the south of Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and a captain who is in charge of it. No doubt the captain will have some sort of controlling device on their person. Get the controller and use it on the focus. With any luck, we'll be able to get some more information about what they're really up to out there.]],logDesc=[[Obtain the Ley Line Focus Control Ring and use it to gain information from the Ley Line Focus on the Glittering Strand. Then, return to the Image of Archmage Modera at Stars' Rest.]]}
DB[12066]={id=12066,zoneId=65,name=[[The Focus on the Beach]],level=72,minLevel=71,giver=[[Image of Archmage Aethas Sunreaver]],giverType=[[NPC]],giverId=26471,ender=[[Image of Archmage Aethas Sunreaver]],enderType=[[NPC]],enderId=26471,prevId=12061,rewardNextId=12084,wowhead=[[https://www.wowhead.com/wotlk/quest=12066]],image=[[assets/images/quests/placeholder.png]],desc=[[The mage hunter forces are active on the Glittering Strand to the south of Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and a captain who is in charge of it. No doubt the captain of the force down there will have some sort of controlling device on their person. Get the controller and use it on the focus. With any skill on your part, we'll be able to get some more information about what they're really up to out there.]],logDesc=[[Obtain the Ley Line Focus Control Ring and use it to gain information from the Ley Line Focus on the Glittering Strand. Then, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.]]}
DB[12067]={id=12067,zoneId=65,name=[[A Letter for Home]],level=72,minLevel=71,giverType=[[NPC]],ender=[[Commander Saia Azuresteel]],enderType=[[NPC]],enderId=26459,wowhead=[[https://www.wowhead.com/wotlk/quest=12067]],image=[[assets/images/quests/placeholder.png]],desc=[[You find a letter secreted in the lining of her robes. It reads: "Father, I'm sorry for disappearing on you. If you're reading this letter, then I'm dead. I've been forced to work for Malygos's armies under threat that our family would be killed if I didn't. I feel so ashamed. If there's anything that you can do to fight them, don't worry about me. I have them fooled and I'm sabotaging them from the inside. I love you, Daddy! Em" Commander Saia Azuresteel will want to see this!]],logDesc=[[Deliver Captain Malin's Letter to Commander Saia Azuresteel at Stars' Rest.]]}
DB[12068]={id=12068,zoneId=394,name=[[Voices From the Dust]],level=75,minLevel=73,giver=[[Image of Drakuru]],giverType=[[NPC]],giverId=26701,ender=[[Image of Drakuru]],enderType=[[NPC]],enderId=26787,prevId=12802,rewardNextId=12238,wowhead=[[https://www.wowhead.com/wotlk/quest=12068]],image=[[assets/images/quests/placeholder.png]],desc=[[<Drakuru places the Eye of the Prophets on his brow and the Heart of the Ancients on his chest.> We be close, mon, very close! The Drakkari Tablets be all dat remain ta be found. Nobody be knowin' how old dey be or what dey be sayin', but with the eye and the heart Drakuru can be readin' dem. Dey lie deep inside the crypt at Drakil'jin, due east of here. Once ya got the tablets, get sacred mojo from the oracles and protectors so ya can summon me there. They'd be proud to be dyin' for such a cause.]],logDesc=[[Drakuru wants you to collect the Drakkari Tablets from the Ruins of Drakil'jin and 5 Sacred Mojo from Drakkari Oracles and Protectors there. You are then to use Drakuru's Elixir at Drakuru's Brazier at the ruins to summon his image.]],choiceRewards={{id=38718,qty=1},{id=39022,qty=1},{id=39051,qty=1},{id=39089,qty=1},{id=38751,qty=1}}}
DB[12069]={id=12069,zoneId=65,name=[[Return of the High Chief]],level=73,minLevel=71,giver=[[Banthok Icemist]],giverType=[[NPC]],giverId=26733,ender=[[Overlord Agmar]],enderType=[[NPC]],enderId=26379,prevId=12064,rewardNextId=12140,wowhead=[[https://www.wowhead.com/wotlk/quest=12069]],image=[[assets/images/quests/placeholder.png]],desc=[[<Banthok hands you the prison key.> You must hurry, $N. Take the key and use it to unchain my father from the Anub'ar prison. Once he is freed, assist him in destroying the Anub'ar leader, Under-king Anub'et'kan. When the Under-king is defeated, take from his chitinous carapace a fragment as a trophy to present to the Horde at Agmar's Hammer. Let Agmar see the might of the High Chief!]],logDesc=[[Free High Chief Icemist using the Anub'ar Prison Key and assist him in defeating Under-king Anub'et'kan. Recover a Fragment of Anub'et'kan's Husk and return it to Overlord Agmar at Agmar's Hammer in the Dragonblight.]]}
DB[12070]={id=12070,zoneId=394,name=[[Rallying the Troops]],level=75,minLevel=72,giver=[[Kurun]],giverType=[[NPC]],giverId=26260,ender=[[Kurun]],enderType=[[NPC]],enderId=26260,prevId=11982,rewardNextId=11985,wowhead=[[https://www.wowhead.com/wotlk/quest=12070]],image=[[assets/images/quests/placeholder.png]],desc=[[The sons of iron have used their runes to enthrall many of my brothers and are using them to break the siege on Thor Modan. I wish we did not have to fight them, but we have no choice. My giants will not hold out long against them. I have imbued this earthen shard with a blessing that will aid our allies. Take it with you to the battle in the Boulder Hills to the north, and use it to reassure and fortify my brethren. Kill any iron dwarves who would stand in your way.]],logDesc=[[Use the Shard of the Earth to rally the Grizzly Hills Giants fighting in the Boulder Hills, kill any iron dwarves who oppose you, then report to Kurun on the hill overlooking Thor Modan.]]}
DB[12071]={id=12071,zoneId=65,name=[[Attack by Air!]],level=72,minLevel=71,giver=[[Senior Sergeant Juktok]],giverType=[[NPC]],giverId=26415,ender=[[Valnok Windrager]],enderType=[[NPC]],enderId=26574,prevId=12053,rewardNextId=12072,wowhead=[[https://www.wowhead.com/wotlk/quest=12071]],image=[[assets/images/quests/placeholder.png]],desc=[[They have seen the might of the Horde by land, now they must feel it from the air! I want you to report to Valnok Windrager at once! You will find him here, in Agmar's Hammer. Valnok has already been briefed on your mission and is expecting you. ]],logDesc=[[Speak with Valnok Windrager at Agmar's Hammer.]]}
DB[12072]={id=12072,zoneId=65,name=[[Blightbeasts be Damned!]],level=72,minLevel=71,giver=[[Valnok Windrager]],giverType=[[NPC]],giverId=26574,ender=[[Valnok Windrager]],enderType=[[NPC]],enderId=26574,prevId=12071,wowhead=[[https://www.wowhead.com/wotlk/quest=12072]],image=[[assets/images/quests/placeholder.png]],desc=[[You've no doubt seen the army of Anub'ar blightbeasts that are being constructed at Icemist Village. The Anub'ar have plans to send those monsters against our soldiers at the Wrathgate. This cannot happen! Venture west to Icemist Village with this flare gun and use it to call down one of my war riders. Climb on its back and command it to destroy the blightbeasts that are out of reach from the ground! Once you have decimated their aerial forces, return to me for your reward!]],logDesc=[[Use Valnok's Flare Gun to call down a Kor'kron War Rider at Icemist Village. Mount the Kor'kron War Rider and then use it to kill 25 Anub'ar Blightbeasts! Return to Valnok Windrager at Agmar's Hammer should you complete this mission.]],choiceRewards={{id=37957,qty=1},{id=37999,qty=1},{id=38042,qty=1},{id=38103,qty=1}}}
DB[12073]={id=12073,zoneId=394,name=[[Pounding the Iron]],level=75,minLevel=73,giver=[[Scout Vor'takh]],giverType=[[NPC]],giverId=26666,ender=[[Scout Vor'takh]],enderType=[[NPC]],enderId=26666,prevId=12054,nextId=12204,rewardNextId=12204,exGroup=-12058,wowhead=[[https://www.wowhead.com/wotlk/quest=12073]],image=[[assets/images/quests/placeholder.png]],desc=[[The Alliance isn't the only force opposing us in Grizzly Hills. The iron dwarves have firm control of the eastern coast, although Thor Modan, to the northeast, is besieged by stone giants. A skilled warrior uses an enemy's weakness against him and we would be fools to ignore the vulnerability of the iron dwarves at Thor Modan. Show the iron dwarves no mercy. Slay any and all who would stand in your way. The 'sons of iron' will learn to fear the Horde.]],logDesc=[[Kill any 10 Iron Dwarves defending Thor Modan and report back to Scout Vor'takh at Camp Oneqwah.]]}
DB[12074]={id=12074,zoneId=394,name=[[An Expedient Ally]],level=75,minLevel=73,giver=[[Scout Vor'takh]],giverType=[[NPC]],giverId=26666,ender=[[Kurun]],enderType=[[NPC]],enderId=26260,nextId=11982,rewardNextId=11982,exGroup=11981,wowhead=[[https://www.wowhead.com/wotlk/quest=12074]],image=[[assets/images/quests/placeholder.png]],desc=[[The old iron dwarf capital of Thor Modan, far to the northeast, is under siege by a mysterious band of stone giants and earthen. Why the creations of the titans would war against each other is beyond my understanding and the Horde's interest, but there is an opportunity here to weaken a mutual enemy. Travel to Thor Modan and seek out this 'Kurun' who commands the giants and earthen. Make common cause with him and use his forces to crush the iron dwarves.]],logDesc=[[Speak with Kurun on the hill overlooking Thor Modan.]]}
DB[12075]={id=12075,zoneId=65,name=[[Slim Pickings]],level=74,minLevel=72,giver=[[Zort]],giverType=[[NPC]],giverId=26659,ender=[[Zort]],enderType=[[NPC]],enderId=26659,prevId=12112,rewardNextId=12076,wowhead=[[https://www.wowhead.com/wotlk/quest=12075]],image=[[assets/images/quests/placeholder.png]],desc=[[Cold out here, isn't it, $r? Ko'char has refused to meet with me. It seems he has more pressing things on his mind - namely, the jormungar that have been attacking them from the cavern below. Maybe you can help me convince Ko'char that I'm one of the good guys. I saw a giant being eaten by some of the worms at the entrance to the cavern north of here... I'm still puzzled as to how the worms are killing them so easily. Bring me a sample from one of his wounds.]],logDesc=[[Collect a sample of Rockflesh from the Ice Giant corpse at the cavern entrance in the Crystal Vice, north of Zort's location. After this task is complete, return to Zort near the center of the canyon.]]}
DB[12076]={id=12076,zoneId=65,name=[[Messy Business]],level=74,minLevel=72,giver=[[Zort]],giverType=[[NPC]],giverId=26659,ender=[[Zort]],enderType=[[NPC]],enderId=26659,prevId=12075,rewardNextId=12077,wowhead=[[https://www.wowhead.com/wotlk/quest=12076]],image=[[assets/images/quests/placeholder.png]],desc=[[Even at first glance, the sample you brought me shows obvious signs of some kind of corrosive spit. It would be a natural assumption that the same substance these worms use to burrow through the ground has allowed them a formidable weapon against the Ice Giants. Take this scraper and pick a fight with some of the worms. When they spit on you, use the scraper to remove it and bring it back to me. Get me a couple samples - I'm going to have to use it as the base for an elixir.]],logDesc=[[Collect 2 Vials of Corrosive Spit from the Jormungar by using the scraper on yourself.  Bring the vials back to Zort in the Crystal Vice when your task is complete.]]}
DB[12077]={id=12077,zoneId=65,name=[[Apply This Twice A Day]],level=74,minLevel=72,giver=[[Zort]],giverType=[[NPC]],giverId=26659,ender=[[Ko'char the Unbreakable]],enderType=[[NPC]],enderId=26473,prevId=12076,wowhead=[[https://www.wowhead.com/wotlk/quest=12077]],image=[[assets/images/quests/placeholder.png]],desc=[[This elixir should protect against their spit. Offer it to Ko'char for me, will you? Tell him there's plenty more where that came from if he'll return the favor.]],logDesc=[[Offer the elixir that Zort has prepared to Ko'char the Unbreakable.]],rewards={{id=36770,qty=1}}}
DB[12078]={id=12078,zoneId=65,name=[[Worm Wrangler]],level=74,minLevel=72,giver=[[Zort]],giverType=[[NPC]],giverId=26659,ender=[[Zort]],enderType=[[NPC]],enderId=26659,wowhead=[[https://www.wowhead.com/wotlk/quest=12078]],image=[[assets/images/quests/placeholder.png]],desc=[[So be it. If the giants will not come to our aid, perhaps we can make use of these worms. There are sure to be some spawn with their brood mother in the cavern below. Take this box and capture 3 of their spawn and bring them to me. Where diplomacy fails, enslaving is a perfectly viable alternative.]],logDesc=[[Enter the caverns in Crystal Vice and trap 3 Jormungar Spawn inside sturdy crates.  Be sure to pick the crates up after the Jormungar Spawn are trapped inside! Bring the captured Jormungar Spawn back to Zort in the Crystal Vice.]]}
DB[12079]={id=12079,zoneId=65,name=[[Stomping Grounds]],level=74,minLevel=72,giver=[[Ko'char the Unbreakable]],giverType=[[NPC]],giverId=26473,ender=[[Ko'char the Unbreakable]],enderType=[[NPC]],enderId=26473,wowhead=[[https://www.wowhead.com/wotlk/quest=12079]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings little one.  I know not what madness has brought you to the Crystal Vice, but you are welcome in my presence.   These ice worms... these jormungar have taken a taste to eating my brothers.  I doubt you will find my kind friendly by any terms during this time of battle, but if you are here to help with the worms, then you have my ear. If we are to take the cavern back, we must first clear the canyon of these jormungar feeders.  Join us in battle, $r!]],logDesc=[[Delve into the cavern at the north end of the Crystal Vice and kill 8 Ice Heart Jormungar Feeders for Ko'char the Unbreakable.]]}
DB[12080]={id=12080,zoneId=65,name=[[Really Big Worm]],level=74,minLevel=72,giver=[[Ko'char the Unbreakable]],giverType=[[NPC]],giverId=26473,ender=[[Ko'char the Unbreakable]],enderType=[[NPC]],enderId=26473,wowhead=[[https://www.wowhead.com/wotlk/quest=12080]],image=[[assets/images/quests/placeholder.png]],desc=[[The jormungar have a spawnmother in the caverns below. We call her Rattlebore - a name that was gifted to her by an adventurer from the Plaguelands. I saw her only briefly as I was fighting off their initial onslaught - she is large enough to make even my icy bones shiver. This cavern will not be ours until she is removed from it. Gather your friends and end this.]],logDesc=[[Enter the Ice Heart Cavern and slay Rattlebore.  If it is still in your possession, be sure to use Zort's Protective Elixir to protect you from the Jormungar's corrosive spit. Return to Ko'char the Unbreakable in the Crystal Vice when the task is complete.]],choiceRewards={{id=37945,qty=1},{id=37989,qty=1},{id=38033,qty=1},{id=38096,qty=1}}}
DB[12081]={id=12081,zoneId=394,name=[[Gavrock]],level=75,minLevel=72,giver=[[Kurun]],giverType=[[NPC]],giverId=26260,ender=[[Gavrock]],enderType=[[NPC]],enderId=26420,prevId=11985,rewardNextId=12093,wowhead=[[https://www.wowhead.com/wotlk/quest=12081]],image=[[assets/images/quests/placeholder.png]],desc=[[Without your help, we wouldn't have been able to turn the tide of the battle for Thor Modan. This ancient city has long been a battlefield between the forces of earth and stone. I can only hope we have silenced it for the last time. The iron dwarves can still use their magic to capture and enslave my brothers. Gavrock is searching for a way to free the runed giants. Look for him on a small cluster of islands, called the Ruins of Tethys, off the central part of the Eastwind Shore to the south.]],logDesc=[[Speak with Gavrock at the Ruins of Tethys.]]}
DB[12082]={id=12082,zoneId=394,name=[[Dun-da-Dun-tah!]],level=75,minLevel=73,giver=[[Harrison Jones]],giverType=[[NPC]],giverId=26814,ender=[[Harkor]],enderType=[[NPC]],enderId=26884,wowhead=[[https://www.wowhead.com/wotlk/quest=12082]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen, kid. This is no place for you to be playin' around. I'm about to make a break for it. Stick with me and I'll get you outta here.]],logDesc=[[Escort Harrison from Drakil'jin Ruins, then speak with Harkor at Harkor's Camp.]],choiceRewards={{id=38729,qty=1},{id=39028,qty=1},{id=39056,qty=1},{id=39094,qty=1}}}
DB[12083]={id=12083,zoneId=65,name=[[Atop the Woodlands]],level=72,minLevel=71,giver=[[Image of Archmage Modera]],giverType=[[NPC]],giverId=26673,ender=[[Image of Archmage Modera]],enderType=[[NPC]],enderId=26673,prevId=12065,rewardNextId=12098,wowhead=[[https://www.wowhead.com/wotlk/quest=12083]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm convinced that there must be more of those foci, each of them in-turn redirecting the ley line energies. We still don't know precisely what they're doing with all of that power, though. My guess is that you'll find another one atop the Lothalor Woodlands to the southeast. Once again you'll need to find the person in charge and take whatever controlling device they have in their possession as I'm sure that each focus has its own. Be careful, $N, those woods are very dangerous.]],logDesc=[[Obtain the Ley Line Focus Control Amulet and use it to gain information from the Ley Line Focus in the Lothalor Woodlands. Then, return to the Image of Archmage Modera at Stars' Rest.]],choiceRewards={{id=37942,qty=1},{id=37985,qty=1},{id=38029,qty=1},{id=38093,qty=1}}}
DB[12084]={id=12084,zoneId=65,name=[[Atop the Woodlands]],level=72,minLevel=71,giver=[[Image of Archmage Aethas Sunreaver]],giverType=[[NPC]],giverId=26471,ender=[[Image of Archmage Aethas Sunreaver]],enderType=[[NPC]],enderId=26471,prevId=12066,rewardNextId=12106,wowhead=[[https://www.wowhead.com/wotlk/quest=12084]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm convinced that there must be more of those foci, each of them in-turn redirecting the ley line energies. We still don't know precisely what they're doing with all of that power, though. My guess is that you'll find another one atop the Lothalor Woodlands to the south. Once again you'll need to find the person in charge and take whatever controlling device they have in their possession as I'm sure that each focus has its own. Be quick about your business, $c. I feel that time may be running out.]],logDesc=[[Obtain the Ley Line Focus Control Amulet and use it to gain information from the Ley Line Focus in the Lothalor Woodlands. Then, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.]],choiceRewards={{id=37942,qty=1},{id=37985,qty=1},{id=38029,qty=1},{id=38093,qty=1}}}
DB[12085]={id=12085,zoneId=65,name=[[A Letter for Home]],level=72,minLevel=71,giverType=[[NPC]],ender=[[Overlord Agmar]],enderType=[[NPC]],enderId=26379,wowhead=[[https://www.wowhead.com/wotlk/quest=12085]],image=[[assets/images/quests/placeholder.png]],desc=[[You find a letter secreted in the lining of his robes. It reads: "Deino, Ta'zinni sorry for disappearing on ya. If you're reading this letter, then I be dead. I been forced to work for Malygos's armies under threat that the family would be killed if I didn't. Ta'zinni wasn't gonna let that happen! Don't worry about me, just keep your kids safe. I have them fooled and I'm sabotaging them from the inside. I love you, sistah! Ta'zinni" Overlord Agmar is sure to want to see this!]],logDesc=[[Deliver Lieutenant Ta'zinni's Letter to Overlord Agmar at Agmar's Hammer.]]}
DB[12086]={id=12086,zoneId=3537,name=[[The Son of Karkut]],level=72,minLevel=68,giver=[[Ataika]],giverType=[[NPC]],giverId=26169,ender=[[Corporal Venn]],enderType=[[NPC]],enderId=26187,prevId=11932,rewardNextId=11944,wowhead=[[https://www.wowhead.com/wotlk/quest=12086]],image=[[assets/images/quests/placeholder.png]],desc=[[The man you seek went far to the east, to a place near the coast called Death's Stand, beyond Unu'pe. Be careful if you go in search of him, $N.  He bore the mark of Karkut... he who watches over the dead.]],logDesc=[[Go east to Death's Stand, just beyond Unu'pe.]]}
DB[12087]={id=12087,zoneId=3537,name=[[A Little Help Here? DEPRECATED]],level=72,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12087]],image=[[assets/images/quests/placeholder.png]],desc=[[We were sent here to take over the Howling Ziggurat, due north.  We weren't expecting to make it back alive.... hell, we already lost half our crew. Tassarian was on point and the higher ups... well, they didn't like something about him. He took off this morning... he might've gone to the ziggurat on his own.  But right now we have more pressing matters to worry about.  The Scourge keeps getting closer and closer to the camp, we need to take care of them -- now!]],logDesc=[[Corporal Venn at Death's Stand wants you to kill 8 Ziggurat Defenders.]]}
DB[12088]={id=12088,zoneId=3537,name=[[Thassarian, the Death Knight]],level=72,minLevel=68,giver=[[Corporal Venn]],giverType=[[NPC]],giverId=26187,ender=[[Thassarian]],enderType=[[NPC]],enderId=26170,prevId=11944,wowhead=[[https://www.wowhead.com/wotlk/quest=12088]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, $N, you helped us out... so I figure it's only fair that we help you out as well. You're looking for Thassarian?  He disappeared this morning.  We think he went off north to the Wailing Ziggurat.  If we hadn't fought side by side by him we'd even think he was a traitor. See, he's a Death Knight... and I know they're on our side and all... but it wasn't too long ago they were servants of Arthas. But not Thassarian, he's a good guy.  Go to the Wailing Ziggurat, see if he's doing okay.]],logDesc=[[Look for Thassarian inside the Wailing Ziggurat, north of Death's Stand.]]}
DB[12089]={id=12089,zoneId=65,name=[[Wanted: Magister Keldonus]],level=74,minLevel=71,giverType=[[NPC]],ender=[[Captain Gort]],enderType=[[NPC]],enderId=26618,wowhead=[[https://www.wowhead.com/wotlk/quest=12089]],image=[[assets/images/quests/placeholder.png]],desc=[[By decree of Overlord Agmar: Target: Magister Keldonus Crime: Treason Status: Alive Magister Keldonus, once mage commander of Agmar's Hammer, is to be killed on sight in the name of the Horde. Keldonus was last seen traveling southwest towards Moonrest Gardens to join the Blue Dragonflight in their campaign against magic. Approach with caution as Keldonus is a powerful magus. Do not engage solo! All bounties are paid out by Captain Gort at Agmar's Hammer.]],logDesc=[[Slay Magister Keldonus and return to Captain Gort at Agmar's Hammer in the Dragonblight.]],choiceRewards={{id=38195,qty=1},{id=38194,qty=1},{id=38137,qty=1},{id=38189,qty=1},{id=38196,qty=1},{id=38138,qty=1}}}
DB[12090]={id=12090,zoneId=65,name=[[Wanted: Gigantaur]],level=74,minLevel=71,giverType=[[NPC]],ender=[[Captain Gort]],enderType=[[NPC]],enderId=26618,wowhead=[[https://www.wowhead.com/wotlk/quest=12090]],image=[[assets/images/quests/placeholder.png]],desc=[[By decree of Overlord Agmar: Target: Gigantaur Crime: Attacks upon the Horde; "Bein' ugly" Status: Alive The magnataur lord, Gigantaur, is wanted in relation to a number of attacks against Horde soldiers and installations in the Dragonblight. Gigantaur was last seen wandering the woods and roads south by southeast of Agmar's Hammer. Gigantaur should be considered armed and extremely dangerous. Do not engage solo! All bounties are paid out by Captain Gort at Agmar's Hammer.]],logDesc=[[Slay Gigantaur and return to Captain Gort at Agmar's Hammer in the Dragonblight. ]],choiceRewards={{id=37969,qty=1},{id=38012,qty=1},{id=38055,qty=1},{id=38116,qty=1}}}
DB[12091]={id=12091,zoneId=65,name=[[Wanted: Dreadtalon]],level=74,minLevel=71,giverType=[[NPC]],ender=[[Captain Gort]],enderType=[[NPC]],enderId=26618,wowhead=[[https://www.wowhead.com/wotlk/quest=12091]],image=[[assets/images/quests/placeholder.png]],desc=[[By decree of Overlord Agmar: Target: Dreadtalon Crime: Attacks upon the Horde Status: Alive Dreadtalon is wanted for numerous attacks upon Horde caravans traveling to and from Venomspite. Dreadtalon makes his home on a bluff overlooking the Ruby Dragonshrine, east of Agmar's Hammer. He should be approached with extreme caution. Do not engage solo! All bounties are paid out by Captain Gort at Agmar's Hammer.]],logDesc=[[Slay Dreadtalon and return to Captain Gort at Agmar's Hammer in the Dragonblight.]],choiceRewards={{id=37970,qty=1},{id=38013,qty=1},{id=38056,qty=1},{id=38117,qty=1}}}
DB[12092]={id=12092,zoneId=65,name=[[Strengthen the Ancients]],level=72,minLevel=71,giver=[[Sarendryana]],giverType=[[NPC]],giverId=26837,ender=[[Sarendryana]],enderType=[[NPC]],enderId=26837,wowhead=[[https://www.wowhead.com/wotlk/quest=12092]],image=[[assets/images/quests/placeholder.png]],desc=[[It's not only the $r race that has been impacted by what the blue dragonflight forces have done. The ancients of the Lothalor Woods to the southeast have been affected as well. Some have been corrupted-- avoid them at all costs--but most can still be saved. However, the treants of the woods seem to be immune to the magic seeping through the land and the arcane wyrms that have come with it. Ask the treants for their bark and feed it to the ancients. Hopefully that will be enough to save them.]],logDesc=[[Use the Bark of the Walkers to strengthen 3 Lothalor Ancients and then return to Sarendryana at Stars' Rest.]],choiceRewards={{id=37966,qty=1},{id=38008,qty=1},{id=38051,qty=1},{id=38112,qty=1}}}
DB[12093]={id=12093,zoneId=394,name=[[Runes of Compulsion]],level=75,minLevel=72,giver=[[Gavrock]],giverType=[[NPC]],giverId=26420,ender=[[Gavrock]],enderType=[[NPC]],enderId=26420,prevId=12081,rewardNextId=12094,wowhead=[[https://www.wowhead.com/wotlk/quest=12093]],image=[[assets/images/quests/placeholder.png]],desc=[[Even as Kurun attacks Thor Modan, the iron dwarves work their magics against our brothers. Summoning our brothers from the earth, then binding them with runes, the sons of iron force them to war against the children of stone. Along the Eastwind Shore, they use runes of compulsion to send enslaved giants to the battlefields of the north. Find the four runes of compulsion and force their overseers to appear by defeating the rune-weavers who man each rune. Without the overseers, the runes are useless.]],logDesc=[[Gavrock, at the Ruins of Tethys, wants you to neutralize the four Runes of Compulsion by defeating Overseer Durval, Overseer Korgan, Overseer Lochli, and Overseer Brunon.]]}
DB[12094]={id=12094,zoneId=394,name=[[Latent Power]],level=75,minLevel=72,giver=[[Gavrock]],giverType=[[NPC]],giverId=26420,ender=[[Gavrock]],enderType=[[NPC]],enderId=26420,prevId=12093,rewardNextId=12099,wowhead=[[https://www.wowhead.com/wotlk/quest=12094]],image=[[assets/images/quests/placeholder.png]],desc=[[While the runes of compulsion are dormant, there is a chance we can release the runed giants. I will give you a piece of stone that has been part of me since my creation. If properly imbued, it can be used to free the bound giants. Two ancient stone markers sit atop places of power between the Path of Iron and the forest's edge -- locations your people would call the intersections of ley lines. The other is on an island at the southern end of these ruins. Charge the shard at each stone and return.]],logDesc=[[Charge the Shard of Gavrock at the First Ancient Stone, the Second Ancient Stone, and the Third Ancient Stone, then return to Gavrock at the Ruins of Tethys.]]}
DB[12095]={id=12095,zoneId=65,name=[[To Dragon's Fall]],level=75,minLevel=71,giver=[[Captain Gort]],giverType=[[NPC]],giverId=26618,ender=[[Rokhan]],enderType=[[NPC]],enderId=26859,rewardNextId=12097,wowhead=[[https://www.wowhead.com/wotlk/quest=12095]],image=[[assets/images/quests/placeholder.png]],desc=[[East of here, in the heart of the Dragonblight, is a field full of nothing but dragon bones and snow. The Scourge have set up multiple camps in the central tundra and are raising frostwyrms to send against our forces at the Wrathgate. While most of these frostwyrms are easily dealt with by Rokhan and his dragon hunters, one of them is proving to be a bit problematic. Go northeast and seek out Rokhan at Dragon's Fall. Help him and his men put down Sarathstra and you'll be rewarded handsomely!]],logDesc=[[Speak with Rokhan at Dragon's Fall in the Dragonblight.]]}
DB[12096]={id=12096,zoneId=65,name=[[Strengthen the Ancients]],level=72,minLevel=71,giver=[[Earthwarden Grife]],giverType=[[NPC]],giverId=26854,ender=[[Earthwarden Grife]],enderType=[[NPC]],enderId=26854,wowhead=[[https://www.wowhead.com/wotlk/quest=12096]],image=[[assets/images/quests/placeholder.png]],desc=[[The ancients of the Lothalor Woods to the south are being corrupted by arcane wyrms... wyrms which have risen out of the ground! Those that are already corrupted are deadly and of no use to us, but most can still be saved. Luckily, the treants of the woods seem to be immune to everything happening up there. Ask the treants for their bark and when you get some, feed it to the ancients. This should strengthen them. Now leave me to my business! I have to keep an eye on these apothecaries.]],logDesc=[[Use the Bark of the Walkers to strengthen 3 Lothalor Ancients and then return to Earthwarden Grife at Agmar's Hammer.]],choiceRewards={{id=37966,qty=1},{id=38008,qty=1},{id=38051,qty=1},{id=38112,qty=1}}}
DB[12097]={id=12097,zoneId=65,name=[[Sarathstra, Scourge of the North]],level=75,minLevel=71,giver=[[Rokhan]],giverType=[[NPC]],giverId=26859,ender=[[Captain Gort]],enderType=[[NPC]],enderId=26618,prevId=12095,wowhead=[[https://www.wowhead.com/wotlk/quest=12097]],image=[[assets/images/quests/placeholder.png]],desc=[[Me hunters be dead or frozen, $N. Just you and whatever allies you bring wit ya is all da help you get. You still want to do dis? Just say da word and me call for da dragon once more. If ya kill it, take da beast's frozen heart back to Agmar's Hammer and present it to Gort. He sure to reward you good, mon.]],logDesc=[[Speak with Rokhan to call down the frostwyrm, Sarathstra. Kill Sarathstra and deliver Sarathstra's Frozen Heart to Captain Gort at Agmar's Hammer.]],choiceRewards={{id=38530,qty=1},{id=38532,qty=1},{id=38531,qty=1},{id=38533,qty=1}}}
DB[12098]={id=12098,zoneId=65,name=[[Search Indu'le Village]],level=72,minLevel=71,giver=[[Image of Archmage Modera]],giverType=[[NPC]],giverId=26673,ender=[[Mage-Commander Evenstar]],enderType=[[NPC]],enderId=26873,prevId=12083,rewardNextId=12107,wowhead=[[https://www.wowhead.com/wotlk/quest=12098]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm certain that you'll find the next ley line focus somewhere in the remains of Indu'le Village to the southeast. The problem is, we've had absolutely no reports of there being one there. If you would, please investigate the village for any signs of the focus or the mage hunters and their commander in the area. Don't forget to search in the lake if you have to.]],logDesc=[[Search for the commander of the mage hunter forces at Indu'le Village and Lake Indu'le.]]}
DB[12099]={id=12099,zoneId=394,name=[[Free at Last]],level=75,minLevel=72,giver=[[Gavrock]],giverType=[[NPC]],giverId=26420,ender=[[Gavrock]],enderType=[[NPC]],enderId=26420,prevId=12094,wowhead=[[https://www.wowhead.com/wotlk/quest=12099]],image=[[assets/images/quests/placeholder.png]],desc=[[The rock shard you imbued should be powerful enough to break the runic magic binding my brothers. Take it with you and find the runed giants walking north along the Eastwind Shore. Unleash the power stored in the stone and observe the results. If it works, the runed giants should return to their senses and stop obeying the iron dwarves. If the stone fails to work, the giants may attack in a weakened state. But, what choice do we have? If we do not try, they will remain enslaved without hope.]],logDesc=[[Use Gavrock's Runebreaker to free 4 Runed Giants, then return to Gavrock at the Ruins of Tethys.]],choiceRewards={{id=39117,qty=1},{id=39109,qty=1},{id=39120,qty=1},{id=39119,qty=1},{id=39112,qty=1}}}
DB[12100]={id=12100,zoneId=65,name=[[Containing the Rot]],level=72,minLevel=71,giver=[[Soar Hawkfury]],giverType=[[NPC]],giverId=26504,ender=[[Soar Hawkfury]],enderType=[[NPC]],enderId=26504,rewardNextId=12101,wowhead=[[https://www.wowhead.com/wotlk/quest=12100]],image=[[assets/images/quests/placeholder.png]],desc=[[With Scourge comes death and disease. We often overlook that the wildlife of a Scourge infested area is ravaged and ultimately destroyed by rot and contagion. For most of the indigenous beasts of the Dragonblight it is too late. The festering disease that the Scourge brings has already infected the beasts and they are now rabid and rotting. You must venture west, towards the Pit of Narjun, and cull the infected wildlife. Check their corpses for a preserved organ as we need one to devise a vaccine.]],logDesc=[[Soar Hawkfury at Agmar's Hammer in the Dragonblight wants you to kill 15 Infected Wildlife and recover a Rot Resistant Organ.]]}
DB[12101]={id=12101,zoneId=65,name=[[The Good Doctor...]],level=72,minLevel=71,giver=[[Soar Hawkfury]],giverType=[[NPC]],giverId=26504,ender=[[Doctor Sintar Malefious]],enderType=[[NPC]],enderId=26505,prevId=12100,rewardNextId=12102,wowhead=[[https://www.wowhead.com/wotlk/quest=12101]],image=[[assets/images/quests/placeholder.png]],desc=[[Our Forsaken allies have sent their apothecary core here to assist us in destroying the Scourge at the Wrathgate. One among them, Doctor Sintar Malefious, is well versed in the Scourge rot and methods of containing the spread. I had previously worked out a deal with him in regards to devising a vaccine for wildlife. He's since been waiting on the organ. Deliver this rot resistant organ to Dr. Malefious and let him know it's from me. He'll direct you on your next task.]],logDesc=[[Deliver the Rot Resistant Organ to Doctor Sintar Malefious at Agmar's Hammer. ]]}
DB[12102]={id=12102,zoneId=65,name=[[In Search of the Ruby Lilac]],level=73,minLevel=71,giver=[[Doctor Sintar Malefious]],giverType=[[NPC]],giverId=26505,ender=[[Doctor Sintar Malefious]],enderType=[[NPC]],enderId=26505,prevId=12101,rewardNextId=12104,wowhead=[[https://www.wowhead.com/wotlk/quest=12102]],image=[[assets/images/quests/placeholder.png]],desc=[[How fortuitous it is that the Ruby Dragonshrine lays just to the east. It is there that you will find a flower called the ruby lilac. This lifegiving plant is all that I need to concoct a vaccine for the untainted beasts of this region. Travel east and search the Ruby Dragonshrine for the lilac. Just one thing: The dragonshrine, like all the dragonshrines in this blasted wasteland, is beset by the Scourge. Watch your step. We wouldn't want you to be devoured by an emberwyrm. <Sintar laughs.>]],logDesc=[[Doctor Sintar Malefious at Agmar's Hammer in the Dragonblight wants you to collect 1 Ruby Lilac.]]}
DB[12103]={id=12103,zoneId=3537,name=[[DEPRECATED]],level=74,minLevel=72,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12103]],image=[[assets/images/quests/placeholder.png]],desc=[[I've heard enough, $N.  We must make sure whatever's happening at Silverbrook doesn't spread to the rest of the continent. I don't care if it's the water, the altitude or an ancient troll curse that's driven these villagers murderously insane... return to Silverbrook and put an end to them.]],logDesc=[[Captain Derrick at Amberpine Lodge wants you to slay 8 Silverbrook Villagers and 8 Silverbrook Trappers.]]}
DB[12104]={id=12104,zoneId=65,name=[[Return to Soar]],level=73,minLevel=71,giver=[[Doctor Sintar Malefious]],giverType=[[NPC]],giverId=26505,ender=[[Soar Hawkfury]],enderType=[[NPC]],enderId=26504,prevId=12102,rewardNextId=12111,wowhead=[[https://www.wowhead.com/wotlk/quest=12104]],image=[[assets/images/quests/placeholder.png]],desc=[[<Doctor Malefious hands you a vial full of murky liquid.> Here you are then, $r. Take this back to the cow and let him know that all debts have been paid. We are officially "square." Now leave me before I set Jennings upon you.]],logDesc=[[Deliver Sintar's Vaccine to Soar Hawkfury at Agmar's Hammer.]]}
DB[12105]={id=12105,zoneId=394,name=[[Descent into Darkness]],level=74,minLevel=73,giverType=[[NPC]],ender=[[Lieutenant Dumont]],enderType=[[NPC]],enderId=26875,rewardNextId=12109,wowhead=[[https://www.wowhead.com/wotlk/quest=12105]],image=[[assets/images/quests/placeholder.png]],desc=[[The journal was written by a denizen of Silverbrook named Mikhail.  It details the arrival of a shadow-worshipping group called the "wolfcult." The villagers were reluctant to embrace the cult at first, but sympathizers sprung up gradually among town residents. Unsettled by this, Mikhail sent his daughter Sasha away from Silverbrook while he attempted to reason with the other villagers. Mikhail's last entry mentions a meeting of local town leaders to discuss unspecified events in Hollowstone Mine.]],logDesc=[[Bring Mikhail's Journal to Lieutenant Dumont in Amberpine Lodge.]],choiceRewards={{id=38734,qty=1},{id=39033,qty=1},{id=39060,qty=1},{id=39098,qty=1}}}
DB[12106]={id=12106,zoneId=65,name=[[Search Indu'le Village]],level=72,minLevel=71,giver=[[Image of Archmage Aethas Sunreaver]],giverType=[[NPC]],giverId=26471,ender=[[Mage-Commander Evenstar]],enderType=[[NPC]],enderId=26873,prevId=12084,rewardNextId=12110,wowhead=[[https://www.wowhead.com/wotlk/quest=12106]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm certain that you'll find the next ley line focus somewhere in the remains of Indu'le Village to the southeast. The problem is, I've had absolutely no reports of there being one there. I need you to go investigate the village for any signs of the focus or the mage hunters and their commander in the area. Search in the lake if you have to!]],logDesc=[[Search for the commander of the mage hunter forces at Indu'le Village and Lake Indu'le.]]}
DB[12107]={id=12107,zoneId=65,name=[[The End of the Line]],level=72,minLevel=71,giver=[[Mage-Commander Evenstar]],giverType=[[NPC]],giverId=26873,ender=[[Image of Archmage Modera]],enderType=[[NPC]],enderId=26673,prevId=12098,rewardNextId=12119,wowhead=[[https://www.wowhead.com/wotlk/quest=12107]],image=[[assets/images/quests/placeholder.png]],desc=[[Within his robes you find two things of interest. One is a talisman, which is clearly a focus controlling device. The other is a set of orders from someone named Sidragos, which were ultimately intended for the leader back at the Moonrest Gardens. The water-soaked parchment informs Goramosh that he is to move all mage hunter forces east to the Azure Dragonshrine. Perhaps you should get what information you can from the focus and head east to observe the dragonshrine from its western ledge.]],logDesc=[[Use the Ley Line Focus Control Talisman to gain information from the Ley Line Focus under Lake Indu'le. Then, head east to the Azure Dragonshrine near south central Dragonblight and observe what is occurring there from the western ledge. Afterward, return to the Image of Archmage Modera at Stars' Rest.]],choiceRewards={{id=38151,qty=1},{id=38152,qty=1},{id=38129,qty=1},{id=38153,qty=1},{id=38217,qty=1}}}
DB[12108]={id=12108,zoneId=3537,name=[[DEPRECATED]],level=74,minLevel=72,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12108]],image=[[assets/images/quests/placeholder.png]],desc=[[The dirt mound is, indeed, a hastily dug grave.  The body beneath is unrecognizable but you find a note that identifies that man as Mikhail. The note mentions Hollowstone Mine once again.  Perhaps someone back at Amberpine Lodge might be familiar with the area.]],logDesc=[[Bring Mikhail's Note to Cartographer Tobias at Amberpine Lodge.]]}
DB[12109]={id=12109,zoneId=394,name=[[Report to Gryan Stoutmantle... Again]],level=74,minLevel=73,giver=[[Lieutenant Dumont]],giverType=[[NPC]],giverId=26875,ender=[[Captain Gryan Stoutmantle]],enderType=[[NPC]],enderId=26212,prevId=12105,rewardNextId=12158,wowhead=[[https://www.wowhead.com/wotlk/quest=12109]],image=[[assets/images/quests/placeholder.png]],desc=[[The Westfall boys were sent east to look for a path into the northern territories.  Their secondary objective is to secure strategic resource points, so I'm sure they wouldn't mind investigating a mine. Look for the Westfall Brigade encampment far to the northeast and seek out Gryan Stoutmantle.  You might remember him if you ever spent any time in Westfall.  Make sure to tell him I sent you. He'll be more than happy to let you claim a functioning mine for the king.]],logDesc=[[Speak to Captain Gryan Stoutmantle at the Westfall Brigade Encampment.]]}
DB[12110]={id=12110,zoneId=65,name=[[The End of the Line]],level=72,minLevel=71,giver=[[Mage-Commander Evenstar]],giverType=[[NPC]],giverId=26873,ender=[[Image of Archmage Aethas Sunreaver]],enderType=[[NPC]],enderId=26471,prevId=12106,rewardNextId=12122,wowhead=[[https://www.wowhead.com/wotlk/quest=12110]],image=[[assets/images/quests/placeholder.png]],desc=[[Within his robes you find two things of interest. One is a talisman, which is clearly a focus controlling device. The other is a set of orders from someone named Sidragos, which were ultimately intended for the leader back at the Moonrest Gardens. The fragile water-soaked parchment informs Goramosh that he is to move all mage hunter forces east to the Azure Dragonshrine. Perhaps you should get what information you can from the focus and head east to observe the dragonshrine from its western ledge.]],logDesc=[[Use the Ley Line Focus Control Talisman to gain information from the Ley Line Focus under Lake Indu'le. Then, head east to the Azure Dragonshrine near south central Dragonblight and observe what is occurring there from the western ledge Afterward, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.]],choiceRewards={{id=38151,qty=1},{id=38152,qty=1},{id=38129,qty=1},{id=38153,qty=1},{id=38217,qty=1}}}
DB[12111]={id=12111,zoneId=65,name=[[Where the Wild Things Roam]],level=73,minLevel=71,giver=[[Soar Hawkfury]],giverType=[[NPC]],giverId=26504,ender=[[Soar Hawkfury]],enderType=[[NPC]],enderId=26504,prevId=12104,wowhead=[[https://www.wowhead.com/wotlk/quest=12111]],image=[[assets/images/quests/placeholder.png]],desc=[[Inside this pack are several vials containing the vaccine that Sintar created. I now want you to search the nearby woods for Snowfall elk and arctic grizzlies. When you locate the animals, find a safe distance and throw a vial in their general direction. The vial will shatter and release a fine gas that will act as the inoculating agent. The beasts merely have to step inside the gas and they will be vaccinated - ultimately saved. Inoculate as many of the beasts as you can and return to me. ]],logDesc=[[Soar Hawkfury at Agmar's Hammer in the Dragonblight wants you to use the Pack of Vaccine to vaccinate 5 Snowfall Elk and 5 Arctic Grizzlies.]],choiceRewards={{id=38171,qty=1},{id=38172,qty=1},{id=38132,qty=1},{id=38169,qty=1},{id=38170,qty=1},{id=38131,qty=1}}}
DB[12112]={id=12112,zoneId=65,name=[[Stiff Negotiations]],level=74,minLevel=72,giver=[[Narf]],giverType=[[NPC]],giverId=26647,ender=[[Zort]],enderType=[[NPC]],enderId=26659,rewardNextId=12075,wowhead=[[https://www.wowhead.com/wotlk/quest=12112]],image=[[assets/images/quests/placeholder.png]],desc=[[Well it seems you were of a bit of use after all. It's not been my experience to meet many a $r that are. We don't have any more use for you here. Head into the Vice and see if my brother Zort could use a hand. He went to see if he could con the giants into laying down their lives so that we don't have to. He certainly wasn't known for having the brains in the family.]],logDesc=[[Locate Zort in the center of the Crystal Vice, northeast of Nozzlerust Post.]]}
DB[12113]={id=12113,zoneId=394,name=[[Nice to Meat You]],level=75,minLevel=73,giver=[[Harkor]],giverType=[[NPC]],giverId=26884,ender=[[Harkor]],enderType=[[NPC]],enderId=26884,wowhead=[[https://www.wowhead.com/wotlk/quest=12113]],image=[[assets/images/quests/placeholder.png]],desc=[[G'day to ya, $c! Have yerself a seat by me fire, eh? I'd offer to share a nice hot meal, only I ain't got one. I'm stuck here waitin' on an associate, or I'd be out tryin' to remedy that situation meself. Say, you seem to have nuthin' but time on yer hands and there be plenty o' meat in these parts. What say ya lend a hand and round up some grub?]],logDesc=[[Harkor at Harkor's Camp wants you to collect 10 pieces of Fibrous Worg Meat from Duskhowl Prowlers and 10 Shovelhorn Steaks from Longhoof Grazers.]]}
DB[12114]={id=12114,zoneId=394,name=[[Therapy]],level=75,minLevel=73,giver=[[Harkor]],giverType=[[NPC]],giverId=26884,ender=[[Harkor]],enderType=[[NPC]],enderId=26884,wowhead=[[https://www.wowhead.com/wotlk/quest=12114]],image=[[assets/images/quests/placeholder.png]],desc=[[Trolls... me hates 'em all! <Harkor spits.> I once got meself captured by a band o' tha beasts... came this close ta gettin' me head shrunk! Me friends tell me to just move on and put it all behind me, but that just ain't sittin' right. Wanna know what would make me feel better, $r? Seein' a pile of their corpses so high it blots out the sun! I've got good gold to spend if ya can make that happen.]],logDesc=[[Harkor at Harkor's Camp wants you to kill 10 Drakkari Protectors and 10 Drakkari Oracles outside Drakil'jin Ruins.]],choiceRewards={{id=38728,qty=1},{id=39027,qty=1},{id=39055,qty=1},{id=39093,qty=1},{id=38758,qty=1}}}
DB[12115]={id=12115,zoneId=65,name=[[Koltira and the Language of Death]],level=72,minLevel=71,giver=[[Captain Gort]],giverType=[[NPC]],giverId=26618,ender=[[Koltira Deathweaver]],enderType=[[NPC]],enderId=26581,prevId=12057,wowhead=[[https://www.wowhead.com/wotlk/quest=12115]],image=[[assets/images/quests/placeholder.png]],desc=[[There is one who recently joined our cause that might be able to decipher this tome. An unbound death knight known as Koltira Deathweaver has temporarily taken residence here at Agmar's Hammer. As he was once a death knight of Arthas and member of the Scourge, he might be able to translate the language of the dead. Take the flesh-bound tome to Koltira and ask him to translate the pages. ]],logDesc=[[Take the Flesh-Bound Tome to Koltira Deathweaver.]]}
DB[12116]={id=12116,zoneId=394,name=[[It Takes Guts....]],level=75,minLevel=73,giver=[[Kraz]],giverType=[[NPC]],giverId=26886,ender=[[Kraz]],enderType=[[NPC]],enderId=26886,rewardNextId=12120,wowhead=[[https://www.wowhead.com/wotlk/quest=12116]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, $c. It is kind of you to stop and listen to Kraz's tale. For many years Kraz has strained to hear the spirits and do their bidding. Recently,  many voices have been crying to Kraz from these ruins. They seek for a peace they cannot find on their own. If you would help the spirits of those who have come before, enter this crypt and collect something that once belonged to those tormented souls.]],logDesc=[[Kraz at Harkor's Camp wants you to enter Drakil'jin Ruins and collect 5 Drakkari Canopic Jars.]]}
DB[12117]={id=12117,zoneId=65,name=[[Travel to Moa'ki Harbor]],level=72,minLevel=68,giver=[[Hotawa]],giverType=[[NPC]],giverId=28382,ender=[[Elder Ko'nani]],enderType=[[NPC]],enderId=26194,prevId=11968,exGroup=12117,wowhead=[[https://www.wowhead.com/wotlk/quest=12117]],image=[[assets/images/quests/placeholder.png]],desc=[[$R, word just arrived from Moa'ki Harbor. Something very bad happened over there this morning! You've been very helpful to us here. Would you consider using the boat from Unu'pe to travel to the great Dragonblight? By the sound of things, Elder Ko'nani could certainly use your assistance.]],logDesc=[[Travel to Moa'ki Harbor in the Dragonblight and speak with Elder Ko'nani.]],choiceRewards={{id=37283,qty=1},{id=37566,qty=1},{id=37546,qty=1},{id=37319,qty=1}}}
DB[12118]={id=12118,zoneId=65,name=[[Travel to Moa'ki Harbor]],level=72,minLevel=68,giver=[[Anuniaq]],giverType=[[NPC]],giverId=24810,ender=[[Elder Ko'nani]],enderType=[[NPC]],enderId=26194,prevId=11458,exGroup=12117,wowhead=[[https://www.wowhead.com/wotlk/quest=12118]],image=[[assets/images/quests/placeholder.png]],desc=[[$R, word just came in off the boat from Moa'ki Harbor. Something very bad happened over there this morning! You've been very helpful to us here. Would you consider using the boat to travel to the great Dragonblight? By the sound of things, Elder Ko'nani could certainly use your assistance.]],logDesc=[[Travel to Moa'ki Harbor in the Dragonblight and speak with Elder Ko'nani.]],choiceRewards={{id=37283,qty=1},{id=37566,qty=1},{id=37546,qty=1},{id=37319,qty=1}}}
DB[12119]={id=12119,zoneId=65,name=[[Gaining an Audience]],level=72,minLevel=71,giver=[[Image of Archmage Modera]],giverType=[[NPC]],giverId=26673,ender=[[Tariolstrasz]],enderType=[[NPC]],enderId=26443,prevId=12107,rewardNextId=12766,wowhead=[[https://www.wowhead.com/wotlk/quest=12119]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you must travel as swiftly as you can to Wyrmrest Temple and present this letter to the steward, Tariolstrasz. The temple sits in the center of the Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to get to it. I'm sure that when the steward reads your introduction, he'll see to it that you gain an audience with Queen Alexstrasza. We can only hope that we're not too late. Thank you for all that you have done on our behalf. Safe journeys!]],logDesc=[[Deliver your Letter of Introduction to Wyrmrest Temple to Tariolstrasz at Wyrmrest Temple.]]}
DB[12120]={id=12120,zoneId=394,name=[[Drak'aguul's Mallet]],level=75,minLevel=73,giver=[[Kraz]],giverType=[[NPC]],giverId=26886,ender=[[Kraz]],enderType=[[NPC]],enderId=26886,prevId=12116,rewardNextId=12121,wowhead=[[https://www.wowhead.com/wotlk/quest=12120]],image=[[assets/images/quests/placeholder.png]],desc=[[Corruption.... Even before you delivered these jars, Kraz could sense it. This corruption fills the ancient Drakkari spirits with great angst and prevents them from entering the rest they seek. Kraz will not lie, $c. Cleansing this place will require great sacrifice, but we shall speak of that at another time. There is one among the living here who holds the key to its cleansing. Seek out Drak'aguul and return to Kraz with the mallet he carries.]],logDesc=[[Kraz at Harkor's Camp wants you to slay Drak'aguul outside Drakil'jin Ruins and return with the Drakil'jin Mallet.]],choiceRewards={{id=38730,qty=1},{id=39029,qty=1},{id=39057,qty=1},{id=39095,qty=1}}}
DB[12121]={id=12121,zoneId=394,name=[[See You on the Other Side]],level=75,minLevel=73,giver=[[Kraz]],giverType=[[NPC]],giverId=26886,ender=[[Gan'jo]],enderType=[[NPC]],enderId=26924,prevId=12120,rewardNextId=12137,wowhead=[[https://www.wowhead.com/wotlk/quest=12121]],image=[[assets/images/quests/placeholder.png]],desc=[[These Drakkari have met you with nothing but savage hostility. You owe them nothing. Few indeed would carry out the task that Kraz asks of you today. To cleanse this place and send the spirits to their eternal rest, you must join them in death. There is one inside the crypt who awaits you - on the other side. He holds the knowledge we seek, $n. Use the mallet on the gongs. The spirit of he who corrupts this place will surely deliver you to the spirit world. Kraz awaits your return.]],logDesc=[[Kraz at Harkor's Camp wants you to use the Drakil'jin Mallet on the gongs outside Drakil'jin Ruins. Once you have been slain, you are to enter the ruins and speak with the spirit of Gan'jo while you are dead.]]}
DB[12122]={id=12122,zoneId=65,name=[[Gaining an Audience]],level=72,minLevel=71,giver=[[Image of Archmage Aethas Sunreaver]],giverType=[[NPC]],giverId=26471,ender=[[Tariolstrasz]],enderType=[[NPC]],enderId=26443,prevId=12110,rewardNextId=12767,wowhead=[[https://www.wowhead.com/wotlk/quest=12122]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, you must travel as swiftly as you can to Wyrmrest Temple and present this letter to the steward, Tariolstrasz. The temple sits in the center of the Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to get to it. I'm sure that when the steward reads your introduction, he'll see to it that you gain an audience with Queen Alexstrasza. We can only hope that we're not too late. Thank you for all that you have done on our behalf. Safe journeys!]],logDesc=[[Deliver your Letter of Introduction to Wyrmrest Temple to Tariolstrasz at Wyrmrest Temple.]]}
DB[12123]={id=12123,zoneId=65,name=[[Informing the Queen]],level=75,minLevel=71,giver=[[Tariolstrasz]],giverType=[[NPC]],giverId=26443,ender=[[Alexstrasza the Life-Binder]],enderType=[[NPC]],enderId=26917,prevId=12768,nextId=12435,rewardNextId=12435,wowhead=[[https://www.wowhead.com/wotlk/quest=12123]],image=[[assets/images/quests/placeholder.png]],desc=[[<The dragon steward pulls your letter of introduction out of his sleeve.> Yes... yes, I think that you are ready to see the queen now. When you are ready, speak to me again and I will see to it that one of these drakes delivers you safely to the top of the temple. You will need to present your letter in person to Queen Alexstrasza.]],logDesc=[[Deliver your Letter of Introduction to Wyrmrest Temple to Alexstrasza the Life-Binder at Wyrmrest Temple.]]}
DB[12124]={id=12124,zoneId=65,name=[[Informing the Queen]],level=75,minLevel=71,giver=[[Tariolstrasz]],giverType=[[NPC]],giverId=26443,ender=[[Alexstrasza the Life-Binder]],enderType=[[NPC]],enderId=26917,prevId=12769,nextId=12435,rewardNextId=12435,wowhead=[[https://www.wowhead.com/wotlk/quest=12124]],image=[[assets/images/quests/placeholder.png]],desc=[[<The dragon steward pulls your letter of introduction out of his sleeve.> Yes... yes, I think that you are ready to see the queen now. When you are ready, speak to me again and I will see to it that one of these drakes delivers you safely to the top of the temple. You will need to present your letter in person to Queen Alexstrasza.]],logDesc=[[Deliver your Letter of Introduction to Wyrmrest Temple to Alexstrasza the Life-Binder at Wyrmrest Temple.]]}
DB[12125]={id=12125,zoneId=65,name=[[In Service of Blood]],level=73,minLevel=71,giver=[[Koltira Deathweaver]],giverType=[[NPC]],giverId=26581,ender=[[Koltira Deathweaver]],enderType=[[NPC]],enderId=26581,prevId=12115,nextId=12132,exGroup=-12125,wowhead=[[https://www.wowhead.com/wotlk/quest=12125]],image=[[assets/images/quests/placeholder.png]],desc=[[The blood of innocents was once used to sate the thirst of the blade. Alas, such options are no longer available to me. <Koltira pauses to think.> We must improvise. South of here, upon the high bluffs, is the tuskarr village of Indu'le. Having been recently overrun by the Blue Dragonflight's chaotic magic, the resident tuskarr of Indu'le have gone mad. Take this blood gem and use it on a deranged villager. If I cannot take the blood of innocents, I shall have the blood of the meek!]],logDesc=[[Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Blood Gem on a Deranged Indu'le Villager and return to him with a Filled Blood Gem.]]}
DB[12126]={id=12126,zoneId=65,name=[[In Service of the Unholy]],level=73,minLevel=71,giver=[[Koltira Deathweaver]],giverType=[[NPC]],giverId=26581,ender=[[Koltira Deathweaver]],enderType=[[NPC]],enderId=26581,prevId=12115,nextId=12132,exGroup=-12125,wowhead=[[https://www.wowhead.com/wotlk/quest=12126]],image=[[assets/images/quests/placeholder.png]],desc=[[The power of the unholy is coveted among my kind. It makes up the very fiber of our existence, granting death to those that dare make a mockery of it! Thankfully there is a font from which I may draw from in my time of need. Take this unholy gem and make your way to the Ruby Dragonshrine, east of here. It is there that you will find Duke Vallenhal, death knight of Arthas. Weaken his resolve in battle and unleash the power of the gem upon him. It will finish him off and steal his unholy energy! ]],logDesc=[[Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Unholy Gem on Duke Vallenhal and return to him with a Filled Unholy Gem.]]}
DB[12127]={id=12127,zoneId=65,name=[[In Service of Frost]],level=73,minLevel=71,giver=[[Koltira Deathweaver]],giverType=[[NPC]],giverId=26581,ender=[[Koltira Deathweaver]],enderType=[[NPC]],enderId=26581,prevId=12115,nextId=12132,exGroup=-12125,wowhead=[[https://www.wowhead.com/wotlk/quest=12127]],image=[[assets/images/quests/placeholder.png]],desc=[[The biting cold protects the death knight while repelling his enemies. He that commands the power of frost can incite chaos and destruction! Take this frost gem and travel far across the open tundra of the Dragonblight until you come upon the Mirror of Dawn, east of Wyrmrest Temple. It is there that you are to battle the legions of ice revenants that dwell upon the lakes surface and take from them the essence of frost. Utilize the power of the gem when they are weak, $N!]],logDesc=[[Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Frost Gem on Ice Revenants and return to him with a Filled Frost Gem.]]}
DB[12128]={id=12128,zoneId=394,name=[[Check Up on Raegar]],level=75,minLevel=73,giver=[[Brugar Stoneshear]],giverType=[[NPC]],giverId=26226,ender=[[Raegar Breakbrow]],enderType=[[NPC]],enderId=26883,prevId=12014,rewardNextId=12129,wowhead=[[https://www.wowhead.com/wotlk/quest=12128]],image=[[assets/images/quests/placeholder.png]],desc=[[With all the excitement about the army trying to move through Thor Modan, I'd almost forgotten about Raegar's crew down at Prospector's Point. I sent Raegar and his assistants, along with a mountaineer friend, down to establish a small post near Dun Argol, at the southern end of the Eastwind Shore. They were to investigate the iron dwarf presence in the southern hills, but I haven't received any reports yet. Could you check up on them if you're going down that way?]],logDesc=[[Speak with Raegar Breakbrow at Prospector's Point.]]}
DB[12129]={id=12129,zoneId=394,name=[[The Perfect Plan]],level=75,minLevel=73,giver=[[Raegar Breakbrow]],giverType=[[NPC]],giverId=26883,ender=[[Raegar Breakbrow]],enderType=[[NPC]],enderId=26883,prevId=12128,rewardNextId=12130,wowhead=[[https://www.wowhead.com/wotlk/quest=12129]],image=[[assets/images/quests/placeholder.png]],desc=[[The iron dwarves are making no secret of the fact that they're preparing for war. With their giants, golems, and lightning elementals, they'd have a technological advantage against the Westfall Brigade. If they don't find passage north in time, the irons could take them by surprise. We've got to tie them up here, and I've got just the way to do it. Dun Argol is full of rune-smiths churning out war golems. They carry plans for specific pieces, so you'll need to find and assemble all the parts.]],logDesc=[[Bring the completed War Golem Blueprint to Raegar Breakbrow at Prospector's Point.]]}
DB[12130]={id=12130,zoneId=394,name=[[Why Fabricate When You Can Appropriate?]],level=75,minLevel=73,giver=[[Raegar Breakbrow]],giverType=[[NPC]],giverId=26883,ender=[[Raegar Breakbrow]],enderType=[[NPC]],enderId=26883,prevId=12129,rewardNextId=12131,wowhead=[[https://www.wowhead.com/wotlk/quest=12130]],image=[[assets/images/quests/placeholder.png]],desc=[[We've got the blueprints, but we can't do anything with them without parts! We don't have access to a foundry, much less materials, but there's a whole load of parts up in Dun Argol. Your job? Give them a new home. They're likely to be scattered around any of the buildings where the iron rune-smiths are working, and I wouldn't blame the irons for being cranky when you try to filch their handiwork. The more parts you can bring, the better we can make this golem.]],logDesc=[[Bring 8 War Golem Parts to Raegar Breakbrow at Prospector's Point.]]}
DB[12131]={id=12131,zoneId=394,name=[[We Have the Power]],level=75,minLevel=73,giver=[[Raegar Breakbrow]],giverType=[[NPC]],giverId=26883,ender=[[Raegar Breakbrow]],enderType=[[NPC]],enderId=26883,prevId=12130,rewardNextId=12138,wowhead=[[https://www.wowhead.com/wotlk/quest=12131]],image=[[assets/images/quests/placeholder.png]],desc=[[We're almost there, but the war golem won't run without power cells. From the information I was able to collect in Dun Argol before we were discovered, both Rune-Smith Durar and Rune-Smith Kathorn each create one power cell. We'll need one power cell from each of the rune-smiths before our golem will work. You should be able to find each rune-smith in his workshop on the central level of Dun Argol.]],logDesc=[[Bring Durar's Power Cell and Kathorn's Power Cell to Raegar Breakbrow at Prospector's Point.]]}
DB[12132]={id=12132,zoneId=65,name=[[The Power to Destroy]],level=73,minLevel=71,giver=[[Koltira Deathweaver]],giverType=[[NPC]],giverId=26581,ender=[[Koltira Deathweaver]],enderType=[[NPC]],enderId=26581,rewardNextId=12136,wowhead=[[https://www.wowhead.com/wotlk/quest=12132]],image=[[assets/images/quests/placeholder.png]],desc=[[While you have done much for me, one task remains. Beside the world you know exists another world. It is from that world, the world of shadows, that my tormentors assault me. While I am powerless to face my own demons, you could end their reign of terror. You have the strength, I have seen it with my own eyes. Enter the world of shadows and face the demons that torment me! Do this and I will translate the tome, as promised.]],logDesc=[[Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to enter the world of shadows and defeat 6 Shadowy Tormentors. Speak to Koltira Deathweaver should you need to re-enter the world of shadows.]]}
DB[12133]={id=12133,name=[[Smash the Pumpkin]],name_loc=[[Aplasta la calabaza]],level=-1,minLevel=1,giver=[[Large Jack-o'-Lantern]],giver_loc=[[Calabaza iluminada]],giverType=[[GO]],giverId=186887,ender=[[Costumed Orphan Matron]],ender_loc=[[Matrona de huérfanos disfrazada]],enderType=[[NPC]],enderId=24519,poiX=-9430,poiY=56,wowhead=[[https://www.wowhead.com/wotlk/quest=12133]],image=[[assets/images/quests/placeholder.png]],desc=[[This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within. Smashing the pumpking reveals an old, scorched holy symbol.]],logDesc=[[Give the Scorched Holy Symbol to the Costumed Orphan Matron.]],rewards={{id=34077,qty=1}}}
DB[12134]={id=12134,zoneId=394,name=[[Sasha's Hunt]],level=75,minLevel=73,giver=[[Sasha]],giverType=[[NPC]],giverId=26935,ender=[[Sasha]],enderType=[[NPC]],enderId=26935,prevId=12329,wowhead=[[https://www.wowhead.com/wotlk/quest=12134]],image=[[assets/images/quests/placeholder.png]],desc=[[This thing... this curse... that's affecting Silverbrook and Solstice Village... it makes beasts out of people. My father tried to warn them, but they all listened to the wolfcult instead. They're too far gone now, it's time to put them down... for their own sake.]],logDesc=[[Sasha wants you to kill 12 Solstice Hunters in Solstice Village.]],choiceRewards={{id=39011,qty=1},{id=39010,qty=1},{id=38755,qty=1},{id=39110,qty=1}}}
DB[12135]={id=12135,name=[["Let the Fires Come!"]],name_loc=[["¡Dejad que el fuego se acerque!"]],level=-1,minLevel=1,giver=[[Costumed Orphan Matron]],giver_loc=[[Matrona de huérfanos disfrazada]],giverType=[[NPC]],giverId=24519,ender=[[Costumed Orphan Matron]],ender_loc=[[Matrona de huérfanos disfrazada]],enderType=[[NPC]],enderId=24519,exGroup=12135,poiX=-9430,poiY=56,wowhead=[[https://www.wowhead.com/wotlk/quest=12135]],image=[[assets/images/quests/placeholder.png]],desc=[[You must help us!  The Headless Horseman will attack the village at any moment!  Fires will be everywhere!  The children aren't safe! Please, $n, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!]],logDesc=[[The Costumed Orphan Matron wants you to help put out all the village fires after the Headless Horseman lights them.  When they are out, speak again to the Costumed Orphan Matron.]],rewards={{id=20557,qty=3},{id=34068,qty=1}}}
DB[12136]={id=12136,zoneId=65,name=[[The Translated Tome]],level=73,minLevel=71,giver=[[Koltira Deathweaver]],giverType=[[NPC]],giverId=26581,ender=[[Captain Gort]],enderType=[[NPC]],enderId=26618,prevId=12132,wowhead=[[https://www.wowhead.com/wotlk/quest=12136]],image=[[assets/images/quests/placeholder.png]],desc=[[Here it is, $N. I have translated everything printed upon the pages of the tome. Inside it you will find a list of the names of Cult of the Damned members spanning the entire continent. Their network of spies and operatives is impressive, to say the least. Farewell, friend. May the book serve you and your people well.]],logDesc=[[Deliver the Translated Flesh-bound Tome to Captain Gort at Agmar's Hammer.]],choiceRewards={{id=37958,qty=1},{id=38000,qty=1},{id=38043,qty=1},{id=38104,qty=1}}}
DB[12137]={id=12137,zoneId=394,name=[[Chill Out, Mon]],level=75,minLevel=73,giver=[[Gan'jo]],giverType=[[NPC]],giverId=26924,ender=[[Kraz]],enderType=[[NPC]],enderId=26886,prevId=12121,rewardNextId=12152,wowhead=[[https://www.wowhead.com/wotlk/quest=12137]],image=[[assets/images/quests/placeholder.png]],desc=[[It be as the prophecies said, mon. A $r $c be comin' to set our spirits to rest. We been waitin' for a long time now! The Drakkari have become a lost people, fierce and savage. But here we suffer by no fault of our own, mon. This place need cleansin' and only the living can do it. Speak to me when ya be ready to rejoin your body. Then take the snow from the chest near me here and put my bruddas to sleep. Take their remnants to your spirit guide. He be knowin' what to do next.]],logDesc=[[Gan'jo wants you to collect the Snow of Eternal Slumber from his chest in the Drakil'jin Ruins. You are to use the Snow on the Ancient Drakkari Spirits there and take their Drakkari Spirit Particles back to Kraz at Harkor's Camp.]]}
DB[12138]={id=12138,zoneId=394,name=[[... Or Maybe We Don't]],level=75,minLevel=73,giver=[[Raegar Breakbrow]],giverType=[[NPC]],giverId=26883,ender=[[Raegar Breakbrow]],enderType=[[NPC]],enderId=26883,prevId=12131,wowhead=[[https://www.wowhead.com/wotlk/quest=12138]],image=[[assets/images/quests/placeholder.png]],desc=[[You'd think the guys making the power cells would've thought to power them up, but no, they've got to make it difficult for us. Fine, we'll charge those cells the hard way. There's enough power in them to run the golem for a short time, but don't expect it to be any good in combat. You see the lightning sentries that the irons have posted around the perimeter of Dun Argol? Bring the golem with you, take it close to them, and use the golem to absorb the power as the sentries die.]],logDesc=[[Charge your War Golem with the energy from 10 Lightning Sentries and return to Raegar Breakbrow at Prospector's Point.]]}
DB[12139]={id=12139,name=[["Let the Fires Come!"]],name_loc=[["¡Dejad que el fuego se acerque!"]],level=-1,minLevel=1,giver=[[Masked Orphan Matron]],giver_loc=[[Supervisora de huérfanos enmascarada]],giverType=[[NPC]],giverId=23973,ender=[[Masked Orphan Matron]],ender_loc=[[Supervisora de huérfanos enmascarada]],enderType=[[NPC]],enderId=23973,exGroup=12139,poiX=2240,poiY=283,wowhead=[[https://www.wowhead.com/wotlk/quest=12139]],image=[[assets/images/quests/placeholder.png]],desc=[[The Headless Horseman will attack the village at any moment!  Fires will be everywhere! $n, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!]],logDesc=[[The Masked Orphan Matron wants you to help put out all the village fires.  When they are out, speak again to the Masked Orphan Matron in town.]],rewards={{id=20557,qty=3},{id=34068,qty=1}}}
DB[12140]={id=12140,zoneId=65,name=[[All Hail Roanauk!]],level=73,minLevel=71,giver=[[Overlord Agmar]],giverType=[[NPC]],giverId=26379,ender=[[Overlord Agmar]],enderType=[[NPC]],enderId=26379,prevId=12069,wowhead=[[https://www.wowhead.com/wotlk/quest=12140]],image=[[assets/images/quests/placeholder.png]],desc=[[Like the tauren, Forsaken, trolls and blood elves, so too do the taunka need a leader born of their own blood. The one you saved from Icemist, Roanauk, will be this leader. <Overlord Agmar hands you a parchment.> I give to you something familiar - the blood oath of the Horde. Take the oath to Roanauk Icemist and initiate him into the Horde as leader of the taunka. Let us not keep him waiting. <Agmar nods.> ]],logDesc=[[Seek out Roanauk Icemist at Agmar's Hammer and initiate him as a member and leader of the Horde forces. Return to Overlord Agmar with the Blood Oath of the Horde when you complete this task. ]],choiceRewards={{id=38293,qty=1},{id=38002,qty=1},{id=38106,qty=1},{id=37960,qty=1}}}
DB[12141]={id=12141,zoneId=3537,name=[[A Diplomatic Mission]],level=71,minLevel=68,giver=[[Counselor Talbot]],giverType=[[NPC]],giverId=25301,ender=[[Karuk]],enderType=[[NPC]],enderId=25435,prevId=11791,nextId=11613,rewardNextId=11613,wowhead=[[https://www.wowhead.com/wotlk/quest=12141]],image=[[assets/images/quests/placeholder.png]],desc=[[I see that you are very eager to help, $N.  You didn't come all the way to Northrend to stay holed up in a city!  I've just the task for you... something that'll take you far away from here. We've long sought to gain the favor of the tuskarr native to Northrend.  Recently a young tuskarr came to us seeking help, something we couldn't offer at the time. Now that you're around, maybe you can lend him a hand.  Look for Karuk near the Riplash Strand, southwest of here, and see what you can do to help.]],logDesc=[[Speak to Karuk at Riplash Strand, southwest of Valiance Keep.]]}
DB[12142]={id=12142,zoneId=65,name=[[Pest Control]],level=73,minLevel=72,giver=[[Duane]],giverType=[[NPC]],giverId=26978,ender=[[Duane]],enderType=[[NPC]],enderId=26978,rewardNextId=12143,wowhead=[[https://www.wowhead.com/wotlk/quest=12142]],image=[[assets/images/quests/placeholder.png]],desc=[[Ugh! One of those little snobold runts trashed our camp while we were busy with that last dragon. They've been plaguing us whenever we turn our backs... I've had enough! To the south you'll find the snobolds hiding under the skirts of some of the local magnataur. Go slaughter them. If the magnataur interfere on behalf of their slaves, kill them as well.]],logDesc=[[Duane at the 7th Legion Front wants you to kill 10 Snowplain Snobolds and 3 Dragonblight Magnataur at the magnataur camps surrounding Wyrmrest.]]}
DB[12143]={id=12143,zoneId=65,name=[[Canyon Chase]],level=73,minLevel=72,giver=[[Duane]],giverType=[[NPC]],giverId=26978,ender=[[Duane]],enderType=[[NPC]],enderId=26978,prevId=12142,wowhead=[[https://www.wowhead.com/wotlk/quest=12143]],image=[[assets/images/quests/placeholder.png]],desc=[[I can't believe this! Another band of those vermin just tried to take off with more of our supplies. They're scurrying off towards that north canyon, get after them and deal with whoever they're going to!]],logDesc=[[Duane wants you to chase the snobolds down the canyon northeast of 7th Legion Front and deal with their leader.]],choiceRewards={{id=37965,qty=1},{id=38007,qty=1},{id=38049,qty=1},{id=38111,qty=1}}}
DB[12144]={id=12144,zoneId=65,name=[[Pest Control]],level=73,minLevel=72,giver=[[Kontokanis]],giverType=[[NPC]],giverId=26979,ender=[[Kontokanis]],enderType=[[NPC]],enderId=26979,rewardNextId=12145,wowhead=[[https://www.wowhead.com/wotlk/quest=12144]],image=[[assets/images/quests/placeholder.png]],desc=[[Oi, mon! One of dose little snobold runts trashed our camp during da last dragon attack. Dey've been houndin us wheneva we turn our backs and I've had enough.  To da east you'll find da snobolds hiding under da skirts of some of da local magnataur. Go slaughter dem. If da magnataur interfere on behalf of deir slaves, kill dem as well.]],logDesc=[[Kontokanis at Dragon's Fall wants you to kill 10 Snowplain Snobolds and 3 Dragonblight Magnataur at the magnataur camps surrounding Wyrmrest.]]}
DB[12145]={id=12145,zoneId=65,name=[[Canyon Chase]],level=73,minLevel=72,giver=[[Kontokanis]],giverType=[[NPC]],giverId=26979,ender=[[Kontokanis]],enderType=[[NPC]],enderId=26979,prevId=12144,wowhead=[[https://www.wowhead.com/wotlk/quest=12145]],image=[[assets/images/quests/placeholder.png]],desc=[[I can't believe dis! Another band of dose vermin just tried ta take off with more of our supplies. Dey're scurrying down da canyon now, get after dem and deal with whoever dey're going to!]],logDesc=[[Kontokanis wants you to chase the snobolds down the canyon south of Dragon's Fall and deal with their leader.]],choiceRewards={{id=37965,qty=1},{id=38007,qty=1},{id=38049,qty=1},{id=38111,qty=1}}}
DB[12146]={id=12146,zoneId=65,name=[[Disturbing Implications]],level=73,minLevel=72,giverType=[[NPC]],ender=[[Aurastrasza]],enderType=[[NPC]],enderId=26983,nextId=12148,rewardNextId=12148,wowhead=[[https://www.wowhead.com/wotlk/quest=12146]],image=[[assets/images/quests/placeholder.png]],desc=[[The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur. Take the horn south down the Path of the Titans to Wyrmrest and seek out someone who might be interested in these threatening implications.]],logDesc=[[Bring the Emblazoned Battle Horn to Wyrmrest and seek out someone who might be interested in assessing the potential threat.]]}
DB[12147]={id=12147,zoneId=65,name=[[Disturbing Implications]],level=73,minLevel=72,giverType=[[NPC]],ender=[[Aurastrasza]],enderType=[[NPC]],enderId=26983,nextId=12148,rewardNextId=12148,wowhead=[[https://www.wowhead.com/wotlk/quest=12147]],image=[[assets/images/quests/placeholder.png]],desc=[[The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur.  Take the horn east across the Dragon Wastes to Wyrmrest and seek out someone who might be interested in these threatening implications.]],logDesc=[[Bring the Emblazoned Battle Horn to Wyrmrest and seek out someone who might be interested in assessing the potential threat.]]}
DB[12148]={id=12148,zoneId=65,name=[[One of a Kind]],level=73,minLevel=72,giver=[[Aurastrasza]],giverType=[[NPC]],giverId=26983,ender=[[Aurastrasza]],enderType=[[NPC]],enderId=26983,rewardNextId=12149,wowhead=[[https://www.wowhead.com/wotlk/quest=12148]],image=[[assets/images/quests/placeholder.png]],desc=[[Such a strange seal to see among magnataur... it suggests an unusual amount of organization. Magnataur rarely put aside their aggressive natures to cooperate with each other.  I suspect they have their eyes set on raiding a large settlement. I very much doubt that this horn is unique, I need you to prove me wrong. In the canyon northwest of the Azure Dragonshrine you will find Bonesunder. Go challenge him and bring me back any evidence you find that might confirm my concerns.]],logDesc=[[Find and kill Bonesunder in or near the canyon northwest of the Azure Dragonshrine. Bring any evidence you find back to Aurastrasza at Wyrmrest Temple.]]}
DB[12149]={id=12149,zoneId=65,name=[[Mighty Magnataur]],level=73,minLevel=72,giver=[[Aurastrasza]],giverType=[[NPC]],giverId=26983,ender=[[Aurastrasza]],enderType=[[NPC]],enderId=26983,prevId=12148,rewardNextId=12150,wowhead=[[https://www.wowhead.com/wotlk/quest=12149]],image=[[assets/images/quests/placeholder.png]],desc=[[Magnataur are hideously violent creatures... this is the main reason we rarely see them come together in any real numbers without killing each other. A powerful leader has stepped up somewhere among them and we need to hunt him down if we are to stop this threat.  I will start asking around. I need you to disrupt them as much as possible in the meantime. East of here there are 3 torches erected. Near them, there are 3 dominant Magnataur - put them down to buy us some time to hunt down this leader.]],logDesc=[[Hunt down and kill Bloodfeast, Iceshatter, and Drakegore east of Wyrmrest Bloodfeast resides in the southeastern corner of the Dragon Wastes, just north of the Emerald Dragonshrine. Iceshatter patrols the northern edge of the Mirror of Dawn. Drakegore wanders at the bottom of the cliffs west of the Bronze Dragonshrine. Return to Aurastrasza at Wyrmrest once the magnataur have been slain.]]}
DB[12150]={id=12150,zoneId=65,name=[[Reclusive Runemaster]],level=74,minLevel=72,giver=[[Aurastrasza]],giverType=[[NPC]],giverId=26983,ender=[[Aurastrasza]],enderType=[[NPC]],enderId=26983,prevId=12149,rewardNextId=12151,wowhead=[[https://www.wowhead.com/wotlk/quest=12150]],image=[[assets/images/quests/placeholder.png]],desc=[[Dregmar Runebrand is a magnataur runemaster... a rare breed. He's generally solitary, but has been known to associate with the more powerful and influential magnataur in Dragonblight for quite some time. He will know who this new leader is.  It is unlikely we will gain any aid with the increasing concerns with the Scourge and the blue flight, so I need you to procure the information from Dregmar by any means necessary. I was told he can be found amongst the cliffs overlooking the Mirror of the Dawn.]],logDesc=[[Locate Dregmar Runebrand near his cave on the path to the cliffs overlooking the Mirror of the Dawn. Challenge him and uncover the name of the magnataur leader by any means necessary. Return to Aurastrasza at Wyrmrest once the information is obtained.]]}
DB[12151]={id=12151,zoneId=65,name=[[Wanton Warlord]],level=74,minLevel=72,giver=[[Aurastrasza]],giverType=[[NPC]],giverId=26983,ender=[[Aurastrasza]],enderType=[[NPC]],enderId=26983,prevId=12150,wowhead=[[https://www.wowhead.com/wotlk/quest=12151]],image=[[assets/images/quests/placeholder.png]],desc=[[There's no reason to suspect Dregmar's words are anything but true. Whether Grom'thar defeats you or is defeated by you, he can wash his hands of this. Follow his instructions... take the horn that you brought me earlier, travel to the ring of torches south of the Azure Dragonshrine, and blow it to announce your challenge. When Grom'thar the Thunderbringer arrives, kill him and bring me his head.]],logDesc=[[Travel to the ring of torches south of the Azure Dragonshrine and blow the Emblazoned Battle Horn. Defeat Grom'thar the Thunderbringer and bring his head back to Aurastrasza at Wyrmrest.]],choiceRewards={{id=38156,qty=1},{id=38157,qty=1},{id=38155,qty=1},{id=38154,qty=1},{id=38130,qty=1},{id=38224,qty=1}}}
DB[12152]={id=12152,zoneId=394,name=[[Jin'arrak's End]],level=75,minLevel=73,giver=[[Kraz]],giverType=[[NPC]],giverId=26886,ender=[[Kraz]],enderType=[[NPC]],enderId=26886,prevId=12137,wowhead=[[https://www.wowhead.com/wotlk/quest=12152]],image=[[assets/images/quests/placeholder.png]],desc=[[It is good to see you back among the living. Many who travel the path of the dead do not return to speak of it. While you were away, a vision appeared to Kraz revealing what remains to be done. A sacred offering lies somewhere inside the crypt. Take this spirit dust fashioned from the remnants you collected and use it on the offering. The infused offering will bring an end to the corrupted warlord and will release the many tormented souls. May the spirits guide your actions, $n.]],logDesc=[[Kraz at Harkor's Camp wants you to collect the Sacred Drakkari Offering from the Drakil'jin Ruins and use the Drakkari Spirit Dust on it. You must use the Infused Drakkari Offering at the gongs outside of Drakil'jin Ruins.]],choiceRewards={{id=39114,qty=1},{id=39125,qty=1},{id=39127,qty=1},{id=39124,qty=1},{id=39113,qty=1},{id=39118,qty=1}}}
DB[12153]={id=12153,zoneId=394,name=[[The Iron Thane and His Anvil]],level=75,minLevel=73,giver=[[Raegar Breakbrow]],giverType=[[NPC]],giverId=26883,ender=[[Raegar Breakbrow]],enderType=[[NPC]],enderId=26883,prevId=12138,wowhead=[[https://www.wowhead.com/wotlk/quest=12153]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you've charged up your war golem, we're going to put all that energy to good use. Activate the golem inside Dun Argol to take control of it. Our  information about Dun Argol's leader, Iron Thane Furyhammer, suggests his bodyguard protects him from all harm. That bodyguard is the construct he travels with, called The Anvil. Disable the construct, and his protection will disappear. The thane stays in the building at the top of Dun Argol and supervises production from the bottom level.]],logDesc=[[Using the abilities of your War Golem, defeat Iron Thane Furyhammer, then return to Raegar Breakbrow at Prospector's Point.]],choiceRewards={{id=38711,qty=1},{id=39015,qty=1},{id=39044,qty=1},{id=39076,qty=1}}}
DB[12154]={id=12154,zoneId=394,name=[[Blackout]],level=75,minLevel=73,giver=[[Raegar Breakbrow]],giverType=[[NPC]],giverId=26883,ender=[[Raegar Breakbrow]],enderType=[[NPC]],enderId=26883,prevId=12138,wowhead=[[https://www.wowhead.com/wotlk/quest=12154]],image=[[assets/images/quests/placeholder.png]],desc=[[The large hall at the top of Dun Argol houses the power source for the entire area. If you can destroy the power core, it will cripple Dun Argol for some time. No power means no golems, no sentries, and no more lightning armaments. When we were sent up here, they told us these explosives were for excavation, but thanks to Iron Thane Furyhammer, the research has been scrapped. We may as well get some use out of them, though. They're the only thing we have on hand capable of destroying the power core.]],logDesc=[[Use Raegar's Explosives to destroy the Runic Power Core at Dun Argol, then report to Raegar Breakbrow at Prospector's Point.]]}
DB[12155]={id=12155,name=[[Smash the Pumpkin]],name_loc=[[Aplasta la calabaza]],level=-1,minLevel=1,giver=[[Large Jack-o'-Lantern]],giver_loc=[[Calabaza iluminada]],giverType=[[GO]],giverId=186887,ender=[[Masked Orphan Matron]],ender_loc=[[Supervisora de huérfanos enmascarada]],enderType=[[NPC]],enderId=23973,poiX=2240,poiY=283,wowhead=[[https://www.wowhead.com/wotlk/quest=12155]],image=[[assets/images/quests/placeholder.png]],desc=[[This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within. Smashing the pumpking reveals an old, scorched holy symbol.]],logDesc=[[Give the Scorched Holy Symbol to the Masked Orphan Matron.]],rewards={{id=34077,qty=1}}}
DB[12156]={id=12156,zoneId=3537,name=[[DEPRECAED]],level=74,minLevel=72,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12156]],image=[[assets/images/quests/placeholder.png]],desc=[[I was meant to set off for Silverbrook, northwest of here, about an hour ago.  My military escort appears to be running late. I'll be damned if this diplomatic mission gets sidetracked because some new recruit overslept. We're negotiating a deal with the locals and timeliness is essential.  What do you say?  If you come with me, you'll be well compensated for your troubles.]],logDesc=[[Escort the Alliance Envoy to the town of Silverbrook.  Report to Lieutenant Dumont at the Amberpine Lodge when you've completed this task.]]}
DB[12157]={id=12157,zoneId=65,name=[[The Lost Courier]],level=72,minLevel=71,giver=[[Private Casey]],giverType=[[NPC]],giverId=26186,ender=[[Courier Lanson]],enderType=[[NPC]],enderId=27060,rewardNextId=12171,wowhead=[[https://www.wowhead.com/wotlk/quest=12157]],image=[[assets/images/quests/placeholder.png]],desc=[[We're lucky we made it this far, $N.  We were ambushed by Scourge as soon as we landed. One of our men turned out to be a spy for the Cult of the Damned.  Thassarian appears to have more evidence of cultist infiltration.  Apparently it goes all the way to the top. I've sent one of my best couriers to our outpost in western Dragonblight, but he has not yet returned. I fear he may have fallen to the Scourge. Will you go to Dragonblight and search for him? Courier Lanson is his name. ]],logDesc=[[Speak to Courier Lanson at Star's Rest in Dragonblight.]]}
DB[12158]={id=12158,zoneId=394,name=[[Hollowstone Mine]],level=75,minLevel=73,giver=[[Captain Gryan Stoutmantle]],giverType=[[NPC]],giverId=26212,ender=[[Petrov]],enderType=[[NPC]],enderId=26932,prevId=12109,rewardNextId=12159,wowhead=[[https://www.wowhead.com/wotlk/quest=12158]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been meaning to send some of our lads to check out Hollowstone Mine.  Haven't had a chance to yet -- we've had our hands full between the Horde on the west and the iron dwarves to the east. If Dumont sent you, though, the least I can do is point you in the right direction. You'll find the mine entrance to the northwest, not far from here.  See if you think operations there can be salvaged.  We sure could use the additional resources until our mine in Farshire is operational again.]],logDesc=[[Look for clues inside Hollowstone Mine northwest of the Westfall Brigade Encampment.]]}
DB[12159]={id=12159,zoneId=394,name=[[Souls at Unrest]],level=75,minLevel=73,giver=[[Petrov]],giverType=[[NPC]],giverId=26932,ender=[[Petrov]],enderType=[[NPC]],enderId=26932,prevId=12158,rewardNextId=12160,wowhead=[[https://www.wowhead.com/wotlk/quest=12159]],image=[[assets/images/quests/placeholder.png]],desc=[[<Petrov looks deeply disturbed, breathing heavily and shifting his gaze nervously around the mine.> My comrades... we must put their souls to rest!  I kill them and kill them but.. they just come back! I've had an idea for a while but I just don't have the heart to do it myself. Maybe you can do this for me?  Take this lantern and use its oil to burn their remains so they never get up again. I'll answer your questions later.  Help my friends first!]],logDesc=[[Petrov at Hollowstone Mine wants you to use the Miner's Lantern to burn the corpses of 8 Hollowstone Miners.]],choiceRewards={{id=38735,qty=1},{id=39034,qty=1},{id=39064,qty=1},{id=39099,qty=1}}}
DB[12160]={id=12160,zoneId=394,name=[[A Name from the Past]],level=75,minLevel=73,giver=[[Petrov]],giverType=[[NPC]],giverId=26932,ender=[[Captain Gryan Stoutmantle]],enderType=[[NPC]],enderId=26212,prevId=12159,wowhead=[[https://www.wowhead.com/wotlk/quest=12160]],image=[[assets/images/quests/placeholder.png]],desc=[[It worked!  It worked!  My comrades can finally enjoy their well-earned rest... I'll stay here and finish the job.  We Hollowstone miners always finish the job -- we never give up! That's why Arugal made an example of us.  We wouldn't fall in line, you see?  We wouldn't join his wolfcult!]],logDesc=[[Return to Captain Gryan Stoutmantle at the Westfall Brigade Encampment.]]}
DB[12161]={id=12161,zoneId=394,name=[[Ruuna the Blind]],level=75,minLevel=73,giver=[[Private Arun]],giverType=[[NPC]],giverId=27582,ender=[[Ruuna the Blind]],enderType=[[NPC]],enderId=27581,nextId=12328,rewardNextId=12328,exGroup=12161,wowhead=[[https://www.wowhead.com/wotlk/quest=12161]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey there.  I overheard what you were saying to the captain and I just want you to know...  things aren't that simple in Northrend. Just because someone's dead it doesn't mean they're out of the picture. Southwest of here, near Vordrassil Pass, lives a blind woman who goes by the name Ruuna the Blind.  They say she speaks to the dead and has visions of the past and future. I haven't heard your whole story but it sounds like she'd be right up your alley.]],logDesc=[[Speak to Ruuna the Blind at Ruuna's Camp near Vordrassil Pass.]]}
DB[12162]={id=12162,zoneId=394,name=[[Solstice Village]],level=75,minLevel=72,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12162]],image=[[assets/images/quests/placeholder.png]]}
DB[12163]={id=12163,zoneId=394,name=[[The Evil Below]],level=75,minLevel=72,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12163]],image=[[assets/images/quests/placeholder.png]]}
DB[12164]={id=12164,zoneId=394,name=[[Hour of the Worg]],level=75,minLevel=73,giver=[[Sasha]],giverType=[[NPC]],giverId=26935,ender=[[Sasha]],enderType=[[NPC]],enderId=26935,prevId=12411,wowhead=[[https://www.wowhead.com/wotlk/quest=12164]],image=[[assets/images/quests/placeholder.png]],desc=[[It is time, then, $N.  Arugal must be defeated. Get a couple of people you can trust and head for Bloodmoon Isle.  It's just off the coast, east of here. We'll hit them fast.  Take out Arugal's lieutenants -- I'll catch up with you when it's time to take out the monster himself.]],logDesc=[[Sasha at the White Pine Trading Post wants you to go to  Bloodmoon Isle and slay Selas, Varlam, Goremaw and the Shade of Arugal.]],choiceRewards={{id=39170,qty=1},{id=39171,qty=1},{id=39169,qty=1},{id=39168,qty=1},{id=39172,qty=1}}}
DB[12165]={id=12165,zoneId=394,name=[[An Intriguing Plan]],level=75,minLevel=73,giver=[[Tormak the Scarred]],giverType=[[NPC]],giverId=27221,ender=[[Prospector Rokar]],enderType=[[NPC]],enderId=27227,prevId=12195,rewardNextId=12196,wowhead=[[https://www.wowhead.com/wotlk/quest=12165]],image=[[assets/images/quests/placeholder.png]],desc=[[Prospector Rokar has decided to help us. He's concocted a plan to use the iron dwarves' strength against them. I must admit, our new 'friend' is more insightful than I'd given him credit for. He's correct in that our numbers are too few for a direct attack. Travel to Dun Argol, in the snowy regions to the southeast, and capture all the parts of their war golem blueprints from the iron rune-smiths there. Bring the assembled blueprint to Rokar and we'll see if his plan has any merit.]],logDesc=[[Bring the completed War Golem Blueprints to Prospector Rokar at Camp Oneqwah.]]}
DB[12166]={id=12166,zoneId=65,name=[[The Liquid Fire of Elune]],level=72,minLevel=71,giver=[[Warden Jodi Moonsong]],giverType=[[NPC]],giverId=26973,ender=[[Warden Jodi Moonsong]],enderType=[[NPC]],enderId=26973,rewardNextId=12167,wowhead=[[https://www.wowhead.com/wotlk/quest=12166]],image=[[assets/images/quests/placeholder.png]],desc=[[$R will you assist me? The Scourge have moved into Icemist to the north. Wherever they go, they spread their taint, and the creatures of the land suffer. Take this vial, which is filled with the liquid fire of Elune from the moonwell. Please, use the liquid to cleanse the corpses of the blighted wildlife that you find.]],logDesc=[[Warden Jodi Moonsong at Stars' Rest has asked you to use the Liquid Fire of Elune to cleanse the corpses of 6 Blighted Elk and 6 Rabid Grizzlies.]]}
DB[12167]={id=12167,zoneId=65,name=[[Kill the Cultists]],level=72,minLevel=71,giver=[[Warden Jodi Moonsong]],giverType=[[NPC]],giverId=26973,ender=[[Warden Jodi Moonsong]],enderType=[[NPC]],enderId=26973,prevId=12166,wowhead=[[https://www.wowhead.com/wotlk/quest=12167]],image=[[assets/images/quests/placeholder.png]],desc=[[The Anub'ar cultists are indirectly responsible for the plaguing of the beasts, and we must put an end to it! The fumes that emit from the cultists' suits seep into everything they come near, poisoning and corrupting their surroundings. You must go north to Icemist Village and slay them. Bring back any of their suits that survive your assault and I will see to it that they are properly disposed of.]],logDesc=[[Collect 5 Functional Cultist Suits for Warden Jodi Moonsong at Stars' Rest.]]}
DB[12168]={id=12168,zoneId=65,name=[[The Favor of Zangus]],level=72,minLevel=71,giverType=[[NPC]],ender=[[Warden Jodi Moonsong]],enderType=[[NPC]],enderId=26973,rewardNextId=12169,wowhead=[[https://www.wowhead.com/wotlk/quest=12168]],image=[[assets/images/quests/placeholder.png]],desc=[[An inscription on the back of the favor reads, "To my favorite pupil, If you continue to show promise, I will teach you wonders beyond your imaginings. If you do not, I will have you destroyed! As ever, High Cultist Zangus" No doubt the warden at Stars' Rest will want to see this.]],logDesc=[[Deliver the Favor of Zangus to Warden Jodi Moonsong at Stars' Rest.]]}
DB[12169]={id=12169,zoneId=65,name=[[The High Cultist]],level=72,minLevel=71,giver=[[Warden Jodi Moonsong]],giverType=[[NPC]],giverId=26973,ender=[[Warden Jodi Moonsong]],enderType=[[NPC]],enderId=26973,prevId=12168,wowhead=[[https://www.wowhead.com/wotlk/quest=12169]],image=[[assets/images/quests/placeholder.png]],desc=[[I have dreamed of Zangus before but without the context that you have discovered, I knew not what it meant. You have brought clarity to the vision that the goddess has bestowed upon me, and now I know that he can be found within the Pit of Narjun to the north. You know your target, $N. If there's to be an end to the suffering of the land, the high cultist must die!]],logDesc=[[Warden Jodi Moonsong at Stars' Rest has asked you to slay High Cultist Zangus.]],choiceRewards={{id=37961,qty=1},{id=38003,qty=1},{id=38045,qty=1},{id=38107,qty=1}}}
DB[12170]={id=12170,zoneId=394,name=[[Blackriver Brawl]],level=74,minLevel=73,giver=[[Raider Captain Kronn]],giverType=[[NPC]],giverId=27120,ender=[[Raider Captain Kronn]],enderType=[[NPC]],enderId=27120,wowhead=[[https://www.wowhead.com/wotlk/quest=12170]],image=[[assets/images/quests/placeholder.png]],desc=[[The Venture Company abandoned operations shortly after we showed up.  Clearly they were afraid of what we were going to do to their greedy little hides. With them gone, their logging camps are up for grabs.  Our war machine is a hungry beast... without renewing our supplies we won't make it to Icecrown. Unfortunately the Alliance seems to have the same idea and we must make sure we're the ones that prevail.  Head into the logging camp and help us fight the Alliance scum.]],logDesc=[[Raider Captain Kronn wants you to slay 10 Alliance units or players at the Blackriver Logging Camp.]],rewards={{id=37836,qty=10}}}
DB[12171]={id=12171,zoneId=65,name=[[Of Traitors and Treason]],level=72,minLevel=71,giver=[[Courier Lanson]],giverType=[[NPC]],giverId=27060,ender=[[Palena Silvercloud]],enderType=[[NPC]],enderId=26881,rewardNextId=12174,exGroup=12171,wowhead=[[https://www.wowhead.com/wotlk/quest=12171]],image=[[assets/images/quests/placeholder.png]],desc=[[The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of Dragonblight. If any of the traitors on this list are stationed at Wintergarde... it could be catastrophic. Hurry, $N. Show the document to Palena Silvercloud here at Stars' Rest and explain the nature of your mission. She will put you on her fastest hippogryph to Wintergarde!]],logDesc=[[Show the Alliance Missive to Palena Silvercloud at Stars' Rest.]]}
DB[12172]={id=12172,name=[[Attunement to Dalaran]],level=73,minLevel=71,giver=[[Image of Archmage Modera]],giverType=[[NPC]],giverId=26673,ender=[[Image of Archmage Modera]],enderType=[[NPC]],enderId=26673,wowhead=[[https://www.wowhead.com/wotlk/quest=12172]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome, mage. By now you must be wondering where Dalaran is and how to get there. I will help you. But before I can teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you risk destroying yourself in the process. Take this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the west. Then you will be ready to learn the spell.]],logDesc=[[The Image of Archmage Modera at Stars' Rest has asked you to become Attuned to the Ley Lines of Northrend.]]}
DB[12173]={id=12173,name=[[Attunement to Dalaran]],level=73,minLevel=71,giver=[[Image of Archmage Aethas Sunreaver]],giverType=[[NPC]],giverId=26471,ender=[[Image of Archmage Aethas Sunreaver]],enderType=[[NPC]],enderId=26471,wowhead=[[https://www.wowhead.com/wotlk/quest=12173]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello, mage. By now you must be wondering where Dalaran is and how to get there. I can help you with this if you can survive a simple test. Before I teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you will destroy yourself in the process! Take this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the southwest. Then you will be ready to learn what I have to teach.]],logDesc=[[The Image of Archmage Aethas Sunreaver at Agmar's Hammer has asked you to become Attuned to the Ley Lines of Northrend.]]}
DB[12174]={id=12174,zoneId=65,name=[[High Commander Halford Wyrmbane]],level=72,minLevel=71,giver=[[Palena Silvercloud]],giverType=[[NPC]],giverId=26881,ender=[[High Commander Halford Wyrmbane]],enderType=[[NPC]],enderId=27136,prevId=12171,rewardNextId=12235,exGroup=12174,wowhead=[[https://www.wowhead.com/wotlk/quest=12174]],image=[[assets/images/quests/placeholder.png]],desc=[[<Palena hands the missive back to you.> Snowstorm will take you to Wintergarde, $N. I guarantee you that it will be the fastest flight you've ever taken. Go now! ]],logDesc=[[Deliver the Alliance Missive to High Commander Halford Wyrmbane at Wintergarde Keep in eastern Dragonblight.  ]]}
DB[12175]={id=12175,zoneId=394,name=[[Gray Worg Hides]],level=74,minLevel=73,giver=[[Hidetrader Jun'ik]],giverType=[[NPC]],giverId=27037,ender=[[Hidetrader Jun'ik]],enderType=[[NPC]],enderId=27037,rewardNextId=12176,wowhead=[[https://www.wowhead.com/wotlk/quest=12175]],image=[[assets/images/quests/placeholder.png]],desc=[[Let me tell you something, mon.  When you get put in charge of outfittin' the armies of the Horde, you go through a lot of hides! Conqueror Krenna, the she-wolf runnin' this place, she gave me a tight deadline.  If I don't outfit her whole regiment by week's end she's gonna have me wrestling bears in the pit. Help me out and I'll pay you top price.  I'll be needin' hides from graymist hunters. You'll find them all around in pockets to the north, hunting stag.  Remember, mon.  Top price!]],logDesc=[[Hidetrader Jun'ik in Conquest Hold wants you to get 3 Gray Worg Hides from Graymist Hunters in the woods to the north.]],choiceRewards={{id=38734,qty=1},{id=39033,qty=1},{id=39060,qty=1},{id=39098,qty=1}}}
DB[12176]={id=12176,zoneId=394,name=[[A Minor Substitution]],level=74,minLevel=73,giver=[[Hidetrader Jun'ik]],giverType=[[NPC]],giverId=27037,ender=[[Hidetrader Jun'ik]],enderType=[[NPC]],enderId=27037,prevId=12175,rewardNextId=12177,wowhead=[[https://www.wowhead.com/wotlk/quest=12176]],image=[[assets/images/quests/placeholder.png]],desc=[[Krenna, she be wantin' worg hides for all the outfits.  There's not gonna be enough worg hides for her army, though.  Not now, not ever. Those worgs -- they be skinny, mon!  Here's what we're gonna do... if you can keep a secret that is. East of Voldrune there be grizzly bears as fat as an ogre.  Those large hides -- those we can use! Hurry, $g brother:sister;.  Krenna's not known for her patience.]],logDesc=[[Hidetrader Jun'ik wants you to bring him 6 Grizzly Hides.]],choiceRewards={{id=38735,qty=1},{id=39034,qty=1},{id=39064,qty=1},{id=39099,qty=1}}}
DB[12177]={id=12177,zoneId=394,name=[[Jun'ik's Coverup]],level=74,minLevel=73,giver=[[Hidetrader Jun'ik]],giverType=[[NPC]],giverId=27037,ender=[[Hidetrader Jun'ik]],enderType=[[NPC]],enderId=27037,prevId=12176,rewardNextId=12178,wowhead=[[https://www.wowhead.com/wotlk/quest=12177]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, we have a small problem.  Grizzly hides... they be brown, mon! Think... think! I got it, mon!  Is like this: gray is black an' white all mixed up.  You get me some coal an' some flour, I'll grind it all up and dust the hides with it.  No one will know the better! Blacksmiths sell coal for smeltin' an' you can get flour from the provisioner.]],logDesc=[[Bring 1 piece of Coal and 5 Simple Flour to Hidetrader Jun'ik at Conquest Hold in Grizzly Hills.]]}
DB[12178]={id=12178,zoneId=394,name=[[Delivery to Krenna]],level=74,minLevel=73,giver=[[Hidetrader Jun'ik]],giverType=[[NPC]],giverId=27037,ender=[[Conqueror Krenna]],enderType=[[NPC]],enderId=26860,prevId=12177,nextId=12427,rewardNextId=12427,exGroup=-12178,wowhead=[[https://www.wowhead.com/wotlk/quest=12178]],image=[[assets/images/quests/placeholder.png]],desc=[[This is it, mon.  Let's take these hides to Krenna and see if they pass the test. Let's hope for both our sakes Krenna doesn't notice anything.]],logDesc=[[Take the Bundle of Hides to Krenna in Conquest Hold.]]}
DB[12179]={id=12179,name=[[Specialization 1 [PH] ]],level=65,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12179]],image=[[assets/images/quests/placeholder.png]],desc=[[DESCRIPTION: Complete this quest for Specialization 1.]],logDesc=[[LOG: Complete this quest for Specialization 1.]]}
DB[12180]={id=12180,zoneId=394,name=[[The Captive Prospectors]],level=75,minLevel=73,giver=[[Mountaineer Kilian]],giverType=[[NPC]],giverId=26885,ender=[[Mountaineer Kilian]],enderType=[[NPC]],enderId=26885,prevId=11993,wowhead=[[https://www.wowhead.com/wotlk/quest=12180]],image=[[assets/images/quests/placeholder.png]],desc=[[Raegar sent a team of prospectors into Dun Argol to search for artifacts and information about the history of the settlement. Raegar's team never expected Dun Argol to be this heavily populated. They're being held captive while the iron dwarves prepare for war. We haven't the men to charge in after them, and Raegar's too busy fantasizing about defeating the irons to be of much help. It falls to you, $N. Any of the irons or their servants could be carrying the keys to the cages holding our men.]],logDesc=[[Free Prospector Gann, Prospector Torgan, and Prospector Varana, then return to Mountaineer Kilian at Prospector's Point.]]}
DB[12181]={id=12181,zoneId=495,name=[[Give it a Name]],level=72,minLevel=71,giver=[[Chief Plaguebringer Harris]],giverType=[[NPC]],giverId=24251,ender=[[Tobias Sarkhoff]],enderType=[[NPC]],enderId=24155,rewardNextId=12182,wowhead=[[https://www.wowhead.com/wotlk/quest=12181]],image=[[assets/images/quests/placeholder.png]],desc=[[My, my, how long has it been? How long have we been working on this damned plague? Finally, after an eternity of failure, we are blessed with perfection. This... It doesn't even have a proper name yet! This blight... That's it, BLIGHT! This blight will tear down the very fabric of life! <Harris hands you a vial.> Now, find the bat handler, Tobias, and show him the specimen. He'll get you on your way to Venomspite. ]],logDesc=[[Show the Blight Specimen to Tobias Sarkhoff at New Agamand. ]]}
DB[12182]={id=12182,zoneId=65,name=[[To Venomspite!]],level=72,minLevel=71,giver=[[Tobias Sarkhoff]],giverType=[[NPC]],giverId=24155,ender=[[Chief Plaguebringer Middleton]],enderType=[[NPC]],enderId=27172,prevId=12181,nextId=12188,rewardNextId=12188,wowhead=[[https://www.wowhead.com/wotlk/quest=12182]],image=[[assets/images/quests/placeholder.png]],desc=[[I got a special bat all lined up for you, buddy. Fastest and smoothest ride I've got. He'll take you right to Venomspite - in style. Just hand that vial over to Chief Plaguebringer Middleton once you land.]],logDesc=[[Deliver the Blight Specimen to Chief Plaguebringer Middleton at Venomspite in eastern Dragonblight.]]}
DB[12183]={id=12183,zoneId=394,name=[[Looking the Part]],level=75,minLevel=73,giver=[[Mountaineer Kilian]],giverType=[[NPC]],giverId=26885,ender=[[Mountaineer Kilian]],enderType=[[NPC]],enderId=26885,prevId=12180,rewardNextId=12184,wowhead=[[https://www.wowhead.com/wotlk/quest=12183]],image=[[assets/images/quests/placeholder.png]],desc=[[If, as Prospector Varana said, only certain irons are permitted to communicate with this Loken, it'll probably be the overseers who have the privilege. We have to get you in there to see what all this is about, but it won't be easy. The first step will be to get a proper uniform for you. Then, we'll worry about doing your makeup. Find one of the overseers at Dun Argol, kill him, and bring back his uniform. If you get blood on it, you'll have only yourself to blame.]],logDesc=[[Bring an Overseer's Uniform to Mountaineer Kilian at Prospector's Point.]]}
DB[12184]={id=12184,zoneId=394,name=[[Cultivating an Image]],level=75,minLevel=73,giver=[[Mountaineer Kilian]],giverType=[[NPC]],giverId=26885,ender=[[Mountaineer Kilian]],enderType=[[NPC]],enderId=26885,prevId=12183,rewardNextId=12185,wowhead=[[https://www.wowhead.com/wotlk/quest=12184]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we've got the uniform, we've got to get enough information to complete your camouflage. Raegar brought along this camera to document the team's finds, but I have a different use in mind. I want you to take it with you to Dun Argol and use it to capture the images of iron dwarves. Of course, your models aren't going to be a cooperative lot, so you may have to, err... subdue them first. Bring back the camera and the images when you're done.]],logDesc=[[Use Kilian's Camera to record the images of 8 Iron Dwarves in Dun Argol, then return to Mountaineer Kilian at Prospector's Point.]]}
DB[12185]={id=12185,zoneId=394,name=[[Put on Your Best Face for Loken]],level=75,minLevel=73,giver=[[Mountaineer Kilian]],giverType=[[NPC]],giverId=26885,ender=[[Mountaineer Kilian]],enderType=[[NPC]],enderId=26885,prevId=12184,wowhead=[[https://www.wowhead.com/wotlk/quest=12185]],image=[[assets/images/quests/placeholder.png]],desc=[[Using the images you've captured, I've created everything you need for your overseer disguise kit. You'll make a fine iron dwarf, if I do say so myself. Take the kit with you to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city. There, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.]],logDesc=[[Disguise yourself as an Iron Rune Overseer, intercept the message from Loken, then report to Mountaineer Kilian at Prospector's Point.]],choiceRewards={{id=38713,qty=1},{id=39017,qty=1},{id=39046,qty=1},{id=39078,qty=1}}}
DB[12186]={id=12186,name=[[FLAG: Winner]],name_loc=[[MARCA: Ganador]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12186]],image=[[assets/images/quests/placeholder.png]]}
DB[12187]={id=12187,name=[[FLAG: Participant]],name_loc=[[MARCA: Participante]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12187]],image=[[assets/images/quests/placeholder.png]]}
DB[12188]={id=12188,zoneId=65,name=[[The Forsaken Blight and You: How Not to Die]],level=72,minLevel=71,giver=[[Chief Plaguebringer Middleton]],giverType=[[NPC]],giverId=27172,ender=[[Chief Plaguebringer Middleton]],enderType=[[NPC]],enderId=27172,rewardNextId=12200,wowhead=[[https://www.wowhead.com/wotlk/quest=12188]],image=[[assets/images/quests/placeholder.png]],desc=[[The details behind the functionality of the blight are hardly important. All you need to know is that it does the job it was designed to do. I have managed to synthesize a strain of the blight that is inert. <Middleton uncorks a vial and inhales.> See, my body is still, mostly, intact. Now mix this with a reactive agent and we'd all be turned to shapeless piles of goo. On the beach south of here you will find pathetic specters of Alliance soldiers past. Slay them and bring me ectoplasmic residue.]],logDesc=[[Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to bring him 10 Ectoplasmic Residue.]],choiceRewards={{id=37963,qty=1},{id=38005,qty=1},{id=38047,qty=1},{id=38109,qty=1}}}
DB[12189]={id=12189,zoneId=65,name=[[Imbeciles Abound!]],level=72,minLevel=71,giver=[[Doctor Sintar Malefious]],giverType=[[NPC]],giverId=26505,ender=[[Chief Plaguebringer Middleton]],enderType=[[NPC]],enderId=27172,nextId=12188,rewardNextId=12188,wowhead=[[https://www.wowhead.com/wotlk/quest=12189]],image=[[assets/images/quests/placeholder.png]],desc=[[The shipment from New Agamand was to arrive at Venomspite last week and then be delivered to me after some simple field tests. It is a Horde imperative - the last piece of the "victory puzzle." <Sintar sighs.> It is quite disheartening to know that you are surrounded by imbeciles and incompetent boobs! You must travel to Venomspite, near the eastern border of Dragonblight. Find that buffoon, Middleton, and let him know that I am waiting on the package.]],logDesc=[[Travel to Venomspite in Dragonblight and speak with Chief Plaguebringer Middleton. ]]}
DB[12190]={id=12190,zoneId=394,name=[[Say Hello to My Little Friend]],level=74,minLevel=73,giver=[[Prigmon]],giverType=[[NPC]],giverId=26519,ender=[[Harkor]],enderType=[[NPC]],enderId=26884,prevId=12483,wowhead=[[https://www.wowhead.com/wotlk/quest=12190]],image=[[assets/images/quests/placeholder.png]],desc=[[Harkor's gunna drop a gold brick when he sees these choice ingredients. All that be left is gettin' them to him. He's camped out on the eastern coast near dem haunted ruins - Drakil'jin, dey be called. You'll likely be makin' it there before I can finish up with these corpses... unless, ya think you'd rather try your hand at embalming?]],logDesc=[[Prigmon wants you to bring Harkor's Ingredients to Harkor at Harkor's Camp.]]}
DB[12195]={id=12195,zoneId=394,name=[[The Unexpected 'Guest']],level=75,minLevel=73,giver=[[Tormak the Scarred]],giverType=[[NPC]],giverId=27221,ender=[[Tormak the Scarred]],enderType=[[NPC]],enderId=27221,rewardNextId=12165,wowhead=[[https://www.wowhead.com/wotlk/quest=12195]],image=[[assets/images/quests/placeholder.png]],desc=[[A recent hunting expedition brought back more than just game. They encountered a wounded dwarf fleeing the iron dwarf stronghold of Dun Argol. He may have information we can use to strike at our ancient enemy, but before he's of any use to us, we must bring down his fever. The horns of the silvercoat stags, who roam the nearby forest, have long been used to make healing poultices. If you can bring enough of the horns to me, we'll see if the poultice can bring our 'guest' around.]],logDesc=[[Bring 5 Mature Stag Horns to Tormak the Scarred at Camp Oneqwah.]]}
DB[12196]={id=12196,zoneId=394,name=[[From the Ground Up]],level=75,minLevel=73,giver=[[Prospector Rokar]],giverType=[[NPC]],giverId=27227,ender=[[Prospector Rokar]],enderType=[[NPC]],enderId=27227,prevId=12195,rewardNextId=12197,wowhead=[[https://www.wowhead.com/wotlk/quest=12196]],image=[[assets/images/quests/placeholder.png]],desc=[[We don't have enough time for me to forge the parts myself, but the foundries over at Dun Argol, to the southeast, are working day and night to churn out golem parts. I think you should go back there and pick up enough of them for me to make a golem from this blueprint. They're probably scattered around any of the buildings where the iron rune-smiths are working. Please hurry, $N. That Tormak looks like he's just waiting for an excuse to carry out his threat!]],logDesc=[[Bring 8 War Golem Parts to Prospector Rokar at Camp Oneqwah.]]}
DB[12197]={id=12197,zoneId=394,name=[[We Have the Power]],level=75,minLevel=73,giver=[[Prospector Rokar]],giverType=[[NPC]],giverId=27227,ender=[[Prospector Rokar]],enderType=[[NPC]],enderId=27227,prevId=12196,rewardNextId=12198,wowhead=[[https://www.wowhead.com/wotlk/quest=12197]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, we've got the shell of a golem, but that's not good enough for Tormak. He doesn't realize that these things don't just come together and miraculously start working! We're going to need power cells to animate it. When I was in Dun Argol, I noticed that Rune-Smith Durar and Rune-Smith Kathorn were the ones who manufactured the cells. We'll need one from each to power our golem. You should be able to find each rune-smith in his workshop on the central level of Dun Argol.]],logDesc=[[Bring Durar's Power Cell and Kathorn's Power Cell to Prospector Rokar at Camp Oneqwah.]]}
DB[12198]={id=12198,zoneId=394,name=[[... Or Maybe We Don't]],level=75,minLevel=73,giver=[[Prospector Rokar]],giverType=[[NPC]],giverId=27227,ender=[[Prospector Rokar]],enderType=[[NPC]],enderId=27227,prevId=12197,rewardNextId=12199,wowhead=[[https://www.wowhead.com/wotlk/quest=12198]],image=[[assets/images/quests/placeholder.png]],desc=[[The golem's cells have just enough power to run it at the lowest levels, but it can't power any of its combat systems. The good news is that the perimeter of Dun Argol is patrolled by lightning sentries. We should be able to use their power to charge up the golem's weapon systems. Bring the golem with you, take it close to them, it will absorb the power as the sentries die.]],logDesc=[[Charge your War Golem with the energy from 10 Lightning Sentries and return to Prospector Rokar at Camp Oneqwah.]]}
DB[12199]={id=12199,zoneId=394,name=[[Bringing Down the Iron Thane]],level=75,minLevel=73,giver=[[Prospector Rokar]],giverType=[[NPC]],giverId=27227,ender=[[Tormak the Scarred]],enderType=[[NPC]],enderId=27221,prevId=12198,wowhead=[[https://www.wowhead.com/wotlk/quest=12199]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that the golem is fully charged, it can be used against the leader at Dun Argol. When I observed Iron Thane Furyhammer, he was always guarded by a personal golem that shielded him from all harm. That construct called The Anvil, can be disrupted, causing him to drop the shield. Use your golem's EMP ability to do just that. You'll be able to activate and take control of your golem inside Dun Argol. The thane is in the main plant at the top and supervises production from the bottom level.]],logDesc=[[Using the abilities of your War Golem, defeat Iron Thane Furyhammer, then return to Tormak the Scarred at Camp Oneqwah.]],choiceRewards={{id=38711,qty=1},{id=39015,qty=1},{id=39044,qty=1},{id=39076,qty=1}}}
DB[12200]={id=12200,zoneId=65,name=[[Emerald Dragon Tears]],level=72,minLevel=71,giver=[[Chief Plaguebringer Middleton]],giverType=[[NPC]],giverId=27172,ender=[[Chief Plaguebringer Middleton]],enderType=[[NPC]],enderId=27172,prevId=12188,rewardNextId=12218,wowhead=[[https://www.wowhead.com/wotlk/quest=12200]],image=[[assets/images/quests/placeholder.png]],desc=[[With an inert specimen of the blight compound complete and the activating agent in hand there only remains a need for a suitable shell to house the components. Southwest of here, on the shores of central Dragonblight, is where you will find the Emerald Dragonshrine. Within the shrine you will find the hardened remnants of a green dragon's tear drop. I don't know the whole story, but apparently they cry a lot right before they die. Go figure. Go to the Emerald Dragonshrine and gather tears.]],logDesc=[[Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to collect 8 Emerald Dragon Tears.]]}
DB[12201]={id=12201,zoneId=394,name=[[The Overseer's Shadow]],level=75,minLevel=73,giver=[[Scout Vor'takh]],giverType=[[NPC]],giverId=26666,ender=[[Scout Vor'takh]],enderType=[[NPC]],enderId=26666,prevId=12204,rewardNextId=12202,wowhead=[[https://www.wowhead.com/wotlk/quest=12201]],image=[[assets/images/quests/placeholder.png]],desc=[[It sounds like this Loken is the mastermind behind the sudden preparations for war on the part of the iron dwarves. Only the highest ranking irons are likely to have access to him, so we'll have to make you into an overseer to find out what's going on in there. I have a plan, for that, but we'll need some supplies. Find one of the iron rune overseers at Dun Argol, to the southeast, kill him, and bring back his uniform.]],logDesc=[[Bring an Overseer's Uniform to Scout Vor'takh at Camp Oneqwah.]]}
DB[12202]={id=12202,zoneId=394,name=[[Cultivating an Image]],level=75,minLevel=73,giver=[[Scout Vor'takh]],giverType=[[NPC]],giverId=26666,ender=[[Scout Vor'takh]],enderType=[[NPC]],enderId=26666,prevId=12201,rewardNextId=12203,wowhead=[[https://www.wowhead.com/wotlk/quest=12202]],image=[[assets/images/quests/placeholder.png]],desc=[[Now we have to finish the job of making you as repulsive as those iron dwarves. The best way to do that is to base your disguise on the ugly mugs of real iron dwarves. When Tormak's hunting party discovered that wayward prospector, they took the camera he carried. Now, I suppose, we'll get the chance to use it. Take it with you to Dun Argol, kill some iron dwarves, and record their likenesses in this device. Bring it back once you have enough examples.]],logDesc=[[Use Rokar's Camera to record the images of 8 Iron Dwarves in Dun Argol, then return to Scout Vor'takh at Camp Oneqwah.]]}
DB[12203]={id=12203,zoneId=394,name=[[Loken's Orders]],level=75,minLevel=73,giver=[[Scout Vor'takh]],giverType=[[NPC]],giverId=26666,ender=[[Scout Vor'takh]],enderType=[[NPC]],enderId=26666,prevId=12202,wowhead=[[https://www.wowhead.com/wotlk/quest=12203]],image=[[assets/images/quests/placeholder.png]],desc=[[I've created everything else you'll need for your overseer disguise kit. Try not to retch when you put it on. I took pains to make it as true to reality as possible. Take the kit with you southeast to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city. There, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.]],logDesc=[[Disguise yourself as an Iron Rune Overseer, intercept the message from Loken, then report to Scout Vor'takh at Camp Oneqwah.]]}
DB[12204]={id=12204,zoneId=394,name=[[In the Name of Loken]],level=75,minLevel=73,giver=[[Scout Vor'takh]],giverType=[[NPC]],giverId=26666,ender=[[Scout Vor'takh]],enderType=[[NPC]],enderId=26666,rewardNextId=12201,wowhead=[[https://www.wowhead.com/wotlk/quest=12204]],image=[[assets/images/quests/placeholder.png]],desc=[[The iron dwarves stand as one of the fiercest and most coordinated foes in Northrend. Wherever we have traveled, they have battled us with the name of Loken on their lips. We must learn who this Loken is and what he seeks. The locals may be of help. To the northeast, at the Redwood Trading Post, a human named Hugh Glass peddles his wares. Further east, at the Ruins of Tethys, you'll find a stone giant named Gavrock. Ask them about this Loken. They've got to know something of use.]],logDesc=[[Speak with Hugh Glass and Gavrock about Loken, then report your findings to Scout Vor'takh at Camp Oneqeah.]]}
DB[12205]={id=12205,zoneId=65,name=[[Wanted: The Scarlet Onslaught]],level=72,minLevel=71,giverType=[[NPC]],ender=[[High Executor Wroth]],enderType=[[NPC]],enderId=27243,wowhead=[[https://www.wowhead.com/wotlk/quest=12205]],image=[[assets/images/quests/placeholder.png]],desc=[[By order of High Executor Wroth all members of the illegal organization known as the Scarlet Onslaught are to be put to death immediately. No quarter is to be offered, and those proceeding to action upon this decree should be aware that any who are captured by the humans will be left to die, or worse! In the High Executor's words, "Paint the snow red with their blood!"]],logDesc=[[Kill 20 members of the Scarlet Onslaught and report to High Executor Wroth at Venomspite.]]}
DB[12206]={id=12206,zoneId=65,name=[[Blighted Last Rites]],level=72,minLevel=71,giver=[[Apothecary Vicky Levine]],giverType=[[NPC]],giverId=27248,ender=[[Apothecary Vicky Levine]],enderType=[[NPC]],enderId=27248,rewardNextId=12211,wowhead=[[https://www.wowhead.com/wotlk/quest=12206]],image=[[assets/images/quests/placeholder.png]],desc=[[Have you read the wanted poster? What is the high executor thinking?! <Vicky looks around and continues in hushed tones.> We can't very well have those Scarlet Onslaught idiots being raised by their priests, or worse, rising as the Scourge, now can we? No, I'm in total agreement with you, we have to do something about the corpses. I have just the thing. Take this blight that we just created and test it on the prisoner in the cage right here. No muss, no fuss, no returning enemies.]],logDesc=[[Apothecary Vicky Levine at Venomspite has asked you to test the Flask of Blight upon the Scarlet Onslaught Prisoner.]]}
DB[12207]={id=12207,zoneId=394,name=[[Vordrassil's Fall]],level=74,minLevel=72,giver=[[Windseer Grayhorn]],giverType=[[NPC]],giverId=27262,ender=[[Windseer Grayhorn]],enderType=[[NPC]],enderId=27262,prevId=12413,wowhead=[[https://www.wowhead.com/wotlk/quest=12207]],image=[[assets/images/quests/placeholder.png]],desc=[[Long ago, powerful druids planted a tree to the northeast of here. It was called Vordrassil and it was to be a world tree.  It is not known why, but after the tree was fully grown, the druids decided it needed to be destroyed. Ever since we arrived here, the earth has spoken to me, $N.  Its cries of pain come from the places where Vordrassil's remains fell on the ground. Corrupting ooze roams those places.  Bring me samples of it so we may begin to heal the land.]],logDesc=[[Windseer Grayhorn in Conquest Hold wants you to go to Vordrassil's Limb, Vordrassil's Heart or Vordrassil's Tears and obtain 6 Slime Samples from the Entropic Oozes.]],choiceRewards={{id=38719,qty=1},{id=39023,qty=1},{id=39052,qty=1},{id=39090,qty=1}}}
DB[12208]={id=12208,zoneId=394,name=[[Good Troll Hunting]],level=74,minLevel=73,giver=[[Sergeant Thurkin]],giverType=[[NPC]],giverId=27266,ender=[[Samir]],enderType=[[NPC]],enderId=26424,nextId=11984,rewardNextId=11984,exGroup=12208,wowhead=[[https://www.wowhead.com/wotlk/quest=12208]],image=[[assets/images/quests/placeholder.png]],desc=[[Good for nothing wretches! They could have had it easy. We extended our hand in peace. All they had to do was give us passage through Drak'Tharon and we'd have let them be. But no, the prideful little ice trolls decided that they wanted it rough. Now they'll be destroyed and we'll pass through their precious keep to Zul'Drak anyway. We've contracted a gang to deliver us captured trolls. Talk to Samir if you want in on the action. You can find him to the northwest of here, due south of Zeb'Halek.]],logDesc=[[Sergeant Thurkin told you to speak to Samir at Granite Springs.]]}
DB[12209]={id=12209,zoneId=65,name=[[Materiel Plunder]],level=72,minLevel=71,giver=[[Quartermaster Bartlett]],giverType=[[NPC]],giverId=27267,ender=[[Quartermaster Bartlett]],enderType=[[NPC]],enderId=27267,wowhead=[[https://www.wowhead.com/wotlk/quest=12209]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah good, new meat. Do you wish to prove yourself, new meat? The Scarlet Onslaught, the most zealous and racist of the Scarlet Crusade, are in our backyard to the south. If we're going to fight them, we'll need more armor and weapons than I can make in such a short time. Why don't we take theirs? More to the point, why don't YOU take theirs?]],logDesc=[[Quartermaster Bartlett at Venomspite has asked you to steal 8 Scarlet Onslaught Armor and 8 Scarlet Onslaught Weapons.]]}
DB[12210]={id=12210,zoneId=394,name=[[Troll Season!]],level=73,minLevel=73,giver=[[Lieutenant Dumont]],giverType=[[NPC]],giverId=26875,ender=[[Samir]],enderType=[[NPC]],enderId=26424,nextId=11984,rewardNextId=11984,exGroup=12210,wowhead=[[https://www.wowhead.com/wotlk/quest=12210]],image=[[assets/images/quests/placeholder.png]],desc=[[You, $r! No sense standing around here when there's work to be done! Drak'Theron Keep is the most direct route to Zul'Drak. We MUST capture it to ensure safe passage for the Alliance. But until we get the numbers to make an assault, we'll have to content ourselves in thinning out the ice trolls and collecting intel. To that end, we've conscripted a gang of thugs to capture and deliver live trolls for interrogation. Travel northwest and speak with Samir at Granite Springs. He'll direct you further.]],logDesc=[[Lieutenant Dumont at Amberpine Lodge wants you to speak to Samir at Granite Springs.]]}
DB[12211]={id=12211,zoneId=65,name=[[Let Them Not Rise!]],level=72,minLevel=71,giver=[[Apothecary Vicky Levine]],giverType=[[NPC]],giverId=27248,ender=[[Apothecary Vicky Levine]],enderType=[[NPC]],enderId=27248,prevId=12206,wowhead=[[https://www.wowhead.com/wotlk/quest=12211]],image=[[assets/images/quests/placeholder.png]],desc=[[I don't understand it. The blight should have worked! No sense worrying about it now. <The apothecary seems relieved for some reason.> Though it doesn't work on the Onslaught for some strange reason, we still need to keep their priests from raising them. I have another idea, one that their corpses shouldn't have any protection from. $N, take a container of my rats and unleash them upon any Onslaught corpses you come across at New Hearthglen. I starve the vermin, so they should be voracious!]],logDesc=[[Apothecary Vicky Levine at Venomspite has asked you to use her Container of Rats to pick clean the corpses of 15 Scarlet Onslaught members at New Hearthglen.]],choiceRewards={{id=37971,qty=1},{id=38014,qty=1},{id=38057,qty=1},{id=38118,qty=1}}}
DB[12212]={id=12212,zoneId=394,name=[[Replenishing the Storehouse]],level=74,minLevel=73,giver=[[Master Woodsman Anderhol]],giverType=[[NPC]],giverId=27277,ender=[[Master Woodsman Anderhol]],enderType=[[NPC]],enderId=27277,rewardNextId=12216,wowhead=[[https://www.wowhead.com/wotlk/quest=12212]],image=[[assets/images/quests/placeholder.png]],desc=[[G'day, $c. The good lieutenant here says that there's been a Horde raid on our storehouse that's left our food supply dangerously low. No doubt we'll make those cretins pay, but first we need to focus our attention on restocking. My men are doing all they can, but we're going to need every able body to contribute if we're to avert a crisis. You should have no trouble harvesting venison from the local stag in these parts. Happy hunting!]],logDesc=[[Master Woodsman Anderhol at Amberpine Lodge wants you to kill Tallhorn Stag and collect 8 Succulent Venison.]]}
DB[12213]={id=12213,zoneId=394,name=[[The Darkness Beneath]],level=74,minLevel=72,giver=[[Windseer Grayhorn]],giverType=[[NPC]],giverId=27262,ender=[[Windseer Grayhorn]],enderType=[[NPC]],enderId=27262,prevId=12413,wowhead=[[https://www.wowhead.com/wotlk/quest=12213]],image=[[assets/images/quests/placeholder.png]],desc=[[Something... dark... happened to the tree Vordrassil.  After the druids decided to destroy it, its hollow remains grew roots deep into the ground. I want you to go to the three locations to the northeast where the tree's trunk shattered and go as far beneath the ground as you can. Use this orb once you get there to get an imprint of the energy surrounding the area.  This might shed some light on what happened to Vordrassil and why it failed to become a world tree.]],logDesc=[[Windseer Grayhorn in Conquest Hold wants you to go to Vordrassil's Heart, Vordrassil's Tears and Vordrassil's Limb and use the Geomancer's Orb in the depths beneath the surface.]]}
DB[12214]={id=12214,zoneId=65,name=[[Fresh Remounts]],level=72,minLevel=71,giver=[[Hansel Bauer]],giverType=[[NPC]],giverId=27028,ender=[[Hansel Bauer]],enderType=[[NPC]],enderId=27028,prevId=12209,wowhead=[[https://www.wowhead.com/wotlk/quest=12214]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello. I am Hansel. Pleased to meet you, $g sir : ma'am;. The high executor came to me and said, 'Hansel, I want you to get us new mounts.' Where does he think dreadsteeds come from? The ground? <whispering> Actually, they do if you can find a horse graveyard. But we don't have one of those, so what we need you to do is go south to New Hearthglen, kill the knights, take their riding crops, and steal their warhorses. Ride the horse back to me here and hand over the reins, if you would.]],logDesc=[[Hansel Bauer at Venomspite has asked you to steal 3 Onslaught Warhorses and deliver them to him, handing over the reins when you do so.]]}
DB[12215]={id=12215,zoneId=394,name=[[Them or Us!]],level=74,minLevel=73,giver=[[Master Woodsman Anderhol]],giverType=[[NPC]],giverId=27277,ender=[[Master Woodsman Anderhol]],enderType=[[NPC]],enderId=27277,rewardNextId=12217,wowhead=[[https://www.wowhead.com/wotlk/quest=12215]],image=[[assets/images/quests/placeholder.png]],desc=[[As if we didn't have enough to concern ourselves with.... With the present food crisis, we find ourselves competing for food with the local worgs. The situation is becoming more dire, and I fear that if we don't address the issue immediately we'll soon find ourselves with nothing to hunt. Scour the forest, $r. Kill any graymist you find. Recent reports have sighted a concentration of them on the other side of the river west of here.]],logDesc=[[Anderhol at Amberpine Lodge wants you to find and kill 6 Graymist Hunters in Grizzly Hills.]]}
DB[12216]={id=12216,zoneId=394,name=[[Take Their Rear!]],level=74,minLevel=73,giver=[[Master Woodsman Anderhol]],giverType=[[NPC]],giverId=27277,ender=[[Master Woodsman Anderhol]],enderType=[[NPC]],enderId=27277,prevId=12212,wowhead=[[https://www.wowhead.com/wotlk/quest=12216]],image=[[assets/images/quests/placeholder.png]],desc=[[We've all been working hard and it's beginning to pay off, but we're still far from our goal. We need much more meat than we have and it's growing clear that the local stag population won't be enough by itself. I'm afraid we need you to turn your attention to more dangerous prey - the grizzlies that give this region its name. They're plentiful, and they're well fed from the abundant fish that swim in these streams. Be safe, $c!]],logDesc=[[Anderhol at Amberpine Lodge wants you to collect 8 Grizzly Flanks from the Grizzly Bears in Grizzly Hills.]]}
DB[12217]={id=12217,zoneId=394,name=[[Eagle Eyes]],level=74,minLevel=73,giver=[[Master Woodsman Anderhol]],giverType=[[NPC]],giverId=27277,ender=[[Master Woodsman Anderhol]],enderType=[[NPC]],enderId=27277,prevId=12215,wowhead=[[https://www.wowhead.com/wotlk/quest=12217]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, $n, we've determined how the Horde was able to locate our hidden stores of food. It turns out that they were binding their sight to the unsuspecting eagles that soar above the trees here. Using eagle vision, they were able to effectively spy on our every action. By order of the lieutenant, we've got to hunt down these majestic birds in order to thwart our enemy.]],logDesc=[[Anderhol in Amberpine Lodge wants you to kill 5 Imperial Eagles and then report back to him.]]}
DB[12218]={id=12218,zoneId=65,name=[[Spread the Good Word]],level=72,minLevel=71,giver=[[Chief Plaguebringer Middleton]],giverType=[[NPC]],giverId=27172,ender=[[Chief Plaguebringer Middleton]],enderType=[[NPC]],enderId=27172,prevId=12200,rewardNextId=12221,wowhead=[[https://www.wowhead.com/wotlk/quest=12218]],image=[[assets/images/quests/placeholder.png]],desc=[[Before I can ship you off to Doctor Malefious with the good news, you will have to run a simple field test of the blight with the modifications I have made. The hungering dead stream out from what remains of Old Wintergarde. Commandeer a vehicle from the east gate and drive it northeast through Vengeance Pass until you reach the twin towers at the southeastern edge of Wintergarde. Drop the blight bomb on the undead that cover the area. Report back to me with the results!]],logDesc=[[Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to use the Forsaken Blight Spreader's Blight Bomb to destroy 30 Hungering Dead on the outskirts of the Carrion Fields.]]}
DB[12219]={id=12219,zoneId=394,name=[[The Failed World Tree]],level=74,minLevel=73,giver=[[Hierophant Thayreen]],giverType=[[NPC]],giverId=27295,ender=[[Hierophant Thayreen]],enderType=[[NPC]],enderId=27295,prevId=12310,nextId=12247,exGroup=-12219,wowhead=[[https://www.wowhead.com/wotlk/quest=12219]],image=[[assets/images/quests/placeholder.png]],desc=[[My ancestors once planted a tree in the middle of the Grizzly Hills. It was called Vordrassil and it was to become a world tree. For reasons long forgotten, after the tree was fully grown, they decided it needed to be destroyed.  Its giant trunk splintered at three locations in the area to the north. Where the tree touched the ground, foul ooze began to crawl the earth.  Bring me slime samples so I can begin my work and the earth can be healed.]],logDesc=[[Hierophant Thayreen at Amberpine Lodge wants you to go to Vordrassil's Limb, Vordrassil's Heart or Vordrassil's Tears and obtain 6 Slime Samples from the Entropic Oozes.]],choiceRewards={{id=38719,qty=1},{id=39023,qty=1},{id=39052,qty=1},{id=39090,qty=1}}}
DB[12220]={id=12220,zoneId=394,name=[[A Dark Influence]],level=74,minLevel=73,giver=[[Hierophant Thayreen]],giverType=[[NPC]],giverId=27295,ender=[[Hierophant Thayreen]],enderType=[[NPC]],enderId=27295,prevId=12310,nextId=12246,exGroup=-12219,wowhead=[[https://www.wowhead.com/wotlk/quest=12220]],image=[[assets/images/quests/placeholder.png]],desc=[[When the tree Vordrassil fell, its hollow remains grew roots deep into the ground. I want you to go north of here to the three locations where the trunk shattered and go as far beneath the ground as you can.  You'll find them west of Grizzlemaw. Use this orb once you get there to get an imprint of the energy surrounding the area.  If we're to heal the land, we must first find out what caused Vordrassil to fail as a world tree all those years ago.]],logDesc=[[Hierophant Thayreen at Amberpine Lodge wants you to go to Vordrassil's Heart, Vordrassil's Tears and Vordrassil's Limb and use the Geomancer's Orb in the depths beneath the surface.]]}
DB[12221]={id=12221,zoneId=65,name=[[The Forsaken Blight]],level=72,minLevel=71,giver=[[Chief Plaguebringer Middleton]],giverType=[[NPC]],giverId=27172,ender=[[Doctor Sintar Malefious]],enderType=[[NPC]],enderId=26505,prevId=12218,wowhead=[[https://www.wowhead.com/wotlk/quest=12221]],image=[[assets/images/quests/placeholder.png]],desc=[[I have prepared a package that must be delivered to Doctor Sintar Malefious at Agmar's Hammer. The contents of the package include the final blight specimen along with instructions on preparation and samples of the reactive agent. You will find Agmar's Hammer in western Dragonblight. Just look for the black, jagged metal orc buildings - that will be Agmar's Hammer. ]],logDesc=[[Deliver The Forsaken Blight to Doctor Sintar Malefious at Agmar's Hammer.]],choiceRewards={{id=38178,qty=1},{id=38177,qty=1},{id=38135,qty=1},{id=38295,qty=1},{id=38176,qty=1},{id=38134,qty=1}}}
DB[12222]={id=12222,zoneId=394,name=[[Secrets of the Flamebinders]],level=74,minLevel=73,giver=[[Woodsman Drake]],giverType=[[NPC]],giverId=27391,ender=[[Woodsman Drake]],enderType=[[NPC]],enderId=27391,prevId=12294,nextId=12225,rewardNextId=12255,exGroup=-12222,wowhead=[[https://www.wowhead.com/wotlk/quest=12222]],image=[[assets/images/quests/placeholder.png]],desc=[[Even as we attempt to fight off the Horde, the Dragonflayer tribe musters in their village of Voldrune, near the coast to the south. The most powerful warriors in the village are granted flame-imbued talismans that give them the ability to control powerful, savage proto-drakes. If we can gain control of one of these drakes, perhaps we can use it to neutralize the threat posed by Voldrune. The Dragonflayer flamebinders create the talismans and imbue them with power. Kill them and take the talismans.]],logDesc=[[Bring 3 Flame-Imbued Talismans to Woodsman Drake at Amberpine Lodge.]]}
DB[12223]={id=12223,zoneId=394,name=[[Thinning the Ranks]],level=74,minLevel=73,giver=[[Woodsman Drake]],giverType=[[NPC]],giverId=27391,ender=[[Woodsman Drake]],enderType=[[NPC]],enderId=27391,prevId=12294,nextId=12225,rewardNextId=12255,exGroup=-12222,wowhead=[[https://www.wowhead.com/wotlk/quest=12223]],image=[[assets/images/quests/placeholder.png]],desc=[[There's a flurry of activity down in Voldrune village to the south. Thane Torvald Eriksson and his huscarls are preparing for war. With most of our men in the field dealing with the Horde's treachery, Amberpine will be vulnerable. Travel to Voldrune, which is near the southern coast, and show those Dragonflayers we're no soft target. Slay as many of the huscarls as you can find. Make them think twice about taking advantage of our conflict with the Horde.]],logDesc=[[Kill 12 Dragonflayer Huscarls and return to Woodsman Drake at Amberpine Lodge.]]}
DB[12224]={id=12224,zoneId=65,name=[[The Kor'kron Vanguard!]],level=73,minLevel=71,giver=[[Overlord Agmar]],giverType=[[NPC]],giverId=26379,ender=[[Saurfang the Younger]],enderType=[[NPC]],enderId=25257,rewardNextId=12496,wowhead=[[https://www.wowhead.com/wotlk/quest=12224]],image=[[assets/images/quests/placeholder.png]],desc=[[You have done well, $g brother:sister;. All that you have faced, you have done as a champion of the Horde. The Scourged Anub'ar of Azjol-Nerub, crushed under your foot! The taunka, brave and powerful new members of the Horde, because of you! Our super-weapon against the Scourge, tested and perfected by you! The time has come, the moment is now - our elite soldiers at the Wrathgate need you. The son of Saurfang awaits your arrival at the Kor'kron Vanguard. Go now, northeast to the Wrathgate.]],logDesc=[[Report to Saurfang the Younger at the Kor'kron Vanguard.]],choiceRewards={{id=38541,qty=1},{id=38543,qty=1},{id=38540,qty=1},{id=38542,qty=1}}}
DB[12225]={id=12225,zoneId=394,name=[[Mmm... Amberseeds!]],level=73,minLevel=73,giverType=[[NPC]],ender=[[Master Woodsman Anderhol]],enderType=[[NPC]],enderId=27277,rewardNextId=12226,wowhead=[[https://www.wowhead.com/wotlk/quest=12225]],image=[[assets/images/quests/placeholder.png]],desc=[[Your stomach growls as the pungent smell of hearty nuts draws your attention to the the bucket of seeds. Some thoughtful soul has obviously left these complimentary morsels here to rejuvenate weary visitors. Grateful, you take the remaining few and devour them. The seeds do not disappoint. Finding yourself hungry for more, you set out to discover their origins....]],logDesc=[[Speak with Master Woodsman Anderhol in Amberpine Lodge.]]}
DB[12226]={id=12226,zoneId=394,name=[[Just Passing Through]],level=73,minLevel=73,giver=[[Master Woodsman Anderhol]],giverType=[[NPC]],giverId=27277,ender=[[Master Woodsman Anderhol]],enderType=[[NPC]],enderId=27277,prevId=12225,rewardNextId=12227,wowhead=[[https://www.wowhead.com/wotlk/quest=12226]],image=[[assets/images/quests/placeholder.png]],desc=[[We must act quickly, $r! We can't risk letting those precious seeds become fully digested. They need to come out, NOW. Forage up some blackroot from the riverbank just west of here and I'll make you a purgative that should get things moving. Hurry now! And remember, you brought this upon yourself....]],logDesc=[[Anderhol at Amberpine Lodge wants you to bring him 5 Blackroot Stalks.]]}
DB[12227]={id=12227,zoneId=394,name=[[Doing Your Duty]],level=73,minLevel=73,giver=[[Master Woodsman Anderhol]],giverType=[[NPC]],giverId=27277,ender=[[Master Woodsman Anderhol]],enderType=[[NPC]],enderId=27277,prevId=12226,wowhead=[[https://www.wowhead.com/wotlk/quest=12227]],image=[[assets/images/quests/placeholder.png]],desc=[[Alright, $r. Here's the juice. It works immediately, so don't use it until you're safely inside the outhouse. Now go get me those seeds!]],logDesc=[[Anderhol in Amberpine Lodge wants you to take the Anderhol's Slider Cider and use the nearby outhouse to retrieve the Partially Processed Amberseeds.]],choiceRewards={{id=38746,qty=1},{id=38745,qty=1},{id=38747,qty=1}}}
DB[12228]={id=12228,name=[[Reacquiring the Magic [PH] ]],name_loc=[[Volver a adquirir la magia [PH] ]],level=60,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],poiX=3982,poiY=-4760,wowhead=[[https://www.wowhead.com/wotlk/quest=12228]],image=[[assets/images/quests/placeholder.png]]}
DB[12229]={id=12229,zoneId=394,name=[[A Possible Link]],level=74,minLevel=72,giver=[[Windseer Grayhorn]],giverType=[[NPC]],giverId=27262,ender=[[Windseer Grayhorn]],enderType=[[NPC]],enderId=27262,wowhead=[[https://www.wowhead.com/wotlk/quest=12229]],image=[[assets/images/quests/placeholder.png]],desc=[[Not long ago we sent an expedition to the east, where it was attacked by crazed furbolgs.  One of the survivors described slaying one of them and its body expelling a dark slimy substance. For thousands of years, the furbolgs in this region have been peaceful.  It is possible that there is a link to the furbolgs' behavior and the dark energy we were able to detect earlier. Bring me samples of the furbolgs' blood.  You will find them to the east in the Rage Fang Shrine and the Heart's Blood Shrine.]],logDesc=[[Windseer Grayhorn in Conquest Hold wants you to obtain 8 Crazed Furbolg Blood from the Furbolgs at Heart's Blood Shrine and Rage Fang Shrine.]],choiceRewards={{id=38726,qty=1},{id=39025,qty=1},{id=39053,qty=1},{id=39091,qty=1}}}
DB[12230]={id=12230,zoneId=65,name=[[Stealing from the Siegesmiths]],level=72,minLevel=71,giver=[[Deathguard Molder]],giverType=[[NPC]],giverId=27320,ender=[[Deathguard Molder]],enderType=[[NPC]],enderId=27320,prevId=12211,rewardNextId=12232,wowhead=[[https://www.wowhead.com/wotlk/quest=12230]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm tasked with the destruction of the Scarlet Onslaught's ballistae. Unfortunately, the apothecaries and I are at odds on the use of our resources, so I've nothing to destroy them with! To the northeast are the Carrion Fields. The Scourge siegesmiths there at their forge and meat wagons are demolition masters. Luckily for us, they also leave their bombs lying about.  I want you to retrieve them for me, off of the ground or the siegesmiths, I don't care which.]],logDesc=[[Deathguard Molder at Venomspite has asked you to retrieve 6 Siegesmith Bombs.]]}
DB[12231]={id=12231,zoneId=394,name=[[The Bear God's Offspring]],level=75,minLevel=72,giver=[[Windseer Grayhorn]],giverType=[[NPC]],giverId=27262,ender=[[Windseer Grayhorn]],enderType=[[NPC]],enderId=27262,wowhead=[[https://www.wowhead.com/wotlk/quest=12231]],image=[[assets/images/quests/placeholder.png]],desc=[[It is possible that the furbolg of Grizzly Hills have the same taint that plagued Vordrassil.  They've been involved in a deadly tribal war recently after years of peaceful coexistence. The shrines that they guard to the east are home to Ursoc's offspring. If the corruption has affected the furbolg, it is possible that because of their lineage, Kodian and Orsonn have remained unharmed. If that's the case, find them and listen to what they have to say.]],logDesc=[[Windseer Grayhorn in Conquest Hold wants you to speak to Orsonn at the Ragefang Shrine and Kodian at the Heart's Blood Shrine.]]}
DB[12232]={id=12232,zoneId=65,name=[[Bombard the Ballistae]],level=72,minLevel=71,giver=[[Deathguard Molder]],giverType=[[NPC]],giverId=27320,ender=[[Deathguard Molder]],enderType=[[NPC]],enderId=27320,prevId=12230,wowhead=[[https://www.wowhead.com/wotlk/quest=12232]],image=[[assets/images/quests/placeholder.png]],desc=[[At last, our chance to strike at their siege engines! Don't flub it. I kid. A little. $C, bombard New Hearthglen's ballistae with these bombs. We'll show the Royal Apothecary Society how it's done old style. No concoctions required!]],logDesc=[[Deathguard Molder at Venomspite has asked you to use the Siegesmith Bombs to bombard 5 New Hearthglen Ballistae.]],choiceRewards={{id=37992,qty=1},{id=37949,qty=1},{id=38284,qty=1}}}
DB[12233]={id=12233,zoneId=394,name=[[[Depricated]Sewing Your Seed]],level=73,minLevel=73,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12233]],image=[[assets/images/quests/placeholder.png]],desc=[[No, no... You hold on to these. You didn't actually expect me to handle them after all of that did you? here's what you're going to do....]]}
DB[12234]={id=12234,zoneId=65,name=[[Need to Know]],level=72,minLevel=71,giver=[[Spy Mistress Repine]],giverType=[[NPC]],giverId=27337,ender=[[Spy Mistress Repine]],enderType=[[NPC]],enderId=27337,prevId=12230,rewardNextId=12239,wowhead=[[https://www.wowhead.com/wotlk/quest=12234]],image=[[assets/images/quests/placeholder.png]],desc=[[I need to know what New Hearthglen is up to. I want you to steal their orders of the day so that I can find that out. Head south and in their abbey, in their barracks, and on their beach, find those daily plans! Just in case you're confused, the barracks is the large building right next to the smithy.]],logDesc=[[Spy Mistress Repine at Venomspite has asked you to steal the Scarlet Onslaught Daily Orders: Abbey, Scarlet Onslaught Daily Orders: Barracks, and Scarlet Onslaught Daily Orders: Beach.]]}
DB[12235]={id=12235,zoneId=65,name=[[Naxxramas and the Fall of Wintergarde]],level=72,minLevel=71,giver=[[High Commander Halford Wyrmbane]],giverType=[[NPC]],giverId=27136,ender=[[Gryphon Commander Urik]],enderType=[[NPC]],enderId=27317,rewardNextId=12237,wowhead=[[https://www.wowhead.com/wotlk/quest=12235]],image=[[assets/images/quests/placeholder.png]],desc=[[Lord Fordragon has led a crushing assault against Arthas at the Wrathgate. In response to this affront, Arthas has sent Naxxramas down upon us. While Kel'Thuzad hides in the floating citadel, his ground commander, Thel'zan, lays siege to Wintergarde Keep. The lower village is already lost and any chance of extracting survivors from the ruins diminishes by the minute. We must act quickly! Report to Gryphon Commander Urik at the gryphon station at once! He'll get you up to speed. Leave me! ]],logDesc=[[Speak with Gryphon Commander Urik at the gryphon station in Wintergarde Keep.]]}
DB[12236]={id=12236,zoneId=394,name=[[Ursoc, the Bear God]],level=75,minLevel=72,giver=[[Windseer Grayhorn]],giverType=[[NPC]],giverId=27262,ender=[[Windseer Grayhorn]],enderType=[[NPC]],enderId=27262,wowhead=[[https://www.wowhead.com/wotlk/quest=12236]],image=[[assets/images/quests/placeholder.png]],desc=[[The time has come, $N.  Now we will learn whether our efforts will accomplish what we need or nothing at all. Take these ashes and seek the furbolg that Kodian told you about, Tur Ragepaw, near Ursoc's Den.  You will find the den to the north of Grizzlemaw. Convince Tur to aid you, for you will need all the help you can get. Once you've defeated the bear god, use these ashes over his body. Even if his worldly form is destroyed, his spirit must be saved.]],logDesc=[[Windseer Grayhorn in Conquest Hold wants you to find Tur Ragepaw near Ursoc's Den and defeat Ursoc with his help.  Use the Purified Ashes of Vordrassil on Ursoc's Corpse when you've accomplished this.]],rewards={{id=39173,qty=1}},choiceRewards={{id=39176,qty=1},{id=39177,qty=1},{id=39178,qty=1},{id=39174,qty=1},{id=39175,qty=1}}}
DB[12237]={id=12237,zoneId=65,name=[[Flight of the Wintergarde Defender]],level=72,minLevel=71,giver=[[Gryphon Commander Urik]],giverType=[[NPC]],giverId=27317,ender=[[Gryphon Commander Urik]],enderType=[[NPC]],enderId=27317,prevId=12235,rewardNextId=12251,wowhead=[[https://www.wowhead.com/wotlk/quest=12237]],image=[[assets/images/quests/placeholder.png]],desc=[[With this whistle you can call down a Wintergarde gryphon. Mount the creature and head towards the ruins of Wintergarde Village, now known as the Carrion Fields, southeast of here. Once at the fields, keep your eyes peeled for helpless Wintergarde villagers. When you spot one, fly low and use the gryphon to pick them up. Return the rescued villager here, to the gryphon station. There are Scourge all over the place so you'll need to keep your wits about you, hero. Good luck!]],logDesc=[[Rescue 10 Helpless Wintergarde Villagers and return to Gryphon Commander Urik at Wintergarde Keep.]]}
DB[12238]={id=12238,zoneId=4196,name=[[Cleansing Drak'Tharon]],level=75,minLevel=73,giver=[[Image of Drakuru]],giverType=[[NPC]],giverId=26500,ender=[[Drakuru]],enderType=[[NPC]],enderId=28016,prevId=12068,nextId=12663,wowhead=[[https://www.wowhead.com/wotlk/quest=12238]],image=[[assets/images/quests/placeholder.png]],desc=[[The time be here at last, good friend. Drak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. My soul will be havin' peace, and in return for your help, the keep's most valuable treasures be yours, mon! Da keep rises up into a sacred ziggurat. Once ya be reachin' its top, ya must summon me a final time, and I'll perform the ritual. Alas, mon, my summonin' will again be comin' at a cost. Ya must collect the mojo from the survivors in the keep,]],logDesc=[[Drakuru wants you to use Drakuru's Elixir at his brazier inside Drak'Tharon. Using Drakuru's Elixir there will require 5 Enduring Mojo.]],choiceRewards={{id=40758,qty=1},{id=40755,qty=1},{id=40757,qty=1},{id=40756,qty=1}}}
DB[12238]={id=12238,zoneId=4196,name=[[Cleansing Drak'Tharon]],level=75,minLevel=73,giver=[[Image of Drakuru]],giverType=[[NPC]],giverId=26787,ender=[[Drakuru]],enderType=[[NPC]],enderId=28016,prevId=12068,nextId=12663,wowhead=[[https://www.wowhead.com/wotlk/quest=12238]],image=[[assets/images/quests/placeholder.png]],desc=[[The time be here at last, good friend. Drak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. My soul will be havin' peace, and in return for your help, the keep's most valuable treasures be yours, mon! Da keep rises up into a sacred ziggurat. Once ya be reachin' its top, ya must summon me a final time, and I'll perform the ritual. Alas, mon, my summonin' will again be comin' at a cost. Ya must collect the mojo from the survivors in the keep,]],logDesc=[[Drakuru wants you to use Drakuru's Elixir at his brazier inside Drak'Tharon. Using Drakuru's Elixir there will require 5 Enduring Mojo.]],choiceRewards={{id=40758,qty=1},{id=40755,qty=1},{id=40757,qty=1},{id=40756,qty=1}}}
DB[12239]={id=12239,zoneId=65,name=[[The Spy in New Hearthglen]],level=72,minLevel=71,giver=[[Spy Mistress Repine]],giverType=[[NPC]],giverId=27337,ender=[[Agent Skully]],enderType=[[NPC]],enderId=27350,prevId=12234,rewardNextId=12254,wowhead=[[https://www.wowhead.com/wotlk/quest=12239]],image=[[assets/images/quests/placeholder.png]],desc=[[I have a spy within the ranks of the Scarlet Onslaught. I need you to deliver these daily orders to her so that she can plan the next phase of our assault. She goes by the name of Agent Skully and she's under a magical guise to appear as the Onslaught's cemetery caretaker. Here, take these orders to her, and then do as she asks. You'll find the graveyard on the side of the abbey.]],logDesc=[[Deliver the Scarlet Onslaught Daily Orders to Agent Skully at New Hearthglen.]]}
DB[12240]={id=12240,zoneId=65,name=[[A Means to an End]],level=72,minLevel=71,giver=[[Apothecary Vicky Levine]],giverType=[[NPC]],giverId=27248,ender=[[Apothecary Vicky Levine]],enderType=[[NPC]],enderId=27248,prevId=12230,rewardNextId=12243,wowhead=[[https://www.wowhead.com/wotlk/quest=12240]],image=[[assets/images/quests/placeholder.png]],desc=[[I received a few barrels of termites from my sister at the Bulwark back home in the last shipment. I think they're going to come in handy for something I have in mind for you. The lumbermill operations at New Hearthglen are problematic for us, but so far we haven't been able to get anyone in there to take out their foreman. I think that if you were to unleash these termites on his precious woodworks, he'd be sure to come running. Ready to take him out, $c?]],logDesc=[[Apothecary Vicky Levine at Venomspite has asked you to use the Levine Family Termites to lure Foreman Kaleiki out and kill him.]]}
DB[12241]={id=12241,zoneId=394,name=[[Destroy the Sapling]],level=75,minLevel=72,giver=[[Windseer Grayhorn]],giverType=[[NPC]],giverId=27262,ender=[[Windseer Grayhorn]],enderType=[[NPC]],enderId=27262,nextId=12236,rewardNextId=12236,exGroup=-12241,wowhead=[[https://www.wowhead.com/wotlk/quest=12241]],image=[[assets/images/quests/placeholder.png]],desc=[[The furbolgs' work must be undone, $N.  The best of intentions do not count for much when the result is tainted by such strong a corruption. The sapling must be destroyed, for it is the source of this dark influence.  Take this torch and use it to set fire to the corrupted sapling and bring me its ashes. Once cleansed, by fire, I will use what power I can to remove the taint from them.  You will need the ashes to purify Ursoc from the evil power that holds sway over him.]],logDesc=[[Windseer Grayhorn in Conquest Hold wants you to take the Verdant Torch and use it to burn Vordrassil's Sapling.  Bring Vordrassil's Ashes back to Windseer Grayhorn.]]}
DB[12242]={id=12242,zoneId=394,name=[[Vordrassil's Seeds]],level=74,minLevel=73,giver=[[Windseer Grayhorn]],giverType=[[NPC]],giverId=27262,ender=[[Windseer Grayhorn]],enderType=[[NPC]],enderId=27262,nextId=12236,rewardNextId=12236,exGroup=-12241,wowhead=[[https://www.wowhead.com/wotlk/quest=12242]],image=[[assets/images/quests/placeholder.png]],desc=[[We must make sure that Vordrassil is never regrown.  The furbolg must have harvested its seed. Go to Grizzlemaw, in central Grizzly Hills, and obtain all the seeds that you can find.  I will make sure they're properly destroyed.]],logDesc=[[Windseer Grayhorn in Conquest Hold wants you to go to Grizzlemaw and obtain 8 of Vordrassil's Seeds.]],choiceRewards={{id=38753,qty=1},{id=38743,qty=1},{id=38757,qty=1}}}
DB[12243]={id=12243,zoneId=65,name=[[Fire Upon the Waters]],level=72,minLevel=71,giver=[[Apothecary Vicky Levine]],giverType=[[NPC]],giverId=27248,ender=[[Apothecary Vicky Levine]],enderType=[[NPC]],enderId=27248,prevId=12240,wowhead=[[https://www.wowhead.com/wotlk/quest=12243]],image=[[assets/images/quests/placeholder.png]],desc=[[I have another mission for you. I was able to repurpose some of the blight to concoct my world-famous burning water. I want you to take it and set the sails of the Sinner's Folly ablaze! Use it from the dock. Once the sails are on fire, the deckhands will be busy putting them out, and you'll slip belowdecks to 'retrieve' the captain's rutters. You'll find the ship on Crusader's Landing, below and south of New Hearthglen. Look for the captain's quarters on the first lower deck, behind the stairs.]],logDesc=[[Apothecary Vicky Levine at Venomspite has asked you to use her Apothecary's Burning Water to set the sails of the Sinner's Folly afire. While the deckhands are busy attempting to put the fires out, head belowdecks and retrieve Captain Shely's Rutters from the captain.]],choiceRewards={{id=37950,qty=1},{id=37993,qty=1},{id=38037,qty=1},{id=38068,qty=1}}}
DB[12244]={id=12244,zoneId=394,name=[[Shredder Repair]],level=74,minLevel=73,giver=[[Synipus]],giverType=[[NPC]],giverId=27371,ender=[[Synipus]],enderType=[[NPC]],enderId=27371,wowhead=[[https://www.wowhead.com/wotlk/quest=12244]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen, pal. Why don't ya roll up your sleeves and grab a wrench? There's work to be done! They need these shredders refurbished and sent down to Venture Bay, and they need it done yesterday.... No wrench? Well what good are ya then? May as well go down with the rest of the lugheads and play with the Horde! While you're there, see if you can drive some of those broken-down shredders up here for repairs. Be careful! They're in pretty bad shape.]],logDesc=[[Synipus at Blue Sky Logging Grounds wants you to bring 3 Broken-down Shredders back to him.]],rewards={{id=37500,qty=1}}}
DB[12245]={id=12245,zoneId=65,name=[[No Mercy for the Captured]],level=72,minLevel=71,giver=[[Spy Mistress Repine]],giverType=[[NPC]],giverId=27337,ender=[[High Executor Wroth]],enderType=[[NPC]],enderId=27243,rewardNextId=12252,wowhead=[[https://www.wowhead.com/wotlk/quest=12245]],image=[[assets/images/quests/placeholder.png]],desc=[[We have more fools for you to kill. My agents tell me that several of our good citizens have seen fit to fall into the hands of the Scarlet Onslaught. This will not do. Go back to New Hearthglen and eliminate Deathguard Schneider, Senior Scrivener Barriga, Engineer Burke and Chancellor Amai. From what I hear, they're spread out throughout the area. No doubt they are being kept in cages awaiting torture. Speak with them and then kill them!]],logDesc=[[Spy Mistress Repine has asked you to slay Deathguard Schneider, Senior Scrivener Barriga, Engineer Burke, and Chancellor Amai. When you've accomplished this task, report your success to High Executor Wroth at Venomspite.]]}
DB[12246]={id=12246,zoneId=394,name=[[A Possible Link]],level=74,minLevel=73,giver=[[Hierophant Thayreen]],giverType=[[NPC]],giverId=27295,ender=[[Hierophant Thayreen]],enderType=[[NPC]],enderId=27295,nextId=12248,exGroup=-12246,wowhead=[[https://www.wowhead.com/wotlk/quest=12246]],image=[[assets/images/quests/placeholder.png]],desc=[[The furbolgs that live east of here are more aggressive and bestial than the ones we're used to.  Our forces have squared off with them more than once, and the survivors always speak of a dark, slimy substance dripping from their corpses. Their condition could be linked with the contaminants we found on Vordrassil's remains. Bring me samples of the furbolgs' blood.  You will find them in the Rage Fang Shrine and the Heart's Blood Shrine, far to the east.]],logDesc=[[Hierophant Thayreen at Amberpine Lodge wants you to obtain 8 Crazed Furbolg Blood from the Furbolgs at Heart's Blood Shrine and Rage Fang Shrine.]],choiceRewards={{id=38726,qty=1},{id=39025,qty=1},{id=39053,qty=1},{id=39091,qty=1}}}
DB[12247]={id=12247,zoneId=394,name=[[Children of Ursoc]],level=75,minLevel=73,giver=[[Hierophant Thayreen]],giverType=[[NPC]],giverId=27295,ender=[[Hierophant Thayreen]],enderType=[[NPC]],enderId=27295,nextId=12250,exGroup=-12246,wowhead=[[https://www.wowhead.com/wotlk/quest=12247]],image=[[assets/images/quests/placeholder.png]],desc=[[The furbolgs of Grizzly Hills carry with them a corruption of some kind, that is for sure.  Tribal war has broken out amongst them after years of peaceful coexistence. What remains to be seen is whether the bears they worship as gods have also been tainted. Ursoc's two children, Orsonn and Kodian, dwell in the Heart's Blood Shrine and the Rage Fang Shrine, south and southeast of Grizzlemaw. See if they will speak to you regarding what has happened here.]],logDesc=[[Hierophant Thayreen at Amberpine Lodge wants you to speak to Orsonn at the Rage Fang Shrine and Kodian at the Heart's Blood Shrine.]]}
DB[12248]={id=12248,zoneId=394,name=[[Vordrassil's Sapling]],level=75,minLevel=73,giver=[[Hierophant Thayreen]],giverType=[[NPC]],giverId=27295,ender=[[Hierophant Thayreen]],enderType=[[NPC]],enderId=27295,nextId=12249,rewardNextId=12249,exGroup=-12248,wowhead=[[https://www.wowhead.com/wotlk/quest=12248]],image=[[assets/images/quests/placeholder.png]],desc=[[The druids of old seem to have had good reasons for destroying Vordrassil.  We cannot let the furbolgs regrow it. On the other hand, saving Ursoc's spirit hinges on the magic contained by the sapling. Take this torch and use it to burn the tree.  You will find it in the middle of Grizzlemaw, inside Vordrassil's old trunk. Bring me Vordrassil's ashes.  It is my hope that once purified by fire, we may use its magic to cleanse Ursoc's spirit of its dark taint.]],logDesc=[[Hierophant Thayreen in Amberpine Lodge wants you to take the Verdant Torch and use it to burn Vordrassil's Sapling.  Bring Vordrassil's Ashes back to Hierophant Thayreen.]]}
DB[12249]={id=12249,zoneId=394,name=[[Ursoc, the Bear God]],level=75,minLevel=73,giver=[[Hierophant Thayreen]],giverType=[[NPC]],giverId=27295,ender=[[Hierophant Thayreen]],enderType=[[NPC]],enderId=27295,wowhead=[[https://www.wowhead.com/wotlk/quest=12249]],image=[[assets/images/quests/placeholder.png]],desc=[[It is time, $N.  Take these ashes and look for the furbolg that Kodian spoke of.  If he went to seek Ursoc, he will be near his den, north of Grizzlemaw. You will need his help.  You won't be able to defeat Ursoc alone. Once you've defeated Ursoc, use these ashes to purify his spirit.  Only then will we know whether our efforts have been in vain or not.]],logDesc=[[Hierophant Thayreen at Amberpine Lodge wants you to find Tur Ragepaw near Ursoc's Den and defeat Ursoc with his help.  Use the Purified Ashes of Vordrassil on Ursoc's Corpse when you've accomplished this.]],rewards={{id=39173,qty=1}},choiceRewards={{id=39176,qty=1},{id=39177,qty=1},{id=39178,qty=1},{id=39174,qty=1},{id=39175,qty=1}}}
DB[12250]={id=12250,zoneId=394,name=[[Vordrassil's Seeds]],level=75,minLevel=73,giver=[[Hierophant Thayreen]],giverType=[[NPC]],giverId=27295,ender=[[Hierophant Thayreen]],enderType=[[NPC]],enderId=27295,nextId=12249,rewardNextId=12249,exGroup=-12248,wowhead=[[https://www.wowhead.com/wotlk/quest=12250]],image=[[assets/images/quests/placeholder.png]],desc=[[We cannot allow Vordrassil to grow again.  If the furbolg regrew it once, they can do it again. Go to Grizzlemaw, in central Grizzly Hills, and obtain Vordrassil's seeds.  I will make sure they're properly disposed of.]],logDesc=[[Hierophant Thayreen at Amberpine Lodge wants you to go to Grizzlemaw and obtain 8 of Vordrassil's Seeds.]],choiceRewards={{id=38753,qty=1},{id=38743,qty=1},{id=38757,qty=1}}}
DB[12251]={id=12251,zoneId=65,name=[[Return to the High Commander]],level=72,minLevel=71,giver=[[Gryphon Commander Urik]],giverType=[[NPC]],giverId=27317,ender=[[High Commander Halford Wyrmbane]],enderType=[[NPC]],enderId=27136,prevId=12237,rewardNextId=12253,wowhead=[[https://www.wowhead.com/wotlk/quest=12251]],image=[[assets/images/quests/placeholder.png]],desc=[[Return to High Commander Halford Wyrmbane at once, $N. Let him know that your mission was a success and that the few remaining villagers that were rescued are back to work.]],logDesc=[[Speak with High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.]],choiceRewards={{id=37956,qty=1},{id=37998,qty=1},{id=38041,qty=1},{id=38102,qty=1}}}
DB[12252]={id=12252,zoneId=65,name=[[Torture the Torturer]],level=72,minLevel=71,giver=[[High Executor Wroth]],giverType=[[NPC]],giverId=27243,ender=[[High Executor Wroth]],enderType=[[NPC]],enderId=27243,prevId=12245,wowhead=[[https://www.wowhead.com/wotlk/quest=12252]],image=[[assets/images/quests/placeholder.png]],desc=[[Enough! I want you to put an end to the torture of my people! The Onslaught's torturer, LeCraft, has been bleeding information out of everyone that gets caught by those fiends! I need to know what they know. My sources tell me that he has set up shop in the basement of their barracks, which is right next to the smithy. I'll loan you my personal branding iron to see to it that the job is done right. Find him and get that information.]],logDesc=[[High Executor Wroth at Venomspite wants you to use the branding iron 5 times on Torturer LeCraft to get the information out of him. After that, kill him.]],choiceRewards={{id=37953,qty=1},{id=37995,qty=1},{id=38039,qty=1},{id=38100,qty=1}}}
DB[12253]={id=12253,zoneId=65,name=[[Rescue from Town Square]],level=72,minLevel=71,giver=[[High Commander Halford Wyrmbane]],giverType=[[NPC]],giverId=27136,ender=[[High Commander Halford Wyrmbane]],enderType=[[NPC]],enderId=27136,prevId=12251,rewardNextId=12309,wowhead=[[https://www.wowhead.com/wotlk/quest=12253]],image=[[assets/images/quests/placeholder.png]],desc=[[Just down this path here is Wintergarde's town square. Once a hive of activity for the citizens of Wintergarde, now a warzone, filled with murderous geists hell-bent on vengeance towards the living. In the buildings surrounding the town square are trapped villagers that must be rescued! I ask much of you, now, $N, but you are the only soldier I can spare. Free our people. Take this path down into town square and enter those houses. Kill anything that gets in your way! Return to me should you survive.]],logDesc=[[High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight wants you to rescue 6 Trapped Wintergarde Villagers.]]}
DB[12254]={id=12254,zoneId=65,name=[[Without a Prayer]],level=72,minLevel=71,giver=[[Agent Skully]],giverType=[[NPC]],giverId=27350,ender=[[Agent Skully]],enderType=[[NPC]],enderId=27350,prevId=12239,rewardNextId=12260,wowhead=[[https://www.wowhead.com/wotlk/quest=12254]],image=[[assets/images/quests/placeholder.png]],desc=[[These plans indicate something imminent is being planned. But first, there's the matter of this strange protection that the Onslaught forces have. If Venomspite is to deal with them once and for all, we must find out who's behind it and eliminate them. I've noticed that the bishop in the chapel on the far side of New Hearthglen, across from the lumbermill, has stepped up his blessing of the troops. Kill him and steal his prayer book. Maybe it will give us a clue.]],logDesc=[[Agent Skully at New Hearthglen has asked you to acquire Bishop Street's Prayer Book.]]}
DB[12255]={id=12255,zoneId=394,name=[[The Thane of Voldrune]],level=74,minLevel=73,giver=[[Woodsman Drake]],giverType=[[NPC]],giverId=27391,ender=[[Woodsman Drake]],enderType=[[NPC]],enderId=27391,prevId=12222,wowhead=[[https://www.wowhead.com/wotlk/quest=12255]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you've captured the flame-imbued talismans and weakened Voldrune's defenses, we can strike at its leader, Thane Torvald Eriksson. The thane's favorite mount is an unruly proto-drake he calls Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the talismans, you should be able to control it long enough to use it against the thane. Once you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and show him no mercy.]],logDesc=[[Use Flamebringer to defeat Thane Torvald Eriksson and report to Woodsman Drake at Amberpine Lodge.]],choiceRewards={{id=38712,qty=1},{id=39016,qty=1},{id=39045,qty=1},{id=39077,qty=1},{id=38749,qty=1}}}
DB[12256]={id=12256,zoneId=394,name=[[The Flamebinders' Secrets]],level=74,minLevel=73,giver=[[Sergeant Nazgrim]],giverType=[[NPC]],giverId=27388,ender=[[Sergeant Nazgrim]],enderType=[[NPC]],enderId=27388,nextId=12259,rewardNextId=12259,exGroup=-12256,wowhead=[[https://www.wowhead.com/wotlk/quest=12256]],image=[[assets/images/quests/placeholder.png]],desc=[[Even as the Alliance cowards attack our positions, the Dragonflayer vrykul outpost of Voldrune, to the southeast, prepares for war. The vrykul are far from the strongest enemy we face here, but we must eliminate them before they can truly threaten us. Their most powerful warriors are permitted to ride half-trained proto-drakes into battle. To control the beasts, their flamebinders create powerful talismans. You'll need to slay them and take the talismans if our plan is to work.]],logDesc=[[Bring 3 Flame-Imbued Talismans to Sergeant Nazgrim at Conquest Hold.]]}
DB[12257]={id=12257,zoneId=394,name=[[A Show of Strength]],level=74,minLevel=73,giver=[[Sergeant Nazgrim]],giverType=[[NPC]],giverId=27388,ender=[[Sergeant Nazgrim]],enderType=[[NPC]],enderId=27388,nextId=12259,rewardNextId=12259,exGroup=-12256,wowhead=[[https://www.wowhead.com/wotlk/quest=12257]],image=[[assets/images/quests/placeholder.png]],desc=[[Preparations for war are underway in the vrykul village of Voldrune to the southeast. Voldrune's thane cannot field a large army, but with our forces spread thin, we are still at risk. We cannot risk giving the thane and his men an opportunity to attack, so we must take the battle to them. If you are truly a $c of the Horde, you will relish the chance to demonstrate our strength. Cut down the huscarls and prove to this Dragonflayer clan that the Horde is not to be trifled with!]],logDesc=[[Kill 12 Dragonflayer Huscarls and return to Sergeant Nazgrim at Conquest Hold.]]}
DB[12258]={id=12258,zoneId=65,name=[[The Fate of the Dead]],level=72,minLevel=71,giver=[[Commander Lynore Windstryke]],giverType=[[NPC]],giverId=27155,ender=[[Commander Lynore Windstryke]],enderType=[[NPC]],enderId=27155,wowhead=[[https://www.wowhead.com/wotlk/quest=12258]],image=[[assets/images/quests/placeholder.png]],desc=[[The town square, down this path, is overrun with the undead citizens of Wintergarde! Our own crypt provides a seemingly endless supply of soldiers for the Scourge to throw at us. Take no pity on them, though, $N. While they were once mortal, capable of compassion and thought, they are now ravaging undead with only one purpose: our destruction. Venture forth to the town square and deliver the vengeful geists to their maker. Give them peace.]],logDesc=[[Commander Lynore Windstryke at Wintergarde Keep in Dragonblight wants you to kill 15 Vengeful Geists. ]],choiceRewards={{id=37954,qty=1},{id=37996,qty=1},{id=38040,qty=1},{id=38101,qty=1}}}
DB[12259]={id=12259,zoneId=394,name=[[The Thane of Voldrune]],level=74,minLevel=73,giver=[[Sergeant Nazgrim]],giverType=[[NPC]],giverId=27388,ender=[[Sergeant Nazgrim]],enderType=[[NPC]],enderId=27388,rewardNextId=12412,wowhead=[[https://www.wowhead.com/wotlk/quest=12259]],image=[[assets/images/quests/placeholder.png]],desc=[[With the flame-imbued talismans, we can finally challenge the thane. His favorite mount is a ferocious proto-drake called Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the power of the talismans, you should be able to bend it to your will and use it against the thane. Once you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and use Flamebringer to destroy him.]],logDesc=[[Use Flamebringer to defeat Thane Torvald Eriksson and report to Sergeant Nazgrim at Conquest Hold.]],choiceRewards={{id=38712,qty=1},{id=39016,qty=1},{id=39045,qty=1},{id=39077,qty=1},{id=38749,qty=1}}}
DB[12260]={id=12260,zoneId=65,name=[[The Perfect Dissemblance]],level=72,minLevel=71,giver=[[Agent Skully]],giverType=[[NPC]],giverId=27350,ender=[[Agent Skully]],enderType=[[NPC]],enderId=27350,prevId=12254,rewardNextId=12274,wowhead=[[https://www.wowhead.com/wotlk/quest=12260]],image=[[assets/images/quests/placeholder.png]],desc=[[You may wonder how I can maintain this guise; I use a magic mirror that was loaned to me by the spy mistress. It only has so much power in it, but I think there's enough for the both of us. Here, take it. I want you to use it to impersonate one of the Onslaught raven priests. Be quick about it... I have no idea how long my glamour will last while you have the mirror. Realize that you won't immediately be perfectly disguised, so don't count on it being foolproof until I've had a chance to help you.]],logDesc=[[Agent Skully at New Hearthglen has asked you steal the image of a Onslaught Raven Priest. Return the Banshee's Magic Mirror to her when you have done so.]]}
DB[12261]={id=12261,zoneId=65,name=[[No Place to Run]],level=74,minLevel=72,giver=[[Serinar]],giverType=[[NPC]],giverId=26593,ender=[[Serinar]],enderType=[[NPC]],enderId=26593,prevId=12447,rewardNextId=12263,wowhead=[[https://www.wowhead.com/wotlk/quest=12261]],image=[[assets/images/quests/placeholder.png]],desc=[[They're drawing power from the bones of my dead brothers... I have no love for the cult, but I'm baffled by their audacity. There will be no mercy shown for them... not that I ever would have anyway. Ensure that they have no place to flee when the slaughter starts. Place a destructive ward at the end of the path leading out of the shrine... where the road starts to give way to snow. Defend it until it is fully charged.]],logDesc=[[Place a Destructive Ward at the end of the path leading out of Obsidian Dragonshrine, where the road starts to give way to snow. Protect the ward until it is fully charged, then return to Serinar.]]}
DB[12262]={id=12262,zoneId=65,name=[[No One to Save You]],level=74,minLevel=72,giver=[[Serinar]],giverType=[[NPC]],giverId=26593,ender=[[Serinar]],enderType=[[NPC]],enderId=26593,prevId=12447,wowhead=[[https://www.wowhead.com/wotlk/quest=12262]],image=[[assets/images/quests/placeholder.png]],desc=[[We will spare no one.  Outside, lowly necrolytes and their skeletal servants shame my land with their presence. Slaughter them all.]],logDesc=[[Kill 6 Burning Depths Necrolytes and 10 Smoldering Skeletons outside of the Obsidian Dragonshrine. Return to Serinar once the task is complete.]]}
DB[12263]={id=12263,zoneId=65,name=[[The Best of Intentions]],level=74,minLevel=72,giver=[[Serinar]],giverType=[[NPC]],giverId=26593,ender=[[Serinar]],enderType=[[NPC]],enderId=26593,prevId=12261,wowhead=[[https://www.wowhead.com/wotlk/quest=12263]],image=[[assets/images/quests/placeholder.png]],desc=[[The Cult of the Damned has not come just to extract power from dead dragons. I suspect I know what they are up to, but I need you to prove me correct. I will grant you the guise of this dead necrolyte. Proceed to the back of the cave and confirm their intentions for being in this sacred place. I will watch through your eyes.  Be cautious $N, any damage done to you is likely to break the fragile illusion.]],logDesc=[[Wait for Serinar to administer the disguise of a Burning Depths Necrolyte, then proceed to the back of the Maw of Neltharion to uncover what the Cult of the Damned is doing there. Return to Serinar with details regarding their purpose.]]}
DB[12264]={id=12264,zoneId=65,name=[[Culling the Damned]],level=74,minLevel=72,giver=[[Serinar]],giverType=[[NPC]],giverId=26593,ender=[[Serinar]],enderType=[[NPC]],enderId=26593,prevId=12263,wowhead=[[https://www.wowhead.com/wotlk/quest=12264]],image=[[assets/images/quests/placeholder.png]],desc=[[The cave beyond was swarming with Cult atrocities. There is only one way to deal with such creatures... you know what to do.]],logDesc=[[Kill 3 Burning Depths Necromancers, 6 Smoldering Constructs, and 6 Smoldering Geist in the Maw of Neltharion, and then return to Serinar.]]}
DB[12265]={id=12265,zoneId=65,name=[[Defiling the Defilers]],level=74,minLevel=72,giver=[[Serinar]],giverType=[[NPC]],giverId=26593,ender=[[Serinar]],enderType=[[NPC]],enderId=26593,prevId=12263,rewardNextId=12267,wowhead=[[https://www.wowhead.com/wotlk/quest=12265]],image=[[assets/images/quests/placeholder.png]],desc=[[I sensed a large accumulation of magic in the runes that we witnessed when you were scouting the cave. I will not have you toy with extracting the magic... often the most straight forward solution is the most effective one. Destroy the runes... stamp them out and ensure that the Cult will not have access to whatever power that they've accumulated there.]],logDesc=[[Locate and stamp out 8 Necromantic Runes that have been drawn on the floor inside the Maw of Neltharion. Return to Serinar once the task is complete.]]}
DB[12266]={id=12266,zoneId=65,name=[[Tales of Destruction]],level=74,minLevel=72,giver=[[Serinar]],giverType=[[NPC]],giverId=26593,ender=[[Nalice]],enderType=[[NPC]],enderId=27765,prevId=12267,wowhead=[[https://www.wowhead.com/wotlk/quest=12266]],image=[[assets/images/quests/placeholder.png]],desc=[[You can leave now, $r. Go tell Nalice she missed out on a good slaughter.]],logDesc=[[Travel back to Wyrmrest and let Nalice know that Serinar's task is complete.]]}
DB[12267]={id=12267,zoneId=65,name=[[Neltharion's Flame]],level=75,minLevel=72,giver=[[Serinar]],giverType=[[NPC]],giverId=26593,ender=[[Serinar]],enderType=[[NPC]],enderId=26593,prevId=12265,rewardNextId=12266,wowhead=[[https://www.wowhead.com/wotlk/quest=12267]],image=[[assets/images/quests/placeholder.png]],desc=[[With the cult's ranks thinned and some of their power stripped, it's time to strike at the source of the corruption. Rothin the Decaying is resurrecting black dragons as magmawyrms in the back of the cave. Go to the summoning chamber and cleanse the remaining bones in the only way that will ensure that they will never be toyed with again... with flame. Burning the bones will surely gain Rothin's attention, see to it that he is destroyed as well. The magic in this vial should see the task done.]],logDesc=[[Use Neltharion's Flame to douse the summoning area in the back of the Maw of Neltharion. Once you get the attention of Rothin the Decaying, kill him, then return to Serinar at the front of the cave.]],choiceRewards={{id=37944,qty=1},{id=38032,qty=1},{id=38095,qty=1},{id=37988,qty=1}}}
DB[12268]={id=12268,zoneId=394,name=[[Pieces Parts]],level=74,minLevel=73,giver=[[Pipthwack]],giverType=[[NPC]],giverId=27416,ender=[[Pipthwack]],enderType=[[NPC]],enderId=27416,wowhead=[[https://www.wowhead.com/wotlk/quest=12268]],image=[[assets/images/quests/placeholder.png]],desc=[[Ack! This thing's a mess! Goblin engineering leaves a great deal to be desired, believe you me. Just look at this! It's a wonder it ever worked to begin with. Give me a hand, will ya? To get this even close to operable specifications I'll need to replace a few cogs, sprockets, and springs. You should have no trouble finding them down around the sawmill.]],logDesc=[[Pipthwack in Blue Sky Logging Grounds wants you to collect 4 Grooved Cogs, 3 Notched Sprockets, and 2 High Tension Springs.]]}
DB[12269]={id=12269,zoneId=65,name=[[Not In Our Mine]],level=72,minLevel=71,giver=[[Highlord Leoric Von Zeldig]],giverType=[[NPC]],giverId=27156,ender=[[Highlord Leoric Von Zeldig]],enderType=[[NPC]],enderId=27156,prevId=12251,wowhead=[[https://www.wowhead.com/wotlk/quest=12269]],image=[[assets/images/quests/placeholder.png]],desc=[[That blasted necropolis blindsided us! In the wake of its destruction Wintergarde Mine was lost. Worse yet, Kel'Thuzad's acolytes have raised the slain miners as Scourge and are using them to supply their siegesmiths with materials from our mine! The supply line must be halted and our lost brothers must be put to rest. Travel to Wintergarde Mine, northeast of here in the Carrion Fields, and destroy the risen miners. Return to me with their miner cards so that I may put their passing in our registry.]],logDesc=[[Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight wants you to recover 10 Wintergarde Miner's Cards.]]}
DB[12270]={id=12270,zoneId=394,name=[[Shred the Alliance]],level=74,minLevel=73,giver=[[Grekk]],giverType=[[NPC]],giverId=27423,ender=[[Grekk]],enderType=[[NPC]],enderId=27423,wowhead=[[https://www.wowhead.com/wotlk/quest=12270]],image=[[assets/images/quests/placeholder.png]],desc=[[Read my lips, $c - I need those shredders! Just as important - I need to keep them out of the hands of the Alliance! They've been refurbishing the shredders and using them against our brothers in Venture Bay. Now we're going to give them a taste of their own medicine! You see a shredder out there, grab it! You see one of the Alliance scum on one, kill 'em and then grab it! Once you have one, drive it back here to me and we'll get to work on it. Dismissed!]],logDesc=[[Grekk at Blue Sky Logging Grounds wants you to acquire 3 shredders and return to him with them.]],rewards={{id=37500,qty=1}}}
DB[12271]={id=12271,zoneId=65,name=[[The Rod of Compulsion]],level=72,minLevel=71,giverType=[[NPC]],ender=[[High Executor Wroth]],enderType=[[NPC]],enderId=27243,rewardNextId=12273,wowhead=[[https://www.wowhead.com/wotlk/quest=12271]],image=[[assets/images/quests/placeholder.png]],desc=[[A rod drops from LeCraft's dead hand. There are pulsing magical runes along its length. Could this be how he was getting his confessions? Better let the high executor have a look at it.]],logDesc=[[Deliver the Torturer's Rod to High Executor Wroth at Venomspite.]]}
DB[12272]={id=12272,zoneId=65,name=[[The Bleeding Ore]],level=72,minLevel=71,giver=[[Siege Engineer Quarterflash]],giverType=[[NPC]],giverId=27159,ender=[[Siege Engineer Quarterflash]],enderType=[[NPC]],enderId=27159,prevId=12251,nextId=12281,exGroup=-12272,wowhead=[[https://www.wowhead.com/wotlk/quest=12272]],image=[[assets/images/quests/placeholder.png]],desc=[[Hours before the Naxxramas invasion, one of the miners stumbled upon a dark ore that was oozing a viscous fluid. In the chaos that occurred during the evacuation of the mine, we lost the samples taken from the alien node. Now the Scourge prospects the ore for use in their machines of death. You must get back to Wintergarde Mine, due northeast of here in the Carrion Fields, and recover the strange ore. It is imperative to our mission's success!]],logDesc=[[Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight wants you to recover 10 samples of Strange Ore from Wintergarde Mine.]]}
DB[12273]={id=12273,zoneId=65,name=[[The Denouncement]],level=73,minLevel=71,giver=[[High Executor Wroth]],giverType=[[NPC]],giverId=27243,ender=[[High Executor Wroth]],enderType=[[NPC]],enderId=27243,prevId=12271,wowhead=[[https://www.wowhead.com/wotlk/quest=12273]],image=[[assets/images/quests/placeholder.png]],desc=[[It's time for us to utterly demoralize the Onslaught forces! I want you to take the rod and use it on four of their leaders: Commander Jordan upstairs at the barracks, Lead Cannoneer Zierhut down the southeast ramp overlooking the beach, Blacksmith Goodman at the smithy, and Stable Master Mercer at the stables. Place them under the rod's compulsion, concentrate on making them denounce the Onslaught, and then kill them!]],logDesc=[[High Executor Wroth at Venomspite has tasked you with using the Rod of Compulsion on Commander Jordan, Lead Cannoneer Zierhut, Blacksmith Goodman, and Stable Master Mercer. Once the rod has been used on them, kill each to exact a denouncement of the Scarlet Onslaught as their final words.]],choiceRewards={{id=37968,qty=1},{id=38011,qty=1},{id=38054,qty=1},{id=38115,qty=1}}}
DB[12274]={id=12274,zoneId=65,name=[[A Fall From Grace]],level=73,minLevel=71,giver=[[Agent Skully]],giverType=[[NPC]],giverId=27350,ender=[[Agent Skully]],enderType=[[NPC]],enderId=27350,prevId=12260,rewardNextId=12283,wowhead=[[https://www.wowhead.com/wotlk/quest=12274]],image=[[assets/images/quests/placeholder.png]],desc=[[We need more information from the high abbot, and now that we have the visage of one of the raven priests, I think we can get you close to talk with him. Unfortunately, we need to separate him from his bodyguards or you'll never get any information out of him. <The agent leans on her shovel and thinks a moment.> I think I've got it! While in disguise, go to the top of the abbey and ring the bell. That should bring the abbot's bodyguards running and you can then head down to speak with him.]],logDesc=[[Agent Skully at New Hearthglen has asked you to ring the bell in the abbey and then go speak with the high abbot and get information out of him.]]}
DB[12275]={id=12275,zoneId=65,name=[[The Demo-gnome]],level=72,minLevel=71,giver=[[High Commander Halford Wyrmbane]],giverType=[[NPC]],giverId=27136,ender=[[Siege Engineer Quarterflash]],enderType=[[NPC]],enderId=27159,prevId=12251,rewardNextId=12276,wowhead=[[https://www.wowhead.com/wotlk/quest=12275]],image=[[assets/images/quests/placeholder.png]],desc=[[Quarterflash recently requisitioned my group for a specialist that he could send on a reconnaissance mission to the Wintergarde Mine. To that end, I sent him Slinkin, my demolitionist. I foolishly thought that he could close off that pit of damnation after his mission for Quarterflash was complete, securing another victory for us against the Scourge. An entire day has now passed and Slinkin has not returned. I want answers! Speak with Siege Engineer Quarterflash and track down my missing agent!]],logDesc=[[Speak with Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight.]]}
DB[12276]={id=12276,zoneId=65,name=[[The Search for Slinkin]],level=72,minLevel=71,giver=[[Siege Engineer Quarterflash]],giverType=[[NPC]],giverId=27159,ender=[[Slinkin the Demo-gnome]],enderType=[[NPC]],enderId=27412,prevId=12275,rewardNextId=12277,wowhead=[[https://www.wowhead.com/wotlk/quest=12276]],image=[[assets/images/quests/placeholder.png]],desc=[[While I have not heard from Slinkin or know what fate has befallen him, perhaps I can assist in finding him. <Quarterflash holds up a tiny mechanical toy.> This is not a toy, newfound compatriot. It is, in fact, my latest mechanical creation. The machine was created with the sole purpose of finding that which has been lost. These are unfortunate circumstances, but the machine is your best chance at finding Slinkin. When you are ready to begin your search, place the bot on the ground next to me.]],logDesc=[[Find Slinkin the Demo-gnome in Wintergarde Mine. Use Quarterflash's Homing Bot if you need help finding the mine.]]}
DB[12277]={id=12277,zoneId=65,name=[[Leave Nothing to Chance]],level=72,minLevel=71,giver=[[Slinkin the Demo-gnome]],giverType=[[NPC]],giverId=27412,ender=[[Siege Engineer Quarterflash]],enderType=[[NPC]],enderId=27159,prevId=12276,nextId=12281,exGroup=-12272,wowhead=[[https://www.wowhead.com/wotlk/quest=12277]],image=[[assets/images/quests/placeholder.png]],desc=[[If there is good in your heart and your conscience is clear, read on. In this mine, near the foreman's scaffold, rests a hefty cargo of dynamite. Go there and pick up several bundles of the explosive and make your way towards the entrance of the mine. Once there, set the dynamite and blow up the entrance. Remember to do this for the upper and lower entry points of Wintergarde Mine. You must leave nothing to chance. The evil that exists here must never be allowed out. Light guide you.]],logDesc=[[Retrieve a Wintergarde Mine Bomb and use it to blow up the Upper Wintergarde Mine Shaft and the Lower Wintergarde Mine Shaft. Report back to Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight when you have completed this task.]],choiceRewards={{id=38293,qty=1},{id=38002,qty=1},{id=38106,qty=1},{id=37960,qty=1}}}
DB[12279]={id=12279,zoneId=394,name=[[A Bear of an Appetite]],level=75,minLevel=72,giver=[[Hugh Glass]],giverType=[[NPC]],giverId=26484,ender=[[Hugh Glass]],enderType=[[NPC]],enderId=26484,wowhead=[[https://www.wowhead.com/wotlk/quest=12279]],image=[[assets/images/quests/placeholder.png]],desc=[[Thank goodness you're back, Limpy! I worried that Griselda and I were going to be all alone. I'm cooking up some food here for us, but Griselda'll have none of it. She's fond of the fish that live off the coast of the Eastwind Shore, to the east. Can't stand them myself, but she's always been a picky eater. Six good-sized fish ought to keep her happy for a while. Now, run... err... limp along, Joe. Wouldn't want to keep the girl waiting, would ya?]],logDesc=[[Bring 6 Northern Salmon to Hugh Glass at the Redwood Trading Post.]]}
DB[12280]={id=12280,zoneId=394,name=[[Making Repairs]],level=74,minLevel=73,giver=[[Lurz]],giverType=[[NPC]],giverId=27422,ender=[[Lurz]],enderType=[[NPC]],enderId=27422,wowhead=[[https://www.wowhead.com/wotlk/quest=12280]],image=[[assets/images/quests/placeholder.png]],desc=[[Twenty shredders by noon tomorrow! Who makes these schedules, anyway? No one who ever put one of these garbage cans back together, that's who.... If I'm going to hit my quota, I'll need a hand. Help me out and I'll share my commission with you - fair enough? I need cogs, sprockets and springs. They're littered across the ground down by the shredders.]],logDesc=[[Lurz at Blue Sky Logging Grounds wants you to collect 4 Grooved Cogs, 3 Notched Sprockets, and 2 High Tension Springs.]]}
DB[12281]={id=12281,zoneId=65,name=[[Understanding the Scourge War Machine]],level=72,minLevel=71,giver=[[Siege Engineer Quarterflash]],giverType=[[NPC]],giverId=27159,ender=[[High Commander Halford Wyrmbane]],enderType=[[NPC]],enderId=27136,nextId=12325,exGroup=-12281,wowhead=[[https://www.wowhead.com/wotlk/quest=12281]],image=[[assets/images/quests/placeholder.png]],desc=[[We must take solace in the fact that Slinkin's death, while tragic, was for the greater good. His discovery coupled with your heroics in the mine and the samples you returned brings us one step closer to understanding the Scourge war machine. Take this package to High Commander Halford Wyrmbane. It holds a sample of the strange ore and my analysis.]],logDesc=[[Deliver Quarterflash's Package to High Commander Halford Wyrmbane at Wintergarde Keep.]]}
DB[12282]={id=12282,zoneId=65,name=[[Imprints on the Past]],level=72,minLevel=71,giver=[[Zelig the Visionary]],giverType=[[NPC]],giverId=27314,ender=[[Zelig the Visionary]],enderType=[[NPC]],enderId=27314,prevId=12251,rewardNextId=12287,wowhead=[[https://www.wowhead.com/wotlk/quest=12282]],image=[[assets/images/quests/placeholder.png]],desc=[[The memories of the past haunt this land, $N. I hear the cries of the fallen echo across Northrend - calling to me. Arthas left a terrible imprint on everything he touched. Only wither and decay remains in his wake. It is important, then, for us to study the past so that we may better know our enemy. Perhaps untold truths shall surface that could help in our campaign. First, you must recover my scrying orb from the town hall, $N. Exit this tower and turn left down the path to reach the town square.]],logDesc=[[Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to recover his Scrying Orb.]],choiceRewards={{id=37938,qty=1},{id=38025,qty=1},{id=38070,qty=1},{id=38086,qty=1}}}
DB[12283]={id=12283,zoneId=65,name=[[The Truth Will Out]],level=72,minLevel=71,giver=[[Agent Skully]],giverType=[[NPC]],giverId=27350,ender=[[High Executor Wroth]],enderType=[[NPC]],enderId=27243,prevId=12274,rewardNextId=12285,wowhead=[[https://www.wowhead.com/wotlk/quest=12283]],image=[[assets/images/quests/placeholder.png]],desc=[[We have to figure out what's going on here. We need the general's diary! I'm pretty sure that you'll find it on her nightstand upstairs at her house. It's the one next to church, across from the stables and the lumbermill. Once you acquire the diary, take it to the high executor back at Venomspite. You'll have to do this the old-fashioned way; the power of the mirror is low and there's only enough left for me. <The agent smirks.>]],logDesc=[[Agent Skully has asked you to acquire The Diary of High General Abbendis and to deliver it to High Executor Wroth at Venomspite.]]}
DB[12284]={id=12284,zoneId=394,name=[[Keep 'Em on Their Heels]],level=74,minLevel=73,giver=[[Commander Bargok]],giverType=[[NPC]],giverId=27451,ender=[[Commander Bargok]],enderType=[[NPC]],enderId=27451,wowhead=[[https://www.wowhead.com/wotlk/quest=12284]],image=[[assets/images/quests/placeholder.png]],desc=[[We've suffered heavy casualties here, $r. The only good news is that we've given as much as we've taken. I've requested more troops, but the bulk of our forces are bogged down in Venture Bay. It looks like we're on our own for now. No matter how bad it gets, we MUST stand our ground! The precious resources of this region are essential to the Horde's long-term success in Northrend. We've got to keep the Alliance on their heels until help arrives. Get out there and give 'em something to think about.]],logDesc=[[Commander Bargok wants you to kill 15 Alliance units or players in Blue Sky Logging Ground.]]}
DB[12285]={id=12285,zoneId=65,name=[[Do Unto Others]],level=73,minLevel=71,giver=[[High Executor Wroth]],giverType=[[NPC]],giverId=27243,ender=[[High Executor Wroth]],enderType=[[NPC]],enderId=27243,prevId=12283,wowhead=[[https://www.wowhead.com/wotlk/quest=12285]],image=[[assets/images/quests/placeholder.png]],desc=[[Their attack is imminent, $c. I need you to get in there and sever the head of the Scarlet Onslaught, literally! It's not going to be easy... Abbendis is sure to be surrounded by a great many of her men. I suggest that you take at least a couple of friends along. Bring back her head and I'll see to it that you're properly rewarded for saving Venomspite. Fail and don't even bother to return!]],logDesc=[[High Executor Wroth at Venomspite has ordered you to return with The Head of the High General.]],choiceRewards={{id=38536,qty=1},{id=38537,qty=1},{id=38535,qty=1},{id=38534,qty=1}}}
DB[12287]={id=12287,zoneId=65,name=[[Orik Trueheart and the Forgotten Shore]],level=72,minLevel=71,giver=[[Zelig the Visionary]],giverType=[[NPC]],giverId=27314,ender=[[Orik Trueheart]],enderType=[[NPC]],enderId=27347,prevId=12282,rewardNextId=12290,wowhead=[[https://www.wowhead.com/wotlk/quest=12287]],image=[[assets/images/quests/placeholder.png]],desc=[[I have gazed upon the orb and seen the path that you must walk, $N. Many years ago an atrocity was committed upon the shores of Dragonblight. The act itself remains shrouded in darkness, but I am certain that your destiny lies south, amidst the ruins of the Forgotten Shore. Take the road southeast through the ravaged town square. Follow the trail until you arrive at Dawn's Reach. You will meet an old friend of mine there known as Orik Trueheart. He will be expecting you.]],logDesc=[[Seek out the assistance of Orik Trueheart at Dawn's Reach in Dragonblight.]]}
DB[12288]={id=12288,zoneId=394,name=[[Overwhelmed!]],level=74,minLevel=73,giver=[[Aumana]],giverType=[[NPC]],giverId=27464,ender=[[Aumana]],enderType=[[NPC]],enderId=27464,wowhead=[[https://www.wowhead.com/wotlk/quest=12288]],image=[[assets/images/quests/placeholder.png]],desc=[[You there, $c! Help me! We're losing valuable lives! There are simply too many wounded for me to tend to alone. If we can't get our soldiers healed we could be run out of Grizzly Hills altogether! Take this tourniquet and use it on the wounded down on the battlefield. Hurry, $n! They're dyyying!!]],logDesc=[[Aumana at Blue Sky Logging Grounds wants you to use the Renewing Tourniquet on 10 Wounded Skirmishers.]]}
DB[12289]={id=12289,zoneId=394,name=[[Kick 'Em While They're Down]],level=74,minLevel=73,giver=[[Sergeant Hartsman]],giverType=[[NPC]],giverId=27468,ender=[[Sergeant Hartsman]],enderType=[[NPC]],enderId=27468,wowhead=[[https://www.wowhead.com/wotlk/quest=12289]],image=[[assets/images/quests/placeholder.png]],desc=[[It is a dark day for the Alliance. Many good men lay dead or dying here. Our only consolation is that they fought well and brought down many of the enemy with them. With the bulk of our forces committed to Venture Bay we stand alone to weather this storm. The resources in this region are vital to the Alliance and may well make the difference in our struggle against the Horde. We must not fail! Go, $n. Strike at them while they lick their wounds. Avenge your fallen brothers and keep our hopes alive!]],logDesc=[[Sergeant Hartsman wants you to defeat 15 Horde units or players in Blue Sky Logging Grounds.]]}
DB[12290]={id=12290,zoneId=65,name=[[The Murkweed Elixir]],level=72,minLevel=71,giver=[[Orik Trueheart]],giverType=[[NPC]],giverId=27347,ender=[[Orik Trueheart]],enderType=[[NPC]],enderId=27347,prevId=12287,rewardNextId=12291,wowhead=[[https://www.wowhead.com/wotlk/quest=12290]],image=[[assets/images/quests/placeholder.png]],desc=[[The spirits of the damned haunt the coast. In life they were brave and noble soldiers of the Alliance, but in death they are cursed - bound to this world until the end of days. We must discover the source of their anguish if we are to free them! To the southeast, on the Eldritch Heights, you will find a rare herb known as murkweed. It is murkweed that I will use to concoct an elixir that will allow you temporary entry into the world of the forgotten. Go now and gather the weed.]],logDesc=[[Orik Trueheart at Dawn's Reach in Dragonblight wants you to recover 5 Murkweed from the Eldritch Heights.]]}
DB[12291]={id=12291,zoneId=65,name=[[The Forgotten Tale]],level=72,minLevel=71,giver=[[Orik Trueheart]],giverType=[[NPC]],giverId=27347,ender=[[Orik Trueheart]],enderType=[[NPC]],enderId=27347,prevId=12290,rewardNextId=12301,wowhead=[[https://www.wowhead.com/wotlk/quest=12291]],image=[[assets/images/quests/placeholder.png]],desc=[[The toxins in the murkweed elixir will render you unconscious. So powerful is the effect of the murkweed that even your spirit will be fooled, allowing you to temporarily enter the world of the dead. Once a spirit, you must speak to the ghostly denizens of the Forgotten Shore. Seek out the cause of their anguish and return to me. Remember, $N, these spirits were once Alliance soldiers. Treat them with respect, honor and dignity. Now, with elixir in hand, venture south to the Forgotten Shore.]],logDesc=[[Orik Trueheart at Dawn's Reach in Dragonblight wants you to hear the tales of a Forgotten Peasant, Forgotten Rifleman, Forgotten Knight and Forgotten Footman.]]}
DB[12292]={id=12292,zoneId=394,name=[[Local Support]],level=74,minLevel=73,giver=[[Lieutenant Dumont]],giverType=[[NPC]],giverId=26875,ender=[[Lieutenant Dumont]],enderType=[[NPC]],enderId=26875,rewardNextId=12293,wowhead=[[https://www.wowhead.com/wotlk/quest=12292]],image=[[assets/images/quests/placeholder.png]],desc=[[We've reached a deadlock with the Horde in Grizzly Hills.  Our forces are just about evenly matched and all signs so far have pointed to a stalemate. Until this morning, that is.  The local trappers have requested our help.  Apparently the Horde took something that belongs to them... a relic of some sort. We get this back for them and they'll give us the edge we need.  Head to the Evergreen Trading Post, west of Conquest Hold and look for a cedar chest.]],logDesc=[[Lieutenant Dumont at Amberpine Lodge wants you to go to Evergreen Trading Post and obtain the Cedar Chest.]],choiceRewards={{id=38732,qty=1},{id=39030,qty=1},{id=39058,qty=1},{id=39096,qty=1},{id=38759,qty=1}}}
DB[12293]={id=12293,zoneId=394,name=[[Close the Deal]],level=74,minLevel=73,giver=[[Lieutenant Dumont]],giverType=[[NPC]],giverId=26875,ender=[[Ivan]],enderType=[[NPC]],enderId=27469,prevId=12292,rewardNextId=12294,wowhead=[[https://www.wowhead.com/wotlk/quest=12293]],image=[[assets/images/quests/placeholder.png]],desc=[[We have what the trappers want.  Now it's up to us to sign them up with our side. Take the chest to a trapper named Ivan at the Aspen Grove Post, just north of here. If all goes well, we'll have local woodsmen serving as scouts for the king's army in no time.]],logDesc=[[Bring the Cedar Chest to Ivan at Aspen Grove Post.]]}
DB[12294]={id=12294,zoneId=394,name=[[A Tentative Pact]],level=74,minLevel=73,giver=[[Ivan]],giverType=[[NPC]],giverId=27469,ender=[[Lieutenant Dumont]],enderType=[[NPC]],enderId=26875,prevId=12293,rewardNextId=12295,wowhead=[[https://www.wowhead.com/wotlk/quest=12294]],image=[[assets/images/quests/placeholder.png]],desc=[[Very well, $N.  Your people kept their end of the bargain. Tell Dumont that we'll honor the deal.]],logDesc=[[Return to Lieutenant Dumont in Amberpine Lodge.]]}
DB[12295]={id=12295,zoneId=394,name=[[An Exercise in Diplomacy]],level=74,minLevel=73,giver=[[Lieutenant Dumont]],giverType=[[NPC]],giverId=26875,ender=[[Envoy Ducal]],enderType=[[NPC]],enderId=26821,prevId=12294,wowhead=[[https://www.wowhead.com/wotlk/quest=12295]],image=[[assets/images/quests/placeholder.png]],desc=[[We'd been trying to negotiate with the trappers for weeks, but we'd gotten nowhere until you found that blasted chest of theirs. This should be good news to our envoy in Silverbrook.  We sent Ducal there about a week ago and his last letter indicated he'd been making little progress. Go to Silverbrook and aid him in his diplomatic efforts.  Take the roads heading northwest of here and you should find it after crossing a couple of bridges.]],logDesc=[[Speak to Envoy Ducal in Silverbrook.]]}
DB[12296]={id=12296,zoneId=394,name=[[Life or Death]],level=74,minLevel=73,giver=[[Rheanna]],giverType=[[NPC]],giverId=27484,ender=[[Rheanna]],enderType=[[NPC]],enderId=27484,wowhead=[[https://www.wowhead.com/wotlk/quest=12296]],image=[[assets/images/quests/placeholder.png]],desc=[[Oh, the carnage.... I've been through many battles, $c, and this one was more brutal than any I've seen. Our fight with the Horde has become more intense than ever. It's them or us here in Northrend - life or death. If we are to survive here another day we'll need to mend our wounded. There are too many for me to rescue alone. I've prepared special bandages that will enable you to assist me. Take one and tend to those who have not yet succumbed to their wounds.]],logDesc=[[Rheanna at Blue Sky Logging Grounds wants you to use the Renewing Bandage on 10 Wounded Westfall Infantry units.]]}
DB[12297]={id=12297,zoneId=65,name=[[Of Traitors and Treason]],level=72,minLevel=71,giver=[[Captain Adams]],giverType=[[NPC]],giverId=23749,ender=[[Greer Orehammer]],enderType=[[NPC]],enderId=23859,rewardNextId=12298,exGroup=12171,wowhead=[[https://www.wowhead.com/wotlk/quest=12297]],image=[[assets/images/quests/placeholder.png]],desc=[[The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of the Great Dragonblight. If any of the traitors on this list are stationed at Wintergarde... it could be catastrophic. Hurry, $N. Show the document to Greer Orehammer here at Westguard Keep and explain the nature of your mission. He'll put you on his fastest gryphon to Wintergarde!]],logDesc=[[Captain Adams has asked you to show the Alliance Missive to Greer Orehammer at Westguard Keep.]]}
DB[12298]={id=12298,zoneId=65,name=[[High Commander Halford Wyrmbane]],level=72,minLevel=71,giver=[[Greer Orehammer]],giverType=[[NPC]],giverId=23859,ender=[[High Commander Halford Wyrmbane]],enderType=[[NPC]],enderId=27136,prevId=12297,rewardNextId=12235,exGroup=12174,wowhead=[[https://www.wowhead.com/wotlk/quest=12298]],image=[[assets/images/quests/placeholder.png]],desc=[[<Greer hands the missive back to you.> Skysong will take you to Wintergarde, $N. I guarantee you that it will be the fastest flight you've ever taken. Go now! ]],logDesc=[[Deliver the Alliance Missive to High Commander Halford Wyrmbane at Wintergarde Keep in eastern Dragonblight.  ]]}
DB[12299]={id=12299,zoneId=394,name=[[Northern Hospitality]],level=74,minLevel=73,giver=[[Sergei]],giverType=[[NPC]],giverId=27486,ender=[[Sergei]],enderType=[[NPC]],enderId=27486,prevId=12295,nextId=12300,exGroup=-12299,wowhead=[[https://www.wowhead.com/wotlk/quest=12299]],image=[[assets/images/quests/placeholder.png]],desc=[[It's good to meet you.  Let us celebrate our pact by partaking in some good old fashioned Horde-killing. You'll find marauders from Conquest Hold just outside our town, west of here.  Why don't you head out there and hunt them like the filthy animals they are? Let's see if our new allies can back all their talk with some action.]],logDesc=[[Sergei at Silverbrook wants you to slay 8 Conquest Hold Marauders.]],choiceRewards={{id=38762,qty=1},{id=38760,qty=1},{id=38761,qty=1}}}
DB[12300]={id=12300,zoneId=394,name=[[Test of Mettle]],level=74,minLevel=73,giver=[[Sergei]],giverType=[[NPC]],giverId=27486,ender=[[Captured Trapper]],enderType=[[NPC]],enderId=27497,prevId=12299,rewardNextId=12302,wowhead=[[https://www.wowhead.com/wotlk/quest=12300]],image=[[assets/images/quests/placeholder.png]],desc=[[Alright, friend.  You've done us a favor or two, but that's not the true test of a person's courage. Around these parts, you're not a real hunter unless you wear your prey's skin. <Sergei unsheathes his skinning knife and hands it to you.> The leader of those motherless orcs attacking our town is called Bonesnap; you'll find him at a camp further northwest. That's right.  You're going to skin the monster.]],logDesc=[[Find Sergeant Bonesnap northwest of Silverbrook and pass the Test of Mettle.]]}
DB[12301]={id=12301,zoneId=65,name=[[The Truth Shall Set Us Free]],level=72,minLevel=71,giver=[[Orik Trueheart]],giverType=[[NPC]],giverId=27347,ender=[[Orik Trueheart]],enderType=[[NPC]],enderId=27347,prevId=12291,rewardNextId=12305,wowhead=[[https://www.wowhead.com/wotlk/quest=12301]],image=[[assets/images/quests/placeholder.png]],desc=[[Zelig gave this crystal ball to me years ago with specific instruction on its use. For five years - whenever I would feel anger, anxiety, or sorrow over the events that transpired here - I was to focus my thoughts upon the orb. I now understand why Zelig gave this crystal to me. Take my crystalline orb to the Forgotten Shore. Find the ruins of my old base on the upper reaches of the beach and place the orb in the center of town. Let the forgotten see the world through my heart and soul.]],logDesc=[[Orik Trueheart at Dawn's Reach in Dragonblight wants you to use Orik's Crystalline Orb in the ruins located at the Forgotten Shore to redeem the Forgotten.]]}
DB[12302]={id=12302,zoneId=394,name=[[Words of Warning]],level=74,minLevel=73,giver=[[Captured Trapper]],giverType=[[NPC]],giverId=27497,ender=[[Caged Prisoner]],enderType=[[NPC]],enderId=27499,prevId=12300,wowhead=[[https://www.wowhead.com/wotlk/quest=12302]],image=[[assets/images/quests/placeholder.png]],desc=[[Thanks for helping me, $N.  My name's Sasha.  Listen, I have to get the hell out of here. The people that sent you here... my people... they've changed.  They're not good people anymore... and they want to turn you into one of... one of them. This... 'test' they sent you on is just the beginning. Head to the northwestern end of Silverbrook.  You'll find something of interest to you. Good luck... and trust no one.]],logDesc=[[Go to the northwestern end of Silverbrook.]]}
DB[12303]={id=12303,zoneId=65,name=[[Funding the War Effort]],level=72,minLevel=71,giver=[[Quartermaster Bartlett]],giverType=[[NPC]],giverId=27267,ender=[[Quartermaster Bartlett]],enderType=[[NPC]],enderId=27267,wowhead=[[https://www.wowhead.com/wotlk/quest=12303]],image=[[assets/images/quests/placeholder.png]],desc=[[<The quartermaster lowers his voice and whispers to you.> $C, I need your help; our coffers are empty. The Kor'kron Vanguard at the Wrath Gate has taken all of our coin for the fight there. But, I've heard whispers that there's treasure to be had amongst the wrecks on the Forgotten Shore to the southeast. We have to do something soon, or we won't be able to continue the fight against the Scarlet Onslaught. War isn't cheap, you know!]],logDesc=[[Quartermaster Bartlett at Venomspite has asked you to recover 6 Forgotten Treasure.]],choiceRewards={{id=38181,qty=1},{id=38071,qty=1},{id=37986,qty=1},{id=38030,qty=1},{id=38036,qty=1}}}
DB[12304]={id=12304,zoneId=65,name=[[Beachfront Property]],level=72,minLevel=71,giver=[[Surveyor Hansen]],giverType=[[NPC]],giverId=32599,ender=[[Surveyor Hansen]],enderType=[[NPC]],enderId=32599,wowhead=[[https://www.wowhead.com/wotlk/quest=12304]],image=[[assets/images/quests/placeholder.png]],desc=[[It's time for Venomspite to expand! We'll take care of the Onslaught in due time, but I want you to spearhead our efforts on the Forgotten Shore. The property value has outstanding potential and just look at that view! Unfortunately, there's an infestation of human ghosts, shipwrecked crews and the like who haven't quite realized that they're dead. Clear the beach and the waters off the shore, and maybe you and I will talk about building a cozy, new mausoleum down there soon.]],logDesc=[[Surveyor Hansen, just north of the Forgotten Shore, has asked you to slay 20 Forgotten ghosts.]]}
DB[12305]={id=12305,zoneId=65,name=[[Parting Thoughts]],level=72,minLevel=71,giver=[[Orik Trueheart]],giverType=[[NPC]],giverId=27347,ender=[[Zelig the Visionary]],enderType=[[NPC]],enderId=27314,prevId=12301,rewardNextId=12475,wowhead=[[https://www.wowhead.com/wotlk/quest=12305]],image=[[assets/images/quests/placeholder.png]],desc=[[You have honored me and honored the memory of hundreds of Alliance veterans, $N. Zelig was wise in sending you here. Please return to him and give him my thanks. He will be happy to hear of the events that transpired at the Forgotten Shore. I do not have the gift of foresight like Zelig, but I am certain that great things await you, friend. Farewell.  ]],logDesc=[[Return to Zelig the Visionary at Wintergarde Keep in Dragonblight.]],choiceRewards={{id=38181,qty=1},{id=38071,qty=1},{id=37986,qty=1},{id=38030,qty=1},{id=38036,qty=1}}}
DB[12307]={id=12307,zoneId=394,name=[[Wolfsbane Root]],level=74,minLevel=73,giver=[[Katja]],giverType=[[NPC]],giverId=27545,ender=[[Katja]],enderType=[[NPC]],enderId=27545,prevId=12295,nextId=12300,exGroup=-12299,wowhead=[[https://www.wowhead.com/wotlk/quest=12307]],image=[[assets/images/quests/placeholder.png]],desc=[[Have you heard of the wolfsbane plant?  It is a horrible weed... it destroys our farmable crops. We spent all of last week cutting them down, but the roots are beginning to sprout again. It might not seem like an urgent matter, but a resurgence of the plant could be a real... disaster.  Do you think you could help us by uprooting them where you find them near the village?]],logDesc=[[Katja in Silverbrook wants you to uproot 8 Wolfsbane Roots.]],choiceRewards={{id=39062,qty=1},{id=39105,qty=1},{id=38754,qty=1},{id=38756,qty=1}}}
DB[12308]={id=12308,zoneId=394,name=[[Escape from Silverbrook]],level=74,minLevel=73,giver=[[Caged Prisoner]],giverType=[[NPC]],giverId=27499,ender=[[Lieutenant Dumont]],enderType=[[NPC]],enderId=26875,prevId=12302,nextId=12310,rewardNextId=12310,exGroup=12308,wowhead=[[https://www.wowhead.com/wotlk/quest=12308]],image=[[assets/images/quests/placeholder.png]],desc=[[You... you're not one of them?  Quick!  Let me out! We have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!]],logDesc=[[Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook.  Report to Lieutenant Dumont when you reach Amberpine Lodge.]],choiceRewards={{id=38733,qty=1},{id=39031,qty=1},{id=39059,qty=1},{id=39097,qty=1},{id=38750,qty=1}}}
DB[12309]={id=12309,zoneId=65,name=[[Find Durkon!]],level=72,minLevel=71,giver=[[High Commander Halford Wyrmbane]],giverType=[[NPC]],giverId=27136,ender=[[Cavalier Durkon]],enderType=[[NPC]],enderId=27318,prevId=12253,rewardNextId=12311,wowhead=[[https://www.wowhead.com/wotlk/quest=12309]],image=[[assets/images/quests/placeholder.png]],desc=[[After the Scourge breached the south wall, I ordered Cavalier Durkon to investigate the town crypt. Moments ago I was handed his report. The undead that plague us are coming from two sources: the ruins of Wintergarde, now a breeding ground for Scourge, and our very own town crypt! Amidst the chaos and confusion the Scourge managed to get a necrolord inside the crypt. In his message, Durkon requested assistance. You will find him and help him, $N. The crypt is on the western border of the town square.]],logDesc=[[Seek out Cavalier Durkon at the Wintergarde Crypt in Dragonblight. ]]}
DB[12310]={id=12310,zoneId=394,name=[[A Swift Response]],level=74,minLevel=73,giver=[[Lieutenant Dumont]],giverType=[[NPC]],giverId=26875,ender=[[Lieutenant Dumont]],enderType=[[NPC]],enderId=26875,prevId=12308,wowhead=[[https://www.wowhead.com/wotlk/quest=12310]],image=[[assets/images/quests/placeholder.png]],desc=[[Our response must be immediate.  Decisive.  We must teach these savages not to cross us. Our scouts have located what's left of the Silverbrook trappers... you know, the ones you didn't get to douse in flames.  Apparently they're blockading the road to the southeast... perhaps they're trying to box us in. Head to the Forest's Edge post and take care of them.  Their leader's reported to be a man named Vladek... make sure he's dealt with.]],logDesc=[[Lieutenant Dumont wants you to go to Forest's Edge Post and slay Vladek and 7 Silverbrook Hunters.]]}
DB[12311]={id=12311,zoneId=65,name=[[The Noble's Crypt]],level=72,minLevel=71,giver=[[Cavalier Durkon]],giverType=[[NPC]],giverId=27318,ender=[[Cavalier Durkon]],enderType=[[NPC]],enderId=27318,prevId=12309,wowhead=[[https://www.wowhead.com/wotlk/quest=12311]],image=[[assets/images/quests/placeholder.png]],desc=[[Held within the cold stone walls of this crypt are the remains of the nobles and dignitaries that died in Northrend. At its very core now sits a necrolord who raises the corpses as servants of the Scourge. You must make your way to the bottom of the Wintergarde Crypt and kill Necrolord Amarion. Only then will the assault from within cease! And $N, be on the lookout for any information that might be laying about inside the room where Amarion resides.  ]],logDesc=[[Cavalier Durkon at Wintergarde Keep wants you to slay Necrolord Amarion.]],choiceRewards={{id=37953,qty=1},{id=37995,qty=1},{id=38039,qty=1},{id=38100,qty=1}}}
DB[12312]={id=12312,zoneId=65,name=[[Secrets of the Scourge]],level=73,minLevel=71,giverType=[[NPC]],ender=[[Cavalier Durkon]],enderType=[[NPC]],enderId=27318,rewardNextId=12319,wowhead=[[https://www.wowhead.com/wotlk/quest=12312]],image=[[assets/images/quests/placeholder.png]],desc=[[Scrawled across the flesh-bound chapters of this tome are strange symbols and shapes that seem to have been scraped into the pages with a blade. You have no idea what is written, but you are certain that whatever it is, it must be important. Deliver the tome to Cavalier Durkon standing guard topside at Wintergarde Crypt.]],logDesc=[[Deliver the Flesh-bound Tome to Cavalier Durkon at Wintergarde Keep in Dragonblight.]]}
DB[12313]={id=12313,name=[[UNUSED Save Brewfest!]],level=-1,minLevel=65,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=12062,wowhead=[[https://www.wowhead.com/wotlk/quest=12313]],image=[[assets/images/quests/placeholder.png]],desc=[[Save Brewfest!  Talk to the Brewfest spy in the Grim Guzzler of Blackrock Depths.]],logDesc=[[Talk to the Brewfest spy in the Grim Guzzler of Blackrock Depths. ]]}
DB[12314]={id=12314,zoneId=394,name=[[Down With Captain Zorna!]],level=74,minLevel=73,giver=[[Baron Freeman]],giverType=[[NPC]],giverId=27520,ender=[[Baron Freeman]],enderType=[[NPC]],enderId=27520,wowhead=[[https://www.wowhead.com/wotlk/quest=12314]],image=[[assets/images/quests/placeholder.png]],desc=[[The Horde's forces are poised to break through our lines and complete their conquest of Venture Bay if we do not act. The Horde's forces in the port are commanded by Captain Zorna, near the ship on the far side of the bay. If you can defeat her, the Horde's offensive will falter and we can seize the chance to capture the port. Beware, $N, for Zorna is a fierce fighter. It may take several people to defeat her, or if you have access to a repaired shredder, you might try using it to your advantage.]],logDesc=[[Slay Captain Zorna and report to Baron Freeman at Venture Bay.]],rewards={{id=37836,qty=10}}}
DB[12315]={id=12315,zoneId=394,name=[[Crush Captain Brightwater!]],level=74,minLevel=73,giver=[[General Khazgar]],giverType=[[NPC]],giverId=27532,ender=[[General Khazgar]],enderType=[[NPC]],enderId=27532,wowhead=[[https://www.wowhead.com/wotlk/quest=12315]],image=[[assets/images/quests/placeholder.png]],desc=[[With every advance, our men are met by fresh Alliance reinforcements. It's almost as though their commander anticipates my every move! The time has come for good Captain Brightwater to meet his end. He commands his troops from aboard an Alliance destroyer at the far end of the bay. This will be no easy fight, $N. Take along a couple of trusted friends, or if you have a key to one of those repaired shredders, use it to disembowel Brightwater! Either way, he must fall!]],logDesc=[[Slay Captain Brightwater and report to General Khazgar at Venture Bay.]],rewards={{id=37836,qty=10}}}
DB[12316]={id=12316,zoneId=394,name=[[Keep Them at Bay!]],level=74,minLevel=73,giver=[[Lieutenant Stuart]],giverType=[[NPC]],giverId=27562,ender=[[Lieutenant Stuart]],enderType=[[NPC]],enderId=27562,wowhead=[[https://www.wowhead.com/wotlk/quest=12316]],image=[[assets/images/quests/placeholder.png]],desc=[[We cannot permit the Horde to control Venture Bay. The port is essential to our operations in Grizzly Hills and beyond. Captain Stoutmantle has taken the rest of the Westfall Brigade east in search of a passage through the mountains, so we'll have no reinforcements. Go into the field, $N, and kill the Conquest Hold berserkers the Horde has sent against us. Cut them down until none remain standing. The Alliance must have this port!]],logDesc=[[Defeat 10 Horde units or players in Venture Bay and return to Lieutenant Stuart.]],rewards={{id=37836,qty=10}}}
DB[12317]={id=12317,zoneId=394,name=[[Keep Them at Bay]],level=74,minLevel=73,giver=[[Centurion Kaggrum]],giverType=[[NPC]],giverId=27563,ender=[[Centurion Kaggrum]],enderType=[[NPC]],enderId=27563,wowhead=[[https://www.wowhead.com/wotlk/quest=12317]],image=[[assets/images/quests/placeholder.png]],desc=[[This wretched Westfall Brigade is proving a tougher opponent than we'd thought. Though few in number, they fight well and bravely, but we cannot afford to wait them out. Conqueror Krenna's orders were to capture the port quickly. You must break the stalemate, $N. Find the enemy's marines and slaughter them until the resistance ceases. Only then will we be able to claim ownership of the port. Go quickly. We don't want to keep Conqueror Krenna waiting.]],logDesc=[[Defeat 10 Alliance units or players in Venture Bay and return to Centurion Kaggrum.]],rewards={{id=37836,qty=10}}}
DB[12319]={id=12319,zoneId=65,name=[[Mystery of the Tome]],level=73,minLevel=71,giver=[[Cavalier Durkon]],giverType=[[NPC]],giverId=27318,ender=[[High Commander Halford Wyrmbane]],enderType=[[NPC]],enderId=27136,prevId=12312,rewardNextId=12320,wowhead=[[https://www.wowhead.com/wotlk/quest=12319]],image=[[assets/images/quests/placeholder.png]],desc=[[What can it be, $N? That was certainly no ordinary curse that the blasted lich put on you! <Durkon flips through the grisly pages of the tome.> I don't even know if I'm looking at it the right way. We must find out what information is held within this tome! <Durkon hands the book back to you.> The High Commander will know what to do. Take the flesh-bound tome to him and tell him exactly what happened here.]],logDesc=[[Take the Flesh-bound Tome to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.]]}
DB[12320]={id=12320,zoneId=65,name=[[Understanding the Language of Death]],level=73,minLevel=71,giver=[[High Commander Halford Wyrmbane]],giverType=[[NPC]],giverId=27136,ender=[[Inquisitor Hallard]],enderType=[[NPC]],enderId=27316,prevId=12319,wowhead=[[https://www.wowhead.com/wotlk/quest=12320]],image=[[assets/images/quests/placeholder.png]],desc=[[Take the book and follow the path leading up to the barracks. Once inside the barracks take the staircase down to the prison. At the prison you will find Inquisitor Hallard and our mayor, Godfrey. I believe Godfrey might be the missing piece of this puzzle and Hallard the man to put it all together. Go now!]],logDesc=[[Take the Flesh-bound Tome to Inquisitor Hallard at the Wintergarde Keep prison.]]}
DB[12321]={id=12321,zoneId=65,name=[[A Righteous Sermon]],level=73,minLevel=71,giver=[[Inquisitor Hallard]],giverType=[[NPC]],giverId=27316,ender=[[High Commander Halford Wyrmbane]],enderType=[[NPC]],enderId=27136,prevId=12320,nextId=12325,exGroup=-12281,wowhead=[[https://www.wowhead.com/wotlk/quest=12321]],image=[[assets/images/quests/placeholder.png]],desc=[[Godfrey Goodard, once a righteous man and mayor of Wintergarde, is now an agent of the Scourge. His transformation from man to undying ghoul has taken place slowly, over time. He hears the call of the Lich King now and lives only to serve his master. But as with all Scourge, Godfrey knows the language of death and with proper motivation, will tell us what we need to know about the tome. Once you hear what you need to hear, return to the High Commander at the front lines. I'll clean up here as needed.]],logDesc=[[Wait for Inquisitor Hallard to finish his Righteous Sermon and return to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight with the information you uncover.]],choiceRewards={{id=37950,qty=1},{id=37993,qty=1},{id=38037,qty=1},{id=38068,qty=1}}}
DB[12323]={id=12323,zoneId=394,name=[[Smoke 'Em Out]],level=74,minLevel=73,giver=[[Sergeant Downey]],giverType=[[NPC]],giverId=27602,ender=[[Sergeant Downey]],enderType=[[NPC]],enderId=27602,wowhead=[[https://www.wowhead.com/wotlk/quest=12323]],image=[[assets/images/quests/placeholder.png]],desc=[[There are still pockets of cowardly Venture Company men holed up in some of the buildings at the center of Venture Bay. I need every man I can spare out there fighting against the Horde, but we can't allow those Venture Company stragglers to camp out in those buildings, either. Maybe we can "convince" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; they probably bite.]],logDesc=[[Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Sergeant Downey.]],rewards={{id=37836,qty=10}}}
DB[12324]={id=12324,zoneId=394,name=[[Smoke 'Em Out]],level=74,minLevel=73,giver=[[Stone Guard Ragetotem]],giverType=[[NPC]],giverId=27606,ender=[[Stone Guard Ragetotem]],enderType=[[NPC]],enderId=27606,wowhead=[[https://www.wowhead.com/wotlk/quest=12324]],image=[[assets/images/quests/placeholder.png]],desc=[[Not only is this port infested with sniveling Alliance cowards, but to make matters worse, there are still Venture Company employees holed up in some of the buildings. They're not worth the time it takes to kill and I can't spare the warriors anyway. Maybe we can "convince" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; there's no telling what diseases they're carrying.]],logDesc=[[Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Stone Guard Ragetotem.]],rewards={{id=37836,qty=10}}}
DB[12325]={id=12325,zoneId=65,name=[[Into Hostile Territory]],level=73,minLevel=71,giver=[[High Commander Halford Wyrmbane]],giverType=[[NPC]],giverId=27136,ender=[[Duke August Foehammer]],enderType=[[NPC]],enderId=27157,rewardNextId=12326,wowhead=[[https://www.wowhead.com/wotlk/quest=12325]],image=[[assets/images/quests/placeholder.png]],desc=[[You have done much to advance our efforts against the Scourge, $N. In fact, the morale of all those who have come into contact with you soars! Such is your influence over the soldiers and citizenry of Wintergarde, ally. And because of you we are now prepared to go on the offensive! You are to report to Duke August Foehammer, across the Carrion Fields at Thorson's Post, east of here. Gryphon Commander Urik at the gryphon station has prepared a special gryphon to drop you behind enemy lines. Go now!]],logDesc=[[Speak with Gryphon Commander Urik to secure a ride to Thorson's Post. Report to Duke August Foehammer when you arrive at Thorson's Post in Dragonblight. ]]}
DB[12326]={id=12326,zoneId=65,name=[[Steamtank Surprise]],level=73,minLevel=71,giver=[[Duke August Foehammer]],giverType=[[NPC]],giverId=27157,ender=[[Ambo Cash]],enderType=[[NPC]],enderId=1293,prevId=12325,rewardNextId=12455,wowhead=[[https://www.wowhead.com/wotlk/quest=12326]],image=[[assets/images/quests/placeholder.png]],desc=[[This is a seek and destroy mission. You'll be driving a tank into the Carrion Fields to dismantle Scourge plague wagons. With the tank comes a crew of three 7th Legion soldiers. All must survive if this mission is to succeed! You'll need to get in close to a plague wagon to unleash your engineer. Let them do their deed and move on to the next one. When the field is clear of plague wagons, head to the mausoleum in front of the ruined keep and drop off the rest of your crew. Meet with Ambo Cash inside.]],logDesc=[[Use an Alliance Steam Tank to destroy 6 Plague Wagons and deliver the 7th Legion Elites to Wintergarde Mausoleum. Speak with Ambo Cash inside the Wintergarde Mausoleum in Dragonblight should you succeed.]],choiceRewards={{id=37992,qty=1},{id=37949,qty=1},{id=38284,qty=1}}}
DB[12327]={id=12327,zoneId=394,name=[[Out of Body Experience]],level=75,minLevel=73,giver=[[Ruuna the Blind]],giverType=[[NPC]],giverId=27581,ender=[[Ruuna the Blind]],enderType=[[NPC]],enderId=27581,prevId=12328,rewardNextId=12329,wowhead=[[https://www.wowhead.com/wotlk/quest=12327]],image=[[assets/images/quests/placeholder.png]],desc=[[Ah, you seek a vision of the past.  You're a wise $r. Every time someone drops by for a reading, they seem to always ask about the future.  When you get to be my age, you learn that scrying the past, more often than not, is more useful. Drink this potion and peer into my crystal ball.  Let us see what knowledge we can obtain.]],logDesc=[[Drink the Gossamer Potion near Ruuna's Crystal Ball and witness the Vision from the Past.]]}
DB[12328]={id=12328,zoneId=394,name=[[Ruuna's Request]],level=75,minLevel=73,giver=[[Ruuna the Blind]],giverType=[[NPC]],giverId=27581,ender=[[Ruuna the Blind]],enderType=[[NPC]],enderId=27581,rewardNextId=12327,wowhead=[[https://www.wowhead.com/wotlk/quest=12328]],image=[[assets/images/quests/placeholder.png]],desc=[[I will not charge you gold for my services, for I can foresee that your actions are necessary and much hinges on what you learn today. I will, however, ask you to collect a reagent for me.  Obtain gossamer dust from the fern feeder moths northeast of here.  Do this and I will prepare a potion that will take you to the time and place where the events took place that you need to witness.]],logDesc=[[Ruuna the Blind wants you to obtain 4 handfuls of Gossamer Dust.]],choiceRewards={{id=38727,qty=1},{id=39026,qty=1},{id=39054,qty=1},{id=39092,qty=1}}}
DB[12329]={id=12329,zoneId=394,name=[[Fate and Coincidence]],level=75,minLevel=73,giver=[[Ruuna the Blind]],giverType=[[NPC]],giverId=27581,ender=[[Sasha]],enderType=[[NPC]],enderId=26935,prevId=12327,wowhead=[[https://www.wowhead.com/wotlk/quest=12329]],image=[[assets/images/quests/placeholder.png]],desc=[[There are two types of people in this world, $N.  Those who believe in coincidence and those who don't. On the day I lost my eyesight I was given the gift of clairvoyance.  I suppose you can guess what sort of person I am. Earlier today, a young woman named Sasha was granted the same vision you were.  You will want to talk to her. You'll find her directly east of here at the White Pine Trading Post, on the way to Solstice Village.]],logDesc=[[Speak to Sasha at the White Pine Trading Post.]]}
DB[12330]={id=12330,zoneId=394,name=[[Anatoly Will Talk]],level=75,minLevel=73,giver=[[Sasha]],giverType=[[NPC]],giverId=26935,ender=[[Sasha]],enderType=[[NPC]],enderId=26935,prevId=12329,wowhead=[[https://www.wowhead.com/wotlk/quest=12330]],image=[[assets/images/quests/placeholder.png]],desc=[[My sister is here somewhere, and I can't seem to get this monster to talk. He doesn't seem to care about his own well-being, but I've an idea.  I knew Anatoly's wife, Tatjana, from before the wolfcult arrived -- she was a horse-handler. Take this tranquillizer dart.  Bring her back alive, we're going to need her if we're to have any leverage with Anatoly. I will help you find the person behind all this once we save my sister.]],logDesc=[[Sasha at the White Pine Trading Post wants you to take the Tranquilizer Dart and use it on Tatjana in Solstice Village.  Bring Tatjana back to the White Pine Trading Post.]],choiceRewards={{id=38744,qty=1},{id=38752,qty=1},{id=38748,qty=1}}}
DB[12372]={id=12372,zoneId=65,name=[[Defending Wyrmrest Temple]],level=74,minLevel=71,giver=[[Lord Afrasastrasz]],giverType=[[NPC]],giverId=27575,ender=[[Lord Afrasastrasz]],enderType=[[NPC]],enderId=27575,prevId=12435,wowhead=[[https://www.wowhead.com/wotlk/quest=12372]],image=[[assets/images/quests/placeholder.png]],desc=[[Emboldened by the overabundance of magic now flowing through the Azure Dragonshrine, the blue dragonflight has dared to attack Wyrmrest Temple itself! I ask that you ride one of our defenders into battle to slay their dragons and drakes, and to attack the eruption of ley line energies at the dragonshrine itself in order to destabilize it. Outside on the east and west terraces are wyrmrest defenders. Speak with one to ride it into battle. Without your help, $N, we will surely lose.]],logDesc=[[Afrasastrasz at Wyrmrest Temple has asked you to slay 3 Azure Dragons, slay 5 Azure Drakes, and to destabilize the Azure Dragonshrine while riding a Wyrmrest Defender into battle.]]}
DB[12411]={id=12411,zoneId=394,name=[[A Sister's Pledge]],level=75,minLevel=73,giver=[[Sasha]],giverType=[[NPC]],giverId=26935,ender=[[Anya]],enderType=[[NPC]],enderId=27646,prevId=12330,wowhead=[[https://www.wowhead.com/wotlk/quest=12411]],image=[[assets/images/quests/placeholder.png]],desc=[[Please, $N.  I know it is Arugal you're after.  I swear on my father's memory I will help you take him down. But I must beg you... Anya is completely innocent, we cannot leave her with these savages. Help me rescue my sister and you'll have me at your side when you face Arugal. I know the den Anatoly spoke of.  We'll find it on the other side of this hill.  Let's go, my sister's in danger.]],logDesc=[[Look for Anya in the Duskhowl Den near Solstice Village.]]}
DB[12412]={id=12412,zoneId=394,name=[[My Enemy's Friend]],level=75,minLevel=73,giver=[[Conqueror Krenna]],giverType=[[NPC]],giverId=26860,ender=[[Conqueror Krenna]],enderType=[[NPC]],enderId=26860,prevId=12259,rewardNextId=12413,wowhead=[[https://www.wowhead.com/wotlk/quest=12412]],image=[[assets/images/quests/placeholder.png]],desc=[[If there is one thing I can get through your head, let it be this: the Alliance will be crushed in the Grizzly Hills. There is far too much lumber, ore, game and strategic territory for us to give up on any single battlefront here. So far we've been successful... but there's something that could tip the scales in our enemy's favor. Far to the east  of here, at the Forest Edge's Post, local trappers seek to join the Alliance.  Slaughter them before they have the chance to do so.]],logDesc=[[Conqueror Krenna in Conquest Hold wants you to slay 8 Silverbrook Hunters and their leader, Vladek, at the Forest's Edge Post.]],choiceRewards={{id=38732,qty=1},{id=39030,qty=1},{id=39058,qty=1},{id=39096,qty=1},{id=38759,qty=1}}}
DB[12413]={id=12413,zoneId=394,name=[[Attack on Silverbrook]],level=74,minLevel=73,giver=[[Conqueror Krenna]],giverType=[[NPC]],giverId=26860,ender=[[Conqueror Krenna]],enderType=[[NPC]],enderId=26860,prevId=12412,nextId=12427,rewardNextId=12427,exGroup=-12178,wowhead=[[https://www.wowhead.com/wotlk/quest=12413]],image=[[assets/images/quests/placeholder.png]],desc=[[A few hours ago, the trappers were nothing but peasants threatening to add their number to the Alliance's. Now they've become something else... an uncertainty.  I do not like uncertainties.  Go to the hills outside their main town in northern Grizzly Hills, Silverbrook, and help my men crush them.]],logDesc=[[Conqueror Krenna at Conquest Hold wants you to slay 8 Silverbrook Defenders in the Silverbrook Hills.]],choiceRewards={{id=38733,qty=1},{id=39031,qty=1},{id=39059,qty=1},{id=39097,qty=1},{id=38750,qty=1}}}
DB[12414]={id=12414,zoneId=394,name=[[Mounting Up]],level=75,minLevel=73,giver=[[Squire Percy]],giverType=[[NPC]],giverId=26377,ender=[[Squire Percy]],enderType=[[NPC]],enderId=26377,wowhead=[[https://www.wowhead.com/wotlk/quest=12414]],image=[[assets/images/quests/placeholder.png]],desc=[[Cap'n Stoutmantle left most of our calvary... cavlary... uh, horsemen at the fight for Venture Bay. We chose a good place to put the camp 'cause there are tons of highland mustangs running around near here and in the Boulder Hills to the northeast. The Cap'n put me in charge of capturing some of 'em. Will you help? I've got a stick and some string, and there are loads of wild carrots growing near the camp. Pick the carrots and use them with the stick to lure in the mustang, then ride it back here.]],logDesc=[[Ride 5 Highland Mustangs back to Squire Percy at the Westfall Brigade Encampment.]]}
DB[12415]={id=12415,zoneId=394,name=[[The Horse Hollerer]],level=75,minLevel=73,giver=[[Soulok Stormfury]],giverType=[[NPC]],giverId=26944,ender=[[Soulok Stormfury]],enderType=[[NPC]],enderId=26944,wowhead=[[https://www.wowhead.com/wotlk/quest=12415]],image=[[assets/images/quests/placeholder.png]],desc=[[The Alliance's 'Westfall Brigade' is camped far to the north, near Thor Modan. They have foolishly divided their forces to contest our control of Venture Bay, and they have been left without cavalry. They're now trying to capture and tame the wild highland mustangs that roam the area around the Westfall Brigade Encampment and Boulder Hills. We must stop them before they're able to replace their lost mounts. Take this and throw it near the horses to drive them away.]],logDesc=[[Scare 15 Highland Mustangs and return to Soulok Stormfury at Camp Oneqwah.]]}
DB[12416]={id=12416,zoneId=65,name=[[Heated Battle]],level=74,minLevel=71,giver=[[Ceristrasz]],giverType=[[NPC]],giverId=27506,ender=[[Ceristrasz]],enderType=[[NPC]],enderId=27506,prevId=12460,rewardNextId=12417,wowhead=[[https://www.wowhead.com/wotlk/quest=12416]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, $r. Captain Iskandar leads a group of your kind in stemming the flow of the Scourge out of the shrine. Go to his aid... but please stay behind his men. The flow of Scourge is endless and I don't want to lose you in one of those scarred canyons.]],logDesc=[[Aid Captain Iskandar in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker. Return to Ceristrasz once you have finished this task.]]}
DB[12417]={id=12417,zoneId=65,name=[[Return to the Earth]],level=74,minLevel=71,giver=[[Ceristrasz]],giverType=[[NPC]],giverId=27506,ender=[[Ceristrasz]],enderType=[[NPC]],enderId=27506,prevId=12416,rewardNextId=12418,wowhead=[[https://www.wowhead.com/wotlk/quest=12417]],image=[[assets/images/quests/placeholder.png]],desc=[[I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks. Get into the shrine through one of the other passes to the south or north... the Scourge presence should be lighter there. Search the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.]],logDesc=[[Enter the Ruby Dragonshrine through one of the northern or southern passes and search for Ruby Acorns.  Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth.  Return to Ceristrasz once the task is complete.]]}
DB[12418]={id=12418,zoneId=65,name=[[Through Fields of Flame]],level=75,minLevel=71,giver=[[Ceristrasz]],giverType=[[NPC]],giverId=27506,ender=[[Ceristrasz]],enderType=[[NPC]],enderId=27506,prevId=12417,rewardNextId=12768,wowhead=[[https://www.wowhead.com/wotlk/quest=12418]],image=[[assets/images/quests/placeholder.png]],desc=[[I have one final task for you, $r... one that should turn the tide of this fight. Return to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine. I also need you to find the source of the corruption under the shrine and put an end to it. I know I have asked a lot of you, but if you do this for me, we will win this battle.]],logDesc=[[Enter the Ruby Dragonshrine through one of the northern or southern passes, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Ceristrasz once the task is complete.]],choiceRewards={{id=37962,qty=1},{id=38004,qty=1},{id=38046,qty=1},{id=38108,qty=1}}}
DB[12419]={id=12419,zoneId=65,name=[[The Fate of the Ruby Dragonshrine]],level=75,minLevel=71,giverType=[[NPC]],ender=[[Krasus]],enderType=[[NPC]],enderId=27990,wowhead=[[https://www.wowhead.com/wotlk/quest=12419]],image=[[assets/images/quests/placeholder.png]],desc=[[As you pick up the brooch, its faint glow brightens slightly. Krasus will want to know of Dahlia's fate. Take the brooch to him at Wyrmrest.]],logDesc=[[Bring Dahlia Suntouch's Ruby Brooch to Krasus in the Ruling Council Chamber at Wyrmrest and inform him of Dahlia's fate.]]}
DB[12420]={id=12420,name=[[Brew of the Month Club]],name_loc=[[Club de la Cerveza del Mes]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Larkin Thunderbrew]],ender_loc=[[Larkin Cebatruenos]],enderType=[[NPC]],enderId=27478,poiX=-4849,poiY=-862,wowhead=[[https://www.wowhead.com/wotlk/quest=12420]],image=[[assets/images/quests/placeholder.png]],desc=[[Membership has its privileges.  Being part of the "Brew of the Month" club means knowing where to get the latest and greatest brew. Bring your "Brew of the Month" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.]],logDesc=[[Bring the "Brew of the Month" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.]]}
DB[12421]={id=12421,name=[[Brew of the Month Club]],name_loc=[[Club de la Cerveza del Mes]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Ray'ma]],ender_loc=[[Ray'ma]],enderType=[[NPC]],enderId=27489,poiX=1473,poiY=-4209,wowhead=[[https://www.wowhead.com/wotlk/quest=12421]],image=[[assets/images/quests/placeholder.png]],desc=[[There is strength in numbers, $n.  Being part of the "Brew of the Month" club means knowing you and your brethren will always have access to the best brew. Bring your "Brew of the Month" club membership form to Ray'ma in the Darkbriar Lodge in Orgrimmar's Valley of Spirits.]],logDesc=[[Bring the "Brew of the Month" club membership form to Ray'ma in the Darkbriar Lodge in Orgrimmar's Valley of Spirits.]]}
DB[12422]={id=12422,zoneId=394,name=[[Tactical Clemency]],level=74,minLevel=73,giver=[[Gorgonna]],giverType=[[NPC]],giverId=27102,ender=[[Captured Trapper]],enderType=[[NPC]],enderId=27497,prevId=12424,nextId=12427,rewardNextId=12427,exGroup=-12178,wowhead=[[https://www.wowhead.com/wotlk/quest=12422]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen, $N.  I need you to act with discretion and speed. One of Krenna's top sergeants has captured a trapper outcast outside of Silverbrook.  Now, if things turn out the way they usually do, the prisoner is going to be executed before the day is over. We can't let that happen.  You see, the prisoner matches the description of Mikhail's older daughter in his diary. If we set her loose and follow her closely, she'll lead us to whoever's controlling the trappers.  Take this letter to her.]],logDesc=[[Deliver the Letter of Amnesty to the Captured Trapper in Silverbrook Hills.]]}
DB[12423]={id=12423,zoneId=394,name=[[Mikhail's Journal]],level=74,minLevel=73,giverType=[[NPC]],ender=[[Conqueror Krenna]],enderType=[[NPC]],enderId=26860,rewardNextId=12424,wowhead=[[https://www.wowhead.com/wotlk/quest=12423]],image=[[assets/images/quests/placeholder.png]],desc=[[From what you can gather, this journal was written by a denizen of Silverbrook named Mikhail. It is written in some variant of the common human tongue.  Perhaps you should bring this back to Conqueror Krenna.]],logDesc=[[Bring Mikhail's Journal to Conqueror Krenna in Conquest Hold.]]}
DB[12424]={id=12424,zoneId=394,name=[[Gorgonna]],level=74,minLevel=73,giver=[[Conqueror Krenna]],giverType=[[NPC]],giverId=26860,ender=[[Gorgonna]],enderType=[[NPC]],enderId=27102,prevId=12423,rewardNextId=12422,wowhead=[[https://www.wowhead.com/wotlk/quest=12424]],image=[[assets/images/quests/placeholder.png]],desc=[[This book is written in the pig-tongue the humans use.  It needs to be burned immediately. Hand it to my sister Gorgonna and do not waste my time.]],logDesc=[[Bring Mikhail's Journal to Gorgonna in Conquest Hold.]]}
DB[12425]={id=12425,zoneId=394,name=[[Ruuna the Blind]],level=75,minLevel=73,giver=[[Gorgonna]],giverType=[[NPC]],giverId=27102,ender=[[Ruuna the Blind]],enderType=[[NPC]],enderId=27581,nextId=12328,rewardNextId=12328,exGroup=12161,wowhead=[[https://www.wowhead.com/wotlk/quest=12425]],image=[[assets/images/quests/placeholder.png]],desc=[[This trapper business has the potential to be more important than we've accounted for. If they're not with the Alliance, there's a good chance they're with the Scourge, which could mean trouble. Our previous efforts might've paid off, though.  We spotted our former captive meeting with a fortune teller of some sort before we lost track of her. I'm almost certain now that she will take us to their leader if we can find her again.  Find Ruuna the Blind and see what you can find out.]],logDesc=[[Speak to Ruuna the Blind at Ruuna's Camp near Vordrassil Pass.]]}
DB[12426]={id=12426,zoneId=394,name=[[DEPRECATED]],level=75,minLevel=72,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12426]],image=[[assets/images/quests/placeholder.png]]}
DB[12427]={id=12427,zoneId=394,name=[[The Conquest Pit: Bear Wrestling!]],level=74,minLevel=73,giver=[[Grennix Shivwiggle]],giverType=[[NPC]],giverId=27719,ender=[[Bookie Vel'jen]],enderType=[[NPC]],enderId=27720,rewardNextId=12428,wowhead=[[https://www.wowhead.com/wotlk/quest=12427]],image=[[assets/images/quests/placeholder.png]],desc=[[So you're interested in the fights, eh?  Well, Krenna has outlawed pit-fighting for all enlisted combatants.  But you, my friend, are technically a free agent and are not included in this prohibition. Nice loophole, eh? Anyway, if you're interested I can start you off with something easy, a measly bear.  I'll even let you bring friends along!]],logDesc=[[Defeat Ironhide inside the Conquest Pit and speak to Bookie Vel'jen for a reward.]]}
DB[12428]={id=12428,zoneId=394,name=[[The Conquest Pit: Mad Furbolg Fighting]],level=74,minLevel=73,giver=[[Grennix Shivwiggle]],giverType=[[NPC]],giverId=27719,ender=[[Bookie Vel'jen]],enderType=[[NPC]],enderId=27720,prevId=12427,wowhead=[[https://www.wowhead.com/wotlk/quest=12428]],image=[[assets/images/quests/placeholder.png]],desc=[[You're not bad.  Not bad at all. Think you can take a furbolg?  What about one of those extra-large crazed Northrend furbolgs? Good, good.  Get your crew together, and head to the ring.  Let's give these folks a show... maybe we can earn some more coin while we're at it.]],logDesc=[[Defeat Torgg Thundertotem inside the Conquest Pit and speak to Bookie Vel'jen for a reward. ]]}
DB[12429]={id=12429,zoneId=394,name=[[The Conquest Pit: Blood and Metal]],level=74,minLevel=73,giver=[[Grennix Shivwiggle]],giverType=[[NPC]],giverId=27719,ender=[[Bookie Vel'jen]],enderType=[[NPC]],enderId=27720,prevId=12428,wowhead=[[https://www.wowhead.com/wotlk/quest=12429]],image=[[assets/images/quests/placeholder.png]],desc=[[It's nice to have a real fighter around these parts... we'd only had prisoners and caged beasts for the past few weeks.  The people get bored, ya know? Anyhow, your next challenge is a genuine iron golem stolen from the depths of Thor Modan... think you can swing it?]],logDesc=[[Defeat Rustblood inside the Conquest Pit and speak to Bookie Vel'jen for a reward. ]]}
DB[12430]={id=12430,zoneId=394,name=[[The Conquest Pit: Death Is Likely]],level=75,minLevel=73,giver=[[Grennix Shivwiggle]],giverType=[[NPC]],giverId=27719,ender=[[Bookie Vel'jen]],enderType=[[NPC]],enderId=27720,prevId=12429,wowhead=[[https://www.wowhead.com/wotlk/quest=12430]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm gonna shoot straight with ya, kid.  This next contender's a murderer. Literally. He was to be executed last week, but he strangled the hangman with his left hand, so Krenna's guards sort of let me have him. Feel free to pass on this one.  I wouldn't blame ya.]],logDesc=[[Defeat Horgrenn Hellcleave inside the Conquest Pit and speak to Bookie Vel'jen for a reward. ]]}
DB[12431]={id=12431,zoneId=394,name=[[The Conquest Pit: Final Showdown]],level=75,minLevel=73,giver=[[Grennix Shivwiggle]],giverType=[[NPC]],giverId=27719,ender=[[Gorgonna]],enderType=[[NPC]],enderId=27102,prevId=12430,wowhead=[[https://www.wowhead.com/wotlk/quest=12431]],image=[[assets/images/quests/placeholder.png]],desc=[[You must've really upset Krenna.  She and Gorgonna have had a spat and you're wanted in the pit immediately. There are some wild rumors that it's a fight to the death!  That would be bad news for you, but great news for our business venture! At any rate, you can't run away from fate... best get in there on the quick and get it over with.]],logDesc=[[Defeat Krenna in the Conquest Pit and speak to Gorgonna for a reward.]],choiceRewards={{id=39181,qty=1},{id=39183,qty=1},{id=39182,qty=1},{id=39179,qty=1},{id=39180,qty=1}}}
DB[12431]={id=12431,zoneId=394,name=[[The Conquest Pit: Final Showdown]],level=75,minLevel=73,giver=[[Grennix Shivwiggle]],giverType=[[NPC]],giverId=27719,ender=[[Gorgonna]],enderType=[[NPC]],enderId=27726,prevId=12430,wowhead=[[https://www.wowhead.com/wotlk/quest=12431]],image=[[assets/images/quests/placeholder.png]],desc=[[You must've really upset Krenna.  She and Gorgonna have had a spat and you're wanted in the pit immediately. There are some wild rumors that it's a fight to the death!  That would be bad news for you, but great news for our business venture! At any rate, you can't run away from fate... best get in there on the quick and get it over with.]],logDesc=[[Defeat Krenna in the Conquest Pit and speak to Gorgonna for a reward.]],choiceRewards={{id=39181,qty=1},{id=39183,qty=1},{id=39182,qty=1},{id=39179,qty=1},{id=39180,qty=1}}}
DB[12432]={id=12432,zoneId=394,name=[[Riding the Red Rocket]],level=74,minLevel=73,giver=[[General Gorlok]],giverType=[[NPC]],giverId=27708,ender=[[General Gorlok]],enderType=[[NPC]],enderId=27708,wowhead=[[https://www.wowhead.com/wotlk/quest=12432]],image=[[assets/images/quests/placeholder.png]],desc=[[You there, $r! Get your lousy carcass over here! The Alliance have a shipment of lumber all ready for transport just northeast of here. Since getting our hands on that wood is out of the question, there's only one thing to do - destroy it! The goblin at the end of the dock here has some torpedoes all ready to go. He's got all the fuel for them on the docked goblin ship to the north. Get some fuel, then commandeer one of the torpedoes and ride it into their ship. Dismissed!]],logDesc=[[General Gorlok at the lighthouse in Venture Bay wants you to destroy the Alliance Lumber Boat. General Gorlok will only be present at the lighthouse when the Horde has it in their possession.]],rewards={{id=37836,qty=10}}}
DB[12433]={id=12433,zoneId=394,name=[[Seeking Solvent]],level=74,minLevel=73,giver=[[Gurtor]],giverType=[[NPC]],giverId=27565,ender=[[Gurtor]],enderType=[[NPC]],enderId=27565,wowhead=[[https://www.wowhead.com/wotlk/quest=12433]],image=[[assets/images/quests/placeholder.png]],desc=[[Gah! Not again. Another blown gasket.... Every time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean. Tell ya what, $r. There's some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent. Get me one of those and I'll make it worth your trouble.]],logDesc=[[Gurtor at the Venture Bay Horde base wants you to bring him a canister of Element 115.]],rewards={{id=37836,qty=4}}}
DB[12434]={id=12434,zoneId=394,name=[[Always Seeking Solvent]],level=74,minLevel=73,giver=[[Gurtor]],giverType=[[NPC]],giverId=27565,ender=[[Gurtor]],enderType=[[NPC]],enderId=27565,prevId=12433,wowhead=[[https://www.wowhead.com/wotlk/quest=12434]],image=[[assets/images/quests/placeholder.png]],rewards={{id=37836,qty=2}}}
DB[12435]={id=12435,zoneId=65,name=[[Report to Lord Afrasastrasz]],level=74,minLevel=71,giver=[[Alexstrasza the Life-Binder]],giverType=[[NPC]],giverId=26917,ender=[[Lord Afrasastrasz]],enderType=[[NPC]],enderId=27575,rewardNextId=12372,wowhead=[[https://www.wowhead.com/wotlk/quest=12435]],image=[[assets/images/quests/placeholder.png]],desc=[[I abhor the loss of life... any life. But I will not stand idly by and allow Malygos to kill us and defile the temple! I have appointed Lord Afrasastrasz as the commander of Wyrmrest's defenses. Speak with Torastrasza to ride a drake down to him. Please lend him your aid, $N. Your involvement with the defense of Wyrmrest will be critical to us prevailing against the blue dragonflight.]],logDesc=[[Speak with Lord Afrasastrasz at Wyrmrest Temple.]]}
DB[12436]={id=12436,zoneId=394,name=[[Supplemental Income]],level=74,minLevel=73,giver=[[Provisioner Lorkran]],giverType=[[NPC]],giverId=26868,ender=[[Provisioner Lorkran]],enderType=[[NPC]],enderId=26868,wowhead=[[https://www.wowhead.com/wotlk/quest=12436]],image=[[assets/images/quests/placeholder.png]],desc=[[Hail, $c.  You'll find that here at Conquest Hold, we buy and sell what Krenna wants us to buy and sell... at the price that Krenna wants us to buy and sell. All this is stifling business.  I'm hoping to make a little bit of coin on the side and feed our grunts at the same time.  Why don't you go hunt down some stag and bring me the venison? They're numerous in the area, so bring me only the best meat.]],logDesc=[[Provisioner Lorkran at Conquest Hold wants you to obtain 5 Succulent Venison from  the nearby Tallhorn Stag.]]}
DB[12437]={id=12437,zoneId=394,name=[[Riding the Red Rocket]],level=74,minLevel=73,giver=[[Commander Howser]],giverType=[[NPC]],giverId=27759,ender=[[Commander Howser]],enderType=[[NPC]],enderId=27759,wowhead=[[https://www.wowhead.com/wotlk/quest=12437]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen, $n. This battle is as much over resources as tactical supremacy. I have a mission that could turn the tide in our struggle against the Horde here. There are torpedoes at the end of the dock that we can use to take down the Horde's lumber ship to the northwest. You'll need to get some of the fuel that's stored on the docked goblin ship just north of here, then ride one of the torpedoes into their transport!]],logDesc=[[Commander Howser at the lighthouse in Venture Bay wants you to destroy the Horde lumber shipment. Commander Howser will only be present at the lighthouse when the Alliance has it in their possession.]],rewards={{id=37836,qty=10}}}
DB[12438]={id=12438,zoneId=65,name=[[Wanted: Kreug Oathbreaker]],level=74,minLevel=71,giverType=[[NPC]],ender=[[Highlord Leoric Von Zeldig]],enderType=[[NPC]],enderId=27156,prevId=12251,wowhead=[[https://www.wowhead.com/wotlk/quest=12438]],image=[[assets/images/quests/placeholder.png]],desc=[[Posted by: Illusia Lune The Scourge flesh giant known as Kreug Oathbreaker was responsible for the deaths of my husband, children and my dear friends, the Whisperveils. Those brave enough to take on this bounty will find Kreug in the southeastern reaches of the Carrion Fields. I demand justice! Kill Kreug Oathbreaker! In the event that Kreug is slain, I have pooled money and items together and given them to Highlord Leoric Von Zeldig to give out as a reward. Please vindicate us!]],logDesc=[[Kill Kreug Oathbreaker and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.]],choiceRewards={{id=37957,qty=1},{id=37999,qty=1},{id=38042,qty=1},{id=38103,qty=1}}}
DB[12439]={id=12439,zoneId=65,name=[[A Disturbance In The West]],level=72,minLevel=71,giver=[[Vas the Unstable]],giverType=[[NPC]],giverId=27158,ender=[[Rodney Wells]],enderType=[[NPC]],enderId=26878,nextId=12440,rewardNextId=12440,wowhead=[[https://www.wowhead.com/wotlk/quest=12439]],image=[[assets/images/quests/placeholder.png]],desc=[[Another force threatens to destroy all that we have worked for, $N. You must head westward to Stars' Rest. Archmage Modera has sensed a great disturbance in the magical ley lines of our world that must be dealt with immediately! Go now, $N! Speak to Rodney Wells at the gryphon station here in Wintergarde and let him know the nature of your mission. He will place you on his fastest gryphon to deliver you to Stars' Rest. Speak with Archmage Modera when you arrive.]],logDesc=[[Speak to Rodney Wells at Wintergarde Keep to secure a ride to Stars' Rest in western Dragonblight.]]}
DB[12440]={id=12440,zoneId=65,name=[[To Stars' Rest!]],level=72,minLevel=71,giver=[[Rodney Wells]],giverType=[[NPC]],giverId=26878,ender=[[Image of Archmage Modera]],enderType=[[NPC]],enderId=26673,rewardNextId=12000,exGroup=11995,wowhead=[[https://www.wowhead.com/wotlk/quest=12440]],image=[[assets/images/quests/placeholder.png]],desc=[[When you are ready I will place you on my fastest gryphon to Stars' Rest. Once you get there, find and speak with Archmage Modera. Good luck, ally!]],logDesc=[[Speak with the Image of Archmage Modera at Stars' Rest in western Dragonblight. ]]}
DB[12441]={id=12441,zoneId=65,name=[[Wanted: High Shaman Bloodpaw]],level=74,minLevel=71,giverType=[[NPC]],ender=[[Highlord Leoric Von Zeldig]],enderType=[[NPC]],enderId=27156,prevId=12251,wowhead=[[https://www.wowhead.com/wotlk/quest=12441]],image=[[assets/images/quests/placeholder.png]],desc=[[Posted by: Drolfy While out in the Eldritch Heights with my cousins, Skrotee and Brote, a vicious band of wolvar from the Bloodpaw tribe attacked us. We attempted to flee, but I fear they got Skrotee and Brote. I demand retribution! Is there someone brave enough to venture to the southeastern reaches of Dragonblight, to the Eldritch Heights, and kill High Shaman Bloodpaw and his cronies? I have given a hefty sum of gold to Highlord Leoric Von Zeldig to disperse to anyone that claims this bounty!]],logDesc=[[Kill High Shaman Bloodpaw and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.]],choiceRewards={{id=38171,qty=1},{id=38172,qty=1},{id=38132,qty=1},{id=38169,qty=1},{id=38170,qty=1},{id=38131,qty=1}}}
DB[12442]={id=12442,zoneId=65,name=[[Wanted: Onslaught Commander Iustus]],level=74,minLevel=71,giverType=[[NPC]],ender=[[Highlord Leoric Von Zeldig]],enderType=[[NPC]],enderId=27156,prevId=12251,wowhead=[[https://www.wowhead.com/wotlk/quest=12442]],image=[[assets/images/quests/placeholder.png]],desc=[[Posted by: Highlord Leoric Von Zeldig Upon the northeastern path from Wintergarde a battalion of 7th Legion were ambushed and slain by Onslaught Commander Iustus and an army of mindless Scarlet Onslaught zealots. Such cold and calculated actions must be met with force! Wintergarde demands justice! Seek out Onslaught Commander Iustus at Onslaught Base Camp to the northeast and end his miserable existence. I will hand out the reward for this bounty to any who would dare take up the task! ]],logDesc=[[Kill Onslaught Commander Iustus and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward. ]],choiceRewards={{id=38115,qty=1},{id=38054,qty=1},{id=38529,qty=1},{id=38528,qty=1}}}
DB[12443]={id=12443,zoneId=394,name=[[Seeking Solvent]],level=74,minLevel=73,giver=[[Barblefink]],giverType=[[NPC]],giverId=27495,ender=[[Barblefink]],enderType=[[NPC]],enderId=27495,wowhead=[[https://www.wowhead.com/wotlk/quest=12443]],image=[[assets/images/quests/placeholder.png]],desc=[[Gah! Not again. Another blown gasket.... Every time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean. Tell ya what, $r. There's some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent. Get me one of those and I'll make it worth your trouble.]],logDesc=[[Barblefink at the Alliance base in Venture Bay wants you to bring him a canister of Element 115.]],rewards={{id=37836,qty=4}}}
DB[12444]={id=12444,zoneId=394,name=[[Blackriver Skirmish]],level=74,minLevel=73,giver=[[Scout Captain Carter]],giverType=[[NPC]],giverId=27783,ender=[[Scout Captain Carter]],enderType=[[NPC]],enderId=27783,wowhead=[[https://www.wowhead.com/wotlk/quest=12444]],image=[[assets/images/quests/placeholder.png]],desc=[[The Venture Company's on its way out of Grizzly Hills.  They used to run logging operations here, but things got a little too dangerous for them. Their abandoned sites are up for grabs and we sure as hell can't let the Horde get their hands on them. The Blackriver Logging Camp is the smallest of the three logging sites in this zone, but we still need it.  Do your part and fend off the Horde forces.  Any lumber they get here will be made into weapons to be used against us elsewhere.]],logDesc=[[Scout Captain Carter wants you to kill 10 Horde units or players in the Blackriver Logging Camp.]],rewards={{id=37836,qty=10}}}
DB[12445]={id=12445,name=[[]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12445]],image=[[assets/images/quests/placeholder.png]]}
DB[12446]={id=12446,zoneId=394,name=[[Always Seeking Solvent]],level=74,minLevel=73,giver=[[Barblefink]],giverType=[[NPC]],giverId=27495,ender=[[Barblefink]],enderType=[[NPC]],enderId=27495,prevId=12443,wowhead=[[https://www.wowhead.com/wotlk/quest=12446]],image=[[assets/images/quests/placeholder.png]],rewards={{id=37836,qty=2}}}
DB[12447]={id=12447,zoneId=65,name=[[The Obsidian Dragonshrine]],level=74,minLevel=72,giver=[[Nalice]],giverType=[[NPC]],giverId=27765,ender=[[Serinar]],enderType=[[NPC]],enderId=26593,wowhead=[[https://www.wowhead.com/wotlk/quest=12447]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge come. Korialstrasz calls upon his allies in a futile attempt to save their Ruby Dragonshrine, but it seems the good graces of the red flight don't extend to saving the shrines of the other flights. Surprised? I'm not. There is another of my brood who has left to clear our Obsidian Dragonshrine of the undead vermin that now infest it. All it would take to prove yourself more noble and righteous than Alexstrasza herself is a quick jaunt over there and a few swings of a blade. I'm amused.]],logDesc=[[Travel to the Obsidian Dragonshrine Northwest of Wymrest and just West of the Wrath Gate. Locate Serinar inside of the shrine and offer him your aid.]]}
DB[12448]={id=12448,zoneId=65,name=[[Heated Battle]],level=74,minLevel=71,giver=[[Vargastrasz]],giverType=[[NPC]],giverId=27763,ender=[[Vargastrasz]],enderType=[[NPC]],enderId=27763,prevId=12461,rewardNextId=12449,wowhead=[[https://www.wowhead.com/wotlk/quest=12448]],image=[[assets/images/quests/placeholder.png]],desc=[[The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, $r. Captain Drayzen leads a group of your kind in stemming the flow of the Scourge out of the shrine. Go to his aid... but please stay behind his men. The flow of Scourge is endless and I don't want to lose you in one of those scarred canyons.]],logDesc=[[Aid Captain Drayzen in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker. Return to Vargastrasz once you have finished this task.]]}
DB[12449]={id=12449,zoneId=65,name=[[Return to the Earth]],level=74,minLevel=71,giver=[[Vargastrasz]],giverType=[[NPC]],giverId=27763,ender=[[Vargastrasz]],enderType=[[NPC]],enderId=27763,prevId=12448,rewardNextId=12450,wowhead=[[https://www.wowhead.com/wotlk/quest=12449]],image=[[assets/images/quests/placeholder.png]],desc=[[I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks. Get into the shrine through the pass in the south... the Scourge presence should be lighter there. Search the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.]],logDesc=[[Enter the Ruby Dragonshrine through the southern pass and search for Ruby Acorns.  Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth.  Return to Vargastrasz once the task is complete.]]}
DB[12450]={id=12450,zoneId=65,name=[[Through Fields of Flame]],level=75,minLevel=71,giver=[[Vargastrasz]],giverType=[[NPC]],giverId=27763,ender=[[Vargastrasz]],enderType=[[NPC]],enderId=27763,prevId=12449,rewardNextId=12769,wowhead=[[https://www.wowhead.com/wotlk/quest=12450]],image=[[assets/images/quests/placeholder.png]],desc=[[I have one final task for you, $r... one that should turn the tide of this fight. Return to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine. I also need you to find the source of the corruption under the shrine and put an end to it. I know I have asked a lot of you, but if you do this for me, we will win this battle.]],logDesc=[[Enter the Ruby Dragonshrine through the southern pass, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Vargastrasz once the task is complete.]],choiceRewards={{id=37962,qty=1},{id=38004,qty=1},{id=38046,qty=1},{id=38108,qty=1}}}
DB[12451]={id=12451,zoneId=394,name=[[Onward to Camp Oneqwah]],level=74,minLevel=73,giver=[[Sergeant Nazgrim]],giverType=[[NPC]],giverId=27388,ender=[[Scout Vor'takh]],enderType=[[NPC]],enderId=26666,wowhead=[[https://www.wowhead.com/wotlk/quest=12451]],image=[[assets/images/quests/placeholder.png]],desc=[[While we build Conquest Hold, I sent Scout Vor'takh to make contact with our taunka allies in the east. They're based in Camp Oneqwah, which is in the easternmost part of Grizzly Hills, beyond Grizzlemaw. Make the journey there, hear Vor'takh's report and offer your assistance with anything he and the local chieftain may need. Your contributions to Conquest Hold have been exemplary and I know Vor'takh will be grateful for the assistance.]],logDesc=[[Speak with Scout Vor'takh at Camp Oneqwah.]]}
DB[12452]={id=12452,zoneId=65,name=[[zzOLD The Fate of the Ruby Dragonshrine]],level=74,minLevel=72,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12452]],image=[[assets/images/quests/placeholder.png]],logDesc=[[Bring Dahlia's Ruby Broach to Ceristrasz and inform him of her fate.]]}
DB[12453]={id=12453,zoneId=394,name=[[Eyes Above]],level=74,minLevel=73,giver=[[Windseer Grayhorn]],giverType=[[NPC]],giverId=27262,ender=[[Windseer Grayhorn]],enderType=[[NPC]],enderId=27262,wowhead=[[https://www.wowhead.com/wotlk/quest=12453]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been asked to lend my support to our efforts against the Alliance.  At the moment our military forces are about evenly matched and we're looking for ways to find an edge. The imperial eagles that fly over the mountains and trees in this area would make excellent scouts for us.  Take this silver feather and use it to bind my sight to that of them. Being able to see our enemy's movements will grant us the strategic advantage we need.  You'll find abundant eagles in the mountains to the east.]],logDesc=[[Windseer Grayhorn wants you to use the Silver Feather on 6 Imperial Eagles in Grizzly Hills.]],choiceRewards={{id=38762,qty=1},{id=38760,qty=1},{id=38761,qty=1}}}
DB[12454]={id=12454,zoneId=65,name=[[Cycle of Life]],level=74,minLevel=72,giver=[[Nishera the Garden Keeper]],giverType=[[NPC]],giverId=27255,ender=[[Nishera the Garden Keeper]],enderType=[[NPC]],enderId=27255,rewardNextId=12456,wowhead=[[https://www.wowhead.com/wotlk/quest=12454]],image=[[assets/images/quests/placeholder.png]],desc=[[Ysera sleeps in the Emerald Dream, watching over both the Dream and Azeroth. But a horrible nightmare has taken hold in the Dream, and now I fear that Ysera is being affected by it. Recently, I asked her to aid in the fight against the Scourge that are raising frostwyrms at the other dragonshrines. She misunderstood. Instead, she told our dragonshrine's defenders to treat those not of the green dragonflight as enemies. I need you to slay some of the skytalons. The shrine must regain its balance.]],logDesc=[[Nishera the Garden Keeper at the Emerald Dragonshrine has asked you to slay 5 Emerald Skytalons.]]}
DB[12455]={id=12455,zoneId=65,name=[[Scattered To The Wind]],level=73,minLevel=71,giver=[[Ambo Cash]],giverType=[[NPC]],giverId=1293,ender=[[Ambo Cash]],enderType=[[NPC]],enderId=1293,prevId=12326,rewardNextId=12457,wowhead=[[https://www.wowhead.com/wotlk/quest=12455]],image=[[assets/images/quests/placeholder.png]],desc=[[The munitions drop went badly, friend. The shipment of ammo from Westguard Keep was intercepted by the frostwyrms circling overhead. The flying machines were torn apart in a matter of seconds and their cargo was scattered to the wind. Most of it is still topside - on the Carrion Fields. I'm gonna need you to go back up and recover the munitions crates that are scattered all over this damned place. Hurry it up! We can't start this offensive without guns and ammo, $g buddy:missy;!]],logDesc=[[Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to recover 8 Wintergarde Munitions.]]}
DB[12456]={id=12456,zoneId=65,name=[[The Plume of Alystros]],level=74,minLevel=72,giver=[[Nishera the Garden Keeper]],giverType=[[NPC]],giverId=27255,ender=[[Nishera the Garden Keeper]],enderType=[[NPC]],enderId=27255,prevId=12454,wowhead=[[https://www.wowhead.com/wotlk/quest=12456]],image=[[assets/images/quests/placeholder.png]],desc=[[I can feel that the shrine is not completely back in balance. The verdant keeper has been angered by our actions, and I sense that he will not listen to reason. Alystros is an immense skytalon who perches at the south end of the Emerald Dragonshrine. It is he who is in charge of the dragonshrine's aerial defenses. I fear that we will have to deal with him. Take these skytalon molts and place them on the ground where he can see them. He will come. Bring me his plume.]],logDesc=[[Nishera the Garden Keeper at the Emerald Dragonshrine has asked you to acquire The Plume of Alystros.]],choiceRewards={{id=37937,qty=1},{id=37981,qty=1},{id=38024,qty=1},{id=38085,qty=1}}}
DB[12457]={id=12457,zoneId=65,name=[[The Chain Gun And You]],level=73,minLevel=71,giver=[[Ambo Cash]],giverType=[[NPC]],giverId=1293,ender=[[Ambo Cash]],enderType=[[NPC]],enderId=1293,prevId=12455,rewardNextId=12463,wowhead=[[https://www.wowhead.com/wotlk/quest=12457]],image=[[assets/images/quests/placeholder.png]],desc=[[We've set up chain guns and barricades directly to the east and to the west. Our injured soldiers are hiding in both rooms - trying their best to not alert the mindless ghouls to their presence. Now that we have ammo, I need you to man one of the chain guns and use it to blast a path clear for our soldiers! Once you're on board, call a soldier out from hiding and then lay down heavy fire to keep the Scourge off him! Get a move on!]],logDesc=[[Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to save 8 Injured 7th Legion Soldiers.]]}
DB[12458]={id=12458,zoneId=65,name=[[Seeds of the Lashers]],level=74,minLevel=72,giver=[[Lord Itharius]],giverType=[[NPC]],giverId=27785,ender=[[Lord Itharius]],enderType=[[NPC]],enderId=27785,rewardNextId=12459,wowhead=[[https://www.wowhead.com/wotlk/quest=12458]],image=[[assets/images/quests/placeholder.png]],desc=[[We need more weapons in the fight against the Scourge. The natural properties of the Emerald Dragonshrine to the southeast may be the answer. Any unliving creature, save those that Sylvanas has redeemed, that steps foot in the dragonshrine falls to dust. I want to test a theory, and I want you to be my instrument in doing so, young $r. Go to the Emerald Dragonshrine and take the seeds from the emerald lashers therein.]],logDesc=[[Lord Itharius at the top of Wyrmrest Temple has asked you to return with 3 Lasher Seeds.]]}
DB[12459]={id=12459,zoneId=65,name=[[That Which Creates Can Also Destroy]],level=74,minLevel=72,giver=[[Lord Itharius]],giverType=[[NPC]],giverId=27785,ender=[[Lord Itharius]],enderType=[[NPC]],enderId=27785,prevId=12458,wowhead=[[https://www.wowhead.com/wotlk/quest=12459]],image=[[assets/images/quests/placeholder.png]],desc=[[Since we only have three seeds, we must put them to the best possible use. Your targets are one of the reanimated frost wyrms circling to the north near Galakrond's Rest, Turgid the Vile in the ruined barracks at the Carrion Fields to the east, and Overseer Deathgaze at Jintha'kalar far to the northeast. While the seeds would outright destroy one of the lesser Scourge, they will greatly weaken these three. Enough so, in fact, that you should be able to handle them on your own.]],logDesc=[[Lord Itharius at the top of Wyrmrest Temple has asked you to destroy a Weakened Reanimated Frost Wyrm, Weakened Turgid the Vile, and Weakened Overseer Deathgaze.]],choiceRewards={{id=37940,qty=1},{id=37983,qty=1},{id=38027,qty=1},{id=38088,qty=1}}}
DB[12460]={id=12460,zoneId=65,name=[[Report to the Ruby Dragonshrine]],level=74,minLevel=71,giver=[[Lauriel Trueblade]],giverType=[[NPC]],giverId=27803,ender=[[Ceristrasz]],enderType=[[NPC]],enderId=27506,prevId=12766,rewardNextId=12416,wowhead=[[https://www.wowhead.com/wotlk/quest=12460]],image=[[assets/images/quests/placeholder.png]],desc=[[We need you at the Ruby Dragonshrine. The dragons are beset on all sides by the blue flight and the scourge... they're in no better a state than we are. The situation seems dire, but this affords us a rare opportunity to establish a valuable alliance. I secured a regiment to aid the red dragonflight against the Scourge at the Ruby Dragonshrine. If you have a fight in you, please go find Ceristrasz on the ridge east of the shrine and help him in any way that you can.]],logDesc=[[Report to Ceristrasz on the ridge east of the Ruby Dragonshrine, west of Wyrmrest.]]}
DB[12461]={id=12461,zoneId=65,name=[[Report to the Ruby Dragonshrine]],level=74,minLevel=71,giver=[[Golluck Rockfist]],giverType=[[NPC]],giverId=27804,ender=[[Vargastrasz]],enderType=[[NPC]],enderId=27763,prevId=12767,rewardNextId=12448,wowhead=[[https://www.wowhead.com/wotlk/quest=12461]],image=[[assets/images/quests/placeholder.png]],desc=[[You are leaving to the Ruby Dragonshrine. This is not a request. The dragons are beset on all sides by the blue flight and the scourge... they're in no better a state than we are. It is not often we are afforded the opportunity to redeem ourselves for the transgressions of our ancestors. I have secured a regiment to aid the red dragonflight against the Scourge at the Ruby Dragonshrine. Join them and crush the Scourge beneath your boots! For the Horde!]],logDesc=[[Report to Vargastrasz on a ridge outside of the Ruby Dragonshrine, just east of Agmar's Hammer.]]}
DB[12462]={id=12462,zoneId=65,name=[[Breaking Off A Piece]],level=73,minLevel=71,giver=[[Yord "Calamity" Icebeard]],giverType=[[NPC]],giverId=27319,ender=[[Yord "Calamity" Icebeard]],enderType=[[NPC]],enderId=27319,wowhead=[[https://www.wowhead.com/wotlk/quest=12462]],image=[[assets/images/quests/placeholder.png]],desc=[[Just down the steps lies the gateway to damnation: Scourge as far as the eye can see and getting thicker with each passing moment. What little intelligence we've been able to gather indicates that two Scourge necrolords are furiously working at emptying the first two crypts down below. Before we can breach the inner chamber to Thel'zan, we'll need to take care of those two clowns and their Naxxramas cronies. Go down into the mausoleum and take out the necrolords and the Naxxramas dreadguards and shades.]],logDesc=[[Yord "Calamity" Icebeard at the Wintergarde Mausoleum in Dragonblight wants you to kill Necrolord X'avius, Necrolord Horus, and 15 Naxxramas Scourge. ]],choiceRewards={{id=37959,qty=1},{id=38001,qty=1},{id=38044,qty=1},{id=38105,qty=1}}}
DB[12463]={id=12463,zoneId=65,name=[[Plunderbeard Must Be Found!]],level=73,minLevel=71,giver=[[Ambo Cash]],giverType=[[NPC]],giverId=1293,ender=[[Plunderbeard]],enderType=[[NPC]],enderId=27828,prevId=12457,rewardNextId=12465,wowhead=[[https://www.wowhead.com/wotlk/quest=12463]],image=[[assets/images/quests/placeholder.png]],desc=[[There's been talk of a tunnel dug by Scourge that connects the embalming chambers of the mausoleum with the large crypts, now unearthed by Thel'zan and his minions. I recently sent my best rogue, Plunderbeard, in search of answers, but have yet to hear back from him. If I were a betting man I'd wager that he's a goner. I want you to go down those steps and head straight through the embalming chamber and look for Plunderbeard. Dead or alive, he'll have answers. ]],logDesc=[[Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to find Plunderbeard.]]}
DB[12464]={id=12464,zoneId=65,name=[[My Old Enemy]],level=73,minLevel=71,giver=[[Commander Eligor Dawnbringer]],giverType=[[NPC]],giverId=27784,ender=[[Commander Eligor Dawnbringer]],enderType=[[NPC]],enderId=27784,prevId=12251,wowhead=[[https://www.wowhead.com/wotlk/quest=12464]],image=[[assets/images/quests/placeholder.png]],desc=[[My old enemy, High General Abbendis, has come to Northrend. Somehow she survived the attacks upon Tyr's Hand and brought a small force north. They've established New Hearthglen to the south. While they could prove useful in fighting the Scourge, Abbendis herself is far too shrewd an opponent to let live. Trust me, if we let them stand, she will be at our throats before the dust settles. So, we'll deprive them of their leadership and go about our business. Bring me her head as proof.]],logDesc=[[Deliver The High General's Head to Commander Eligor Dawnbringer at Wintergarde Keep.]],choiceRewards={{id=38178,qty=1},{id=38177,qty=1},{id=38135,qty=1},{id=38176,qty=1},{id=38134,qty=1},{id=38295,qty=1}}}
DB[12465]={id=12465,zoneId=65,name=[[Plunderbeard's Journal]],level=73,minLevel=71,giver=[[Plunderbeard]],giverType=[[NPC]],giverId=27828,ender=[[Ambo Cash]],enderType=[[NPC]],enderId=1293,prevId=12463,rewardNextId=12466,wowhead=[[https://www.wowhead.com/wotlk/quest=12465]],image=[[assets/images/quests/placeholder.png]],desc=[[Whatever was written on the remaining pages of Plunderbeard's journal must be recovered. Search the chambers located on the other side of this tunnel for Plunderbeard's assailants. They must be the ones who tore the journal apart! Should you recover the missing pages, return them to Ambo Cash at the entrance of the Wintergarde Mausoleum.]],logDesc=[[Recover Page 4 of Plunderbeard's Journal, Page 5 of Plunderbeard's Journal, Page 6 of Plunderbeard's Journal, and Page 7 of Plunderbeard's Journal and return them to Ambo Cash at the Wintergarde Mausoleum in Dragonblight.]]}
DB[12466]={id=12466,zoneId=65,name=[[Chasing Icestorm: The 7th Legion Front]],level=73,minLevel=71,giver=[[Ambo Cash]],giverType=[[NPC]],giverId=1293,ender=[[Legion Commander Tyralion]],enderType=[[NPC]],enderId=27844,prevId=12465,rewardNextId=12467,wowhead=[[https://www.wowhead.com/wotlk/quest=12466]],image=[[assets/images/quests/placeholder.png]],desc=[[You need to get to the 7th Legion Front in northern Dragonblight. Return to Wintergarde Keep and take the north gate out of town. Keep north until you hit a road. Take a left on that road and follow it until you reach the snowline. Once at the snowline keep heading west until you hit the Path of the Titans. Follow that north and it'll lead you right into the 7th Legion Front. Once there, speak with Legion Commander Tyralion. He'll be expecting you. And $N - it has been a pleasure. Farewell.]],logDesc=[[Report to Legion Commander Tyralion at the 7th Legion Front in central Dragonblight.]]}
DB[12467]={id=12467,zoneId=65,name=[[Chasing Icestorm: Thel'zan's Phylactery]],level=73,minLevel=71,giver=[[Legion Commander Tyralion]],giverType=[[NPC]],giverId=27844,ender=[[High Commander Halford Wyrmbane]],enderType=[[NPC]],enderId=27136,prevId=12466,rewardNextId=12472,wowhead=[[https://www.wowhead.com/wotlk/quest=12467]],image=[[assets/images/quests/placeholder.png]],desc=[[Your frostwyrm is out there. <Tyralion points west.> And it's a big one! When you're ready to fight, go speak with "Wyrmbait." He'll "fetch" her. Once Icestorm is close enough we'll chain her to the ground and finish her off! Hopefully, with your help, we'll be able to take her down and get you that phylactery. Once you've got the phylactery, return to Wintergarde Keep and report to High Commander Halford Wyrmbane. He's been making preparations for the final showdown with Thel'zan.]],logDesc=[[Recover Thel'zan's Phylactery from Icestorm and return it to High Commander Halford Wyrmbane at Wintergarde Keep. ]],choiceRewards={{id=37958,qty=1},{id=38000,qty=1},{id=38043,qty=1},{id=38104,qty=1}}}
DB[12468]={id=12468,zoneId=394,name=[[The Conqueror's Task]],level=74,minLevel=73,giver=[[Conqueror Krenna]],giverType=[[NPC]],giverId=26860,ender=[[Sergeant Nazgrim]],enderType=[[NPC]],enderId=27388,prevId=12487,nextId=12257,rewardNextId=12257,wowhead=[[https://www.wowhead.com/wotlk/quest=12468]],image=[[assets/images/quests/placeholder.png]],desc=[[The Horde is a magnificent war machine and you are nothing but a cog. I am in charge of securing fuel for this machine.  If I fail, the machine fails. Lumber, ore, water... it's all here and we want it.  And so does the Alliance. Before we can move against the human scum, we need to solidify our control over the western region. Speak to Sergeant Nazgrim about eradicating the vrykul in Voldrune and then maybe - if you turn out to not be a complete failure - we'll send you on further tasks.]],logDesc=[[Speak to Sergeant Nazgrim in Conquest Hold.]]}
DB[12469]={id=12469,zoneId=65,name=[[Return to Sender]],level=74,minLevel=72,giver=[[Nozzlerust Supply Runner]],giverType=[[NPC]],giverId=26896,ender=[[Xink]],enderType=[[NPC]],enderId=26660,rewardNextId=12044,wowhead=[[https://www.wowhead.com/wotlk/quest=12469]],image=[[assets/images/quests/placeholder.png]],desc=[[Upon closer examination, the goblin appears to have been running a pack full of explosives across the wastes for delivery. The harpy feathers half-buried in the snow nearby suggest how he met his ill fate. It appears that the goblin was bringing the explosives towards the Wrath Gate from somewhere to the east. It seems most prudent to follow the ridge back to the east and inform the sender of their runner's fate.]],logDesc=[[Follow the ridge to the east and deliver the pack of explosives to Xink at Nozzlerust Post in northern Dragonblight.]]}
DB[12470]={id=12470,zoneId=65,name=[[Mystery of the Infinite]],level=75,minLevel=72,giver=[[Chromie]],giverType=[[NPC]],giverId=27856,ender=[[Chromie]],enderType=[[NPC]],enderId=27856,wowhead=[[https://www.wowhead.com/wotlk/quest=12470]],image=[[assets/images/quests/placeholder.png]],desc=[[A time storm at the Bronze Dragonshrine to the northeast is keeping immortals from entering. The Infinite Dragonflight are in a fight inside with the defenders to wrest control of the dragonshrine. We must take this opportunity to gain information. You are not immortal. You can cross into the dragonshrine and use the Hourglass of Eternity. Protect the hourglass for long enough and the leader of the Infinite Dragonflight should be revealed. Be warned, the Infinite Dragonflight will try to stop you!]],logDesc=[[Chromie, at the top of Wyrmrest Temple, has asked you to travel to the Bronze Dragonshrine. Once inside, place the Hourglass of Eternity on the ground. Protect the hourglass for as long as it lasts and then return to her with whatever information you gain.]],choiceRewards={{id=38173,qty=1},{id=38174,qty=1},{id=38133,qty=1},{id=38202,qty=1}}}
DB[12471]={id=12471,zoneId=3537,name=[[Cruelty of the Kvaldir]],level=71,minLevel=68,giver=[[Captured Tuskarr Prisoner]],giverType=[[NPC]],giverId=25636,ender=[[Karuk]],enderType=[[NPC]],enderId=25435,wowhead=[[https://www.wowhead.com/wotlk/quest=12471]],image=[[assets/images/quests/placeholder.png]],desc=[[I thank you for saving me, $N.  The kvaldir are animals! They made us fight the other prisoners.  It would've been more merciful to just kill us all. The youngling Karuk is still alive -- I noticed him arrive here.  Tell him his father fought until the end.]],logDesc=[[Speak to Karuk about the Captured Tuskarr Prisoner.]]}
DB[12472]={id=12472,zoneId=65,name=[[Finality]],level=73,minLevel=71,giver=[[High Commander Halford Wyrmbane]],giverType=[[NPC]],giverId=27136,ender=[[Legion Commander Yorik]],enderType=[[NPC]],enderId=27857,prevId=12467,wowhead=[[https://www.wowhead.com/wotlk/quest=12472]],image=[[assets/images/quests/placeholder.png]],desc=[[Thanks to your heroics, Lord Fordragon has given the command to launch a full assault against Thel'zan. 7th Legion have made their way into the summoning chamber of the mausoleum and located what appears to be a gateway to hell. The only piece that's missing now is you. Take the phylactery and report to Legion Commander Yorik inside the Wintergarde Mausoleum. There is a tunnel that the Scourge dug out just outside the keep that you can take to get to Yorik quickly. Go now, $N! Lead us to victory!]],logDesc=[[Take Thel'zan's Phylactery to Legion Commander Yorik inside the Wintergarde Mausoleum in Dragonblight.]]}
DB[12473]={id=12473,zoneId=65,name=[[An End And A Beginning]],level=73,minLevel=71,giver=[[Legion Commander Yorik]],giverType=[[NPC]],giverId=27857,ender=[[High Commander Halford Wyrmbane]],enderType=[[NPC]],enderId=27136,prevId=12472,rewardNextId=12474,wowhead=[[https://www.wowhead.com/wotlk/quest=12473]],image=[[assets/images/quests/placeholder.png]],desc=[[Every good story has a beginning and an ending, $N. While your story is far from over, I'll be damned if it's not already turning out to be the stuff of legend! No matter what happens to us when this is all over, what you've done at Wintergarde will be a tale told for years to come. Now, ally, when you are ready I will use the phylactery to coax Thel'zan out of hiding. Should we somehow succeed, report the victory to High Commander Halford Wyrmbane at Wintergarde Keep.]],logDesc=[[Defeat Thel'zan the Duskbringer and report to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.]]}
DB[12474]={id=12474,zoneId=65,name=[[To Fordragon Hold!]],level=73,minLevel=71,giver=[[High Commander Halford Wyrmbane]],giverType=[[NPC]],giverId=27136,ender=[[Highlord Bolvar Fordragon]],enderType=[[NPC]],enderId=27872,prevId=12473,rewardNextId=12495,wowhead=[[https://www.wowhead.com/wotlk/quest=12474]],image=[[assets/images/quests/placeholder.png]],desc=[[With the Naxxramas war machine stopped dead in its tracks the time has come for you to help our forces at Angrathar, the Wrathgate. Nestled against the mountain in northern Dragonblight is our base of operations, Fordragon Hold. It is there that Lord Fordragon awaits your arrival! Go now, $N! Take the north gate out of town and travel north by northwest until you arrive at your destination. Light protect you!]],logDesc=[[Venture to Fordragon Hold in Dragonblight and speak with Highlord Bolvar Fordragon. ]],choiceRewards={{id=38541,qty=1},{id=38543,qty=1},{id=38540,qty=1},{id=38542,qty=1}}}
DB[12475]={id=12475,zoneId=65,name=[[What Secrets Men Hide]],level=73,minLevel=71,giver=[[Zelig the Visionary]],giverType=[[NPC]],giverId=27314,ender=[[Zelig the Visionary]],enderType=[[NPC]],enderId=27314,prevId=12305,rewardNextId=12478,wowhead=[[https://www.wowhead.com/wotlk/quest=12475]],image=[[assets/images/quests/placeholder.png]],desc=[[After the betrayal at the Forgotten Shore, Prince Arthas - with Muradin in tow - began his quest for Frostmourne. Could the location of the cavern where Frostmourne was found be near? What secrets could it hold? While the orb has no answers for these questions, it does show me something. To the northeast of Wintergarde Keep is an outpost built by the Scarlet Onslaught. Somewhere within that outpost is a map. The orb tells me that this map will be of great use to us. Retrieve it!]],logDesc=[[Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to find the Onslaught Map and return it to him.]]}
DB[12476]={id=12476,zoneId=65,name=[[The Return of the Crusade?]],level=73,minLevel=71,giver=[[Commander Lynore Windstryke]],giverType=[[NPC]],giverId=27155,ender=[[Commander Lynore Windstryke]],enderType=[[NPC]],enderId=27155,prevId=12305,wowhead=[[https://www.wowhead.com/wotlk/quest=12476]],image=[[assets/images/quests/placeholder.png]],desc=[[To the northeast of Wintergarde Keep is a newly built encampment, set up by the Scarlet Crusade - or rather - the Scarlet Onslaught as they now call themselves. While we are unsure as to why they are in Northrend, they are certainly no less dangerous than they were before. As of last night the Scarlet Onslaught has killed twelve of our soldiers. They must be taught a lesson, $N. Go to Onslaught Base Camp and thin them out.  ]],logDesc=[[Commander Lynore Windstryke at Wintergarde Keep in Dragonblight wants you to kill 20 Scarlet Onslaught at the Onslaught Base Camp.]],rewards={{id=33447,qty=5}}}
DB[12477]={id=12477,zoneId=65,name=[[The Path of Redemption]],level=73,minLevel=71,giver=[[High Commander Halford Wyrmbane]],giverType=[[NPC]],giverId=27136,ender=[[High Commander Halford Wyrmbane]],enderType=[[NPC]],enderId=27136,prevId=12305,wowhead=[[https://www.wowhead.com/wotlk/quest=12477]],image=[[assets/images/quests/placeholder.png]],desc=[["The Path of Redemption," ever heard of it? It is allegedly a journal that holds the prophetic ramblings of High General Abbendis of the Scarlet Onslaught. Within that book can be found the motivations and goals of the Scarlet zealots - not to mention a whole lot of insanity. Venture to Onslaught Base Camp, northeast of Wintergarde Keep, and recover a copy of "The Path of Redemption" from one of the Onslaught soldiers.]],logDesc=[[Return "The Path of Redemption" to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.]]}
DB[12478]={id=12478,zoneId=65,name=[[Frostmourne Cavern]],level=73,minLevel=71,giver=[[Zelig the Visionary]],giverType=[[NPC]],giverId=27314,ender=[[Zelig the Visionary]],enderType=[[NPC]],enderId=27314,prevId=12475,wowhead=[[https://www.wowhead.com/wotlk/quest=12478]],image=[[assets/images/quests/placeholder.png]],desc=[[They have labeled the cave as Frostmourne Cavern. Why the Scarlet Onslaught is interested in such things is unknown, but by the look of things, the area surrounding the cave is heavily guarded. Nonetheless, we must proceed! Take this scrying orb and travel north out of town and then northwest towards Scarlet Point. Make your way into the cave and battle your way to the bottom. Once there, use the orb. Return here with what you discover.]],logDesc=[[Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to use Zelig's Scrying Orb at the bottom of Frostmourne Cavern. Unlock the secrets of the past!]],choiceRewards={{id=38530,qty=1},{id=38532,qty=1},{id=38531,qty=1},{id=38533,qty=1}}}
DB[12479]={id=12479,zoneId=3703,name=[[Onwards to Northrend!]],level=70,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12479]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend. You can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord.]],logDesc=[[Speak to the Alliance Recruiter inside Valiance Keep in Borean Tundra or the one at Vengeance Landing in Howling Fjord.]]}
DB[12480]={id=12480,zoneId=3703,name=[[Onwards to Northrend!]],level=70,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12480]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend. You can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.]],logDesc=[[Speak to the Horde Recruiter inside Warsong Hold in Borean Tundra or Vengeance Landing in Howling Fjord.]]}
DB[12481]={id=12481,zoneId=495,name=[[Adding Injury to Insult]],level=71,minLevel=68,giver=[[Lydell]],giverType=[[NPC]],giverId=24458,ender=[[Lydell]],enderType=[[NPC]],enderId=24458,prevId=11303,wowhead=[[https://www.wowhead.com/wotlk/quest=12481]],image=[[assets/images/quests/placeholder.png]],desc=[[The vrykul are being clever about this.  Fortunately I've a trick up my sleeve. This leader of theirs, Bjorn, is a real hothead.  We've pieced together enough of their language to fashion what we think is a good insult.  Something involving his mother and large barnyard animals... we're not quite sure. Take this piece of paper and read it to him.  Once he starts chasing you, lure him back here.  We'll make sure he doesn't make it out alive.]],logDesc=[[Read the Vrykul Insult to Bjorn Halgurdsson in Baleheim, then lead him back to Lydell's Ambush and help slay him.]],choiceRewards={{id=35889,qty=1},{id=35888,qty=1},{id=35890,qty=1},{id=35891,qty=1}}}
DB[12482]={id=12482,zoneId=495,name=[[Against Nifflevar]],level=71,minLevel=68,giver=[[Ranger Captain Areiel]],giverType=[[NPC]],giverId=27922,ender=[[Ranger Captain Areiel]],enderType=[[NPC]],enderId=27922,wowhead=[[https://www.wowhead.com/wotlk/quest=12482]],image=[[assets/images/quests/placeholder.png]],desc=[[We await reinforcements from Vengeance Landing to move against Nifflevar.  If we were to capture it earlier, though, it would provide us with a great advantage over the Alliance. Head into town and see if you can put a dent in their numbers.]],logDesc=[[Ranger Captain Areiel wants you to go to Nifflevar and slay 5 Dragonflayer Warriors, 4 Dragonflayer Rune-Seers and 4 Dragonflayer Hunting Hounds.]]}
DB[12483]={id=12483,zoneId=394,name=[[Shimmercap Stew]],level=75,minLevel=73,giver=[[Prigmon]],giverType=[[NPC]],giverId=26519,ender=[[Prigmon]],enderType=[[NPC]],enderId=26519,rewardNextId=12190,wowhead=[[https://www.wowhead.com/wotlk/quest=12483]],image=[[assets/images/quests/placeholder.png]],desc=[[Say, while yer here, how bout ya help ol' Prigmon with a little chore? I got a friend who can make a mean stew - one like ya never tasted before! There be a few ingredients found in these parts that he be needin'. They be in ruins to the southwest and the camp just north o' here. Whatd'ya say, mon?]],logDesc=[[Prigmon in Granite Springs wants you to collect 5 Shimmering Snowcaps and 5 Ice Serpent Eyes from Drak'Zin Ruins and 5 Sweetroot from Zeb'Halak.]]}
DB[12484]={id=12484,zoneId=394,name=[[Scourgekabob]],level=74,minLevel=73,giver=[[Prigmon]],giverType=[[NPC]],giverId=26519,ender=[[Mack Fearsen]],enderType=[[NPC]],enderId=26604,prevId=11990,wowhead=[[https://www.wowhead.com/wotlk/quest=12484]],image=[[assets/images/quests/placeholder.png]],desc=[[Ugh. Wrappin' up these unfortunate trolls be makin' my heart ache, but not so much as my back! Help ol' Prigmon out and haul one of these carcasses over to Mack. If we don't burn 'em they be walkin' again in no time.]],logDesc=[[Prigmon at Granite Springs wants you to bring a Mummified Troll Carcass to Mack Fearsen and place it in the fire.]]}
DB[12485]={id=12485,zoneId=495,name=[[Howling Fjord: aa - A - LK FLAG]],level=70,minLevel=60,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12485]],image=[[assets/images/quests/placeholder.png]]}
DB[12486]={id=12486,zoneId=3537,name=[[To Bor'gorok Outpost, Quickly!]],level=71,minLevel=69,giver=[[Sauranok the Mystic]],giverType=[[NPC]],giverId=25272,ender=[[Spirit Talker Snarlfang]],enderType=[[NPC]],enderId=25339,prevId=-11598,rewardNextId=11624,wowhead=[[https://www.wowhead.com/wotlk/quest=12486]],image=[[assets/images/quests/placeholder.png]],desc=[[Did you feel it? <Sauranok momentarily clutches his chest in confusion. His hand comes away trailing red-hot steam.> Something terrible has happened to my old friend, Farseer Grimwalker. I just sensed it. He had a pupil that he took with him when he went north. They were going to help the overlord establish an outpost on the edge of Sholazar Basin. Her name is Snarlfang. She is a spirit talker. Perhaps she will know what happened. Or, at least, she can help you to find out.]],logDesc=[[Speak with Spirit Talker Snarlfang at Bor'gorok Outpost.]]}
DB[12487]={id=12487,zoneId=394,name=[[To Conquest Hold, But Be Careful!]],level=74,minLevel=73,giver=[[High Executor Wroth]],giverType=[[NPC]],giverId=27243,ender=[[Conqueror Krenna]],enderType=[[NPC]],enderId=26860,rewardNextId=12468,wowhead=[[https://www.wowhead.com/wotlk/quest=12487]],image=[[assets/images/quests/placeholder.png]],desc=[[I've received a request for help from our base in the Grizzly Hills. I'm sending you to see Conqueror Krenna. <The high executor waves a sheaf of parchment in the air as if he could care less what is written on it.> She's attempting to secure all of the natural resources or somesuch. Just watch your back around her. The word is that she's aggressive even for an orc. Follow the road east and then southeast. Cross the bridge at the Dragonspine Tributary and go east from the Evergreen Trading Post.]],logDesc=[[Present yourself to Conqueror Krenna at Conquest Hold in the Grizzly Hills.]]}
DB[12488]={id=12488,zoneId=65,name=[[The High Executor Needs You]],level=74,minLevel=73,giver=[[Senior Sergeant Juktok]],giverType=[[NPC]],giverId=26415,ender=[[High Executor Wroth]],enderType=[[NPC]],enderId=27243,rewardNextId=12487,wowhead=[[https://www.wowhead.com/wotlk/quest=12488]],image=[[assets/images/quests/placeholder.png]],desc=[[It's a good thing that I intercepted this request from High Executor Wroth before it got to Overlord Agmar. What is Wroth thinking? <The sergeant rips up the letter that he's holding.> $C, go see what it is that the high executor wants. Follow the road east and pass through The Dragon Wastes. You'll find a path leading up out of the wastes on the southeast side, and the Forsaken town, Venomspite, will stand before you on the south side of the mountain.]],logDesc=[[Speak with High Executor Wroth at Venomspite in Dragonblight.]]}
DB[12489]={id=12489,zoneId=3711,name=[[Welcome to Sholazar Basin]],level=76,minLevel=76,giver=[[Monte Muzzleshot]],giverType=[[NPC]],giverId=27987,ender=[[Hemet Nesingwary]],enderType=[[NPC]],enderId=27986,prevId=12521,wowhead=[[https://www.wowhead.com/wotlk/quest=12489]],image=[[assets/images/quests/placeholder.png]],desc=[[So, where did you come from? I don't suppose that fool of an archmage sent you, too? You're lucky to be in one piece, $g laddie:lass;! They nearly blew you up! The jungle here's a darned dangerous place, 'specially with the Venture Company about.  Git you! Go see the boss... he'll sort you out. The camp's at the end of that path to the northwest. Now, git!]],logDesc=[[Follow the path to the northwest to reach the camp that Monte mentioned.]]}
DB[12490]={id=12490,zoneId=3537,name=[[Veehja's Revenge]],level=71,minLevel=68,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12490]],image=[[assets/images/quests/placeholder.png]],desc=[[We share a common enemy today, $r!  My people have been wiped out by these Kvaldir... my city has been all but destroyed.  It is time for exacting revenge! In return for my help, I'd like you to slay the barbaric monsters that defile Riplash.  You will be well rewarded, $c.]],logDesc=[[Veehja at the Shrine of Scales wants you to slay 6 Skadir Mariners, 3 Skadir Mistweavers and 2 Skadir Runecasters.]]}
DB[12493]={id=12493,zoneId=3711,name=[[PvP Test]],name_loc=[[PvP Test]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12493]],image=[[assets/images/quests/placeholder.png]],desc=[[Kill me some guys from the other side!  Those guys suck!  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.]],logDesc=[[Kill 10 opponents.]]}
DB[12494]={id=12494,name=[[FLAG: Riding Trainer Advertisement (20)]],name_loc=[[FLAG: Riding Trainer Advertisement (20)]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12494]],image=[[assets/images/quests/placeholder.png]]}
DB[12495]={id=12495,zoneId=65,name=[[Audience With The Dragon Queen]],level=74,minLevel=71,giver=[[Highlord Bolvar Fordragon]],giverType=[[NPC]],giverId=27872,ender=[[Alexstrasza the Life-Binder]],enderType=[[NPC]],enderId=26917,prevId=12474,nextId=12497,rewardNextId=12497,wowhead=[[https://www.wowhead.com/wotlk/quest=12495]],image=[[assets/images/quests/placeholder.png]],desc=[[Our assault against Angrathar has staggered the Scourge, but they remain unrelenting. From overhead they send their frost wyrms to strafe the field of battle, making an advance upon the gate itself impossible. The frost wyrm attacks must be stopped, but before we defile the bones of ancient dragons, we must gain permission from their queen. Travel southeast to Wyrmrest Temple and seek out Queen Alexstrasza. Tell her what we must do and ask her for guidance. Go now, $N!]],logDesc=[[Seek out Alexstrasza the Life-Binder at Wyrmrest Temple in Dragonblight.]]}
DB[12496]={id=12496,zoneId=65,name=[[Audience With The Dragon Queen]],level=74,minLevel=71,giver=[[Saurfang the Younger]],giverType=[[NPC]],giverId=25257,ender=[[Alexstrasza the Life-Binder]],enderType=[[NPC]],enderId=26917,prevId=12224,nextId=12497,rewardNextId=12497,wowhead=[[https://www.wowhead.com/wotlk/quest=12496]],image=[[assets/images/quests/placeholder.png]],desc=[[Though I know you hunger to destroy the Scourge that stand before us at the Wrath Gate, we must first deal with the threat that looms overhead. Until the strafing assaults of the frost wyrms are halted, we cannot move forward. But before we assault the dying grounds of dragons, we must first be granted permission. Venture now to the hallowed halls of dragonkind: Wyrmrest Temple. Once there, seek out Queen Alexstrasza. Ride now, $N! Southeast, to Wyrmrest!]],logDesc=[[Seek out Alexstrasza the Life-Binder at Wyrmrest Temple in Dragonblight.]]}
DB[12497]={id=12497,zoneId=65,name=[[Galakrond and the Scourge]],level=74,minLevel=71,giver=[[Alexstrasza the Life-Binder]],giverType=[[NPC]],giverId=26917,ender=[[Torastrasza]],enderType=[[NPC]],enderId=26949,rewardNextId=12498,wowhead=[[https://www.wowhead.com/wotlk/quest=12497]],image=[[assets/images/quests/placeholder.png]],desc=[[Atop the Wicked Coil, the Grand Necrolord of the Scourge, Antiok, sits upon the shoulders of the reconstructed storm giant lord, Thiassi. From there he commands the armies of undead to work day and night to unearth Galakrond's massive bones. Should they succeed in raising Galakrond, all of your efforts will have been for naught. While I cannot call down the full fury of the Red Dragonflight to assist you in your journey, I will grant you my blessing. Go now and speak with my majordomo, Torastrasza.]],logDesc=[[Speak with Torastrasza at Wyrmrest Temple in Dragonblight.]]}
DB[12498]={id=12498,zoneId=65,name=[[On Ruby Wings]],level=74,minLevel=71,giver=[[Torastrasza]],giverType=[[NPC]],giverId=26949,ender=[[Alexstrasza the Life-Binder]],enderType=[[NPC]],enderId=26917,prevId=12497,wowhead=[[https://www.wowhead.com/wotlk/quest=12498]],image=[[assets/images/quests/placeholder.png]],desc=[[Use this beacon to signal a Wyrmrest vanquisher. Climb upon its back and fly north to Galakrond's Rest. Once there, command the dragon to destroy the Scourge scavengers that work to unearth Galakrond. Once the area has been cleansed, fly to the Wicked Coil, overlooking Galakrond's Rest, to destroy Grand Necrolord Antiok and recover the scythe that he uses to control the wyrms. Do this and return to Queen Alexstrasza for a hero's reward! $N, beware the rotting storm giants that wander the area!]],logDesc=[[Destroy 30 Wastes Scavengers and recover the Scythe of Antiok. Return to Alexstrasza the Life-Binder at Wyrmrest Temple should you complete this task.]],choiceRewards={{id=38010,qty=1},{id=38053,qty=1},{id=38114,qty=1},{id=38073,qty=1}}}
DB[12499]={id=12499,zoneId=65,name=[[Return To Angrathar]],level=74,minLevel=71,giver=[[Alexstrasza the Life-Binder]],giverType=[[NPC]],giverId=26917,ender=[[Highlord Bolvar Fordragon]],enderType=[[NPC]],enderId=27872,prevId=12498,wowhead=[[https://www.wowhead.com/wotlk/quest=12499]],image=[[assets/images/quests/placeholder.png]],desc=[[With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth. The time to make your final stand is now, $N. Return to Fordragon Hold and notify Highlord Fordragon. ]],logDesc=[[Speak with Highlord Bolvar Fordragon at Fordragon Hold and tell him of your victory over the Scourge. ]]}
DB[12500]={id=12500,zoneId=65,name=[[Return To Angrathar]],level=74,minLevel=71,giver=[[Alexstrasza the Life-Binder]],giverType=[[NPC]],giverId=26917,ender=[[Saurfang the Younger]],enderType=[[NPC]],enderId=25257,prevId=12498,wowhead=[[https://www.wowhead.com/wotlk/quest=12500]],image=[[assets/images/quests/placeholder.png]],desc=[[With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth. The time to make your final stand is now, $N. Return to the Kor'kron Vanguard and notify Saurfang the Younger.]],logDesc=[[Speak with Saurfang the Younger at the Kor'kron Vangaurd and tell him of your victory over the Scourge.]]}
DB[12501]={id=12501,zoneId=66,name=[[Troll Patrol]],level=76,minLevel=74,giver=[[Commander Kunz]],giverType=[[NPC]],giverId=28039,ender=[[Commander Kunz]],enderType=[[NPC]],enderId=28039,prevId=12596,wowhead=[[https://www.wowhead.com/wotlk/quest=12501]],image=[[assets/images/quests/placeholder.png]],desc=[[Unsheathe that weapon, $r. It's time to go on patrol! I've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance. You can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you. Report back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it! Dismissed!]],logDesc=[[Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him. Captain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'Valok.]]}
DB[12502]={id=12502,zoneId=66,name=[[Troll Patrol: High Standards]],level=76,minLevel=74,giver=[[Captain Brandon]],giverType=[[NPC]],giverId=28042,ender=[[Captain Brandon]],enderType=[[NPC]],enderId=28042,prevId=-12501,wowhead=[[https://www.wowhead.com/wotlk/quest=12502]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen, $c. This is the Argent Crusade. Our men will fight to the end and never complain no matter what the conditions. That said, we've taken some heavy casualties in this campaign and we've been hitting it hard with little or no sleep for months. That all takes a toll on morale, whether we admit it or not. It may not seem like much, but seeing our standard raised over the battlefield is of considerable comfort to a soldier. Take these banners and raise them at the pedestals in Drak'Sotra.]],logDesc=[[Captain Brandon wants you to place the Argent Crusade Banner in the Drakkari Pedestals at Drak'Sotra.]]}
DB[12503]={id=12503,zoneId=66,name=[[Defend the Stand]],level=76,minLevel=74,giver=[[Commander Falstaav]],giverType=[[NPC]],giverId=28059,ender=[[Commander Falstaav]],enderType=[[NPC]],enderId=28059,nextId=12596,rewardNextId=12596,exGroup=-12503,wowhead=[[https://www.wowhead.com/wotlk/quest=12503]],image=[[assets/images/quests/placeholder.png]],desc=[[Despite our substantial successes in the lower third of Zul'Drak, we must still face the onslaught of the Scourge. Such is the way in this frigid hell. The attacks are unrelenting, yet my men need rest. If you are willing, we could use your aid in reinforcing them. Below in the courtyard you'll find no end to the fighting. Dispatch the Scourge there with all the zeal you can muster, $c.]],logDesc=[[Commander Falstaav has tasked you with the destruction of any 10 Scourge in the courtyard at The Argent Stand.]]}
DB[12504]={id=12504,zoneId=66,name=[[Argent Crusade, We Are Leaving!]],level=76,minLevel=74,giver=[[Sergeant Stackhammer]],giverType=[[NPC]],giverId=28056,ender=[[Sergeant Stackhammer]],enderType=[[NPC]],enderId=28056,prevId=12505,wowhead=[[https://www.wowhead.com/wotlk/quest=12504]],image=[[assets/images/quests/placeholder.png]],desc=[[<The sergeant quickly reads through the orders you've handed him, a frown coming over his face.> Look, $g lad : lass;, I'd love to just up and leave, but take a look out there. All of my people are fighting. Tell you what, you've come this far, you think you're up to doing me a small favor? Head out there and round up my soldiers? Tell 'em that the sergeant orders them to report back immediately. Lend them a hand if you will.]],logDesc=[[Sergeant Stackhammer at the Altar of Sseratus wants you to speak with 10 of his Argent Soldiers and tell them to report back to him.]],choiceRewards={{id=39771,qty=1},{id=39834,qty=1},{id=39780,qty=1},{id=39782,qty=1}}}
DB[12505]={id=12505,zoneId=66,name=[[New Orders for Sergeant Stackhammer]],level=76,minLevel=74,giver=[[Commander Kunz]],giverType=[[NPC]],giverId=28039,ender=[[Sergeant Stackhammer]],enderType=[[NPC]],enderId=28056,prevId=12740,rewardNextId=12504,wowhead=[[https://www.wowhead.com/wotlk/quest=12505]],image=[[assets/images/quests/placeholder.png]],desc=[[$C, you're here to help, right? I've got new orders for our forces that are currently deployed at the Drakkari altar to the north. You can't miss it. Just head straight up the avenue. Sergeant Stackhammer shouldn't be hard to find.]],logDesc=[[Commander Kunz has asked you to deliver the New Deployment Orders to Sergeant Stackhammer at the Altar of Sseratus.]]}
DB[12506]={id=12506,zoneId=66,name=[[Trouble at the Altar of Sseratus]],level=76,minLevel=74,giver=[[Hexxer Ubungo]],giverType=[[NPC]],giverId=28062,ender=[[Hexxer Ubungo]],enderType=[[NPC]],enderId=28062,prevId=12740,wowhead=[[https://www.wowhead.com/wotlk/quest=12506]],image=[[assets/images/quests/placeholder.png]],desc=[[There's trouble at the altar of the snake god. The presence of the Scourge has weakened the land, $r. This in turn has weakened the wild gods. We know that the Drakkari are taking advantage of this to do evil things to the gods. I need you to be my eyes and ears. The Altar of Sseratus is at the end of the avenue to the north. Sneak around the back and get a look inside of the main altar building. Whatever you do, avoid the prophet at all costs!]],logDesc=[[Hexxer Ubungo at The Argent Stand has asked you to investigate the main altar building at the Altar of Sseratus.]]}
DB[12507]={id=12507,zoneId=66,name=[[Strange Mojo]],level=76,minLevel=74,giverType=[[NPC]],ender=[[Hexxer Ubungo]],enderType=[[NPC]],enderId=28062,rewardNextId=12510,wowhead=[[https://www.wowhead.com/wotlk/quest=12507]],image=[[assets/images/quests/placeholder.png]],desc=[[This bottle of strange mojo may be the key to what is truly going on here. The Zandalari troll Hexxer Ubungo, back at The Argent Stand, may want to take a look at it.]],logDesc=[[Deliver the Strange Mojo to Hexxer Ubungo at The Argent Stand.]]}
DB[12508]={id=12508,zoneId=66,name=[[Mopping Up]],level=76,minLevel=74,giver=[[Corporal Maga]],giverType=[[NPC]],giverId=28099,ender=[[Corporal Maga]],enderType=[[NPC]],enderId=28099,prevId=12505,wowhead=[[https://www.wowhead.com/wotlk/quest=12508]],image=[[assets/images/quests/placeholder.png]],desc=[[I couldn't help but overhear what you were talking to the sergeant about. That doesn't change the fact that we still have a job to do here. While you're out there, do you think you could help us to put some of those followers of Sseratus out of their misery?]],logDesc=[[Corporal Maga at the Altar of Sseratus wants you to kill any combination of 10 Champions of Sseratus, Priests of Sseratus, or Drakkari Snake Handlers.]]}
DB[12509]={id=12509,zoneId=66,name=[[Troll Patrol: Intestinal Fortitude]],level=76,minLevel=74,giver=[[Captain Rupert]],giverType=[[NPC]],giverId=28044,ender=[[Captain Rupert]],enderType=[[NPC]],enderId=28044,prevId=-12501,wowhead=[[https://www.wowhead.com/wotlk/quest=12509]],image=[[assets/images/quests/placeholder.png]],desc=[[Finally, the patrol arrives! Here's the situation, $r. We've lost many of our finest soldiers in this campaign and have had to call upon our recruits to fill in the gaps. We've just fought one of our fiercest battles and many of the recruits were simply not prepared to face this enemy. There are more fights ahead, and I need them ready to follow orders. If there's one thing I can't stomach, it's cowardice. Perhaps you can help them find the courage to continue.]],logDesc=[[Captain Rupert in Drak'Sotra wants you to restore courage to the cowering Crusade Recruits.]]}
DB[12510]={id=12510,zoneId=66,name=[[Precious Elemental Fluids]],level=76,minLevel=74,giver=[[Hexxer Ubungo]],giverType=[[NPC]],giverId=28062,ender=[[Hexxer Ubungo]],enderType=[[NPC]],enderId=28062,prevId=12507,rewardNextId=12514,wowhead=[[https://www.wowhead.com/wotlk/quest=12510]],image=[[assets/images/quests/placeholder.png]],desc=[[<The hexxer examines the decanter of mojo.> I have an idea for how to deal with the prophet of Sseratus. But first, we're going to need some things. The Drak'Sotra Fields are directly to the south. Because of the stresses on the land from the Scourge and the deaths of gods, the wall between worlds has weakened and the elementals are flooding in. We need the precious fluids of their lords. If you combine three links from the elementals a tether will be made, and one of their lords can be summoned.]],logDesc=[[Hexxer Ubungo at The Argent Stand wants you to acquire 3 Precious Elemental Fluids.]],choiceRewards={{id=39781,qty=1},{id=39842,qty=1},{id=39803,qty=1},{id=39805,qty=1}}}
DB[12511]={id=12511,zoneId=394,name=[[The Hills Have Us]],level=73,minLevel=73,giver=[[Gryphon Commander Urik]],giverType=[[NPC]],giverId=27317,ender=[[Lieutenant Dumont]],enderType=[[NPC]],enderId=26875,wowhead=[[https://www.wowhead.com/wotlk/quest=12511]],image=[[assets/images/quests/placeholder.png]],desc=[[While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills. All in hopes of finding an alternate route into Icecrown. Lieutenant Dumont, stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?]],logDesc=[[Report to Lieutenant Dumont at Amberpine Lodge in western Grizzly Hills. ]]}
DB[12512]={id=12512,zoneId=66,name=[[Leave No One Behind]],level=76,minLevel=74,giver=[[Dr. Rogers]],giverType=[[NPC]],giverId=28125,ender=[[Dr. Rogers]],enderType=[[NPC]],enderId=28125,wowhead=[[https://www.wowhead.com/wotlk/quest=12512]],image=[[assets/images/quests/placeholder.png]],desc=[[Ahh, good. They sent someone. Listen, $r. We need a hand here. Our forces were pushed back and we've lost Drak'Sotra to the Scourge. Where they came from is anyone's guess.... The point is, we need every man we can get here, and some of our best have yet to return from battle. I need you to enter the ruins now that the fighting has died down and find our wounded, patch them up, and bring them here to me. Scour Drak'Sotra! They couldn't have gone far.]],logDesc=[[Dr. Rogers at Drak'Sotra wants you to find Crusader Lamoof, Crusader Jonathan, and Crusader Josephine. Use the Crusader's Bandage on them, and escort them safely back to him.]],choiceRewards={{id=39807,qty=1},{id=39868,qty=1},{id=39857,qty=1},{id=39860,qty=1}}}
DB[12514]={id=12514,zoneId=66,name=[[Mushroom Mixer]],level=76,minLevel=74,giver=[[Hexxer Ubungo]],giverType=[[NPC]],giverId=28062,ender=[[Hexxer Ubungo]],enderType=[[NPC]],enderId=28062,prevId=12510,wowhead=[[https://www.wowhead.com/wotlk/quest=12514]],image=[[assets/images/quests/placeholder.png]],desc=[[Now what we need is something to spike the mojo with. Something that'll make it so that when the prophet drinks it, he'll become less powerful. Drak'Agal lies to the east. There's a mushroom there that the natives call muddlecap fungus. I think it's exactly what we need. Bring back lots of them. When we mix them into the mojo, the mind of anyone who drinks it will become muddled.]],logDesc=[[Collect 10 Muddlecap Fungus and deliver them to Hexxer Ubungo at The Argent Stand.]]}
DB[12516]={id=12516,zoneId=66,name=[[Too Much of a Good Thing]],level=76,minLevel=74,giver=[[Hexxer Ubungo]],giverType=[[NPC]],giverId=28062,ender=[[Hexxer Ubungo]],enderType=[[NPC]],enderId=28062,prevId=12514,rewardNextId=12623,wowhead=[[https://www.wowhead.com/wotlk/quest=12516]],image=[[assets/images/quests/placeholder.png]],desc=[[There. I've modified the mojo. Now when the prophet drinks it, not only will he lose some of his power, his mind will also be addled by the effects of the fungus. At least that's the theory. As for how to get him to drink it, might I suggest you simply throw it at him? No doubt he'll catch and drink it given the arrogance that he's displayed at the altar. Unless you can kill him, $c, your Argent Crusade is about to come to a terrible end.]],logDesc=[[Slay the Muddled Prophet of Sseratus and then return to Hexxer Ubungo at The Argent Stand.]],choiceRewards={{id=39785,qty=1},{id=39843,qty=1},{id=39815,qty=1},{id=39817,qty=1}}}
DB[12517]={id=12517,name=[[Rogues Deck]],name_loc=[[La baraja de Pícaros]],level=15,minLevel=10,giverType=[[NPC]],ender=[[Darkmoon Fortune Teller]],ender_loc=[[Clarividente de la Luna Negra]],enderType=[[NPC]],enderId=30481,wowhead=[[https://www.wowhead.com/wotlk/quest=12517]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you have gathered all of the Rogue cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card. You feel the card could be used to communicate with someone or something.]],logDesc=[[Use the Rogues Deck to summon a Darkmoon Fortune Teller and give the deck to them.]],choiceRewards={{id=38318,qty=1},{id=39509,qty=1},{id=39507,qty=1}}}
DB[12518]={id=12518,name=[[Mages Deck]],name_loc=[[La baraja de Magos]],level=35,minLevel=30,giverType=[[NPC]],ender=[[Darkmoon Fortune Teller]],ender_loc=[[Clarividente de la Luna Negra]],enderType=[[NPC]],enderId=30481,wowhead=[[https://www.wowhead.com/wotlk/quest=12518]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that you have gathered all of the Mage cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card. You feel the card could be used to communicate with someone or something.]],logDesc=[[Use the Mages Deck to summon a Darkmoon Fortune Teller and give the deck to them.]],choiceRewards={{id=44215,qty=1},{id=44213,qty=1}}}
DB[12519]={id=12519,zoneId=66,name=[[Troll Patrol: Whatdya Want, a Medal?]],level=76,minLevel=74,giver=[[Captain Grondel]],giverType=[[NPC]],giverId=28043,ender=[[Captain Grondel]],enderType=[[NPC]],enderId=28043,prevId=-12501,wowhead=[[https://www.wowhead.com/wotlk/quest=12519]],image=[[assets/images/quests/placeholder.png]],desc=[[Look at me, $r. Do I look like I have time fer fillin' out reports? It be all I can do to keep this post free o' the bloody Scourge, and they want me to mess with paperwork! <sigh> No sense in complainin'. I need to get the commander some kinda kill count from the last skirmish. You wanna be helpful? Go and get me all the medals you can find from the dead trolls around here. That'll hafta be close enough.]],logDesc=[[Captain Grondel outside the Coliseum wants you to gather 7 Drakkari Medallions from the nearby Drakkari Corpses.]]}
DB[12520]={id=12520,zoneId=3711,name=[[Rhino Mastery: The Test]],level=76,minLevel=76,giver=[[Hemet Nesingwary]],giverType=[[NPC]],giverId=27986,ender=[[Hemet Nesingwary]],enderType=[[NPC]],enderId=27986,prevId=12525,rewardNextId=12526,wowhead=[[https://www.wowhead.com/wotlk/quest=12520]],image=[[assets/images/quests/placeholder.png]],desc=[[No rough landing is going to stop ol' Hemet from mastering the largest game Sholazar has to offer. In the wilds northwest of the camp, the jungles are ruled by the mighty shardhorn rhino. You can prove your worth to the expedition, $g lad:lass;, by showing me that you're tough enough to face down those powerful beasts.]],logDesc=[[Kill 15 Shardhorn Rhinos and return to Hemet Nesingwary at the Nesingwary Base Camp.]]}
DB[12521]={id=12521,zoneId=3711,name=[[Where in the World is Hemet Nesingwary?]],level=76,minLevel=76,giver=[[Archmage Pentarus]],giverType=[[NPC]],giverId=28160,ender=[[Monte Muzzleshot]],enderType=[[NPC]],enderId=27987,rewardNextId=12489,wowhead=[[https://www.wowhead.com/wotlk/quest=12521]],image=[[assets/images/quests/placeholder.png]],desc=[[When I heard that the legendary Hemet Nesingwary was setting sail for the Sholazar Basin, I offered to help fund his expedition. We know little of Sholazar,  but it's said to be a lush paradise in the midst of this frozen continent. Hemet has agreed to send back samples of exotic plants, reagents, and crystals. There hasn't been any word from him. Monte Muzzleshot was supposed to be bringing them supplies, but he hasn't returned, either. If you'll look into it, I'll send you in my flying machine.]],logDesc=[[Talk to Archmage Pentarus when you're ready to leave for Sholazar Basin. When you arrive, speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin.]]}
DB[12522]={id=12522,zoneId=3711,name=[[Need an Engine, Take an Engine]],level=76,minLevel=76,giver=[[Weslex Quickwrench]],giverType=[[NPC]],giverId=28033,ender=[[Weslex Quickwrench]],enderType=[[NPC]],enderId=28033,rewardNextId=12523,wowhead=[[https://www.wowhead.com/wotlk/quest=12522]],image=[[assets/images/quests/placeholder.png]],desc=[[She's ruined... ruined! I told that captain to be careful with such a precious cargo, but would she listen to me? No! When the ship ran aground, it damaged my flying machine, the Spirit of Gnomeregan. Now, we're left without any means to send our reports! There is a chance, though, that the Venture Company's antics may work in our favor. They shot down another flying machine right about where Monte parachuted into the swamp to the east. Go there and retrieve the engine. It may be our only hope.]],logDesc=[[Weslex Quickwrench at the Nesingwary Base Camp wants you to bring him a Flying Machine Engine.]]}
DB[12523]={id=12523,zoneId=3711,name=[[Have a Part, Give a Part]],level=76,minLevel=76,giver=[[Weslex Quickwrench]],giverType=[[NPC]],giverId=28033,ender=[[Weslex Quickwrench]],enderType=[[NPC]],enderId=28033,prevId=12522,wowhead=[[https://www.wowhead.com/wotlk/quest=12523]],image=[[assets/images/quests/placeholder.png]],desc=[[Great, now that we've got an engine, we're going to need an assortment of other parts to get her back in flying condition. Don't worry, I know what I'm doing. A good mechanic can hold his creations together with anything, but we're better off if it doesn't come to that. Anyway, those Venture Company dullards have plenty of spare parts for their mining equipment all over Swindlegrin's Dig on the far side of that yellow crystal pillar to the northeast. Scoop up a few and bring them back here.]],logDesc=[[Bring 7 Venture Co. Spare Parts to Weslex Quickwrench at the Nesingwary Base Camp.]]}
DB[12524]={id=12524,zoneId=3711,name=[[Venture Co. Misadventure]],level=76,minLevel=76,giver=[[Debaar]],giverType=[[NPC]],giverId=28032,ender=[[Debaar]],enderType=[[NPC]],enderId=28032,rewardNextId=12525,wowhead=[[https://www.wowhead.com/wotlk/quest=12524]],image=[[assets/images/quests/placeholder.png]],desc=[[Ever since we arrived, the Venture Company has hampered our efforts to secure our campsite and survey the area. Normally, we wouldn't care what they were up to, but they've started antagonizing our scouts and shooting down supply flights. We can't allow this insult to stand. Hemet Nesingwary's expedition came here to hunt, and hunt it shall. Go to Swindlegrin's Dig, on the far side of the crystal pillar to the northeast, and kill any Venture Company employee you see!]],logDesc=[[Debaar at the Nesingwary Base Camp wants you to kill 15 Venture Company members. You may kill either Venture Co. Ruffians or Venture Co. Excavators.]]}
DB[12525]={id=12525,zoneId=3711,name=[[Wipe That Grin Off His Face]],level=76,minLevel=76,giver=[[Debaar]],giverType=[[NPC]],giverId=28032,ender=[[Debaar]],enderType=[[NPC]],enderId=28032,prevId=12524,wowhead=[[https://www.wowhead.com/wotlk/quest=12525]],image=[[assets/images/quests/placeholder.png]],desc=[[We must send Foreman Swindlegrin packing if we're going to shut down his mine permanently, but be careful. His bodyguard, Meatpie, is a large, mean ogre, and  isn't likely to let you see the foreman without a fight. The two probably occupy a platform that would let them look out over the entire Venture Company operation at Swindlegrin's Dig. Remember, the dig is on the far side of the Suntouched Pillar to the northeast. Good luck, $N.]],logDesc=[[Kill Foreman Swindlegrin and Meatpie and return to Debaar at the Nesingwary Base Camp.]],choiceRewards={{id=39332,qty=1},{id=39376,qty=1},{id=39430,qty=1},{id=39452,qty=1}}}
DB[12526]={id=12526,zoneId=3711,name=[[Rhino Mastery: The Chase]],level=76,minLevel=76,giver=[[Hemet Nesingwary]],giverType=[[NPC]],giverId=27986,ender=[[Oracle Soo-rahm]],enderType=[[NPC]],enderId=28191,prevId=12520,rewardNextId=12543,wowhead=[[https://www.wowhead.com/wotlk/quest=12526]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, that's settled then. We'll seek out this native sage and have a word with him. He's not likely to volunteer his services, though. I'm told he keeps a small lean-to near the Bones of Nozronn, just across the river to the south. Seek him out, introduce yourself, and ask what he requires to help us track down this patriarch of the rhinos.]],logDesc=[[Speak to Oracle Soo-rahm at the Bones of Nozronn.]]}
DB[12527]={id=12527,zoneId=66,name=[[Gluttonous Lurkers]],level=76,minLevel=74,giver=[[Apprentice Pestlepot]],giverType=[[NPC]],giverId=28204,ender=[[Alchemist Finklestein]],enderType=[[NPC]],enderId=28205,wowhead=[[https://www.wowhead.com/wotlk/quest=12527]],image=[[assets/images/quests/placeholder.png]],desc=[[My master, Finklestein, is in the shrine at Heb'Valok to the northwest preparing a truth serum, and he needs basilisk crystals. Heb'Valok is on the west side of the road leading north before the Altar of Sseratus. There are basilisks to the east at Drak'Agal. If you grab the Zul'Drak rats and throw them at the basilisk, they will become gorged and docile after eating five. Then you'll be able to take their crystals. Killing the basilisk won't do you any good. That'd just break its crystals!]],logDesc=[[Deliver 5 Basilisk Crystals to Alchemist Finklestein in the shrine at Heb'Valok.]]}
DB[12528]={id=12528,zoneId=3711,name=[[Playing Along]],level=77,minLevel=76,giver=[[Tracker Gekgek]],giverType=[[NPC]],giverId=28095,ender=[[High-Shaman Rakjak]],enderType=[[NPC]],enderId=28082,rewardNextId=12529,wowhead=[[https://www.wowhead.com/wotlk/quest=12528]],image=[[assets/images/quests/placeholder.png]],desc=[[My kill! You take my kill! <Gekgek taunts you with his spear.> You dumb, $r. Now you owe Gekgek! You be Frenzyheart slave. You slay many more beasts for Frenzyheart. You go Frenzyheart Hill to northeast - you tell High-Shaman Rakjak you the new slave. Go, $r! Go or I taunt you a second time! <Gekgek waves his spear around menacingly.>]],logDesc=[[Report to High-Shaman Rakjak at Frenzyheart Hill as the new "slave."]]}
DB[12529]={id=12529,zoneId=3711,name=[[The Ape Hunter's Slave]],level=77,minLevel=76,giver=[[High-Shaman Rakjak]],giverType=[[NPC]],giverId=28082,ender=[[High-Shaman Rakjak]],enderType=[[NPC]],enderId=28082,prevId=12528,nextId=12533,exGroup=-12529,wowhead=[[https://www.wowhead.com/wotlk/quest=12529]],image=[[assets/images/quests/placeholder.png]],desc=[[You think you so great hunter, eh? You no Frenzyheart, you not know of hunt. Goregek is great ape hunter. He slay so many ape you can't count on claws. You go with Goregek and hunt hardknuckles to east. You the slave, $r. You do what Goregek tell you.]],logDesc=[[Kill 8 Hardknuckle Foragers and 6 Hardknuckle Chargers for High-Shaman Rakjak at Frenzyheart Hill. If you lose Goregek's Shackles, speak to Elder Harkek in Frenzyheart Hill.]]}
DB[12530]={id=12530,zoneId=3711,name=[[Tormenting the Softknuckles]],level=77,minLevel=76,giver=[[Goregek the Gorilla Hunter]],giverType=[[NPC]],giverId=28214,ender=[[High-Shaman Rakjak]],enderType=[[NPC]],enderId=28082,prevId=12528,nextId=12534,exGroup=-12529,wowhead=[[https://www.wowhead.com/wotlk/quest=12530]],image=[[assets/images/quests/placeholder.png]],desc=[[Slave thing! Rakjak want me to babysit you while I kill hardknuckles. I feeling generous today, so I let you kill some too, but don't get in Goregek's way! Rakjak not know yet, but Goregek has eye on big bad hardknuckle mama. We go to Hardknuckle Clearing to east and poke softknuckles with poker and she sure to come yelling! <Goregek rubs his hands together gleefully.>]],logDesc=[[Goregek has given you a Softknuckle Poker for use on Softknuckles to draw the Hardknuckle Matriarch out of hiding. Slay the Hardknuckle Matriarch and report her death to High-Shaman Rajak at Frenzyheart Hill. If you lose Goregek's Shackles, speak to Elder Harkek in Frenzyheart Hill.]]}
DB[12531]={id=12531,zoneId=3711,name=[[The Underground Menace]],level=77,minLevel=76,giver=[[Elder Harkek]],giverType=[[NPC]],giverId=28138,ender=[[High-Shaman Rakjak]],enderType=[[NPC]],enderId=28082,prevId=12532,nextId=12536,exGroup=-12535,wowhead=[[https://www.wowhead.com/wotlk/quest=12531]],image=[[assets/images/quests/placeholder.png]],desc=[[Lion killer, chicken chaser, new Frenzyheart slave... I know you no want to stay slave, so I tell you what to do. Show you better than the other Frenzyheart hunters and then Rakjak respect you. Under sands of south river there a beast that kills wasp, apes, and even wolvar. He called Serfex. You bring claw of Serfex to Rakjak and maybe he release you from slaveness. Hope Dajik teaching you good so Serfex be easy stuff.]],logDesc=[[Locate Serfex under the sands of the southern river, slay him, and bring his claw to High-Shaman Rakjak at Frenzyheart Hill. If you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.]]}
DB[12532]={id=12532,zoneId=3711,name=[[Flown the Coop!]],level=77,minLevel=76,giver=[[Elder Harkek]],giverType=[[NPC]],giverId=28138,ender=[[Elder Harkek]],enderType=[[NPC]],enderId=28138,rewardNextId=12531,wowhead=[[https://www.wowhead.com/wotlk/quest=12532]],image=[[assets/images/quests/placeholder.png]],desc=[[Dumb Goregek stumble into chicken house and let all the chickens go! They all around hill - go get chickens back! <Elder Harkek shoos you away.>]],logDesc=[[Capture 12 Chicken Escapees for Elder Harkek. If you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.]],choiceRewards={{id=39337,qty=1},{id=39383,qty=1},{id=39435,qty=1},{id=39455,qty=1}}}
DB[12533]={id=12533,zoneId=3711,name=[[The Wasp Hunter's Apprentice]],level=77,minLevel=76,giver=[[High-Shaman Rakjak]],giverType=[[NPC]],giverId=28082,ender=[[High-Shaman Rakjak]],enderType=[[NPC]],enderId=28082,prevId=12530,nextId=12532,exGroup=-12533,wowhead=[[https://www.wowhead.com/wotlk/quest=12533]],image=[[assets/images/quests/placeholder.png]],desc=[[Rakjak not dumb. Maybe you good at killing things. Maybe Frenzyheart can make you into real hunter. Dajik hunts giant wasp things better than all wolvar. Go with Dajik to Sapphire Hive to southeast or to river in south and learn the hunt.]],logDesc=[[Kill 6 Sapphire Hive Wasps and 9 Sapphire Hive Drones for High-Shaman Rakjak in Frenzyheart Hill. If you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.]]}
DB[12534]={id=12534,zoneId=3711,name=[[The Sapphire Queen]],level=77,minLevel=76,giver=[[Elder Harkek]],giverType=[[NPC]],giverId=28138,ender=[[High-Shaman Rakjak]],enderType=[[NPC]],enderId=28082,prevId=12529,nextId=12532,exGroup=-12533,wowhead=[[https://www.wowhead.com/wotlk/quest=12534]],image=[[assets/images/quests/placeholder.png]],desc=[[Bristlepine can be dangerous, but most stay far away from wolvar. Wasps on other hand not fear the Frenzyheart... they even kill some of our hunters. I know Rakjak want wasp queen dead, but no wolvar want to go into her hive. You go kill wasp queen in Sapphire Hive to southeast and get stinger for Rakjak. Me bet Rakjak like that.]],logDesc=[[Bring the Stinger of the Sapphire Queen to High-Shaman Rakjak at Frenzyheart Hill. If you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.]],choiceRewards={{id=39346,qty=1},{id=39387,qty=1},{id=39436,qty=1},{id=39450,qty=1}}}
DB[12535]={id=12535,zoneId=3711,name=[[Mischief in the Making]],level=77,minLevel=76,giver=[[High-Shaman Rakjak]],giverType=[[NPC]],giverId=28082,ender=[[High-Shaman Rakjak]],enderType=[[NPC]],enderId=28082,prevId=12532,nextId=12536,exGroup=-12535,wowhead=[[https://www.wowhead.com/wotlk/quest=12535]],image=[[assets/images/quests/placeholder.png]],desc=[[You good hunter, but Frenzyheart can make you stronger. Harkek think maybe you ready for something more important. Before Rakjak send you on important mission, you need gather things for Rakjak. All along river to south are blue crystals. Rakjak need lots of blue crystals. You go get crystals now.]],logDesc=[[High-Shaman Rakjak at Frenzyheart Hill wants 8 Skyreach Crystal Clusters.]]}
DB[12536]={id=12536,zoneId=3711,name=[[A Rough Ride]],level=77,minLevel=76,giver=[[High-Shaman Rakjak]],giverType=[[NPC]],giverId=28082,ender=[[Zepik the Gorloc Hunter]],enderType=[[NPC]],enderId=28216,wowhead=[[https://www.wowhead.com/wotlk/quest=12536]],image=[[assets/images/quests/placeholder.png]],desc=[[Zepik is best hunter of the Frenzyheart. Zepik hunts big-tongues... ugly things near swamps that try to steal all stuff they can find. Zepik going on long trek to break big-tongue shrine and try to scare them away. We no want big-tongues in this land anymore. There a crocolisk chained on northeast side of hill, next to tree - go with Zepik and do what Zepik tell you.]],logDesc=[[Ride the captive crocolisk to Mistwhisper Refuge and then speak to Zepik for further instructions. If you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.]]}
DB[12537]={id=12537,zoneId=3711,name=[[Lightning Definitely Strikes Twice]],level=77,minLevel=76,giver=[[Zepik the Gorloc Hunter]],giverType=[[NPC]],giverId=28216,ender=[[Zepik the Gorloc Hunter]],enderType=[[NPC]],enderId=28216,prevId=12536,nextId=12539,exGroup=-12537,wowhead=[[https://www.wowhead.com/wotlk/quest=12537]],image=[[assets/images/quests/placeholder.png]],desc=[[Okay, the crystal things... The big-tongues use the crystals to power their rain shrines. Zepik not know quite how it works, but Zepik does know that if they use wrong crystals, the clouds and the rain go crazy! Zepik tried to sneak in at one of their other rain shrines, but it not go so well. It sure to go much better with two! Take crystals, place at big stone pillar shrine thing, then smash them to release power. Zepik not sure what will happen, so might want to step back after.]],logDesc=[[Zepik wants you to smash the Skyreach Crystal Clusters in front of the Mistwhisper weather shrine. If you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.]],choiceRewards={{id=39347,qty=1},{id=39400,qty=1},{id=39437,qty=1},{id=39457,qty=1}}}
DB[12538]={id=12538,zoneId=3711,name=[[The Mist Isn't Listening]],level=77,minLevel=76,giver=[[Zepik the Gorloc Hunter]],giverType=[[NPC]],giverId=28216,ender=[[Zepik the Gorloc Hunter]],enderType=[[NPC]],enderId=28216,prevId=12536,nextId=12539,exGroup=-12537,wowhead=[[https://www.wowhead.com/wotlk/quest=12538]],image=[[assets/images/quests/placeholder.png]],desc=[[Gorillas and wasps are boring! Big-tongues the only thing fun to hunt. While we mess up rain shrine, we kill lots of mist big-tongues. That sure to make them not want to come back to village thing. <Zepik nods to himself confidently.>]],logDesc=[[Zepik wants you to kill 12 Mistwhisper Gorlocs. If you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.]]}
DB[12539]={id=12539,zoneId=3711,name=[[Hoofing It]],level=77,minLevel=76,giver=[[Zepik the Gorloc Hunter]],giverType=[[NPC]],giverId=28216,ender=[[High-Shaman Rakjak]],enderType=[[NPC]],enderId=28082,rewardNextId=12540,wowhead=[[https://www.wowhead.com/wotlk/quest=12539]],image=[[assets/images/quests/placeholder.png]],desc=[[Okay, we done! Time to go back. No crocolisk to ride this time though. If we go east and stay near ridge, it should lead all the way back near hill. Need to be careful not to go far below ridge though or we might go right into big-tongue tree village thing. Zepik not think they like us right now.]],logDesc=[[Find your way back to Frenzyheart Hill and speak to High-Shaman Rakjak.]]}
DB[12540]={id=12540,zoneId=3711,name=[[Just Following Orders]],level=77,minLevel=76,giver=[[High-Shaman Rakjak]],giverType=[[NPC]],giverId=28082,ender=[[Injured Rainspeaker Oracle]],enderType=[[NPC]],enderId=28217,prevId=12539,wowhead=[[https://www.wowhead.com/wotlk/quest=12540]],image=[[assets/images/quests/placeholder.png]],desc=[[Okay $g guy:lady;, Rakjak have very important job. You go capture injured big-tongue that tracker spotted at river to north. Not bring hunter this time because they maybe want to just kill it. I want to hide it so that I can poke it and make it tell me things. Go you and bring me big-tongue prize thing.]],logDesc=[[Locate an Injured Rainspeaker Oracle for High-Shaman Rakjak at Frenzyheart Hill. ]]}
DB[12541]={id=12541,zoneId=66,name=[[Troll Patrol: The Alchemist's Apprentice]],level=76,minLevel=74,giver=[[Alchemist Finklestein]],giverType=[[NPC]],giverId=28205,ender=[[Alchemist Finklestein]],enderType=[[NPC]],enderId=28205,prevId=12596,wowhead=[[https://www.wowhead.com/wotlk/quest=12541]],image=[[assets/images/quests/placeholder.png]],desc=[[Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands. We have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum. Creating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step. Let me know when you're ready, $r. And remember, timing is everything! ]],logDesc=[[Alchemist Finklestein at Heb'Valok wants you to assist him in the creation of a truth serum. When you are ready to begin, you are to speak to him and follow his instructions.]]}
DB[12542]={id=12542,zoneId=65,name=[[The Call Of The Crusade]],level=74,minLevel=74,giver=[[Tilda Darathan]],giverType=[[NPC]],giverId=27348,ender=[[Crusader Valus]],enderType=[[NPC]],enderId=28228,rewardNextId=12545,wowhead=[[https://www.wowhead.com/wotlk/quest=12542]],image=[[assets/images/quests/placeholder.png]],desc=[[$C! The Argent Crusade is looking for able bodied soldiers that are willing to set aside their differences and join forces to battle the forces of the Lich King. Will you take up our cause? Should you be interested, venture north to Light's Trust and speak with Crusader Valus. You will find Light's Trust amidst the ruins of the sacked troll city of Jintha'kalar - bordering Zul'Drak. Farewell.]],logDesc=[[Report to Crusader Valus at Light's Trust in Dragonblight. ]]}
DB[12543]={id=12543,zoneId=3711,name=[[An Offering for Soo-rahm]],level=76,minLevel=76,giver=[[Oracle Soo-rahm]],giverType=[[NPC]],giverId=28191,ender=[[Oracle Soo-rahm]],enderType=[[NPC]],enderId=28191,prevId=12526,rewardNextId=12544,wowhead=[[https://www.wowhead.com/wotlk/quest=12543]],image=[[assets/images/quests/placeholder.png]],desc=[[We not know you, stranger, but we know you want something. We will talk to Bones of Nozronn for you, but you must bring us offerings. We need powerful emperor cobra fangs to complete our oracle's necklace. Go to the Wildgrowth Mangal, northeast of our hut, find cobras and bring back best fangs. Then we make bones speak to you.]],logDesc=[[Bring 5 Intact Cobra Fangs to Oracle Soo-rahm, near the Bones of Nozronn.]]}
DB[12544]={id=12544,zoneId=3711,name=[[The Bones of Nozronn]],level=76,minLevel=76,giver=[[Oracle Soo-rahm]],giverType=[[NPC]],giverId=28191,ender=[[Hemet Nesingwary]],enderType=[[NPC]],enderId=27986,prevId=12543,wowhead=[[https://www.wowhead.com/wotlk/quest=12544]],image=[[assets/images/quests/placeholder.png]],desc=[[Bones of Nozronn, Oracle Soo-rahm sends $N to you! We have prepared incense for you. Light it and place it near Nozronn's head and you will hear his voice. <Confused, you tell Soo-rahm that you haven't even told him your question.> True, we not know, but mighty Nozronn does. Do not doubt. Nozronn will answer your heart's question. Go. Nozronn not wait long.]],logDesc=[[Use Soo-rahm's Incense near the Bones of Nozronn, then return to Hemet Nesingwary at Nesingwary's Base Camp with the information you learned.]]}
DB[12545]={id=12545,zoneId=65,name=[[The Cleansing Of Jintha'kalar]],level=74,minLevel=74,giver=[[Crusader Valus]],giverType=[[NPC]],giverId=28228,ender=[[Crusader Valus]],enderType=[[NPC]],enderId=28228,prevId=12542,wowhead=[[https://www.wowhead.com/wotlk/quest=12545]],image=[[assets/images/quests/placeholder.png]],desc=[[We wrested this ancient Drakkari temple from a swarm of invading Scourge. Not more than one-hundred paces from where we stand is the ruined city of Jintha'kalar. Scourge necromancers run amok, turning the living Drakkari trolls that remain into servants of the Lich King. All are now lost to the Light. All must be purged. <Valus looks upon you sternly.> All.]],logDesc=[[Crusader Valus at Light's Trust in Dragonblight has asked you to slay 15 Jintha'kalar Scourge.]],choiceRewards={{id=38190,qty=1},{id=38188,qty=1},{id=38198,qty=1},{id=38207,qty=1},{id=38206,qty=1}}}
DB[12546]={id=12546,zoneId=3711,name=[[Reclamation]],level=78,minLevel=77,giver=[[Avatar of Freya]],giverType=[[NPC]],giverId=27801,ender=[[Avatar of Freya]],enderType=[[NPC]],enderId=27801,prevId=12797,wowhead=[[https://www.wowhead.com/wotlk/quest=12546]],image=[[assets/images/quests/placeholder.png]],desc=[[It is time, $N.  The Etymidian is one of the most destructive forces ever created by the titans and I am loathe to unleash him in my lands. There is little choice, however.  Our enemies have forced my hand and the fury of the titans will cleanse all.]],logDesc=[[Go to the Avalanche in Sholazar Basin and use the Omega Rune to deploy Etymidian.  Use him to slay 200 Scourge Minions, Bythius the Flesh-Shaper, Urgreth of the Thousand Tombs and Hailscorn. Speak to the Avatar of Freya in Sholazar Basin when you've completed this task.]],choiceRewards={{id=40290,qty=1},{id=40291,qty=1},{id=40292,qty=1},{id=40293,qty=1},{id=40295,qty=1}}}
DB[12547]={id=12547,zoneId=490,name=[[The Activation Rune]],level=78,minLevel=77,giver=[[The Etymidian]],giverType=[[NPC]],giverId=28092,ender=[[The Etymidian]],enderType=[[NPC]],enderId=28092,prevId=12548,rewardNextId=12797,wowhead=[[https://www.wowhead.com/wotlk/quest=12547]],image=[[assets/images/quests/placeholder.png]],desc=[[This colossal being appears to be inactive.  You notice an empty rune-shaped slot on its chest. Perhaps you might be able to find the missing rune inside the nearby overlook.]],logDesc=[[Obtain the Omega Rune inside the Shaper's Terrace and bring it to The Etymidian.]],choiceRewards={{id=39366,qty=1},{id=39411,qty=1},{id=39442,qty=1},{id=39465,qty=1}}}
DB[12548]={id=12548,zoneId=3711,name=[[The Etymidian]],level=78,minLevel=77,giver=[[Avatar of Freya]],giverType=[[NPC]],giverId=27801,ender=[[The Etymidian]],enderType=[[NPC]],enderId=28092,prevId=12613,rewardNextId=12547,wowhead=[[https://www.wowhead.com/wotlk/quest=12548]],image=[[assets/images/quests/placeholder.png]],desc=[[It is time, $N.  The Waygate has been activated for the first time in seven centuries.  Use it to travel to where our final hope lies. Let us put an end to those who would seek to bring the taint of undeath to this pristine land.  Let us unleash the Etymidian.]],logDesc=[[Go through the Waygate in the southern end of Sholazar Basin and look for the weapon known as the Etymidian on the other side.]]}
DB[12549]={id=12549,zoneId=3711,name=[[Dreadsaber Mastery: Becoming a Predator]],level=76,minLevel=76,giver=[[Buck Cantwell]],giverType=[[NPC]],giverId=28031,ender=[[Buck Cantwell]],enderType=[[NPC]],enderId=28031,prevId=12525,nextId=12551,rewardNextId=12550,wowhead=[[https://www.wowhead.com/wotlk/quest=12549]],image=[[assets/images/quests/placeholder.png]],desc=[[If you've hunted with Hemet before, you know that he's tested his skill against many large cats, but the dreadsabers here in Sholazar are different. They're able to bring down larger game than I've ever seen a cat hunt. To overcome and kill such a predator is the mark of a true hunter. If you seek to prove you're up to the challenge, test yourself against the dreadsabers. They live in the wilderness surrounding the camp and south of the river.]],logDesc=[[Kill 15 Dreadsabers and return to Buck Cantwell at the Nesingwary Base Camp.]]}
DB[12550]={id=12550,zoneId=3711,name=[[Dreadsaber Mastery: Stalking the Prey]],level=76,minLevel=76,giver=[[Buck Cantwell]],giverType=[[NPC]],giverId=28031,ender=[[Buck Cantwell]],enderType=[[NPC]],enderId=28031,prevId=12549,rewardNextId=12558,wowhead=[[https://www.wowhead.com/wotlk/quest=12550]],image=[[assets/images/quests/placeholder.png]],desc=[[I have heard that the natives tell stories of a large dreadsaber they call Shango. I haven't seen any evidence of this Shango's existence, but my injuries have kept me from venturing outside the camp. If you fancy yourself something of a tracker, you might be able to find out the truth about Shango. Debaar said she saw some large tracks on her last outing. Go north from the camp toward Bittertide Lake, and search its southern shore for the prints.]],logDesc=[[Buck Cantwell at the Nesingwary Base Camp wants you to identify 3 Shango Tracks from the Dreadsaber Tracks near Bittertide Lake.]]}
DB[12551]={id=12551,zoneId=3711,name=[[Crocolisk Mastery: The Trial]],level=76,minLevel=76,giver=[[Debaar]],giverType=[[NPC]],giverId=28032,ender=[[Debaar]],enderType=[[NPC]],enderId=28032,prevId=12520,rewardNextId=12560,wowhead=[[https://www.wowhead.com/wotlk/quest=12551]],image=[[assets/images/quests/placeholder.png]],desc=[[I warn you, stranger -- do not make any comments about crashing the ship. I already get enough of it from the rest of the expedition. If you're looking to try your hand at hunting, though, you should test your skills against the wily mangal crocolisks. They live all along the river to the south, and in the Wildgrowth Mangal to the east. Prove you can hold your own against them and we'll talk again, hunter.]],logDesc=[[Kill 15 Mangal Crocolisks and return to Debaar at the Nesingwary Encampment.]]}
DB[12552]={id=12552,zoneId=66,name=[[Death to the Necromagi]],level=76,minLevel=74,giver=[[Sergeant Moonshard]],giverType=[[NPC]],giverId=28283,ender=[[Sergeant Moonshard]],enderType=[[NPC]],enderId=28283,prevId=12598,rewardNextId=12554,wowhead=[[https://www.wowhead.com/wotlk/quest=12552]],image=[[assets/images/quests/placeholder.png]],desc=[[When the trolls brought down Kolramas, it crashed next to us to the southeast. Unfortunately the crash did not destroy all of the Scourge within. Now they're raising our men from the dead and using them against us! This will not be allowed to continue. You will see to it that their necromagi are slaughtered! Do we understand each other?]],logDesc=[[Sergeant Moonshard at Drak'Sotra has asked you to destroy 8 Hath'ar Necromagi.]]}
DB[12553]={id=12553,zoneId=66,name=[[Skimmer Spinnerets]],level=76,minLevel=74,giver=[[Specialist Cogwheel]],giverType=[[NPC]],giverId=28284,ender=[[Specialist Cogwheel]],enderType=[[NPC]],enderId=28284,prevId=12598,nextId=12583,rewardNextId=12555,wowhead=[[https://www.wowhead.com/wotlk/quest=12553]],image=[[assets/images/quests/placeholder.png]],desc=[[Why do I always get the tough tasks to tackle? The Scourge at Kolramas have plague sprayers that are getting dangerously close. You don't want to know what's going to happen if they start heading this way! I've got an idea for how we might bring them down, but first we're going to need something... something from their own creatures. The Hath'ar skimmers can spin a very strong web that we can put to good use. Bring back some of their spinnerets.]],logDesc=[[Specialist Cogwheel at Drak'Sotra has asked you to collect 5 Intact Skimmer Spinnerets.]]}
DB[12554]={id=12554,zoneId=66,name=[[Malas the Corrupter]],level=76,minLevel=74,giver=[[Sergeant Moonshard]],giverType=[[NPC]],giverId=28283,ender=[[Sergeant Moonshard]],enderType=[[NPC]],enderId=28283,prevId=12552,wowhead=[[https://www.wowhead.com/wotlk/quest=12554]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, gather at least one other person and head back down there! You'll find the leader of Kolramas, Malas the Corrupter, gloating from atop the crashed necropolis. Kill him and bring me his head!]],logDesc=[[Sergeant Moonshard at Drak'Sotra insists that you return with the Head of the Corrupter.]],choiceRewards={{id=43160,qty=1},{id=43161,qty=1},{id=43162,qty=1},{id=43163,qty=1}}}
DB[12555]={id=12555,zoneId=66,name=[[A Tangled Skein]],level=76,minLevel=74,giver=[[Specialist Cogwheel]],giverType=[[NPC]],giverId=28284,ender=[[Specialist Cogwheel]],enderType=[[NPC]],enderId=28284,wowhead=[[https://www.wowhead.com/wotlk/quest=12555]],image=[[assets/images/quests/placeholder.png]],desc=[[There! One tangled skein thrower ready and waiting for you to take those plague sprayers down. You just aim and let loose. The webbing should foul up their hover spells long enough to cause them to crash to the ground just like Kolramas. Kind of poetic. I like that!]],logDesc=[[Specialist Cogwheel at Drak'Sotra has asked you to use the Tangled Skein Thrower in order to cause the destruction of 5 Plague Sprayers.]],choiceRewards={{id=39806,qty=1},{id=39822,qty=1},{id=39824,qty=1},{id=39784,qty=1},{id=39823,qty=1},{id=39808,qty=1}}}
DB[12556]={id=12556,zoneId=3711,name=[[Rhino Mastery: The Kill]],level=76,minLevel=76,giver=[[Hemet Nesingwary]],giverType=[[NPC]],giverId=27986,ender=[[Hemet Nesingwary]],enderType=[[NPC]],enderId=27986,prevId=12544,exGroup=-12556,wowhead=[[https://www.wowhead.com/wotlk/quest=12556]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we know where to find Farunn, all that remains is the battle against the great beast. Are you ready to take on this rhino, $N? For all the spirit's blustering, I'm certain it was telling the truth about the beast's strength. When you're ready to face him, head north past the Suntouched Pillar and look for Farunn on the northeast shore of the Bittertide Lake. It may even venture near the Glimmering Pillar. Bring back its horn to commemorate your kill.]],logDesc=[[Bring Farunn's Horn to Hemet Nesingwary at the Nesingwary Base Camp.]],choiceRewards={{id=39333,qty=1},{id=39377,qty=1},{id=39431,qty=1},{id=39453,qty=1}}}
DB[12557]={id=12557,zoneId=66,name=[[Lab Work]],level=76,minLevel=74,giver=[[Alchemist Finklestein]],giverType=[[NPC]],giverId=28205,ender=[[Alchemist Finklestein]],enderType=[[NPC]],enderId=28205,prevId=-12596,wowhead=[[https://www.wowhead.com/wotlk/quest=12557]],image=[[assets/images/quests/placeholder.png]],desc=[[I assume by your interruption that you wish to be numbered among those I am considering for apprenticeship. A worthy aspiration... Should I someday choose to accept your petition, I must be confident that you can find your way around my laboratory. I have many ingredients here; some plentiful, and others in short supply. Take your time, $c. Find a muddy mire maggot, a withered batwing, an amberseed, and some chilled serpent mucus. Succeed, and I'll know to take your request seriously.]],logDesc=[[Alchemist Finklestein at Heb'Valok wants you to find a Muddy Mire Maggot, a Withered Batwing, an Amberseed, and some Chilled Serpent Mucus from within his laboratory.]]}
DB[12558]={id=12558,zoneId=3711,name=[[Dreadsaber Mastery: Ready to Pounce]],level=76,minLevel=76,giver=[[Buck Cantwell]],giverType=[[NPC]],giverId=28031,ender=[[Buck Cantwell]],enderType=[[NPC]],enderId=28031,prevId=12550,exGroup=-12556,wowhead=[[https://www.wowhead.com/wotlk/quest=12558]],image=[[assets/images/quests/placeholder.png]],desc=[[Shango awaits, $N. If you have succeeded in your tracking, he will not know that you stalk him, and you will need the advantage. He is supposed to be bigger, stronger, and more ferocious than the other dreadsabers of the basin. Travel north, to the western shore of Bittertide Lake and near the falls that feed it, do battle with Shango. If you succeed, return with his pelt.]],logDesc=[[Bring Shango's Pelt to Buck Cantwell at the Nesingwary Base Camp.]],choiceRewards={{id=39323,qty=1},{id=39375,qty=1},{id=39429,qty=1},{id=39451,qty=1},{id=39503,qty=1}}}
DB[12559]={id=12559,zoneId=3711,name=[[Powering the Waygate - The Maker's Perch]],level=77,minLevel=77,giver=[[Avatar of Freya]],giverType=[[NPC]],giverId=27801,ender=[[Avatar of Freya]],enderType=[[NPC]],enderId=27801,prevId=12621,rewardNextId=12613,wowhead=[[https://www.wowhead.com/wotlk/quest=12559]],image=[[assets/images/quests/placeholder.png]],desc=[[It is time then.  Let us activate the waygate. You will find the first switch inside the Maker's Perch in the western edge of the basin. Beware, $N.  The titans used the perch to watch over their creations.  Many of their stone servants still guard the place.]],logDesc=[[The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Maker's Perch and use the Activation Switch Gamma.]]}
DB[12560]={id=12560,zoneId=3711,name=[[Crocolisk Mastery: The Plan]],level=76,minLevel=76,giver=[[Debaar]],giverType=[[NPC]],giverId=28032,ender=[[Debaar]],enderType=[[NPC]],enderId=28032,prevId=12551,rewardNextId=12569,wowhead=[[https://www.wowhead.com/wotlk/quest=12560]],image=[[assets/images/quests/placeholder.png]],desc=[[The mangal crocolisk is a master of the ambush, and I intend to beat the best at his game. To do that, we'll need to construct a convincing camouflage for you. We'll use plants that grow in the sandy soil of the riverbanks and lake beaches. The sandfern is best for this purpose. It grows in the sandy areas near the shores of the Seabreach Flow, just to the south, Bittertide Lake and Bittertide Falls, to the north, and the edges of River's Heart, the large lake beyond the mangal to the east.]],logDesc=[[Bring 5 Sandfern fronds to Debaar at the Nesingwary Base Camp.]]}
DB[12561]={id=12561,zoneId=3711,name=[[An Issue of Trust]],level=77,minLevel=77,giver=[[Avatar of Freya]],giverType=[[NPC]],giverId=27801,ender=[[Avatar of Freya]],enderType=[[NPC]],enderId=27801,prevId=12803,rewardNextId=12611,wowhead=[[https://www.wowhead.com/wotlk/quest=12561]],image=[[assets/images/quests/placeholder.png]],desc=[[This should never have happened.  The forces of undeath storm the very cradle of life! If you're not here to destroy the minions of the Lich King, then leave at once.  Do not incur my wrath by distracting me from my duties.]],logDesc=[[Obtain Freya's trust by destroying 6 Blighted Corpses and 10 Bonescythe Ravagers in the Lost Lands.]],choiceRewards={{id=39363,qty=1},{id=39406,qty=1},{id=39439,qty=1},{id=39459,qty=1}}}
DB[12562]={id=12562,zoneId=66,name=[[The Drakkari Do Not Need Water Elementals!]],level=76,minLevel=74,giver=[[Sub-Lieutenant Jax]],giverType=[[NPC]],giverId=28309,ender=[[Sub-Lieutenant Jax]],enderType=[[NPC]],enderId=28309,wowhead=[[https://www.wowhead.com/wotlk/quest=12562]],image=[[assets/images/quests/placeholder.png]],desc=[[Intelligence reports that ever since those water elementals appeared in the Drak'Sotra Fields, a number of Drakkari shaman have come down from the upper tiers of Zul'Drak to take control of them. I cannot stress enough, $g sir : ma'am;, how dangerous that could prove. We do not want them to have water elementals at their disposal. The commander has ordered that these Drakkari water binders are to be put to the sword. Head south when you're ready.]],logDesc=[[Sub-Lieutenant Jax at The Argent Stand has asked you to kill 10 Drakkari Water Binders.]]}
DB[12563]={id=12563,zoneId=66,name=[[Troll Patrol]],level=76,minLevel=74,giver=[[Commander Kunz]],giverType=[[NPC]],giverId=28039,ender=[[Commander Kunz]],enderType=[[NPC]],enderId=28039,prevId=12596,wowhead=[[https://www.wowhead.com/wotlk/quest=12563]],image=[[assets/images/quests/placeholder.png]],desc=[[Unsheathe that weapon, $r. It's time to go on patrol! I've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance. You can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you. Report back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it! Dismissed!]],logDesc=[[Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him. Captain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'Valok.]]}
DB[12564]={id=12564,zoneId=66,name=[[Troll Patrol: Something for the Pain]],level=76,minLevel=74,giver=[[Captain Brandon]],giverType=[[NPC]],giverId=28042,ender=[[Captain Brandon]],enderType=[[NPC]],enderId=28042,prevId=-12563,wowhead=[[https://www.wowhead.com/wotlk/quest=12564]],image=[[assets/images/quests/placeholder.png]],desc=[[Gritty as my men are, they're still mortal. Wounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life. Thankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience. The salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.]],logDesc=[[Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields.]]}
DB[12565]={id=12565,zoneId=66,name=[[The Blessing of Zim'Abwa]],level=76,minLevel=74,giver=[[Hexxer Ubungo]],giverType=[[NPC]],giverId=28062,enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12565]],image=[[assets/images/quests/placeholder.png]],desc=[[I am heartened to see the zeal with which your Argent Crusade is dealing with the Scourge, $r. I would like to help with your efforts. The Drakkari trolls of this once-great city used to make regular offerings to their gods, but now neglect them, or worse. If you were to make offerings to the gods, they would show their appreciation in return. Zim'Abwa's statue is just to the southwest. Zim'Abwa would gladly accept your offerings of Drakkari artifacts as a sign that you are protecting Zul'Drak.]],logDesc=[[Hexxer Ubungo at The Argent Stand wants you to present 10 Drakkari Offerings to the statue of Zim'Abwa.]]}
DB[12566]={id=12566,zoneId=495,name=[[Help for Camp Winterhoof]],level=71,minLevel=68,giver=[[Longrunner Nanik]],giverType=[[NPC]],giverId=28314,ender=[[Chieftain Ashtotem]],enderType=[[NPC]],enderId=24129,exGroup=11411,wowhead=[[https://www.wowhead.com/wotlk/quest=12566]],image=[[assets/images/quests/placeholder.png]],desc=[[I am Longrunner Nanik of the Taunka, sent by the chieftain of Camp Winterhoof to seek out allies in the fight against the vrykul. They mass to the west and south of our village, and though we slay 10 of them for every one of our dead, we cannot hold. Apothecary Scyllis has promised to send brave $cs northwest to our aid. Will you help my people fend off the vrykul assaults? Follow the road far to the northwest, across the river, and into the foothills of the mountains to reach Camp Winterhoof.]],logDesc=[[Speak with Chieftain Ashtotem at Camp Winterhoof.]]}
DB[12567]={id=12567,zoneId=66,name=[[Blessing of Zim'Abwa]],level=76,minLevel=74,giverType=[[NPC]],enderType=[[NPC]],prevId=12565,wowhead=[[https://www.wowhead.com/wotlk/quest=12567]],image=[[assets/images/quests/placeholder.png]]}
DB[12568]={id=12568,zoneId=66,name=[[Troll Patrol: Done to Death]],level=76,minLevel=74,giver=[[Captain Rupert]],giverType=[[NPC]],giverId=28044,ender=[[Captain Rupert]],enderType=[[NPC]],enderId=28044,prevId=-12563,wowhead=[[https://www.wowhead.com/wotlk/quest=12568]],image=[[assets/images/quests/placeholder.png]],desc=[[Trust me, $r. I know.... The smell of burnt flesh has become sickening to even me, a Forsaken. Nevertheless, it is our solemn duty to ensure that our brethren never walk with the Scourge. Pour this oil on the corpses of our fallen to ensure that we never face them on the battlefield as enemies.]],logDesc=[[Captain Rupert wants you to use the Incinerating Oil on 5 Defeated Argent Footmen in Drak'Sotra.]]}
DB[12569]={id=12569,zoneId=3711,name=[[Crocolisk Mastery: The Ambush]],level=76,minLevel=76,giver=[[Debaar]],giverType=[[NPC]],giverId=28032,ender=[[Debaar]],enderType=[[NPC]],enderId=28032,prevId=12560,exGroup=-12556,wowhead=[[https://www.wowhead.com/wotlk/quest=12569]],image=[[assets/images/quests/placeholder.png]],desc=[[The largest crocolisk in the basin, known around here as "Bushwhacker" for his ambush prowess, likes to sun himself in the shallow waters of River's Heart. It's the large lake at the basin's center, and is to the east of our camp. I want you to take the camouflage I've prepared and hide on the western beach of River's Heart and ambush Bushwhacker when he shows himself. Bring back his mighty jaws if you are able to overcome him.]],logDesc=[[Bring Bushwhacker's Jaw to Debaar at the Nesingwary Base Camp.]],choiceRewards={{id=39331,qty=1},{id=39374,qty=1},{id=39461,qty=1},{id=39480,qty=1}}}
DB[12570]={id=12570,zoneId=3711,name=[[Fortunate Misunderstandings]],level=77,minLevel=76,giver=[[Injured Rainspeaker Oracle]],giverType=[[NPC]],giverId=28217,ender=[[High-Oracle Soo-say]],enderType=[[NPC]],enderId=28027,prevId=12540,rewardNextId=12571,wowhead=[[https://www.wowhead.com/wotlk/quest=12570]],image=[[assets/images/quests/placeholder.png]],desc=[[I sorry! I not mean to get you in trouble! <The injured oracle stares at you blankly for a long while.> You save me! We thank you. We going to go back to village now. You come too... you can stay with us! Puppy-men kind of mean anyway. Let me know when you ready to go, okay?]],logDesc=[[Escort the Injured Rainspeaker Oracle to Rainspaker Canopy and speak to High-Oracle Soo-say.]],choiceRewards={{id=39335,qty=1},{id=39378,qty=1},{id=39432,qty=1},{id=39482,qty=1}}}
DB[12571]={id=12571,zoneId=3711,name=[[Make the Bad Snake Go Away]],level=77,minLevel=76,giver=[[High-Oracle Soo-say]],giverType=[[NPC]],giverId=28027,ender=[[High-Oracle Soo-say]],enderType=[[NPC]],enderId=28027,prevId=12570,nextId=12573,rewardNextId=12573,exGroup=-12571,wowhead=[[https://www.wowhead.com/wotlk/quest=12571]],image=[[assets/images/quests/placeholder.png]],desc=[[We were here long before the puppy-men came. This is very sacred place - we will not leave. You seem like maybe you good, but we have Lafoo stay with you just in case. You understand we think. There snakes thing that keeps trying to eat our hatchlings. Go with Lafoo and make them stop, okay? Especially big one near waterfall to northeast.]],logDesc=[[High-Oracle Soo-say in Rainspeaker Canopy wants you to kill Venomtip and 10 Emperor Cobras. If you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.]]}
DB[12572]={id=12572,zoneId=3711,name=[[Gods like Shiny Things]],level=77,minLevel=76,giver=[[Lafoo]],giverType=[[NPC]],giverId=28120,ender=[[High-Oracle Soo-say]],enderType=[[NPC]],enderId=28027,prevId=12570,nextId=12573,exGroup=-12571,wowhead=[[https://www.wowhead.com/wotlk/quest=12572]],image=[[assets/images/quests/placeholder.png]],desc=[[Soo-say said we go with you. You be nice, okay? Ooh, ooh! We know! We can make Soo-say happy if we bring back more offerings for shrine! We not need to go far, there's always stuffs to dig up around village... just look for sparkles in dirt! Let's go! Let's go! More offerings for shrine!]],logDesc=[[Collect 6 of the treasures that Lafoo digs up and bring them to High-Oracle Soo-say in Rainspeaker Canopy. If you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.]]}
DB[12573]={id=12573,zoneId=3711,name=[[Making Peace]],level=77,minLevel=76,giver=[[High-Oracle Soo-say]],giverType=[[NPC]],giverId=28027,ender=[[High-Oracle Soo-say]],enderType=[[NPC]],enderId=28027,wowhead=[[https://www.wowhead.com/wotlk/quest=12573]],image=[[assets/images/quests/placeholder.png]],desc=[[We have great idea. You were friends with puppy-men, they maybe listen to you. We want you to go give offering to Shaman Vekjik. He southwest where river turns into waterfall.  Tell puppy-man we no want fight. Tell him we play nice. You good $r. We trust you do this right.]],logDesc=[[High-Oracle Soo-say at Rainspeaker Canopy wants you to give a peace offering to Shaman Vekjik and then return with his response. If you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.]],choiceRewards={{id=39672,qty=1},{id=39674,qty=1},{id=39673,qty=1},{id=39675,qty=1}}}
DB[12574]={id=12574,zoneId=3711,name=[[Back So Soon?]],level=77,minLevel=76,giver=[[High-Oracle Soo-say]],giverType=[[NPC]],giverId=28027,ender=[[Mistcaller Soo-gan]],enderType=[[NPC]],enderId=28114,prevId=12573,wowhead=[[https://www.wowhead.com/wotlk/quest=12574]],image=[[assets/images/quests/placeholder.png]],desc=[[<High-Oracle Soo-say stares at your forehead for a while before speaking.> Soo-gan ask for help. We think they might have been attacked by puppy-men again. We sending you and Jaloot to help... follow west river up to Mistwhisper Refuge. Do what Soo-gan says... hit the puppy-men on the nose if they being mean, they don't like that. <High-Oracle Soo-say goes back to staring at your forehead as you leave.>]],logDesc=[[Travel to Mistwhisper Refuge and speak to Mistcaller Soo-gan. If you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.]]}
DB[12575]={id=12575,zoneId=3711,name=[[The Lost Mistwhisper Treasure]],level=77,minLevel=76,giver=[[Mistcaller Soo-gan]],giverType=[[NPC]],giverId=28114,ender=[[Mistcaller Soo-gan]],enderType=[[NPC]],enderId=28114,prevId=12574,nextId=12577,exGroup=-12576,wowhead=[[https://www.wowhead.com/wotlk/quest=12575]],image=[[assets/images/quests/placeholder.png]],desc=[[So some puppy-men come and smash blue crystals at Great Mist Stone! Lots of rain and lightning and badness... blue is wrong crystal for Great Mist Stone! Dumb puppy-men. After lightning, puppy-men stole big treasure we found in the sea-lake. We need treasure back to give to Great Mist Stone! Mist Stone is angry after what the puppy-men did! One who took it named Tarter... no, Tiktak... no, no... Tartek. That it, Tartek! He went to the camp thing to north. Go get treasure back!]],logDesc=[[Kill Warlord Tartek and retrieve the Mistwhisper Treasure for Mistcaller Soo-gan at Mistwhisper Refuge. If you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.]],choiceRewards={{id=39336,qty=1},{id=39380,qty=1},{id=39433,qty=1},{id=39454,qty=1}}}
DB[12576]={id=12576,zoneId=3711,name=[[Forced Hand]],level=77,minLevel=76,giver=[[Mistcaller Soo-gan]],giverType=[[NPC]],giverId=28114,ender=[[Mistcaller Soo-gan]],enderType=[[NPC]],enderId=28114,prevId=12574,nextId=12577,exGroup=-12576,wowhead=[[https://www.wowhead.com/wotlk/quest=12576]],image=[[assets/images/quests/placeholder.png]],desc=[[We try to be nice to puppy-men ever since they came, but they nothing but mean. We okay with them being dumb - they not do much harm. Now they mess with sacred shrines though. Sacred shrines not for messing with. The Great Stones are here from all the way back when the Great Ones made us. We wouldn't know what to do if the Great Mist Stone were hurt. Go to their camp to north... make puppy-men stop and not come back!]],logDesc=[[Kill 8 Frenzyheart Spearbearers and 6 Frenzyheart Scavengers for Mistcaller Soo-gan at Mistwhisper Refuge. If you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.]]}
DB[12577]={id=12577,zoneId=3711,name=[[Home Time!]],level=77,minLevel=76,giver=[[Mistcaller Soo-gan]],giverType=[[NPC]],giverId=28114,ender=[[High-Oracle Soo-say]],enderType=[[NPC]],enderId=28027,rewardNextId=12578,wowhead=[[https://www.wowhead.com/wotlk/quest=12577]],image=[[assets/images/quests/placeholder.png]],desc=[[You're a good dryskin. Mistwhisper safe, treasure safe, and puppy-men sure to leave us alone now. You go back to Rainspeaker Canopy and tell Soo-say you done good.]],logDesc=[[Return to Rainspeaker Canopy.]]}
DB[12578]={id=12578,zoneId=3711,name=[[The Angry Gorloc]],level=77,minLevel=76,giver=[[High-Oracle Soo-say]],giverType=[[NPC]],giverId=28027,ender=[[Moodle]],enderType=[[NPC]],enderId=28122,prevId=12577,wowhead=[[https://www.wowhead.com/wotlk/quest=12578]],image=[[assets/images/quests/placeholder.png]],desc=[[I not think you be back in time to go out again, but I wrong. I sending Moodle to nearby Mosswalker friends to bop silly Mosswalkers for not coming see shrine. Their village is east, up ridge, northeast of broken pillar. You go with Moodle! He extra smart Rainspeaker... you listen to him good-like.]],logDesc=[[Travel to Mosswalker Village and speak to Moodle once you've arrived. If you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.]]}
DB[12579]={id=12579,zoneId=3711,name=[[Lifeblood of the Mosswalker Shrine]],level=77,minLevel=76,giver=[[Moodle]],giverType=[[NPC]],giverId=28122,ender=[[Moodle]],enderType=[[NPC]],enderId=28122,prevId=12578,exGroup=-12580,wowhead=[[https://www.wowhead.com/wotlk/quest=12579]],image=[[assets/images/quests/placeholder.png]],desc=[[I've always suspected that the pillars have been the main reason for our weather and seclusion from the undead... this confirms it a bit. Not terribly long ago, there was a sound of a great explosion when the Lifeblood Pillar fell. The weather changed for the mosswalkers almost immediately... it began to snow, something we never see. They were able to stop the snow by bringing more lifeblood crystals to the Great Moss Stone. Perhaps if we can do the same, it will help ward off the undead as well.]],logDesc=[[Moodle wants you to collect 10 Lifeblood Shards, but stay away from the cave inside of the pillar itself. If you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.]]}
DB[12580]={id=12580,zoneId=3711,name=[[The Mosswalker Savior]],level=77,minLevel=76,giver=[[Moodle]],giverType=[[NPC]],giverId=28122,ender=[[Moodle]],enderType=[[NPC]],enderId=28122,prevId=12578,exGroup=-12580,wowhead=[[https://www.wowhead.com/wotlk/quest=12580]],image=[[assets/images/quests/placeholder.png]],desc=[[There's some small chance that the Mosswalkers are not all dead yet... and at the very least, they deserve to not be butchered like this. Let's find some revenge for this slaughter and see if there are any to be saved in the process.]],logDesc=[[Moodle wants you to rescue 6 of the Mosswalker Victims in Mosswalker Village, though some of them may no longer be alive to save. If you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.]]}
DB[12581]={id=12581,zoneId=3711,name=[[A Hero's Burden]],level=77,minLevel=76,giver=[[Moodle]],giverType=[[NPC]],giverId=28122,enderType=[[NPC]],prevId=12580,wowhead=[[https://www.wowhead.com/wotlk/quest=12581]],image=[[assets/images/quests/placeholder.png]],desc=[[Perhaps the crystals will ward off the undead gradually, but there is one more thing that must be done. We need to find the leader of these undead and kill him to ensure there's no one to push the wretches back upon us. If my suspicions are correct, he will be somewhere inside the fallen pillar... the Sundered Shard. The corpses being dragged there would suggest as much anyway. I'll place the shards and bring the news to Soo-say... you will need to find other help in the meantime.]],logDesc=[[Kill Artruis the Heartless. While securing the aid of friends is highly recommended, Moodle will not be able to accompany you on this task.]],choiceRewards={{id=39483,qty=1},{id=39485,qty=1},{id=39475,qty=1},{id=39484,qty=1}}}
DB[12582]={id=12582,zoneId=3711,name=[[Frenzyheart Champion]],level=77,minLevel=76,giver=[[Zepik the Gorloc Hunter]],giverType=[[NPC]],giverId=28668,ender=[[Zepik the Gorloc Hunter]],enderType=[[NPC]],enderId=28668,prevId=12581,exGroup=12582,wowhead=[[https://www.wowhead.com/wotlk/quest=12582]],image=[[assets/images/quests/placeholder.png]]}
DB[12583]={id=12583,zoneId=66,name=[[Crashed Sprayer]],level=76,minLevel=74,giver=[[Specialist Cogwheel]],giverType=[[NPC]],giverId=28284,ender=[[Specialist Cogwheel]],enderType=[[NPC]],enderId=28284,nextId=12555,rewardNextId=12555,wowhead=[[https://www.wowhead.com/wotlk/quest=12583]],image=[[assets/images/quests/placeholder.png]],desc=[[I know that one of those plague sprayers crashed somewhere within Drak'Sotra to the west of us. Why don't you see if you can find it. I can use the parts from the sprayer to create the device that's going to bring those things down!]],logDesc=[[Specialist Cogwheel at Drak'Sotra has asked you to collect Plague Sprayer Parts.]]}
DB[12584]={id=12584,zoneId=66,name=[[Pure Evil]],level=76,minLevel=74,giver=[[Captain Rupert]],giverType=[[NPC]],giverId=28044,ender=[[Eitrigg]],enderType=[[NPC]],enderId=28244,prevId=12552,wowhead=[[https://www.wowhead.com/wotlk/quest=12584]],image=[[assets/images/quests/placeholder.png]],desc=[[We know that Kolramas, the crashed necropolis to the southeast, was carrying a large amount of an ore known as saronite when the trolls shot it down. My scouts tell me that much of the saronite is strewn about within the innards of that thing. Eitrigg and his friends back at The Argent Stand want a bunch of the stuff so that they can study it. I want you to head in there and see if you can collect enough for them.]],logDesc=[[Captain Rupert has asked you to collect 10 Chunks of Saronite and deliver them to Eitrigg at The Argent Stand.]],choiceRewards={{id=39773,qty=1},{id=39837,qty=1},{id=39795,qty=1},{id=39792,qty=1}}}
DB[12585]={id=12585,zoneId=66,name=[[Troll Patrol: Creature Comforts]],level=76,minLevel=74,giver=[[Captain Grondel]],giverType=[[NPC]],giverId=28043,ender=[[Captain Grondel]],enderType=[[NPC]],enderId=28043,prevId=-12563,wowhead=[[https://www.wowhead.com/wotlk/quest=12585]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, it ain't glamorous, but it needs doin'. My troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya. What they need is a nice fire to dry 'em out and lighten their spirits. This part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture. Round us up some fuel for burnin' and we'll be mighty grateful.]],logDesc=[[Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood.]]}
DB[12586]={id=12586,zoneId=3711,name=[[In Search of Bigger Game]],level=77,minLevel=75,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12586]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, $N, you've been an enormous asset to the expedition so far. Debaar, Buck, and I couldn't have have assembled such an amazing collection of trophies without you. But, I hear there are even fiercer monsters in other parts of the basin. I've sent a search party up north to get an idea of what other beasts await us. I'd like you to meet up with them and see what they've found. Head north, beyond Bittertide Lake and search for the encampment.]],logDesc=[[Talk to <x> at <x>.]]}
DB[12587]={id=12587,zoneId=66,name=[[Troll Patrol]],level=76,minLevel=74,giver=[[Commander Kunz]],giverType=[[NPC]],giverId=28039,ender=[[Commander Kunz]],enderType=[[NPC]],enderId=28039,prevId=12596,wowhead=[[https://www.wowhead.com/wotlk/quest=12587]],image=[[assets/images/quests/placeholder.png]],desc=[[Unsheathe that weapon, $r. It's time to go on patrol! I've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance. You can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you. Report back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it! Dismissed!]],logDesc=[[Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him. Captain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'valok.]]}
DB[12588]={id=12588,zoneId=66,name=[[Troll Patrol: Can You Dig It?]],level=76,minLevel=74,giver=[[Captain Brandon]],giverType=[[NPC]],giverId=28042,ender=[[Captain Brandon]],enderType=[[NPC]],enderId=28042,prevId=-12587,wowhead=[[https://www.wowhead.com/wotlk/quest=12588]],image=[[assets/images/quests/placeholder.png]],desc=[[One of our troops came across an old treasure map during our last offensive. If what it shows is true, then there are priceless troll artifacts nearby. My soldiers have their hands full, pressed between the Drakkari and the Scourge. I need you to follow up on this intelligence. Take this shovel and use it at the loose dirt mounds to the southwest. Return to me after a diligent search has been conducted.]],logDesc=[[Captain Brandon in Drak'Sotra wants you to use the Steel Spade on the nearby Ancient Dirt Mounds to recover the Ancient Drakkari Relic.]]}
DB[12589]={id=12589,zoneId=3711,name=[[Kick, What Kick?]],level=76,minLevel=76,giver=[[Drostan]],giverType=[[NPC]],giverId=28328,ender=[[Drostan]],enderType=[[NPC]],enderId=28328,prevId=12525,rewardNextId=12592,wowhead=[[https://www.wowhead.com/wotlk/quest=12589]],image=[[assets/images/quests/placeholder.png]],desc=[[So you think you can shoot? Well, let's give it a try. Here, we'll start you out with something nice and gentle. Don't worry, it's got no kick to it at all. Remember, don't point that gun at anything you don't intend to fire at. Now, when you're ready, just take aim at that apple on top o' old Lucky Wilhelm's head and let 'er fly!]],logDesc=[[Using the RJR Rifle, shoot the apple on top of Lucky Wilhelm's head, then speak with Drostan.]]}
DB[12590]={id=12590,zoneId=66,name=[[Blahblah[PH] ]],level=76,minLevel=74,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12590]],image=[[assets/images/quests/placeholder.png]]}
DB[12591]={id=12591,zoneId=66,name=[[Troll Patrol: Throwing Down]],level=76,minLevel=74,giver=[[Captain Rupert]],giverType=[[NPC]],giverId=28044,ender=[[Captain Rupert]],enderType=[[NPC]],enderId=28044,prevId=-12587,wowhead=[[https://www.wowhead.com/wotlk/quest=12591]],image=[[assets/images/quests/placeholder.png]],desc=[[Clever... Just when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine! Now we're caught between two nethurbian armies and our predicament is worsening by the minute. As our first course of action, we must stop them from reinforcing. Their tunnels must be sealed. Take these grenades and throw them down their craters to the northwest.]],logDesc=[[Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nethurbian Craters.]]}
DB[12592]={id=12592,zoneId=3711,name=[[The Great Hunter's Challenge]],level=76,minLevel=76,giver=[[Drostan]],giverType=[[NPC]],giverId=28328,ender=[[Drostan]],enderType=[[NPC]],enderId=28328,prevId=12589,wowhead=[[https://www.wowhead.com/wotlk/quest=12592]],image=[[assets/images/quests/placeholder.png]],desc=[[So y'have something of a hunter's instinct. You're not a bad shot, and Hemet hasn't driven you out, so he must be planning on including you in the hunt. How'd you like to have a bit of a competition, just me and you? Hemet and the others will ask you to help in their hunting. Along the way, you and I will count up the kills we contribute to their goals. Now, this isn't something you can win in the blink of an eye, and you'll find yourself killing many different kinds of creatures. Good luck!]],logDesc=[[Kill 60 Game Animals while you aid Hemet and his companions in their hunting. When you've killed your 60, return to Drostan at the Nesingwary Base Camp to compare numbers.]],choiceRewards={{id=39330,qty=1},{id=39373,qty=1},{id=39428,qty=1},{id=39448,qty=1}}}
DB[12593]={id=12593,name=[[In Service Of The Lich King]],name_loc=[[Al servicio del Rey Exánime]],level=55,minLevel=55,giver=[[The Lich King]],giver_loc=[[El Rey Exánime]],giverType=[[NPC]],giverId=25462,ender=[[Instructor Razuvious]],enderType=[[NPC]],enderId=28357,rewardNextId=12619,poiX=2456,poiY=-5556,wowhead=[[https://www.wowhead.com/wotlk/quest=12593]],image=[[assets/images/quests/placeholder.png]],desc=[[All that I am: anger, cruelty, vengeance - I bestow upon you, my chosen knight. I have granted you immortality so that you may herald in a new, dark age for the Scourge. Gaze now upon the lands below us. The Scarlet Crusade scurries to undo my work, while Light's Hope stands defiantly against us - a blemish upon these Plaguelands. They must all be shown the price of their defiance. You will become my force of retribution. Where you tread, doom will follow. Go now and claim your destiny, death knight.]],logDesc=[[Report to Instructor Razuvious in the Heart of Acherus. ]]}
DB[12594]={id=12594,zoneId=66,name=[[Troll Patrol: Couldn't Care Less]],level=76,minLevel=74,giver=[[Captain Grondel]],giverType=[[NPC]],giverId=28043,ender=[[Captain Grondel]],enderType=[[NPC]],enderId=28043,prevId=-12587,wowhead=[[https://www.wowhead.com/wotlk/quest=12594]],image=[[assets/images/quests/placeholder.png]],desc=[[Of all the posts, they throw me in this one. The place is flooded with putrid, stagnant water and now it's host to sewage elementals! I don't really know what they are or why they're here, and frankly I couldn't care less. What I do know is they're making a mess of my sector! How am I supposed to conduct any dignified military operations with those foul things roaming around? Get out there, $c, and don't come back 'til you've cleared your share of 'em off of my battlefield!]],logDesc=[[Captain Grondel wants you to kill 7 Mossy Rampagers in Drak'Agal.]]}
DB[12595]={id=12595,zoneId=3711,name=[[In Search of Bigger Game]],level=77,minLevel=76,giver=[[Hemet Nesingwary]],giverType=[[NPC]],giverId=27986,ender=[[Dorian Drakestalker]],enderType=[[NPC]],enderId=28376,prevId=12556,wowhead=[[https://www.wowhead.com/wotlk/quest=12595]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, $N, you've certainly proven your mettle as a hunter of all kinds of game animals -- rhinos, cats, and crocolisks. For some members of the expedition, these creatures are sufficient to test their hunting skills, but others, like myself, crave larger challenges. Dorian Drakestalker went north, across Bittertide Lake and established a camp there. He's heard rumors of gigantic primordial drakes. Just imagine what a quarry they would be! Go check up on Dorian and see if he's had any luck.]],logDesc=[[Speak with Dorian Drakestalker at Dorian's Outpost in Sholazar Basin.]]}
DB[12596]={id=12596,zoneId=66,name=[[Pa'Troll]],level=76,minLevel=74,giver=[[Commander Kunz]],giverType=[[NPC]],giverId=28039,ender=[[Commander Kunz]],enderType=[[NPC]],enderId=28039,wowhead=[[https://www.wowhead.com/wotlk/quest=12596]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome to The Argent Stand, scrub. I am Commander Kunz, but you - you can call me... Commander. Don't think you're going to just cruise through my region, picking which missions you're going to participate in, answering to no one. Here, you report to me and you follow my orders to the letter. Understood?! First, you're going to get familiar with my men and the region we're charged with clearing. Report to each of them and do as they ask. Return to me when your patrol is done.]],logDesc=[[Commander Kunz at The Argent Stand wants you to visit the four Argent Crusade posts, follow their leaders' orders, and then return and report to him. Captain Brandon and Captain Rupert are posted at Drak'Sotra, Southeast of here. Captain Grondel is posted in Drak'Agal, due east. Alchemist Finklestein is posted in Heb'Valok, to the north.]],choiceRewards={{id=39800,qty=1},{id=39864,qty=1},{id=39850,qty=1},{id=39851,qty=1},{id=39827,qty=1}}}
DB[12597]={id=12597,zoneId=66,name=[[Something for the Pain]],level=76,minLevel=74,giver=[[Captain Brandon]],giverType=[[NPC]],giverId=28042,ender=[[Captain Brandon]],enderType=[[NPC]],enderId=28042,prevId=-12596,wowhead=[[https://www.wowhead.com/wotlk/quest=12597]],image=[[assets/images/quests/placeholder.png]],desc=[[Gritty as my men are, they're still mortal. Wounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life. Thankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience. The salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.]],logDesc=[[Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields.]]}
DB[12598]={id=12598,zoneId=66,name=[[Throwing Down]],level=76,minLevel=74,giver=[[Captain Rupert]],giverType=[[NPC]],giverId=28044,ender=[[Captain Rupert]],enderType=[[NPC]],enderId=28044,prevId=-12596,rewardNextId=12555,wowhead=[[https://www.wowhead.com/wotlk/quest=12598]],image=[[assets/images/quests/placeholder.png]],desc=[[Clever... Just when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine! Now we're caught between two Nerubian armies and our predicament is worsening by the minute. As our first course of action, we must stop them from reinforcing. Their tunnels must be sealed. Take these grenades and throw them down their craters to the northwest.]],logDesc=[[Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nerubian Craters.]]}
DB[12599]={id=12599,zoneId=66,name=[[Creature Comforts]],level=76,minLevel=74,giver=[[Captain Grondel]],giverType=[[NPC]],giverId=28043,ender=[[Captain Grondel]],enderType=[[NPC]],enderId=28043,prevId=-12596,wowhead=[[https://www.wowhead.com/wotlk/quest=12599]],image=[[assets/images/quests/placeholder.png]],desc=[[Well, it ain't glamorous, but it needs doin'. My troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya. What they need is a nice fire to dry 'em out and lighten their spirits. This part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture. Round us up some fuel for burnin' and we'll be mighty grateful.]],logDesc=[[Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood.]]}
DB[12600]={id=12600,name=[[Upper Deck Promo - Bear Mount]],name_loc=[[Promoción de Upper Deck - Montura de oso]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12600]],image=[[assets/images/quests/placeholder.png]]}
DB[12601]={id=12601,zoneId=66,name=[[The Alchemist's Apprentice]],level=76,minLevel=74,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12601]],image=[[assets/images/quests/placeholder.png]],desc=[[Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands. We have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum. Creating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step. Let me know when you're ready, $r. And remember, timing is everything!]],logDesc=[[Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum. When you are ready to begin, you are to speak to him and follow his instructions.]]}
DB[12602]={id=12602,zoneId=66,name=[[The Alchemist's Apprentice]],level=76,minLevel=74,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12602]],image=[[assets/images/quests/placeholder.png]],desc=[[Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands. We have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum. Creating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step. Let me know when you're ready, $r. And remember, timing is everything!]],logDesc=[[Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum. When you are ready to begin, you are to speak to him and follow his instructions.]]}
DB[12603]={id=12603,zoneId=3711,name=[[Sharpening Your Talons]],level=77,minLevel=76,giver=[[Dorian Drakestalker]],giverType=[[NPC]],giverId=28376,ender=[[Dorian Drakestalker]],enderType=[[NPC]],enderId=28376,prevId=12595,exGroup=-12603,wowhead=[[https://www.wowhead.com/wotlk/quest=12603]],image=[[assets/images/quests/placeholder.png]],desc=[[The primordial drakes occupy most of the area to the north and east, and I can feel the heat of their breath even at this distance. Before we can challenge the mightiest among the drakes, we must test our skills against the lesser creatures. Still, don't let your guard down; any one of these beasts can devour a man whole. Once you've familiarized yourself with the combat tactics of these drakes, return and I will tell you our next step.]],logDesc=[[Kill 6 Primordial Drakes and then speak with Dorian Drakestalker at Dorian's Outpost.]]}
DB[12604]={id=12604,zoneId=66,name=[[Congratulations!]],level=76,minLevel=74,giver=[[Commander Kunz]],giverType=[[NPC]],giverId=28039,ender=[[Commander Kunz]],enderType=[[NPC]],enderId=28039,wowhead=[[https://www.wowhead.com/wotlk/quest=12604]],image=[[assets/images/quests/placeholder.png]],rewards={{id=43556,qty=1}}}
DB[12605]={id=12605,zoneId=3711,name=[[Securing the Bait]],level=77,minLevel=76,giver=[[Dorian Drakestalker]],giverType=[[NPC]],giverId=28376,ender=[[Dorian Drakestalker]],enderType=[[NPC]],enderId=28376,prevId=12595,exGroup=-12603,wowhead=[[https://www.wowhead.com/wotlk/quest=12605]],image=[[assets/images/quests/placeholder.png]],desc=[[We're not likely to get Broodmother Slivina's attention waving our arms around like fools, but if we're smart, we can bait her into fighting us. We'll also secure more, uh, fodder for my little project. <Dorian glances over at Zootfizzle.> But don't worry about that for now. Just look for the primordial drake eggs in the area east and northeast of the camp. Burst them open and scoop up the hatchlings that come out. When the broodmother realizes what we've done, she'll have no choice but to face us.]],logDesc=[[Bring 6 Primordial Hatchlings to Dorian Drakestalker at Dorian's Outpost.]]}
DB[12606]={id=12606,zoneId=66,name=[[Cocooned!]],level=76,minLevel=74,giver=[[Captain Rupert]],giverType=[[NPC]],giverId=28044,ender=[[Captain Rupert]],enderType=[[NPC]],enderId=28044,prevId=12598,wowhead=[[https://www.wowhead.com/wotlk/quest=12606]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that the tunnels have been sealed, our next concern is recovering those who have fallen to the enemy. With any luck, several of our soldiers are still alive and relatively well inside the nerubian cocoons. Free them, $c, while you still can!]],logDesc=[[Captain Rupert wants you to open the Nerubian Cocoons in Drak'Sotra and return to him once you have freed 3 Captive Footmen.]]}
DB[12607]={id=12607,zoneId=3711,name=[[A Mammoth Undertaking]],level=77,minLevel=76,giver=[[Zootfizzle]],giverType=[[NPC]],giverId=28374,ender=[[Zootfizzle]],enderType=[[NPC]],enderId=28374,prevId=12603,wowhead=[[https://www.wowhead.com/wotlk/quest=12607]],image=[[assets/images/quests/placeholder.png]],desc=[[Before you go off challenging Broodmother Slivina, Dorian thought it might be a good idea for you and Hemet to coordinate your efforts by riding into battle on the back of a mammoth. The area around the camp is full of them. Just take this bridle and skip it over the head of a shattertusk mammoth. Be careful of the bulls, though. They won't tolerate the harness at all. Bring the mammoth back here when you've found a suitable one.]],logDesc=[[Bring a Shattertusk Mammoth to Zootfizzle at Dorian's Outpost.]]}
DB[12608]={id=12608,zoneId=3711,name=[[Cultist Incursion]],level=78,minLevel=77,giver=[[Cultist Corpse]],giverType=[[NPC]],giverId=28464,ender=[[Avatar of Freya]],enderType=[[NPC]],enderId=27801,prevId=12612,wowhead=[[https://www.wowhead.com/wotlk/quest=12608]],image=[[assets/images/quests/placeholder.png]],desc=[[<It appears the Avatar of Freya was right.  The undead were not able to enter Sholazar Basin before the Lifeblood Pillar was brought down -- they used their living agents from the Cult of the Damned instead.> <You'd best warn her about the Lich King's living agents within Sholazar Basin.>]],logDesc=[[Speak to the Avatar of Freya at the Rainspeaker Rapids.]]}
DB[12609]={id=12609,zoneId=66,name=[[Stocking the Shelves]],level=76,minLevel=74,giver=[[Captain Arnath]],giverType=[[NPC]],giverId=28045,ender=[[Captain Arnath]],enderType=[[NPC]],enderId=28045,prevId=12799,wowhead=[[https://www.wowhead.com/wotlk/quest=12609]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen, $c. I realize that it's a lot to ask.... Fresh spider ichor is somewhat hard to come by, even in these heavily infested regions. But Finklestein said he'd settle for no less than a vat of it, and that he needs it soon. I'll keep my men out in the field collecting reagents, but if the alchemist's order is going to be filled in time, they'll require some assistance. As you roam the fields of Zul'Drak, keep your eyes peeled for trapdoor crawlers and bring me all of the ichor you can find.]],logDesc=[[Captain Arnath in Heb'Valok asked you to collect 7 units of Fresh Spider Ichor from the Trapdoor Crawlers in Zul'Drak.]],choiceRewards={{id=39865,qty=1},{id=39852,qty=1},{id=39853,qty=1},{id=39802,qty=1},{id=39829,qty=1}}}
DB[12610]={id=12610,zoneId=66,name=[[Clipping Their Wings]],level=76,minLevel=74,giver=[[Captain Arnath]],giverType=[[NPC]],giverId=28045,ender=[[Captain Arnath]],enderType=[[NPC]],enderId=28045,prevId=12799,wowhead=[[https://www.wowhead.com/wotlk/quest=12610]],image=[[assets/images/quests/placeholder.png]],desc=[[Ever since Finklestein's arrival, I've been relegated to collecting various ingredients for his experiments and recipes. I'll follow my orders as I've vowed to do, but I'm a seasoned veteran. I've taken part in dozens of conflicts. I'd much rather be on the front lines, having a more direct impact on the Crusade's outcome here. Help me, $r. Collect some bat wings for me so that I might get back to the real action sooner.]],logDesc=[[Captain Arnath in Heb'Valok has asked you to collect 7 Unblemished Bat Wings from Zul'Drak Bats.]],choiceRewards={{id=39804,qty=1},{id=39867,qty=1},{id=39854,qty=1},{id=39855,qty=1}}}
DB[12611]={id=12611,zoneId=3711,name=[[Returned Sevenfold]],level=77,minLevel=77,giver=[[Avatar of Freya]],giverType=[[NPC]],giverId=27801,ender=[[Avatar of Freya]],enderType=[[NPC]],enderId=27801,prevId=12561,rewardNextId=12612,wowhead=[[https://www.wowhead.com/wotlk/quest=12611]],image=[[assets/images/quests/placeholder.png]],desc=[[The agents of the Lich King have foolishly trespassed upon these lands where the power of life rules supreme.  All harm they inflict will be returned to them sevenfold. The monster directly responsible for corrupting the land is known as Thalgran Blightbringer; you will find him just to the north of here.  Take this ward and use it to reflect the power of death upon him.  Show the Scourge that the power of life prevails above all.]],logDesc=[[The Avatar of Freya wants you defeat Thalgran Blightbringer by using Freya's Ward to reflect his Deathbolts back to him sevenfold.]],rewards={{id=39481,qty=1}},choiceRewards={{id=39367,qty=1},{id=39412,qty=1},{id=39444,qty=1},{id=39464,qty=1}}}
DB[12612]={id=12612,zoneId=3711,name=[[The Fallen Pillar]],level=77,minLevel=77,giver=[[Avatar of Freya]],giverType=[[NPC]],giverId=27801,ender=[[Cultist Corpse]],enderType=[[NPC]],enderId=28464,prevId=12611,rewardNextId=12608,wowhead=[[https://www.wowhead.com/wotlk/quest=12612]],image=[[assets/images/quests/placeholder.png]],desc=[[The titans shaped entire life forms here, fostering their unfettered growth. The five crystal pillars that surround the basin emanate pure lifeforce.  The Scourge should've never been able to penetrate the basin, but one of the pillars was destroyed. Go to the Lifeblood Pillar and see if you can find out what happened.  No undead would've been able to approach the pillar, so keep your eyes out for living intruders.  You'll find what remains of the pillar directly south of here.]],logDesc=[[Travel to the Lifeblood Pillar and look for clues to its destruction.]]}
DB[12613]={id=12613,zoneId=3711,name=[[Powering the Waygate - The Maker's Overlook]],level=77,minLevel=77,giver=[[Avatar of Freya]],giverType=[[NPC]],giverId=27801,ender=[[Avatar of Freya]],enderType=[[NPC]],enderId=27801,prevId=12559,rewardNextId=12548,wowhead=[[https://www.wowhead.com/wotlk/quest=12613]],image=[[assets/images/quests/placeholder.png]],desc=[[We cannot stop now, $r.  You've triggered the first switch, but one remains. The titans constructed a second vantage point where they oversaw their creations.  You'll find it to the east, high in the mountains. Pull the activation switch theta inside the overlook and the waygate will open.]],logDesc=[[The Avatar of Freya wants you to head to the Maker's Overlook in eastern Sholazar Basin and use the Activation Switch Theta.]]}
DB[12614]={id=12614,zoneId=3711,name=[[Post-partum Aggression]],level=77,minLevel=76,giver=[[Dorian Drakestalker]],giverType=[[NPC]],giverId=28376,ender=[[Dorian Drakestalker]],enderType=[[NPC]],enderId=28376,prevId=12607,wowhead=[[https://www.wowhead.com/wotlk/quest=12614]],image=[[assets/images/quests/placeholder.png]],desc=[[Broodmother Slivina's likely to be a snarling ball of teeth, spikes, and talons. You've gone and stolen her children away and no mother takes kindly to that. 'Tis true they hatched from eggs, but she loves the little beasts no less than your mother loves you. She'll be desperate and fierce in equal measures, everything Hemet loves in a target. You and he, along with that mammoth, should be a match for her. She's on her perch at the northern edge of the Savage Thicket and hungers for revenge.]],logDesc=[[Kill Broodmother Slivina and return to Dorian Drakestalker at Dorian's Outpost.]],choiceRewards={{id=39487,qty=1},{id=39486,qty=1},{id=39490,qty=1},{id=39488,qty=1},{id=39478,qty=1},{id=40353,qty=1}}}
DB[12615]={id=12615,zoneId=66,name=[[The Blessing of Zim'Torga]],level=77,minLevel=74,giver=[[Witch Doctor Khufu]],giverType=[[NPC]],giverId=28479,enderType=[[NPC]],prevId=12516,wowhead=[[https://www.wowhead.com/wotlk/quest=12615]],image=[[assets/images/quests/placeholder.png]],desc=[[Hexxer Ubungo probably told you about making offerings to the gods of Zul'Drak. Zim'Abwa is not the only god that stands forgotten by the Drakkari. We have taken refuge within the presence of Zim'Torga, the Mother of Prosperity. As with Zim'Abwa, if you were to give offerings of the Drakkari to her, she is sure to give you her blessing.]],logDesc=[[Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Torga.]]}
DB[12616]={id=12616,zoneId=2562,name=[[Chamber of Secrets]],level=70,minLevel=70,giver=[[Argent Emissary]],giverType=[[NPC]],giverId=16285,ender=[[Argent Emissary]],enderType=[[NPC]],enderId=16285,wowhead=[[https://www.wowhead.com/wotlk/quest=12616]],image=[[assets/images/quests/placeholder.png]],desc=[[Excellent, an experienced adventurer. Precisely what we need. There has been talk from the Kirin Tor guarding Medivh's tower that something is amiss with Karazhan. There is a new power lurking within, one that answers neither to the Guardian's magic nor the Legion. From what they've scouted, it appears it is an elven prince called Tenris Mirkblood, and there is reason to believe he serves the Scourge. Go, my friend, investigate Mirkblood's chamber, and return with any information you might find.]],logDesc=[[The Argent Dawn Emissary wants you to search the chamber of Tenris Mirkblood within the Servant's Quarters of Karazhan.]],rewards={{id=40354,qty=1}}}
DB[12617]={id=12617,zoneId=3711,name=[[Exterminate the Intruders]],level=77,minLevel=77,giver=[[Avatar of Freya]],giverType=[[NPC]],giverId=27801,ender=[[Avatar of Freya]],enderType=[[NPC]],enderId=27801,prevId=12608,exGroup=-12617,wowhead=[[https://www.wowhead.com/wotlk/quest=12617]],image=[[assets/images/quests/placeholder.png]],desc=[[I am an embodiment of but one aspect of Freya, daughter of the titans.  I am the Lifewarden -- I was left here to protect this land against the threat of the Scourge. I never anticipated the Lich King would send willing living servants to do his work. I could easily crush these cultists myself, but I am all that stands between the undead armies and the rest of the basin.  Go, $N.  Deliver my wrath to these insolent trespassers.]],logDesc=[[The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Death's Hand Encampment to the northwest and slay 8 Cultist Infiltrators.]],choiceRewards={{id=39365,qty=1},{id=39385,qty=1},{id=39441,qty=1},{id=39449,qty=1}}}
DB[12618]={id=12618,zoneId=66,name=[[Blessing of Zim'Torga]],level=77,minLevel=74,giverType=[[NPC]],enderType=[[NPC]],prevId=12615,wowhead=[[https://www.wowhead.com/wotlk/quest=12618]],image=[[assets/images/quests/placeholder.png]]}
DB[12619]={id=12619,name=[[The Emblazoned Runeblade]],name_loc=[[La hojarruna blasonada]],level=55,minLevel=55,giver=[[Instructor Razuvious]],giverType=[[NPC]],giverId=28357,ender=[[Instructor Razuvious]],enderType=[[NPC]],enderId=28357,prevId=12593,rewardNextId=12842,poiX=2439,poiY=-5672,wowhead=[[https://www.wowhead.com/wotlk/quest=12619]],image=[[assets/images/quests/placeholder.png]],desc=[[The single most important piece of equipment to a death knight is the runeblade. It is through the runeblade that a death knight commands the powers of frost, blood and the unholy. The runeblade also acts as a vessel to store the death knight's runic power. The time has come to create your first runeblade. Search the weapon racks on this floor and locate a battle-worn sword. Once found, take the sword to a nearby runeforge and use it to create a runeblade.]],logDesc=[[Search the weapon racks in Ebon Hold for a Battle-worn Sword and then use it on a runeforge to craft a Runebladed Sword. Return the Runebladed Sword to Instructor Razuvious in Ebon Hold.]],rewards={{id=38707,qty=1}}}
DB[12620]={id=12620,zoneId=3711,name=[[The Lifewarden's Wrath]],level=77,minLevel=77,giver=[[Avatar of Freya]],giverType=[[NPC]],giverId=27801,ender=[[Avatar of Freya]],enderType=[[NPC]],enderId=27801,prevId=12617,rewardNextId=12621,wowhead=[[https://www.wowhead.com/wotlk/quest=12620]],image=[[assets/images/quests/placeholder.png]],desc=[[We were not quick enough, $N.  The cultist scum have arrived at the Glimmering Pillar and are making preparations to destroy it, I can sense them. We don't have much time.  Blow upon this horn atop the Glimmering Pillar to channel my power through the crystal. We shall show this scum to not trifle with the titans' creations.]],logDesc=[[The Avatar of Freya at the Rainspeaker Rapids wants you to use Freya's Horn atop of the Glimmering Pillar.]]}
DB[12621]={id=12621,zoneId=3711,name=[[Freya's Pact]],level=77,minLevel=77,giver=[[Avatar of Freya]],giverType=[[NPC]],giverId=27801,ender=[[Avatar of Freya]],enderType=[[NPC]],enderId=27801,prevId=12620,rewardNextId=12559,wowhead=[[https://www.wowhead.com/wotlk/quest=12621]],image=[[assets/images/quests/placeholder.png]],desc=[[The cultists have been taken care of, but the Scourge's invasion has not slowed down.  The situation is becoming desperate, $N. There exists a last resort.  Before I reveal any more, however, I must be sure I have your absolute trust.]],logDesc=[[Listen to what the Avatar of Freya has to say.]]}
DB[12622]={id=12622,zoneId=66,name=[[The Leaders at Jin'Alai]],level=77,minLevel=74,giver=[[Scalper Ahunae]],giverType=[[NPC]],giverId=28484,ender=[[Scalper Ahunae]],enderType=[[NPC]],enderId=28484,prevId=12623,rewardNextId=12640,wowhead=[[https://www.wowhead.com/wotlk/quest=12622]],image=[[assets/images/quests/placeholder.png]],desc=[[You thinkin' what Ahunae thinkin', mon? Some of the Drakkari trolls have gathered at the Pools of Jin'Alai to the southwest. We be needin' to draw out their leaders, and Ahunae knows just how you be doin' it, too! Go in there and kill those trolls. When you kill enough, their leaders show up. When they show up next to their totems, you make sure to be gettin' the treasure of Kutube'sa, Gawanil, and Chulo the Mad, mon.]],logDesc=[[Scalper Ahunae at Zim'Torga has asked you to retrieve the Treasure of Kutube'sa, the Treasure of Gawanil, and the Treasure of Chulo the Mad.]],rewards={{id=20390,qty=5}},choiceRewards={{id=39775,qty=1},{id=39838,qty=1},{id=39796,qty=1},{id=39798,qty=1}}}
DB[12623]={id=12623,zoneId=66,name=[[To the Witch Doctor]],level=77,minLevel=74,giver=[[Hexxer Ubungo]],giverType=[[NPC]],giverId=28062,ender=[[Witch Doctor Khufu]],enderType=[[NPC]],enderId=28479,prevId=12516,rewardNextId=12627,wowhead=[[https://www.wowhead.com/wotlk/quest=12623]],image=[[assets/images/quests/placeholder.png]],desc=[[We Zandalari could use your help, $N. We must put an end to what the Drakkari are doing to their gods! To the northeast, up the great steps that lead to the next tier of Zul'Drak, lies Zim'Torga. It is the home to another of the god statues and a refuge that my people are desparately attempting to defend. I would like for you to travel there and speak to Witch Doctor Khufu. Be warned though, the place is under constant attack from the Drakkari.]],logDesc=[[Speak with Witch Doctor Khufu at Zim'Torga.]]}
DB[12624]={id=12624,zoneId=3711,name=[[It Could Be Anywhere!]],level=76,minLevel=76,giver=[[Chad]],giverType=[[NPC]],giverId=28497,ender=[[Chad]],enderType=[[NPC]],enderId=28497,wowhead=[[https://www.wowhead.com/wotlk/quest=12624]],image=[[assets/images/quests/placeholder.png]],desc=[[When I found out that Miss Boulian was helping Nesingwary with his expedition, I signed up as a deckhand immediately.  You see, I'd been meaning to marry her for months! I had it all planned out.  I was going to propose the very night of the shipwreck... but now the ring is gone.  I've searched everywhere! I know it might sound crazy, but I know the engagement ring is in the Basin.  If some Venture Company didn't steal it, maybe a wild creature ate it.  But it's here somewhere... I just know it!]],logDesc=[[Look for a Golden Engagement Ring on the various creatures in Sholazar Basin.]],choiceRewards={{id=39479,qty=1},{id=39446,qty=1},{id=39466,qty=1},{id=39474,qty=1}}}
DB[12625]={id=12625,name=[[Dominion Over Acherus]],name_loc=[[Dominio de Acherus]],level=55,minLevel=55,giverType=[[NPC]],enderType=[[NPC]],poiX=2450,poiY=-5652,wowhead=[[https://www.wowhead.com/wotlk/quest=12625]],image=[[assets/images/quests/placeholder.png]],desc=[[Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold. Though your thoughts may still be hazy, we haven't a moment to spare. You must claim dominion over Acherus and your mind! The horns of war surge! Take the stairs on this floor - located north, south, east and west - to the garrison floor above us. Seek out Master Siegesmith Corvus and acquire his status report. It must be delivered to Thalanor.]],logDesc=[[Report to Master Siegesmith Corvus on the garrison floor of Ebon Hold.]]}
DB[12626]={id=12626,name=[[Company of the Damned]],name_loc=[[La Compañía de los Condenados]],level=55,minLevel=55,giverType=[[NPC]],enderType=[[NPC]],poiX=2354,poiY=-5666,wowhead=[[https://www.wowhead.com/wotlk/quest=12626]],image=[[assets/images/quests/placeholder.png]],desc=[[<Corvus salutes.> Our stockpiles of weapons, armor and munitions are nearly at maximum capacity. We are ready for war! <Corvus rolls up a fleshy piece of vellum.> On the other side of this garrison floor, southwest of here, you will find the officers' quarters. Take this status report there and deliver it to Scourge Commander Thalanor, battalion commander of the Company of the Damned.]],logDesc=[[Deliver Corvus' Report to Scourge Commander Thalanor at the garrison floor of Ebon Hold.]]}
DB[12627]={id=12627,zoneId=66,name=[[Breaking Through Jin'Alai]],level=77,minLevel=74,giver=[[Witch Doctor Khufu]],giverType=[[NPC]],giverId=28479,ender=[[Witch Doctor Khufu]],enderType=[[NPC]],enderId=28479,prevId=12623,wowhead=[[https://www.wowhead.com/wotlk/quest=12627]],image=[[assets/images/quests/placeholder.png]],desc=[[I have been trying to commune with the gods. However, the medicine men at the Pools of Jin'Alai are performing rituals that are interfering with my attempts. It is imperative that we break through their obtrusion. If you were to head southwest into the pools area, I am certain that you would come across the cauldrons they are using for their magic. Disturb each of the cauldrons to bring down their ritual that is blocking me.]],logDesc=[[Witch Doctor Khufu at Zim'Torga has asked you to disturb the Blue Cauldron, Green Cauldron, Purple Cauldron, and Red Cauldron.]]}
DB[12628]={id=12628,zoneId=66,name=[[To Speak With Har'koa]],level=77,minLevel=74,giver=[[Witch Doctor Khufu]],giverType=[[NPC]],giverId=28479,ender=[[Har'koa]],enderType=[[NPC]],enderId=28401,prevId=12627,rewardNextId=12632,wowhead=[[https://www.wowhead.com/wotlk/quest=12628]],image=[[assets/images/quests/placeholder.png]],desc=[[The gods have spoken, $N. We now know what you must do. You must now go to the Altar of Har'koa to the southeast and speak with the leopard goddess.]],logDesc=[[Speak with Har'koa at the Altar of Har'koa.]]}
DB[12629]={id=12629,zoneId=66,name=[[You Can Run, But You Can't Hide]],level=75,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12637,rewardNextId=12648,wowhead=[[https://www.wowhead.com/wotlk/quest=12629]],image=[[assets/images/quests/placeholder.png]],desc=[[Once the Scourge have a target in their sights, they'll stop at nothing to acquire it. You're doomed to a mindless existence as a walking corpse.... <Stefan's face twists into a cruel grin.> ... unless we can use their desires against them. I'll explain later. I have complex magic to prepare which requires certain material components. Travel due east of here to the Reliquary of Agony. Slay abominations and gather the ghoul drool you'll find there then return to me with their remnants.]],logDesc=[[Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.]]}
DB[12630]={id=12630,zoneId=66,name=[[Kickin' Nass and Takin' Manes]],level=75,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12884,wowhead=[[https://www.wowhead.com/wotlk/quest=12630]],image=[[assets/images/quests/placeholder.png]],desc=[[Before you meet Nass, there's something you should know. He got a toxic dose of blight back in the day, and now he's deaf, blind, and mostly numb. It's not all bad, though. He's virtually immune to the stuff now, which makes him perfect for certain tasks - like the one I'm about to give you. There are many freshly scourged trolls nearby and we need to study the blight's effect on them. Take Nass, and this boot. When you've slain a troll, give him a good kick and he'll know to take a hair sample.]],logDesc=[[Stefan in Ebon Watch wants you to use Nass to collect 10 hair samples from Withered Trolls. If you lose Nass, return to Stefan to recover him.]]}
DB[12631]={id=12631,zoneId=66,name=[[An Invitation, of Sorts...]],level=75,minLevel=74,giverType=[[NPC]],ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,rewardNextId=12637,wowhead=[[https://www.wowhead.com/wotlk/quest=12631]],image=[[assets/images/quests/placeholder.png]],desc=[[Crafted of bone and dripping with blood, this choker is of intricate and deliberate design. Gazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch. If anyone can explain this, a death knight can....]],logDesc=[[Take the Unliving Choker to Stefan at Ebon Watch.]]}
DB[12632]={id=12632,zoneId=66,name=[[But First My Offspring]],level=77,minLevel=74,giver=[[Har'koa]],giverType=[[NPC]],giverId=28401,ender=[[Har'koa]],enderType=[[NPC]],enderId=28401,prevId=12628,wowhead=[[https://www.wowhead.com/wotlk/quest=12632]],image=[[assets/images/quests/placeholder.png]],desc=[[I am the last of the gods to be subdued, so we must first attempt to free the others. Bound by the magics of my subduers, I am unable to discern their fates. But first, I would ask that you do me a kindness. Already the Drakkari turn my magic against me. They have transformed my offspring into monstrosities. Take one of my whiskers. Slay my tortured children and use the magic of it to release them from their nightmare, and bring them back to life.]],logDesc=[[Har'koa has asked you to use her whisker on the corpses of her children to free and resurrect them. Return to her at the Altar of Har'koa when you are done.]],choiceRewards={{id=39787,qty=1},{id=39856,qty=1},{id=39821,qty=1},{id=39891,qty=1}}}
DB[12633]={id=12633,zoneId=66,name=[[Darkness Calling]],level=75,minLevel=74,giverType=[[NPC]],ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12238,rewardNextId=12638,wowhead=[[https://www.wowhead.com/wotlk/quest=12633]],image=[[assets/images/quests/placeholder.png]],desc=[[Crafted of bone and dripping with blood, this choker is of intricate and deliberate design. Gazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch. If anyone can explain this, a death knight can....]],logDesc=[[Take the Writhing Choker to Stefan in Ebon Watch.]]}
DB[12634]={id=12634,zoneId=3711,name=[[Some Make Lemonade, Some Make Liquor]],level=76,minLevel=76,giver=[[Grimbooze Thunderbrew]],giverType=[[NPC]],giverId=29157,ender=[[Grimbooze Thunderbrew]],enderType=[[NPC]],enderId=29157,rewardNextId=12644,wowhead=[[https://www.wowhead.com/wotlk/quest=12634]],image=[[assets/images/quests/placeholder.png]],desc=[[Life's tossed me a cartload of lemons this time! When the ship ran aground, the kegs carrying my best brew burst! All we have now are a few bottles of rum, and it won't sustain a thirsty expedition! We need to get some booze cooking, and fast!! The trees in the Wildgrowth Mangal, to the east, seem laden with fruit, but it's too high for me to reach. Look for good, strong vines, see if you can use it to shake some of that fruit out of the trees. Bring me whatever you can find.]],logDesc=[[Bring 1 Orange, 2 Banana Bunches, and 1 Papaya to Grimbooze Thunderbrew at the Nesingwary Base Camp.]]}
DB[12635]={id=12635,zoneId=66,name=[[Relics of the Snow Leopard Goddess]],level=77,minLevel=74,giver=[[Chronicler To'kini]],giverType=[[NPC]],giverId=28527,ender=[[Chronicler To'kini]],enderType=[[NPC]],enderId=28527,wowhead=[[https://www.wowhead.com/wotlk/quest=12635]],image=[[assets/images/quests/placeholder.png]],desc=[[I overheard that you are going to see to the well-being of Har'koa. Good luck to you. I am wondering if while you are in the vicinity of the altar, you would be willing to recover their relics? I do not require many, and it is only a short trip to the southeast. What do you say?]],logDesc=[[Chronicler To'kini at Zim'Torga wants you to recover 10 Har'koan Relics.]]}
DB[12636]={id=12636,name=[[The Eye Of Acherus]],name_loc=[[El ojo de Acherus]],level=55,minLevel=55,giver=[[Instructor Razuvious]],giverType=[[NPC]],giverId=28357,ender=[[The Lich King]],ender_loc=[[El Rey Exánime]],enderType=[[NPC]],enderId=25462,prevId=12848,rewardNextId=12641,poiX=2345,poiY=-5672,wowhead=[[https://www.wowhead.com/wotlk/quest=12636]],image=[[assets/images/quests/placeholder.png]],desc=[[Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold. Looming above the face of the necropolis is the all-seeing eye of Acherus. From it the master is able to see great distances into the territories held by our enemies. What the eye sees, the Lich King sees, and now the time has come for you to peer through the eye! The Lich King has called for you, $N. Go now! Suffer well, $g brother:sister;... ]],logDesc=[[Report to the Lich King in Ebon Hold.]]}
DB[12637]={id=12637,zoneId=66,name=[[Near Miss]],level=75,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12631,rewardNextId=12629,wowhead=[[https://www.wowhead.com/wotlk/quest=12637]],image=[[assets/images/quests/placeholder.png]],desc=[[It was either wisdom or luck that prevented you from wearing this choker, $r. Either way, your acquiring it was no random occurance. You've been targeted by someone, or something.... Take your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.]],logDesc=[[Stefan at Ebon Watch wants you to take the Unliving Choker to Bloodrose Datura.]]}
DB[12638]={id=12638,zoneId=66,name=[[Close Call]],level=75,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12633,rewardNextId=12643,wowhead=[[https://www.wowhead.com/wotlk/quest=12638]],image=[[assets/images/quests/placeholder.png]],desc=[[It was either wisdom or luck that prevented you from wearing this choker, $r. Either way, your acquiring it was no random occurence. You've been targeted by someone, or something.... Take your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.]],logDesc=[[Stefan at Ebon Watch wants you to take the Writhing Choker to Bloodrose Datura.]]}
DB[12639]={id=12639,zoneId=66,name=[[The Frozen Earth]],level=77,minLevel=74,giver=[[Element-Tamer Dagoda]],giverType=[[NPC]],giverId=28480,ender=[[Element-Tamer Dagoda]],enderType=[[NPC]],enderId=28480,prevId=12622,wowhead=[[https://www.wowhead.com/wotlk/quest=12639]],image=[[assets/images/quests/placeholder.png]],desc=[[We captured these elementals from nearby, and I have plenty of defenders now. But, it takes a great deal of power to make them strong enough to stand up to our enemies. The frozen earth at Drak'Mabwa to the northwest have what I need to maintain our defenses. I'll need more of their essence if I'm to keep this up.]],logDesc=[[Element-Tamer Dagoda at Zim'Torga wants you to collect 7 Essence of the Frozen Earth.]],choiceRewards={{id=39772,qty=1},{id=39835,qty=1},{id=39783,qty=1},{id=39786,qty=1}}}
DB[12640]={id=12640,zoneId=66,name=[[Sealing the Rifts]],level=77,minLevel=74,giver=[[Scalper Ahunae]],giverType=[[NPC]],giverId=28484,ender=[[Scalper Ahunae]],enderType=[[NPC]],enderId=28484,prevId=12622,rewardNextId=12659,wowhead=[[https://www.wowhead.com/wotlk/quest=12640]],image=[[assets/images/quests/placeholder.png]],desc=[[Dagoda gonna be sendin' you northwest to Drak'Mabwa to get her more stuff for her defenders if she didn't already. While you up there, Ahunae be wantin' you to destroy the rifts those elementals pourin' out of. The last thing we needin' is for them to attack us! Just watch out, more of those frozen earth'll show up when you try to seal the rifts.]],logDesc=[[Scalper Ahunae at Zim'Torga has asked you to seal 7 Elemental Rifts.]]}
DB[12641]={id=12641,name=[[Death Comes From On High]],name_loc=[[La muerte viene de arriba]],level=55,minLevel=55,giver=[[The Lich King]],giver_loc=[[El Rey Exánime]],giverType=[[NPC]],giverId=25462,ender=[[The Lich King]],ender_loc=[[El Rey Exánime]],enderType=[[NPC]],enderId=25462,prevId=12636,rewardNextId=12657,poiX=1815,poiY=-5989,wowhead=[[https://www.wowhead.com/wotlk/quest=12641]],image=[[assets/images/quests/placeholder.png]],desc=[[Towering above this platform is the eye of Acherus. From it you will call forth a probe that you will then use to analyze Scarlet Crusade fortifications at New Avalon. The eye has a host of powers that should make the acquisition of this data simple. Use the eye's siphon to analyze the forge, town hall, hold, and chapel. The eye's control mechanisms are located on either side of this platform. Waste no more time, $N. The Scourge will have this place. The Lich King commands it!]],logDesc=[[The Lich King commands you to use the Eye of Acherus to analyze the Scarlet Hold, New Avalon Forge, New Avalon Town Hall and the Chapel of the Crimson Flame. Control the Eye of Acherus by using the Eye of Acherus Control Mechanism.]]}
DB[12642]={id=12642,zoneId=66,name=[[Spirit of Rhunok]],level=77,minLevel=74,giver=[[Har'koa]],giverType=[[NPC]],giverId=28401,ender=[[Spirit of Rhunok]],enderType=[[NPC]],enderId=28561,prevId=12632,rewardNextId=12646,wowhead=[[https://www.wowhead.com/wotlk/quest=12642]],image=[[assets/images/quests/placeholder.png]],desc=[[My feelings tell me that Rhunok doesn't have much time. I can tell that the arctic bear god's spirit has already separated from his weakened body. It is his spirit with which you must commune. His altar lies to the northwest beyond Drak'Mabwa.]],logDesc=[[Speak with the Spirit of Rhunok at the Altar of Rhunok.]]}
DB[12643]={id=12643,zoneId=66,name=[[Silver Lining]],level=75,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12638,rewardNextId=12649,wowhead=[[https://www.wowhead.com/wotlk/quest=12643]],image=[[assets/images/quests/placeholder.png]],desc=[[Once the Scourge have a target in their sights, they'll stop at nothing to acquire it. You're doomed to a mindless existence as a walking corpse.... <Stefan's face twists into a cruel grin.> ... unless we can use their desires against them. I'll explain later. I have complex magic to prepare which requires certain material components. Travel due east of here to the land beneath the Reliquary of Agony. Slay the ghouls and abominations you'll find there and return to me with their remnants.]],logDesc=[[Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.]]}
DB[12644]={id=12644,zoneId=3711,name=[[Still At It]],level=76,minLevel=76,giver=[[Grimbooze Thunderbrew]],giverType=[[NPC]],giverId=29157,ender=[[Grimbooze Thunderbrew]],enderType=[[NPC]],enderId=29157,prevId=12634,rewardNextId=12645,wowhead=[[https://www.wowhead.com/wotlk/quest=12644]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we've got the raw materials, I've had my assistant ready the still. He'll oversee the process, but I want you to help keep everything under control. You might be tempted to think that we just throw everything into the still and let it sit, but you're wrong. Ingredients and heat need to be added at certain times, and the pressure regulated at others. You'll have no more than 10 seconds to react to a situation. Speak with "Tipsy" McManus when you're ready to start distilling.]],logDesc=[[Successfully complete the distillation process and bring the completed Thunderbrew's Jungle Punch to Grimbooze Thunderbrew at the Nesingwary Base Camp.]]}
DB[12645]={id=12645,zoneId=3711,name=[[The Taste Test]],level=76,minLevel=76,giver=[[Grimbooze Thunderbrew]],giverType=[[NPC]],giverId=29157,ender=[[Grimbooze Thunderbrew]],enderType=[[NPC]],enderId=29157,prevId=12644,wowhead=[[https://www.wowhead.com/wotlk/quest=12645]],image=[[assets/images/quests/placeholder.png]],desc=[[And now for the moment of truth! <Grimbooze chuckles.> I've always wanted to say that. Normally, I'd debut a new drink at a banquet, but we can't have one in the middle of the jungle. Instead, just take samples to a few trusted friends and return with their comments. Let's see, we'll definitely want Hemet Nesingwary's opinion, and Hadrius Harlowe's, too. They're here in camp. You'll want to head over to Lakeside Landing, near the center of the Basin and offer Tamara Wobblesprocket a taste.]],logDesc=[[Offer a sample of Thunderbrew's Jungle Punch to Hemet Nesingwary, Hadrius Harlowe, and Tamara Wobblesprocket, then return to Grimbooze Thunderbrew at the Nesingwary Base Camp.]],rewards={{id=39520,qty=20}}}
DB[12646]={id=12646,zoneId=66,name=[[My Prophet, My Enemy]],level=77,minLevel=74,giver=[[Spirit of Rhunok]],giverType=[[NPC]],giverId=28561,ender=[[Spirit of Rhunok]],enderType=[[NPC]],enderId=28561,prevId=12642,rewardNextId=12647,wowhead=[[https://www.wowhead.com/wotlk/quest=12646]],image=[[assets/images/quests/placeholder.png]],desc=[[My prophet absorbed too much of my power too quickly, and subsequently killed himself. You can see the results at the water-filled crater to the south in Drak'Mabwa. My former priests have already resurrected him so that he can finish the job. They're channeling my power back into him, and it will not be long now before he reawakens. You must put an end to him and return with my mojo before it is too late.]],logDesc=[[The Spirit of Rhunok at the Altar of Rhunok has asked you to acquire his Arctic Bear God Mojo.]]}
DB[12647]={id=12647,zoneId=66,name=[[An End to the Suffering]],level=77,minLevel=74,giver=[[Spirit of Rhunok]],giverType=[[NPC]],giverId=28561,ender=[[Spirit of Rhunok]],enderType=[[NPC]],enderId=28561,prevId=12646,rewardNextId=12653,wowhead=[[https://www.wowhead.com/wotlk/quest=12647]],image=[[assets/images/quests/placeholder.png]],desc=[[My body is too far gone now, $N. It is only a matter of time before a new prophet is elevated and finishes what the other began. I am going to imbue you with the last of my power. The tormentor inside the altar building carries incense, which will awaken my body and make it vulnerable. Use the incense and do me the kindness of putting an end to my suffering. I apologize if I fight back. Even for me, the will to survive is strong.]],logDesc=[[The Spirit of Rhunok has asked you to use the Tormentor's Incense to awaken his body. You are then to slay Rhunok using the power that his spirit has imbued you with. If for some reason you lose the Mojo of Rhunok aura, you can return to the Spirit of Rhunok to have it reapplied.]],choiceRewards={{id=39789,qty=1},{id=39858,qty=1},{id=39825,qty=1},{id=39893,qty=1}}}
DB[12648]={id=12648,zoneId=66,name=[[Dressing Down]],level=75,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12629,nextId=12661,rewardNextId=12661,exGroup=12648,wowhead=[[https://www.wowhead.com/wotlk/quest=12648]],image=[[assets/images/quests/placeholder.png]],desc=[[There... I've created a disguise that should make you indistinguishable from the Scourge. You'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them! Another thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert. Let's test it out. Use the choker and visit the Scourge merchant just east of here. Return to me with a bottle of bitter plasma.]],logDesc=[[Stefan at Ebon Watch wants you to use the Ensorceled Choker to apply the Scourge disguise. While in Scourge form, you are to purchase Bitter Plasma from Gristlegut. If you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]]}
DB[12649]={id=12649,zoneId=66,name=[[Suit Up!]],level=75,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12643,nextId=12661,rewardNextId=12661,exGroup=12648,wowhead=[[https://www.wowhead.com/wotlk/quest=12649]],image=[[assets/images/quests/placeholder.png]],desc=[[There... I've created a disguise that should make you indistinguishable from the Scourge. You'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them! Another thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert. Let's test it out. Use the choker and visit the Scourge vendor just east of here. Return to me with a bottle of bitter plasma.]],logDesc=[[Stefan at Ebon Watch wants you to use the Ensorcelled Choker to apply the Scourge disguise. While in Scourge form, you are to purchase Bitter Plasma from Gristlegut. If you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]]}
DB[12650]={id=12650,zoneId=66,name=[[Plundering Their Own]],level=77,minLevel=74,giver=[[Chronicler To'kini]],giverType=[[NPC]],giverId=28527,ender=[[Chronicler To'kini]],enderType=[[NPC]],enderId=28527,prevId=12635,wowhead=[[https://www.wowhead.com/wotlk/quest=12650]],image=[[assets/images/quests/placeholder.png]],desc=[[There is another altar nearby where there are artifacts to be saved. It is said that the Drakkari at the Altar of Rhunok to the northwest, beyond the broken tundra of Drak'Mabwa, have already plundered their own holy site. $C, I would be appreciative if you could rescue those artifacts from their undeserving hands.]],logDesc=[[Chronicler To'kini at Zim'Torga wants you to recover 7 Rhunokian Artifacts.]]}
DB[12651]={id=12651,zoneId=3711,name=[[Lakeside Landing]],level=77,minLevel=76,giver=[[Hemet Nesingwary]],giverType=[[NPC]],giverId=27986,ender=[[Tamara Wobblesprocket]],enderType=[[NPC]],enderId=28568,prevId=12592,wowhead=[[https://www.wowhead.com/wotlk/quest=12651]],image=[[assets/images/quests/placeholder.png]],desc=[[When the trouble with the Venture Company started, I asked Marvin Wobblesprocket and his wife, Tamara, to take their flying machines east to River's Heart. I asked them to setup a small camp there so that we could use them as a relay to fly in supplies and survey the area. They should have arrived by now and started setting up. River's Heart is near the center of the basin where the rivers converge. Search for Lakeshore Landing on the northeast shore. Marvin mentioned it would be the best spot.]],logDesc=[[Speak with Tamara Wobblesprocket at Lakeside Landing.]]}
DB[12652]={id=12652,zoneId=66,name=[[Feedin' Da Goolz]],level=75,minLevel=74,giver=[[Gristlegut]],giverType=[[NPC]],giverId=28589,ender=[[Gristlegut]],enderType=[[NPC]],enderId=28589,wowhead=[[https://www.wowhead.com/wotlk/quest=12652]],image=[[assets/images/quests/placeholder.png]],desc=[[Git o'er heer, gool! Yeh, I talkin' to yoo. It feedin' time now. Gotta git da grub ta all da gools! Speshal grub dis time! Bowels an' brainz bowl... num, num, num. Jus drop da bowl nexta da gool. Gud way ta make frenz. Yoo got goolfrenz? Ha, ha, hah!]],logDesc=[[Gristlegut at the Reliquary of Agony wants you to use Bowels and Brains Bowl next to 10 Decaying Ghouls.]],choiceRewards={{id=39812,qty=1},{id=39876,qty=1},{id=39880,qty=1},{id=39882,qty=1},{id=39831,qty=1}}}
DB[12653]={id=12653,zoneId=66,name=[[Back to Har'koa]],level=77,minLevel=74,giver=[[Spirit of Rhunok]],giverType=[[NPC]],giverId=28561,ender=[[Har'koa]],enderType=[[NPC]],enderId=28401,prevId=12647,rewardNextId=12665,wowhead=[[https://www.wowhead.com/wotlk/quest=12653]],image=[[assets/images/quests/placeholder.png]],desc=[[And now it is time for you to return to the leopard goddess. Somehow I sense that she has other plans for you. Tell her that no matter what, we are eternal.]],logDesc=[[Speak with Har'koa at the Altar of Har'koa.]]}
DB[12654]={id=12654,zoneId=3711,name=[[The Part-time Hunter]],level=76,minLevel=76,giver=[[Tamara Wobblesprocket]],giverType=[[NPC]],giverId=28568,ender=[[Tamara Wobblesprocket]],enderType=[[NPC]],enderId=28568,wowhead=[[https://www.wowhead.com/wotlk/quest=12654]],image=[[assets/images/quests/placeholder.png]],desc=[[When Hemet asked me to accompany Marvin out here, I hoped that I might have the opportunity to work on my own hunting skills in between repairing the flying machines and setting up the camp. I wanted to take down a ferocious lion named Pitch. He's said to make his home south of here, near where the Wildgrowth Mangal meets the northern face of the Skyreach Pillar. If you can find the beast, would you bring back his remains? If the rumors are true, they'd make a trophy even Hemet will respect!]],logDesc=[[Bring Pitch's Remains to Tamara Wobblesprocket at Lakeside Landing.]]}
DB[12655]={id=12655,zoneId=66,name=[[The Blessing of Zim'Rhuk]],level=77,minLevel=74,giver=[[Witch Doctor Khufu]],giverType=[[NPC]],giverId=28479,enderType=[[NPC]],prevId=12632,wowhead=[[https://www.wowhead.com/wotlk/quest=12655]],image=[[assets/images/quests/placeholder.png]],desc=[[There is another god of Zul'Drak that is being neglected. Zim'Rhuk's statue lies directly to the north. Known as "The Wise One", Zim'Rhuk is also known to be very protective of his domain. He maintains guardians that deal harshly with anyone that does not have the wits to slip past them. Avoid the guardians and give the Drakkari offerings to Zim'Rhuk so that you will benefit from his blessing.]],logDesc=[[Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Rhuk.]]}
DB[12656]={id=12656,zoneId=66,name=[[Blessing of Zim'Rhuk]],level=77,minLevel=74,giverType=[[NPC]],enderType=[[NPC]],prevId=12655,wowhead=[[https://www.wowhead.com/wotlk/quest=12656]],image=[[assets/images/quests/placeholder.png]]}
DB[12657]={id=12657,name=[[The Might Of The Scourge]],name_loc=[[El poder de la Plaga]],level=55,minLevel=55,giver=[[The Lich King]],giver_loc=[[El Rey Exánime]],giverType=[[NPC]],giverId=25462,ender=[[Highlord Darion Mograine]],ender_loc=[[Alto señor Darion Mograine]],enderType=[[NPC]],enderId=28444,prevId=12641,rewardNextId=12850,poiX=2461,poiY=-5593,wowhead=[[https://www.wowhead.com/wotlk/quest=12657]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen well, death knight, for I give to you the words that will start a war. My final judgment has been passed: Death. To. All. None shall stand so boldly against the might of the Scourge without reprisal! As you have served me well in your first task, so too shall you serve me in your next task. Take my judgment to Highlord Mograine at the command post of Acherus, found on the first floor. Tell him to begin the assault. And when the Crusade has been dealt with, we will finish off the Argent Dawn. ]],logDesc=[[The Lich King commands you to carry his orders to Highlord Darion Mograine at Ebon Hold. Use the glowing transporter behind the Lich King to reach Highlord Darion Mograine in the Hall of Command.]],rewards={{id=38662,qty=1}}}
DB[12658]={id=12658,zoneId=3711,name=[[My Pet Roc]],level=77,minLevel=76,giver=[[Zootfizzle]],giverType=[[NPC]],giverId=28374,ender=[[Zootfizzle]],enderType=[[NPC]],enderId=28374,prevId=12603,wowhead=[[https://www.wowhead.com/wotlk/quest=12658]],image=[[assets/images/quests/placeholder.png]],desc=[[Dorian's had me training and feeding the baby drakes he captures, and it has gotten me thinking. I want a pet of my own! No, not a juvenile drake. I don't want a pet capable of biting my hand off! However, in the Bonefields to the northeast of the camp, beyond the area dominated by the drakes, there's a large population of goretalon rocs. The grown ones are beyond hope of domesticating, but if you bring me the eggs from their nests, I can raise them from the time they hatch.]],logDesc=[[Bring 7 Roc Eggs to Zootfizzle at Dorian's Outpost.]]}
DB[12659]={id=12659,zoneId=66,name=[[Scalps!]],level=77,minLevel=74,giver=[[Scalper Ahunae]],giverType=[[NPC]],giverId=28484,ender=[[Scalper Ahunae]],enderType=[[NPC]],enderId=28484,prevId=12640,wowhead=[[https://www.wowhead.com/wotlk/quest=12659]],image=[[assets/images/quests/placeholder.png]],desc=[[I thinkin' it be time to do some scalpin', mon! The trolls at Heb'Drakkar to the northeast should do nicely. With their fancy bats and attackin' us, they got it comin'! Ahunae even give you his own knife so that you do the job right.]],logDesc=[[Scalper Ahunae at Zim'Torga wants you to use Ahunae's Knife to scalp 10 Heb'Drakkar trolls. The scalper reminds you that you should loot them first.]]}
DB[12660]={id=12660,zoneId=3711,name=[[Weapons of Destruction]],level=77,minLevel=77,giver=[[Avatar of Freya]],giverType=[[NPC]],giverId=27801,ender=[[Avatar of Freya]],enderType=[[NPC]],enderId=27801,prevId=12608,exGroup=-12617,wowhead=[[https://www.wowhead.com/wotlk/quest=12660]],image=[[assets/images/quests/placeholder.png]],desc=[[The Lich King's lackeys have dared to bring weapons of destruction into my domain.  I will not stand for this. Go to their outpost to the north and destroy the weapons they would use against the land.  We cannot let the Scourge taint another inch of these sacred lands.]],logDesc=[[The Avatar of Freya wants you to go to the Death's Hand Encampment to the northwest and destroy 4 Unstable Explosives.]]}
DB[12661]={id=12661,zoneId=66,name=[[Infiltrating Voltarus]],level=75,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,rewardNextId=12669,wowhead=[[https://www.wowhead.com/wotlk/quest=12661]],image=[[assets/images/quests/placeholder.png]],desc=[[By now you've probably guessed the details of my plan. We're using the Scourge's interest in you against them. You're going undercover. I know it's likely a death sentence, but if we do nothing your death is a certainty. Travel northeast to Reliquary of Pain and stand on the platform while wearing your disguise. Once inside Voltarus, you must earn the trust of the Scourge commander. When you've completed your mission, blow this horn and I'll fly to your location to receive your report.]],logDesc=[[Stefan wants you to use your Ensorcelled Choker to get into Voltarus and do whatever the Scourge leader there asks of you. If you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]],choiceRewards={{id=39809,qty=1},{id=39869,qty=1},{id=39866,qty=1},{id=39870,qty=1},{id=39830,qty=1}}}
DB[12662]={id=12662,zoneId=66,name=[[Bringing Down Heb'Jin]],level=77,minLevel=74,giver=[[Element-Tamer Dagoda]],giverType=[[NPC]],giverId=28480,ender=[[Element-Tamer Dagoda]],enderType=[[NPC]],enderId=28480,prevId=12640,wowhead=[[https://www.wowhead.com/wotlk/quest=12662]],image=[[assets/images/quests/placeholder.png]],desc=[[<Dagoda looks at Ahunae and sighs.> You want to really deal with Heb'Drakkar? Collecting scalps isn't going to get the job done. You have to take out their leader, Heb'Jin. The problem is, he's up on the bat rookery goading his forces on. Bang his drum and I guarantee that he'll fly down. That's when you kill him. You can take this net we got from one of his headhunters. Use it to trap his bat when he lands. That way you won't have to fight both of them. ]],logDesc=[[Element-Tamer Dagoda at Zim'Torga wants you to kill Heb'Jin.]],choiceRewards={{id=39777,qty=1},{id=39836,qty=1},{id=39788,qty=1},{id=39790,qty=1}}}
DB[12663]={id=12663,zoneId=66,name=[[Reunited]],level=75,minLevel=74,giver=[[Overlord Drakuru]],giverType=[[NPC]],giverId=28503,ender=[[Overlord Drakuru]],enderType=[[NPC]],enderId=28503,prevId=12649,exGroup=12663,wowhead=[[https://www.wowhead.com/wotlk/quest=12663]],image=[[assets/images/quests/placeholder.png]],desc=[[$n! Ya musta received mah gift! Turn around, mon, lemme get a good look at ya... Ahh, ya make me proud. We come such a long way, you and I, and now we be servin' da Lich King together. Stick with me and big things be comin, mon. Big things... but first, we need to be gettin' ya caught up. So much been happenin' since I saw ya last. Go speak ta Gorebag for a tour of Zul'Drak. Listen for me and I'll tell ya all ya be needin' ta know.]],logDesc=[[Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak.]]}
DB[12664]={id=12664,zoneId=66,name=[[Dark Horizon]],level=75,minLevel=74,giver=[[Overlord Drakuru]],giverType=[[NPC]],giverId=28503,ender=[[Overlord Drakuru]],enderType=[[NPC]],enderId=28503,prevId=12648,exGroup=12663,wowhead=[[https://www.wowhead.com/wotlk/quest=12664]],image=[[assets/images/quests/placeholder.png]],desc=[[Ahh, another supplicant answerin' da Lich King's call. <Drakuru sniffs you.> Freshly scourged, eh? Ya still be reekin' of da living! Long be da line of dem who seek da Lich King's blessings. Ya must rise above da masses and prove yerself worthy of wieldin' true power. Lookin' down over Zul'Drak, I sensed potential in ya. I ordered your - invitation. Da rest be up ta you.... Go an' speak ta Gorebag for a tour of Zul'Drak. Dere be much ta do if you're to be of any worth to me.]],logDesc=[[Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak.]]}
DB[12665]={id=12665,zoneId=66,name=[[I Sense a Disturbance]],level=77,minLevel=74,giver=[[Har'koa]],giverType=[[NPC]],giverId=28401,ender=[[Har'koa]],enderType=[[NPC]],enderId=28401,prevId=12653,rewardNextId=12666,wowhead=[[https://www.wowhead.com/wotlk/quest=12665]],image=[[assets/images/quests/placeholder.png]],desc=[[There's something wrong with Quetz'lun, the wind serpent goddess. What it is exactly I cannot sense, but I do know that her altar has been overrun with powerful creatures. I'm going to send you there on the back of one of my children, which you saved. The two of you will move swiftly and with great stealth to uncover what has become of Quetz'lun. My child will see you safely back to me. Just keep your eyes open. When you are ready, ask and I will call one of my kittens for you.]],logDesc=[[Har'koa has asked you to determine what has happened to Quetz'lun. Speak to her to be able to ride one of her children stealthily into the Altar of Quetz'lun. Return to her at the Altar of Har'koa once you have done so.]]}
DB[12666]={id=12666,zoneId=66,name=[[Preparations for the Underworld]],level=77,minLevel=74,giver=[[Har'koa]],giverType=[[NPC]],giverId=28401,ender=[[Har'koa]],enderType=[[NPC]],enderId=28401,prevId=12665,rewardNextId=12667,wowhead=[[https://www.wowhead.com/wotlk/quest=12666]],image=[[assets/images/quests/placeholder.png]],desc=[[Quetz'lun may be dead, but I can still feel her spirit lingering in the underworld at the altar. We have to find a way to get you to her. Luckily for us, I just happen to have a supply of former supplicants at hand who are no longer in need of their sacred adornments. Both my subduers and claws are likely to still be wearing them. Bring the adornments to me and I'll draw upon their energy to enable you to cross over into Quetz'lun's underworld nightmare.]],logDesc=[[Har'koa wants you to collect 8 Sacred Adornments. Deliver them to her at the Altar of Har'koa.]]}
DB[12667]={id=12667,zoneId=66,name=[[Seek the Wind Serpent Goddess]],level=77,minLevel=74,giver=[[Har'koa]],giverType=[[NPC]],giverId=28401,ender=[[Quetz'lun's Spirit]],enderType=[[NPC]],enderId=28030,prevId=12666,rewardNextId=12672,wowhead=[[https://www.wowhead.com/wotlk/quest=12667]],image=[[assets/images/quests/placeholder.png]],desc=[[You are prepared, but I'm not certain that you're ready for what is to come. When you cross back over into Quetz'lun's altar area, you will enter the realm of the dead. From what I can feel of it, it's not going to be pleasant. Try not to be distracted by what you see in there. Simply head for the altar building and seek out Quetz'lun's Spirit.]],logDesc=[[Seek Quetz'lun's Spirit at the Altar of Quetz'lun.]]}
DB[12668]={id=12668,zoneId=66,name=[[Foundation for Revenge]],level=77,minLevel=74,giver=[[Quetz'lun's Spirit]],giverType=[[NPC]],giverId=28030,ender=[[Quetz'lun's Spirit]],enderType=[[NPC]],enderId=28030,prevId=12672,rewardNextId=12674,wowhead=[[https://www.wowhead.com/wotlk/quest=12668]],image=[[assets/images/quests/placeholder.png]],desc=[[I have something special planned for my favorite high priests. But first you get to prove yourself in laying the foundation for my revenge. You do still want to live, yes? As you have seen, my devotees are enjoying their stay here, but now it's time for them to make final restitution. Do me the smallest of favors if you would, $N. Lure them near my soul fonts and then put an end to their existences. They taste so delicious, and their sacrifice will not go in vain, I can assure you.]],logDesc=[[Quetz'lun's Spirit has tasked you with the destruction of 12 trolls, either Quetz'lun Worshippers or Serpent-Touched Berserkers, near her Soul Fonts. Only after you have accomplished this should you return to her at the Altar of Quetz'lun.]]}
DB[12669]={id=12669,zoneId=66,name=[[So Far, So Bad]],level=75,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12661,rewardNextId=12677,wowhead=[[https://www.wowhead.com/wotlk/quest=12669]],image=[[assets/images/quests/placeholder.png]],desc=[[Everything you've reported is consistent with what we know. Learning of Drakuru and earning his trust will lay the groundwork for your future missions. Return to him and do as he says. Do whatever you must to appear sincere, $n. A great deal is riding upon your performance. This time I'm adding an additional assignment: While you're in the field, pour this additive into their blight cauldrons. It should neutralize the scourging agent and render the batch useless.]],logDesc=[[Stefan at Ebon Watch wants you to return to Drakuru and complete any tasks he has for you. While at the Reliquary of Pain, you are to use the Diluting Additive on 5 Blight Cauldrons. If you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]],choiceRewards={{id=39810,qty=1},{id=39871,qty=1},{id=39872,qty=1},{id=39874,qty=1}}}
DB[12670]={id=12670,name=[[The Scarlet Harvest]],name_loc=[[La cosecha Escarlata]],level=55,minLevel=55,giver=[[Scourge Commander Thalanor]],giver_loc=[[Comandante de la Plaga Thalanor]],giverType=[[NPC]],giverId=28510,ender=[[Prince Valanar]],ender_loc=[[Príncipe Valanar]],enderType=[[NPC]],enderId=28377,prevId=12850,rewardNextId=12678,poiX=2371,poiY=-5701,wowhead=[[https://www.wowhead.com/wotlk/quest=12670]],image=[[assets/images/quests/placeholder.png]],desc=[[Below Acherus stands Death's Breach, the staging point for our assault upon the Scarlet Crusade. You are to ride one of my Scourge gryphons, located on either side of this platform, and report to Prince Valanar. Do as he says and you may live to see these lands fall before us.]],logDesc=[[Report to Prince Valanar at Death's Breach.]]}
DB[12671]={id=12671,zoneId=3711,name=[[Reconnaissance Flight]],level=77,minLevel=77,giver=[[Pilot Vic]],giverType=[[NPC]],giverId=28746,ender=[[Pilot Vic]],enderType=[[NPC]],enderId=28746,prevId=12699,wowhead=[[https://www.wowhead.com/wotlk/quest=12671]],image=[[assets/images/quests/placeholder.png]],desc=[[It's about time we had planes up and running in this place.  The professor's been asking me to check out a strange weather pattern coming from the northeast. Thing is, I'm going to need a co-pilot if we're going into uncharted territory.  No way in hell I'm heading out there alone. What do you say, $g tough-guy : hotshot;?  You might learn a thing or two.  And once you learn to deal with the northern winds... you can pretty much fly anywhere.]],logDesc=[[Help Pilot Vic complete the Reconnaissance Flight.]]}
DB[12672]={id=12672,zoneId=66,name=[[Setting the Stage]],level=77,minLevel=74,giver=[[Quetz'lun's Spirit]],giverType=[[NPC]],giverId=28030,ender=[[Quetz'lun's Spirit]],enderType=[[NPC]],enderId=28030,prevId=12667,rewardNextId=12668,wowhead=[[https://www.wowhead.com/wotlk/quest=12672]],image=[[assets/images/quests/placeholder.png]],desc=[[I will give you a chance at continued existence. There are fragments of the power that fueled my curse scattered about the altar grounds. It is my desire that you collect some of them for me. Not so many that the curse will be lifted, but enough that I will be able to eventually make use of them to exact revenge upon my prophet. Go, insect. Run and do my bidding before I change my mind about letting you live.]],logDesc=[[Quetz'lun's Spirit has demanded that you collect 10 Underworld Power Fragments. Return to her at the Altar of Quetz'lun only when you have done so.]]}
DB[12673]={id=12673,zoneId=66,name=[[It Rolls Downhill]],level=75,minLevel=74,giver=[[Overlord Drakuru]],giverType=[[NPC]],giverId=28503,ender=[[Overlord Drakuru]],enderType=[[NPC]],enderId=28503,prevId=-12669,wowhead=[[https://www.wowhead.com/wotlk/quest=12673]],image=[[assets/images/quests/placeholder.png]],desc=[[If ya ever gonna be worthy of da Lich King's gifts, ya must learn ta be a great leader - one who be commandin' respect! I got a task dat gonna refine your command skills, mon.... Summa my minions be trained ta harvest blight crystals from da land below, but dey be lazy and slow. You gonna be in charge o' dem, mon. Take dis scepter and teach 'em how to get da job done. When dey be under your control, make 'em harvest dem crystals!]],logDesc=[[Overlord Drakuru in Voltarus wants you to use the Scepter of Suggestion on the Blight Geists and then order them to harvest 7 Blight Crystals.]]}
DB[12674]={id=12674,zoneId=66,name=[[Hell Hath a Fury]],level=77,minLevel=74,giver=[[Quetz'lun's Spirit]],giverType=[[NPC]],giverId=28030,ender=[[Quetz'lun's Spirit]],enderType=[[NPC]],enderId=28030,prevId=12668,rewardNextId=12675,wowhead=[[https://www.wowhead.com/wotlk/quest=12674]],image=[[assets/images/quests/placeholder.png]],desc=[[It is now time for you to punish my three high priests: Mu'funu, Tua-Tua, and Hawinni. You'll find them spread around the altar grounds. Take this hexxing stick. I've empowered it with my rage and indignation. I'm sure that it will prove potent. Just use it and proceed to destroy them. The hex will take care of the rest. <Quetz'lun displays a toothy grin.> Succeed and I may let you go. Fail and die.]],logDesc=[[Quetz'lun's Spirit at the Altar of Quetz'lun wants you to use Quetz'lun's Hexxing Stick upon High Priest Mu'funu, High Priestess Tua-Tua, and High Priest Hawinni. Once you have done this, slay them.]],choiceRewards={{id=39791,qty=1},{id=39859,qty=1},{id=39839,qty=1},{id=39841,qty=1}}}
DB[12675]={id=12675,zoneId=66,name=[[One Last Thing]],level=77,minLevel=74,giver=[[Quetz'lun's Spirit]],giverType=[[NPC]],giverId=28030,ender=[[Har'koa]],enderType=[[NPC]],enderId=28401,prevId=12674,rewardNextId=12684,wowhead=[[https://www.wowhead.com/wotlk/quest=12675]],image=[[assets/images/quests/placeholder.png]],desc=[[There is one last thing that is needed to enact the final revenge against my prophet. The power fragments you collected must be imbued with a portion of a living gods' spirit. You're going to need to beseech Har'koa for some of hers. Once you've done that, when you return here, you will not come to the underworld. Instead, you will return to the physical world of my altar. My children and guardians will no longer attack you, and you'll be able to get to my prophet without having to worry about them.]],logDesc=[[Deliver the Underworld Power Fragments to Har'koa and beseech her for a portion of her spirit. You will still find her at the Altar of Har'koa.]]}
DB[12676]={id=12676,zoneId=66,name=[[Sabotage]],level=75,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12677,rewardNextId=12713,wowhead=[[https://www.wowhead.com/wotlk/quest=12676]],image=[[assets/images/quests/placeholder.png]],desc=[[While we're working to discover the purpose of these crystals, we need you back in Voltarus doing Drakuru's bidding. Every task you perform successfully gets you closer to him, and brings us that much nearer to knowing his mind. While you're there, I have another mission for you. Drakuru's Scourgewagons pose a significant threat. We need them destroyed.  Make your way to the wagons and activate these charges. Once they're set, get clear! The explosion will expose you if you're too close.]],logDesc=[[Stefan at Ebon Watch wants you to perform another task for Drakuru. Additionally, you are to use the Explosive Charges on 5 Scourgewagons at the  Reliquary of Pain. If you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]],choiceRewards={{id=39811,qty=1},{id=39873,qty=1},{id=39875,qty=1},{id=39877,qty=1}}}
DB[12677]={id=12677,zoneId=66,name=[[Hazardous Materials]],level=75,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12669,rewardNextId=12676,wowhead=[[https://www.wowhead.com/wotlk/quest=12677]],image=[[assets/images/quests/placeholder.png]],desc=[[Blight crystals?! What could this scumbag Drakuru be up to? Clearly, he's working on something significant. Continue to do his bidding and perhaps once he's more familiar with you he'll reveal his plans. In the meantime, we need to have a look at these crystals. While you're in Voltarus, try to get some samples of the harvested crystals when no one's looking. Be alert! Handling those crystals can trigger your disguise to fail.]],logDesc=[[Stefan at Ebon Watch wants you to go to Voltarus and complete any tasks Drakuru has for you. While there, you are to steal 5 Harvested Blight Crystals. If you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]]}
DB[12678]={id=12678,name=[[If Chaos Drives, Let Suffering Hold The Reins]],name_loc=[[Cuando llegue el caos, deja que el sufrimiento tome las riendas]],level=55,minLevel=55,giver=[[Prince Valanar]],giver_loc=[[Príncipe Valanar]],giverType=[[NPC]],giverId=28377,ender=[[Prince Valanar]],ender_loc=[[Príncipe Valanar]],enderType=[[NPC]],enderId=28377,prevId=12670,poiX=2370,poiY=-5923,wowhead=[[https://www.wowhead.com/wotlk/quest=12678]],image=[[assets/images/quests/placeholder.png]],desc=[[They make their stand now, outside of Death's Breach, futilely attempting to push us back in hopes of saving their horses, mines, lumber and citizens. This will be your first lesson in Scourge warfare: TERROR! Go to the front lines, south of here, and destroy Scarlet Crusaders. Leave their corpses so that we may utilize them for the death march. But most importantly: kill the fleeing villagers. Soldiers dying are an affordance, but villagers? That is what strikes fear into the hearts of man.]],logDesc=[[Prince Valanar at Death's Breach commands you to slay 10 Scarlet Crusaders or Scarlet Peasants and 10 Citizens of Havenshire.]],rewards={{id=38671,qty=1}}}
DB[12679]={id=12679,name=[[Tonight We Dine In Havenshire]],name_loc=[[Esta noche cenamos en Villa Refugio]],level=55,minLevel=55,giver=[[Orithos the Sky Darkener]],giver_loc=[[Orithos el Ensombrecedor del cielo]],giverType=[[NPC]],giverId=28647,ender=[[Orithos the Sky Darkener]],ender_loc=[[Orithos el Ensombrecedor del cielo]],enderType=[[NPC]],enderId=28647,prevId=12670,nextId=12697,exGroup=-12733,poiX=2001,poiY=-5894,wowhead=[[https://www.wowhead.com/wotlk/quest=12679]],image=[[assets/images/quests/placeholder.png]],desc=[[The Sky Darkeners are mindless constructs with one purpose: KILL! Specifically, they are aiming to kill any man or woman that they see fleeing Havenshire for the safety of New Avalon. We certainly can't allow those cowards to make it to safety and then take up arms against us! There is one slight problem. They use saronite arrows for maximum range and damage. Saronite, however, is a metal only found in Northrend, so supplies are limited! Retrieve those arrows for me and I will reward you handsomely.]],logDesc=[[Orithos the Sky Darkener at Death's Breach wants you to recover 15 Saronite Arrows.]],choiceRewards={{id=39320,qty=1},{id=38664,qty=1},{id=39322,qty=1}}}
DB[12680]={id=12680,name=[[Grand Theft Palomino]],name_loc=[[El gran robo de Palomino]],level=55,minLevel=55,giver=[[Salanar the Horseman]],giver_loc=[[Salanar el Jinete]],giverType=[[NPC]],giverId=28653,ender=[[Salanar the Horseman]],ender_loc=[[Salanar el Jinete]],enderType=[[NPC]],enderId=28653,prevId=12670,rewardNextId=12687,poiX=2335,poiY=-5683,wowhead=[[https://www.wowhead.com/wotlk/quest=12680]],image=[[assets/images/quests/placeholder.png]],desc=[[How fortuitous it is that the Crusade has a stable full of horses a mere stone's throw from this post. Though they guard it tenaciously, an enterprising young death knight could break through their defenses and take what is rightfully $g his:hers;! Once you acquire a horse from the Havenshire Stables, return it to me and I will see what can be done about transforming it into a proper deathcharger. Remember, $N, it's only stealing if you're caught. Watch out for that deranged stable master, Kitrik!]],logDesc=[[Salanar the Horseman asks that you steal a horse from the Havenshire Stables and return it to him at Death's Breach.]]}
DB[12681]={id=12681,zoneId=3711,name=[[Reagent Agent]],level=77,minLevel=76,giver=[[Colvin Norrington]],giverType=[[NPC]],giverId=28771,ender=[[Colvin Norrington]],enderType=[[NPC]],enderId=28771,prevId=12603,wowhead=[[https://www.wowhead.com/wotlk/quest=12681]],image=[[assets/images/quests/placeholder.png]],desc=[[That Archmage Pentarus, back in Dalaran, will be expecting us to return with all kinds of reagents and talismans. It seems the locals are fond of animal parts. Twisted claws from the goretalon rocs are among their favorite. It's not my place to say whether the rumors are true or not, but I've a feeling there's something here. The rocs live in the Bonefields off to the northeast, where they feed on the corpses of old mammoths. Will you help me gather talons for the archmage's research?]],logDesc=[[Bring 5 Twisted Roc Claws to Colvin Norrington at Dorian's Outpost.]],choiceRewards={{id=39368,qty=1},{id=39413,qty=1},{id=39445,qty=1},{id=39463,qty=1}}}
DB[12682]={id=12682,zoneId=3711,name=[[Uncharted Territory (DEPRECATED)]],level=76,minLevel=75,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12682]],image=[[assets/images/quests/placeholder.png]],desc=[[Not all of us in this expedition are here to hunt the biggest and rarest game.  Some of us actually have serious work to do. The mere existence of this place boggles the mind -- a tropical paradise in the middle of Northrend.  I wouldn't be a scholar worthy of the name if I didn't put some effort into trying to understand this place. Take these]]}
DB[12683]={id=12683,zoneId=3711,name=[[Burning to Help]],level=77,minLevel=76,giver=[[Colvin Norrington]],giverType=[[NPC]],giverId=28771,ender=[[Colvin Norrington]],enderType=[[NPC]],enderId=28771,wowhead=[[https://www.wowhead.com/wotlk/quest=12683]],image=[[assets/images/quests/placeholder.png]],desc=[[There's no more caustic material in all of the basin than bittertide hydra sputum. I've got special containers to collect just such a thing for Archmage Pentarus' studies. Now all I need is a brave, um... collector. You look like a hardy, adventurous $c. How'd you like to make a bit of money and aid Dalaran's cause at the same time? All you need to do is take this container with you to Bittertide Lake, to the southwest. Engage the hydra and use the container to sample the sputum they shower you with.]],logDesc=[[Colvin Norrington at Dorian's Outpost wants you to take 5 Hydra Sputum Samples and kill 5 Bittertide Hydra.]]}
DB[12684]={id=12684,zoneId=66,name=[[Blood of a Dead God]],level=77,minLevel=74,giver=[[Har'koa]],giverType=[[NPC]],giverId=28401,ender=[[Har'koa]],enderType=[[NPC]],enderId=28401,prevId=12675,wowhead=[[https://www.wowhead.com/wotlk/quest=12684]],image=[[assets/images/quests/placeholder.png]],desc=[[Mam'toth, the god of the mammoths, destroyed himself, and took much of his temple with him, rather than allowing his trolls to gain his power. If I'm to sacrifice a portion of my spirit, I will need something with which to bolster myself. Mam'toth left behind an enormous crater to the northeast, just north of the Altar of Quetz'lun. Within the crater his blood yet lives. Bring it to me.]],logDesc=[[Har'koa has asked you to collect 7 Blood of Mam'toth. Return them to her at the Altar of Har'koa.]]}
DB[12685]={id=12685,zoneId=66,name=[[You Reap What You Sow]],level=77,minLevel=74,giver=[[Har'koa]],giverType=[[NPC]],giverId=28401,ender=[[Witch Doctor Khufu]],enderType=[[NPC]],enderId=28479,prevId=12684,wowhead=[[https://www.wowhead.com/wotlk/quest=12685]],image=[[assets/images/quests/placeholder.png]],desc=[[This is what it has come down to... revenge. <Har'koa sighs.> Take this ritual kit and enact it near Quetz'lun's corpse upon her altar. If everything works properly, her spirit should be drawn into the material world where she will be able to reclaim her power from the prophet. The rest will be up to you, $N. You must slay the prophet in his drained state.]],logDesc=[[Slay the Drained Prophet of Quetz'lun and then inform Witch Doctor Khufu at Zim'Torga.]],choiceRewards={{id=39844,qty=1},{id=39861,qty=1},{id=39793,qty=1},{id=39845,qty=1},{id=39826,qty=1}}}
DB[12686]={id=12686,zoneId=66,name=[[Zero Tolerance]],level=75,minLevel=74,giver=[[Overlord Drakuru]],giverType=[[NPC]],giverId=28503,ender=[[Overlord Drakuru]],enderType=[[NPC]],enderId=28503,prevId=-12677,wowhead=[[https://www.wowhead.com/wotlk/quest=12686]],image=[[assets/images/quests/placeholder.png]],desc=[[Ignorance! Dis be intolerable, mon! My entire batch of blight be useless! Dat mongrel, Darmuk! He be responsible for watchin over da blight. He failed me, mon! Dis be a good lesson for ya, $n. Failure be like a disease dat spreads. Ya gotta catch it and kill it early, before it be killin' you! Take dis scepter. It make my scourged trolls stronger. Use dem ta kill Darmuk. He be lurkin' down below just to da south. Let dat be an example to all, mon. Don't be failin' Drakuru!]],logDesc=[[Drakuru in Voltarus wants you to go to the Reliquary of Pain and use the Scepter of Empowerment on a Servant of Drakuru. You are then to use its abilities to defeat Darmuk.]]}
DB[12687]={id=12687,name=[[Into the Realm of Shadows]],name_loc=[[En el Reino de las Sombras]],level=55,minLevel=55,giver=[[Salanar the Horseman]],giver_loc=[[Salanar el Jinete]],giverType=[[NPC]],giverId=28653,ender=[[Salanar the Horseman]],ender_loc=[[Salanar el Jinete]],enderType=[[NPC]],enderId=28653,prevId=12680,nextId=12697,exGroup=-12733,poiX=2335,poiY=-5683,wowhead=[[https://www.wowhead.com/wotlk/quest=12687]],image=[[assets/images/quests/placeholder.png]],desc=[[The horse you stole has been taken to the Realm of Shadows. It is there that my dark rider will slay the beast and raise it as a deathcharger. Do you think yourself brave enough to enter the Realm of Shadows in pursuit of the deathcharger? If you accept, I will transport you to the shadow world. Once there, seek out a dark rider in the open fields south of us. To emerge victorious you must slay him, overtake his deathcharger and return it to Death's Breach. Issue the Horseman's Call should you succeed.]],logDesc=[[Salanar the Horseman at Death's Breach has challenged you to slay the Dark Rider of Acherus and take his Acherus Deathcharger. Should you succeed, return the Acherus Deathcharger to Death's Breach and use the Horseman's Call to summon Salanar.]],rewards={{id=39208,qty=1}}}
DB[12688]={id=12688,zoneId=3711,name=[[Engineering a Disaster]],level=76,minLevel=76,giver=[[Engineer Helice]],giverType=[[NPC]],giverId=28787,ender=[[Hemet Nesingwary]],enderType=[[NPC]],enderId=27986,wowhead=[[https://www.wowhead.com/wotlk/quest=12688]],image=[[assets/images/quests/placeholder.png]],desc=[[These goblin goons and their minions have decided that they own this pillar and its crystals. I came here to explore the crystals and take samples, but they overpowered me and won't let me return to the camp. If you'll help me fight our way out of here, we can teach these thugs a lesson they'll never forget!]],logDesc=[[Help Engineer Helice escape from Swindlegrin's Dig, then speak with Hemet Nesingwary at the Nesingwary Base Camp.]]}
DB[12689]={id=12689,zoneId=3711,name=[[Hand of the Oracles]],level=77,minLevel=76,giver=[[Jaloot]],giverType=[[NPC]],giverId=28667,ender=[[Jaloot]],enderType=[[NPC]],enderId=28667,prevId=12581,exGroup=12582,wowhead=[[https://www.wowhead.com/wotlk/quest=12689]],image=[[assets/images/quests/placeholder.png]]}
DB[12690]={id=12690,zoneId=66,name=[[Fuel for the Fire]],level=75,minLevel=74,giver=[[Overlord Drakuru]],giverType=[[NPC]],giverId=28503,ender=[[Overlord Drakuru]],enderType=[[NPC]],enderId=28503,prevId=-12676,rewardNextId=12710,wowhead=[[https://www.wowhead.com/wotlk/quest=12690]],image=[[assets/images/quests/placeholder.png]],desc=[[It be time we start our march to Gundrak, mon. It be time for me ta turn ya loose on dem trolls! Dey breached our wall and put a whole army just north of us. Hahaha! Dey be fuel for da fire, mon! We gunna take da chieftiains an' kill da rest! It all be part of my master plan.... You take dis scepter and go command my abominations. Bring 'em to da Drakkari army and kill em all! When da chieftains come, my pet Shalewing gunna snatch 'em up and bring 'em here to me.]],logDesc=[[Drakuru in Voltarus wants you to use the Scepter of Command on Bloated Abominations and then use their abilities at the Frigid Breach to kill 60 Drakkari Skullcrushers and lure out 3 Drakkari Chieftains. Chieftains will appear when enough Skullcrushers have been slain.]]}
DB[12691]={id=12691,zoneId=3711,name=[[A Timeworn Coffer]],level=78,minLevel=77,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12691]],image=[[assets/images/quests/placeholder.png]],desc=[[The stone coffer appears to be locked.  It appears that a key fits inside a large stone keyhole. Perhaps one of the guardians in the vicinity has this key in its possession.]],logDesc=[[Obtain a Huge Stone Key from the nearby Sholazar Guardians and bring it to the Timeworn Coffer at the Maker's Overlook.]],choiceRewards={{id=39348,qty=1},{id=39402,qty=1},{id=39438,qty=1},{id=39508,qty=1}}}
DB[12692]={id=12692,zoneId=3711,name=[[Return of the Lich Hunter]],level=77,minLevel=76,giver=[[Zepik the Gorloc Hunter]],giverType=[[NPC]],giverId=28668,ender=[[Elder Harkek]],enderType=[[NPC]],enderId=28138,wowhead=[[https://www.wowhead.com/wotlk/quest=12692]],image=[[assets/images/quests/placeholder.png]],desc=[[Okay, I going back to Frenzyheart Hill to make sure all Frenzyheart know what you done for wolvar and for Zepik. You great hunter and they dumb to think you not. Go back to hill and talk to Elder Harkek... I make sure he knows you not traitor before any other Frenzyheart. Thank you, Lich Hunter.]],logDesc=[[Return to Frenzyheart Hill and speak to Elder Harkek.]]}
DB[12693]={id=12693,name=[[Wolvar Faction Choice Tracker]],name_loc=[[Wolvar Faction Choice Tracker]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12693]],image=[[assets/images/quests/placeholder.png]]}
DB[12694]={id=12694,name=[[Oracle Faction Choice Tracker]],name_loc=[[Oracle Faction Choice Tracker]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12694]],image=[[assets/images/quests/placeholder.png]]}
DB[12695]={id=12695,zoneId=3711,name=[[Return of the Friendly Dryskin]],level=77,minLevel=76,giver=[[Jaloot]],giverType=[[NPC]],giverId=28667,ender=[[High-Oracle Soo-say]],enderType=[[NPC]],enderId=28027,wowhead=[[https://www.wowhead.com/wotlk/quest=12695]],image=[[assets/images/quests/placeholder.png]],desc=[[Yay! Soo-say probably worrying about us! Maybe you go back to town and tell him everything okay? Yeah, go tell Soo-say. I going grab shiny ball thing from dead lich guy - I meet you there! Go go! I meet you there!]],logDesc=[[Return to Rainspeaker Canopy and speak to High-Oracle Soo-say.]]}
DB[12696]={id=12696,zoneId=3711,name=[[Aerial Surveillance]],level=77,minLevel=77,giver=[[Professor Calvert]],giverType=[[NPC]],giverId=28266,ender=[[Pilot Vic]],enderType=[[NPC]],enderId=28746,prevId=12523,wowhead=[[https://www.wowhead.com/wotlk/quest=12696]],image=[[assets/images/quests/placeholder.png]],desc=[[You did a good job helping Wes with getting that flying machine back up and running. If you'd like to help us further, there is an unusual weather pattern coming in from the northeast.  I have a pilot ready to work for me, but I'm afraid he needs a copilot. If you think you're up to it, you can take the flight to Lakeside Landing.  Tell Vic I sent you.]],logDesc=[[Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there.]]}
DB[12697]={id=12697,name=[[Gothik the Harvester]],name_loc=[[Gothik el Cosechador]],level=55,minLevel=55,giver=[[Prince Valanar]],giver_loc=[[Príncipe Valanar]],giverType=[[NPC]],giverId=28377,ender=[[Gothik the Harvester]],ender_loc=[[Gothik el Cosechador]],enderType=[[NPC]],enderId=28658,rewardNextId=12698,poiX=2349,poiY=-5758,wowhead=[[https://www.wowhead.com/wotlk/quest=12697]],image=[[assets/images/quests/placeholder.png]],desc=[[CHAOS, $N! The Crusade is in a frenzy. They have diverted all forces outside of New Avalon to set up a blockade at Light's Point, east of here. They are desperately trying to strip the Havenshire Mine of all resources and load the cargo aboard the frigates they have docked on the coast. Let's stir things up a bit, shall we? Gothik the Harvester, grand necromancer of the Lich King, has graced us with his presence. He has a gift he'd like to bestow upon the Scarlet Crusade. Seek him out.]],logDesc=[[Speak with Gothik the Harvester at Death's Breach.]]}
DB[12698]={id=12698,name=[[The Gift That Keeps On Giving]],name_loc=[[La ofrenda que sigue dando]],level=55,minLevel=55,giver=[[Gothik the Harvester]],giver_loc=[[Gothik el Cosechador]],giverType=[[NPC]],giverId=28658,ender=[[Gothik the Harvester]],ender_loc=[[Gothik el Cosechador]],enderType=[[NPC]],enderId=28658,prevId=12697,rewardNextId=12700,poiX=2349,poiY=-5758,wowhead=[[https://www.wowhead.com/wotlk/quest=12698]],image=[[assets/images/quests/placeholder.png]],desc=[[I have come from the frozen heart of Naxxramas to feast on souls and deliver a vicious thrashing upon our sworn enemies - and I'm all out of souls. This device I am about to give to you is a portable plague spreader. Take it east, to the Havenshire Mines, and unleash it near the Scarlet miners working inside. Use it to turn the miners into ghouls and return to me when you have a small army at your side. I have saved a special place for them in the vacuum cleaner of souls!]],logDesc=[[Gothik the Harvester at Death's Breach has given you the Gift of the Harvester to use on Scarlet Miners. Create 5 Scarlet Ghouls with the device and return the ghouls to Gothik.]],rewards={{id=38674,qty=1}}}
DB[12699]={id=12699,zoneId=3711,name=[[An Embarassing Incident]],level=77,minLevel=77,giver=[[Pilot Vic]],giverType=[[NPC]],giverId=28746,ender=[[Pilot Vic]],enderType=[[NPC]],enderId=28746,rewardNextId=12671,wowhead=[[https://www.wowhead.com/wotlk/quest=12699]],image=[[assets/images/quests/placeholder.png]],desc=[[There's one little problem we have to solve before we head out.  You see, I can't seem to find the keys to my flying machine. I've looked pretty much everywhere for them... maybe you can give me a hand.  Only place I haven't looked yet is inside the lake. I'll even give you my very own air tank.  It's almost empty, but it's got a couple of hits left.]],logDesc=[[Look for Vic's Keys inside the lake at River's Heart.]]}
DB[12700]={id=12700,name=[[An Attack Of Opportunity]],name_loc=[[Un ataque de oportunidad]],level=55,minLevel=55,giver=[[Gothik the Harvester]],giver_loc=[[Gothik el Cosechador]],giverType=[[NPC]],giverId=28658,ender=[[Prince Valanar]],ender_loc=[[Príncipe Valanar]],enderType=[[NPC]],enderId=28377,prevId=12698,rewardNextId=12701,poiX=2371,poiY=-5701,wowhead=[[https://www.wowhead.com/wotlk/quest=12700]],image=[[assets/images/quests/placeholder.png]],desc=[[Only the Scarlet forces at New Avalon and Light's Point challenge us! The time to attack the Scarlet fleet at Light's Point has come. The diversion at the mine has caused chaos amidst their ranks. They are frantically working to clear the area and return to their ships. The time is ripe! Prince Valanar is seizing this opportunity to finish off the Scarlet fleet. Report to him at once!]],logDesc=[[Speak with Prince Valanar at Death's Breach.]]}
DB[12701]={id=12701,name=[[Massacre At Light's Point]],name_loc=[[Masacre en la Punta de la Luz]],level=55,minLevel=55,giver=[[Prince Valanar]],giver_loc=[[Príncipe Valanar]],giverType=[[NPC]],giverId=28377,ender=[[Prince Valanar]],ender_loc=[[Príncipe Valanar]],enderType=[[NPC]],enderId=28377,prevId=12700,rewardNextId=12706,poiX=2196,poiY=-6154,wowhead=[[https://www.wowhead.com/wotlk/quest=12701]],image=[[assets/images/quests/placeholder.png]],desc=[[In their haste the Crusade will make one fatal error: forgetting to check the mine cars. You are to return to Havenshire Mine, east of here, and locate the mine car that my minions have planted near the outhouse. Climb inside the mine car and a Scarlet miner will unwittingly see to it that you are placed safely behind enemy lines. Once aboard one of their ships, use the cannons against them! SLAUGHTER THEM ALL! Call the Scourge gryphon from the cannon when you are ready to return.]],logDesc=[[Prince Valanar at Death's Breach has commanded you to slaughter 100 Scarlet Defenders.]],rewards={{id=38666,qty=1}}}
DB[12702]={id=12702,zoneId=3711,name=[[Chicken Party!]],level=77,minLevel=76,giver=[[Elder Harkek]],giverType=[[NPC]],giverId=28138,ender=[[Elder Harkek]],enderType=[[NPC]],enderId=28138,prevId=12692,wowhead=[[https://www.wowhead.com/wotlk/quest=12702]],image=[[assets/images/quests/placeholder.png]],desc=[[I bet you not guess what happen again. Nope, not Goregek or chickens. Okay, I lie. Goregek let chickens out again. Dumb Goregek and rumbly belly. Let me know if you need help from any of the hunters... they around here somewhere.]],logDesc=[[Capture 12 Chicken Escapees for Elder Harkek at Frenzyheart Hill.]]}
DB[12703]={id=12703,zoneId=3711,name=[[Kartak's Rampage]],level=78,minLevel=76,giver=[[Vekgar]],giverType=[[NPC]],giverId=29146,ender=[[Shaman Jakjek]],enderType=[[NPC]],enderId=28106,prevId=12692,exGroup=12703,wowhead=[[https://www.wowhead.com/wotlk/quest=12703]],image=[[assets/images/quests/placeholder.png]],desc=[[You the great Lich Hunter, eh? Good to have such strong Frenzyheart ally for battle. Maybe you strong enough to call Kartak even. Big battle at Kartak's Hold to southwest.  Go kill spark big-tongues until you get good bit of Oracle Blood. Bring blood to altar in Kartak's Hold to call Kartak for delicious feast of big-tongue. Kartak take your body if you worthy... with Kartak's powers, you slaughter more big-tongues than even best dreams. Go kill lots, hunter!]],logDesc=[[Bring a pure sample of Oracle Blood to the Altar of Kartak to summon Kartak. With the aid of Kartak's shared powers, slaughter 50 of the nearby Sparktouched Gorlocs for Shaman Jakjek in Kartak's Hold.]]}
DB[12704]={id=12704,zoneId=3711,name=[[Appeasing the Great Rain Stone]],level=77,minLevel=76,giver=[[High-Oracle Soo-say]],giverType=[[NPC]],giverId=28027,ender=[[High-Oracle Soo-say]],enderType=[[NPC]],enderId=28027,prevId=12695,wowhead=[[https://www.wowhead.com/wotlk/quest=12704]],image=[[assets/images/quests/placeholder.png]],desc=[[Since mosswalker been attacked I worried maybe we not good to Great Rain Stone... we maybe too greedy. We need more treasures to offer! You good at finding shinies last time... maybe you go look more around village for shinies? You maybe need one of good Rainspeakers for help. Just tell us who.]],logDesc=[[High-Oracle Soo-say in Rainspeaker Canopy wants you to take a companion to dig up and collect 6 Shiny Treasures. Be sure to speak to High-Oracle Soo-say in Rainspeaker Canopy about securing the aid of one of your previous companions.]]}
DB[12705]={id=12705,zoneId=3711,name=[[Will of the Titans]],level=78,minLevel=76,giver=[[Oracle Soo-dow]],giverType=[[NPC]],giverId=29149,ender=[[Lightningcaller Soo-met]],enderType=[[NPC]],enderId=28107,prevId=12695,exGroup=12761,wowhead=[[https://www.wowhead.com/wotlk/quest=12705]],image=[[assets/images/quests/placeholder.png]],desc=[[Puppy-men been attacking Sparktouched... we need fight or they just attack other Oracles too. You been good friend to us, so maybe we allow you special honor. Great Ones left protector long time ago for shrines... it here still, but it not know something wrong til shrines messed with. Puppy-men down there have bad crystals for making trouble... bring a bad crystal to Lightning Shrine so Soo-holu know to help. Don't be scared if Soo-holu take your body... he very powerful, so he keep you safe.]],logDesc=[[Obtain a Tainted Crystal from the wolvar near Sparktouched Haven and bring it to the Great Lightning Stone to call Soo-holu. With the aid of Soo-holu's shared powers, kill 50 of the nearby Frenzyheart wolvar, then return to Lightningcaller Soo-met near the Great Lightning Stone.]]}
DB[12706]={id=12706,name=[[Victory At Death's Breach!]],name_loc=[[¡Victoria en la Brecha de la Muerte!]],level=55,minLevel=55,giver=[[Prince Valanar]],giver_loc=[[Príncipe Valanar]],giverType=[[NPC]],giverId=28377,ender=[[Highlord Darion Mograine]],ender_loc=[[Alto señor Darion Mograine]],enderType=[[NPC]],enderId=28444,prevId=12701,rewardNextId=12714,poiX=2461,poiY=-5593,wowhead=[[https://www.wowhead.com/wotlk/quest=12706]],image=[[assets/images/quests/placeholder.png]],desc=[[<Prince Valanar hands you a sealed scroll.> This is the full report of our victory at Death's Breach. You are to deliver this to Highlord Mograine - inside Acherus. I have made sure to include your heroics in the report. Mograine will undoubtedly reward you greatly for this victory, $N. Go now!]],logDesc=[[Deliver Prince Valanar's Report to Highlord Darion Mograine in Acherus: The Ebon Hold.]],rewards={{id=38669,qty=1}}}
DB[12707]={id=12707,zoneId=66,name=[[Wooly Justice]],level=77,minLevel=74,giver=[[Scalper Ahunae]],giverType=[[NPC]],giverId=28484,ender=[[Scalper Ahunae]],enderType=[[NPC]],enderId=28484,prevId=12685,wowhead=[[https://www.wowhead.com/wotlk/quest=12707]],image=[[assets/images/quests/placeholder.png]],desc=[[Ahunae hear about your trip to Mam'toth Crater, mon. The children of Mam'toth are enraged and cry out for justice! Follow the avenue northeast up the steps to the next tier of Zul'Drak. On your right you will find what's left of the Altar of Mam'toth. When you get there, flash this Medallion of Mam'toth in front of the eyes of one of the enraged mammoths. It'll calm down for a little while, letting you hop on its back. Ride it around, trampling all of the Mam'toth disciples that you can find!]],logDesc=[[Scalper Ahunae at Zim'Torga wants you to use the Medallion of Mam'toth to calm and ride an Enraged Mammoth. You are then to trample 12 Mam'toth Disciples to death.]],choiceRewards={{id=39770,qty=1},{id=39833,qty=1},{id=39776,qty=1},{id=39778,qty=1},{id=39818,qty=1}}}
DB[12708]={id=12708,zoneId=66,name=[[Enchanted Tiki Warriors]],level=77,minLevel=74,giver=[[Element-Tamer Dagoda]],giverType=[[NPC]],giverId=28480,ender=[[Element-Tamer Dagoda]],enderType=[[NPC]],enderId=28480,prevId=12685,wowhead=[[https://www.wowhead.com/wotlk/quest=12708]],image=[[assets/images/quests/placeholder.png]],desc=[[I know that you're headed up to the Zol'Maz Stronghold to the northeast, $c. While you're there, I need you to deal with the warlord's special guardians. The enchanted tiki warriors, as they're called, represent a very real threat. If the Drakkari were to mass produce them, we'd quickly be overrun. Let's you and I demonstrate that they're not worth the effort to create, shall we?]],logDesc=[[Element-Tamer Dagoda at Zim'Torga has asked you to destroy 12 Enchanted Tiki Warriors.]]}
DB[12709]={id=12709,zoneId=66,name=[[Hexed Caches]],level=77,minLevel=74,giver=[[Chronicler To'kini]],giverType=[[NPC]],giverId=28527,ender=[[Chronicler To'kini]],enderType=[[NPC]],enderId=28527,prevId=12685,wowhead=[[https://www.wowhead.com/wotlk/quest=12709]],image=[[assets/images/quests/placeholder.png]],desc=[[Pardon me, $N. I'm given to understand that you might be heading northeast up to the Zol'Maz Stronghold. Such a trip presents a great opportunity for us to conclude our Drakkari goods gathering. As I have come to know, the Drakkari warlord is extremely paranoid. He's had all of his caches at the stronghold hexed with dire magic. Rumor has it that his tiki warriors carry the cure, but who can say? If you could find the time to acquire some of those goods, I would be most appreciative.]],logDesc=[[Chronicler To'kini at Zim'Torga has asked you to acquire 12 Zol'Maz Stronghold Caches.]],choiceRewards={{id=39797,qty=1},{id=39863,qty=1},{id=39848,qty=1},{id=39849,qty=1}}}
DB[12710]={id=12710,zoneId=66,name=[[Disclosure]],level=75,minLevel=74,giver=[[Overlord Drakuru]],giverType=[[NPC]],giverId=28503,ender=[[Overlord Drakuru]],enderType=[[NPC]],enderId=28503,prevId=12690,wowhead=[[https://www.wowhead.com/wotlk/quest=12710]],image=[[assets/images/quests/placeholder.png]],desc=[[Ya doin' well, $n. You be provin' dat I got an eye for talent! Now ya see why da Lich King gave me his blessing.... Da time has come for me to reveal my master plan to ya, mon. Now you be seein' how we gunna sweep through da swarms of Drakkari trolls to take our rightful place in da great palace of Gundrak. Take dis scepter, mon. It be a token of my trust in ya. With it, you be able ta access my upper chamber and witness for yourself our secret weapons.]],logDesc=[[Drakuru in Voltarus wants you to take the teleporter to his upper chamber.]]}
DB[12711]={id=12711,name=[[Abandoned Mail]],name_loc=[[Mensaje abandonado]],level=55,minLevel=55,giver=[[Abandoned Mail]],giver_loc=[[Correo abandonado]],giverType=[[GO]],giverId=190917,ender=[[Abandoned Mail]],ender_loc=[[Correo abandonado]],enderType=[[GO]],enderId=190917,prevId=12670,poiX=2114,poiY=-5796,wowhead=[[https://www.wowhead.com/wotlk/quest=12711]],image=[[assets/images/quests/placeholder.png]]}
DB[12712]={id=12712,zoneId=66,name=[[The Key of Warlord Zol'Maz]],level=77,minLevel=74,giver=[[Har'koa]],giverType=[[NPC]],giverId=28401,ender=[[Har'koa]],enderType=[[NPC]],enderId=28401,prevId=12685,rewardNextId=12721,wowhead=[[https://www.wowhead.com/wotlk/quest=12712]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, we need a key to unlock the chains of the rhino god, Akali. Even now he is being prepared for the slaughter. The Drakkari warlord, Zol'Maz, carries the key. Hearing of your exploits, he has secluded himself and his family at their stronghold up the steps to the northeast. The warlord is strong and you will need help. If you were to combine the tiki, sword and incantation of his family members, you would be able to summon such help as you challenge him before his home's gate.]],logDesc=[[Har'koa at Zim'Torga has asked you to acquire the Key of Warlord Zol'Maz.]]}
DB[12713]={id=12713,zoneId=66,name=[[Betrayal]],level=76,minLevel=74,giver=[[Stefan Vadu]],giverType=[[NPC]],giverId=28518,ender=[[Stefan Vadu]],enderType=[[NPC]],enderId=28518,prevId=12676,wowhead=[[https://www.wowhead.com/wotlk/quest=12713]],image=[[assets/images/quests/placeholder.png]],desc=[[The time has come to end this charade, $n. As valuable as your information has been, we must bring Drakuru down and bring his project to an end before his freaks are unleashed. We've modified your scepter for the job. When the time is right, you will be able to use it on Drakuru's Blightbloods and turn them against him. It's your only hope of defeating him. Fight well.]],logDesc=[[Stefan in Ebon Watch wants you to defeat Drakuru. If you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.]],choiceRewards={{id=39655,qty=1},{id=39653,qty=1},{id=39652,qty=1}}}
DB[12714]={id=12714,name=[[The Will Of The Lich King]],name_loc=[[La voluntad del Rey Exánime]],level=55,minLevel=55,giver=[[Highlord Darion Mograine]],giver_loc=[[Alto señor Darion Mograine]],giverType=[[NPC]],giverId=28444,ender=[[Prince Valanar]],ender_loc=[[Príncipe Valanar]],enderType=[[NPC]],enderId=28907,prevId=12706,rewardNextId=12715,poiX=2315,poiY=-5740,wowhead=[[https://www.wowhead.com/wotlk/quest=12714]],image=[[assets/images/quests/placeholder.png]],desc=[[It is the will of the Lich King that drives us onward, $N. None are more aware of this than death knights. Our very existence is intrinsically tied to his consciousness. Surely you have heard him speak to you - invading your thoughts... Can you hear him now? Perhaps it is too early for you. <Mograine closes his eyes and nods to an unseen host.> Yes, my lord. It will be done. $N, you are to return to Death's Breach and report to Prince Valanar. The Lich King commands it!]],logDesc=[[Return to Death's Breach and report to Prince Valanar.]]}
DB[12715]={id=12715,name=[[The Crypt of Remembrance]],name_loc=[[La Cripta de los Recuerdos]],level=55,minLevel=55,giver=[[Prince Valanar]],giver_loc=[[Príncipe Valanar]],giverType=[[NPC]],giverId=28907,ender=[[Prince Keleseth]],ender_loc=[[Príncipe Keleseth]],enderType=[[NPC]],enderId=28911,prevId=12714,rewardNextId=12719,poiX=1879,poiY=-5765,wowhead=[[https://www.wowhead.com/wotlk/quest=12715]],image=[[assets/images/quests/placeholder.png]],desc=[[The attacks upon the gates of the last Scarlet bastion have begun. Our ghouls are wearing the Crusade's front lines down while we labor to fortify our new forward base, the Crypt of Remembrance. Venture south to the crypt, which borders New Avalon, and report to my dear brother, Prince Keleseth. He will be expecting you. Prepare yourself, $N, for you are about to witness the next stage of Scourge warfare: DOMINATION! Ride now, death knight!]],logDesc=[[Report to Prince Keleseth at the Crypt of Remembrance.]]}
DB[12716]={id=12716,name=[[The Plaguebringer's Request]],name_loc=[[La solicitud del Pesteador]],level=55,minLevel=55,giver=[[Noth the Plaguebringer]],giver_loc=[[Noth el Pesteador]],giverType=[[NPC]],giverId=28919,ender=[[Noth the Plaguebringer]],ender_loc=[[Noth el Pesteador]],enderType=[[NPC]],enderId=28919,rewardNextId=12717,poiX=1784,poiY=-5878,wowhead=[[https://www.wowhead.com/wotlk/quest=12716]],image=[[assets/images/quests/placeholder.png]],desc=[[Look at this pumpkin patch! Notice anything missing? Of course you don't, because you're a moron! Your brain was probably the first thing to die. <Noth sighs.> I have been commanded to put together a plague cauldron. You will help me. Directly inside the gate of New Avalon is the inn. Enter the inn and steal an empty cauldron. Then go to the forge, also near the gate, and steal some iron chains. Bring those back to me along with 10 Crusader skulls. Do I need to tell you where to get those too?]],logDesc=[[Noth the Plaguebringer has requested that you bring him 1 Empty Cauldron, 1 Iron Chain and 10 Crusader Skulls.]],rewards={{id=38668,qty=1}}}
DB[12717]={id=12717,name=[[Noth's Special Brew]],name_loc=[[El brebaje especial de Noth]],level=55,minLevel=55,giver=[[Noth the Plaguebringer]],giver_loc=[[Noth el Pesteador]],giverType=[[NPC]],giverId=28919,ender=[[Plague Cauldron]],ender_loc=[[Caldera de peste]],enderType=[[GO]],enderId=190936,prevId=12716,poiX=1993,poiY=-5826,wowhead=[[https://www.wowhead.com/wotlk/quest=12717]],image=[[assets/images/quests/placeholder.png]],desc=[[The cauldron is ready to begin spewing its foul corruption across the land! Now, death knight, a brief lesson in plague cauldrons. The gas that the cauldron emits is deadly to the living, but empowers Scourge. As with all Scourge creations, it feeds off of death and grows stronger the longer it feeds. Take these Crusader skulls and drop them in the cauldron. You will be quite happy with the results.]],logDesc=[[Place the Pile of Crusader Skulls inside the Plague Cauldron.]],rewards={{id=39327,qty=5}}}
DB[12718]={id=12718,name=[[More Skulls For Brew]],name_loc=[[Más calaveras para brebaje]],level=55,minLevel=55,giver=[[Plague Cauldron]],giver_loc=[[Caldera de peste]],giverType=[[GO]],giverId=190936,ender=[[Plague Cauldron]],ender_loc=[[Caldera de peste]],enderType=[[GO]],enderId=190936,prevId=12717,poiX=1655,poiY=-6046,wowhead=[[https://www.wowhead.com/wotlk/quest=12718]],image=[[assets/images/quests/placeholder.png]],rewards={{id=39327,qty=5}}}
DB[12719]={id=12719,name=[[Nowhere To Run And Nowhere To Hide]],name_loc=[[No hay escapatoria]],level=55,minLevel=55,giver=[[Prince Keleseth]],giver_loc=[[Príncipe Keleseth]],giverType=[[NPC]],giverId=28911,ender=[[Prince Keleseth]],ender_loc=[[Príncipe Keleseth]],enderType=[[NPC]],enderId=28911,prevId=12715,rewardNextId=12720,poiX=1587,poiY=-5700,wowhead=[[https://www.wowhead.com/wotlk/quest=12719]],image=[[assets/images/quests/placeholder.png]],desc=[[Nothing less than total annihilation will suffice, $N. To that end, a few hundred mindless ghouls assaulting the front gate of New Avalon will not do. We must infiltrate the inner sanctum and dispose of their officials. They must be shown that no one can escape the Scourge's grasp! Make your way to the New Avalon Town Hall, southwest of here, and assassinate the mayor. Search the building for the New Avalon registry and bring it to me.]],logDesc=[[Prince Keleseth at the Crypt of Remembrance has ordered you to kill Mayor Quimby and recover the New Avalon Registry.]]}
DB[12720]={id=12720,name=[[How To Win Friends And Influence Enemies]],name_loc=[[Cómo ganar amigos e influenciar a los enemigos]],level=55,minLevel=55,giver=[[Prince Keleseth]],giver_loc=[[Príncipe Keleseth]],giverType=[[NPC]],giverId=28911,ender=[[Prince Keleseth]],ender_loc=[[Príncipe Keleseth]],enderType=[[NPC]],enderId=28911,prevId=12719,poiX=1879,poiY=-5765,wowhead=[[https://www.wowhead.com/wotlk/quest=12720]],image=[[assets/images/quests/placeholder.png]],desc=[[In my travels across this world I have made several interesting discoveries. For instance, did you know that with the proper amount of encouragement one can extract all the truths that a man dares hide? As luck would have it, I happen to have some encouragement on hand. <Keleseth pulls something out of an ornately jeweled box.> These are my "persuaders." Equip them and take to the field, death knight. Apply the pointy ends to the soldiers of New Avalon. Discover the truth about this "Crimson Dawn."]],logDesc=[[Prince Keleseth at the Crypt of Remembrance has ordered you to discover the truth about the "Crimson Dawn." Remove Keleseth's Persuaders from the Ornately Jeweled Box and use them to "persuade" the Scarlet Crusade into talking.]],rewards={{id=38672,qty=1}}}
DB[12721]={id=12721,zoneId=66,name=[[Rampage]],level=77,minLevel=74,giver=[[Har'koa]],giverType=[[NPC]],giverId=28401,ender=[[Witch Doctor Khufu]],enderType=[[NPC]],enderId=28479,prevId=12712,wowhead=[[https://www.wowhead.com/wotlk/quest=12721]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, there is no time left. You must take the key and use it to unlock Akali. He is being held in the courtyard in front of Gundrak, the capital of Zul'Drak. Akali's chains are secured by four anchor points. You must unlock each of them to set the rhino god free. Gundrak is teeming with ice trolls. However, I believe that if you're careful, you should be able to slip in without too much danger. Once you're done, please inform the witch doctor.]],logDesc=[[Har'koa at Zim'Torga has asked you to free Akali and then to inform Witch Doctor Khufu at Zim'Torga.]],choiceRewards={{id=39794,qty=1},{id=39862,qty=1},{id=39846,qty=1},{id=39847,qty=1}}}
DB[12722]={id=12722,name=[[Lambs To The Slaughter]],name_loc=[[Corderos al matadero]],level=55,minLevel=55,giver=[[Baron Rivendare]],giver_loc=[[Barón Osahendido]],giverType=[[NPC]],giverId=28910,ender=[[Baron Rivendare]],ender_loc=[[Barón Osahendido]],enderType=[[NPC]],enderId=28910,prevId=12715,poiX=1655,poiY=-6046,wowhead=[[https://www.wowhead.com/wotlk/quest=12722]],image=[[assets/images/quests/placeholder.png]],desc=[[Most humans would have fled the moment a Scourge necropolis took up residence in their air space. Not the Scarlet Crusade! I must confess - I rather enjoy our exchanges with the Crusade. Through the years, Scourge battles against them have resulted in several of the most tragic events in human history. Yet here we stand - AGAIN - locked in battle! We shan't deny them the pleasures of eternal servitude to the Lich King! Enter New Avalon and fulfill their death wish. Leave no survivors.]],logDesc=[[Baron Rivendare at the Crypt of Remembrance has commanded you to slay 10 Scarlet Crusade Soldiers and 15 Citizens of New Avalon.]],rewards={{id=38670,qty=1}}}
DB[12723]={id=12723,name=[[Behind Scarlet Lines]],name_loc=[[Detrás de las líneas Escarlata]],level=55,minLevel=55,giver=[[Prince Keleseth]],giver_loc=[[Príncipe Keleseth]],giverType=[[NPC]],giverId=28911,ender=[[Orbaz Bloodbane]],ender_loc=[[Orbaz Malasangre]],enderType=[[NPC]],enderId=28914,prevId=12720,rewardNextId=12724,exGroup=-12716,poiX=1404,poiY=-5827,wowhead=[[https://www.wowhead.com/wotlk/quest=12723]],image=[[assets/images/quests/placeholder.png]],desc=[[I have sent Orbaz, Thassarian and Koltira behind enemy lines to search for the courier. They have set up a base of operations at the Scarlet Tavern, located at the southern end of New Avalon. The tavern is tucked away behind the two orchards, adjacent to the Chapel of the Crimson Flame. You are to make your way to the tavern and report to Orbaz Bloodbane. He will update you on their situation. ]],logDesc=[[Report to Orbaz Bloodbane at the Scarlet Tavern in New Avalon.]]}
DB[12724]={id=12724,name=[[The Path Of The Righteous Crusader]],name_loc=[[El camino del cruzado honrado]],level=55,minLevel=55,giver=[[Orbaz Bloodbane]],giver_loc=[[Orbaz Malasangre]],giverType=[[NPC]],giverId=28914,ender=[[Orbaz Bloodbane]],ender_loc=[[Orbaz Malasangre]],enderType=[[NPC]],enderId=28914,prevId=12723,poiX=1647,poiY=-6040,wowhead=[[https://www.wowhead.com/wotlk/quest=12724]],image=[[assets/images/quests/placeholder.png]],desc=[[We haven't got a damned clue about when or where this courier is supposed to show up. None of these humans had an answer either. <Orbaz points to the Scarlet corpses strewn across the floor.> I did manage to beat something useful out of the last one. Inside Scarlet Hold they keep a schedule of all patrol routes. I want you to break into the hold and steal the schedule. The hold is the largest building in New Avalon - northeast of here.]],logDesc=[[Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to steal the New Avalon Patrol Schedule from the Scarlet Hold.]],rewards={{id=38667,qty=1}}}
DB[12725]={id=12725,name=[[Brothers In Death]],name_loc=[[Hermanos en la muerte]],level=55,minLevel=55,giver=[[Thassarian]],giverType=[[NPC]],giverId=28913,ender=[[Koltira Deathweaver]],ender_loc=[[Koltira Tejemuerte]],enderType=[[NPC]],enderId=28912,prevId=12723,rewardNextId=12727,poiX=1656,poiY=-6039,wowhead=[[https://www.wowhead.com/wotlk/quest=12725]],image=[[assets/images/quests/placeholder.png]],desc=[[Breaking through the Scarlet lines was no easy task. We suffered many casualties during the assault and lost one of our best death knights, Koltira Deathweaver. I don't know whether he's dead or alive, but I'll be damned if we don't search for him. I last saw him being bound in irons and dragged away to the Scarlet Hold, northeast of here. Tear that keep asunder, death knight. Find Koltira!]],logDesc=[[Search for Koltira Deathweaver in the Scarlet Hold.]]}
DB[12726]={id=12726,zoneId=3711,name=[[Song of Wind and Water]],level=80,minLevel=77,giver=[[Oracle Soo-nee]],giverType=[[NPC]],giverId=29006,ender=[[Oracle Soo-nee]],enderType=[[NPC]],enderId=29006,prevId=12695,exGroup=12726,wowhead=[[https://www.wowhead.com/wotlk/quest=12726]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen to storm, yes?  The Stormwright's Shelf echoes with ancient song.... the Song of Wind and Water. The great tempest devours the sons of typhoons and storms.  Take this drum and play his song... play Haiphoon's song. Help him feed on wind and water so tempest can continue.]],logDesc=[[Soo-nee wants you to use the Tempest Drums at the Stormwright's Shelf and help Haiphoon devour 3 Storm Revenants and 3 Aqueous Spirits.]]}
DB[12727]={id=12727,name=[[Bloody Breakout]],name_loc=[[Estallido sangriento]],level=55,minLevel=55,giver=[[Koltira Deathweaver]],giver_loc=[[Koltira Tejemuerte]],giverType=[[NPC]],giverId=28912,ender=[[Thassarian]],enderType=[[NPC]],enderId=28913,prevId=12725,rewardNextId=12738,poiX=1398,poiY=-5827,wowhead=[[https://www.wowhead.com/wotlk/quest=12727]],image=[[assets/images/quests/placeholder.png]],desc=[[The alarms have been sounded. The High Inquisitor and his acolytes will be here soon. I'm too badly injured to be of much use, but I'll do what little I can to help. Slay the High Inquisitor and his cronies. Tear off his head and return with it to Thassarian. Vengeance will soothe his savage soul. One more thing, $N. If you do manage to survive and make it back to Thassarian, tell him that they're executing prisoners at the chapel. Perhaps he'll send you there to play the hero once more.]],logDesc=[[Slay High Inquisitor Valroth and take Valroth's Head to Thassarian at the Scarlet Tavern in New Avalon.]],rewards={{id=38665,qty=1}}}
DB[12728]={id=12728,zoneId=3537,name=[[Monitoring the Rift: Winterfin Cavern]],level=71,minLevel=69,giver=[[Librarian Garren]],giverType=[[NPC]],giverId=25291,ender=[[Librarian Garren]],enderType=[[NPC]],enderId=25291,prevId=11582,wowhead=[[https://www.wowhead.com/wotlk/quest=12728]],image=[[assets/images/quests/placeholder.png]],desc=[[I need to compile my notes and prepare a presentation for my colleagues in Dalaran. While I do, I must ask that you visit the Winterfin Cavern to the north. You must use the Arcanometer while standing in the mouth of the cavern. Return to me at once when you have the data. My documentation will be incomplete without it.]],logDesc=[[Librarian Garren at Amber Ledge wants you to use the Arcanometer at Winterfin Caverns.]],choiceRewards={{id=37282,qty=1},{id=37320,qty=1},{id=37458,qty=1},{id=37471,qty=1}}}
DB[12729]={id=12729,zoneId=66,name=[[The Gods Have Spoken]],level=77,minLevel=74,giver=[[Witch Doctor Khufu]],giverType=[[NPC]],giverId=28479,ender=[[Har'koa]],enderType=[[NPC]],enderId=28401,prevId=12721,rewardNextId=12730,wowhead=[[https://www.wowhead.com/wotlk/quest=12729]],image=[[assets/images/quests/placeholder.png]],desc=[[The gods have spoken and we must heed their wisdom. Gather friends to your side, $N. Take them north to Zim'Rhuk to destroy guardians there until they yield the unblemished heart. Take them east to the Altar of Quetz'lun and disrupt the altar wardens until you recover their gusty essence. Deliver both to Har'koa and she will combine them into that which will compel late Akali's prophet to appear.]],logDesc=[[Deliver the Unblemished Heart of the Guardian and the Gusty Essence of the Warden to Har'koa at Zim'Torga.]]}
DB[12730]={id=12730,zoneId=66,name=[[Convocation at Zol'Heb]],level=78,minLevel=74,giver=[[Har'koa]],giverType=[[NPC]],giverId=28401,ender=[[Har'koa]],enderType=[[NPC]],enderId=28401,prevId=12729,wowhead=[[https://www.wowhead.com/wotlk/quest=12730]],image=[[assets/images/quests/placeholder.png]],desc=[[You and your friends must take this instrument of convocation - of summoning - to Zol'Heb just south of Gundrak. Therein you will find a circle of power. Use the convocation to force the prophet of Akali to appear. My heart goes out to you, $N. We have been through much together, and you have done all that you can to not only save my life, but those of the other gods the Drakkari have destroyed. But I fear this time we may not see each other again until the afterlife.]],logDesc=[[Har'koa at Zim'Torga has asked you to slay the Prophet of Akali.]],choiceRewards={{id=41890,qty=1},{id=41891,qty=1},{id=41905,qty=1},{id=41932,qty=1}}}
DB[12731]={id=12731,name=[[]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=12731]],image=[[assets/images/quests/placeholder.png]]}
DB[12732]={id=12732,zoneId=3711,name=[[The Heartblood's Strength]],level=80,minLevel=77,giver=[[Rejek]],giverType=[[NPC]],giverId=29043,ender=[[Rejek]],enderType=[[NPC]],enderId=29043,prevId=12692,exGroup=12758,wowhead=[[https://www.wowhead.com/wotlk/quest=12732]],image=[[assets/images/quests/placeholder.png]],desc=[[One day, Rejek will be mighty warrior. Blood and skyfire will make Rejek strong. You see soon. Rejek give you vial, you take to very top of Suntouched Pillar, far to west. Put waters there in vial. Then go to north edge of basin, to ledge north of Bonefields. You find and kill goretalon matriarch. Take heartblood. You combine heartblood and water, bring to Rejek. Rejek drink, make strong.]],logDesc=[[Bring a vial of Suntouched Heartblood to Rejek at Frenzyheart Hill.]]}
DB[12733]={id=12733,name=[[Death's Challenge]],name_loc=[[Desafío de la Muerte]],level=55,minLevel=55,giver=[[Olrun the Battlecaller]],giver_loc=[[Olrun la Clamabatallas]],giverType=[[NPC]],giverId=29047,ender=[[Olrun the Battlecaller]],ender_loc=[[Olrun la Clamabatallas]],enderType=[[NPC]],enderId=29047,prevId=12670,nextId=12697,exGroup=-12733,poiX=2371,poiY=-5766,wowhead=[[https://www.wowhead.com/wotlk/quest=12733]],image=[[assets/images/quests/placeholder.png]],desc=[[Born of the Lich King's victory over Illidan Stormrage in the heart of the frozen wastes, Death's Challenge is a rite of passage that all death knights must undergo. Seek out other death knights of Acherus and challenge them to a duel. They must accept and fight until a victor emerges! Go now, $N! Victory for the Scourge! Glory to the Lich King! ]],logDesc=[[Olrun the Battlecaller has ordered you to win 5 duels against other death knights. You may choose to battle death knight initiates or players.]],rewards={{id=40483,qty=1}}}
DB[12734]={id=12734,zoneId=3711,name=[[Rejek: First Blood]],level=80,minLevel=77,giver=[[Rejek]],giverType=[[NPC]],giverId=29043,ender=[[Rejek]],enderType=[[NPC]],enderId=29043,prevId=12692,exGroup=12758,wowhead=[[https://www.wowhead.com/wotlk/quest=12734]],image=[[assets/images/quests/placeholder.png]],desc=[[Rejek just became youngest warrior in all of Frenzyheart tribe. Father gave Rejek a mighty sword to defeat Frenzyheart enemies, but old tradition say sword need to be blooded first. Older warrior usually do that. You do this honor for Rejek? Take blade, put in corpses of all Frenzyheart foes: wasps and hardknuckles to southwest, and the big-tongues. Maybe blood blade on Mistwhispers, far to northwest near Bittertide Lake.]],logDesc=[[Blood Rejek's Blade on the corpses of a Sapphire Hive Wasp, a Hardknuckle Charger, and 3 members of the Mistwhisper Tribe. You may blood the sword on either Mistwhisper Oracles or Mistwhisper Warriors. Return to Rejek at Frenzyheart Hill when your task is complete.]]}
DB[12735]={id=12735,zoneId=3711,name=[[A Cleansing Song]],level=80,minLevel=77,giver=[[Oracle Soo-nee]],giverType=[[NPC]],giverId=29006,ender=[[Oracle Soo-nee]],enderType=[[NPC]],enderId=29006,prevId=12695,exGroup=12726,wowhead=[[https://www.wowhead.com/wotlk/quest=12735]],image=[[assets/images/quests/placeholder.png]],desc=[[Earth in Sholazar is pure.  The pillars have protected the land for centuries. Water, not as pure, it comes from outside Sholazar.... from oceans, from lakes, from rivers.  Water sometimes bring bad spirits - need to be cleansed. You take this chime and play at Bittertide Lake, Wintergrasp River and River's Heart.  It make bad spirit angry... and then you must kill it.]],logDesc=[[Soo-nee, at the Rainspeaker Canopy, wants you to play the Cleansing Chime at Bittertide Lake, Wintergrasp River and River's Heart and slay the evil spirits that plague the waters there.]]}
DB[12736]={id=12736,zoneId=3711,name=[[Song of Reflection]],level=80,minLevel=77,giver=[[Oracle Soo-nee]],giverType=[[NPC]],giverId=29006,ender=[[Oracle Soo-nee]],enderType=[[NPC]],enderId=29006,prevId=12695,exGroup=12726,wowhead=[[https://www.wowhead.com/wotlk/quest=12736]],image=[[assets/images/quests/placeholder.png]],desc=[[Of course you not as smart as gorloc!  You just simple $r. You not without hope, though!  You show you can learn.  Maybe crystals make you smart like crystals make us smart! I teach you to play song to clear your mind.  You play song by crystals then crystals make your mind better... not as good as gorloc's but better than you have now.  Lifeblood Pillar is broken, but other pillars still good!]],logDesc=[[Soo-nee at Rainspeaker Canopy wants you to use the Didgeridoo of Contemplation at the top of the Glimmering Pillar, the Suntouched Pillar, the Mosslight Pillar and the Skyreach Pillar.]]}
DB[12737]={id=12737,zoneId=3711,name=[[Song of Fecundity]],level=80,minLevel=77,giver=[[Oracle Soo-nee]],giverType=[[NPC]],giverId=29006,ender=[[Oracle Soo-nee]],enderType=[[NPC]],enderId=29006,prevId=12695,exGroup=12726,wowhead=[[https://www.wowhead.com/wotlk/quest=12737]],image=[[assets/images/quests/placeholder.png]],desc=[[The storm is a destructive force.  Storm burns trees.  Storm floods houses. But storm can also be life force if you know right song.  In Stormwright Shelf, above Maker's Perch, you can find small dirt mounds.  They very fertile -- they carry inside a strong seed.  All they wait for is the right song. You take this horn and play song for them.]],logDesc=[[Soo-nee at Rainspeaker Canopy wants you to go to the Stormwright's Shelf, northwest of the Maker's Perch, and play the Horn of Fecundity near 8 piles Soaked Fertile Dirt.]]}
DB[12738]={id=12738,name=[[A Cry For Vengeance!]],name_loc=[[¡Un grito de venganza!]],level=55,minLevel=55,giver=[[Thassarian]],giverType=[[NPC]],giverId=28913,ender=[[Knight Commander Plaguefist]],ender_loc=[[Caballero Comandante Puño de Peste]],enderType=[[NPC]],enderId=29053,prevId=12727,poiX=1348,poiY=-5715,wowhead=[[https://www.wowhead.com/wotlk/quest=12738]],image=[[assets/images/quests/placeholder.png]],desc=[[The cry for vengeance must be heard, $N. Commander Plaguefist and a company of death knights are on their way to raze the Chapel of the Crimson Flame. If there are any death knights imprisoned at the chapel, Plaguefist will get them out. You can still catch up to them if you hurry. The chapel is due west of here.]],logDesc=[[Report to Knight Commander Plaguefist at the Chapel of the Crimson Flame.]]}
DB[12739]={id=12739,name=[[A Special Surprise]],name_loc=[[Una sorpresa especial]],level=55,minLevel=55,giver=[[Knight Commander Plaguefist]],giver_loc=[[Caballero Comandante Puño de Peste]],giverType=[[NPC]],giverId=29053,ender=[[Knight Commander Plaguefist]],ender_loc=[[Caballero Comandante Puño de Peste]],enderType=[[NPC]],enderId=29053,prevId=12738,nextId=12751,rewardNextId=12751,poiX=1319,poiY=-5772,wowhead=[[https://www.wowhead.com/wotlk/quest=12739]],image=[[assets/images/quests/placeholder.png]],desc=[[We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, $N. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing. I was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty tauren in there that I think you'll take great pleasure in executing.]],logDesc=[[Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Malar Bravehorn, an Argent Dawn prisoner inside the nearby prison house.]]}
DB[12740]={id=12740,zoneId=66,name=[[Parachutes for the Argent Crusade]],level=76,minLevel=74,giver=[[Commander Falstaav]],giverType=[[NPC]],giverId=28059,ender=[[Commander Falstaav]],enderType=[[NPC]],enderId=28059,nextId=12596,rewardNextId=12596,exGroup=-12503,wowhead=[[https://www.wowhead.com/wotlk/quest=12740]],image=[[assets/images/quests/placeholder.png]],desc=[[Those sky terrors are destroying my men and women! Dying from falling is a horrible way to go. $C, you have to get these parachutes out to them! At least then they'll have a fighting chance to survive.]],logDesc=[[Commander Falstaav at The Argent Stand has asked you to equip 10 Argent Crusaders or Argent Shieldmen out in the courtyard with parachutes.]],choiceRewards={{id=39779,qty=1},{id=39840,qty=1},{id=39799,qty=1},{id=39801,qty=1},{id=39820,qty=1}}}
DB[12741]={id=12741,zoneId=3711,name=[[Strength of the Tempest]],level=80,minLevel=77,giver=[[Rejek]],giverType=[[NPC]],giverId=29043,ender=[[Rejek]],enderType=[[NPC]],enderId=29043,prevId=12692,exGroup=12758,wowhead=[[https://www.wowhead.com/wotlk/quest=12741]],image=[[assets/images/quests/placeholder.png]],desc=[[Silly big-tongues think singing to the clouds give them power. Rejek show big-tongues how to get power by taking it! Far to northwest, there is large, flat area the big-tongues call 'Stormwright's Shelf.' Rejek is sure you can only get there by flying like bird. On this shelf, Rejek has heard of mighty forces of wind and water. Kill them for their badness, then take it to the big-tongue 'Shrine of the Tempest' at shelf's western side. Rejek will await your return with ultimate power.]],logDesc=[[Gather 3 Essences of the Monsoon and 3 Essences of the Storm and take them to the Shrine of the Tempest. Return to Rejek at Frenzyheart Hill with the True Power of the Tempest.]]}
DB[12742]={id=12742,name=[[A Special Surprise]],name_loc=[[Una sorpresa especial]],level=55,minLevel=55,giver=[[Knight Commander Plaguefist]],giver_loc=[[Caballero Comandante Puño de Peste]],giverType=[[NPC]],giverId=29053,ender=[[Knight Commander Plaguefist]],ender_loc=[[Caballero Comandante Puño de Peste]],enderType=[[NPC]],enderId=29053,prevId=12738,nextId=12751,rewardNextId=12751,poiX=1321,poiY=-5741,wowhead=[[https://www.wowhead.com/wotlk/quest=12742]],image=[[assets/images/quests/placeholder.png]],desc=[[We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, $N. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing. I was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty human in there that I think you'll take great pleasure in executing.]],logDesc=[[Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Ellen Stanbridge, an Argent Dawn prisoner inside the nearby prison house.]]}
