DB[12792]={id=12792,zoneId=66,name=[[First Things First]],level=75,minLevel=74,giver=[[Commander Kunz]],giverType=[[NPC]],giverId=28039,ender=[[Sergeant Riannah]],enderType=[[NPC]],enderId=29137,exGroup=12789,wowhead=[[https://www.wowhead.com/wotlk/quest=12792]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen up, $r! This entire region is full of crises. Everywhere you look you'll find those who could use your assistance. <Kunz looks you squarely in the eye.> No one needs your help right now more than Riannah. The scourge have forced their way between us, leaving her and those she commands isolated. Light's Breach, where her forces are holding out, lies just southwest of here.]],logDesc=[[Commander Kunz at Argent Stand wants you to report to Sergeant Riannah at Light's Breach.]]}
DB[12793]={id=12793,zoneId=66,name=[[Smoke on the Horizon]],level=75,minLevel=74,giver=[[Witch Doctor Khufu]],giverType=[[NPC]],giverId=28479,ender=[[Sergeant Riannah]],enderType=[[NPC]],enderId=29137,exGroup=12789,wowhead=[[https://www.wowhead.com/wotlk/quest=12793]],image=[[assets/images/quests/placeholder.png]],desc=[[You hear that, $r? The clamor of battle far to the west reaches us here, even over the din of our own struggle. The Scourge are threatening to break through the lines of those calling themselves the Argent Crusade. Preventing this is as urgent as anything in the region. Travel to Light's Breach and join in their struggle. Speak to Maaka and he will provide you safe passage.]],logDesc=[[Khufu in Zim'Torga wants you to travel to Light's Breach and report to Sergeant Riannah there. Maaka will provide you with transportation there.]]}
DB[12794]={id=12794,zoneId=4395,name=[[The Magical Kingdom of Dalaran]],level=74,minLevel=74,giver=[[Baron Ulrik von Stromhearth]],giverType=[[NPC]],giverId=23729,ender=[[Archmage Celindra]],enderType=[[NPC]],enderId=29156,rewardNextId=12790,exGroup=12796,wowhead=[[https://www.wowhead.com/wotlk/quest=12794]],image=[[assets/images/quests/placeholder.png]],desc=[[Hello, $N. You may or may not be aware that we Kirin Tor moved our city here to Northrend. No longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest. We believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there. When you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.]],logDesc=[[Deliver the Kirin Tor Signet to Archmage Celindra at the Violet Gate in Dalaran.]]}
