DB[13475]={id=13475,name=[[For Great Honor]],level=-1,minLevel=71,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13475]],image=[[assets/images/quests/placeholder.png]]}
DB[13476]={id=13476,name=[[For Great Honor]],level=-1,minLevel=71,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13476]],image=[[assets/images/quests/placeholder.png]],desc=[[Serving the Horde in one of the great battles against the Alliance is a source of great honor!  The few however, that have served the Horde in ALL of our active battlefronts are our truly great fighters.  We shall vanquish our opponents, not by fighting isolated skirmishes, but by waging a well-coordinated war. Go forth and crush the Alliance on every front!  For Honor!  For the Horde!]],logDesc=[[Bring a Mark of Honor from each battleground to a Horde Warbringer in any Horde capital city, Shattrath, Dalaran, or Wintergrasp.]]}
DB[13477]={id=13477,name=[[Concerted Efforts]],level=-1,minLevel=71,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13477]],image=[[assets/images/quests/placeholder.png]]}
DB[13478]={id=13478,name=[[Concerted Efforts]],level=-1,minLevel=71,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13478]],image=[[assets/images/quests/placeholder.png]],desc=[[We're not fighting isolated battles against the Horde anymore, $g lad:lass;. Victory in one front means denying the Horde resources they'd use against us in a different battle.  By the same token, abandoning any given battle could give the advantage to our opponent somewhere else around the world. The Alliance is in need of more combatants with this sort of worldly understanding... truly seasoned veterans!  $N, come back to me after you've served against the Horde at all of our active battlegrounds.]],logDesc=[[Bring a Mark of Honor from each battleground to an Alliance Brigadier General in any Alliance Capital City, Shattrath, Dalaran, or Wintergrasp.]]}
DB[13479]={id=13479,name=[[The Great Egg Hunt]],name_loc=[[La gran búsqueda de huevos]],level=-1,minLevel=1,giver=[[Spring Gatherer]],giver_loc=[[Recolector primaveral]],giverType=[[NPC]],giverId=32798,ender=[[Spring Gatherer]],ender_loc=[[Recolector primaveral]],enderType=[[NPC]],enderId=32798,poiX=2237,poiY=249,wowhead=[[https://www.wowhead.com/wotlk/quest=13479]],image=[[assets/images/quests/placeholder.png]],desc=[[Noblegarden, celebration of life and spring! I hope you've been enjoying the egg hunt, friend, because I could use the services of a capable individual like you. I'm not certain what form of magic was used in the creation of the eggs, and the druids aren't keen on explaining it to me. Perhaps you could collect some shell fragments for me during your egg collection. You can keep the contents of the eggs; all I require is a sufficient sample of the eggs themselves.]],logDesc=[[The Sping Gatherer wants you to get 20 shell fragments.]],rewards={{id=44792,qty=1}}}
DB[13480]={id=13480,name=[[The Great Egg Hunt]],name_loc=[[La gran búsqueda de huevos]],level=-1,minLevel=1,giver=[[Spring Collector]],giver_loc=[[Colector primaveral]],giverType=[[NPC]],giverId=32799,ender=[[Spring Collector]],ender_loc=[[Colector primaveral]],enderType=[[NPC]],enderId=32799,poiX=-9453,poiY=44,wowhead=[[https://www.wowhead.com/wotlk/quest=13480]],image=[[assets/images/quests/placeholder.png]],desc=[[Noblegarden, celebration of life and spring! I hope you've been enjoying the egg hunt, friend, because I could use the services of a capable individual like you. I'm not certain what form of magic was used in the creation of the eggs, and the druids aren't keen on explaining it to me. Perhaps you could collect some shell fragments for me during your egg collection. You can keep the contents of the eggs; all I require is a sufficient sample of the eggs themselves.]],logDesc=[[The Spring Collector wants you to get 20 shell fragments.]],rewards={{id=44792,qty=1}}}
DB[13481]={id=13481,zoneId=210,name=[[Let's Get Out of Here!]],level=80,minLevel=77,giver=[[Father Kamaros]],giverType=[[NPC]],giverId=32800,ender=[[Brother Keltan]],enderType=[[NPC]],enderId=31261,prevId=13144,wowhead=[[https://www.wowhead.com/wotlk/quest=13481]],image=[[assets/images/quests/placeholder.png]],desc=[[The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape. I cannot make it on my own, $c, but with your help, I may yet live to fight the Scourge again. Will you help me make my escape before the Scourge's butchers come to finish me off?]],logDesc=[[Escort Father Kamaros to safety and then report to Brother Keltan aboard Orgrim's Hammer.]]}
DB[13482]={id=13482,zoneId=210,name=[[Let's Get Out of Here]],level=80,minLevel=77,giver=[[Father Kamaros]],giverType=[[NPC]],giverId=32800,ender=[[Absalan the Pious]],enderType=[[NPC]],enderId=31259,prevId=13144,wowhead=[[https://www.wowhead.com/wotlk/quest=13482]],image=[[assets/images/quests/placeholder.png]],desc=[[The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape. I cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again. Will you help me make my escape before the Scourge's butchers come to finish me off?]],logDesc=[[Escort Father Kamaros to safety and then report to Absalan the Pious aboard the Skybreaker.]]}
DB[13483]={id=13483,name=[[Spring Gatherers]],name_loc=[[Recolectores primaverales]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Spring Gatherer]],ender_loc=[[Recolector primaveral]],enderType=[[NPC]],enderId=32798,rewardNextId=13479,poiX=2237,poiY=249,wowhead=[[https://www.wowhead.com/wotlk/quest=13483]],image=[[assets/images/quests/placeholder.png]],desc=[[If you're looking for something to do, I hear there are mages in the settlements near capital cities - Razor Hill, Brill, Bloodhoof Village, and Falconwing Square - who have been recruiting egg hunters for help with some research they're doing. I'm not sure of the particulars, but I'm sure they'd tell you.]],logDesc=[[Talk to a Spring Gatherer in Razor Hill, Brill, Bloodhoof Village, or Falconwing Square.]]}
DB[13484]={id=13484,name=[[Spring Collectors]],name_loc=[[Colectores primaverales]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Spring Collector]],ender_loc=[[Colector primaveral]],enderType=[[NPC]],enderId=32799,rewardNextId=13480,poiX=-9453,poiY=44,wowhead=[[https://www.wowhead.com/wotlk/quest=13484]],image=[[assets/images/quests/placeholder.png]],desc=[[If you're looking for something to do, I hear there are mages in the settlements near capital cities - Goldshire, Kharanos, Dolanaar, and Azure Watch - who have been recruiting egg hunters for help with some research they're doing. I'm not sure of the particulars, but I'm sure they'd tell you.]],logDesc=[[Talk to a Spring Collector in Goldshire, Kharanos, Dolanaar, or Azure Watch.]]}
