DB[13502]={id=13502,name=[[A Tisket, a Tasket, a Noblegarden Basket]],name_loc=[[¿Qué llevas en la cestita?]],level=-1,minLevel=1,giver=[[Noblegarden Vendor]],giver_loc=[[Vendedor del Jardín Noble]],giverType=[[NPC]],giverId=32836,ender=[[Noblegarden Vendor]],ender_loc=[[Vendedor del Jardín Noble]],enderType=[[NPC]],enderId=32836,poiX=-9452,poiY=42,wowhead=[[https://www.wowhead.com/wotlk/quest=13502]],image=[[assets/images/quests/placeholder.png]],desc=[[Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you've found ten Noblegarden Chocolates.]],logDesc=[[The Noblegarden Vendor wants you to collect 10 Noblegarden Chocolates and return them along with the Egg Basket.]],rewards={{id=45067,qty=1}}}
DB[13503]={id=13503,name=[[A Tisket, a Tasket, a Noblegarden Basket]],name_loc=[[¿Qué llevas en la cestita?]],level=-1,minLevel=1,giver=[[Noblegarden Merchant]],giver_loc=[[Mercader del Jardín Noble]],giverType=[[NPC]],giverId=32837,ender=[[Noblegarden Merchant]],ender_loc=[[Mercader del Jardín Noble]],enderType=[[NPC]],enderId=32837,poiX=2241,poiY=261,wowhead=[[https://www.wowhead.com/wotlk/quest=13503]],image=[[assets/images/quests/placeholder.png]],desc=[[Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you've found ten Noblegarden Chocolates.]],logDesc=[[The Noblegarden Merchant wants you to collect 10 Noblegarden Chocolates and return them along with the Egg Basket.]],rewards={{id=45067,qty=1}}}
DB[13524]={id=13524,zoneId=394,name=[[Escape from Silverbrook]],level=74,minLevel=73,giverType=[[NPC]],enderType=[[NPC]],nextId=12310,rewardNextId=12310,exGroup=12308,wowhead=[[https://www.wowhead.com/wotlk/quest=13524]],image=[[assets/images/quests/placeholder.png]],desc=[[You... you're not one of them?  Quick!  Let me out! We have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!]],logDesc=[[Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook.  Report to Lieutenant Dumont when you reach Amberpine Lodge.]],choiceRewards={{id=38733,qty=1},{id=39031,qty=1},{id=39059,qty=1},{id=39097,qty=1},{id=38750,qty=1}}}
DB[13538]={id=13538,zoneId=4197,name=[[Southern Sabotage]],level=80,minLevel=78,giver=[[Tactical Officer Ahbramis]],giverType=[[NPC]],giverId=31153,ender=[[Tactical Officer Ahbramis]],enderType=[[NPC]],enderId=31153,wowhead=[[https://www.wowhead.com/wotlk/quest=13538]],image=[[assets/images/quests/placeholder.png]],desc=[[The three towers south of the Wintergrasp river are draining power from the Fortress!  Destroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower, then return to me. Remember, only siege vehicles can damage a tower, so make sure to protect them from the Horde!]],logDesc=[[Destroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower and return to Tactical Officer Ahbramis in Wintergrasp.]],rewards={{id=43228,qty=10}}}
DB[13539]={id=13539,zoneId=4197,name=[[Toppling the Towers]],level=80,minLevel=78,giver=[[Tactical Officer Kilrath]],giverType=[[NPC]],giverId=31151,ender=[[Tactical Officer Kilrath]],enderType=[[NPC]],enderId=31151,wowhead=[[https://www.wowhead.com/wotlk/quest=13539]],image=[[assets/images/quests/placeholder.png]],desc=[[While the Alliance may be pounding on our doors, a true tactician looks beyond the obvious. "Attack him where he is unprepared, appear where you are not expected." $n, I need you to travel across the Wintergrasp River and destroy one of the three towers to the south. Our Warlocks report that the towers are draining power we could use to bolster our own troops. Return to me once you've destroyed a tower.]],logDesc=[[Destroy Shadowsight Tower, Flamewatch Tower, or Winter's Edge Tower and return to Tactical Officer Kilrath in Wintergrasp.]],rewards={{id=43228,qty=10}}}
DB[13541]={id=13541,name=[[]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13541]],image=[[assets/images/quests/placeholder.png]]}
DB[13548]={id=13548,name=[[Candy Bucket]],name_loc=[[Cubo de caramelos]],level=-1,minLevel=1,giver=[[Candy Bucket]],giver_loc=[[Cubo de caramelos]],giverType=[[GO]],giverId=194119,ender=[[Candy Bucket]],ender_loc=[[Cubo de caramelos]],enderType=[[GO]],enderId=194119,poiX=7851,poiY=-796,wowhead=[[https://www.wowhead.com/wotlk/quest=13548]],image=[[assets/images/quests/placeholder.png]],rewards={{id=37586,qty=1}}}
DB[13549]={id=13549,zoneId=66,name=[[Tails Up]],level=77,minLevel=74,giver=[[Chronicler To'kini]],giverType=[[NPC]],giverId=28527,ender=[[Chronicler To'kini]],enderType=[[NPC]],enderId=28527,prevId=12635,wowhead=[[https://www.wowhead.com/wotlk/quest=13549]],image=[[assets/images/quests/placeholder.png]],desc=[[Along with the Drakkari artifacts, I'm interested in returning to Zandalar with some of the Zul'Drak wildlife. I have males of both the frost leopards and icepaw bears, but I need females! Too bad that my trapper was killed in a most unfortunate accident. Perhaps you would be willing to fill in for him? Put the leopards and bears to sleep with this blowgun then lift their tails and return with some females if you would be so kind. They can be found near the Altars of Rhunok, Quetz'lun, and Har'koa.]],logDesc=[[Chronicler To'kini at Zim'Torga wants you to use To'kini's Blowgun on Frost Leopards and Icepaw Bears. Return to him with 3 females of each.]]}
DB[13556]={id=13556,zoneId=66,name=[[Eggs for Dubra'Jin]],level=77,minLevel=74,giver=[[Ha'wana]],giverType=[[NPC]],giverId=33025,ender=[[Ha'wana]],enderType=[[NPC]],enderId=33025,wowhead=[[https://www.wowhead.com/wotlk/quest=13556]],image=[[assets/images/quests/placeholder.png]],desc=[[How ya doin', mon? Thinkin' ya might be helpin' me out? Bah'Kini be needin' lots o' the raptor eggs to be sacrificin' to Dubra'Jin. How ya thinkin' we not be overrun yet by the Drakkari? Dubra'Jin be lendin' us his aid! We need ya to gather up the raptor eggs from around the trees outside here in Gundrak. Sometimes the raptors carry 'em to keep 'em warm, too.]],logDesc=[[Ha'wana at Dubra'Jin needs you to collect 12 Gundrak Raptor Eggs.]]}
DB[13559]={id=13559,zoneId=67,name=[[Hodir's Tribute]],level=80,minLevel=77,giver=[[Lillehoff]],giverType=[[NPC]],giverId=32540,ender=[[Lillehoff]],enderType=[[NPC]],enderId=32540,wowhead=[[https://www.wowhead.com/wotlk/quest=13559]],image=[[assets/images/quests/placeholder.png]]}
DB[13571]={id=13571,name=[[Fletcher's Lost and Found]],level=80,minLevel=1,giver=[[Washed-Up Mage]],giverType=[[NPC]],giverId=32516,ender=[[Washed-Up Mage]],enderType=[[NPC]],enderId=32516,prevId=12645,wowhead=[[https://www.wowhead.com/wotlk/quest=13571]],image=[[assets/images/quests/placeholder.png]]}
DB[13592]={id=13592,name=[[A Valiant's Field Training]],level=80,minLevel=77,giver=[[Sir Marcus Barlowe]],giverType=[[NPC]],giverId=33222,ender=[[Sir Marcus Barlowe]],enderType=[[NPC]],enderId=33222,wowhead=[[https://www.wowhead.com/wotlk/quest=13592]],image=[[assets/images/quests/placeholder.png]],desc=[[The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy. Travel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.]],logDesc=[[Sir Marcus Barlowe at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.]],rewards={{id=44987,qty=1}}}
DB[13593]={id=13593,name=[[Valiant Of Stormwind]],level=80,minLevel=77,giver=[[Marshal Jacob Alerius]],giverType=[[NPC]],giverId=33225,ender=[[Marshal Jacob Alerius]],enderType=[[NPC]],enderId=33225,rewardNextId=13718,wowhead=[[https://www.wowhead.com/wotlk/quest=13593]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Stormwind's tournament delegation? You will train and rise through the ranks as you have before, but when you are named a champion of Stormwind, your squire will have the option of carrying our banner into battle.]],logDesc=[[Speak with Marshal Jacob Alerius again if you wish to become a valiant of Stormwind.]]}
DB[13600]={id=13600,name=[[A Worthy Weapon]],level=80,minLevel=77,giver=[[Marshal Jacob Alerius]],giverType=[[NPC]],giverId=33225,ender=[[Marshal Jacob Alerius]],enderType=[[NPC]],enderId=33225,wowhead=[[https://www.wowhead.com/wotlk/quest=13600]],image=[[assets/images/quests/placeholder.png]],desc=[[Of all the times to have such rotten luck! My tournament blade has gone missing and I need it for a match this afternoon. One of the bards tells me that travelers used to present winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to Drak'Mar lake in northeastern Dragonblight, near its border with Zul'Drak and Grizzly Hills.]],logDesc=[[Bring the Blade of Drak'Mar to Marshal Jacob Alerius at the Argent Tournament Grounds.]],rewards={{id=44987,qty=2}}}
DB[13603]={id=13603,name=[[A Blade Fit For A Champion]],level=80,minLevel=77,giver=[[Marshal Jacob Alerius]],giverType=[[NPC]],giverId=33225,ender=[[Marshal Jacob Alerius]],enderType=[[NPC]],enderId=33225,wowhead=[[https://www.wowhead.com/wotlk/quest=13603]],image=[[assets/images/quests/placeholder.png]],desc=[[Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost. There's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, $N. Otherwise, you'll catch warts.]],logDesc=[[Retrieve the Ashwood Brand and bring it to Marshal Jacob Alerius at the Argent Tournament Grounds.]],rewards={{id=44987,qty=2}}}
DB[13604]={id=13604,zoneId=4273,name=[[Archivum Data Disc]],level=80,minLevel=80,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13604]],image=[[assets/images/quests/placeholder.png]],desc=[[This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections.  Engraved along its edge, bold runes spell out the word "ARCHIVUM." There must be a device inside Ulduar capable of reading the disc.]],logDesc=[[Bring the Archivum Data Disc to the Archivum Console in Ulduar.]]}
DB[13606]={id=13606,zoneId=4273,name=[[Freya's Sigil]],level=80,minLevel=80,giver=[[Prospector Doren]],giverType=[[NPC]],giverId=33956,ender=[[Prospector Doren]],enderType=[[NPC]],enderId=33956,prevId=13607,nextId=13614,exGroup=-13611,wowhead=[[https://www.wowhead.com/wotlk/quest=13606]],image=[[assets/images/quests/placeholder.png]],desc=[[Freya's Sigil is going to be one of the tougher ones, I reckon. According to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark.  Should any of the elders be harmed, the Sigil's integrity will be compromised. Sparing the elders, however, means that Freya will be more powerful when you face her. What can I say, $N.  We're stuck between a rock and hard place.]],logDesc=[[Prospector Doren at the Archivum in Ulduar wants you to obtain Freya's Sigil. For more information on obtaining Freya's Sigil consult the Archivum Console.]]}
DB[13607]={id=13607,zoneId=4273,name=[[The Celestial Planetarium]],level=80,minLevel=80,giver=[[Prospector Doren]],giverType=[[NPC]],giverId=33956,ender=[[Prospector Doren]],enderType=[[NPC]],enderId=33956,prevId=13604,wowhead=[[https://www.wowhead.com/wotlk/quest=13607]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen, $glad:lass;!  Azeroth's fate is at stake here. Our only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters. Locate the Celestial Planetarium and come back with any information you get.  We might still have some time to prepare for Algalon's arrival.]],logDesc=[[Prospector Doren at the Archivum in Ulduar wants you to locate the entrance to the Celestial Planetarium.]]}
DB[13609]={id=13609,zoneId=4273,name=[[Hodir's Sigil]],level=80,minLevel=80,giver=[[Prospector Doren]],giverType=[[NPC]],giverId=33956,ender=[[Prospector Doren]],enderType=[[NPC]],enderId=33956,prevId=13607,nextId=13614,exGroup=-13611,wowhead=[[https://www.wowhead.com/wotlk/quest=13609]],image=[[assets/images/quests/placeholder.png]],desc=[[Hodir's Sigil won't be easy to obtain.  Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it! Check the Archivum console if you need more information.  That thing contains more knowledge than all of the world's libraries put together!]],logDesc=[[Prospector Doren at the Archivum in Ulduar wants you to obtain Hodir's Sigil. For more information on obtaining Hodir's Sigil, consult the Archivum Console.]]}
DB[13610]={id=13610,zoneId=4273,name=[[Thorim's Sigil]],level=80,minLevel=80,giver=[[Prospector Doren]],giverType=[[NPC]],giverId=33956,ender=[[Prospector Doren]],enderType=[[NPC]],enderId=33956,prevId=13607,nextId=13614,exGroup=-13611,wowhead=[[https://www.wowhead.com/wotlk/quest=13610]],image=[[assets/images/quests/placeholder.png]],desc=[[Thorim's not himself, $N.  He's come under a dark influence. An evil presence under the guise of an illusion pretends to be his lost wife, Sif. Ye can't let him be overcome by this impostor's spell.  If he does, the location of his sigil might forever be lost! Yer going to have to beat some sense into him and yer going to have to do it quick. As always, the Archivum Console will give ye all the gory details... even the ones ye don't like.]],logDesc=[[Prospector Doren at the Archivum in Ulduar wants you to obtain Thorim's Sigil. For more information on obtaining Thorim's Sigil consult the Archivum Console.]]}
DB[13611]={id=13611,zoneId=4273,name=[[Mimiron's Sigil]],level=80,minLevel=80,giver=[[Prospector Doren]],giverType=[[NPC]],giverId=33956,ender=[[Prospector Doren]],enderType=[[NPC]],enderId=33956,prevId=13607,nextId=13614,exGroup=-13611,wowhead=[[https://www.wowhead.com/wotlk/quest=13611]],image=[[assets/images/quests/placeholder.png]],desc=[[Mimiron's a clever one.  His entire abode is rigged with some sort of self-destruction mechanism. Unfortunately yer gonna have to race against it if ye want to get his sigil.  Check the Archivum Console for more details if ye need them.]],logDesc=[[Prospector Doren at the Ulduar Archivum wants you to obtain Mimiron's Sigil. For more information on obtaining Mimiron's Sigil consult the Archivum Console.]]}
DB[13614]={id=13614,zoneId=4273,name=[[Algalon]],level=80,minLevel=80,giver=[[Prospector Doren]],giverType=[[NPC]],giverId=33956,enderType=[[NPC]],prevId=13611,wowhead=[[https://www.wowhead.com/wotlk/quest=13614]],image=[[assets/images/quests/placeholder.png]],desc=[[You really did it, $N.  Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium. You best hurry, $g lad:lass;.  Time is of the essence.]],logDesc=[[Bring the Sigils of the Watchers to the Archivum Console in Ulduar.]],rewards={{id=45796,qty=1},{id=45875,qty=1}}}
DB[13616]={id=13616,name=[[The Edge Of Winter]],level=80,minLevel=77,giver=[[Marshal Jacob Alerius]],giverType=[[NPC]],giverId=33225,ender=[[Marshal Jacob Alerius]],enderType=[[NPC]],enderId=33225,wowhead=[[https://www.wowhead.com/wotlk/quest=13616]],image=[[assets/images/quests/placeholder.png]],desc=[[Curse that death knight for breaking my sword! In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, $N.]],logDesc=[[Marshal Jacob Alerius at the Argent Tournament Grounds wants you to bring him Winter's Edge.]],rewards={{id=44987,qty=2}}}
DB[13622]={id=13622,zoneId=4273,name=[[Ancient History]],level=80,minLevel=80,giverType=[[NPC]],enderType=[[NPC]],nextId=13629,rewardNextId=13629,wowhead=[[https://www.wowhead.com/wotlk/quest=13622]],image=[[assets/images/quests/placeholder.png]],desc=[[The pieces fit together to form an elegant hammer.  Its construction appears to be at least partially Titan in nature. The console inside the Archivum might have some information regarding this artifact.]],logDesc=[[Bring the Shattered Fragments of Val'anyr to the Archivum Console in the Archivum in Ulduar.]]}
DB[13625]={id=13625,name=[[Learning The Reins]],level=80,minLevel=77,giver=[[Scout Shalyndria]],giverType=[[NPC]],giverId=33647,ender=[[Scout Shalyndria]],enderType=[[NPC]],enderId=33647,wowhead=[[https://www.wowhead.com/wotlk/quest=13625]],image=[[assets/images/quests/placeholder.png]],desc=[[Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds. Visit the stables outside the pavilion, equip your lance, and mount up on the Quel'dorei steed. Familiarize yourself with the tactics available to you and use them to defeat the three different kinds of training dummies.]],logDesc=[[Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets and then return to Scout Shalyndria at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or the Silver Covenant Pavilion.]],rewards={{id=45192,qty=2}}}
DB[13627]={id=13627,name=[[Jack Me Some Lumber]],level=80,minLevel=77,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13627]],image=[[assets/images/quests/placeholder.png]],desc=[[Come closer. No, not too close. Don't want any unnecessary suspicion now, do we? This coliseum requires more lumber than we've stockpiled and there's no way I'm going to pay to have it shipped in from Grizzly Hills. At the western end of Crystalsong Forest, by the Great Tree, grow a number of young Crystalsong oaks. They'd provide just the kind of planking we need for building and scaffolding. Take this axe, use it to fell the trees and then hew them into planks, but don't let anyone see you!]],logDesc=[[Bring 12 Rough Hewn Planks to Bezzle Blastbolt at the Argent Tournament Grounds.]]}
DB[13629]={id=13629,zoneId=4445,name=[[Val'anyr, Hammer of Ancient Kings]],level=80,minLevel=80,giverType=[[NPC]],enderType=[[NPC]],prevId=13622,wowhead=[[https://www.wowhead.com/wotlk/quest=13629]],image=[[assets/images/quests/placeholder.png]],desc=[[The Archivum Console has hinted at a possible way to rebind the fragments of Val'anyr:  you must get the fragments inside the physical form of the being known as Yogg-Saron. It sounds like a long shot, but for an artifact of such power you think the risk might just be worth it.]],logDesc=[[Throw the Shattered Pieces of Val'anyr into Yogg-Saron's maw while he's casting Deafening Roar and defeat Yogg-Saron and recover the Reforged Hammer of Ancient Kings. This can only be completed in Heroic mode and only if at least one Ulduar Watcher is not assisting you.]],rewards={{id=46017,qty=1}}}
DB[13631]={id=13631,zoneId=4273,name=[[All Is Well That Ends Well]],level=80,minLevel=80,giverType=[[NPC]],ender=[[Rhonin]],enderType=[[NPC]],enderId=16128,wowhead=[[https://www.wowhead.com/wotlk/quest=13631]],image=[[assets/images/quests/placeholder.png]],desc=[[We'd best hurry now, $N.  We're going to have to transmit the reply-code from Dalaran. Take it to Rhonin, I will meet you there.]],logDesc=[[Take the Reply-Code Alpha to Rhonin in Dalaran.]],choiceRewards={{id=46320,qty=1},{id=46321,qty=1},{id=46322,qty=1},{id=46323,qty=1}}}
DB[13633]={id=13633,name=[[The Black Knight of Westfall?]],level=80,minLevel=77,giver=[[Crusader Rhydalla]],giverType=[[NPC]],giverId=33417,ender=[[Crusader Rhydalla]],enderType=[[NPC]],enderId=33417,nextId=13641,rewardNextId=13641,wowhead=[[https://www.wowhead.com/wotlk/quest=13633]],image=[[assets/images/quests/placeholder.png]],desc=[[No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end. Of course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background. He claims to be descended from the Cooper family of Westfall. Would you visit their residence in the western part of Moonbrook in Westfall? See if you can find any proof of his story.]],logDesc=[[Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings.]]}
DB[13634]={id=13634,name=[[The Black Knight of Silverpine?]],level=80,minLevel=77,giver=[[Crusader Rhydalla]],giverType=[[NPC]],giverId=33417,ender=[[Crusader Rhydalla]],enderType=[[NPC]],enderId=33417,nextId=13641,rewardNextId=13641,wowhead=[[https://www.wowhead.com/wotlk/quest=13634]],image=[[assets/images/quests/placeholder.png]],desc=[[No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end. Of course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background. He claims to hail from Valgan's Field in Silverpine Forest. It's a small farm on the western shore of Lordamere Lake. Would you visit the farm and let me know if there's any truth to his story?]],logDesc=[[Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings.]]}
DB[13641]={id=13641,name=[[The Seer's Crystal]],level=80,minLevel=77,giver=[[Crusader Rhydalla]],giverType=[[NPC]],giverId=33417,ender=[[Crusader Rhydalla]],enderType=[[NPC]],enderId=33417,nextId=13643,wowhead=[[https://www.wowhead.com/wotlk/quest=13641]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that we know there's no truth to the Black Knight's stories, we must find a way to connect him to the murdered knights. I know a way to reveal the truth about how they died, but it requires a rare material. We must gain a seer's crystal, found only among the unbound seers who congregate near night elf ruins in the Forlorn Woods in the central part of Crystalsong Forest. Find one of these seers, $N, and bring me the crystal it holds.]],logDesc=[[Bring a Seer's Crystal to Crusader Rhydalla at the Argent Tournament Grounds.]]}
DB[13643]={id=13643,name=[[The Stories Dead Men Tell]],level=80,minLevel=77,giver=[[Crusader Rhydalla]],giverType=[[NPC]],giverId=33417,ender=[[Crusader Rhydalla]],enderType=[[NPC]],enderId=33417,prevId=13641,rewardNextId=13654,wowhead=[[https://www.wowhead.com/wotlk/quest=13643]],image=[[assets/images/quests/placeholder.png]],desc=[[The crystal will reveal the truth about how three of the tournament's combatants died. Take it with you to the graveyard east of the Tournament Grounds and use it before the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip. If indeed these men were murdered, then we must find a way to tie it to the Black Knight before he strikes again. Look closely at what the crystal tells you, $N, for we must be certain these deaths were not accidental.]],logDesc=[[Use the Seer's Crystal at the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip to determine how they died, then return to Crusader Rhydalla.]]}
DB[13649]={id=13649,name=[[Justin's Fun Test]],name_loc=[[Justin's Fun Test]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-5168,poiY=-543,wowhead=[[https://www.wowhead.com/wotlk/quest=13649]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey there!  You look like you can handle your brew.  But can you handle your brew mug?  The Dark Irons have come back with a vengeance to ruin our celebration.  Tossing mugs at them is the best way to stop them, but first, let's see if you can toss one at old S.T.O.U.T. here. It's easy, pick up a complimentary sampler and take a drink.  Just make sure you're facing S.T.O.U.T.  Talk to me after you've hit him 5 times.]],logDesc=[[Use the Complimentary Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Boxey Boltspinner.]],rewards={{id=37829,qty=10}}}
DB[13654]={id=13654,name=[[There's Something About the Squire]],level=80,minLevel=77,giver=[[Crusader Rhydalla]],giverType=[[NPC]],giverId=33417,ender=[[Crusader Rhydalla]],enderType=[[NPC]],enderId=33417,prevId=13643,rewardNextId=13663,wowhead=[[https://www.wowhead.com/wotlk/quest=13654]],image=[[assets/images/quests/placeholder.png]],desc=[[Every day, the Black Knight's squire, Maloric, makes a big show of heading to Crystalsong Forest with his axe over his shoulder. He wants us to believe he's chopping wood, but he never returns with more than a few twigs. He usually goes toward the ruins southwest of the Mirror of Twilight. He spends a lot of time out there, even for a squire with responsibilities to his knight. Find a way to distract or incapacitate him and search him. If he's up to something, we'll know it.]],logDesc=[[Obtain a Large Femur from a Skeletal Woodcutter and use it to incapacitate Maloric. Search Maloric for evidence, then report back to Crusader Rhydalla at the Argent Tournament Grounds.]]}
DB[13662]={id=13662,zoneId=51,name=[[Gaining Acceptance]],name_loc=[[Conseguir aceptación]],level=60,minLevel=45,giver=[[Master Smith Burninate]],giver_loc=[[Maestro herrero Cremación]],giverType=[[NPC]],giverId=14624,ender=[[Master Smith Burninate]],ender_loc=[[Maestro herrero Cremación]],enderType=[[NPC]],enderId=14624,prevId=7722,poiX=-6524,poiY=-1189,wowhead=[[https://www.wowhead.com/wotlk/quest=13662]],image=[[assets/images/quests/placeholder.png]]}
DB[13663]={id=13663,name=[[The Black Knight's Orders]],level=80,minLevel=77,giver=[[Crusader Rhydalla]],giverType=[[NPC]],giverId=33417,ender=[[Crusader Rhydalla]],enderType=[[NPC]],enderId=33417,prevId=13654,wowhead=[[https://www.wowhead.com/wotlk/quest=13663]],image=[[assets/images/quests/placeholder.png]],desc=[[We must discover who sent the Black Knight to the tournament and what his master hopes to gain by killing the competitors. The Kirin Tor has offered to help in this matter and provided us with something to help our search. Take this enchanted bridle to the Black Knight's camp on the eastern edge of the tournament grounds and use it to gain control over the Black Knight's gryphon. The bridle's magic will force the gryphon to take you to his master's home. Search it and return with anything you find.]],logDesc=[[Use the Enchanted Bridle to gain control of the Black Knight's Gryphon and ride it to its destination. Once you have arrived, recover the Stolen Tournament Invitation and the Black Knight's Orders and bring them to Crusader Rhydalla at the Argent Tournament Grounds.]]}
DB[13664]={id=13664,name=[[The Black Knight's Fall]],level=80,minLevel=77,giver=[[Crusader Rhydalla]],giverType=[[NPC]],giverId=33417,ender=[[Crusader Rhydalla]],enderType=[[NPC]],enderId=33417,prevId=13663,wowhead=[[https://www.wowhead.com/wotlk/quest=13664]],image=[[assets/images/quests/placeholder.png]],desc=[[We must put an end to the Black Knight's scheming, and show those who oppose us that we will not stand by and allow our champions to be murdered. By now, he will suspect that someone is on his trail. Challenge him in the light of day, where he cannot refuse or murder in the dark, $N. Use my argent charger for the battle. It's housed in the stables. Speak to Squire Cavin at the Ring of Champions. The squire will call the Black Knight to battle, but you will make him answer for his crimes.]],logDesc=[[Defeat the Black Knight and then speak to Crusader Rhydalla at the Argent Tournament Grounds.]]}
DB[13665]={id=13665,name=[[The Grand Melee]],level=80,minLevel=77,giver=[[Captain Joseph Holley]],giverType=[[NPC]],giverId=33223,ender=[[Captain Joseph Holley]],enderType=[[NPC]],enderId=33223,wowhead=[[https://www.wowhead.com/wotlk/quest=13665]],image=[[assets/images/quests/placeholder.png]],desc=[[The grand melee is the most important of the tournament's competitions. The people of Stormwind adore their knights and are looking forward to seeing us win the melee. To that end, they've been honing their skills against the other valiants. I suggest you do the same. Go to the stables outside the pavilion, equip your lance, mount the stabled Elwynn steed, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent. ]],logDesc=[[Bring 3 Marks of the Valiant to Captain Joseph Holley at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.]],rewards={{id=44987,qty=1}}}
DB[13666]={id=13666,name=[[A Blade Fit For A Champion]],level=80,minLevel=77,giver=[[Arcanist Taelis]],giverType=[[NPC]],giverId=33625,ender=[[Arcanist Taelis]],enderType=[[NPC]],enderId=33625,wowhead=[[https://www.wowhead.com/wotlk/quest=13666]],image=[[assets/images/quests/placeholder.png]],desc=[[Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons. There's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, $N. Otherwise, you'll catch warts.]],logDesc=[[Retrieve the Ashwood Brand and bring it to Arcanist Taelis at the Argent Tournament Grounds.]],rewards={{id=45192,qty=2}}}
DB[13667]={id=13667,name=[[The Argent Tournament]],level=80,minLevel=77,giver=[[Justicar Mariel Trueheart]],giverType=[[NPC]],giverId=33817,ender=[[Arcanist Taelis]],enderType=[[NPC]],enderId=33625,rewardNextId=13828,wowhead=[[https://www.wowhead.com/wotlk/quest=13667]],image=[[assets/images/quests/placeholder.png]],desc=[[We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy. Arcanist Taelis is the Silver Covenant's representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Alliance tent in the northeastern part of the grounds.]],logDesc=[[Speak with Arcanist Taelis at the Argent Tournament grounds to enroll in the tournament.]]}
DB[13668]={id=13668,name=[[The Argent Tournament]],level=80,minLevel=77,giver=[[Justicar Mariel Trueheart]],giverType=[[NPC]],giverId=33817,ender=[[Magister Edien Sunhollow]],enderType=[[NPC]],enderId=33542,rewardNextId=13829,wowhead=[[https://www.wowhead.com/wotlk/quest=13668]],image=[[assets/images/quests/placeholder.png]],desc=[[We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy. Magister Edien Sunhollow is the Sunreaver representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Horde tent in the southeastern part of the grounds. ]],logDesc=[[Speak with Magister Edien Sunhollow at the Argent Tournament grounds to enroll in the tournament.]]}
DB[13669]={id=13669,name=[[A Worthy Weapon]],level=80,minLevel=77,giver=[[Arcanist Taelis]],giverType=[[NPC]],giverId=33625,ender=[[Arcanist Taelis]],enderType=[[NPC]],enderId=33625,wowhead=[[https://www.wowhead.com/wotlk/quest=13669]],image=[[assets/images/quests/placeholder.png]],desc=[[Our champions have taken a liking to ancient weapons produced here in Northrend. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.]],logDesc=[[Bring the Blade of Drak'Mar to Arcanist Taelis at the Argent Tournament Grounds.]],rewards={{id=45192,qty=2}}}
DB[13670]={id=13670,name=[[The Edge Of Winter]],level=80,minLevel=77,giver=[[Arcanist Taelis]],giverType=[[NPC]],giverId=33625,ender=[[Arcanist Taelis]],enderType=[[NPC]],enderId=33625,wowhead=[[https://www.wowhead.com/wotlk/quest=13670]],image=[[assets/images/quests/placeholder.png]],desc=[[The Ironforge grand champion's squire told me an intriguing story. In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, $N.]],logDesc=[[Arcanist Taelis at the Argent Tournament Grounds wants you to bring him Winter's Edge.]],rewards={{id=45192,qty=2}}}
DB[13671]={id=13671,name=[[Training In The Field]],level=80,minLevel=77,giver=[[Avareth Swiftstrike]],giverType=[[NPC]],giverId=33646,ender=[[Avareth Swiftstrike]],enderType=[[NPC]],enderId=33646,wowhead=[[https://www.wowhead.com/wotlk/quest=13671]],image=[[assets/images/quests/placeholder.png]],desc=[[The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament. Travel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.]],logDesc=[[Avareth Swiftstrike at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment.]],rewards={{id=45192,qty=1}}}
DB[13672]={id=13672,name=[[Up To The Challenge]],level=80,minLevel=77,giver=[[Arcanist Taelis]],giverType=[[NPC]],giverId=33625,ender=[[Arcanist Taelis]],enderType=[[NPC]],enderId=33625,rewardNextId=13679,wowhead=[[https://www.wowhead.com/wotlk/quest=13672]],image=[[assets/images/quests/placeholder.png]],desc=[[When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant. When you are ready to begin the challenge, return to me.]],logDesc=[[Present Arcanist Taelis at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge.]]}
DB[13673]={id=13673,name=[[A Blade Fit For A Champion]],level=80,minLevel=77,giver=[[Magister Edien Sunhollow]],giverType=[[NPC]],giverId=33542,ender=[[Magister Edien Sunhollow]],enderType=[[NPC]],enderId=33542,wowhead=[[https://www.wowhead.com/wotlk/quest=13673]],image=[[assets/images/quests/placeholder.png]],desc=[[Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons. There's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, $N. Otherwise, you'll catch warts.]],logDesc=[[Retrieve the Ashwood Brand and bring it to Magister Edien Sunhollow at the Argent Tournament Grounds.]],rewards={{id=45192,qty=2}}}
DB[13674]={id=13674,name=[[A Worthy Weapon]],level=80,minLevel=77,giver=[[Magister Edien Sunhollow]],giverType=[[NPC]],giverId=33542,ender=[[Magister Edien Sunhollow]],enderType=[[NPC]],enderId=33542,wowhead=[[https://www.wowhead.com/wotlk/quest=13674]],image=[[assets/images/quests/placeholder.png]],desc=[[Our champions have taken a liking to ancient weapons produced here in Northrend. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.]],logDesc=[[Bring the Blade of Drak'Mar to Magister Edien Sunhollow at the Argent Tournament Grounds.]],rewards={{id=45192,qty=2}}}
DB[13675]={id=13675,name=[[The Edge Of Winter]],level=80,minLevel=77,giver=[[Magister Edien Sunhollow]],giverType=[[NPC]],giverId=33542,ender=[[Magister Edien Sunhollow]],enderType=[[NPC]],enderId=33542,wowhead=[[https://www.wowhead.com/wotlk/quest=13675]],image=[[assets/images/quests/placeholder.png]],desc=[[I heard an interesting story from one of the Ogrimmar valiants. In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, $N.]],logDesc=[[Magister Edien Sunhollow at the Argent Tournament Grounds wants you to bring him Winter's Edge.]],rewards={{id=45192,qty=2}}}
DB[13676]={id=13676,name=[[Training In The Field]],level=80,minLevel=77,giver=[[Amariel Sunsworn]],giverType=[[NPC]],giverId=33658,ender=[[Amariel Sunsworn]],enderType=[[NPC]],enderId=33658,wowhead=[[https://www.wowhead.com/wotlk/quest=13676]],image=[[assets/images/quests/placeholder.png]],desc=[[The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament. Travel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.]],logDesc=[[Amariel Sunsworn at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment.]],rewards={{id=45192,qty=1}}}
DB[13677]={id=13677,name=[[Learning The Reins]],level=80,minLevel=77,giver=[[Galathia Brightdawn]],giverType=[[NPC]],giverId=33659,ender=[[Galathia Brightdawn]],enderType=[[NPC]],enderId=33659,wowhead=[[https://www.wowhead.com/wotlk/quest=13677]],image=[[assets/images/quests/placeholder.png]],desc=[[Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds. Visit the stables outside the pavilion, equip your lance, and mount up on the Sunreaver hawkstrider. Familiarize yourself with the mount and use its abilities to defeat the three different kinds of training dummies.  ]],logDesc=[[Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets, and then return to Galathia Brightdawn at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or the Sunreaver Pavilion.]],rewards={{id=45192,qty=2}}}
DB[13678]={id=13678,name=[[Up To The Challenge]],level=80,minLevel=77,giver=[[Magister Edien Sunhollow]],giverType=[[NPC]],giverId=33542,ender=[[Magister Edien Sunhollow]],enderType=[[NPC]],enderId=33542,rewardNextId=13680,wowhead=[[https://www.wowhead.com/wotlk/quest=13678]],image=[[assets/images/quests/placeholder.png]],desc=[[When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant. When you are ready to begin the challenge, return to me.]],logDesc=[[Present Magister Edien Sunhollow at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge.]]}
DB[13679]={id=13679,name=[[The Aspirant's Challenge]],level=80,minLevel=77,giver=[[Arcanist Taelis]],giverType=[[NPC]],giverId=33625,ender=[[Arcanist Taelis]],enderType=[[NPC]],enderId=33625,prevId=13672,wowhead=[[https://www.wowhead.com/wotlk/quest=13679]],image=[[assets/images/quests/placeholder.png]],desc=[[You have trained hard as an aspirant, $N, and now the time has come to test your mounted combat skills against a skilled opponent. Equip your lance, then go to the stables outside the pavilion and mount up on the stabled Quel'dorei steed. At the Aspirants' Ring on the northern side of the tournament grounds, you'll find Squire David. He'll make certain that you're ready for the fight and call out your opponent. Good luck, $N. May your horse be steady and your aim true.]],logDesc=[[Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Arcanist Taelis at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.]]}
DB[13680]={id=13680,name=[[The Aspirant's Challenge]],level=80,minLevel=77,giver=[[Magister Edien Sunhollow]],giverType=[[NPC]],giverId=33542,ender=[[Magister Edien Sunhollow]],enderType=[[NPC]],enderId=33542,prevId=13678,wowhead=[[https://www.wowhead.com/wotlk/quest=13680]],image=[[assets/images/quests/placeholder.png]],desc=[[You have trained hard as an aspirant, $N, and now the time has come to test your mounted combat skills against an experienced opponent. Equip your lance, then go to the stables outside the pavilion and mount the Sunreaver hawkstrider. At the Aspirants' Ring on the northern side of the tournament grounds, you'll find a human child called Squire David. He'll ask if you're ready for the fight and call out your opponent. Good luck, $N. May your mount be steady and your aim true.]],logDesc=[[Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Magister Edien Sunhollow at the Argent Tournament Grounds.]]}
DB[13681]={id=13681,name=[[A Chip Off the Ulduar Block]],level=80,minLevel=77,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13681]],image=[[assets/images/quests/placeholder.png]],desc=[[Getting stone for this job has been a nightmare, I tell ya! There are tons of stone available from ruins in safe places, but those holier-than-thou paladins won't go for it. Something about 'priceless artifacts.' Anyway, whining about that isn't going to get this place built. There are tons of crumbling titan ruins in the Foot Steppes and at the Inventor's Library in Storm Peaks. Take my, uh, 'chisel' with you and see if you can break those huge blocks into useful pieces.]],logDesc=[[Bring 15 Small Stone Blocks to Bozzle Blastbolt at the Argent Tournament Grounds.]]}
DB[13682]={id=13682,name=[[Threat From Above]],level=80,minLevel=77,giver=[[Eadric the Pure]],giverType=[[NPC]],giverId=33759,ender=[[Eadric the Pure]],enderType=[[NPC]],enderId=33759,prevId=13794,wowhead=[[https://www.wowhead.com/wotlk/quest=13682]],image=[[assets/images/quests/placeholder.png]],desc=[[Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned's infiltrator. He doesn't believe that they will stop just because their Black Knight has been defeated. Our skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don't intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.]],logDesc=[[Eadric the Pure at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.]],rewards={{id=44990,qty=2}},choiceRewards={{id=46114,qty=1},{id=45724,qty=1}}}
DB[13684]={id=13684,name=[[A Valiant Of Stormwind]],level=80,minLevel=77,giver=[[Arcanist Taelis]],giverType=[[NPC]],giverId=33625,ender=[[Marshal Jacob Alerius]],enderType=[[NPC]],enderId=33225,prevId=13679,wowhead=[[https://www.wowhead.com/wotlk/quest=13684]],image=[[assets/images/quests/placeholder.png]],desc=[[You've proven yourself worthy of competing under the banner of Stormwind, $N. Now, you should introduce yourself to Marshal Jacob Alerius, who leads the Stormwind delegation. As Stormwind's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, $N, and I wish you luck in the competition ahead.]],logDesc=[[Speak with Marshal Jacob Alerius at the Argent Tournament Grounds  to become a valiant of Stormwind.]]}
DB[13685]={id=13685,name=[[A Valiant Of Ironforge]],level=80,minLevel=77,giver=[[Arcanist Taelis]],giverType=[[NPC]],giverId=33625,ender=[[Lana Stouthammer]],enderType=[[NPC]],enderId=33312,prevId=13679,wowhead=[[https://www.wowhead.com/wotlk/quest=13685]],image=[[assets/images/quests/placeholder.png]],desc=[[You've proven yourself worthy of competing under the banner of Ironforge, $N. Now, you should introduce yourself to Lana Stouthammer, who leads the Ironforge delegation. As Ironforge's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, $N, and I wish you luck in the competition ahead.]],logDesc=[[Speak with Lana Stouthammer at the Argent Tournament Grounds  to become a valiant of Ironforge.]]}
DB[13686]={id=13686,name=[[Alliance Tournament Eligibility Marker]],level=80,minLevel=77,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13686]],image=[[assets/images/quests/placeholder.png]]}
DB[13687]={id=13687,name=[[Horde Tournament Eligibility Marker]],level=80,minLevel=77,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13687]],image=[[assets/images/quests/placeholder.png]]}
DB[13688]={id=13688,name=[[A Valiant Of Gnomeregan]],level=80,minLevel=77,giver=[[Arcanist Taelis]],giverType=[[NPC]],giverId=33625,ender=[[Ambrose Boltspark]],enderType=[[NPC]],enderId=33335,prevId=13679,wowhead=[[https://www.wowhead.com/wotlk/quest=13688]],image=[[assets/images/quests/placeholder.png]],desc=[[You've proven yourself worthy of competing under the banner of Gnomeregan, $N. Now, you should introduce yourself to Ambrose Boltspark, who leads the Gnomeregan delegation. As the gnomish grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, $N, and I wish you luck in the competition ahead.]],logDesc=[[Speak with Ambrose Boltspark at the Argent Tournament Grounds  to become a valiant of Gnomeregan.]]}
DB[13689]={id=13689,name=[[A Valiant Of Darnassus]],level=80,minLevel=77,giver=[[Arcanist Taelis]],giverType=[[NPC]],giverId=33625,ender=[[Jaelyne Evensong]],enderType=[[NPC]],enderId=33592,prevId=13679,wowhead=[[https://www.wowhead.com/wotlk/quest=13689]],image=[[assets/images/quests/placeholder.png]],desc=[[You've proven yourself worthy of competing under the banner of Darnassus, $N. Now, you should introduce yourself to Jaelyne Evensong, who leads the Darnassus delegation. As the night elf grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, $N, and I wish you luck in the competition ahead.]],logDesc=[[Speak with Jaelyne Evensong at the Argent Tournament Grounds  to become a valiant of Darnassus.]]}
