DB[13692]={id=13692,name=[[The Sword and the Sea]],level=80,minLevel=77,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13692]],image=[[assets/images/quests/placeholder.png]],desc=[[My sword was lost at sea.  Catch it and bring it back!]],logDesc=[[Old Man Barlo in Crystalsong Forest wants you to bring him the Sword of Knighthood.]],rewards={{id=34863,qty=1}}}
