DB[13696]={id=13696,name=[[A Valiant Of Silvermoon]],level=80,minLevel=77,giver=[[Magister Edien Sunhollow]],giverType=[[NPC]],giverId=33542,ender=[[Eressea Dawnsinger]],enderType=[[NPC]],enderId=33379,prevId=13680,wowhead=[[https://www.wowhead.com/wotlk/quest=13696]],image=[[assets/images/quests/placeholder.png]],desc=[[You've proven yourself worthy of competing under the banner of Silvermoon, $N. Now, you should speak with Eressea Dawnsinger, who leads the Silvermoon delegation. As Silvermoon's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, $N, and I wish you luck in the competition ahead.]],logDesc=[[Speak with Eressea Dawnsinger at the Argent Tournament Grounds  to become a valiant of Silvermoon.]]}
DB[13697]={id=13697,name=[[The Valiant's Charge]],level=80,minLevel=77,giver=[[Mokra the Skullcrusher]],giverType=[[NPC]],giverId=33361,ender=[[Mokra the Skullcrusher]],enderType=[[NPC]],enderId=33361,rewardNextId=13726,wowhead=[[https://www.wowhead.com/wotlk/quest=13697]],image=[[assets/images/quests/placeholder.png]],desc=[[In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents. The valiants are a spirited lot, competing amongst themselves for honor and notoriety. Train as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.]],logDesc=[[Bring 25 Valiant's Seals to Mokra the Skullcrusher at the Argent Tournament Grounds.]]}
DB[13699]={id=13699,name=[[The Valiant's Challenge]],level=80,minLevel=77,giver=[[Marshal Jacob Alerius]],giverType=[[NPC]],giverId=33225,ender=[[Marshal Jacob Alerius]],enderType=[[NPC]],enderId=33225,prevId=13718,wowhead=[[https://www.wowhead.com/wotlk/quest=13699]],image=[[assets/images/quests/placeholder.png]],desc=[[You are nearly ready to compete on behalf of Stormwind in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade. Go to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready. After the battle is concluded, we will speak of the outcome.]],logDesc=[[Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Marshal Jacob Alerius at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.]]}
DB[13700]={id=13700,name=[[Alliance Champion Marker]],level=80,minLevel=77,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13700]],image=[[assets/images/quests/placeholder.png]]}
DB[13701]={id=13701,name=[[Horde Champion Marker]],level=80,minLevel=77,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13701]],image=[[assets/images/quests/placeholder.png]]}
DB[13702]={id=13702,name=[[A Champion Rises]],level=80,minLevel=77,giver=[[Marshal Jacob Alerius]],giverType=[[NPC]],giverId=33225,ender=[[Justicar Mariel Trueheart]],enderType=[[NPC]],enderId=33817,prevId=13699,wowhead=[[https://www.wowhead.com/wotlk/quest=13702]],image=[[assets/images/quests/placeholder.png]],desc=[[Congratulations, $N. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities. Justicar Mariel Trueheart has asked to speak with you, $N, and to formally enter you in the champions' grand melee.]],logDesc=[[Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.]],rewards={{id=44998,qty=1},{id=44990,qty=10}}}
DB[13703]={id=13703,name=[[Valiant Of Ironforge]],level=80,minLevel=77,giver=[[Lana Stouthammer]],giverType=[[NPC]],giverId=33312,ender=[[Lana Stouthammer]],enderType=[[NPC]],enderId=33312,wowhead=[[https://www.wowhead.com/wotlk/quest=13703]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Ironforge's tournament delegation? You will train and rise through the ranks as you have before, but when you are named a champion of Ironforge, your squire will have the option of carrying our banner into battle.]],logDesc=[[Speak with Lana Stouthammer again if you wish to become a valiant of Ironforge.]]}
DB[13704]={id=13704,name=[[Valiant Of Gnomeregan]],level=80,minLevel=77,giver=[[Ambrose Boltspark]],giverType=[[NPC]],giverId=33335,ender=[[Ambrose Boltspark]],enderType=[[NPC]],enderId=33335,wowhead=[[https://www.wowhead.com/wotlk/quest=13704]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome, champion. Word of your combat prowess has already reached my ears. Gnomeregan's delegation could really benefit from a $c like you. You will train and rise through the ranks as you have before, but when you are named a champion of Gnomeregan, your squire will have the option of carrying our banner into battle.]],logDesc=[[Speak with Ambrose Boltspark again if you wish to become a valiant of Gnomeregan.]]}
DB[13705]={id=13705,name=[[Valiant Of The Exodar]],level=80,minLevel=77,giver=[[Colosos]],giverType=[[NPC]],giverId=33593,ender=[[Colosos]],enderType=[[NPC]],enderId=33593,wowhead=[[https://www.wowhead.com/wotlk/quest=13705]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome, champion. Word of your deeds has already reached my ears. Do you wish to join the Exodar's tournament delegation? You will train and rise through the ranks as you have before, but when you are named a champion of the Exodar, your squire will have the option of carrying our banner into battle.]],logDesc=[[Speak with Colosos again if you wish to become a valiant of the Exodar.]]}
DB[13706]={id=13706,name=[[Valiant Of Darnassus]],level=80,minLevel=77,giver=[[Jaelyne Evensong]],giverType=[[NPC]],giverId=33592,ender=[[Jaelyne Evensong]],enderType=[[NPC]],enderId=33592,wowhead=[[https://www.wowhead.com/wotlk/quest=13706]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome, champion. I have heard of your accomplishments and we would be honored if you would join the delegation from Darnassus. You will train and rise through the ranks as you have before, but when you are named a champion of Darnassus, your squire will have the option of carrying our banner into battle.]],logDesc=[[Speak with Jaelyne Eveonsong again if you wish to become a valiant of Darnassus.]]}
DB[13707]={id=13707,name=[[Valiant Of Orgrimmar]],level=80,minLevel=77,giver=[[Mokra the Skullcrusher]],giverType=[[NPC]],giverId=33361,ender=[[Mokra the Skullcrusher]],enderType=[[NPC]],enderId=33361,wowhead=[[https://www.wowhead.com/wotlk/quest=13707]],image=[[assets/images/quests/placeholder.png]],desc=[[So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Orgrimmar's delegation. You will train and rise through the ranks as you have before, but when you are named a champion of Orgrimmar, your gruntling will have the option of carrying our banner into battle.]],logDesc=[[Speak with Mokra the Skullcrusher again if you wish to become a valiant of Orgrimmar.]]}
DB[13708]={id=13708,name=[[Valiant Of Sen'jin]],level=80,minLevel=77,giver=[[Zul'tore]],giverType=[[NPC]],giverId=33372,ender=[[Zul'tore]],enderType=[[NPC]],enderId=33372,wowhead=[[https://www.wowhead.com/wotlk/quest=13708]],image=[[assets/images/quests/placeholder.png]],desc=[[Greetings, champion. If you are willing, I would welcome you into Sen'jin's tournament delegation. You will train and rise through the ranks as you have before, but when you are named a champion of Sen'jin, your gruntling will have the option of carrying our banner into battle.]],logDesc=[[Speak with Zul'tore again if you wish to become a valiant of Sen'jin.]]}
DB[13709]={id=13709,name=[[Valiant Of Thunder Bluff]],level=80,minLevel=77,giver=[[Runok Wildmane]],giverType=[[NPC]],giverId=33403,ender=[[Runok Wildmane]],enderType=[[NPC]],enderId=33403,wowhead=[[https://www.wowhead.com/wotlk/quest=13709]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome, champion. As grand champion of the Thunder Bluff delegation, I would be honored to welcome you into our ranks, if you are willing. You will train and rise through the ranks as you have before, but when you are named a champion of Thunder Bluff, your gruntling will have the option of carrying our banner into battle.]],logDesc=[[Speak with Runok Wildmane again if you wish to become a valiant of Thunder Bluff.]]}
DB[13710]={id=13710,name=[[Valiant Of Undercity]],level=80,minLevel=77,giver=[[Deathstalker Visceri]],giverType=[[NPC]],giverId=33373,ender=[[Deathstalker Visceri]],enderType=[[NPC]],enderId=33373,wowhead=[[https://www.wowhead.com/wotlk/quest=13710]],image=[[assets/images/quests/placeholder.png]],desc=[[Welcome, champion. The Forsaken delegation could always use more $cs like you. Would you join us? You will train and rise through the ranks as you have before, but when you are named a champion of the Undecity, your gruntling will have the option of carrying our banner into battle.]],logDesc=[[Speak with Deathstalker Visceri again if you wish to become a valiant of the Undercity.]]}
DB[13711]={id=13711,name=[[Valiant Of Silvermoon]],level=80,minLevel=77,giver=[[Eressea Dawnsinger]],giverType=[[NPC]],giverId=33379,ender=[[Eressea Dawnsinger]],enderType=[[NPC]],enderId=33379,wowhead=[[https://www.wowhead.com/wotlk/quest=13711]],image=[[assets/images/quests/placeholder.png]],desc=[[So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Silvermoon's delegation. You will train and rise through the ranks as you have before, but when you are named a champion of Silvermoon, your gruntling will have the option of carrying our banner into battle.]],logDesc=[[Speak with Eressea Dawnsinger again if you wish to become a valiant of Silvermoon.]]}
DB[13713]={id=13713,name=[[The Valiant's Challenge]],level=80,minLevel=77,giver=[[Lana Stouthammer]],giverType=[[NPC]],giverId=33312,ender=[[Lana Stouthammer]],enderType=[[NPC]],enderId=33312,prevId=13714,wowhead=[[https://www.wowhead.com/wotlk/quest=13713]],image=[[assets/images/quests/placeholder.png]],desc=[[You are nearly ready to compete on behalf of Ironforge in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade. Go to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready. After the battle is concluded, we will speak of the outcome.]],logDesc=[[Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Lana Stouthammer at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.]]}
DB[13714]={id=13714,name=[[The Valiant's Charge]],level=80,minLevel=77,giver=[[Lana Stouthammer]],giverType=[[NPC]],giverId=33312,ender=[[Lana Stouthammer]],enderType=[[NPC]],enderId=33312,rewardNextId=13713,wowhead=[[https://www.wowhead.com/wotlk/quest=13714]],image=[[assets/images/quests/placeholder.png]],desc=[[In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents. The valiants are a spirited lot, competing amongst themselves for honor and notoriety. Train as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.]],logDesc=[[Bring 25 Valiant's Seals to Lana Stouthammer at the Argent Tournament Grounds.]]}
