DB[13736]={id=13736,name=[[A Champion Rises]],level=80,minLevel=77,giver=[[Mokra the Skullcrusher]],giverType=[[NPC]],giverId=33361,ender=[[Justicar Mariel Trueheart]],enderType=[[NPC]],enderId=33817,prevId=13726,wowhead=[[https://www.wowhead.com/wotlk/quest=13736]],image=[[assets/images/quests/placeholder.png]],desc=[[You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of Orgrimmar! Justicar Mariel Trueheart has asked to speak with you, $N, and to formally enter you in the champions' grand melee.]],logDesc=[[Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.]],rewards={{id=45022,qty=1},{id=44990,qty=10}}}
