DB[13917]={id=13917,zoneId=490,name=[[Gorishi Grub]],name_loc=[[Larva Gorishi]],level=53,minLevel=48,giver=[[Venomhide Hatchling]],giver_loc=[[Prole de pellejo venenoso]],giverType=[[NPC]],giverId=34320,ender=[[Venomhide Hatchling]],ender_loc=[[Prole de pellejo venenoso]],enderType=[[NPC]],enderId=34320,poiX=-8050,poiY=-1547,wowhead=[[https://www.wowhead.com/wotlk/quest=13917]],image=[[assets/images/quests/placeholder.png]],desc=[[The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt. The hatchling's drawings seem to resemble various types of large insects, perhaps the gorishi silithids. The hatchling finishes his picture, then gestures at it with one short arm, snaps its jaws, and licks its lips. It must want you to go to the Slithering Scar, in center of the southern part of Un'Goro Crater, and gather silithid meat. When you have the meat, feed it to your hungry hatchling.]],logDesc=[[Your Venomhide Hatchling wants you to feed it 10 Silithid Meat.]],rewards={{id=47196,qty=1}}}
DB[13926]={id=13926,name=[[Little Orphan Roo Of The Oracles]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Oracle Orphan]],enderType=[[NPC]],enderId=33533,exGroup=13926,wowhead=[[https://www.wowhead.com/wotlk/quest=13926]],image=[[assets/images/quests/placeholder.png]],desc=[[The orphans have been looking forward to the opportunity to meet friends like you, $N. It's wonderful that you've agreed to take one into your care. Take this whistle.  With it, you will be able to call for the orphan you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact. Please, $N, call upon your orphan.  He will be excited to meet you and see the sights of Northrend with you.]],logDesc=[[Speak to Orphan Matron Aria, then use the Oracle Orphan Whistle to call the orphan you will be taking care of during Children's Week.]]}
DB[13927]={id=13927,name=[[Little Orphan Kekek Of The Wolvar]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Wolvar Orphan]],enderType=[[NPC]],enderId=33532,exGroup=13926,wowhead=[[https://www.wowhead.com/wotlk/quest=13927]],image=[[assets/images/quests/placeholder.png]],desc=[[The orphans have been looking forward to the opportunity to meet friends like you, $N. It's wonderful that you've agreed to take one into your care. Take this whistle.  With it, you will be able to call for the orphan you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact. Please, $N, call upon your orphan.  He will be excited to meet you and see the sights of Northrend with you.]],logDesc=[[Speak to Orphan Matron Aria, then use the Wolvar Orphan Whistle to call the orphan you will be taking care of during Children's Week.]]}
DB[13929]={id=13929,name=[[The Biggest Tree Ever!]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Oracle Orphan]],enderType=[[NPC]],enderId=33533,prevId=13926,nextId=1,exGroup=-13929,wowhead=[[https://www.wowhead.com/wotlk/quest=13929]],image=[[assets/images/quests/placeholder.png]],desc=[[Before there was a big war and we left the village, we remember Soo-say telling us all about the biggest tree ever! Soo-say call it Grizzlemaw or something. Soo-say tell us it in the middle Grizzle Hills. No, wait, that not what Soo-say say. Soo-say say Grizzly Hills. Now we remember! Tree is big and right in middle of Grizzly Hills. Can't miss! You take us there, oki? We see inside of giant tree? Soo-say tell us big bear men live in tree too. Maybe we see them.]],logDesc=[[Take your orphan, Roo, to visit Grizzlemaw. Make sure to call for him if he is not present when you enter the trunk of the great tree.]]}
DB[13930]={id=13930,name=[[Home Of The Bear-Men]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Wolvar Orphan]],enderType=[[NPC]],enderId=33532,prevId=13927,exGroup=-13930,wowhead=[[https://www.wowhead.com/wotlk/quest=13930]],image=[[assets/images/quests/placeholder.png]],desc=[[High Shaman Rakjak always tell stories of mighty warriors, even ones far away. Sometimes he tell stories about giant bear-men fighting great battle for tree-city. Maybe you take Kekek there, see tree, see battle! High Shaman Rakjak tell Kekek that giant tree-city Grizzlemaw stand in the middle of Grizzly Hills. Kekek never see a city before meeting orphan lady, but this city have no warriors, only men in purple dresses. Kekek want to see real warriors fight for real city.]],logDesc=[[Take your orphan, Kekek, to visit Grizzlemaw. Make sure to call for him if he is not present when you enter the trunk of the great tree.]]}
DB[13931]={id=13931,name=[[Another Year, Another Souvenir.]],name_loc=[[Otro año, otro recuerdo]],level=-1,minLevel=1,giver=[[Driz Tumblequick]],giver_loc=[[Driz Pataplaf]],giverType=[[NPC]],giverId=24510,ender=[[Blix Fixwidget]],ender_loc=[[Blix Chirimbolo]],enderType=[[NPC]],enderId=24495,prevId=11409,poiX=1175,poiY=-4293,wowhead=[[https://www.wowhead.com/wotlk/quest=13931]],image=[[assets/images/quests/placeholder.png]],desc=[[Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one. Talk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.]],logDesc=[[Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.]],rewards={{id=37892,qty=1}}}
DB[13932]={id=13932,name=[[Another Year, Another Souvenir.]],name_loc=[[Otro año, otro recuerdo]],level=-1,minLevel=1,giver=[[Pol Amberstill]],giver_loc=[[Pol Semperámbar]],giverType=[[NPC]],giverId=24468,ender=[[Belbi Quikswitch]],ender_loc=[[Belbi Tiratrastos]],enderType=[[NPC]],enderId=23710,prevId=11318,poiX=-5177,poiY=-624,wowhead=[[https://www.wowhead.com/wotlk/quest=13932]],image=[[assets/images/quests/placeholder.png]],desc=[[Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you. In any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.]],logDesc=[[Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.]],rewards={{id=37892,qty=1}}}
DB[13933]={id=13933,name=[[The Bronze Dragonshrine]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Oracle Orphan]],enderType=[[NPC]],enderId=33533,prevId=13926,nextId=1,exGroup=-13929,wowhead=[[https://www.wowhead.com/wotlk/quest=13933]],image=[[assets/images/quests/placeholder.png]],desc=[[Sometimes High-Oracle Soo-say tell stories about a shrine to dragon-things, not like great rain stone, but different. Soo-say tell us maybe we see ourselves there, but not like in a shiny. Soo-say mean we could see what we are like many years from now. You take us there? We remember shrine to bronze dragon-things in place called Dragonblight. Soo-say say great rain stone show him shrine to northeast of Wyrmrest Temple, or northwest of place dryskins call Wintergarde Keep. We go?]],logDesc=[[Take your orphan, Roo, to visit the Bronze Dragonshrine. Make sure to call for him if he is not present when you get there.]]}
DB[13934]={id=13934,name=[[The Bronze Dragonshrine]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Wolvar Orphan]],enderType=[[NPC]],enderId=33532,prevId=13927,exGroup=-13930,wowhead=[[https://www.wowhead.com/wotlk/quest=13934]],image=[[assets/images/quests/placeholder.png]],desc=[[When Kekek was a pup, he sometimes heard elders talking about a far-off shrine. Sometimes they say that bronze dragon-things there know all about future. Kekek tell you he be great warrior, now we go see. Bronze dragon-thing shrine somewhere in Dragonblight, northeast of dragon-thing temple called Wyrmrest, also northwest of man-town called Wintergarde. We go there, see future. Prove orphan-lady wrong about Kekek. Kekek warrior, not bully.]],logDesc=[[Take your orphan, Kekek, to visit the Bronze Dragonshrine. Make sure to call for him if he is not present when you get there.]]}
DB[13937]={id=13937,name=[[A Trip To The Wonderworks]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Oracle Orphan]],enderType=[[NPC]],enderId=33533,prevId=13954,wowhead=[[https://www.wowhead.com/wotlk/quest=13937]],image=[[assets/images/quests/placeholder.png]],desc=[[We have time for one more stop? We heard Dalaran has toy store, but we never get to go there. Orphan mistress says too many orphans would crowd the store. Maybe we can go, just us? We can have a small paper zeppelin? We think they have those at Wonderworks in Dalaran. We always wanted to play with one. Maybe you throw one to us?]],logDesc=[[Purchase a Small Paper Zeppelin at the Wonderworks and then throw it to your orphan, Roo.]]}
DB[13938]={id=13938,name=[[A Visit To The Wonderworks]],level=-1,minLevel=70,giver=[[Pol Amberstill]],giverType=[[NPC]],giverId=24468,ender=[[Pol Amberstill]],enderType=[[NPC]],enderId=24468,prevId=13955,wowhead=[[https://www.wowhead.com/wotlk/quest=13938]],image=[[assets/images/quests/placeholder.png]],desc=[[You take Kekek one more place? Orphan lady say Dalaran have toy store called Wonderworks, but Kekek never seen it. She say that if one orphan go, she have to take everyone. Maybe you take Kekek? Kekek seen other children playing with small paper zeppelin? Kekek hear those come from Wonderworks. Maybe you get one and throw it around with Kekek?]],logDesc=[[Purchase a Small Paper Zeppelin at the Wonderworks and then throw it to your orphan, Kekek.]]}
DB[13938]={id=13938,name=[[A Visit To The Wonderworks]],level=-1,minLevel=70,giver=[[Pol Amberstill]],giverType=[[NPC]],giverId=24468,ender=[[Wolvar Orphan]],enderType=[[NPC]],enderId=33532,prevId=13955,wowhead=[[https://www.wowhead.com/wotlk/quest=13938]],image=[[assets/images/quests/placeholder.png]],desc=[[You take Kekek one more place? Orphan lady say Dalaran have toy store called Wonderworks, but Kekek never seen it. She say that if one orphan go, she have to take everyone. Maybe you take Kekek? Kekek seen other children playing with small paper zeppelin? Kekek hear those come from Wonderworks. Maybe you get one and throw it around with Kekek?]],logDesc=[[Purchase a Small Paper Zeppelin at the Wonderworks and then throw it to your orphan, Kekek.]]}
DB[13950]={id=13950,name=[[Playmates!]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Oracle Orphan]],enderType=[[NPC]],enderId=33533,prevId=13926,nextId=1,exGroup=-13929,wowhead=[[https://www.wowhead.com/wotlk/quest=13950]],image=[[assets/images/quests/placeholder.png]],desc=[[Orphanage gets real lonely, you know? Sometimes we want to go places, meet new friends. Maybe you can take us somewheres with other hatchlings? We heard about a place called Winterfin Retreat, in the big Borean Tundra. We think it's way in the northwest, near the edge of the Coldarra-island. The orphan lady say someone brave save a bunch of hatchlings there. We think they lonely, too. We think they need friends. You take us there?]],logDesc=[[Take your orphan, Roo, to visit Winterfin Retreat. Make sure to call for him if he is not present when you get there.]]}
DB[13951]={id=13951,name=[[Playmates!]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Wolvar Orphan]],enderType=[[NPC]],enderId=33532,prevId=13927,exGroup=-13930,wowhead=[[https://www.wowhead.com/wotlk/quest=13951]],image=[[assets/images/quests/placeholder.png]],desc=[[Kekek think there not enough other pups living with orphan-lady. Maybe we go visit some others? Kekek know a tribe that lives in Dragonblight, at place called Snowfall Glade. You know? Snowfall Glade north of walrus-men town of Mo'aki Harbor and south of Ruby Dragonshrine. <Kekek scowls at the mention of the tuskarr.> You take Kekek there, to some of the villages there. Maybe we meet new wolvar, show them how fierce Frenzyheart are!]],logDesc=[[Take your orphan, Kekek, to visit Snowfall Glade. Make sure to call for him if he is not present when you get there.]]}
DB[13952]={id=13952,name=[[The Grateful Dead]],name_loc=[[Los muertos agradecidos]],level=-1,minLevel=1,giver=[[Cheerful Human Spirit]],giver_loc=[[Espíritu de humana alegre]],giverType=[[NPC]],giverId=34435,ender=[[Cheerful Human Spirit]],ender_loc=[[Espíritu de humana alegre]],enderType=[[NPC]],enderId=34435,exGroup=14166,poiX=-9338,poiY=186,wowhead=[[https://www.wowhead.com/wotlk/quest=13952]],image=[[assets/images/quests/placeholder.png]],desc=[[It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me! Might I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful... Chapman there sells the recipe, I think.]],logDesc=[[Acquire some Bread of the Dead and give it to the Cheerful Human Spirit in Stormwind's graveyard. Use an Orange Marigold to see the otherwise invisible spirit.]],rewards={{id=46831,qty=1}}}
DB[13954]={id=13954,name=[[The Dragon Queen]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Oracle Orphan]],enderType=[[NPC]],enderId=33533,prevId=13929,exGroup=-13954,wowhead=[[https://www.wowhead.com/wotlk/quest=13954]],image=[[assets/images/quests/placeholder.png]],desc=[[One of High-Oracle Soo-say's stories says Great Ones made all the dragons and a queen for the dragons, too. We want to see her! Would you take us to the top of Wyrmrest Temple? We remember Soo-say telling us the temple-thing was in the middle of Dragonblight. We really want to meet dragon queen. She must be so big and pretty. Maybe she help us find new parents. You take us?]],logDesc=[[Take your orphan, Roo, to visit Alexstrasza the Life-Binder at the top of Wyrmrest Temple. Make sure to call for him if he is not present when you get there.]]}
DB[13955]={id=13955,name=[[The Dragon Queen]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Wolvar Orphan]],enderType=[[NPC]],enderId=33532,prevId=13930,exGroup=-13955,wowhead=[[https://www.wowhead.com/wotlk/quest=13955]],image=[[assets/images/quests/placeholder.png]],desc=[[Kekek always liked dragons. Always wanted to be one, but orphan-lady said no. But she did say maybe you take Kekek to meet dragon queen. Kekek think orphan-lady have good idea for once. You take Kekek to Wyrmrest Temple in the middle of Dragonblight? Fly all the way to top to meet dragon queen. She must be really big, to be queen of all dragons. Kekek can't wait to see!]],logDesc=[[Take your orphan, Kekek, to visit Alexstrasza the Life-Binder at the top of Wyrmrest Temple. Make sure to call for him if he is not present when you get there.]]}
DB[13956]={id=13956,name=[[Meeting a Great One]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Oracle Orphan]],enderType=[[NPC]],enderId=33533,prevId=13929,exGroup=-13954,wowhead=[[https://www.wowhead.com/wotlk/quest=13956]],image=[[assets/images/quests/placeholder.png]],desc=[[High-Oracle Soo-say always tell us about how Great Ones built shrines and we give them shinies, but he never see Great Ones. No one see Great Ones, but maybe you know how to find one? Soo-say told us the Great Ones made a waygate and put it in the center of the southern part of Sholazar. Soo-say not say where it goes, but maybe it take us to a Great One! Take us through that waygate and let's find out, $N.]],logDesc=[[Take your orphan, Roo, to visit the Etymidian at the Shaper's Terrace. Make sure to call for him if he is not present when you get there.]]}
DB[13957]={id=13957,name=[[The Mighty Hemet Nesingwary]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Wolvar Orphan]],enderType=[[NPC]],enderId=33532,prevId=13930,exGroup=-13955,wowhead=[[https://www.wowhead.com/wotlk/quest=13957]],image=[[assets/images/quests/placeholder.png]],desc=[[Know who Kekek always wanted to meet? Hemet Nesingwary. Maybe you take Kekek to see him? Elder Harkek tell us all about him. He come to Sholazar to hunt biggest creatures anywhere! Even Frenzyheart elders respect Hemet Nesingwary as great hunter. Elder Harkek tell Kekek that Nesingwary Base Camp in the middle of west side of Sholazar, right on river called Seabreach Flow. We go visit and learn how to hunt like Hemet?]],logDesc=[[Take your orphan, Kekek, to visit Hemet Nesingwary at the Nesingwary Base Camp. Make sure to call for him if he is not present when you get there.]]}
DB[13959]={id=13959,name=[[Back To The Orphanage]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Orphan Matron Aria]],enderType=[[NPC]],enderId=34365,prevId=13937,wowhead=[[https://www.wowhead.com/wotlk/quest=13959]],image=[[assets/images/quests/placeholder.png]],desc=[[We had the best time with you, $N. We wish you could be our $g daddy : mama; now, but you have to take us back to Orphan Matron Aria in Dalaran. Maybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One! We going to miss you, $N. We promise to write letter sometime, oki?]],logDesc=[[Return your ward to the Dalaran orphanage by handing in the Oracle Orphan Whistle to Orphan Matron Aria in Dalaran.]]}
DB[13960]={id=13960,name=[[Back To The Orphanage]],level=-1,minLevel=70,giverType=[[NPC]],ender=[[Orphan Matron Aria]],enderType=[[NPC]],enderId=34365,prevId=13938,wowhead=[[https://www.wowhead.com/wotlk/quest=13960]],image=[[assets/images/quests/placeholder.png]],desc=[[Know what? You not so bad after all, $N. You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do. You, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes. Kekek gotta go back to orphan-lady Aria now, back in purple human city.]],logDesc=[[Return your ward to the Dalaran orphanage by handing in the Wolvar Orphan Whistle to Orphan Matron Aria in Dalaran.]]}
DB[13966]={id=13966,name=[[A Winter Veil Gift]],name_loc=[[Un obsequio del Festival de Invierno]],level=-1,minLevel=10,giver=[[Winter Veil Gift]],giver_loc=[[Obsequio del Festival de Invierno]],giverType=[[GO]],giverId=187236,ender=[[Winter Veil Gift]],ender_loc=[[Obsequio del Festival de Invierno]],enderType=[[GO]],enderId=187236,poiX=-4916,poiY=-980,wowhead=[[https://www.wowhead.com/wotlk/quest=13966]],image=[[assets/images/quests/placeholder.png]],rewards={{id=46740,qty=1}}}
DB[13986]={id=13986,zoneId=1638,name=[[An Injured Colleague]],level=73,minLevel=71,giver=[[Sorn Proudmane]],giverType=[[NPC]],giverId=35471,ender=[[Aponi Brightmane]],enderType=[[NPC]],enderId=34526,wowhead=[[https://www.wowhead.com/wotlk/quest=13986]],image=[[assets/images/quests/placeholder.png]],desc=[[The fight's been hard up here, $c, as I'm sure you know. We're holding out, but not everyone has gone unscathed. A warrior in our band, Aponi Brightmane, was taken ill by an infected wound in her arm. She's been taken back to Thunder Bluff for recuperation. It seems she left her shield here at the front in the confusion, however - could you take it to her, along with our well-wishes? Her smile is missed around here. You can find her on Elder Rise on the Bluff.]],logDesc=[[Take the Battered Tribal Shield to Aponi Brightmane on Elder Rise within Thunder Bluff.]]}
DB[13990]={id=13990,name=[[Upper Deck Promo - Chicken Mount]],name_loc=[[Upper Deck Promo - Chicken Mount]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13990]],image=[[assets/images/quests/placeholder.png]]}
DB[13997]={id=13997,zoneId=151,name=[[If You're Reading This While I'm In Combat...]],level=80,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=13997]],image=[[assets/images/quests/placeholder.png]],desc=[[Dan is the most awesome programmer in the world... the World of Warcraft! Isn't it weird that you used to not be able to talk with me at all while I was fighting?  No longer, my friend, now that Dan has made significant improvements to one of my creature flags! Celebrate with me by snuffing out the lives of these awful creatures that perpetually have me in combat.]],logDesc=[[ELM Daze Target wants you to kill 5 ELM Attackers for Dan and Great Justice!]]}
DB[14016]={id=14016,name=[[The Black Knight's Curse]],level=80,minLevel=77,giver=[[Crusader Rhydalla]],giverType=[[NPC]],giverId=33417,ender=[[Crusader Rhydalla]],enderType=[[NPC]],enderId=33417,prevId=13664,wowhead=[[https://www.wowhead.com/wotlk/quest=14016]],image=[[assets/images/quests/placeholder.png]],desc=[[I wanted to remove the Black Knight's remains from the tournament grounds after your victory, but Confessor Paletress insisted that he receive a decent burial. Ever since, a dark presence has lingered in the cemetery and people are afraid to go there to visit the fallen. Would you visit the cemetery just past the eastern end of the tournament grounds and see if you can discover what's happening?]],logDesc=[[Crusader Rhydalla at the Argent Tournament Grounds wants you to investigate the Black Knight's Grave.]]}
DB[14017]={id=14017,name=[[The Black Knight's Fate]],level=80,minLevel=77,giver=[[Crusader Rhydalla]],giverType=[[NPC]],giverId=33417,ender=[[Crusader Rhydalla]],enderType=[[NPC]],enderId=33417,prevId=14016,wowhead=[[https://www.wowhead.com/wotlk/quest=14017]],image=[[assets/images/quests/placeholder.png]],desc=[[You said the body was taken by cultists? I can only think of one place they would have gone, Deathspeaker's Watch, the encampment on the rise west of the tournament grounds. Whatever the cultists are doing must be stopped. The rumors I've heard can only be true, then. The infamous Doctor Kohler must be among the cultists, practicing his arts. Look for a rise or an altar overlooking the cultist camp, slay the doctor, and look for proof of his plans. Slow down his work in any other way you can.]],logDesc=[[Capture Doctor Kolher's Orders at Deathspeaker's Watch, then return to Crusader Rhydalla at the Argent Tournament Grounds.]],rewards={{id=44990,qty=3}}}
DB[14022]={id=14022,name=[[Pilgrim's Bounty]],name_loc=[[La Generosidad del Peregrino]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Gregory Tabor]],enderType=[[NPC]],enderId=34675,poiX=-9130,poiY=352,wowhead=[[https://www.wowhead.com/wotlk/quest=14022]],image=[[assets/images/quests/placeholder.png]],desc=[[Won't you celebrate Pilgrim's Bounty with us, $N? It's a time for reflecting on your journeys and your good fortune, sharing plentiful food and stories with friends. You can partake of wonderful Pilgrim's Bounty feasts near major towns by sitting at a bountiful table and serving the foods you find there. If you're interested in learning how to cook the traditional Pilgrim's Bounty foods, seek out Gregory Tabor. You will find him just outside Stormwind's gates.]],logDesc=[[Speak with Gregory Tabor just outside the city gates of Stormwind.]]}
DB[14023]={id=14023,name=[[Spice Bread Stuffing]],name_loc=[[Relleno de pan de especias]],level=-1,minLevel=1,giver=[[Gregory Tabor]],giverType=[[NPC]],giverId=34675,ender=[[Jasper Moore]],enderType=[[NPC]],enderId=34744,prevId=14064,rewardNextId=14024,poiX=-9115,poiY=359,wowhead=[[https://www.wowhead.com/wotlk/quest=14023]],image=[[assets/images/quests/placeholder.png]],desc=[[Our spice bread stuffing is the cornerstone of the Pilgrim's Bounty table. The recipe has always been a favorite in Stormwind and now it has taken its place in the bountiful cookbook. If you are already a cook, pay a visit to the Pilgrim's Bounty vendor to get your copy of the cookbook and all the local ingredients you'll need to prepare holiday fare. And if you're not yet a cook, there's no better time to start! Once you've made the stuffing, bring it to Jasper Moore over near the tables.]],logDesc=[[Cook 5 servings of Spice Bread Stuffing and then bring them to Jasper Moore at the feasting area just outside Stormwind's gates.]]}
DB[14024]={id=14024,name=[[Pumpkin Pie]],name_loc=[[Tarta de calabaza]],level=-1,minLevel=1,giver=[[Jasper Moore]],giverType=[[NPC]],giverId=34744,ender=[[Edward Winslow]],enderType=[[NPC]],enderId=34644,prevId=14023,rewardNextId=14028,poiX=-5063,poiY=-792,wowhead=[[https://www.wowhead.com/wotlk/quest=14024]],image=[[assets/images/quests/placeholder.png]],desc=[[That spice bread stuffing you made smells delicious, but no Pilgrim's Bounty feast is complete without a slice of pumpkin pie. It's another one of our favorite dishes here in Stormwind, since it uses ripe Elwynn pumpkins that only grow here. If you don't know how to make pumpkin pie already, there's a recipe in your bountiful cookbook. Would you mind cooking up a few slices and bringing them to Edward Winslow outside Ironforge? He's bound to be running low by now.]],logDesc=[[Make 5 slices of Pumpkin Pie and bring them to Edward Winslow at the feasting area right outside Ironforge.]]}
DB[14028]={id=14028,name=[[Cranberry Chutney]],name_loc=[[Chatni de arándanos]],level=-1,minLevel=1,giver=[[Edward Winslow]],giverType=[[NPC]],giverId=34644,ender=[[Jasper Moore]],enderType=[[NPC]],enderId=34744,prevId=14024,rewardNextId=14030,poiX=-9115,poiY=359,wowhead=[[https://www.wowhead.com/wotlk/quest=14028]],image=[[assets/images/quests/placeholder.png]],desc=[[If you haven't tried the cranberry chutney yet, you're in for a treat. It's made with the freshest tangy Wetlands cranberries. Just pick some up from the Pilgrim's Bounty vendor if you want to try your hand at making chutney. The recipe should be in your bountiful cookbook. If you've got some extra time on your hands, would you mind making some of the chutney and bringing it down to Jasper Moore outside Stormwind? I promised him I'd trade some for the pie you brought.]],logDesc=[[Make 5 servings of Cranberry Chutney and bring them to Jasper Moore at the feasting area outside Stormwind.]]}
DB[14030]={id=14030,name=[[They're Ravenous In Darnassus]],name_loc=[[En Darnassus están hambrientos]],level=-1,minLevel=1,giver=[[Jasper Moore]],giverType=[[NPC]],giverId=34744,ender=[[Isaac Allerton]],enderType=[[NPC]],enderId=34676,prevId=14028,rewardNextId=14033,poiX=9960,poiY=2241,wowhead=[[https://www.wowhead.com/wotlk/quest=14030]],image=[[assets/images/quests/placeholder.png]],desc=[[Thanks for bringing the cranberry chutney. There's so much cooking to do, I hardly have time to think of anything else. And on top of my responsibilities here, Isaac Allerton in Darnassus is out of almost everything. I don't suppose you'd be willing to step in and whip up some more spice bread stuffing and pumpkin pie? The vendor should have all the ingredients you need You should be able to find him near the feasting tables near the entrance to Darnassus just beyond the Warrior's Terrace.]],logDesc=[[Bring 5 servings of Spice Bread Stuffing and 5 Pumpkin Pies to Isaac Allerton near the entrance to Darnassus.]]}
DB[14032]={id=14032,zoneId=9,name=[[Kobold Camp Cleanup]],name_loc=[[Kobold Camp Cleanup [Programming Test] ]],level=2,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-8797,poiY=-259,wowhead=[[https://www.wowhead.com/wotlk/quest=14032]],image=[[assets/images/quests/placeholder.png]],desc=[[Your first task is one of cleansing, $N.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.]],logDesc=[[Kill 8 Kobold Vermin, then return to Marshal McBride.]]}
DB[14033]={id=14033,name=[[Candied Sweet Potatoes]],name_loc=[[Batatas confitadas]],level=-1,minLevel=1,giver=[[Isaac Allerton]],giverType=[[NPC]],giverId=34676,ender=[[Gregory Tabor]],enderType=[[NPC]],enderId=34675,prevId=14030,rewardNextId=14035,poiX=-9130,poiY=352,wowhead=[[https://www.wowhead.com/wotlk/quest=14033]],image=[[assets/images/quests/placeholder.png]],desc=[[While you're here, you might want to stock up on Teldrassil sweet potatoes. They're used to make the most delicious candied sweet potatoes you've ever tasted. If you don't believe me, look up the recipe in your bountiful cookbook and give it a try. And if there are any extras, you might want to share them with Gregory Tabor at the feasting area just outside Stormwind. They're one of his favorites, but to hear him tell it, everything's his favorite!]],logDesc=[[Make 5 servings of Candied Sweet Potatoes and bring them to Gregory Tabor just outside the gates of Stormwind.]]}
DB[14035]={id=14035,name=[[Slow-roasted Turkey]],name_loc=[[Pavo a fuego lento]],level=-1,minLevel=1,giver=[[Gregory Tabor]],giverType=[[NPC]],giverId=34675,ender=[[Isaac Allerton]],enderType=[[NPC]],enderId=34676,prevId=14033,poiX=9960,poiY=2241,wowhead=[[https://www.wowhead.com/wotlk/quest=14035]],image=[[assets/images/quests/placeholder.png]],desc=[[Every Pilgrim's Bounty feast requires a magnificent centerpiece, and I'm not talking about a decorative horn of plenty, either. No, the focus of the meal is a magnificent roast turkey. There's a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Elwynn Forest, so you shouldn't have a problem finding one. Once you're done roasting them, will you bring them to Isaac Allerton near the gates of Darnassus?]],logDesc=[[Make 5 Slow-Roasted Turkeys and bring them to Isaac Allerton near the gates of Darnassus.]],rewards={{id=44844,qty=1}}}
DB[14036]={id=14036,name=[[Pilgrim's Bounty]],name_loc=[[La Generosidad del Peregrino]],level=-1,minLevel=1,giverType=[[NPC]],ender=[[Miles Standish]],enderType=[[NPC]],enderId=34677,poiX=1805,poiY=260,wowhead=[[https://www.wowhead.com/wotlk/quest=14036]],image=[[assets/images/quests/placeholder.png]],desc=[[Are you here to celebrate Pilgrim's Bounty with us? It was once a time for reflecting on your journeys and your good fortune while sharing a meal with friends. Many still mark the occasion. You can partake of Pilgrim's Bounty feasts near major towns by sitting at a bountiful table and serving the foods you find there. If you're interested in learning how to cook the traditional Pilgrim's Bounty foods, seek out Miles Standish. You will find him in the courtyard above Undercity.]],logDesc=[[Speak with Miles Standish in the courtyard above Undercity.]]}
DB[14037]={id=14037,name=[[Spice Bread Stuffing]],name_loc=[[Relleno de pan de especias]],level=-1,minLevel=1,giver=[[William Mullins]],giverType=[[NPC]],giverId=34768,ender=[[William Mullins]],enderType=[[NPC]],enderId=34768,prevId=14065,rewardNextId=14040,poiX=1787,poiY=247,wowhead=[[https://www.wowhead.com/wotlk/quest=14037]],image=[[assets/images/quests/placeholder.png]],desc=[[Our spice bread stuffing is the cornerstone of the Pilgrim's Bounty table. The recipe dates from better times in Lordaeron and now it has taken its place in the traditional meal. If you are already a cook, pay a visit to the Pilgrim's Bounty vendor to get your copy of the bountiful cookbook and all the local ingredients you'll need to prepare holiday fare. And if you're not yet a cook, there's no better time to start! Once you've made the stuffing, bring it to William Mullins over near the tables.]],logDesc=[[Cook 5 servings of Spice Bread Stuffing and then bring them to William Mullins at the feasting area in the courtyard above the Undercity.]]}
DB[14040]={id=14040,name=[[Pumpkin Pie]],name_loc=[[Tarta de calabaza]],level=-1,minLevel=1,giver=[[William Mullins]],giverType=[[NPC]],giverId=34768,ender=[[Francis Eaton]],enderType=[[NPC]],enderId=34679,prevId=14037,rewardNextId=14041,poiX=1322,poiY=-4426,wowhead=[[https://www.wowhead.com/wotlk/quest=14040]],image=[[assets/images/quests/placeholder.png]],desc=[[That spice bread stuffing you made is a hit, but no Pilgrim's Bounty feast is complete without a slice of pumpkin pie. It's another traditional local dish, since it uses ripe Tirisfal pumpkins that only grow around here. If you don't know how to make pumpkin pie already, there's a recipe in your bountiful cookbook. Would you mind cooking up a few slices and bringing them to Francis Eaton outside Orgrimmar? He's bound to be running low by now.]],logDesc=[[Make 5 slices of Pumpkin Pie and bring them to Francis Eaton at the feasting area right outside Orgrimmar.]]}
DB[14041]={id=14041,name=[[Cranberry Chutney]],name_loc=[[Chatni de arándanos]],level=-1,minLevel=1,giver=[[Francis Eaton]],giverType=[[NPC]],giverId=34679,ender=[[Dokin Farplain]],ender_loc=[[Dokin Llanura Lejana]],enderType=[[NPC]],enderId=34678,prevId=14040,rewardNextId=14043,poiX=-1294,poiY=194,wowhead=[[https://www.wowhead.com/wotlk/quest=14041]],image=[[assets/images/quests/placeholder.png]],desc=[[Have you tried the cranberry chutney yet? It's made with fresh tangy Southfury cranberries. Just pick some up from the Pilgrim's Bounty vendor if you want to try your hand at making chutney. The recipe should be in your bountiful cookbook. If you've got some extra time on your hands, would you mind making some of the chutney and bringing it to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff.]],logDesc=[[Make 5 servings of Cranberry Chutney and bring them to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff.]]}
DB[14043]={id=14043,name=[[Candied Sweet Potatoes]],name_loc=[[Batatas confitadas]],level=-1,minLevel=1,giver=[[Dokin Farplain]],giver_loc=[[Dokin Llanura Lejana]],giverType=[[NPC]],giverId=34678,ender=[[Francis Eaton]],enderType=[[NPC]],enderId=34679,prevId=14041,rewardNextId=14044,poiX=1322,poiY=-4426,wowhead=[[https://www.wowhead.com/wotlk/quest=14043]],image=[[assets/images/quests/placeholder.png]],desc=[[While you're here, you might want to stock up on Mulgore sweet potatoes. They're used to make delicious candied sweet potatoes, my favorite part of the Pilgrim's Bounty meal. If you don't believe me, look up the recipe in your bountiful cookbook and give it a try. If you're headed back to Orgrimmar, bring them to Francis Eaton at the feasting area just outside the city. I've been trying to keep him supplied, but everything goes so fast over there.]],logDesc=[[Make 5 servings of Candied Sweet Potatoes and bring them to Francis Eaton just outside of Orgrimmar.]]}
DB[14044]={id=14044,name=[[Undersupplied in the Undercity]],name_loc=[[Cortos de suministros en Entrañas]],level=-1,minLevel=1,giver=[[Francis Eaton]],giverType=[[NPC]],giverId=34679,ender=[[Miles Standish]],enderType=[[NPC]],enderId=34677,prevId=14043,rewardNextId=14047,poiX=1805,poiY=260,wowhead=[[https://www.wowhead.com/wotlk/quest=14044]],image=[[assets/images/quests/placeholder.png]],desc=[[Thanks for bringing the candied sweet potatoes. There's so much cooking to do, I can hardly keep up. And then, Miles sends me a note saying he's on the verge of running out of stuffing and cranberry chutney. I don't suppose you'd be willing to step in and whip up some more of each? The vendor should have all the ingredients you need. You should be able to find Miles Standish near the feasting tables in the courtyard in the ruins above Undercity.]],logDesc=[[Bring 5 servings of Spice Bread Stuffing and 5 servings of Cranberry Chutney to Miles Standish near the entrance to Undercity.]]}
DB[14047]={id=14047,name=[[Slow-roasted Turkey]],name_loc=[[Pavo a fuego lento]],level=-1,minLevel=1,giver=[[Miles Standish]],giverType=[[NPC]],giverId=34677,ender=[[Francis Eaton]],enderType=[[NPC]],enderId=34679,prevId=14044,poiX=1322,poiY=-4426,wowhead=[[https://www.wowhead.com/wotlk/quest=14047]],image=[[assets/images/quests/placeholder.png]],desc=[[Every Pilgrim's Bounty feast requires a centerpiece, and for us, that's a slow-roasted wild turkey. I can't think of anything better to bring the meal together. There's a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Tirisfal Glades, so you shouldn't have a problem finding any. Once you're done roasting them, will you bring them to Francis Eaton outside Orgrimmar?]],logDesc=[[Make 5 Slow-Roasted Turkeys and bring them to Francis Eaton near the gates of Orgrimmar.]],rewards={{id=44844,qty=1}}}
DB[14048]={id=14048,name=[[Can't Get Enough Turkey]],name_loc=[[No tenemos suficiente pavo...]],level=-1,minLevel=1,giver=[[Caitrin Ironkettle]],giver_loc=[[Caitrin Hierrocaldera]],giverType=[[NPC]],giverId=34708,ender=[[Caitrin Ironkettle]],ender_loc=[[Caitrin Hierrocaldera]],enderType=[[NPC]],enderId=34708,prevId=14022,poiX=-5062,poiY=-803,wowhead=[[https://www.wowhead.com/wotlk/quest=14048]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been cooking nonstop since before the start of the holiday, and I still can't keep up with the demand. I don't suppose I could persuade you to help with one of the dishes, could I? Turkey is hard to come by here, so if you could supply some slow-roasted turkeys, it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in Elwynn Forest. You should be able to buy everything else you need from any of the Pilgrim's Bounty vendors.]],logDesc=[[Bring 20 Slow-Roasted Turkeys to Caitrin Ironkettle outside Ironforge.]],choiceRewards={{id=46723,qty=1},{id=46800,qty=1},{id=44785,qty=1},{id=46824,qty=1},{id=44788,qty=1},{id=44812,qty=1}}}
DB[14051]={id=14051,name=[[Don't Forget The Stuffing!]],name_loc=[[¡No olvides el relleno!]],level=-1,minLevel=1,giver=[[Caitrin Ironkettle]],giver_loc=[[Caitrin Hierrocaldera]],giverType=[[NPC]],giverId=34708,ender=[[Caitrin Ironkettle]],ender_loc=[[Caitrin Hierrocaldera]],enderType=[[NPC]],enderId=34708,prevId=14022,poiX=-5062,poiY=-803,wowhead=[[https://www.wowhead.com/wotlk/quest=14051]],image=[[assets/images/quests/placeholder.png]],desc=[[Keeping these tables stocked can be overwhelming! I've got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don't burn. I think I've got everything covered. No, wait, I'm forgetting something. The stuffing! Oh, no. There won't be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn't take long to buy or make some stuffing and you can buy the ingredients right here.]],logDesc=[[Bring 20 Spice Bread Stuffing to Caitrin Ironkettle at the feasting area outside Ironforge.]],choiceRewards={{id=46723,qty=1},{id=46800,qty=1},{id=44785,qty=1},{id=46824,qty=1},{id=44788,qty=1},{id=44812,qty=1}}}
DB[14053]={id=14053,name=[[We're Out of Cranberry Chutney Again?]],name_loc=[[¿Otra vez sin chatni de arándanos?]],level=-1,minLevel=1,giver=[[Ellen Moore]],giver_loc=[[Ellen Moore]],giverType=[[NPC]],giverId=34710,ender=[[Ellen Moore]],ender_loc=[[Ellen Moore]],enderType=[[NPC]],enderId=34710,prevId=14022,poiX=-9111,poiY=365,wowhead=[[https://www.wowhead.com/wotlk/quest=14053]],image=[[assets/images/quests/placeholder.png]],desc=[[My husband, Jasper, was going to make more cranberry chutney, but it looks like he's busy trying to make sure there's enough candied sweet potatoes for all the guests. Would you be willing to help? If you're a cook, you can get the tangy Wetlands cranberries you'll need from the Pilgrim's Bounty vendor outside Ironforge. If you don't feel up to cooking, you could always ask someone else to make the chutney, too.]],logDesc=[[Bring 20 servings of Cranberry Chutney to Ellen Moore at the feasting area outside Stormwind.]],choiceRewards={{id=46723,qty=1},{id=46800,qty=1},{id=44785,qty=1},{id=46824,qty=1},{id=44788,qty=1},{id=44812,qty=1}}}
DB[14054]={id=14054,name=[[Easy As Pie]],name_loc=[[Fácil como una tarta]],level=-1,minLevel=1,giver=[[Mary Allerton]],giver_loc=[[Mary Allerton]],giverType=[[NPC]],giverId=34711,ender=[[Mary Allerton]],ender_loc=[[Mary Allerton]],enderType=[[NPC]],enderId=34711,prevId=14022,poiX=9990,poiY=2235,wowhead=[[https://www.wowhead.com/wotlk/quest=14054]],image=[[assets/images/quests/placeholder.png]],desc=[[Isaac's been hard at work helping celebrants learn about the traditional Pilgrim's Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I've been trying to keep the tables stocked with as many of the dishes as I can, but we're running out of one of Isaac's favorites, pumpkin pie. Would you be able to get some for us? If you want to make the pies yourself, you'll need to buy ripe Elwynn pumpkins from the Pilgrim's Bounty vendor outside Stormwind.]],logDesc=[[Bring 20 pieces of Pumpkin Pie to Mary Allerton at the feasting area near the gates of Darnassus.]],choiceRewards={{id=46723,qty=1},{id=46800,qty=1},{id=44785,qty=1},{id=46824,qty=1},{id=44788,qty=1},{id=44812,qty=1}}}
DB[14055]={id=14055,name=[[She Says Potato]],name_loc=[[El corro de las batatas]],level=-1,minLevel=1,giver=[[Jasper Moore]],giverType=[[NPC]],giverId=34744,ender=[[Jasper Moore]],enderType=[[NPC]],enderId=34744,prevId=14022,poiX=-9115,poiY=359,wowhead=[[https://www.wowhead.com/wotlk/quest=14055]],image=[[assets/images/quests/placeholder.png]],desc=[[My wife Ellen has enlisted my help in keeping the tables stocked, but she can't make up her mind. First I was making pumpkin pie, but now she's changed her mind and she wants candied sweet potatoes. Well, I've already started on the pie, so maybe you can help me whip up those sweet potatoes. She'll be pleasantly surprised if we can get everything she's asked for. If you're going to cook the sweet potatoes yourself, you'll have to buy them from the Pilgrim's Bounty merchant in Darnassus. Thanks, $N.]],logDesc=[[Bring 20 Candied Sweet Potatoes to Jasper Moore at the feasting area outside of Stormwind.]],choiceRewards={{id=46723,qty=1},{id=46800,qty=1},{id=44785,qty=1},{id=46824,qty=1},{id=44788,qty=1},{id=44812,qty=1}}}
DB[14058]={id=14058,name=[[She Says Potato]],name_loc=[[El corro de las batatas]],level=-1,minLevel=1,giver=[[William Mullins]],giverType=[[NPC]],giverId=34768,ender=[[William Mullins]],enderType=[[NPC]],enderId=34768,prevId=14036,poiX=1787,poiY=247,wowhead=[[https://www.wowhead.com/wotlk/quest=14058]],image=[[assets/images/quests/placeholder.png]],desc=[[Roberta Carter has recruited me to help prepare one of the feast dishes, candied sweet potatoes.  Normally, I'd love to help, but I've promised the hostess that I'd help her watch the tables. I'd really appreciate it if you would help me come up with those candied sweet potatoes. Roberta would never forgive me if I let her down. If you're going to cook the sweet potatoes yourself, you'll have to buy them from the Pilgrim's Bounty merchant in Thunder Bluff. Thanks, $N.]],logDesc=[[Bring 20 Candied Sweet Potatoes to William Mullins at the feasting area above Undercity.]],choiceRewards={{id=46723,qty=1},{id=46800,qty=1},{id=44785,qty=1},{id=46824,qty=1},{id=44788,qty=1},{id=44812,qty=1}}}
DB[14059]={id=14059,name=[[We're Out of Cranberry Chutney Again?]],name_loc=[[¿Otra vez sin chatni de arándanos?]],level=-1,minLevel=1,giver=[[Roberta Carter]],giver_loc=[[Roberta Carter]],giverType=[[NPC]],giverId=34712,ender=[[Roberta Carter]],ender_loc=[[Roberta Carter]],enderType=[[NPC]],enderId=34712,prevId=14036,poiX=1821,poiY=267,wowhead=[[https://www.wowhead.com/wotlk/quest=14059]],image=[[assets/images/quests/placeholder.png]],desc=[[I wish I knew why we're going through cranberry chutney so fast. Sometimes, I think they're feeding it to the abominations when I'm not looking. Would you be willing to help me make up a new batch? If you're a cook, you can get the tangy Southfury cranberries you'll need from the Pilgrim's Bounty vendor outside Orgrimmar. If you don't feel up to cooking, you could always ask someone else to make the chutney, too.]],logDesc=[[Bring 20 servings of Cranberry Chutney to Roberta Carter at the feasting area in the courtyard above Undercity.]],choiceRewards={{id=46723,qty=1},{id=46800,qty=1},{id=44785,qty=1},{id=46824,qty=1},{id=44788,qty=1},{id=44812,qty=1}}}
DB[14060]={id=14060,name=[[Easy As Pie]],name_loc=[[Fácil como una tarta]],level=-1,minLevel=1,giver=[[Mahara Goldwheat]],giver_loc=[[Mahara Orotrigo]],giverType=[[NPC]],giverId=34714,ender=[[Mahara Goldwheat]],ender_loc=[[Mahara Orotrigo]],enderType=[[NPC]],enderId=34714,prevId=14036,poiX=-1336,poiY=193,wowhead=[[https://www.wowhead.com/wotlk/quest=14060]],image=[[assets/images/quests/placeholder.png]],desc=[[Dokin and Laha have been hard at work helping celebrants learn about the traditional Pilgrim's Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I've been trying to keep the tables stocked with as many of the dishes as I can, but we're running low on pumpkin pie. Would you be able to get some for us? If you want to make the pies yourself, you'll need to buy ripe Tirisfal pumpkins from the Pilgrim's Bounty vendor outside the Undercity.]],logDesc=[[Bring 20 pieces of Pumpkin Pie to Marhara Goldwheat at the feasting area outside Thunder Bluff.]],choiceRewards={{id=46723,qty=1},{id=46800,qty=1},{id=44785,qty=1},{id=46824,qty=1},{id=44788,qty=1},{id=44812,qty=1}}}
DB[14061]={id=14061,name=[[Can't Get Enough Turkey]],name_loc=[[No tenemos suficiente pavo...]],level=-1,minLevel=1,giver=[[Ondani Greatmill]],giver_loc=[[Ondani Gran Molino]],giverType=[[NPC]],giverId=34713,ender=[[Ondani Greatmill]],ender_loc=[[Ondani Gran Molino]],enderType=[[NPC]],enderId=34713,prevId=14036,poiX=1320,poiY=-4414,wowhead=[[https://www.wowhead.com/wotlk/quest=14061]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been cooking nonstop since before the start of the holiday, and I still can't keep up with the demand. I don't suppose I could persuade you to help with one of the dishes, could I? Turkey is hard to come by here, so if you could supply some slow-roasted turkeys, it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in the Tirisfal Glades. You should be able to buy everything else you need from any of the Pilgrim's Bounty vendors.]],logDesc=[[Bring 20 Slow-Roasted Turkeys to Ondani Greatmill outside Orgrimmar.]],choiceRewards={{id=46723,qty=1},{id=46800,qty=1},{id=44785,qty=1},{id=46824,qty=1},{id=44788,qty=1},{id=44812,qty=1}}}
DB[14062]={id=14062,name=[[Don't Forget The Stuffing!]],name_loc=[[¡No olvides el relleno!]],level=-1,minLevel=1,giver=[[Ondani Greatmill]],giver_loc=[[Ondani Gran Molino]],giverType=[[NPC]],giverId=34713,ender=[[Ondani Greatmill]],ender_loc=[[Ondani Gran Molino]],enderType=[[NPC]],enderId=34713,prevId=14036,poiX=1320,poiY=-4414,wowhead=[[https://www.wowhead.com/wotlk/quest=14062]],image=[[assets/images/quests/placeholder.png]],desc=[[Keeping these tables stocked can be overwhelming! I've got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don't burn. I think I've got everything covered. No, wait, I'm forgetting something. The stuffing! Oh, no. There won't be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn't take long to buy or make some stuffing and you can buy the ingredients right here.]],logDesc=[[Bring 20 Spice Bread Stuffing to Ondani Greatmill outside Orgrimmar.]],choiceRewards={{id=46723,qty=1},{id=46800,qty=1},{id=44785,qty=1},{id=46824,qty=1},{id=44788,qty=1},{id=44812,qty=1}}}
DB[14064]={id=14064,name=[[Sharing a Bountiful Feast]],name_loc=[[Compartir un festín generoso]],level=-1,minLevel=1,giver=[[Bountiful Table Hostess]],giver_loc=[[Anfitriona de mesa generosa]],giverType=[[NPC]],giverId=34653,ender=[[Bountiful Table Hostess]],ender_loc=[[Anfitriona de mesa generosa]],enderType=[[NPC]],enderId=34653,prevId=14022,poiX=-11321,poiY=-196,wowhead=[[https://www.wowhead.com/wotlk/quest=14064]],image=[[assets/images/quests/placeholder.png]],desc=[[You've not celebrated Pilgrim's Bounty properly until you've eaten your fill at a Bountiful Table. Please, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food. Once you eat enough of every dish, you'll be infused with the Spirit of Sharing.]],logDesc=[[Eat five helpings of every food at a Bountiful Table until you gain the Spirit of Sharing.]]}
DB[14065]={id=14065,name=[[Sharing a Bountiful Feast]],name_loc=[[Compartir un festín generoso]],level=-1,minLevel=1,giver=[[Bountiful Feast Hostess]],giver_loc=[[Anfitriona de festín generoso]],giverType=[[NPC]],giverId=34654,ender=[[Bountiful Feast Hostess]],ender_loc=[[Anfitriona de festín generoso]],enderType=[[NPC]],enderId=34654,prevId=14036,poiX=-12368,poiY=163,wowhead=[[https://www.wowhead.com/wotlk/quest=14065]],image=[[assets/images/quests/placeholder.png]],desc=[[You've not celebrated Pilgrim's Bounty properly until you've eaten your fill at a Bountiful Table. Please, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food. Once you eat enough of every dish, you'll be infused with the Spirit of Sharing.]],logDesc=[[Eat five helpings of every food at a Bountiful Table until you gain the Spirit of Sharing.]]}
DB[14074]={id=14074,name=[[A Leg Up]],level=80,minLevel=77,giver=[[Narasi Snowdawn]],giverType=[[NPC]],giverId=34880,ender=[[Narasi Snowdawn]],enderType=[[NPC]],enderId=34880,wowhead=[[https://www.wowhead.com/wotlk/quest=14074]],image=[[assets/images/quests/placeholder.png]],desc=[[The Argent Crusade dispatched a fast ship carrying tallstrider meat and other supplies for us here at the tournament grounds, but it never arrived. Scouts reported seeing it attacked by the kvaldir, fearsome vrykul raiders who roam the seas. They've slain the crew and taken the cargo to an island called Hrothgar's Landing. If you look to the north, you can see it shrouded in the mist. Would you help us in recovering the stolen supplies? Without those tallstrider legs, we'll soon be out of food.]],logDesc=[[Recover 10 Stolen Tallstrider Legs for Narasi Snowdawn at the Argent Tournament Grounds.]],rewards={{id=44990,qty=1}}}
DB[14076]={id=14076,name=[[Breakfast Of Champions]],level=80,minLevel=77,giver=[[Savinia Loresong]],giverType=[[NPC]],giverId=34912,ender=[[Savinia Loresong]],enderType=[[NPC]],enderId=34912,wowhead=[[https://www.wowhead.com/wotlk/quest=14076]],image=[[assets/images/quests/placeholder.png]],desc=[[Now that the coliseum is complete, the Argent Crusade has asked us to help look after the creatures that champions will be fighting. The giant jormungar have perhaps the strangest diet; they grow strong by eating the eggs of their own kind and the best eggs come from deep jormungar. Take this drum to the Foot Steppes in central Storm Peaks and play them near the snow mounds you see there.  Rouse the deep jormungar, kill them, and gather their egg sacs.]],logDesc=[[Acquire 4 Jormungar Egg Sacs and bring them to Savinia Loresong at the Argent Tournament Grounds.]],rewards={{id=44990,qty=1}}}
DB[14077]={id=14077,name=[[The Light's Mercy]],level=80,minLevel=77,giver=[[Narasi Snowdawn]],giverType=[[NPC]],giverId=34880,ender=[[Narasi Snowdawn]],enderType=[[NPC]],enderId=34880,wowhead=[[https://www.wowhead.com/wotlk/quest=14077]],image=[[assets/images/quests/placeholder.png]],desc=[[I've been listening to Confessor Paletress speak, and I must tell you, her words have given me much to consider. It is not enough to fight beside the crusaders; we must take up their mission. Off the north coast is Hrothgar's Landing, where the seagoing Kvaldir have overrun an old tuskarr settlement and slain the villagers. Take this book and read the rites for the dead near the corpses of the villagers. It will allow their spirits to escape the mists engulfing the island and find peace.]],logDesc=[[Use the Confessor's Prayer Book to perform last rites for 8 Slain Tualiq Villagers and then return to Narasi Snowdawn at the Argent Tournament Grounds.]],rewards={{id=44990,qty=1}}}
DB[14079]={id=14079,zoneId=12,name=[[Learn to Ride in Elwynn Forest]],name_loc=[[Aprende a montar en el Bosque de Elwynn]],level=20,minLevel=20,giverType=[[NPC]],ender=[[Randal Hunter]],ender_loc=[[Randal Predatio]],enderType=[[NPC]],enderId=4732,poiX=-9441,poiY=-1391,wowhead=[[https://www.wowhead.com/wotlk/quest=14079]],image=[[assets/images/quests/placeholder.png]],desc=[[This pamphlet advertising riding training and mount purchases was sent from Randal Hunter. Randal can be found at Elwynn Forest's Eastvale Logging Camp, along the road east out of Stormwind.]],logDesc=[[Return the pamphlet to Randal Hunter at Eastvale Logging Camp in Elwynn Forest.]]}
DB[14080]={id=14080,name=[[Stop The Aggressors]],level=80,minLevel=77,giver=[[Narasi Snowdawn]],giverType=[[NPC]],giverId=34880,ender=[[Narasi Snowdawn]],enderType=[[NPC]],enderId=34880,wowhead=[[https://www.wowhead.com/wotlk/quest=14080]],image=[[assets/images/quests/placeholder.png]],desc=[[The Kvaldir, fearsome vrykul raiders, have disrupted our shipments and murdered the tuskarr inhabitants of an island to the north, renaming it Hrothgar's Landing. If they are allowed to get a foothold there, there is no doubt that we will be their next target. The crusade's forces have their hands full dealing with the Scourge, and we must defend the tournament grounds. Fly north from the grounds until you reach the island and take on the Kvaldir before they can destroy anything else.]],logDesc=[[Narasi Snowdawn at the Argent Tournament Grounds wants you to kill 10 Kvaldir.]],rewards={{id=44990,qty=1}}}
DB[14081]={id=14081,zoneId=3430,name=[[Learn to Ride in the Eversong Woods]],name_loc=[[Aprende a montar en el Bosque Canción Eterna]],level=20,minLevel=20,giverType=[[NPC]],ender=[[Perascamin]],ender_loc=[[Perascamin]],enderType=[[NPC]],enderId=16280,poiX=9269,poiY=-7510,wowhead=[[https://www.wowhead.com/wotlk/quest=14081]],image=[[assets/images/quests/placeholder.png]],desc=[[This pamphlet advertising riding training and mount purchases was sent from Perascamin. Perascamin can be found at Thuron's Livery, southeast of the Shepherd's Gate leaving Silvermoon City.]],logDesc=[[Return the pamphlet to Perascamin at Thuron's Livery in Silvermoon City.]]}
