DB[14087]={id=14087,zoneId=215,name=[[Learn to Ride in Mulgore]],name_loc=[[Aprende a montar en Mulgore]],level=20,minLevel=20,giverType=[[NPC]],ender=[[Kar Stormsinger]],ender_loc=[[Kar Tormensón]],enderType=[[NPC]],enderId=3690,poiX=-2276,poiY=-400,wowhead=[[https://www.wowhead.com/wotlk/quest=14087]],image=[[assets/images/quests/placeholder.png]],desc=[[This pamphlet advertising riding training and mount purchases was sent from Kar Stormsinger. Kar can be found in Mulgore's Bloodhoof Village.]],logDesc=[[Return the pamphlet to Kar Stormsinger at Bloodhoof Village in Mulgore.]]}
