DB[14178]={id=14178,zoneId=3358,name=[[Call to Arms: Arathi Basin]],level=-1,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],exGroup=14180,wowhead=[[https://www.wowhead.com/wotlk/quest=14178]],image=[[assets/images/quests/placeholder.png]],desc=[[The reality of fighting on multiple fronts, $g lad : lass;, is that we cannot spread our forces too thin or we risk losing it all! Critical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements. Return to me with news of victory, $N.  We cannot allow the Horde scum to secure the resources that are rightfully ours!]],logDesc=[[Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.]]}
DB[14179]={id=14179,zoneId=3820,name=[[Call to Arms: Eye of the Storm]],level=-1,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],exGroup=14180,wowhead=[[https://www.wowhead.com/wotlk/quest=14179]],image=[[assets/images/quests/placeholder.png]],desc=[[The fight against the Horde knows no boundaries, $N.  Even in Outland, territorial disputes and old hatreds are enough to tip the scales in favor of war. Go into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.]],logDesc=[[Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.]]}
DB[14180]={id=14180,zoneId=3277,name=[[Call to Arms: Warsong Gulch]],level=-1,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],exGroup=14180,wowhead=[[https://www.wowhead.com/wotlk/quest=14180]],image=[[assets/images/quests/placeholder.png]],desc=[[The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory. Their need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!]],logDesc=[[Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.]]}
DB[14181]={id=14181,zoneId=3358,name=[[Call to Arms: Arathi Basin]],level=-1,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],exGroup=14183,wowhead=[[https://www.wowhead.com/wotlk/quest=14181]],image=[[assets/images/quests/placeholder.png]],desc=[[Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain. Do not delay, $c, go to Arathi Basin and crush the enemy.  Victory to the Horde!]],logDesc=[[Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.]]}
DB[14182]={id=14182,zoneId=3820,name=[[Call to Arms: Eye of the Storm]],level=-1,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],exGroup=14183,wowhead=[[https://www.wowhead.com/wotlk/quest=14182]],image=[[assets/images/quests/placeholder.png]],desc=[[We will fight and crush the enemy wherever we find them.  Azeroth, Outland, the place makes no difference. We cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!]],logDesc=[[Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran,  or Shattrath.]]}
DB[14183]={id=14183,zoneId=3277,name=[[Call to Arms: Warsong Gulch]],level=-1,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],exGroup=14183,wowhead=[[https://www.wowhead.com/wotlk/quest=14183]],image=[[assets/images/quests/placeholder.png]],desc=[[The Alliance is an insidious enemy, $N.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens. Today we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!]],logDesc=[[Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath. ]]}
DB[14185]={id=14185,name=[[FLAG: Riding Trainer Advertisement (40)]],name_loc=[[FLAG: Riding Trainer Advertisement (40)]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=14185]],image=[[assets/images/quests/placeholder.png]]}
DB[14186]={id=14186,name=[[FLAG: Riding Trainer Advertisement (60)]],name_loc=[[FLAG: Riding Trainer Advertisement (60)]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=14186]],image=[[assets/images/quests/placeholder.png]]}
DB[14187]={id=14187,name=[[FLAG: Riding Trainer Advertisement (70)]],name_loc=[[FLAG: Riding Trainer Advertisement (70)]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=14187]],image=[[assets/images/quests/placeholder.png]]}
DB[14199]={id=14199,zoneId=4723,name=[[Proof of Demise: The Black Knight]],level=80,minLevel=80,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=14199]],image=[[assets/images/quests/placeholder.png]],desc=[[My counterpart, Archmage Timear, has asked me to warn you of something dire. Soon, you will be participating in the Trial of the Champions at the Argent Coliseum in Icecrown. You must beware of interference from one known only as the Black Knight. Bring me a fragment of his soul that the Kirin Tor will know he is dealt with. I am told that failing to do so will be your own undoing.]],logDesc=[[Archmage Lan'dalock in Dalaran wants you to return with a Fragment of the Black Knight's Soul. This quest may only be completed on Heroic difficulty.]],rewards={{id=47241,qty=2}}}
DB[14200]={id=14200,name=[[Kickoff Mail Marker]],level=70,minLevel=70,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=14200]],image=[[assets/images/quests/placeholder.png]]}
DB[14203]={id=14203,zoneId=4613,name=[[Waterlogged Recipe]],level=80,minLevel=70,giverType=[[NPC]],ender=[[Christi Stockton]],enderType=[[NPC]],enderId=32337,wowhead=[[https://www.wowhead.com/wotlk/quest=14203]],image=[[assets/images/quests/placeholder.png]],desc=[[This appears to be the remains of a mixture for potent wine.  Perhaps the proprietor of One More Glass in Dalaran would be interested in it....]],logDesc=[[Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city.]],rewards={{id=43016,qty=5}}}
DB[14349]={id=14349,zoneId=139,name=[[The Call to Command]],name_loc=[[La llamada del teniente]],level=60,minLevel=56,giver=[[Nathanos Blightcaller]],giver_loc=[[Nathanos Clamañublo]],giverType=[[NPC]],giverId=11878,ender=[[Lady Sylvanas Windrunner]],ender_loc=[[Lady Sylvanas Brisaveloz]],enderType=[[NPC]],enderId=10181,rewardNextId=14350,exGroup=6144,poiX=1290,poiY=316,wowhead=[[https://www.wowhead.com/wotlk/quest=14349]],image=[[assets/images/quests/placeholder.png]],desc=[[The order has come down, $c. Sylvanas herself has requested that I send my most 'capable' agents back to the Undercity for a highly sensitive tactical operation. Unfortunately, my most capable agents were killed over three years ago. In their stead I have a collection of brain dead riff-raff. <Nathanos stares coldly at you.> Travel to the Undercity at once and report to the Dark Lady. Do not embarrass me, $c!]],logDesc=[[Travel to the Undercity and speak with Lady Sylvanas Windrunner.]]}
DB[14350]={id=14350,zoneId=139,name=[[The Crimson Courier]],name_loc=[[El mensajero carmesí]],level=60,minLevel=56,giver=[[Lady Sylvanas Windrunner]],giver_loc=[[Lady Sylvanas Brisaveloz]],giverType=[[NPC]],giverId=10181,ender=[[Nathanos Blightcaller]],ender_loc=[[Nathanos Clamañublo]],enderType=[[NPC]],enderId=11878,rewardNextId=6146,exGroup=6145,poiX=3315,poiY=-3380,wowhead=[[https://www.wowhead.com/wotlk/quest=14350]],image=[[assets/images/quests/placeholder.png]],desc=[[We cannot attack the Scarlet Crusade's command directly; they are too well defended. But there's more than one way to skin a cat. They'll be nothing without their main force. The Deathstalkers have been collecting data on the activity of the Crusade outside of Stratholme. Each day, a report is sent from their central command to Tyr's Hand. This report is the key, $r! Find the Crimson Courier and recover that report. Bring it to Nathanos.]],logDesc=[[Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command. Take the command to Nathanos Blightcaller for further instruction.]]}
DB[14351]={id=14351,zoneId=267,name=[[Battle of Hillsbrad]],name_loc=[[La batalla de Trabalomas]],level=32,minLevel=19,giver=[[High Executor Darthalia]],giver_loc=[[Suma ejecutora Darthalia]],giverType=[[NPC]],giverId=2215,ender=[[Bragor Bloodfist]],ender_loc=[[Bragor Puñosangre]],enderType=[[NPC]],enderId=36273,prevId=541,poiX=1288,poiY=334,wowhead=[[https://www.wowhead.com/wotlk/quest=14351]],image=[[assets/images/quests/placeholder.png]],desc=[[Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize. Take this sealed commendation to Bragor Bloodfist in the Undercity.  Go with pride, $c.]],logDesc=[[Take Darthalia's Sealed Commendation to Bragor Bloodfist in the Undercity.]],rewards={{id=3760,qty=1}},choiceRewards={{id=6282,qty=1},{id=3761,qty=1},{id=3822,qty=1}}}
DB[14352]={id=14352,zoneId=722,name=[[An Unholy Alliance]],name_loc=[[Una alianza impía]],level=36,minLevel=28,giverType=[[NPC]],ender=[[Bragor Bloodfist]],ender_loc=[[Bragor Puñosangre]],enderType=[[NPC]],enderId=36273,nextId=14353,rewardNextId=14353,poiX=2190,poiY=1864,wowhead=[[https://www.wowhead.com/wotlk/quest=14352]],image=[[assets/images/quests/placeholder.png]],desc=[[My Lady, You know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area. Please, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being. Best Regards, Ambassador Malcin]],logDesc=[[Take the Small Scroll to Bragor Bloodfist in the Undercity.]]}
DB[14353]={id=14353,zoneId=722,name=[[An Unholy Alliance]],name_loc=[[Una alianza impía]],level=36,minLevel=28,giver=[[Bragor Bloodfist]],giver_loc=[[Bragor Puñosangre]],giverType=[[NPC]],giverId=36273,ender=[[Bragor Bloodfist]],ender_loc=[[Bragor Puñosangre]],enderType=[[NPC]],enderId=36273,prevId=14352,poiX=1288,poiY=334,wowhead=[[https://www.wowhead.com/wotlk/quest=14353]],image=[[assets/images/quests/placeholder.png]],desc=[[Supposedly this Malcin is outside Razorfen Downs. There's no question - he has to die. My contacts in Orgrimmar tell me their scouts have found signs of the Plague down there. The quilboar are showing signs of being plagued, too; they're much more powerful. Whatever the Scourge are doing down there needs to end. Now. Find this Malcin and kill him. Report back here when he's dead.]],logDesc=[[Bring Ambassador Malcin's Head to Bragor Bloodfist in the Undercity.]],choiceRewards={{id=17039,qty=1},{id=17042,qty=1},{id=17043,qty=1}}}
DB[14355]={id=14355,zoneId=796,name=[[Into The Scarlet Monastery]],name_loc=[[En el Monasterio Escarlata]],level=42,minLevel=30,giver=[[Bragor Bloodfist]],giver_loc=[[Bragor Puñosangre]],giverType=[[NPC]],giverId=36273,ender=[[Bragor Bloodfist]],ender_loc=[[Bragor Puñosangre]],enderType=[[NPC]],enderId=36273,poiX=1288,poiY=334,wowhead=[[https://www.wowhead.com/wotlk/quest=14355]],image=[[assets/images/quests/placeholder.png]],desc=[[One of my duties while I'm stationed here is to help the Forsaken take care of their borders, and that, $c, is exactly what you're going to do for me. I might live and breathe, but the Scarlet Crusade will cut down my people as quickly as they will one of the undead. They're a problem here, a big one, and you're going to do something about it. Go to the Monastery and slay High Inquisitor Whitemane and her lieutenants.]],logDesc=[[Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Bragor Bloodfist in the Undercity.]],choiceRewards={{id=6802,qty=1},{id=6803,qty=1},{id=10711,qty=1}}}
DB[14356]={id=14356,zoneId=2437,name=[[The Power to Destroy...]],name_loc=[[Poder destructivo]],level=16,minLevel=9,giver=[[Bragor Bloodfist]],giver_loc=[[Bragor Puñosangre]],giverType=[[NPC]],giverId=36273,ender=[[Bragor Bloodfist]],ender_loc=[[Bragor Puñosangre]],enderType=[[NPC]],enderId=36273,poiX=1288,poiY=334,wowhead=[[https://www.wowhead.com/wotlk/quest=14356]],image=[[assets/images/quests/placeholder.png]],desc=[[Listen up, $c. You may not know this, but Orgrimmar's got a problem. Deep in Ragefire Chasm, a sect of the Shadow Council called the Searing Blade performs their sinister work. They're mainly orcs, and I can't trust sensitive information in the hands of the grunts there. That's where you come in. They should have two books in their possession. I want them kept out of the hands of the Searing Blade and the Forsaken alike. Bring them to me directly.]],logDesc=[[Bring the books Spells of Shadow and Incantations from the Nether to Bragor Bloodfist in Undercity.]],choiceRewards={{id=15449,qty=1},{id=15450,qty=1},{id=15451,qty=1}}}
DB[14409]={id=14409,zoneId=1657,name=[[A Cautious Return]],level=73,minLevel=71,giver=[[Daros Moonlance]],giverType=[[NPC]],giverId=36506,ender=[[Archmage Mordent Evenshade]],enderType=[[NPC]],enderId=36479,wowhead=[[https://www.wowhead.com/wotlk/quest=14409]],image=[[assets/images/quests/placeholder.png]],desc=[[A moment of your time, $c. Change is coming. It has drawn us out of the ruins of Eldre'Thalas and into the wide world once more. I have come to research this city and cannot stray from it, but if you are inclined, I have an errand for you. My colleague set out for Darnassus to speak with the High Priestess there, that we might come to an understanding. Take this journal to Mordent Evenshade in the temple. It may help in his diplomacy mission.]],logDesc=[[Bring Daros' Journal to Mordent Evenshade in Darnassus.]]}
DB[14418]={id=14418,name=[[The Deathstalkers]],name_loc=[[Los mortacechadores]],level=13,minLevel=10,giver=[[Mennet Carkad]],giverType=[[NPC]],giverId=6467,ender=[[Aleric Hawkins]],ender_loc=[[Aleric Hawkins]],enderType=[[NPC]],enderId=36517,prevId=14421,poiX=1385,poiY=342,wowhead=[[https://www.wowhead.com/wotlk/quest=14418]],image=[[assets/images/quests/placeholder.png]],desc=[[The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal. Hawkins will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him. Ah, and how could I forget? Welcome to the Deathstalkers.]],logDesc=[[Deliver Andron's Ledger to Aleric Hawkins in the Hall of the Dark Lady in the Undercity.]],rewards={{id=7298,qty=1}}}
DB[14419]={id=14419,name=[[The Deathstalkers]],name_loc=[[Los mortacechadores]],level=13,minLevel=10,giver=[[Mennet Carkad]],giverType=[[NPC]],giverId=6467,ender=[[Andron Gant]],enderType=[[NPC]],enderId=6522,prevId=14420,rewardNextId=14421,poiX=1389,poiY=347,wowhead=[[https://www.wowhead.com/wotlk/quest=14419]],image=[[assets/images/quests/placeholder.png]],desc=[[The letter of introduction should be enough to convince Andron that you are the messenger he's been waiting for. I've met Andron before, he doesn't quite have the mental capacity to be that suspicious. Our leader suspects that Andron has been providing aid to some other group. He wishes to know what organization this is and requires proof of it. I want you to speak with Andron, and obtain this information. You'll find him at his shop near the Apothecarium.]],logDesc=[[Speak with Andron Gant in the Undercity.]]}
DB[14420]={id=14420,name=[[The Deathstalkers]],name_loc=[[Los mortacechadores]],level=13,minLevel=10,giver=[[Mennet Carkad]],giverType=[[NPC]],giverId=6467,ender=[[Mennet Carkad]],enderType=[[NPC]],enderId=6467,prevId=1885,rewardNextId=14419,poiX=550,poiY=1455,wowhead=[[https://www.wowhead.com/wotlk/quest=14420]],image=[[assets/images/quests/placeholder.png]],desc=[[If you wish to join the Deathstalkers, the Dark Lady's elite guard, you will have to prove your worth. I will not lie to you, $n, this task could mean your death. I have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity. I will leave the method of procurement to your discretion. It will be better for you if you know less of the nature of this business. Succeed and I shall tell you more.]],logDesc=[[Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter.]]}
DB[14421]={id=14421,name=[[The Deathstalkers]],name_loc=[[Los mortacechadores]],level=13,minLevel=10,giver=[[Andron Gant]],giverType=[[NPC]],giverId=6522,ender=[[Mennet Carkad]],enderType=[[NPC]],enderId=6467,prevId=14419,rewardNextId=14418,poiX=1385,poiY=342,wowhead=[[https://www.wowhead.com/wotlk/quest=14421]],image=[[assets/images/quests/placeholder.png]],desc=[[You'll find the ledger with the information your employers seek on the bookshelf behind me. Deliver it with my regards, and tell them that I would prefer it if they sent you, if they find enough value that they should wish to continue our arrangement.]],logDesc=[[Bring Andron's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity.]]}
DB[14436]={id=14436,zoneId=215,name=[[Dwarven Digging]],name_loc=[[Una excavación de los enanos]],level=8,minLevel=6,giverType=[[NPC]],enderType=[[NPC]],poiX=-1885,poiY=282,wowhead=[[https://www.wowhead.com/wotlk/quest=14436]],image=[[assets/images/quests/placeholder.png]],desc=[[There are dwarves preparing a dig site to the northwest.  They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings. Collect the dwarven tools of digging, smash them, and return to me with the dwarves' broken tools. You can smash the tools at a forge.  You will find one in Thunder Bluff, but any forge -- even a forge at the dwarven camp -- will suffice.]],logDesc=[[Collect 5 Prospector's Picks. At a forge, smash the Prospector's Picks to create Broken Tools. Bring 5 Broken Tools to Ahmo Thunderhorn in Bloodhoof Village.]],choiceRewards={{id=4969,qty=1},{id=4970,qty=1}}}
DB[14437]={id=14437,zoneId=220,name=[[Rites of the Earthmother]],name_loc=[[Los ritos de la Madre Tierra]],level=5,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-2334,poiY=-422,wowhead=[[https://www.wowhead.com/wotlk/quest=14437]],image=[[assets/images/quests/placeholder.png]],desc=[[For you to continue with the Rites of the Earthmother you must pass two more tests. It is time for you to broaden your experience, $n. Travel to Bloodhoof Village and seek out the Ahmo Thunderhorn. There you may continue your journey and earn the acceptance of the elders of Thunder Bluff. Take this totem to Ahmo. He will recognize my carvings and help you on your path. Follow the road out of Camp Narache and travel with haste. Do not stray or you will lose your way.]],logDesc=[[Take the Totem of Hawkwind to Ahmo Thunderhorn in Bloodhoof Village. Follow the road out of Camp Narache.]]}
DB[14438]={id=14438,zoneId=215,name=[[Sharing the Land]],name_loc=[[Compartir la tierra]],level=6,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],poiX=-2451,poiY=216,wowhead=[[https://www.wowhead.com/wotlk/quest=14438]],image=[[assets/images/quests/placeholder.png]],desc=[[$N, there are many conflicts that wound this land. It is my hope that you will not bear witness to as many of them as our elders have. Yet there is one that I would ask you to seek. It will give you some sense of how terrible, if left unchecked, even a small threat can be to the land. Palemane gnolls have settled to the south of Bloodhoof and in a cave to the west. They disrespect our attempts to communicate with them, and they slay the wildlife of Mulgore unbridled. Words are no longer the answer.]],logDesc=[[Kill 10 Palemane Tanners, 8 Palemane Skinners, and 5 Palemane Poachers, then return to Ahmo Thunderhorn in Bloodhoof Village.]],rewards={{id=4960,qty=25}}}
DB[14439]={id=14439,zoneId=215,name=[[Journey into Thunder Bluff]],name_loc=[[Viaje a Cima del Trueno]],level=10,minLevel=3,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=776,wowhead=[[https://www.wowhead.com/wotlk/quest=14439]],image=[[assets/images/quests/placeholder.png]],desc=[[You will now be revered within our great city. Any $r worthy of completing the Rites of the Earthmother earns that honor. For your final quest, seek out our young leader, Baine Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.]],logDesc=[[Speak with Baine Bloodhoof in Thunder Bluff.]]}
DB[14440]={id=14440,zoneId=215,name=[[Rites of the Earthmother]],name_loc=[[Los ritos de la Madre Tierra]],level=14,minLevel=3,giverType=[[NPC]],enderType=[[NPC]],poiX=-912,poiY=-477,wowhead=[[https://www.wowhead.com/wotlk/quest=14440]],image=[[assets/images/quests/placeholder.png]],desc=[[You have passed the Rites of the Earthmother and earned your place in Thunder Bluff. But in order to maintain the spot that you strived so hard to achieve, you must continue to prove your worth to your people. We are hunters, $n. Down below in Mulgore there is a mighty kodo named Arra'chea. Show me your skills in the ways of tracking and hunting by bringing me the Horn of Arra'chea.]],logDesc=[[Baine Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea.]],rewards={{id=4909,qty=1}}}
DB[14441]={id=14441,name=[[Garrosh's Autograph]],name_loc=[[El autógrafo de Garrosh]],level=-1,minLevel=10,giverType=[[NPC]],ender=[[Caladis Brightspear]],ender_loc=[[Caladis Lanza Reluciente]],enderType=[[NPC]],enderId=36624,wowhead=[[https://www.wowhead.com/wotlk/quest=14441]],image=[[assets/images/quests/placeholder.png]],desc=[[They say that Garrosh Hellscream is one of the greatest heroes in the Horde! When I grow up, I want to be a hero of the Horde too! Do you know Garrosh, $N? Could you do me a favor, please? Could you get his autograph for me? I dunno how to ask him, and he probably wouldn't listen to someone like me... but you! You're an adventurer, like him! I bet he'd give you his autograph easy! Please?]],logDesc=[[Travel to Orgrimmar to see about getting Garrosh Hellscream's autograph for your ward.]]}
DB[14443]={id=14443,zoneId=210,name=[[The Battered Hilt]],level=80,minLevel=80,giverType=[[NPC]],ender=[[Caladis Brightspear]],enderType=[[NPC]],enderId=36624,rewardNextId=14444,wowhead=[[https://www.wowhead.com/wotlk/quest=14443]],image=[[assets/images/quests/placeholder.png]],desc=[[This battered old sword hilt has seen better days. Before the hilt was snapped from the blade, it must've been a magnificent example of the blacksmith's art. The graceful symbols and exotic gemstones decorating the hilt suggest that the weapon may have belonged to a powerful person. Surely, the Silver Covenant members would be interested in hearing about the recovery of such an artifact. Seek out their representative at Quel'Delar's Rest, south of the Argent Tournament Grounds.]],logDesc=[[Bring the Battered Hilt to Caladis Brightspear at Quel'Delar's rest, south of the Argent Tournament Grounds.]]}
DB[14444]={id=14444,zoneId=210,name=[[What The Dragons Know]],level=80,minLevel=80,giver=[[Caladis Brightspear]],giverType=[[NPC]],giverId=36624,ender=[[Arcanist Tybalin]],enderType=[[NPC]],enderId=36669,prevId=14443,rewardNextId=14457,wowhead=[[https://www.wowhead.com/wotlk/quest=14444]],image=[[assets/images/quests/placeholder.png]],desc=[[There's no mistaking it - this hilt comes from a powerful, ancient weapon, but which one? I do not recall seeing or hearing of a sword with these markings, but that doesn't mean that all is lost. Korialstrasz, better known as Krasus, has long been a friend to the quel'dorei and the Kirin Tor. With his vast knowledge and resources, he's certain to know something. Travel to the top of Wyrmrest Temple and seek his counsel, then report to Arcanist Tybalin inside the Silver Enclave in Dalaran.]],logDesc=[[Speak to Krasus at the top of Wyrmrest Temple.]]}
DB[14457]={id=14457,zoneId=4395,name=[[The Sunreaver Plan]],level=80,minLevel=80,giver=[[Arcanist Tybalin]],giverType=[[NPC]],giverId=36669,ender=[[Arcanist Tybalin]],enderType=[[NPC]],enderId=36669,prevId=14444,rewardNextId=20438,wowhead=[[https://www.wowhead.com/wotlk/quest=14457]],image=[[assets/images/quests/placeholder.png]],desc=[[One of my contacts in the Underbelly caught sight of a Sunreaver agent buying reagents from a dealer in the Black Market area. The Sunreavers normally aren't known for their interest in what goes on down in the sewers, so that's a big indication that they're planning something. Head into the Underbelly, find this Sunreaver agent, and take care of him. Search the body for any information that might give us a lead on the location of that tome from Wyrmrest. We can't let them get it back to Icecrown first.]],logDesc=[[Obtain the Sunreaver Orders.]]}
DB[14483]={id=14483,name=[[Something is in the Air (and it Ain't Love)]],level=80,minLevel=75,giverType=[[NPC]],ender=[[Detective Snap Snagglebolt]],enderType=[[NPC]],enderId=37172,wowhead=[[https://www.wowhead.com/wotlk/quest=14483]],image=[[assets/images/quests/placeholder.png]],desc=[[The inside of the card is scribbled with mad, detailed plans to infect most of Azeroth.  You should show this to one of Steamwheedle's investigators immediately!]],logDesc=[[Bring the Faded Lovely Greeting Card to Detective Snap Snagglebolt in Orgrimmar.]]}
DB[14488]={id=14488,name=[[You've Been Served]],level=80,minLevel=75,giver=[[Investigator Fezzen Brasstacks]],giverType=[[NPC]],giverId=38208,ender=[[Apothecary Hummel]],enderType=[[NPC]],enderId=36296,wowhead=[[https://www.wowhead.com/wotlk/quest=14488]],image=[[assets/images/quests/placeholder.png]],desc=[[You made it, huh? Good. I've been waiting for help. No time like the present to act, right? Take this kit and head deeper inside to serve papers to the leader of that scumbag chemical company, Hummel. The paper's inside. So's a little something to protect you from any chemical tricks they might pull. Use one of the neutralizers when the time comes, all right?]],logDesc=[[Serve the Court Subpoena to Apothecary Hummel in Shadowfang Keep.]]}
DB[20438]={id=20438,zoneId=210,name=[[A Suitable Disguise]],level=80,minLevel=80,giver=[[Arcanist Tybalin]],giverType=[[NPC]],giverId=36669,ender=[[Arcanist Tybalin]],enderType=[[NPC]],enderId=36669,prevId=14457,rewardNextId=20439,wowhead=[[https://www.wowhead.com/wotlk/quest=20438]],image=[[assets/images/quests/placeholder.png]],desc=[[Getting you inside the Sunreaver's Sanctuary will be tougher than it appears. Only those who possess Sunreaver tabards are permitted entry to sanctuary. If we can get our hands on one, a simple enchantment will do the rest of the work. On the balcony above Threads of Fate, you'll find Shandy Glossgleam. I've helped him a few times in the past, so he owes me a favor. He handles laundry for a wide variety of people in the city. Maybe he can find a way to 'lend' you a tabard for a while.]],logDesc=[[Obtain a Borrowed Tabard from Shandy Glossgleam.]]}
DB[20439]={id=20439,zoneId=210,name=[[A Meeting With The Magister]],level=80,minLevel=80,giver=[[Arcanist Tybalin]],giverType=[[NPC]],giverId=36669,ender=[[Arcanist Tybalin]],enderType=[[NPC]],enderId=36669,prevId=20438,rewardNextId=24454,wowhead=[[https://www.wowhead.com/wotlk/quest=20439]],image=[[assets/images/quests/placeholder.png]],desc=[[I've placed an enchantment on the tabard that should allow you to slip past the Sunreaver Sanctuary's defenses for a short period of time. You should have enough time to find your way into The Filthy Animal and meet up with the Sunreaver contact there, one Magister Hathorel. Obtain the copy of Ancient Dragonforged Blades that his men borrowed from Wyrmrest while your disguise holds, and return it to me.]],logDesc=[[Retrieve the Ancient Dragonforged Blades tome from Magister Hathorel.]]}
DB[24216]={id=24216,zoneId=3277,name=[[Call to Arms: Warsong Gulch]],name_loc=[[Llamamiento a las armas: Garganta Grito de Guerra]],level=-1,minLevel=21,giverType=[[NPC]],enderType=[[NPC]],exGroup=24216,poiX=1316,poiY=357,wowhead=[[https://www.wowhead.com/wotlk/quest=24216]],image=[[assets/images/quests/placeholder.png]],desc=[[The Alliance is an insidious enemy, $N.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens. Today we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!]],logDesc=[[Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath. ]]}
DB[24217]={id=24217,zoneId=3277,name=[[Call to Arms: Warsong Gulch]],name_loc=[[Llamamiento a las armas: Garganta Grito de Guerra]],level=-1,minLevel=11,giverType=[[NPC]],enderType=[[NPC]],poiX=1316,poiY=357,wowhead=[[https://www.wowhead.com/wotlk/quest=24217]],image=[[assets/images/quests/placeholder.png]],desc=[[The Alliance is an insidious enemy, $N.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens. Today we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!]],logDesc=[[Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath. ]]}
DB[24218]={id=24218,zoneId=3277,name=[[Call to Arms: Warsong Gulch]],name_loc=[[Llamamiento a las armas: Garganta Grito de Guerra]],level=-1,minLevel=21,giverType=[[NPC]],enderType=[[NPC]],exGroup=24218,poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=24218]],image=[[assets/images/quests/placeholder.png]],desc=[[The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory. Their need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!]],logDesc=[[Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.]]}
DB[24219]={id=24219,zoneId=3277,name=[[Call to Arms: Warsong Gulch]],name_loc=[[Llamamiento a las armas: Garganta Grito de Guerra]],level=-1,minLevel=11,giverType=[[NPC]],enderType=[[NPC]],poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=24219]],image=[[assets/images/quests/placeholder.png]],desc=[[The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory. Their need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!]],logDesc=[[Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.]]}
DB[24220]={id=24220,zoneId=3358,name=[[Call to Arms: Arathi Basin]],name_loc=[[Llamamiento a las armas: Cuenca de Arathi]],level=-1,minLevel=21,giverType=[[NPC]],enderType=[[NPC]],exGroup=24218,poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=24220]],image=[[assets/images/quests/placeholder.png]],desc=[[The reality of fighting on multiple fronts, $g lad : lass;, is that we cannot spread our forces too thin or we risk losing it all! Critical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements. Return to me with news of victory, $N.  We cannot allow the Horde scum to secure the resources that are rightfully ours!]],logDesc=[[Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.]]}
DB[24221]={id=24221,zoneId=3358,name=[[Call to Arms: Arathi Basin]],name_loc=[[Llamamiento a las armas: Cuenca de Arathi]],level=-1,minLevel=21,giverType=[[NPC]],enderType=[[NPC]],exGroup=24216,poiX=1316,poiY=357,wowhead=[[https://www.wowhead.com/wotlk/quest=24221]],image=[[assets/images/quests/placeholder.png]],desc=[[Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain. Do not delay, $c, go to Arathi Basin and crush the enemy.  Victory to the Horde!]],logDesc=[[Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.]]}
DB[24222]={id=24222,zoneId=3820,name=[[Call to Arms: Eye of the Storm DEPRECATED]],level=-1,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=24222]],image=[[assets/images/quests/placeholder.png]],desc=[[We will fight and crush the enemy wherever we find them.  Azeroth,Outland,the place makes no difference. We cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!]],logDesc=[[Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city,Wintergrasp,Dalaran, or Shattrath.]]}
DB[24223]={id=24223,zoneId=3358,name=[[Call to Arms: Arathi Basin]],name_loc=[[Llamamiento a las armas: Cuenca de Arathi]],level=-1,minLevel=51,giverType=[[NPC]],enderType=[[NPC]],exGroup=24224,poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=24223]],image=[[assets/images/quests/placeholder.png]],desc=[[The reality of fighting on multiple fronts, $g lad : lass;, is that we cannot spread our forces too thin or we risk losing it all! Critical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements. Return to me with news of victory, $N.  We cannot allow the Horde scum to secure the resources that are rightfully ours!]],logDesc=[[Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.]]}
DB[24224]={id=24224,zoneId=3277,name=[[Call to Arms: Warsong Gulch]],name_loc=[[Llamamiento a las armas: Garganta Grito de Guerra]],level=-1,minLevel=51,giverType=[[NPC]],enderType=[[NPC]],exGroup=24224,poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=24224]],image=[[assets/images/quests/placeholder.png]],desc=[[The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory. Their need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!]],logDesc=[[Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.]]}
DB[24225]={id=24225,zoneId=3277,name=[[Call to Arms: Warsong Gulch]],name_loc=[[Llamamiento a las armas: Garganta Grito de Guerra]],level=-1,minLevel=51,giverType=[[NPC]],enderType=[[NPC]],exGroup=24225,poiX=1316,poiY=357,wowhead=[[https://www.wowhead.com/wotlk/quest=24225]],image=[[assets/images/quests/placeholder.png]],desc=[[The Alliance is an insidious enemy, $N.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens. Today we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!]],logDesc=[[Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath. ]]}
DB[24226]={id=24226,zoneId=3358,name=[[Call to Arms: Arathi Basin]],name_loc=[[Llamamiento a las armas: Cuenca de Arathi]],level=-1,minLevel=51,giverType=[[NPC]],enderType=[[NPC]],exGroup=24225,poiX=1316,poiY=357,wowhead=[[https://www.wowhead.com/wotlk/quest=24226]],image=[[assets/images/quests/placeholder.png]],desc=[[Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain. Do not delay, $c, go to Arathi Basin and crush the enemy.  Victory to the Horde!]],logDesc=[[Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.]]}
DB[24227]={id=24227,zoneId=3820,name=[[DEPRECATED]],level=-1,minLevel=61,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=24227]],image=[[assets/images/quests/placeholder.png]],desc=[[The fight against the Horde knows no boundaries,$N.  Even in Outland,territorial disputes and old hatreds are enough to tip the scales in favor of war. Go into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.]],logDesc=[[Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city,Wintergrasp,Dalaran,or Shattrath.]]}
DB[24426]={id=24426,zoneId=2597,name=[[Call to Arms: Alterac Valley]],name_loc=[[Llamamiento a las armas: Valle de Alterac]],level=-1,minLevel=51,giverType=[[NPC]],enderType=[[NPC]],exGroup=24225,poiX=1316,poiY=357,wowhead=[[https://www.wowhead.com/wotlk/quest=24426]],image=[[assets/images/quests/placeholder.png]],desc=[[We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan. A decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts. Go, $N.  Earn great honor by heeding the call of the brave Frostwolf warriors.]],logDesc=[[Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran or Shattrath.]]}
DB[24427]={id=24427,zoneId=2597,name=[[Call to Arms: Alterac Valley]],name_loc=[[Llamamiento a las armas: Valle de Alterac]],level=-1,minLevel=51,giverType=[[NPC]],ender=[[Alliance Brigadier General]],ender_loc=[[General de brigada de la Alianza]],enderType=[[NPC]],enderId=15351,exGroup=24224,poiX=-8767,poiY=408,wowhead=[[https://www.wowhead.com/wotlk/quest=24427]],image=[[assets/images/quests/placeholder.png]],desc=[[The reality of fighting on multiple fronts, $g lad : lass;, is that we cannot spread our forces too thin or we risk losing it all! Critical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants. Go now, $N, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!]],logDesc=[[Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran or Shattrath. ]]}
DB[24428]={id=24428,zoneId=1519,name=[[A Most Puzzling Circumstance]],level=80,minLevel=80,giverType=[[NPC]],ender=[[Zardeth of the Black Claw]],enderType=[[NPC]],enderId=1435,wowhead=[[https://www.wowhead.com/wotlk/quest=24428]],image=[[assets/images/quests/placeholder.png]],desc=[[You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Zardeth of the Black Claw.]],logDesc=[[Take the Head of Onyxia to Zardeth of the Black Claw in the basement of the Slaughtered Lamb.]],choiceRewards={{id=49486,qty=1},{id=49485,qty=1},{id=49487,qty=1}}}
DB[24429]={id=24429,zoneId=1637,name=[[A Most Puzzling Circumstance]],level=80,minLevel=80,giverType=[[NPC]],ender=[[Neeru Fireblade]],enderType=[[NPC]],enderId=3216,wowhead=[[https://www.wowhead.com/wotlk/quest=24429]],image=[[assets/images/quests/placeholder.png]],desc=[[You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Neeru Fireblade.]],logDesc=[[Take the Head of Onyxia to Neeru Fireblade in the Cleft of Shadow.]],choiceRewards={{id=49486,qty=1},{id=49485,qty=1},{id=49487,qty=1}}}
DB[24431]={id=24431,zoneId=4613,name=[[Waterlogged Recipe]],level=80,minLevel=70,giverType=[[NPC]],ender=[[Christi Stockton]],enderType=[[NPC]],enderId=32337,wowhead=[[https://www.wowhead.com/wotlk/quest=24431]],image=[[assets/images/quests/placeholder.png]],desc=[[This appears to be the remains of a mixture for potent wine.  Perhaps the proprietor of One More Glass in Dalaran would be interested in it....]],logDesc=[[Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city.]],rewards={{id=43016,qty=5}}}
DB[24442]={id=24442,zoneId=4769,name=[[Battle Plans Of The Kvaldir]],level=80,minLevel=77,giverType=[[NPC]],ender=[[Justicar Mariel Trueheart]],enderType=[[NPC]],enderId=33817,wowhead=[[https://www.wowhead.com/wotlk/quest=24442]],image=[[assets/images/quests/placeholder.png]],desc=[[Looking over the captured attack plans, you find a map of the Eastern Kingdoms and Kalimdor with major settlements marked. Reading over the orders, you learn that  Kvaldir captains have drafted plans for a series of devastating raids. According to the orders, the attacks are to begin after Mistcaller Yngvar "consults the Heart of the Mists." Perhaps you could delay the attacks by capturing the omen from the Mistcaller's Cave on the western side of Hrothgar's Landing and notify Justicar Mariel Trueheart.]],logDesc=[[Recover the Heart of the Mists and bring it and the Kvaldir Attack Plans to Justicar Mariel Trueheart at the Argent Tournament Grounds.]]}
DB[24451]={id=24451,zoneId=210,name=[[An Audience With The Arcanist]],level=80,minLevel=80,giver=[[Magister Hathorel]],giverType=[[NPC]],giverId=36670,ender=[[Magister Hathorel]],enderType=[[NPC]],enderId=36670,prevId=24556,rewardNextId=24558,wowhead=[[https://www.wowhead.com/wotlk/quest=24451]],image=[[assets/images/quests/placeholder.png]],desc=[[I've placed an enchantment on the tabard that should allow you to slip past the Silver Enclave's defenses for a short period of time. You should have enough time to find your way up to the top level of the Silver Enclave and meet up with the Silver Covenant's man there, known as Arcanist Tybalin. While disguised, obtain the copy of Ancient Dragonforged Blades that his men borrowed from Wyrmrest, and return the book to me.]],logDesc=[[Retrieve the Ancient Dragonforged Blades tome from Arcanist Tybalin.]]}
DB[24454]={id=24454,zoneId=210,name=[[Return To Caladis Brightspear]],level=80,minLevel=80,giver=[[Arcanist Tybalin]],giverType=[[NPC]],giverId=36669,ender=[[Caladis Brightspear]],enderType=[[NPC]],enderId=36624,prevId=20439,wowhead=[[https://www.wowhead.com/wotlk/quest=24454]],image=[[assets/images/quests/placeholder.png]],desc=[[We must get this book to Caladis Brightspear immediately. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at keeping the Sunreavers at bay. Take it with you to Quel'Delar's rest, south of the Argent Tournament Grounds in Icecrown. Caladis and the sword will be waiting. The sooner we can identify the blade, the sooner we can claim it.]],logDesc=[[Bring Ancient Dragonforged Blades to Caladis Brightspear at Quel'Delar's Rest.]]}
DB[24461]={id=24461,zoneId=4813,name=[[Reforging The Sword]],level=80,minLevel=80,giver=[[Caladis Brightspear]],giverType=[[NPC]],giverId=36624,ender=[[Caladis Brightspear]],enderType=[[NPC]],enderId=36624,prevId=24454,rewardNextId=24476,wowhead=[[https://www.wowhead.com/wotlk/quest=24461]],image=[[assets/images/quests/placeholder.png]],desc=[[We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel. In the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar. You must gather bars of infused saronite and capture the forgemaster's hammer, then bring them to the forgemaster's anvil and reforge the sword.]],logDesc=[[Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer and use them to make the Reforged Quel'Delar.]]}
DB[24476]={id=24476,zoneId=210,name=[[Tempering The Blade]],level=80,minLevel=80,giver=[[Caladis Brightspear]],giverType=[[NPC]],giverId=36624,ender=[[Caladis Brightspear]],enderType=[[NPC]],enderId=36624,prevId=24461,rewardNextId=24480,wowhead=[[https://www.wowhead.com/wotlk/quest=24476]],image=[[assets/images/quests/placeholder.png]],desc=[[At last, the pieces of Quel'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything. Deep in Icecrown Citadel's Forge of Souls is a place where the blade can safely be tempered. Take Quel'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me in The Frozen Halls.]],logDesc=[[Temper the Reforged Quel'Delar in the Crucible of Souls.]]}
DB[24480]={id=24480,zoneId=4820,name=[[The Halls Of Reflection]],level=80,minLevel=80,giver=[[Caladis Brightspear]],giverType=[[NPC]],giverId=36624,ender=[[Caladis Brightspear]],enderType=[[NPC]],enderId=36624,prevId=24476,rewardNextId=24522,wowhead=[[https://www.wowhead.com/wotlk/quest=24480]],image=[[assets/images/quests/placeholder.png]],desc=[[You have reforged and tempered the sword, yet it sits quietly in its sheath, showing no signs of the power it should possess. You say the sword pulls you, as though it possesses a will? Dare you bring it where it wishes to go? It's not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Take it into Icecrown Citadel's Halls of Reflection, but be on your guard! I'll be waiting for you in The Frozen Halls.]],logDesc=[[Bring your Tempered Quel'Delar to Sword's Rest inside the Halls of Reflection.]]}
DB[24498]={id=24498,zoneId=4813,name=[[The Path to the Citadel]],level=80,minLevel=78,giver=[[Lady Jaina Proudmoore]],giverType=[[NPC]],giverId=36993,ender=[[Martin Victus]],enderType=[[NPC]],enderId=37591,prevId=24683,rewardNextId=24710,wowhead=[[https://www.wowhead.com/wotlk/quest=24498]],image=[[assets/images/quests/placeholder.png]],desc=[[They've put our captured soldiers to work in the quarry! Kill their captors and set them free, hero, and do it quickly. We will need their aid when we confront Scourgelord Tyrannus.]],logDesc=[[Free 15 Alliance Slaves and kill Forgemaster Garfrost.]]}
DB[24499]={id=24499,zoneId=4809,name=[[Echoes of Tortured Souls]],level=80,minLevel=78,giver=[[Lady Jaina Proudmoore]],giverType=[[NPC]],giverId=37597,ender=[[Lady Jaina Proudmoore]],enderType=[[NPC]],enderId=38160,prevId=24510,rewardNextId=24683,wowhead=[[https://www.wowhead.com/wotlk/quest=24499]],image=[[assets/images/quests/placeholder.png]],desc=[[I cannot thank you enough for coming. We're severely undermanned to be risking a venture into the citadel, but opportunities like this are too rare to pass up. I'm awaiting the arrival of champions from the coliseum, but if your reputation holds true, you should be more than equipped to fight through the forge yourself. Clear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the citadel. Please hurry, $n. We're counting on you.]],logDesc=[[Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.]],rewards={{id=49426,qty=2}}}
DB[24500]={id=24500,zoneId=4820,name=[[Wrath of the Lich King]],level=80,minLevel=78,giver=[[Archmage Koreln]],giverType=[[NPC]],giverId=37582,ender=[[Lady Jaina Proudmoore]],enderType=[[NPC]],enderId=36955,prevId=24711,wowhead=[[https://www.wowhead.com/wotlk/quest=24500]],image=[[assets/images/quests/placeholder.png]],desc=[[Uther knew a great deal about how Arthas might be defeated. It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that? Many questions remain, but the answers that you've uncovered may be critical to ensuring Arthas' defeat. You need to find Jaina and escape the Lich King while there's still time.]],logDesc=[[Find Lady Jaina Proudmoore and escape the Halls of Reflection]],rewards={{id=49426,qty=2}}}
DB[24506]={id=24506,zoneId=4809,name=[[Inside the Frozen Citadel]],level=80,minLevel=78,giver=[[Dark Ranger Vorel]],giverType=[[NPC]],giverId=37780,ender=[[Lady Sylvanas Windrunner]],enderType=[[NPC]],enderId=37596,rewardNextId=24511,wowhead=[[https://www.wowhead.com/wotlk/quest=24506]],image=[[assets/images/quests/placeholder.png]],desc=[[$C! Come close quickly, I must have a word! My queen, the Lady Sylvanas Windrunner, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as "The Forge of Souls." She sent word before she left for me to find fierce fighters to send her way. I think you'll do. Go to her within the entrance to the forge, $c.]],logDesc=[[Enter The Forge of Souls from the side of Icecrown Citadel and locate Lady Sylvanas Windrunner.]]}
DB[24507]={id=24507,zoneId=4813,name=[[The Path to the Citadel]],level=80,minLevel=78,giver=[[Lady Sylvanas Windrunner]],giverType=[[NPC]],giverId=36990,ender=[[Gorkun Ironskull]],enderType=[[NPC]],enderId=37592,prevId=24682,rewardNextId=24712,wowhead=[[https://www.wowhead.com/wotlk/quest=24507]],image=[[assets/images/quests/placeholder.png]],desc=[[They've put our captured soldiers to work in the quarry. Kill their captors and set them free, $c, and do it quickly. We will need their aid when we confront Scourgelord Tyrannus.]],logDesc=[[Free 15 Horde Slaves and kill Forgemaster Garfrost.]]}
DB[24508]={id=24508,name=[[Temp Quest Record]],level=80,minLevel=78,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=24508]],image=[[assets/images/quests/placeholder.png]]}
DB[24509]={id=24509,name=[[Temp Quest Record]],level=80,minLevel=78,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=24509]],image=[[assets/images/quests/placeholder.png]]}
DB[24510]={id=24510,zoneId=4809,name=[[Inside the Frozen Citadel]],level=80,minLevel=78,giver=[[Apprentice Nelphi]],giverType=[[NPC]],giverId=37776,ender=[[Lady Jaina Proudmoore]],enderType=[[NPC]],enderId=37597,rewardNextId=24499,wowhead=[[https://www.wowhead.com/wotlk/quest=24510]],image=[[assets/images/quests/placeholder.png]],desc=[[$C! Come close quickly, I must have a word! My patron, the Lady Jaina Proudmoore, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as "The Forge of Souls." She sent word before she left for me to find any help that I could... and, well, I was hoping that might be you. Please, find her there as soon as you can.]],logDesc=[[Enter The Forge of Souls from the side of Icecrown Citadel and find Lady Jaina Proudmoore.]]}
DB[24511]={id=24511,zoneId=4809,name=[[Echoes of Tortured Souls]],level=80,minLevel=78,giver=[[Lady Sylvanas Windrunner]],giverType=[[NPC]],giverId=37596,ender=[[Lady Sylvanas Windrunner]],enderType=[[NPC]],enderId=38161,prevId=24506,rewardNextId=24682,wowhead=[[https://www.wowhead.com/wotlk/quest=24511]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm glad we have someone capable to aid us in this. Delving into the citadel with so few is risky at best, but opportunities like this are too rare to pass up. I'm awaiting the arrival of champions from the coliseum, but if your reputation holds true, you should be more than equipped to fight through the forge yourself. Clear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the Citadel. Be quick about it, $n. Time is short.]],logDesc=[[Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.]],rewards={{id=49426,qty=2}}}
DB[24522]={id=24522,zoneId=4080,name=[[Journey To The Sunwell]],level=80,minLevel=80,giver=[[Caladis Brightspear]],giverType=[[NPC]],giverId=36624,ender=[[Halduron Brightwing]],enderType=[[NPC]],enderId=37527,prevId=24480,rewardNextId=24535,wowhead=[[https://www.wowhead.com/wotlk/quest=24522]],image=[[assets/images/quests/placeholder.png]],desc=[[Take Quel'Delar to the Sunwell as quickly as possible, $N. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword. The guardians of the Sunwell will not simply allow you to walk in, so you must find Halduron Brightwing, who will be inspecting the guards there.]],logDesc=[[Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas.]]}
DB[24535]={id=24535,zoneId=4080,name=[[Thalorien Dawnseeker]],level=80,minLevel=80,giver=[[Halduron Brightwing]],giverType=[[NPC]],giverId=37527,ender=[[Halduron Brightwing]],enderType=[[NPC]],enderId=37527,prevId=24522,wowhead=[[https://www.wowhead.com/wotlk/quest=24535]],image=[[assets/images/quests/placeholder.png]],desc=[[If you truly bear Quel'Delar, $N, I might be able to admit you to the Sunwell. If you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.]],logDesc=[[Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar.]]}
DB[24536]={id=24536,name=[[Something Stinks]],name_loc=[[Algo apesta]],level=-1,minLevel=1,giver=[[Detective Snap Snagglebolt]],giver_loc=[[Detective Snap Tuerceganzúas]],giverType=[[NPC]],giverId=37172,ender=[[Detective Snap Snagglebolt]],ender_loc=[[Detective Snap Tuerceganzúas]],enderType=[[NPC]],enderId=37172,prevId=24805,rewardNextId=24541,poiX=1658,poiY=-4392,wowhead=[[https://www.wowhead.com/wotlk/quest=24536]],image=[[assets/images/quests/placeholder.png]],desc=[[Get a load of these guys, would ya? Steamwheedle's been handling the business of holidays for years, and all of a sudden, these guys bust into the market. They're not Steamwheedle; the cartel hired me to get to the bottom of this. Something stinks here and it ain't just perfume. Take this device I brought and go analyze the perfume clouds around the guards. I want to know what they're putting in that stuff. Things ain't natural.]],logDesc=[[Use Snagglebolt's Air Analyzer to test the air around 6 heavily perfumed guards, then return to Detective Snap Snagglebolt in Orgrimmar.]]}
DB[24541]={id=24541,name=[[Pilfering Perfume]],name_loc=[[Afanar el aroma]],level=-1,minLevel=1,giver=[[Detective Snap Snagglebolt]],giver_loc=[[Detective Snap Tuerceganzúas]],giverType=[[NPC]],giverId=37172,ender=[[Detective Snap Snagglebolt]],ender_loc=[[Detective Snap Tuerceganzúas]],enderType=[[NPC]],enderId=37172,prevId=24536,rewardNextId=24850,poiX=1658,poiY=-4392,wowhead=[[https://www.wowhead.com/wotlk/quest=24541]],image=[[assets/images/quests/placeholder.png]],desc=[[I knew they were up to no good! There's some sort of mind-affecting chemical in here, but I can't get a handle on it with such a small sample. I need the real stuff. Don't just go over there and buy it! I don't want you giving these scumbags one copper. Nah, you gotta get it from the source, discreet-like. I'll disguise you as a package runner. I saw a stockpile guarded by their goons outside the gates. Go run by, and DON'T stop, or they'll make you! They'll toss you a crate. Bring it back here.]],logDesc=[[While disguised as a package-runner, go to the Crown Chemical Company's stockpile outside the gates of Orgrimmar, then return the package they toss you to Detective Snap Snagglebolt in Orgimmar.]]}
DB[24545]={id=24545,zoneId=4812,name=[[The Sacred and the Corrupt]],level=80,minLevel=80,giver=[[Highlord Darion Mograine]],giverType=[[NPC]],giverId=37120,enderType=[[NPC]],nextId=24743,wowhead=[[https://www.wowhead.com/wotlk/quest=24545]],image=[[assets/images/quests/placeholder.png]],desc=[[It is against my judgment that I present you this errand, $r, as it will likely end in your undoing. Ignore my counsel and embark on the endeavor, and I shall provide you with the knowledge and resources to see it through. You must return to Frostmourne Cavern and recover Light's Vengeance, Arthas' discarded hammer. Reforged with saronite and etched with the acidic blood of the Lich King's abominations, it will provide the foundation for our work.]],logDesc=[[Place Light's Vengeance, 25 Primordial Saronite, Rotface's Acidic Blood, and Festergut's Acidic Blood in Highlord Mograine's runeforge in Icecrown Citadel. Rotface's Acidic Blood and Festergut's Acidic Blood may only be obtained in the 25 person difficulty setting of Icecrown Citadel.]]}
DB[24547]={id=24547,zoneId=4812,name=[[A Feast of Souls]],level=80,minLevel=80,giver=[[Highlord Darion Mograine]],giverType=[[NPC]],giverId=37120,ender=[[Highlord Darion Mograine]],enderType=[[NPC]],enderId=37120,prevId=24743,nextId=24749,wowhead=[[https://www.wowhead.com/wotlk/quest=24547]],image=[[assets/images/quests/placeholder.png]],desc=[[Shadow's Edge is among the greatest weapons a $c could hope to obtain. Is your lust for power sated, $r? <You feel Mograine's penetrating gaze.> I thought not. A final warning then... You now embark on the most treacherous leg of your quest. Bridle your aspirations, for if your aims are impure then your life, your very soul, is forfeit. The weapon you hold is but an empty husk, a mere shadow of what it may become. Only by devouring a thousand souls shall its true potential be unlocked.]],logDesc=[[Highlord Darion Mograine wants you to use Shadow's Edge to slay 1000 of the Lich King's minions in Icecrown Citadel. Souls can be obtained in 10 or 25 person difficulty.]]}
DB[24548]={id=24548,zoneId=4812,name=[[The Splintered Throne]],level=80,minLevel=80,giver=[[Highlord Darion Mograine]],giverType=[[NPC]],giverId=37120,ender=[[Highlord Darion Mograine]],enderType=[[NPC]],enderId=37120,prevId=24757,nextId=24912,wowhead=[[https://www.wowhead.com/wotlk/quest=24548]],image=[[assets/images/quests/placeholder.png]],desc=[[The Lich King's throne once served as his prison. Kil'jaeden himself crafted the vessel of icy crystals from the twisting nether, its sole purpose to hold Ner'zhul's vengeful spirit. When Arthas struck the crystal with Frostmourne, he released Ner'zhul's soul, allowing it to merge with his own. Splinters from that impact are now scattered throughout the citadel. I shall require those shards, held only by the Lich King's most powerful servants, to seal the power contained in your blade.]],logDesc=[[Highlord Darion Mograine wants you to collect 50 Shadowfrost Shards. Shadowfrost Shards may only be obtained in the 25 person difficulty setting.]]}
DB[24549]={id=24549,zoneId=4812,name=[[Shadowmourne...]],level=80,minLevel=80,giver=[[Highlord Darion Mograine]],giverType=[[NPC]],giverId=37120,ender=[[Highlord Darion Mograine]],enderType=[[NPC]],enderId=37120,prevId=24912,nextId=24748,wowhead=[[https://www.wowhead.com/wotlk/quest=24549]],image=[[assets/images/quests/placeholder.png]],logDesc=[[Highlord Darion Mograine wants you to bring him Shadow's Edge.]],rewards={{id=49623,qty=1}}}
DB[24553]={id=24553,zoneId=4075,name=[[The Purification of Quel'Delar]],level=80,minLevel=80,giver=[[Halduron Brightwing]],giverType=[[NPC]],giverId=37527,ender=[[Caladis Brightspear]],enderType=[[NPC]],enderId=36624,prevId=24535,rewardNextId=24796,wowhead=[[https://www.wowhead.com/wotlk/quest=24553]],image=[[assets/images/quests/placeholder.png]],desc=[[I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to me and to the rest of my people that Quel'Delar has been recovered. As promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. The blade will bond to you. When that happens, carry it to Caladis Brightspear at Quel'Delar's Rest.]],logDesc=[[Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.]]}
DB[24554]={id=24554,zoneId=210,name=[[The Battered Hilt]],level=80,minLevel=80,giverType=[[NPC]],ender=[[Myralion Sunblaze]],enderType=[[NPC]],enderId=36642,rewardNextId=24555,wowhead=[[https://www.wowhead.com/wotlk/quest=24554]],image=[[assets/images/quests/placeholder.png]],desc=[[This battered old sword hilt has seen better days. Before the hilt was snapped from the blade, it must've been a magnificent example of the blacksmith's art. The graceful symbols and exotic gemstones decorating the hilt suggest that the weapon may have belonged to a powerful person. Surely, the Sunreavers would be interested in hearing about the recovery of such an artifact. Seek out their representatives at Quel'Delar's Rest, to the south of the Argent Tournament Grounds.]],logDesc=[[Bring the Battered Hilt to Myralion Sunblaze at Quel'Delar's Rest, south of the Argent Tournament Grounds.]]}
DB[24555]={id=24555,zoneId=210,name=[[What The Dragons Know]],level=80,minLevel=80,giver=[[Myralion Sunblaze]],giverType=[[NPC]],giverId=36642,ender=[[Magister Hathorel]],enderType=[[NPC]],enderId=36670,prevId=24554,rewardNextId=24557,wowhead=[[https://www.wowhead.com/wotlk/quest=24555]],image=[[assets/images/quests/placeholder.png]],desc=[[There's no mistaking it - this hilt comes from a powerful, ancient weapon, but which one? I do not recognize these particular markings, but we haven't hit a dead end yet. Korialstrasz, better known as Krasus, has long been a friend to the quel'dorei and the Kirin Tor. With his vast knowledge and resources, he's certain to know something. Travel to the top of Wyrmrest Temple and seek his counsel, then report to Magister Hathorel inside Sunreaver's Sanctuary in Dalaran.]],logDesc=[[Speak to Krasus at the top of Wyrmrest Temple.]]}
DB[24556]={id=24556,zoneId=210,name=[[A Suitable Disguise]],level=80,minLevel=80,giver=[[Magister Hathorel]],giverType=[[NPC]],giverId=36670,ender=[[Magister Hathorel]],enderType=[[NPC]],enderId=36670,prevId=24557,rewardNextId=24451,wowhead=[[https://www.wowhead.com/wotlk/quest=24556]],image=[[assets/images/quests/placeholder.png]],desc=[[Getting you inside the Silver Enclave will be tougher than it appears. Only those who possess Silver Covenant tabards are permitted entry to sanctuary. If we can get our hands on one, a simple enchantment will do the rest of the work. On the balcony above Threads of Fate, you'll find Shandy Glossgleam. I've helped him a few times in the past, so he owes me a favor. He handles laundry for a wide variety of people in the city. Maybe he can find a way to 'lend' you a tabard for a while.]],logDesc=[[Obtain a Borrowed Tabard from Shandy Glossgleam.]]}
DB[24557]={id=24557,zoneId=4395,name=[[The Silver Covenant's Scheme]],level=80,minLevel=80,giver=[[Magister Hathorel]],giverType=[[NPC]],giverId=36670,ender=[[Magister Hathorel]],enderType=[[NPC]],enderId=36670,prevId=24555,rewardNextId=24556,wowhead=[[https://www.wowhead.com/wotlk/quest=24557]],image=[[assets/images/quests/placeholder.png]],desc=[[One of my contacts in the Underbelly caught sight of a Silver Covenant agent gathering information at the Cantrips and Crows Tavern. Silver Covenant members aren't normally found in the sewers, so they must be plotting something. Go into the Underbelly, find this Silver Covenant agent, and eliminate him. Search the body for any information that might give us a lead on the location of that tome from Wyrmrest. We can't let those simpering Silver Covenant weaklings get it back to Icecrown before we do.]],logDesc=[[Capture the Silver Covenant Orders.]]}
DB[24558]={id=24558,zoneId=210,name=[[Return To Myralion Sunblaze]],level=80,minLevel=80,giver=[[Magister Hathorel]],giverType=[[NPC]],giverId=36670,ender=[[Myralion Sunblaze]],enderType=[[NPC]],enderId=36642,prevId=24451,wowhead=[[https://www.wowhead.com/wotlk/quest=24558]],image=[[assets/images/quests/placeholder.png]],desc=[[We must get this book to Myralion Sunblade. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at evading the Silver Covenant's men. Take it with you to Quel'Delar's Rest, south of the Argent Tournament Grounds in Icecrown. Myralion will be waiting for you. If he can identify that blade, we may be able to claim it in the name of Aethas Sunreaver and show Dalaran and the Alliance that we will lead the charge against the Lich King.]],logDesc=[[Bring Ancient Dragonforged Blades to Myralion Sunblaze at Quel'Delar's Rest.]]}
DB[24559]={id=24559,zoneId=4813,name=[[Reforging The Sword]],level=80,minLevel=80,giver=[[Myralion Sunblaze]],giverType=[[NPC]],giverId=36642,ender=[[Myralion Sunblaze]],enderType=[[NPC]],enderId=36642,prevId=24558,rewardNextId=24560,wowhead=[[https://www.wowhead.com/wotlk/quest=24559]],image=[[assets/images/quests/placeholder.png]],desc=[[We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel. In the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar. You must gather bars of infused saronite and capture the forgemaster's hammer, then bring them to the forgemaster's anvil and reforge the sword.]],logDesc=[[Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer, then combine them with the Remnants of Quel'Delar to create the Reforged Quel'Delar.]]}
DB[24560]={id=24560,zoneId=210,name=[[Tempering The Blade]],level=80,minLevel=80,giver=[[Myralion Sunblaze]],giverType=[[NPC]],giverId=36642,ender=[[Myralion Sunblaze]],enderType=[[NPC]],enderId=36642,prevId=24559,rewardNextId=24561,wowhead=[[https://www.wowhead.com/wotlk/quest=24560]],image=[[assets/images/quests/placeholder.png]],desc=[[At last, the pieces of Quel'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything. Deep in Icecrown Citadel's Forge of Souls is a place where the blade can safely be tempered. Take Quel'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me. I'll be waiting in The Frozen Halls.]],logDesc=[[Temper the Re-forged Quel'Delar in the Crucible of Souls.]]}
DB[24561]={id=24561,zoneId=4820,name=[[The Halls Of Reflection]],level=80,minLevel=80,giver=[[Myralion Sunblaze]],giverType=[[NPC]],giverId=36642,ender=[[Myralion Sunblaze]],enderType=[[NPC]],enderId=36642,prevId=24560,rewardNextId=24562,wowhead=[[https://www.wowhead.com/wotlk/quest=24561]],image=[[assets/images/quests/placeholder.png]],desc=[[You have re-forged and tempered the sword, yet it sits quietly in its sheath, little different from a mundane blade. You say the sword pulls you, as though it possesses a will? Dare you bring it where it wishes to go? It is not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Bear it with you to Icecrown Citadel's Halls of Reflection, but be on your guard. I will wait for you in The Frozen Halls.]],logDesc=[[Bring Quel'Delar to Sword's Rest inside the Halls of Reflection.]]}
DB[24562]={id=24562,zoneId=4080,name=[[Journey To The Sunwell]],level=80,minLevel=80,giver=[[Myralion Sunblaze]],giverType=[[NPC]],giverId=36642,ender=[[Halduron Brightwing]],enderType=[[NPC]],enderId=37527,prevId=24561,rewardNextId=24563,wowhead=[[https://www.wowhead.com/wotlk/quest=24562]],image=[[assets/images/quests/placeholder.png]],desc=[[Take Quel'Delar to the Sunwell as quickly as possible, $N. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword. The guardians will try to stop you from entering the Sunwell Plateau, but make yourself known to Halduron Brightwing, who will be inspecting the guards there.]],logDesc=[[Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas.]]}
DB[24563]={id=24563,zoneId=4080,name=[[Thalorien Dawnseeker]],level=80,minLevel=80,giver=[[Halduron Brightwing]],giverType=[[NPC]],giverId=37527,ender=[[Halduron Brightwing]],enderType=[[NPC]],enderId=37527,prevId=24562,wowhead=[[https://www.wowhead.com/wotlk/quest=24563]],image=[[assets/images/quests/placeholder.png]],desc=[[You are the one working with Myralion Sunblaze, arent you? I know of a way we can test the sword. If you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.]],logDesc=[[Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar.]]}
DB[24564]={id=24564,zoneId=4075,name=[[The Purification of Quel'Delar]],level=80,minLevel=80,giver=[[Halduron Brightwing]],giverType=[[NPC]],giverId=37527,ender=[[Myralion Sunblaze]],enderType=[[NPC]],enderId=36642,prevId=24563,rewardNextId=24801,wowhead=[[https://www.wowhead.com/wotlk/quest=24564]],image=[[assets/images/quests/placeholder.png]],desc=[[The Sunwell and the end of Quel'Delar's exile await, $N. You will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary and do not allow them to entrap you in their political scheming. Instead, remain focused on your task here. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Afterward, show the blade to Myralion Sunblaze at Quel'Delar's Rest.]],logDesc=[[Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau. ]]}
DB[24576]={id=24576,name=[[A Friendly Chat...]],name_loc=[[Una charla amistosa...]],level=-1,minLevel=1,giver=[[Roka]],giverType=[[NPC]],giverId=38328,ender=[[Detective Snap Snagglebolt]],ender_loc=[[Detective Snap Tuerceganzúas]],enderType=[[NPC]],enderId=37172,prevId=24851,poiX=1658,poiY=-4392,wowhead=[[https://www.wowhead.com/wotlk/quest=24576]],image=[[assets/images/quests/placeholder.png]],desc=[[<Roka listens with disgust as you tell her why you're trying to track down Snivel.> You mean I've been under the spell of an alchemist all this time? I can't believe I fell for that fraud! If I ever get my hands on that conniving little goblin, I'll tear him apart! If he's finished his errands, he's on his way down to the zeppelin tower east of Orgrimmar's gates! Whatever you do, $N, you can't let him board that zeppelin and get away with all this! Hurry to the zeppelin tower before you miss him!]],logDesc=[[Go to the zeppelin tower outside Orgrimmar and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.]]}
DB[24579]={id=24579,zoneId=4493,name=[[Sartharion Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24579]],image=[[assets/images/quests/placeholder.png]],desc=[[Sartharion, the Onyx Guardian, watches over the eggs of the Twilight Dragonflight. He rests within the Obsidian Sanctum in the Chamber of the Aspects underneath Wyrmrest Temple. The Council of Six has decreed that Sartharion must die!]],logDesc=[[Kill Sartharion. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24580]={id=24580,zoneId=3456,name=[[Anub'Rekhan Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24580]],image=[[assets/images/quests/placeholder.png]],desc=[[Anub'Rekhan, once-mighty Spider Lord of the nerubian empire, has been taken by the Lich King and corrupted into a state of undeath. Now a crypt lord, he sits in his parlor in the Arachnid Quarter of Naxxramas, spinning strategies for Kel'Thuzad. The Council of Six has decreed that Anub'Rekhan must die!]],logDesc=[[Kill Anub'Rekhan. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24581]={id=24581,zoneId=3456,name=[[Noth the Plaguebringer Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24581]],image=[[assets/images/quests/placeholder.png]],desc=[[Noth the Plaguebringer, traitor and coward! Second only to the Lich King himself for the number of souls that have been Scourged! Make haste to Naxxramas. You will find him within the Plague Quarter hiding behind his undead minions. Destroy him! The Council of Six has decreed that Noth must die!]],logDesc=[[Kill Noth the Plaguebringer. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24582]={id=24582,zoneId=3456,name=[[Instructor Razuvious Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24582]],image=[[assets/images/quests/placeholder.png]],desc=[[Instructor Razuvious smugly struts about the Military Quarter of Naxxramas. It is said that only a death knight personally trained by him could possibly even withstand the prowess of his blade. You and your group are going to prove everyone wrong. The Council of Six has decreed that Razuvious must die!]],logDesc=[[Kill Instructor Razuvious. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24583]={id=24583,zoneId=3456,name=[[Patchwerk Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24583]],image=[[assets/images/quests/placeholder.png]],desc=[[The so-called "avatar of war", Patchwerk is the ultimate abomination. It is also taking a heavy toll upon on our forces in the Dragonblight. I want you to assemble your companions and enter the Construct Quarter of Naxxramas. Disassemble the construct. The Council of Six has decreed that Patchwerk must die!]],logDesc=[[Kill Patchwerk. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24584]={id=24584,zoneId=4500,name=[[Malygos Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24584]],image=[[assets/images/quests/placeholder.png]],desc=[[Our resources are strained. Malygos, the Spell-Weaver, is draining all of the magic out of the world, consolidating it in the Eye of Eternity. Without magic, we are doomed. $C, the Nexus War must be brought to an end. The Council of Six has decreed that Malygos must die!]],logDesc=[[Kill Malygos. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24585]={id=24585,zoneId=4273,name=[[Flame Leviathan Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24585]],image=[[assets/images/quests/placeholder.png]],desc=[[Within the Formation Grounds sits Ulduar's first line of defense: Flame Leviathan. The Kirin Tor have been provided with information suggesting that this Keeper-created machine is soon to be transported to an undisclosed location and let loose to wreak havoc upon the mortals of Azeroth. This must not come to pass. The Council of Six has decreed that Flame Leviathan must die!]],logDesc=[[Kill Flame Leviathan. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24586]={id=24586,zoneId=4273,name=[[Razorscale Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24586]],image=[[assets/images/quests/placeholder.png]],desc=[[Razorscale normally keeps to her aerie near the Colossal Forge in Ulduar. Of late, however, she has been spotted reigning fire down upon lands outside of the titan complex. Though the broodmother's is a sad tale, she poses an imminent threat to all of Northrend. The Council of Six has decreed that Razorscale must die!]],logDesc=[[Kill Razorscale. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24587]={id=24587,zoneId=4273,name=[[Ignis the Furnace Master Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24587]],image=[[assets/images/quests/placeholder.png]],desc=[[The great fire giant, Ignis the Furnace Master toils away inside of Ulduar's Colossal Forge. Under orders from Loken, Ignis creates weapons that are terrifying in their power. The Council of Six has decreed that Ignis must die!]],logDesc=[[Kill Ignis the Furnace Master. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24588]={id=24588,zoneId=4273,name=[[XT-002 Deconstructor Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24588]],image=[[assets/images/quests/placeholder.png]],desc=[[Yet another strange construct of Mimiron, the XT-002 Deconstructor actually thinks that it is the keeper's son. Do not be fooled by its feigned innocence. It is a deadly machine! You will find the Deconstructor within Ulduar's Scrapyard. The Council of Six has decreed that XT-002 Deconstructor must die!]],logDesc=[[Kill XT-002 Deconstructor. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24589]={id=24589,zoneId=4722,name=[[Lord Jaraxxus Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24589]],image=[[assets/images/quests/placeholder.png]],desc=[[Archmage Timear has foreseen a horrible event, which is about to transpire. A foolish gnome warlock is about to accidentally summon an Eredar lord of the Burning Legion into the middle of the Trial of the Crusader. You must be there when it happens, $c. If Lord Jaraxxus escapes, he will open a portal and the Burning Legion will spill forth into our world once more. The Council of Six has decreed that Lord Jaraxxus must die!]],logDesc=[[Kill Lord Jaraxxus. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24590]={id=24590,zoneId=4812,name=[[Lord Marrowgar Must Die!]],level=80,minLevel=80,giver=[[Archmage Lan'dalock]],giverType=[[NPC]],giverId=20735,ender=[[Archmage Lan'dalock]],enderType=[[NPC]],enderId=20735,exGroup=24579,wowhead=[[https://www.wowhead.com/wotlk/quest=24590]],image=[[assets/images/quests/placeholder.png]],desc=[[Lord Marrowgar is the guardian of the Frozen Throne within the Spire Chamber. Pieced together by the Lich King from the bones of a thousand vanquished adventurers, Marrowgar wields the power of the throne itself. Without the destruction of this bone wraith, there is no hope of taking Icecrown Citadel. The Council of Six has decreed that Lord Marrowgar must die!]],logDesc=[[Kill Lord Marrowgar. This quest can be completed with any difficulty or size raid.]],rewards={{id=49426,qty=5},{id=47241,qty=5}}}
DB[24594]={id=24594,zoneId=4075,name=[[The Purification of Quel'Delar]],level=80,minLevel=80,giver=[[Halduron Brightwing]],giverType=[[NPC]],giverId=37527,ender=[[Myralion Sunblaze]],enderType=[[NPC]],enderId=36642,prevId=24563,rewardNextId=24800,wowhead=[[https://www.wowhead.com/wotlk/quest=24594]],image=[[assets/images/quests/placeholder.png]],desc=[[The Sunwell and the end of Quel'Delar's exile await, $N. You will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming. Instead, remain focused on your task here. Speak to a Warden of the Sunwell to enter the Sunwell Plateau. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Show the blade to Myralion Sunblaze at Quel'Delar's Rest once it is restored.]],logDesc=[[Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau. ]]}
DB[24595]={id=24595,zoneId=4075,name=[[The Purification of Quel'Delar]],level=80,minLevel=80,giver=[[Halduron Brightwing]],giverType=[[NPC]],giverId=37527,ender=[[Caladis Brightspear]],enderType=[[NPC]],enderId=36624,prevId=24535,rewardNextId=24795,wowhead=[[https://www.wowhead.com/wotlk/quest=24595]],image=[[assets/images/quests/placeholder.png]],desc=[[I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to my people that Quel'Delar has been recovered. As promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. Once the blade is restored, return with it to Caladis Brightspear at Quel'Delar's Rest.]],logDesc=[[Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.]]}
DB[24596]={id=24596,zoneId=4075,name=[[The Purification of Quel'Delar]],level=80,minLevel=80,giver=[[Halduron Brightwing]],giverType=[[NPC]],giverId=37527,ender=[[Myralion Sunblaze]],enderType=[[NPC]],enderId=36642,prevId=24563,rewardNextId=24798,wowhead=[[https://www.wowhead.com/wotlk/quest=24596]],image=[[assets/images/quests/placeholder.png]],desc=[[The Sunwell and the end of Quel'Delar's exile await, $N. You will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming. Instead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete the its restoration, then speak with Myralion Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.]],logDesc=[[Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.]]}
