DB[24629]={id=24629,name=[[A Perfect Puff of Perfume]],name_loc=[[El punto perfecto de perfume]],level=-1,minLevel=1,giver=[[Public Relations Agent]],giver_loc=[[Agente de Relaciones Públicas]],giverType=[[NPC]],giverId=37675,ender=[[Public Relations Agent]],ender_loc=[[Agente de Relaciones Públicas]],enderType=[[NPC]],enderId=37675,poiX=-8869,poiY=639,wowhead=[[https://www.wowhead.com/wotlk/quest=24629]],image=[[assets/images/quests/placeholder.png]],desc=[[You look like a real go-getter, $c. How about we work out a little win-win scenario? Crown's looking to offer samples of our latest holiday-themed products to as many potential customers as possible. Help us share the love, and we'll give you discounts on some great Crown merchandise! Your time, our money, friend. What do you say?]],logDesc=[[Spray 10 people with the Crown Perfume Sprayer.]],rewards={{id=49927,qty=5}}}
DB[24635]={id=24635,name=[[A Cloudlet of Classy Cologne]],name_loc=[[Cúmulo de colonia clásica]],level=-1,minLevel=1,giver=[[Public Relations Agent]],giver_loc=[[Agente de Relaciones Públicas]],giverType=[[NPC]],giverId=37675,ender=[[Public Relations Agent]],ender_loc=[[Agente de Relaciones Públicas]],enderType=[[NPC]],enderId=37675,poiX=-8869,poiY=639,wowhead=[[https://www.wowhead.com/wotlk/quest=24635]],image=[[assets/images/quests/placeholder.png]],desc=[[You seem the enterprising sort, $c. How about we make a little deal? Crown wants to offer samples of our latest holiday-themed products to as many potential customers as we can. Help us share the love while earning some fantastic Crown merchandise! Your time, our money, friend. What do you think?]],logDesc=[[Spray 10 people with the Crown Cologne Sprayer.]],rewards={{id=49927,qty=5}}}
DB[24636]={id=24636,name=[[Bonbon Blitz]],name_loc=[[Bombardeo de bombones]],level=-1,minLevel=1,giver=[[Public Relations Agent]],giver_loc=[[Agente de Relaciones Públicas]],giverType=[[NPC]],giverId=37675,ender=[[Public Relations Agent]],ender_loc=[[Agente de Relaciones Públicas]],enderType=[[NPC]],enderId=37675,poiX=-8869,poiY=639,wowhead=[[https://www.wowhead.com/wotlk/quest=24636]],image=[[assets/images/quests/placeholder.png]],desc=[[I can see you've got an eye for opportunity, $c. What do you say we make a little coin together? Crown needs to push samples of our latest holiday-themed products to every potential customer in the city. Help us share the love, and we'll share some of that amazing Crown merchandise with you! Your time, our money, friend. We got a deal?]],logDesc=[[Toss 10 people samples from the Crown Chocolate Sampler.]],rewards={{id=49927,qty=5}}}
DB[24638]={id=24638,name=[[Crushing the Crown]],name_loc=[[Aplasta La Corona]],level=-1,minLevel=5,giver=[[Detective Snap Snagglebolt]],giver_loc=[[Detective Snap Tuerceganzúas]],giverType=[[NPC]],giverId=37172,ender=[[Detective Snap Snagglebolt]],ender_loc=[[Detective Snap Tuerceganzúas]],enderType=[[NPC]],enderId=37172,prevId=24576,poiX=1248,poiY=-4153,wowhead=[[https://www.wowhead.com/wotlk/quest=24638]],image=[[assets/images/quests/placeholder.png]],desc=[[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough. Here's an entry I want you to check out: it's right outside Orgrimmar's gates, to the west! That can't be good. Get out there and rough 'em up. Oh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]],logDesc=[[Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon just west of Orgrimmar's gates in Durotar, then return to Detective Snap Snagglebolt in Orgrimmar.]],rewards={{id=49927,qty=5}}}
DB[24645]={id=24645,name=[[Crushing the Crown]],name_loc=[[Aplasta La Corona]],level=-1,minLevel=14,giver=[[Detective Snap Snagglebolt]],giver_loc=[[Detective Snap Tuerceganzúas]],giverType=[[NPC]],giverId=37172,ender=[[Detective Snap Snagglebolt]],ender_loc=[[Detective Snap Tuerceganzúas]],enderType=[[NPC]],enderId=37172,prevId=24576,poiX=-109,poiY=1123,wowhead=[[https://www.wowhead.com/wotlk/quest=24645]],image=[[assets/images/quests/placeholder.png]],desc=[[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough. Here's an entry I want you to check out: it's just outside Ambermill in Silverpine Forest. That can't be good. Get out there and rough 'em up. Oh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]],logDesc=[[Kill 5 Crown Thugs and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Ambermill in Silverpine Forest, then return to Detective Snap Snagglebolt in Orgrimmar.]],rewards={{id=49927,qty=5}}}
DB[24647]={id=24647,name=[[Crushing the Crown]],name_loc=[[Aplasta La Corona]],level=-1,minLevel=23,giver=[[Detective Snap Snagglebolt]],giver_loc=[[Detective Snap Tuerceganzúas]],giverType=[[NPC]],giverId=37172,ender=[[Detective Snap Snagglebolt]],ender_loc=[[Detective Snap Tuerceganzúas]],enderType=[[NPC]],enderId=37172,prevId=24576,poiX=-422,poiY=123,wowhead=[[https://www.wowhead.com/wotlk/quest=24647]],image=[[assets/images/quests/placeholder.png]],desc=[[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough. Here's an entry I want you to check out: it's just outside the village of Hillsbrad in -- you guessed it -- Hillsbrad Foothills. That can't be good. Get out there and rough 'em up. Oh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]],logDesc=[[Kill 5 Crown Dusters and use Snagglebolt's Khorium Bomb to destroy one chemical wagon just outside of Hillsbrad Village in Hillsbrad Foothills, then return to Detective Snap Snagglebolt in Orgrimmar.]],rewards={{id=49927,qty=5}}}
DB[24648]={id=24648,name=[[Crushing the Crown]],name_loc=[[Aplasta La Corona]],level=-1,minLevel=32,giver=[[Detective Snap Snagglebolt]],giver_loc=[[Detective Snap Tuerceganzúas]],giverType=[[NPC]],giverId=37172,ender=[[Detective Snap Snagglebolt]],ender_loc=[[Detective Snap Tuerceganzúas]],enderType=[[NPC]],enderId=37172,prevId=24576,poiX=-3409,poiY=-4214,wowhead=[[https://www.wowhead.com/wotlk/quest=24648]],image=[[assets/images/quests/placeholder.png]],desc=[[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough. Here's an entry I want you to check out: it's near Sentry Point, just outside Theramore in Dustwallow. Don't give me that look, okay? This is a problem for us, too. Get out there and rough 'em up. Oh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]],logDesc=[[Kill 5 Crown Hoodlums and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Theramore in Dustwallow Marsh, then return to Detective Snap Snagglebolt in Orgrimmar.]],rewards={{id=49927,qty=5}}}
DB[24649]={id=24649,name=[[Crushing the Crown]],name_loc=[[Aplasta La Corona]],level=-1,minLevel=41,giver=[[Detective Snap Snagglebolt]],giver_loc=[[Detective Snap Tuerceganzúas]],giverType=[[NPC]],giverId=37172,ender=[[Detective Snap Snagglebolt]],ender_loc=[[Detective Snap Tuerceganzúas]],enderType=[[NPC]],enderId=37172,prevId=24576,poiX=60,poiY=-2514,wowhead=[[https://www.wowhead.com/wotlk/quest=24649]],image=[[assets/images/quests/placeholder.png]],desc=[[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough. Here's an entry I want you to check out: it's to the east of Aerie Peak in the Hinterlands. Don't give me that look, okay? This is a problem for the Horde, too. Get out there and rough 'em up. Oh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]],logDesc=[[Kill 5 Crown Agents and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Aerie Peak in the Hinterlands, then return to Detective Snap Snagglebolt in Orgrimmar.]],rewards={{id=49927,qty=5}}}
DB[24650]={id=24650,name=[[Crushing the Crown]],name_loc=[[Aplasta La Corona]],level=-1,minLevel=51,giver=[[Detective Snap Snagglebolt]],giver_loc=[[Detective Snap Tuerceganzúas]],giverType=[[NPC]],giverId=37172,ender=[[Detective Snap Snagglebolt]],ender_loc=[[Detective Snap Tuerceganzúas]],enderType=[[NPC]],enderId=37172,prevId=24576,poiX=6756,poiY=-4937,wowhead=[[https://www.wowhead.com/wotlk/quest=24650]],image=[[assets/images/quests/placeholder.png]],desc=[[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough. Here's an entry I want you to check out: it's in Winterspring, just east of Everlook. Oh, now this is personal. Get out there and rough 'em up. Oh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]],logDesc=[[Kill 5 Crown Sprinklers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Everlook in Winterspring, then return to Detective Snap Snagglebolt in Orgrimmar.]],rewards={{id=49927,qty=5}}}
DB[24651]={id=24651,name=[[Crushing the Crown]],level=-1,minLevel=61,giver=[[Detective Snap Snagglebolt]],giverType=[[NPC]],giverId=37172,ender=[[Detective Snap Snagglebolt]],enderType=[[NPC]],enderId=37172,prevId=24576,wowhead=[[https://www.wowhead.com/wotlk/quest=24651]],image=[[assets/images/quests/placeholder.png]],desc=[[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough. Here's an entry I want you to check out: it looks like it's just east of Shattrath, in Terokkar Forest. Get out there and rough 'em up. Oh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]],logDesc=[[Kill 5 Crown Underlings and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Shattrath City in Terokkar Forest, then return to Detective Snap Snagglebolt in Orgrimmar.]],rewards={{id=49927,qty=5}}}
DB[24652]={id=24652,name=[[Crushing the Crown]],level=-1,minLevel=71,giver=[[Detective Snap Snagglebolt]],giverType=[[NPC]],giverId=37172,ender=[[Detective Snap Snagglebolt]],enderType=[[NPC]],enderId=37172,prevId=24576,wowhead=[[https://www.wowhead.com/wotlk/quest=24652]],image=[[assets/images/quests/placeholder.png]],desc=[[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough. Here's an entry I want you to check out: it looks like it's in the Forlorn Woods of Crystalsong, northwest of the Mirror of Twilight. Get out there and rough 'em up. Oh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]],logDesc=[[Kill 5 Crown Sprayers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon in the Forlorn Woods of Crystalsong Forest, then return to Detective Snap Snagglebolt in Orgrimmar.]],rewards={{id=49927,qty=5}}}
DB[24655]={id=24655,name=[[Something Stinks]],name_loc=[[Algo apesta]],level=-1,minLevel=1,giver=[[Inspector Snip Snagglebolt]],giver_loc=[[Inspector Snip Tuerceganzúas]],giverType=[[NPC]],giverId=38066,ender=[[Inspector Snip Snagglebolt]],ender_loc=[[Inspector Snip Tuerceganzúas]],enderType=[[NPC]],enderId=38066,prevId=24804,rewardNextId=24656,poiX=-8868,poiY=653,wowhead=[[https://www.wowhead.com/wotlk/quest=24655]],image=[[assets/images/quests/placeholder.png]],desc=[[Get a load of these guys, would ya? Steamwheedle's been handling the business of holidays for years, and all of a sudden, these guys bust into the market. They're not Steamwheedle; the cartel hired me to get to the bottom of this. Something stinks here and it ain't just perfume. Take this device I brought and go analyze the perfume clouds around the guards. I want to know what they're putting in that stuff. Things ain't natural.]],logDesc=[[Use Snagglebolt's Air Analyzer to test the air around 6 heavily perfumed guards, then return to Inspector Snip Snagglebolt in Stormwind.]]}
DB[24656]={id=24656,name=[[Pilfering Perfume]],name_loc=[[Afanar el aroma]],level=-1,minLevel=1,giver=[[Inspector Snip Snagglebolt]],giver_loc=[[Inspector Snip Tuerceganzúas]],giverType=[[NPC]],giverId=38066,ender=[[Inspector Snip Snagglebolt]],ender_loc=[[Inspector Snip Tuerceganzúas]],enderType=[[NPC]],enderId=38066,prevId=24655,rewardNextId=24848,poiX=-8868,poiY=653,wowhead=[[https://www.wowhead.com/wotlk/quest=24656]],image=[[assets/images/quests/placeholder.png]],desc=[[I knew they were up to no good! There's some sort of mind-affecting chemical in here, but I can't get a handle on it with such a small sample. I need the real stuff. Don't just go over there and buy it! I don't want you giving these scumbags one copper. Nah, you gotta get it from the source, discreet-like. I'll disguise you as a package runner. I saw a stockpile guarded by their goons outside the gates. Go run by, and DON'T stop, or they'll make you! They'll toss you a crate. Bring it back here.]],logDesc=[[While disguised as a package-runner, go to the Crown Chemical Company's stockpile outside the gates of Stormwind, then return the package they toss you to Inspector Snip Snagglebolt in Stormwind.]]}
DB[24657]={id=24657,name=[[A Friendly Chat...]],name_loc=[[Una charla amistosa...]],level=-1,minLevel=1,giver=[[Marion Sutton]],giverType=[[NPC]],giverId=38325,ender=[[Inspector Snip Snagglebolt]],ender_loc=[[Inspector Snip Tuerceganzúas]],enderType=[[NPC]],enderId=38066,prevId=24849,poiX=-8868,poiY=653,wowhead=[[https://www.wowhead.com/wotlk/quest=24657]],image=[[assets/images/quests/placeholder.png]],desc=[[<Marion listens with horror as you tell her why you're trying to track down Snivel.> You mean, he might've used some kind of chemical on me? Ew! I can't believe I fell for that fraud! If he's finished all of his errands, he's on his way down to the docks to catch a ship to the South Seas! Whatever you do, $N, you can't let him get away with this. Hurry down to Stormwind Harbor before you miss him!]],logDesc=[[Go to Stormwind Harbor and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.]]}
DB[24658]={id=24658,name=[[Crushing the Crown]],name_loc=[[Aplasta La Corona]],level=-1,minLevel=5,giver=[[Inspector Snip Snagglebolt]],giver_loc=[[Inspector Snip Tuerceganzúas]],giverType=[[NPC]],giverId=38066,ender=[[Inspector Snip Snagglebolt]],ender_loc=[[Inspector Snip Tuerceganzúas]],enderType=[[NPC]],enderId=38066,prevId=24657,poiX=-9412,poiY=491,wowhead=[[https://www.wowhead.com/wotlk/quest=24658]],image=[[assets/images/quests/placeholder.png]],desc=[[This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough. Here's an entry I want you to check out: it's northeast of Westbrook Garrison right outside in Elwynn! That can't be good. Get out there and rough 'em up. Oh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.]],logDesc=[[Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon northeast of Westbrook Garrison in Elwynn Forest, then return to Inspector Snip Snagglebolt in Stormwind.]],rewards={{id=49927,qty=5}}}
