DB[24792]={id=24792,name=[[Man on the Inside]],level=-1,minLevel=78,giver=[[Inspector Snip Snagglebolt]],giverType=[[NPC]],giverId=38066,ender=[[Investigator Fezzen Brasstacks]],enderType=[[NPC]],enderId=38208,prevId=24657,rewardNextId=14488,wowhead=[[https://www.wowhead.com/wotlk/quest=24792]],image=[[assets/images/quests/placeholder.png]],desc=[[You look like you're fit enough to take on the mastermind behind this operation. The ledger says he's holed up in Shadowfang Keep, so that's where I'm sending you. We have a man there already but he's not fit to take down an operation by himself. Head on in; the investigator will meet you there. And bring friends.]],logDesc=[[Report to Investigator Fezzen Brasstacks in Shadowfang Keep.]]}
DB[24793]={id=24793,name=[[Man on the Inside]],level=-1,minLevel=78,giver=[[Detective Snap Snagglebolt]],giverType=[[NPC]],giverId=37172,ender=[[Investigator Fezzen Brasstacks]],enderType=[[NPC]],enderId=38208,prevId=24576,rewardNextId=14488,wowhead=[[https://www.wowhead.com/wotlk/quest=24793]],image=[[assets/images/quests/placeholder.png]],desc=[[You look like you're fit enough to take on the mastermind behind this operation. The ledger says he's holed up in Shadowfang Keep, so that's where I'm sending you. We have a man there already but he's not fit to take down an operation by himself. Head on in; the investigator will meet you there. And bring friends.]],logDesc=[[Report to Investigator Fezzen Brasstacks in Shadowfang Keep.]]}
DB[24795]={id=24795,zoneId=210,name=[[A Victory For The Silver Covenant]],level=80,minLevel=80,giver=[[Caladis Brightspear]],giverType=[[NPC]],giverId=36624,ender=[[Justicar Mariel Trueheart]],enderType=[[NPC]],enderId=33817,prevId=24595,wowhead=[[https://www.wowhead.com/wotlk/quest=24795]],image=[[assets/images/quests/placeholder.png]],desc=[[In spite of Queen Lana'thel's boasting, you have restored Quel'Delar, $N. Long have we dreamt of reclaiming Quel'Delar. The Silver Covenant, and indeed all quel'dorei owe you a debt of gratitude. As a $c, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? Perhaps the Argent Crusade can find one. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Silver Covenant.]],logDesc=[[Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.]],choiceRewards={{id=50050,qty=1},{id=50051,qty=1},{id=50052,qty=1}}}
DB[24796]={id=24796,zoneId=210,name=[[A Victory For The Silver Covenant]],level=80,minLevel=80,giver=[[Caladis Brightspear]],giverType=[[NPC]],giverId=36624,ender=[[Vereesa Windrunner]],enderType=[[NPC]],enderId=30115,prevId=24553,wowhead=[[https://www.wowhead.com/wotlk/quest=24796]],image=[[assets/images/quests/placeholder.png]],desc=[[In spite of Queen Lana'thel's boasting, you have restored Quel'Delar, $N. Long have we dreamt of reclaiming Quel'Delar. The Silver Covenant, and indeed all quel'dorei owe you a debt of gratitude. Vereesa Windrunner, the leader of the Silver Covenant, asked to see you after you returned from the Sunwell. Take Quel'Delar with you and go to Dalaran's Violet Citadel where she waits, $N.]],logDesc=[[Bring the Restored Quel'Delar to Vereesa Windrunner at the Violet Citadel in Dalaran.]],choiceRewards={{id=50048,qty=1},{id=50049,qty=1},{id=50046,qty=1},{id=50047,qty=1}}}
DB[24797]={id=24797,zoneId=4075,name=[[REUSE]],level=80,minLevel=77,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=24797]],image=[[assets/images/quests/placeholder.png]]}
DB[24798]={id=24798,zoneId=210,name=[[A Victory For The Sunreavers]],level=80,minLevel=80,giver=[[Myralion Sunblaze]],giverType=[[NPC]],giverId=36642,ender=[[Justicar Mariel Trueheart]],enderType=[[NPC]],enderId=33817,prevId=24596,wowhead=[[https://www.wowhead.com/wotlk/quest=24798]],image=[[assets/images/quests/placeholder.png]],desc=[[At last, Quel'Delar is restored for the glory of the Sunreavers and the sin'dorei! All of Silvermoon will celebrate you as a hero, $N. As a $c, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? No worthy sin'dorei has come forward. Let us seek the Argent Crusade's counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.]],logDesc=[[Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.]],choiceRewards={{id=50050,qty=1},{id=50051,qty=1},{id=50052,qty=1}}}
DB[24799]={id=24799,zoneId=210,name=[[A Victory For The Sunreavers]],level=80,minLevel=80,giver=[[Myralion Sunblaze]],giverType=[[NPC]],giverId=36642,ender=[[Justicar Mariel Trueheart]],enderType=[[NPC]],enderId=33817,prevId=24598,wowhead=[[https://www.wowhead.com/wotlk/quest=24799]],image=[[assets/images/quests/placeholder.png]],desc=[[At last, Quel'Delar is restored for the glory of the Sunreavers! All the Horde will celebrate you as a hero, $N. As a $c, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? I will not conceal my disappointment; I had hoped it would be a worthy sin'dorei. Let us seek the Argent Crusade's counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.]],logDesc=[[Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.]],choiceRewards={{id=50050,qty=1},{id=50051,qty=1},{id=50052,qty=1}}}
DB[24800]={id=24800,zoneId=210,name=[[A Victory For The Sunreavers]],level=80,minLevel=80,giver=[[Myralion Sunblaze]],giverType=[[NPC]],giverId=36642,ender=[[Archmage Aethas Sunreaver]],enderType=[[NPC]],enderId=30116,prevId=24594,wowhead=[[https://www.wowhead.com/wotlk/quest=24800]],image=[[assets/images/quests/placeholder.png]],desc=[[At last, Quel'Delar is restored for the glory of the Sunreavers and the sin'dorei! All of Silvermoon will proclaim you a hero, as will all of the Horde. Archmage Aethas Sunreaver, the leader of the Sunreavers, asked to see you after you returned from the Sunwell. Travel to the Violet Citadel in Dalaran as soon as you can, $N and bring Quel'Delar with you. The archmage wishes to congratulate you personally!]],logDesc=[[Bring the Restored Quel'Delar to Archmage Aethas Sunreaver at the Violet Citadel in Dalaran.]],choiceRewards={{id=50048,qty=1},{id=50049,qty=1},{id=50046,qty=1},{id=50047,qty=1}}}
DB[24801]={id=24801,zoneId=210,name=[[A Victory For The Sunreavers]],level=80,minLevel=80,giver=[[Myralion Sunblaze]],giverType=[[NPC]],giverId=36642,ender=[[Archmage Aethas Sunreaver]],enderType=[[NPC]],enderId=30116,prevId=24564,wowhead=[[https://www.wowhead.com/wotlk/quest=24801]],image=[[assets/images/quests/placeholder.png]],desc=[[At last, Quel'Delar is restored for the glory of the Sunreavers and the Horde! This is a blessing for our efforts against the Lich King. Archmage Aethas Sunreaver, the leader of the Sunreavers, asked to see you after you returned from the Sunwell. Travel to the Violet Citadel in Dalaran as soon as you can, $N and bring Quel'Delar with you. The archmage wishes to congratulate you personally!]],logDesc=[[Bring the Restored Quel'Delar to Archmage Aethas Sunreaver at the Violet Citadel in Dalaran.]],choiceRewards={{id=50048,qty=1},{id=50049,qty=1},{id=50046,qty=1},{id=50047,qty=1}}}
DB[24802]={id=24802,zoneId=4820,name=[[Wrath of the Lich King]],level=80,minLevel=78,giver=[[Dark Ranger Loralen]],giverType=[[NPC]],giverId=37779,ender=[[Lady Sylvanas Windrunner]],enderType=[[NPC]],enderId=37554,prevId=24713,wowhead=[[https://www.wowhead.com/wotlk/quest=24802]],image=[[assets/images/quests/placeholder.png]],desc=[[Uther knew a great deal about how Arthas might be defeated. It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that? Many questions remain, but the answers that you've uncovered may be critical to ensuring Arthas' defeat. You need to find Sylvanas and escape the Lich King while there's still time.]],logDesc=[[Find Lady Sylvanas Windrunner and escape the Halls of Reflection]],rewards={{id=49426,qty=2}}}
DB[24803]={id=24803,name=[[Kalu'ak Fishing Derby]],name_loc=[[Competición de pesca Kalu'ak]],level=-1,minLevel=1,giver=[[Elder Clearwater]],giver_loc=[[Ancestro Aguaclara]],giverType=[[NPC]],giverId=38294,ender=[[Elder Clearwater]],ender_loc=[[Ancestro Aguaclara]],enderType=[[NPC]],enderId=38294,poiX=5699,poiY=617,wowhead=[[https://www.wowhead.com/wotlk/quest=24803]],image=[[assets/images/quests/placeholder.png]],choiceRewards={{id=50255,qty=1},{id=50287,qty=1}}}
DB[24804]={id=24804,name=[[Uncommon Scents]],name_loc=[[Olores extraños]],level=-1,minLevel=1,giver=[[Junior Inspector]],giver_loc=[[Inspector subalterno]],giverType=[[NPC]],giverId=38293,ender=[[Inspector Snip Snagglebolt]],ender_loc=[[Inspector Snip Tuerceganzúas]],enderType=[[NPC]],enderId=38066,rewardNextId=24655,poiX=-8868,poiY=653,wowhead=[[https://www.wowhead.com/wotlk/quest=24804]],image=[[assets/images/quests/placeholder.png]],desc=[[Something's not right about this Crown Chemical Company. Steamwheedle's got eyes on 'em, and we could use a few more. Head to Stormwind if you're interested in helping us out. Inspector Snip Snagglebolt is heading up the investigation there, and he can use all the help he can get.]],logDesc=[[Report to Inspector Snip Snagglebolt in Stormwind.]]}
