DB[24914]={id=24914,zoneId=4812,name=[[Personal Property]],level=80,minLevel=80,giverType=[[NPC]],ender=[[Highlord Darion Mograine]],enderType=[[NPC]],enderId=37120,wowhead=[[https://www.wowhead.com/wotlk/quest=24914]],image=[[assets/images/quests/placeholder.png]],desc=[[You can detect no hinges or openings on this box. Were it not for the shifting of items inside,it could easily be mistaken for solid metal. If anyone could know the method of its opening,it would be Highlord Mograine.]],logDesc=[[Bring the Sealed Chest to Highlord Darion Mograine in Icecrown Citadel.]],rewards={{id=51316,qty=1}}}
