DB[25055]={id=25055,name=[[Elemental Research]],level=80,minLevel=80,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=25055]],image=[[assets/images/quests/placeholder.png]],desc=[[[ph] I'll give you a sack of shaman stuff.  Use the elemental sapta to enter the spirit and use the totem on the Agitated Earth Elementals.]],logDesc=[[[ph] log description]]}
