DB[25180]={id=25180,zoneId=1519,name=[[Tablets of the Earth]],name_loc=[[Tablillas de la tierra]],level=-1,minLevel=5,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=25180]],image=[[assets/images/quests/placeholder.png]],desc=[[Some time ago,my brother Brann sent an urgent message from Ulduar. He said he'd found an ancient titan cache with mysterious and important relics. King Wrynn dispatched one of his fastest ships to Northrend to transport the courier and the boat should've arrived by now. I'm worried,$N. I haven't heard anything about the courier's arrival. Would you be willing to travel to Stormwind Harbor and see if he's arrived?]],logDesc=[[Bring the Tablets of Earth to King Magni Bronzebeard in Ironforge.]]}
DB[25181]={id=25181,zoneId=1519,name=[[Tablets of Fire]],name_loc=[[Tablillas de fuego]],level=-1,minLevel=5,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=25181]],image=[[assets/images/quests/placeholder.png]],desc=[[I'm expecting the arrival of a courier traveling from Northrend. He's carrying a collection of ancient titan treasures,ones I'm hoping will shed light on my troubling visions. The shaman should've arrived on one of the recent zeppelin flights and I'm starting to get worried. He was to meet me by the zeppelin tower southwest of Orgrimmar's gates,but I don't want to miss my audience with the warchief. Would you be willing to look for the courier and see what's delaying him?]],logDesc=[[Bring the Tablets of Fire to Seer Bahura in Orgrimmar.]]}
DB[25199]={id=25199,zoneId=1,name=[[Basic Orders]],name_loc=[[Órdenes básicas]],level=-1,minLevel=1,giver=[[Captain Tread Sparknozzle]],giver_loc=[[Capitán Tread Chispaboquilla]],giverType=[[NPC]],giverId=39675,ender=[[Captain Tread Sparknozzle]],ender_loc=[[Capitán Tread Chispaboquilla]],enderType=[[NPC]],enderId=39675,prevId=25229,rewardNextId=25285,wowhead=[[https://www.wowhead.com/wotlk/quest=25199]],image=[[assets/images/quests/placeholder.png]],desc=[[Hey! You look like you could give us a hand! If you're willing to help our cause,we have to get you through training.  Gnome training is brutal and rigorous,so I hope you're ready. Head over to Drill Sergeant Steamcrank and he'll walk you through what you need to know.  Make sure you follow his orders when he gives them,or else you'll never make it I'm warning you though,it's tough over there.  Come back to see me,if you make it.]],logDesc=[[Follow Drill Sergeant Steamcrank's cues and then report back to Captain Tread Sparknozzle.]]}
DB[25212]={id=25212,zoneId=1,name=[[Vent Horizon]],name_loc=[[Horizonte de conductos]],level=-1,minLevel=1,giver=[[Pilot Muzzlesprock]],giver_loc=[[Piloto Engranahocico]],giverType=[[NPC]],giverId=39386,ender=[[Pilot Muzzlesprock]],ender_loc=[[Piloto Engranahocico]],enderType=[[NPC]],enderId=39386,prevId=25199,wowhead=[[https://www.wowhead.com/wotlk/quest=25212]],image=[[assets/images/quests/placeholder.png]],desc=[[We thought that we could wait for the radiation to subside around Gnomeregan,but it doesn't appear to be getting better. If we want to take back our city,we need to make sure it's safe for our troops to enter. Take these Radiageigatrons,hop in 'Thunderflash' here, and toss them at the ventilation shafts outside of Gnomeregan. They'll report the radiation levels directly to me.]],logDesc=[[Use Pilot Muzzlesprock's flying machine to toss Radiageigatrons at the vents surrounding Gnomeregan.]]}
DB[25228]={id=25228,zoneId=1637,name=[[Prophecies Of Doom]],name_loc=[[Profecías de fatalidad]],level=-1,minLevel=5,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=25254,wowhead=[[https://www.wowhead.com/wotlk/quest=25228]],image=[[assets/images/quests/placeholder.png]],desc=[[Harbingers of doom are nothing new on the streets of Orgrimmar,but I'm worried about this latest batch. These people are organized and they've attracted a lot of attention in the Drag,where they seem to congregate. I've thought about rounding them up or otherwise disrupting their activities,but that will just drive them underground. We need to find out more about them. Would you go to the Drag,listen to what these doomsayers are spreading,and gather any literature you can find about their ideas?]],logDesc=[[Listen to a speech given by a Doomsayer in the Drag and obtain copies of the pamphlets "Elemental Fire for the Soul","What Does 'The End of All Things' Mean for Me?",and "Finding Security and Comfort in a Doomed World".]]}
DB[25229]={id=25229,zoneId=1,name=[[A Few Good Gnomes]],name_loc=[[Algunos gnomos buenos]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],rewardNextId=25199,wowhead=[[https://www.wowhead.com/wotlk/quest=25229]],image=[[assets/images/quests/placeholder.png]],desc=[[Our engineers have been working on getting our battle machines ready for our assault on Gnomeregan,but we're out of pilots! We've developed a device called the Motivate-a-Tron,which prevents distraction from other sources and gives the gnome the courage to enlist. After motivating a few Gnome Citizens,lead them out to Captain Tread Sparknozzle out at Steelgrill's Depot,just south of Ironforge. Oh,and be careful. The device is still a little experimental.]],logDesc=[[Recruit Gnome Citizens from Tinker Town using the Motivate-a-Tron and lead them to Captain Tread Sparknozzle at Steelgrill's Depot.]]}
DB[25238]={id=25238,zoneId=210,name=[[Strength Ring Flag]],name_loc=[[Anillo de fuerza]],level=-1,minLevel=1,giverType=[[NPC]],enderType=[[NPC]],wowhead=[[https://www.wowhead.com/wotlk/quest=25238]],image=[[assets/images/quests/placeholder.png]]}
